window.__DEPARTMENTS__ = [{"id":"cardio","name":"心血管内科","short":"心内","abbr":"CV","group":"内科","order":1},{"id":"resp","name":"呼吸与危重症医学科","short":"呼吸","abbr":"RESP","group":"内科","order":2},{"id":"gi","name":"消化内科","short":"消化","abbr":"GI","group":"内科","order":3},{"id":"endo","name":"内分泌代谢科","short":"内分泌","abbr":"ENDO","group":"内科","order":4},{"id":"renal","name":"肾脏内科","short":"肾内","abbr":"REN","group":"内科","order":5},{"id":"neuro","name":"神经内科","short":"神内","abbr":"NEU","group":"内科","order":6},{"id":"heme","name":"血液科","short":"血液","abbr":"HEM","group":"内科","order":7},{"id":"rheum","name":"风湿免疫科","short":"风湿","abbr":"RHE","group":"内科","order":8},{"id":"onco","name":"肿瘤科","short":"肿瘤","abbr":"ONC","group":"内科","order":9},{"id":"id","name":"感染科","short":"感染","abbr":"ID","group":"内科","order":10},{"id":"geriatric","name":"老年医学科","short":"老年","abbr":"GER","group":"内科","order":11},{"id":"emerg","name":"急诊与重症","short":"急诊ICU","abbr":"ICU","group":"平台","order":12},{"id":"anes","name":"麻醉与围术期","short":"麻醉","abbr":"ANES","group":"平台","order":13},{"id":"gen_surg","name":"普通外科","short":"普外","abbr":"GS","group":"外科","order":20},{"id":"ortho","name":"骨科","short":"骨科","abbr":"ORTHO","group":"外科","order":21},{"id":"uro","name":"泌尿外科","short":"泌尿","abbr":"URO","group":"外科","order":22},{"id":"nsurg","name":"神经外科","short":"神外","abbr":"NS","group":"外科","order":23},{"id":"cts","name":"心胸外科","short":"胸外","abbr":"CTS","group":"外科","order":24},{"id":"vascular","name":"血管外科","short":"血管","abbr":"VAS","group":"外科","order":25},{"id":"obgyn","name":"妇产科","short":"妇产","abbr":"OB","group":"外科","order":26},{"id":"peds","name":"儿科","short":"儿科","abbr":"PED","group":"外科","order":27},{"id":"eye","name":"眼科","short":"眼科","abbr":"EYE","group":"外科","order":28},{"id":"ent","name":"耳鼻咽喉科","short":"耳鼻喉","abbr":"ENT","group":"外科","order":29},{"id":"derm","name":"皮肤科","short":"皮肤","abbr":"DERM","group":"外科","order":30},{"id":"psych","name":"精神心理科","short":"精神","abbr":"PSY","group":"外科","order":31}];window.__CALC__ = {"anes":{"items":[{"id":"anes_asa","name":"ASA 麻醉风险分级（体格状态）","aka":["ASA Physical Status Classification","ASA-PS"],"cat":"术前评估","rank":1,"desc":"按全身健康状态将择期手术患者分为 Ⅰ–Ⅵ 级，是术前评估与围术期风险沟通的通用分级。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ级","criteria":"健康、无系统性疾病；不吸烟，无或极少饮酒（含 BMI 正常的健康人、孕产妇）","level":"ok"},{"label":"Ⅱ级","criteria":"轻度系统性疾病、无功能受限：控制良好的高血压/糖尿病、吸烟、偶饮酒、肥胖（BMI 30–40）、轻度肺疾病、妊娠","level":"ok"},{"label":"Ⅲ级","criteria":"严重系统性疾病、有明显功能受限：控制不佳的糖尿病/高血压、COPD、终末期肾病规律透析、心梗病史 >3 个月、BMI ≥40、长期酗酒","level":"warn"},{"label":"Ⅳ级","criteria":"威胁生命的严重系统性疾病：近期（<3 个月）心梗/脑卒中/TIA、严重瓣膜病、心衰、脓毒症、DIC、急性肝衰、终末期肾病未透析","level":"high"},{"label":"Ⅴ级","criteria":"濒死：不手术难以存活者，如腹主动脉瘤破裂、严重创伤、严重颅内出血致颅内高压、肠缺血伴多器官功能障碍","level":"crit"},{"label":"Ⅵ级","criteria":"脑死亡，器官捐献者","level":"crit"}],"note":"2020 版 ASA-PS 明确附加「E」表示急诊手术（如 ⅢE）。分级反映术前状态而非手术风险，需结合手术类型与 RCRI 等指标；体重与 BMI 单独列明不直接决定分级的普遍误解已在 2020 年版澄清。","refs":["ASA Physical Status Classification System, 2020（ASA House of Delegates 2014 版，2020 最后修订）","中华医学会麻醉学分会：术前风险评估与患者准备专家共识（2017）"]},{"id":"anes_mallampati","name":"改良 Mallampati 气道分级","aka":["Modified Mallampati Classification","MMPT"],"cat":"气道评估","rank":2,"desc":"患者坐位、张口伸舌直视下按可见咽部结构分为 Ⅰ–Ⅳ 级，Ⅳ级提示困难面罩与困难喉镜风险显著增加。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ级","criteria":"可见软腭、咽柱、腭垂（悬雍垂）与咽后壁","level":"ok"},{"label":"Ⅱ级","criteria":"可见软腭、咽柱与腭垂，咽后壁被舌根遮挡","level":"ok"},{"label":"Ⅲ级","criteria":"可见软腭与舌根，腭垂及咽柱不可见","level":"warn"},{"label":"Ⅳ级","criteria":"仅见硬腭，软腭不可见","level":"high"}],"note":"需坐位、头中立、张口不发声伸舌。单用 Mallampati 预测困难插管敏感性低，应结合张口度（<3 cm）、甲颏距离（<6 cm）、颈活动度、下颌潴留与 BMI 综合评估。","refs":["Samsoon GLT, Young JRB. Anaesthesia 1987;42:487-490（改良分级原版）","ASA Difficult Airway Management Guidelines, 2022","中华医学会麻醉学分会：困难气道管理专家共识（2019）"]},{"id":"anes_lemon","name":"LEMON 困难气道评估","aka":["LEMON Score","Difficult Airway Assessment"],"cat":"气道评估","rank":3,"desc":"按 L 外观、E 3-3-2、M Mallampati、O 梗阻、N 颈活动度 5 项累加，≥3 分提示困难插管风险高，帮助制定气道预案。","inputs":[{"key":"look","label":"L：外观（Look externally）——面部外伤/畸形/张口受限/小下颌/胡须遮挡","type":"select","options":[{"value":0,"label":"正常观感"},{"value":1,"label":"有可疑特征"}],"required":true},{"key":"evaluate","label":"E：3-3-2（张口度 ≥3 指、下颌骨 ≥3 指、颏甲距离 ≥2 指）","type":"select","options":[{"value":0,"label":"三项均达标"},{"value":1,"label":"任一项不达标"}],"required":true},{"key":"mallampati","label":"M：Mallampati 分级","type":"select","options":[{"value":0,"label":"Ⅰ–Ⅱ 级"},{"value":1,"label":"Ⅲ–Ⅳ 级"}],"required":true},{"key":"obstruction","label":"O：气道梗阻（声音嘶哑、吞咽困难、喘鸣、颈部肿物/肥胖颈短）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"neck","label":"N：颈活动度（屈伸受限、颈椎病、颈托固定）","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"受限"}],"required":true}],"formula":"LEMON = L（0/1）+ E（0/1）+ M（0/1）+ O（0/1）+ N（0/1），总分 0–5","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"≥3 分：高度困难气道风险，急诊科优先考虑清醒纤维支气管镜/可视喉镜、外科气道预案，术前请麻醉科会诊"},{"when":"v == 2","level":"warn","text":"2 分：中风险，可由经验丰富的麻醉医师用可视喉镜进行插管，备环甲膜穿刺套件与双人吸引"},{"when":"v <= 1","level":"ok","text":"0–1 分：低风险，按常规气道管理，但仍需口咽/鼻咽通气道与应急预案"}],"note":"LEMON 是快速床旁筛查工具，敏感性高但特异度一般，不能替代困难气道预案（DAS/ASA 的 A–B–C–D 流程与「不能插管不能氧合」外科气道预案）。","refs":["Reed MJ, et al. Can J Anaesth 2005;52:237-240（LEMON 应用）","ASA Difficult Airway Management Guidelines, 2022","中华医学会麻醉学分会：困难气道管理专家共识（2019）"]},{"id":"anes_rcri","name":"RCRI 修订心脏风险指数","aka":["Revised Cardiac Risk Index","Lee Index","RCRI"],"cat":"术前评估","rank":4,"desc":"6 项独立危险因素（缺血性心脏病、心衰、脑血管病、胰岛素治疗糖尿病、术前肌酐 >177 μmol/L、高危手术）预测非心脏手术围术期主要心脏事件（MACE）。","inputs":[{"key":"ihd","label":"缺血性心脏病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"hf","label":"心力衰竭","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"cvd","label":"脑血管疾病（脑卒中/TIA）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"dm_insulin","label":"糖尿病需胰岛素治疗","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"cr_high","label":"术前血肌酐 >177 μmol/L（2 mg/dL）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"surgery","label":"高危手术类型","type":"select","options":[{"value":0,"label":"低危（门诊、浅表、内镜、白内障）"},{"value":1,"label":"中危（腹腔内、胸腔内、泌尿、矫形）"},{"value":2,"label":"高危（主动脉/外周血管、开放腹部、大创伤、肝移植等）"}],"required":true,"hint":"按 2014 ESC/AHA 指南三分类：高危 = 2 分，其余计 0"}],"formula":"RCRI = 6 项各 1 分（高危手术按指南归入 1 项），总分 0–6","compute":"formula_only","algorithm":"v = ihd + hf + cvd + dm_insulin + cr_high + (surgery == 2 ? 1 : 0)","interpret":[{"when":"v == 0","level":"ok","text":"0 分：MACE 风险约 0.4%，通常无需额外心脏检查，可择期手术（C 级以上手术分期评估心跳储备）"},{"when":"v == 1","level":"ok","text":"1 分：风险约 0.9%，无临床危险因素者可直接手术；活动能力差者评估心功能"},{"when":"v == 2","level":"warn","text":"2 分：风险约 7%（2007 版分层），需评估活动能力与功能状态（DASI/METs），高危手术考虑术前心脏超声或负荷试验"},{"when":"v >= 3","level":"high","text":"≥3 分：风险约 11%，需心脏科会诊、优化治疗（β 阻滞剂、他汀），避免非必要高风险择期手术"}],"note":"RCRI 对低-中危手术低估风险，对血管手术预测能力有限，需结合手术分级、功能容量与生物标志物（BNP、肌钙蛋白）。术前应进行 5 项危险因素心血管风险指数（VSG）与功能容量评估。","refs":["Lee TH, et al. Circulation 1999;100:1043-1049（RCRI 原版）","2014 ESC/ESA Non-cardiac Surgery Guidelines","中国非心脏手术围术期心血管评估与管理专家共识（2020）"]},{"id":"anes_apfel","name":"Apfel 术后恶心呕吐（PONV）风险评分","aka":["Apfel Score","PONV Risk Score"],"cat":"围术期并发症","rank":5,"desc":"4 项预测因素（女性、非吸烟、PONV 或晕动病史、术后阿片类使用）累加，指导预防性止吐与常规预防策略。","inputs":[{"key":"female","label":"女性","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"nonsmoker","label":"非吸烟","type":"select","options":[{"value":0,"label":"否（吸烟）"},{"value":1,"label":"是（不吸烟）"}],"required":true},{"key":"ponv_history","label":"既往 PONV 或晕动病史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"opioid","label":"术后使用阿片类镇痛药","type":"select","options":[{"value":0,"label":"否（以多模式镇痛为主）"},{"value":1,"label":"是"}],"required":true}],"formula":"简化 Apfel 评分 = 4 项各 1 分（0–4）；原 Apfel 模型：女性 3 分 + 非吸烟 1 分 + 既往 PONV 1 分 + 阿片 1 分（0–6）","compute":"formula_only","algorithm":"v = female + nonsmoker + ponv_history + opioid  // 女性按 3 分加权为原模型；简化版按 0/1 ×4","interpret":[{"when":"v == 0 && female == 0","level":"ok","text":"0 分：PONV 风险约 10%，一般无需预防性止吐，可考虑多模式镇痛"},{"when":"v <= 2","level":"warn","text":"1–2 分：风险约 20%–40%，推荐 1–2 种不同机制止吐药（5-HT3 拮抗剂 + 地塞米松），首选 TIVA 与丙泊酚"},{"when":"v >= 3 && v <= 5","level":"high","text":"3–5 分：风险 60%–80%，强烈推荐预防性联合止吐（≥2 种）+ 非药物措施（补液、避免氧化亚氮与吸入麻醉）"},{"when":"v >= 6","level":"crit","text":"6 分（有 PONV 史的高危患者）：风险 >80%，多模式止吐（≥3 种不同机制）+ TIVA + 术后管理，术前告知并备补救方案"}],"note":"使用本简化版（女性计 3 分）总分可至 6，与经典 Apfel 模型一致。预防宜选用不同机制药物（5-HT3 拮抗剂、地塞米松、NK1 拮抗剂、丁酰苯类），避免两次用同类药；术中吸氧与扩容亦有帮助。","refs":["Apfel CC, et al. Anesthesiology 1999;91:693-700（Apfel 评分原版）","第四版术后恶心呕吐管理共识指南（Anesth Analg 2020, Gan TJ 等）","中国术后恶心呕吐防治专家共识（2021）"]},{"id":"anes_albrete","name":"Aldrete 麻醉后恢复评分","aka":["Aldrete Score","Post-Anesthesia Recovery Score"],"cat":"恢复与镇静","rank":6,"desc":"按活动、呼吸、循环、意识、氧饱和度 5 项各 0–2 分（0–10）评估 PACU 苏醒情况，≥9 分且观察达标是出室标准。","inputs":[{"key":"activity","label":"活动（活动度）","type":"select","options":[{"value":2,"label":"能主动活动四肢/按指令活动"},{"value":1,"label":"两个肢体可自主活动"},{"value":0,"label":"不能活动"}],"required":true},{"key":"respiration","label":"呼吸","type":"select","options":[{"value":2,"label":"能深呼吸、自由咳嗽"},{"value":1,"label":"呼吸困难/浅表呼吸"},{"value":0,"label":"无自主呼吸（需机械通气）"}],"required":true},{"key":"circulation","label":"循环（血压、脉率与术前比较）","type":"select","options":[{"value":2,"label":"血压与脉率较术前波动 <20%"},{"value":1,"label":"波动 20%–49%"},{"value":0,"label":"波动 ≥50%"}],"required":true},{"key":"consciousness","label":"意识","type":"select","options":[{"value":2,"label":"完全清醒、定向力正常"},{"value":1,"label":"可唤醒但嗜睡"},{"value":0,"label":"对刺激无反应"}],"required":true},{"key":"spo2","label":"氧饱和度（吸室内空气时）","type":"select","options":[{"value":2,"label":"SpO2 >92%（空气）"},{"value":1,"label":"需吸氧维持 SpO2 >90%"},{"value":0,"label":"吸氧后 SpO2 仍 <90%"}],"required":true}],"formula":"Aldrete = 活动 0–2 + 呼吸 0–2 + 循环 0–2 + 意识 0–2 + SpO2 0–2，总分 0–10","compute":"sum","interpret":[{"when":"v >= 9","level":"ok","text":"9–10 分：达出 PACU 指征，仍需至少观察 30 分钟、无恶心呕吐、镇痛可控制、排尿无异常"},{"when":"v >= 7","level":"warn","text":"7–8 分：继续在 PACU 观察，每小时复评；排查残余肌松、呼吸抑制、低体温与疼痛"},{"when":"v <= 6","level":"high","text":"≤6 分：不宜出室，查肌松拮抗是否充分（TOF 比值 >0.9）、气道梗阻/呼吸抑制，必要时转入 ICU/麻醉复苏室"}],"note":"改良版（Aldrete 1995）用 SpO2 替换 O2 饱和度项。出室还需满足：疼痛评分低、无 PONV、体温正常（>36 °C）、无活动性出血；门诊手术需另一位成人陪同。","refs":["Aldrete JA. J Clin Monit 1995;11:41-46（Aldrete 改良版原版）","中国麻醉后恢复室（PACU）管理专家共识（2021）","ASAStandards for Postanesthesia Care, 2018"]},{"id":"anes_ramsay","name":"Ramsay 镇静评分","aka":["Ramsay Sedation Scale","RSS"],"cat":"恢复与镇静","rank":7,"desc":"以 6 级评定镇静深度（1 清醒 → 6 无反应），传统用于 ICU/内镜镇静，目标 2–3 级。","inputs":[],"compute":"formula_only","levels":[{"label":"1 级","criteria":"清醒：焦虑/烦躁或不安","level":"ok"},{"label":"2 级","criteria":"清醒且平静、服从指令、合作","level":"ok"},{"label":"3 级","criteria":"仅对指令有反应（嗜睡但可唤醒执行指令）","level":"warn"},{"label":"4 级","criteria":"对眉间轻叩或大声刺激反应灵敏（快速的睁眼或肢体运动）","level":"warn"},{"label":"5 级","criteria":"对上述刺激反应迟钝","level":"high"},{"label":"6 级","criteria":"无任何反应（深睡眠/昏迷）","level":"crit"}],"note":"Ramsay 无躁动分档（不受控的躁动需另用 RASS/CAM-ICU 评估），近年机械通气患者更推荐 RASS 或 SAS。内镜/局麻辅助镇静目标通常为 2–3 级；6 级需立即评估气道与呼吸。","refs":["Ramsay MAE, et al. Br Med J 1974;2:656-659（Ramsay 原版）","中国重症患者镇痛镇静治疗指南（2018）","PADIS Guidelines 2018（SCCM）"]},{"id":"anes_rass","name":"RASS 镇静躁动评分","aka":["Richmond Agitation-Sedation Scale","RASS"],"cat":"恢复与镇静","rank":8,"desc":"以 +4 至 −5 共 10 档评估清醒与镇静深度，ICU 轻镇静目标 −2 至 0，是镇痛镇静滴定与谵妄监测的常用量表。","inputs":[],"compute":"formula_only","levels":[{"label":"+4 好斗","criteria":"明显好斗、有暴力倾向，对工作人员构成危险","level":"crit"},{"label":"+3 非常躁动","criteria":"拉扯或拔除各种管道、导管，有攻击性行为","level":"high"},{"label":"+2 躁动","criteria":"频繁无目的活动，或人机对抗","level":"warn"},{"label":"+1 不安","criteria":"焦虑、但仍可保持安静（行动不具攻击性）","level":"warn"},{"label":"0 清醒平静","criteria":"清醒、平静、自然状态","level":"ok"},{"label":"−1 嗜睡","criteria":"唤之能保持清醒（睁眼并维持 ≥10 秒）","level":"ok"},{"label":"−2 轻镇静","criteria":"唤之能睁眼并保持接触（<10 秒）","level":"ok"},{"label":"−3 中度镇静","criteria":"对语言刺激有动作或睁眼反应（无目光接触）","level":"warn"},{"label":"−4 深镇静","criteria":"对声音无反应，对疼痛刺激有动作或睁眼","level":"high"},{"label":"−5 不可唤醒","criteria":"对声音与疼痛刺激均无反应","level":"crit"}],"note":"先语言（呼名）后疼痛（肩部摇晃/胸骨按压）分级刺激；ICU 建议目标 RASS −2～0 并每日唤醒。RASS +1 以上需排查疼痛、谵妄（CAM-ICU）、尿潴留、气管导管不适与酒精戒断。","refs":["Sessler CN, et al. Am J Respir Crit Care Med 2002;166:1338-1344（RASS 原版）","PADIS Guidelines 2018（SCCM）","中国重症患者镇痛镇静治疗指南（2018）"]},{"id":"anes_cpot","name":"CPOT 重症监护疼痛观察工具","aka":["Critical-Care Pain Observation Tool","CPOT"],"cat":"恢复与镇静","rank":9,"desc":"对无法自述疼痛的 ICU 患者，按面部表情、肢体活动、肌张力、通气依从/发声 4 项各 0–2 分（0–8），≥3 分提示明显疼痛。","inputs":[{"key":"face","label":"面部表情","type":"select","options":[{"value":0,"label":"无肌肉紧张（放松）"},{"value":1,"label":"表情紧张（皱眉、眉间紧锁）"},{"value":2,"label":"面部扭曲（痛苦表情、紧闭双眼、咬牙）"}],"required":true},{"key":"body","label":"肢体活动","type":"select","options":[{"value":0,"label":"无动作或正常体位"},{"value":1,"label":"保护性活动（缓慢、谨慎移动、触摸疼痛部位）"},{"value":2,"label":"烦躁不安（拉扯管道、剧烈动作）"}],"required":true},{"key":"muscle","label":"肌肉紧张度（被动活动上臂时评估）","type":"select","options":[{"value":0,"label":"对被动活动无抵抗"},{"value":1,"label":"对被动活动有轻度抵抗"},{"value":2,"label":"对被动活动有强烈抵抗或肌肉强直"}],"required":true},{"key":"vent","label":"通气依从性或发声（机械通气者选通气项，非通气者选发声项）","type":"select","options":[{"value":0,"label":"通气：依从/无报警；非通气：正常语调发声"},{"value":1,"label":"通气：呛咳但可耐受；非通气：叹气或呻吟"},{"value":2,"label":"通气：对抗呼吸机；非通气：哭泣或喊叫"}],"required":true}],"formula":"CPOT = 面部表情（0–2）+ 肢体活动（0–2）+ 肌张力（0–2）+ 通气依从/发声（0–2），总分 0–8","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"≥3 分：存在明显疼痛，先排除非疼痛原因（体位、导管、尿潴留、寒战、焦虑）后给予镇痛（如芬太尼/瑞芬太尼滴定），30–60 分钟后复评"},{"when":"v == 2","level":"warn","text":"2 分：可疑疼痛，15–30 分钟内复评，检查是否有护理操作诱因"},{"when":"v <= 1","level":"ok","text":"0–1 分：疼痛控制良好，维持现有镇痛方案，每日至少 2 次评估"}],"note":"CPOT 评分 ≥3 分作为疼痛阈值适用于静息状态，翻身等护理操作后短期升高为生理性，不应据此加量镇痛。机械通气者可比较 CPOT 与 BPS 的一致性；注意肌张力项在躁动/寒战时假性升高。","refs":["Gélinas C, et al. Am J Crit Care 2006;15:420-427（CPOT 原版）","PADIS Guidelines 2018（SCCM）","中国成人 ICU 镇痛和镇静治疗指南（2018）"]},{"id":"anes_bis","name":"BIS 脑电双频指数判读","aka":["Bispectral Index","BIS","BIS 监控"],"cat":"麻醉深度监测","rank":10,"desc":"以脑电双频指数（0–100）量化麻醉深度，40–60 为全麻推荐区间，减少术中知晓与镇静过度（术后谵妄）。","inputs":[{"key":"bis","label":"BIS 数值","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"agent","label":"麻醉方式","type":"select","options":[{"value":1,"label":"全麻（丙泊酚/挥发性吸入）"},{"value":2,"label":"静脉镇静/清醒镇静"},{"value":3,"label":"合并使用氯胺酮、氧化亚氮或神经电生理监测"}],"required":true}],"formula":"BIS 0–100 无单位指数：100 = 清醒，60–80 镇静，40–60 外科麻醉（推荐区间），<40 深度抑制/爆发抑制","compute":"formula_only","algorithm":"v = bis","interpret":[{"when":"bis < 40","level":"high","text":"<40：麻醉过深/爆发抑制，增加术后认知功能障碍与谵妄风险，减浅麻醉并检查血压与灌注"},{"when":"bis <= 60","level":"ok","text":"40–60：外科麻醉深度，适合多数全麻维持（老年、衰弱患者可放宽至 50–60）"},{"when":"bis <= 80","level":"warn","text":"61–80：浅麻醉（镇静/抗伤害不足），对有术中知晓风险者（心脏、剖宫产全麻、全静脉麻醉）应加深"},{"when":"bis > 80","level":"crit","text":">80：清醒/极浅麻醉，存在术中知晓风险，立即追加镇静或加深麻醉，排除设备位置与信号不良"}],"note":"BIS 不可用于氯胺酮、氧化亚氮及部分神经电生理监测场景（信号失真）。接收电极须贴在额颞部并保证阻抗 <7.5 kΩ；监测用于减少镇静剂用量，不能替代临床观察与肌松监测。","refs":["ASA Practice Advisory for Intraoperative Awareness and Brain Function Monitoring, 2018","中国麻醉深度监测专家共识（2020）","B-Aware 随机对照试验（Anesthesiology 2004）"]},{"id":"anes_mac","name":"MAC 最低肺泡有效浓度参考","aka":["Minimum Alveolar Concentration","MAC"],"cat":"麻醉深度监测","rank":11,"desc":"以 1.0 MAC 指 50% 患者对伤害性刺激无体动反应的呼气末吸入麻醉药浓度，按年龄、复合用药校正估算目标吸入浓度。","inputs":[{"key":"agent","label":"吸入麻醉药","type":"select","options":[{"value":1,"label":"七氟烷（Sevoflurane，成人 MAC 约 1.8%–2.0%）"},{"value":2,"label":"地氟烷（Desflurane，成人 MAC 约 6.0%–7.3%）"},{"value":3,"label":"异氟烷（Isoflurane，成人 MAC 约 1.15%–1.2%）"},{"value":4,"label":"氧化亚氮（N2O，成人 MAC 约 104%）"}],"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":1,"max":110,"step":1,"required":true},{"key":"opioid","label":"是否复合阿片类/镇痛","type":"select","options":[{"value":0,"label":"否（单用吸入麻醉）"},{"value":30,"label":"是（大剂量阿片，MAC 降低约 30%）"}],"required":true},{"key":"target_mac","label":"目标 MAC 倍数（如 1.0、1.3）","type":"select","options":[{"value":0.8,"label":"0.8 MAC（老年/衰弱/低血压）"},{"value":1.0,"label":"1.0 MAC（标准外科刺激）"},{"value":1.3,"label":"1.3 MAC（强刺激/防止体动）"},{"value":0.5,"label":"0.5 MAC（清醒插管维持/减浅）"}],"required":true}],"formula":"校正 MAC = 年龄 MAC × 10^[−0.00269 × (年龄 − 40)]（40 岁以上约每 10 年下降 6%）；复合阿片类时 MAC 约降低 30%（取 0.7 倍）；目标呼气末浓度 = 校正 MAC × 目标 MAC 倍数","compute":"formula_only","algorithm":"base = agent==1 ? 1.9 : agent==2 ? 6.6 : agent==3 ? 1.17 : 104\nage_mac = base * Math.pow(10, -0.00269 * (age - 40))  // 年龄校正（Mapleson）\nadj = age_mac * (1 - opioid / 100)\nv = Math.round(adj * target_mac * 100) / 100  // 目标呼气末浓度（%）","interpret":[{"when":"target_mac >= 1.2","level":"warn","text":"目标浓度 ≥1.2 MAC：用于强刺激/防止体动，注意剂量依赖性低血压与血管扩张，老年人应减量"},{"when":"target_mac >= 0.9","level":"ok","text":"0.9–1.2 MAC：标准外科麻醉维持区间，建议同时监测 BIS 与血压"},{"when":"target_mac < 0.9","level":"warn","text":"低于 0.9 MAC：适合老年/衰弱患者或合并镇痛，需注意知晓风险，建议联合 BIS/脑电监测"}],"note":"MAC 单位对挥发性麻醉药为呼气末浓度（vol%）+ 患者年龄校正。宁可用「0.5–1.3 MAC + 个体化血压/脑电」，避免固定沿用 1.0 MAC。MAC-awake 约为 1/3 MAC（苏醒阈值），MAC-BAR 抑制交感反应约需 1.5 MAC。","refs":["Eger EI II. Anesthesiology 2001;95:290-292（MAC 与年龄校正）","Nickalls RWD, Mapleson WW. BJA 2003;91:170-174（MAC 年龄校正）","Miller's Anesthesia 第 9 版（2020）— 吸入麻醉药章节"]},{"id":"anes_stop_bang","name":"STOP-Bang 阻塞性睡眠呼吸暂停筛查","aka":["STOP-BANG Questionnaire","OSA 围术期筛查"],"cat":"术前评估","rank":12,"desc":"8 项术前问卷筛查阻塞性睡眠呼吸暂停（OSA），≥3 分提示中高危，指导围术期气道与镇痛管理。","inputs":[{"key":"snore","label":"S：打鼾（响到隔壁房间可闻/需关闭房门）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"tired","label":"T：白天疲劳嗜睡（几乎每天）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"observed","label":"O：有人观察到睡眠中呼吸暂停/憋气/窒息","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"pressure","label":"P：有高血压","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bmi_high","label":"B：BMI >35 kg/m²","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age_high","label":"A：年龄 >50 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"neck","label":"N：颈围 >40 cm（女性 >35 cm）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"male","label":"G：男性","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"STOP-Bang = 8 项各 1 分，总分 0–8；≤2 低危，3–4 中危，≥5 高危","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：低危，按常规围术期方案；若临床上高度怀疑 OSA 仍建议睡眠监测"},{"when":"v <= 4","level":"warn","text":"3–4 分：中危，术前评估睡眠呼吸情况，避免术前镇静药，术后 PACU 延长观察，镇痛以区域阻滞 + 多模式为主"},{"when":"v >= 5","level":"high","text":"5–8 分：高危，建议术前多导睡眠监测（PSG），必要时转诊；术后持续 SpO2 监测、CPAP 支持（若已使用），慎用阿片类"}],"note":"STOP-Bang 敏感性强、特异度有限；高危（尤其合并 COPD/心衰）围术期并发症风险升高，需个体化镇痛与监护级别。评估不代替 PSG 诊断；已诊断 OSA 的患者应评估 CPAP 依从性。","refs":["Chung F, et al. Anesthesiology 2008;108:812-821（STOP-Bang 原版）","ASA Practice Guidelines for Obstructive Sleep Apnea, 2014","中国阻塞性睡眠呼吸暂停多学科诊疗指南（2018）"]}]},"cardio":{"items":[{"id":"map","name":"平均动脉压（MAP）","aka":["Mean Arterial Pressure","MAP"],"cat":"血流动力学","rank":1,"desc":"由收缩压与舒张压估算平均动脉压，判断器官灌注是否足够。","inputs":[{"key":"sbp","label":"收缩压 SBP","unit":"mmHg","type":"number","min":20,"max":300,"step":1,"required":true},{"key":"dbp","label":"舒张压 DBP","unit":"mmHg","type":"number","min":10,"max":200,"step":1,"required":true}],"formula":"MAP = DBP + (SBP − DBP) / 3","compute":"map","interpret":[{"when":"v < 65","level":"crit","text":"MAP < 65 mmHg：低于多数成人器官灌注目标下限，见于休克/低血压状态，需评估容量、泵功能与血管张力，并按休克流程处理。"},{"when":"v >= 65 && v <= 100","level":"ok","text":"MAP 65–100 mmHg：多数成人目标区间（ICU 常规初始目标 MAP ≥ 65 mmHg）。"},{"when":"v > 100 && v <= 110","level":"warn","text":"MAP 轻度升高，结合患者基础血压判断；慢性高血压者目标可更高。"},{"when":"v > 110","level":"high","text":"MAP 明显升高：见于高血压急症/亚急症、颅高压或疼痛应激等，结合临床评估靶器官损害。"}],"note":"MAP 由无创血压估算；危重症以有创动脉压为准。慢性高血压、老年患者自动调节曲线右移，可接受更高 MAP 目标。","refs":["2024 ESC 血压升高与高血压管理指南","中国高血压防治指南（2024 年修订版）","2021 中国脓毒症/脓毒性休克急诊治疗指南"]},{"id":"cha2ds2_vasc","name":"CHA₂DS₂-VASc 评分（房颤卒中风险）","aka":["CHA2DS2-VASc","房颤血栓栓塞风险"],"cat":"风险评分","rank":2,"desc":"评估非瓣膜性房颤患者卒中/血栓栓塞风险，指导是否启动口服抗凝。","inputs":[{"key":"chf","label":"心力衰竭/左室功能不全（C）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"htn","label":"高血压（H）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age75","label":"年龄 ≥75 岁（A₂）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"dm","label":"糖尿病（D）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"stroke","label":"卒中/TIA/血栓栓塞史（S₂）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true},{"key":"vasc","label":"血管疾病（V，心梗/外周动脉病/主动脉斑块）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age65","label":"年龄 65–74 岁（A）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"female","label":"女性（Sc）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"总分 = C1 + H1 + A2(≥75 岁 2) + D1 + S2(2) + V1 + A(65–74 岁 1) + Sc(女性 1)，满分 9 分","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分（男性）：卒中低危，一般不需抗凝；女性 1 分（仅性别项）亦属低危。"},{"when":"v == 1","level":"warn","text":"1 分：男性为卒中低危/中低危，应考虑口服抗凝（CHA₂DS₂-VA ≥1 即建议抗凝）；女性单纯性别 1 分不需抗凝。"},{"when":"v >= 2","level":"high","text":"≥2 分：卒中高危，若无禁忌建议口服抗凝（优先 NOAC，除外机械瓣/中重度二尖瓣狭窄）。"}],"note":"2023 ACC/AHA/ACCP/HRS 房颤指南与 2024 ESC 房颤指南已改用去性别项的 CHA₂DS₂-VA（男性 ≥1、女性 ≥1 均考虑抗凝）。评分不能替代对瓣膜病、肥厚型心肌病等特殊情况的判断。","refs":["2024 ESC 心房颤动管理指南","2023 ACC/AHA/ACCP/HRS 心房颤动诊断与管理指南","心房颤动：目前的认识和治疗建议（2022）中国专家共识","中国心房颤动诊断和治疗指南（2023）"]},{"id":"cha2ds2_va","name":"CHA₂DS₂-VA 评分（2023 新版，去性别项）","aka":["CHA2DS2-VA","房颤卒中风险（简化）"],"cat":"风险评分","rank":3,"desc":"去掉性别项的房颤卒中风险评分，2023 ACC/AHA 与 2024 ESC 指南推荐替代 CHA₂DS₂-VASc。","inputs":[{"key":"chf","label":"心力衰竭/左室功能不全","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"htn","label":"高血压","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age75","label":"年龄 ≥75 岁","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"dm","label":"糖尿病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"stroke","label":"卒中/TIA/血栓栓塞史","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true},{"key":"vasc","label":"血管疾病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age65","label":"年龄 65–74 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"总分 = C1 + H1 + A2 + D1 + S2 + V1 + A(65–74)1，满分 8 分","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：卒中低危，可不抗凝，定期重新评估（每年复查危险因素）。"},{"when":"v == 1","level":"warn","text":"1 分：建议口服抗凝（IIa 类推荐），结合出血风险与患者意愿决策。"},{"when":"v >= 2","level":"high","text":"≥2 分：口服抗凝 I 类推荐，无禁忌即启动。"}],"note":"无性别差异：男女同一阈值。女性不再单独作为危险因素，仅用于解释既往评分体系中的差异。","refs":["2023 ACC/AHA/ACCP/HRS 心房颤动诊断与管理指南","2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）"]},{"id":"has_bled","name":"HAS-BLED 出血风险评分","aka":["HAS-BLED","房颤出血风险"],"cat":"风险评分","rank":4,"desc":"评估抗凝患者大出血风险，识别可纠正的出血危险因素。","inputs":[{"key":"htn","label":"未控制高血压（SBP >160 mmHg）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"renal","label":"肾功能异常（透析/移植/SCr >200 μmol/L）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"liver","label":"肝功能异常（肝硬化或胆红素↑伴转氨酶↑）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"stroke","label":"卒中史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"bleeding","label":"出血史或出血倾向","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"inr","label":"INR 不稳定（TTR <60%）","type":"select","options":[{"value":0,"label":"无/不适用"},{"value":1,"label":"有"}],"required":true},{"key":"elderly","label":"年龄 >65 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"drugs","label":"药物（抗血小板/NSAID）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"alcohol","label":"酒精过量（≥8 单位/周）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"各项 0/1 分求和，最高 9 分","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"≤2 分：出血低危，常规抗凝可按指南实施，定期随访。"},{"when":"v >= 3","level":"high","text":"≥3 分：出血高危——不是抗凝禁忌，而是应纠正可纠正因素（控制血压、停 NSAID、限酒、稳定 INR）、缩短随访间隔、优先 NOAC。"}],"note":"HAS-BLED 高评分不应作为拒绝抗凝的理由；单纯年龄、既往出血等不可纠正项不改变抗凝指征。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）","心房颤动抗凝治疗中国专家共识（2019）"]},{"id":"grace_acs","name":"GRACE 评分（ACS 院内/6 个月死亡风险）","aka":["GRACE","Global Registry of Acute Coronary Events"],"cat":"风险评分","rank":5,"desc":"急性冠脉综合征入院时风险分层，指导侵入策略时机。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":40,"max":260,"step":1,"required":true},{"key":"crea","label":"血肌酐","unit":"mg/dL","type":"number","min":0.2,"max":15,"step":0.01,"required":true,"hint":"μmol/L ÷ 88.4 = mg/dL"},{"key":"killip","label":"Killip 分级","type":"select","options":[{"value":1,"label":"I 级（无湿啰音、无 S3）"},{"value":2,"label":"II 级（湿啰音<1/2 肺野或 S3、颈静脉压升高）"},{"value":3,"label":"III 级（急性肺水肿）"},{"value":4,"label":"IV 级（心源性休克）"}],"required":true},{"key":"cardiac_arrest","label":"入院时心脏骤停","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"st_dev","label":"ST 段压低","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"markers","label":"心肌损伤标志物升高","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"GRACE 2.0 分段积分：年龄、心率、收缩压、肌酐各自按区间查表取分，Killip 分级查表取分，加心脏骤停、ST 压低、标志物升高各计分，求和后查表换算院内死亡概率","compute":"formula_only","algorithm":"// GRACE 2.0 院内死亡模型（体外验证模型）\n// 1) 分段积分(Score): 按查表规则逐项加权\nfunction graceScore(age, hr, sbp, crea_mgdl, killip, arrest, stDep, markers):\n  s = 0\n  // 年龄(岁): <30:0, 30-39:8, 40-49:25, 50-59:41, 60-69:58, 70-79:75, 80-89:91, >=90:100\n  s += ageScore[floor(age/10)]   // 见 lookup 表\n  // 心率(/min): <=49.9:0, 50-69.9:3, 70-89.9:9, 90-109.9:15, 110-149.9:24, 150-199.9:38, >=200:46\n  // 收缩压(mmHg): >=200:0, 160-199.9:10, 140-159.9:24, 120-139.9:34, 100-119.9:43, 80-99.9:58, <80:63（分段越界判为相应极值）\n  // Killip: I:0, II:21, III:43, IV:64\n  // 肌酐(mg/dL): 0-0.39:2, 0.4-0.79:5, 0.8-1.19:8, 1.2-1.59:11, 1.6-1.99:14, 2-3.99:23, >=4:31\n  s += hrScore(hr) + sbpScore(sbp) + killipScore(killip) + creaScore(crea_mgdl)\n  s += (arrest ? 39 : 0) + (stDep ? 28 : 0) + (markers ? 14 : 0)\n  // 2) 归一化：x = (s - 23.4) / 10.0（GRACE 2.0 院内死亡）\n  // P(院内死亡) = 0.9859 - 0.0081 * exp(x)   // 近似换算函数，用于分级提示\n  // 3) 分级：积分<=108 低危；109-140 中危；>140 高危\n  return { score: s, tier: s <= 108 ? '低危' : (s <= 140 ? '中危' : '高危') }\n// 注：程序实现时直接输出分段积分与等级即可，概率仅供参考","interpret":[{"when":"v <= 108","level":"ok","text":"低危（≤108）：院内死亡风险约 <1%，可择期侵入策略或药物保守评估。"},{"when":"v > 108 && v <= 140","level":"warn","text":"中危（109–140）：建议 24–72 h 内冠脉造影（NSTE-ACS 早期侵入）。"},{"when":"v > 140","level":"crit","text":"高危（>140）：院内死亡风险明显升高，NSTE-ACS 应 24 h 内（紧急）侵入评估；STEMI 直接再灌注。"}],"note":"需使用血肌酐 mg/dL；GRACE 2.0 可交互式计算 6 个月死亡与 1 年死亡/心梗复合终点。心电图 ST 压低与心肌标志物按入院时状态记。","refs":["非 ST 段抬高型急性冠脉综合征诊断和治疗指南（2024）","2015 ESC NSTE-ACS 指南（GRACE 风险分层）","2023 ESC 急性冠脉综合征管理指南"]},{"id":"timi_ua_nstemi","name":"TIMI 评分（UA/NSTEMI）","aka":["TIMI UA/NSTEMI","TIMI Risk Score NSTE-ACS"],"cat":"风险评分","rank":6,"desc":"不稳定型心绞痛/NSTEMI 14 天复合终点风险分层。","inputs":[{"key":"age65","label":"年龄 ≥65 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"cad_risk","label":"≥3 个冠心病危险因素","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"known_cad","label":"已知冠心病（狭窄 ≥50%）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"asa7d","label":"7 天内使用阿司匹林","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"angina24h","label":"24 h 内严重心绞痛发作 ≥2 次","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"st_dev","label":"心电图 ST 段改变 ≥0.5 mm","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"markers","label":"心肌标志物升高","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"7 项各 1 分求和（0–7）","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：低危，14 天死亡/心梗/紧急血运重建风险约 4.7%–8.3%，可药物保守观察。"},{"when":"v >= 3 && v <= 4","level":"warn","text":"3–4 分：中危，风险约 13.2%–19.9%，建议早期侵入策略。"},{"when":"v >= 5","level":"crit","text":"5–7 分：高危，风险约 26.2%–40.9%，积极抗栓并尽早冠脉造影/血运重建。"}],"note":"TIMI 不含血流动力学/心衰项，休克或急性心衰者以 GRACE/Killip 为主。","refs":["非 ST 段抬高型急性冠脉综合征诊断和治疗指南（2024）","2014 AHA/ACC NSTE-ACS 指南","2023 ESC 急性冠脉综合征管理指南"]},{"id":"timi_stemi","name":"TIMI 评分（STEMI 30 天死亡）","aka":["TIMI Risk Index STEMI","STEMI TIMI"],"cat":"风险评分","rank":7,"desc":"ST 段抬高型心肌梗死 30 天死亡风险分层。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true,"hint":"65–79 岁计 2 分，≥80 岁计 3 分"},{"key":"dm_htn_angina","label":"≥3 个冠心病危险因素（含糖尿病、高血压、心绞痛史）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"known_cad","label":"已知冠心病（狭窄 ≥50%）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"asa7d","label":"7 天内使用阿司匹林","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"angina24h","label":"24 h 内严重心绞痛发作 ≥2 次","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"st_dev","label":"ST 段改变 ≥0.5 mm","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"markers","label":"心肌标志物升高","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"STEMI 专用 TIMI：年龄 ≥75 岁 3 分、65–74 岁 2 分；SBP <100 mmHg 3 分；心率 >100 次/分 2 分；Killip II–IV 级 2 分；前壁 STEMI 或 LBBB 1 分；糖尿病/高血压/心绞痛史 1 分；体重 <67 kg 1 分；距治疗时间 >4 h 1 分，满分 14 分","compute":"formula_only","algorithm":"// STEMI TIMI 14 分制\nfunction timiStemi(age, sbp, hr, killip, anteriorOrLBBB, dmOrHtnOrAngina, weightKg, timeToTxH):\n  s = 0\n  s += (age >= 75 ? 3 : (age >= 65 ? 2 : 0))\n  s += (sbp < 100 ? 3 : 0)\n  s += (hr > 100 ? 2 : 0)\n  s += (killip >= 2 ? 2 : 0)\n  s += (anteriorOrLBBB ? 1 : 0)\n  s += (dmOrHtnOrAngina ? 1 : 0)\n  s += (weightKg < 67 ? 1 : 0)\n  s += (timeToTxH > 4 ? 1 : 0)\n  return { score: s, tier: s <= 2 ? '低危' : (s <= 4 ? '中低危' : (s <= 6 ? '中危' : (s <= 8 ? '中高危' : '高危'))) }\n// 参考 30 天死亡率：0-1 分约 0.8%-2.2%；5 分约 12.4%；≥8 分 >26%","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：低危，30 天死亡率约 <3%，仍须按指南完成再灌注与二级预防。"},{"when":"v >= 3 && v <= 8","level":"warn","text":"3–8 分：中至高危，30 天死亡率约 5%–26%，收治 CCU/监护病房，缩短门-球时间。"},{"when":"v >= 9","level":"crit","text":"≥9 分：极高危（30 天死亡率 >26%），考虑机械循环支持评估与强化监护。"}],"note":"本条目展示 STEMI 专用 14 分制；界面上的勾选项仅为示意，实际请按 formula 中的 8 个变量输分。旧版 7 项 TIMI 主要用于 UA/NSTEMI。","refs":["急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","2013 ACCF/AHA STEMI 指南（TIMI 风险评分）"]},{"id":"heart_score","name":"HEART 评分（胸痛危险分层）","aka":["HEART Score","胸痛评分"],"cat":"风险评分","rank":8,"desc":"急诊胸痛患者 6 周主要心血管不良事件风险分层，用于决定留观/出院。","inputs":[{"key":"history","label":"病史（History）","type":"select","options":[{"value":0,"label":"轻度可疑（0）"},{"value":1,"label":"中度可疑（1）"},{"value":2,"label":"高度可疑（2）"}],"required":true},{"key":"ecg","label":"心电图（ECG）","type":"select","options":[{"value":0,"label":"正常（0）"},{"value":1,"label":"非特异性复极异常（1）"},{"value":2,"label":"显著 ST 偏移（2）"}],"required":true},{"key":"age","label":"年龄（Age）","type":"select","options":[{"value":0,"label":"<45 岁（0）"},{"value":1,"label":"45–64 岁（1）"},{"value":2,"label":"≥65 岁（2）"}],"required":true},{"key":"risk","label":"危险因素（Risk factors）","type":"select","options":[{"value":0,"label":"无（0）"},{"value":1,"label":"1–2 个或吸烟（1）"},{"value":2,"label":"≥3 个或已有动脉粥样硬化（2）"}],"required":true},{"key":"trop","label":"肌钙蛋白（Troponin）","type":"select","options":[{"value":0,"label":"正常（0）"},{"value":1,"label":"1–3 倍正常上限（1）"},{"value":2,"label":">3 倍正常上限（2）"}],"required":true}],"formula":"5 项各 0–2 分求和（0–10）","compute":"sum","interpret":[{"when":"v <= 3","level":"ok","text":"0–3 分：低危，6 周 MACE 约 1.7%，可考虑门诊评估/早期出院。"},{"when":"v >= 4 && v <= 6","level":"warn","text":"4–6 分：中危，MACE 约 16.6%，建议留观、连续肌钙蛋白与进一步检查。"},{"when":"v >= 7","level":"crit","text":"7–10 分：高危，MACE 约 50.1%，按 ACS 处理，早期侵入评估。"}],"note":"需配合高敏肌钙蛋白 0/1 h 或 0/3 h 算法使用。","refs":["胸痛中心建设与管理指南（2021）","2021 AHA/ACC 胸痛评估与诊断指南","2023 ESC 急性冠脉综合征管理指南"]},{"id":"wells_dvt","name":"Wells 评分（深静脉血栓）","aka":["Wells DVT Score","DVT 可能性评分"],"cat":"风险评分","rank":9,"desc":"疑诊下肢深静脉血栓者的验前概率评估。","inputs":[{"key":"cancer","label":"活动性肿瘤（治疗中或姑息）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"paralysis","label":"瘫痪/轻瘫/近期下肢石膏固定","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bedridden","label":"卧床 >3 天或 4 周内大手术","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"tenderness","label":"沿深静脉走行局部压痛","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"leg_swelling","label":"整条下肢肿胀","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"calf_diff","label":"小腿周径差 >3 cm","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"pitting","label":"患肢凹陷性水肿","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"collateral","label":"非静脉曲张性侧支浅静脉","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"prev_dvt","label":"既往 DVT 史","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"alt_dx","label":"存在至少与 DVT 同样可能的其他诊断（−2）","type":"select","options":[{"value":0,"label":"否"},{"value":-2,"label":"是（−2）"}],"required":true}],"formula":"9 项各 1 分 + 替代诊断 −2 分，总分 −2 至 9","compute":"sum","interpret":[{"when":"v <= 0","level":"ok","text":"≤0 分：DVT 可能性低（约 5%），结合 D-二聚体可排除。"},{"when":"v >= 1 && v <= 2","level":"warn","text":"1–2 分：中等可能（约 17%），建议查 D-二聚体或超声。"},{"when":"v >= 3","level":"high","text":"≥3 分：高度可能（约 53%），直接行下肢静脉超声，不建议仅以 D-二聚体排除。"}],"note":"采用原始三分类；两项制（≤1 分 DVT 不太可能）见 Wren 等修订版。","refs":["中国血栓性疾病防治指南（2018）","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"wells_pe","name":"Wells 评分（肺栓塞）","aka":["Wells PE Score","PE 可能性评分"],"cat":"风险评分","rank":10,"desc":"疑诊肺栓塞者的临床可能性评估。","inputs":[{"key":"dvt_signs","label":"DVT 临床征象（下肢肿胀、压痛）","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"pe_likely","label":"PE 是最可能诊断（或可能性相同）","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"hr100","label":"心率 >100 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":1.5,"label":"是（+1.5）"}],"required":true},{"key":"immob","label":"制动 >3 天或 4 周内手术","type":"select","options":[{"value":0,"label":"否"},{"value":1.5,"label":"是（+1.5）"}],"required":true},{"key":"prev_vte","label":"既往 DVT/PE 史","type":"select","options":[{"value":0,"label":"否"},{"value":1.5,"label":"是（+1.5）"}],"required":true},{"key":"hemoptysis","label":"咯血","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"cancer","label":"活动性肿瘤","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"各项加权求和，总分 0–12.5","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"≤4 分：PE 可能性低（两项制「不太可能」，患病率约 12%），下一步查 D-二聚体；阴性可排除。"},{"when":"v > 4","level":"high","text":">4 分：PE「可能」（患病率约 37%），直接行 CTPA 或 V/Q 显像。"}],"note":"三分类：0–1 低（1.3%）、2–6 中（16.2%）、≥7 高（40.6%）。妊娠期首选 D-二聚体分层 + 下肢超声。","refs":["肺血栓栓塞症诊治与预防指南（2018，中华医学会呼吸病学分会）","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"geneva_revised","name":"修订版 Geneva 评分（肺栓塞）","aka":["Revised Geneva Score"],"cat":"风险评分","rank":11,"desc":"全客观变量的肺栓塞临床可能性评分。","inputs":[{"key":"age65","label":"年龄 ≥65 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"prev_vte","label":"既往 DVT/PE","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"surgery","label":"1 个月内手术或下肢骨折","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"cancer","label":"活动性恶性肿瘤","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"pain","label":"单侧下肢疼痛","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"hemoptysis","label":"咯血","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"hr_75_94","label":"心率 75–94 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"hr95","label":"心率 ≥95 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":5,"label":"是（+5）"}],"required":true},{"key":"dvt_pain","label":"下肢深静脉触痛伴单侧水肿","type":"select","options":[{"value":0,"label":"否"},{"value":4,"label":"是（+4）"}],"required":true}],"formula":"加权求和，总分 0–25","compute":"sum","interpret":[{"when":"v <= 3","level":"ok","text":"0–3 分：低度可能（约 8%），查 D-二聚体，阴性可排除。"},{"when":"v > 3 && v <= 10","level":"warn","text":"4–10 分：中度可能（约 28%），查 D-二聚体 + 影像。"},{"when":"v > 10","level":"high","text":"≥11 分：高度可能（约 74%），直接 CTPA。"}],"note":"两项制：≤5 分 PE 不太可能。与 Wells 相比不含主观判断。","refs":["肺血栓栓塞症诊治与预防指南（2018）","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"pesi","name":"肺栓塞严重指数（PESI）","aka":["PESI","Pulmonary Embolism Severity Index"],"cat":"风险评分","rank":12,"desc":"急性肺栓塞 30 天死亡风险分级，决定门诊治疗/早期出院。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true,"hint":"直接加原始岁数"},{"key":"male","label":"男性","type":"select","options":[{"value":0,"label":"否"},{"value":10,"label":"是（+10）"}],"required":true},{"key":"cancer","label":"肿瘤","type":"select","options":[{"value":0,"label":"否"},{"value":30,"label":"是（+30）"}],"required":true},{"key":"hf_lung","label":"心力衰竭或慢性肺病","type":"select","options":[{"value":0,"label":"否"},{"value":10,"label":"是（+10）"}],"required":true},{"key":"hr110","label":"心率 ≥110 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":20,"label":"是（+20）"}],"required":true},{"key":"sbp100","label":"收缩压 <100 mmHg","type":"select","options":[{"value":0,"label":"否"},{"value":30,"label":"是（+30）"}],"required":true},{"key":"rr30","label":"呼吸频率 ≥30 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":20,"label":"是（+20）"}],"required":true},{"key":"temp36","label":"体温 <36 ℃","type":"select","options":[{"value":0,"label":"否"},{"value":20,"label":"是（+20）"}],"required":true},{"key":"ams","label":"意识改变","type":"select","options":[{"value":0,"label":"否"},{"value":60,"label":"是（+60）"}],"required":true},{"key":"spo2","label":"血氧饱和度 <90%","type":"select","options":[{"value":0,"label":"否"},{"value":20,"label":"是（+20）"}],"required":true}],"formula":"总分 = 年龄（岁）+ 各项加权分，最高约 395","compute":"sum","interpret":[{"when":"v <= 65","level":"ok","text":"I 级（≤65）：30 天死亡率 0–1.6%，可考虑门诊/早期出院治疗。"},{"when":"v > 65 && v <= 85","level":"ok","text":"II 级（66–85）：30 天死亡率 1.7%–3.5%，部分患者可早期出院。"},{"when":"v > 85 && v <= 105","level":"warn","text":"III 级（86–105）：30 天死亡率 3.2%–7.1%，住院治疗。"},{"when":"v > 105 && v <= 125","level":"high","text":"IV 级（106–125）：30 天死亡率 4.0%–11.4%，住院并密切监护。"},{"when":"v > 125","level":"crit","text":"V 级（>125）：30 天死亡率 10%–24.5%，重症监护，评估溶栓/导管治疗。"}],"note":"年龄按实际岁数直接计入；简化版 sPESI 见下一条。","refs":["肺血栓栓塞症诊治与预防指南（2018）","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"pesi_simplified","name":"简化肺栓塞严重指数（sPESI）","aka":["sPESI","Simplified PESI"],"cat":"风险评分","rank":13,"desc":"6 项二分类指标快速识别低危肺栓塞。","inputs":[{"key":"age80","label":"年龄 >80 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"cancer","label":"肿瘤","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"cpd","label":"慢性心肺疾病","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"hr110","label":"心率 ≥110 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"sbp100","label":"收缩压 <100 mmHg","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"spo2","label":"血氧饱和度 <90%","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"6 项各 1 分，0 分即可判低危","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：低危（30 天死亡率约 1%），若影像与右心功能允许可门诊抗凝。"},{"when":"v >= 1","level":"high","text":"≥1 分：非低危（30 天死亡率约 10.9%），需住院并评估是否中高危/高危。"}],"note":"还需结合右心室功能（超声/CT）与肌钙蛋白对中危再分层。","refs":["肺血栓栓塞症诊治与预防指南（2018）","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"arc_hbr","name":"ARC-HBR 高出血风险标准","aka":["ARC-HBR","Academic Research Consortium High Bleeding Risk"],"cat":"抗栓/出血","rank":14,"desc":"PCI 术后高出血风险判定，决定双联抗血小板疗程缩短。","inputs":[{"key":"major","label":"主要标准个数（活动性出血、既往大出血、血小板<100×10⁹/L、CrCl<30、肝硬化、透析、1 个月内大手术/创伤/颅内出血、12 个月内自发性颅内出血、口服抗凝长期使用）","unit":"个","type":"number","min":0,"max":9,"step":1,"required":true},{"key":"minor","label":"次要标准个数（年龄>75、eGFR 30–59、血红蛋白 110–129 g/L、血小板 100–149×10⁹/L、12 个月内需住院的出血、预计长期使用 NSAIDs/激素）","unit":"个","type":"number","min":0,"max":6,"step":1,"required":true}],"formula":"满足 ≥1 条主要标准，或 ≥2 条次要标准，即判为 HBR","compute":"formula_only","algorithm":"// ARC-HBR 判定\nfunction arcHbr(major, minor):\n  eligible = (major >= 1) || (minor >= 2)\n  return { hbr: eligible, label: eligible ? '高出血风险(HBR)' : '非高出血风险' }\n// 判定为 HBR：考虑 1–3 个月 DAPT，之后 P2Y12 单药或 SAPT，优先无聚合物药物涂层支架/DES 选择","interpret":[{"when":"major >= 1 || minor >= 2","level":"high","text":"符合 ARC-HBR：高出血风险，建议 DAPT 缩短至 1–3 个月，随后单药抗血小板；避免长时间三联抗栓。"},{"when":"major == 0 && minor < 2","level":"ok","text":"未达 ARC-HBR：按标准 DAPT 疗程（一般 6–12 个月），ACS 高危者可行 12 个月。"}],"note":"主要/次要标准须逐条核对（本条目只读取个数）。高龄+肾功能不全是最常见的组合。","refs":["2023 ESC 急性冠脉综合征管理指南","2024 ESC 慢性冠脉综合征管理指南","冠心病双联抗血小板治疗中国专家共识（2021）"]},{"id":"orbit_bleeding","name":"ORBIT 出血风险评分（房颤）","aka":["ORBIT score"],"cat":"抗栓/出血","rank":15,"desc":"房颤患者抗凝后大出血风险的定量评分。","inputs":[{"key":"age74","label":"年龄 ≥74 岁（2 分）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"anemia","label":"贫血（血红蛋白/血细胞比容降低）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"bleeding","label":"既往出血史","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"renal","label":"eGFR <60 mL/min/1.73m²","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"antiplatelet","label":"抗血小板药物使用","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"0–7 分（3 项各 2 分 + 2 项各 1 分）","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：低出血风险（年大出血约 2.0%）。"},{"when":"v == 3","level":"warn","text":"3 分：中出血风险（约 4.7%/年），加强随访与血压管理。"},{"when":"v >= 4","level":"high","text":"≥4 分：高出血风险（约 8.1%/年），纠正可纠正因素，优先 NOAC、避免不必要的抗血小板联合。"}],"note":"ORBIT 较 HAS-BLED 含贫血项，对 NOAC 人群区分度较好。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）"]},{"id":"maggic","name":"MAGGIC 心衰评分（1 年死亡）","aka":["MAGGIC","Meta-Analysis Global Group in Chronic Heart Failure"],"cat":"心衰","rank":16,"desc":"慢性心衰患者 1 年与 3 年死亡风险预测。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"female","label":"女性（+1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"lv_ef","label":"LVEF","unit":"%","type":"number","min":5,"max":80,"step":1,"required":true},{"key":"nyha","label":"NYHA 心功能分级","type":"select","options":[{"value":1,"label":"I 级"},{"value":2,"label":"II 级"},{"value":3,"label":"III 级"},{"value":4,"label":"IV 级"}],"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":60,"max":240,"step":1,"required":true},{"key":"crea","label":"血肌酐","unit":"μmol/L","type":"number","min":20,"max":1200,"step":1,"required":true},{"key":"dm","label":"糖尿病（+1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"smoker","label":"目前吸烟（+1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"copd","label":"COPD（+1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"MAGGIC 积分：年龄、LVEF、收缩压、肌酐按分段查表计分，NYHA II/III/IV 分别 +2/+6/+8，女性 +1，糖尿病 +1，吸烟 +1，COPD +1；总分 0–57，查表得 1 年/3 年死亡率","compute":"formula_only","algorithm":"// MAGGIC 危险积分（连续变量分段）\nfunction maggic(age, female, lvef, nyha, sbp, crea_umol, dm, smoker, copd):\n  s = 0\n  // 年龄：<55:0, 55-59:1, 60-64:2, 65-69:3, 70-74:5, 75-79:6, >=80:8\n  s += agePts(age)\n  // 女性 +1\n  // LVEF(%)：<20:7, 20-24:6, 25-29:5, 30-34:3, 35-39:2, >=40:0\n  s += efPts(lvef)\n  // NYHA：I:0, II:2, III:6, IV:8\n  s += nyhaPts(nyha)\n  // 收缩压(mmHg)：<90:5, 90-99:5, 100-109:4, 110-119:3, 120-129:2, 130-139:2, 140-149:1, >=150:0\n  s += sbpPts(sbp)\n  // 肌酐(μmol/L)：<90:0, 90-109:1, 110-129:2, 130-149:3, 150-169:3, 170-209:4, 210-249:5, >=250:6\n  s += creaPts(crea_umol)\n  s += female + dm + smoker + copd\n  // 1 年死亡率 ≈ 0.5% + (0.09% × s) 分段查表；3 年死亡率更高\n  return { score: s, tier: s <= 10 ? '低危' : (s <= 19 ? '中危' : (s <= 27 ? '高危' : '极高危')) }\n// 注：分段边界以原始 MAGGIC 发表表格为准，实现时把各级分表写进常量","interpret":[{"when":"v <= 10","level":"ok","text":"低积分（≤10）：1 年死亡风险低，继续优化 GDMT 与随访。"},{"when":"v > 10 && v <= 19","level":"warn","text":"中积分（11–19）：1 年死亡风险中危，评估器械治疗（ICD/CRT）与进阶心衰管理。"},{"when":"v > 19 && v <= 27","level":"high","text":"高积分（20–27）：高危，考虑心衰专科门诊/心脏移植或 LVAD 评估。"},{"when":"v > 27","level":"crit","text":"极高积分（>27）：1 年死亡率 >40%，优先姑息/进阶治疗决策，讨论移植、LVAD 与预立医疗计划。"}],"note":"MAGGIC 使用 LVEF 连续值与分级的查表分；界面输入仅用于记录，实际风险按分段表计算。","refs":["中国心力衰竭诊断和治疗指南（2024）","2021 ESC 急慢性心力衰竭诊断与治疗指南","MAGGIC 协作组危险评分（Pocock SJ, Lancet 2013）"]},{"id":"shfm","name":"西雅图心衰模型（SHFM）","aka":["Seattle Heart Failure Model"],"cat":"心衰","rank":17,"desc":"慢性心衰 1/2/5 年生存预测，并估算药物与器械治疗的生存获益。","inputs":[{"key":"lvef","label":"LVEF","unit":"%","type":"number","min":5,"max":80,"step":1,"required":true},{"key":"nyha","label":"NYHA 分级","type":"select","options":[{"value":1,"label":"I 级"},{"value":2,"label":"II 级"},{"value":3,"label":"III 级"},{"value":4,"label":"IV 级"}],"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":60,"max":240,"step":1,"required":true},{"key":"bun","label":"血尿素氮 BUN","unit":"mmol/L","type":"number","min":0.5,"max":100,"step":0.1,"required":true},{"key":"sodium","label":"血钠","unit":"mmol/L","type":"number","min":105,"max":160,"step":1,"required":true}],"formula":"SHFM 为多变量 Cox 模型：危险评分 = Σβ×变量（LVEF、NYHA、收缩压、BUN、血钠、年龄、糖尿病、利尿剂剂量、ACEI/ARB/β 阻滞剂/他汀/MRA 使用等），再换算 1/2/5 年生存率","compute":"formula_only","algorithm":"// SHFM 按发布模型：先算危险评分，再查表得 1/2/5 年生存\nfunction shfm(params):\n  // 系数来自 Levy WC et al., Circulation 2006 发表的模型表，实现时以常量表录入\n  s = sumForEachVar(coef[var] * value[var])\n  surv1 = 1 - 0.5 ^ exp(s)      // 简式近似，精确值以模型表为准\n  return { score: s, surv1: surv1 }\n// 本条目界面输入不足以跑完整模型，展示为参考；实现时须完整录入全部变量与系数","interpret":[{"when":"lvef <= 30","level":"high","text":"LVEF ≤30%：属 HFrEF，应评估 ICD/CRT 指征并按 SYNPASE/四联用药优化。"},{"when":"lvef > 30 && lvef <= 40","level":"warn","text":"LVEF 31%–40%：HFmrEF，SGLT2i、RAASi、MRA 可获益，目标 LVEF 改善。"},{"when":"lvef > 40","level":"ok","text":"LVEF >40%：HFpEF/HFimpEF，SGLT2i 与综合管理为主。"}],"note":"SHFM 需完整录入全部变量与系数才能给出生存率，本界面仅作分类提示；国内临床更多使用 MAGGIC 与 NT-proBNP 联合评估。","refs":["中国心力衰竭诊断和治疗指南（2024）","2021 ESC 急慢性心力衰竭诊断与治疗指南","Levy WC, Circulation 2006（SHFM 原始模型）"]},{"id":"hfref_four_pillars","name":"HFrEF 四联用药剂量参考","aka":["HFrEF GDMT 四联","新四联"],"cat":"心衰","rank":18,"desc":"射血分数降低心衰四类基石药物及常用起始/目标剂量速查。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"ARNI（沙库巴曲缬沙坦）","criteria":"起始 50 mg 或 25 mg（老年/低血压/肾功能不全）bid；目标 200 mg bid；转 ARNI 需停 ACEI 36 h；不适用于有血管性水肿史或妊娠者","level":"ok"},{"label":"ACEI（依那普利/培哚普利）","criteria":"依那普利 起始 2.5 mg bid，目标 10 mg bid；培哚普利 起始 2 mg qd，目标 4–8 mg qd；咳喘、高钾、肌酐升高 >30% 需复查","level":"ok"},{"label":"ARB（缬沙坦/坎地沙坦）","criteria":"缬沙坦 起始 40 mg bid、目标 160 mg bid；与 ARNI 不可联用","level":"ok"},{"label":"β 受体阻滞剂（美托洛尔/比索洛尔）","criteria":"琥珀酸美托洛尔缓释 起始 11.875–23.75 mg qd，目标 190 mg qd；比索洛尔起始 1.25 mg qd，目标 10 mg qd；须病情稳定后加量","level":"ok"},{"label":"MRA（螺内酯）","criteria":"起始 10–20 mg qd，目标 25–50 mg qd；eGFR <30 或 K⁺ >5.0 mmol/L 不用；监测血钾与肌酐","level":"warn"},{"label":"SGLT2i（达格列净/恩格列净）","criteria":"达格列净 10 mg qd、恩格列净 10 mg qd；eGFR 下限放宽至 20 mL/min/1.73m²（心衰适应证）；注意泌尿生殖道感染","level":"ok"},{"label":"利尿剂（呋塞米/托拉塞米）","criteria":"按容量状态滴定：呋塞米 20–40 mg qd–bid 起始，目标为无淤血的最低剂量；体重每日监测","level":"warn"},{"label":"地高辛","criteria":"0.125–0.25 mg qd（老年、肾功能不全者 0.125 mg 隔日或减量），目标血药浓度 0.5–0.9 ng/mL，无症状房颤心室率控制时较低剂量","level":"warn"}],"note":"四联应尽早联用并逐步滴定至耐受的最大剂量；ARNI/ACEI/ARB 只选其一，且不与 MRA 联用时有高钾风险须监测。剂量以最新版说明书与 2024 中国心衰指南为准，肾功能不全者按说明书调整。","refs":["中国心力衰竭诊断和治疗指南（2024）","2023 ESC 心力衰竭重点更新","2022 AHA/ACC/HFSA 心力衰竭管理指南"]},{"id":"six_min_walk","name":"6 分钟步行距离（6MWD）判读","aka":["6MWT","6-minute walk test"],"cat":"心衰","rank":19,"desc":"评估心衰患者运动耐量，预测预后与再住院风险。","inputs":[{"key":"dist","label":"6 分钟步行距离","unit":"m","type":"number","min":0,"max":900,"step":1,"required":true},{"key":"predicted","label":"预计 6MWD（可选，按年龄/身高/体重计算）","unit":"m","type":"number","min":100,"max":1000,"step":1,"required":false}],"formula":"6MWD 为实测值；预后阈值（心衰指南常用）：<300 m 提示预后不良；实测/预计百分比 <80% 为运动耐量下降","compute":"formula_only","algorithm":"// 6MWD 预后判读\nfunction sixMWD(dist, predicted):\n  pct = predicted ? dist / predicted * 100 : null\n  tier = dist < 300 ? '差（预后不良）'\n       : dist < 400 ? '中等'\n       : dist < 500 ? '较好'\n       : '良好'\n  if (pct !== null && pct < 80) tier += '；低于预计值 80%'\n  return { dist, pct, tier }\n// 预计值参考方程（Enright-Sherrill, 成人）：男 6MWD = 7.57×身高(cm) − 5.02×年龄 − 1.76×体重(kg) − 309；女 = 2.11×身高 − 2.29×年龄 − 5.78×体重 + 667","interpret":[{"when":"dist < 300","level":"crit","text":"<300 m：运动耐量明显下降，心衰预后不良（与 1 年死亡/再住院显著相关），考虑强化治疗或心脏移植评估。"},{"when":"dist >= 300 && dist < 400","level":"warn","text":"300–399 m：中度受限，评估为 NYHA II–III 级，督促康复训练。"},{"when":"dist >= 400 && dist < 500","level":"ok","text":"400–499 m：较好，接近轻中度受限。"},{"when":"dist >= 500","level":"ok","text":"≥500 m：运动耐量良好，提示心功能代偿较好。"}],"note":"6MWD 变化 ≥30 m 视为临床有意义（改善或恶化）；试验需按 ATS 规范进行（30 m 走廊、标准指令）。","refs":["中国心力衰竭诊断和治疗指南（2024）","2002 ATS 6 分钟步行试验指南","2013 ATS/ERS 肺功能检查技术标准（6MWT）"]},{"id":"killip","name":"Killip 分级（AMI 心功能）","aka":["Killip class","Killip 分级"],"cat":"分级量表","rank":20,"desc":"急性心肌梗死患者床边心功能分级。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"I 级","criteria":"无心力衰竭征象：肺部无湿啰音，无第 3 心音及颈静脉压升高","level":"ok"},{"label":"II 级","criteria":"轻至中度心衰：湿啰音 ≤1/2 肺野，或第 3 心音、颈静脉压升高；有 S3 奔马律及肺部啰音","level":"warn"},{"label":"III 级","criteria":"急性肺水肿：湿啰音 >1/2 肺野，可伴低氧血症、端坐呼吸","level":"high"},{"label":"IV 级","criteria":"心源性休克：低血压（SBP <90 mmHg 或需升压药）、外周灌注不足（少尿、肢端湿冷）、肺水肿","level":"crit"}],"note":"Killip III/IV 级院内死亡率显著升高；入院 48 h 内按最差分级取值并纳入 GRACE 评分。","refs":["急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","2023 ESC 急性冠脉综合征管理指南"]},{"id":"nyha","name":"NYHA 心功能分级","aka":["New York Heart Association class"],"cat":"分级量表","rank":21,"desc":"按症状与活动能力对慢性心衰进行功能分级。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"I 级","criteria":"体力活动不受限：日常活动不引起疲乏、心悸、呼吸困难或心绞痛","level":"ok"},{"label":"II 级","criteria":"体力活动轻度受限：休息时无症状，日常活动可引起症状","level":"ok"},{"label":"III 级","criteria":"体力活动明显受限：休息时无症状，低于日常活动的轻微活动即可引起症状","level":"warn"},{"label":"IV 级","criteria":"不能从事任何体力活动：休息时即有症状，任何活动均使症状加重","level":"crit"}],"note":"NYHA 反映症状，不反映 LVEF；同一患者可能在不同时间变动，建议记录随访时点。","refs":["中国心力衰竭诊断和治疗指南（2024）","2022 AHA/ACC/HFSA 心力衰竭管理指南"]},{"id":"acc_aha_hf_stage","name":"ACC/AHA 心衰分期（A–D）","aka":["心衰分期","HF stages"],"cat":"分级量表","rank":22,"desc":"按疾病进程对心衰进行分期，与 NYHA 分级互补（分期不可逆）。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"A 期（心衰高危）","criteria":"存在心衰危险因素（高血压、糖尿病、肥胖、动脉粥样硬化性疾病、心肌病家族史、心脏毒性药物暴露），无结构性心脏病、症状或生物标志物异常","level":"ok"},{"label":"B 期（心衰前期）","criteria":"无心衰症状/体征，但有无症状的结构性心脏病（LVEF 降低、左室肥厚、室壁运动异常）或利钠肽/肌钙蛋白升高（无其他原因）","level":"warn"},{"label":"C 期（症状性心衰）","criteria":"有结构性心脏病，且当前或既往有活动性心衰症状/体征","level":"high"},{"label":"D 期（终末期心衰）","criteria":"因症状严重而需反复住院或需静脉强心，需进阶治疗（心脏移植、LVAD、姑息治疗）或已达到生命终末阶段","level":"crit"}],"note":"2022 AHA/ACC/HFSA 新增 C 期定义中的「既往或当前」，并强调以利钠肽筛查 B 期。中国指南沿用 A–D 分期 + NYHA。","refs":["2022 AHA/ACC/HFSA 心力衰竭管理指南","中国心力衰竭诊断和治疗指南（2024）"]},{"id":"ccs_angina","name":"CCS 心绞痛分级（加拿大心血管学会）","aka":["CCS class","加拿大心血管学会分级"],"cat":"分级量表","rank":23,"desc":"评价稳定型心绞痛症状严重程度，也用于中国慢性冠脉综合征指南的分级。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"I 级","criteria":"日常活动（如走路、爬楼）不引起心绞痛；剧烈、快速或长时间活动时才发作","level":"ok"},{"label":"II 级","criteria":"日常活动轻度受限：快走、爬较快楼梯、饭后或情绪激动时、晨起时发作","level":"ok"},{"label":"III 级","criteria":"日常活动明显受限：平地步行 <2 个街区（约 200 m）或爬 1 层楼即发作","level":"warn"},{"label":"IV 级","criteria":"轻微活动或休息时即可发作，不能从事任何体力活动","level":"crit"}],"note":"CCS IV 静息发作提示 ACS 或严重缺血，须急诊评估。CCS 分级、NYHA 分级与 EHRA 分级属性不同，不要混用。","refs":["慢性冠脉综合征诊断和治疗指南（2024）","2024 ESC 慢性冠脉综合征管理指南","2013 ACCF/AHA 稳定性冠心病指南"]},{"id":"ehra_symptom","name":"房颤 EHRA 症状分级","aka":["EHRA symptom score"],"cat":"分级量表","rank":24,"desc":"按症状对日常生活的影响程度对房颤进行分级。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"1 级","criteria":"无症状：房颤不引起任何症状","level":"ok"},{"label":"2a 级","criteria":"轻度症状：日常生活不受影响","level":"ok"},{"label":"2b 级","criteria":"中度症状：日常活动不受影响，但存在患者困扰（如运动耐量轻度下降）","level":"ok"},{"label":"3 级","criteria":"重度症状：日常生活受影响、出现症状，但仍可耐受","level":"warn"},{"label":"4 级","criteria":"致残症状：日常生活严重受影响、不能从事正常活动","level":"crit"}],"note":"EHRA 分级决定节律控制（导管消融/抗心律失常药）意愿强烈程度：≥2b 和 3 级更倾向积极节律控制。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）"]},{"id":"chads2","name":"CHADS₂ 评分（房颤卒中，旧版）","aka":["CHADS2"],"cat":"风险评分","rank":25,"desc":"早期房颤卒中风险评分，现已基本被 CHA₂DS₂-VASc 取代。","inputs":[{"key":"chf","label":"充血性心衰（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"htn","label":"高血压（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age75","label":"年龄 ≥75 岁（1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"dm","label":"糖尿病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"stroke","label":"卒中/TIA 史（2）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true}],"formula":"求和，满分 6 分","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：低危，年卒中约 1.9%。"},{"when":"v == 1","level":"warn","text":"1 分：中危，年卒中约 2.8%，考虑抗凝。"},{"when":"v >= 2","level":"high","text":"≥2 分：高危，年卒中 ≥4%，建议抗凝。"}],"note":"旧版评分不包含 65–74 岁、血管疾病、女性；保留仅供历史资料与旧文献对照。","refs":["心房颤动：目前的认识和治疗建议（2022）","2019 AHA/ACC/HRS 心房颤动管理指南"]},{"id":"same_tt2r2","name":"SAME-TT₂R₂ 评分","aka":["SAMe-TT2R2"],"cat":"风险评分","rank":26,"desc":"预测华法林维持者能否达到良好 INR 控制（TTR ≥70%），指导 VKA 还是 NOAC。","inputs":[{"key":"female","label":"女性（1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age60","label":"年龄 <60 岁（1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"meds","label":"≥2 种易相互作用药物（如胺碘酮）（1）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"smoker","label":"吸烟（2）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"race","label":"非白种人（2）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true}],"formula":"S1+A1+M1+E1+T2+R2 = 0–8 分","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：TTR ≥70% 可能性大，可考虑华法林。"},{"when":"v == 3","level":"warn","text":"3 分：边界，可选择华法林并加强 INR 管理，或优先 NOAC。"},{"when":"v > 3","level":"high","text":">3 分：预测最差（poor TTR），优先 NOAC。"}],"note":"SAME-TT2R2 仅适用于华法林使用者；NOAC 适应人群无需此评分。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）"]},{"id":"six_month_bleeding_fa","name":"房颤出血风险整合提示","aka":["房颤出血风险评估"],"cat":"抗栓/出血","rank":27,"desc":"把 HAS-BLED、ORBIT 与可纠正因素整合，形成出血随访要点。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"HAS-BLED ≥3","criteria":"提示出血高危：不是禁忌，需处理可纠正因素（血压、抗血小板/NSAID、酒精、INR 稳定）","level":"warn"},{"label":"ORBIT ≥4","criteria":"年大出血风险约 8%，建议优先 NOAC、缩短随访、评估贫血与肾功能","level":"high"},{"label":"可纠正的 6 项","criteria":"血压未控制（SBP >160）、抗血小板/NSAID 联用、酒精过量、INR 不稳定、贫血、肾功能恶化","level":"warn"},{"label":"特殊高危人群","criteria":"既往颅内出血、透析、肝硬化、12 个月内消化道出血 → 按 ARC-HBR，改用更短抗栓或暂缓抗凝","level":"crit"}],"note":"2024 ESC 房颤指南建议动态评估出血风险，不因高分而停抗凝，而是改变干预方式。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）"]},{"id":"crusade_score","name":"CRUSADE 出血评分（NSTE-ACS）","aka":["CRUSADE bleeding score"],"cat":"风险评分","rank":28,"desc":"NSTE-ACS 住院期间大出血风险预测。","inputs":[{"key":"male","label":"男性（+6）","type":"select","options":[{"value":0,"label":"否"},{"value":6,"label":"是（+6）"}],"required":true},{"key":"dm","label":"糖尿病（+6）","type":"select","options":[{"value":0,"label":"否"},{"value":6,"label":"是（+6）"}],"required":true},{"key":"prev_cvd","label":"既往血管疾病（+6）","type":"select","options":[{"value":0,"label":"否"},{"value":6,"label":"是（+6）"}],"required":true},{"key":"hr","label":"心率（次/分）","type":"select","options":[{"value":0,"label":"≤70（0）"},{"value":3,"label":"71–80（3）"},{"value":6,"label":"81–90（6）"},{"value":8,"label":"91–100（8）"},{"value":10,"label":"101–110（10）"},{"value":11,"label":"111–120（11）"},{"value":12,"label":"≥121（12）"}],"required":true},{"key":"sbp","label":"收缩压（mmHg）","type":"select","options":[{"value":0,"label":"≤100（0）"},{"value":3,"label":"101–180（3）"},{"value":5,"label":"181–200（5）"},{"value":6,"label":"201–220（6）"},{"value":8,"label":"221–240（8）"},{"value":10,"label":"≥241（10）"}],"required":true},{"key":"hct","label":"血细胞比容（%）","type":"select","options":[{"value":0,"label":"≥40（0）"},{"value":3,"label":"37–39.9（3）"},{"value":6,"label":"34–36.9（6）"},{"value":9,"label":"31–33.9（9）"},{"value":14,"label":"≤30.9（14）"}],"required":true},{"key":"crcl","label":"肌酐清除率（mL/min）","type":"select","options":[{"value":0,"label":"≥121（0）"},{"value":7,"label":"91–120（7）"},{"value":17,"label":"61–90（17）"},{"value":28,"label":"31–60（28）"},{"value":35,"label":"16–30（35）"},{"value":39,"label":"≤15（39）"}],"required":true},{"key":"signs","label":"心衰征象（+7）","type":"select","options":[{"value":0,"label":"否"},{"value":7,"label":"是（+7）"}],"required":true}],"formula":"各项加权求和，总分 20–91","compute":"sum","interpret":[{"when":"v <= 30","level":"ok","text":"≤30 分：极低出血风险（约 3.1%），可常规抗栓。"},{"when":"v > 30 && v <= 41","level":"ok","text":"31–40 分：低危（约 5.5%）。"},{"when":"v > 41 && v <= 51","level":"warn","text":"41–50 分：中危（约 8.6%），注意抗栓强度与穿刺路径选择。"},{"when":"v > 51 && v <= 65","level":"high","text":"51–65 分：高危（约 11.9%），优先桡动脉入路、减量抗凝。"},{"when":"v > 65","level":"crit","text":">65 分：极高危（约 19.5%），严格评估出血与缺血平衡，谨慎使用 GP IIb/IIIa 抑制剂。"}],"note":"入口已按分段查表取值，直接求和即可。","refs":["非 ST 段抬高型急性冠脉综合征诊断和治疗指南（2024）","2014 AHA/ACC NSTE-ACS 指南"]},{"id":"cardiac_output_fick","name":"心输出量/心指数（Fick 法）","aka":["CO/CI Fick","Fick principle"],"cat":"血流动力学","rank":29,"desc":"以氧耗量和动静脉氧差推算心输出量，再结合 BSA 得心指数。","inputs":[{"key":"vo2","label":"氧耗量 VO₂","unit":"mL/min","type":"number","min":50,"max":800,"step":1,"required":true,"hint":"常用估算 125×BSA"},{"key":"cao2","label":"动脉血氧含量 CaO₂","unit":"mL/dL","type":"number","min":5,"max":25,"step":0.1,"required":true,"hint":"1.34×Hb×SaO₂+0.0031×PaO₂"},{"key":"cvo2","label":"混合静脉血氧含量 CvO₂","unit":"mL/dL","type":"number","min":2,"max":20,"step":0.1,"required":true},{"key":"bsa","label":"体表面积 BSA","unit":"m²","type":"number","min":0.5,"max":3,"step":0.01,"required":true,"hint":"可用 BSA 计算器"}],"formula":"CO = VO₂ / (CaO₂ − CvO₂) × 10（L/min）；CI = CO / BSA（L/min/m²）","compute":"formula_only","algorithm":"// Fick 法\nfunction fick(vo2, cao2, cvo2, bsa):\n  co = vo2 / ((cao2 - cvo2) * 10)   // L/min\n  ci = co / bsa                    // L/min/m²\n  return { co, ci, tier: ci < 2.2 ? '心指数降低' : (ci > 4.0 ? '心指数偏高' : '正常') }\n// 阈值：CI 正常 2.5–4.0 L/min/m²；心源性休克 CI <2.2 且需升压药；CO 参考值 4–8 L/min","interpret":[{"when":"(vo2 / ((cao2 - cvo2) * 10) / bsa) < 2.2","level":"crit","text":"CI <2.2 L/min/m²：心输出量明显降低，若伴低灌注为心源性休克，需正性肌力/机械循环支持评估。"},{"when":"(vo2 / ((cao2 - cvo2) * 10) / bsa) >= 2.2 && (vo2 / ((cao2 - cvo2) * 10) / bsa) < 2.5","level":"warn","text":"CI 2.2–2.5：临界，结合灌注指标（乳酸、尿量）判断。"},{"when":"(vo2 / ((cao2 - cvo2) * 10) / bsa) >= 2.5 && (vo2 / ((cao2 - cvo2) * 10) / bsa) <= 4.0","level":"ok","text":"CI 2.5–4.0 L/min/m²：正常范围。"},{"when":"(vo2 / ((cao2 - cvo2) * 10) / bsa) > 4.0","level":"high","text":"CI >4.0：偏高，见于高动力状态（脓毒症、贫血、甲亢、动静脉瘘）。"}],"note":"热稀释法（Swan-Ganz）与 Fick 法互为参考；Hb、SaO₂ 与 VO₂ 的误差会显著影响结果。","refs":["中国心力衰竭诊断和治疗指南（2024）","2020 重症患者血流动力学监测与治疗中国专家共识","2021 ESC 急性心衰指南"]},{"id":"bsa_mosteller","name":"体表面积（Mosteller）","aka":["BSA Mosteller"],"cat":"血流动力学","rank":30,"desc":"按身高体重估算体表面积，用于心指数、化疗剂量与心功能指数校正。","inputs":[{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":5,"max":300,"step":0.1,"required":true},{"key":"height_cm","label":"身高","unit":"cm","type":"number","min":50,"max":230,"step":1,"required":true}],"formula":"BSA = √(身高 cm × 体重 kg / 3600)","compute":"bsa","interpret":[{"when":"v < 1.4","level":"low","text":"BSA <1.4 m²：多见于儿童或低体重患者，心指数/药物剂量需按实测计算。"},{"when":"v >= 1.4 && v <= 2.2","level":"ok","text":"BSA 1.4–2.2 m²：成人常见范围。"},{"when":"v > 2.2","level":"warn","text":"BSA >2.2 m²：超重体质，心指数用实测有效面积可能低估，必要时以无脂肪体重校正。"}],"note":"DuBois 公式：BSA = 0.007184 × W^0.425 × H^0.725（W kg，H cm）；国内多采用 Mosteller 或许文生公式。","refs":["中国心力衰竭诊断和治疗指南（2024）","Mosteller RD, N Engl J Med 1987"]},{"id":"shock_index","name":"休克指数（SI）","aka":["Shock Index","心率/收缩压比"],"cat":"血流动力学","rank":31,"desc":"心率与收缩压之比，用于快速识别失代偿、隐匿性休克与急性期风险。","inputs":[{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":40,"max":300,"step":1,"required":true}],"formula":"SI = HR / SBP","compute":"formula_only","algorithm":"function shockIndex(hr, sbp):\n  si = hr / sbp\n  return { v: si, tier: si < 0.5 ? '偏低' : (si <= 0.7 ? '正常' : (si <= 0.9 ? '升高' : (si <= 1.0 ? '显著升高' : '休克')) ) }\n// 改良休克指数 MSI = HR / MAP","interpret":[{"when":"v < 0.5","level":"low","text":"SI <0.5：偏低，见于窦缓或高收缩压；结合症状判断。"},{"when":"v >= 0.5 && v <= 0.7","level":"ok","text":"SI 0.5–0.7：正常范围。"},{"when":"v > 0.7 && v <= 0.9","level":"warn","text":"SI 0.71–0.9：升高，提示循环储备下降，警惕隐匿性低血容量/早期休克。"},{"when":"v > 0.9 && v <= 1.0","level":"high","text":"SI 0.91–1.0：显著升高，PTCA/创伤人群中提示预后不良，建议快速评估容量与灌注。"},{"when":"v > 1.0","level":"crit","text":"SI >1.0：达到休克水平，立即按休克流程启动复苏。"}],"note":"β 受体阻滞剂、起搏器患者心率不能代偿，SI 可能低估休克；需结合乳酸、尿量、毛细血管再充盈。","refs":["2020 重症患者血流动力学监测与治疗中国专家共识","2021 中国脓毒症/脓毒性休克急诊治疗指南","2023 ESC 急性冠脉综合征管理指南"]},{"id":"pulse_pressure","name":"脉压差","aka":["Pulse Pressure"],"cat":"血流动力学","rank":32,"desc":"收缩压与舒张压之差，反映大动脉僵硬度与每搏输出量。","inputs":[{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":40,"max":300,"step":1,"required":true},{"key":"dbp","label":"舒张压","unit":"mmHg","type":"number","min":20,"max":200,"step":1,"required":true}],"formula":"PP = SBP − DBP","compute":"formula_only","algorithm":"function pulsePressure(sbp, dbp):\n  return { v: sbp - dbp }\n// 正常参考 30–50 mmHg；≥60 mmHg 为脉压增宽（老年人动脉硬化典型）","interpret":[{"when":"v < 30","level":"low","text":"PP <30 mmHg：脉压减小，见于心输出量低、主动脉瓣狭窄、心包积液/压塞、休克。"},{"when":"v >= 30 && v <= 50","level":"ok","text":"PP 30–50 mmHg：正常范围。"},{"when":"v > 50 && v <= 60","level":"warn","text":"PP 51–60 mmHg：轻度增宽，注意动脉硬化与主动脉瓣反流。"},{"when":"v > 60","level":"high","text":"PP >60 mmHg：脉压增宽，老年常提示大动脉僵硬（独立心血管危险因素）；青少年/主动脉瓣反流/动静脉瘘也可见。"}],"note":"脉压增宽是老年人高血压的重要表型，收缩压升高而舒张压偏低者不宜过度降压。","refs":["中国高血压防治指南（2024 年修订版）","中国老年高血压管理指南（2023）"]},{"id":"rpp","name":"心率血压乘积（RPP）","aka":["Rate Pressure Product","双乘积"],"cat":"血流动力学","rank":33,"desc":"估算心肌耗氧量，评估心绞痛阈值与负荷试验反应。","inputs":[{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":40,"max":300,"step":1,"required":true}],"formula":"RPP = HR × SBP","compute":"formula_only","algorithm":"function rpp(hr, sbp):\n  return { v: hr * sbp }\n// 参考：静息 <10000 为低；>20000 为显著升高（高强度运动时可达 30000+）","interpret":[{"when":"v < 10000","level":"ok","text":"RPP <10000：静息心肌耗氧量低，心绞痛风险低。"},{"when":"v >= 10000 && v <= 20000","level":"warn","text":"RPP 10000–20000：中度升高，见于日常活动或轻型负荷。"},{"when":"v > 20000","level":"high","text":"RPP >20000：心肌耗氧显著增加，若在此水平出现缺血提示严重冠脉狭窄或需求过高。"}],"note":"RPP 数值越大表示心肌耗氧越多；负荷试验中记录出现缺血时的 RPP 可估计缺血阈值。","refs":["慢性冠脉综合征诊断和治疗指南（2024）","2021 AHA/ACC 胸痛评估与诊断指南"]},{"id":"stroke_volume_ef","name":"每搏输出量与射血分数（按体表面积）","aka":["SV/EF","每搏量指数"],"cat":"血流动力学","rank":34,"desc":"由 EDV 与 ESV 计算每搏量、射血分数与每搏量指数。","inputs":[{"key":"edv","label":"左室舒张末期容积 EDV","unit":"mL","type":"number","min":20,"max":500,"step":1,"required":true},{"key":"esv","label":"左室收缩末期容积 ESV","unit":"mL","type":"number","min":5,"max":400,"step":1,"required":true},{"key":"bsa","label":"体表面积 BSA","unit":"m²","type":"number","min":0.5,"max":3,"step":0.01,"required":true}],"formula":"SV = EDV − ESV；EF = SV / EDV × 100%；SVI = SV / BSA；CO = SV × HR","compute":"formula_only","algorithm":"function svEf(edv, esv, bsa):\n  if (esv >= edv) return { error: 'ESV 应小于 EDV' }\n  sv = edv - esv\n  ef = sv / edv * 100\n  svi = sv / bsa\n  tier = ef >= 50 ? '正常' : (ef >= 41 ? '轻度降低' : (ef >= 30 ? '中度降低' : '重度降低'))\n  return { v: Math.round(ef*10)/10, sv, svi, tier }","interpret":[{"when":"v >= 50","level":"ok","text":"EF ≥50%：收缩功能正常（注意 HFpEF 仍可存在舒张功能不全）。"},{"when":"v >= 41 && v < 50","level":"warn","text":"EF 41–49%：轻度降低（HFmrEF 下限），评估病因与是否进展。"},{"when":"v >= 30 && v < 41","level":"high","text":"EF 30–40%：中度降低，属 HFrEF，应启动四联治疗并评估 ICD 指征。"},{"when":"v < 30","level":"crit","text":"EF <30%：重度降低，猝死风险增高，评估 ICD/CRT、机械循环支持与移植适应证。"}],"note":"SVI 正常约 35–55 mL/m²（部分教材 30–65）。EF 是负荷依赖指标，且与 BSA 无关，故用 SVI 反映前向血流。","refs":["中国心力衰竭诊断和治疗指南（2024）","中国超声心动图测量与报告规范（2023）"]},{"id":"qtc_bazett","name":"QTc 校正（Bazett）","aka":["QTc Bazett"],"cat":"心电图","rank":35,"desc":"以 Bazett 公式按心率校正 QT 间期。","inputs":[{"key":"qt","label":"QT 间期","unit":"ms","type":"number","min":150,"max":700,"step":1,"required":true},{"key":"rr","label":"RR 间期","unit":"ms","type":"number","min":250,"max":2500,"step":1,"required":true,"hint":"60000 / 心率"}],"formula":"QTc = QT / √(RR/s)","compute":"formula_only","algorithm":"function qtcBazett(qtMs, rrMs):\n  if (rrMs <= 0) return { error: 'RR 必须 >0' }\n  qtc = qtMs / Math.sqrt(rrMs / 1000)\n  return { v: Math.round(qtc), tier: qtcTier(qtc) }\n// 分级：<450 正常；450-469 临界；470-499 延长；>=500 高危 TdP（女性临界/延长切点抬高 10 ms）","interpret":[{"when":"v >= 500","level":"crit","text":"QTc ≥500 ms：高度危险，TdP 风险显著升高，需心电监护、纠正 K⁺/Mg²⁺、停用致 QT 延长药物，必要时临时起搏提高心率。"},{"when":"v >= 470 && v < 500","level":"high","text":"QTc 470–499 ms：延长，需排查获得性/先天性长 QT，停用致 QT 延长药物并随访。"},{"when":"v >= 450 && v < 470","level":"warn","text":"QTc 450–469 ms（男）/460–469（女）：临界延长，检查电解质（K⁺、Mg²⁺）、药物与家族史。"},{"when":"v < 450","level":"ok","text":"QTc <450 ms：男性正常范围；女性 QTc <460 ms 亦为正常。"}],"note":"Bazett 在心动过速时高估、心动过缓时低估 QTc，推荐用 Fridericia 复核。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议（QT 部分）","2020 ESC 室性心律失常管理指南"]},{"id":"qtc_fridericia","name":"QTc 校正（Fridericia）","aka":["QTc Fridericia"],"cat":"心电图","rank":36,"desc":"以 Fridericia 公式（三次方根）校正 QT 间期，心动过速时更准确。","inputs":[{"key":"qt","label":"QT 间期","unit":"ms","type":"number","min":150,"max":700,"step":1,"required":true},{"key":"rr","label":"RR 间期","unit":"ms","type":"number","min":250,"max":2500,"step":1,"required":true}],"formula":"QTc = QT / ∛(RR/s)","compute":"formula_only","algorithm":"function qtcFridericia(qt, rr):\n  return { v: Math.round(qt / Math.cbrt(rr / 1000)) }\n// 分级同 QTc 通用阈值","interpret":[{"when":"v >= 500","level":"crit","text":"QTc ≥500 ms：TdP 高危，严密心电监护并纠正诱因。"},{"when":"v >= 470 && v < 500","level":"high","text":"QTc 470–499 ms：延长，停用可疑药物并监测。"},{"when":"v >= 450 && v < 470","level":"warn","text":"QTc 450–469 ms：临界，复查电解质与药物清单。"},{"when":"v < 450","level":"ok","text":"QTc <450 ms：正常或接近正常。"}],"note":"Fridericia 与心率相关性更好，是评估药物致 QT 延长的首选；四种公式结果差异大时取最保守值。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","2020 ESC 室性心律失常管理指南"]},{"id":"qtc_framingham","name":"QTc 校正（Framingham）","aka":["QTc Framingham"],"cat":"心电图","rank":37,"desc":"线性回归式 QTc，兼顾中间心率范围。","inputs":[{"key":"qt","label":"QT 间期","unit":"ms","type":"number","min":150,"max":700,"step":1,"required":true},{"key":"rr","label":"RR 间期","unit":"ms","type":"number","min":250,"max":2500,"step":1,"required":true}],"formula":"QTc = QT + 0.154 × (1000 − RR)","compute":"formula_only","algorithm":"function qtcFramingham(qt, rr):\n  return { v: Math.round(qt + 0.154 * (1000 - rr)) }\n// RR 单位 ms","interpret":[{"when":"v >= 500","level":"crit","text":"QTc ≥500 ms：TdP 高危，严密心电监护并纠正诱因。"},{"when":"v >= 470 && v < 500","level":"high","text":"QTc 470–499 ms：延长，停用可疑药物并监测。"},{"when":"v >= 450 && v < 470","level":"warn","text":"QTc 450–469 ms：临界，复查电解质与药物清单。"},{"when":"v < 450","level":"ok","text":"QTc <450 ms：正常或接近正常。"}],"note":"Framingham 线性式在心动过缓时较少低估 QTc，国内常用于药物致 QT 延长监测。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","2022 中国药物致 QT 间期延长与 TdP 防治专家共识"]},{"id":"qtc_hodges","name":"QTc 校正（Hodges）","aka":["QTc Hodges"],"cat":"心电图","rank":38,"desc":"以心率为自变量的线性 QTc 公式。","inputs":[{"key":"qt","label":"QT 间期","unit":"ms","type":"number","min":150,"max":700,"step":1,"required":true},{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true}],"formula":"QTc = QT + 1.75 × (HR − 60)","compute":"formula_only","algorithm":"function qtcHodges(qt, hr):\n  return { v: Math.round(qt + 1.75 * (hr - 60)) }\n// 分级同 QTc 通用阈值","interpret":[{"when":"v >= 500","level":"crit","text":"QTc ≥500 ms：TdP 高危，严密心电监护并纠正诱因。"},{"when":"v >= 470 && v < 500","level":"high","text":"QTc 470–499 ms：延长，停用可疑药物并监测。"},{"when":"v >= 450 && v < 470","level":"warn","text":"QTc 450–469 ms：临界，复查电解质与药物清单。"},{"when":"v < 450","level":"ok","text":"QTc <450 ms：正常或接近正常。"}],"note":"Hodges 公式以心率为自变量，心率本身测量误差会放大到 QTc。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","2022 中国药物致 QT 间期延长与 TdP 防治专家共识"]},{"id":"qtc_interpret","name":"QTc 判读标准","aka":["QTc 阈值","QT 延长判读"],"cat":"心电图","rank":39,"desc":"统一 QTc 分级阈值与临床处理要点。","inputs":[],"compute":"formula_only","interpret":[{"when":"v >= 500","level":"crit","text":"QTc ≥500 ms，或伴晕厥/TdP：高危，立即心电监护、停致 QT 药物、纠正 K⁺/Mg²⁺，先天性长 QT 考虑 β 阻滞剂。"},{"when":"v >= 460 && v < 500","level":"high","text":"QTc 460–499 ms（女 ≥480），或较基线增加 ≥60 ms：延长，处置诱因并随访复查。"},{"when":"v >= 440 && v < 460","level":"warn","text":"男性 440–459 ms、女性 460–479 ms：临界延长，复查电解质与用药清单。"},{"when":"v < 440","level":"ok","text":"男性 QTc <440 ms、女性 <460 ms：正常。"}],"levels":[{"label":"正常","criteria":"男性 QTc <440 ms，女性 QTc <460 ms","level":"ok"},{"label":"临界延长","criteria":"男性 440–459 ms，女性 460–479 ms","level":"warn"},{"label":"延长","criteria":"QTc ≥460 ms（男）/ ≥480 ms（女）；或较基线增加 ≥60 ms","level":"high"},{"label":"高危","criteria":"QTc ≥500 ms，或伴晕厥、TdP、T-U 融合/电交替；先天性长 QT 需考虑 β 阻滞剂","level":"crit"}],"note":"使用 QT 最长导联且排除 U 波；电解质（K⁺、Mg²⁺、Ca²⁺）、药物（胺碘酮、喹诺酮、大环内酯、抗真菌药、抗精神病药）与心动过缓是关键诱因。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","2022 中国药物致 QT 间期延长与 TdP 防治专家共识"]},{"id":"rr_to_hr","name":"心率换算（RR 间期→心率）","aka":["RR 间期换算心率"],"cat":"心电图","rank":40,"desc":"由 RR 间期换算心率，以及房颤时 6 秒法估算心室率。","inputs":[{"key":"rr","label":"RR 间期","unit":"ms","type":"number","min":200,"max":3000,"step":1,"required":true},{"key":"beats6s","label":"6 秒内 QRS 波个数（可选，房颤用）","unit":"个","type":"number","min":0,"max":40,"step":1,"required":false}],"formula":"HR = 60000 / RR（ms）；6 秒法：HR ≈ 6 秒内 QRS 数 × 10","compute":"formula_only","algorithm":"function rrToHr(rrMs, beats6s):\n  hr = 60000 / rrMs\n  hr2 = beats6s ? beats6s * 10 : null\n  return { v: Math.round(hr), v2: hr2, tier: hr < 60 ? '心动过缓' : (hr <= 100 ? '正常' : '心动过速') }","interpret":[{"when":"v < 60","level":"low","text":"<60 次/分：心动过缓，结合症状与窦房结/房室传导功能评估。"},{"when":"v >= 60 && v <= 100","level":"ok","text":"60–100 次/分：正常静息心率。"},{"when":"v > 100 && v <= 150","level":"warn","text":"101–150 次/分：心动过速，鉴别窦速、房颤、室上速、房扑 2:1 传导。"},{"when":"v > 150","level":"crit","text":">150 次/分：明显心动过速，警惕室速/室上速，需心电监护与鉴别。"}],"note":"1 大格 = 300/大格数；小格法 1500/RR 小格数。房颤不规则时用 6 秒法。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","2020 ESC 室性心律失常管理指南"]},{"id":"axis_calc","name":"额面心电轴计算","aka":["QRS 电轴","Axis"],"cat":"心电图","rank":41,"desc":"由 I 与 aVF 导联 QRS 主波方向判断额面电轴。","inputs":[{"key":"lead1","label":"I 导联净振幅（正/负）","type":"select","options":[{"value":1,"label":"主波向上"},{"value":-1,"label":"主波向下"}],"required":true},{"key":"lead2","label":"II 导联净振幅","type":"select","options":[{"value":1,"label":"主波向上"},{"value":-1,"label":"主波向下"}],"required":true},{"key":"lead_avf","label":"aVF 导联净振幅","type":"select","options":[{"value":1,"label":"主波向上"},{"value":-1,"label":"主波向下"}],"required":true}],"formula":"I 向上 + aVF 向上 = 正常（−30°~+90°）；I 向上 + aVF 向下 = 电轴左偏（需 II 导联区分）；I 向下 + aVF 向上 = 右偏；均向下 = 极度右偏","compute":"formula_only","algorithm":"function axis(l1, l2, avf):\n  if (l1 > 0 && avf > 0) return l2 > 0 ? '正常（-30°~+90°）' : '轻度左偏（0°~-30°，多属正常）'\n  if (l1 > 0 && avf < 0) return '电轴左偏（<-30°）'\n  if (l1 < 0 && avf > 0) return '电轴右偏（+90°~+180°）'\n  return '极度右偏（西北轴，-90°~-180°）'","interpret":[{"when":"lead1 == 1 && lead_avf == 1","level":"ok","text":"I、aVF 均向上：电轴正常（约 −30°~+90°）。"},{"when":"lead1 == 1 && lead_avf == -1 && lead2 == 1","level":"warn","text":"I 向上、aVF 向下、II 向上：电轴 0°~−30°，多数为生理性，无需处理。"},{"when":"lead1 == 1 && lead_avf == -1 && lead2 == -1","level":"high","text":"电轴左偏（<−30°）：见于左前分支阻滞、左室肥厚、下壁心梗、起搏等。"},{"when":"lead1 == -1 && lead_avf == 1","level":"high","text":"电轴右偏（>+90°）：见于右室肥厚、左后分支阻滞、侧壁心梗、瘦高体型。"},{"when":"lead1 == -1 && lead_avf == -1","level":"crit","text":"极度右偏/西北轴：见于室速、严重右心负荷或导联错接，须结合临床。"}],"note":"更精确：用 I 与 aVF 的净振幅查表/三角函数求角度；此三分类法适合快速判读。","refs":["2017 AHA/ACCF/HRS 心电图标准化与解读建议","黄宛临床心电图学（第 6 版）"]},{"id":"bp_classify_cn2024","name":"血压分级（中国 2024 指南）","aka":["血压分级","高血压诊断标准"],"cat":"血压","rank":42,"desc":"按诊室血压对成人血压水平分级。","inputs":[{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":50,"max":300,"step":1,"required":true},{"key":"dbp","label":"舒张压","unit":"mmHg","type":"number","min":20,"max":200,"step":1,"required":true}],"formula":"按 SBP 与 DBP 较高者定级；诊室血压 ≥140/90 mmHg 诊断高血压","compute":"formula_only","algorithm":"function bpClass(sbp, dbp):\n  // SBP 与 DBP 较高者定级\n  if (sbp >= 180 || dbp >= 110) return '3 级高血压（重度）'\n  if (sbp >= 160 || dbp >= 100) return '2 级高血压（中度）'\n  if (sbp >= 140 || dbp >= 90)  return '1 级高血压（轻度）'\n  if (sbp >= 120 || dbp >= 80)  return '正常高值'\n  return (sbp < 90 || dbp < 60) ? '低血压' : '正常血压'\n// 中国高血压防治指南 2024：诊断切点 140/90；家庭 135/85、24h 动态 130/80","interpret":[{"when":"sbp >= 180 || dbp >= 110","level":"crit","text":"3 级高血压（≥180/110）：立即评估靶器官损害，排除高血压急症。"},{"when":"sbp >= 160 || dbp >= 100","level":"high","text":"2 级高血压（160–179/100–109）：启动药物治疗 + 生活方式干预。"},{"when":"sbp >= 140 || dbp >= 90","level":"warn","text":"1 级高血压（140–159/90–99）：3–6 个月生活方式干预未达标即启动药物。"},{"when":"sbp >= 120 || dbp >= 80","level":"warn","text":"正常高值（120–139/80–89）：非药物干预为主，合并高危因素者评估早期用药。"},{"when":"sbp < 90 || dbp < 60","level":"low","text":"低于 90/60：低血压，评估症状、容量与药物因素。"},{"when":"sbp >= 90 && dbp >= 60 && sbp < 120 && dbp < 80","level":"ok","text":"正常血压（<120/80 mmHg）：保持健康生活方式，定期监测。"}],"note":"中国高血压防治指南 2024 年修订版：诊断切点仍为 ≥140/90 mmHg；家庭血压 ≥135/85、动态 24 h ≥130/80 亦为高血压。美国 2017 指南已降至 130/80。","refs":["中国高血压防治指南（2024 年修订版）","2024 ESC 血压升高与高血压管理指南"]},{"id":"hbp_risk_strat","name":"高血压心血管危险分层","aka":["高血压危险分层"],"cat":"血压","rank":43,"desc":"结合血压分级、危险因素、靶器官损害与合并症确定危险度。","inputs":[{"key":"bp_grade","label":"血压分级","type":"select","options":[{"value":1,"label":"正常高值"},{"value":2,"label":"1 级"},{"value":3,"label":"2 级"},{"value":4,"label":"3 级"}],"required":true},{"key":"rf","label":"危险因素个数（吸烟、血脂异常、糖耐量异常、肥胖、早发心血管病家族史等）","unit":"个","type":"number","min":0,"max":6,"step":1,"required":true},{"key":"tod","label":"靶器官损害（LVH、eGFR 下降、微量白蛋白尿、PWV 增高等）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"disease","label":"临床合并症（脑血管病、冠心病、心衰、CKD ≥3 期、糖尿病伴靶器官损害）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"按「血压分级 × 危险因素数/靶器官损害/合并症」二维表定级：低危 / 中危 / 高危 / 很高危","compute":"formula_only","algorithm":"// 中国高血压指南危险分层表（简化）\nfunction hbpRisk(bpGrade, rf, tod, disease):\n  if (disease === 1 || bpGrade === 4) return '很高危'\n  if (tod === 1 || rf >= 3) return bpGrade >= 2 ? '很高危' : '高危'\n  if (rf === 0) return bpGrade === 1 ? '低危' : (bpGrade === 2 ? '中危' : '高危')\n  if (rf <= 2) return bpGrade === 1 ? '中危' : '高危'\n  return '高危'\n// 说明：3 级高血压不论危险因素数均为高危起步，伴合并症时很高危","interpret":[{"when":"bp_grade >= 4 || disease == 1","level":"crit","text":"很高危：3 级高血压或合并临床疾病（冠心病/卒中/心衰/CKD），立即联合药物治疗，目标 <130/80 mmHg 并同时启用他汀。"},{"when":"tod == 1 || rf >= 3","level":"high","text":"高危：有靶器官损害或 ≥3 个危险因素，立即启动药物治疗 + 生活方式干预。"},{"when":"rf >= 1","level":"warn","text":"中危：1–2 个危险因素，生活方式干预 1 个月未达标即启动药物。"},{"when":"bp_grade >= 2","level":"high","text":"2 级高血压无其他危险因素：仍为高危，立即药物治疗。"},{"when":"bp_grade == 1 && rf == 0 && tod == 0 && disease == 0","level":"low","text":"正常高值且无危险因素：低危，生活方式干预并每年复评。"}],"note":"危险分层决定启动药物时机与目标：低危可生活方式干预 3 个月，高危/很高危需立即药物 + 联合治疗。","refs":["中国高血压防治指南（2024 年修订版）","2024 ESC 血压升高与高血压管理指南"]},{"id":"wch_masked_htn","name":"白大衣/隐匿性高血压判断","aka":["WCH","masked hypertension"],"cat":"血压","rank":44,"desc":"比较诊室血压与家庭/动态血压，判断白大衣性高血压与隐匿性高血压。","inputs":[{"key":"office","label":"诊室血压（收缩压）","unit":"mmHg","type":"number","min":80,"max":260,"step":1,"required":true},{"key":"home","label":"家庭血压（收缩压平均）","unit":"mmHg","type":"number","min":70,"max":260,"step":1,"required":true},{"key":"abpm_day","label":"动态白天平均收缩压（可选）","unit":"mmHg","type":"number","min":70,"max":260,"step":1,"required":false}],"formula":"诊室 ≥140 且家庭 <135（或动态日间 <135）→ 白大衣性高血压；诊室 <140 且家庭 ≥135（或日间 ≥135）→ 隐匿性高血压","compute":"formula_only","algorithm":"function wch(office, home, abpmDay):\n  const out = abpmDay ? abpmDay : home\n  const officeHigh = office >= 140\n  const outHigh = out >= 135\n  if (officeHigh && !outHigh) return '白大衣性高血压'\n  if (!officeHigh && outHigh) return '隐匿性高血压'\n  if (officeHigh && outHigh) return '持续性高血压'\n  return '血压正常'\n// 动态夜间 ≥120 亦提示隐匿/夜间高血压","interpret":[{"when":"office >= 140 && home < 135","level":"warn","text":"白大衣性高血压：诊室高、诊室外正常（约 15%–30% 诊室高血压者）；需随访，每年复查动态血压，合并靶器官损害者考虑治疗。"},{"when":"office < 140 && home >= 135","level":"high","text":"隐匿性高血压：诊室外高、诊室正常，心血管风险接近持续性高血压，应启动降压治疗并强化监测。"},{"when":"office >= 140 && home >= 135","level":"high","text":"持续性高血压：诊室与诊室外均高，按指南规范治疗。"},{"when":"office < 140 && home < 135","level":"ok","text":"血压正常范围：保持生活方式，定期监测。"}],"note":"家庭血压阈值 135/85，动态 24 h 130/80、日间 135/85、夜间 120/70 mmHg。白大衣高血压仍需评估靶器官损害。","refs":["中国高血压防治指南（2024 年修订版）","中国家庭血压监测指南（2019）","2024 ESC 血压升高与高血压管理指南"]},{"id":"orthostatic_hypotension","name":"体位性低血压判断（卧立位血压差）","aka":["Orthostatic hypotension","直立性低血压"],"cat":"血压","rank":45,"desc":"对比卧位与立位（或坐位转站立）血压，判断体位性低血压。","inputs":[{"key":"sbp_sup","label":"卧位收缩压","unit":"mmHg","type":"number","min":50,"max":260,"step":1,"required":true},{"key":"dbp_sup","label":"卧位舒张压","unit":"mmHg","type":"number","min":20,"max":160,"step":1,"required":true},{"key":"sbp_stand","label":"站立 3 min 收缩压","unit":"mmHg","type":"number","min":40,"max":260,"step":1,"required":true},{"key":"dbp_stand","label":"站立 3 min 舒张压","unit":"mmHg","type":"number","min":20,"max":160,"step":1,"required":true}],"formula":"ΔSBP = 卧位 − 立位；ΔDBP = 卧位 − 立位；ΔSBP ≥20 mmHg 或 ΔDBP ≥10 mmHg 诊断体位性低血压","compute":"formula_only","algorithm":"function ortho(sbpSup, dbpSup, sbpStand, dbpStand):\n  const dSbp = sbpSup - sbpStand\n  const dDbp = dbpSup - dbpStand\n  if (dSbp >= 20 || dDbp >= 10) return '体位性低血压'\n  if (dSbp >= 10 || dDbp >= 5)  return '临界（需复查）'\n  return '未见体位性低血压'\n// 卧位测于卧 5 min 以上；站立后 1 min 与 3 min 各测一次","interpret":[{"when":"sbp_sup - sbp_stand >= 20 || dbp_sup - dbp_stand >= 10","level":"high","text":"符合体位性低血压：评估容量、药物（α 阻滞剂、利尿剂、三环类、硝酸酯）、糖尿病/帕金森/自主神经病变；老年注意跌倒。"},{"when":"sbp_sup - sbp_stand >= 10","level":"warn","text":"ΔSBP 10–19 mmHg：临界，建议重复测量（站立 1 与 3 min 各测一次）。"},{"when":"sbp_sup - sbp_stand < 10 && dbp_sup - dbp_stand < 5","level":"ok","text":"未见体位性低血压（<10/5 mmHg 下降）。"}],"note":"另需评估餐后低血压（餐后 2 h 内 SBP 降 ≥20 mmHg）与卧位高血压伴立位低血压（M 型）。","refs":["中国老年高血压管理指南（2023）","2018 中国高血压防治指南（站位血压测量）","2024 ESC 血压升高与高血压管理指南"]},{"id":"ckdepi_2021","name":"eGFR（CKD-EPI 2021，肌酐）","aka":["CKD-EPI 2021","eGFR 2021"],"cat":"肾功能","rank":46,"desc":"无种族系数的 eGFR 公式，心血管药物剂量调整与预后分层。","inputs":[{"key":"scr","label":"血肌酐","unit":"μmol/L","type":"number","min":10,"max":2000,"step":1,"required":true,"hint":"mg/dL = μmol/L ÷ 88.4"},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"女（1）"},{"value":1,"label":"男（2）"}],"required":true}],"formula":"eGFR = 142 × min(Scr/κ,1)^α × max(Scr/κ,1)^(−1.200) × 0.9938^年龄 × 1.012（女）；κ=0.7（女）/0.9（男），α=−0.241（女）/−0.302（男）","compute":"egfr_ckdepi","interpret":[{"when":"v >= 90","level":"ok","text":"eGFR ≥90 mL/min/1.73m²：肾功能正常（G1），但需尿白蛋白评估是否 CKD。"},{"when":"v >= 60 && v < 90","level":"warn","text":"60–89：G2 轻度下降，多数 NOAC 可常规剂量（具体看说明书体重/年龄标准）。"},{"when":"v >= 30 && v < 60","level":"high","text":"30–59：G3 中重度下降，NOAC/ACEI/MRA 需减量或谨慎使用，MRA 在 eGFR <30 禁用。"},{"when":"v >= 15 && v < 30","level":"crit","text":"15–29：G4 重度下降，多数 NOAC 减量或慎用，评估肾脏替代治疗时机。"},{"when":"v < 15","level":"crit","text":"<15：G5 终末期，透析患者抗凝需专门评估（华法林为主）。"}],"note":"CKD-EPI 2021 去种族项，FDA/NKF 推荐替代 2009 版；肌酐仍偏重肌肉量，肌少症患者可能高估。eGFR <60 持续 3 个月定义 CKD。","refs":["2021 CKD-EPI 肌酐方程（Inker LA, NEJM 2021）","KDIGO 2012/2024 CKD 评估与管理指南","中国慢性肾脏病早期评价与管理指南（2023）"]},{"id":"cockcroft_gault","name":"肌酐清除率（Cockcroft-Gault）","aka":["CrCl Cockcroft-Gault","CG 公式"],"cat":"肾功能","rank":47,"desc":"NOAC、抗生素等药物说明书常用的 CrCl 计算。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":20,"max":300,"step":0.1,"required":true,"hint":"肥胖/偏低体重时宜用理想体重"},{"key":"scr","label":"血肌酐","unit":"mg/dL","type":"number","min":0.1,"max":20,"step":0.01,"required":true,"hint":"μmol/L ÷ 88.4"},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"女"},{"value":1,"label":"男"}],"required":true}],"formula":"CrCl = (140 − 年龄) × 体重 / (72 × Scr mg/dL)，女性 ×0.85","compute":"crcl_cockcroft","interpret":[{"when":"v >= 80","level":"ok","text":"CrCl ≥80：多数 NOAC 可按全剂量使用。"},{"when":"v >= 50 && v < 80","level":"warn","text":"50–79：达比加群（若伴其他出血危险因素）、利伐沙班等需核查说明书减量条件。"},{"when":"v >= 30 && v < 50","level":"high","text":"30–49：达比加群/艾多沙班/利伐沙班多需减量（艾多沙班 vs 利伐沙班规则不同），ACEI/MRA 需监测。"},{"when":"v >= 15 && v < 30","level":"crit","text":"15–29：多数 NOAC 禁用或严格减量，剂量必须遵说明书。"},{"when":"v < 15","level":"crit","text":"<15（或透析）：NOAC 多禁用；华法林为常规选择。"}],"note":"药物剂量以说明书规定的公式为准（NOAC 多用 CG）。理想体重：男 = 50 + 0.9×(身高 cm − 152)，女 = 45.5 + 0.9×(身高 cm − 152)。","refs":["房颤抗凝中国专家共识（2019）","各 NOAC 中文说明书（达比加群酯/利伐沙班/阿哌沙班/艾多沙班）","中国慢性肾脏病早期评价与管理指南（2023）"]},{"id":"mdrd_egfr","name":"eGFR（MDRD 研究方程）","aka":["MDRD","eGFR MDRD"],"cat":"肾功能","rank":48,"desc":"经典 MDRD 方程，旧报告与文献对照用。","inputs":[{"key":"scr","label":"血肌酐","unit":"μmol/L","type":"number","min":10,"max":2000,"step":1,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"女"},{"value":1,"label":"男"}],"required":true}],"formula":"eGFR = 175 × Scr(mg/dL)^−1.154 × 年龄^−0.203 × 0.742（女）","compute":"formula_only","algorithm":"function mdrd(scrUmol, age, sex):\n  const scr = scrUmol / 88.4\n  let egfr = 175 * Math.pow(scr, -1.154) * Math.pow(age, -0.203)\n  if (sex === 0) egfr *= 0.742\n  return { v: Math.round(egfr) }\n// 中国四变量 MDRD 校正：× 1.233（CKD 中国人群）","interpret":[{"when":"v >= 90","level":"ok","text":"≥90：正常范围（需结合尿检）。"},{"when":"v >= 60 && v < 90","level":"warn","text":"60–89：轻度下降。"},{"when":"v >= 30 && v < 60","level":"high","text":"30–59：中重度下降，药物剂量需调整。"},{"when":"v < 30","level":"crit","text":"<30：重度下降，评估替代治疗与用药禁忌。"}],"note":"MDRD 在 eGFR >60 时低估，已被 CKD-EPI 2021 取代；仅用于历史数据解读。","refs":["KDIGO 2012 CKD 指南","中国慢性肾脏病早期评价与管理指南（2023）"]},{"id":"china_par_ascvd","name":"China-PAR 10 年 ASCVD 风险","aka":["China-PAR","中国动脉粥样硬化性心血管病风险"],"cat":"血脂","rank":49,"desc":"中国人群 ASCVD 10 年发病风险预测，决定他汀起始与 LDL-C 目标。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":20,"max":99,"step":1,"required":true},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"女"},{"value":1,"label":"男"}],"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":70,"max":260,"step":1,"required":true},{"key":"tc","label":"总胆固醇 TC","unit":"mmol/L","type":"number","min":1.5,"max":15,"step":0.01,"required":true},{"key":"hdl","label":"HDL-C","unit":"mmol/L","type":"number","min":0.3,"max":4,"step":0.01,"required":true},{"key":"smoke","label":"现在吸烟","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"dm","label":"糖尿病","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"China-PAR：先算个体「均值差」(X-mean)/s 的回归和，得到危险评分，再换算 10 年 ASCVD 风险百分比","compute":"formula_only","algorithm":"// China-PAR 模型（Yang X et al., Circulation 2016）\nfunction chinaPar(age, sex, sbp, tc, hdl, smoke, dm, regionNorth, urban, bmi, wc, fh):\n  // 男女分模型；系数取自发表模型表\n  // 男性：ln(年龄)×12.05057 + ln(TC)×1.12925 + ln(HDL)×(-0.93046) + ln(SBP)×2.08106\n  //   + 吸烟×0.46652 + 糖尿病×0.59345 + (北)×0.30819 + (城市)×0.23493 + ln(WC)×0.86849 + (家族史)×0.29505\n  // 女性：ln(年龄)×12.77513 + ... 系数见原文表 2\n  Sum = Σ coef_i × (x_i - mean_i)/sd_i\n  risk10 = 1 - 0.994^exp(Sum)   // 基线生存率模型\n  return { v: risk10 * 100 }\n// 分级：<5% 低危；5%–9.9% 中危；>=10% 高危；ASCVD 患者为极高危","interpret":[{"when":"v < 5","level":"ok","text":"10 年风险 <5%（低危）：生活方式干预为主，LDL-C 目标 <3.4 mmol/L。"},{"when":"v >= 5 && v < 10","level":"warn","text":"5%–9.9%（中危）：LDL-C 目标 <2.6 mmol/L，考虑中等强度他汀。"},{"when":"v >= 10","level":"high","text":"≥10%（高危）：LDL-C 目标 <1.8 mmol/L 且降幅 ≥50%，启动他汀（必要时联合依折麦布/PCSK9i）。"}],"note":"China-PAR 完整模型还需南北地区、城乡、腰围、家族史等变量；本界面仅为简化示例。极高危（已患 ASCVD）者 LDL-C 目标 <1.4 mmol/L 且降幅 ≥50%。","refs":["中国血脂管理指南（2023 年）","中国心血管病风险评估和管理指南（2019）","Yang X, Circulation 2016（China-PAR 模型）"]},{"id":"ldl_target","name":"LDL-C 目标值判定","aka":["LDL-C 目标","降脂达标判定"],"cat":"血脂","rank":50,"desc":"按 ASCVD 危险分层确定 LDL-C 目标并判断是否达标。","inputs":[{"key":"risk","label":"ASCVD 危险分层","type":"select","options":[{"value":1,"label":"低危"},{"value":2,"label":"中危"},{"value":3,"label":"高危"},{"value":4,"label":"超高危"},{"value":5,"label":"极高危"}],"required":true},{"key":"ldl","label":"当前 LDL-C","unit":"mmol/L","type":"number","min":0.1,"max":15,"step":0.01,"required":true},{"key":"ldl_base","label":"基线 LDL-C（可选，用于降幅判断）","unit":"mmol/L","type":"number","min":0.1,"max":15,"step":0.01,"required":false}],"formula":"低危 <3.4；中危 <2.6；高危 <1.8 且降幅 ≥50%；超高危 <1.4 且降幅 ≥50%；极高危 <1.0","compute":"formula_only","algorithm":"function ldlTarget(risk, ldl, ldlBase):\n  const target = {1:3.4, 2:2.6, 3:1.8, 4:1.4, 5:1.0}[risk]\n  const reach = ldl < target\n  const dropOk = ldlBase ? (1 - ldl / ldlBase) >= 0.5 : null\n  return { target, reach, dropOk, ok: reach && (dropOk !== false) }","interpret":[{"when":"risk >= 5 && ldl < 1.0","level":"ok","text":"极高危且 LDL-C <1.0 mmol/L：达标。"},{"when":"risk == 4 && ldl < 1.4","level":"ok","text":"超高危且 LDL-C <1.4 mmol/L：达标，注意仍需较基线降幅 ≥50%。"},{"when":"risk == 3 && ldl < 1.8","level":"ok","text":"高危且 LDL-C <1.8 mmol/L：达标（需降幅 ≥50%）。"},{"when":"risk == 2 && ldl < 2.6","level":"ok","text":"中危且 LDL-C <2.6 mmol/L：达标。"},{"when":"risk == 1","level":"ok","text":"低危且 LDL-C <3.4 mmol/L：达标。"},{"when":"risk == 1 && ldl >= 3.4","level":"high","text":"低危但 LDL-C ≥3.4 mmol/L：未达标，启动中等强度他汀 + 生活方式干预。"},{"when":"risk >= 2","level":"high","text":"未达所选分层目标：强化他汀（必要时联合依折麦布/PCSK9 抑制剂）并确认较基线降幅是否 ≥50%。"}],"note":"注意本判读规则按 LDL-C 强度排序给出提示，具体达标以所选分层为准；2019 ESC 使用「极高危 <1.4、高危 <1.8」两档，中国 2023 指南分四档。","refs":["中国血脂管理指南（2023 年）","2019 ESC/EAS 血脂异常管理指南","中国胆固醇教育计划调脂治疗降低心血管事件专家建议（2023）"]},{"id":"friedewald_ldl","name":"LDL-C 计算（Friedewald）","aka":["Friedewald 公式"],"cat":"血脂","rank":51,"desc":"由 TC、HDL-C、TG 估算 LDL-C。","inputs":[{"key":"tc","label":"总胆固醇 TC","unit":"mmol/L","type":"number","min":1,"max":20,"step":0.01,"required":true},{"key":"hdl","label":"HDL-C","unit":"mmol/L","type":"number","min":0.2,"max":5,"step":0.01,"required":true},{"key":"tg","label":"甘油三酯 TG","unit":"mmol/L","type":"number","min":0.1,"max":30,"step":0.01,"required":true}],"formula":"LDL-C = TC − HDL-C − TG/2.2（mmol/L）；TG >4.5 mmol/L 时不适用","compute":"formula_only","algorithm":"function friedewald(tc, hdl, tg):\n  if (tg > 4.5) return { error: 'TG >4.5 mmol/L，Friedewald 不可靠，改用 Martin-Hopkins 或直接测定' }\n  return { v: Math.round((tc - hdl - tg / 2.2) * 100) / 100 }","interpret":[{"when":"tg > 4.5","level":"warn","text":"TG >4.5 mmol/L：Friedewald 明显低估 LDL-C，改用 Martin-Hopkins 公式或直接匀相法测定。"},{"when":"tc - hdl - tg / 2.2 < 1.4","level":"ok","text":"LDL-C <1.4 mmol/L：达超高危目标。"},{"when":"tc - hdl - tg / 2.2 >= 1.4 && tc - hdl - tg / 2.2 < 1.8","level":"ok","text":"LDL-C <1.8 mmol/L：达高危目标。"},{"when":"tc - hdl - tg / 2.2 >= 1.8 && tc - hdl - tg / 2.2 < 2.6","level":"warn","text":"LDL-C 1.8–2.6 mmol/L：仅达中危目标；高危以上未达标。"},{"when":"tc - hdl - tg / 2.2 >= 2.6 && tc - hdl - tg / 2.2 < 3.4","level":"warn","text":"LDL-C 2.6–3.4 mmol/L：仅低危达标。"},{"when":"tc - hdl - tg / 2.2 >= 3.4","level":"high","text":"LDL-C ≥3.4 mmol/L：启动/强化他汀，必要时联合依折麦布或 PCSK9 抑制剂。"}],"note":"TG 高、Lp(a) 高、糖尿病时 Friedewald 误差大；直接测定法或 Martin-Hopkins 更准确。","refs":["中国血脂管理指南（2023 年）","2021 AHA/ACC 多学科胆固醇管理指南"]},{"id":"martin_hopkins_ldl","name":"LDL-C 计算（Martin-Hopkins）","aka":["Martin-Hopkins 公式"],"cat":"血脂","rank":52,"desc":"按非 HDL-C 分层选择除数，高 TG 时更准确的 LDL-C 估算。","inputs":[{"key":"tc","label":"总胆固醇 TC","unit":"mmol/L","type":"number","min":1,"max":20,"step":0.01,"required":true},{"key":"hdl","label":"HDL-C","unit":"mmol/L","type":"number","min":0.2,"max":5,"step":0.01,"required":true},{"key":"tg","label":"甘油三酯 TG","unit":"mmol/L","type":"number","min":0.1,"max":30,"step":0.01,"required":true}],"formula":"LDL-C = TC − HDL-C − TG/除数；除数按 TG(mg/dL) 分档查表（3.0–4.4 取 3.4 至 TG 400–499 取 6.9）","compute":"formula_only","algorithm":"function martinHopkins(tc, hdl, tgMmol):\n  const nonHdl = tc - hdl\n  const tg = tgMmol * 88.57   // 转 mg/dL\n  const table = [[0,3.5],[100,3.6],[150,3.8],[200,4.0],[250,4.3],[300,4.5],[350,4.7]]\n  // 原文除数表（mg/dL 分档）\n  const divByTg = (tg) => tg < 100 ? 3.5 : tg < 150 ? 3.6 : tg < 200 ? 3.8 : tg < 250 ? 4.0 : tg < 300 ? 4.3 : tg < 350 ? 4.5 : 4.7\n  // 更精确表还按 nonHDL-C 再分档，见原文表\n  return { v: Math.round((nonHdl - tgMmol / divByTg(tg)) * 100) / 100 }\n// 粗版：LDL-C = nonHDL-C − TG(mmol/L) / 2.2（TG<1.7 近似 Friedewald）","interpret":[{"when":"tc - hdl - tg / 2.2 < 1.4","level":"ok","text":"估算 LDL-C <1.4 mmol/L：达超高危目标。"},{"when":"tc - hdl - tg / 2.2 < 1.8","level":"ok","text":"估算 LDL-C <1.8 mmol/L：达高危目标。"},{"when":"tc - hdl - tg / 2.2 >= 1.8 && tc - hdl - tg / 2.2 < 2.6","level":"warn","text":"估算 LDL-C 1.8–2.6 mmol/L：仅达中危目标。"},{"when":"tc - hdl - tg / 2.2 >= 2.6","level":"high","text":"估算 LDL-C ≥2.6 mmol/L：未达高危目标，需强化降脂。"}],"note":"Martin-Hopkins 在 TG >4.5 mmol/L 时优于 Friedewald；本界面用简化除数提示，精确计算请按原表。","refs":["中国血脂管理指南（2023 年）","Martin SS et al., JAMA 2013"]},{"id":"mi_infarct_size","name":"心肌梗死面积估算","aka":["MI size","梗死面积"],"cat":"ACS","rank":53,"desc":"按 STEMI 危险区域与 Selvester QRS 评分估算梗死面积/心肌挽救比例。","inputs":[{"key":"selvester","label":"Selvester QRS 评分","unit":"分","type":"number","min":0,"max":32,"step":1,"required":true,"hint":"每分约对应 3% 左室质量"},{"key":"aart","label":"AAR（危险区域，由 ST 抬高导联估算）","unit":"%左室","type":"number","min":0,"max":80,"step":1,"required":false}],"formula":"梗死面积（%左室）≈ Selvester 评分 × 3%；心肌挽救比例 = (AAR − 梗死面积) / AAR","compute":"formula_only","algorithm":"function infarctSize(selvester, aar):\n  const infarctPct = Math.min(selvester * 3, 100)\n  const salvage = aar ? Math.max(0, (aar - infarctPct) / aar * 100) : null\n  return { v: infarctPct, salvage: salvage }\n// 同法可用 CT 延迟强化（%LV mass）或心脏磁共振区分梗死/水肿面积","interpret":[{"when":"v < 15","level":"ok","text":"梗死面积 <15% 左室：较小梗死，心功能代偿可能性大。"},{"when":"v >= 15 && v < 30","level":"warn","text":"15%–29%：中等梗死，注意重构与左心功能。"},{"when":"v >= 30","level":"crit","text":"≥30%：大面积梗死，心源性休克与心衰风险高，评估机械循环支持与心脏保护。"}],"note":"Selvester 评分在 LBBB/起搏/肥厚时不可靠；AAR 可用 Aldrich 公式（按 ST 抬高导联位置）。","refs":["急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","2023 ESC 急性冠脉综合征管理指南"]},{"id":"cardiac_trop_fast","name":"hs-cTn 快速诊断路径（0/1 h）判读","aka":["0/1h hs-cTn","快速排除 AMI"],"cat":"ACS","rank":54,"desc":"基于高敏肌钙蛋白 0/1 h 变化幅度的快速排除/确诊流程。","inputs":[{"key":"t0","label":"0 h hs-cTn","unit":"ng/L","type":"number","min":0,"max":10000,"step":0.1,"required":true},{"key":"t1","label":"1 h hs-cTn","unit":"ng/L","type":"number","min":0,"max":10000,"step":0.1,"required":true},{"key":"assay","label":"检测方法","type":"select","options":[{"value":1,"label":"hs-cTnT（Roche，第 5 代）"},{"value":2,"label":"hs-cTnI（Abbott）"}],"required":true}],"formula":"0/1 h ESC 流程：T 型：0 h <6 ng/L 或 1 h 变化 <3 ng/L 且 0 h <6 → 排除；0 h <14 且 1 h 变化 <4 → 排除；0 h ≥14 且变化 ≥4 → 确诊","compute":"formula_only","algorithm":"// 阈值以 Roche hs-cTnT 第 5 代为默认\nfunction ruleOut01(t0, t1, assay):\n  const d = t1 - t0\n  // hs-cTnT: rule-out 0h <6 或 (0h<6 且 1h 变化<3)；rule-in 0h>=14 且变化>=4\n  if (t0 >= 14 && d >= 4) return '确诊（rule-in）'\n  if (t0 < 6 && d < 3) return '排除（rule-out）'\n  return '观察（需 3h 或影像/临床评估）'\n// hs-cTnI (Abbott)：rule-out 0h<5 或 0h<150 且变化<2；rule-in 0h>=52 或变化>=6","interpret":[{"when":"t0 >= 14 && t1 - t0 >= 4","level":"crit","text":"符合 rule-in：按 NSTEMI 处理，启动抗栓与 24 h 内（高危即刻）冠脉造影。"},{"when":"t0 < 6 && t1 - t0 < 3","level":"ok","text":"符合 rule-out：结合临床与 ECG 可考虑出院，门诊随访；女性可参考年龄相关阈值。"},{"when":"t1 - t0 < 4 || t0 < 14","level":"warn","text":"观察区：1–3 h 复测或 0/3 h 流程，必要时 CTA/负荷试验。"}],"note":"胸痛发作 3 h 内者 0/1 h 路径灵敏度下降；透析患者基线升高需看动态变化。各医院检测平台阈值不同，须以本室说明书为准。","refs":["非 ST 段抬高型急性冠脉综合征诊断和治疗指南（2024）","2020 ESC NSTE-ACS 指南（0/1 h 流程）","高敏心肌肌钙蛋白临床应用中国专家共识（2020）"]},{"id":"duke_treadmill","name":"Duke 平板运动试验评分","aka":["Duke Treadmill Score","DTS"],"cat":"功能评估","rank":55,"desc":"平板运动试验结果定量评分，预测冠心病与预后。","inputs":[{"key":"duration","label":"运动时间（Bruce 方案）","unit":"min","type":"number","min":0,"max":25,"step":0.1,"required":true},{"key":"st_dev","label":"ST 段最大压低（mm）","unit":"mm","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"angina_index","label":"心绞痛指数","type":"select","options":[{"value":0,"label":"无（0）"},{"value":1,"label":"非限制性心绞痛（1）"},{"value":2,"label":"限制性心绞痛（2）"}],"required":true}],"formula":"DTS = 运动时间(min) − 5×ST 压低(mm) − 4×心绞痛指数","compute":"formula_only","algorithm":"function dukeTreadmill(durationMin, stDevMm, anginaIdx):\n  const dts = durationMin - 5 * stDevMm - 4 * anginaIdx\n  return { v: dts, tier: dts < -11 ? '高危' : (dts <= 4 ? '中危' : '低危') }","interpret":[{"when":"v < -11","level":"crit","text":"DTS ≤−11：高危（5 年死亡率 >5%），建议冠脉造影。"},{"when":"v >= -11 && v <= 4","level":"warn","text":"DTS −10 至 +4：中危（5 年死亡率 1–5%），进一步负荷影像或 CT 冠脉造影。"},{"when":"v > 4","level":"ok","text":"DTS ≥+5：低危（5 年死亡率 <1%），每年复发风险 <1%，可药物管理。"}],"note":"不适用于左束支阻滞、起搏心律、预激与 ST 改变基线异常者，应改用负荷心肌灌注/超声或 CMR。","refs":["慢性冠脉综合征诊断和治疗指南（2024）","2021 AHA/ACC 胸痛评估与诊断指南"]},{"id":"lv_mass_echo","name":"左室质量指数（超声）","aka":["LVMI","左室肥厚判定"],"cat":"功能评估","rank":56,"desc":"按 ASE 公式由超声测值计算左室质量指数，判断左室肥厚。","inputs":[{"key":"lvedd","label":"LVEDD","unit":"mm","type":"number","min":25,"max":100,"step":0.1,"required":true},{"key":"lvesd","label":"LVESD","unit":"mm","type":"number","min":10,"max":90,"step":0.1,"required":true},{"key":"pwt","label":"后壁厚度 PWTD","unit":"mm","type":"number","min":3,"max":30,"step":0.1,"required":true},{"key":"ivsd","label":"室间隔厚度 IVSd","unit":"mm","type":"number","min":3,"max":30,"step":0.1,"required":true},{"key":"bsa","label":"体表面积 BSA","unit":"m²","type":"number","min":0.5,"max":3,"step":0.01,"required":true},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"女"},{"value":1,"label":"男"}],"required":true}],"formula":"LV mass(g) = 0.8 × 1.04 × [(LVEDD+PWTD+IVSd)³ − LVEDD³] + 0.6；LVMI = LV mass / BSA","compute":"formula_only","algorithm":"function lvmi(lvedd, lvesd, pwt, ivsd, bsa, sex):\n  const lvm = 0.8 * 1.04 * (Math.pow(lvedd + pwt + ivsd, 3) - Math.pow(lvedd, 3)) + 0.6\n  const idx = lvm / bsa\n  const limit = sex === 0 ? 95 : 115   // g/m²\n  return { mass: lvm, v: idx, tier: idx > limit ? '左室肥厚' : '正常' }\n// 相对室壁厚度 RWT = 2×PWTD/LVEDD；>0.42 为向心性重构/肥厚","interpret":[{"when":"sex == 0 && v > 95","level":"high","text":"女性 LVMI >95 g/m²：符合左室肥厚，抗高血压治疗中优先 ACEI/ARB + CCB。"},{"when":"sex == 1 && v > 115","level":"high","text":"男性 LVMI >115 g/m²：符合左室肥厚，评估高血压/主动脉瓣狭窄/HCM/淀粉样变。"},{"when":"(sex == 0 && v <= 95) || (sex == 1 && v <= 115)","level":"ok","text":"LVMI 未达肥厚切点。"}],"note":"指南推荐女性 >95、男性 >115 g/m² 为左室肥厚（ASE/EACVI 2015）；3D 或 CMR 测量更准确。","refs":["中国超声心动图测量与报告规范（2023）","2015 ASE/EACVI 左室肥厚定量建议","中国高血压防治指南（2024 年修订版）"]},{"id":"e_cv_cmr","name":"心肌细胞外容积（ECV，CMR）","aka":["ECV","extracellular volume"],"cat":"功能评估","rank":57,"desc":"由血细胞比容与 T1 值计算心肌细胞外容积比例，评估弥漫纤维化。","inputs":[{"key":"hct","label":"血细胞比容","unit":"%","type":"number","min":10,"max":70,"step":0.1,"required":true},{"key":"t1_myo","label":"增强后心肌 T1","unit":"ms","type":"number","min":100,"max":1000,"step":1,"required":true},{"key":"t1_blood","label":"增强后血池 T1","unit":"ms","type":"number","min":50,"max":800,"step":1,"required":true},{"key":"t1_myo_native","label":"增强前心肌 T1","unit":"ms","type":"number","min":100,"max":1600,"step":1,"required":true},{"key":"t1_blood_native","label":"增强前血池 T1","unit":"ms","type":"number","min":100,"max":2000,"step":1,"required":true}],"formula":"ECV = (1 − Hct) × [(1/T1ℳᵒ⁰ᵗᵉ) − (1/T1ℳⁿᵃᵗᵛ)] / [(1/T1ᴮᵒ⁰ᵗᵉ) − (1/T1ᴮⁿᵃᵗᵛ)]","compute":"formula_only","algorithm":"function ecv(hct, t1MyoPost, t1BloodPost, t1MyoPre, t1BloodPre):\n  const a = 1 / t1MyoPost - 1 / t1MyoPre\n  const b = 1 / t1BloodPost - 1 / t1BloodPre\n  if (b === 0) return { error: 'T1 值异常' }\n  return { v: Math.round((1 - hct / 100) * (a / b) * 100 * 10) / 10 }\n// 正常 <30%（女性略高）","interpret":[{"when":"v < 30","level":"ok","text":"ECV <30%：心肌间质正常范围。"},{"when":"v >= 30 && v < 35","level":"warn","text":"30%–35%：轻度弥漫纤维化，见于高血压心脏病、早期扩心病。"},{"when":"v >= 35","level":"high","text":"≥35%：显著弥漫纤维化，提示淀粉样变（常 >40%）、严重重构或心肌炎后。"}],"note":"前体是血细胞比容与两次 T1 配对；不同场强与序列正常值不同，判读需结合序列参考值。","refs":["2020 CMR 心肌组织特征量化中国专家共识","2017 SCMR 心肌 T1 mapping 推荐"]},{"id":"ctr_chest","name":"心胸比（CTR）","aka":["Cardiothoracic ratio"],"cat":"功能评估","rank":58,"desc":"由胸片测量心脏最大横径与胸廓内径之比，判断心脏增大。","inputs":[{"key":"cardiac","label":"心脏最大横径","unit":"mm","type":"number","min":30,"max":300,"step":1,"required":true},{"key":"thorax","label":"胸廓内径（膈面）","unit":"mm","type":"number","min":100,"max":500,"step":1,"required":true}],"formula":"CTR = 心脏最大横径 / 胸廓内径","compute":"formula_only","algorithm":"function ctr(cardiac, thorax):\n  return { v: Math.round(cardiac / thorax * 100) / 100 }\n// CTR >0.5 提示心脏增大（正位片，需吸气充分）","interpret":[{"when":"v <= 0.5","level":"ok","text":"CTR ≤0.50：心胸比正常。"},{"when":"v > 0.5 && v <= 0.55","level":"warn","text":"0.51–0.55：轻度增大，结合 LV 直径与病史；肥胖/吸气不足可假性增大。"},{"when":"v > 0.55","level":"high","text":">0.55：明显心脏增大，建议超声心动图评估心腔与瓣膜。"}],"note":"仅见于后前位片、呼吸相充分时可靠；侧位与床旁片不适用。","refs":["中国心力衰竭诊断和治疗指南（2024）","中国心脏病影像学检查规范（2018）"]},{"id":"chads_vas_c_bleed_combined","name":"房颤抗凝决策速查（卒中-出血联合）","aka":["房颤抗凝决策"],"cat":"抗栓/出血","rank":59,"desc":"把卒中风险与出血风险放在一起，给出抗凝药物与随访建议。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"低卒中风险（CHA₂DS₂-VA 0）","criteria":"不推荐抗凝；每年复查危险因素，女性/65 岁临界者可考虑","level":"ok"},{"label":"卒中风险 ≥1 + 出血低危（HAS-BLED ≤2）","criteria":"启动 NOAC（房颤非瓣膜性）或华法林（INR 2.0–3.0，TTR >70%）","level":"ok"},{"label":"卒中风险 ≥2 + 出血高危（HAS-BLED ≥3）","criteria":"仍应抗凝，但选择较低出血风险 NOAC、纠正可纠正因素、3 个月随访；避免同时使用抗血小板","level":"warn"},{"label":"机械瓣/中重度二尖瓣狭窄","criteria":"必须使用华法林（NOAC 禁用），INR 目标按瓣膜类型（机械主动脉瓣 2.0–3.0，二尖瓣 2.5–3.5）","level":"warn"},{"label":"既往颅内出血/活动性出血","criteria":"暂缓或改用左心耳封堵；多学科讨论，个体化权衡","level":"crit"},{"label":"CKD 4–5 期/透析","criteria":"华法林或低剂量阿哌沙班（依说明书），剂量遵说明书，避免达比加群","level":"crit"}],"note":"NOAC 剂量必须按说明书（年龄、体重、CrCl、合并用药），不凭经验减量。","refs":["2024 ESC 心房颤动管理指南","中国心房颤动诊断和治疗指南（2023）","心房颤动抗凝治疗中国专家共识（2019）"]},{"id":"watc_bleed_thrombocytopenia","name":"合并血小板减少的抗凝评估","aka":["血小板减少抗凝"],"cat":"抗栓/出血","rank":60,"desc":"按血小板水平给出房颤/静脉血栓抗凝的谨慎处理思路。","inputs":[{"key":"plt","label":"血小板计数","unit":"×10⁹/L","type":"number","min":1,"max":1000,"step":1,"required":true}],"formula":"按血小板计数分级确定抗凝强度与是否可抗凝","compute":"formula_only","algorithm":"function pltAnticoag(plt):\n  if (plt >= 100) return '常规抗凝'\n  if (plt >= 50) return '可抗凝，首选 NOAC，密切监测'\n  if (plt >= 30) return '个体化，多学科讨论，减量或暂缓'\n  return '暂缓抗凝，评估出血/输注血小板'","interpret":[{"when":"v >= 100","level":"ok","text":"血小板 ≥100×10⁹/L：按常规指征抗凝。"},{"when":"v >= 50 && v < 100","level":"warn","text":"50–99：可抗凝（NOAC 优先），加强血常规监测，避免联合抗血小板。"},{"when":"v >= 30 && v < 50","level":"high","text":"30–49：需多学科讨论，个体化减量或暂缓，卒中极高危者权衡。"},{"when":"v < 30","level":"crit","text":"<30：一般暂缓抗凝，评估出血原因与血小板输注；左心耳封堵可讨论。"}],"note":"HIT（肝素诱导血小板减少）须停肝素；免疫性血小板减少治疗原发病可改善。具体阈值以各指南与说明书为准。","refs":["2024 ESC 心房颤动管理指南","中国成人血小板减少症诊疗专家共识（2020）"]},{"id":"vte_anticoag_dose","name":"VTE 抗凝剂量参考","aka":["DVT/PE 抗凝剂量"],"cat":"抗栓/出血","rank":61,"desc":"急性 VTE 常用抗凝药物起始与维持剂量速查。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"利伐沙班","criteria":"15 mg bid ×21 天，之后 20 mg qd（与食物同服）；CrCl 15–49 或高出血者维持 15 mg qd；CrCl <15 慎用","level":"ok"},{"label":"阿哌沙班","criteria":"10 mg bid ×7 天，之后 5 mg bid；≥2 项（年龄 ≥80、体重 ≤60 kg、CrCl ≤30）时减为 2.5 mg bid","level":"ok"},{"label":"达比加群酯","criteria":"需先静脉抗凝 ≥5 天：150 mg bid（CrCl 30–50 或高龄/出血风险高者 110 mg bid）；CrCl <30 禁用","level":"warn"},{"label":"低分子肝素（依诺肝素）","criteria":"1 mg/kg q12h 皮下（CrCl <30 减为 1 mg/kg qd）；妊娠期首选；监测血小板","level":"ok"},{"label":"磺达肝癸钠","criteria":"体重 <50 kg：5 mg qd；50–100 kg：7.5 mg qd；>100 kg：10 mg qd；CrCl <30 慎用","level":"ok"},{"label":"华法林","criteria":"起始 2.5–3 mg qd（老年/肝功能不全减量），与肝素重叠 ≥5 天至 INR ≥2.0 持续 2 天；目标 INR 2.0–3.0","level":"warn"},{"label":"疗程","criteria":"诱发性 DVT/PE 3 个月；无诱因 3–6 个月后评估延长抗凝；肿瘤相关 VTE 推荐 LMWH 或 NOAC（利伐沙班/艾多沙班）","level":"ok"}],"note":"所有剂量以说明书和 2018 中国肺血栓栓塞症指南为准；肾功能不全按 CrCl 调整，妊娠期禁 NOAC 与华法林（早孕期），首选 LMWH。","refs":["肺血栓栓塞症诊治与预防指南（2018）","中国血栓性疾病防治指南（2018）","2019 ESC 急性肺栓塞诊断与管理指南","各抗凝药中文说明书"]},{"id":"pericardial_effusion","name":"心包积液分级","aka":["Pericardial effusion grading"],"cat":"心包疾病","rank":62,"desc":"按超声舒张期无回声区宽度与血流动力学分级心包积液。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"微量/微量积液","criteria":"舒张末期无回声区 <10 mm，无血流动力学影响","level":"ok"},{"label":"少量","criteria":"10–20 mm（<1 cm 亦计少量），通常无症状","level":"ok"},{"label":"中量","criteria":"20–40 mm（10–20 mm 之间），注意右心塌陷征象与进展","level":"warn"},{"label":"大量","criteria":">40 mm 或环形分布伴心脏摆动，需评估心包穿刺","level":"high"},{"label":"伴心包压塞","criteria":"出现压塞任一征象：右房/右室舒张期塌陷、下腔静脉扩张不塌陷、摆动心脏、奇脉 >10 mmHg","level":"crit"}],"note":"2023 ESC 心包疾病指南将积液分为微量（<10 mm）、少量（10–20 mm）、中量（20–40 mm）、大量（>40 mm）与压塞（附临床/影像表现）。","refs":["2023 ESC 心包疾病诊断与管理指南","中国心包疾病诊断和治疗指南（2021）"]},{"id":"beck_triad_tamponade","name":"Beck 三联征与心包压塞评估","aka":["Beck triad","心包压塞"],"cat":"心包疾病","rank":63,"desc":"以 checklist 形式系统评估心包压塞的临床与超声征象。","inputs":[{"key":"hypotension","label":"低血压（SBP <90 mmHg 或下降 >20 mmHg）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"jvp","label":"颈静脉怒张","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"muffled","label":"心音遥远低钝","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pulsus","label":"奇脉 >10 mmHg","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"rv_collapse","label":"超声右室舒张期塌陷","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Beck 三联征 = 低血压 + 颈静脉怒张 + 心音低钝；压塞确诊要求伴超声/血流动力学征象","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"无压塞征象，按心包炎/积液病因治疗并随访超声。"},{"when":"v >= 1 && v <= 2","level":"warn","text":"存在部分征象：监测血流动力学与超声，警惕进展。"},{"when":"v >= 3 && v <= 4","level":"high","text":"多项阳性：高度怀疑压塞，紧急床旁超声与多学科会诊。"},{"when":"v >= 5","level":"crit","text":"满足 Beck 三联征 + 奇脉 + 超声塌陷：心包压塞确诊，立即心包穿刺引流（首选超声引导），避免使用血管扩张剂。"}],"note":"注意「奇脉」参考值：吸气时收缩压下降 >10 mmHg；心房颤动、主动脉瓣反流者奇脉可减弱。低血压+颈静脉怒张+心音低钝三项齐全时即为 Beck 三联征。","refs":["2023 ESC 心包疾病诊断与管理指南","中国心包疾病诊断和治疗指南（2021）"]},{"id":"pericarditis_dx","name":"急性心包炎诊断标准（checklist）","aka":["Pericarditis diagnosis"],"cat":"心包疾病","rank":64,"desc":"按 ESC/中国指南的 4 条诊断标准中需满足 ≥2 条。","inputs":[{"key":"chest_pain","label":"心包性胸痛（前倾位缓解）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"rub","label":"心包摩擦音","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"ecg","label":"心电图广泛 ST 抬高/PR 段压低","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"effusion","label":"新出现或加重的心包积液","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"4 项中满足 ≥2 项即可诊断急性心包炎","compute":"sum","interpret":[{"when":"v >= 2","level":"high","text":"符合急性心包炎诊断（≥2 条）：一线治疗为 NSAIDs + 秋水仙碱，限制运动；评估高危因素。"},{"when":"v == 1","level":"warn","text":"仅 1 条：诊断存疑，需检查 hs-cTn、CRP/ESR、超声与 MRI。"},{"when":"v == 0","level":"ok","text":"无支持标准：考虑其他胸痛病因（ACS、肺栓塞、主动脉夹层）。"}],"note":"高危特征：发热 >38 ℃、亚急性病程、大量积液、压塞、NSAID 无效；心肌炎（肌钙蛋白升高）合并需住院。","refs":["2023 ESC 心包疾病诊断与管理指南","中国心包疾病诊断和治疗指南（2021）"]},{"id":"aortic_stenosis_severity","name":"主动脉瓣狭窄严重度分级","aka":["AS severity"],"cat":"瓣膜病","rank":65,"desc":"按超声速度、平均压差、瓣口面积判断主动脉瓣狭窄程度。","inputs":[{"key":"vmax","label":"峰值流速 Vmax","unit":"m/s","type":"number","min":1,"max":7,"step":0.1,"required":true},{"key":"mean_grad","label":"平均跨瓣压差","unit":"mmHg","type":"number","min":0,"max":200,"step":1,"required":true},{"key":"ava","label":"瓣口面积 AVA","unit":"cm²","type":"number","min":0.2,"max":5,"step":0.01,"required":true}],"formula":"按 Vmax、平均压差与 AVA 分级：轻度 Vmax 2.6–2.9/AVA >1.5；中度 3.0–4.0 / 1.0–1.5；重度 ≥4.0 / <1.0","compute":"formula_only","algorithm":"function asSeverity(vmax, meanGrad, ava):\n  if (vmax >= 4 || ava < 1.0) return '重度（Vmax≥4m/s 或 AVA<1.0cm²）'\n  if (vmax >= 3.0 || ava < 1.5) return '中度'\n  if (vmax >= 2.6) return '轻度'\n  return '硬化（Vmax<2.6）'","interpret":[{"when":"vmax >= 4 || ava < 1.0","level":"crit","text":"重度 AS：症状出现或 LVEF <50% 者应行 AVR/TAVI；无症状者需负荷试验评估。"},{"when":"vmax >= 3.0 || ava < 1.5","level":"warn","text":"中度 AS：每年超声随访，监测 LVEF 与症状。"},{"when":"vmax >= 2.6","level":"ok","text":"轻度 AS：2–3 年随访一次超声。"},{"when":"vmax < 2.6 && ava >= 1.5","level":"ok","text":"主动脉瓣硬化（Vmax <2.6 m/s、AVA ≥1.5）：无血流动力学梗阻，管理危险因素。"}],"note":"低流速低压差（LVEF 降低）需多巴酚丁胺负荷超声确诊；AVA <1.0 且平均压差 <40 需进一步评估。","refs":["2021 ESC/EACTS 瓣膜性心脏病管理指南","中国心脏瓣膜病诊断和治疗指南（2021）","中国超声心动图测量与报告规范（2023）"]},{"id":"aortic_regurg_severity","name":"主动脉瓣反流严重度分级","aka":["AR severity"],"cat":"瓣膜病","rank":66,"desc":"按缩流颈宽度、反流分数与左室大小判断主动脉瓣反流程度。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"轻度","criteria":"缩流颈宽度 <3 mm；反流分数 <30%；无反流束明显增宽；左室大小正常","level":"ok"},{"label":"中度","criteria":"缩流颈 3–6 mm；反流分数 30%–49%；LV 轻度增大","level":"warn"},{"label":"重度","criteria":"缩流颈 ≥6 mm；反流分数 ≥50%；LVEDD >65 mm 或 LVESD >50 mm（部分标准 >55/>25 mm/m²）","level":"high"},{"label":"极重度/进展","criteria":"降主动脉内舒张期反向血流、LV 快速增大（年增 >5 mm）、出现症状或 LVEF <55%","level":"crit"}],"note":"重度 AR 有症状或 LVEF ≤55%/LVEDD 接近手术阈值时应考虑手术；马凡综合征按主动脉根部直径更早手术。","refs":["2021 ESC/EACTS 瓣膜性心脏病管理指南","中国心脏瓣膜病诊断和治疗指南（2021）","中国超声心动图测量与报告规范（2023）"]},{"id":"mitral_regurg_severity","name":"二尖瓣反流严重度分级","aka":["MR severity"],"cat":"瓣膜病","rank":67,"desc":"按反流束面积、缩流颈、有效反流口面积判断二尖瓣反流程度。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"轻度","criteria":"彩色反流束面积 <4 cm²；缩流颈 <3 mm；EROA <20 mm²；反流量 <30 mL","level":"ok"},{"label":"中度","criteria":"反流束 4–10 cm²；缩流颈 3–7 mm；EROA 20–39 mm²；反流量 30–60 mL；可再细分 2+ / 2+~3+","level":"warn"},{"label":"重度","criteria":"缩流颈 ≥7 mm；EROA ≥40 mm²；反流量 ≥60 mL；肺静脉收缩期逆流；LVESD ≥50 mm 或 LVEF <60%","level":"high"},{"label":"极重度","criteria":"缩流颈 ≥10 mm、EROA ≥60 mm²、反流束 >10 cm²、无收缩期肺静脉血流","level":"crit"}],"note":"继发性 MR 以 LV 功能与症状为手术决策主轴；Tmvr/TEER 需 MDT 评估。","refs":["2021 ESC/EACTS 瓣膜性心脏病管理指南","中国心脏瓣膜病诊断和治疗指南（2021）","中国超声心动图测量与报告规范（2023）"]},{"id":"tapse","name":"三尖瓣环收缩期位移（TAPSE）判读","aka":["TAPSE","右室收缩功能"],"cat":"功能评估","rank":68,"desc":"以超声 M 型测量三尖瓣环位移评估右室收缩功能。","inputs":[{"key":"tapse","label":"TAPSE","unit":"mm","type":"number","min":0,"max":40,"step":1,"required":true}],"formula":"TAPSE 直接测值；右室收缩功能正常参考 ≥17 mm（ESC/ASE）","compute":"formula_only","algorithm":"function tapse(v):\n  return { v, tier: v < 10 ? '严重降低' : (v < 17 ? '降低' : '正常') }","interpret":[{"when":"v < 10","level":"crit","text":"<10 mm：右室收缩功能严重减低，见于肺高压晚期、右室心梗、ARVC，预后差。"},{"when":"v >= 10 && v < 17","level":"high","text":"10–16 mm：右室收缩功能减低，结合 RVFAC/RVEF 与肺压评估。"},{"when":"v >= 17","level":"ok","text":"≥17 mm：右室纵向收缩功能正常。"}],"note":"TAPSE 反映纵向功能，受角度影响；心脏术后与心包病变时可能低估。","refs":["2015 ASE/EACVI 右心评估建议","2022 ESC/ERS 肺动脉高压诊断与治疗指南"]},{"id":"tapse_pasp_ratio","name":"TAPSE/PASP 比值（右室-肺循环耦联）","aka":["TAPSE/PASP"],"cat":"功能评估","rank":69,"desc":"评估右室收缩与肺动脉压力的耦联，用于心衰与肺高压预后。","inputs":[{"key":"tapse","label":"TAPSE","unit":"mm","type":"number","min":0,"max":40,"step":1,"required":true},{"key":"pasp","label":"估测肺动脉收缩压 PASP","unit":"mmHg","type":"number","min":5,"max":150,"step":1,"required":true}],"formula":"TAPSE/PASP","compute":"formula_only","algorithm":"function tapsePasp(tapse, pasp):\n  const r = tapse / pasp\n  return { v: Math.round(r * 100) / 100,\n           tier: r >= 0.35 ? '耦联保留' : (r >= 0.31 ? '轻度失耦联' : '显著失耦联') }\n// 心衰：<0.35 提示失代偿风险；肺高压：<0.31 为预后关键阈值","interpret":[{"when":"v > 0.75","level":"ok","text":">0.75 mm/mmHg：右室-肺循环耦联良好（正常 >0.35）。"},{"when":"v >= 0.35 && v <= 0.75","level":"ok","text":"0.35–0.75：耦联保留。"},{"when":"v >= 0.31 && v < 0.35","level":"warn","text":"0.31–0.34：轻度失耦联，提示右室储备下降。"},{"when":"v < 0.31","level":"crit","text":"<0.31 mm/mmHg：显著失耦联，心衰/肺高压预后不良，考虑进阶治疗评估。"}],"note":"心衰中 <0.35 提示失代偿风险；肺高压中 <0.31 为预后分层关键阈值（2022 ESC/ERS）。","refs":["2022 ESC/ERS 肺动脉高压诊断与治疗指南","中国心力衰竭诊断和治疗指南（2024）"]},{"id":"shd_vasodilator_test","name":"右心导管舒血管反应试验判读","aka":["Vasoreactivity test"],"cat":"功能评估","rank":70,"desc":"按 mPAP 与 PVR 变化判断肺高压患者急性舒血管反应性。","inputs":[{"key":"mpap_base","label":"基线 mPAP","unit":"mmHg","type":"number","min":5,"max":100,"step":1,"required":true},{"key":"mpap_after","label":"试验后 mPAP","unit":"mmHg","type":"number","min":2,"max":100,"step":1,"required":true},{"key":"co_base","label":"基线心输出量 CO","unit":"L/min","type":"number","min":1,"max":15,"step":0.1,"required":true},{"key":"co_after","label":"试验后心输出量 CO","unit":"L/min","type":"number","min":1,"max":15,"step":0.1,"required":true}],"formula":"反应性阳性：mPAP 下降 ≥10 mmHg 且绝对值降至 ≤40 mmHg，同时 CO 不变或增加","compute":"formula_only","algorithm":"function vasoreactivity(mpapBase, mpapAfter, coBase, coAfter):\n  const ok = (mpapBase - mpapAfter) >= 10 && mpapAfter <= 40 && coAfter >= coBase\n  return { positive: ok }","interpret":[{"when":"mpap_base - mpap_after >= 10 && mpap_after <= 40 && co_after >= co_base","level":"ok","text":"急性舒血管反应阳性：考虑 CCB 治疗并 3 个月评估疗效（仅特发性/遗传性/药物相关 PAH）。"},{"when":"mpap_base - mpap_after < 10 || mpap_after > 40 || co_after < co_base","level":"warn","text":"反应阴性：CCB 不适用，按肺高压靶向治疗分层（ESC 2022 四支柱）治疗。"}],"note":"仅用于 PAH（第 1 组），不用于第 2–4 组；阳性率仅约 10%。","refs":["2022 ESC/ERS 肺动脉高压诊断与治疗指南","中国肺动脉高压诊断与治疗指南（2021）"]},{"id":"h2fpef_score","name":"H₂FPEF 评分（HFpEF 可能性）","aka":["H2FPEF score"],"cat":"心衰","rank":71,"desc":"射血分数保留心衰的无创评分，协助诊断。","inputs":[{"key":"bmi","label":"BMI >30 kg/m²（2 分）","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是（+2）"}],"required":true},{"key":"af","label":"心房颤动（3 分）","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"age75","label":"年龄 >60 岁（1 分，75 岁以上计 2 分）","type":"select","options":[{"value":0,"label":"≤60 岁"},{"value":1,"label":"61–74 岁（+1）"},{"value":2,"label":"≥75 岁（+2）"}],"required":true},{"key":"pad","label":"肺动脉收缩压 >35 mmHg（1 分）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"e_e","label":"E/e′ >9（1 分）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"pcwp","label":"静息/负荷 PCWP >15 mmHg（1 分）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"各项加权求和（0–9）","compute":"sum","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：HFpEF 可能性低（<10%），寻找其他病因。"},{"when":"v >= 2 && v <= 4","level":"warn","text":"2–4 分：中等可能，建议负荷超声/右心导管（运动或容量负荷）明确。"},{"when":"v >= 5","level":"high","text":"≥5 分：HFpEF 高度可能（>90%），按 HFpEF 管理（SGLT2i、利尿、合并症治疗）。"}],"note":"H₂FPEF 用于 HFpEF 诊断可能性；另有 HFA-PEFF 诊断流程（含利钠肽、负荷试验）。","refs":["2024 中国心力衰竭诊断和治疗指南（HFpEF 部分）","2022 AHA/ACC/HFSA 心衰指南","2019 H₂FPEF 评分（Reddy YNV, Circulation 2018）"]},{"id":"shd_who_group","name":"肺高压临床分类（WHO 1–5 组）","aka":["PH classification"],"cat":"功能评估","rank":72,"desc":"肺高压五分类速查，指导治疗路径。","inputs":[],"compute":"sum","interpret":[{"when":"v == 0","level":"warn","text":"第 2、3 组以治疗原发病为主；PAH 靶向药仅在严格指征下使用（第 2 组合并第 1 组特征、第 3 组重度者慎用）。"},{"when":"v >= 4","level":"high","text":"第 4 组 CTEPH：V/Q 显像筛查阳性者评估 PEA 手术；不可手术者可用利奥西呱或球囊肺动脉成形。"},{"when":"v >= 1 && v < 4","level":"high","text":"第 1 组 PAH：按 ESC 2022 危险分层（低/中/高）选择初始单药或联合靶向治疗。"},{"when":"v < 0","level":"warn","text":"请按 WHO 临床分类选择治疗路径。"}],"levels":[{"label":"第 1 组 PAH","criteria":"特发性/遗传性/药物相关/结缔组织病/先天性心脏病/门脉高压/血吸虫相关；mPAP >20、PAWP ≤15、PVR >2 WU","level":"high"},{"label":"第 2 组 左心疾病相关","criteria":"HFrEF/HFpEF/瓣膜病，PAWP >15；以治疗左心疾病为主，慎用 PAH 靶向药","level":"warn"},{"label":"第 3 组 肺部疾病/低氧","criteria":"COPD、ILD、OSA、肥胖低通气；治疗基础病与氧疗，PAH 靶向治疗限于重度（2022 更新）","level":"warn"},{"label":"第 4 组 慢性血栓栓塞性","criteria":"CTEPH/其他肺动脉梗阻；行 V/Q 显像筛查，CTEPH 可行 PEA/球囊肺动脉成形/利奥西呱","level":"high"},{"label":"第 5 组 多因素/不明机制","criteria":"血液病、系统性疾病、代谢病、复杂先心等，病因治疗为主","level":"warn"}],"note":"2022 ESC/ERS 更新血流动力学定义：mPAP >20 mmHg、PVR >2 WU；第 3 组与第 2 组可叠加第 1 组靶向治疗（标注「+」）。","refs":["2022 ESC/ERS 肺动脉高压诊断与治疗指南","中国肺动脉高压诊断与治疗指南（2021）"]},{"id":"shd_6mwd_who","name":"WHO 功能分级（肺高压）","aka":["WHO-FC"],"cat":"分级量表","rank":73,"desc":"肺高压患者功能状态分级，指导治疗强度。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"I 级","criteria":"日常体力活动不受限，无呼吸困难/乏力/胸痛/晕厥","level":"ok"},{"label":"II 级","criteria":"日常活动轻度受限，休息时无症状，普通活动时出现症状","level":"ok"},{"label":"III 级","criteria":"体力活动明显受限，休息时无症状，低于日常的活动即出现症状","level":"warn"},{"label":"IV 级","criteria":"不能从事任何体力活动，休息时即有呼吸困难/乏力，有右心衰征象，静息状态下不能活动","level":"crit"}],"note":"WHO-FC 与 6MWD、BNP 共同构成肺高压危险分层（ESC 四张表：低/中/高危），WHO IV 级或 6MWD <165 m 为高危。","refs":["2022 ESC/ERS 肺动脉高压诊断与治疗指南","中国肺动脉高压诊断与治疗指南（2021）"]},{"id":"nyha_to_ccs_note","name":"NYHA 与 CCS 分级对照说明","aka":["分级对照"],"cat":"分级量表","rank":74,"desc":"说明心功能（NYHA）与心绞痛（CCS）两套分级不能互换。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"同属功能分级但维度不同","criteria":"NYHA 评价心衰症状（疲乏/呼吸困难），CCS 评价心绞痛发作阈值；二者不换算","level":"warn"},{"label":"常见混淆","criteria":"「CCS I 级」≠「NYHA I 级」；稳定型心绞痛患者可同时评 NYHA 与 CCS 两级","level":"warn"},{"label":"使用建议","criteria":"心衰用 NYHA，慢性冠脉综合征用 CCS；ACS 用 Killip；房颤用 EHRA","level":"ok"}],"note":"体检与病历记录时请明确写「NYHA II 级」或「CCS II 级」，避免歧义。","refs":["中国心力衰竭诊断和治疗指南（2024）","慢性冠脉综合征诊断和治疗指南（2024）"]},{"id":"anion_gap_cardio","name":"阴离子间隙（AG）","aka":["Anion gap"],"cat":"血流动力学","rank":75,"desc":"心衰/休克患者代谢性酸中毒鉴别，评估乳酸堆积与酮症。","inputs":[{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":180,"step":1,"required":true},{"key":"cl","label":"血氯","unit":"mmol/L","type":"number","min":60,"max":140,"step":1,"required":true},{"key":"hco3","label":"碳酸氢根 HCO₃⁻","unit":"mmol/L","type":"number","min":2,"max":40,"step":1,"required":true},{"key":"albumin","label":"白蛋白（可选，校正）","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":false}],"formula":"AG = Na⁺ − (Cl⁻ + HCO₃⁻)（参考 8–16）；白蛋白校正 AG = AG + 0.25 × (40 − 白蛋白 g/L)","compute":"formula_only","algorithm":"function anionGap(na, cl, hco3, alb):\n  let ag = na - (cl + hco3)\n  if (alb) ag += 0.25 * (40 - alb)\n  return { v: ag }","interpret":[{"when":"v <= 16","level":"ok","text":"≤16 mmol/L：阴离子间隙正常，无高 AG 酸中毒。"},{"when":"v > 16 && v <= 20","level":"warn","text":"17–20：轻度升高，结合乳酸、酮体、肾功能判读。"},{"when":"v > 20","level":"high","text":">20：高 AG 代谢性酸中毒，见于乳酸性酸中毒（心源性休克、低灌注）、DKA、尿毒症、药物（二甲双胍）。"}],"note":"心衰/低白蛋白血症患者需做白蛋白校正；休克时应直接测乳酸。","refs":["2020 重症患者血流动力学监测与治疗中国专家共识","中国心力衰竭诊断和治疗指南（2024）"]},{"id":"sodium_hf_prognosis","name":"心衰低钠血症分层","aka":["Hyponatremia in HF"],"cat":"心衰","rank":76,"desc":"按血钠对心衰患者进行风险分层与处理提示。","inputs":[{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":170,"step":1,"required":true}],"formula":"血钠 <135 mmol/L 为低钠血症；<130 为中度；<125 为重度","compute":"formula_only","algorithm":"function sodiumTier(na):\n  if (na < 120) return '重度'\n  if (na < 125) return '重度'\n  if (na < 130) return '中度'\n  if (na < 135) return '轻度'\n  if (na > 145) return '高钠'\n  return '正常'","interpret":[{"when":"v < 125","level":"crit","text":"<125 mmol/L：重度低钠，住院期间死亡与再入院风险高，考虑托伐普坦（按说明书）与液体限制，避免过快纠正（<8 mmol/L/24h）。"},{"when":"v >= 125 && v < 130","level":"high","text":"125–129：中度低钠，限制液体、评估利尿剂与噻嗪类。"},{"when":"v >= 130 && v < 135","level":"warn","text":"130–134：轻度低钠，多见于利尿剂过量或稀释性低钠，调整利尿方案。"},{"when":"v >= 135 && v <= 145","level":"ok","text":"血钠正常。"},{"when":"v > 145","level":"warn","text":"高钠：多见于大量利尿/脱水，评估容量并纠正。"}],"note":"心衰低钠多为稀释性（ADH 不适当分泌），托伐普坦可改善症状但需遵说明书与指南。","refs":["中国心力衰竭诊断和治疗指南（2024）","2021 ESC 急慢性心力衰竭诊断与治疗指南"]},{"id":"ntprobnp_interpret","name":"BNP/NT-proBNP 判读（年龄分层）","aka":["NT-proBNP","BNP"],"cat":"心衰","rank":77,"desc":"按年龄分层判断 NT-proBNP 是否提示心衰，辅助排除急性/慢性心衰。","inputs":[{"key":"ntprobnp","label":"NT-proBNP","unit":"ng/L","type":"number","min":0,"max":100000,"step":1,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"acute","label":"急性（急诊）vs 门诊","type":"select","options":[{"value":1,"label":"急性"},{"value":0,"label":"门诊"}],"required":true}],"formula":"急性：排除 <300、确诊 >450（>50 岁）；门诊：排除 <125；年龄分层排除界值 <50 岁 <300、50–75 岁 <450、>75 岁 <900（急性）","compute":"formula_only","algorithm":"function ntprobnp(nt, age, acute):\n  if (acute === 1) {\n    if (nt < 300) return '排除'\n    if (nt > 1800 && age >= 75) return '高度可能'\n    if (nt > 900 && age >= 50) return '高度可能'\n    if (nt > 450) return '高度可能'\n    return '灰区'\n  }\n  return nt < 125 ? '排除' : '需评估'\n","interpret":[{"when":"v < 300","level":"ok","text":"NT-proBNP <300 ng/L（急性）：心衰可能性低，可排除急性心衰（灰区除外）。"},{"when":"v >= 300 && v < 450","level":"warn","text":"300–449：灰区，结合超声与临床。"},{"when":"v >= 450","level":"high","text":"≥450：高度提示心衰，建议超声心动图。"}],"note":"肾功能不全、老年、房颤、肺栓塞可升高；肥胖可降低。参考值以本实验室检测平台为准，本条目为 ESC 通用阈值。","refs":["2021 ESC 急慢性心力衰竭诊断与治疗指南","中国心力衰竭诊断和治疗指南（2024）","利钠肽检测与心力衰竭专家共识（2022）"]},{"id":"charlson_cardio","name":"Charlson 合并症指数（心内科）","aka":["CCI","Charlson Comorbidity Index"],"cat":"风险评分","rank":78,"desc":"评估合并症负荷，用于心衰/ACS 长期预后与治疗强度权衡。","inputs":[{"key":"mi","label":"心肌梗死（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"chf","label":"充血性心衰（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pvd","label":"外周血管病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"cva","label":"脑血管病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"dementia","label":"痴呆（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"copd","label":"慢性肺病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"ctd","label":"结缔组织病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"ulcer","label":"消化性溃疡（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"liver_mild","label":"轻度肝病（1）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"dm","label":"糖尿病（1）/伴并发症（2）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"无并发症（1）"},{"value":2,"label":"伴终末器官损害（2）"}],"required":true},{"key":"renal","label":"中重度肾病（2）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"cancer","label":"实体瘤（2）/转移瘤（6）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"实体瘤（2）"},{"value":6,"label":"转移瘤（6）"}],"required":true},{"key":"age","label":"年龄加权（<50 岁 0；50–59 1；60–69 2；70–79 3；≥80 4）","type":"select","options":[{"value":0,"label":"<50 岁"},{"value":1,"label":"50–59 岁"},{"value":2,"label":"60–69 岁"},{"value":3,"label":"70–79 岁"},{"value":4,"label":"≥80 岁"}],"required":true}],"formula":"各合并症加权求和 + 年龄加权","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：合并症负担低，估计 10 年生存 >90%。"},{"when":"v >= 3 && v <= 4","level":"warn","text":"3–4 分：中等负担，10 年生存约 53%–77%。"},{"when":"v >= 5","level":"high","text":"≥5 分：高合并症负担（10 年生存 <21%），治疗目标与强度需个体化、共同决策。"}],"note":"原版与 Quan 更新版权重不同；心衰/ACS 研究常同时报告 Charlson 与 Elixhauser。","refs":["Charlson ME, J Chronic Dis 1987","中国心力衰竭诊断和治疗指南（2024）"]},{"id":"big_r_sounding","name":"收缩压变异度（CV，家庭血压）","aka":["BP variability"],"cat":"血压","rank":79,"desc":"按家庭连续测量血压计算变异系数，评估血压波动与心血管风险。","inputs":[{"key":"sd","label":"收缩压标准差 SD","unit":"mmHg","type":"number","min":0,"max":60,"step":0.1,"required":true},{"key":"mean","label":"收缩压均值","unit":"mmHg","type":"number","min":60,"max":250,"step":1,"required":true}],"formula":"CV = SD / 均值 × 100%","compute":"formula_only","algorithm":"function bpCV(sd, mean):\n  if (mean <= 0) return { error: '均值必须 >0' }\n  return { v: Math.round(sd / mean * 1000) / 10 }\n// CV >15% 提示血压变异度增大","interpret":[{"when":"v < 10","level":"ok","text":"CV <10%：血压相对平稳。"},{"when":"v >= 10 && v <= 15","level":"warn","text":"10%–15%：变异偏大，建议规范测量（清晨、固定时间）并复核。"},{"when":"v > 15","level":"high","text":">15%：血压变异度显著增大，与靶器官损害和卒中风险相关，需排查依从性、睡眠呼吸暂停与继发性高血压。"}],"note":"家庭血压连续 7 天（早晚各 2 次）计算更有代表性；避免测压姿势、测量时间不一致带来的假性变异。","refs":["中国家庭血压监测指南（2019）","中国高血压防治指南（2024 年修订版）"]},{"id":"six_min_hr_drop","name":"运动后心率恢复（HRR）","aka":["Heart rate recovery"],"cat":"功能评估","rank":80,"desc":"运动峰值心率与恢复期 1–2 分钟心率之差，反映自主神经功能与预后。","inputs":[{"key":"peak_hr","label":"峰值心率","unit":"次/分","type":"number","min":50,"max":250,"step":1,"required":true},{"key":"hr_1min","label":"恢复 1 分钟心率","unit":"次/分","type":"number","min":30,"max":220,"step":1,"required":true},{"key":"hr_2min","label":"恢复 2 分钟心率（可选）","unit":"次/分","type":"number","min":30,"max":220,"step":1,"required":false}],"formula":"HRR1 = 峰值 HR − 1 分钟 HR；HRR2 = 峰值 HR − 2 分钟 HR","compute":"formula_only","algorithm":"function hrr(peak, hr1, hr2):\n  const h1 = peak - hr1\n  const h2 = hr2 ? peak - hr2 : null\n  return { v: h1, v2: h2, tier: h1 < 12 ? '异常' : (h1 < 18 ? '弱' : '正常') }","interpret":[{"when":"v >= 18","level":"ok","text":"HRR1 ≥18 次/分：自主神经功能良好。"},{"when":"v >= 12 && v < 18","level":"warn","text":"HRR1 12–17：恢复偏慢，结合运动耐量与心衰指标。"},{"when":"v < 12","level":"high","text":"HRR1 <12 次/分：异常，全因死亡风险升高（尤其 <10），提示交感过度激活。"}],"note":"β 受体阻滞剂会降低 HRR；平板试验（Bruce）常用阈值 12 次/分为界。","refs":["2022 ESC 心脏康复指南","慢性冠脉综合征诊断和治疗指南（2024）"]},{"id":"six_min_mets","name":"代谢当量（METs）估算（平板试验）","aka":["METs","功能容量"],"cat":"功能评估","rank":81,"desc":"由 Bruce 方案阶段估算运动能力，评估预后与手术风险。","inputs":[{"key":"stage","label":"Bruce 方案阶段","type":"select","options":[{"value":1,"label":"1 级（1.7 mph, 10%）"},{"value":2,"label":"2 级（2.5 mph, 12%）"},{"value":3,"label":"3 级（3.4 mph, 14%）"},{"value":4,"label":"4 级（4.2 mph, 16%）"},{"value":5,"label":"5 级（5.0 mph, 18%）"}],"required":true}],"formula":"Bruce 各级参考 METs：1 级约 4.6、2 级约 7.0、3 级约 10.1、4 级约 12.9、5 级约 15 METs；METs <4 为功能容量差","compute":"formula_only","algorithm":"function bruceMets(stage):\n  const mets = [0, 4.6, 7.0, 10.1, 12.9, 15.0][stage]\n  return { v: mets, tier: mets < 4 ? '差' : (mets < 7 ? '中等' : (mets < 10 ? '良好' : '优秀')) }","interpret":[{"when":"stage <= 1","level":"warn","text":"≤4.6 METs：功能容量差（<4 METs），非心脏手术前需进一步评估。"},{"when":"stage == 2","level":"ok","text":"约 7 METs：中等功能容量，可完成多数日常活动。"},{"when":"stage >= 3","level":"ok","text":"≥10 METs：功能容量良好，预后较好。"}],"note":"METs 与实际摄氧量相关（1 MET ≈ 3.5 mL O₂/kg/min）；心衰患者可用 CPET 的峰值 VO₂ 判读。","refs":["2022 ESC 非心脏手术围术期心血管评估指南","慢性冠脉综合征诊断和治疗指南（2024）"]},{"id":"shd_rv_lv_ratio","name":"右室-左室基底径比（RV/LV）","aka":["RV/LV ratio"],"cat":"功能评估","rank":82,"desc":"评估右室扩大与肺栓塞/肺高压的右心负荷。","inputs":[{"key":"rv","label":"右室基底径","unit":"mm","type":"number","min":10,"max":90,"step":1,"required":true},{"key":"lv","label":"左室基底径","unit":"mm","type":"number","min":15,"max":90,"step":1,"required":true}],"formula":"RV/LV = RV 基底径 / LV 基底径","compute":"formula_only","algorithm":"function rvLv(rv, lv):\n  return { v: Math.round(rv / lv * 100) / 100, tier: rv / lv > 1 ? '右室扩大' : '正常' }","interpret":[{"when":"v <= 1.0","level":"ok","text":"≤1.0：右室与左室比例正常。"},{"when":"v > 1.0 && v <= 1.2","level":"warn","text":"1.01–1.2：轻度右室扩大，结合三尖瓣反流速度与室间隔形态。"},{"when":"v > 1.2","level":"high","text":">1.2：右室显著扩大（CT 上为肺栓塞高危征象），提示右心负荷过重。"}],"note":"CT 四腔心切面 RV/LV >1.0 为右心功能不全征象；超声四腔心 RV 与 LV 基底径正常比 ≤0.6（不是 1.0），注意两种测量口径差异。","refs":["2015 ASE/EACVI 右心评估建议","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"bleeding_risk_intra_op_anticoag","name":"PCI 围术期抗凝（肝素/比伐芦定）剂量速查","aka":["PCI 抗凝剂量"],"cat":"抗栓/出血","rank":83,"desc":"PCI 术中抗凝药物剂量与时间窗口速查。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"普通肝素（UFH）","criteria":"未用直接抗凝者：70–100 U/kg 静推（目标 ACT 250–300 s）；已用依诺肝素者补 0.3 mg/kg 依诺肝素静推或不补","level":"ok"},{"label":"比伐芦定","criteria":"0.75 mg/kg 静推 + 1.75 mg/kg/h 持续输注至术后 4 h（有出血高危者优先）；HIT 患者适用","level":"ok"},{"label":"依诺肝素","criteria":"1 mg/kg 皮下 q12h 或 0.5 mg/kg 静推（部分方案）；CrCl <30 减量；最后一剂 8 h 内不宜介入","level":"warn"},{"label":"磺达肝癸钠","criteria":"PCI 时不作为单用抗凝（导管血栓风险），需补 UFH 50–100 U/kg","level":"warn"},{"label":"OAC 患者（房颤）","criteria":"NOAC 术前停药 24–48 h（依 CrCl 与药物），不需桥接；华法林持续用药者维持 INR 2.0–3.0","level":"warn"}],"note":"剂量以 2023 ESC ACS 指南与药品说明书为准；HIT 禁用肝素、改用比伐芦定或阿加曲班。","refs":["2023 ESC 急性冠脉综合征管理指南","2024 中国经皮冠状动脉介入治疗指南","冠心病双联抗血小板治疗中国专家共识（2021）"]},{"id":"dapt_duration","name":"DAPT 疗程决策","aka":["双联抗血小板疗程"],"cat":"抗栓/出血","rank":84,"desc":"按缺血/出血风险与支架类型决定双联抗血小板疗程。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"高出血风险（ARC-HBR）","criteria":"DAPT 1–3 个月后转为 P2Y12 单药（ACS）或 SAPT（CCS），优先替格瑞洛/氯吡格雷单药","level":"warn"},{"label":"标准 ACS 患者","criteria":"DAPT 12 个月（阿司匹林 + 替格瑞洛/氯吡格雷），出血低危且缺血高危者可考虑 >12 个月","level":"ok"},{"label":"标准 CCS（DES）","criteria":"DAPT 6 个月，随后 SAPT 长期","level":"ok"},{"label":"合并口服抗凝（房颤）","criteria":"三联抗栓 1–4 周（出血高危更短），后 NOAC + 单抗血小板（多为氯吡格雷）12 个月，再单用 OAC","level":"warn"},{"label":"复杂 PCI（左主干/多支/长病变）","criteria":"缺血高危者 DAPT 12 个月以上，需评估出血风险，可延至 30 个月","level":"ok"}],"note":"替格瑞洛禁用于既往颅内出血；氯吡格雷需注意 CYP2C19 慢代谢。AF + PCI 的三联/双联方案以 2023 ESC ACS 与 2024 ESC 房颤指南为准。","refs":["2023 ESC 急性冠脉综合征管理指南","2024 中国经皮冠状动脉介入治疗指南","冠心病双联抗血小板治疗中国专家共识（2021）"]},{"id":"statin_intensity","name":"他汀强度分级","aka":["Statin intensity"],"cat":"血脂","rank":85,"desc":"他汀类降 LDL-C 强度分级与常用剂量速查。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"高强度（LDL-C 降 ≥50%）","criteria":"阿托伐他汀 40–80 mg qd；瑞舒伐他汀 20–40 mg qd（中国患者常用 20 mg，40 mg 需谨慎）","level":"ok"},{"label":"中等强度（LDL-C 降 30%–49%）","criteria":"阿托伐他汀 10–20 mg；瑞舒伐他汀 5–10 mg；辛伐他汀 20–40 mg；普伐他汀 40 mg；氟伐他汀 80 mg；匹伐他汀 2–4 mg","level":"ok"},{"label":"低强度（LDL-C 降 <30%）","criteria":"辛伐他汀 10 mg；普伐他汀 10–20 mg；氟伐他汀 20–40 mg；匹伐他汀 1 mg","level":"ok"},{"label":"联合治疗","criteria":"他汀 + 依折麦布 10 mg qd（额外降 15%–20%）；仍不达标加 PCSK9 抑制剂（依洛尤单抗 140 mg q2w / 阿利西尤单抗 150 mg q2w）；或 inclisiran","level":"warn"},{"label":"注意事项","criteria":"监测 ALT、CK；肌肉症状 CK >5×ULN 需停药评估；糖尿病、CKD 患者剂量调整遵说明书；东亚人群剂量宜偏低","level":"warn"}],"note":"中国患者对高强度他汀耐受性低于欧美，常采用中等强度 + 联合依折麦布达到目标。剂量以说明书为准。","refs":["中国血脂管理指南（2023 年）","2019 ESC/EAS 血脂异常管理指南"]},{"id":"acls_epi_dose_cardio","name":"心脏骤停肾上腺素给药时机","aka":["ACLS 肾上腺素","CPR 药物"],"cat":"ACS","rank":86,"desc":"按心律类型与时间给出肾上腺素/胺碘酮使用要点。","inputs":[],"compute":"formula_only","interpret":[],"levels":[{"label":"不可除颤心律（PEA/心停）","criteria":"尽早给予肾上腺素 1 mg 静推，每 3–5 min 一次（2020 AHA）","level":"crit"},{"label":"可除颤心律（VF/pVT）","criteria":"第 2 次除颤后给肾上腺素 1 mg，此后每 3–5 min；胺碘酮 300 mg 静推（第 3 次除颤后），可再 150 mg","level":"crit"},{"label":"可除颤心律（2023 ESC 更新）","criteria":"考虑早期（第 2 次除颤）给肾上腺素，避免每 3–5 min 重复累积剂量过高","level":"warn"},{"label":"可逆病因（5H5T）","criteria":"低氧、低血容量、酸中毒、低/高钾、低体温；张力性气胸、心包压塞、毒素、肺栓塞、冠脉血栓","level":"warn"}],"note":"本条目为用药时机提示，不含个体化剂量推算；儿科按压剂量 0.01 mg/kg（1:10000）。请按最新一期高级生命支持指南执行。","refs":["2020 AHA 心肺复苏与心血管急救指南","2023 ESC 心脏骤停管理指南","2021 中国心脏骤停救治专家共识"]},{"id":"hypertensive_emergency","name":"高血压急症/亚急症判定","aka":["Hypertensive emergency"],"cat":"血压","rank":87,"desc":"按血压水平与靶器官损害判断高血压急症与亚急症。","inputs":[{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":80,"max":300,"step":1,"required":true},{"key":"dbp","label":"舒张压","unit":"mmHg","type":"number","min":30,"max":200,"step":1,"required":true},{"key":"tod","label":"急性靶器官损害（心、脑、肾、眼底、主动脉）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"SBP ≥180 和/或 DBP ≥120 mmHg 时：伴急性靶器官损害为高血压急症，否则为亚急症","compute":"formula_only","algorithm":"function htnEmergency(sbp, dbp, tod):\n  const veryHigh = sbp >= 180 || dbp >= 120\n  if (veryHigh && tod === 1) return '高血压急症'\n  if (veryHigh) return '高血压亚急症'\n  return '非急症'","interpret":[{"when":"sbp >= 180 || dbp >= 120","level":"crit","text":"SBP ≥180 或 DBP ≥120 mmHg：立即评估靶器官损害，伴胸痛/呼吸困难/神经症状/视力障碍者按高血压急症处理。"},{"when":"sbp < 180 && dbp < 120","level":"warn","text":"未达 180/120：按常规血压分级管理，注意症状与既往病史。"}],"note":"高血压急症需静脉降压（如硝普钠、乌拉地尔、尼卡地平），1 h 内 MAP 降幅 ≤25%；主动脉夹层除外（需快速下降）。亚急症口服药 24–48 h 渐进控制。","refs":["中国高血压防治指南（2024 年修订版）","中国高血压急症诊疗规范（2022）","2024 ESC 血压升高与高血压管理指南"]}]},"cts":{"items":[{"id":"cts_euroscore2","name":"EuroSCORE II 心脏手术死亡风险评分","aka":["European System for Cardiac Operative Risk Evaluation II","EuroSCORE II"],"cat":"手术风险","rank":1,"desc":"综合患者、心脏与手术因素预测心脏手术院内/30 天病死率，是心脏外科决策与知情同意的核心工具。","inputs":[{"key":"procedure_pts","label":"手术类型权重（logistic 系数）","type":"select","options":[{"value":0.0061,"label":"CABG（孤立）"},{"value":0.5524,"label":"非 CABG 单瓣手术"},{"value":1.0628,"label":"双瓣手术"},{"value":1.6156,"label":"三瓣及以上手术"},{"value":0.4306,"label":"CABG + 瓣膜手术"},{"value":0.4477,"label":"胸主动脉手术"}],"required":true},{"key":"urgency_pts","label":"手术紧急程度","type":"select","options":[{"value":0,"label":"择期"},{"value":0.3172,"label":"急诊"},{"value":0.7039,"label":"紧急"},{"value":1.3632,"label":"抢救（crash）"}],"required":true},{"key":"comorb_pts","label":"合并症权重合计（仅勾选存在项）","type":"select","options":[{"value":0,"label":"无以下合并症"},{"value":0.5366,"label":"有（已勾选 ≥1 项，见下一项复选）"}],"required":true},{"key":"comorb_list","label":"合并症明细（仅在上一项选择“有”时计入）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"糖尿病（胰岛素治疗）"},{"value":2,"label":"慢性肺病"},{"value":3,"label":"外周动脉疾病 / 术前肌酐 200 μmol/L"},{"value":4,"label":"主动脉瓣狭窄"},{"value":5,"label":"左室功能中度不全（EF 31%–50%）"},{"value":6,"label":"左室功能重度不全（EF 21%–30%）"},{"value":7,"label":"左室功能极重度不全（EF ≤ 20%）"},{"value":8,"label":"近期心肌梗死（90 天内）"},{"value":9,"label":"肺动脉高压（sPAP > 55 mmHg）"},{"value":10,"label":"心内膜炎"},{"value":11,"label":"术前危重状态（ICU、机械通气、正性肌力）"}],"required":false,"hint":"本项为提示性选择，实际 logit 计算需按合并症系数逐项相加，详见 algorithm"},{"key":"biometric_pts","label":"生物测量权重合计","type":"select","options":[{"value":0,"label":"年龄 < 60 岁、女性无特殊计分"},{"value":0.5343,"label":"年龄 60–64 岁"},{"value":1.0686,"label":"年龄 65–69 岁"},{"value":1.6029,"label":"年龄 70–74 岁"},{"value":2.1371,"label":"年龄 ≥ 75 岁（每增加 5 岁约 +0.53）"},{"value":0.2196,"label":"女性"}],"required":true},{"key":"ejection_pts","label":"左室射血分数权重（不含在 biometric 中时选 0）","type":"select","options":[{"value":0,"label":"已在合并症中计入"},{"value":0.2,"label":"EF 31%–50%（中度）"},{"value":0.6,"label":"EF 21%–30%（重度）"},{"value":0.9,"label":"EF ≤ 20%（极重度）"}],"required":false}],"formula":"logit = −5.324537 + 0.5343×年龄段 + 0.2196×女性 + 合并症系数和 + 手术类型系数 + 紧急度系数 + …；预测病死率 = e^logit / (1 + e^logit)，再乘以截距修正","compute":"formula_only","algorithm":"logit = -5.324537\nlogit += ageGroupCoef          # 60–64: 0.5343；65–69: 1.0686；70–74: 1.6029；≥75: 2.1371（每 5 岁 +0.5343）\nif female: logit += 0.2196\nif insulinDiabetes: logit += 0.3545\nif chronicLung: logit += 0.1885\nif extraCardiacArteriopathy: logit += 0.6196\nif renal_creatinine_gt_200: logit += 0.9725\nif criticalPreop: logit += 1.0861\nlogit += nyhaCoef             # NYHA II 0.1075；III 0.5685；IV 1.0945\nif lvef 31-50: logit += 0.2329\nif lvef 21-30: logit += 0.6072\nif lvef <=20: logit += 1.0628\nif recentMI: logit += 0.1520\nif pHTN: logit += 0.1780\nif activeEndocarditis: logit += 0.6196\nlogit += procedureCoef       # 见 inputs 第一项\nlogit += urgencyCoef         # 见 inputs 第二项\nv = round(100 * exp(logit) / (1 + exp(logit)), 2)  # 预测病死率 %","interpret":[{"when":"v < 2","level":"ok","text":"预测病死率 < 2%：低危，可常规推进手术，重点在术后快速康复（ERAS）"},{"when":"v < 5","level":"warn","text":"2%–5%：中危，加强术前优化（贫血、营养、肺功能），心脏团队讨论手术方式"},{"when":"v < 10","level":"high","text":"5%–10%：高危，需 heart team 讨论 TAVI/微创/介入替代方案，充分知情同意"},{"when":"v >= 10","level":"crit","text":"≥ 10%：极高危，原则上优先考虑经导管/杂交方案或非手术治疗，术前需多学科与家属共同决策"}],"note":"本表把 EuroSCORE II 的 logistic 系数做了分组近似，仅用于教学与粗估；正式评估请使用官方在线计算器。EuroSCORE II 系统性高估近年队列风险约 1.3–1.5 倍，不宜作为拒绝手术的唯一依据。","refs":["Nashef SA, et al. Eur J Cardiothorac Surg 2012（EuroSCORE II 原版）","中国心脏外科手术风险评估专家共识（2021）","2021 ESC/EACTS 瓣膜病管理指南"]},{"id":"cts_nyha","name":"NYHA 心功能分级","aka":["New York Heart Association Functional Class","NYHA"],"cat":"术前功能评估","rank":2,"desc":"按体力活动受限程度将心力衰竭症状分为 Ⅰ–Ⅳ 级，是瓣膜病与冠心病的核心手术指征与术前评估项。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ 级","criteria":"体力活动不受限，日常活动不引起疲乏、心悸或呼吸困难","level":"ok"},{"label":"Ⅱ 级","criteria":"体力活动轻度受限，休息时无症状，日常活动即引起疲乏、心悸或呼吸困难","level":"ok"},{"label":"Ⅲ 级","criteria":"体力活动明显受限，休息时无症状，低于日常活动即引起症状","level":"warn"},{"label":"Ⅳ 级","criteria":"不能从事任何体力活动，休息时亦有症状，活动后加重","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"Ⅰ–Ⅱ 级症状轻，先优化药物治疗；Ⅲ–Ⅳ 级提示重度症状负担，评估手术/介入指征与术前风险"}],"note":"NYHA 为主观分级，重复性有限，建议结合 6 分钟步行试验与 NT-proBNP；重症主动脉瓣狭窄出现 NYHA Ⅲ–Ⅳ 级即为手术（或 TAVI）I 类指征。","refs":["2021 ESC/EACTS 心脏瓣膜病管理指南","中国慢性心力衰竭诊治指南（2024）","2020 ESC 房颤管理指南（NYHA 分层）"]},{"id":"cts_ccs","name":"CCS 心绞痛分级","aka":["Canadian Cardiovascular Society Angina Class","CCS"],"cat":"术前功能评估","rank":3,"desc":"按诱发心绞痛的体力活动强度分为 Ⅰ–Ⅳ 级，评估冠心病患者症状严重度并指导血运重建决策。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ 级","criteria":"日常活动（如步行、上楼）不引起心绞痛；剧烈、快速或长时间劳动时发作","level":"ok"},{"label":"Ⅱ 级","criteria":"日常活动轻度受限：快步走、上楼、餐后、寒冷或情绪激动时发作","level":"ok"},{"label":"Ⅲ 级","criteria":"日常活动明显受限：平地步行 1–2 个街区或登一层楼即发作","level":"warn"},{"label":"Ⅳ 级","criteria":"不能从事任何体力活动，休息时亦可出现心绞痛","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"Ⅰ–Ⅱ 级以药物治疗 + 运动康复为主；Ⅲ 级评估血运重建；Ⅳ 级按 ACS 流程紧急处理"}],"note":"CCS Ⅳ 级或静息心绞痛提示不稳定型心绞痛，需按 ACS 流程评估；左主干或三支病变者出现 CCS Ⅲ–Ⅳ 级，CABG 优于 PCI（SYNTAX 评分高时更明显）。","refs":["2023 ESC 急性冠脉综合征管理指南","2024 ESC 慢性冠脉综合征管理指南","中国稳定性冠心病诊断与治疗指南（2018）"]},{"id":"cts_ariscat","name":"ARISCAT 术后肺部并发症风险指数","aka":["Assess Respiratory Risk in Surgical Patients in Catalonia","ARISCAT"],"cat":"手术风险","rank":4,"desc":"基于 7 项术前因素预测全麻手术后肺部并发症（PPC）风险，指导术前肺康复与麻醉策略。","inputs":[{"key":"age_pts","label":"年龄","type":"select","options":[{"value":0,"label":"≤ 50 岁"},{"value":3,"label":"51–80 岁"},{"value":16,"label":"> 80 岁"}],"required":true},{"key":"spo2_pts","label":"术前 SpO₂","type":"select","options":[{"value":0,"label":"≥ 96%"},{"value":8,"label":"91%–95%"},{"value":24,"label":"≤ 90%"}],"required":true},{"key":"resp_infection","label":"术前 1 个月内呼吸道感染","type":"select","options":[{"value":0,"label":"无"},{"value":17,"label":"有"}],"required":true},{"key":"anemia","label":"术前贫血（Hb < 100 g/L）","type":"select","options":[{"value":0,"label":"无"},{"value":11,"label":"有"}],"required":true},{"key":"incision_pts","label":"手术切口部位","type":"select","options":[{"value":0,"label":"外周"},{"value":15,"label":"上腹部 / 胸腔"},{"value":24,"label":"腹腔内 / 下腹部"}],"required":true},{"key":"duration_pts","label":"手术时长","type":"select","options":[{"value":0,"label":"< 2 小时"},{"value":16,"label":"2–3 小时"},{"value":23,"label":"> 3 小时"}],"required":true},{"key":"emergency","label":"急诊手术","type":"select","options":[{"value":0,"label":"否"},{"value":8,"label":"是"}],"required":true}],"formula":"总分 = 年龄 + SpO₂ + 呼吸道感染 + 贫血 + 切口部位 + 手术时长 + 急诊（0–123 分）","compute":"sum","interpret":[{"when":"v < 26","level":"ok","text":"< 26 分：低危，PPC 发生率约 1.6%，常规术后呼吸训练与早期活动"},{"when":"v < 45","level":"warn","text":"26–44 分：中危，PPC 发生率约 13.3%，术前戒烟、肺功能训练、术中肺保护通气"},{"when":"v >= 45","level":"high","text":"≥ 45 分：高危，PPC 发生率约 42%，需术前 2–4 周肺康复、纠正贫血、术后计划性 ICU 监护与高频胸壁振荡"}],"note":"ARISCAT 队列以欧洲人群为主，国内研究提示阈值可调整；对胸外科切除手术，需与 ppoFEV1/ppoDLCO 结合评估。","refs":["Canet J, et al. Anesthesiology 2010（ARISCAT 原版）","2021 中国成人术后肺部并发症防治专家共识"]},{"id":"cts_ppo","name":"肺切除术后预计肺功能（ppoFEV1 / ppoDLCO）","aka":["predicted postoperative FEV1","ppoFEV1","ppoDLCO","肺叶切除术后预测肺功能"],"cat":"术前功能评估","rank":1,"desc":"用肺段法估算切除后残存肺功能，判断患者能否耐受肺叶/全肺切除。","inputs":[{"key":"fev1","label":"术前 FEV1","unit":"L","type":"number","min":0.3,"max":6,"step":0.01,"required":true},{"key":"dlco","label":"术前 DLCO","unit":"mL/min/mmHg","type":"number","min":5,"max":40,"step":0.1,"required":true},{"key":"resection_segments","label":"拟切除的肺段数","type":"select","options":[{"value":1,"label":"1 段（楔形/单段切除）"},{"value":2,"label":"2 段（下叶基底段等）"},{"value":3,"label":"3 段（左肺上叶或右肺上叶）"},{"value":5,"label":"5 段（左肺下叶 / 右肺中叶+下叶）"},{"value":10,"label":"10 段（全肺切除）"}],"required":true},{"key":"total_segments","label":"患者肺总段数","type":"select","options":[{"value":19,"label":"19 段（左肺 9 + 右肺 10）"},{"value":20,"label":"20 段（简化全肺）"}],"required":true}],"formula":"ppoFEV1 = 术前 FEV1 × (1 − 切除段数 / 总段数)；ppoDLCO 同理","compute":"formula_only","algorithm":"ratio = 1 - resection_segments / total_segments\nppo_fev1 = fev1 * ratio\nppo_dlco = dlco * ratio\nv = round(ppo_fev1, 2)\nppo_dlco_pct = round(100 * ppo_dlco / dlco, 0)   # 相对术前百分比","interpret":[{"when":"v >= 1.2","level":"ok","text":"ppoFEV1 ≥ 1.2 L：可耐受肺叶切除，术后风险可接受，按 ERAS 流程"},{"when":"v >= 0.8","level":"warn","text":"ppoFEV1 0.8–1.2 L：处于边界，需加做运动试验（爬楼梯 ≥ 22 m 或 6MWT > 400 m）与心肺运动试验"},{"when":"v < 0.8","level":"crit","text":"ppoFEV1 < 0.8 L：肺功能储备不足，避免全肺切除；若确需切除，需 VO₂max > 10 mL/kg/min 支持并计划术后呼吸支持"}],"note":"ppoDLCO < 30% 预计值或 VO₂max < 10 mL/kg/min 同样提示高风险。肺叶切除一般弃用全肺公式，改用肺段法（本表）；上叶切除时残腔代偿更好，实际术后功能常优于估算。","refs":["2013 ACCP 肺癌切除术前生理评估指南","中国胸外科围手术期气道管理专家共识（2022 版）","2023 中国肺癌诊疗指南（肺部手术术前评估）"]},{"id":"cts_rcri","name":"RCRI 修订心脏风险指数","aka":["Revised Cardiac Risk Index","RCRI","Lee's Index","改良心脏风险指数"],"cat":"手术风险","rank":2,"desc":"用 6 项术前因素预测非心脏手术主要心脏不良事件（MACE）风险，是胸外科术前心脏评估的标准工具。","inputs":[{"key":"ihd","label":"缺血性心脏病（心绞痛、既往心梗、PCI/CABG 史）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"hf","label":"心力衰竭病史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"cvd","label":"脑血管疾病（卒中 / TIA）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"insulin","label":"需胰岛素治疗的糖尿病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"cr","label":"术前肌酐 > 176.8 μmol/L（2 mg/dL）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"RCRI = 危险因素个体数（0–6，含手术类型分层：高危手术记 1 分）","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：MACE 风险约 0.4%，无需额外心脏检查，直接手术"},{"when":"v == 1","level":"ok","text":"1 分：MACE 风险约 0.9%，按功能储备评估（如能爬 2 层楼可行手术）"},{"when":"v == 2","level":"warn","text":"2 分：MACE 风险约 6.6%，建议心脏彩超 + 心电图复查，优化 β 阻滞剂与容量状态"},{"when":"v >= 3","level":"high","text":"≥ 3 分：MACE 风险约 11%–15%，需心内科会诊、术后 ICU 监护，必要时延期手术完成心脏评估"}],"note":"本表按原 6 因素（含手术类型）设计，实际临床常用 5 个患者因素 + 手术风险分层；RCRI 对 MACE 预测精度中等，建议与 NT-proBNP（> 300 pg/mL 提示风险升高）联合使用。","refs":["2014 ACC/AHA 非心脏手术围手术期心血管评估指南","2022 ESC 非心脏手术围手术期心血管评估与管理指南","中国非心脏手术围手术期心血管风险评估专家共识（2020）"]},{"id":"cts_caprini","name":"Caprini 静脉血栓栓塞风险评分","aka":["Caprini Risk Assessment Model","RAM"],"cat":"手术风险","rank":3,"desc":"按患者、手术与化验指标累加静脉血栓栓塞（VTE）危险因素，指导外科术后血栓预防强度。","inputs":[{"key":"age_pts","label":"年龄","type":"select","options":[{"value":0,"label":"≤ 40 岁"},{"value":1,"label":"41–60 岁"},{"value":2,"label":"61–74 岁"},{"value":3,"label":"≥ 75 岁"}],"required":true},{"key":"bmi_over","label":"BMI > 25 kg/m²","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"surgery_type","label":"手术类型","type":"select","options":[{"value":1,"label":"小手术（< 45 分钟）"},{"value":2,"label":"大手术（> 45 分钟）"},{"value":3,"label":"开胸 / 开腹 / 腔镜大手术（> 2 小时）"}],"required":true},{"key":"malignancy","label":"恶性肿瘤或化疗中","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"varicose","label":"静脉曲张 / 下肢水肿","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"bedridden","label":"卧床 > 72 小时或石膏固定","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"history_vte","label":"既往 VTE 史 / 家族性血栓倾向","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true},{"key":"central_line","label":"中心静脉置管 / 机械通气","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Caprini 总分 = 各危险因素权重之和（≥ 5 分为高危及极高危）","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：低/中危，使用梯度压力袜 + 早期活动，一般无需药物预防（开胸手术仍建议评估）"},{"when":"v <= 8","level":"warn","text":"5–8 分：高危，建议低分子肝素预防（依诺肝素 40 mg qd）或 IPC，术后 24 小时内启动"},{"when":"v >= 9","level":"high","text":"≥ 9 分：极高危，药物 + 机械联合预防，出院后延长预防至 4 周（肿瘤/胸外科大手术），并筛查出血风险"}],"note":"本表为精简版（部分权重合并），与官方 40 项表结果可能差 1–3 分；已在用抗凝药者需评估出血；严重血小板减少（< 50×10⁹/L）或颅内出血急性期禁用药物预防。","refs":["中国普通外科静脉血栓栓塞症预防指南（2021 版）","2021 CHEST 抗栓治疗指南（VTE 预防）","Caprini JA, et al. Thromb Haemost 2005"]},{"id":"cts_tnm_lung","name":"TNM 肺癌分期说明（第 9 版）","aka":["TNM staging lung cancer","IASLC 第 9 版","NSCLC 分期"],"cat":"肿瘤分期","rank":4,"desc":"非小细胞肺癌与小细胞肺癌的 TNM 分期速查，用于确定分期组、治疗策略与手术可行性。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ 期","criteria":"T1–2 N0 M0：可手术，肺叶切除 + 纵隔淋巴结清扫为首选","level":"ok"},{"label":"Ⅱ 期","criteria":"T1–2 N1 或 T3 N0：手术 + 辅助化疗，ⅡB/ⅢA 部分加辅助免疫治疗","level":"warn"},{"label":"Ⅲ 期","criteria":"T3–4 N1 / N2 或 T1–4 N2：多学科讨论，可手术者行新辅助化免后手术；不可手术者行同步放化疗 + 巩固免疫","level":"warn"},{"label":"Ⅳ 期","criteria":"M1a（胸膜/心包积液、对侧肺结节）、M1b（单一胸外转移）、M1c（多器官转移）：靶向/免疫全身治疗为主","level":"high"},{"label":"小细胞肺癌局限期（LS-SCLC）","criteria":"Ⅰ–Ⅲ 期（T1–4 N0–3 M0，可纳入一个耐受放疗野）：同步化放疗 ± 预防性颅脑照射；T1–2 N0 可考虑手术","level":"warn"},{"label":"小细胞肺癌广泛期（ES-SCLC）","criteria":"Ⅳ 期（T 任何 N 任何 M1a–c）：一线化疗 + 免疫治疗","level":"high"}],"interpret":[{"when":"v >= 0","level":"ok","text":"Ⅰ–Ⅱ 期首选手术；Ⅲ 期需多学科讨论手术或根治性放化疗；Ⅳ 期以全身治疗为主；SCLC 局限期同步放化疗，广泛期化疗 + 免疫"}],"note":"第 9 版肺癌 TNM（2026 年起临床推行）对 N 分期、T 大小分组与 M 描述有调整；实际分期须结合病理类型与 EBUS/纵隔镜病理结果，影像分期不能替代纵隔病理分期。","refs":["IASLC 第 9 版肺癌 TNM 分期（Rami-Porta R, et al. J Thorac Oncol 2024）","中国原发性肺癌诊疗指南（2024 版）","NCCN 非小细胞肺癌临床实践指南（2024 v3）"]}]},"derm":{"items":[{"id":"derm_pasi","name":"银屑病面积与严重度指数 PASI","aka":["Psoriasis Area and Severity Index","PASI"],"cat":"银屑病","desc":"按头颈、上肢、躯干、下肢 4 个部位的红斑、浸润、鳞屑（各 0–4 分）乘以面积系数与部位权重，总分 0–72，评估银屑病严重度与疗效。","inputs":[{"key":"head_e","label":"头部红斑（E）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"head_i","label":"头部浸润（I）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"head_d","label":"头部鳞屑（D）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"head_area","label":"头部受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"upper_e","label":"上肢红斑（E）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"upper_i","label":"上肢浸润（I）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"upper_d","label":"上肢鳞屑（D）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"upper_area","label":"上肢受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"trunk_e","label":"躯干红斑（E）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"trunk_i","label":"躯干浸润（I）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"trunk_d","label":"躯干鳞屑（D）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"trunk_area","label":"躯干受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"lower_e","label":"下肢红斑（E）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"lower_i","label":"下肢浸润（I）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"lower_d","label":"下肢鳞屑（D）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：显著"},{"value":4,"label":"4：极重"}],"required":true},{"key":"lower_area","label":"下肢受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true}],"formula":"PASI = 0.1×(E头+I头+D头)×A头 + 0.2×(E上肢+I上肢+D上肢)×A上肢 + 0.3×(E躯干+I躯干+D躯干)×A躯干 + 0.4×(E下肢+I下肢+D下肢)×A下肢；面积用 0–6 级（0–100%），总分 0–72","compute":"formula_only","algorithm":"head = 0.1 * (head_e + head_i + head_d) * head_area\nupper = 0.2 * (upper_e + upper_i + upper_d) * upper_area\ntrunk = 0.3 * (trunk_e + trunk_i + trunk_d) * trunk_area\nlower = 0.4 * (lower_e + lower_i + lower_d) * lower_area\nv = Math.round((head + upper + trunk + lower) * 10) / 10\nBSA = (head_area + upper_area + trunk_area + lower_area) / 6 * 100   # 粗略全身面积（%）","interpret":[{"when":"v <= 5","level":"ok","text":"PASI ≤ 5：轻度；以外用糖皮质激素/维生素 D 衍生物为主，可考虑光疗"},{"when":"v <= 10","level":"warn","text":"PASI 5–10：中度；评估 DLQI（> 5 提示影响生活质量），可系统治疗或光疗"},{"when":"v > 10","level":"high","text":"PASI > 10：重度；满足中重度标准（PASI > 10 或 BSA > 10% 或 DLQI > 10），首选系统治疗/生物制剂"}],"note":"按 PASI 75/90 判断疗效：PASI 75 缓解，PASI 90/100 深度缓解；PASI 对躯干四肢权重高，皮损局限于面部/掌跖者宜同时用 DLQI 与特定部位评分。","refs":["Fredriksson T, Pettersson U. Dermatologica 1978（PASI 原版）","中国银屑病诊疗指南（2023 版，中华医学会皮肤性病学分会）","S3 Guideline for the Treatment of Psoriasis Vulgaris（German, 2021 update）"],"rank":1},{"id":"derm_easi","name":"湿疹面积与严重度指数 EASI","aka":["Eczema Area and Severity Index","EASI"],"cat":"湿疹与特应性皮炎","desc":"4 部位红斑、水肿/丘疹、抓痕、苔藓化（各 0–3）乘面积（0–6）与部位系数，总分 0–72，评估特应性皮炎严重度。","inputs":[{"key":"head_s","label":"头颈：严重度（4 项平均，0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"head_area","label":"头颈受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"upper_s","label":"上肢：严重度（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"upper_area","label":"上肢受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"trunk_s","label":"躯干：严重度（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"trunk_area","label":"躯干受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true},{"key":"lower_s","label":"下肢：严重度（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"lower_area","label":"下肢受累面积比例","type":"select","options":[{"value":0,"label":"0：0%"},{"value":1,"label":"1：1–9%"},{"value":2,"label":"2：10–29%"},{"value":3,"label":"3：30–49%"},{"value":4,"label":"4：50–69%"},{"value":5,"label":"5：70–89%"},{"value":6,"label":"6：90–100%"}],"required":true}],"formula":"EASI = 0.1×(E+Ex+L+Lic)头×A头 + 0.2×上肢×A + 0.3×躯干×A + 0.4×下肢×A；总分 0–72（成人）；儿童头颈/下肢系数为 0.2/0.3","compute":"formula_only","algorithm":"head = 0.1 * head_s * head_area\nupper = 0.2 * upper_s * upper_area\ntrunk = 0.3 * trunk_s * trunk_area\nlower = 0.4 * lower_s * lower_area\nv = Math.round((head + upper + trunk + lower) * 10) / 10","interpret":[{"when":"v <= 1","level":"ok","text":"EASI ≤ 1：缓解/几乎无皮损；维持保湿剂与弱效外用药，随访 3 个月"},{"when":"v <= 7","level":"ok","text":"EASI 1.1–7：轻度；加用中效糖皮质激素与钙调磷酸酶抑制剂，评价诱因与保湿"},{"when":"v <= 21","level":"warn","text":"EASI 7.1–21：中度；评估光疗、系统性免疫抑制剂或生物制剂（dupilumab 等），查 SCORAD 与 DLQI"},{"when":"v <= 50","level":"high","text":"EASI 21.1–50：重度；生物制剂/Janus 激酶抑制剂指征，评估睡眠与心理负担"},{"when":"v > 50","level":"crit","text":"EASI > 50：极重度；注意继发感染（细菌/疱疹性湿疹）与红皮病，及时系统治疗与住院"}],"note":"EASI 的 4 项体征为红斑、水肿/丘疹、抓痕、苔藓化，各取平均（0–3）；评分时至少 2 周内避免使用外用药于评价区域。","refs":["Hanifin JM et al. Exp Dermatol 2001（EASI 原版）","中国特应性皮炎诊疗指南（2020 版，中华医学会皮肤性病学分会）","AAD Guidelines of Care for the Management of Atopic Dermatitis 2014"],"rank":2},{"id":"derm_scorad","name":"特应性皮炎 SCORAD","aka":["SCORing Atopic Dermatitis","SCORAD"],"cat":"湿疹与特应性皮炎","desc":"结合皮损范围（A）、严重度（B，6 项 0–3）与主观症状（C，瘙痒+失眠 0–10）计算，总分 0–103，欧洲常用 AD 综合评估工具。","inputs":[{"key":"extent_pct","label":"皮损面积占体表百分比（%BSA）","unit":"%","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"erythema","label":"红斑（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"edema","label":"水肿/丘疹（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"oozing","label":"渗出/结痂（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"excoriation","label":"抓痕（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"lichenification","label":"苔藓化（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"dryness","label":"皮肤干燥（0–3）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"}],"required":true},{"key":"pruritus","label":"瘙痒 VAS（0–10）","unit":"分","type":"number","min":0,"max":10,"step":1,"required":true},{"key":"insomnia","label":"失眠 VAS（0–10）","unit":"分","type":"number","min":0,"max":10,"step":1,"required":true}],"formula":"SCORAD = A/5 + 7B/2 + C；A 为皮损面积 %，B = 6 项严重度之和（0–18），C = 瘙痒 + 失眠（0–20）；总分 0–103","compute":"formula_only","algorithm":"A = extent_pct\nB = erythema + edema + oozing + excoriation + lichenification + dryness\nC = pruritus + insomnia\nv = Math.round((A / 5 + 7 * B / 2 + C) * 10) / 10","interpret":[{"when":"v < 25","level":"ok","text":"SCORAD < 25：轻度；外用治疗 + 保湿剂，避免刺激物与过热"},{"when":"v <= 50","level":"warn","text":"SCORAD 25–50：中度；评估光疗或系统性治疗，注意金黄色葡萄球菌定植与过敏原"},{"when":"v > 50","level":"high","text":"SCORAD > 50：重度；系统治疗（环孢素、甲氨蝶呤、生物制剂），必要时短期全身激素"}],"note":"SCORAD 含主观症状，儿童与精神障碍患者可用客观 SCORAD（oSCORAD，仅 A+B）；与 EASI 不可直接互换。","refs":["European Task Force on Atopic Dermatitis. Dermatology 1993（SCORAD 原版）","中国特应性皮炎诊疗指南（2020 版）","Willan Practical Guide to Dermatology Scoring（2017）"],"rank":3},{"id":"derm_dlqi","name":"皮肤病生活质量指数 DLQI","aka":["Dermatology Life Quality Index","DLQI"],"cat":"生活质量","desc":"10 项自评（症状、日常、休闲、工作、人际、衣着、运动、性、治疗负担），总分 0–30，量化皮肤病对生活质量的影响。","inputs":[{"key":"q1","label":"瘙痒、刺痛或疼痛","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q2","label":"尴尬或自卑","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q3","label":"影响购物、做家务或庭院工作","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q4","label":"影响所穿衣物选择","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q5","label":"影响社交或休闲活动","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q6","label":"影响运动锻炼","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q7","label":"影响工作或学习","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q8","label":"影响人际关系（亲友、伴侣）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q9","label":"影响性生活","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true},{"key":"q10","label":"治疗带来的麻烦（如涂药、占时间）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻微"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：很严重"}],"required":true}],"formula":"DLQI = 10 项之和（每项 0–3 分），总分 0–30","compute":"sum","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：对生活质量无影响"},{"when":"v <= 5","level":"ok","text":"2–5 分：轻度影响；常规外用治疗，关注患者依从性"},{"when":"v <= 10","level":"warn","text":"6–10 分：中度影响；评估系统治疗或光疗获益"},{"when":"v <= 20","level":"high","text":"11–20 分：很大影响；考虑系统治疗/生物制剂，筛查抑郁（PHQ-9）"},{"when":"v > 20","level":"crit","text":"21–30 分：极大影响；优先系统治疗，必要时心理干预"}],"note":"DLQI 用于成人，儿童用 CDLQI；0–1 可视为临床缓解界值，疗效评价常以 ≥ 5 分下降为有临床意义。","refs":["Finlay AY, Khan GK. Clin Exp Dermatol 1994（DLQI 原版）","中国银屑病诊疗指南（2023 版）","BAD Guidance on DLQI Scoring（British Association of Dermatologists）"],"rank":4},{"id":"derm_acne_grade","name":"痤疮严重度分级（Pillsbury）","aka":["Acne Severity Grading","Pillsbury 分级"],"cat":"痤疮","desc":"按皮损类型（粉刺、炎性丘疹、脓疱、结节囊肿）与数量分为轻、中、重度（Ⅰ–Ⅳ 级），指导治疗选择。","inputs":[{"key":"acne_grade","label":"选择最接近的分级表现","type":"select","options":[{"value":1,"label":"Ⅰ：以黑头/白头粉刺为主"},{"value":2,"label":"Ⅱ：散在炎性丘疹与脓疱，总数 < 30"},{"value":3,"label":"Ⅲ：多发炎性丘疹、脓疱，30–100 个"},{"value":4,"label":"Ⅳ：结节、囊肿为主，或总数 > 100 伴瘢痕"}],"required":true}],"formula":"按主要皮损类型与数量分 Ⅰ–Ⅳ 级（Pillsbury 分类），中国指南对应轻、中度、重度、重度","compute":"formula_only","levels":[{"label":"轻度（Ⅰ 级）","criteria":"以黑头/白头粉刺为主，散在炎性丘疹，总数 < 10","level":"ok"},{"label":"中度（Ⅱ 级）","criteria":"粉刺与炎性丘疹/脓疱，总数 10–30 个","level":"warn"},{"label":"重度（Ⅲ 级）","criteria":"多发炎性丘疹、脓疱，总数 30–100 个，可有结节","level":"high"},{"label":"重度-Ⅳ 级","criteria":"以结节、囊肿为主，总数 > 100 个，伴瘢痕或系统症状","level":"crit"}],"interpret":[{"when":"acne_grade <= 1","level":"ok","text":"轻度：外用维 A 酸（阿达帕林）+ 过氧苯甲酰，疗程 12 周，注意防晒与保湿"},{"when":"acne_grade == 2","level":"warn","text":"中度：外用联合，若炎性皮损为主加口服四环素类（多西环素 100 mg qd，8–12 周）"},{"when":"acne_grade == 3","level":"high","text":"重度：口服异维 A 酸（0.5 mg/kg/d 起，累积剂量 120–150 mg/kg）或口服抗生素联合，女性评估高雄激素"},{"when":"acne_grade >= 4","level":"crit","text":"Ⅳ 级/暴发性痤疮：系统治疗 + 糖皮质激素短期，警惕聚合性痤疮与瘢痕，早干预避免毁容"}],"note":"使用口服异维 A 酸前查血脂、肝功能，育龄女性严格避孕（妊娠致畸分级 X）；暴发性痤疮需排除系统感染。","refs":["中国痤疮治疗指南（2019 修订版，中国痤疮治疗共识组）","AAD Guidelines of Care for the Management of Acne Vulgaris 2016","Global Alliance to Improve Outcomes in Acne: Evidence-based Recommendations 2018"],"rank":5},{"id":"derm_psoriasis_bsa","name":"银屑病体表面积（BSA）与严重度分层","aka":["Body Surface Area for Psoriasis","BSA 65 法则"],"cat":"银屑病","desc":"用「手掌法」（患者一掌约 1% BSA）估算皮损面积，结合 PASI 与 DLQI 将银屑病分为轻、中、重度。","inputs":[{"key":"hands","label":"受累皮损折合的患者手掌数（1 掌 ≈ 1% BSA）","unit":"掌","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"pasi_val","label":"PASI 分值","unit":"分","type":"number","min":0,"max":72,"step":0.1,"required":true},{"key":"dlqi_val","label":"DLQI 分值（0–30）","unit":"分","type":"number","min":0,"max":30,"step":1,"required":true}],"formula":"BSA(%) ≈ 手掌数 × 1%；严重度：轻度 = BSA ≤ 10% 且 PASI ≤ 10 且 DLQI ≤ 10；否则中重度","compute":"formula_only","algorithm":"v = hands   # % BSA\nif hands <= 10 && pasi_val <= 10 && dlqi_val <= 10:\n  severity = '轻度'\nelif hands <= 10 && (pasi_val > 10 || dlqi_val > 10):\n  severity = '中度'\nelse:\n  severity = '重度'\n# 特殊部位（面部、掌跖、生殖器、头皮）受累可升级为中重度","interpret":[{"when":"hands <= 10 && pasi_val <= 10 && dlqi_val <= 10","level":"ok","text":"轻度：BSA ≤ 10% 且 PASI ≤ 10、DLQI ≤ 10；外用治疗 ± 光疗为主"},{"when":"hands <= 30 && pasi_val <= 20","level":"warn","text":"中度：建议光疗、系统性免疫抑制剂或生物制剂，3 个月内评估 PASI 75"},{"when":"hands <= 100","level":"high","text":"中重度–重度：系统治疗或生物制剂指征；筛查结核、肝炎（HBV/HCV）及恶性肿瘤，女性备孕评估"},{"when":"true","level":"crit","text":"几乎全身受累：警惕红皮病型/脓疱型银屑病，需住院、静脉补液、体温与电解质监测"}],"note":"掌跖受累、面部/生殖器受累即使 BSA < 10% 也可按「因部位失能」升级为中重度；BSA 与 PASI 常不一致，需两者同时记录。","refs":["中国银屑病诊疗指南（2023 版）","S3 Guideline for the Treatment of Psoriasis Vulgaris（German, 2021）","NICE Guideline: Psoriasis – Assessment and Management（2012，更新 2017）"],"rank":6},{"id":"derm_npuap","name":"压疮/NPUAP 分期（2016 版）","aka":["Pressure Injury Staging","NPUAP/EPUAP Pressure Injury Classification"],"cat":"创面与压力性损伤","desc":"按组织损伤深度与是否可见床垫面分为 1–4 期、不可分期与深部组织损伤（DTI），指导换药与减压策略。","inputs":[{"key":"stage","label":"创面表现","type":"select","options":[{"value":1,"label":"1 期：完好皮肤指压不变白的红斑"},{"value":2,"label":"2 期：部分皮层缺失，浅表溃疡或血疱"},{"value":3,"label":"3 期：全层皮肤缺失，可见皮下脂肪，但骨/肌腱/肌肉未外露"},{"value":4,"label":"4 期：全层皮肤与组织缺失，骨/肌腱/肌肉外露"},{"value":5,"label":"不可分期：全层缺失，被腐肉/焦痂覆盖"},{"value":6,"label":"深部组织损伤（DTI）：完整或破损皮肤下持续指压不变白深红斑/紫斑"}],"required":true}],"formula":"按创面深度与组织可见性直接分 1–4 期、不可分期、DTI（NPUAP 2016 术语：pressure injury，取代 pressure ulcer）","compute":"formula_only","levels":[{"label":"1 期","criteria":"皮肤完整，指压不变白的红斑，常见于骨隆突处；深肤色者可为紫红色或蓝色","level":"warn"},{"label":"2 期","criteria":"部分皮层缺失，浅表开放性溃疡或完整/破裂的血性水疱，无腐肉","level":"warn"},{"label":"3 期","criteria":"全层皮肤缺失，可见皮下脂肪，无骨、肌腱、肌肉外露；可能有腐肉/潜行","level":"high"},{"label":"4 期","criteria":"全层皮肤与组织缺失，骨、肌腱、肌肉暴露，常有潜行与窦道","level":"crit"},{"label":"不可分期","criteria":"全层皮肤与组织缺失，溃疡床被腐肉/焦痂覆盖，清除后重新分期","level":"high"},{"label":"深部组织损伤（DTI）","criteria":"完整或破损皮肤下持续性指压不变白的深红斑/紫斑，提示深部组织损伤","level":"high"}],"interpret":[{"when":"stage == 1","level":"warn","text":"1 期：减压（翻身 2 h 计划、减压床垫）、营养支持、保持皮肤清洁干燥，加强 Braden 评估"},{"when":"stage == 2","level":"warn","text":"2 期：水胶体/泡沫敷料保护，避免摩擦剪切，必要时消毒后覆盖"},{"when":"stage == 3","level":"high","text":"3 期：清创（自溶性/酶/器械）+ 泡沫敷料或负压治疗（NPWT），监测感染"},{"when":"stage == 4","level":"crit","text":"4 期：多学科（外科/骨科/整形）评估清创与皮瓣，排查骨髓炎（骨探及），需营养科介入"},{"when":"stage == 5","level":"high","text":"不可分期：足跟稳定焦痂可保留，其余部位需清创后重新分期；评估血供（ABI）"},{"when":"true","level":"high","text":"DTI：禁止按摩，立即减压并观察 48–72 h，常迅速演变为 3/4 期，需全面评估营养（白蛋白、前白蛋白）"}],"note":"期别不可逆（不能治愈后「退回」1 期，只能描述为愈合）；忌用「褥疮」等旧称；不可分期与 DTI 均不应计为 1–4 期统计。","refs":["NPUAP/EPUAP/PPPIA International Guideline（2014）与 NPUAP 2016 分期修订","中国压疮（压力性损伤）预防和治疗指南（2019）","NPIAP Pressure Injury Stages（2016）"],"rank":7},{"id":"derm_tbsa","name":"烧伤面积九分法与 TBSA 估算","aka":["Wallace Rule of Nines","TBSA","体表面积烧伤估算"],"cat":"创面与压力性损伤","desc":"按 Wallace 九分法估算成人烧伤总面积（TBSA），并结合 Lund-Browder 法（儿童）指导补液与转诊。","inputs":[{"key":"head","label":"头颈（成人 9%，儿童 18%）","unit":"%","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"trunk_front","label":"躯干前面","unit":"%","type":"number","min":0,"max":18,"step":0.5,"required":true},{"key":"trunk_back","label":"躯干后面","unit":"%","type":"number","min":0,"max":18,"step":0.5,"required":true},{"key":"arm_r","label":"右上肢","unit":"%","type":"number","min":0,"max":9,"step":0.5,"required":true},{"key":"arm_l","label":"左上肢","unit":"%","type":"number","min":0,"max":9,"step":0.5,"required":true},{"key":"leg_r","label":"右下肢（含臀部）","unit":"%","type":"number","min":0,"max":20,"step":0.5,"required":true},{"key":"leg_l","label":"左下肢（含臀部）","unit":"%","type":"number","min":0,"max":20,"step":0.5,"required":true},{"key":"perineum","label":"会阴/生殖器","unit":"%","type":"number","min":0,"max":1,"step":1,"required":true}],"formula":"TBSA = 头颈 + 躯干前 + 躯干后 + 双臂 + 双腿 + 会阴；成人九分法（头 9、躯干前后各 18、每上肢 9、每下肢 18、会阴 1）","compute":"sum","algorithm":"v = head + trunk_front + trunk_back + arm_r + arm_l + leg_r + leg_l + perineum\n# 仅计 II 度及 III 度（浅 II 度可计入，I 度不计）\n# 儿童需按 Lund-Browder 调整：头 18%（1 岁）→9%（成人），每下肢 14%","interpret":[{"when":"v < 10","level":"ok","text":"TBSA < 10%：门急诊处理，创面覆盖 + 止痛，注意破伤风免疫"},{"when":"v < 20","level":"warn","text":"10–19%：需静脉补液（Parkland：4 mL/kg/%TBSA × 体重，可先按 2 mL 评估），转烧伤科"},{"when":"v < 30","level":"high","text":"20–29%：烧伤 ICU 监护，注意气道损伤、低体温与液体负荷"},{"when":"v <= 60","level":"crit","text":"30–60%：重度烧伤，需气管插管（吸入性损伤）、肠道营养与早期切痂"},{"when":"v > 60","level":"crit","text":"TBSA > 60%：特重度，预测死亡率高（Baux/Abbreviated Burn Severity Index 结合年龄评估），转中心"}],"note":"TBSA 只计 II 度以上烧伤；吸入性损伤、环状焦痂需立即切开减张；儿童与老年人面积估算需专门图表（Lund-Browder）。","refs":["Wallace AB. Lancet 1951（九分法原版）","中华医学会烧伤外科学分会：中国烧伤休克防治指南（2015）","ABA Advanced Burn Life Support (ABLS) Provider Manual 2018"],"rank":8},{"id":"derm_sjs_ten","name":"SJS/TEN 严重度（SCORTEN）","aka":["SCORTEN","Stevens-Johnson Syndrome / TEN Severity Score"],"cat":"创面与压力性损伤","desc":"7 项指标预测中毒性表皮坏死松解（TEN）死亡率，用于早期分层与 ICU/烧伤单元收治决策。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":0,"max":120,"step":1,"required":true},{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"bsa_detached","label":"已剥离表皮面积（TBSA，%）","unit":"%","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"bun_mmol","label":"血清尿素（BUN）","unit":"mmol/L","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"glucose","label":"血糖","unit":"mmol/L","type":"number","min":1,"max":60,"step":0.1,"required":true},{"key":"bicarbonate","label":"碳酸氢根","unit":"mmol/L","type":"number","min":1,"max":40,"step":1,"required":true},{"key":"malignancy","label":"合并恶性肿瘤","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"SCORTEN 7 项各计 1 分：年龄 > 40、心率 > 120、表皮剥离 > 10% BSA、BUN > 10 mmol/L（28 mg/dL）、血糖 > 14 mmol/L（252 mg/dL）、HCO3− < 20 mmol/L、恶性肿瘤","compute":"formula_only","algorithm":"s = 0\ns += age > 40 ? 1 : 0\ns += hr > 120 ? 1 : 0\ns += bsa_detached > 10 ? 1 : 0\ns += bun_mmol > 10 ? 1 : 0\ns += glucose > 14 ? 1 : 0\ns += bicarbonate < 20 ? 1 : 0\ns += malignancy\nv = s   # 入院 24 h 内计算，第 3 天复评","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：预测病死率约 3.2%；普通病房或烧伤单元观察，停用可疑药物，创面覆盖"},{"when":"v == 2","level":"warn","text":"2 分：预测病死率约 12%；转入烧伤 ICU/皮肤科重症病房，多学科会诊（眼科、口腔）"},{"when":"v == 3","level":"high","text":"3 分：预测病死率约 35%；ICU 监护，考虑 IVIG/环孢素/血浆置换（证据等级低）"},{"when":"v >= 4","level":"crit","text":"≥ 4 分：预测病死率 > 50%；重症 ICU、感染预防、液体与营养支持，与家属沟通预后"}],"note":"SCORTEN 需在入院 24 h 内计算且第 3 天复评；药物性 SJS/TEN 停用可疑药是核心治疗；眼部受累 24 h 内眼科干预防止瘢痕。","refs":["Bastuji-Garin S et al. J Invest Dermatol 2000（SCORTEN 原版）","中国指南：中毒性表皮坏死松解型药疹诊治专家共识（2021）","SJS/TEN Clinical Guideline（European Academy of Dermatology, 2017）"],"rank":9},{"id":"derm_braden","name":"Braden 压疮风险评估","aka":["Braden Scale","压疮风险评分"],"cat":"创面与压力性损伤","desc":"从感知、潮湿、活动、移动、营养、摩擦剪切 6 个维度评估压力性损伤风险，总分 6–23，是最常用的压疮风险量表。","inputs":[{"key":"sensory","label":"感知能力（1–4）","type":"select","options":[{"value":1,"label":"1：完全受限"},{"value":2,"label":"2：非常受限"},{"value":3,"label":"3：轻度受限"},{"value":4,"label":"4：无损害"}],"required":true},{"key":"moisture","label":"潮湿程度（1–4）","type":"select","options":[{"value":1,"label":"1：持续潮湿"},{"value":2,"label":"2：非常潮湿"},{"value":3,"label":"3：偶尔潮湿"},{"value":4,"label":"4：很少潮湿"}],"required":true},{"key":"activity","label":"活动能力（1–4）","type":"select","options":[{"value":1,"label":"1：卧床"},{"value":2,"label":"2：坐位"},{"value":3,"label":"3：偶尔行走"},{"value":4,"label":"4：经常行走"}],"required":true},{"key":"mobility","label":"移动能力（1–4）","type":"select","options":[{"value":1,"label":"1：完全不能"},{"value":2,"label":"2：严重受限"},{"value":3,"label":"3：轻度受限"},{"value":4,"label":"4：不受限"}],"required":true},{"key":"nutrition","label":"营养摄取（1–4）","type":"select","options":[{"value":1,"label":"1：非常差"},{"value":2,"label":"2：可能不足"},{"value":3,"label":"3：充足"},{"value":4,"label":"4：良好"}],"required":true},{"key":"friction","label":"摩擦与剪切力（1–3）","type":"select","options":[{"value":1,"label":"1：已有问题"},{"value":2,"label":"2：有潜在问题"},{"value":3,"label":"3：无明显问题"}],"required":true}],"formula":"Braden = 感知（1–4）+ 潮湿（1–4）+ 活动（1–4）+ 移动（1–4）+ 营养（1–4）+ 摩擦剪切（1–3），总分 6–23","compute":"sum","interpret":[{"when":"v <= 9","level":"crit","text":"≤ 9 分：极高风险；每日评估，实施减压计划（翻身 2 h、独立减压垫），必要时使用减压敷料"},{"when":"v <= 12","level":"high","text":"10–12 分：高风险；每 2–3 天复评，系统减压与营养干预（蛋白 1.2–1.5 g/kg/d）"},{"when":"v <= 14","level":"warn","text":"13–14 分：中度风险；每周评估，规律翻身与皮肤护理"},{"when":"v <= 18","level":"ok","text":"15–18 分：低至中度风险（部分指南界值为 18）；加强皮肤观察与移动计划"},{"when":"v > 18","level":"ok","text":"> 18 分：风险较低；常规护理与每周筛查"}],"note":"Braden 各医院常采用 18/19 为高危界值；不能替代临床判断，手术、ICU、临终患者需更频繁评估。低分子肝素、麻醉等不是评估维度。","refs":["Bergstrom N, Braden B et al. Nursing Research 1987（Braden 原版）","中国压疮（压力性损伤）预防和治疗指南（2019）","EPUAP/NPIAP/PPPIA International Guideline（2019）"],"rank":10},{"id":"derm_vitiligo_vasi","name":"白癜风面积评分指数（VASI）","aka":["Vitiligo Area Scoring Index","VASI"],"cat":"色素性疾病","desc":"对手、上肢、躯干、下肢等部位的白斑脱色程度（分级）与受累面积（单位换算）加权求和，评估白癜风严重度与疗效。","inputs":[{"key":"hands_units","label":"手部脱色单位数（1 单位 = 1% BSA）","unit":"单位","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"upper_units","label":"上肢脱色单位数","unit":"单位","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"trunk_units","label":"躯干脱色单位数","unit":"单位","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"lower_units","label":"下肢脱色单位数","unit":"单位","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"face_units","label":"头面部脱色单位数","unit":"单位","type":"number","min":0,"max":100,"step":0.5,"required":true},{"key":"depig_fraction","label":"平均脱色程度（可观察区域）","type":"select","options":[{"value":0,"label":"0：无脱色"},{"value":0.1,"label":"10%"},{"value":0.25,"label":"25%"},{"value":0.5,"label":"50%"},{"value":0.75,"label":"75%"},{"value":0.9,"label":"90%"},{"value":1,"label":"100% 完全脱色"}],"required":true}],"formula":"VASI = 0.1×(手部单位×脱色%) + 0.2×(上肢单位×脱色%) + 0.3×(躯干单位×脱色%) + 0.4×(下肢单位×脱色%)；以手掌为 1 单位（约 1% BSA）","compute":"formula_only","algorithm":"frac = depig_fraction\nv = 0.1 * hands_units * frac + 0.2 * upper_units * frac + 0.3 * trunk_units * frac + 0.4 * lower_units * frac\n# 面部单位仅作补充观察（原量表不含面部加权），不进入 v\nvasi = Math.round(v * 10) / 10","interpret":[{"when":"v <= 1","level":"ok","text":"VASI ≤ 1：局限/轻度；外用钙调磷酸酶抑制剂或激素 + NB-UVB 局部照射"},{"when":"v <= 10","level":"warn","text":"1.1–10：中度；NB-UVB（2–3 次/周）联合外用，评估是否稳定期"},{"when":"v <= 25","level":"high","text":"10.1–25：扩散型；系统治疗（小剂量激素短期、JAK 抑制剂、甲氨蝶呤）并筛查甲状腺抗体与维生素 D"},{"when":"v > 25","level":"high","text":"> 25：广泛受累；考虑自体表皮移植/黑素细胞移植（稳定期 ≥ 6 个月），注意心理支持与防晒"}],"note":"VASI 对面积依赖「手掌单位」估算，面颈与手部虽面积小但对生活质量影响大；儿童用 VASI 或 VES，建议拍照前后对比。","refs":["Hamzavi I et al. Arch Dermatol 2004（VASI 原版）","中国白癜风诊疗指南（2021 版，中华医学会皮肤性病学分会）","Vitiligo Global Issues Consensus Conference（2012）"],"rank":11}]},"emerg":{"items":[{"id":"emerg_gcs","name":"格拉斯哥昏迷评分（GCS）","aka":["Glasgow Coma Scale","GCS"],"cat":"意识与神经急症","rank":1,"desc":"以睁眼（E1–4）、语言（V1–5）、运动（M1–6）三项评估意识水平，总分 3–15 分，是创伤与急危重症分层的核心指标。","inputs":[{"key":"e","label":"睁眼反应（E）","type":"select","options":[{"value":4,"label":"自发睁眼"},{"value":3,"label":"呼唤后睁眼"},{"value":2,"label":"疼痛刺激后睁眼"},{"value":1,"label":"无睁眼反应"}],"required":true},{"key":"v","label":"语言反应（V）","type":"select","options":[{"value":5,"label":"回答正确、定向力正常"},{"value":4,"label":"回答混乱（可对话但答非所问）"},{"value":3,"label":"不恰当词语"},{"value":2,"label":"无法理解的声音/呻吟"},{"value":1,"label":"无发声"},{"value":"t","label":"插管（T）：记为 1 分，另注 E、M 推算"}],"required":true,"hint":"气管插管者语言项记 1 分并标注 T"},{"key":"m","label":"运动反应（M）","type":"select","options":[{"value":6,"label":"按指令动作"},{"value":5,"label":"疼痛定位（有目的推开）"},{"value":4,"label":"疼痛躲避（屈曲回撤）"},{"value":3,"label":"异常屈曲（去皮质强直）"},{"value":2,"label":"异常伸展（去大脑强直）"},{"value":1,"label":"无运动反应"}],"required":true}],"formula":"GCS = E（1–4）+ V（1–5）+ M（1–6），总分 3–15；插管者分数标注为「GCSe+m 分（T）」","compute":"sum","algorithm":"v = e + m + ?（V 选 T 时 / 语言项不计分，按 e + m + 1 计算并标注 T）","interpret":[{"when":"v >= 13","level":"ok","text":"13–15 分：轻度意识障碍或清醒，继续监测意识变化与瞳孔（每 1–2 小时复评，GCS 下降 ≥2 分立即复查头颅 CT）"},{"when":"v >= 9","level":"warn","text":"9–12 分：中度意识障碍，禁食禁水、留置胃管、密切监测，寻找病因（低血糖、中毒、颅内病变）"},{"when":"v >= 3","level":"crit","text":"3–8 分：重度昏迷，GCS ≤8 分需保护气道（气管插管），评估颅内压、启动高级生命支持"}],"note":"单看总分可掩盖单项恶化：M 项权重最大，M ≤4 提示脑干功能受累。需结合瞳孔、肢体偏瘫与格拉斯哥-列日（GLS）评估。镇静镇痛及低血糖状态下评分不可靠。","refs":["Teasdale G, Jennett B. Lancet 1974;2:81-84（GCS 原版）","中国颅脑创伤外科手术指南（2018）","AHA/ASA 自发性脑出血管理指南（2022）"]},{"id":"emerg_news2","name":"英国国家早期预警评分（NEWS2）","aka":["National Early Warning Score 2","NEWS2"],"cat":"预警与病情分层","rank":2,"desc":"按 7 项生理参数（含 SpO2 量表与吸氧状态）识别病情恶化风险，总分 0–20，用于急诊留观与病房的分级监测与升级处置。","inputs":[{"key":"rr","label":"呼吸频率","unit":"次/分","type":"number","min":4,"max":60,"step":1,"required":true},{"key":"spo2_scale2","label":"是否使用 SpO2 量表 2（高碳酸血症型呼吸衰竭，目标 88%–92%）","type":"select","options":[{"value":0,"label":"否（量表 1，目标 94%–98%）"},{"value":1,"label":"是（量表 2）"}],"required":true},{"key":"spo2","label":"SpO2","unit":"%","type":"number","min":50,"max":100,"step":1,"required":true},{"key":"o2","label":"是否吸氧","type":"select","options":[{"value":0,"label":"否（空气）"},{"value":2,"label":"是（任何氧气治疗）"}],"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":30,"max":300,"step":1,"required":true},{"key":"hr","label":"脉率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"avpu","label":"意识（ACVPU）","type":"select","options":[{"value":0,"label":"清醒（A）"},{"value":3,"label":"新发意识混乱（C）"},{"value":3,"label":"对声音有反应（V）/ 对疼痛有反应（P）/ 无反应（U）"}],"required":true},{"key":"temp","label":"体温","unit":"°C","type":"number","min":30,"max":44,"step":0.1,"required":true}],"formula":"NEWS2 = RR 分 + SpO2 分 + 吸氧分（0/2）+ SBP 分 + 脉率分 + ACVPU 分（0/3）+ 体温分；各参数分档：RR ≤8=3、9–11=1、12–20=0、21–24=2、≥25=3；SpO2（量表 1）≤91=3、92–93=2、94–95=1、≥96=0；SBP ≤90=3、91–100=2、101–110=1、111–219=0、≥220=3；脉率 ≤40=3、41–50=1、51–90=0、91–110=1、111–130=2、≥131=3；体温 ≤35.0=3、35.1–36.0=1、36.1–38.0=0、38.1–39.0=1、≥39.1=2","compute":"formula_only","algorithm":"sR = rr<=8?3 : rr<=11?1 : rr<=20?0 : rr<=24?2 : 3\n// SpO2 量表 1\nsS = spo2<=91?3 : spo2<=93?2 : spo2<=95?1 : 0\n// 量表 2（高碳酸血症）：≤83=3、84–85=2、86–87=1、88–92=0、93–94=1、95–96=2、≥97=3\nif spo2_scale2 == 1: sS = spo2<=83?3 : spo2<=85?2 : spo2<=87?1 : spo2<=92?0 : spo2<=94?1 : spo2<=96?2 : 3\nsB = sbp<=90?3 : sbp<=100?2 : sbp<=110?1 : sbp<=219?0 : 3\nsP = hr<=40?3 : hr<=50?1 : hr<=90?0 : hr<=110?1 : hr<=130?2 : 3\nsT = temp<=35.0?3 : temp<=36.0?1 : temp<=38.0?0 : temp<=39.0?1 : 2\nv = sR + sS + o2 + sB + sP + avpu + sT\nred = any(sR==3 || sS==3 || sB==3 || sP==3 || avpu==3)","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：低风险，常规监测（每 4–12 小时复评），按科室常规护理"},{"when":"red == 1 || v >= 7","level":"crit","text":"7 分及以上，或任一单项 3 分：高风险，立即通知上级医师、转入抢救室/重症监护评估，启动急救团队（每 30 分钟–1 小时复评）"},{"when":"v >= 5","level":"warn","text":"5–6 分：中风险，1 小时内由医生评估，提高监测频率（每 1 小时复评），准备升级监护"},{"when":"v == 3 && red == 0","level":"warn","text":"3 分：低-中风险，医生评估并增加复评频次（至少每 4–6 小时）"}],"note":"慢性阻塞性肺疾病/Ⅱ 型呼吸衰竭患者改用 SpO2 量表 2，否则会因目标饱和度偏低被反复误判为高危。NEWS2 不适用于 16 岁以下儿童及产科患者。","refs":["Royal College of Physicians. National Early Warning Score (NEWS) 2, 2017（update 2019 修订）","中国急诊危重症患者病情严重程度评分专家共识（2021）"]},{"id":"emerg_shock_index","name":"休克指数（SI）","aka":["Shock Index","心率收缩压比值"],"cat":"循环与休克","rank":3,"desc":"心率除以收缩压，反映循环储备，在血压尚正常的「代偿期」即提示失血或休克。","inputs":[{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":30,"max":300,"step":1,"required":true}],"formula":"SI = 心率 / 收缩压；改良休克指数 MSI = 心率 / 平均动脉压","compute":"formula_only","algorithm":"v = round(hr / sbp, 2)","interpret":[{"when":"v < 0.7","level":"low","text":"SI <0.7：可能存在心动过缓或高血压状态，复查并排除药物（β 阻滞剂）影响"},{"when":"v <= 0.9","level":"ok","text":"0.7–0.9：正常范围，仍需结合乳酸、毛细血管再充盈与碱剩余"},{"when":"v <= 1.0","level":"warn","text":"0.9–1.0：临界，警惕隐匿性休克，建议测乳酸与行超声评估容量"},{"when":"v > 1.0","level":"high","text":">1.0：提示循环失代偿（约失血 ≥15%–20% 容量），立即补液/输血并寻找出血源"},{"when":"v >= 1.4","level":"crit","text":"≥1.4：重度休克风险（疑似大出血/脓毒症），启动大量输血方案、复苏团队与损伤控制"}],"note":"服 β 受体阻滞剂或起搏器者心率不可靠；老年、孕妇及运动员的基线 SI 不同。SI 与乳酸联用优于单用血压判断预后。","refs":["Allgöwer M, Burri C. Dtsch Med Wochenschr 1967;92:1947-1950（休克指数原版）","中国急诊感染性休克临床实践指南（2020）","ATLS 第 10 版（2018，血流动力学分级）"]},{"id":"emerg_qsofa","name":"qSOFA 脓毒症快速筛查","aka":["Quick Sequential Organ Failure Assessment","qSOFA"],"cat":"感染与器官功能","rank":4,"desc":"对疑似感染患者床旁快速筛查：RR ≥22 次/分、意识改变、SBP ≤100 mmHg 各 1 分，≥2 分提示预后不良风险增高。","inputs":[{"key":"rr","label":"呼吸频率 ≥22 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"mental","label":"意识状态改变（GCS <15）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"sbp","label":"收缩压 ≤100 mmHg","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"qSOFA = 3 项各 1 分，总分 0–3","compute":"sum","interpret":[{"when":"v >= 2","level":"crit","text":"≥2 分：脓毒症高危，立即测乳酸、血培养、1 小时内广谱抗生素，评估容量与器官灌注（Sepsis-3 的「临床恶化预警」，非确诊工具）"},{"when":"v == 1","level":"warn","text":"1 分：继续筛查（SOFA、乳酸、尿量），每 1–2 小时复评"},{"when":"v == 0","level":"ok","text":"0 分：qSOFA 阴性不排除脓毒症，仍需按临床判断评估感染灶与器官功能"}],"note":"Sepsis-3 明确：qSOFA 用于院外/病房快速识别而非诊断标准，确诊仍用 SOFA 变化 ≥2 分（或乳酸 >2 mmol/L 伴低血压）。2016 年后不推荐 qSOFA 单独替代 SIRS/NEWS。","refs":["Singer M, et al. JAMA 2016;315:801-810（Sepsis-3）","中国脓毒症/脓毒性休克急诊治疗指南（2018）","SCCM/ESICM Surviving Sepsis Campaign Guidelines 2021"]},{"id":"emerg_sofa","name":"SOFA 序贯器官衰竭评分","aka":["Sequential Organ Failure Assessment","SOFA"],"cat":"感染与器官功能","rank":5,"desc":"按呼吸、凝血、肝、循环、中枢、肾脏 6 个系统各 0–4 分评估器官功能障碍，总分 0–24，评分变化 ≥2 分为脓毒症定义要素。","inputs":[{"key":"resp","label":"呼吸：PaO2/FiO2","unit":"mmHg","type":"number","min":30,"max":700,"step":1,"required":true,"hint":"需已按规范计算 P/F 比值"},{"key":"vent","label":"是否机械通气（含无创通气）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"plt","label":"凝血：血小板","unit":"×10^9/L","type":"number","min":5,"max":1000,"step":1,"required":true},{"key":"bili","label":"肝：总胆红素","unit":"μmol/L","type":"number","min":1,"max":700,"step":1,"required":true},{"key":"map_lt70","label":"循环：MAP <70 mmHg","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"vaso","label":"循环：血管活性药物（多巴胺/去甲肾上腺素）","type":"select","options":[{"value":0,"label":"未使用"},{"value":2,"label":"多巴胺 ≤5 或任何剂量多巴酚丁胺"},{"value":3,"label":"多巴胺 >5 或去甲肾上腺素 ≤0.1 μg/(kg·min)"},{"value":4,"label":"多巴胺 >15 或去甲肾上腺素 >0.1 μg/(kg·min)"}],"required":true},{"key":"gcs","label":"中枢：GCS 分值","type":"select","options":[{"value":0,"label":"15 分"},{"value":1,"label":"13–14 分"},{"value":2,"label":"10–12 分"},{"value":3,"label":"6–9 分"},{"value":4,"label":"<6 分"}],"required":true},{"key":"crea","label":"肾：血肌酐","unit":"μmol/L","type":"number","min":10,"max":1500,"step":1,"required":true},{"key":"urine","label":"肾：24 小时尿量","unit":"mL/d","type":"number","min":0,"max":8000,"step":10,"required":false,"hint":"有尿量时取肌酐与尿量评分的较高者"}],"formula":"SOFA = 呼吸分 + 凝血分 + 肝分 + 循环分 + 中枢分 + 肾分（各 0–4），总分 0–24；较基线增加 ≥2 分提示器官功能障碍加重","compute":"formula_only","algorithm":"// 呼吸（P/F，mmHg）\nsResp = resp>=400?0 : resp>=300?1 : (resp>=200 && vent==1)?2 : (resp>=100 && vent==1)?3 : (resp<100 && vent==1)?4 : 2\n// 通气未达标时按无通气分档：≥300 为 1，<300 为 2\nif vent==0: sResp = resp>=400?0 : (resp>=300?1:2)\nsCoag = plt>=150?0 : plt>=100?1 : plt>=50?2 : plt>=20?3 : 4\nsLiv  = bili<20?0 : bili<32?1 : bili<102?2 : bili<204?3 : 4\nsCard = vaso>0 ? vaso : (map_lt70==1?1:0)\nsCNS  = gcs  // 已按 select 映射 0–4\nsRen  = crea<110?0 : crea<170?1 : crea<299?2 : (crea<440 || urine<500)?3 : (crea>=440 || urine<200)?4 : 0\nv = sResp + sCoag + sLiv + sCard + sCNS + sRen","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：器官功能基本正常，需与基线比较（基线常为 0）"},{"when":"v <= 6","level":"warn","text":"2–6 分：器官功能障碍，疑似感染者已达脓毒症（较基线 ≥2 分），需集束化治疗"},{"when":"v <= 12","level":"high","text":"7–12 分：多器官功能障碍，建议入住 ICU，每日复评 SOFA 动态变化"},{"when":"v >= 13","level":"crit","text":"≥13 分：重度器官衰竭，病死率显著升高（>50%），评估 ICU 资源与治疗目标"}],"note":"SOFA 需连续计算（ΔSOFA）而非单次绝对值：24 小时内 SOFA 变化是评估治疗反应与预后的关键。PaO2/FiO2 需在稳定呼吸状态下测定，FiO2 以小数表示。","refs":["Vincent JL, et al. Intensive Care Med 1996;22:707-710（SOFA 原版）","Singer M, et al. JAMA 2016;315:801-810（Sepsis-3）","SCCM/ESICM Surviving Sepsis Campaign Guidelines 2021"]},{"id":"emerg_iss","name":"损伤严重度评分（ISS）","aka":["Injury Severity Score","ISS"],"cat":"创伤评估","rank":6,"desc":"将 6 个身体区域中最重的 3 个损伤区域 AIS 分值平方求和，量化多发伤严重度，判断是否入创伤中心、预测死亡风险。","inputs":[{"key":"highest_ais","label":"最高 AIS 区域：AIS 分值","type":"select","options":[{"value":1,"label":"1（轻度：擦伤、单纯骨折）"},{"value":2,"label":"2（中度：长骨骨折、中度脑挫伤）"},{"value":3,"label":"3（重度：无生命危险）"},{"value":4,"label":"4（严重：危及生命）"},{"value":5,"label":"5（危重：生存不确定）"},{"value":6,"label":"6（致命：存活证据不可得）"}],"required":true},{"key":"second_ais","label":"第二重区域：AIS 分值","type":"select","options":[{"value":0,"label":"无其他区域损伤"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"third_ais","label":"第三重区域：AIS 分值","type":"select","options":[{"value":0,"label":"无其他区域损伤"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true}],"formula":"ISS = AIS₁² + AIS₂² + AIS₃²（取 6 个区域中最高的 3 个区域的 AIS 分值；任一区域 AIS = 6 时 ISS 自动记为 75）","compute":"formula_only","algorithm":"if highest_ais == 6: v = 75\nelse: v = highest_ais^2 + second_ais^2 + third_ais^2  // 范围内 1–75","interpret":[{"when":"v >= 75","level":"crit","text":"AIS 6 或 ISS = 75：极重伤，预后极差，需启动创伤团队最高级别响应与家属沟通"},{"when":"v >= 25","level":"crit","text":"≥25 分：严重多发伤，需创伤中心/ICU，病死率高（>25%），优先损伤控制复苏"},{"when":"v >= 16","level":"high","text":"16–24 分：重伤标准（ISS >15），入创伤中心，多学科会诊、全身 CT 评估"},{"when":"v >= 9","level":"warn","text":"9–15 分：中度损伤，按创伤流程系统排查，观察 24–48 小时"},{"when":"v <= 8","level":"ok","text":"1–8 分：轻度损伤，对症处理与随访"}],"note":"ISS 只计 3 个最重区域，会低估同一区域内多发伤（如双侧硬膜下血肿）；头部单一 AIS 5 + 其他 0（ISS = 25）可能高估。AIS 2005/2008 更新版编码是计分依据。","refs":["Baker SP, et al. J Trauma 1974;14:187-196（ISS 原版）","AAAM AIS 2005 update 2016（损伤严重度编码）","中国创伤救治培训教程（2022）"]},{"id":"emerg_rts","name":"修正创伤评分（RTS）","aka":["Revised Trauma Score","RTS"],"cat":"创伤评估","rank":7,"desc":"以 GCS、收缩压、呼吸频率三项按权重编码求和（0–7.8408），用于院前分诊与 TRISS 预后模型。","inputs":[{"key":"gcs","label":"GCS 分值","type":"select","options":[{"value":4,"label":"13–15 分"},{"value":3,"label":"9–12 分"},{"value":2,"label":"6–8 分"},{"value":1,"label":"4–5 分"},{"value":0,"label":"3 分"}],"required":true},{"key":"sbp","label":"收缩压","type":"select","options":[{"value":4,"label":">89 mmHg"},{"value":3,"label":"76–89 mmHg"},{"value":2,"label":"50–75 mmHg"},{"value":1,"label":"1–49 mmHg"},{"value":0,"label":"0 mmHg（无脉搏）"}],"required":true},{"key":"rr","label":"呼吸频率","type":"select","options":[{"value":4,"label":"10–29 次/分"},{"value":3,"label":">29 次/分"},{"value":2,"label":"6–9 次/分"},{"value":1,"label":"1–5 次/分"},{"value":0,"label":"0 次/分"}],"required":true}],"formula":"编码后 RTS = 0.9368 × GCSc + 0.7326 × SBPc + 0.2908 × RRc，范围 0–7.8408；T-RTS（分诊用）= GCSc + SBPc + RRc（0–12）","compute":"formula_only","algorithm":"v = round(0.9368 * gcs + 0.7326 * sbp + 0.2908 * rr, 4)\ntriage = gcs + sbp + rr  // T-RTS：>11 需重点转运，≤11 需创伤中心","interpret":[{"when":"v >= 7.0","level":"ok","text":"≥7.0：生理状态良好，生存概率高，可转普通急诊处理"},{"when":"v >= 5.5","level":"warn","text":"5.5–7.0：中度生理紊乱，需创伤中心评估，监测是否恶化"},{"when":"v >= 4.0","level":"high","text":"4.0–5.5：严重生理紊乱，直接转创伤中心，启动高级创伤生命支持"},{"when":"v < 4.0","level":"crit","text":"<4.0：生理极度紊乱，高死亡风险（>40%），需复苏优先/损伤控制与抢救团队"}],"note":"RTS 不考虑解剖损伤与年龄；与 ISS、年龄组成 TRISS 模型计算生存概率，用于创伤质量评估。院前分诊常用 T-RTS。","refs":["Champion HR, et al. J Trauma 1989;29:623-629（RTS 原版）","ATLS 第 10 版（2018）","中国创伤中心建设与管理标准（2021）"]},{"id":"emerg_start","name":"START 批量伤员检伤分类","aka":["Simple Triage and Rapid Treatment","START"],"cat":"检伤分类","rank":8,"desc":"灾害/批量伤员场景下用 30–60 秒快速评估自主呼吸、呼吸频率、循环（毛细血管再充盈/脉搏）与意识，将伤员分为红/黄/绿/黑四级。","inputs":[{"key":"can_walk","label":"能否自行走动","type":"select","options":[{"value":1,"label":"能（→ 绿色）"},{"value":0,"label":"不能"}],"required":true},{"key":"breath","label":"开放气道后是否恢复自主呼吸","type":"select","options":[{"value":0,"label":"有自主呼吸"},{"value":1,"label":"开放气道后恢复（→ 红）"},{"value":2,"label":"开放气道后仍无呼吸（→ 黑）"}],"required":true},{"key":"rr","label":"呼吸频率","type":"select","options":[{"value":0,"label":"≤30 次/分"},{"value":1,"label":">30 次/分（→ 红）"}],"required":true},{"key":"perfusion","label":"循环：桡动脉触及 / 毛细血管再充盈","type":"select","options":[{"value":0,"label":"脉搏可及且 CRP ≤2 秒"},{"value":1,"label":"无脉搏或 CRP >2 秒（→ 红）"}],"required":true},{"key":"mental","label":"意识：能否按指令动作","type":"select","options":[{"value":0,"label":"能"},{"value":1,"label":"不能（→ 红）"}],"required":true}],"formula":"依次判定：能行走→绿；无呼吸且开放气道后仍无呼吸→黑；呼吸 >30 次/分、无脉搏/CRP>2 秒或不能按指令→红；其余→黄","compute":"formula_only","algorithm":"v = 0  // 0=绿 1=黄 2=红 3=黑\nif breath == 2: v = 3\nelif can_walk == 1: v = 0\nelif breath == 1 || rr == 1 || perfusion == 1 || mental == 1: v = 2\nelse: v = 1","interpret":[{"when":"v == 3","level":"crit","text":"黑色（期待治疗/死亡）：开放气道后无呼吸，资源匮乏时暂不处理，记录并标记"},{"when":"v == 2","level":"high","text":"红色（立即）：优先转运与急救，气道/呼吸/循环任一异常者 60 秒内完成止血、气道开放"},{"when":"v == 1","level":"warn","text":"黄色（延迟）：生命体征稳定但不能行走，30–60 分钟内评估处理"},{"when":"v == 0","level":"ok","text":"绿色（轻伤/行走伤员）：可自行行走，集中引导至轻伤区并二次评估"}],"note":"START 适用于成人及 >8 岁儿童；儿童（<8 岁）用 JumpSTART（先给 5 次人工呼吸，呼吸 <15 次/分或 >45 次/分归红）。每次重新分类后应更新伤员标签。","refs":["Super G. START: Simple Triage and Rapid Treatment, Hoag Hospital/Newport Beach Fire Dept, 1983（修订版 1994）","化学恐怖袭击批量伤员医学救援指南（2020）","中国创伤救治培训教程（2022）"]},{"id":"emerg_tbsa_wallace","name":"烧伤面积九分法（Wallace）与 TBSA 估算","aka":["Rule of Nines","Wallace Rule of Nines","TBSA"],"cat":"烧伤","rank":9,"desc":"以成人身体各区域占体表面积百分比的九分法估算烧伤面积，是液体复苏与分诊的依据；儿童需调整头颈与下肢比例。","inputs":[{"key":"mode","label":"使用方式","type":"select","options":[{"value":1,"label":"成人：逐区勾选累加"},{"value":2,"label":"快速估算：仅填总面积"}],"required":true},{"key":"total_direct","label":"已估算的烧伤总面积 TBSA（模式 2 填写）","unit":"%","type":"number","min":0,"max":100,"step":1,"required":false},{"key":"head","label":"头面颈（成人 9%，儿童 18%）","type":"select","options":[{"value":0,"label":"未烧伤"},{"value":9,"label":"全部 9%"},{"value":4.5,"label":"约一半 4.5%"}],"required":false},{"key":"trunk_front","label":"躯干前面（18%，含胸部腹部）","type":"select","options":[{"value":0,"label":"未烧伤"},{"value":18,"label":"全部 18%"},{"value":9,"label":"约一半 9%"}],"required":false},{"key":"trunk_back","label":"躯干后面（18%）","type":"select","options":[{"value":0,"label":"未烧伤"},{"value":18,"label":"全部 18%"},{"value":9,"label":"约一半 9%"}],"required":false},{"key":"each_arm","label":"每侧上肢（9%，含前后）","type":"select","options":[{"value":0,"label":"两上肢均未烧伤"},{"value":9,"label":"一侧 9%"},{"value":18,"label":"双侧 18%"}],"required":false},{"key":"each_leg","label":"每侧下肢（成人 18%，儿童 13.5%/侧）","type":"select","options":[{"value":0,"label":"两下肢均未烧伤"},{"value":18,"label":"一侧 18%"},{"value":36,"label":"双侧 36%"}],"required":false},{"key":"perineum","label":"会阴（1%）","type":"select","options":[{"value":0,"label":"未烧伤"},{"value":1,"label":"1%"}],"required":false}],"formula":"成人：头颈 9% + 双上肢 18% + 躯干前后 36% + 双下肢 36% + 会阴 1% = 100%；儿童（<10 岁）：头颈 18%、双下肢各 13.5%，其余同成人","compute":"formula_only","algorithm":"if mode == 2: v = total_direct\nelse: v = head + trunk_front + trunk_back + each_arm + each_leg + perineum  // 0–100","interpret":[{"when":"v < 10","level":"ok","text":"<10%：轻中度烧伤，门诊/烧伤病房处理，创面护理 + 镇痛，评估吸入性损伤"},{"when":"v < 20","level":"warn","text":"10%–19%：中度烧伤，建立静脉通路、按 Parkland 补液，警惕休克"},{"when":"v < 30","level":"high","text":"20%–29%：重度烧伤，转烧伤中心，开始晶体液复苏、监测尿量"},{"when":"v >= 30","level":"crit","text":"≥30%：特重度烧伤，需高级烧伤中心，气道评估（吸入性损伤可能）、大量补液与多学科管理"}],"note":"只计Ⅱ度以上（深Ⅱ度、Ⅲ度）烧伤面积；Ⅰ 度（红斑）不计。大面积烧伤用 Lund-Browder 图表更准确；手掌法（患者手掌约 1% TBSA）用于散在小面积估算。含颜面、手、会阴、关节、环形烧伤或吸入性损伤、电击伤、化学烧伤者不论面积均需烧伤中心处理。","refs":["中国烧伤早期救治专家共识（2018）","ABLS Advanced Burn Life Support Course Manual（2018）","WHO 烧伤管理实践指南（2018）"]},{"id":"emerg_parkland","name":"Parkland 补液公式（烧伤液体复苏）","aka":["Parkland Formula","Baxter 公式"],"cat":"烧伤","rank":10,"desc":"按烧伤后 24 小时乳酸林格液总量估算（4 mL × 体重 × TBSA%），前 8 小时输一半，后续以尿量滴定。","inputs":[{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":10,"max":250,"step":0.5,"required":true},{"key":"tbsa","label":"烧伤面积 TBSA（Ⅱ度及Ⅲ度）","unit":"%","type":"number","min":1,"max":100,"step":1,"required":true},{"key":"hours_since","label":"自受伤至开始补液的时间","unit":"小时","type":"number","min":0,"max":24,"step":0.5,"required":true,"hint":"前 8 小时从受伤时刻起算，非从到院时间起算"}],"formula":"24 小时总量 = 4 mL × 体重（kg）× TBSA（%）；前 8 小时（自受伤起）输入总量的一半，余下 16 小时输另一半；液体首选乳酸林格液","compute":"formula_only","algorithm":"total = 4 * weight_kg * tbsa  // mL/24h\nfirst8_rate = (total / 2) / 8  // mL/h，前 8 小时速率\nrest = hours_since >= 8 ? 0 : (8 - hours_since) * first8_rate  // 尚需在前 8 小时窗口内补入的量\nremaining16 = total - total / 2\nv = round(total, 0)  // 主结果：24 小时总量（mL）","interpret":[{"when":"tbsa >= 20","level":"crit","text":"TBSA ≥20%：已达到静脉复苏指征，立即启动 4 mL/kg/%TBSA，目标成人尿量 0.5 mL/(kg·h)（儿童 1 mL/(kg·h)）"},{"when":"tbsa >= 15","level":"high","text":"TBSA 15%–19%：多数指南建议静脉复苏，同时评估气道、镇痛与转运烧伤中心"},{"when":"tbsa >= 10","level":"warn","text":"TBSA 10%–14%：口服/静脉补液均可，合并吸入性损伤、儿童或老年人倾向于静脉补液"},{"when":"tbsa < 10","level":"ok","text":"<10%：一般无需按公式静脉复苏，口服补液与镇痛，创面处理为主"}],"note":"公式仅为起始估算：必须根据尿量动态调整，避免液体过负荷（「液体蠕变」）。儿童（<30 kg）需额外加维持量（4-2-1 法则）。电击伤、吸入性损伤、多发伤需个体化上调。","refs":["Baxter CR. Surg Clin North Am 1974;54:1391-1410（Parkland 公式原版）","中国烧伤早期救治专家共识（2018）","ISBI Practice Guidelines for Burn Care（2016）"]},{"id":"emerg_apache2","name":"APACHE Ⅱ 评分","aka":["Acute Physiology and Chronic Health Evaluation II","APACHE II"],"cat":"预警与病情分层","rank":11,"desc":"由 12 项急性生理指标、年龄与慢性健康状况三部分求和（0–71），用于入 ICU 24 小时内病情严重度分层与病死率预测。","inputs":[{"key":"temp_c","label":"体温（直肠）","unit":"°C","type":"number","min":30,"max":44,"step":0.1,"required":true},{"key":"map","label":"平均动脉压","unit":"mmHg","type":"number","min":20,"max":200,"step":1,"required":true},{"key":"hr","label":"心率","unit":"次/分","type":"number","min":20,"max":250,"step":1,"required":true},{"key":"rr","label":"呼吸频率","unit":"次/分","type":"number","min":0,"max":70,"step":1,"required":true},{"key":"pf","label":"氧合：PaO2/FiO2","type":"select","options":[{"value":0,"label":"FiO2 <0.5 且 PaO2 >70 mmHg，或 FiO2 ≥0.5 且 P/F >350"},{"value":2,"label":"FiO2 <0.5 且 PaO2 61–70 mmHg，或 FiO2 ≥0.5 且 P/F 200–350"},{"value":3,"label":"FiO2 <0.5 且 PaO2 55–60 mmHg，或 FiO2 ≥0.5 且 P/F 100–199"},{"value":4,"label":"FiO2 <0.5 且 PaO2 <55 mmHg，或 FiO2 ≥0.5 且 P/F <100"}],"required":true},{"key":"ph","label":"动脉血 pH","type":"select","options":[{"value":4,"label":"≥7.70"},{"value":3,"label":"7.60–7.69"},{"value":1,"label":"7.50–7.59"},{"value":0,"label":"7.33–7.49"},{"value":2,"label":"7.25–7.32"},{"value":3,"label":"7.15–7.24"},{"value":4,"label":"<7.15"}],"required":true},{"key":"sodium","label":"血钠","unit":"mmol/L","type":"number","min":90,"max":200,"step":1,"required":true},{"key":"potassium","label":"血钾","unit":"mmol/L","type":"number","min":1,"max":10,"step":0.1,"required":true},{"key":"creatinine","label":"血肌酐（是否急性肾衰竭）","type":"select","options":[{"value":0,"label":"<53 μmol/L（无 ARF）"},{"value":1,"label":"53–124 μmol/L 或急性肾衰竭 <124"},{"value":2,"label":"125–172 μmol/L（无 ARF）"},{"value":3,"label":"178–304 μmol/L 或急性肾衰竭 133–304"},{"value":4,"label":"≥305 μmol/L 或急性肾衰竭 ≥305"}],"required":true},{"key":"hct","label":"血细胞比容","unit":"%","type":"number","min":10,"max":70,"step":0.1,"required":true},{"key":"wbc","label":"白细胞","unit":"×10^9/L","type":"number","min":0.1,"max":200,"step":0.1,"required":true},{"key":"gcs","label":"GCS（APACHE 用 15 − GCS 计分）","type":"select","options":[{"value":0,"label":"15 分"},{"value":1,"label":"13–14 分"},{"value":2,"label":"11–12 分"},{"value":3,"label":"8–10 分"},{"value":4,"label":"5–7 分"},{"value":5,"label":"3–4 分"}],"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":16,"max":110,"step":1,"required":true},{"key":"chronic","label":"慢性健康状况（严重器官功能不全或免疫抑制）","type":"select","options":[{"value":0,"label":"无重大慢性器官功能不全"},{"value":2,"label":"有，择期术后"},{"value":5,"label":"有，非手术或急诊术后"}],"required":true}],"formula":"APACHE Ⅱ = 12 项急性生理分（A，0–48）+ 年龄分（B，0–6）+ 慢性健康分（C，0–5），总分 0–71；评分取入 ICU 后首个 24 小时内最差值","compute":"formula_only","algorithm":"// 生理分 A（取 24h 最差）\nsT = temp_c>=41?4 : temp_c>=39?3 : temp_c>=38.5?1 : temp_c>=36?0 : temp_c>=34?1 : temp_c>=32?2 : temp_c>=30?3 : 4\nsM = map>=160?4 : map>=130?3 : map>=110?2 : map>=70?0 : map>=50?2 : 4\nsH = hr>=180?4 : hr>=140?3 : hr>=110?2 : hr>=70?0 : hr>=55?2 : hr>=40?3 : 4\nsR = rr>=50?4 : rr>=35?3 : rr>=25?1 : rr>=12?0 : rr>=10?1 : rr>=6?2 : 4\nsNa = sodium>=180?4 : sodium>=160?3 : sodium>=155?2 : sodium>=150?1 : sodium>=130?0 : sodium>=120?2 : sodium>=111?3 : 4\nsK = potassium>=7?4 : potassium>=6?3 : potassium>=5.5?1 : potassium>=3.5?0 : potassium>=3?1 : potassium>=2.5?2 : 4\nsCr = creatinine  // select 已映射 0–4\nsHct = hct>=60?4 : hct>=50?2 : hct>=46?1 : hct>=30?0 : hct>=20?2 : 4\nsWbc = wbc>=40?4 : wbc>=20?2 : wbc>=15?1 : wbc>=3?0 : wbc>=1?2 : 4\nA = sT + sM + sH + sR + pf + ph + sNa + sK + sCr + sHct + sWbc + gcs\nB = age>=75?6 : age>=65?5 : age>=55?3 : age>=45?2 : 0\nv = A + B + chronic","interpret":[{"when":"v <= 9","level":"ok","text":"0–9 分：低危，预计病死率 <10%，常规 ICU 监护"},{"when":"v <= 19","level":"warn","text":"10–19 分：中危，预计病死率 10%–25%，需密切监护与每日复评"},{"when":"v <= 29","level":"high","text":"20–29 分：高危，预计病死率 35%–55%，评估治疗目标与家属沟通"},{"when":"v >= 30","level":"crit","text":"≥30 分：极高危，预计病死率 >70%，考虑资源分配与治疗目标讨论"}],"note":"APACHE Ⅱ 用于群体比较与预后研究，不用于个体治疗的决策依据。缺失值按 0 计（如无血气分析）。死于院内者需用入院 24 小时内最差值；有创通气 PaO2 应取最高 FiO2 时的低值。","refs":["Knaus WA, et al. Crit Care Med 1985;13:818-829（APACHE Ⅱ 原版）","中国重症医学专科资质培训教材（2021）","SAPS 3 与 APACHE IV 比较研究（Intensive Care Med 2007）"]},{"id":"emerg_bg_crisis","name":"血糖危象识别（DKA / HHS / 严重低血糖）","aka":["Diabetic Ketoacidosis","Hyperosmolar Hyperglycemic State","血糖危象分级"],"cat":"代谢急症","rank":12,"desc":"依据血糖、血酮、pH、HCO3−、有效血渗透压与意识状态区分糖尿病酮症酸中毒（DKA）、高渗高血糖状态（HHS）与低血糖，并判定严重度。","inputs":[{"key":"glucose","label":"血糖","unit":"mmol/L","type":"number","min":0.5,"max":80,"step":0.1,"required":true},{"key":"ketone","label":"血 β-羟丁酸","unit":"mmol/L","type":"number","min":0,"max":15,"step":0.1,"required":false,"hint":"尿酮 3+ 约相当于血酮 >3 mmol/L"},{"key":"ph","label":"动脉血 pH","unit":"","type":"number","min":6.4,"max":7.8,"step":0.01,"required":false},{"key":"hco3","label":"HCO3−","unit":"mmol/L","type":"number","min":1,"max":40,"step":1,"required":false},{"key":"osmolality","label":"有效血渗透压（2×Na+ + 血糖）","unit":"mOsm/kg","type":"number","min":200,"max":450,"step":1,"required":false},{"key":"mental","label":"意识状态","type":"select","options":[{"value":0,"label":"清醒"},{"value":1,"label":"嗜睡/反应迟钝"},{"value":2,"label":"昏迷"}],"required":true}],"formula":"DKA：血糖 ≥11.1 mmol/L + 血酮 ≥3.0 mmol/L（或尿酮 3+）+ pH <7.3 和/或 HCO3− <18；HHS：血糖 ≥33.3 mmol/L + 有效渗透压 ≥320 mOsm/kg + pH ≥7.3、HCO3− ≥18、血酮 <3.0","compute":"formula_only","algorithm":"is_hypo = glucose < 3.9\nis_dka  = glucose >= 11.1 && ketone >= 3.0 && (ph < 7.30 || hco3 < 18)\nis_hhs  = glucose >= 33.3 && osmolality >= 320 && (ph >= 7.30 || ph == null) && (ketone < 3.0 || ketone == null)\n// DKA 严重度：轻度 pH 7.25–7.30 / HCO3 15–18；中度 pH 7.00–7.24 / HCO3 10–15；重度 pH <7.00 / HCO3 <10\nv = is_hypo ? -1 : (is_dka ? (ph < 7.00 || hco3 < 10 ? 2 : 1) : (is_hhs ? 3 : (glucose >= 11.1 ? 4 : 0)))","interpret":[{"when":"glucose < 3.9 && glucose >= 2.8","level":"warn","text":"低血糖 2.8–3.9 mmol/L：口服 15–20 g 速效糖或静推 50% 葡萄糖 20–40 mL，15 分钟复测"},{"when":"glucose < 2.8","level":"crit","text":"重度低血糖 <2.8 mmol/L：立即静推 50% 葡萄糖 20–40 mL（或 10% 葡萄糖 150–200 mL），必要时胰高血糖素 1 mg，寻找病因（胰岛素过量、肝衰、肾上腺危象）"},{"when":"ph < 7.00 || hco3 < 10","level":"crit","text":"重度 DKA：转 ICU/高依赖，生理盐水 1–1.5 L/h 起始，小剂量胰岛素 0.1 U/(kg·h)，监测血钾（<3.3 mmol/L 先补钾）、血糖与酮体，每 1–2 小时复查"},{"when":"glucose >= 11.1 && (ketone >= 3.0 || (ph < 7.30 && ph > 7.00))","level":"high","text":"DKA（轻–中度）：补液 + 胰岛素 + 补钾三联，同时寻找诱因（感染、停药、SGLT2i 相关正常血糖性 DKA）"},{"when":"glucose >= 33.3 && (osmolality >= 320 || mental >= 1)","level":"crit","text":"HHS：血糖 ≥33.3 mmol/L + 有效渗透压 ≥320 mOsm/kg，病死率高于 DKA，需 ICU、缓慢降糖（每小时 3–6 mmol/L）、警惕血栓与脑水肿"},{"when":"glucose >= 11.1","level":"warn","text":"高血糖：按 DKA/HHS 流程补查血酮、血气、渗透压与电解质，暂不排除正常血糖性 DKA（SGLT2 抑制剂）"}],"note":"SGLT2 抑制剂相关 DKA 可为正常血糖（<11.1 mmol/L），疑诊时仍需查酮体与 pH。有效渗透压注意校正钠与血糖；血钠正常时补液首选生理盐水，血糖降至 11.1–14 mmol/L 后改为含糖液。","refs":["ADA Standards of Care in Diabetes—2024（Hyperglycemic Crises）","中国糖尿病诊疗指南（2020 版）","中国 2 型糖尿病防治指南（2020 年版）— 糖尿病酮症酸中毒"]},{"id":"emerg_poisoning_severity","name":"中毒严重度评分（PSS）","aka":["Poisoning Severity Score","PSS"],"cat":"中毒","rank":13,"desc":"按器官系统表现将急性中毒分为 0–4 级（无症状→致死），取最重系统定级，用于中毒分级、洗胃/解毒剂决策与预后沟通。","inputs":[{"key":"component","label":"分项（按最重系统逐项判断）","type":"select","options":[{"value":1,"label":"胃肠道"},{"value":2,"label":"呼吸系统"},{"value":3,"label":"心血管系统"},{"value":4,"label":"神经系统"},{"value":5,"label":"肝/肾/血液/代谢等"}],"required":true},{"key":"grade","label":"该系统的表现等级（0–4）","type":"select","options":[{"value":0,"label":"0：无相关症状与体征"},{"value":1,"label":"1（轻度）：轻微/一过性症状，如呕吐、轻度头痛"},{"value":2,"label":"2（中度）：明显症状，如持续呕吐、窦性心动过速、意识模糊"},{"value":3,"label":"3（重度）：危及生命的器官损害，如心律失常、呼吸抑制、昏迷"},{"value":4,"label":"4（致死）：心搏骤停、呼吸停止、多器官衰竭"}],"required":true}],"formula":"PSS = 各系统评分中的最高等级（0 无中毒症状；1 轻度；2 中度；3 重度；4 致死）","compute":"formula_only","algorithm":"v = grade  // 取最重系统等级作为总体分级","interpret":[{"when":"grade == 0","level":"ok","text":"0 级：无中毒表现，观察 4–6 小时（视毒物半衰期），排查可疑毒物并登记随访"},{"when":"grade == 1","level":"warn","text":"1 级（轻度）：对症支持治疗，口服活性炭（1 小时内、无禁忌），监测生命体征 6–12 小时"},{"when":"grade == 2","level":"warn","text":"2 级（中度）：留观或住院，补液/解毒剂（如纳洛酮、氟马西尼、N-乙酰半胱氨酸），必要时洗胃"},{"when":"grade == 3","level":"crit","text":"3 级（重度）：立即入抢救室/ICU，特异性解毒剂（有机磷-阿托品+氯解磷定；CO-高压氧；对乙酰氨基酚-NAC）并联系中毒救治中心"},{"when":"grade == 4","level":"crit","text":"4 级（致死）：心搏骤停/呼吸停止/多器官衰竭，启动高级生命支持与血液净化（血液灌流/透析）评估"}],"note":"PSS 取最重器官系统评分，不能累加；评估时机对结果影响大（摄入后 4–6 小时）。儿童误服、自杀意图患者需同步精神科评估。不明毒物时参考「中毒五项」与尿毒物筛查。","refs":["Persson HE, et al. J Toxicol Clin Toxicol 1998;36:205-213（PSS 原版）","中国急性中毒诊断与治疗专家共识（2019）","EAPCCT/WHO 中毒严重度评分指南（2016 修订）"]},{"id":"emerg_triage_level","name":"急诊分诊分级（五级）","aka":["Emergency Severity Index","ESI","五级分诊"],"cat":"检伤分类","rank":14,"desc":"按病情危急程度将急诊患者分为 1–5 级，决定就诊顺序与响应时限，是急诊拥挤时的标准化分流依据。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ级（复苏）","criteria":"濒死、心搏骤停、严重呼吸窘迫或休克，需立即生命支持（气道、呼吸、循环任一崩溃）","level":"crit"},{"label":"Ⅱ级（危急）","criteria":"潜在致命，需在 10 分钟内接诊：胸痛疑似 ACS、严重创伤、意识改变、剧烈腹痛、高危中毒","level":"high"},{"label":"Ⅲ级（紧急）","criteria":"生命体征不稳定或需多项资源，10–30 分钟内接诊：发热伴感染、中等程度损伤、持续呕吐","level":"warn"},{"label":"Ⅳ级（次紧急）","criteria":"生命体征稳定但病情较重，可等待 30–60 分钟：小骨折、单纯腹痛、轻中度感染","level":"ok"},{"label":"Ⅴ级（非紧急）","criteria":"生命体征稳定，仅需 1 项或无需资源，60 分钟内处理：轻症上感、换药拆线、慢性病复查","level":"ok"}],"note":"ESI/五级分诊均需在到院 5 分钟内完成初次分诊，并在候诊期间动态复评（尤其 Ⅱ–Ⅲ 级患者超过 30 分钟）。分诊等级不替代医生评估，疼痛评分与生命体征变异是升级信号。","refs":["中国急诊预检分诊专家共识（2018）","Emergency Severity Index (ESI) Version 4 Handbook, ENA 2012","国家卫生健康委：急诊科建设与管理指南（试行，2018）"]}]},"endo":{"items":[{"id":"endo_bmi","name":"体质指数（BMI）与中国成人体型判定","aka":["Body Mass Index","BMI 分级"],"cat":"体重管理","rank":1,"desc":"由身高体重计算 BMI，并按中国成人超重/肥胖标准分级。","inputs":[{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":10,"max":300,"step":0.1,"required":true},{"key":"height_cm","label":"身高","unit":"cm","type":"number","min":50,"max":250,"step":0.5,"required":true}],"formula":"BMI = 体重(kg) / 身高(m)²","compute":"bmi","interpret":[{"when":"v < 18.5","level":"warn","text":"BMI 18.5 以下：体重过低，评估营养风险（可与 NRS2002 联用）"},{"when":"v >= 18.5 && v < 24","level":"ok","text":"BMI 18.5–23.9：中国成人正常范围"},{"when":"v >= 24 && v < 28","level":"warn","text":"BMI 24–27.9：超重，建议生活方式干预"},{"when":"v >= 28 && v < 35","level":"high","text":"BMI 28 以上：肥胖，评估代谢综合征并启动减重治疗"},{"when":"v >= 35","level":"crit","text":"BMI ≥ 35：重度肥胖，评估减重药物/代谢手术适应证"}],"note":"中国标准（WS/T 428-2013）以 24/28 为超重/肥胖切点，与 WHO 国际切点 25/30 不同；老年人 BMI 可结合肌少症评估。","refs":["中国成人超重和肥胖预防控制指南（2021）","WS/T 428-2013 成人体重判定"]},{"id":"endo_ibw_adjbw","name":"理想体重与校正体重","aka":["IBW","Adjusted Body Weight"],"cat":"体重管理","rank":2,"desc":"估算理想体重 IBW 与肥胖患者的校正体重，用于给药剂量或能量估算。","inputs":[{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true},{"key":"height_cm","label":"身高","unit":"cm","type":"number","min":120,"max":230,"step":0.5,"required":true},{"key":"actual_kg","label":"实际体重","unit":"kg","type":"number","min":20,"max":300,"step":0.1,"required":false}],"formula":"IBW = 身高(cm) − 105 （男性）；女性 ×0.95；校正体重 = IBW + 0.4×(实际体重 − IBW)","compute":"formula_only","algorithm":"if sex==1: ibw = height_cm - 105; ibw2 = 50 + 0.91*(height_cm-152.4)\nelse: ibw = (height_cm - 105) * 0.95; ibw2 = 45.5 + 0.91*(height_cm-152.4)\nadj = actual_kg ? ibw + 0.4*(actual_kg - ibw) : null\nv = ibw; 输出 ibw(简易法)、ibw2(Devine 法)、adj","interpret":[{"when":"v > 0","level":"ok","text":"理想体重约按上式估算；肥胖者调整剂量时用校正体重（如氨基糖苷、部分吸入麻醉药）"}],"note":"简易法为国内临床常用；Devine 法多用于药物剂量计算。仅作估算，实际用药以说明书为准。","refs":["中国成人超重和肥胖预防控制指南（2021）","中国肥胖及2型糖尿病外科治疗指南（2019）"]},{"id":"endo_bmr","name":"基础代谢率（BMR / Harris-Benedict）","aka":["Basal Metabolic Rate","Harris-Benedict 公式"],"cat":"能量代谢","rank":10,"desc":"估算基础能量消耗，用于营养支持的能量目标设定。","inputs":[{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":15,"max":110,"step":1,"required":true},{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":20,"max":300,"step":0.1,"required":true},{"key":"height_cm","label":"身高","unit":"cm","type":"number","min":120,"max":230,"step":0.5,"required":true}],"formula":"男：BMR = 66.5 + 13.75×W + 5.003×H − 6.775×A；女：BMR = 655.1 + 9.563×W + 1.850×H − 4.676×A（kcal/d）","compute":"formula_only","algorithm":"if sex==1: v = 66.5 + 13.75*weight_kg + 5.003*height_cm - 6.775*age\nelse: v = 655.1 + 9.563*weight_kg + 1.850*height_cm - 4.676*age","interpret":[{"when":"v > 0","level":"ok","text":"按活动系数修正：卧床 1.2、轻度 1.3–1.4、中度 1.5–1.6、重度 1.8–2.0；重症患者按 25–30 kcal/kg/d 估算"}],"note":"肥胖者建议用校正体重；机械通气患者优先间接测热法。","refs":["中国成人患者肠外肠内营养临床应用指南（2023）","ESPEN guidelines on clinical nutrition in the ICU (2019)"]},{"id":"endo_homa_ir","name":"胰岛素抵抗指数（HOMA-IR）与 HOMA-β","aka":["HOMA-IR","HOMA1-IR"],"cat":"能量代谢","rank":12,"desc":"由空腹血糖与空腹胰岛素估算胰岛素抵抗程度与 β 细胞功能。","inputs":[{"key":"fpg","label":"空腹血糖 FPG","unit":"mmol/L","type":"number","min":1,"max":40,"step":0.1,"required":true},{"key":"fins","label":"空腹胰岛素 FINS","unit":"mU/L","type":"number","min":0.1,"max":500,"step":0.1,"required":true}],"formula":"HOMA-IR = FPG(mmol/L)×FINS(mU/L)/22.5；HOMA-β = 20×FINS/(FPG−3.5)","compute":"formula_only","algorithm":"v = fpg*fins/22.5; b = 20*fins/((fpg-3.5)||0.01)","interpret":[{"when":"v < 2.69","level":"ok","text":"HOMA-IR 约 2.69 以下：胰岛素敏感性尚可（中国人群常用参考切点）"},{"when":"v >= 2.69","level":"warn","text":"HOMA-IR ≥ 2.69：提示胰岛素抵抗，建议评估代谢综合征并干预"}],"note":"中国人群切点文献不一致（2.0–2.7）；需空腹 8–10 h，胰岛素检测方法不同不可横向比较；接受胰岛素治疗者不适用。","refs":["中国2型糖尿病防治指南（2020年版）","中国胰岛素抵抗相关临床问题专家共识（2021）"]},{"id":"endo_tyg","name":"甘油三酯-葡萄糖指数（TyG）","aka":["TyG index","Triglyceride-Glucose Index"],"cat":"能量代谢","rank":16,"desc":"由空腹甘油三酯与血糖计算胰岛素抵抗替代指标。","inputs":[{"key":"tg","label":"甘油三酯 TG","unit":"mg/dL","type":"number","min":10,"max":3000,"step":1,"required":true},{"key":"fpg","label":"空腹血糖 FPG","unit":"mg/dL","type":"number","min":18,"max":720,"step":1,"required":true}],"formula":"TyG = ln[TG(mg/dL)×FPG(mg/dL)/2]；TG mg/dL = mmol/L×88.57，FPG mg/dL = mmol/L×18","compute":"formula_only","algorithm":"v = Math.log(tg*fpg/2)","interpret":[{"when":"v < 8.5","level":"ok","text":"TyG 偏低：胰岛素抵抗可能性较小（各家切点 8.3–8.8 不一，需结合人群）"},{"when":"v >= 8.5","level":"warn","text":"TyG 升高：提示胰岛素抵抗，与心血管风险、脂肪肝相关，建议进一步评估"}],"note":"为研究型替代指标，尚无统一临床诊断切点；输入须为 mg/dL。","refs":["中国胰岛素抵抗相关临床问题专家共识（2021）","中国血脂管理指南（2023年）"]},{"id":"endo_ogtt","name":"口服葡萄糖耐量试验（OGTT）判读","aka":["OGTT","75g 葡萄糖耐量试验"],"cat":"糖代谢","rank":4,"desc":"输入空腹与 2 小时血糖，按中国/WHO 标准判读糖代谢状态。","inputs":[{"key":"fpg","label":"空腹血糖","unit":"mmol/L","type":"number","min":1,"max":40,"step":0.1,"required":true},{"key":"pg2h","label":"服糖后 2 h 血糖","unit":"mmol/L","type":"number","min":1,"max":60,"step":0.1,"required":true}],"formula":"依据 FPG 与 2hPG 联合判读","compute":"formula_only","algorithm":"同时输出 fpg 与 pg2h 判定：\nfpg>=7.0 或 pg2h>=11.1 → 糖尿病\nfpg 6.1–6.9 且 pg2h<7.8 → 空腹血糖受损(IFG)\npg2h 7.8–11.0 → 糖耐量减低(IGT)\n均正常 → 正常","interpret":[{"when":"fpg >= 7.0 || pg2h >= 11.1","level":"crit","text":"达糖尿病诊断切点：无典型症状需改日复测确认，或结合 HbA1c ≥ 6.5% 确诊"},{"when":"fpg >= 6.1 || (pg2h >= 7.8 && pg2h < 11.1)","level":"warn","text":"IFG/IGT 糖尿病前期：生活方式干预，每年复查"},{"when":"fpg < 6.1 && pg2h < 7.8","level":"ok","text":"糖代谢正常"}],"note":"试验前停用影响糖代谢药物 3 天以上，空腹 8–10 h，75 g 无水葡萄糖溶于 250–300 mL 水 5 min 内服完；妊娠期用 75 g 诊断 GDM（切点不同）。","refs":["中国2型糖尿病防治指南（2020年版）","WHO 糖尿病诊断标准（2006）"]},{"id":"endo_hba1c_eag","name":"HbA1c 与平均血糖换算（eAG）","aka":["eAG","estimated Average Glucose"],"cat":"糖代谢","rank":6,"desc":"HbA1c（%）与估算平均血糖（mg/dL、mmol/L）互换。","inputs":[{"key":"hba1c","label":"HbA1c","unit":"%","type":"number","min":3,"max":20,"step":0.1,"required":true}],"formula":"eAG(mg/dL) = 28.7×HbA1c − 46.7；eAG(mmol/L) = eAG(mg/dL)/18","compute":"formula_only","algorithm":"v = 28.7*hba1c - 46.7 (mg/dL); mmol = v/18","interpret":[{"when":"hba1c < 7","level":"ok","text":"HbA1c < 7.0%：多数成人 2 型糖尿病控制达标"},{"when":"hba1c >= 7 && hba1c < 8","level":"warn","text":"HbA1c 7.0–8.0%：未达标，复查方案依从性并调整治疗"},{"when":"hba1c >= 8 && hba1c < 9","level":"high","text":"HbA1c 8.0–9.0%：需强化降糖（加用或联合 GLP-1RA/SGLT2i/胰岛素）"},{"when":"hba1c >= 9","level":"crit","text":"HbA1c ≥ 9.0% 或有症状：考虑启动胰岛素治疗"}],"note":"贫血、血红蛋白病、近期输血、妊娠、CKD 晚期可致 HbA1c 失真；换算值为群体回归，个体差异存在。","refs":["中国2型糖尿病防治指南（2020年版）","ADA Standards of Care in Diabetes (2024)"]},{"id":"endo_dm_dx","name":"糖尿病诊断标准分级","aka":["糖尿病诊断切点","糖代谢分类"],"cat":"糖代谢","rank":3,"desc":"按 FPG、OGTT 2hPG、随机血糖与 HbA1c 综合判定糖代谢状态。","inputs":[{"key":"fpg","label":"空腹血糖（可选）","unit":"mmol/L","type":"number","min":0,"max":40,"step":0.1,"required":false},{"key":"pg2h","label":"OGTT 2 h 血糖（可选）","unit":"mmol/L","type":"number","min":0,"max":60,"step":0.1,"required":false},{"key":"hba1c","label":"HbA1c（可选）","unit":"%","type":"number","min":0,"max":20,"step":0.1,"required":false},{"key":"symptom","label":"典型症状（多饮多尿体重下降）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true}],"formula":"任一项达切点即可诊断：FPG ≥ 7.0 mmol/L；OGTT 2h ≥ 11.1 mmol/L；HbA1c ≥ 6.5%；有典型症状者随机血糖 ≥ 11.1 mmol/L","compute":"formula_only","algorithm":"count 达标项 (fpg>=7.0, pg2h>=11.1, hba1c>=6.5, symptom&&随机血糖可另填)\n若 symptom==1 且任一项达标 → 确诊糖尿病\n若 symptom==0 且仅 1 项达标 → 需改日复测确认","interpret":[{"when":"symptom == 1 && (fpg >= 7 || pg2h >= 11.1 || hba1c >= 6.5)","level":"crit","text":"有典型症状且有指标达标：可诊断糖尿病，启动综合管理"},{"when":"fpg >= 7 || pg2h >= 11.1 || hba1c >= 6.5","level":"high","text":"单项达标但无症状：需改日复测确认（同一指标或另一指标）"},{"when":"fpg >= 6.1 || (pg2h >= 7.8 && pg2h < 11.1) || (hba1c >= 5.7 && hba1c < 6.5)","level":"warn","text":"糖尿病前期（IFG/IGT/HbA1c 5.7–6.4%）：强化生活方式干预"},{"when":"v >= 0","level":"ok","text":"未达糖代谢异常切点"}],"note":"HbA1c 采用 NGSP 标化方法；急性感染、创伤、应激状态需除外应激性高血糖；妊娠糖尿病另有诊断流程。","refs":["中国2型糖尿病防治指南（2020年版）","ADA Standards of Care in Diabetes (2024)"]},{"id":"endo_dka_insulin","name":"糖尿病酮症酸中毒（DKA）液体与胰岛素方案参考","aka":["DKA 补液","DKA 小剂量胰岛素"],"cat":"糖尿病急性并发症","rank":7,"desc":"生成 DKA 处理的液体、胰岛素与补钾参考方案（不自动计算剂量）。","inputs":[{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":20,"max":250,"step":0.5,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":180,"step":1,"required":true},{"key":"k","label":"血钾","unit":"mmol/L","type":"number","min":1.5,"max":8,"step":0.1,"required":true},{"key":"glu","label":"血糖","unit":"mmol/L","type":"number","min":5,"max":80,"step":0.1,"required":true},{"key":"ph","label":"动脉血 pH","unit":"","type":"number","min":6.5,"max":7.6,"step":0.01,"required":false}],"formula":"第 1 h 生理盐水 15–20 mL/kg；随后按 4–14 mL/kg/h 依脱水与心肾功能调整；胰岛素 0.1 U/kg/h 持续静滴；血糖降至 11.1–13.9 mmol/L 时改含糖液并减量至 0.05 U/kg/h","compute":"formula_only","algorithm":"fluid1h = 15–20 * weight_kg (mL)\ninsulin = 0.1*weight_kg U/h\nk<3.3 → 先补钾再上胰岛素\nph<6.9 → 考虑碳酸氢钠（遵当地流程）","interpret":[{"when":"k < 3.3","level":"crit","text":"血钾 < 3.3 mmol/L：先补钾，暂缓胰岛素，防致命性心律失常"},{"when":"k >= 3.3 && k < 5.3","level":"warn","text":"血钾 3.3–5.2：尿量正常时每升液体加氯化钾，维持 4–5 mmol/L"},{"when":"k >= 5.3","level":"high","text":"血钾 ≥ 5.3：暂不补钾，监测心电图与血钾"},{"when":"glu < 11.1","level":"warn","text":"血糖已 ≤ 11.1 mmol/L：改用 5% 葡萄糖液，胰岛素减至 0.05 U/kg/h，维持血糖 8.3–11.1"}],"note":"开环与闭环均需每小时监测血糖、电解质、渗透压；纠正血钠可用校正钠；儿童 DKA 补液更保守，须按儿科规范。","refs":["中国高血糖危象诊断与治疗指南（2012）","ADA Hyperglycemic Crises in Adults Consensus Report (2024)"]},{"id":"endo_hhs","name":"高渗高血糖状态（HHS）诊断","aka":["HHS","Hyperosmolar Hyperglycemic State","高渗性高血糖综合征"],"cat":"糖尿病急性并发症","rank":11,"desc":"按血糖、有效血浆渗透压、pH 与酮体判定 HHS，并与 DKA 鉴别。","inputs":[{"key":"glu","label":"血糖","unit":"mmol/L","type":"number","min":5,"max":100,"step":0.1,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":190,"step":1,"required":true},{"key":"ph","label":"动脉血 pH","unit":"","type":"number","min":6.5,"max":7.7,"step":0.01,"required":true},{"key":"hco3","label":"HCO3⁻","unit":"mmol/L","type":"number","min":1,"max":40,"step":1,"required":true},{"key":"ketone","label":"血/尿酮体","unit":"","type":"select","options":[{"value":1,"label":"阳性/显著升高"},{"value":0,"label":"阴性/轻度"}],"required":true}],"formula":"有效血浆渗透压 = 2×Na + 血糖(mmol/L)；HHS：血糖 ≥ 33.3 mmol/L 且有效渗透压 ≥ 320 mOsm/kg，pH > 7.30、HCO3⁻ > 18、酮体阴性或轻度","compute":"formula_only","algorithm":"v = 2*na + glu\nHHS: glu>=33.3 && v>=320 && ph>7.30 && ketone==0\nDKA: glu>=13.9 && (ph<7.30 || hco3<18) && ketone==1\n混合: 两者均满足","interpret":[{"when":"glu >= 33.3 && v >= 320 && ketone == 0","level":"crit","text":"符合 HHS：积极补液（等渗液优先）、小剂量胰岛素，警惕低血容量与血栓"},{"when":"glu >= 13.9 && (ph < 7.30 || hco3 < 18) && ketone == 1","level":"crit","text":"符合 DKA：按 DKA 流程补液加小剂量胰岛素"},{"when":"glu >= 13.9 && v >= 320 && ketone == 1","level":"crit","text":"DKA 与 HHS 混合型：按高血糖危象统一管理，神经症状明显者警惕脑水肿"},{"when":"v >= 0","level":"warn","text":"未完全符合 HHS/DKA 切点，需结合临床与其他病因（感染、卒中、药物）"}],"note":"HHS 病死率高于 DKA（约 5–20%），多见于老年 T2DM，补液纠正需数日；避免血糖下降过快。","refs":["中国高血糖危象诊断与治疗指南（2012）","ADA Hyperglycemic Crises in Adults Consensus Report (2024)"]},{"id":"endo_tft_tsh_ft4","name":"甲状腺功能判读（TSH / FT4）","aka":["甲功判读","TSH FT4 FT3"],"cat":"甲状腺","rank":5,"desc":"根据 TSH 与 FT4 组合判定甲亢、甲减、亚临床状态及中枢性异常。","inputs":[{"key":"tsh","label":"TSH","unit":"mIU/L","type":"number","min":0,"max":200,"step":0.01,"required":true},{"key":"ft4","label":"FT4（与 TSH 同单位参考区间）","unit":"","type":"number","min":0,"max":100,"step":0.01,"required":true},{"key":"ft4_state","label":"FT4 相对参考区间","unit":"","type":"select","options":[{"value":-1,"label":"低于下限"},{"value":0,"label":"正常"},{"value":1,"label":"高于上限"}],"required":true}],"formula":"TSH 与 FT4 联合判读（FT4 以是否在参考区间表示）","compute":"formula_only","algorithm":"若 tsh 高于上限(>4.2 常用) 或 ft4_state==-1 → 甲减方向；tsh 低于下限(<0.27 常用) 或 ft4_state==1 → 甲亢方向；\n详细分型见 interpret","interpret":[{"when":"tsh < 0.1 && ft4_state == 1","level":"high","text":"临床甲亢：TSH 抑制 + FT4 升高，查 TRAb、甲状腺超声/摄碘率"},{"when":"tsh < 0.1 && ft4_state == 0","level":"warn","text":"亚临床甲亢（TSH<0.1）：老年与房颤患者评估治疗指征"},{"when":"tsh > 10 && ft4_state == -1","level":"crit","text":"临床甲减：TSH 升高 + FT4 降低，启动左甲状腺素替代"},{"when":"tsh > 4.2 && ft4_state == 0","level":"warn","text":"亚临床甲减：TSH ≥ 10 或伴症状/TPOAb 阳性者考虑替代"},{"when":"tsh < 0.27 && ft4_state == -1","level":"crit","text":"中枢性甲减可能：TSH 不低而 FT4 低，查垂体影像与其他垂体激素"},{"when":"v >= 0","level":"ok","text":"TSH 与 FT4 匹配在参考区间内，甲功正常"}],"note":"不同实验室参考区间差异大，须以本院区间为准；妊娠期采用妊娠特异性参考值；重症患者可出现正常甲状腺功能病态综合征。","refs":["成人甲状腺功能减退症诊治指南（2017）","中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022）"]},{"id":"endo_graves_score","name":"Graves 甲亢临床评分（改良 Wayne 指数）","aka":["Wayne 指数","Graves 诊断评分"],"cat":"甲状腺","rank":13,"desc":"根据症状体征评分辅助甲亢/Graves 病临床判断。","inputs":[{"key":"palp","label":"可触及的甲状腺肿大","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"bruit","label":"甲状腺血管杂音/震颤","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true},{"key":"eye","label":"突眼","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true},{"key":"hr","label":"心率 > 90 次/分","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（+3）"}],"required":true},{"key":"af","label":"心房颤动","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有（+4）"}],"required":true},{"key":"weight_loss","label":"近 1 年体重下降","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有（+3）"}],"required":true},{"key":"sweat","label":"多汗/怕热","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有（+2）"}],"required":true}],"formula":"各项加权求和，总分 0–16","compute":"sum","interpret":[{"when":"v >= 11","level":"high","text":"高度提示甲亢，查 TSH/FT4/FT3、TRAb、甲状腺摄碘率"},{"when":"v >= 5 && v < 11","level":"warn","text":"可疑甲亢，需实验室确认"},{"when":"v < 5","level":"ok","text":"甲亢临床证据不足"}],"note":"原版 Wayne 指数含更多条目并按分值二分类；本表为临床简化加权版本，仅供参考不能替代实验室诊断。","refs":["中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022）","Chinese Society of Endocrinology 甲亢诊治共识"]},{"id":"endo_hypothyroid_grade","name":"甲状腺功能减退分级","aka":["甲减分级","临床/亚临床甲减"],"cat":"甲状腺","rank":14,"desc":"按 TSH 与 FT4 水平区分临床甲减、亚临床甲减及严重程度。","inputs":[{"key":"tsh","label":"TSH","unit":"mIU/L","type":"number","min":0,"max":200,"step":0.01,"required":true},{"key":"ft4_low","label":"FT4 低于参考下限","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"symptom","label":"有甲减症状","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true}],"formula":"临床甲减：TSH↑ + FT4↓；亚临床甲减：TSH↑ + FT4 正常","compute":"formula_only","algorithm":"v = tsh（以 TSH 表征严重程度）","interpret":[{"when":"ft4_low == 1 && tsh > 10","level":"crit","text":"重度临床甲减（TSH > 10）：立即左甲状腺素替代，警惕黏液性水肿昏迷"},{"when":"ft4_low == 1","level":"high","text":"临床甲减：按体重与心血管情况启动左甲状腺素替代，4–6 周复查 TSH"},{"when":"tsh >= 10","level":"high","text":"亚临床甲减（TSH ≥ 10）：建议治疗"},{"when":"tsh > 4.2","level":"warn","text":"亚临床甲减（TSH 4.2–10）：TSH 4.2–10 且 TPOAb 阳性或有症状者考虑治疗"},{"when":"v >= 0","level":"ok","text":"TSH 在参考范围内，无甲减证据"}],"note":"老年人替代剂量宜小起始（约 1.6 μg/kg/d 的 50% 起）；冠心病患者更慢；妊娠期甲减目标 TSH 更严格。","refs":["成人甲状腺功能减退症诊治指南（2017）","ATA Guidelines for the Treatment of Hypothyroidism (2014)"]},{"id":"endo_frax","name":"骨质疏松骨折风险评估（FRAX 中国版）","aka":["FRAX","骨折风险预测工具"],"cat":"骨代谢","rank":8,"desc":"输入 FRAX 官网计算的 10 年主要骨质疏松性骨折与髋部骨折概率，判定干预指征。","inputs":[{"key":"pmof","label":"10 年主要骨质疏松性骨折概率（MOF）","unit":"%","type":"number","min":0,"max":100,"step":0.1,"required":true},{"key":"hip","label":"10 年髋部骨折概率","unit":"%","type":"number","min":0,"max":100,"step":0.1,"required":false},{"key":"prior_fx","label":"既往脆性骨折","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true},{"key":"t_score","label":"腰椎/股骨颈最低 T 值","unit":"","type":"number","min":-6,"max":3,"step":0.1,"required":false}],"formula":"FRAX（中国人群模型，可含或不含 BMD）计算 10 年骨折概率","compute":"formula_only","algorithm":"v = pmof；判定用中国指南阈值（见 note，按年龄/性别分段）","interpret":[{"when":"hip >= 3","level":"crit","text":"10 年髋部骨折概率 ≥ 3%：考虑抗骨质疏松药物治疗"},{"when":"pmof >= 20","level":"high","text":"10 年主要骨折概率 ≥ 20%：考虑抗骨质疏松药物治疗"},{"when":"t_score <= -2.5","level":"high","text":"T 值 ≤ −2.5：诊断骨质疏松，启动治疗评估"},{"when":"prior_fx == 1","level":"warn","text":"既往脆性骨折：已是极高骨折风险，直接评估治疗"},{"when":"v >= 0","level":"ok","text":"未达治疗阈值：生活方式干预并定期复评"}],"note":"中国 FRAX 干预阈值随年龄与性别变化（老年女性 MOF 约 10–11% 起考虑），请以 FRAX 中国官网与《原发性骨质疏松症诊疗指南（2022）》阈值表为准；本页仅作概率转译，不替代 FRAX 计算器。","refs":["原发性骨质疏松症诊疗指南（2022）","FRAX® Tool 中国人群模型（WHO Collaborating Centre, University of Sheffield）"]},{"id":"endo_bone_markers","name":"骨代谢指标判读（25-OH-VD、PTH、CTX、PINP）","aka":["骨转换标志物","25(OH)D","P1NP","β-CTX"],"cat":"骨代谢","rank":15,"desc":"根据维生素 D、PTH 与骨转换标志物水平判定骨代谢状态。","inputs":[{"key":"vd","label":"25-OH-VD","unit":"ng/mL","type":"number","min":0,"max":150,"step":0.1,"required":true},{"key":"pth","label":"PTH（可选）","unit":"pg/mL","type":"number","min":0,"max":2000,"step":0.1,"required":false},{"key":"ctx_high","label":"β-CTX 高于参考上限","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未查"}],"required":true},{"key":"pinp_high","label":"P1NP 高于参考上限","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未查"}],"required":true}],"formula":"按指标与参考区间判读（维生素 D 分层为临床共识）","compute":"formula_only","algorithm":"v = vd；分层与组合见 interpret","interpret":[{"when":"vd < 12","level":"crit","text":"25-OH-VD < 12 ng/mL（30 nmol/L）：维生素 D 缺乏，需补充治疗并查血钙磷、PTH"},{"when":"vd >= 12 && vd < 20","level":"warn","text":"25-OH-VD 12–20 ng/mL：不足，建议补充并复查"},{"when":"pth > 65 && vd < 20","level":"warn","text":"PTH 升高伴维生素 D 不足：考虑继发性甲旁亢，先纠正维生素 D 后复查"},{"when":"ctx_high == 1 && pinp_high == 1","level":"warn","text":"骨转换率升高：评估绝经后早期、甲亢、畸形性骨炎或骨吸收性治疗监测"},{"when":"v >= 20","level":"ok","text":"维生素 D 充足参考范围（≥ 20 ng/mL，理想 ≥ 30 ng/mL）"}],"note":"β-CTX 与 P1NP 需空腹晨起采血、统一检测平台；治疗后 P1NP 上升/CTX 下降为有效指标；参考区间以本院为准。","refs":["原发性骨质疏松症诊疗指南（2022）","中国维生素 D 缺乏及相关疾病诊治共识（2018）"]},{"id":"endo_cushing_screen","name":"库欣综合征筛查","aka":["Cushing 综合征筛查","皮质醇增多症"],"cat":"肾上腺","rank":17,"desc":"汇总库欣综合征三项一线筛查项目的判读（以填写结果形式呈现）。","inputs":[{"key":"lnsc","label":"午夜唾液皮质醇高于界值","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未查"}],"required":true},{"key":"dst","label":"1 mg 过夜地塞米松抑制试验皮质醇 ≥ 50 nmol/L（1.8 μg/dL）","unit":"","type":"select","options":[{"value":1,"label":"是（未抑制）"},{"value":0,"label":"否（抑制）"}],"required":true},{"key":"ufc","label":"24 h 尿游离皮质醇升高（查 2 次）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未查"}],"required":true},{"key":"high_risk","label":"高危临床表型（肌无力、紫纹、自发瘀斑、近端肌病、青年骨质疏松）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true}],"formula":"任一项筛查阳性需进一步定性；高危表型者三项均需完成","compute":"sum","interpret":[{"when":"v >= 2","level":"crit","text":"≥ 2 项筛查阳性：高度怀疑库欣综合征，行 ACTH + 大剂量地塞米松抑制试验 + 垂体/肾上腺影像"},{"when":"high_risk == 1","level":"high","text":"高危表型：即使 1 项阳性也应完善三项筛查，必要时重复"},{"when":"v == 0","level":"ok","text":"筛查阴性：假性库欣、周期性库欣者仍需随访"}],"note":"停用外源性糖皮质激素、口服避孕药、妊娠可致假阳性；1 mg DST 界值按检测方法（LC-MS/MS 约 50 nmol/L）调整。","refs":["库欣综合征诊疗专家共识（2016）","Endocrine Society Diagnosis of Cushing's Syndrome Guideline (2008)"]},{"id":"endo_adrenal_crisis","name":"肾上腺危象判断","aka":["Adrenal Crisis","急性肾上腺皮质功能不全"],"cat":"肾上腺","rank":18,"desc":"结合临床体征、血压与实验室指标识别肾上腺危象，指导紧急激素与补液。","inputs":[{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":30,"max":220,"step":1,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":95,"max":180,"step":1,"required":true},{"key":"k","label":"血钾","unit":"mmol/L","type":"number","min":1.5,"max":9,"step":0.1,"required":true},{"key":"glu","label":"血糖","unit":"mmol/L","type":"number","min":1,"max":40,"step":0.1,"required":true},{"key":"trigger","label":"诱因（感染/手术/停药/创伤）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true},{"key":"shock","label":"液体复苏后仍低血压","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"临床综合判断：低血压/休克 + 低钠、高钾、低血糖 + 诱因 + 对补液不敏感","compute":"formula_only","algorithm":"score = (sbp<90) + (na<135) + (k>5.0) + (glu<3.9) + trigger + (shock==1) → v","interpret":[{"when":"shock == 1 && v >= 3","level":"crit","text":"高度提示肾上腺危象：立即静推氢化可的松（遵流程剂量）并补液，同时采血查皮质醇/ACTH"},{"when":"v >= 3","level":"high","text":"可疑肾上腺危象：先抽血查皮质醇、ACTH 后立即经验性激素治疗，不要等结果"},{"when":"v >= 1","level":"warn","text":"存在肾上腺皮质功能不全线索，完善 ACTH 兴奋试验"},{"when":"v == 0","level":"ok","text":"无明显肾上腺危象线索"}],"note":"既往诊断或长期激素使用者需备急救卡；高钾血症伴休克需警惕与感染性休克鉴别；氢化可的松具体剂量请遵本院急救流程与说明书。","refs":["肾上腺皮质功能减退症诊治专家共识（2021）","Endocrine Society Treatment of Adrenal Insufficiency Guideline (2016)"]},{"id":"endo_hyponatremia","name":"低钠血症渗透压计算与纠正速率","aka":["低钠血症纠正","血钠升速限制"],"cat":"水电解质","rank":9,"desc":"计算血钠升幅、24 h 最大纠正量与渗透压，防范渗透性脱髓鞘。","inputs":[{"key":"na0","label":"初始血钠","unit":"mmol/L","type":"number","min":95,"max":160,"step":1,"required":true},{"key":"na1","label":"目标血钠（24 h 末）","unit":"mmol/L","type":"number","min":95,"max":170,"step":1,"required":true},{"key":"glu","label":"血糖（可选，用于校正）","unit":"mmol/L","type":"number","min":0,"max":80,"step":0.1,"required":false},{"key":"chronic","label":"病程是否 > 48 h","unit":"","type":"select","options":[{"value":1,"label":"慢性（>48 h）"},{"value":0,"label":"急性（≤48 h）"}],"required":true}],"formula":"校正血钠 = 实测 Na + 1.6×(血糖 mmol/L − 5.5)/5.5；24 h 升幅 = Na1 − Na0；血浆渗透压 = 2×Na + 血糖 + 尿素","compute":"formula_only","algorithm":"delta = na1 - na0; na_corr = glu>5.5 ? na0 + 1.6*(glu-5.5)/5.5 : na0; v = delta","interpret":[{"when":"na0 < 120 && chronic == 1","level":"crit","text":"重度低钠（<120）：有症状用 3% 高渗盐水快速升 4–6 mmol/L，24 h 总升幅不超过 8 mmol/L"},{"when":"delta > 8 && chronic == 1","level":"crit","text":"24 h 升幅 > 8 mmol/L：渗透性脱髓鞘风险，慢化并考虑去氨加压素或补液"},{"when":"delta > 10","level":"crit","text":"升幅 > 10–12 mmol/L（急性期）：超过安全上限，立即调整"},{"when":"na1 < 130","level":"warn","text":"仍为低钠血症：查明病因（SIADH、利尿剂、心衰、肝硬化、肾上腺功能不全）"},{"when":"v >= -8 && v <= 8","level":"ok","text":"计划升幅在安全范围内（慢性 ≤ 8 mmol/L/24 h）"}],"note":"有癫痫、昏迷等严重症状时 3% 盐水 100–150 mL 20 min 内可重复，使血钠升高 4–6 mmol/L；高血糖者需用校正钠判读。","refs":["中国低钠血症诊治专家共识（2017）","European Guideline on Diagnosis and Treatment of Hyponatraemia (2014)"]},{"id":"endo_corrected_calcium","name":"校正血钙（白蛋白校正）与离子钙","aka":["Corrected Calcium","白蛋白校正钙"],"cat":"水电解质","rank":19,"desc":"按白蛋白水平校正总钙，判定低钙/高钙及危象程度。","inputs":[{"key":"ca","label":"总钙","unit":"mg/dL","type":"number","min":3,"max":20,"step":0.1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/dL","type":"number","min":1,"max":6,"step":0.1,"required":true}],"formula":"校正钙(mg/dL) = 总钙 + 0.8×(4.0 − 白蛋白 g/dL)；若用 mmol/L：校正钙 = 总钙 + 0.02×(40 − 白蛋白 g/L)","compute":"formula_only","algorithm":"v = ca + 0.8*(4.0 - alb)","interpret":[{"when":"v >= 14","level":"crit","text":"校正钙 ≥ 14 mg/dL（3.5 mmol/L）：高钙危象，大量补液 + 降钙素/双膦酸盐，查 PTH"},{"when":"v > 10.5","level":"high","text":"高钙血症：查 PTH、25-OH-VD、PTHrP，排查恶性肿瘤与甲旁亢"},{"when":"v >= 8.5 && v <= 10.5","level":"ok","text":"血钙在参考范围内"},{"when":"v < 8.5 && v >= 7.0","level":"warn","text":"低钙血症：查镁、PTH、维生素 D，口服/静脉补钙"},{"when":"v < 7.0","level":"crit","text":"重度低钙（<7 mg/dL）：静脉补钙并监测 QTc，纠正低镁"}],"note":"输入单位固定为 mg/dL 与 g/dL；重症、酸碱失衡时以离子钙为准。","refs":["高钙血症诊治专家共识（2022）","中国慢性肾脏病矿物质和骨异常诊治指南（2019）"]},{"id":"endo_metabolic_syndrome","name":"代谢综合征诊断（CDS 标准）","aka":["Metabolic Syndrome","MS"],"cat":"体重管理","rank":20,"desc":"按中国糖尿病学会（CDS）标准综合判定代谢综合征。","inputs":[{"key":"wc","label":"男性腰围 ≥ 90 cm / 女性 ≥ 85 cm","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"tg","label":"TG ≥ 1.70 mmol/L 或已治疗","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"hdl","label":"HDL-C < 1.04 mmol/L（男）/ < 1.30 mmol/L（女）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"bp","label":"血压 ≥ 130/85 mmHg 或已治疗","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"fpg","label":"FPG ≥ 5.6 mmol/L 或已诊断 T2DM","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"具备 3 项或以上即可诊断","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"符合代谢综合征：综合干预（减重 5–10%、降压降糖调脂）"},{"when":"v == 2","level":"warn","text":"2 项异常：代谢综合征高危，强化生活方式干预"},{"when":"v < 2","level":"ok","text":"代谢异常项少于 2 项"}],"note":"CDS 2004/2013 标准以腰围为基础项；IDF 与 NCEP-ATP III 切点不同，跨标准不可混用。","refs":["中国2型糖尿病防治指南（2020年版）","中国成人血脂异常防治指南（2016年修订版）"]}]},"ent":{"items":[{"id":"ent_pta","name":"纯音平均听阈（PTA）","aka":["Pure Tone Average","PTA","言语频率平均听阈"],"cat":"听力学","desc":"以 0.5、1、2 kHz（或 0.5、1、2、4 kHz）气导听阈的算术平均代表整体听力水平，是评价听力损失程度与残疾鉴定的基础指标。","inputs":[{"key":"hz500","label":"0.5 kHz 气导听阈","unit":"dB HL","type":"number","min":-10,"max":120,"step":5,"required":true},{"key":"hz1000","label":"1 kHz 气导听阈","unit":"dB HL","type":"number","min":-10,"max":120,"step":5,"required":true},{"key":"hz2000","label":"2 kHz 气导听阈","unit":"dB HL","type":"number","min":-10,"max":120,"step":5,"required":true},{"key":"hz4000","label":"4 kHz 气导听阈（4 频 PTA 时填写）","unit":"dB HL","type":"number","min":-10,"max":120,"step":5,"required":false}],"formula":"PTA（3 频）= (0.5 + 1 + 2 kHz) / 3；PTA（4 频）= (0.5 + 1 + 2 + 4 kHz) / 4","compute":"formula_only","algorithm":"s3 = hz500 + hz1000 + hz2000\nif hz4000 is provided:\n  v = (s3 + hz4000) / 4\nelse:\n  v = s3 / 3\nv = Math.round(v * 10) / 10   # 保留 1 位小数","interpret":[{"when":"v <= 25","level":"ok","text":"PTA ≤ 25 dB HL：正常听力范围（0.5–4 kHz 8 频平均可到 20 dB）"},{"when":"v <= 40","level":"warn","text":"26–40 dB HL：轻度听力损失，安静环境可交流，嘈杂环境困难；复查声导抗排除中耳病变"},{"when":"v <= 55","level":"warn","text":"41–55 dB HL：中度听力损失，需言语识别率测试与助听器验配评估"},{"when":"v <= 70","level":"high","text":"56–70 dB HL：中重度听力损失，助听器为主，考虑人工耳蜗指征评估"},{"when":"v <= 90","level":"high","text":"71–90 dB HL：重度听力损失，助听器效果有限，评估人工耳蜗"},{"when":"v > 90","level":"crit","text":"> 90 dB HL：极重度听力损失，有条件者行人工耳蜗植入；需排除听神经病"}],"note":"骨导与气导分别计算可判断传导性/感音神经性；单侧聋、突聋与工伤鉴定对频率组合有专门规定，需核对当地标准。","refs":["WHO 听力损失分级（1997 年，15 岁以下儿童及成人推荐分级）","中华医学会耳鼻咽喉头颈外科学分会：突发性聋诊断和治疗指南（2015）"],"rank":1},{"id":"ent_hearing_grade","name":"听力损失分级（WHO 1997 / 2021 双标准）","aka":["WHO Hearing Loss Grading","听力残疾分级"],"cat":"听力学","desc":"按较好耳 0.5、1、2、4 kHz 平均听阈（PTA）划分听力损失程度，用于诊断分级与康复决策。","inputs":[{"key":"better_ear_pta","label":"好耳 4 频平均听阈（0.5/1/2/4 kHz）","unit":"dB HL","type":"number","min":-10,"max":130,"step":1,"required":true}],"formula":"以好耳 PTA 直接分档（WHO 1997：≤25 正常、26–40 轻、41–55 中、56–70 中重、71–90 重、>90 极重）","compute":"formula_only","algorithm":"v = better_ear_pta\nif v < 20: grade = '正常'\nelif v < 35: grade = '轻度'\nelif v < 50: grade = '中度'\nelif v < 65: grade = '中重度'\nelif v < 80: grade = '重度'\nelif v < 95: grade = '极重度'\nelse: grade = '完全失听/全聋'","interpret":[{"when":"v <= 25","level":"ok","text":"≤ 25 dB HL：正常（WHO 1997）；按 2021 新标准 ≥ 20 dB 即属轻度以上损失，20–34 dB 在嘈杂环境已受影响"},{"when":"v <= 40","level":"warn","text":"26–40 dB：轻度损失（WHO 1997）/ 中度损失（WHO 2021 35–49 dB 区间起点）；建议言语测听 + 助听器适应证评估"},{"when":"v <= 55","level":"warn","text":"41–55 dB：中度损失；助听器验配，评估耳鸣与噪声防护"},{"when":"v <= 70","level":"high","text":"56–70 dB：中重度损失；助听器为核心，配合听力康复训练"},{"when":"v <= 90","level":"high","text":"71–90 dB：重度损失；助听器效果需实测，评估人工耳蜗"},{"when":"v > 90","level":"crit","text":"> 90 dB：极重度损失/全聋；人工耳蜗植入评估，儿童需 3 个月内干预"}],"note":"分级以好耳为准；我国听力残疾评定（GB/T 26341）采用好耳平均听力并附加百分比换算，两者不等同。","refs":["WHO Prevention of Deafness and Hearing Impairment, 1997 分级","WHO World Report on Hearing（2021）听力损失分级","中华医学会耳鼻咽喉头颈外科学分会：听力损失诊断与干预相关指南（2021）"],"rank":2},{"id":"ent_dhi","name":"眩晕残障量表 DHI","aka":["Dizziness Handicap Inventory","DHI"],"cat":"前庭与平衡","desc":"25 项（躯体 7、情绪 9、功能 9）自评量表，量化眩晕对生活质量的影响，总分 0–100。","inputs":[{"key":"physical","label":"躯体（P）亚组得分","unit":"分","type":"number","min":0,"max":28,"step":1,"required":true,"hint":"7 题，每题 0/2/4 分"},{"key":"emotional","label":"情绪（E）亚组得分","unit":"分","type":"number","min":0,"max":36,"step":1,"required":true,"hint":"9 题，每题 0/2/4 分"},{"key":"functional","label":"功能（F）亚组得分","unit":"分","type":"number","min":0,"max":36,"step":1,"required":true,"hint":"9 题，每题 0/2/4 分"}],"formula":"DHI = 躯体（0–28）+ 情绪（0–36）+ 功能（0–36），总分 0–100；每题 否=0、有时=2、是=4","compute":"sum","algorithm":"v = physical + emotional + functional\nP = physical; E = emotional; F = functional","interpret":[{"when":"v <= 10","level":"ok","text":"0–10 分：无或可忽略的残障；以病因治疗与宣教为主"},{"when":"v <= 30","level":"warn","text":"11–30 分：轻中度残障；前庭康复训练（VRT）联合病因治疗"},{"when":"v <= 60","level":"warn","text":"31–60 分：中重度残障；需 VRT、认知行为干预，排查 PPPD 与焦虑抑郁（PHQ-9/GAD-7）"},{"when":"v > 60","level":"high","text":"> 60 分：重度残障，跌倒风险高；多学科（耳鼻喉/康复/精神心理）干预，慎用前庭抑制药以免阻碍代偿"}],"note":"DHI 用于评价主观残障与疗效，不能替代前庭功能检查；单亚组升高提示相应维度问题（E 高提示情绪负担）。","refs":["Jacobson GP, Newman CW. Arch Otolaryngol Head Neck Surg 1990（DHI 原版量表）","中华医学会耳鼻咽喉头颈外科学分会：梅尼埃病诊断和治疗指南（2017）","Barany Society: Diagnostic Criteria for Persistent Postural-Perceptual Dizziness（2017）"],"rank":3},{"id":"ent_dix_hallpike","name":"Dix-Hallpike 试验判读","aka":["Dix-Hallpike Test","D-H 试验"],"cat":"前庭与平衡","desc":"通过头位变换诱发眼震诊断后半规管良性阵发性位置性眩晕（BPPV），依据潜伏期、时长、方向与疲劳性判读。","inputs":[{"key":"latency","label":"眼震潜伏期","type":"select","options":[{"value":0,"label":"无潜伏期（立即出现）"},{"value":1,"label":"1–5 秒后出现"},{"value":2,"label":"> 10 秒或始终不出现"}],"required":true},{"key":"duration","label":"眼震持续时间","type":"select","options":[{"value":0,"label":"< 10 秒"},{"value":1,"label":"10–60 秒"},{"value":2,"label":"持续恒定，> 60 秒"}],"required":true},{"key":"direction","label":"眼震方向","type":"select","options":[{"value":0,"label":"扭转-垂直向上（上跳且向地侧旋）"},{"value":1,"label":"水平向地或向天"},{"value":2,"label":"垂直向下（下跳）"}],"required":true},{"key":"upbeating_persist","label":"出现下跳（downbeat）持续性眼震伴不稳","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"无数值；按 潜伏期 / 时长 / 方向 / 疲劳性 四要素判读（后半规管 BPPV：潜伏 1–5 s、持续 < 60 s、上跳扭转、可疲劳）","compute":"formula_only","algorithm":"if upbeating_persist == 1: result = '中枢性位置性眼震（下跳型）'\nelif latency == 1 && duration == 1 && direction == 0: result = '后半规管 BPPV（同侧）'\nelif latency == 0 && duration == 0 && direction == 0: result = '可能为上半规管 BPPV 或不典型'\nelif direction == 1: result = '水平半规管 BPPV，改用 Roll 试验/仰卧侧头试验确认'\nelif latency == 2 || duration == 2: result = '不典型，需排查中枢或直立性低血压'\nelse: result = '阴性'","interpret":[{"when":"upbeating_persist == 1","level":"crit","text":"下跳型持续眼震：高度提示中枢病变（小脑/脑干），禁止按 BPPV 复位，立即行头颅 MRI（含 DWI/梯度回波）与神经科评估"},{"when":"latency == 1 && duration == 1 && direction == 0","level":"high","text":"典型后半规管 BPPV：眼震 1–5 s 潜伏、< 60 s、上跳扭转；行 Epley 或 Semont 手法复位，1 次有效率约 70–90%"},{"when":"direction == 1","level":"warn","text":"水平眼震：属水平半规管 BPPV（或中枢），改行仰卧侧头/Roll 试验，向地性用 Barbecue 或 Gufoni，向天性行 Gufoni 反向或 Forced Prolonged Position"},{"when":"latency == 0 && duration == 0","level":"warn","text":"无潜伏、短程上跳眼震：考虑上半规管 BPPV 或前庭性偏头痛，可试行反向 Epley"},{"when":"latency == 2 || duration == 2","level":"warn","text":"长潜伏或持续眼震：不符合典型 BPPV，需耳科/神经科进一步定位（视频头脉冲 vHIT、VEMP、MRI）"},{"when":"true","level":"ok","text":"试验阴性：若临床高度怀疑，重复试验或行侧卧/Supine Roll 试验排查其他半规管"}],"note":"试验前应坐位 30 s 观察有无自发眼震；老年人颈痛、颈椎不稳者慎行。判读核心是「上跳+扭转+短暂+疲劳」为外周后半规管。","refs":["Barany Society: Clinical Practice Guideline for Benign Paroxysmal Positional Vertigo（2015）","AAO-HNS Clinical Practice Guideline: Benign Paroxysmal Positional Vertigo (Update) 2017","中华医学会耳鼻咽喉头颈外科学分会：良性阵发性位置性眩晕诊断和治疗指南（2017）"],"rank":4},{"id":"ent_lund_mackay","name":"鼻窦 Lund-Mackay CT 评分","aka":["Lund-Mackay Score","LM 评分"],"cat":"鼻与鼻窦","desc":"对 6 个鼻窦系统及窦口鼻道复合体逐侧评分（每侧 0/1/2 分），总分 0–24，量化慢性鼻窦炎影像学严重度。","inputs":[{"key":"maxillary_r","label":"右侧上颌窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"maxillary_l","label":"左侧上颌窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"ant_ethmoid_r","label":"右侧前组筛窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"ant_ethmoid_l","label":"左侧前组筛窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"post_ethmoid_r","label":"右侧后组筛窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"post_ethmoid_l","label":"左侧后组筛窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"sphenoid_r","label":"右侧蝶窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"sphenoid_l","label":"左侧蝶窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"frontal_r","label":"右侧额窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"frontal_l","label":"左侧额窦","type":"select","options":[{"value":0,"label":"0：完全清晰"},{"value":1,"label":"1：部分浑浊"},{"value":2,"label":"2：完全浑浊"}],"required":true},{"key":"omc_r","label":"右侧窦口鼻道复合体（OMC）","type":"select","options":[{"value":0,"label":"0：通畅"},{"value":1,"label":"1：部分阻塞"},{"value":2,"label":"2：完全阻塞"}],"required":true},{"key":"omc_l","label":"左侧窦口鼻道复合体（OMC）","type":"select","options":[{"value":0,"label":"0：通畅"},{"value":1,"label":"1：部分阻塞"},{"value":2,"label":"2：完全阻塞"}],"required":true}],"formula":"每侧 = 上颌窦 + 前筛 + 后筛 + 蝶窦 + 额窦 + OMC（各 0–2），单侧 0–12，总分 0–24","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：影像学无鼻窦浑浊；若有鼻部症状，考虑变应性鼻炎、非感染性鼻炎或鼻中隔偏曲"},{"when":"v <= 4","level":"ok","text":"1–4 分：轻度影像学改变；注意健康成人也有 0–4 分，需结合症状与鼻内镜（Lund-Kennedy）"},{"when":"v <= 8","level":"warn","text":"5–8 分：中度；规范药物治疗（鼻用糖皮质激素 ± 生理盐水冲洗，可选短期抗生素）4–8 周后复查"},{"when":"v <= 12","level":"warn","text":"9–12 分：中重度；评估 FESS 指征，注意合并鼻息肉、变应性真菌性鼻窦炎"},{"when":"v > 12","level":"high","text":"> 12 分：重度；优先手术（FESS）并完善嗜酸性粒细胞、IgE、ANCA、囊性纤维化等检查排除系统性疾病"}],"note":"LM 评分与症状相关性弱，不能单独用于诊断慢性鼻窦炎（需 EPOS 2020 症状+内镜/CT 综合）；复查间隔应 ≥ 12 周以避免假性浑浊。","refs":["Lund VJ, Mackay IS. Am J Rhinol 1993（Lund-Mackay 评分原版）","EPOS 2020：European Position Paper on Rhinosinusitis and Nasal Polyps","中华耳鼻咽喉头颈外科杂志：中国慢性鼻窦炎诊断和治疗指南（2018）"],"rank":5},{"id":"ent_tonsil_grade","name":"扁桃体肿大分级（Brodsky）","aka":["Tonsil Grading","Brodsky Tonsillar Grading"],"cat":"咽喉与气道","desc":"依据扁桃体占口咽腔气道的比例分为 0–4 度，用于评估 OSAHS、反复扁桃体炎的手术指征。","inputs":[{"key":"grade_sel","label":"扁桃体占咽腔比例方位（选择最接近的一项）","type":"select","options":[{"value":0,"label":"完全包于扁桃体窝内"},{"value":1,"label":"占据扁桃体窝至腭咽弓之间"},{"value":2,"label":"超出腭咽弓但未超过腭咽弓与悬雍垂中线"},{"value":3,"label":"超出咽腭弓，接近中线"},{"value":4,"label":"两侧扁桃体几乎在中线相接（接吻扁桃体）"}],"required":true}],"formula":"Brodsky 0–4 度，按扁桃体遮蔽咽腔比例：0（窝内）～ 4（中线相接，占咽腔 ≥ 75%）","compute":"formula_only","levels":[{"label":"0 度","criteria":"扁桃体完全位于扁桃体窝内，不可见或仅见于窝内","level":"ok"},{"label":"Ⅰ 度","criteria":"扁桃体占据扁桃体窝至腭咽弓，未超过腭咽弓","level":"ok"},{"label":"Ⅱ 度","criteria":"扁桃体超过腭咽弓，但未达到腭咽弓与悬雍垂之间的中线","level":"warn"},{"label":"Ⅲ 度","criteria":"扁桃体超过咽腭弓，接近中线，约占咽腔 50–75%","level":"warn"},{"label":"Ⅳ 度","criteria":"两侧扁桃体几乎在中线相接（接吻扁桃体），占咽腔 ≥ 75%","level":"high"}],"interpret":[{"when":"grade_sel <= 1","level":"ok","text":"0–Ⅰ 度：通常无需干预；反复咽痛者按 Centor/McIsaac 评估链球菌感染"},{"when":"grade_sel == 2","level":"warn","text":"Ⅱ 度：若伴打鼾、张口呼吸、睡眠呼吸暂停，需 PSG 评估 OSAHS"},{"when":"grade_sel >= 3","level":"high","text":"Ⅲ–Ⅳ 度：气道阻塞风险高；儿童 OSAHS 首选扁桃体（腺样体）切除；成人注意与舌根、软腭塌陷的复合因素"}],"note":"分级受张口度与舌体位置影响，检查时需压舌并充分发「啊」；成人扁桃体肥大需警惕淋巴瘤（单侧肿大、无压痛、伴颈部淋巴结）。","refs":["Brodsky L. Otolaryngol Clin North Am 1989（扁桃体分级）","中国儿童阻塞性睡眠呼吸暂停诊断和治疗指南（2020）","AAO-HNSF Clinical Practice Guideline: Tonsillectomy in Children (Update) 2019"],"rank":6},{"id":"ent_house_brackmann","name":"面神经功能分级 House-Brackmann","aka":["House-Brackmann Facial Nerve Grading","H-B 分级"],"cat":"面神经","desc":"按静态对称性、运动幅度与联动/挛缩程度将面神经功能分为 Ⅰ–Ⅵ 级，用于面瘫（Bell 麻痹、肿瘤术后、外伤）随访。","inputs":[{"key":"hb_grade","label":"选择最接近的等级表现","type":"select","options":[{"value":1,"label":"Ⅰ：各区功能正常"},{"value":2,"label":"Ⅱ：轻度功能异常，闭眼需轻微用力，口角轻度不对称"},{"value":3,"label":"Ⅲ：中度异常，闭眼需用力，口角明显不对称，额纹可动"},{"value":4,"label":"Ⅳ：中重度异常，闭眼不全，口角不对称明显，无明显联动"},{"value":5,"label":"Ⅴ：重度异常，仅见轻微运动，闭眼不全"},{"value":6,"label":"Ⅵ：完全麻痹，无任何运动"}],"required":true}],"formula":"按 Ⅰ–Ⅵ 级描述直接分档（原表另有 % 功能保留值：Ⅰ 100、Ⅱ 80、Ⅲ 70、Ⅳ 60、Ⅴ 25、Ⅵ 0）","compute":"formula_only","levels":[{"label":"Ⅰ 级（正常）","criteria":"各区面肌功能正常，对称","level":"ok"},{"label":"Ⅱ 级（轻度）","criteria":"轻度异常，闭眼需轻微用力，口角轻度不对称，无明显联动","level":"ok"},{"label":"Ⅲ 级（中度）","criteria":"明显但无毁形的差异，额部可动，闭眼需用力，口角明显不对称","level":"warn"},{"label":"Ⅳ 级（中重度）","criteria":"明显毁形与不对称，闭眼不全，口角明显不对称，无联动/挛缩","level":"warn"},{"label":"Ⅴ 级（重度）","criteria":"仅可有轻微运动，闭眼不全，口角轻微运动","level":"high"},{"label":"Ⅵ 级（完全麻痹）","criteria":"无任何运动，闭眼不能，面部不对称","level":"crit"}],"interpret":[{"when":"hb_grade <= 2","level":"ok","text":"Ⅰ–Ⅱ 级：功能良好，可每 1–2 个月随访；如仍有裂隙露眼需夜间眼膏防角膜炎"},{"when":"hb_grade == 3","level":"warn","text":"Ⅲ 级：有明显异常但可接受；面瘫病程早期评估糖皮质激素（72 h 内）与康复训练"},{"when":"hb_grade == 4","level":"warn","text":"Ⅳ 级：中重度；注意眼表保护、瞬目训练，7–10 天复查 ENoG/肌电评估预后"},{"when":"hb_grade >= 5","level":"crit","text":"Ⅴ–Ⅵ 级：严重至完全麻痹；保护角膜（眼膏+眼罩/睑缘缝合），排除肿瘤与颅内病变，必要时面神经减压/修复"}],"note":"H-B 分级整体性强但对联动与不对称描述粗，术后与神经移植随访建议同时使用 Sunnybrook 分级（线性评分更灵敏）。","refs":["House JW, Brackmann DE. Otolaryngol Head Neck Surg 1985（H-B 分级原版）","中华医学会神经外科学分会：周围性面神经损伤诊疗相关专家共识（2021）"],"rank":7},{"id":"ent_thi","name":"耳鸣残障量表 THI","aka":["Tinnitus Handicap Inventory","THI"],"cat":"听力学","desc":"25 项耳鸣自评量表（功能 11、情感 9、灾难 5），总分 0–100，评价耳鸣致残程度与疗效。","inputs":[{"key":"functional","label":"功能亚组（F）得分","unit":"分","type":"number","min":0,"max":44,"step":1,"required":true,"hint":"11 题 × 0/2/4"},{"key":"emotional","label":"情感亚组（E）得分","unit":"分","type":"number","min":0,"max":36,"step":1,"required":true,"hint":"9 题 × 0/2/4"},{"key":"catastrophic","label":"灾难亚组（C）得分","unit":"分","type":"number","min":0,"max":20,"step":1,"required":true,"hint":"5 题 × 0/2/4"}],"formula":"THI = 功能（0–44）+ 情感（0–36）+ 灾难（0–20），总分 0–100；每题 否=0、有时=2、是=4","compute":"sum","interpret":[{"when":"v <= 16","level":"ok","text":"0–16 分：轻微；以宣教、避免噪声暴露、睡眠管理与音乐掩蔽为主"},{"when":"v <= 36","level":"warn","text":"18–36 分：轻度；声治疗 + 认知行为治疗（CBT）优于单纯药物"},{"when":"v <= 56","level":"warn","text":"38–56 分：中度；CBT 为核心，评估睡眠（PSQI）与焦虑抑郁（PHQ-9/GAD-7）"},{"when":"v <= 76","level":"high","text":"58–76 分：重度；多学科干预，CBT + 声治疗 + 必要时短期抗焦虑药，定期复评"},{"when":"v > 76","level":"crit","text":"78–100 分：极重度；需精神心理评估自杀风险，避免使用可能加重耳鸣的耳毒性药物"}],"note":"分级界值存在 ±4 分差异（不同文献），宜用同一界值纵向比较；单侧搏动性耳鸣须行血管影像（DSA/CTA）排除动静脉畸形、血管瘤。","refs":["Newman CW, Jacobson GP, Spitzer JB. Arch Otolaryngol Head Neck Surg 1996（THI 原版）","中华医学会耳鼻咽喉头颈外科学分会：耳鸣诊断和治疗指南（2023，中国）","AAO-HNSF Clinical Practice Guideline: Tinnitus 2014"],"rank":8},{"id":"ent_epworth","name":"Epworth 嗜睡量表（ESS）","aka":["Epworth Sleepiness Scale","ESS","日间嗜睡评分"],"cat":"睡眠与气道","desc":"8 个生活场景下打瞌睡倾向的自评（各 0–3 分），总分 0–24，筛查日间过度嗜睡（OSAHS、嗜睡症）。","inputs":[{"key":"sitting_read","label":"坐着阅读安静时","type":"select","options":[{"value":0,"label":"0：从不打瞌睡"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"watching_tv","label":"看电视时","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"inactive_public","label":"在公共场所安静坐着（会议、剧场）","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"passenger","label":"作为乘客坐车 1 小时不停车","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"lying_afternoon","label":"下午躺下休息时","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"sitting_talking","label":"坐着与人谈话时","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"quiet_after_lunch","label":"午饭后安静坐着（不饮酒）","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true},{"key":"stopped_car","label":"开车遇红灯短暂停车时","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：很少"},{"value":2,"label":"2：有时"},{"value":3,"label":"3：经常"}],"required":true}],"formula":"ESS = 8 项之和（0–3 分/项），总分 0–24","compute":"sum","interpret":[{"when":"v <= 10","level":"ok","text":"0–10 分：日间嗜睡在正常范围；若鼾声、夜间憋醒明显仍需行 PSG"},{"when":"v <= 15","level":"warn","text":"11–15 分：轻中度嗜睡，可见于部分 OSAHS 或睡眠不足；行睡眠卫生宣教 + 多导睡眠监测（PSG）"},{"when":"v < 18","level":"high","text":"16–17 分：明显嗜睡；警惕 OSAHS、发作性睡病、周期性肢体运动，行 PSG + MSLT"},{"when":"v >= 18","level":"crit","text":"≥ 18 分：重度嗜睡，驾驶与操作机械风险高；禁止驾驶，尽快行 PSG/CPAP 评估"}],"note":"ESS 反映主观嗜睡，非 OSAHS 严重度；OSAHS 严重度按 AHI 分级（5/15/30）。","refs":["Johns MW. Sleep 1991;14:540-545（ESS 原版）","中国成人 OSAHS 诊断和治疗指南（2011，中华医学会呼吸病学分会）","AASM International Classification of Sleep Disorders, 3rd ed. 2014"],"rank":9},{"id":"ent_mallampati","name":"Mallampati 气道分级","aka":["Modified Mallampati Classification","改良 Mallampati 评分"],"cat":"咽喉与气道","desc":"坐位张口伸舌时观察口咽结构可见程度（Ⅰ–Ⅳ），预测困难气道风险，气管插管前评估常规项目。","inputs":[{"key":"mp_class","label":"张口伸舌时可见结构","type":"select","options":[{"value":1,"label":"Ⅰ：可见软腭、咽腭弓、悬雍垂"},{"value":2,"label":"Ⅱ：可见软腭、咽腭弓，悬雍垂被舌根遮挡"},{"value":3,"label":"Ⅲ：仅见软腭与舌根底"},{"value":4,"label":"Ⅳ：仅见硬腭，软腭不可见"}],"required":true}],"formula":"按可见口咽结构直接分为 Ⅰ–Ⅳ 级（改良版去除发「啊」动作）","compute":"formula_only","levels":[{"label":"Ⅰ 级","criteria":"可见软腭、咽腭弓、悬雍垂，困难气道风险低","level":"ok"},{"label":"Ⅱ 级","criteria":"可见软腭、咽腭弓、悬雍垂基底，风险低","level":"ok"},{"label":"Ⅲ 级","criteria":"仅可见软腭与舌根底部，困难插管风险增加","level":"warn"},{"label":"Ⅳ 级","criteria":"仅见硬腭，困难插管风险高","level":"high"}],"interpret":[{"when":"mp_class <= 2","level":"ok","text":"Ⅰ–Ⅱ 级：困难喉镜暴露风险低；仍需结合张口度（≥3 cm）、甲颏距离（≥6.5 cm）、颈部活动度综合评估"},{"when":"mp_class == 3","level":"warn","text":"Ⅲ 级：困难插管风险增加；准备可视喉镜、备好抢救车与吸氧，避免单凭一项决定"},{"when":"mp_class >= 4","level":"high","text":"Ⅳ 级：高困难气道风险；术前与家属沟通风险，备纤维支气管镜/声门上气道与紧急气道方案（CICO）"}],"note":"单用 Mallampati 预测能力有限（敏感度约 50%），应与 STOP-Bang、张口度、颈围联合评估；肥胖、头颈肿瘤放化疗后尤需谨慎。","refs":["Mallampati SR et al. Can Anaesth Soc J 1985（原版）","ASA Practice Guidelines for Management of the Difficult Airway 2022","中华医学会麻醉学分会：困难气道管理专家共识（2013）"],"rank":10},{"id":"ent_asap","name":"OMC 窦口阻塞功能评估（Lund-Kennedy 鼻内镜评分）","aka":["Lund-Kennedy Endoscopic Score","LK 内镜评分"],"cat":"鼻与鼻窦","desc":"鼻内镜下对息肉、水肿、分泌物、瘢痕/结痂各侧计 0–2 分，每侧 0–8 分，用于慢性鼻窦炎（CRS）与术后随访。","inputs":[{"key":"polyp_r","label":"右侧息肉","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：中鼻道内息肉"},{"value":2,"label":"2：息肉超出中鼻道"}],"required":true},{"key":"polyp_l","label":"左侧息肉","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：中鼻道内息肉"},{"value":2,"label":"2：息肉超出中鼻道"}],"required":true},{"key":"edema_r","label":"右侧水肿（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：重度（鼻腔堵塞）"}],"required":true},{"key":"edema_l","label":"左侧水肿（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：重度（鼻腔堵塞）"}],"required":true},{"key":"discharge_r","label":"右侧分泌物（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：清亮稀薄"},{"value":2,"label":"2：黏稠/脓性"}],"required":true},{"key":"discharge_l","label":"左侧分泌物（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：清亮稀薄"},{"value":2,"label":"2：黏稠/脓性"}],"required":true},{"key":"scar_r","label":"右侧瘢痕/结痂（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：重度"}],"required":true},{"key":"scar_l","label":"左侧瘢痕/结痂（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：重度"}],"required":true}],"formula":"每侧 = 息肉 + 水肿 + 分泌物 + 瘢痕/结痂（各 0–2）；单侧 0–8，总分 0–16","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：内镜下无炎症表现；若症状持续注意非嗜酸/非息肉型 CRS 及鼻后滴漏综合征"},{"when":"v <= 4","level":"ok","text":"1–4 分：轻度；规范鼻用糖皮质激素与生理盐水冲洗，3 个月复评"},{"when":"v <= 8","level":"warn","text":"5–8 分：中度；评估口服激素短期疗程与生物制剂（dupilumab/omalizumab）适应证（重型伴 2 型炎症）"},{"when":"v > 8","level":"high","text":"> 8 分：重度；FESS 后复发者需再手术评估，结合 LM CT 与嗜酸性粒细胞"}],"note":"Lund-Kennedy 与 Lund-Mackay 常联合记录；术后早期 2–3 周结痂评分偏高，不宜据此判断疗效。","refs":["Lund VJ, Kennedy DW. Otolaryngol Head Neck Surg 1997（LK 评分）","EPOS 2020 欧洲鼻窦炎与鼻息肉意见书","中国慢性鼻窦炎诊断和治疗指南（2018，中华耳鼻咽喉头颈外科杂志）"],"rank":11}]},"eye":{"items":[{"id":"eye_va_convert","name":"视力换算（小数 / 五分 / LogMAR）","aka":["Visual Acuity Conversion","Snellen 换算","LogMAR"],"cat":"视力与屈光","rank":1,"desc":"在三种常用视力记录方式之间换算，并判读视力损伤分级。","inputs":[{"key":"vc","label":"小数视力（小数记录法，可选）","type":"number","min":0.01,"max":2,"step":0.01,"required":false,"hint":"如 1.0、0.5"},{"key":"logmar","label":"LogMAR（可选，优先使用）","type":"number","min":-0.3,"max":2,"step":0.02,"required":false},{"key":"eye","label":"眼别","type":"select","options":[{"value":1,"label":"右眼 OD"},{"value":2,"label":"左眼 OS"}],"required":false}],"formula":"LogMAR = −lg(小数视力)；五分记录 = 5 + LogMAR；例：1.0 ↔ LogMAR 0 ↔ 5.0；0.1 ↔ LogMAR 1.0 ↔ 4.0；0.05 ↔ LogMAR 1.3 ↔ 3.7","compute":"formula_only","algorithm":"lg = logmar 有值 ? logmar : -Math.log10(vc)\nvc_out = logmar 有值 ? Math.pow(10, -logmar) : vc\nfive = 5 + lg\nv = Math.round((5 + lg) * 10) / 10   # 以五分记录为统一判定值\ntext = `LogMAR ${lg.toFixed(2)} / 小数 ${vc_out.toFixed(2)} / 五分 ${five.toFixed(1)}`\n","interpret":[{"when":"v >= 5","level":"ok","text":"五分 ≥5.0（小数 ≥1.0）：正常视力，可直接做屈光/眼底检查"},{"when":"v >= 4.5","level":"ok","text":"四分位 4.5–4.9（小数 0.32–0.8）：轻度下降，查屈光、裂隙灯与眼底"},{"when":"v >= 4","level":"warn","text":"4.0–4.4（小数 0.1–0.25）：中度视力障碍，需明确病因；注意国内驾照裸眼视力要求"},{"when":"v >= 3.3","level":"high","text":"3.3–3.9（小数 0.02–0.08）：重度视力障碍（WHO 2019 分级），转眼科专科评估"},{"when":"v < 3.3","level":"crit","text":"<3.3（小数 <0.02）：盲/极重度，评估光感、光定位与视野，启动低视力康复"}],"note":"换算仅在受检者在标准照明、正确距离下测得的眯眼/针孔最佳矫正视力间成立；LogMAR ETDRS 字母行数才是临床与研究标准。WHO 2020 分级：轻度 <0.5、中度 <0.3、重度 <0.1、盲 <0.05（较好眼）。5 分记录法国内为 5 − lg(小数)。","refs":["WHO World Report on Vision（2019）及 ICD-11 视力损伤分级","中华医学会眼科学分会：视力残疾评定与视功能检查规范（2018）"]},{"id":"eye_iop","name":"眼压判读（Goldmann 眼压计）","aka":["Intraocular Pressure","IOP"],"cat":"青光眼","rank":2,"desc":"解读压平眼压测量值，给出进一步检查方向。","inputs":[{"key":"iop_od","label":"右眼 OD","unit":"mmHg","type":"number","min":0,"max":80,"step":0.5,"required":true},{"key":"iop_os","label":"左眼 OS","unit":"mmHg","type":"number","min":0,"max":80,"step":0.5,"required":true},{"key":"cct","label":"中央角膜厚度 CCT（可选）","unit":"μm","type":"number","min":400,"max":700,"step":1,"required":false}],"formula":"正常眼压 10–21 mmHg（人群 95% 区间）；CCT 校正：CCT 每偏离 540 μm 约 10 μm 影响 0.1–0.5 mmHg（薄角膜低估、厚角膜高估）","compute":"formula_only","algorithm":"high = Math.max(iop_od, iop_os)\nlow = Math.min(iop_od, iop_os)\ndiff = high - low\nv = high\n","interpret":[{"when":"v <= 21 && low >= 6 && (high - low) <= 5","level":"ok","text":"双眼 6–21 mmHg 且眼压差 ≤5 mmHg：正常范围；青光眼高危者仍需查眼底与视野"},{"when":"v > 21 && v <= 30","level":"warn","text":"22–30 mmHg：轻中度升高，查房角（gonioscopy）、视盘 CD 比与 OCT RNFL，排除高眼压症/开角型青光眼"},{"when":"v > 30","level":"crit","text":">30 mmHg：显著升高，立即降眼压（如噻吗洛尔/溴莫尼定/乙酰唑胺），警惕急性闭角型青光眼发作（伴眼痛、头痛、恶心、虹视）"},{"when":"low < 6","level":"warn","text":"任一眼 <6 mmHg：低眼压，评估术后/炎症/视网膜脱离/睫状体功能"},{"when":"high - low > 5","level":"warn","text":"双眼压差 >5 mmHg：提示单眼病变（如继发青光眼、炎症、占位），需单眼详细检查"}],"note":"压平眼压计受角膜厚度、曲率与手术史影响；薄角膜（<520 μm）测值偏低、厚角膜（>580 μm）偏高。角膜移植/屈光术后改用眼压笔或动态轮廓眼压。正常眼压型青光眼压 <21 mmHg 仍可进展。","refs":["中华医学会眼科学分会青光眼学组：中国青光眼指南（2020）","AAO Preferred Practice Pattern Glaucoma（2021）"]},{"id":"eye_cd_ratio","name":"杯盘比（C/D）判读","aka":["Cup-to-Disc Ratio","视杯视盘比"],"cat":"青光眼","rank":3,"desc":"根据视盘杯盘比与盘沿、出血等体征判断青光眼性视神经损害可疑程度。","inputs":[{"key":"cd_ratio","label":"垂直杯盘比 C/D","type":"number","min":0,"max":1,"step":0.05,"required":true},{"key":"asymmetry","label":"双眼 C/D 差","type":"number","min":0,"max":1,"step":0.05,"required":true},{"key":"notch","label":"盘沿变窄/切迹（ISNT 规则破坏）","type":"select","options":[{"value":0,"label":"无（盘沿均匀）"},{"value":1,"label":"局部盘沿变窄"},{"value":2,"label":"切迹/盘沿出血"}],"required":true},{"key":"iop","label":"眼压（可空）","unit":"mmHg","type":"number","min":0,"max":80,"step":0.5,"required":false}],"formula":"C/D = 视杯垂直径 / 视盘垂直径；正常多为 0.3–0.5，≥0.6 疑似增大，双眼差 >0.2 可疑","compute":"formula_only","algorithm":"v = cd_ratio * 100  # 以百分数表示便于判读\nrisk = 0\nif cd_ratio >= 0.6: risk++\nif asymmetry > 0.2: risk++\nif notch >= 1: risk++\nif iop > 21: risk++\n","interpret":[{"when":"v < 50 && asymmetry <= 0.2 && notch == 0","level":"ok","text":"C/D <0.5、双眼对称、盘沿完整：生理性大杯或正常视盘，≥40 岁每年筛查"},{"when":"v < 60 && asymmetry <= 0.2 && notch <= 1","level":"warn","text":"C/D 0.5–0.6：边界值，叠加 OCT RNFL 与视野（24-2）；3 个月复查看 CD 进展"},{"when":"v >= 60 || asymmetry > 0.2","level":"high","text":"C/D ≥0.6 或双眼不对称 >0.2：可疑青光眼视神经病变，行 OCT 神经纤维层 + 房角镜 + 视野"},{"when":"notch >= 2","level":"crit","text":"盘沿切迹/盘沿出血：高度提示青光眼进展，按青光眼目标眼压管理（较基线降 20–30%）"}],"note":"大视盘（近视眼、视盘倾斜）可有生理性大杯；C/D 单一指标不足以诊断，需结合盘沿面积（ISNT 规则）、RNFL 厚度（OCT）与视野缺损（鼻侧阶梯、生理盲点扩大）。","refs":["中华医学会眼科学分会青光眼学组：中国青光眼指南（2020）","AAO Preferred Practice Pattern Primary Open-Angle Glaucoma（2021）"]},{"id":"eye_dr_grading","name":"糖尿病视网膜病变分级（国际临床分级）","aka":["Diabetic Retinopathy Grading","DR 分级","ETDRS"],"cat":"眼底病变","rank":4,"desc":"按国际临床分级（NPC / NPDR 轻中重 / PDR）判读眼底所见并给出随访间隔。","inputs":[{"key":"microaneurysm","label":"微动脉瘤（仅有）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"存在"}],"required":true},{"key":"moderate","label":"中重度出血/硬性渗出/棉絮斑/静脉串珠（>3 个象限）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"存在轻度"},{"value":2,"label":"存在且 >20 处出血"}],"required":true},{"key":"severe_features","label":"4-2-1 规则特征数（≥20 处出血任一象限、静脉串珠 ≥2 象限、IRMA ≥1 象限）","type":"number","min":0,"max":3,"step":1,"required":true},{"key":"pdr_signs","label":"增殖特征（新生血管、玻璃体积血、视网膜前出血、纤维增殖）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"},{"value":2,"label":"有且伴玻璃体积血/牵拉性视网膜脱离"}],"required":true},{"key":"dme","label":"糖尿病黄斑水肿 DME","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有（OCT 黄斑中心厚度增加/渗出距中心 <500 μm）"}],"required":true}],"formula":"分级：0 无 DR；1 轻度 NPDR（仅微动脉瘤）；2 中度 NPDR（不止微动脉瘤、未达重度）；3 重度 NPDR（4-2-1 任一）；4 PDR；DME 单独记录并优先处理","compute":"formula_only","algorithm":"v = 0\nif microaneurysm == 1: v = 1\nif moderate >= 1: v = 2\nif severe_features >= 1: v = 3\nif pdr_signs >= 1: v = 4\nif dme == 1: v += 10  # 10 表示合并 DME\n","interpret":[{"when":"v == 0","level":"ok","text":"无 DR：每年 1 次散瞳眼底照相（1 型 5 年后起，2 型确诊时起）"},{"when":"v == 1","level":"ok","text":"轻度 NPDR：每 12 个月复查眼底，强化血糖（HbA1c<7%）、血压（<130/80）、血脂"},{"when":"v == 2","level":"warn","text":"中度 NPDR：每 6–12 个月复查，评估 OMA/硬性渗出与妊娠风险"},{"when":"v == 3","level":"high","text":"重度 NPDR：每 2–4 个月随访，评估全视网膜光凝（PRP）指征，警惕 1 年内进展为 PDR"},{"when":"v >= 4","level":"crit","text":"PDR：立即转视网膜专科，行 PRP 或抗 VEGF；玻璃体积血/牵拉性视网膜脱离需玻璃体切割手术"}],"note":"国际临床分级（2002）为筛查用，4-2-1 规则即重度 NPDR 阈值；DME 可在任何 DR 分期出现，伴中心凹受累时抗 VEGF 优先。妊娠可加速进展。合并 CKD/血糖控制差进展加快。","refs":["中华医学会眼科学分会：我国糖尿病视网膜病变临床诊疗指南（2022）","AAO International Clinical Diabetic Retinopathy Disease Severity Scale（2002，2019 更新）","ETDRS Report No.12（1991）"]},{"id":"eye_amd_grade","name":"年龄相关性黄斑变性（AMD）分级","aka":["AMD Grading","AREDS 简化分级"],"cat":"眼底病变","rank":5,"desc":"按玻璃膜疣大小、数量与色素改变分级早期/晚期 AMD，给出补充治疗建议。","inputs":[{"key":"drusen_size","label":"玻璃膜疣最大直径","type":"select","options":[{"value":0,"label":"无或 <63 μm（小）"},{"value":1,"label":"63–124 μm（中）"},{"value":2,"label":"≥125 μm（大）"}],"required":true},{"key":"pigment","label":"色素异常/玻璃膜疣数量多","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"advanced","label":"晚期特征（CNV/脉络膜新生血管、地图样萎缩、视网膜下出血/积液）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"地图样萎缩（干性晚期）"},{"value":2,"label":"CNV/出血/积液（湿性晚期）"}],"required":true},{"key":"fellow","label":"对侧眼已进展为晚期 AMD","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"AREDS 分级：无/早期（小玻璃膜疣或无）→ 中期（大玻璃膜疣或中玻璃膜疣+色素异常）→ 晚期（CNV 或地图样萎缩）；AREDS2 配方：维 A 酸维 C 500 mg + 维 E 400 IU + 锌 80 mg + 叶黄素 10 mg + 玉米黄质 2 mg","compute":"formula_only","algorithm":"v = 0\nif drusen_size == 1 || drusen_size == 2 || pigment == 1: v = 1\nif (drusen_size == 2 && pigment == 1) || (drusen_size == 2 && fellow == 1): v = 2\nif drusen_size == 2 && pigment == 1 && fellow == 1: v = 3\nif advanced >= 1: v += 10  # 10=晚期\n","interpret":[{"when":"v == 0","level":"ok","text":"无/早期 AMD：每 12 个月查眼底＋OCT，戒烟，控制血压血脂"},{"when":"v >= 1 && v < 10","level":"warn","text":"中期 AMD：3–6 个月复查，建议 AREDS2 补充剂（降低进展约 25%），教会 Amsler 表自测"},{"when":"v >= 10","level":"crit","text":"晚期 AMD：湿性（CNV）→ 抗 VEGF 玻璃体腔注射（阿柏西普/雷珠单抗），2 周内首针；干性地图样萎缩 → 目前以监测为主，部分用药（补体抑制剂）"}],"note":"使用 Amsler 表在家自查：出现中心暗点、视物变形需立即复诊（湿性 AMD 视力下降快）。吸烟是唯一明确可干预的危险因素。补充剂不适用于吸烟者（β-胡萝卜素增肺癌风险，故 AREDS2 用叶黄素替代）。","refs":["AAO Preferred Practice Pattern Age-Related Macular Degeneration（2019，2023 更新）","AREDS2 Research Group JAMA（2013）","中华医学会眼科学分会：中国年龄相关性黄斑变性临床诊疗指南（2023）"]},{"id":"eye_glaucoma_stage","name":"青光眼分期（MD 与视野缺损）","aka":["Glaucoma Staging","Hodapp-Parrish-Anderson","视野分期"],"cat":"青光眼","rank":6,"desc":"按 Humphrey 视野 MD 与缺损范围划分轻、中、重度青光眼，指导目标眼压。","inputs":[{"key":"md","label":"视野平均缺损 MD","unit":"dB","type":"number","min":-35,"max":5,"step":0.1,"required":true},{"key":"psd","label":"模式标准差 PSD（可选）","unit":"dB","type":"number","min":0,"max":20,"step":0.1,"required":false},{"key":"field_loss","label":"视野缺损（Hodapp 分级）","type":"select","options":[{"value":0,"label":"无或早期（1–2 个 5 dB 及以上敏感度减低点，未触及中心 5°）"},{"value":1,"label":"中度（>2 个点减弱但未完全丧失，未触及中心 5°）"},{"value":2,"label":"重度（≥1 个半侧视野完全丧失，或中心 5° 内 1 点）"}],"required":true}],"formula":"Hodapp-Parrish-Anderson：轻度 MD >−6 dB；中度 −6 至 −12 dB；重度 <−12 dB（与视野缺损形态综合）","compute":"formula_only","algorithm":"v = md > -6 ? 1 : (md >= -12 ? 2 : 3)\nif field_loss == 2: v = 3\nif field_loss == 1: v = Math.max(v, 2)\n","interpret":[{"when":"v <= 1","level":"ok","text":"轻度：目标眼压较基线降低 20–25%，每 6–12 个月查视野与 OCT"},{"when":"v == 2","level":"warn","text":"中度：目标眼压降低 25–30%，每 4–6 个月查视野，评估是否需联合手术（小梁切除/SLT）"},{"when":"v >= 3","level":"crit","text":"重度：目标眼压降低 ≥30%（理想 <12 mmHg），3 个月 1 次视野，评估滤过手术；注意视力残疾评定"}],"note":"视野需在矫正屈光、相同仪器下重复至少 2 次确认（学习效应）；进展判断用 GPA/趋势分析（MD 斜率），优于单次 MD。MD 受白内障影响可人为变负，需结合晶状体状态。","refs":["Hodapp E, Parrish RK, Anderson DR. Clinical Decisions in Glaucoma（1993）","中华医学会眼科学分会青光眼学组：中国青光眼指南（2020）"]},{"id":"eye_refraction_convert","name":"屈光度换算（顶点距离 / 等效球镜）","aka":["Vertex Distance Conversion","Spherical Equivalent","SE"],"cat":"视力与屈光","rank":7,"desc":"在隐形眼镜与框架眼镜度数间换算，并计算等效球镜与近视分级。","inputs":[{"key":"sphere","label":"球镜度数 Sphere","unit":"D","type":"number","min":-30,"max":30,"step":0.25,"required":true,"hint":"近视填负数"},{"key":"cylinder","label":"柱镜度数 Cylinder","unit":"D","type":"number","min":-10,"max":10,"step":0.25,"required":true,"hint":"负数（内柱）"},{"key":"vertex_mm","label":"顶点距离","unit":"mm","type":"number","min":8,"max":20,"step":1,"required":false,"hint":"框架顶点距离常用 12 mm，隐形眼镜为 0"}],"formula":"等效球镜 SE = 球镜 + 柱镜/2；顶点距离换算：F_contact = F_frame / (1 − d × F_frame)，d 为顶点距离(m)；柱镜同理并常用交叉柱镜调整","compute":"formula_only","algorithm":"se = sphere + cylinder / 2\nd = (vertex_mm || 12) / 1000\nfc = sphere / (1 - d * sphere)\nfcc = cylinder / (1 - d * cylinder)\nv = Math.round(se * 100) / 100  # 等效球镜\ntext = `等效球镜 SE ${se.toFixed(2)} D；隐形眼镜球镜 ${fc.toFixed(2)} D / 柱镜 ${fcc.toFixed(2)} D`\n","interpret":[{"when":"v > -0.5 && v < 0.5","level":"ok","text":"等效球镜 −0.50 至 +0.50 D：正视（屈光误差在生理范围）"},{"when":"v <= -0.5 && v > -3","level":"warn","text":"−0.50 至 −3.00 D：轻度近视，注意矫正与控制近距离用眼；儿童需散瞳验光"},{"when":"v <= -3 && v > -6","level":"warn","text":"−3.00 至 −6.00 D：中度近视，建议每半年查眼底（周边视网膜变性/裂孔）"},{"when":"v <= -6","level":"high","text":"≤−6.00 D：高度近视，视网膜脱离、黄斑病变与青光眼风险升高，建议每年散瞳查眼底＋OCT"},{"when":"v >= 0.5","level":"warn","text":"远视 ≥+0.50 D：儿童需散瞳验光，伴内斜者可能需配镜＋遮盖；成人注意闭角型青光眼前房深度"}],"note":"超过 ±4.00 D 的镜片必须做顶点距离换算（隐形眼镜度数绝对值更小）；柱镜不相互垂直时需做交叉柱镜换算（Cylinder transposition）。儿童用 1% 阿托品或 0.5% 托吡卡胺散瞳验光。","refs":["中华医学会眼科学分会斜视与小儿眼科学组：儿童屈光不正与斜视弱视诊治指南（2014）","卫生部近视眼重点实验室：近视防治相关专家共识（2018）"]},{"id":"eye_cataract_loc","name":"白内障分级（LOCS III 简化 / 视力手术指征）","aka":["Lens Opacities Classification","LOCS III"],"cat":"晶状体","rank":8,"desc":"按核硬化、皮质楔形混浊与后囊下混浊分级判断白内障程度与手术时机。","inputs":[{"key":"nuclear","label":"核硬化程度（NO 1–6）","type":"number","min":1,"max":6,"step":0.1,"required":true},{"key":"cortical","label":"皮质白内障（C，分期 1–5）","type":"select","options":[{"value":1,"label":"1（轻微）"},{"value":2,"label":"2"},{"value":3,"label":"3（中度）"},{"value":4,"label":"4"},{"value":5,"label":"5（重度）"}],"required":true},{"key":"psc","label":"后囊下混浊 PSC（1–5）","type":"select","options":[{"value":1,"label":"1（轻微）"},{"value":2,"label":"2"},{"value":3,"label":"3（中度）"},{"value":4,"label":"4"},{"value":5,"label":"5（重度）"}],"required":true},{"key":"va","label":"最佳矫正视力（小数）","type":"number","min":0.01,"max":1.5,"step":0.01,"required":true}],"formula":"LOCS III：NO1–6、C1–5、P1–5；手术指征以最佳矫正视力 <0.5（或患者视功能需求受限）结合晶状体混浊程度","compute":"formula_only","algorithm":"grade = Math.max(nuclear, cortical, psc)\nv = grade  # 取最重成分\n","interpret":[{"when":"v <= 2 && va >= 0.8","level":"ok","text":"早期白内障：视力≥0.8，每 12 个月复查，矫正屈光并注意紫外线防护"},{"when":"v <= 3 && va >= 0.5","level":"warn","text":"轻中度：视力 0.5–0.8，6 个月复查；注意眩光与夜间视力，驾驶者评估"},{"when":"va < 0.5","level":"high","text":"视力 <0.5：具备白内障手术指征，行 IOL Master 生物测量与角膜内皮计数"},{"when":"v >= 4","level":"crit","text":"LOCS IV–V 级（重度/成熟期）：视力明显下降，尽早手术；成熟/过熟期警惕继发性青光眼与晶状体脱位"}],"note":"视力并非手术唯一标准：眩光、对比敏感度、色觉改变、单眼复视均为指征；PSC 即使视力尚可也常进展快（尤其糖尿病、激素使用者），建议手术时机前移。","refs":["中华医学会眼科学分会白内障及人工晶状体学组：中国白内障摘除手术专家共识（2022）","LOCS III. Arch Ophthalmol（1993）"]},{"id":"eye_dry_eye_osis","name":"干眼症状与严重度（OSDI 简化）","aka":["Dry Eye Severity","OSDI"],"cat":"眼表","rank":9,"desc":"综合症状频度、体征（BUT、Schirmer）分级干眼严重度与治疗路径。","inputs":[{"key":"symptom_freq","label":"症状频度","type":"select","options":[{"value":0,"label":"无或很少"},{"value":1,"label":"每周数次"},{"value":2,"label":"每日"},{"value":3,"label":"持续全天"}],"required":true},{"key":"but","label":"泪膜破裂时间 BUT（秒）","unit":"s","type":"number","min":0,"max":30,"step":0.5,"required":true},{"key":"schirmer","label":"Schirmer I 试验（mm/5 min，可空）","unit":"mm","type":"number","min":0,"max":35,"step":1,"required":false},{"key":"staining","label":"角膜荧光素染色（Oxford 分级 0–5）","type":"number","min":0,"max":5,"step":1,"required":true}],"formula":"BUT <10 s 为泪膜不稳定；Schirmer I ≤5 mm/5min 为水液缺乏；Oxford 染色 >3 为明显上皮损伤","compute":"formula_only","algorithm":"v = 0\nif symptom_freq >= 1 || but < 10 || staining >= 1: v = 1\nif symptom_freq >= 2 || but < 5 || staining >= 2: v = 2\nif symptom_freq >= 3 || but < 3 || staining >= 4 || (schirmer != null && schirmer <= 2): v = 3\n","interpret":[{"when":"v == 0","level":"ok","text":"无明显干眼：健康用眼，环境加湿，减少空调风对视；40 岁以上每年筛查"},{"when":"v == 1","level":"ok","text":"轻度：人工泪液（0.1% 玻璃酸钠 qid），热敷＋眼睑清洁，检查潜在干眼诱因（药物、屈光手术史）"},{"when":"v == 2","level":"warn","text":"中度：不含防腐剂人工泪液＋环孢素 0.05% 或立他司特，泪道栓塞评估，查 MGD/睑板腺"},{"when":"v >= 3","level":"high","text":"重度：自体血清滴眼、湿房镜、口服多西环素/omega-3，筛查 SS-B 与类天疱疮，警惕角膜穿孔"}],"note":"干眼需分型（水液缺乏型/蒸发过强型/混合型），蒸发型占多数（MGD 为常见原因），单纯补水无效。含防腐剂滴眼液每日 >4–6 次会加重眼表毒性。","refs":["中华医学会眼科学分会角膜病学组：干眼临床诊疗专家共识（2022）","TFOS DEWS II Report（2017）"]},{"id":"eye_retinal_detach_risk","name":"孔源性视网膜脱离危险因素积分","aka":["Rhegmatogenous RD Risk","视网膜脱离高危"],"cat":"眼底病变","rank":10,"desc":"结合高度近视、周边变性、症状与对侧眼病史，评估视网膜脱离高风险与随访策略。","inputs":[{"key":"high_myopia","label":"高度近视（≤−6.00 D）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"lattice","label":"周边视网膜格子样变性/视网膜裂孔","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"格子样变性"},{"value":2,"label":"裂孔/马蹄形撕裂"}],"required":true},{"key":"symptoms","label":"闪光感、飞蚊症骤增或视野遮挡","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"闪光/飞蚊骤增"},{"value":2,"label":"视野遮挡（幕样暗影）"}],"required":true},{"key":"fellow","label":"对侧眼发生过视网膜脱离","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"风险积分 = 高度近视(1) + 格子样变性(1)/裂孔(2) + 闪光或飞蚊骤增(1)/视野遮挡(2) + 对侧眼病史(1)，总分 0–5","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"低风险：常规年度眼底检查（高度近视无需额外干预）"},{"when":"v <= 2","level":"warn","text":"1–2 分：每 6–12 个月散瞳查周边视网膜；格子样变性无明显裂孔时观察为主"},{"when":"v == 3","level":"high","text":"3 分：4–6 个月复查或预防性激光光凝（尤其马蹄形裂孔、对侧眼病史），告知脱离预警症状"},{"when":"v >= 4","level":"crit","text":"≥4 分或缺视野遮挡：立即散瞳查眼底，怀疑视网膜脱离须当日转视网膜专科（巩膜扣带/玻璃体切割）"}],"note":"出现视野遮挡（幕样暗影）伴闪光提示已发生视网膜脱离，需急诊手术（黄斑区未脱离时手术效果最好）。有症状的视网膜裂孔行激光光凝；无症状格子样变性多观察。对侧眼病史者 <10% 的裂孔会进展，需个体化。","refs":["中华医学会眼科学分会眼底病学组：视网膜静脉阻塞、孔源性视网膜脱离诊断与治疗指南（2019）","AAO Preferred Practice Pattern Retinal Detachment（2018）"]}]},"gen_surg":{"items":[{"id":"clavien_dindo","name":"Clavien-Dindo 并发症分级","aka":["Clavien-Dindo Classification","CD 分级"],"cat":"并发症与手术风险","desc":"按「所需治疗干预的强度」对术后并发症进行客观分级，是外科并发症报告的标准分类。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ级","criteria":"任何偏离正常术后病程的情况，但无需药物、手术、内镜或介入治疗；允许的治疗为止吐药、退热药、镇痛药、利尿剂、电解质与物理治疗；亦包括床旁处理的切口感染","level":"ok"},{"label":"Ⅱ级","criteria":"需要Ⅰ级以外药物治疗，包括输血与全肠外营养","level":"warn"},{"label":"Ⅲa 级","criteria":"需手术、内镜或介入治疗，但无需全身麻醉","level":"warn"},{"label":"Ⅲb 级","criteria":"需手术、内镜或介入治疗，需全身麻醉","level":"high"},{"label":"Ⅳa 级","criteria":"危及生命的并发症，单个器官功能障碍（含透析）","level":"crit"},{"label":"Ⅳb 级","criteria":"危及生命的并发症，多器官功能障碍","level":"crit"},{"label":"Ⅴ级","criteria":"患者死亡","level":"crit"}],"note":"分级后缀「d」表示出院时该并发症仍未缓解，如「Ⅲa-d」。用于并发症严重度描述与质控，不用于预测。","refs":["Clavien PA, et al. Ann Surg 2009;250:187-196（Clavien-Dindo 分级原版）","Dindo D, et al. Ann Surg 2004;240:205-213","中国医师协会外科医师分会：手术并发症报告与评价专家共识（2018）"],"rank":1},{"id":"comprehensive_complication_index","name":"综合并发症指数（CCI）","aka":["Comprehensive Complication Index","CCI"],"cat":"并发症与手术风险","desc":"把每例患者的全部 Clavien-Dindo 并发症加权整合为 0–100 的单一连续变量，弥补只取「最重并发症」的信息损失。","inputs":[{"key":"cd_count","label":"并发症例次数（患者发生的并发症总数）","unit":"次","type":"number","min":0,"max":50,"step":1,"required":true},{"key":"cd_sum_weight","label":"各并发症 CCI 权重之和（按下方算法表查表累加）","type":"number","min":0,"max":500,"step":0.1,"required":true,"hint":"单次并发症权重：Ⅰ级 300、Ⅱ级 500、Ⅲa 1000、Ⅲb 1500、Ⅳa 2000、Ⅳb 2500、Ⅴ级 3500"}],"formula":"CCI = √(Σ wᵢ) / 2，wᵢ 为各并发症的 Clavien-Dindo 权重（Ⅰ=300、Ⅱ=500、Ⅲa=1000、Ⅲb=1500、Ⅳa=2000、Ⅳb=2500、Ⅴ=3500）；无并发症 CCI = 0","compute":"formula_only","algorithm":"v = 0\nif cd_count <= 0: v = 0\nelse: v = round(math.sqrt(cd_sum_weight) / 2, 1)\n级别判断见 interpret","interpret":[{"when":"v == 0","level":"ok","text":"无并发症（CCI 0）：术后恢复顺利"},{"when":"v < 10","level":"ok","text":"CCI < 10：以Ⅰ–Ⅱ级轻并发症为主，可继续常规观察与对症处理"},{"when":"v < 30","level":"warn","text":"CCI 10–29.9：中等并发症负荷，核对出院标准与随访计划"},{"when":"v < 40","level":"high","text":"CCI 30–39.9：重度并发症负荷，多需介入/再次手术，建议 MDT 讨论并记录并发症"},{"when":"v >= 40","level":"crit","text":"CCI ≥ 40：单次Ⅳ级或多次并发症累积，死亡或器官衰竭风险高，按危重患者管理"}],"note":"CCI 100 对应死亡（单次Ⅴ级）。仅计入手术相关并发症，不含入院原发病本身。","refs":["Slankamenac K, et al. Ann Surg 2013;258:1-7（CCI 原始文献）","中国医师协会外科医师分会：手术质量评价指标专家共识（2020）"],"rank":2},{"id":"possum","name":"POSSUM 生理与手术严重度评分","aka":["Physiological and Operative Severity Score","P-POSSUM"],"cat":"并发症与手术风险","desc":"用 12 项生理指标与 6 项手术指标评估普通外科手术（非创伤）的并发症与 30 天死亡风险，便于术前量化沟通与质控。","inputs":[{"key":"age","label":"年龄","type":"select","options":[{"value":1,"label":"≤60 岁"},{"value":2,"label":"61–70 岁"},{"value":4,"label":"≥71 岁"}],"required":true},{"key":"cardiac","label":"心脏征象","type":"select","options":[{"value":1,"label":"无心力衰竭"},{"value":2,"label":"使用利尿剂、地高辛或抗心绞痛/降压药"},{"value":4,"label":"周围水肿、华法林治疗或胸片临界心脏增大"},{"value":8,"label":"颈静脉压升高或胸片心脏增大"}],"required":true},{"key":"resp","label":"呼吸征象","type":"select","options":[{"value":1,"label":"无气促"},{"value":2,"label":"活动后气促或轻度 COPD"},{"value":4,"label":"限制性气促（上一层楼即气促）或中度 COPD"},{"value":8,"label":"静息气促（呼吸 ≥30 次/分）、纤维化或实变"}],"required":true},{"key":"sbp","label":"收缩压","type":"select","options":[{"value":1,"label":"110–130 mmHg"},{"value":2,"label":"131–170 或 100–109 mmHg"},{"value":4,"label":"≥171 或 90–99 mmHg"},{"value":8,"label":"≤89 mmHg"}],"required":true},{"key":"pr","label":"脉率","type":"select","options":[{"value":1,"label":"50–80 次/分"},{"value":2,"label":"81–100 或 40–49 次/分"},{"value":4,"label":"101–120 次/分"},{"value":8,"label":"≥121 或 ≤39 次/分"}],"required":true},{"key":"gcs","label":"Glasgow 昏迷评分","type":"select","options":[{"value":1,"label":"15 分"},{"value":2,"label":"12–14 分"},{"value":4,"label":"9–11 分"},{"value":8,"label":"≤8 分"}],"required":true},{"key":"hb","label":"血红蛋白","type":"select","options":[{"value":1,"label":"130–160 g/L"},{"value":2,"label":"115–129 或 161–170 g/L"},{"value":4,"label":"100–114 或 171–180 g/L"},{"value":8,"label":"≤99 或 ≥181 g/L"}],"required":true},{"key":"wcc","label":"白细胞计数","type":"select","options":[{"value":1,"label":"4.0–10.0 ×10⁹/L"},{"value":2,"label":"10.1–20.0 或 3.1–4.0 ×10⁹/L"},{"value":4,"label":"≥20.1 或 ≤3.0 ×10⁹/L"}],"required":true},{"key":"urea","label":"尿素","type":"select","options":[{"value":1,"label":"≤6.6 mmol/L"},{"value":2,"label":"6.7–9.2 mmol/L"},{"value":4,"label":"9.3–13.3 mmol/L"},{"value":8,"label":"≥13.4 mmol/L"}],"required":true},{"key":"na","label":"血钠","type":"select","options":[{"value":1,"label":"≥136 mmol/L"},{"value":2,"label":"131–135 mmol/L"},{"value":4,"label":"126–130 mmol/L"},{"value":8,"label":"≤125 mmol/L"}],"required":true},{"key":"k","label":"血钾","type":"select","options":[{"value":1,"label":"3.5–5.0 mmol/L"},{"value":2,"label":"3.2–3.4 或 5.1–5.3 mmol/L"},{"value":4,"label":"2.9–3.1 或 5.4–5.9 mmol/L"},{"value":8,"label":"≥6.0 mmol/L"}],"required":true},{"key":"ecg","label":"心电图","type":"select","options":[{"value":1,"label":"正常"},{"value":4,"label":"房颤（心室率 60–90 次/分）"},{"value":8,"label":"其他异常节律，或 ≥5 次/分早搏、病理性 Q 波、ST-T 改变"}],"required":true},{"key":"op_sev","label":"手术严重度","type":"select","options":[{"value":1,"label":"小手术"},{"value":2,"label":"中等手术"},{"value":4,"label":"大手术"},{"value":8,"label":"特大手术（Major+）"}],"required":true},{"key":"op_num","label":"手术数量","type":"select","options":[{"value":1,"label":"1 个"},{"value":4,"label":"2 个"},{"value":8,"label":">2 个"}],"required":true},{"key":"op_blood","label":"估计失血量","type":"select","options":[{"value":1,"label":"≤100 mL"},{"value":2,"label":"101–500 mL"},{"value":4,"label":"501–999 mL"},{"value":8,"label":"≥1000 mL"}],"required":true},{"key":"op_contam","label":"腹腔污染程度","type":"select","options":[{"value":1,"label":"无"},{"value":2,"label":"少量（浆液性液体）"},{"value":4,"label":"局部脓液"},{"value":8,"label":"游离肠内容物、脓液或血液"}],"required":true},{"key":"malig","label":"恶性肿瘤情况","type":"select","options":[{"value":1,"label":"无"},{"value":2,"label":"仅原发灶"},{"value":4,"label":"淋巴结转移"},{"value":8,"label":"远处转移"}],"required":true},{"key":"op_mode","label":"手术时机","type":"select","options":[{"value":1,"label":"择期"},{"value":4,"label":"入院 24 小时内急诊（复苏 >2 小时可行）"},{"value":8,"label":"紧急手术（需 2 小时内进行）"}],"required":true}],"formula":"PS = 12 项生理指标之和；OS = 6 项手术指标之和；并发症 ln[R1/(1−R1)] = −5.91 + 0.16×PS + 0.19×OS；POSSUM 死亡 ln[R2/(1−R2)] = −7.04 + 0.13×PS + 0.16×OS；P-POSSUM 死亡 ln[R/(1−R)] = −9.065 + 0.1692×PS + 0.1550×OS","compute":"formula_only","algorithm":"ps = age + cardiac + resp + sbp + pr + gcs + hb + wcc + urea + na + k + ecg\nos = op_sev + op_num + op_blood + op_contam + malig + op_mode\nmorb_r = 1 / (1 + Math.exp(-(-5.91 + 0.16*ps + 0.19*os)))\nmort_r = 1 / (1 + Math.exp(-(-7.04 + 0.13*ps + 0.16*os)))\nppossum_r = 1 / (1 + Math.exp(-(-9.065 + 0.1692*ps + 0.1550*os)))\nv = ps  # 结果同时展示 PS、OS 与三种预测概率","interpret":[{"when":"ps <= 20","level":"ok","text":"PS ≤20（低危）：并发症率约 14%、病死率约 0.2%，常规 ERAS 流程管理"},{"when":"ps <= 30","level":"warn","text":"PS 21–30（中危）：并发症率约 26%、病死率约 1%，术前优化心肺功能，术后加强监测"},{"when":"ps <= 40","level":"high","text":"PS 31–40（高危）：并发症率约 45%、病死率约 2%，建议 MDT 评估，术后考虑 ICU/HDU"},{"when":"ps > 40","level":"crit","text":"PS >40（极高危）：严重生理紊乱，病死率可达 5% 以上，应权衡手术必要性并充分知情同意"}],"note":"POSSUM 会高估低危患者死亡率，临床常以 P-POSSUM 校正；不适用于创伤患者。各项取 1/2/4/8 分，生理指标取术前值，缺项按 1 分计。","refs":["Copeland GP, et al. Br J Surg 1991;78:355-360（POSSUM 原始文献）","Whiteley MS, et al. Br J Surg 1996;83:1182-1185（P-POSSUM 回归方程）","中国医师协会外科医师分会：普通外科围手术期风险评估与质量管理专家共识（2019）"],"rank":3},{"id":"gs_nrs2002","name":"营养风险筛查 NRS 2002","aka":["Nutritional Risk Screening 2002","NRS 2002"],"cat":"并发症与手术风险","desc":"住院患者营养风险筛查首选工具，≥3 分提示存在营养风险，需进一步营养评定与干预。","inputs":[{"key":"age70","label":"年龄","type":"select","options":[{"value":0,"label":"<70 岁"},{"value":1,"label":"≥70 岁"}],"required":true},{"key":"bmi","label":"BMI 与体重变化（疾病严重度列前初筛）","type":"select","options":[{"value":0,"label":"BMI ≥20.5，近 3 个月体重下降 <5%"},{"value":2,"label":"BMI <20.5，或近 3 个月体重下降 >5%，或近 1 周进食 0–75%"}],"required":true,"hint":"BMI <18.5 且一般情况差者直接判为营养不良"},{"key":"disease","label":"疾病严重度（营养需求增加程度）","type":"select","options":[{"value":0,"label":"正常营养需求（如择期小手术）"},{"value":1,"label":"慢性病伴轻中度应激（如股骨颈骨折、血透、肝硬化、COPD）"},{"value":2,"label":"大手术、脑卒中、重症肺炎、血液系统恶性肿瘤"},{"value":3,"label":"颅脑损伤、骨髓移植、APACHEⅡ >10 的 ICU 患者"}],"required":true}],"formula":"NRS 2002 总分 = 营养状态受损评分（0–3）+ 疾病严重度评分（0–3）+ 年龄评分（≥70 岁 +1）","compute":"sum","interpret":[{"when":"v < 3","level":"ok","text":"得分 < 3：无营养风险，1 周后复查；如以后行重大手术需重新评估"},{"when":"v >= 3 && v < 5","level":"warn","text":"得分 ≥ 3：存在营养风险，制定营养支持计划；围手术期按手术计划评估是否给予预康复营养支持"},{"when":"v >= 5","level":"high","text":"得分 ≥ 5：高度营养风险，建议营养科会诊、术前 7–14 天营养支持（口服营养补充或肠内营养）后择期手术"}],"note":"初筛 4 个问题任一为「是」才继续做评定；术前长时间禁食、消化道肿瘤低位梗阻患者应特别注意。","refs":["Kondrup J, et al. Clin Nutr 2003;22:415-421（NRS 2002 原版）","中华医学会肠外肠内营养学分会：成人围手术期营养支持指南（2021）","中国成人住院患者营养风险筛查（NRS 2002）专家共识（2018）"],"rank":4},{"id":"alvarado","name":"Alvarado 评分（急性阑尾炎）","aka":["Alvarado Score","MANTRELS 评分"],"cat":"阑尾炎","desc":"依据症状、体征与血象诊断急性阑尾炎，是使用最广的阑尾炎临床概率评分。","inputs":[{"key":"migratory","label":"转移性右下腹痛","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"anorexia","label":"食欲减退/厌食","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"nausea","label":"恶心/呕吐","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"tenderness","label":"右下腹压痛（含反跳痛时为 2 分）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"rebound","label":"反跳痛或疼痛性抬头试验（压痛已计 2 分时此格仅记录）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"temp","label":"体温升高","type":"select","options":[{"value":0,"label":"<37.3 ℃"},{"value":1,"label":"37.3–38.5 ℃"},{"value":2,"label":">38.5 ℃"}],"required":true},{"key":"leuk","label":"白细胞","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"10–14.9 ×10⁹/L"},{"value":2,"label":"≥15 ×10⁹/L"}],"required":true},{"key":"neutrophils","label":"中性粒细胞左移（中性粒细胞 >75%）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Alvarado = 转移性右下腹痛 1（M）+ 厌食 1（A）+ 恶心呕吐 1（N）+ 右下腹压痛 2（T）+ 反跳痛 1（R）+ 体温升高 1（E）+ 白细胞升高 2（L）+ 中性粒左移 1（Mantrels），满分 10 分","compute":"sum","algorithm":"v = migratory + anorexia + nausea + tenderness + rebound + temp + leuk + neutrophils  # 满分 10","interpret":[{"when":"v <= 4","level":"ok","text":"≤4 分：急性阑尾炎可能性低（约 <30%），结合超声/CT 与 6–12 小时观察，警惕漏诊"},{"when":"v <= 6","level":"warn","text":"5–6 分：疑似阑尾炎，需影像学（超声首选，必要时 CT）确认，可住院观察"},{"when":"v <= 8","level":"high","text":"7–8 分：很可能阑尾炎（>80%），建议尽早行腹腔镜阑尾切除"},{"when":"v >= 9","level":"crit","text":"9–10 分：高度提示阑尾炎，尽快手术准备，术前抗生素与补液"}],"note":"儿童、孕妇与老年人表现不典型，Alvarado 评分敏感性下降；孕中晚期首选超声/MRI。","refs":["Alvarado A. Ann Emerg Med 1986;15:557-564（Alvarado 评分原版）","中华医学会外科学分会疝与腹壁外科学组：急性阑尾炎诊治专家共识（2021）"],"rank":1},{"id":"modified_alvarado","name":"改良 Alvarado 评分（MAS）","aka":["Modified Alvarado Score","MAS"],"cat":"阑尾炎","desc":"在 Alvarado 评分基础上去掉「中性粒细胞左移」、将白细胞阈值设为 10×10⁹/L，便于基层快速判断。","inputs":[{"key":"migratory","label":"转移性右下腹痛","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"anorexia","label":"食欲减退/厌食","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"nausea","label":"恶心/呕吐","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"tenderness","label":"右下腹压痛","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"rebound","label":"反跳痛（或疼痛性抬头试验，或咳嗽痛）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"temp","label":"体温升高","type":"select","options":[{"value":0,"label":"<37.3 ℃"},{"value":1,"label":"≥37.3 ℃"}],"required":true},{"key":"leuk","label":"白细胞 >10×10⁹/L","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true}],"formula":"MAS = M1 + A1 + N1 + 压痛2 + R1 + 体温1 + 白细胞2（满分 9 分）","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"≤4 分：阑尾炎可能性低，需影像学排除其他腹痛原因"},{"when":"v <= 6","level":"warn","text":"5–6 分：可能阑尾炎，建议影像学检查并观察 6–12 小时复查"},{"when":"v >= 7","level":"high","text":"≥7 分：高度提示急性阑尾炎，建议行急诊阑尾切除"}],"note":"改良 Alvarado 的 cut-off 常用 7 分；儿童与孕妇使用时需降低阴性阈值，避免延误。","refs":["Kalan M, et al. J R Soc Med 1994;87:551-554（MAS 原版）","中国研究型医院学会：急性阑尾炎临床实践指南（2020）"],"rank":2},{"id":"airs","name":"急性阑尾炎 AIRS 严重度评估","aka":["Appendicitis Inflammatory Response Score","AIRS"],"cat":"阑尾炎","desc":"用 CRP、中性粒细胞比例与腹膜刺激征评估阑尾炎严重度，较 Alvarado 更早识别复杂性阑尾炎。","inputs":[{"key":"vomit","label":"呕吐","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pain","label":"右下腹疼痛","type":"select","options":[{"value":1,"label":"轻度"},{"value":2,"label":"中度"},{"value":3,"label":"重度"}],"required":true},{"key":"rebound","label":"反跳痛/肌紧张（腹膜刺激征）","type":"select","options":[{"value":1,"label":"轻度"},{"value":2,"label":"中度"},{"value":3,"label":"重度"}],"required":true},{"key":"temp","label":"体温","type":"select","options":[{"value":0,"label":"<38.5 ℃"},{"value":1,"label":"≥38.5 ℃"}],"required":true},{"key":"wbc","label":"白细胞","type":"select","options":[{"value":0,"label":"<10 ×10⁹/L"},{"value":1,"label":"10–14.9"},{"value":2,"label":"≥15"}],"required":true},{"key":"neut","label":"中性粒细胞比例","type":"select","options":[{"value":0,"label":"<70%"},{"value":1,"label":"70–84%"},{"value":2,"label":"≥85%"}],"required":true},{"key":"crp","label":"C 反应蛋白","type":"select","options":[{"value":0,"label":"<10 mg/L"},{"value":1,"label":"10–49"},{"value":2,"label":"≥50"}],"required":true}],"formula":"AIRS = 呕吐1 + 疼痛部位严重度1–3 + 腹膜刺激征1–3 + 体温1 + 白细胞0–2 + 中性粒比例0–2 + CRP0–2（满分 12）","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：低疑诊，可门诊观察或影像学复核"},{"when":"v <= 7","level":"warn","text":"5–7 分：可能阑尾炎，建议急诊评估 + 超声/CT"},{"when":"v <= 11","level":"high","text":"8–11 分：高度疑似或复杂性阑尾炎，需急诊手术，术前广谱抗生素"},{"when":"v >= 12","level":"crit","text":"12 分：很可能为穿孔/复杂性阑尾炎，优先复苏 + 补液，尽快手术"}],"note":"AIRS ≥8 分对复杂性（穿孔/坏疽）阑尾炎有较好提示价值，此类患者术前需液体复苏并考虑留置引流。","refs":["Andersson M, Andersson RE. World J Surg 2008;32:1843-1849（AIRS 原版）","中华医学会外科学分会：急性阑尾炎诊治专家共识（2021）"],"rank":3},{"id":"ranson","name":"Ranson 评分（急性胰腺炎）","aka":["Ranson Criteria"],"cat":"胰腺炎","desc":"以入院时 5 项和 48 小时内 6 项指标评估急性胰腺炎严重程度，>3 分提示重症风险。","inputs":[{"key":"age","label":"年龄","type":"select","options":[{"value":0,"label":"≤55 岁"},{"value":1,"label":">55 岁"}],"required":true},{"key":"wbc","label":"白细胞","type":"select","options":[{"value":0,"label":"<16 ×10⁹/L"},{"value":1,"label":"≥16 ×10⁹/L"}],"required":true},{"key":"glu","label":"血糖","type":"select","options":[{"value":0,"label":"≤11.1 mmol/L"},{"value":1,"label":">11.1 mmol/L"}],"required":true},{"key":"ldh","label":"乳酸脱氢酶","type":"select","options":[{"value":0,"label":"≤350 U/L"},{"value":1,"label":">350 U/L"}],"required":true},{"key":"ast","label":"AST","type":"select","options":[{"value":0,"label":"≤250 U/L"},{"value":1,"label":">250 U/L"}],"required":true},{"key":"hct_drop","label":"48 小时内血细胞比容下降","type":"select","options":[{"value":0,"label":"<10%"},{"value":1,"label":"≥10%"}],"required":true},{"key":"bun_rise","label":"48 小时内 BUN 升高","type":"select","options":[{"value":0,"label":"<1.8 mmol/L"},{"value":1,"label":"≥1.8 mmol/L"}],"required":true},{"key":"ca","label":"血钙","type":"select","options":[{"value":0,"label":"≥2.0 mmol/L"},{"value":1,"label":"<2.0 mmol/L"}],"required":true},{"key":"pao2","label":"动脉血氧分压 PaO₂","type":"select","options":[{"value":0,"label":">60 mmHg"},{"value":1,"label":"≤60 mmHg"}],"required":true},{"key":"base_deficit","label":"碱缺失","type":"select","options":[{"value":0,"label":"≤4 mmol/L"},{"value":1,"label":">4 mmol/L"}],"required":true},{"key":"fluid_seq","label":"48 小时液体隔离量（估算）","type":"select","options":[{"value":0,"label":"<6 L"},{"value":1,"label":"≥6 L"}],"required":true}],"formula":"Ranson 评分 = 入院时 5 项（年龄、白细胞、血糖、LDH、AST）+ 48 小时内 6 项（HCT↓、BUN↑、血钙、PaO₂、碱缺失、液体隔离）","compute":"sum","algorithm":"v = sum(入院 5 项) + sum(48h 6 项)  # gallstone 项恒为 0 分，仅记录病因","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：轻症，病死率约 0–3%，以液体复苏、镇痛、早期肠内营养为主"},{"when":"v <= 4","level":"warn","text":"3–4 分：中度风险，病死率约 15%，需住院监护与 48 小时强化评估"},{"when":"v <= 5","level":"high","text":"5–6 分：重症倾向（病死率 40% 左右），收入 ICU/重症监护单元"},{"when":"v >= 6","level":"crit","text":"≥6 分：重度急性胰腺炎，病死率约 15–40%，多器官衰竭与感染性坏死风险高"}],"note":"48 小时指标须完整留观采集；胆源性胰腺炎的阈值不同（改良 Ranson），建议同时用 BISAP/CTSI 修正。","refs":["Ranson JH, et al. Surg Gynecol Obstet 1974;139:69-81（Ranson 原版）","中华医学会消化病学分会胰腺疾病学组：中国急性胰腺炎诊治指南（2019）"],"rank":1},{"id":"bisap","name":"BISAP 评分（急性胰腺炎）","aka":["Bedside Index for Severity in Acute Pancreatitis"],"cat":"胰腺炎","desc":"入院 24 小时内 5 项床旁指标预测重症急性胰腺炎，操作简便、无需 48 小时等待。","inputs":[{"key":"bun","label":"BUN","type":"select","options":[{"value":0,"label":"≤8.9 mmol/L（<25 mg/dL）"},{"value":1,"label":">8.9 mmol/L"}],"required":true},{"key":"gcs_impaired","label":"精神状态改变（GCS <15 或定向力障碍）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"sirs","label":"SIRS 标准 ≥2 项（T>38 或 <36 ℃、HR>90、RR>20 或 PaCO₂<32、WBC>12 或 <4 或幼稚粒 >10%）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age","label":"年龄","type":"select","options":[{"value":0,"label":"≤60 岁"},{"value":1,"label":">60 岁"}],"required":true},{"key":"effusion","label":"影像学胸腔积液","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"BISAP = 血尿素氮 1 + 精神异常 1 + SIRS 1 + 年龄>60 岁 1 + 胸腔积液 1（满分 5）","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：重症率 <1%，可内科保守治疗、早期肠内营养"},{"when":"v == 1","level":"ok","text":"1 分：重症风险低（约 1–2%），动态复查 BUN 与尿量"},{"when":"v == 2","level":"warn","text":"2 分：重症风险升高（约 5–7%），进入高依赖单元，强化液体管理"},{"when":"v >= 3","level":"crit","text":"≥3 分：重症风险高（病死率 10–20%），收入 ICU，警惕 48 小时内器官衰竭"}],"note":"BISAP 强调入院 24 小时内评估；BUN 升高是最强的单项预后指标，补液后仍需复测。","refs":["Wu BU, et al. Gut 2008;57:1698-1703（BISAP 原版）","中华医学会急诊医学分会：急性胰腺炎急诊诊断与治疗专家共识（2021）","中国急性胰腺炎诊治指南（2019，沈阳）"],"rank":2},{"id":"apache2","name":"APACHE Ⅱ 急性生理与慢性健康评分","aka":["Acute Physiology and Chronic Health Evaluation II"],"cat":"胰腺炎","desc":"重症监护通用的病情严重度评分（12 项急性生理 + 年龄 + 慢性健康），在急性胰腺炎中被广泛用于严重度分层。","inputs":[{"key":"temp","label":"体温","unit":"℃","type":"number","min":32,"max":43,"step":0.1,"required":true,"hint":"直肠温度"},{"key":"map","label":"平均动脉压","unit":"mmHg","type":"number","min":30,"max":160,"step":1,"required":true},{"key":"hr","label":"心率","unit":"次/分","type":"number","min":30,"max":220,"step":1,"required":true},{"key":"rr","label":"呼吸频率","unit":"次/分","type":"number","min":4,"max":70,"step":1,"required":true},{"key":"pao2","label":"PaO₂","unit":"mmHg","type":"number","min":30,"max":600,"step":1,"required":true,"hint":"FiO₂ ≥0.5 时用 A-a 梯度替代，需专用实现"},{"key":"ph","label":"动脉血 pH","type":"number","min":6.5,"max":7.8,"step":0.01,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":180,"step":1,"required":true},{"key":"k","label":"血钾","unit":"mmol/L","type":"number","min":1.5,"max":8.0,"step":0.1,"required":true},{"key":"crea","label":"血肌酐","unit":"μmol/L","type":"number","min":20,"max":1200,"step":1,"required":true,"hint":"急性肾衰时该项分值 ×2"},{"key":"hct","label":"血细胞比容","unit":"%","type":"number","min":10,"max":70,"step":0.1,"required":true},{"key":"wbc","label":"白细胞","unit":"×10⁹/L","type":"number","min":0.1,"max":80,"step":0.1,"required":true},{"key":"gcs","label":"GCS 评分","unit":"分","type":"number","min":3,"max":15,"step":1,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":15,"max":110,"step":1,"required":true},{"key":"chronic","label":"慢性健康状况","type":"select","options":[{"value":0,"label":"无严重器官功能不全/免疫抑制"},{"value":2,"label":"非手术或急诊术后：肝/心/呼吸/肾慢性功能不全或免疫抑制"},{"value":5,"label":"择期术后：上述严重器官功能不全或免疫抑制"}],"required":true}],"formula":"APACHE Ⅱ = 12 项急性生理分（0–4 分/项）+ 年龄分（≤44 岁 0；45–54 岁 2；55–64 岁 3；65–74 岁 5；≥75 岁 6）+ 慢性健康分（0/2/5）","compute":"formula_only","algorithm":"APS = score(temp) + score(map) + score(hr) + score(rr) + score(pao2) + score(ph) + score(na) + score(k) + score(scr) + score(hct) + score(wbc) + score(gcs)\n# 每项按 APACHE Ⅱ 原始分值表 0/1/2/3/4 分；scr 在急性肾衰时加倍\nage_pts: age<45→0；45–54→2；55–64→3；65–74→5；≥75→6\nv = APS + age_pts + chronic_pts","interpret":[{"when":"v <= 9","level":"ok","text":"≤9 分：预计病死率 <10%，常规监护"},{"when":"v <= 14","level":"warn","text":"10–14 分：预计病死率约 15%–25%，加强监护与器官功能复查"},{"when":"v <= 19","level":"high","text":"15–19 分：预计病死率约 25%–40%，收入 ICU"},{"when":"v <= 29","level":"crit","text":"20–29 分：预计病死率 40%–70%，需有创监测与器官支持"},{"when":"v >= 30","level":"crit","text":"≥30 分：预计病死率 >70%，按极危重患者管理并沟通预后"}],"note":"APACHE Ⅱ 取入住 ICU 后 24 小时内最差值；住院期间动态变化比单次分值更有意义。","refs":["Knaus WA, et al. Crit Care Med 1985;13:818-829（APACHE Ⅱ 原版）","中国急性胰腺炎诊治指南（2019）中重症急性胰腺炎 APACHEⅡ 评分推荐","中华医学会重症医学分会：ICU 患者病情严重度评分应用专家共识（2018）"],"rank":3},{"id":"ctsi","name":"CT 严重指数 CTSI（急性胰腺炎）","aka":["CT Severity Index","Balthazar CTSI"],"cat":"胰腺炎","desc":"结合增强 CT 胰腺坏死范围与炎症程度评估急性胰腺炎严重度，是判断局部并发症的关键影像工具。","inputs":[{"key":"balthazar","label":"Balthazar 炎症分级（CT 表现）","type":"select","options":[{"value":0,"label":"A 级：胰腺形态正常"},{"value":1,"label":"B 级：胰腺局灶或弥漫性增大"},{"value":2,"label":"C 级：胰腺实质及周围脂肪炎症改变"},{"value":3,"label":"D 级：单个液体积聚（肾前间隙）"},{"value":4,"label":"E 级：≥2 个液体积聚或脂肪间隙积液"}],"required":true},{"key":"necrosis","label":"坏死范围（增强 CT 无强化区）","type":"select","options":[{"value":0,"label":"无坏死"},{"value":2,"label":"坏死 <30%"},{"value":4,"label":"坏死 30%–50%"},{"value":6,"label":"坏死 >50%"}],"required":true}],"formula":"CTSI = Balthazar 分级分（0/1/2/3/4）+ 坏死范围分（0/2/4/6）；改良 CTSI（MCTSI）另加胰外并发症 2 分","compute":"sum","interpret":[{"when":"v <= 3","level":"ok","text":"0–3 分：轻症，病死率约 3%，无坏死或坏死 <30%，以内科支持治疗为主"},{"when":"v <= 6","level":"warn","text":"4–6 分：中度，病死率约 6%，需监测局部并发症"},{"when":"v >= 7","level":"crit","text":"7–10 分：重度，病死率 17%–40%，感染性坏死风险高，考虑多学科诊疗与 ICU"}],"note":"最佳检查时间为起病 72 小时后，过早 CT 会低估坏死范围；疑似胆源性者先行超声。","refs":["Balthazar EJ, et al. Radiology 1990;174:331-336（CTSI 原版）","中国急性胰腺炎诊治指南（2019，沈阳）","中华医学会放射学分会：急性胰腺炎影像诊断专家共识（2020）"],"rank":4},{"id":"glasgow_blatchford","name":"Glasgow-Blatchford 评分（上消化道出血）","aka":["GBS","Blatchford Score"],"cat":"消化道出血","desc":"结合临床与化验指标预测上消化道出血患者是否需输血或内镜干预，无需内镜、适用范围广。","inputs":[{"key":"bun","label":"血尿素氮","type":"select","options":[{"value":0,"label":"<6.5 mmol/L"},{"value":2,"label":"6.5–7.9"},{"value":3,"label":"8.0–9.9"},{"value":4,"label":"10.0–24.9"},{"value":6,"label":"≥25.0"}],"required":true},{"key":"male","label":"性别","type":"select","options":[{"value":0,"label":"女性"},{"value":1,"label":"男性"}],"required":true},{"key":"hb","label":"血红蛋白（男性）","type":"select","options":[{"value":0,"label":"≥130 g/L"},{"value":1,"label":"120–129"},{"value":3,"label":"100–119"},{"value":6,"label":"<100"}],"required":true},{"key":"hb_f","label":"血红蛋白（女性）","type":"select","options":[{"value":0,"label":"≥120 g/L"},{"value":1,"label":"100–119"},{"value":6,"label":"<100"}],"required":true},{"key":"sbp","label":"收缩压","type":"select","options":[{"value":0,"label":"≥110 mmHg"},{"value":1,"label":"100–109"},{"value":2,"label":"90–99"},{"value":3,"label":"<90"}],"required":true},{"key":"hr","label":"心率","type":"select","options":[{"value":0,"label":"<100 次/分"},{"value":1,"label":"≥100 次/分"}],"required":true},{"key":"melena","label":"黑便","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"syncope","label":"晕厥","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"hepatic","label":"肝病史（已知或实验室提示）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"cardiac","label":"心功能不全史","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true}],"formula":"GBS = BUN 0–6 + 血红蛋白 0–6（按性别择一）+ 收缩压 0–3 + 心率 1 + 黑便 1 + 晕厥 2 + 肝病 2 + 心衰 2（满分 23）","compute":"sum","algorithm":"v = bun + (hb if male == 1 else hb_f) + sbp + hr + melena + syncope + hepatic + cardiac","interpret":[{"when":"v == 0","level":"ok","text":"0 分：极低危，可考虑门诊处理并安排门诊胃镜"},{"when":"v <= 3","level":"ok","text":"1–3 分：低危，可住院观察 24 小时，择期内镜"},{"when":"v <= 6","level":"warn","text":"4–6 分：中危，需住院并 24 小时内内镜"},{"when":"v >= 7","level":"crit","text":"≥7 分：高危，需输血准备、12 小时内急诊内镜，必要时 ICU"}],"note":"女性不需填 hemoglobin 男性项（取 0）。GBS 0 分在多数指南中可界定为可门诊患者。","refs":["Blatchford O, et al. Lancet 2000;356:1318-1321（GBS 原版）","中华医学会消化内镜学分会：急性非静脉曲张性上消化道出血诊治指南（2018）","急性上消化道出血急诊诊治流程专家共识（2020）"],"rank":1},{"id":"rockall","name":"Rockall 再出血与死亡风险评分","aka":["Rockall Score"],"cat":"消化道出血","desc":"上消化道出血后再出血与死亡风险的经典评分，分临床（内镜前）与完整（含内镜）两种用法。","inputs":[{"key":"age","label":"年龄","type":"select","options":[{"value":0,"label":"<60 岁"},{"value":1,"label":"60–79 岁"},{"value":2,"label":"≥80 岁"}],"required":true},{"key":"shock","label":"休克状态（收缩压/心率）","type":"select","options":[{"value":0,"label":"SBP ≥100 且 HR <100"},{"value":1,"label":"SBP ≥100 且 HR ≥100"},{"value":2,"label":"SBP <100"}],"required":true},{"key":"comorbid","label":"合并症","type":"select","options":[{"value":0,"label":"无重大合并症"},{"value":2,"label":"心力衰竭、缺血性心脏病或其他重要合并症"},{"value":3,"label":"肝衰竭、肾衰竭或恶性肿瘤"}],"required":true},{"key":"stigmata","label":"内镜下出血征象","type":"select","options":[{"value":0,"label":"无或仅见暗色基底"},{"value":1,"label":"血凝块、无出血的可见血管或黑斑"},{"value":2,"label":"活动性出血（喷血/渗血）"}],"required":true},{"key":"diagnosis","label":"内镜诊断","type":"select","options":[{"value":0,"label":"Mallory-Weiss 综合征或无病变"},{"value":1,"label":"所有其他诊断"},{"value":2,"label":"消化道恶性肿瘤"}],"required":true}],"formula":"完整 Rockall = 年龄 0/1/2 + 休克 0/1/2 + 合并症 0/2/3 + 内镜出血征象 0/1/2 + 内镜诊断 0/1/2（满分 11）；无内镜时为临床 Rockall（0–7）","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：再出血/死亡风险低（再出血约 5%），可住院观察后择期内镜"},{"when":"v <= 4","level":"warn","text":"3–4 分：中等风险（再出血 15–20%，病死率 5–10%），24 小时内内镜并监护"},{"when":"v <= 6","level":"high","text":"5–6 分：高风险（再出血约 40%，病死率 15–20%），需 ICU 监护"},{"when":"v >= 7","level":"crit","text":"≥7 分：极高风险（病死率 >30%），ICU 管理、输血与止血治疗并行"}],"note":"若尚未行内镜，可只填前 3 项作为临床 Rockall，用于风险评估而非再出血预测。","refs":["Rockall TA, et al. Gut 1996;38:316-321（Rockall 原版）","中华医学会消化内镜学分会：急性非静脉曲张性上消化道出血诊治指南（2018）"],"rank":2},{"id":"forrest","name":"Forrest 分级（溃疡出血内镜）","aka":["Forrest Classification"],"cat":"消化道出血","desc":"内镜下溃疡出血征象分级，决定内镜止血方式与再出血风险。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰa 级","criteria":"喷射性活动性出血","level":"crit"},{"label":"Ⅰb 级","criteria":"渗血（持续性活动性出血）","level":"crit"},{"label":"Ⅱa 级","criteria":"无活动性出血的裸露血管","level":"high"},{"label":"Ⅱb 级","criteria":"血管上附着血凝块","level":"warn"},{"label":"Ⅱc 级","criteria":"溃疡底部黑斑/色素点","level":"warn"},{"label":"Ⅲ 级","criteria":"清洁基底，无出血征象","level":"ok"}],"note":"Ⅰa、Ⅰb、Ⅱa 为再出血高危，需内镜下联合止血（注射+热凝/钛夹）；Ⅱb 建议冲洗后按高危处理；Ⅱc 与Ⅲ级一般不需内镜止血，可口服质子泵抑制剂。","refs":["Forrest JA, et al. Lancet 1974;2:394-397（Forrest 分级原版）","中华医学会消化内镜学分会：急性非静脉曲张性上消化道出血诊治指南（2018）","急性非静脉曲张性上消化道出血诊治（2015）多学科共识"],"rank":3},{"id":"child_pugh","name":"Child-Pugh 分级","aka":["Child-Turcotte-Pugh","CTP 评分"],"cat":"肝胆功能","desc":"肝硬化肝功能储备的经典分级，用于肝切除、分流术与肝移植的术前评估。","inputs":[{"key":"bili","label":"总胆红素","type":"select","options":[{"value":1,"label":"<34 μmol/L（<2 mg/dL）"},{"value":2,"label":"34–51 μmol/L"},{"value":3,"label":">51 μmol/L（>3 mg/dL）"}],"required":true},{"key":"alb","label":"白蛋白","type":"select","options":[{"value":1,"label":">35 g/L"},{"value":2,"label":"28–35 g/L"},{"value":3,"label":"<28 g/L"}],"required":true},{"key":"inr","label":"凝血酶原时间/INR","type":"select","options":[{"value":1,"label":"PT 延长 <4 s 或 INR <1.7"},{"value":2,"label":"PT 延长 4–6 s 或 INR 1.7–2.3"},{"value":3,"label":"PT 延长 >6 s 或 INR >2.3"}],"required":true},{"key":"ascites","label":"腹水","type":"select","options":[{"value":1,"label":"无"},{"value":2,"label":"轻度（易控制）"},{"value":3,"label":"中重度（难控制）"}],"required":true},{"key":"enceph","label":"肝性脑病","type":"select","options":[{"value":1,"label":"无"},{"value":2,"label":"1–2 级"},{"value":3,"label":"3–4 级"}],"required":true}],"formula":"Child-Pugh = 胆红素 + 白蛋白 + PT/INR + 腹水 + 肝性脑病（每项 1–3 分）；A 级 5–6、B 级 7–9、C 级 10–15","compute":"sum","algorithm":"v = sum(5 项)\nif v <= 6: grade = 'A'\nelif v <= 9: grade = 'B'\nelse: grade = 'C'","interpret":[{"when":"v <= 6","level":"ok","text":"Child-Pugh A 级（5–6 分）：肝功能代偿，可耐受大范围肝切除，围术期风险较低"},{"when":"v <= 9","level":"warn","text":"Child-Pugh B 级（7–9 分）：肝功能受损，需限肝切除范围、术前营养与减黄抗病毒等优化，术后肝衰竭风险明显升高"},{"when":"v >= 10","level":"crit","text":"Child-Pugh C 级（10–15 分）：失代偿，禁忌择期肝切除，应评估肝移植"}],"note":"胆红素单位以 μmol/L 表示；如采用改良 Child-Pugh 可用 INR 替代 PT 延长。","refs":["Pugh RN, et al. Br J Surg 1973;60:646-649（Child-Pugh 原版）","中国医师协会外科医师分会：肝切除术前肝脏储备功能评估专家共识（2011）","中华医学会外科学分会：成年人肝脏切除手术技术规范与操作指南（2022）"],"rank":1},{"id":"meld","name":"MELD 评分（终末期肝病模型）","aka":["Model for End-stage Liver Disease","MELD-Na"],"cat":"肝胆功能","desc":"基于胆红素、INR 与肌酐预测终末期肝病 3 个月死亡的评分，是肝移植优先排序的核心工具。","inputs":[{"key":"bili","label":"总胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true,"hint":"μmol/L ÷ 17.1 得 mg/dL"},{"key":"inr","label":"INR","type":"number","min":0.8,"max":10,"step":0.1,"required":true},{"key":"crea","label":"血肌酐","unit":"mg/dL","type":"number","min":0.2,"max":15,"step":0.1,"required":true,"hint":"μmol/L ÷ 88.4 得 mg/dL"},{"key":"na","label":"血钠（MELD-Na 用）","unit":"mmol/L","type":"number","min":100,"max":160,"step":1,"required":true},{"key":"dialysis","label":"近 1 周透析≥2 次","unit":"分","type":"number","min":0,"max":1,"step":1,"required":true,"hint":"0=否，1=是（肌酐取 4.0 mg/dL）"}],"formula":"MELD = 3.78×ln[胆红素(mg/dL)] + 11.2×ln(INR) + 9.57×ln[肌酐(mg/dL)] + 6.43（各项最低取 1.0，肌酐最高取 4.0）；MELD-Na = MELD + 1.32×(137−Na) − [0.033×MELD×(137−Na)]（Na 限于 125–137）","compute":"formula_only","algorithm":"b = max(bili, 1.0); i = max(inr, 1.0); c = max(crea, 1.0); if dialysis==1: c = 4.0; c = min(c, 4.0)\nv = round(3.78*Math.log(b) + 11.2*Math.log(i) + 9.57*Math.log(c) + 6.43)  # 6–25 分内\nmeld_na = v + 1.32*(137-min(max(na,125),137)) - (0.033*v*(137-min(max(na,125),137)))","interpret":[{"when":"v <= 9","level":"ok","text":"MELD ≤9：3 个月死亡风险低（<4%），可继续随访/抗病毒治疗"},{"when":"v <= 14","level":"warn","text":"MELD 10–14：3 个月死亡约 6%，进入肝移植评估窗口"},{"when":"v <= 19","level":"high","text":"MELD 15–19：3 个月死亡约 20%，优先推荐移植评估"},{"when":"v <= 29","level":"high","text":"MELD 20–29：3 个月死亡 25%–45%，需积极移植准备与并发症管理"},{"when":"v >= 30","level":"crit","text":"MELD ≥30：3 个月死亡 >50%，按终末期肝病管理，ICU 与移植中心紧急沟通"}],"note":"原始 MELD 公式上限为 40；MELD 3.0 已将白蛋白与性别纳入，中国移植分配仍以 MELD-Na 为主流。","refs":["Kamath PS, et al. Hepatology 2001;33:464-470（MELD 原版）","中国医师协会器官移植医师分会：中国肝移植受者评估与选择指南（2021）","中华医学会外科学分会：肝切除术围手术期肝脏功能评估专家共识（2017）"],"rank":2},{"id":"match_braun","name":"吻合口漏风险预测（Match/Braun-Anastomotic Leak）","aka":["Anastomotic Leak Risk Score","吻合口漏危险因素"],"cat":"肝胆功能","desc":"汇总结直肠（及胃、食管）吻合口漏的已知危险因素，术前识别高危患者并调整术式与术后监测策略。","inputs":[{"key":"male","label":"男性","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age","label":"年龄","type":"select","options":[{"value":0,"label":"≤65 岁"},{"value":1,"label":">65 岁"}],"required":true},{"key":"bmi","label":"BMI","type":"select","options":[{"value":0,"label":"<30 kg/m²"},{"value":1,"label":"≥30 kg/m²"}],"required":true},{"key":"asa","label":"ASA 分级","type":"select","options":[{"value":0,"label":"Ⅰ–Ⅱ级"},{"value":1,"label":"Ⅲ级及以上"}],"required":true},{"key":"dm","label":"糖尿病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"steroid","label":"长期使用激素/免疫抑制","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"malnutrition","label":"营养不良（白蛋白 <30 g/L 或 NRS≥5）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"neoadjuvant","label":"新辅助放化疗","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"emergency","label":"急诊手术","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"contaminated","label":"污染/感染术野","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"coloanal","label":"吻合口距肛缘 ≤5 cm（结肠肛管吻合）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"transfusion","label":"术中/术后输血","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"lap","label":"术式（腹腔镜/开放，仅记录不计分）","type":"select","options":[{"value":0,"label":"记录用（不计分）"}],"required":true},{"key":"reconstruct","label":"吻合方式","type":"select","options":[{"value":0,"label":"侧侧/端端为常规"},{"value":1,"label":"手工缝合或不加保护的消化道重建"}],"required":true,"hint":"结直肠手术中回肠造口保护可显著降低漏后后果，属保护性措施，不计分"}],"formula":"漏风险因素计分（非交叉验证模型）：每项高危因素 1 分，v = 累计分值；结合术式判断：直肠低位前切除 + 新辅助放化疗 + 男性为经典高危组合","compute":"sum","algorithm":"v = sum(各危险因素)  # 在 0–12 之间，仅作危险分层，不作个体概率","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：标准风险（结直肠漏率约 3%–7%），常规吻合 + 术后 24–48 小时复查 CRP/PCT 与体温"},{"when":"v <= 5","level":"warn","text":"3–5 分：风险升高，建议术中加强吻合（吻合器/加固缝合）、术后第 3–5 天 CRP 监测，警惕腹痛发热"},{"when":"v >= 6","level":"high","text":"≥6 分：高危，考虑预防性造口/引流，术后延迟进食，出现发热、腹痛、心动过速即复查 CT 与引流液"}],"note":"吻合口漏多发生在术后第 5–7 天；术后第 3 天 CRP 正常对排除漏有较高阴性预测价值。不作个体概率预测。","refs":["中华医学会外科学分会结直肠外科学组：结直肠吻合口漏预防与处理专家共识（2019）","中国医师协会结直肠肿瘤专业委员会：直肠癌前切除术后吻合口漏诊治中国专家共识（2022）","2020 ESES/ESCP 吻合口漏共识"],"rank":3},{"id":"ehs_hernia","name":"腹壁切口疝 EHS 分型","aka":["EHS Hernia Classification","欧洲疝学会分型"],"cat":"疝与乳腺甲状腺","desc":"按缺损位置（中线 M1–M5、侧方 L1–L4）与缺损宽度（W1–W3）对腹壁疝进行结构化分型，指导术式与补片选择。","inputs":[{"key":"site","label":"缺损位置","type":"select","options":[{"value":1,"label":"M1（剑突下）"},{"value":2,"label":"M2（上腹）"},{"value":3,"label":"M3（脐）"},{"value":4,"label":"M4（下腹）"},{"value":5,"label":"M5（耻骨上）"},{"value":6,"label":"L1（肋缘下）"},{"value":7,"label":"L2（侧腹）"},{"value":8,"label":"L3（髂窝）"},{"value":9,"label":"L4（腰/背）"}],"required":true},{"key":"width","label":"缺损宽度","type":"select","options":[{"value":1,"label":"W1：<4 cm"},{"value":2,"label":"W2：4–10 cm"},{"value":3,"label":"W3：>10 cm"}],"required":true}],"formula":"EHS 分型 = 位置（中线 M1–M5 / 侧方 L1–L4）+ 缺损宽度（W1 <4 cm、W2 4–10 cm、W3 >10 cm）","compute":"sum","algorithm":"site_codes = {1:'M1',2:'M2',3:'M3',4:'M4',5:'M5',6:'L1',7:'L2',8:'L3',9:'L4'}\nwidth_codes = {1:'W1',2:'W2',3:'W3'}\nlabel = site_codes[site] + width_codes[width]\nv = site*10 + width  # 仅编码，不用于求和解读","interpret":[{"when":"width == 1","level":"ok","text":"W1（<4 cm）：小缺损，腹腔镜 IPOM 或开放小切口修补，可考虑免补片或轻量补片（依据指南）"},{"when":"width == 2","level":"warn","text":"W2（4–10 cm）：中等缺损，多数推荐补片加强修补（Sublay/Underlay），术后引流与腹带"},{"when":"width == 3","level":"high","text":"W3（>10 cm）：巨大切口疝，需术前腹壁功能评估、可能需组织分离技术（TAR）与术前气腹，复发率与并发症率显著升高"}],"note":"宽度以术中测量为准；合并感染、肠瘘、复发疝等需另行评估是否为复杂疝（EHS「复杂腹壁疝」定义）。","refs":["Muysoms FE, et al. Hernia 2009;13:407-414（EHS 分型原版）","中华医学会外科学分会疝与腹壁外科学组：腹壁切口疝诊断和治疗指南（2018）"],"rank":1},{"id":"birads","name":"乳腺影像 BI-RADS 分级","aka":["BI-RADS","Breast Imaging Reporting and Data System"],"cat":"疝与乳腺甲状腺","desc":"统一乳腺超声/X 线/MRI 的描述与分类，0–6 类对应不同的恶性概率与处理建议。","inputs":[{"key":"category","label":"BI-RADS 分类","type":"select","options":[{"value":0,"label":"0 类：评估不完整"},{"value":1,"label":"1 类：阴性"},{"value":2,"label":"2 类：良性"},{"value":3,"label":"3 类：可能良性"},{"value":4,"label":"4 类：可疑恶性"},{"value":5,"label":"5 类：高度提示恶性"},{"value":6,"label":"6 类：已活检证实恶性"}],"required":true},{"key":"mode","label":"检查方法（超声/钼靶/MRI，仅记录不计分）","type":"select","options":[{"value":0,"label":"记录用（不计分）"}],"required":true}],"formula":"按 BI-RADS 第 5 版：0 需补充影像；1–2 良性随访；3 良性可能（恶性 <2%），短期随访 6 个月；4 类细分为 4A/4B/4C（恶性概率 2–10%/10–50%/50–95%）；5 类恶性 ≥95%；6 类已证实","compute":"sum","algorithm":"v = category  # 0–6\nmode 仅用于记录检查方法，不参与分级","interpret":[{"when":"category == 0","level":"warn","text":"0 类：评估不完整，需补充加压投照、局部放大或超声/MRI 后再分类"},{"when":"category <= 2","level":"ok","text":"1–2 类：良性发现，按年龄常规 1–2 年复查"},{"when":"category == 3","level":"warn","text":"3 类：可能良性（恶性 <2%），6 个月短期随访；随访 2–3 年稳定可降为 2 类"},{"when":"category == 4","level":"high","text":"4 类：可疑恶性（2%–95%），建议空心针穿刺活检（4A 2–10%、4B 10–50%、4C 50–95%）"},{"when":"category == 5","level":"crit","text":"5 类：高度提示恶性（≥95%），需活检并转入乳腺外科 MDT"},{"when":"category == 6","level":"crit","text":"6 类：已活检证实恶性，评估新辅助治疗或手术"}],"note":"中国指南在 BI-RADS 第 5 版基础上增加超声弹性成像与造影补充；钼靶适宜 40 岁以上女性筛查。","refs":["D'Orsi CJ, et al. ACR BI-RADS Atlas 5th ed. 2013","中华医学会超声医学分会：乳腺超声检查规范性指南（2015）","中国抗癌协会乳腺癌专业委员会：中国抗癌协会乳腺癌诊治指南与规范（2021）"],"rank":2},{"id":"tirads","name":"甲状腺结节 C-TIRADS 分级","aka":["C-TIRADS","TI-RADS","甲状腺影像报告和数据系统"],"cat":"疝与乳腺甲状腺","desc":"基于超声恶性征象计分的甲状腺结节风险分层（C-TIRADS 计数法），指导细针穿刺（FNA）指征与随访。","inputs":[{"key":"solid","label":"实性结节且实性成分低回声","type":"select","options":[{"value":0,"label":"否（囊性为主、海绵样或实性部分 <50%）"},{"value":1,"label":"是"}],"required":true},{"key":"hypoechoic","label":"实性成分回声水平","type":"select","options":[{"value":0,"label":"等回声或高回声"},{"value":1,"label":"低回声（低于周围甲状腺实质）"},{"value":2,"label":"极低回声（低于颈前肌）"}],"required":true},{"key":"microcalc","label":"点状强回声（微钙化）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"irregular","label":"边缘不规则、分叶或毛刺","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"taller","label":"纵横比 >1（前后径大于横径）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"comet","label":"彗星尾征（多为良性提示）","type":"select","options":[{"value":0,"label":"无"},{"value":-1,"label":"有"}],"required":true}],"formula":"C-TIRADS 恶性征象计分：实性低回声 +1、极低回声 +1、点状强回声 +1、边缘不规则 +1、纵横比 >1 +1，彗星尾征 −1；总分 0 分=3 类、1 分=4A、2 分=4B、3–4 分=4C、≥5 分=5 类","compute":"sum","algorithm":"s = Math.max(solid, 1 if hypoechoic == 2 else 0) + microcalc + irregular + taller + comet\nif s <= 0: cat = 3类\nelif s == 1: cat = 4A\nelif s == 2: cat = 4B\nelif s <= 4: cat = 4C\nelse: cat = 5类","interpret":[{"when":"v <= 0","level":"ok","text":"0 分（3 类）：良性可能，恶性率 <2%，>2 cm 随访 6–12 个月，必要时 FNA"},{"when":"v == 1","level":"warn","text":"1 分（4A 类）：低度可疑（2%–10%），>1.5 cm 建议 FNA，<1.5 cm 随访"},{"when":"v == 2","level":"warn","text":"2 分（4B 类）：中度可疑（10%–50%），>1 cm 建议 FNA"},{"when":"v <= 4","level":"high","text":"3–4 分（4C 类）：高度可疑（50%–90%），>0.5 cm 建议 FNA，必要时术中冰冻"},{"when":"v >= 5","level":"crit","text":"≥5 分（5 类）：恶性率 >90%，无论大小均建议 FNA 或直接手术评估"}],"note":"C-TIRADS 采用计数法，截值与 ACR TI-RADS 不同；实性低回声与回声水平不重复叠加。≤1 cm 的可疑结节需结合主动监测指征。","refs":["Zhou J, et al. Endocrine 2020;67:252-257（C-TIRADS 原版）","中华医学会超声医学分会：甲状腺结节超声恶性危险分层中国指南（C-TIRADS 2020）","中国医师协会外科医师分会甲状腺外科医师委员会：甲状腺结节和分化型甲状腺癌诊治指南（2022）"],"rank":3}]},"geriatric":{"items":[{"id":"geri_frail","name":"FRAIL 衰弱筛查量表","aka":["FRAIL Scale","衰弱量表"],"cat":"衰弱与躯体功能","desc":"5 个条目（疲乏、阻力、步行、疾病数、体重下降）筛查老年人衰弱，0 分健康、3 分以上为衰弱。","inputs":[{"key":"fatigue","label":"疲乏（过去 4 周大部分时间感到疲乏）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"resistance","label":"难以爬上一层楼梯（阻力）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ambulation","label":"难以步行一个街区（约 200–300 m）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"illness","label":"患有 ≥ 5 种慢性病","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"weight_loss","label":"近 1 年体重下降 ≥ 5%","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"FRAIL = 5 项「是」的个数（0–5）：0 健康、1–2 前期衰弱、≥ 3 衰弱","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：健康；每年复筛，维持运动与蛋白摄入"},{"when":"v <= 2","level":"warn","text":"1–2 分：前期衰弱（pre-frail）；每周 2–3 次抗阻训练 + 有氧运动，蛋白 1.0–1.2 g/kg/d，补充维生素 D"},{"when":"v >= 3","level":"high","text":"≥ 3 分：衰弱；多学科综合评估（运动、营养、多重用药、跌倒），运动处方（resistive training）可逆转为前期衰弱"},{"when":"v == 5","level":"crit","text":"5 分：重度衰弱；住院/跌倒/失能风险显著升高，注意肌少症、吞咽与压疮风险，及早转老年医学科"}],"note":"FRAIL 便于快速筛查但灵敏度低于 Fried 表型（需握力、步速）；营养不良（NRS2002/MNA）、多重用药与抑郁需同步评估。","refs":["Morley JE et al. J Nutr Health Aging 2012（FRAIL 量表）","中国老年人衰弱预防与干预专家共识（2017）","Fried LP et al. J Gerontol 2001（衰弱表型标准）"],"rank":1},{"id":"geri_cfs","name":"临床衰弱量表 CFS（Rockwood 9 级）","aka":["Clinical Frailty Scale","CFS","Rockwood 量表"],"cat":"衰弱与躯体功能","desc":"基于临床整体判断（认知、活动、疾病负担）将老年人分为 1–9 级，快捷可靠，广泛用于急诊、ICU 与术前评估。","inputs":[{"key":"cfs_level","label":"选择最符合的等级描述","type":"select","options":[{"value":1,"label":"1：非常健康（积极锻炼、体力充沛）"},{"value":2,"label":"2：健康（无活动受限，偶有轻微症状）"},{"value":3,"label":"3：维持健康（有慢性病但控制良好）"},{"value":4,"label":"4：极轻度衰弱（症状限制活动，但非依赖）"},{"value":5,"label":"5：轻度衰弱（工具性日常生活依赖外出/家务/用药）"},{"value":6,"label":"6：中度衰弱（穿衣沐浴等 ADL 需辅助，上楼梯困难）"},{"value":7,"label":"7：重度衰弱（完全依赖他人照顾，但非末期）"},{"value":8,"label":"8：极重度衰弱（完全依赖，接近生命末期）"},{"value":9,"label":"9：终末期（预期寿命 < 6 个月，无其他可逆因素）"}],"required":true}],"formula":"按 1–9 级临床描述直接判定（基于活动能力、认知与疾病负担的整体判断）","compute":"formula_only","levels":[{"label":"1 级 非常健康","criteria":"精力充沛、积极锻炼，同龄人中最健康的一类","level":"ok"},{"label":"2 级 健康","criteria":"无活动限制，偶有轻微症状但生活自理","level":"ok"},{"label":"3 级 维持健康","criteria":"有慢性疾病但症状控制良好，不依赖他人","level":"ok"},{"label":"4 级 极轻度衰弱","criteria":"症状导致一定活动受限，但生活基本独立","level":"warn"},{"label":"5 级 轻度衰弱","criteria":"完全独立但工具性日常活动（IADL，外出、家务、用药）受限","level":"warn"},{"label":"6 级 中度衰弱","criteria":"基本日常生活活动（ADL：穿衣、沐浴）需辅助，上楼梯困难","level":"warn"},{"label":"7 级 重度衰弱","criteria":"完全依赖他人照护，身体甚至认知明显衰退","level":"high"},{"label":"8 级 极重度衰弱","criteria":"完全依赖，卧床或接近生命末期，小幅疾病即可致命","level":"crit"},{"label":"9 级 终末期","criteria":"预期寿命 < 6 个月，通常无明显可逆因素","level":"crit"}],"interpret":[{"when":"cfs_level <= 3","level":"ok","text":"1–3 级：健康/维持健康；常规防病与筛查，保持运动（每周 ≥ 150 min 中等强度）"},{"when":"cfs_level <= 5","level":"warn","text":"4–5 级：极轻度至轻度衰弱；术前需衰弱评估，运动+营养干预，评估 IADL 依赖（用药管理、交通）"},{"when":"cfs_level <= 6","level":"warn","text":"6 级：中度衰弱；ADL 辅助、防跌倒、多学科门诊（老年综合评估 CGA），慎用经复杂代谢药物"},{"when":"cfs_level <= 7","level":"high","text":"7 级：重度衰弱；优先维护功能与舒适，避免侵入性过度治疗，评估长期照护与家庭支持"},{"when":"cfs_level >= 8","level":"crit","text":"8–9 级：极重度/终末期；以姑息与舒适照护为主，与患者/家属讨论治疗目标、预先医疗指示"}],"note":"CFS 2 级与 4 级的区分需结合基线状态与近期变化；急性疾病期评分会升高，应参考病前状态（更准确使用 4 周前水平）。可用于 ICU 决策，但不可单独作为放弃治疗依据。","refs":["Rockwood K et al. CMAJ 2005;173:489-495（CFS 原版）","Clinical Frailty Scale 2.0（Dalhousie University, 2020）","中国老年人衰弱预防与干预专家共识（2017）"],"rank":2},{"id":"geri_barthel","name":"Barthel 指数（ADL 评估）","aka":["Barthel Index","BI","日常生活活动能力评分"],"cat":"衰弱与躯体功能","desc":"10 项日常生活活动评分，总分 0–100，量化自理能力，用于卒中、康复及长期照护分级。","inputs":[{"key":"feeding","label":"进食（0/5/10）","type":"select","options":[{"value":0,"label":"0：依赖"},{"value":5,"label":"5：需部分帮助"},{"value":10,"label":"10：独立"}],"required":true},{"key":"bathing","label":"洗澡（0/5）","type":"select","options":[{"value":0,"label":"0：依赖"},{"value":5,"label":"5：独立"}],"required":true},{"key":"grooming","label":"修饰（0/5）","type":"select","options":[{"value":0,"label":"0：需帮助"},{"value":5,"label":"5：独立"}],"required":true},{"key":"dressing","label":"穿衣（0/5/10）","type":"select","options":[{"value":0,"label":"0：依赖"},{"value":5,"label":"5：需部分帮助"},{"value":10,"label":"10：独立"}],"required":true},{"key":"bowels","label":"大便控制（0/5/10）","type":"select","options":[{"value":0,"label":"0：失禁或需灌肠"},{"value":5,"label":"5：偶有失禁"},{"value":10,"label":"10：能控制"}],"required":true},{"key":"bladder","label":"小便控制（0/5/10）","type":"select","options":[{"value":0,"label":"0：失禁或留置导尿"},{"value":5,"label":"5：偶有失禁"},{"value":10,"label":"10：能控制"}],"required":true},{"key":"toilet","label":"如厕（0/5/10）","type":"select","options":[{"value":0,"label":"0：依赖"},{"value":5,"label":"5：需部分帮助"},{"value":10,"label":"10：独立（可自理导尿/便器）"}],"required":true},{"key":"transfer","label":"床椅转移（0/5/10/15）","type":"select","options":[{"value":0,"label":"0：完全依赖，不能坐"},{"value":5,"label":"5：需大部分帮助"},{"value":10,"label":"10：需少量帮助"},{"value":15,"label":"15：独立"}],"required":true},{"key":"mobility","label":"平地行走（0/5/10/15）","type":"select","options":[{"value":0,"label":"0：不能行走"},{"value":5,"label":"5：仅能用轮椅"},{"value":10,"label":"10：需 1 人帮助"},{"value":15,"label":"15：独立行走 45 m"}],"required":true},{"key":"stairs","label":"上下楼梯（0/5/10）","type":"select","options":[{"value":0,"label":"0：不能"},{"value":5,"label":"5：需帮助"},{"value":10,"label":"10：独立"}],"required":true}],"formula":"Barthel = 10 项之和，总分 0–100（每 5 分为一档）","compute":"sum","interpret":[{"when":"v >= 100","level":"ok","text":"100 分：完全自理；可社区独立生活"},{"when":"v >= 61","level":"ok","text":"61–99 分：轻度依赖；居家为主，评估跌倒与辅具（助行器、扶手）"},{"when":"v >= 41","level":"warn","text":"41–60 分：中度依赖；需要部分照护，康复训练（ADL 训练）改善潜力大"},{"when":"v >= 21","level":"high","text":"21–40 分：重度依赖；需照护者支持与长期护理评估，预防压疮与吸入性肺炎"},{"when":"v < 21","level":"crit","text":"≤ 20 分：完全依赖；长期照护机构或家庭护理，需多学科（营养、康复、护理）干预"}],"note":"Barthel 是「能力」评估而非「需要帮助」的量化；如厕与行走对老年人最敏感，5 分变化可视为临床有意义。失禁者需先排除尿路感染与便秘。","refs":["Mahoney FI, Barthel DW. Md State Med J 1965（Barthel 原版）","中国老年医学学会：老年人生活能力评估相关专家共识（2019）","MDS-RAI / 国家老年护理分级标准参考"],"rank":3},{"id":"geri_mmse","name":"简易精神状态检查 MMSE","aka":["Mini-Mental State Examination","MMSE"],"cat":"认知评估","desc":"30 项（定向、记忆、注意、语言、视空间），满分 30，按教育年限分界判定认知障碍，最广泛使用的痴呆筛查量表。","inputs":[{"key":"orientation","label":"定向力（时间 5 项 + 地点 5 项，0–10）","unit":"分","type":"number","min":0,"max":10,"step":1,"required":true},{"key":"registration","label":"即刻记忆（3 个词，0–3）","unit":"分","type":"number","min":0,"max":3,"step":1,"required":true},{"key":"attention","label":"注意与计算（100−7 连续 5 次，0–5）","unit":"分","type":"number","min":0,"max":5,"step":1,"required":true},{"key":"recall","label":"延迟回忆（3 个词，0–3）","unit":"分","type":"number","min":0,"max":3,"step":1,"required":true},{"key":"language","label":"语言（命名、复述、三步指令、阅读、书写、结构复制，0–9）","unit":"分","type":"number","min":0,"max":9,"step":1,"required":true},{"key":"education","label":"受教育年限","unit":"年","type":"number","min":0,"max":30,"step":1,"required":true}],"formula":"MMSE = 定向 10 + 即刻记忆 3 + 注意/计算 5 + 延迟回忆 3 + 语言 9，总分 0–30；分界随教育：文盲 ≤ 17、小学 ≤ 20、中学及以上 ≤ 24","compute":"sum","algorithm":"v = orientation + registration + attention + recall + language\nif education == 0: cutoff = 17\nelif education <= 6: cutoff = 20\nelse: cutoff = 24\nimpaired = v <= cutoff","interpret":[{"when":"education == 0 && v <= 17","level":"crit","text":"文盲 ≤ 17 分：提示认知障碍；行 MoCA（对轻度认知障碍更敏感）与头颅 MRI，排除谵妄、抑郁与甲状腺/维生素 B12 缺乏"},{"when":"education <= 6 && v <= 20","level":"crit","text":"小学教育 ≤ 20 分：提示认知障碍；需结合日常生活能力（ADL/IADL）区分 MCI 与痴呆"},{"when":"education > 6 && v <= 24","level":"crit","text":"中学及以上 ≤ 24 分：提示认知障碍；MMSE 对 MCI 敏感度低（约 60%），建议 MoCA 与神经心理成套测验"},{"when":"v >= 27","level":"ok","text":"≥ 27 分：认知功能大致正常；高分者仍需每年随访"},{"when":"v > 24","level":"warn","text":"25–26 分（分界以上 2 分内）：认知功能可疑减退；3–6 个月复评，注意听力视力、教育程度与抑郁影响"}],"note":"MMSE 对语言依赖高、受教育影响大，对执行功能与前额叶损害不敏感；已获取版权者方可使用，替代品可考虑 MoCA/MMSE-2。","refs":["Folstein MF, Folstein SE, McHugh PR. J Psychiatr Res 1975（MMSE 原版）","中国医学会神经病学分会：中国痴呆与认知障碍诊治指南（2018 版）","中国认知障碍诊治相关专家共识（中华医学会精神医学分会，2018）"],"rank":4},{"id":"geri_moca","name":"蒙特利尔认知评估 MoCA","aka":["Montreal Cognitive Assessment","MoCA"],"cat":"认知评估","desc":"30 分制（视空间/执行 5、命名 3、记忆 5、注意 6、语言 3、抽象 2、延迟回忆 5、定向 1），对轻度认知障碍（MCI）敏感。","inputs":[{"key":"visuospatial","label":"视空间与执行功能（0–5）","unit":"分","type":"number","min":0,"max":5,"step":1,"required":true,"hint":"连线、立方体、画钟"},{"key":"naming","label":"命名（0–3）","unit":"分","type":"number","min":0,"max":3,"step":1,"required":true},{"key":"memory","label":"记忆（0–5，仅记录不评分）","unit":"分","type":"number","min":0,"max":5,"step":1,"required":true,"hint":"此 5 分不计入总分"},{"key":"attention","label":"注意（数字广度、敲击、连减 7，0–6）","unit":"分","type":"number","min":0,"max":6,"step":1,"required":true},{"key":"language","label":"语言（复述、流畅性，0–3）","unit":"分","type":"number","min":0,"max":3,"step":1,"required":true},{"key":"abstraction","label":"抽象（0–2）","unit":"分","type":"number","min":0,"max":2,"step":1,"required":true},{"key":"delayed_recall","label":"延迟回忆（0–5）","unit":"分","type":"number","min":0,"max":5,"step":1,"required":true},{"key":"orientation","label":"定向（0–6）","unit":"分","type":"number","min":0,"max":6,"step":1,"required":true},{"key":"education","label":"受教育年限（< 12 年加 1 分）","unit":"年","type":"number","min":0,"max":30,"step":1,"required":true}],"formula":"MoCA = 视空间 5 + 命名 3 + 注意 6 + 语言 3 + 抽象 2 + 延迟回忆 5 + 定向 6，满分 30（记忆 5 分仅记录）；< 26 分提示认知障碍（< 12 年教育加 1 分）","compute":"formula_only","algorithm":"raw = visuospatial + naming + attention + language + abstraction + delayed_recall + orientation\nv = education < 12 ? Math.min(30, raw + 1) : raw\nimpaired = v < 26","interpret":[{"when":"v >= 26","level":"ok","text":"≥ 26 分：认知正常范围；若临床怀疑仍每 6–12 个月复评（MoCA 对 MCI 的显著优势在于执行功能）"},{"when":"v >= 22","level":"warn","text":"22–25 分：提示轻度认知障碍（MCI）；结合 ADL 保留、客观日常功能与影像（海马萎缩、白质高信号），3–6 个月复评"},{"when":"v >= 18","level":"high","text":"18–21 分：中度认知损害；评估日常生活能力与照顾需求，排查可逆病因（甲减、B12、抑郁、药物）"},{"when":"v < 18","level":"crit","text":"< 18 分：重度认知损害；评估痴呆分期（CDR）、吞咽与安全（走失、用药），讨论照护计划"}],"note":"MoCA 受教育与语言文化影响，需使用验证的中文版（北京版）；分数可因测试者培训与实践效应波动，同一患者建议随访使用相同版本。","refs":["Nasreddine ZS et al. J Am Geriatr Soc 2005（MoCA 原版）","中国痴呆与认知障碍诊治指南（2018 版）","MoCA 中文版验证研究（Beijing version, 2007）"],"rank":5},{"id":"geri_morse","name":"Morse 跌倒风险评估","aka":["Morse Fall Scale","MFS"],"cat":"跌倒与安全","desc":"6 项（跌倒史、次级诊断、助行器、静脉输液/肝素、步态、认知/精神状态）加权评分，评估住院患者跌倒风险。","inputs":[{"key":"history","label":"近 3 个月内有跌倒史","type":"select","options":[{"value":0,"label":"否"},{"value":25,"label":"是"}],"required":true},{"key":"secondary","label":"≥ 2 个医学诊断（次级诊断）","type":"select","options":[{"value":0,"label":"否"},{"value":15,"label":"是"}],"required":true},{"key":"aid","label":"使用辅助行走设备","type":"select","options":[{"value":0,"label":"无/卧床/护士协助"},{"value":15,"label":"拐杖/助行器"},{"value":30,"label":"扶家具行走"}],"required":true},{"key":"iv","label":"静脉输液/肝素锁","type":"select","options":[{"value":0,"label":"否"},{"value":20,"label":"是"}],"required":true},{"key":"gait","label":"步态","type":"select","options":[{"value":0,"label":"正常/卧床不能行走"},{"value":10,"label":"虚弱（步幅小、拖步）"},{"value":20,"label":"步态不稳（需帮助/扶墙）"}],"required":true},{"key":"mental","label":"精神状态/自知力","type":"select","options":[{"value":0,"label":"正确评估自身能力"},{"value":15,"label":"高估或忘记自身限制"}],"required":true}],"formula":"Morse = 6 项加权之和，总分 0–125；< 25 低风险、25–44 中风险、≥ 45 高风险","compute":"sum","interpret":[{"when":"v < 25","level":"ok","text":"0–24 分：低风险；常规护理（床挡、呼叫器、防滑鞋），住院期间每周复评"},{"when":"v <= 44","level":"warn","text":"25–44 分：中风险；增加巡视频次、照明与地面安全，协助如厕与转移"},{"when":"v >= 45","level":"high","text":"≥ 45 分：高风险；落实防跌倒措施（床旁陪护、离床报警、低床位、防滑垫），每班复评；跌倒后须排查骨折与硬膜下出血"},{"when":"gait == 20 && mental == 15","level":"crit","text":"步态不稳且高估自身能力：极高风险，需专人陪护并限制单独行走，警惕骨质疏松性脆性骨折"}],"note":"Morse 主要用于住院患者；社区与门诊可用 STEADI 或 TUG（5 次坐立 > 12 s 提示跌倒风险）。跌倒史是最强预测因子。","refs":["Morse JM, Morse RM, Tylko SJ. Can J Aging 1989（Morse 原版）","中国老年人跌倒风险评估与干预专家共识（2019）","CDC STEADI: Stopping Elderly Accidents, Deaths & Injuries（2019）"],"rank":6},{"id":"geri_nrs2002","name":"营养风险筛查 NRS 2002","aka":["Nutritional Risk Screening 2002","NRS2002"],"cat":"营养与全身评估","desc":"以营养状态受损、疾病严重度与年龄（≥ 70 岁加 1 分）计算，总分 ≥ 3 分提示存在营养风险，需营养干预。","inputs":[{"key":"nutrition_score","label":"营养状态受损（0–3）","type":"select","options":[{"value":0,"label":"0：正常营养状态"},{"value":1,"label":"1：体重下降 > 5%/3 个月，或前 1 周摄入为需要量 50–75%"},{"value":2,"label":"2：体重下降 > 5%/2 个月或 BMI 18.5–20.5 且一般状态差，或摄入 25–60%"},{"value":3,"label":"3：体重下降 > 5%/1 个月或 BMI < 18.5 且一般状态差，或摄入 0–25%"}],"required":true},{"key":"disease_score","label":"疾病严重度（0–3）","type":"select","options":[{"value":0,"label":"0：无疾病/轻"},{"value":1,"label":"1：慢性病急性发作/髋部骨折/肝硬化/COPD 等"},{"value":2,"label":"2：大手术、卒中、重度肺炎、血液恶性肿瘤"},{"value":3,"label":"3：颅脑损伤、骨髓移植、重症（APACHE > 10）、大面积烧伤"}],"required":true},{"key":"age_70","label":"年龄 ≥ 70 岁","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（加 1 分）"}],"required":true}],"formula":"NRS2002 = 营养状态受损（0–3）+ 疾病严重度（0–3）+ 年龄（≥ 70 岁 +1），总分 0–7；≥ 3 分有营养风险","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：无营养风险；1 周后复评（住院患者每周复查，病情变化时重评）"},{"when":"v == 3","level":"warn","text":"3 分：存在营养风险；启动营养治疗（口服营养补充 300–600 kcal/d），评估能量与蛋白需求"},{"when":"v <= 4","level":"high","text":"4 分：高营养风险；营养师会诊，肠内营养优先（蛋白 1.2–1.5 g/kg/d），每周复评是否达标"},{"when":"v >= 5","level":"crit","text":"≥ 5 分：极高风险；肠内/肠外营养支持，警惕再喂养综合征（低磷、低钾、低镁），监测前 72 h 电解质"}],"note":"NRS2002 适用于一般住院成人，老年人可直接用；ICU 与严重肝肾功能衰竭者的适用性需谨慎。不能进食 5–7 天以上者即使评分低也需营养支持。","refs":["Kondrup J et al. Clin Nutr 2003（NRS2002 原版）","ESPEN Guidelines on Nutritional Screening and Assessment（2019）","中国临床营养诊疗指南（2023，中华医学会肠外肠内营养学分会）"],"rank":7},{"id":"geri_cga","name":"老年综合评估 CGA 清单","aka":["Comprehensive Geriatric Assessment","CGA Checklist"],"cat":"营养与全身评估","desc":"多维度（躯体、认知、心理、营养、用药、功能与社会支持）综合评估清单，用于识别可干预的老年患者问题。","inputs":[{"key":"adl_dep","label":"日常生活能力（ADL）受限","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有（Barthel < 100）"}],"required":true},{"key":"iadl_dep","label":"工具性日常活动（IADL：购物、理财、用药、交通）受限","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"cog_imp","label":"认知功能损害（MMSE/MoCA 异常）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"mood","label":"抑郁或焦虑症状（PHQ-9 ≥ 10 / GAD-7 ≥ 10）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"malnutrition","label":"营养风险（MNA-SF ≤ 11 或 BMI < 18.5）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"polypharmacy","label":"多重用药（≥ 5 种长期用药）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"fall","label":"过去 1 年跌倒史或步态不稳","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"incontinence","label":"尿失禁/大便失禁","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"sensory","label":"视力/听力障碍","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"social","label":"社会支持不足/独居/照护者负担","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"CGA 问题数 = 10 个维度中阳性项之和（0–10）；阳性维度逐项制定干预计划（问题清单驱动）","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 项：无明显问题；每年复查一次老年综合评估"},{"when":"v <= 2","level":"warn","text":"1–2 项：轻度；针对阳性维度单学科干预（如跌倒→防跌倒、视力→验配镜）"},{"when":"v <= 4","level":"warn","text":"3–4 项：老年综合征共存；需多学科团队（老年医学、护理、康复、营养、药学）制定综合计划"},{"when":"v >= 5","level":"high","text":"≥ 5 项：复杂高龄患者；实施 CGA 干预方案，优先处理跌倒、多重用药与认知（老人用药用 Beers 标准）"}],"note":"CGA 价值在于「评估—干预—随访」闭环：每次至少记录 ADL/IADL、认知、抑郁、营养、用药与跌倒 6 项；临终阶段可简化为 ADL 与症状负担。","refs":["Ellis G, Whitehead MA, Robinson D, O'Neill D, Langhorne P. Age Ageing 2011（CGA 系统评价）","中国老年综合评估技术应用专家共识（2017）","AGS 2015 Beers Criteria（2019 更新）用于老年人多重用药审核"],"rank":8},{"id":"geri_tug","name":"起立-行走测试 TUG","aka":["Timed Up and Go Test","TUG","起立行走计时测试"],"cat":"衰弱与躯体功能","desc":"记录从椅子起立、行走 3 m 后返回坐下所需时间，评估移动能力与跌倒风险，是老年快速功能测试。","inputs":[{"key":"seconds","label":"完成测试时间","unit":"秒","type":"number","min":1,"max":300,"step":0.1,"required":true}],"formula":"TUG 时间（秒）< 10 独立、10–20 部分依赖、> 20 高风险跌倒（每增加 1 s 比例风险约 1.1）","compute":"formula_only","algorithm":"v = seconds\nif v < 10: level = '独立'\nif v < 20: level = '需辅助/部分依赖'\nelse: level = '高风险'\n# 使用助行器完成提示功能下降","interpret":[{"when":"seconds < 10","level":"ok","text":"< 10 s：移动能力良好，跌倒风险低；保持每周运动习惯"},{"when":"seconds <= 13.5","level":"ok","text":"10–13.5 s：功能正常下限；社区老年人仍需监测步速与平衡"},{"when":"seconds <= 20","level":"warn","text":"13.5–20 s：部分依赖/中度跌倒风险；康复训练（平衡、下肢力量）联合居家环境改造"},{"when":"seconds > 20 && seconds <= 30","level":"high","text":"20–30 s：高风险跌倒与失能；评估辅助器具、骨质疏松与跌倒原因（低血压、心律失常、药物、视力）"},{"when":"seconds > 30","level":"crit","text":"> 30 s：基本卧床级别活动能力，需照护与康复评估，警惕髋部骨折风险（骨质疏松治疗）"}],"note":"使用常规椅子与标准 3 m 距离、允许使用助行器；帕金森病与认知障碍患者需双侧测试并由同一位评估者执行。","refs":["Podsiadlo D, Richardson S. J Am Geriatr Soc 1991（TUG 原版）","中国老年人跌倒风险评估与干预专家共识（2019）","CDC STEADI 跌倒风险算法（2019）"],"rank":9},{"id":"geri_mna_sf","name":"微型营养评定简表 MNA-SF","aka":["Mini Nutritional Assessment Short Form","MNA-SF"],"cat":"营养与全身评估","desc":"6 项（进食、体重下降、活动、应激、神经心理、BMI/小腿围），总分 0–14，筛查老年营养不良。","inputs":[{"key":"intake","label":"近 3 个月进食量减少","type":"select","options":[{"value":0,"label":"0：严重减少"},{"value":1,"label":"1：中度减少"},{"value":2,"label":"2：无减少"}],"required":true},{"key":"weight_loss","label":"近 3 个月体重下降","type":"select","options":[{"value":0,"label":"0：> 3 kg"},{"value":1,"label":"1：不知道"},{"value":2,"label":"2：1–3 kg"},{"value":3,"label":"3：无"}],"required":true},{"key":"mobility","label":"活动能力","type":"select","options":[{"value":0,"label":"0：卧床或轮椅"},{"value":1,"label":"1：可下床但不能外出"},{"value":2,"label":"2：可外出"}],"required":true},{"key":"stress","label":"近 3 个月心理应激或急性病","type":"select","options":[{"value":0,"label":"0：是"},{"value":2,"label":"2：否"}],"required":true},{"key":"neuropsych","label":"神经心理问题","type":"select","options":[{"value":0,"label":"0：严重痴呆或抑郁"},{"value":1,"label":"1：轻度痴呆"},{"value":2,"label":"2：无"}],"required":true},{"key":"bmi","label":"BMI（kg/m²）","type":"select","options":[{"value":0,"label":"0：< 19"},{"value":1,"label":"1：19–< 21"},{"value":2,"label":"2：21–< 23"},{"value":3,"label":"3：≥ 23"}],"required":true,"hint":"无法测身高时以小腿围 < 31 cm 记 0 分"}],"formula":"MNA-SF = 进食 + 体重下降 + 活动 + 应激 + 神经心理 + BMI（或小腿围），总分 0–14；≥ 12 正常、8–11 有风险、0–7 营养不良","compute":"sum","interpret":[{"when":"v >= 12","level":"ok","text":"12–14 分：营养状况正常；每 3 个月复评，注意蛋白质摄入"},{"when":"v >= 8","level":"warn","text":"8–11 分：存在营养不良风险；营养师评估，口服营养补充与饮食强化，筛查吞咽（洼田饮水试验）"},{"when":"v < 8","level":"high","text":"0–7 分：营养不良；全面营养评估（含白蛋白、前白蛋白、维生素 D），制定个体化营养支持，警惕肌肉减少症与功能下降"}],"note":"MNA-SF 中 BMI 界值依亚洲人群调整（≥ 23 分满分）；卧床患者用小腿围（CC）替代 BMI。营养筛查阳性不等于需肠外营养。","refs":["Guigoz Y, Vellas B, Garry PJ. Nutr Rev 1996 / Vellas B et al. 2006（MNA-SF）","中国老年人营养不良防治专家共识（2017）","ESPEN Guidelines on Clinical Nutrition and Hydration in Geriatrics（2019）"],"rank":10}]},"gi":{"items":[{"id":"child_pugh","name":"Child-Pugh 分级（肝硬化）","aka":["Child-Pugh Score","Child 分级","CTP"],"cat":"肝硬化","rank":1,"desc":"用 5 项临床指标（胆红素、白蛋白、INR、腹水、肝性脑病）评估肝硬化储备功能，分 A/B/C 三级。","inputs":[{"key":"bili","label":"总胆红素","unit":"μmol/L","type":"number","min":1,"max":800,"step":1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":true},{"key":"inr","label":"INR（或凝血酶原时间延长秒数）","unit":"","type":"number","min":0.6,"max":6,"step":0.1,"required":true},{"key":"ascites","label":"腹水","type":"select","required":true,"options":[{"value":1,"label":"无"},{"value":2,"label":"轻度（易控制/药物可控制）"},{"value":3,"label":"中重度（难控制）"}]},{"key":"enceph","label":"肝性脑病（West-Haven）","type":"select","required":true,"options":[{"value":1,"label":"无"},{"value":2,"label":"1–2 级"},{"value":3,"label":"3–4 级"}]}],"formula":"各项 1–3 分求和（5–15 分）：A 级 5–6 分、B 级 7–9 分、C 级 10–15 分","compute":"child_pugh","algorithm":"# 分支逻辑\nbili: <34 → 1；34–51 → 2；>51 → 3（μmol/L）\nalb:  >35 → 1；28–35 → 2；<28 → 3（g/L）\ninr:  <1.7 → 1；1.7–2.3 → 2；>2.3 → 3\n      （无 INR 时可用 PT 延长：<4 s → 1；4–6 s → 2；>6 s → 3）\nascites / encephalopathy 直接取 select 值（1/2/3）\nv = bili_pt + alb_pt + inr_pt + ascites + enceph   # 5–15\nif v <= 6: grade = 'A'\nelse if v <= 9: grade = 'B'\nelse: grade = 'C'\n返回 { v, grade }","interpret":[{"when":"v >= 10","level":"crit","text":"C 级（10–15 分）：肝功能失代偿，手术风险极高，1 年生存率约 45%；优先评估肝移植、TIPS 与并发症综合管理"},{"when":"v >= 7","level":"warn","text":"B 级（7–9 分）：中度肝功能受损，择期手术需风险评估（> 2 分即需多学科讨论），避免肝毒性药物与诱因"},{"when":"v <= 6","level":"ok","text":"A 级（5–6 分）：代偿良好，多可耐受一般手术；仍需监测静脉曲张、HCC 筛查与营养"}],"note":"胆红素、白蛋白、INR 建议取同一天晨血；腹水与 HE 分级带主观性。Child-Pugh 含腹水与 HE 两主观项，近年 MELD 3.0 用于移植排序更客观。","refs":["2019 中国肝硬化诊治指南（中华医学会肝病学分会）","2015 肝硬化门静脉高压食管胃底静脉曲张出血防治共识（Child-Pugh 分级）","Pugh RN, et al. Transection of the oesophagus for bleeding oesophageal varices. Br J Surg 1973"]},{"id":"meld3","name":"MELD 3.0 评分","aka":["MELD 3.0","Model for End-stage Liver Disease 3.0"],"cat":"肝硬化","rank":2,"desc":"加入性别与白蛋白的终末期肝病模型，用于移植排序与短期死亡风险评估。","inputs":[{"key":"bili","label":"总胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true,"hint":"μmol/L ÷ 17.1"},{"key":"inr","label":"INR","unit":"","type":"number","min":0.6,"max":6,"step":0.1,"required":true},{"key":"crea","label":"肌酐","unit":"mg/dL","type":"number","min":0.2,"max":12,"step":0.1,"required":true,"hint":"μmol/L ÷ 88.4；>4.0 按 4.0 计"},{"key":"alb","label":"白蛋白","unit":"g/dL","type":"number","min":1,"max":5.5,"step":0.1,"required":true,"hint":"g/L ÷ 10；<1.5 按 1.5 计"},{"key":"sex","label":"性别","type":"select","required":true,"options":[{"value":0,"label":"男"},{"value":1,"label":"女"}]}],"formula":"MELD 3.0 = 1.33×女性 + 4.56×ln(胆红素) + 0.82×(137 − Na) − 0.24×(137 − Na)×ln(胆红素) + 9.53×ln(INR) + 0.90×(6.38 − 白蛋白) − 9.53；结果取整，范围 6–40；胆红素 <1.0 按 1.0 计","compute":"meld3","algorithm":"bili_c = max(bili, 1.0); crea_c = max(min(crea, 4.0), 1.0); alb_c = max(alb, 1.5); na = 137\nx = 1.33*sex + 4.56*log(bili_c) + 0.82*(na - na) - 0.24*(na - na)*log(bili_c) + 9.53*log(inr) + 0.90*(6.38 - alb_c) - 9.53\n注：本条目未采集血钠，MELD 3.0 原式中 Na 项（0.82×(137−Na) − 0.24×(137−Na)×ln(bili)）在 Na=137 时归零；有低钠血症（<125 mmol/L）时应改用完整公式（见 meld_na 条目）\nv = round(x); if v < 6 → 6; if v > 40 → 40","interpret":[{"when":"v >= 30","level":"crit","text":"MELD 3.0 ≥ 30：3 个月死亡风险极高，属移植高优先级，转诊移植中心并强化并发症管理"},{"when":"v >= 20","level":"high","text":"20–29 分：失代偿与死亡风险显著升高，评估肝移植适应证，处理感染、出血与电解质紊乱"},{"when":"v >= 15","level":"warn","text":"15–19 分：需纳入移植评估流程，密切随访腹水、肾功能与脑病"},{"when":"v >= 10","level":"warn","text":"10–14 分：中度风险，监测并发症与营养状态，避免肝毒性药物"},{"when":"v >= 0","level":"ok","text":"≤ 9 分：短期风险相对较低，按 Child-Pugh 与并发症随访"}],"note":"终末期肾病患者无法用血清肌酐反映肾功能（常伴 INR/胆红素异常）。MELD 3.0 在女性中计 +1.33 分以纠偏。中国肝移植器官分配实际仍以 MELD-Na 与当地规范为准。","refs":["Kim WR, et al. MELD 3.0: The Model for End-stage Liver Disease Updated for the Modern Era. Gastroenterology 2021","2019 中国肝硬化诊治指南（评分工具应用）","2018 肝移植技术管理规范（国家卫健委）"]},{"id":"meld_na","name":"MELD-Na 评分","aka":["MELD-Na","MELD 钠"],"cat":"肝硬化","rank":3,"desc":"MELD 加血钠修正，预测终末期肝病 3 个月死亡率，用于移植等待期排序。","inputs":[{"key":"bili","label":"总胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true},{"key":"inr","label":"INR","unit":"","type":"number","min":0.6,"max":6,"step":0.1,"required":true},{"key":"crea","label":"肌酐","unit":"mg/dL","type":"number","min":0.2,"max":12,"step":0.1,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":110,"max":150,"step":1,"required":true,"hint":"<125 按 125 计，>137 按 137 计"}],"formula":"MELD = 3.78×ln(胆红素) + 11.2×ln(INR) + 9.57×ln(肌酐) + 6.43（上限各 40）；MELD-Na = MELD + 1.32×(137 − Na) − 0.033×MELD×(137 − Na)","compute":"meld_na","algorithm":"bili_c = max(bili, 1.0); crea_c = min(max(crea, 1.0), 4.0); inr_c = max(inr, 1.0); na_c = min(max(na, 125), 137)\nmeld = 3.78*log(bili_c) + 11.2*log(inr_c) + 9.57*log(crea_c) + 6.43\nif meld < 6 → 6; if meld > 40 → 40\nmeldna = meld + 1.32*(137 - na_c) - 0.033*meld*(137 - na_c)\nv = round(min(max(meldna, 6), 40))\n返回 { meld, meldna }","interpret":[{"when":"v >= 30","level":"crit","text":"MELD-Na ≥ 30：3 个月死亡风险极高，属肝移植优先级别，转诊移植中心，强化并发症管理"},{"when":"v >= 20","level":"high","text":"20–29 分：3 个月死亡率明显升高，评估肝移植适应证并治疗诱因（感染、出血、电解质紊乱）"},{"when":"v >= 15","level":"warn","text":"15–19 分：失代偿加重风险，纳入移植评估流程，密切随访"},{"when":"v >= 10","level":"warn","text":"10–14 分：中度风险，监测腹水、感染与肾功能，避免肝毒性药物"},{"when":"v >= 0","level":"ok","text":"≤ 9 分：短期风险相对较低，按 Child-Pugh 与并发症随访"}],"note":"肌酐应在无利尿剂干扰与未透析状态下测定；若使用血液透析，肌酐按 4.0 计。低钠血症常提示稀释性低钠与高死亡风险走势。","refs":["Kim WR, et al. Hyponatremia and mortality among patients on the liver-transplant waiting list. NEJM 2008","2019 中国肝硬化诊治指南","2018 肝移植技术管理规范（国家卫健委）"]},{"id":"he_west_haven","name":"肝性脑病 West-Haven 分级","aka":["West Haven criteria","HE grading"],"cat":"肝硬化","rank":4,"desc":"按意识、定向力、扑翼样震颤与昏迷程度将肝性脑病分为 0–4 级，是临床与 Child-Pugh 判读的标准分级。","inputs":[{"key":"grade_sel","label":"临床表现对应级别","type":"select","required":true,"options":[{"value":0,"label":"0 级：无异常，仅心理测量异常"},{"value":1,"label":"1 级：轻度精神错乱、欣快或淡漠、注意力下降"},{"value":2,"label":"2 级：嗜睡、定向力与计算力减退、明显扑翼样震颤、行为改变"},{"value":3,"label":"3 级：昏睡但可唤醒、言语不清、明显意识模糊"},{"value":4,"label":"4 级：昏迷（对疼痛刺激无反应）"}]}],"formula":"按临床表现判级 0–4 级（1–4 级可再分为 A 型急性肝衰竭、B 型门体分流无肝硬化、C 型肝硬化相关）","compute":"formula_only","algorithm":"直接取 grade_sel（0-4）作为分级；A 型=急性肝衰竭、B 型=门体分流无肝硬化、C 型=肝硬化相关\nv = grade_sel","interpret":[{"when":"grade_sel == 4","level":"crit","text":"4 级：昏迷，需气道保护与 ICU 监护，排除脑水肿（急性肝衰竭）、低血糖、电解质紊乱与颅内病变"},{"when":"grade_sel == 3","level":"crit","text":"3 级：昏睡可唤醒，禁食蛋白暂不限制过严但需控制诱因，乳果糖灌肠/口服，纠正低钾低钠与感染"},{"when":"grade_sel == 2","level":"high","text":"2 级：明显 HE，启动乳果糖阶梯治疗（至每日 2–3 次软便），利福昔明作为二级预防，处理消化道出血等诱因"},{"when":"grade_sel == 1","level":"warn","text":"1 级：早期 HE，寻找诱因（便闭、感染、低钾、消化道出血、镇静药、TIPS），乳果糖滴定"},{"when":"grade_sel == 0","level":"ok","text":"0 级：无临床 HE；曾发生显性 HE 者应行二级预防（乳果糖±利福昔明）"}],"note":"West-Haven 标准主观性强、观察者一致性低；建议结合 HE 简易分级或心理测量（PHES）识别隐匿性 HE（MHE）。乳果糖初始剂量按说明书，以每日 2–3 次软便为目标调整。","refs":["2018 肝硬化肝性脑病诊疗指南（中华医学会消化病学分会）","2014 AASLD/EASL Practice Guidelines on Hepatic Encephalopathy","中国肝性脑病诊治共识（2022）"]},{"id":"gb_score","name":"Glasgow-Blatchford 评分（上消化道出血）","aka":["GBS","Glasgow-Blatchford Score"],"cat":"消化道出血","rank":5,"desc":"上消化道出血入院时风险分层，评估是否需内镜干预、输血与住院。","inputs":[{"key":"bun","label":"尿素氮 BUN","type":"select","required":true,"options":[{"value":0,"label":"小于 6.5 mmol/L（18.2 mg/dL）"},{"value":2,"label":"6.5–7.9 mmol/L"},{"value":3,"label":"8.0–9.9 mmol/L"},{"value":4,"label":"10.0–24.9 mmol/L"},{"value":6,"label":"≥ 25.0 mmol/L"}]},{"key":"hb","label":"血红蛋白（男）","type":"select","required":true,"options":[{"value":0,"label":"≥ 130 g/L"},{"value":1,"label":"120–129 g/L"},{"value":3,"label":"100–119 g/L"},{"value":6,"label":"< 100 g/L"}]},{"key":"sbp","label":"收缩压","type":"select","required":true,"options":[{"value":0,"label":"≥ 110 mmHg"},{"value":1,"label":"100–109 mmHg"},{"value":2,"label":"90–99 mmHg"},{"value":3,"label":"< 90 mmHg"}]},{"key":"hr","label":"心率","type":"select","required":true,"options":[{"value":0,"label":"< 100 次/分"},{"value":1,"label":"100–119 次/分"},{"value":2,"label":"≥ 120 次/分"}]},{"key":"melena","label":"黑便","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"syncope","label":"晕厥","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":2,"label":"有"}]},{"key":"liver","label":"肝病史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":2,"label":"有"}]},{"key":"cardiac","label":"心力衰竭病史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":2,"label":"有"}]}],"formula":"GBS = BUN(0–6) + Hb(0–6) + SBP(0–3) + HR(0–2) + 黑便(1) + 晕厥(2) + 肝病(2) + 心衰(2)；女性 Hb 阈值下调一档（≥120=0、100–119=1、<100=6）","compute":"sum","interpret":[{"when":"v >= 7","level":"crit","text":"≥ 7 分：高危，需紧急内镜（24 h 内，血流动力学不稳时复苏后尽快），输血与 ICU 评估，静脉曲张出血者用生长抑素类+抗生素"},{"when":"v >= 3","level":"high","text":"3–6 分：中危，住院观察，24 h 内胃镜（如有呕血/黑便持续则提前）"},{"when":"v == 0","level":"ok","text":"0 分：极低危，可门诊管理（需具备 24 h 复诊与随访条件）；1–2 分按低危个体化"}],"note":"GBS 对上消化道出血敏感性极高，是风险分层的首选；女性血红蛋白阈值需下调一档。评分 0–1 分可考虑门诊，但合并抗凝、老年或依从性差者应住院。","refs":["2021 中国急性非静脉曲张性上消化道出血诊治指南（中华医学会消化内镜学分会）","2016 急性上消化道出血急诊诊治流程专家共识（中国医师协会急诊医师分会）","Blatchford O, et al. A risk score to predict need for treatment for upper-gastrointestinal haemorrhage. Lancet 2000"]},{"id":"he_simple","name":"肝性脑病简易分级（ISHEN）","aka":["Simplified HE grading","ISHEN 分级"],"cat":"肝硬化","rank":6,"desc":"用定向力、扑翼样震颤与昏睡程度快速判级，替代 West-Haven 的简化工具。","inputs":[{"key":"orient","label":"定向力","type":"select","required":true,"options":[{"value":0,"label":"正常"},{"value":1,"label":"轻度减退"},{"value":2,"label":"明显减退"}]},{"key":"asterixis","label":"扑翼样震颤","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"可疑/轻度"},{"value":2,"label":"明显"}]},{"key":"somnolence","label":"嗜睡/意识水平","type":"select","required":true,"options":[{"value":0,"label":"清醒"},{"value":1,"label":"嗜睡可唤醒"},{"value":2,"label":"昏睡/难以唤醒"}]},{"key":"coma","label":"是否昏迷（对疼痛无反应）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":3,"label":"是（4 级）"}]}],"formula":"无昏迷时：总分 0 → 无 HE；1–2 分 → 1 级；3–4 分 → 2 级；≥ 5 分 → 3 级；昏迷 → 4 级","compute":"he_simple","algorithm":"if coma == 3: grade = 4\nelse:\n  s = orient + asterixis + somnolence\n  if s == 0 → 0 级\n  if s <= 2  → 1 级\n  if s <= 4  → 2 级\n  else       → 3 级\nv = grade","interpret":[{"when":"v >= 4","level":"crit","text":"4 级（昏迷）：ICU 监护，气道保护，乳果糖灌肠，排查脑水肿、颅内出血、低血糖与代谢性脑病"},{"when":"v == 3","level":"crit","text":"3 级：显著意识障碍，禁镇静药，乳果糖+利福昔明，纠正诱因（感染、消化道出血、低钾、电解质失衡、TIPS）"},{"when":"v == 2","level":"high","text":"2 级：显性 HE，住院，乳果糖口服/灌肠滴定至每日 2–3 次软便"},{"when":"v == 1","level":"warn","text":"1 级：早期显性 HE，识别并去除诱因，乳果糖起始治疗"},{"when":"v == 0","level":"ok","text":"无明显 HE；有 HE 既往史者维持二级预防"}],"note":"适用于意识清醒可配合的患者；昏迷、镇静或谵妄患者判读需慎重。合并肝肾综合征、低钠与感染可放大神经系统表现。","refs":["2018 肝硬化肝性脑病诊疗指南（中华医学会消化病学分会）","中国肝性脑病诊治共识（2022）"]},{"id":"saag","name":"腹水 SAAG（血清-腹水白蛋白梯度）","aka":["SAAG","Serum-Ascites Albumin Gradient"],"cat":"肝硬化","rank":7,"desc":"区分门静脉高压性腹水与非门脉高压性腹水，是所有腹水首次就诊的必查指标。","inputs":[{"key":"salb","label":"血清白蛋白","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":true},{"key":"aalb","label":"腹水白蛋白","unit":"g/L","type":"number","min":0,"max":50,"step":0.1,"required":true},{"key":"aprot","label":"腹水总蛋白","unit":"g/L","type":"number","min":0,"max":80,"step":0.1,"required":false},{"key":"pmn","label":"腹水多形核细胞计数","unit":"/μL","type":"number","min":0,"max":100000,"step":10,"required":false}],"formula":"SAAG = 血清白蛋白 − 腹水白蛋白（g/L）；≥ 11 g/L 提示门静脉高压性","compute":"saag","algorithm":"v = salb - aalb   # g/L\nif pmn >= 250 → 合并 SBP 提示（interpret 优先匹配）\nSAAG >= 11 → 门脉高压性；< 11 → 非门脉高压性","interpret":[{"when":"pmn >= 250","level":"crit","text":"腹水 PMN ≥ 250/μL：诊断自发性腹膜炎（SBP），立即经验性抗感染（第三代头孢类，遵指南与说明书）并白蛋白支持，详见 SBP 诊疗流程"},{"when":"v >= 11","level":"warn","text":"SAAG ≥ 11 g/L：门静脉高压性腹水（肝硬化、心源性、Budd-Chiari）；结合腹水总蛋白区分：< 25 g/L 多为肝硬化，≥ 25 g/L 提示心源性或 Budd-Chiari"},{"when":"v >= 0","level":"ok","text":"SAAG < 11 g/L：非门脉高压性腹水（腹膜癌病、结核性腹膜炎、胰源性），查腹水细胞学、ADA、LDH 与影像"}],"note":"血清与腹水标本应同日采集（同一次采血/穿刺）；近期输注白蛋白或利尿剂强化会干扰判读。腹水诊断性穿刺建议首次均做细胞计数与培养。","refs":["2019 中国肝硬化诊治指南（腹水管理部分）","2012 AASLD 肝硬化腹水指南（SAAG 界定门脉高压性腹水）","2021 中国肝硬化门静脉高压症多学科诊治共识"]},{"id":"maddrey","name":"Maddrey 判别函数（重症酒精性肝炎）","aka":["Maddrey Discriminant Function","mDF"],"cat":"肝硬化","rank":8,"desc":"判断酒精性肝炎严重度，mDF ≥ 32 提示重症，可考虑糖皮质激素。","inputs":[{"key":"pt_patient","label":"凝血酶原时间 PT（患者）","unit":"s","type":"number","min":8,"max":120,"step":0.1,"required":true},{"key":"pt_control","label":"凝血酶原时间（对照）","unit":"s","type":"number","min":8,"max":30,"step":0.1,"required":true,"hint":"通常 11–13 s"},{"key":"bili","label":"总胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true,"hint":"μmol/L ÷ 17.1"}],"formula":"mDF = 4.6 × (PT患者 − PT对照) + 总胆红素(mg/dL)","compute":"maddrey","algorithm":"v = 4.6 * (pt_patient - pt_control) + bili   # bili 单位 mg/dL","interpret":[{"when":"v >= 32","level":"crit","text":"mDF ≥ 32：重症酒精性肝炎，28 天死亡率高；无禁忌可考虑泼尼松龙 40 mg/d × 28 d（或 4 周），第 7 天复评 Lille 评分决定是否停药"},{"when":"v >= 20","level":"high","text":"mDF 20–31：中重度，戒酒、营养支持、密切监测感染与肾功能"},{"when":"v >= 0","level":"ok","text":"mDF < 20：轻中度，以戒酒与营养支持为主"}],"note":"激素使用前须排除活动性感染、消化道出血与肾功能不全；感染是激素抵抗与死亡的主因。Lille ≥ 0.45 提示无效，应停激素。","refs":["2018 酒精性肝病防治指南（中华医学会肝病学分会）","AASLD 2019 Alcoholic Liver Disease Practice Guidance","EASL 2018 Clinical Practice Guidelines on alcohol-related liver disease"]},{"id":"albi","name":"ALBI 评分（白蛋白-胆红素）","aka":["ALBI grade","Albumin-Bilirubin"],"cat":"肝硬化","rank":9,"desc":"基于白蛋白与胆红素的肝功能评估，用于 HCC 治疗决策与预后分层。","inputs":[{"key":"alb","label":"白蛋白","unit":"g/L","type":"number","min":15,"max":60,"step":1,"required":true},{"key":"bili","label":"总胆红素","unit":"μmol/L","type":"number","min":1,"max":800,"step":1,"required":true}],"formula":"ALBI = log10(胆红素 μmol/L) × 0.66 + 白蛋白(g/L) × (−0.0852)；分级：≤ −2.60 为 1 级、> −2.60 且 ≤ −1.39 为 2 级、> −1.39 为 3 级","compute":"albi","algorithm":"v = log10(bili) * 0.66 - 0.0852 * alb   # alb 用 g/L\n注意：常用算式中 alb 以 g/L 代入，系数 -0.0852；若以 g/dL 代入系数为 -0.852","interpret":[{"when":"v > -1.39","level":"crit","text":"ALBI 3 级：肝功能差（近似 Child-Pugh C 范围），系统治疗/介入耐受性差，优先支持治疗与姑息方案"},{"when":"v > -2.6","level":"warn","text":"ALBI 2 级：中度受损，HCC 局部治疗（消融/TACE）可行，系统治疗需评估肝功能储备"},{"when":"v >= -30","level":"ok","text":"ALBI 1 级：肝功能良好，可考虑根治性治疗（切除、移植、消融）"}],"note":"ALBI 不含腹水/脑病等主观项，可动态监测；对 HCC 系统治疗（靶向/免疫）耐受性判断优于 Child-Pugh。肝移植资格仍以 MELD 为基础。","refs":["2022 中国原发性肝癌诊疗指南（肝功能评估部分）","Johnson PJ, et al. Assessment of liver function in patients with hepatocellular carcinoma: a new evidence-based approach—the ALBI grade. J Clin Oncol 2015"]},{"id":"fib4","name":"FIB-4 肝纤维化指数","aka":["FIB-4","Fibrosis-4 index"],"cat":"肝脏纤维化","rank":10,"desc":"用年龄、AST、ALT、血小板筛查晚期肝纤维化（F3–F4），常用于脂肪肝与慢乙肝风险分层。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":100,"step":1,"required":true},{"key":"ast","label":"AST","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"alt","label":"ALT","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"plt","label":"血小板","unit":"×10^9/L","type":"number","min":1,"max":800,"step":1,"required":true}],"formula":"FIB-4 = 年龄(岁) × AST (U/L) ÷ (血小板 ×10^9/L × √ALT)","compute":"fib4","algorithm":"v = age * ast / (plt * sqrt(alt))","interpret":[{"when":"v >= 3.25","level":"crit","text":"FIB-4 ≥ 3.25：晚期纤维化（F3–F4）可能性高，转诊肝病专科，评估弹性成像与抗病毒/减重干预；肝硬化者进入 HCC 与静脉曲张监测"},{"when":"v >= 1.3","level":"warn","text":"FIB-4 1.30–3.24：灰区，需肝脏瞬时弹性成像（LSM）或血清标志物（ELF）进一步判断，每年复评"},{"when":"v >= 0","level":"ok","text":"FIB-4 < 1.30：晚期纤维化风险低，可 2–3 年复查；高危人群（代谢性肝病、持续转氨酶异常）仍应随访"}],"note":"NAFLD 建议用更低阈值 1.3（> 65 岁 2.0）；FIB-4 在活动性炎症（AST 显著升高）时高估、在血小板增多时低估。中国 NAFLD 共识把 FIB-4 作为一线无创筛查。","refs":["2018 非酒精性脂肪性肝病防治指南（中华医学会肝病学分会）","2022 中国慢性乙型肝炎防治指南（无创肝纤维化评估）","Sterling RK, et al. Development of a simple noninvasive index to predict significant fibrosis in patients with HIV/HCV. Hepatology 2006"]},{"id":"apri","name":"APRI 指数（AST/血小板比值）","aka":["APRI","AST to Platelet Ratio Index"],"cat":"肝脏纤维化","rank":11,"desc":"以 AST 与血小板估算肝纤维化与肝硬化，常用于资源有限场景替代肝活检。","inputs":[{"key":"ast","label":"AST","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"ast_uln","label":"AST 正常上限（通常 40 U/L）","unit":"U/L","type":"number","min":1,"max":80,"step":1,"required":true},{"key":"plt","label":"血小板","unit":"×10^9/L","type":"number","min":1,"max":800,"step":1,"required":true}],"formula":"APRI = (AST / AST 正常上限) / 血小板(×10^9/L) × 100","compute":"apri","algorithm":"v = (ast / ast_uln) / plt * 100","interpret":[{"when":"v >= 2.0","level":"crit","text":"APRI > 2.0：肝硬化可能性大（特异性高），启动肝硬化并发症筛查：胃镜查静脉曲张、超声+AFP 每 6 个月筛查 HCC"},{"when":"v >= 1.0","level":"warn","text":"APRI 1.0–2.0：显著纤维化/早期肝硬化可能，需弹性成像或活检确认"},{"when":"v >= 0","level":"ok","text":"APRI < 1.0：肝硬化可能性低，按病因随访"}],"note":"APRI 对 AST 水平高度依赖，急性肝炎期偏高；ALT 显著升高而 AST 正常时易遗漏。不能替代弹性成像与临床综合判断。","refs":["2019 中国肝硬化诊治指南（无创标志物）","Wai CT, et al. A simple noninvasive index can predict both significant fibrosis and cirrhosis in patients with chronic hepatitis C. Hepatology 2003"]},{"id":"ast_alt_ratio","name":"AST/ALT 比值（De Ritis 比值）","aka":["AST/ALT ratio","De Ritis ratio"],"cat":"肝脏生化","rank":12,"desc":"区分酒精性与非酒精性肝病、提示进展性纤维化。","inputs":[{"key":"ast","label":"AST","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"alt","label":"ALT","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"ggt","label":"GGT","unit":"U/L","type":"number","min":1,"max":3000,"step":1,"required":false}],"formula":"AST/ALT 比值 = AST ÷ ALT","compute":"ast_alt_ratio","algorithm":"v = ast / max(alt, 1)","interpret":[{"when":"v >= 1.5","level":"warn","text":"≥ 1.5：高度提示酒精性肝损伤（伴 GGT 升高更支持）；肝硬化与 Wilson 病也可见 AST≫ALT，需查酒精史、GGT 与铜代谢"},{"when":"v >= 1","level":"warn","text":"1.0–1.5：可为酒精性、晚期纤维化或非酒精性脂肪肝进展"},{"when":"v >= 0","level":"ok","text":"< 1：多见于病毒性肝炎、非酒精性脂肪肝、药物性肝损伤（ALT 优势）"}],"note":"饮酒后 AST/ALT > 2 更典型；ALT 正常而 AST 升高需排除心肌、骨骼肌来源（查 CK）。","refs":["2018 酒精性肝病防治指南（中华医学会肝病学分会）","《内科学》（第 9 版）肝脏生化指标判读"]},{"id":"nfs_nafld","name":"非酒精性脂肪肝纤维化评分 NFS","aka":["NAFLD Fibrosis Score","NFS"],"cat":"肝脏纤维化","rank":13,"desc":"综合年龄、BMI、血糖、血小板、白蛋白与 AST/ALT 评估 NAFLD 纤维化程度。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":100,"step":1,"required":true},{"key":"bmi","label":"BMI","unit":"kg/m²","type":"number","min":10,"max":60,"step":0.1,"required":true},{"key":"ifg","label":"空腹血糖受损/糖尿病（FPG ≥ 5.6 mmol/L 或已诊断）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"ast","label":"AST","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"alt","label":"ALT","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"plt","label":"血小板","unit":"×10^9/L","type":"number","min":1,"max":800,"step":1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/dL","type":"number","min":1,"max":6,"step":0.1,"required":true,"hint":"g/L ÷ 10"}],"formula":"NFS = −1.675 + 0.037×年龄 + 0.094×BMI + 1.13×IFG/糖尿病 + 0.99×AST/ALT − 0.013×血小板 − 0.66×白蛋白(g/dL)","compute":"nfs_nafld","algorithm":"v = -1.675 + 0.037*age + 0.094*bmi + 1.13*ifg + 0.99*(ast/alt) - 0.013*plt - 0.66*alb   # alb 单位 g/dL","interpret":[{"when":"v > 0.676","level":"crit","text":"NFS > 0.676：F3–F4 纤维化可能（阳性预测值高），转诊肝病专科，评估弹性成像/活检，启动减重与代谢干预"},{"when":"v > -1.455","level":"warn","text":"NFS −1.455 至 0.676：不确定区，需肝脏弹性成像（LSM）或 ELF 进一步分层，每年复查"},{"when":"v >= -30","level":"ok","text":"NFS < −1.455：F3–F4 可能性低，强化减重 5–10%、控制血脂血糖，2–3 年复查"}],"note":"NFS 已逐渐被 FIB-4 取代（FIB-4 更简便），但两者常互补；BMI 与血糖需避免药物性肥胖的干扰解释。2023 中国 NAFLD 共识更名 MASLD 后仍沿用无创评分。","refs":["2018 非酒精性脂肪性肝病防治指南（中华医学会肝病学分会）","Angulo P, et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis. Hepatology 2007","2023 代谢相关脂肪性肝病（MAFLD/MASLD）诊疗中国专家共识"]},{"id":"dili_r","name":"DILI 分型 R 值","aka":["R value","Roussel Uclaf Causality 相关分型"],"cat":"肝脏生化","rank":14,"desc":"根据 ALT 与 ALP 相对正常上限的倍数判断药物性肝损伤为肝细胞型、混合型或胆汁淤积型。","inputs":[{"key":"alt","label":"ALT","unit":"U/L","type":"number","min":1,"max":10000,"step":1,"required":true},{"key":"alt_uln","label":"ALT 正常上限","unit":"U/L","type":"number","min":1,"max":80,"step":1,"required":true,"hint":"常用 40 U/L"},{"key":"alp","label":"ALP","unit":"U/L","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"alp_uln","label":"ALP 正常上限","unit":"U/L","type":"number","min":1,"max":400,"step":1,"required":true,"hint":"常用 120 U/L（按本院参考值）"}],"formula":"R = (ALT/ULN_ALT) ÷ (ALP/ULN_ALP)：R ≥ 5 肝细胞型；2 < R < 5 混合型；R ≤ 2 胆汁淤积型","compute":"dili_r","algorithm":"alt_ratio = alt / alt_uln\nalp_ratio = max(alp / alp_uln, 0.1)\nR = alt_ratio / alp_ratio\nif R >= 5 → '肝细胞型'\nelse if R > 2 → '混合型'\nelse → '胆汁淤积型'\nv = R","interpret":[{"when":"v >= 5","level":"crit","text":"R ≥ 5：肝细胞型 DILI，停药为第一处置；ALT > 5×ULN 或伴胆红素 > 2×ULN（Hy's law 倾向）需住院监测，必要时按指南使用 N-乙酰半胱氨酸/糖皮质激素（遵指南与说明书）"},{"when":"v > 2","level":"warn","text":"2 < R < 5：混合型 DILI，停用可疑药物，每日监测 ALT、ALP、胆红素直至下降"},{"when":"v >= 0","level":"ok","text":"R ≤ 2：胆汁淤积型 DILI，注意 ALP 与胆红素同步升高（胆管消失综合征风险），查影像排除胆道梗阻"}],"note":"R 值应在发病初/服药期间计算（ALT 与 ALP 峰值）；转氨酶已下降时计算会低估。中国 DILI 指南推荐结合 RUCAM 因果评分与分型（肝细胞损伤型）。Hy's law：ALT ≥ 3×ULN 且 TBIL ≥ 2×ULN 且无胆道梗阻。","refs":["2015 药物性肝损伤诊治指南（中华医学会肝病学分会）；2023 年更新版","2020 中国药物性肝损伤诊治指南（RUCAM 评分与 R 值分型）","EASL 2019 Clinical Practice Guidelines: Drug-induced liver injury"]},{"id":"bisap","name":"BISAP 评分（急性胰腺炎）","aka":["BISAP","Bedside Index for Severity in Acute Pancreatitis"],"cat":"急性胰腺炎","rank":15,"desc":"入院 24 h 内 5 项床旁指标预测急性胰腺炎重症与死亡风险。","inputs":[{"key":"bun","label":"BUN > 8.9 mmol/L（25 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"gcs","label":"意识障碍（GCS < 15）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"sirs","label":"SIRS（≥ 2 项生命体征异常）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age","label":"年龄 > 60 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"effusion","label":"胸腔积液（影像学）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]}],"formula":"BISAP = BUN + 意识障碍 + SIRS + 年龄 + 胸腔积液（各 1 分，0–5）","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"≥ 3 分：重症风险显著升高（死亡率明显高于 2 分以下），转 ICU/重症监护，早期液体复苏与器官支持"},{"when":"v == 2","level":"warn","text":"2 分：中危，住院监测 48–72 h，动态评估 BUN、Hct 与器官功能"},{"when":"v <= 1","level":"ok","text":"0–1 分：轻症为主，早期肠内营养、充分镇痛与液体治疗"}],"note":"BISAP 简化床旁使用，优于 Ranson 的 48 h 等待；未含血钙与 CRP。SIRS 标准：T > 38 ℃ 或 < 36 ℃、HR > 90、RR > 20 或 PaCO2 < 32、WBC > 12 或 < 4 或幼稚粒细胞 > 10%。","refs":["2019 中国急性胰腺炎诊治指南（中华医学会消化病学分会）；2021 年修订版","Wu BU, et al. The early prediction of mortality in acute pancreatitis: a large population-based study (BISAP). Gut 2008"]},{"id":"ranson","name":"Ranson 评分（急性胰腺炎）","aka":["Ranson criteria"],"cat":"急性胰腺炎","rank":16,"desc":"入院时与 48 h 两组指标累计计分，预测重症与死亡，经典但需 48 h 才能完成。","inputs":[{"key":"age","label":"年龄 > 55 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"wbc","label":"WBC > 16 ×10^9/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"glu","label":"血糖 > 11.1 mmol/L（200 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"ldh","label":"LDH > 350 U/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"ast","label":"AST > 250 U/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"hct48","label":"48 h 内 Hct 下降 > 10%","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"bun48","label":"48 h BUN 升高 > 1.8 mmol/L（5 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"ca48","label":"48 h 血钙 < 2.0 mmol/L（8 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"pao2_48","label":"48 h PaO2 < 60 mmHg","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"base48","label":"48 h BE < −4 mmol/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"seq48","label":"48 h 液体丢失 > 6 L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"Ranson 总分 = 入院 5 项 + 48 h 6 项（各 1 分，0–11）","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"≥ 5 分：重症（死亡率约 20–40%），ICU 评估与多器官支持，早期影像学评估坏死"},{"when":"v >= 3","level":"high","text":"3–4 分：中度-重度，住院监测，48–72 h 内复查 CT 评估坏死"},{"when":"v >= 0","level":"ok","text":"0–2 分：轻症（死亡率 < 1%），早期肠内营养与补液"}],"note":"胆源性胰腺炎另有 Gallstone 版 Ranson（用血糖、LDH、AST、WBC、年龄不同阈值）。Ranson 需 48 h 完成判断，不应作为唯一分级工具（结合 BISAP 与修订版 Atlanta）。","refs":["2019 中国急性胰腺炎诊治指南（中华医学会消化病学分会）","2012 修订版 Atlanta 急性胰腺炎分类（国际共识）","Ranson JH, et al. Prognostic signs and the role of operative management in acute pancreatitis. Surg Gynecol Obstet 1974"]},{"id":"haps","name":"HAPS 高脂血症性急性胰腺炎严重度评分","aka":["HAPS","Hypertriglyceridemic Acute Pancreatitis Score"],"cat":"急性胰腺炎","rank":17,"desc":"专门针对高甘油三酯性胰腺炎的严重度评分，含低钙与 TG 水平。","inputs":[{"key":"tg","label":"甘油三酯","type":"select","required":true,"options":[{"value":0,"label":"≤ 11.3 mmol/L（1000 mg/dL）"},{"value":1,"label":"11.3–22.6 mmol/L"},{"value":2,"label":"> 22.6 mmol/L"}]},{"key":"ca","label":"血钙","type":"select","required":true,"options":[{"value":0,"label":"≥ 2.0 mmol/L"},{"value":1,"label":"1.75–2.0 mmol/L"},{"value":2,"label":"< 1.75 mmol/L"}]},{"key":"sirs","label":"SIRS","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"age","label":"年龄 > 60 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"crp","label":"CRP > 150 mg/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"HAPS = TG(0–2) + 血钙(0–2) + SIRS(0–1) + 年龄>60(0–1) + CRP>150(0–1)；≥ 3 分提示可能重症","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"≥ 5 分：重症风险高，需 ICU 评估、血浆置换/血液净化降 TG（按指南适应证）与器官支持"},{"when":"v >= 3","level":"high","text":"3–4 分：可能重症，住院密切监测，血脂净化与降脂治疗（贝特类/他汀按说明书）"},{"when":"v >= 0","level":"ok","text":"0–2 分：轻症倾向，禁食期短、低脂饮食，降 TG 与控糖"}],"note":"国内学者提出的高甘油三酯性胰腺炎专用评分；TG 峰值应在入院早期或血脂清除前记录。低钙提示脂肪坏死皂化与重度病程。","refs":["2021 中国急性胰腺炎诊治指南（高甘油三酯血症性胰腺炎部分）","2021 高甘油三酯血症性胰腺炎诊治中国专家共识"]},{"id":"ctsi","name":"CT 严重指数 CTSI / 改良 CTSI","aka":["CTSI","Balthazar score","改良 CTSI"],"cat":"急性胰腺炎","rank":18,"desc":"按胰腺坏死范围与炎症扩散计算，评估急性胰腺炎严重度与坏死风险。","inputs":[{"key":"necrosis","label":"胰腺坏死范围","type":"select","required":true,"options":[{"value":0,"label":"无坏死"},{"value":2,"label":"≤ 30%"},{"value":4,"label":"30–50%"},{"value":6,"label":"> 50%"}]},{"key":"inflammation","label":"炎症范围（改良 CTSI）","type":"select","required":true,"options":[{"value":0,"label":"正常胰腺"},{"value":2,"label":"胰腺及周围脂肪炎症"},{"value":4,"label":"炎症累及小网膜囊/肾前间隙"},{"value":6,"label":"炎症累及腹膜后其他区域"}]},{"key":"fluid","label":"胰周液体积聚","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"1 个区域"},{"value":2,"label":"≥ 2 个区域"}]}],"formula":"改良 CTSI（MCTSI，0–10）= 坏死（0/2/4/6）+ 炎症（0/2/4/6）+ 液体积聚（0/1/2）；经典 Balthazar CTSI = 分级（0–4）+ 坏死（0/2/4/6，0–10）","compute":"sum","interpret":[{"when":"v >= 8","level":"crit","text":"MCTSI ≥ 8：重度，坏死与感染风险高，评估 ICU、经皮穿刺引流与营养支持"},{"when":"v >= 4","level":"high","text":"MCTSI 4–7：中度，72 h 后复查增强 CT，监测胰腺假性囊肿/包裹性坏死"},{"when":"v >= 0","level":"ok","text":"MCTSI ≤ 3：轻症，以支持治疗为主"}],"note":"应在发病 72 h 后行增强 CT 评估坏死（早期易低估）；肾功能不全者避免碘对比剂。MRI 或超声可作为替代。","refs":["2019 中国急性胰腺炎诊治指南（影像学评估部分）","Balthazar EJ, et al. Acute pancreatitis: value of CT in establishing prognosis. Radiology 1990","Mortele KJ, et al. A modified CT severity index for evaluating acute pancreatitis. AJR 2004"]},{"id":"rockall","name":"Rockall 评分（上消化道出血再出血与死亡）","aka":["Rockall Score","完整 Rockall 评分"],"cat":"消化道出血","rank":19,"desc":"结合年龄、休克、合并症与内镜所见，预测再出血率与死亡率。","inputs":[{"key":"age","label":"年龄","type":"select","required":true,"options":[{"value":0,"label":"< 60 岁"},{"value":1,"label":"60–79 岁"},{"value":2,"label":"≥ 80 岁"}]},{"key":"shock","label":"休克表现","type":"select","required":true,"options":[{"value":0,"label":"无休克（SBP ≥ 100、HR < 100）"},{"value":1,"label":"心动过速（HR ≥ 100，SBP ≥ 100）"},{"value":2,"label":"低血压（SBP < 100）"}]},{"key":"comorb","label":"合并症","type":"select","required":true,"options":[{"value":0,"label":"无重要合并症"},{"value":2,"label":"心衰、缺血性心脏病、其他重要疾病"},{"value":3,"label":"肾衰、肝衰、肿瘤播散"}]},{"key":"stigma","label":"内镜所见（出血征象）","type":"select","required":true,"options":[{"value":0,"label":"无活动性出血（Mallory-Weiss 或黑斑）"},{"value":1,"label":"溃疡渗血，无血管显露"},{"value":2,"label":"上消化道恶性肿瘤或血管暴露/附着血凝块"},{"value":3,"label":"活动性出血（Forrest Ia/Ib）"}]},{"key":"dx","label":"内镜诊断","type":"select","required":true,"options":[{"value":0,"label":"Mallory-Weiss 或正常"},{"value":1,"label":"消化性溃疡、糜烂性病变"},{"value":2,"label":"上消化道恶性肿瘤"}]}],"formula":"完整 Rockall = 临床 3 项（年龄 0–2、休克 0–2、合并症 0–3）+ 内镜 2 项（征象 0–3、诊断 0–2）；总分 0–11；仅临床部分（0–7）用于内镜前","compute":"sum","interpret":[{"when":"v >= 8","level":"crit","text":"≥ 8 分：再出血与死亡风险极高（死亡率 > 40%），ICU 与多学科评估，必要时手术或介入（血管造影栓塞）"},{"when":"v >= 5","level":"high","text":"5–7 分：高风险（死亡率约 10–20%），重症监护/密切观察，内镜治疗后再出血风险高"},{"when":"v >= 3","level":"warn","text":"3–4 分：中危，住院治疗，内镜治疗后监测 24–72 h"},{"when":"v <= 2","level":"ok","text":"0–2 分：低危（死亡率 < 5%），可门诊或短期住院"}],"note":"完整 Rockall 需内镜结果，常用于内镜后风险判断；内镜前决策多用 GBS 或 Blatchford。中国指南推荐对所有非静脉曲张性上消化道出血使用 GB 评分 + Rockall 联合。","refs":["2021 中国急性非静脉曲张性上消化道出血诊治指南","Rockall TA, et al. Risk assessment after acute upper gastrointestinal haemorrhage. Gut 1996"]},{"id":"aims65","name":"AIMS65 评分（上消化道出血）","aka":["AIMS65"],"cat":"消化道出血","rank":20,"desc":"5 项简单指标预测上消化道出血院内死亡与住院时间。","inputs":[{"key":"alb","label":"白蛋白 < 30 g/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"inr","label":"INR > 1.5","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"gcs","label":"意识改变（GCS < 14）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"sbp","label":"收缩压 < 90 mmHg","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age","label":"年龄 > 65 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"AIMS65 = 白蛋白<30 + INR>1.5 + 意识改变 + SBP<90 + 年龄>65（各 1 分，0–5）","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"≥ 3 分：院内死亡风险显著升高，转 ICU，紧急内镜与输血策略"},{"when":"v == 2","level":"high","text":"2 分：高风险，住院并 24 h 内内镜，监测再出血"},{"when":"v >= 0","level":"ok","text":"0–1 分：低风险，可择期内镜；但仍需评估是否需要输血与住院"}],"note":"AIMS65 与 GBS 互补：GBS 判断是否需要干预，AIMS65 预测死亡率但灵敏度低，不建议单独用于排除高危。","refs":["2021 中国急性非静脉曲张性上消化道出血诊治指南","Saltzman JR, et al. A simple risk score accurately predicts in-hospital mortality, length of stay, and cost in acute upper GI bleeding. Gastrointest Endosc 2011"]},{"id":"forrest","name":"Forrest 分级（溃疡出血内镜征象）","aka":["Forrest classification"],"cat":"消化道出血","rank":21,"desc":"按内镜下出血征象分级，决定内镜治疗与再出血风险。","inputs":[{"key":"cls","label":"内镜分级","type":"select","required":true,"options":[{"value":1,"label":"Ⅰa 喷射性出血"},{"value":2,"label":"Ⅰb 渗血"},{"value":3,"label":"Ⅱa 显露血管（无出血）"},{"value":4,"label":"Ⅱb 附着血凝块"},{"value":5,"label":"Ⅱc 黑斑/黑色基底"},{"value":6,"label":"Ⅲ 清洁基底"}]}],"formula":"Forrest Ⅰa/Ⅰb（活动性出血）、Ⅱa/Ⅱb/Ⅱc（近期出血征象）、Ⅲ（无出血征象）","compute":"formula_only","algorithm":"直接按 cls 取分级；v = cls（1-6）\nⅠa=1、Ⅰb=2、Ⅱa=3、Ⅱb=4、Ⅱc=5、Ⅲ=6","interpret":[{"when":"cls <= 2","level":"crit","text":"Ⅰa/Ⅰb 活动性出血：必须内镜下止血（注射+热凝固/止血夹），再出血约 55%，止血后高剂量 PPI 静脉给药（遵说明书），必要时介入栓塞"},{"when":"cls == 3","level":"high","text":"Ⅱa 显露血管：高再出血风险（约 43%），需内镜止血并高剂量 PPI"},{"when":"cls == 4","level":"warn","text":"Ⅱb 附着血凝块：冲刷后依所见处理（如可见血管则止血），高剂量 PPI 静脉给药"},{"when":"cls == 5","level":"ok","text":"Ⅱc 黑斑：再出血率低（约 7%），口服 PPI 即可，不需内镜止血"},{"when":"cls == 6","level":"ok","text":"Ⅲ 清洁基底：再出血率低（约 5%），口服 PPI 与根除幽门螺杆菌"}],"note":"内镜止血后应静脉大剂量 PPI；溃疡出血患者应根除幽门螺杆菌（停用抗凝/抗血小板需多学科权衡）。静脉曲张出血不用 Forrest 分级，应用 LDRf 分型。","refs":["2021 中国急性非静脉曲张性上消化道出血诊治指南","2015 消化性溃疡病诊断与治疗规范（中华医学会消化病学分会）"]},{"id":"mayo_uc","name":"Mayo 评分（溃疡性结肠炎活动度）","aka":["Mayo Score","UC 活动指数"],"cat":"炎症性肠病","rank":22,"desc":"4 项（排便次数、便血、内镜、医师总体评价）评估 UC 活动度，用于临床试验与疗效判断。","inputs":[{"key":"stool","label":"排便次数（较正常增加）","type":"select","required":true,"options":[{"value":0,"label":"正常"},{"value":1,"label":"增加 1–2 次/日"},{"value":2,"label":"增加 3–4 次/日"},{"value":3,"label":"增加 ≥ 5 次/日"}]},{"key":"bleed","label":"便血","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"少量（< 50% 排便带血）"},{"value":2,"label":"明显"},{"value":3,"label":"大量（几乎全部为血）"}]},{"key":"endo","label":"内镜所见","type":"select","required":true,"options":[{"value":0,"label":"正常"},{"value":1,"label":"轻度（红斑、血管纹理减少、轻度易脆）"},{"value":2,"label":"中度（明显红斑、血管纹理消失、糜烂）"},{"value":3,"label":"重度（自发性出血、溃疡）"}]},{"key":"global","label":"医师总体评价","type":"select","required":true,"options":[{"value":0,"label":"正常"},{"value":1,"label":"轻度"},{"value":2,"label":"中度"},{"value":3,"label":"重度"}]}],"formula":"Mayo = 排便次数(0–3) + 便血(0–3) + 内镜(0–3) + 医师评价(0–3)，总分 0–12；未行内镜时用部分 Mayo（0–9）","compute":"sum","interpret":[{"when":"v >= 11","level":"crit","text":"Mayo 11–12：重度活动，住院评估，静脉糖皮质激素（遵说明书），无效 3–5 天评估挽救治疗（英夫利西单抗/环孢素）或手术"},{"when":"v >= 7","level":"high","text":"Mayo 7–10：中重度活动，优化 5-ASA 剂量或生物制剂/小分子药物，评估合并感染与结肠镜检查"},{"when":"v >= 3","level":"warn","text":"Mayo 3–6：轻度活动，按 5-ASA 诱导与维持，复查粪钙卫蛋白"},{"when":"v < 3","level":"ok","text":"Mayo ≤ 2：临床缓解，维持治疗与定期监测"}],"note":"Mayo 内镜项通常按直肠乙状结肠镜评分，全结肠镜更准确。部分 Mayo 不含内镜，适用于门诊快速评估。持续活动者警惕巨结肠与中毒性结肠炎。","refs":["2018 炎症性肠病诊断与治疗的共识意见（中华医学会消化病学分会炎症性肠病学组）","2023 中国炎症性肠病诊治指南（UC 部分）","Schroeder KW, et al. Coated oral 5-ASA therapy for mildly to moderately active ulcerative colitis. NEJM 1987"]},{"id":"cdai","name":"CDAI 克罗恩病活动指数","aka":["Crohn's Disease Activity Index","CDAI"],"cat":"炎症性肠病","rank":23,"desc":"经典 CD 活动指数（基于 7 天日记的 8 项变量），用于临床试验与活动度判定。","inputs":[{"key":"stool","label":"7 天稀便/水样便次数总和","unit":"次","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"pain","label":"7 天腹痛评分总和（0 无–3 重，每日 1 项）","unit":"分","type":"number","min":0,"max":21,"step":1,"required":true},{"key":"well","label":"7 天总体健康评分总和（0 好–4 差）","unit":"分","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"extra","label":"并发症项数（关节/皮肤/眼/肛周/其他）","type":"select","required":true,"options":[{"value":0,"label":"0 项"},{"value":1,"label":"1 项"},{"value":2,"label":"2 项"},{"value":3,"label":"3 项"},{"value":4,"label":"4 项"},{"value":5,"label":"5 项"},{"value":6,"label":"6 项"}]},{"key":"antidiarr","label":"使用止泻药","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":30,"label":"是"}]},{"key":"mass","label":"腹部包块","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":10,"label":"可疑"},{"value":20,"label":"明确"}]},{"key":"hct","label":"红细胞压积","type":"select","required":true,"options":[{"value":0,"label":"男 ≥ 0.47 / 女 ≥ 0.42"},{"value":6,"label":"男 0.39–0.46 / 女 0.33–0.41"},{"value":12,"label":"男 < 0.39 / 女 < 0.33"}]},{"key":"bmiw","label":"体重","type":"select","required":true,"options":[{"value":0,"label":"标准体重 ≥ 1.0"},{"value":1,"label":"标准体重 0.9–0.99"},{"value":2,"label":"标准体重 0.8–0.89"},{"value":3,"label":"标准体重 0.7–0.79"},{"value":4,"label":"标准体重 < 0.7"}]}],"formula":"CDAI = 2×稀便次数 + 5×腹痛总分 + 7×总体健康总分 + 20×并发症项数 + 30×止泻药 + 10×腹部包块 + 6×Hct 分 + 1×体重分","compute":"cdai","algorithm":"v = 2*stool + 5*pain + 7*well + 20*extra + antidiarr + mass + hct + bmiw","interpret":[{"when":"v >= 450","level":"crit","text":"CDAI > 450：重度活动，住院治疗，评估生物制剂与营养支持，警惕穿孔、狭窄与脓肿"},{"when":"v >= 220","level":"high","text":"CDAI 220–450：中度活动，启动激素或生物制剂诱导（按 CD 指南），复查炎症指标与影像"},{"when":"v >= 150","level":"warn","text":"CDAI 150–219：轻度活动，优化 5-ASA/免疫抑制剂，监测粪钙卫蛋白与 CRP"},{"when":"v >= 0","level":"ok","text":"CDAI < 150：临床缓解；缓解 100 分下降为「临床缓解」。勿单独依赖 CDAI 评估黏膜愈合"}],"note":"CDAI 采集繁琐（7 天日记），临床常用 Harvey-Bradshaw 替代；黏膜愈合需结合内镜（SES-CD）。CDAI 对肛周病变与狭窄型评价不足。","refs":["2018 炎症性肠病诊断与治疗的共识意见（中华医学会消化病学分会）","Best WR, et al. Development of a Crohn's disease activity index. Gastroenterology 1976"]},{"id":"hbi","name":"Harvey-Bradshaw 指数（简化 CDAI）","aka":["Harvey-Bradshaw Index","HBI","简化 CDAI"],"cat":"炎症性肠病","rank":24,"desc":"5 项简易评分（不需 7 天日记），门诊快速评估 CD 活动度。","inputs":[{"key":"well","label":"总体健康（0 好–4 差）","type":"select","required":true,"options":[{"value":0,"label":"0 好"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4 差"}]},{"key":"pain","label":"腹痛","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"轻度"},{"value":2,"label":"中度"},{"value":3,"label":"重度"}]},{"key":"stool","label":"每日稀便次数（0–3 计分：≤1 次计 0）","type":"select","required":true,"options":[{"value":0,"label":"0–1 次"},{"value":1,"label":"2 次"},{"value":2,"label":"3 次"},{"value":3,"label":"≥ 4 次"}]},{"key":"mass","label":"腹部包块","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"可疑"},{"value":2,"label":"明确"},{"value":3,"label":"明确伴触痛"}]},{"key":"extra","label":"并发症（关节/皮肤/眼/肛周等，按项数）","type":"select","required":true,"options":[{"value":0,"label":"0 项"},{"value":1,"label":"1 项"},{"value":2,"label":"2 项"},{"value":3,"label":"≥ 3 项"}]}],"formula":"HBI = 总体健康(0–4) + 腹痛(0–3) + 稀便次数分(0–3) + 腹部包块(0–3) + 并发症(0–3)","compute":"sum","interpret":[{"when":"v >= 11","level":"crit","text":"HBI ≥ 11：重度活动，住院与生物制剂/激素诱导，排查并发症"},{"when":"v >= 8","level":"high","text":"HBI 8–10：中度活动，优化治疗并复查炎症指标"},{"when":"v >= 5","level":"warn","text":"HBI 5–7：轻度活动，按 CD 指南强化维持治疗"},{"when":"v < 5","level":"ok","text":"HBI ≤ 4：临床缓解，维持治疗"}],"note":"HBI ≥ 5 通常判定为活动期；与 CDAI 相关性良好但不完全一致，临床试验宜用 CDAI。","refs":["2018 炎症性肠病诊断与治疗的共识意见（中华医学会消化病学分会）","Harvey RF, Bradshaw JM. A simple index of Crohn's-disease activity. Lancet 1980"]},{"id":"truelove_witts","name":"Truelove-Witts 分度（UC 病情）","aka":["Truelove and Witts severity","UC 严重度分级"],"cat":"炎症性肠病","rank":25,"desc":"按血便、体温、脉搏、血红蛋白、ESR 判断 UC 轻/中/重度，决定是否住院与激素治疗。","inputs":[{"key":"blood","label":"血便（次/日）","type":"select","required":true,"options":[{"value":0,"label":"少量 < 4 次/日"},{"value":1,"label":"4 次以上/日"},{"value":2,"label":"≥ 6 次/日"}]},{"key":"temp","label":"体温","type":"select","required":true,"options":[{"value":0,"label":"< 37.5 ℃"},{"value":1,"label":"37.5–37.9 ℃"},{"value":2,"label":"≥ 37.8 ℃"}]},{"key":"hr","label":"脉搏","type":"select","required":true,"options":[{"value":0,"label":"< 90 次/分"},{"value":1,"label":"90–99 次/分"},{"value":2,"label":"≥ 90 次/分"}]},{"key":"hb","label":"血红蛋白","type":"select","required":true,"options":[{"value":0,"label":"正常或 > 105 g/L"},{"value":1,"label":"90–105 g/L（不及正常 75%）"},{"value":2,"label":"≤ 75 g/L（< 正常 75%）"}]},{"key":"esr","label":"ESR","type":"select","required":true,"options":[{"value":0,"label":"< 30 mm/h"},{"value":1,"label":"30–50 mm/h"},{"value":2,"label":"> 30 mm/h 且伴全身症状"}]}],"formula":"轻度：全部指标轻度；中度：介于轻重度之间；重度：血便 ≥ 6 次/日 + 体温 ≥ 37.8 ℃ + 心动过速 + Hb ≤ 75 g/L + ESR > 30 mm/h（6 项中 ≥ 4 项）","compute":"truelove_witts","algorithm":"severe_items = 血便>=2 计 1 + 体温>=2 计 1 + 脉搏>=2 计 1 + Hb>=2 计 1 + ESR>=2 计 1\nif severe_items >= 4 → 重度（v = severe_items）\nelse 依据各项分值：任一项为 1 → 中度（v = 2）；全部为 0 → 轻度（v = 0）","interpret":[{"when":"v >= 4","level":"crit","text":"重度：必须住院，静脉激素，排除巨结肠/感染（大便培养、艰难梭菌毒素），3–5 天无效评估挽救/手术"},{"when":"v >= 2","level":"warn","text":"中度：口服激素或 5-ASA 加量，1–2 周复评，复发频繁者考虑生物制剂"},{"when":"v >= 0","level":"ok","text":"轻度：5-ASA 口服/局部，避免 NSAIDs，评估是否需要局部灌肠"}],"note":"Truelove-Witts 采用临床与实验室指标，超急重症（暴发型）可伴发热、腹膨胀与中毒症状，需急诊评估；与 Mayo/CDAI 不能混用。","refs":["2018 炎症性肠病诊断与治疗的共识意见（中华医学会消化病学分会）","Truelove SC, Witts LJ. Cortisone in ulcerative colitis: final report on a therapeutic trial. BMJ 1955"]},{"id":"lille","name":"Lille 评分（酒精性肝炎激素反应）","aka":["Lille Score"],"cat":"肝硬化","rank":26,"desc":"在激素治疗第 7 天评估应答，决定是否继续糖皮质激素。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":100,"step":1,"required":true},{"key":"alb_d0","label":"第 0 天白蛋白","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":true},{"key":"alb_d7","label":"第 7 天白蛋白","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":true},{"key":"crea_d0","label":"第 0 天肌酐","unit":"mg/dL","type":"number","min":0.2,"max":12,"step":0.1,"required":true},{"key":"crea_d7","label":"第 7 天肌酐","unit":"mg/dL","type":"number","min":0.2,"max":12,"step":0.1,"required":true},{"key":"bili_d0","label":"第 0 天胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true},{"key":"bili_d7","label":"第 7 天胆红素","unit":"mg/dL","type":"number","min":0.1,"max":60,"step":0.1,"required":true},{"key":"pt_d0","label":"第 0 天 PT（秒）","unit":"s","type":"number","min":8,"max":120,"step":0.1,"required":true},{"key":"pt_d7","label":"第 7 天 PT（秒）","unit":"s","type":"number","min":8,"max":120,"step":0.1,"required":true}],"formula":"Lille = 3.19 − 0.101×年龄 + 0.147×白蛋白0d(g/L) + 0.0165×(白蛋白7d − 白蛋白0d) − 0.206×(肌酐0d 降至 < 1.3 或 7d 下降 ≥ 0 记 0，否则 1) 项 + 0.113×胆红素0d − 0.02×胆红素7d + 0.0065×PT0d − 0.0096×PT7d","compute":"formula_only","algorithm":"# 伪代码（需在实现时按官方公式逐项映射）\nv1 = 白蛋白0d; v2 = 白蛋白7d - 白蛋白0d\na = 1 if (肌酐7d < 1.3 或 肌酐7d < 肌酐0d) else 0\n注：Lille 官方公式为 3.19 − 0.101×年龄 + 0.147×白蛋白(0d) + 0.0165×(Δ白蛋白) − 0.206×R(肌酐应答) + 0.113×胆红素(0d) − 0.02×胆红素(7d) + 0.0065×PT(0d) − 0.0096×PT(7d)，R=0 表示肌酐下降/未升，R=1 表示肌酐升高\nL = 上述结果\n应答 = (L < 0.45)","interpret":[{"when":"v >= 0.56","level":"crit","text":"Lille ≥ 0.56：无应答，停用激素，评估早期肝移植（MELD 高者优先）与感染控制"},{"when":"v >= 0.45","level":"warn","text":"Lille 0.45–0.56：部分应答/临界，密切监测并考虑停激素"},{"when":"v >= 0","level":"ok","text":"Lille < 0.45：有应答，完成 28 天疗程并在出院后继续戒酒与营养支持"}],"note":"公式中胆红素、肌酐需用 mg/dL；PT 用秒。激素前须排除严重感染与消化道出血。Lille 不能用于未用激素者。","refs":["2018 酒精性肝病防治指南（中华医学会肝病学分会）","Louvet A, et al. The Lille model: a new tool for therapeutic strategy in patients with severe alcoholic hepatitis. Hepatology 2007","AASLD 2019 Alcoholic Liver Disease Practice Guidance"]},{"id":"hcc_up_to_seven","name":"HCC 肝移植 UP-to-7 标准","aka":["Up-to-seven criteria","up-to-7"],"cat":"肝硬化","rank":27,"desc":"以「肿瘤个数 + 最大直径」≤ 7 的改良移植标准，扩大肝移植适应证判断。","inputs":[{"key":"count","label":"肿瘤个数","unit":"个","type":"number","min":1,"max":20,"step":1,"required":true},{"key":"size","label":"最大肿瘤直径","unit":"cm","type":"number","min":0.5,"max":20,"step":0.1,"required":true},{"key":"afp","label":"AFP","unit":"ng/mL","type":"number","min":0,"max":100000,"step":1,"required":false}],"formula":"up-to-7 = 肿瘤个数 + 最大肿瘤直径(cm)；≤ 7 视为符合","compute":"hcc_up_to_seven","algorithm":"v = count + size   # 个数 + 最大直径(cm)","interpret":[{"when":"afp > 1000","level":"crit","text":"AFP > 1000 ng/mL：高复发风险，WHO/中国指南视其为移植相对禁忌，需强化桥接治疗与再次评估"},{"when":"v <= 7","level":"ok","text":"符合 up-to-7：较 Milan 标准扩展（可覆盖 e.g. 5 个 ≤2 cm 或 1 个 ≤6 cm），移植后 5 年生存与 Milan 相近，按中心规范评估"},{"when":"v > 7","level":"high","text":"超出 up-to-7：移植复发风险高，优先局部治疗（射频/栓塞）与降期后再评估"}],"note":"中国多数移植中心以 Milan 标准（单发 ≤5 cm 或多发 ≤3 个且最大 ≤3 cm）为基本标准，up-to-7 为扩展标准，需结合 mRECIST 评估与降期。","refs":["2019 中国肝硬化诊治指南（HCC 筛查与移植）","2022 中国原发性肝癌诊疗指南","Mazzaferro V, et al. Predicting survival after liver transplantation in patients with HCC beyond the Milan criteria. Lancet Oncol 2009"]},{"id":"hbv_clinical","name":"慢性乙型肝炎活动度与分期","aka":["CHB phase","慢乙肝免疫分期"],"cat":"病毒性肝炎","rank":28,"desc":"依据 HBeAg、HBV DNA、ALT 判断慢乙肝免疫分期，决定抗病毒治疗启动。","inputs":[{"key":"hbeag","label":"HBeAg","type":"select","required":true,"options":[{"value":1,"label":"阳性"},{"value":0,"label":"阴性"}]},{"key":"dna_log","label":"HBV DNA","unit":"log10 IU/mL","type":"number","min":0,"max":10,"step":0.1,"required":true,"hint":"未检出填 0；如 2×10^5 = 5.3"},{"key":"alt","label":"ALT","unit":"U/L","type":"number","min":1,"max":2000,"step":1,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"family_hcc","label":"肝硬化或肝癌家族史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]}],"formula":"免疫耐受期：HBeAg+、HBV DNA > 2×10^7 IU/mL、ALT 正常；免疫清除期：HBeAg+、DNA > 2×10^3、ALT 升高；非活动携带：HBeAg−、DNA < 2×10^3、ALT 正常；再活动期：HBeAg−、DNA > 2×10^3、ALT 升高","compute":"hbv_phase","algorithm":"if hbeag == 1 and dna_log > 7 and alt 正常 → 免疫耐受期\nelif hbeag == 1 and dna_log > 3 and alt 升高 → 免疫清除期\nelif hbeag == 0 and dna_log < 3 and alt 正常 → 非活动携带\nelse → 再活动期\nv = alt  # interpret 主要依据 dna_log / alt / age / 家族史","interpret":[{"when":"alt > 2 && dna_log > 4","level":"crit","text":"HBV DNA > 10^4 IU/mL 且 ALT 显著升高：符合治疗指征，启动核苷（酸）类似物（恩替卡韦/替诺福韦类）或干扰素（遵指南与说明书）"},{"when":"age > 30 && dna_log > 5","level":"warn","text":"年龄 > 30 岁且 HBV DNA 明显升高：按 2022 中国指南推荐启动抗病毒治疗（无需等 ALT 升高）"},{"when":"family_hcc == 1 && dna_log > 3","level":"warn","text":"有肝硬化/肝癌家族史且可测得 HBV DNA：属于扩大治疗指征，建议抗病毒并 6 个月超声+AFP 筛查"},{"when":"v >= 0","level":"ok","text":"需结合免疫分期判断；非活动携带者定期检测（HBV DNA、ALT、HBsAg/HBeAg、AFP、超声）"}],"note":"2022 中国指南对年龄 > 30 岁、家族史、肝硬化等高危人群扩大了治疗范围。ALT 正常但 DNA 高的育龄女性需按母婴阻断流程处理。HBV DNA 单位与 log 换算须结合检验方法。","refs":["2022 中国慢性乙型肝炎防治指南（中华医学会肝病学分会、感染病学分会）","2019 中国肝硬化诊治指南（HBV 相关肝硬化抗病毒）","EASL 2017 Clinical Practice Guidelines on HBV"]},{"id":"liver_vol_remnant","name":"肝切除术后残肝体积比（FLR%）","aka":["Future Liver Remnant","FLR","残肝体积"],"cat":"肝硬化","rank":29,"desc":"评估拟行肝切除术后残余肝体积占标准肝体积比例，判断肝功能衰竭风险。","inputs":[{"key":"flr_ml","label":"预计残肝体积","unit":"mL","type":"number","min":100,"max":3000,"step":1,"required":true},{"key":"slv_ml","label":"标准肝体积（按体表面积计算）","unit":"mL","type":"number","min":500,"max":3500,"step":1,"required":true},{"key":"cirrhosis","label":"肝硬化程度","type":"select","required":true,"options":[{"value":0,"label":"无肝硬化/轻度纤维化"},{"value":1,"label":"Child-Pugh A 肝硬化"}]}],"formula":"FLR% = 残肝体积 ÷ 标准肝体积 × 100；一般要求 ≥ 20–25%（健康肝），肝硬化 ≥ 30–40%","compute":"liver_vol_remnant","algorithm":"v = flr_ml / slv_ml * 100","interpret":[{"when":"cirrhosis == 0 && v >= 25","level":"ok","text":"健康肝 FLR ≥ 25%：可耐受大范围肝切除，术后肝功能衰竭风险低"},{"when":"cirrhosis == 1 && v >= 40","level":"ok","text":"Child-Pugh A 肝硬化 FLR ≥ 40%：相对安全，围术期加强营养与感染预防"},{"when":"cirrhosis == 1","level":"crit","text":"肝硬化 FLR < 40%：术后肝功能衰竭风险高，不建议直接切除；考虑门静脉栓塞（PVE）或 ALPPS 二步法"},{"when":"v >= 20","level":"warn","text":"健康肝 FLR 20–24%：处于临界，建议 PVE 促肝增生或缩小切除范围"},{"when":"v >= 0","level":"crit","text":"FLR < 20%：肝切除术后肝衰竭风险很高，需前期门静脉栓塞/二期切除"}],"note":"标准肝体积常用 Urata 公式（按体表面积）；CT 体积测量与功能评估（ICG 15 分钟滞留率）结合。PVE 后需复测体积（通常 4–6 周）。","refs":["2022 中国原发性肝癌诊疗指南（手术切除评估）","门静脉栓塞与 ALPPS 二步肝切除中国专家共识（2019）","Urata K, et al. Calculation of child and adult standard liver volume for liver transplantation. Hepatology 1995"]},{"id":"pc_s_lead","name":"门静脉-胆道分离分级（PS 分级，Bismuth 改良）","aka":["Bismuth-Corlette","肝门部胆管癌分型"],"cat":"胆道疾病","rank":30,"desc":"按肿瘤累及胆管范围分型（Ⅰ–Ⅳ 型），指导手术方式与可切除性评估。","inputs":[{"key":"type","label":"Bismuth-Corlette 类型","type":"select","required":true,"options":[{"value":1,"label":"Ⅰ 型：汇合部以下"},{"value":2,"label":"Ⅱ 型：累及汇合部"},{"value":3,"label":"Ⅲa 型：累及右肝管"},{"value":4,"label":"Ⅲb 型：累及左肝管"},{"value":5,"label":"Ⅳ 型：累及双侧肝管"}]}],"formula":"Bismuth-Corlette Ⅰ–Ⅳ 型（Ⅲ 型按左右分支分 a/b）","compute":"formula_only","algorithm":"直接按 type 取 Bismuth-Corlette 分型；v = type","interpret":[{"when":"type >= 4","level":"crit","text":"Ⅲa/Ⅲb/Ⅳ 型：需更广泛的肝切除（半肝或多段切除）+ 胆肠吻合，评估残肝体积与门静脉/肝动脉受累，多学科讨论"},{"when":"type == 3","level":"high","text":"Ⅲ 型：右/左肝管受累，常需半肝切除，注意对侧肝管确保切缘阴性"},{"when":"type == 2","level":"warn","text":"Ⅱ 型：累及汇合部，可行局部切除+胆管重建，R0 切除难度较大"},{"when":"type == 1","level":"ok","text":"Ⅰ 型：局部切除可行，胆管切缘需 > 5 mm 评估"}],"note":"Bismuth-Corlette 分型不包含血管侵犯与远处转移，需结合增强 CT/MRCP 评估门静脉、肝动脉与肝叶萎缩；单纯胆管造影分型可能低估累及范围。","refs":["2019 胆管癌诊断与治疗指南（中华医学会外科学分会胆道外科学组）","Bismuth H, Corlette MB. Intrahepatic cholangiocarcinoma：surgical anatomy. Surg Clin North Am 1975"]},{"id":"lith_stone","name":"胆总管结石预测（ASGE 风险分层）","aka":["ASGE risk stratification","可疑胆总管结石"],"cat":"胆道疾病","rank":31,"desc":"依据临床、生化与影像指标将可疑胆总管结石分为低/中/高危，决定 ERCP 或 MRCP 先做。","inputs":[{"key":"hgb","label":"黄疸（TBIL > 34 μmol/L 或可见黄疸）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"dilated","label":"胆总管扩张（> 6 mm 或 > 8 mm 术后）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"stone_img","label":"影像学见胆总管结石","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"cholangitis","label":"胆管炎（发热+黄疸+右上腹痛）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"bili_high","label":"TBIL > 68 μmol/L（4 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"alt_high","label":"ALT 明显升高（> 3×ULN）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age55","label":"年龄 > 55 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"ASGE 分层：高危（任一强预测因子：影像见结石、胆管炎、TBIL > 68 μmol/L 且胆管扩张）→ 直接 ERCP；中危（黄疸、胆管扩张或肝功能异常）→ MRCP/EUS；低危（无上述因素）→ 胆囊切除，无需 ERCP","compute":"asge_bile","algorithm":"高危：stone_img==1 或 cholangitis==1 或 (bili_high==1 且 dilated==1)\n中危：hgb==1 或 dilated==1 或 alt_high==1\n低危：其余\nv = 高危 3 / 中危 2 / 低危 1（interpret 以 v 与单项条件共同判断时以单项条件优先）","interpret":[{"when":"stone_img == 1 || cholangitis == 1","level":"crit","text":"高危：直接 ERCP（胆管炎 24 h 内，需抗生素与液体复苏），避免不必要的 MRCP 延误"},{"when":"bili_high == 1 && dilated == 1","level":"crit","text":"高危（TBIL > 68 μmol/L 且胆管扩张）：直接 ERCP；若无法施行，行 MRCP/EUS 定位"},{"when":"hgb == 1 || dilated == 1 || alt_high == 1","level":"warn","text":"中危：先行 MRCP 或 EUS，阳性再 ERCP；ALT 升高常提示结石已排出"},{"when":"age55 == 1","level":"warn","text":"低危（老年单独一项）：胆囊切除前无需 ERCP/MRCP，术中胆道造影视需要"},{"when":"v >= 0","level":"ok","text":"低危：择期 LC，围术期监测胆红素"}],"note":"本条目为 ASGE 2010 风险分层简化输入版，非数值评分。胆管炎合并休克（ACST）应紧急 ERCP 引流（PTCD 或 ENBD）。","refs":["2019 中国急性胆管炎诊断与治疗指南（中华医学会外科学分会胆道外科学组）","ASGE Guideline: The role of endoscopy in the evaluation of suspected choledocholithiasis. Gastrointest Endosc 2010"]},{"id":"balthazar_class","name":"Balthazar CT 分级（胰腺炎形态）","aka":["Balthazar grade"],"cat":"急性胰腺炎","rank":32,"desc":"按 CT 上胰腺形态（正常、肿大、炎症扩散、积液、坏死）分级 A–E，判断并发坏死风险。","inputs":[{"key":"grade","label":"CT 分级","type":"select","required":true,"options":[{"value":1,"label":"A：正常胰腺"},{"value":2,"label":"B：胰腺局灶或弥漫肿大"},{"value":3,"label":"C：胰腺及周围炎症/脂肪条索"},{"value":4,"label":"D：单个胰周积液"},{"value":5,"label":"E：≥ 2 个积液或腹膜后积气"}]}],"formula":"Balthazar A–E 级（0–4 分：A=0、B=1、C=2、D=3、E=4）；与坏死结合为 CTSI","compute":"formula_only","algorithm":"直接按 grade 取 A-E；v = grade（1-5），CTSI 形态分 = grade-1","interpret":[{"when":"grade == 5","level":"crit","text":"E 级：多区域积液/积气，感染与坏死风险最高，加强液体复苏、营养与影像随访，考虑引流"},{"when":"grade == 4","level":"high","text":"D 级：单个积液，重症倾向，72 h 复查 CT 评估坏死"},{"when":"grade <= 3","level":"ok","text":"A–C 级：形态学较轻，以支持治疗与病因处理为主"}],"note":"Balthazar 仅描述形态，应与坏死范围合成 CTSI（见 ctsi 条目）；早期 CT 对坏死判断不足，72 h 后更准确。","refs":["2019 中国急性胰腺炎诊治指南（影像学）","Balthazar EJ, et al. Acute pancreatitis: prognostic value of CT. Radiology 1985"]},{"id":"likelihood_gi_pneumatosis","name":"急性肠系膜缺血早期识别（乳酸+症状）","aka":["AMI early detection","肠系膜缺血风险提示"],"cat":"急腹症","rank":33,"desc":"结合乳酸、疼痛-体征分离与危险因素提示肠系膜缺血需行 CTA 评估。","inputs":[{"key":"lac","label":"乳酸","unit":"mmol/L","type":"number","min":0.1,"max":25,"step":0.1,"required":true},{"key":"pain_ratio","label":"疼痛剧烈但与体征不符（疼痛-体征分离）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"af","label":"房颤/近期栓塞史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"age","label":"年龄 > 60 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"lactate_warn","label":"白细胞升高/代谢性酸中毒","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]}],"formula":"风险项：乳酸升高（> 2）×3 + 疼痛-体征分离×3 + 房颤/栓塞史×2 + 年龄 > 60×1 + 血象/酸中毒×1；≥ 5 分提示高度怀疑","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"高度怀疑肠系膜缺血：立即行腹部 CTPA（血管重建），禁灌肠，外科/介入会诊，抗凝（遵说明书）"},{"when":"v >= 3","level":"warn","text":"中等怀疑：CTA 评估，监测乳酸与腹部体征变化"},{"when":"v >= 0","level":"ok","text":"低度怀疑：按急性腹痛常规鉴别；症状不进食物或进展时复评"}],"note":"本条目为临床风险提示，非权威评分；肠系膜静脉血栓、非闭塞性肠缺血也可无房颤史。禁忌使用「乳酸正常即排除」。","refs":["2020 急性肠系膜缺血诊治中国专家共识（中华医学会外科学分会血管外科学组）","WSES Guidelines on acute mesenteric ischemia: World J Emerg Surg 2017"]}]},"heme":{"items":[{"id":"heme_mcv_classification","name":"贫血形态学分类（MCV / MCHC 判读）","aka":["MCV 分类","正细胞性贫血"],"cat":"贫血评估","rank":1,"desc":"按 MCV 与 MCHC 将贫血分为大细胞、正细胞、小细胞低色素三类。","inputs":[{"key":"mcv","label":"MCV","unit":"fL","type":"number","min":40,"max":150,"step":0.1,"required":true},{"key":"mchc","label":"MCHC","unit":"g/L","type":"number","min":200,"max":450,"step":1,"required":true},{"key":"hb","label":"血红蛋白（可选）","unit":"g/L","type":"number","min":20,"max":220,"step":1,"required":false}],"formula":"MCV < 80 fL 小细胞；80–100 fL 正细胞；> 100 fL 大细胞。MCHC < 320 g/L 提示低色素","compute":"formula_only","algorithm":"v = mcv","interpret":[{"when":"mcv < 80 && mchc < 320","level":"warn","text":"小细胞低色素性贫血：查铁四项、血红蛋白电泳、地中海贫血筛查"},{"when":"mcv < 80","level":"warn","text":"小细胞性贫血：缺铁、地中海贫血、慢性病贫血、铁粒幼细胞贫血"},{"when":"mcv > 100","level":"high","text":"大细胞性贫血：查维生素 B12、叶酸、甲功、酒精、MDS/巨幼贫"},{"when":"mcv >= 80 && mcv <= 100","level":"ok","text":"正细胞性贫血：查网织红、溶血指标、肾功、慢性炎症、骨髓"}],"note":"儿童与妊娠期 MCV 参考区间不同；网织红升高伴正细胞提示出血或溶血。","refs":["血液病诊断及疗效标准（第 4 版，2018）","中国成人缺铁性贫血诊治专家共识（2018）"]},{"id":"heme_hb_anemia_grade","name":"血红蛋白与贫血分级","aka":["Hb 分级","贫血严重度"],"cat":"贫血评估","rank":2,"desc":"按 WHO 与国内标准判定贫血及严重程度。","inputs":[{"key":"hb","label":"血红蛋白","unit":"g/L","type":"number","min":20,"max":220,"step":1,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女（非妊娠）"}],"required":true}],"formula":"成人贫血：男 Hb < 130 g/L，女 < 120 g/L；轻度 > 90、中度 60–89、重度 30–59、极重度 < 30 g/L","compute":"formula_only","algorithm":"anemia = sex==1 ? hb<130 : hb<120; v = hb","interpret":[{"when":"(sex == 1 && hb >= 130) || (sex == 0 && hb >= 120)","level":"ok","text":"血红蛋白正常"},{"when":"hb >= 90","level":"warn","text":"轻度贫血（90 g/L 至正常下限）：查病因，多为慢性失血或营养性"},{"when":"hb >= 60 && hb < 90","level":"high","text":"中度贫血：进一步查网织红、铁代谢、叶酸 B12，评估输血指征"},{"when":"hb >= 30 && hb < 60","level":"crit","text":"重度贫血：多需输血，注意心衰与输注速度"},{"when":"hb < 30","level":"crit","text":"极重度贫血：紧急输血与生命支持"}],"note":"国内分级按 Hb 90/60/30 为界；孕妇 < 110 g/L、老年男性阈值不同；急性失血时 Hb 延迟下降。","refs":["血液病诊断及疗效标准（第 4 版，2018）","WHO Haemoglobin Concentrations for the Diagnosis of Anaemia (2011)"]},{"id":"heme_plt_thrombocytopenia","name":"血小板减少分级","aka":["PLT 分级","血小板计数分级"],"cat":"贫血评估","rank":3,"desc":"按血小板计数分级并提示出血风险与干预。","inputs":[{"key":"plt","label":"血小板计数","unit":"×10⁹/L","type":"number","min":1,"max":1500,"step":1,"required":true}],"formula":"按 PLT 计数分度（100–300 正常）","compute":"formula_only","algorithm":"v = plt","interpret":[{"when":"plt < 10","level":"crit","text":"极重度（< 10）：自发出血高危，输注血小板（ITP 除外需权衡）"},{"when":"plt < 20","level":"crit","text":"重度（10–19）：避免侵入操作，必要时输注血小板"},{"when":"plt < 50","level":"high","text":"中度（20–49）：避免肌肉注射与手术，重大手术前需 ≥ 50"},{"when":"plt < 100","level":"warn","text":"轻度（50–99）：查病因（ITP、脾亢、药物、HIT）"},{"when":"plt <= 300","level":"ok","text":"血小板计数正常"},{"when":"plt > 300","level":"warn","text":"血小板增多（> 300）：查反应性（感染/缺铁）与原发（ET/JAK2）"}],"note":"ITP 输注指征遵循指南（有活动性出血才输）；血小板 < 50 时腰穿、中心静脉置管需谨慎；HIT 需用 4T 评分。","refs":["成人原发免疫性血小板减少症诊断与治疗中国指南（2020）","CTCAE v5.0 血小板减少分级"]},{"id":"heme_isth_dic","name":"DIC 诊断评分（ISTH）","aka":["ISTH DIC Score","弥散性血管内凝血评分"],"cat":"出凝血","rank":4,"desc":"用血小板、D-二聚体、PT、纤维蛋白原综合评分判断显性 DIC。","inputs":[{"key":"plt","label":"血小板（×10⁹/L）","unit":"","type":"select","options":[{"value":0,"label":"≥ 100"},{"value":1,"label":"< 100"},{"value":2,"label":"< 50"}],"required":true},{"key":"ddimer","label":"D-二聚体/纤维蛋白降解产物","unit":"","type":"select","options":[{"value":0,"label":"未升高"},{"value":2,"label":"中度升高"},{"value":3,"label":"显著升高"}],"required":true},{"key":"pt","label":"PT 延长","unit":"","type":"select","options":[{"value":0,"label":"< 3 s"},{"value":1,"label":"3–6 s"},{"value":2,"label":"> 6 s"}],"required":true},{"key":"fibrinogen","label":"纤维蛋白原","unit":"","type":"select","options":[{"value":0,"label":"≥ 1.0 g/L"},{"value":1,"label":"< 1.0 g/L"}],"required":true}],"formula":"ISTH 显性 DIC：PLT + D-二聚体 + PT + FIB，0–8 分","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"≥ 5 分：符合显性 DIC，治疗原发病，出血者补充血浆/血小板/纤维蛋白原，不推荐肝素除非血栓为主"},{"when":"v < 5","level":"warn","text":"< 5 分：非显性 DIC，动态监测（每 4–12 h）"}],"note":"D-二聚体按实验室区间分级（中度/显著）；必要时用 DIC 动态监测（每日评分）；产科、肝病需结合专科标准。","refs":["中国弥散性血管内凝血诊断与治疗指南（2017）","ISTH Guidelines for DIC Diagnosis (2013)"]},{"id":"heme_wells_dvt","name":"Wells 评分（深静脉血栓）","aka":["Wells DVT Score","DVT 概率"],"cat":"血栓与止血","rank":5,"desc":"预测下肢深静脉血栓的临床概率，指导 D-二聚体和影像流程。","inputs":[{"key":"cancer","label":"活动性肿瘤（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"paralysis","label":"瘫痪/石膏固定（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bedridden","label":"卧床 > 3 天或 4 周内大手术（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"tenderness","label":"沿深静脉走行压痛（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"swelling","label":"整个下肢肿胀（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"calf","label":"小腿肿胀 > 3 cm（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"pitting","label":"凹陷性水肿（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"collateral","label":"非静脉曲张的侧支浅静脉（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"prior_dvt","label":"既往 DVT 史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"alternative","label":"至少与 DVT 同样可能的替代诊断（−2）","unit":"","type":"select","options":[{"value":0,"label":"无/否"},{"value":-2,"label":"是（−2）"}],"required":true}],"formula":"Wells = 各项之和（−2 至 9）","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"高概率（≥ 3）：直接查下肢静脉加压超声"},{"when":"v >= 1 && v <= 2","level":"warn","text":"中概率（1–2）：测 D-二聚体，阳性则超声"},{"when":"v <= 0","level":"ok","text":"低概率（≤ 0）：D-二聚体阴性可除外 DVT"}],"note":"用二分法时可把 ≤ 0 视为「DVT 不可能」；孕妇、复发性 DVT 需用专科评分；D-二聚体按年龄校正（> 50 岁：年龄×10 μg/L FEU）。","refs":["中国肺血栓栓塞症诊治与预防指南（2018）","CHEST Antithrombotic Therapy for VTE Disease (2021)"]},{"id":"heme_4t_hit","name":"4T 评分（肝素诱导血小板减少症 HIT）","aka":["4Ts","HIT 评分"],"cat":"血栓与止血","rank":6,"desc":"评估肝素诱导血小板减少症临床概率，指导抗体检测与替代抗凝。","inputs":[{"key":"thrombocytopenia","label":"血小板减少程度","unit":"","type":"select","options":[{"value":0,"label":"下降 < 30% 或最低 < 10"},{"value":1,"label":"下降 30–50% 或最低 10–19"},{"value":2,"label":"下降 > 50% 且最低 ≥ 20"}],"required":true},{"key":"timing","label":"血小板下降时间","unit":"","type":"select","options":[{"value":0,"label":"≤ 4 天且无近期肝素暴露"},{"value":1,"label":"> 10 天/不确定/≤ 1 天（有暴露史）"},{"value":2,"label":"5–10 天（或 ≤ 1 天且有近期暴露）"}],"required":true},{"key":"thrombosis","label":"血栓或其他后遗症","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"进展/复发/疑皮肤坏死"},{"value":2,"label":"新发血栓/皮肤坏死/急性全身反应"}],"required":true},{"key":"other_cause","label":"其他导致血小板减少的原因","unit":"","type":"select","options":[{"value":0,"label":"明确存在"},{"value":1,"label":"可能存在"},{"value":2,"label":"不存在"}],"required":true}],"formula":"4T = 四项各 0–2 分（0–8）","compute":"sum","interpret":[{"when":"v >= 6","level":"crit","text":"高概率（6–8）：立即停用肝素并换用非肝素抗凝（argatroban/比伐卢定/磺达肝癸钠），送 HIT 抗体"},{"when":"v >= 4 && v <= 5","level":"high","text":"中概率（4–5）：查 HIT 抗体（PF4/肝素 ELISA），阳性者行功能试验"},{"when":"v <= 3","level":"ok","text":"低概率（≤ 3）：HIT 可能性低，可继续肝素并每日监测血小板"}],"note":"HIT 典型为血小板下降 > 50% 且发生在肝素使用 5–10 天；只能用直接凝血酶抑制剂或磺达肝癸钠，禁用华法林单药与血小板输注。","refs":["肝素诱导的血小板减少症中国专家共识（2017）","ASH Guidelines for HIT (2018)"]},{"id":"heme_padua","name":"Padua 血栓风险评分","aka":["Padua Score","内科住院患者 VTE 风险"],"cat":"血栓预防","rank":7,"desc":"内科住院患者静脉血栓栓塞风险评估。","inputs":[{"key":"cancer","label":"活动性肿瘤（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"prior_vte","label":"既往 VTE（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"immobilization","label":"活动受限 ≥ 3 天（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"thrombophilia","label":"已知易栓症（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"trauma","label":"近期创伤/大手术（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age70","label":"年龄 ≥ 70 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"heart_resp_failure","label":"心衰和/或呼吸衰竭（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ami_stroke","label":"急性心梗或缺血性卒中（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"infection","label":"急性感染/风湿病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"obesity","label":"肥胖 BMI ≥ 30（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"hormone","label":"激素治疗（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"Padua 评分各项之和，0–20","compute":"sum","interpret":[{"when":"v >= 4","level":"high","text":"VTE 高危（≥ 4）：无禁忌可药物预防（低分子肝素/磺达肝癸钠），评估出血风险"},{"when":"v >= 1 && v <= 3","level":"warn","text":"低-中危：基础预防（早期活动、机械预防），每 2 天复评"},{"when":"v == 0","level":"ok","text":"低危：基础预防"}],"note":"与出血风险（如 IMPROVE 出血评分）联合决策；肿瘤患者注意低分子肝素剂量；肾衰需按 CrCl 调整。","refs":["中国血栓性疾病防治指南（2018）","ACCP Antithrombotic Therapy (2012) / Padua Prediction Score, Barbar 2010"]},{"id":"heme_caprini","name":"Caprini 血栓风险评分（外科/围手术期）","aka":["Caprini RAM","外科 VTE 评分"],"cat":"血栓预防","rank":8,"desc":"外科与住院患者 VTE 风险分层，指导围手术期血栓预防。","inputs":[{"key":"age41_60","label":"年龄 41–60 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"minor_surgery","label":"小手术（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bmi25","label":"BMI > 25（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"swollen_legs","label":"下肢肿胀/静脉曲张（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age61_74","label":"年龄 61–74 岁（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"major_surgery","label":"大手术 > 45 min（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"malignancy","label":"恶性肿瘤（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"bedridden","label":"卧床 > 72 h（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"prior_vte","label":"既往 VTE（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"family_vte","label":"VTE 家族史（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"stroke","label":"卒中（+5）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":5,"label":"是"}],"required":true}],"formula":"Caprini 各项权重相加（0–20+）","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"极高危（≥ 5）：药物预防 + 机械预防，延长预防至出院后 4 周"},{"when":"v >= 3 && v < 5","level":"high","text":"高危（3–4）：药物或机械预防，评估出血风险"},{"when":"v == 2","level":"warn","text":"中危（2）：机械预防，必要时药物预防"},{"when":"v <= 1","level":"ok","text":"低危（0–1）：早期活动与基础预防"}],"note":"本表为常见条目简化版；完整 Caprini 含 40+ 项，评分 > 9 的极高危患者可考虑下腔静脉滤器（有禁忌时）；需同时评估出血（如 IMPROVE Bleeding）。","refs":["中国骨科大手术静脉血栓栓塞症预防指南（2016）","CHEST Antithrombotic Therapy (2012) / Caprini JA 2005"]},{"id":"heme_improve_vte","name":"IMPROVE VTE 风险评分","aka":["IMPROVE VTE","IMPROVE 评分"],"cat":"血栓预防","rank":12,"desc":"内科住院患者 VTE 风险预测（与 Padua 互补）。","inputs":[{"key":"prior_vte","label":"既往 VTE（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true},{"key":"thrombophilia","label":"已知易栓症（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"immobilization","label":"需卧床 ≥ 7 天（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"cancer","label":"行放疗/化疗的肿瘤（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"icu","label":"ICU 住院（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age60","label":"年龄 ≥ 60 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"immob_mob","label":"下肢不能活动（偏瘫/截瘫）（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"IMPROVE VTE 各项之和（0–11）","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"VTE 高风险（≥ 3）：评估药物预防（肝素/磺达肝癸钠），同评出血风险"},{"when":"v >= 1 && v <= 2","level":"warn","text":"中危：机械预防与早期活动"},{"when":"v == 0","level":"ok","text":"低危"}],"note":"IMPROVE VTE 2.0 已修订部分条目权重；与 IMPROVE Bleeding 配对使用可提高预防决策准确性。","refs":["中国血栓性疾病防治指南（2018）","Spyropoulos AC, et al. J Thromb Haemost 2011"]},{"id":"heme_iron_studies","name":"铁代谢指标判读（SI、TSAT、TIBC、铁蛋白）","aka":["TSAT","缺铁性贫血鉴别"],"cat":"贫血评估","rank":9,"desc":"由血清铁、总铁结合力、铁蛋白计算 TSAT 并鉴别缺铁、慢性病贫血、铁过载。","inputs":[{"key":"si","label":"血清铁 SI","unit":"μmol/L","type":"number","min":0,"max":100,"step":0.1,"required":true},{"key":"tibc","label":"总铁结合力 TIBC","unit":"μmol/L","type":"number","min":10,"max":120,"step":0.1,"required":true},{"key":"ferritin","label":"铁蛋白","unit":"ng/mL","type":"number","min":0,"max":5000,"step":1,"required":true},{"key":"crp_high","label":"CRP 升高/活动性炎症","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"TSAT(%) = 血清铁/TIBC×100；缺铁：TSAT < 20%、铁蛋白 < 30 ng/mL；铁过载：TSAT > 50%","compute":"formula_only","algorithm":"v = si/tibc*100","interpret":[{"when":"ferritin < 30 && v < 20","level":"high","text":"绝对缺铁：口服铁剂（必要时静脉铁），查失血原因（消化道/月经过多）"},{"when":"ferritin >= 30 && ferritin <= 100 && v < 20 && crp_high == 1","level":"warn","text":"炎症状态下缺铁可能（功能性缺铁）：铁蛋白 30–100 ng/mL 提示需静脉铁评估"},{"when":"v >= 50","level":"warn","text":"TSAT ≥ 50%：筛查血色病/HFE、反复输血铁过载，查铁蛋白并考虑祛铁"},{"when":"ferritin > 1000","level":"high","text":"铁蛋白 > 1000 ng/mL：注意炎症、肝病、肿瘤或噬血细胞综合征"},{"when":"v >= 20 && v < 50","level":"ok","text":"TSAT 与铁蛋白在参考范围，铁状态正常"}],"note":"铁蛋白为急性期反应蛋白，炎症时正常上限提高；贫血且铁蛋白 > 100–300 不建议盲目补铁；地中海贫血者 TSAT 正常或升高。","refs":["中国成人缺铁性贫血诊治专家共识（2018）","KDIGO Anemia in CKD Guideline (2012)"]},{"id":"heme_kdigo_anemia","name":"KDIGO 贫血评估（CKD）","aka":["CKD 贫血分级","肾性贫血评估"],"cat":"贫血评估","rank":10,"desc":"按 CKD 患者 Hb 水平判定贫血程度与铁剂/ESA 治疗指征。","inputs":[{"key":"hb","label":"血红蛋白","unit":"g/L","type":"number","min":30,"max":200,"step":1,"required":true},{"key":"male_adult","label":"成年男性","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true},{"key":"tsat","label":"转铁蛋白饱和度（可选）","unit":"%","type":"number","min":0,"max":100,"step":0.1,"required":false},{"key":"egfr","label":"eGFR（可选）","unit":"mL/min/1.73m²","type":"number","min":1,"max":150,"step":1,"required":false}],"formula":"CKD 贫血：成年男 Hb < 130 g/L、绝经后女 < 120 g/L、绝经前女 < 110 g/L","compute":"formula_only","algorithm":"v = hb; threshold = male_adult?130:120","interpret":[{"when":"hb >= 130","level":"ok","text":"Hb ≥ 130：多数 CKD 患者无需 ESA"},{"when":"hb >= 100 && hb < 130","level":"warn","text":"Hb 100–129：评估铁状态，TSAT < 20% 或铁蛋白 < 200 补铁；不建议盲目 ESA"},{"when":"hb < 100","level":"high","text":"Hb < 100：先纠正铁缺乏（静脉铁优先），再考虑 ESA 治疗（目标 Hb 110–120）"},{"when":"hb < 80","level":"crit","text":"Hb < 80：症状明显者考虑输血；查其他病因（失血、溶血、甲旁亢）"}],"note":"ESA 目标 Hb 不超过 130 g/L（卒中与血栓风险）；铁蛋白 > 500 提示需谨慎补铁；HIF-PHI（罗沙司他）可用。","refs":["KDIGO Anemia in CKD Guideline (2012)","中国肾性贫血诊治临床实践指南（2021）"]},{"id":"heme_ipssr","name":"IPSS-R（骨髓增生异常综合征预后评分）","aka":["IPSS-R","MDS 修订国际预后评分"],"cat":"血液肿瘤","rank":13,"desc":"综合细胞遗传、骨髓原始细胞与血细胞减少数判定 MDS 预后分组。","inputs":[{"key":"cyto","label":"细胞遗传学风险","unit":"","type":"select","options":[{"value":0,"label":"极好（−Y, del(11q)）"},{"value":1,"label":"好（正常, del(5q), del(20q), 双克隆）"},{"value":2,"label":"中等（del(7q), +8, +19, i(17q), 其他 1 个异常）"},{"value":3,"label":"差（−7, inv(3)/t(3q), 双异常, 复杂 3 个）"},{"value":4,"label":"极差（复杂 ≥ 3 个异常）"}],"required":true},{"key":"blasts","label":"骨髓原始细胞","unit":"","type":"select","options":[{"value":0,"label":"≤ 2%"},{"value":0.5,"label":"> 2%–< 5%"},{"value":1,"label":"5%–10%"},{"value":1.5,"label":"> 10%–30%"}],"required":true},{"key":"hb_grade","label":"血红蛋白","unit":"","type":"select","options":[{"value":0,"label":"≥ 100 g/L"},{"value":0.5,"label":"80–< 100"},{"value":1,"label":"< 80"}],"required":true},{"key":"plt_grade","label":"血小板","unit":"","type":"select","options":[{"value":0,"label":"≥ 100×10⁹/L"},{"value":0.5,"label":"50–< 100"},{"value":1,"label":"< 50"}],"required":true},{"key":"anc_grade","label":"中性粒细胞","unit":"","type":"select","options":[{"value":0,"label":"≥ 0.8×10⁹/L"},{"value":0.5,"label":"< 0.8"}],"required":true}],"formula":"IPSS-R = 染色体风险分 + 原始细胞分 + 血细胞减少分（Hb、PLT、ANC 之和）","compute":"sum","interpret":[{"when":"v <= 1.5","level":"ok","text":"极低危（≤ 1.5）：监测为主，必要时生长因子/输血"},{"when":"v <= 3","level":"warn","text":"低危（> 1.5–3）：支持治疗，评估来那度胺（del(5q)）、EPO"},{"when":"v <= 4.5","level":"high","text":"中危（> 3–4.5）：评估去甲基化药物（阿扎胞苷/地西他滨）"},{"when":"v <= 6","level":"high","text":"高危（> 4.5–6）：去甲基化药物或异基因造血干细胞移植"},{"when":"v > 6","level":"crit","text":"极高危（> 6）：优先考虑 HSCT 与临床试验"}],"note":"IPSS-R 分值与分组按 Greenberg 2012 原表；WHO 2022 分型改动后需配合分子分型（如 TP53、SF3B1）；儿童不适用。","refs":["中国骨髓增生异常综合征诊断与治疗指南（2024 版）","Greenberg PL, et al. Blood 2012 (IPSS-R)"]},{"id":"heme_cll_staging","name":"慢性淋巴细胞白血病分期（Rai / Binet）","aka":["CLL Rai 分期","Binet 分期"],"cat":"血液肿瘤","rank":16,"desc":"按淋巴结、肝脾肿大与血红蛋白/血小板水平对 CLL 分期。","inputs":[{"key":"stage","label":"分期选择","unit":"","type":"select","options":[{"value":0,"label":"Rai 0 / Binet A（无贫血，淋巴结+肝脾+，Hb≥110, PLT≥100）"},{"value":1,"label":"Rai I / Binet A（淋巴结+，无肝脾肿大）"},{"value":2,"label":"Rai II / Binet B（肝脾肿大，Hb≥110, PLT≥100）"},{"value":3,"label":"Rai III / Binet C（Hb<110）"},{"value":4,"label":"Rai IV（PLT<100 或 PLT<100 且 Hb<110）"},{"value":5,"label":"Binet C（Hb<100 或 PLT<100）"}],"required":true}],"formula":"Rai 0–IV；Binet A–C","compute":"formula_only","algorithm":"v = stage","interpret":[{"when":"stage <= 1","level":"ok","text":"Rai 0–I / Binet A：早期，多观察等待（watch & wait）"},{"when":"stage == 2","level":"warn","text":"Rai II / Binet B：中间期，评估治疗指征（症状、进行性贫血、巨脾）"},{"when":"stage >= 3","level":"high","text":"Rai III–IV / Binet C：晚期，多需治疗（BTK 抑制剂、BCL-2 抑制剂或联合化疗）"}],"note":"Rai 分期 Hb < 110 g/L、PLT < 100×10⁹/L；Binet 用 Hb < 100、PLT < 100；治疗指征按 iwCLL 2018 判断（症状、大块淋巴结、进行性血细胞减少等）。","refs":["中国慢性淋巴细胞白血病诊断与治疗指南（2022 版）","iwCLL Guidelines (2018)"]},{"id":"heme_myeloma_iss","name":"多发性骨髓瘤 ISS / R-ISS 分期","aka":["ISS","R-ISS 分期"],"cat":"血液肿瘤","rank":15,"desc":"按 β2 微球蛋白、白蛋白（及 LDH、细胞遗传）判定 MM 预后分期。","inputs":[{"key":"b2m","label":"β2 微球蛋白","unit":"mg/L","type":"number","min":0.5,"max":40,"step":0.1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":true},{"key":"ldh_high","label":"LDH 高于正常上限","unit":"","type":"select","options":[{"value":0,"label":"否/未查"},{"value":1,"label":"是"}],"required":true},{"key":"high_risk_cyto","label":"高危细胞遗传（del17p、t(4;14)、t(14;16)）","unit":"","type":"select","options":[{"value":0,"label":"否/未查"},{"value":1,"label":"是"}],"required":true}],"formula":"ISS：Ⅰ 期 β2M < 3.5 且 Alb ≥ 35；Ⅱ 期非Ⅰ非Ⅲ；Ⅲ 期 β2M ≥ 5.5。R-ISS：Ⅰ 期 = ISS Ⅰ + 标准细胞遗传 + LDH 正常","compute":"formula_only","algorithm":"if b2m<3.5 && alb>=35 → iss=1\nelse if b2m>=5.5 → iss=3\nelse iss=2\nR-ISS：iss1 且无高危且 LDH 正常 → 1；iss3 且(高危或 LDH 高) → 3；其余 → 2\nv = iss","interpret":[{"when":"b2m < 3.5 && alb >= 35","level":"ok","text":"ISS Ⅰ 期：预后较好（中位 OS 较长），R-ISS Ⅰ 期如无高危细胞遗传与 LDH 升高"},{"when":"b2m < 5.5","level":"warn","text":"ISS Ⅱ 期：中间预后，按 R-ISS 细分"},{"when":"b2m >= 5.5","level":"high","text":"ISS Ⅲ 期：高危，考虑以蛋白酶体抑制剂/免疫调节剂为基础方案与 MRD 监测"}],"note":"β2M 受肾功能影响，肾衰时需校正（按 eGFR 调整）；R-ISS 高危需同时存在 ISS Ⅲ + 高危细胞遗传或高 LDH；新增 R2-ISS。","refs":["中国多发性骨髓瘤诊治指南（2022 年修订）","Greipp PR, et al. Blood 2005 (ISS) / Palumbo A, et al. JCO 2015 (R-ISS)"]},{"id":"heme_lymphoma_stage","name":"淋巴瘤 Ann Arbor 分期","aka":["Ann Arbor","Lugano 分期"],"cat":"血液肿瘤","rank":17,"desc":"依据受累淋巴结区与膈上下分布对淋巴瘤进行 I–IV 期与 A/B 症状分组。","inputs":[{"key":"stage","label":"分期","unit":"","type":"select","options":[{"value":1,"label":"Ⅰ 期（单个淋巴结区或单个结外器官）"},{"value":2,"label":"Ⅱ 期（膈同侧 ≥2 个淋巴结区）"},{"value":3,"label":"Ⅲ 期（膈上下均有淋巴结区）"},{"value":4,"label":"Ⅳ 期（弥漫/播散结外器官）"}],"required":true},{"key":"b_symptom","label":"B 症状（不明原因发热 > 38℃、盗汗、6 月内体重下降 > 10%）","unit":"","type":"select","options":[{"value":0,"label":"无（A）"},{"value":1,"label":"有（B）"}],"required":true}],"formula":"Ⅰ–Ⅳ 期，后缀 A 或 B；E = 结外受累，S = 脾","compute":"formula_only","algorithm":"v = stage*2 + b_symptom","interpret":[{"when":"stage == 1","level":"ok","text":"Ⅰ 期：局限期，早期霍奇金或 NHL 可考虑局部放疗 ± 化疗"},{"when":"stage == 2","level":"warn","text":"Ⅱ 期：局限期（膈同侧），联合化疗 ± 放疗"},{"when":"stage == 3","level":"high","text":"Ⅲ 期：晚期，全身化疗（CHOP/R-CHOP 等）+ PET-CT 评估"},{"when":"stage == 4","level":"crit","text":"Ⅳ 期：广泛播散，以全身化疗为主，注意 CNS 预防与感染支持"}],"note":"Lugano 2014 对 Ann Arbor 做了修订（不建议「X」「E」滥用，PET-CT 为评估标准）；需同时计算 IPI 预后指数。","refs":["中国淋巴瘤治疗指南（2021 版）","Lugano Classification (Cheson BD, JCO 2014)"]},{"id":"heme_anemia_workup_checklist","name":"贫血病因初筛流程清单","aka":["贫血检查清单","Anemia workup"],"cat":"贫血评估","rank":11,"desc":"以勾选方式提示贫血病因筛查项目与判读顺序。","inputs":[{"key":"retic_high","label":"网织红升高（> 2%）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"hemolysis","label":"溶血证据（间接胆红素↑、LDH↑、结合珠蛋白↓）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"mcv_low","label":"MCV < 80 fL","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"mcv_high","label":"MCV > 100 fL","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"renal","label":"肾功能异常","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"bleeding","label":"明确失血（月经过多/消化道出血）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"按勾选结果分派检查路径（不计算总分）","compute":"sum","interpret":[{"when":"hemolysis == 1 && retic_high == 1","level":"crit","text":"考虑溶血：查 Coombs、外周血涂片（破碎红细胞）、LDH、游离 Hb、尿含铁血黄素"},{"when":"mcv_low == 1","level":"warn","text":"小细胞：查铁四项、血红蛋白电泳、粪隐血与妇科评估"},{"when":"mcv_high == 1","level":"warn","text":"大细胞：查 B12、叶酸、甲功、酒精史，警惕 MDS"},{"when":"renal == 1","level":"warn","text":"肾性贫血：查 eGFR、铁状态、PTH，必要时 ESA"},{"when":"v == 0","level":"ok","text":"未发现特定指向：完善骨髓穿刺/活检与全身评估"}],"note":"首诊需同时评估输血指征（Hb < 70 或有症状）；网织红校正指数（RPI）可区分生成低下与失血/溶血。","refs":["血液病诊断及疗效标准（第 4 版，2018）","中国成人缺铁性贫血诊治专家共识（2018）"]},{"id":"heme_hasbled_alias","name":"HAS-BLED（出血风险，血液科别名入口）","aka":["HAS-BLED","出血风险评分"],"cat":"出凝血","rank":18,"desc":"抗凝出血风险评估，主条目在心内科；本项供血液科检索入口，算法一致。","inputs":[{"key":"htn","label":"未控制高血压（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"renal","label":"肾功能异常（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"liver","label":"肝功能异常（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stroke","label":"卒中史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bleed","label":"出血史/易出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"inr","label":"INR 不稳定（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age","label":"年龄 > 65 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"drug","label":"药物（抗血小板/NSAIDs）（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"alcohol","label":"饮酒过量（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"HAS-BLED 9 项相加，0–9","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"≥ 3：出血高危，纠正可逆因素，密切随访；不因评分高停用抗凝"},{"when":"v >= 1 && v <= 2","level":"warn","text":"1–2：中危"},{"when":"v == 0","level":"ok","text":"0：低出血风险"}],"note":"本表与心内科 cardio.json 的 has_bled 为同一量表（别名），合并时的唯一 id 以心内科条目为准。","refs":["心房颤动诊断和治疗中国指南（2023）","Pisters R, et al. Chest 2010"]},{"id":"heme_transfusion_threshold","name":"红细胞输注指征（限制性输血策略）","aka":["输血阈值","Restrictive transfusion"],"cat":"输血","rank":14,"desc":"按 Hb 与临床状况给出限制性输注建议（输入参考非处方）。","inputs":[{"key":"hb","label":"血红蛋白","unit":"g/L","type":"number","min":20,"max":200,"step":1,"required":true},{"key":"acs","label":"急性冠脉综合征/心肌缺血","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"symptomatic","label":"明显贫血症状（晕厥、胸痛、心衰）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"active_bleeding","label":"活动性大出血","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"一般阈值 Hb < 70 g/L；心脏手术/合并冠心病 Hb < 80 g/L；ACS 可考虑 < 80–90 g/L","compute":"formula_only","algorithm":"v = hb","interpret":[{"when":"active_bleeding == 1 || symptomatic == 1","level":"crit","text":"有活动性出血或缺血症状：立即输注红细胞（1–2 U），同时止血/病因处理"},{"when":"acs == 1 && hb < 90","level":"high","text":"ACS 合并 Hb < 90：考虑输注红细胞"},{"when":"hb < 70","level":"high","text":"Hb < 70 g/L：多数成人按限制性策略输注红细胞"},{"when":"hb < 80","level":"warn","text":"Hb 70–79：心脏手术、稳定型冠心病或老年患者可考虑输注"},{"when":"v >= 80","level":"ok","text":"Hb ≥ 80：一般不需输注，查病因并补充造血原料"}],"note":"输注 1 U 红细胞约升高 Hb 5–10 g/L；避免单纯 Hb 驱动输血，需评估容量负荷与输血反应；术前储血与自体输血见输血科。","refs":["临床输血技术规范（2000，国家卫健委）","AABB Red Blood Cell Transfusion Guidelines (2023)"]},{"id":"heme_hodgkin_ips","name":"霍奇金淋巴瘤国际预后评分（IPS）","aka":["IPS","Hasenclever 评分"],"cat":"血液肿瘤","rank":19,"desc":"晚期霍奇金淋巴瘤 7 项不良预后因素评分。","inputs":[{"key":"alb","label":"白蛋白 < 40 g/L（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"hb","label":"Hb < 105 g/L（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"sex","label":"男性（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age","label":"年龄 ≥ 45 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stage","label":"Ⅳ 期（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"wbc","label":"白细胞 ≥ 15×10⁹/L（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"lymph","label":"淋巴细胞 < 0.6×10⁹/L 或 < 8%（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"IPS 0–7 分","compute":"sum","interpret":[{"when":"v <= 1","level":"ok","text":"IPS 0–1：低危，ABVD 方案化疗 6 周期"},{"when":"v == 2","level":"warn","text":"IPS 2：中危，ABVD ± 放疗"},{"when":"v >= 3","level":"high","text":"IPS ≥ 3：高危，考虑 BEACOPP 等强化方案与 PET 中期评估"}],"note":"IPS 适用于晚期（ⅡB–Ⅳ）；早期预后用 GHSG 风险因素；PET-CT 中期 Deauville 评分决定升级。","refs":["中国霍奇金淋巴瘤诊断与治疗指南（2022 版）","Hasenclever D, Diehl V. NEJM 1998"]},{"id":"heme_febrile_neutropenia","name":"中性粒细胞缺乏伴发热风险评估","aka":["粒缺伴发热","Febrile neutropenia"],"cat":"血液肿瘤","rank":20,"desc":"按中性粒细胞绝对计数与发热定义识别高风险，指导经验性抗菌与粒系集落刺激因子使用。","inputs":[{"key":"anc","label":"中性粒细胞绝对计数 ANC","unit":"×10⁹/L","type":"number","min":0,"max":20,"step":0.01,"required":true},{"key":"temp","label":"体温","unit":"℃","type":"number","min":35,"max":42.5,"step":0.1,"required":true},{"key":"duration","label":"预计粒缺持续 > 7 天","unit":"","type":"select","options":[{"value":0,"label":"否/未知"},{"value":1,"label":"是"}],"required":true},{"key":"instability","label":"血流动力学不稳/器官功能障碍","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"粒缺：ANC < 0.5×10⁹/L 或 < 1.0 且预计 48 h 降至 0.5 以下；发热：单次体温 ≥ 38.3℃ 或 ≥ 38.0℃ 持续 1 h","compute":"formula_only","algorithm":"v = anc*100 + (temp>=38.3?1:0)","interpret":[{"when":"instability == 1","level":"crit","text":"血流动力学不稳：立即经验性广谱抗菌（碳青霉烯类），1 h 内给药，按感染性休克流程"},{"when":"anc < 0.5 && (temp >= 38.3 || temp >= 38.0) && duration == 1","level":"crit","text":"高危粒缺伴发热：住院，经验性抗铜绿假单胞菌 β-内酰胺，加拍胸片/HPCT"},{"when":"anc < 0.5 && temp >= 38.3","level":"high","text":"粒缺伴发热：血培养 ×2、尿培养，经验性抗菌，评估 G-CSF"},{"when":"anc < 0.5","level":"warn","text":"粒缺无发热：保护性隔离，监测体温"},{"when":"v >= 50","level":"ok","text":"ANC ≥ 0.5，粒缺已恢复"}],"note":"G-CSF 不常规用于所有发热粒缺，按中国指南在高危/预期长粒缺使用；抗菌药剂量需按肾功能调整，具体遵指南与说明书。","refs":["中国中性粒细胞缺乏伴发热患者抗菌药物临床应用指南（2020 年版）","IDSA Febrile Neutropenia Guideline (2010)"]}]},"id":{"items":[{"id":"id_qsofa","name":"qSOFA 快速序贯器官衰竭评估","aka":["quick SOFA","qSOFA","快速SOFA"],"cat":"脓毒症评估","rank":1,"desc":"非 ICU 场景快速筛查疑似感染患者脓毒症风险的床旁三指标评分（0–3 分）。","inputs":[{"key":"rr","label":"呼吸频率 ≥22 次/min","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"sbp","label":"收缩压 ≤100 mmHg","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"gcs","label":"意识改变（GCS <15）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"qSOFA = RR≥22 + SBP≤100 + GCS<15，三项各 1 分，总分 0–3","compute":"sum","interpret":[{"when":"v >= 2","level":"crit","text":"qSOFA ≥2：疑似感染患者死亡风险显著升高，应立即评估器官功能（SOFA、乳酸），按脓毒症 1 h 集束化处置"},{"when":"v == 1","level":"warn","text":"qSOFA = 1：密切观察，6–12 h 内重复评估，查乳酸、血培养与感染灶"},{"when":"v == 0","level":"ok","text":"qSOFA = 0：脓毒症可能性低，按感染常规处理；病情变化随时复评"}],"note":"qSOFA 是床旁预警而非诊断标准，不能替代 SOFA；灵敏度偏低，单独使用可能漏诊，须结合乳酸、临床判断与感染证据。","refs":["Sepsis-3 定义（JAMA 2016）","拯救脓毒症运动（SSC）国际指南 2021"]},{"id":"id_sofa","name":"SOFA 序贯器官衰竭评分","aka":["SOFA score","Sequential Organ Failure Assessment"],"cat":"脓毒症评估","rank":2,"desc":"6 个器官系统（呼吸、凝血、肝、循环、中枢、肾）0–4 分累加，用于诊断脓毒症与评估器官功能障碍程度。","inputs":[{"key":"resp","label":"呼吸：PaO2/FiO2 分级","unit":"","type":"select","options":[{"value":0,"label":"≥400"},{"value":1,"label":"<400"},{"value":2,"label":"<300"},{"value":3,"label":"<200 且需呼吸支持"},{"value":4,"label":"<100 且需呼吸支持"}],"required":true},{"key":"coag","label":"凝血：血小板","unit":"","type":"select","options":[{"value":0,"label":"≥150×10⁹/L"},{"value":1,"label":"<150×10⁹/L"},{"value":2,"label":"<100×10⁹/L"},{"value":3,"label":"<50×10⁹/L"},{"value":4,"label":"<20×10⁹/L"}],"required":true},{"key":"liver","label":"肝：胆红素","unit":"","type":"select","options":[{"value":0,"label":"<20 μmol/L"},{"value":1,"label":"20–32 μmol/L"},{"value":2,"label":"33–101 μmol/L"},{"value":3,"label":"102–204 μmol/L"},{"value":4,"label":">204 μmol/L"}],"required":true},{"key":"cardio","label":"循环：MAP / 升压药","unit":"","type":"select","options":[{"value":0,"label":"MAP ≥70 mmHg"},{"value":1,"label":"MAP <70 mmHg"},{"value":2,"label":"多巴胺 ≤5 或任何剂量多巴酚丁胺"},{"value":3,"label":"多巴胺 >5 或去甲肾上腺素 ≤0.1 μg/kg/min"},{"value":4,"label":"多巴胺 >15 或去甲肾上腺素 >0.1 μg/kg/min"}],"required":true},{"key":"cns","label":"中枢：GCS","unit":"","type":"select","options":[{"value":0,"label":"GCS 15"},{"value":1,"label":"GCS 13–14"},{"value":2,"label":"GCS 10–12"},{"value":3,"label":"GCS 6–9"},{"value":4,"label":"GCS <6"}],"required":true},{"key":"renal","label":"肾：肌酐 / 尿量","unit":"","type":"select","options":[{"value":0,"label":"Cr <110 μmol/L"},{"value":1,"label":"Cr 110–170 μmol/L"},{"value":2,"label":"Cr 171–299 μmol/L"},{"value":3,"label":"Cr 300–440 或尿量 <500 mL/d"},{"value":4,"label":"Cr >440 或尿量 <200 mL/d"}],"required":true}],"formula":"SOFA = 6 个系统分值之和（0–24）；脓毒症诊断需在感染基础上较基线急性升高 ≥2 分","compute":"sum","interpret":[{"when":"v >= 15","level":"crit","text":"SOFA ≥15：极重度器官功能障碍，ICU 病死率 >80%，需多器官支持与限制性治疗决策讨论"},{"when":"v >= 12","level":"crit","text":"SOFA 12–14：重度器官功能障碍，病死率约 50%–80%，脓毒症流程+器官支持+感染源控制"},{"when":"v >= 8","level":"high","text":"SOFA 8–11：重度脓毒症，病死率约 25%–50%，需 ICU 评估、有创监测与积极复苏"},{"when":"v >= 2","level":"warn","text":"SOFA 2–7：若为急性升高 ≥2 分即诊断脓毒症，按 1 h 集束化处理并每 2–4 h 复评"},{"when":"v < 2","level":"ok","text":"SOFA 0–1：无显著器官功能障碍；感染患者仍需监测生命体征与乳酸"}],"note":"需与患者基线 SOFA 对比（慢性器官衰竭者常已有基础分）；循环项用去甲肾上腺素剂量，多巴胺剂量单位为 μg/kg/min。","refs":["Sepsis-3 定义（JAMA 2016）","拯救脓毒症运动（SSC）国际指南 2021","中国脓毒症/脓毒性休克急诊治疗指南 2018"]},{"id":"id_sirs","name":"SIRS 全身炎症反应综合征标准","aka":["SIRS","Systemic Inflammatory Response Syndrome"],"cat":"脓毒症评估","rank":3,"desc":"感染或非感染性炎症的经典四项判据，满足 ≥2 项视为 SIRS（旧版脓毒症定义要素，现用于辅助判断炎症状态）。","inputs":[{"key":"temp","label":"体温异常","unit":"","type":"select","options":[{"value":1,"label":">38 ℃ 或 <36 ℃"},{"value":0,"label":"36–38 ℃"}],"required":true},{"key":"hr","label":"心率 >90 次/min","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"rr","label":"呼吸 >20 次/min 或 PaCO2 <32 mmHg","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"wbc","label":"白细胞 >12 或 <4×10⁹/L，或杆状核 >10%","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"SIRS 满足项数 = 体温异常 + 心率>90 + 呼吸>20（或 PaCO2<32）+ 白细胞异常，≥2 项为 SIRS","compute":"sum","interpret":[{"when":"v >= 2","level":"warn","text":"符合 SIRS：存在系统性炎症，需鉴别感染与非感染原因（胰腺炎、创伤、术后、自身免疫病）；感染证据者进一步用 SOFA 评估脓毒症"},{"when":"v == 1","level":"ok","text":"不足以诊断 SIRS：结合感染灶、CRP/PCT 与影像随访"},{"when":"v == 0","level":"ok","text":"无 SIRS 表现：暂不考虑系统性炎症，按原发病处理"}],"note":"SIRS 特异性低，非感染性疾病也可阳性；脓毒症诊断已改用 Sepsis-3（感染 + SOFA ≥2），SIRS 不作诊断必需条件。","refs":["ACCP/SCCM 共识 1992（SIRS 原始定义）","Sepsis-3 定义（JAMA 2016）","中国脓毒症/脓毒性休克急诊治疗指南 2018"]},{"id":"id_curb65","name":"CURB-65 社区获得性肺炎严重度评分","aka":["CURB-65","CAP severity"],"cat":"呼吸道感染评估","rank":4,"desc":"以意识、尿素氮、呼吸频率、血压、年龄 5 项判断社区获得性肺炎（CAP）严重度与住院/ICU 需求。","inputs":[{"key":"confusion","label":"新发意识障碍（Confusion）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"urea","label":"血尿素氮 >7 mmol/L（Urea）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"rr","label":"呼吸频率 ≥30 次/min（RR）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"bp","label":"SBP <90 mmHg 或 DBP ≤60 mmHg（BP）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"age","label":"年龄 ≥65 岁","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"CURB-65 = C + U + R + B + 年龄≥65，各 1 分，总分 0–5","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"CURB-65 ≥3：重症 CAP，30 天病死率约 15%–30%，住院治疗，评估 ICU 转入（另参考 IDSA/ATS 次要/主要标准）"},{"when":"v == 2","level":"warn","text":"CURB-65 = 2：住院（普通病房）治疗，经验性抗感染 + 监测血氧与意识"},{"when":"v == 1","level":"ok","text":"CURB-65 = 1：可门诊治疗，老年或合并病多者考虑短期留观"},{"when":"v == 0","level":"ok","text":"CURB-65 = 0：低危，可门诊口服抗菌药治疗并 48–72 h 复诊"}],"note":"CURB-65 不能替代 IDSA/ATS 重症 CAP 标准（需有创通气、脓毒症休克、多叶浸润、PaO2/FiO2 <250 等）；老年、免疫抑制、低氧血症者应偏低门槛住院。","refs":["中国成人社区获得性肺炎诊断和治疗指南（2016 年版）","BTS 社区获得性肺炎管理指南 2009（CURB-65）","IDSA/ATS 成人 CAP 诊治指南 2019"]},{"id":"id_pct_interpret","name":"降钙素原（PCT）判读","aka":["Procalcitonin","PCT 判读","降钙素原阈值"],"cat":"实验室判读","rank":5,"desc":"按 PCT 浓度区间提示细菌感染可能性、脓毒症风险与抗菌药物疗程决策参考。","inputs":[{"key":"pct","label":"血清 PCT","unit":"ng/mL","type":"number","min":0,"max":1000,"step":0.01,"required":true}],"formula":"判读区间：<0.1 细菌感染可能性低；0.1–0.5 需结合临床；0.5–2 可能细菌感染；2–10 提示脓毒症风险高；>10 高度提示脓毒性休克/重症感染","compute":"formula_only","algorithm":"v = pct","interpret":[{"when":"pct > 10","level":"crit","text":"PCT >10 ng/mL：高度提示严重细菌感染或脓毒性休克，立即血培养+经验性广谱抗菌药并按脓毒症流程处理；PCT 下降 <80%/48 h 提示治疗失败或感染源未控制"},{"when":"pct > 2","level":"high","text":"PCT 2–10 ng/mL：脓毒症风险较高，强烈提示细菌感染，启动/强化抗菌治疗并评估感染灶"},{"when":"pct > 0.5","level":"warn","text":"PCT 0.5–2 ng/mL：可能存在细菌感染（尤其呼吸道/腹腔），结合 CRP、白细胞与影像决定是否抗菌；<0.5 时强烈不推荐经验性抗菌"},{"when":"pct > 0.1","level":"ok","text":"PCT 0.1–0.5 ng/mL：细菌感染可能性低，提示病毒或非感染性炎症，可观察并动态复查"},{"when":"pct <= 0.1","level":"ok","text":"PCT ≤0.1 ng/mL：细菌感染可能性低，不推荐常规抗菌治疗（除非有明确感染灶与临床危重）"}],"note":"PCT 在术后 3 天内、严重创伤、烧伤、肾衰竭、自身免疫病、部分肿瘤及长时间休克时可假性升高；病毒性感染、局部感染可正常。<br>抗菌疗程可参考 PCT 下降 ≥80% 或 <0.5 ng/mL 作为停药助力，但不能单独停药。","refs":["降钙素原指导抗菌药物临床应用专家共识（2020）","拯救脓毒症运动（SSC）国际指南 2021（生物标志物部分）","IDSA 医院获得性肺炎/呼吸机相关肺炎指南 2016"]},{"id":"id_fuo_checklist","name":"发热待查（FUO）排查清单","aka":["FUO workup checklist","不明原因发热评估清单"],"cat":"诊断流程","rank":6,"desc":"按感染、结缔组织病、肿瘤三条主线勾选已完成的关键检查，帮助发现漏查项与下一步方向。","inputs":[{"key":"cultures","label":"完成 3 套血培养（不同部位/时间）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"imaging","label":"完成胸腹盆腔 CT 或 PET-CT","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"tb_igra","label":"完成 IGRA/T-SPOT 与胸片","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"autoimmune","label":"完成 ANA/ANCA/RF/补体/铁蛋白","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"tumor","label":"完成 LDH、肿瘤标志物与血涂片","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"biopsy","label":"完成骨髓穿刺/淋巴结活检（或已明确禁忌）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"drug_fever","label":"已排查药物热（回顾 3 周用药并停可疑药）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"hiv","label":"完成 HIV、HBV、HCV 筛查","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"已完成项数之和（0–8），不构成诊断评分","compute":"sum","interpret":[{"when":"v >= 8","level":"warn","text":"常规清单已全部完成而病因仍不明：考虑 mNGS、PET-CT 复查、专科活检或按病程线索试验性治疗，每 2–4 周复评"},{"when":"v >= 4","level":"warn","text":"部分完成：优先补做培养、影像与免疫学；发热 >3 周且指标升高者尽快 PET-CT"},{"when":"v < 4","level":"high","text":"关键检查缺口较多：先按感染→自身免疫→肿瘤顺序补齐基础检查，避免无方向治疗"}],"note":"清单用于结构化推进，不是诊断评分；对免疫抑制或近期旅行者需追加 CMV、PCP、布病、Q 热、登革等特定病原。","refs":["中国发热待查诊治专家共识 2017","不明原因发热诊断与治疗专家共识（2023 更新）"]},{"id":"id_septic_shock_check","name":"脓毒性休克判定（Sepsis-3 简化流程）","aka":["Septic shock criteria","感染性休克判定"],"cat":"脓毒症评估","rank":7,"desc":"以感染证据、广谱升压药需求、MAP 与乳酸水平判定是否达到脓毒性休克标准并指导复苏。","inputs":[{"key":"infection","label":"确诊或高度疑似感染","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"vasopressor","label":"充分液体复苏后仍需升压药维持 MAP ≥65 mmHg","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"lactate_high","label":"重复血乳酸 >2 mmol/L","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"sofa2","label":"SOFA 较基线急性升高 ≥2 分","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"脓毒性休克 = 感染 + 升压药依赖（MAP ≥65 mmHg）+ 乳酸 >2 mmol/L；脓毒症 = 感染 + SOFA 急性 +2","compute":"sum","interpret":[{"when":"infection == 1 && vasopressor == 1 && lactate_high == 1","level":"crit","text":"符合脓毒性休克：立即 1 h 集束化——乳酸复测、血培养、广谱抗菌药、30 mL/kg 晶体、去甲肾上腺素维持 MAP ≥65 mmHg，并行感染源控制"},{"when":"infection == 1 && sofa2 == 1","level":"high","text":"脓毒症（未达休克）：规范 1 h 集束化并密切监测乳酸与血压，若升压药需求出现再按休克处理"},{"when":"infection == 0","level":"warn","text":"无明确感染证据：寻找其他休克原因（心源、低血容量、梗阻、过敏、肾上腺危象），必要时经验性覆盖并复评"},{"when":"v >= 0","level":"ok","text":"未达脓毒症/脓毒性休克标准：按感染常规治疗，若病情恶化动态复评"}],"note":"乳酸 >2 mmol/L 需排除其他原因（癫痫、肝衰、双胍类、缺氧）；升压药剂量与乳酸水平决定风险分层，乳酸 >4 mmol/L 者病死率显著升高。","refs":["Sepsis-3 定义（JAMA 2016）","拯救脓毒症运动（SSC）国际指南 2021"]},{"id":"id_renal_dose_band","name":"抗菌药物肾功能调整参考（按 CrCl 分档）","aka":["Renal dose adjustment","肾功能不全抗菌药剂量"],"cat":"特殊人群用药","rank":8,"desc":"按 Cockcroft-Gault 肌酐清除率分档，给出常见抗菌药物调整幅度与高毒风险药物提示。","inputs":[{"key":"crcl","label":"肌酐清除率 CrCl（Cockcroft-Gault）","unit":"mL/min","type":"number","min":1,"max":200,"step":1,"required":true},{"key":"dialysis","label":"是否接受肾脏替代治疗","unit":"","type":"select","options":[{"value":1,"label":"是（HD/CRRT）"},{"value":0,"label":"否"}],"required":true}],"formula":"CrCl = (140−年龄)×体重(kg) / (0.818×Scr[μmol/L])，女性再 ×0.85；按 >50、30–50、10–30、<10 四档调整","compute":"formula_only","algorithm":"v = crcl","interpret":[{"when":"dialysis == 1","level":"crit","text":"肾脏替代治疗：美罗培南 0.5–1 g q8h（CRRT 1 g q8h 延长输注）；哌拉西林他唑巴坦 4.5 g q8h 延长输注（CRRT）；万古霉素按谷浓度 10–15 mg/L 给药；避免氨基糖苷类，优先按浓度监测"},{"when":"crcl < 10","level":"crit","text":"CrCl <10：美罗培南 0.5 g q24h；哌拉西林他唑巴坦 2.25 g q6h；恩替卡韦 0.05 mg qd；乙胺丁醇 15 mg/kg tiw；避免 TDF/TAF，头孢曲松无需调整"},{"when":"crcl < 30","level":"high","text":"CrCl 10–30：美罗培南 0.5 g q12h；哌拉西林他唑巴坦 2.25 g q6h；头孢他啶阿维巴坦 0.94 g q12h；奥司他韦 30 mg qd；多黏菌素 B 无需调整（多黏菌素 E 需减量）"},{"when":"crcl <= 50","level":"warn","text":"CrCl 30–50：美罗培南 1 g q12h；哌拉西林他唑巴坦 3.375 g q6h；头孢他啶阿维巴坦 1.25 g q8h；奥司他韦 30 mg bid；恩替卡韦 0.25 mg qd"},{"when":"crcl >= 0","level":"ok","text":"CrCl >50：按常规剂量给药，每 24–48 h 复查肾功能；使用万古霉素、氨基糖苷类、多黏菌素时常规监测血药浓度"}],"note":"肥胖或肌肉量异常者 CrCl 易高估（建议用去脂体重或测 24 h 肌酐清除率）；CRRT 与间歇 HD 剂量不同，需与药师协商；抗菌治疗开始 48–72 h 应复查肾功能并重新调整。","refs":["热病（The Sanford Guide to Antimicrobial Therapy）2024","药物说明书（美罗培南、哌拉西林他唑巴坦、万古霉素、恩替卡韦等）2023","KDIGO 急性肾损伤临床实践指南 2012"]},{"id":"id_igra_tb","name":"结核感染 IGRA/T-SPOT 判读与潜伏感染处置","aka":["IGRA","T-SPOT.TB","QuantiFERON","结核潜伏感染 LTBI"],"cat":"结核与潜伏感染","rank":9,"desc":"结合 IGRA/T-SPOT 结果、临床症状、影像与暴露史，判读结核感染状态并选择潜伏感染治疗方案。","inputs":[{"key":"igra","label":"IGRA/T-SPOT 结果","unit":"","type":"select","options":[{"value":2,"label":"阳性"},{"value":1,"label":"不确定/临界"},{"value":0,"label":"阴性"}],"required":true},{"key":"symptom","label":"有活动性结核症状（咳嗽 ≥2 周、低热、盗汗、消瘦）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"imaging","label":"胸片/CT 有活动性结核病灶","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"highrisk","label":"高危人群（HIV、免疫抑制、透析、矽肺、密切接触者）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"总分 = IGRA 分值 + 症状 + 影像 + 高危因素；用于分类活动性结核、潜伏感染（LTBI）与未感染","compute":"sum","interpret":[{"when":"symptom == 1 && imaging == 1","level":"crit","text":"疑似活动性肺结核：查痰抗酸染色 3 次+培养+GeneXpert MTB/RIF，按 2HRZE/4HR 规范治疗并报告传染病"},{"when":"igra == 2 && highrisk == 1","level":"high","text":"IGRA 阳性+高危：诊断为潜伏结核感染（LTBI），优先 6H（异烟肼 300 mg qd 6 个月）或 3HP（异烟肼+利福喷丁按体重 weekly ×3 个月），排除活动性后再启动预防性治疗"},{"when":"igra == 2","level":"warn","text":"IGRA 阳性、无活动性证据：考虑 LTBI，评估预防性治疗获益（年龄、肝病、经济与社会因素），必要时 6H 或 3HP"},{"when":"igra == 1","level":"warn","text":"IGRA 不确定：可 4–8 周后复查，同时结合 PPD、影像与暴露史，不据此启动治疗"},{"when":"igra == 0","level":"ok","text":"IGRA 阴性：不支持结核感染；免疫抑制者存在假阴性，需结合临床与影像"}],"note":"IGRA 不能区分活动性与潜伏感染，也不能评估疗效；BCG 接种不影响结果，但类固醇/免疫抑制可致假阴性。LTBI 治疗前必须排除活动性结核并监测肝功能。","refs":["中国结核病预防控制工作技术规范（2020 年版）","结核分枝杆菌潜伏感染诊治专家共识（2020）","WHO Guidelines on Latent TB Infection 2020"]},{"id":"id_hiv_stage_cdc","name":"HIV 感染 CDC 分期（2014）","aka":["CDC HIV staging","HIV 分期","CD4 分期"],"cat":"病毒与免疫","rank":10,"desc":"按 CD4⁺ T 淋巴细胞计数分 3 档、结合机会性感染/肿瘤等临床分期判据，判定 HIV 感染的 CDC 分期（0、1、2、3 及未知）。","inputs":[{"key":"cd4","label":"CD4⁺ T 淋巴细胞计数","unit":"cells/μL","type":"number","min":0,"max":2000,"step":1,"required":true},{"key":"aids_def","label":"有 AIDS 指征性疾病（机会性感染/肿瘤，如 PCP、食管念珠菌、弓形虫脑病、卡波西肉瘤、淋巴瘤）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true},{"key":"acute","label":"当前处于急性 HIV 感染期（血清阴转期，抗体初筛阳性/核酸阳性）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"CD4 ≥500 → 1 期；200–499 → 2 期；<200 → 3 期（AIDS）；出现 AIDS 指征性疾病即为 3 期，CD4 恢复后仍维持诊断分期","compute":"formula_only","algorithm":"v = cd4\nif acute == 1: stage = '0'\nelse if aids_def == 1 || cd4 < 200: stage = '3'\nelse if cd4 >= 500: stage = '1'\nelse: stage = '2'","interpret":[{"when":"acute == 1","level":"crit","text":"CDC 0 期：急性 HIV 感染，病毒载量高、传染性强，应立即启动 ART 并完成基线检测（CD4、RNA、耐药、HLA-B*5701、结核及性病筛查）"},{"when":"aids_def == 1 || cd4 < 200","level":"crit","text":"CDC 3 期 / AIDS：启动 ART，并行 PCP 预防（TMP-SMX 960 mg qd，CD4 <200 或口咽念珠菌），弓形虫预防（CD4 <100），必要时 MAC 预防；定期筛查结核、CMV 视网膜病变"},{"when":"cd4 < 500","level":"warn","text":"CDC 2 期：CD4 200–499，加强 ART 依从与免疫重建随访，注意机会性感染筛查"},{"when":"cd4 >= 500","level":"ok","text":"CDC 1 期：CD4 ≥500，启动 ART，目标病毒载量 <50 copies/mL，规范随访（每 3–6 个月 CD4 与病毒载量）"}],"note":"AIDS 指征性疾病一旦出现即终身维持 3 期（即使 CD4 恢复）；CD4 分档应与病毒载量联合评估，ART 后每 3–6 个月复查；需注意 IRIS（免疫重建炎症综合征）。","refs":["中国艾滋病诊疗指南（2021 年版）","CDC Revised Surveillance Case Definition for HIV Infection 2014","WHO Consolidated Guidelines on HIV 2021"]},{"id":"id_exposure_pep","name":"狂犬病/血源性病原体暴露后分级与处置","aka":["Rabies PEP","狂犬病暴露分级","职业暴露后处置","PEP"],"cat":"暴露后处置","rank":11,"desc":"按暴露方式与皮损程度对狂犬病暴露分级，决定伤口处理、狂犬病疫苗与狂犬病免疫球蛋白（RIG）的使用；同型模板亦可用于血源性病原体职业暴露（HIV、HBV、HCV）的风险分层。","inputs":[{"key":"contact","label":"暴露方式","unit":"","type":"select","options":[{"value":3,"label":"单处或多处贯穿性咬伤/抓伤（皮肤破损、出血）、黏膜被唾液污染"},{"value":2,"label":"裸露皮肤被轻咬、无出血的轻微抓伤或擦伤"},{"value":1,"label":"接触/喂养动物、完好的皮肤被舔"},{"value":0,"label":"血源暴露（针刺伤、血液/体液溅入黏膜）"}],"required":true},{"key":"source_hiv","label":"（血源暴露时）源患者 HIV 阳性","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/不适用"}],"required":true}],"formula":"狂犬病暴露分级：Ⅰ级无需处置；Ⅱ级处理伤口+全程疫苗；Ⅲ级处理伤口+全程疫苗+狂犬病免疫球蛋白","compute":"formula_only","algorithm":"v = contact\nif contact == 3: PEP3\nelse if contact == 2: PEP2\nelse if contact == 1: none\nelse if contact == 0 and source_hiv == 1: HIV PEP","interpret":[{"when":"contact == 3","level":"crit","text":"Ⅲ级暴露：立即冲洗伤口 15 min（肥皂水/络合碘），按体重 20 IU/kg 在伤口周围浸润注射狂犬病免疫球蛋白（剩余量肌注），并接种 5 剂疫苗（0、3、7、14、28 天）或 2-1-1 方案（第 0 天 2 剂，第 7、21 天各 1 剂）"},{"when":"contact == 2","level":"warn","text":"Ⅱ级暴露：处理伤口并全程接种狂犬病疫苗（5 剂或 2-1-1 方案），不需要免疫球蛋白；若暴露者免疫功能低下升级为Ⅲ级处置"},{"when":"contact == 1","level":"ok","text":"Ⅰ级暴露：无感染风险，不需处置，清洗暴露部位"},{"when":"contact == 0 && source_hiv == 1","level":"crit","text":"HIV 职业暴露：立即基线检测并 2 h 内（最迟 72 h 内）启动三联 PEP，如 TDF 300 mg qd + 拉替拉韦 400 mg bid（或杜鲁特韦 50 mg qd）+ 拉米夫定 300 mg qd，全程 28 天"},{"when":"contact == 0","level":"warn","text":"血源暴露：无需狂犬病处置；按病原分型处理（HBV 暴露需 HBIG + 疫苗，HCV 暴露随访 HCV RNA）"}],"note":"本条目以狂犬病暴露分级为主体，同时给出职业暴露（针刺伤）同型处置模板；狂犬病一旦发病病死率近 100%，无禁忌证时疫苗与 RIG 不应延迟。<br>疫苗常见 2-1-1 与 5 剂两种程序，按当地疾控供应方案执行。<br>血源暴露 HBV：未接种者 6 个月内 HBIG + 乙肝疫苗；HCV 暴露 4–6 周查 HCV RNA。","refs":["狂犬病预防控制技术指南（2016 年版，中国疾控中心）","狂犬病暴露预防处置工作规范（2023 年版）","血源性病原体职业接触防护导则（GBZ/T 213-2008）","中国艾滋病诊疗指南（2021 年版，暴露后预防部分）"]}]},"neuro":{"items":[{"id":"neuro_nihss","name":"美国国立卫生研究院卒中量表（NIHSS）","aka":["NIHSS","NIH Stroke Scale"],"cat":"卒中评估","rank":1,"desc":"量化急性卒中神经功能缺损程度，判断溶栓与取栓适宜性。","inputs":[{"key":"loc","label":"意识水平","unit":"","type":"select","options":[{"value":0,"label":"0 清醒"},{"value":1,"label":"1 嗜睡"},{"value":2,"label":"2 昏睡"},{"value":3,"label":"3 昏迷"}],"required":true},{"key":"loc_q","label":"意识水平问答","unit":"","type":"select","options":[{"value":0,"label":"0 均正确"},{"value":1,"label":"1 答对一项"},{"value":2,"label":"2 均错误"}],"required":true},{"key":"loc_c","label":"意识水平指令","unit":"","type":"select","options":[{"value":0,"label":"0 均完成"},{"value":1,"label":"1 完成一项"},{"value":2,"label":"2 均不能"}],"required":true},{"key":"gaze","label":"凝视","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1 部分注视麻痹"},{"value":2,"label":"2 强迫性眼位偏斜"}],"required":true},{"key":"visual","label":"视野","unit":"","type":"select","options":[{"value":0,"label":"0 无缺损"},{"value":1,"label":"1 部分偏盲"},{"value":2,"label":"2 完全偏盲"},{"value":3,"label":"3 双侧偏盲"}],"required":true},{"key":"facial","label":"面瘫","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1 轻瘫"},{"value":2,"label":"2 部分瘫"},{"value":3,"label":"3 完全瘫"}],"required":true},{"key":"arm_motor","label":"左上肢运动（近端）","unit":"","type":"select","options":[{"value":0,"label":"0 不下坠"},{"value":1,"label":"1 下坠但不落床"},{"value":2,"label":"2 下坠至床"},{"value":3,"label":"3 不能抗重力"},{"value":4,"label":"4 无运动"}],"required":true},{"key":"arm_motor_r","label":"右上肢运动（近端）","unit":"","type":"select","options":[{"value":0,"label":"0 不下坠"},{"value":1,"label":"1 下坠但不落床"},{"value":2,"label":"2 下坠至床"},{"value":3,"label":"3 不能抗重力"},{"value":4,"label":"4 无运动"}],"required":true},{"key":"leg_motor","label":"左下肢运动","unit":"","type":"select","options":[{"value":0,"label":"0 不下坠"},{"value":1,"label":"1 下坠但不落床"},{"value":2,"label":"2 下坠至床"},{"value":3,"label":"3 不能抗重力"},{"value":4,"label":"4 无运动"}],"required":true},{"key":"leg_motor_r","label":"右下肢运动","unit":"","type":"select","options":[{"value":0,"label":"0 不下坠"},{"value":1,"label":"1 下坠但不落床"},{"value":2,"label":"2 下坠至床"},{"value":3,"label":"3 不能抗重力"},{"value":4,"label":"4 无运动"}],"required":true},{"key":"ataxia","label":"共济失调","unit":"","type":"select","options":[{"value":0,"label":"0 无"},{"value":1,"label":"1 一个肢体"},{"value":2,"label":"2 两个肢体"}],"required":true},{"key":"sensory","label":"感觉","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1 轻中度丧失"},{"value":2,"label":"2 重度/完全丧失"}],"required":true},{"key":"language","label":"语言","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1 轻中度失语"},{"value":2,"label":"2 重度失语"},{"value":3,"label":"3 缄默/完全失语"}],"required":true},{"key":"dysarthria","label":"构音障碍","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1 轻度"},{"value":2,"label":"2 重度/不能理解"}],"required":true},{"key":"neglect","label":"忽视","unit":"","type":"select","options":[{"value":0,"label":"0 无"},{"value":1,"label":"1 一种感觉忽视"},{"value":2,"label":"2 多种/严重忽视"}],"required":true}],"formula":"15 项相加，总分 0–42","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"轻度（0–4）：多为小卒中或 TIA 边缘，仍依影像评估再灌注治疗"},{"when":"v >= 5 && v <= 15","level":"warn","text":"中度（5–15）：适合静脉溶栓评估；前循环大血管闭塞考虑取栓"},{"when":"v >= 16 && v <= 20","level":"high","text":"中重度（16–20）：出血转化与预后不良风险升高"},{"when":"v >= 21","level":"crit","text":"重度（≥ 21）：严重缺损，评估大面积梗死与脑水肿，谨慎溶栓"}],"note":"评分需按标准顺序（意识→凝视→视野→面瘫→运动→共济→感觉→语言→构音→忽视）；尽可能取首评前 1.5–3 h 时间；昏迷患者运动项可能无法完整评估。","refs":["中国急性缺血性脑卒中诊治指南（2023）","AHA/ASA Guidelines for Early Management of AIS (2019)"]},{"id":"neuro_gcs","name":"格拉斯哥昏迷评分（GCS）","aka":["GCS","Glasgow Coma Scale"],"cat":"意识与病情","rank":2,"desc":"评估意识障碍程度，用于创伤、卒中、昏迷患者的病情监测。","inputs":[{"key":"eye","label":"睁眼 E","unit":"","type":"select","options":[{"value":4,"label":"4 自发睁眼"},{"value":3,"label":"3 呼唤睁眼"},{"value":2,"label":"2 疼痛刺激睁眼"},{"value":1,"label":"1 无睁眼"}],"required":true},{"key":"verbal","label":"语言 V","unit":"","type":"select","options":[{"value":5,"label":"5 定向正确"},{"value":4,"label":"4 胡言乱语"},{"value":3,"label":"3 不恰当词汇"},{"value":2,"label":"2 无法理解声音"},{"value":1,"label":"1 无发声"}],"required":true},{"key":"motor","label":"运动 M","unit":"","type":"select","options":[{"value":6,"label":"6 遵指令"},{"value":5,"label":"5 定位疼痛"},{"value":4,"label":"4 逃避疼痛"},{"value":3,"label":"3 屈曲（去皮质）"},{"value":2,"label":"2 伸展（去脑）"},{"value":1,"label":"1 无运动"}],"required":true},{"key":"intubated","label":"是否气管插管","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（V 计为 1T）"}],"required":true}],"formula":"GCS = E + V + M（3–15）","compute":"sum","interpret":[{"when":"v <= 8","level":"crit","text":"GCS ≤ 8：重度昏迷，考虑气管插管保护气道，急查头颅影像与病因"},{"when":"v >= 9 && v <= 12","level":"high","text":"中度意识障碍（9–12），加强监护，复查影像与脑电"},{"when":"v >= 13 && v <= 14","level":"warn","text":"轻度意识障碍（13–14），警惕早期脑水肿或演变"},{"when":"v >= 15","level":"ok","text":"GCS 15：意识清楚"}],"note":"插管者语言项记为 1T；运动项最有预后价值；需动态记录（如瞳孔、血压、时间）。别名：GCS（与急诊/麻醉科同名算法，id 统一用 neuro_gcs）。","refs":["中国急性颅脑创伤救治指南（2020）","Teasdale G, Jennett B. Lancet 1974"]},{"id":"neuro_mrs","name":"改良 Rankin 量表（mRS）","aka":["mRS","modified Rankin Scale"],"cat":"功能结局","rank":3,"desc":"评估卒中后残疾程度，是卒中疗效主要终点指标。","inputs":[{"key":"mrs_grade","label":"分级","unit":"","type":"select","options":[{"value":0,"label":"0 完全无症状"},{"value":1,"label":"1 无明显残疾"},{"value":2,"label":"2 轻度残疾"},{"value":3,"label":"3 中度残疾"},{"value":4,"label":"4 中重度残疾"},{"value":5,"label":"5 重度残疾"},{"value":6,"label":"6 死亡"}],"required":true}],"formula":"直接选择分级 0–6","compute":"formula_only","algorithm":"v = mrs_grade","interpret":[{"when":"v <= 2","level":"ok","text":"mRS 0–2：功能独立（临床良好结局）"},{"when":"v == 3 || v == 4","level":"high","text":"mRS 3–4：残疾，需康复与护理支持"},{"when":"v >= 5","level":"crit","text":"mRS 5–6：重度残疾或死亡，评估长期照护与并发症"}],"note":"建议用结构化访谈（mRS-9Q）减少评估者差异；90 天 mRS 为急性卒中试验标准终点。","refs":["中国急性缺血性脑卒中诊治指南（2023）","AHA/ASA AIS Guidelines (2019)"]},{"id":"neuro_barthel","name":"Barthel 指数（BI）","aka":["BI","Barthel Index"],"cat":"功能结局","rank":8,"desc":"评估日常生活活动能力（ADL），用于康复与出院评估。","inputs":[{"key":"feeding","label":"进食","unit":"","type":"select","options":[{"value":10,"label":"10 独立"},{"value":5,"label":"5 需部分帮助"},{"value":0,"label":"0 依赖"}],"required":true},{"key":"bathing","label":"洗澡","unit":"","type":"select","options":[{"value":5,"label":"5 独立"},{"value":0,"label":"0 依赖"}],"required":true},{"key":"grooming","label":"修饰","unit":"","type":"select","options":[{"value":5,"label":"5 独立"},{"value":0,"label":"0 依赖"}],"required":true},{"key":"dressing","label":"穿衣","unit":"","type":"select","options":[{"value":10,"label":"10 独立"},{"value":5,"label":"5 部分"},{"value":0,"label":"0 依赖"}],"required":true},{"key":"bowels","label":"大便控制","unit":"","type":"select","options":[{"value":10,"label":"10 正常"},{"value":5,"label":"5 偶失禁"},{"value":0,"label":"0 失禁"}],"required":true},{"key":"bladder","label":"小便控制","unit":"","type":"select","options":[{"value":10,"label":"10 正常"},{"value":5,"label":"5 偶失禁"},{"value":0,"label":"0 失禁"}],"required":true},{"key":"toilet","label":"如厕","unit":"","type":"select","options":[{"value":10,"label":"10 独立"},{"value":5,"label":"5 部分"},{"value":0,"label":"0 依赖"}],"required":true},{"key":"transfer","label":"床椅转移","unit":"","type":"select","options":[{"value":15,"label":"15 独立"},{"value":10,"label":"10 部分"},{"value":5,"label":"5 需卧床"},{"value":0,"label":"0 完全依赖"}],"required":true},{"key":"mobility","label":"平地行走","unit":"","type":"select","options":[{"value":15,"label":"15 独立"},{"value":10,"label":"10 需帮助"},{"value":5,"label":"5 轮椅"},{"value":0,"label":"0 不能"}],"required":true},{"key":"stairs","label":"上下楼梯","unit":"","type":"select","options":[{"value":10,"label":"10 独立"},{"value":5,"label":"5 需帮助"},{"value":0,"label":"0 不能"}],"required":true}],"formula":"10 项相加，0–100","compute":"sum","interpret":[{"when":"v >= 100","level":"ok","text":"100：完全独立"},{"when":"v >= 61 && v < 100","level":"ok","text":"61–99：轻度依赖，可出院回归社区"},{"when":"v >= 41 && v <= 60","level":"warn","text":"41–60：中度依赖，需康复训练与部分护理"},{"when":"v >= 21 && v <= 40","level":"high","text":"21–40：重度依赖，加强护理与康复"},{"when":"v <= 20","level":"crit","text":"0–20：完全依赖，需长期照护"}],"note":"以实际（需帮助与否）而非能力计分；卒中急性期建议结合 mRS 与 NIHSS 共同评估。别名：Barthel（老年科另有 geriatric_barthel，算法一致）。","refs":["中国脑卒中康复治疗指南（2011/2016）","Mahoney FI, Barthel DW. Md State Med J 1965"]},{"id":"neuro_essen","name":"ESSEN 卒中风险评分","aka":["ESRS","Essen Stroke Risk Score"],"cat":"卒中评估","rank":10,"desc":"评估非心源性缺血性卒中复发风险，用于二级预防强度决策。","inputs":[{"key":"age_75","label":"年龄 ≥ 75 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age_65","label":"年龄 65–74 岁（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"htn","label":"高血压（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"dm","label":"糖尿病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"mi","label":"心肌梗死史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"pad","label":"周围动脉病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"tia","label":"既往 TIA/卒中以外的卒中史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"other_cardiac","label":"其他心脏病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"各项相加，0–6 分","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"ESSEN ≥ 3：卒中复发高风险，强化二级预防（双联抗血小板、强化降脂）"},{"when":"v >= 1 && v <= 2","level":"warn","text":"ESSEN 1–2：中风险"},{"when":"v == 0","level":"ok","text":"ESSEN 0：低风险"}],"note":"年龄项按原量表为 65–75 岁 +1、≥ 75 岁 +2；本表拆为两个互斥选项输入。仅适用非心源性卒中。","refs":["中国缺血性卒中和短暂性脑缺血发作二级预防指南（2022）","Weimar C, et al. Stroke 2009"]},{"id":"neuro_abcd2","name":"ABCD² 评分（TIA 后卒中风险）","aka":["ABCD2","TIA 风险评分"],"cat":"卒中评估","rank":4,"desc":"预测短暂性脑缺血发作后 2/7/90 天内卒中风险。","inputs":[{"key":"age","label":"年龄 ≥ 60 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bp","label":"血压 ≥ 140/90 mmHg（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"clinical","label":"临床表现","unit":"","type":"select","options":[{"value":0,"label":"0 其他症状"},{"value":1,"label":"1 言语障碍（无肢体无力）"},{"value":2,"label":"2 单侧肢体无力"}],"required":true},{"key":"duration","label":"持续时间","unit":"","type":"select","options":[{"value":0,"label":"0 <10 min"},{"value":1,"label":"1 10–59 min"},{"value":2,"label":"2 ≥60 min"}],"required":true},{"key":"dm","label":"糖尿病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"ABCD² = 年龄 + 血压 + 临床 + 持续时间 + 糖尿病（0–7）","compute":"sum","interpret":[{"when":"v >= 6","level":"crit","text":"6–7 分：高危，2 天内卒中风险约 8%；应急诊评估、立即抗血小板与血管评估"},{"when":"v >= 4 && v <= 5","level":"high","text":"4–5 分：中危，推荐 24–48 h 内评估，启动双联抗血小板 21 天"},{"when":"v <= 3","level":"ok","text":"0–3 分：低危，尽早门诊评估并完成血管影像"}],"note":"ABCD² 对颈动脉狭窄、串联病变敏感性有限，不能替代影像（ABCD³-I）；发作次数与 DWI 阳性为重要补充。","refs":["中国缺血性卒中和短暂性脑缺血发作二级预防指南（2022）","AHA/ASA Definition and Evaluation of TIA (2009)"]},{"id":"neuro_chads2","name":"CHADS₂ 评分（房颤卒中风险）","aka":["CHADS2","CHADS₂"],"cat":"卒中评估","rank":17,"desc":"评估非瓣膜性房颤患者卒中风险，历史评分，现多用 CHA₂DS₂-VASc。","inputs":[{"key":"chf","label":"充血性心衰（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"htn","label":"高血压（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age75","label":"年龄 ≥ 75 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"dm","label":"糖尿病（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stroke","label":"卒中/TIA 史（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true}],"formula":"CHADS₂ = CHF + HTN + 年龄≥75 + DM + 2×卒中史（0–6）","compute":"sum","interpret":[{"when":"v >= 2","level":"high","text":"≥ 2 分：卒中高风险，推荐口服抗凝（NOAC 优先或华法林 INR 2–3）"},{"when":"v == 1","level":"warn","text":"1 分：中风险，结合 CHA₂DS₂-VASc 与出血风险决定抗凝"},{"when":"v == 0","level":"ok","text":"0 分：低风险，可不抗凝"}],"note":"已由 CHA₂DS₂-VASc 取代；CHA₂DS₂-VASc 与 HAS-BLED 见心内科（cardio）条目，本处为别名入口。","refs":["心房颤动诊断和治疗中国指南（2023）","ACC/AHA/ACCP/HRS Atrial Fibrillation Guideline (2023)"]},{"id":"neuro_hasbled_alias","name":"HAS-BLED 出血风险评分（别名入口）","aka":["HAS-BLED","出血风险"],"cat":"卒中评估","rank":18,"desc":"抗凝治疗出血风险评估；实现已在心内科文件，本条目作为神经科检索入口。","inputs":[{"key":"htn","label":"未控制高血压（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"renal","label":"肾功能异常（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"liver","label":"肝功能异常（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stroke","label":"卒中史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"bleed","label":"出血史/易出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"inr","label":"INR 不稳定（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"age","label":"年龄 > 65 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"drug","label":"药物（抗血小板/NSAIDs）（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"alcohol","label":"饮酒过量（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"HAS-BLED 9 项相加，0–9","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"≥ 3 分：出血高危，纠正可逆因素并密切随访，不应因评分高而停用抗凝"},{"when":"v >= 1 && v <= 2","level":"warn","text":"1–2 分：中危，规律随访"},{"when":"v == 0","level":"ok","text":"0 分：低出血风险"}],"note":"本表与心内科 cardio 文件中的 has_bled 为同一量表（别名 has_bled），合并时以 cardio 版本为准。","refs":["心房颤动诊断和治疗中国指南（2023）","Pisters R, et al. Chest 2010"]},{"id":"neuro_abcd3i","name":"ABCD³-I 评分（TIA 后 7 天卒中风险）","aka":["ABCD3-I","ABCD³-I"],"cat":"卒中评估","rank":11,"desc":"在 ABCD² 基础上加入双重 TIA、同侧颈动脉狭窄与 DWI 高信号。","inputs":[{"key":"abcd2","label":"ABCD² 总分（0–7）","unit":"","type":"number","min":0,"max":7,"step":1,"required":true},{"key":"dual_tia","label":"7 天内双重 TIA（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"carotid","label":"同侧颈动脉狭窄 ≥ 50%（+2）","unit":"","type":"select","options":[{"value":0,"label":"否/未知"},{"value":2,"label":"是"}],"required":true},{"key":"dwi","label":"DWI 高信号（+2）","unit":"","type":"select","options":[{"value":0,"label":"否/未查"},{"value":2,"label":"是"}],"required":true}],"formula":"ABCD³-I = ABCD² + 2×双重 TIA + 2×颈动脉狭窄≥50% + 2×DWI 阳性（0–13）","compute":"sum","interpret":[{"when":"v >= 8","level":"crit","text":"≥ 8 分：7 天卒中风险高，建议住院或急诊留观，尽快完成 CTA/MRA 与心电监测"},{"when":"v >= 4 && v < 8","level":"high","text":"4–7 分：中高危，48 h 内完成评估并启动抗血小板"},{"when":"v < 4","level":"ok","text":"< 4 分：低危，门诊尽快评估"}],"note":"需颅脑 MRI DWI 与颈部血管影像，故基层可用 ABCD² 先行；颈动脉狭窄 ≥ 50% 应考虑 CEA/CAS。","refs":["中国缺血性卒中和短暂性脑缺血发作二级预防指南（2022）","Engelter ST, et al. Neurology 2012"]},{"id":"neuro_thrombolysis_ck","name":"静脉溶栓禁忌与注意事项清单","aka":["rt-PA 溶栓 checkList","阿替普酶禁忌证"],"cat":"卒中评估","rank":9,"desc":"按条目勾选，汇总相对/绝对禁忌，提示溶栓决策（公式仅为计数参考）。","inputs":[{"key":"ich_history","label":"既往颅内出血史","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有（绝对禁忌）"}],"required":true},{"key":"ct_hemorrhage","label":"CT 示颅内出血或大面积低密度","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有（绝对禁忌）"}],"required":true},{"key":"bp_high","label":"血压 > 185/110 mmHg（可降至 185/110 以下）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（相对，需降压后复评）"}],"required":true},{"key":"platelet","label":"血小板 < 100×10⁹/L","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（禁忌）"}],"required":true},{"key":"inr","label":"INR > 1.7 或服用华法林","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（禁忌）"}],"required":true},{"key":"doac","label":"48 h 内服用新型口服抗凝药","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（按机构流程评估）"}],"required":true},{"key":"recent_surgery","label":"3 周内大手术或 2 周内穿刺","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（相对/禁忌）"}],"required":true},{"key":"glu_abnormal","label":"血糖 < 2.8 或 > 22.2 mmol/L","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是（先纠正）"}],"required":true},{"key":"time_ok","label":"发病 4.5 h 内（替奈普酶/阿替普酶适应证）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"禁忌项计数；具体剂量见指南（阿替普酶 0.9 mg/kg，最大 90 mg）","compute":"sum","interpret":[{"when":"ich_history == 1 || ct_hemorrhage == 1 || platelet == 1 || inr == 1","level":"crit","text":"存在绝对禁忌：禁止静脉溶栓，评估机械取栓"},{"when":"time_ok == 0","level":"crit","text":"超出时间窗：4.5 h 外需按影像（灌注不匹配）评估桥接或取栓"},{"when":"recent_surgery == 1 && v <= 2","level":"high","text":"相对禁忌：多学科评估获益与出血风险"},{"when":"bp_high == 1","level":"warn","text":"血压超限：先降压至 < 185/110 mmHg 再复评"},{"when":"v == 0","level":"ok","text":"未发现明显禁忌，按指南进行溶栓（需 complete 影像、凝血、血糖、NIHSS 评估）"}],"note":"剂量：阿替普酶 0.9 mg/kg（最大 90 mg），10% 1 min 静推其余 1 h 泵入；替奈普酶 0.25 mg/kg 单次推注（最大 25 mg）。溶栓 24 h 内不用抗血小板/抗凝。","refs":["中国急性缺血性脑卒中诊治指南（2023）","AHA/ASA AIS Guidelines (2019)"]},{"id":"neuro_ich_score","name":"脑出血 ICH 评分","aka":["ICH Score","原发性脑出血预后评分"],"cat":"脑出血","rank":12,"desc":"预测自发性脑出血 30 天死亡率。","inputs":[{"key":"gcs","label":"GCS","unit":"","type":"select","options":[{"value":0,"label":"13–15（0）"},{"value":1,"label":"5–12（1）"},{"value":2,"label":"3–4（2）"}],"required":true},{"key":"age","label":"年龄 ≥ 80 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"volume","label":"血肿体积 ≥ 30 mL（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ivh","label":"脑室内出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"infratentorial","label":"幕下出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"ICH = GCS 档 + 年龄≥80 + 体积≥30 mL + IVH + 幕下（0–6）","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"5–6 分：30 天死亡率极高（> 60%），评估外科指征与家属沟通"},{"when":"v == 4","level":"crit","text":"4 分：30 天死亡率约 65%，考虑监护与部分外科干预"},{"when":"v == 3","level":"high","text":"3 分：30 天死亡率约 40%，评估引流与止血治疗"},{"when":"v == 2","level":"warn","text":"2 分：30 天死亡率约 26%"},{"when":"v <= 1","level":"ok","text":"0–1 分：30 天死亡率约 0–13%，积极保守治疗"}],"note":"血肿体积用 ABC/2 法估算；ICH 评分未纳入血糖与出血扩展，需结合临床；抗凝相关出血预后更差。","refs":["中国脑出血诊治指南（2019）","Hemphill JC, et al. Stroke 2001 (ICH Score)"]},{"id":"neuro_mich","name":"mICH 预后评分","aka":["mICH","Modified ICH Score"],"cat":"脑出血","rank":16,"desc":"改良 ICH 评分，包含 GCS 与 NIHSS 双项，预测 90 天功能结局。","inputs":[{"key":"age","label":"年龄 ≥ 80 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"gcs","label":"GCS 3–4（+2）/ 5–12（+1）","unit":"","type":"select","options":[{"value":0,"label":"13–15"},{"value":1,"label":"5–12"},{"value":2,"label":"3–4"}],"required":true},{"key":"nihss","label":"NIHSS","unit":"","type":"select","options":[{"value":0,"label":"<10"},{"value":1,"label":"10–19"},{"value":2,"label":"≥20"}],"required":true},{"key":"volume","label":"血肿体积 ≥ 30 mL（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ivh","label":"脑室内出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"infratentorial","label":"幕下出血（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"mICH = 年龄 + GCS + NIHSS + 体积 + IVH + 幕下（0–7）","compute":"sum","interpret":[{"when":"v >= 6","level":"crit","text":"6–7 分：90 天极差结局风险高（mRS 5–6 约 90%+）"},{"when":"v >= 4","level":"high","text":"4–5 分：90 天不良结局风险高，早期康复与外科评估"},{"when":"v <= 3","level":"ok","text":"0–3 分：90 天功能结局相对较好"}],"note":"mICH 将原始 ICH 评分的 GCS 细分并加入 NIHSS，对 90 天 mRS 0–3 预测优于原始 ICH；需同时可评分。","refs":["中国脑出血诊治指南（2019）","Chuang YC, et al. Stroke 2013"]},{"id":"neuro_hunt_hess","name":"Hunt-Hess 分级（蛛网膜下腔出血）","aka":["Hunt and Hess","HH 分级"],"cat":"脑血管病","rank":13,"desc":"评估动脉瘤性蛛网膜下腔出血的病情严重程度与手术风险。","inputs":[],"formula":"根据临床表现选择 0–5 级","compute":"formula_only","levels":[{"label":"0 级","criteria":"未破裂动脉瘤，无症状","level":"ok"},{"label":"Ⅰ 级","criteria":"无症状或仅有轻微头痛、轻度颈项强直","level":"ok"},{"label":"Ⅱ 级","criteria":"中度至重度头痛、颈项强直、颅神经麻痹（无意识障碍）","level":"warn"},{"label":"Ⅲ 级","criteria":"嗜睡、意识模糊、轻度局灶神经功能障碍","level":"high"},{"label":"Ⅳ 级","criteria":"昏睡、中重度偏瘫或早期去大脑强直","level":"crit"},{"label":"Ⅴ 级","criteria":"深昏迷、去大脑强直、濒死状态","level":"crit"}],"note":"Ⅰ–Ⅲ 级可早期夹闭/栓塞，Ⅳ–Ⅴ 级多延期手术或介入；Hunt-Hess 与 WFNS 鉴别：HH 更依赖主观描述，改良 HH 按意识与局灶分档。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2021）","AHA/ASA Management of Aneurysmal SAH (2023)"]},{"id":"neuro_wfns","name":"世界神经外科联盟分级（WFNS）","aka":["WFNS","WFNS grade"],"cat":"脑血管病","rank":14,"desc":"用 GCS 与局灶缺损对动脉瘤性 SAH 分级，优于 Hunt-Hess 的客观性。","inputs":[{"key":"gcs","label":"GCS","unit":"","type":"select","options":[{"value":1,"label":"15（无局灶缺损）"},{"value":2,"label":"13–14（无局灶缺损）"},{"value":3,"label":"13–14（有局灶缺损）"},{"value":4,"label":"7–12"},{"value":5,"label":"3–6"}],"required":true}],"formula":"按 GCS 与局灶缺损分 1–5 级","compute":"formula_only","algorithm":"v = gcs 选项值（1–5）","interpret":[{"when":"v == 1","level":"ok","text":"Ⅰ 级：可早期介入/夹闭"},{"when":"v == 2","level":"warn","text":"Ⅱ 级：可早期手术/介入，注意脑血管痉挛"},{"when":"v == 3","level":"high","text":"Ⅲ 级：考虑延期处理，ICU 监测"},{"when":"v == 4","level":"high","text":"Ⅳ 级：多为延期手术，评价脑积水与再出血风险"},{"when":"v == 5","level":"crit","text":"Ⅴ 级：极重度，多先保守治疗，评估挽救性措施"}],"note":"GCS 13–14 伴局灶缺损为Ⅲ 级，是 WFNS 与 Hunt-Hess 主要差异点；需与 Fisher 分级联合评估。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2021）","Teasdale GM, et al. J Neurosurg 1988 (WFNS)"]},{"id":"neuro_fisher","name":"Fisher 分级（改良 Fisher CT 分级）","aka":["Fisher grade","mFisher"],"cat":"脑血管病","rank":15,"desc":"依据 CT 上蛛网膜下腔积血范围预测脑血管痉挛风险。","inputs":[],"formula":"根据 CT 积血表现选择 1–4 级","compute":"formula_only","levels":[{"label":"1 级","criteria":"未见蛛网膜下腔出血痕迹","level":"ok"},{"label":"2 级","criteria":"弥漫性薄层出血（<1 mm），无血凝块","level":"warn"},{"label":"3 级","criteria":"局限性血块或厚层出血（≥1 mm）","level":"high"},{"label":"4 级","criteria":"脑实质内或脑室内积血（可伴弥漫性出血）","level":"crit"}],"note":"改良 Fisher 分级预测症状性脑血管痉挛：3 级风险约 33%、4 级约 40%；1–2 级 < 15%。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2021）","Claassen J, et al. Neurosurgery 2001 (mFisher)"]},{"id":"neuro_mmse","name":"简易精神状态检查（MMSE）","aka":["MMSE","Mini-Mental State Examination"],"cat":"认知评估","rank":5,"desc":"筛查总体认知功能，评估认知障碍严重程度。","inputs":[{"key":"orientation_time","label":"时间定向（年/季/月/日/星期）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"orientation_place","label":"地点定向（省/市/区/医院/楼层）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"registration","label":"即刻记忆（3 个词）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"attention","label":"注意力和计算（100−7 连续 5 次）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"recall","label":"延迟回忆（3 个词）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"naming","label":"命名（2 件物品）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"}],"required":true},{"key":"repetition","label":"复述（句子）","unit":"","type":"select","options":[{"value":0,"label":"0（错误）"},{"value":1,"label":"1（正确）"}],"required":true},{"key":"command","label":"三步指令","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"reading","label":"阅读（闭眼）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"}],"required":true},{"key":"writing","label":"书写（1 个完整句子）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"}],"required":true},{"key":"drawing","label":"图形复制（相交五边形）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"}],"required":true},{"key":"education","label":"受教育年限","unit":"年","type":"number","min":0,"max":30,"step":1,"required":true}],"formula":"各项相加，总分 0–30；教育程度校正：≤ 6 年者 +1（或按教育分层判读）","compute":"sum","interpret":[{"when":"v >= 27","level":"ok","text":"≥ 27（校正后）：认知正常范围"},{"when":"v >= 21 && v < 27","level":"warn","text":"21–26：轻度认知功能障碍可能，结合 MoCA 与教育程度"},{"when":"v >= 10 && v < 21","level":"high","text":"10–20：中度认知障碍"},{"when":"v < 10","level":"crit","text":"< 10：重度认知障碍，需评估照护能力与痴呆病因"}],"note":"判读需按教育程度校正（文盲 ≤ 17、小学 ≤ 20、中学及以上 ≤ 24 提示异常）；MMSE 对血管性痴呆和额叶功能敏感度低。老年科另有 geriatric_mmse 条目（同量表，别名）。","refs":["中国痴呆与认知障碍诊治指南（2015/2018）","Folstein MF, et al. J Psychiatr Res 1975"]},{"id":"neuro_moca","name":"蒙特利尔认知评估（MoCA）","aka":["MoCA","Montreal Cognitive Assessment"],"cat":"认知评估","rank":6,"desc":"筛查轻度认知障碍（MCI），对执行功能与视空间更敏感。","inputs":[{"key":"visuospatial","label":"视空间/执行（连线、立方体、钟表）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"naming","label":"命名（3 种动物）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"attention","label":"注意力（数字、字母）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"},{"value":6,"label":"6"}],"required":true},{"key":"language","label":"语言（句子复述、词语流畅）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"abstraction","label":"抽象（相似性）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"}],"required":true},{"key":"recall","label":"延迟回忆（5 个词）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"}],"required":true},{"key":"orientation","label":"定向（6 项）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5"},{"value":6,"label":"6"}],"required":true},{"key":"education","label":"受教育年限 ≤ 12 年（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"各项相加，0–30；教育 ≤ 12 年时 +1 分","compute":"sum","interpret":[{"when":"v >= 26","level":"ok","text":"≥ 26：认知功能正常范围"},{"when":"v >= 18 && v < 26","level":"warn","text":"18–25：MCI 可能，需神经心理全套与 ADL 评估"},{"when":"v < 18","level":"high","text":"< 18：认知障碍显著，评估痴呆病因与照护"}],"note":"北京版 MoCA 建议文盲 ≤ 13、小学 ≤ 19、初中及以上 ≤ 24 为异常；受教育与文化影响，判读以版本与教育分层为准。","refs":["中国痴呆与认知障碍诊治指南（2015/2018）","Nasreddine ZS, et al. J Am Geriatr Soc 2005"]},{"id":"neuro_cdr","name":"临床痴呆评定量表（CDR）","aka":["CDR","Clinical Dementia Rating"],"cat":"认知评估","rank":18,"desc":"按记忆、定向、判断、社会事务、家务、个人照料六项评定痴呆严重度。","inputs":[{"key":"memory","label":"记忆","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":0.5,"label":"0.5 可疑"},{"value":1,"label":"1 轻度"},{"value":2,"label":"2 中度"},{"value":3,"label":"3 重度"}],"required":true},{"key":"orientation","label":"定向力","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":0.5,"label":"0.5"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"judgement","label":"判断与解决问题","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":0.5,"label":"0.5"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"community","label":"社会事务","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":0.5,"label":"0.5"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"home","label":"家务与爱好","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":0.5,"label":"0.5"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true},{"key":"selfcare","label":"个人照料","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":0.5,"label":"0.5"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"}],"required":true}],"formula":"CDR 总分：记忆（M）为主要项，CDR 按「记忆分 + 其他项多数规则」确定","compute":"formula_only","algorithm":"M = memory\nothers = [orientation, judgement, community, home, selfcare]\n若 M==0: 若其他项>=2 项 ≥1 → 1；若 1 项 ≥1 且无 ≥2 → 0.5；否则 0\n若 M==0.5: 其他项多为 0 → 0.5；多数 ≥1 → 1\n若 M>=1: CDR = M（其余项多数低于 M 时可下调）\n具体按 CDR 标准化算法（Morris 1993）执行","interpret":[{"when":"memory == 0","level":"ok","text":"CDR 0：正常"},{"when":"memory >= 0.5 && memory < 1","level":"warn","text":"CDR 0.5：可疑痴呆，评估 MCI 与 AD 生物标志物"},{"when":"memory >= 1 && memory < 2","level":"high","text":"CDR 1：轻度痴呆，开始认知训练与药物治疗评估"},{"when":"memory >= 2","level":"crit","text":"CDR 2–3：中度/重度痴呆，需照护计划与行为症状管理"}],"note":"需根据知情者提供信息；记忆项权重最大；CDR 是痴呆分期最常用量表。算法需按标准化（boxes）执行，本页提供参考分。","refs":["中国痴呆与认知障碍诊治指南（2015/2018）","Morris JC. Neurology 1993"]},{"id":"neuro_npi","name":"神经精神症状问卷（NPI）","aka":["NPI","Neuropsychiatric Inventory"],"cat":"认知评估","rank":22,"desc":"由知情者报告评估 12 项痴呆行为心理症状的频率与严重度。","inputs":[{"key":"total_freq_sev","label":"12 项（频度×严重度）之和","unit":"","type":"number","min":0,"max":144,"step":1,"required":true},{"key":"caregiver_distress","label":"照护者痛苦总分（0–60）","unit":"","type":"number","min":0,"max":60,"step":1,"required":false}],"formula":"每项：频度 F（0–4）× 严重度 S（0–3）；总分 0–144","compute":"formula_only","algorithm":"v = total_freq_sev","interpret":[{"when":"v < 10","level":"ok","text":"< 10：无明显行为心理症状"},{"when":"v >= 10 && v < 30","level":"warn","text":"10–29：轻度症状，优先非药物干预"},{"when":"v >= 30 && v < 60","level":"high","text":"30–59：中度症状，评估诱因（疼痛、感染、环境），必要时精神科会诊"},{"when":"v >= 60","level":"crit","text":"≥ 60：重度症状，抗精神病药需谨慎（锥体外系、跌倒、死亡风险）"}],"note":"12 项含妄想、幻觉、激越、抑郁、焦虑、欣快、淡漠、脱抑制、易激惹、异常运动、夜间行为、食欲进食。照护者痛苦用于交流。","refs":["中国痴呆与认知障碍诊治指南（2015/2018）","Cummings JL, et al. Neurology 1994"]},{"id":"neuro_hachinski","name":"Hachinski 缺血指数量表","aka":["Hachinski Ischemia Score","缺血指数"],"cat":"认知评估","rank":20,"desc":"鉴别血管性痴呆与阿尔茨海默病。","inputs":[{"key":"abrupt","label":"急性起病（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"stepwise","label":"阶梯式恶化（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"fluct","label":"波动性病程（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"nocturnal","label":"夜间意识模糊（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"personality","label":"人格相对保留（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"depression","label":"抑郁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"somatic","label":"躯体主诉（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"emotion","label":"情感失控（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"htn","label":"高血压史（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stroke","label":"卒中史（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"atherosclerosis","label":"动脉粥样硬化证据（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"focal","label":"局灶神经症状（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"focal_sign","label":"局灶神经体征（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true}],"formula":"13 项加权求和，0–18","compute":"sum","interpret":[{"when":"v >= 7","level":"high","text":"≥ 7 分：支持血管性痴呆，评估脑血管影像与危险因素"},{"when":"v >= 4 && v < 7","level":"warn","text":"4–6 分：混合性痴呆可能"},{"when":"v < 4","level":"ok","text":"≤ 4 分：支持阿尔茨海默病等原发神经变性病"}],"note":"原量表满分 18；改良 Hachinski 可加 MRI 项（白质病变、梗死灶）；需与临床影像综合分析。","refs":["中国痴呆与认知障碍诊治指南（2015/2018）","Hachinski VC, et al. Arch Neurol 1975"]},{"id":"neuro_snoop4","name":"头痛 SNOOP4 红旗征","aka":["SNOOP4","头痛危险信号"],"cat":"头痛","rank":7,"desc":"筛查继发性头痛的危险信号，指导影像与腰椎穿刺决策。","inputs":[{"key":"s","label":"全身症状/疾病（发热、体重下降、HIV、肿瘤）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"n","label":"神经功能缺损或脑病","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"o","label":"突发雷击样头痛（<1 min 达峰）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"older","label":"年龄 > 50 岁新发头痛","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pattern","label":"头痛模式改变或进行性加重","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"positional","label":"体位性/咳嗽用力加重","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"papilledema","label":"视乳头水肿","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pregnancy","label":"妊娠/产褥期，或伴发自身免疫病","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"painful","label":"疼痛性眼肌麻痹或全身性表现","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"post_trauma","label":"头部外伤后新发头痛","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"immune","label":"免疫抑制或恶性肿瘤病史","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"drug","label":"止痛药过度使用","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"红旗项计数（0–12）","compute":"sum","interpret":[{"when":"s == 1 || n == 1 || o == 1","level":"crit","text":"存在重大红旗（突发/神经缺损/全身疾病）：急诊头颅 CT/CTA，排除 SAH、静脉窦血栓、感染"},{"when":"papilledema == 1","level":"crit","text":"视乳头水肿：考虑颅高压，行影像（MRV 排除静脉窦血栓）与腰穿测压"},{"when":"pregnancy == 1","level":"crit","text":"妊娠/产褥期头痛：优先排除子痫前期与脑静脉窦血栓"},{"when":"v >= 1","level":"warn","text":"存在红旗征：建议影像学检查或专科评估"},{"when":"v == 0","level":"ok","text":"无红旗征：可按原发性头痛（偏头痛/紧张型）处理并随访"}],"note":"SNOOP4 为头痛继发性病因筛查框架；新发头痛 + 年龄 > 50 岁需排查巨细胞动脉炎（ESR、颞动脉超声）。","refs":["中国头痛诊治指南（偏头痛，2022）","ICHD-3 国际头痛疾病分类（2018）","Do TP, et al. Cephalalgia 2019 (SNOOP4)"]},{"id":"neuro_csf","name":"脑脊液判读（常规/生化/细胞）","aka":["CSF 判读","腰椎穿刺结果判读"],"cat":"脑脊液","rank":19,"desc":"根据细胞数、蛋白、糖与压力区分化脑、结脑、病毒性脑炎与 SAH 等。","inputs":[{"key":"opening_pressure","label":"开放压","unit":"mmH2O","type":"number","min":40,"max":600,"step":1,"required":true},{"key":"wbc","label":"白细胞数","unit":"×10⁶/L","type":"number","min":0,"max":20000,"step":1,"required":true},{"key":"pmn_pct","label":"多核（中性）比例","unit":"%","type":"number","min":0,"max":100,"step":1,"required":true},{"key":"protein","label":"蛋白","unit":"g/L","type":"number","min":0.1,"max":10,"step":0.01,"required":true},{"key":"glucose_ratio","label":"脑脊液糖/血糖比值","unit":"","type":"number","min":0,"max":2,"step":0.01,"required":true}],"formula":"按压力、白细胞数、细胞分类、蛋白、糖比值综合判读","compute":"formula_only","algorithm":"v = wbc；依据 wbc、pmn_pct、protein、glucose_ratio、opening_pressure 组合给出影像学鉴别","interpret":[{"when":"wbc >= 1000 && pmn_pct >= 80 && glucose_ratio < 0.4","level":"crit","text":"化脑模式：中性粒细胞为主、糖显著降低、蛋白高，立即经验性抗菌（头孢曲松 + 万古霉素，剂量按说明书/指南）"},{"when":"wbc >= 50 && pmn_pct < 50 && glucose_ratio < 0.5 && protein > 1.0","level":"high","text":"结脑模式：淋巴细胞为主、糖低、蛋白显著高，查抗酸染色、T-SPOT、Xpert MTB/RIF"},{"when":"wbc >= 10 && wbc < 500 && pmn_pct < 50 && glucose_ratio >= 0.6","level":"warn","text":"病毒性脑炎/脑膜炎模式：淋巴细胞为主、糖正常，查 HSV/PCR，考虑阿昔洛韦"},{"when":"opening_pressure > 200","level":"high","text":"颅内压升高，警惕脑疝风险，行头颅影像后再腰穿"},{"when":"wbc < 5 && protein < 0.45 && glucose_ratio >= 0.6","level":"ok","text":"脑脊液基本正常；但不能完全排除早期中枢感染"}],"note":"正常开放压 80–180 mmH2O（侧卧位）、白细胞 < 5×10⁶/L、蛋白 0.15–0.45 g/L、糖为血糖的 50–70%；腰穿禁忌含颅内占位、后颅窝病变与明显颅高压。","refs":["中国中枢神经系统细菌性感染诊治专家共识（2017）","中国结核性脑膜炎诊治专家共识（2019）"]},{"id":"neuro_avpu","name":"意识水平快速评估（AVPU）","aka":["AVPU","Alert Verbal Painful Unresponsive"],"cat":"意识与病情","rank":21,"desc":"急诊与院前快速分级意识状态，替代 GCS 的简化版本。","inputs":[{"key":"avpu","label":"意识状态","unit":"","type":"select","options":[{"value":1,"label":"A 清醒"},{"value":2,"label":"V 对声音有反应"},{"value":3,"label":"P 对疼痛有反应"},{"value":4,"label":"U 无反应"}],"required":true}],"formula":"四级分类 A/V/P/U","compute":"formula_only","algorithm":"v = avpu","interpret":[{"when":"v == 1","level":"ok","text":"A：清醒，可进一步评估 NIHSS/GCS"},{"when":"v == 2","level":"warn","text":"V：仅对声音反应，警惕意识障碍进展，监测 GCS/瞳孔"},{"when":"v >= 3","level":"crit","text":"P/U：对疼痛或无反应，气道保护与快速病因评估（血糖、影像、脑疝征象）"}],"note":"AVPU 用于院前与急诊初筛；详细评估仍用 GCS（A≈15、V≈13、P≈9、U≈3）。","refs":["ICRC 院前急救指南（2019）","AHA/ASA AIS Guidelines (2019)"]},{"id":"neuro_herniation","name":"脑疝判断（颅内压危象识别）","aka":["脑疝征象","Herniation signs"],"cat":"意识与病情","rank":23,"desc":"综合瞳孔、意识、呼吸与运动模式识别脑疝，指导紧急降颅压。","inputs":[{"key":"pupil","label":"瞳孔变化","unit":"","type":"select","options":[{"value":0,"label":"等大等圆，对光敏"},{"value":1,"label":"单侧瞳孔散大/对光迟钝"},{"value":2,"label":"双侧散大固定"}],"required":true},{"key":"gcs","label":"GCS","unit":"","type":"number","min":3,"max":15,"step":1,"required":true},{"key":"posture","label":"姿势","unit":"","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"去皮质强直（屈曲）"},{"value":2,"label":"去大脑强直（伸展）"}],"required":true},{"key":"respiration","label":"呼吸模式","unit":"","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"Cheyne-Stokes"},{"value":2,"label":"中枢性呼吸/呼吸暂停"}],"required":true},{"key":"ct_mass","label":"CT 占位效应（中线移位 > 5 mm）","unit":"","type":"select","options":[{"value":0,"label":"否/未查"},{"value":1,"label":"是"}],"required":true}],"formula":"综合评分：瞳孔 + GCS 分级 + 姿势 + 呼吸 + 占位","compute":"formula_only","algorithm":"v = pupil*2 + (gcs<=8?2:gcs<=12?1:0) + posture + respiration + ct_mass","interpret":[{"when":"pupil == 2 || (pupil == 1 && gcs <= 8)","level":"crit","text":"脑疝危象：立即 20% 甘露醇（按说明书 0.5–1 g/kg）或高渗盐水降颅压，气道保护，头高 30°，召集神外急诊"},{"when":"posture == 2 || respiration == 2","level":"crit","text":"中脑/延髓受压征象：紧急影像与外科会诊，避免腰穿"},{"when":"gcs <= 8","level":"high","text":"GCS ≤ 8：昏迷，考虑气管插管，监测 ICP"},{"when":"v <= 2","level":"ok","text":"无明显脑疝征象，继续监测"}],"note":"钩回疝早期出现同侧瞳孔散大、对侧偏瘫；枕骨大孔疝表现为呼吸骤停与双侧瞳孔固定。降颅压药物请遵本院流程与说明书。","refs":["中国颅内压增高诊治专家共识（2020）","AHA/ASA AIS Guidelines (2019)"]}]},"nsurg":{"items":[{"id":"nsurg_gcs","name":"格拉斯哥昏迷评分（GCS）","aka":["Glasgow Coma Scale","GCS"],"cat":"意识与全身状况","rank":1,"desc":"由睁眼、语言、运动三项组成的意识水平评分（3–15 分），用于颅脑损伤与神经重症的快速分层。","inputs":[{"key":"eye","label":"睁眼反应 E","type":"select","options":[{"value":4,"label":"自动睁眼"},{"value":3,"label":"呼唤睁眼"},{"value":2,"label":"疼痛刺激睁眼"},{"value":1,"label":"无睁眼"}],"required":true},{"key":"verbal","label":"语言反应 V","type":"select","options":[{"value":5,"label":"回答正确"},{"value":4,"label":"回答错误（混乱）"},{"value":3,"label":"不恰当词语"},{"value":2,"label":"无意义声音"},{"value":1,"label":"无发声"}],"required":true},{"key":"motor","label":"运动反应 M","type":"select","options":[{"value":6,"label":"遵嘱动作"},{"value":5,"label":"疼痛定位"},{"value":4,"label":"疼痛躲避（屈曲回缩）"},{"value":3,"label":"疼痛异常屈曲（去皮质）"},{"value":2,"label":"疼痛伸展（去大脑）"},{"value":1,"label":"无运动"}],"required":true}],"formula":"GCS = E（1–4）+ V（1–5）+ M（1–6），总分 3–15","compute":"sum","interpret":[{"when":"v <= 8","level":"crit","text":"3–8 分：重度昏迷，需保护气道（气管插管指征，GCS ≤ 8），立即头颅 CT 并请神经外科会诊"},{"when":"v <= 12","level":"high","text":"9–12 分：中度意识障碍，监测瞳孔与生命体征，4–6 小时复查 CT"},{"when":"v <= 14","level":"warn","text":"13–14 分：轻度意识障碍，需观察 24 小时；受伤后 2 小时内下降 ≥ 1 分或出现局灶体征应复查 CT"},{"when":"v >= 15","level":"ok","text":"15 分：意识清楚，按伤情决定是否需要影像与留观"}],"note":"气管插管、镇静肌松状态下 V 项无法评估记为 1T；GCS 不能反映脑干功能，需结合瞳孔、脑干反射与 GCS-P（GCS − 瞳孔反应分）。","refs":["中国颅脑创伤外科手术指南（2020）","2023 AHA/ASA 重型颅脑创伤救治指南"]},{"id":"nsurg_mrs","name":"改良 Rankin 量表（mRS）","aka":["modified Rankin Scale","mRS"],"cat":"意识与全身状况","rank":2,"desc":"评估卒中或颅脑疾病后 90 天功能残疾程度的 0–6 级量表，是神经外科疗效评价的主要终点。","inputs":[],"compute":"formula_only","levels":[{"label":"0 级","criteria":"完全无症状","level":"ok"},{"label":"1 级","criteria":"有症状但无明显残疾，能完成所有日常职责与活动","level":"ok"},{"label":"2 级","criteria":"轻度残疾，无法完成所有既往活动，但能在无帮助情况下自理","level":"ok"},{"label":"3 级","criteria":"中度残疾，需部分帮助，但能独立行走","level":"warn"},{"label":"4 级","criteria":"中重度残疾，无法独立行走、无法自理，需他人帮助","level":"high"},{"label":"5 级","criteria":"重度残疾，卧床、失禁，需持续护理","level":"crit"},{"label":"6 级","criteria":"死亡","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"0–2 级：功能独立（良好结局），可出院随访并启动二级预防"}],"note":"mRS 0–2 定义为功能独立（良好结局），3–6 为不良结局；评估应在固定时间点（如发病 90 天 ±7 天）由面访或结构化问卷完成。","refs":["中国急性缺血性脑卒中诊治指南（2023）","2015 AHA/ASA 急性缺血性卒中早期管理指南（mRS 结构化评估）"]},{"id":"nsurg_kps","name":"卡氏功能状态评分（KPS）","aka":["Karnofsky Performance Status","KPS"],"cat":"意识与全身状况","rank":3,"desc":"以 0–100 分描述患者体力活动与自理能力，是脑肿瘤手术与放化疗取舍、临床试验入组的关键分层因素。","inputs":[{"key":"kps","label":"KPS 评分","type":"select","options":[{"value":100,"label":"100：正常，无主诉，无疾病证据"},{"value":90,"label":"90：能正常活动，有轻微症状或体征"},{"value":80,"label":"80：正常活动费力，有部分症状或体征"},{"value":70,"label":"70：能自理，不能维持正常活动或工作"},{"value":60,"label":"60：需偶尔帮助，基本能自理"},{"value":50,"label":"50：需较多帮助与经常医疗照顾"},{"value":40,"label":"40：残疾，需特殊照顾与帮助"},{"value":30,"label":"30：严重残疾，需住院，但无死亡危险"},{"value":20,"label":"20：病重，需住院与积极支持治疗"},{"value":10,"label":"10：濒死，进展迅速"},{"value":0,"label":"0：死亡"}],"required":true}],"formula":"KPS 取 0–100 分十档之一，按「能否自理 / 能否工作 / 需否帮助」判定","compute":"formula_only","algorithm":"v = kps","interpret":[{"when":"v >= 70","level":"ok","text":"70–100 分：可耐受开颅手术与辅助放化疗，按标准方案推进"},{"when":"v >= 50","level":"warn","text":"50–60 分：需个体化权衡，术后并发症与住院时间显著增加，考虑活检或减量方案"},{"when":"v >= 20","level":"high","text":"20–40 分：一般不宜积极手术，以姑息减压、激素、放疗为主，早期引入安宁疗护"},{"when":"v < 20","level":"crit","text":"0–10 分：濒死状态，仅对症支持治疗"}],"note":"脑肿瘤中 KPS ≥ 70 且年龄 ≤ 65 岁者术后辅助治疗耐受性更好；KPS 与 ECOG 可换算（KPS 70–80 约 ECOG 1，50–60 约 ECOG 2）。","refs":["中国中枢神经系统胶质瘤诊断与治疗指南（2022）","NCCN 中枢神经系统肿瘤临床实践指南（2024）"]},{"id":"nsurg_wfns","name":"WFNS 蛛网膜下腔出血分级","aka":["World Federation of Neurosurgical Societies scale","WFNS"],"cat":"蛛网膜下腔出血与动脉瘤","rank":1,"desc":"结合 GCS 与局灶性神经功能缺损评估动脉瘤性蛛网膜下腔出血（aSAH）病情严重度，指导手术时机。","inputs":[{"key":"gcs","label":"GCS 总分","type":"select","options":[{"value":15,"label":"15 分"},{"value":14,"label":"14 分"},{"value":13,"label":"13 分"},{"value":12,"label":"12 分"},{"value":11,"label":"11 分"},{"value":10,"label":"10 分"},{"value":9,"label":"9 分"},{"value":8,"label":"8 分"},{"value":7,"label":"7 分"},{"value":6,"label":"6 分"},{"value":5,"label":"5 分"},{"value":4,"label":"4 分"},{"value":3,"label":"3 分"}],"required":true},{"key":"deficit","label":"局灶性神经功能缺损（失语、偏瘫、轻偏瘫）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Ⅰ 级 GCS 15 无缺损；Ⅱ 级 GCS 13–14 无缺损；Ⅲ 级 GCS 13–14 有缺损；Ⅳ 级 GCS 7–12 有无缺损均可；Ⅴ 级 GCS 3–6","compute":"formula_only","algorithm":"if gcs == 15 and deficit == 0: v = 1\nelif gcs >= 13 and deficit == 0: v = 2\nelif gcs >= 13 and deficit == 1: v = 3\nelif gcs >= 7: v = 4\nelse: v = 5","interpret":[{"when":"v <= 2","level":"ok","text":"Ⅰ–Ⅱ 级：预后较好，24 小时内早期夹闭或介入栓塞以降低再出血风险"},{"when":"v == 3","level":"warn","text":"Ⅲ 级：需先行腰大池引流/脱水与尼莫地平，评估后 24–72 小时内处理动脉瘤"},{"when":"v == 4","level":"high","text":"Ⅳ 级：意识障碍明显，先控制颅高压、脑室外引流，病情稳定后尽快（72 小时内）处理责任动脉瘤"},{"when":"v == 5","level":"crit","text":"Ⅴ 级：深度昏迷，多伴脑疝或严重脑积水；预后差，个体化决定是否干预及是否行去骨瓣减压"}],"note":"WFNS 与 Hunt-Hess 一致性中等，WFNS 以 GCS 为基础、重复性更好。所有级别均需尽早启动尼莫地平预防脑血管痉挛（21 天）。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2020）","2023 AHA/ASA 动脉瘤性蛛网膜下腔出血管理指南"]},{"id":"nsurg_hunt_hess","name":"Hunt-Hess 分级","aka":["Hunt and Hess Scale"],"cat":"蛛网膜下腔出血与动脉瘤","rank":2,"desc":"按头痛、脑膜刺激征与意识/神经缺损将动脉瘤性蛛网膜下腔出血分为 Ⅰ–Ⅴ 级，是传统的手术风险分层工具。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ 级","criteria":"无症状或轻度头痛、轻度颈项强直","level":"ok"},{"label":"Ⅱ 级","criteria":"中度至重度头痛、颈项强直，无脑神经以外神经缺损","level":"ok"},{"label":"Ⅲ 级","criteria":"嗜睡、意识模糊，或轻度局灶性神经缺损","level":"warn"},{"label":"Ⅳ 级","criteria":"木僵、中重度偏瘫，可有早期去大脑强直与自主神经紊乱","level":"high"},{"label":"Ⅴ 级","criteria":"深昏迷、去大脑强直、濒死外观","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"Ⅰ–Ⅱ 级可 24 小时内早期处理动脉瘤；Ⅲ–Ⅳ 级先稳定颅内压再尽快干预；Ⅴ 级个体化决定干预强度"}],"note":"合并严重全身疾病（高血压、糖尿病、慢阻肺、重度动脉粥样硬化）或严重血管痉挛时级别上调一级；改良 Hunt-Hess（WFNS）可减少观察者差异。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2020）","2023 AHA/ASA 动脉瘤性蛛网膜下腔出血管理指南"]},{"id":"nsurg_fisher_mfisher","name":"改良 Fisher 分级（mFisher）","aka":["modified Fisher Scale","mFisher","改良 Fisher CT 分级"],"cat":"蛛网膜下腔出血与动脉瘤","rank":3,"desc":"依据 CT 上蛛网膜下腔出血厚度与脑室内出血判定脑血管痉挛风险。","inputs":[],"compute":"formula_only","levels":[{"label":"1 级","criteria":"蛛网膜下腔无出血，或仅有薄层出血（< 1 mm），无脑室内出血","level":"ok"},{"label":"2 级","criteria":"蛛网膜下腔薄层出血（< 1 mm），伴脑室内出血","level":"warn"},{"label":"3 级","criteria":"蛛网膜下腔厚层出血（≥ 1 mm），无脑室内出血","level":"high"},{"label":"4 级","criteria":"蛛网膜下腔厚层出血（≥ 1 mm），伴脑室内出血","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"1–2 级脑血管痉挛风险低；3–4 级风险约 20%–40%，强化尼莫地平、TCD 监测与正常血容量管理"}],"note":"3–4 级（厚层出血）症状性脑血管痉挛风险约 20%–40%，需强化尼莫地平、经颅多普勒监测与维持正常血容量；1–2 级风险低。","refs":["中国动脉瘤性蛛网膜下腔出血诊疗指导规范（2020）","Frontera JA, et al. Neurosurgery 2006（mFisher 原版）"]},{"id":"nsurg_ich","name":"ICH 脑出血评分","aka":["ICH Score","Hemphill Score"],"cat":"脑出血","rank":1,"desc":"基于 GCS、出血量、脑室出血、年龄与幕下位置预测自发性脑出血 30 天病死率（0–6 分）。","inputs":[{"key":"gcs","label":"GCS 总分","type":"select","options":[{"value":0,"label":"13–15 分"},{"value":1,"label":"5–12 分"},{"value":2,"label":"3–4 分"}],"required":true},{"key":"volume","label":"血肿体积（CT 测算，多田公式：长×宽×层数/2）","unit":"mL","type":"number","min":0,"max":200,"step":1,"required":true},{"key":"ivh","label":"脑室内出血","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"infratentorial","label":"出血部位","type":"select","options":[{"value":0,"label":"幕上（基底节、丘脑、脑叶等）"},{"value":1,"label":"幕下（脑干、小脑）"}],"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true}],"formula":"总分 = GCS 分 + 体积分（≥ 30 mL 记 1）+ 脑室出血（1）+ 幕下（1）+ 年龄（≥ 80 岁记 1），0–6 分","compute":"formula_only","algorithm":"volPts = volume >= 30 ? 1 : 0\nagePts = age >= 80 ? 1 : 0\nv = gcs + volPts + ivh + infratentorial + agePts  # 0–6","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：30 天病死率约 0%–13%，积极内科治疗并考虑微创清除/去骨瓣"},{"when":"v == 2","level":"warn","text":"2 分：30 天病死率约 26%，加强颅高压监测，评估手术指征"},{"when":"v == 3","level":"high","text":"3 分：30 天病死率约 72%（原始队列），以控制颅高压、脑室引流为主，慎重评估手术获益"},{"when":"v >= 4","level":"crit","text":"4–6 分：30 天病死率 97%–100%，以姑息与家属沟通为主，避免无获益的积极干预"}],"note":"血肿体积用多田公式（ABC/2）估算时对不规则血肿有高估；改良评分（max-ICH）加入年龄、NIHSS 等因素，但 ICH Score 仍是最常用标准化工具。评分不替代临床判断。","refs":["中国脑出血诊治指南（2019）","2022 AHA/ASA 自发性脑出血管理指南","Hemphill JC, et al. Stroke 2001（ICH Score 原版）"]},{"id":"nsurg_mich","name":"mICH 改良脑出血评分","aka":["modified ICH Score","max-ICH score"],"cat":"脑出血","rank":2,"desc":"在 ICH Score 基础上加入年龄与 NIHSS 及血肿体积细分，预测脑出血 90 天功能结局，更侧重功能而非仅死亡。","inputs":[{"key":"age_pts","label":"年龄","type":"select","options":[{"value":0,"label":"< 70 岁"},{"value":1,"label":"≥ 70 岁"}],"required":true},{"key":"gcs_pts","label":"GCS 总分","type":"select","options":[{"value":0,"label":"13–15 分"},{"value":1,"label":"5–12 分"},{"value":2,"label":"3–4 分"}],"required":true},{"key":"nihss_pts","label":"NIHSS 评分","type":"select","options":[{"value":0,"label":"< 10 分"},{"value":1,"label":"10–20 分"},{"value":2,"label":"> 20 分"}],"required":true},{"key":"volume_pts","label":"血肿体积","type":"select","options":[{"value":0,"label":"< 30 mL"},{"value":1,"label":"30–60 mL"},{"value":2,"label":"> 60 mL"}],"required":true},{"key":"location_pts","label":"出血部位","type":"select","options":[{"value":0,"label":"幕上无脑室出血"},{"value":1,"label":"幕上伴脑室出血"},{"value":2,"label":"幕下"}],"required":true}],"formula":"总分 = 年龄 + GCS + NIHSS + 体积 + 部位（0–9 分）；mICH = 原始 max-ICH 分 +（无“幕上无脑室出血”选项时按 0 计）","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：90 天良好结局（mRS 0–3）概率较高，积极治疗并评估微创/开颅清除"},{"when":"v <= 4","level":"warn","text":"3–4 分：结局不确定，需结合血肿扩大风险、年龄耐受度个体化决定"},{"when":"v <= 6","level":"high","text":"5–6 分：预后不良可能性大，以控制颅压与并发症为主，与家属充分沟通"},{"when":"v >= 7","level":"crit","text":"7–9 分：90 天死亡或重度残疾概率极高，考虑以舒适照护为主"}],"note":"本表按 max-ICH 计分结构（年龄 0–1、GCS 0–2、NIHSS 0–2、体积 0–2、部位 0–2），与原 ICH Score 不可互换；不同文献阈值略有差异，需按本单位采用的版本解读。","refs":["中国脑出血诊治指南（2019）","Sembill JA, et al. Neurology 2017（max-ICH 原始文献）"]},{"id":"nsurg_graeb","name":"Graeb 脑室出血评分","aka":["Graeb Score","Intraventricular Hemorrhage Score"],"cat":"脑出血","rank":3,"desc":"按各脑室（双侧侧脑室、第三、第四脑室）积血量与脑室扩大程度评分（0–12 分），预测脑室出血患者的转归与引流需求。","inputs":[{"key":"lat_l","label":"左侧侧脑室积血量","type":"select","options":[{"value":0,"label":"无积血"},{"value":1,"label":"积血 < 一半"},{"value":2,"label":"积血 ≥ 一半但未完全充满"},{"value":3,"label":"完全充满"}],"required":true},{"key":"lat_r","label":"右侧侧脑室积血量","type":"select","options":[{"value":0,"label":"无积血"},{"value":1,"label":"积血 < 一半"},{"value":2,"label":"积血 ≥ 一半但未完全充满"},{"value":3,"label":"完全充满"}],"required":true},{"key":"third","label":"第三脑室积血量","type":"select","options":[{"value":0,"label":"无积血"},{"value":1,"label":"积血 < 一半"},{"value":2,"label":"积血 ≥ 一半但未完全充满"},{"value":3,"label":"完全充满"}],"required":true},{"key":"fourth","label":"第四脑室积血量","type":"select","options":[{"value":0,"label":"无积血"},{"value":1,"label":"积血 < 一半"},{"value":2,"label":"积血 ≥ 一半但未完全充满"},{"value":3,"label":"完全充满"}],"required":true},{"key":"dilation","label":"脑室扩大程度","type":"select","options":[{"value":0,"label":"无扩大"},{"value":1,"label":"轻度至中度扩大"},{"value":2,"label":"重度扩大"}],"required":true}],"formula":"总分 = 左 + 右侧脑室（各 0–3）+ 第三、第四脑室（各 0–3）+ 脑室扩大（0–2），0–12 分","compute":"sum","interpret":[{"when":"v <= 3","level":"ok","text":"0–3 分：轻度脑室出血，外引流需求低，可保守观察并动态复查 CT"},{"when":"v <= 7","level":"warn","text":"4–7 分：中度脑室出血，考虑脑室外引流；监测意识与脑室变化"},{"when":"v >= 8","level":"high","text":"8–12 分：重度脑室出血，病死率显著升高，应尽快行双侧脑室外引流 ± 脑室内溶栓"}],"note":"Graeb 总分 > 6 或第四脑室积血常伴梗阻性脑积水；脑室外引流已成为脑室出血治疗核心手段，第四脑室出血可考虑内镜下清除。","refs":["中国脑出血诊治指南（2019）","Graeb DA, et al. Radiology 1982（Graeb 评分原版）"]},{"id":"nsurg_spetzler_martin","name":"Spetzler-Martin 动静脉畸形分级","aka":["Spetzler-Martin Grade","SM Grade","AVM 分级"],"cat":"蛛网膜下腔出血与动脉瘤","rank":4,"desc":"依据畸形团大小、邻近功能区（eloquent area）与引流静脉特征将脑 AVM 分为 Ⅰ–Ⅴ 级，预测手术风险与致残率。","inputs":[{"key":"size","label":"畸形团（nidus）最大径","type":"select","options":[{"value":1,"label":"< 3 cm"},{"value":2,"label":"3–6 cm"},{"value":3,"label":"> 6 cm"}],"required":true},{"key":"eloquent","label":"位于功能区（感觉运动/语言/视觉皮质、丘脑、下丘脑、脑干、小脑脚、深部核团）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"venous","label":"引流静脉","type":"select","options":[{"value":0,"label":"仅浅表引流（皮质静脉/硬膜窦）"},{"value":1,"label":"深部引流（大脑大静脉、直窦、内静脉）"}],"required":true}],"formula":"SM 分级 = 大小分（1–3）+ 功能区（0–1）+ 深部静脉引流（0–1），1–5 级","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"Ⅰ–Ⅱ 级（手术低风险）：显微切除为主要选择，术后致残率 < 10%，可考虑治愈性治疗"},{"when":"v == 3","level":"warn","text":"Ⅲ 级（中等风险）：多学科讨论，可选择手术 + 栓塞 + SRS 联合的辅助治疗"},{"when":"v == 4","level":"high","text":"Ⅳ 级（高风险）：以保守观察、重复 SRS 或部分栓塞减压为主，手术致残率明显升高"},{"when":"v == 5","level":"crit","text":"Ⅴ 级（极高风险）：一般不建议手术或放疗干预，控制癫痫、避免诱发因素，定期影像随访"}],"note":"补充型（supplemented）分级将 Ⅲ 级细分，便于在同等原始分级下区分利弊；破裂 AVM 的处理时机需结合血肿与神经状态。Spetzler-Ponce 简化模型（A/B/C）更实用。","refs":["中国脑动静脉畸形诊疗指南（2021）","2017 AHA/ASA 脑动静脉畸形管理科学声明"]},{"id":"nsurg_phases","name":"PHASES 未破裂颅内动脉瘤破裂风险评分","aka":["PHASES Score","动脉瘤破裂风险评分"],"cat":"蛛网膜下腔出血与动脉瘤","rank":5,"desc":"综合人群、高血压、年龄、动脉瘤大小、部位与既往破裂史估算未破裂动脉瘤 5 年破裂概率，辅助决定是否干预。","inputs":[{"key":"population","label":"人群来源","type":"select","options":[{"value":0,"label":"北美 / 欧洲（除外芬兰）"},{"value":2,"label":"日本"},{"value":3,"label":"芬兰"},{"value":5,"label":"低危人群（如中国、韩国、南美等）"}],"required":true},{"key":"hypertension","label":"高血压","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"age_pts","label":"年龄","type":"select","options":[{"value":0,"label":"≥ 70 岁"},{"value":1,"label":"< 70 岁"}],"required":true},{"key":"size_pts","label":"动脉瘤最大径","type":"select","options":[{"value":0,"label":"< 7.0 mm"},{"value":3,"label":"7.0–9.9 mm"},{"value":6,"label":"10.0–19.9 mm"},{"value":10,"label":"≥ 20 mm"}],"required":true},{"key":"location","label":"动脉瘤部位","type":"select","options":[{"value":0,"label":"颈内动脉（非后交通段）"},{"value":2,"label":"大脑中动脉"},{"value":4,"label":"大脑前动脉 / 前交通 / 后交通 / 后循环（椎基底动脉）"}],"required":true},{"key":"earlier_sah","label":"既往蛛网膜下腔出血史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有（另一个动脉瘤曾破裂）"}],"required":true}],"formula":"PHASES = 人群 + 高血压 + 年龄 + 大小 + 部位 + 既往出血，0–22 分","compute":"sum","interpret":[{"when":"v <= 2","level":"ok","text":"0–2 分：5 年破裂风险约 0.4%，以影像随访为主（1–3 年复查），积极控压"},{"when":"v <= 4","level":"warn","text":"3–4 分：5 年破裂风险约 1%–2%，随访更密（每 6–12 月），评估形态学高危特征（不规则、子囊、增大快）"},{"when":"v <= 6","level":"high","text":"5–6 分：5 年破裂风险约 3%–5%，需多学科讨论血管内介入/夹闭的获益-风险"},{"when":"v >= 7","level":"crit","text":"≥ 7 分：5 年破裂风险 > 10%，通常建议积极治疗（介入或夹闭），并控制血压与戒烟"}],"note":"PHASES 基于国际未破裂动脉瘤研究（UCAS 等）队列，未纳入吸烟、家族史、形态学（长宽比、流入角）等独立因素；不适用于多囊肾、家族性高危人群与已经破裂的动脉瘤。","refs":["中国颅内动脉瘤诊疗指南（2021）","Greving JP, et al. Lancet Neurol 2014（PHASES 原版）"]},{"id":"nsurg_asia","name":"ASIA 脊髓损伤神经功能分级","aka":["ASIA Impairment Scale","AIS","美国脊柱损伤协会分级"],"cat":"脊柱脊髓损伤","rank":1,"desc":"依据最低骶段（S4–S5）保留情况与损伤平面以下运动/感觉保留程度，将脊髓损伤分为 A–E 级。","inputs":[],"compute":"formula_only","levels":[{"label":"A 级（完全性损伤）","criteria":"最低骶段 S4–S5 的感觉或运动功能均无保留","level":"crit"},{"label":"B 级（感觉不完全损伤）","criteria":"损伤神经平面以下包括骶段 S4–S5 存在感觉而运动功能保留，且神经平面以下 > 3 个节段无运动保留","level":"high"},{"label":"C 级（运动不完全损伤）","criteria":"骶段 S4–S5 有感觉或运动保留，损伤平面以下 > 3 个节段存在运动功能，且半数以上关键肌肌力 < 3 级","level":"warn"},{"label":"D 级（运动不完全损伤）","criteria":"骶段 S4–S5 有感觉或运动保留，损伤平面以下 > 3 个节段存在运动功能，且半数以上关键肌肌力 ≥ 3 级","level":"warn"},{"label":"E 级（正常）","criteria":"运动与感觉功能均正常","level":"ok"}],"interpret":[{"when":"v >= 0","level":"ok","text":"A 级为完全性损伤，需早期减压固定与康复；B–D 级为不完全性损伤，C/D 级康复潜力更大；E 级功能正常"}],"note":"A 级为完全性损伤；B–E 为不完全性损伤。分级需在伤后 72 小时内及出院时各完成一次（含肛门括约肌自主收缩与肛门感觉），并记录神经损伤平面（NLI）与 AIS 分级。","refs":["中国脊柱脊髓损伤诊疗指南（2021）","ISNCSCI 国际脊髓损伤神经分类标准（2023 修订版）"]}]},"obgyn":{"items":[{"id":"obgyn_bishop","name":"Bishop 评分（宫颈成熟度）","aka":["Bishop Score","宫颈评分"],"cat":"产程与分娩","rank":1,"desc":"评估宫颈成熟度以预测引产成功率（总分 0–13）。","inputs":[{"key":"dilation","label":"宫颈扩张（cm）","type":"select","options":[{"value":0,"label":"闭合"},{"value":1,"label":"1–2 cm"},{"value":2,"label":"3–4 cm"},{"value":3,"label":"≥5 cm"}],"required":true},{"key":"effacement","label":"宫颈消退（%）","type":"select","options":[{"value":0,"label":"0–30%"},{"value":1,"label":"40–50%"},{"value":2,"label":"60–70%"},{"value":3,"label":"≥80%"}],"required":true},{"key":"station","label":"胎头位置（坐骨棘上/下，cm）","type":"select","options":[{"value":0,"label":"−3"},{"value":1,"label":"−2"},{"value":2,"label":"−1 或 0"},{"value":3,"label":"+1 或 +2"}],"required":true},{"key":"consistency","label":"宫颈质地","type":"select","options":[{"value":0,"label":"硬"},{"value":1,"label":"中等"},{"value":2,"label":"软"}],"required":true},{"key":"position","label":"宫颈位置","type":"select","options":[{"value":0,"label":"后位"},{"value":1,"label":"中位"},{"value":2,"label":"前位"}],"required":true}],"formula":"Bishop = 宫口扩张 + 宫颈消退 + 胎头位置 + 质地 + 位置（0–13 分）","compute":"sum","interpret":[{"when":"v <= 5","level":"warn","text":"≤5 分：宫颈未成熟，直接缩宫素引产失败率高，建议先机械性（球囊/海藻棒）或前列腺素促宫颈成熟"},{"when":"v <= 9","level":"ok","text":"6–9 分：宫颈中等成熟，可直接引产，预计需较多缩宫素或一次前列腺素"},{"when":"v >= 10 && v <= 11","level":"ok","text":"10–11 分：宫颈成熟，引产成功率高，可直接人工破膜＋缩宫素"},{"when":"v >= 12","level":"ok","text":"12–13 分：宫颈高度成熟，引产几乎必成，注意过强宫缩风险"}],"note":"改良 Bishop 评分对胎头位置与宫口扩张项重新赋分，总分 0–13；≤5 分为促宫颈成熟指征阈值。胎膜早破引产、瘢痕子宫引产需个体化评估子宫破裂风险。","refs":["FIGO/WHO《正常分娩指南》（2015，宫颈成熟度章节）","ACOG Practice Bulletin No.107 引产（2009，2022 修订版）"]},{"id":"obgyn_naegele","name":"预产期推算（Naegele 法）","aka":["Naegele's Rule","EDD","Estimated Date of Delivery"],"cat":"产前检查","rank":2,"desc":"由末次月经首日（LMP）推算预产期，并以超声头臀长校正。","inputs":[{"key":"lmp_month","label":"LMP 月份","type":"number","min":1,"max":12,"step":1,"required":true},{"key":"lmp_day","label":"LMP 日期（日）","type":"number","min":1,"max":31,"step":1,"required":true},{"key":"crl_mm","label":"早孕期超声头臀长 CRL（可空）","unit":"mm","type":"number","min":10,"max":90,"step":0.1,"required":false,"hint":"6+0–13+6 周测量；CRL 7–84 mm 时最准确"}],"formula":"EDD = LMP + 280 天（LMP 月份减 3 或加 9、日加 7）；孕周 = 距 LMP 天数 / 7；由 CRL 推算孕周 ≈ CRL(mm) + 42 天","compute":"formula_only","algorithm":"d = new Date(2028, lmp_month-1, lmp_day)\nedd = d + 280 天\nif (lmp_month > 3) edd_month = lmp_month - 3 else edd_month = lmp_month + 9\nedd_day = lmp_day + 7（>该月天数则顺延进月）\nweeks = floor((today - d) / 7)；days = (today - d) % 7\nif crl_mm 有值：ga_from_crl_days = crl_mm + 42；若两者差 >7 天以 CRL 为准重新定 EDD\n","interpret":[{"when":"v < 196","level":"ok","text":"孕周 < 28 周：常规产检，20–24 周系统超声筛查"},{"when":"v <= 272","level":"ok","text":"28–38+6 周：按指南产检，监测胎动与血压，≥37 周可讨论分娩计划"},{"when":"v >= 280","level":"warn","text":"≥40 周：需评估胎盘功能与胎儿监测；≥41 周建议引产（过期妊娠风险上升）"}],"note":"规则在月经周期 28 天、排卵在第 14 天时最准确；周期不规律者以早孕期 CRL 为准（7–8 周偏差 >5 天、9–13+6 周偏差 >7 天时改以超声定 EDD）。","refs":["ACOG Committee Opinion No.700 Methods for Estimating the Due Date（2017）","中华医学会妇产科学分会产科学组：孕前和孕期保健指南（2018）"]},{"id":"obgyn_gtpal","name":"GTPAL 产科病史记录","aka":["Gravida Para","孕产次"],"cat":"产科档案","rank":3,"desc":"结构化记录孕次、产次、足月产、早产、存活子代数，全面概括生育史。","inputs":[{"key":"g","label":"孕次 Gravida（含本次）","type":"number","min":0,"max":25,"step":1,"required":true},{"key":"t","label":"足月产 Term（≥37 周）","type":"number","min":0,"max":20,"step":1,"required":true},{"key":"p","label":"早产 Preterm（20–36+6 周）","type":"number","min":0,"max":20,"step":1,"required":true},{"key":"a","label":"流产/宫外孕 Abortion（<20 周）","type":"number","min":0,"max":20,"step":1,"required":true},{"key":"l","label":"存活子代数 Living","type":"number","min":0,"max":20,"step":1,"required":true}],"formula":"G = T + P + A（孕次须等于足月+早产+流产）；P（产次）= T + P，且 G ≥ P","compute":"formula_only","algorithm":"expected_g = t + p + a\nif g != expected_g: 提示「孕次与足月/早产/流产之和不等，请核对」\nif l > t + p: 提示「存活数不能大于产次」\nv = t + p  # 产次\ntext = `G${g} P${t+p} (T${t} P${p} A${a} L${l})`\n","interpret":[{"when":"g == t + p + a","level":"ok","text":"记录自洽：按孕期保健指南分层管理（产次 ≥3 或既往早产史者列为高危妊娠重点监护）"},{"when":"g != t + p + a","level":"warn","text":"孕次与 T+P+A 之和不等，常见于宫颈妊娠、多胎漏记；请重新核对病史"}],"note":"GTPAL 取代了旧 G/P 的模糊写法；中国临床常用「孕 n 产 m」表述（G P），记录时建议同时写全 GTPAL。产次 ≥5 为经产妇高危要素。","refs":["ACOG Committee Opinion No.787 (2019) The Use of GTPAL","中华医学会妇产科学分会：高危妊娠管理指南（2021）"]},{"id":"obgyn_bmi_preg","name":"孕前 BMI 与建议增重","aka":["Pregnancy BMI Weight Gain","孕期体重增长"],"cat":"产前检查","rank":4,"desc":"按孕前 BMI 分类，给出中国指南的孕期总增重与中晚孕期每周增重范围。","inputs":[{"key":"weight_kg","label":"孕前体重","unit":"kg","type":"number","min":30,"max":200,"step":0.1,"required":true},{"key":"height_cm","label":"身高","unit":"cm","type":"number","min":130,"max":210,"step":0.1,"required":true},{"key":"twins","label":"是否双胎妊娠","type":"select","options":[{"value":0,"label":"单胎"},{"value":1,"label":"双胎"}],"required":true}],"formula":"BMI = 体重(kg) / 身高(m)²；孕前 BMI <18.5 偏瘦、18.5–23.9 正常、24.0–27.9 超重、≥28.0 肥胖（中国标准）","compute":"bmi","interpret":[{"when":"v < 18.5 && twins == 0","level":"warn","text":"偏瘦：单胎建议总增重 12.5–18 kg，孕中晚期约 0.51 kg/周"},{"when":"v < 18.5 && twins == 1","level":"warn","text":"偏瘦双胎：建议总增重 17–24 kg，加强营养监测"},{"when":"v < 24 && twins == 0","level":"ok","text":"正常：单胎建议总增重 11.5–16 kg，孕中晚期约 0.42 kg/周"},{"when":"v < 28 && twins == 0","level":"warn","text":"超重：单胎建议总增重 7–11.5 kg，约 0.28 kg/周；筛查妊娠期糖尿病"},{"when":"v < 30 && twins == 0","level":"high","text":"肥胖 I 度：单胎建议总增重 5–9 kg，约 0.22 kg/周；加强 GDM/子痫前期/巨大儿筛查"},{"when":"twins == 0","level":"high","text":"肥胖 II 度以上（BMI ≥30）：单胎建议总增重 5–9 kg，个体化管理，警惕体重不增或过度增加"},{"when":"v < 24 && twins == 1","level":"ok","text":"正常双胎：建议总增重 16.7–24.3 kg"},{"when":"v < 28 && twins == 1","level":"warn","text":"超重双胎：建议总增重 13.9–22.5 kg"},{"when":"twins == 1","level":"high","text":"肥胖双胎：建议总增重 11.3–19.1 kg，需与营养科联合管理并筛查 GDM/子痫前期"}],"note":"增重值为 IOM 2009 与中国《妊娠期妇女体重增长推荐值》（WS/T 801-2022）区间；孕早期（<14 周）总增重通常 ≤2 kg。BMI 估值为孕前值，孕中测得可能偏高。","refs":["WS/T 801-2022 妊娠期妇女体重增长推荐值标准","IOM 2009 Weight Gain During Pregnancy With Singleton/Twin Gestations"]},{"id":"obgyn_ogtt","name":"妊娠期糖尿病 OGTT 诊断阈值（75g）","aka":["GDM OGTT","75g 口服葡萄糖耐量"],"cat":"妊娠期合并症","rank":5,"desc":"75 g OGTT 三时点判读，任一达标即可诊断妊娠期糖尿病（GDM）。","inputs":[{"key":"fpg","label":"空腹血糖（0 h）","unit":"mmol/L","type":"number","min":2,"max":25,"step":0.1,"required":true},{"key":"bg1h","label":"服糖后 1 h","unit":"mmol/L","type":"number","min":2,"max":30,"step":0.1,"required":true},{"key":"bg2h","label":"服糖后 2 h","unit":"mmol/L","type":"number","min":2,"max":30,"step":0.1,"required":true}],"formula":"诊断阈值：0 h ≥5.1、1 h ≥10.0、2 h ≥8.5 mmol/L；空腹 ≥7.0 或 2 h ≥11.1 则按孕前糖尿病（PGDM）处理而非 GDM","compute":"formula_only","algorithm":"hits = 0\nif fpg >= 5.1 hits++\nif bg1h >= 10.0 hits++\nif bg2h >= 8.5 hits++\nif fpg >= 7.0 || bg2h >= 11.1: v = 99 (PGDM)\nelse v = hits\n","interpret":[{"when":"v == 0","level":"ok","text":"三项均未达标：排除 GDM，常规随诊；高危者 32–34 周可复查"},{"when":"v == 1","level":"warn","text":"1 项达标：诊断 GDM，立即开始医学营养治疗＋自我血糖监测（空腹 <5.3、餐后 2 h <6.7 mmol/L）"},{"when":"v == 2","level":"high","text":"2 项达标：GDM，血糖控制难度较高，建议强化监测，7–10 天后评估是否需胰岛素"},{"when":"v >= 3 && v < 99","level":"crit","text":"3 项全部达标：GDM 重度异常，尽早住院评估与胰岛素/营养干预"},{"when":"v >= 99","level":"crit","text":"空腹 ≥7.0 或 2 h ≥11.1 mmol/L：符合孕前显性糖尿病（PGDM）标准，按糖尿病合并妊娠管理（眼底、肾功能、心超评估）"}],"note":"孕 24–28 周行 75 g OGTT，检查前禁食 8–10 h、日碳水化合物摄入 ≥150 g 连续 3 天。结果需 2 次确认以外的单次异常即诊断（中国指南），不宜按 OGTT 单项幅度自行忽略。","refs":["中华医学会妇产科学分会：妊娠合并糖尿病诊治指南（2014，2022 更新要点）","WHO 2013 Diagnostic Criteria and Classification of Hyperglycaemia First Detected in Pregnancy"]},{"id":"obgyn_preeclampsia","name":"子痫前期严重度与诊断要件","aka":["Preeclampsia Severity","重度子痫前期"],"cat":"妊娠期合并症","rank":6,"desc":"根据血压、器官损伤与实验室项数判断子痫前期及其严重特征。","inputs":[{"key":"sbp","label":"收缩压","unit":"mmHg","type":"number","min":70,"max":260,"step":1,"required":true},{"key":"dbp","label":"舒张压","unit":"mmHg","type":"number","min":30,"max":180,"step":1,"required":true},{"key":"proteinuria","label":"尿蛋白","type":"select","options":[{"value":0,"label":"阴性"},{"value":1,"label":"微量 / 尿蛋白 ±"},{"value":2,"label":"≥ 1+ 或 24 h ≥0.3 g"},{"value":3,"label":"≥ 3+ 或 24 h ≥2 g / 尿蛋白肌酐比 ≥0.3"}],"required":true},{"key":"severity_flags","label":"重度特征项数（血小板 <100、AST/ALT 升高 >2 倍、肌酐 >97 μmol/L、肺水肿、新发头痛/视觉异常、上腹痛）","type":"number","min":0,"max":6,"step":1,"required":true}],"formula":"血压：≥140/90（间隔 ≥4 h 两次）；重度：≥160/110。严重特征：血小板 <100×10⁹/L、肝酶正常上限 2 倍、肌酐 >97 μmol/L(或升高)、肺水肿、新发中枢神经/视觉症状、持续性上腹痛","compute":"formula_only","algorithm":"htn = sbp >= 140 || dbp >= 90\nsevere_bp = sbp >= 160 || dbp >= 110\nv = 0  # 0 正常 / 1 妊娠期高血压 / 2 子痫前期 / 3 重度特征 / 4 重度子痫前期\nif htn && proteinuria < 2 && severity_flags == 0: v = 1\nif htn && (proteinuria >= 2 || severity_flags >= 1): v = 2\nif severity_flags >= 1 && !htn && proteinuria >= 2: v = 2  # 蛋白尿+严重特征\nif severe_bp || severity_flags >= 1: v = Math.max(v, 3)\nif severe_bp && (proteinuria >= 2 || severity_flags >= 1): v = 4\n","interpret":[{"when":"v == 0","level":"ok","text":"血压正常、无蛋白尿：继续常规产检，每次记录血压与尿蛋白"},{"when":"v == 1","level":"warn","text":"妊娠期高血压：预约复评（1–2 周内），查血常规、肝肾功能、尿蛋白定量；出现头痛/视物模糊立即就诊"},{"when":"v == 2","level":"high","text":"子痫前期：住院评估（期待治疗），每 4 h 测血压，每日查胎动与尿蛋白，评估终止妊娠时机"},{"when":"v == 3","level":"crit","text":"存在严重特征：按重度子痫前期处理，立即硫酸镁防抽搐、静脉降压，评估 24–48 h 内终止妊娠"},{"when":"v >= 4","level":"crit","text":"重度子痫前期：即刻住院，多学科（产科/ICU/麻醉）讨论终止妊娠，≥34 周建议终止；<34 周权衡期待治疗"}],"note":"血压测量需静坐 5 min、右臂、合适袖带；可疑白大衣高血压时用动态血压。HELLP 综合征（溶血、肝酶升高、低血小板）是重度病变型。","refs":["中华医学会妇产科学分会：妊娠期高血压疾病诊治指南（2020）","ACOG Practice Bulletin No.222 Gestational Hypertension and Preeclampsia（2020，2022 修订）"]},{"id":"obgyn_apgar","name":"Apgar 新生儿评分","aka":["Apgar Score"],"cat":"新生儿评估","rank":7,"desc":"出生后 1、5（10）分钟评估心率、呼吸、肌张力、反射与肤色，评估新生儿的过渡状况。","inputs":[{"key":"hr","label":"心率","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"<100 次/分"},{"value":2,"label":"≥100 次/分"}],"required":true},{"key":"resp","label":"呼吸","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"弱、不规则"},{"value":2,"label":"啼哭有力"}],"required":true},{"key":"tone","label":"肌张力","type":"select","options":[{"value":0,"label":"瘫软"},{"value":1,"label":"四肢略屈曲"},{"value":2,"label":"主动活动"}],"required":true},{"key":"reflex","label":"反射刺激（对刺激的反应）","type":"select","options":[{"value":0,"label":"无反应"},{"value":1,"label":"皱眉/面部扭曲"},{"value":2,"label":"哭、咳嗽、喷嚏"}],"required":true},{"key":"color","label":"肤色","type":"select","options":[{"value":0,"label":"全身青紫或苍白"},{"value":1,"label":"躯干粉红、肢端青紫"},{"value":2,"label":"全身粉红"}],"required":true}],"formula":"Apgar = 心率 + 呼吸 + 肌张力 + 反射 + 肤色（每项 0–2，总分 0–10）","compute":"sum","interpret":[{"when":"v >= 7","level":"ok","text":"7–10 分：一般状态良好，常规新生儿护理与母婴同室"},{"when":"v >= 4","level":"warn","text":"4–6 分：轻–中度抑制，继续复苏（保暖、清呼吸道、刺激、正压通气），5 min 复评"},{"when":"v < 4","level":"crit","text":"<4 分：重度抑制/围产期缺氧，立即按 NRP 流程复苏，5/10 min 持续复评并转 NICU"}],"note":"Apgar 反映即时状态，不单独用于诊断窒息；诊断需结合脐血血气（pH <7.0、BE ≤−12）。5 min <7 分应延长至 10、15、20 min 复评。","refs":["AAP/ACOG Committee Opinion No.644 The Apgar Score（2015）","中国新生儿复苏指南（2021）"]},{"id":"obgyn_pph_bloodloss","name":"产后出血量估算与分级","aka":["Postpartum Hemorrhage Quantification","PPH"],"cat":"分娩并发症","rank":8,"desc":"按称重法/血红蛋白下降/休克指数综合估算失血量并分级处置。","inputs":[{"key":"bags","label":"收集袋/纱布估量总血量","unit":"mL","type":"number","min":0,"max":6000,"step":10,"required":true},{"key":"hb_drop","label":"Hb 下降值","unit":"g/L","type":"number","min":0,"max":90,"step":1,"required":false},{"key":"shock_index","label":"休克指数（心率/收缩压）","type":"number","min":0.3,"max":3,"step":0.01,"required":false}],"formula":"失血量估计：Hb 下降 10 g/L 约相当于失血 400–500 mL；休克指数 ≥1.0 提示失血量约 >1000 mL；标准：剖宫产 ≥1000 mL、阴道分娩 ≥500 mL 诊断产后出血","compute":"formula_only","algorithm":"v = bags\nif hb_drop 有值: v = Math.max(v, hb_drop * 45)\nif shock_index 有值: v = Math.max(v, shockToLoss(shock_index))  # 0.5→<500, 0.7→750, 0.9→1000, 1.0→1500, 1.5→2500\n","interpret":[{"when":"v < 500","level":"ok","text":"<500 mL（阴道分娩）或 <1000 mL（剖宫产）：常规观察，称重法持续累计"},{"when":"v < 1000","level":"warn","text":"500–1000 mL：诊断产后出血，按摩子宫＋宫缩剂，建立静脉通路、查凝血，寻找病因（4T）"},{"when":"v < 1500","level":"high","text":"1000–1500 mL：启动大量输血预案评估，宫腔球囊/压迫缝合，ICU 床位准备"},{"when":"v < 2000","level":"crit","text":"1500–2000 mL：难治性产后出血，输血（血浆:红细胞 ≈1:1.5–2），介入栓塞或剖腹探查"},{"when":"v >= 2000","level":"crit","text":"≥2000 mL：危及生命，气管插管、纠正凝血、考虑子宫切除，启动多学科抢救"}],"note":"称重法：湿重−干重（1 g≈1 mL）；视觉估测常低估 30–50%。休克指数比血压更早反映失血。以「4T」（Tone/Thrombin/Trauma/Tissue）逐一排查。","refs":["中华医学会妇产科学分会：产后出血预防与处理指南（2023）","WHO Recommendations for the Prevention and Treatment of Postpartum Haemorrhage（2012）","RCOG Green-top Guideline No.52 Prevention and Management of Postpartum Haemorrhage（2016）"]},{"id":"obgyn_afi","name":"羊水指数 AFI（四象限）","aka":["Amniotic Fluid Index","羊水过多/过少"],"cat":"产前检查","rank":9,"desc":"四个象限最大羊水暗区垂直深度之和（cm），评估羊水量。","inputs":[{"key":"q1","label":"右上象限最大暗区（RUQ）","unit":"cm","type":"number","min":0,"max":30,"step":0.1,"required":true},{"key":"q2","label":"右下象限（RLQ）","unit":"cm","type":"number","min":0,"max":30,"step":0.1,"required":true},{"key":"q3","label":"左上象限（LUQ）","unit":"cm","type":"number","min":0,"max":30,"step":0.1,"required":true},{"key":"q4","label":"左下象限（LLQ）","unit":"cm","type":"number","min":0,"max":30,"step":0.1,"required":true}],"formula":"AFI = RUQ + RLQ + LUQ + LLQ（cm）；正常 8–24 cm，≤5 过少（中度 5–8），≥25 过多","compute":"sum","interpret":[{"when":"v <= 5","level":"crit","text":"AFI ≤5 cm：羊水过少，若已足月建议考虑终止妊娠；未足月者行 NST/生物物理评分并每周复查"},{"when":"v <= 8","level":"warn","text":"AFI 5–8 cm：临界偏少，48–72 h 内复查，评估母体 hydration、胎儿生长与胎盘功能"},{"when":"v < 25","level":"ok","text":"AFI 8–24 cm：羊水量正常"},{"when":"v >= 25","level":"high","text":"AFI ≥25 cm：羊水过多，筛查 GDM、胎儿结构异常（消化道闭锁）、同种免疫与多胎，警惕胎膜早破与脐带脱垂"}],"note":"AFI 受孕周、操作者影响；多胎妊娠不适用四象限法，单胎用最大垂直暗区（MVP）<2 cm 亦为羊水过少。单一暗区 ≤1 cm 提示绝对羊水过少。","refs":["ACOG Practice Bulletin No.175 Ultrasound in Pregnancy（2016）","ISUOG Practice Guidelines: Ultrasound Assessment of Fetal Biometry and Growth（2019）"]},{"id":"obgyn_nst","name":"胎心监护 NST 判读（Reactive / Non-reactive）","aka":["Non-stress Test","无应激试验"],"cat":"胎儿监测","rank":10,"desc":"20–40 min 胎心监护中按胎心加速、基线变异与减速评估胎儿宫内状况。","inputs":[{"key":"accel","label":"20 min 内 ≥15 bpm、持续 ≥15 s 的加速次数","type":"number","min":0,"max":20,"step":1,"required":true},{"key":"variability","label":"基线变异（bpm）","type":"select","options":[{"value":0,"label":"消失（无明显变异）"},{"value":1,"label":"微小（≤5）"},{"value":2,"label":"中等（6–25）"},{"value":3,"label":"显著（>25）"}],"required":true},{"key":"decel","label":"减速类型","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"偶发可变减速（<50% 宫缩）"},{"value":2,"label":"反复变异减速（≥50% 宫缩）"},{"value":3,"label":"晚期/延长减速或正弦波"}],"required":true},{"key":"ga","label":"孕周","unit":"周","type":"number","min":24,"max":43,"step":1,"required":true}],"formula":"NST：20 min 内 ≥2 次加速（孕周 ≥32 周：≥15 bpm × 15 s；<32 周：≥10 bpm × 10 s）＋中等变异 = 反应型；否则为无反应型","compute":"formula_only","algorithm":"need = ga >= 32 ? 2 : 2  # 阈值次数相同，幅度/时长不同\nreactive = accel >= need\nv = 0\nif !reactive: v = 1                     # 无反应型（可加 vibroacoustic stimulation）\nif reactive && variability == 2 && decel >= 2: v = 2   # 反应型但有反复减速\nif variability == 0: v = Math.max(v, 2)\nif variability == 3: v = Math.max(v, 2)  # 显著变异需排除缺氧早期\nif decel == 3: v = 3                     # 病理性\n","interpret":[{"when":"v == 0","level":"ok","text":"反应型：胎儿状况良好，高危妊娠每周 1–2 次随访"},{"when":"v == 1","level":"warn","text":"无反应型：给予声音/触觉刺激后复查 20 min，同时评估睡眠周期；仍未反应则行生物物理评分（BPP）或宫缩应激试验"},{"when":"v == 2","level":"high","text":"反应型但变异异常/反复减速：视为可疑，结合 BPP、胎动与羊水量，必要时住院监测"},{"when":"v >= 3","level":"crit","text":"病理性图形（晚期/延长减速或正弦波）：提示胎盘功能不全或胎儿贫血，立即评估分娩，备脐血与新生儿复苏"}],"note":"判读需结合宫缩、药物（β 受体激动剂可致心动过速、硫酸镁致变异减少）、胎儿睡眠（20–40 min 循环）与母体血糖。不可仅凭单次无反应型下结论。","refs":["ACOG Practice Bulletin No.145 Antepartum Fetal Surveillance（2014，2021 修订）","中华医学会围产医学分会：电子胎心监护应用专家共识（2015）"]},{"id":"obgyn_rmi","name":"RMI 卵巢肿物恶性风险指数","aka":["Risk of Malignancy Index","RMI I"],"cat":"妇科肿瘤筛查","rank":11,"desc":"CA125 × 绝经状态评分 × 超声评分，评估附件肿物恶性风险。","inputs":[{"key":"ca125","label":"血清 CA125","unit":"U/mL","type":"number","min":0,"max":20000,"step":0.1,"required":true},{"key":"menopause","label":"绝经状态","type":"select","options":[{"value":1,"label":"绝经前"},{"value":3,"label":"绝经后"}],"required":true},{"key":"us_flags","label":"超声阳性特征数（多房囊性、实性区、双侧、腹水、转移）","type":"number","min":0,"max":5,"step":1,"required":true},{"key":"incidental","label":"可选：术中偶见、既往卵巢癌史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"是"}],"required":false,"hint":"RMI 不支持上述情形，请直接按临床分期/专科处理"}],"formula":"RMI = CA125 × M × U；M（绝经前 1、绝经后 3）；U（0 项 0、1 项 1、2–5 项 3）","compute":"formula_only","algorithm":"U = us_flags == 0 ? 0 : (us_flags == 1 ? 1 : 3)\nv = ca125 * menopause * U\nif incidental == 1: v = -1  # 不适用，见 note\n","interpret":[{"when":"v < 0","level":"warn","text":"存在既往卵巢癌史或非活检发现（偶见）：RMI 不适用，直接按妇科肿瘤专科流程（MDT、影像分期）处理"},{"when":"v < 25","level":"low","text":"RMI <25：低风险，可腹腔镜探查；仍须术中冰冻并告知保守监测可能漏诊"},{"when":"v < 200","level":"warn","text":"RMI 25–200：中风险，建议三级中心影像复评（MRI/mpMRI）并由妇科肿瘤医师评估"},{"when":"v >= 200","level":"crit","text":"RMI ≥200：高风险，转妇科肿瘤中心，按卵巢癌分期手术/新辅助化疗路径"}],"note":"RMI 对交界性肿瘤与粘液性癌敏感度较低（粘液性癌常 CA125 不升），绝经前内膜异位囊肿 CA125 假阳性。早孕/急性炎症期 CA125 可升高，不宜测定。不能替代病理诊断。","refs":["RCOG Green-top Guideline No.62 Management of Suspected Ovarian Masses in Premenopausal Women（2011）","ESGO/ISUOG/IOTA/ESGE Consensus Statement on Pre-operative Diagnosis of Ovarian Tumors（2021）","中华医学会妇科肿瘤学分会：卵巢恶性肿瘤诊断与治疗指南（2022）"]},{"id":"obgyn_pprom","name":"足月前胎膜早破（PPROM）风险分级","aka":["PPROM Risk Stratification"],"cat":"分娩并发症","rank":12,"desc":"综合孕周、感染指标与羊水指数，分层 PPROM 的期待治疗与终止妊娠时机。","inputs":[{"key":"ga","label":"孕周","unit":"周","type":"number","min":22,"max":40,"step":1,"required":true},{"key":"infection","label":"感染征象（发热 ≥38℃、子宫压痛、阴道脓性分泌物、胎心 >160）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"1 项"},{"value":2,"label":"≥2 项"}],"required":true},{"key":"afi","label":"羊水指数（可空）","unit":"cm","type":"number","min":0,"max":30,"step":0.1,"required":false}],"formula":"PPROM：孕 28–36+6 周、无感染迹象时期待治疗（抗生素预防 GBS＋糖皮质激素促胎肺成熟）；≥34 周或感染迹象明确则终止妊娠","compute":"formula_only","algorithm":"v = 0  # 0 期待治疗 / 1 早期终止评估 / 2 终止妊娠\nif infection >= 2 || (infection == 1 && ga >= 34): v = 2\nelse if ga >= 37: v = 2\nelse if ga >= 34: v = 1\nelse: v = 0\nif afi 有值 && afi <= 2: v = Math.max(v, 1)  # 羊水过少风险高\n","interpret":[{"when":"v == 0","level":"warn","text":"期待治疗：抗生素 7–10 天，糖皮质激素（＜34 周），每 4 h 测体温心率、每日血常规，警惕绒毛膜羊膜炎"},{"when":"v == 1","level":"high","text":"早期终止评估：孕 34–36+6 周或羊水极少，多学科讨论引产时机，避免等待至感染发生"},{"when":"v >= 2","level":"crit","text":"立即终止妊娠：已诊断绒毛膜羊膜炎或≥37 周，启动缩宫素引产，产妇抗生素治疗（氨苄西林＋庆大霉素），新生儿科待产"}],"note":"疑似 PPROM 应行阴道窥器检查（避免指检）与 pH/胰岛素样生长因子结合蛋白-1 检测确认。GBS 筛查未做者按高危预防性用药。","refs":["ACOG Practice Bulletin No.188 Prelabor Rupture of Membranes（2018）","中华医学会妇产科学分会：胎膜早破诊断与处理指南（2015）"]}]},"onco":{"items":[{"id":"onco_ecog_ps","name":"ECOG 体能状态评分（PS）","aka":["ECOG PS","ZPS","Zubrod 评分"],"cat":"体能状态","rank":1,"desc":"评估肿瘤患者日常活动能力，决定化疗强度与临床试验入组。","inputs":[{"key":"ps","label":"ECOG 分级","unit":"","type":"select","options":[{"value":0,"label":"0 活动完全正常"},{"value":1,"label":"1 可走动，轻体力活动受限"},{"value":2,"label":"2 卧床 < 50%，生活自理"},{"value":3,"label":"3 卧床 > 50%，部分自理"},{"value":4,"label":"4 完全卧床，无法自理"},{"value":5,"label":"5 死亡"}],"required":true}],"formula":"直接选择 0–5 级","compute":"formula_only","algorithm":"v = ps","interpret":[{"when":"v <= 1","level":"ok","text":"PS 0–1：可耐受标准剂量化疗与联合方案"},{"when":"v == 2","level":"warn","text":"PS 2：考虑减量或单药，老年评估后再决定"},{"when":"v == 3","level":"high","text":"PS 3：多不宜常规化疗，考虑姑息治疗/靶向/免疫单药"},{"when":"v >= 4","level":"crit","text":"PS 4–5：以最佳支持治疗为主"}],"note":"化疗前须在病历记录 PS；PS 下降 ≥ 2 级或突发下降提示疾病进展或并发症；与 KPS 可近似换算（KPS ≈ 100 − 10×PS）。","refs":["中国常见恶性肿瘤诊治规范（国家卫健委 2022）","NCCN Guidelines – Palliative Care (2024)"]},{"id":"onco_kps","name":"Karnofsky 体能状态评分（KPS）","aka":["KPS","Karnofsky Performance Status"],"cat":"体能状态","rank":2,"desc":"按 0–100 分评估功能状态，用于放疗、化疗与预后评估。","inputs":[{"key":"kps","label":"KPS 分值","unit":"","type":"select","options":[{"value":100,"label":"100 正常无症状"},{"value":90,"label":"90 能正常活动，轻微症状"},{"value":80,"label":"80 轻微症状，需努力才能正常活动"},{"value":70,"label":"70 生活自理，不能正常工作"},{"value":60,"label":"60 偶尔需帮助"},{"value":50,"label":"50 需较多帮助，频繁医疗"},{"value":40,"label":"40 卧床，需特殊照顾"},{"value":30,"label":"30 严重不能自理，住院"},{"value":20,"label":"20 病重，需支持治疗"},{"value":10,"label":"10 濒死"},{"value":0,"label":"0 死亡"}],"required":true}],"formula":"直接选择 KPS 分值（0–100）","compute":"formula_only","algorithm":"v = kps","interpret":[{"when":"v >= 80","level":"ok","text":"KPS ≥ 80：可接受积极抗肿瘤治疗与联合化疗"},{"when":"v >= 70 && v < 80","level":"ok","text":"KPS 70–79：可考虑化疗，但需密切监测"},{"when":"v >= 60 && v < 70","level":"warn","text":"KPS 60–69：慎用高强度化疗，考虑减量或单药"},{"when":"v < 60","level":"high","text":"KPS < 60：多不宜化疗，以支持治疗与症状控制为主"},{"when":"v <= 40","level":"crit","text":"KPS ≤ 40：仅姑息治疗，评估临终关怀"}],"note":"KPS 常用于放疗适应证（如脑转移放疗要求 KPS ≥ 60–70）；与 ECOG 换算仅供参考。","refs":["中国常见恶性肿瘤诊治规范（国家卫健委 2022）","Karnofsky DA, Burchenal JH (1949)"]},{"id":"onco_morse_fall","name":"Morse 跌倒风险评估","aka":["Morse Fall Scale","MFS"],"cat":"支持治疗","rank":4,"desc":"评估住院肿瘤患者跌倒风险，指导防跌倒措施。","inputs":[{"key":"history","label":"近 3 个月跌倒史","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":25,"label":"有（25）"}],"required":true},{"key":"secondary","label":"次要诊断（≥ 2 个）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":15,"label":"有（15）"}],"required":true},{"key":"aid","label":"行走辅助","unit":"","type":"select","options":[{"value":0,"label":"不需/卧床"},{"value":15,"label":"用辅助器（15）"},{"value":30,"label":"扶床/椅（30）"}],"required":true},{"key":"iv","label":"静脉输液/肝素锁","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":20,"label":"有（20）"}],"required":true},{"key":"gait","label":"步态","unit":"","type":"select","options":[{"value":0,"label":"正常/卧床"},{"value":10,"label":"虚弱（10）"},{"value":20,"label":"步态异常（20）"}],"required":true},{"key":"mental","label":"精神状态（认知/理解力）","unit":"","type":"select","options":[{"value":0,"label":"正确认识自身能力"},{"value":15,"label":"高估/遗忘限制（15）"}],"required":true}],"formula":"6 项相加，0–125","compute":"sum","interpret":[{"when":"v >= 45","level":"crit","text":"高危（≥ 45）：立即实施全面防跌倒措施（床档、专人陪护、体位性低血压监测）"},{"when":"v >= 25 && v < 45","level":"high","text":"中危（25–44）：标准防跌倒措施，每小时巡视"},{"when":"v < 25","level":"ok","text":"低危（< 25）：常规护理与教育"}],"note":"化疗后疲乏、贫血、骨转移、使用阿片类药物者风险更高；老年科另有 geriatric_morse 条目（同表，别名）。","refs":["中国肿瘤患者跌倒预防管理专家共识（2021）","Morse JM, et al. 1989"]},{"id":"onco_nrs2002","name":"NRS2002 营养风险筛查","aka":["NRS 2002","营养风险筛查 2002"],"cat":"支持治疗","rank":5,"desc":"住院患者营养风险筛查，≥ 3 分需营养干预。","inputs":[{"key":"bmi_low","label":"BMI < 18.5","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是（3）"}],"required":true},{"key":"weight_loss","label":"近 1–3 个月体重下降","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"> 5%/3 月（1）"},{"value":2,"label":"> 5%/2 月（2）"},{"value":3,"label":"> 5%/1 月或 > 15%/3 月（3）"}],"required":true},{"key":"intake","label":"近 1 周食量减少","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"减少 25–50%（1）"},{"value":2,"label":"减少 50–75%（2）"},{"value":3,"label":"减少 > 75%（3）"}],"required":true},{"key":"severity","label":"疾病严重程度","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"轻度（髋部骨折、慢性病急性发作）（1）"},{"value":2,"label":"中度（大手术、卒中、重度肺炎、血液肿瘤）"},{"value":3,"label":"重度（ICU、APACHE > 10、颅脑创伤、骨髓移植）"}],"required":true},{"key":"age70","label":"年龄 ≥ 70 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"营养状况分（BMI、体重、食量取最高）+ 疾病分 + 年龄分","compute":"formula_only","algorithm":"nut = Math.max(bmi_low, weight_loss, intake); v = nut + severity + age70","interpret":[{"when":"v >= 5","level":"crit","text":"≥ 5 分：高营养风险，立即启动营养支持（肠内优先）"},{"when":"v >= 3","level":"high","text":"3–4 分：存在营养风险，制定营养干预方案并每周复评"},{"when":"v < 3","level":"ok","text":"< 3 分：暂无营养风险，每周复查"}],"note":"需实际测量身高体重；放疗、化疗期间恶化应复评；与 PG-SGA 联合使用更全面。老年科另有 geriatric_nrs2002。","refs":["肿瘤患者营养治疗指南（2019/2023）","ESPEN Guidelines on Nutrition in Cancer Patients (2017)"]},{"id":"onco_pgsga","name":"患者自评主观全面营养评估（PG-SGA）","aka":["PG-SGA","Patient-Generated SGA"],"cat":"支持治疗","rank":6,"desc":"肿瘤患者营养状况分级，指导营养干预强度。","inputs":[{"key":"weight","label":"体重情况（自评框）","unit":"","type":"select","options":[{"value":0,"label":"0 体重稳定/增加"},{"value":1,"label":"1–2 轻中度下降"},{"value":3,"label":"3–4 明显下降/持续下降"}],"required":true},{"key":"intake","label":"进食情况","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1–2 减少"},{"value":3,"label":"3 极少/仅液体"}],"required":true},{"key":"symptoms","label":"影响进食的症状（恶心、呕吐、吞咽困难等）","unit":"","type":"select","options":[{"value":0,"label":"0 无"},{"value":1,"label":"1–2 轻中度"},{"value":3,"label":"3 严重"}],"required":true},{"key":"function","label":"活动能力","unit":"","type":"select","options":[{"value":0,"label":"0 正常"},{"value":1,"label":"1–2 中度受限"},{"value":3,"label":"3 卧床"}],"required":true},{"key":"exam","label":"体格检查（脂肪/肌肉消耗）","unit":"","type":"select","options":[{"value":0,"label":"0 无消瘦"},{"value":1,"label":"1–2 轻中度"},{"value":3,"label":"3 重度"}],"required":true}],"formula":"自评框 A（体重、进食、症状、活动）+ 专业人员 B–D（疾病、代谢、体检）分级 A/B/C","compute":"formula_only","algorithm":"v = weight+intake+symptoms+function+exam（自评部分计分参考）\n分级：A 营养良好；B 中度营养不良；C 重度营养不良","interpret":[{"when":"exam >= 3 || weight >= 3","level":"crit","text":"重度营养不良（C 级）：立即肠内/肠外营养，考虑暂停或减量化疗"},{"when":"v >= 4","level":"high","text":"中度营养不良倾向（B 级）：营养咨询 + 口服营养补充（ONS），每周复评"},{"when":"v < 4","level":"ok","text":"营养良好（A 级）：饮食宣教，每 2–4 周复评"}],"note":"PG-SGA 含自评与专业评估两部分；本页为自评部分简化计分，正式分级须按完整量表；总分 ≥ 9 提示重度营养不良。","refs":["肿瘤患者营养治疗指南（2019/2023）","Ottery FD, 1994 (PG-SGA)"]},{"id":"onco_ctcae","name":"CTCAE 毒性分级参考（常见不良事件）","aka":["CTCAE","不良事件分级"],"cat":"支持治疗","rank":7,"desc":"按 CTCAE 5.0 对常见实验室/临床症状分级，指导是否减量或停药。","inputs":[{"key":"tox_type","label":"毒性类型","unit":"","type":"select","options":[{"value":1,"label":"中性粒细胞减少"},{"value":2,"label":"血小板减少"},{"value":3,"label":"贫血"},{"value":4,"label":"肝功能（ALT）"},{"value":5,"label":"肌酐升高"},{"value":6,"label":"腹泻"},{"value":7,"label":"周围神经病变"}],"required":true},{"key":"grade","label":"CTCAE 分级","unit":"","type":"select","options":[{"value":0,"label":"0 无"},{"value":1,"label":"1 轻度"},{"value":2,"label":"2 中度"},{"value":3,"label":"3 重度"},{"value":4,"label":"4 危及生命"},{"value":5,"label":"5 死亡"}],"required":true}],"formula":"按 CTCAE v5.0 分 1–5 级；本页仅给出通用处理原则","compute":"formula_only","algorithm":"v = grade","interpret":[{"when":"grade >= 4","level":"crit","text":"4 级：危及生命，停药并紧急处理，按方案永久减量/停药"},{"when":"grade == 3","level":"high","text":"3 级：暂停化疗至恢复 ≤ 1 级，下一周期减量 25–50%（按方案）"},{"when":"grade == 2","level":"warn","text":"2 级：对症处理，监测血象与生化，必要时延期"},{"when":"grade <= 1","level":"ok","text":"0–1 级：可按计划继续治疗"}],"note":"具体分级阈值需查 CTCAE v5.0 原文（如中性粒细胞 < 0.5 且伴发热为 3 级）；减量幅度以具体方案与说明书为准。","refs":["NCI CTCAE v5.0 (2017)","中国抗肿瘤药物不良反应管理专家共识（2020）"]},{"id":"onco_recist","name":"RECIST 1.1 疗效判读","aka":["RECIST 1.1","实体瘤疗效评价"],"cat":"疗效评估","rank":3,"desc":"基于可测量病灶径和变化判定 CR/PR/SD/PD。","inputs":[{"key":"baseline_sum","label":"基线靶病灶径和","unit":"mm","type":"number","min":1,"max":2000,"step":1,"required":true},{"key":"current_sum","label":"当前靶病灶径和","unit":"mm","type":"number","min":0,"max":3000,"step":1,"required":true},{"key":"new_lesion","label":"出现新病灶","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"nontarget_status","label":"非靶病灶状态","unit":"","type":"select","options":[{"value":0,"label":"完全消失"},{"value":1,"label":"稳定/未完全消失"},{"value":2,"label":"明确进展"}],"required":true},{"key":"lymph_nodes","label":"靶淋巴结短径是否均 < 10 mm","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未纳入"}],"required":true}],"formula":"疗效由径和变化率与是否新发病灶共同判定：CR 全部消失；PR ≥ 30% 缩小；PD ≥ 20% 增大且绝对值 ≥ 5 mm；SD 介于 PR 与 PD","compute":"formula_only","algorithm":"change = (current_sum - baseline_sum)/baseline_sum\nCR: current_sum==0 且淋巴结均<10mm 且非靶消失 且无新病灶\nPR: change <= -0.30 且非靶非进展\nPD: new_lesion==1 或 nontarget_status==2 或 (change >= 0.20 且 current_sum-baseline_sum >= 5)\n否则 SD\nv = change*100","interpret":[{"when":"new_lesion == 1 || nontarget_status == 2","level":"crit","text":"PD（进展）：出现新病灶或非靶明确进展，评估更换方案或局部治疗"},{"when":"current_sum <= baseline_sum * 0.7 && baseline_sum > 0","level":"high","text":"PR（部分缓解）：靶病灶径和缩小 ≥ 30%，继续方案并按周期复查"},{"when":"current_sum > baseline_sum * 1.2 && (current_sum - baseline_sum) >= 5","level":"high","text":"PD（进展）：径和增大 ≥ 20% 且 ≥ 5 mm，需确认（≥ 4 周后）"},{"when":"v <= 0","level":"ok","text":"SD（稳定）：未达 PR 也未达 PD"},{"when":"v > 0","level":"warn","text":"SD（稳定）：靶病灶略有增大但未达 PD"}],"note":"靶病灶最多 5 个（每器官 2 个）；淋巴结以短径计；PR/CR 需 ≥ 4 周后确认；免疫治疗建议用 iRECIST。","refs":["RECIST 1.1 (EJC 2009)","中国实体瘤疗效评估专家共识"]},{"id":"onco_tnm","name":"TNM 分期说明（第 8 版）","aka":["TNM","AJCC 8th"],"cat":"疗效评估","rank":8,"desc":"解释 T/N/M 定义与总体分期对应关系（不涉及具体瘤种的特殊分期表）。","inputs":[{"key":"t_stage","label":"T 分期","unit":"","type":"select","options":[{"value":0,"label":"T0 无原发灶证据"},{"value":1,"label":"Tis 原位癌"},{"value":2,"label":"T1 肿瘤小，局限"},{"value":3,"label":"T2 肿瘤较大，局限"},{"value":4,"label":"T3 侵犯局部结构"},{"value":5,"label":"T4 广泛侵犯/固定"}],"required":true},{"key":"n_stage","label":"N 分期","unit":"","type":"select","options":[{"value":0,"label":"N0 无区域淋巴结转移"},{"value":1,"label":"N1 区域淋巴结转移"},{"value":2,"label":"N2 多枚/较大区域淋巴结"},{"value":3,"label":"N3 广泛区域淋巴结"}],"required":true},{"key":"m_stage","label":"M 分期","unit":"","type":"select","options":[{"value":0,"label":"M0 无远处转移"},{"value":1,"label":"M1 远处转移"}],"required":true}],"formula":"TNM 组合映射为总体分期（Ⅰ–Ⅳ），具体阈值因瘤种而异","compute":"formula_only","algorithm":"v = t_stage*10 + n_stage + (m_stage?100:0)","interpret":[{"when":"m_stage == 1","level":"crit","text":"Ⅳ 期（M1）：远处转移，以全身治疗为主，评估局部治疗指征"},{"when":"t_stage >= 4 || n_stage >= 3","level":"high","text":"局部晚期（多为 Ⅲ 期）：多学科讨论（MDT），新辅助/同步放化疗"},{"when":"t_stage >= 2 || n_stage >= 1","level":"warn","text":"Ⅱ–Ⅲ 期（依瘤种）：手术 ± 辅助治疗"},{"when":"t_stage <= 1 && n_stage == 0","level":"ok","text":"早期（多为 0–Ⅰ 期）：以局部治疗（手术/内镜）为主"}],"note":"AJCC 第 8 版于 2018 年实施，2023 年起逐步被第 9 版取代（如乳腺癌、肺癌等）；各瘤种分期表不同（如结直肠、肺、肝），请对照对应瘤种分期表。","refs":["AJCC Cancer Staging Manual, 8th Edition (2017)","中国恶性肿瘤诊治规范（国家卫健委 2022）"]},{"id":"onco_caprini","name":"Caprini 血栓风险评分（肿瘤科入口）","aka":["Caprini","肿瘤患者 VTE 风险"],"cat":"支持治疗","rank":9,"desc":"肿瘤患者围手术期/住院 VTE 风险评估；完整版见血液科 heme_caprini。","inputs":[{"key":"age61_74","label":"年龄 61–74 岁（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"malignancy","label":"恶性肿瘤（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"major_surgery","label":"大手术 > 45 min（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"bedridden","label":"卧床 > 72 h（+2）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"bmi25","label":"BMI > 25（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"prior_vte","label":"既往 VTE（+3）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":3,"label":"是"}],"required":true}],"formula":"Caprini 评分（简化条目），与 heme_caprini 同表","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"极高危（≥ 5）：药物 + 机械预防，延长至术后 4 周"},{"when":"v >= 3","level":"high","text":"高危（3–4）：评估药物预防（低分子肝素），注意血小板与出血"},{"when":"v == 2","level":"warn","text":"中危（2）：机械预防为主"},{"when":"v <= 1","level":"ok","text":"低危：早期活动"}],"note":"肿瘤患者 VTE 风险还可用 Khorana 评分（门诊化疗者）；抗凝需评估血小板与出血风险。完整版见 heme.json 的 heme_caprini（同量表，别名）。","refs":["中国肿瘤相关静脉血栓栓塞症预防与治疗专家指南（2019）","CHEST Antithrombotic Therapy (2012)"]},{"id":"onco_tls_risk","name":"肿瘤溶解综合征（TLS）风险评估","aka":["TLS","Tumor Lysis Syndrome 风险"],"cat":"急症与并发症","rank":10,"desc":"按瘤种、瘤负荷与实验室指标评估 TLS 风险，指导水化与别嘌醇/拉布立酶。","inputs":[{"key":"high_risk_tumor","label":"高危瘤种（Burkitt、淋巴母细胞淋巴瘤、高负荷 AML/ALL）","unit":"","type":"select","options":[{"value":2,"label":"高危瘤种"},{"value":1,"label":"中危（DLBCL 大包块等）"},{"value":0,"label":"低危"}],"required":true},{"key":"ldh","label":"LDH > 2 倍正常上限","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"bulk","label":"大包块病灶（> 10 cm）或白细胞 > 100×10⁹/L","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"renal","label":"已有肾功能不全/脱水","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"风险分层：瘤种风险 + LDH 升高 + 瘤负荷 + 肾功能","compute":"sum","interpret":[{"when":"high_risk_tumor == 2 && (bulk == 1 || ldh == 1)","level":"crit","text":"高危 TLS：化疗前水化（2–3 L/m²/d），拉布立酶降尿酸，监测 K、P、Ca、尿酸、肌酐 6–8 h"},{"when":"v >= 3","level":"high","text":"中高危：水化 + 别嘌醇（GFR 正常 300 mg/d，遵说明书），48 h 内每小时监测"},{"when":"v >= 1","level":"warn","text":"中低危：口服水化 + 别嘌醇，每日监测电解质"},{"when":"v == 0","level":"ok","text":"低危：常规监测，不需常规预防"}],"note":"TLS 诊断（Cairo-Bishop）：尿酸、钾、磷升高和/或钙降低，伴肌酐升高或心律失常；拉布立酶禁用于 G6PD 缺乏者、妊娠。","refs":["肿瘤溶解综合征诊疗中国专家共识（2019）","NCCN Guidelines – B-Cell Lymphomas (2024)"]},{"id":"onco_opioid_conversion","name":"阿片类药物止痛滴定与换算参考","aka":["阿片换算表","Opioid Conversion"],"cat":"癌痛管理","rank":11,"desc":"参考性换算表（不自动开具处方），提示等效剂量关系与滴定原则。","inputs":[{"key":"current_opioid","label":"当前阿片药物","unit":"","type":"select","options":[{"value":1,"label":"吗啡口服"},{"value":2,"label":"羟考酮口服"},{"value":3,"label":"芬太尼透皮贴"},{"value":4,"label":"曲马多口服"}],"required":true},{"key":"daily_dose","label":"日总量（mg；贴剂为 μg/h）","unit":"","type":"number","min":0,"max":2000,"step":0.1,"required":true},{"key":"pain_vas","label":"疼痛评分 NRS","unit":"0–10","type":"number","min":0,"max":10,"step":1,"required":true}],"formula":"口服吗啡:口服羟考酮 ≈ 1.5:1；口服吗啡:芬太尼贴（μg/h）换算需按说明书；突破痛剂量为日总量的 10–15%（速释）","compute":"formula_only","algorithm":"v = daily_dose（参考值输出，不在本工具自动换算处方）","interpret":[{"when":"current_opioid == 1","level":"warn","text":"吗啡口服：突破痛按日总量 10–15% 给速释吗啡，1 h 后复评"},{"when":"current_opioid == 2","level":"warn","text":"羟考酮口服：注意便秘与中枢抑制，突破痛按日总量 10–15%"},{"when":"current_opioid == 3","level":"high","text":"芬太尼透皮：仅用于阿片耐受患者，发热/出汗时吸收增加，谨慎加量"},{"when":"current_opioid == 4","level":"warn","text":"曲马多：有癫痫与 5-HT 综合征风险，日剂量上限遵说明书"},{"when":"pain_vas >= 7","level":"crit","text":"重度疼痛（≥ 7）：考虑静脉/皮下滴定，按镇痛阶梯与本院流程"}],"note":"本品类转换须个体化，肾功能不全时吗啡/羟考酮代谢物蓄积，改用芬太尼或氢吗啡酮；本页不提供换算剂量，处方须遵说明书与《癌症疼痛诊疗规范》。","refs":["癌症疼痛诊疗规范（2018 年版，国家卫健委）","NCCN Adult Cancer Pain Guidelines (2024)"]},{"id":"onco_myelotoxicity_delay","name":"化疗骨髓抑制与剂量调整参考","aka":["骨髓抑制分级","剂量调整参考"],"cat":"支持治疗","rank":12,"desc":"按 ANC/血小板水平提示化疗延迟、减量与 G-CSF 使用。","inputs":[{"key":"anc","label":"ANC","unit":"×10⁹/L","type":"number","min":0,"max":20,"step":0.01,"required":true},{"key":"plt","label":"血小板","unit":"×10⁹/L","type":"number","min":1,"max":1000,"step":1,"required":true},{"key":"febrile","label":"粒缺伴发热","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"ANC ≥ 1.5、PLT ≥ 100 方可按计划化疗（多数方案）","compute":"formula_only","algorithm":"v = anc*100 + (plt>=100?1:0)","interpret":[{"when":"febrile == 1","level":"crit","text":"粒缺伴发热：停药 + 广谱抗菌 + G-CSF（按指南），下次化疗减量 25–50%"},{"when":"anc < 1.0 || plt < 50","level":"high","text":"3–4 级骨髓抑制：延期化疗至恢复，评估 G-CSF 与减量"},{"when":"anc < 1.5 || plt < 100","level":"warn","text":"2 级：延期 1 周复查，必要时给 G-CSF"},{"when":"v >= 151 && plt >= 100","level":"ok","text":"血象允许按计划化疗"}],"note":"剂量调整以具体方案（如 CHOP、FOLFOX）说明书与指南为准；既往 1 个周期发生粒缺发热者下周期预防性使用 G-CSF。","refs":["中国中性粒细胞缺乏伴发热患者抗菌药物临床应用指南（2020 年版）","CSCO 常见恶性肿瘤诊疗指南（2023）"]},{"id":"onco_ipi","name":"IPI 国际预后指数（弥漫大 B 细胞淋巴瘤）","aka":["IPI","International Prognostic Index"],"cat":"疗效评估","rank":13,"desc":"按年龄、LDH、体能状态、分期、结外累及对 DLBCL 预后分层。","inputs":[{"key":"age","label":"年龄 > 60 岁（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ldh","label":"LDH > 正常（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ps","label":"ECOG PS ≥ 2（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"stage","label":"Ann Arbor Ⅲ/Ⅳ 期（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"extranodal","label":"结外累及 > 1 处（+1）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"IPI = 5 项之和（0–5）","compute":"sum","interpret":[{"when":"v >= 4","level":"crit","text":"高危（4–5）：5 年 OS 约 26%；考虑强化方案（R-CHOP 加量/新药）与中枢预防"},{"when":"v == 3","level":"high","text":"中高危（3）：5 年 OS 约 43%，R-CHOP ± 新药"},{"when":"v >= 1 && v <= 2","level":"warn","text":"中低危（1–2）：5 年 OS 约 51–73%"},{"when":"v == 0","level":"ok","text":"低危（0）：5 年 OS 约 73%"}],"note":"年龄调整 IPI（aaIPI）用于 ≤ 60 岁；NCCN-IPI 对预后区分更好；中枢预防用于高危（双打击等）。","refs":["中国弥漫大B细胞淋巴瘤诊疗指南（2021）","International Non-Hodgkin Lymphoma Prognostic Factors Project, NEJM 1993"]},{"id":"onco_ps_care","name":"癌症患者姑息/支持治疗指征评估","aka":["姑息治疗指征","Palliative care triggers"],"cat":"支持治疗","rank":14,"desc":"综合体能状态、症状与预后因素提示启动姑息/安宁疗护。","inputs":[{"key":"ps","label":"ECOG PS","unit":"","type":"number","min":0,"max":4,"step":1,"required":true},{"key":"symptoms","label":"难以控制的症状（疼痛、呼吸困难、恶心）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true},{"key":"weight_loss","label":"6 个月内体重下降 > 10%","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true},{"key":"prognosis","label":"预计生存期 < 6 个月","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未知"}],"required":true}],"formula":"按 PS、症状负担、营养状况与预计生存期综合判断","compute":"sum","interpret":[{"when":"prognosis == 1 && (ps >= 3 || symptoms == 1 || weight_loss == 1)","level":"crit","text":"建议启动安宁疗护（hospice），多学科症状管理与家属沟通"},{"when":"ps >= 3 || symptoms == 1 || weight_loss == 1","level":"high","text":"建议早期姑息治疗联合放化疗（早期姑息可改善生活质量和生存）"},{"when":"v <= 0","level":"ok","text":"常规支持治疗与随访，每位晚期患者均应评估姑息需求"}],"note":"姑息治疗不等于放弃治疗；需进行生命末期讨论（预立医疗照护计划、DNR）；抑郁与谵妄需筛查。","refs":["中国安宁疗护实践指南（2020）","ASCO Recommendations Update on Palliative Care (2017)"]},{"id":"onco_mdrpi","name":"改良 D'Amico 前列腺癌风险分层","aka":["D'Amico 风险分组","前列腺癌风险"],"cat":"疗效评估","rank":15,"desc":"按 PSA、Gleason 评分与临床分期对前列腺癌行低/中/高危分层。","inputs":[{"key":"psa","label":"PSA","unit":"ng/mL","type":"number","min":0,"max":5000,"step":0.1,"required":true},{"key":"gleason","label":"Gleason 评分（ISUP 分级组 1–5）","unit":"","type":"select","options":[{"value":1,"label":"1 组（≤ 6）"},{"value":2,"label":"2 组（3+4=7）"},{"value":3,"label":"3 组（4+3=7）"},{"value":4,"label":"4 组（8）"},{"value":5,"label":"5 组（9–10）"}],"required":true},{"key":"t_stage","label":"临床 T 分期","unit":"","type":"select","options":[{"value":1,"label":"T1–T2a"},{"value":2,"label":"T2b–T2c"},{"value":3,"label":"T3a"},{"value":4,"label":"T3b–T4"}],"required":true}],"formula":"低危：PSA < 10 且 ISUP 1 且 T1–T2a；中危：PSA 10–20 或 ISUP 2–3 或 T2b；高危：PSA > 20 或 ISUP ≥ 4 或 ≥ T3a","compute":"formula_only","algorithm":"高危：psa>20 || gleason>=4 || t_stage>=3\n中危：psa>=10 || gleason>=2 || t_stage==2\n低危：其余\nv = psa","interpret":[{"when":"psa > 20 || gleason >= 4 || t_stage >= 3","level":"crit","text":"高危：根治性手术/放疗 + 长期 ADT，必要时新辅助"},{"when":"psa >= 10 || gleason >= 2 || t_stage == 2","level":"warn","text":"中危：根治性治疗（手术或放疗 ± ADT），评估 PSMA-PET 分期"},{"when":"v >= 0","level":"ok","text":"低危：主动监测或局部治疗，按预期寿命决策"}],"note":"Gleason 评分以主要 + 次要计；PSA 应取治疗前值；2014 ISUP 分级组与 NCCN 风险分组略有差异。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022，前列腺癌部分）","NCCN Prostate Cancer Guidelines (2024)"]},{"id":"onco_bmi_cachexia","name":"肿瘤恶病质诊断（Fearon 标准）","aka":["癌性恶病质","Cancer cachexia"],"cat":"支持治疗","rank":16,"desc":"按体重下降、BMI 与食欲功能判定肿瘤恶病质分期。","inputs":[{"key":"weight_loss_pct","label":"近 6 个月体重下降","unit":"%","type":"number","min":0,"max":50,"step":0.1,"required":true},{"key":"bmi","label":"BMI","unit":"kg/m²","type":"number","min":10,"max":50,"step":0.1,"required":true},{"key":"sarcopenia","label":"肌肉量减少（CT 或 BIA 证实）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否/未查"}],"required":true},{"key":"intake_low","label":"摄食减少或全身炎症（CRP 升高）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"恶病质：6 月体重下降 > 5%，或 BMI < 20 且下降 > 2%，或肌肉量减少且下降 > 2%","compute":"formula_only","algorithm":"v = weight_loss_pct","interpret":[{"when":"weight_loss_pct > 5 && intake_low == 1","level":"crit","text":"恶病质（难治期倾向）：营养支持 + 甲地孕酮/奥氮平促食欲（遵说明书），评估终止抗肿瘤治疗"},{"when":"weight_loss_pct > 5 || (bmi < 20 && weight_loss_pct > 2) || (sarcopenia == 1 && weight_loss_pct > 2)","level":"high","text":"符合肿瘤恶病质：ONS + 运动康复 + 抗炎（按指南），定期复评体重与握力"},{"when":"weight_loss_pct <= 2","level":"ok","text":"前恶病质/无明显体重下降：监测与早期干预"}],"note":"恶病质分级：前恶病质（< 5% 下降 + 厌食代谢改变）、恶病质（6 月 > 5%）、难治性（预期生存 < 3 月，对治疗无反应）；不可与饥饿性消耗混同。","refs":["肿瘤患者营养治疗指南（2023）","Fearon K, et al. Lancet Oncol 2011"]}]},"ortho":{"items":[{"id":"vas_pain","name":"疼痛视觉模拟评分（VAS 0–10）","aka":["Visual Analogue Scale","VAS"],"cat":"疼痛与功能评分","desc":"用 0–10 数字刻度自评疼痛强度，是骨科术后与慢性疼痛最常用的单维疼痛评估。","inputs":[{"key":"vas","label":"疼痛评分（0 无痛，10 最剧烈）","unit":"分","type":"number","min":0,"max":10,"step":1,"required":true}],"formula":"患者自评：0 = 无痛，10 = 能想象的最剧烈疼痛；NRS 数字评分法 0–10 与之等效","compute":"formula_only","algorithm":"v = vas","interpret":[{"when":"v == 0","level":"ok","text":"0 分：无痛，无需镇痛"},{"when":"v <= 3","level":"ok","text":"1–3 分：轻度疼痛，可口服对乙酰氨基酚/NSAIDs，按需多模式镇痛"},{"when":"v <= 6","level":"warn","text":"4–6 分：中度疼痛，建议多模式镇痛（NSAIDs + 弱阿片/曲马多）并每 4 小时复评"},{"when":"v <= 10","level":"high","text":"7–10 分：重度疼痛，需静脉镇痛或强阿片类，排查骨筋膜室综合征、血肿、感染、内固定失效等急症"}],"note":"术后静息 VAS >4 分提示镇痛不足；动态（活动时）评分可更高，影响早期下地与功能锻炼。","refs":["中华医学会骨科学分会：骨科围手术期镇痛专家共识（2016）","中国康复医学会：成人疼痛评估中国专家共识（2020）"],"rank":1},{"id":"nrs_pain","name":"数字评分法疼痛评估（NRS）","aka":["Numeric Rating Scale","NRS"],"cat":"疼痛与功能评分","desc":"以 0–10 口头数字评估疼痛，适用于术后、急诊与老年患者快速筛查，较 VAS 更易完成。","inputs":[{"key":"nrs","label":"NRS 评分","unit":"分","type":"number","min":0,"max":10,"step":1,"required":true}],"formula":"0 = 无痛；1–3 轻度；4–6 中度；7–10 重度","compute":"formula_only","algorithm":"v = nrs","interpret":[{"when":"v <= 3","level":"ok","text":"1–3 分：轻度疼痛，非阿片镇痛可控制"},{"when":"v <= 6","level":"warn","text":"4–6 分：中度疼痛，启动多模式镇痛并复评"},{"when":"v >= 7","level":"high","text":"7–10 分：重度疼痛，按急症处理：查原因（血肿、感染、骨筋膜室综合征、不稳定内固定）后加强镇痛"}],"note":"认知障碍或语言障碍者可用面部表情量表（Wong-Baker）或 FLACC（儿童），见儿科/老年科。","refs":["中华医学会骨科学分会：骨科围手术期镇痛专家共识（2016）","中国医师协会：术后疼痛管理专家共识（2021）"],"rank":2},{"id":"lys_ky_kss","name":"Lysholm 膝关节评分","aka":["Lysholm Knee Scoring Scale","LKS"],"cat":"脊柱与关节功能","desc":"评估膝关节功能（疼痛、不稳、肿胀、交锁、上楼、下蹲等 8 项），常用于 ACL 重建与半月板术后随访。","inputs":[{"key":"limp","label":"跛行","type":"select","options":[{"value":5,"label":"无"},{"value":3,"label":"轻度或偶尔"},{"value":0,"label":"持续严重"}],"required":true},{"key":"support","label":"支撑","type":"select","options":[{"value":5,"label":"不需要"},{"value":2,"label":"需手杖或拐杖"},{"value":0,"label":"不能负重"}],"required":true},{"key":"lock","label":"交锁感","type":"select","options":[{"value":15,"label":"无交锁"},{"value":10,"label":"有交锁但无卡住"},{"value":6,"label":"偶尔卡住"},{"value":2,"label":"经常卡住"},{"value":0,"label":"检查时即存在交锁"}],"required":true},{"key":"giving","label":"打软腿","type":"select","options":[{"value":25,"label":"无打软腿"},{"value":20,"label":"剧烈运动时偶尔"},{"value":15,"label":"日常活动时偶尔"},{"value":10,"label":"日常活动时经常"},{"value":0,"label":"每步均可发生"}],"required":true},{"key":"pain","label":"疼痛","type":"select","options":[{"value":25,"label":"无"},{"value":20,"label":"剧烈运动时偶有"},{"value":15,"label":"剧烈运动时明显"},{"value":10,"label":"走 2 km 以上后明显"},{"value":5,"label":"走 2 km 以内即出现"},{"value":0,"label":"持续严重"}],"required":true},{"key":"swelling","label":"肿胀","type":"select","options":[{"value":10,"label":"无"},{"value":6,"label":"剧烈运动时"},{"value":2,"label":"日常活动时"},{"value":0,"label":"持续"}],"required":true},{"key":"climb","label":"上下楼","type":"select","options":[{"value":10,"label":"无问题"},{"value":6,"label":"轻度困难"},{"value":2,"label":"每步都有困难"},{"value":0,"label":"不能"}],"required":true},{"key":"squat","label":"下蹲","type":"select","options":[{"value":5,"label":"无问题"},{"value":4,"label":"轻度困难"},{"value":2,"label":"不超过 90°"},{"value":0,"label":"不能下蹲"}],"required":true}],"formula":"Lysholm 总分 = 8 项得分之和（跛行 5 + 支撑 5 + 交锁 15 + 打软腿 25 + 疼痛 25 + 肿胀 10 + 上下楼 10 + 下蹲 5），满分 100","compute":"sum","interpret":[{"when":"v >= 95","level":"ok","text":"95–100 分：优，膝关节功能接近正常"},{"when":"v >= 84","level":"ok","text":"84–94 分：良，可恢复运动但剧烈运动需谨慎"},{"when":"v >= 65","level":"warn","text":"65–83 分：可，需继续康复训练（股四头肌与本体感觉）"},{"when":"v < 65","level":"high","text":"<65 分：差，需重新评估膝不稳、半月板或软骨损伤，考虑影像/关节镜"}],"note":"原始 Lysholm 总分 95 分（不含下蹲项），现常用加入下蹲项的 100 分版本，报告时需注明版本。","refs":["Lysholm J, Gillquist J. Am J Sports Med 1982;10:150-154（Lysholm 原版）","中华医学会运动医疗分会：前交叉韧带损伤诊疗专家共识（2021）"],"rank":1},{"id":"hss_knee","name":"HSS 膝关节评分","aka":["Hospital for Special Surgery Knee Score"],"cat":"脊柱与关节功能","desc":"评估人工膝关节置换术前膝关节功能与临床症状，满分 100（疼痛 30、功能 22、活动度 18、肌力 10、屈曲畸形 10、关节不稳 10）。","inputs":[{"key":"pain","label":"疼痛","type":"select","options":[{"value":30,"label":"无疼痛"},{"value":20,"label":"轻度/偶尔"},{"value":10,"label":"中度，需镇痛药"},{"value":5,"label":"持续剧痛需阿片"},{"value":0,"label":"完全残废"}],"required":true},{"key":"func","label":"功能（行走+上下楼）","type":"select","options":[{"value":22,"label":"行走不受限且上下楼正常"},{"value":15,"label":"行走 >1 km、上下楼轻度受限"},{"value":8,"label":"行走 0.5–1 km、需扶栏"},{"value":4,"label":"行走 <0.5 km、需扶手杖"},{"value":0,"label":"不能行走"}],"required":true},{"key":"rom","label":"活动度（屈伸）","type":"select","options":[{"value":18,"label":"≥120°"},{"value":15,"label":"100–119°"},{"value":12,"label":"90–99°"},{"value":8,"label":"70–89°"},{"value":4,"label":"50–69°"},{"value":0,"label":"<50°"}],"required":true},{"key":"strength","label":"肌力（股四头肌）","type":"select","options":[{"value":10,"label":"5 级"},{"value":8,"label":"4 级"},{"value":4,"label":"3 级"},{"value":0,"label":"≤2 级"}],"required":true},{"key":"deformity","label":"屈曲畸形","type":"select","options":[{"value":10,"label":"无"},{"value":8,"label":"5°–10°"},{"value":4,"label":"11°–15°"},{"value":0,"label":">15°"}],"required":true},{"key":"laxity","label":"关节不稳","type":"select","options":[{"value":10,"label":"无"},{"value":8,"label":"轻度（<5°）"},{"value":4,"label":"中度（5°–15°）"},{"value":0,"label":"重度（>15°）"}],"required":true}],"formula":"HSS = 疼痛 30 + 功能 22 + 活动度 18 + 肌力 10 + 屈曲畸形 10 + 关节不稳 10，满分 100；扣分项：需手杖 −5、伸膝受限 5° −2（每 5°）、内外翻畸形 −1/5°。","compute":"sum","interpret":[{"when":"v >= 85","level":"ok","text":"85–100 分：优，KNEE 功能良好"},{"when":"v >= 70","level":"ok","text":"70–84 分：良，可门诊随访与继续肌力训练"},{"when":"v >= 60","level":"warn","text":"60–69 分：可，需评估内翻/外翻畸形与屈曲挛缩，复评是否需要翻修或康复强化"},{"when":"v < 60","level":"high","text":"<60 分：差，建议影像学（下肢全长片）与翻修评估"}],"note":"HSS 主要用于 TKA 前后评估；术后含减分项，报告时应同时给出影像学力线与内外翻畸形。","refs":["Insall JN, et al. Clin Orthop Relat Res 1976;121:76-79（HSS 原版）","中华医学会骨科学分会关节外科学组：骨关节炎诊疗指南（2018）"],"rank":2},{"id":"oswestry_odi","name":"Oswestry 功能障碍指数（ODI）","aka":["Oswestry Disability Index","ODI"],"cat":"脊柱与关节功能","desc":"评估腰痛对日常生活的影响（10 个方面），是腰椎手术与保守治疗疗效评价的核心指标。","inputs":[{"key":"pain","label":"疼痛程度","type":"select","options":[{"value":0,"label":"无痛"},{"value":1,"label":"轻微"},{"value":2,"label":"中度"},{"value":3,"label":"较重"},{"value":4,"label":"严重"},{"value":5,"label":"极严重"}],"required":true},{"key":"selfcare","label":"自理（穿衣洗漱）","type":"select","options":[{"value":0,"label":"不需帮助"},{"value":1,"label":"需帮助但可独立"},{"value":2,"label":"需间歇帮助"},{"value":3,"label":"需大部分帮助"},{"value":4,"label":"日常生活大部分不能完成"},{"value":5,"label":"卧床、穿衣困难需人帮助"}],"required":true},{"key":"lift","label":"提物","type":"select","options":[{"value":0,"label":"可提重物"},{"value":1,"label":"可提重物但引起疼痛"},{"value":2,"label":"不能从地面提物"},{"value":3,"label":"只能提轻物"},{"value":4,"label":"只能提很轻物品"},{"value":5,"label":"不能提任何物品"}],"required":true},{"key":"walk","label":"行走","type":"select","options":[{"value":0,"label":"行走无限制"},{"value":1,"label":"可走 1 km 以上"},{"value":2,"label":"可走 500 m"},{"value":3,"label":"可走 100 m"},{"value":4,"label":"需手杖或拐杖"},{"value":5,"label":"卧床，需他人帮助如厕"}],"required":true},{"key":"sit","label":"坐","type":"select","options":[{"value":0,"label":"可任意坐"},{"value":1,"label":"可坐 1 小时以上"},{"value":2,"label":"可坐 30 分钟"},{"value":3,"label":"可坐 10 分钟"},{"value":4,"label":"只能坐几分钟"},{"value":5,"label":"不能坐"}],"required":true},{"key":"stand","label":"站立","type":"select","options":[{"value":0,"label":"可站任意久"},{"value":1,"label":"可站 1 小时"},{"value":2,"label":"可站 30 分钟"},{"value":3,"label":"可站 10 分钟"},{"value":4,"label":"只能站几分钟"},{"value":5,"label":"不能站"}],"required":true},{"key":"sleep","label":"睡眠","type":"select","options":[{"value":0,"label":"睡眠不受影响"},{"value":1,"label":"偶有疼痛影响"},{"value":2,"label":"睡眠受影响 <2 小时"},{"value":3,"label":"睡眠受影响 2–4 小时"},{"value":4,"label":"睡眠受影响 4–6 小时"},{"value":5,"label":"几乎不能入睡"}],"required":true},{"key":"social","label":"社交","type":"select","options":[{"value":0,"label":"正常社交"},{"value":1,"label":"社交稍受限"},{"value":2,"label":"社交明显受限但可参与"},{"value":3,"label":"社交受限"},{"value":4,"label":"很少外出"},{"value":5,"label":"不能外出"}],"required":true},{"key":"travel","label":"出行","type":"select","options":[{"value":0,"label":"可任意出行"},{"value":1,"label":"出行有疼痛"},{"value":2,"label":"需 1 小时以上才能出行"},{"value":3,"label":"外出受限"},{"value":4,"label":"只能在床上附近活动"},{"value":5,"label":"不能出行"}],"required":true},{"key":"work","label":"工作/家务","type":"select","options":[{"value":0,"label":"可正常从事重体力劳动"},{"value":1,"label":"可从事但不能重体力"},{"value":2,"label":"可从事轻工作的大部分工作"},{"value":3,"label":"只能从事轻工作不多"},{"value":4,"label":"几乎不能工作"},{"value":5,"label":"不能工作，需帮助"}],"required":true}],"formula":"ODI = 实际得分 / 可能满分（5×完成题数）×100%；10 题，每项 0–5 分，满分 50","compute":"formula_only","algorithm":"answered = 实际完成的题数（≥1 项）\nv = round(sum(各项分) / (5 * answered) * 100, 1)","interpret":[{"when":"v <= 20","level":"ok","text":"0%–20%：轻度失能，可保守治疗（康复、物理治疗）"},{"when":"v <= 40","level":"warn","text":"21%–40%：中度失能，需强化保守治疗，评估神经症状与影像学"},{"when":"v <= 60","level":"high","text":"41%–60%：重度失能，建议脊柱外科评估手术指征（如保守 6 周无效）"},{"when":"v <= 80","level":"high","text":"61%–80%：严重失能，多数需手术干预"},{"when":"v > 80","level":"crit","text":">80%：卧床残疾，需尽快手术或住院康复"}],"note":"ODI 变化 <10% 一般视为临床无意义变化；中文版 ODI 2.1 已在国内验证。","refs":["Fairbank JC, et al. Physiotherapy 1980;66:271-273（ODI 原版）","中华医学会骨科学分会脊柱外科学组：腰椎间盘突出症诊疗指南（2020）","Chinese ODI 2.1 中文版信效度验证研究（2016）"],"rank":3},{"id":"joa_cervical","name":"JOA 颈椎功能评分","aka":["Japanese Orthopaedic Association Cervical Score","JOA 颈椎"],"cat":"脊柱与关节功能","desc":"评估颈椎病（脊髓型）上肢运动、下肢运动、感觉与膀胱功能，常用 JOA 改善率评价疗效。","inputs":[{"key":"upper","label":"上肢运动功能","type":"select","options":[{"value":4,"label":"正常"},{"value":3,"label":"可完成精细动作（握筷、写字）"},{"value":2,"label":"可握匙但精细动作困难"},{"value":1,"label":"可持物但不能握匙"},{"value":0,"label":"不能自己进食/穿衣"}],"required":true},{"key":"lower","label":"下肢运动功能","type":"select","options":[{"value":4,"label":"正常"},{"value":3,"label":"可行走但肢体僵硬或轻度不稳"},{"value":2,"label":"可上下楼但需扶"},{"value":1,"label":"平地走不稳需扶"},{"value":0,"label":"不能行走"}],"required":true},{"key":"sens_upper","label":"上肢感觉","type":"select","options":[{"value":2,"label":"正常"},{"value":1,"label":"轻度减退"},{"value":0,"label":"明显减退或疼痛"}],"required":true},{"key":"sens_lower","label":"下肢感觉","type":"select","options":[{"value":2,"label":"正常"},{"value":1,"label":"轻度减退"},{"value":0,"label":"明显减退或疼痛"}],"required":true},{"key":"trunk","label":"躯干感觉","type":"select","options":[{"value":2,"label":"正常"},{"value":1,"label":"轻度减退"},{"value":0,"label":"明显减退或疼痛"}],"required":true},{"key":"bladder","label":"膀胱功能","type":"select","options":[{"value":3,"label":"正常"},{"value":2,"label":"轻度排尿困难或尿频"},{"value":1,"label":"明显排尿困难或失禁"},{"value":0,"label":"尿潴留/不能自主排尿"}],"required":true}],"formula":"JOA = 上肢运动 4 + 下肢运动 4 + 上肢感觉 2 + 下肢感觉 2 + 躯干感觉 2 + 膀胱功能 3，满分 17；改善率 =（末次 − 术前）/（17 − 术前）×100%","compute":"sum","interpret":[{"when":"v >= 15","level":"ok","text":"15–17 分：轻度受累，可保守治疗（颈托、理疗、营养神经药）"},{"when":"v >= 12","level":"warn","text":"12–14 分：中度受累，密切随访；如进行性加重或 MRI 显示明显脊髓受压，讨论手术"},{"when":"v <= 11","level":"high","text":"≤11 分：重度脊髓功能障碍，建议尽早行椎管减压手术（前路/后路），避免跌倒与颈部外伤"}],"note":"改善率 ≥75% 为优、50%–74% 为良、25%–49% 可、<25% 差（Hirabayashi 法）。脊髓型颈椎病出现下肢不稳、大小便障碍时应手术。","refs":["日本整形外科学会（JOA）颈椎病疗效判定标准（1994 修订）","中华医学会骨科学分会：颈椎病诊治与康复指南（2018）","Hirabayashi K, et al. Spine 1981（JOA 改善率法）"],"rank":4},{"id":"harris_hip","name":"Harris 髋关节评分（HHS）","aka":["Harris Hip Score","HHS"],"cat":"脊柱与关节功能","desc":"评估髋关节疼痛、功能、畸形与活动度，用于髋关节置换（THA）与非置换治疗前后比较，满分 100。","inputs":[{"key":"pain","label":"疼痛","type":"select","options":[{"value":44,"label":"无或可忽略"},{"value":40,"label":"轻度、偶发，不影响活动"},{"value":30,"label":"轻度疼痛，需偶尔服镇痛药"},{"value":20,"label":"中度疼痛，活动受限，需口服 NSAIDs"},{"value":10,"label":"明显疼痛，活动严重受限"},{"value":0,"label":"完全残废、卧床痛"}],"required":true},{"key":"gait","label":"步态跛行","type":"select","options":[{"value":11,"label":"无"},{"value":8,"label":"轻度"},{"value":5,"label":"中度"},{"value":0,"label":"严重"}],"required":true},{"key":"support","label":"助行器","type":"select","options":[{"value":11,"label":"不需"},{"value":7,"label":"长距离需手杖"},{"value":5,"label":"持续需手杖"},{"value":4,"label":"单拐"},{"value":2,"label":"双手杖"},{"value":0,"label":"不能行走"}],"required":true},{"key":"distance","label":"步行距离","type":"select","options":[{"value":11,"label":">1000 m"},{"value":8,"label":"500–1000 m"},{"value":5,"label":"200–500 m"},{"value":2,"label":"仅室内"},{"value":0,"label":"卧床/坐轮椅"}],"required":true},{"key":"stairs","label":"上下楼","type":"select","options":[{"value":4,"label":"正常"},{"value":2,"label":"需扶栏"},{"value":1,"label":"一步一步"},{"value":0,"label":"不能"}],"required":true},{"key":"shoes","label":"穿脱鞋袜","type":"select","options":[{"value":4,"label":"容易"},{"value":2,"label":"困难"},{"value":0,"label":"不能"}],"required":true},{"key":"sit","label":"坐","type":"select","options":[{"value":5,"label":"正常、可坐 1 小时"},{"value":3,"label":"坐高椅 30 分钟"},{"value":0,"label":"任何椅子坐不住"}],"required":true},{"key":"transport","label":"乘坐交通工具","type":"select","options":[{"value":1,"label":"可以进入并使用公共汽车"},{"value":0,"label":"不能"}],"required":true},{"key":"rom","label":"活动度（屈髋等综合）","type":"select","options":[{"value":5,"label":"正常或接近正常"},{"value":3,"label":"轻度受限"},{"value":1,"label":"中度受限"},{"value":0,"label":"严重受限/强直"}],"required":true},{"key":"deformity","label":"畸形（固定屈曲/内收/内外旋）","type":"select","options":[{"value":4,"label":"无畸形"},{"value":0,"label":"存在固定畸形"}],"required":true}],"formula":"HHS = 疼痛 44 + 功能（步态 11、助行器 11、步行距离 11、上下楼 4、穿鞋 4、坐 5、乘车 1）+ 活动度 5 + 畸形 4；轻度跛行另行减 1 分（含在步态项内）。","compute":"sum","interpret":[{"when":"v >= 90","level":"ok","text":"90–100 分：优，髋关节功能良好"},{"when":"v >= 80","level":"ok","text":"80–89 分：良，可继续康复训练"},{"when":"v >= 70","level":"warn","text":"70–79 分：可，需评估疼痛来源（假体松动/感染/髂腰肌），必要时影像学"},{"when":"v < 70","level":"high","text":"<70 分：差，建议 X 线/CT 评估假体位置与松动，考虑翻修"}],"note":"HHS 有天花板效应，近年多用 HOOS/WOMAC 等患者报告结局（PROMs）；THA 术后良好者通常在 90 分以上。","refs":["Harris WH. J Bone Joint Surg Am 1969;51:737-755（Harris 髋评分原版）","中华医学会骨科学分会关节外科学组：髋关节骨关节炎诊疗指南（2021）"],"rank":5},{"id":"gcs_ortho","name":"Glasgow 昏迷评分（骨科创伤）","aka":["Glasgow Coma Scale","GCS"],"cat":"创伤与多发伤","desc":"评估意识水平（睁眼 4 + 言语 5 + 运动 6，3–15 分），骨科多发伤患者入院必评，用于判断颅脑合并伤。","inputs":[{"key":"eye","label":"睁眼","type":"select","options":[{"value":4,"label":"自动睁眼"},{"value":3,"label":"呼唤睁眼"},{"value":2,"label":"疼痛刺激睁眼"},{"value":1,"label":"无睁眼"}],"required":true},{"key":"verbal","label":"言语","type":"select","options":[{"value":5,"label":"回答切题"},{"value":4,"label":"言语混乱"},{"value":3,"label":"不恰当词语"},{"value":2,"label":"无法理解的声音"},{"value":1,"label":"无言语"}],"required":true},{"key":"motor","label":"运动","type":"select","options":[{"value":6,"label":"遵嘱动作"},{"value":5,"label":"疼痛定位"},{"value":4,"label":"疼痛回撤"},{"value":3,"label":"异常屈曲（去皮层）"},{"value":2,"label":"异常伸展（去脑）"},{"value":1,"label":"无反应"}],"required":true}],"formula":"GCS = 睁眼（1–4）+ 言语（1–5）+ 运动（1–6），总分 3–15","compute":"sum","interpret":[{"when":"v <= 8","level":"crit","text":"3–8 分：重度颅脑损伤，需立即气道保护（气管插管）与神经外科/ICU 会诊，推迟非紧急骨科手术"},{"when":"v <= 12","level":"high","text":"9–12 分：中度颅脑损伤，需 CT 与神外会诊，骨科手术权衡时机"},{"when":"v <= 15","level":"ok","text":"13–15 分：轻度损伤/清醒，可按计划处理骨科损伤"}],"note":"气管插管患者言语项记为 1T，与运动/睁眼合并报告（如 E1V1tM6 = 8t）。老年、镇静状态需注明。","refs":["Teasdale G, Jennett B. Lancet 1974;2:81-84（GCS 原版）","中华医学会创伤学分会：重型颅脑创伤救治指南（2019）","中国医师协会创伤外科医师分会：多发伤救治专家共识（2020）"],"rank":1},{"id":"rts","name":"修订创伤评分（RTS）","aka":["Revised Trauma Score","RTS"],"cat":"创伤与多发伤","desc":"依据 GCS、收缩压与呼吸频率评估创伤严重度，是 TRISS 生存概率预测的生理学部分。","inputs":[{"key":"gcs","label":"GCS 评分","type":"select","options":[{"value":4,"label":"13–15"},{"value":3,"label":"9–12"},{"value":2,"label":"6–8"},{"value":1,"label":"4–5"},{"value":0,"label":"3"}],"required":true},{"key":"sbp","label":"收缩压","type":"select","options":[{"value":4,"label":"≥90 mmHg"},{"value":3,"label":"76–89"},{"value":2,"label":"50–75"},{"value":1,"label":"1–49"},{"value":0,"label":"0"}],"required":true},{"key":"rr","label":"呼吸频率","type":"select","options":[{"value":4,"label":"10–29 次/分"},{"value":3,"label":"≥30"},{"value":2,"label":"6–9"},{"value":1,"label":"1–5"},{"value":0,"label":"0"}],"required":true}],"formula":"编码 RTS（现场）= 0.9368×GCS编码 + 0.7326×SBP编码 + 0.2908×RR编码（0–7.8408）；简易 RTS（T-RTS）= 三项编码之和（0–12）","compute":"sum","interpret":[{"when":"v >= 11","level":"ok","text":"T-RTS 11–12：轻度生理紊乱，按创伤流程评估"},{"when":"v <= 10 && v >= 9","level":"warn","text":"T-RTS 9–10：中度生理紊乱，需住院监护"},{"when":"v <= 8 && v >= 7","level":"high","text":"T-RTS 7–8：重度生理紊乱，建议入创伤中心/ICU"},{"when":"v <= 6","level":"crit","text":"T-RTS ≤6：极重度（病死率高），立即复苏与损伤控制手术"}],"note":"本输入的 v 为三项编码之和（T-RTS，0–12），非加权 RTS 概率值；加权 RTS 需在 engine 中按公式计算。","refs":["Champion HR, et al. J Trauma 1989;29:623-629（RTS 原版）","中国医师协会创伤外科医师分会：创伤评分应用专家共识（2018）"],"rank":2},{"id":"iss","name":"损伤严重度评分（ISS）","aka":["Injury Severity Score","ISS"],"cat":"创伤与多发伤","desc":"按 AIS 对全身 6 个区域中最重 3 处损伤平方求和，是判定「严重多发伤」的标准（ISS ≥16）。","inputs":[{"key":"ais1","label":"最重损伤区 AIS 编码","type":"number","min":1,"max":6,"step":1,"required":true},{"key":"ais2","label":"次重损伤区 AIS 编码","type":"number","min":1,"max":6,"step":1,"required":false},{"key":"ais3","label":"第三损伤区 AIS 编码","type":"number","min":1,"max":6,"step":1,"required":false}],"formula":"ISS = AIS₁² + AIS₂² + AIS₃²（取 6 个身体区域中 AIS 最大的 3 个区域，AIS 6 分则 ISS 直接记 75）；AIS 区域：头颈、面部、胸部、腹部及盆腔脏器、四肢及骨盆、体表。","compute":"formula_only","algorithm":"if ais1 == 6 or ais2 == 6 or ais3 == 6: v = 75\nelse: v = ais1*ais1 + (ais2 or 0)**2 + (ais3 or 0)**2","interpret":[{"when":"v < 16","level":"ok","text":"ISS <16：轻–中度损伤，病死率较低，按常规创伤救治"},{"when":"v <= 24","level":"warn","text":"ISS 16–24：严重多发伤，进入创伤中心抢救流程（大出血、气道、颅脑优先）"},{"when":"v <= 49","level":"high","text":"ISS 25–49：重度损伤，病死率明显升高，建议损伤控制外科与 ICU"},{"when":"v >= 50","level":"crit","text":"ISS ≥50：极重度损伤，病死率高（>50%），优先损伤控制复苏"}],"note":"每一区域的 AIS 只能取一次，同一区域多处损伤不重复计算；AIS 以 2005/2008 版为基础。","refs":["Baker SP, et al. J Trauma 1974;14:187-196（ISS 原版）","中国医师协会创伤外科医师分会：多发伤诊疗规范（2021）"],"rank":3},{"id":"gustilo_anderson","name":"Gustilo-Anderson 开放骨折分型","aka":["Gustilo-Anderson","开放骨折分型"],"cat":"骨折分型","desc":"按伤口大小、软组织损伤程度与污染情况对开放骨折分型，决定清创时机、抗生素与固定方式。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ型","criteria":"伤口 <1 cm，清洁，软组织损伤轻微，骨端不暴露","level":"ok"},{"label":"Ⅱ型","criteria":"伤口 1–10 cm，中度软组织损伤，无大面积撕脱或失活组织","level":"warn"},{"label":"ⅢA 型","criteria":"伤口 >10 cm，广泛软组织损伤，但骨仍有软组织覆盖（含高能量/农业/枪伤）","level":"high"},{"label":"ⅢB 型","criteria":"广泛软组织损伤伴骨膜剥离与骨外露，需软组织覆盖（皮瓣/肌瓣）","level":"high"},{"label":"ⅢC 型","criteria":"任何开放骨折合并需要修复的动脉损伤（无论伤口大小）","level":"crit"}],"note":"所有开放骨折均需在伤后 6–8 小时内清创并早期静脉抗生素：Ⅰ/Ⅱ型用一代头孢，Ⅲ型加用氨基糖苷类；ⅢC 需血管外科会诊并尽快重建血运。破伤风预防按免疫史执行。","refs":["Gustilo RB, Anderson JT. J Bone Joint Surg Am 1976;58:453-458（原版分型）","Gustilo RB, et al. J Bone Joint Surg Am 1984;66:113-121（Ⅲ型细分）","中华医学会骨科学分会创伤骨科学组：开放骨折诊疗指南（2019）"],"rank":1},{"id":"danis_weber","name":"Danis-Weber 踝关节骨折分型","aka":["Weber 分型","Danis-Weber"],"cat":"骨折分型","desc":"以腓骨骨折线相对胫距关节（下胫腓联合）的水平位置分型，决定下胫腓是否需固定。","inputs":[],"compute":"formula_only","levels":[{"label":"A 型","criteria":"腓骨骨折位于下胫腓联合以下（多为外踝横形骨折，下胫腓联合完整）","level":"ok"},{"label":"B 型","criteria":"腓骨骨折位于下胫腓联合水平（腓骨远端螺旋/斜形），可能伴下胫腓联合损伤","level":"warn"},{"label":"C 型","criteria":"腓骨骨折位于下胫腓联合以上（腓骨中下段），下胫腓联合均损伤，为不稳定骨折","level":"high"}],"note":"Weber 分型与 Lauge-Hansen 联合使用：A 型对应旋后-内收，B 型多为旋后-外旋，C 型多为旋前-外旋。B 型需在术中应力试验评估下胫腓稳定性。","refs":["Danis R. Arch Chirurg Belg 1949（原版）","Weber BG. AO/ASIF 踝部骨折分类（1972）","中华医学会骨科学分会创伤骨科学组：踝关节骨折诊疗指南（2018）"],"rank":2},{"id":"lauge_hansen","name":"Lauge-Hansen 踝关节骨折分型","aka":["Lauge-Hansen Classification"],"cat":"骨折分型","desc":"按受伤时足的位置（旋前/旋后）与暴力方向（外旋/内收/外展）描述踝部韧带与骨折损伤顺序，指导复位与固定。","inputs":[],"compute":"formula_only","levels":[{"label":"旋后-内收（SA）","criteria":"Ⅰ期外踝横形骨折 → Ⅱ期内踝垂直骨折（或内侧副韧带断裂），常伴距骨内移","level":"ok"},{"label":"旋后-外旋（SER）","criteria":"Ⅰ期下胫腓前韧带 → Ⅱ期腓骨远端螺旋骨折（后下至前上）→ Ⅲ期下胫腓后韧带或后踝骨折 → Ⅳ期内踝骨折/三角韧带断裂","level":"warn"},{"label":"旋前-外旋（PER）","criteria":"Ⅰ期内踝骨折/三角韧带断裂 → Ⅱ期下胫腓前韧带 → Ⅲ期高位腓骨骨折（>7 cm，Maisonneuve）→ Ⅳ期后踝骨折/下胫腓后韧带","level":"high"},{"label":"旋前-外展（PA）","criteria":"Ⅰ期内踝骨折 → Ⅱ期下胫腓前/后韧带 → Ⅲ期下胫腓联合以上腓骨短斜形骨折伴外侧撞击","level":"high"}],"note":"SER 为最常见类型（约 60%）；PER 需警惕 Maisonneuve 骨折，X 线片应包含腓骨全长。部分损伤需应力试验判断不稳定。","refs":["Lauge-Hansen N. Arch Surg 1950;60:957-985（原版）","中华医学会骨科学分会创伤骨科学组：踝关节骨折诊疗指南（2018）"],"rank":3},{"id":"garden","name":"Garden 分型（股骨颈骨折）","aka":["Garden Classification"],"cat":"骨折分型","desc":"依据骨折移位程度对股骨颈骨折分型，指导内固定（Ⅰ–Ⅱ型）或关节置换（Ⅲ–Ⅳ型）的选择。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ型","criteria":"不完全骨折（嵌插型），股骨颈外展、骨小梁内折，内侧骨皮质完整","level":"ok"},{"label":"Ⅱ型","criteria":"完全骨折但无移位（股骨颈轴线夹角正常）","level":"warn"},{"label":"Ⅲ型","criteria":"完全骨折伴部分移位（股骨头内旋、外展，骨小梁紊乱）","level":"high"},{"label":"Ⅳ型","criteria":"完全骨折伴完全移位（股骨头原始位置恢复，股骨干外旋上移）","level":"crit"}],"note":"Pauwels 分型按骨折线角度（<30°、30–50°、>50°）评估剪切力，角度越大越不稳定。年龄 >65 岁、移位型多首选关节置换；年轻患者优先内固定并注意股骨头坏死与骨不连。","refs":["Garden RS. J Bone Joint Surg Br 1961;43:647-663（原版）","中华医学会骨科学分会创伤骨科学组：老年髋部骨折诊疗专家共识（2017）","中国医师协会骨科医师分会：股骨颈骨折诊疗指南（2021）"],"rank":4},{"id":"pauwels","name":"Pauwels 分型（股骨颈骨折）","aka":["Pauwels Classification"],"cat":"骨折分型","desc":"按股骨颈骨折线与水平线的夹角（Pauwels 角）评估剪切负荷，角度越大骨不连与股骨头坏死风险越高。","inputs":[{"key":"angle","label":"骨折线角度","type":"select","options":[{"value":1,"label":"Ⅰ型：<30°（骨折线接近水平）"},{"value":2,"label":"Ⅱ型：30°–50°"},{"value":3,"label":"Ⅲ型：>50°（骨折线接近垂直）"}],"required":true}],"formula":"Pauwels Ⅰ：<30°（压应力为主）；Ⅱ：30°–50°；Ⅲ：>50°（剪切应力为主）","compute":"sum","interpret":[{"when":"angle == 1","level":"ok","text":"Ⅰ型：稳定型，剪切力小，内固定后愈合率高"},{"when":"angle == 2","level":"warn","text":"Ⅱ型：中等不稳定，建议多枚螺钉强力内固定，术后避免早期负重"},{"when":"angle == 3","level":"high","text":"Ⅲ型：高度不稳定（垂直剪切），骨不连与股骨头坏死风险高；老年患者优先考虑关节置换"}],"note":"Pauwels 分型对年轻股骨颈骨折判断预后更敏感；测量应在正位 X 线上以骨折线为准。","refs":["Pauwels F. Z Orthop 1935（原版）","中华医学会骨科学分会创伤骨科学组：股骨颈骨折内固定治疗专家共识（2020）"],"rank":5},{"id":"neer_prox_humerus","name":"Neer 分型（肱骨近端骨折）","aka":["Neer Classification"],"cat":"骨折分型","desc":"按肱骨头、大结节、小结节、肱骨干四个解剖部分是否移位（≥1 cm 或 ≥45°）分型，指导手术方式。","inputs":[],"compute":"formula_only","levels":[{"label":"一部分骨折","criteria":"各骨折块移位 <1 cm 且成角 <45°（含无移位骨折），保守治疗","level":"ok"},{"label":"二部分骨折","criteria":"1 个骨折块移位 ≥1 cm 或成角 ≥45°（外科颈、大结节、小结节或解剖颈移位）","level":"warn"},{"label":"三部分骨折","criteria":"2 个骨折块移位（常为肱骨头 + 大小结节 + 骨干构成三部分）","level":"high"},{"label":"四部分骨折","criteria":"肱骨头、大结节、小结节、骨干均移位，肱骨头血供受损风险高","level":"crit"}],"note":"Neer 分型重复一致性中等（尤其在三/四部分之间），需结合 3D-CT；老年四部分骨折可考虑反式肩关节置换，年轻患者优先切开复位内固定。骨折脱位需单独标注。","refs":["Neer CS. J Bone Joint Surg Am 1970;52:1077-1089（原版）","中华医学会骨科学分会创伤骨科学组：肱骨近端骨折诊疗指南（2020）"],"rank":6},{"id":"schatzker","name":"Schatzker 分型（胫骨平台骨折）","aka":["Schatzker Classification"],"cat":"骨折分型","desc":"按骨折累及的内外侧平台与关节面压缩程度分型（Ⅰ–Ⅵ），是胫骨平台骨折手术方案选择的基础。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ型","criteria":"外侧平台劈裂骨折（无压缩），多见于年轻患者","level":"ok"},{"label":"Ⅱ型","criteria":"外侧平台劈裂 + 压缩骨折","level":"warn"},{"label":"Ⅲ型","criteria":"外侧平台单纯压缩骨折（关节面塌陷，多为骨质疏松老年患者）","level":"warn"},{"label":"Ⅳ型","criteria":"内侧平台骨折（可伴外侧平台骨折与髁间棘），常伴韧带/半月板损伤","level":"high"},{"label":"Ⅴ型","criteria":"双髁骨折（内外侧平台均受累，干骺端完整）","level":"high"},{"label":"Ⅵ型","criteria":"双髁骨折合并胫骨近端干骺端与骨干分离（骨折-脱位型）","level":"crit"}],"note":"Ⅳ–Ⅵ型为高能量损伤，需评估软组织条件（Schatzker Ⅵ 常需跨关节外固定架分期处理）；术中导航/关节镜辅助可提高关节面复位质量。需查血管与骨筋膜室。","refs":["Schatzker J, et al. Clin Orthop Relat Res 1979;138:94-104（原版）","中华医学会骨科学分会创伤骨科学组：胫骨平台骨折诊疗专家共识（2019）"],"rank":7},{"id":"salter_harris","name":"Salter-Harris 骨骺损伤分型","aka":["Salter-Harris Classification","骨骺损伤分型"],"cat":"骨折分型","desc":"按骨折线相对骨骺板的位置（SALTR）对儿童骨骺损伤分型，预测生长障碍风险。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ型","criteria":"骨折线仅穿过骺板（Slipped），X 线可正常，需临床压痛判断","level":"ok"},{"label":"Ⅱ型","criteria":"骨折线穿过骺板并累及干骺端（Above，最常见）","level":"ok"},{"label":"Ⅲ型","criteria":"骨折线穿过骺板并累及骨骺（Lower/关节内）","level":"warn"},{"label":"Ⅳ型","criteria":"骨折线穿过干骺端、骺板与骨骺（Through，关节内）","level":"high"},{"label":"Ⅴ型","criteria":"骺板压缩性损伤（Crush/Rammed），早期 X 线常无异常，生长停滞风险最高","level":"crit"}],"note":"Ⅲ–Ⅴ型累及骨骺或骺板挤压，生长障碍风险高，需解剖复位（必要时切开）与定期随访（每 3–6 个月 1 年）。Ⅰ/Ⅱ型多为闭合复位 + 石膏。","refs":["Salter RB, Harris WR. J Bone Joint Surg Am 1963;45:587-622（原版）","中华医学会小儿外科学分会：儿童骨骺损伤诊治专家共识（2020）"],"rank":8},{"id":"salter_harris_thompson","name":"Salter-Harris 附加型（Rang 与 Peterson 扩展）","aka":["Rang 扩展","Peterson 分型"],"cat":"骨折分型","desc":"补充 SALTR 五型之外的少见骨骺损伤类型：骺板周围环损伤（Rang Ⅵ）与开放骨折伴骨骺缺损（Rang Ⅶ），以及 Peterson 分型（需按资料判读）。","inputs":[],"compute":"formula_only","levels":[{"label":"Rang Ⅵ 型","criteria":"骺板周围环（Ranvier 区/软骨膜环）损伤，可致局部骺板早闭与成角畸形","level":"high"},{"label":"Rang Ⅶ 型","criteria":"骺板完全或部分离断（开放骨折致骨骺缺血/分离），预后差","level":"crit"},{"label":"Rang Ⅷ/Ⅸ 型","criteria":"干骺端或骨膜环血供损伤，导致骨生长障碍（Ⅸ 为骨膜撕脱致延迟愈合）","level":"high"}],"note":"此扩展型较罕见，主要见于开放性损伤、烧伤或感染后；如影像学难以判断建议 MRI 评估骺板通畅性。Peterson 分型（Ⅰ–Ⅵ）另有一套分类，使用时需注明。","refs":["Rang M. Children's Fractures, 3rd ed. 1983（Rang 扩展型）","中华医学会小儿外科学分会：儿童骨骺损伤诊治专家共识（2020）"],"rank":9},{"id":"tile_pelvis","name":"Tile 骨盆骨折分型","aka":["Tile Classification"],"cat":"骨折分型","desc":"按骨盆稳定性与后环完整度分为 A（稳定）、B（旋转不稳、垂直稳定）、C（旋转与垂直均不稳）。","inputs":[],"compute":"formula_only","levels":[{"label":"A 型","criteria":"稳定型（后环完整）：A1 撕脱骨折、A2 髂骨翼骨折、A3 骶尾骨横形骨折","level":"ok"},{"label":"B 型","criteria":"旋转不稳、垂直稳定：B1 开书样（外旋）、B2 侧方压缩、B3 双侧 B 型","level":"high"},{"label":"C 型","criteria":"旋转与垂直均不稳定（后环完全断裂）：C1 单侧后方、C2 双侧、C3 伴髋臼骨折","level":"crit"}],"note":"B/C 型需评估血流动力学：后环出血可致休克，超过 4 个单位输血仍不稳者考虑血管造影栓塞或骨盆填塞。AO/OTA 分型对 C 型进一步细分。","refs":["Tile M. J Bone Joint Surg Br 1988;70:1-12（原版）","中华医学会骨科学分会创伤骨科学组：骨盆骨折诊疗指南（2019）"],"rank":10},{"id":"frax","name":"FRAX 骨折风险评估","aka":["Fracture Risk Assessment Tool","FRAX 10 年骨折概率"],"cat":"围术期风险","desc":"基于临床危险因素（可含股骨颈 BMD）计算 10 年髋部骨折与主要骨质疏松性骨折概率，指导抗骨质疏松治疗。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":40,"max":90,"step":1,"required":true},{"key":"sex","label":"性别","type":"select","options":[{"value":0,"label":"男性"},{"value":1,"label":"女性"}],"required":true},{"key":"bmi","label":"体重指数（输入值）","unit":"kg/m²","type":"number","min":15,"max":45,"step":0.1,"required":true},{"key":"prior_fx","label":"既往脆性骨折","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"hip_fx","label":"父母髋部骨折史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"smoke","label":"当前吸烟","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"glucocorticoid","label":"长期口服糖皮质激素（泼尼松 ≥5 mg/d 超过 3 个月）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"ra","label":"类风湿关节炎","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"secondary","label":"继发性骨质疏松（甲亢、甲状旁腺功能亢进、1 型糖尿病、早绝经等）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"alcohol","label":"每日饮酒 ≥3 个单位","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"femoral_neck_t","label":"股骨颈 BMD T 值","type":"number","min":-6,"max":2,"step":0.1,"required":false,"hint":"可选；不填则按不含 BMD 的模型"}],"formula":"FRAX 使用 WHO 开发的特定国家模型（中国人群模型），结合年龄、性别、BMI、危险因素与可选股骨颈 BMD 计算 10 年髋部骨折与主要骨质疏松性骨折概率；干预阈值：主要骨质疏松性骨折概率 ≥20% 或髋部骨折 ≥3%","compute":"formula_only","algorithm":"算法：按中国 FRAX 模型（官方在线计算或本地查表插值）计算\nhip10 = FRAX_hip(age, sex, bmi, prior_fx, hip_fx, smoke, gc, ra, secondary, alcohol, T)\nmajor10 = FRAX_major(同上)\n阈值判断见 interpret（本输入为简化版，不作为个体概率）","interpret":[{"when":"major10 >= 20 || hip10 >= 3","level":"high","text":"主要骨质疏松性骨折 10 年概率 ≥20% 或髋部骨折 ≥3%：建议启动抗骨质疏松药物（双膦酸盐/地舒单抗等）并补充钙与维生素 D"},{"when":"T != null && T <= -2.5","level":"warn","text":"T ≤ −2.5（骨质疏松）：即使 FRAX 未达阈值也应治疗"},{"when":"T != null && T <= -1.0 && T > -2.5","level":"warn","text":"T −1.0 ~ −2.5（骨量减少）：结合 FRAX 概率决定是否治疗"},{"when":"T == null","level":"warn","text":"未输入 BMD：按临床危险因素估算，建议行 DXA（腰椎 + 股骨颈）明确"}],"note":"中国人群 FRAX 干预阈值与部分西方国家不同，中国指南沿用 ≥20%（主要骨折）/≥3%（髋部）；本条目为输入清单，概率需用官方 FRAX 模型（无 BMD 与含 BMD 两种）。","refs":["Kanis JA, et al. Osteoporos Int 2008（FRAX 模型原始文献）","中华医学会骨质疏松和骨矿盐疾病分会：原发性骨质疏松症诊疗指南（2022）","中国骨质疏松性骨折诊疗指南（2017）"],"rank":1},{"id":"caprini","name":"Caprini 静脉血栓栓塞风险评分","aka":["Caprini Score","VTE 风险评分"],"cat":"围术期风险","desc":"手术（尤其是骨科大手术）患者 VTE 风险评估的经典工具，按分值决定机械与药物预防。","inputs":[{"key":"age","label":"年龄","type":"select","options":[{"value":0,"label":"≤40 岁"},{"value":1,"label":"41–60 岁"},{"value":2,"label":"61–74 岁"},{"value":3,"label":"≥75 岁"}],"required":true},{"key":"surgery","label":"手术类型与时长","type":"select","options":[{"value":1,"label":"小手术（<45 分钟）"},{"value":2,"label":"大手术 >45 分钟或脊柱/腹腔大手术 >2 小时"},{"value":5,"label":"髋/膝关节置换、髋部骨折或骨盆骨折手术"}],"required":true},{"key":"malignancy","label":"恶性肿瘤","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"bmi","label":"BMI","type":"select","options":[{"value":0,"label":"<30 kg/m²"},{"value":1,"label":"≥30 kg/m²"}],"required":true},{"key":"varicose","label":"下肢静脉曲张","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"swelling","label":"下肢肿胀（当前）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"immob","label":"卧床 >72 小时或石膏/支具固定","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"central_line","label":"中心静脉置管","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"copd","label":"COPD/肺部疾病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"chf","label":"充血性心力衰竭","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"mi","label":"近期心肌梗死/缺血性卒中","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"ibd","label":"炎症性肠病","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"prior_vte","label":"既往 VTE 史","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true},{"key":"family_vte","label":"VTE 家族史","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true},{"key":"thrombophilia","label":"已知血栓形成倾向（因子 V Leiden、狼疮抗凝物等）","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true},{"key":"stroke","label":"卒中（<1 个月）","type":"select","options":[{"value":0,"label":"无"},{"value":5,"label":"有"}],"required":true},{"key":"arthroplasty","label":"计划行大关节置换","type":"select","options":[{"value":0,"label":"无"},{"value":5,"label":"有"}],"required":true},{"key":"hip_pelvis_spine","label":"髋、骨盆或下肢骨折/多发性创伤/脊髓损伤（<1 个月）","type":"select","options":[{"value":0,"label":"无"},{"value":5,"label":"有"}],"required":true},{"key":"pregnancy","label":"妊娠或产后","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Caprini 各危险因素按 1、2、3、5 分计分并求和；总分 0–1 低危、2 中危、3–4 高危、≥5 极高危","compute":"sum","interpret":[{"when":"v <= 1","level":"ok","text":"0–1 分：低危，鼓励早期下床活动，可考虑机械预防"},{"when":"v <= 2","level":"warn","text":"2 分：中危，建议机械预防（间歇充气加压）± 药物预防"},{"when":"v <= 4","level":"high","text":"3–4 分：高危，建议药物预防（低分子肝素）+ 机械预防"},{"when":"v >= 5","level":"crit","text":"≥5 分：极高危，药物 + 机械预防 7–14 天（关节置换/髋部骨折），并复查 D-二聚体与 DVT 超声"}],"note":"骨科大手术（THA/TKA/髋部骨折）均属极高危，需按中国骨科大手术 VTE 预防指南（2016）执行；有高出血风险者先机械预防。","refs":["Caprini JA. Dis Mon 2005;51:70-78（Caprini 评分原版）","中华医学会骨科学分会：中国骨科大手术静脉血栓栓塞症预防指南（2016）","中国静脉血栓栓塞症预防指南（2017）"],"rank":2},{"id":"wells_dvt","name":"Wells 深静脉血栓评分","aka":["Wells Score for DVT"],"cat":"围术期风险","desc":"依据临床特征评估下肢深静脉血栓（DVT）验前概率，决定 D-二聚体与超声检查路径。","inputs":[{"key":"cancer","label":"活动性癌症（治疗中或 6 个月内）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"paralysis","label":"瘫痪、轻瘫或近期下肢石膏固定","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"bedrest","label":"卧床 >3 天或 4 周内大手术","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"calf_pain","label":"沿深静脉走行压痛","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"leg_swelling","label":"整个下肢肿胀","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"calf_swelling","label":"小腿肿胀超过对侧 3 cm","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pitting","label":"患肢凹陷性水肿","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"collateral","label":"浅静脉侧支循环（非静脉曲张）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"prior_dvt","label":"既往 DVT 史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"alt_dx","label":"其他诊断可能性 ≥ DVT","type":"select","options":[{"value":0,"label":"是（−2）"},{"value":-2,"label":"否"}],"required":true}],"formula":"Wells DVT = 9 项临床特征各 1 分，若「其他诊断可能性更大」则 −2 分；总分 −2 至 9","compute":"sum","interpret":[{"when":"v <= 0","level":"ok","text":"≤0 分：低度可能（约 5%），查 D-二聚体，阴性可排除 DVT"},{"when":"v <= 2","level":"warn","text":"1–2 分：中度可能（约 17%），查 D-二聚体 + 下肢静脉超声"},{"when":"v >= 3","level":"high","text":"≥3 分：高度可能（约 17%–53%），直接行下肢静脉超声，阳性开始抗凝；阴性时复查超声"}],"note":"「其他诊断可能性 ≥ DVT」选「是」即 −2 分，是 Wells 评分的关键减分项。妊娠期首选超声，D-二聚体特异性下降。","refs":["Wells PS, et al. Lancet 1997;350:1795-1798（Wells DVT 原版）","中华医学会呼吸病学分会：肺血栓栓塞症诊治与预防指南（2018）","深静脉血栓形成的诊断和治疗指南（第 3 版，2017）"],"rank":3},{"id":"asi_vte_ortho","name":"骨科手术 VTE 预防决策要点","aka":["骨科 VTE 预防检查清单","THA/TKA 抗凝要点"],"cat":"围术期风险","desc":"汇总骨科大手术（THA、TKA、髋部骨折）VTE 药物与机械预防的关键要点与时限，供围术期快速核对。","inputs":[{"key":"proc","label":"手术类型","type":"select","options":[{"value":1,"label":"TKA（全膝置换）"},{"value":2,"label":"THA（全髋置换）"},{"value":3,"label":"髋部骨折内固定/置换"},{"value":4,"label":"膝关节周围骨折/下肢多发骨折"},{"value":5,"label":"脊柱大手术"}],"required":true},{"key":"bleeding","label":"高出血风险（活动性出血、血小板 <50×10⁹/L、严重肝病等）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"renal","label":"肾功能不全（CrCl <30 mL/min）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"按中国骨科大手术 VTE 预防指南：THA/TKA/髋部骨折建议 LMWH 或 Xa 因子抑制剂预防 10–14 天（髋部骨折/THA 可延长至 35 天）；机械预防（IPC）联合使用","compute":"formula_only","algorithm":"if bleeding == 1: 先机械预防（IPC），出血控制后评估延迟药物预防\nelif renal == 1: LMWH 减量或改用普通肝素/磺达肝癸钠（遵说明书），并监测\nelse: 按术式给予 LMWH/口服 Xa 抑制剂 10–14 天（髋部骨折延长 28–35 天）","interpret":[{"when":"bleeding == 1","level":"crit","text":"高出血风险：先用间歇充气加压（IPC），暂缓药物抗凝；出血控制后 24–48 小时复评"},{"when":"renal == 1","level":"warn","text":"CrCl <30：LMWH 需减量或间隔延长，必要时改用普通肝素；磺达肝癸钠按说明书减量"},{"when":"proc == 3","level":"high","text":"髋部骨折：入院即开始预防（术前可用 LMWH），术后继续 28–35 天"},{"when":"proc >= 1","level":"warn","text":"关节置换/下肢骨折：药物预防 10–14 天 + 机械预防，出院前超声筛查高危者"}],"note":"具体剂量与给药时机遵药品说明书与院内方案；椎管内麻醉前需停用抗凝药（LMWH 术前 12–24 小时停药）。","refs":["中华医学会骨科学分会：中国骨科大手术静脉血栓栓塞症预防指南（2016）","中国创伤骨科患者围手术期静脉血栓栓塞症预防指南（2021）","ACCP 抗栓治疗指南第 9 版（2012，骨科部分补充）"],"rank":4}]},"peds":{"items":[{"id":"peds_apgar","name":"Apgar 新生儿评分","aka":["Apgar Score"],"cat":"新生儿评估","rank":1,"desc":"出生后 1、5（10）分钟五项体征评分，评估新生儿复苏效果与过渡状况。","inputs":[{"key":"hr","label":"心率","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"<100 次/分"},{"value":2,"label":"≥100 次/分"}],"required":true},{"key":"resp","label":"呼吸","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"弱、不规则"},{"value":2,"label":"啼哭有力"}],"required":true},{"key":"tone","label":"肌张力","type":"select","options":[{"value":0,"label":"瘫软"},{"value":1,"label":"四肢略屈曲"},{"value":2,"label":"主动活动"}],"required":true},{"key":"reflex","label":"反射刺激（对刺激的反应）","type":"select","options":[{"value":0,"label":"无反应"},{"value":1,"label":"皱眉/面部扭曲"},{"value":2,"label":"哭、咳嗽、喷嚏"}],"required":true},{"key":"color","label":"肤色","type":"select","options":[{"value":0,"label":"全身青紫或苍白"},{"value":1,"label":"躯干粉红、肢端青紫"},{"value":2,"label":"全身粉红"}],"required":true}],"formula":"Apgar = 心率 + 呼吸 + 肌张力 + 反射 + 肤色（每项 0–2，总分 0–10）","compute":"sum","interpret":[{"when":"v >= 8","level":"ok","text":"8–10 分：状态良好，常规新生儿护理与母婴同室"},{"when":"v >= 7","level":"ok","text":"7 分：轻度抑制，加强观察；5 min 复评"},{"when":"v >= 4","level":"warn","text":"4–6 分：中度抑制，按 NRP 继续复苏（正压通气/氧浓度滴定），5、10 min 复评"},{"when":"v < 4","level":"crit","text":"<4 分：重度抑制，立即气管插管、胸外按压（HR <60），启动 NICU 转运预案"}],"note":"Apgar 只反映即时状态，不能单独诊断窒息；需结合脐血 pH（<7.0）与 BE（≤−12 mmol/L）。5 min <7 分需每 5 min 复评至 20 min。","refs":["AAP/ACOG Committee Opinion No.644 The Apgar Score（2015）","中国新生儿复苏指南（2021）"]},{"id":"peds_gcs","name":"儿童格拉斯哥昏迷评分（GCS）","aka":["Pediatric GCS","pGCS"],"cat":"神经评估","rank":2,"desc":"按年龄分档（<1 岁、≥1 岁）评估儿童意识水平。","inputs":[{"key":"eye","label":"睁眼反应","type":"select","options":[{"value":4,"label":"自发睁眼"},{"value":3,"label":"呼唤/大声叫醒时睁眼"},{"value":2,"label":"疼痛刺激时睁眼"},{"value":1,"label":"不睁眼"}],"required":true},{"key":"verbal","label":"语言反应（≥1 岁）","type":"select","options":[{"value":5,"label":"回答切题"},{"value":4,"label":"回答混乱"},{"value":3,"label":"词不达意/不恰当"},{"value":2,"label":"难以理解的声音"},{"value":1,"label":"无反应"}],"required":true},{"key":"verbal_infant","label":"语言反应（<1 岁，替代项）","type":"select","options":[{"value":5,"label":"咕咕声/牙牙学语、社交微笑"},{"value":4,"label":"哭闹但可安抚"},{"value":3,"label":"哭闹或不恰当哭/反应差"},{"value":2,"label":"对疼痛仅呻吟/烦躁"},{"value":1,"label":"无反应"}],"required":false,"hint":"<1 岁者请选本项，并覆盖上面的语言反应项"},{"key":"motor","label":"运动反应","type":"select","options":[{"value":6,"label":"遵嘱运动"},{"value":5,"label":"疼痛定位"},{"value":4,"label":"疼痛逃避（屈曲回缩）"},{"value":3,"label":"异常屈曲（去皮质）"},{"value":2,"label":"异常伸直（去大脑）"},{"value":1,"label":"无反应"}],"required":true}],"formula":"GCS = 睁眼(E) + 语言(V) + 运动(M)，E 1–4、V 1–5、M 1–6，总分 3–15","compute":"sum","algorithm":"v = eye + (verbal_infant != null ? verbal_infant : verbal) + motor\n","interpret":[{"when":"v >= 14","level":"ok","text":"13–15 分：轻度/无意识障碍，结合病史与瞳孔评估"},{"when":"v >= 9","level":"warn","text":"9–12 分：中度意识障碍，收住院观察，头颅 CT 指征评估，每 1–2 h 复评"},{"when":"v < 9","level":"crit","text":"3–8 分：重度意识障碍（昏迷），需气道保护、甘露醇/高渗盐水、神经外科会诊"}],"note":"GCS 有年龄版本差异，<1 岁者使用婴幼儿版语言项。需记录瞳孔、生命体征与分值变化趋势，单次分值不足以判断预后。","refs":["AHA/AAP PALS 儿童高级生命支持指南（2020）","中国儿童颅脑创伤诊疗指南（2019）"]},{"id":"peds_weight_est","name":"儿童体重估算（按年龄公式）","aka":["Pediatric Weight Estimation","APLS weight formula"],"cat":"生长发育","rank":3,"desc":"无实际体重时按年龄估算体重，供院前与急诊用药参考。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":0,"max":12,"step":0.1,"required":true}],"formula":"APLS：1–5 岁 = 2 × 年龄(岁) + 8 kg；6–12 岁 = 3 × 年龄(岁) + 7 kg；<1 岁 =（月龄+9）/2 kg（出生体重约 3.3 kg，4 月龄约 2 倍，1 岁约 3 倍）","compute":"formula_only","algorithm":"if age < 1: v = (age * 12 + 9) / 2\nelse if age <= 5: v = 2 * age + 8\nelse: v = 3 * age + 7\nv = Math.round(v * 10) / 10\n","interpret":[{"when":"v <= 10","level":"ok","text":"估算体重 ≤10 kg：按 0–2 岁体重带参考，用药用 mg/kg 并核对可及的最小规格"},{"when":"v <= 20","level":"ok","text":"10–20 kg：按 4-2-1 盐水试液补给，注意容量限制（20 mL/kg 冲击）"},{"when":"v <= 40","level":"warn","text":"20–40 kg：接近学龄期，药物剂量需测算上限（部分药物有成人最大量）"},{"when":"v > 40","level":"high","text":">40 kg：按成人剂量上限计算，检查体重是否超出设备量程"}],"note":"公式估算误差可达 ±20%，仅用于急救情景；有实际体重（含家长描述）时以实际体重为准。肥胖儿童易低估，需按实际称重。","refs":["APLS The Practical Approach to Emergencies（2016）","AHA/AAP PALS 儿童高级生命支持指南（2020）"]},{"id":"peds_fluid_maintenance","name":"儿童液体维持量（Holliday-Segar 4-2-1）","aka":["4-2-1 Rule","Holliday-Segar Method","维持液体"],"cat":"液体与电解质","rank":4,"desc":"按体重分段计算每小时维持液量，用于脱水/禁食补液。","inputs":[{"key":"weight","label":"体重","unit":"kg","type":"number","min":0.5,"max":120,"step":0.1,"required":true}],"formula":"每小时：前 10 kg × 4 mL/kg/h，11–20 kg × 2 mL/kg/h，>20 kg × 1 mL/kg/h；每日（m² 法）：<10 kg 100 mL/kg，10–20 kg 1000 + 50×(kg−10)，>20 kg 1500 + 20×(kg−20)","compute":"formula_only","algorithm":"h = Math.min(weight, 10) * 4\nif weight > 10: h += Math.min(weight - 10, 10) * 2\nif weight > 20: h += (weight - 20) * 1\nv = Math.round(h)  # mL/h\n","interpret":[{"when":"v < 20","level":"ok","text":"<20 mL/h：新生儿/小婴儿，注意避免过量；若尿量 >2 mL/kg/h 需评估多尿"},{"when":"v < 60","level":"ok","text":"维持量：通常用等渗液（含葡萄糖的生理盐水）输注，定期查电解质"},{"when":"v < 100","level":"ok","text":"维持量：输液泵精确控制；禁食或发热时按每 1℃ 增加 10–12%"},{"when":"v >= 100","level":"warn","text":"≥100 mL/h：大儿童，注意颅脑损伤/肾功能不全时需限液（2/3 维持量）"}],"note":"近年推荐等渗液（0.9% NaCl + 5% GS）替代低渗液以防低钠血症；颅脑外伤、肾衰、心衰者按 2/3–1/2 维持量。持续输注（而非冲击）以免造成抗利尿激素不适当分泌。","refs":["AAP Clinical Practice Guideline Maintenance Intravenous Fluids in Children（2018）","中国儿童健康管理：儿科液体治疗专家共识（2019）"]},{"id":"peds_dehydration","name":"儿童脱水程度判断（WHO / 临床分级）","aka":["Dehydration Severity"],"cat":"液体与电解质","rank":5,"desc":"按精神状态、眼泪、口渴、皮肤弹性等临床体征分级脱水程度。","inputs":[{"key":"mental","label":"精神状态","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"烦躁/易激惹"},{"value":2,"label":"嗜睡/反应差"}],"required":true},{"key":"eyes","label":"眼窝","type":"select","options":[{"value":0,"label":"正常"},{"value":1,"label":"轻度凹陷"},{"value":2,"label":"明显凹陷"}],"required":true},{"key":"thirst","label":"口渴/饮水表现","type":"select","options":[{"value":0,"label":"正常饮水"},{"value":1,"label":"口渴、急欲饮水"},{"value":2,"label":"不能饮水/喝不进去"}],"required":true},{"key":"skin","label":"皮肤弹性（腹壁捏起试验）","type":"select","options":[{"value":0,"label":"立即复原"},{"value":1,"label":"缓慢（1–2 s）"},{"value":2,"label":"非常缓慢（>2 s）"}],"required":true},{"key":"capillary","label":"毛细血管再充盈时间","type":"select","options":[{"value":0,"label":"< 2 s"},{"value":1,"label":"2–3 s"},{"value":2,"label":"> 3 s"}],"required":false}],"formula":"总分 0–10：0 项 = 无脱水（<3%）；1–3 项/得分 1–3 = 轻度（3–5%）；4–6 = 中度（6–9%）；≥7 = 重度（≥10%）","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"无脱水：口服补液（ORS）维持，继续母乳/常规饮食"},{"when":"v <= 3","level":"warn","text":"轻度脱水（约 3–5%）：ORS 50 mL/kg 分 3–4 h 补足，每 1–2 h 复评"},{"when":"v <= 6","level":"high","text":"中度脱水（约 6–9%）：ORS 75–100 mL/kg 分 4 h；呕吐不能口服者静脉补液（生理盐水 10–20 mL/kg）"},{"when":"v >= 7","level":"crit","text":"重度脱水（≥10%）：立即静脉 20 mL/kg 生理盐水快速扩容（可重复），纠正休克后再补累积损失；监测电解质与尿量"}],"note":"WHO 四体征（精神状态、眼窝、口渴、皮肤弹性）中 ≥2 项为重度；本工具加入毛细血管再充盈以区分休克。低钠/高钠脱水补液方案须结合血钠，纠钠速度 ≤10 mmol/L/日。","refs":["WHO Pocket Book of Hospital Care for Children（2013，第 2 版）","中国儿童急性腹泻病诊治专家共识（2016）"]},{"id":"peds_egfr_schwartz","name":"儿童 eGFR（Schwartz 公式，2009 床旁版）","aka":["Schwartz Equation","Bedside Schwartz"],"cat":"肾脏功能","rank":6,"desc":"由身高与血清肌酐估算儿童肾小球滤过率，用于 CKD 分期与用药调整。","inputs":[{"key":"height","label":"身高","unit":"cm","type":"number","min":30,"max":200,"step":0.1,"required":true},{"key":"scr_umol","label":"血清肌酐 Scr","unit":"μmol/L","type":"number","min":10,"max":1500,"step":1,"required":true},{"key":"scr_mg","label":"或 Scr（可空）","unit":"mg/dL","type":"number","min":0.1,"max":17,"step":0.01,"required":false,"hint":"有 mg/dL 值时优先使用"}],"formula":"eGFR = 0.413 × 身高(cm) / Scr(mg/dL)；μmol/L ÷ 88.4 = mg/dL","compute":"formula_only","algorithm":"mg = scr_mg > 0 ? scr_mg : scr_umol / 88.4\nv = Math.round(0.413 * height / mg * 10) / 10  # mL/min/1.73 m²\n","interpret":[{"when":"v >= 90","level":"ok","text":"≥90：正常或 G1；若持续蛋白尿/血尿需查病因（CKD 可 eGFR 正常）"},{"when":"v >= 60","level":"warn","text":"60–89：G2，轻度下降；每 3–6 月复查，控制血压与蛋白尿"},{"when":"v >= 45","level":"warn","text":"45–59：G3a，需肾内科随访，避免肾毒性药物，评估贫血与骨代谢"},{"when":"v >= 30","level":"high","text":"30–44：G3b，药物按肾功能调整，限制蛋白摄入（0.8 g/kg/d）"},{"when":"v >= 15","level":"crit","text":"15–29：G4，准备透析/移植评估，严格限钾、限磷"},{"when":"v < 15","level":"crit","text":"<15：G5 肾衰竭，需肾替代治疗，转肾脏科急诊评估"}],"note":"Schwartz 床旁公式适用于 1–16 岁；<1 岁（尤其早产）用 Schwartz-Lyon（k=0.33/0.45 月龄相关）。肌肉量大的患儿（如 Duchenne 肌营养不良）肌酐低会高估 GFR；胱抑素 C 版（CKiD）更准。","refs":["KDIGO 2012 Clinical Practice Guideline for Evaluation and Management of CKD","KDIGO 2024 CKD Guideline","中华医学会儿科学分会：儿童慢性肾脏病诊治指南（2018）"]},{"id":"peds_pew","name":"儿童营养风险筛查（STAMP / Pew 儿科营养风险）","aka":["Pediatric Nutritional Risk","STAMP","营养风险筛查"],"cat":"营养与生长","rank":7,"desc":"综合病情、进食状态与体重变化三项，筛查住院儿童营养风险。","inputs":[{"key":"diagnosis","label":"疾病分类","type":"select","options":[{"value":0,"label":"常规疾病（无额外风险）"},{"value":1,"label":"轻中度风险（如急性感染、择期小手术）"},{"value":2,"label":"重度风险（如 IBD、心衰、烧伤、恶性肿瘤）"}],"required":true},{"key":"intake","label":"摄入情况","type":"select","options":[{"value":0,"label":"进食正常"},{"value":1,"label":"摄入减少（49–75%）"},{"value":2,"label":"摄入明显减少（<50%，或超过 3 天未进食）"}],"required":true},{"key":"weight_change","label":"近期体重变化","type":"select","options":[{"value":0,"label":"无下降"},{"value":1,"label":"下降 0–1% 或体重增长不足"},{"value":2,"label":"下降 ≥2%（或长期停滞）"}],"required":true}],"formula":"STAMP 总分 = 疾病风险 + 摄入情况 + 体重变化（0–6）；≥4 为高风险，2–3 为中风险，0–1 为低风险","compute":"sum","interpret":[{"when":"v <= 1","level":"ok","text":"低风险：常规营养评估，入院 7 天复评"},{"when":"v <= 3","level":"warn","text":"中风险：入院 3 天内行营养师会诊，记录 3 天摄食量并考虑营养补充"},{"when":"v >= 4","level":"high","text":"高风险：24 h 内营养干预（口头/肠内营养），每周 1–2 次复评并监测生长曲线"}],"note":"STAMP 适用于 1 月龄–18 岁住院儿童；早产儿及使用利尿剂、中心静脉营养者另需人体成分评估。「Pew 营养风险」在国内指 Pew 报告（1998）儿科营养不良标准的筛查工具，本条目采用 STAMP 的临床可操作版本，判读以 STAMP 官方阈值为准。","refs":["Pew Nutrition Risk Report（1998，Pew Charity Trusts）","ESPGHAN Screening Tool for Assessment of Malnutrition in Paediatrics（STAMP，2010）","中国儿童营养筛查与评估专家共识（2018）"]},{"id":"peds_flacc","name":"FLACC 疼痛评分（儿童）","aka":["FLACC Pain Scale"],"cat":"疼痛评估","rank":8,"desc":"适用于 2 月龄–7 岁或表达能力受限儿童的 5 项观察性疼痛评分（0–10）。","inputs":[{"key":"face","label":"面部表情 Face","type":"select","options":[{"value":0,"label":"表情自然/微笑"},{"value":1,"label":"偶尔皱眉、淡漠、不关心"},{"value":2,"label":"频繁皱眉、下颌颤抖、牙关紧闭"}],"required":true},{"key":"legs","label":"腿部 Legs","type":"select","options":[{"value":0,"label":"正常姿势/放松"},{"value":1,"label":"不安、紧张、来回动"},{"value":2,"label":"踢打、屈曲或僵硬不动"}],"required":true},{"key":"activity","label":"活动 Activity","type":"select","options":[{"value":0,"label":"安静平卧、体位正常、活动自如"},{"value":1,"label":"扭动、前后摇摆、紧张"},{"value":2,"label":"身体弓起、僵硬、剧烈抖动"}],"required":true},{"key":"cry","label":"哭闹 Cry","type":"select","options":[{"value":0,"label":"不哭"},{"value":1,"label":"呻吟、呜咽、偶有哭诉"},{"value":2,"label":"持续大哭、尖叫、抽泣"}],"required":true},{"key":"consolability","label":"可安慰性 Consolability","type":"select","options":[{"value":0,"label":"安静、放松"},{"value":1,"label":"拥抱/安抚后缓解"},{"value":2,"label":"难以安慰"}],"required":true}],"formula":"FLACC = 面部 + 腿部 + 活动 + 哭闹 + 可安慰性（每项 0–2，总分 0–10）","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：无痛，常规观察"},{"when":"v <= 3","level":"ok","text":"1–3 分：轻度疼痛，非药物干预（安抚、体位、冷敷）"},{"when":"v <= 6","level":"warn","text":"4–6 分：中度疼痛，口服对乙酰氨基酚/布洛芬（按体重），安抚并 1 h 复评"},{"when":"v >= 7","level":"high","text":"7–10 分：重度疼痛，考虑阿片类（吗啡 0.05–0.1 mg/kg IV），15–30 min 复评，警惕呼吸抑制"}],"note":"FLACC 在睡眠时评分可能偏低；意识障碍、插管或术后肌张力异常的患儿判读受限。评分应结合行为、生理（心率、呼吸）与家长描述，<2 月龄的疼痛评估用 NIPS/PIPP。","refs":["Merkel SI et al. The FLACC: A Behavioral Scale for Scoring Postoperative Pain in Young Children. Pediatr Nurs（1997）","AAP Policy Statement Pain and Distress in Children（2016）"]},{"id":"peds_wong_baker","name":"Wong-Baker 面部表情疼痛量表","aka":["Wong-Baker FACES Pain Rating Scale","面部疼痛评分"],"cat":"疼痛评估","rank":9,"desc":"6 张面孔对应 0–10 分，适用于 ≥3 岁能自我报告的儿童。","inputs":[{"key":"face_score","label":"患儿自我选择的面孔","type":"select","options":[{"value":0,"label":"0：无痛"},{"value":1,"label":"2：痛一点点"},{"value":2,"label":"4：痛得稍多"},{"value":3,"label":"6：更痛"},{"value":4,"label":"8：痛得厉害"},{"value":5,"label":"10：痛得最厉害"}],"required":true},{"key":"numeric","label":"或 0–10 数字疼痛评分（可空）","type":"number","min":0,"max":10,"step":1,"required":false}],"formula":"以所选面孔对应的分值判读（0/2/4/6/8/10）；0 无痛，1–3 轻度，4–6 中度，7–10 重度","compute":"formula_only","algorithm":"v = numeric 有值 ? numeric : (face_score * 2)\n","interpret":[{"when":"v == 0","level":"ok","text":"0 分：无痛，常规观察"},{"when":"v <= 3","level":"ok","text":"1–3 分：轻度疼痛，非药物干预为主（分散注意力、冰敷），必要时对乙酰氨基酚"},{"when":"v <= 6","level":"warn","text":"4–6 分：中度疼痛，按体重给镇痛药，记录评分趋势"},{"when":"v >= 7","level":"high","text":"7–10 分：重度疼痛，立即镇痛（阿片类视情况），复评并查找病因"}],"note":"需使用标准彩色面孔图，向患儿解释「脸表示无痛到最痛」。自评优于家长代理；对无法理解量表的幼儿改用 FLACC。","refs":["Wong DL, Baker CM. Pain in Children: Comparison of Assessment Scales. Pediatr Nurs（1988）","中国儿童疼痛评估与治疗专家共识（2019）"]},{"id":"peds_neonatal_jaundice","name":"新生儿黄疸小时胆红素判读（Bhutani 曲线）","aka":["Hour-specific Bilirubin Nomogram","TSB 风险分级"],"cat":"新生儿评估","rank":10,"desc":"按生后小时数（或日龄）结合经皮/血清胆红素判断高风险区间与是否需光疗。","inputs":[{"key":"hours","label":"生后小时数","unit":"h","type":"number","min":6,"max":336,"step":1,"required":true},{"key":"tsb","label":"总胆红素 TSB（经皮或血清）","unit":"mg/dL","type":"number","min":0,"max":40,"step":0.1,"required":true},{"key":"ga","label":"出生胎龄","type":"select","options":[{"value":1,"label":"≥38 周（足月）"},{"value":2,"label":"35–37+6 周（近足月）"},{"value":3,"label":"32–34+6 周（早产）"},{"value":4,"label":"<32 周（早产）"}],"required":true},{"key":"risk","label":"高危因素（溶血、同胞黄疸病史、头颅血肿、严重瘀斑、G6PD 缺乏）","type":"number","min":0,"max":5,"step":1,"required":false}],"formula":"Bhutani 第 95 百分位（≥38 周）：12 h ≈7、24 h ≈11.5、48 h ≈15.5、72 h ≈17.5 mg/dL；第 75 百分位约为其 82%；≥第 95 百分位或 48 h 内快速上升 >0.2 mg/dL/h 为高风险","compute":"formula_only","algorithm":"p95 = interpolate(hours, [6,12,24,36,48,72,96,120,144,168], [5,7,11.5,13.5,15.5,17.5,18.5,18.8,18.5,18])\nif ga == 2: p95 *= 0.90\nif ga >= 3: p95 *= 0.80\nif risk >= 1: p95 *= 0.90  # 高危因素提前达阈值\nv = tsb - p95  # >0 为高于第95百分位\n","interpret":[{"when":"v <= -3","level":"ok","text":"低于第 75 百分位：低风险，继续按小时纵向监测，出院前 24–48 h 内复测"},{"when":"v < 0","level":"warn","text":"第 75–95 百分位：中高风险，每 12–24 h 复测 TSB，评估喂养与排泄"},{"when":"v < 2","level":"high","text":"高于第 95 百分位：接近光疗阈值的 1/3，检查血型/直接抗人球蛋白、G6PD、CBC，准备光疗"},{"when":"v >= 2","level":"crit","text":"显著高于第 95 百分位：立即测血清 TSB、血型交叉、直抗与网织红细胞，开始光疗；接近换血阈值（≥20–25 mg/dL 或 ≥5 mg/dL/h 上升）转 NICU"}],"note":"界值为近似值，实际须对照 AAP 2004/2022 小时曲线与光疗阈值表（依胎龄、小时数、危险因素）。经皮胆红素在 15 mg/dL 以上不精确，需查血清 TSB。超过 24 h 出现黄疸须鉴别病理性（溶血、感染、胆道闭锁：直接胆红素升高）。","refs":["AAP Clinical Practice Guideline Hyperbilirubinemia in the Newborn ≥35 Weeks（2004，2022 修订）","中国新生儿高胆红素血症诊治专家共识（2022）"]},{"id":"peds_wells_dvt","name":"儿童静脉血栓风险（简化 Wells + 危险因素）","aka":["Pediatric DVT Risk","Caprini Pediatric"],"cat":"血栓与止血","rank":11,"desc":"结合临床特征与危险因素快速筛查儿童深静脉血栓可能的院前/门诊工具。","inputs":[{"key":"central_line","label":"中心静脉置管","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"mobility","label":"活动受限（卧床 ≥3 天/制动）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"limb_signs","label":"单侧肢体肿胀/疼痛（周径差 ≥3 cm）","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"thrombophilia","label":"遗传性易栓症/抗磷脂抗体阳性","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"sepsis","label":"脓毒症/严重感染","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"加权总分 = 中心静脉置管(2) + 活动受限(1) + 肢体体征(2) + 易栓症(1) + 脓毒症(1)，范围 0–7","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：低风险，鼓励活动与充分水化，无需影像筛查"},{"when":"v <= 2","level":"warn","text":"1–2 分：中风险，D-二聚体＋下肢静脉超声，监测肢体症状变化"},{"when":"v <= 4","level":"high","text":"3–4 分：中高风险，行加压超声（CUS）确诊，评估抗凝（依肝素按体重）"},{"when":"v >= 5","level":"crit","text":"≥5 分：高风险，立即影像确诊并启动抗凝；查抗磷脂抗体/易栓症，警惕肺栓塞（胸痛、气促、低氧）"}],"note":"儿科 VTE 多为 CVC 相关，Wells 评分未经儿童前瞻验证，本条目取 CVC 权重等临床常用要素的组合，仅作筛查而非诊断。确诊依赖影像。抗凝剂量须按体重和年龄（如依诺肝素 1 mg/kg q12h）计算，不在本工具估值。","refs":["CHEST Guideline Antithrombotic Therapy in Neonates and Children（2012，第 9 版）","ASH 2018 Guidelines Venous Thromboembolism in Pediatric Patients","中国儿童静脉血栓栓塞症诊治专家共识（2021）"]},{"id":"peds_growth_height_prediction","name":"儿童身高预测（骨龄/父母身高）","aka":["Mid-parental Height","Target Height"],"cat":"生长发育","rank":12,"desc":"由父母身高推算遗传靶身高范围，判断儿童身高是否达到遗传潜能。","inputs":[{"key":"father","label":"父亲身高","unit":"cm","type":"number","min":100,"max":230,"step":0.1,"required":true},{"key":"mother","label":"母亲身高","unit":"cm","type":"number","min":100,"max":230,"step":0.1,"required":true},{"key":"sex","label":"患儿性别","type":"select","options":[{"value":1,"label":"男"},{"value":2,"label":"女"}],"required":true},{"key":"child_height","label":"患儿目前身高（可空）","unit":"cm","type":"number","min":50,"max":200,"step":0.1,"required":false}],"formula":"男：TH = (父 + 母 + 13) / 2；女：TH = (父 + 母 − 13) / 2；靶身高范围 TH ± 8.5 cm","compute":"formula_only","algorithm":"v = sex == 1 ? (father + mother + 13) / 2 : (father + mother - 13) / 2\nlow = v - 8.5; high = v + 8.5\n","interpret":[{"when":"v < 150","level":"warn","text":"靶身高 <150 cm：遗传倾向矮小，需评估生长曲线百分位、骨龄与甲状腺功能"},{"when":"v < 178","level":"ok","text":"靶身高 150–178 cm：范围 ±8.5 cm，定期绘制生长曲线"},{"when":"v >= 178","level":"ok","text":"靶身高 ≥178 cm：遗传高个，评估骨龄与性早熟"}],"note":"靶身高仅反映遗传潜能，不替代实际生长曲线追踪（>97 或 <3 百分位或跨 2 条主百分位需评估）。生长激素缺乏/特纳综合征需骨龄＋IGF-1＋激发试验。","refs":["中华医学会儿科学分会内分泌遗传代谢学组：矮身材儿童诊治指南（2008）","WHO Child Growth Standards（2006）"]}]},"psych":{"items":[{"id":"psych_phq9","name":"患者健康问卷抑郁量表 PHQ-9","aka":["Patient Health Questionnaire-9","PHQ-9"],"cat":"情绪与焦虑","desc":"9 项自评（依据 DSM-5 抑郁症状，近 2 周，每项 0–3 分），总分 0–27，用于抑郁筛查与严重度分级。","inputs":[{"key":"q1","label":"做事时提不起劲或没有兴趣","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q2","label":"感到心情低落、沮丧或绝望","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q3","label":"入睡困难、睡不安稳或睡眠过多","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q4","label":"感觉疲倦或没有活力","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q5","label":"食欲不振或吃得太多","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q6","label":"觉得自己很糟、很失败，或让自己/家人失望","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q7","label":"注意力不集中（如看报、看电视时）","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q8","label":"行动或说话迟缓，或烦躁、坐立不安（他人可察觉）","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q9","label":"有不如死掉或伤害自己的念头","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true}],"formula":"PHQ-9 = 9 项之和（每项 0–3），总分 0–27","compute":"sum","interpret":[{"when":"q9 >= 1","level":"crit","text":"第 9 题（自杀念头）≥ 1：立即行 C-SSRS 风险评估，评估计划、手段、既往尝试与保护因素，必要时精神科急会诊"},{"when":"v <= 4","level":"ok","text":"0–4 分：无或极轻微抑郁；心理教育、规律作息与随访"},{"when":"v <= 9","level":"warn","text":"5–9 分：轻度抑郁；心理治疗（CBT/IPT）为主，2–4 周复评"},{"when":"v <= 14","level":"warn","text":"10–14 分：中度；CBT + 抗抑郁药（SSRI）可考虑，评估睡眠与躯体症状"},{"when":"v <= 19","level":"high","text":"15–19 分：中重度；首选药物 + 心理治疗，注意评估（筛查）双相病史（MDQ）"},{"when":"v >= 20","level":"crit","text":"20–27 分：重度；需专科诊治、排除器质性病因与双相，评估自杀风险与是否需要住院"}],"note":"PHQ-9 是筛查工具，不可替代诊断（诊断需 DSM-5/ICD-11 访谈）。评分 ≥ 10 有较好敏感度与特异度；有明显躯体症状者需排除甲减、贫血等。","refs":["Kroenke K, Spitzer RL, Williams JB. J Gen Intern Med 2001（PHQ-9 原版）","中国精神障碍诊疗规范（2020 年版，国家卫生健康委员会）","DSM-5 重性抑郁障碍诊断标准（APA 2013）","中华医学会：中国抑郁障碍防治指南（第二版，2015）"],"rank":1},{"id":"psych_gad7","name":"广泛性焦虑障碍量表 GAD-7","aka":["Generalized Anxiety Disorder-7","GAD-7"],"cat":"情绪与焦虑","desc":"7 项自评（近 2 周焦虑症状，每项 0–3），总分 0–21，筛查焦虑并量化严重度。","inputs":[{"key":"q1","label":"感到紧张、焦虑或急切","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q2","label":"不能停止或控制担忧","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q3","label":"对各种各样的事情担忧过多","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q4","label":"很难放松下来","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q5","label":"由于不安而无法静坐","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q6","label":"容易变得烦恼或急躁","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true},{"key":"q7","label":"感到害怕，似乎会有可怕的事情发生","type":"select","options":[{"value":0,"label":"0：完全不会"},{"value":1,"label":"1：好几天"},{"value":2,"label":"2：一半以上时间"},{"value":3,"label":"3：几乎每天"}],"required":true}],"formula":"GAD-7 = 7 项之和（每项 0–3），总分 0–21","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：无明显焦虑；提供心理教育与压力管理"},{"when":"v <= 9","level":"warn","text":"5–9 分：轻度焦虑；心理治疗（CBT）+ 规律运动，必要时短期苯二氮平类（限 2–4 周）"},{"when":"v <= 14","level":"warn","text":"10–14 分：中度；首选 SSRI/SNRI，联合 CBT，4–6 周评估疗效"},{"when":"v >= 15","level":"high","text":"≥ 15 分：重度；专科治疗，排查甲亢、心律失常、咖啡因依赖与物质滥用"}],"note":"GAD-7 也可用于惊恐、社交焦虑等其他焦虑障碍的筛查；其焦虑项目高但无特定恐惧时，需结合结构式访谈；躯体化突出者需排除心血管、内分泌疾病。","refs":["Spitzer RL, Kroenke K, Williams JB, Löwe B. Arch Intern Med 2006（GAD-7 原版）","中国精神障碍诊疗规范（2020 年版）","中华医学会：中国焦虑障碍防治指南（2012）"],"rank":2},{"id":"psych_hamd17","name":"汉密尔顿抑郁量表 HAMD-17","aka":["Hamilton Depression Rating Scale-17","HDRS-17"],"cat":"他评量表","desc":"17 项半结构化他评（其中 8 项 0–4、9 项 0–2），总分 0–52，评估抑郁严重度与疗效，临床试验常用。","inputs":[{"key":"mood","label":"抑郁情绪（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：询问时始叙述"},{"value":2,"label":"2：自发叙述"},{"value":3,"label":"3：表情/姿势显露"},{"value":4,"label":"4：言语与表情活动均显抑郁"}],"required":true},{"key":"guilt","label":"罪恶感（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：自我谴责"},{"value":2,"label":"2：自责或对往事后悔"},{"value":3,"label":"3：认为生病是惩罚"},{"value":4,"label":"4：罪恶妄想"}],"required":true},{"key":"suicide","label":"自杀（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：活着没意思"},{"value":2,"label":"2：希望自己已死"},{"value":3,"label":"3：自杀观念或自杀姿态"},{"value":4,"label":"4：自杀未遂"}],"required":true},{"key":"insomnia_early","label":"入睡困难（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：偶有"},{"value":2,"label":"2：每晚均入睡困难"}],"required":true},{"key":"insomnia_mid","label":"睡眠中段觉醒（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：偶有"},{"value":2,"label":"2：每晚均醒"}],"required":true},{"key":"insomnia_late","label":"早醒（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：偶有"},{"value":2,"label":"2：每晚早醒"}],"required":true},{"key":"work","label":"工作与兴趣（0–4）","type":"select","options":[{"value":0,"label":"0：无困难"},{"value":1,"label":"1：感吃力"},{"value":2,"label":"2：兴趣减退、效率下降"},{"value":3,"label":"3：活动明显减少"},{"value":4,"label":"4：因症状停止工作"}],"required":true},{"key":"retardation","label":"迟缓（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：明显"},{"value":3,"label":"3：严重"},{"value":4,"label":"4：木僵"}],"required":true},{"key":"agitation","label":"激越（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：坐立不安"},{"value":2,"label":"2：小动作多"},{"value":3,"label":"3：不能安坐"},{"value":4,"label":"4：反复来回走动/绞手"}],"required":true},{"key":"anxiety_psych","label":"精神性焦虑（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"anxiety_somatic","label":"躯体性焦虑（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"somatic_gi","label":"胃肠道症状（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：有"},{"value":2,"label":"2：严重"}],"required":true},{"key":"somatic_general","label":"全身症状（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：有"},{"value":2,"label":"2：严重"}],"required":true},{"key":"genital","label":"生殖系统症状（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：重度"}],"required":true},{"key":"hypochondria","label":"疑病（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：关注身体"},{"value":2,"label":"2：过分担忧"},{"value":3,"label":"3：反复求医"},{"value":4,"label":"4：疑病妄想"}],"required":true},{"key":"insight","label":"体重减轻（0–2）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：可能减轻"},{"value":2,"label":"2：确定减轻（> 0.5 kg/周）"}],"required":true},{"key":"loss_insight","label":"自知力（0–2）","type":"select","options":[{"value":0,"label":"0：自知有病"},{"value":1,"label":"1：部分承认"},{"value":2,"label":"2：完全否认"}],"required":true}],"formula":"HAMD-17 = 17 项之和（8 项 0–4 + 9 项 0–2），总分 0–52","compute":"sum","interpret":[{"when":"suicide >= 3","level":"crit","text":"自杀项 ≥ 3：存在自杀观念/姿态或未遂，立即行 C-SSRS 评估，考虑住院与防自杀措施"},{"when":"v <= 7","level":"ok","text":"0–7 分：正常或无抑郁"},{"when":"v <= 13","level":"warn","text":"8–13 分：轻度抑郁；心理治疗为主，1–2 周复评"},{"when":"v <= 18","level":"warn","text":"14–18 分：中度；抗抑郁药 + 心理治疗，评估自杀与躯体状况"},{"when":"v <= 24","level":"high","text":"19–24 分：重度；药物剂量优化、联合心理治疗，可考虑增效（rTMS/ECT 评估）"},{"when":"v > 24","level":"crit","text":"> 24 分：极重度；住院评估，排除精神病性症状与紧张症，考虑 ECT"}],"note":"HAMD-17 为他评量表（需培训的评定者），含 17 项以外的睡眠/体重等条目不计入；疗效评价常用减分率 ≥ 50% 为有效，< 7 分为缓解。内容效度侧重躯体和睡眠。","refs":["Hamilton M. J Neurol Neurosurg Psychiatry 1960（HAMD 原版）","中华医学会：中国抑郁障碍防治指南（第二版，2015）","中国精神障碍诊疗规范（2020 年版）"],"rank":3},{"id":"psych_hama","name":"汉密尔顿焦虑量表 HAMA","aka":["Hamilton Anxiety Rating Scale","HAMA"],"cat":"他评量表","desc":"14 项半结构化他评（精神性焦虑 6 项、躯体性焦虑 8 项，各 0–4 分），总分 0–56，评估焦虑严重度与疗效。","inputs":[{"key":"anxious_mood","label":"焦虑心境（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"tension","label":"紧张（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"fears","label":"恐惧（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"insomnia","label":"失眠（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"intellectual","label":"认知功能（记忆、注意）障碍（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"depressed_mood","label":"抑郁心境（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"somatic_muscular","label":"躯体性焦虑：肌肉系统（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"somatic_sensory","label":"躯体性焦虑：感觉系统（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"cardiovascular","label":"心血管系统症状（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"respiratory","label":"呼吸系统症状（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"gi","label":"胃肠道症状（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"genitourinary","label":"生殖泌尿系统症状（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"autonomic","label":"自主神经症状（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"interview_behavior","label":"会谈时行为表现（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true}],"formula":"HAMA = 14 项之和（每项 0–4），总分 0–56；精神性焦虑 6 项（0–24），躯体性焦虑 8 项（0–32）","compute":"sum","interpret":[{"when":"v < 7","level":"ok","text":"< 7 分：无焦虑"},{"when":"v <= 13","level":"ok","text":"7–13 分：可能焦虑；结合 GAD-7 与临床访谈确认"},{"when":"v <= 20","level":"warn","text":"14–20 分：肯定有焦虑；心理治疗 + 药物治疗（SSRI/SNRI），4 周评估"},{"when":"v <= 28","level":"high","text":"21–28 分：明显焦虑；专科治疗，评估惊恐发作、物质使用与器质性疾病"},{"when":"v > 28","level":"crit","text":"> 28 分：严重焦虑；需住院或加强门诊管理，注意激越、自伤风险与锥体外系反应"}],"note":"HAMA 与 HAMD 部分条目重叠（抑郁心境），两者不宜简单相加；HAMA 侧重躯体和焦虑，对焦虑疗效评价敏感。","refs":["Hamilton M. Br J Med Psychol 1959（HAMA 原版）","中华医学会：中国焦虑障碍防治指南（2012）","中国精神障碍诊疗规范（2020 年版）"],"rank":4},{"id":"psych_panss","name":"阳性与阴性症状量表 PANSS","aka":["Positive and Negative Syndrome Scale","PANSS"],"cat":"精神分裂症","desc":"30 项（阳性 7、阴性 7、一般精神病理 16，各 1–7 分）他评量表，总分 30–210，评估精神分裂症症状谱与疗效。","inputs":[{"key":"positive","label":"阳性症状分（P7 项，7–49）","unit":"分","type":"number","min":7,"max":49,"step":1,"required":true,"hint":"P1-P7 之和"},{"key":"negative","label":"阴性症状分（N7 项，7–49）","unit":"分","type":"number","min":7,"max":49,"step":1,"required":true,"hint":"N1-N7 之和"},{"key":"general","label":"一般精神病理分（G16 项，16–112）","unit":"分","type":"number","min":16,"max":112,"step":1,"required":true,"hint":"G1-G16 之和"}],"formula":"PANSS 总分 = 阳性（7–49）+ 阴性（7–49）+ 一般精神病理（16–112），30–210；复合分 = 阳性 − 阴性","compute":"sum","algorithm":"v = positive + negative + general\ncomposite = positive - negative   # 复合分 > 0 提示阳性症状优势，< 0 提示阴性症状优势","interpret":[{"when":"v < 58","level":"ok","text":"30–57 分：症状轻微/缓解；维持在缓解（≤ 3 分每项）并预防复发"},{"when":"v <= 75","level":"warn","text":"58–75 分：轻中度；核对抗精神病药剂量与依从性，心理教育"},{"when":"v <= 95","level":"warn","text":"76–95 分：中度；调整抗精神病药（换用/联合/长效针剂），评估代谢与锥体外系不良反应"},{"when":"v <= 115","level":"high","text":"96–115 分：中重度；考虑氯氮平（难治性，需监测白细胞），减少应激源"},{"when":"v > 115","level":"crit","text":"> 115 分：重度；精神科住院评估，警惕冲动、自伤/他伤与兴奋性谵妄，先排除物质与器质性病因"}],"note":"PANSS 的 30 项逐项 1–7 分，需培训评定者；疗效常用减分 ≥ 30% 为部分有效、≥ 50% 为明显有效。PANSS-6 简化版适合门诊快速评估。","refs":["Kay SR, Fiszbein A, Opler LA. Schizophr Bull 1987（PANSS 原版）","中国精神分裂症防治指南（第二版，2015）","中国精神障碍诊疗规范（2020 年版）"],"rank":5},{"id":"psych_ymrs","name":"Young 躁狂评定量表 YMRS","aka":["Young Mania Rating Scale","YMRS"],"cat":"双相障碍","desc":"11 项临床他评，其中 4 项（易激惹、言语、思维内容、破坏性行为）0–8 分，其余 0–4 分，总分 0–60，评估躁狂严重度。","inputs":[{"key":"elevated_mood","label":"心境高涨（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度或可能"},{"value":2,"label":"2：明确但可控制"},{"value":3,"label":"3：明显"},{"value":4,"label":"4：极重"}],"required":true},{"key":"motor","label":"活动-精力增加（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"sexual","label":"性兴趣（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：中度"},{"value":3,"label":"3：重度"},{"value":4,"label":"4：极重"}],"required":true},{"key":"sleep","label":"睡眠（0–4）","type":"select","options":[{"value":0,"label":"0：睡眠正常"},{"value":1,"label":"1：比平时少 1 h"},{"value":2,"label":"2：少 1–2 h"},{"value":3,"label":"3：少 2–3 h"},{"value":4,"label":"4：不愿睡/无法睡"}],"required":true},{"key":"irritability","label":"易激惹（0–8）","type":"select","options":[{"value":0,"label":"0：无"},{"value":2,"label":"2：易怒，开始提问即显敌意"},{"value":4,"label":"4：明显易激惹，明显敌意"},{"value":6,"label":"6：非常易怒，面谈无法进行"},{"value":8,"label":"8：敌对，破坏性，需要约束"}],"required":true},{"key":"speech","label":"言语（0–8）","type":"select","options":[{"value":0,"label":"0：正常"},{"value":2,"label":"2：语速快，略增多"},{"value":4,"label":"4：语速加快，交谈困难"},{"value":6,"label":"6：语速极快，无法交谈"},{"value":8,"label":"8：言语不可理解"}],"required":true},{"key":"thought_form","label":"思维形式障碍（0–4）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度离题"},{"value":2,"label":"2：明显离题"},{"value":3,"label":"3：思维奔逸"},{"value":4,"label":"4：思维散漫，无法跟随"}],"required":true},{"key":"thought_content","label":"思维内容（0–8）","type":"select","options":[{"value":0,"label":"0：正常"},{"value":2,"label":"2：有夸大观念但可置疑"},{"value":4,"label":"4：夸大妄想/被害妄想"},{"value":6,"label":"6：妄想伴冲动情绪"},{"value":8,"label":"8：妄想支配行为"}],"required":true},{"key":"disruptive","label":"破坏性-攻击行为（0–8）","type":"select","options":[{"value":0,"label":"0：无"},{"value":2,"label":"2：偶有挑衅"},{"value":4,"label":"4：有威胁言语"},{"value":6,"label":"6：有冲动破坏行为"},{"value":8,"label":"8：有暴力，需约束"}],"required":true},{"key":"appearance","label":"外貌（0–4）","type":"select","options":[{"value":0,"label":"0：正常"},{"value":1,"label":"1：轻度不注意外表"},{"value":2,"label":"2：中度不注意"},{"value":3,"label":"3：邋遢"},{"value":4,"label":"4：极不整"}],"required":true},{"key":"insight","label":"自知力（0–4）","type":"select","options":[{"value":0,"label":"0：有自知力"},{"value":1,"label":"1：可能患病"},{"value":2,"label":"2：承认行为改变但否认患病"},{"value":3,"label":"3：否认任何变化"},{"value":4,"label":"4：完全不合作"}],"required":true}],"formula":"YMRS = 11 项之和（易激惹、言语、思维内容、破坏性行为 0–8；其余 0–4），总分 0–60","compute":"sum","interpret":[{"when":"v <= 12","level":"ok","text":"0–12 分：无或轻度躁狂（缓解期）；随访并评估情绪稳定剂血药浓度"},{"when":"v <= 20","level":"warn","text":"13–20 分：轻中度躁狂；调整心稳定剂（锂盐/丙戊酸），减停抗抑郁药，规律睡眠"},{"when":"v <= 30","level":"high","text":"21–30 分：中度躁狂；加用非典型抗精神病药，监护自杀与冲动风险，限制刺激性活动"},{"when":"v > 30","level":"crit","text":"> 30 分：重度躁狂/精神病性；住院治疗，排除甲亢、物质（可卡因/类固醇）与谵妄，注意约束安全"}],"note":"需与 HAMD 联合评估混合特征；锂盐起始 300 mg bid 并 5–7 天查血锂（目标 0.6–0.8 mmol/L，急性期 0.8–1.2）。","refs":["Young RC, Biggs JT, Ziegler VE, Meyer DA. Br J Psychiatry 1978（YMRS 原版）","中华医学会：中国双相障碍防治指南（第二版，2015）","中国精神障碍诊疗规范（2020 年版）"],"rank":6},{"id":"psych_cssrs","name":"哥伦比亚自杀严重程度评定量表 C-SSRS","aka":["Columbia-Suicide Severity Rating Scale","C-SSRS"],"cat":"风险评估","desc":"按意念、强度、行为（5 类）分级评估自杀风险，确定干预级别（观察、安全计划、住院）。","inputs":[{"key":"ideation","label":"过去 1 个月最高自杀意念（1–5）","type":"select","options":[{"value":1,"label":"1：希望死去（被动）"},{"value":2,"label":"2：非特异性主动念头"},{"value":3,"label":"3：有方法但不行动"},{"value":4,"label":"4：有意图但无具体计划"},{"value":5,"label":"5：有意图与具体计划"}],"required":true},{"key":"intensity","label":"意念强度总分（频率、持续时间、可控性、威慢因素、原因 各 0–5，共 0–25）","unit":"分","type":"number","min":0,"max":25,"step":1,"required":true},{"key":"behavior","label":"终身自杀行为（过去 3 个月）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：准备行为（无意图的自伤）"},{"value":2,"label":"2：自伤行为（非自杀性）"},{"value":3,"label":"3：中止/被打断的未遂"},{"value":4,"label":"4：有实际致死可能的未遂"},{"value":5,"label":"5：有致死可能的实际未遂"}],"required":true},{"key":"access","label":"近期可获取自杀手段（药物/利器/高处等）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"分三档风险：低（意念 ≤ 2 且无行为）、中（意念 3–4 或强度 ≥ 10）、高（意念 5、行为 ≥ 3 或有手段获取）","compute":"formula_only","algorithm":"if ideation == 5 || behavior >= 3 || access == 1: v = '高风险'\nelif ideation >= 3 || intensity >= 10: v = '中风险'\nelse: v = '低风险'\n# 存在行动预案与致命手段可获取者按高风险处理","interpret":[{"when":"access == 1 || behavior >= 3 || ideation == 5","level":"crit","text":"高风险：立即精神科急会诊，1:1 陪护、清除危险物品（限制手段获取），评估是否需要强制住院与保护性约束，与家属/监护人沟通"},{"when":"ideation >= 3 || intensity >= 10","level":"high","text":"中风险：当日完成安全计划（警示信号、应对策略、求助联系人），增加随访频次（≤ 72 h），治疗药物（慎用三环类/大剂量）"},{"when":"true","level":"warn","text":"低风险：心理教育、安全计划与定期随访；持续筛查（每次就诊）+ 24 h 危机热线"}],"note":"C-SSRS 分为基线/筛查版与随访版，须按对应版本询问；临终、意识障碍患者结合代理人信息。有自伤史者 1 年内风险升高 5–9 倍。","refs":["Posner K et al. Am J Psychiatry 2011（C-SSRS 验证研究）","中国精神障碍诊疗规范（2020 年版）中自杀风险评估章节","中华医学会精神医学分会：中国自杀预防相关专家共识（2019）"],"rank":7},{"id":"psych_ciwa_ar","name":"酒精戒断评估 CIWA-Ar","aka":["Clinical Institute Withdrawal Assessment for Alcohol, Revised","CIWA-Ar"],"cat":"物质依赖","desc":"10 项评估（其中 3 项体征），总分 0–67，指导酒精戒断的基于症状的苯二氮平类给药。","inputs":[{"key":"nausea","label":"恶心/呕吐（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度恶心无呕吐"},{"value":2,"label":"2：干呕"},{"value":3,"label":"3：呕吐 1–3 次/日"},{"value":4,"label":"4：呕吐 ≥ 4 次/日"},{"value":5,"label":"5：持续呕吐"},{"value":6,"label":"6：呕吐伴脱水"},{"value":7,"label":"7：呕吐伴休克/衰竭"}],"required":true},{"key":"tremor","label":"震颤（0–7，双臂前伸）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：仅用手指可见"},{"value":2,"label":"2：双手可见"},{"value":3,"label":"3：明显，上肢可抬"},{"value":4,"label":"4：明显，上肢不可抬"},{"value":5,"label":"5：全身性粗大震颤"},{"value":6,"label":"6：严重震颤影响活动"},{"value":7,"label":"7：极度震颤，无法完成动作"}],"required":true},{"key":"sweat","label":"出汗（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：手心潮湿"},{"value":2,"label":"2：前额可见汗珠"},{"value":3,"label":"3：前额汗珠明显"},{"value":4,"label":"4：全身性出汗"},{"value":5,"label":"5：全身大汗"},{"value":6,"label":"6：大汗伴湿透衣物"},{"value":7,"label":"7：极度出汗"}],"required":true},{"key":"anxiety","label":"焦虑（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"agitation","label":"激惹不安（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"tactile","label":"触觉异常（蚁行感/瘙痒，0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"auditory","label":"听觉异常（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"visual","label":"视觉异常（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"headache","label":"头痛（0–7）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：轻度"},{"value":2,"label":"2：轻度"},{"value":3,"label":"3：中度"},{"value":4,"label":"4：中度"},{"value":5,"label":"5：重度"},{"value":6,"label":"6：重度"},{"value":7,"label":"7：极度"}],"required":true},{"key":"orientation","label":"定向力与意识（0–4）","type":"select","options":[{"value":0,"label":"0：正常"},{"value":1,"label":"1：不确定日期"},{"value":2,"label":"2：日期错误 < 2 天"},{"value":3,"label":"3：日期错误 > 2 天"},{"value":4,"label":"4：对人物/地点定向障碍"}],"required":true}],"formula":"CIWA-Ar = 9 项（各 0–7）+ 定向力（0–4），总分 0–67","compute":"sum","interpret":[{"when":"v <= 8","level":"ok","text":"0–8 分：轻度戒断；不需常规苯二氮平，每 4–8 h 复评，补充维生素 B1（硫胺素 100 mg 肌注/口服）"},{"when":"v <= 15","level":"warn","text":"9–15 分：中度；地西泮 10–20 mg 或劳拉西泮 2–4 mg 口服，按需，每小时复评至 ≤ 8 分"},{"when":"v <= 20","level":"high","text":"16–20 分：中重度；地西泮 20 mg 口服，肝功能不全用劳拉西泮；监测生命体征、血糖与电解质"},{"when":"v > 20","level":"crit","text":"> 20 分：重度戒断；警惕酒精戒断性癫痫（通常 6–48 h）与震颤谵妄（48–96 h）、Wernicke 脑病，静脉苯二氮平并收治监护"}],"note":"CIWA-Ar 不适用于无法交流、已伴谵妄或合并其他镇静药物者；肝功能不全与老年患者改用劳拉西泮，长效地西泮在肝硬化中半衰期延长。","refs":["Sullivan JT et al. Br J Addict 1989（CIWA-Ar 原版）","中国酒精依赖诊疗指南（2019，中华医学会精神医学分会）","ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020)"],"rank":8},{"id":"psych_cage","name":"CAGE 酒精问题筛查","aka":["CAGE Questionnaire","CAGE 问卷"],"cat":"物质依赖","desc":"4 个是/否问题快速筛查酒精使用障碍，≥ 2 分为阳性，最适合门诊与急诊初筛。","inputs":[{"key":"cut_down","label":"是否曾觉得应该减少饮酒？（Cut down）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"annoyed","label":"是否因别人批评饮酒而烦恼？（Annoyed）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"guilty","label":"是否对饮酒感到内疚？（Guilty）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"eye_opener","label":"是否早晨起床先饮酒以稳定情绪？（Eye-opener）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"CAGE = 4 项「是」的个数（0–4），≥ 2 为阳性","compute":"sum","interpret":[{"when":"v == 0","level":"ok","text":"0 分：筛查阴性；仍建议询问标准饮酒量（男性 ≤ 25 g/日，女性 ≤ 15 g/日）"},{"when":"v == 1","level":"warn","text":"1 分：需澄清；若「晨饮」或「愧疚」单项阳性应进一步行 AUDIT 与临床评估"},{"when":"v == 2","level":"warn","text":"2 分：阳性（敏感度约 74%、特异度 91%）；行 AUDIT、肝功能与电解质，给予简短干预（5A 法）"},{"when":"v >= 3","level":"high","text":"3–4 分：高度提示酒精使用障碍；评估戒断风险（CIWA-Ar）、转诊成瘾专科与心理治疗"}],"note":"CAGE 对女性灵敏度较低，孕期与青少年患者不适用；筛查阳性不等于诊断，AUDIT ≥ 8 更符合 DSM-5 酒精使用障碍。","refs":["Ewing JA. JAMA 1984（CAGE 原版）","中国酒精依赖诊疗指南（2019）","WHO AUDIT：The Alcohol Use Disorders Identification Test（2001）"],"rank":9},{"id":"psych_audit","name":"酒精使用障碍筛查量表 AUDIT","aka":["Alcohol Use Disorders Identification Test","AUDIT"],"cat":"物质依赖","desc":"WHO 10 项筛查（3 项饮酒量、4 项依赖、3 项危害），总分 0–40，识别危险饮酒与酒精使用障碍。","inputs":[{"key":"q1","label":"多久饮酒一次（饮酒频度）","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月 1 次或更少"},{"value":2,"label":"2：每月 2–4 次"},{"value":3,"label":"3：每周 2–4 次"},{"value":4,"label":"4：每天或几乎每天"}],"required":true},{"key":"q2","label":"典型饮酒日饮用标准杯数（1 标准杯≈10 g 纯酒精）","type":"select","options":[{"value":0,"label":"0：1–2 杯"},{"value":1,"label":"1：3–4 杯"},{"value":2,"label":"2：5–6 杯"},{"value":3,"label":"3：7–9 杯"},{"value":4,"label":"4：≥ 10 杯"}],"required":true},{"key":"q3","label":"每次喝 6 杯或以上（狂饮）的频度","type":"select","options":[{"value":0,"label":"0：没有"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：几乎每天"}],"required":true},{"key":"q4","label":"开始饮酒后难以停止（失控）的频度","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：每天"}],"required":true},{"key":"q5","label":"无法完成期望的事情的频度","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：每天"}],"required":true},{"key":"q6","label":"早晨需要饮酒（晨饮）的频度","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：每天"}],"required":true},{"key":"q7","label":"饮酒后感到内疚或后悔的频度","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：每天"}],"required":true},{"key":"q8","label":"因饮酒而忘记前一晚事情的频度（断片）","type":"select","options":[{"value":0,"label":"0：从不"},{"value":1,"label":"1：每月不足 1 次"},{"value":2,"label":"2：每月"},{"value":3,"label":"3：每周"},{"value":4,"label":"4：每天"}],"required":true},{"key":"q9","label":"你或他人因饮酒受伤（含跌倒、外伤、事故）","type":"select","options":[{"value":0,"label":"0：没有"},{"value":2,"label":"2：有，但非过去一年"},{"value":4,"label":"4：过去一年有"}],"required":true},{"key":"q10","label":"亲友、医生曾建议你戒酒","type":"select","options":[{"value":0,"label":"0：没有"},{"value":2,"label":"2：有，但非过去一年"},{"value":4,"label":"4：过去一年有"}],"required":true}],"formula":"AUDIT = 10 项之和；第 1–8 题 0–4 分，第 9–10 题 0/2/4 分，总分 0–40","compute":"sum","interpret":[{"when":"v <= 7","level":"ok","text":"0–7 分：低风险饮酒；健康宣教与定期再筛"},{"when":"v <= 15","level":"warn","text":"8–15 分：危险饮酒；简短干预（反馈+建议+目标设定），1 个月内复评"},{"when":"v <= 19","level":"high","text":"16–19 分：有害饮酒；动机性访谈 + 戒酒目标，评估肝功能、血压与睡眠"},{"when":"v > 19","level":"crit","text":"≥ 20 分：可疑酒精依赖；成瘾专科转诊，评估戒断风险（CIWA-Ar）与硫胺素补充"}],"note":"女性、老年人阈值较低（≥ 6–7 分为阳性）；AUDIT-C（3 题）适合快速筛查。注意硫胺素缺乏导致 Wernicke 脑病。","refs":["Babor TF et al. AUDIT: The Alcohol Use Disorders Identification Test — Guidelines for Use in Primary Care, WHO 2001","中国酒精依赖诊疗指南（2019）","DSM-5 酒精使用障碍诊断标准（APA 2013）"],"rank":10},{"id":"psych_psqi","name":"匹兹堡睡眠质量指数 PSQI","aka":["Pittsburgh Sleep Quality Index","PSQI"],"cat":"睡眠","desc":"7 个成分（主观睡眠质量、潜伏期、时长、效率、紊乱、药物、日间功能，各 0–3），总分 0–21，> 5 提示睡眠质量差。","inputs":[{"key":"sleep_quality","label":"C1 主观睡眠质量","type":"select","options":[{"value":0,"label":"0：很好"},{"value":1,"label":"1：较好"},{"value":2,"label":"2：较差"},{"value":3,"label":"3：很差"}],"required":true},{"key":"latency","label":"C2 入睡困难（需 > 30 min 的频次）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：< 1 次/周"},{"value":2,"label":"2：1–2 次/周"},{"value":3,"label":"3：≥ 3 次/周"}],"required":true},{"key":"duration","label":"C3 实际睡眠时长","type":"select","options":[{"value":0,"label":"0：> 7 h"},{"value":1,"label":"1：6–7 h"},{"value":2,"label":"2：5–6 h"},{"value":3,"label":"3：< 5 h"}],"required":true},{"key":"efficiency","label":"C4 睡眠效率（睡眠时间/卧床时间）","type":"select","options":[{"value":0,"label":"0：≥ 85%"},{"value":1,"label":"1：75–84%"},{"value":2,"label":"2：65–74%"},{"value":3,"label":"3：< 65%"}],"required":true},{"key":"disturbance","label":"C5 睡眠紊乱（夜醒/上厕所等频次）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：< 1 次/周"},{"value":2,"label":"2：1–2 次/周"},{"value":3,"label":"3：≥ 3 次/周"}],"required":true},{"key":"medication","label":"C6 使用催眠药物","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：< 1 次/周"},{"value":2,"label":"2：1–2 次/周"},{"value":3,"label":"3：≥ 3 次/周"}],"required":true},{"key":"dysfunction","label":"C7 日间功能障碍（困倦、精力不足）","type":"select","options":[{"value":0,"label":"0：无"},{"value":1,"label":"1：< 1 次/周"},{"value":2,"label":"2：1–2 次/周"},{"value":3,"label":"3：≥ 3 次/周"}],"required":true}],"formula":"PSQI = C1 + C2 + C3 + C4 + C5 + C6 + C7，各成分 0–3，总分 0–21","compute":"sum","interpret":[{"when":"v <= 5","level":"ok","text":"0–5 分：睡眠质量良好；保持规律作息"},{"when":"v <= 10","level":"warn","text":"6–10 分：睡眠质量差；睡眠卫生宣教 + 刺激控制，评估焦虑抑郁（PHQ-9/GAD-7）"},{"when":"v <= 15","level":"warn","text":"11–15 分：中度失眠；CBT-I（失眠认知行为治疗）为一线，限制卧床时间与午睡"},{"when":"v > 15","level":"high","text":"> 15 分：重度睡眠障碍；评估 OSAHS（打鼾/夜间憋醒）、RLS、慢性疼痛与药物（β 受体阻滞剂、糖皮质激素）"}],"note":"PSQI 为过去 1 个月的回顾性自评，不宜用于单次失眠的评价；CBT-I 优于长期催眠药；老年人与抑郁患者需结合客观 PSG。","refs":["Buysse DJ et al. Psychiatry Res 1989（PSQI 原版）","中国成人失眠诊断与治疗指南（2017，中华医学会神经病学分会）","AASM International Classification of Sleep Disorders, 3rd ed. 2014"],"rank":11},{"id":"psych_cam","name":"意识状态评估法 CAM（谵妄筛查）","aka":["Confusion Assessment Method","CAM"],"cat":"谵妄与意识","desc":"基于 DSM 的 4 特征法筛查谵妄（急性起病与波动、注意力不集中、思维紊乱、意识水平改变），住院患者常用。","inputs":[{"key":"acute","label":"急性起病且病程波动（①②）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"inattention","label":"注意力不集中（③）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"disorganized","label":"思维紊乱（④）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"altered_loc","label":"意识水平改变（⑤）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"阳性 = （①急性起病/波动 且 ③注意力不集中）且（④思维紊乱 或 ⑤意识水平改变）；总分 0–4（仅作记录）","compute":"sum","algorithm":"v = acute + inattention + disorganized + altered_loc\npositive = (acute == 1 && inattention == 1) && (disorganized == 1 || altered_loc == 1)","interpret":[{"when":"acute == 1 && inattention == 1 && (disorganized == 1 || altered_loc == 1)","level":"crit","text":"CAM 阳性：诊断谵妄（DSM-5/ICD-11 需补充排除其他病因）；立即查血糖、电解质、血气、血氨、尿常规、感染灶与用药（抗胆碱能药）"},{"when":"acute == 1 && inattention == 1","level":"high","text":"急性起病+注意力障碍但无其他特征：疑似谵妄，复评（至少每日 2 次）并行 4AT/ICDSC 辅助"},{"when":"true","level":"ok","text":"CAM 阴性：仍需高危患者每日筛查（ICU 用 CAM-ICU，需 RASS ≥ −3 方能评估注意力）"}],"note":"CAM 不适用于昏迷/严重听力语言障碍者；老年人谵妄常表现为低活动型，易漏诊；需区分痴呆基础（既往认知）。","refs":["Inouye SK et al. Ann Intern Med 1990（CAM 原版）","中国老年患者术后谵妄防治相关专家共识（2017）","NICE Delirium: Prevention, Diagnosis and Management（NICE CG103，2023）"],"rank":12}]},"renal":{"items":[{"id":"renal_ckdepi2021","name":"CKD-EPI 2021 估算肾小球滤过率","aka":["eGFR CKD-EPI 2021","eGFRcr 2021"],"cat":"肾功能评估","rank":1,"desc":"基于血肌酐、年龄、性别的 2021 无种族 CKD-EPI 公式（当前推荐）。","inputs":[{"key":"scr","label":"血肌酐 Scr","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true}],"formula":"eGFR = 142×min(Scr/κ,1)^α×max(Scr/κ,1)^(−1.200)×0.9938^age×1.012(女)；κ=0.7(女)/0.9(男)，α=−0.241(女)/−0.302(男)","compute":"egfr_ckdepi","interpret":[{"when":"v >= 90","level":"ok","text":"G1：eGFR ≥ 90，若有肾损伤标志物则为 CKD"},{"when":"v >= 60 && v < 90","level":"ok","text":"G2：60–89，若有白蛋白尿等标志物持续 3 个月则为 CKD"},{"when":"v >= 45 && v < 60","level":"warn","text":"G3a：45–59，需按年龄校正用考虑是否 CKD，评估并发症"},{"when":"v >= 30 && v < 45","level":"high","text":"G3b：30–44，评估贫血、钙磷、酸中毒，药物剂量调整"},{"when":"v >= 15 && v < 30","level":"high","text":"G4：15–29，肾科转诊、准备肾脏替代治疗"},{"when":"v < 15","level":"crit","text":"G5：< 15，肾衰竭，启动透析/移植评估"}],"note":"输入肌酐须为 mg/dL（如为 μmol/L 请除以 88.4）；肌肉量异常、截肢、妊娠时准确性下降，可联合胱抑素 C（eGFRcr-cys）。","refs":["中国慢性肾脏病早期评价与管理指南（2023）","KDIGO 2024 CKD Guideline","Inker LA, et al. NEJM 2021 (CKD-EPI 2021)"]},{"id":"renal_ckdepi2021_norace","name":"CKD-EPI 2009 无种族校正版（历史对照）","aka":["CKD-EPI 2009 无种族","eGFRrace-free historical"],"cat":"肾功能评估","rank":13,"desc":"2009 版 CKD-EPI 公式去除种族系数的形式，用于与旧报告数据对照复评。","inputs":[{"key":"scr","label":"血肌酐 Scr","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true}],"formula":"eGFR = 141×min(Scr/κ,1)^α×max(Scr/κ,1)^(−1.209)×0.993^age×1.018(女)；κ=0.7(女)/0.9(男)，α=−0.329(女)/−0.411(男)","compute":"formula_only","algorithm":"k = sex==0?0.7:0.9; a = sex==0?-0.329:-0.411\nv = 141 * Math.pow(Math.min(scr/k,1),a) * Math.pow(Math.max(scr/k,1),-1.209) * Math.pow(0.993,age) * (sex==0?1.018:1)","interpret":[{"when":"v < 15","level":"crit","text":"G5 区间"},{"when":"v >= 15 && v < 30","level":"high","text":"G4 区间"},{"when":"v >= 30 && v < 60","level":"warn","text":"G3a/G3b 区间"},{"when":"v >= 60","level":"ok","text":"G1/G2 区间"}],"note":"新版推荐改用 CKD-EPI 2021（无种族）；此式仅用于复评历史报告，不作为当前诊断依据。","refs":["KDIGO 2024 CKD Guideline","Inker LA, et al. NEJM 2021 附录（race-free 复现）"]},{"id":"renal_cockcroft_gault","name":"Cockcroft-Gault 肌酐清除率","aka":["Ccr","CG 公式"],"cat":"肾功能评估","rank":2,"desc":"估算肌酐清除率，广泛用于药物剂量调整。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"weight_kg","label":"体重","unit":"kg","type":"number","min":20,"max":250,"step":0.1,"required":true},{"key":"scr","label":"血肌酐 Scr","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true}],"formula":"Ccr(mL/min) = (140−年龄)×体重×0.85(女) / [72×Scr(mg/dL)]","compute":"crcl_cockcroft","interpret":[{"when":"v < 15","level":"crit","text":"Ccr < 15：重度肾功能不全，多数经肾排泄药物需减量或禁用，核查说明书"},{"when":"v >= 15 && v < 30","level":"high","text":"Ccr 15–29：重度减退，按说明书调整剂量，避免肾毒性药物"},{"when":"v >= 30 && v < 50","level":"warn","text":"Ccr 30–49：中度减退，注意经肾排泄药物与造影剂"},{"when":"v >= 50 && v < 80","level":"ok","text":"Ccr 50–79：轻度减退"},{"when":"v >= 80","level":"ok","text":"Ccr ≥ 80：正常范围"}],"note":"肥胖者建议用校正体重，消瘦者用实际体重；多数说明书剂量按本公式；Scr 单位若为 μmol/L 需换算。","refs":["中国慢性肾脏病早期评价与管理指南（2023）","Cockcroft DW, Gault MH. Nephron 1976"]},{"id":"renal_mdrd","name":"MDRD 公式估算 eGFR","aka":["MDRD-4","Modification of Diet in Renal Disease"],"cat":"肾功能评估","rank":12,"desc":"四变量 MDRD 公式，旧版常用 eGFR 估算。","inputs":[{"key":"scr","label":"血肌酐 Scr","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true}],"formula":"eGFR = 175×Scr^−1.154×年龄^−0.203×0.742(女)","compute":"formula_only","algorithm":"v = 175 * Math.pow(scr,-1.154) * Math.pow(age,-0.203) * (sex==0?0.742:1)","interpret":[{"when":"v < 15","level":"crit","text":"G5：< 15 mL/min/1.73m²"},{"when":"v >= 15 && v < 30","level":"high","text":"G4：15–29"},{"when":"v >= 30 && v < 60","level":"warn","text":"G3a/G3b：30–59"},{"when":"v >= 60","level":"ok","text":"G1/G2：≥ 60"}],"note":"MDRD 在 eGFR > 60 时偏差大，建议改用 CKD-EPI 2021；中国人群已有改良 MDRD（×1.233）用于历史数据。","refs":["中国慢性肾脏病早期评价与管理指南（2023）","Levey AS, et al. Ann Intern Med 2006 (MDRD-4)"]},{"id":"renal_uacr","name":"尿白蛋白/肌酐比值（UACR）与白蛋白尿分期","aka":["UACR","ACR","尿微量白蛋白"],"cat":"肾功能评估","rank":3,"desc":"由尿白蛋白浓度与尿肌酐计算 ACR，按 KDIGO A1–A3 分期。","inputs":[{"key":"ualb","label":"尿白蛋白浓度","unit":"mg/L","type":"number","min":0,"max":20000,"step":0.1,"required":true},{"key":"ucr","label":"尿肌酐浓度","unit":"μmol/L","type":"number","min":100,"max":50000,"step":1,"required":true}],"formula":"ACR(mg/g) = 尿白蛋白(mg/L) ÷ 尿肌酐(μmol/L) × 1000/8.84 ≈ mg/L ÷ mmol/L","compute":"formula_only","algorithm":"v = ualb / (ucr/1000) / 8.84  // mg/g","interpret":[{"when":"v < 30","level":"ok","text":"A1：< 30 mg/g，白蛋白尿正常或轻度升高"},{"when":"v >= 30 && v < 300","level":"warn","text":"A2：30–299 mg/g，中度白蛋白尿，启动 ACEI/ARB + SGLT2i 评估"},{"when":"v >= 300","level":"high","text":"A3：≥ 300 mg/g，重度白蛋白尿，需积极延缓 CKD 进展"}],"note":"建议晨尿 3–6 个月内至少 2 次阳性才诊断；运动、发热、UTI、月经期可假阳性；糖尿病用 mg/mmol 换算（×8.84）。","refs":["中国慢性肾脏病早期评价与管理指南（2023）","KDIGO 2024 CKD Guideline"]},{"id":"renal_kdigo_ckd_stage","name":"KDIGO CKD 分期与风险分级（G1–G5 / A1–A3 组合）","aka":["CKD 热图","KDIGO 风险分级"],"cat":"肾功能评估","rank":4,"desc":"组合 GFR 分期与白蛋白尿分期，给出复查频率与转诊建议，并绘制风险矩阵。","inputs":[{"key":"g_stage","label":"GFR 分期","unit":"","type":"select","options":[{"value":1,"label":"G1 ≥90"},{"value":2,"label":"G2 60–89"},{"value":3,"label":"G3a 45–59"},{"value":4,"label":"G3b 30–44"},{"value":5,"label":"G4 15–29"},{"value":6,"label":"G5 <15"}],"required":true},{"key":"a_stage","label":"白蛋白尿分期","unit":"","type":"select","options":[{"value":1,"label":"A1 <30 mg/g"},{"value":2,"label":"A2 30–299"},{"value":3,"label":"A3 ≥300"}],"required":true}],"formula":"风险矩阵：绿 = 低危（无 CKD 标志物时），黄 = 中危，橙 = 高危，红 = 极高危","compute":"formula_only","algorithm":"risk 由 g_stage 与 a_stage 查 KDIGO 热图：\n(G1,A1)=绿; (G1,A2)/(G2,A1)=黄; (G1,A3)/(G2,A2)/(G3a,A1)/(G2,A3)=橙;\nG3a,A2 / G3a,A3 / G3b 任意 A = 红；G4/G5 全部 红\nv = g_stage*10 + a_stage（便于渲染矩阵位）","interpret":[{"when":"g_stage == 1 && a_stage == 1","level":"ok","text":"低危：无 CKD（无其他肾损伤标志物时）；每年筛查"},{"when":"(g_stage == 1 && a_stage == 2) || (g_stage == 2 && a_stage == 1)","level":"warn","text":"中危：每 12 个月复查 eGFR/UACR"},{"when":"(g_stage <= 2 && a_stage == 3) || (g_stage == 2 && a_stage == 2) || (g_stage == 3 && a_stage == 1)","level":"high","text":"高危：每 6 个月复查；启动肾脏保护（ACEI/ARB、SGLT2i），控制血压与蛋白尿"},{"when":"(g_stage == 3 && a_stage >= 2) || g_stage >= 4","level":"crit","text":"极高危：每 3 个月复查，肾内科随访，评估并发症与替代治疗准备"}],"note":"CKD 需肾损伤标志物或 eGFR < 60 持续 ≥ 3 个月；G1–G2 仅在有白蛋白尿等标志物时诊断 CKD。","refs":["KDIGO 2024 CKD Guideline","中国慢性肾脏病早期评价与管理指南（2023）"]},{"id":"renal_aki_kdigo","name":"急性肾损伤 KDIGO 分期","aka":["AKI KDIGO","AKI 分期"],"cat":"急肾衰","rank":5,"desc":"按血肌酐升幅与尿量对 AKI 进行 1–3 期判定。","inputs":[{"key":"scr_ratio","label":"血肌酐 / 基线肌酐","unit":"倍","type":"number","min":0.5,"max":20,"step":0.01,"required":true},{"key":"scr_rise","label":"48 h 内肌酐绝对上升","unit":"mg/dL","type":"number","min":0,"max":10,"step":0.01,"required":false},{"key":"uo","label":"尿量","unit":"mL/kg/h","type":"number","min":0,"max":10,"step":0.01,"required":false},{"key":"uo_hours","label":"少尿持续时间","unit":"h","type":"number","min":0,"max":72,"step":1,"required":false},{"key":"rrt","label":"已行肾脏替代治疗","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"1 期：Scr 1.5–1.9×基线或升高 ≥0.3 mg/dL；2 期：2.0–2.9×；3 期：≥3.0× 或 Scr ≥4.0 mg/dL 或 RRT；尿量 <0.5 mL/kg/h ≥6 h","compute":"formula_only","algorithm":"stage = 0\nif rrt==1 → 3\nelif scr_ratio>=3 → 3\nelif scr_ratio>=2 → 2\nelif scr_ratio>=1.5 || scr_rise>=0.3 → 1\n尿量：<0.5 ×6h → 1；<0.5 ×12h → 2；<0.3 ×24h 或 无尿×12h → 3\nv = max(stage)","interpret":[{"when":"rrt == 1","level":"crit","text":"3 期：已开始 RRT，按 ICU 管理"},{"when":"scr_ratio >= 3","level":"crit","text":"3 期：肌酐 ≥ 3 倍基线，评估 RRT 指征（高钾、酸中毒、容量超负荷、尿毒症症状）"},{"when":"scr_ratio >= 2","level":"high","text":"2 期：停用肾毒性药物、优化容量与灌注，每日监测肌酐"},{"when":"scr_ratio >= 1.5 || scr_rise >= 0.3","level":"warn","text":"1 期：寻找病因（容量的不足、药物、梗阻），停用 NSAIDs/造影剂"},{"when":"uo < 0.5 && uo_hours >= 12","level":"high","text":"少尿 ≥ 12 h：至少 2 期，评估容量状态与血流动力学"},{"when":"v >= 0","level":"ok","text":"未达 AKI 标准，高危者继续监测"}],"note":"基线肌酐取发病前 7 天内最低值或既往稳定值；中国成人 Scr ≥ 4.0 mg/dL（353.6 μmol/L）自动为 3 期；尿量需按体重计算。","refs":["KDIGO Clinical Practice Guideline for Acute Kidney Injury (2012)","急性肾损伤诊疗指南（2015）"]},{"id":"renal_fena","name":"钠排泄分数（FENa）","aka":["FENa","Fractional Excretion of Sodium"],"cat":"肾小管功能","rank":6,"desc":"鉴别肾前性与肾实质性 AKI 的尿钠排泄比例。","inputs":[{"key":"una","label":"尿钠","unit":"mmol/L","type":"number","min":0,"max":300,"step":1,"required":true},{"key":"sna","label":"血钠","unit":"mmol/L","type":"number","min":95,"max":180,"step":1,"required":true},{"key":"ucr","label":"尿肌酐","unit":"mg/dL","type":"number","min":1,"max":3000,"step":0.1,"required":true},{"key":"scr","label":"血肌酐","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true},{"key":"diuretic","label":"使用利尿剂","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"FENa(%) = (尿钠/血钠) ÷ (尿肌酐/血肌酐) ×100","compute":"formula_only","algorithm":"v = (una/sna)/(ucr/scr)*100","interpret":[{"when":"v < 1","level":"ok","text":"FENa < 1%：提示肾前性（低灌注），补液试验观察尿量"},{"when":"v >= 1 && v <= 2","level":"warn","text":"FENa 1–2%：结果不确定，结合容量状态与 FEUrea"},{"when":"v > 2","level":"high","text":"FENa > 2%：提示肾实质性损伤（ATN）；但 CKD、利尿剂、尿路梗阻时也可升高"}],"note":"使用利尿剂时参考 FEUrea；尿肌酐单位需与血肌酐一致；早期 ATN 或造影剂肾病 FENa 可 < 1%。","refs":["KDIGO AKI Guideline (2012)","中国急性肾损伤临床实践指南（2023）"]},{"id":"renal_feurea","name":"尿素排泄分数（FEUrea）","aka":["FEUrea","Fractional Excretion of Urea"],"cat":"肾小管功能","rank":9,"desc":"使用利尿剂时鉴别肾前性氮质血症与 ATN。","inputs":[{"key":"uurea","label":"尿尿素","unit":"mg/dL","type":"number","min":1,"max":5000,"step":1,"required":true},{"key":"bun_mg","label":"血尿素（BUN）","unit":"mg/dL","type":"number","min":1,"max":300,"step":1,"required":true},{"key":"ucr","label":"尿肌酐","unit":"mg/dL","type":"number","min":1,"max":3000,"step":0.1,"required":true},{"key":"scr","label":"血肌酐","unit":"mg/dL","type":"number","min":0.2,"max":20,"step":0.01,"required":true}],"formula":"FEUrea(%) = (尿尿素/血尿素) ÷ (尿肌酐/血肌酐) ×100","compute":"formula_only","algorithm":"v = (uurea/bun_mg)/(ucr/scr)*100","interpret":[{"when":"v < 35","level":"ok","text":"FEUrea < 35%：肾前性氮质血症（即使使用利尿剂）"},{"when":"v >= 35 && v < 50","level":"warn","text":"FEUrea 35–49%：不确定区间"},{"when":"v >= 50","level":"high","text":"FEUrea ≥ 50%：提示 ATN 等肾实质性损伤"}],"note":"血尿素单位 mg/dL，若为 mmol/L 需 ×2.8；尿素受高蛋白、消化道出血影响。","refs":["KDIGO AKI Guideline (2012)","中国急性肾损伤临床实践指南（2023）"]},{"id":"renal_uosm_posm","name":"尿渗透压/血渗透压比","aka":["Uosm/Posm"],"cat":"肾小管功能","rank":14,"desc":"评估尿浓缩能力，辅助鉴别肾前性、ATN 与 SIADH。","inputs":[{"key":"uosm","label":"尿渗透压","unit":"mOsm/kg","type":"number","min":20,"max":1500,"step":1,"required":true},{"key":"posm","label":"血浆渗透压","unit":"mOsm/kg","type":"number","min":200,"max":450,"step":1,"required":true}],"formula":"比值 = 尿渗透压 / 血浆渗透压","compute":"formula_only","algorithm":"v = uosm/posm","interpret":[{"when":"v >= 1.5","level":"ok","text":"尿浓缩功能保留（肾前性、SIADH 可 > 1.5）"},{"when":"v >= 1 && v < 1.5","level":"warn","text":"浓缩能力下降，结合临床"},{"when":"v < 1","level":"high","text":"比值 < 1：尿稀释，提示 ATN 或尿崩症"}],"note":"SIADH 尿渗透压常 > 100 mOsm/kg 且尿钠 > 30 mmol/L；尿崩症尿渗 < 血浆渗。","refs":["KDIGO AKI Guideline (2012)","中国低钠血症诊治专家共识（2017）"]},{"id":"renal_posm","name":"血浆渗透压计算","aka":["Serum Osmolality","有效渗透压"],"cat":"肾小管功能","rank":11,"desc":"由钠、血糖、尿素计算实测血浆渗透压与渗透压间隙。","inputs":[{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":95,"max":190,"step":1,"required":true},{"key":"glu","label":"血糖","unit":"mmol/L","type":"number","min":1,"max":100,"step":0.1,"required":true},{"key":"bun","label":"血尿素","unit":"mmol/L","type":"number","min":0,"max":100,"step":0.1,"required":true},{"key":"measured","label":"实测渗透压（可选）","unit":"mOsm/kg","type":"number","min":100,"max":500,"step":1,"required":false}],"formula":"计算渗透压 = 2×Na + 血糖 + 尿素；有效渗透压 = 2×Na + 血糖；渗透压间隙 = 实测 − 计算","compute":"formula_only","algorithm":"v = 2*na + glu + bun; effective = 2*na + glu; gap = measured? measured - v : null","interpret":[{"when":"v > 320","level":"crit","text":"高渗状态（> 320）：警惕 HHS、尿毒症或外源性渗透物质"},{"when":"v >= 285 && v <= 320","level":"ok","text":"渗透压在正常参考区间"},{"when":"v < 285","level":"warn","text":"低渗状态：评估低钠血症真实性（假性低钠、SIADH）"}],"note":"渗透压间隙 > 10 mOsm/kg 提示甲醇、乙二醇、异丙醇、甘露醇等；尿素可自由透膜，有效渗透压不计尿素。","refs":["中国低钠血症诊治专家共识（2017）","ADA Hyperglycemic Crises in Adults Consensus Report (2024)"]},{"id":"renal_anion_gap","name":"阴离子间隙（AG）","aka":["Anion Gap","AG"],"cat":"酸碱平衡","rank":7,"desc":"计算 AG 与白蛋白校正 AG，用于代谢性酸中毒分型。","inputs":[{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":180,"step":1,"required":true},{"key":"cl","label":"血氯","unit":"mmol/L","type":"number","min":60,"max":140,"step":1,"required":true},{"key":"hco3","label":"HCO3⁻","unit":"mmol/L","type":"number","min":1,"max":45,"step":1,"required":true},{"key":"alb","label":"白蛋白（可选）","unit":"g/L","type":"number","min":10,"max":60,"step":1,"required":false}],"formula":"AG = Na − (Cl + HCO3)；校正 AG = AG + 2.5×(40 − 白蛋白 g/L)/10","compute":"formula_only","algorithm":"v = na - cl - hco3; ag_corr = alb? v + 2.5*(40-alb)/10 : v","interpret":[{"when":"v <= 12","level":"ok","text":"AG 正常（8–12）：高氯性正常 AG 代谢性酸中毒（腹泻、RTA）或正常"},{"when":"v > 12 && v < 20","level":"warn","text":"AG 轻度升高：查乳酸、酮体、肌酐、药物（二甲双胍等）"},{"when":"v >= 20","level":"crit","text":"AG 显著升高：高 AG 代谢性酸中毒（DKA、乳酸酸中毒、尿毒症、中毒），计算 ΔAG/ΔHCO3"}],"note":"低白蛋白显著低估 AG，需用校正 AG；高钙、高镁、锂可影响 AG。","refs":["中国代谢性酸中毒诊疗指南（2019）","KDIGO CKD-MBD Guideline Update (2017)"]},{"id":"renal_kur_ktv","name":"透析充分性（Kt/V 与 URR）","aka":["spKt/V","URR","Dialysis Adequacy"],"cat":"透析治疗","rank":8,"desc":"由透析前后尿素氮与超滤量估算 spKt/V 与尿素下降率。","inputs":[{"key":"bun_pre","label":"透析前 BUN","unit":"mmol/L","type":"number","min":1,"max":80,"step":0.1,"required":true},{"key":"bun_post","label":"透析后 BUN","unit":"mmol/L","type":"number","min":0.5,"max":60,"step":0.1,"required":true},{"key":"pre_kg","label":"透析前体重","unit":"kg","type":"number","min":20,"max":200,"step":0.1,"required":true},{"key":"post_kg","label":"透析后体重","unit":"kg","type":"number","min":20,"max":200,"step":0.1,"required":true},{"key":"hours","label":"单次透析时长","unit":"h","type":"number","min":0.5,"max":10,"step":0.1,"required":true}],"formula":"URR = (BUN前 − BUN后)/BUN前 ×100%；spKt/V（Daugirdas 二代）= −ln(R−0.008t) + (4−3.5R)×UF/W，R = BUN后/BUN前","compute":"formula_only","algorithm":"R = bun_post/bun_pre\nv = -Math.log(R - 0.008*hours) + (4 - 3.5*R)*(pre_kg-post_kg)/post_kg\nURR = (1-R)*100","interpret":[{"when":"v >= 1.4","level":"ok","text":"spKt/V ≥ 1.4 达标（URR ≥ 65%）；低于 1.2 需调整处方"},{"when":"v >= 1.2 && v < 1.4","level":"warn","text":"spKt/V 1.2–1.4 边缘：评估血流量、透析器面积、时长与血管通路"},{"when":"v < 1.2","level":"high","text":"spKt/V < 1.2 不达标：增加时长/频率或改高通量透析器"}],"note":"透析后 BUN 应避开反跳（慢速 15–30 s 采血）；月平均 spKt/V 目标 ≥ 1.4；腹膜透析用 Kt/V 周总量 ≥ 1.7。","refs":["血液透析质量控制标准（国家卫健委 2010）","中国血液透析充分性临床实践指南（2015）","KDOQI Hemodialysis Adequacy Update (2015)"]},{"id":"renal_iga_oxford","name":"IgA 肾病牛津分型（MEST-C）","aka":["Oxford classification","MEST-C 评分"],"cat":"肾小球疾病","rank":16,"desc":"依据 MEST-C 五项病理指标判定预后风险。","inputs":[{"key":"m","label":"M：系膜细胞增生","unit":"","type":"select","options":[{"value":0,"label":"M0 ≤50% 肾小球"},{"value":1,"label":"M1 >50%"}],"required":true},{"key":"e","label":"E：内皮细胞增生","unit":"","type":"select","options":[{"value":0,"label":"E0 无"},{"value":1,"label":"E1 有"}],"required":true},{"key":"s","label":"S：节段性硬化","unit":"","type":"select","options":[{"value":0,"label":"S0 无"},{"value":1,"label":"S1 有"}],"required":true},{"key":"t","label":"T：肾小管萎缩/间质纤维化","unit":"","type":"select","options":[{"value":0,"label":"T0 ≤25%"},{"value":1,"label":"T1 26–50%"},{"value":2,"label":"T2 >50%"}],"required":true},{"key":"c","label":"C：新月体（细胞/纤维细胞性）","unit":"","type":"select","options":[{"value":0,"label":"C0 无"},{"value":1,"label":"C1 <25%"},{"value":2,"label":"C2 ≥25%"}],"required":true}],"formula":"MEST-C 组合评分，按 T 与 C 分档评估进展风险","compute":"sum","interpret":[{"when":"t == 2","level":"crit","text":"T2：> 50% 小管萎缩/间质纤维化，肾功能丢失风险高，提前免疫抑制与肾脏保护"},{"when":"t == 1","level":"high","text":"T1：中等小管间质病变，预后不良因素，随访频次加密"},{"when":"c == 2","level":"high","text":"C2：≥ 25% 新月体，可考虑免疫抑制治疗（需结合 eGFR 与尿蛋白）"},{"when":"e == 1 || s == 1","level":"warn","text":"E1/S1 提示活动性病变，控制蛋白尿（ACEI/ARB、SGLT2i），必要时免疫抑制"}],"levels":[{"label":"M0 / M1","criteria":"系膜细胞增生：> 50% 肾小球增生为 M1","level":"ok"},{"label":"E0 / E1","criteria":"毛细血管内皮细胞增生：有为 E1","level":"warn"},{"label":"S0 / S1","criteria":"节段性肾小球硬化：有为 S1（排除粘连和球囊壁增厚）","level":"warn"},{"label":"T0 / T1 / T2","criteria":"小管萎缩/间质纤维化 ≤25% / 26–50% / >50%","level":"high"},{"label":"C0 / C1 / C2","criteria":"细胞或纤维细胞性新月体：无 / <25% / ≥25%","level":"high"}],"note":"2016 版加入 C（新月体），2021 年修订了 T 的定义（仅小管萎缩或间质纤维化 > 25%）；M1/E1 对治疗反应影响有争议。","refs":["IgA 肾病诊断与治疗中国专家共识（2021）","KDIGO 2021 Glomerular Diseases Guideline","Oxford IgA Nephropathy Classification (2017)"]},{"id":"renal_uric_gout","name":"尿酸与痛风分级","aka":["高尿酸血症分级","Hyperuricemia grading"],"cat":"代谢与肾结石","rank":15,"desc":"按血尿酸水平判定高尿酸血症分层与痛风处理阈值。","inputs":[{"key":"ua","label":"血尿酸","unit":"μmol/L","type":"number","min":50,"max":1200,"step":1,"required":true},{"key":"sex","label":"性别","unit":"","type":"select","options":[{"value":1,"label":"男"},{"value":0,"label":"女"}],"required":true},{"key":"gout","label":"有痛风发作史","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true}],"formula":"高尿酸血症：男 ≥ 420 μmol/L、女 ≥ 360 μmol/L（非同日两次）","compute":"formula_only","algorithm":"v = ua","interpret":[{"when":"gout == 1 && ua < 360","level":"ok","text":"痛风患者血尿酸 < 360 μmol/L：达标（有痛风石者目标 < 300）"},{"when":"gout == 1","level":"high","text":"痛风患者未达标：降尿酸治疗（别嘌醇需查 HLA-B*5801），避免高嘌呤饮食与酒精"},{"when":"ua >= 540","level":"high","text":"血尿酸 ≥ 540 μmol/L：即使无症状也建议降尿酸治疗"},{"when":"(sex == 1 && ua >= 420) || (sex == 0 && ua >= 360)","level":"warn","text":"高尿酸血症：评估合并症（CKD、高血压、代谢综合征），生活方式干预"},{"when":"v < 360","level":"ok","text":"血尿酸在正常范围"}],"note":"急性发作期不宜立即调整降尿酸药；CKD 患者别嘌醇减量；痛风合并 CKD 首选非布司他需注意心血管风险。","refs":["中国高尿酸血症与痛风诊疗指南（2019）","中国高尿酸血症相关疾病诊疗多学科专家共识（2023）"]},{"id":"renal_volume_repletion","name":"血容量与补液量估算","aka":["补液量估算","脱水评估"],"cat":"代谢与肾结石","rank":17,"desc":"由体重下降与血清钠估算失水量与补液速度（参考值）。","inputs":[{"key":"weight_kg","label":"当前体重","unit":"kg","type":"number","min":20,"max":250,"step":0.1,"required":true},{"key":"lost_pct","label":"体重丢失百分比","unit":"%","type":"number","min":0,"max":20,"step":0.5,"required":true},{"key":"na","label":"血钠","unit":"mmol/L","type":"number","min":100,"max":180,"step":1,"required":true}],"formula":"失水量(L) ≈ 体重×丢失百分比；Na>145 时按 TBW 修正：水缺乏 = TBW×(Na/140 −1)×1000，TBW = 体×0.6(男)/0.5(女)","compute":"formula_only","algorithm":"lost = weight_kg*lost_pct/100; v = lost (L)","interpret":[{"when":"lost_pct >= 10","level":"crit","text":"体重丢失 ≥ 10%：重度脱水/低血容量，先等渗晶体快速扩容（如 500 mL/h，按心肾功能）后减慢"},{"when":"lost_pct >= 5","level":"warn","text":"体重丢失 5–10%：中度脱水，口服或静脉补液，评估尿量"},{"when":"lost_pct > 0","level":"ok","text":"轻度脱水：口服补液为主，纠正病因"}],"note":"高钠者补液速度应控制（每 24 h 血钠下降 ≤ 10 mmol/L）；心衰、肾病综合征患者需更谨慎；本页仅参考补液总量。","refs":["中国低钠血症诊治专家共识（2017）","WS/T 578.2 中国居民膳食指南（水部分）"]}]},"resp":{"items":[{"id":"abg_auto","name":"血气分析全自动解读","aka":["Arterial Blood Gas","ABG","血气分析、酸碱失衡判断"],"cat":"血气分析","rank":1,"desc":"输入 pH、PaCO2、HCO3- 等血气指标，自动判断原发酸碱失衡、代偿是否充分（Winter 等公式）、AG 与校正 AG、氧合指数、A-a 梯度。","inputs":[{"key":"ph","label":"pH","unit":"","type":"number","min":6.5,"max":7.9,"step":0.01,"required":true,"hint":"动脉血，37 ℃"},{"key":"pco2","label":"PaCO2","unit":"mmHg","type":"number","min":5,"max":150,"step":1,"required":true},{"key":"hco3","label":"HCO3-","unit":"mmol/L","type":"number","min":2,"max":60,"step":0.1,"required":true},{"key":"na","label":"Na+","unit":"mmol/L","type":"number","min":100,"max":180,"step":0.1,"required":true},{"key":"cl","label":"Cl-","unit":"mmol/L","type":"number","min":60,"max":140,"step":0.1,"required":true},{"key":"lac","label":"乳酸 Lac","unit":"mmol/L","type":"number","min":0.1,"max":30,"step":0.1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/L","type":"number","min":5,"max":60,"step":1,"required":true,"hint":"用于白蛋白校正 AG"},{"key":"fio2","label":"FiO2（吸氧浓度）","unit":"","type":"number","min":0.21,"max":1,"step":0.01,"required":true,"hint":"小数，如 0.4；鼻导管 3 L/min 约 0.33"},{"key":"pao2","label":"PaO2","unit":"mmHg","type":"number","min":20,"max":600,"step":1,"required":true},{"key":"be","label":"BE（碱剩余）","unit":"mmol/L","type":"number","min":-40,"max":40,"step":0.5,"required":false,"hint":"可留空"},{"key":"k","label":"K+","unit":"mmol/L","type":"number","min":1.5,"max":9,"step":0.1,"required":false}],"formula":"AG = Na − (Cl + HCO3)；校正 AG = AG + 2.5×(40 − 白蛋白 g/L)；ΔAG = 校正AG − 12；ΔHCO3 = 24 − HCO3；delta-delta = ΔAG / ΔHCO3；P/F = PaO2 / FiO2；PAO2 = FiO2×(760−47) − PaCO2/0.8；A-a = PAO2 − PaO2","compute":"abg_readout","algorithm":"# 伪代码：返回 {ph, pco2, hco3, ag, ag_corr, delta_ag, delta_hco3, delta_delta, pf, aa, primary[], mixed[], compensation[]}\n1. 先测值方向：\n   acido = (ph < 7.35) or (ph <= 7.40 and pco2 > 45)\n   alkal = (ph > 7.45) or (ph >= 7.40 and pco2 < 35)\n   两者皆假时判『呼吸性/代谢性失衡但 pH 代偿至正常范围』：按 pco2 与 hco3 偏离 40/24 的方向判断（pco2 偏离为主→呼吸性，hco3 偏离为主→代谢性）。\n2. 原发失衡：\n   if acido and pco2 > 45: 主 = 呼酸\n   if acido and hco3 < 22: 主 = 代酸\n   if alkal and pco2 < 35: 主 = 呼碱\n   if alkal and hco3 > 26: 主 = 代碱\n   （若 pH 异常但两项均不满足，则判混合型失衡并提示复核血样/时相）\n3. 代偿判断（±2 视为与代偿范围相符）：\n   代酸: 预期 PaCO2 = 1.5×hco3 + 8；偏差 = pco2 − 预期\n         偏差 > 2 → 合并呼酸；偏差 < −2 → 合并呼碱\n   代碱: 预期 PaCO2 = 0.7×(hco3 − 24) + 40；偏差 > 2 → 合并呼酸；< −2 → 合并呼碱\n   呼酸（急）: 预期 HCO3 = 24 + 0.1×(pco2 − 40)；呼酸（慢）: 预期 HCO3 = 24 + 0.35×(pco2 − 40)\n       hco3 高于两者 → 合并代碱；低于急性预期 → 合并代酸\n   呼碱（急）: 预期 HCO3 = 24 − 0.2×(40 − pco2)；呼碱（慢）: 预期 HCO3 = 24 − 0.5×(40 − pco2)\n       hco3 低于两者 → 合并代酸；高于慢性预期 → 合并代碱\n4. AG = na − cl − hco3；ag_corr = AG + 2.5×(40 − alb)\n5. delta_ag = ag_corr − 12；delta_hco3 = 24 − hco3；delta_delta = delta_ag / max(delta_hco3, 0.1)\n   若为代酸且 delta_delta < 1 → 合并高氯性（正常 AG）代酸；> 2 → 合并代碱\n6. pf = pao2 / fio2；aa = fio2×(760−47) − pco2/0.8 − pao2\n7. 乳酸：lac > 2 提示组织低灌注/无氧代谢，可与代酸合并判读","interpret":[{"when":"ph < 7.20","level":"crit","text":"重度酸血症（pH < 7.20）：立即评估气道与通气支持；pH < 7.10 时考虑碳酸氢钠（仅在严重代谢性酸中毒且有适应证时，遵指南与说明书）"},{"when":"ph >= 7.20 && ph < 7.35","level":"warn","text":"酸血症（pH 7.20–7.35）：结合原发失衡类型处理病因，代谢性酸中毒优先纠正休克/低灌注"},{"when":"ph > 7.45","level":"warn","text":"碱血症（pH > 7.45）：注意低钾、低氯、利尿剂/激素或过度通气；pH > 7.55 时警惕心律失常与氧解离曲线左移"},{"when":"lac > 4","level":"crit","text":"乳酸 > 4 mmol/L：提示严重组织低灌注或脓毒症，按脓毒症集束化流程复查乳酸清除率"},{"when":"pf < 100","level":"crit","text":"P/F < 100：重度氧合障碍，符合重度 ARDS 范围，评估气管插管与肺保护性通气（Vt 6 mL/kg 理想体重、PEEP 滴定）"},{"when":"pf < 200","level":"high","text":"P/F 100–200：中度氧合障碍，考虑 ARDS 或重症肺炎，高流量氧疗/无创通气评估"},{"when":"pf < 300","level":"warn","text":"P/F 200–300：轻度氧合障碍，监控呼吸功，明确病因（肺炎、肺水肿、肺栓塞）"},{"when":"v >= 0","level":"ok","text":"pH 7.35–7.45：结合 PaCO2/HCO3 与代偿公式判断是否存在混合型失衡"}],"note":"解读顺序：pH 定酸/碱 → PaCO2 与 HCO3 定原发 → 代偿公式查混合 → AG/校正 AG/δ-δ 查代谢性成分。抽血前观察者效应、静脉血混合、乳酸/白蛋白未复查都会影响判读，建议同时看 BE 与电解质。","refs":["《内科学》（第 9 版）呼吸系统疾病·酸碱平衡失调章，人民卫生出版社","2023 慢性阻塞性肺疾病急性加重诊治中国专家共识（SAFE 模式血气管理与无创通气部分）","2021 中国 ARDS 诊断与治疗指南（氧合指数分级部分）","Kellum JA, et al. Clinical review: reunification of acid–base physiology. Crit Care 2005（AG、delta-delta 方法学）","2016 ATS/ACCP 血气分析临床解读基础（A-a 梯度、代偿公式图示）"]},{"id":"anion_gap","name":"阴离子间隙 AG（含白蛋白校正 AG）","aka":["Anion Gap","AG","校正 AG"],"cat":"血气分析","rank":2,"desc":"计算阴离子间隙判断高 AG 型代谢性酸中毒，并按白蛋白水平做校正（低白蛋白会掩盖高 AG）。","inputs":[{"key":"na","label":"Na+","unit":"mmol/L","type":"number","min":100,"max":180,"step":0.1,"required":true},{"key":"cl","label":"Cl-","unit":"mmol/L","type":"number","min":60,"max":140,"step":0.1,"required":true},{"key":"hco3","label":"HCO3-","unit":"mmol/L","type":"number","min":2,"max":60,"step":0.1,"required":true},{"key":"alb","label":"白蛋白","unit":"g/L","type":"number","min":5,"max":60,"step":1,"required":false,"hint":"留空则不做校正"}],"formula":"AG = Na − (Cl + HCO3)；校正 AG = AG + 2.5×(40 − 白蛋白 g/L)","compute":"anion_gap","algorithm":"AG = na - cl - hco3\nif alb 存在: ag_corr = AG + 2.5 * (40 - alb) else ag_corr = AG\nv = ag_corr （解读以此为准；同时返回 AG）","interpret":[{"when":"v > 20","level":"crit","text":"校正 AG > 20：明确高 AG 代谢性酸中毒，常见于乳酸酸中毒、酮症酸中毒、尿毒症、中毒（甲醇/乙二醇/水杨酸）"},{"when":"v > 12 && v <= 20","level":"warn","text":"校正 AG 12–20：高 AG 代谢性酸中毒可能，结合乳酸、酮体、肌酐、渗透压间隙与用药史确认"},{"when":"v < 4","level":"low","text":"AG < 4：低 AG，见于严重低白蛋白血症、锂/溴中毒或实验室误差，注意低蛋白造成的假性低 AG"},{"when":"v >= 4 && v <= 12","level":"ok","text":"AG 4–12：正常范围；如有代酸，则提示高氯性（正常 AG）代酸，如腹泻、肾小管酸中毒、大量生理盐水输入"}],"note":"白蛋白每降低 10 g/L，AG 约低估 2.5 mmol/L。低蛋白血症、IgG 异常（多发性骨髓瘤）及高磷/高脂血症均可使 AG 判读失真。","refs":["《内科学》（第 9 版）代谢性酸中毒章节","Kellum JA, et al. Determinants of blood pH in health and disease. Crit Care 2000","2021 中国脓毒症/脓毒性休克急诊治疗指南（乳酸与代酸评估部分）"]},{"id":"pf_ratio","name":"氧合指数 P/F 与 A-a 梯度","aka":["PaO2/FiO2","P/F Ratio","A-a Gradient","肺泡动脉氧分压差"],"cat":"血气分析","rank":3,"desc":"由 PaO2、FiO2、PaCO2 计算氧合指数与肺泡-动脉氧分压差，判断氧合障碍程度及分流/弥散因素。","inputs":[{"key":"pao2","label":"PaO2","unit":"mmHg","type":"number","min":20,"max":600,"step":1,"required":true},{"key":"fio2","label":"FiO2","unit":"","type":"number","min":0.21,"max":1,"step":0.01,"required":true},{"key":"pco2","label":"PaCO2","unit":"mmHg","type":"number","min":5,"max":150,"step":1,"required":true},{"key":"age","label":"年龄","unit":"岁","type":"number","min":0,"max":110,"step":1,"required":false,"hint":"用于 A-a 梯度预计值（= age/4 + 4）"}],"formula":"P/F = PaO2 / FiO2；PAO2 = FiO2×(760 − 47) − PaCO2/0.8；A-a = PAO2 − PaO2；预计 A-a ≈ 年龄/4 + 4","compute":"pf_ratio","algorithm":"pao2_alv = fio2*(760-47) - pco2/0.8\npf = pao2 / fio2\naa = pao2_alv - pao2\nif age 存在: aa_pred = age/4 + 4  # 预计值，仅作参考\nv = pf  # 主结果用作 interpret；同时输出 pao2_alv、aa、aa_pred","interpret":[{"when":"v < 100","level":"crit","text":"P/F < 100：重度氧合障碍（重度 ARDS 范围），氧合与呼吸功再评估，考虑有创通气、俯卧位、ECMO 指征评估"},{"when":"v < 200","level":"high","text":"P/F 100–200：中度，常见于 ARDS/重症肺炎，高流量或无创通气，注意 PEEP 与肺保护"},{"when":"v < 300","level":"warn","text":"P/F 200–300：轻度氧合障碍，明确病因（肺炎/肺水肿/肺栓塞/间质性肺病），密切监测"},{"when":"v <= 400","level":"ok","text":"P/F 300–400：氧合基本可接受，注意 A-a 梯度是否显著增大"},{"when":"v > 400","level":"ok","text":"P/F > 400：氧合良好"}],"note":"P/F 受 FiO2 与 PEEP 影响，应在稳定状态下测量；ARDS 分级要求 PEEP ≥ 5 cmH2O。A-a 梯度增大提示通气/血流比例失调、分流或弥散障碍，而低通气时 A-a 梯度通常正常。","refs":["2021 中国急性呼吸窘迫综合征诊断和治疗指南","ARDS Definition Task Force. ARDS: the Berlin Definition. JAMA 2012","《内科学》（第 9 版）呼吸衰竭章节"]},{"id":"curb65","name":"CURB-65 肺炎严重度评分","aka":["CURB-65","社区获得性肺炎严重度"],"cat":"肺炎与感染","rank":4,"desc":"社区获得性肺炎（CAP）5 项指标评分，指导门诊/住院/ICU 分层。","inputs":[{"key":"confusion","label":"意识障碍（新发）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"urea","label":"尿素氮 BUN > 7 mmol/L（≈ 19 mg/dL，≥ 20 mg/dL 计分）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"rr","label":"呼吸频率 ≥ 30 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"bp","label":"血压（SBP < 90 或 DBP ≤ 60 mmHg）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age65","label":"年龄 ≥ 65 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"CURB-65 = 意识障碍 + BUN + RR≥30 + 低血压 + 年龄≥65（各 1 分，0–5 分）","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"3–5 分：高危，需住院（≥4 分评估 ICU），同时评估脓毒症，开始经验性抗感染"},{"when":"v == 2","level":"warn","text":"2 分：中危，建议住院或短期观察，评估并发症与基础病"},{"when":"v <= 1","level":"ok","text":"0–1 分：低危，可门诊治疗（0 分死亡率 < 1%，1 分约 3%），注意合并症与低氧血症"}],"note":"CURB-65 不包含氧合与合并症，需结合 PaO2/FiO2、胸片范围与基础病判断；中国 CAP 指南推荐对中高危患者同时使用 PSI 辅助。","refs":["2016 中国成人社区获得性肺炎诊断和治疗指南（中华医学会呼吸病学分会）","Lim WS, et al. Defining community acquired pneumonia severity on presentation to hospital. Thorax 2003"]},{"id":"crb65","name":"CRB-65 评分（床旁简化版）","aka":["CRB-65"],"cat":"肺炎与感染","rank":5,"desc":"去尿素氮的 4 项床旁评分，适用于基层/急诊无生化条件时快速分层。","inputs":[{"key":"confusion","label":"意识障碍（新发）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"rr","label":"呼吸频率 ≥ 30 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"bp","label":"血压（SBP < 90 或 DBP ≤ 60 mmHg）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age65","label":"年龄 ≥ 65 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"CRB-65 = 意识障碍 + RR≥30 + 低血压 + 年龄≥65（各 1 分，0–4 分）","compute":"sum","interpret":[{"when":"v >= 2","level":"crit","text":"2–4 分：需住院并评估死亡风险，≥3 分按重症处理考虑 ICU"},{"when":"v == 1","level":"warn","text":"1 分：门诊治疗需谨慎，建议 24–48 h 复诊或住院观察"},{"when":"v == 0","level":"ok","text":"0 分：低危，门诊治疗，交代复诊警示症状"}],"note":"无血生化时替代 CURB-65，但灵敏度略低；老年、免疫抑制与低氧者即使 0 分也应复查。","refs":["2016 中国成人社区获得性肺炎诊断和治疗指南（中华医学会呼吸病学分会）","BTS Pneumonia Guidelines: CRB-65, Thorax 2009"]},{"id":"psi_port","name":"PSI / PORT 肺炎严重指数","aka":["Pneumonia Severity Index","PSI","PORT score"],"cat":"肺炎与感染","rank":6,"desc":"CAP 30 天死亡风险分层，分为 5 级，指导住院与重症监护决策。","inputs":[{"key":"age","label":"年龄（男性 = 年龄；女性 = 年龄 − 10）","unit":"岁","type":"number","min":18,"max":110,"step":1,"required":true},{"key":"nursing","label":"居住在养老/医疗机构","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":10,"label":"是"}]},{"key":"neoplasm","label":"肿瘤病史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":30,"label":"有"}]},{"key":"liver","label":"肝病","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":20,"label":"有"}]},{"key":"chf","label":"充血性心力衰竭","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":10,"label":"有"}]},{"key":"cva","label":"脑血管疾病","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":10,"label":"有"}]},{"key":"renal","label":"肾脏疾病","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":10,"label":"有"}]},{"key":"mental","label":"意识改变","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":20,"label":"有"}]},{"key":"rr","label":"呼吸频率 ≥ 30 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":20,"label":"是"}]},{"key":"sbp","label":"收缩压 < 90 mmHg","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":20,"label":"是"}]},{"key":"temp","label":"体温 < 35 ℃ 或 ≥ 40 ℃","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":15,"label":"是"}]},{"key":"hr","label":"心率 ≥ 125 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":10,"label":"是"}]},{"key":"ph","label":"pH < 7.35","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":30,"label":"是"}]},{"key":"bun","label":"BUN > 11 mmol/L（≥ 30 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":20,"label":"是"}]},{"key":"na","label":"Na+ < 130 mmol/L","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":20,"label":"是"}]},{"key":"glu","label":"血糖 > 13.9 mmol/L（> 250 mg/dL）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":10,"label":"是"}]},{"key":"hr_ct","label":"红细胞压积 < 30%","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":10,"label":"是"}]},{"key":"pao2","label":"PaO2 < 60 mmHg 或 SpO2 < 90%","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":10,"label":"是"}]},{"key":"pleural","label":"胸腔积液（胸片）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":10,"label":"有"}]}],"formula":"PSI 总分 = 年龄(女−10) + 居住机构 10 + 肿瘤 30 + 肝病 20 + 心衰 10 + 脑血管病 10 + 肾病 10 + 意识改变 20 + RR≥30 20 + SBP<90 20 + 体温异常 15 + HR≥125 10 + pH<7.35 30 + BUN 20 + Na<130 20 + 血糖 10 + Hct<30 10 + 低氧 10 + 胸腔积液 10","compute":"sum","interpret":[{"when":"v > 130","level":"crit","text":"Ⅴ级（> 130 分）：30 天死亡率约 27%，需住院并考虑 ICU"},{"when":"v > 90","level":"high","text":"Ⅳ级（91–130 分）：死亡率约 8–9%，建议住院"},{"when":"v > 70","level":"warn","text":"Ⅲ级（71–90 分）：死亡率约 0.9–2.8%，短期住院观察或密切门诊随访"},{"when":"v > 50","level":"ok","text":"Ⅱ级（≤ 70 分）：低死亡风险，可门诊治疗"},{"when":"v >= 0","level":"ok","text":"Ⅰ级（≤ 50 分，无危险因素且 < 50 岁）：门诊治疗"}],"note":"PSI 需先判年龄分层与危险因素；数据缺失项按 0 分处理会低估风险。老年与合并症患者分值易偏高，需结合临床（如低氧、不能进食、社会支持）决定住院。","refs":["2016 中国成人社区获得性肺炎诊断和治疗指南（中华医学会呼吸病学分会）","Fine MJ, et al. A prediction rule to identify low-risk patients with community-acquired pneumonia. NEJM 1997","2007 IDSA/ATS CAP Guidelines（PSI 分层推荐）"]},{"id":"qsofa","name":"qSOFA 快速序贯器官衰竭评分","aka":["quick SOFA","qSOFA"],"cat":"重症评分","rank":7,"desc":"床旁 3 项指标快速识别可疑感染中高死亡风险患者。","inputs":[{"key":"rr","label":"呼吸频率 ≥ 22 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"sbp","label":"收缩压 ≤ 100 mmHg","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"gcs","label":"GCS < 15（意识改变）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"qSOFA = RR≥22 + SBP≤100 + GCS<15（各 1 分）","compute":"sum","interpret":[{"when":"v >= 2","level":"crit","text":"≥ 2 分：器官功能障碍风险显著升高，启动脓毒症评估（乳酸、血培养、器官功能、尽早抗感染与液体复苏）"},{"when":"v == 1","level":"warn","text":"1 分：密切监测，1 h 内复评，必要时升级为 SOFA"},{"when":"v == 0","level":"ok","text":"0 分：暂不提示高死亡风险，但不能排除感染，需按临床判断继续评估"}],"note":"qSOFA 不用于单独诊断脓毒症，是提示性筛查工具；不适用于孕产妇与儿童。","refs":["Sepsis-3: Singer M, et al. The Third International Consensus Definitions for Sepsis and Septic Shock. JAMA 2016","2021 中国脓毒症/脓毒性休克急诊治疗指南（中国医师协会急诊医师分会）"]},{"id":"sofa","name":"SOFA 序贯器官衰竭评分","aka":["Sequential Organ Failure Assessment"],"cat":"重症评分","rank":8,"desc":"6 系统器官功能评分，诊断脓毒症并动态评估病情。","inputs":[{"key":"pf","label":"氧合 P/F (mmHg)","unit":"mmHg","type":"number","min":20,"max":700,"step":1,"required":true,"hint":"呼吸支持者需按插管状态计分"},{"key":"plt","label":"血小板","unit":"×10^9/L","type":"number","min":1,"max":800,"step":1,"required":true},{"key":"bili","label":"总胆红素","unit":"μmol/L","type":"number","min":0,"max":800,"step":1,"required":true},{"key":"map_mm","label":"MAP 或血管活性药","type":"select","required":true,"options":[{"value":0,"label":"MAP ≥ 70 mmHg"},{"value":1,"label":"MAP < 70 mmHg"},{"value":2,"label":"多巴胺 ≤ 5 或任意剂量多巴酚丁胺"},{"value":3,"label":"多巴胺 > 5 或去甲肾上腺素 ≤ 0.1 μg/kg/min"},{"value":4,"label":"多巴胺 > 15 或去甲肾上腺素 > 0.1 μg/kg/min"}]},{"key":"gcs_s","label":"GCS 评分","unit":"分","type":"number","min":3,"max":15,"step":1,"required":true},{"key":"crea","label":"肌酐 或 尿量","type":"select","required":true,"options":[{"value":0,"label":"Cr < 110 μmol/L"},{"value":1,"label":"Cr 110–170 μmol/L"},{"value":2,"label":"Cr 171–299 μmol/L"},{"value":3,"label":"Cr 300–440 或尿量 < 500 mL/d"},{"value":4,"label":"Cr > 440 或尿量 < 200 mL/d"}]}],"formula":"SOFA = 呼吸 + 凝血 + 肝 + 循环 + 神经 + 肾（每项 0–4 分，总分 0–24）；呼吸项：P/F ≥400=0、<400=1、<300=2、<200 且呼吸支持=3、<100 且呼吸支持=4；血小板 ≥150=0、<150=1、<100=2、<50=3、<20=4；胆红素 <20=0、20–32=1、33–101=2、102–204=3、>204=4；GCS 15=0、13–14=1、10–12=2、6–9=3、<6=4","compute":"sofa","algorithm":"resp = 0 if pf >= 400; 1 if pf < 400; 2 if pf < 300; 3 if pf < 200 && 已机械通气; 4 if pf < 100 && 已机械通气\ncoag = 0 if plt >= 150; 1 if plt < 150; 2 if plt < 100; 3 if plt < 50; 4 if plt < 20\nliver = 0 if bili < 20; 1 if bili <= 32; 2 if bili <= 101; 3 if bili <= 204; else 4\ncircul = map_mm  # 直接取 select 分值 0–4\ncns = 0 if gcs == 15; 1 if gcs >= 13; 2 if gcs >= 10; 3 if gcs >= 6; else 4\nrenal = crea  # 直接取 select 分值 0–4\nv = resp + coag + liver + circul + cns + renal","interpret":[{"when":"v >= 12","level":"crit","text":"SOFA ≥ 12：多器官衰竭，死亡率高，转入 ICU，全面器官支持与病因治疗"},{"when":"v >= 6","level":"high","text":"SOFA 6–11：器官功能明显受损，密切监测并评估 ICU 转运"},{"when":"v >= 2","level":"warn","text":"SOFA ≥ 2（较基线升高 ≥ 2 分）符合脓毒症器官功能障碍定义（Sepsis-3），启动脓毒症集束化治疗"},{"when":"v >= 0","level":"ok","text":"SOFA < 2：当前器官功能相对稳定，6–24 h 复评动态变化"}],"note":"诊断脓毒症需「可疑感染 + SOFA 急性增加 ≥ 2 分」。血管活性药剂量条目需按实际泵速换算；尿量项需 24 h 总量判读。","refs":["Sepsis-3: Singer M, et al. JAMA 2016","2021 中国脓毒症/脓毒性休克急诊治疗指南","Vincent JL, et al. The SOFA score. Intensive Care Med 1996"]},{"id":"apache2","name":"APACHE II 简化评分","aka":["Acute Physiology and Chronic Health Evaluation II"],"cat":"重症评分","rank":9,"desc":"入 ICU 24 h 内生理指标 + 年龄 + 慢性健康评分，估计院内死亡率（简化输入版）。","inputs":[{"key":"age_pts","label":"年龄分值（<45:0, 45–54:2, 55–64:3, 65–74:5, ≥75:6）","type":"select","required":true,"options":[{"value":0,"label":"≤44 岁"},{"value":2,"label":"45–54 岁"},{"value":3,"label":"55–64 岁"},{"value":5,"label":"65–74 岁"},{"value":6,"label":"≥75 岁"}]},{"key":"chronic","label":"慢性健康（严重器官不全/免疫抑制）","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":2,"label":"择期术后"},{"value":5,"label":"非手术或急诊术后"}]},{"key":"acute","label":"急性生理总分 APS（12 项生理指标分值之和，0–60）","unit":"分","type":"number","min":0,"max":60,"step":1,"required":true,"hint":"按 APACHE II 表逐项计分后求和"},{"key":"gcs_adj","label":"GCS 扣分（15 − GCS）","unit":"分","type":"number","min":0,"max":12,"step":1,"required":false}],"formula":"APACHE II = APS + 年龄分 + 慢性健康分 + （15 − GCS）","compute":"apache2","algorithm":"v = acute + age_pts + chronic + (gcs_adj 或 15 - gcs_s)\n# acute 为 12 项 APS 之和（Temperature、MAP、HR、RR、Oxygenation、Arterial pH、Na、K、Creatinine、Hct、WBC、GCS 扣分已含于 acute 时不要再加 gcs_adj）\nif gcs_adj 未提供: gcs_adj = 0  # 并在界面提示 APS 必须含 GCS 项","interpret":[{"when":"v >= 35","level":"crit","text":"≥ 35 分：预计院内死亡率 > 70%，病情极重，动态复评并讨论治疗目标"},{"when":"v >= 25","level":"high","text":"25–34 分：预计死亡率约 50–70%，加强器官支持"},{"when":"v >= 15","level":"warn","text":"15–24 分：预计死亡率约 15–40%，需密切监护"},{"when":"v >= 0","level":"ok","text":"< 15 分：相对低危，仍应逐个生理指标纠偏"}],"note":"取入 ICU 后 24 h 内最差值计分；GCS 在镇静/插管状态下的判读需注明。分值用于病情严重度分层，不可单独决定治疗强度。","refs":["Knaus WA, et al. APACHE II: a severity of disease classification system. Crit Care Med 1985","中国重症医学质量控制指标与评分系统应用专家共识（2020）"]},{"id":"wells_pe","name":"Wells 评分（肺栓塞）","aka":["Wells Score for PE"],"cat":"肺栓塞","rank":10,"desc":"肺栓塞临床可能性分层，指导 D-二聚体与 CT 肺动脉造影顺序。","inputs":[{"key":"dvt_sign","label":"DVT 临床体征","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":3,"label":"有"}]},{"key":"pe_likely","label":"PE 作为最可能的诊断","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":3,"label":"是"}]},{"key":"hr","label":"心率 > 100 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1.5,"label":"是"}]},{"key":"immob","label":"制动或近 4 周手术","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1.5,"label":"是"}]},{"key":"prev","label":"既往 DVT/PE 史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1.5,"label":"有"}]},{"key":"hemo","label":"咯血","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"cancer","label":"恶性肿瘤（6 月内治疗或姑息）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"Wells = DVT 体征 3 + PE 最可能 3 + HR>100 1.5 + 制动/手术 1.5 + 既往 VTE 1.5 + 咯血 1 + 肿瘤 1（0–12.5）","compute":"sum","interpret":[{"when":"v > 6","level":"crit","text":"> 6 分：高度可能（概率约 40–60%），直接行 CTPA 或 V/Q；血流动力学不稳定时床旁超声 + 溶栓评估"},{"when":"v > 4","level":"warn","text":"4.5–6 分：中度可能，D-二聚体或直接影像学检查（按本地流程）"},{"when":"v > 2","level":"warn","text":"2–4 分：中度可能，先查 D-二聚体（按年龄校正），阴性且临床低疑时可排除"},{"when":"v >= 0","level":"ok","text":"≤ 2 分：低度可能，D-二聚体阴性可基本排除 PE；D-二聚体阳性需影像学"}],"note":"简化版（每项 1 分，> 4 分为可能）与三分法（<2/2–6/>6）解读不同，需注明所用版本；妊娠期首选 CTPA 需权衡，D-二聚体按年龄校正（>50 岁用年龄×10 μg/L）。","refs":["2018 中国肺血栓栓塞症诊治与预防指南（中华医学会呼吸病学分会肺栓塞与肺血管病学组）","2019 ESC 急性肺栓塞诊断与管理指南","Wells PS, et al. Derivation of a simple clinical model. Thromb Haemost 2000"]},{"id":"geneva_rev","name":"修订版 Geneva 评分（肺栓塞）","aka":["Revised Geneva Score"],"cat":"肺栓塞","rank":11,"desc":"不依赖临床主观判断的 PE 可能性评分，与 Wells 类似用于分层。","inputs":[{"key":"age65","label":"年龄 > 65 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"prev","label":"既往 DVT/PE","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":3,"label":"有"}]},{"key":"surg","label":"1 月内手术或下肢骨折","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":2,"label":"是"}]},{"key":"cancer","label":"活动性恶性肿瘤","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":2,"label":"是"}]},{"key":"unilat","label":"单侧下肢疼痛","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":3,"label":"有"}]},{"key":"hemoptysis","label":"咯血","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":2,"label":"有"}]},{"key":"hr","label":"心率 75–94 次/分 / ≥ 95 次/分","type":"select","required":true,"options":[{"value":0,"label":"< 75 次/分"},{"value":3,"label":"75–94 次/分"},{"value":5,"label":"≥ 95 次/分"}]},{"key":"palp","label":"下肢深静脉触痛及单侧水肿","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":4,"label":"有"}]}],"formula":"修订 Geneva = 年龄>65 1 + 既往 VTE 3 + 手术/骨折 2 + 肿瘤 2 + 单侧下肢痛 3 + 咯血 2 + 心率 3/5 + 下肢深静脉体征 4（0–22）","compute":"sum","interpret":[{"when":"v >= 11","level":"crit","text":"≥ 11 分：高度可能（约 26%），直接行 CTPA"},{"when":"v >= 4","level":"warn","text":"4–10 分：中度可能（约 28%），D-二聚体或影像学"},{"when":"v < 4","level":"ok","text":"0–3 分：低度可能（约 8%），D-二聚体阴性可排除"}],"note":"三分类阈值 0–3 / 4–10 / ≥11；二分类阈值为 ≤ 5 分低可能。老龄与肾病患者 D-二聚体特异性下降，需结合年龄校正。","refs":["2018 中国肺血栓栓塞症诊治与预防指南","Le Gal G, et al. Prediction of pulmonary embolism in the emergency department: the revised Geneva score. Ann Intern Med 2006"]},{"id":"s_pesi","name":"简化 PESI（sPESI）","aka":["Simplified Pulmonary Embolism Severity Index"],"cat":"肺栓塞","rank":12,"desc":"肺栓塞患者 30 天死亡风险快速分层，指导门诊治疗与住院决策。","inputs":[{"key":"age80","label":"年龄 > 80 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"cancer","label":"恶性肿瘤","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"cardio","label":"慢性心肺疾病","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"hr","label":"心率 ≥ 110 次/分","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"sbp","label":"收缩压 < 100 mmHg","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"spo2","label":"SpO2 < 90%","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"sPESI = 年龄>80 + 肿瘤 + 慢性心肺病 + HR≥110 + SBP<100 + SpO2<90%（各 1 分）","compute":"sum","interpret":[{"when":"v >= 1","level":"high","text":"≥ 1 分：30 天死亡风险升高（约 8–10%），建议住院治疗与监测"},{"when":"v == 0","level":"ok","text":"0 分：低危（30 天死亡率约 1%），符合条件者可考虑门诊抗凝（须评估出血、依从性与随访条件）"}],"note":"门诊治疗标准（Hestia 标准）需同时满足无血流动力学不稳、无低氧、无严重合并症等；中国指南对门诊抗凝持谨慎态度，需个体化。","refs":["2018 中国肺血栓栓塞症诊治与预防指南","Jiménez D, et al. Simplification of the pulmonary embolism severity index. Arch Intern Med 2010","2019 ESC 急性肺栓塞诊断与管理指南"]},{"id":"bode","name":"BODE 指数","aka":["BODE Index"],"cat":"COPD 与哮喘","rank":13,"desc":"COPD 多维预后评分（BMI、气流受限、呼吸困难、6MWD），优于单纯 FEV1。","inputs":[{"key":"bmi_pts","label":"BMI 分值","type":"select","required":true,"options":[{"value":0,"label":"> 21"},{"value":1,"label":"≤ 21"}]},{"key":"fev1_pts","label":"FEV1 % 预计值","type":"select","required":true,"options":[{"value":0,"label":"≥ 65%"},{"value":1,"label":"50–64%"},{"value":2,"label":"36–49%"},{"value":3,"label":"≤ 35%"}]},{"key":"mmrc_pts","label":"mMRC 呼吸困难分级","type":"select","required":true,"options":[{"value":0,"label":"0–1 级"},{"value":1,"label":"2 级"},{"value":2,"label":"3 级"},{"value":3,"label":"4 级"}]},{"key":"smwd_pts","label":"6 分钟步行距离","type":"select","required":true,"options":[{"value":0,"label":"≥ 350 m"},{"value":1,"label":"250–349 m"},{"value":2,"label":"150–249 m"},{"value":3,"label":"≤ 149 m"}]}],"formula":"BODE = BMI + FEV1% + mMRC + 6MWD（总分 0–10）","compute":"sum","interpret":[{"when":"v >= 7","level":"crit","text":"7–10 分：4 年死亡风险约 60–80%，应加强肺康复、长程氧疗评估与姑息/移植评估"},{"when":"v >= 5","level":"high","text":"5–6 分：高死亡风险（约 30–50%），积极肺康复与吸入治疗优化，反复急性加重者考虑三联治疗"},{"when":"v >= 3","level":"warn","text":"3–4 分：中等风险，纳入肺康复计划，年度随访"},{"when":"v >= 0","level":"ok","text":"0–2 分：相对低风险，保持运动与戒烟"}],"note":"BODE 在 COX 模型中优于 FEV1 单独预测；急性加重期不宜评估，应稳定期复查。BMI ≤ 21 计 1 分（营养风险）。","refs":["2021 中国慢性阻塞性肺疾病诊治指南（中华医学会呼吸病学分会慢阻肺学组）","Celli BR, et al. The BODE index: a better predictor of mortality than FEV1. NEJM 2004"]},{"id":"cat_score","name":"CAT 评分（COPD 评估测试）","aka":["COPD Assessment Test"],"cat":"COPD 与哮喘","rank":14,"desc":"8 项症状问卷（各 0–5 分），量化 COPD 症状负担与生活质量影响。","inputs":[{"key":"cough","label":"咳嗽","type":"select","required":true,"options":[{"value":0,"label":"0 从不咳嗽"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 一直咳嗽"}]},{"key":"phlegm","label":"咳痰","type":"select","required":true,"options":[{"value":0,"label":"0 没有痰"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 满肺都是痰"}]},{"key":"chest","label":"胸闷","type":"select","required":true,"options":[{"value":0,"label":"0 无胸闷"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 非常闷"}]},{"key":"stairs","label":"爬楼/爬坡气促","type":"select","required":true,"options":[{"value":0,"label":"0 不气短"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 很气短"}]},{"key":"activity","label":"家务活动受限","type":"select","required":true,"options":[{"value":0,"label":"0 不受限"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 完全受限"}]},{"key":"confidence","label":"外出信心","type":"select","required":true,"options":[{"value":0,"label":"0 有信心外出"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 完全没信心"}]},{"key":"sleep","label":"睡眠","type":"select","required":true,"options":[{"value":0,"label":"0 睡得很好"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 根本睡不好"}]},{"key":"energy","label":"精力","type":"select","required":true,"options":[{"value":0,"label":"0 精力充沛"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 完全没精力"}]}],"formula":"CAT = 8 项得分之和（0–40）","compute":"sum","interpret":[{"when":"v >= 30","level":"crit","text":"≥ 30 分：症状极重，影响生活质量，评估急性加重风险与升级治疗（含肺康复、长程氧疗评估）"},{"when":"v > 20","level":"high","text":"21–29 分：症状重，考虑 LABA+LAMA±ICS 优化，纳入肺康复"},{"when":"v >= 10","level":"warn","text":"10–20 分：症状中等，按 GOLD ABE 分组调整吸入方案并复评"},{"when":"v < 10","level":"ok","text":"< 10 分：症状较轻，维持吸入治疗并戒烟"}],"note":"CAT ≥ 10 视为症状多（mMRC ≥ 2 同义）；急性加重期评分会显著升高，稳定期或出院后 4 周复评更可靠。","refs":["2021 中国慢性阻塞性肺疾病诊治指南","GOLD 2023 Report（CAT 与 ABE 分组评估）","Jones PW, et al. Development and first validation of the COPD Assessment Test. ERJ 2009"]},{"id":"mmrc","name":"mMRC 呼吸困难分级","aka":["modified Medical Research Council dyspnea scale"],"cat":"COPD 与哮喘","rank":15,"desc":"5 级呼吸困难量表，用于 COPD 症状分组与肺康复评估。","inputs":[{"key":"grade","label":"mMRC 级别","type":"select","required":true,"options":[{"value":0,"label":"0 级：剧烈活动才气促"},{"value":1,"label":"1 级：平地快走或爬缓坡气促"},{"value":2,"label":"2 级：平路行走比同龄人慢或需停下休息"},{"value":3,"label":"3 级：平路行走约 100 m 或几分钟需停下"},{"value":4,"label":"4 级：穿衣等日常活动即气促，无法外出"}]}],"formula":"mMRC 0–4 级（0–1 为症状少，≥2 为症状多）","compute":"sum","interpret":[{"when":"v >= 3","level":"crit","text":"3–4 级：重度呼吸困难，评估长程氧疗、肺康复与高级治疗（外科肺减容/移植）适应证"},{"when":"v == 2","level":"warn","text":"2 级：症状多（≥2 级分组），按 GOLD ABE 强化治疗与肺康复"},{"when":"v <= 1","level":"ok","text":"0–1 级：症状少，以戒烟、疫苗与吸入维持治疗为主"}],"note":"与 CAT 二选一使用；症状分级（A/B/E 中的 B/E）依据 mMRC ≥ 2 或 CAT ≥ 10。","refs":["2021 中国慢性阻塞性肺疾病诊治指南","GOLD 2023 Report","2019 GOLD 指南更新：ABE 评估工具的由来"]},{"id":"gold_spirometry","name":"GOLD 气流受限分级（FEV1 % 预计值）","aka":["GOLD Grade","气流受限严重度分级"],"cat":"肺功能判读","rank":16,"desc":"依据吸入支气管扩张剂后 FEV1 % 预计值分 1–4 级，是 COPD 诊断与分级的基础。","inputs":[{"key":"fev1pp","label":"支扩后 FEV1 % 预计值","unit":"%","type":"number","min":5,"max":150,"step":1,"required":true},{"key":"ratio","label":"FEV1/FVC（支扩后）","unit":"","type":"number","min":0.2,"max":1.2,"step":0.01,"required":true,"hint":"< 0.70 为气流受限（COPD 诊断条件）"}],"formula":"GOLD 1：FEV1 ≥ 80% 预计值；GOLD 2：50–79%；GOLD 3：30–49%；GOLD 4：< 30%（均需 FEV1/FVC < 0.70）","compute":"gold_grade","algorithm":"if ratio < 0.70:\n  if fev1pp >= 80 → GOLD 1\n  elif fev1pp >= 50 → GOLD 2\n  elif fev1pp >= 30 → GOLD 3\n  else → GOLD 4\nelse: 不满足 COPD 气流受限标准\nv = grade 序号(1-4)；ratio >= 0.7 时 v = 0","interpret":[{"when":"ratio >= 0.7","level":"warn","text":"FEV1/FVC ≥ 0.70：不满足 COPD 气流受限标准，考虑限制性通气障碍、哮喘或其他原因，需查肺总量/TLC 与激发试验"},{"when":"fev1pp < 30","level":"crit","text":"GOLD 4 级（极重度）：FEV1 < 30% 预计值，评估长程氧疗、肺康复、反复急性加重者三联治疗，必要时移植评估"},{"when":"fev1pp < 50","level":"high","text":"GOLD 3 级（重度）：FEV1 30–49%，优先 LABA+LAMA，反复急性加重者加 ICS"},{"when":"fev1pp < 80","level":"warn","text":"GOLD 2 级（中度）：FEV1 50–79%，推荐长效支气管扩张剂，随访症状与急性加重"},{"when":"fev1pp >= 80","level":"ok","text":"GOLD 1 级（轻度）：FEV1 ≥ 80%，以戒烟、疫苗与按需 SABA 为主"}],"note":"分级须在吸入支气管扩张剂后测量，并与症状/急性加重（ABE 分组）共同决策；FEV1% 分级不代表吸入治疗强度。","refs":["2021 中国慢性阻塞性肺疾病诊治指南","GOLD 2024 Report（诊断与分级部分）","2022 中国慢性阻塞性肺疾病急性加重诊治专家共识"]},{"id":"gold_abe","name":"GOLD ABE 分组","aka":["GOLD ABE Assessment","COPD 综合评估分组"],"cat":"COPD 与哮喘","rank":17,"desc":"综合症状（mMRC/CAT）与急性加重史分为 A/B/E 组，决定初始吸入治疗方案。","inputs":[{"key":"symptom_high","label":"症状负荷（mMRC ≥ 2 或 CAT ≥ 10）","type":"select","required":true,"options":[{"value":0,"label":"症状少（mMRC 0–1 且 CAT < 10）"},{"value":1,"label":"症状多（mMRC ≥ 2 或 CAT ≥ 10）"}]},{"key":"exac","label":"过去 1 年急性加重次数","type":"select","required":true,"options":[{"value":0,"label":"0–1 次（未因加重住院）"},{"value":1,"label":"≥ 2 次"},{"value":2,"label":"≥ 1 次因加重住院"}]}],"formula":"E 组：≥2 次中度加重或 ≥1 次住院加重；A 组：0–1 次加重且症状少；B 组：0–1 次加重且症状多","compute":"gold_abe","algorithm":"if exac >= 1 (≥2 次中度加重或 ≥1 次住院) → 'E'\nelif symptom_high == 1 → 'B'\nelse → 'A'\nv = exac*10 + symptom_high  # E 组 v>=10","interpret":[{"when":"exac == 2","level":"crit","text":"E 组（≥ 1 次住院加重）：首选 LABA+LAMA，血嗜酸细胞 ≥ 300/μL 或反复加重考虑三联；强化疫苗接种与肺康复"},{"when":"exac == 1","level":"high","text":"E 组（≥ 2 次中度加重）：LABA+LAMA 起始，嗜酸细胞 ≥ 300/μL 考虑加 ICS"},{"when":"symptom_high == 1","level":"warn","text":"B 组（症状多、加重少）：LABA+LAMA 起始，辅以肺康复"},{"when":"symptom_high == 0","level":"ok","text":"A 组（症状少、加重少）：按需短效支气管扩张剂或单药长效支气管扩张剂"}],"note":"2023 年起 GOLD 以 ABE 取代 ABCD；ICS 使用需结合血嗜酸细胞计数（≥ 300/μL 获益明显，< 100/μL 不推荐）。","refs":["2021 中国慢性阻塞性肺疾病诊治指南","GOLD 2024 Report","2023 慢性阻塞性肺疾病急性加重中国专家共识"]},{"id":"fev1_fvc","name":"FEV1/FVC 判读（阻塞/限制性通气）","aka":["FEV1/FVC","一秒率判读"],"cat":"肺功能判读","rank":18,"desc":"结合 FEV1 占预计值百分比与 FVC 判读通气功能障碍类型及严重度。","inputs":[{"key":"fev1","label":"FEV1","unit":"L","type":"number","min":0.2,"max":8,"step":0.01,"required":true},{"key":"fvc","label":"FVC","unit":"L","type":"number","min":0.2,"max":9,"step":0.01,"required":true},{"key":"fev1pp","label":"FEV1 % 预计值","unit":"%","type":"number","min":5,"max":160,"step":1,"required":true},{"key":"vcpp","label":"FVC % 预计值","unit":"%","type":"number","min":10,"max":160,"step":1,"required":false}],"formula":"FEV1/FVC = FEV1 ÷ FVC；LLN 通常为 0.70（GOLD）或按年龄/性别/身高第五百分位；FEV1% 分级：≥70 轻、60–69 轻-中、50–59 中、35–49 中-重、<35 重","compute":"fev1_fvc","algorithm":"ratio = fev1 / fvc\nif ratio < 0.70 or ratio < LLN → 阻塞性通气障碍；若 vcpp < LLN 且 ratio >= 0.7 → 限制性（需 TLC 确认）\n严重度按 fev1pp：>=80 正常/轻度、70-79 轻度、60-69 轻-中、50-59 中度、35-49 中-重、<35 重度\nv = fev1pp  # 用于 interpret","interpret":[{"when":"fev1pp < 35","level":"crit","text":"FEV1 < 35% 预计值：极重度通气障碍，注意呼吸衰竭风险，评估长期氧疗与无创通气"},{"when":"fev1pp < 50","level":"high","text":"FEV1 35–49%：重度通气障碍，活动耐量显著下降，评估肺康复与急性加重预防"},{"when":"fev1pp < 70","level":"warn","text":"FEV1 50–69%：中度通气障碍，需明确可逆性与病因（阻塞 vs 限制）"},{"when":"fev1pp <= 79","level":"warn","text":"FEV1 70–79%：轻度通气障碍，结合症状与支扩试验判断"},{"when":"fev1pp >= 80","level":"ok","text":"FEV1 ≥ 80% 预计值：通气功能基本正常范围"}],"note":"需同时看 FEV1/FVC：< 0.70（或 < LLN）为阻塞；FEV1/FVC 正常而 FVC < LLN 提示限制性，需 TLC 确认。质量控制（可逆性、用力充分）直接影响判读。","refs":["中国肺功能检查指南（2014）与肺功能检查技术规范（2019）","GOLD 2024 Report","ATS/ERS 2005 肺功能标准化解读（LLN 与严重度分级）"]},{"id":"dlco","name":"DLCO 判读（弥散功能）","aka":["DLCO","一氧化碳弥散量","TLCO"],"cat":"肺功能判读","rank":19,"desc":"依据 DLCO % 预计值判断弥散功能受损程度，并提示可能病因。","inputs":[{"key":"dlcopp","label":"DLCO % 预计值","unit":"%","type":"number","min":5,"max":200,"step":1,"required":true},{"key":"vapp","label":"VA % 预计值（肺泡通气量）","unit":"%","type":"number","min":10,"max":200,"step":1,"required":false,"hint":"用于区分 DLCO 下降是否继发于肺容积减少"},{"key":"hb","label":"血红蛋白","unit":"g/L","type":"number","min":40,"max":220,"step":1,"required":false}],"formula":"DLCO 严重度（% 预计值）：≥ 80 正常、60–79 轻度、40–59 中度、< 40 重度；DLCO/VA（KCO）用于校正肺容积","compute":"dlco_grade","algorithm":"v = dlcopp\n若 vapp 提供：kco = dlcopp / vapp，kco 正常而 DLCO 降低提示肺容积减少为主\n若 hb 提供且 < 130 g/L：DLCO 需按 Hb 校正后判读（提示贫血致假性降低）","interpret":[{"when":"dlcopp < 40","level":"crit","text":"DLCO < 40%：重度弥散障碍，注意静息或运动低氧，需评估氧疗与ILD 病因（如 IPF、结缔组织病相关 ILD）"},{"when":"dlcopp < 60","level":"high","text":"DLCO 40–59%：中度弥散障碍，结合 HRCT、自身抗体与超声心动图排查 ILD/肺血管病"},{"when":"dlcopp < 80","level":"warn","text":"DLCO 60–79%：轻度弥散障碍，可见于早期 ILD、肺气肿、贫血或吸烟"},{"when":"dlcopp >= 80","level":"ok","text":"DLCO ≥ 80% 预计值：弥散功能正常（须校正 Hb 与 VA）"}],"note":"DLCO 需按血红蛋白与 COHb 校正；贫血使 DLCO 假性降低、红细胞增多使其升高。DLCO 明显下降且肺容积正常者警惕肺血管病，肺容积也下降者常为间质性病变。","refs":["中国肺功能检查指南——弥散功能（2014）","ATS/ERS 2005 DLCO 标准化测定与解读","2018 特发性肺纤维化诊断和治疗中国专家共识（DLCO 与随访部分）"]},{"id":"act","name":"哮喘控制测试（ACT）","aka":["Asthma Control Test"],"cat":"COPD 与哮喘","rank":20,"desc":"5 项问卷（各 1–5 分，总分 5–25），评估哮喘近 4 周控制水平。","inputs":[{"key":"q1","label":"Q1 日常活动受限程度","type":"select","required":true,"options":[{"value":1,"label":"1 完全受限"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 完全不受限"}]},{"key":"q2","label":"Q2 气促发作频率","type":"select","required":true,"options":[{"value":1,"label":"1 每天多次"},{"value":2,"label":"2 每天 1 次"},{"value":3,"label":"3 每周 3–6 次"},{"value":4,"label":"4 每周 1–2 次"},{"value":5,"label":"5 没有"}]},{"key":"q3","label":"Q3 夜间/清晨憋醒频率","type":"select","required":true,"options":[{"value":1,"label":"1 每晚或每天"},{"value":2,"label":"2 每周 4 次以上"},{"value":3,"label":"3 每周 2–3 次"},{"value":4,"label":"4 每周 1 次"},{"value":5,"label":"5 没有"}]},{"key":"q4","label":"Q4 缓解药使用频率","type":"select","required":true,"options":[{"value":1,"label":"1 每天 3 次以上"},{"value":2,"label":"2 每天 1–2 次"},{"value":3,"label":"3 每周 2–3 次"},{"value":4,"label":"4 每周 1 次或更少"},{"value":5,"label":"5 完全没有"}]},{"key":"q5","label":"Q5 自评哮喘控制情况","type":"select","required":true,"options":[{"value":1,"label":"1 完全没控制"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"},{"value":5,"label":"5 完全控制"}]}],"formula":"ACT = 5 项得分之和（5–25）","compute":"sum","interpret":[{"when":"v >= 20","level":"ok","text":"20–25 分：哮喘控制良好，维持当前方案，3–6 个月复评，考虑逐步降级"},{"when":"v >= 16","level":"warn","text":"16–19 分：部分控制，检查吸入技术与依从性，升级治疗（如 ICS-福莫特罗 MART）"},{"when":"v >= 5","level":"high","text":"5–15 分：未控制，需升级治疗、排查诱发因素与合并症（鼻炎、GERD、肥胖），复查肺功能"}],"note":"ACT 反映近 4 周症状；肺功能未达标的患者即使 ACT 好也需评估。儿童（C-ACT）版本 7 项计分不同。","refs":["2020 中国支气管哮喘防治指南（中华医学会呼吸病学分会哮喘学组）","GINA 2023 报告（哮喘控制评估工具）","Nathan RA, et al. Development of the Asthma Control Test. J Allergy Clin Immunol 2004"]},{"id":"asthma_control","name":"哮喘控制水平分级（GINA）","aka":["Asthma Control Level","GINA 控制水平"],"cat":"COPD 与哮喘","rank":21,"desc":"按过去 4 周日间症状、活动受限、夜间憋醒与缓解药使用评估控制程度。","inputs":[{"key":"daytime","label":"日间症状 > 2 次/周","type":"select","required":true,"options":[{"value":0,"label":"否（≤ 2 次/周）"},{"value":1,"label":"是"}]},{"key":"night","label":"夜间憋醒","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"saba","label":"缓解药使用 > 2 次/周","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"limit","label":"活动受限","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"pft","label":"肺功能（FEV1/FVC < 0.75 或 FEV1 < 80% 预计值）","type":"select","required":false,"options":[{"value":0,"label":"正常"},{"value":1,"label":"异常"}]}],"formula":"4 项（+ 肺功能）全部为「否」→ 控制；1–2 项为「是」→ 部分控制；3–4 项 → 未控制","compute":"asthma_control","algorithm":"n = daytime + night + saba + limit  (+ pft 如提供)\nv = n\n0 → 良好控制；1-2 → 部分控制；>=3 → 未控制","interpret":[{"when":"v >= 3","level":"crit","text":"未控制：3–4 项达标，需升级治疗（GINA 4–5 级方案），查吸入技术、依从性与合并症，警惕重症哮喘（附件评估）"},{"when":"v >= 1","level":"warn","text":"部分控制：1–2 项达标，考虑升级或维持加 MART 方案，强化随访 1–3 个月"},{"when":"v == 0","level":"ok","text":"良好控制：维持当前方案 3 个月，稳定后可考虑逐步降级至 ICS 单药或低剂量 ICS-福莫特罗"}],"note":"中国指南采用 GINA 分级：良好控制、部分控制、未控制；每年至少评估一次并记录急性加重史。ICS 不可随意停用以防加重。","refs":["2020 中国支气管哮喘防治指南","GINA 2023 Report（控制评估与阶梯治疗）"]},{"id":"stop_bang","name":"STOP-BANG 睡眠呼吸暂停筛查","aka":["STOP-BANG","OSA 筛查问卷"],"cat":"睡眠呼吸","rank":22,"desc":"8 项指标筛查阻塞性睡眠呼吸暂停（OSA）高危人群，指导多导睡眠监测。","inputs":[{"key":"snore","label":"S 打鼾（大于说话声）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"tired","label":"T 白天疲劳/嗜睡","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"observed","label":"O 被观察到呼吸暂停","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"pressure","label":"P 高血压（或已诊治）","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"bmi","label":"B BMI > 35 kg/m²","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"age","label":"A 年龄 > 50 岁","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"neck","label":"N 颈围 > 40 cm","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"gender","label":"G 男性","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]}],"formula":"STOP-BANG = S+T+O+P+B+A+N+G（各 1 分，0–8）","compute":"sum","interpret":[{"when":"v >= 5","level":"crit","text":"5–8 分：OSA 高危（中重度阳性预测值高），尽快安排多导睡眠监测（PSG）或家庭睡眠呼吸监测"},{"when":"v >= 3","level":"warn","text":"3–4 分：中危，建议 PSG 或先做便携监测，评估日间嗜睡与合并心脑血管病"},{"when":"v >= 0","level":"ok","text":"0–2 分：低危，如症状明显（打鼾、嗜睡、晨起头痛）仍应转诊睡眠专科"}],"note":"STOP 部分（前 4 项）≥ 2 分即为 STOP 阳性；STOP-BANG ≥ 3 视为阳性。已诊断 OSA 者评估 CPAP 依从性需用其他量表。","refs":["2015 阻塞性睡眠呼吸暂停低通气综合征诊治指南（中华医学会呼吸病学分会睡眠呼吸障碍学组）","Chung F, et al. STOP-Bang Questionnaire. Anesthesiology 2008","2023 中国阻塞性睡眠呼吸暂停多学科诊疗指南"]},{"id":"epworth","name":"Epworth 嗜睡量表（ESS）","aka":["Epworth Sleepiness Scale"],"cat":"睡眠呼吸","rank":23,"desc":"8 种日常情境下打瞌睡概率（0–3 分），评估日间嗜睡程度。","inputs":[{"key":"sitting","label":"坐着阅读时","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"tv","label":"看电视时","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"public","label":"公共场所静坐（如开会、剧场）","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"passenger","label":"乘车 1 小时以上不停车时","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"rest","label":"下午躺下休息时","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"talking","label":"坐着与人交谈时","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"lunch","label":"安静就餐后（未饮酒）","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]},{"key":"car","label":"停车等红灯的几分钟内","type":"select","required":true,"options":[{"value":0,"label":"0 从不"},{"value":1,"label":"1 很少"},{"value":2,"label":"2 有时"},{"value":3,"label":"3 经常"}]}],"formula":"ESS = 8 项之和（0–24）","compute":"sum","interpret":[{"when":"v > 15","level":"crit","text":"16–24 分：重度嗜睡，驾驶/高处作业风险高，尽快睡眠专科评估并明确病因"},{"when":"v > 11","level":"warn","text":"12–15 分：明显嗜睡（中国指南界值约 11/12 分），建议 PSG 排查 OSA，评估驾驶安全"},{"when":"v >= 0","level":"ok","text":"≤ 10 分：日间嗜睡不明显；若 STOP-BANG 高危仍需进一步检查"}],"note":"ESS > 10 为广泛使用的异常界值，中国指南报道界值为 11/12 分；睡眠剥夺、抑郁与药物（抗组胺、苯二氮类）均可使评分升高。","refs":["2015 阻塞性睡眠呼吸暂停低通气综合征诊治指南（中华医学会呼吸病学分会）","Johns MW. A new method for measuring daytime sleepiness: the Epworth Sleepiness Scale. Sleep 1991"]},{"id":"smwt","name":"6 分钟步行试验判读（6MWT）","aka":["6MWT","6-minute walk test"],"cat":"肺功能判读","rank":24,"desc":"依据 6 分钟步行距离占预计值比例判断运动耐量，预测 COPD/ILD 预后。","inputs":[{"key":"dist","label":"6 分钟步行距离","unit":"m","type":"number","min":20,"max":900,"step":1,"required":true},{"key":"pred","label":"预计值（m，可留空；男性约 7.57×身高cm − 5.02×年龄 − 1.76×体重kg − 309；女性约 2.11×身高cm − 2.29×体重kg − 5.78×年龄 + 667）","unit":"m","type":"number","min":100,"max":900,"step":1,"required":false},{"key":"spo2_before","label":"试验前 SpO2","unit":"%","type":"number","min":60,"max":100,"step":1,"required":false},{"key":"spo2_after","label":"试验后 SpO2","unit":"%","type":"number","min":40,"max":100,"step":1,"required":false}],"formula":"6MWD % 预计 = 实测 ÷ 预计 × 100；COPD 阈值：≥ 350 m 较好、< 350 m 提示预后不良","compute":"smwt","algorithm":"v = dist\nif pred 提供先算 pred（按公式，性别由界面选择）\npct = dist / pred * 100\ndelta_spo2 = spo2_before - spo2_after","interpret":[{"when":"spo2_before > 0 && spo2_after > 0 && spo2_before - spo2_after >= 4","level":"crit","text":"运动后 SpO2 下降 ≥ 4%：提示运动性低氧，评估静息/运动氧疗，避免剧烈运动诱发加重"},{"when":"pred > 0 && v < 60","level":"crit","text":"< 60% 预计值：运动耐量严重下降，与住院及死亡风险升高相关，考虑肺康复与高级治疗评估"},{"when":"pred > 0 && v < 80","level":"warn","text":"60–79% 预计值：运动耐量下降，建议肺康复，复评动态变化（> 30 m 变化有意义）"},{"when":"dist < 350","level":"warn","text":"6MWD < 350 m：COPD 预后不良阈值（BODE 6MWD ≤ 349 m 计 1 分），需强化肺康复"},{"when":"v >= 0","level":"ok","text":"运动耐量尚可；随访时 > 30 m 的变化具有临床意义"}],"note":"试验需标准化：平直 30 m 走廊、标准鼓励语、试验前后测 SpO2 与心率；结果受身高、年龄、性别、体重与学习效应影响，首次偏低。","refs":["ATS Statement: Guidelines for the Six-Minute Walk Test. Am J Respir Crit Care Med 2002","2021 中国慢性阻塞性肺疾病诊治指南（肺康复部分）","Holland AE, et al. An official ERS/ATS technical standard: field walking tests. ERJ 2014"]},{"id":"mayo_nodule","name":"肺结节恶性概率（Mayo 模型）","aka":["Mayo Clinic model","Mayo 肺结节模型"],"cat":"结节与肿瘤","rank":25,"desc":"依据年龄、吸烟、结节大小位置与毛刺等估计单个肺结节恶性概率，指导随访或活检。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":100,"step":1,"required":true},{"key":"smoke_years","label":"吸烟年数（年）","type":"number","min":0,"max":80,"step":1,"required":true},{"key":"smoke_quit","label":"已戒烟年数（未戒烟填 0）","unit":"年","type":"number","min":0,"max":60,"step":1,"required":true},{"key":"diameter","label":"结节直径/最长径","unit":"mm","type":"number","min":3,"max":60,"step":0.5,"required":true},{"key":"upper","label":"位于上叶","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"spiculation","label":"毛刺征","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]}],"formula":"x = 0.0391×年龄 + 0.7917×吸烟量(包年) + 0.1274×直径mm + 1.0407×上叶 + 0.7838×毛刺 − 6.8272；恶性概率 = e^x/(1+e^x)；吸烟量包年 = 吸烟年数×每日包数（按 1 包/日计）","compute":"mayo_nodule","algorithm":"pack_years = smoke_years * 1.0   # 未采集每日包数时按 1 包/日估算，需在结果中提示\nx = 0.0391*age + 0.7917*pack_years + 0.1274*diameter + 1.0407*upper + 0.7838*spiculation - 6.8272\np = exp(x)/(1+exp(x))\nv = round(p*1000)/10   # 以百分数输出\n注：模型不单列戒烟年数项，戒烟年数仅用于临床判断（<15 年戒烟仍为高危）","interpret":[{"when":"v >= 65","level":"crit","text":"恶性概率 ≥ 65%：高度可疑，建议外科切除/活检（PET-CT 用于分期，不宜替代病理）"},{"when":"v >= 15","level":"high","text":"15–65%：中度可疑，PET-CT 与多学科评估，考虑 CT 引导下活检或手术切除"},{"when":"v >= 5","level":"warn","text":"5–15%：低危，3 个月复查薄层 CT，随访观察增大与形态变化"},{"when":"v >= 0","level":"ok","text":"< 5%：极低危，按 Fleischner/中国指南随访（如 6–12 个月复查 CT）"}],"note":"本模型基于胸片年代数据，对新式 CT 检出的小磨玻璃结节（尤其纯磨玻璃）低估风险；mGGN 与实性结节随访策略不同，需结合 2018 中国肺结节诊治共识与 Brock 模型。","refs":["2018 中国肺部结节分类、诊断与治疗指南（中华医学会呼吸病学分会肺癌学组）","2015 肺结节诊治中国专家共识","Swensen SJ, et al. The probability of malignancy in solitary pulmonary nodules. Arch Intern Med 1997","Fleischner Society 2017 肺结节随访指南"]},{"id":"brock_model","name":"肺结节恶性概率（Brock 模型）","aka":["Brock model","PanCan model","Brock 结节模型"],"cat":"结节与肿瘤","rank":26,"desc":"基于 CT 特征的肺结节（含磨玻璃）恶性概率模型，适合 CT 筛查人群。","inputs":[{"key":"age","label":"年龄","unit":"岁","type":"number","min":18,"max":100,"step":1,"required":true},{"key":"female","label":"性别","type":"select","required":true,"options":[{"value":0,"label":"男"},{"value":1,"label":"女"}]},{"key":"family","label":"一级亲属肺癌家族史","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"emphysema","label":"肺气肿","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]},{"key":"size","label":"结节平均直径","unit":"mm","type":"number","min":3,"max":60,"step":0.5,"required":true},{"key":"type","label":"结节类型","type":"select","required":true,"options":[{"value":0,"label":"实性"},{"value":1,"label":"部分实性"},{"value":2,"label":"非实性（纯磨玻璃）"}]},{"key":"upper","label":"位于上叶","type":"select","required":true,"options":[{"value":0,"label":"否"},{"value":1,"label":"是"}]},{"key":"count","label":"结节个数","type":"select","required":true,"options":[{"value":0,"label":"单发"},{"value":1,"label":"多发（≥2）"}]},{"key":"spiculation","label":"毛刺征","type":"select","required":true,"options":[{"value":0,"label":"无"},{"value":1,"label":"有"}]}],"formula":"logit = −6.7891 + 0.0287×年龄 + 0.6011×女性 + 0.2963×家族史 + 0.2953×肺气肿 + 0.0824×直径mm + 0.6581×部分实性 − 0.2769×非实性 + 0.3775×上叶 + 0.3251×多发 + 0.8129×毛刺；p = 1/(1+e^−logit)","compute":"brock_model","algorithm":"logit = -6.7891 + 0.0287*age + 0.6011*female + 0.2963*family + 0.2953*emphysema + 0.0824*size + 0.6581*(type==1) - 0.2769*(type==2) + 0.3775*upper + 0.3251*count + 0.8129*spiculation\np = 1/(1+exp(-logit))\nv = round(p*1000)/10  # 百分数","interpret":[{"when":"v >= 50","level":"crit","text":"恶性概率 ≥ 50%：高度怀疑，建议手术切除或明确组织学诊断"},{"when":"v >= 15","level":"high","text":"15–50%：中度可疑，PET-CT（部分实性病灶敏感性有限）与多学科讨论，考虑活检"},{"when":"v >= 5","level":"warn","text":"5–15%：低危，3 个月薄层 CT 复查，观察实性成分变化"},{"when":"v >= 0","level":"ok","text":"< 5%：极低危，12 个月复查 CT（纯磨玻璃可延长至 12 个月以上）"}],"note":"Brock 模型适用于 8–30 mm 结节；> 30 mm 实性病灶属肿块，应按肺癌流程处理。模型不能替代多学科评估与随访影像变化。","refs":["2018 中国肺部结节分类、诊断与治疗指南（中华医学会呼吸病学分会）","McWilliams A, et al. Probability of cancer in pulmonary nodules detected on first screening CT. NEJM 2013","Fleischner Society 2017 肺结节随访指南"]}]},"rheum":{"items":[{"id":"rheum_das28_esr","name":"DAS28-ESR（类风湿关节炎疾病活动度）","aka":["DAS28","Disease Activity Score 28"],"cat":"类风湿关节炎","rank":1,"desc":"用 28 关节压痛/肿胀数、ESR 与患者总体评价计算 RA 疾病活动度。","inputs":[{"key":"tjc28","label":"28 关节压痛数 TJC28","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"sjc28","label":"28 关节肿胀数 SJC28","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"esr","label":"ESR","unit":"mm/h","type":"number","min":0,"max":150,"step":1,"required":true},{"key":"gh","label":"患者总体健康评价 VAS","unit":"mm (0–100)","type":"number","min":0,"max":100,"step":1,"required":true}],"formula":"DAS28 = 0.56×√TJC28 + 0.28×√SJC28 + 0.70×ln(ESR) + 0.014×GH","compute":"formula_only","algorithm":"v = 0.56*Math.sqrt(tjc28) + 0.28*Math.sqrt(sjc28) + 0.70*Math.log(Math.max(esr,1)) + 0.014*gh","interpret":[{"when":"v < 2.6","level":"ok","text":"临床缓解（< 2.6）：维持治疗，按达标治疗（T2T）每 3–6 月复评"},{"when":"v < 3.2","level":"ok","text":"低疾病活动度（2.6–3.2）"},{"when":"v <= 5.1","level":"warn","text":"中疾病活动度（3.2–5.1）：调整 csDMARD/靶向药物"},{"when":"v > 5.1","level":"high","text":"高疾病活动度（> 5.1）：强化治疗，考虑生物制剂或 JAK 抑制剂"}],"note":"28 关节（双肩、肘、腕、掌指 1–5、近指 1–5、双膝）；ESR 用 mm/h；妊娠、贫血、感染时 ESR 受干扰，可用 DAS28-CRP。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","EULAR Recommendations for Management of RA (2022)"]},{"id":"rheum_das28_crp","name":"DAS28-CRP（类风湿关节炎活动度）","aka":["DAS28-CRP","DAS28-CRP(4)"],"cat":"类风湿关节炎","rank":2,"desc":"以 CRP 替代 ESR 计算 DAS28，适用于 ESR 失真情况。","inputs":[{"key":"tjc28","label":"28 关节压痛数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"sjc28","label":"28 关节肿胀数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"crp","label":"CRP","unit":"mg/L","type":"number","min":0,"max":300,"step":0.1,"required":true},{"key":"gh","label":"患者总体健康评价 VAS","unit":"mm (0–100)","type":"number","min":0,"max":100,"step":1,"required":true}],"formula":"DAS28-CRP = 0.56×√TJC28 + 0.28×√SJC28 + 0.36×ln(CRP+1) + 0.014×GH + 0.96","compute":"formula_only","algorithm":"v = 0.56*Math.sqrt(tjc28) + 0.28*Math.sqrt(sjc28) + 0.36*Math.log(crp+1) + 0.014*gh + 0.96","interpret":[{"when":"v < 2.4","level":"ok","text":"临床缓解（< 2.4，CRP 版本切点）"},{"when":"v < 2.9","level":"ok","text":"低疾病活动度（2.4–2.9）"},{"when":"v <= 4.1","level":"warn","text":"中疾病活动度（2.9–4.1）"},{"when":"v > 4.1","level":"high","text":"高疾病活动度（> 4.1）"}],"note":"DAS28-CRP 切点与 ESR 版不同（2.4/2.9/4.1）；不能把两版本结果混用于同一患者随访。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","EULAR Recommendations for Management of RA (2022)"]},{"id":"rheum_cdai","name":"CDAI（临床疾病活动指数）","aka":["CDAI","Clinical Disease Activity Index"],"cat":"类风湿关节炎","rank":3,"desc":"不含急性期反应物的 RA 活动度指标，可即时计算。","inputs":[{"key":"tjc28","label":"28 关节压痛数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"sjc28","label":"28 关节肿胀数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"pga","label":"患者整体评价 PGA","unit":"cm (0–10)","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"ega","label":"医生整体评价 EGA","unit":"cm (0–10)","type":"number","min":0,"max":10,"step":0.1,"required":true}],"formula":"CDAI = TJC28 + SJC28 + PGA + EGA（0–76）","compute":"formula_only","algorithm":"v = tjc28 + sjc28 + pga + ega","interpret":[{"when":"v <= 2.8","level":"ok","text":"缓解（≤ 2.8）"},{"when":"v <= 10","level":"ok","text":"低活动度（2.8–10）"},{"when":"v <= 22","level":"warn","text":"中活动度（10–22）"},{"when":"v > 22","level":"high","text":"高活动度（> 22）：考虑强化治疗"}],"note":"PGA/EGA 用 0–10 cm VAS；CDAI 与 SDAI 切点相同；无需血检，适合基层随访。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","Aletaha D, et al. Arthritis Rheum 2005"]},{"id":"rheum_sdai","name":"SDAI（简化疾病活动指数）","aka":["SDAI","Simplified Disease Activity Index"],"cat":"类风湿关节炎","rank":4,"desc":"在 CDAI 基础上加入 CRP 的 RA 活动度指标。","inputs":[{"key":"tjc28","label":"28 关节压痛数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"sjc28","label":"28 关节肿胀数","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"pga","label":"患者整体评价","unit":"cm (0–10)","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"ega","label":"医生整体评价","unit":"cm (0–10)","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"crp","label":"CRP","unit":"mg/dL","type":"number","min":0,"max":30,"step":0.1,"required":true}],"formula":"SDAI = TJC28 + SJC28 + PGA + EGA + CRP(mg/dL)（0–86）","compute":"formula_only","algorithm":"v = tjc28 + sjc28 + pga + ega + crp","interpret":[{"when":"v <= 3.3","level":"ok","text":"缓解（≤ 3.3）"},{"when":"v <= 11","level":"ok","text":"低活动度（3.3–11）"},{"when":"v <= 26","level":"warn","text":"中活动度（11–26）"},{"when":"v > 26","level":"high","text":"高活动度（> 26）"}],"note":"CRP 单位须为 mg/dL（如为 mg/L 请除以 10）；CRP 受感染影响，活动度判断需结合关节体征。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","Smolen JS, et al. Ann Rheum Dis 2003"]},{"id":"rheum_basdai","name":"BASDAI（强直性脊柱炎疾病活动指数）","aka":["BASDAI","Bath AS Disease Activity Index"],"cat":"脊柱关节炎","rank":5,"desc":"患者自评 6 项，评估强直性脊柱炎疾病活动度与生物制剂指征。","inputs":[{"key":"fatigue","label":"疲乏","unit":"VAS 0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"spine_pain","label":"颈背/髋部疼痛","unit":"VAS 0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"joint_pain","label":"外周关节疼痛/肿胀","unit":"VAS 0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"enthesitis","label":"附着点炎症/疼痛","unit":"VAS 0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"morning_intensity","label":"晨僵程度","unit":"VAS 0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"morning_duration","label":"晨僵持续时间","unit":"VAS 0–10（时间 0–2 h 折算）","type":"number","min":0,"max":10,"step":0.1,"required":true}],"formula":"BASDAI = [Q1+Q2+Q3+Q4+(Q5+Q6)/2]÷5（0–10）","compute":"formula_only","algorithm":"v = (fatigue + spine_pain + joint_pain + enthesitis + (morning_intensity + morning_duration)/2)/5","interpret":[{"when":"v >= 4","level":"high","text":"BASDAI ≥ 4：疾病活动，治疗未达标；NSAIDs 无效者评估 TNF 抑制剂/IL-17 抑制剂"},{"when":"v >= 2 && v < 4","level":"warn","text":"BASDAI 2–4：轻中度活动，继续 NSAIDs 与锻炼"},{"when":"v < 2","level":"ok","text":"BASDAI < 2：疾病控制良好"}],"note":"第 6 项晨僵持续时间 0–2 h 按 VAS 0–10 折算（0 = 无，10 = ≥ 2 h）；需同时评估 BASFI 与 CRP。","refs":["中国强直性脊柱炎诊疗规范（2022）","ASAS/EULAR Recommendations for axSpA (2022)"]},{"id":"rheum_asdas","name":"ASDAS（强直性脊柱炎疾病活动评分）","aka":["ASDAS-CRP","ASDAS-ESR"],"cat":"脊柱关节炎","rank":6,"desc":"含急性期反应物的 axSpA 活动评分，用于 EULAR 活动度分档。","inputs":[{"key":"back_pain","label":"背痛/晨僵总分","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"morning_stiffness","label":"晨僵持续时间","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"patient_global","label":"患者整体评价","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"peripheral","label":"外周疼痛/肿胀","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"crp","label":"CRP","unit":"mg/L","type":"number","min":0,"max":300,"step":0.1,"required":true}],"formula":"ASDAS-CRP = 0.121×背痛 + 0.110×晨僵时长 + 0.073×患者整体 + 0.079×外周 + 0.579×ln(CRP+1)","compute":"formula_only","algorithm":"v = 0.121*back_pain + 0.110*morning_stiffness + 0.073*patient_global + 0.079*peripheral + 0.579*Math.log(crp+1)","interpret":[{"when":"v < 1.3","level":"ok","text":"无活动（< 1.3）"},{"when":"v < 2.1","level":"ok","text":"低活动（1.3–2.1）"},{"when":"v <= 3.5","level":"warn","text":"高活动（2.1–3.5）：调整治疗并复评"},{"when":"v > 3.5","level":"high","text":"极高活动（> 3.5）：考虑生物制剂"}],"note":"CRP 用 mg/L；ASDAS 需用 CRP 或 ESR 任一种（不可混用）；临床缓解标准 ASDAS < 1.3，主要改善 ≥ 1.1。","refs":["中国强直性脊柱炎诊疗规范（2022）","Machado P, et al. Arthritis Rheum 2011"]},{"id":"rheum_basfi","name":"BASFI（强直性脊柱炎功能指数）","aka":["BASFI","Bath AS Functional Index"],"cat":"脊柱关节炎","rank":7,"desc":"患者自评 10 项日常功能，评估脊柱关节炎功能损害。","inputs":[{"key":"socks","label":"穿袜子/拾物","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"bend","label":"弯腰捡物","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"reach","label":"上举物体","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"rise_chair","label":"从无扶手椅起立","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"floor","label":"从仰卧起立","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"stand","label":"无支撑站立 10 min","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"stairs","label":"上 12–15 级台阶","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"look","label":"回头看","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"activity","label":"体力活动","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true},{"key":"full_day","label":"整日在家/工作","unit":"0–10","type":"number","min":0,"max":10,"step":0.1,"required":true}],"formula":"BASFI = 10 项均值（0–10）","compute":"formula_only","algorithm":"v = (socks+bend+reach+rise_chair+floor+stand+stairs+look+activity+full_day)/10","interpret":[{"when":"v < 2","level":"ok","text":"BASFI < 2：功能良好"},{"when":"v >= 2 && v < 4","level":"warn","text":"BASFI 2–4：轻中度功能受限，建议康复锻炼"},{"when":"v >= 4","level":"high","text":"BASFI ≥ 4：功能受限明显，强化康复与药物治疗"}],"note":"各条 0–10 VAS；需与其他评分同时记录；功能不可逆损害时 BASFI 不随治疗改善。","refs":["中国强直性脊柱炎诊疗规范（2022）","Calin A, et al. J Rheumatol 1994"]},{"id":"rheum_sledai","name":"SLEDAI-2K（系统性红斑狼疮疾病活动指数）","aka":["SLEDAI","SLE Disease Activity Index"],"cat":"系统性红斑狼疮","rank":8,"desc":"按 24 项临床与实验室表现加权评估 SLE 当前活动度。","inputs":[{"key":"seizure","label":"癫痫发作（+8）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"psychosis","label":"精神病性症状（+8）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"visual","label":"视觉障碍（+8）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"cns","label":"颅神经/脑血管事件（+8）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"lupus_headache","label":"狼疮性头痛（+8，2K 版）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"vasculitis","label":"血管炎（+8）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":8,"label":"有"}],"required":true},{"key":"arthritis","label":"关节炎（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"myositis","label":"肌炎（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"urinary_cast","label":"管型尿（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"hematuria","label":"血尿（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"proteinuria","label":"蛋白尿 > 0.5 g/24h（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"pyuria","label":"脓尿（+4）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"rash","label":"新发皮疹（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"alopecia","label":"脱发（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"mucosal","label":"口腔/鼻黏膜溃疡（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"pleurisy","label":"胸膜炎（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"pericarditis","label":"心包炎（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"low_complement","label":"补体降低（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"dsdna","label":"抗 dsDNA 升高（+2）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"有"}],"required":true},{"key":"fever","label":"发热（+1）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"thrombocytopenia","label":"血小板减少 < 100×10⁹/L（+1）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"leukopenia","label":"白细胞减少 < 3.0×10⁹/L（+1）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"esr_high","label":"ESR > 50 mm/h（+1）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"24 项加权求和（0–105）","compute":"sum","interpret":[{"when":"v >= 12","level":"crit","text":"极高活动（≥ 12）：考虑大剂量激素联合免疫抑制剂/生物制剂，注意感染"},{"when":"v >= 6 && v < 12","level":"high","text":"中高活动（6–11）：调整激素与免疫抑制剂"},{"when":"v >= 1 && v < 6","level":"warn","text":"轻度活动（1–5）：维持治疗与随访"},{"when":"v == 0","level":"ok","text":"无活动（0）：继续维持治疗"}],"note":"SLEDAI 只反映近 10 天活动；需与损伤指数（SLICC/ACR DI）区分；蛋白尿以 24 h 尿蛋白为准。","refs":["2020 中国系统性红斑狼疮诊疗指南","Gladman D, et al. J Rheumatol 2002 (SLEDAI-2K)"]},{"id":"rheum_slicc_di","name":"SLICC/ACR 损伤指数（SDI）","aka":["SLICC DI","损伤指数"],"cat":"系统性红斑狼疮","rank":15,"desc":"评估 SLE 不可逆器官损伤，指导长期预后判断。","inputs":[{"key":"renal","label":"肾脏损伤（GFR < 50%、蛋白尿 ≥ 3.5 g/d、透析等）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"1 分"},{"value":2,"label":"2 分"},{"value":3,"label":"3 分"}],"required":true},{"key":"cns","label":"神经精神损伤（认知、癫痫、脑血管意外等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"},{"value":3,"label":"3"},{"value":4,"label":"4"}],"required":true},{"key":"pulmonary","label":"肺（肺高压、纤维化、肺梗死等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"}],"required":true},{"key":"cardio","label":"心血管（心衰、心梗、心肌病等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"}],"required":true},{"key":"peripheral_vasc","label":"周围血管（跛行、坏死等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"}],"required":true},{"key":"msk","label":"骨骼肌肉（关节畸形、骨坏死等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"},{"value":2,"label":"2"}],"required":true},{"key":"skin","label":"皮肤（瘢痕性脱发、皮肤溃疡等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"1"}],"required":true},{"key":"diabetes","label":"糖尿病（需治疗）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"1"}],"required":true},{"key":"malignancy","label":"恶性肿瘤","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"1"}],"required":true}],"formula":"SDI = 12 器官系统损伤分之和（0–47）","compute":"sum","interpret":[{"when":"v >= 3","level":"high","text":"SDI ≥ 3：器官损伤显著，提示预后不良与死亡风险升高"},{"when":"v >= 1 && v < 3","level":"warn","text":"SDI 1–2：已出现不可逆损伤，注意控制疾病活动与药物毒性"},{"when":"v == 0","level":"ok","text":"SDI 0：无器官损伤"}],"note":"损伤需持续 ≥ 6 个月且归因于 SLE 本身或治疗；与 SLEDAI 同时评估（活动 vs 损伤）；本简表未列全 12 项，仅作参考。","refs":["2020 中国系统性红斑狼疮诊疗指南","Gladman D, et al. Arthritis Rheum 1996 (SLICC/ACR DI)"]},{"id":"rheum_ra_acr_eular","name":"ACR/EULAR 2010 类风湿关节炎分类标准评分","aka":["RA 分类标准","2010 ACR/EULAR"],"cat":"分类标准","rank":9,"desc":"对具有至少 1 个关节肿胀且无法用其他疾病解释者，按四项评分≥6 分分类为 RA。","inputs":[{"key":"joint_involvement","label":"关节受累","unit":"","type":"select","options":[{"value":0,"label":"0（1 个大关节）"},{"value":1,"label":"1（2–10 个大关节）"},{"value":2,"label":"2（1–3 个小关节）"},{"value":3,"label":"3（4–10 个小关节）"},{"value":5,"label":"5（> 10 个关节，至少 1 个为小关节）"}],"required":true},{"key":"serology","label":"血清学","unit":"","type":"select","options":[{"value":0,"label":"RF 与抗 CCP 均阴性"},{"value":2,"label":"RF 或抗 CCP 低滴度阳性"},{"value":3,"label":"RF 或抗 CCP 高滴度阳性"}],"required":true},{"key":"apr","label":"急性时相反应物","unit":"","type":"select","options":[{"value":0,"label":"CRP 与 ESR 均正常"},{"value":1,"label":"CRP 或 ESR 升高"}],"required":true},{"key":"duration","label":"症状持续时间","unit":"","type":"select","options":[{"value":0,"label":"< 6 周"},{"value":1,"label":"≥ 6 周"}],"required":true}],"formula":"四项相加，0–10 分；≥ 6 分分类为 RA","compute":"sum","interpret":[{"when":"v >= 6","level":"high","text":"≥ 6 分：可分类为 RA，尽早启动 csDMARD（甲氨蝶呤），按 T2T 达标治疗"},{"when":"v >= 3 && v < 6","level":"warn","text":"3–5 分：未分类关节炎，密切随访并鉴别其他关节炎"},{"when":"v < 3","level":"ok","text":"< 3 分：不符合 RA 分类标准"}],"note":"小关节指 MCP、PIP、第 2–5 跖趾、拇指指间、腕关节；高滴度指 ≥ 3 倍正常上限；标准仅用于分类，不用于诊断个体患者。","refs":["2010 ACR/EULAR RA Classification Criteria","中国类风湿关节炎诊疗指南（2018/2023）"]},{"id":"rheum_gout_acr_eular","name":"ACR/EULAR 2015 痛风分类标准评分","aka":["痛风分类标准","2015 ACR/EULAR Gout"],"cat":"分类标准","rank":10,"desc":"按临床表现、实验室与影像评分（≥ 8 分）分类为痛风，适用于有至少 1 次外周关节肿胀/疼痛发作。","inputs":[{"key":"msu_crystal","label":"关节液中检出 MSU 结晶（金标准）","unit":"","type":"select","options":[{"value":0,"label":"未查/阴性"},{"value":1,"label":"阳性（直接分类）"}],"required":true},{"key":"pattern","label":"受累关节模式","unit":"","type":"select","options":[{"value":0,"label":"其他"},{"value":1,"label":"第 1 跖趾关节（MTP1）受累"},{"value":2,"label":"MTP1 为主"}],"required":true},{"key":"characteristics","label":"发作特征（红斑、触痛、行走困难）","unit":"","type":"select","options":[{"value":0,"label":"≤ 1 项"},{"value":1,"label":"2 项"},{"value":2,"label":"3 项"}],"required":true},{"key":"time_course","label":"发作时间特点（24 h 达峰、14 天内缓解、发作间期完全恢复）","unit":"","type":"select","options":[{"value":0,"label":"无/1 项"},{"value":1,"label":"2 项"},{"value":2,"label":"3 项"}],"required":true},{"key":"tophus","label":"痛风石","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"imaging","label":"影像（超声双轨征或 DECT 尿酸盐）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"有"}],"required":true},{"key":"ua_high","label":"血尿酸高于实验室上限（> 1 次）","unit":"","type":"select","options":[{"value":0,"label":"正常/未查"},{"value":2,"label":"升高"}],"required":true}],"formula":"MSU 阳性直接分类；否则各项相加，≥ 8 分分类为痛风","compute":"sum","interpret":[{"when":"msu_crystal == 1","level":"crit","text":"关节液检出 MSU 结晶：直接分类为痛风，急性期抗炎 + 缓解后降尿酸"},{"when":"v >= 8","level":"high","text":"≥ 8 分：可分类为痛风，启动降尿酸（目标 < 360 μmol/L，痛风石者 < 300）"},{"when":"v >= 4 && v < 8","level":"warn","text":"4–7 分：未分类，需进一步关节超声/DECT 或随访"},{"when":"v < 4","level":"ok","text":"< 4 分：不符合痛风分类"}],"note":"血尿酸在急性期可正常，不应据此排除；标准不适用于已确诊痛风者的分期；降尿酸药物从小剂量开始并预防发作。","refs":["中国高尿酸血症与痛风诊疗指南（2019）","2015 ACR/EULAR Gout Classification Criteria"]},{"id":"rheum_sle_2019_acr_eular","name":"2019 EULAR/ACR 系统性红斑狼疮分类标准","aka":["SLE 2019 分类标准","EULAR/ACR SLE"],"cat":"分类标准","rank":11,"desc":"先满足入围标准，再按 7 个领域加权评分（≥ 10 分）分类为 SLE。","inputs":[{"key":"ana","label":"ANA ≥ 1:80（入围条件）","unit":"","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"hematologic","label":"血液系统（白细胞减少、血小板减少、溶血）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"4 分"}],"required":true},{"key":"renal","label":"肾脏（蛋白尿 > 0.5 g/d、活动性尿沉渣、活检 III/IV 型）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"4–10 分"}],"required":true},{"key":"mucocutaneous","label":"黏膜皮肤（脱发、口腔溃疡、亚急性/盘状皮疹）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"2–6 分"}],"required":true},{"key":"serosal","label":"浆膜炎（胸腔/心包积液、急性心包炎）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":5,"label":"5 分"}],"required":true},{"key":"joint","label":"关节（≥ 2 个关节滑膜炎）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":6,"label":"6 分"}],"required":true},{"key":"neuro","label":"神经精神（癫痫、精神病、脑炎）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":2,"label":"2–5 分"}],"required":true},{"key":"immunologic","label":"免疫学（抗 dsDNA、抗 Sm、抗磷脂抗体等）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":4,"label":"4–6 分"}],"required":true},{"key":"complement","label":"补体（C3/C4 降低）","unit":"","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"3–4 分"}],"required":true}],"formula":"各领域加权分之和（单领域只计最高分），≥ 10 分分类为 SLE","compute":"sum","interpret":[{"when":"ana == 0","level":"ok","text":"ANA 阴性：不满足入围条件，一般不能按本标准分类，考虑其他诊断"},{"when":"ana == 1 && v >= 10","level":"crit","text":"≥ 10 分且 ANA 阳性：可分类为 SLE，评估活动度并启动治疗"},{"when":"ana == 1 && v < 10","level":"warn","text":"< 10 分：不满足分类标准，需随访或考虑其他诊断（如未分化结缔组织病）"}],"note":"入围条件：ANA ≥ 1:80 且至少 1 个临床领域条目；评分按最高分项计（如肾活检 III/IV 型 10 分、抗 dsDNA 6 分）；本表为简化的领域分，正式判定请对照标准表。","refs":["2020 中国系统性红斑狼疮诊疗指南","2019 EULAR/ACR Classification Criteria for SLE"]},{"id":"rheum_essdai","name":"ESSDAI（干燥综合征疾病活动指数）","aka":["ESSDAI","EULAR Sjögren's Syndrome Disease Activity Index"],"cat":"干燥综合征","rank":12,"desc":"按 12 个器官领域加权评估原发性干燥综合征全身活动度。","inputs":[{"key":"constitutional","label":"全身症状（发热/盗汗）","unit":"","type":"select","options":[{"value":0,"label":"无（0）"},{"value":3,"label":"轻度（3）"},{"value":6,"label":"中/重度（6）"}],"required":true},{"key":"lymphadenopathy","label":"淋巴结肿大","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":4,"label":"轻度（4）"},{"value":8,"label":"中/重度（8）"}],"required":true},{"key":"glandular","label":"腺体（腮腺肿大）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":2,"label":"轻度（2）"},{"value":4,"label":"中/重度（4）"}],"required":true},{"key":"articular","label":"关节（滑膜炎）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":2,"label":"轻度（2）"},{"value":4,"label":"中/重度（4）"}],"required":true},{"key":"cutaneous","label":"皮肤（紫癜、溃疡）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":3,"label":"轻度（3）"},{"value":6,"label":"中/重度（6）"}],"required":true},{"key":"pulmonary","label":"肺（间质性肺炎）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":5,"label":"轻度（5）"},{"value":10,"label":"中/重度（10）"}],"required":true},{"key":"renal","label":"肾脏（间质性肾炎等）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":5,"label":"轻度（5）"},{"value":10,"label":"中/重度（10）"}],"required":true},{"key":"muscular","label":"肌肉（肌炎）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":6,"label":"轻/中度（6）"},{"value":12,"label":"重度（12）"}],"required":true},{"key":"pns","label":"周围神经","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":5,"label":"轻度（5）"},{"value":10,"label":"中/重度（10）"}],"required":true},{"key":"cns","label":"中枢神经","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":5,"label":"轻度（5）"},{"value":10,"label":"重度（10）"}],"required":true},{"key":"hematologic","label":"血液（血细胞减少）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":2,"label":"轻度（2）"},{"value":4,"label":"重度（4）"}],"required":true},{"key":"biological","label":"生物学（高球蛋白、低补体、冷球蛋白）","unit":"","type":"select","options":[{"value":0,"label":"0"},{"value":1,"label":"轻度（1）"},{"value":2,"label":"重度（2）"}],"required":true}],"formula":"12 个领域加权分之和（0–123）","compute":"sum","interpret":[{"when":"v >= 14","level":"high","text":"高活动（≥ 14）：考虑糖皮质激素联合免疫抑制剂（羟氯喹、甲氨蝶呤、霉酚酸酯）"},{"when":"v >= 5 && v < 14","level":"warn","text":"中等活动（5–13）：对症治疗 + 免疫调节，3 个月复评"},{"when":"v < 5","level":"ok","text":"低活动（< 5）：以对症治疗（人工泪液、唾液替代）为主"}],"note":"ESSDAI 仅评估系统活动，干眼/口干症状用 ESSPRI 评估；需结合 B 细胞淋巴瘤筛查（腮腺肿大、冷球蛋白）。","refs":["原发性干燥综合征诊疗规范（2023）","Seror R, et al. Ann Rheum Dis 2010 (ESSDAI)"]},{"id":"rheum_vas_pain","name":"视觉模拟疼痛评分（VAS）","aka":["VAS","Visual Analogue Scale"],"cat":"症状评估","rank":13,"desc":"患者主观疼痛/总体状态 0–100 mm 标尺评分及分级。","inputs":[{"key":"vas","label":"疼痛 VAS","unit":"mm (0–100)","type":"number","min":0,"max":100,"step":1,"required":true}],"formula":"0–100 mm 长度标尺（0 = 无痛，100 = 最严重）","compute":"formula_only","algorithm":"v = vas","interpret":[{"when":"v == 0","level":"ok","text":"无疼痛"},{"when":"v <= 30","level":"ok","text":"轻度疼痛（1–30）：非药物与弱镇痛为主"},{"when":"v <= 60","level":"warn","text":"中度疼痛（31–60）：评估 NSAIDs/弱阿片"},{"when":"v > 60","level":"high","text":"重度疼痛（> 60）：强阿片或专科干预，注意疼痛原因"}],"note":"VAS 需用真实标尺；老年或认知障碍者改用 NRS 或 Wong-Baker 面部表情图；与 NRS（0–10）不可直接换算。","refs":["中国疼痛诊疗指南（2017）","IASP Pain Management Guidelines"]},{"id":"rheum_morning_stiffness","name":"晨僵与关节计数（28/44 关节）","aka":["晨僵时间","关节计数"],"cat":"症状评估","rank":14,"desc":"记录晨僵持续时间与关节压痛/肿胀计数，辅助鉴别炎性 versus 机械性关节病。","inputs":[{"key":"morning_minutes","label":"晨僵持续时间","unit":"min","type":"number","min":0,"max":1440,"step":1,"required":true},{"key":"tjc","label":"压痛关节数（28 关节）","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true},{"key":"sjc","label":"肿胀关节数（28 关节）","unit":"个","type":"number","min":0,"max":28,"step":1,"required":true}],"formula":"按晨僵时长与关节计数分类；炎症性 ≥ 30 min 伴关节肿胀","compute":"formula_only","algorithm":"v = morning_minutes","interpret":[{"when":"morning_minutes >= 60 && sjc >= 3","level":"high","text":"晨僵 ≥ 60 min 且 ≥ 3 个关节肿胀：高度提示炎症性关节炎，查 RF、抗 CCP、CRP、ESR"},{"when":"morning_minutes >= 30","level":"warn","text":"晨僵 ≥ 30 min：提示炎症性，需与骨关节炎鉴别"},{"when":"morning_minutes < 30","level":"ok","text":"晨僵 < 30 min：多为机械性关节病（骨关节炎）"}],"note":"28 关节不含踝、中足；晨僵需与长时间不动后僵硬区分；炎性关节炎晨僵常数小时。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","EULAR Recommendations for Management of RA (2022)"]},{"id":"rheum_disease_activity_checklist","name":"类风湿关节炎达标治疗（T2T）随访清单","aka":["T2T","达标治疗"],"cat":"类风湿关节炎","rank":16,"desc":"按治疗目标与实际达标情况提示下一步调整。","inputs":[{"key":"das28","label":"当前 DAS28","unit":"","type":"number","min":0,"max":10,"step":0.01,"required":true},{"key":"target_achieved","label":"已达标（DAS28 < 2.6/2.4）","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"glucocorticoid","label":"长期使用糖皮质激素 > 3 个月","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true},{"key":"months","label":"治疗时长","unit":"月","type":"number","min":0,"max":120,"step":1,"required":true}],"formula":"按 T2T 原则：每 3 个月评估一次，6 个月未达标需调整方案","compute":"formula_only","algorithm":"v = das28","interpret":[{"when":"target_achieved == 1","level":"ok","text":"已达标：维持 csDMARD，激素逐步减量至停用，每 3–6 月复评"},{"when":"months >= 6 && target_achieved == 0","level":"high","text":"6 个月未达标：更换或联合方案（MTX + 生物制剂/JAK 抑制剂）"},{"when":"glucocorticoid == 1","level":"warn","text":"长期激素：按指南尽快减停，评估骨密度与感染风险"}],"note":"MTX 为锚定药物；治疗前筛查乙肝、结核（T-SPOT）、肝肾功能；定期监测血常规与肝功。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","EULAR Recommendations for Management of RA (2022)"]},{"id":"rheum_anti_ccp","name":"类风湿关节炎自身抗体判读（RF / 抗 CCP）","aka":["RF","抗 CCP 抗体"],"cat":"实验室判读","rank":17,"desc":"根据类风湿因子与抗环瓜氨酸肽抗体结果评估 RA 可能性。","inputs":[{"key":"rf","label":"RF","unit":"","type":"select","options":[{"value":0,"label":"阴性/正常"},{"value":1,"label":"低滴度阳性"},{"value":2,"label":"高滴度阳性（≥ 3 倍上限）"}],"required":true},{"key":"ccp","label":"抗 CCP 抗体","unit":"","type":"select","options":[{"value":0,"label":"阴性/正常"},{"value":1,"label":"低滴度阳性"},{"value":2,"label":"高滴度阳性（≥ 3 倍上限）"}],"required":true},{"key":"symptoms","label":"对称性小关节肿痛 ≥ 6 周","unit":"","type":"select","options":[{"value":1,"label":"是"},{"value":0,"label":"否"}],"required":true}],"formula":"抗 CCP 特异性高于 RF；两者高滴度阳性支持 RA","compute":"formula_only","algorithm":"v = rf*2 + ccp*3 + symptoms","interpret":[{"when":"ccp == 2 || (rf == 2 && ccp >= 1)","level":"high","text":"抗 CCP 高滴度阳性：高度支持 RA，常提示侵袭性病程（关节破坏快），应尽早 csDMARD"},{"when":"ccp >= 1 || rf >= 1","level":"warn","text":"抗体阳性：结合关节表现分类；RF 也见于干燥综合征、感染、肝病、老年健康人"},{"when":"v <= 1","level":"ok","text":"RF 与抗 CCP 阴性：血清阴性 RA 占约 20–30%，仍可依临床分类"}],"note":"抗 CCP 对早期 RA 敏感度约 60–70%、特异性 > 95%；RF 敏感性高特异性低；均不能单独诊断。","refs":["中国类风湿关节炎诊疗指南（2018/2023）","2010 ACR/EULAR RA Classification Criteria"]},{"id":"rheum_renal_lupus","name":"狼疮肾炎分型与蛋白尿判读","aka":["LN ISN/RPS 分型","狼疮肾炎"],"cat":"系统性红斑狼疮","rank":18,"desc":"按 ISN/RPS 病理分型与蛋白尿水平判定 LN 活动与治疗强度。","inputs":[{"key":"class","label":"病理分型","unit":"","type":"select","options":[{"value":1,"label":"Ⅰ/Ⅱ 型（系膜增生）"},{"value":2,"label":"Ⅲ 型（局灶增生）"},{"value":3,"label":"Ⅳ 型（弥漫增生）"},{"value":4,"label":"Ⅴ 型（膜性）"},{"value":5,"label":"Ⅵ 型（硬化型）"}],"required":true},{"key":"proteinuria","label":"24 h 尿蛋白","unit":"g","type":"number","min":0,"max":30,"step":0.1,"required":true},{"key":"egfr","label":"eGFR","unit":"mL/min/1.73m²","type":"number","min":1,"max":200,"step":1,"required":false},{"key":"activity","label":"活动性尿沉渣（红细胞管型/血尿）","unit":"","type":"select","options":[{"value":1,"label":"有"},{"value":0,"label":"无"}],"required":true}],"formula":"按 ISN/RPS 分型与蛋白尿、活动性尿沉渣综合判断","compute":"formula_only","algorithm":"v = proteinuria","interpret":[{"when":"class == 2 || class == 3","level":"crit","text":"Ⅲ/Ⅳ 型及Ⅴ+Ⅲ/Ⅳ 型：活动性增殖性（或合并膜性）LN，糖皮质激素 + 霉酚酸酯/环磷酰胺（诱导），后续维持"},{"when":"class == 1","level":"warn","text":"Ⅰ/Ⅱ 型：按蛋白尿与活动情况对症治疗"},{"when":"class == 4","level":"high","text":"Ⅴ 型（膜性）：激素 + 钙调磷酸酶抑制剂/霉酚酸酯"},{"when":"class == 5","level":"crit","text":"Ⅵ 型：硬化型，多为不可逆肾衰，评估透析与移植"},{"when":"proteinuria >= 3.5","level":"high","text":"肾病范围蛋白尿（≥ 3.5 g/d）：ACEI/ARB + 利尿，注意血栓与感染"}],"note":"需肾活检分期；2018 修订加入活动性/慢性病变评分（NIH 活动指数）；目标为 6 个月蛋白尿减少 ≥ 50%、12 个月 < 0.5–0.7 g/g。","refs":["2020 中国系统性红斑狼疮诊疗指南","KDIGO 2021 Glomerular Diseases Guideline (LN)"]}]},"uro":{"items":[{"id":"ipss","name":"IPSS / AUA-SI 国际前列腺症状评分","aka":["International Prostate Symptom Score","AUA Symptom Index"],"cat":"前列腺症状与性功能","desc":"7 项下尿路症状评分（0–35）评估良性前列腺增生（BPH）症状严重度，是中老年男性门诊筛查核心工具。","inputs":[{"key":"incomplete","label":"过去 1 个月：排尿后感觉膀胱未排空","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"frequency","label":"排尿后 2 小时内又需排尿","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"intermittency","label":"排尿中断、尿流不连续","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"urgency","label":"尿急（难以憋尿）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"weak_stream","label":"尿线细弱","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"straining","label":"需要用力才能开始排尿","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"nocturia","label":"夜间需起床排尿次数","type":"select","options":[{"value":0,"label":"0 次"},{"value":1,"label":"1 次"},{"value":2,"label":"2 次"},{"value":3,"label":"3 次"},{"value":4,"label":"4 次"},{"value":5,"label":"≥5 次"}],"required":true}],"formula":"IPSS = 7 项之和（每项 0–5 分），总分 0–35","compute":"sum","interpret":[{"when":"v <= 7","level":"ok","text":"0–7 分：轻度症状，可观察等待 + 生活方式调整（睡前限水、减少咖啡因/酒精）"},{"when":"v <= 19","level":"warn","text":"8–19 分：中度症状，建议 α 受体阻滞剂，必要时联合 5α 还原酶抑制剂（前列腺 >40 mL）"},{"when":"v >= 20","level":"high","text":"20–35 分：重度症状，评估药物联合治疗、TURP/HoLEP/激光等手术指征（残余尿 >50–100 mL、反复尿潴留、肾功能损害）"}],"note":"IPSS ≥8 分或生活质量受明显影响者建议治疗；急性尿潴留、反复血尿、膀胱结石、肾功能不全为绝对手术指征。需结合 QoL 评分与尿流率。","refs":["Barry MJ, et al. J Urol 1992;148:1547-1557（IPSS/AUA-SI 原版）","中华医学会泌尿外科学分会：良性前列腺增生诊断治疗指南（2021 版）","中国泌尿外科和男科疾病诊断治疗指南（2022 版）"],"rank":1},{"id":"ipss_qol","name":"IPSS 生活质量评分（QoL）","aka":["Quality of Life due to Urinary Symptoms","QoL 指数"],"cat":"前列腺症状与性功能","desc":"以单一 0–6 分问题评估患者对当前排尿症状的主观困扰程度，是治疗决策的重要依据。","inputs":[{"key":"qol","label":"如果余生都将维持现在的排尿状况，您觉得如何","type":"select","options":[{"value":0,"label":"非常满意"},{"value":1,"label":"满意"},{"value":2,"label":"基本满意"},{"value":3,"label":"一般"},{"value":4,"label":"不满意"},{"value":5,"label":"苦恼"},{"value":6,"label":"非常痛苦"}],"required":true}],"formula":"QoL 0–6 分：0 = 非常满意，6 = 非常痛苦","compute":"sum","interpret":[{"when":"qol <= 1","level":"ok","text":"0–1 分：对症状满意，可观察等待"},{"when":"qol <= 3","level":"warn","text":"2–3 分：一般/不满意，结合 IPSS 考虑药物或微创治疗"},{"when":"qol >= 4","level":"high","text":"4–6 分：明显困扰，即使 IPSS 轻中度也应积极治疗（药物或手术）"}],"note":"QoL ≥4 分常作为开始治疗的阈值；IPSS 与 QoL 同时升高需排除神经源性膀胱等。","refs":["中华医学会泌尿外科学分会：良性前列腺增生诊断治疗指南（2021 版）","中国泌尿外科和男科疾病诊断治疗指南（2022 版）"],"rank":2},{"id":"iief5","name":"国际勃起功能指数（IIEF-5）","aka":["International Index of Erectile Function-5","SHIM"],"cat":"前列腺症状与性功能","desc":"5 项问卷（总分 5–25）评估勃起功能障碍（ED）的严重程度，也用于 TURP 等手术前后性功能评估。","inputs":[{"key":"confidence","label":"对勃起有信心的程度","type":"select","options":[{"value":1,"label":"很低"},{"value":2,"label":"低"},{"value":3,"label":"中等"},{"value":4,"label":"高"},{"value":5,"label":"很高"}],"required":true},{"key":"hardness","label":"受到刺激后阴茎硬度足以插入","type":"select","options":[{"value":1,"label":"几乎不能"},{"value":2,"label":"少数时候"},{"value":3,"label":"约一半时候"},{"value":4,"label":"多数时候"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"maintain","label":"插入后能维持勃起","type":"select","options":[{"value":1,"label":"几乎不能"},{"value":2,"label":"少数时候"},{"value":3,"label":"约一半时候"},{"value":4,"label":"多数时候"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"complete","label":"能完成性交","type":"select","options":[{"value":1,"label":"几乎不能"},{"value":2,"label":"少数时候"},{"value":3,"label":"约一半时候"},{"value":4,"label":"多数时候"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"satisfaction","label":"性交时满足感","type":"select","options":[{"value":1,"label":"几乎没有"},{"value":2,"label":"少数时候"},{"value":3,"label":"约一半时候"},{"value":4,"label":"多数时候"},{"value":5,"label":"几乎总有"}],"required":true}],"formula":"IIEF-5 = 5 项各 1–5 分之和，总分 5–25","compute":"sum","interpret":[{"when":"v >= 22","level":"ok","text":"22–25 分：无勃起功能障碍，定期筛查"},{"when":"v >= 17","level":"warn","text":"17–21 分：轻度 ED，生活方式干预（戒烟、运动、控制血糖血压）+ PDE5 抑制剂按需"},{"when":"v >= 12","level":"warn","text":"12–16 分：轻中度 ED，PDE5 抑制剂规律/按需，检查睾酮与血管危险因素"},{"when":"v >= 8","level":"high","text":"8–11 分：中度 ED，联合治疗，评估前列腺根治术/放疗后神经血管束损伤"},{"when":"v <= 7","level":"crit","text":"5–7 分：重度 ED，PDE5 抑制剂效果差，考虑真空泵、海绵体内注射或阴茎假体"}],"note":"ED 常为心血管疾病早期标志：45 岁以上 ED 患者建议评估血糖、血脂、血压与睾酮。服用硝酸酯类者为 PDE5 抑制剂禁忌。","refs":["Rosen RC, et al. Int J Impot Res 1999;11:319-326（IIEF-5 原版）","中华医学会男科学分会：勃起功能障碍诊断与治疗指南（2022）"],"rank":3},{"id":"nih_cpsi","name":"NIH-CPSI 慢性前列腺炎症状指数","aka":["NIH Chronic Prostatitis Symptom Index"],"cat":"前列腺症状与性功能","desc":"评估慢性前列腺炎/慢性盆腔疼痛综合征（CP/CPPS）的疼痛、排尿与生活质量，总分 0–43。","inputs":[{"key":"pain_site","label":"过去 1 周疼痛或不适的部位（按原始计分）","type":"select","options":[{"value":1,"label":"会阴部或仅在排尿时疼痛"},{"value":2,"label":"睾丸、耻骨上或膀胱区"},{"value":3,"label":"阴茎头部、下腹或会阴多处（≥2 处）"}],"required":true},{"key":"pain_freq","label":"疼痛或不适的频率","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"很少"},{"value":2,"label":"偶尔"},{"value":3,"label":"经常"},{"value":4,"label":"很频繁"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"pain_severity","label":"疼痛或不适的严重程度","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"轻微"},{"value":2,"label":"轻度"},{"value":3,"label":"中度"},{"value":4,"label":"重度"}],"required":true},{"key":"voiding","label":"排尿不尽感或尿频的评分","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"少于 1/5 次"},{"value":2,"label":"少于 1/2 次"},{"value":3,"label":"约 1/2 次"},{"value":4,"label":"多于 1/2 次"},{"value":5,"label":"几乎总是"}],"required":true},{"key":"qol1","label":"对日常生活的影响","type":"select","options":[{"value":0,"label":"无影响"},{"value":1,"label":"仅轻微"},{"value":2,"label":"有一些"},{"value":3,"label":"明显"},{"value":4,"label":"很大"}],"required":true},{"key":"qol2","label":"对工作的影响","type":"select","options":[{"value":0,"label":"无影响"},{"value":1,"label":"仅轻微"},{"value":2,"label":"有一些"},{"value":3,"label":"明显"},{"value":4,"label":"很大"}],"required":true}],"formula":"NIH-CPSI 疼痛分（部位 0–3、频率 0–5、严重度 0–4）+ 排尿分（0–10）+ 生活质量分（0–12，2 题合计 0–8 在简化版）+ 总分 0–43","compute":"formula_only","algorithm":"pain = pain_site*?  # 实际计分：疼痛部位 0–3 分（单部位1、多部位>1）、频率0–5、严重度0–4\nuro = voiding + incomplete*?（0–10，本表用单题近似）\nqol = qol1 + qol2（原始 0–12）\nv = pain + uro + qol  # 0–43","interpret":[{"when":"v <= 9","level":"ok","text":"0–9 分：轻度症状，以生活方式调整与随访为主"},{"when":"v <= 18","level":"warn","text":"10–18 分：中度症状，α 受体阻滞剂 + 抗炎/物理治疗，复查 NIH-CPSI"},{"when":"v >= 19","level":"high","text":"19–43 分：重度症状，联合用药（α 阻滞剂 + 抗菌药仅用于细菌性）与精神心理评估，必要时神经调控"}],"note":"本条目输入为简化版（缺 1 项排尿题的细项），v 与标准 0–43 分不完全等值；NIH-CPSI 亦用于 UPOINT 表型导向治疗评估。","refs":["Litwin MS, et al. J Urol 1999;162:369-375（NIH-CPSI 原版）","中华医学会泌尿外科学分会：前列腺炎诊断治疗指南（2021 版）","中国泌尿外科和男科疾病诊断治疗指南（2022 版）"],"rank":4},{"id":"psad","name":"PSA 密度（PSAD）","aka":["PSA Density"],"cat":"前列腺癌风险","desc":"血清总 PSA 除以前列腺体积，校正前列腺体积对 PSA 的影响，提高前列腺穿刺阳性率判断。","inputs":[{"key":"psa","label":"血清总 PSA","unit":"ng/mL","type":"number","min":0,"max":200,"step":0.01,"required":true},{"key":"volume","label":"前列腺体积（经直肠超声/MRI）","unit":"mL","type":"number","min":5,"max":300,"step":0.1,"required":true}],"formula":"PSAD = PSA（ng/mL）/ 前列腺体积（mL）","compute":"formula_only","algorithm":"v = round(psa / volume, 3)","interpret":[{"when":"v < 0.15","level":"ok","text":"PSAD <0.15：前列腺增生可能性大，若无异常 DRE 可随访 PSA"},{"when":"v <= 0.20","level":"warn","text":"PSAD 0.15–0.20：可疑，结合 DRE、MRI（PI-RADS）决定是否穿刺"},{"when":"v > 0.20","level":"high","text":"PSAD >0.20：穿刺阳性与临床显著癌风险增加，建议 mpMRI 靶向穿刺"}],"note":"PSA 4–10 ng/mL 灰区时 PSAD 价值最大；体积测量以 TRUS 计算（0.52×三径乘积）或 MRI 为准。","refs":["中华医学会泌尿外科学分会：中国前列腺癌筛查与早诊早治指南（2022）","中国抗癌协会泌尿男生殖系肿瘤专业委员会：前列腺穿刺中国专家共识（2021）","EAU 前列腺癌指南（2023）"],"rank":1},{"id":"d_amico","name":"D'Amico 前列腺癌风险分层","aka":["D'Amico Risk Groups"],"cat":"前列腺癌风险","desc":"按 PSA、Gleason 评分与临床分期将局限性前列腺癌分为低、中、高危，决定治疗方式（根治/放疗/主动监测）。","inputs":[{"key":"psa","label":"PSA","type":"select","options":[{"value":1,"label":"<10 ng/mL"},{"value":2,"label":"10–20 ng/mL"},{"value":3,"label":">20 ng/mL"}],"required":true},{"key":"gleason","label":"Gleason 评分 / ISUP 分级组","type":"select","options":[{"value":1,"label":"Gleason ≤6 或 ISUP 1 级"},{"value":2,"label":"Gleason 7 或 ISUP 2–3 级"},{"value":3,"label":"Gleason ≥8 即 ISUP 4–5 级"}],"required":true},{"key":"stage","label":"临床分期（T 分期）","type":"select","options":[{"value":1,"label":"T1–T2a"},{"value":2,"label":"T2b–T2c"},{"value":3,"label":"T3a 及以上"}],"required":true}],"formula":"低危 = PSA<10 且 Gleason≤6 且 T1–T2a；中危 = 上述任一升高但未达高危；高危 = PSA>20 或 Gleason≥8 或 T3a 及以上","compute":"formula_only","algorithm":"hi = (psa == 3 || gleason == 3 || stage == 3)\nlo = (psa == 1 && gleason == 1 && stage == 1)\nv = 3 if hi else (1 if lo else 2)  # 危险组","interpret":[{"when":"psa == 3 || gleason == 3 || stage == 3","level":"crit","text":"高危：根治性前列腺切除或放疗 + 长期 ADT 2–3 年，多学科讨论；术后辅助放疗指征需评估"},{"when":"psa == 1 && gleason == 1 && stage == 1","level":"ok","text":"低危：主动监测为首选（或根治/放疗），PSA 每 3–6 个月复查"},{"when":"psa >= 1","level":"warn","text":"中危：主动监测部分患者可选，多数建议根治性治疗（手术或放疗 ± ADT 4–6 个月）"}],"note":"本输入三者取最高危险因素；如有影像学（PSMA-PET/MRI）提示 N1/M1 则为转移性，不适用本分层。","refs":["D'Amico AV, et al. JAMA 1998;280:969-974（D'Amico 分层原版）","中华医学会泌尿外科学分会：中国前列腺癌诊断治疗指南（2022 版）","CSCO 前列腺癌诊疗指南（2023）"],"rank":2},{"id":"gleason_isup","name":"Gleason 评分与 ISUP 分级组","aka":["Gleason Score","ISUP Grade Group"],"cat":"前列腺癌风险","desc":"根据穿刺病理的主要与次要腺体结构评分，换算 ISUP 分级组（1–5），是前列腺癌预后与治疗方案的核心指标。","inputs":[{"key":"primary","label":"主要 Gleason 评分（占比最高）","type":"select","options":[{"value":1,"label":"3 分"},{"value":2,"label":"4 分"},{"value":3,"label":"5 分"},{"value":0,"label":"（无）"}],"required":true},{"key":"secondary","label":"次要 Gleason 评分","type":"select","options":[{"value":1,"label":"3 分"},{"value":2,"label":"4 分"},{"value":3,"label":"5 分"}],"required":true}],"formula":"Gleason 评分 = 主要 + 次要分级（各 3–5 分），总分 6–10；ISUP 分级组：1 = GS ≤6（3+3）；2 = 3+4；3 = 4+3；4 = 8（4+4、3+5、5+3）；5 = 9–10（4+5、5+4、5+5）","compute":"formula_only","algorithm":"total = primary + secondary\nif total <= 6: grade = 1\nelif primary == 1 and secondary == 2: grade = 2   # 3+4\nelif primary == 2 and secondary == 1: grade = 3   # 4+3\nelif total == 8: grade = 4\nelse: grade = 5","interpret":[{"when":"primary <= 1 && secondary <= 1","level":"ok","text":"Gleason 6 / ISUP 1 级：低级别，主动监测可考虑"},{"when":"primary == 1 && secondary == 2","level":"warn","text":"Gleason 3+4=7 / ISUP 2 级：中危（低中危可不需淋巴结清扫）"},{"when":"primary == 2 && secondary == 1","level":"warn","text":"Gleason 4+3=7 / ISUP 3 级：中高危，注意切缘与囊外侵犯"},{"when":"primary == 2 && secondary == 2","level":"high","text":"Gleason 4+4=8 / ISUP 4 级：高危，考虑扩大淋巴结清扫与多学科治疗"},{"when":"primary == 3 || secondary == 3","level":"crit","text":"Gleason 9–10 / ISUP 5 级：极高危，易转移，需系统治疗（ADT + 新型内分泌/化疗）讨论"}],"note":"当穿刺标本有多个分化程度时，取最高 Gleason 评分（不论占比）作为最终评分；Gleason 1–2 分已不再使用。","refs":["Epstein JI, et al. Am J Surg Pathol 2016;40:244-252（ISUP 2014 分级组）","中华医学会病理学分会：前列腺癌病理诊断规范（2020）","中国前列腺癌诊疗指南（2022 版）"],"rank":3},{"id":"renal_nephrometry","name":"RENAL 肾脏肿瘤测量评分","aka":["RENAL Nephrometry Score","RENAL 评分"],"cat":"肾肿瘤与结石","desc":"用影像学的 5 项指标（R 最大径、E 外生比例、N 邻近肾窦、A 前/后位、L 与肾极线关系）量化肾肿瘤复杂度，指导部分/根治性肾切除选择。","inputs":[{"key":"r","label":"R：肿瘤最大径","type":"select","options":[{"value":1,"label":"≤4 cm"},{"value":2,"label":"4–7 cm"},{"value":3,"label":"≥7 cm"}],"required":true},{"key":"e","label":"E：外生/内生比例","type":"select","options":[{"value":1,"label":"≥50% 外生"},{"value":2,"label":"<50% 外生"},{"value":3,"label":"完全内生"}],"required":true},{"key":"n","label":"N：距肾窦集合系统距离","type":"select","options":[{"value":1,"label":"≥7 mm"},{"value":2,"label":"4–7 mm"},{"value":3,"label":"≤4 mm"}],"required":true},{"key":"a","label":"A：前/后位","type":"select","options":[{"value":1,"label":"前方"},{"value":2,"label":"后方"},{"value":3,"label":"无法确定/中线"}],"required":true},{"key":"l","label":"L：与肾极线关系","type":"select","options":[{"value":1,"label":"完全位于上/下极线外"},{"value":2,"label":"跨越极线 <50%"},{"value":3,"label":"跨越极线 ≥50% 或位于两极之间"}],"required":true}],"formula":"RENAL = R（1–3）+ E（1–3）+ N（1–3）+ A（1–3，多不计入总分）+ L（1–3）；总分（不含 A）3–12","compute":"sum","algorithm":"v = r + e + n + l   # 不含 A（前后位仅用于手术入路规划）\n后缀 = a == 1 ? 'a' : (a == 2 ? 'p' : 'x')","interpret":[{"when":"v <= 6","level":"ok","text":"4–6 分（低复杂度）：部分肾切除（保留肾单位）为首选，可腹腔镜/机器人"},{"when":"v <= 9","level":"warn","text":"7–9 分（中等复杂度）：部分切除仍可行但难度增加，需评估热缺血时间（目标 <25 分钟）"},{"when":"v >= 10","level":"high","text":"10–12 分（高复杂度）：根治性肾切除或开放/机器人部分切除，需个体化评估与 MDT"}],"note":"RENAL 仅评估解剖复杂度，需结合肾功能（eGFR）、对侧肾功能与患者体能；PADUA 评分（10 项）为另一常用工具。","refs":["Kutikov A, Uzzo RG. J Urol 2009;182:844-853（RENAL 评分原版）","中华医学会泌尿外科学分会：中国肾细胞癌诊断治疗指南（2019 版）","中国泌尿外科和男科疾病诊断治疗指南（2022 版）"],"rank":1},{"id":"padua","name":"PADUA 肾脏肿瘤评分","aka":["Preoperative Aspects and Dimensions Used for an Anatomical Classification"],"cat":"肾肿瘤与结石","desc":"用 10 项解剖参数评估肾肿瘤部分切除的技术难度（6–14 分），与 RENAL 互补。","inputs":[{"key":"tumor_size","label":"肿瘤大小","type":"select","options":[{"value":1,"label":"≤4 cm"},{"value":2,"label":"4.1–7 cm"},{"value":3,"label":">7 cm"}],"required":true},{"key":"exophytic","label":"外生比例","type":"select","options":[{"value":1,"label":"≥50% 外生"},{"value":2,"label":"<50% 外生"},{"value":3,"label":"完全内生"}],"required":true},{"key":"parenchymal_depth","label":"与肾窦关系（肾实质深度）","type":"select","options":[{"value":1,"label":"≤50% 占据肾实质"},{"value":2,"label":">50% 占据肾实质"},{"value":3,"label":"累及肾窦"}],"required":true},{"key":"renal_margin","label":"肿瘤边界（肾外侧缘）","type":"select","options":[{"value":1,"label":"外侧缘"},{"value":2,"label":"内侧缘"},{"value":3,"label":"内外侧缘均有"}],"required":true},{"key":"sinus_line","label":"与肾窦线关系","type":"select","options":[{"value":1,"label":"未触及肾窦线"},{"value":2,"label":"触及肾窦线"},{"value":3,"label":"越过肾窦线"}],"required":true},{"key":"collecting_system","label":"集合系统受累","type":"select","options":[{"value":1,"label":"未累及"},{"value":2,"label":"累及"}],"required":true},{"key":"polar_line","label":"与肾极线关系","type":"select","options":[{"value":1,"label":"位于极线外（上下极）"},{"value":2,"label":"跨越极线"},{"value":3,"label":"位于肾中部（两极线之间）"}],"required":true}],"formula":"PADUA = 肿瘤大小 1–3 + 外生比例 1–3 + 与肾窦关系 1–3 + 肾内外侧缘 1–3 + 肾窦线 1–2 + 集合系统 1–2 + 肾极线 1–3；总分 7–19 分（原版）","compute":"sum","interpret":[{"when":"v <= 8","level":"ok","text":"≤8 分：低复杂度，部分肾切除（保留肾单位）为宜"},{"when":"v <= 10","level":"warn","text":"9–10 分：中等复杂度，需选择经验丰富的术者与恰当入路"},{"when":"v >= 11","level":"high","text":"≥11 分：高复杂度，部分切除难度大，需评估根治性切除或开放手术"}],"note":"本表为简化版输入，实际 PADUA 各项分值（1–3 分）按 Ficarra 原表；用于手术规划时建议同时列出 RENAL 评分。","refs":["Ficarra V, et al. Eur Urol 2009;56:618-623（PADUA 原版）","中华医学会泌尿外科学分会：保留肾单位手术中国专家共识（2021）"],"rank":2},{"id":"guy_grade","name":"Guy's 肾结石评分（Guy's Stone Score）","aka":["Guy's Stone Score","GSS"],"cat":"肾肿瘤与结石","desc":"基于 CT 影像的 4 级评分预测经皮肾镜取石（PCNL）的结石清除率，指导术式选择。","inputs":[],"compute":"formula_only","levels":[{"label":"GSS Ⅰ级","criteria":"单发结石位于肾盂或中/下极肾盏，解剖结构正常，或结石为单发、肾盂结石","level":"ok"},{"label":"GSS Ⅱ级","criteria":"结石位于上极肾盏，或肾盂结石伴解剖异常（如肾盂输尿管连接部梗阻）","level":"warn"},{"label":"GSS Ⅲ级","criteria":"多发结石（≥2 个）位于肾盏，或结石位于肾盏憩室，或部分鹿角形结石","level":"high"},{"label":"GSS Ⅳ级","criteria":"完全鹿角形结石、脊柱畸形、马蹄肾或其他复杂解剖异常","level":"crit"}],"note":"Ⅰ级结石清除率约 90%，Ⅳ级约 40%–50%，Ⅳ级常需联合多通道 PCNL 或分期手术。需结合 S.T.O.N.E. 评分。","refs":["Thomas K, et al. J Urol 2011;186:130-134（Guy's 评分原版）","中华医学会泌尿外科学分会：中国泌尿系结石诊疗指南（2021 版）"],"rank":3},{"id":"eau_stone_risk","name":"EAU 尿路结石复发风险评估","aka":["EAU urolithiasis recurrence risk","结石危险分层"],"cat":"肾肿瘤与结石","desc":"按结石成分、复发史、合并症等将患者分为低/中/高危复发，决定代谢检查与随访强度。","inputs":[{"key":"recurrence","label":"复发情况","type":"select","options":[{"value":0,"label":"初发"},{"value":1,"label":"复发（同一患者再次出现结石）"}],"required":true},{"key":"composition","label":"结石成分（高危成分）","type":"select","options":[{"value":0,"label":"未检出高危成分（草酸钙/尿酸/碳酸钙）"},{"value":1,"label":"感染性结石（磷酸铵镁/碳酸磷灰石）"},{"value":2,"label":"胱氨酸结石"}],"required":true,"hint":"感染性与胱氨酸结石均属高危成分"},{"key":"comorbidity","label":"合并症","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"肥胖、糖尿病、骨质疏松、痛风、肾小管酸中毒、甲状旁腺功能亢进、肠切除/肠旁路、多囊肾等"}],"required":true},{"key":"family","label":"结石家族史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"EAU 分层：低危 = 初发 + 非感染性结石 + 无合并症/家族史；中危 = 1 项危险因素（复发、家族史或合并症）；高危 = 感染性/胱氨酸结石、合并代谢病、多次复发","compute":"formula_only","algorithm":"risk_pts = recurrence + comorbidity + family\nif composition >= 1: v = 2      # 感染性/胱氨酸结石：高危\nelif risk_pts >= 2: v = 2       # 多项复发危险因素：高危\nelif risk_pts == 1: v = 1       # 中危\nelse: v = 0                     # 低危","interpret":[{"when":"v == 0","level":"ok","text":"低危：基础（血液+尿液）检查 + 饮水量 2.5 L/d 与饮食调整，每年复查"},{"when":"v == 1","level":"warn","text":"中危：进一步代谢评估（24 小时尿、结石成分分析），生活方式干预，结石每年超声随访"},{"when":"v >= 2","level":"high","text":"高危：完整代谢评估，针对性药物（枸橼酸盐、噻嗪类、别嘌醇等需按成分），并对合并症治疗"}],"note":"结石成分分析是分层的关键；尿酸结石可碱化尿液溶石，感染性结石需控制感染并行结石清除。","refs":["EAU Guidelines on Urolithiasis (2023)","中华医学会泌尿外科学分会：中国泌尿系结石诊疗指南（2021 版）","中国泌尿外科和男科疾病诊断治疗指南（2022 版）"],"rank":4},{"id":"qsofa","name":"qSOFA 快速脓毒症筛查（尿源性）","aka":["Quick SOFA","qSOFA"],"cat":"感染与功能","desc":"输入感染（如急性肾盂肾炎、梗阻性化脓性肾盂肾炎）患者出现 RR ≥22、GCS <15、SBP ≤100 等 3 项即提示脓毒症，需紧急处理。","inputs":[{"key":"rr","label":"呼吸频率 ≥22 次/分","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"gcs","label":"意识改变（GCS <15）","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"sbp","label":"收缩压 ≤100 mmHg","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true}],"formula":"qSOFA = 呼吸频率 ≥22 次/分（1）+ 意识改变（1）+ 收缩压 ≤100 mmHg（1），总分 0–3","compute":"sum","interpret":[{"when":"v <= 1","level":"warn","text":"0–1 分：暂不支持脓毒症，但尿源性感染仍需血/尿培养与影像学（CT）排除梗阻"},{"when":"v >= 2","level":"crit","text":"≥2 分：脓毒症高危，立即启动 3 小时集束化（血培养、乳酸、广谱抗生素）并寻找梗阻部位"}],"note":"尿源性脓毒症常伴梗阻性肾盂肾炎，需在抗感染同时尽快解除梗阻（经皮肾穿刺造瘘/输尿管支架引流），否则感染难以控制。GCS 14 分计 1 分。","refs":["Singer M, et al. JAMA 2016;315:801-810（Sepsis-3）","中国脓毒症/脓毒性休克急诊治疗指南（2018）","尿源性脓毒症急诊诊治中国专家共识（2022）"],"rank":1},{"id":"asua_uui","name":"AUA 尿失禁症状评估与分型要点","aka":["Urinary Incontinence assessment","尿失禁分型评估"],"cat":"感染与功能","desc":"依据尿失禁症状特征（压力/急迫/混合/充盈性）与尿动力学线索，确定类型与初步处理方向。","inputs":[{"key":"type","label":"症状类型","type":"select","options":[{"value":1,"label":"压力性（咳嗽/打喷嚏/运动时漏尿）"},{"value":2,"label":"急迫性（尿急后不自主漏尿，伴尿频）"},{"value":3,"label":"混合性"},{"value":4,"label":"充盈性（排尿困难、排尿不尽、滴沥）"},{"value":5,"label":"其他（瘘、神经源性）"}],"required":true},{"key":"female","label":"性别","type":"select","options":[{"value":0,"label":"女性"},{"value":1,"label":"男性"}],"required":true},{"key":"pvd","label":"盆腔器官脱垂/前列腺手术史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"分型：压力性尿失禁（SUI）、急迫性（UUI）、混合性（MUI）、充盈性、神经源性/瘘性；评估尿垫试验、尿动力学（复杂病例）、残余尿与膀胱镜","compute":"formula_only","algorithm":"v = type","interpret":[{"when":"type == 1","level":"warn","text":"压力性尿失禁：女性首选盆底肌训练 8–12 周；无效可考虑尿道中段吊带术或阴道托；男性注意前列腺术后括约肌损伤"},{"when":"type == 2","level":"high","text":"急迫性尿失禁：膀胱训练 + 抗胆碱能/β3 受体激动剂；排除膀胱过度活动症、感染、膀胱结石、神经因素"},{"when":"type == 3","level":"high","text":"混合性：先处理症状更明显者，建议尿动力学检查后再选择治疗"},{"when":"type == 4","level":"crit","text":"充盈性：查残余尿与前列腺体积、评估逼尿肌收缩力，必要时导尿，老年男性多为 BPH 所致"},{"when":"type >= 5","level":"crit","text":"其他类型：需膀胱镜与尿动力学明确（瘘需手术修补，神经源性需间歇导尿 + 抗胆碱药）"}],"note":"本条目为分型要点提示，不做自动计算；尿失禁评估需记录漏尿频率、尿垫使用量（1 小时尿垫试验）与残余尿。","refs":["中国康复医学会：女性压力性尿失禁诊断和治疗指南（2017）","中华医学会泌尿外科学分会：膀胱过度活动症诊断治疗指南（2021 版）","AUA/SUFU Guideline on Urinary Incontinence in Adults（2023）"],"rank":2},{"id":"prostate_psa_volume","name":"前列腺体积与 PSA 判读","aka":["前列腺体积估算","PSA 体积判读"],"cat":"前列腺症状与性功能","desc":"以经腹/经直肠超声三径估算前列腺体积，并按年龄调整的 PSA 参考值判断是否需要进一步检查。","inputs":[{"key":"ap","label":"前后径（H）","unit":"mm","type":"number","min":10,"max":100,"step":0.1,"required":true},{"key":"trans","label":"左右径（W）","unit":"mm","type":"number","min":10,"max":120,"step":0.1,"required":true},{"key":"cc","label":"上下径（L）","unit":"mm","type":"number","min":10,"max":120,"step":0.1,"required":true},{"key":"psa","label":"血清 PSA","unit":"ng/mL","type":"number","min":0,"max":200,"step":0.01,"required":false},{"key":"age","label":"年龄","unit":"岁","type":"number","min":40,"max":100,"step":1,"required":true}],"formula":"前列腺体积 = 0.52 × H × W × L（cm³）；体积 >30–40 mL 视为增大；PSA 参考上限随年龄：40–49 岁 2.5、50–59 岁 3.5、60–79 岁 4.5 ng/mL","compute":"formula_only","algorithm":"v = round(0.52 * (ap/10) * (trans/10) * (cc/10), 1)  # mL\npsa_cut = age < 50 ? 2.5 : (age < 60 ? 3.5 : 4.5)\n体积 >40 mL 时 PSA 可升高约 0.2 ng/mL 每 10 mL，见 note","interpret":[{"when":"v < 30","level":"ok","text":"<30 mL：体积正常，PSA 轻度升高时需警惕前列腺癌，建议直肠指检与 mpMRI"},{"when":"v <= 40","level":"warn","text":"30–40 mL：轻度增大（BPH），结合 IPSS 与尿流率；PSA 高于年龄上限者建议 MRI/穿刺"},{"when":"v > 40","level":"high","text":">40 mL：明显增生，BPH 用药可选 5α 还原酶抑制剂（可降低 PSA 约 50%，解读 PSA 需乘 2）"}],"note":"TRUS 测量以 0.52×三径乘积；增大的前列腺会使 PSA 升高（增生组织贡献约 0.067 ng/mL/g），故 PSA 升高需结合体积与游离/总 PSA 比值。","refs":["中华医学会泌尿外科学分会：良性前列腺增生诊断治疗指南（2021 版）","中国前列腺癌筛查与早诊早治指南（2022）"],"rank":5}]},"vascular":{"items":[{"id":"vasc_rutherford_cl","name":"Rutherford 下肢缺血临床分级","aka":["Rutherford Classification","Rutherford category"],"cat":"动脉缺血分级","rank":1,"desc":"按下肢缺血严重程度分为 0–6 级（急性/慢性通用），是外周动脉疾病（PAD）标准化记录与治疗决策的基础。","inputs":[],"compute":"formula_only","levels":[{"label":"0 级（无症状）","criteria":"运动试验正常，无血流动力学显著的缺血症状","level":"ok"},{"label":"1 级（轻度间歇性跛行）","criteria":"平地行走 > 500 m 或运动试验后出现症状，踝压 > 50 mmHg","level":"ok"},{"label":"2 级（中度间歇性跛行）","criteria":"平地行走 100–500 m 出现症状","level":"warn"},{"label":"3 级（重度间歇性跛行）","criteria":"平地行走 < 100 m 出现症状，静息踝压多 < 50 mmHg","level":"warn"},{"label":"4 级（静息痛）","criteria":"静息性缺血性疼痛，踝压常 < 40 mmHg、趾压 < 30 mmHg","level":"high"},{"label":"5 级（组织缺损）","criteria":"轻微组织缺损（足趾/足跟溃疡，无骨暴露），合并静息痛","level":"high"},{"label":"6 级（重大组织缺损）","criteria":"大面积组织缺损/坏疽，可能需截肢，常伴感染","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"0–3 级为跛行期，以运动康复与药物治疗为主；4–6 级属 CLTI，需尽快评估血运重建（旁路/腔内）与保肢方案"}],"note":"4–6 级为慢性肢体威胁性缺血（CLTI）；急性肢体缺血（6 小时至 14 天内）另用 Rutherford 急性分级（Ⅰ 可行走 / Ⅱa 边缘性 / Ⅱb 立即威胁 / Ⅲ 不可逆），Ⅱb 与 Ⅲ 需紧急血运重建。","refs":["2019 中国下肢动脉硬化闭塞症诊治指南","2024 ACC/AHA 下肢外周动脉疾病管理指南","Rutherford RB, et al. J Vasc Surg 1997"]},{"id":"vasc_fontaine","name":"Fontaine 下肢动脉缺血分期","aka":["Fontaine Classification","Fontaine stage"],"cat":"动脉缺血分级","rank":2,"desc":"按症状与组织缺损将下肢动脉硬化闭塞症分为 Ⅰ–Ⅳ 期（Ⅳ 期分 4a/4b），是欧洲传统分期。","inputs":[],"compute":"formula_only","levels":[{"label":"Ⅰ 期","criteria":"无症状（部分为其他原因发现脉搏减弱）","level":"ok"},{"label":"Ⅱa 期","criteria":"轻度间歇性跛行，跛行距离 > 200 m","level":"warn"},{"label":"Ⅱb 期","criteria":"中度至重度间歇性跛行，跛行距离 < 200 m","level":"warn"},{"label":"Ⅲ 期","criteria":"静息性疼痛（夜间加重，下垂可缓解）","level":"high"},{"label":"Ⅳ 期","criteria":"组织坏死/溃疡；4a 为可挽救的局部缺损，4b 为不可逆坏疽需截肢","level":"crit"}],"interpret":[{"when":"v >= 0","level":"ok","text":"Ⅰ–Ⅱa 期先保守治疗（运动 + 抗血小板 + 他汀）；Ⅱb–Ⅳ 期需评估血运重建，Ⅳ 期伴坏疽时先控制感染再决定截肢平面"}],"note":"Fontaine Ⅱb 对应 Rutherford 3 级，Ⅲ 对应 4 级，Ⅳ 对应 5–6 级；二者常并列记录。跛行距离以行走试验（跑步机 3.2 km/h、12% 坡度）为准更客观。","refs":["2019 中国下肢动脉硬化闭塞症诊治指南","2024 ACC/AHA 下肢外周动脉疾病管理指南","2023 ESC 外周动脉疾病诊断与管理指南"]},{"id":"vasc_abi","name":"踝肱指数判读（ABI）","aka":["Ankle-Brachial Index","ABI"],"cat":"无创血管评估","rank":1,"desc":"踝部收缩压与肱动脉收缩压之比，是诊断外周动脉疾病与评估肢体缺血程度的首选无创指标。","inputs":[{"key":"ankle_sbp","label":"患侧踝部最高收缩压（胫前或胫后动脉）","unit":"mmHg","type":"number","min":20,"max":300,"step":1,"required":true},{"key":"brachial_sbp","label":"双侧肱动脉最高收缩压","unit":"mmHg","type":"number","min":30,"max":300,"step":1,"required":true}],"formula":"ABI = 踝部收缩压 / 肱动脉收缩压","compute":"formula_only","algorithm":"v = round(ankle_sbp / brachial_sbp, 2)","interpret":[{"when":"v >= 1.4","level":"high","text":"≥ 1.4：血管钙化（常见于糖尿病、慢性肾病、透析），ABI 假性升高；改测趾臂指数（TBI < 0.7 提示 PAD）或趾压 < 30 mmHg"},{"when":"v >= 1.0","level":"ok","text":"1.0–1.39：正常；若症状典型可做运动后 ABI（下降 > 20%）或双功超声"},{"when":"v >= 0.9","level":"warn","text":"0.90–0.99：边缘性异常，需结合症状与影像，建议 6–12 个月复查"},{"when":"v >= 0.5","level":"high","text":"0.50–0.89：轻中度 PAD，以运动康复、抗血小板、他汀、戒烟为主，评估跛行严重度"},{"when":"v < 0.5","level":"crit","text":"< 0.50：重度缺血，若无症状需排除假阴；伴静息痛/溃疡时提示 CLTI，需尽快血运重建评估"}],"note":"测压需患者仰卧 10 分钟以上，测双侧肱动脉与双踝双动脉，取最高值；静息 ABI 正常而症状可疑时做平板运动后复测。糖尿病/终末期肾病患者钙化率高，ABI 常不可靠。","refs":["2024 ACC/AHA 下肢外周动脉疾病管理指南","2023 ESC 外周动脉疾病诊断与管理指南","中国外周动脉疾病诊治指南（2021 版）"]},{"id":"vasc_wifi","name":"WIfI 肢体威胁性缺血分级","aka":["SVS WIfI Classification","Wound Ischemia foot Infection"],"cat":"动脉缺血分级","rank":3,"desc":"综合伤口、缺血、足部感染三项（各 0–3 级）评估 CLTI 截肢风险与血运重建获益，指导保肢策略。","inputs":[{"key":"wound","label":"伤口分级 W","type":"select","options":[{"value":0,"label":"0 级：无伤口"},{"value":1,"label":"1 级：小溃疡无坏疽，前足/中足浅表"},{"value":2,"label":"2 级：较深溃疡伴骨/关节暴露，或足趾坏疽"},{"value":3,"label":"3 级：大面积深部溃疡，全足坏疽或中后足受累"}],"required":true},{"key":"ischemia","label":"缺血分级 I（踝压/趾压）","type":"select","options":[{"value":0,"label":"0 级：踝压 ≥ 100、趾压 ≥ 60 mmHg"},{"value":1,"label":"1 级：踝压 70–99、趾压 40–59 mmHg"},{"value":2,"label":"2 级：踝压 50–69、趾压 30–39 mmHg"},{"value":3,"label":"3 级：踝压 < 50、趾压 < 30 mmHg"}],"required":true},{"key":"infection","label":"足部感染分级 fI","type":"select","options":[{"value":0,"label":"0 级：无感染"},{"value":1,"label":"1 级：浅表轻度感染（红斑 < 2 cm 等）"},{"value":2,"label":"2 级：中度感染（红斑 ≥ 2 cm、深部组织、可伴骨髓炎）"},{"value":3,"label":"3 级：重度感染（全身感染征象、脓毒症）"}],"required":true}],"formula":"WIfI 总分 = W（0–3）+ I（0–3）+ fI（0–3），0–9 分；风险由三维组合决定","compute":"sum","interpret":[{"when":"v <= 2 && ischemia <= 1","level":"ok","text":"很低危：1 年截肢风险约 < 1%–3%，以伤口护理、感染控制与随访为主，血运重建需求低"},{"when":"v <= 4","level":"warn","text":"低/中危：截肢风险升至约 5%–15%，保肢获益取决于血运重建，评估旁路或腔内治疗"},{"when":"v <= 6","level":"high","text":"高危：截肢风险显著升高（约 20%–40%），需尽快血运重建 + 彻底清创 + 感染控制"},{"when":"v >= 7","level":"crit","text":"极高危：1 年死亡/截肢风险极高（截肢 > 40%，死亡约 25%–50%），评估保肢可行性，同时讨论截肢与姑息方案"}],"note":"WIfI 三个维度需分别解读，总分仅辅助；截肢与死亡预测中缺血（I）权重最大。血运重建后按 1 年再评估（WIfI 再分期可判断保肢效果）。","refs":["SVS WIfI 分级（Mills JL, et al. J Vasc Surg 2014）","2024 全球血管指南：慢性肢体威胁性缺血管理（Global Vascular Guidelines 2019）","2024 ACC/AHA 下肢外周动脉疾病管理指南"]},{"id":"vasc_ceap","name":"CEAP 慢性静脉疾病分类","aka":["CEAP Classification","Clinico-Etiologic-Anatomic-Pathophysiologic"],"cat":"静脉疾病","rank":2,"desc":"按临床（C）、病因（E）、解剖（A）、病理生理（P）四维描述慢性静脉疾病，C 分级 0–6 为临床核心。","inputs":[{"key":"c_class","label":"临床分级 C","type":"select","options":[{"value":0,"label":"C0：无可见静脉疾病体征"},{"value":1,"label":"C1：毛细血管扩张或网状静脉"},{"value":2,"label":"C2：静脉曲张（主干直径 ≥ 3 mm）"},{"value":3,"label":"C3：水肿，无皮肤改变"},{"value":4,"label":"C4：皮肤改变（C4a 色素沉着/湿疹，C4b 脂质硬化/白色萎缩）"},{"value":5,"label":"C5：已愈合的静脉性溃疡"},{"value":6,"label":"C6：活动性静脉性溃疡"}],"required":true},{"key":"symptomatic","label":"是否有症状（S 后缀）","type":"select","options":[{"value":0,"label":"无症状（a）"},{"value":1,"label":"有症状（s：疼痛、沉重、肿胀、瘙痒等）"}],"required":true}],"formula":"C 分级 0–6（每级可加 S/A 后缀），完整 CEAP 表述如 C2s Ep As Pr","compute":"formula_only","algorithm":"v = c_class\nsuffix = symptomatic == 1 ? 's' : 'a'","interpret":[{"when":"v <= 2","level":"ok","text":"C0–C2：以弹力袜 + 保守治疗为主；C2 可行静脉腔内热消融/硬化治疗，评估深静脉通畅性"},{"when":"v == 3","level":"warn","text":"C3：压力治疗（20–30 mmHg 以上）为一线，联合静脉活性药物与体重管理"},{"when":"v == 4","level":"high","text":"C4：针对症状性静脉曲张行腔内治疗 + 压力治疗，局部皮肤护理，预防进展为溃疡"},{"when":"v >= 5","level":"crit","text":"C5–C6：静脉性溃疡，需多学科伤口管理（压迫治疗为首选），溃疡愈合后行浅静脉功能不全手术以降低复发"}],"note":"C（临床）是唯一必须记录的维度；E（原发/继发/先天性）、A（浅/深/穿通静脉）、P（反流/阻塞）需超声评估。2020 版 CEAP 新增 C4c（冠状静脉扩张）。","refs":["2020 CEAP 更新（Lurie F, et al. J Vasc Surg Venous Lymphat Disord 2020）","中国慢性下肢静脉疾病诊断与治疗指南（2019 版）","2022 ESVS 静脉曲张管理临床实践指南"]},{"id":"vasc_villalta","name":"Villalta 血栓后综合征评分","aka":["Villalta Scale","PTS score"],"cat":"静脉疾病","rank":3,"desc":"深静脉血栓（DVT）后 3–6 个月起评估血栓后综合征（PTS），按症状与体征评分判定 PTS 分级与严重度。","inputs":[{"key":"symptoms","label":"5 项症状（疼痛、痉挛、沉重、感觉异常、瘙痒）合计分","type":"select","options":[{"value":0,"label":"0 分（均无）"},{"value":1,"label":"1–4 分"},{"value":2,"label":"5–9 分"},{"value":3,"label":"10–14 分"},{"value":4,"label":"15–20 分"}],"required":true},{"key":"signs","label":"6 项体征（胫前水肿、皮肤硬化、色素沉着、发红、静脉扩张、小腿压痛）合计分","type":"select","options":[{"value":0,"label":"0 分（均无）"},{"value":1,"label":"1–5 分"},{"value":2,"label":"6–10 分"},{"value":3,"label":"11–15 分"},{"value":4,"label":"16–18 分"}],"required":true},{"key":"ulcer","label":"是否存在静脉性溃疡","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true}],"formula":"Villalta 分 = 症状分（0–3 每项）+ 体征分（0–3 每项），总分 0–33；有溃疡时单独记为“重度”","compute":"formula_only","algorithm":"v = symptomTotal + signTotal   # 每项均为 0–3 分，共 11 项，0–33 分\nif ulcer == 1: v = 33           # 溃疡等同于重度（标记）","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：无 PTS；继续弹力袜与抗凝随访，年度专科复查"},{"when":"v <= 9","level":"warn","text":"5–9 分：轻度 PTS；压力袜（30–40 mmHg）、运动训练、体重管理，每 6 个月复评"},{"when":"v <= 14","level":"high","text":"10–14 分：中度 PTS；加压治疗 + 静脉活性药物，评估深静脉反流/阻塞是否可行腔内开通"},{"when":"v >= 15","level":"crit","text":"≥ 15 分或任意溃疡：重度 PTS；规范伤口护理、压迫治疗，必要时行髂静脉支架或反流手术"}],"note":"本表把各子项合计分做了区间近似，准确评估请按 11 个子项逐项 0–3 计分（每项：无 0 / 轻度 1 / 中度 2 / 重度 3）。评分应在抗凝期间、DVT 发病后 ≥ 3 个月进行。","refs":["Villalta S, et al. Haematologica 1994（Villalta 原版）","2021 CHEST 抗栓治疗指南（VTE 长期管理）","中国深静脉血栓形成诊断和治疗指南（2023 年修订版）"]},{"id":"vasc_caprini","name":"Caprini 静脉血栓栓塞风险评分","aka":["Caprini Risk Assessment Model","Caprini RAM"],"cat":"静脉疾病","rank":4,"desc":"累加患者、手术与化验危险因素评估 VTE 风险，指导血管外科围手术期血栓预防强度与疗程。","inputs":[{"key":"age_pts","label":"年龄","type":"select","options":[{"value":0,"label":"≤ 40 岁"},{"value":1,"label":"41–60 岁"},{"value":2,"label":"61–74 岁"},{"value":3,"label":"≥ 75 岁"}],"required":true},{"key":"bmi_over","label":"BMI > 25 kg/m²","type":"select","options":[{"value":0,"label":"否"},{"value":1,"label":"是"}],"required":true},{"key":"surgery_type","label":"手术类型","type":"select","options":[{"value":1,"label":"小手术（< 45 分钟）"},{"value":2,"label":"大手术（> 45 分钟）"},{"value":5,"label":"膝/髋关节置换、重大血管手术（开放或长时腔内）"}],"required":true},{"key":"malignancy","label":"恶性肿瘤或化疗中","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"chronic_venous","label":"慢性静脉功能不全 / 下肢静脉曲张","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"bedridden","label":"卧床 > 72 小时或石膏固定","type":"select","options":[{"value":0,"label":"否"},{"value":2,"label":"是"}],"required":true},{"key":"history_vte","label":"既往 VTE / 家族性血栓倾向","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true},{"key":"hypercoag","label":"凝血异常（抗磷脂抗体、因子 V Leiden、蛋白 C/S 缺乏等）","type":"select","options":[{"value":0,"label":"无"},{"value":3,"label":"有"}],"required":true}],"formula":"Caprini 总分 = 各危险因素权重之和，≥ 5 分为高危，≥ 9 分为极高危","compute":"sum","interpret":[{"when":"v <= 4","level":"ok","text":"0–4 分：低/中危，梯度压力袜 + 早期下床，可行者用间歇充气加压（IPC），一般不需药物预防"},{"when":"v <= 8","level":"warn","text":"5–8 分：高危，术后 12–24 小时启用低分子肝素（依诺肝素 40 mg qd），出血高危者先 IPC"},{"when":"v >= 9","level":"high","text":"≥ 9 分：极高危，药物 + 机械联合预防，疗程一般 7–14 天，血管开放手术后延长至出院后 4 周，复查双功超声"}],"note":"本表为精简版权重；血管外科以腹主动脉瘤修复、下肢旁路等高値手术为主，多数患者可归为高危。合并抗凝指征（如房颤）者需评估叠加出血风险，避免双联抗凝。","refs":["中国普通外科静脉血栓栓塞症预防指南（2021 版）","2021 CHEST 抗栓治疗指南（VTE 预防）","Caprini JA, et al. Thromb Haemost 2005"]},{"id":"vasc_wells_dvt","name":"Wells 深静脉血栓评分","aka":["Wells Score for DVT","Wells DVT"],"cat":"静脉疾病","rank":1,"desc":"基于临床特征将疑似 DVT 患者分为确诊可能/不可能，指导 D-二聚体与加压超声的检查路径。","inputs":[{"key":"cancer","label":"活动性肿瘤（治疗中、6 个月内或姑息）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"immobility","label":"瘫痪/近期石膏固定/卧床 > 3 天或 4 周内大手术","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"tenderness","label":"沿深静脉走行局部压痛（含小腿）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"leg_swelling","label":"整条下肢肿胀","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"calf_diff","label":"小腿围差 > 3 cm（胫骨粗隆下 10 cm）","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"pitting_edema","label":"患肢凹陷性水肿","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"collateral","label":"患肢浅表非静脉曲张性侧支静脉","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"prior_dvt","label":"既往 DVT 史","type":"select","options":[{"value":0,"label":"无"},{"value":1,"label":"有"}],"required":true},{"key":"alt_dx","label":"其他诊断至少与 DVT 同样可能","type":"select","options":[{"value":0,"label":"否（DVT 更可能）"},{"value":-2,"label":"是（有其他等效诊断）"}],"required":true}],"formula":"Wells DVT 总分 = 9 项之和（每项 1 分，其他诊断等效 −2 分），−2 至 9 分","compute":"sum","interpret":[{"when":"v <= 0","level":"ok","text":"≤ 0 分：DVT 可能性低（< 5%），D-二聚体阴性可安全排除；阳性则做加压超声"},{"when":"v <= 2","level":"warn","text":"1–2 分：中等可能（约 17%），行 D-二聚体；阴性可排除（低龄/非孕期），阳性或临床高度怀疑直接超声"},{"when":"v >= 3","level":"high","text":"≥ 3 分：很可能（约 53%），直接行加压超声（近端静脉）；超声阴性而临床高度怀疑时重复超声或 D-二聚体"}],"note":"Wells 有两级法（≥ 2 分为可能）；妊娠期、既往 DVT、D-二聚体随年龄升高时需按年龄校正阈值（年龄 × 10 μg/L，> 50 岁）。本评分不适用于已有明确抗凝或血栓复发患者的再评估。","refs":["2019 ESC 急性肺栓塞诊断与管理指南（DVT 诊断路径）","2021 CHEST 抗栓治疗指南","Wells PS, et al. Lancet 1997"]},{"id":"vasc_nascet","name":"NASCET 颈动脉狭窄度判读","aka":["NASCET criteria","North American Symptomatic Carotid Endarterectomy Trial"],"cat":"颈动脉疾病","rank":3,"desc":"按远端正常颈内动脉为分母计算狭窄百分比，是决定症状性/无症状性颈动脉狭窄是否手术的标准判读法。","inputs":[{"key":"narrowest","label":"狭窄最窄处管径","unit":"mm","type":"number","min":0.3,"max":10,"step":0.1,"required":true},{"key":"distal","label":"远端正常颈内动脉管径","unit":"mm","type":"number","min":2,"max":10,"step":0.1,"required":true},{"key":"symptomatic","label":"是否症状性（6 个月内同侧 TIA/卒中/一过性黑矇）","type":"select","options":[{"value":0,"label":"无症状"},{"value":1,"label":"症状性"}],"required":true}],"formula":"狭窄度（NASCET）= (1 − 狭窄处管径 / 远端正常管径) × 100%","compute":"formula_only","algorithm":"v = round((1 - narrowest / distal) * 100, 0)   # 百分比","interpret":[{"when":"v < 50","level":"ok","text":"< 50%：无手术指征，最佳药物治疗（抗血小板 + 他汀 + 控压戒烟），每年超声随访"},{"when":"v <= 69 && symptomatic == 1","level":"warn","text":"症状性 50%–69%：CEA 或 CAS 可获益（需综合年龄、性别、斑块特征）；围手术期风险应 < 6%，尽快在 2 周内手术"},{"when":"v >= 70","level":"high","text":"≥ 70%：若为症状性，CEA/CAS 为 I 类指征（2 周内），围手术期卒中/死亡风险需 < 6%；无症状 ≥ 70% 需个体化（狭窄进展、斑块易损）"},{"when":"v >= 90","level":"crit","text":"≥ 90% 或近闭塞：卒中风险最高，优先 CEA；注意“串珠样”细线征与假性闭塞（超声/CTA）"}],"note":"NASCET 分母为远端正常颈内动脉，与欧式 ECST 法（以狭窄处估计原管径为分母）不同，ECST 70% ≈ NASCET 50%。判定需双功超声 + CTA/MRA 或 DSA 证实，测径以 DSA 为准。","refs":["2023 中国颈动脉狭窄诊治指南","2021 ESC/EACTS 与 ESVS 颈动脉疾病管理指南（ESVS 2023）","NASCET 研究组. N Engl J Med 1991"]}]}};window.__GUIDE__ = {"anes":{"categories":[{"id":"peri","name":"围术期","rank":1,"summary":"以“术前风险分层—术中器官保护—术后早期康复”为主线：术前用 ASA 分级、RCRI 与衰弱筛查判断可否手术及需要何种监测，气道评估与术前禁食是安全基础；术后以多模式镇痛（阿片减量）、PONV 风险分层与早期活动为核心，减少并发症与住院日。","compare":[{"diseaseId":"an_pacu","dx":"术后 24–48 小时内出现恶心、干呕或呕吐，按 Apfel 评分（女性、不吸烟、晕动病/PONV 史、术后阿片）分层，0–4 项对应 10%–79% 风险","key":"术前评估是“术前决策”（能否耐受手术、需要何种监测与优化），PONV 是“术后康复问题”（预防性联合止吐 + 多模式镇痛减阿片）"},{"diseaseId":"an_preop","dx":"访视采集病史、体格检查、实验室与心肺功能评估并按 ASA 分级（Ⅰ–Ⅵ）与 RCRI 分层，识别可优化因素","key":"术前评估关注“风险与优化”，PONV 关注“症状控制与出院延迟”；术前识别高危 PONV 患者（Apfel ≥3）是围术期管理的衔接点"}],"diseases":[{"id":"an_preop","name":"术前评估与 ASA 分级","aka":["Preoperative Assessment","ASA Physical Status","术前访视"],"rank":1,"basic":{"define":"麻醉医师在术前通过病史、体格检查、实验室与心肺功能评估，判断患者合并症、器官功能储备与手术风险，并据此制定麻醉方式、监测分级与围术期优化方案；ASA 分级是美国麻醉医师协会（ASA）按全身疾病严重程度划分的体格状态分级，用于风险沟通与管理（不用于预测具体手术风险）。","risk":["高龄（≥65 岁）、衰弱（frailty）与多重用药（≥5 种）患者术后并发症风险增加","心肺疾病：冠心病、心衰（EF <40%）、中重度瓣膜病、COPD 与肺动脉高压","糖尿病血糖控制不佳（HbA1c >8%）、慢性肾病与肝功能不全","OSA（阻塞性睡眠呼吸暂停）、肥胖（BMI ≥35）与困难气道预测阳性","抗凝/抗血小板药物与围术期停药管理不当"],"epi":"ASA Ⅲ 级及以上患者约占择期手术的 30%–40%，其术后 30 天主要心血管事件风险约为 ASA Ⅰ–Ⅱ 级的 3–5 倍；我国三级医院 ASA Ⅲ–Ⅳ 级患者比例逐年上升。术前充分评估可使非心脏手术围术期心脏事件降低约 20%–30%。"},"patho":"手术创伤与麻醉引起交感神经兴奋、儿茶酚胺与皮质醇升高、炎性介质释放与凝血/纤溶失衡，使心肌氧耗增加、斑块易破裂并增加血栓风险；低体温、容量改变与疼痛进一步加重器官负担。术前评估的目的是识别“储备不足但可优化”的环节（贫血、容量、血糖、气道、抗凝），通过风险分层选择监测与麻醉方式，从而降低围术期发病率和病死率。","dx":{"criteria":["ASA 分级：Ⅰ 级（健康）、Ⅱ 级（轻度系统性疾病无功能受限）、Ⅲ 级（重度系统性疾病、功能受限）、Ⅳ 级（重度系统性疾病、持续威胁生命）、Ⅴ 级（濒死、不手术预期不存活 24 小时）、Ⅵ 级（脑死亡器官捐献）；急诊手术加后缀“E”。","非心脏手术心血管风险指数（RCRI，修订心脏风险指数）：缺血性心脏病、心力衰竭、脑血管病、胰岛素治疗糖尿病、肌酐 >177 µmol/L（2 mg/dL）、高危手术（腹腔内/胸腔内/腹股沟以上血管手术）各 1 分，≥3 项为高危。","功能储备评估：Duke 活动状态指数（DASI）<34 分或不能爬 2 层楼提示储备不足，需进一步心肺功能评估。","气道评估：Mallampati 分级（Ⅲ–Ⅳ 级）、张口度 <3 横指、甲颏距离 <6 cm、颈围 >40 cm、颈椎活动受限与既往困难插管史。","衰弱筛查（FRAIL 量表或 Fried 标准）与营养筛查（NRS-2002）用于老年患者。"],"workup":["病史与用药核对（抗凝药、抗血小板药、降糖药、ACEI/ARB、MAOI、中草药）与过敏史、既往麻醉史","心电图：年龄 ≥65 岁或有心血管危险因素者；若有症状或活动耐量下降需心脏超声、负荷试验与心内科会诊","常规血液检查：血常规、凝血功能、肝肾功能、电解质、血糖；年龄 <40 岁、ASA Ⅰ–Ⅱ 级且无合并症者不作为常规","胸部 X 线与肺功能：COPD、吸烟或胸腔手术患者","OSA 筛查（STOP-BANG ≥3 分提示高危）、气道评估与禁食时间核对","HbA1c（糖尿病患者）与术后谵妄风险因素评估（高龄、认知障碍、视力/听力障碍）"],"grading":"ASA Ⅰ–Ⅵ 级（可加 E 表示急诊）；RCRI 0–1 分低危（MACE 约 0.4%–1%）、2 分中危（约 1%–5%）、≥3 分高危（>5%–11%）；按手术风险分为低危（<1%）、中危（1%–5%）与高危（>5%）。"},"ddx":[{"name":"术后恶心呕吐（PONV）与镇痛","point":"与本类中“PONV”的鉴别点：术前评估是手术前的风险分层与优化过程，不涉及症状诊断；PONV 是术后以恶心呕吐为主要表现的临床事件，用 Apfel 评分分层并用预防性止吐方案处理。"},{"name":"术后谵妄","point":"术后 1–3 天出现注意力障碍与意识波动，常与高龄、认知障碍与疼痛/感染相关；术前即需识别其风险因素。"},{"name":"术后呼吸衰竭（OSA 相关）","point":"高危 OSA 患者术后出现低通气与低氧（尤其短小手术、阿片使用后），术前 STOP-BANG 筛查是关键。"},{"name":"围术期心肌梗死","point":"术后 1–3 天出现胸痛/肌钙蛋白升高伴心电图改变，高危 RCRI 与术中低血压是重要危险因素。"},{"name":"恶性高热易感者术前评估","point":"家族史与既往麻醉后高热史，需与麻醉相关基因检测及无触发药物方案衔接。"}],"tx":{"drug":[{"name":"术前抗凝/抗血小板管理（华法林、DOAC、阿司匹林）","dose":"华法林：术前约 5 天停药，INR ≤1.5 方可手术（高危血栓者桥接按指南）；达比加群/利伐沙班等按说明书于术前 1–3 天停药，肾功能不全者延长；阿司匹林用于二级预防者多数可继续（遵说明书）","note":"术前抗凝决策需联合手术出血风险与血栓风险，必要时心内科/血液科会诊；区域麻醉需按指南核对停药时间","renal":"DOAC 经肾清除，eGFR <50 者需延长停药时间","hepatic":"严重肝病伴凝血障碍者需凝血功能评估","interact":"与 NSAIDs、SSRI、中草药（银杏、人参）合用出血风险增加"},{"name":"术前禁食与碳水化合物负荷（ERAS 方案）","dose":"清饮（水、无渣果汁）术前 2 小时；母乳 4 小时；配方奶、牛乳与清淡固体 6 小时；可口服碳水化合物饮料 400 mL 于术前 2–3 小时（糖尿病与胃排空障碍者除外）","note":"避免长时间禁食致脱水与胰岛素抵抗；急诊与胃排空障碍者按饱胃处理","renal":"CKD 需限制液量者遵医嘱","hepatic":"肝硬化腹水者避免大量液体负荷","interact":"遵说明书"},{"name":"术前预防性抗菌药（头孢唑林等）","dose":"切皮前 60 分钟内给予，头孢唑林 1–2 g 静滴（体重 >80 kg 用 2 g），术中每 4 小时或失血 >1500 mL 追加","note":"需在手术实际开始前 30–60 分钟给药以达有效组织浓度；β-内酰胺过敏者遵说明书选替代","renal":"头孢唑林在 CrCl <50 者需调整间隔","hepatic":"无需调整","interact":"与华法林合用可延长 INR"},{"name":"术前镇静（咪达唑仑）","dose":"1–2 mg 静推（老年 0.5–1 mg）；短小手术可不用","note":"老年、OSA 与肝肾功能不全者减少剂量；不可替代充分解释与沟通","renal":"咪达唑仑代谢产物在肾衰蓄积，减量","hepatic":"肝病者半衰期延长，减量","interact":"与阿片类协同抑制呼吸"},{"name":"ACEI/ARB 与降糖药围术期管理","dose":"ACEI/ARB 择期手术当日停用一次（心衰患者遵心内科意见）；磺脲类药物术前停用，二甲双胍手术当日停用，胰岛素按方案减量（遵说明书）","note":"ACEI/ARB 持续使用增加术中低血压风险，停用增加高血压风险，需个体化","renal":"CKD 患者 ACEI/ARB 停药需监测血压","hepatic":"无需调整","interact":"ACEI/ARB 与非甾体抗炎药合用增加围术期急性肾损伤"}],"nonDrug":["麻醉方式选择：区域麻醉、神经阻滞与全身麻醉按手术部位、患者意愿与合并症个体化，神经阻滞可减少阿片用量","监测分级：ASA Ⅲ 级以上或大手术需有创动脉压/中心静脉监测与体温管理（保温暖，目标中心体温 ≥36 ℃）","术前优化：贫血纠正（Hb <80 g/L 或心血管病 <100 g/L 评估输血）、营养不良营养支持、戒烟 ≥4 周与血糖控制（HbA1c <8%）","多学科会诊与预康复（prehabilitation）：高危患者术前呼吸训练与运动训练","术后疼痛与 PONV 预防计划在术前即制定（多模式镇痛、Apfel 分层预防）","麻醉知情同意与术前禁食宣教，记录气道评估与既往困难气道"],"life":["术前戒烟、限酒、体重管理（BMI 目标 <30），减少术后肺部并发症","告知患者麻醉方式与术后疼痛管理方式，术后早期下床活动","老年患者术前评估认知功能与谵妄预防（定向力宣教、睡眠管理）","术后 24 小时内随访并发症（恶心呕吐、疼痛、低氧、伤口），必要时转 ICU"]},"prog":"ASA Ⅰ–Ⅱ 级择期手术围术期病死率 <0.1%，ASA Ⅲ 级约 1%–3%，ASA Ⅳ 级约 10%–20%；RCRI ≥3 分者 30 天主要心血管事件约 5%–11%。充分术前优化（贫血、血糖、营养、戒烟、预康复）可使术后并发症显著下降，ERAS 路径使住院日缩短约 2–3 天。","refs":["中华医学会麻醉学分会《围手术期麻醉评估与优化专家共识》（2021）","中华医学会麻醉学分会《急诊手术麻醉指南》","中华医学会麻醉学分会《加速康复外科（ERAS）中国专家共识》（2021）","ASA《Physical Status Classification System》（2020）","ESC/ESA《非心脏手术围术期心血管评估与管理指南》（2022 年更新）"]},{"id":"an_pacu","name":"术后恶心呕吐（PONV）与镇痛","aka":["PONV","术后镇痛","Postoperative Nausea and Vomiting","PACU 综合征"],"rank":2,"basic":{"define":"术后 24–48 小时内发生的恶心、干呕或呕吐；按时间分为早期（术后 24 小时内）与晚期（>24 小时）。术后镇痛以“多模式镇痛”为核心：联合区域阻滞/局部浸润、非阿片类镇痛药与选择性阿片，兼顾镇痛效果与阿片相关不良反应（呼吸抑制、PONV、肠麻痹）。","risk":["PONV：女性、不吸烟、晕动病或 PONV 病史、术后使用阿片类（Apfel 四项，0–4 项对应风险约 10%/21%/39%/61%/79%）","PONV：腹腔镜/妇科/耳鼻喉/斜视手术，吸入麻醉 vs 丙泊酚全静脉麻醉","镇痛：大手术、开胸与腹部手术、慢性阿片使用者，术后疼痛控制不足致睡眠障碍与慢性疼痛","OSA、老年与肾功能不全者对阿片呼吸抑制更敏感"],"epi":"PONV 总体发生率约 20%–30%，高危患者（Apfel ≥3）可达 60%–80%；未预防的高危患者 PONV 发生率可达 70%以上。约 10%–50% 的手术患者发生中重度术后疼痛，其中 10%–20% 可能在术后 3–6 个月发展成慢性术后疼痛。"},"patho":"PONV 由呕吐中枢与化学感受区（CTZ）共同介导：吸入麻醉与阿片类激活 5-HT3（肠嗜铬细胞）、NK1、D2 与 H1 受体通路，前庭系统（晕动病）与胃排空延迟也参与；女性与 PONV 史者中枢触发阈值低。术后疼痛使交感兴奋、阿片用量增加而进一步升高 PONV 风险，形成恶性循环。术后疼痛来自切口躯体痛、内脏痛与神经病理性痛，多模式镇痛通过不同机制叠加减少阿片用量及相关不良事件。","dx":{"criteria":["PONV：术后 24–48 小时内出现恶心（主观）、干呕（有呕吐动作无内容物）或呕吐（胃内容物排出）；按 Apfel 风险评分：女性、非吸烟、晕动病或 PONV 史、术后阿片使用各 1 分。","风险层次：0 分为低危（约 10%）、1 分为 21%、2 分为 39%、3 分为 61%、4 分为 79%；≥3 分推荐两种或以上药物预防，≥1 项高危时考虑丙泊酚 TIVA 与避免吸入麻醉/氧化亚氮。","严重程度：0–2 次呕吐为轻至中度，反复呕吐（>3 次/日）需排除低血压、低钠血症、肠梗阻、胃扩张与低血糖。","镇痛评估：术后使用数字评分法（NRS 0–10），<3 分为可接受；需评估疼痛部位、性质与阿片相关副作用（呼吸频率 <8 次/分、镇静评分）。"],"workup":["评估阿片使用量、静息/活动疼痛评分与镇痛满意度","监测呼吸频率、SpO₂、镇静程度（Ramsay/POSS）以识别阿片呼吸抑制","反复呕吐者查电解质、血糖与腹部查体（腹胀/肠鸣音）","评估是否为手术并发症（腹腔积液、肠麻痹、恶性肠梗阻）而非单纯 PONV","记录 PONV 发作时间、诱因（进食、体动、拔管）与既往 PONV 史","术后疼痛评估疼痛性质（神经病理性痛建议加用加巴喷丁类与区域阻滞）"],"grading":"PONV 按 Apfel 0–4 项分层（约 10%/21%/39%/61%/79%）；疼痛按 NRS 0–10 分（轻度 1–3、中度 4–6、重度 7–10）；镇痛按术后疼痛管理与阿片不良反应评估（POSS 评分）。"},"ddx":[{"name":"术前评估与 ASA 分级","point":"与本类中“术前评估”的鉴别点：PONV 是术后症状性事件、诊断依据为症状及 Apfel 风险，术前评估是手术前风险分层与优化过程；两者在术前识别 PONV 高危者与制定预防方案处衔接。"},{"name":"术后肠梗阻/胃扩张","point":"腹胀、无肠鸣音、呕吐物为胃内容物或胆汁，腹平片见液气平面；需禁食、胃肠减压而非单纯止吐。"},{"name":"术后低钠血症","point":"大量输液与抗利尿激素异常导致，表现为恶心呕吐伴乏力与意识改变，血钠 <130 mmol/L。"},{"name":"腹腔内出血/积液","point":"术后血压下降、苍白与腹部膨隆，超声见腹腔积液；需紧急处理而非止吐。"},{"name":"阿片过量或呼吸抑制","point":"呼吸频率 <8 次/分、针尖样瞳孔、镇静加深，需纳洛酮拮抗并吸氧。"}],"tx":{"drug":[{"name":"昂丹司琼（5-HT3 拮抗剂）","dose":"4 mg 静推（拔管前或手术结束前），q8h 按需；也可 8 mg 口服；儿童 0.1 mg/kg（最大 4 mg）","note":"延长 QT，与其他延长 QT 药物慎联用；PONV 治疗应换用不同机制药物而非重复同一种","renal":"无需调整","hepatic":"严重肝病单次剂量 ≤8 mg/日","interact":"与胺碘酮、氟喹诺酮合用 QT 延长风险增加"},{"name":"地塞米松","dose":"4–8 mg 静推（诱导前或手术开始前），单次给药；>0.1 mg/kg 无效时不再追加","note":"可致围术期血糖升高与伤口愈合不良风险（糖尿病慎用大剂量）","renal":"无需调整","hepatic":"无需调整","interact":"与氟喹诺酮合用增加肌腱断裂风险"},{"name":"甲氧氯普胺（多巴胺拮抗剂）","dose":"10 mg 静推（成人），q6h 按需；儿童 0.1–0.15 mg/kg","note":"止吐效果相对较弱，可作为联合方案第三线；避免用于帕金森病与肠梗阻","renal":"CKD 减量","hepatic":"严重肝病减量","interact":"与抗精神病药合用锥体外系反应风险增加"},{"name":"氟哌利多/氟哌啶醇（D2 拮抗剂）","dose":"氟哌利多 0.625–1.25 mg 静推；氟哌啶醇 0.5–1 mg 静推","note":"可致 QT 延长与锥体外系反应；已从部分国家市场撤出氟哌利多，使用前评估 QT","renal":"无需调整","hepatic":"无需调整","interact":"与 QT 延长药同用风险增加"},{"name":"阿瑞匹坦（NK1 拮抗剂）","dose":"术前口服 40 mg（或静脉 fosaprepitant 150 mg）单次，用于高风险的晚期 PONV 预防","note":"可减弱口服避孕药效果（需替代避孕措施 28 天）；与华法林合用需监测 INR","renal":"无需调整","hepatic":"严重肝病慎用","interact":"CYP3A4 抑制剂，与咪达唑仑、芬太尼合用延长作用"},{"name":"多模式镇痛：对乙酰氨基酚 + NSAIDs","dose":"对乙酰氨基酚 1 g 静滴 q6h（每日总量 ≤4 g，肝病 ≤2 g）；帕瑞昔布 40 mg 静推 q12h（或氟比洛芬酯 50 mg q8h），疗程 ≤3 天","note":"NSAIDs 与肾功能不全、消化道溃疡、出血风险与骨愈合相关；肾功能不全与出血高危者慎用","renal":"CrCl <30 mL/min 不用 NSAIDs；对乙酰氨基酚无需调整","hepatic":"严重肝病对乙酰氨基酚 ≤2 g/日；NSAIDs 肝病慎用","interact":"NSAIDs 与抗凝药/抗血小板药合用增加出血；对乙酰氨基酚与华法林合用可升高 INR"},{"name":"阿片类（芬太尼/羟考酮）","dose":"芬太尼 25–50 µg 静推按需（PACU），或羟考酮 5 mg 口服 q4–6h；PCIA 泵按方案设定；老年与 OSA 患者减量 30%–50%","note":"滴定至疼痛 NRS ≤3，避免单次大剂量；监测呼吸频率与镇静；可用纳洛酮 0.04–0.4 mg 静推拮抗","renal":"羟考酮在肾衰需减量；芬太尼相对安全","hepatic":"严重肝病阿片类清除下降，减量","interact":"与苯二氮䓬类、加巴喷丁类合用呼吸抑制叠加"}],"nonDrug":["PONV 预防分层策略：低危（Apfel 0–1）不需常规预防；中危（2）用 2 种药物；高危（≥3）用 3 种药物并考虑丙泊酚 TIVA、避免氧化亚氮与减少阿片","已发生 PONV 时更换机制不同的药物（如 5-HT3 已用则改 NK1 或 D2 拮抗剂），而非重复同药","多模式镇痛：区域阻滞（TAP、椎旁、神经丛阻滞）与切口局部浸润可显著减少阿片用量","疼痛滴定：PACU 中按 NRS 滴定镇痛，重症疼痛考虑硬膜外/神经阻滞","术后充分补液（按需而非过量）、早期下床与嚼口香糖促进肠功能恢复","OSA 患者术后监测 SpO₂ 与呼吸，必要时无创通气","PONV 持续超过 3 天需排除肠梗阻、颅内高压等继发因素"],"life":["出院前评估镇痛效果与阿片使用，开具口服镇痛药并按需复诊","术后 24–48 小时电话随访恶心呕吐与疼痛，减少出院后不良反应","阿片类药物开具最小必要量，教育患者合理使用与储存、避免酒精","慢性疼痛或慢性阿片使用者转介疼痛科，术后 4 周复评"]},"prog":"多数 PONV 经治疗在 24–48 小时内缓解，严重者延长住院 1–3 天；出院后 PONV 发生率约 10%–20%。规范多模式镇痛可使阿片用量减少 30%–50%，术后疼痛控制满意率 >85%，并降低慢性术后疼痛发生率约 20%–30%。","refs":["中华医学会麻醉学分会《术后恶心呕吐防治专家共识》（2020）","中华医学会麻醉学分会《成人术后疼痛管理专家共识》（2019）","中华医学会麻醉学分会《多模式镇痛中国专家共识》","Apfel 等《简化 PONV 风险评分（Apfel 1999）》","第 4 版《术后恶心呕吐管理共识指南》（Gan 等，2020）"]}]},{"id":"anes_emerg","name":"麻醉急症","rank":2,"summary":"麻醉急症的共同点是“分秒必争 + 特异性解救药 + 团队预案”：恶性高热需立即停用吸入麻醉药/琥珀胆碱并给予丹曲林 2.5 mg/kg；困难气道遵循 ASA“预判—优化—呼救—紧急入路”流程，强调及时声门上气道与环甲膜切开；局麻药中毒先气道与循环支持，再用 20% 脂肪乳剂。三者均需建立“急症车 + 预案演练 + 术后追踪”。","compare":[{"diseaseId":"an_mh","dx":"吸入麻醉药/琥珀胆碱暴露后出现无法解释的高碳酸血症（ETCO₂ 骤升）、肌僵硬、高热（>40 ℃）、高钾与横纹肌溶解，血气示呼吸性+代谢性酸中毒","key":"特异性用药：MH 用丹曲林 2.5 mg/kg 重复至 10 mg/kg；LAST 用 20% 脂肪乳剂 1.5 mL/kg；困难气道靠通气与紧急气道技术解决"},{"diseaseId":"an_airway","dx":"面罩通气困难（SpO₂ 下降、胸廓起伏不明显）、声门上气道失败、插管失败（≥3 次或 >10 分钟），CICO（不能插管不能氧合）为最危重情形","key":"MH/LAST 由药物触发，有特异性解毒药；困难气道的根本是“氧合失败”，处理重点是尽早声门上气道与紧急有创气道"},{"diseaseId":"an_la_tox","dx":"局麻药注射后出现口周麻木、耳鸣、金属味、抽搐、意识障碍，继而心律失常/心脏骤停（常用布比卡因、罗哌卡因），或注药部位异常麻木","key":"LAST 以神经-心脏毒性为特征且进展迅速，需脂肪乳剂；MH 以高代谢（高碳酸、高热、肌僵）为特征，需丹曲林"}],"diseases":[{"id":"an_mh","name":"恶性高热","aka":["Malignant Hyperthermia","MH","恶性高热危象"],"rank":1,"basic":{"define":"吸入性挥发性麻醉药（七氟烷、地氟烷等）或去极化肌松药（琥珀胆碱）触发的骨骼肌高代谢危象，由骨骼肌雷诺定受体（RYR1）基因突变致肌浆网钙释放失控，表现为高碳酸血症、肌僵硬、高热、酸中毒与高钾，未经丹曲林治疗病死率极高。","risk":["RYR1 或 CACNA1S 基因突变的易感者（常染色体显性，外显率不完全）","家族史：既往麻醉后高热、肌红蛋白尿或术中死亡；MH 易感者家族史","合并肌病（中央轴空病、King-Denborough 综合征）或既往麻醉中咬肌痉挛","吸入麻醉药与琥珀胆碱联合使用；长时间手术与高环境温度可加重"],"epi":"接受全身麻醉者 MH 发生率约 1/10 万（儿童约 1/1.5 万–1/5 万，成人约 1/5 万–1/10 万）；我国报道病例逐年增多，未使用丹曲林时病死率 >70%，规范使用丹曲林后病死率降至 <5%–10%（国际转诊中心报道）。"},"patho":"RYR1 突变使肌浆网钙通道在麻醉药刺激下持续开放，大量 Ca²⁺ 释放入胞浆，激活肌球蛋白 ATP 酶与糖酵解，产生大量 CO₂、乳酸与热；持续肌收缩使氧耗剧增、ATP 耗竭、细胞膜破坏，导致高钾、肌红蛋白尿、横纹肌溶解与急性肾损伤，进一步引发心律失常与 MODS。高热是晚期表现，高碳酸血症（ETCO₂ 骤升）常为首个信号。","dx":{"criteria":["触发后出现无法解释的 ETCO₂ 进行性升高（常 >45–50 mmHg 且持续升高）、与通气量不成比例","全身肌肉僵硬（咬肌痉挛→全身肌强直），伴心动过速与呼吸性/代谢性酸中毒（pH 下降、乳酸升高）","体温迅速升高、中心体温可达 >40 ℃，出汗与皮肤潮红或发绀，高钾血症（K⁺ >6 mmol/L 及心律失常）","肌红蛋白尿（酱油色尿）、CK 显著升高（>10000 U/L）、凝血障碍与急性肾损伤","诊断评分：临床评分（Larach 评分）≥35 为“很可能”、20–34 “可能”；快速确认：呼出气或动脉 CO₂ 骤升 + 不能解释的肌强直 + 酸中毒","确诊：咖啡因-氟烷体外收缩试验（IVCT）为金标准（仅少数中心可做）；基因检测（RYR1 靶向测序）用于家族筛查"],"workup":["即时：ETCO₂、SpO₂、有创动脉压、体温（中心体温与皮肤）、动脉血气（含 K⁺、乳酸、CK）","尿量与尿色（肌红蛋白尿），电解质、肌酐、凝血功能","心电图（高钾表现与心律失常）","术后：CK 峰浓度、肾功能与肌红蛋白尿持续时间","家族筛查：易感者转介麻醉遗传学与 IVCT 中心","排除鉴别：脓毒症、甲状腺危象、神经阻滞恶性综合征（NMS）、嗜铬细胞瘤危象"],"grading":"按 Larach 临床评分：≥35 分“很可能”、20–34 分“可能”、≤19 分“不太可能”；按反应分型：经典型（全身肌僵+高代谢）、咬肌痉挛型（仅咬肌强直，可伴或不伴 MH 反应）、迟发型（术后 1 小时内出现）。"},"ddx":[{"name":"困难气道","point":"与本类中“困难气道”的鉴别点：MH 表现为高代谢（ETCO₂ 骤升、高热、肌僵），有吸入麻醉药/琥珀胆碱触发史；困难气道的 ETCO₂ 常因通气不足而下降并伴 SpO₂ 下降，无高热与肌僵。"},{"name":"局麻药中毒（LAST）","point":"与本类中“局麻药中毒”的鉴别点：LAST 有局麻药注射史，以口周麻木、抽搐与心律失常为特征，无高热与肌强直；MH 有吸入麻醉药/琥珀胆碱暴露史与高代谢。"},{"name":"脓毒症/脓毒性休克","point":"发热伴感染灶、白细胞与降钙素原升高、血管扩张性低血压；无肌僵与 ETCO₂ 骤升。"},{"name":"甲状腺危象","point":"甲亢病史，高热、心动过速与意识改变，伴甲状腺肿与甲功异常；无药物触发与肌僵。"},{"name":"神经阻滞剂恶性综合征（NMS）","point":"抗精神病药暴露史，肌强直、高热与自主神经不稳定，丹曲林部分有效但以停药+溴隐亭/丹曲林为主。"}],"tx":{"drug":[{"name":"丹曲林钠（Dantrolene sodium）","dose":"2.5 mg/kg 静推/快速静滴，必要时每 5–10 分钟重复至总量 10 mg/kg（若仍无效，有报道可至 10–20 mg/kg，遵说明书与 MH 中心方案）；成功后 1 mg/kg 持续输注 24–48 小时防复发","note":"MH 唯一特异性解救药，应尽早（首选）给药，不应等待确诊；每瓶 20 mg 用 60 mL 无菌注射用水溶解（不含抗菌剂的粉针剂）","renal":"肾功能不全无需调整，但需监测尿量与容量","hepatic":"严重肝病慎用（可致肝损伤）","interact":"与维拉帕米合用可致高钾与心肌抑制，禁用钙通道阻滞剂"},{"name":"碳酸氢钠 8.4%","dose":"1–2 mmol/kg 静滴，按血气与 pH 调整；仅在严重代谢性酸中毒时使用","note":"可加重高钠与高渗；与钙剂同通路禁忌","renal":"肾衰者监测钠负荷","hepatic":"无需调整","interact":"与肾上腺素、钙剂同通路禁忌"},{"name":"氯化钙/葡萄糖酸钙","dose":"10% 氯化钙 5–10 mL 或 10% 葡萄糖酸钙 10–20 mL 静推，用于高钾伴心电图改变时；钙剂稳定心肌","note":"仅在明确高钾伴心电图改变时使用；中心静脉给氯化钙（外渗可致组织坏死）","renal":"无需调整","hepatic":"无需调整","interact":"与头孢曲松同通路禁忌"},{"name":"胰岛素 + 葡萄糖（降钾）","dose":"普通胰岛素 10 U + 50% 葡萄糖 25 g 静推，继以 10% 葡萄糖泵入监测血糖","note":"与丹曲林治疗并行处理高钾；监测血糖防低血糖","renal":"低血糖风险高，需延长监测","hepatic":"无需调整","interact":"β 受体阻滞剂可延迟血糖回升"},{"name":"抗心律失常（胺碘酮/利多卡因）","dose":"心律失常时按 ACLS 处理；室性心律失常可用胺碘酮 150–300 mg 静推或利多卡因 1–1.5 mg/kg","note":"勿用钙通道阻滞剂（维拉帕米/地尔硫䓬）与丹曲林合用","renal":"无需调整","hepatic":"胺碘酮严重肝病减量","interact":"与丹曲林合用时禁用钙通道阻滞剂"},{"name":"冰毯/冷生理盐水降温（物理降温）","dose":"静脉输注冰生理盐水 15–20 mL/kg，体表冰袋与降温毯，目标中心体温 38 ℃ 以下并避免过度降温","note":"降温需与丹曲林同时进行，不可单靠物理降温","renal":"CKD 患者控制输液量","hepatic":"无需调整","interact":"无"}],"nonDrug":["立即停用所有触发药物（吸入麻醉药、琥珀胆碱），更换麻醉回路与钠石灰（碱石灰可蓄积热量）","100% 纯氧高流量通气（较常规增加 2–3 倍分钟通气量以排出 CO₂）","有创监测：动脉压、中心静脉压、体温、尿量与血气（每 15–30 分钟）","碱化与利尿：维持尿量 ≥2 mL/kg/h 以清除肌红蛋白，必要时甘露醇或呋塞米","高钾/心律失常按 ACLS 处理；必要时血液净化","疑 MH 者术前准备：触发药物-free 麻醉（丙泊酚 TIVA、非去极化肌松药），备丹曲林 ≥36 瓶（至少 720 mg）与 MH 急症车","转介 MH 热线上报与家族筛查；术后至少监测 24 小时"],"life":["MH 易感者避免使用吸入麻醉药与琥珀胆碱，选择 TIVA；手术麻醉前告知并佩戴警示卡","家族筛查（RYR1 基因检测或 IVCT），提供遗传咨询","丹曲林 24–48 小时维持后逐步减停，监测 CK 与肾功能恢复","术后急性肾损伤随访（1–3 个月复查肌酐）与康复"]},"prog":"及时使用丹曲林者预后良好，多数在 24–48 小时内体温与代谢恢复，病死率 <5%；未用丹曲林者病死率 >70%，死亡多因高钾致心律失常、顽固性酸中毒与急性肾衰竭。约 20% 患者出现肌无力与肾功能不全等并发症，多数可恢复。术后 1 年内复发（未充分治疗）者应再评估。","refs":["中华医学会麻醉学分会《恶性高热诊疗专家共识》（2019）","中国医师协会麻醉学医师分会《恶性高热防治中国专家共识》","欧洲恶性高热小组（EMHG）指南（2021 更新）","Malignant Hyperthermia Association of the United States（MHAUS）处置流程","中华医学会麻醉学分会《吸入麻醉药临床应用专家共识》"]},{"id":"an_airway","name":"困难气道","aka":["Difficult Airway","CICO","不能插管不能氧合"],"rank":2,"basic":{"define":"经过培训的麻醉医师遇到面罩通气困难、声门上气道（SGA）置入困难或气管插管困难（≥3 次尝试或 >10 分钟）中的任一种；最危重情形为不能插管不能氧合（CICO），需立即建立紧急有创气道。","risk":["预测困难：Mallampati Ⅲ–Ⅳ 级、张口度 <3 横指、甲颏距离 <6 cm、颈围 >40 cm、颈椎活动受限","肥胖（BMI >35）、OSA、大舌/扁桃体肥大、下颌后缩、颈短与颞下颌关节病变","颌面/颈部手术、放疗后、口腔肿物、喉部肿瘤与气道狭窄、既往重建手术后","颈椎损伤、急诊饱胃、血/分泌物/呕吐物污染气道、气道水肿（烧伤、过敏、血管性水肿）"],"epi":"困难面罩通气发生率约 1.4%–5%（OSA 患者更高），困难插管约 5%–8%，CICO 罕见（约 1/5000–1/50000 例）但可迅速致命；困难气道的直接并发症包括缺氧性脑损伤与死亡，约 30%–50% 的麻醉相关死亡与气道管理失败相关。"},"patho":"气道管理失败的本质是氧合失败：反复插管与面罩通气不当导致低氧、高碳酸、心跳骤停；同时咽喉部创伤、误吸、水肿与出血进一步恶化气道，形成尝试越多—失败越多—损伤越重的恶性循环。喉头位置评估（Lemon 评分）与三维评估（张口、下颌空间、颈部活动）共同决定可选策略；氧储备、预氧合（呼出气氧浓度 >90%）与快速呼叫是降低风险的关键。","dx":{"criteria":["面罩通气困难：无法维持 SpO₂ ≥90%（FiO₂ 1.0）、无胸廓起伏或明显漏气，伴严重气道梗阻（如吸气性三凹征）。","插管困难：≥3 次尝试、需要 >10 分钟或直接喉镜失败后改用其他设备；声门暴露分级 Cormack-Lehane Ⅲ–Ⅳ 级。","声门上气道置入困难：4 次尝试仍失败或漏气压高于平台压。","CICO：多次插管失败 + SGA 失败/不可用 + 面罩通气不足（SpO₂ 进行性下降）。","术前气道评估：Mallampati、张口度、甲颏距离、颈围、颈椎活动度与既往困难气道史，结合张口度 <3 指 + 甲颏距离 <6 cm + Mallampati Ⅲ–Ⅳ 级预测困难。"],"workup":["术前：气道评估表（Mallampati、张口度、甲颏距离、颈围、下颌活动度、既往困难气道），必要时喉镜/纤维支气管镜评估","备选计划：可插管喉罩、视频喉镜、纤维支气管镜、逆行插管、环甲膜切开包与硬质支气管镜","SpO₂、ETCO₂、气道压与呼吸音监测；困难气道时立即备好急症呼吸机与吸引器","影像：颈部/口咽肿物、气道狭窄或压迫者行 CT/MRI 评估","紧急有创气道前定位：环甲膜（甲状软骨与环状软骨间），确认解剖标志"],"grading":"按困难类型分为面罩通气困难、SGA 置入困难、插管困难与 CICO；按 ASA 困难气道管理路径分为非紧急路径（保留自主呼吸、可用 SGA 与取消手术）与紧急路径（CICO 时立即环甲膜切开）；Cormack-Lehane 喉镜视野分级 Ⅰ–Ⅳ 级。"},"ddx":[{"name":"恶性高热","point":"与本类中恶性高热的鉴别点：困难气道表现为通气不足、低氧与 ETCO₂ 降低，无高热、肌僵与酸中毒；恶性高热为 ETCO₂ 骤升、肌僵与高热，代谢亢进。"},{"name":"喉痉挛","point":"全麻或浅麻醉下声带闭合致吸气性喘鸣、SpO₂ 下降，常有分泌物或疼痛诱因；可用正压通气、加深麻醉或肌松缓解。"},{"name":"支气管痉挛","point":"呼气性喘鸣、气道阻力升高与 CO₂ 波形呈鲨鱼鳍样，多见于哮喘/COPD；与困难气道的固定上气道梗阻不同。"},{"name":"气道水肿（过敏/血管性水肿）","point":"唇舌与咽喉水肿、进行性呼吸困难，需肾上腺素与激素，气道可迅速恶化。"},{"name":"异物或分泌物误吸","point":"饱胃或出血时发生，需吸引与头低位，误吸后易发生化学性肺炎。"}],"tx":{"drug":[{"name":"罗库溴铵（快速序贯诱导）","dose":"0.6–1.2 mg/kg 静推（气道条件差时 1.2 mg/kg，90 秒内起效）；不可插管时可用舒更葡糖钠 16 mg/kg 逆转","note":"琥珀胆碱禁忌（高钾、烧伤、脊髓损伤）时的替代；需确认气道可通气与设备就绪","renal":"肾衰时罗库溴铵作用延长，舒更葡糖钠可逆转但需监测再箭毒化","hepatic":"严重肝病作用延长","interact":"与氨基糖苷类、镁剂合用作用增强"},{"name":"舒更葡糖钠（Sugammadex）","dose":"2 mg/kg（四个成串刺激 2 个反应）、4 mg/kg（强直刺激后计数 1–2）、16 mg/kg（立即逆转紧急情况）静推","note":"用于罗库溴铵/维库溴铵过量时的强制逆转，恢复自呼吸；过敏与心动过缓/心脏停搏风险需监测","renal":"eGFR <30 不推荐；透析患者慎用","hepatic":"无需调整","interact":"可降低激素类避孕药效果（需替代避孕 7 天）"},{"name":"丙泊酚（镇静）","dose":"1.5–2.5 mg/kg 静推（诱导）；维持 4–12 mg/kg/h","note":"气道梗阻时镇静可加重梗阻，需在能通气的前提下使用；循环不稳者减量","renal":"无需调整","hepatic":"严重肝病减量","interact":"与阿片类协同抑制呼吸与循环"},{"name":"右美托咪定（清醒插管辅助）","dose":"负荷 0.5–1 µg/kg（10–15 分钟）后 0.2–0.7 µg/kg/h 维持","note":"保持自主呼吸与可唤醒，用于困难气道清醒纤维支气管镜插管","renal":"无需调整","hepatic":"严重肝病减量","interact":"与 β 受体阻滞剂合用加重心动过缓"},{"name":"肾上腺素（气道水肿/反流误吸）","dose":"过敏致气道水肿：0.3–0.5 mg 肌注；雾化 1:1000 溶液 2–5 mL；反流误吸后顽固低氧者按休克处理","note":"气道水肿时首选肌注肾上腺素，避免静脉推注","renal":"无需调整","hepatic":"无需调整","interact":"与 β 受体阻滞剂合用减弱效应"}],"nonDrug":["ASA 流程：预判→准备（多个设备与呼叫帮助）→优化（体位、枕垫、头低位）→尝试次数限制（≤3 次，由最有经验者操作）→SGA 过渡→紧急气道","非紧急路径：保留自主呼吸、尝试 SGA、视频喉镜与纤维支气管镜；必要时取消手术延期","紧急路径（CICO）：立即经环甲膜穿刺/切开（14 G 穿刺针或手术刀+探条+小号气切管），同时持续声门上通气","面罩通气的双人法与手工托下颌，口咽/鼻咽通气道；体重过大者斜坡位与枕头","清醒插管（纤维支气管镜/视频喉镜）用于可维持自呼吸的困难气道，表面麻醉 + 右美托咪定","环甲膜切开（紧急气道）后转入外科气道（气管切开）评估；颈椎损伤者手法固定避免过伸","困难气道事件后记录（气道管理表）并随访气道损伤与吸入性肺炎"],"life":["困难气道患者随身携带警示卡，记录所用设备与成功方式","术前评估与气道影像复查，肥胖与 OSA 患者减重与 CPAP 治疗","术后咽喉疼痛、声音嘶哑与气道损伤随访，严重者喉镜/纤维支气管镜检查","建立科室困难气道预案演练与急症车检查制度"]},"prog":"多数困难气道通过 SGA 或视频喉镜成功处理，预后良好；CICO 若环甲膜切开延迟 >3–5 分钟，脑缺氧与死亡风险显著升高（围术期气道相关死亡占麻醉死亡的约 30%）。反复插管尝试增加气道损伤、喉水肿与吸入性肺炎风险，术后需密切随访。","refs":["中华医学会麻醉学分会《困难气道管理专家共识》（2022）","中国医师协会麻醉学医师分会《困难气道处理中国专家共识》","ASA《困难气道管理实践指南》（2022）","Difficult Airway Society《DAS 成人非预期困难气道管理指南》（2015）","中华医学会麻醉学分会《气道管理相关并发症防治专家共识》"]},{"id":"an_la_tox","name":"局麻药全身毒性","aka":["LAST","Local Anesthetic Systemic Toxicity","局麻药中毒"],"rank":3,"basic":{"define":"局麻药误入血管或吸收过量后引起中枢神经系统兴奋/抑制与心脏毒性（心律失常、心肌抑制、心脏骤停）的急症；以布比卡因（尤其 0.75% 用于产科）与左布比卡因心脏毒性最强，脂肪乳剂（lipid emulsion）是特异性解救手段。","risk":["局麻药误入血管（区域阻滞、神经丛阻滞、硬膜外/骶管、伤口浸润时回抽阴性但仍有血管内注射）","局麻药剂量过量（超过最大安全剂量）、注射速度过快与组织血供丰富部位（头皮、颈部、肋间）","老年、低体重、心功能不全与肝功能不全者清除减慢","布比卡因/左布比卡因等心脏毒性药物用于大容量阻滞；肾上腺素共制剂掩盖早期毒性","合并使用其他心脏抑制药物（β 受体阻滞剂、钙通道阻滞剂）"],"epi":"LAST 总体发生率约 0.3–1.8/1000 例区域阻滞，外周神经阻滞约 1/1000–1/2000；布比卡因心脏毒性事件中非致死率约 1/10000，致死率 <1/100000（美国麻醉患者安全基金会数据）；规范使用脂肪乳剂后心脏骤停存活率显著提高（>50% 升至 80% 以上）。"},"patho":"局麻药阻断神经与心肌钠通道。中枢神经系统对低浓度更敏感：先出现兴奋（口周麻木、耳鸣、金属味、谵妄、抽搐），后转为抑制（意识丧失、呼吸抑制与昏迷）；心脏毒性包括传导阻滞、室性心律失常（布比卡因可致顽固性室速/室颤）与心肌收缩力抑制。布比卡因与心肌钠通道解离极慢，心脏毒性可持续数十分钟，且“再毒性”（re-toxicity）常见。脂肪乳剂通过“脂肪池”作用吸附脂溶性局麻药并改善心肌能量代谢，是治疗基石。","dx":{"criteria":["局麻药注射或吸收后出现典型症状：口周/舌麻木、金属味、耳鸣、视物模糊、头晕、言语不清、躁动、抽搐，继而意识丧失与心律失常","心脏毒性表现：PR/QRS 延长、室性早搏、宽 QRS 心动过速、室颤、心脏骤停；低血压、心肌抑制","用药史：剂量超过最大安全量或误入血管（布比卡因 >2 mg/kg、利多卡因 >7 mg/kg、罗哌卡因 >3–4 mg/kg 需警惕，实际阈值个体差异大）","血流动力学与气体分析：低氧、酸中毒（加重心脏毒性）、低血压与心律失常","排除其他原因：过敏反应（荨麻疹、气道水肿、血压骤降）、肾上腺素反应（心悸、血压升高）、血管迷走反射、心肌缺血"],"workup":["心电监护、SpO₂、血压与意识评估（每 1–2 分钟）","动脉血气（乳酸、pH）、电解质与血糖；疑低钠癫痫者检查血钠","心电图识别 QRS 增宽与前驱心律失常","局部阻滞部位评估：回抽是否有血、注药速度与剂量核对；必要时超声确认","必要时床旁心脏超声评估收缩功能与容量","排除过敏：类胰蛋白酶（1–2 小时后）与过敏史"],"grading":"按毒性表现分级（Goodman 改良）：Ⅰ 级（口周麻木、金属味、耳鸣等前驱症状）、Ⅱ 级（躁动、抽搐）、Ⅲ 级（意识丧失、呼吸抑制、昏迷）、Ⅳ 级（心血管崩溃：心律失常、心脏骤停）；治疗应在Ⅰ–Ⅱ 级即开始脂肪乳剂。"},"ddx":[{"name":"恶性高热","point":"与本类中“恶性高热”的鉴别点：LAST 有局麻药注射史，以口周麻木、抽搐与心律失常为核心，体温多正常；MH 有吸入麻醉药/琥珀胆碱暴露史，以 ETCO₂ 骤升、高热、肌僵为特征，二者解救药不同。"},{"name":"困难气道","point":"与本类中“困难气道”的鉴别点：LAST 的非特异性症状（口周麻木、言语不清、呼吸困难）可误判为气道问题，但 LAST 在局麻药注射后出现，气道本身无解剖梗阻。"},{"name":"过敏反应（局麻药过敏罕见，多为酯类）","point":"荨麻疹、面部水肿、支气管痉挛与低血压，肾上腺素为首选；LAST 无荨麻疹且以神经毒性为先。"},{"name":"肾上腺素反应/血管迷走性晕厥","point":"心悸、大汗或心动过缓、低血压伴晕厥，症状短暂且无 QRS 增宽。"},{"name":"癫痫（原发）","point":"无局麻药注射史，抽搐后多见发作后状态，需与局麻药所致抽搐鉴别。"}],"tx":{"drug":[{"name":"20% 脂肪乳剂（Intralipid）","dose":"体重 >70 kg：首剂 100 mL 静推（1.5 mL/kg，2–3 分钟），随后 200–250 mL 以约 0.25 mL/kg/min 输注；<70 kg：首剂 1.5 mL/kg，随后 0.25 mL/kg/min；心脏骤停者首剂后可每 3–5 分钟重复 1 次，总量可达 10–12 mL/kg，持续至循环稳定后 15 分钟","note":"LAST 心脏骤停的基石治疗，越早越好；同时按 ACLS 进行 CPR，避免大剂量利多卡因（加重心脏毒性），可用胺碘酮","renal":"无需调整","hepatic":"无需调整","interact":"与丙泊酚长期输注联用可致脂肪超载；避免与脂肪乳剂混合"},{"name":"肾上腺素（心脏骤停/低血压）","dose":"心脏骤停：按 ACLS 1 mg q3–5min 静推；低血压：0.01–0.1 µg/kg/min 泵入（需注意局麻药毒性中肾上腺素敏感性增高）","note":"LAST 中肾上腺素需小剂量谨慎滴定，避免高血压与心律失常；CPR 时间要足够长（可达 1 小时以上）","renal":"无需调整","hepatic":"无需调整","interact":"与三环类、MAOIs 合用增强升压"},{"name":"苯二氮䓬类（抽搐控制）","dose":"咪达唑仑 2–5 mg 静推（或地西泮 5–10 mg 静推），必要时重复；持续抽搐者丙泊酚 1–2 mg/kg 静推或咪达唑仑泵入","note":"需气道与呼吸支持，抽搐加重酸中毒与心脏毒性","renal":"咪达唑仑代谢产物在肾衰蓄积","hepatic":"肝病减量","interact":"与阿片类协同抑制呼吸"},{"name":"碳酸氢钠（纠正酸中毒）","dose":"8.4% 碳酸氢钠 1–2 mmol/kg 静滴，按血气调整；酸中毒可加重心脏毒性","note":"与脂肪乳剂治疗并行；监测血 pH 与钠","renal":"肾衰者注意钠负荷","hepatic":"无需调整","interact":"与钙剂同通路禁忌"},{"name":"硫酸镁（心律失常）","dose":"1–2 g 静推（10 分钟），用于尖端扭转型室速或顽固性室性心律失常","note":"与脂肪乳剂同用，不作为首选抗心律失常药","renal":"肾衰减量并监测腱反射","hepatic":"无需调整","interact":"与神经肌肉阻滞剂协同"}],"nonDrug":["立即停止注射局麻药、呼救，保持气道通畅，100% 吸氧（低氧加重心脏毒性）","心电监护与有创动脉压（必要时），建立静脉通路（可用大号留置针输注脂肪乳剂）","抽搐时保护气道与防止误吸，必要时肌松与气管插管","心脏骤停：立即 CPR 并尽早使用脂肪乳剂，复苏时间需延长（≥1 小时），必要时体外循环（ECPR）","停用所有可能加重毒性的药物（利多卡因、β 受体阻滞剂、钙通道阻滞剂），避免使用钙通道阻滞剂","预防：超声引导、回抽、分次缓慢注药、用最低有效剂量，计算最大安全剂量（布比卡因 <2 mg/kg、利多卡因 <7 mg/kg）","区域阻滞后持续监测 ≥30 分钟（布比卡因延长至 45–60 分钟）"],"life":["出院前评估神经系统后遗症（抽搐后认知与记忆）与心脏功能","文献报道须知情通报并改进区域阻滞流程（超声 + 分次注药）","脂肪乳剂“脂肪超载”监测（甘油三酯、血小板、肝功能），多可逆","心理支持与再次区域阻滞的风险沟通"]},"prog":"早期识别（Ⅰ–Ⅱ 级）并立即给予脂肪乳剂者多数完全恢复；出现心脏骤停者若脂肪乳剂与 CPR 及时（数分钟内），存活率可达 80% 以上（ASRA 数据），延缓 >15–20 分钟者预后差。晚期可出现“再毒性”，需监测 4–6 小时。部分患者遗留缺血性脑损伤。","refs":["中华医学会麻醉学分会《局麻药全身毒性防治专家共识》（2021）","中国医师协会麻醉学医师分会《外周神经阻滞中国专家共识》（2020）","ASRA《局麻药全身毒性检查表与治疗建议》（2020）","AAGBI《局麻药全身毒性管理指南》（2010）","中华医学会麻醉学分会《区域麻醉与镇痛并发症防治专家共识》"]}]},{"id":"anes_airway2","name":"气道与通气管理","rank":3,"summary":"三大技术风险：①饱胃/反流高危患者用快速序贯诱导（RSI）缩短气道无保护间期；②单肺通气以低潮气量（4–6 mL/kg）、PEEP 5 cmH₂O、限制平台压为核心，低氧按“核位置—调 FiO₂—加 PEEP/CPAP—间断双肺通气”顺序处理；③椎管内麻醉需警惕穿刺后头痛（PDPH）与硬膜外血肿，术后新发下肢无力必须在 6–12 小时内完成 MRI 并减压。","compare":[{"diseaseId":"anes_rsI","dx":"饱胃（末次固体 <6 小时、肠梗阻、妊娠、食管裂孔疝）者需全麻插管：去氮给氧、快速静推肌松、避免面罩正压通气","key":"RSI 防“诱导期反流误吸”；单肺通气管“人工气道建立后”的分侧通气；椎管内并发症涉“穿刺与置管”的神经风险，三者分属诱导、通气与穿刺环节"},{"diseaseId":"anes_onelung","dx":"胸科手术需术侧肺萎陷；单肺通气 SpO₂ <90% 或 PaO₂ <60 mmHg 即为低氧血症","key":"单肺通气低氧多因导管位置与分流，插管顺利不代表位置正确；RSI 相关低氧发生在插管过程中且伴呛咳/反流"},{"diseaseId":"anes_sa","dx":"穿刺后 1–5 天体位性头痛（直立加重、平卧缓解）为 PDPH；新发下肢无力/麻木伴尿潴留为硬膜外血肿，急诊 MRI 确诊","key":"前两者发生于全麻与气道操作，椎管内并发症多发生于清醒/半清醒患者，核心是术后新发神经症状的时效性"}],"diseases":[{"id":"anes_rsI","name":"快速序贯诱导与反流误吸预防","aka":["RSI","Rapid Sequence Induction","Aspiration Prophylaxis"],"rank":1,"basic":{"define":"快速序贯诱导（rapid sequence induction, RSI）针对饱胃或反流误吸高危患者：预氧合后快速静脉注射镇静药与速效肌松药、避免或缩短面罩正压通气、尽快完成气管插管，以缩短气道无保护时间。误吸（aspiration）指胃内容物进入喉以下呼吸道，可致化学性肺炎（Mendelson 综合征）、细菌性肺炎与急性呼吸衰竭。","risk":["饱胃：末次固体 <6 小时、急诊创伤、妊娠 ≥20 周、肠梗阻与胃排空障碍","食管裂孔疝、胃食管反流病、肥胖（BMI ≥35）与食管/胃手术史","急腹症、肠梗阻、上消化道出血与胰腺炎","意识障碍、酒精或药物中毒","困难气道预测阳性合并饱胃（双重风险，需视频喉镜或清醒插管）"],"epi":"围术期误吸发生率约 1/2000–1/6000 例全麻，急诊与产科更高；误吸后吸入性肺炎约占 15%–30%，重症误吸病死率 5%–20%，多见于大量低 pH 胃内容物与肠梗阻。"},"patho":"全麻后食管下括约肌张力下降、咽部保护反射消失，仰卧位胃内容物易反流至咽部。胃容量 >0.4–0.8 mL/kg、pH <2.5 的内容物误吸后引起化学性肺炎：胃酸直接损伤肺泡上皮与毛细血管内皮，致渗透性肺水肿、表面活性物质失活与通气/血流比例失调，48 小时后可继发细菌感染。面罩正压通气可把气体压入胃内、升高胃内压而促进反流，故 RSI 强调“预氧合而非通气”。琥珀酰胆碱起效 45–60 秒、罗库溴铵 1.2 mg/kg 约 60 秒，是缩短无保护间期的药理基础。","dx":{"criteria":["误吸高危：末次固体进食 <6 小时或清饮 <2 小时、肠梗阻/急腹症、妊娠 ≥20 周、胃排空障碍、食管裂孔疝、意识障碍或急诊创伤。","误吸事件：诱导/拔管期胃内容物自口咽涌出或呛咳、SpO₂ 骤降、气道阻力升高、双肺湿啰音或哮鸣音，支气管镜见胃内容物。","吸入性肺炎：误吸后 2 小时内低氧、胸片双下肺浸润（右下叶多见），可伴发热；误吸 48 小时后新发发热与脓痰提示继发细菌感染。","困难气道预测：Mallampati Ⅲ–Ⅳ 级、张口度 <3 cm、甲颏距离 <6 cm、颈围 >40 cm、颈椎活动受限。"],"workup":["病史：末次进食种类与时间、反酸烧心、肠梗阻症状、既往麻醉与胃手术史、妊娠周数","肠梗阻者查腹部立位平片/CT；择期胃排空障碍者行胃镜","术前用药：质子泵抑制剂或 H₂ 受体拮抗剂静脉抑酸、甲氧氯普胺 10 mg 静推促胃动力（肠梗阻禁用），必要时鼻胃管减压","气道后备方案与抢救设备就位：视频喉镜、纤维支气管镜、环甲膜切开包、脂肪乳","心电、SpO₂ 与呼气末 CO₂ 监测（确认导管位置最关键），高危者行有创动脉压监测"],"grading":"RSI 方案分层：标准 RSI（无困难气道预测，首选视频喉镜）；改良 RSI（合并困难气道预测，允许有限低压正压通气并备清醒插管）；延迟序贯诱导（DSI，仅高流量经鼻吸氧 + 小剂量镇静，用于储备极低的危重患者）。"},"ddx":[{"name":"单肺通气与低氧处理（本类 anes_onelung）","point":"与本类中“单肺通气”的鉴别点：单肺通气低氧发生在导管置入后单侧通气期间，处理核心是核对导管位置与通气策略；RSI 相关低氧发生在诱导插管过程，伴呛咳、反流或气道显露困难。"},{"name":"椎管内麻醉并发症（本类 anes_sa）","point":"与本类中“椎管内麻醉并发症”的鉴别点：椎管内并发症发生在穿刺/置管后，表现为头痛或下肢神经症状；RSI 的并发症是反流误吸、肌松药过敏与插管失败。"},{"name":"困难气道（an_airway）","point":"与 anes_1.json 中“困难气道”的鉴别点：困难气道指面罩通气、喉镜暴露或插管本身困难，RSI 关注缩短无保护间期；两者合并时需预先确立“插管失败—通气失败”预案（SGA + 环甲膜切开）。"},{"name":"诱导后低血压/心律失常","point":"需区分药物（丙泊酚、肌松药组胺释放）、容量不足与过敏；琥珀酰胆碱可致心律失常（高钾风险者），需与过敏的心动过速伴皮疹鉴别。"}],"tx":{"drug":[{"name":"丙泊酚（诱导镇静）","dose":"1.5–2.5 mg/kg 静推（RSI 常 2–2.5 mg/kg）；休克或心功能不全者减至 0.5–1.5 mg/kg，或选依托咪酯 0.2–0.3 mg/kg","note":"RSI 中镇静药先于肌松药快速推注；低血容量与老年患者减量缓慢推注","renal":"遵说明书","hepatic":"肝硬化者清除减慢、分布容积增大，减量","interact":"与阿片类、苯二氮䓬类协同抑制循环与呼吸"},{"name":"琥珀酰胆碱","dose":"1–1.5 mg/kg 静推，起效 45–60 秒，作用持续 5–10 分钟","note":"禁忌：高钾风险（烧伤 >24–72 小时、挤压伤、脊髓损伤 3 天–6 个月、长期制动、神经肌肉病）、恶性高热家族史、青光眼/眼球破裂","renal":"尿毒症或高钾血症者避免使用","hepatic":"假性胆碱酯酶合成减少者作用延长，遵说明书","interact":"氨基糖苷类、镁剂、吸入麻醉药延长作用；可诱发恶性高热"},{"name":"罗库溴铵","dose":"1.2 mg/kg 静推，起效约 60 秒","note":"无高钾风险，适用于琥珀酰胆碱禁忌者；插管失败需恢复自主呼吸时用舒更葡糖 16 mg/kg 立即拮抗","renal":"肾功能不全者作用稍延长，单次 1.2 mg/kg 通常可接受","hepatic":"严重肝病者作用延长","interact":"吸入麻醉药、镁剂、氨基糖苷类增强肌松；舒更葡糖降低口服避孕药疗效"},{"name":"舒更葡糖（Sugammadex）","dose":"16 mg/kg 静推（用于罗库溴铵 1.2 mg/kg 后立即逆转）","note":"不能逆转琥珀酰胆碱或阿曲库铵；用于“插管失败、需紧急恢复自主呼吸”，需同步启动困难气道流程","renal":"eGFR <30 者不推荐","hepatic":"无需调整","interact":"降低口服避孕药疗效，需额外避孕 7 天"},{"name":"奥美拉唑/雷尼替丁（术前抑酸）","dose":"奥美拉唑 40 mg 静推或雷尼替丁 50 mg 静推（术前 1 次）","note":"降低胃内容物酸度、减轻误吸后化学性肺炎；机械性肠梗阻禁用促胃动力药","renal":"肾功能不全者 H₂ 受体拮抗剂减量","hepatic":"严重肝病者无需调整","interact":"奥美拉唑经 CYP2C19 代谢，与氯吡格雷合用可降低其抗血小板作用"}],"nonDrug":["100% 氧预氧合 ≥3 分钟（经鼻高流量可延长安全时限），不面罩正压通气，喉镜显露至导管到位目标 <60 秒","环状软骨压迫按科室方案，证据有限，不得因压迫延迟插管","饱胃合并明确困难气道者可行清醒纤支镜/视频喉镜插管，保留自主呼吸与气道保护反射","插管后立即以呼气末 CO₂ 波形确认位置，置胃管减压并头高位 30°","困难气道按“声门上气道—环甲膜切开”流程保障氧合","误吸后立即头低位、吸引口咽与气管，必要时支气管镜清理，复查胸片与血气"],"life":["严格执行禁食标准（清饮 2 小时、母乳 4 小时、固体 6 小时），未达标择期手术应推迟","术后头高位、监测体温与 SpO₂，误吸高危者术后 2 小时复查胸片","术前戒烟、控制 GERD 症状，告知禁食对防止误吸的重要性","术后早期活动与呼吸训练，减少肺部并发症"]},"prog":"规范 RSI 插管失败率约 0.1%–0.5%，误吸相关显著并发症约 1/3000–1/10000 例，多数为短暂血氧下降或轻度化学性肺炎、24–48 小时缓解；大量误吸或肠梗阻内容物误吸者重症肺炎与 ARDS 风险升高，病死率 5%–20%。视频喉镜与充分预氧合可提高首次插管成功率。","refs":["中华医学会麻醉学分会《困难气道管理专家共识》（2017）","中华医学会麻醉学分会《成人非心脏手术术前禁食专家共识》（2014）","中华医学会麻醉学分会《急诊手术麻醉指南》","ASA《Practice Guidelines for Preoperative Fasting and the Use of Pharmacologic Agents to Reduce the Risk of Pulmonary Aspiration》（2017）","Difficult Airway Society《Guidelines for Management of Unanticipated Difficult Intubation in Adults》（2015）"]},{"id":"anes_onelung","name":"单肺通气与低氧处理","aka":["OLV","One-Lung Ventilation","肺隔离"],"rank":2,"basic":{"define":"单肺通气（one-lung ventilation, OLV）经双腔支气管导管或支气管封堵器使术侧肺隔离萎陷、仅对非术侧（依赖侧）肺通气，用于胸科、食管与纵隔手术。有效通气肺容积减半、缺氧性肺血管收缩（HPV）受抑与通气/血流比例失调，可致低氧血症。","risk":["术侧肺疾病（肺炎、肺不张、脓胸）与对侧肺疾病（COPD、肺气肿、肺挫伤）","侧卧位与开胸、肺萎陷不充分或过度、导管位置异常","单肺通气时间长、潮气量与气道压设置不当","严重肺气肿、肺切除术后残余肺功能差与支气管胸膜瘘","肺移植、气管手术等特殊气道管理"],"epi":"单肺通气期间低氧血症（SpO₂ <90% 或 PaO₂ <60 mmHg）发生率约 5%–10%，多数短暂；持续 SpO₂ <85% 约 1%–2%。采用低潮气量 + PEEP 肺保护策略后肺切除术后肺部并发症显著下降。"},"patho":"非通气侧肺仍接受部分心排血量灌注，形成右向左分流，静脉血未经氧合进入体循环。缺氧性肺血管收缩（HPV）使非通气肺血管阻力升高、血流转向通气肺，是代偿机制，通常在单肺通气 20–30 分钟达高峰。术侧肺萎陷不充分、导管移位、对侧肺过度通气与高气道压加重通气/血流比例失调；PEEP 过高则减少通气肺灌注、加重分流。","dx":{"criteria":["单肺通气适应证：胸科、纵隔肿瘤、食管手术、胸腔镜、肺切除及需肺隔离的大咯血/脓胸。","低氧血症：单肺通气期间 SpO₂ <90% 持续 >30 秒或 FiO₂ 1.0 下 PaO₂ <60 mmHg，排除导管位置错误与循环不稳定。","气道压提示：平台压 >25–30 cmH₂O 或较双肺通气升高 >10 cmH₂O，提示导管位置异常、顺应性下降或通气策略不当。","支气管镜定位：蓝套囊位于隆突近端、左主支气管开口可见；体位改变后必须复查。"],"workup":["术前肺功能：FEV₁ 与 DLCO，ppoFEV₁ <40% 预测值者需进一步评估","胸部 CT 与支气管镜：明确肿瘤位置、气道内病变与是否全肺切除","术中监测：有创动脉压、呼气末 CO₂、SpO₂、气道压力与容量，必要时中心静脉压或经食管超声","单肺通气开始 15–30 分钟查动脉血气，指导 FiO₂ 与 PEEP 调整","导管选择：男性 37–39 F、女性 35–37 F，儿童与困难气道用封堵器"],"grading":"按隔离方式分双腔管法与支气管封堵器法；低氧按 PaO₂ 分轻度（60–80 mmHg）、中度（40–60 mmHg）与重度（<40 mmHg）。保护性单肺通气：潮气量 4–6 mL/kg（预测体重）、PEEP 5 cmH₂O、平台压 ≤25 cmH₂O、FiO₂ 下调至维持 SpO₂ ≥95%。"},"ddx":[{"name":"快速序贯诱导与反流误吸（本类 anes_rsI）","point":"与本类中“快速序贯诱导”的鉴别点：单肺通气低氧在双腔管/封堵器置入并开始单侧通气后出现，关键是支镜核对位置；RSI 相关低氧发生于诱导与插管过程，伴反流与呛咳。"},{"name":"椎管内麻醉并发症（本类 anes_sa）","point":"与本类中“椎管内麻醉并发症”的鉴别点：单肺通气是全身麻醉下的通气问题（低氧、气道压高），椎管内并发症为穿刺后头痛或脊髓受压，麻醉方式与临床表现完全不同。"},{"name":"困难气道（an_airway）","point":"与 anes_1.json 中“困难气道”的鉴别点：困难气道是插管困难本身，单肺通气低氧更多源于导管位置与分流，插管顺利不代表双腔管位置正确。"},{"name":"术中支气管痉挛/过敏反应","point":"气道阻力骤升伴呼气末 CO₂ 波形上升段变斜与喘息，可伴皮疹与低血压；单肺通气低氧经调 FiO₂、PEEP 与吸痰后可改善，无过敏皮肤表现。"}],"tx":{"drug":[{"name":"通气参数调整（FiO₂/PEEP/CPAP，属“器械参数”）","dose":"FiO₂ 升至 1.0；通气侧 PEEP 5–10 cmH₂O；术侧 CPAP 1–2 cmH₂O（部分方案 5 cmH₂O）；肺复张 20–30 cmH₂O 持续 10–15 秒（按科室方案）","note":"PEEP 个体化滴定，避免过度 PEEP 降低通气侧肺血流；需与外科沟通暂停操作行双肺通气","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"去氧肾上腺素","dose":"50–100 µg 静推，按血压重复；持续泵入 0.5–2 µg/kg/min（遵科室方案）","note":"α 激动剂升高体循环阻力，可使肺血流由非通气肺向通气肺重分布、减少分流；注意心率与冠脉灌注","renal":"肾功能不全者血压目标个体化","hepatic":"严重肝病者药效延长，减量","interact":"与单胺氧化酶抑制剂合用可致高血压危象"},{"name":"硝酸甘油","dose":"0.5–1 µg/kg/min 静脉泵入，按血压滴定（遵说明书）","note":"肺动脉高压或右心功能不全者可在维持体循环压前提下降低肺血管阻力，但可能加重分流","renal":"严重肾功能不全慎用","hepatic":"肝病者代谢减慢，减量","interact":"禁与磷酸二酯酶 5 抑制剂（西地那非）合用，可致严重低血压"},{"name":"沙丁胺醇（支气管痉挛时）","dose":"2.5–5 mg 雾化吸入或经气管导管给药；必要时肾上腺素 10–20 µg 静推（遵说明书）","note":"用于低氧伴气道阻力升高与喘息，需先排除导管移位、痰栓与肺水肿","renal":"遵说明书","hepatic":"遵说明书","interact":"与非选择性 β 受体阻滞剂合用时疗效降低"}],"nonDrug":["首先纤维支气管镜核对双腔管/封堵器位置：过深拔出 1–2 cm、过浅推进，体位改变后复查","处理顺序：FiO₂ 1.0 → 清除通气侧肺分泌物 → 通气侧 PEEP 与肺复张 → 术侧 CPAP → 间断双肺通气","维持心排血量与平均动脉压，使用血管加压药或正性肌力药，避免过度液体负荷","低氧持续者请外科暂停操作、恢复双肺通气或改为开放胸腔；术毕复查支气管镜","术后肺保护性通气，早期拔管或过渡至无创通气"],"life":["术前戒烟 ≥4 周（至少 2 周）、呼吸训练与预康复","术后胸段硬膜外或椎旁阻滞镇痛，保障深呼吸与咳痰、早期活动","术后 48 小时监测 SpO₂ 与呼吸功，警惕肺炎与肺不张","长期随访肺功能与肿瘤治疗计划"]},"prog":"多数单肺通气低氧经核对导管位置与调整参数可迅速纠正，极少数需放弃肺隔离。低潮气量 + PEEP 肺保护策略可使肺切除术后肺部并发症降低约 30%–50%、缩短住院日。术后肺部并发症仍是胸科手术主要死因之一。","refs":["中华医学会麻醉学分会《胸科手术单肺通气专家共识》（2018）","中华医学会麻醉学分会《肺保护性通气策略专家共识》","中华医学会麻醉学分会《胸外科手术麻醉指南》","欧洲胸心麻醉学会（EACTA）《单肺通气指南》（2019）"]},{"id":"anes_sa","name":"椎管内麻醉并发症（穿刺后头痛与硬膜外血肿）","aka":["PDPH","Epidural Hematoma","Spinal/Epidural Complications"],"rank":3,"basic":{"define":"椎管内麻醉（腰麻、硬膜外及腰硬联合）并发症包括穿刺后头痛（post-dural puncture headache, PDPH）、硬膜外血肿与脊髓受压、硬膜外脓肿、局麻药全身毒性及持续性神经损伤。PDPH 为硬脊膜穿破后脑脊液持续漏出、颅内低压所致体位性头痛；硬膜外血肿是硬膜外间隙出血压迫脊髓，属需即刻识别的急症。","risk":["PDPH：粗针（腰麻 25–27 G 风险低）、硬膜外意外穿破硬膜（1%–2%）、年龄 <40 岁、女性、妊娠与产后、低 BMI、既往 PDPH 史","硬膜外血肿：凝血障碍（INR >1.5、血小板 <80×10⁹/L）、抗凝/抗血小板治疗、脊柱畸形与反复穿刺、高龄","感染：糖尿病、免疫抑制、置管 >48–72 小时、无菌操作不严","神经损伤：穿刺困难、局麻药浓度过高或容量过大"],"epi":"PDPH 总体发生率约 0.5%–1%，硬膜外意外穿破硬脊膜后升至 50%–80%，27 G 笔尖式腰麻针后约 0.2%–1%。椎管内血肿约 1/10 万–1/50 万例，合并抗凝者显著升高，减压延迟 >12 小时约半数遗留永久神经缺损。硬膜外脓肿约 1/1 万–1/2 万。"},"patho":"PDPH：硬膜穿破后脑脊液持续外漏、颅内压下降，脑组织下沉牵拉脑膜与血管等痛觉敏感结构，形成“直立加重、平卧缓解”的体位性头痛，可伴颈强、恶心、耳鸣与听力下降，偶有第 Ⅵ 颅神经麻痹。硬膜外血肿：硬膜外静脉丛创伤性出血形成血肿压迫脊髓与神经根，数小时内可进展为不可逆脊髓缺血与瘫痪。","dx":{"criteria":["PDPH（ICHD-3）：硬/蛛网膜穿破后 5 天内出现头痛，直立 15 分钟内加重、平卧 30 分钟内缓解，伴颈强、耳鸣、畏光或恶心，无其他病因可解释。","硬膜外血肿：椎管内麻醉后新发下肢无力/瘫痪、感觉平面上升、尿潴留或背痛，立即行全脊柱 MRI，确诊后 6–12 小时内手术减压。","硬膜外脓肿：穿刺后 3–7 天发热、背痛、局部压痛与进行性神经功能障碍，MRI 增强可见硬膜外脓肿。","PDPH 严重度：轻度（可耐受、不影响哺乳）、中度（需卧床、影响日常）、重度（卧床不起，伴恶心呕吐、视物模糊）。"],"workup":["记录头痛与体位关系、持续时间，排除偏头痛与紧张性头痛（非体位性）","神经系统查体：肌力、感觉平面、反射与病理征；疑血肿者每 30–60 分钟复评","PDPH 多无需影像，MRI 可示脑膜强化与脑下垂；需排除颅内静脉窦血栓","硬膜外血肿：急诊全脊柱 MRI（T2 见硬膜外高信号压迫脊髓），无法 MRI 者行 CT","凝血功能（PT/INR、aPTT、血小板）与抗凝药史核对","穿刺后发热 + 背痛：血培养、CRP、MRI 增强排除脓肿"],"grading":"PDPH 按 ICHD-3 分急性（<3 个月）与持续（>3 个月），按严重度分轻/中/重度。硬膜外血肿高危因素：穿刺困难、凝血异常、年龄 >60 岁，术后新发神经功能异常即为警示。"},"ddx":[{"name":"快速序贯诱导与反流误吸（本类 anes_rsI）","point":"与本类中“快速序贯诱导”的鉴别点：椎管内并发症发生于穿刺/置管后，多为清醒或半清醒状态下表现为头痛或神经症状；RSI 并发症发生于全麻诱导，表现为反流、呛咳与低氧。"},{"name":"单肺通气与低氧处理（本类 anes_onelung）","point":"与本类中“单肺通气”的鉴别点：单肺通气低氧源于分流与导管位置，属通气事件；椎管内并发症可经交感阻滞致低血压，但与通气无关，新发下肢无力是警示信号。"},{"name":"术后谵妄与术后认知障碍（anes_ponv_refract）","point":"与 anes_critical 类中“术后谵妄”的鉴别点：谵妄为意识波动与注意力障碍，多发生于老年全麻患者；椎管内并发症为局灶性运动/感觉缺失与尿潴留，查体可定位。"},{"name":"偏头痛/紧张性头痛与穿刺后脑膜炎","point":"偏头痛与紧张性头痛不随体位缓解；穿刺后 3 天以上发热、颈强需考虑脑膜炎，应行脑脊液检查并经验性抗感染。"}],"tx":{"drug":[{"name":"咖啡因","dose":"咖啡因 300–500 mg 口服，或苯甲酸钠咖啡因 500 mg 静脉缓慢输注（遵说明书），可重复 1–2 次","note":"经脑血管收缩缓解 PDPH；可致心悸与焦虑，避免与高剂量茶碱合用","renal":"严重肾功能不全慎用","hepatic":"严重肝病者代谢减慢，减量","interact":"喹诺酮类、氟伏沙明增高咖啡因浓度"},{"name":"对乙酰氨基酚/NSAIDs","dose":"对乙酰氨基酚 1 g q6h 静/口服；布洛芬 400 mg q8h（遵说明书）","note":"对症治疗；疑硬膜外血肿者禁用 NSAIDs，肾功能不全者避免","renal":"eGFR <30 者避免 NSAIDs","hepatic":"肝功能不全者对乙酰氨基酚每日 ≤2 g","interact":"NSAIDs 与抗凝药合用增加出血风险"},{"name":"地塞米松（仅作脊髓水肿辅助）","dose":"10–20 mg 静推（遵说明书）","note":"仅用于硬膜外血肿/脓肿辅助减轻脊髓水肿，不能替代手术减压；PDPH 不常规使用","renal":"遵说明书","hepatic":"遵说明书","interact":"升高血糖，与降糖药作用拮抗"},{"name":"广谱抗生素（硬膜外脓肿）","dose":"经验性静脉用药，如头孢曲松 2 g q12h + 万古霉素，按药敏与肾功调整（遵说明书）","note":"取血培养后尽早给药，进展或脓液积聚者需外科减压引流","renal":"万古霉素按肾功能调整并监测谷浓度","hepatic":"无需调整","interact":"万古霉素与氨基糖苷类、呋塞米合用增加肾毒性"}],"nonDrug":["PDPH 保守：仰卧休息、充足饮水、避免用力，加用咖啡因与镇痛，多数 1–2 周自愈","硬膜外血肿：立即停抗凝、联系神经外科，6–12 小时内椎板切除减压；每 30–60 分钟查神经功能","穿刺前按指南核对抗凝停药（低分子肝素 12–24 小时、DOAC 48–72 小时、氯吡格雷 5–7 天）并纠正凝血异常","PDPH 持续 >1 周或重度：硬膜外血补片（EBP，自体血 15–20 mL）","硬膜外脓肿：外科减压 + 引流，抗生素通常 ≥6 周（遵感染科）","操作规范：超声引导、严格无菌、消毒液待干，置管 ≤48–72 小时并每日查看穿刺点"],"life":["PDPH 缓解后逐步活动，避免剧烈咳嗽与脱水；哺乳期可正常哺乳","穿刺后 24–48 小时观察下肢力量与排尿，宣教“新发无力、麻木、不能排尿立即返院”","术后疼痛管理与早期活动防深静脉血栓，恢复抗凝前先评估拔管时间","血肿减压后每月随访神经功能，残留障碍者行康复训练"]},"prog":"PDPH 多数 1–2 周自愈，约 10%–20% 超过 1 周，EBP 有效率 >80%–90%。硬膜外血肿 6–12 小时内减压约 70%–80% 患者神经功能基本恢复，延迟 >12–24 小时者永久损伤或截瘫风险显著升高。硬膜外脓肿早期治疗病死率 <5%，延误可 >20%。","refs":["中华医学会麻醉学分会《椎管内麻醉专家共识》（2020）","中华医学会麻醉学分会《围术期抗栓药物管理专家共识》（2022）","ASRA《Regional Anesthesia in the Patient Receiving Antithrombotic or Thrombolytic Therapy: Fifth Edition》（2018）","International Headache Society《ICHD-3 头痛疾病国际分类》（2018）"]}]},{"id":"anes_critical","name":"围术期危重症","rank":4,"summary":"主线是“快速识别 + 目标导向复苏”：大出血遵循大量输血方案（MTP）1:1:1 并配合氨甲环酸与损伤控制；术中过敏立即停可疑药物、肾上腺素静脉分次给药并快速扩容；术后谵妄以非药物预防为主，术后认知障碍重在风险沟通与早期认知康复。","compare":[{"diseaseId":"anes_hemorrhage","dx":"术中/术后失血伴低血压、心动过速、Hb 下降；休克指数 >1、乳酸 >4 mmol/L 或碱缺失 >6 mEq/L 提示大出血，启动 MTP","key":"大出血以“失血与低灌注”为核心，靠输血与止血；过敏休克以“过敏原暴露后低血压 + 气道/皮肤表现”为特征，靠肾上腺素，两者机制相反、易混淆"},{"diseaseId":"anes_anaphylaxis","dx":"给药后数分钟内低血压、支气管痉挛、皮疹或血管性水肿；术中常以不明原因低血压伴气道阻力升高为首发，血类胰蛋白酶可确诊","key":"过敏休克常在大出血复苏中被漏诊；鉴别线索为暴露时序、气道阻力骤升与对血制品的反应差，而对肾上腺素反应快"},{"diseaseId":"anes_ponv_refract","dx":"术后 1–7 天注意力障碍、意识波动、幻觉与睡眠节律紊乱（CAM/4AT 阳性）；POCD 为术后 1 周–3 个月记忆与执行功能下降","key":"前两者为急性生理性危象（循环与凝血、免疫），谵妄与认知障碍为术后中枢神经功能问题，靠 CAM 与神经心理测评识别"}],"diseases":[{"id":"anes_hemorrhage","name":"围术期大出血与输血","aka":["Massive Hemorrhage","Massive Transfusion Protocol","MTP"],"rank":1,"basic":{"define":"围术期大出血指失血 >1500 mL、>30% 估计血容量或 3 小时内输血 >50% 血容量，引起低血容量性休克、稀释性凝血病、低体温与酸中毒，需启动大量输血方案（massive transfusion protocol, MTP）——短时间内按比例输注红细胞、血浆、血小板与凝血因子，同时外科/介入止血。","risk":["创伤、肝脾破裂、大血管损伤、骨盆骨折与产科大出血（胎盘植入、产后出血）","术前贫血（Hb <100 g/L）与抗凝/抗血小板治疗","高龄、休克、低体温与 ASA Ⅲ 级以上合并症","巨大肿瘤切除、脊柱手术、器官移植与长时间手术"],"epi":"严重创伤是 1–44 岁人群首位死因，约 30%–40% 创伤死亡由大出血所致；院内大出血病死率 20%–40%。伤后 3–24 小时约 25%–35% 严重创伤出现急性创伤性凝血病（ATC），合并者病死率升至 3–4 倍。"},"patho":"有效循环血量下降致组织低灌注与乳酸酸中毒；大量输注晶体/红细胞稀释凝血因子与血小板，叠加低体温（<35 ℃ 抑制凝血酶与血小板功能）与酸中毒（pH <7.2 抑制凝血因子活性），构成“致死三联征”（凝血病、低体温、酸中毒）。创伤与休克还致纤溶亢进与糖萼损伤，加重出血。大量输血（>10 U 红细胞）可致高钾、低钙（枸橼酸螯合）、TRALI 与循环超负荷。","dx":{"criteria":["大出血临床评分（ABC）：脉冲式出血、不能控制的活动性出血、生命体征异常（SBP <90 mmHg、HR >110 次/分、休克指数 >1）各计 1 分，≥2 分启动 MTP。","休克指数（HR/SBP）>1.0 提示中度失血，>1.5 提示重度。","失血分级：Ⅰ 级 <15%、Ⅱ 级 15%–30%（心动过速）、Ⅲ 级 30%–40%（低血压）、Ⅳ 级 >40%（严重休克）。","急性创伤性凝血病：INR >1.2–1.5、aPTT >上限 1.5 倍、纤维蛋白原 <1.5–2.0 g/L、血小板 <100×10⁹/L；TEG/ROTEM 示凝血启动延迟或强度不足。"],"workup":["快速评估 ABCS，有创动脉压与中心静脉压，对照基础贫血情况","实验室：血常规、凝血（PT/INR、aPTT、纤维蛋白原）、血气（乳酸、碱缺失、离子钙）、血型与抗体筛查、肾功能与电解质","床旁血栓弹力图（TEG/ROTEM）指导成分输血；血气每 30–60 分钟复查","FAST 超声、全身 CT（稳定者）与血管造影（DSA）","监测尿量、体温（维持 ≥36 ℃）与中心静脉血氧饱和度"],"grading":"按失血比例分 Ⅰ–Ⅳ 级；MTP 起始配比 1:1:1，持续至出血控制；严重创伤合并休克建议 3 小时内氨甲环酸 1 g 负荷后 8 小时再输 1 g。"},"ddx":[{"name":"术中过敏休克（本类 anes_anaphylaxis）","point":"与本类中“术中过敏休克”的鉴别点：大出血有活动性出血证据、Hb/SpO₂ 下降且对扩容与输血有反应；过敏休克在暴露过敏原后突发低血压伴气道阻力升高、皮疹或水肿，扩容反应差、肾上腺素反应迅速。"},{"name":"术后谵妄与术后认知障碍（本类 anes_ponv_refract）","point":"与本类中“术后谵妄”的鉴别点：大出血是循环与凝血的急性危象，伴低血压、贫血与凝血异常；谵妄是注意力与意识障碍的中枢并发症，生命体征可平稳。"},{"name":"腰麻后低血压（交感阻滞）","point":"麻醉平面以下血管扩张致低血压，伴阻滞平面与心率变化，Hb 正常、无活动性出血，补液与血管加压药可迅速纠正。"},{"name":"局麻药中毒（an_la_tox）","point":"与 anes_1.json 中“局麻药中毒”的鉴别点：有明确注药史，表现为口周麻木、耳鸣、抽搐与心律失常，需脂肪乳与抗惊厥治疗，而非以失血为主要机制。"}],"tx":{"drug":[{"name":"红细胞输注","dose":"Hb <70 g/L 输注（合并心血管病者 <80 g/L 考虑）；大出血按 1:1:1 配输，1 U 约升 Hb 10 g/L","note":"活动性出血期维持 Hb 70–90 g/L，避免循环超负荷；紧急时用 O 型血","renal":"大量输注警惕高钾","hepatic":"肝病者目标可个体化","interact":"大量输注致枸橼酸蓄积，需监测并补钙"},{"name":"新鲜冰冻血浆（FFP）","dose":"与红细胞 1:1 配比，起始 10–15 mL/kg；INR >1.5 伴活动性出血时输注","note":"纠正稀释性凝血病，快速输注；注意过敏与 TRALI","renal":"循环超负荷者减慢输注并利尿","hepatic":"凝血因子合成不足者增加用量","interact":"遵说明书"},{"name":"血小板","dose":"1 治疗量（约 5–6 U 单采），活动性出血且血小板 <50×10⁹/L 时输注；脑/眼科手术维持 <100×10⁹/L","note":"按 1:1:1 补充，TEG MA 值下降时优先补血小板","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"氨甲环酸（TXA）","dose":"1 g 静推 10 分钟，随后 1 g 输注 8 小时；产科出血 1 g 静推可重复 1 g","note":"出血 3 小时内使用获益最大，超过 3 小时启动可能增加血栓风险","renal":"CrCl <30 者减量（遵说明书）","hepatic":"无需调整","interact":"与抗凝药合用时降低抗凝效应"},{"name":"纤维蛋白原浓缩物/冷沉淀","dose":"纤维蛋白原 <1.5 g/L（产科 <2.0 g/L）时补充；冷沉淀 10 U 或纤维蛋白原浓缩物 2–4 g（遵说明书）","note":"TEG FIBTEM 振幅低或出血量大时优先；冷沉淀融化后尽快输注","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"葡萄糖酸钙/氯化钙","dose":"10% 葡萄糖酸钙 1 g 缓慢静推，离子钙 <1.1 mmol/L 时补充，每输 4 U 红细胞可预防性补钙一次","note":"大量输血致低钙，负性肌力与凝血障碍；氯化钙经中心静脉稀释后使用，警惕外渗","renal":"肾衰者注意钙累积","hepatic":"无需调整","interact":"与头孢曲松、碳酸氢钠配伍禁忌"},{"name":"去甲肾上腺素/苯肾上腺素","dose":"去甲肾上腺素 0.05–0.5 µg/kg/min 泵入；苯肾上腺素 50–100 µg 静推，按血压滴定","note":"止血前可允许性低血压（SBP 80–90 mmHg，颅脑损伤除外），止血后恢复目标血压","renal":"遵说明书","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用可致严重高血压"}],"nonDrug":["启动 MTP：通知输血科、开放 2 条大口径静脉、送检标本与床旁 TEG，按 1:1:1 持续输注至止血","外科/介入止血：损伤控制手术（填塞、血管结扎）、骨盆外固定、REBOA 与 DSA 栓塞","损伤控制复苏：限制晶体液（避免 >1–2 L）、允许性低血压、尽早输血、保温（输液加温、覆盖）与纠酸","并发症管理：高钾、低钙、TRALI 与循环超负荷，监测尿量与电解质","止血后目标：Hb 70–90 g/L、血小板 ≥50×10⁹/L、纤维蛋白原 ≥1.5 g/L、INR ≤1.5、体温 ≥36 ℃"],"life":["术后 24–48 小时 ICU 监测 Hb、凝血功能与乳酸","早期康复、营养支持，出血控制 24–48 小时后评估血栓预防","口服铁剂 100–200 mg/日纠正缺铁性贫血（遵说明书），随访凝血与器官功能","择期患者术前纠正贫血（Hb ≥100 g/L）并规范停用抗凝药"]},"prog":"大出血病死率 20%–40%，合并创伤性凝血病者可升至 30%–50%；及时启动 MTP 与 1:1:1 配比、尽早止血可改善早期生存（PROPPR 研究减少早期止血失败与死亡）。输血相关 TRALI、循环超负荷与感染需持续监测。","refs":["中华医学会麻醉学分会《围术期输血管理专家共识（2021 版）》","国家卫生健康委员会《临床输血技术规范》","欧洲创伤复苏指南（European Guideline on Management of Major Bleeding and Coagulopathy Following Trauma, 2023）","ASA《Practice Guidelines for Perioperative Blood Management》（2015）"]},{"id":"anes_anaphylaxis","name":"术中过敏休克（围术期过敏反应）","aka":["Perioperative Anaphylaxis","Anaphylactic Shock"],"rank":2,"basic":{"define":"围术期过敏反应指围术期暴露于药物、消毒剂、乳胶或血液制品后出现的快速严重过敏反应，表现为支气管痉挛、皮肤黏膜改变、循环崩溃或多系统受累。术中因体位与覆盖皮肤表现常不可见，常以“不明原因低血压伴气道阻力升高”为首发，可迅速进展为过敏性休克。","risk":["既往药物过敏史（青霉素、头孢类、肌松药、乳胶、氯己定）与哮喘、肥大细胞增多症","肌松药（罗库溴铵、琥珀酰胆碱、顺阿曲库铵）为最常见诱因之一，其次为抗生素与氯己定消毒剂","多次手术麻醉史与女性","使用 β 受体阻滞剂与 ACEI 可加重严重度与治疗难度"],"epi":"围术期过敏反应约 1/3000–1/20000 例麻醉，肌松药相关占 30%–60%，抗生素约 20%–30%。严重过敏（Ⅲ–Ⅳ 级）约 1/10000，围术期过敏相关病死率约 1%–6%，延迟诊断与肾上腺素剂量不足是主要可避免死因。"},"patho":"IgE 介导的 Ⅰ 型超敏反应：过敏原与肥大细胞/嗜碱性粒细胞表面 IgE 交联，脱颗粒释放组胺、类胰蛋白酶、白三烯与前列腺素，引起全身小血管扩张与毛细血管通透性增加（血管性水肿、低血容量性休克）、支气管平滑肌痉挛与黏液分泌增加。部分药物（万古霉素、肌松药、阿片）可经非 IgE 机制直接激活肥大细胞（类过敏反应）。严重者喉头水肿与循环崩溃，数分钟内可致心跳骤停。","dx":{"criteria":["临床诊断：急性起病（数分钟至数小时）且①皮肤黏膜受累（荨麻疹、潮红、唇舌肿胀）+ 气道/呼吸问题（支气管痉挛、喉头水肿、低氧）；或②暴露可能过敏原后突发低血压或支气管痉挛，两者满足其一。","术中表现：不明原因低血压（SBP <90 mmHg 或较基础下降 >30%）伴气道阻力骤升、SpO₂ 下降、潮红或荨麻疹，需与失血、麻醉过深、心肌缺血与肺栓塞鉴别。","围术期过敏分级（Ring & Messmer）：Ⅰ 级皮肤症状；Ⅱ 级轻度全身反应；Ⅲ 级支气管痉挛、低血压加重；Ⅳ 级心跳骤停。","确诊：反应后 1–2 小时内血清类胰蛋白酶 >基线 1.2 倍且 >2 ng/mL 有意义；恢复期（4–6 周）查特异性 IgE 或皮肤试验。"],"workup":["识别时序：给药后 1–5 分钟出现症状最具提示性，记录生命体征、气道阻力与双肺哮鸣音","排除鉴别：失血、麻醉过深、肺栓塞、急性心肌梗死与恶性高热同时评估","急性期：动脉血气（低氧、酸中毒）、乳酸、血常规、类胰蛋白酶（1–2 小时内）、床旁超声看心脏充盈","恢复期过敏原确认：停药 ≥4 周后皮肤点刺/皮内试验、特异性 IgE、嗜碱性粒细胞活化试验","核对可疑药物：肌松药、β-内酰胺类、氯己定、乳胶与血制品，保留用药批号"],"grading":"Ring & Messmer Ⅰ–Ⅳ 级（Ⅰ 皮肤、Ⅱ 轻度全身、Ⅲ 严重危及生命、Ⅳ 心跳骤停）；按受累器官（皮肤/气道/循环）分级可提高识别灵敏度。"},"ddx":[{"name":"围术期大出血与输血（本类 anes_hemorrhage）","point":"与本类中“围术期大出血”的鉴别点：大出血有失血证据、Hb 下降、对输血反应良好，低血压渐进伴四肢湿冷；过敏休克在给药后数分钟突发低血压伴气道阻力升高、皮疹或面部水肿，对肾上腺素反应迅速。"},{"name":"术后谵妄与术后认知障碍（本类 anes_ponv_refract）","point":"与本类中“术后谵妄”的鉴别点：过敏休克是急性全身免疫反应伴循环与气道症状，发生于给药当下；谵妄为术后注意力与意识障碍，无低血压与皮疹。"},{"name":"恶性高热（an_mh）","point":"与 anes_1.json 中“恶性高热”的鉴别点：恶性高热由吸入麻醉药/琥珀酰胆碱触发，核心为呼气末 CO₂ 骤升、高热与肌强直，首选丹曲林；过敏休克以低血压、气道阻力升高与皮疹为主，首选肾上腺素。"},{"name":"支气管痉挛（哮喘/COPD 发作）","point":"哮鸣与气道阻力升高但血压稳定，多有哮喘/COPD 病史，支气管扩张剂可缓解；伴低血压、皮疹与过敏原暴露者按过敏处理。"}],"tx":{"drug":[{"name":"肾上腺素（首选）","dose":"术中静脉给药 0.01–0.02 mg（10–20 µg）分次静推，每 1–2 分钟重复，按反应递增；尚未建立静脉通路时 0.5 mg 肌注（大腿外侧）；心跳骤停时 1 mg 静推","note":"将 1 mg/mL 稀释为 0.1 mg/mL 后小量静推，避免未稀释大剂量致高血压与心肌缺血；使用 β 阻滞剂者可能需更大剂量或加胰高血糖素","renal":"无需调整","hepatic":"肝病者药效可能延长","interact":"与单胺氧化酶抑制剂、三环类抗抑郁药合用可致严重高血压"},{"name":"晶体液快速扩容","dose":"初始 20 mL/kg 快速输注（成人 1–2 L），按血压与心率反应重复，必要时加压输注","note":"低血压主因血管扩张与血管内液体外渗，需大量补液；心功能不全者监测肺水肿","renal":"CKD 与心衰者控制液量与速度","hepatic":"肝硬化腹水者谨慎","interact":"遵说明书"},{"name":"去甲肾上腺素/血管加压素（持续输注）","dose":"去甲肾上腺素 0.05–0.5 µg/kg/min；难治性低血压可加血管加压素 0.01–0.04 U/min（遵临床滴定）","note":"用于反复推注肾上腺素后仍低血压者，需有创动脉压监测","renal":"遵说明书","hepatic":"遵说明书","interact":"与利多卡因等合用可致心律失常"},{"name":"糖皮质激素与抗组胺药（辅助）","dose":"氢化可的松 200 mg 静推或甲泼尼龙 1–2 mg/kg；苯海拉明 25–50 mg 静推或氯苯那敏 10 mg 肌注（遵说明书）","note":"不改变早期血流动力学，可减轻迟发相反应与皮肤症状；不能替代肾上腺素","renal":"遵说明书","hepatic":"遵说明书","interact":"升高血糖、可能加重感染"},{"name":"沙丁胺醇/异丙托溴铵雾化","dose":"沙丁胺醇 2.5–5 mg 雾化，必要时异丙托溴铵 0.5 mg 雾化","note":"用于支气管痉挛，需与肾上腺素联合","renal":"遵说明书","hepatic":"遵说明书","interact":"与非选择性 β 受体阻滞剂作用拮抗"},{"name":"胰高血糖素（β 阻滞剂服用者难治性低血压）","dose":"1–5 mg 静推（遵说明书）","note":"绕开 β 受体直接增强心肌收缩与心率","renal":"遵说明书","hepatic":"遵说明书","interact":"可致高血糖"}],"nonDrug":["立即停用全部可疑药物、撤除乳胶制品、更换含氯己定的管路与碘消毒剂，请外科暂停手术","100% 氧、头低位、气管插管（已插管者调整导管），喉头水肿严重者紧急外科气道","有创动脉压、中心静脉压、呼气末 CO₂ 与气道压监测，扩容同时评估心脏充盈","心跳骤停按 CPR 流程，肾上腺素 1 mg 每 3–5 分钟，过敏相关骤停可延长复苏时间","术后 ICU 观察 24 小时（双相反应风险），复查类胰蛋白酶，4–6 周后确认过敏原并出具禁忌卡"],"life":["出院提供过敏药物清单与禁忌卡，今后麻醉需避免相关药物","有过敏史者术前评估：皮肤试验、特异性 IgE 与替代药物方案","β 受体阻滞剂使用者与心内科讨论风险（ACEI 不常规停用）","随访过敏相关心脏事件与迟发型反应"]},"prog":"及时使用肾上腺素与扩容后多数患者 30–60 分钟内血流动力学稳定；围术期过敏病死率约 1%–6%，难治性休克与心跳骤停者更高。约 1%–20% 出现双相反应，需 ICU 观察。明确过敏原并回避后复发风险低，但再次暴露可能更严重。","refs":["中华医学会麻醉学分会《围术期过敏反应诊治专家共识》（2018）","中华医学会变态反应学分会《严重过敏反应诊断和临床管理专家共识》（2021）","世界过敏组织（WAO）《Anaphylaxis Guidance》（2020）","欧洲过敏与临床免疫学会（EAACI）《Perioperative Anaphylaxis Guideline》（2018）"]},{"id":"anes_ponv_refract","name":"术后谵妄与术后认知障碍","aka":["Postoperative Delirium","POD","Postoperative Cognitive Dysfunction","POCD"],"rank":3,"basic":{"define":"术后谵妄（postoperative delirium, POD）是术后急性起病、波动性的注意力与意识障碍，多发生于术后 1–3 天（老年可至 7 天）。术后认知功能障碍（postoperative cognitive dysfunction, POCD）指术后数周至数月记忆、执行功能与信息处理速度下降；现统称围术期神经认知障碍（PND），按时相分为术前已存在、术后谵妄与术后认知功能下降。","risk":["高龄（≥65 岁）、术前认知障碍/痴呆与受教育程度低","心脏/大血管手术、髋部骨折与重大骨科手术、长时间（>3 小时）与急诊手术","苯二氮䓬类、抗胆碱能药、大剂量阿片、术中低血压与脑氧饱和度下降","疼痛、睡眠剥夺、感染/脓毒症、低氧、电解质紊乱、尿潴留与感觉剥夺","酗酒与戒断、抑郁、衰弱与多病共存"],"epi":"术后谵妄总体发生率 10%–20%，老年髋部骨折与心脏手术达 20%–50%，ICU 机械通气患者 50%–80%。谵妄使住院延长 2–3 天、病死率增加 1.5–2 倍。POCD 术后 1 周约 25%–30%，3 个月约 10%–15%，60 岁以上更常见。"},"patho":"机制未完全阐明，主要假说：①神经炎症——手术创伤与麻醉激活外周免疫、增加血脑屏障通透性与小胶质细胞激活，促炎因子（IL-1β、IL-6、TNF-α）损害突触可塑性；②神经递质失衡——胆碱能活性下降、多巴胺能相对亢进，抗胆碱能药与阿片加重；③脑血流与代谢失衡——术中低血压、低氧使脆弱脑区缺血；④淀粉样蛋白与 Tau 沉积（与阿尔茨海默病通路交叉）。POD 是认知持续下降的独立危险因素。","dx":{"criteria":["术后谵妄（DSM-5）：①注意力障碍；②意识水平波动或受损；③起病急（数小时至数天）且病程波动；④认知障碍（记忆、定向、语言或知觉）；⑤不能用其他神经疾病或昏迷解释。","亚型：高活动型（躁动、拔管）、低活动型（嗜睡、反应迟钝，易漏诊）与混合型，低活动型占 30%–40%。","筛查工具：CAM 或 CAM-ICU、4AT（4 项，>1 分提示可能谵妄），老年与认知障碍患者每日筛查 1–2 次。","POCD：术前与术后 1 周、3 个月重复神经心理测评（MMSE/MoCA 及记忆、执行功能），≥1.5 个标准差下降或 ≥2 个测验异常有意义。"],"workup":["术前基线认知评估：MoCA/MMSE（≥65 岁或既往认知障碍），记录教育年限","术后 24–72 小时每日 CAM/4AT，特别关注低活动型","鉴别检查：血糖、电解质（钠、钙）、血气（低氧/高碳酸）、肾功能、CRP 与培养、心电图、甲状腺功能","新发局灶体征或意识持续下降者行头颅 CT/MRI，排除卒中、颅内出血与低钠性脑病","用药回顾：苯二氮䓬类、抗胆碱能药、H₂ 受体拮抗剂、抗精神病药与阿片","高危或心脏手术：脑氧饱和度（NIRS）与处理脑电图监测麻醉深度与血压"],"grading":"按 DSM-5 亚型（高活动型/低活动型/混合型）；严重度可用谵妄评定修订量表（DRD）。POCD 按神经心理评分下降 >1.5 SD 或 ≥2 个测验异常判定，持续 >3 个月提示更持久损害。"},"ddx":[{"name":"围术期大出血与输血（本类 anes_hemorrhage）","point":"与本类中“围术期大出血”的鉴别点：大出血致低灌注可引起意识改变，但伴低血压、Hb 下降与乳酸升高，复苏后改善；谵妄在血流动力学稳定时出现，注意力与意识波动是核心。"},{"name":"术中过敏休克（本类 anes_anaphylaxis）","point":"与本类中“术中过敏休克”的鉴别点：过敏休克以低血压、气道阻力升高与皮疹为主，发生于给药后即刻；谵妄为术后 24–72 小时起病的认知与注意力障碍，生命体征平稳。"},{"name":"椎管内麻醉后神经并发症（anes_sa）","point":"与 anes_airway2 类中“椎管内麻醉并发症”的鉴别点：椎管内并发症为局灶性运动/感觉缺失或体位性头痛；谵妄为弥漫性认知与注意力障碍，无固定感觉平面与瘫肢。"},{"name":"代谢性脑病/脓毒症相关脑病","point":"脓毒症、低钠血症与肝肾功能衰竭均可致意识改变，可借发热、感染指标、血钠与肝肾功能鉴别；可与谵妄并存，需同时治疗原发病并施非药物干预。"}],"tx":{"drug":[{"name":"右美托咪定","dose":"0.2–0.7 µg/kg/h 静脉泵入（ICU 机械通气 0.2–1.0 µg/kg/h），按镇静评分与心率滴定","note":"用于躁动型谵妄与术后镇静，减少阿片与苯二氮䓬用量；低血压与心动过缓者减量","renal":"严重肾功能不全者无需调整（遵说明书）","hepatic":"肝功能不全者半衰期延长，减量","interact":"与 β 受体阻滞剂、丙泊酚合用加强镇静与心动过缓"},{"name":"氟哌啶醇（不作为常规一线）","dose":"0.5–1 mg 静注或肌注（老年 0.25–0.5 mg），按需每 4–6 小时重复，一日总量 ≤5 mg（遵说明书）","note":"仅用于严重躁动、幻觉或自伤/拔管风险者，不缩短病程，警惕 QT 延长与锥体外系反应；不用于常规预防","renal":"肾功能不全者无需调整","hepatic":"肝功能不全者减量","interact":"与氟喹诺酮、抗心律失常药合用增加尖端扭转型室速风险"},{"name":"褪黑素","dose":"2–3 mg 睡前口服（证据有限，遵医嘱）","note":"帮助恢复睡眠-觉醒节律，不作为预防谵妄的常规推荐","renal":"遵说明书","hepatic":"遵说明书","interact":"与镇静催眠药合用加强镇静"},{"name":"避免/简化苯二氮䓬类（必要者咪达唑仑）","dose":"咪达唑仑 0.5–1 mg 静推，老年 0.25–0.5 mg；围术期尽量以丙泊酚/右美托咪定或区域阻滞替代","note":"苯二氮䓬类是谵妄的独立危险因素，尤其 ICU 与老年患者","renal":"咪达唑仑代谢物在肾衰时蓄积","hepatic":"肝病者代谢延长","interact":"与阿片类协同抑制呼吸"},{"name":"多模式镇痛（减少阿片）","dose":"对乙酰氨基酚 1 g q6h + 罗哌卡因/布比卡因区域阻滞，阿片按需最小剂量（遵说明书）","note":"疼痛未控制是谵妄诱因，单纯减阿片而疼痛加重反而增加风险；平衡镇痛是核心","renal":"严重肾功能不全者慎用 NSAIDs","hepatic":"对乙酰氨基酚每日总量 ≤2 g","interact":"阿片与苯二氮䓬合用增加呼吸抑制"}],"nonDrug":["一线非药物干预：定向力沟通与日间照明、认知刺激（家属参与、眼镜与助听器、时钟日历）、早期活动、睡眠保护（减少夜间打扰）、规律排便与导尿管管理","预防：术前风险评估、避免过深麻醉与低血压（MAP 维持基线 ±20%）、限制苯二氮䓬与抗胆碱能药、优化镇痛","麻醉、外科、老年/精神科、护理与康复多学科共同管理","避免约束与过度镇静；危及安全时先改善环境与疼痛，再考虑小剂量抗精神病药","POCD：术后 1 周与 3 个月神经心理测评，认知训练、运动与控制血管危险因素"],"life":["术前评估认知并告知患者与家属风险，术后家属参与定向力训练","睡眠卫生：固定作息、避免睡前咖啡因、白天光照","出院后随访认知与日常生活能力，≥65 岁者 3 个月复查 MoCA","控制血压、血糖与戒烟限酒，参与社交与认知活动"]},"prog":"多数谵妄 3–7 天缓解，约 20%–30% 持续数周；谵妄使住院延长、院内病死率增加 10%–20%。POCD 术后 1 周约 25%–30%、3 个月约 10%–15%，多数可恢复，老年与心脏手术患者与术后 1 年痴呆风险升高相关。多学科非药物预防可降低谵妄发生率约 30%–40%。","refs":["中华医学会麻醉学分会《术后谵妄/围术期神经认知障碍防治专家共识》（2019）","中华医学会麻醉学分会《老年人围术期管理专家共识》（2020）","欧洲麻醉学会（ESA）《Perioperative Neurocognitive Disorders: Guidelines》（2018）","美国老年医学会（AGS）《Postoperative Delirium in Older Adults: Clinical Practice Guideline》（2014）"]}]}]},"cardio":{"categories":[{"id":"cad","name":"冠心病","rank":1,"summary":"以抗血小板+降脂为核心二级预防，按缺血/出血风险分层决定血运重建；急性冠脉综合征强调再灌注时间窗与双联抗血小板。","compare":[{"diseaseId":"cad_sap","dx":"劳力性胸痛，休息或含服硝酸甘油数分钟内缓解，肌钙蛋白阴性，运动试验或 CTA 见 >50% 狭窄","key":"无心肌坏死标志物升高、症状可预测=慢性冠脉综合征"},{"diseaseId":"cad_stemi","dx":"缺血性胸痛 + 相邻两个导联 ST 段抬高（V2–V3 ≥0.2 mV 男性 ≥40 岁 / ≥0.25 mV 男性 <40 岁 / ≥0.15 mV 女性，其他导联 ≥0.1 mV）或新发左束支阻滞","key":"肌钙蛋白升高伴 ST 抬高，需 12 h 内（首选 2 h 内）直接 PCI"},{"diseaseId":"cad_nstemi","dx":"缺血症状 + 肌钙蛋白超过参考上限第 99 百分位（hs-cTn 0/1 h 算法），无持续性 ST 抬高","key":"有坏死=NSTEMI，仅心电图 ST-T 改变而无坏死=UA；按 GRACE 评分决定紧急/早期侵入"},{"diseaseId":"cad_scad","dx":"典型劳力性心绞痛但造影无 >50% 阻塞，或冠脉痉挛（夜间静息发作，乙酰胆碱/麦角新碱激发阳性），或微血管功能障碍（CFR <2.0、IMR ≥25）","key":"无阻塞性狭窄却有缺血证据，需冠脉功能学检查（CFR/IMR、激发试验）"}],"diseases":[{"id":"cad_sap","name":"稳定型心绞痛（慢性冠脉综合征）","aka":["稳定型心绞痛","SAP","稳定性冠心病","CCS"],"rank":1,"basic":{"define":"由冠脉固定性狭窄（通常 ≥70%，左主干 ≥50%）导致的心肌供氧-需氧失衡，表现为可预测的劳力性胸骨后压榨样不适，休息或硝酸甘油 3–5 min 内缓解。","risk":["男性 >55 岁、女性 >65 岁","高血压、糖尿病、血脂异常（LDL-C 升高）","吸烟","早发冠心病家族史","腹型肥胖、缺乏运动、慢性肾脏病"],"epi":"我国≥18 岁人群冠心病患病率约 1%–2%，60 岁以上明显升高；《中国心血管健康与疾病报告》估计冠心病现患人数逾 1100 万，是城乡居民主要死因之一。"},"patho":"动脉粥样硬化斑块（纤维帽完整、钙化为主）使管腔固定狭窄，运动时心肌耗氧增加而血流储备不足，诱发短暂心内膜下缺血；缺血代谢产物（腺苷等）刺激心脏交感传入纤维产生胸痛。斑块破裂或侵蚀则转为急性冠脉综合征。","dx":{"criteria":["典型心绞痛三要素：胸骨后压迫/紧缩感；由运动或情绪诱发；休息或硝酸甘油 3–5 min 缓解；满足 2 项为不典型、3 项为典型","冠脉 CTA 或造影示至少 1 支主要冠脉或其主要分支管腔直径狭窄 ≥50%（功能性显著狭窄）","或存在缺血证据：运动平板 ST 段水平型/下斜型压低 ≥1 mm（0.1 mV）持续 ≥2 min；负荷超声/负荷 MRI 新发 ≥1 个节段室壁运动异常；SPECT 可逆性灌注缺损","静息心电图正常不能排除；肌钙蛋白应处于正常范围（超过 99 百分位需按 ACS 处理）","冠状动脉血流储备 CFR <2.0 提示微血管功能障碍"],"workup":["静息 12 导联心电图：ST 段压低、T 波倒置、病理性 Q 波或左室肥厚","血常规、肾功能、空腹血糖与 HbA1c、血脂、肝功能、电解质","超声心动图：LVEF、节段性室壁运动、瓣膜与左室肥厚","冠脉 CTA：低-中验前概率、无严重钙化者适用；验前概率 >85% 直接造影","负荷试验用于症状不典型、CTA 结果与症状不符时","高敏肌钙蛋白基线值，急性发作时排除 ACS"],"grading":"加拿大心血管学会（CCS）心绞痛分级：Ⅰ级 一般活动不诱发；Ⅱ级 日常活动轻度受限（快步走、上楼）；Ⅲ级 日常活动明显受限（平地步行 1–2 个街区）；Ⅳ级 任何活动即发作，可静息发作。"},"ddx":[{"name":"NSTEMI/UA（cad_nstemi）","point":"与本类 cad_nstemi 的鉴别点：SAP 症状可预测、休息即缓解、肌钙蛋白阴性；NSTEMI/UA 为静息或进行性加重，症状持续 >20 min，肌钙蛋白升高或心电图动态 ST-T 改变。"},{"name":"STEMI（cad_stemi）","point":"与本类 cad_stemi 的鉴别点：STEMI 胸痛持续 >30 min 不缓解、相邻导联 ST 抬高或新发 LBBB；SAP 无 ST 抬高、5 min 内缓解。"},{"name":"冠脉痉挛/微血管性心绞痛（cad_scad）","point":"与本类 cad_scad 的鉴别点：SAP 有明确负荷相关性与固定狭窄；痉挛型多夜间静息发作伴短暂 ST 抬高，微血管型常为女性、负荷诱发但造影无狭窄。"},{"name":"主动脉瓣狭窄","point":"劳力性呼吸困难、晕厥、心绞痛三联征，但胸痛多在活动后出现，超声见瓣口面积 <1.0 cm²、跨瓣压差升高。"},{"name":"胃食管反流病","point":"烧灼感、与体位及进食相关、抗酸药有效，与劳力无关，心电图与负荷试验阴性。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"75–100 mg qd 长期口服","note":"无禁忌者一线抗血小板；CCS 一般单药，PCI 后与 P2Y12 抑制剂联用","renal":"无需调整，出血风险随 eGFR 下降增加","hepatic":"严重肝病、活动性消化道出血禁用","interact":"与 NSAIDs 联用增加消化道出血；与 OAC 合用需评估，三联一般不超过 1 周–1 个月"},{"name":"氯吡格雷","dose":"75 mg qd；PCI 术前负荷 300–600 mg","note":"不能耐受阿司匹林者替代；CYP2C19 慢代谢者疗效降低","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"奥美拉唑/埃索美拉唑降低活性代谢物浓度，改用泮托拉唑或雷贝拉唑"},{"name":"阿托伐他汀","dose":"10–20 mg qn 起始，未达标增至 40–80 mg qn；目标 LDL-C <1.4 mmol/L 且降幅 ≥50%（极高危）或 <1.8 mmol/L 且降幅 ≥50%（高危）","note":"所有冠心病患者均应使用；4–6 周复查血脂与肝功能","renal":"无需调整","hepatic":"活动性肝病或转氨酶持续 >3 倍正常上限禁用；ALT/AST >3 倍需停药","interact":"强 CYP3A4 抑制剂（克拉霉素、伊曲康唑）、西柚汁增加肌病风险；与贝特类合用监测 CK"},{"name":"瑞舒伐他汀","dose":"5–10 mg qn 起始，可增至 20 mg qn（亚洲人群起始 5 mg）","note":"他汀不耐受或需强化降脂时选用","renal":"eGFR <30 起始 5 mg、最大 10 mg","hepatic":"活动性肝病禁用","interact":"与吉非罗齐、环孢素合用显著增加肌病风险，避免"},{"name":"依折麦布","dose":"10 mg qd","note":"他汀未达标时联合，可额外降低 LDL-C 约 15%–20%","renal":"无需调整","hepatic":"重度肝功能不全不推荐","interact":"与贝特类合用增加胆囊疾病风险"},{"name":"依洛尤单抗（PCSK9 抑制剂）","dose":"140 mg 皮下注射 q2w 或 420 mg q4w","note":"最大耐受他汀 + 依折麦布仍不达标或家族性高胆固醇血症者","renal":"无需调整","hepatic":"重度肝功能不全资料有限，遵说明书","interact":"无已知临床显著相互作用"},{"name":"美托洛尔（缓释）","dose":"23.75–47.5 mg qd 起始，滴定至静息心率 55–60 次/分；普通片 25–50 mg bid","note":"心绞痛、心梗后或 LVEF ≤40% 者首选；变异型心绞痛不宜单独使用","renal":"无需调整","hepatic":"肝硬化者减量","interact":"与维拉帕米/地尔硫䓬合用增加心动过缓与传导阻滞；CYP2D6 抑制剂升高浓度"},{"name":"比索洛尔","dose":"1.25–2.5 mg qd 起始，每 1–2 周递增，最大 10 mg qd","note":"选择性 β1 阻滞剂，支气管痉挛风险较低","renal":"eGFR <20 最大 10 mg","hepatic":"重度肝功能不全最大 10 mg","interact":"避免与非二氢吡啶类 CCB 合用"},{"name":"硝酸甘油（舌下）","dose":"0.5 mg 舌下含服，5 min 可重复 1 次，最多 3 次","note":"急性发作缓解；反复发作提示病情不稳定；近 24 h 内用过西地那非者禁用","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"禁与 PDE5 抑制剂（西地那非 24 h、他达拉非 48 h 内）合用"},{"name":"单硝酸异山梨酯（缓释）","dose":"30–60 mg qd，可加至 120 mg qd","note":"长期抗心绞痛；需保留 8–12 h 无硝酸酯间期","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"禁用 PDE5 抑制剂"},{"name":"地尔硫䓬（缓释）","dose":"90 mg qd 起始，可增至 360 mg qd 分次","note":"β 阻滞剂禁忌且有血管痉挛因素时；LVEF <40% 或房室传导阻滞者禁用","renal":"慎用，遵说明书","hepatic":"肝硬化者减量","interact":"CYP3A4 抑制剂升高浓度；与他汀合用增加肌病风险"}],"nonDrug":["PCI：药物难以控制的心绞痛、左主干 ≥50% 或前降支近段 ≥70%、负荷试验缺血面积 >10% 者","CABG：多支病变合并糖尿病、左主干病变、SYNTAX 评分高者优于 PCI","CCI 级（难治性心绞痛）可考虑体外反搏、经皮激光血运重建或脊髓刺激","血运重建前后均需持续优化药物治疗"],"life":["戒烟（含二手烟）","每周 ≥150 min 中等强度有氧运动，参加心脏康复","限盐 <5 g/d，BMI 18.5–24 kg/m²","血压目标 <130/80 mmHg，HbA1c <7.0%（个体化）","每年评估症状、危险因素控制与用药依从性；筛查焦虑抑郁"]},"prog":"规范二级预防后年心血管死亡率约 1%–2%；合并糖尿病、多支病变或 LVEF 降低者风险升高 2–3 倍。主要不良事件为进展为急性冠脉综合征与心力衰竭。","refs":["中华医学会心血管病学分会《稳定性冠心病诊断与治疗指南》2018","《中国慢性冠脉综合征患者诊断及管理指南》2023","《中国血脂管理指南（2023 年）》","2024 ESC Guidelines for the management of chronic coronary syndromes"]},{"id":"cad_stemi","name":"ST 段抬高型心肌梗死","aka":["STEMI","急性 ST 段抬高型心肌梗死"],"rank":2,"basic":{"define":"冠状动脉急性血栓性闭塞导致透壁性心肌缺血坏死，表现为持续性胸痛伴心电图相邻导联 ST 段抬高（或等危表现）及心肌坏死标志物升高。","risk":["吸烟","高血压、糖尿病、血脂异常","男性 >55 岁、女性 >65 岁","既往心梗或 PCI/CABG 史","可卡因/安非他命使用","高龄、慢性肾病"],"epi":"我国急性心梗年发病约 60 万–80 万例，STEMI 约占急性心梗的 30%–40%；院内死亡率约 4%–8%，合并心源性休克者 >30%。"},"patho":"易损斑块（薄纤维帽、大量脂质核、炎症活跃）破裂或侵蚀，血小板黏附聚集并激活凝血级联，形成富含纤维蛋白的红血栓完全闭塞血管；心肌缺血 20 min 后开始凝固性坏死，约 6 h 后透壁坏死完成。再灌注可造成缺血再灌注损伤（无复流、心律失常）。","dx":{"criteria":["持续性缺血性胸痛 >20–30 min，硝酸甘油不能完全缓解","相邻两个导联新发 ST 段抬高：V2–V3 男性 ≥40 岁 ≥0.2 mV、<40 岁 ≥0.25 mV，女性 ≥0.15 mV；其他导联 ≥0.1 mV；或新发左束支传导阻滞伴缺血症状","下壁导联抬高伴 V1–V3 ST 压低提示后壁心梗；V1–V3 单纯 ST 压低按 STEMI 等危处理","hs-cTn 升高超过参考上限第 99 百分位；但不应等待结果再启动再灌注","院外心脏骤停复苏后心电图 ST 抬高同样按 STEMI 处理"],"workup":["首诊 10 min 内完成 12 导联心电图；疑后壁/右室时加做 V7–V9、V3R–V4R","高敏肌钙蛋白动态检测（0/1 h），不等待结果即按 ACS 流程处置","床旁超声：节段性室壁运动异常、LVEF、机械并发症、心包积液","入院即刻血常规、凝血、肾功能、电解质、血糖、血脂、NT-proBNP","急诊冠脉造影：明确梗死相关动脉与多支病变","持续心电监护 ≥24 h，评估室速/室颤与房室阻滞"],"grading":"按导联定位：前壁（V1–V4 加 I、aVL）、下壁（Ⅱ、Ⅲ、aVF）、侧壁（Ⅰ、aVL、V5–V6）、后壁（V7–V9）、右室（V3R–V4R）。Killip 分级：Ⅰ级无湿啰音，Ⅱ级啰音 <50% 肺野，Ⅲ级急性肺水肿，Ⅳ级心源性休克。"},"ddx":[{"name":"NSTEMI/UA（cad_nstemi）","point":"与本类 cad_nstemi 的鉴别点：STEMI 有相邻导联持续性 ST 抬高或新发 LBBB，需立即再灌注；NSTEMI 无 ST 抬高（可有 ST 压低/T 波倒置），按风险分层决定侵入时机。"},{"name":"稳定型心绞痛（cad_sap）","point":"与本类 cad_sap 的鉴别点：SAP 症状 3–5 min 缓解、肌钙蛋白阴性、无 ST 抬高；STEMI 症状持续超过 20–30 min 且心电图持续抬高。"},{"name":"冠脉痉挛/微血管性心绞痛（cad_scad）","point":"与本类 cad_scad 的鉴别点：痉挛型短暂 ST 抬高多在夜间静息发作，含服硝酸甘油数分钟内回落，肌钙蛋白多不升高；STEMI 抬高持续不回落并伴坏死标志物动态升高。"},{"name":"急性主动脉夹层","point":"撕裂样背痛、双上肢血压差 >20 mmHg、纵隔增宽，D-二聚体显著升高；累及冠脉开口时可并存 ST 抬高，此时溶栓禁忌，需 CTA 确诊。"},{"name":"急性肺栓塞","point":"突发呼吸困难、胸膜性胸痛、低氧，D-二聚体升高，CTPA 见肺动脉充盈缺损；心电图多为 SⅠQⅢTⅢ，罕见 ST 抬高。"},{"name":"心包炎/早复极","point":"心包炎 ST 抬高弥漫、凹面向上伴 PR 段压低，疼痛随呼吸/体位变化；早复极见于年轻男性，无缺血症状、肌钙蛋白阴性。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"首剂 150–300 mg 嚼服（负荷），后续 100 mg qd","note":"确诊或高度怀疑即给，不等造影结果","renal":"无需调整","hepatic":"严重肝病禁用","interact":"与抗凝联用增加出血；与 NSAIDs 同服降低抗血小板效果"},{"name":"替格瑞洛","dose":"负荷 180 mg，维持 90 mg bid（≥12 个月）；溶栓者 ≥75 岁 45 mg bid、<75 岁 90 mg bid，维持 30 天","note":"直接 PCI 首选；既往脑卒中/短暂性脑缺血者慎用","renal":"无需调整","hepatic":"重度肝功能不全禁用","interact":"强 CYP3A4 抑制剂（酮康唑、克拉霉素）禁用；强诱导剂（利福平、卡马西平）降低疗效"},{"name":"氯吡格雷","dose":"负荷 300–600 mg，维持 75 mg qd；溶栓者 <75 岁 300 mg 负荷，≥75 岁不给负荷直接 75 mg","note":"替格瑞洛出血高危或禁忌时选用","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"避免与奥美拉唑、埃索美拉唑合用"},{"name":"普通肝素（UFH）","dose":"直接 PCI：静脉推注 70–100 U/kg（联用 GPⅡb/Ⅲa 时 50–70 U/kg），ACT 维持 250–300 s（联用 GPⅡb/Ⅲa 时 200–250 s）","note":"溶栓后 PCI 者按 ACT 补充","renal":"重度肾功能不全相对安全（较 LMWH）","hepatic":"凝血功能障碍者减量，监测 APTT","interact":"与 GPⅡb/Ⅲa、溶栓药、DOAC 出血风险叠加"},{"name":"依诺肝素","dose":"静脉推注 0.5 mg/kg（30 mg 为常用上限，遵说明书），随后 1 mg/kg q12h 皮下；≥75 岁 0.75 mg/kg q12h 不给推注；CrCl <30 mL/min 1 mg/kg q24h","note":"溶栓或保守治疗抗凝可选；PCI 时末次皮下注射 <8 h 不再追加","renal":"CrCl <30 mL/min 改为 qd 或改用 UFH","hepatic":"重度肝病慎用","interact":"与磺达肝癸钠、DOAC、NSAIDs 联用增加出血"},{"name":"磺达肝癸钠","dose":"2.5 mg 皮下注射 qd；CrCl 30–50 mL/min 慎用，<30 mL/min 禁用","note":"非直接 PCI 患者抗凝选择；不用于直接 PCI","renal":"CrCl <30 mL/min 禁用","hepatic":"重度肝病慎用","interact":"不与其他抗凝药常规联用"},{"name":"比伐芦定","dose":"0.75 mg/kg 静脉推注，随后 1.75 mg/kg/h 持续至 PCI 结束（术后继续 1–4 h，遵说明书）","note":"肝素诱导血小板减少症（HIT）者首选；出血高危者可考虑","renal":"CrCl <30 mL/min 减量（遵说明书）","hepatic":"遵说明书","interact":"仅与抗血小板药联用"},{"name":"替罗非班","dose":"10–25 µg/kg 静脉推注（3 min），随后 0.10–0.15 µg/kg/min 静滴 12–18 h","note":"仅用于高血栓负荷、无复流或缓血流者；联用时肝素减量","renal":"CrCl <30 mL/min 剂量减半（遵说明书）","hepatic":"重度肝功能不全慎用","interact":"与抗凝、双抗叠加显著增加出血"},{"name":"硝酸甘油（静脉）","dose":"5–10 µg/min 起始，每 5–10 min 递增 5–10 µg/min，依血压滴定；SBP <90 mmHg 或右室梗死禁用","note":"缓解缺血与肺水肿；持续 >24 h 易耐受","renal":"遵说明书","hepatic":"遵说明书","interact":"禁用 PDE5 抑制剂"},{"name":"美托洛尔（静脉/口服）","dose":"稳定者静脉 2.5–5 mg 缓慢推注，可重复至总量 15 mg；随后口服 25–50 mg q6–12h 过渡至缓释制剂","note":"发病 24 h 内稳定患者尽早口服；心衰、低血压、心动过缓、房室阻滞者暂缓","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"勿与维拉帕米静脉制剂同用"},{"name":"阿托伐他汀","dose":"入院即启动 40–80 mg qn","note":"目标 LDL-C <1.4 mmol/L 且降幅 ≥50%","renal":"无需调整","hepatic":"活动性肝病禁用","interact":"同他汀类"},{"name":"依折麦布","dose":"10 mg qd（入院即启动）","note":"与高强度他汀联合强化降脂","renal":"无需调整","hepatic":"重度肝功能不全不推荐","interact":"与贝特类合用增加胆囊疾病风险"},{"name":"阿利西尤单抗（PCSK9 抑制剂）","dose":"75 mg 或 150 mg 皮下注射 q2w（遵说明书）","note":"他汀 + 依折麦布仍未达标者"},{"name":"培哚普利/依那普利（ACEI）","dose":"LVEF ≤40%、前壁心梗或合并心衰者在 24 h 内起始小剂量；培哚普利 2 mg qd、依那普利 2.5 mg bid，逐步滴定至目标剂量","note":"SBP <100 mmHg、双侧肾动脉狭窄者禁用","renal":"Cr 升高 >30% 减量","hepatic":"重度肝功能不全减量","interact":"与保钾利尿剂、钾片合用高钾"},{"name":"螺内酯","dose":"LVEF ≤40% 且 eGFR >30、血钾 <5.0 mmol/L 时 20 mg qd","note":"血钾 >5.0 mmol/L 或 eGFR <30 禁用","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 ACEI/ARB 合用高钾"}],"nonDrug":["再灌注：直接 PCI，目标 FMC-to-device ≤90 min（转运时 ≤120 min）；无条件者 30 min 内溶栓（发病 ≤12 h），溶栓后 2–24 h 转运行冠脉造影","溶栓禁忌：既往颅内出血、3 个月内缺血性卒中、主动脉夹层、活动性出血、近期大手术/创伤、血压 >180/110 mmHg 未控制","心源性休克：立即血运重建，可辅以 IABP；ECMO 用于难治性休克","机械并发症（乳头肌断裂、室间隔穿孔、游离壁破裂）：急诊外科","室颤立即除颤；Ⅱ度Ⅱ型或Ⅲ度房室阻滞临时起搏","出院前评估 LVEF，≤40% 者 40 天–3 个月评估 ICD"],"life":["绝对戒烟，急性期卧床 24–48 h 后逐步活动","心脏康复，低盐低脂饮食，控制血压、血糖、血脂","双联抗血小板默认 12 个月（高出血风险可 3–6 个月），严禁自行停药","出院 1、3、6、12 个月随访，复查血脂、肝肾功能、LVEF","识别再发胸痛并立即呼叫急救"]},"prog":"直接 PCI 时代院内死亡率约 4%–6%，1 年死亡率约 7%–10%；发病至再灌注每延长 30 min，1 年死亡相对风险增加约 7.5%。合并心源性休克者病死率 30%–50%。","refs":["中华医学会心血管病学分会《急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）》","《急性 ST 段抬高型心肌梗死溶栓治疗的合理用药指南（第 2 版）》2019","《急性心肌梗死后心室重构防治专家共识》2020","2023 ESC Guidelines for the management of acute coronary syndromes"]},{"id":"cad_nstemi","name":"非 ST 段抬高型心肌梗死/不稳定型心绞痛","aka":["NSTEMI","UA","NSTE-ACS"],"rank":3,"basic":{"define":"冠脉部分闭塞或斑块破裂后血栓不稳定导致的急性心肌缺血综合征：有心肌坏死（肌钙蛋白升高）为 NSTEMI，无坏死标志物升高但有心电图缺血改变或典型症状者为不稳定型心绞痛（UA）。","risk":["年龄 ≥65 岁","高血压、糖尿病、慢性肾病","既往心肌梗死或 PCI/CABG","吸烟、血脂异常","贫血、慢性炎症状态"],"epi":"占急性冠脉综合征的 60%–70%，随人口老龄化比例上升；女性与老年患者比例高于 STEMI。院内死亡率约 2%–5%，但 6 个月再发事件率与 STEMI 相近。"},"patho":"斑块破裂或侵蚀后形成非完全闭塞性血栓，血流部分受限导致心内膜下缺血，可呈波动性；炎症与血小板激活推动血栓进展与远端微栓塞，可进展为完全闭塞（演变为 STEMI）。","dx":{"criteria":["缺血症状：休息性胸痛 >20 min、新发或恶化性劳力心绞痛、梗死后心绞痛","心电图：新发 ST 段压低 ≥0.05 mV（0.5 mm）、T 波倒置 ≥0.1 mV 或短暂 ST 抬高（<20 min）；可无改变","肌钙蛋白超过参考上限第 99 百分位 → NSTEMI；hs-cTn 0/1 h 算法中变化值（Δ）超出阈值提示急性心肌损伤","GRACE 评分：>140 高危（24 h 内侵入），109–140 中危（72 h 内），≤108 低危（可负荷试验或 CTA）","极高危（<2 h 侵入）：血流动力学不稳定、心源性休克、再发胸痛药物无效、恶性心律失常或心脏骤停、急性心衰、反复 ST-T 动态改变"],"workup":["12 导联心电图动态监测（首诊及每 6–12 h 或症状复发时复查）","hs-cTn 0/1 h 或 0/3 h 动态检测","床旁超声评估 LVEF 与室壁运动","血常规、肾功能（造影剂肾病评估）、血糖、血脂、BNP","GRACE 评分（年龄、心率、收缩压、肌酐、Killip 分级、ST 改变、标志物、心脏停搏史）","冠脉造影 + 必要时 FFR/IVUS：高危或有明确缺血者尽早"],"grading":"GRACE 评分：>140 高、109–140 中、≤108 低。TIMI 评分 ≥3 分为高危；出血风险用 CRUSADE/HAS-BLED 评估。"},"ddx":[{"name":"STEMI（cad_stemi）","point":"与本类 cad_stemi 的鉴别点：STEMI 相邻导联 ST 抬高持续不回落（除后壁等危），需即刻再灌注；NSTEMI 仅有 ST 压低/T 波倒置，按风险分层决定侵入时机。"},{"name":"稳定型心绞痛（cad_sap）","point":"与本类 cad_sap 的鉴别点：UA/NSTEMI 为静息、初发（<2 个月）或进行性加重的心绞痛，肌钙蛋白可升高，需住院按 ACS 处理；SAP 症状阈值固定、肌钙蛋白阴性。"},{"name":"冠脉痉挛/微血管性心绞痛（cad_scad）","point":"与本类 cad_scad 的鉴别点：痉挛发作夜间静息、心电图短暂 ST 抬高但肌钙蛋白阴性、激发试验阳性；NSTEMI 标志物升高、多有固定狭窄、不随硝酸酯完全缓解。"},{"name":"急性心包炎","point":"胸膜炎性胸痛随体位变化、弥漫性 ST 抬高与 PR 压低，肌钙蛋白多正常，超声见心包积液。"},{"name":"Takotsubo（应激性）心肌病","point":"强烈情绪/疾病诱因后类似 ACS，造影无阻塞性狭窄，超声心尖球囊样改变而基底部收缩正常。"},{"name":"急性肺栓塞","point":"D-二聚体升高、低氧、右心负荷增加（右室扩大、肌钙蛋白升高），CTPA 确诊；冠脉正常。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"首剂 150–300 mg 嚼服，维持 75–100 mg qd","note":"确诊或高度怀疑即给","renal":"无需调整","hepatic":"严重肝病禁用","interact":"与抗凝联用增加出血"},{"name":"氯吡格雷","dose":"负荷 300 mg（PCI 时 300–600 mg），维持 75 mg qd","note":"NSTE-ACS 默认 12 个月 DAPT；出血高危者缩短","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"避免奥美拉唑/埃索美拉唑联用"},{"name":"替格瑞洛","dose":"负荷 180 mg，维持 90 mg bid","note":"中高危患者优先（较氯吡格雷降低心血管死亡）","renal":"无需调整","hepatic":"重度肝功能不全禁用","interact":"强 CYP3A4 抑制剂禁用"},{"name":"磺达肝癸钠","dose":"2.5 mg 皮下注射 qd，最多 8 天或至 PCI","note":"首选用于保守治疗或早期侵入者（出血风险低于依诺肝素）","renal":"CrCl <30 mL/min 禁用","hepatic":"重度肝功能不全慎用","interact":"不与其他抗凝药常规联用"},{"name":"依诺肝素","dose":"1 mg/kg 皮下 q12h（CrCl <30 mL/min 1 mg/kg q24h），疗程 2–8 天或至 PCI","note":"造影前末次皮下注射 <8 h 者可直接 PCI","renal":"CrCl <30 mL/min 减为 qd","hepatic":"重度肝病慎用","interact":"联用抗血小板增加出血"},{"name":"普通肝素","dose":"静脉冲击 60–70 U/kg（最大 4000 U）后 12–15 U/kg/h 输注，维持 APTT 正常上限 1.5–2.5 倍；PCI 中 70–100 U/kg 推注","note":"严重肾功能不全或需快速逆转时选用","renal":"相对安全","hepatic":"监测 APTT","interact":"与抗血小板药联用增加出血"},{"name":"美托洛尔（缓释）","dose":"稳定者 23.75–47.5 mg qd 起始，滴定至静息心率 55–60 次/分；静脉 2.5–5 mg 缓慢推注（总量 ≤15 mg）","note":"Killip ≥Ⅱ、SBP <100 mmHg、HR <60 或房室阻滞者暂缓","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"避免与维拉帕米静脉制剂合用"},{"name":"阿托伐他汀","dose":"40–80 mg qn（入院即启动）","note":"目标 LDL-C <1.4 mmol/L 或降幅 ≥50%","renal":"无需调整","hepatic":"活动性肝病禁用","interact":"同他汀类"},{"name":"依折麦布","dose":"10 mg qd","note":"他汀未达标时联合","renal":"无需调整","hepatic":"重度肝功能不全不推荐","interact":"与贝特类合用增加胆囊疾病风险"},{"name":"培哚普利/雷米普利（ACEI）","dose":"培哚普利 2 mg qd 起始，目标 8 mg qd；雷米普利 2.5 mg bid 起始，目标 10 mg qd；LVEF ≤40%、糖尿病或高血压者 24 h 内启动","note":"血肌酐 >221 µmol/L 或双侧肾动脉狭窄者禁用","renal":"Cr 升高 <30% 可继续，>30% 减量","hepatic":"重度肝硬化起始减半","interact":"与钾片、保钾利尿剂合用致高钾"},{"name":"螺内酯","dose":"20 mg qd（LVEF ≤40% 且 eGFR >30）","note":"血钾 >5.0 mmol/L 禁用","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 ACEI/ARB 合用高钾"}],"nonDrug":["侵入策略：极高危 <2 h，GRACE >140 在 24 h 内，中危 72 h 内行冠脉造影","腔内影像（IVUS/OCT）指导支架置入","CABG：左主干、三支病变合并糖尿病或 SYNTAX 评分高者","合并房颤需口服抗凝时三联疗法 ≤1 周后转双联","出院前评估 LVEF，参加心脏康复"],"life":["戒烟限酒，低盐低脂饮食，控制体重","坚持双抗 12 个月，尤其支架植入后 1 个月内勿停药","血糖、血压、血脂达标；定期复查","静息胸痛持续 >15 min 即刻就医"]},"prog":"院内死亡率约 2%–5%，6 个月主要心血管事件率约 10%–15%。早期侵入策略与 DAPT、他汀可将 1 年心血管死亡约减半；LVEF ≤40% 或 GRACE 高危者预后较差。","refs":["中华医学会心血管病学分会《非 ST 段抬高型急性冠状动脉综合征诊断和治疗指南（2016）》","《中国急性冠脉综合征诊治质量控制标准》2021","2023 ESC Guidelines for the management of acute coronary syndromes"]},{"id":"cad_scad","name":"冠脉痉挛与微血管性心绞痛（非阻塞性冠脉疾病）","aka":["冠脉痉挛","变异型心绞痛","微血管性心绞痛","INOCA","MINOCA"],"rank":4,"basic":{"define":"冠脉造影无 ≥50% 阻塞性狭窄但存在心肌缺血的临床综合征：表现为冠状动脉痉挛（短暂、严重、可缓解的血管收缩，常致短暂 ST 抬高）或冠脉微血管功能障碍（小血管舒缩异常或结构重构，负荷诱发心肌缺血）。","risk":["女性、绝经后","吸烟（痉挛型强相关）","高血压、糖尿病、代谢综合征","自身免疫病与慢性炎症","长期压力、睡眠障碍","可卡因、麦角胺类、氟尿嘧啶等药物"],"epi":"因缺血症状行造影者中 30%–50% 无阻塞性狭窄，女性更高；MINOCA 约占急性心梗的 5%–15%，其中痉挛与微血管功能障碍是重要机制。"},"patho":"痉挛型：血管平滑肌高反应性、内皮功能受损，RhoA/Rho 激酶通路激活导致血管收缩，可致完全闭塞与透壁缺血。微血管型：微动脉舒张反应异常、心肌灌注储备下降（CFR <2.0）、微血管重构与内皮功能障碍，导致心内膜下缺血与心肌纤维化。","dx":{"criteria":["典型或非典型心绞痛伴客观缺血证据（负荷试验、灌注显像或心电图动态改变），但造影无 ≥50% 阻塞性狭窄，或 FFR >0.80、IVUS 最小管腔面积 >4 mm²","冠脉痉挛：乙酰胆碱（冠脉内 20–100 µg 递增）或麦角新碱激发诱导 >90% 血管收缩伴症状与心电图改变；自发夜间短暂 ST 抬高为强提示","微血管功能障碍：冠脉血流储备 CFR <2.0，或微血管阻力指数 IMR ≥25（正常 <25）","可表现为 MINOCA：肌钙蛋白升高 + 无阻塞性狭窄，需排除心肌炎、Takotsubo、肺栓塞","OCT/IVUS 无斑块破裂或侵蚀征象"],"workup":["12 导联与动态心电图，捕捉发作时短暂 ST 改变","运动平板/踏车试验，必要时负荷灌注显像或负荷超声","冠脉造影 + FFR；无狭窄者行乙酰胆碱/麦角新碱激发试验","冠脉功能学：CFR、IMR、微血管痉挛试验","IVUS/OCT：评估斑块负荷、侵蚀、内膜","心脏 MRI：鉴别心肌炎、Takotsubo、心肌梗死定位与纤维化","必要时自身免疫与高凝筛查"],"grading":"分为：① 血管痉挛性心绞痛（自发/药理激发）；② 微血管性心绞痛；③ 非阻塞性冠脉疾病伴其他原因（如心肌病）。COVADIS 提出血管痉挛性心绞痛诊断标准用于研究。"},"ddx":[{"name":"稳定型心绞痛（cad_sap）","point":"与本类 cad_sap 的鉴别点：SAP 有 ≥50% 固定狭窄、阈值固定；痉挛型夜间静息发作、激发试验阳性但无固定狭窄，微血管型为负荷诱发而 FFR 正常。"},{"name":"NSTEMI/UA（cad_nstemi）","point":"与本类 cad_nstemi 的鉴别点：ACS 有斑块破裂或血栓证据（OCT/IVUS 可见）；痉挛/微血管型无破裂斑块，肌钙蛋白多为阴性或轻度升高。"},{"name":"STEMI（cad_stemi）","point":"与本类 cad_stemi 的鉴别点：STEMI 的 ST 抬高不可自行回落，造影见血栓性闭塞；痉挛型抬高在含服硝酸甘油后数分钟内恢复、造影通畅，需激发试验证实。"},{"name":"食管痉挛/焦虑相关胸痛","point":"症状类似心绞痛，但无心电图或灌注异常、负荷试验阴性，心理评估与 PPI 试验有助于鉴别。"},{"name":"肥厚型心肌病","point":"非阻塞性冠脉伴心绞痛时需鉴别：超声见室间隔非对称肥厚、SAM 征，基因或 MRI 证实，缺血多为微血管性机制。"}],"tx":{"drug":[{"name":"地尔硫䓬（缓释）","dose":"90–180 mg qd 起始，可增至 360 mg qd 分次","note":"痉挛型首选 CCB，需长期使用；LVEF <40% 或 Ⅱ 度以上房室阻滞者禁用","renal":"遵说明书","hepatic":"肝硬化者减量","interact":"CYP3A4 抑制剂升高浓度；与 β 阻滞剂合用加重心动过缓"},{"name":"氨氯地平","dose":"5 mg qd，可增至 10 mg qd","note":"痉挛型或微血管型均可用","renal":"无需调整","hepatic":"肝功能不全起始 2.5 mg","interact":"与辛伐他汀（>20 mg）合用增加肌病风险"},{"name":"硝酸异山梨酯（短效）/单硝酸异山梨酯","dose":"短效 5–10 mg 舌下或口服按需；单硝酸异山梨酯 30–60 mg qd","note":"发作时优先短效；长效制剂需保留 8–12 h 无硝酸酯期","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"禁用 PDE5 抑制剂"},{"name":"尼可地尔","dose":"5 mg tid，必要时增至 10 mg tid","note":"K-ATP 通道开放剂，微血管型与痉挛型均可考虑","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"与 PDE5 抑制剂合用可致低血压"},{"name":"雷诺嗪","dose":"500 mg bid 起始，2 周后可增至 1000 mg bid","note":"微血管型或难治性心绞痛辅助；QT 延长者禁用","renal":"CrCl 15–30 mL/min 起始 500 mg bid（遵说明书）","hepatic":"重度肝功能不全禁用","interact":"CYP3A4 抑制剂升高浓度；避免与 QT 延长药合用"},{"name":"曲美他嗪","dose":"35 mg（缓释）bid 或 20 mg tid，餐后服用","note":"可减少发作；帕金森病禁用","renal":"eGFR 30–60 减量","hepatic":"重度肝功能不全禁用","interact":"无重大相互作用"},{"name":"伊伐布雷定","dose":"2.5–5 mg bid 起始，目标 7.5 mg bid，静息心率 50–60 次/分","note":"窦性心律、心率 >60 次/分且不能耐受 β 阻滞剂者","renal":"eGFR <15 慎用","hepatic":"重度肝功能不全禁用","interact":"与克拉霉素等 CYP3A4 抑制剂禁用"},{"name":"阿司匹林","dose":"75–100 mg qd","note":"微血管型或有斑块证据者使用；纯痉挛型无斑块者获益不确定","renal":"无需调整","hepatic":"严重肝病禁用","interact":"增加消化道出血风险"},{"name":"阿托伐他汀","dose":"20–40 mg qn（遵说明书调整）","note":"存在斑块或内皮功能异常者使用","renal":"无需调整","hepatic":"活动性肝病禁用","interact":"同他汀类"}],"nonDrug":["戒烟并避免诱因（寒冷、情绪激动、可卡因、麦角类、5-FU）；痉挛型避免非选择性 β 受体阻滞剂","心脏康复、生物反馈与睡眠障碍治疗","难治病例可考虑体外反搏；多学科讨论","无阻塞性狭窄者不常规置入支架，须先排除痉挛机制"],"life":["严格戒烟（痉挛型复发首要干预）","规律运动，避免寒冷刺激与暴饮暴食","夜间发作者可调整长效 CCB 至晚间给药","监测心率、血压与下肢水肿","随访症状控制与 LVEF，必要时复查功能学"]},"prog":"多数长期预后优于阻塞性冠心病，但反复缺血与住院率高、生活质量下降。痉挛型合并多支痉挛或基础心血管病存在心梗与猝死风险；微血管型部分患者症状持续 5 年以上。","refs":["《冠状动脉痉挛综合征诊断与治疗中国专家共识》2015","《冠状动脉微血管疾病诊断和治疗的中国专家共识》2017","中华医学会心血管病学分会《非梗阻性冠心病诊断与管理专家共识》2019","2024 ESC Guidelines for the management of chronic coronary syndromes"]}]},{"id":"hf","name":"心力衰竭","rank":2,"summary":"按 LVEF 分型后尽早启动基础治疗并滴定至目标剂量；急性失代偿先稳定血流动力学，再转入长期改善预后药物。","compare":[{"diseaseId":"hf_hfref","dx":"LVEF ≤40%，症状体征符合心衰，NT-proBNP >125 pg/mL（非急性）","key":"新四联（ARNI/ACEI/ARB + β 阻滞剂 + MRA + SGLT2i）均有生存获益"},{"diseaseId":"hf_hfmref","dx":"LVEF 41%–49%，伴左室肥厚/左房扩大或 E/e' 升高，NT-proBNP 升高","key":"以 SGLT2i 为基石，ARNI 有获益"},{"diseaseId":"hf_hfpef","dx":"LVEF ≥50%，E/e' >15（9–15 需结合其他指标），左房容积指数 >34 mL/m²","key":"SGLT2i 有循证；重点利尿、控血压、治房颤/肥胖/OSA"},{"diseaseId":"hf_acute","dx":"急性呼吸困难 + 淤血/低灌注，NT-proBNP >300 pg/mL 或 BNP >100 pg/mL","key":"按湿冷/干冷/湿暖/干暖分型决定利尿与血管活性药"}],"diseases":[{"id":"hf_hfref","name":"射血分数降低的心力衰竭","aka":["HFrEF","收缩性心衰"],"rank":1,"basic":{"define":"有心衰症状和/或体征，且左室射血分数（LVEF）≤40% 的心力衰竭。","risk":["缺血性心肌病/心梗史","长期未控高血压","扩张型心肌病、心肌炎","糖尿病、肥胖","酒精、蒽环类/曲妥珠单抗等心脏毒性药物","持续性房颤等快速心律失常"],"epi":"我国 35 岁以上人群心衰患病率约 1.3%（约 890 万），HFrEF 约占 30%–40%；住院患者院内死亡约 4%–5%，1 年死亡约 15%–20%。"},"patho":"心肌损伤后收缩力下降，交感神经与 RAAS（AngⅡ、醛固酮）过度激活，导致水钠潴留、血管收缩与心室重构（心腔扩大、纤维化）；肾灌注下降致心肾综合征。四联药物通过逆转神经内分泌过度激活改善预后。","dx":{"criteria":["心衰症状（劳力性呼吸困难、端坐呼吸、乏力）和/或体征（肺啰音、颈静脉怒张、外周水肿、第三心音）","LVEF ≤40%（超声 Simpson 法）","NT-proBNP >125 pg/mL 或 BNP >35 pg/mL（非急性）；急性期 NT-proBNP >300 pg/mL 或 BNP >100 pg/mL（年龄分层 NT-proBNP：<50 岁 >450、50–75 岁 >900、>75 岁 >1800 pg/mL）","6 分钟步行试验 <150 m 为重度（<300 m 中度、>450 m 轻度）","伴左室扩大、左房扩大等结构性证据"],"workup":["超声心动图：LVEF、室腔大小、瓣膜、肺动脉压","心电图（缺血、房颤、传导阻滞，影响 CRT/β 阻滞剂选择）与胸片","NT-proBNP/BNP、血常规、肾功能+电解质、肝功能、血糖、甲功","心脏 MRI：病因不明的心肌病","冠脉造影/CTA：缺血病因可疑时","寻找诱因与合并症：贫血、感染、甲亢、用药不当"],"grading":"NYHA 分级：Ⅰ级活动不受限；Ⅱ级日常活动轻度受限；Ⅲ级低于日常活动即出现症状；Ⅳ级静息即有症状。ACC/AHA 分期 A–D。"},"ddx":[{"name":"射血分数轻度降低的心衰（hf_hfmref）","point":"与本类 hf_hfmref 的鉴别点：HFrEF LVEF ≤40%、左室显著扩大；HFmrEF LVEF 41%–49%，舒张功能异常更突出。"},{"name":"射血分数保留的心衰（hf_hfpef）","point":"与本类 hf_hfpef 的鉴别点：HFpEF LVEF ≥50%、室壁增厚、左房扩大、E/e' 升高；HFrEF 左室扩大室壁变薄。"},{"name":"急性失代偿性心衰/心源性休克（hf_acute）","point":"与本类 hf_acute 的鉴别点：HFrEF 为慢性稳定期；急性心衰数小时至数天急剧加重（肺水肿、低血压、少尿），需静脉利尿/血管活性药。"},{"name":"慢性阻塞性肺疾病/哮喘","point":"呼吸困难伴喘息、呼气延长，BNP 正常或轻度升高，肺功能示气流受限，LVEF 正常。"},{"name":"肾病综合征/肝硬化腹水","point":"水肿为主而肺淤血不明显，伴大量蛋白尿或门静脉高压征象，LVEF 正常。"},{"name":"心脏淀粉样变性","point":"老年、心电图低电压与室壁厚度不匹配、应变“心尖保留”，需核素显像或活检。"}],"tx":{"drug":[{"name":"沙库巴曲缬沙坦（ARNI）","dose":"50 mg bid 起始，每 2–4 周倍增，目标 200 mg bid","note":"首选替代 ACEI/ARB；由 ACEI 转换须停药 ≥36 h，SBP 需 ≥100 mmHg","renal":"eGFR <30 慎用；Cr 升高 >30% 减量","hepatic":"Child-Pugh C 不推荐","interact":"禁与 ACEI 合用；与保钾利尿剂合用高钾"},{"name":"培哚普利（ACEI）","dose":"2 mg qd 起始，每 1–2 周倍增，目标 4–8 mg qd","note":"不能耐受 ARNI 时选用；干咳者换 ARB","renal":"eGFR <30 起始减半","hepatic":"重度肝功能不全起始减半","interact":"与钾片、保钾利尿剂合用高钾"},{"name":"依那普利（ACEI）","dose":"2.5 mg bid 起始，目标 10 mg bid","note":"低钠、血流动力学不稳定者从小剂量起","renal":"eGFR <30 起始 2.5 mg qd","hepatic":"重度肝功能不全慎用","interact":"同 ACEI 类"},{"name":"雷米普利（ACEI）","dose":"1.25–2.5 mg qd 起始，目标 10 mg qd","note":"大型试验证实降低死亡","renal":"eGFR <30 起始 1.25 mg qd","hepatic":"重度肝功能不全慎用","interact":"同 ACEI 类"},{"name":"氯沙坦（ARB）","dose":"25–50 mg qd 起始，目标 150 mg qd（不耐受者 100 mg qd）","note":"ACEI 咳嗽或血管性水肿时替代","renal":"eGFR <30 慎用","hepatic":"肝功能不全起始 25 mg","interact":"同 RAAS 抑制剂"},{"name":"琥珀酸美托洛尔缓释片","dose":"11.875–23.75 mg qd 起始（需达干体重），每 2 周倍增，目标 190 mg qd 或最大耐受剂量","note":"起始心率 <55 次/分或 SBP <90 mmHg 暂缓；急性失代偿期不加量","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"避免与非二氢吡啶类 CCB 合用"},{"name":"比索洛尔","dose":"1.25 mg qd 起始，目标 10 mg qd","note":"选择性 β1，耐受性较好","renal":"eGFR <20 最大 10 mg","hepatic":"重度肝功能不全最大 10 mg","interact":"同 β 阻滞剂"},{"name":"卡维地洛","dose":"3.125 mg bid 起始，每 2 周倍增，目标 25 mg bid（>85 kg 者 50 mg bid）","note":"兼具 α1 阻滞，注意体位性低血压","renal":"慎用，遵说明书","hepatic":"重度肝功能不全禁用","interact":"抑制 CYP2D6，与氟西汀等合用升高浓度"},{"name":"螺内酯（MRA）","dose":"20 mg qd 起始，可增至 25–50 mg qd","note":"eGFR ≥30 且血钾 <5.0 mmol/L 时启动，2–3 天及 1 周复查血钾与肌酐","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 ACEI/ARB 合用高钾"},{"name":"依普利酮（MRA）","dose":"25 mg qd 起始，目标 50 mg qd","note":"螺内酯致乳房发育时替代","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"强 CYP3A4 抑制剂（克拉霉素）禁用"},{"name":"达格列净（SGLT2i）","dose":"10 mg qd（无需滴定）","note":"eGFR ≥20 可用，4 周内显效","renal":"eGFR <20 不推荐起始，已在用者可至透析前","hepatic":"重度肝功能不全慎用","interact":"与胰岛素/磺脲类联用需下调后者剂量"},{"name":"恩格列净（SGLT2i）","dose":"10 mg qd，可增至 25 mg qd","note":"降低心血管死亡与心衰住院","renal":"eGFR <20 不推荐起始","hepatic":"重度肝功能不全慎用","interact":"同 SGLT2i 类"},{"name":"呋塞米","dose":"口服 20–40 mg qd 起始，按容量调整；静脉 20–40 mg 缓慢推注，必要时加倍或持续输注","note":"缓解淤血，目标干体重；不改善生存","renal":"eGFR 降低需增量","hepatic":"注意低钾与肝性脑病","interact":"与地高辛合用致低钾性心律失常"},{"name":"地高辛","dose":"0.125 mg qd（≥70 岁或肾功能不全减量/隔日），目标 0.5–0.9 ng/mL","note":"合并房颤控制心率或仍有症状的窦律患者","renal":"eGFR <30 减量并监测浓度","hepatic":"遵说明书","interact":"胺碘酮、维拉帕米、螺内酯升高浓度"},{"name":"伊伐布雷定","dose":"2.5–5 mg bid 起始，滴定至心率 50–60 次/分，最大 7.5 mg bid","note":"窦律、已用最大耐受 β 阻滞剂而心率仍 ≥70 次/分","renal":"eGFR <15 慎用","hepatic":"重度肝功能不全禁用","interact":"强 CYP3A4 抑制剂禁用"},{"name":"维立西呱","dose":"2.5 mg qd 起始，每 2 周倍增，目标 10 mg qd","note":"NYHA Ⅱ–Ⅳ、近期心衰加重且基础治疗已优化","renal":"eGFR <30 慎用或减量","hepatic":"重度肝功能不全慎用","interact":"与 PDE5 抑制剂/硝酸酯联用注意低血压"}],"nonDrug":["CRT：LVEF ≤35%、窦律、QRS ≥150 ms 且 LBBB 为Ⅰ类；QRS 130–149 ms 且 LBBB 或非 LBBB QRS ≥150 ms 为Ⅱa","ICD 一级预防：优化药物 ≥3 个月后 LVEF ≤35%、NYHA Ⅱ–Ⅲ、预期生存 >1 年","心脏移植/左室辅助装置：终末期药物无效者评估","超滤：利尿剂抵抗并容量超负荷","限制液体 1.5–2 L/d（低钠者）"],"life":["限钠 <3 g/d","每日测体重，2–3 天增重 ≥2 kg 就诊","戒烟限酒，避免 NSAIDs、非二氢吡啶类 CCB、噻唑烷二酮类","心脏康复与中等强度运动","每 1–3 个月随访，每年流感疫苗"]},"prog":"优化四联后 1 年死亡率约 10%–12%；反复住院者 1 年死亡约 25%。LVEF <25%、NT-proBNP 高、肾功能受损、NYHA Ⅲ–Ⅳ 为不良预后因素。","refs":["中华医学会心血管病学分会《中国心力衰竭诊断和治疗指南 2024》","《中国心力衰竭诊断和治疗指南 2018》","2022 AHA/ACC/HFSA Heart Failure Guideline"]},{"id":"hf_hfmref","name":"射血分数轻度降低的心力衰竭","aka":["HFmrEF","射血分数中间值心衰"],"rank":2,"basic":{"define":"有心衰症状和/或体征，LVEF 41%–49%，并伴利钠肽升高或结构性心脏病证据的心力衰竭。","risk":["缺血性心脏病","高血压、糖尿病","老年、女性","房颤","早期心肌病"],"epi":"约占全部心衰的 15%–20%；年龄分布与 HFpEF 相近，随访约 1/3 转为 LVEF ≤40%。"},"patho":"介于收缩与舒张功能损害之间：收缩功能轻度减退兼左室僵硬度增加与重构；神经内分泌激活较 HFrEF 轻，心肌纤维化与顺应性下降是主要机制。","dx":{"criteria":["心衰症状和/或体征","LVEF 41%–49%","NT-proBNP >125 pg/mL 或 BNP >35 pg/mL（非急性）","或结构性证据：左房容积指数 >34 mL/m²、LV 质量指数（男 >115 g/m²、女 >95 g/m²）、E/e' >13、纵向应变降低","排除可逆因素（甲亢、重度贫血、快速房颤）"],"workup":["超声：LVEF、左房容积、E/e'、应变","NT-proBNP/BNP","血常规、肾功能、电解质、血糖、甲功","冠脉 CTA/造影：缺血病因","心脏 MRI（病因不明）"],"grading":"NYHA 分级 Ⅰ–Ⅳ，尚未形成统一分级。"},"ddx":[{"name":"射血分数降低的心衰（hf_hfref）","point":"与本类 hf_hfref 的鉴别点：HFrEF LVEF ≤40%、左室显著扩大；HFmrEF 仅轻度降低，可随访下降至 ≤40%。"},{"name":"射血分数保留的心衰（hf_hfpef）","point":"与本类 hf_hfpef 的鉴别点：HFpEF LVEF ≥50%、室壁增厚、E/e' >15；HFmrEF LVEF 41%–49%。"},{"name":"急性心衰（hf_acute）","point":"与本类 hf_acute 的鉴别点：HFmrEF 多为慢性稳定状态；急性心衰有肺水肿或低灌注，需静脉治疗。"},{"name":"肺部疾病所致呼吸困难","point":"BNP 正常或轻度升高，肺功能异常，超声无结构性心脏病。"}],"tx":{"drug":[{"name":"恩格列净（SGLT2i）","dose":"10 mg qd","note":"HFmrEF 证据最强，降低心衰住院与心血管死亡","renal":"eGFR <20 不推荐起始","hepatic":"重度肝功能不全慎用","interact":"与利尿剂/胰岛素联用注意容量与低血糖"},{"name":"达格列净（SGLT2i）","dose":"10 mg qd","note":"与恩格列净同属Ⅰ类推荐","renal":"eGFR <20 不推荐起始","hepatic":"重度肝功能不全慎用","interact":"同 SGLT2i"},{"name":"沙库巴曲缬沙坦（ARNI）","dose":"50 mg bid 起始，目标 200 mg bid","note":"尽早使用抑制重构；由 ACEI 转换间隔 36 h","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全不推荐","interact":"禁与 ACEI 合用"},{"name":"美托洛尔缓释片","dose":"23.75–47.5 mg qd 起始，目标 190 mg qd 或最大耐受","note":"合并冠心病、房颤或高血压时选用","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"忌与维拉帕米合用"},{"name":"螺内酯","dose":"20 mg qd，可增至 25–50 mg qd","note":"可选，需 eGFR ≥30 并监测血钾","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 RAASi 合用高钾"},{"name":"呋塞米","dose":"20–40 mg qd 口服，按淤血调整","note":"控制容量至干体重","renal":"肾功能不全增量","hepatic":"注意低钾","interact":"与地高辛合用致低钾性心律失常"}],"nonDrug":["合并冠心病者按指征血运重建","合并房颤考虑节律控制/消融","LVEF 降至 ≤35% 时按 HFrEF 评估 CRT/ICD"],"life":["限钠 <3 g/d，监测体重","规律运动与心脏康复","控制血压、血糖、血脂，戒烟限酒","3–6 个月复查超声评估 LVEF","避免 NSAIDs 与噻唑烷二酮类"]},"prog":"预后接近 HFpEF 而优于 HFrEF，年死亡率约 8%–12%；约 30% 患者 LVEF 降至 ≤40%。","refs":["中华医学会心血管病学分会《中国心力衰竭诊断和治疗指南 2024》","2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure"]},{"id":"hf_hfpef","name":"射血分数保留的心力衰竭","aka":["HFpEF","舒张性心衰"],"rank":3,"basic":{"define":"有心衰症状和/或体征、LVEF ≥50%，并具备左室充盈压升高或结构性心脏病证据的心力衰竭。","risk":["高龄、女性","高血压、糖尿病、肥胖与代谢综合征","房颤","慢性肾脏病","睡眠呼吸暂停","心肌淀粉样变、肥厚型心肌病"],"epi":"占全部心衰的 40%–50%，以老年女性为主；住院率与死亡率与 HFrEF 相近，1 年再住院率约 35%。"},"patho":"左室舒张功能减退与僵硬度增加（心肌肥大、胶原沉积、微血管稀疏）、左房重构与房颤；系统性炎症与代谢异常驱动。运动时变时性不足与肺动脉高压限制心输出量，导致运动耐量下降与肺淤血。","dx":{"criteria":["心衰症状和/或体征，LVEF ≥50%","NT-proBNP >125 pg/mL（窦律、非急性）或 >300 pg/mL（急性）；房颤者阈值约 2–3 倍","左房容积指数 >34 mL/m²；E/e' >15（或 9–15 结合其他指标）；LV 质量指数男 >115 g/m²、女 >95 g/m²","运动负荷超声：E/e' 升高 ≥15 或肺动脉收缩压升高","有创血流动力学（金标准）：静息肺毛细血管楔压 ≥15 mmHg（运动 ≥25 mmHg）","H2FPEF 评分 ≥6 高度提示，0–1 低度可能"],"workup":["超声（含应变、左房容积）","NT-proBNP/BNP","运动负荷超声或心肺运动试验","心脏 MRI（淀粉样变、肥厚型心肌病）","血常规、肾功能、甲功、铁代谢","睡眠呼吸监测；必要时右心导管"],"grading":"H2FPEF 评分（BMI >30、房颤、年龄 >60 岁、E/e' >9、肺动脉收缩压 >35 mmHg、利尿剂使用）：0–1 低、2–5 中间、6–9 高概率。NYHA 同样适用。"},"ddx":[{"name":"射血分数轻度降低的心衰（hf_hfmref）","point":"与本类 hf_hfmref 的鉴别点：HFpEF LVEF ≥50%；HFmrEF 为 41%–49%，部分由 HFpEF 演变而来。"},{"name":"射血分数降低的心衰（hf_hfref）","point":"与本类 hf_hfref 的鉴别点：HFpEF 左室不扩大、室壁增厚、E/e' 明显升高；HFrEF 左室扩大、LVEF ≤40%。"},{"name":"急性心衰/心源性休克（hf_acute）","point":"与本类 hf_acute 的鉴别点：HFpEF 为慢性；高血压性急性肺水肿可发生于 HFpEF 基础上，需静脉治疗。"},{"name":"心脏淀粉样变","point":"室壁增厚伴“颗粒”与应变心尖保留、心电图低电压与厚度不匹配，需核素显像与免疫固定电泳。"},{"name":"慢性阻塞性肺疾病","point":"呼气气流受限、肺过度充气，BNP 多正常，左房不扩大、E/e' 不升高。"},{"name":"肥胖相关运动耐量下降","point":"运动时呼吸困难无肺淤血体征，NT-proBNP 多正常，负荷试验无充盈压升高。"}],"tx":{"drug":[{"name":"恩格列净（SGLT2i）","dose":"10 mg qd","note":"HFpEF 唯一有明确循证改善预后，降低心衰住院与心血管死亡","renal":"eGFR <20 不推荐起始","hepatic":"重度肝功能不全慎用","interact":"与利尿剂合用注意低血压"},{"name":"达格列净（SGLT2i）","dose":"10 mg qd","note":"同恩格列净，Ⅰ类推荐","renal":"eGFR <20 不推荐起始","hepatic":"重度肝功能不全慎用","interact":"同 SGLT2i"},{"name":"呋塞米","dose":"20–40 mg qd 口服起始；急性淤血静脉 20–40 mg 推注","note":"改善淤血症状，无死亡获益；避免过度利尿","renal":"肾功能不全增量","hepatic":"注意低钾与肝性脑病","interact":"与地高辛合用致低钾性心律失常"},{"name":"螺内酯","dose":"20 mg qd（合并高血压或房颤者）","note":"部分分析提示获益，监测血钾","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 RAASi 合用高钾"},{"name":"沙库巴曲缬沙坦（ARNI）","dose":"50 mg bid 起始，可增至 200 mg bid","note":"非一线，部分分析降低心衰住院","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全不推荐","interact":"禁与 ACEI 合用"},{"name":"氯沙坦（ARB）","dose":"50 mg qd，可增至 100 mg qd","note":"合并高血压与左室肥厚可用；生存获益不确切","renal":"eGFR <30 慎用","hepatic":"肝功能不全减量","interact":"同 ARB 类"},{"name":"美托洛尔缓释片","dose":"23.75–47.5 mg qd（合并房颤或冠心病）","note":"不改善 HFpEF 生存，控制心率与合并症","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"忌与维拉帕米合用"},{"name":"利拉鲁肽（GLP-1 RA）","dose":"0.6 mg qd 皮下起始，1 周后 1.2 mg qd，可增至 1.8 mg qd","note":"合并肥胖者可改善症状与活动耐量（按体重滴定）","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与磺脲类/胰岛素联用低血糖风险"}],"nonDrug":["血压目标 <130/80 mmHg","合并房颤行节律控制（消融可改善耐量）","BMI ≥35 者减重/减重手术；OSA 行 CPAP","合并冠心病按指征血运重建","难治淤血可超滤"],"life":["限钠 <3 g/d，避免快速大量饮水","每周 ≥150 min 有氧运动，肥胖者减重 5%–10%","治疗糖尿病、房颤、OSA、CKD","监测血压、体重与肾功能，避免 NSAIDs"]},"prog":"年死亡率约 10%–15%，再住院率高。SGLT2i 将心衰住院相对风险降低约 20%–25%；合并淀粉样变或重度肺动脉高压者预后差。","refs":["中华医学会心血管病学分会《中国心力衰竭诊断和治疗指南 2024》","《射血分数保留的心力衰竭诊断与治疗中国专家共识》2021","2021 ESC Heart Failure Guidelines"]},{"id":"hf_acute","name":"急性心力衰竭与心源性休克","aka":["急性心衰","ADHF","急性肺水肿","心源性休克"],"rank":4,"basic":{"define":"心衰症状和体征在数小时至数天急剧加重（肺水肿、淤血或低灌注）需紧急处理者；伴持续低血压（SBP <90 mmHg ≥30 min）与组织低灌注为心源性休克。","risk":["慢性心衰急性失代偿（感染、心律失常、未依从、NSAIDs、停药）","急性心梗与机械并发症","急性心肌炎、Takotsubo","高血压急症、快速房颤","瓣膜急性病变（腱索断裂、感染性心内膜炎）"],"epi":"我国住院心衰中约 60% 为急性失代偿，院内死亡约 5%–10%；合并心源性休克者院内死亡 30%–50%。"},"patho":"容量与压力负荷骤增或收缩力急降，肺毛细血管楔压升至 >18–20 mmHg，形成肺水肿与低氧；心输出量下降致低灌注、乳酸酸中毒与多器官受累。","dx":{"criteria":["急性呼吸困难（端坐呼吸、夜间阵发性呼吸困难）、肺啰音、第三心音、颈静脉怒张、外周水肿","胸片肺门蝴蝶状浸润、Kerley B 线；床旁超声 B 线与充盈压升高","NT-proBNP >300 pg/mL 或 BNP >100 pg/mL（NT-proBNP 年龄阈值：50–75 岁 >900、>75 岁 >1800 pg/mL）","心源性休克：SBP <90 mmHg 持续 >30 min 或需升压药维持，乳酸 >2 mmol/L、尿量 <0.5 mL/kg/h；心指数 <2.2 L/min/m²、肺毛细血管楔压 >15 mmHg","急性肺水肿：SpO₂ <90% 或 PaO₂/FiO₂ <300"],"workup":["床旁心电图、胸片、血气、乳酸、血常规、肾功能与电解质","床旁超声（心功能、容量、机械并发症）","NT-proBNP/BNP、肌钙蛋白","血压、尿量、意识与灌注监测；必要时有创监测","诱因排查：感染、ACS、心律失常"],"grading":"分型：① 湿暖（淤血、灌注正常）→利尿；② 湿冷（淤血+低灌注）→利尿+正性肌力/血管活性药；③ 干冷→小量扩容+正性肌力；④ 干暖→口服过渡。Killip 分级用于心梗后心衰。"},"ddx":[{"name":"慢性 HFrEF 失代偿（hf_hfref）","point":"与本类 hf_hfref 的鉴别点：HFrEF 为慢性稳定期；急性心衰需住院静脉治疗，急性期 LVEF 可暂时下降需出院前复评。"},{"name":"HFmrEF（hf_hfmref）","point":"与本类 hf_hfmref 的鉴别点：HFmrEF 稳定期、LVEF 41%–49%；急性心衰可发生于任何 LVEF 区间，有无肺水肿/低灌注决定路径。"},{"name":"HFpEF（hf_hfpef）","point":"与本类 hf_hfpef 的鉴别点：HFpEF 为慢性；高血压性急性肺水肿（LVEF 正常）需与 ACS、哮喘鉴别。"},{"name":"急性冠脉综合征","point":"胸痛+ST 改变+肌钙蛋白升高，室壁运动异常对应冠脉分布；ACS 所致者按 STEMI/NSTEMI 处理。"},{"name":"慢性阻塞性肺疾病急性加重/哮喘","point":"呼气性呼吸困难伴喘息、肺过度充气，BNP 正常或轻度升高，支气管扩张剂有效。"},{"name":"感染性/低血容量性休克","point":"感染性休克有发热与感染灶、心排偏高；低血容量者前负荷低、补液改善；心源性休克超声示收缩功能严重下降。"}],"tx":{"drug":[{"name":"呋塞米（静脉）","dose":"20–40 mg 缓慢静推；已用利尿剂者按当日口服量 1–2.5 倍给药；效果不佳加倍或改 5–40 mg/h 持续输注（遵说明书）","note":"淤血者首选，监测尿量与肾功能；抵抗时联合美托拉宗","renal":"eGFR 降低需更高剂量","hepatic":"注意低钾与肝性脑病","interact":"NSAIDs 削弱利尿；与地高辛合用加强毒性"},{"name":"硝酸甘油（静脉）","dose":"5–10 µg/min 起始，每 5–10 min 递增 5–10 µg/min，按血压滴定（SBP ≥90 mmHg）","note":"高血压性急性肺水肿、湿暖型适用；低血压禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"禁用 PDE5 抑制剂"},{"name":"重组人脑利钠肽","dose":"1.5–2 µg/kg 静推后 0.0075–0.01 µg/kg/min 静滴（遵说明书）","note":"改善急性期呼吸困难；低血压者慎用","renal":"慎用，遵说明书","hepatic":"遵说明书","interact":"与利尿剂联用注意低血压"},{"name":"去甲肾上腺素","dose":"0.02–0.1 µg/kg/min 起始，按血压滴定，维持 MAP ≥65 mmHg","note":"心源性休克低血压首选升压药","renal":"遵说明书","hepatic":"遵说明书","interact":"不可与碱性液同管"},{"name":"多巴酚丁胺","dose":"2.5 µg/kg/min 起始，递增至 2.5–10 µg/kg/min","note":"湿冷型低心排伴低血压时联合去甲肾上腺素","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂合用效果减弱"},{"name":"米力农","dose":"负荷 25–50 µg/kg（不稳定者可不给），随后 0.375–0.75 µg/kg/min 静滴","note":"伴肺动脉高压的右心衰或用 β 阻滞剂者","renal":"CrCl 降低需减量（遵说明书）","hepatic":"重度肝功能不全慎用","interact":"与血管扩张剂叠加低血压"},{"name":"左西孟旦","dose":"12 µg/kg 缓慢推注（可省略），随后 0.05–0.1 µg/kg/min 静滴 24 h","note":"低心排伴右心功能不全、已用 β 阻滞剂者","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"与其他血管扩张剂叠加低血压"},{"name":"沙库巴曲缬沙坦（早期启动）","dose":"SBP ≥100 mmHg 且稳定后 50 mg bid 起始，住院期逐步上调","note":"入院 24–48 h 内评估启动，减少 30 天再住院","renal":"eGFR <30 慎用","hepatic":"Child-Pugh C 不推荐","interact":"禁与 ACEI 合用（间隔 36 h）"},{"name":"羧基麦芽糖铁（静脉）","dose":"按缺铁程度与体重计算总剂量（遵说明书），分次输注","note":"铁蛋白 <100 µg/L 或 100–299 µg/L 且转铁蛋白饱和度 <20%","renal":"eGFR <15 慎用","hepatic":"重度肝功能不全慎用","interact":"勿与口服铁剂同用"}],"nonDrug":["氧疗：SpO₂ <90% 给氧，目标 92%–96%（COPD 88%–92%）；呼吸窘迫用 CPAP/BiPAP，意识障碍者插管","心源性休克：紧急血运重建，机械循环支持（IABP、Impella、VA-ECMO）由心脏团队决策","机械并发症急诊外科","难治性容量超负荷：超滤/CRRT","急性期不加量或新增 β 阻滞剂"],"life":["半卧位、记录出入量与每日体重","限钠 <3 g/d，低钠者限液 1.5 L/d","出院前自我管理计划（体重、症状、依从性）","出院 7–14 天门诊随访并滴定基础药物","避免感染、劳累、擅自停药"]},"prog":"急性失代偿院内死亡 5%–10%，出院后 1 年死亡 20%–30%，30 天再住院约 20%；心源性休克院内死亡 30%–50%，多器官衰竭者更高。","refs":["《急性心力衰竭中国急诊管理指南》2022","中华医学会心血管病学分会《中国心力衰竭诊断和治疗指南 2024》","《心源性休克诊断和治疗中国专家共识》2019"]}]},{"id":"af","name":"心房颤动","rank":3,"summary":"评估卒中与出血风险后抗凝（非瓣膜性首选 DOAC），心室率控制或节律控制，并管理高血压、肥胖、睡眠呼吸暂停、饮酒等危险因素。","compare":[{"diseaseId":"af_parox","dx":"发作 <7 天（多在 48 h 内）自行或经干预终止，间歇期为窦性心律","key":"可自发恢复窦律，导管消融成功率高"},{"diseaseId":"af_persist","dx":"持续 >7 天或需药物/电复律才能终止","key":"心房重构明显，常需多次消融或“消融+药物”策略"},{"diseaseId":"af_valv","dx":"合并中重度二尖瓣狭窄（瓣口 <1.5 cm²）或机械瓣置换术后","key":"禁用 DOAC，须华法林（INR 2.0–3.0，机械瓣按瓣位设定）"}],"diseases":[{"id":"af_parox","name":"阵发性心房颤动","aka":["阵发性房颤","PAF"],"rank":1,"basic":{"define":"发作后 7 天内（多数在 48 h 内）自行终止、发作间期恢复窦性心律的房颤，为最常见类型。","risk":["年龄 ≥65 岁","高血压、冠心病、瓣膜病","糖尿病、肥胖、睡眠呼吸暂停","甲亢、过量饮酒","心房扩大、左室舒张功能不全","情绪应激与过度运动"],"epi":"我国 35 岁以上人群房颤患病率约 0.7%，60 岁以上约 1.8%，80 岁以上 >6%；阵发性房颤占全部房颤的 30%–50%。"},"patho":"肺静脉肌袖异位电位触发局灶快速除极，作用于存在纤维化与心房扩大的基质，形成快速紊乱的房性激动；心房收缩丧失与心室率过快导致血栓形成与心功能受损。","dx":{"criteria":["心电图（12 导联或 ≥30 s 单导联记录）示 P 波消失、快速不规则 f 波、RR 间期绝对不规则","持续 <7 天可自行终止；≥30 s 记录即可诊断","发作间期为窦性心律，需与其他房性心律失常鉴别","可穿戴设备清晰心电图可辅助诊断，需医生核实","CHA₂DS₂-VASc 评估卒中风险（女性 1 分、男性 ≥2 分建议抗凝）"],"workup":["12 导联心电图与动态心电图（24–48 h）或 14 天事件记录器","超声心动图：左房大小、LVEF、瓣膜","甲功、血常规、肾功能、电解质、肝功能","睡眠呼吸监测","拟消融/复律者左房 CT 或 TEE 排除血栓","CHA₂DS₂-VASc 与 HAS-BLED 评分"],"grading":"CHA₂DS₂-VASc：0 分（男）/1 分（女）低危；1 分（男）/2 分（女）中危；≥2 分（男）/≥3 分（女）高危。房颤负荷：<6 min/日偶发、6 min–24 h 阵发、>24 h 持续。"},"ddx":[{"name":"持续性房颤（af_persist）","point":"与本类 af_persist 的鉴别点：阵发性 7 天内自行终止；持续性 >7 天或需复律终止，心房重构更明显。"},{"name":"合并瓣膜病的房颤（af_valv）","point":"与本类 af_valv 的鉴别点：后者合并中重度二尖瓣狭窄或机械瓣，须华法林抗凝；阵发性房颤无瓣膜病变可选 DOAC。"},{"name":"房性期前收缩/房性心动过速","point":"可见清晰 P' 波，房速节律较规则，Holter 可见明确 P 波而非 f 波。"},{"name":"房室结折返性心动过速（AVNRT）","point":"突发突止、节律绝对规则、心率 150–250 次/分，迷走刺激或腺苷可终止。"},{"name":"心房扑动","point":"F 波呈锯齿状、频率 250–350 次/分，常有固定比例传导，三尖瓣峡部消融可根治。"}],"tx":{"drug":[{"name":"利伐沙班","dose":"20 mg qd 随餐；CrCl 15–49 mL/min 15 mg qd；CrCl <15 mL/min 不推荐","note":"非瓣膜性房颤首选抗凝，无需监测 INR","renal":"CrCl 15–49 减至 15 mg qd","hepatic":"Child-Pugh B 慎用，C 禁用","interact":"强 CYP3A4/P-gp 抑制剂（酮康唑、利托那韦）避免；利福平降低浓度"},{"name":"阿哌沙班","dose":"5 mg bid；若满足 ≥2 项（年龄 ≥80 岁、体重 ≤60 kg、肌酐 ≥133 µmol/L）减为 2.5 mg bid","note":"减量须严格满足标准","renal":"CrCl <25 mL/min 慎用（遵说明书）","hepatic":"Child-Pugh C 禁用","interact":"强 CYP3A4/P-gp 抑制剂/诱导剂影响浓度"},{"name":"达比加群酯","dose":"150 mg bid 或 110 mg bid（≥80 岁、合用维拉帕米、出血高危者选 110 mg bid）；CrCl 30–49 mL/min 110 mg bid；CrCl <30 mL/min 不推荐","note":"有特异性逆转剂依达赛珠单抗","renal":"按 CrCl 减量，<30 不推荐","hepatic":"严重肝功能损害禁用","interact":"维拉帕米、胺碘酮（P-gp 抑制）升高浓度需减量；利福平降低疗效"},{"name":"艾多沙班","dose":"60 mg qd；CrCl 15–49 mL/min、体重 ≤60 kg 或合用强 P-gp 抑制剂时 30 mg qd；CrCl <15 mL/min 不推荐","note":"按肾功能与体重减量","renal":"按 CrCl 减量","hepatic":"Child-Pugh B/C 慎用或禁用","interact":"环孢素、决奈达隆等强 P-gp 抑制剂需减量"},{"name":"华法林","dose":"2.5–3 mg qd 起始，按 INR 调整，目标 INR 2.0–3.0（TTR >70%）","note":"瓣膜性房颤、机械瓣或 DOAC 禁忌时","renal":"肾功能不全慎用，出血风险增加","hepatic":"严重肝病禁用","interact":"与胺碘酮、甲硝唑、NSAIDs 等相互作用多"},{"name":"美托洛尔（缓释/普通）","dose":"缓释 47.5–95 mg qd 起始；普通片 25–50 mg bid，目标静息心率 <110 次/分","note":"心室率控制一线；合并心衰时缓慢滴定","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"与维拉帕米合用可致心动过缓"},{"name":"比索洛尔","dose":"2.5–5 mg qd 起始，可增至 10 mg qd","note":"心率控制","renal":"eGFR <20 最大 10 mg","hepatic":"重度肝功能不全最大 10 mg","interact":"同 β 阻滞剂"},{"name":"地尔硫䓬","dose":"静脉 2.5–5 mg/h；口服缓释 90–180 mg qd","note":"不合并心衰时控制心率；LVEF <40% 禁用","renal":"慎用，遵说明书","hepatic":"肝硬化减量","interact":"与 β 阻滞剂合用加重心动过缓"},{"name":"地高辛","dose":"0.125 mg qd（老年/肾功能不全减量），目标 0.5–0.9 ng/mL","note":"合并心衰或 β 阻滞剂效果不足时加用","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"胺碘酮、维拉帕米升高浓度"},{"name":"胺碘酮","dose":"复律前负荷 200 mg tid × 1–2 周，渐减至 200 mg qd 维持；长期维持 100–200 mg qd","note":"合并结构性心脏病或心衰者节律控制首选；监测甲功、肺功能、肝功能","renal":"无需调整","hepatic":"肝功异常减量或停药","interact":"与华法林、地高辛相互作用显著"},{"name":"普罗帕酮","dose":"复律：450–600 mg 顿服（筛选合格者可“口袋药”）；维持 150 mg tid（可至 300 mg tid）","note":"仅无结构性心脏病、LVEF 正常者","renal":"重度肾功能不全减量","hepatic":"重度肝功能不全减量","interact":"与 β 阻滞剂合用增强负性传导；升高地高辛与华法林浓度"},{"name":"索他洛尔","dose":"80 mg bid 起始，必要时 160 mg bid；起始需住院监测 QT","note":"需 QTc <450 ms、eGFR >60","renal":"CrCl 40–60 减量，<40 慎用","hepatic":"遵说明书","interact":"与其他 QT 延长药合用增加尖端扭转风险"}],"nonDrug":["导管消融（肺静脉隔离）：阵发性房颤单次成功率约 70%–80%，症状性、药物无效或首选者","电复律：血流动力学不稳定或症状明显者，复律前抗凝 ≥3 周或 TEE 排除血栓","左心耳封堵：长期抗凝禁忌且 CHA₂DS₂-VASc ≥2","危险因素干预（减重、运动、戒酒、OSA 治疗）","起搏+房室结消融：室率难以控制且不宜消融者"],"life":["戒酒或严格限量","BMI >27 者减重 ≥10%，每周 ≥150 min 中等强度运动","控制血压、血糖，筛查睡眠呼吸暂停","限制咖啡因，避免疲劳与情绪应激","抗凝依从性与出血教育，每年复查肾功能"]},"prog":"年进展为持续性房颤约 5%–10%；充分抗凝后年卒中风险 1%–2%；消融后 1 年窦律维持率约 70%–80%。未抗凝者缺血性卒中风险增加 3–5 倍。","refs":["中华医学会心电生理和起搏分会《心房颤动：目前的认识和治疗建议（2021）》","《心房颤动诊断和治疗中国指南》2023","2024 ESC Guidelines for the management of atrial fibrillation"]},{"id":"af_persist","name":"持续性心房颤动","aka":["持续性房颤","非阵发性房颤"],"rank":2,"basic":{"define":"持续超过 7 天未自行终止、或需药物/电复律才能恢复窦律的房颤；持续 >1 年且仍拟节律控制者为长程持续性房颤。","risk":["高龄、高血压、心衰","长期未控房颤与左房扩大","肥胖、饮酒、睡眠呼吸暂停","瓣膜病、甲亢","慢性肾病"],"epi":"约占房颤的 30%–40%，随年龄与病程延长比例上升；长程持续性房颤约 10%–15%。"},"patho":"持续快速心房激动导致电重构（动作电位时程缩短、离子通道重塑）与结构重构（纤维化、左房扩大），折返基质固化使复律后易复发；心房收缩丧失与左心耳血流淤滞促发血栓。","dx":{"criteria":["心电图示 P 波消失、f 波替代、RR 间期绝对不规则，持续 >7 天或需复律终止","≥30 s 心动记录即可确诊；动态心电图 24–48 h 提高检出","长程持续性：持续 >1 年且仍计划节律控制","CHA₂DS₂-VASc ≥2（男）/≥3（女）建议抗凝；1 分（男）/2 分（女）亦应考虑","左房内径 >50 mm 或病程 >5 年提示复律/消融成功率降低"],"workup":["12 导联与动态心电图","超声：左房容积指数、LVEF、瓣膜、右心功能","甲功、肾功能、电解质、肝功能","拟复律者 TEE 排除血栓","消融前左房 CT/MRI","CHA₂DS₂-VASc 与 HAS-BLED"],"grading":"按持续时间分持续性（>7 天）与长程持续性（>1 年）；CHA₂DS₂-VASc 分层同阵发性房颤。"},"ddx":[{"name":"阵发性房颤（af_parox）","point":"与本类 af_parox 的鉴别点：阵发性 7 天内自行终止、间歇窦律；持续性 >7 天需复律，复发率更高。"},{"name":"合并瓣膜病的房颤（af_valv）","point":"与本类 af_valv 的鉴别点：瓣膜性房颤须华法林并处理瓣膜病变；持续性房颤无瓣膜狭窄者可首选 DOAC 与消融。"},{"name":"心房扑动伴不规则传导","point":"F 波呈锯齿状（Ⅱ、Ⅲ、aVF 明显），三尖瓣峡部消融可根治。"},{"name":"预激综合征合并房颤","point":"极快预激（RR 可 <250 ms）为急症，禁用房室结阻断药，需电复律。"}],"tx":{"drug":[{"name":"利伐沙班","dose":"20 mg qd 随餐；CrCl 15–49 mL/min 15 mg qd；CrCl <15 mL/min 不推荐","note":"非瓣膜性房颤标准抗凝","renal":"按 CrCl 减量","hepatic":"Child-Pugh B 慎用，C 禁用","interact":"强 CYP3A4/P-gp 抑制剂/诱导剂影响"},{"name":"阿哌沙班","dose":"5 mg bid；满足 ≥2 项减量条件（≥80 岁、≤60 kg、肌酐 ≥133 µmol/L）时 2.5 mg bid","note":"出血风险相对较低","renal":"CrCl <25 mL/min 慎用","hepatic":"Child-Pugh C 禁用","interact":"同 DOAC"},{"name":"达比加群酯","dose":"150 mg bid 或 110 mg bid；CrCl 30–49 mL/min 110 mg bid；<30 不推荐","note":"注意消化道出血","renal":"按 CrCl 减量","hepatic":"严重肝功能损害禁用","interact":"P-gp 抑制剂升高浓度"},{"name":"艾多沙班","dose":"60 mg qd；CrCl 15–49 mL/min、≤60 kg 或强 P-gp 抑制剂时 30 mg qd","note":"每日一次，依从性好","renal":"按 CrCl 减量，<15 不推荐","hepatic":"Child-Pugh B/C 慎用","interact":"强 P-gp 抑制剂减量"},{"name":"胺碘酮","dose":"200 mg qd 维持（复律前负荷 200 mg tid × 1–2 周，遵说明书）","note":"节律控制或复律后维持；监测甲功、肺功能","renal":"无需调整","hepatic":"ALT >3 倍停药","interact":"与华法林、地高辛相互作用显著"},{"name":"美托洛尔（缓释）","dose":"47.5–95 mg qd，目标静息心率 <110 次/分（节律控制中酌情 <80 次/分）","note":"室率控制及节律控制失败的过渡","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"与维拉帕米合用增加阻滞风险"},{"name":"地高辛","dose":"0.125 mg qd（肾功能不全减量），目标 0.5–0.9 ng/mL","note":"合并心衰或静息心率高时联合","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"胺碘酮升高浓度"},{"name":"索他洛尔","dose":"80 mg bid 起始，必要时 160 mg bid；起始住院监测 QT","note":"无结构性心脏病者节律控制；QTc >450 ms 禁用","renal":"CrCl 40–60 减量","hepatic":"遵说明书","interact":"避免与其他 QT 延长药合用"}],"nonDrug":["导管消融（肺静脉隔离 ± 后壁隔离）：单次成功率约 50%–70%，多次 70%–80%","电复律：拟节律控制、症状明显者，需评估左房容积与病程","房室结消融+起搏器：高龄、室率难控且不宜消融者","左心耳封堵：抗凝禁忌者","节律与室率控制策略按症状、心房大小、病程与意愿选择"],"life":["戒酒、减重、治疗 OSA 与高血压","不因“感觉正常”停药","每 6–12 个月复查心电图与肾功能","识别出血征象与卒中症状","接种流感疫苗"]},"prog":"药物复律后 1 年无复发率约 30%–50%，消融后 60%–70%；未抗凝者卒中风险与阵发性相似或更高。","refs":["《心房颤动诊断和治疗中国指南》2023","中华医学会心电生理和起搏分会《心房颤动：目前的认识和治疗建议（2021）》","2024 ESC Guidelines for the management of atrial fibrillation"]},{"id":"af_valv","name":"合并瓣膜病的心房颤动","aka":["瓣膜性房颤","风湿性房颤"],"rank":3,"basic":{"define":"合并中重度二尖瓣狭窄（瓣口面积 <1.5 cm²）或机械瓣置换术后的房颤，属“瓣膜性房颤”，抗凝须用华法林，禁用 DOAC。","risk":["风湿性心脏病（二尖瓣狭窄）","机械瓣置换术后","心衰与心房扩大","既往栓塞事件","高龄、高血压"],"epi":"风湿性心脏病仍是我国瓣膜性房颤的主要原因，合并二尖瓣狭窄者栓塞风险约为无房颤者的 5–10 倍；机械瓣术后房颤年卒中风险可达 4%–8%。"},"patho":"二尖瓣狭窄致左房压力升高、心房扩大与纤维化，形成持续房颤基质；房颤使心房收缩丧失、左心耳淤滞，血栓高发；机械瓣高致栓性叠加房颤进一步增加血栓风险。","dx":{"criteria":["房颤心电图（P 波消失、f 波、RR 不规则）","合并中重度二尖瓣狭窄（瓣口面积 <1.5 cm² 或跨瓣压差 >5 mmHg）或机械瓣置换术后","超声见二尖瓣狭窄、心房扩大及心房自发显影/血栓","华法林抗凝：二尖瓣狭窄 INR 2.0–3.0；机械瓣按瓣膜类型与位置设定（常见 2.0–3.0 或 2.5–3.5）","评估 CHA₂DS₂-VASc 与 HAS-BLED"],"workup":["超声：瓣口面积、跨瓣压差、Wilkins 评分、左房大小、左心耳血栓","心电图与动态心电图","INR 监测（TTR >70%）","血常规、肾功能、肝功能、凝血","必要时 TEE","拟瓣膜介入时心导管评估"],"grading":"瓣膜狭窄严重度：轻度 >1.5、中度 1.0–1.5、重度 <1.0 cm²；房颤按持续时间分型。"},"ddx":[{"name":"阵发性房颤（af_parox）","point":"与本类 af_parox 的鉴别点：后者无中重度瓣膜狭窄或机械瓣，可选 DOAC；瓣膜性房颤必须华法林并监测 INR。"},{"name":"持续性房颤（af_persist）","point":"与本类 af_persist 的鉴别点：持续性房颤可为非瓣膜性、DOAC 首选；瓣膜性房颤以瓣膜病变定性，抗凝药选择不同。"},{"name":"中重度二尖瓣反流（非狭窄、无机械瓣）","point":"仍属非瓣膜性房颤，DOAC 可用。"},{"name":"机械瓣血栓/瓣膜功能障碍","point":"突发心衰、瓣膜音改变、超声见跨瓣压差升高与血栓影，需急诊评估。"}],"tx":{"drug":[{"name":"华法林","dose":"2.5–3 mg qd 起始（高龄、低体重、心衰者减量），二尖瓣狭窄目标 INR 2.0–3.0；机械瓣按瓣膜类型与位置设定","note":"瓣膜性房颤唯一推荐口服抗凝","renal":"肾功能不全慎用，出血风险升高","hepatic":"严重肝病禁用","interact":"与胺碘酮、甲硝唑、NSAIDs 等相互作用多；维生素 K 摄入波动影响 INR"},{"name":"美托洛尔（缓释）","dose":"47.5–95 mg qd 起始，目标心率 <110 次/分","note":"室率控制，避免过度心动过速","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"与维拉帕米合用增加心动过缓"},{"name":"地尔硫䓬","dose":"缓释 90–180 mg qd；静脉 2.5–5 mg/h（LVEF 正常者）","note":"室率控制；合并心衰禁用","renal":"慎用，遵说明书","hepatic":"肝硬化减量","interact":"CYP3A4 抑制剂升高浓度"},{"name":"地高辛","dose":"0.125 mg qd（老年/肾功能不全减量）","note":"二尖瓣狭窄合并房颤控制室率常用，尤其合并心衰","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"胺碘酮、维拉帕米升高浓度"},{"name":"胺碘酮","dose":"200 mg qd（复律前负荷 200 mg tid × 1–2 周）","note":"节律控制；监测毒性","renal":"无需调整","hepatic":"ALT >3 倍停药","interact":"与华法林合用需减量并密切监测 INR"},{"name":"依诺肝素（围术期桥接）","dose":"1 mg/kg 皮下 q12h（CrCl <30 mL/min 1 mg/kg qd），华法林停用期间桥接（遵说明书）","note":"机械瓣桥接策略需团队个体化","renal":"CrCl <30 mL/min 减量","hepatic":"重度肝病慎用","interact":"与抗血小板联用增加出血"}],"nonDrug":["经皮二尖瓣球囊成形术：Wilkins 评分 ≤8、无左房血栓者","外科瓣膜置换/修复：重度反流、严重钙化或需同期 CABG 者","导管消融：症状明显者可考虑，左房巨大时成功率低","左心耳封堵：抗凝绝对禁忌者","机械瓣定期超声随访"],"life":["早期每周、稳定后每月监测 INR，TTR >70%","维生素 K 摄入保持稳定","戒酒、避免外伤","口腔卫生与心内膜炎预防","房颤症状与卒中体征教育"]},"prog":"充分抗凝后年卒中风险可降至 2%–4%；合并重度狭窄与左房巨大者栓塞与心衰风险仍高；抗凝不良的机械瓣患者年血栓栓塞率显著升高。","refs":["《心房颤动诊断和治疗中国指南》2023","中华医学会《中国瓣膜性心脏病诊治指南》2021","2024 ESC Guidelines for the management of atrial fibrillation","2020 ACC/AHA Valvular Heart Disease Guideline"]}]},{"id":"htn","name":"高血压","rank":4,"summary":"以血压水平与整体心血管风险分层决定起始时机与联合方案；高血压急症按靶器官损害类型控制降压速度，避免骤降致灌注不足。","compare":[{"diseaseId":"htn_primary","dx":"非同日 3 次诊室血压 ≥140/90 mmHg（家庭 ≥135/85、动态 24 h ≥130/80 mmHg）","key":"慢性管理，一般目标 <130/80 mmHg，优先单片复方制剂"},{"diseaseId":"htn_emerg","dx":"SBP ≥180 mmHg 和/或 DBP ≥120 mmHg，伴急性靶器官损害（脑病、ACS、肺水肿、主动脉夹层、急性肾损伤）","key":"需静脉降压并严格控制首小时降压幅度（一般 MAP 降幅 ≤25%）"}],"diseases":[{"id":"htn_primary","name":"原发性高血压","aka":["高血压","高血压病","EH"],"rank":1,"basic":{"define":"未使用降压药情况下，非同日 3 次测量诊室血压 SBP ≥140 mmHg 和/或 DBP ≥90 mmHg，排除继发因素的原发性血压升高。","risk":["高盐饮食（>5 g/d 食盐）","超重与肥胖（BMI ≥24 kg/m²）","过量饮酒、吸烟（含二手烟）","缺乏运动、长期精神紧张","睡眠呼吸暂停、糖尿病、血脂异常","高血压家族史、年龄 ≥55 岁"],"epi":"我国 ≥18 岁人群高血压患病率约 27%（约 2.45 亿患者），但控制率仅约 16%；高血压是卒中、冠心病、心衰与慢性肾病最重要可干预危险因素。"},"patho":"交感神经活性升高、RAAS 激活、钠敏感性增加与血管内皮功能障碍共同导致外周阻力增大、容量负荷增加；长期高压致小动脉重构（内膜增生、玻璃样变）与左室肥厚，最终引起脑、心、肾、眼底靶器官损害。","dx":{"criteria":["非同日 3 次诊室血压 ≥140/90 mmHg","家庭自测血压（连测 5–7 天，取平均值）≥135/85 mmHg","动态血压：24 h 平均 ≥130/80 mmHg，白天 ≥135/85 mmHg，夜间 ≥120/70 mmHg","≥65 岁老年患者可用 ≥140/90 mmHg；虚弱老年可 ≥150/90 mmHg","白大衣高血压：诊室升高而家庭/动态正常；隐匿性高血压：诊室正常而家庭/动态升高","初诊即需排除白大衣效应与继发性高血压（年轻、顽固、低钾、夜尿多、腹部杂音）"],"workup":["诊室、家庭与动态血压测量","血常规、尿常规、肾功能+电解质、血糖+HbA1c、血脂、尿酸、肝功能","心电图与超声心动图（左室肥厚）","眼底检查","尿白蛋白/肌酐比值（UACR）","低钾或顽固性高血压：醛固酮/肾素、甲状腺功能、皮质醇、睡眠呼吸监测、肾脏超声或肾动脉超声"],"grading":"血压分级：正常高值 130–139/85–89；1 级 140–159/90–99；2 级 160–179/100–109；3 级 ≥180/110 mmHg。心血管风险分层：低危、中危、高危、很高危（结合血压水平、危险因素、靶器官损害与临床合并症）。"},"ddx":[{"name":"高血压急症（htn_emerg）","point":"与本类 htn_emerg 的鉴别点：原发性高血压为慢性管理；高血压急症指 SBP ≥180/DBP ≥120 mmHg 伴急性靶器官损害，需静脉降压并可每 5–15 min 调量。仅血压升高而无急性损害者为“高血压亚急症”，口服药缓慢降压即可。"},{"name":"肾实质性高血压","point":"常见于 CKD、多囊肾、肾小球肾炎，伴蛋白尿/血尿、肌酐升高与肾脏缩小，多在年轻或顽固者。"},{"name":"肾血管性高血压（肾动脉狭窄）","point":"突发或顽固高压、腹部血管杂音、单侧肾缩小，肾动脉 CTA/MRA 确诊，多见于纤维肌性发育异常（青年女性）或动脉粥样硬化（老年）。"},{"name":"原发性醛固酮增多症","point":"高血压伴低钾（约 30%–40%）、醛固酮/肾素比值升高，肾上腺 CT 与盐水负荷试验确诊。"},{"name":"嗜铬细胞瘤","point":"阵发性头痛、心悸、多汗三联征，发作性血压骤升降，血浆游离甲氧基肾上腺素升高，CT/MRI 定位。"},{"name":"甲状腺功能亢进/妊娠期高血压","point":"甲亢伴心动过速、体重下降、TSH 降低；妊娠期高血压需与子痫前期鉴别（蛋白尿、血小板下降、肝酶升高）。"},{"name":"阻塞性睡眠呼吸暂停相关高血压","point":"夜间血压不降（非杓型）、晨峰明显、白天嗜睡，睡眠监测 AHI ≥5。"}],"tx":{"drug":[{"name":"氨氯地平","dose":"5 mg qd，最大 10 mg qd","note":"无禁忌者首选之一，尤其老年、单纯收缩期高血压","renal":"无需调整","hepatic":"肝功能不全起始 2.5 mg","interact":"与辛伐他汀 >20 mg 合用增加肌病风险"},{"name":"硝苯地平控释片","dose":"30 mg qd 起始，可增至 60–120 mg qd","note":"避免使用短效硝苯地平舌下含服降压","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"CYP3A4 抑制剂升高浓度"},{"name":"培哚普利（ACEI）","dose":"4 mg qd 起始，目标 8 mg qd","note":"合并糖尿病、蛋白尿、心衰、冠心病首选","renal":"eGFR <30 起始减半；肌酐升高 >30% 需评估","hepatic":"重度肝功能不全减量","interact":"与保钾利尿剂/钾片合用高钾；妊娠禁用"},{"name":"依那普利（ACEI）","dose":"5–10 mg bid 起始，目标 10–20 mg bid","note":"ACEI 类代表药","renal":"eGFR <30 起始减量","hepatic":"重度肝功能不全减量","interact":"同 ACEI；NSAIDs 减弱降压"},{"name":"氯沙坦（ARB）","dose":"50 mg qd，可增至 100 mg qd","note":"ACEI 咳嗽时替代","renal":"eGFR <30 慎用","hepatic":"肝功能不全减量","interact":"与保钾利尿剂合用高钾；妊娠禁用"},{"name":"缬沙坦（ARB）","dose":"80 mg qd 起始，可增至 160 mg qd","note":"耐受性好","renal":"无需按 eGFR 常规调整，重度受损慎用","hepatic":"肝功能不全减量","interact":"同 ARB"},{"name":"美托洛尔（缓释）","dose":"47.5 mg qd 起始，可增至 190 mg qd","note":"合并冠心病、心衰、心率快者首选","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"忌与非二氢吡啶类 CCB 合用；可掩盖低血糖"},{"name":"比索洛尔","dose":"2.5–5 mg qd 起始，可增至 10 mg qd","note":"选择性 β1 阻滞剂","renal":"eGFR <20 最大 10 mg","hepatic":"重度肝功能不全最大 10 mg","interact":"同 β 阻滞剂"},{"name":"氢氯噻嗪","dose":"12.5–25 mg qd","note":"联合用药基础；注意电解质与尿酸","renal":"eGFR <30 效果差，改用袢利尿剂","hepatic":"重度肝功能不全慎用","interact":"与地高辛合用致低钾；NSAIDs 减弱利尿降压"},{"name":"吲达帕胺（缓释）","dose":"1.5 mg qd","note":"降压效果与低钾风险较氢氯噻嗪略低","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与其他利尿剂合用低钾叠加"},{"name":"螺内酯","dose":"20 mg qd（顽固性高血压，第四线）","note":"需 eGFR ≥30 且血钾 <5.0 mmol/L","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 ACEI/ARB 合用高钾"},{"name":"培哚普利氨氯地平（单片复方）","dose":"5 mg/5 mg 或 10/5 mg qd（遵说明书）","note":"起始联合治疗时首选，提高依从性","renal":"按 ACEI 成分调整","hepatic":"按成分调整","interact":"同成分药物"}],"nonDrug":["≥2 级高血压、合并心血管病或高危患者起始即联合治疗（ACEI/ARB + CCB 或利尿剂）","难治性高血压（≥3 种含利尿剂药物未达标）评估继发原因、依从性与睡眠呼吸暂停","肾动脉狭窄/肾血管性高血压经评估后可考虑介入","原发性醛固酮增多症：肾上腺腺瘤手术或 MRA","嗜铬细胞瘤：α 阻滞剂（酚苄明）术前准备"],"life":["限盐 <5 g/d（必要时 <3.8 g/d），增加富钾食物","减重 BMI <24 kg/m²，腰围男 <90 cm、女 <85 cm","每周 ≥150 min 中等强度运动","限酒（男 ≤25 g/d 酒精，女 ≤15 g/d），戒烟","规律测量血压（家庭早晚各 1 次），按时服药","保持睡眠充足与心理平衡"]},"prog":"控制血压 <130/80 mmHg 可使卒中风险相对下降约 35%–40%；我国控制率仍不足 20%，多数患者需终身用药。坚持单片复方与家庭血压监测可显著改善达标率。","refs":["中华医学会心血管病学分会《中国高血压防治指南（2024 年修订版）》","《中国高血压防治指南（2018 年修订版）》","2024 ESC Guidelines for the management of elevated blood pressure and hypertension","《国家基层高血压防治管理指南》2020"]},{"id":"htn_emerg","name":"高血压急症","aka":["高血压危象","高血压急症（合并靶器官损害）, Hypertensive Emergency"],"rank":2,"basic":{"define":"血压急剧升高（通常 SBP ≥180 mmHg 和/或 DBP ≥120 mmHg）并伴急性靶器官损害（高血压脑病、急性冠脉综合征、急性肺水肿、主动脉夹层、急性肾损伤、子痫）的危重状态；无急性靶器官损害者为高血压亚急症。","risk":["既往高血压未控制或擅自停药","肾实质性疾病、肾动脉狭窄","嗜铬细胞瘤、子痫前期/子痫","可卡因/安非他命使用","急性卒中、主动脉夹层","钠负荷过高、NSAIDs 使用"],"epi":"占急诊就诊的 1%–2%，院内死亡率约 3%–10%，合并主动脉夹层、急性心衰或卒中者死亡率显著更高。"},"patho":"血压骤然升高超过脑血管与肾脏自动调节上限（平均动脉压约 110–130 mmHg 以上），内皮剪切力损伤、血管通透性增加与纤维样坏死，导致脑水肿、急性冠脉缺血、肺水肿与肾损害；随后激活的肾素-血管紧张素系统使血压进一步升高，形成恶性循环。","dx":{"criteria":["SBP ≥180 mmHg 和/或 DBP ≥120 mmHg（部分患者低于该值但有明确急性靶器官损害，须个体化）","伴急性靶器官损害：① 高血压脑病（意识障碍、抽搐、视乳头水肿）；② 急性冠脉综合征；③ 急性左心衰/肺水肿；④ 主动脉夹层；⑤ 急性肾损伤/恶性肾硬化；⑥ 子痫或子痫前期；⑦ 颅高压或眼底出血渗出","排除“高血压亚急症”：血压显著升高但无急性靶器官损害，可口服药缓慢降压，不需急诊静脉药物","需与白大衣效应/疼痛焦虑所致一过性血压升高鉴别"],"workup":["双眼血压对比、神经系统查体","心电图、肌钙蛋白、BNP","床旁胸片或超声（肺水肿、主动脉）","血常规、电解质、肌酐、尿常规（蛋白、红细胞）","眼底检查","怀疑夹层、卒中时行 CTA/MRI；妊娠者查尿蛋白、肝酶、血小板"],"grading":"按靶器官损害类型分类：高血压脑病、急性脑卒中、ACS、急性左心衰、主动脉夹层、肾功能不全、子痫前期/子痫、围术期高血压。按就诊病情分为高血压急症与亚急症。"},"ddx":[{"name":"原发性高血压（htn_primary）","point":"与本类 htn_primary 的鉴别点：原发性高血压为慢性、无急性靶器官损害，SBP 多 <180 mmHg，可在门诊滴定药物；高血压急症需静脉降压并每 5–15 min 监测，避免过快降压导致脑/肾灌注不足。"},{"name":"急性缺血性卒中/脑出血","point":"伴局灶神经功能缺损，需头颅 CT 明确；除非合并高血压脑病、溶栓或夹层，急性卒中早期降压一般不宜过急（SBP ≥220 mmHg 才干预）。"},{"name":"主动脉夹层","point":"撕裂样胸背痛、双上肢血压差 >20 mmHg、纵隔增宽，需 CTA；降压目标 SBP 100–120 mmHg 且心率 60 次/分以下，须 β 阻滞剂优先。"},{"name":"急性肺水肿（心源性）","point":"端坐呼吸、双肺湿啰音、BNP 升高；不能区分时按高血压性急性肺水肿处理（扩血管+利尿）。"},{"name":"嗜铬细胞瘤危象","point":"阵发性头痛、心悸、大汗伴血压骤升骤降，血/尿甲氧基肾上腺素升高；禁用单纯 β 阻滞剂，需 α 阻滞剂先行。"},{"name":"子痫前期/子痫","point":"妊娠 ≥20 周、蛋白尿、血小板减少、肝酶升高；治疗首选拉贝洛尔或肼屈嗪，硫酸镁预防抽搐。"}],"tx":{"drug":[{"name":"拉贝洛尔","dose":"静脉 10–20 mg 缓慢推注（2 min），必要时 10 min 后重复，总量 ≤300 mg；或 0.5–2 mg/min 持续输注","note":"大多数高血压急症一线（脑病、ACS、子痫均适用）；哮喘、严重心动过缓者禁用","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与 CCB 合用增加心动过缓；可掩盖低血糖"},{"name":"尼卡地平","dose":"静脉 5 mg/h 起始，每 5–15 min 增 2.5 mg/h，最大 15 mg/h","note":"起效快、易滴定，适用于多数急症；颅内压升高者慎用","renal":"无需调整","hepatic":"重度肝功能不全起始减量","interact":"CYP3A4 抑制剂升高浓度"},{"name":"乌拉地尔","dose":"静脉 12.5–25 mg 缓慢推注，随后 5–40 mg/h 持续输注","note":"α1 阻滞兼中枢作用，适用于围术期与脑卒中","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与其他降压药叠加低血压"},{"name":"硝酸甘油（静脉）","dose":"5–10 µg/min 起始，每 5 min 增 5–10 µg/min，按血压滴定","note":"急性冠脉综合征、急性肺水肿首选；颅内高压者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"禁用 PDE5 抑制剂"},{"name":"硝普钠","dose":"0.3–0.5 µg/kg/min 起始，逐渐增至 2–3 µg/kg/min（遵说明书），需动脉监测","note":"主动脉夹层等需精确控压时使用，连续使用不宜超过 24–72 h，防氰化物中毒","renal":"肾功能不全易蓄积氰化物，慎用","hepatic":"遵说明书","interact":"与其他扩血管药叠加低血压"},{"name":"艾司洛尔","dose":"静脉负荷 0.5 mg/kg（1 min），随后 50 µg/kg/min 输注，可增至 200 µg/kg/min","note":"主动脉夹层需先控制心率（<60 次/分）；超短效易滴定","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与其他 β 阻滞剂不叠加使用"},{"name":"美托洛尔（静脉）","dose":"2.5–5 mg 缓慢推注，可重复至总量 15 mg","note":"主动脉夹层、ACS 控制心率；心衰/心动过缓者慎用","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"勿与维拉帕米静脉制剂同用"},{"name":"呋塞米","dose":"静脉 20–40 mg 缓慢推注（急性肺水肿）","note":"肺水肿辅助，不作为单独降压药","renal":"肾功能不全需加量","hepatic":"低钾风险","interact":"与地高辛合用致低钾性心律失常"},{"name":"肼屈嗪（静脉）","dose":"5 mg 缓慢推注，可每 20–30 min 重复，或 0.5–10 mg/h 输注（子痫治疗常用，遵说明书）","note":"妊娠期高血压急症可选；反射性心动过速","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他扩血管药叠加低血压"},{"name":"硫酸镁","dose":"子痫/子痫前期：4–6 g 静脉负荷（20 min），随后 1–2 g/h 维持（遵说明书），监测呼吸与膝反射","note":"用于预防/控制抽搐，非单纯降压药","renal":"eGFR <30 减量并密切监测镁浓度","hepatic":"遵说明书","interact":"与 CCB 合用可致低血压与神经肌肉阻滞"},{"name":"酚妥拉明（α 阻滞剂）","dose":"嗜铬细胞瘤危象：静脉 1–5 mg 推注，随后持续输注（遵说明书）","note":"必须先 α 阻断后 β 阻断","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂合用致血压骤降"}],"nonDrug":["降压速度（一般认为）：多数急症首小时 MAP 降幅 ≤25%，随后 2–6 h 降至 160/100–110 mmHg，24–48 h 逐步达目标","主动脉夹层：SBP 100–120 mmHg 且心率 <60 次/分，先 β 阻滞剂再加用血管扩张剂","高血压脑病/子痫：可较快降压（首小时 MAP 降 20%–25%）以缓解脑水肿","急性缺血性卒中：不常规紧急降压，仅在 SBP ≥220 mmHg（拟溶栓时 ≥185/110 mmHg）时处理","脑出血：SBP >150 mmHg 可降至 140 mmHg 左右（个体化）","急性肺水肿/ACS：降压同时扩冠、利尿、按 ACS 流程"],"life":["急性期卧床、吸氧、心电与血压监测（有条件动脉置管）","病情稳定后 24–48 h 内过渡至口服药，避免立位低血压","出院前评估继发原因与依从性，制定长期血压管理方案","限盐、戒烟、规律随访，血压目标个体化","教育患者勿自行增减药物、定期家庭测压"]},"prog":"及时规范处理者死亡率约 3%–10%，合并主动脉夹层、急性心衰或卒中者死亡风险显著升高；1 年再发率约 10%–20%，坚持长期血压管理与继发原因纠正可显著改善预后。","refs":["中华医学会心血管病学分会《中国高血压防治指南（2024 年修订版）》","《高血压急症诊治中国专家共识》2017","2024 ESC Guidelines for the management of elevated blood pressure and hypertension","《中国急诊高血压诊疗专家共识（2017 修订版）》"]}]},{"id":"arrhythmia","name":"心律失常","rank":5,"summary":"先判断血流动力学是否稳定：不稳定（低血压、休克、意识障碍、胸痛、心衰）立即同步电复律（室颤/无脉室速直接除颤）；稳定者明确机制（窄 QRS 多为室上性，宽 QRS 先按室速处理）后选择药物、起搏或消融，并针对病因（缺血、电解质、甲亢、药物致心动过缓/尖端扭转）纠正可逆因素。","compare":[{"diseaseId":"ar_brady","dx":"窦性心率 <50 次/分、窦性停搏 ≥3 s 或窦房阻滞，伴黑矇/晕厥","key":"有症状的窦房结功能障碍首选永久起搏"},{"diseaseId":"ar_avb","dx":"PR 延长（I 度）、P 波后 QRS 脱漏（II 度）、P 与 QRS 各自独立（III 度）","key":"II 度 II 型与 III 度进展为完全性阻滞风险高，需起搏"},{"diseaseId":"ar_bbb","dx":"QRS ≥120 ms 伴右/左束支阻滞图形，每个 P 波后均有 QRS","key":"LBBB 掩盖心梗图形，新发 LBBB 伴胸痛按 STEMI 处理"},{"diseaseId":"ar_pvc","dx":"提前出现的宽大畸形 QRS、无前导 P 波、完全性代偿间歇","key":"Lown 3–5 级为复杂室早，负荷 >15% 需评估室早性心肌病"},{"diseaseId":"ar_af_flutter","dx":"P 波消失，见锯齿状 F 波 250–350 次/分，心室率可规则","key":"常伴器质性心脏病，典型房扑消融成功率高"},{"diseaseId":"ar_psvt","dx":"突发突止、窄 QRS 规则心动过速 150–250 次/分，P 波常隐匿于 QRS","key":"刺激迷走神经或腺苷可终止；宽 QRS 且预激者禁用房室结阻滞剂"},{"diseaseId":"ar_wpw","dx":"窦律 PR <120 ms、δ 波、QRS 增宽，A 型/B 型定位旁路","key":"禁用洋地黄、维拉帕米与 β 受体阻滞剂"},{"diseaseId":"ar_vt","dx":"宽 QRS 心动过速 100–250 次/分，房室分离、夺获/融合波","key":"不伴预激的宽 QRS 心动过速一律先按室速处理"},{"diseaseId":"ar_vf_scd","dx":"意识丧失、无脉搏，心电图示心室扑动/心室颤动波","key":"立即 CPR 与除颤，室颤存活者评估 ICD"},{"diseaseId":"ar_hereditary","dx":"QTc 延长（男 >470 ms、女 >480 ms）或 V1–V3 穹隆型 ST 抬高","key":"禁用延长 QT 的药物；高危者首选 ICD"}],"diseases":[{"id":"ar_brady","name":"窦房结功能障碍（病态窦房结综合征）","aka":["病态窦房结综合征","窦性心动过缓","窦性停搏","窦房阻滞","SSS"],"rank":1,"basic":{"define":"窦房结及其周围组织的起搏与传导功能减退，表现为持续性窦性心动过缓（<60 次/分，多数 <50 次/分）、窦性停搏（>2 s 无 P 波）、窦房阻滞，以及与快速房性心律失常交替的慢-快综合征（病态窦房结综合征）。","risk":["年龄增长、窦房结退行性变","缺血性心脏病、心肌病、心肌炎、淀粉样变","洋地黄、β 受体阻滞剂、非二氢吡啶类钙拮抗剂、胺碘酮等药物","甲减、高钾血症、低氧、颅内压增高","心脏手术或射频消融损伤窦房结/窦房结动脉"],"epi":"病态窦房结综合征占起搏器置入适应证的 30%–50%，多见于 60 岁以上人群，患病率随年龄增加。"},"patho":"窦房结 P 细胞自动去极化能力下降，周边心房肌纤维化使冲动传出受阻（窦房阻滞）；病变可累及房室结及希氏-浦肯野系统，形成慢-快综合征，心动过速后出现长时间停搏。","dx":{"criteria":["持续性窦性心律 <50 次/分，或窦性停搏 ≥3 s（清醒状态），或窦房阻滞，并伴相应症状（黑矇、晕厥、乏力、运动耐量下降）","窦性心动过缓 <40 次/分或反复窦性停搏 >3 s 提示高度功能障碍","动态心电图：24 h 平均心率 <50 次/分，或总心搏 <8 万次，或醒时最长 RR 间期 >3 s","症状与心动过缓的因果关系是诊断核心：有症状即可诊断，无症状的单纯窦缓不诊断 SSS","阿托品试验（静注 1–2 mg 后心率不能升至 90 次/分）提示窦房结功能减退"],"workup":["12 导联心电图与 24–48 h 动态心电图，必要时延长至 7–14 天事件记录器","运动试验观察心率变时性（最大心率 <0.8×（220−年龄）为变时性不全）","超声心动图评估结构病变与左房大小","甲功、电解质、心肌酶、药物史核查","窦房结功能检查：窦房结恢复时间、校正值、窦房传导时间","植入起搏器前评估房室传导（预防起搏器综合征）"],"grading":"按症状：无症状偶发、轻度（乏力、运动耐量下降）、重度（黑矇、晕厥、心衰加重）。按心电图：单纯窦缓型、窦房阻滞/窦性停搏型、慢-快综合征型。"},"ddx":[{"name":"房室传导阻滞（ar_avb）","point":"与本类 ar_avb 的鉴别点：窦房结功能障碍时 P 波明显减慢或消失、P 波与 QRS 一一对应；房室阻滞时 P 波频率正常，为 PR 延长或 QRS 脱漏。"},{"name":"药物性心动过缓","point":"停用 β 受体阻滞剂、地高辛、胺碘酮、非二氢吡啶类钙拮抗剂后心率恢复，应优先排除药物与电解质紊乱再考虑起搏器。"},{"name":"迷走神经张力过高/运动性心动过缓","point":"青年运动员或夜间睡眠时心率 <50 次/分、无黑矇晕厥、运动后心率可升至 >120 次/分，属生理现象。"},{"name":"甲减、高钾血症、低氧/低体温","point":"各有原发病表现与内分泌/生化异常，纠正后心动过缓改善。"},{"name":"癫痫、直立性低血压致晕厥","point":"晕厥时不伴心动过缓记录者为鉴别关键，须行倾斜试验、脑电图排除。"}],"tx":{"drug":[{"name":"阿托品","dose":"0.5 mg 静脉注射，可重复至总量 3 mg（成人）","note":"仅用于急性症状性窦缓的过渡处理；青光眼、前列腺增生者禁用；对严重窦房结病变反应差","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗胆碱能药合用作用增强"},{"name":"异丙肾上腺素","dose":"起始 1–2 μg/min 静脉泵入，按心率 60–70 次/分滴定","note":"临时起搏前的过渡；可诱发室性心律失常、心肌缺血","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂相互拮抗"},{"name":"茶碱（氨茶碱）","dose":"遵说明书，按体重与血药浓度调整","note":"仅作辅助提高心率，疗效证据有限，不作常规推荐","renal":"肾功能不全时清除减慢","hepatic":"肝功能不全者减量并监测血药浓度","interact":"与大环内酯类、喹诺酮类合用时浓度升高"}],"nonDrug":["有症状的窦房结功能障碍（含慢-快综合征、窦房结/窦房传导异常）为永久起搏 I 类适应证","单纯窦缓无相关症状、或症状由可逆因素（药物、电解质）所致者不置入起搏器","合并变时性不全、活动量需求大者选择频率应答起搏","持续房室传导正常者可选 AAI(R)，合并房室传导障碍者选 DDD(R)","急性期严重窦缓（晕厥、心衰、低血压）可临时起搏过渡","慢-快综合征中的快速房性心律失常可行导管消融，或起搏后药物控制心室率"],"life":["停用或调整致心动过缓药物，非必需药物需由医生权衡","避免迷走刺激诱因（用力排便、剧烈咳嗽、颈动脉窦压迫）","动态监测心率，定期程控起搏器参数与电池电量（每 6–12 个月）","起搏器后限制患侧上肢剧烈活动 6 周，避免强磁场环境","积极治疗缺血、甲减、电解质紊乱等基础病因"]},"prog":"无器质性心脏病者预后良好，主要死于心血管基础疾病；置入起搏器可显著改善晕厥与生活质量，但不能改善基础疾病预后，需长期随访房颤（起搏术后 5 年房颤发生率约 20%–30%）。","refs":["中华医学会心电生理和起搏分会. 心动过缓和传导异常患者的起搏和心脏同步治疗专家共识（2022 更新版）","中华医学会心电生理和起搏分会. 病态窦房结综合征中国专家共识（2018）","中国起搏器及电生理器械登记（2021 年度）","ACC/AHA/HRS Guideline on the Evaluation and Management of Patients With Bradycardia and Cardiac Conduction Delay, 2018"]},{"id":"ar_avb","name":"房室传导阻滞","aka":["AVB","II 度房室传导阻滞","III 度房室传导阻滞","莫氏 I 型","莫氏 II 型","文氏现象"],"rank":2,"basic":{"define":"激动自心房经房室结-希氏束-浦肯野系统向心室传导过程中延迟或阻滞，按程度分为 I 度（PR 延长）、II 度（部分 P 波后 QRS 脱漏，分 Mobitz I 型文氏与 Mobitz II 型）、III 度（心房心室完全分离）。","risk":["心肌梗死（下壁梗死多为房室结阻滞，前壁梗死多为希氏-浦肯野系统阻滞）","心肌炎、心肌病、心力衰竭","退行性传导系统疾病（Lenègre 病、Lev 病）、老年钙化","心脏瓣膜手术后、射频消融损伤","高钾血症、洋地黄中毒、β 受体阻滞剂/非二氢吡啶类钙拮抗剂/胺碘酮","先天性房室阻滞（母体抗 Ro/La 抗体）"],"epi":"老年人 II 度及以上房室阻滞患病率约 1%–3%，80 岁以上明显升高；起搏器置入原因中房室阻滞约占 20%–30%。"},"patho":"房室结阻滞多因缺血、药物、迷走张力增高引起，常为一过性且可逆；希氏束及以下阻滞多为纤维化退行性变、缺血坏死，呈不可逆且易进展为完全性阻滞。III 度阻滞时心室由低位逸搏点（交界区 40–60 次/分、室性 20–40 次/分）驱动，心率慢且不稳定。","dx":{"criteria":["I 度：PR 间期 >0.20 s（>200 ms），每个 P 波后均有 QRS","II 度 I 型（Mobitz I）：PR 间期逐渐延长直至一个 P 波后 QRS 脱漏，脱漏后 PR 缩短（典型文氏）","II 度 II 型（Mobitz II）：PR 间期恒定，间歇出现 P 波后无 QRS，常伴束支阻滞或宽 QRS","III 度：P 波与 QRS 波各自独立，P-P 与 R-R 规则，房率 > 室率，常有房室分离","症状：I 度多无症状；II、III 度可有乏力、头晕、黑矇、晕厥（阿-斯综合征）"],"workup":["12 导联心电图及 Holter，必要时长程记录至症状出现","运动试验与阿托品试验评估阻滞部位（给药后改善提示房室结阻滞）","超声心动图与左心室功能","心肌酶、电解质（血钾）、药物浓度（地高辛、胺碘酮）","冠脉评估（缺血性病因）、心脏磁共振（心肌病变）","希氏束电图测定 HV 间期（>100 ms 提示结下阻滞）","怀疑先天性阻滞者查母体抗 Ro/La 抗体"],"grading":"按阻滞部位：房室结阻滞（QRS 窄、阿托品可改善）与结下阻滞（QRS 宽、阿托品无效或加重）。按程度 I/II（I 型、II 型）/III 度。II 度 II 型与 III 度、有症状的高度阻滞均为起搏适应证。"},"ddx":[{"name":"窦房结功能障碍（ar_brady）","point":"与本类 ar_brady 的鉴别点：后者 P 波减少或消失而 P 与 QRS 关系正常；房室阻滞 P 波频率正常，异常在 P-QRS 传导关系。"},{"name":"交界性逸搏心律","point":"P 波可倒置或埋于 QRS 中，规则 40–60 次/分；III 度阻滞 P 波可见且未下传，房室分离明确。"},{"name":"未下传的房性期前收缩","point":"提前出现的 P' 波后无 QRS，易误为 II 度阻滞；基础心律 PR 恒定，无渐进延长。"},{"name":"2:1 房室传导的房性心动过速与心房扑动","point":"P'/F 波频率 >250 次/分，QRS 规律出现，本质为房室结生理性阻滞而非传导病变。"},{"name":"高钾血症所致中毒性宽 QRS","point":"T 波高尖、QRS 增宽，纠正血钾后传导恢复，应测血钾并停用保钾药物。"}],"tx":{"drug":[{"name":"阿托品","dose":"0.5 mg 静脉注射，每 3–5 min 可重复，总量不超过 3 mg","note":"房室结阻滞（尤其下壁心梗、迷走张力过高）有效；结下阻滞（宽 QRS）无效甚至加重，应慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗胆碱能药物叠加致尿潴留"},{"name":"异丙肾上腺素","dose":"1–4 μg/min 静脉泵入，按心率滴定，通常使心率维持 60 次/分左右","note":"用于临时起搏前过渡；急性心肌缺血者可能加重缺血与室性心律失常","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂拮抗"},{"name":"多巴胺","dose":"2–10 μg/(kg·min) 静脉泵入，按血压与心率滴定","note":"合并低血压的 III 度阻滞可选用，提升心率作用弱于异丙肾上腺素","renal":"遵说明书","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用作用增强"},{"name":"糖皮质激素","dose":"遵说明书（如甲泼尼龙 1 mg/kg 静脉给药），用于急性心肌炎所致阻滞","note":"仅针对免疫性/炎症性病因，需在专科指导下使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道出血风险"}],"nonDrug":["有症状的 II 度 II 型、III 度房室阻滞为永久起搏 I 类适应证","无症状但 HV 间期 >100 ms 或电生理检查诱发出希氏-浦肯野系统阻滞者应考虑起搏","II 度 I 型若为结下阻滞（宽 QRS）或伴症状，按高度阻滞处理","急性前壁心梗并发 II 度 II 型/III 度阻滞，即使症状缓解也应考虑永久起搏","下壁心梗所致房室阻滞多暂时性，可先临时起搏（经静脉或体外起搏）观察 5–7 天","起搏方式：窦房结功能正常者选 DDD(R)/VDD；慢性房颤者选 VVI(R)","心脏再同步治疗（CRT）适用于合并心衰（LVEF ≤35%）与 LBBB（QRS ≥150 ms）的阻滞患者"],"life":["停用或减量致阻滞药物（β 受体阻滞剂、非二氢吡啶类钙拮抗剂、地高辛、胺碘酮）","III 度阻滞患者避免单独活动、驾车与游泳，避免突然起立","教会患者及家属识别晕厥先兆并就医，必要时随身携带急救信息","起搏器术后定期随访与程控，每 6–12 个月一次，电池接近耗竭时缩短间隔","纠正电解质紊乱，监测血钾、甲状腺功能与肾功能"]},"prog":"I 度与稳定 II 度 I 型进展缓慢；II 度 II 型每年约 35%–50% 进展为完全性阻滞，未起搏的完全性阻滞年死亡率显著升高，阿-斯综合征为猝死主要原因。起搏治疗后症状明显改善，远期预后主要由基础疾病决定。","refs":["中华医学会心电生理和起搏分会. 心动过缓和传导异常患者的起搏与心脏同步治疗专家共识（2022 更新版）","中华医学会心血管病学分会. 急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","ACC/AHA/HRS Guideline on Bradycardia and Cardiac Conduction Delay, 2018","2021 ESC Guidelines on Cardiac Pacing and Cardiac Resynchronization Therapy"]},{"id":"ar_bbb","name":"室内传导阻滞","aka":["束支传导阻滞","完全性右束支阻滞","完全性左束支阻滞","左前分支阻滞","LAFB","LPFB","BBB"],"rank":3,"basic":{"define":"冲动在希氏束分叉以下（右束支、左束支及其前/后分支）传导延迟或阻断，心电图表现为 QRS 增宽及相应形态改变，分完全性与不完全性右/左束支阻滞及左前/左后分支阻滞。","risk":["高血压、冠心病、心肌梗死（尤其前壁与间隔部）","扩张型心肌病、肥厚型心肌病、心脏淀粉样变","Lenègre/Lev 退行性变、老年心脏传导系统纤维化","主动脉瓣置换术后、室间隔缺损封堵术后","心力衰竭（LBBB 提示机械不同步）","急性肺栓塞（右束支阻滞常为一过性）"],"epi":"成人完全性右束支阻滞约 0.2%–0.4%，随年龄升高（80 岁以上约 1%–2%）；完全性左束支阻滞约 0.1%–0.5%，与心血管死亡率及心衰风险显著相关。"},"patho":"束支阻滞使心室激动顺序改变：RBBB 时右室激动延迟；LBBB 时室间隔激动由右室向左室逆向开始，左心室内传导延迟致机械不同步，长期可致左室重构与心衰；分支阻滞仅改变左室电轴而 QRS 时限正常或轻度延长。","dx":{"criteria":["完全性右束支阻滞：QRS ≥120 ms，V1/V2 呈 rsR' 型（兔耳征），I、aVL、V5、V6 导联宽钝 S 波，ST-T 与主波方向相反","不完全性右束支阻滞：同 RBBB 图形但 QRS 110–120 ms","完全性左束支阻滞：QRS ≥120 ms，I、aVL、V5、V6 呈宽大 R 波（顶部切迹），V1 呈 QS 或 rS，I、V5、V6 无 q 波","左前分支阻滞：电轴左偏 −45°～−90°，II、III、aVF 呈 rS，I、aVL 呈 qR，QRS 常 <120 ms","左后分支阻滞：电轴右偏 +90°～+180°，I、aVL 呈 rS，II、III、aVF 呈 qR，QRS <120 ms（需排除右室肥厚与侧壁心梗）","双分支阻滞：右束支+左前/左后分支阻滞；双分支阻滞 HV >100 ms 或晕厥提示进展为三支阻滞"],"workup":["12 导联心电图，对比既往心电图判断新发或陈旧（新发考虑缺血/肺栓塞）","超声心动图评估心室大小与左室功能，LVEF <50% 者进一步评估","冠脉造影或冠脉 CTA（新发 LBBB 伴胸痛视为 STEMI 等同处理）","心脏磁共振鉴别心肌病、淀粉样变与浸润性疾病","B 型利钠肽、心肌酶、D-二聚体（新发 RBBB 需排除肺栓塞）","电生理检查（晕厥伴双分支阻滞、怀疑间歇性三支阻滞）"],"grading":"按形态：完全性（QRS ≥120 ms）与不完全性（QRS 110–120 ms）。按受累支：右束支、左束支、单分支、双分支、三支（双分支+一度房室阻滞或交替性束支阻滞）。"},"ddx":[{"name":"房室传导阻滞（ar_avb）","point":"与本类 ar_avb 的鉴别点：室内传导阻滞每个 P 波后都有 QRS、PR 间期正常或轻度延长，异常在 QRS 形态；房室阻滞异常在 P-QRS 的传导关系。"},{"name":"右心室肥厚/右心室扩大","point":"V1 R 波高（R/S >1）伴电轴右偏，但无 V1 的 rsR' 与侧壁宽 S 波；心脏超声见右室扩大。"},{"name":"室性期前收缩（ar_pvc）","point":"与本类 ar_pvc 的鉴别点：宽 QRS 提前出现且无前导 P 波、伴完全性代偿间歇；束支阻滞为窦性心律下的宽 QRS，每次有 P 波。"},{"name":"预激综合征（ar_wpw）","point":"与本类 ar_wpw 的鉴别点：WPW 的 PR 间期短（<120 ms）、有 δ 波；LBBB 型预激的 V1 图形酷似 LBBB，但 PR 缩短可鉴别。"},{"name":"心肌梗死（间隔坏死）","point":"LBBB 时 I、aVL、V5、V6 失去病理性 q 波，掩盖间隔梗死；需用 Sgarbossa 标准判断是否存在急性心梗。"}],"tx":{"drug":[{"name":"沙库巴曲缬沙坦（ARNI）","dose":"起始 50–100 mg bid，按耐受性逐步滴定至 200 mg bid","note":"合并 HFrEF（LVEF ≤40%）者作为基础治疗（依那普利需停用 36 h 后启用）","renal":"eGFR 30–60 时起始剂量减半，<30 慎用","hepatic":"Child-Pugh C 级减量","interact":"与保钾利尿剂合用易高钾"},{"name":"琥珀酸美托洛尔","dose":"23.75–47.5 mg qd 起始，逐步滴定至 95–190 mg qd","note":"合并 HFrEF 的基础治疗；束支阻滞本身无特异性药物治疗","renal":"遵说明书","hepatic":"重度肝功能不全者减量","interact":"与维拉帕米、地尔硫䓬合用抑制传导"},{"name":"肝素/低分子肝素","dose":"遵说明书","note":"新发 RBBB 伴右心负荷增加者需按肺栓塞流程评估并抗凝","renal":"肌酐清除率 <30 时按说明书减量","hepatic":"遵说明书","interact":"与抗血小板药物合用增加出血风险"}],"nonDrug":["新发 LBBB 伴典型胸痛按急性 STEMI 等同处理，急诊再灌注","合并晕厥的双分支阻滞、HV >100 ms 或电生理可诱发结下阻滞者行永久起搏（不全或间歇性三支阻滞）","HFrEF（LVEF ≤35%）合并完全性 LBBB 且 QRS ≥150 ms 为 CRT I 类适应证","LBBB 但心脏结构与功能正常、无房室阻滞证据者不需器械治疗","无症状的孤立性完全性 RBBB 不需特殊干预","主动脉瓣置换术前发现的 LBBB 须评估术后传导阻滞风险"],"life":["控制血压、血糖、血脂，戒烟限酒，预防缺血性心脏病进展","定期复查心电图与超声心动图，LBBB 伴心衰者每 6–12 个月评估 LVEF","可加重传导障碍的药物（β 受体阻滞剂、非二氢吡啶类钙拮抗剂）评估后谨慎使用","双分支阻滞者出现黑矇、晕厥立即就诊","合并心衰者限制钠盐、监测体重"]},"prog":"孤立性 RBBB 预后接近正常人群；LBBB 与心血管死亡、心衰住院、房室阻滞风险增加相关（RR 约 1.5–2.0）；双分支阻滞每年约 1%–5% 进展为完全性阻滞，合并晕厥者进展风险更高。","refs":["中华医学会心电生理和起搏分会. 心动过缓和传导异常患者的起搏和心脏同步治疗专家共识（2022 更新版）","中华医学会心血管病学分会. 慢性心力衰竭诊断和治疗指南（2024）","2021 ESC Guidelines on Cardiac Pacing and Cardiac Resynchronization Therapy","AHA/ACCF/HRS Recommendations for the Standardization and Interpretation of the Electrocardiogram, 2009"]},{"id":"ar_pvc","name":"室性期前收缩","aka":["室性早搏","室早","PVC","室性过早搏动","频发室早"],"rank":4,"basic":{"define":"希氏束分叉以下的心室异位起搏点提前发放冲动，心电图示提前出现的宽大畸形 QRS 波群（≥120 ms）、无前导 P 波、ST-T 与主波方向相反，伴完全性代偿间歇。","risk":["器质性心脏病（冠心病、心肌病、心衰）","心肌缺血、心肌炎、心肌瘢痕","电解质紊乱（低钾、低镁）、酸碱失衡","咖啡因、酒精、吸烟、精神紧张、睡眠不足","药物（洋地黄中毒、抗心律失常药致心律失常、拟交感药物）","年龄增长与高血压"],"epi":"健康人群 Holter 检出率 40%–75%，多数为偶发；室早负荷 >10% 者约 1%–4%，与左室功能下降及心肌病风险相关。"},"patho":"心室异位起搏点自律性增高、触发活动（早期/延迟后除极）或折返引起提前激动；频繁室早可致心室不同步收缩与重构，形成室早诱发性心肌病；器质性心脏病者的频发室早与室速、猝死风险相关。","dx":{"criteria":["心电图：提前出现的宽大畸形 QRS（≥120 ms），前无 P 波，ST-T 与主波相反，完全性代偿间歇","同一导联形态相同为单形性，两种及以上形态为多形性","按 Lown 分级评估严重度（见分级项）","24 h Holter 计算室早负荷（室早总数/总心搏数）；>10% 有临床意义，>15%–20% 需评估室早性心肌病","伴晕厥、成对、短阵室速（≥3 个连发）或 R-on-T 者风险高","无症状者仅体检发现，无需过度治疗"],"workup":["12 导联心电图与 24–48 h Holter 定量负荷、形态与联律","超声心动图评估 LVEF、室壁运动与结构","运动试验（观察运动时室早增多/减少）","电解质、甲功、心肌酶、药物史","心脏磁共振（怀疑心肌病/瘢痕）","疑似高危者（晕厥、家族性猝死）行电生理检查"],"grading":"Lown 分级：0 级无室早；1 级偶发单形（<30 次/h）；2 级频发单形（≥30 次/h）；3 级多源性；4A 级成对室早；4B 级短阵室速（≥3 个连发）；5 级 R-on-T 型室早。3–5 级（复杂室早）与猝死风险相关。"},"ddx":[{"name":"室性心动过速（ar_vt）","point":"与本类 ar_vt 的鉴别点：VT 为 ≥3 个连续室性搏动、频率 >100 次/分；室早为单个或成对提前搏动，不持续。"},{"name":"房性期前收缩伴差异性传导","point":"提前的 P' 波后出现宽 QRS，常呈右束支阻滞图形；代偿间歇多不完全，与室早的完全性代偿间歇不同。"},{"name":"预激综合征（ar_wpw）旁路前传图形","point":"与本类 ar_wpw 的鉴别点：WPW 为窦律下持续宽 QRS（δ 波），室早为单个提前搏动、有基础窦律。"},{"name":"高钾血症/药物所致宽 QRS","point":"全面宽 QRS、T 波高尖或 P 波消失，多为代谢性；纠正后恢复，而非单个提前搏动。"},{"name":"起搏器起搏心律","point":"可见起搏信号钉，节律规则，与自身心律关系明确；调阅起搏器记录可区分。"}],"tx":{"drug":[{"name":"美托洛尔/比索洛尔","dose":"美托洛尔 25–50 mg bid；比索洛尔 2.5–5 mg qd","note":"合并交感兴奋、器质性心脏病或心衰者首选，可减少室早并改善预后；注意心动过缓与低血压","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与维拉帕米、地尔硫䓬合用抑制传导"},{"name":"普罗帕酮","dose":"150 mg tid，最大 200 mg tid","note":"无器质性心脏病的症状性频发室早可选用；心梗、心衰、严重传导阻滞者禁用（CAST 研究示心梗后死亡增加）","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与胺碘酮、β 受体阻滞剂合用致心律失常风险增加"},{"name":"美西律","dose":"100–150 mg tid，按耐受性调整至 200 mg tid","note":"用于症状性室早；需监测 QRS 时限，增宽 >25% 时减量","renal":"肌酐清除率 <30 时减量","hepatic":"肝功能不全者减量","interact":"与普罗帕酮合用增加中枢神经系统不良反应"},{"name":"胺碘酮","dose":"起始 0.2 g tid，1 周后 0.2 g bid，再减为 0.2 g qd 维持","note":"其他药物无效或合并器质性心脏病的症状性频发室早可短期使用；长期不良反应多，不常规首选","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与华法林、地高辛合用需减量；避免与延长 QT 药物合用"},{"name":"门冬氨酸钾镁/氯化钾","dose":"遵说明书（依据血钾补充，维持血钾 ≥4.0 mmol/L）","note":"纠正低钾低镁；伴长 QT 或尖端扭转倾向者优先补充","renal":"肾功能不全者需监测血钾并减量","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI 合用增加高钾风险"}],"nonDrug":["无器质性心脏病、无症状或症状轻微的偶发室早不需治疗，仅随访","消除诱因（停咖啡因/酒精、补钾镁、治疗缺血、纠正心衰）优先于抗心律失常药","症状明显、药物无效，或室早负荷 >15%–20% 伴 LVEF 下降（室早性心肌病）者行射频消融","起源于右室流出道或左室分支的室早消融成功率高（>85%）","Lown 4B 级或伴晕厥、心室晚电位阳性者评估 ICD（尤其合并结构性心脏病）","合并心衰（LVEF ≤35%）者按心衰指南优化药物治疗，必要时评估 CRT/ICD"],"life":["戒烟限酒、减少咖啡因，规律睡眠，管理焦虑情绪","避免自行服用含麻黄碱的感冒药与兴奋剂","定期复查 Holter（每 6–12 个月）评估负荷变化","出现心悸伴胸闷、黑矇、晕厥或心率明显加快时及时就诊","适当有氧运动，器质性心脏病患者的剧烈运动须经评估"]},"prog":"无器质性心脏病的偶发室早预后良好；频发室早（负荷 >15%–20%）持续 1 年以上可致左室扩大及 LVEF 下降（室早性心肌病），消融后可逆；器质性心脏病合并复杂室早者猝死风险升高，但主要由基础心脏病程度决定。","refs":["中华医学会心电生理和起搏分会. 室性心律失常中国专家共识（2020 更新版）","中华医学会心血管病学分会. 慢性心力衰竭诊断和治疗指南（2024）","2022 ESC Guidelines for the Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death","AHA/ACC/HRS 2017 Guideline for Management of Patients With Ventricular Arrhythmias"]},{"id":"ar_af_flutter","name":"心房扑动","aka":["房扑","AFL","典型房扑","非典型房扑","峡部依赖性房扑"],"rank":5,"basic":{"define":"心房内大折返激动，频率 250–350 次/分（典型约 300 次/分），心电图示锯齿状 F 波，按房室传导比例（2:1、3:1、4:1 或可变）形成规则或规则-不规则的心室律。","risk":["高血压、冠心病、心肌病、瓣膜病、心力衰竭","慢性阻塞性肺疾病与肺部感染","甲状腺功能亢进、饮酒、心脏术后","心房扩大、心房纤维化","既往房颤、导管消融或外科迷宫术后（切口性房扑）"],"epi":"房扑患病率约 0.1%–0.4%，为房颤的 1/5–1/10；男性多见（约 2:1），多数患者会进展为房颤或与房颤交替。"},"patho":"典型房扑为右心房内围绕三尖瓣环的逆时针折返，折返环经下腔静脉-三尖瓣环峡部，形成常见型（逆钟向，下壁导联负向 F 波）与反向型；非典型房扑折返环位于左房或右房其他部位，常见于房颤消融或外科术后。房室结不能承受 300 次/分的房波传导，通常 2:1（室率约 150 次/分）或 4:1 传导。","dx":{"criteria":["心电图：无正常 P 波，见连续规则锯齿状 F 波，F-F 间期 200–240 ms（频率 250–300 次/分）","II、III、aVF 呈倒置锯齿波、V1 直立为典型逆钟向房扑；反向型下壁导联 F 波直立","2:1 传导时心室率约 150 次/分，易误诊为窦速或室上速；3:1 约 100 次/分，4:1 约 75 次/分","房室传导比例可变时心室律不规则，需与房颤鉴别","刺激迷走神经或腺苷可一过性加重房室阻滞，显露更多 F 波，明确扑动机制"],"workup":["12 导联心电图及 Holter（确认传导比例与间歇发作）","超声心动图：左右房大小、瓣膜、LVEF","甲功、电解质、血常规、肾功能","拟导管消融者行电生理检查，定位折返环（典型房扑为 CTI 依赖性）","拟复律者经食管超声排除心房血栓（房扑 >48 h 或抗凝不足）","CHA₂DS₂-VASc 评分评估血栓风险"],"grading":"按折返路径：典型房扑（峡部依赖性，分逆钟向与顺钟向）、非典型房扑（左房扑动、切口性房扑、局灶房扑）。按房室传导：固定比例（2:1/3:1/4:1）与可变传导。"},"ddx":[{"name":"心房颤动（af 大类）","point":"与本类 af 大类（心房颤动）的鉴别点：房颤 f 波形态不规则、心房率 350–600 次/分、心室律绝对不齐；房扑 F 波形态一致、房率 250–350 次/分，可规则。"},{"name":"阵发性室上性心动过速（ar_psvt）","point":"与本类 ar_psvt 的鉴别点：PSVT 突发突止，P 波隐匿于 QRS，多无连续锯齿波；房扑 F 波连续存在，迷走刺激可显露。"},{"name":"窦性心动过速","point":"2:1 房扑室率约 150 次/分易混淆；窦速有正常 P 波（II 导联直立）、有明确的病因且心率逐渐变化。"},{"name":"房性心动过速","point":"房速为局灶起源，P' 波之间可见等电位线、房率 150–250 次/分，与锯齿状 F 波不同；需电生理标测。"},{"name":"心室颤动/心室扑动（ar_vf_scd）","point":"无 P/F 波、心室波呈正弦波且不可辨认 QRS-T，伴意识丧失，须立即除颤，与房扑截然不同。"}],"tx":{"drug":[{"name":"胺碘酮","dose":"负荷 150 mg 静注 10 min，随后 1 mg/min 维持 6 h、0.5 mg/min 维持 18 h；口服维持 200 mg qd","note":"房扑复律与维持窦律均有效；需监测 QT、甲功、肝功能与肺毒性","renal":"遵说明书","hepatic":"肝功能异常时减量或停药","interact":"与华法林、地高辛合用需减量；避免与其他延长 QT 药物合用"},{"name":"伊布利特","dose":"体重 ≥60 kg：1 mg 静推 10 min；<60 kg：0.01 mg/kg 静推 10 min，10 min 后可重复一次","note":"主要用于急性房扑复律，转复率约 60%–80%；用药中及用药后 4 h 连续心电监护，QTc >440 ms、低钾、左室功能不全者禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他延长 QT 药物合用增加尖端扭转风险"},{"name":"索他洛尔","dose":"起始 80 mg q12h，按耐受性与 QTc 可增至 120–160 mg q12h，需住院监测","note":"维持窦律有效；QTc >500 ms 或肌酐清除率 <40 ml/min 禁用（延长 QT、致 TdP）","renal":"按肌酐清除率调整剂量并减量","hepatic":"遵说明书","interact":"与延长 QT 药物、噻嗪类利尿剂合用风险增加"},{"name":"美托洛尔","dose":"酒石酸美托洛尔 25–50 mg bid，或琥珀酸美托洛尔 47.5–95 mg qd","note":"控制房室传导、减慢心室率；急性心衰失代偿期慎用","renal":"遵说明书","hepatic":"重度肝功能不全者减量","interact":"与维拉帕米、地尔硫䓬合用可致严重心动过缓与低血压"},{"name":"地尔硫䓬","dose":"静脉 0.25 mg/kg（约 15–20 mg）缓慢静注 2 min，可 15 min 后重复；口服 30–60 mg tid","note":"心率控制效果与 β 受体阻滞剂相当；LVEF <40%、预激合并房扑者禁用","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与 β 受体阻滞剂合用增加传导阻滞风险"},{"name":"华法林/利伐沙班（抗凝）","dose":"华法林目标 INR 2.0–3.0；利伐沙班 20 mg qd（肌酐清除率 15–49 ml/min 用 15 mg qd）","note":"房扑血栓栓塞风险与房颤相当，CHA₂DS₂-VASc 评分指导下抗凝","renal":"利伐沙班在肌酐清除率 <15 禁用","hepatic":"Child-Pugh B/C 级禁用利伐沙班","interact":"华法林与胺碘酮合用需减少 30%–50% 剂量"}],"nonDrug":["血流动力学不稳定的房扑（低血压、心肌缺血、休克、心力衰竭）立即同步电复律，起始能量 50–100 J（双相波），无效加倍","典型房扑导管消融（下腔静脉-三尖瓣环峡部 CTI 线）成功率高（约 90%），为一线节律控制策略","房扑持续 >48 h 或抗凝不足者，复律前需 TEE 排除左房血栓并规范抗凝（复律前 3 周、复律后 4 周）","非典型房扑（含切口性房扑、左房扑动）可行三维标测引导消融","房室结消融+起搏器“消融起搏”策略用于老年、药物难治且心室率难以控制者"],"life":["戒酒、控制体重、治疗甲亢、改善睡眠呼吸暂停","监测心率与心律，出现心悸加重或晕厥立即就诊","长期抗凝须规律服药，避免漏服；行手术或有创操作时按医嘱调整抗凝","消融术后 3 个月为空白期，按医嘱用抗心律失常药与抗凝药","控制高血压、心衰等基础疾病，定期复查心电图"]},"prog":"典型房扑导管消融成功率约 90%，术后 3 年内约 20%–30% 出现房颤；未治疗者卒中风险与房颤相当，年卒中率约 2%–4%；发展为永久性房扑者心衰风险增加。","refs":["中华医学会心电生理和起搏分会. 心房颤动：目前的认识和治疗建议（2021）","中华医学会心电生理和起搏分会. 心房扑动诊断和治疗的中国专家共识","2020 ESC Guidelines for the Diagnosis and Management of Atrial Fibrillation","HRS/EHRA/ECAS/APHRS/SOLACE Expert Consensus Statement on Catheter and Surgical Ablation, 2017"]},{"id":"ar_psvt","name":"阵发性室上性心动过速","aka":["PSVT","室上速","AVNRT","AVRT","房室结折返性心动过速","房室折返性心动过速"],"rank":6,"basic":{"define":"起源于希氏束分叉以上的快速规则心律（多为折返性），最常见为房室结折返性心动过速（AVNRT）与房室折返性心动过速（AVRT），临床特点为突发突止、心率 150–250 次/分、QRS 多数窄而规则。","risk":["各年龄段均可发病，AVNRT 多见中青年女性，AVRT 多见于青年男性","交感神经激活（情绪激动、劳累、咖啡因、饮酒）","既往阵发性发作史","预激综合征（AVRT 的旁路基础）","低钾血症、甲亢、贫血可诱发"],"epi":"普通人群年发病率约 0.1%–0.2%，患病率约 0.2%–0.3%；AVNRT 占 PSVT 的 50%–60%，AVRT 约 30%–40%，约 60% 首发于 20 岁以前。"},"patho":"AVNRT 由房室结内纵向分离形成的快慢双径路折返，折返环局限在房室结内；AVRT 为心房-房室结-心室-旁路形成的大折返，顺向型（经房室结下传、旁路上传）QRS 窄，逆向型（经旁路下传）QRS 宽。激动频率由折返环不应期决定。","dx":{"criteria":["突发突止的规则快速心律，心率 150–250 次/分，持续时间数秒至数小时","窄 QRS（<120 ms，除非伴差异性传导或存在预激）","AVNRT：P 波常埋于 QRS 内或紧随 QRS（假性 r' 于 V1、假性 S 波于下壁导联），RP <90 ms","AVRT：逆行 P 波位于 QRS 后（RP >90 ms、RP <PR），可见 δ 波（窦律时）与 PR 缩短","小剂量腺苷或刺激迷走神经可终止（AVNRT 与 AVRT 均可），终止前可有短暂房室阻滞","发作稀少者需动态心电图或食管/心内电生理检查确认机制"],"workup":["12 导联心电图，窦律与发作时对比","24–72 h Holter 或事件记录器，发作稀少时延长监测","超声心动图（排除器质性心脏病）","电解质、甲功、血常规","电生理检查明确折返机制与慢径/旁路位置（拟消融者必做）","AVRT 患者需评估旁路前传不应期（高危旁路）"],"grading":"按机制：AVNRT（典型/非典型）、AVRT（顺向型/逆向型）、房速、窦房结折返性心动过速。按 QRS：窄 QRS 型、宽 QRS 型（伴差异性传导或逆传型 AVRT）。"},"ddx":[{"name":"预激综合征（ar_wpw）","point":"与本类 ar_wpw 的鉴别点：孤立 WPW 指窦律下短 PR+δ 波、无持续心动过速；顺向型 AVRT 为旁路参与的大折返，需电生理确认并评估消融。"},{"name":"心房扑动（ar_af_flutter）","point":"与本类 ar_af_flutter 的鉴别点：房扑 2:1 传导时室率约 150 次/分，锯齿状 F 波，迷走刺激后显露 F 波；PSVT 无连续 F 波。"},{"name":"心房颤动（af 大类）","point":"与本类 af 大类（心房颤动）的鉴别点：房颤心室律绝对不规则、无 P 波；PSVT 高度规则（除频发早搏干扰）。"},{"name":"室性心动过速（ar_vt）","point":"与本类 ar_vt 的鉴别点：宽 QRS 心动过速不伴预激时按室速处理；VT 常有房室分离、融合波、电轴偏转，血流动力学更差。"},{"name":"窦性心动过速","point":"P 波正常、心率逐渐变化、有明确诱因（发热、贫血、甲亢、焦虑），刺激迷走神经可逐渐减慢而非突然终止。"}],"tx":{"drug":[{"name":"腺苷","dose":"6 mg 快速静脉推注（1–2 s），无效则 12 mg 快速推注，可再重复 12 mg；推注后立即用生理盐水 20 ml 快速冲管","note":"首选终止药物，单次成功率 >90%；半衰期 <10 s；哮喘、严重 COPD、预激合并房颤者禁用（可致室颤）；需连续心电监护与除颤仪待命","renal":"遵说明书","hepatic":"遵说明书","interact":"与双嘧达莫合用作用增强（需减量），与咖啡因/茶碱合用作用减弱"},{"name":"维拉帕米","dose":"5 mg 静脉缓注 2 min，15 min 后可重复 5 mg；口服 40–80 mg tid","note":"腺苷无效或复发时的替代选择；LVEF <40%、宽 QRS 未明确机制、预激者禁用；低血压者慎用","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与 β 受体阻滞剂合用增加心动过缓与低血压风险"},{"name":"地尔硫䓬","dose":"0.25 mg/kg（约 15–20 mg）静脉缓注 2 min，可重复 0.35 mg/kg","note":"作用与维拉帕米类似，低血压发生率略低；禁忌证同维拉帕米","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与地高辛合用增加地高辛浓度"},{"name":"艾司洛尔","dose":"负荷 0.5 mg/kg 静注 1 min，随后 50 μg/(kg·min) 泵入，最大 200 μg/(kg·min)","note":"短效 β 受体阻滞剂，用于腺苷/钙拮抗剂禁忌或无效者；低血压、急性心衰、支气管痉挛者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与维拉帕米/地尔硫䓬合用可致心动过缓"},{"name":"普罗帕酮","dose":"70 mg 静脉缓注（10 min），无效 20–30 min 后重复 70 mg，总量不超过 210 mg","note":"无预激、无器质性心脏病者可用于复律；宽 QRS、器质性心脏病、心衰患者禁用","renal":"遵说明书","hepatic":"肝功能不全者减量并延长给药间隔","interact":"与胺碘酮、β 受体阻滞剂合用增加致心律失常风险"}],"nonDrug":["刺激迷走神经：改良 Valsalva 动作（半卧位用力呼气 15 s 后立即平卧并被动抬高下肢 15 s）成功率约 40%–50%，为院前首选","血流动力学不稳定（低血压、休克、意识改变、心肌缺血）立即同步电复律，10–50 J（双相波）起始","射频消融为根治手段：AVNRT 慢径改良消融成功率 >95%、并发症率 <1%；旁路消融成功率约 90%–95%","反复发作、药物无效或不愿长期服药者、高危职业（飞行员、驾驶员）者推荐消融","食管心房调搏可用于诊断与终止（尤其药物无效时）"],"life":["避免咖啡因、酒精、烟草，规律作息与睡眠","学习 Valsalva 动作自救方法（老年人及颈动脉狭窄者禁行颈动脉窦按摩）","发作时采取坐卧位并测心率、记录心电图，以便复诊","消融术后 3 个月内避免剧烈运动，定期复查心电图","若出现晕厥、胸痛或宽 QRS 心动过速，立即急诊就诊"]},"prog":"多数患者预后良好，AVNRT 与无器质性心脏病的 AVRT 不增加死亡风险；消融后长期无复发率约 90%–95%，复发多在 3 个月内；反复发作明显影响生活质量。","refs":["中华医学会心电生理和起搏分会. 室上性心动过速诊断和治疗中国专家共识（2018）","中华医学会心电生理和起搏分会. 预激综合征诊断和治疗中国专家共识（2019）","2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia","2019 ESC Guidelines for the Management of Supraventricular Tachycardia"]},{"id":"ar_wpw","name":"预激综合征（WPW 综合征）","aka":["WPW","沃-帕-怀综合征","预激综合征","旁路","δ 波"],"rank":7,"basic":{"define":"存在先天性房室旁路（Kent 束）使心室部分心肌提前激动，窦性心律时表现为 PR 间期缩短、δ 波与 QRS 增宽；部分患者经旁路形成折返性心动过速（AVRT）或诱发房颤伴快速心室率，即 WPW 综合征。","risk":["先天性旁路（多数为单旁路，少数多旁路）","青少年及中青年，男性略多","Ebstein 畸形等先天性心脏病常合并右侧旁路","家族聚集（PRKAG2 突变等）","合并房颤时经旁路快速传导可致室颤"],"epi":"人群心电图预激图形检出率 0.1%–0.3%；其中约 50%–60% 有心动过速发作（WPW 综合征），约 0.1%–0.4%/年发生心室颤动导致猝死。"},"patho":"旁路直接连接心房与心室，绕开房室结的传导延迟，使心室提前（预激）激动部分心肌；窦律时形成 δ 波，心动过速时旁路与房室结构成折返环。房颤时冲动经不应期短的旁路快速下传，可致极快心室率并蜕变为心室颤动。","dx":{"criteria":["窦性心律时 PR 间期 <120 ms，QRS 起始部粗钝（δ 波），QRS ≥120 ms，伴继发性 ST-T 改变","A 型（V1 主波向上，旁路在左室）、B 型（V1 主波向下，旁路在右室）","间歇性预激提示旁路不应期较长、猝死风险较低","合并房颤者表现为极快、绝对不规则的心室率（>250 次/分）与宽 QRS","无症状预激图形（仅有心电图异常）与 WPW 综合征（伴心动过速）需分别诊断"],"workup":["12 导联心电图（窦律与发作时）、动态心电图","超声心动图评估结构心脏病（Ebstein 畸形等）","电生理检查测定最短预激 RR 间期（<250 ms 为高危旁路）与旁路前传不应期","运动试验观察 δ 波是否消失（提示旁路不应期长、低危）","拟消融前行三维标测定位旁路位置","家族史与遗传评估（多旁路伴肥厚者考虑 PRKAG2）"],"grading":"按心电图定位：A 型/B 型；按旁路前传不应期：高危（<250 ms）、中危（250–300 ms）、低危（>300 ms 或运动后消失）。按临床：无症状预激、伴 AVRT、伴房颤、多旁路。"},"ddx":[{"name":"阵发性室上性心动过速（ar_psvt）","point":"与本类 ar_psvt 的鉴别点：AVNRT 窦律 PR 正常无 δ 波；顺向型 AVRT 依赖旁路逆传，窦律可有 δ 波，两者发作图形相似，须以窦律心电图和电生理区分。"},{"name":"室内传导阻滞的 LBBB 型（ar_bbb）","point":"与本类 ar_bbb 的鉴别点：LBBB 的 PR 正常、无 δ 波；WPW 的 PR <120 ms 且 QRS 起始部粗钝，为房室结与旁路双径同步激动。"},{"name":"心肌梗死（假性梗死图形）","point":"WPW 的 δ 波与负向 QRS 可在下壁导联出现 QS 波，误判为下壁心梗；结合 PR 缩短与冠脉影像正常可鉴别。"},{"name":"心室颤动（ar_vf_scd）","point":"与本类 ar_vf_scd 的鉴别点：预激伴房颤经旁路快速下传可蜕变为室颤，属终末事件；一旦无脉搏即按室颤处理并除颤。"},{"name":"左心室肥厚","point":"V5/V6 R 波高大伴劳损，PR 正常、无 δ 波；WPW 伴宽 QRS 易误判为肥厚，超声心动图可鉴别。"}],"tx":{"drug":[{"name":"腺苷（仅顺向型 AVRT 稳定、窄 QRS 时）","dose":"6 mg 快速静推，可重复 12 mg","note":"阻断房室结可终止顺向型 AVRT；严禁用于预激伴房颤（可增加旁路传导诱发室颤）","renal":"遵说明书","hepatic":"遵说明书","interact":"与双嘧达莫合用作用增强"},{"name":"普罗帕酮","dose":"发作时 70 mg 静脉缓注，无效可重复；口服维持 150 mg tid","note":"可抑制旁路前传；无器质性心脏病者可用；不推荐单独用于预激伴房颤","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与胺碘酮合用增加致心律失常风险"},{"name":"胺碘酮","dose":"150 mg 静脉缓注 10 min，随后 1 mg/min 泵入 6 h","note":"用于合并器质性心脏病的旁路伴房颤患者；长期口服前评估 QT、甲功与肺功能","renal":"遵说明书","hepatic":"肝功能异常时减量","interact":"与华法林、地高辛合用需减量"},{"name":"β 受体阻滞剂/维拉帕米/地高辛（禁用）","dose":"禁用，不给予常规剂量","note":"绝对禁用：阻断房室结后冲动更多经旁路下传，房颤时心室率进一步加快甚至室颤","renal":"不适用","hepatic":"不适用","interact":"与旁路前传形成协同致快心室率"}],"nonDrug":["射频导管消融为根治手段，成功率约 90%–95%，并发症率约 1%–2%","有症状的 WPW（AVRT 发作）为消融 I 类适应证；高危职业（运动员、飞行员、驾驶员）建议消融","无症状预激：电生理或运动试验提示高危旁路（最短预激 RR <250 ms）时考虑消融","预激伴房颤、心室率极快且血流动力学不稳定者立即同步电复律或除颤","合并 Ebstein 畸形者消融前需评估三尖瓣解剖，必要时外科同期处理","多旁路或消融失败者行外科旁路离断术，或长期胺碘酮治疗"],"life":["避免可诱发心动过速的因素（咖啡因、酒精、兴奋剂、剧烈情绪波动）","明确告知患者及急救人员：禁用洋地黄、维拉帕米、β 受体阻滞剂及非二氢吡啶类钙拮抗剂","未消融的高危患者避免参加竞技性运动与潜水","发作时记录心电图，发作持续 >30 min 或伴晕厥立即就医","消融后 1、3、6、12 个月复查心电图，复发时重新评估消融"]},"prog":"多数患者发作可控，消融后长期成功率 90%–95%；无症状预激者年猝死风险约 0.1%–0.4%，但部分以猝死为首发表现，故高危旁路需干预；合并器质性心脏病或房颤者风险显著增高。","refs":["中华医学会心电生理和起搏分会. 预激综合征诊断和治疗中国专家共识（2019）","中华医学会心电生理和起搏分会. 室上性心动过速诊断和治疗中国专家共识（2018）","ACC/AHA/ESC Guidelines for the Management of Patients With Supraventricular Arrhythmias, 2003","2022 ESC Guidelines for the Management of Patients With Ventricular Arrhythmias（预激伴房颤部分）"]},{"id":"ar_vt","name":"室性心动过速","aka":["室速","VT","单形性室速","多形性室速","尖端扭转型室速","TdP"],"rank":8,"basic":{"define":"起源于希氏束分叉以下、由 ≥3 个室性搏动连续组成的心动过速，频率 >100 次/分（多数 140–200 次/分），持续时间 <30 s 为非持续性（NSVT），≥30 s 或引起血流动力学障碍为持续性。","risk":["陈旧性心肌梗死与心肌瘢痕（最常见）","扩张型心肌病、肥厚型心肌病、致心律失常性右室心肌病","低钾、低镁、低钙血症","长 QT 综合征、Brugada 综合征等遗传性心律失常","药物（包括抗心律失常药、延长 QT 的抗生素/抗抑郁药）、电击","心肌炎、缺血发作"],"epi":"持续性室速多见于有器质性心脏病者，年发生率在心梗后 LVEF <40% 者中约 5%–10%；青少年猝死病例中遗传性心律失常约占 10%–30%。"},"patho":"瘢痕周围存活心肌构成的折返环是单形性室速的主要机制；多形性室速与尖端扭转型（TdP）由延迟后除极触发、QT 延长使复极离散加大所致；急性缺血、电解质紊乱促发触发活动。持续折返使心室同步收缩丧失、心排量下降，可蜕变为室颤。","dx":{"criteria":["宽 QRS（≥120 ms）心动过速，频率 >100 次/分，连续 ≥3 个室性搏动","支持室速的证据：房室分离（P 波与 QRS 无关）、夺获波、融合波、胸前导联同向性、电轴极度偏转","单形性：同一形态 QRS；多形性：QRS 形态与振幅逐搏变化、电轴扭转","尖端扭转型（TdP）：QRS 尖端围绕等电位线扭转、QTc 延长（多 >500 ms）、常由短-长-短联律间期诱发","非持续性：<30 s 自行终止；持续性：≥30 s 或需干预","晕厥、低血压、休克、心绞痛或心衰提示血流动力学不稳定"],"workup":["12 导联心电图（发作时与窦律时）、Holter、床边监护","电解质、血气、心肌酶、血药浓度（地高辛、胺碘酮等）","超声心动图、冠脉造影或冠脉 CTA 评估缺血与结构","心脏磁共振评估瘢痕、心肌病、心肌炎","QTc 测量（Bazett 公式）、家族史与心电图筛查（遗传性心律失常）","电生理检查明确折返环与消融靶点"],"grading":"按形态：单形性、多形性（含尖端扭转型）。按持续：非持续性（<30 s）、持续性（≥30 s 伴血流动力学障碍）。按病因：缺血性、非缺血结构性、特发性（右室流出道、左室分支）、遗传性离子通道病。"},"ddx":[{"name":"阵发性室上性心动过速（ar_psvt）","point":"与本类 ar_psvt 的鉴别点：PSVT 多窄 QRS、规则无房室分离；宽 QRS 伴差异性传导或逆传型 AVRT 需电生理鉴别，未明确前按室速处理。"},{"name":"预激综合征伴房颤（ar_wpw）","point":"与本类 ar_wpw 的鉴别点：预激伴房颤为不规则宽 QRS 极快心室率（>250 次/分）伴 δ 波形态；室速多为规则宽 QRS。二者均禁用房室结阻滞剂。"},{"name":"室内传导阻滞伴室上速（ar_bbb）","point":"已知 LBBB/RBBB 患者在心动过速时呈同一形态，需借助既往心电图与电生理检查。"},{"name":"心室颤动（ar_vf_scd）","point":"与本类 ar_vf_scd 的鉴别点：室颤无可辨认的 QRS 形态、属终末状态，须立即除颤；室速可有清晰 QRS，部分可电复律或药物终止。"},{"name":"高钾血症或药物致宽 QRS 心律","point":"查血钾、血气与用药史，重度高钾（>6.5 mmol/L）心电图似正弦波，须先降钾。"}],"tx":{"drug":[{"name":"胺碘酮","dose":"150 mg 静脉缓注 10 min，必要时重复；随后 1 mg/min 泵入 6 h、0.5 mg/min 泵入 18 h；无脉室速/室颤除颤时 300 mg 静推","note":"血流动力学稳定的单形性室速首选；合并结构性心脏病者长期预防首选；监测 QT 与血钾","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与华法林、地高辛合用需减量；避免与其他延长 QT 药物合用"},{"name":"硫酸镁","dose":"尖端扭转型室速：25% 硫酸镁 8 ml（2 g）稀释后静脉缓慢注射（10–20 min），可重复；随后 2–4 g/h 泵入维持","note":"TdP 首选，即使血镁正常也有效；低镁者需持续补充","renal":"肾功能不全时减量（易蓄积中毒）","hepatic":"遵说明书","interact":"与神经肌肉阻滞剂合用作用增强"},{"name":"利多卡因","dose":"1–1.5 mg/kg 静脉注射，必要时 5–10 min 后重复 0.5–0.75 mg/kg，总量 <3 mg/kg；随后 1–4 mg/min 泵入","note":"急性心肌缺血/心梗相关室速可选用；肝功能受损者减量","renal":"遵说明书","hepatic":"肝功能不全者显著减量","interact":"与 β 受体阻滞剂合用增加中枢神经毒性"},{"name":"艾司洛尔/美托洛尔","dose":"艾司洛尔 0.5 mg/kg 静注 1 min 后 50 μg/(kg·min)；美托洛尔 5 mg 静注（每次间隔 5 min，不超过 3 次）","note":"多形性室速或交感驱动性室速（如 CPVT）可用；心衰失代偿与心动过缓者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与维拉帕米合用可致心动过缓"},{"name":"异丙肾上腺素（TdP 伴心动过缓/长间歇）","dose":"1–2 μg/min 泵入，提高心率至 100–120 次/分","note":"用于获得性长 QT 致 TdP、伴心动过缓者；先天性长 QT 综合征患者禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂拮抗"}],"nonDrug":["血流动力学不稳定（低血压、休克、意识丧失、严重心肌缺血）立即同步电复律，单形性起始 100 J、多形性 200 J（双相波），无效递增","无脉室速按室颤处理：立即 CPR 与除颤 200 J","尖端扭转型室速：停用一切延长 QT 药物、纠正低钾低镁、必要时超速起搏或异丙肾上腺素","一级预防：心梗 40 天后 LVEF ≤35%（NYHA II–III）、或非缺血性心肌病 LVEF ≤35% 者置入 ICD","二级预防：合并结构性心脏病、血流动力学障碍的持续性室速，或心脏骤停幸存者行 ICD","反复发作、药物无效的室速行导管射频消融（尤其缺血性瘢痕、右室流出道、分支室速）；必要时联合 ICD"],"life":["坚持抗心律失常与心衰规范治疗，勿自行停药","避免延长 QT 药物（抗组胺药、大环内酯类、氟喹诺酮类、抗精神病药等）与低钾诱因","ICD/CRT-D 患者定期程控，术后避免强磁场；发生放电后立即就诊","家族筛查（长 QT 患者首度亲属心电图）、避免竞技运动与冷水刺激","定期复查电解质、心电图与心功能，每年至少一次"]},"prog":"持续性伴血流动力学障碍的室速若不及时终止可蜕变为室颤致猝死；器质性心脏病伴持续性室速者 2 年死亡率 20%–40%，ICD 可显著降低心律失常死亡率；特发性室速消融后预后良好；获得性长 QT 致 TdP 在纠正诱因后多可恢复。","refs":["中华医学会心电生理和起搏分会. 室性心律失常中国专家共识（2020 更新版）","中华医学会心血管病学分会. 急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","2022 ESC Guidelines for the Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death","AHA/ACC/HRS 2017 Guideline for Management of Patients With Ventricular Arrhythmias"]},{"id":"ar_vf_scd","name":"心室扑动与心室颤动 / 心脏性猝死","aka":["室扑","室颤","VF","心脏性猝死","SCD","心脏骤停","SCA"],"rank":9,"basic":{"define":"心室扑动呈规则正弦波样心室激动（约 200–250 次/分），心室颤动呈形态与振幅完全不规则的颤动波；两者使心室丧失有效泵血功能，导致心脏骤停。心脏性猝死指症状出现后 1 h 内由心脏原因引起的自然死亡，多数由室颤/室扑导致。","risk":["冠心病（尤其急性心梗与陈旧性心梗伴低 LVEF）","心肌病（扩张型、肥厚型、致心律失常性右室）与心力衰竭","遗传性心律失常（长 QT、Brugada、CPVT）与家族性猝死史","严重电解质紊乱（低钾、低镁、高钾）与药物致 QT 延长","剧烈运动、情绪应激、心动过缓-停搏后异位心律","既往心脏骤停或持续性室速史"],"epi":"我国每年心脏性猝死约 54.4 万人（每分钟约 1 人），院外心脏骤停存活率 <1%；冠心病占心脏性猝死病因的 50%–70%，院外可除颤心律约占 20%–30%。"},"patho":"急性心肌缺血或瘢痕折返使心室肌电活动完全失序、多子波碎裂，心肌丧失协调收缩；除颤越早成功率越高，每延迟 1 min 成功率下降 7%–10%。心脏骤停后 4–6 min 开始不可逆脑损伤。","dx":{"criteria":["意识突然丧失、大动脉（颈动脉）搏动消失、呼吸停止或叹息样、面色苍白或发绀","室扑为规则正弦波，无明显 QRS-T 区分（200–250 次/分）；室颤为不规则、形态振幅不一的颤动波","区分可除颤心律（室颤/无脉室速）与不可除颤心律（无脉电活动、心脏停搏）","心脏性猝死判定：急性症状出现后 1 h 内由心脏原因导致的死亡，排除非心源性"],"workup":["立即判断反应、呼吸与脉搏（≤10 s），启动急救系统与 CPR","连接除颤仪/监护，识别心律","复苏中每 5 min 复查心律、血气、电解质与血糖","复苏后 12 导联心电图、心肌酶、肌钙蛋白","冠脉造影（疑似急性缺血导致心脏骤停）","床旁超声评估可逆病因（心脏压塞、张力性气胸等）","存活者行心脏磁共振、电生理、遗传学与家族筛查"],"grading":"按心律分为可除颤心律（室颤、无脉室速）与不可除颤心律（心脏停搏、无脉电活动）。心脏性猝死风险分层常用 LVEF（≤35% 为高危）与病因（缺血性/非缺血性）。"},"ddx":[{"name":"室性心动过速（ar_vt）","point":"与本类 ar_vt 的鉴别点：有脉室速患者仍可触及脉搏、血压可测，室颤则脉搏消失、无意识；两者可互相转变。"},{"name":"阿-斯综合征（房室传导阻滞所致）（ar_avb）","point":"与本类 ar_avb 的鉴别点：完全性阻滞致心室停搏（长间歇）引起晕厥，心电图示长 RR 间期而非颤动波，起搏治疗后不再发作。"},{"name":"晕厥（血管迷走性、心源性）","point":"晕厥者意识多在 20–30 s 内自行恢复、有脉搏，与心脏骤停无脉搏、需 CPR 的本质不同。"},{"name":"低血糖昏迷/低氧性脑病","point":"测血糖可鉴别；低血糖者心搏存在，补充葡萄糖可迅速恢复。"},{"name":"癫痫大发作","point":"癫痫有抽搐、脉搏存在、发作后嗜睡与遗忘；抽搐也可发生于心脏骤停早期，须先判断脉搏。"}],"tx":{"drug":[{"name":"肾上腺素","dose":"1 mg 静脉/骨内注射，每 3–5 min 重复 1 次","note":"心脏骤停核心药物；可除颤心律在 2–3 次除颤后使用，不可除颤心律立即使用","renal":"骤停时无需调整","hepatic":"遵说明书","interact":"与 β 受体阻滞剂合用升压效果减弱"},{"name":"胺碘酮","dose":"可除颤心律：300 mg 静脉推注（首剂），第二剂 150 mg；复苏后维持 1 mg/min 泵入 6 h","note":"用于除颤无效的室颤/无脉室速；也可用利多卡因 1–1.5 mg/kg 替代","renal":"遵说明书","hepatic":"遵说明书","interact":"与延长 QT 药物合用增加致心律失常风险"},{"name":"利多卡因","dose":"1–1.5 mg/kg 静脉推注，必要时重复，维持 1–4 mg/min","note":"胺碘酮不可得时的替代；心梗相关室颤可选用","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与 β 受体阻滞剂合用增加中枢神经毒性"},{"name":"碳酸氢钠","dose":"1 mmol/kg 静脉给药（仅限特定情形）","note":"仅在已知高钾血症、三环类抗抑郁药过量或长时间停搏时考虑，不常规使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与儿茶酚胺同管路给药可致失活"},{"name":"硫酸镁","dose":"1–2 g 静脉缓慢注射（尖端扭转型或低镁时）","note":"对非尖端扭转的室颤证据不足，不常规使用","renal":"肾功能不全时减量","hepatic":"遵说明书","interact":"与神经肌肉阻滞剂合用作用增强"}],"nonDrug":["立即启动高质量 CPR：胸外按压 100–120 次/分，深度 5–6 cm，按压-通气比 30:2，尽量减少中断","尽快除颤：双相波 120–200 J（按厂家推荐），单相波 360 J，除颤后立即恢复按压 2 min 再评估","建立高级人工气道（声门上气道或气管插管），监测呼气末二氧化碳（EtCO₂ ≥10 mmHg 提示按压有效）","可逆病因（5H5T：低氧、低血容量、酸中毒、低钾/高钾、低体温；张力性气胸、心脏压塞、中毒、肺栓塞、冠脉血栓）须同步处理","自主循环恢复后目标温度管理（32–36 ℃ 至少 24 h），优化血压与氧合","ICD 适应证：心脏骤停幸存者（室颤/血流动力学不稳定室速）、心梗 40 d 后 LVEF ≤35%、非缺血性心肌病 LVEF ≤35% 且 NYHA II–III","公共场所配置 AED，推广公众心肺复苏培训"],"life":["高危患者及家属学习 CPR 与 AED 使用，家中可配置家用 AED","坚持心衰规范药物治疗（ARNI/β 受体阻滞剂/醛固酮拮抗剂/SGLT2 抑制剂）以降低猝死风险","严格控制血压、血脂、血糖，戒烟限酒，治疗睡眠呼吸暂停","ICD 患者定期程控，记录放电事件（ICD 放电一次即需复诊）","家族性猝死或离子通道病患者行一级亲属心电图、基因筛查","避免诱发因素：剧烈运动（高危患者）、过度劳累、严重电解质紊乱"]},"prog":"院外心脏骤停存活率 <10%，但早期除颤与高质量 CPR 可使存活率提升至 30%–50%；曾发生室颤的心脏骤停幸存者 1–3 年复发风险 20%–30%，置入 ICD 后心律失常死亡率显著下降；神经功能结局是远期预后的决定因素。","refs":["中华医学会心电生理和起搏分会. 心脏性猝死的一级预防中国专家共识","中华医学会急诊医学分会. 中国成人心肺复苏与心血管急救指南（2020/2023 更新）","AHA/ACC/HRS Guideline for the Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death, 2017","2020 AHA Guidelines for CPR and Emergency Cardiovascular Care"]},{"id":"ar_hereditary","name":"遗传性心律失常（长 QT 综合征与 Brugada 综合征）","aka":["LQTS","长 QT 综合征","Brugada 综合征","BrS","离子通道病","遗传性心律失常"],"rank":10,"basic":{"define":"由心肌离子通道（或相关调控蛋白）基因突变导致的原发性电生理异常，心脏结构多正常，表现为特定心电图改变与室性心律失常/猝死易感性。最常见两类为长 QT 综合征（LQTS，QT 延长致尖端扭转型室速）与 Brugada 综合征（右胸导联 ST 段穹隆型抬高致多形性室速/室颤）。","risk":["家族史（一级亲属猝死、晕厥或已知离子通道病）","青少年/青年男性，夜间晕厥或猝死","长 QT 的获得性加重因素：低钾低镁、延长 QT 药物、心动过缓","Brugada 的诱因：发热（>38.5 ℃）、钠通道阻滞剂、饮酒、饱餐、夜间迷走张力增高","运动/情绪激动诱发者需与 CPVT 鉴别"],"epi":"长 QT 综合征患病率约 1/2000–1/2500；Brugada 综合征在亚洲人群（尤其东南亚男性）患病率约 0.1%–0.5%，为年轻男性非结构性心脏病猝死的重要病因。"},"patho":"LQTS 多由钾通道（KCNQ1、KCNH2）功能缺失或钠通道（SCN5A）功能获得使复极延迟，QT 延长、复极离散增大，早期后除极诱发尖端扭转型室速。Brugada 综合征多为 SCN5A 功能缺失，右室流出道心外膜复极异常与局部传导延迟形成折返；两者均可蜕变为室颤导致猝死。","dx":{"criteria":["LQTS：QTc（Bazett）男性 >470 ms、女性 >480 ms 提示延长；≥500 ms 高度异常；结合晕厥、家族史、T 波异常按 Schwartz 评分诊断","LQTS 心电图：T 波宽大或切迹（LQT2 双峰 T 波），TdP 发作多为短-长-短联律起始","Brugada 综合征：V1–V3 中至少 1 个右胸导联（第 2–3 肋间）呈穹隆型 ST 段抬高 ≥2 mm；2/3 型需药物激发试验（阿义马林/氟卡尼）转为 1 型","伴自发晕厥或室颤者为高危 Brugada 确诊条件之一","基因检测：约 70%–80% LQTS 可检出致病突变（KCNQ1、KCNH2、SCN5A 最常见）；Brugada 约 20%–30% 检出 SCN5A 突变","须排除获得性原因（电解质、药物、心肌缺血、心肌病）后方可诊断遗传性"],"workup":["12 导联心电图测量 QTc（取 II 或 V5 导联，Bazett），必要时 Holter 与运动试验","Brugada 需在高位肋间（V1–V2 第 2–3 肋间）复查心电图","发热时复查心电图（Brugada 发热可显现典型图形）","电解质（钾、镁、钙）、甲功、药物清单","超声心动图、心脏磁共振排除结构性心脏病（尤其 ARVC）","基因检测（先证者及一级亲属级联筛查）","电生理检查（Brugada 综合征风险分层）"],"grading":"LQTS Schwartz 评分：≥3.5 分高度可能，1–3 分中等可能，≤1 分可能性小。Brugada：I 型（诊断性）、II 型（马鞍型）、III 型；高危特征为确诊 1 型 + 既往心脏骤停/晕厥。"},"ddx":[{"name":"心室颤动（ar_vf_scd）","point":"与本类 ar_vf_scd 的鉴别点：后者为终末心律失常事件，本类为可致室颤的基础电生理异常；猝死者需基因检测明确是否离子通道病。"},{"name":"室性心动过速（ar_vt）","point":"与本类 ar_vt 的鉴别点：结构性心脏病（瘢痕）来源的室速与离子通道病机制不同，需靠心脏磁共振、基因检测与心电图特征区分。"},{"name":"获得性长 QT（电解质、药物、心动过缓）","point":"纠正诱因后 QTc 恢复；遗传性者 QTc 持续延长且一级亲属中亦异常。"},{"name":"急性心肌梗死致 ST 抬高","point":"STEMI 的 ST 抬高伴病理性 Q 波、胸痛与心肌酶升高；Brugada 图形在右胸导联孤立出现且无心肌损伤标志物异常。"},{"name":"致心律失常性右室心肌病（ARVC）","point":"结构改变（右室扩大、室壁运动异常、epsilon 波），心脏磁共振或超声可区别。"}],"tx":{"drug":[{"name":"β 受体阻滞剂（LQTS 基础治疗）","dose":"普萘洛尔 1–2 mg/(kg·d) 分 2–3 次；纳多洛尔 0.5–1 mg/(kg·d)；无绝对禁忌时终身使用","note":"LQT1 与 LQT2 首选，尤其运动诱发者；需监测心率、血压与 QTc；避免漏服（停药可致反弹）","renal":"纳多洛尔经肾排泄，肾功能不全减量","hepatic":"遵说明书","interact":"与维拉帕米合用抑制传导"},{"name":"美西律（LQT3 辅助）","dose":"100–200 mg tid，按耐受性调整","note":"阻断晚钠电流，缩短 LQT3 的 QTc；须与 β 受体阻滞剂联合","renal":"肌酐清除率 <30 时减量","hepatic":"肝功能不全者减量","interact":"与胺碘酮合用增加致心律失常风险"},{"name":"雷诺嗪（LQT3）","dose":"遵说明书（一般 500–1000 mg bid，按耐受性调整）","note":"抑制晚钠电流，可缩短 QT；国内证据有限，专科指导使用","renal":"重度肾功能不全慎用","hepatic":"肝功能不全者减量","interact":"抑制 CYP3A4，浓度升高"},{"name":"奎尼丁（Brugada 辅助）","dose":"遵说明书（小剂量 200 mg bid 起，监测心电图）","note":"对 Brugada 发作有抑制作用，用于 ICD 反复放电者；需监测 QT 与血药浓度","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与胺碘酮合用增加 QT 延长风险"},{"name":"异丙肾上腺素（Brugada 电风暴）","dose":"1–2 μg/min 静脉泵入，按心率调整","note":"可纠正 Brugada 电风暴、抑制反复室颤；仅院内监护下使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂拮抗"}],"nonDrug":["ICD 为高危患者（既往心脏骤停、晕厥伴自发 1 型 Brugada 图形、LQTS 经 β 受体阻滞剂后仍晕厥）的首选预防手段","Brugada 综合征行右室流出道心外膜基质消融，可显著减少 ICD 放电","发热（>38.5 ℃）时积极退热并使用对乙酰氨基酚，Brugada 患者住院观察（危险窗约 24–72 h）","左心交感神经切除术（LCSD）用于药物难治性 LQTS 高危及反复放电者","一级亲属筛查：心电图、运动试验与基因检测（级联筛查）","LQTS 患者避免竞技性运动（尤其游泳、冬泳、哨声刺激）与突发惊吓"],"life":["携带“禁忌药物清单”卡片（CredibleMeds 列表），就诊时主动告知医生","避免自行服感冒药、胃肠动力药与抗组胺药等延长 QT 或阻断钠通道药物","避免剧烈运动、冷水刺激、睡眠惊醒及情绪激动（尤其 LQT1）","发作前驱症状（心悸、黑矇、晕厥）出现时立即就坐或平卧，避免摔伤","ICD 患者定期程控；放电后立即复诊评估诱因","避免低钾低镁（腹泻、呕吐、过度利尿时及时补钾），育龄患者遗传咨询与妊娠期管理"]},"prog":"未治疗的 LQTS 晕厥年发生率约 5%，猝死风险与 QTc、突变类型相关（LQT3 静息风险最高、LQT1 以运动诱发为主）；β 受体阻滞剂可降低 60%–70% 的心律失常事件。Brugada 有晕厥或心脏骤停史者 3 年内室颤复发率约 15%–20%；无症状 1 型患者年猝死风险约 0.5%。","refs":["中华医学会心电生理和起搏分会. 遗传性心律失常中国专家共识（2021）","中华医学会心血管病学分会. 心脏性猝死的一级预防中国专家共识","2015 ESC Guidelines for the Management of Patients With Ventricular Arrhythmias（遗传性心律失常部分）","HRS/EHRA/APHRS Expert Consensus Statement on Inherited Primary Arrhythmia Syndromes, 2013"]}]},{"id":"vhd","name":"心脏瓣膜病","rank":6,"summary":"以超声定量分级决定随访与干预，核心门槛是「症状 + 心室重构」：有症状或无症状但已出现左室/左房损害即需干预，并警惕急性瓣膜反流的急症表现。","compare":[{"diseaseId":"vhd_ms","dx":"心尖部舒张中晚期隆隆样杂音 + 开瓣音 + S1 亢进；超声测瓣口面积与平均跨瓣压差","key":"MS 为舒张期杂音、有开瓣音、左房大而左室不扩大"},{"diseaseId":"vhd_mr","dx":"心尖部全收缩期吹风样杂音向腋下传导、S1 减弱；超声测反流容积与 EROA","key":"急性 MR 突发肺水肿伴低血压而左室不扩大；慢性 MR 以左室扩大为特征"},{"diseaseId":"vhd_as","dx":"主动脉瓣区收缩期喷射性杂音向颈部传导、A2 减弱、脉压小；超声测流速、平均压差与瓣口面积","key":"AS 收缩期杂音、脉压小；AR 舒张期杂音、脉压宽"},{"diseaseId":"vhd_ar","dx":"胸骨左缘第 2–3 肋间舒张期叹气样递减型杂音，前倾坐位呼气末最清，伴水冲脉、脉压增宽","key":"急性 AR（夹层/心内膜炎）可无典型杂音，仅表现为突发肺水肿与低血压"},{"diseaseId":"vhd_rheumatic","dx":"链球菌咽炎史 + Jones 标准（2 项主要或 1 主要 + 2 次要）+ 链球菌感染证据","key":"风湿热是 MS/多瓣膜病变的病因，需判断活动性并启动二级预防"},{"diseaseId":"vhd_tv","dx":"三尖瓣反流见颈静脉 v 波、肝大与下肢水肿，超声示瓣环扩张与反流束；肺动脉瓣狭窄见喷射性收缩期杂音、P2 减弱，超声估测跨瓣压差","key":"以右心容量负荷为主，多继发于左心病变或肺动脉高压；重度三尖瓣反流提示右室扩大与预后不良"}],"diseases":[{"id":"vhd_ms","name":"二尖瓣狭窄","aka":["Mitral Stenosis","MS","风湿性二尖瓣狭窄"],"rank":1,"basic":{"define":"二尖瓣叶增厚、粘连、交界融合致舒张期左房至左室血流受阻，我国以风湿性最常见（>90%），少数为退行性钙化或先天性。","risk":["风湿热或链球菌咽炎史，30–50 岁女性多见","风湿热高发地区居住","重度二尖瓣环钙化（老年，多为瓣下梗阻）","罕见：类风湿、系统性红斑狼疮"],"epi":"我国风湿性心脏病患病率逐年下降，但中西部农村仍不低；女性多于男性，男女比约 1:2。"},"patho":"风湿性炎症致瓣叶纤维化、交界粘连、腱索缩短，瓣口由正常 4–6 cm² 缩小。左房压升高引起左房扩大、肺静脉压升高（活动后 >25 mmHg 即出现劳力性呼吸困难）、反应性肺血管收缩与肺动脉高压，继发右心衰。左室因充盈受限舒张末期容积偏小。左房扩大与心肌纤维化是房颤与左房血栓的温床。","dx":{"criteria":["症状：劳力性呼吸困难、夜间阵发性呼吸困难、咯血、声音嘶哑（Ortner 综合征）、右心衰表现","心尖区舒张中晚期低调隆隆样杂音（左侧卧位、呼气末、钟形探头更清），窦性心律者可收缩期前增强；S1 亢进；瓣叶弹性好时出现开瓣音（OS），A2–OS 间距越短越重；P2 亢进、可闻 Graham Steell 杂音（肺动脉瓣相对关闭不全）","超声：轻度瓣口面积 >1.5 cm²、平均压差 <5 mmHg；中度 1.0–1.5 cm²、压差 5–10 mmHg；重度 <1.0 cm²、压差 ≥10 mmHg（心率 60–80 次/分），或肺动脉收缩压 >50 mmHg","合并中重度主动脉瓣反流或快心率时压力减半时间（PHT）法误差大，应改用直接平面法或 3D 面积法"],"workup":["经胸超声：瓣口面积、平均压差、瓣叶形态（Wilkins 评分）、左房内径、肺动脉收缩压、合并 MR","经食管超声：左房/左心耳血栓、Wilkins 评分不明确、球囊成形术前","心电图：P 波双峰增宽（P mitrale）、房颤、右室肥厚；胸片：左房增大、肺淤血、含铁血黄素沉着","负荷超声：症状与静息指标不符时","血常规、肾功能、INR（抗凝者）、ASO（疑活动性风湿）"],"grading":"超声分级：轻 >1.5 cm²；中 1.0–1.5 cm²、压差 5–10 mmHg；重 <1.0 cm²、压差 ≥10 mmHg、肺动脉收缩压 >50 mmHg。Wilkins 评分（瓣叶活动度、厚度、钙化、瓣下增厚，各 0–4 分）≤8 分提示适合经皮球囊成形。"},"ddx":[{"name":"二尖瓣关闭不全","point":"与本类中 vhd_mr 的鉴别点：MR 为收缩期杂音、S1 减弱、左室扩大；MS 为舒张期杂音、开瓣音、左室不扩大。风湿性多瓣膜病变可并存，以反流定量与瓣口面积判断主病变。"},{"name":"左房黏液瘤","point":"舒张期隆隆样杂音随体位改变，可伴晕厥、栓塞；超声见左房内活动团块，瓣口正常。"},{"name":"Austin Flint 杂音","point":"重度主动脉瓣反流冲击二尖瓣前叶所致心尖舒张期杂音，无开瓣音、S1 正常；超声见前叶舒张期扑动。"},{"name":"三尖瓣狭窄","point":"杂音在三尖瓣区、吸气增强（Carvallo 征），伴颈静脉 a 波增高与肝大。"},{"name":"左房三房心","point":"早期肺淤血而二尖瓣口正常，超声见左房内隔膜。"}],"tx":{"drug":[{"name":"呋塞米","dose":"口服 20–40 mg qd 起，按水肿调整；急性肺水肿 20–40 mg 静推","note":"缓解淤血；MS 依赖前负荷，过量致心排骤降与低血压","renal":"eGFR 下降时加量，避免肾前性氮质血症","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加耳肾毒性"},{"name":"美托洛尔/比索洛尔","dose":"美托洛尔缓释片 23.75–47.5 mg qd 起，静息心率控至 60–80 次/分","note":"延长舒张充盈、降低跨瓣压差，合并房颤控率一线；急性肺水肿伴低血压时慎用","renal":"遵说明书","hepatic":"重度肝损减量","interact":"与维拉帕米/地尔硫䓬合用加重负性传导"},{"name":"地高辛","dose":"0.125–0.25 mg qd，老年或肾功能不全者 0.125 mg qd 或隔日","note":"用于伴心衰或快速房颤且 β 阻滞剂耐受不佳者；窦性心律无效","renal":"按 CrCl 调整，目标浓度 0.5–0.9 ng/mL","hepatic":"遵说明书","interact":"与胺碘酮、维拉帕米合用升高浓度易中毒"},{"name":"华法林","dose":"起始 2.5–3 mg qd，目标 INR 2.0–3.0","note":"风湿性 MS 合并房颤抗凝强推荐；重度 MS 窦性心律但左房 >50 mm 或见左房自发显影亦考虑","renal":"重肾损出血风险高，加密监测","hepatic":"肝损致 INR 波动需密切监测","interact":"与胺碘酮、复方新诺明合用增强抗凝"},{"name":"新型口服抗凝药","dose":"利伐沙班 20 mg qd（CrCl 15–49 mL/min 用 15 mg qd）","note":"中重度 MS 或机械瓣者不宜用 NOAC，以华法林为主","renal":"CrCl <15 mL/min 禁用","hepatic":"Child-Pugh B 级以上慎用","interact":"避免强 P-gp/CYP3A4 抑制剂或诱导剂"},{"name":"苄星青霉素（二级预防）","dose":"120 万 U 肌注每 4 周（<27 kg 用 60 万 U）","note":"确诊风湿性心脏病者长期预防，减少复发与进展","renal":"遵说明书","hepatic":"遵说明书","interact":"与丙磺舒合用延长半衰期"}],"nonDrug":["经皮球囊二尖瓣成形术（PBMV）：重度 MS 伴症状、Wilkins ≤8 分、无左房血栓、无中重度 MR；无症状但肺动脉收缩压 >50 mmHg 或负荷后压差显著升高亦考虑","外科分离/修复或置换：PBMV 禁忌或不宜者；机械瓣用于年轻、可耐受抗凝者，生物瓣用于高龄、抗凝禁忌或计划妊娠者","房颤：导管消融用于左房不过度扩大者；左心耳封堵或外科迷宫作为选择","妊娠期重度 MS 孕前评估并考虑 PBMV，孕期控率限液"],"life":["限盐 <5 g/d、避免剧烈运动与高原","每 6–12 个月复查超声（重者每 6 个月）","合并房颤长期抗凝并定期测 INR","育龄女性孕前咨询","仅人工瓣或既往心内膜炎者操作前预防 IE"]},"prog":"无症状重度 MS 5 年生存约 80%；出现明显症状而未干预 10 年生存约 50%–60%。PBMV 后 10 年约 60%–70% 免于再干预。房颤未抗凝者体循环栓塞年发生 2%–4%。","refs":["中国心脏瓣膜病介入治疗指南 2020","中华医学会心血管病学分会 二尖瓣狭窄诊治专家共识 2019","2021 ESC/EACTS 心脏瓣膜病管理指南","2020 ACC/AHA 心脏瓣膜病管理指南"]},{"id":"vhd_mr","name":"二尖瓣关闭不全","aka":["Mitral Regurgitation","MR","二尖瓣反流"],"rank":2,"basic":{"define":"收缩期二尖瓣不能完全闭合致血液反流入左房；按病程分急性与慢性，按机制分原发性（瓣叶/腱索/乳头肌）与继发性（左室重构致瓣环扩大、瓣叶牵拉）。","risk":["二尖瓣脱垂/腱索断裂、风湿热、感染性心内膜炎","冠心病乳头肌功能不全或断裂","扩张型/缺血性心肌病（继发性 MR）","老年退行性钙化、肥厚型心肌病伴 SAM"],"epi":"最常见的瓣膜病，超声检出率约 20%–25%，多为轻度；重度约 1%–2%。我国老年退行性与缺血性病因逐年增加。"},"patho":"急性 MR 时左房来不及扩张，左房压骤升、前向心排下降，表现为肺水肿伴低血压而左室不扩大。慢性 MR 经左房扩大缓冲压力，左室以偏心性重构维持每搏量，长期容量负荷致扩张与收缩功能下降；EF 可因后负荷降低而高估真实功能，故 EF ≤60% 或 LVESD ≥40 mm 提示失代偿。继发性 MR 的核心是左室重构致瓣环扩张与乳头肌移位。","dx":{"criteria":["心尖部全收缩期吹风样杂音向左腋下传导、S1 减弱；急性者杂音可短促甚至被肺水肿掩盖；重度慢性见心尖搏动左移、S3","超声定量：轻度 反流容积 <30 mL、EROA <0.20 cm²、反流分数 <30%；中度 30–60 mL、0.20–0.39 cm²、30%–49%；重度 ≥60 mL、≥0.40 cm²、≥50%","缩流颈宽度 ≥0.7 cm 或肺静脉收缩期逆向血流提示重度","慢性重度手术评估标志：LVEF ≤60%、LVESD ≥40 mm（≥45 mm 为高危）、LVEDD ≥70 mm","急性 MR：突发呼吸困难、肺水肿、低血压，常伴胸痛（乳头肌断裂）或发热（心内膜炎）"],"workup":["经胸超声：机制（脱垂/连枷/穿孔、瓣环、左室重构）、反流定量、LVEF 与 LVESD/LVEDD、左房大小、肺动脉压","经食管超声：修复或经导管钳夹（TEER）前精确评估瓣叶病变","心电图（左房增大、左室肥厚、房颤）、胸片（左房/左室增大）","负荷超声：症状与静息指标不符，重度 MR 运动时肺动脉压 >60 mmHg 提示预后不良","BNP、肌钙蛋白、血培养（急性）、冠脉造影（≥40 岁拟手术）"],"grading":"反流分级：轻 <30 mL、EROA <0.20 cm²；中 30–60 mL、0.20–0.39 cm²；重 ≥60 mL、≥0.40 cm²。慢性分期：代偿期（EF 正常、LVESD <40 mm）→过渡期（EF 55%–60%、LVESD 40–44 mm）→失代偿期（EF <55% 或 LVESD ≥45 mm 或有症状）。"},"ddx":[{"name":"二尖瓣狭窄","point":"与本类中 vhd_ms 的鉴别点：MS 为舒张期杂音伴开瓣音、S1 亢进、左室不扩大；MR 为收缩期杂音、左室扩大。"},{"name":"三尖瓣关闭不全","point":"杂音在胸骨左下缘、吸气增强，伴颈静脉 v 波与肝搏动。"},{"name":"室间隔缺损","point":"胸骨左缘第 3–4 肋间粗糙收缩期杂音伴震颤，超声见跨室间隔分流。"},{"name":"肥厚型梗阻性心肌病（SAM）","point":"杂音随前负荷下降（Valsalva、站立）增强，超声见 SAM 与流出道压差，MR 为继发。"},{"name":"主动脉瓣反流","point":"舒张期杂音、脉压增宽；Austin Flint 杂音易与 MS 混淆，超声可辨。"}],"tx":{"drug":[{"name":"呋塞米","dose":"口服 20–40 mg qd 起；急性肺水肿 20–40 mg 静推并加用血管扩张剂","note":"急性 MR 需同时降后负荷，避免心排骤降","renal":"eGFR 下降时加量，监测电解质","hepatic":"遵说明书","interact":"与非甾体抗炎药合用削弱利尿"},{"name":"硝酸甘油","dose":"舌下 0.5 mg 或静脉 5–10 μg/min 起，逐步滴定","note":"降低前/后负荷、减少反流容积；低血压时禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与西地那非等 PDE5 抑制剂合用致严重低血压，禁忌"},{"name":"硝普钠","dose":"0.3–0.5 μg/kg/min 静脉起，常用 0.5–5 μg/kg/min","note":"急性重度 MR 合并高血压时强效降后负荷，需动脉监测，SBP >90–100 mmHg 时用","renal":"肾损者警惕氰化物蓄积","hepatic":"遵说明书","interact":"与其他降压药合用致严重低血压"},{"name":"沙库巴曲缬沙坦","dose":"50 mg bid 起，每 2–4 周倍增，目标 200 mg bid","note":"继发性 MR 伴 HFrEF 改善重构与预后","renal":"eGFR <30 或高钾者慎用","hepatic":"Child-Pugh C 级禁用","interact":"与 ACEI 需间隔 36 h；与保钾药合用致高钾"},{"name":"华法林/NOAC（合并房颤）","dose":"华法林 INR 2.0–3.0；利伐沙班 20 mg qd（CrCl 15–49 mL/min 用 15 mg qd）","note":"CHA2DS2-VASc 男 ≥2/女 ≥3 推荐长期抗凝","renal":"NOAC 按 CrCl 调整","hepatic":"Child-Pugh B 级以上慎用 NOAC","interact":"华法林与抗菌药合用需加密监测"}],"nonDrug":["原发性慢性重度 MR 有症状，或无症状但 LVEF ≤60%（部分指南 ≤65%）或 LVESD ≥40 mm：二尖瓣修复优先于置换","无症状重度 MR：LVEF ≤60%、LVESD ≥40 mm 或 LVEDD ≥70 mm、肺动脉压 >50 mmHg 即手术；指标快速恶化者宜早手术","经导管二尖瓣钳夹（TEER）：外科高危或禁忌的原发性 MR（尤其瓣叶脱垂）及适当筛选的继发性 MR","急性重度 MR（腱索/乳头肌断裂、心内膜炎）：急诊手术，IABP/ECMO 过渡","继发性 MR 优先处理左室病因而非单纯修瓣"],"life":["限盐限液，重度者避免等长运动","轻中度每 2–3 年、重度每 6–12 个月复查超声","机械瓣终身抗凝、生物瓣术后短期抗凝","育龄女性孕前评估"]},"prog":"慢性原发性重度 MR 未手术者每年约 3%–5% 进展为左室功能不全，出现症状或 EF <60% 后 10 年生存约 50%。急性 MR 合并乳头肌断裂未手术者 24 h 内死亡率可达 50%。继发性 MR 远期死亡率与再住院率仍高。","refs":["中华医学会心血管病学分会 二尖瓣反流诊治专家共识 2019","中国心脏瓣膜病介入治疗指南 2020","2020 ACC/AHA 心脏瓣膜病管理指南","2021 ESC/EACTS 心脏瓣膜病管理指南"]},{"id":"vhd_as","name":"主动脉瓣狭窄","aka":["Aortic Stenosis","AS"],"rank":3,"basic":{"define":"瓣叶增厚、钙化或粘连使左室射血受阻，最常见为老年钙化性（合并或不合并二叶瓣），其次为风湿性与先天性二叶式主动脉瓣。","risk":["年龄 >65 岁、男性","二叶式主动脉瓣（发病提前 10–20 年）","高血压、血脂异常、糖尿病、代谢综合征","慢性肾病、高磷血症","风湿热"],"epi":"≥65 岁主动脉瓣钙化约 25%，>75 岁重度 AS 约 3.4%；二叶瓣患病率 1%–2%，是 60 岁前 AS 最主要原因。"},"patho":"进行性钙化与纤维化致固定性梗阻，左室向心性肥厚，室壁应力与耗氧上升而冠脉灌注受限（心绞痛）。肥厚左室顺应性下降，运动时外周血管扩张而心排不能相应增加（晕厥）。后期舒张功能不全、左房扩大与房颤加重淤血（心衰）。钙化性瓣膜病近似动脉粥样硬化样炎症过程，瓣口面积每年约减 0.05–0.1 cm²。","dx":{"criteria":["三联征：劳力性心绞痛、晕厥或先兆晕厥、劳力性呼吸困难/心衰；一旦出现即预后明显恶化","主动脉瓣区收缩期喷射性粗糙杂音向颈部传导、可伴震颤，A2 减弱；脉压小、细迟脉；心尖抬举样搏动","重度（至少 2 项）：最大流速 ≥4.0 m/s、平均压差 ≥40 mmHg、瓣口面积 ≤1.0 cm²","低流量低梯度：面积 ≤1.0 cm² 而压差 <40 mmHg、流速 <4.0 m/s，小剂量多巴酚丁胺负荷超声（流速或压差升 >20% 为假性重度）或 CT 钙化评分","无症状者运动试验出现症状或血压下降，提示早期干预"],"workup":["经胸超声：流速、平均压差、LVEF、左室质量、主动脉根部与升主动脉内径、合并病变","心电图（左室肥厚、传导阻滞）、胸片（主动脉结突出、瓣膜钙化）","冠脉造影或 CTA：≥40–50 岁拟 TAVR 前常规","CT：TAVR 术前根部、瓣环、入路与冠脉高度评估","多巴酚丁胺负荷超声（低 EF 低梯度）；NT-proBNP、肾功能、凝血与血型"],"grading":"轻度 流速 2.6–2.9 m/s、压差 <20 mmHg、面积 >1.5 cm²；中度 3.0–3.9 m/s、20–39 mmHg、1.0–1.5 cm²；重度 ≥4.0 m/s、≥40 mmHg、≤1.0 cm²（极重 ≥5.0 m/s）。"},"ddx":[{"name":"主动脉瓣反流","point":"与本类中 vhd_ar 的鉴别点：AR 舒张期叹气样杂音、脉压增宽；AS 收缩期杂音、脉压小。两者可并存，需以反流定量与瓣口面积取舍。"},{"name":"肥厚型梗阻性心肌病","point":"杂音在胸骨左缘、Valsalva 或站立增强、硝酸甘油加重；超声见非对称肥厚、SAM 与流出道压差，瓣膜正常。"},{"name":"主动脉瓣下隔膜","point":"杂音类似但位置更低、无瓣叶钙化，多普勒湍流起始于瓣下。"},{"name":"主动脉缩窄","point":"上肢高血压、下肢低血压、背部连续性杂音，CTA 见缩窄段与压差。"},{"name":"左室流出道梗阻/低心排心肌病","point":"疲劳呼吸困难而无喷射性杂音，瓣口面积正常。"}],"tx":{"drug":[{"name":"呋塞米","dose":"20–40 mg qd 口服起，按反应调整","note":"仅缓解淤血症状，不改变病程","renal":"eGFR 下降时加量，避免肾前性氮质血症","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"美托洛尔/比索洛尔","dose":"美托洛尔缓释片 23.75–47.5 mg qd 起","note":"合并房颤控率或合并心衰/冠心病；重度 AS 心排依赖者谨慎滴定","renal":"遵说明书","hepatic":"重度肝损减量","interact":"与地尔硫䓬/维拉帕米合用加重低血压"},{"name":"沙库巴曲缬沙坦（合并心衰）","dose":"50 mg bid 起，倍增滴定，目标 200 mg bid","note":"AS 合并 HFrEF 可考虑，需监测血压","renal":"eGFR <30 或高钾者慎用","hepatic":"Child-Pugh C 级禁用","interact":"与 ACEI 间隔 36 h；与保钾药合用致高钾"},{"name":"华法林/NOAC（合并房颤）","dose":"华法林 INR 2.0–3.0；TAVR 术后按出血风险评估","note":"合并房颤栓塞风险高","renal":"NOAC 按 CrCl 调整","hepatic":"Child-Pugh B 级以上慎用 NOAC","interact":"与胺碘酮合用需加密监测"},{"name":"他汀类","dose":"阿托伐他汀 20–40 mg qn（按 ASCVD 指征）","note":"对 AS 进展无确切延缓作用，仅按 ASCVD 预防使用","renal":"监测肌酸激酶","hepatic":"活动性肝病禁用","interact":"与克拉霉素、维拉帕米合用增加肌病风险"}],"nonDrug":["SAVR：症状性重度 AS；无症状但 LVEF <50%、运动试验阳性、流速 ≥5.0 m/s 或快速进展；年龄较轻（通常 <65 岁）、STS 低危、解剖合适者首选","TAVR：高龄（≥75–80 岁）、手术高危或禁忌（STS ≥8%）、解剖合适者首选；中低危在特定条件由心脏团队评估","球囊成形仅作血流动力学不稳或需非心脏手术的桥接及姑息","合并重 CAD：SAVR 同期 CABG，TAVR 者按需 PCI","二叶瓣需评估根部：升主动脉 ≥50 mm 或年增 ≥5 mm 同期置换"],"life":["重度者避免剧烈运动与等长用力","重/中度/轻度分别每 6–12 个月、1–2 年、2–3 年复查超声","术后机械瓣终身抗凝；TAVR 后抗血小板按出血与房颤情况","人工瓣者操作前预防 IE"]},"prog":"无症状重度 AS 出现症状后平均生存 2–5 年，猝死年风险约 1%。SAVR 后 10 年生存约 65%–70%，高危 TAVR 5 年生存约 40%–50%。","refs":["中华医学会心血管病学分会 主动脉瓣狭窄经导管治疗专家共识 2021","中国心脏瓣膜病介入治疗指南 2020","2021 ESC/EACTS 心脏瓣膜病管理指南","2020 ACC/AHA 心脏瓣膜病管理指南"]},{"id":"vhd_ar","name":"主动脉瓣关闭不全","aka":["Aortic Regurgitation","AR","主动脉瓣反流"],"rank":4,"basic":{"define":"舒张期主动脉瓣不能完全闭合致血液反流入左室；分急性与慢性，按部位分瓣叶病变（心内膜炎、二叶瓣、风湿、脱垂）与根部/升主动脉病变（夹层、扩张、马凡）。","risk":["主动脉夹层、根部扩张或动脉瘤","感染性心内膜炎","二叶式主动脉瓣、风湿性心脏病","马凡等结缔组织病","强直性脊柱炎、大动脉炎、创伤"],"epi":"超声检出率约 4%–10%，重度约 0.5%，男性多于女性。我国以老年退行性与二叶瓣为主，中青年需警惕夹层与遗传性主动脉病。"},"patho":"慢性 AR 左室承受容量与压力双重负荷，经离心性肥厚与扩大维持每搏量，可在 EF 正常时长期代偿；一旦收缩末期应力过高，收缩功能转为不可逆下降。脉压增宽致冠脉舒张灌注减少（心绞痛）。急性 AR 时血液反流入未扩张左室使舒张末压骤升、二尖瓣提前关闭，表现为肺水肿与低心排，可无典型杂音。","dx":{"criteria":["胸骨左缘第 2–3 肋间舒张期叹气样递减型杂音（前倾坐位、呼气末最清），可伴 Austin Flint 杂音；脉压增宽、水冲脉、股动脉枪击音、点头征","重度超声指标（至少 1 项）：反流束宽度/流出道宽度 ≥65%、近端反流束宽 ≥6 mm、反流容积 ≥60 mL、EROA ≥0.30 cm²、反流分数 ≥50%、降主动脉全舒张期逆向血流","慢性重度干预标志：LVEF ≤50%（部分 ≤55%）、LVESD >50 mm 或 LVEDD >65 mm，或症状","急性 AR：突发肺水肿、低血压、胸痛（夹层）或发热（心内膜炎），需紧急 TEE 而非等待经胸超声","主动脉根部/升主动脉 ≥50 mm（二叶瓣 ≥55 mm）或年增 ≥5 mm 需手术评估；脉压 >60–70 mmHg 提示重度"],"workup":["经胸超声：反流定量、LVEF、LVESD/LVEDD、主动脉内径、二尖瓣提前关闭与前叶舒张期扑动","经食管超声：疑夹层、心内膜炎或经胸条件不佳","心电图（左室肥厚劳损）、胸片（心影靴形、根部突出）","主动脉 CTA：夹层或根部扩张","冠脉造影/CTA（拟手术）、负荷超声、NT-proBNP"],"grading":"轻度 反流束宽 <25%、容积 <30 mL、EROA <0.10 cm²；中度 <65%、30–59 mL、0.10–0.29 cm²；重度 ≥65%、≥60 mL、≥0.30 cm²。分期：Ⅰ 无症状伴重度但过度负荷证据少；Ⅱ 无症状但 LVESD >50 mm；Ⅲ 无症状但 EF ≤50%；Ⅳ 有症状。"},"ddx":[{"name":"主动脉瓣狭窄","point":"与本类中 vhd_as 的鉴别点：AS 收缩期喷射性杂音、脉压小；AR 舒张期叹气样杂音、脉压增宽。"},{"name":"Graham Steell 杂音（肺动脉瓣反流）","point":"杂音位置相近但吸气增强、伴肺动脉高压与右室扩大，无脉压增宽。"},{"name":"二尖瓣狭窄","point":"Austin Flint 杂音与 MS 均为心尖舒张期杂音，但 AR 无开瓣音、伴脉压增宽，超声见前叶扑动。"},{"name":"冠状动脉瘘","point":"连续性杂音，彩色多普勒见异常分流通道，脉压增宽不明显。"},{"name":"主动脉夹层","point":"撕裂样胸背痛 + 突发 AR、双侧血压差，CT 见真假腔，属外科急症。"}],"tx":{"drug":[{"name":"硝普钠（急性 AR）","dose":"0.3–0.5 μg/kg/min 静脉起，滴定至血压允许范围，需动脉监测","note":"同时降低后负荷并适度减慢心率；夹层时目标心率 <60 次/分、SBP 100–120 mmHg","renal":"肾损监测氰化物蓄积","hepatic":"遵说明书","interact":"与其他血管扩张剂合用致严重低血压"},{"name":"美托洛尔（夹层控率降压）","dose":"静推 5 mg 起，每 5–15 min 可重复至心率 <60 次/分，随后口服维持","note":"单纯严重 AR 失代偿时不宜单独使用（延长舒张期反流）","renal":"遵说明书","hepatic":"重度肝损减量","interact":"与硝普钠联用注意低血压"},{"name":"尼卡地平","dose":"5 mg/h 静脉起，5–15 min 可加 2.5 mg/h","note":"β 阻滞剂禁忌时用于夹层血压控制","renal":"遵说明书","hepatic":"肝损减量","interact":"与强 CYP3A4 抑制剂合用升高浓度"},{"name":"ACEI/ARB（有争议）","dose":"依那普利 5–10 mg bid 或缬沙坦 80 mg qd 起，滴定至耐受剂量","note":"无症状重度 AR 不伴高血压时不建议常规以此延缓手术；合并高血压或心衰时使用","renal":"双侧肾动脉狭窄或高钾禁用","hepatic":"遵说明书","interact":"与保钾利尿剂合用致高钾"},{"name":"呋塞米","dose":"20–40 mg 静推，按反应 1–2 h 重复","note":"缓解肺淤血，须同时降后负荷","renal":"eGFR 下降时加量","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加耳肾毒性"},{"name":"抗菌药物（心内膜炎）","dose":"经验性万古霉素 + 头孢曲松，按血培养调整，疗程 4–6 周","note":"血培养 3 套后启动；伴心衰、脓肿或持续感染应早期手术","renal":"按 CrCl 调整万古霉素并监测 AUC","hepatic":"遵说明书","interact":"与哌拉西林他唑巴坦合用增加肾损伤"}],"nonDrug":["急性重度 AR（夹层、心内膜炎、创伤）伴血流动力学不稳：外科急症；Stanford A 型夹层立即行主动脉置换 + 瓣膜修复或置换","慢性重度 AR 手术：有症状，或无症但 LVEF ≤50%（部分 ≤55%）、LVESD >50 mm（>45 mm 高危）、LVEDD >65 mm；或同期 CABG/升主动脉手术","升主动脉置换：二叶瓣 ≥55 mm、非二叶瓣 ≥55–60 mm 或年增 ≥5 mm、马凡 ≥50 mm 或有危险因素","瓣膜修复优先于置换，年轻者可考虑 Ross 手术","TAVR 对单纯 AR 应用受限，仅外科高危且解剖合适者"],"life":["重度者避免等长与竞技运动，主动脉扩张者禁举重与对抗性运动","轻/中重度分别每 1–2 年、6–12 个月复查超声并监测主动脉内径","控制血压","人工瓣者操作前预防 IE","马凡等定期影像随访，可考虑 β 阻滞剂/ARB"]},"prog":"无症状重度 AR 且 EF 正常者年进展至手术约 4%–5%；出现症状或 EF <50% 未手术者年死亡率 10%–25%。术后 10 年生存约 65%–75%。急性 AR 合并夹层或心内膜炎未手术者死亡率极高。","refs":["中华医学会心血管病学分会 主动脉瓣反流诊治专家共识 2021","中国主动脉夹层诊治指南 2022","2021 ESC/EACTS 心脏瓣膜病管理指南","2020 ACC/AHA 心脏瓣膜病管理指南"]},{"id":"vhd_tv","name":"三尖瓣与肺动脉瓣疾病","aka":["Tricuspid and Pulmonary Valve Disease","三尖瓣反流","肺动脉瓣狭窄"],"rank":5,"basic":{"define":"含三尖瓣反流（以左心衰继发的功能性为主）、三尖瓣狭窄（风湿性）、肺动脉瓣狭窄（多为先天性或法洛四联症术后）与肺动脉瓣反流（术后残余）。","risk":["左心瓣膜病、左心衰晚期、肺动脉高压、房颤（瓣环扩大）","起搏器/ICD 导线跨瓣","右房扩大","风湿热（三尖瓣狭窄）","先天性肺动脉瓣狭窄、TOF 术后"],"epi":"功能性 TR 最常见，中重度 TR 在一般人群约 1%–2%，左心瓣膜术后仍可达 20%–30%；孤立性三尖瓣狭窄罕见。"},"patho":"功能性 TR 源于右室扩大、瓣环扩张与乳头肌移位致对合不良，本质是右室重构，继发于左心衰、肺高压或房颤；右室容量负荷进一步扩大右房与瓣环形成恶性循环，出现肝大、腹水、水肿与心排下降。三尖瓣狭窄使右房压升高、右室充盈受限。肺动脉瓣狭窄阻碍右室射血致右室压显著升高，长期右心衰；肺动脉瓣反流致右室扩张与运动耐量下降。","dx":{"criteria":["TR：胸骨左下缘或剑突下收缩期杂音、吸气增强（Carvallo 征），颈静脉 v 波与肝搏动、肝大、腹水、下肢水肿，常伴房颤","重度 TR 定量：缩流颈 ≥0.7 cm、PISA 半径 ≥0.9 cm、反流容积 ≥45 mL、EROA ≥0.40 cm²、肝静脉双相或全收缩期逆向血流","三尖瓣狭窄：舒张期隆隆样杂音吸气增强、颈静脉 a 波增高；平均跨瓣压差 ≥5 mmHg 为重度","肺动脉瓣狭窄：胸骨左缘第 2 肋间收缩期喷射性杂音伴喀喇音、P2 减弱；峰值流速 轻 2.5–3.0 m/s、中 3.0–4.0 m/s、重 >4.0 m/s（导管压差 >40 mmHg）","TOF 术后：肺动脉瓣反流分数 ≥40% 或右室舒张末期容积指数 ≥160 mL/m² 为干预参考"],"workup":["经胸超声：TR 定量与机制（瓣环径、右室大小与功能、右室收缩压）、三尖瓣压差、肺动脉瓣形态与压差","右心导管：肺高压评估、肺动脉瓣跨瓣压差测量","心电图（右室肥厚、右房扩大、房颤、导线）、胸片（右房/右室增大）","肝功能与腹水评估（淤血性肝病）、肾功能与电解质","心脏 MRI：右室容积与功能（术后随访首选）"],"grading":"TR：轻度各项重度指标均不满足；中度介于其间；重度 EROA ≥0.40 cm²、容积 ≥45 mL、缩流颈 ≥0.7 cm。肺动脉瓣狭窄：轻 2.5–3.0 m/s、中 3.0–4.0 m/s、重 >4.0 m/s。TOF 术后 PR：RVEDVi ≥160 mL/m² 或 PR 分数 ≥40%。"},"ddx":[{"name":"二尖瓣关闭不全","point":"与本类中 vhd_mr 的鉴别点：MR 杂音在心尖、向腋下传导，伴左室扩大与肺淤血；TR 杂音在胸骨左下缘、吸气增强，伴颈静脉 v 波。"},{"name":"致心律失常性右室心肌病","point":"右室扩大与 TR 显著而左心正常，影像见右室局部运动异常与纤维脂肪替代。"},{"name":"淤血性肝硬化","point":"右心衰性肝病以颈静脉压升高、肝颈静脉回流阳性为特征，可先心后肝。"},{"name":"房间隔缺损","point":"右心扩大伴 TR，杂音在胸骨左缘第 2 肋间，超声见房水平分流。"},{"name":"肺动脉瓣下漏斗部狭窄","point":"杂音位置相近但压差位于瓣下，需导管或超声定位。"}],"tx":{"drug":[{"name":"托拉塞米/呋塞米","dose":"托拉塞米 10–20 mg qd 或呋塞米 20–40 mg qd 起","note":"减轻右心淤血，避免过度容量收缩致心排下降","renal":"eGFR 下降时加量，监测肌酐与血钾","hepatic":"肝硬化腹水者避免过快利尿","interact":"与地高辛合用增加低钾性心律失常"},{"name":"螺内酯","dose":"20 mg qd 起，可增至 40 mg qd","note":"用于右心衰与腹水，协同利尿、减少低钾","renal":"eGFR <30 或血钾 >5.0 mmol/L 禁用","hepatic":"肝硬化者需监测","interact":"与 ACEI/ARB/ARNI 合用高钾叠加"},{"name":"西地那非","dose":"20 mg tid（确证肺动脉高压且有适应证时）","note":"左心来源肺高压不宜常规使用，先优化左心治疗","renal":"重度肾损减量","hepatic":"遵说明书","interact":"与硝酸酯类同用禁忌"},{"name":"波生坦","dose":"62.5 mg bid ×4 周后 125 mg bid","note":"仅用于 PAH 或相关适应证，需每月查肝功","renal":"遵说明书","hepatic":"肝损者禁用或减量","interact":"CYP3A4 抑制剂升高浓度，与华法林合用需监测"},{"name":"地高辛","dose":"0.125–0.25 mg qd（老年/肾损减量）","note":"合并房颤控率或右心衰","renal":"按 CrCl 调整并监测浓度","hepatic":"遵说明书","interact":"与胺碘酮/维拉帕米合用升高浓度"},{"name":"苄星青霉素（二级预防）","dose":"120 万 U 肌注每 4 周（<27 kg 用 60 万 U）","note":"风湿性三尖瓣病变者长期预防","renal":"遵说明书","hepatic":"遵说明书","interact":"与丙磺舒合用延长半衰期"}],"nonDrug":["左心瓣膜手术同期三尖瓣干预：重度 TR 且瓣环 >40 mm，或轻中度 TR 伴瓣环扩大/既往右心衰","孤立性三尖瓣手术：有症状重度 TR，或右室扩大/功能下降进展、瓣环显著扩大（>40–45 mm）；修复（瓣环成形）优先，无法修复时置换","继发性 TR 不宜在左心病变未处理时单独置换（术后低心排风险高）","经导管三尖瓣缘对缘修复或异位瓣环成形：外科高危重度 TR","起搏器相关 TR：调整或拔除导线后评估，必要时同期修复","肺动脉瓣狭窄重度（导管压差 >40 mmHg）或有症状：经皮球囊肺动脉瓣成形术；瓣下/漏斗狭窄多为外科","TOF 术后 PR 达干预阈值或有症状/心律失常：经导管肺动脉瓣置换","房颤伴 TR：早期节律控制可延缓右室扩大"],"life":["限盐 <5 g/d，记录体重；腹水者限液","每 6–12 个月复查超声（重度每 6 个月）","避免大量饮酒与肺部感染","机械瓣三尖瓣术后 INR 2.5–3.0（血栓风险高）"]},"prog":"中重度功能性 TR 未干预者年死亡率约 10%，孤立性重度 TR 5 年生存约 50%；术后残余 TR 与右室功能障碍常见。肺动脉瓣狭窄球囊成形后 10 年免于再干预 >90%。","refs":["中华医学会心血管病学分会 三尖瓣反流专家共识 2021","中国心脏瓣膜病介入治疗指南 2020","2021 ESC/EACTS 心脏瓣膜病管理指南","2020 ACC/AHA 心脏瓣膜病管理指南"]},{"id":"vhd_rheumatic","name":"风湿热与风湿性心脏病","aka":["Acute Rheumatic Fever","Rheumatic Heart Disease","RHD"],"rank":6,"basic":{"define":"A 组链球菌咽炎后的免疫介导多系统炎症（风湿热），累及心内膜、心肌与心包；反复发作致瓣膜纤维化变形形成风湿性心脏病。","risk":["5–15 岁儿童，链球菌性咽炎未充分抗生素治疗","拥挤居住、卫生与医疗条件差地区","家族易感性（HLA 相关）","未坚持青霉素二级预防"],"epi":"全球风湿热年新发约 47 万例，RHD 现患约 4000 万例，年死亡约 30 万。我国发病率显著下降，但西南、西北农村与少数民族地区仍可见。"},"patho":"链球菌 M 蛋白等与心肌、瓣膜（尤其二尖瓣、主动脉瓣）抗原交叉反应（分子模拟），引发自身抗体与 T 细胞介导损伤（Aschoff 小体）。急性期瓣膜水肿、沿闭合线细小赘生物；愈合后瓣叶纤维化、交界融合、腱索短缩致狭窄与关闭不全。病变随复发累积，控制复发是防止进展的关键。","dx":{"criteria":["Jones 标准：有链球菌感染证据（咽拭子或快速抗原阳性、ASO/抗 DNA 酶 B 升高）时，2 项主要表现或 1 主要 + 2 次要即可诊断","主要表现：心脏炎（新发杂音、超声瓣膜炎、心包炎）、多关节炎（游走性大关节）、舞蹈症、边缘性红斑、皮下结节","次要表现：发热、关节痛、ESR 或 CRP 升高、PR 间期延长","超声「亚临床心脏炎」：病理性二尖瓣反流有助于早期诊断","活动性判断：持续发热、关节症状、ESR >60 mm/h 或 CRP 持续升高、炎症指标回复延迟、超声瓣膜炎进展；ASO/抗 DNA 酶 B 仅提示近期感染，不反映活动性"],"workup":["咽拭子培养/快速抗原；ASO 与抗 DNA 酶 B（双抗体提高敏感性）","ESR、CRP、血常规、白蛋白","心电图：PR 间期延长、心动过速、心肌炎改变","超声心动图：瓣膜反流/狭窄、瓣叶增厚、心包积液、LVEF","心脏 MRI（疑心肌炎）；胸片、必要时关节影像"],"grading":"Jones 标准：主要表现 5 项、次要表现 4 项。发作类型：初次、复发、亚临床（仅超声瓣膜炎）。心脏炎严重度：轻（无症状）、中（心衰或心脏增大）、重（药物难控心衰）。"},"ddx":[{"name":"二尖瓣狭窄","point":"与本类中 vhd_ms 的鉴别点：MS 为风湿热慢性后遗症，ESR/CRP 正常、无链球菌感染证据；若炎症指标升高伴杂音加重，按活动性风湿热处理。"},{"name":"感染性心内膜炎","point":"血培养阳性、超声见较大活动性赘生物，风湿热赘生物细小沿闭合线；两者可并存。"},{"name":"幼年特发性关节炎","point":"对称性小关节、病程 >6 周、ANA/RF 阳性，无链球菌证据、心脏炎少见。"},{"name":"红斑狼疮（Libman-Sacks）","point":"多系统损害、ANA/抗 dsDNA 阳性，赘生物位于瓣叶两面。"},{"name":"病毒性心肌炎","point":"病毒前驱史、肌钙蛋白升高、MRI 水肿，无瓣膜炎与链球菌证据。"}],"tx":{"drug":[{"name":"青霉素 V（清除链球菌）","dose":"500 mg bid 或 250 mg qid 口服 ×10 天；不能口服者苄星青霉素 60 万–120 万 U 单次肌注","note":"无论咽拭子是否阳性均完成 10 天疗程（一期预防）","renal":"重度肾损调整间隔","hepatic":"遵说明书","interact":"与华法林合用致 INR 波动"},{"name":"苄星青霉素（二级预防）","dose":"≥27 kg：120 万 U 肌注每 4 周（高发区或儿童可每 3 周）；<27 kg：60 万 U 每 4 周","note":"疗程：心脏炎伴残留瓣膜病变 10 年或至 40 岁；无心脏炎 5 年或至 21 岁；心脏炎完全恢复 10 年或至 21 岁；注射前备肾上腺素","renal":"遵说明书","hepatic":"遵说明书","interact":"与丙磺舒合用延长半衰期"},{"name":"磺胺嘧啶（青霉素过敏替代）","dose":">27 kg 500 mg qd；<27 kg 250 mg qd","note":"过敏者用；红霉素 250 mg bid 为另一选择","renal":"重度肾损慎用","hepatic":"肝功能不全慎用","interact":"与华法林合用增强抗凝"},{"name":"阿司匹林（抗炎）","dose":"儿童 80–100 mg/kg/d 分 4 次，2–4 周后减量；成人 4–8 g/d 分次","note":"用于无心脏炎的关节炎；心脏炎者不单用","renal":"eGFR <30 慎用","hepatic":"活动性肝病禁用","interact":"与布洛芬合用降低抗血小板作用"},{"name":"泼尼松（中重度心脏炎）","dose":"1–2 mg/kg/d（最大 80 mg/d），2–4 周后减量，减量期宜 >12 周以防反跳","note":"严重心脏炎首选；轻度可先用阿司匹林，1 周无效改激素","renal":"监测血糖与电解质","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"呋塞米（心脏炎合并心衰）","dose":"20–40 mg 口服或静推，按需调整","note":"联合限盐、卧床；严重者考虑激素冲击","renal":"监测肾功能与电解质","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加肾毒性"}],"nonDrug":["卧床：无心脏炎 1–2 周；心脏炎无心衰 2–4 周；合并心衰 4–6 周以上，直至活动指标恢复","急性期合并心衰或重度瓣膜病变按心衰流程处理，炎症与病情稳定后择期行球囊成形或瓣膜手术","合并房颤者华法林抗凝并评估左房血栓","一期预防：规范治疗链球菌性咽炎、学校与社区筛查及卫生改善","妊娠期 RHD 由心脏团队评估，风湿性 MS 需心衰与抗凝多学科管理","建立 RHD 登记随访以提高注射依从性"],"life":["坚持苄星青霉素注射，漏注是复发与进展主因","急性期每 1–2 周、稳定期每 6–12 个月复查炎症指标与超声","改善住房拥挤与口腔皮肤卫生","育龄女性孕前咨询"]},"prog":"规范二级预防者复发率由年 20%–30% 降至 <5%。RHD 中约 40%–60% 最终需瓣膜干预；坚持预防可显著延缓病变进展。预后取决于就诊时瓣膜损害程度与预防依从性。","refs":["中华医学会儿科学分会心血管学组 风湿热诊断与防治指南 2019","2020 AHA 风湿热诊断与治疗科学声明","WHO 风湿热与风湿性心脏病二级预防推荐","中国心脏瓣膜病介入治疗指南 2020"]}]},{"id":"cardiomyopathy","name":"心肌疾病","rank":7,"summary":"按表型（扩张/肥厚/限制/右室心律失常型）+ 病因双重分类，影像立表型、遗传与病原找病因；治疗围绕心衰四联、梗阻与心律失常管理、猝死风险分层（ICD/CRT）。","compare":[{"diseaseId":"cm_dcm","dx":"LVEDD >5.0 cm（女）/5.5 cm（男）且 LVEF <45%，心室扩大、室壁变薄","key":"收缩功能下降为中心，四联药物为基石"},{"diseaseId":"cm_hcm","dx":"任一段 ≥15 mm（家族史者 ≥13 mm）且无其他致肥厚原因；LVOT 压差 ≥30 mmHg 为梗阻型","key":"以梗阻与猝死分层为核心，需限运动"},{"diseaseId":"cm_rcm","dx":"双房扩大、心室腔不扩大，E/A >2、DT <150 ms，BNP 显著升高","key":"须与缩窄性心包炎鉴别，后者可手术治愈"},{"diseaseId":"cm_arvc","dx":"2010 任务标准：2 主要，或 1 主要 +2 次要，或 4 次要","key":"右室起源 LBBB 型室速，运动加速进展"},{"diseaseId":"cm_myocarditis","dx":"前驱感染后心衰/胸痛/心律失常，肌钙蛋白升高，CMR 符合 Lake Louise","key":"急性期慎用正性肌力药，暴发需机械支持"},{"diseaseId":"cm_peripartum","dx":"妊娠最后 1 个月至产后 5 个月内新发心力衰竭、LVEF <45%，且无其他可解释病因；酒精性者需长期大量饮酒史（通常 >80 g/d 持续 5 年以上）","key":"围生期心肌病与妊娠时间窗强绑定，酒精性心肌病戒酒后 LVEF 可明显回升；两者冠脉均正常"}],"diseases":[{"id":"cm_dcm","name":"扩张型心肌病","aka":["DCM","Dilated Cardiomyopathy"],"rank":1,"basic":{"define":"以左室或双室扩大伴收缩功能下降（LVEF <45%）、不能归因于冠心病、负荷异常或已知心肌病的原发性心肌疾病。","risk":["家族遗传（TTN、LMNA、MYH7，占 20%–40%）","病毒性心肌炎后","长期大量饮酒、蒽环类化疗、抗精神病药","甲亢、围生期、自身免疫病","男性、中青年发病"],"epi":"我国患病率约 19/10 万，居心衰病因第三位；家族性占 20%–40%，5 年生存 50%–70%。"},"patho":"心肌细胞变性坏死并被纤维瘢痕替代，双室扩大、室壁变薄、收缩无力；神经内分泌过度激活与心室重构恶性循环，继发房颤、传导阻滞与室性心律失常。","dx":{"criteria":["男 LVEDD >5.5 cm、女 >5.0 cm（或 >3.2 cm/m²）伴室壁变薄","LVEF <45%，排除冠心病、瓣膜病、高血压心脏","多呈慢性心衰病程（>3 个月），非急性心肌坏死","家族史或致病基因阳性支持诊断","须同时具备心室扩大与收缩功能下降"],"workup":["超声：心腔径、LVEF、室壁、腔内血栓、瓣膜反流","CMR：组织特征，鉴别缺血与心肌炎","冠脉 CTA/造影排除缺血性心肌病","BNP、肌钙蛋白、甲功、肾功能电解质、铁代谢","动态心电图（室早负荷、NSVT）","基因检测（<50 岁或家族史阳性）"],"grading":"LVEF：轻 40%–45%、中 30%–39%、重 <30%；分期 ACC/AHA A–D；NYHA I–IV；病因分原发性与继发性。"},"ddx":[{"name":"肥厚型心肌病（cm_hcm）","point":"与本类 cm_hcm 鉴别：DCM 心室扩大、室壁薄、收缩下降；HCM 室壁 ≥15 mm，扩张期需结合既往影像。"},{"name":"限制型心肌病（cm_rcm）","point":"与本类 cm_rcm 鉴别：RCM 心室腔不扩大、双房扩大、舒张受限；DCM 心腔显著扩大。"},{"name":"致心律失常性右室心肌病（cm_arvc）","point":"与本类 cm_arvc 鉴别：ARVC 以右室扩大、V1–V3 T 波倒置与 LBBB 型室速为主，左室收缩功能常保留。"},{"name":"缺血性心肌病","point":"有心梗史或冠脉多支病变，延迟强化按冠脉供血区域分布。"},{"name":"高血压性心脏病晚期","point":"长期重度高血压、向心性肥厚，血压控制后部分可逆。"},{"name":"酒精性/围生期心肌病（cm_peripartum）","point":"以饮酒史或妊娠末月至产后 5 个月起病，去除诱因后恢复率较高。"}],"tx":{"drug":[{"name":"沙库巴曲缬沙坦（ARNI）","dose":"50–100 mg bid 起始，每 2–4 周倍增至目标 200 mg bid","note":"HFrEF 首选；换药前停 ACEI ≥36 h","renal":"eGFR <30 慎用并测血钾","hepatic":"重度肝损慎用","interact":"禁与 ACEI 合用；与保钾药合用致高钾"},{"name":"依那普利","dose":"2.5 mg bid 起始，渐增至 10 mg bid（目标 10–20 mg/d）","note":"不耐受 ARNI 时用","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"禁与 ARNI 联用"},{"name":"比索洛尔","dose":"1.25 mg qd 起始，每 2 周倍增，目标 10 mg qd","note":"容量稳定后起始，滴定至最大耐受量","renal":"无需调整","hepatic":"重度肝损减量","interact":"与维拉帕米/地尔硫䓬致传导阻滞"},{"name":"螺内酯","dose":"20 mg qd 起始（可 25–50 mg/d）；依普利酮 25 mg qd 起始至 50 mg","note":"LVEF ≤35%、NYHA II–IV；血钾 >5.0 或 eGFR <30 禁用","renal":"eGFR <30 禁用，30–49 减量","hepatic":"中度肝损慎用","interact":"与 ACEI/ARNI、钾剂合用致高钾"},{"name":"达格列净","dose":"达格列净 10 mg qd（或恩格列净 10 mg qd）","note":"LVEF 下降或保留型心衰均获益","renal":"eGFR ≥20 可用，透析不推荐","hepatic":"重度肝损慎用","interact":"与利尿剂叠加注意容量"},{"name":"呋塞米","dose":"20–40 mg qd 起始，按出入量调整；顽固水肿可静脉 40–80 mg","note":"有淤血才用，目标干体重","renal":"eGFR 低者加量","hepatic":"注意低钾低钠","interact":"与地高辛、氨基糖苷类增毒"},{"name":"伊伐布雷定","dose":"2.5–5 mg bid 起始，渐增至 7.5 mg bid，心率目标 55–60 次/分","note":"窦性心律、心率 ≥77 次/分且 β 阻滞剂已足量","renal":"eGFR <15 慎用","hepatic":"重度肝损禁用","interact":"强 CYP3A4 抑制剂致心动过缓"},{"name":"维利西呱","dose":"2.5 mg qd 起始，每 2 周倍增至 10 mg qd","note":"近期心衰恶化且病情稳定者","renal":"eGFR <15 慎用","hepatic":"重度肝损不推荐","interact":"禁与 PDE5 抑制剂合用（低血压）"},{"name":"地高辛","dose":"0.125 mg qd（老年或肾功不全隔日）","note":"房颤快室率或症状性低心排，不改善生存","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"胺碘酮、维拉帕米升高血药浓度"},{"name":"利伐沙班（房颤/左室血栓）","dose":"20 mg qd（CrCl 15–49 用 15 mg qd）或华法林 INR 2.0–3.0","note":"左室血栓抗凝 3–6 个月后复查","renal":"按 CrCl 调整","hepatic":"Child-Pugh C 禁用","interact":"见房颤篇"}],"nonDrug":["ICD 一级预防：LVEF ≤35%、NYHA II–III、优化药物 ≥3 个月仍低；二级为骤停存活或持续性室速","CRT：QRS ≥150 ms 且 LBBB、LVEF ≤35%（I 类）；130–149 ms 个体化","导管消融：血流动力学不稳定室速、频发室早","LVAD 桥接或目的治疗；终末期心脏移植","LMNA 等基因阳性者尽早评估 ICD"],"life":["限钠 <5 g/d，按容量限液","完全戒酒，避免 NSAIDs 与噻唑烷二酮","流感与肺炎疫苗","每 3–6 个月复查超声、BNP、肾功能；每日称重","家属学习 CPR 与 AED"]},"prog":"规范四联使 HFrEF 年死亡率降至约 10% 以下；20%–30% 患者 LVEF 可回升但不可停药；LMNA 等人群猝死风险高。","refs":["《中国扩张型心肌病诊断和治疗指南》2018","《中国心力衰竭诊断和治疗指南》2024","2023 ESC Guidelines for the management of cardiomyopathies"]},{"id":"cm_hcm","name":"肥厚型心肌病","aka":["HCM","Hypertrophic Cardiomyopathy","IHSS"],"rank":2,"basic":{"define":"心肌节段性肥厚（任一段舒张末 ≥15 mm，家族史者 ≥13 mm）且不能由负荷异常或系统疾病解释的原发性心肌病；静息或激发后 LVOT 压差 ≥30 mmHg 为梗阻型。","risk":["肌节基因突变（MYBPC3、MYH7），常染色体显性","青年猝死家族史、晕厥史","室间隔 ≥30 mm、NSVT","扩张期（LVEF <50%）","房颤与左房扩大"],"epi":"成人患病率约 1:500，我国估计患者超 100 万但诊断率低；为青年运动性猝死首要原因之一。"},"patho":"肌节蛋白突变致心肌排列紊乱、纤维化与肥厚；室间隔增厚造成 LVOT 动力性梗阻（SAM 加重），舒张顺应性下降致充盈压升高与左房扩大；室腔小、氧耗增、微血管稀疏形成缺血与心律失常基质。","dx":{"criteria":["超声/CMR 任一段 ≥15 mm（家族史者 ≥13 mm），排除高血压、瓣膜狭窄、淀粉样变、Fabry","梗阻型：静息或激发（Valsalva、运动）LVOT 压差 ≥30 mmHg","心尖肥厚型：心尖段 ≥15 mm、室间隔正常，常有巨大倒置 T 波","静息无梗阻而症状不相称者需运动负荷超声或导管激发","青少年以体表面积 z 值判断"],"workup":["静息 + Valsalva 激发超声：厚度、压差、SAM、二尖瓣反流、左房容积","CMR：心尖受累、延迟强化（>15% 左室质量提示高危）","24–48 h 动态心电图","运动负荷试验：症状与血压反应","三代家系筛查与基因检测","老年增厚伴低电压者查焦磷酸盐显像与轻链"],"grading":"静息梗阻/潜在梗阻/非梗阻；部位：基底段、心室中部、心尖；猝死风险低/中/高。"},"ddx":[{"name":"扩张型心肌病（cm_dcm）","point":"与本类 cm_dcm 鉴别：HCM 室壁厚、室腔小；DCM 心室扩大、室壁薄、LVEF <45%。"},{"name":"限制型心肌病（cm_rcm）","point":"与本类 cm_rcm 鉴别：RCM 无节段肥厚与梗阻，以双房扩大、限制性充盈为特征。"},{"name":"致心律失常性右室心肌病（cm_arvc）","point":"与本类 cm_arvc 鉴别：ARVC 无室壁肥厚与 LVOT 梗阻，以右室扩大与室性心律失常为主。"},{"name":"高血压性心脏病","point":"长期高血压、向心性肥厚多 <15 mm，血压控制后可部分逆转。"},{"name":"心脏淀粉样变","point":"低电压与室壁增厚不匹配，均匀颗粒状增厚，焦磷酸盐显像阳性。"},{"name":"主动脉瓣狭窄","point":"喷射性杂音向颈部传导且 Valsalva 减弱；HCM 杂音 Valsalva 增强、蹲位减弱。"}],"tx":{"drug":[{"name":"美托洛尔","dose":"25–50 mg bid 或缓释 47.5–95 mg qd，可至最大耐受量；静息心率 <60–65 次/分","note":"有症状 HCM 一线，改善舒张充盈与梗阻","renal":"无需调整","hepatic":"重度肝损减量","interact":"与维拉帕米合用致心动过缓"},{"name":"维拉帕米","dose":"40–80 mg tid（缓释 120–240 mg qd），最大 480 mg/d","note":"β 阻滞剂不耐受时用；压差 ≥50 mmHg 伴低血压慎用","renal":"肾功能不全减量","hepatic":"肝硬化减量","interact":"与 β 阻滞剂合用致严重心动过缓"},{"name":"丙吡胺","dose":"100–150 mg tid 起始，可至 200 mg qid","note":"梗阻型二线辅助，监测 QT 与排尿","renal":"CrCl <40 减量/禁用","hepatic":"遵说明书","interact":"与其他 QT 延长药致尖端扭转"},{"name":"玛伐凯泰（Mavacamten）","dose":"5 mg qd 起始（遵说明书可 2.5 mg），按 LVEF 滴定至 15 mg qd","note":"梗阻性 HCM 肌球蛋白抑制剂；每 4 周查 LVEF，<50% 减量或停药","renal":"重度慎用","hepatic":"中重度禁用","interact":"维拉帕米、地尔硫䓬需减量；强 CYP3A4 抑制剂禁用"},{"name":"氢氯噻嗪","dose":"12.5–25 mg qd（或呋塞米 20 mg qd）","note":"仅晚期容量过负荷，过度利尿加重梗阻","renal":"监测肾功能","hepatic":"注意低钾","interact":"与地高辛合用注意血钾"},{"name":"胺碘酮","dose":"维持 100–200 mg qd","note":"合并房颤节律控制；长期查甲功与肺","renal":"无需调整","hepatic":"监测肝功","interact":"与华法林、地高辛相互作用"},{"name":"利伐沙班（房颤）","dose":"20 mg qd 或华法林 INR 2.0–3.0","note":"HCM 合并房颤均需抗凝","renal":"按 CrCl 调整","hepatic":"Child-Pugh C 禁用","interact":"见房颤篇"}],"nonDrug":["室间隔减容：难治症状（NYHA III–IV）且压差 ≥50 mmHg；外科心肌切除为金标准","酒精室间隔消融：手术高危或解剖不宜（起搏器 5%–10%）","ICD：二级为室颤/持续性室速；一级见危险因素（≥30 mm、家族猝死、不明晕厥、LVEF <50%、延迟强化 >15%）","终末期按 HFrEF 治疗、CRT/移植评估"],"life":["避免竞技与骤发剧烈运动、脱水","避免血管扩张剂、过量利尿与正性肌力药","戒烟限酒","一级亲属（含儿童）超声 1–2 年随访","家庭学习 CPR/AED"]},"prog":"总体年死亡率约 1%，猝死年发生 0.5%–1%；5%–10% 进入扩张期；室间隔减压术后 5 年生存 >90%。","refs":["《中国肥厚型心肌病诊断和治疗指南》2022","2024 AHA/ACC Hypertrophic Cardiomyopathy Guideline","2023 ESC Guidelines for the management of cardiomyopathies"]},{"id":"cm_rcm","name":"限制型心肌病","aka":["RCM","Restrictive Cardiomyopathy"],"rank":3,"basic":{"define":"心室壁僵硬度增加、舒张充盈受限、心室腔不大而收缩功能相对保留的心肌病；可为特发性或继发于淀粉样变、结节病、放化疗、血色病等。","risk":["心脏淀粉样变（AL 或 ATTR）","纵隔放疗、蒽环类、骨髓移植后","结节病、硬皮病、嗜酸粒细胞增多症","血色病、糖原贮积病、Fabry 病","肌节/中间丝基因突变（DES 等）"],"epi":"约占心肌病 5%；老年 HFpEF 人群淀粉样变可达 8%–13%，我国 ATTR 早期诊断率低。"},"patho":"间质纤维化、异常蛋白/铁/糖原沉积使室壁僵硬，舒张压迅速上升、心房显著扩张；心排量依赖心率，容量耐受差，出现双心衰、房颤与心源性栓塞。","dx":{"criteria":["双房扩大（常 >40 mm）而双室容量不大，室壁正常或轻度增厚","限制性充盈：E/A >2.0、DT <150 ms、e' <8 cm/s、E/e' 升高","二尖瓣血流随呼吸变异 <15%","BNP 显著升高，可伴低电压或假性梗死 Q 波","心内膜心肌活检见纤维化/淀粉样沉积（金标准）"],"workup":["超声：双房大小、应变保留心尖（提示淀粉样变）","CMR：心内膜下环形强化，ECV >40% 提示高危","血清/尿蛋白电泳 + 游离轻链（AL 筛查）","焦磷酸盐显像（ATTR）与 TTR 基因测序","结节病筛查、放化疗史、嗜酸粒细胞","必要时心内膜心肌活检"],"grading":"病因原发性/继发性；淀粉样变 AL/ATTR；舒张功能 Nagueh I–III 级；按 NYHA 评估。"},"ddx":[{"name":"肥厚型心肌病（cm_hcm）","point":"与本类 cm_hcm 鉴别：HCM 节段肥厚、有梗阻；RCM 室壁多不厚、无梗阻，双房扩大突出。"},{"name":"扩张型心肌病（cm_dcm）","point":"与本类 cm_dcm 鉴别：DCM 心室扩大、LVEF <45%；RCM 心腔不扩大、LVEF 多正常。"},{"name":"缩窄性心包炎（pc_constrictive）","point":"与 pericardium_chd 大类 pc_constrictive 鉴别：缩窄有心包增厚钙化、室间隔弹跳、E 随吸气下降 >25%、舒张压平台相等；RCM 呼吸变异 <15%、BNP 更高。"},{"name":"致心律失常性右室心肌病（cm_arvc）","point":"与本类 cm_arvc 鉴别：ARVC 以右室扩大与室速为主，室腔不呈双房扩张的限制型充盈。"},{"name":"老年 HFpEF","point":"无全身疾病线索，双房扩大不显著，CMR 无环形强化。"},{"name":"心包积液伴压塞（pc_effusion）","point":"大量积液、奇脉，穿刺后即刻缓解；RCM 无积液。"}],"tx":{"drug":[{"name":"呋塞米","dose":"20 mg qd 起始按体重滴定；螺内酯 20–25 mg qd","note":"改善淤血，过量致低血压与低心排","renal":"eGFR <30 慎用螺内酯","hepatic":"注意血钾","interact":"与 ACEI/ARB 合用致高钾"},{"name":"维拉帕米","dose":"40–80 mg tid（或美托洛尔 25–50 mg bid）","note":"延长充盈时间，静息心率 60–70 次/分","renal":"肾功能不全减量","hepatic":"肝硬化减量","interact":"与 β 阻滞剂合用致心动过缓"},{"name":"依那普利","dose":"2.5–5 mg bid 起始缓慢加量","note":"RCM 血压偏低，易低血压与肾损","renal":"监测肌酐","hepatic":"遵说明书","interact":"与保钾药合用致高钾"},{"name":"氯苯唑酸（Tafamidis）","dose":"61 mg qd（或 20 mg 葡甲胺盐，遵说明书）","note":"ATTR 心肌病延缓功能下降","renal":"重度肾损慎用","hepatic":"重度肝损慎用","interact":"升高 BCRP 底物（瑞舒伐他汀等）浓度"},{"name":"AL 淀粉样变化疗","dose":"按血液科方案（如达雷妥尤单抗 + CyBorD）","note":"AL 型需抗浆细胞治疗","renal":"按肾功能调整","hepatic":"按肝功能调整","interact":"遵血液科方案"},{"name":"华法林（房颤）","dose":"INR 2.0–3.0，或按 CrCl 选 DOAC","note":"淀粉样变血栓与出血风险均高，需个体化","renal":"按 CrCl 选药","hepatic":"Child-Pugh C 禁用","interact":"见房颤篇"},{"name":"地高辛（慎用）","dose":"0.125 mg qd，仅房颤室率控制","note":"淀粉样变敏感易中毒","renal":"减量","hepatic":"遵说明书","interact":"胺碘酮、维拉帕米升高浓度"}],"nonDrug":["病因治疗：AL 型自体移植/化疗；ATTR 稳定剂；血色病放血与铁螯合；Fabry 酶替代","心脏移植：特发性/家族性终末期主要选择","房颤节律控制（消融成功率低但可改善症状）","CRT 获益有限；ICD 仅持续性室速/室颤者","血液、肾、神经、遗传多学科管理"],"life":["低盐、限液与体重管理","避免血管扩张剂与容量骤变","免疫抑制者疫苗与感染预防","ATTR 与家族性家系筛查","定期复查 NT-proBNP、肌钙蛋白、超声"]},"prog":"特发性 5 年生存 60%–70%；AL 未治疗中位生存 <1 年，现代治疗可至 3–5 年；ATTR 中位生存 3–5 年。","refs":["《中国限制型心肌病诊治专家共识》2020","《心脏淀粉样变诊治中国专家共识》2022","2023 ESC Guidelines for the management of cardiomyopathies"]},{"id":"cm_arvc","name":"致心律失常性右室心肌病","aka":["ARVC","ARVD/C","Arrhythmogenic Cardiomyopathy"],"rank":4,"basic":{"define":"右室（部分左室）心肌被脂肪-纤维组织替代、伴右室扩大与功能减低、易发右室起源室速/室颤的遗传性心肌病。","risk":["桥粒基因突变（PKP2、DSP、DSG2、DSC2、JUP），约 50% 有突变","年轻男性、高强度竞技运动","长期耐力运动、右心负荷增加","家族猝死史"],"epi":"患病率约 1:2000–1:5000；年轻运动员猝死中占 10%–20%。"},"patho":"桥粒蛋白缺陷使心肌对机械应力耐受下降，右室游离壁被脂肪/纤维替代，形成折返环路（LBBB 形态、下壁电轴室速），可进展为室颤；DSP 突变左室受累更明显。","dx":{"criteria":["2010 任务标准 6 类，需 2 主要，或 1 主要 +2 次要，或 4 次要","结构/功能：RVEF ≤40% 或 RVEDV/BSA ≥113 mL/m²（男）/≥89（女）为主要","复极：V1–V3 T 波倒置为主要（≥14 岁、无 RBBB）；V1–V2 倒置为次要","除极：epsilon 波为主要；V1–V2 终末激动时间 ≥55 ms 为次要","心律失常：LBBB 形态室速（电轴 -90°~+120°）为主要；>500 室早/24 h 为次要","家族史或致病突变为主要/次要标准"],"workup":["超声：右室径、RVEDV/BSA、RVEF、游离壁运动","CMR：右室容积/RVEF 金标准、室壁变薄与强化","12 导联 + V1–V3 放大找 epsilon 波","24 h Holter 与事件记录器","监护下运动试验","基因检测与三代家系筛查"],"grading":"确诊/边缘/可能；心脏骤停风险分高（持续性室速、晕厥、心衰）、中（青年男性、竞技运动）、低。"},"ddx":[{"name":"扩张型心肌病（cm_dcm）","point":"与本类 cm_dcm 鉴别：DCM 左室扩大与 LVEF <45% 为主；ARVC 右室扩大主导，V1–V3 T 波倒置与 LBBB 型室速。"},{"name":"肥厚型心肌病（cm_hcm）","point":"与本类 cm_hcm 鉴别：HCM 室壁增厚、无右室扩大，室速多为多形性。"},{"name":"限制型心肌病（cm_rcm）","point":"与本类 cm_rcm 鉴别：RCM 心室腔不扩大而双房扩大，呈限制性充盈，无右室游离壁脂肪替代。"},{"name":"RVOT 特发性室速","point":"室速形态相似但心脏结构正常、无 T 波倒置与家族史。"},{"name":"心脏结节病","point":"CMR 斑片透壁强化、肺门淋巴结与 PET 高代谢，活检为非干酪样肉芽肿。"},{"name":"Brugada 综合征","point":"V1–V2 穹隆型 ST 抬高 ≥2 mm，心脏结构正常，夜间晕厥/室颤首发。"}],"tx":{"drug":[{"name":"美托洛尔","dose":"缓释 47.5–95 mg qd（或比索洛尔 2.5–5 mg qd），可至最大耐受量","note":"抑制运动诱发室性心律失常","renal":"无需调整","hepatic":"重度肝损减量","interact":"与维拉帕米合用致心动过缓"},{"name":"索他洛尔","dose":"80 mg bid 起始至 160 mg bid，起始测 QTc","note":"β 阻滞剂基础上抑制室速；QTc >500 ms 禁用","renal":"CrCl 40–60 减量，<40 避免","hepatic":"遵说明书","interact":"与其他 QT 延长药致尖端扭转"},{"name":"胺碘酮","dose":"负荷 200 mg tid × 1–2 周，维持 200 mg qd","note":"控制室速复发与减少 ICD 放电","renal":"无需调整","hepatic":"监测肝功","interact":"升高华法林、地高辛浓度"},{"name":"氟卡尼（难治）","dose":"50–100 mg bid 起始（须在 β 阻滞剂或胺碘酮背景下）","note":"仅无左心结构病变、有经验中心使用","renal":"肾功能不全减量","hepatic":"重度肝损减量","interact":"与其他抗心律失常药合成传导抑制"},{"name":"呋塞米（右心衰）","dose":"20–40 mg qd，必要时加螺内酯 20 mg qd","note":"右心衰以利尿为主，慎用血管扩张剂","renal":"监测肾功能","hepatic":"注意血钾","interact":"与地高辛相互作用"}],"nonDrug":["运动限制：确诊或突变携带者避免竞技与高强度耐力运动","ICD：持续性室速/室颤/骤停后；高危特征（右室显著扩大、LVEF ≤35%、多基因突变）一级预防","导管消融：反复放电或难治室速的辅助，常需重复","终末期心衰或难治室颤行移植评估","基因阳性亲属筛查"],"life":["严格限制竞技运动","避免能量饮料、发热与脱水","一级亲属心电图、超声/CMR 与基因检测","ICD 患者每 3–6 个月随访，备家庭 AED","妊娠多学科评估"]},"prog":"确诊者年猝死约 1%（高危 5%–10%）；DSP 突变左室受累型进展更快。","refs":["《中国致心律失常性右室心肌病诊断和治疗专家共识》2019","2010 Revised Task Force Criteria（Eur Heart J 2010）","2019 HRS Expert Consensus on Arrhythmogenic Cardiomyopathy"]},{"id":"cm_myocarditis","name":"心肌炎","aka":["Myocarditis","暴发性心肌炎","Fulminant Myocarditis"],"rank":5,"basic":{"define":"由感染（多为病毒）、自身免疫或药物毒性引起的心肌局灶或弥漫性炎症损伤，表现为胸痛、心律失常、心衰或心源性休克；血流动力学崩溃者为暴发性心肌炎。","risk":["病毒感染前驱（柯萨奇、流感、腺病毒、细小病毒 B19、新冠）","青壮年与儿童，暴发性多见青壮年","自身免疫病、免疫检查点抑制剂","可卡因等兴奋剂、部分药物","剧烈运动与应激"],"epi":"发病率 1–10/10 万/年；暴发性占急性心肌炎约 10%，未及时机械支持者院内死亡率 50%–70%。"},"patho":"病毒直接损伤并触发细胞免疫与细胞因子风暴，心肌坏死与水肿；暴发性者迅速弥漫性收缩无力、休克与恶性心律失常，晚期纤维化可演变为扩张型心肌病。","dx":{"criteria":["前驱感染后胸痛、心悸、气促，或年轻人不明原因心衰/休克/心律失常","肌钙蛋白与 BNP/NT-proBNP 升高","心电图非特异 ST-T 改变、房室阻滞、室性心律失常","CMR（Lake Louise 标准）≥1 项：水肿（T2/STIR 或 T2 mapping）、非缺血性延迟强化、T1 或 ECV 升高","超声见节段运动异常而冠脉正常、室壁增厚（水肿）、心包积液","确诊：心内膜活检见浸润 + 心肌坏死"],"workup":["心电监护、心肌酶、BNP、CRP、ESR、肝肾、凝血、乳酸","病毒 PCR/血清学、自身抗体、免疫治疗史","超声动态评估 LVEF 与积液","冠脉造影/CTA 排除心梗","稳定后 1–2 周 CMR","疑似巨细胞型或拟免疫抑制前活检"],"grading":"病程急性/慢性；病理分淋巴细胞性、巨细胞性、嗜酸粒细胞性；病情轻中度与暴发性（需机械支持）。"},"ddx":[{"name":"扩张型心肌病（cm_dcm）","point":"与本类 cm_dcm 鉴别：DCM 慢性、心室扩大明确而无急性炎症；心肌炎急性起病、前驱感染、CMR 水肿与强化。"},{"name":"肥厚型心肌病（cm_hcm）","point":"与本类 cm_hcm 鉴别：HCM 有明确室壁肥厚与梗阻，无急性炎症性水肿信号。"},{"name":"急性冠脉综合征","point":"有冠脉病变且延迟强化按冠脉分布；心肌炎多年轻、非缺血格式。"},{"name":"急性心包炎（pc_acute）","point":"与 pericardium_chd 大类 pc_acute 鉴别：心包炎以胸膜性胸痛、摩擦音、广泛 ST 凹面抬高为主，肌钙蛋白仅轻度升高。"},{"name":"Takotsubo 心肌病","point":"强应激诱因、室壁异常超出单支冠脉分布，数周恢复。"},{"name":"脓毒症心肌病","point":"有感染灶与休克，心肌抑制随脓毒症控制改善。"}],"tx":{"drug":[{"name":"呋塞米（稳定期）","dose":"按需 20–40 mg qd；稳定后按 HFrEF 四联滴定","note":"仅血流动力学稳定时用","renal":"监测肾功能","hepatic":"遵说明书","interact":"见 cm_dcm"},{"name":"美托洛尔（稳定后）","dose":"12.5–25 mg bid 起始缓慢加量","note":"急性不稳定期禁用","renal":"无需调整","hepatic":"减量","interact":"与维拉帕米合用致心动过缓"},{"name":"布洛芬（伴心包炎短期）","dose":"400–600 mg tid，≤1 周","note":"NSAIDs 可加重心肌损伤，仅伴心包炎且 EF 正常时用","renal":"eGFR <30 避免","hepatic":"慎用","interact":"与抗凝合用增加出血"},{"name":"秋水仙碱（伴心包炎）","dose":"0.5 mg bid（体重 <70 kg 或肾功不全 0.5 mg qd），3–6 个月","note":"降低心包炎复发","renal":"eGFR <35 减量，<15 禁用","hepatic":"减量","interact":"强 CYP3A4/P-gp 抑制剂增毒；与他汀致肌病"},{"name":"免疫抑制（严格适应证）","dose":"巨细胞型：甲泼尼龙 1 g/d × 3 天后泼尼松 1 mg/kg 递减 + 环孢素 A","note":"仅活检证实巨细胞/嗜酸粒细胞性或自身免疫相关；病毒性不推荐","renal":"环孢素按浓度与肾功调","hepatic":"监测肝功","interact":"与秋水仙碱合用肌病风险"},{"name":"奥司他韦（流感）","dose":"75 mg bid × 5 天","note":"仅明确病原时使用","renal":"按药调整","hepatic":"按药调整","interact":"遵说明书"},{"name":"去甲肾上腺素","dose":"0.05–0.5 µg/kg/min（可加多巴酚丁胺 2–5 µg/kg/min）","note":"大剂量儿茶酚胺加重室性心律失常，优先机械支持","renal":"监测尿量","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗"},{"name":"胺碘酮（抗心律失常）","dose":"负荷 150 mg 静推后 1 mg/min 泵入","note":"先纠正钾 ≥4.0 mmol/L 与镁","renal":"无需调整","hepatic":"监测肝功","interact":"与其他 QT 延长药合用风险"}],"nonDrug":["机械循环支持：休克、乳酸升高与灌注不足时尽早 IABP、Impella 或 VA-ECMO（EF 多在 5–10 天恢复）","临时起搏：高度房室阻滞或慢室率依赖","室速/室颤电复律，镇静与气道保护","活检指导靶向治疗（疑巨细胞型、MCS 置入前）","MCS 依赖 4–6 周无恢复者评估 LVAD/移植","转入有 ECMO 与心衰团队的中心"],"life":["急性期卧床，限制体力活动 3–6 个月；运动员评估后恢复训练","戒烟酒，避免兴奋剂","流感与新冠疫苗","出院后 3、6、12 个月复查超声/CMR 与心电图","稳定后按 HFrEF 四联长期随访"]},"prog":"轻中度多在 2–4 周恢复，10%–20% 演变为扩张型心肌病；暴发性经 ECMO 支持 1 年生存 60%–80%，复发约 10%。","refs":["《成人急性心肌炎诊断与治疗中国专家共识》2021","《暴发性心肌炎诊断与治疗中国专家共识》2017","2020 Lake Louise Criteria（JACC 2018 更新）"]},{"id":"cm_peripartum","name":"围生期心肌病与酒精性心肌病","aka":["PPCM","Peripartum Cardiomyopathy","ACM","Alcoholic Cardiomyopathy"],"rank":6,"basic":{"define":"围生期：妊娠末月至产后 5 个月内、既往无心肌病者出现 LVEF <45% 的收缩性心衰且无其他病因；酒精性：长期大量饮酒（男 >80 g/d、女 >40 g/d，≥10 年）所致左室扩大、收缩功能减低的非缺血性心肌病。","risk":["围生期：多胎、高龄（>30 岁）、多产、双胎、子痫前期","围生期：产后起病（约 70%）、长期保胎","酒精性：长期高量饮酒、营养不良（硫胺素缺乏）、男性","酒精性：合并肝硬化、吸烟","两者均可叠加高血压/贫血/感染"],"epi":"围生期心肌病约 1/3000–1/1500 妊娠；酒精性心肌病占非缺血性心肌病 10%–15%，男女约 3:1。"},"patho":"围生期：16 kDa 催乳素片段介导微血管损伤与氧化应激，叠加妊娠晚期容量增加与免疫激活；酒精：乙醛与氧化应激直接损伤心肌、干扰蛋白合成与钙处理，致收缩无力与间质纤维化。","dx":{"criteria":["围生期：① 妊娠末月至产后 5 个月内起病；② 既往无心肌病且无其他病因；③ LVEF <45% 或缩短分数下降","围生期：BNP 升高与肺淤血提示病理，需与生理性水肿、心率增快鉴别","酒精性：大量饮酒史，LVEDD >5.0 cm（女）/5.5 cm（男），LVEF <40%，排除其他病因","酒精性：戒酒 6 个月后部分恢复，需长期随访","两者均需冠脉评估排除缺血"],"workup":["超声：LVEF、LVEDD、右室、心包积液、腔内血栓","BNP（妊娠期基线偏高，动态更有意义）、肌钙蛋白","心电图与 Holter","CMR（产后可做）","冠脉 CTA/造影","铁代谢、甲功、AUDIT-C、硫胺素","围生期查血压、尿蛋白、sFlt-1/PlGF 与产科情况"],"grading":"围生期按 NYHA 与 LVEF 分层（<30% 重症需评估 MCS/ICD）；酒精性分戒酒后恢复型与不可逆型。"},"ddx":[{"name":"扩张型心肌病（cm_dcm）","point":"与本类 cm_dcm 鉴别：DCM 无妊娠时间窗或饮酒史、慢性进展；围生期心肌病限于特定时间窗，酒精性需大量饮酒史且部分可逆。"},{"name":"肥厚型心肌病（cm_hcm）","point":"与本类 cm_hcm 鉴别：HCM 为室壁肥厚与梗阻、LVEF 多保留，与本类扩张性表型不同。"},{"name":"妊娠高血压/子痫前期心衰","point":"血压显著升高、蛋白尿、多脏器受累，多为舒张功能不全，降压后改善。"},{"name":"心肌炎（cm_myocarditis）","point":"与本类 cm_myocarditis 鉴别：心肌炎有前驱感染、肌钙蛋白明显升高与 CMR 炎症表现。"},{"name":"甲亢性心脏病","point":"FT3/FT4 升高、TSH 降低、高动力循环，抗甲亢后恢复。"},{"name":"硫胺素缺乏性心脏病","point":"营养不良、高输出量、周围神经病变，补硫胺素后迅速改善。"}],"tx":{"drug":[{"name":"呋塞米","dose":"20–40 mg qd 按尿量滴定（围生期哺乳期可用）","note":"避免过量致胎盘/肾灌注不足","renal":"监测肾功能","hepatic":"注意低钾","interact":"与地高辛、氨基糖苷类增毒"},{"name":"卡维地洛","dose":"3.125 mg bid 起始，每 2 周倍增至 25 mg bid","note":"围生期可用（哺乳安全）；稳定后起始","renal":"eGFR <30 慎用","hepatic":"重度肝损禁用","interact":"与维拉帕米联用抑制传导"},{"name":"依那普利","dose":"2.5 mg bid 起始渐增至 10 mg bid","note":"围生期妊娠及哺乳禁用，停乳后可用","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"禁与 ARNI 合用"},{"name":"沙库巴曲缬沙坦（酒精性）","dose":"50–100 mg bid 起始至 200 mg bid","note":"围生期哺乳期禁用；酒精性 LVEF <40% 可用","renal":"eGFR <30 慎用","hepatic":"重度肝损慎用","interact":"禁与 ACEI 合用"},{"name":"螺内酯","dose":"20–25 mg qd","note":"围生期产后可考虑；酒精性 LVEF ≤35% 加用","renal":"eGFR <30 禁用","hepatic":"慎用","interact":"与 ACEI/ARNI 合用高钾"},{"name":"溴隐亭（围生期）","dose":"2.5 mg qd 起始，可至 2.5 mg bid，联用抗凝 ≥2 周，8 周内","note":"证据有争议，仍以标准抗心衰为主；不哺乳","renal":"肾功能不全慎用","hepatic":"肝功不全慎用","interact":"大剂量与降压药增加心血管事件"},{"name":"硫胺素（酒精性）","dose":"100 mg iv/im qd × 3–7 天，后 100 mg po qd","note":"常规补充，防 Wernicke 脑病","renal":"无需调整","hepatic":"遵说明书","interact":"无重大相互作用"},{"name":"依诺肝素（围生期 LVEF <30% 或血栓）","dose":"1 mg/kg q12h；产后可换华法林或 DOAC","note":"围生期高凝且华法林致畸","renal":"按 CrCl 调整","hepatic":"慎用","interact":"见房颤篇"}],"nonDrug":["围生期：重度心衰多学科评估提前终止妊娠","围生期：LVEF ≤35% 持续 3–6 个月考虑 ICD/CRT；休克行 ECMO/MCS","酒精性：强制戒酒为核心，LVEF ≤35% 持续者考虑 ICD","两者按 HFrEF 长期用药，6 个月复查超声再评估","房颤、左室血栓与终末期移植评估"],"life":["围生期：再次妊娠前需 LVEF ≥50%，复发风险 20%–30%","围生期哺乳用药：β 阻滞剂、利尿剂可用；ACEI/ARB、ARNI 禁用","酒精性：彻底戒酒并加入戒酒支持计划","酒精性：高蛋白营养与 B 族维生素","两者：低盐、控血压、疫苗、定期复查 BNP 与超声"]},"prog":"围生期 6 个月内 50%–70% 恢复 LVEF ≥50%；酒精性戒酒者 5 年生存 80%–90%，继续饮酒者 <50%，多在戒酒 6–12 个月改善。","refs":["《围生期心肌病诊治中国专家共识》2020","《中国心力衰竭诊断和治疗指南》2024","2019 ESC Position Statement on Peripartum Cardiomyopathy"]}]},{"id":"pericardium_chd","name":"心包与先天性心脏病","rank":8,"summary":"心包疾病按炎症-积液-缩窄三步判断，NSAIDs 加秋水仙碱为基础，压塞即刻穿刺；先心病以左向右分流为核心，评估 Qp/Qs、肺血管阻力与封堵适应证，艾森曼格禁关闭。","compare":[{"diseaseId":"chd_asd","dx":"胸骨左缘 2–3 肋间柔和收缩期杂音 + S2 固定分裂，超声见房水平分流","key":"成人最常见先心病，封堵受肺阻力限制"},{"diseaseId":"chd_vsd","dx":"胸骨左缘 3–4 肋间全收缩期杂音伴震颤，超声见室水平分流","key":"小缺损可自愈，中大型须在肺高压前关闭"},{"diseaseId":"chd_pda","dx":"左第 2 肋间连续性机器样杂音 + 脉压增宽 + 水冲脉","key":"早产儿可药物关闭，成人以介入封堵为主"},{"diseaseId":"pc_acute","dx":"胸膜性胸痛 + 摩擦音 + 广泛 ST 凹面抬高/PR 压低 + 新发积液，4 项中 ≥2 项","key":"NSAIDs + 秋水仙碱，警惕压塞"},{"diseaseId":"pc_effusion","dx":"呼吸困难、颈静脉怒张、心音低钝，超声见积液；压塞 Beck 三联征 + 奇脉 ≥10 mmHg","key":"血流动力学不稳立即穿刺"},{"diseaseId":"pc_constrictive","dx":"右心衰 + 心包增厚/钙化 + 室间隔弹跳 + 二尖瓣 E 随吸气下降 >25%","key":"剥脱术可治愈，须与限制型心肌病鉴别"}],"diseases":[{"id":"chd_asd","name":"房间隔缺损","aka":["ASD","Atrial Septal Defect","继发孔型房间隔缺损"],"rank":1,"basic":{"define":"房间隔发育吸收过多或融合不全所致缺损，分继发孔型（最常见）、原发孔型、静脉窦型与冠状静脉窦型；血流以左房向右房分流为主。","risk":["遗传综合征（唐氏、Holt-Oram、Noonan）","母孕期风疹、酗酒与致畸药物","家族性先心病史","早产","女性多见"],"epi":"最常见成人先心病，活产婴儿约 1.6/1000，占先心病 10%–15%，女男约 2:1。"},"patho":"左房压高于右房，长期左向右分流使肺血流增加、右房右室扩大与肺动脉压升高；重度肺血管病变可致分流逆转（艾森曼格），出现发绀与右心衰。","dx":{"criteria":["胸骨左缘 2–3 肋间柔和收缩期杂音、第 2 心音固定分裂、三尖瓣区舒张期杂音","超声见房间隔中断与过隔血流、右心扩大，可估 Qp/Qs；经食管确认边缘","心电图：不完全性右束支阻滞（V1 rSr'）、电轴右偏","胸片：右心扩大、肺血增多、肺动脉段突出","导管：Qp/Qs ≥1.5 提示分流显著，评估 PVR"],"workup":["经胸 + 经食管超声（类型、边缘长度、肺静脉异位引流）","心电图与动态心电图","右心导管：Qp/Qs、PAP、PVR","成人心超与主动脉根部评估","综合征者遗传咨询"],"grading":"解剖：继发孔型、原发孔型、静脉窦型；分流小（<1.5）/中（1.5–2.0）/大（>2.0）；肺血管病变可逆/临界/艾森曼格。"},"ddx":[{"name":"室间隔缺损（chd_vsd）","point":"与本类 chd_vsd 鉴别：VSD 杂音在胸骨左缘 3–4 肋间伴震颤，S2 不固定分裂，超声见室水平分流。"},{"name":"动脉导管未闭（chd_pda）","point":"与本类 chd_pda 鉴别：PDA 为连续性杂音伴脉压增宽；ASD 无脉压改变而有 S2 固定分裂。"},{"name":"部分性肺静脉异位引流","point":"右室扩大与 Qp/Qs 增大相似，需追踪肺静脉汇入，常合并静脉窦型 ASD。"},{"name":"三尖瓣反流","point":"胸骨下端杂音随吸气增强，超声见反流束，房间隔完整。"},{"name":"肺动脉高压右室扩大","point":"无过隔分流，有慢阻肺/肺栓塞史。"},{"name":"肺动脉瓣狭窄","point":"P2 减弱、杂音向背部传导，超声见瓣膜狭窄，无房水平分流。"}],"tx":{"drug":[{"name":"呋塞米（右心衰）","dose":"20–40 mg qd 按需","note":"右心衰淤血时用，不宜长期大剂量","renal":"监测肾功能","hepatic":"注意低钾","interact":"见心衰篇"},{"name":"波生坦（艾森曼格）","dose":"62.5 mg bid × 4 周后 125 mg bid；可联合西地那非 20 mg tid","note":"仅导管证实毛细血管前肺高压且关闭禁忌者","renal":"遵说明书","hepatic":"监测肝酶，Child-Pugh B/C 禁用","interact":"诱导 CYP3A4，降华法林与避孕药浓度"},{"name":"利伐沙班（房颤）","dose":"20 mg qd（CrCl 15–49 用 15 mg qd）","note":"艾森曼格抗凝需谨慎（咯血、出血）","renal":"按 CrCl 调整","hepatic":"Child-Pugh C 禁用","interact":"见房颤篇"},{"name":"胺碘酮（房扑/房颤）","dose":"维持 200 mg qd","note":"成人未关闭者房扑/房颤常见","renal":"无需调整","hepatic":"监测肝功","interact":"与华法林、地高辛相互作用"},{"name":"心内膜炎预防","dose":"阿莫西林 2 g 术前 30–60 min 单次","note":"封堵器/补片术后 6 个月内为高危","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["介入封堵：继发孔型、边缘距腔静脉/冠状静脉窦/房室瓣 ≥5 mm、多 ≤36 mm，Qp/Qs ≥1.5 或右心扩大","外科修补：原发孔型、静脉窦型、缺损过大或合并肺静脉异位引流","关闭指征：Qp/Qs ≥1.5 伴右心扩大、PAP <收缩压 2/3、PVR <2/3 循环阻力；成人无症状亦建议关闭","最佳时机学龄前 3–5 岁","艾森曼格禁关闭，按 PAH 管理并避免妊娠"],"life":["每 1–3 年超声随访，监测肺高压","术后 6 个月内避免竞技运动","艾森曼格：避免高海拔、脱水、剧烈运动，严禁妊娠","高危者侵入性操作前预防心内膜炎","一级亲属筛查"]},"prog":"未干预者 30 岁后渐现右心衰、房颤与肺高压；及时关闭者 30 年生存近正常；艾森曼格靶向治疗下中位生存 40–50 岁。","refs":["《中国先天性心脏病诊断与治疗指南》2020","2020 ESC Guidelines for the management of adult congenital heart disease","《房间隔缺损介入封堵治疗中国专家共识》2017"]},{"id":"chd_vsd","name":"室间隔缺损","aka":["VSD","Ventricular Septal Defect"],"rank":2,"basic":{"define":"胚胎期室间隔发育不全所致左、右室间异常通道，为最常见先天性心脏畸形；按位置分膜周部、肌部、双动脉下（干下）型。","risk":["遗传综合征（唐氏、DiGeorge 22q11、Noonan）","母孕期风疹与致畸药物","家族性先心病史","早产与低出生体重","常合并复杂先心病"],"epi":"占活产婴儿 1.5–3.5/1000，占先心病 20%–30%；膜周部 70%–80%；30%–50% 小 VSD 1–2 岁自然闭合。"},"patho":"收缩期左室压显著高于右室形成左向右分流，肺血流与左心容量负荷增加；大分流致婴儿心衰与生长滞后；长期肺血管病变使 PVR 升高，最终分流逆转（艾森曼格）。","dx":{"criteria":["胸骨左缘 3–4 肋间粗糙全收缩期杂音伴震颤，P2 亢进，大量分流时心尖部舒张中期杂音","超声见室间隔中断与过隔血流，测直径、Qp/Qs、肺动脉压","心电图：大分流者左房/左室扩大、右室肥厚","胸片：肺血增多、心影增大","导管评估 Qp/Qs、PVR（成人关闭决策必需）"],"workup":["经胸/经食管超声：位置、直径、分流方向、主动脉瓣脱垂","心电图与动态心电图","胸片","右心导管","染色体与遗传咨询","心内膜炎风险评估"],"grading":"大小：小（<3 mm 或 Qp/Qs <1.5）、中（3–6 mm 或 1.5–2.0）、大（>6 mm 或 >2.0）；肺血管病变可逆/临界/艾森曼格。"},"ddx":[{"name":"房间隔缺损（chd_asd）","point":"与本类 chd_asd 鉴别：ASD 杂音更高更柔、无震颤、S2 固定分裂；VSD 杂音更低更粗并伴震颤。"},{"name":"动脉导管未闭（chd_pda）","point":"与本类 chd_pda 鉴别：PDA 为连续性杂音伴脉压增宽；VSD 为收缩期杂音、脉压正常。"},{"name":"肥厚型心肌病（LVOT 梗阻）","point":"杂音随 Valsalva 增强，超声见室间隔增厚与 SAM，无分流。"},{"name":"三尖瓣反流","point":"胸骨下端杂音随吸气增强，超声见反流束与右心扩大。"},{"name":"二尖瓣反流","point":"心尖部杂音向腋下传导，超声见二尖瓣反流束。"},{"name":"主动脉瓣狭窄","point":"喷射性杂音向颈部传导伴细迟脉，超声见瓣膜狭窄。"}],"tx":{"drug":[{"name":"呋塞米（心衰过渡）","dose":"1–2 mg/kg/d 分次（婴儿）","note":"仅大分流心衰的过渡","renal":"监测肾功能","hepatic":"注意低钾","interact":"与地高辛相互作用"},{"name":"卡托普利（婴幼儿）","dose":"0.1–0.5 mg/kg tid（地高辛按体重遵说明书）","note":"需儿科心内科指导，不延迟关闭","renal":"按体重与肾功能调整","hepatic":"遵说明书","interact":"低钾时地高辛易中毒"},{"name":"波生坦（艾森曼格）","dose":"62.5 mg bid 起始，4 周后 125 mg bid","note":"仅关闭禁忌者，按 PAH 指南","renal":"遵说明书","hepatic":"监测肝酶，Child-Pugh B/C 禁用","interact":"诱导 CYP3A4"},{"name":"心内膜炎预防","dose":"阿莫西林 2 g 术前 30–60 min 单次（过敏用头孢氨苄 2 g 或克林霉素 600 mg）","note":"未修复 VSD 与术后 6 个月内属高危","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["小 VSD（尤其肌部）1–2 岁自然闭合率 30%–50%，每 3–6 个月随访","介入封堵：膜周部/肌部 3–14 mm、边缘距瓣膜 ≥2–3 mm、无明显反流，体重通常 ≥10 kg","外科修补：大分流心衰、干下型（易合并主动脉瓣脱垂）、合并瓣膜畸形，多在 1 岁前","成人先导管评估，艾森曼格不关闭","合并主动脉瓣脱垂者同期处理"],"life":["术后随访残余分流与主动脉瓣反流","未关闭小 VSD 每年随访并做牙科保健","大分流未修复者避免剧烈运动","艾森曼格避免脱水、高海拔、妊娠","婴幼儿营养与生长监测"]},"prog":"小 VSD 自然闭合后长期良好；及时关闭者 30 年生存 >95%；大 VSD 未干预者 5 岁内肺血管病变进展。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《常见先天性心脏病经导管介入治疗中国专家共识（2022）》","2020 ESC Guidelines for the management of adult congenital heart disease"]},{"id":"chd_pda","name":"动脉导管未闭","aka":["PDA","Patent Ductus Arteriosus"],"rank":3,"basic":{"define":"胎儿期连接肺动脉与降主动脉的动脉导管出生后未正常闭合（功能关闭 48–72 h、解剖关闭 2–3 周），持续开放形成主动脉到肺动脉的左向右分流。","risk":["早产与低出生体重","新生儿呼吸窘迫综合征、母孕期风疹","高原地区（低氧不利闭合）","遗传综合征（22q11 缺失等）","女性多见"],"epi":"足月儿约 1/2000–1/1600，占先心病 5%–10%；<28 周早产儿发生率 60%–80%。"},"patho":"出生后肺血管阻力下降与氧分压升高本应促导管收缩；早产儿导管肌层不成熟、前列腺素 E2 高使导管开放，形成主动脉→肺动脉分流，降低舒张压与冠脉灌注，致左心容量负荷与肺水肿；长期可致肺高压。","dx":{"criteria":["左第 2 肋间连续性机器样杂音（收缩期增强、舒张期递减），可扪及震颤","脉压增宽、水冲脉、毛细血管搏动","超声见肺动脉分叉与降主动脉间连续分流，LA/Ao >1.5 提示显著分流","心电图左室高电压；胸片肺血增多、主动脉结突出","成人导管评估 Qp/Qs、PVR 与分流方向"],"workup":["超声：导管形态（漏斗/管型/窗型）、最小直径、分流方向","早产儿：体重、分流程度、氧与通气需求","心电图、胸片","成人右心导管（PVR >5 WU 时精细评估）","必要时 CTA 三维重建"],"grading":"大小：小（<2 mm 或 LA/Ao <1.5）、中大型；形态：漏斗型、管型、窗型；肺血管病变可逆/临界/艾森曼格。"},"ddx":[{"name":"室间隔缺损（chd_vsd）","point":"与本类 chd_vsd 鉴别：VSD 为全收缩期杂音、无连续成分，脉压正常。"},{"name":"房间隔缺损（chd_asd）","point":"与本类 chd_asd 鉴别：ASD 无脉压增宽与水冲脉，伴 S2 固定分裂。"},{"name":"主动脉-肺动脉窗","point":"连续性杂音相近但为近端大通道，常合并复杂畸形，需 CTA。"},{"name":"主动脉瓣关闭不全","point":"舒张期递减性杂音，无连续成分，超声见主动脉瓣反流。"},{"name":"冠状动脉瘘","point":"连续性杂音多在心前区下段，超声见冠脉扩张与瘘口。"},{"name":"颈部动静脉瘘","point":"局部连续性杂音与包块，无心脏扩大与肺血增多。"}],"tx":{"drug":[{"name":"布洛芬（早产儿关闭）","dose":"首剂 10 mg/kg，后 5 mg/kg q24h × 2 次（静脉）","note":"临床显著 PDA 首选；少尿、出血、NEC 禁用","renal":"少尿或肌酐升高禁用","hepatic":"肝功异常慎用","interact":"与氨基糖苷类、利尿剂增肾毒"},{"name":"吲哚美辛（早产儿）","dose":"0.1–0.2 mg/kg q12–24h × 3 次，按胎龄调整","note":"注意尿量与肾功能","renal":"少尿禁用","hepatic":"慎用","interact":"同 NSAIDs"},{"name":"对乙酰氨基酚（替代）","dose":"15 mg/kg q6h × 3–5 天","note":"NSAIDs 禁忌时替代，关闭率略低","renal":"相对安全","hepatic":"肝功不良慎用","interact":"与肝毒药物合用风险"},{"name":"呋塞米（中大型 PDA 心衰）","dose":"1–2 mg/kg/d 分次","note":"减轻肺水肿，不关闭导管","renal":"监测肾功能","hepatic":"注意血钾","interact":"与 NSAIDs 同用注意肾灌注"},{"name":"波生坦（艾森曼格）","dose":"62.5 mg bid 起始，4 周后 125 mg bid","note":"仅禁关闭者，按 PAH 指南","renal":"遵说明书","hepatic":"监测肝酶，Child-Pugh B/C 禁用","interact":"诱导 CYP3A4"},{"name":"心内膜炎预防","dose":"阿莫西林 2 g 术前 30–60 min 单次","note":"未关闭 PDA 与术后 6 个月内为高危","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["介入封堵：足月儿/儿童/成人中大型 PDA 首选，导管 2–14 mm、肺高压可逆，体重通常 ≥3–5 kg","外科结扎/离断：早产儿药物无效、窗型或极短导管、合并需手术畸形","早产儿临床显著 PDA（通气依赖、肺水肿）考虑关闭；无症状可观察","艾森曼格禁关闭","成人小分流无左心扩大者可随访"],"life":["早产儿氧疗监测 SpO₂ 目标，兼顾导管闭合与视网膜病变","儿童关闭后 1 年复查超声与心电图","成人关注肺高压与心律失常","艾森曼格避免妊娠、高海拔与脱水","牙科卫生与心内膜炎预防"]},"prog":"足月儿小 PDA 多不影响寿命；大分流未关闭者 40 岁左右可成艾森曼格；及时封堵/手术后 20 年生存 >95%。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《早产儿动脉导管未闭管理专家共识》2021","2020 ESC Guidelines for the management of adult congenital heart disease"]},{"id":"pc_acute","name":"急性心包炎","aka":["Acute Pericarditis","心包炎"],"rank":4,"basic":{"define":"心包脏、壁层急性炎症，以胸痛、心包摩擦音、心电图改变与心包积液为特征，病程 <4–6 周；按病因分特发性/病毒性、结核性、化脓性、自身免疫性、肿瘤性等。","risk":["病毒感染后（柯萨奇、流感、腺病毒）","结核（我国常见，易大量血性积液）","系统性疾病（SLE、RA、硬皮病）","肿瘤与胸部放疗","心梗后（Dressler）、心脏手术后","尿毒症、甲减、药物"],"epi":"占急性胸痛就诊约 1%，特发性/病毒性最常见；我国结核性心包炎仍占重要比例。"},"patho":"病毒直接侵犯或心外膜心肌损伤的免疫反应致心包毛细血管通透性增高、纤维蛋白或浆液渗出；渗液快速增多易致压塞；反复发作与自身免疫机制相关。","dx":{"criteria":["4 项中 ≥2 项：① 心包炎性胸痛（锐利、胸膜性、坐位前倾缓解、仰卧加重）；② 心包摩擦音；③ 广泛 ST 凹面向上抬高或 PR 压低（aVR 抬高）；④ 新发/加重心包积液","支持：CRP/ESR 升高、发热、CT/CMR 炎症表现","超声示心包摩擦、积液量及压塞征象","病原学：T-SPOT、ADA、积液 PCR、血/积液培养"],"workup":["12 导联心电图（ST 抬高 ≥1 mm，无镜像压低）","超声：积液量、右房/右室塌陷","CRP、ESR、肌钙蛋白、BNP、肾功、甲功","胸部 CT：心包增厚、纵隔淋巴结、结核灶","穿刺送检：细胞分类、蛋白、ADA、T-SPOT、培养、细胞学","自身抗体与肿瘤标志物"],"grading":"病程急性（<4–6 周）/慢性（>6 个月）；严重度轻（无高危）/中（CRP 高伴积液）/重（压塞）；复发（4–6 周内）、难治（>6 周无效）。"},"ddx":[{"name":"心包积液与压塞（pc_effusion）","point":"与本类 pc_effusion 鉴别：心包炎以炎症表现为主、积液可少；压塞以颈静脉怒张、奇脉与低血压为主。"},{"name":"缩窄性心包炎（pc_constrictive）","point":"与本类 pc_constrictive 鉴别：缩窄为慢性右心衰、心包增厚钙化，无急性胸痛与 ST 抬高。"},{"name":"房间隔缺损（chd_asd）","point":"与本大类 chd_asd 鉴别：ASD 为慢性右心负荷、固定分裂 S2 与左向右分流，无胸痛、摩擦音与 ST 抬高。"},{"name":"心肌炎（cm_myocarditis）","point":"肌钙蛋白显著升高、室壁运动异常与 CMR 水肿提示心肌受累。"},{"name":"急性心肌梗死","point":"ST 抬高按冠脉区域、凸面向上伴镜像压低，酶显著升高。"},{"name":"肺栓塞","point":"突发呼吸困难、D-二聚体升高、CTPA 见肺动脉充盈缺损。"}],"tx":{"drug":[{"name":"布洛芬","dose":"400–600 mg tid，足量 2–4 周后每 2–4 周减 25%","note":"一线抗炎，不可骤停","renal":"eGFR <30 慎用","hepatic":"重度肝损避免","interact":"与抗凝、SSRI 出血风险；与 ACEI/利尿剂伤肾"},{"name":"萘普生","dose":"250–500 mg bid","note":"替代 NSAIDs","renal":"肾功能不全减量","hepatic":"慎用","interact":"同 NSAIDs"},{"name":"阿司匹林","dose":"750–1000 mg tid","note":"心梗后心包炎首选；勿与布洛芬合用","renal":"慎用","hepatic":"慎用","interact":"与抗凝、抗血小板协同出血"},{"name":"秋水仙碱","dose":"0.5 mg bid（体重 <70 kg 或肾功不全 0.5 mg qd），首发 3 个月、复发 6 个月","note":"与 NSAIDs 联合，显著降低复发","renal":"eGFR <35 减量，<15 禁用","hepatic":"中度以上慎用","interact":"强 CYP3A4/P-gp 抑制剂增毒；与他汀致肌病"},{"name":"泼尼松","dose":"0.2–0.5 mg/kg/d（约 15–30 mg/d），2 周后缓减，疗程 4–6 周","note":"仅 NSAIDs + 秋水仙碱禁忌/无效、自身免疫或妊娠；作一线增加复发","renal":"遵说明书","hepatic":"慎用","interact":"与 NSAIDs 消化道出血；升糖升压"},{"name":"抗结核治疗","dose":"异烟肼 300 mg qd + 利福平 450–600 mg qd + 吡嗪酰胺 1.5 g qd + 乙胺丁醇 0.75–1 g qd，疗程 6–9 个月","note":"确诊或高度疑结核时尽早开始","renal":"按肾功能调整","hepatic":"监测肝功","interact":"利福平降多种药物浓度；乙胺丁醇致视神经炎"},{"name":"万古霉素 + 头孢曲松（化脓性）","dose":"万古霉素 15–20 mg/kg q12h + 头孢曲松 2 g qd，按药敏调整","note":"化脓性需外科引流而非单纯穿刺","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"阿那白滞素（IL-1 抑制剂）","dose":"100 mg 皮下 qd；开始前筛查结核与感染","note":"难治性或秋水仙碱依赖的复发性心包炎","renal":"减量","hepatic":"慎用","interact":"与其他免疫抑制剂增加感染"}],"nonDrug":["卧床与限制运动至症状消失、CRP 正常、心电图恢复","积液快速增多、压塞倾向、化脓/结核性者行心包穿刺或开窗引流","反复复发（>2 次）难治者评估心包切除术","心包镜/活检用于疑难或疑肿瘤/结核","结核病例报告与督导化疗"],"life":["急性期避免剧烈与竞技运动（学生运动员至 3 个月）","足量足疗程用药，勿自行停药","警惕呼吸困难、低血压等压塞症状","戒烟、流感疫苗","每 1–2 周复查 CRP 与超声 4–6 周，之后 3–6 个月"]},"prog":"规范抗炎首次治愈 70%–80%，复发率 15%–30%（激素起始更高）；结核性/化脓性约 20%–30% 进展为缩窄。","refs":["《中国心包疾病诊断和治疗专家共识》2019","2015 ESC Guidelines for the Diagnosis and Management of Pericardial Diseases","《结核性心包炎诊断与治疗专家共识》2018"]},{"id":"pc_effusion","name":"心包积液与心脏压塞","aka":["Pericardial Effusion","Cardiac Tamponade","心包填塞"],"rank":5,"basic":{"define":"心包腔液体超生理量（>50 mL）称心包积液；积液量或增长速率使心包腔内压升高、限制心室舒张充盈并引起血流动力学障碍时称心脏压塞。","risk":["肿瘤（肺癌、乳腺癌、纵隔淋巴瘤）及心包转移","特发性/病毒性心包炎、结核","尿毒症（透析相关）、甲减","心脏手术或导管术后出血","SLE、抗凝过度、主动脉夹层","心衰、肝硬化、低蛋白血症"],"epi":"超声检出心包积液约 1%–3%；恶性肿瘤患者心包积液 5%–20%，肺癌与乳腺癌最常见。"},"patho":"积液抬高心包腔压力，超过心腔舒张压时充盈减少、每搏量下降；快速积聚（出血 100–200 mL 即可）致压力骤升；吸气时右心充盈增加、左心减少形成奇脉。","dx":{"criteria":["Beck 三联征：低血压、颈静脉怒张、心音遥远（常仅部分出现）","奇脉：吸气时收缩压下降 ≥10 mmHg","超声：积液回声、右房收缩晚期塌陷、右室舒张早期塌陷、室间隔随呼吸偏移、下腔静脉扩张不塌陷","心电图：窦速、低电压、电交替","积液量：微量 <50、少量 50–100、中量 100–500、大量 >500 mL"],"workup":["床旁超声（快速评估积液与压塞）","血压测奇脉、颈静脉压、肝颈回流征","心电图","BNP、肌钙蛋白、CRP、肾功、甲功、凝血、血常规","胸部 CT：积液密度、心包增厚/肿块、纵隔淋巴结","穿刺送检：细胞学、ADA、T-SPOT、培养、乳糜试验"],"grading":"时间：急性（分–天，常出血）、亚急性（天–周，常肿瘤）、慢性（>6 个月，常特发性）；血流动力学无压塞/早期压塞/压塞。"},"ddx":[{"name":"急性心包炎（pc_acute）","point":"与本类 pc_acute 鉴别：心包炎以胸痛、摩擦音、ST 抬高为主；压塞以低血压、颈静脉怒张、奇脉与右心塌陷为主。"},{"name":"缩窄性心包炎（pc_constrictive）","point":"与本类 pc_constrictive 鉴别：缩窄性积液少或无、慢性右心衰、心包增厚钙化。"},{"name":"动脉导管未闭（chd_pda）","point":"与本大类 chd_pda 鉴别：PDA 为脉压增宽与连续性杂音，无奇脉与心腔受压。"},{"name":"右室梗死","point":"下壁心梗时颈静脉怒张与低血压，但无大量积液与右心塌陷。"},{"name":"张力性气胸","point":"患侧呼吸音消失、纵隔偏移、超声肺滑动消失。"},{"name":"急性肺栓塞","point":"右心扩大、D-二聚体升高、CTPA 见血栓，心包无积液。"}],"tx":{"drug":[{"name":"快速补液","dose":"生理盐水 250–500 mL 快速静滴，可重复至总量 500–1000 mL","note":"穿刺前的过渡；肺水肿或泵衰竭者避免","renal":"少尿者减量","hepatic":"遵说明书","interact":"与血管扩张剂/利尿剂加重低血压"},{"name":"去甲肾上腺素","dose":"0.05–0.5 µg/kg/min，维持 MAP ≥65 mmHg","note":"增加外周阻力维持冠脉灌注","renal":"监测尿量","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗"},{"name":"异丙肾上腺素（可选）","dose":"2–10 µg/min 泵入","note":"低血压伴心动过缓时增快心率，可诱发心律失常","renal":"无需调整","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗"},{"name":"抗结核治疗","dose":"异烟肼 300 mg qd + 利福平 450–600 mg qd + 吡嗪酰胺 1.5 g qd + 乙胺丁醇 0.75–1 g qd","note":"可在充分化疗基础上加泼尼松 0.5 mg/kg/d 渐减","renal":"按肾功能调整","hepatic":"监测肝功","interact":"利福平为强酶诱导剂"},{"name":"万古霉素 + 头孢曲松（化脓性）","dose":"万古霉素 15–20 mg/kg q12h + 头孢曲松 2 g qd","note":"化脓性需外科引流","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"呋塞米（非压塞性慢性积液）","dose":"20–40 mg qd 按需","note":"仅心衰/肝硬化所致稳定积液；压塞时禁用","renal":"监测肾功能","hepatic":"注意低钾","interact":"见心衰篇"}],"nonDrug":["穿刺指征：① 压塞（紧急）；② 中-大量积液待诊断；③ 疑化脓/结核性；④ 有症状的大量积液；⑤ 主动脉夹层时禁穿刺，先外科处理","超声引导剑突下或心尖入路，留置导管引流","反复大量或肿瘤性积液行剑突下心包开窗","外科心包切除用于化脓性/缩窄性","压塞患者麻醉诱导易循环崩溃，需先扩容并谨慎诱导","穿刺前停抗凝至 INR <1.5 或 DOAC 已停 ≥24–48 h"],"life":["警惕呼吸困难、晕厥、颈静脉鼓胀","心脏术后每日超声与引流量，引流突然减少需警惕","恶性积液 3–4 周随访超声","避免剧烈活动与突然体位改变","抗结核依从性与肝功监测"]},"prog":"急性压塞不穿刺者病死率近 100%；穿刺并发症 1%–5%；恶性积液开窗后中位生存数月；结核性治愈后 20%–30% 进展为缩窄。","refs":["《心包积液及心脏压塞诊疗专家共识》2019","2015 ESC Guidelines for the Diagnosis and Management of Pericardial Diseases","《中国心包疾病诊断和治疗专家共识》2019"]},{"id":"pc_constrictive","name":"缩窄性心包炎","aka":["Constrictive Pericarditis","心包缩窄"],"rank":6,"basic":{"define":"心包纤维化、增厚、钙化而失去弹性，限制心室舒张充盈，以体循环淤血（颈静脉怒张、肝大、腹水、水肿）与心排量下降为特征的慢性心包疾病。","risk":["结核性心包炎（我国主要病因）","心脏手术、放疗与心包切开术后","化脓性心包炎、尿毒症","恶性肿瘤转移","反复发作的自身免疫性心包炎"],"epi":"结核性心包炎 20%–30% 后遗缩窄；心脏术后发生率 0.2%–2%；男女约 2:1，40–60 岁多见。"},"patho":"心包纤维化与钙化形成硬壳，限制舒张容量，充盈只能靠早期快速完成，两侧心室舒张压平台相等；吸气时右心充盈增、左心减形成奇脉；长期右房压升高致肝淤血与腹水。","dx":{"criteria":["活动后气促、乏力，颈静脉显著怒张（Kussmaul 征可阳性）、肝大、腹水、下肢水肿，可有心包叩击音","超声：LVEF 多正常、双房扩大、室壁正常、下腔静脉扩张、室间隔弹跳","多普勒：二尖瓣 E 随吸气下降 >25%、三尖瓣随吸气上升 ≥40%；e' >8 cm/s","CT：心包增厚 ≥4 mm、钙化，右室受压变形","右心导管：双侧舒张末压差 ≤5 mmHg 且相等、右室平方根征"],"workup":["超声（呼吸变异、室间隔弹跳、下腔静脉）","心脏 CT（心包厚度与钙化最佳）与 CMR","右心导管 + 左右心室同步记录","BNP、肝功、白蛋白、肾功能、腹水常规","结核筛查与手术/放疗史","腹水者排查肝硬化/肝癌"],"grading":"病程亚急性（数周–数月）/慢性（>6 个月）；炎症活动期/纤维钙化期；渗出-缩窄型同时见积液与缩窄。"},"ddx":[{"name":"急性心包炎（pc_acute）","point":"与本类 pc_acute 鉴别：急性有胸痛、摩擦音、ST 抬高，血流动力学多稳定。"},{"name":"心包积液与压塞（pc_effusion）","point":"与本类 pc_effusion 鉴别：压塞为急性积液与右心塌陷，穿刺即缓解；缩窄为慢性改变，需手术。"},{"name":"限制型心肌病（cm_rcm）","point":"与 cardiomyopathy 大类 cm_rcm 鉴别：RCM 无室间隔弹跳与心包增厚，E 呼吸变异 <15%、e' <8 cm/s、BNP 显著升高；缩窄性 e' 保留、E 吸气下降 >25%。"},{"name":"肝硬化腹水","point":"颈静脉压显著升高、肝颈回流征阳性、下腔静脉扩张与肝静脉血流异常。"},{"name":"严重三尖瓣反流","point":"有瓣膜病/肺高压史，超声见反流束，无室间隔弹跳与心包增厚。"},{"name":"心脏淀粉样变","point":"低电压与增厚不匹配、环形心内膜下强化、焦磷酸盐显像阳性。"}],"tx":{"drug":[{"name":"呋塞米","dose":"20–40 mg qd 起始按淤血滴定；螺内酯 20–40 mg qd 辅助","note":"术前减症状，避免过度利尿致低心排","renal":"监测肾功能","hepatic":"淤血性肝损时减量","interact":"与地高辛合用注意血钾"},{"name":"抗结核治疗","dose":"异烟肼 300 mg qd + 利福平 450–600 mg qd + 吡嗪酰胺 1.5 g qd + 乙胺丁醇 0.75–1 g qd，6–9 个月","note":"术前控制结核，术后完成全程","renal":"按肾功能调整","hepatic":"监测肝功","interact":"利福平诱导 CYP3A4"},{"name":"泼尼松（结核性抗炎）","dose":"0.5 mg/kg/d 渐减 4–8 周","note":"活动性结核伴大量积液者减少缩窄（证据有限）","renal":"遵说明书","hepatic":"慎用","interact":"与 NSAIDs 消化道出血"},{"name":"美托洛尔（小剂量）","dose":"12.5–25 mg bid","note":"心排量依赖心率，过度减慢致低心排，仅心动过速时用","renal":"无需调整","hepatic":"减量","interact":"与维拉帕米合用显著心动过缓"},{"name":"华法林（房颤）","dose":"INR 2.0–3.0 或按 CrCl 选 DOAC","note":"右房扩大者房颤风险高","renal":"按 CrCl 调整","hepatic":"Child-Pugh C 禁用","interact":"见房颤篇"}],"nonDrug":["心包剥脱术：有症状、影像证实缩窄者尽早手术；手术死亡率 5%–15%","渗出-缩窄型先引流或抗炎，再由 CT 判断是否手术","剥脱范围含上、下腔静脉及两侧心室表面（隔神经内侧）","结核性先控制活动性再手术","术后右室功能恢复延迟，需长期减药与随访"],"life":["低盐限液、控制体重","术前营养支持（低蛋白血症）与肝功能评估","结核患者完成全程化疗并复查","术后 3、6、12 个月复查超声","警惕利尿过度的低血压与肾前性氮质血症"]},"prog":"未手术者 5 年预后差（心源性肝硬化与衰竭）；术后 80%–90% 症状改善，10 年生存 70%–80%。","refs":["《中国心包疾病诊断和治疗专家共识》2019","2015 ESC Guidelines for the Diagnosis and Management of Pericardial Diseases","《缩窄性心包炎外科治疗中国专家共识》2021"]}]},{"id":"endocarditis_aorta","name":"感染性心内膜炎与主动脉疾病","rank":9,"summary":"发热 + 新出现杂音先想心内膜炎（血培养 + 超声双管齐下）；胸背痛 + 血压双上肢不等先想主动脉夹层（未排除前禁用抗栓与溶栓）。","compare":[{"diseaseId":"ie_native","dx":"发热 + 新出现或变化的杂音 + 血培养阳性 + 超声见赘生物（改良 Duke 标准）","key":"血培养与超声是两项主标准，两项均满足可确诊"},{"diseaseId":"ie_prosthetic","dx":"人工瓣置换术后发热，早发（<1 年）以葡萄球菌为主，晚发（≥1 年）类似自体瓣膜","key":"人工瓣环周漏、瓣周脓肿与传导阻滞提示需早期手术"},{"diseaseId":"aorta_dissection","dx":"突发撕裂样胸背痛 + 双上肢血压差 >20 mmHg + 纵隔增宽，CTA 见内膜片与双腔","key":"疼痛性质为撕裂样、累及范围广、D-二聚体显著升高；未排除前禁用抗栓"},{"diseaseId":"takayasu","dx":"年轻女性、无脉症、双上肢血压差、ESR/CRP 升高，血管影像见主动脉及分支狭窄","key":"慢性炎症性，以狭窄/闭塞为主；夹层为急性撕裂、以内膜片与双腔为特征"}],"diseases":[{"id":"ie_native","name":"自体瓣膜感染性心内膜炎","aka":["Infective Endocarditis","IE","自体瓣膜心内膜炎"],"rank":1,"basic":{"define":"病原微生物（细菌、真菌、立克次体）直接感染心内膜（多为瓣膜）引起的炎症性病变，特征为赘生物形成，可致瓣膜破坏、栓塞与脓毒症。","risk":["器质性心脏病：风湿性瓣膜病、二尖瓣脱垂、先天性心脏病、既往心内膜炎","人工瓣膜与心血管植入装置（起搏器、ICD）","静脉药瘾者（右侧心内膜炎，金葡菌为主）","侵入性操作（拔牙、内镜、泌尿道操作）未预防","免疫抑制、糖尿病、透析、肿瘤","高龄"],"epi":"年发病率约 3–10/10 万，随人口老龄化与植入器械增多，发病率呈上升趋势；我国链球菌仍为主要病原，但金黄色葡萄球菌比例上升。院内病死率约 15%–25%。"},"patho":"血流动力学造成的湍流与非细菌性血栓性心内膜炎（NBTE）为细菌黏附提供基础。菌血症后病原体黏附于受损内膜与血小板-纤维蛋白血栓，繁殖形成赘生物并躲避宿主免疫（生物膜形成）。赘生物可：① 直接破坏瓣叶与腱索（急性二尖瓣或主动脉瓣反流、心衰）；② 脱落造成体循环栓塞（脑、脾、肾、冠脉）；③ 形成瓣周脓肿与传导阻滞；④ 持续菌血症激活全身炎症反应。","dx":{"criteria":["改良 Duke 标准（2023 Duke-ISCVID 更新）：","主要标准 1——血培养阳性：典型病原体（草绿链球菌、金黄色葡萄球菌、肠球菌）至少 2 次独立培养阳性；或持久阳性（≥2 次间隔 12 h 以上）；或 Coxiella burnetii 单次阳性","主要标准 2——影像阳性：超声（TTE/TEE）见赘生物、脓肿、假性动脉瘤或新出现的人工瓣周漏；或 PET/CT 见植入物周围异常摄取","次要标准：易感因素（心脏病史或静脉药瘾）、发热 ≥38 ℃、血管现象（栓塞、Janeway 损害、结膜出血）、免疫现象（肾小球肾炎、Osler 结节、Roth 斑、类风湿因子阳性）、血培养阳性但不符合主要标准","确诊：2 项主要标准，或 1 项主要 + 3 项次要，或 5 项次要；可能 IE：1 项主要 + 1 项次要，或 3 项次要"],"workup":["血培养：抗生素使用前采 3 组（不同部位、间隔 ≥1 h），每瓶需 10 mL 血，已用抗生素者需延长孵育或使用吸附瓶","超声心动图：TTE 为初筛（阴性不能排除），TEE 敏感度 >90%，推荐用于所有疑诊者（尤其人工瓣、起搏器导线、TTE 阴性）","心电图：监测新出现的房室传导阻滞（提示瓣周脓肿）","实验室：血常规、CRP、ESR、肾功能、尿常规（血尿提示肾受累）、类风湿因子","影像：头颅 MRI/CT（栓塞）、腹部门窗式 CT（脾/肾梗死）、PET/CT（疑人工瓣或装置感染）","手术或栓塞物培养与组织病理（确诊金标准）"],"grading":"按病程分急性（<6 周，金葡菌为主，进展快）与亚急性（>6 周，链球菌为主）；按瓣膜分自体瓣与人工瓣；按病原体分层决定抗生素方案强度。"},"ddx":[{"name":"人工瓣膜心内膜炎（ie_prosthetic）","point":"与人工瓣心内膜炎的鉴别：自体瓣 IE 多发生在有器质性心脏病或静脉药瘾者，超声见自体瓣赘生物；人工瓣 IE 发生于瓣置换后，早发以葡萄球菌为主，常伴瓣周脓肿与瓣周漏。"},{"name":"主动脉夹层（aorta_dissection）","point":"与主动脉夹层的鉴别：夹层以突发撕裂样胸背痛为主、无持续发热与血培养阳性；但夹层累及主动脉瓣可致急性 AR，需心动超声鉴别。IE 的栓塞可致胸痛，但影像见赘生物与双腔分属不同病变。"},{"name":"多发性大动脉炎（takayasu）","point":"与大动脉炎的鉴别：大动脉炎为慢性无脉症、CRP/ESR 升高但血培养阴性、无赘生物；IE 有持续菌血症与心脏赘生物。"},{"name":"心包炎","point":"以胸痛与心包摩擦音为特征，心电图弥漫 ST 抬高，无赘生物与菌血症。"},{"name":"风湿热","point":"儿童多见，有链球菌感染史与游走性关节炎、环形红斑、皮下结节，ASO 升高但血培养阴性。"},{"name":"系统性红斑狼疮（Libman-Sacks 心内膜炎）","point":"免疫性非感染性赘生物（多见于二尖瓣下表面），血培养阴性，伴 ANA 阳性与多系统表现。"}],"tx":{"drug":[{"name":"青霉素 G（链球菌性 IE）","dose":"1200 万–1800 万 U/d 持续静脉输注或分 6 次，疗程 4 周（自体瓣、敏感株）；青霉素敏感菌 <0.12 µg/mL 时可用 4 周","note":"敏感链球菌首选；需监测肾功能与血钾（大剂量青霉素钠可致高钠与低钾）","renal":"CrCl <30 减量或延长间隔","hepatic":"无需调整","interact":"与氨基糖苷类协同但对肾毒性叠加；大剂量与丙磺舒合用升高血药浓度"},{"name":"头孢曲松（链球菌/肠球菌联合方案）","dose":"2 g 静脉滴注 qd（可 q12h）","note":"门诊序贯治疗与部分链球菌 IE 可用；与庆大霉素联用治疗肠球菌性 IE（2 g q12h + 庆大霉素）","renal":"CrCl <30 减量","hepatic":"重度肝病减量","interact":"与含钙输液（林格液）在新生儿中可致沉淀；与华法林合用增强抗凝"},{"name":"苯唑西林 / 氯唑西林（甲氧西林敏感金葡菌 MSSA）","dose":"2 g 静脉滴注 q4h，疗程 4–6 周","note":"MSSA 首选，优于万古霉素；MRSA 则改用万古霉素","renal":"CrCl <30 减量","hepatic":"肝毒性（转氨酶升高），需监测","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"万古霉素（MRSA 或青霉素过敏）","dose":"15–20 mg/kg 静脉滴注 q8–12h，目标谷浓度 15–20 mg/L（AUC/MIC ≥400），需药物监测","note":"MRSA 经验性与目标治疗；肾毒性（尤其联用氨基糖苷或袢利尿剂）；滴注速度需 >60 分钟（红人综合征）","renal":"严格按 CrCl 调整并监测血药浓度","hepatic":"无需调整","interact":"与氨基糖苷类、两性霉素 B、环孢素合用增加肾毒性"},{"name":"达托霉素（高剂量，用于 MRSA 或右心 IE）","dose":"8–10 mg/kg 静脉滴注 q24h（右心 IE 与高 MIC 时用高剂量）","note":"与 β 内酰胺类联用可增强疗效；可被肺表面活性物质灭活，不用于左心或肺炎","renal":"CrCl <30 延长间隔或减量","hepatic":"无需调整","interact":"与他汀类合用增加肌病风险（建议停用他汀）"},{"name":"庆大霉素（肠球菌性 IE 联合短疗程）","dose":"3 mg/kg/d 分 2–3 次（或单次）静脉/肌注，疗程 2 周（肠球菌性）","note":"仅用于肠球菌性 IE 的协同治疗，短疗程以减少肾毒性；不用于链球菌性 IE（毒性大于获益）","renal":"按 CrCl 调整，监测血药浓度与血肌酐","hepatic":"无需调整","interact":"与万古霉素、两性霉素 B、袢利尿剂合用增加耳肾毒性"},{"name":"氟康唑 / 两性霉素 B（真菌性 IE）","dose":"氟康唑 400–800 mg/d 口服/静滴（念珠菌）；两性霉素 B 脱氧胆酸盐 0.7–1 mg/kg/d 或脂质体 3–5 mg/kg/d","note":"真菌性 IE 需长疗程（≥6 周）且多数需手术；两性霉素 B 需监测肾功与电解质","renal":"两性霉素 B 肾毒性显著，CrCl <30 需减量或改用脂质体","hepatic":"氟康唑肝毒性，需监测","interact":"氟康唑抑制 CYP2C9/3A4，升高华法林与他汀浓度；两性霉素 B 与肾毒性药物合用需谨慎"}],"nonDrug":["手术指征（约 50% 患者需要）：① 心衰（瓣膜急性关闭不全）；② 未控制的感染（持续菌血症 >7–10 天、瓣周脓肿、真菌性）；③ 预防栓塞（赘生物 >10 mm 且反复栓塞）；④ 人工瓣功能障碍或瓣周漏","急性心衰是手术的最主要指征（不能因感染未控而延误）","感染的持续监测：每日体温、血培养（每 24–48 小时）至阴性","起搏器/ICD 导线感染：需完全拔除装置（经静脉拔除）","抗生素预防（仅高危患者做牙科等操作前）：阿莫西林 2 g 术前 30–60 分钟单次口服"],"life":["疗程结束后复查血培养、CRP 与超声（评估瓣膜功能与赘生物）","出院后 1、3、6、12 个月随访，包括复发监测（复发多在 6 个月内）","口腔卫生与定期牙科检查（减少菌血症来源）","静脉药瘾者需戒毒干预与心理支持","告知患者后续任何侵入性操作前需告知医生有心内膜炎史"]},"prog":"未经治疗几乎全部死亡；规范抗生素治疗后院内病死率仍约 15%–25%，金葡菌与心衰者更高。复发率约 2%–6%（多在 6 个月内）。早期手术（尤其合并心衰）可显著降低病死率。人工瓣心内膜炎病死率（约 20%–40%）高于自体瓣。","refs":["《成人感染性心内膜炎预防、诊断和治疗专家共识》（中华医学会心血管病学分会，2014）","2023 ESC Guidelines for the Management of Endocarditis","2023 Duke-ISCVID Criteria for Infective Endocarditis (Clin Infect Dis)","2015 AHA Scientific Statement: Infective Endocarditis in Adults","《中国感染性心内膜炎外科治疗专家共识》（2022）"]},{"id":"ie_prosthetic","name":"人工瓣膜心内膜炎","aka":["Prosthetic Valve Endocarditis","PVE","早发型 PVE","晚发型 PVE"],"rank":2,"basic":{"define":"发生于人工瓣置换术后（机械瓣或生物瓣）的感染性心内膜炎，按术后时间分早发型（≤12 个月，多为围术期获得）与晚发型（>12 个月，机制近似自体瓣 IE），病死率高于自体瓣心内膜炎。","risk":["术后早期（前 12 个月风险最高）","围术期感染、伤口感染、导管留置","金黄色葡萄球菌与凝固酶阴性葡萄球菌定植","长期激素或免疫抑制","再次瓣膜置换、复杂手术","透析与糖尿病"],"epi":"人工瓣置换术后 1 年内 PVE 发生率约 1%–3%，5 年累计约 3%–6%。机械瓣与生物瓣风险相近。早期 PVE 以葡萄球菌（尤其凝固酶阴性葡萄球菌、金葡菌）与真菌多见，晚期以链球菌为主。"},"patho":"早期 PVE 病原多来自术中污染、皮肤菌群或导管感染，倾向于侵袭瓣环与缝合环，造成瓣周脓肿、假性动脉瘤与瓣周漏。晚期 PVE 由菌血症（牙科、泌尿道、消化道操作或日常菌血症）种植于瓣膜-缝合环界面。生物瓣可被感染并迅速破坏；机械瓣本身不易感染但缝合环与瓣周组织易受累。瓣周脓肿可压迫传导系统产生房室阻滞，也可破入心包致压塞。","dx":{"criteria":["人工瓣置换术后发热 + 新出现杂音或心力衰竭，应高度怀疑 PVE","血培养阳性（主要标准同自体瓣 IE）；凝固酶阴性葡萄球菌单次阳性需谨慎解读（常见污染，需多次）","超声（首选 TEE，敏感度显著优于 TTE）：赘生物、瓣周脓肿（低回声区）、假性动脉瘤、新出现的瓣周漏（需与术后基线对比）","PET/CT 或放射性核素标记白细胞显像：对瓣周感染与植入物感染有较高价值（2023 ESC 推荐）","新出现房室传导阻滞或束支阻滞提示瓣周脓肿累及传导系统","满足改良 Duke 标准（同自体瓣 IE）即可诊断；PVE 的影像证据常需 TEE"],"workup":["血培养 3 组（抗生素前），需含需氧与厌氧瓶","TTE + TEE（TEE 为必需，PVE 诊断敏感度约 80%–90%）","心电图（新出现传导阻滞）","PET/CT 或标记白细胞扫描（疑 PVE 而超声阴性时）","胸片、胸壁超声（瓣周脓肿）与经食管三维超声（术前评估）","手术标本（赘生物、瓣膜、瓣周组织）培养与病理"],"grading":"按术后时间分早期（≤12 个月）与晚期（>12 个月）；影像学上区分瓣膜赘生物与瓣周感染（脓肿、假性动脉瘤、瓣周漏）——后者手术指征更明确。"},"ddx":[{"name":"自体瓣膜感染性心内膜炎（ie_native）","point":"与自体瓣心内膜炎的鉴别：自体瓣 IE 发生于天然瓣膜，超声见瓣叶赘生物；PVE 发生于人工瓣，常累及缝合环与瓣周组织，瓣周脓肿与瓣周漏更常见，手术门槛更低。"},{"name":"主动脉夹层（aorta_dissection）","point":"与主动脉夹层的鉴别：夹层为突发撕裂痛、CTA 见内膜片，无持续菌血症；但夹层可累及主动脉根部致急性瓣周漏，需影像区分。"},{"name":"多发性大动脉炎（takayasu）","point":"与大动脉炎的鉴别：慢性无脉症、血培养阴性、无赘生物与瓣周破坏。"},{"name":"术后早期非感染性炎症（术后综合征/心包切开后综合征）","point":"术后数天至数周发热、CRP 升高但血培养阴性，超声无赘生物与瓣周脓肿，对 NSAIDs 或激素反应好。"},{"name":"瓣周漏（非感染性）","point":"手术后即出现，无发热与菌血症，超声见漏但无脓肿与赘生物。"},{"name":"起搏器/ICD 导线感染","point":"可并存，需经食管超声与血培养确认，处理需拔除装置。"}],"tx":{"drug":[{"name":"万古霉素 + 美罗培南 + 庆大霉素（早期 PVE 经验方案）","dose":"万古霉素 15–20 mg/kg q8–12h（谷浓度 15–20 mg/L）+ 美罗培南 2 g q8h + 庆大霉素 3 mg/kg/d（分次）；血培养结果回报后调整","note":"早期 PVE 需覆盖葡萄球菌（含 MRSA）、革兰阴性菌与肠球菌；确认病原后尽快降阶梯以减少肾毒性","renal":"三联均有肾毒性，需严格按 CrCl 调整并监测","hepatic":"美罗培南肝毒性低，万古霉素无需调整","interact":"万古霉素 + 庆大霉素肾毒性协同，需密切监测"},{"name":"利福平（金葡菌性 PVE 辅助）","dose":"300 mg 口服 q8h（或 600 mg q12h），在菌血症清除后加用，全疗程 ≥6 周","note":"利福平对生物膜内葡萄球菌有杀菌作用，是 PVE 方案的关键组成；必须与主方案联用，绝不单用（快速耐药）","renal":"无需调整","hepatic":"肝毒性（转氨酶升高、胆汁淤积），需监测肝功能","interact":"强 CYP3A4 诱导剂，显著降低华法林、他汀、口服避孕药、抗真菌药（伊曲康唑、伏立康唑）浓度"},{"name":"头孢曲松 + 氨苄西林（肠球菌性 PVE）","dose":"头孢曲松 2 g q12h + 氨苄西林 2 g q4h，疗程 6 周；或氨苄西林 + 头孢曲松（避免氨基糖苷以减少肾毒性）","note":"肠球菌性 PVE 常需手术；双 β 内酰胺方案肾毒性低于氨基糖苷联合","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与华法林合用增强抗凝"},{"name":"手术与抗凝管理（机械瓣患者）","dose":"术前桥接：停华法林，用普通肝素静脉（APTT 1.5–2 倍）至术前 6 h 停；术后 24–48 h 无出血即恢复","note":"机械瓣患者合并 PVE 的抗栓管理极复杂，需心脏团队决策；颅内出血者需停抗凝","renal":"肝素无需调整","hepatic":"重度肝病慎用肝素","interact":"肝素与抗血小板药叠加出血风险"}],"nonDrug":["手术指征（PVE 手术率高于自体瓣，约 50%）：心衰、未控制感染、瓣周脓肿/假性动脉瘤、瓣膜功能障碍与反复栓塞","早期手术优于保守治疗（尤其合并瓣周脓肿或心衰）","术后抗生素总疗程 6 周（自手术日算起；若术中培养阳性需重新计算）","术后长期抗凝管理（机械瓣需华法林，生物瓣术后 3 个月抗凝后改抗血小板）","心电监护：新出现房室阻滞需警惕脓肿进展"],"life":["出院前复查血培养、超声（评估瓣周情况）与炎症指标","长期随访：1、3、6、12 个月及此后每年（PVE 复发率约 5%–10%）","口腔与皮肤卫生、侵入性操作前抗生素预防","机械瓣患者需维持 INR 达标与定期监测","告知患者发热 + 瓣膜症状需立即就诊（复发或新发心内膜炎）"]},"prog":"早期 PVE 病死率 20%–40%，晚期约 10%–20%；合并瓣周脓肿、心衰与葡萄球菌感染者更高。手术联合抗生素是改善生存的关键。复发率约 5%–10%，复发多见于术后 6 个月内。机械瓣 PVE 的病死率高于生物瓣。","refs":["2023 ESC Guidelines for the Management of Endocarditis（PVE 章节）","《成人感染性心内膜炎预防、诊断和治疗专家共识》（中华医学会心血管病学分会，2014）","2015 AHA Scientific Statement: Infective Endocarditis in Adults（PVE 部分）","2023 Duke-ISCVID Criteria for Infective Endocarditis","《中国心脏瓣膜术后感染性心内膜炎诊治专家共识》（2021）"]},{"id":"aorta_dissection","name":"主动脉夹层","aka":["Aortic Dissection","Stanford A 型","Stanford B 型","主动脉内膜撕裂"],"rank":3,"basic":{"define":"主动脉内膜撕裂，血液进入中膜形成假腔并使内膜与中膜分离的急危重症。按 Stanford 分型：A 型累及升主动脉（需急诊手术），B 型未累及升主动脉（多数可药物或腔内治疗）。","risk":["高血压（最主要，约 70% 患者有）","结缔组织病：马方综合征、Ehlers-Danlos 综合征、Loeys-Dietz 综合征","二叶主动脉瓣、主动脉缩窄","妊娠（尤其第三孕期与产褥期）","动脉粥样硬化与高龄","可卡因与拟交感药物、严重外伤、医源性（插管/支架）"],"epi":"年发病率约 3–6/10 万，男性多于女性（约 2–3:1），发病高峰 60–70 岁（结缔组织病者更年轻）。未治疗的 A 型夹层 48 小时内病死率约 50%，是心血管急症中致死最快者之一。"},"patho":"中膜囊性坏死与弹性纤维断裂使主动脉壁抗张强度下降，在血压冲击下内膜撕裂形成假腔（入口），血液沿中膜层分离（可顺行或逆行），并可通过再破口回到真腔。假腔压迫真腔致器官缺血（冠脉、颈动脉、肾动脉、肠系膜、下肢）；外膜破裂致心包积血/压塞、胸腔或腹膜后大出血而猝死。升主动脉受累时可致主动脉瓣关闭不全、冠脉开口受累（致心梗）与心包压塞。","dx":{"criteria":["典型症状：突发撕裂样或刀割样胸背痛或腹痛（占 80%–90%），部分疼痛可迁移（随夹层蔓延）；晕厥发生约 10%–15%","体征：双上肢或上下肢血压差 >20 mmHg、脉搏短绌（约 20%）、新出现主动脉瓣反流杂音、颈静脉怒张（压塞）","确诊影像（任一项即可）：主动脉 CTA（首选，敏感度与特异度均 >95%，见内膜片、双腔与假腔）；经食管超声（床旁、可评估瓣膜与心包）；MRA（稳定患者、随访）；主动脉造影（已多被 CTA 取代）","胸片：纵隔增宽（>8 cm）、主动脉轮廓异常、胸腔积液——正常胸片不能排除","D-二聚体：显著升高（>500 ng/mL）有高阴性预测价值；D-二聚体正常可高度（但不完全）排除","分型：Stanford A（累及升主动脉，需急诊手术）；Stanford B（不累及升主动脉，多数药物治疗，复杂型可腔内治疗）"],"workup":["立即主动脉 CTA（血流动力学稳定者）或床旁经食管超声（不稳定者）","心电图与心肌标志物（排除 ACS，但注意 A 型夹层可致冠脉受累并发心梗）","双侧上肢与下肢血压、脉搏","床旁超声（心包积液、主动脉瓣反流、心功能）","血常规、凝血、肾功能、D-二聚体、血型与交叉配血","若拟手术：冠脉造影（注意风险）或 CT 冠脉成像"],"grading":"Stanford 分型（A/B）为治疗决策核心；DeBakey 分型（I 型：累及升主动脉并延伸至降主动脉；II 型：限于升主动脉；III 型：限于降主动脉）。按时间分急性（≤14 天）、亚急性（15–90 天）与慢性（>90 天）。"},"ddx":[{"name":"自体瓣膜感染性心内膜炎（ie_native）","point":"与心内膜炎的鉴别：IE 有持续发热、血培养阳性与赘生物；夹层为突发撕裂痛、无发热，影像见内膜片。两者可并存（IE 可致夹层、夹层可致继发感染）。"},{"name":"人工瓣膜心内膜炎（ie_prosthetic）","point":"与 PVE 的鉴别：PVE 有瓣膜置换史与发热，影像见瓣周脓肿；夹层为急性撕裂痛、无感染征象。"},{"name":"多发性大动脉炎（takayasu）","point":"与大动脉炎的鉴别：大动脉炎为年轻女性慢性炎症性狭窄/闭塞，CRP/ESR 高但无内膜片与双腔；夹层为急性、CTA 见内膜片。"},{"name":"急性冠脉综合征（STEMI/NSTEMI）","point":"此鉴别关乎生死：A 型夹层累及冠脉时可出现 ST 抬高与肌钙蛋白升高，若误诊为 STEMI 而给予溶栓或双抗可致大出血死亡。夹层有撕裂样痛、双上肢血压差与纵隔增宽；影像（CTA/食管超声）是唯一可靠鉴别。"},{"name":"肺栓塞","point":"以呼吸困难与胸痛为主、无撕裂样性质，CTPA 见肺动脉充盈缺损，无主动脉内膜片。"},{"name":"急性心包炎","point":"胸痛随呼吸与体位变化、心包摩擦音、心电图弥漫 ST 抬高，无内膜片与血压差。"},{"name":"自发性食管破裂 / 急性胰腺炎","point":"均有剧烈胸腹疼痛，但影像与酶学可鉴别；食管破裂有纵隔气肿，胰腺炎有脂肪酶升高。"}],"tx":{"drug":[{"name":"艾司洛尔（首选静脉 β 阻滞剂）","dose":"负荷 0.5 mg/kg 静脉推注（1 分钟），随后 50 µg/kg/min 泵入，按心率调整至 100–200 µg/kg/min；目标心率 <60 次/分","note":"先控制心率（降低 dP/dt），再控制血压；哮喘、重度心衰与心动过缓者禁用","renal":"无需调整","hepatic":"严重肝病慎用","interact":"与维拉帕米、地尔硫卓合用增加心脏传导阻滞与心衰风险"},{"name":"拉贝洛尔","dose":"20 mg 静脉推注（2 分钟），随后 0.5–2 mg/min 泵入；或 1–2 mg/min 起始，总量可达 300 mg","note":"α/β 双重阻滞剂，是夹层降压的常用药；高血压急症中安全；避免用于哮喘与严重心动过缓","renal":"无需调整","hepatic":"肝病者减量","interact":"与硝酸酯类合用协同降压"},{"name":"尼卡地平 / 硝普钠（二线或联合）","dose":"尼卡地平 5 mg/h 起始，每 5–15 分钟递增 2.5 mg/h，最大 15 mg/h；硝普钠 0.3–0.5 µg/kg/min 起始，按血压滴定，最大 10 µg/kg/min","note":"在 β 阻滞剂控制心率后加用，目标 SBP 100–120 mmHg（确保脏器灌注）；硝普钠需避光且长期使用有氰化物中毒风险（尤其肾功能不全）","renal":"硝普钠在肾功能不全者氰化物蓄积风险高","hepatic":"重度肝病慎用","interact":"硝普钠与 β 阻滞剂合用可致反射性心动过速（β 阻滞剂可对抗）"},{"name":"吗啡（镇痛）","dose":"3–5 mg 静脉缓慢推注，必要时重复","note":"疼痛与焦虑升高交感张力与血压，镇痛是治疗的一部分；注意呼吸抑制","renal":"肾功能不全者活性代谢物蓄积，需减量","hepatic":"肝病者减量","interact":"与镇静药合用增加呼吸抑制"},{"name":"艾司洛尔维持（术后/转长期）","dose":"转口服：美托洛尔 25–100 mg bid 或比索洛尔 2.5–10 mg qd，按心率滴定","note":"长期 β 阻滞剂是夹层后二级预防的核心","renal":"无需调整","hepatic":"肝病减量","interact":"同 β 阻滞剂类"},{"name":"禁忌提示：抗栓与溶栓","dose":"确诊或高度怀疑夹层时禁用抗血小板（双抗）、抗凝与溶栓治疗","note":"误诊为 ACS 而给溶栓/双抗可致主动脉破裂大出血死亡；这是夹层最重要的安全警示","renal":"—","hepatic":"—","interact":"—"}],"nonDrug":["Stanford A 型：急诊外科手术（升主动脉置换，必要时全主动脉弓置换 + 支架象鼻）","Stanford B 型（无并发症）：药物保守（严格降压与心率控制）+ 密切影像随访","Stanford B 型（复杂型：灌注不良、快速扩张、破裂先兆、顽固疼痛/高血压）：胸主动脉腔内修复（TEVAR）","急性期监护：ICU、有创血压监测、双上肢血压对比、尿量与神经功能监测","手术中需注意脊髓保护（脑脊液引流）与脏器灌注"],"life":["终身严格血压管理：目标 SBP <120 mmHg（可耐受时），长期 β 阻滞剂为基础","避免剧烈运动、重体力劳动、屏气用力与可卡因等拟交感药物","定期影像随访：术后 1、3、6、12 个月，此后每年 CTA 评估残余夹层与假腔变化","遗传性结缔组织病者需家系筛查与基因检测","妊娠期高风险（尤其马方综合征者），需孕前评估与多学科管理"]},"prog":"未治疗 A 型夹层 48 小时内病死率约 50%，1 周约 70%；急诊手术后 30 天病死率约 10%–30%（依中心与并发症而定）。B 型药物保守者 5 年生存约 60%–80%，但约 20%–40% 需后期干预。长期预后取决于血压控制与假腔是否血栓化。","refs":["《主动脉夹层诊断与治疗规范中国专家共识》（中华医学会心血管病学分会，2017）","2022 ACC/AHA Guideline for the Diagnosis and Management of Aortic Disease","2014 ESC Guidelines on the Diagnosis and Treatment of Aortic Diseases","《Stanford B 型主动脉夹层腔内治疗中国专家共识》（2021）","《中国胸主动脉腔内修复术（TEVAR）临床实践指南》"]},{"id":"takayasu","name":"多发性大动脉炎","aka":["Takayasu Arteritis","TA","无脉症","主动脉弓综合征"],"rank":4,"basic":{"define":"累及主动脉及其主要分支的慢性肉芽肿性大血管炎，导致管腔狭窄、闭塞或动脉瘤形成，因常致上肢脉搏减弱或消失而称「无脉症」，多见于年轻女性。","risk":["年轻女性（<40 岁，男女比约 1:8–9）","亚洲人群高发（日本、中国、印度）","HLA-B52 等遗传易感","结核感染史（部分地区相关）"],"epi":"年发病率约 1–3/100 万，我国与日本相对高发。发病高峰 20–30 岁，女性占 80%–90%。"},"patho":"以 T 细胞介导的肉芽肿性炎症累及主动脉中膜与外膜，伴 CD4⁺ T 细胞、巨噬细胞与多核巨细胞浸润，导致中膜弹力纤维与平滑肌破坏，内膜增生与纤维化致管腔狭窄，中膜破坏可致动脉瘤。按 Numano 分型累及不同部位（I 型主动脉弓分支；IIa 型升主动脉+弓；IIb 型+降主动脉；III 型胸降+腹主动脉；IV 型腹主动脉；V 型全主动脉）。肾脏受累（肾动脉狭窄）是继发性高血压的主要原因，也是预后关键。","dx":{"criteria":["ACR 1990 分类标准（满足 ≥3 项）：① 发病年龄 ≤40 岁；② 肢体间歇性运动障碍（活动时肢体缺血）；③ 肱动脉搏动减弱；④ 双上肢血压差 >10 mmHg；⑤ 锁骨下动脉或主动脉杂音；⑥ 动脉造影见主动脉或其分支狭窄或闭塞","活动期判断：发热、乏力、体重下降、关节肌痛 + ESR/CRP 升高，但约 50% 患者在诊断时炎症指标正常","影像诊断（必须）：CTA/MRA 见主动脉及分支管壁均匀环形增厚、狭窄或闭塞、动脉瘤；PET/CT 见管壁 FDG 摄取增高（评估活动性）","需与动脉粥样硬化、肌纤维发育不良、主动脉夹层与大动脉炎样病变（梅毒、IgG4 相关）鉴别"],"workup":["ESR、CRP（活动性指标）、血常规、肝肾功能","双上肢与双下肢血压测量（对比）、脉搏触诊、血管杂音听诊","CTA 或 MRA（全主动脉与分支，评估狭窄与动脉瘤）","PET/CT（评估管壁炎症活动性，指导激素减量）","颈动脉与锁骨下动脉超声（管壁增厚与血流）","筛查继发性高血压：肾动脉超声/CTA、醛固酮肾素比值（若有肾动脉狭窄）","眼科检查（高血压视网膜病变、眼底缺血）"],"grading":"Numano 分型（I–V 型）；临床活动度按 NIH 标准（新发或加重的全身症状、炎症指标升高、影像新发病变）分为活动期与缓解期。"},"ddx":[{"name":"感染性心内膜炎（ie_native）","point":"与 IE 的鉴别：IE 有持续发热、血培养阳性与心脏赘生物，为急性感染性病程；大动脉炎为慢性炎症性狭窄/闭塞，无赘生物与菌血症。"},{"name":"主动脉夹层（aorta_dissection）","point":"与夹层的鉴别：夹层为突发撕裂样疼痛、CTA 见内膜片与双腔；大动脉炎为慢性病程、管壁环形增厚与狭窄，无内膜片。"},{"name":"动脉粥样硬化性外周动脉病","point":"年龄较大、有吸烟与糖尿病等危险因素，病变多为偏心性斑块伴钙化，而非环形均匀增厚；无全身炎症表现。"},{"name":"巨细胞动脉炎（rh_gca）","point":"发病年龄 ≥50 岁、累及颞动脉与颅外颈动脉分支，有头痛、颞部压痛与视力威胁，主动脉受累亦有；大动脉炎以 <40 岁女性、主动脉及其分支为主。"},{"name":"IgG4 相关性疾病","point":"可有主动脉周围炎与腹膜后纤维化，血清 IgG4 升高与组织 IgG4⁺ 浆细胞浸润，需病理鉴别。"},{"name":"肌纤维发育不良","point":"年轻女性、肾动脉或颈内动脉中远段「串珠样」改变，无炎症指标升高与管壁增厚。"}],"tx":{"drug":[{"name":"泼尼松（糖皮质激素）","dose":"起始 1 mg/kg/d（最大 60 mg/d）口服，临床与炎症缓解后（通常 2–4 周）逐渐减量，每 2–4 周减 5–10 mg，至维持 5–10 mg/d；疗程常需 1–2 年以上","note":"活动期的一线治疗；单用激素约 50% 可缓解，但复发率高（约 50%–70%）；需预防骨质疏松、PPI 保护胃黏膜与监测血糖","renal":"无需调整（但肾动脉狭窄者需监测血压与肾功能）","hepatic":"肝病者需监测","interact":"与 NSAIDs 合用增加消化道溃疡；降低降糖药效果；活疫苗禁用"},{"name":"甲氨蝶呤（激素节约剂）","dose":"10–25 mg 每周一次（口服或皮下），联合叶酸 5 mg 每周（非同日）","note":"激素不能顺利减量或复发的二线基础用药；需监测肝功能、血象与肾功能","renal":"CrCl <30 禁用（蓄积毒性）","hepatic":"肝病与酗酒者禁用","interact":"与 NSAIDs 合用可能降低排泄增加毒性；与磺胺类（复方新诺明）合用增加骨髓抑制"},{"name":"硫唑嘌呤","dose":"1–2 mg/kg/d 口服","note":"激素节约剂；用药前建议查 TPMT 活性（缺乏者禁用）；需监测血象","renal":"肾功能不全减量","hepatic":"肝病者慎用","interact":"与别嘌醇合用显著增加骨髓抑制（需减至 1/4 剂量）"},{"name":"托珠单抗（IL-6 受体拮抗剂）","dose":"8 mg/kg 静脉每 4 周，或 162 mg 皮下每周/每两周（遵说明书）","note":"激素难治或复发性大动脉炎的有效选择（TOCITAK 研究支持）；用药前筛查结核与乙肝，监测感染与肝功能","renal":"无需调整","hepatic":"转氨酶 >3 倍上限需评估","interact":"与其他免疫抑制剂合用增加感染风险；影响 CRP 生成（可能掩盖感染）"},{"name":"阿司匹林（抗血小板）","dose":"75–100 mg qd","note":"用于预防血栓形成与缺血事件（证据有限但广泛使用）；合并动脉瘤者需权衡","renal":"CrCl <30 慎用","hepatic":"活动性肝病禁用","interact":"与抗凝或其他 NSAIDs 合用增加出血"},{"name":"降压药（肾动脉狭窄继发高血压）","dose":"ACEI/ARB 为肾血管性高血压首选（依那普利 5–20 mg/d 或缬沙坦 80–160 mg/d），双侧肾动脉狭窄者禁用；可联用钙拮抗剂（氨氯地平 5–10 mg/d）与 β 阻滞剂","note":"肾动脉狭窄致高血压是主要并发症，需同时评估血运重建；单侧狭窄可用 ACEI/ARB，双侧禁用（可致急性肾衰）","renal":"监测肌酐与血钾（升高 >30% 需评估）","hepatic":"重度肝病慎用","interact":"ACEI/ARB 与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低降压效果并增加肾损伤"}],"nonDrug":["血运重建指征：血流动力学显著的肾动脉狭窄伴难治性高血压或肾功能下降、脑血管缺血（短暂脑缺血/卒中）、肢体严重缺血、主动脉瓣反流","手术或介入时机的关键：应在炎症控制（缓解期）后进行，活动期手术吻合口并发症与再狭窄率高","优先选择经皮腔内血管成形或支架（PTA/PTAS）；复杂病变需旁路手术","主动脉瘤：直径 >5 cm 或快速增大者需外科或腔内修复","定期有创血压监测与双上肢血压对照，避免依赖单侧测量"],"life":["长期随访：炎症指标（ESR/CRP）每 1–3 个月，影像（MRA/CTA）每 6–12 个月","避免长时间压迫患肢、剧烈运动与寒冷刺激","妊娠：病情稳定 ≥6 个月再计划妊娠，妊娠期需多学科管理（激素可继续）","激素长期使用：补钙与维生素 D、骨密度监测、胃黏膜保护","结核高危人群用药前筛查（激素与生物制剂可致潜伏结核再激活）"]},"prog":"规范免疫抑制治疗后 5 年生存率 >90%，但复发率约 50%，需长期随访。主要并发症为肾动脉狭窄所致高血压与肾衰竭、主动脉瓣反流、动脉瘤破裂与脑血管事件。早期识别与炎症控制可显著改善预后；延误诊断者常遗留不可逆血管狭窄。","refs":["《大动脉炎诊断与治疗中国专家共识》（中华医学会风湿病学分会，2011）及后续更新","2018 EULAR Recommendations for the Management of Large Vessel Vasculitis","1990 ACR Classification Criteria for Takayasu Arteritis","2021 ACR/VF Guideline for the Management of Giant Cell Arteritis and Takayasu Arteritis","2018 Japanese Circulation Society Guideline on Diagnosis and Treatment of Takayasu Arteritis"]}]},{"id":"pulm_vasc_other","name":"肺血管病与心血管其他","rank":10,"summary":"肺高压先做右心导管确诊并分 WHO 1–5 组（决定治疗路径）；血脂与高血压管理看「危险分层后的目标值」，而非单一化验值。","compare":[{"diseaseId":"ph_group","dx":"静息 mPAP ≥20 mmHg + PVR >2 WU + PAWP ≤15 mmHg（右心导管），并分 WHO 1–5 组","key":"右心导管是确诊必需；分组决定能否使用靶向药（仅 1 组与部分 4 组有效）"},{"diseaseId":"dyslipidemia","dx":"LDL-C 超出目标值（极高危 <1.4 mmol/L 且降幅 ≥50%），伴 TC/TG/HDL-C 异常","key":"先做 ASCVD 风险分层，再定 LDL-C 目标；目标导向治疗而非化验单范围"},{"diseaseId":"secondary_htn","dx":"年轻发病、血压难控（≥3 种药）、伴低血钾或夜尿、肌酐升高或双肾大小差异","key":"优先筛查原醛（醛固酮/肾素比值）、肾血管与睡眠呼吸暂停"},{"diseaseId":"cardiac_neurosis","dx":"心悸胸闷心悸伴焦虑或过度关注，检查（心电、超声、运动试验）无器质性异常","key":"排除性诊断，需先完成心血管评估并处理共病焦虑抑郁"}],"diseases":[{"id":"ph_group","name":"肺动脉高压（WHO 分类与靶向治疗）","aka":["Pulmonary Hypertension","PH","肺高血压","动脉性肺动脉高压 PAH"],"rank":1,"basic":{"define":"静息状态下经右心导管测得平均肺动脉压（mPAP）≥20 mmHg 的血流动力学状态，可源于多种疾病。按 WHO 分五组：1 组动脉性肺动脉高压（PAH）、2 组左心疾病相关、3 组肺部疾病/缺氧相关、4 组慢性血栓栓塞性（CTEPH）、5 组机制不明/多因素。","risk":["1 组：特发性（无明确病因）、遗传性（BMPR2 等突变）、结缔组织病相关（系统性硬化、SLE）、先天性心脏病、门脉高压、药物毒物相关","2 组：左心衰（HFrEF/HFpEF）、瓣膜病","3 组：COPD、间质性肺病、睡眠呼吸暂停、高原缺氧","4 组：急性肺栓塞后未完全溶解（CTEPH）","5 组：结节病、血液病、慢性肾病等"],"epi":"全球患病率约 1%（>65 岁约 10%）。我国 1 组 PAH 中先心病相关最常见，其次为特发性与结缔组织病相关。CTEPH 在急性肺栓塞后 2 年内的累积发生率约 0.5%–4%。"},"patho":"肺血管内皮功能障碍与平滑肌增殖致肺小动脉重构与闭塞，肺血管阻力（PVR）升高，右心室后负荷增加，最终发生右心衰。1 组 PAH 涉及 BMPR2/TGF-β 通路异常、内皮素-1 与前列环素通路失衡、NO 合成减少；三条通路分别是靶向药（内皮素受体拮抗剂、前列环素类似物、NO-cGMP 通路激动剂）的治疗靶点。4 组 CTEPH 为血栓机化不溶解形成纤维性狭窄与微血管病变，是唯一可手术治愈（PEA）的类型。","dx":{"criteria":["右心导管（确诊必需）血流动力学定义：mPAP ≥20 mmHg；且 PVR >2 WU（肺血管病前毛细血管性）；PAWP ≤15 mmHg（区分 2 组）","2 组左心疾病：PAWP >15 mmHg（毛细血管后性）","1 组需排除左心疾病、肺部疾病与 CTEPH 后（「三排除」）","TTE 筛查：估测肺动脉收缩压（PASP）升高、右室扩大与室间隔平直/D 形、三尖瓣环收缩期位移（TAPSE）降低","CTEPH 诊断：有效抗凝 ≥3 个月后 V/Q 扫描见多发节段性灌注缺损 + 右心导管 mPAP >20 mmHg + CTPA 或肺动脉造影见机化血栓","心肺运动试验、6 分钟步行距离（6MWD）与 WHO 功能分级用于严重度与疗效评估"],"workup":["TTE（筛查与评估右心功能）","右心导管 + 急性血管反应试验（吸入 NO 或伊洛前列素）：仅 1 组适用，阳性（mPAP 下降 ≥10 mmHg 至 ≤40 mmHg 且心输出量不减）提示可试用大剂量钙拮抗剂","V/Q 肺通气灌注扫描（CTEPH 最敏感，优于 CTPA）","CTPA、肺功能与动脉血气、睡眠监测（排除 3 组）","自身抗体谱（ANA、抗 Scl-70、抗着丝点、抗 U1RNP）与肝功能（门脉高压）","遗传咨询与 BMPR2 基因检测（1 组年轻患者与家族史者）","NT-proBNP、6MWD、WHO 功能分级（基线与随访）"],"grading":"WHO 功能分级（Ⅰ–Ⅳ，类似 NYHA）；风险分层（ESC/ERS 简化表，用 1 年预期死亡风险分低、中、低中、中高、高危）：主要指标 WHO 分级、6MWD、NT-proBNP、右房压与心指数。"},"ddx":[{"name":"血脂异常与动脉粥样硬化防治（dyslipidemia）","point":"与血脂异常的鉴别：肺高压以右心负荷与呼吸困难为主，右心导管 mPAP 升高；血脂异常本身不直接致肺高压（但可加重左心疾病）。"},{"name":"继发性高血压（secondary_htn）","point":"与继发性高血压的鉴别：肺高压不表现为系统血压升高，反可因右心输出量下降而血压偏低；两者在呼吸困难与晕厥上可重叠，需右心导管区分。"},{"name":"左心疾病相关肺高压（2 组）","point":"关键鉴别靠右心导管 PAWP：>15 mmHg 提示左心疾病；TTE 见左室扩大或舒张功能不全、LA 扩大。"},{"name":"慢性血栓栓塞性肺动脉高压（CTEPH，4 组）","point":"有急性肺栓塞史、V/Q 扫描见多发节段性灌注缺损，需评估 PEA 手术（可治愈）。"},{"name":"呼吸系统疾病相关（3 组）","point":"COPD 或 ILD 背景，肺功能见阻塞或限制性通气障碍与 DLCO 降低，右心导管通常 mPAP 轻中度升高。"},{"name":"左心衰与第 2 组肺高压的呼吸困难","point":"肺水肿表现、BNP 显著升高与左室射血分数降低或舒张功能不全，需超声鉴别。"}],"tx":{"drug":[{"name":"安立生坦（内皮素受体拮抗剂）","dose":"5 mg qd 口服，4 周后增至 10 mg qd（1 组 PAH 一线）","note":"需定期监测肝功能（转氨酶升高）与血红蛋白；妊娠期禁用（致畸，需双重避孕，REMS 类管理）","renal":"重度肾功能不全慎用","hepatic":"中度以上肝损害禁用或减量；肝硬化相关 PAH 慎用","interact":"与环孢素合用显著升高血药浓度（禁用）；与利福平合用降低疗效"},{"name":"波生坦","dose":"62.5 mg bid 起始（4 周），后 125 mg bid","note":"肝毒性较强（每月查肝功能），妊娠禁用","renal":"无需调整","hepatic":"避免用于中重度肝损害","interact":"CYP3A4 与 CYP2C9 诱导剂/抑制剂相互影响；降低激素类避孕药效果"},{"name":"西地那非 / 他达拉非（PDE5 抑制剂）","dose":"西地那非 20 mg tid；他达拉非 20–40 mg qd（改善 6MWD 与血流动力学）","note":"禁与硝酸酯类同用（可致严重低血压）；注意头痛、潮红与视觉异常（西地那非）","renal":"CrCl <30 西地那非减量","hepatic":"重度肝损害他达拉非避免使用","interact":"绝对禁忌与硝酸酯类、利奥西呱合用（低血压风险）"},{"name":"利奥西呱（sGC 激动剂）","dose":"0.5–1 mg tid 起始，每 2 周递增 0.5 mg，最大 2.5 mg tid","note":"适用于 1 组与 CTEPH 术后持续/残余肺高压；禁与 PDE5 抑制剂合用（严重低血压）","renal":"CrCl <30 慎用","hepatic":"重度肝损害禁用","interact":"禁与硝酸酯类、PDE5 抑制剂同用"},{"name":"曲前列尼尔（前列环素类似物，皮下/静脉）","dose":"皮下持续输注：1.25 ng/kg/min 起始，逐渐增至耐受剂量；静脉途径用于高危患者","note":"用于中高危与重症；皮下输注部位疼痛常见；不可突然停药（反跳可致肺高压危象）","renal":"无需调整","hepatic":"重度肝损害减量","interact":"与抗凝合用增加出血；与降压药合用加重低血压"},{"name":"伊洛前列素（吸入）","dose":"2.5–5 µg 吸入，每日 6–9 次","note":"起效快、半衰期短；可用于急性血管反应试验；需专用雾化装置","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"与降压药、抗凝合用需注意"},{"name":"钙拮抗剂（仅用于急性血管反应试验阳性者）","dose":"硝苯地平缓释 120–240 mg/d 或地尔硫卓 240–720 mg/d 或氨氯地平 20 mg/d（剂量远高于常规降压剂量）","note":"仅适用于试验阳性的 1 组患者（约占 10%）；未做试验或用阴性者禁用（可致严重低血压与右心衰）","renal":"无需调整","hepatic":"肝病者减量","interact":"与 β 阻滞剂合用可致心衰；与 CYP3A4 抑制剂合用升高浓度"}],"nonDrug":["长期氧疗：仅在静息或运动诱发低氧（PaO₂ <60 mmHg）时使用（3 组）","利尿剂：右心衰伴容量负荷过重时使用（袢利尿剂），需监测血容量与肾前性肾功损害","房间隔造口术：重症 PAH 反复晕厥的姑息治疗","肺移植 / 心肺移植：靶向治疗无效的 1 组重症患者","CTEPH：肺动脉血栓内膜剥脱术（PEA，唯一可治愈手段）；不能手术者用利奥西呱或 BPA（球囊肺动脉成形）","抗凝：IPAH 与 CTEPH 常规抗凝（华法林或 DOAC，CTEPH 推荐终身）"],"life":["避免妊娠（PAH 合并妊娠病死率高达 20%–30%，需严格避孕并讨论风险）","避免高原、剧烈运动与脱水；乘机时需评估氧合","避免使用非甾体抗炎药（加重水钠潴留与肾功能损害）","定期随访：每 3–6 个月评估 WHO 功能分级、6MWD、NT-proBNP 与超声","疫苗接种（流感、肺炎球菌、COVID-19）"]},"prog":"1 组 PAH 未治疗的中位生存约 2.8 年；靶向治疗后 5 年生存约 50%–70%。风险分层是治疗强度与随访频率的依据，低危者年病死率 <5%。CTEPH 手术（PEA）后 5 年生存 >80%。2 组肺高压预后取决于左心疾病，目前无靶向药获批。","refs":["《中国肺高血压诊断和治疗指南（2021）》（中华医学会心血管病学分会）","2022 ESC/ERS Guidelines for the Diagnosis and Treatment of Pulmonary Hypertension","2018 第六届世界肺高压研讨会（WSPH）临床分类更新","《中国肺动脉高压诊断与治疗指南（2021）》","2023 ESC/ERS Focused Update on Pulmonary Hypertension"]},{"id":"dyslipidemia","name":"血脂异常与动脉粥样硬化防治","aka":["Dyslipidemia","高脂血症","血脂异常"],"rank":2,"basic":{"define":"血浆中胆固醇、甘油三酯、低密度脂蛋白（LDL-C）或高密度脂蛋白（HDL-C）水平异常，是动脉粥样硬化性心血管病（ASCVD）最重要的可干预危险因素。","risk":["LDL-C 升高（因果关系最明确）","家族性高胆固醇血症（LDLR、APOB、PCSK9 基因突变）","饮食（饱和脂肪、反式脂肪、高糖）","肥胖、缺乏运动、吸烟、饮酒","糖尿病、甲状腺功能减退、肾病综合征、胆汁淤积","继发性：噻嗪类、β 阻滞剂、糖皮质激素、雌激素"],"epi":"我国成人血脂异常总体患病率约 40%，但知晓率、治疗率与控制率均低（治疗控制率不足 20%）。LDL-C 升高是 ASCVD 的致病性危险因素，降低 LDL-C 可线性降低事件风险。"},"patho":"LDL-C 进入血管内膜并被氧化修饰，巨噬细胞通过清道夫受体吞噬形成泡沫细胞（无负反馈调节），聚集形成脂纹与粥样斑块。斑块内脂质核心增大、纤维帽变薄（易损斑块）后破裂，暴露组织因子致血栓形成，引发急性冠脉综合征或卒中。HDL-C 参与胆固醇逆转运，但其升高并不必然降低事件（CETP 抑制剂研究失败），故不以 HDL-C 为主要干预靶点。他汀通过抑制 HMG-CoA 还原酶减少胆固醇合成并上调 LDL 受体，是降 LDL-C 的基石。","dx":{"criteria":["血脂水平（中国成人血脂异常防治指南）：TC ≥6.2 mmol/L、LDL-C ≥4.1 mmol/L、TG ≥2.3 mmol/L、HDL-C <1.0 mmol/L（任一异常即诊断）","危险分层（决定 LDL-C 目标）：","极高危：ASCVD（心梗、缺血性卒中、ACS、血运重建等）+ 糖尿病伴靶器官损害或 ≥3 项危险因素 + 严重 CKD（eGFR <30）→ LDL-C 目标 <1.4 mmol/L 且降幅 ≥50%","高危：LDL-C ≥4.9 mmol/L 或 TC ≥7.2 mmol/L；糖尿病（40 岁以上或有危险因素）；单项危险因素极重 → 目标 <1.8 mmol/L 且降幅 ≥50%","中危与低危：目标 <2.6 mmol/L 与 <3.4 mmol/L","家族性高胆固醇血症（FH）筛查：成人 LDL-C ≥4.9 mmol/L（未治疗）、早发 ASCVD 家族史、肌腱黄色瘤或角膜环；Dutch 标准或 Simon Broome 标准评分诊断，确诊靠基因"],"workup":["空腹血脂全套（TC、TG、LDL-C、HDL-C）与计算非 HDL-C（TC − HDL-C）","Lp(a)：升高（>50 mg/dL）为独立危险因素，早发 ASCVD 或家族史者建议检测","继发性原因筛查：TSH（甲减）、空腹血糖与 HbA1c、肝功能与尿蛋白（肾病综合征）、肾功能","ASCVD 风险评估（China-PAR 模型 10 年风险）","颈动脉超声（斑块负荷）与冠脉钙化积分（必要时）","FH 疑诊者做基因检测与家系筛查"],"grading":"按 LDL-C 水平与 ASCVD 风险分层（低危、中危、高危、极高危），目标值见诊断标准；他汀强度分：高强度（LDL-C 降幅 ≥50%，如阿托伐他汀 40–80 mg、瑞舒伐他汀 20–40 mg）、中等强度（30%–49%）、低强度（<30%）。"},"ddx":[{"name":"继发性高血压（secondary_htn）","point":"与继发性高血压的鉴别：血脂异常不直接引起血压升高，但常与代谢综合征共存；继发性高血压有明确的内分泌或肾血管病因（低血钾、肌酐升高、双侧肾大小不等）。"},{"name":"肺动脉高压（ph_group）","point":"与肺高压的鉴别：肺高压以右心负荷为主，血脂可正常；但慢性右心衰继发肝功能受损可致血脂降低（而非升高）。"},{"name":"甲状腺功能减退（thy_hypo）","point":"甲减常伴继发性高胆固醇血症，TSH 升高可确诊；单纯降脂治疗前应先纠正甲减。"},{"name":"肾病综合征（gn_ns）","point":"大量蛋白尿、低白蛋白血症与水肿，伴明显高脂血症（肝脏代偿合成增加），需治疗原发病。"},{"name":"家族性高胆固醇血症","point":"LDL-C 显著升高（常 >4.9 mmol/L）、肌腱黄色瘤、早发 ASCVD 家族史，常规他汀难以达标。"},{"name":"家族性高甘油三酯血症","point":"TG 显著升高（>5.6 mmol/L）伴胰腺炎风险，HDL-C 降低，需排除饮食与酒精因素。"}],"tx":{"drug":[{"name":"阿托伐他汀（高强度他汀）","dose":"40–80 mg qn 口服；中等强度 10–20 mg qn","note":"LDL-C 降幅约 50%（80 mg）；需查基线肝功与肌酸激酶，用药 4–12 周复查血脂与肝功能；肌肉症状需评估","renal":"CrCl <30 慎用大剂量","hepatic":"活动性肝病禁用；转氨酶 >3 倍上限需评估（无症状者可监测）","interact":"与 CYP3A4 抑制剂（大环内酯、唑类抗真菌药、胺碘酮、维拉帕米、葡萄柚）合用增加肌病风险；与贝特类、环孢素合用增加肌毒性"},{"name":"瑞舒伐他汀","dose":"10–20 mg qn（高强度可达 20–40 mg）","note":"以肾脏排泄为主，与其他他汀类药物代谢途径不同；蛋白尿（可逆）与肌病风险与剂量相关","renal":"CrCl <30 起始 5 mg，不超过 10 mg","hepatic":"活动性肝病禁用","interact":"与环孢素合用禁忌；与吉非贝齐合用显著增加肌病（避免联合）"},{"name":"依折麦布（胆固醇吸收抑制剂）","dose":"10 mg qd","note":"他汀基础上可再降 LDL-C 约 20%；常与中等强度他汀联用以达到高强度降脂效果；不良反应少","renal":"无需调整","hepatic":"重度肝损害不推荐","interact":"与贝特类合用增加胆囊疾病风险"},{"name":"PCSK9 抑制剂（依洛尤单抗 / 阿利西尤单抗）","dose":"依洛尤单抗 140 mg q2w 或 420 mg 每月一次皮下；阿利西尤单抗 75 mg q2w（可增至 150 mg q2w）","note":"可再降 LDL-C 约 50%–60%；用于 FH、他汀不耐受或仍不达标的极高危患者；注射部位反应常见","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"无显著 CYP 相互作用"},{"name":"非诺贝特（高 TG 与混合型血脂异常）","dose":"160 mg qd（微粒化 145 mg qd），餐后服用","note":"TG ≥5.6 mmol/L 时优先降 TG 以防胰腺炎；与他汀联合需谨慎并监测肌酶","renal":"CrCl <50 减量，<30 禁用","hepatic":"肝病与胆囊疾病者禁用","interact":"与他汀合用增加肌病风险；增强华法林抗凝作用"},{"name":"高纯度 ω-3 脂肪酸（二十碳五烯酸乙酯）","dose":"2 g bid（4 g/d）随餐口服","note":"可降低 TG 约 20%–30%；用于严重高 TG 或他汀治疗后残余风险；注意房颤风险（高剂量）","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝合用轻度增加出血风险"},{"name":"英克司兰（ siRNA 类 PCSK9 抑制剂）","dose":"284 mg 皮下注射第 1 天、第 3 个月，之后每 6 个月一次","note":"半年一次给药的依从性优势；适用于 ASCVD 或 FH 需大幅降 LDL-C 者（遵说明书）","renal":"无需调整","hepatic":"重度肝损害资料有限","interact":"无显著 CYP 相互作用"}],"nonDrug":["治疗性生活方式改变：限制饱和脂肪（<总热量 7%）与反式脂肪，增加膳食纤维与植物固醇；有氧运动（每周 ≥150 分钟）","减重（目标 BMI <24 kg/m²）与戒烟限酒","高血压与糖尿病的综合管理（协同降低 ASCVD 风险）","脂蛋白血浆置换：仅用于严重 FH（LDL-C 极高且药物无法控制）","家族性高胆固醇血症的家系筛查（级联筛查可早期识别携带者）"],"life":["用药后 4–12 周复查血脂；达标且稳定者每 3–6 个月复查","坚持长期用药（他汀获益随时间累积，停药致 LDL-C 反弹与风险回升）","肌肉症状（肌痛、乏力）与深色尿需及时就医（排除横纹肌溶解）","育龄女性：他汀类在妊娠期禁用，计划妊娠前需与医生讨论","合并脂肪肝者需区分是他汀的肝酶波动还是真正肝病（ALT >3 倍上限 + 胆红素升高需停药评估）"]},"prog":"LDL-C 每降低 1 mmol/L，主要心血管事件相对风险降低约 22%。极高危患者达标后仍存在残余风险（来自 TG、Lp(a) 与炎症），需综合管理。他汀不耐受者通过换用不同他汀或非他汀药物大多可达到靶目标。FH 患者需终身强化治疗，未治疗者早发 ASCVD 风险极高。","refs":["《中国血脂管理指南（2023 年）》（中国血脂管理指南修订联合专家委员会）","2019 ESC/EAS Guidelines for the Management of Dyslipidaemias","2018 AHA/ACC Multisociety Guideline on the Management of Blood Cholesterol","《家族性高胆固醇血症筛查与诊治中国专家共识》（2023）","《中国心血管病一级预防指南》（2020）"]},{"id":"secondary_htn","name":"继发性高血压","aka":["Secondary Hypertension","继发性高血压筛查"],"rank":3,"basic":{"define":"有明确病因可查的高血压，约占全部高血压的 5%–10%（在难治性高血压中可达 20%–30%）。常见病因包括肾实质性、肾血管性、内分泌性（原醛、嗜铬细胞瘤、库欣）与睡眠呼吸暂停。","risk":["年龄 <30 岁或 >55 岁新发高血压","血压顽固难控（≥3 种药含利尿剂仍不达标）","伴低血钾、代谢性碱中毒（提示原醛）","伴阵发性头痛、心悸、大汗（嗜铬细胞瘤）","肌酐升高或双肾大小差异 >1.5 cm（肾血管性）","伴向心性肥胖、紫纹（库欣）","打鼾、日间嗜睡与肥胖（OSA）"],"epi":"原醛在高血压人群中约占 5%–10%（难治性高血压中约 20%）；肾血管性约占 1%–5%；嗜铬细胞瘤约 0.1%–0.6%；OSA 在高血压人群中约 30%–50%。"},"patho":"肾实质性：肾单位减少致水钠潴留与 RAAS 激活。肾血管性：肾动脉狭窄致肾灌注压下降、肾素释放增加（肾素依赖性）。原醛：肾上腺腺瘤或双侧增生致醛固酮自主分泌，钠潴留与钾排泄增加（容量依赖 + 低肾素）。嗜铬细胞瘤：儿茶酚胺阵发性释放致血管收缩与心率增快。库欣：糖皮质激素过量致盐皮质激素受体激活。OSA：反复低氧激活交感神经与 RAAS，致夜间血压不降。","dx":{"criteria":["原醛筛查：醛固酮/肾素比值（ARR）——血浆醛固酮（ng/dL）/血浆肾素活性（ng/mL/h）>20–30 且醛固酮 >15 ng/dL 为初筛阳性；筛查前需纠正低钾并停用干扰药物（螺内酯 4 周、ACEI/ARB 2 周）","原醛确诊：盐水负荷试验（4 小时内输注 2 L 生理盐水后醛固酮 >10 ng/dL）、卡托普利试验或氟氢可的松试验阳性；确诊后行肾上腺 CT + 肾上腺静脉采血（AVS）分侧","肾血管性：肾动脉超声（收缩期峰值流速 >180 cm/s）、CTA/MRA 或肾动脉造影；卡托普利肾图","嗜铬细胞瘤：24 小时尿甲氧基肾上腺素（MN）与去甲氧基肾上腺素（NMN）或血浆游离 MN 检测；确诊后 CT/MRI 定位，必要时 MIBG 或 DOTATATE PET","库欣：24 小时尿游离皮质醇、午夜唾液皮质醇、1 mg 过夜地塞米松抑制试验；确诊后 ACTH 与垂体 MRI/肾上腺 CT","OSA：多导睡眠监测（AHI ≥5 伴症状或 AHI ≥15）"],"workup":["详细的病史（发病年龄、家族史、用药史含甘草与避孕药、打鼾、阵发症状）与体格检查（双上肢血压、腹部血管杂音、紫纹、满月脸）","基础：血钾、血钠、肌酐、eGFR、尿常规与尿蛋白、血气（碱中毒）","内分泌筛查：ARR（原醛首选）、24 小时尿 MN/NMN、皮质醇节律","影像：肾脏与肾上腺 CT、肾动脉 CTA/MRA、垂体 MRI","睡眠监测（疑 OSA）","难治性高血压者行 24 小时动态血压（排除白大衣效应与依从性问题）"],"grading":"按病因分为肾实质性、肾血管性、内分泌性（原醛、嗜铬、库欣、甲状腺疾病）、OSA、药物性与其他（主动脉缩窄、颅内病变）。"},"ddx":[{"name":"血脂异常与动脉粥样硬化防治（dyslipidemia）","point":"与血脂异常的鉴别：血脂异常不直接引起血压升高，但常与代谢综合征并存；继发性高血压有明确的内分泌或肾血管病因与特定生化异常。"},{"name":"肺动脉高压（ph_group）","point":"与肺高压的鉴别：肺高压不表现为系统血压升高，反可因右心输出量下降而低血压；两者可在呼吸困难与晕厥上重叠，需右心导管区分。"},{"name":"原发性高血压","point":"无明确病因、多在中年起病、家族史明显、对常规降压药反应好且无低钾与代谢性碱中毒；继发性高血压常年轻起病、顽固难控伴低钾。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"低血钾 + 代谢性碱中毒 + ARR 升高；肾上腺 CT 见腺瘤或增生，AVS 分侧确诊。"},{"name":"嗜铬细胞瘤（ad_pheo）","point":"阵发性头痛、心悸、大汗三联征，尿 MN/NMN 升高，影像见肾上腺或副神经节肿块。"},{"name":"肾血管性高血压","point":"肌酐升高、双侧肾脏大小差异、腹部血管杂音；肾动脉 CTA 见狭窄。年轻女性需考虑肌纤维发育不良，老年人多为动脉粥样硬化。"},{"name":"库欣综合征（ad_cushing）","point":"向心性肥胖、紫纹、满月脸、血糖升高；皮质醇节律异常与地塞米松抑制试验阳性。"}],"tx":{"drug":[{"name":"螺内酯（原醛，术前或不能手术）","dose":"起始 20–40 mg qd，可增至 100–200 mg/d 分次","note":"醛固酮受体拮抗剂，为双侧增生或不能手术者的一线；注意男性乳房发育（可换依普利酮 25–50 mg bid）","renal":"eGFR <30 慎用；监测血钾（尤其联用 ACEI/ARB）","hepatic":"肝病者慎用","interact":"与 ACEI/ARB、补钾剂合用致高钾；与地高辛合用升高其浓度"},{"name":"依普利酮","dose":"25 mg bid 起始，可增至 50 mg bid","note":"选择性醛固酮受体拮抗剂，抗雄激素副作用少；价格较高","renal":"CrCl <50 慎用；<30 避免","hepatic":"肝病者慎用","interact":"同螺内酯"},{"name":"酚苄明（嗜铬细胞瘤术前准备）","dose":"10 mg bid 起始，每 2–4 天递增 10 mg，至控制血压与症状（常用 20–40 mg bid–tid），术前 10–14 天开始","note":"必须先用 α 阻滞剂，再用 β 阻滞剂（反向会致血压危象）；注意体位性低血压与反射性心动过速","renal":"无需调整","hepatic":"肝病者减量","interact":"与 β 阻滞剂合用需 α 先用；与三环类抗抑郁药合用可致严重高血压"},{"name":"美托洛尔（嗜铬细胞瘤心率控制，α 阻滞后）","dose":"25–50 mg bid","note":"仅在 α 阻滞剂充分起效后使用；单独使用可致血压危象","renal":"无需调整","hepatic":"肝病减量","interact":"与维拉帕米合用可致传导阻滞"},{"name":"硝苯地平 / 氨氯地平（肾血管性高血压与常规联合）","dose":"硝苯地平缓释 30–60 mg qd；氨氯地平 5–10 mg qd","note":"对肾血管性高血压有效；可与 ACEI/ARB 联用","renal":"无需调整","hepatic":"肝病者减量","interact":"与 CYP3A4 抑制剂合用升高浓度"},{"name":"ACEI / ARB（单侧肾动脉狭窄）","dose":"依那普利 5–20 mg/d 或缬沙坦 80–320 mg/d","note":"单侧狭窄可用（有保护作用）；双侧狭窄或孤立肾动脉狭窄禁用（可致急性肾衰）","renal":"监测肌酐（升高 >30% 需评估）；双侧狭窄禁用","hepatic":"重度肝病慎用","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低降压效果并增加肾损伤"},{"name":"库欣综合征治疗","dose":"手术切除为首选；不能手术者用美替拉酮 250 mg tid 起始（按皮质醇滴定）、酮康唑 200–600 mg/d 或米托坦","note":"需内分泌专科主导；术后需激素替代与随访","renal":"遵说明书","hepatic":"酮康唑肝毒性需监测","interact":"酮康唑抑制 CYP3A4 作用广泛（他汀、苯二氮卓、华法林等）"}],"nonDrug":["原醛腺瘤：腹腔镜肾上腺切除（术前螺内酯准备），术后 1 年约 50%–80% 高血压缓解","嗜铬细胞瘤：手术切除（术前 α 阻滞 ≥10–14 天，容量扩充）；不能手术者长期 α 阻滞","肾血管性：球囊扩张/支架（纤维肌发育不良效果好）；动脉粥样硬化性者需权衡（ASTRAL 研究提示获益有限）","库欣：经蝶垂体手术（垂体瘤）或肾上腺切除","OSA：持续正压通气（CPAP）是核心治疗，减重可显著改善"],"life":["肾上腺术后需激素替代（单侧切除后约 1%–2% 出现永久性肾上腺功能不全）","嗜铬细胞瘤：术后随访 5–10 年（复发率约 5%–10%，部分为遗传性）","限盐（<5 g/d）、减重、运动与限酒","避免突然停用降压药（尤其 β 阻滞剂与可乐定，可致反跳性高血压）","遗传性嗜铬细胞瘤（MEN2、VHL、SDHx 突变）需家系筛查"]},"prog":"原醛经手术或螺内酯治疗后心血管并发症显著改善（早期识别可逆转）；嗜铬细胞瘤手术治愈率约 90%，恶性者预后差；肾血管性高血压的预后取决于原发病与血运重建效果；库欣未经治疗者心血管病死率显著升高（手术缓解后仍高于常人）；OSA 经 CPAP 治疗可改善血压与心血管风险。","refs":["《中国继发性高血压筛查与诊治专家共识》（中华医学会心血管病学分会，2023）","2016 Endocrine Society Clinical Practice Guideline: Primary Aldosteronism","2014 Endocrine Society Guideline: Pheochromocytoma and Paraganglioma","2020 International Consensus on Primary Aldosteronism (PACT)","《中国高血压防治指南（2024 年修订版）》"]},{"id":"cardiac_neurosis","name":"心脏神经症与双心医学","aka":["Cardiac Neurosis","Da Costa 综合征","焦虑性心脏症状","双心医学"],"rank":4,"basic":{"define":"以心悸、胸闷、胸痛、气短、乏力等心血管系统症状为主诉，伴明显的焦虑或躯体化倾向，但心血管系统检查无足以解释症状的器质性异常的一类功能性障碍。是「双心医学」（心理-心脏病学）的核心对象。","risk":["青年与中年（20–40 岁），女性多见","焦虑障碍、抑郁障碍、躯体形式障碍","A 型性格、完美主义、职业压力","疑病倾向与过度健康关注","生活事件刺激（丧亲、工作变动）","咖啡因、酒精、尼古丁滥用"],"epi":"在心内科门诊中，以胸痛或心悸就诊而最终无器质性病因者约占 20%–40%；惊恐障碍人群中心血管症状发生率极高，是急诊胸痛的重要「非心源性」原因。"},"patho":"核心是自主神经功能失衡（交感神经张力增高）与痛觉中枢敏化：焦虑激活下丘脑-垂体-肾上腺轴与交感神经，致心率增快、血压波动与心肌氧耗上升，患者能感知到正常或轻微的心搏增强；同时焦虑降低内感受阈值（内感受性过敏），使心肺感受器信号被放大为「心脏危险」的认知。抑郁与焦虑也是冠心病不良预后的独立危险因素（经炎症、血小板活性与依从性下降介导），故双心问题不只是「症状」，也影响预后。","dx":{"criteria":["症状特征：心悸（可伴心跳重、停搏感）、胸痛（局限性、针刺样、数秒或数小时、与劳力无明确关系、休息或转移注意力可缓解）、气短（叹息样呼吸、不能深吸气感）、乏力、头晕、出汗、手足发凉","必须有器质性心脏病评估已充分排除至少一次：静息与必要时运动心电图、心动超声、心肌标志物（急性症状）","伴焦虑或抑郁量表阳性：GAD-7 ≥5 或 PHQ-9 ≥5；必要时心理科评估","症状与情绪、压力、睡眠相关，且不能用器质性疾病解释","注意「双心」双向：既可为纯功能性，也可在有器质性心脏病背景上叠加焦虑抑郁（如心梗后焦虑）"],"workup":["详细病史与症状日记（诱因、持续时间、缓解方式、与活动的关系）","静息心电图、必要时运动试验或 24 小时动态心电图（有条件可加事件记录器）","心脏超声（结构与功能）","hs-cTn（如以胸痛为主，至少一次急诊评估排除 ACS）","甲状腺功能、血常规、血糖（排除甲亢与贫血等拟似病因）","心理量表：GAD-7、PHQ-9；必要时心理科会诊"],"grading":"按主要表现分：心脏-血管型（心悸、心前区不适、血压波动）、神经-呼吸型（气短、叹息样）、运动-感觉型（乏力、头晕）与混合型。心理层面按 GAD-7/PHQ-9 分轻中重度。"},"ddx":[{"name":"继发性高血压（secondary_htn）","point":"与继发性高血压的鉴别：内分泌性高血压（嗜铬细胞瘤）可有阵发性心悸、出汗与血压骤升，但发作时血压显著升高、尿 MN/NMN 阳性；心脏神经症的血压波动多在正常范围且与情绪对应。"},{"name":"肺动脉高压（ph_group）","point":"与肺高压的鉴别：肺高压有明确的血流动力学异常（mPAP 升高）与右心负荷表现；心脏神经症患者超声与右心导管均正常。"},{"name":"血脂异常与动脉粥样硬化（dyslipidemia）","point":"血脂异常本身不产生症状；需避免仅因血脂轻度异常而将功能性症状归为「冠心病」。"},{"name":"冠心病","point":"症状与劳力明确相关、持续 3–5 分钟、含服硝酸甘油缓解，有典型心电图与影像学缺血证据；功能性者症状与情绪相关性更强且检查阴性。"},{"name":"心律失常","point":"动态心电图见明确的心律失常（如房颤、室早负荷高、室上速），且症状与心律失常发作同步。"},{"name":"甲状腺功能亢进","point":"心率快、手抖、体重下降、TSH 降低与 FT4 升高。"},{"name":"惊恐发作","point":"发作性强烈恐惧伴濒死感、心悸、出汗、过度换气，通常 10–20 分钟达峰；心脏神经症更偏向持续性主诉与健康担忧。"}],"tx":{"drug":[{"name":"β 阻滞剂（美托洛尔缓释 / 比索洛尔）","dose":"美托洛尔缓释 23.75–47.5 mg qd 或比索洛尔 2.5 mg qd，常用于心悸突出者","note":"可缓解心悸的躯体感知，但需注意可诱发抑郁情绪与疲乏；不应无限期使用，需与心理治疗同步；心动过缓与传导阻滞者禁用","renal":"无需调整","hepatic":"肝病者减量","interact":"与维拉帕米、地尔硫卓合用增加传导阻滞与心衰风险；可掩盖低血糖"},{"name":"SSRI（舍曲林 / 帕罗西汀 / 艾司西酞普兰）","dose":"舍曲林 25–50 mg 起始，4 周后增至 50–200 mg qd；艾司西酞普兰 5–10 mg qd（老年人 5 mg）","note":"合并焦虑障碍或抑郁障碍的一线；起效需 2–4 周，需足疗程（6–12 个月）；初期可能出现焦虑加重（需向患者说明）","renal":"重度肾功能不全减量（帕罗西汀尤需）","hepatic":"肝病者减量","interact":"与曲马多、曲普坦、MAO 抑制剂合用警惕 5-HT 综合征；与抗凝合用增加出血风险；氟西汀与帕罗西汀强抑制 CYP2D6（影响美托洛尔、他莫昔芬）"},{"name":"坦度螺酮（轻度焦虑）","dose":"10 mg tid 口服，可增至 30–60 mg/d","note":"5-HT1A 受体部分激动剂，依赖性与镇静风险低；用于轻中度焦虑","renal":"严重肾功不全慎用","hepatic":"肝病者减量","interact":"与其他 5-HT 类药物合用注意 5-HT 综合征"},{"name":"曲唑酮（改善睡眠）","dose":"25–50 mg qn 睡前，可增至 100 mg","note":"改善睡眠而较少抗胆碱作用；注意体位性低血压与晨间嗜睡","renal":"慎用","hepatic":"肝病者减量","interact":"与 SSRI 合用增加 5-HT 综合征风险；与抗凝合用增加出血"}],"nonDrug":["心理教育与解释：向患者明确「检查已排除器质性心脏病」，解释症状机制（自主神经与内感受敏化），减轻灾难化认知","认知行为治疗（CBT）：证据最强，对心悸相关焦虑与惊恐有效","呼吸训练与放松技巧：缓慢腹式呼吸（每分钟 6 次）可改善气短与过度换气","规律有氧运动：改善自主神经平衡，证据支持对焦虑与功能性症状均有效","限制咖啡因、酒精与尼古丁；规律作息与睡眠卫生","正念减压与生物反馈：可作为辅助"],"life":["避免反复无指征的检查（过度检查强化疾病信念，形成医源性循环）","建立固定随访关系与明确的复诊计划（减少反复急诊就诊）","筛查共病抑郁与焦虑，必要时转心理科/精神科","劳逸结合与压力管理，识别职业与家庭压力源","运动处方（每周至少 150 分钟中等强度）作为长期策略"]},"prog":"多数患者通过心理教育、认知行为治疗与规律运动症状显著改善，预后良好。但若不识别与处理，容易长期反复就诊、过度检查与功能损害（约 30% 长期存在症状）。合并器质性心脏病的「双心」患者，焦虑抑郁未处理会显著增加心血管事件与死亡风险。","refs":["《在心血管科就诊患者心理处方中国专家共识（2020 年版）》（中华医学会心血管病学分会）","《双心疾病诊疗专家共识》（中国康复医学会心血管病专业委员会）","2020 ESC Position Paper on Mental Health and Cardiovascular Disease (ESC Prevention of CVD Programme)","《中国焦虑障碍防治指南（第二版）》","2019 AHA Scientific Statement: Psychological Health and Cardiovascular Risk"]}]},{"id":"arrhythmia_atrial","name":"房性心律失常","rank":13,"summary":"房性期前收缩多数无需药物，重点在排除器质性病变与诱因，只有症状明显、触发房速/房颤或伴高危基础病时才考虑抗心律失常药；房性心动过速与房扑（含 1:1 或 2:1 传导）的关键鉴别靠 P 波形态与有无等电位线，维拉帕米、普罗帕酮用于无结构性心脏病者，折返性者射频消融可根治。","compare":[{"diseaseId":"ar_pac","dx":"提前出现的 P' 波，P'-P 间期短于基本窦性周期，QRS 形态多与窦性相同，代偿间歇多不完全","key":"孤立或少量早搏、无持续心动过速，以去除诱因与评估基础心脏病为主"},{"diseaseId":"ar_at","dx":"连续 ≥3 个室上性早搏、心率 100–250 次/分，P 波形态与窦性不同，突发突止","key":"持续发作需与房扑、房颤鉴别；迷走刺激有效提示折返性，房速多不受影响"}],"diseases":[{"id":"ar_pac","name":"房性期前收缩","aka":["房性早搏","Premature Atrial Complex","PAC","房早"],"rank":1,"basic":{"define":"起源于窦房结以外心房任何部位的提前搏动，是最常见的期前收缩类型之一。按频率与分布分为偶发、频发（>100 次/24 h 或 >5 次/分）、二联律/三联律、成对以及多源房早。","risk":["精神紧张、焦虑与睡眠不足","咖啡、浓茶、酒精与吸烟","甲状腺功能亢进","低钾、低镁血症","冠心病、高血压性心脏病、心衰与心肌病","左房扩大（二尖瓣病变、肥厚型心肌病）","洋地黄过量、茶碱与拟交感药物"],"epi":"健康成人 24 小时动态心电图检出率极高，随年龄增长而升高，60 岁以上可达 70% 以上；多数为偶发且无临床意义。频发房早是房颤发生的独立预测因子，可视为心房电重构与结构重构的早期标记。"},"patho":"心房内存在异位起搏灶或触发性活动（早期/延迟后除极）或微折返，提前发放激动并在心房内扩布。房早后常伴窦房结重整，故代偿间歇多不完全。频发房早可驱动心房电重构（动作电位时程缩短、细胞钙处理异常）与结构重构（纤维化），逐步形成房颤基质；若伴室内差异性传导，可表现为宽 QRS，需与室早鉴别。","dx":{"criteria":["提前出现的 P' 波，形态不同于窦性 P 波（肢体导联 II、V1 最易识别）","P'-R 间期正常或略延长；如 P' 埋在 T 波后，原 T 波形态可变化","QRS 波群多与窦性相同（窄）；伴室内差异性传导时宽大畸形，多为右束支阻滞图形","代偿间歇多不完全（异位激动侵入并重整窦房结）","与室性早搏鉴别：房早有提前 P' 波、QRS 窄、代偿间歇多不完全；室早无 P' 波、QRS 宽大畸形、代偿完全","频发标准：>5 次/分、成对、二联律或多源者视为频发，需进一步评估"],"workup":["常规 12 导联心电图（P' 波形态定位来源：高位右房接近窦性，低位右房/冠状静脉窦呈负向 P）","24 小时动态心电图：总计数、分布节律、是否成对或短阵房速","甲状腺功能、电解质（钾、镁）与血常规","超声心动图：左房大小、左室肥厚、瓣膜病变、心功能","有冠心病高危因素者行负荷试验或冠脉评估"],"grading":"房早 Lown 分级：0 级无房早；1 级偶发；2 级频发（>30 次/小时或成对）；3 级多源；4 级成对或短阵房速；5 级房早诱发房颤/房速。"},"ddx":[{"name":"房性心动过速（ar_at）","point":"与本类 ar_at 鉴别：房早为单个提前搏动后恢复窦性节律；房速为连续 ≥3 个房性异位搏动、心率 >100 次/分，形成持续性心动过速。"},{"name":"窦性心律不齐","point":"P 波形态与窦性一致，心率随呼吸周期性变化，无提前出现的 P' 波。"},{"name":"房室交界性期前收缩","point":"P' 波逆行（II、III、aVF 倒置）且常位于 QRS 之后或与之重叠，代偿间歇多完全。"},{"name":"室性期前收缩伴逆行传导","point":"QRS 宽大畸形、代偿间歇完全，逆行 P 多见于 ST-T 段。"},{"name":"T 波或 U 波重叠造成的伪像","point":"对比同一患者多次心电图，观察 T 波形态变化；必要时改变体位复查。"}],"tx":{"drug":[{"name":"无药物治疗（首选）","dose":"偶发、无症状者不推荐抗心律失常药物；去除诱因后复查动态心电图","note":"避免滥用抗心律失常药，尤其伴结构性心脏病者，药物致心律失常风险高于房早本身","renal":"不适用","hepatic":"不适用","interact":"不适用"},{"name":"美托洛尔","dose":"缓释片 23.75–47.5 mg qd，或普通片 25 mg bid，按症状与心率调整","note":"有症状、与心动过速或交感兴奋相关者首选；心率控制在 60–80 次/分即可，不必强求房早消失","renal":"重度肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用可致心动过缓与负性肌力；CYP2D6 抑制剂升高其浓度"},{"name":"普罗帕酮","dose":"150 mg tid，最大 200 mg tid","note":"仅限无结构性心脏病者；心梗史、LVEF <40%、QRS 增宽或 Brugada 波形者禁用","renal":"重度肾功能不全减量","hepatic":"肝功能不全减量","interact":"可升高地高辛与华法林浓度"},{"name":"参松养心胶囊（中成药）","dose":"2–4 粒 tid","note":"部分研究显示可减少房早负荷，可用于症状性患者作为辅助","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["射频导管消融：适用于症状明显、药物无效、频发房早伴心房肌病、房早触发房颤或房速者；术前需三维标测定位异位灶","治疗基础病：甲亢、低钾、贫血、心衰与瓣膜病","停用或调整引起房早的药物（洋地黄、茶碱、β 激动剂）","频发房早者定期动态心电图筛查房颤"],"life":["限制或戒除咖啡因与酒精，戒烟","保证睡眠、减轻精神压力","定期复查动态心电图与超声（尤其左房结构与功能）","合并结构性心脏病者按基础病方案管理，无需长期抗凝"]},"prog":"健康人群中的偶发房早预后良好，一般不影响寿命与心功能。需要警惕的是频发与多源房早：可发展为心房肌病，左房明显增大者进展为房颤的风险增加，并间接触及卒中风险。冠心病与心衰患者出现频发房早提示整体心血管风险升高，应以处理基础病为主。","refs":["《心律失常诊断与治疗中国专家共识》2020","《室上性心动过速基层诊疗指南（2019 年）》","《心房颤动：目前的认识和治疗建议（2021）》","2021 ESC Guidelines for the diagnosis and clinical management of atrial fibrillation"]},{"id":"ar_at","name":"房性心动过速","aka":["Atrial Tachycardia","AT","房速","房扑样房速"],"rank":2,"basic":{"define":"起源于心房（窦房结以外）的异位激动持续快速发放，表现为心率 >100 次/分、P 波形态不同于窦性、连续 ≥3 个室上性早搏的心律失常。按机制分为局灶性（自律性、触发、微折返）与大折返性（房扑、不典型房扑、消融瘢痕相关）；按临床分为阵发性、持续性、无休止性与多源性。","risk":["心房扩大与心房纤维化（高血压、瓣膜病、心衰、扩张型/肥厚型心肌病）","房颤消融或心脏外科术后（切口/瘢痕相关大折返）","洋地黄中毒（多源性房速的经典原因）","电解质紊乱与缺氧、慢性肺病","甲状腺功能亢进","年龄与遗传易感性"],"epi":"占室上性心动过速的 5%–15%，各年龄段均可发生，成人中多见于女性；无休止性房速在儿童中更多见，可导致心动过速性心肌病。导管消融时代，房速是房颤消融术后最常见的复发心律失常之一，术后早期发生率可达 10%–20%。"},"patho":"局灶性房速由心房局部自律性增强、触发性活动（延迟后除极、洋地黄介导）或微折返所致，小范围心肌即可形成起搏点；大折返性房速依赖心房内固定解剖或瘢痕屏障形成的巨大折返环路，常累及三尖瓣环峡部或左房前壁/顶部/二尖瓣峡部。持续心动过速可致负性肌力，从而造成心动过速性心肌病；伴心房肌病时，长病程可演变为心房颤动。","dx":{"criteria":["**房速**：心率 100–250 次/分，P 波形态与窦性不同（V1 直立提示左房起源、倒置提示右房），P-P 间期规则，可伴房室文氏传导（心房率快而心室率不规则）","**与窦性心动过速**：窦速时 P 波形态正常，起始与终止均渐变；房速突发突止，P 波形态畸形","**与房扑鉴别**：典型房扑呈锯齿状 F 波（II、III、aVF 倒置，频率 250–350 次/分），无等电位线，房室传导多为 2:1–4:1；房速 P 波间有等电位线，房率多 <250 次/分（缓慢房扑不能仅凭房率区分，需电生理确认折返机制）","**与房室折返性心动过速（AVRT）/房室结折返性心动过速（AVNRT）**：迷走刺激（颈动脉窦按摩、Valsalva）可终止 AVNRT/AVRT，房速多不受影响或仅出现房室阻滞而房率不变","**与心房颤动**：房速 P 波可辨认、节律规则或规则的不规则；房颤无 P 波、RR 绝对不齐","**多源性房速**：≥3 种不同形态 P 波、P-P 与 P-R 间期均多变，常见于 COPD 急性加重与缺氧"],"workup":["12 导联心电图（P 波形态定位，必要时加深 P 波导联）","24 小时动态心电图：评估总负荷与有无心动过速性心肌病","食管心房调搏：观察终止方式与诱发特点","电生理检查：三维标测（Carto/EnSite）确定起源与机制，为消融准备","超声心动图：心房大小、心室功能、有无结构性心脏病","甲状腺功能、电解质、地高辛浓度（疑中毒时）","COPD 患者查血气（尤其多源性房速）"],"grading":"按机制分：局灶性（自律性、触发、微折返）与大折返性（典型/不典型房扑、切口性房速、消融瘢痕相关）；按病程分：阵发性（<7 天）、持续性（7 天至 6 个月）、无休止性（>6 个月或无法终止）；同时描述房室传导比例（如 2:1）。"},"ddx":[{"name":"房性期前收缩（ar_pac）","point":"与本类 ar_pac 鉴别：房早为单个提前搏动后恢复窦性节律；房速为连续 ≥3 个房性异位搏动、心率 >100 次/分的持续性节律。"},{"name":"心房扑动","point":"房扑呈锯齿状 F 波、无等电位线、房率 250–350 次/分，2:1 传导致心室率多为 150 次/分；房速 P 波之间有等电位线，房率多在 100–250 次/分。"},{"name":"心房颤动","point":"房颤无 P 波、RR 间期绝对不齐；房速节律规则或呈固定比例传导。"},{"name":"窦性心动过速","point":"P 波为正常窦性形态，有渐起的诱因（发热、失血、甲亢、运动）；房速突发突止，P 波形态改变。"},{"name":"房室结折返性/房室折返性心动过速","point":"P 波多埋于 QRS 内或位于 QRS 之后，可被迷走刺激终止；房速不被终止。"},{"name":"多源性房速与房颤","point":"多源性房速可有规则节律、≥3 种 P 波形态；房颤无清晰 P 波。"}],"tx":{"drug":[{"name":"维拉帕米","dose":"静脉 5 mg 加 5% 葡萄糖 20 ml 缓慢静推，必要时 15 分钟后重复 5 mg；口服缓释片 120–240 mg qd","note":"阻断房室结与触发活动，局灶性房速有效；预激合并房速、宽 QRS 无法排除室速、心衰或 LVEF 低者禁用","renal":"肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与 β 阻滞剂合用致严重传导阻滞；升高地高辛浓度"},{"name":"普罗帕酮","dose":"静脉 1–2 mg/kg 缓慢推注（>10 分钟）；口服 150 mg tid，可增至 200 mg tid","note":"终止局灶性房速有效；无结构性心脏病者适用，结构性心脏病、心梗后、LVEF <40% 禁用","renal":"重度肾功能不全减量","hepatic":"肝功能不全减量","interact":"禁与索他洛尔、胺碘酮联用"},{"name":"美托洛尔","dose":"静脉 2.5–5 mg 缓慢推注，可重复至总量 10–15 mg；口服缓释片 47.5–95 mg qd","note":"控制心室率、抑制触发性房速；对持续性房速多仅减慢心室率","renal":"重度肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用致传导阻滞"},{"name":"地尔硫䓬","dose":"静脉 0.25 mg/kg 缓慢静推（2 分钟），必要时 0.35 mg/kg 追加；口服缓释 90–180 mg qd","note":"作用类似维拉帕米，用于房速终止与心室率控制","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 β 阻滞剂同用致心动过缓与低血压"},{"name":"胺碘酮","dose":"负荷 150 mg 静滴 10 分钟，随后 1 mg/min 维持 6 小时、0.5 mg/min 维持 18 小时；口服维持 200 mg qd","note":"难治性、反复发作或合并器质性心脏病者的三线选择","renal":"无需调整","hepatic":"监测肝功能，严重肝病禁用","interact":"升高华法林、地高辛浓度；延长 QT"},{"name":"硫酸镁（多源性房速）","dose":"10% 硫酸镁 10–20 ml 加 250 ml 液体静滴，监测血镁","note":"用于 COPD/低镁状态下的多源性房速，同时纠正低钾","renal":"肾功能不全时减量并监测血镁","hepatic":"遵说明书","interact":"与神经肌肉阻滞剂协同"}],"nonDrug":["迷走刺激（Valsalva、咽部刺激、颈动脉窦按摩）：对 AVNRT/AVRT 有效，房速多无效，可帮助鉴别","同步直流电复律：血流动力学不稳定、持续房速伴心衰者，起始 50–100 J","射频消融：局灶性房速消融成功率高（多数 >80%）；大折返房速（房扑样、房颤术后房速）成功率略低","心房快速起搏终止（超速抑制）：阵发性触发型房速","治疗基础病：甲亢、COPD 缺氧、心衰，纠正低钾低镁"],"life":["避免酒精、咖啡因与拟交感药物","控制血压与体重，管理睡眠呼吸暂停","长期发作者每 6–12 个月复查超声与动态心电图，警惕心动过速性心肌病","电生理检查前停用抗心律失常药 3–5 个半衰期（胺碘酮除外）"]},"prog":"预后主要取决于基础心脏病与心室率控制。局灶性房速经射频消融后多数根治；无休止性房速若不治疗，可致心动过速性心肌病，终止心律后心功能多可恢复。大折返房速（尤其房颤消融术后）复发率较高，常需再次消融。持续房速伴心房扩大者可进展为房颤，卒中风险需按房颤指南评估抗凝。","refs":["《心律失常诊断与治疗中国专家共识》2020","《室上性心动过速基层诊疗指南（2019 年）》","《心房颤动：目前的认识和治疗建议（2021）》","2019 ESC Guidelines for the management of patients with supraventricular tachycardia"]}]},{"id":"chd_more","name":"其他先天性心脏病","rank":14,"summary":"本类以分流程度、肺血管阻力与心腔负荷为评估主线：房室间隔缺损重视房室瓣与肺血管病变，主动脉缩窄靠上下肢血压差与导管前后分型，肺动脉狭窄按跨瓣压力阶差分级决定球囊扩张或手术；大动脉转位是新生儿急症，必须生后尽快识别、用前列腺素 E1 维持导管开放、限期行动脉调转；Ebstein 畸形以三尖瓣下移程度、发绀与心律失常为核心管理。","compare":[{"diseaseId":"chd_avsd","dx":"心尖部全收缩期杂音、P2 亢进，心电图电轴左偏伴 PR 延长与右束支阻滞，超声见原发孔缺损伴共同房室瓣","key":"房室瓣反流 + 肺高压，21 三体相关率高，修补时机为 2–6 月龄以预防肺血管病变"},{"diseaseId":"chd_coarctation","dx":"上肢血压高于下肢 ≥20 mmHg、股动脉搏动减弱或延迟，背部和肩胛区收缩期杂音，CT/MRI 见主动脉峡部狭窄","key":"上下肢血压差与股动脉搏动；新生儿期为导管依赖性，需前列腺素维持"},{"diseaseId":"chd_ps","dx":"胸骨左缘 2 肋间收缩期喷射性杂音伴收缩期喀喇音，P2 减弱，超声测跨瓣压差","key":"喀喇音 + P2 减弱 + 压差分级；轻中度随访，重度球囊扩张或外科瓣膜成形"},{"diseaseId":"chd_tga","dx":"新生儿生后数小时内重度发绀、吸氧不改善，胸片蛋形心，超声见主动脉起自右室、肺动脉起自左室","key":"导管依赖性发绀急症，前列腺素 E1 维持 + 限期动脉调转术（生后 2 周内）"},{"diseaseId":"chd_ebstein","dx":"三尖瓣区收缩期杂音、右房巨大，心电图右束支阻滞样图形伴右房扩大，超声见三尖瓣隔瓣下移 >8 mm/m²","key":"三尖瓣下移程度决定发绀与右心衰；合并预激者易发心律失常"}],"diseases":[{"id":"chd_avsd","name":"房室间隔缺损","aka":["Atrioventricular Septal Defect","AVSD","心内膜垫缺损","Endocardial Cushion Defect","原发孔型房间隔缺损合并二尖瓣裂"],"rank":1,"basic":{"define":"胚胎期房间隔下部与室间隔上部（心内膜垫组织）融合障碍、共同房室瓣形成失败所致的复杂先心病；表现为原发孔型房间隔缺损、室间隔流入道缺损及共同房室瓣（Rastelli A/B/C 型）。分为部分型（存在两片房室瓣但共瓣环、无室间隔缺损）与完全型。","risk":["21 三体综合征（唐氏）——21 三体患儿合并先心病者中 AVSD 占很大比例","18 三体与其他染色体异常","母孕期风疹、糖尿病与酒精暴露","家族性先心病史","部分型以女性更常见"],"epi":"约占全部先心病的 4%–5%，在 21 三体综合征患儿中是最常见的先心病类型之一。完全型多在 3 个月内出现症状，部分型可晚至成人期才因房室瓣反流或肺动脉高压就诊。"},"patho":"共同房室瓣缺乏分隔，收缩期房室瓣（尤其左房室瓣）反流使左房与左室容量负荷增加；完全型同时存在大量左向右分流，婴儿期易出现心力衰竭。长期左向右分流致肺血流增多与肺动脉高压，可在 1–2 年内进展为肺血管病变。房室结位置下移，易发生房室传导阻滞；共同房室瓣再造后仍可能残留或再发反流。","dx":{"criteria":["心尖部收缩期杂音（二尖瓣裂所致反流），完全型伴胸骨左缘下部全收缩期杂音","P2 亢进（肺血增多、肺高压）","心电图：**电轴左偏 + 不完全性右束支阻滞**为核心表现，PR 间期延长、V1 呈 rSr′；电轴左偏是与继发孔型 ASD（电轴右偏）鉴别的要点","胸片：心脏增大（右房、右室突出）、肺血增多、肺动脉段突出","超声心动图是确诊依据：原发孔型房间隔缺损、流入道室间隔缺损、共同房室瓣及其反流程度、Rastelli 分型","心导管（必要时）：Qp/Qs、肺动脉压与阻力，评估肺血管病变是否可逆"],"workup":["经胸超声心动图：分型、房室瓣环直径、反流程度与心室平衡","经食管超声：术前评估共同房室瓣与修复方案","心电图与动态心电图：评估房室传导与心律失常","右心导管或心脏 MRI：肺高压与分流评估","染色体核型检查与遗传咨询","婴儿期监测生长发育、喂养与心衰体征"],"grading":"Rastelli 分型：A 型共同前桥瓣漂浮于室间隔嵴之上、腱索附着于室间隔嵴；B 型腱索附着于右室面；C 型无腱索附着。另分为部分型、完全型与过渡型；完全型婴儿期手术，部分型可择期。"},"ddx":[{"name":"主动脉缩窄（chd_coarctation）","point":"与本类 chd_coarctation 鉴别：CoA 以上下肢血压差与股动脉搏动减弱为特征；AVSD 无血压差，以房室瓣反流与房水平分流为主。"},{"name":"肺动脉狭窄（chd_ps）","point":"与本类 chd_ps 鉴别：PS 为喷射性杂音伴喀喇音、P2 减弱；AVSD 杂音为心尖部反流杂音，P2 亢进。"},{"name":"大动脉转位（chd_tga）","point":"与本类 chd_tga 鉴别：TGA 以新生儿重度发绀、吸氧不改善为主；AVSD 婴儿多为中心衰与肺高压，发绀较轻。"},{"name":"Ebstein 畸形（chd_ebstein）","point":"与本类 chd_ebstein 鉴别：Ebstein 三尖瓣下移、右房巨大；AVSD 房室瓣位置正常，缺损位于房间隔下部与室间隔流入道。"},{"name":"继发孔型房间隔缺损（chd_asd）","point":"同为房间隔缺损，但继发孔型电轴多右偏、无房室瓣反流与流入道室缺；原发孔型电轴左偏并伴房室瓣裂，属 AVSD 部分型。"},{"name":"室间隔缺损（chd_vsd）","point":"单纯 VSD 无共同房室瓣，心电图电轴正常，超声见膜周部或肌部缺损。"}],"tx":{"drug":[{"name":"呋塞米（心衰）","dose":"1–2 mg/kg 静脉或口服，bid 至 qd，按体重与尿量调整","note":"完全型婴儿心衰的基础治疗，需补钾","renal":"监测电解质与肾功能","hepatic":"遵说明书","interact":"与地高辛合用注意低钾致洋地黄中毒"},{"name":"卡托普利/依那普利（心衰）","dose":"卡托普利 0.1–0.5 mg/kg q8h–q12h；或依那普利 0.1 mg/kg qd 起始","note":"新生儿尤其早产儿用药需谨慎，监测血压与肾功能","renal":"肾动脉狭窄者禁用，监测肌酐与血钾","hepatic":"遵说明书","interact":"与保钾利尿剂合用致高钾；与 NSAIDs 合用降低效果"},{"name":"西地那非（术后肺高压）","dose":"0.5–1 mg/kg q6h–q8h；成人 20 mg tid","note":"按说明书与肺高压专科方案使用","renal":"重度肾功能不全减量","hepatic":"Child-Pugh C 禁用","interact":"禁与硝酸酯类合用；与波生坦联用浓度互降"},{"name":"波生坦（不可手术肺血管病变）","dose":"按体重起始 1–2 mg/kg bid，成人 62.5 mg bid 起","note":"仅用于因肺血管病变无法手术者，需监测肝酶","renal":"遵说明书","hepatic":"监测肝酶，严重肝病禁用","interact":"CYP3A4 诱导剂降低其浓度"},{"name":"心内膜炎预防","dose":"阿莫西林 50 mg/kg 术前 30–60 分钟单次（成人 2 g）","note":"未修补或有残余缺损者属高危","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["完全型 AVSD：2–6 月龄手术修复（合并心衰者可早至 2–4 月龄），目标预防肺血管病变；常用两片法再造房间隔与室间隔并修复共同房室瓣","部分型 AVSD：学龄前（2–5 岁）修复，缝合房室瓣裂口","合并肺高压者可术前用靶向药物降低阻力，评估可否手术","不可手术者按肺动脉高压管理，避免妊娠与剧烈活动","术后房室瓣反流再发或完全性房室传导阻滞（需起搏）者需再次手术"],"life":["术后 6 个月内预防心内膜炎","限制高盐与过量液体，防治呼吸道感染","每 6–12 个月复查心超与心电图，监测房室瓣反流与残余缺损","合并 21 三体者加强呼吸、喂养与康复支持","妊娠前须行心肺功能评估"]},"prog":"完全型 AVSD 若未手术，约半数在 1 岁内死亡，婴幼儿期进展为艾森曼格者预后差。早期完成修补者长期生存良好，但相当一部分需再手术（房室瓣反流或左房室瓣狭窄）；术后完全性房室传导阻滞需永久起搏者的比例约 2%–5%。部分型修补后生活质量良好，长期仍需警惕房室瓣反流与房颤。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《先天性心脏病外科治疗中国专家共识——房间隔缺损、室间隔缺损与房室间隔缺损》","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]},{"id":"chd_coarctation","name":"主动脉缩窄","aka":["Coarctation of the Aorta","CoA","主动脉缩窄症"],"rank":2,"basic":{"define":"主动脉管腔在动脉导管附着处（峡部）附近局限性狭窄，导致左室后负荷增高、上肢血压高于下肢。按与动脉导管的关系分为导管前型（狭窄位于动脉导管近端，婴儿期多见，常合并其他心内畸形）与导管后型（狭窄位于导管远端，成人多见，常为孤立病变）。","risk":["Turner 综合征","二叶主动脉瓣（成人 CoA 合并率高）","室间隔缺损等左心系统畸形","主动脉弓发育不良","家族性先心病史","男性多见"],"epi":"占先心病的 5%–8%，活产婴儿约 4/10000。成人期首次诊断者多为导管后型；新生儿期依赖导管开放，未识别者常在导管关闭后数日内出现休克。"},"patho":"狭窄使左室压力负荷增加，致左室肥厚与左心功能不全；狭窄近端血压升高，远端灌注压下降。缩窄使肾血流减少，激活 RAAS，进一步升高血压。狭窄处形成侧支循环（肋间动脉、内乳动脉），可在胸片形成肋骨切迹。导管前型合并大分流时下半身血氧降低，表现为差异性发绀。狭窄解除后仍可能残留高血压与主动脉壁病变。","dx":{"criteria":["**上下肢血压差**：上肢（肱动脉）收缩压高于下肢（腘动脉或踝部）≥20 mmHg，或股动脉搏动减弱、延迟（桡股搏动时间差）","差异性发绀（导管前型）：下肢脉氧低于上肢","心脏杂音：胸骨左缘上部至左肩胛下区收缩期杂音，侧支循环发达时可闻连续性杂音","胸片：主动脉结突出（3 字征）、肋骨切迹（成人）、心脏增大","心电图：左室肥厚伴劳损、电轴左偏","新生儿急症：无脉、休克、代谢性酸中毒伴上下肢血压差，提示导管关闭后急性左心衰","超声测狭窄前后压差，增强 CT 或心脏 MRI 明确解剖（弓部形态、狭窄长度、侧支）"],"workup":["四肢血压测量（双臂与双下肢，间隔 ≥5 分钟重复）","股动脉与桡动脉搏动时间与强度对比","经胸超声：峡部压差、左室肥厚与功能","心脏 MRI（无辐射，首选）或增强 CT：狭窄长度、弓部形态、直径与 Z 值、侧支","右心导管：合并 VSD 或 PDA 时测分流与肺阻力","24 小时动态血压：评估治疗后残余高血压","Turner 综合征与二叶主动脉瓣筛查"],"grading":"分型：导管前型（婴儿型，狭窄在导管近端，常伴心内畸形、差异性发绀）、导管后型（成人型，狭窄在导管远端，常为孤立病变）；按程度：压差 <20 mmHg 为轻度；压差 ≥20 mmHg 或狭窄直径 <50% 为有意义狭窄；伴左室肥厚、高血压或左心功能减低者为重度。"},"ddx":[{"name":"大动脉转位（chd_tga）","point":"与本类 chd_tga 鉴别：TGA 生后重度发绀、吸氧不改善；CoA 休克期以股动脉搏动消失与下半身灌注不足为主，发绀仅限下半身。"},{"name":"肺动脉狭窄（chd_ps）","point":"与本类 chd_ps 鉴别：PS 杂音为胸骨左缘上部喷射性、P2 减弱，无上下肢血压差。"},{"name":"房室间隔缺损（chd_avsd）","point":"与本类 chd_avsd 鉴别：AVSD 以房室瓣反流与左向右分流为主，无上下肢血压差；CoA 心电图多为左室肥厚。"},{"name":"Ebstein 畸形（chd_ebstein）","point":"与本类 chd_ebstein 鉴别：Ebstein 以三尖瓣下移与右心衰/心律失常为主，无上肢高血压。"},{"name":"原发性高血压","point":"上下肢血压差不超过 10 mmHg，股动脉搏动正常，影像学无狭窄。"},{"name":"大动脉炎","point":"多见于年轻女性，ESR/CRP 升高，狭窄部位不限于峡部，血管壁增厚与炎症特征明显。"}],"tx":{"drug":[{"name":"前列腺素 E1（新生儿导管依赖）","dose":"0.01–0.05 μg·kg⁻¹·min⁻¹ 持续静脉输注","note":"导管前型伴休克或导管依赖循环时使用；注意呼吸暂停、体循环低血压与发热；尽快明确解剖并过渡到手术","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"多巴胺/多巴酚丁胺（休克）","dose":"5–10 μg·kg⁻¹·min⁻¹ 静脉泵入，按血压与灌注滴定","note":"新生儿左心衰休克，需在 NICU 条件下使用","renal":"监测尿量","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用可致高血压危象"},{"name":"美托洛尔（术后/成人高血压）","dose":"缓释片 23.75–95 mg qd，按血压调整；儿童按体重 0.5–2 mg/kg/d","note":"术后残余高血压一线之一，尤其合并主动脉根部扩张者","renal":"重度肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用致心动过缓"},{"name":"氨氯地平（成人高血压）","dose":"2.5–5 mg qd 起始，最大 10 mg qd","note":"β 阻滞剂不适用或控制不佳时使用","renal":"肾功能不全无需调整","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂升高其浓度"},{"name":"依那普利（术后残余高血压）","dose":"成人 5–10 mg bid；儿童 0.1–0.5 mg/kg/d 起始","note":"需先排除残余缩窄或肾动脉狭窄","renal":"双侧肾动脉狭窄、孤立肾禁用；监测肌酐与血钾","hepatic":"遵说明书","interact":"与 NSAIDs、保钾利尿剂相互作用"}],"nonDrug":["球囊扩张血管成形术：成人局灶性 CoA 首选，可辅以裸金属支架（成人型）或可扩张支架（儿童），即时成功率高","外科手术：新生儿与婴幼儿、长段狭窄、弓部发育不良或合并心内畸形者，行端端吻合或扩大端端吻合","干预指征：压差 ≥20 mmHg 伴高血压或左室肥厚；或压差 <20 mmHg 但狭窄直径 <50% 伴明显高血压或侧支","合并二叶主动脉瓣者需评估主动脉瓣功能并长期随访主动脉根部直径","合并 VSD/PDA 者同期矫治"],"life":["终身监测上下肢血压，成人每年至少一次动态血压","MRI/CT 定期复查主动脉（每 2–3 年），警惕再狭窄与升主动脉扩张","控制体重与高盐饮食，规律有氧运动","避免未控高血压时进行竞技运动","女性妊娠前评估主动脉根部直径与血压"]},"prog":"新生儿期未识别者可在导管关闭后迅速进入休克并死亡；及时修补者长期生存良好。术后残余高血压在成人群中相当常见并持续至远期，心血管事件风险仍高于匹配人群；再狭窄率约 10%–20%，多见于术后早期；二叶主动脉瓣与修复年龄较大者需警惕主动脉根部扩张与夹层。早诊早治者远期预后好。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《主动脉缩窄诊断与治疗中国专家共识》","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]},{"id":"chd_ps","name":"肺动脉狭窄","aka":["Pulmonary Stenosis","PS","肺动脉瓣狭窄","Pulmonary Valve Stenosis","右室流出道梗阻"],"rank":3,"basic":{"define":"右室流出道至肺动脉任意水平的狭窄，以肺动脉瓣狭窄最常见，其次为漏斗部（右室流出道）狭窄与肺动脉主干/分支狭窄。多为先天性，少数为获得性（风湿、类癌、肿瘤）。","risk":["遗传综合征（Noonan、Williams）","新生儿风疹综合征","家族性遗传易感","可并入法洛四联症等复杂先心病","母体致畸药物暴露"],"epi":"占先心病的 8%–10%，单纯肺动脉瓣狭窄活产婴儿约 0.7/1000，男女大致相当。成人先心病中占比约 10%，多数为瓣膜型；Noonan 综合征合并率较高。"},"patho":"瓣膜型常见瓣叶增厚融合呈圆顶状，或发育不良（增厚、僵硬），导致开放受限与跨瓣压差增大；右室收缩压升高，长期致右室肥厚、右室舒张压升高、右心扩大，严重者右房压升高，经卵圆孔右向左分流出现发绀。漏斗部狭窄由肌束肥厚造成；分支肺动脉狭窄使肺血流分布不均。跨瓣压差随血流增加而增大，重度者心输出量受限，活动耐量下降。","dx":{"criteria":["胸骨左缘第 2 肋间收缩期喷射性杂音，向颈部与左肩背部传导，常伴收缩期喀喇音；P2 减弱（重度时消失）","重度狭窄或伴右向左分流者可见发绀","心电图：右室肥厚、电轴右偏、右房扩大，与狭窄严重程度相关","胸片：右室增大、肺动脉段突出、肺血减少或正常","超声心动图：瓣叶增厚/圆顶、跨瓣峰压差、以三尖瓣反流速度估算右室收缩压"],"workup":["经胸超声：瓣环直径、瓣叶形态（瓣膜型/发育不良型）、跨瓣压差、右室功能","心电图：评估右室肥厚与心律失常","心导管：测右室-肺动脉压差，评估球囊扩张指征","心脏 MRI：复杂病例的右室容积与分流评估","遗传筛查与综合征评估（Noonan 面容、Turner）"],"grading":"按跨瓣峰压差分级：轻度 <36 mmHg；中度 ≥36 且 <64 mmHg；重度 ≥64 mmHg。新生儿危重型需依赖导管开放。按部位分瓣膜型、漏斗部型、肺动脉干/分支型；按形态分典型（圆顶）与发育不良型。"},"ddx":[{"name":"主动脉缩窄（chd_coarctation）","point":"与本类 chd_coarctation 鉴别：CoA 有上下肢血压差、杂音在背部；PS 杂音在胸骨左缘上部、无血压差。"},{"name":"房室间隔缺损（chd_avsd）","point":"与本类 chd_avsd 鉴别：AVSD 以房室瓣反流与电轴左偏为特征、P2 亢进；PS 心电图右室肥厚、电轴右偏、P2 减弱。"},{"name":"大动脉转位（chd_tga）","point":"与本类 chd_tga 鉴别：TGA 新生儿重度发绀、吸氧不改善；单纯 PS 新生儿多无症状。"},{"name":"Ebstein 畸形（chd_ebstein）","point":"与本类 chd_ebstein 鉴别：Ebstein 以三尖瓣下移、右房巨大与房性心律失常为主；PS 无三尖瓣下移。"},{"name":"继发孔型房间隔缺损（chd_asd）","point":"ASD 有 S2 固定分裂、P2 正常或亢进、肺血增多；PS 为喷射性杂音伴喀喇音、P2 减弱、肺血减少。"},{"name":"法洛四联症","point":"四联症伴明显发绀与杵状指、心影靴形；单纯 PS 发绀少见。"}],"tx":{"drug":[{"name":"经导管球囊肺动脉瓣成形术","dose":"球囊直径约为瓣环的 1.1–1.25 倍，按标准介入方案；术后压差下降为成功标准","note":"压差 ≥64 mmHg 或伴症状/右室肥厚者为适应证；发育不良型瓣球囊效果差","renal":"遵说明书","hepatic":"遵说明书","interact":"不适用"},{"name":"前列腺素 E1（危重型新生儿）","dose":"0.01–0.05 μg·kg⁻¹·min⁻¹ 静脉输注","note":"新生儿危重型狭窄依赖动脉导管时维持导管开放，等待球囊或手术","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"β 阻滞剂（心律失常对症）","dose":"美托洛尔或普萘洛尔按体重 1–2 mg/kg/d 分次，需心律专科指导","note":"合并室性心律失常或右室功能受损时辅助，不能替代解除狭窄","renal":"肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米等合用致心动过缓"},{"name":"心内膜炎预防","dose":"阿莫西林成人 2 g 单次（儿童 50 mg/kg）术前 30–60 分钟；青霉素过敏者用克林霉素或阿奇霉素","note":"人工瓣或修补术后属高危","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["球囊肺动脉瓣成形术适应证：跨瓣压差 ≥64 mmHg；或压差 <64 mmHg 伴症状、右室肥厚、右室扩大、心律失常","外科手术：瓣膜成形、流出道重建或置换，用于球囊失败（发育不良型瓣）、合并右室流出道狭窄或复杂畸形者","新生儿危重型可先行球囊或手术"],"life":["轻度 PS（<36 mmHg）每 2–3 年随访超声","球囊扩张后 1 个月、3 个月、1 年复查，以后每 1–3 年评估肺动脉反流与右室大小","重度狭窄解除后注意脑缺氧、右心衰与心律失常","高危患者侵入性操作前预防心内膜炎","孕妇合并重度 PS 需产科与心内科联合管理"]},"prog":"轻度 PS 可长期稳定，仅需随访；压差 ≥64 mmHg 且未治疗者运动耐量下降，长期可有右心衰与心律失常风险。球囊瓣成形术后多数患者远期免于再干预，幼儿期球囊扩张后可有再狭窄，常需二次球囊。重度狭窄解除后生存率接近正常人群，但长期肺动脉反流可致右室扩张，个别需肺动脉瓣置换。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《常见先天性心脏病（房间隔缺损、室间隔缺损、动脉导管未闭、肺动脉瓣狭窄）介入治疗中国专家共识》","2020 ESC Guidelines for the management of adult congenital heart disease"]},{"id":"chd_tga","name":"大动脉转位","aka":["Transposition of the Great Arteries","D-TGA","大动脉转位（D 型）","完全性大动脉转位"],"rank":4,"basic":{"define":"出生前主动脉与肺动脉起源互换，主动脉起自形态学右室、肺动脉起自形态学左室，形成两条平行的循环（体循环与肺循环）而失去串联关系；典型形式为 D-TGA（主动脉位于肺动脉前右）。以室间隔是否完整分为简单型与复杂型（合并 VSD、左室流出道狭窄、主动脉缩窄等）。","risk":["母孕期糖尿病与肥胖","母孕期风疹与致畸药物","染色体与遗传综合征","男性多见","家族性先心病史"],"epi":"占先心病的 5%–7%，活产婴儿约 0.3/1000。未治疗者多数在新生儿期死亡，是新生儿期最危重的紫绀型先心病之一；动脉调转术后远期生存良好。"},"patho":"体循环与肺循环平行，交叉混合的血液极少：发绀程度取决于合并畸形（ASD、VSD、PDA）带来的混合程度以及肺血流多少。VSD 较大者混合较好但肺血过多，易心衰；合并 VSD 与左室流出道狭窄者肺血减少，发绀更重。动脉导管在生后收缩关闭后，混合进一步减少，患儿迅速恶化（导管依赖性）。术后需移植冠状动脉，远期并发症包括主动脉根部扩张、冠状动脉损害与肺动脉狭窄。","dx":{"criteria":["**生后重度发绀**：多在生后数小时至 24 小时内出现，**吸氧后不改善**（鉴别呼吸系统疾病的关键）","呼吸窘迫与发绀程度不成比例（发绀重而呼吸不急促）","心脏体征可不明显，简单型时无杂音或仅轻微","胸片：心影呈**蛋形（egg-on-string）**，上纵隔窄（大血管前后排列），肺血正常或增多","心电图：右室肥厚（新生儿右室优势需结合年龄判断）","超声心动图是金标准：确认大动脉起源互换、室间隔是否完整、合并畸形（ASD/PDA/VSD/主动脉缩窄）与冠状动脉分支","血气：PaO2 低而 PaCO2 正常或偏低，高氧试验不改善"],"workup":["生后立即行 12 导联心电图与血气分析","经胸超声（新生儿急症出生当日即可完成，重点看房室连接与大血管连接）","胸片与其他发绀型先心病鉴别","全血细胞计数与凝血、感染指标（排除脓毒症）","术前冠状动脉解剖评估（CT 血管造影或心导管），影响手术方案"],"grading":"分型：D-TGA（最常见）与 L-TGA（先天性纠正型，预后不同）；简单型（室间隔完整）与复杂型（合并 VSD、左室流出道狭窄、主动脉缩窄或弓离断）；按冠状动脉解剖（Yacoub 分类）分层，决定手术可行性。"},"ddx":[{"name":"肺动脉狭窄（chd_ps）","point":"与本类 chd_ps 鉴别：重度 PS 有喷射性杂音与喀喇音、P2 减弱，房室与大动脉连接正常；TGA 吸氧不改善且超声见大动脉起源互换。"},{"name":"Ebstein 畸形（chd_ebstein）","point":"与本类 chd_ebstein 鉴别：Ebstein 三尖瓣下移、右房巨大，发绀由房水平分流所致；TGA 为两条循环平行失衡。"},{"name":"主动脉缩窄（chd_coarctation）","point":"与本类 chd_coarctation 鉴别：CoA 以休克与下半身灌注不足为主；TGA 为全身性发绀。"},{"name":"房室间隔缺损（chd_avsd）","point":"与本类 chd_avsd 鉴别：AVSD 婴儿多为中心衰与肺高压，发绀较轻；TGA 生后即刻重度发绀。"},{"name":"完全性肺静脉异位引流","point":"发绀伴呼吸急促、肺淤血，超声见肺静脉汇入体静脉，左房偏小。"},{"name":"法洛四联症","point":"四联症胸片为靴形心，有缺氧发作；TGA 胸片为蛋形心、大血管错位。"},{"name":"持续性肺动脉高压与脓毒症","point":"前者大血管位置正常、对一氧化氮有效；后者有感染指标升高与循环差。"}],"tx":{"drug":[{"name":"前列腺素 E1（术前维持）","dose":"0.01–0.05 μg·kg⁻¹·min⁻¹ 静脉持续输注，依据血氧与血压滴定，维持动脉导管开放","note":"确诊后立即开始；观察呼吸暂停、低血压与发热；若出现呼吸抑制需准备插管；避免剂量过大导致过多肺血流与体循环低灌注","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"多巴胺/肾上腺素（低灌注）","dose":"多巴胺 5–10 μg·kg⁻¹·min⁻¹；必要时肾上腺素 0.05–0.2 μg·kg⁻¹·min⁻¹","note":"维持体循环灌注，围术期辅助","renal":"监测尿量","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用致高血压危象"},{"name":"米力农","dose":"0.25–0.75 μg·kg⁻¹·min⁻¹ 静脉泵入","note":"术后低心排时降低肺血管阻力、改善心肌收缩","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与西地那非联用可致低血压"},{"name":"西地那非（术后肺高压）","dose":"0.5–2 mg/kg q6h–q8h","note":"按术后方案，警惕低血压","renal":"重度肾功能不全减量","hepatic":"遵说明书","interact":"禁与硝酸酯类同用"},{"name":"呋塞米","dose":"1–2 mg/kg 静注 q12h 或按需","note":"术后液体管理，需补钾","renal":"监测电解质","hepatic":"遵说明书","interact":"与地高辛合用需补钾"}],"nonDrug":["**动脉调转术（Arterial Switch Operation，ASO）**：简单型在生后 2 周内完成（通常生后 4–14 天），合并 VSD 者可延至 4–8 周；冠状动脉移植至新主动脉，主动脉与肺动脉互换","术前行前列腺素 E1，必要时加限制性球囊房间隔造口术（Rashkind 术）以改善混合","合并左室流出道狭窄者改行 Rastelli 或 Nikaidoh 术式","冠状动脉解剖不宜调转者评估其他术式","长期随访主动脉根部扩张、新肺动脉瓣狭窄或反流、冠状动脉功能与心功能"],"life":["术后 6 个月内预防心内膜炎","每 1–2 年复查超声、心电图与运动试验，监测主动脉根部与右室流出道","避免高强度竞技运动，尤其有残余梗阻或冠状动脉病变者","妊娠需行心脏评估与多学科管理","成人患者注意冠脉事件风险，必要时行冠状动脉 CT 或负荷试验"]},"prog":"未治疗者新生儿期死亡率极高。动脉调转术后中远期生存良好，但需终身随访：长期并发症包括主动脉根部扩张与瓣膜反流、肺动脉分支狭窄（部分需再干预）、冠状动脉狭窄与心功能下降。术后早期死亡主要与冠状动脉移植并发症及低心排有关，远期关注右室流出道与大动脉根部。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《先天性心脏病外科治疗中国专家共识——大动脉转位》","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]},{"id":"chd_ebstein","name":"Ebstein 畸形","aka":["Ebstein Anomaly","Ebstein's Anomaly","三尖瓣下移畸形"],"rank":5,"basic":{"define":"三尖瓣隔瓣（及部分后瓣）附着点向左室侧移位，使部分右室（房化右室）并入右房，功能性右室变小、三尖瓣关闭不全；常合并房间隔缺损或卵圆孔未闭、三尖瓣发育异常与预激综合征。按右室发育与瓣膜条件不同，从轻型成人长期无症状到新生儿重度发绀、心力衰竭不等。","risk":["锂盐孕期暴露","遗传综合征与家族性病例","合并房间隔缺损或卵圆孔未闭","女性与男性相当，成人队列女性略多"],"epi":"占先心病的 0.5%–1%，活产婴儿约 0.1–0.2/1000。相当比例合并预激综合征（WPW），是成人期心律失常就诊的常见原因之一。"},"patho":"三尖瓣下移导致右房扩大与功能性右室缩小，收缩期反流使右房压升高；右房压超过左房时经房间隔缺损发生右向左分流而发绀。右房显著扩大易致房性心律失常，并常见预激相关心动过速。右室收缩功能减弱，长期可发展为右心衰与低心排。房化右室与巨大右房改变右心几何构型，术前需评估能否行瓣膜成形。","dx":{"criteria":["三尖瓣区收缩期杂音（反流轻时杂音不明显）、第 1 心音分裂（三尖瓣成分延迟）、右房扩大","发绀：右房压升高伴房间隔缺损时出现，运动可加重","心电图：**右束支阻滞样图形（V1 呈 rSR′ 或宽 R）+ 右房扩大（P 波高尖）+ 一度房室传导阻滞**；部分可见预激波形","胸片：心影增大呈球形（右房增大），主动脉结小","超声心动图：三尖瓣隔瓣与后瓣下移、下移距离指数增大、右房扩大、房化右室形成、反流程度与房间隔分流；确诊靠超声","心脏 MRI 评估右室容积、功能与瓣膜解剖（手术规划）"],"workup":["经胸超声：三尖瓣下移程度、反流、右室容积、合并缺损","心电图与 24 小时动态心电图：筛查预激、房扑/房颤与室速","心脏 MRI：右室与房化右室测量、右室功能","电生理检查（术前）：预激与旁路定位","血氧饱和度监测（发绀程度），合并发绀者查血常规评估红细胞增多"],"grading":"Carpentier 分型：A 型（功能性右室容积足够、下移较轻）、B 型（右室容积可、三尖瓣显著下移）、C 型（右室小、房化右室大、瓣叶活动受限）、D 型（瓣叶严重发育不良、右室极小，需行 Fontan 路径或心室替代术）。"},"ddx":[{"name":"大动脉转位（chd_tga）","point":"与本类 chd_tga 鉴别：TGA 生后早期严重发绀、吸氧不改善、蛋形心；Ebstein 发绀为房水平右向左分流所致，超声见瓣膜下移。"},{"name":"房室间隔缺损（chd_avsd）","point":"与本类 chd_avsd 鉴别：AVSD 有原发孔缺损与共同房室瓣、电轴左偏；Ebstein 三尖瓣下移是核心，房室瓣位置异常而非间隔缺损为主。"},{"name":"肺动脉狭窄（chd_ps）","point":"与本类 chd_ps 鉴别：PS 为喷射性杂音、P2 减弱、无右房巨大；Ebstein 为收缩期反流杂音。"},{"name":"主动脉缩窄（chd_coarctation）","point":"与本类 chd_coarctation 鉴别：CoA 有上下肢血压差；Ebstein 无血压差而有右房巨大。"},{"name":"单纯三尖瓣发育不良","point":"三尖瓣位置正常，仅瓣叶增厚或腱索异常伴反流；Ebstein 有明确瓣环下移。"},{"name":"心包积液导致的右房增大","point":"超声见积液与心包改变，三尖瓣位置正常。"}],"tx":{"drug":[{"name":"利尿剂（右心衰）","dose":"呋塞米 20–40 mg qd–bid（儿童 1–2 mg/kg），可联合螺内酯 20 mg qd","note":"右心衰淤血时使用；避免过度利尿致低血压与低灌注","renal":"监测肾功能与电解质","hepatic":"遵说明书","interact":"与地高辛合用时注意低钾低镁"},{"name":"胺碘酮（房性心律失常）","dose":"负荷 150 mg 静滴 10 分钟，随后 1 mg/min 维持；口服维持 200 mg qd","note":"预激合并房扑/房颤时**禁用洋地黄、维拉帕米、β 阻滞剂**（可加速旁路前传）；胺碘酮可用于控制心室率或复律","renal":"无需调整","hepatic":"监测肝酶","interact":"与华法林、地高辛相互作用；延长 QT"},{"name":"普罗帕酮（预激合并房颤，稳定期）","dose":"150 mg tid 或按体重","note":"仅限经电生理评估、无严重右心衰者；急性房扑/房颤时不单独使用","renal":"肾功能不全减量","hepatic":"肝功能不全减量","interact":"避免与胺碘酮联用"},{"name":"美托洛尔（心律失常预防）","dose":"25–50 mg bid 或按体重","note":"用于稳定期心律失常预防；急性预激房颤时禁用","renal":"重度肾功能不全遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米同用致心脏阻滞"},{"name":"华法林/直接口服抗凝药（合并房扑/房颤）","dose":"按 CHA₂DS₂-VASc 评分与肾功能；华法林目标 INR 2.0–3.0","note":"合并房性心律失常者卒中风险高；发绀者需评估出血风险","renal":"DOAC 按 CrCl 调整","hepatic":"严重肝病慎用或禁用","interact":"胺碘酮、氟康唑等强烈影响华法林 INR"}],"nonDrug":["**三尖瓣成形/置换 + 房化右室折叠术**：Carpentier A 型和部分 B 型可选；修补指征为 NYHA ≥Ⅱ 级、进行性右室扩张或三尖瓣反流加重、发绀伴右向左分流","C/D 型：行双向 Glenn 或全腔静脉-肺动脉连接（Fontan 改良或 1.5 心室修补）","射频消融预激旁路：症状性预激首选，术前或术中一并处理","合并房间隔缺损者同期修补","严重发绀伴红细胞增多症者避免脱水，按指南评估放血指征"],"life":["每 6–12 个月至 1 年复查超声、心电图与血氧","重度发绀者避免高海拔、剧烈运动与脱水","妊娠需心内科与产科联合评估，重度发绀者妊娠风险高","术后 6 个月内预防心内膜炎","残余右心衰、心律失常需长期专科随访"]},"prog":"轻型成人多可长期稳定，部分 50 岁以后才出现症状；重度发绀的婴儿若不干预，新生儿期死亡率较高。成人初次三尖瓣修补手术死亡率较低，术后多数患者症状改善，但瓣膜成形者远期有一定再手术率。心血管死亡多与心律失常相关，合并预激者急性房颤可危及生命。","refs":["《中国先天性心脏病诊断与治疗指南》2020","《先天性心脏病外科治疗中国专家共识——三尖瓣下移畸形》","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]}]},{"id":"cad_other","name":"冠心病的其他临床类型","rank":44,"summary":"同属冠心病谱系但不以典型心绞痛为主诉的两类：无症状性心肌缺血靠客观证据发现，缺血性心肌病以心力衰竭为首发表现，二者都需按冠心病二级预防处理。","compare":[{"diseaseId":"cad_silent_ischemia","dx":"有心肌缺血客观证据（负荷试验、动态心电图、影像或造影）但无典型心绞痛症状","key":"症状缺如，靠客观检查发现；糖尿病与老年患者高发"},{"diseaseId":"cad_ischemic_cmp","dx":"冠心病证据 + 左室扩大 + LVEF 降低（通常 <40%），排除其他心肌病","key":"以心力衰竭为首发表现，CMR 延迟强化呈缺血性分布（心内膜下或透壁）"}],"diseases":[{"id":"cad_silent_ischemia","name":"无症状性心肌缺血","aka":["Silent Myocardial Ischemia","SMI","隐匿性冠心病","无症状性冠心病"],"rank":1,"basic":{"define":"存在心肌缺血的客观证据（负荷试验、动态心电图、心肌灌注显像、冠状动脉影像或心肌磁共振灌注异常），但患者无典型心绞痛或等同症状。","risk":["2 型糖尿病与糖尿病自主神经病变（痛觉传入迟钝）","高龄、女性、慢性肾脏病","既往心肌梗死、血运重建（PCI/CABG）后","长期 β 受体阻滞剂或硝酸酯类掩盖症状","吸烟、高血压、血脂异常、肥胖等冠心病危险因素聚集"],"epi":"2 型糖尿病患者中检出率约 20%–30%，既往心梗患者中约 20%–30% 存在无症状缺血发作；普通人群中因缺乏筛查，实际患病率被低估。"},"patho":"心肌氧供需失衡产生缺血，但痛觉信号未能上传至中枢：糖尿病自主神经病变使心脏交感与副交感传入纤维受损；部分患者内源性阿片肽升高、缺血范围小或持续时间短（<1 min）不足以触发痛觉；侧支循环也使缺血程度减轻。缺血同样可导致心肌顿抑、舒张功能下降与心律失常，因此“无症状”不等于“无风险”。","dx":{"criteria":["无典型心绞痛、胸闷或等同症状（气促、乏力、上腹不适）","负荷试验阳性：运动或药物负荷心电图 ST 段水平型或下斜型压低 ≥1 mm（0.08 s 后），或负荷超声新出现 ≥1 个室壁节段运动异常","动态心电图：ST 段压低 ≥1 mm、持续 ≥1 min，两次发作间隔 ≥1 min（1×1×1 规则）","冠状动脉 CTA 或造影见 ≥50% 狭窄，且功能学（FFR ≤0.80、iFR ≤0.89）或负荷影像证实缺血","心肌灌注显像或 CMR 见可逆性灌注缺损，或 CMR 见心内膜下缺血性延迟强化","分型：Ⅰ 型为完全无症状者；Ⅱ 型为心肌梗死后仍有无症状缺血发作；Ⅲ 型为既有心绞痛又有无症状发作者"],"workup":["静息 12 导联心电图：可见陈旧梗死 Q 波、左室肥厚或非特异性 ST-T 改变，正常不能排除","运动平板或踏车试验：评估缺血阈值、运动耐量与心律失常，不能运动者改药物负荷","负荷超声心动图或 SPECT/PET 心肌灌注：定位缺血与评估存活心肌","冠状动脉 CTA：适用于中低危、可排除显著狭窄；钙化重者需结合功能学","心脏磁共振：评估缺血性延迟强化、室壁厚度与存活心肌","24–48 h 动态心电图：捕捉日常生活中的无症状 ST 段压低"],"grading":"按发作时是否伴症状分为无症状性（silent）与混合性（部分发作有症状）；按缺血负荷分为低负荷（≤1 个节段或总缺血时间 <30 min/24 h）与高负荷（多节段、总缺血时间 ≥60 min/24 h），后者事件风险更高。"},"ddx":[{"name":"稳定型心绞痛（cad_sap）","point":"与本类中稳定型心绞痛的鉴别：后者有劳力性胸痛且能被休息或硝酸甘油缓解，本型完全无痛，只能靠客观检查发现。"},{"name":"变异型心绞痛/冠脉痉挛（cad_scad）","point":"痉挛性缺血多在静息、夜间发作，心电图见一过性 ST 段抬高而非压低，常伴疼痛；本型为固定狭窄导致的 ST 段压低且无痛。"},{"name":"非心源性胸痛","point":"食管痉挛、肋软骨炎、焦虑等可有胸痛但负荷试验阴性、无缺血影像证据；本型相反，有缺血证据而无症状。"},{"name":"假性 ST 段压低","point":"体位改变、过度通气、低钾血症、洋地黄效应、左室肥厚伴劳损均可致 ST 段压低，需结合负荷影像或功能学排除。"},{"name":"扩张型心肌病（cm_dcm）","point":"可有心力衰竭与心电图异常，但冠脉无显著狭窄、CMR 延迟强化呈壁内分布，与本型的缺血性证据不同。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"75–100 mg qd 口服（无禁忌者长期）","note":"二级预防基础用药；有消化道出血史者加 PPI","renal":"CKD 无需调整；透析患者出血风险高，需个体化","hepatic":"严重肝病伴凝血障碍者慎用","interact":"与抗凝药、NSAID 联用增加出血；与甲氨蝶呤合用增加毒性"},{"name":"阿托伐他汀","dose":"20–40 mg qn 口服，目标 LDL-C <1.8 mmol/L（高危 <1.4 mmol/L）","note":"所有冠心病患者均应使用；监测肝酶与肌酸激酶","renal":"CKD 1–3 期无需调整；4–5 期起始 10 mg 并监测","hepatic":"活动性肝病或转氨酶 >3 倍正常上限禁用","interact":"与克拉霉素、伊曲康唑、环孢素合用升高浓度与肌病风险；避免大量葡萄柚汁"},{"name":"美托洛尔缓释片","dose":"47.5–95 mg qd 口服，静息心率控制在 55–60 次/分","note":"减少缺血发作与改善预后；哮喘、严重心动过缓慎用","renal":"无需调整","hepatic":"肝硬化者减量","interact":"与维拉帕米、地尔硫䓬合用可致严重心动过缓与传导阻滞；与胰岛素合用掩盖低血糖症状"},{"name":"培哚普利","dose":"4–8 mg qd 口服（从小剂量 2 mg 起始，1–2 周加倍）","note":"合并高血压、糖尿病、左室功能不全者优先；监测血钾与肌酐","renal":"eGFR <30 起始 2 mg qd；双侧肾动脉狭窄禁用","hepatic":"无需调整","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAID 合用削弱降压并增加肾损伤"},{"name":"硝酸异山梨酯缓释片","dose":"20 mg bid 口服（症状性发作者按需，无症状者不作为常规）","note":"本型无痛，硝酸酯仅用于合并心绞痛或心衰者；长期使用产生耐受","renal":"无需调整","hepatic":"严重肝病慎用","interact":"与 PDE5 抑制剂（西地那非等）24 h 内合用可致致命性低血压，禁忌"}],"nonDrug":["血运重建：左主干或前降支近端 ≥70%、多支病变伴大面积缺血、FFR ≤0.80 者行 PCI 或 CABG，可减少无症状缺血负荷","糖尿病患者每年筛查：静息心电图 + 必要时负荷试验或 CTA，尤其合并自主神经病变者","运动康复与心脏康复处方：每周 ≥150 min 中等强度有氧运动","控制诱因：纠正贫血、甲亢、心动过速、血压剧烈波动"],"life":["戒烟并避免二手烟；限酒","地中海饮食或 DASH 饮食，限盐 <5 g/d，控制体重 BMI <24 kg/m²","规律有氧运动，避免久坐；运动前评估缺血阈值","每年复查血脂、血糖、血压、肾功能与心电图；症状变化随时就诊"]},"prog":"无症状并不代表低危：合并糖尿病或多支病变者，其心血管死亡与心梗风险与有症状冠心病相近。规范二级预防与必要血运重建可显著降低事件率；缺血负荷高、LVEF 下降者预后更差。","refs":["《稳定性冠心病诊断与治疗指南》（中华医学会心血管病学分会，2018）","2019 ESC Guidelines for the diagnosis and management of chronic coronary syndromes","2023 AHA/ACC/ACCP/ASPC/NLA/PCNA Guideline for the Management of Patients With Chronic Coronary Disease","《中国 2 型糖尿病防治指南（2020 年版）》心血管并发症筛查部分"]},{"id":"cad_ischemic_cmp","name":"缺血性心肌病","aka":["Ischemic Cardiomyopathy","ICM","冠心病性心力衰竭","缺血性心力衰竭"],"rank":2,"basic":{"define":"由冠状动脉粥样硬化性狭窄或闭塞引起心肌长期缺血、坏死与纤维化，导致左心室扩大和收缩功能下降（LVEF <40%–50%）的一组临床综合征，需排除其他原因的心肌病。","risk":["多支冠状动脉病变、左主干或前降支近端狭窄","既往心肌梗死（尤其前壁大面积梗死）","糖尿病、高血压、血脂异常、吸烟","慢性肾脏病、高龄、男性","未行血运重建的稳定型冠心病"],"epi":"在冠心病高发地区，缺血性心肌病约占慢性心力衰竭病因的 50%–70%；心肌梗死后 5 年内约 20%–30% 患者发生心力衰竭，前壁梗死伴 LVEF <40% 者风险最高。"},"patho":"慢性缺血导致心肌顿抑与冬眠（hibernation），收缩蛋白表达下调、能量代谢由脂肪酸转向葡萄糖；反复缺血与梗死形成瘢痕，触发左室重构：室壁变薄、心腔扩大、球形化，室壁应力升高进一步恶化收缩功能。存活心肌与瘢痕交错分布，是缺血性心肌病区别于扩张型心肌病的病理基础。","dx":{"criteria":["有冠心病证据：既往心梗、冠脉造影或 CTA 见 ≥1 支主要血管 ≥70% 狭窄（左主干 ≥50%）","左心室扩大（LVEDD >55 mm 或 LVEDV 指数增高）伴收缩功能下降，LVEF <40%（部分标准为 <50%）","心力衰竭症状与体征（NYHA Ⅱ–Ⅳ 级），或以心衰为首发表现","CMR 延迟强化呈缺血性分布：心内膜下或透壁强化，符合冠脉供血区域","排除其他病因：无原发性心肌病、瓣膜病、酒精性、心肌炎、淀粉样变等证据","核素/负荷超声/CMR 评估存活心肌比例，指导血运重建决策"],"workup":["超声心动图：左室舒张末径、LVEF、室壁节段运动、二尖瓣反流、左房大小与肺动脉压","心脏磁共振：延迟强化定位瘢痕与存活心肌，鉴别扩张型心肌病（壁内强化）与淀粉样变（弥漫心内膜下强化）","冠状动脉造影：明确病变支数、部位与 SYNTAX 评分，决定 PCI 或 CABG","BNP/NT-proBNP：辅助诊断与预后分层","负荷试验或 PET：评估存活心肌与缺血范围","肾功能、电解质、甲状腺功能、铁代谢：心衰药物治疗前基线评估"],"grading":"按 LVEF 分为 HFrEF（≤40%）、HFmrEF（41%–49%）、HFpEF（≥50%，本型较少）；按 NYHA 心功能分级 Ⅰ–Ⅳ 级；按存活心肌比例分为以存活心肌为主（血运重建获益大）与以瘢痕为主（获益有限）。"},"ddx":[{"name":"扩张型心肌病（cm_dcm）","point":"与本类中扩张型心肌病的鉴别：DCM 冠状动脉无显著狭窄，CMR 延迟强化多为室间隔壁内线性强化；缺血性心肌病有明确冠脉病变且强化呈心内膜下或透壁的血管 territory 分布。"},{"name":"瓣膜性心脏病所致心衰（vhd_mr）","point":"重度二尖瓣反流或主动脉瓣病变可致左室扩大与 LVEF 下降，超声见瓣膜结构与血流异常；缺血性心肌病的二尖瓣反流多为继发性（瓣环扩张、乳头肌移位）。"},{"name":"酒精性心肌病（cm_peripartum）","point":"长期大量饮酒史，戒酒后 LVEF 可明显改善；冠脉通常正常，CMR 无缺血性延迟强化。"},{"name":"心肌炎后心肌病（cm_myocarditis）","point":"多有病毒感染前驱史、发病年龄轻，CMR 见心外膜下或壁内强化伴水肿；冠脉无显著狭窄。"},{"name":"心脏淀粉样变","point":"超声见室壁对称增厚、颗粒样回声、心电图低电压与之不匹配；CMR 弥漫心内膜下强化，血/尿轻链或 PYP 显像阳性。"},{"name":"高血压性心脏病","point":"长期高血压致左室向心性肥厚，LVEF 多保留；缺血性心肌病以左室扩大与节段性室壁运动异常为主，伴冠脉病变。"}],"tx":{"drug":[{"name":"沙库巴曲缬沙坦","dose":"起始 50 mg bid 口服（未用 ACEI 者或低血压者 25 mg bid），每 2–4 周倍增至目标 200 mg bid","note":"HFrEF 首选，替代 ACEI/ARB；可降低心血管死亡与心衰住院","renal":"eGFR <30 慎用并减量；肌酐较基线升高 >30% 需评估","hepatic":"重度肝损害（Child-Pugh C）不推荐","interact":"与 ACEI 必须间隔 36 h 以上（血管性水肿风险）；与保钾利尿剂合用监测血钾"},{"name":"比索洛尔","dose":"1.25 mg qd 起始，每 2 周递增至 10 mg qd（静息心率不低于 55 次/分）","note":"病情稳定后启动，可降低猝死与总死亡率；急性失代偿期暂缓","renal":"eGFR <20 最大 10 mg qd 并慎用","hepatic":"严重肝损害减量","interact":"与非二氢吡啶类钙拮抗剂合用可致传导阻滞；与胰岛素合用掩盖低血糖"},{"name":"螺内酯","dose":"20 mg qd 口服（血钾与肾功能允许时可增至 25–50 mg qd）","note":"适用于 LVEF ≤35% 且 NYHA Ⅱ–Ⅳ 级；监测血钾与肌酐","renal":"eGFR <30 或血钾 >5.0 mmol/L 禁用","hepatic":"肝硬化伴腹水者慎用并监测","interact":"与 ACEI/ARB、补钾剂合用致高钾；与 NSAID 合用降低利尿效果"},{"name":"达格列净","dose":"10 mg qd 口服（晨服，不受进食影响）","note":"SGLT2 抑制剂，降低心衰住院与心血管死亡；非糖尿病患者同样获益","renal":"eGFR <20 不推荐起始；已用药者可继续至透析前","hepatic":"重度肝损害不推荐","interact":"与利尿剂合用注意容量不足；与胰岛素/磺脲类合用需减量以防低血糖"},{"name":"呋塞米","dose":"20–40 mg qd 口服（水肿明显者 20 mg bid 或静脉 40 mg 推注，按尿量与体重调整）","note":"缓解淤血症状，不改善预后；以最小有效剂量维持干体重","renal":"eGFR 下降时常需加量；监测电解质与肾功能","hepatic":"肝硬化者注意低钾与肝性脑病诱因","interact":"与氨基糖苷类合用增加耳肾毒性；与锂剂合用升高血锂"},{"name":"阿司匹林","dose":"75–100 mg qd 口服","note":"冠心病二级预防；合并房颤需抗凝者评估联合方案","renal":"CKD 无需调整；透析者出血风险高","hepatic":"严重肝病慎用","interact":"与抗凝药、NSAID 合用增加出血"},{"name":"阿托伐他汀","dose":"40 mg qn 口服，目标 LDL-C <1.4 mmol/L","note":"所有缺血性心肌病患者均应强化降脂","renal":"CKD 1–3 期无需调整；4–5 期减量","hepatic":"活动性肝病禁用","interact":"与克拉霉素、环孢素合用增加肌病风险"}],"nonDrug":["血运重建：多支病变伴存活心肌者优先 CABG（STICH 试验支持），解剖适合且 SYNTAX 评分低者可选 PCI；以瘢痕为主者血运重建获益有限","ICD 一级预防：优化药物治疗 ≥3 个月后 LVEF ≤35%、NYHA Ⅱ–Ⅲ 级、预期生存 >1 年","CRT：窦性心律、QRS ≥150 ms、LBBB 形态、LVEF ≤35% 者获益最大","机械循环支持与心脏移植：难治性终末期心衰的评估指征","容量管理：每日称重，体重 3 天内增加 >2 kg 需调整利尿剂"],"life":["限盐 <5 g/d、限液（顽固性低钠者 1.5–2 L/d），每日监测体重与尿量","戒烟限酒；流感与肺炎球菌疫苗接种","心脏康复：病情稳定后每周 ≥150 min 中等强度运动，避免剧烈用力","定期随访：每 1–3 个月评估 NYHA 分级、血压、心率、肾功能、电解质与 BNP"]},"prog":"缺血性心肌病预后与 LVEF、NYHA 分级、存活心肌比例及是否血运重建相关。未血运重建者 5 年死亡率可达 50%；规范药物联合血运重建（尤其 CABG）可改善症状与长期生存，但围术期风险高于单纯药物治疗。","refs":["《中国心力衰竭诊断和治疗指南 2024》（中华医学会心血管病学分会）","2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure","2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure","STICH Trial（N Engl J Med 2011；长期随访 2016）","《稳定性冠心病诊断与治疗指南》（中华医学会心血管病学分会，2018）"]}]},{"id":"hf_right","name":"右心衰竭","rank":45,"summary":"右心衰以体循环淤血与右室射血能力下降为核心，诊断靠颈静脉压升高、肝大、下肢水肿加右室结构与功能指标（TAPSE、RVFAC、RV S′）；治疗首要是病因（左心衰、肺高压、右室梗死、ARVC），容量管理用利尿剂但须避免过度降低前负荷，肺高压相关者加靶向药物，右室梗死忌硝酸酯与过度利尿。","compare":[],"diseases":[{"id":"hf_right_failure","name":"右心衰竭","aka":["Right Heart Failure","RHF","右心功能不全","右心室衰竭"],"rank":1,"basic":{"define":"右心室充盈或射血功能受损，不能维持正常的肺循环血流与中心静脉压，引起以体循环淤血为主的临床综合征。可孤立存在（右室梗死、致心律失常性右室心肌病、肺高压），也可继发于左心衰竭。","risk":["左心衰竭（最常见，占右心衰的大多数）","肺动脉高压（WHO 第 1、4 组为主，慢性血栓栓塞性与先心病相关亦常见）","右室心肌梗死（下壁 MI 累及右室）","致心律失常性右室心肌病（ARVC）","右心瓣膜病（重度三尖瓣反流、肺动脉瓣狭窄）与先天性分流（ASD）","脓毒症、ARDS、急性肺栓塞所致急性肺心病"],"epi":"慢性心力衰竭患者中约 30%–50% 合并不同程度右室功能不全，右室功能是预后独立预测因子；下壁心肌梗死中约 30%–50% 累及右室，急性肺栓塞中约 1/3–1/2 出现右室功能不全。"},"patho":"右室壁薄、顺应性高，对急性后负荷升高耐受差：肺栓塞或急性肺高压时右室急性扩张、室间隔左移、左室充盈受限，心输出量骤降而表现为休克。慢性后负荷升高引起右室肥厚、扩张与继发性三尖瓣反流，右房压升高致颈静脉怒张、肝大、腹水与下肢水肿。右室扩张使心包内压升高，通过心室相互依赖进一步限制左室充盈，形成右心衰加重左心衰的恶性循环。右室梗死时右室收缩力下降且高度依赖前负荷，硝酸酯、利尿剂或麻醉易诱发严重低血压。","dx":{"criteria":["**体循环淤血体征**：颈静脉压 >8 cmH₂O（颈静脉怒张、半卧位仍充盈）、肝颈静脉回流征阳性、肝大伴压痛、下肢凹陷性水肿、腹水、胸水","**右室奔马律与杂音**：胸骨左缘第 3–4 肋间右室 S3、三尖瓣反流性收缩期杂音（吸气增强）、P2 亢进提示肺高压","**超声心动图**：TAPSE <17 mm、RVFAC <35%、RV S′ <9.5 cm/s、右室基底段内径 >41 mm、右室/左室比值 >1、下腔静脉充盈且随呼吸塌陷率 <50%","**右心导管**：右房压 >8 mmHg、肺动脉楔压（PAWP）≤15 mmHg 提示单纯右心衰；心指数 <2.2 L/min/m²、右室每搏功指数降低提示低心排；平均肺动脉压 >20 mmHg 诊断肺高压","**生物标志物**：BNP/NT-proBNP 升高（右室壁应力），NT-proBNP 受肾功能影响，需结合 eGFR 解读；肌钙蛋白升高提示右室缺血或心肌损伤","**心电图**：电轴右偏、V1 高 R 波、右室劳损型 ST-T 改变；下壁 MI 者 V4R 导联 ST 段抬高 ≥1 mm（≥0.5 mm 即高度提示）提示右室梗死","**排除其他水肿原因**：心包压塞、缩窄性心包炎、三尖瓣器质性病变、肝硬化、肾病综合征、甲状腺功能减退"],"workup":["经胸超声心动图为首选：右室大小与功能（TAPSE、RVFAC、S′、三维 RVEF）、三尖瓣反流速度估肺动脉收缩压、室间隔运动、下腔静脉","心电图加做 V4R、V7–V9（疑下壁/右室梗死），BNP/NT-proBNP、肌钙蛋白、血气、乳酸、肾功能与电解质","右心导管：鉴别毛细血管前与毛细血管后肺高压（mPAP、PAWP、PVR、心输出量），肺高压靶向治疗前必须完成","心脏 MRI：ARVC 诊断（右室扩大、局部室壁运动异常、脂肪浸润、RVEF ≤45%）、右室纤维化与右室容积定量","疑肺栓塞查 D-二聚体与 CTPA；疑睡眠呼吸障碍行夜间血氧/多导睡眠监测；疑肝硬化行肝功能与门脉评估"],"grading":"按起病分急性（右室梗死、急性肺栓塞、心脏术后、脓毒症）与慢性（左心衰、肺高压、ARVC、右心瓣膜病）；按病因分左心衰相关、肺高压相关、右室缺血/梗死、心肌病、右心瓣膜病、先天性分流；按严重度依 TAPSE、RVFAC、右房压与心指数分层，TAPSE <17 mm、RVFAC <35%、右房压 >15 mmHg、CI <2.2 L/min/m² 提示高危。"},"ddx":[{"name":"射血分数降低的心力衰竭（hf_hfref）","point":"与本类外最易混淆的邻类疾病鉴别：左心衰以肺淤血为主（端坐呼吸、夜间阵发性呼吸困难、肺底湿啰音），LVEF <40%、左室扩大；右心衰以体循环淤血为主、肺野清晰、LVEF 多保留。晚期两者常并存，需超声与右心导管判断以谁为主。"},{"name":"急性心力衰竭与心源性休克（hf_acute）","point":"急性左心衰以急性肺水肿、粉红色泡沫痰、SpO₂ 下降为主；急性右心衰以低血压、颈静脉怒张、肺野清晰为特征，两者均可低心排，容量反应性相反。"},{"name":"缩窄性心包炎（pc_constrictive）","point":"同样有颈静脉怒张、肝大、腹水，但超声见心包增厚/钙化、室间隔抖动、二尖瓣 E 峰呼吸变异 >25%，右室不大、BNP 多正常或轻度升高；右心衰右室扩大、BNP 明显升高。"},{"name":"心包积液与心脏压塞（pc_effusion）","point":"压塞有奇脉（吸气收缩压下降 >10 mmHg）、心音低钝、超声心包积液与右房/右室舒张期塌陷；右心衰无奇脉、无积液。"},{"name":"三尖瓣与肺动脉瓣疾病（vhd_tv）","point":"原发性三尖瓣病变（Ebstein、类癌、感染性心内膜炎）以三尖瓣结构异常为主，右室大小可正常；继发性三尖瓣反流为右室扩大的结果，需判断因果。"},{"name":"肺动脉高压（ph_group）","point":"肺高压是右心衰最常见病因之一，右心导管 mPAP >20 mmHg、PVR >3 WU 确诊；右心衰是其结果，二者为因果而非并列诊断。"},{"name":"致心律失常性右室心肌病（cm_arvc）","point":"ARVC 以右室扩大、局部运动异常、epsilon 波、右胸导联 T 波倒置及室性心律失常为特征，心脏 MRI 与基因检测可鉴别；单纯右心衰无这些电学与结构特征。"},{"name":"肝硬化或肾病综合征","point":"两者均有腹水与下肢水肿，但颈静脉压正常、无肝颈静脉回流征，超声右室大小与功能正常，结合肝功能、尿蛋白可鉴别。"}],"tx":{"drug":[{"name":"呋塞米","dose":"口服 20–40 mg qd–bid；静脉 20–40 mg 缓慢推注，按尿量与体重滴定，顽固性水肿可 2.5–5 mg/h 持续泵入","note":"目标为每日体重下降 0.5–1.0 kg；右心衰对前负荷敏感，过度利尿可致心输出量与血压下降，需监测颈静脉压、尿量、电解质与肾功能","renal":"CrCl <30 mL/min 常需加量或改用托拉塞米；无尿者禁用","hepatic":"肝硬化合并右心衰者避免过度利尿与低钾（诱发肝性脑病）","interact":"NSAIDs 减弱利尿效应；与地高辛合用低钾致洋地黄中毒；与氨基糖苷类合用耳肾毒性增加"},{"name":"托拉塞米","dose":"口服 10–20 mg qd；静脉 10–20 mg/d，按利尿反应调整，最大 100–200 mg/d","note":"生物利用度高于呋塞米，口服与静脉等效；适用于呋塞米抵抗的顽固性水肿","renal":"CrCl <30 mL/min 时减量并延长间隔","hepatic":"重度肝损减量，监测电解质","interact":"与地高辛、锂剂合用需监测浓度"},{"name":"螺内酯","dose":"20 mg qd，最大 50 mg qd","note":"适用于慢性右心衰合并继发性醛固酮增多；eGFR <30 mL/min 或血钾 >5.0 mmol/L 时禁用","renal":"eGFR <30 禁用；监测肌酐与血钾","hepatic":"肝功能不全者慎用（代谢减慢）","interact":"与 ACEI/ARB、补钾剂合用致高钾；与地高辛合用升高地高辛浓度"},{"name":"托伐普坦","dose":"15 mg qd 起始，按血钠与尿量调整，最大 60 mg qd","note":"用于合并低钠血症（血钠 <130 mmol/L）的顽固性容量负荷；24 小时血钠升高不超过 8–10 mmol/L，避免渗透性脱髓鞘","renal":"CrCl <10 mL/min 不推荐","hepatic":"肝病相关腹水者慎用，重度肝损不推荐","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素）升高血药浓度"},{"name":"去甲肾上腺素","dose":"0.05–0.5 µg·kg⁻¹·min⁻¹ 静脉泵入，维持 MAP ≥65 mmHg","note":"右室梗死或急性右心衰合并休克时恢复右室冠脉灌注压的首选升压药；避免单独使用大剂量致肺血管阻力升高","renal":"按血流动力学滴定，无固定调整","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用可致高血压危象；与 β 阻滞剂合用减弱正性肌力"},{"name":"多巴酚丁胺","dose":"2–5 µg·kg⁻¹·min⁻¹ 静脉泵入，按心输出量与血压滴定","note":"用于右室收缩力下降伴低心排；可因 β₂ 扩血管作用降低体循环阻力，右室梗死时需与去甲肾上腺素联用","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂合用失效；与硝酸酯类合用加重低血压"},{"name":"米力农","dose":"0.375–0.75 µg·kg⁻¹·min⁻¹ 静脉泵入（常用 0.5 µg·kg⁻¹·min⁻¹）","note":"磷酸二酯酶Ⅲ抑制剂，肺高压相关右心衰可降低肺血管阻力，但体循环低血压与心律失常常见，需有创监测","renal":"按 CrCl 减量 30%–50%，CrCl <30 慎用","hepatic":"重度肝损减量","interact":"与利尿剂合用加重低钾；与 β 激动剂合用增加心律失常"},{"name":"西地那非","dose":"20 mg tid，间隔 4–6 小时，最大 80 mg tid","note":"仅用于右心导管确诊的肺动脉高压相关右心衰；禁与硝酸酯类、利奥西呱合用；注意体循环低血压、视力异常与听力下降","renal":"CrCl <30 mL/min 减量或慎用","hepatic":"Child-Pugh C 禁用","interact":"禁与硝酸酯类、利奥西呱合用（严重低血压）；CYP3A4 抑制剂升高其浓度"},{"name":"波生坦","dose":"62.5 mg bid 起始 4 周，耐受后 125 mg bid；体重 <40 kg 者 31.25 mg bid 起始","note":"内皮素受体拮抗剂，用于 WHO 第 1、4 组肺高压相关右心衰；每月监测肝酶，ALT/AST >3 倍正常上限需停药；致畸，女性需避孕","renal":"肾功能不全无需调整","hepatic":"中重度肝损禁用；治疗期间监测肝酶","interact":"CYP3A4 抑制剂（酮康唑）升高浓度；与格列本脲合用致肝毒性；降低华法林、西地那非浓度"},{"name":"马昔腾坦","dose":"10 mg qd","note":"长效内皮素受体拮抗剂，肝酶升高与体液潴留风险低于波生坦；致畸，需 REMS 式避孕管理；血红蛋白下降需监测","renal":"重度肾功能不全慎用","hepatic":"中重度肝损（Child-Pugh B/C）不推荐","interact":"CYP3A4 强抑制剂合用需谨慎；与 CYP3A4 诱导剂合用降低疗效"},{"name":"利奥西呱","dose":"1 mg tid 起始，每 2 周增加 0.5 mg，最大 2.5 mg tid","note":"可溶性鸟苷酸环化酶激动剂，用于第 1、4 组肺高压；禁与 PDE5 抑制剂联用；低血压、咯血需警惕","renal":"CrCl <30 mL/min 不推荐","hepatic":"Child-Pugh B/C 禁用","interact":"禁与西地那非、他达拉非合用；与硝酸酯类合用致严重低血压"},{"name":"地高辛","dose":"0.125 mg qd，肾功能不全者 0.0625 mg qd 或隔日","note":"用于合并房颤控制心室率或右心衰伴收缩功能不全；右心衰时对洋地黄敏感性增加，治疗窗窄","renal":"按 CrCl 减量，CrCl <30 慎用并监测血药浓度","hepatic":"遵说明书","interact":"低钾、低镁、高钙增强毒性；与胺碘酮、维拉帕米、克拉霉素合用升高浓度"}],"nonDrug":["病因治疗：急性右室梗死尽早再灌注（PCI），急性肺栓塞按危险分层抗凝、溶栓或介入取栓，ARVC 行抗心律失常与 ICD 评估，左心衰按指南规范治疗，重度三尖瓣反流行瓣膜成形或置换","机械循环支持：药物难治性右心衰/心源性休克使用右室辅助装置（RVAD）或 VA-ECMO，作为恢复或移植桥接","房间隔造口术：重度肺高压反复晕厥或右心衰、靶向治疗无效者，作为肺移植桥接（风险高，需专科中心）","肺移植或心肺移植：终末期肺高压或右心衰，规范药物治疗仍为 WHO 功能Ⅳ级者","ICD：ARVC 及猝死高危者；超滤或血液净化用于顽固性容量负荷合并肾功能不全"],"life":["限钠 2–3 g/d，每日晨起称重，3 天内体重增加 >2 kg 或水肿加重需就诊","肺高压相关者避免脱水、高温、热水浴与突然停用靶向药物（可致反跳）","氧疗维持 SpO₂ ≥90%（艾森门格综合征另按右向左分流管理）","每 1–3 个月复查超声、BNP 与肾功能，肺高压者每 3–6 个月评估 6 分钟步行距离与 WHO 功能分级","避免妊娠：重度肺高压与右心衰妊娠死亡率高，需严格避孕"]},"prog":"右室功能是心力衰竭与肺高压预后的独立决定因素：TAPSE <17 mm、右房压 >15 mmHg、心指数 <2.0 L/min/m² 者 1 年死亡率显著升高。右室梗死及时再灌注后右室功能多在数周内恢复，预后较好；肺高压相关右心衰预后最差，特发性肺动脉高压未靶向治疗的中位生存约 2.8 年，规范靶向治疗后明显改善。","refs":["中华医学会心血管病学分会：右心衰竭诊断和治疗中国专家共识（2012）","中华医学会心血管病学分会心力衰竭学组：中国心力衰竭诊断和治疗指南 2024","中华医学会心血管病学分会肺血管病学组：中国肺动脉高压诊断与治疗指南（2021 版）","2022 ESC/ERS Guidelines for the diagnosis and treatment of pulmonary hypertension"]}]},{"id":"ar_sinus_jx","name":"窦性与交界区心律失常","rank":46,"summary":"窦性与交界区心律失常多为继发性或良性：窦速先找病因（发热、贫血、甲亢、低容量、药物），不强行减慢心率；交界区早搏通常无需治疗，关键是和房早伴差异传导鉴别；交界区逸搏是次级起搏点的代偿，频率 40–60 次/分，处理重点是病因（洋地黄中毒、下壁心梗、心肌炎、术后）与是否需要起搏。","compare":[{"diseaseId":"ar_sinus_tachy","dx":"窦性心律、静息心率 >100 次/分，P 波形态正常、渐起渐止，多为继发性","key":"先纠正病因（发热、贫血、甲亢、低容量、药物），不强行减慢心率；仅不适当窦速用伊伐布雷定"},{"diseaseId":"ar_junctional_pac","dx":"提前出现的窄 QRS，无窦性 P 波或逆行 P（PR <0.12 s），多有完全代偿间歇","key":"单个提前搏动、通常无需治疗；与房早伴室内差异传导的鉴别靠前置异位 P 波"},{"diseaseId":"ar_junctional_escape","dx":"长间歇后出现、连续 ≥3 个窄 QRS，频率 40–60 次/分，P 波缺失或逆行","key":"逸搏是代偿现象，治病因与灌注；症状性、不可逆者需起搏"}],"diseases":[{"id":"ar_sinus_tachy","name":"窦性心动过速","aka":["Sinus Tachycardia","窦速","不适当窦性心动过速","Inappropriate Sinus Tachycardia","IST"],"rank":1,"basic":{"define":"窦房结发放冲动频率增快，成人静息心率 >100 次/分，每个 QRS 前有正常形态窦性 P 波。多数为生理性或继发性代偿，少数为不适当窦性心动过速（IST）。","risk":["发热与感染（体温每升高 1 ℃ 心率约增 10 次/分）、脓毒症","有效血容量不足：失血、脱水、过度利尿、呕吐腹泻","贫血（Hb <90 g/L 时心率增快明显）、甲亢","疼痛、焦虑、低氧、肺栓塞、心力衰竭、心肌炎、心包炎","药物与兴奋剂：阿托品、β₂ 受体激动剂、氨茶碱、甲状腺素过量、咖啡因、酒精、可卡因","不适当窦速多见于年轻女性，常伴直立不耐受"],"epi":"窦性心动过速是临床最常见的心动过速，住院患者中约 1/3 存在不同程度窦速；不适当窦速在女性中约占 90%，多见于 20–40 岁，多数患者长期被误诊为焦虑症。"},"patho":"交感张力增高、迷走张力降低或窦房结固有自律性增高（If 电流增强、窦房结超速）使心率增快。继发性窦速是维持心输出量的代偿反应，此时强行减慢心率可致血压下降与组织灌注不足。持续心率 >100 次/分数周至数月可致心动过速性心肌病，表现为 LVEF 下降、左室扩大，控制心率后多可逆转。IST 患者对迷走刺激反应减弱、对 β 阻滞剂反应不完全，机制涉及窦房结起搏细胞自律性增高与自主神经调节异常。","dx":{"criteria":["成人静息 12 导联心电图心率 >100 次/分（常见 100–150 次/分，运动时可达按年龄预测的最大心率 220−年龄）","每个 QRS 前有正常形态 P 波：Ⅰ、Ⅱ、aVF 直立，aVR 倒置；PR 间期 0.12–0.20 s，QRS <0.12 s","起始与终止渐起渐止（与折返性心动过速的突发突止不同），心率随活动、情绪、发热波动","必须除外继发因素：血常规、铁蛋白、甲状腺功能（TSH、FT3、FT4）、电解质、血气、D-二聚体、超声心动图","不适当窦速诊断：24 小时 Holter 平均心率 >90 次/分、白天 >100 次/分，轻微活动即 >100 次/分，P 波形态正常，排除所有继发原因","体位性心动过速综合征（POTS）：卧位心率正常，站立 10 分钟内增加 ≥30 次/分（12–19 岁 ≥40 次/分）或 >120 次/分，伴直立不耐受","心动过速性心肌病：心率持续 >100 次/分达数周至数月，LVEF <50% 且无其他心肌病证据，控制心率后 LVEF 恢复"],"workup":["12 导联心电图与长条记录，比较不同时间、不同体位的心率与 P 波形态","24–72 小时动态心电图：平均心率、白天/夜间心率、心率变异性，判断是否 IST 或 POTS","甲状腺功能、血常规、铁蛋白、电解质、肾功能、血气；疑肺栓塞查 D-二聚体与 CTPA","超声心动图：除外结构性心脏病、评估 LVEF（心动过速性心肌病）与右室负荷","详细药物与兴奋剂史（含感冒药、减肥药、能量饮料、甲状腺素），疑 POTS 行直立倾斜试验"],"grading":"按机制分生理性（运动、妊娠、情绪）、继发性病理性（发热、贫血、甲亢、低容量、药物）、不适当窦速与 POTS；按心率水平分轻度（100–120 次/分）、中度（120–150 次/分）、重度（>150 次/分）；按并发症分是否合并心动过速性心肌病。"},"ddx":[{"name":"房室交界区性期前收缩（ar_junctional_pac）","point":"与本类 ar_junctional_pac 鉴别：交界性早搏是提前出现的单个窄 QRS，无窦性 P 波或为逆行 P，其后有代偿间歇；窦速为持续、规则、P 波形态正常的快速心律。"},{"name":"房室交界区性逸搏心律（ar_junctional_escape）","point":"与本类 ar_junctional_escape 鉴别：逸搏心律频率 40–60 次/分，出现在长间歇之后，P 波缺失或逆行；窦速心率 >100 次/分且由窦性 P 波驱动。"},{"name":"房性心动过速（ar_at）","point":"房速 P 波形态与窦性不同（Ⅱ、Ⅲ、aVF 可倒置），心率 150–250 次/分，突发突止，可见温醒现象；窦速 P 波正常、渐起渐止。"},{"name":"心房扑动 2∶1 传导（ar_af_flutter）","point":"心室率多在 150 次/分且固定，下壁导联见锯齿状 F 波、等电位线消失；窦速有明确等电位线与正常 P 波，按压颈动脉窦后窦速渐减慢、房扑可暴露 F 波。"},{"name":"房室结折返性心动过速（ar_psvt）","point":"突发突止，心率 150–250 次/分，P 波常埋于 QRS 或 RP <70 ms；窦速为渐起渐止、P 波清晰可见。"},{"name":"甲状腺功能亢进","point":"窦速伴 TSH 降低、FT3/FT4 升高、脉压增大、体重下降、震颤与怕热；甲亢是窦速的可治病因，需先控制甲亢。"},{"name":"体位性心动过速综合征（POTS）","point":"卧位心率正常，直立后心率增加 ≥30 次/分并伴头晕、心悸、乏力，无直立性低血压；窦速在卧位即 >100 次/分。"}],"tx":{"drug":[{"name":"伊伐布雷定","dose":"起始 2.5–5 mg bid，每 2–4 周按心率调整，最大 7.5 mg bid；不适当窦速常用 5 mg bid","note":"选择性 If 通道抑制剂，仅用于窦性心律：不适当窦速（排除继发原因、心率 >100 次/分且症状明显，属超说明书用药，需知情同意）或 HFrEF 窦性心律、LVEF ≤35%、心率 ≥70 次/分且已用最大耐受 β 阻滞剂；房颤/房扑、病态窦房结综合征禁用；视网膜闪光感发生率约 2%–14%","renal":"CrCl 15–60 mL/min 起始 2.5 mg bid；CrCl <15 mL/min 不推荐","hepatic":"Child-Pugh C 禁用，Child-Pugh A/B 起始 2.5 mg bid","interact":"CYP3A4 抑制剂（克拉霉素、酮康唑、地尔硫䓬）显著升高浓度；与延长 QT 药物合用增加心律失常风险；葡萄柚汁升高浓度"},{"name":"美托洛尔","dose":"缓释片 23.75–47.5 mg qd 起始，按心率调整至 95 mg qd；普通片 12.5–25 mg bid","note":"用于交感张力增高或症状性 IST，但 IST 疗效有限，过度减慢心率可致乏力与运动耐量下降；哮喘、重度心动过缓、失代偿心衰慎用","renal":"肾功能不全无需调整","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用致心动过缓与传导阻滞；CYP2D6 抑制剂（帕罗西汀、氟西汀）升高浓度"},{"name":"比索洛尔","dose":"1.25–2.5 mg qd 起始，最大 10 mg qd","note":"高选择性 β₁ 阻滞剂，适合需长期控制交感兴奋者；支气管痉挛性疾病慎用","renal":"CrCl <20 mL/min 最大 10 mg qd 且需监测","hepatic":"重度肝损最大 10 mg qd","interact":"与非二氢吡啶类钙拮抗剂合用致心动过缓；与胰岛素合用掩盖低血糖症状"},{"name":"普萘洛尔","dose":"10–20 mg q6–8h 口服，按心率调整","note":"甲亢所致窦速首选，兼可抑制外周 T4 向 T3 转化；哮喘、 COPD 禁用；长期使用突然停药可致反跳","renal":"肾功能不全无需调整","hepatic":"肝硬化者减量（首过效应降低）","interact":"与利血平合用致严重心动过缓；与甲状腺素合用需调整剂量"},{"name":"地尔硫䓬","dose":"普通片 30 mg tid，最大 90 mg tid；缓释片 90 mg qd 起始","note":"β 阻滞剂禁忌或不耐受时的替代，用于 IST 症状控制；LVEF <40%、房室传导阻滞者禁用","renal":"肾功能不全无需调整","hepatic":"肝硬化者减量，监测血压与心率","interact":"CYP3A4 抑制剂升高浓度；与 β 阻滞剂合用致心动过缓与心衰"}],"nonDrug":["病因治疗是核心：退热、补液/输血、纠正贫血与甲亢、停用致病药物（咖啡因、减肥药、β₂ 激动剂）、治疗肺栓塞与心衰，多数窦速随病因而缓解","不适当窦速：先做 3 个月以上生活方式调整（睡眠、运动训练、避免兴奋剂、补液与限咖啡因），药物无效且症状严重者可行窦房结改良消融（并发症包括窦缓需起搏，需严格选择）","POTS：增加盐水摄入 2–3 L/d、弹力袜、倾斜训练，必要时用米多君或低剂量 β 阻滞剂","心动过速性心肌病：控制心率（β 阻滞剂或伊伐布雷定）后 3–6 个月复查超声，多数 LVEF 恢复","禁止对继发性窦速使用电复律或强效减慢心率药物（可致血流动力学崩溃）"],"life":["减少咖啡因、酒精、尼古丁与能量饮料；保证睡眠、避免过度疲劳与焦虑","每日监测静息心率与血压，记录症状（心悸、头晕、活动耐量）与心率的关系","甲亢、贫血、发热等病因治疗后 4–6 周复查心电图与心率","IST 患者避免竞技性耐力运动诱发心率持续升高，可进行规律有氧训练降低交感张力","妊娠期窦速常见（血容量增加、心率增快 10–20 次/分），以病因评估为主，β 阻滞剂需产科与心内科共同决策"]},"prog":"生理性与继发性窦速在病因去除后多完全恢复，不遗留心脏结构损害。不适当窦速症状常迁延，约半数患者需长期药物控制，窦房结消融的有效率约 70%–80% 但约 10%–20% 术后需起搏。持续心率 >100 次/分数月者可发展为可逆性心动过速性心肌病，早期识别并控制心率后预后良好。","refs":["中华医学会心血管病学分会、中国生物医学工程学会心律分会：抗心律失常药物临床应用中国专家共识（2023）","中华医学会心血管病学分会心力衰竭学组：中国心力衰竭诊断和治疗指南 2024（伊伐布雷定部分）","2019 ESC Guidelines for the management of patients with supraventricular tachycardia","2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia"]},{"id":"ar_junctional_pac","name":"房室交界区性期前收缩","aka":["Premature Junctional Complex","PJC","交界性早搏","Junctional Premature Beat"],"rank":2,"basic":{"define":"房室交界区（房室结及希氏束分叉以上）起搏点提前发放冲动，产生提前出现的窄 QRS 波，其前无窦性 P 波或伴逆行 P 波。属良性异位搏动，多数无需治疗。","risk":["迷走张力增高、疲劳、情绪应激、咖啡因与酒精","洋地黄过量（最常见的药物原因）、β 阻滞剂或非二氢吡啶类钙拮抗剂过量","低钾血症、低镁血症","下壁心肌缺血/梗死、心肌炎、心肌病","心脏手术（尤其房室结附近）、导管消融或右心导管术后","老年传导系统退行性变"],"epi":"健康成人 24 小时动态心电图中交界性早搏通常少于总心搏的 1%，多无临床意义；随年龄增长、洋地黄使用与心脏手术后检出率升高，频发者（>10% 总心搏）少见。"},"patho":"交界区起搏细胞（房结区、结希区）4 相自动除极加速或发生触发活动，提前发放冲动。冲动经希氏束下传心室产生窄 QRS（与窦性相同），同时逆传心房产生逆行 P 波（Ⅱ、Ⅲ、aVF 倒置、aVR 直立）；因逆传速度慢于下传，P 波常位于 QRS 之后（RP <0.20 s）或埋于 QRS 中。若伴室内差异传导，QRS 可增宽呈右束支阻滞型，易误判为室性早搏。频发交界性早搏可使房室同步丧失、每搏量下降，产生心悸；极频发者可致心动过速性心肌病。","dx":{"criteria":["提前出现的 QRS 波，形态与窦性相同或相近，QRS 时限 <0.12 s","其前无窦性 P 波；若有 P 波则为逆行 P（Ⅱ、Ⅲ、aVF 倒置、aVR 直立），PR <0.12 s 或 RP <0.20 s","代偿间歇多数完全：早搏前后窦性 P-P 间期等于 2 倍正常 P-P 间期","伴室内差异传导时 QRS ≥0.12 s，多呈右束支阻滞图形，需与室性早搏鉴别","频发标准：动态心电图 >30 次/小时，或 >10% 总心搏；成对出现或连续 3 个以上为交界性心动过速（>100 次/分）","必须评估可逆原因：血钾、血镁、地高辛血药浓度（>2.0 ng/mL 提示中毒）、肌钙蛋白与超声心动图"],"workup":["12 导联心电图加长条记录，逐搏确认 P 波位置与代偿间歇，与窦性 QRS 形态比对","24–72 小时动态心电图：早搏负荷、成对/短阵、与症状的相关性","电解质（钾、镁、钙）、肾功能、地高辛血药浓度（使用洋地黄者）","超声心动图：除外结构性心脏病、评估房室瓣与心房大小","运动试验：观察早搏是否随运动增多或诱发室速（提示需进一步评估）"],"grading":"按频率分偶发（<30 次/小时或 <1% 总心搏）、频发（>30 次/小时或 >10% 总心搏）；按形态分单发、成对、短阵交界性心动过速；按病因分功能性（迷走张力、兴奋剂）与器质性/药物性（洋地黄中毒、缺血、术后）。"},"ddx":[{"name":"窦性心动过速（ar_sinus_tachy）","point":"与本类 ar_sinus_tachy 鉴别：窦速为持续性规则心律、每个 QRS 前有正常窦性 P 波；交界性早搏是提前的单次搏动，其后节律被重整，基础心率可正常。"},{"name":"房室交界区性逸搏心律（ar_junctional_escape）","point":"与本类 ar_junctional_escape 鉴别：二者同源于交界区但时机相反——逸搏在长间歇后延迟出现（频率 40–60 次/分），早搏则提前出现（联律间期短于窦性周期）。"},{"name":"房性期前收缩伴室内差异传导（ar_pac）","point":"房早有提前的异位 P 波（形态与窦性不同，Ⅱ、Ⅲ、aVF 可直立），PR 常 >0.12 s，多为不完全代偿间歇；交界性早搏无 P 波或为逆行 P（PR <0.12 s），代偿间歇多完全。"},{"name":"室性期前收缩（ar_pvc）","point":"室早 QRS 宽大畸形 ≥0.12 s、T 波与主波方向相反、其前无 P 波、代偿间歇完全；差异传导的交界性早搏需靠前置逆行 P 波与既往心电图 QRS 形态鉴别。"},{"name":"房室结折返性心动过速（ar_psvt）","point":"AVNRT 为连续快速心律（150–250 次/分）、突发突止；交界性早搏仅为单个或成对提前搏动，不形成持续心动过速。"},{"name":"洋地黄中毒性心律失常","point":"除交界性早搏外常有恶心、呕吐、黄视、PR 延长、鱼钩样 ST 改变与血药浓度 >2.0 ng/mL，减量或停药后早搏减少。"}],"tx":{"drug":[{"name":"美托洛尔","dose":"12.5–25 mg bid 口服，按心率与症状调整","note":"仅用于症状明显、频发且无禁忌者；多数患者无需用药。注意心动过缓、乏力与掩盖低血糖","renal":"肾功能不全无需调整","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用致心动过缓；CYP2D6 抑制剂升高浓度"},{"name":"比索洛尔","dose":"1.25–2.5 mg qd 起始，最大 5 mg qd","note":"用于频发交界性早搏伴交感兴奋或心悸明显者；哮喘患者慎用","renal":"CrCl <20 mL/min 减量","hepatic":"重度肝损减量","interact":"与非二氢吡啶类钙拮抗剂合用致传导阻滞"},{"name":"氯化钾","dose":"口服 10% 氯化钾 10–20 mL tid，或静脉补钾（浓度 ≤0.3%，速度 ≤20 mmol/h），目标血钾 4.0–5.0 mmol/L","note":"仅用于低钾相关早搏；补钾前确认尿量 >30 mL/h，肾功能不全者减慢速度并监测血钾","renal":"肾功能不全者减量并密切监测，避免高钾","hepatic":"遵说明书","interact":"与 ACEI/ARB、螺内酯合用增加高钾风险；与地高辛合用需监测"},{"name":"地高辛特异性抗体片段（Digoxin Immune Fab）","dose":"按血清地高辛浓度与体重依说明书公式计算，严重中毒（血流动力学不稳、高钾、室性心律失常）时使用，具体剂量需专科会诊","note":"仅用于洋地黄中毒所致心律失常；用药后血钾与地高辛检测值失真，需临床判断","renal":"肾功能不全者药物清除延迟，需延长观察","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["无症状者无需治疗，仅解释与定期随访；去除诱因（咖啡因、酒精、疲劳、应激）","停用或减量可疑药物：洋地黄、β 阻滞剂、非二氢吡啶类钙拮抗剂、茶碱","纠正电解质紊乱（低钾、低镁）与心肌缺血；下壁心梗者尽早再灌注","频发（>10%–15% 总心搏）伴明显症状、药物无效者，可考虑射频消融交界区异位灶（需权衡房室传导损伤风险）","合并结构性心脏病或早搏负荷高者每年复查超声与动态心电图"],"life":["避免过量咖啡因、酒精与能量饮料，规律作息、减少熬夜与精神应激","记录心悸发作的时间、诱因与持续时间，复诊时提供动态心电图结果","使用洋地黄者定期监测血药浓度、血钾与肾功能，出现恶心、黄视、心悸加重及时就诊","无需限制一般体力活动；合并器质性心脏病者按原发病管理"]},"prog":"孤立性交界性早搏属良性，不增加心血管死亡风险，多数随诱因去除而减少。洋地黄中毒或急性缺血所致者在纠正病因后可消失；频发早搏（>10% 总心搏）长期存在者少数可发展为交界性心动过速或心动过速性心肌病，射频消融后预后良好。","refs":["中华医学会心血管病学分会、中国生物医学工程学会心律分会：抗心律失常药物临床应用中国专家共识（2023）","2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia","《内科学》（第 9 版，人民卫生出版社，2018）","中华医学会心血管病学分会：中国心力衰竭诊断和治疗指南 2024（洋地黄中毒处理部分）"]},{"id":"ar_junctional_escape","name":"房室交界区性逸搏心律","aka":["Junctional Escape Rhythm","交界性逸搏心律","交界区逸搏","加速性交界区心律","Accelerated Junctional Rhythm"],"rank":3,"basic":{"define":"窦房结冲动形成或传导障碍时，房室交界区作为次级起搏点被动发放冲动，连续 3 个以上、频率 40–60 次/分的窄 QRS 心律。逸搏本身是生理性代偿，临床意义取决于基础病因与血流动力学。","risk":["病态窦房结综合征、窦性停搏或严重窦性心动过缓","Ⅱ度Ⅱ型或Ⅲ度房室传导阻滞","下壁心肌梗死（房室结缺血）、心肌炎","心脏手术（房室结附近）、导管消融或右心导管术后","洋地黄过量、β 阻滞剂或非二氢吡啶类钙拮抗剂过量","高钾血症、颈动脉窦过敏、血管迷走性晕厥、睡眠呼吸暂停（夜间迷走张力增高）"],"epi":"交界区固有逸搏频率为 40–60 次/分（希氏束起搏 40–50 次/分），加速性交界区心律 60–100 次/分，交界区心动过速 >100 次/分。下壁心肌梗死合并房室传导阻滞者约 10%–20%，多在再灌注后 24–72 小时恢复；老年人以传导系统退行性变与药物过量为主。"},"patho":"窦房结频率低于交界区固有频率，或窦性冲动不能下传时，交界区起搏细胞 4 相自动除极达阈值而逸搏，属保护性机制。冲动经希氏束下传产生窄 QRS，逆传心房产生逆行 P 波；因逆传慢于下传，P 波常位于 QRS 之后（RP <0.20 s）或埋于 QRS，形成房室分离。频率 40–60 次/分虽低于正常窦性，静息心输出量多可维持；但房室同步丧失使心房辅助充盈作用消失，心输出量下降 15%–25%，老年与左室功能不全者可出现头晕、乏力、低血压。加速性交界区心律多由洋地黄中毒、心肌缺血或术后自律性增高所致，属主动性心律失常。","dx":{"criteria":["连续 ≥3 个交界区搏动，频率 40–60 次/分（加速性交界区心律 60–100 次/分，交界区心动过速 >100 次/分）","QRS 窄（<0.12 s）或与窦性 QRS 形态相同；合并束支阻滞或差异传导时可增宽","P 波缺失，或逆行 P 波位于 QRS 之前（PR <0.12 s）或之后（RP <0.20 s），Ⅱ、Ⅲ、aVF 倒置、aVR 直立","逸搏间期长于基础窦性周期，常出现在窦性停搏、窦缓（<50 次/分）或高度房室阻滞的长间歇之后","必须评估血流动力学：血压、意识、尿量、末梢灌注，以及是否出现晕厥、心绞痛、急性心衰","必须寻找可逆病因：地高辛浓度、血钾、肌钙蛋白、药物史、心脏手术史"],"workup":["12 导联心电图加长条记录：测量逸搏频率、逸搏间期、有无逆行 P 与房室分离，与窦缓、Ⅲ度房室阻滞、房颤伴缓慢心室率鉴别","24–72 小时动态心电图：最长 RR 间期（>3 s 为起搏指征参考）、逸搏负荷、昼夜心率变化","电解质（钾、镁、钙）、肾功能、地高辛血药浓度、肌钙蛋白与血气","超声心动图：评估结构性心脏病、左室功能与心房大小；疑急性下壁心梗时加做 V4R 并急诊再灌注评估","药物史核查（β 阻滞剂、非二氢吡啶类钙拮抗剂、地高辛、抗心律失常药）；疑窦房结功能障碍者行电生理检查（窦房结恢复时间 SNRT >1500 ms 或校正 SNRT >525 ms 提示异常）"],"grading":"按频率分逸搏心律（40–60 次/分）、加速性交界区心律（60–100 次/分）、交界区心动过速（>100 次/分）；按病因分可逆性（药物、电解质、缺血、术后）与不可逆性（传导系统退行性变、术后损伤）；按血流动力学分稳定与不稳定（低血压、晕厥、心衰、缺血）。"},"ddx":[{"name":"窦性心动过速（ar_sinus_tachy）","point":"与本类 ar_sinus_tachy 鉴别：窦速 >100 次/分、P 波正常且每个 QRS 前均有 P；交界区逸搏 40–60 次/分、无 P 或逆行 P，出现于长间歇后。"},{"name":"房室交界区性期前收缩（ar_junctional_pac）","point":"与本类 ar_junctional_pac 鉴别：交界性早搏提前出现、联律间期短，其前后有基础窦性心律；逸搏在长间歇后延迟出现，提示高级起搏点失败。"},{"name":"窦房结功能障碍（ar_brady）","point":"病态窦房结综合征以窦缓、窦性停搏、慢快综合征为表现，逸搏心律是其结果之一；需以动态心电图与窦房结功能检查判断窦房结本身病变。"},{"name":"房室传导阻滞（ar_avb）","point":"Ⅲ度房室阻滞时逸搏可来自交界区（窄 QRS、40–60 次/分）或心室（宽 QRS、20–40 次/分）；前者预后较好，后者提示希氏束以下病变，需尽快起搏。"},{"name":"心房颤动伴缓慢心室率","point":"房颤时 RR 绝对不齐、无 P 波、可见 f 波；交界区逸搏心律 RR 规则、无 f 波。"},{"name":"高钾血症所致宽 QRS 心律","point":"血钾 >6.5 mmol/L 时 QRS 增宽、P 波消失，可呈正弦波，易误认为室性逸搏；查血钾与血气可迅速鉴别，需紧急降钾。"},{"name":"室性逸搏心律","point":"心室逸搏 QRS 宽大畸形 ≥0.12 s、频率 20–40 次/分、无逆行 P，提示希氏束以下起搏点，血流动力学更不稳定，需紧急临时起搏。"}],"tx":{"drug":[{"name":"阿托品","dose":"0.5–1 mg 静脉推注，每 3–5 分钟可重复，最大总量 3 mg","note":"用于症状性心动过缓/逸搏伴低灌注；房室结水平的阻滞（下壁心梗）有效，希氏束以下阻滞常无效；青光眼、前列腺增生、尿潴留者慎用","renal":"肾功能不全无需调整","hepatic":"遵说明书","interact":"与其他抗胆碱药合用作用增强；与抗精神病药合用增加抗胆碱能不良反应"},{"name":"异丙肾上腺素","dose":"1–4 µg/min 静脉泵入，按心率滴定（一般维持 60 次/分左右）","note":"用于阿托品无效的临时过渡，提高交界区与心室逸搏频率；可诱发室速、心肌缺血与心律失常，冠心病、重度主动脉瓣狭窄慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂合用相互拮抗；与拟交感药合用增加心律失常"},{"name":"葡萄糖酸钙","dose":"10% 葡萄糖酸钙 10–20 mL 静脉缓慢推注（5–10 分钟），必要时重复","note":"仅用于高钾血症所致宽 QRS/逸搏，稳定心肌膜；不降低血钾，需同时用胰岛素-葡萄糖、利尿或透析降钾","renal":"肾功能不全者钙蓄积，避免反复大剂量","hepatic":"遵说明书","interact":"与洋地黄合用可加重洋地黄毒性（避免同时静脉推注钙剂）"},{"name":"地高辛特异性抗体片段（Digoxin Immune Fab）","dose":"按血清地高辛浓度与体重依说明书公式计算，严重中毒时使用，具体剂量需专科会诊","note":"洋地黄过量所致交界区逸搏/加速性交界区心律的首选解毒治疗；用药后血钾与地高辛检测值失真","renal":"肾功能不全者清除延迟，需延长监护","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["临时起搏指征：症状性心动过缓伴低血压（收缩压 <90 mmHg）、意识改变、休克、缺血性胸痛、急性心衰，或最长 RR 间期 >3 s，药物无效时经静脉或经皮起搏","永久起搏指征：不可逆的窦房结功能障碍（症状性停搏 >3 s、SNRT 异常）、Ⅱ度Ⅱ型或Ⅲ度房室阻滞、交替性束支阻滞","纠正可逆因素：停用 β 阻滞剂/非二氢吡啶类钙拮抗剂/地高辛，补钾或降钾，急性下壁心梗尽早再灌注（多数房室结缺血性阻滞 24–72 小时恢复，可暂不起搏）","血管迷走性晕厥所致者行倾斜训练、增加盐与水摄入，反复心脏抑制型可考虑起搏","避免使用负性传导药物（β 阻滞剂、地尔硫䓬、维拉帕米、胺碘酮）直至传导恢复"],"life":["教会患者自测脉搏，心率 <40 次/分或出现头晕、黑矇、晕厥前兆立即就诊","起搏器植入者术后 1、3、6 个月程控随访，此后每 6–12 个月一次，注意囊袋与导线并发症","避免诱因：过度 vagal 刺激（饱餐、便秘、屏气）、脱水、电解质紊乱；睡眠呼吸暂停者行 CPAP 治疗","定期复查心电图与动态心电图，评估逸搏负荷与传导阻滞进展"]},"prog":"交界区逸搏本身是保护性机制，短期预后取决于基础病因：药物性或下壁心梗所致者在去除病因后多完全恢复，不需永久起搏；传导系统退行性变所致者常需永久起搏，起搏后生活质量与生存接近同龄人群。发生于Ⅲ度房室阻滞且逸搏频率 <40 次/分、QRS 增宽者，晕厥与猝死风险高，需尽快起搏。","refs":["2018 ACC/AHA/HRS Guideline on the Evaluation and Management of Patients With Bradycardia and Cardiac Conduction Delay","2021 ESC Guidelines on cardiac pacing and cardiac resynchronization therapy","中华医学会心血管病学分会、中国生物医学工程学会心律分会：抗心律失常药物临床应用中国专家共识（2023）","《内科学》（第 9 版，人民卫生出版社，2018）"]}]},{"id":"ar_genetic_more","name":"遗传性心律失常（补充）","rank":47,"summary":"短 QT 综合征以 QTc <340 ms、胸前导联 T 波高尖对称、易发室颤为特征；诊断需结合 QTc、基因与家族史，并排除高钙、高钾、酸中毒、洋地黄等获得性短 QT；猝死幸存者首选 ICD，奎尼丁可延长 QT 并减少放电，无症状者的 ICD 决策须个体化。","compare":[],"diseases":[{"id":"ar_sqts","name":"短 QT 综合征","aka":["Short QT Syndrome","SQTS","短 QT 间期综合征"],"rank":1,"basic":{"define":"常染色体显性遗传的离子通道病，复极外向钾电流功能增强或去极化钠/钙电流功能丧失，使动作电位时程与 QT 间期缩短，易发多形性室速/室颤与心脏性猝死。以 QTc <340 ms 为核心诊断阈值，部分患者需 QTc ≤360 ms 合并高危因素才诊断。","risk":["KCNH2 功能获得突变（SQT1，最常见、外显率最高）","KCNQ1（SQT2）、KCNJ2（SQT3）、SLC4A3 等基因突变","一级亲属 <40 岁不明原因猝死史或确诊 SQTS","男性（外显率与猝死风险高于女性，尤其 SQT1）","合并心房颤动（约 20%–30%）","获得性促发因素：高钙血症、高钾血症、酸中毒、洋地黄、低温、急性心肌缺血"],"epi":"极罕见，文献估计患病率低于 1/10 000；儿童青少年中符合 QTc ≤340 ms 者约 5/10 000（多数为良性早复极或正常变异），真正 SQTS 更少。确诊者多在 20–40 岁，男性外显率与猝死风险更高。"},"patho":"复极外向钾电流（IKr、IKs、IK1）增强使动作电位 2、3 相缩短，心外膜复极明显早于中层心肌，跨壁复极离散度增大，形成功能性折返基质；心室有效不应期缩短使房颤易发。部分患者伴早复极样 J 点抬高，与早复极综合征存在表型重叠。获得性短 QT（高钙、高钾、酸中毒、洋地黄、低温、缺氧）通过相似机制致心律失常，纠正病因后 QT 多恢复。猝死常由短联律间期室早触发多形性室速/室颤，可发生于静息或睡眠中。","dx":{"criteria":["**QTc ≤340 ms**（Bazett 校正）为诊断阈值（2017 AHA/ACC/HRS）；QTc <320 ms 高度提示，需在不同时间、不同心率下重复测量排除测量误差","QTc ≤360 ms 且具备以下任一项亦可诊断：确认致病基因突变、一级亲属确诊 SQTS、一级亲属 <40 岁不明原因猝死、无结构性心脏病的室速/室颤存活者","**心电图特征**：ST 段极短、T 波高尖对称（V2–V4 明显）、Tp-e/QT 比值增大、J 点或早复极样抬高，P 波与 QRS 时限正常","**必须排除获得性短 QT**：血钙 >2.6 mmol/L、血钾 >5.5 mmol/L、酸中毒（pH <7.35）、洋地黄（血药浓度 >2.0 ng/mL）、低温、急性缺血、运动员心脏、抗雄激素或甲状腺素过量","动态心电图与运动试验：心率增快时 QT 不适当缩短（正常 QT 随心率增快而缩短，SQTS 缩短过度），可见短阵室速或房颤","基因检测：KCNH2、KCNQ1、KCNJ2、SLC4A3、CACNA1C、CACNB2b 等 panel（阳性率约 20%–30%，阴性不排除诊断）","家族筛查：一级亲属 12 导联心电图 + 基因检测，可发现无症状携带者"],"workup":["12 导联心电图（纸速 25 mm/s、增益 10 mm/mV），测量 QT 与 RR，用 Bazett 与 Fridericia 双公式校正，取多次测量的最短 QTc","24–72 小时动态心电图：最短 QTc、房颤负荷、短阵室速、昼夜心率变化","电解质（钙、钾、镁）、血气 pH、肾功能、地高辛浓度，排除获得性短 QT","超声心动图与心脏 MRI：排除结构性心脏病（HCM、ARVC、心肌炎）","运动试验与电生理检查：运动后 QTc 变化；电生理诱发室颤的价值有限，不作为常规","基因检测与遗传咨询，一级亲属级联筛查"],"grading":"按基因型分 SQT1（KCNH2，最常见）、SQT2（KCNQ1）、SQT3（KCNJ2，T 波不对称、U 波明显）及 SQT4–SQT6（钙通道、SLC4A3 等）；按风险分层：心脏骤停幸存者 > 晕厥/自发性室速 > 无症状但 QTc <340 ms 合并家族猝死史 > 仅基因阳性且 QTc 正常。"},"ddx":[{"name":"长 QT 综合征（邻类：遗传性心律失常）","point":"与本类外最易混淆的邻类疾病鉴别：LQTS 为 QTc 延长（>480 ms）、T 波形态异常、尖端扭转型室速；SQTS 为 QTc 缩短（<340 ms），二者治疗方向相反（LQTS 用 β 阻滞剂，SQTS 用奎尼丁），QTc 测量是分水岭。"},{"name":"高钙血症","point":"血钙 >2.6 mmol/L 时 ST 段缩短、QT 缩短，常伴乏力、便秘、多尿与恶性肿瘤/甲旁亢证据；纠正血钙后 QT 恢复，基因检测阴性。"},{"name":"高钾血症","point":"血钾 >5.5 mmol/L 时 T 波高尖对称、P 波低平、QRS 增宽，QT 缩短；血气与血钾可迅速鉴别，降钾后心电图恢复。"},{"name":"早复极综合征","point":"J 点抬高 ≥0.1 mV、J 波、ST 段凹面向上，QT 多正常；高危表型为下壁导联 J 波 >0.2 mV 伴水平/下斜型 ST，猝死风险与 SQTS 不同，基因与 QTc 可鉴别。"},{"name":"Brugada 综合征","point":"V1–V3 穹隆型 ST 段抬高 ≥2 mm、QT 正常，发热或钠通道阻滞剂可诱发；SQTS 以 QTc 缩短与 T 波高尖为主，无 Brugada 型 ST 改变。"},{"name":"运动员心脏","point":"窦性心动过缓、QT 随心率延长，停止训练后恢复；无猝死家族史与致病突变，QTc 极少 <340 ms。"},{"name":"洋地黄效应","point":"ST 段呈鱼钩样下移、QT 缩短、PR 延长，血药浓度 >2.0 ng/mL，停药后恢复；SQTS 无鱼钩样 ST 改变。"},{"name":"结构性心脏病所致室颤（HCM、ARVC、心肌炎）","point":"超声或心脏 MRI 可见肥厚、右室扩大/脂肪浸润、心肌水肿或延迟强化；SQTS 心脏结构正常，靠 QTc 与基因诊断。"}],"tx":{"drug":[{"name":"奎尼丁","dose":"硫酸奎尼丁 200 mg q6h 起始（或 200 mg tid），按 QTc 与耐受性调整；目标 QTc 延长至 400–460 ms，不超过 500 ms","note":"目前唯一被证实可延长 QT、减少室速/室颤复发的药物，对 SQT1（KCNH2）效果最明显；可减少 ICD 放电但不能替代 ICD；监测 QTc、QRS（较基线增宽 >25% 停药）与血药浓度；腹泻、金鸡纳反应、血小板减少常见","renal":"CrCl <30 mL/min 减量并延长给药间隔，监测血药浓度","hepatic":"以肝代谢为主，肝硬化或肝功能不全者减量并监测血药浓度","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素、地尔硫䓬）升高浓度；与胺碘酮、索他洛尔合用进一步延长 QT；与地高辛合用升高地高辛浓度；碱性尿减少排泄"},{"name":"氢奎尼丁","dose":"250 mg bid 起始，按 QTc 调整至 250 mg tid；目标 QTc 400–460 ms，不超过 500 ms","note":"欧洲常用，耐受性略优于硫酸奎尼丁；同样需监测 QTc 与 QRS 时限，可显著减少心律失常负荷与 ICD 放电","renal":"重度肾功能不全减量，监测血药浓度","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂升高浓度；与其他延长 QT 药物合用增加尖端扭转风险；升高地高辛浓度"},{"name":"氯化钾（纠正低钾）","dose":"口服氯化钾缓释片 0.5–1.0 g bid–tid，或 10% 氯化钾 10–15 mL 口服，目标血钾 4.0–4.5 mmol/L","note":"仅在血钾 <4.0 mmol/L 时补充；低钾会进一步缩短 QT、降低室颤阈值，是可纠正的促发因素；不作为常规治疗，补钾前确认尿量与肾功能","renal":"eGFR <30 mL/min 减量并密切监测血钾，避免高钾","hepatic":"遵说明书","interact":"与 ACEI/ARB、螺内酯、补钾剂合用增加高钾风险"}],"nonDrug":["ICD 二级预防（Ⅰ类）：心脏骤停幸存者或血流动力学不稳定的室速/室颤，无论 QTc 水平均推荐","ICD 一级预防（Ⅱa/Ⅱb，个体化）：无症状但 QTc <340 ms 且合并一级亲属 <40 岁猝死、确诊致病突变或电生理可诱发室颤者；儿童植入需权衡 inappropriate shock 与导线并发症","导管消融：仅作为 ICD 反复放电的辅助（消融触发室早/室速），不能根治，不能替代 ICD","避免低钾、低镁、酸中毒、高热、脱水与剧烈运动；避免使用洋地黄、儿茶酚胺类等进一步缩短 QT 的药物","家族级联筛查（心电图 + 基因）与遗传咨询，基因阳性者即使 QTc 正常也需定期随访"],"life":["避免竞技性运动与极端耐力运动（尤其 SQT1 男性），可进行中等强度有氧活动","避免高温环境、脱水、大量咖啡因与能量饮料；发热时积极降温补液","每年复查 12 导联心电图、动态心电图与超声心动图；ICD 患者每 3–6 个月程控","出现 ICD 放电、晕厥前兆或心悸加重立即就诊，评估触发因素与药物依从性","妊娠前遗传咨询与多学科评估，妊娠期心律失常风险增加，需心内科与产科共同管理"]},"prog":"猝死风险在男性、QTc <320 ms、SQT1 型与既往心脏骤停者最高，未治疗的症状性患者年猝死率可达数个百分点。ICD 可显著降低猝死风险，但儿童与年轻患者 inappropriate shock 与导线并发症 5 年可达 20%–30%，需权衡获益。奎尼丁可减少心律失常负荷与放电，但不能替代 ICD。","refs":["中华医学会心电生理和起搏分会：遗传性原发性心律失常综合征诊断与治疗中国专家共识（2015）","2022 ESC Guidelines for the management of patients with ventricular arrhythmias and the prevention of sudden cardiac death","2017 AHA/ACC/HRS Guideline for Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death","HRS/EHRA/APHRS Expert Consensus Statement on the Diagnosis and Management of Patients with Inherited Primary Arrhythmia Syndromes（2013）"]}]},{"id":"chd_more2","name":"先天性心脏病（补充）","rank":48,"summary":"法洛四联症以右室流出道梗阻程度决定发绀与缺氧发作，缺氧发作是膝胸位 + 吗啡 + 去氧肾上腺素 + β 阻滞剂的急症，确诊后 3–12 月龄行根治手术；艾森门格综合征是左向右分流长期肺高压致右向左分流，封堵为禁忌，靠靶向药物与并发症管理，妊娠属禁忌。","compare":[{"diseaseId":"chd_tof","dx":"生后即发绀、蹲踞、胸骨左缘喷射性杂音伴 P2 减弱与 S2 单一，胸片靴形心与肺血减少，超声见对位不良 VSD、主动脉骑跨与右室流出道梗阻","key":"肺血少 + P2 减弱 + 靴形心；缺氧发作按急症处理，3–12 月龄根治"},{"diseaseId":"chd_eisenmenger","dx":"先心病史、晚期出现中心性发绀与杵状指，P2 亢进、肺血增多，右心导管 PVR ≥5 WU 伴右向左分流","key":"肺血多 + P2 亢进 + PVR 显著升高；封堵与妊娠均为禁忌，用肺高压靶向药物"}],"diseases":[{"id":"chd_tof","name":"法洛四联症","aka":["Tetralogy of Fallot","TOF","法乐四联症"],"rank":1,"basic":{"define":"由四种畸形组成的发绀型先心病：对位不良型室间隔缺损、右室流出道梗阻（漏斗部 ± 肺动脉瓣）、主动脉骑跨（≤50%）与右室肥厚。右室流出道梗阻程度决定肺血流与发绀轻重，是症状与手术时机的核心变量。","risk":["22q11.2 微缺失（DiGeorge 综合征）","母亲糖尿病、苯丙酮尿症、孕期酒精或维 A 酸暴露","家族性先心病史","21 三体等其他染色体异常（较少见）","男性略多"],"epi":"占全部先心病的 5%–10%，活产儿约 3–5/10 000，是最常见的发绀型先心病（约占发绀型先心的 50%–70%）；未手术者自然病程差，根治术后长期生存显著改善。"},"patho":"对位不良的室间隔缺损大且主动脉骑跨，右室血流出口受阻，右室压与左室相等，肺血流减少；分流方向取决于右室流出道梗阻与体循环血管阻力的比值。哭闹、脱水、感染、贫血使梗阻加重或体循环阻力下降时，右向左分流骤增，形成缺氧发作（tet spell），肺血流近乎中断。慢性低氧致红细胞增多、杵状指与侧支循环；长期肺血流减少使左心发育偏小，术后易出现肺动脉瓣反流与右室扩张。","dx":{"criteria":["生后数周至 6 个月出现中心性发绀（重型者生后即有），哭闹、喂奶时加重，逐渐出现杵状指（趾）","胸骨左缘 2–4 肋间粗糙的收缩期喷射性杂音（来自右室流出道而非 VSD），肺动脉瓣成分（P2）减弱或消失、第二心音单一（仅为主动脉瓣关闭音）","**蹲踞现象**：活动后蹲下，增加体循环阻力、减少右向左分流，使发绀与气促缓解，为特征性表现","**缺氧发作**：突发呼吸急促、发绀加重、杂音减弱或消失（肺血流近乎中断）、烦躁不安→意识丧失/抽搐，SpO₂ 骤降，可致死亡","胸片：靴形心（心尖上翘）、肺血减少、肺动脉段凹陷，约 25% 伴右位主动脉弓","心电图：右室肥厚（V1 高 R 波）、电轴右偏，无左室肥厚","超声心动图确诊：对位不良 VSD 大小、主动脉骑跨率 ≤50%、右室流出道梗阻部位与压差、肺动脉分支及冠状动脉起源","心导管或 CTA：McGoon 比值、肺动脉指数、体肺侧支（MAPCA），用于评估可否一期根治"],"workup":["经胸超声心动图：四种畸形定量、流出道压差、肺动脉瓣环 Z 值、冠脉起源（术前必查）","心导管造影或 CTA：肺动脉分支发育（McGoon 比值、PA 指数）、MAPCA、右位主动脉弓","心脏 MRI：右室容积、肺动脉瓣反流分数（术后随访）、右室射血分数","血气与血常规：低氧血症、Hb/Hct 升高（代偿性红细胞增多）、血小板与凝血功能","染色体微阵列或 22q11.2 FISH、遗传咨询；术前气道与肺功能评估"],"grading":"按右室流出道梗阻程度分轻型（无明显发绀，pink TOF）、经典型、重型（新生儿期即重度发绀，导管依赖）；按肺动脉发育分良好（McGoon 比值 ≥2.0）、可（1.5–2.0）、差（<1.5，PA 指数 <150 mm²/m² 提示发育不良）；合并畸形包括右位主动脉弓（25%）、冠状动脉异常（5%–10%）、MAPCA。"},"ddx":[{"name":"艾森门格综合征（chd_eisenmenger）","point":"与本类 chd_eisenmenger 鉴别：艾森门格为左向右分流晚期肺高压致右向左分流，发绀出现晚（儿童或青年），有肺血增多史、P2 亢进、胸片肺血多或残根样；TOF 生后即发绀、肺血少、P2 减弱、靴形心。"},{"name":"大动脉转位（chd_tga）","point":"与本类 chd_tga 鉴别：TGA 生后数小时即重度发绀、吸氧不改善，胸片蛋形心、肺血增多，超声见主动脉起自右室、肺动脉起自左室；TOF 发绀出现较晚、肺血少。"},{"name":"肺动脉狭窄（chd_ps）","point":"与本类 chd_ps 鉴别：单纯 PS 无 VSD、无主动脉骑跨，发绀仅在合并 ASD/PFO 时出现；TOF 有对位不良 VSD 与主动脉骑跨，杂音更粗糙且伴单一 P2。"},{"name":"室间隔缺损（chd_vsd）","point":"与本类 chd_vsd 鉴别：大 VSD 左向右分流、肺血多、P2 亢进、无发绀（晚期可发展为艾森门格）；TOF 肺血少、P2 减弱、有发绀与蹲踞。"},{"name":"房室间隔缺损（chd_avsd）","point":"与本类 chd_avsd 鉴别：AVSD 电轴左偏、共同房室瓣、常合并 21 三体；TOF 电轴右偏、右室肥厚、无房室瓣共瓣环。"},{"name":"右室双出口","point":"超声见两条大动脉均主要起自右室，VSD 为左室唯一出口；与 TOF 的鉴别靠主动脉骑跨程度（>50% 支持 DORV）与大动脉空间关系。"},{"name":"三尖瓣闭锁或单心室","point":"超声见三尖瓣无血流、右室发育不良或单一心室腔，心电图常为左室肥厚伴电轴左偏；TOF 为双心室结构、右室肥厚。"}],"tx":{"drug":[{"name":"吗啡","dose":"0.05–0.1 mg/kg 静脉、肌注或皮下，单次，必要时 30 分钟后重复","note":"缺氧发作的一线用药：抑制过度通气与交感张力，缓解漏斗部痉挛；注意呼吸抑制与低血压，需备复苏设备","renal":"肾功能不全者延长给药间隔","hepatic":"肝功能不全者减量","interact":"与镇静药、麻醉药合用加重呼吸抑制；与单胺氧化酶抑制剂合用可致呼吸抑制"},{"name":"去氧肾上腺素","dose":"5–20 µg/kg 静脉推注，每 10–15 分钟可重复；或以 0.1–0.5 µg·kg⁻¹·min⁻¹ 持续泵入","note":"提高体循环阻力、减少右向左分流，是缺氧发作的关键药物；监测血压与心率（可致反射性心动过缓），避免外渗致组织坏死","renal":"遵说明书","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂、三环类抗抑郁药合用可致高血压危象；与 β 阻滞剂合用可致血压骤升"},{"name":"艾司洛尔","dose":"负荷 100–500 µg/kg 静脉 1 分钟内推注，维持 25–50 µg·kg⁻¹·min⁻¹（最大 200 µg·kg⁻¹·min⁻¹）","note":"短效 β₁ 阻滞剂，缓解漏斗部痉挛；哮喘、失代偿心衰、重度心动过缓慎用","renal":"肾功能不全无需调整（经红细胞酯酶代谢）","hepatic":"肝功能不全无需调整","interact":"与维拉帕米、地尔硫䓬合用致严重低血压与心动过缓"},{"name":"普萘洛尔","dose":"发作时 0.1 mg/kg 缓慢静脉推注；发作间期口服 1–2 mg/kg/d 分 3–4 次","note":"口服用于反复发作或新生儿期等待手术的过渡治疗，可减轻发绀与发作频率；哮喘禁用，注意低血糖与心动过缓","renal":"肾功能不全无需调整","hepatic":"肝功能不全减量","interact":"与维拉帕米合用致传导阻滞；与胰岛素合用掩盖低血糖症状"},{"name":"碳酸氢钠","dose":"1–2 mmol/kg 静脉缓慢推注，按血气 pH 调整","note":"纠正代谢性酸中毒，酸中毒会加重肺血管收缩与漏斗部痉挛；避免过量致碱中毒与高钠","renal":"肾功能不全者慎用，监测血钠与容量","hepatic":"遵说明书","interact":"与钙剂合用可致沉淀；与儿茶酚胺类合用降低其活性"},{"name":"前列地尔（前列腺素 E1）","dose":"0.01–0.05 µg·kg⁻¹·min⁻¹ 持续静脉泵入，按血氧与血压滴定","note":"用于新生儿期重度发绀、导管依赖型肺血流者，维持动脉导管开放；注意呼吸暂停、发热、体循环低血压，需备气管插管","renal":"遵说明书","hepatic":"遵说明书","interact":"与降压药合用加重低血压；与肝素合用增加出血风险（抑制血小板）"},{"name":"氯胺酮","dose":"1–2 mg/kg 肌注，或 0.5–1 mg/kg 静脉缓慢推注","note":"用于躁动诱发发作的镇静，可维持体循环阻力；避免用于高血压、颅内压增高者；需气道管理条件","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与阿片类合用增加呼吸抑制；与升压药合用增加高血压风险"}],"nonDrug":["**缺氧发作急救流程**：立即膝胸位或抱膝屈曲位、面罩吸氧 100%、减少刺激；静脉补液扩容；吗啡 + 去氧肾上腺素 + 碳酸氢钠；无效时用艾司洛尔或普萘洛尔；仍无效者气管插管、深镇静，紧急外科分流或根治","根治手术时机：有症状或发绀明显者 3–6 月龄（体重 ≥4 kg）、无症状者 6–12 月龄行一期根治（VSD 修补 + 右室流出道解除，尽量保留肺动脉瓣环）","新生儿期重度发绀或肺动脉发育差者：前列腺素 E1 维持后行体肺分流（BT 分流）或右室流出道支架，二期根治","成人未手术者：评估肺动脉发育与左室功能后行根治；已发展为艾森门格者禁忌根治，按肺动脉高压管理","术后随访：残余肺动脉瓣反流致右室扩张（RVEDVI >150 mL/m² 考虑肺动脉瓣置换）、QRS >180 ms 与室速提示猝死高危，需评估 ICD","未修补、有残余缺损或人工材料者行感染性心内膜炎预防"],"life":["避免脱水、哭闹、感染与剧烈活动（缺氧发作诱因）；婴儿少量多餐，发热时积极补液","术后 3、6、12 个月复查超声心动图与心电图，此后每年一次；青春期重点评估肺动脉瓣反流与右室容积","限制竞技性运动（残余右室高压、心律失常、主动脉根部扩张者）","妊娠前心肺功能评估：修复后多数可耐受，但需评估右室容量负荷、肺动脉瓣反流与心律失常风险","口腔卫生与定期牙科检查，按指征行心内膜炎预防"]},"prog":"未手术者约 25% 于 1 岁内死亡、40% 于 3 岁内、70% 于 10 岁内死亡。根治术后 20–30 年生存率 >90%，晚期主要问题为肺动脉瓣反流致右室扩张、室性心律失常与猝死（年发生率约 0.1%–0.3%），需终身随访与再干预评估。","refs":["国家心血管病中心：先天性心脏病外科治疗中国专家共识（十）：法洛四联症（2020）","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]},{"id":"chd_eisenmenger","name":"艾森门格综合征","aka":["Eisenmenger Syndrome","艾森曼格综合征","Eisenmenger 综合征"],"rank":2,"basic":{"define":"先天性左向右分流（ASD、VSD、PDA、AVSD）长期肺血流增多导致肺血管重塑，肺血管阻力进行性升高至等于或超过体循环阻力，分流逆转为右向左或双向，出现持续性中心性发绀。属 WHO 第 1 组肺高压中的先心病相关肺动脉高压（PAH-CHD），为不可手术/不可封堵的终末阶段。","risk":["未修补的大室间隔缺损或动脉导管未闭（压力 + 流量双重负荷，进展最快）","房室间隔缺损（尤其合并 21 三体）","房间隔缺损（进展较慢，多在成年期）","未及时手术或手术时机过晚","女性（ASD 相关肺高压以女性为主）、高原居住","妊娠（可致肺高压危象与死亡）"],"epi":"未修补的先心病中约 5%–10% 最终发展为艾森门格；大 VSD/PDA 常在婴儿期即进展，ASD 多在 20–40 岁出现。我国成人先心病相关肺高压仍占肺高压的相当比例，是妊娠期心血管死亡的重要原因之一。"},"patho":"长期高肺血流与高压损伤肺血管内皮，引起中层肥厚、内膜增生、丛样病变与原位血栓，肺血管阻力进行性升高。当 PVR 超过 SVR 时分流逆转，未氧合血进入体循环，产生中心性发绀与杵状指；右室压力负荷增加，最终右心衰。慢性低氧致继发性红细胞增多、高黏滞血症、血小板功能异常（血栓与出血并存）、胆石症、高尿酸与杵状指；肺动脉扩张或侧支血管破裂可致致命性咯血。","dx":{"criteria":["已知先心病（ASD、VSD、PDA、AVSD）未修补或术后残余分流，出现中心性发绀与杵状指，活动耐量下降","**右心导管（金标准）**：mPAP >20 mmHg、PAWP ≤15 mmHg、PVR ≥5 WU（PVRi ≥8 WU·m²），Qp/Qs 接近 1 或 <1，分流双向或右向左","超声心动图：右室扩大、室间隔扁平或左移、三尖瓣反流速度 >3.4 m/s、分流双向/右向左、右室收缩功能下降","血气：静息 SpO₂ <90%，吸氧后改善不明显（固定性右向左分流）；PaCO₂ 可降低（过度通气）","血常规：Hb/Hct 代偿性升高（Hct 常 >55%），血小板可减少；血尿酸、胆红素升高","心电图：右室肥厚、电轴右偏、右房扩大，可有心律失常（房颤、房扑）","功能评估：6 分钟步行距离下降、BNP/NT-proBNP 升高、WHO 功能分级 Ⅱ–Ⅳ","排除其他发绀原因：高铁血红蛋白血症、肺内分流（肝肺综合征）、慢性肺病、原发性肺动脉高压"],"workup":["右心导管：测 mPAP、PAWP、PVR、SVR、Qp/Qs 与分流方向，判断可否手术；艾森门格禁忌做急性血管反应试验（可致体循环低血压与晕厥）","经胸超声心动图：分流方向与速度、右室大小与功能、TRV、下腔静脉，评估肺高压间接征象","血气、肺功能、CTPA：排除肺实质疾病与慢性血栓栓塞性肺高压","血常规、铁代谢、尿酸、胆红素、凝血功能：评估红细胞增多、缺铁与高黏滞风险","6 分钟步行试验、BNP、WHO 功能分级：基线评估与治疗反应监测","遗传与综合征评估（21 三体、22q11.2），妊娠期多学科评估"],"grading":"按解剖分 ASD、VSD、PDA、AVSD 相关；按修补状态分不可修补（艾森门格）、可修补但高阻力、术后残余/反跳性肺高压；按 WHO 功能分级 Ⅰ–Ⅳ；按风险分层（6MWD、BNP、右房压、心指数、SvO₂）分低、中、高危。"},"ddx":[{"name":"法洛四联症（chd_tof）","point":"与本类 chd_tof 鉴别：TOF 生后即发绀、肺血少、P2 减弱、靴形心，右心导管 PVR 不高、肺血流减少；艾森门格发绀出现晚、P2 亢进、肺血增多、PVR 显著升高。"},{"name":"肺动脉高压（ph_group）","point":"特发性肺动脉高压无先心病与心内分流，超声无分流束，右心导管 Qp/Qs 约 1；艾森门格有明确先心病与双向/右向左分流。"},{"name":"慢性血栓栓塞性肺高压（CTEPH）","point":"有深静脉血栓/肺栓塞史，CTPA 见血栓、网带或肺动脉闭塞，V/Q 显像呈不匹配灌注缺损；无先心病分流，PVR 升高但 Qp/Qs 正常。"},{"name":"房间隔缺损（chd_asd）未合并肺高压","point":"ASD 为左向右分流、无发绀，超声分流单向、右室容量负荷增加但 PVR 正常；艾森门格分流双向/右向左、已发绀。"},{"name":"肝肺综合征或门肺高压","point":"有肝硬化/门脉高压证据，直立性低氧（orthodeoxia）、超声造影见肺内毛细血管扩张，右心导管无先心病分流；艾森门格有先心病史。"},{"name":"高铁血红蛋白血症","point":"发绀明显但 PaO₂ 正常、SpO₂ 与 PaO₂ 不符、血液呈巧克力色，亚甲蓝治疗有效；艾森门格 PaO₂ 降低、吸氧改善有限但有先心病。"},{"name":"慢性肺病相关肺心病","point":"有 COPD、ILD 或睡眠呼吸障碍证据，肺功能异常、PaCO₂ 升高，超声右室扩大但无分流；艾森门格以先心病分流为核心。"}],"tx":{"drug":[{"name":"波生坦","dose":"62.5 mg bid 起始 4 周，耐受后 125 mg bid；体重 <40 kg 者 31.25 mg bid 起始","note":"内皮素受体拮抗剂，改善 6MWD 与血流动力学；每月监测肝酶，ALT/AST >3 倍正常上限停药；致畸，女性需避孕；体液潴留可加重右心衰","renal":"肾功能不全无需调整","hepatic":"中重度肝损禁用；治疗期间每月监测肝酶","interact":"CYP3A4 抑制剂升高浓度；与格列本脲合用致肝毒性；降低华法林与西地那非浓度"},{"name":"安立生坦","dose":"5 mg qd 起始，可增至 10 mg qd","note":"选择性内皮素 A 受体拮抗剂，肝毒性低于波生坦，但外周水肿与贫血常见；育龄女性需避孕","renal":"重度肾功能不全慎用","hepatic":"中重度肝损不推荐","interact":"与环孢素合用升高浓度；CYP3A4 诱导剂降低疗效"},{"name":"马昔腾坦","dose":"10 mg qd","note":"长效内皮素受体拮抗剂，肝酶升高与体液潴留风险较低；致畸，需严格避孕；监测血红蛋白","renal":"重度肾功能不全慎用","hepatic":"Child-Pugh B/C 不推荐","interact":"CYP3A4 强抑制剂合用需谨慎；与 CYP3A4 诱导剂合用降低疗效"},{"name":"西地那非","dose":"20 mg tid，最大 80 mg tid","note":"PDE5 抑制剂，改善 6MWD 与肺血流动力学；禁与硝酸酯类、利奥西呱合用；注意体循环低血压、视力异常与听力下降","renal":"CrCl <30 mL/min 减量或慎用","hepatic":"Child-Pugh C 禁用","interact":"禁与硝酸酯类、利奥西呱合用；CYP3A4 抑制剂升高浓度"},{"name":"他达拉非","dose":"40 mg qd（肺动脉高压剂量）","note":"长效 PDE5 抑制剂，依从性优于西地那非；禁与硝酸酯类、利奥西呱合用；背痛与肌痛常见","renal":"CrCl 31–50 mL/min 从 20 mg qd 起始；CrCl <30 mL/min 避免使用","hepatic":"重度肝损不推荐","interact":"禁与硝酸酯类、利奥西呱合用；CYP3A4 抑制剂升高浓度"},{"name":"利奥西呱","dose":"1 mg tid 起始，每 2 周增加 0.5 mg，最大 2.5 mg tid","note":"可溶性鸟苷酸环化酶激动剂；艾森门格患者咯血风险较高，需谨慎并监测血红蛋白与血压；禁与 PDE5 抑制剂联用","renal":"CrCl <30 mL/min 不推荐","hepatic":"Child-Pugh B/C 禁用","interact":"禁与西地那非、他达拉非合用；与硝酸酯类合用致严重低血压"},{"name":"曲前列尼尔（皮下注射）","dose":"1.25 ng·kg⁻¹·min⁻¹ 起始，每 1–2 周递增 1.25 ng·kg⁻¹·min⁻¹，按耐受滴定","note":"前列环素类似物，用于高危或联合治疗仍恶化者；注射部位疼痛常见，需中心导管者感染风险高；体循环低血压与咯血需警惕","renal":"肾功能不全无需调整","hepatic":"肝功能不全者起始剂量减半并缓慢滴定","interact":"与降压药、利尿剂合用加重低血压；与抗凝药合用增加出血风险"},{"name":"呋塞米","dose":"20–40 mg qd 口服或静脉，按容量与体重调整","note":"用于右心衰与容量负荷过重；艾森门格对前负荷敏感，过度利尿可致低血压、血液浓缩与血栓，需小剂量起始","renal":"CrCl <30 mL/min 加量或改用托拉塞米","hepatic":"遵说明书","interact":"NSAIDs 减弱利尿；与地高辛合用低钾致中毒"},{"name":"地高辛","dose":"0.125 mg qd，肾功能不全者 0.0625 mg qd 或隔日","note":"用于合并房颤控制心室率或右心衰伴收缩功能不全；低氧与低钾时毒性增加，需监测血药浓度","renal":"按 CrCl 减量，CrCl <30 慎用","hepatic":"遵说明书","interact":"低钾、低镁、高钙增强毒性；与胺碘酮、维拉帕米、克拉霉素合用升高浓度"}],"nonDrug":["**禁忌封堵/修补**：PVR ≥5 WU（PVRi ≥8 WU·m²）伴右向左分流者封堵为绝对禁忌，可致急性右心衰、肺高压危象与死亡；仅 PVR <4 WU 且 Qp/Qs >1.5 者考虑手术；PVR 4–5 WU 为灰区，需结合 Qp/Qs、血管反应性与中心经验个体化决策","靶向药物联合治疗：内皮素受体拮抗剂 + PDE5 抑制剂，高危者加前列环素类，按风险分层每 3–6 个月评估","房间隔造口术：反复晕厥或难治性右心衰、靶向治疗无效者考虑，作为移植桥接（风险高，需专科中心）","肺移植或心肺移植：终末期（WHO Ⅳ级、药物治疗无效、反复咯血）","咯血：支气管动脉栓塞，避免常规抗凝；贫血者补铁，缺铁可加重高黏滞","放血治疗：仅 Hct >65% 伴高黏滞症状时等容放血 250–500 mL 并补液，不作常规","感染性心内膜炎预防；严格避孕与妊娠多学科管理"],"life":["**严格避孕**：妊娠死亡率 20%–50%，属妊娠禁忌；意外妊娠需心内科、产科、麻醉与 ICU 多学科团队管理","避免高原、脱水、剧烈运动、热水浴与突然停用靶向药物（可致反跳与肺高压危象）","低盐饮食，氧疗维持 SpO₂ ≥90%（夜间与活动时），长途飞行需吸氧","每 3–6 个月门诊随访，每年评估 6 分钟步行距离、BNP、超声与右心导管（按需）","接种流感、肺炎球菌疫苗；避免使用体循环血管扩张剂与抑制心肌收缩药物"]},"prog":"自然病程中位生存约 20–30 年，明显优于特发性肺动脉高压，主要死因为右心衰、咯血、心律失常与妊娠。靶向治疗可改善 6 分钟步行距离与血流动力学，联合治疗优于单药，但对死亡率的改善证据有限；WHO 功能Ⅳ级、低钠血症、BNP 显著升高与心指数 <2.0 L/min/m² 者预后差。","refs":["中华医学会心血管病学分会肺血管病学组：中国肺动脉高压诊断与治疗指南（2021 版）","2022 ESC/ERS Guidelines for the diagnosis and treatment of pulmonary hypertension","2020 ESC Guidelines for the management of adult congenital heart disease","2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"]}]},{"id":"vhd_more","name":"多瓣膜病","rank":49,"summary":"多瓣膜病以风湿性最常见（二尖瓣 + 主动脉瓣），狭窄与反流并存时血流动力学互相掩盖（MS 掩盖 AR 的脉压增大、MR 低估 AS 的压差），诊断靠超声逐瓣定量；有症状或重度者应同期处理所有需干预的瓣膜，顺序遵循先解除梗阻、后纠正反流，先左心、后三尖瓣。","compare":[],"diseases":[{"id":"vhd_multivalve","name":"多瓣膜病","aka":["Multiple Valvular Heart Disease","Combined Valvular Disease","多瓣膜病变","联合瓣膜病"],"rank":1,"basic":{"define":"两个或以上心脏瓣膜同时存在狭窄和/或关闭不全。最常见病因为风湿性心脏病（二尖瓣 + 主动脉瓣），其次为老年退行性钙化、感染性心内膜炎、黏液样变性（二尖瓣脱垂）、马方综合征与纵隔放疗后。","risk":["风湿热反复发作（A 组链球菌咽炎未规范治疗）","女性（风湿性二尖瓣狭窄为主）","高龄与退行性瓣膜钙化","感染性心内膜炎（可同时损伤多个瓣膜）","马方综合征等结缔组织病（主动脉瓣反流 + 二尖瓣脱垂）","纵隔放疗史、类癌、起搏导线或中心静脉导管相关三尖瓣反流"],"epi":"风湿性心脏病中二尖瓣受累约 90% 以上、主动脉瓣 20%–30%、三尖瓣 5%–10%；我国多瓣膜病仍以风湿性为主，但随着人口老龄化，退行性多瓣膜病比例明显上升。"},"patho":"狭窄与反流并存使心室同时承受压力与容量负荷，心肌重构与心衰进展更快。AS 合并 MR 时，MR 使左室射血阻力下降，跨瓣压差与症状被低估；MS 合并 AR 时，左室充盈受限使脉压增大与左室扩大不明显，AR 严重度易被低估；MS 合并 TS 时右心排血减少，肺淤血反而“减轻”，易延误诊断。三尖瓣反流多为左心瓣膜病继发肺高压与右室扩大所致，左心纠正后可部分回退，但重度 TR 需同期成形，否则是术后右心衰与再手术的重要原因。","dx":{"criteria":["多瓣膜区杂音：心尖部舒张期隆隆样 + 收缩期吹风样、主动脉瓣区喷射性 + 舒张期叹气样；重度 MS 时杂音可不明显（“沉默型”），需结合开瓣音与超声","**超声逐瓣定量**：MS 瓣口面积 ≤1.0 cm² 为重度、1.0–1.5 cm² 为中度；MR 反流容积 ≥60 mL、反流分数 ≥50% 为重度；AS 峰值流速 ≥4 m/s、平均压差 ≥40 mmHg、瓣口面积 ≤1.0 cm² 为重度；AR 缩流颈 ≥0.6 cm、反流容积 ≥60 mL 为重度；TR 缩流颈 ≥0.7 cm 为重度","症状：活动后气促、心绞痛、晕厥、右心衰表现（腹胀、水肿）；症状与瓣膜严重度不匹配时行运动试验、6 分钟步行试验或 BNP 评估","心电图：左室肥厚伴劳损（AS/AR）、左房扩大与房颤（MS/MR）、右室肥厚（肺高压），可有传导阻滞","胸片：心影增大、左房/左室/右室增大、瓣膜钙化、肺淤血或肺血重新分布","肺动脉压评估：超声估肺动脉收缩压 >50 mmHg 提示肺高压，影响手术决策与预后","风湿活动与感染性心内膜炎筛查：ESR、CRP、ASO、血培养（发热者）","心导管：症状与超声不一致、低流量低梯度 AS 需多巴酚丁胺负荷；40 岁以上术前冠脉造影"],"workup":["经胸超声心动图：逐瓣定量狭窄与反流、瓣叶形态与钙化、左室与右室功能、肺动脉压，是多瓣膜病诊断与随访的核心","经食管超声：二尖瓣球囊成形术前 Wilkins 评分与左房血栓排查、疑心内膜炎、人工瓣功能评估与术中监测","心导管与冠脉造影：跨瓣压差、肺血管阻力、合并冠心病的术前评估；低流量低梯度 AS 行多巴酚丁胺负荷","心脏 MRI：AR/MR 反流分数与心室容积定量，尤其超声条件差者","BNP/NT-proBNP、ESR/CRP/ASO、血培养、肾功能与凝血功能（术前与抗凝评估）","运动试验或 6 分钟步行试验：无症状重度病变者的症状客观化与风险分层"],"grading":"按受累瓣膜组合分二尖瓣 + 主动脉瓣（风湿性最常见）、二尖瓣 + 三尖瓣、主动脉瓣 + 二尖瓣 + 三尖瓣、主动脉瓣 + 二尖瓣 + 肺动脉瓣；按每个瓣膜分别分级为轻、中、重度；按症状 NYHA Ⅰ–Ⅳ级；按手术风险用 STS 评分与 EuroSCORE II 分层（预测死亡率 >8% 为高危）。"},"ddx":[{"name":"二尖瓣狭窄（vhd_ms）","point":"与本类外最易混淆的邻类疾病鉴别：单纯 MS 仅心尖部舒张期隆隆样杂音与开瓣音，超声仅二尖瓣受累；多瓣膜病同时有主动脉瓣区杂音与相应瓣膜病变，需逐瓣评估以免漏诊被掩盖的 AR 或 AS。"},{"name":"二尖瓣关闭不全（vhd_mr）","point":"单纯 MR 为心尖部全收缩期杂音向腋下传导，左室扩大、LVEF 代偿性升高；多瓣膜病常伴 MS 的舒张期杂音与左房扩大，超声可见瓣叶增厚/钙化与联合病变。"},{"name":"主动脉瓣狭窄（vhd_as）","point":"单纯 AS 为喷射性杂音向颈部传导、脉压小、迟脉；合并 MR 时脉压与杂音被掩盖，跨瓣压差低估，需结合三维超声与心导管判断真实严重度。"},{"name":"主动脉瓣关闭不全（vhd_ar）","point":"单纯 AR 为叹气样舒张期杂音、脉压增大、水冲脉；合并 MS 时左室充盈受限，脉压增大不明显，AR 严重度易被低估。"},{"name":"风湿热与风湿性心脏病（vhd_rheumatic）","point":"风湿活动期有发热、关节痛、ESR/CRP 升高、ASO 升高、PR 间期延长；多瓣膜病是风湿热后遗的瓣膜改变，无活动指标，需区分是否需要抗风湿治疗。"},{"name":"肥厚型梗阻性心肌病（cm_hcm）","point":"收缩期杂音随 Valsalva 动作增强、伴 SAM 征与左室流出道压差，瓣叶结构正常；多瓣膜病杂音随体位与呼吸符合瓣膜定位，超声见瓣叶增厚/钙化/脱垂。"},{"name":"扩张型心肌病（cm_dcm）","point":"全心扩大、弥漫室壁运动减弱、功能性 MR/TR（瓣环扩张而瓣叶正常）；多瓣膜病有器质性瓣叶病变与相应的狭窄/反流定量，心室扩大程度与瓣膜病变匹配。"},{"name":"自体瓣膜感染性心内膜炎（ie_native）","point":"发热、血培养阳性、赘生物与瓣膜破坏（急性反流）；多瓣膜病合并 IE 时需判断反流加重是原发病进展还是赘生物所致，血培养与超声随访可鉴别。"}],"tx":{"drug":[{"name":"呋塞米","dose":"口服 20–40 mg qd–bid；静脉 20–40 mg 缓慢推注，按容量与症状调整","note":"用于肺淤血与右心衰；MS 与 AS 对前负荷敏感，过度利尿可致心输出量与血压下降，需小剂量起始并监测肾功能与电解质","renal":"CrCl <30 mL/min 加量或改用托拉塞米","hepatic":"遵说明书","interact":"NSAIDs 减弱利尿；与地高辛合用低钾致中毒；与氨基糖苷类合用耳肾毒性增加"},{"name":"螺内酯","dose":"20 mg qd，最大 50 mg qd","note":"用于合并右心衰或继发性醛固酮增多；eGFR <30 mL/min 或血钾 >5.0 mmol/L 禁用","renal":"eGFR <30 禁用，监测肌酐与血钾","hepatic":"肝功能不全者慎用","interact":"与 ACEI/ARB、补钾剂合用致高钾"},{"name":"美托洛尔","dose":"缓释片 23.75–47.5 mg qd 起始，按心率与血压调整；普通片 12.5–25 mg bid","note":"用于合并房颤控制心室率、MS 窦性心动过速时延长舒张期；重度 AS 伴低心输出量者慎用（负性肌力），失代偿心衰禁用","renal":"肾功能不全无需调整","hepatic":"肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用致心动过缓与传导阻滞；CYP2D6 抑制剂升高浓度"},{"name":"地高辛","dose":"0.125 mg qd，肾功能不全者 0.0625 mg qd 或隔日","note":"用于房颤伴快速心室率或合并收缩功能不全；MS 窦性心律者无效；重度 MS 伴快速房颤时优先控制心室率","renal":"按 CrCl 减量，CrCl <30 慎用","hepatic":"遵说明书","interact":"低钾、低镁、高钙增强毒性；与胺碘酮、维拉帕米、克拉霉素合用升高浓度"},{"name":"华法林","dose":"首剂 2.5–3 mg qd（中国人群），根据 INR 调整；二尖瓣机械瓣目标 INR 2.5–3.5，主动脉瓣机械瓣 2.0–3.0","note":"机械瓣置换后终身抗凝；风湿性中重度 MS 合并房颤者即使未手术也需抗凝（INR 2.0–3.0）；NOAC 禁用于机械瓣与中重度风湿性 MS；出血高危者需评估 HAS-BLED","renal":"重度肾功能不全者出血风险增加，需更密切监测 INR","hepatic":"肝硬化者凝血因子合成减少，INR 目标需个体化并警惕出血","interact":"胺碘酮、甲硝唑、复方磺胺甲噁唑升高 INR；利福平、卡马西平降低 INR；与 NSAIDs、抗血小板药合用增加出血"},{"name":"苄星青霉素","dose":"成人 120 万 U 肌注，每 4 周 1 次；体重 <27 kg 儿童 60 万 U 肌注，每 4 周 1 次","note":"风湿热二级预防：风湿性心脏病伴瓣膜损害者至少 10 年或至 40 岁，严重瓣膜病变或人工瓣者需终身；青霉素过敏者改用红霉素或阿奇霉素","renal":"肾功能不全无需调整（单次肌注）","hepatic":"遵说明书","interact":"与丙磺舒合用升高青霉素浓度；与口服避孕药合用可能降低避孕效果"},{"name":"依那普利","dose":"2.5–5 mg bid 起始，按血压与肾功能调整至 10 mg bid","note":"用于合并 HFrEF 或高血压者；重度 AS 伴低血压、双侧肾动脉狭窄者禁用或慎用；不可用于妊娠期","renal":"双侧肾动脉狭窄、孤立肾禁用；起始后 1–2 周复查肌酐与血钾","hepatic":"肝功能不全者减量（前体药需肝代谢）","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低疗效并增加肾损"}],"nonDrug":["手术指征：有症状的重度瓣膜病变；无症状但 LVEF ≤50%、左室收缩末径 >45 mm（MR/AR）、静息肺动脉收缩压 >50 mmHg、新发房颤（MS/AS）或运动试验异常者","**同期处理原则**：所有需干预的瓣膜应在一次手术中解决（Ⅰ类推荐），避免二次手术与遗留病变；合并重度 AS 与中度 MR 时，MR 可能在 AS 解除后减轻，需术中经食管超声重新评估再决定是否处理二尖瓣","**顺序原则**：先解除梗阻性病变（AS、MS），再纠正反流；先处理左心（主动脉瓣、二尖瓣），三尖瓣在左心瓣膜处理、心脏复跳后经右房评估再成形，避免过度矫正或遗漏","术式选择：AS 行 SAVR 或 TAVI（按年龄、风险与解剖）；MS 首选经皮球囊二尖瓣成形（瓣口面积 ≤1.5 cm²、Wilkins 评分 ≤8、无左房血栓、无中重度 MR）；MR 优先修复而非置换；TR 用成形环或 De Vega","人工瓣选择：年龄 <60–65 岁、预期寿命长、可耐受抗凝者倾向机械瓣；≥65 岁或出血风险高者倾向生物瓣，需个体化并与患者共同决策","术后随访：出院前与术后 3–6 个月复查超声，机械瓣终身监测 INR，生物瓣术后 10 年起每年评估衰败"],"life":["限盐 2–3 g/d、控制体重，每日称重；出现体重 3 天增加 >2 kg、气促加重及时就诊","风湿热二级预防：每 4 周肌注苄星青霉素，不可自行停药；注意口腔卫生与牙科操作前预防","机械瓣患者避免剧烈碰撞性运动，定期监测 INR（稳定后每 4 周一次），避免大量食用维生素 K 含量波动大的食物","妊娠前多学科评估：机械瓣者妊娠期抗凝方案复杂（华法林致畸与出血风险），需心内科、产科与麻醉共同管理","每 6–12 个月复查超声心动图与心电图，房颤者评估抗凝与心室率控制"]},"prog":"未干预的症状性重度瓣膜病预后差：症状性重度 AS 平均生存 2–3 年，症状性重度 MS 10 年生存率显著下降，合并肺高压与右心衰者更差。双瓣置换围术期死亡率约 5%–10%，高于单瓣手术，需心脏团队评估；同期手术可改善症状与长期生存，但机械瓣需终身抗凝、生物瓣存在远期衰败风险。","refs":["经导管主动脉瓣置换术中国专家共识（2020 更新版）","2021 ESC/EACTS Guidelines for the management of valvular heart disease","2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease","《内科学》（第 9 版，人民卫生出版社，2018）"]}]}]},"cts":{"categories":[{"id":"chest_trauma","name":"胸部创伤","rank":1,"summary":"胸部创伤以「先解除致命压迫、再恢复通气与循环」为原则：张力性气胸需立即针刺/指切减压后置管，血气胸以大口径胸管引流并在持续出血 >200 mL/h 时开胸，连枷胸重点在充分镇痛、呼吸支持与肺挫伤管理。","compare":[{"diseaseId":"ct_tension_pnx","dx":"突发严重呼吸困难、患侧呼吸音消失、气管向对侧偏移、颈静脉怒张伴低血压；叩诊呈鼓音，床旁超声无肺滑动征","key":"血流动力学不稳定 + 单侧呼吸音消失 = 立即穿刺减压，不等 X 线；针刺后改置胸管"},{"diseaseId":"ct_hemothorax","dx":"创伤后呼吸困难、患侧叩诊浊音、呼吸音减弱，X 线/US 见胸腔积液，胸管置入见血性引流液","key":"首次引流量 >1000 mL 或持续 >200 mL/h 达 3 h 需开胸；同时处理低血容量性休克"},{"diseaseId":"ct_flail","dx":"≥3 根相邻肋骨各有 ≥2 处骨折，出现反常呼吸运动，伴胸壁压痛、呼吸困难和低氧","key":"决定性治疗为充分镇痛（硬膜外/肋间阻滞）+ 无创/有创通气；反常呼吸严重或呼吸衰竭时考虑肋骨内固定"}],"diseases":[{"id":"ct_tension_pnx","name":"张力性气胸","aka":["张力性气胸","Tension Pneumothorax","高压性气胸"],"rank":1,"basic":{"define":"胸膜腔内气体只进不出、压力持续升高，压迫同侧肺并使纵隔移位、腔静脉回流受阻，可在数分钟内导致循环衰竭的致命性急症。","risk":["胸部钝性/穿透伤（肋骨骨折刺破肺、膈肌破裂）","机械通气（尤其大潮气量、高水平 PEEP）或气道正压通气者","胸腔穿刺/置管、肺活检、支气管镜等操作后","自发性气胸患者突然剧烈咳嗽或正压通气"],"epi":"胸部创伤在创伤死亡中占 20%–25%，其中张力性气胸约占胸部创伤的 5%，但院前可预防性死亡的主要原因之一；合并胸腔出血与休克时病死率显著升高。"},"patho":"胸膜腔与肺或气道之间形成单向活瓣：吸气时气体逸入胸膜腔，呼气时活瓣关闭，胸腔内压逐步超过大气压。高压使同侧肺萎陷、胸腔内静脉受压、纵隔向健侧移位，导致回心血量急剧减少、心排量下降；若未纠正，数分钟内出现休克与心跳骤停。健侧肺受压与纵隔摆动进一步加重低氧与二氧化碳潴留。","dx":{"criteria":["临床上以「发现即处理」为原则，出现以下三联征即临床诊断：突发严重呼吸困难、患侧呼吸音消失、低血压/休克","体格检查：患侧胸廓饱满、叩诊过清音至鼓音、气管偏向健侧、颈静脉怒张；听诊呼吸音消失","床旁超声：肺滑动征消失、无 B 线、M 型超声见「条形码征」（barcode sign）","X 线（病情允许时）：患侧大量透亮区、肺完全萎陷、纵隔与心脏向健侧移位、膈肌低平","必须与血胸、心脏压塞、大面积肺不张鉴别；穿刺减压后症状明显缓解可回证诊断"],"workup":["首要为快速评估 ABC、生命体征与血氧饱和度；勿因等待影像延误减压","床旁胸膜超声作为快速确认手段，每 5–10 min 动态监测","减压后行胸部 X 线确认肺复张与胸管位置","血气分析、乳酸、血常规、凝血功能与血型","机械通气患者需警惕气道压力骤升与潮气量骤降，应立即排查","对合并钝性胸部创伤者行胸腹部 CT 评估肺挫伤、隐匿性血胸与膈肌损伤"],"grading":"按发生机制分为开放性/闭合性张力性气胸；按患者状态分为血流动力学稳定型（可先穿刺或小口径引流）与不稳定型（立即针刺/指切减压）；无统一分级系统。"},"ddx":[{"name":"大量血胸（ct_hemothorax）","point":"与本类 ct_hemothorax 的鉴别点：张力性气胸叩诊呈过清音/鼓音、床旁超声无积液、无肺滑动征；血胸叩诊浊音、超声见无回声液体伴肺漂浮征，且多伴低血容量性休克。"},{"name":"连枷胸（ct_flail）","point":"与本类 ct_flail 的鉴别点：连枷胸可见胸壁反常呼吸运动与肋骨多段骨折，呼吸音通常存在（若合并气胸则减弱）；单纯连枷胸不引起患侧呼吸音完全消失与纵隔移位。"},{"name":"心脏压塞","point":"同为创伤后休克原因，特征为 Beck 三联征（低血压、颈静脉怒张、心音低钝）、超声见心包积液与右心塌陷；可行心包穿刺。"},{"name":"大面积肺不张/主支气管断裂","point":"气管断离时患侧因支气管中断出现「肺坠落征」，纵隔向患侧移位、常伴张力性气胸或皮下气肿；胸腔闭式引流持续大量漏气是重要提示。"},{"name":"自发性气胸（非创伤）","point":"无创伤史，年轻瘦高体型或有 COPD/肺大泡；一般不引起严重血流动力学障碍，仅少数形成张力性。"}],"tx":{"drug":[{"name":"莫西沙星","dose":"400 mg 静滴 qd，或遵说明书（创伤后胸腔创伤/引流常规预防感染，一般 ≤48–72 h）","note":"单纯创伤性气胸不常规预防性用抗菌药；合并肺挫伤、胸腔积液、开放性伤或留置胸管时短期使用","renal":"CrCl <30 减量","hepatic":"重度肝功能不全慎用","interact":"与含铝/镁抗酸剂同服降低吸收；QT 延长风险叠加（与胺碘酮等合用需监测心电图）"},{"name":"头孢唑林","dose":"1–2 g 静滴 q8h，或遵说明书（开放性胸部伤口/手术预防用药）","note":"对青霉素过敏者可用克林霉素替代","renal":"CrCl <35 时按说明书延长间隔","hepatic":"","interact":"与丙磺舒合用升高血药浓度"},{"name":"芬太尼","dose":"25–50 μg 静脉推注，必要时重复，或 0.5–1 μg/kg 快速诱导后泵入","note":"用于减压操作与胸管置入的镇痛，同时避免呼吸抑制加重低氧","renal":"无需调整","hepatic":"严重肝病清除减慢，减量","interact":"与苯二氮䓬类合用加重呼吸抑制"},{"name":"氯胺酮","dose":"0.5–1 mg/kg 静脉缓推（诱导镇痛与分离麻醉，必要时 0.25 mg/kg 追加）","note":"血流动力学不稳定患者的镇痛镇静优选，对呼吸循环抑制较轻","renal":"遵说明书","hepatic":"重度肝功能不全减量","interact":"与交感神经兴奋药合用加重高血压"},{"name":"去甲肾上腺素","dose":"0.05–0.5 μg/kg/min 静脉泵入，滴定至收缩压 ≥90 mmHg","note":"仅在减压后仍存在低血压时使用，同时积极补液与胸腔血液回输","renal":"","hepatic":"","interact":"与其他交感胺类合用可致严重高血压"}],"nonDrug":["立即针刺减压：患侧第 2 肋间锁骨中线或第 4–5 肋间腋中线，用 14–16 G 粗针（或 8 cm 长针）刺入胸膜腔，听到气体逸出声后接三通/指套活瓣","指切减压（finger thoracotomy）：针刺无效或需要快速过渡时，在第 4–5 肋间腋前线切开皮肤、钝性分离至胸腔","针刺减压后必须立即放置更大口径（28–32 Fr）胸腔闭式引流管，连接水封瓶","机械通气患者：调低潮气量与 PEEP，必要时暂停正压通气，气管插管时避免过度通气","中重度漏气或肺不张者予低负压吸引（−20 cmH₂O），记录漏气量；引流管确认无漏气、肺复张后夹管观察","持续大量漏气提示支气管断裂，需行支气管镜检查，必要时手术修复","胸腔内压力高、心脏骤停者按复苏流程处理，同时行双侧腋中线胸腔减压（双侧针减压）"],"life":["伤后 24–48 h 密切监测呼吸频率、SpO₂ 与血气，警惕迟发性张力性气胸与复张性肺水肿","胸管拔除指征：无漏气 ≥24 h、引流量 <100–200 mL/d、胸片示肺完全复张；拔管后复查胸片","出院后 4–6 周内避免乘飞机、潜水及剧烈体力活动，咳嗽时勿过度用力","戒烟、呼吸功能锻炼；有自发性气胸史者复发风险较高，需专科随访"]},"prog":"及时减压与引流者存活率 >90%；未处理的张力性气胸可在数分钟内致死，是院前可预防性死亡的常见原因。合并严重肺挫伤、休克或多发伤者病死率可达 10%–20%。","refs":["《胸部创伤诊治中国专家共识》（中华医学会创伤学分会，2018）","《美国高级创伤生命支持（ATLS）第 10 版》（2018）","《欧洲创伤与急诊外科学会胸部创伤管理指南》（2017）"]},{"id":"ct_hemothorax","name":"血气胸","aka":["血胸","血气胸","Hemothorax","Hemopneumothorax"],"rank":2,"basic":{"define":"胸膜腔内有血液与气体同时积聚（或单纯血胸），可由肋间血管、胸廓内动脉、肺实质撕裂或心脏大血管损伤引起，大量血胸可压迫肺并导致失血性休克。","risk":["钝性或穿透性胸部创伤（肋骨骨折、刀刺伤、枪伤）","医源性：胸腔穿刺、胸管置入、中心静脉置管、肺活检","凝血功能障碍或抗凝治疗","脊柱/肋骨骨折移位刺破血管"],"epi":"血胸是创伤后最常见的胸腔积液原因，约占胸部创伤的 1/3；合并休克的血胸病死率可达 20%–30%。我国胸部创伤患者中肋骨骨折、血胸与气胸为前三位。"},"patho":"胸膜腔出血使胸腔内压升高并压迫肺、限制膈肌运动，同时造成体循环失血与有效循环血量下降；胸腔内积血中的纤维蛋白可机化成纤维胸，压迫肺并限制胸廓活动。出血源常见为肋间动脉、胸廓内动脉（压力高、出血迅猛）、肺实质（低压、多可自限）及心脏大血管（绝大多数迅速致死）。血气胸时气体与血液混合，形成液平面。","dx":{"criteria":["创伤后呼吸困难、胸痛、患侧叩诊浊音、呼吸音减弱或消失，伴失血表现（心动过速、低血压、面色苍白）","床旁超声（FAST）：胸腔内无回声积液伴肺「漂动征」，是快速确诊与量化首选","胸部 X 线：胸腔积液伴气液平面（立位），但可漏诊 <200–300 mL 积血；卧位片示弥漫性模糊","胸部 CT：精确定量、评估肺挫伤、肋骨骨折与隐匿性血胸，血流动力学稳定者首选","胸腔闭式引流见血性液体可确诊，需记录引流量与引流速度","疑大血管或心脏损伤（高度不稳定、大量血胸）时行增强 CT 或急诊手术探查"],"workup":["首诊：生命体征、气管位置、呼吸音与颈静脉评估；建立两条大口径静脉通路","FAST 超声 / 床旁胸片，需在抢救同时完成","胸腔闭式引流后立即评估引流量与血压反应；查血红蛋白、血细胞比容、凝血、血型配血","血流动力学稳定者行胸腹 CT 增强，评估活动性出血（造影剂外溢）与合并伤","血气分析、乳酸、血栓弹力图/凝血功能指导复苏（目标 MAP、Hb 维持）","合并持续漏气或引流不畅时复查胸片/超声，必要时胸腔镜探查"],"grading":"按量分型：少量 <500 mL；中等 500–1000 mL；大量 >1000 mL（或 >1/3 患侧胸腔容积，X 线示患侧胸廓 >50% 阴影伴纵隔移位）。按病程分：急性、亚急性、机化性（慢性）。"},"ddx":[{"name":"张力性气胸（ct_tension_pnx）","point":"与本类 ct_tension_pnx 的鉴别点：血胸叩诊浊音、超声见液体与肺漂浮征、常伴失血性休克；张力性气胸叩诊鼓音、无液体回声且伴明显纵隔移位与颈静脉怒张。"},{"name":"连枷胸（ct_flail）","point":"与本类 ct_flail 的鉴别点：连枷胸以反常呼吸运动与多段肋骨骨折为特征，可无大量胸腔积液；血胸以患侧叩实音、积液与失血为主，超声/CT 可直接鉴别。"},{"name":"乳糜胸","point":"引流液呈乳白色（或进食后变浊），来自胸导管损伤；血胸为血性液体且 Hb 高。"},{"name":"心脏压塞","point":"可伴胸腔积液但以心包积液为特征，超声见心包腔积液与心腔塌陷；需心包穿刺/开窗。"},{"name":"胸腔积液（创伤无关，如感染/心衰）","point":"无外伤史或无活动性出血表现，积液清澈或有感染征象；创伤后早期通常为血性积液，需结合病史判断。"}],"tx":{"drug":[{"name":"氨甲环酸","dose":"创伤后 3 h 内 1 g 静脉滴注（>10 min），随后 1 g 静滴 8 h（CRASH-2 方案）","note":"用于创伤性大出血，可降低失血相关死亡率；伤后 3 h 内使用获益","renal":"重度肾功能不全减量","hepatic":"遵说明书","interact":"与其他促凝药合用需评估血栓风险"},{"name":"头孢唑林","dose":"1–2 g 静滴 q8h（严重创伤开放胸伤可延长至 24–48 h，具体遵说明书）","note":"用于开放性胸伤与胸管置入后感染预防；穿透性胸部创伤建议短程预防","renal":"CrCl <35 时按说明书延长间隔","hepatic":"","interact":"与丙磺舒合用升高血药浓度"},{"name":"芬太尼","dose":"25–50 μg 静脉推注，必要时重复；或 0.5–1 μg/kg 泵入","note":"用于清创、胸管置入与骨折镇痛；须避免过度呼吸抑制","renal":"无需调整","hepatic":"严重肝病减量","interact":"与苯二氮䓬类合用加重呼吸抑制"},{"name":"去甲肾上腺素","dose":"0.05–0.5 μg/kg/min 静脉泵入，滴定至 MAP ≥65 mmHg","note":"仅在充分容量复苏后仍低血压时使用","renal":"","hepatic":"","interact":"与其他交感胺类合用致严重高血压"},{"name":"浓缩红细胞/新鲜冰冻血浆（按需）","dose":"按大量输血方案：红细胞:血浆:血小板约 1:1:1 的比例，视出血量与凝血状态调整（具体剂量遵输血科方案）","note":"Hb <70 g/L 或活动性出血伴 Hb <90 g/L 时输注；纠正凝血病用 FFP 与血小板","renal":"","hepatic":"","interact":""}],"nonDrug":["立即放置大口径（28–32 Fr）胸腔闭式引流管，一般取第 4–5 肋间腋中线，连接水封瓶，避免过度负压吸引","开胸指征：首次引流量 >1000 mL（或 >20 mL/kg）；持续引流 >200 mL/h 达 2–3 h；伴持续失血性休克、心包压塞或大血管损伤","穿刺/引流同时行损伤控制性复苏（限制性液体复苏、允许性低血压）与快速输血","血流动力学稳定者的残余血胸（>300–500 mL）或机化性血胸行胸腔镜（VATS）清除，减少机化成纤维胸","引流不畅（疑血块堵塞）时可行胸管冲洗或换管，持续引流是防止纤维胸的关键","合并肺挫伤/ARDS 者采取肺保护性通气（潮气量 6 mL/kg 理想体重，PEEP 滴定）","术后或引流中持续监测引流量与血气，判定是否需要外科止血（电凝、缝合、肺楔形切除或肺叶切除）"],"life":["引流期间每日记录引流量、性状与漏气情况，复查胸片评估肺复张","拔管后 4–6 周避免高强度胸廓运动与憋气，鼓励深呼吸与排痰预防肺不张","肋骨骨折康复期避免负重，加强镇痛后早期下床活动","出院后 2 周、6 周门诊复查，评估有无残余血胸或纤维胸"]},"prog":"及时引流且出血自发停止者预后良好，病死率约 5%–10%；大量血胸需开胸者病死率 20%–30%。机化性血胸未及时清除可致胸膜纤维化、限制性通气障碍与反复感染。","refs":["《胸部创伤诊治中国专家共识》（中华医学会创伤学分会，2018）","《世界急诊外科学会（WSES）胸部创伤管理指南》（2020）","《美国高级创伤生命支持（ATLS）第 10 版》（2018）"]},{"id":"ct_flail","name":"连枷胸","aka":["连枷胸","Flail Chest","浮动胸壁"],"rank":3,"basic":{"define":"连续 3 根及以上相邻肋骨各发生 2 处及以上骨折，使该段胸壁与胸廓骨性框架失去连续性，出现随呼吸矛盾运动的「浮动胸壁」，并几乎总伴肺挫伤。","risk":["高能量钝性胸伤（交通事故、坠落、重物压砸）","高龄（>65 岁）、骨质疏松","多发伤、合并休克的颅脑/腹部伤","长期吸烟或慢性肺病（呼吸储备差）"],"epi":"约占需要住院的胸部创伤的 5%–10%，老年创伤患者比例更高；连枷胸患者病死率 10%–30%，其中合并肺挫伤与 ARDS 是主要死因。"},"patho":"外力使肋骨在前后受力点及侧方弯曲点各断裂，形成可活动的胸壁节段，吸气时软化区向内凹陷、呼气时向外膨出（反常呼吸）。但现代观点认为，连枷胸导致呼吸衰竭的主要原因不是「反常呼吸」本身，而是其下方的肺挫伤、肺泡出血与水肿、肺泡顺应性下降及疼痛引起的浅快呼吸，最终发展为 ARDS。矛盾运动造成通气效率下降与合并气胸/血胸。","dx":{"criteria":["胸部创伤史伴严重胸痛、呼吸困难与局部骨擦音；可见患侧胸壁随呼吸矛盾运动","确诊需影像：CT 骨窗显示连续 ≥3 根相邻肋骨各 ≥2 处骨折（X 线亦可，但 CT 敏感更高）","几乎均合并肺挫伤：CT 见肺内斑片状磨玻璃/实变影，与肋骨骨折区域对应","伴低氧血症（PaO₂/FiO₂ <300）与呼吸功增加；需评估是否合并气胸/血胸","疼痛下呼吸浅快、动脉血 CO₂ 升高提示呼吸衰竭倾向","老年人可因胸壁压痛不明显、单纯弱跌倒而出现连枷胸，影像学评估不可省略"],"workup":["胸腹部 CT 增强（骨窗+肺窗）为首选，评估肋骨、肩胛骨与胸骨骨折、肺挫伤程度与合并损伤","血气分析（反复）、SpO₂ 连续监测","床旁超声评估胸腔积液、气胸与膈肌运动","血常规、乳酸、凝血功能、心肌酶（排查心脏挫伤，必要时心电图与肌钙蛋白）","疼痛评分（NRS）与呼吸功评估，作为镇痛方案调整依据","若需长期通气，评估 ARDS 风险（按柏林标准）与引流管情况"],"grading":"按肋骨骨折数目与范围分型：轻度（3–4 根、无呼吸衰竭）；中度（5–7 根或伴肺挫伤 >20%）；重度（≥8 根、双侧或伴呼吸衰竭/需机械通气）。可采用胸壁伤严重度评分（如 AIS、TTSS 改良评分）辅助决策。"},"ddx":[{"name":"张力性气胸（ct_tension_pnx）","point":"与本类 ct_tension_pnx 的鉴别点：连枷胸可见胸壁矛盾运动、患侧呼吸音通常可闻及；张力性气胸呼吸音消失、气管移位、血流动力学迅速恶化，需不等影像立即减压。"},{"name":"大量血胸（ct_hemothorax）","point":"与本类 ct_hemothorax 的鉴别点：连枷胸以胸壁反常运动和疼痛为主，胸腔积液可少或无；血胸以患侧叩实音、快速失血与休克为特征，积液量大。"},{"name":"单纯多发性肋骨骨折","point":"骨折数量不足以构成浮动胸壁（<3 根或未达 2 处骨折），无反常呼吸运动；但同样可引起剧痛与低通气，需警示。"},{"name":"胸骨骨折合并胸壁不稳定","point":"多为方向盘伤，胸骨骨折可致前胸壁不稳定；CT 矢状位重建可明确骨折线与移位。"},{"name":"慢性阻塞性肺疾病急性加重","point":"有 COPD 病史、无外伤史，胸壁无压痛与骨折；但连枷胸患者也可合并 COPD 急性加重，需依靠病史与影像区分。"}],"tx":{"drug":[{"name":"布比卡因（肋间/椎旁阻滞）","dose":"0.25%–0.5% 布比卡因，按骨折区域行多节段肋间阻滞或椎旁阻滞，每节段 3–5 mL，或遵说明书与麻醉科方案","note":"胸壁阻滞是连枷胸镇痛的核心，可显著改善呼吸力学；注意局麻药最大剂量与心律失常风险","renal":"重度肾功能不全时慎用（代谢产物蓄积）","hepatic":"重度肝功能不全减量","interact":"与胺碘酮、氟喹诺酮等合用增加 QT 延长与心脏毒性风险"},{"name":"罗哌卡因（硬膜外镇痛）","dose":"0.1%–0.2% 罗哌卡因 + 阿片类，经胸段硬膜外导管持续输注，速率 4–8 mL/h，或遵麻醉科方案","note":"硬膜外阻滞（T4–T8 置管）是控制多发性肋骨骨折疼痛、减少呼吸衰竭的有效方式，低血压风险较低","renal":"遵说明书","hepatic":"重度肝功能不全减量","interact":"与阿片类合用增加低血压与呼吸抑制"},{"name":"吗啡","dose":"2–4 mg 静脉推注，按需每 2–4 h 追加；或 PCA（负荷 2–5 mg 后 0.5–1 mg/h，bolus 0.5–1 mg，锁定 5–10 min）","note":"疼痛控制不足将加重低通气与肺不张；须监测呼吸频率与 SpO₂","renal":"肾功能不全者活性代谢产物蓄积，减量","hepatic":"严重肝病减量","interact":"与镇静药合用增加呼吸抑制"},{"name":"对乙酰氨基酚","dose":"500–1000 mg 口服/静滴 q6h，每日总量 ≤2 g（肝病者 ≤2 g）","note":"基础镇痛，联合阿片类药物以减少后者用量","renal":"CrCl <30 时延长间隔","hepatic":"严重肝病禁用或减量","interact":"与华法林合用可影响 INR；与酒精合用增加肝毒性"},{"name":"头孢唑林","dose":"1–2 g 静滴 q8h，或遵说明书（肋骨内固定手术预防用药）","note":"需行肋骨内固定或胸腔引流时短期使用","renal":"CrCl <35 时延长间隔","hepatic":"","interact":"与丙磺舒合用升高血药浓度"},{"name":"依诺肝素","dose":"40 mg 皮下注射 qd（CrCl <30 或高危出血者 20 mg qd），自出血稳定后开始","note":"用于创伤后 VTE 预防，肋骨骨折与制动患者风险较高","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板/NSAIDs 合用增加出血"}],"nonDrug":["充分镇痛是治疗核心：硬膜外镇痛、椎旁阻滞或持续肋间神经阻滞，必要时配合镇痛泵","呼吸支持：低氧或呼吸功增加者尽早无创通气（CPAP/BiPAP）；无效、意识障碍或气道保护能力差者气管插管有创通气，采用肺保护策略（VT 6 mL/kg 理想体重）","鼓励深呼吸、咳嗽与早期活动，配合呼吸训练器、吸痰与体位引流，预防肺不张与肺炎","快速康复（ERAS）理念：限制性液体、镇痛后 24–48 h 内下床活动","外科肋骨内固定（SSRF）指征：严重移位性连枷胸、无法脱机的呼吸衰竭、胸壁畸形、开胸手术伴多发肋骨骨折；可能在减少通气时间与肺炎方面获益","合并血气胸者先行胸腔闭式引流道；肺挫伤合并 ARDS 者按柏林标准行肺保护性通气与俯卧位","胸壁外固定（如束胸带）不推荐常规使用，因其限制通气并增加肺不张风险"],"life":["住院期间每日评估疼痛评分、呼吸频率、SpO₂ 与胸部物理治疗完成度","出院前复查胸片，确认无残余积液与气胸；出院后 2–4 周复查","出院后 6–8 周逐步恢复活动，避免剧烈咳嗽、搬重物与对抗性运动","戒烟与肺功能锻炼；老年患者加强营养支持与跌倒预防"]},"prog":"保守治疗者病死率约 10%–15%，合并肺挫伤与 ARDS 达 20%–30%；无合并伤的年轻患者多可恢复。外力固定/内固定可缩短机械通气时间与 ICU 住院日。老年连枷胸患者需长期呼吸功能随访。","refs":["《胸部创伤诊治中国专家共识》（中华医学会创伤学分会，2018）","《连枷胸诊疗中国专家共识》（中国胸心血管外科相关共识，2020）","《世界急诊外科学会（WSES）胸部创伤管理指南》（2020）"]}]},{"id":"chest_tumor","name":"胸部肿瘤与术后","rank":2,"summary":"胸部肿瘤以外科切除为核心，术前需完成分期（TNM + 病理/分子分型）与心肺功能评估；肺癌按分期选择肺叶/肺段切除 + 淋巴结清扫，食管癌强调新辅助治疗后根治性切除与消化道重建，术后并发症（肺不张、吻合口瘘）是主要死因。","compare":[{"diseaseId":"ct_lung_ca","dx":"CT 见肺部结节/肿块，PET-CT 或穿刺活检确诊，分期依据 T（肿瘤大小/侵犯）、N（纵隔/肺门淋巴结）、M（远处转移）","key":"早期（Ⅰ–Ⅱ期）以肺叶/解剖性肺段切除 + 淋巴结清扫为主，Ⅲ期多需新辅助后再评估手术，驱动基因阳性者靶向/免疫治疗"},{"diseaseId":"ct_esoph","dx":"胃镜+组织活检确诊，超声内镜（EUS）评估 T 分期，胸腹部增强 CT/超声内镜评估淋巴结，PET-CT 排查远处转移","key":"进展期食管癌以新辅助放化疗 + 根治性切除（McKeown/Ivor Lewis 术）+ 食管胃吻合为主"}],"diseases":[{"id":"ct_lung_ca","name":"肺癌外科治疗","aka":["肺癌","肺腺癌","非小细胞肺癌","NSCLC","Lung Cancer Surgery"],"rank":1,"basic":{"define":"起源于支气管黏膜上皮或肺泡上皮的恶性肿瘤，外科治疗是非小细胞肺癌（NSCLC）Ⅰ–Ⅲ期可切除及部分寡转移患者获得根治的主要手段，术式以解剖性肺叶切除/肺段切除 + 系统性淋巴结清扫为核心。","risk":["吸烟（含二手烟），与剂量和持续时间正相关","职业暴露（石棉、氡、铬、砷等）","家族史与既往肺部慢性病（COPD、肺纤维化）","高龄、长期暴露于空气污染（PM2.5）"],"epi":"我国肺癌发病率和死亡率均居恶性肿瘤首位，2022 年估计新发约 106 万例、死亡约 73 万例；男性发病率高于女性，但女性非吸烟腺癌比例在上升，>50% 患者确诊时已为晚期。"},"patho":"吸烟致癌物诱发支气管上皮不典型增生—原位癌—浸润癌的逐步演变；EGFR、ALK、KRAS、ROS1 等驱动基因突变是腺癌发生与靶向治疗的关键。NSCLC 以腺癌与鳞癌为主，主要经淋巴管转移至肺门与纵隔，经血行转移至脑、骨、肝与肾上腺；小细胞肺癌生长迅速、早期转移。肺门/纵隔淋巴结状态（N 分期）决定可切除性与预后。","dx":{"criteria":["高危人群低剂量螺旋 CT 筛查：发现肺结节 ≥8 mm 实性成分或亚实性病灶时进一步评估","病理确诊：支气管镜（中央型）、CT 引导经皮肺穿刺（外周型）或 EBUS-TBNA 纵隔淋巴结取样","组织采样需满足分子检测：EGFR 突变、ALK 融合、ROS1、MET、RET、KRAS G12C、PD-L1 表达","分期：胸腹部增强 CT + PET-CT + 头颅 MRI（必要时）评估 T/N/M；小细胞癌需全身分期","纵隔淋巴结评估：PET-CT 提示 N2 需 EBUS-TBNA 或纵隔镜病理证实","术前心肺功能评估：FEV₁、DLCO、心肺运动试验（CPET）判断可耐受切除范围"],"workup":["胸部增强 CT（薄层）+ 腹部超声/增强 CT + 头颅 MRI + 骨扫描或 PET-CT 完成分期","支气管镜/EBUS-TBNA 或 CT 引导穿刺获取病理与分子分型","肺功能（FEV₁、DLCO）、动脉血气、六分钟步行试验（必要时 CPET）、心脏超声","血常规、肝肾功能、凝血、肿瘤标志物（CEA、CYFRA21-1、NSE）","术前戒烟 ≥4 周、呼吸训练与气道雾化；评估无手术禁忌（如未控心梗、严重肺动脉高压）","术后病理（pTNM）与分子分型决定辅助治疗"],"grading":"TNM 分期（UICC/AJCC 第 8 版）：ⅠA（T1a-cN0M0）、ⅠB、ⅡA、ⅡB、ⅢA（可切除）、ⅢB–Ⅳ期（多为不可切除）。病理分型：腺癌、鳞癌、大细胞癌、小细胞肺癌（SCLC）。切除范围：肺叶切除（金标准）、解剖性肺段切除（≤2 cm 外周磨玻璃为主、心肺功能受限者可选）。淋巴结清扫：系统性淋巴结清扫（SND）或采样。"},"ddx":[{"name":"食管癌（ct_esoph）","point":"与本类 ct_esoph 的鉴别点：肺癌以咳嗽、咯血、胸痛与肺内肿块为表现，病理来自肺组织；食管癌以吞咽困难、体重下降为表现，胃镜+活检位于食管黏膜，CT 显示食管壁增厚。"},{"name":"肺转移瘤","point":"多发、边界清楚、多位于肺外周，有原发肿瘤病史；PET-CT 与病史可鉴别，必要时穿刺。"},{"name":"肺结核球/结核性肉芽肿","point":"病灶可有钙化、卫星灶，常位于上叶尖后段，痰结核菌涂片/培养或 T-SPOT 阳性，抗结核试验性治疗可缩小。"},{"name":"炎性假瘤/机化性肺炎","point":"影像可呈肿块样但边缘模糊、抗生素或激素治疗后缩小；需随访或穿刺排除。"},{"name":"良性肺结节（错构瘤、硬化性肺细胞瘤）","point":"形态规则、生长缓慢、可见爆米花样钙化或明显强化；随访 2 年无变化可倾向良性。"}],"tx":{"drug":[{"name":"头孢呋辛","dose":"1.5 g 静脉滴注 q8h，术前 0.5–1 h 单剂，术后按需 24–48 h（或遵说明书）","note":"围手术期预防用药，降低术后手术部位与肺部感染","renal":"CrCl <30 按说明书延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血风险"},{"name":"奥希替尼","dose":"80 mg 口服 qd（EGFR 19del/L858R 突变阳性，术后辅助或晚期）","note":"ⅠB–ⅢA 期 EGFR 突变患者术后辅助靶向治疗（ADAURA 研究）显著延长无病生存；需监测皮疹、腹泻、间质性肺病与 QT","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全减量","interact":"与强 CYP3A4 诱导剂（利福平、卡马西平）合用降低浓度；避免与质子泵抑制剂同服时吸收减少"},{"name":"培美曲塞 + 顺铂（辅助化疗）","dose":"培美曲塞 500 mg/m² 静滴 d1（非鳞癌），顺铂 75 mg/m² d1，每 21 d 一周期，共 4 周期；术前需补充叶酸 400 μg qd 与维生素 B12 1000 μg 肌注","note":"用于完全切除的Ⅱ–ⅢA 期 NSCLC 辅助化疗，可提高 5 年生存约 5%","renal":"CrCl <45 时培美曲塞不推荐使用；顺铂肾功能不全需减量或换用卡铂","hepatic":"重度肝功能不全慎用","interact":"与非甾体抗炎药合用增加培美曲塞毒性；顺铂肾毒性叠加（氨基糖苷类）"},{"name":"帕博利珠单抗","dose":"200 mg 静脉滴注 q3w（或 400 mg q6w），用于 PD-L1 TPS ≥1% 的辅助/新辅助或晚期治疗，疗程按适应证与说明书","note":"围手术期免疫治疗需在 MDT 下评估（CheckMate-816 等研究支持新辅助化疗+免疫）；监测免疫相关不良反应（肺炎、甲状腺炎、结肠炎）","renal":"无需调整","hepatic":"轻中度无需调整，重度慎用","interact":"与全身糖皮质激素/免疫抑制剂合用可能降低疗效"},{"name":"昂丹司琼","dose":"8 mg 静脉推注（化疗前 30 min），必要时 8 mg q12h","note":"预防化疗所致恶心呕吐，联合地塞米松效果更好","renal":"遵说明书","hepatic":"重度肝功能不全每日总剂量不超过 8 mg","interact":"与其他延长 QT 的药物合用需监测心电图"},{"name":"低分子肝素（依诺肝素）","dose":"40 mg 皮下注射 qd，自术后 12–24 h 开始（出血风险高者延后）","note":"肺癌为 VTE 高危，术后预防一般至出院或 4 周","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板/抗凝药合用增加出血"}],"nonDrug":["可切除（Ⅰ–Ⅱ期，部分ⅢA 期）者行解剖性肺叶切除 + 系统性淋巴结清扫（或采样）；外周 ≤2 cm 的磨玻璃结节可考虑肺段切除","术前评估提示不能耐受肺叶切除者，可行亚肺叶切除（肺段/楔形），需保证切缘 ≥肿瘤直径","ⅢA 期（N2 单站、可切除）可在新辅助化疗±免疫治疗后重新评估手术；ⅢB–Ⅳ期以系统治疗为主","微创（VATS/RATS）肺叶切除已成为主流，在肿瘤学效果等同的前提下减少术后疼痛与住院时间","寡转移（单发脑、肾上腺转移）可考虑原发灶切除 + 转移灶局部治疗（立体定向放疗/SBRT）","术后辅助：Ⅱ–ⅢA 期行含铂辅助化疗 4 周期；EGFR 突变者加用奥希替尼辅助靶向；PD-L1 阳性者可考虑辅助免疫","术后肺康复：呼吸训练、有效排痰、早期下床活动","术后随访：前 2 年每 3–6 个月胸部 CT，之后每 6–12 个月"],"life":["术后 6–8 周内避免剧烈活动与提重物，逐步增加有氧运动（步行、爬楼训练）","严格戒烟，避免二手烟与厨房油烟暴露","营养支持（高蛋白饮食、体重监测），防治贫血与低蛋白血症","出现持续咳嗽、咯血、胸痛加重或发热需及时复诊；接种流感与肺炎球菌疫苗","心理支持与肺康复长期随访，靶向/免疫治疗期间定期复查肝肾功能、甲状腺功能与胸部影像"]},"prog":"完全切除的ⅠA 期 5 年生存率 >80%，ⅠB 约 70%，Ⅱ期约 50%–60%，ⅢA 期 30%–40%；不可切除的Ⅳ期 5 年生存率 <10%，但 EGFR/ALK 阳性者靶向治疗后中位生存可达 3–5 年。术后 2 年内为复发高峰。","refs":["《中国原发性肺癌诊疗指南（2023 年版）》（国家卫生健康委员会）","《中国临床肿瘤学会（CSCO）非小细胞肺癌诊疗指南（2023）》","《NCCN 非小细胞肺癌指南（2023）》"]},{"id":"ct_esoph","name":"食管癌外科治疗","aka":["食管癌","食管鳞癌","Esophageal Cancer","Esophageal Carcinoma"],"rank":2,"basic":{"define":"起源于食管黏膜上皮的恶性肿瘤，我国以鳞状细胞癌为主（>90%），外科治疗以食管切除 + 消化道重建（食管胃吻合）+ 区域淋巴结清扫为核心，进展期需结合新辅助治疗。","risk":["长期吸烟与大量饮酒（协同作用）","喜食过烫、粗糙食物，缺乏新鲜蔬果","食管慢性刺激（反流性食管炎、腐蚀性食管炎、贲门失弛缓症）","HPV 感染、家族史；腺癌多与Barrett 食管/肥胖相关"],"epi":"我国食管癌新发约 22 万例/年、死亡约 18 万例/年，居恶性肿瘤第 5–6 位；地域差异显著（太行山区、河南林州、潮汕地区高发），鳞癌占比 >90%，男性多于女性，发病年龄多在 50 岁以上。"},"patho":"长期黏膜刺激导致鳞状上皮不典型增生—原位癌—浸润癌。肿瘤沿黏膜下层向两端蔓延，穿透肌层后侵及周围结构（气管、主动脉、胸膜），经食管旁及纵隔淋巴管转移，晚期经血行转移至肝、肺、骨。食管缺乏浆膜层，肿瘤易早期外侵，是预后较差的重要原因。","dx":{"criteria":["进行性吞咽困难（先固体后液体）、胸骨后疼痛、体重下降；晚期可有声嘶（喉返神经受累）、呛咳（食管气管瘘）","胃镜 + 活检是确诊金标准，须记录病变部位（颈段/胸上/中/下段）与长度","超声内镜（EUS）评估浸润深度（T）与区域淋巴结（N）","胸腹部增强 CT 评估食管壁增厚、外侵与淋巴结；PET-CT 排查远处转移","颈部超声评估颈部淋巴结；必要时支气管镜评估气管受累（胸上段病变）","病理类型（鳞癌/腺癌）、分化程度，必要时行 HER2、PD-L1 检测（腺癌为主）"],"workup":["胃镜及活检、染色内镜/碘染评估病变范围与多原发灶","EUS（T、N 分期）、胸腹增强 CT、PET-CT、颈部超声","肺功能、心功能评估（食管手术对呼吸与循环影响大）","营养评估（BMI、白蛋白、前白蛋白），营养不良者术前营养支持 7–10 d","血常规、肝肾功能、电解质；术前牙科处理与口腔清洁","声带功能检查（疑喉返神经受累）、气道评估"],"grading":"TNM 分期（AJCC 第 8 版）：T1a 黏膜层、T1b 黏膜下层、T2 肌层、T3 外膜、T4 邻近结构；N0–N3 按区域淋巴结数目；M0/M1。部分：颈段、胸上段（距门齿 20–25 cm）、胸中段（25–30 cm）、胸下段（30–40 cm）。早期（Tis–T1a）可行内镜下切除（ESD/EMR）。"},"ddx":[{"name":"肺癌（ct_lung_ca）","point":"与本类 ct_lung_ca 的鉴别点：食管癌以吞咽困难与体重下降为主，胃镜见食管黏膜病变并活检证实；肺癌以咳嗽、咯血、胸部肿块为表现，CT 可见肺内占位。"},{"name":"贲门失弛缓症","point":"吞咽困难呈间歇性、伴反流未消化食物，食管钡透呈「鸟嘴样」狭窄，胃镜见食管扩张而黏膜光滑，活检无癌细胞。"},{"name":"食管良性狭窄（腐蚀性/反流性）","point":"有腐蚀剂误服或长期反流史，狭窄段长、黏膜纤维化，活检无恶性细胞，但需警惕狭窄基础上的癌变。"},{"name":"食管平滑肌瘤/间质瘤","point":"黏膜下隆起、表面黏膜光滑，EUS 见起源于固有肌层的低回声肿块，活检（深层）可确诊。"},{"name":"食管痉挛/胃食管反流病","point":"吞咽困难多间歇、与情绪相关，食管测压见异常收缩，内镜无明显肿块。"}],"tx":{"drug":[{"name":"头孢呋辛/头孢唑林（围手术期预防）","dose":"头孢呋辛 1.5 g 静脉滴注（术前 0.5–1 h），术后 24–48 h 按需；或头孢唑林 2 g 单剂","note":"食管切除+吻合属清洁-污染手术，需覆盖革兰阴性菌与厌氧菌（可加甲硝唑）","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"奥美拉唑","dose":"40 mg 静脉推注 q12h（术后），能进食后改为 20–40 mg 口服 qd","note":"减少胃酸分泌，保护食管胃吻合口，降低反流与吻合口溃疡","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"抑制 CYP2C19，降低氯吡格雷活性；与地西泮、苯妥英合用延长半衰期"},{"name":"氟尿嘧啶 + 顺铂（新辅助化疗）","dose":"氟尿嘧啶 750–1000 mg/m²/d 持续静滴 d1–4（或 5-FU 800 mg/m² d1–5），顺铂 75–80 mg/m² d1，每 21 d 一周期，共 2–4 周期","note":"进展期（T2–T4 或 N+）推荐新辅助放化疗后手术（CROSS/NEOCRTEC5010 方案可加紫杉醇+卡铂+放疗 40–50.4 Gy）","renal":"顺铂 CrCl <60 减量或换卡铂；5-FU 肝功能不全减量","hepatic":"重度肝功能不全禁用 5-FU","interact":"5-FU 与华法林合用显著增加 INR；顺铂与氨基糖苷类合用增加肾毒性"},{"name":"甲氧氯普胺","dose":"10 mg 静脉/肌注 q6–8h，或 5–10 mg 口服 q8h（餐前）","note":"促进胃排空、减轻术后胃潴留与恶心；注意锥体外系反应","renal":"CrCl <30 减量","hepatic":"遵说明书","interact":"与抗精神病药/5-HT3 拮抗剂合用增加锥体外系与 QT 风险"},{"name":"肠内营养制剂（短肽型/整蛋白型）","dose":"术后 24–48 h 经鼻空肠管或空肠造瘘以 20–30 mL/h 起始，逐渐增至 60–100 mL/h，目标 25–30 kcal/kg/d","note":"早期肠内营养降低吻合口瘘与感染风险，改善术后恢复","renal":"肾功能不全选用低蛋白/肾病专用配方","hepatic":"肝病者选用支链氨基酸配方","interact":""},{"name":"低分子肝素（依诺肝素）","dose":"40 mg 皮下注射 qd，术后 12–24 h 开始（按出血风险调整）","note":"食管癌术后 VTE 高危，预防至出院或 4 周","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板/抗凝药合用增加出血"}],"nonDrug":["早期（Tis/T1a、无淋巴结转移）行内镜下黏膜下剥离（ESD）或黏膜切除（EMR）","可切除进展期（T1b–T4a、N0–N1、无远处转移）行根治性食管切除 + 二野/三野淋巴结清扫 + 食管胃吻合（McKeown 三切口、Ivor Lewis 右胸路径或左胸切口）","新辅助放化疗（CROSS 方案：紫杉醇+卡铂+41.4 Gy）后手术已为进展期食管鳞癌标准治疗之一","颈段食管癌以放疗/放化疗为主，手术需全喉食管切除，创伤大需慎重选择","术后吻合口瘘处理：禁食、充分引流、胃管减压、肠内营养支持，必要时食管支架或手术修补","术后肺部并发症（肺不张、肺炎、ARDS）为主要死因，需积极的呼吸道管理与早期活动","营养支持：术前营养风险评估（NRS 2002），术后经鼻空肠管早期喂养","随访：术后 3 年内每 3–6 个月胃镜/CT 复查，长期监测吻合口狭窄与反流"],"life":["术后长期少量多餐（每日 5–6 餐）、细嚼慢咽、餐后坐位或半卧位 ≥30 min，避免平卧与睡前 2 h 进食","避免过烫、过硬与辛辣食物，戒烟酒；监测体重与营养状况","每 3–6 个月复查胃镜与胸腹 CT，发现吻合口狭窄可行扩张","言语/吞咽功能训练，必要时康复科与营养科长期随访"]},"prog":"根治性切除后Ⅰ期 5 年生存率 60%–70%，Ⅱ期约 40%–50%，Ⅲ期 20%–30%；新辅助治疗后病理完全缓解（pCR）者预后更好。术后首要死因为肺部并发症与吻合口瘘，远期需监测吻合口复发与转移。","refs":["《中国食管癌诊疗指南（2022 年版）》（国家卫生健康委员会）","《中国临床肿瘤学会（CSCO）食管癌诊疗指南（2023）》","《食管癌规范化诊治指南（2019）》"]}]},{"id":"chest_benign","name":"胸部良性疾病","rank":3,"summary":"以「明确病因→分层干预」为原则：自发性气胸按原发/继发分层选择观察、抽气或引流；脓胸强调尽早充分引流 + 敏感抗生素，包裹性者选胸腔内纤溶或 VATS 剥脱；纵隔肿瘤按前/中/后三分区定位，结合标志物、影像与病理定性。","compare":[{"diseaseId":"cts_pneumothorax","dx":"突发单侧胸痛、呼吸困难，患侧呼吸音减弱、叩诊鼓音，胸片见胸膜线外无肺纹理透亮区","key":"原发气胸 <2 cm 可观察，继发气胸直接引流；复发或对侧气胸者评估 VATS 切除 + 胸膜固定"},{"diseaseId":"cts_empyema","dx":"发热、咳脓痰；胸腔积液浑浊或脓性，pH <7.20、LDH >1000 U/L、葡萄糖 <2.2 mmol/L","key":"抗生素 + 早期充分引流为核心；包裹性者行胸腔内纤溶或 VATS，机化期需纤维板剥脱"},{"diseaseId":"cts_mediastinum","dx":"多无症状，前纵隔（胸腺瘤、畸胎瘤、甲状腺肿、淋巴瘤）、中纵隔（淋巴结、囊肿）、后纵隔（神经源性肿瘤）","key":"前纵隔肿瘤伴眼睑下垂、易疲劳＝重症肌无力，查 AChR 抗体并术前控制"}],"diseases":[{"id":"cts_pneumothorax","name":"自发性气胸","aka":["自发性气胸","Spontaneous Pneumothorax","原发性自发性气胸","继发性自发性气胸","PSP","SSP"],"rank":1,"basic":{"define":"无外伤或医源性因素下胸膜腔异常积气致肺萎陷。无基础肺病者为原发性（PSP），合并 COPD、肺结核等基础病者为继发性（SSP）。","risk":["年轻瘦高男性（PSP，多与胸膜下肺大泡有关）","吸烟（剂量依赖，增加复发）","COPD、肺结核、间质性肺病、肺朗格汉斯细胞组织细胞增生症、淋巴管肌瘤病","Marfan 综合征等结缔组织病","经期子宫内膜异位相关气胸"],"epi":"PSP 约（18–28）/10 万男性、（1.2–6）/10 万女性，高峰 20–30 岁；SSP 随年龄上升，合并 COPD 者可达 26/10 万，住院病死率 5%–10%。"},"patho":"PSP 多为胸膜下肺大泡破裂，气体漏入胸膜腔；SSP 因气道炎症与小气道活瓣阻塞致肺泡内压升高破裂、肺弹性回缩下降，漏气持续。积气致通气/血流比例失调与低氧；单向活瓣使胸腔压升高时形成张力性气胸，压迫纵隔与腔静脉致循环衰竭。","dx":{"criteria":["突发单侧针刺样胸痛与呼吸困难，可伴干咳；SSP 可迅速呼吸窘迫","患侧呼吸音减弱或消失、叩诊鼓音；大量气胸时气管向健侧移位","立位胸片见脏层胸膜线外无肺纹理；CT 为气胸量与病灶评估金标准","按胸膜线至胸壁距离（BTS）：<2 cm 小量，≥2 cm 大量；或按容积 <20%、20%–40%、>40%","床旁超声肺滑动征消失、条码征，检出敏感性高于胸片","需判断原发/继发、是否复发以及张力性气胸（低血压、纵隔移位）"],"workup":["立位胸片（必要时呼气位）+ 床旁超声","胸部 CT（薄层）评估肺大泡位置与对侧肺，决定手术方式","血气分析、连续 SpO₂ 监测","血常规、凝血、心电图（左侧气胸需与心肌缺血鉴别）","肺功能与 DLCO（手术或麻醉评估，尤其 SSP）","疑继发原因：痰培养、结核检查、自身免疫指标；经期气胸行妇科评估"],"grading":"按病因分原发/继发；按量分小量（<2 cm）与大量（≥2 cm）；按病程分急性与慢性（>3 个月不张，陷闭肺）；按次数分初发与复发。张力性气胸为独立危急类型。"},"ddx":[{"name":"脓胸（cts_empyema）","point":"与本类 cts_empyema 鉴别：气胸叩诊鼓音、超声无液体；脓胸为积液、叩诊浊音、伴发热与炎性指标升高。"},{"name":"纵隔肿瘤（cts_mediastinum）","point":"与本类 cts_mediastinum 鉴别：纵隔肿瘤缓慢压迫症状、CT 见纵隔肿块，无胸膜线外透亮区。"},{"name":"急性冠脉综合征","point":"心电图 ST-T 改变与肌钙蛋白升高，呼吸音对称；左侧气胸可模拟心绞痛，需胸片 + 心电图。"},{"name":"肺栓塞","point":"呼吸困难但呼吸音对称，D-二聚体升高，CTPA 见充盈缺损。"},{"name":"巨大肺大泡","point":"薄壁光滑透亮区、周围有受压肺纹理，CT 可区分，避免误当气胸置管。"}],"tx":{"drug":[{"name":"吗啡","dose":"2–4 mg 静脉缓推，必要时 2–4 h 重复，或遵说明书","note":"胸痛及置管/胸膜固定前镇痛，监测呼吸频率与 SpO₂","renal":"肾功能不全减量","hepatic":"严重肝病减量","interact":"与镇静药合用加重呼吸抑制"},{"name":"利多卡因（局部麻醉）","dose":"1% 利多卡因 10–20 mL 分层浸润，总量 ≤4.5 mg/kg，或遵说明书","note":"经皮胸管置入的主要麻醉方式","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全减量","interact":"与胺碘酮合用增加心脏抑制"},{"name":"布比卡因（肋间阻滞）","dose":"0.25% 布比卡因第 5–7 肋间每处 3–5 mL，或遵说明书","note":"置管后镇痛，减少阿片用量","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全减量","interact":"与延长 QT 药物合用增加心脏毒性"},{"name":"头孢唑林","dose":"1–2 g 静脉滴注（术前 0.5–1 h 单剂），或遵说明书","note":"仅用于胸膜固定/肺大泡切除等手术预防","renal":"CrCl <35 延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度"},{"name":"头孢呋辛 + 甲硝唑（合并胸腔感染时）","dose":"头孢呋辛 1.5 g 静滴 q8h；甲硝唑 500 mg 静滴 q8h，或遵说明书","note":"仅用于引流液培养阳性、发热或引流液混浊者，按药敏调整","renal":"头孢呋辛 CrCl <30 延长间隔；甲硝唑重度肾功能不全减量","hepatic":"甲硝唑重度肝功能不全减量","interact":"甲硝唑与酒精、华法林相互作用"}],"nonDrug":["小量 PSP 且稳定：观察 + 吸氧，24–48 h 复查胸片","大量 PSP 或有症状：针吸抽气（抽至复张或 2.5–4 L）或 8–14 Fr 小口径胸管；抽气后仍大量漏气则置管","SSP：直接置胸管（8–14 Fr 或 20–28 Fr）+ 低负压（−10 至 −20 cmH₂O），不推荐单纯观察","张力性气胸：立即针刺/指切减压（第 4–5 肋间腋中线），随即置管","肺已复张但持续漏气：胸腔内自体血 1–2 mL/kg 促进粘连（按中心规程）","复发高危（同侧复发、对侧气胸、飞行员/潜水员）行 VATS 肺大泡切除 + 胸膜摩擦 + 滑石粉胸膜固定，复发率降至 3%–5%","慢性陷闭肺需 VATS 剥脱，必要时支气管活瓣置入（专科评估）","拔管标准：无漏气 ≥24 h、胸片肺完全复张"],"life":["戒烟是降低复发最有效的措施","完全复张前禁乘飞机（2 周内），已行胸膜固定者终身禁潜水","首次 PSP 复发率 20%–30%，1 周与 1 个月复查胸片","4–6 周内避免剧烈咳嗽、负重与对抗运动","SSP 需同步治疗基础肺病并肺康复"]},"prog":"PSP 多 3–7 d 肺复张，住院病死率 <1%，同侧复发率 20%–30%，二次复发后 >50%；SSP 病死率 10%–20%。VATS 胸膜固定后复发率 3%–5%。","refs":["《自发性气胸诊断与治疗中国专家共识（2023 年版）》","《英国胸科协会（BTS）自发性气胸管理指南》（2023）"]},{"id":"cts_empyema","name":"脓胸","aka":["脓胸","Empyema","胸膜腔感染","化脓性胸膜炎"],"rank":2,"basic":{"define":"病原微生物侵入胸膜腔致积脓或脓性胸腔积液，常由肺炎旁积液进展而来，也可继发于创伤、术后、食管破裂或膈下感染；分急性（渗出期、纤维脓性期）与慢性（机化期）。","risk":["肺炎、肺脓肿、支气管扩张合并感染","食管穿孔、吻合口瘘、开放性胸伤（需氧+厌氧混合感染）","胸腔穿刺/胸管等医源性污染","糖尿病、免疫抑制、酗酒、吸入性肺炎、长期机械通气","结核性或恶性胸腔积液继发感染"],"epi":"社区获得性肺炎中 5%–10% 出现肺炎旁积液，其中约 5%–10% 进展为脓胸；我国以肺炎后续发为主，未充分引流者病死率 15%–20%。"},"patho":"分三期：①渗出期，毛细血管通透性增加形成清亮渗出液；②纤维脓性期，积液变脓性、纤维蛋白形成分隔，肺表面纤维膜限制扩张；③机化期，纤维母细胞增生形成纤维板，肺被包裹固定。积液 pH 下降与葡萄糖消耗加速细菌生长，吸入与食管来源者厌氧菌常见。","dx":{"criteria":["发热、胸痛、咳脓痰、呼吸困难；慢性期消瘦、贫血、杵状指","胸腔积液呈脓性，或革兰染色/培养阳性","或 Rivalta 试验阳性伴任一（Light 标准）：pH <7.20、葡萄糖 <2.2 mmol/L、LDH >1000 U/L","超声见分隔与内部回声、胸膜增厚；增强 CT 见胸膜环形强化（split pleura sign）、多房积液或含气","厌氧培养与血培养不可省略，评估食管破裂与膈下脓肿","胸腔镜或手术探查可直接观察并取材"],"workup":["胸部增强 CT + 床旁超声（定位、穿刺引导）","诊断性胸穿：常规、蛋白、LDH、葡萄糖、pH、革兰染色、需氧/厌氧培养、结核、细胞学、ADA","血常规、CRP、PCT、血培养；糖尿病者查 HbA1c","脓液培养药敏（关注 MRSA、产 ESBL 肠杆菌、厌氧菌）","疑食管破裂行碘水造影/胃镜；疑膈下感染行腹部 CT","营养评估（白蛋白、前白蛋白、BMI）"],"grading":"按病程分渗出期、纤维脓性期（多房化）、机化期；按范围分包裹性与弥漫性；按病因分肺炎性、创伤/术后性与结核性。"},"ddx":[{"name":"自发性气胸（cts_pneumothorax）","point":"与本类 cts_pneumothorax 鉴别：脓胸为积液伴发热、叩诊浊音、超声见液体分隔；气胸为积气、叩诊鼓音、突发胸痛无发热。"},{"name":"纵隔肿瘤（cts_mediastinum）","point":"与本类 cts_mediastinum 鉴别：纵隔肿块位于纵隔内、边界清楚，无胸膜腔感染征象。"},{"name":"结核性胸腔积液","point":"草黄色、淋巴细胞为主，ADA >40 U/L，起病较缓、低热盗汗。"},{"name":"恶性胸腔积液","point":"量大增长快，细胞学/胸膜活检阳性，CT 见胸膜结节，无脓性表现。"},{"name":"肺脓肿","point":"空洞性肺病灶伴液平、咳大量脓臭痰；需 CT 区分肺内与胸膜腔来源。"}],"tx":{"drug":[{"name":"头孢曲松","dose":"2 g 静脉滴注 qd 或 q12h，或遵说明书","note":"社区获得性脓胸经验一线；按培养降阶梯，疗程常 3–6 周","renal":"CrCl <30 按说明书减量","hepatic":"重度肝功能不全慎用","interact":"禁与含钙溶液同管输注"},{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静脉滴注 q6–8h（延长输注 4 h），或遵说明书","note":"覆盖革兰阴性菌与厌氧菌，用于医院获得性、术后或吸入来源脓胸","renal":"CrCl 20–40：4.5 g q8h","hepatic":"遵说明书","interact":"与万古霉素合用增加肾损伤"},{"name":"甲硝唑","dose":"500 mg 静脉滴注 q8h，或遵说明书","note":"厌氧菌（食管来源、吸入性）联合用药","renal":"重度肾功能不全减量","hepatic":"重度肝功能不全减量","interact":"与酒精、华法林相互作用"},{"name":"万古霉素","dose":"15–20 mg/kg 静滴 q8–12h，谷浓度 15–20 mg/L，或遵说明书","note":"疑 MRSA 的医院获得性脓胸","renal":"按 CrCl 调整并监测浓度","hepatic":"遵说明书","interact":"与哌拉西林他唑巴坦合用增加肾毒性"},{"name":"阿替普酶（胸腔内注射）","dose":"10 mg 溶于 30–50 mL 生理盐水经胸管注入，夹管 1 h，连续 3 d，遵说明书","note":"多房/包裹性脓胸促进引流（可联合 DNase）","renal":"遵说明书","hepatic":"凝血障碍者慎用","interact":"全身抗凝/抗血小板增加出血"},{"name":"肠内营养制剂","dose":"25–30 kcal/kg/d，蛋白 1.2–1.5 g/kg/d，或遵说明书","note":"纠正低蛋白血症，促进愈合与引流","renal":"肾功能不全用肾病配方","hepatic":"肝功能不全用支链氨基酸配方","interact":""}],"nonDrug":["胸腔穿刺抽液仅用于渗出期少量积液，不作主流治疗","胸腔闭式引流为纤维脓性期首选：24–28 Fr 或 10–14 Fr 胸管 + 低负压（−10 至 −20 cmH₂O），生理盐水冲洗保持通畅","胸腔内纤溶（IPFT）：包裹性、多房或外科高危者，阿替普酶 + DNase 优于单药（MIST2）","VATS 脓胸清除/剥脱：引流 3–7 d 无效或多房者，为纤维脓性期主要手段","胸膜纤维板剥脱：慢性机化期、肺不能复张、胸廓塌陷或支气管胸膜瘘","处理病因：食管破裂修补 + 引流与营养，膈下脓肿同期引流","营养支持、控糖、氧疗；长期不愈者开窗引流（Eloesser 皮瓣）","拔管标准：引流 <50 mL/d、无分隔漏气、影像示肺复张"],"life":["每日记录引流量、体温与 CRP，复查超声/CT 评估腔隙","完成足疗程抗生素（3–6 周），不擅自停药","出院 2 周、1 个月复查胸片，评估残余脓腔与胸膜增厚","呼吸训练与渐进活动，预防限制性通气障碍","糖尿病、免疫抑制者长期随访"]},"prog":"及时引流 + 敏感抗生素治愈率 80%–90%；VATS 剥脱后多 2–4 周拔管。慢性脓胸可致胸廓塌陷与全身消耗，病死率 15%–20%。","refs":["《胸膜腔感染诊治中国专家共识》（中华医学会呼吸病学分会，2021）","《美国胸科学会（ATS）肺炎旁积液与脓胸管理指南》（2023 更新）"]},{"id":"cts_mediastinum","name":"纵隔肿瘤","aka":["纵隔肿瘤","Mediastinal Tumor","纵隔肿块","胸腺瘤","畸胎瘤","神经源性肿瘤"],"rank":3,"basic":{"define":"纵隔内除心脏、大血管、食管、气管等正常结构外的肿瘤性病变。按分区分为前纵隔（胸骨后至心包前）、中纵隔（气管与心包旁）与后纵隔（气管分叉后至脊柱旁），各区有典型疾病谱（4T：胸腺瘤、畸胎瘤、甲状腺肿、Terrible 淋巴瘤）。","risk":["20–40 岁（生殖细胞肿瘤、淋巴瘤）；成人以胸腺瘤、神经源性肿瘤为主","胸腺瘤相关自身免疫病：重症肌无力、纯红再障、低丙种球蛋白血症","既往纵隔放疗、EB 病毒（霍奇金淋巴瘤）","神经纤维瘤病 1 型"],"epi":"纵隔肿块常规胸片检出率约 1/1000–1/3400；后纵隔肿瘤约 75% 为神经源性；胸腺瘤合并重症肌无力 30%–50%。"},"patho":"前纵隔含残留胸腺与胚胎期迁移的生殖细胞，故胸腺瘤、胸腺癌、畸胎瘤与淋巴瘤多见；中纵隔为淋巴与气道周边结构，多见淋巴瘤与支气管/心包囊肿；后纵隔为神经嵴来源，多见神经鞘瘤、神经纤维瘤与节细胞神经瘤。增大后压迫气道、食管、上腔静脉与喉返神经；胸腺瘤经 AChR 抗体介导的神经肌肉接头障碍引起易疲劳性肌无力。","dx":{"criteria":["常无症状（体检发现）；压迫症状：胸骨后闷痛、咳嗽、气促、吞咽困难、声嘶、上腔静脉综合征","重症肌无力：眼睑下垂、复视、近端肌无力、咀嚼吞咽困难，晨轻暮重；AChR 抗体全身型阳性率 80%–90%，可用重复神经电刺激或单纤维肌电图证实","胸部增强 CT 确定分区、大小、边界、钙化、脂肪成分与血管关系；椎旁肿瘤加 MRI","前纵隔实性肿块伴 AFP 或 β-hCG 升高提示非精原细胞性生殖细胞肿瘤；年轻者伴 B 症状与 LDH 升高考虑淋巴瘤","胸腺瘤一般避免术前穿刺（种植风险），分型依赖手术病理","后纵隔肿瘤伴阵发高血压者查血浆游离甲氧基肾上腺素","胸骨后甲状腺肿查甲功与颈部超声"],"workup":["胸部增强 CT + 腹部超声/CT；前纵隔与椎旁肿瘤加 MRI","PET-CT 用于淋巴瘤分期与恶性胸腺瘤/生殖细胞肿瘤鉴别","AFP、β-hCG、LDH、CEA、NSE；甲状腺功能；肌无力抗体谱与肌电图","CT/超声引导穿刺：淋巴瘤、生殖细胞肿瘤；淋巴瘤可经 EBUS-TBNA 或纵隔镜取材","肺功能、心功能与呼吸肌力（FVC）评估","血常规、肝肾功能、凝血；必要时骨髓检查"],"grading":"按分区：前、中、后纵隔。胸腺瘤 WHO 2015 分 A、AB、B1、B2、B3 与胸腺癌；Masaoka-Koga 分期：Ⅰ 包膜完整、Ⅱ 侵及包膜/胸膜或肺、Ⅲ 侵及邻近器官、Ⅳa 胸膜/心包种植、Ⅳb 淋巴或血行转移。"},"ddx":[{"name":"自发性气胸（cts_pneumothorax）","point":"与本类 cts_pneumothorax 鉴别：纵隔肿瘤起病缓慢、以压迫症状为主，CT 见纵隔肿块；气胸为突发胸痛与呼吸音消失。"},{"name":"脓胸（cts_empyema）","point":"与本类 cts_empyema 鉴别：纵隔肿瘤无发热与 CRP 升高，影像为纵隔实性/囊性肿块；脓胸为胸膜腔积脓。"},{"name":"淋巴瘤","point":"前/中纵隔多发融合淋巴结、B 症状与 LDH 升高，PET 高摄取，需活检分型，以化疗为主不首选切除。"},{"name":"胸骨后甲状腺肿","point":"与颈部甲状腺相连、随吞咽活动，CT 呈高密度含碘组织，常伴甲亢或压迫症状。"},{"name":"支气管囊肿/心包囊肿","point":"中纵隔薄壁囊性病灶、水样密度无强化，常无症状。"},{"name":"纵隔淋巴结结核","point":"年轻患者伴低热盗汗，CT 见环形强化淋巴结与钙化，T-SPOT 阳性。"},{"name":"肺癌伴纵隔淋巴结转移","point":"有肺内原发灶，淋巴结符合 N2/N3 分布，EBUS 可证实。"}],"tx":{"drug":[{"name":"溴吡斯的明","dose":"60 mg 口服 q3–4h（按需），术前维持至术日清晨；剂量个体化，遵说明书","note":"重症肌无力症状控制；过量致胆碱能危象","renal":"肾功能不全减量并延长间隔","hepatic":"遵说明书","interact":"与氨基糖苷类、镁剂合用加重神经肌肉阻滞"},{"name":"泼尼松","dose":"0.5–1 mg/kg/d 口服，按症状滴定，术前维持，或遵说明书","note":"肌无力免疫抑制；术前需稳定数周","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"人免疫球蛋白（IVIG）","dose":"0.4 g/kg/d 静脉输注，连续 5 d，或遵说明书","note":"肌无力危象或术前快速改善","renal":"肾功能不全慎用并减慢输注","hepatic":"遵说明书","interact":"与肾毒性药物合用增加肾损伤"},{"name":"头孢呋辛（围手术期）","dose":"1.5 g 静脉滴注（术前 0.5–1 h），或遵说明书","note":"胸腺切除/纵隔肿瘤切除预防用药","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"奥美拉唑","dose":"20–40 mg 口服/静滴 qd，或遵说明书","note":"应激性溃疡预防；吞咽困难者兼顾吸入防护","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"降低氯吡格雷活性"},{"name":"利妥昔单抗","dose":"375 mg/m² 静脉滴注 q1w 共 4 次，或遵说明书","note":"用于纵隔 B 细胞淋巴瘤或难治性肌无力；监测输注反应与乙肝再激活","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"与其他免疫抑制剂合用增加感染"}],"nonDrug":["Ⅰ–Ⅱ 期胸腺瘤完整切除（正中切口或 VATS/机器人）；合并肌无力者行扩大胸腺切除 + 前纵隔脂肪清扫","Ⅲ 期以上扩大切除 + 血管重建，术后放疗；不可切除者诱导化疗 + 放疗","肌无力术前稳定 2–4 周，术后 24–72 h 监护 FVC 与吞咽，警惕肌无力危象","生殖细胞肿瘤：成熟畸胎瘤切除；非精原细胞肿瘤化疗后切除残余病灶","淋巴瘤以化疗 ± 放疗为主；巨块型警惕气道与上腔静脉受压","支气管/心包囊肿有症状或增大者 VATS 切除","后纵隔神经源性肿瘤完整切除，椎管侵犯者联合神经外科；嗜铬细胞瘤术前 α 阻滞 10–14 d","术前 MDT 评估可切除性与辅助治疗"],"life":["术后 1–3 个月避免剧烈胸廓运动；肌无力改善需数月，长期随访","胸腺瘤前 5 年每 6 个月胸部 CT，之后每年，警惕胸膜种植","避免可加重肌无力的药物（氨基糖苷类、氟喹诺酮、镁剂、β 阻滞剂）","淋巴瘤与生殖细胞肿瘤按方案完成治疗并规律复查","戒烟与营养支持，气促或声嘶加重复诊"]},"prog":"胸腺瘤完整切除后 5 年生存率：Ⅰ–Ⅱ 期 85%–95%、Ⅲ 期 60%–70%、Ⅳ 期 30%–50%；后纵隔神经鞘瘤多为良性，切除后复发率 <5%。","refs":["《中国胸腺上皮肿瘤诊疗指南（2023 年版）》","《中国重症肌无力诊断和治疗指南（2020 版）》","《纵隔肿瘤外科治疗中国专家共识》（2017）"]}]},{"id":"postop","name":"胸外科术后管理","rank":4,"summary":"围绕「管、肺、营养」三条主线：胸管按漏气分级决定拔管与干预（>5 d 为延长漏气，可胸膜固定）；肺叶切除后以 ARISCAT 分层、落实肺保护性通气与早期活动；乳糜胸以引流 + MCT 饮食为基础，大量漏或营养不能维持时尽早结扎胸导管。","compare":[{"diseaseId":"cts_airleak","dx":"胸管水封瓶持续出气泡而肺已复张；按气泡时机分吸气相、呼气相、双相、咳嗽时","key":"少量可观察，>5 d 为延长漏气；首选自体血或滑石粉胸膜固定，无效行 VATS 修补"},{"diseaseId":"cts_postop_pulm","dx":"术后发热、咳痰、气促、SpO₂ 下降，胸片见肺不张或浸润影；术前 ARISCAT ≥45 分为高危","key":"预防靠肺保护性通气（VT 6–8 mL/kg 预测体重、PEEP 5–8）+ 镇痛 + 早期活动"},{"diseaseId":"cts_chylothorax","dx":"术后引流突增（常 >500 mL/d），引流液乳白色，胸水甘油三酯 >1.24 mmol/L","key":"禁食 + TPN 或 MCT 饮食；引流 >1000–1500 mL/d 持续或营养不能维持时及早结扎"}],"diseases":[{"id":"cts_airleak","name":"胸管管理与持续肺漏气","aka":["持续漏气","Prolonged Air Leak","PAL","胸管管理","肺泡漏气"],"rank":1,"basic":{"define":"术后胸膜腔与肺泡/气道间存在持续气体交通，表现为胸管水封瓶持续出气泡；术后 >5 d 仍逸气称延长漏气（PAL）。按量分少量（单相偶见气泡）与大量（双相连续气泡、依赖负压）。","risk":["肺大泡切除/肺减容术、气胸手术、严重 COPD","肺纤维化、高龄、长期吸烟（肺组织脆）","肺叶/肺段切除创面大、肺尖粘连分离","术后高 PEEP、剧烈咳嗽"],"epi":"肺叶切除后 PAL 约 5%–15%，肺减容与肺大泡切除后 20%–50%，气胸手术后 10%–20%；是住院时间延长最常见的单一原因。"},"patho":"肺泡与小气道破口未闭合，气体经脏层胸膜缺损逸入胸膜腔。残余胸腔空间与漏气互为因果：肺不能贴壁则漏气难止，漏气则无法形成粘连，从而延长引流并增加脓胸与肺不张风险。","dx":{"criteria":["水封瓶（或数字化引流系统）持续有气泡逸出，持续 >5 d 即延长漏气","按气泡时机分：咳嗽时（微量）、吸气相（少量）、呼气相（中量）、双相持续（大量）","数字化胸管可量化漏气流量（>100–200 mL/min 为显著）","排除支气管胸膜瘘：气泡随咳嗽大量喷出、负压仍不能复张、气液平面波动","排除技术性漏气（侧孔外露、接头松动、水封瓶位置）","肺完全复张且微量漏气者可行夹管观察后拔管"],"workup":["每日记录漏气量、气泡时机与胸管位置","床旁胸片或透视评估肺复张与残余空腔，必要时 CT","数字化胸管监测漏气流量","引流液性状、体温、WBC、CRP 评估合并脓胸","肺功能评估残余肺储备","疑支气管胸膜瘘者行支气管镜"],"grading":"按时间：≤5 d 常规，>5 d 延长漏气（PAL），>7–14 d 难治性；按量：微量/少量/中量/大量。按性质分肺泡漏气与支气管胸膜瘘。"},"ddx":[{"name":"乳糜胸（cts_chylothorax）","point":"与本类 cts_chylothorax 鉴别：乳糜胸为引流液乳白与甘油三酯升高，不表现为水封瓶气泡；二者可并存。"},{"name":"肺叶切除术后肺部并发症（cts_postop_pulm）","point":"与本类 cts_postop_pulm 鉴别：术后肺并发症以发热、咳痰、浸润影为主；肺复张良好而单纯持续漏气者以其本身为核心问题。"},{"name":"支气管胸膜瘘","point":"气泡随咳嗽喷出，患肺不能复张，伴气液平面与反复感染，需手术或活瓣封堵。"},{"name":"胸管侧孔外露或管路漏气","point":"可见皮肤外气泡与气流声，调整固定即可，非肺实质漏气。"},{"name":"食管吻合口瘘","point":"引流液浑浊混有唾液、淀粉酶升高，伴发热与纵隔气肿。"}],"tx":{"drug":[{"name":"头孢呋辛","dose":"1.5 g 静脉滴注 q8h，或遵说明书","note":"仅引流液混浊、发热或 WBC 升高时抗感染；漏气本身不常规用药","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"吗啡","dose":"2–4 mg 静脉缓推，必要时重复；或 PCA 0.5–1 mg/h，遵说明书","note":"充分镇痛保证深呼吸与咳嗽，是减少漏气的基础","renal":"肾功能不全减量","hepatic":"严重肝病减量","interact":"与镇静药合用加重呼吸抑制"},{"name":"布比卡因（椎旁/胸管注入）","dose":"0.25% 布比卡因 20 mL 胸段椎旁阻滞或经胸管注入，遵说明书","note":"减轻胸管刺激与咳嗽痛，利于肺复张","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全减量","interact":"与延长 QT 药物合用增加心脏毒性"},{"name":"氨溴索","dose":"30 mg 静脉推注 q8h，或遵说明书","note":"促排痰，配合呼吸训练预防肺不张","renal":"重度肾功能不全延长间隔","hepatic":"遵说明书","interact":"与镇咳药合用减弱祛痰效果"},{"name":"沙丁胺醇（雾化）","dose":"2.5–5 mg 雾化 q6h，或遵说明书","note":"COPD 或气道痉挛者改善通气与排痰","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗，注意低钾"}],"nonDrug":["微量漏气且肺已复张：夹管 4–6 h 后复查胸片无气胸即拔管","中大量漏气：维持水封或低负压（−10 至 −20 cmH₂O），避免过度负压","胸膜固定：滑石粉 4–5 g 或自体血 50–100 mL 经胸管注入后夹管 1–2 h（按中心规程）","反复无效、合并感染或肺不复张者 VATS 修补 + 胸膜摩擦","保持管路通畅，挤捏/冲洗防血块堵塞","早期活动、镇痛与激肺训练减少漏气持续","拔管标准：肺复张、漏气停止 >24 h、引流 <200 mL/d，拔管后即刻与 24 h 复查胸片"],"life":["出院前确认无漏气、肺复张","2 周内避免剧烈咳嗽、屏气与提重物 >5 kg","突发胸痛、气促或气泡增多立即复诊","戒烟与肺康复，1 个月复查胸片"]},"prog":"多数漏气 3–5 d 自行闭合；延长漏气 5%–15%，经胸膜固定或再次手术多可解决，但住院日延长；合并脓胸或支气管胸膜瘘者预后差。","refs":["《肺切除术后持续肺漏气管理中国专家共识》（2019）","《欧洲胸外科医师协会（ESTS）持续漏气管理共识》（2015）"]},{"id":"cts_postop_pulm","name":"肺叶切除术后肺部并发症","aka":["术后肺部并发症","Postoperative Pulmonary Complications","PPC","术后肺不张","术后肺炎","ARISCAT"],"rank":2,"basic":{"define":"肺叶切除（或肺段/全肺切除）术后 30 d 内新发、影响临床过程的下呼吸道或肺部事件，包括肺不张、肺炎、呼吸衰竭、ARDS、支气管痉挛与肺栓塞。","risk":["术前 ARISCAT ≥45 分（年龄 >70 岁、术前 SpO₂ <96%、呼吸道感染、麻醉 >2 h、胸部/急诊手术、贫血）","COPD、吸烟、FEV₁ <60%、DLCO 降低","全肺切除或扩大切除、术后疼痛致浅快呼吸","长时间单肺通气、液体过负荷、输血","肥胖、OSA、糖尿病、营养不良"],"epi":"发生率 15%–40%，肺叶切除后肺炎 5%–10%，机械通气 >48 h 约 2%–5%；肺并发症占术后 30 d 死亡的 30%–50%。"},"patho":"手术创伤、单肺通气与全麻致肺泡萎陷与低肺容积，纤毛清除受损；疼痛性咳嗽无力使分泌物潴留形成肺不张并继发感染。剩余肺血流超负荷可致肺水肿，单肺通气缺血再灌注促发 ARDS。","dx":{"criteria":["术后发热 >38 ℃、咳痰、气促或 SpO₂ 下降，胸片/CT 见新发肺不张、浸润影或积液","肺不张：叶段性容积缩小、纵隔向患侧移位","肺炎（CDC 标准）：新发浸润影 + ≥2 项（发热、白细胞异常、脓性痰、氧合下降）或培养证据","呼吸衰竭：PaO₂/FiO₂ <300 或需无创/有创通气；ARDS 按柏林标准分级","术前 ARISCAT：<26 低危、26–44 中危、≥45 高危","排除肺栓塞、心源性肺水肿、支气管胸膜瘘与乳糜胸"],"workup":["胸片与胸部 CT 评估肺不张、积液与残余肺","血气分析、SpO₂；床旁超声评估积液与心功能","血常规、CRP、PCT、痰培养，必要时支气管镜取样","支气管镜清除痰栓，兼具诊断与治疗","术前肺功能、6 分钟步行试验；术后 D-二聚体与 CTPA 排除肺栓塞","BNP 与心脏超声（心衰风险者）"],"grading":"ARISCAT 风险分级（低/中/高）；严重度按 Clavien-Dindo（Ⅱ–Ⅲ 药物/介入，Ⅳ ICU，Ⅴ 死亡）；ARF 按柏林标准轻（200 <P/F ≤300）、中（100 <P/F ≤200）、重（P/F ≤100）度。"},"ddx":[{"name":"胸管管理与持续肺漏气（cts_airleak）","point":"与本类 cts_airleak 鉴别：持续漏气以水封瓶气泡为标志，肺不张以分泌物潴留与浸润影为主；肺不复张伴大量漏气需排除支气管胸膜瘘。"},{"name":"乳糜胸（cts_chylothorax）","point":"与本类 cts_chylothorax 鉴别：乳糜胸为引流突增与乳白液体、甘油三酯升高；术后积液为渗出液，甘油三酯不高。"},{"name":"肺栓塞","point":"突发气促、胸痛，D-二聚体升高，CTPA 见充盈缺损。"},{"name":"心源性肺水肿","point":"BNP 升高、超声左室功能下降，胸片蝶翼样分布。"},{"name":"支气管胸膜瘘","point":"大量持续漏气、患肺不复张、气液平面波动。"}],"tx":{"drug":[{"name":"头孢呋辛","dose":"1.5 g 静脉滴注 q8h，疗程 7–8 d，或遵说明书","note":"术后肺炎经验治疗，获病原后降阶梯","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静脉滴注 q6–8h（延长输注 4 h），或遵说明书","note":"耐药高危或机械通气患者经验治疗，疗程 7–14 d","renal":"CrCl 20–40：4.5 g q8h","hepatic":"遵说明书","interact":"与万古霉素合用增加肾损伤"},{"name":"氨溴索","dose":"30 mg 静脉推注 q8h，或遵说明书","note":"祛痰并促进表面活性物质合成，配合气道廓清","renal":"重度肾功能不全延长间隔","hepatic":"遵说明书","interact":"与镇咳药合用减弱祛痰效果"},{"name":"沙丁胺醇/异丙托溴铵雾化","dose":"沙丁胺醇 2.5 mg + 异丙托溴铵 0.5 mg 雾化 q6h，或遵说明书","note":"解除气道痉挛，注意心动过速与低钾","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗"},{"name":"布地奈德雾化","dose":"1 mg 雾化 bid，或遵说明书","note":"COPD 或气道高反应者，注意口腔念珠菌","renal":"遵说明书","hepatic":"遵说明书","interact":"与 CYP3A4 强抑制剂合用增加全身吸收"},{"name":"对乙酰氨基酚","dose":"500–1000 mg 口服/静脉 q6h，每日 ≤2 g，或遵说明书","note":"多模式镇痛基础用药，减少阿片用量","renal":"CrCl <30 延长间隔","hepatic":"严重肝病禁用或减量","interact":"影响 INR；饮酒增加肝毒性"},{"name":"依诺肝素","dose":"40 mg 皮下注射 qd（CrCl <30 用 20 mg qd），术后 12–24 h 开始，或遵说明书","note":"VTE 预防；与硬膜外导管拔除间隔 ≥4 h","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["术前戒烟 ≥4–8 周、呼吸训练器教学与营养纠正，ARISCAT 高危者术后强化","术中肺保护性通气：VT 6–8 mL/kg 预测体重、PEEP 5–8 cmH₂O、平台压 <30 cmH₂O，单肺通气期肺复张与目标导向液体","镇痛：硬膜外/椎旁阻滞 + 多模式镇痛，保证深呼吸与有效咳嗽","早期活动、半卧位、体位引流与胸部物理治疗","气道廓清：激肺训练器每小时 10 次、辅助咳嗽、雾化湿化，必要时无创通气","支气管镜吸痰/灌洗：痰栓所致肺不张保守无效时","氧疗 SpO₂ 90%–95%；ARDS 用小潮气量 + PEEP 滴定 + 俯卧位","限制性液体管理（术后 24–48 h）、利尿、纠正低蛋白血症","拔管前评估咳嗽力与分泌物，减少再插管"],"life":["出院后呼吸训练 ≥4–6 周（缩唇呼吸、激肺训练器），逐步增加步行","戒烟，接种流感与肺炎球菌疫苗","2 周、1 个月复查胸片与肺功能","蛋白 1.2–1.5 g/kg/d；OSA 者继续 CPAP","按医嘱镇痛，避免因疼痛浅呼吸再发肺不张"]},"prog":"多数肺不张 3–5 d 缓解；术后肺炎病死率 5%–10%；需机械通气的严重呼吸衰竭病死率 20%–40%。肺保护性通气与 ERAS 可明显降低发生率。","refs":["《加速康复外科胸外科中国专家共识》（2020）","《术后肺部并发症防治中国专家共识》（2021）","《欧洲麻醉学会（ESA）围手术期肺保护性通气指南》（2019）"]},{"id":"cts_chylothorax","name":"乳糜胸","aka":["乳糜胸","Chylothorax","胸导管损伤","乳糜性胸腔积液"],"rank":3,"basic":{"define":"胸膜腔内乳糜液积聚，多因胸导管或其分支损伤/阻塞所致。按病因分创伤性（胸外科术后最常见，尤其食管癌切除）、非创伤性（肿瘤、淋巴管肌瘤病、结核、丝虫病）与特发性。","risk":["食管癌切除 + 胸导管旁淋巴结清扫（右胸入路）","肺癌纵隔淋巴结清扫、胸膜剥脱术、交感神经链切除","纵隔肿瘤/淋巴瘤压迫侵犯胸导管","淋巴管肌瘤病、肝硬化、心衰、丝虫病","中心静脉置管误伤或血栓"],"epi":"食管癌术后 1.5%–4%，肺切除术后 0.5%–1%，心脏/右上纵隔手术约 0.5%–1%；处理不当致低蛋白、免疫抑制与电解质紊乱，食管癌术后乳糜胸病死率可达 10%–20%。"},"patho":"胸导管经主动脉裂孔上行，胸上段位于食管后方、脊柱前方，汇入左静脉角。损伤后富含脂肪、淋巴细胞与蛋白质的乳糜漏入胸膜腔；持续引流丢失水分、蛋白、电解质与淋巴细胞，致低蛋白血症、淋巴细胞减少、免疫缺陷与营养不良。","dx":{"criteria":["术后引流量突增（常 >500 mL/d）或持续不减，引流液转乳白色/浑浊，进食后更明显","胸水甘油三酯 >1.24 mmol/L 确诊，<0.56 mmol/L 基本排除；胆固醇/甘油三酯比值 <1","乳糜试验阳性，胸水淋巴细胞比例常 >80%","假性乳糜胸：慢性积液乳白但甘油三酯不高、胆固醇结晶阳性","排除侧孔外露、血性或脓性引流","伴发热与引流液混浊时考虑继发感染"],"workup":["每日引流量与性状，高脂试验餐后观察变化","胸水甘油三酯、胆固醇、蛋白、LDH、淋巴细胞比例、乳糜试验、细胞学与培养","血常规（淋巴细胞计数）、白蛋白、前白蛋白、电解质","胸部增强 CT；核素淋巴显像或淋巴管造影定位漏口","评估营养不良与免疫功能"],"grading":"按引流量分少量 <500 mL/d、中量 500–1000 mL/d、大量 >1000 mL/d；按病因分创伤/医源性、肿瘤性与特发性，用于指导保守 vs 手术。"},"ddx":[{"name":"胸管管理与持续肺漏气（cts_airleak）","point":"与本类 cts_airleak 鉴别：持续漏气为水封瓶气泡而非引流突增与乳白液体；乳糜胸无持续气泡而甘油三酯升高。"},{"name":"肺叶切除术后肺部并发症（cts_postop_pulm）","point":"与本类 cts_postop_pulm 鉴别：术后肺并发症为渗出性积液伴发热咳痰；乳糜胸引流液乳白、甘油三酯高、常无发热。"},{"name":"假性乳糜胸","point":"慢性积液（结核、类风湿）乳白但甘油三酯正常、胆固醇结晶阳性。"},{"name":"脓胸","point":"引流液脓性有臭味、发热与 CRP 升高，培养阳性。"},{"name":"术后血胸","point":"引流为新鲜血伴 Hb 下降与血压波动；乳糜胸 Hb 稳定。"},{"name":"心力衰竭性胸腔积液","point":"双侧漏出液伴心衰体征与 BNP 升高。"}],"tx":{"drug":[{"name":"中链甘油三酯（MCT）肠内营养制剂","dose":"25–30 kcal/kg/d，经口或鼻空肠管以 20–30 mL/h 起始，或遵说明书","note":"MCT 经门静脉吸收不经胸导管，可减少乳糜流量","renal":"肾功能不全用肾病配方","hepatic":"肝功能不全用支链氨基酸配方","interact":""},{"name":"全肠外营养（TPN）","dose":"25–30 kcal/kg/d，氨基酸 1.2–1.5 g/kg/d，低脂配方，或遵说明书","note":"禁食或引流 >1000 mL/d 时首选；监测血糖、电解质、肝酶与导管感染","renal":"调整氨基酸与电解质","hepatic":"减少脂肪乳并监测胆汁淤积","interact":"与华法林等合用影响药效"},{"name":"奥曲肽","dose":"50–100 μg 皮下注射 q8h（或 25–50 μg/h 泵入），或遵说明书","note":"减少肠道淋巴分泌，作保守辅助，证据有限","renal":"肾功能不全减量","hepatic":"肝硬化减量并监测血糖","interact":"影响血糖"},{"name":"人血白蛋白","dose":"20% 白蛋白 50–100 mL 静滴，按白蛋白水平，或遵说明书","note":"大量漏液致低蛋白/低血容量时使用，目标 ≥30 g/L","renal":"遵说明书","hepatic":"肝硬化慎用（容量负荷）","interact":"与血制品间隔输注"},{"name":"氯化钾（静脉补充）","dose":"10% 氯化钾 10–15 mL 加入 500 mL 液体（≤0.3%）静滴，或遵说明书","note":"乳糜液丢失致低钾，按引流量与血钾补充","renal":"肾功能不全者监测血钾与心电图","hepatic":"遵说明书","interact":"与保钾利尿剂合用增加高钾"},{"name":"头孢呋辛（合并感染时）","dose":"1.5 g 静脉滴注 q8h，或遵说明书","note":"淋巴液丢失致免疫低下，引流混浊/发热时按脓胸处理","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"}],"nonDrug":["禁食 + TPN 或仅 MCT 饮食（低脂、高蛋白、高热量），减少胸导管流量","保留胸腔闭式引流（必要时低负压），防止积液压迫与继发感染","手术指征：保守 5–7 d 引流量仍 >1000–1500 mL/d，或 >500 mL/d 持续 1–2 周、营养不能维持或严重免疫抑制","胸导管结扎：右胸第 8–9 肋间，于奇静脉与主动脉间低位结扎；术前高脂饮食或淋巴管造影定位","漏口不明时加做胸膜固定；手术禁忌者可行胸腹腔分流","肿瘤所致者治疗原发病；结核性抗结核；淋巴管肌瘤病用 mTOR 抑制剂","拔管标准：引流 <100–200 mL/d 持续 2–3 d、无感染、肺复张"],"life":["出院后 2–4 周维持低脂饮食并逐步过渡","监测体重、白蛋白与淋巴细胞计数，1 个月复查胸片","4–6 周内避免剧烈咳嗽与负重","注意感染防护；肿瘤相关者随访原发病"]},"prog":"保守治疗成功率 60%–80%；结扎后多 1–2 周内引流量明显下降。及时处理病死率 <5%，合并营养不良与感染者可达 10%–20%。","refs":["《食管癌术后乳糜胸诊治中国专家共识》（2018）","《胸外科围手术期并发症防治中国专家共识》（2019）"]}]},{"id":"chest_wall_diaphragm","name":"胸壁与膈肌疾病","rank":5,"summary":"共同特点是「形态或结构改变 + 功能受限」：胸壁肿瘤以 R0 切除与重建为核心；膈疝按滑动型/食管旁型决定手术；贲门失弛缓症以鸟嘴征与高分辨测压确诊，再选 POEM 或 Heller。","compare":[{"diseaseId":"cts_chest_wall_tumor","dx":"胸壁触及肿块，CT 见肋骨破坏或胸壁软组织病灶","key":"首选 R0 整块切除；缺损 >5 cm 或 ≥3 根肋骨需重建"},{"diseaseId":"cts_diaphragmatic_hernia","dx":"CT/钡餐示胃经膈入胸，胃镜见膈上囊袋","key":"食管旁型有症状即修补；滑动型无反流不手术"},{"diseaseId":"cts_achalasia","dx":"吞咽困难，钡餐鸟嘴征，IRP ≥15 mmHg 且蠕动缺失","key":"降低 LES 压力：POEM 或 Heller + 抗反流"},{"diseaseId":"cts_pectus","dx":"前胸壁凹陷或前突，CT 测 Haller 指数","key":"Haller ≥3.25 或心肺受压者行 Nuss 钢板矫形"}],"diseases":[{"id":"cts_chest_wall_tumor","name":"胸壁肿瘤","aka":["Chest Wall Tumor","肋骨肿瘤","胸壁重建","软骨肉瘤"],"rank":1,"basic":{"define":"发生于胸壁软组织、胸骨与肋骨的肿瘤，分原发（约 40%）与继发（转移或邻近侵犯）；恶性者以软骨肉瘤、骨肉瘤与软组织肉瘤为主。","risk":["胸部放疗史（放疗相关肉瘤）","神经纤维瘤病 1 型","乳腺癌、肺癌、肾癌、甲状腺癌病史"],"epi":"约占全身骨与软组织肿瘤的 5%，恶性者中软骨肉瘤最常见（40%–50%）；弹力纤维瘤、骨纤维异常增殖症为常见良性病。"},"patho":"肿瘤局部浸润并经血行转移，肋骨病灶突破骨皮质后侵入胸膜与肺。软骨肉瘤生长慢、对放化疗不敏感，局部控制全靠完整切除。切除 ≥3 根肋骨或 >5 cm 会造成反常呼吸与胸壁塌陷，需重建骨性框架与软组织覆盖。","dx":{"criteria":["胸壁肿块，恶性者常有夜间痛与快速增大，>5 cm 伴骨破坏恶性可能大","增强 CT（骨窗+软组织窗）评估骨破坏与胸膜肺受累，MRI 评估椎管与肌层","穿刺活检（CT/超声引导）确诊并分级，不应先切除","软骨肉瘤见斑点状钙化；肾癌转移灶富血供，活检前评估出血"],"workup":["增强 CT + MRI（必要）","引导下穿刺活检与分级","PET-CT 或全身骨扫描","胸壁重建 MDT"],"grading":"恶性按 AJCC 第 8 版 T1 ≤5 cm、T2 >5 cm、T3 多发，N0/N1，M0/M1；分级 G1–G3。"},"ddx":[{"name":"膈疝与食管裂孔疝（cts_diaphragmatic_hernia）","point":"膈疝为膈上含气胃囊、随体位变化；胸壁肿瘤为固定肿块。"},{"name":"贲门失弛缓症（cts_achalasia）","point":"以吞咽困难与食管扩张为主，无胸壁肿块。"}],"tx":{"drug":[{"name":"头孢呋辛（围手术期）","dose":"1.5 g 静脉滴注，术前 0.5–1 h，或遵说明书","note":"置入网片者需覆盖葡萄球菌","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"多柔比星 + 异环磷酰胺（软组织肉瘤）","dose":"多柔比星 60–75 mg/m² d1，异环磷酰胺 1.5–2.5 g/m²/d d1–3，每 21 d；按 CSCO/NCCN 与体表面积调整","note":"高度恶性深部肉瘤术前/辅助。","renal":"异环磷酰胺肾功能不全减量或禁用","hepatic":"多柔比星按胆红素减量","interact":"与顺铂合用增加肾毒性"},{"name":"甲氨蝶呤 + 多柔比星 + 顺铂（骨肉瘤）","dose":"MAP：甲氨蝶呤 8–12 g/m²、多柔比星 75 mg/m²、顺铂 120 mg/m² 序贯；按 CSCO/NCCN 与体表面积调整","note":"新辅助与辅助；甲氨蝶呤需亚叶酸钙解救","renal":"甲氨蝶呤肾功能不全禁用","hepatic":"多柔比星肝功不全减量","interact":"甲氨蝶呤与 NSAIDs 合用增加毒性"},{"name":"对乙酰氨基酚","dose":"500–1000 mg 口服 q6h，每日 ≤2 g，或遵说明书","note":"术后镇痛基础","renal":"CrCl <30 延长间隔","hepatic":"严重肝病禁用","interact":"影响华法林 INR"},{"name":"依诺肝素","dose":"40 mg 皮下 qd，术后 12–24 h 开始，或遵说明书","note":"活动受限者 VTE 预防","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["良性有症状或增大者局部切除，典型骨纤维异常增殖症可随访","肋骨恶性整块切除受累肋骨及上下各一根正常肋骨。","软骨肉瘤对放化疗不敏感，治疗完全依赖 R0 切除","缺损 >5 cm 或 ≥3 根肋骨用钛网/Marlex 重建。","软组织覆盖用带蒂肌瓣（背阔肌、胸大肌）或游离皮瓣","孤立胸壁转移灶在原发灶可控时切除"],"life":["重建术后 6–8 周避免负重与剧烈胸廓运动","术前戒烟 ≥4 周，降低补片感染","恶性者长期随访，警惕复发与肺转移"]},"prog":"良性完整切除后极少复发；低度恶性软骨肉瘤 5 年生存率 70%–90%，高度恶性肉瘤 30%–50%。","refs":["《中国胸壁肿瘤外科治疗专家共识》（2021）","《CSCO 软组织肉瘤诊疗指南（2023）》","《NCCN 骨与软组织肿瘤指南（2023）》"]},{"id":"cts_diaphragmatic_hernia","name":"膈疝与食管裂孔疝","aka":["Hiatal Hernia","滑动型食管裂孔疝","食管旁疝","Diaphragmatic Hernia"],"rank":2,"basic":{"define":"腹腔脏器经膈肌缺损进入胸腔。食管裂孔疝分四型：Ⅰ型滑动型（约占 85%–90%）、Ⅱ型单纯食管旁型、Ⅲ型混合型、Ⅳ型多脏器疝入。","risk":["高龄、肥胖、多产与慢性腹压增高","长期反流致裂孔松弛","胸腹部创伤"],"epi":"钡餐检出率 10%–50%，随年龄增加；食管旁疝仅占 5%–10%，急性胃扭转病死率可达 30%–50%。"},"patho":"膈食管韧带松弛使胃食管交界上移（Ⅰ型），抗反流屏障失效致反流性食管炎；Ⅱ–Ⅳ型裂孔扩大后胃底疝入形成「倒置胃」，可扭转、缺血、穿孔或大出血。巨大疝压迫肺致通气受限。","dx":{"criteria":["Ⅰ型：烧心、反酸，餐后与平卧加重，部分无症状","Ⅱ–Ⅳ型：餐后饱胀、嗳气、胸痛，巨大疝气促；并发症时呕血黑便或突发剧痛","钡餐见膈上胃囊/气液平面；胃镜倒转见膈上胃袋，>5 cm 为大疝","胸腹增强 CT 确认疝内容物与嵌顿，急性期首选"],"workup":["钡餐 + 胃镜活检","胸腹增强 CT","食管测压与 pH-阻抗","血常规、电解质"],"grading":"Ⅰ 滑动型、Ⅱ 单纯食管旁型、Ⅲ 混合型、Ⅳ 多脏器；按大小分 <3 cm、3–5 cm、>5 cm。"},"ddx":[{"name":"胸壁肿瘤（cts_chest_wall_tumor）","point":"为实性肿块，无膈上胃囊与气液平面。"},{"name":"贲门失弛缓症（cts_achalasia）","point":"固体液体均吞咽困难、食管扩张、LES 松弛障碍；裂孔疝以反流为主。"}],"tx":{"drug":[{"name":"奥美拉唑","dose":"20–40 mg 口服 qd 餐前，4–8 周；重度可 bid，或遵说明书","note":"Ⅰ型控制反流；长期用评估骨质疏松","renal":"无需调整","hepatic":"重度肝病减量","interact":"降低氯吡格雷活性"},{"name":"莫沙必利","dose":"5 mg 口服 tid 餐前，或遵说明书","note":"改善胃排空与反流","renal":"遵说明书","hepatic":"重度肝病减量","interact":"与延长 QT 药物合用增加心律失常"},{"name":"铝碳酸镁","dose":"0.5–1.0 g 口服 tid 嚼服，或遵说明书","note":"中和胃酸与胆汁，短期辅助","renal":"重度肾功能不全慎用","hepatic":"遵说明书","interact":"与氟喹诺酮同服间隔 2 h"},{"name":"头孢呋辛 + 甲硝唑（围手术期）","dose":"头孢呋辛 1.5 g + 甲硝唑 500 mg 静滴，术前 0.5–1 h，或遵说明书","note":"清洁-污染手术，覆盖革兰阴性菌与厌氧。","renal":"头孢呋辛 CrCl <30 延长间隔","hepatic":"甲硝唑重度肝病减量","interact":"甲硝唑禁酒，与华法林相互作用"},{"name":"晶体液（急性嵌顿复苏）","dose":"按休克程度 20–30 mL/kg 起始，遵医嘱","note":"急性胃扭转伴休克先复苏后手术","renal":"肾功能不全限速","hepatic":"遵说明书","interact":""}],"nonDrug":["Ⅰ型：无症状观察；有反流者 PPI。","Ⅱ–Ⅳ型：症状明显或伴出血、梗阻、扭转者修补 + 胃底折叠 。","巨大疝 >5 cm 高龄高危无症状者可观察，避免腹压骤增","急性嵌顿/扭转：胃镜减压、置胃管、复苏后急诊手术","食管动力严重障碍者选部分折叠（Toupet），防吞咽困难","创伤性膈疝确诊后手术修补，合并伤优先"],"life":["睡前 2–3 h 不进食。","控制体重，避免提重物与剧烈咳嗽","术后 4–6 周流质→软食过渡"]},"prog":"Ⅰ型经 PPI 多数可控，抗反流术后 5 年控制率 85%–90%；Ⅱ–Ⅳ型修补后缓解率 >90%。","refs":["《中国胃食管反流病多学科诊疗共识（2022）》","《食管裂孔疝外科治疗中国专家共识》（2021）","《ASGE GERD 与裂孔疝管理指南》（2022）"]},{"id":"cts_achalasia","name":"贲门失弛缓症","aka":["Achalasia","鸟嘴征","POEM","Heller 肌切开"],"rank":3,"basic":{"define":"食管下括约肌（LES）松弛障碍伴食管体蠕动消失的食管动力障碍，食物滞留致进行性吞咽困难与食管扩张，按 Chicago 分类分三型。","risk":["高峰 30–60 岁","病毒感染与自身免疫因素","少数家族聚集，可与 1 型糖尿病并存"],"epi":"全球发病率约（0.3–1.6）/10 万/年，患病率约 10/10 万；我国呈上升趋势，确诊常延迟 2–5 年。"},"patho":"肌间神经丛抑制性（NO 能）神经元变性丢失，LES 不能松弛且张力升高，食管蠕动减弱或消失。食物淤滞致食管扩张乃至巨食管，可继发食管炎、念珠菌感染，食管鳞癌风险明显升高。","dx":{"criteria":["进行性吞咽困难（固→液体）、反流未消化食物、胸骨后痛、体重下降","钡餐：食管扩张、蠕动减弱，食管胃交界对称「鸟嘴样」狭窄（bird-beak sign）。","高分辨测压（金标准）：IRP ≥15 mmHg 且蠕动缺失或痉挛","Chicago v4.0：Ⅰ型无增压、Ⅱ型全食管增压（反应最佳）、Ⅲ型痉挛（DCI >450）。"],"workup":["高分辨食管测压","动态钡餐造影","胃镜 + 活检","定时钡餐排空"],"grading":"Chicago v4.0 Ⅰ/Ⅱ/Ⅲ 型；扩张分无、轻度 <4 cm、中度 4–6 cm、重度 >6 cm（可呈乙状结肠样）。"},"ddx":[{"name":"膈疝与食管裂孔疝（cts_diaphragmatic_hernia）","point":"裂孔疝以反流为主，LES 松弛功能尚可，钡餐见膈上胃囊。"},{"name":"胸壁肿瘤（cts_chest_wall_tumor）","point":"为胸壁肿块与局部疼痛，无吞咽困难。"}],"tx":{"drug":[{"name":"硝酸异山梨酯","dose":"5–10 mg 舌下含服，餐前 15 min，或遵说明书","note":"暂时降 LES 压力。","renal":"遵说明书","hepatic":"重度肝病慎用","interact":"与 PDE5 抑制剂合用致严重低血压，禁用"},{"name":"硝苯地平","dose":"10–20 mg 口服，餐前 30 min，或遵说明书","note":"疗效有限，用于不能耐受手术者","renal":"无需调整","hepatic":"重度肝病减量","interact":"与 CYP3A4 抑制剂合用升高浓度"},{"name":"A 型肉毒毒素（内镜注射）","dose":"80–100 U 分四点注射于食管胃交界肌层，或遵说明书","note":"高龄、合并症多者；疗效 6–12 个。","renal":"遵说明书","hepatic":"遵说明书","interact":"与氨基糖苷类合用加重神经肌肉阻滞"},{"name":"奥美拉唑","dose":"20 mg 口服 qd–bid，或遵说明书","note":"POEM 或 Heller 术后防反。","renal":"无需调整","hepatic":"重度肝病减量","interact":"降低氯吡格雷活性"},{"name":"氟康唑","dose":"首日 200 mg，之后 100–200 mg 口服 qd，7–14 d，或遵说明书","note":"合并念珠菌食管炎","renal":"CrCl <50 减量","hepatic":"监测肝酶并减量","interact":"与华法林、他汀相互作用"}],"nonDrug":["POEM：黏膜下隧道切开 LES 与胃肌层 8–10 cm。","腹腔镜 Heller + Dor 180° 折叠：长期疗效确。","内镜球囊扩张 30–40 mm 逐级，需 2–3 次。","终末期巨食管：食管切除 + 胃或结肠代食管","术前纠正营养不良，巨食管者禁食并洗食管","术后 Eckardt 评分与钡餐排空评估。"],"life":["细嚼慢咽、少量多餐，餐后饮水并直立 ≥30 。","避免过硬过烫与碳酸饮料","POEM 后短期流质 + PPI。"]},"prog":"POEM 或 Heller 后 5 年症状缓解率 80%–90%，Ⅲ型对 POEM 反应较好。","refs":["《中国贲门失弛缓症诊治专家共识（2023）》","《POEM 治疗贲门失弛缓症中国专家共识》（2020）","《ISDE 贲门失弛缓症诊疗指南》（2020）"]},{"id":"cts_pectus","name":"鸡胸与漏斗胸","aka":["漏斗胸","Pectus Excavatum","鸡胸","Pectus Carinatum","Haller 指数","Nuss 手术"],"rank":4,"basic":{"define":"最常见的两类先天性胸壁畸形：漏斗胸为胸骨下段与肋软骨内陷压迫心肺，鸡胸为胸骨与肋软骨前突。Haller 指数＝胸腔横径/胸骨后最短距离。","risk":["先天性，男孩多见（漏斗胸约 4:1）","Marfan、Ehlers-Danlos。","家族史（漏斗胸达 40%）。"],"epi":"漏斗胸发生率约 1/300–1/400，占胸壁畸形 >90%；鸡胸约为其 1/5，多在青春期前发现。"},"patho":"肋软骨过度生长使前胸壁内陷或前突。凹陷压迫右心与右肺、心脏左移，运动时静脉回流受限，出现运动耐量下降与限制性通气；鸡胸多不影响心肺。两者均可致体像焦虑与社交回避。","dx":{"criteria":["前胸壁凹陷或前突，可不对称，深吸气凹陷加深","CT 测 Haller 指数：>3.25 重度，2.0–3.25 中度","心电图 + 超声心动图：右心受压、二尖瓣脱垂","肺功能限制性通气障碍，CPET 评估运动耐量"],"workup":["胸部 CT 测 Haller 指数","心电图与心脏超声","肺功能与 CPET","脊柱与遗传评估"],"grading":"按 Haller 分轻度 <3.2、中度 3.2–3.5、重度 >3.5；按对称性分对称与不对称型。鸡胸分中央型与混合型。"},"ddx":[{"name":"胸壁肿瘤（cts_chest_wall_tumor）","point":"为局限性肿块伴骨破坏；胸壁畸形无肿块。"},{"name":"膈疝与食管裂孔疝（cts_diaphragmatic_hernia）","point":"以消化道症状与膈上胃囊为主，无前胸壁外形异常。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"500–1000 mg 口服 q6h，每日 ≤2 g，或遵说明书","note":"多模式镇痛基础","renal":"CrCl <30 延长间隔","hepatic":"严重肝病禁用","interact":"影响华法林 INR"},{"name":"芬太尼（PCA/硬膜外）","dose":"负荷 0.5–1 μg/kg 后 0.2–0.5 μg/kg/h；或硬膜外 0.1% 布比卡因 + 芬太尼 2 μg/mL 4–8 mL/h，遵说明书","note":"Nuss 术后疼痛剧烈。","renal":"无需调整","hepatic":"严重肝病减量","interact":"与苯二氮䓬类合用加重呼吸抑制"},{"name":"布比卡因（肋间/椎旁阻滞）","dose":"0.25% 布比卡因每点 3–5 mL 多点注射或椎旁置管，或遵说明书","note":"术中与术后镇痛","renal":"重度肾功能不全慎用","hepatic":"重度肝病减量","interact":"与延长 QT 药物合用增加心脏毒性"},{"name":"头孢唑林（围手术期）","dose":"1–2 g 静脉滴注，术前 0.5–1 h，或遵说明书","note":"预防切口与钢板感染","renal":"CrCl <35 延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度"},{"name":"酮咯酸（短期）","dose":"15–30 mg 静脉 q6h，≤72 h；或 10 mg 口服 q6h，或遵说明书","note":"仅围手术期短期镇痛，青少年慎用","renal":"CrCl <30 禁用","hepatic":"重度肝病禁用","interact":"与抗凝药合用增加出血"}],"nonDrug":["手术指征：Haller ≥3.25、运动耐量下降、右心受压、。","Nuss：经胸骨后隧道置入预弯钢板翻转抬起胸骨。","钢板留置 2–3 年取出；并发症为钢板移位 5%–10%、气。","Ravitch：切除畸形肋软骨 + 胸骨截骨。","鸡胸：骨骺未闭合青少年用胸壁支具。","禁忌：不能耐受全麻、胸壁感染、严重脊柱畸形"],"life":["术后 6–8 周避免提重物与剧烈扭转。","钢板留置期避免接触性运动","取钢板后 3 个月逐步恢复运动"]},"prog":"Nuss 术后矫形满意率 80%–90%，取钢板后复发率 3%–8%；鸡胸支具矫形成功率 60%–80%。","refs":["《中国胸壁畸形（漏斗胸与鸡胸）诊疗专家共识》（2021）","《国际胸壁畸形学会（CWIG）管理共识》（2018）"]}]},{"id":"lung_benign_surg","name":"肺部良性疾病外科","rank":6,"summary":"核心是「界定手术适应证 + 保护肺功能」：肺大疱切除 + 胸膜固定用于复发性气胸，支气管扩张仅限局限型，肺转移瘤以「完全切除 + 无病间期」决策；纵隔感染与食管破裂为外科急症。","compare":[{"diseaseId":"cts_bulla","dx":"CT 见肺尖薄壁透亮囊腔，伴复发气胸或对侧气胸","key":"VATS 肺大疱切除 + 胸膜固定，复发率降至 3%–5%"},{"diseaseId":"cts_bronchiectasis_surg","dx":"HRCT 见印戒征且局限一叶/段，反复咯血或同部位感染","key":"仅局限型、内科无效者手术；弥漫型禁忌"},{"diseaseId":"cts_lung_metastasis","dx":"原发肿瘤史，CT 见多发外周实性结节","key":"无病间期长、可 R0 切除且肺功能足够者获益"},{"diseaseId":"cts_mediastinitis","dx":"呕吐后胸痛、皮下气肿、纵隔气肿，胸水淀粉酶升高","key":"禁食 + 大孔径引流 + 广谱抗生素；<24 h 修补，>24 h 旷置"}],"diseases":[{"id":"cts_bulla","name":"肺大疱与自发性气胸外科","aka":["肺大疱","Bulla","肺大泡切除","胸膜固定","VATS 肺大疱切除"],"rank":1,"basic":{"define":"肺大疱为细支气管活瓣阻塞后肺泡融合形成的薄壁含气腔；自发性气胸多由其破裂引起。外科治疗为切除病灶、封闭漏口并进行胸膜固定以防复发。","risk":["年轻瘦高男性、低体重与吸烟","COPD、肺气肿、陈旧肺结核","Marfan 综合征等结缔组织病"],"epi":"自发性气胸约（18–28）/10 万（男）、（1–6）/10 万（女）；原发者首次保守后复发率 20%–30%。"},"patho":"胸膜下肺泡破裂融合成大疱，破裂后气体经单向活瓣进入胸膜腔，肺萎陷致通气/血流失调与低氧；持续漏气使脏壁层胸膜无法贴附，妨碍愈合。巨大大疱压迫周围肺组织，是复发性气胸的解剖基础。","dx":{"criteria":["肺大疱多无症状，CT 见薄壁（<1 mm）无纹理透亮区，周围肺受压呈弧形","气胸：突发单侧胸痛与呼吸困难，患侧呼吸音减弱、叩诊鼓音","按胸膜线距胸壁 <2 cm 为小量、≥2 cm 为大量（BTS）","床旁超声肺滑动征消失、条码征，敏感性高于胸片"],"workup":["立位胸片 + 床旁超声","胸部薄层 CT","血气与 SpO₂ 监测","肺功能（FEV₁、DLCO）"],"grading":"原发/继发；小量 <2 cm、大量 ≥2 cm；急性与慢性（陷闭肺）；大疱性肺气肿按上叶/下叶为主评估肺减容。"},"ddx":[{"name":"支气管扩张外科治疗（cts_bronchiectasis_surg）","point":"支气管扩张以脓痰、咯血与印戒征为主；肺大疱无纹理透亮、无脓痰。"},{"name":"肺转移瘤切除（cts_lung_metastasis）","point":"转移瘤为多发实性结节并有原发肿瘤史。"}],"tx":{"drug":[{"name":"吗啡","dose":"2–4 mg 静脉缓推，必要时 2–4 h 重复，或遵说明书","note":"胸痛与置管镇痛","renal":"肾功能不全减量","hepatic":"严重肝病减量","interact":"与镇静药合用加重呼吸抑制"},{"name":"头孢唑林","dose":"1–2 g 静脉滴注，术前 0.5–1 h，或遵说明书","note":"肺大疱切除与胸膜固定围手术期预防","renal":"CrCl <35 延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度"},{"name":"布比卡因（肋间/胸管注入）","dose":"0.25% 布比卡因 20 mL 多节段阻滞或经胸管注入，或遵说明书","note":"减少阿片用量，促进肺复张","renal":"重度肾功能不全慎用","hepatic":"重度肝病减量","interact":"与延长 QT 药物合用增加心脏毒性"},{"name":"沙丁胺醇（雾化）","dose":"2.5 mg 雾化 q6h，或遵说明书","note":"合并 COPD 或气道痉挛者改善通气","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 阻滞剂拮抗，注意低钾"},{"name":"依诺肝素","dose":"40 mg 皮下 qd，术后 12–24 h 开始，或遵说明书","note":"术后 VTE 预防","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["初发小量且稳定：观察 + 吸氧，24–48 h 复查","大量或有症状：抽气或 8–14 Fr 胸管。","手术指征：同侧第二次发作、对侧气胸、飞行员/潜水员、漏气 >。","术式：VATS 楔形/电凝切除肺大疱 + 胸膜摩擦或滑石粉固。","大疱 >1/3 且上叶为主者肺减容。","禁忌：不能耐受单肺通气、凝血障碍、广泛粘连"],"life":["严格戒烟，降低复发与对侧新发","术后 4–6 周避免剧烈咳嗽与对抗性运动","完全复张前禁乘飞机，胸膜固定者终身禁潜水"]},"prog":"切除 + 胸膜固定后复发率 3%–5%，住院病死率 <1%；合并 COPD 的继发性气胸病死率 10%–20%。","refs":["《自发性气胸诊断与治疗中国专家共识（2023）》","《VATS 肺大疱切除与胸膜固定技术规范》（2019）","《BTS 自发性气胸管理指南》（2023）"]},{"id":"cts_bronchiectasis_surg","name":"支气管扩张外科治疗","aka":["Bronchiectasis","支气管扩张症","局限型支气管扩张","印戒征"],"rank":2,"basic":{"define":"支气管壁慢性破坏性炎症致不可逆扩张，分柱状、静脉曲张型与囊状。外科仅适用于病变局限（一叶或一段为主）、内科无效且反复咯血或感染者。","risk":["儿童期下呼吸道感染（麻疹、百日咳、肺炎）","肺结核尤其毁损肺","免疫缺陷、原发性纤毛不动综合征"],"epi":"我国 40 岁以上患病率约 1%–2%，多数为局限型；反复咯血与感染为主要就诊原因，外科手术占比 <10%。"},"patho":"炎症破坏支气管壁弹性纤维与软骨形成扩张，纤毛清除受损使分泌物潴留，铜绿假单胞菌长期定植，形成「感染—炎症—扩张」恶性循环；支气管动脉增生致咯血。病灶局限时切除可去除感染与出血来源。","dx":{"criteria":["慢性咳嗽、大量脓痰（晨起为著）、反复咯血与反复下呼吸道感染","HRCT：柱状「轨道征」、囊状「印戒征」（管径大于伴行动脉）、壁增厚","病变以一叶或某段为主，其余肺段相对正常（手术前提）","痰培养含铜绿假单胞菌与药敏"],"workup":["HRCT 薄层 + 多平面重建","支气管镜 + 灌洗","≥2 次痰培养与药敏","肺功能、血气、步行试验"],"grading":"柱状、静脉曲张型、囊状；局限型与弥漫型；咯血：中量 >100 mL/24 h，大咯血 >500 mL/24 h 或每次 >100 mL。"},"ddx":[{"name":"肺大疱与自发性气胸外科（cts_bulla）","point":"肺大疱为薄壁透亮腔，无慢性咳脓痰。"},{"name":"肺转移瘤切除（cts_lung_metastasis）","point":"多发实性结节并有原发癌史；支气管扩张为气道形态改变。"}],"tx":{"drug":[{"name":"左氧氟沙星","dose":"0.5 g 静脉滴注 qd（重度 0.75 g），7–14 d，或遵说明书","note":"急性加重经验治疗，获药敏后调整","renal":"CrCl <50 减量并延长间隔","hepatic":"重度肝病减量","interact":"与含铝/镁抗酸剂降低吸收，QT 延长叠加"},{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静脉滴注 q6–8h，延长输注 4 h，或遵说明书","note":"铜绿假单胞菌感染或重度加重","renal":"CrCl 20–40 用 4.5 g q8h","hepatic":"遵说明书","interact":"与万古霉素合用增加肾损伤"},{"name":"氨溴索","dose":"30 mg 静推/口服 q8h，或遵说明书","note":"促排痰，配合气道廓清","renal":"重度肾功能不全延长间隔","hepatic":"遵说明书","interact":"与镇咳药合用减弱祛痰效果"},{"name":"垂体后叶素","dose":"6–12 U 加入 5% 葡萄糖 20–40 mL 缓慢静推 >10 min，继 0.1–0.2 U/min 泵入，或遵说明书","note":"大咯血止血；高血压、冠心病、孕妇禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与降压药拮抗"},{"name":"头孢呋辛（围手术期）","dose":"1.5 g 静脉滴注，术前 0.5–1 h，或遵说明书","note":"有铜绿假单胞菌定植者改抗假单胞菌药","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"}],"nonDrug":["内科基础：气道廓清、雾化，长期小剂量阿奇霉素 250–500 mg 每周 3 次。","手术适应证：局限型、反复咯血（内科与栓塞失败）、同一部位反复。","大咯血 >500 mL/24 h：先保气道。","术式：病变肺段/肺叶切除（VATS 为主），双侧局限者分期","禁忌：双侧弥漫型、FEV₁ <40% 预计、活动性肺结核未控","术前 5–7 d 抗生素与强化排痰，减少支气管胸膜瘘"],"life":["戒烟，接种流感与肺炎球菌疫苗","每日体位引流与主动循环呼吸技术","术后 6–8 周避免剧烈活动。"]},"prog":"局限型术后症状缓解率 70%–90%，5 年无复发约 80%；弥漫型以内科治疗为主。","refs":["《中国支气管扩张症诊断与治疗指南（2021 年版）》","《支气管扩张症微创外科治疗中国专家共识》（2019）","《ERS 支气管扩张症管理指南》（2017）"]},{"id":"cts_lung_metastasis","name":"肺转移瘤切除指征","aka":["Pulmonary Metastasis","肺转移瘤切除","转移灶切除","无病间期"],"rank":3,"basic":{"define":"原发肿瘤经血行或直接蔓延至肺的结节；肺转移瘤切除适用于原发灶可控、肺部病灶可完全切除（R0）且无其他不可控转移者，可获得长期生存甚至治愈。","risk":["结直肠癌、肾癌、骨与软组织肉瘤、头颈肿瘤。","原发肿瘤分期晚、伴淋巴血管侵犯","无病间期（原发治疗后至肺转移）<12 个。"],"epi":"约 20%–30% 实体瘤出现肺转移，其中 10%–20% 为孤立性；结直肠癌肺转移切除后 5 年生存率 40%–60%。"},"patho":"肿瘤细胞经静脉回流入肺毛细血管床，形成多发、多位于外周与下叶的结节。转移灶多呈膨胀性生长、血供稀疏，数量可多而肺功能损害小；复发多源于微转移，故楔形切除即可取得与肺叶切除相近的效果。","dx":{"criteria":["原发肿瘤病史，随访影像发现新发结节；多数无症状","胸部增强薄层 CT 确定数目、大小与分布，为手术决策核心","多发、边界清楚、外周分布（「炮弹征」见于肾癌与肉瘤）","PET-CT 与全身分期确认肺外无不可控转移"],"workup":["胸部增强薄层 CT + 腹部影像","PET-CT 全身评估","肿瘤标志物（CEA、NSE）","肺功能与心肺评估"],"grading":"无统一分期；预后较佳：无病间期 >12 个月、<3–4 个病灶、最大径 <3 cm、单侧；按可切除性分可切除、临界、不可切除。"},"ddx":[{"name":"肺大疱与自发性气胸外科（cts_bulla）","point":"肺大疱为薄壁含气腔无实性成分；转移瘤为实性结节。"},{"name":"支气管扩张外科治疗（cts_bronchiectasis_surg）","point":"以脓痰、咯血与印戒征为主；转移瘤为结节且多无症状。"}],"tx":{"drug":[{"name":"奥沙利铂 + 亚叶酸钙 + 5-FU（结直肠癌）","dose":"mFOLFOX6：奥沙利铂 85 mg/m²、亚叶酸钙 400 mg/m²、5-FU 400 mg/m² 静推 + 2400 mg/m² 持续 46 h，每 14 d；按 CSCO/NCCN 与体表面积调整","note":"围手术期或转化治疗。","renal":"奥沙利铂 CrCl <30 慎用","hepatic":"重度肝病减量","interact":"5-FU 与华法林合用显著增加 INR"},{"name":"舒尼替尼（肾癌）","dose":"50 mg 口服 qd 服 4 周停 2 周，或 37.5 mg 连续，按说明书与 CSCO 肾癌指南调整","note":"晚期肾癌靶向；部分减瘤后转移灶可切除","renal":"中重度慎用","hepatic":"重度不推荐","interact":"CYP3A4 抑制剂/诱导剂影响浓度"},{"name":"伊马替尼（GIST）","dose":"400 mg 口服 qd（必要时 800 mg/d），按 CSCO GIST 指南与基因型调整","note":"GIST 转移首选靶向。","renal":"遵说明书","hepatic":"中度减量，重度禁用","interact":"与 CYP3A4 抑制剂合用升高浓度"},{"name":"帕博利珠单抗","dose":"200 mg 静脉滴注 q3w 或 400 mg q6w，按适应证与说明书","note":"黑色素瘤等 PD-1 敏感肿瘤。","renal":"无需调整","hepatic":"重度慎用","interact":"糖皮质激素可能降低疗效"},{"name":"头孢呋辛（围手术期）","dose":"1.5 g 静脉滴注，术前 0.5–1 h，或遵说明书","note":"肺楔形/肺叶切除预防感染","renal":"CrCl <30 延长间隔","hepatic":"遵说明书","interact":"与华法林合用增加出血"}],"nonDrug":["R0 完全切除是获益前提：楔形切除首选（切缘 ≥5 mm）。","双侧病变同期或分期楔形切除，以保留肺功能为限","单侧多发或复发者可反复切除，需评估肺储备","不可手术者选 SBRT、射频消融或系统治疗后再评估","术前 4–6 周停抗血管生成靶向药，减少出血与愈合不良","术后前 2 年每 3 个月胸部 CT。"],"life":["规律复查胸部 CT 与肿瘤标志物","戒烟与肺康复，蛋白 1.2–1.5 g/kg。","按原发肿瘤方案完成系统治疗，不自行停药"]},"prog":"R0 切除后 5 年生存率 30%–50%，结直肠癌肺转移可达 40%–60%。","refs":["《中国肺转移瘤外科治疗专家共识》（2021）","《CSCO 结直肠癌诊疗指南（2023）》","《NCCN 结直肠癌指南（2023）》"]},{"id":"cts_mediastinitis","name":"纵隔感染与食管破裂","aka":["纵隔炎","Mediastinitis","食管破裂","Boerhaave 综合征","食管穿孔"],"rank":4,"basic":{"define":"纵隔内结缔组织的急性化脓性感染，感染源多为食管穿孔（自发性 Boerhaave、医源性、异物、肿瘤），也见于颈部感染下行与心胸外科术后，属外科急症。","risk":["剧烈呕吐后自发性破裂，酗酒与暴食者多见","医源性：内镜、扩张/支架、术后吻合口瘘","异物（鱼刺、义齿）或腐蚀性损伤"],"epi":"Boerhaave 年发病率约 1/60 万，40–60 岁男性多见；内镜治疗后穿孔约 0.1%–5%。"},"patho":"食管全层破裂后唾液、胃酸与食物进入纵隔，引起坏死性纵隔炎与胸膜腔感染；纵隔间隙连通且食管无浆膜层，感染可数小时蔓延至下纵隔与双侧胸腔，导致脓胸与脓毒性休克。","dx":{"criteria":["Mackler 三联征：呕吐、胸痛、皮下气肿；常伴呼吸困难、发热与休克","颈胸部握雪感、纵隔气肿与 Hamman 征高度提示","胸部 CT（含碘对比）首选：纵隔气肿、积液、食管壁缺损与脓腔。","碘水（非钡剂）造影见造影剂外溢；阴性而高度怀疑者行低充气胃镜"],"workup":["胸腹增强 CT 并口服碘水","食管碘水造影（不用钡剂）","低充气胃镜定位破口","引流液淀粉酶、培养"],"grading":"按时间 <24 h、24–72 h、>72 h；按部位颈段、胸上/中/下段、腹段；按病因自发、医源、异物、吻合口瘘。"},"ddx":[{"name":"肺大疱与自发性气胸外科（cts_bulla）","point":"气胸为胸膜腔积气与突发胸痛，无呕吐史与皮下气肿。"},{"name":"支气管扩张外科治疗（cts_bronchiectasis_surg）","point":"为慢性咳脓痰与咯血，无纵隔气肿。"}],"tx":{"drug":[{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静脉滴注 q6–8h，延长输注 4 h，或遵说明书","note":"覆盖革兰阴性菌与厌氧菌。","renal":"CrCl 20–40 用 4.5 g q8h","hepatic":"遵说明书","interact":"与万古霉素合用增加肾损伤"},{"name":"万古霉素","dose":"15–20 mg/kg 静脉滴注 q8–12h，谷浓度 15–20 mg/L，或遵说明书","note":"疑 MRSA 或医院获得性感染时联合","renal":"按 CrCl 调整并监测浓度","hepatic":"遵说明书","interact":"与哌拉西林他唑巴坦合用增加肾损伤"},{"name":"甲硝唑","dose":"500 mg 静脉滴注 q8h，或遵说明书","note":"覆盖口腔与消化道厌氧菌","renal":"重度肾功能不全减量","hepatic":"重度肝病减量","interact":"禁酒，与华法林相互作用"},{"name":"卡泊芬净","dose":"首日 70 mg，之后 50 mg 静脉滴注 qd，或遵说明书","note":"长期广谱抗生素或疑念珠菌纵隔炎时加用","renal":"无需调整","hepatic":"中度肝病减至 35 mg qd","interact":"与环孢素合用升高浓度"},{"name":"去甲肾上腺素","dose":"0.05–0.5 μg/kg/min 静脉泵入，滴定至 MAP ≥65 mmHg","note":"脓毒性休克在液体复苏基础上使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他交感胺类合用致严重高血压"}],"nonDrug":["立即禁食、胃肠减压、大口径胸腔引流 + 广谱抗生素 + 液体。","<24 h 的胸段破裂首选一期修补（开胸或胸腔镜）",">24 h 或污染严重：引流 + 食管旷置 + 胃造瘘营养，后期重建。","早期小破口 <2 cm 可内镜金属夹、OTSC、覆膜支架或内。","内镜操作中穿孔立即金属夹闭合，禁食、引流、抗生素","早期肠内营养，蛋白 1.5 g/kg/d"],"life":["进食由流质逐步过渡，少量多餐。","2 周、1 个月复查食管造影与胸片","戒烟酒，避免暴饮暴食与剧烈呕吐"]},"prog":"24 h 内手术者病死率 <10%，超过 24 h 升至 30%–50%；内镜早期闭合的小破口预后好。","refs":["《食管穿孔与食管破裂诊治中国专家共识》（2020）","《急性纵隔感染诊断与治疗中国专家共识》（2021）","《ESGE 医源性穿孔管理指南》（2020）"]}]},{"id":"lung_rare","name":"罕见肺部疾病的外科（肺隔离症、肺动静脉瘘、食管憩室）","rank":7,"summary":"临床少见但易误诊的一类：肺隔离症与肺动静脉瘘须先靠 CTA 确认异常血管再决定切除或栓塞，并排除 HHT 等遗传性疾病；食管憩室须完善吞咽造影与胃镜，以憩室切除+环咽肌切开为主。","compare":[{"diseaseId":"cts_sequestration","dx":"反复左下肺感染，CTA 见来自主动脉的异常体循环动脉供血，肺叶内囊性/肿块影","key":"异常体循环动脉供血"},{"diseaseId":"cts_pavf","dx":"活动后发绀、低氧血症与杵状指，CTA 见肺动静脉之间的异常交通血管团","key":"右向左分流与低氧"},{"diseaseId":"cts_esophageal_diverticulum","dx":"吞咽困难、反流、颈段膨出，食管造影见食管黏膜外突的憩室腔","key":"食管外突囊袋，Zenker 型在环咽肌上方"}],"diseases":[{"id":"cts_sequestration","name":"肺隔离症","aka":["Pulmonary Sequestration","肺叶内型隔离症","肺叶外型隔离症"],"rank":1,"basic":{"define":"一部分无通气功能的肺组织与正常支气管树分离，由体循环异常动脉供血；分叶内型（与正常肺共享脏层胸膜，多左下肺后基底段）与叶外型（有独立脏层胸膜，多见于左侧膈上，常伴其他畸形）。","risk":["多为先天性，胚胎期前肠-肺芽发育异常","叶外型常合并膈疝、先天性心脏病、椎体畸形等","成人发病多因反复感染或偶然发现"],"epi":"占先天性肺畸形的 0.15%–6%，叶内型约占 75%–90%，好发左下肺（约 60%），儿童与成人均可发病。"},"patho":"隔离肺组织无正常支气管沟通，分泌物无法引流，形成囊性变与反复感染；异常体循环动脉多来自胸主动脉或腹主动脉，血管壁薄弱、压力高，可破裂出血至肺内或胸腔。叶内型静脉多引流至肺静脉（形成左向左分流），叶外型多引流至体循环静脉（右向左分流）。","dx":{"criteria":["反复肺部感染（左下肺为主）、咳嗽咳痰，或体检偶发","增强 CT 或 CTA 见异常体循环动脉（多为胸主动脉下段或腹主动脉上段分支）进入隔离肺组织","隔离区内囊性、含气或含液病灶，与支气管树不连通","DSA 在需栓塞或术前进一步确认时使用","叶外型需评估合并畸形（胸片、心脏超声、脊柱影像）"],"workup":["胸片：左下肺囊性或肿块影、后方脊柱旁密度增高","胸部增强 CT/CTA：确认异常动脉起源、行径与数目，评估隔离范围与肺实质破坏","支气管镜检查：多无异常，用于排除异物、肿瘤与脓腔","叶外型查心脏超声、脊柱影像寻找并发畸形","术前肺功能、血气分析"],"grading":"按解剖分叶内型与叶外型；按静脉回流：叶内型多入肺静脉、叶外型多入体静脉；按供血动脉数目与部位评估手术难度。"},"ddx":[{"name":"肺动静脉瘘","point":"与本类中肺动静脉瘘的鉴别：AVM 表现为肺动静脉之间的异常交通，伴低氧与发绀、右向左分流，CTA 见扩张的供血肺动脉与引流肺静脉；隔离症为体循环动脉供血、无右向左分流。"},{"name":"支气管源性囊肿","point":"单房囊性病变，无体循环动脉供血。"},{"name":"支气管扩张","point":"累及多个肺段、双肺分布，需 CT 确认有无异常动脉。"},{"name":"肺脓肿","point":"急性发热、脓痰与液气平面，多无体循环异常动脉。"},{"name":"先天性肺气道畸形（CPAM）","point":"儿童多发病变，肺气道发育异常，无异常体循环动脉。"}],"tx":{"drug":[{"name":"抗感染（术前控制感染）","dose":"按痰培养及药敏选择，常用头孢类如头孢呋辛 1.5 g 静脉滴注 每 8 h 或哌拉西林他唑巴坦 4.5 g 每 8 h，7–14 d，遵医嘱","note":"控制感染后再手术；反复发作者需足疗程，但抗感染不能根治","renal":"按 CrCl 调整剂量与间隔，遵说明书","hepatic":"遵说明书","interact":"与丙戊酸等相互作用，遵说明书"},{"name":"止咳祛痰与物理排痰","dose":"氨溴索 30 mg 口服 每日 3 次或雾化，遵说明书","note":"促进分泌物排出，减少感染复发","renal":"遵说明书","hepatic":"遵说明书","interact":"与镇咳药同用可能抑制排痰"}],"nonDrug":["手术切除：叶内型原则上积极手术（多行肺叶或肺段切除），防止反复感染与咯血；叶外型多数也建议切除（有恶变与感染风险）","关键步骤：术前 CTA 明确异常动脉，术中仔细识别并处理，防止大出血；建议在肺裂分离与肺门处理之后切断异常动脉，减少回缩漏血","微创（胸腔镜/机器人）肺叶切除适用于无严重粘连者；巨大或反复感染者可开胸","胸腔镜下难以控制的异常动脉出血：立即中转开胸","无症状成人叶外型可在多学科评估后选择观察，但需定期随访"],"life":["术后定期胸片或 CT 随访，注意是否有残留或复发","戒烟、预防呼吸道感染","叶外型儿童需随访合并畸形"]},"prog":"手术切除后复发率低，预后良好；未治疗者因反复感染可有肺组织毁损、咯血，异常动脉破裂大出血罕见但致命。叶内型术后并发症主要为术中异常动脉出血与支气管胸膜瘘。","refs":["中国胸腔镜肺叶切除手术规范（2016）","小儿先天性肺发育异常诊治中国专家共识（2020）","2016 ERS 先天性肺畸形管理建议"]},{"id":"cts_pavf","name":"肺动静脉瘘","aka":["Pulmonary Arteriovenous Fistula","PAVF","PAVM","肺动静脉畸形"],"rank":2,"basic":{"define":"肺动脉与肺静脉之间绕过毛细血管床的异常交通，形成右向左分流；可单发或多发，直径 >3 mm 时临床意义明显。约 50%–80% 与遗传性出血性毛细血管扩张症（HHT）相关。","risk":["HHT（Osler-Weber-Rendu 综合征）患者中 15%–50% 合并 PAVF，与 ENG、ACVRL1、SMAD4 基因突变相关","合并 HHT 家族史、反复鼻衄、皮肤黏膜毛细血管扩张","妊娠期因血流动力学改变可增大，增加破裂风险"],"epi":"散发性 PAVF 患病率约 1/10 万，HHT 患病率约 1/5000–1/8000；女性多于男性。"},"patho":"异常血管囊壁薄弱、无毛细血管床缓冲，右向左分流使未氧合血进入肺静脉，导致低氧血症与发绀；微血栓与细菌可绕过肺毛细血管滤过，引起反常栓塞、脑卒中和脑脓肿。妊娠与分娩时血管扩张可致破裂出血，患者咯血。","dx":{"criteria":["活动后呼吸困难、发绀、杵状指；直立位低氧加重（直立性低氧血症）","血氧饱和度与 PaO2 降低，100% 纯氧试验仍有分流","CTA 见血管性结节伴供血肺动脉与引流肺静脉扩张（瘤囊样），为诊断金标准","右向左分流定量：造影超声心动图（agitated saline）可见右心显影后 3–6 个心动周期内左心出现气泡","HHT 诊断（Curaçao 标准）：鼻衄、皮肤黏膜毛细血管扩张、内脏动静脉畸形、一级亲属患病，满足 3 项为确诊、2 项为可疑"],"workup":["胸部增强 CT/CTA（含 MIP 重建），测定最大直径与供血动脉口径","血气分析与 100% 纯氧分流试验；右心导管/造影用于复杂病例","造影超声心动图评估右向左分流程度","HHT 评估：家族史、鼻衄、皮肤检查、肝脏/脑 MRI、血常规（贫血）","脑 MRI 或 MRA 排除合并脑动静脉畸形；腹部超声评估肝脏动静脉畸形"],"grading":"按大小：小（<3 mm，通常无临床意义）、大（≥3 mm，分流明显且栓塞并发症风险高）；按通路分简单瘘（单一供血动脉与单一引流静脉）与复杂瘘（多条供血/多段）；数目分单发与多发。"},"ddx":[{"name":"肺隔离症","point":"与本类中肺隔离症的鉴别：隔离肺由体循环动脉供血、无右向左分流与低氧血症；PAVF 由肺动脉供血并与肺静脉直接相通，伴发绀与分流。"},{"name":"支气管扩张伴咯血","point":"以咳血与反复感染为主，CT 见支气管扩张，无明显异常血管交通。"},{"name":"肺癌（血管性病灶）","point":"病灶不均匀强化、伴淋巴结与浸润征象，无活动性分流。"},{"name":"肺结核球","point":"多为边界清楚单发结节，钙化常见，无低氧与分流。"},{"name":"肺血管瘤（毛细血管性）","point":"极少见，多无右向左分流，造影超声阴性。"}],"tx":{"drug":[{"name":"预防性抗生素（口腔及感染时）","dose":"侵袭性牙科操作前按美国心脏协会方案口服阿莫西林 2 g，青霉素过敏者用克林霉素等，遵说明书","note":"HHT 合并 PAVF 者脑脓肿风险高，建议牙科及操作前预防；无分流或极小病灶者按个体化","renal":"遵说明书","hepatic":"遵说明书","interact":"阿莫西林与别嘌醇合用皮疹增多"},{"name":"补铁（继发性贫血）","dose":"口服铁剂（如琥珀酸亚铁 0.1–0.2 g 每日 2–3 次），按血红蛋白调整","note":"HHT 患者因反复鼻衄与分流致铁缺乏性贫血常见","renal":"遵说明书","hepatic":"遵说明书","interact":"与质子泵抑制剂、四环素类、锌剂间隔服用"},{"name":"靶向药物（HHT 相关，试验性）","dose":"贝伐珠单抗、沙利度胺、他克莫司等有报道改善分流与鼻衄，剂量遵说明书与专科中心方案","note":"仅用于多发、反复出血或栓塞禁忌者的试验性治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["栓塞治疗为首选：经导管用弹簧圈或血管塞闭塞供血动脉，适用于绝大多数 PAVF（>3 mm 或伴分流症状）；成功率 90% 以上","手术（局部切除或肺叶切除）：栓塞失败、巨大瘘、瘘管过于表浅或合并感染出血者","栓塞指征：病灶 ≥3 mm、有症状（低氧、呼吸困难）、有右向左分流证据、供血动脉足够粗可置入装置","栓塞并发症：装置移位、异位栓塞（脑、前壁心梗）、复发","HHT 者术前全面筛查全身动静脉畸形"],"life":["每 1–3 年 CTA 或随访分流（孕前、妊娠期应评估）","避免潜水、高空作业等可能导致气栓/反常栓塞的活动","妊娠期随访心超声与氧饱和度","告知医生自身 PAVF/HHT 史，在接受侵入性操作前评估预防"]},"prog":"单发小病灶预后良好；多发或大病灶伴右向左分流者需注意反常栓塞与出血。栓塞后 5 年通畅率较高，但可复发（尤其 HHT 患者），需长期随访。HHT 者中位生存与脑/肺并发症与筛查密切相关。","refs":["遗传性出血性毛细血管扩张症诊治中国专家共识（2019）","2016 HHT 指南（Second International Guidelines for the Diagnosis and Management of HHT）"]},{"id":"cts_esophageal_diverticulum","name":"食管憩室","aka":["Esophageal Diverticulum","Zenker 憩室","咽食管憩室","食管中段憩室"],"rank":3,"basic":{"define":"食管壁局限性向外突出形成的囊袋，按部位分咽食管型（Zenker，环咽肌上方的下咽部）、食管中段型（牵引型，与纵隔淋巴结感染纤维化相关）与膈上型（与食管动力障碍相关）。","risk":["40 岁以上、男性多见，尤其 Zenker 憩室","环咽肌功能障碍或食管动力异常（如贲门失弛缓）导致腔内压升高","纵隔淋巴结结核或感染后瘢痕牵拉（牵引型）","长期反流、食管裂孔疝、衰老致咽部肌萎缩"],"epi":"Zenker 憩室年发病率约 0.1–0.5/10 万，高峰 70–80 岁，男女比例约 2–3:1；中段牵引型在结核高发区仍可见。"},"patho":"环咽肌本应与吞咽同步松弛，而括约肌与咽部肌肉收缩不同步，使下咽部压力升高，黏膜经肌层薄弱处（Killian 三角）膨出，形成囊袋。囊袋逐渐扩大可压迫食管腔致吞咽困难与反流，内容物滞留引起口臭、误吸与吸入性肺炎。中段牵引型由纵隔纤维化牵拉形成真性憩室（含全层）。","dx":{"criteria":["高危人群：老年人进行性吞咽困难，进食后反流未消化食物、口臭、颈部肿块或咕噜声","食管钡餐（吞咽造影）为诊断金标准：咽食管交界处后壁囊袋，与食管腔相通，可观察排空与滞留","上消化道内镜：观察憩室开口、黏膜与并发疾病（肿瘤、炎），Zenker 憩室镜检有穿孔风险，须由有经验医师操作","高分辨率食管测压：评估环咽肌松弛不全与动力障碍","胸部 CT：中段憩室确定与纵隔、气道的关系，排除肿瘤"],"workup":["食管造影（含动态吞咽），明确憩室位置、大小与颈部狭窄","胃镜评估食管腔与并发疾病，警惕憩室内合并癌（罕见）","食管测压评估动力障碍与环咽肌功能","胸部 CT 评估憩室与周围结构、有无吸入性肺炎","营养状态与误吸风险评估（吞咽功能评估）"],"grading":"Zenker 按大小：小（<2 cm 位于咽后）、中（2–3 cm）、大（>3 cm 可达颈部或纵隔），大憩室更易滞留与误吸；按解剖分 Zenker 型、中段牵引型、膈上型。"},"ddx":[{"name":"贲门失弛缓症","point":"与本类中贲门失弛缓（ct_achalasia）的鉴别：贲门失弛缓为食管下端括约肌不能松弛，影像见食管扩张、鸟嘴样狭窄；食管憩室为局部囊袋，二者可并存但主要矛盾不同。"},{"name":"食管癌","point":"进行性吞咽困难加重、体重下降，内镜见黏膜病变伴活检阳性；憩室相关癌极为罕见。"},{"name":"咽部神经肌肉功能障碍","point":"咽部收缩无力或无环咽肌松弛，影像见造影剂滞留而无囊袋"},{"name":"食管裂孔疝","point":"胃经膈肌上移，CT/造影见胃上提，伴反流；无局部囊袋。"},{"name":"甲状腺肿大（颈部肿块）","point":"随吞咽上下移动，超声与 CT 可明确。"}],"tx":{"drug":[{"name":"抑酸与促动力（对症）","dose":"奥美拉唑 20 mg 口服 每日 1 次；多潘立酮 10 mg 每日 3 次餐前（遵说明书）","note":"仅缓解反流与不适症状，不能缩小憩室；术前合并反流性食管炎时用药","renal":"遵说明书","hepatic":"重度肝功能不全者减量","interact":"奥美拉唑抑制 CYP2C19，影响氯吡格雷活化"},{"name":"抗生素（吸入性肺炎时）","dose":"按药敏或经验性使用，如哌拉西林他唑巴坦 4.5 g 每 8 h 或莫西沙星 0.4 g 每日 1 次，遵医嘱","note":"误吸是主要并发症，须评估吞咽并纠正营养不良","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"莫西沙星与 QT 延长药物合用需注意"}],"nonDrug":["开放手术：经颈部切口憩室切除+环咽肌切开，为经典根治方案，症状缓解率 90%–95%；注意保护喉返神经与甲状腺","内镜下微创（Dohlman/经口内镜下憩室隔切开，STARR）：创伤小、恢复快，用于高龄或不能耐受全麻者，疗效接近开放手术但复发率略高","憩室固定/悬吊术（diverticulopexy）：用于高危患者不切除憩室的替代方案","憩室 >3 cm 或合并症状明显者推荐手术；小而无症状者可观察","误吸或营养不良者术前纠正（必要时置鼻胃管或空肠营养），术后早期吞咽训练"],"life":["进食细嚼慢咽、小口进食并饮水送服，避免进食过快","术后按指导逐步恢复饮食，术后早期吞咽造影评估漏与排空","定期随访复发症状（吞咽困难、反流）","合并动力障碍者长期随访"]},"prog":"治疗充分者症状缓解率 90% 以上，复发率 5%–10%（内镜治疗后略高）。未治疗大憩室者因误吸、营养不良与肺炎影响生活质量，老年患者误吸是主要风险。","refs":["食管憩室诊断与治疗中国专家共识（2021）","中国食管良性疾病诊治专家共识（2018）"]}]}]},"derm":{"categories":[{"id":"eczema_psoriasis","name":"炎症性皮肤病","rank":1,"summary":"特应性皮炎以外用糖皮质激素/钙调神经磷酸酶抑制剂为基础阶梯治疗，中重度加用生物制剂或 JAK 抑制剂；银屑病依皮损面积选择外用与系统治疗，系统用药前筛查结核、肝炎并监测肝肾与血脂。","compare":[{"diseaseId":"de_ad","dx":"反复发作的剧烈瘙痒性湿疹性皮损，好发于屈侧（婴儿面颊、儿童肘窝腘窝），伴皮肤干燥与个人或家族特应性史（哮喘、过敏性鼻炎）","key":"以瘙痒为核心，屈侧分布，个人/家族特应性背景，血嗜酸性粒细胞与 IgE 可升高"},{"diseaseId":"de_psoriasis","dx":"边界清楚的红色斑块覆银白色鳞屑，好发于伸侧（肘膝、头皮、腰骶），Auspitz 征（刮除鳞屑见点状出血）阳性，可有甲损害与关节受累","key":"伸侧分布 + 银白色厚鳞屑 + 甲点状凹陷，无特应性背景"}],"diseases":[{"id":"de_ad","name":"特应性皮炎","aka":["Atopic Dermatitis","AD","湿疹"],"rank":1,"basic":{"define":"一种慢性复发性、瘙痒性、炎症性皮肤病，常始于儿童期，与皮肤屏障功能障碍（丝聚蛋白基因突变）和 Th2 型免疫异常相关，常伴过敏性鼻炎、哮喘等特应性疾病。按年龄分为婴儿期、儿童期与成人期。","risk":["个人或家族特应性病史（哮喘、过敏性鼻炎、食物过敏）","丝聚蛋白（FLG）基因突变、皮肤屏障功能下降","婴儿期湿疹起病、早期食物过敏","环境：干燥气候、尘螨、宠物皮屑、肥皂/洗涤剂刺激","精神压力、金黄色葡萄球菌定植"],"epi":"全球儿童患病率约 10%–20%，成人约 2%–8%；我国城市儿童患病率约 12%–18%，且呈上升趋势，婴幼儿起病约占 60%。多数儿童期起病者到青少年期明显缓解，约 30% 持续至成人。"},"patho":"核心为「屏障缺陷+免疫失调+瘙痒-搔抓循环」。丝聚蛋白缺乏使角质层水合与抗微生物肽减少，过敏原与刺激物易穿透；皮肤局部 Th2 细胞因子（IL-4、IL-13）抑制屏障蛋白表达并招募嗜酸性粒细胞；IL-31 介导瘙痒；搔抓进一步破坏屏障并促炎。金葡菌定植通过分泌超抗原加重炎症。","dx":{"criteria":["Hanifin-Rajka 标准（主要标准：瘙痒 + 典型形态与分布（成人屈侧、婴儿面部）+ 慢性/复发性病程；次要标准 ≥3 项：干皮、鱼鳞病/掌纹加深、IgE 升高、个人或家族特应性史、白色划痕、Dennie-Morgan 褶等）","中国 AD 诊断标准（2019）：对称性湿疹 + 反复发作 ≥6 个月（婴儿 ≥2 个月）+ 屈侧分布或面颊/伸侧（婴儿）+ 伴瘙痒；加上特应性病史或 IgE/嗜酸性粒细胞升高支持","SCORAD 或 EASI 评估严重度：EASI <7 轻度、7–21 中度、21–50 重度、>50 极重度","瘙痒（NRS ≥4 或影响睡眠）与生活质量（DLQI/CDLQI）评分"],"workup":["皮肤检查：皮损分布、苔藓样变、渗出、继发感染（脓疱、黄痂）","SCORAD/EASI、瘙痒 NRS、睡眠与生活质量评分","血常规与嗜酸性粒细胞计数、总 IgE（辅助，非诊断必需）","过敏原检测（皮肤点刺/特异性 IgE）用于中重度或疑食物过敏者，避免盲目忌口","皮肤真菌/细菌培养（疑继发感染或难治性）","疑接触性皮炎时行斑贴试验"],"grading":"按严重度：轻度（EASI <7、瘙痒轻、影响小）、中度（EASI 7–21）、重度（EASI 21–50 或 >50 极重度）；按年龄分期：婴儿期（2 个月—2 岁）、儿童期（2–12 岁）、青少年与成人期（>12 岁）。"},"ddx":[{"name":"银屑病（de_psoriasis）","point":"与本类 de_psoriasis 的鉴别点：AD 以剧烈瘙痒、屈侧湿疹、渗出与苔藓样变为主，边界不清；银屑病为伸侧、边界清楚的红色斑块覆银白厚鳞屑，Auspitz 征阳性，瘙痒轻。"},{"name":"脂溢性皮炎","point":"皮损见于头皮、眉间、鼻唇沟、耳后与胸骨前，覆油腻性淡黄色鳞屑，瘙痒轻；婴儿期可与 AD 并存。"},{"name":"接触性皮炎","point":"有明确接触史（化妆品、金属、橡胶），皮损局限于接触部位、边界清楚，斑贴试验阳性；去除接触物后好转。"},{"name":"皮肤真菌感染（de_tinea）","point":"环状、边界清楚的鳞屑性红斑，边缘活动性脱屑与中心消退，真菌镜检阳性；AD 为对称性、无真菌证据。"},{"name":"疥疮","point":"剧烈夜间瘙痒、指缝/腕屈侧隧道样丘疹、家庭成员同时受累，镜检见疥虫或虫卵；AD 无传染性。"}],"tx":{"drug":[{"name":"氢化可的松（弱效，外用）","dose":"1% 乳膏，薄涂患处 bid；适用于婴儿、面部、颈部与间擦部位的轻度皮损，连续使用不超过 2 周/次","note":"外用糖皮质激素为一线；按部位与年龄选择强度；避免长期大面积使用以减少皮肤萎缩","renal":"遵说明书","hepatic":"遵说明书","interact":"与强效激素叠加使用增加局部与全身副作用"},{"name":"丁酸氢化可的松（中效，外用）","dose":"0.1% 乳膏，薄涂患处 bid；用于躯干四肢中度皮损，疗程 2–4 周","note":"儿童躯干可短暂使用中弱效；面部与间擦部位谨慎","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"糠酸莫米松（中强效，外用）","dose":"0.1% 乳膏，薄涂患处 qd，疗程 2–4 周；大面积>20% 体表面积时需评估","note":"适用于儿童中重度躯干四肢皮损；不建议用于面部与皱褶处长期使用","renal":"遵说明书","hepatic":"遵说明书","interact":"勿与强效激素混合使用"},{"name":"卤米松/丙酸氯倍他索（超强效，外用）","dose":"0.05% 乳膏，薄涂患处 qd–bid，仅用于成人/青少年重度增厚皮损，疗程 ≤2 周，且不与封包同时大面积使用","note":"禁止用于面部、颈部、生殖器与婴幼儿；老年人、皮肤薄处慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"大面积长期使用可致 HPA 轴抑制与激素全身效应"},{"name":"他克莫司软膏（钙调神经磷酸酶抑制剂）","dose":"0.03%（2 岁以上）或 0.1%（成人）软膏，薄涂患处 bid；面部与颈部首选","note":"用于激素不适合的部位（面部、皱褶、婴幼儿），初用可有灼热感；避免与光疗同时使用","renal":"遵说明书","hepatic":"遵说明书","interact":"CYP3A4 抑制剂（酮康唑、红霉素）可增加其血药浓度"},{"name":"吡美莫司乳膏","dose":"1% 乳膏，薄涂患处 bid；2 岁以上，用于面部与敏感部位","note":"适用于轻中度 AD，避免用于免疫受损者或继发感染皮损","renal":"遵说明书","hepatic":"遵说明书","interact":"同他克莫司，CYP3A4 相互作用"},{"name":"西替利嗪/氯雷他定（抗组胺）","dose":"西替利嗪：2–6 岁 2.5 mg qd，6–12 岁 5 mg qd，≥12 岁 10 mg qd；氯雷他定：2–12 岁（<30 kg）5 mg qd、>30 kg 10 mg qd，≥12 岁 10 mg qd","note":"抗组胺药对瘙痒作用有限，可改善合并荨麻疹/过敏性鼻炎；第一代药物可致嗜睡，儿童尽量避免","renal":"西替利嗪肾功能不全减半","hepatic":"氯雷他定肝功能不全减量","interact":"西替利嗪与中枢抑制剂合用增强嗜睡；避免与含相同成分复方药叠加"},{"name":"度普利尤单抗（IL-4Rα 单抗）","dose":"≥6 岁：首次 600 mg 皮下（2 次 300 mg），此后 300 mg q2w；6 个月—5 岁按体重 200 mg q2w 或 300 mg q4w（按说明书体重表）","note":"中重度 AD 首选生物制剂；注射部位反应与结膜炎常见；用药前筛查结核","renal":"轻中度无需调整","hepatic":"重度肝功能不全数据有限","interact":"与减毒活疫苗间隔；无明显 CYP 相互作用"},{"name":"乌帕替尼（JAK1 抑制剂）","dose":"≥12 岁且体重 ≥30 kg：15 mg qd 口服，可增至 30 mg qd（按说明书）；12–17 岁重度 AD 适用","note":"用药前筛查结核、乙肝、丙肝与带状疱疹风险；监测血脂、血常规与肝功","renal":"eGFR <30 慎用或减量","hepatic":"重度肝功能不全不推荐","interact":"与强 CYP3A4 抑制剂合用需减量；与免疫抑制剂合用增加感染风险"}],"nonDrug":["基础护理：每日 2 次足量润肤剂（至少 200–500 g/周，婴儿 150–200 g/周），洗澡水温 ≤37 ℃、5–10 min，用无皂基清洁剂","阶梯外用：轻度用弱效激素/钙调磷酸酶抑制剂；中重度用中强效激素，皮损控制后「间歇维持」（每周 2–3 次）","湿包裹疗法：难治性儿童 AD 可在激素外用后以湿润棉布/管状绷带包裹，显著减轻瘙痒与渗出","光疗（NB-UVB）：成人及 >12 岁中重度、外用治疗无效者，需排除光敏与皮肤癌风险","继发感染（金葡菌）时用莫匹罗星/夫西地酸或口服抗生素；单纯疱疹扩散（疱疹性湿疹）需抗病毒并急诊","避免诱发因素：尘螨、毛纺织品、宠物；不推荐盲目忌口（仅确诊食物过敏者）"],"life":["保持皮肤湿润与舒适，避免搔抓（剪短指甲、夜间戴棉手套）","衣物选纯棉、宽松，避免羊毛与化纤直接接触","心理干预与睡眠管理：AD 与焦虑、抑郁相关","长期随访：每 3–6 个月评估严重度，生物制剂治疗后 4–6 周评估疗效","儿童家长教育手册（洗浴、润肤、用药顺序）可显著改善依从性"]},"prog":"多数儿童期起病者在青少年期缓解，约 30% 持续至成人。规范外用治疗可使 70%–80% 患者得到控制；中重度需系统治疗。合并过敏性哮喘/鼻炎者提示「特应性进程」，需多学科管理。","refs":["中华医学会皮肤性病学分会免疫学组. 中国特应性皮炎诊疗指南（2020 版）","中国特应性皮炎诊疗指南（2019）：诊断标准与阶梯治疗","AAD/EAACI/ETFAD Guidelines for the Management of Atopic Dermatitis (2023)","中国特应性皮炎靶向与生物制剂使用规范（2022）"]},{"id":"de_psoriasis","name":"银屑病","aka":["Psoriasis","牛皮癣","寻常型银屑病"],"rank":2,"basic":{"define":"一种免疫介导的慢性复发性炎症性皮肤病，以边界清楚的红色斑块覆银白色鳞屑为特征，可累及关节（银屑病关节炎）与代谢系统。分为寻常型、脓疱型、红皮病型与关节病型。","risk":["家族史（HLA-Cw6 阳性关联）","肥胖、代谢综合征、2 型糖尿病","吸烟、饮酒、精神压力","感染（尤其链球菌咽炎诱发点滴状银屑病）","药物（β 受体阻滞剂、锂剂、抗疟药、系统激素骤停）、创伤（Koebner 现象）、HIV"],"epi":"全球患病率约 2%–3%，我国约 0.5%–1%（约 700 万–1000 万患者），北方高于南方；发病高峰 20–39 岁与 50–69 岁，男女相似。约 30% 患者合并银屑病关节炎。"},"patho":"Th17/IL-23 轴驱动的免疫异常：树突细胞激活 Th17 细胞，分泌 IL-17A、IL-22 使角质形成细胞过度增殖、角化异常，形成厚鳞屑；真皮血管扩张与炎症细胞浸润。Tc17 细胞在表皮内活跃（Koebner 现象）；IL-17 亦激活成骨细胞与滑膜成纤维细胞，参与关节侵蚀。","dx":{"criteria":["典型皮损：边界清楚的红色斑块，覆厚层银白色鳞屑，好发于头皮、肘膝伸侧、腰骶部与甲","Auspitz 征阳性：刮除鳞屑见半透明膜（薄膜现象），再刮见点状出血","甲损害：点状凹陷（顶针样）、油滴状变色、甲剥离与角化过度","PASI 评分与体表面积（BSA）评估；PASI <10 为轻中度，≥10 中重度","银屑病关节炎：外周关节炎/指趾炎/附着点炎/脊柱炎，CASPAR 标准","分型：寻常型（90%）、脓疱型（全身性/掌跖）、红皮病型（>90% BSA 泛发红斑脱屑）、关节病型"],"workup":["皮肤检查与 PASI/BSA/DLQI 评分","甲检查与关节检查（必要时行 X 线/超声/风湿科评估）","皮肤活检（不典型、难治性或疑皮肤淋巴瘤）","系统治疗前筛查：结核（胸片/IGRA）、乙肝/丙肝、HIV、血常规、肝肾功能、血脂","代谢综合征评估：血压、血糖、BMI、血脂","银屑病关节炎时查 ESR/CRP 与关节影像"],"grading":"按严重度：轻中度（PASI <10 且 BSA <10%，且不影响生活质量）、中重度（PASI ≥10 或 BSA ≥10% 或特殊部位如头皮/掌跖/生殖器/甲受累严重影响生活）；PASI 50/75/90 响应评估。"},"ddx":[{"name":"特应性皮炎（de_ad）","point":"与本类 de_ad 的鉴别点：银屑病伸侧、边界清、银白厚鳞屑、Auspitz 征阳性、瘙痒轻；AD 屈侧湿疹、剧烈瘙痒、边界不清、有特应性背景。"},{"name":"脂溢性皮炎","point":"头皮与面部油腻性淡黄鳞屑、边界不清、瘙痒轻，很少累及远隔部位；需与头皮银屑病鉴别。"},{"name":"扁平苔藓","point":"紫红色多角形扁平丘疹、Wickham 纹（表面网状白线）、黏膜常受累，瘙痒明显，皮损消退后留色素沉着。"},{"name":"体癣（de_tinea）","point":"环状、边缘活动性脱屑、中心消退，真菌镜检阳性；银屑病斑块厚鳞屑、无中心消退。"},{"name":"玫瑰糠疹、二期梅毒疹","point":"玫瑰糠疹有母斑与「圣诞树」样分布、病程自限；二期梅毒疹含掌跖受累、RPR/TPPA 阳性，需常规排查。"}],"tx":{"drug":[{"name":"卡泊三醇（维生素 D₃ 衍生物，外用）","dose":"0.005% 软膏，薄涂患处 qd–bid，每日不超过 15 g（按说明书）；与激素联合使用","note":"轻中度银屑病一线；面部与皱褶处慎用（刺激性）；避免用于钙代谢异常者","renal":"肾功能不全慎用（高钙血症风险）","hepatic":"遵说明书","interact":"与大剂量维生素 D 或钙剂合用增加高钙血症风险"},{"name":"丙酸氯倍他索（强效激素，外用）","dose":"0.05% 软膏，薄涂患处 qd–bid，≤2 周，体表面积不超过 10%","note":"适用于躯干四肢厚斑块；面部、皱褶、头皮长期使用需谨慎","renal":"遵说明书","hepatic":"遵说明书","interact":"大面积长期使用可致 HPA 轴抑制"},{"name":"他扎罗汀（外用维 A 酸）","dose":"0.05%–0.1% 凝胶，薄涂患处 qn，疗程 ≤12 周；需避光","note":"与强效激素联合可增强疗效；妊娠禁用、育龄期需避孕","renal":"遵说明书","hepatic":"遵说明书","interact":"与水杨酸制剂叠加增加刺激性；避免与其他角质剥脱剂同时大面积使用"},{"name":"甲氨蝶呤","dose":"7.5–15 mg 口服/皮下每周 1 次（最大 25 mg/周），同时补充叶酸 5 mg/周（除用药日外）；4–8 周评估疗效","note":"中重度银屑病/关节炎的系统一线；用药前筛查结核与肝炎，监测血常规、肝肾功能","renal":"eGFR <30 禁用；30–60 减量并监测","hepatic":"活动性肝病禁用；累计剂量 >3.5–4 g 或肝纤维化风险高者考虑肝活检","interact":"与 NSAIDs、青霉素类、丙磺舒合用增加 MTX 毒性；避免饮酒；与复方新诺明合用增加骨髓抑制"},{"name":"环孢素","dose":"2.5–5 mg/kg/d 分 2 次口服，疗程通常 ≤1 年；起始 2.5 mg/kg/d，疗效不佳可增至 5 mg/kg/d","note":"用于快速控制中重度或红皮病/脓疱型；监测血压、肾功能与血药浓度","renal":"肾功能不全禁用或减量；监测肌酐","hepatic":"肝功能不全慎用","interact":"与酮康唑、地尔硫䓬、维拉帕米合用升高血药浓度；避免他汀（肌病）；避免西柚汁"},{"name":"阿维 A（口服维 A 酸）","dose":"25–50 mg qd 口服，按疗效与耐受性调整，维持 10–25 mg qd","note":"脓疱型与红皮病型银屑病首选之一；强致畸，育龄女性需严格避孕 3 年；监测血脂与肝功能","renal":"遵说明书","hepatic":"肝功能不全禁用或减量","interact":"与四环素类合用增加颅内高压；与甲氨蝶呤合用增加肝毒性；避免与维生素 A 叠加"},{"name":"司库奇尤单抗（IL-17A 单抗）","dose":"300 mg 皮下注射（分 2 次 150 mg）于第 0、1、2、3、4 周，此后 300 mg q4w；部分患者可减为 150 mg q4w","note":"中重度银屑病/银屑病关节炎；用药前筛查结核；注意念珠菌感染与炎症性肠病加重","renal":"轻中度无需调整","hepatic":"重度肝功能不全数据有限","interact":"与减毒活疫苗间隔；无显著 CYP 相互作用"},{"name":"古塞奇尤单抗（IL-23 单抗）","dose":"100 mg 皮下注射于第 0、4 周，此后 100 mg q8w","note":"中重度斑块状银屑病；需筛查结核；与 IL-17 抑制剂相比感染风险较低","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用增加感染风险"},{"name":"阿普米司特（PDE4 抑制剂）","dose":"第 1 周 10 mg qd，第 2 周 20 mg bid，第 3 周 30 mg bid（每日早晨 30 mg、晚间 20 mg），第 4 周起 30 mg bid","note":"中重度银屑病/关节炎口服药，无肝肾功能监测需要；可致腹泻、恶心与情绪变化","renal":"eGFR <30 减量，30–60 慎用","hepatic":"重度肝功能不全慎用","interact":"与强 CYP3A4 诱导剂（利福平）合用降低疗效"}],"nonDrug":["外用治疗：中强效激素 + 卡泊三醇联合；头皮用含激素/卡泊三醇的凝胶或洗剂；掌跖用封包或角质剥脱剂","光疗：NB-UVB 每周 2–3 次，适用于中重度或外用无效者；PUVA 用于掌跖及泛发","系统治疗按需选择：中重度首选生物制剂（IL-17/IL-23 抑制剂）；MTX、环孢素、阿维 A 依病型选择","脓疱型/红皮病型需住院治疗，避免系统激素骤停（可致脓疱型反跳）","银屑病关节炎需风湿科联合管理，生物制剂选择可同时覆盖皮肤与关节","系统治疗前筛查与治疗中监测：结核、乙肝/丙肝、血常规、肝肾功能、血脂"],"life":["控制体重、戒烟限酒、积极治疗代谢综合征","避免诱发药物（β 受体阻滞剂、锂剂、抗疟药）与皮肤创伤","心理支持：银屑病与抑郁、焦虑相关，需评估 DLQI","长期随访：生物制剂每 3–6 个月评估疗效；每年查结核与感染评估","妊娠计划：系统治疗药物需提前停用（阿维 A 停药 3 年、MTX 停药 3 个月），生物制剂按专科意见"]},"prog":"慢性复发性，多数为轻中度、可长期控制；中重度患者心血管风险、代谢综合征与抑郁风险增加。生物制剂可使 70%–90% 患者达到 PASI 75，但停药后复发常见。","refs":["中华医学会皮肤性病学分会银屑病学组. 中国银屑病诊疗指南（2023 版）","中国银屑病生物治疗专家共识（2021）","AAD-NPF Guidelines of Care for the Management and Treatment of Psoriasis (2020)","EuroGuiDerm. Evidence and consensus based guideline for the treatment of psoriasis vulgaris (2022)"]}]},{"id":"infection","name":"皮肤感染","rank":2,"summary":"带状疱疹在皮疹 72 h 内启动足量抗病毒（肾病调整剂量）并重视疼痛治疗；皮肤真菌感染按部位分层，外用抗真菌药为主，甲癣与头癣需系统治疗，疗程按部位规定。","compare":[{"diseaseId":"de_herpes","dx":"带状疱疹：单侧沿皮节分布的簇集性水疱伴明显神经痛；单纯疱疹：口唇/生殖器等黏膜皮肤交界处成群水疱或溃疡，反复发作，病毒 PCR/Tzanck 涂片阳性","key":"呈带状皮节分布为带状疱疹；局限黏膜反复性为单纯疱疹"},{"diseaseId":"de_tinea","dx":"环状边界清楚的鳞屑性红斑，边缘活动、中心消退，真菌镜检见菌丝或孢子，培养阳性","key":"真菌镜检/培养阳性，无水疱、无神经痛"}],"diseases":[{"id":"de_herpes","name":"带状疱疹与单纯疱疹","aka":["Herpes Zoster","Shingles","Herpes Simplex","HSV"],"rank":1,"basic":{"define":"带状疱疹：水痘-带状疱疹病毒（VZV）再激活所致，沿单侧皮肤神经节分布区出现簇集水疱伴神经痛；单纯疱疹：HSV-1（口唇、面部）或 HSV-2（生殖器）感染，皮肤黏膜成群水疱、溃疡，可反复发作，可致脑炎与新生儿疱疹。","risk":["带状疱疹：年龄 ≥50 岁、免疫抑制（肿瘤、HIV、免疫抑制剂、移植）","带状疱疹：既往水痘史、未接种带状疱疹疫苗","单纯疱疹：性接触、亲吻、免疫抑制、口腔手术或日晒诱发","单纯疱疹：新生儿经产道接触、免疫缺陷、严重湿疹（疱疹性湿疹）"],"epi":"带状疱疹终生风险约 30%，我国 50 岁以上人群年发病率约 5–8/1000，随年龄上升；单纯疱疹 HSV-1 全球成人血清阳性率约 50%–90%，HSV-2 约 10%–15%，生殖器疱疹为常见性传播疾病。"},"patho":"VZV 初次感染（水痘）后潜伏于颅神经与背根神经节，免疫力下降时再激活，沿感觉神经轴突至皮肤，引起神经节炎症与皮节区水疱，神经病理性疼痛源于神经损伤与外周/中枢敏化。HSV 经皮肤黏膜破损进入，潜伏于感觉神经节，应激、紫外线、免疫抑制时再激活至皮损，复发常见于原发部位附近。","dx":{"criteria":["带状疱疹：单侧、沿一个或相邻皮节分布，红线/丘疹→簇集性水疱→结痂；典型伴剧烈烧灼样、电击样疼痛，可先于皮疹出现","带状疱疹特殊部位：三叉神经眼支（需眼科评估，警惕角膜受损）、耳部（Ramsay Hunt 综合征：面瘫+耳痛+耳道水疱）、骶部（可致尿潴留）","单纯疱疹：口唇/鼻周簇集水疱或糜烂结痂；生殖器等部位成群小水疱、溃疡伴疼痛，反复发作","实验室：Tzanck 涂片见多核巨细胞，PCR 为金标准；血清学用于既往感染判断","带状疱疹并发症：疱疹后神经痛（PHN，皮疹消退后疼痛 ≥90 d）、继发细菌感染、播散型（免疫抑制者）"],"workup":["皮损分布与神经节段记录（拍照随访）","带状疱疹：疼痛评分（NRS）、眼/耳/面神经受累检查；免疫功能评估（疑免疫缺陷）","单纯疱疹：部位、复发频率、性暴露史；孕妇妊娠期评估","病毒 PCR（水疱液/拭子）：疑难、播散或免疫抑制者","合并中枢神经系统症状（头痛、意识改变、抽搐）需行腰穿","新生儿疱疹需立即儿科/新生儿科会诊，查血/脑脊液 PCR 与肝功"],"grading":"带状疱疹按皮节分布与并发症（PHN、眼/耳受累、播散型）；单纯疱疹按部位（口唇、生殖器、眼、中枢神经系统、新生儿疱疹）与初发/复发分类。"},"ddx":[{"name":"皮肤真菌感染（de_tinea）","point":"与本类 de_tinea 的鉴别点：真菌感染呈环状红斑、边缘脱屑、真菌镜检阳性、无水疱与神经痛；带状疱疹沿皮节分布簇集水疱伴疼痛，单纯疱疹局限黏膜复发。"},{"name":"接触性皮炎、固定性药疹","point":"接触性皮炎有接触史、皮损限于接触部位；固定性药疹为圆形紫红色斑、同一部位反复发作，有用药史，无水疱沿神经分布。"},{"name":"水痘","point":"全身散发「玫瑰花瓣上的露珠」样水疱，不同阶段皮疹同时存在，始于头面部与躯干，可伴发热；带状疱疹沿皮节单侧分布。"},{"name":"带状疱疹前驱期（胸痛、腹痛）与心绞痛、胆囊炎、阑尾炎","point":"皮疹出现前易误诊，若先有皮疹出现则支持带状疱疹；必要时心电图、超声排除急腹症。"},{"name":"生殖器溃疡（梅毒、软下疳、白塞病）","point":"梅毒硬下疳无痛、质硬、单发，RPR/TPPA 阳性；软下疳疼痛明显、脓性分泌物，HSV PCR 阴性可鉴别。"}],"tx":{"drug":[{"name":"阿昔洛韦（口服）","dose":"带状疱疹：800 mg 口服，5 次/日（q4h，夜间停用），疗程 7 d（重症 10 d）；单纯疱疹初发 400 mg tid 或 200 mg 5 次/日 ×7–10 d；复发 400 mg tid ×5 d","note":"在皮疹出现 72 h 内启动获益最大；超过 72 h 但新水疱仍出现或免疫抑制者仍应使用","renal":"按 CrCl 调整：CrCl 25–50 减为 800 mg q8h，10–25 为 800 mg q12h，<10 为 800 mg q24h（带状疱疹剂量）","hepatic":"遵说明书","interact":"与丙磺舒、西咪替丁合用升高血药浓度；与肾毒性药物合用增加肾损伤"},{"name":"伐昔洛韦","dose":"带状疱疹：1000 mg 口服 tid ×7 d；单纯疱疹初发 1000 mg bid ×7–10 d；复发 500 mg bid ×3 d；生殖器疱疹抑制治疗 500 mg qd","note":"生物利用度较阿昔洛韦高 3–5 倍，依从性好；本药为前药，肾功能要求同族","renal":"CrCl 30–49：带状疱疹 1000 mg q12h；CrCl 10–29：1000 mg q24h；<10 或透析按说明书减量","hepatic":"遵说明书","interact":"与肾毒性药物合用增加风险；与丙磺舒增加血药浓度"},{"name":"泛昔洛韦","dose":"带状疱疹：500 mg 口服 tid ×7 d；单纯疱疹初发 250 mg tid ×7–10 d；复发 125 mg bid ×5 d","note":"依从性好，可与食物同服","renal":"CrCl 20–39：减量为隔日或减半；<20 按说明书","hepatic":"遵说明书","interact":"与丙磺舒合用增加血药浓度"},{"name":"阿昔洛韦（静脉，重症）","dose":"10 mg/kg 静脉滴注 q8h（按体重与肾功能调整），用于播散型、中枢神经系统受累、免疫抑制或无法口服者，疗程 7–21 d","note":"需充分水化（输液维持尿量），避免快速推注（肾小管结晶）","renal":"按 CrCl 调整：CrCl 25–50 10 mg/kg q12h，10–25 q24h，<10 减半；血透后补充","hepatic":"遵说明书","interact":"与肾毒性药物（两性霉素 B、氨基糖苷类）合用增加肾损害"},{"name":"膦甲酸/伐更昔洛韦（耐阿昔洛韦的 HSV/VZV）","dose":"膦甲酸 40 mg/kg 静脉滴注 q8h（按肾功能调整）；伐更昔洛韦按专科方案口服 900 mg bid","note":"仅用于确认耐药或免疫抑制患者；需监测肾功能与电解质（膦甲酸致低钙、低镁）","renal":"按 CrCl 严格减量","hepatic":"遵说明书","interact":"膦甲酸与肾毒性药物合用增加肾损害；与戊烷脒合用致严重低钙"},{"name":"加巴喷丁（带状疱疹后神经痛）","dose":"起始 300 mg qn，逐渐增至 300 mg tid 或 600 mg tid（最大 3600 mg/d），肾功能不全减量","note":"用于 PHN 与急性期神经痛；嗜睡与眩晕常见，需逐渐滴定","renal":"CrCl 30–59 减量至 200–700 mg bid，CrCl 15–29 200–700 mg qd","hepatic":"遵说明书","interact":"与阿片类合用增加呼吸抑制（尤其老年人）；与含铝/镁抗酸剂间隔 2 h"},{"name":"普瑞巴林（带状疱疹后神经痛）","dose":"起始 75 mg bid，可逐渐增至 150 mg bid（最大 600 mg/d）；肾功能不全减量","note":"对 PHN 的循证证据充分；注意头晕、水肿与滥用潜力","renal":"CrCl 30–60 75–150 mg/d 分 2–3 次，CrCl 15–29 25–50 mg/d","hepatic":"遵说明书","interact":"与阿片类、苯二氮䓬类合用增加呼吸抑制与嗜睡"},{"name":"对乙酰氨基酚（单纯疱疹疼痛）","dose":"对乙酰氨基酚 500–1000 mg q6h（最大 3–4 g/d）","note":"用于单纯疱疹疼痛缓解，不影响病毒排出与复发","renal":"肾功能不全减量","hepatic":"肝功能不全时减量","interact":"与酶诱导剂合用增加肝毒性"}],"nonDrug":["保持皮损清洁干燥，避免弄破水疱；可外用炉甘石或生理盐水湿敷","眼部带状疱疹（鼻尖或眼睑受累）立即眼科会诊，全身抗病毒 + 局部激素/抗病毒眼药水","Ramsay Hunt 综合征：抗病毒+糖皮质激素，面神经减压可能，尽早耳鼻喉科评估","预防接种：重组带状疱疹疫苗（RZV，50 岁及以上或 ≥18 岁免疫抑制者 2 剂，间隔 2–6 个月）","单纯疱疹复发抑制治疗：复发 ≥6 次/年者伐昔洛韦 500 mg qd 或阿昔洛韦 400 mg bid，持续 6–12 个月","孕妇生殖器疱疹：分娩时活动性皮损或前驱症状需剖宫产；孕 36 周起伐昔洛韦 500 mg bid 抑制治疗"],"life":["避免接触孕妇、免疫功能低下者与新生儿（尤其皮损未结痂前）","PHN 随访：疼痛评估与阶梯镇痛，必要时疼痛科联合治疗","带状疱疹后 30 d 内如出现持续疼痛、睡眠障碍需调整镇痛方案","单纯疱疹患者告知伴侣与使用安全套，减少传播","心理支持：生殖器疱疹与病耻感、抑郁相关"]},"prog":"带状疱疹皮疹 2–4 周愈合；50 岁以上患者 PHN 发生率约 20%–30%，80 岁以上可达 50%。早期抗病毒（72 h 内）缩短病程并降低 PHN 风险。单纯疱疹初发 2–3 周自愈，复发频率个体差异大；新生儿疱疹与 HSV 脑炎未治疗病死率 >50%。","refs":["中华医学会皮肤性病学分会. 带状疱疹中国专家共识（2018，2022 更新）","中华医学会皮肤性病学分会性病学组. 生殖器疱疹诊疗指南（2020）","IDSA. 2021 Guidance on the Treatment of Genital Herpes","CDC. Sexually Transmitted Infections Treatment Guidelines (2021)"]},{"id":"de_tinea","name":"皮肤真菌感染","aka":["Tinea","Dermatophytosis","体癣","足癣","股癣","头癣","甲癣"],"rank":2,"basic":{"define":"皮肤癣菌（毛癣菌、小孢子菌、表皮癣菌）侵犯角质层、毛发或甲板所致的浅表真菌感染，按部位分为体癣、股癣、足癣、手癣、头癣与甲癣（灰指甲）。","risk":["温暖潮湿环境、足部多汗、穿不透气鞋袜","共用毛巾、拖鞋、浴池；游泳池与健身房","糖尿病、肥胖、免疫抑制（HIV、移植、激素）","宠物（犬小孢子菌致头癣）与儿童集体生活","既往真菌感染史、长期局部激素使用（激素癣）"],"epi":"浅表真菌感染是最常见的皮肤感染之一，足癣在成人中患病率约 20%–30%，甲癣约 5%–10%（老年人更高）；头癣多见于学龄前儿童，我国儿童头癣以犬小孢子菌与紫色毛癣菌为主。"},"patho":"皮肤癣菌分泌角蛋白酶，分解角蛋白获取营养，定居于角质层最外层（体股足癣）、毛囊（头癣）或甲板（甲癣）。真菌代谢产物与宿主免疫反应引起红斑、脱屑与瘙痒；毛发感染可致断发与毛囊破坏（脓癣）。角质层增厚与局部免疫抑制（激素）使感染迁延。","dx":{"criteria":["体癣/股癣：环状边界清楚的红斑，边缘活动性脱屑与丘疹、中心消退（「环状红斑」），股癣累及腹股沟与臀部","足癣：趾间浸渍脱屑（间擦型）、足底厚层鳞屑（角化型）、水疱（水疱型），常单侧或双足；伴甲受累者多","头癣：断发、脱发斑、鳞屑；黑点癣（毛内型）、白癣（毛外型）或脓癣（继发炎症）","甲癣：甲板增厚、变色（黄白/灰褐）、脆裂与甲床分离，甲远端或全甲受累","真菌学检查：10%–20% KOH 镜检见分隔菌丝（皮肤）或孢子（毛发/甲）；培养可鉴定菌种","伍德灯：部分头癣（犬小孢子菌）呈亮绿色荧光"],"workup":["皮损检查与拍照记录（边界、活动边缘）","KOH 镜检（首选，快速）；必要时真菌培养（治前、难治病例）","头癣：毛发镜检与培养、伍德灯；儿童需查家庭成员与宠物","甲癣：甲屑镜检与培养，必要时甲病理 PAS 染色（鉴别甲银屑病）","疑激素癣：停用外用激素 2–4 周后复检","糖尿病/免疫抑制者评估基础疾病"],"grading":"按部位分类（体、股、足、手、头、甲癣）；足癣分型：间擦型、水疱型、角化型；甲癣按受累范围（远端侧位、近端、全甲毁损）与病原分型（皮肤癣菌/非皮肤癣菌霉菌/酵母菌）。"},"ddx":[{"name":"带状疱疹与单纯疱疹（de_herpes）","point":"与本类 de_herpes 的鉴别点：真菌感染无簇集水疱、无神经痛与皮节分布，真菌镜检阳性；疱疹有疼痛性水疱群与病毒 PCR 证据。"},{"name":"银屑病（de_psoriasis）","point":"与本类 de_psoriasis 的鉴别点：银屑病厚层银白鳞屑、Auspitz 征阳性、伸侧对称分布，真菌检查阴性；体癣为环状中心消退、边缘活动。"},{"name":"湿疹/接触性皮炎","point":"对称性、边界不清、渗出与苔藓样变，无中心消退，真菌镜检阴性；激素癣使用激素后呈「边界不清的加重」需警惕。"},{"name":"玫瑰糠疹、二期梅毒疹、红斑狼疮","point":"玫瑰糠疹有母斑与沿皮纹分布；二期梅毒掌跖受累、RPR/TPPA 阳性；红斑狼疮面部蝶形红斑，无环状活动边缘。"},{"name":"甲银屑病、甲扁平苔藓","point":"甲板点状凹陷、油滴状改变，真菌检查阴性；甲癣甲增厚变色、甲屑镜检阳性可鉴别。"}],"tx":{"drug":[{"name":"特比萘芬乳膏（外用）","dose":"1% 乳膏或溶液，薄涂患处 qd–bid，疗程 2–4 周（角化型足癣可延长至 4 周）","note":"对皮肤癣菌杀菌作用强，一线外用；症状消退后继续 1 周以减少复发","renal":"遵说明书","hepatic":"遵说明书","interact":"外用吸收少，药物相互作用罕见"},{"name":"联苯苄唑/酮康唑乳膏（外用）","dose":"1%–2% 乳膏，薄涂患处 qd（联苯苄唑）或 qd–bid（酮康唑），疗程 2–4 周","note":"广谱抗真菌，适用于体股癣与足癣；面部与皱褶处避免与强效激素混用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"特比萘芬（口服）","dose":"成人 250 mg qd；体重 <20 kg 62.5 mg qd，20–40 kg 125 mg qd，>40 kg 250 mg qd；头癣疗程 4 周，甲癣手指甲 6 周、趾甲 12 周","note":"甲癣系统治疗首选之一；用药前查肝功能，治疗 4–6 周复查","renal":"CrCl <50 减量为 250 mg q48h（或减半剂量）","hepatic":"活动性肝病禁用；既往肝损伤者慎用，治疗中监测转氨酶","interact":"口服吸收对 CYP2D6 的抑制可使三环类、某些 β 阻滞剂浓度升高；利福平降低其浓度；避免大量饮酒"},{"name":"伊曲康唑（口服，脉冲方案）","dose":"甲癣：200 mg bid ×1 周为一疗程，手指甲 2 个疗程、趾甲 3 个疗程（每疗程间隔 3 周）；头癣：3–5 mg/kg/d 分 1–2 次 ×4–6 周","note":"对念珠菌与部分霉菌也有效；胶囊需餐后服（酸性环境吸收），口服液空腹","renal":"CrCl <30 禁用静脉制剂；胶囊慎用","hepatic":"肝功能不全慎用；治疗期间监测肝功","interact":"强 CYP3A4 抑制剂，可致尖端扭转型室速（与胺碘酮、西沙必利等合用禁忌）；与华法林、地高辛、他汀合用需调整；避免西柚汁"},{"name":"灰黄霉素（头癣，儿童）","dose":"10–20 mg/kg/d 分 1–2 次口服（餐后服，最大 1 g/d），疗程 6–8 周","note":"对头癣疗效确切，尤其毛癣菌所致者；我国部分中心以伊曲康唑或特比萘芬替代","renal":"肾功能不全慎用","hepatic":"严重肝功能不全禁用","interact":"与华法林、口服避孕药、巴比妥类合用降低疗效；避免饮酒"},{"name":"阿莫罗芬甲涂剂（外用，甲癣）","dose":"5% 甲涂剂涂抹于受累甲板，每周 1–2 次；手指甲最长 6 个月，趾甲最长 12 个月；另有 8% 环吡酮胺甲涂剂 qd 方案","note":"适用于轻度远端甲癣或不能口服者；需定期削薄甲板","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"酮康唑洗剂（头癣/伴马拉色菌）","dose":"2% 酮康唑洗剂涂于头皮与毛发，停留 5 min 后冲洗，2 次/周 ×2–4 周；或 2.5% 二硫化硒洗剂","note":"头癣需联合系统抗真菌与剪发、洗头；洗剂仅辅助减少孢子传播","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["体股癣与足癣：外用抗真菌药为主，保持患处干爽，勤换袜、穿透气鞋","头癣：口服抗真菌 + 剪短头发（每周剪发）、每周 2 次洗头（抗真菌洗剂）、家庭成员与宠物筛查；疗程需完整，避免过早停药","甲癣：远端侧位甲受累可单独外用；近端或全甲受累建议口服；长期疗程需依从性管理","激素癣：停用外用激素，按真菌感染治疗，避免复发","预防：避免共用毛巾、拖鞋；公共浴池穿拖鞋；糖尿病患者足部护理","足癣与甲癣并发时同时治疗，减少复发"],"life":["保持皮肤干燥，沐浴后彻底擦干趾间与腹股沟","勤换袜（棉质或吸湿排汗），鞋交替穿着并通风；可用足部抗真菌粉","治疗结束后 4 周复诊评估（甲癣需更长时间随访）","家庭成员同患足癣/甲癣应同时治疗","糖尿病患者注意足癣与甲癣可致皮肤破损与感染风险"]},"prog":"外用治疗体股癣 1–2 周可明显好转；足癣需 2–4 周且复发率高（尤角化型）；甲癣口服特比萘芬趾甲治愈率约 70%–80%，伊曲康唑脉冲约 60%–70%，复发率 10%–20%。头癣规范治疗可痊愈，脓癣可留瘢痕性脱发。","refs":["中华医学会皮肤性病学分会真菌学组. 中国皮肤真菌病诊疗指南（2022 版）","中国头癣诊疗指南（2019）","BAD Guideline for the management of tinea capitis (2014, updated 2022)","IDSA Clinical Practice Guideline for the Treatment of Dermatophyte Infections (2014)"]}]},{"id":"severe_drug","name":"重症药疹与皮肤肿瘤","rank":3,"summary":"SJS/TEN 为皮肤科最危重的药物反应，核心是立即停用可疑药物、转 ICU/烧伤单元、按 SCORTEN 评估预后并尽早使用系统激素/IVIG/环孢素；荨麻疹以第二代抗组胺药为主，伴气道症状需肾上腺素；基底细胞癌以手术切除（莫氏）为主要治愈手段。","compare":[{"diseaseId":"de_sjs","dx":"用药（多为别嘌醇、卡马西平、复方新诺明、NSAIDs）后 1–3 周出现发热、皮肤疼痛、靶形非典型红斑与黏膜糜烂，表皮剥脱面积 <10% 为 SJS、10%–30% 为 SJS/TEN 重叠、>30% 为 TEN（Nikolsky 征阳性）","key":"全身皮肤疼痛 + 黏膜受累 + 表皮坏死剥脱，Nikolsky 征阳性"},{"diseaseId":"de_urticaria","dx":"风团与（或）血管性水肿，单个风团 <24 h 消退且不留痕迹，剧痒；急性 <6 周，慢性 ≥6 周","key":"一过性、可消退的风团，无表皮剥脱、无水疱与全身皮肤疼痛"},{"diseaseId":"de_bcc","dx":"日光暴露部位（面、鼻、耳）出现珍珠样结节或红斑，表面毛细血管扩张、中央溃疡或结痂，缓慢生长，皮肤镜见树枝状血管","key":"慢性缓慢生长的无痛性结节/溃疡，无明显全身症状"}],"diseases":[{"id":"de_sjs","name":"史蒂文斯-约翰逊综合征与中毒性表皮坏死松解症","aka":["SJS","TEN","Stevens-Johnson Syndrome","Toxic Epidermal Necrolysis","重症多形红斑"],"rank":1,"basic":{"define":"一种由药物（少数为感染或免疫相关）触发的严重皮肤黏膜坏死性反应，表现为广泛非典型靶形红斑、表皮坏死剥脱与黏膜糜烂。表皮剥脱面积 <10% 体表面积为 SJS，10%–30% 为 SJS/TEN 重叠，>30% 为 TEN。病死率 SJS 约 5%，TEN 约 30%。","risk":["药物：别嘌醇、卡马西平/拉莫三嗪/苯妥英、复方新诺明等磺胺类、NSAIDs（美洛昔康、吡罗昔康）、抗生素（头孢、喹诺酮）","HLA-B*15:02（卡马西平）、HLA-B*58:01（别嘌醇）等遗传易感","年龄 >40 岁、HIV 感染、免疫抑制与肿瘤","用药后 1–3 周（初次）或数小时–数天（再次暴露）","既往药疹史"],"epi":"全球年发病率约 1–2/百万（SJS）与 0.4–1.5/百万（TEN），我国以别嘌醇与卡马西平相关者常见。SJS/TEN 死亡主要因脓毒症、多器官衰竭与液体丢失；SCORTEN 评分预测病死率。"},"patho":"药物或其代谢物（如别嘌醇代谢产物、卡马西平活性环氧化物）作为抗原激活药物特异性 CD8⁺ T 细胞，释放 FasL、颗粒酶 B 与穿孔素，诱导角质形成细胞凋亡，形成广泛表皮坏死。MHC I 限制的杀伤性 T 细胞反应与遗传背景（HLA 等位基因）决定易感性。表皮屏障破坏导致大量体液丢失、体温调节障碍与感染风险，类似大面积烧伤。","dx":{"criteria":["用药后 1–3 周（或再次暴露后 1–3 d）出现发热、全身皮肤疼痛、灼热感，继之出现非典型靶形红斑、紫癜样斑片与水疱","黏膜受累 ≥2 个部位（眼、口腔、生殖器、肛门），多为糜烂、出血性结痂","Nikolsky 征阳性：推压似正常皮肤可致表皮剥脱；表皮剥脱面积决定分型（<10% SJS，10%–30% 重叠，>30% TEN）","SCORTEN 评分（入院 24 h 内计算 7 项）：年龄 ≥40 岁、心率 ≥120 次/分、肿瘤史、表皮剥脱 >10%、尿素氮 >10 mmol/L、血糖 >14 mmol/L、碳酸氢盐 <20 mmol/L；0–1 分病死率约 3%，≥5 分约 40%–90%","需早期识别「药疹 + 严重疼痛 + 黏膜受累」并停用可疑药"],"workup":["每日评估体表面积剥脱百分比、体重、体液平衡与体温","皮肤活检：全层表皮坏死、基底细胞空泡化、界面淋巴细胞浸润，可助确诊（不延误治疗）","血常规、电解质、肾功能、肝功能、血糖、血气、白蛋白","血培养与皮肤创面培养（警惕脓毒症：金葡菌、铜绿假单胞菌）","眼科会诊（裂隙灯查角膜与结膜）与泌尿生殖科评估","胸部 X 片/CT（肺炎、肺水肿）；心电图（电解质紊乱致心律失常）"],"grading":"按表皮剥脱面积分型：SJS（<10%）、SJS/TEN 重叠（10%–30%）、TEN（>30%）；SCORTEN 评分预测病死率；并发器官受累（肝、肾、肺、血液、消化道）需单独记录。"},"ddx":[{"name":"荨麻疹（de_urticaria）","point":"与本类 de_urticaria 的鉴别点：SJS/TEN 有表皮坏死剥脱、Nikolsky 征阳性、黏膜糜烂与全身中毒症状；荨麻疹为速发风团，单个 <24 h 消退、无表皮剥脱与黏膜坏死。"},{"name":"基底细胞癌（de_bcc）","point":"与本类 de_bcc 的鉴别点：SJS/TEN 为急性发作的全身性皮肤急症，BCC 为慢性局部肿瘤，无黏膜与全身受累。"},{"name":"多形红斑（EM major）","point":"典型靶形红斑（三区带）以肢端为主，黏膜受累较轻，多为单纯疱疹诱发，表皮剥脱 <10%，全身状态好。"},{"name":"金黄色葡萄球菌烫伤样皮肤综合征（SSSS）","point":"多见于 <5 岁儿童，口周放射状皲裂、无黏膜明显糜烂、尼氏征阳性但浅层剥脱，金葡菌培养阳性；需与 TEN 鉴别。"},{"name":"中毒性休克综合征（TSS）、DRESS 综合征","point":"TSS 有低血压、弥漫性红斑与皮肤脱屑、血培养阳性；DRESS 有嗜酸性粒细胞增多症、淋巴结肿大与内脏受累，病程较缓。"}],"tx":{"drug":[{"name":"立即停用可疑药物与同类药物","dose":"停用所有非必需药物，尤其可疑致敏药（按用药时间表排序判断）；必要时查 HLA 等位基因预测风险","note":"停用越早预后越好；不应为等待确诊而延迟停药","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"甲泼尼龙（系统糖皮质激素）","dose":"1–2 mg/kg/d 静脉或口服起始，2–3 d 后根据病情减量，逐渐减停（疗程约 2–4 周）；部分中心采用大剂量冲击（500–1000 mg/d ×3 d），证据有限且感染风险增加","note":"国内指南多主张早期使用，但国际循证证据仍有争议；需权衡感染与创面愈合；避免快速停药致反跳","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道出血；与利尿剂合用低钾；合并感染时需抗感染覆盖"},{"name":"静脉免疫球蛋白（IVIG）","dose":"0.5–1 g/kg/d 静脉滴注 ×3–4 d（总量 2–3 g/kg），在发病早期（72 h 内）使用可能更有效","note":"通过阻断 Fas-FasL 介导的角质细胞凋亡发挥治疗作用，证据有限；需监测肾功能、血栓与过敏","renal":"肾功能不全时注意渗透性肾病与容量负荷","hepatic":"遵说明书","interact":"与减毒活疫苗间隔；与其他免疫抑制剂联用增加感染风险"},{"name":"环孢素","dose":"3–5 mg/kg/d 口服或静脉分 2 次，疗程 7–14 d，之后可减量","note":"近年研究显示可降低表皮剥脱进展与病死率；需监测血压、肾功能与血药浓度","renal":"肾功能不全减量并监测肌酐","hepatic":"肝功能不全减量","interact":"与酮康唑、地尔硫䓬、维拉帕米合用升高血药浓度；避免西柚汁与他汀（肌病）；与 MTX 合用增加毒性"},{"name":"依那西普/环磷酰胺（选择性重症，专科）","dose":"依那西普 50 mg 皮下单次；环磷酰胺 1–2 mg/kg/d 口服或静脉，按专科方案","note":"证据有限，仅用于重症 TEN 或激素无效者，需在专科条件与知情同意下使用","renal":"环磷酰胺肾功能不全减量","hepatic":"环磷酰胺严重肝功能不全禁用","interact":"与免疫抑制剂合用增加感染；环磷酰胺致出血性膀胱炎需水化"},{"name":"对乙酰氨基酚（镇痛与退热）","dose":"500–1000 mg 口服/静脉 q6h（最大 3–4 g/d）；避免使用 NSAIDs 与阿司匹林（可能加重病情）","note":"皮肤疼痛剧烈，需阿片类（吗啡/芬太尼）与对乙酰氨基酚联合镇痛","renal":"肾功能不全减量","hepatic":"肝功能不全时减量（SJS/TEN 常伴肝损）","interact":"与酶诱导剂合用增加肝毒性"},{"name":"吗啡/芬太尼（镇痛）","dose":"吗啡静脉滴定 2–5 mg q1–2h，按疼痛评分调整（老年/肾功能不全减量）；芬太尼透皮贴 12–25 µg/h 用于稳定疼痛","note":"用于剧烈皮肤疼痛；需监测呼吸与意识","renal":"肾功能不全时吗啡代谢物蓄积，改用芬太尼或谨慎减量","hepatic":"严重肝功能不全减量","interact":"与苯二氮䓬类合用增加呼吸抑制"},{"name":"预防性抗感染（按创面情况）","dose":"不推荐常规预防性使用；疑脓毒症或大面积创面者按创面培养选择，如哌拉西林他唑巴坦 4.5 g q6–8h 静脉，或万古霉素 15–20 mg/kg q8–12h（按体重与肾功能）","note":"需按培养与药敏调整，避免经验性过度使用","renal":"按 CrCl 调整剂量","hepatic":"遵说明书","interact":"万古霉素与氨基糖苷类/利尿剂合用增加肾毒性；哌拉西林他唑巴坦与华法林合用增加出血"}],"nonDrug":["转入烧伤单元或皮肤科重症监护病房（ICU），按大面积烧伤管理：每日创面评估、换药与清创","液体与电解质管理：按 Parkland 公式（4 mL×体重 kg×剥脱体表面积百分比，前 8 h 输入一半）评估晶体液需求，以尿量 0.5–1 mL/kg/h 为目标","体温管理：维持室温 30–32 ℃，减少热量丢失；营养支持（早期肠内营养）","眼科每日评估：人工泪液与润滑剂、局部激素与抗生素点眼，防止睑球粘连与角膜穿孔","口腔与会阴部护理：氯己定漱口、局部镇痛与防粘连；女性阴道模具防止粘连","避免粘贴性敷料与辅助粘贴物（加重皮肤剥脱）；使用非粘贴性敷料（如生物敷料、硅胶敷料）","停用可疑药物并记录于病历，再次用药需标注禁忌"],"life":["长期随访：眼干、畏光、睑球粘连，口腔与食管狭窄、生殖器粘连，色素改变与瘢痕","心理支持与瘙痒/神经病理性疼痛管理","药物过敏记录与书面禁忌卡；HLA-B*58:01（别嘌醇）、HLA-B*15:02（卡马西平）筛查","SCORTEN 高分患者出院后 1 年内病死与再入院风险高，需密切随访","避免再次使用同类结构药物（如其他芳香族抗癫痫药）"]},"prog":"SJS 病死率约 5%，TEN 约 30%（高龄、多器官受累者更高）。多数存活者急性期 2–3 周后开始上皮再生，但遗留眼、黏膜与皮肤后遗症，约 50% 患者有长期眼部并发症。早期停药、ICU 支持与眼科管理显著改善预后。","refs":["中华医学会皮肤性病学分会. 重症多形红斑/中毒性表皮坏死松解型药疹诊疗专家共识（2019，2023 更新）","SJS/TEN Work Group. Guidelines for the Management of Stevens-Johnson Syndrome/Toxic Epidermal Necrolysis (2016, updated 2022)","Bastuji-Garin S, et al. SCORTEN: a severity-of-illness score for toxic epidermal necrolysis. J Invest Dermatol 2000","EuroSCAR Study Group. Medication use and the risk of SJS/TEN (2008)"]},{"id":"de_urticaria","name":"荨麻疹","aka":["Urticaria","Hives","风疹块"],"rank":2,"basic":{"define":"由于皮肤肥大细胞释放组胺等介质引起的局限性、一过性水肿性风团与（或）血管性水肿，单个风团通常在 24 h 内消退且不留痕迹。急性荨麻疹 <6 周，慢性荨麻疹（CSU）≥6 周。","risk":["食物（海鲜、坚果、蛋奶）与食品添加剂","药物（青霉素、NSAIDs、阿司匹林、造影剂）","感染（病毒、细菌、寄生虫，儿童急性荨麻疹多与病毒相关）","物理刺激（冷、热、压力、日光、运动）、昆虫叮咬","慢性自发型：自身免疫（甲状腺抗体、抗 IgE 受体抗体）、幽门螺杆菌感染"],"epi":"约 15%–25% 的人一生中至少发生一次急性荨麻疹；慢性荨麻疹患病率约 0.5%–1%，女性多于男性，以 20–40 岁为主。我国慢性荨麻疹患者中约 50% 伴血管性水肿。"},"patho":"肥大细胞激活后脱颗粒，释放组胺、白三烯、血小板活化因子等，引起真皮浅层血管扩张与通透性增加（风团）、皮下或黏膜深层水肿（血管性水肿）。慢性荨麻疹多与自身免疫机制相关：IgG 抗 FcεRI 抗体或抗 IgE 抗体使肥大细胞持续活化；部分患者存在甲状腺自身抗体。物理性荨麻疹由体温、压力等直接激活肥大细胞。","dx":{"criteria":["典型风团：大小不一、边界清楚的隆起性红色或肤色斑块，伴剧痒，单个风团 <24 h 消退、不留痕迹","血管性水肿：眼睑、口唇、舌、手足与生殖器无痛性肿胀，可伴气道受累（喉头水肿：声嘶、呼吸困难）","皮肤划痕征（Dermographism）：推划皮肤后 1–5 min 出现红色线条与风团，提示物理性荨麻疹","急性荨麻疹：寻找诱因（食物、药物、感染）；慢性荨麻疹：系统病史与实验室筛查（血常规、CRP、甲状腺抗体、幽门螺杆菌）","需排除荨麻疹性血管炎（单个风团 >24 h、消退后留色素沉着、可伴发热与关节痛）"],"workup":["详细病史：发作频率、持续时间、诱因、药物与食物、物理因素、感染与自身免疫病史","皮肤检查与拍照；血管性水肿部位与气道评估","血常规、CRP/ESR、肝功能、甲状腺抗体（慢性 CSU）","过敏原特异性 IgE（疑食物/药物过敏）","皮肤活检（疑荨麻疹性血管炎： >24 h 不消退、留色素沉着）","必要时补体 C4/C1 抑制剂（遗传性血管性水肿伴反复不典型血管性水肿、无风团）"],"grading":"按病程：急性（<6 周）、慢性（≥6 周）；按类型：慢性自发型、诱导型（物理性：皮肤划痕、寒冷、胆碱能、压力、日光）、特殊类型（荨麻疹性血管炎）；按严重度：UAS7 评分（0–42，>15 为重度）。"},"ddx":[{"name":"SJS/TEN（de_sjs）","point":"与本类 de_sjs 的鉴别点：SJS/TEN 有表皮坏死剥脱、Nikolsky 征阳性、黏膜糜烂与全身中毒；荨麻疹为风团、单个 <24 h 消退、无表皮坏死。"},{"name":"基底细胞癌（de_bcc）","point":"与本类 de_bcc 的鉴别点：荨麻疹为急性一过性风团，BCC 为慢性局部结节/溃疡，无风团与血管性水肿。"},{"name":"遗传性/获得性血管性水肿（C1 抑制剂缺乏）","point":"反复发作的非凹陷性水肿、无风团，可伴腹痛，抗组胺与肾上腺素反应差，补体 C4 降低；需与荨麻疹性血管性水肿鉴别。"},{"name":"荨麻疹性血管炎","point":"单个风团持续 >24 h、消退后留色素沉着或紫癜，可伴发热、关节痛，活检见白细胞碎裂性血管炎；与普通荨麻疹鉴别。"},{"name":"过敏性接触性皮炎、药疹（斑丘疹型）","point":"皮疹持续数天、固定部位、可伴脱屑，无风团的一过性特征；需通过皮损形态与病史鉴别。"}],"tx":{"drug":[{"name":"西替利嗪（第二代抗组胺）","dose":"成人及 >12 岁 10 mg qd；6–11 岁 5–10 mg qd；2–5 岁 2.5 mg qd（最大 5 mg/d），肾功能不全减半","note":"一线；慢性荨麻疹可标准剂量加倍（最高 4 倍）以控制症状","renal":"CrCl 30–49 减量为标准剂量隔日；<30 或透析按说明书","hepatic":"肝功能不全减半","interact":"与中枢抑制剂合用增加嗜睡；避免与酒精同用"},{"name":"氯雷他定","dose":"成人及 >6 岁 10 mg qd；2–6 岁（<30 kg）5 mg qd","note":"第二代抗组胺，嗜睡少；慢性荨麻疹可加量至 20 mg qd（超说明书）","renal":"肾功能不全减量（隔日）","hepatic":"肝功能不全减量","interact":"与酮康唑、红霉素合用增加血药浓度（常规剂量安全范围宽）"},{"name":"比拉斯汀/非索非那定（替代第二代）","dose":"比拉斯汀 20 mg qd（≥12 岁）；非索非那定 180 mg qd 或 60 mg bid（成人/≥12 岁）","note":"非索非那定的嗜睡更少；不能与果汁同服（降低吸收）","renal":"非索非那定 CrCl <40 起始 60 mg qd","hepatic":"肝功能不全慎用","interact":"非索非那定与含铝镁抗酸剂间隔 2 h；避免与果汁同服"},{"name":"肾上腺素（急性严重过敏/喉头水肿）","dose":"Epinephrine 1:1000（1 mg/mL）0.3–0.5 mg 肌注于大腿前外侧，必要时 5–15 min 重复；儿童 0.01 mg/kg（最大 0.3–0.5 mg）肌注","note":"伴气道受累（喉头水肿、喘鸣、呼吸困难）或过敏性休克时立即使用；抗组胺不能替代","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂合用减弱反应；与三环类抗抑郁药合用可致高血压"},{"name":"泼尼松（短期，急性重症）","dose":"0.5–1 mg/kg/d（最大 40–60 mg/d）口服 3–5 d，短期使用；不推荐长期用于慢性荨麻疹","note":"用于急性严重发作或抗组胺无效的短期控制，不作为常规维持","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道溃疡；与降糖药合用升高血糖"},{"name":"奥马珠单抗（慢性荨麻疹三线）","dose":"300 mg 皮下注射 q4w（可缩短至 q2w 或增至 600 mg 按需）；≥12 岁 H1 抗组胺（最高 4 倍剂量）治疗 2–4 周无效者","note":"慢性自发型荨麻疹疗效确切；约 30%–40% 需加用免疫抑制剂","renal":"遵说明书","hepatic":"遵说明书","interact":"与减毒活疫苗间隔；无明显 CYP 相互作用"},{"name":"环孢素（慢性难治性荨麻疹）","dose":"2.5–5 mg/kg/d 分 2 次口服，3–6 个月后评估，逐渐减量","note":"用于奥马珠单抗无效或不耐受者；监测血压、肾功能与血药浓度","renal":"肾功能不全禁用或减量；监测肌酐","hepatic":"肝功能不全慎用","interact":"与酮康唑、地尔硫䓬、维拉帕米合用升高血药浓度；避免他汀与西柚汁"},{"name":"孟鲁司特（辅助，慢性荨麻疹）","dose":"10 mg qn 口服（成人与 ≥15 岁）；6–14 岁 5 mg qn","note":"可减少部分患者风团，作为抗组胺的辅助；注意神经精神不良反应","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与苯巴比妥等酶诱导剂合用降低血药浓度"}],"nonDrug":["急性发作：冷水/冷敷减轻瘙痒，避免搔抓与热水烫洗","慢性荨麻疹阶梯治疗：第二代 H1 抗组胺标准剂量 → 加倍至 4 倍 → 加用奥马珠单抗 → 环孢素/免疫调节","诱因管理：避免 NSAIDs、阿司匹林、可待因、造影剂（过敏史者）；物理性荨麻疹针对诱因防护","疑过敏原者进行过敏原检测与回避；急性荨麻疹伴呼吸道症状立即肾上腺素并呼叫急救","慢性荨麻疹无需常规「忌口」；饮食日记用于个别疑食物过敏者","伴血管性水肿反复发作且家族史者查补体除外遗传性血管性水肿"],"life":["慢性荨麻疹需长期管理，多数患者 1–5 年内缓解","心理支持与睡眠管理：CSU 与焦虑、抑郁相关","避免饮酒与剧烈温度变化","随身携带肾上腺素自动注射器（过敏性休克史者），并教会患者与家属使用","妊娠期荨麻疹首选西替利嗪/氯雷他定，避免奥马珠单抗（数据有限）"]},"prog":"急性荨麻疹多数 1–2 周内缓解，部分转为慢性；慢性自发型荨麻疹约 50% 在 1 年内症状改善，约 20% 持续 5 年以上。气道受累（喉头水肿）与过敏性休克是最危险的并发症，需立即肾上腺素处理。","refs":["中华医学会皮肤性病学分会. 中国荨麻疹诊疗指南（2022 版）","EAACI/GA²LEN/EDF/WAO Guideline for the Definition, Classification, Diagnosis and Management of Urticaria (2021/2022)","中国慢性荨麻疹诊疗指南（2014）","AAAAI. Anaphylaxis: A 2023 practice parameter update"]},{"id":"de_bcc","name":"基底细胞癌","aka":["Basal Cell Carcinoma","BCC","基底细胞瘤"],"rank":3,"basic":{"define":"起源于表皮基底细胞或毛囊外根鞘的恶性皮肤肿瘤，生长缓慢、局部浸润，极少转移，但可致局部组织破坏（尤其面部）；是最常见的皮肤恶性肿瘤，多见于长期日晒暴露部位。","risk":["长期紫外线暴露（日光、户外职业）、白皮肤与浅色眼睛","年龄 >50 岁（发病率随年龄上升）、男性","既往基底细胞癌/鳞状细胞癌史（复发与再发风险高）","化学暴露（砷）、放疗史、免疫抑制、着色性干皮病","痣样基底细胞癌综合征（Gorlin 综合征，PTCH1 突变）"],"epi":"全球发病率持续上升，美国每年约 400 万例，为最常见的恶性肿瘤之一；我国皮肤恶性肿瘤中基底细胞癌占比约 30%–40%，头面部为最常见部位（约 70%–80%），多数为 60 岁以上人群。"},"patho":"紫外线（UVB）诱导的 DNA 损伤引起 Patched1（PTCH1）基因失活或 Smoothened（SMO）激活，使 Hedgehog 信号通路持续激活，驱动基底细胞增殖与分化异常。肿瘤生长缓慢，呈局部浸润，可沿筋膜或骨膜向深部蔓延（尤其鼻、内眦、耳周）；远隔转移极少（<0.1%）。","dx":{"criteria":["典型皮损：珍珠样小结节（半透明、表面毛细血管扩张）、浅表红斑伴脱屑、中央溃疡（「侵蚀性溃疡」），生长缓慢（数月至数年）","好发于日光暴露部位：鼻（约 25%）、颊、额、耳、内眦与眼周、颈胸部","皮肤镜：多叶状、树枝状与短毛细血管扩张，蓝灰色卵圆形巢，溃疡与叶状结构","确诊依赖皮肤活检（3–4 mm 全层咬检或切除活检）示基底样细胞巢、周边栅栏状排列与收缩间隙","病理亚型：结节型（最常见）、浅表型、硬斑病样/浸润型（侵袭性强、复发率高）、色素型"],"workup":["皮损大小、部位、边界与深度评估（面部危险区：眼周、鼻唇沟、耳）","皮肤镜检查与活检（首选切除活检或切取活检）","高危者（大病灶、复发、免疫抑制）送 Mohs 显微手术或围手术期影像（超声/MRI）评估深部边界","全身皮肤检查排除其他病灶（约 30%–50% 患者有既往或同时多发皮肤癌）","高危/多发病灶：评估 Gorlin 综合征（多发病灶、掌跖凹陷、颌骨囊肿、骨骼异常）"],"grading":"按危险分层：低危（<6 mm、非面部危险区、结节型、边界清、原发）与高危（≥6 mm 或位于危险区、硬斑病样/浸润型、复发、免疫抑制）；无公认 TNM 分期（AJCC 第 8 版仅用于非皮肤部位或转移）；病理亚型决定手术边界。"},"ddx":[{"name":"SJS/TEN（de_sjs）","point":"与本类 de_sjs 的鉴别点：BCC 为慢性、缓慢生长的局部结节或溃疡；SJS/TEN 为用药后急性全身性表皮坏死与黏膜受累，两者病程与表现截然不同。"},{"name":"荨麻疹（de_urticaria）","point":"与本类 de_urticaria 的鉴别点：BCC 无瘙痒风团、无血管性水肿，为持续性局部皮损；荨麻疹为一过性风团（<24 h）。"},{"name":"鳞状细胞癌（SCC）","point":"SCC 生长较快、角化性红斑或结节表面角化/溃疡，转移风险高于 BCC；需病理鉴别（活检为金标准）。"},{"name":"黑色素瘤（尤其无色素性/结节型）","point":"皮损色素不均、边界不规则、可快速生长，皮肤镜下见不规则色素网与蓝白结构，需活检确诊；BCC 生长缓慢、少有色素。"},{"name":"脂溢性角化病、寻常疣、皮脂腺增生","point":"良性，表面「贴上」样外观、无珍珠样边缘与树枝状血管，皮肤镜与活检可鉴别。"}],"tx":{"drug":[{"name":"维莫德吉（Hedgehog 通路抑制剂）","dose":"150 mg qd 口服，直至进展或不可耐受；仅用于局部晚期或转移性 BCC、不适合手术/放疗者","note":"SMO 抑制剂；副作用包括肌肉痉挛、脱发、味觉障碍、疲劳与低钠血症；需监测肝功能与妊娠","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全不推荐","interact":"与强 CYP3A4 抑制剂合用增加毒性；与利福平（诱导剂）合用降低疗效"},{"name":"索尼德吉（Hedgehog 通路抑制剂）","dose":"200 mg qd 口服，直至进展或不可耐受","note":"用于局部晚期/转移性 BCC，尤其对维莫德吉不耐受者；需监测肝功、肌肉痉挛与脱发","renal":"重度肾功能不全数据有限","hepatic":"肝功能不全慎用","interact":"CYP3A4 底物，与强抑制剂/诱导剂合用需调整"},{"name":"西米普利单抗（PD-1 抑制剂）","dose":"350 mg 静脉滴注 q3w，最长 30 周，用于局部晚期或转移性 BCC","note":"用于不适合手术或 Hedgehog 抑制剂失败/不耐受者；监测免疫相关不良反应","renal":"轻中度无需调整","hepatic":"重度数据有限","interact":"与免疫抑制剂同用可能降低疗效；避免在严重感染期使用"},{"name":"咪喹莫特（外用 5%）","dose":"5% 乳膏薄涂患处，每周 5 次，连用 6 周；或每周 3 次，连用 12 周；仅用于浅表型、低危、非面部危险区的 BCC","note":"局部免疫调节，可致红斑、糜烂与色素改变；不适合浸润型/硬斑病样","renal":"遵说明书","hepatic":"遵说明书","interact":"与外用激素或其他刺激物同用增加局部反应"},{"name":"5-氟尿嘧啶（外用 5%）","dose":"5% 乳膏薄涂浅表型 BCC，bid，连用 3–6 周","note":"仅用于浅表型低危病灶；面部也可用于日光性角化","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"头孢呋辛（围手术期预防）","dose":"1.5 g 静脉于术前 30 min（按机构规范）；门诊小手术无需常规预防","note":"仅高风险创面或人工植入物时使用","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"与丙磺舒延长清除"}],"nonDrug":["手术切除是首选治愈手段：低危病灶扩大切除 4 mm 边界，高危/面部危险区 5–10 mm 或 Mohs 显微手术（面部复发率低）","Mohs 显微手术适用于面部高危区、硬斑病样型或复发病灶，切缘控制优于常规切除","浅表型/低危病灶：刮除+电灼、冷冻治疗或外用咪喹莫特/5-FU","不适合手术（高龄、合并症）者：根治性放疗（尤其面部），疗程 3–6 周","局部晚期/转移：Hedgehog 抑制剂或 PD-1 抑制剂，必要时姑息性手术/放疗","Gorlin 综合征：多学科管理，定期皮肤与颌骨检查","术后随访：前 2 年每 6 个月皮肤检查，之后每年一次"],"life":["严格防晒：SPF ≥30 广谱防晒霜、遮阳帽、避免正午暴晒；户外工作者每 2 h 补涂","定期自查皮肤（每月）与每年皮肤科检查，尤其既往皮肤癌史者","戒烟、避免人工紫外线（美黑灯）","术后创面护理与瘢痕管理（硅酮凝胶/贴）","免疫抑制患者（移植后）需每 6–12 个月皮肤筛查"]},"prog":"基底细胞癌生长缓慢，多数经手术可治愈，5 年治愈率 >95%（低危病灶）；硬斑病样型/复发病灶的 5 年复发率可达 20%–30%。远处转移 <0.1%，多为局部破坏性生长；早期治疗可避免面部组织缺损。","refs":["中华医学会皮肤性病学分会皮肤肿瘤学组. 中国基底细胞癌诊疗专家共识（2018 国家卫健委版与 2022 年更新）","NCCN Guidelines: Basal Cell Skin Cancer, Version 2.2024","NCCN Guidelines: Basal Cell Skin Cancer, Version 2.2024；手术治疗边界参考 BAD（2019）","AJCC Cancer Staging Manual, 8th edition (cutaneous carcinoma)"]}]},{"id":"derm_auto_bullous","name":"自身免疫性大疱病与痤疮","rank":4,"summary":"大疱病鉴别看裂隙层次与直接免疫荧光（DIF）：天疱疮为表皮内棘层松解、DIF 细胞间网状 IgG；类天疱疮为表皮下张力性疱、DIF 沿基底膜线状 IgG/C3；确诊需活检 + DIF 并尽早系统激素。痤疮与玫瑰痤疮以分级外用为主，异维 A 酸治重度痤疮须严控致畸；激素依赖性皮炎关键在停用外用激素。","compare":[{"diseaseId":"de_pemphigus","dx":"中青年，口腔黏膜糜烂常首发，松弛性水疱易破留糜烂面，尼氏征阳性，DIF 细胞间网状 IgG/C3，抗 Dsg1/Dsg3 阳性","key":"表皮内疱 + 尼氏征阳性 + DIF 网状 IgG"},{"diseaseId":"de_bullous_pemphigoid","dx":"老年人，红斑上紧张性厚壁大疱，尼氏征阴性，黏膜多不受累，剧痒，DIF 基底膜线状 IgG/C3，抗 BP180/BP230 阳性","key":"表皮下张力性疱 + 尼氏征阴性 + DIF 线状 IgG"},{"diseaseId":"de_acne","dx":"青少年，面部与胸背皮脂区粉刺、丘疹、脓疱、结节囊肿，无大疱与免疫荧光异常","key":"粉刺为原发损害，局限皮脂分布区"},{"diseaseId":"de_rosacea","dx":"面中部潮红、持久红斑、毛细血管扩张、丘疹脓疱，无粉刺，常双眼受累；有外用激素史者为激素依赖性皮炎","key":"面中部红斑与血管扩张，无粉刺、无大疱"}],"diseases":[{"id":"de_pemphigus","name":"寻常型天疱疮","aka":["Pemphigus Vulgaris","PV","天疱疮"],"rank":1,"basic":{"define":"抗桥粒芯蛋白（Dsg1/Dsg3）自身抗体介导的自身免疫性大疱病，皮肤黏膜松弛性水疱与糜烂，尼氏征阳性。分寻常型、落叶型、增殖型、红斑型与副肿瘤性，寻常型最常见也最重。","risk":["40–60 岁高峰，女性略多","青霉胺、卡托普利、利福平、NSAIDs 可诱发","合并重症肌无力、甲亢、红斑狼疮等自身免疫病","感染、应激、日晒可诱发加重"],"epi":"全球发病率约每年 0.1–0.5/10 万；未治疗病死率 10%–20%，多死于继发感染与治疗并发症。"},"patho":"致病性 IgG 结合 Dsg3（黏膜）与 Dsg1（皮肤），使角质形成细胞黏附丧失而形成棘层松解；裂隙位于基底层上方，基底细胞呈墓碑样排列；表皮屏障丧失致体液丢失与继发感染。","dx":{"criteria":["口腔黏膜糜烂常为首发（50%–70%，可早于皮损数月）","松弛性水疱壁薄易破，破后为疼痛性糜烂面，尼氏征阳性","好发头皮、面颈、胸背、腋下、腹股沟与受压摩擦部位","病理：基底层上方棘层松解，见天疱疮细胞","DIF 表皮细胞间网状 IgG 与 C3（金标准）；ELISA 抗 Dsg1/Dsg3 阳性并用于监测"],"workup":["皮损 HE 活检 + 疱周正常皮肤 DIF 活检（专用固定液）","血清 ELISA 抗 Dsg1/Dsg3 与间接免疫荧光","血常规、肝肾功能、血糖、电解质、白蛋白","结核（IGRA）、乙肝/丙肝、HIV 筛查；长期激素前查骨密度"],"grading":"按面积与严重度分轻、中、重度；按范围分局限型与泛发型；疗效分完全缓解（停药 2 个月无新发且病灶愈合）与部分缓解。"},"ddx":[{"name":"大疱性类天疱疮（de_bullous_pemphigoid）","point":"类天疱疮为老年张力性疱、尼氏征阴性、DIF 基底膜线状；天疱疮为松弛性疱、黏膜首发、DIF 表皮内网状。"},{"name":"痤疮（de_acne）","point":"痤疮以粉刺为主、局限脂溢部位，无水疱与免疫荧光异常。"},{"name":"玫瑰痤疮与激素依赖性皮炎（de_rosacea）","point":"玫瑰痤疮为面中部红斑与脓疱，无水疱及自身抗体。"},{"name":"SJS/TEN、重症多形红斑","point":"有用药史、表皮全层坏死，DIF 阴性。"}],"tx":{"drug":[{"name":"泼尼松","dose":"起始 1 mg/kg/d（约 60 mg/d）晨起顿服；重症 1.5 mg/kg/d 或甲泼尼龙冲击；控制后每 1–2 周减 10%–20%","note":"一线基础，宜联用免疫抑制剂以便减量","renal":"遵说明书","hepatic":"肝功能不全按说明书减量并监测","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"硫唑嘌呤","dose":"1–2 mg/kg/d 口服（常用 50–100 mg/d），起效需 6–8 周","note":"用药前测 TPMT 或 NUDT15 基因型，定期查血常规与肝功","renal":"肾功能不全慎用","hepatic":"肝功能不全减量或禁用","interact":"与别嘌醇合用显著增加骨髓抑制"},{"name":"利妥昔单抗","dose":"375 mg/m² 静滴每周 1 次 ×4 次；或 1000 mg 第 1、15 天各 1 次","note":"中重度或难治病例可提高持续缓解率；用药前筛乙肝","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用增加机会性感染"},{"name":"吗替麦考酚酯","dose":"起始 500 mg bid，渐增至 1–1.5 g bid","note":"起效较快；妊娠禁用","renal":"严重肾功能不全减量","hepatic":"严重肝功能不全慎用","interact":"不与硫唑嘌呤联用"},{"name":"米诺环素 / 烟酰胺","dose":"米诺环素 100 mg bid；烟酰胺 500 mg tid","note":"仅轻症或激素减量期辅助","renal":"肾功能不全减量","hepatic":"肝功能不全慎用","interact":"米诺环素与含铝镁钙制剂间隔 2 h"},{"name":"局部治疗","dose":"丙酸氯倍他索 0.05% 软膏薄涂 bid（短期）；口腔 0.1% 曲安奈德含漱液或凝胶 qid","note":"黏膜顽固病损可局部激素封闭","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["糜烂面生理盐水湿敷，大水疱无菌抽吸而不揭除疱壁","口腔软食、漱口与局部麻醉含漱；营养支持","IVIG（2 g/kg 分 3–5 d）或血浆置换用于难治者","避免日晒与皮肤外伤（同形反应）"],"life":["每 1–3 个月复查抗 Dsg 抗体、血常规与肝肾功能","长期激素者查骨密度与眼压，补充钙与维生素 D；避免撕扯结痂","评估情绪与心理支持；妊娠计划需专科指导"]},"prog":"多数长期可控，病死率已降至 5% 以下；感染与激素累积剂量为主要风险。利妥昔单抗可提高完全缓解率，停药后仍可复发。","refs":["中华医学会皮肤性病学分会. 天疱疮诊断和治疗专家共识（2020 版）","中国天疱疮诊疗指南（2023，中华皮肤科杂志）","Joly P, et al. PEMPHIX trial, Lancet 2017"]},{"id":"de_bullous_pemphigoid","name":"大疱性类天疱疮","aka":["Bullous Pemphigoid","BP","类天疱疮"],"rank":2,"basic":{"define":"主要累及老年人的自身免疫性表皮下大疱病，以抗 BP180（XVII 型胶原）与 BP230 的 IgG 抗体为特征，表现为红斑上紧张性大疱，尼氏征阴性，黏膜受累少。","risk":["年龄 ≥70 岁，卧床与长期护理者发病率更高","帕金森病、痴呆、卒中等神经系统疾病","DPP-4 抑制剂（格列汀类）、部分利尿剂与青霉素可诱发","紫外线、放疗、创伤与同形反应"],"epi":"欧美 ≥70 岁年发病率约 150–400/百万且近 20 年上升；我国缺乏全国数据，多见于 60 岁以上。"},"patho":"抗体结合半桥粒 BP180，激活补体、肥大细胞与嗜酸性粒细胞，释放蛋白酶致基底膜带裂解形成表皮下大疱；IgE 与嗜酸性粒细胞参与瘙痒。前驱期可仅为瘙痒性荨麻疹样斑片（非大疱型）。","dx":{"criteria":["老年人紧张性大疱，疱壁厚不易破，尼氏征阴性","好发躯干屈侧、四肢内侧、腹股沟与腋下，瘙痒剧烈","前驱期可为数月荨麻疹样斑块与剧痒","病理：嗜酸性粒细胞浸润的界面皮炎，表皮下裂隙","DIF 基底膜带线状 IgG 与 C3（金标准，取疱旁正常皮肤）","ELISA 抗 BP180 NC16A 滴度与病情活动相关"],"workup":["皮损 HE 活检 + 疱旁正常皮肤 DIF 活检","盐裂皮肤试验：沉积表皮侧支持类天疱疮，真皮侧支持获得性大疱性表皮松解症","血清抗 BP180/BP230、血嗜酸性粒细胞与 IgE","梳理用药史；治疗前查肝肾功能、血糖、电解质与白蛋白"],"grading":"按范围分局限型与泛发型；按每日新发疱数分轻、中、重度；可用 BPDAI 评估活动度。"},"ddx":[{"name":"寻常型天疱疮（de_pemphigus）","point":"天疱疮松弛性疱、黏膜多次受累、DIF 表皮内网状；类天疱疮张力性疱、DIF 基底膜线状。"},{"name":"痤疮（de_acne）","point":"痤疮为青少年粉刺性丘疹脓疱，无大疱。"},{"name":"玫瑰痤疮与激素依赖性皮炎（de_rosacea）","point":"玫瑰痤疮局限于面中部，无大疱与自身抗体。"},{"name":"获得性大疱性表皮松解症（EBA）","point":"DIF 沉积于真皮侧，抗 VII 型胶原阳性。"}],"tx":{"drug":[{"name":"泼尼松","dose":"中重度 0.5 mg/kg/d（约 30 mg/d）口服，危重 0.5–1 mg/kg/d；控制后每 2–4 周减 20%–30%；局限型可仅外用","note":"主张小起始剂量并早期联用助减剂，降低老年人激素相关死亡","renal":"遵说明书","hepatic":"肝功能不全按说明书减量","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"多西环素","dose":"100 mg bid 或 200 mg qd 口服，可与烟酰胺联用，用于轻中度或助减","note":"8 岁以下与孕妇禁用","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与抗酸剂、铁剂间隔 2 h；增强华法林作用"},{"name":"烟酰胺","dose":"500 mg 口服 tid，疗程数周至数月","note":"常与四环素类联用；可致面部潮红","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"遵说明书"},{"name":"甲氨蝶呤（助减剂）","dose":"10–15 mg 口服或皮下注射，每周 1 次，与激素联用","note":"老年需评估肾功能并补叶酸","renal":"CrCl <30 慎用或禁用","hepatic":"肝功能不全慎用","interact":"与复方新诺明、NSAIDs 合用增加毒性"},{"name":"奥马珠单抗（难治性）","dose":"300 mg 皮下注射，每 2–4 周 1 次","note":"伴高 IgE 与剧痒的难治者可能有效，属超适应证使用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"外用强效激素","dose":"丙酸氯倍他索 0.05% 软膏薄涂受累区 bid，2 周后改隔日或换中效；面部用弱中效","note":"局限型可单用；大面积使用注意系统吸收","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["停用可疑药物（格列汀类、部分利尿剂）并与内科协商替换","抽吸疱液、保持创面清洁；继发感染用抗生素","口服抗组胺或小剂量多塞平止痒（老年防跌倒）","难治者用 IVIG 或血浆置换；卧床者防压疮"],"life":["减量期每 2–4 周复诊，监测抗 BP180 与皮损活动度","评估跌倒风险、营养、血糖与血压","避免皮肤外伤与日晒；免疫抑制期避免减毒活疫苗"]},"prog":"多数在数月至 2–3 年内缓解，复发率 20%–30%；1 年病死率约 20%–40%，与高龄、合并症及激素并发症相关。","refs":["中华医学会皮肤性病学分会. 大疱性类天疱疮诊断和治疗专家共识（2022 版）","EADV Updated S2K guidelines for bullous pemphigoid (2022)","BAD guidelines for bullous pemphigoid (2022 update)"]},{"id":"de_acne","name":"痤疮","aka":["Acne Vulgaris","青春痘","寻常痤疮","重度囊肿型痤疮"],"rank":3,"basic":{"define":"累及毛囊皮脂腺单位的慢性炎症性疾病，以粉刺、丘疹、脓疱、结节、囊肿与瘢痕为表现，好发面部与胸背。轻度（Ⅰ级，粉刺为主）、中度（Ⅱ–Ⅲ级，炎性丘疹脓疱）、重度（Ⅳ级，结节囊肿与瘢痕）。","risk":["青春期雄激素升高与皮脂分泌旺盛；家族史","致痘化妆品、长期摩擦与挤压","高糖与高乳制品饮食、肥胖与胰岛素抵抗","压力、睡眠不足、多囊卵巢与高雄激素","糖皮质激素、锂剂、异烟肼、雄激素等药物"],"epi":"青少年患病率 85% 以上，我国中学生调查约 50%–80%；重度痤疮可遗留瘢痕并影响心理健康。"},"patho":"毛囊口角化异常形成微粉刺，皮脂分泌增加、痤疮丙酸杆菌增殖与毛囊周围炎症共同作用，形成粉刺至结节囊肿的谱系；炎症向真皮深层扩展可破坏毛囊壁形成囊肿与瘢痕。","dx":{"criteria":["青年起病，面部、前胸后背皮脂丰富区对称分布","原发损害为粉刺（黑头与白头），继发丘疹、脓疱、结节与囊肿","粉刺是诊断必备，也是与玫瑰痤疮鉴别的关键","可伴毛孔粗大、皮脂溢出、瘢痕与色素沉着","重度囊肿型结节与囊肿 >5 个，易留瘢痕","女性评估月经、多毛与雄激素，警惕多囊卵巢"],"workup":["计数皮损类型，评估瘢痕与色沉并照片记录；用 GAGS 或国际改良分级","女性疑高雄激素者查睾酮、LH/FSH 与卵巢超声","长期用抗生素或多发耐药者做痤疮丙酸杆菌培养","异维 A 酸前查肝功、血脂、妊娠试验与精神健康评估"],"grading":"Ⅰ级：粉刺为主，少量丘疹脓疱；Ⅱ级：炎性丘疹脓疱增多；Ⅲ级：大量丘疹脓疱并见结节；Ⅳ级：结节囊肿为主，易留瘢痕。"},"ddx":[{"name":"玫瑰痤疮与激素依赖性皮炎（de_rosacea）","point":"玫瑰痤疮以面中部潮红、血管扩张为主，无粉刺；痤疮以粉刺为核心。"},{"name":"寻常型天疱疮（de_pemphigus）","point":"天疱疮为黏膜糜烂与松弛性大疱；痤疮无大疱。"},{"name":"大疱性类天疱疮（de_bullous_pemphigoid）","point":"类天疱疮为老年张力性大疱；痤疮见于青壮年。"},{"name":"马拉色菌毛囊炎与细菌性毛囊炎","point":"马拉色菌毛囊炎真菌镜检阳性；细菌性毛囊炎以毛囊为中心；均无粉刺。"}],"tx":{"drug":[{"name":"过氧化苯甲酰（外用）","dose":"2.5%–5% 凝胶或洗剂，薄涂患处 qd 起，耐受后 bid；胸背可用 5% 洗剂","note":"无耐药性，常与阿达帕林或抗生素联合；可漂白衣物","renal":"遵说明书","hepatic":"遵说明书","interact":"与外用维 A 酸叠加时宜分时使用"},{"name":"阿达帕林 / 维 A 酸（外用）","dose":"阿达帕林 0.1% 凝胶每晚 1 次；维 A 酸 0.025%–0.1% 乳膏每晚 1 次，从低浓度隔日开始","note":"粉刺型与轻中度一线，需 8–12 周显效；初期红斑脱屑与暴痘","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与含酒精制剂同用"},{"name":"克林霉素 / 红霉素（外用）","dose":"1% 克林霉素凝胶薄涂 bid；或 2% 红霉素软膏 bid，疗程 ≤12 周","note":"宜与过氧化苯甲酰联合减少耐药","renal":"遵说明书","hepatic":"遵说明书","interact":"与林可霉素类同用增加腹泻风险"},{"name":"多西环素 / 米诺环素（口服）","dose":"多西环素 100 mg qd–bid（或 40 mg qd 缓释亚抗菌剂量）6–12 周；米诺环素 100 mg qd–bid","note":"中重度炎性丘疹脓疱，限制 12–16 周","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用；米诺环素可致色素沉着","interact":"与维 A 酸类合用增加颅高压；与抗酸剂间隔 2 h"},{"name":"异维 A 酸（口服）","dose":"起始 0.5 mg/kg/d，2–4 周后按耐受增至 1 mg/kg/d（常用 10–20 mg/d）餐时服；累积剂量 120–150 mg/kg 减少复发","note":"重度结节囊肿型或瘢痕倾向一线；育龄女性须执行妊娠预防计划：用药前 1 个月至停药后 1 个月以上严格避孕，每次处方前妊娠试验阴性","renal":"重度肾功能不全减量","hepatic":"肝酶或血脂异常者慎用，用前与 4–8 周后复查肝功血脂","interact":"禁用四环素类（增加颅高压）；与华法林合用监测 INR"},{"name":"螺内酯 / 复方短效避孕药（女性）","dose":"螺内酯 25–50 mg qd（最大 100 mg/d）；含炔雌醇复方避孕药按说明书周期服用","note":"适用多囊卵巢相关者；用药前评估性激素与血钾","renal":"肾功能不全与高钾血症禁用螺内酯","hepatic":"肝功能不全慎用","interact":"螺内酯与 ACEI/ARB、补钾剂合用致高钾"}],"nonDrug":["温和洁面每日 1–2 次，避免过度清洁与磨砂膏；勿挤压囊肿","红蓝光或光动力用于中重度炎性痤疮；果酸/水杨酸焕肤辅助粉刺型","瘢痕与痘印：稳定期点阵激光、微针或化学焕肤；色沉用防晒与维 C、壬二酸","疗程 ≥12 周，有效后外用维 A 酸或过氧化苯甲酰维持"],"life":["减少高糖、高乳制品与高血糖负荷食物","评估抑郁焦虑，尤其使用异维 A 酸者；选无致痘护肤品","异维 A 酸期间严格避孕并签知情同意，规律作息减压"]},"prog":"多数治疗后可明显改善，停药仍可复发；重度结节囊肿型易留萎缩性瘢痕。异维 A 酸达累积剂量后约 70%–85% 长期缓解。","refs":["中华医学会皮肤性病学分会痤疮学组. 中国痤疮治疗指南（2019 修订版；2024 版）","AAD Guidelines of Care for the Management of Acne Vulgaris (2024)"]},{"id":"de_rosacea","name":"玫瑰痤疮与激素依赖性皮炎","aka":["Rosacea","酒渣鼻","激素依赖性皮炎","激素脸"],"rank":4,"basic":{"define":"玫瑰痤疮是以面部阵发性潮红、持久红斑、毛细血管扩张与丘疹脓疱为表现的慢性炎症病，分红斑毛细血管扩张型、丘疹脓疱型、肥厚型与眼型。激素依赖性皮炎是长期外用激素后停用或减量出现的反跳性红肿、丘疹与灼热感，属医源性损伤。","risk":["浅肤色、敏感肌；日晒、热饮、辛辣、酒精与情绪激动","蠕形螨增多、屏障受损与过度清洁","长期（>1 个月）外用强效激素或含激素护肤品（激素依赖性皮炎）","风寒刺激与不规范护肤"],"epi":"成人患病率约 5%–10%，多见 30–50 岁女性，肥厚型多见于男性；面部激素依赖因自行使用激素类或快速祛斑产品而较常见。"},"patho":"固有免疫失衡（抗菌肽 LL-37）、神经血管调节异常与屏障受损致血管持续扩张与炎症丘疹脓疱，蠕形螨与菌群参与炎症。激素依赖性皮炎因外源激素抑制屏障修复，停药后炎症反跳形成依赖—反跳循环。","dx":{"criteria":["玫瑰痤疮：面颊、鼻、额等中央区阵发性潮红与持久红斑，伴毛细血管扩张","丘疹脓疱型：红斑上丘疹脓疱，无粉刺（与痤疮鉴别的关键）","肥厚型：鼻尖增厚与纤维化结节（鼻赘）；眼型：眼干、异物感与睑缘炎","激素依赖性皮炎：明确外用激素史 ≥1 个月，停后 1–3 d 红肿、丘疹、灼热刺痛、脱屑，再用即缓解并反复","皮肤镜见毛细血管扩张与橙红色背景；Wood 灯可示蠕形螨聚集"],"workup":["详询护肤品、外用激素种类与时间，以及日晒、饮食与情绪诱因","疑似眼型行裂隙灯与泪膜破裂时间检查","皮肤镜与蠕形螨刮取检查；评估皮肤屏障","鉴别检查：真菌镜检（脂溢性皮炎）、ANA 与活检（红斑狼疮）"],"grading":"玫瑰痤疮按亚型分类并评估轻中重度；激素依赖性皮炎按累及面积、戒断反应程度与病程分轻中重度。"},"ddx":[{"name":"痤疮（de_acne）","point":"痤疮有粉刺，青少年与皮脂溢出部位；玫瑰痤疮无粉刺，以面部中央潮红为主。"},{"name":"寻常型天疱疮（de_pemphigus）","point":"天疱疮为黏膜糜烂与松弛性大疱；玫瑰痤疮无大疱。"},{"name":"大疱性类天疱疮（de_bullous_pemphigoid）","point":"类天疱疮为老年张力性大疱伴自身抗体；玫瑰痤疮无。"},{"name":"红斑狼疮（蝶形红斑）","point":"蝶形红斑跨鼻梁，伴光敏感、关节痛与 ANA 阳性；玫瑰痤疮无系统损害。"}],"tx":{"drug":[{"name":"甲硝唑凝胶（外用）","dose":"0.75% 或 1% 凝胶薄涂患处 bid，疗程 8–12 周","note":"丘疹脓疱型一线外用，刺激性小","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与含酒精护肤品同用"},{"name":"伊维菌素乳膏 1%","dose":"每晚薄涂全脸（豌豆大小量），连用 12 周，控制后每周 1 次维持","note":"丘疹脓疱型有效并兼顾蠕形螨","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"壬二酸（外用）","dose":"15% 凝胶或 20% 乳膏薄涂 bid，疗程 8–12 周，从 qd 建立耐受","note":"兼具抗炎与改善红斑；初期可刺痛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"多西环素（亚抗菌剂量）","dose":"40 mg 缓释 qd 口服，或 100 mg bid ×4–8 周后减为 40 mg qd","note":"中重度丘疹脓疱型的抗炎治疗；注意光敏","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与抗酸剂、铁剂间隔 2 h"},{"name":"卡维地洛 / 羟甲唑啉（红斑潮红）","dose":"卡维地洛 6.25 mg bid 渐增至 12.5 mg bid；羟甲唑啉 1% 凝胶外用 qd（我国按说明书）","note":"卡维地洛影响心率血压需监测；羟甲唑啉可致反跳性红斑","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用卡维地洛","interact":"卡维地洛与降压药、地高辛合用需注意"},{"name":"激素依赖性皮炎：戒断与替代","dose":"停用强效外用激素（长期强效者 2–4 周内逐级减为弱效后停用）；他克莫司 0.03% 软膏 bid 替代；渗出期生理盐水冷湿敷","note":"戒断期红肿脱屑需充分解释安抚，切勿再用激素","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"羟氯喹","dose":"200 mg bid 口服 8–12 周","note":"适合伴红斑与光敏感者；长期需眼底监测","renal":"肾功能不全减量","hepatic":"肝功能不全慎用","interact":"与 QT 延长药合用增加心律风险"}],"nonDrug":["严格防晒：SPF ≥30、PA +++ 广谱防晒并遮阳，避免日晒是核心","避免热饮、辛辣、酒精、桑拿与情绪波动","弱酸性洁面与屏障修复，避免去角质与含酒精产品","IPL 或脉冲染料激光改善红斑；鼻赘型可 CO2 激光或手术","激素依赖性皮炎停激素后避免任何含激素产品，稳定期再考虑温和光电"],"life":["记录诱发因素与护肤产品，避免盲目更换","评估抑郁焦虑，必要时心理干预；每 2–3 个月随访","警惕快速美白或祛痘产品非法添加激素"]},"prog":"玫瑰痤疮慢性复发，规范外用多可控制但需长期避诱因；激素依赖性皮炎戒断期可持续数周至数月，反复用激素易致难治性红斑与毛细血管扩张。","refs":["中国玫瑰痤疮诊疗指南（2021 版，中华医学会皮肤性病学分会）","中国面部激素依赖性皮炎诊疗专家共识（2022）","ROSCO standard management options for rosacea (2020 update, JAAD)"]}]},{"id":"derm_pigment_other","name":"色素与皮肤附属器病","rank":5,"summary":"色素病以严格防晒为基础：白癜风分型分期，进展期用系统激素与光疗、稳定期可移植；黄褐斑以防晒 + 外用氢醌类与氨甲环酸为核心，光电须谨慎。雄激素性脱发靠米诺地尔与非那雄胺长期维持，斑秃一线为外用与皮损内激素、难治者用 JAK 抑制剂；疥疮须全身涂药并家庭同步治疗。","compare":[{"diseaseId":"de_vitiligo","dx":"境界清楚的瓷白色脱失斑，无鳞屑与萎缩，伍德灯下亮蓝白色荧光，毛发可变白；分节段型与寻常型、进展期与稳定期","key":"瓷白色脱失斑 + 伍德灯亮白荧光"},{"diseaseId":"de_melasma","dx":"面部对称性黄褐色斑片，以颧颊部为主，日晒与妊娠后加重，Wood 灯与皮肤镜判断色素深度","key":"面部对称锯齿状褐色斑，日晒加重"},{"diseaseId":"de_alopecia","dx":"雄激素性脱发：前发际后移与头顶稀疏，拉发试验阴性；斑秃：边界清楚的圆形脱发斑，拉发试验阳性，可见感叹号发","key":"脱发分布与拉发试验（弥漫稀疏 vs 圆形片状）"},{"diseaseId":"de_scabies","dx":"夜间剧痒，指缝、腕侧、阴部红色丘疹与隧道，可查见疥螨或虫卵；家庭成员常同时发病","key":"夜间瘙痒 + 指缝隧道 + 家庭聚集"}],"diseases":[{"id":"de_vitiligo","name":"白癜风","aka":["Vitiligo","白斑病"],"rank":1,"basic":{"define":"获得性、局限性或泛发性皮肤色素脱失病，因黑素细胞破坏形成境界清楚的白斑。按分布分节段型与寻常型（局限型、散发型、泛发型、肢端型）；按活动性分进展期与稳定期。","risk":["自身免疫性甲状腺病及其他自身免疫病","约 20%–30% 有家族史","精神应激、创伤与晒伤（同形反应）","少数与 HLA 相关基因位点有关"],"epi":"全球患病率约 0.5%–1%，我国部分调查约 0.1%–2.7%，好发 10–30 岁；不影响内脏功能但影响外观与心理。"},"patho":"黑素细胞遭自身反应性 CD8⁺ T 细胞攻击而破坏，氧化应激与凋亡是重要机制；白斑处黑素干细胞可耗竭或休眠，故越早治疗越易复色。","dx":{"criteria":["乳白或瓷白色斑片，表面光滑，无鳞屑与萎缩，边缘可有一过性色素加深","好发面部、颈、手、指端、腋下、外生殖器与受压摩擦部位","Wood 灯下呈亮蓝白色荧光，可发现早期白斑","分型：节段型（单侧沿皮节分布，进展快、较早稳定）与寻常型（对称或非对称泛发）","分期：进展期（近 1 年新发、扩大或同形反应阳性）与稳定期（近 1 年无扩大无新发）","泛发型与青少年需排查甲状腺等自身免疫病"],"workup":["全身皮肤检查并照片记录（面积、部位、毛发是否变白）","Wood 灯与皮肤镜（毛囊周围色素岛提示复色潜能）","甲状腺功能与 TPOAb/TgAb，必要时查 ANA 与血糖","诊断不明者活检排除无色素痣；评估心理与生活质量"],"grading":"按分布型分节段型、局限型、散发型、泛发型与肢端型；按分期分进展期与稳定期（≥1 年无活动）。"},"ddx":[{"name":"黄褐斑与色素沉着（de_melasma）","point":"黄褐斑为褐色斑、境界不清；白癜风为瓷白脱失斑，Wood 灯亮白荧光。"},{"name":"雄激素性脱发与斑秃（de_alopecia）","point":"斑秃为脱发斑；白癜风可致毛发变白但无脱发。"},{"name":"疥疮与虫咬皮炎（de_scabies）","point":"疥疮为剧痒丘疹与隧道；炎症后色减色淡而非瓷白。"},{"name":"无色素痣、贫血痣","point":"无色素痣自幼存在；贫血痣摩擦后病灶不变红；白癜风 Wood 灯荧光强。"}],"tx":{"drug":[{"name":"卤米松 / 丙酸氯倍他索（外用强效激素）","dose":"0.05% 软膏或乳膏薄涂白斑 qd–bid，不超过 2–4 周后间歇或换弱中效；面部与皱褶用弱效或他克莫司","note":"稳定期局限白斑一线外用；长期可致萎缩与激素依赖","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"他克莫司 / 吡美莫司（外用）","dose":"他克莫司 0.1% 软膏薄涂 bid（面部 0.03%）8–12 周；吡美莫司 1% 乳膏 bid","note":"面部、儿童与皱褶部位较激素安全，为面部白斑首选","renal":"遵说明书","hepatic":"遵说明书","interact":"与光疗联用时按专科方案调整"},{"name":"卡泊三醇 / 他卡西醇","dose":"卡泊三醇 0.005% 软膏薄涂 bid，常与光疗联合或与激素交替；面部用他卡西醇","note":"面部注意刺激；大量外用可升高血钙","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"小剂量口服激素（进展期）","dose":"泼尼松 0.3–0.5 mg/kg/d 口服，每 2–4 周减 5 mg，疗程 2–3 个月；或甲泼尼龙冲击遵专科","note":"进展期快速控制，可联合 NB-UVB","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"甲氨蝶呤（难治进展期）","dose":"10–15 mg 口服或皮下注射，每周 1 次，联合叶酸，疗程 3–6 个月","note":"用于激素控制不佳或依赖者","renal":"CrCl <30 慎用或禁用","hepatic":"肝功能不全慎用","interact":"与复方新诺明、NSAIDs 合用增加毒性"}],"nonDrug":["NB-UVB 每周 2–3 次，疗程 3–6 个月，适合泛发、面部及稳定后的皮损","308 nm 准分子光适用于面积 <10% 体表面积的局限白斑，面部疗效较好","自体表皮或黑素细胞移植，用于稳定期（≥1 年无活动）且药物光疗无效的局限白斑","进展期避免外伤与过度日晒；全面防晒防同形反应；可用遮瑕伪装"],"life":["每 3 个月评估白斑面积与活动性，调整方案","评估并干预社交焦虑与抑郁；合并甲状腺病者多学科随访","儿童优先外用弱中效激素或钙调磷酸酶抑制剂"]},"prog":"约 30% 可自行部分复色，面部与儿童早期皮损疗效较好；病程慢，进展与稳定交替，肢端与节段型较难治。","refs":["中国白癜风诊疗共识（2021 版，中华医学会皮肤性病学分会）","中国白癜风诊疗指南（2024 版，中华皮肤科杂志）","EADV Vitiligo guidelines (2021, JEADV)"]},{"id":"de_melasma","name":"黄褐斑与色素沉着","aka":["Melasma","Chloasma","肝斑","妊娠斑","炎症后色素沉着"],"rank":2,"basic":{"define":"以面部对称性黄褐色色素沉着为特征的获得性色素病，常见于育龄女性，以颧颊、口周与额部为主。炎症后色素沉着为皮肤炎症或损伤后的局部色素加深，是同部位重要鉴别对象。","risk":["育龄女性、妊娠与口服避孕药（雌激素、孕激素）","日晒与紫外线暴露为最重要诱因","遗传倾向、深肤色人群","甲状腺或卵巢功能异常；不规范美白产品（含汞、氢醌滥用）"],"epi":"育龄女性患病率约 10%–25%，亚洲女性更常见，男性亦可发生；炎症后色素沉着在深肤色人群极为常见。"},"patho":"紫外线、激素与炎症因子刺激黑素细胞活性与黑素合成，并向真皮上层迁移，表皮与真皮均有色素（混合型常见）；基底膜受损与血管增生参与形成，真皮型色素难以外用药清除。","dx":{"criteria":["对称、界限相对清楚但边缘呈锯齿状的黄褐色斑片，以颧颊与额部为主，无鳞屑与萎缩","日晒、妊娠与口服避孕药后加重，春夏明显","Wood 灯：褐色加深提示表皮型，变化不明显提示真皮型，介于两者为混合型；皮肤镜见色素网络与毛细血管扩张","炎症后色素沉着需有炎症或损伤史（痤疮、湿疹、激光后），随代谢逐步变淡","排除颧部褐青色痣、外源性褐黄病与日光性黑子"],"workup":["Wood 灯与皮肤镜评估色素深度与血管因素，决定是否适合光电","询问妊娠、口服避孕药、美白产品与激素使用史","必要时查性激素、甲状腺功能与肝肾功能","单侧不对称或色泽异常者活检排除恶变"],"grading":"按深度分表皮型、真皮型与混合型；按范围与 MASI 评分评估病情。"},"ddx":[{"name":"白癜风（de_vitiligo）","point":"白癜风为瓷白脱失斑、Wood 灯亮白荧光；黄褐斑为褐色沉着。"},{"name":"雄激素性脱发与斑秃（de_alopecia）","point":"脱发为毛发减少，无面部色素斑。"},{"name":"疥疮与虫咬皮炎（de_scabies）","point":"虫咬后色沉伴瘙痒丘疹与虫咬史；黄褐斑无症状。"},{"name":"颧部褐青色痣与日光性黑子","point":"褐青色痣为颧部灰蓝色斑、真皮色素；日光性黑子为边界清楚的褐色斑。"}],"tx":{"drug":[{"name":"广谱防晒剂","dose":"SPF ≥30、PA +++，晨间使用每 3–4 h 补涂；配合遮阳帽与伞；含氧化铁的有色防晒可阻挡可见光","note":"所有治疗的基础，可显著降低复发","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"氢醌 2%–4% 乳膏","dose":"2%–4% 乳膏每晚薄涂色素斑，或按说明书间歇使用（连用 2–3 个月后暂停），与防晒联合","note":"中重度常用外用；长期连续使用（>6 个月）可致外源性褐黄病与色素脱失，须间歇使用并由医生控制疗程","renal":"遵说明书","hepatic":"遵说明书","interact":"与光电联合宜停药数周后再治疗以减少反跳"},{"name":"外用氨甲环酸制剂","dose":"2%–5% 乳膏或精华局部外用 bid，疗程 8–12 周","note":"抑制纤溶酶活性、减少黑素合成；可与氢醌或烟酰胺联用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"维 A 酸类外用","dose":"维 A 酸 0.025%–0.1% 乳膏或阿达帕林 0.1% 凝胶每晚 1 次，逐渐建立耐受","note":"促进角质剥脱并抑制黑素转移；初期红斑脱屑","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他剥脱剂合用增加刺激"},{"name":"烟酰胺 / 壬二酸（外用）","dose":"5% 烟酰胺乳膏 bid；壬二酸 15%–20% 乳膏 bid","note":"用于维持治疗或不能耐受氢醌者","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"口服氨甲环酸（中重度难治）","dose":"250 mg bid–tid（常用 500–750 mg/d）口服 8–16 周；可与光电联合短程使用","note":"可明显改善黄褐斑，但既往血栓、口服避孕药或促凝状态者禁用或慎用；我国属超说明书用药，需知情同意","renal":"肾功能不全减量或禁用","hepatic":"肝功能不全慎用","interact":"与口服避孕药、促凝药合用增加血栓风险"}],"nonDrug":["避光：避免 10:00–16:00 强紫外线时段；用含氧化铁有色防晒阻挡可见光","化学焕肤（果酸、杏仁酸、低浓度水杨酸）须专业操作，深肤色注意炎症后色沉","光电：调 Q、皮秒激光与强脉冲光用于部分患者，能量须低、次数适量","停用含汞或非规范浓度氢醌的快速祛斑产品；温和护肤修复屏障","需长期维持（外用美白剂与防晒），单次治疗易复发"],"life":["口服避孕药相关者与妇科共同评估是否停用","每 2–3 个月随访，避免自行长期使用氢醌；做好预期管理","避免日光浴与不规范强脉冲光治疗；妊娠期色素变化产后多可缓解"]},"prog":"慢性易复发，规范治疗 3–6 个月可明显改善，停药与日晒后易复发；真皮型与混合型反应较差。炎症后色素沉着多在数月至 1–2 年内消退。","refs":["中国黄褐斑诊疗专家共识（2021 版，中华医学会皮肤性病学分会）","European S3 guideline on the treatment of melasma (2016，更新 2023)"]},{"id":"de_alopecia","name":"雄激素性脱发与斑秃","aka":["Androgenetic Alopecia","AGA","Alopecia Areata","AA","脂溢性脱发","男性型脱发","鬼剃头"],"rank":3,"basic":{"define":"雄激素性脱发（AGA）为雄激素依赖性、进行性毛囊微小化，男性前发际后移与头顶稀疏，女性头顶弥漫稀疏而前发际保留。斑秃（AA）为自身免疫性非瘢痕性脱发，表现为边界清楚的圆形脱发斑，可为单发、多发、全秃或普秃。","risk":["AGA：家族史（阳性率 50%–80%）、雄激素与 5α-还原酶活性","AGA：年龄增长与精神压力","AA：合并甲状腺病、白癜风等自身免疫病及家族史","AA：精神应激、感染可为诱因"],"epi":"AGA 男性 30–50 岁患病率可达 30%–50%，女性绝经后明显升高；斑秃全球患病率约 1%–2%，约 5% 进展为全秃或普秃。"},"patho":"AGA 中双氢睾酮作用于易感毛囊雄激素受体，终毛微小化为毳毛、生长期缩短，毛囊逐渐萎缩。斑秃中毛囊生长期的免疫豁免被打破，CD8⁺ T 细胞攻击毛球，导致非瘢痕性急性脱发，毛囊多仍具再生能力。","dx":{"criteria":["AGA 男性：颞部发际后移（M 型）与头顶稀疏，毛发变细，拉发试验多阴性","AGA 女性：头顶弥漫稀疏、额颞发际保留（Ludwig 分型）","斑秃：边界清楚的圆形脱发斑，头皮光滑无瘢痕，拉发试验阳性","斑秃活动期见感叹号发，皮肤镜见黑点征、断发征与黄点","斑秃按范围分斑片型、多发型、网状型、匐行型、全秃与普秃","必要时查甲状腺功能与自身抗体"],"workup":["脱发分级（Norwood-Hamilton、Ludwig）、拉发试验与感叹号发检查","皮肤镜：AGA 见毛发直径差异 >20%、毛囊单位毛发数减少；斑秃见黄点与黑点","甲状腺功能、铁蛋白与血常规；女性查睾酮、DHEA-S 与多囊卵巢","诊断不明或疑瘢痕性脱发时活检（斑秃见蜜蜂群样淋巴细胞浸润）"],"grading":"AGA 按 Norwood-Hamilton（Ⅰ–Ⅶ级）与 Ludwig（Ⅰ–Ⅲ级）分级；斑秃按 SALT 评分分轻（<25%）、中（25%–50%）、重（50%–99%）、全秃与普秃。"},"ddx":[{"name":"白癜风（de_vitiligo）","point":"白癜风为色素脱失斑而毛发存在；斑秃为毛发脱失而头皮正常。"},{"name":"黄褐斑与色素沉着（de_melasma）","point":"黄褐斑为面部色素斑，无毛发丢失。"},{"name":"疥疮与虫咬皮炎（de_scabies）","point":"虫咬可致局部断发，但无圆形脱发斑；疥疮有隧道与家庭聚集。"},{"name":"休止期脱发","point":"分娩、疾病或药物后 2–3 个月弥漫脱发，无圆形脱发斑与感叹号发。"}],"tx":{"drug":[{"name":"米诺地尔酊 5%（外用）","dose":"男性 5% 酊剂 1 mL 涂脱发区 bid（每日 ≤2 mL）；女性 2% 溶液 1 mL bid 或 5% 泡沫剂 qd","note":"AGA 一线外用，需长期使用（≥4 个月评估并持续维持）；初期可短暂狂脱期；斑秃斑片亦可用","renal":"遵说明书","hepatic":"遵说明书","interact":"与强效外用激素联合用于斑秃时注意刺激"},{"name":"非那雄胺 1 mg（男性 AGA）","dose":"1 mg qd 口服，≥6 个月评估疗效，有效后长期维持","note":"5α-还原酶Ⅱ型抑制剂；女性尤其育龄期禁用（致畸）；可致性功能副作用与情绪变化，需知情同意","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"使 PSA 降低约 50%，前列腺癌筛查需按校正值解读"},{"name":"螺内酯（女性 AGA）","dose":"25–50 mg qd 起始，可增至 100–200 mg/d 分次，疗程 6–12 个月","note":"女性常用抗雄治疗；监测血钾；妊娠禁用","renal":"肾功能不全与高钾血症禁用","hepatic":"肝功能不全慎用","interact":"与 ACEI/ARB、补钾剂合用致高钾"},{"name":"外用糖皮质激素（斑秃）","dose":"丙酸氯倍他索 0.05% 软膏薄涂脱发斑 qn，连用 2–4 周后间歇；或 0.1% 糠酸莫米松乳膏 qd","note":"适用局限型斑秃（<25%），面部与儿童用弱中效；长期可致萎缩","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"皮损内注射糖皮质激素（斑秃）","dose":"曲安奈德 10 mg/mL 稀释至 2.5–5 mg/mL，每点 0.1 mL、间距约 1 cm，每 4 周 1 次","note":"局限或多发斑片型常用；注意皮肤萎缩与疼痛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"JAK 抑制剂（重度斑秃）","dose":"巴瑞替尼 2–4 mg qd 或利特昔替尼 50 mg qd（按说明书与专科方案），用于 ≥50% 头皮面积或全秃/普秃成人","note":"部分制剂国内已获批；需筛查结核、乙肝与带状疱疹风险，长期监测血脂与感染","renal":"肾功能不全按说明书调整","hepatic":"肝功能不全慎用","interact":"与强效 CYP3A4 抑制剂合用需调整剂量；治疗期避免活疫苗"},{"name":"小剂量系统激素（快速进展期斑秃）","dose":"泼尼松 0.5 mg/kg/d 口服并按方案减量，疗程不超过 2–3 个月","note":"仅短期控制快速进展或泛发型，需权衡复发与副作用","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血"}],"nonDrug":["AGA：毛发移植适用于稳定期男性；低能量激光与假发、增发纤维作辅助","斑秃：局部免疫治疗（DPCP/SADBE）用于泛发难治者，需专业操作","避免过度染烫、牵拉与高温造型","疗效需 ≥3–6 个月显现，避免频繁更换方案"],"life":["规律作息、减少精神应激，缺铁者补铁","温和洗发，米诺地尔用后洗手并避免接触面部","脱发与抑郁焦虑相关，必要时心理干预；育龄女性用药须有效避孕"]},"prog":"AGA 为进行性病程，米诺地尔与非那雄胺联合可稳定并部分再生，停药后 6–12 个月内多回复原轨迹。约 50%–80% 单发斑片型斑秃 1 年内自行恢复，泛发与儿童起病者预后较差。","refs":["中国雄激素性脱发诊疗指南（2022 版，中国医师协会皮肤科医师分会毛发学组）","中国斑秃诊疗指南（2023 版，中华皮肤科杂志）","AAD Guidelines of care for alopecia areata (2022)"]},{"id":"de_scabies","name":"疥疮与虫咬皮炎","aka":["Scabies","Sarcoptic Mange","疥疮","虫咬性皮炎","丘疹性荨麻疹"],"rank":4,"basic":{"define":"疥疮由人疥螨寄生于角质层引起，传染性强，以夜间剧痒与指缝、腕部丘疹与隧道为特征。虫咬皮炎（丘疹性荨麻疹）为昆虫叮咬后的过敏反应，表现为瘙痒性红色丘疹与风团样斑块，可留色素沉着。","risk":["与疥疮患者密切接触或共用床铺、衣物与被褥","养老院、监狱等集体居住与免疫功能低下（易患结痂性疥疮）","拥挤与卫生条件差的居住环境","虫咬皮炎：户外活动、蚊虫/螨/跳蚤/臭虫叮咬、宠物寄生虫"],"epi":"疥疮集体居住场所易暴发，我国冬春季多见，家庭成员聚集发病是重要线索；虫咬皮炎夏秋季高发。"},"patho":"雌疥螨在角质层内挖隧道并产卵，2–3 d 孵化，成虫寿命约 30 d；虫体、虫卵与排泄物引起过敏反应，导致夜间加重的剧痒。虫咬皮炎由昆虫唾液蛋白触发 IgE 介导的过敏反应。","dx":{"criteria":["疥疮夜间剧痒，指缝、腕屈侧、腋下、乳晕、脐周、腹股沟与外生殖器散在红色丘疹、结节与隧道","男性生殖器与臀部疥疮结节为提示性体征","家庭或同住者同时或先后出现类似瘙痒","刮片或挑取隧道内容物镜下见疥螨、虫卵或粪便即可确诊；皮肤镜见隧道与虫体","结痂性（挪威）疥疮厚层痂皮、螨量巨大，传染性极强，多见免疫抑制与老年患者","虫咬皮炎：暴露部位成群瘙痒红丘疹，中央见叮咬点，数天至数周缓解"],"workup":["全身皮肤检查重点指缝、腕、腋、腹股沟与生殖器，寻找隧道与结节","皮肤镜与刮片查虫体、虫卵；问询家庭与密切接触者","结痂性疥疮者评估免疫状态（HIV、免疫抑制剂）","虫咬皮炎排除疥疮、湿疹与药疹；继发感染者查血常规与分泌物培养"],"grading":"疥疮按形态分典型、结节性与结痂性（挪威）疥疮，按严重度分轻、中、重度；虫咬皮炎按皮疹数量与过敏程度评估。"},"ddx":[{"name":"雄激素性脱发与斑秃（de_alopecia）","point":"脱发无夜间剧痒与隧道；疥疮有家庭聚集。"},{"name":"白癜风（de_vitiligo）","point":"白癜风无瘙痒与丘疹；疥疮伴剧痒与隧道。"},{"name":"黄褐斑与色素沉着（de_melasma）","point":"黄褐斑无瘙痒；虫咬后色沉继发于瘙痒丘疹。"},{"name":"湿疹 / 特应性皮炎","point":"多对称分布于屈侧，无隧道与家庭聚集，疥螨阴性。"},{"name":"药疹与荨麻疹","point":"药疹有用药史；荨麻疹风团 <24 h 消退。"}],"tx":{"drug":[{"name":"硫磺软膏 10%（成人）/ 5%（儿童）","dose":"自颈部以下全身（婴儿含头面）薄涂，连续 3 晚每晚 1 次，第 4 晚洗去","note":"传统、低成本，适用婴幼儿、孕妇与哺乳期；气味大且油腻","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"林丹（γ-六氯环己烷）1%","dose":"自颈部以下全身涂布（不含头面），保留 8–12 h 后彻底洗去 1 次，必要时 7–10 d 后重复","note":"因神经毒性部分国家限制，婴幼儿、孕妇与癫痫患者禁用；使用前核对当地可及性与说明书","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他外用制剂重叠可增加吸收与毒性"},{"name":"氯菊酯 5% 乳膏","dose":"自颈部以下全身薄涂，保留 8–14 h 后洗去，7–14 d 后重复 1 次","note":"国际首选外用药；我国部分地区可及性有限","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"苯甲酸苄酯 10%–25% 乳剂","dose":"自颈部以下全身涂布，保留 24 h 后洗去，可重复 2–3 次（每日 1 次）","note":"国内可及性较好，刺激性强，儿童与破损皮肤用低浓度","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"伊维菌素（口服）","dose":"200 μg/kg 单次口服，2 周后重复 1 次；结痂性疥疮常需 2–3 次并联合外用","note":"用于外用失败、结痂性疥疮或暴发；妊娠期与 5 岁以下慎用","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 CYP3A4 抑制剂（酮康唑、大环内酯类）合用可升高浓度"},{"name":"抗组胺药与局部止痒（虫咬皮炎）","dose":"西替利嗪 10 mg qd 或氯雷他定 10 mg qd；局部炉甘石洗剂或 0.1% 糠酸莫米松乳膏 bid","note":"虫咬以止痒抗过敏为主；疥疮须同时抗疥","renal":"肾功能不全按说明书减量","hepatic":"肝功能不全慎用","interact":"第一代抗组胺药与镇静药合用增加嗜睡"}],"nonDrug":["家庭同步治疗：密切接触者含无症状者应同时治疗，否则极易复发","衣物、被褥与毛巾用 ≥60 ℃ 热水清洗并高温烘干；不能清洗者密封 ≥72 h","外用药须全身涂布（颈部以下，婴幼儿含头皮），包括指缝、脐部与生殖器","残留瘙痒可持续 2–4 周（过敏反应），2 周后仍有新皮损需再治疗；疥疮结节可外用或注射激素","虫咬皮炎：清除积水杂草、驱蚊、宠物驱虫、清洗床上用品"],"life":["告知密切接触者与同住者，集体机构组织筛查与同步治疗","避免抓破致继发感染，出现脓疱或发热需就医","虫咬反复者排查家庭环境与宠物寄生虫；结痂性疥疮隔离至连续 2 次查螨阴性"]},"prog":"规范抗疥后 1–2 周瘙痒明显减轻、皮损消退；失败多因未全身涂药或家庭成员未同步治疗。虫咬皮炎多自行缓解，抓破感染可留瘢痕与色沉。","refs":["疥疮诊疗专家共识（2020 版，中华医学会皮肤性病学分会）","BAD guidelines for the management of scabies (2022 update)","European S1 guideline for the treatment of scabies (2017)"]}]}]},"emerg":{"categories":[{"id":"resusc","name":"复苏与休克","rank":1,"summary":"以“识别—分层—同时干预”为主线：先判断是否为可逆的骤停心律或哪一类休克（分布性/低血容量性/心源性/梗阻性），在 5 分钟内完成气道、循环与病因（H's & T's）评估；骤停按 ACLS 高质量 CPR + 早期除颤 + 每 3–5 分钟肾上腺素，休克按类型选择液体、血管活性药与病因处理，重症患者尽早启动 ECMO 评估。","compare":[{"diseaseId":"em_shock","dx":"收缩压 <90 mmHg 或 MAP <65 mmHg、乳酸 >2 mmol/L、尿量减少伴末梢湿冷或血管扩张","key":"休克是“灌注不足综合征”，需先用 POCUS/乳酸/ScvO2 分型再补液；骤停是循环已停止，须立即 CPR 与除颤"},{"diseaseId":"em_cardiac_arrest","dx":"意识丧失、无正常呼吸、大动脉搏动消失，心电监护见室颤/无脉性室速/心电静止/无脉电活动","key":"骤停时不存在“补液试验”的时间窗，唯一有效手段是高质量胸外按压与电除颤；复苏后进入类似休克的管理"}],"diseases":[{"id":"em_cardiac_arrest","name":"成人心脏骤停","aka":["Cardiac Arrest","CA","心搏骤停","SCA"],"rank":1,"basic":{"define":"心脏机械活动突然停止，导致脑与全身器官血流中断的临床状态；表现为意识丧失、无正常呼吸、大动脉搏动消失，按心电心律分为可除颤（室颤/无脉性室速）与不可除颤（心电静止/无脉电活动）两类。","risk":["冠心病与急性心肌梗死（成人院外骤停首位病因）、心肌病、遗传性离子通道病","严重电解质紊乱（低钾/高钾、低镁）、药物过量（三环类、地高辛、局麻药）","重度缺氧、酸中毒、张力性气胸、心脏压塞、大面积肺栓塞（H's & T's）","低体温与溺水（可逆性特殊病因）、电击伤","肥厚型心肌病/长 QT 等家族性猝死史，剧烈运动中发作"],"epi":"我国每年心脏性猝死人数估计约 54.4 万；院外心脏骤停出院存活率我国约 1%–2%，院内存活出院率约 15%–25%。室颤在目击后 3 分钟内除颤存活率可达 50%–70%，每延迟 1 分钟下降 7%–10%。"},"patho":"骤停后全身血流中断，脑组织在 4–6 分钟即出现不可逆损伤；心肌在缺血 10–15 分钟后 ATP 耗竭、细胞膜泵衰竭、细胞外钾升高，出现不可除颤的电机分离。胸外按压通过胸廓与胸腔内压变化产生前向血流（心泵与胸泵机制并存），按压质量（深度、频率、胸廓回弹、中断时间）直接决定冠脉灌注压与复苏成功率；按压中断 5 秒即可使主动脉压下降至基线。复苏后过量的氧自由基、钙超载与再灌注损伤构成“复苏后病”，需以目标温度管理与多器官保护处理。","dx":{"criteria":["识别（10 秒内完成）：无反应 + 无正常呼吸（或仅有濒死叹息样呼吸），不要求触摸颈动脉超过 10 秒，医护人员可同步检查脉搏。","心律判读：可电击心律＝心室颤动（VF）或无脉性室性心动过速（pVT）；不可电击心律＝心电静止（asystole，需排除导联脱落）或无脉电活动（PEA，有电活动但无脉）。","可逆病因（H's & T's）：低血容量、低氧、酸中毒、低/高钾、低体温；张力性气胸、心脏压塞、毒素中毒、血栓（肺栓塞/冠脉）。至少每 2 个循环复查一次。","ROSC 判定：可触及脉搏或动脉波形出现，且 ETCO₂ 突然持续升高（通常 ≥40 mmHg）。"],"workup":["床旁心电监护与除颤仪（AED/手动除颤器）立即到位，至少 2 分钟一轮评估心律","呼气末二氧化碳（ETCO₂）：<10 mmHg 提示按压质量差或预后极差，突然升高提示 ROSC","床旁超声（POCUS）：ROSC 或 PEA 时评估心脏运动、右室大小、心包积液与下腔静脉，判断心脏压塞/肺栓塞/张力性气胸","动脉血气、血钾/血钙/血糖、乳酸、肌钙蛋白、BNP；疑中毒者查毒物筛查与对乙酰氨基酚/地高辛浓度","12 导联心电图（ROSC 后立即）：识别 STEMI 并转诊 PCI","体温（低体温为可逆病因，需持续复温）"],"grading":"按心律分为可除颤（VF/pVT）与不可除颤（ASY/PEA）；按骤停场所分为院内（IHCA）与院外（OHCA）；复苏后按 CPC 评分评估神经结局（1 良好，5 脑死亡）。"},"ddx":[{"name":"休克（各类休克）","point":"与本类中“休克分型与液体复苏”的鉴别点：休克患者仍存在自主循环与可测血压/灌注指标，属先行存在、可动员的循环衰竭；心脏骤停时循环已完全停止，必须以按压与除颤为主，不能依赖补液或升压药起效。"},{"name":"晕厥（血管迷走性/心源性）","point":"意识短暂丧失后 1–2 分钟内自行恢复，有前驱症状，脉搏存在；骤停不会自行恢复。"},{"name":"癫痫发作","point":"有强直阵挛与发作后状态，发作中脉搏与呼吸多存在；发作后若持续无脉搏需按骤停处理。"},{"name":"低血糖昏迷","point":"可伴抽搐与意识障碍，但脉搏、呼吸存在，指尖血糖低，推注葡萄糖后迅速改善。"},{"name":"阿-斯综合征（Adams-Stokes）","point":"严重心动过缓/传导阻滞致短暂意识丧失，属可植入起搏或心电监护的病因；若进展为无脉需立即按骤停处理。"}],"tx":{"drug":[{"name":"肾上腺素（Epinephrine）静脉/骨内推注","dose":"1 mg（0.1% 稀释后 10 mL）静推，每 3–5 分钟重复一次；不可除颤心律可尽早给予，可除颤心律在首次或第二次除颤后给药","note":"不可与碳酸氢钠同通道推注；大剂量不增加存活率；每次给药后 20 mL 生理盐水冲管并抬高肢体","renal":"无需调整","hepatic":"无需调整","interact":"与 β 受体阻滞剂同用可减弱升压效应；与卤化麻醉药合用可诱发心律失常"},{"name":"胺碘酮（Amiodarone）静脉","dose":"首剂 300 mg 静推（用 5% 葡萄糖稀释至 20 mL）；无效可追加 150 mg；ROSC 后维持 1 mg/min 泵入 6 小时，再 0.5 mg/min 18 小时","note":"用于电击无效的 VF/pVT；不可除颤心律不推荐；尽可能经中心静脉给药","renal":"无需调整","hepatic":"严重肝功能不全者减量","interact":"与华法林、地高辛、β 受体阻滞剂合用需监测；避免与延长 QT 药物联用"},{"name":"利多卡因（替代胺碘酮）","dose":"1–1.5 mg/kg 静推，无效可 0.5–0.75 mg/kg 重复一次（总量 ≤3 mg/kg）；ROSC 后维持 1–4 mg/min 泵入","note":"胺碘酮不可得时的替代；肝功能不全或低心输出量者减量，注意癫痫样毒性","renal":"无需调整","hepatic":"严重肝病减量 50% 并监测血药浓度","interact":"与西咪替丁、氟伏沙明合用升高血药浓度"},{"name":"碳酸氢钠 8.4%","dose":"1 mmol/kg 静滴（按 1 mEq/kg），仅在已知高钾、三环类抗抑郁药中毒或长时间骤停伴严重酸中毒时使用；不推荐常规使用","note":"过量导致高钠、高渗、代谢性碱中毒与左移氧解离曲线；与钙剂同用时间隔冲管且不可经同一通路","renal":"肾功能衰竭易致碱中毒与容量负荷","hepatic":"无需调整","interact":"与肾上腺素、钙剂在通路内配伍禁忌"},{"name":"硫酸镁","dose":"1–2 g 稀释后静推（10–20 分钟），用于尖端扭转型室速或多形性 VT","note":"低镁血症或药物（如胺碘酮、氟喹诺酮）诱导的 TdP 首选；不推荐常规用于 VF","renal":"肾衰者减量至 50% 并监测腱反射","hepatic":"无需调整","interact":"与神经肌肉阻滞剂协同"},{"name":"硫酸阿托品","dose":"1 mg 静推 q3–5min（最大 3 mg），仅用于有症状的窦性心动过缓、房室传导阻滞；不再推荐用于心电静止/PEA","note":"2015 年后 ACLS 已从不可除颤心律流程移除；二度 II 型/三度阻滞勿依赖阿托品","renal":"无需调整","hepatic":"无需调整","interact":"与抗胆碱能药合用加重尿潴留、谵妄"}],"nonDrug":["高质量 CPR：按压深度 5–6 cm、频率 100–120 次/分、按压比例 ≥60%、胸廓完全回弹、每 2 分钟轮换按压者，中断 <10 秒","电除颤：双相波 120–200 J（依设备推荐），单相波 360 J；VF/pVT 立即除颤，尽快 1 次除颤后即刻继续按压","高级气道：喉罩/气管插管后呼吸 10 次/分，避免过度通气；使用声门上气道者按压不中断","可逆病因处理：张力性气胸针刺或指压减压+胸腔闭式引流；心脏压塞超声引导心包穿刺；肺栓塞考虑溶栓；高钾用钙剂+胰岛素葡萄糖+碳酸氢钠","复苏后：目标温度管理 32–36 ℃ 至少 24 小时、避免高热；目标 SpO₂ 94%–98%、PaCO₂ 35–45 mmHg；STEMI 立即 PCI；血流动力学不稳定者升压药或机械循环支持（ECMO/IABP）","难治性骤停（可除颤心律经 3 次除颤仍无效）：可考虑 ECPR（ECMO 辅助心肺复苏），需在 20 分钟内启动并严格筛选"],"life":["存活者完成病因筛查：冠脉造影、心脏 MRI、心电生理、遗传咨询与家族筛查","ICD 二级预防适用于无明确可逆病因的 VF/血流动力学不稳 VT 存活者","家属培训 CPR 与 AED 使用，公众除颤项目推广","关注复苏后认知功能障碍、运动障碍与情绪问题，转介康复"]},"prog":"我国院外心脏骤停神经功能良好存活出院率约 1%–2%，院内约 10%–15%。预后良好相关因素：目击、早期 CPR 与早期除颤、可除颤心律、骤停时长 <15 分钟、ETCO₂ >30 mmHg。复苏后 72 小时持续昏迷、双侧角膜反射消失、肌阵挛状态与 EEG 抑制提示神经预后差。","refs":["中国医师协会急诊医师分会《中国心脏骤停与心肺复苏指南》（2020）","AHA/ACC《2020 心肺复苏与心血管急救指南》及 2023 年更新","欧洲复苏委员会《ERC 2021 复苏指南》","《中国器官捐献与心肺复苏后神经预后评估专家共识》"]},{"id":"em_shock","name":"休克分型与液体复苏","aka":["Shock","循环衰竭","血流动力学不稳定"],"rank":2,"basic":{"define":"各种病因导致氧输送不足或氧利用障碍，引起细胞与组织低灌注的临床综合征；诊断三要素为低血压（SBP <90 mmHg 或 MAP <65 mmHg）、组织低灌注证据（乳酸 >2 mmol/L、少尿、意识改变）与对快速补液有反应性，需保留其一作为诊断依据（Guyton 2020 “休克新定义”）。","risk":["创伤/大出血、消化道出血、产科出血与脱水（低血容量性）","脓毒症、过敏性休克、神经源性（分布性）","急性心肌梗死、暴发性心肌炎、严重心律失常与终末心衰（心源性）","张力性气胸、心脏压塞、大面积肺栓塞（梗阻性）","老年人、心血管基础病患者对容量与升压药反应差"],"epi":"急诊就诊患者中约 1%–3% 表现为休克；脓毒性休克院内病死率约 30%–40%，心源性休克约 30%–50%，创伤失血性休克约 10%–20%（我国创伤救治体系数据）；尽早识别与 1 小时内完成病因处理可显著降低病死率。"},"patho":"休克的核心是氧供（DO₂ = CO × CaO₂）低于氧耗，细胞转向无氧代谢生成乳酸。低血容量与梗阻性休克以“前负荷不足/心泵受阻”为主，心源性以泵功能衰竭为主，分布性以血管张力降低与微循环分流为主。容量反应性取决于 Frank-Starling 曲线位置：仅在曲线上升段（前负荷依赖区）补液才能提高每搏量；下腔静脉充盈、肺部 B 线、心输出量动态变化等用于预测。持续低灌注导致内皮糖萼脱落、毛细血管漏、炎症因子风暴与多器官功能衰竭。","dx":{"criteria":["低血压：SBP <90 mmHg 或较基础值下降 >40 mmHg，或 MAP <65 mmHg（高血压患者 MAP 下降 >40 mmHg 亦有意义）。","组织低灌注：乳酸 >2 mmol/L、尿量 <0.5 mL/kg/h 持续 2 小时、皮肤花斑（mottling score ≥2）、意识改变、毛细血管再充盈 >3 秒。","分型（POCUS + 临床）：低血容量（下腔静脉塌陷、心室小、肺野清；休克指数 SI = HR/SBP >1 提示）；心源性（左室功能差、B 线、颈静脉扩张）；梗阻性（右室扩大、心包积液、肺滑行消失）；分布性（高动力、下肢花斑、暖休克或脓毒症）。","容量反应性：被动抬腿试验（PLR）致每搏量或心输出量上升 ≥10%，或下腔静脉变异度 >12%（机械通气）提示有反应；CVP 单独不推荐使用。","脓毒性休克（Sepsis-3）：序贯器官衰竭评分（SOFA）急性升高 ≥2 分且感染，充分液体复苏后仍需血管活性药维持 MAP ≥65 mmHg 且乳酸 >2 mmol/L。"],"workup":["床旁超声（POCUS 方案 RUSH/CCUS）：评估下腔静脉、心脏收缩、右室大小、肺 B 线、心包积液与腹腔游离液体","血气分析、乳酸（每 2 小时复查）、血常规、凝血、肝肾功能、电解质、血糖","血培养（脓毒症在抗菌药前采集）与降钙素原、CRP；疑心源性查肌钙蛋白、BNP 与 12 导联心电图","有创动脉压（MAP <65 mmHg 或使用大剂量升压药时）与中心静脉置管（需中心静脉氧饱和度时）","尿量：留置导尿记录每小时尿量"],"grading":"按血流动力学分为低血容量性、分布性（脓毒症/过敏/神经源性）、心源性、梗阻性；按严重程度分为代偿/失代偿/难治性（需大剂量升压药或机械循环支持）。"},"ddx":[{"name":"心脏骤停","point":"与本类中“成人心脏骤停”的鉴别点：休克患者仍有自主循环与可测脉搏/血压，存在补液、升压与病因处理的时间窗；骤停时无输出量，必须以 CPR 与除颤为唯一有效干预，复苏成功后再按休克原则处理。"},{"name":"脓毒症（无休克）","point":"感染伴器官功能障碍但血压尚可、乳酸正常，按 1 小时集束化治疗；若 MAP <65 mmHg 且需升压药即转为脓毒性休克。"},{"name":"低血糖昏迷","point":"出汗、心悸、意识改变但无明显低血压，指尖血糖低，葡萄糖后迅速恢复。"},{"name":"严重过敏反应","point":"接触过敏原后数分钟内荨麻疹、喉水肿、支气管痉挛伴低血压，肾上腺素肌注为首选。"},{"name":"心源性肺水肿（无休克）","point":"端坐呼吸、双肺湿啰音、BNP 升高，但血压正常、无低灌注表现；需与心源性休克区分。"}],"tx":{"drug":[{"name":"0.9% 氯化钠 / 平衡晶体液","dose":"初始 500–1000 mL（15 分钟内）快速输注并评估反应，可重复 1–2 次；总量按类型与反应性决定，脓毒症初始推荐 30 mL/kg（心力衰竭/慢性肾病者减速并加用 POCUS 评估）","note":"优先平衡晶体液（乳酸林格液/勃脉力），避免大量生理盐水致高氯性酸中毒；避免单用羟乙基淀粉","renal":"慢性肾衰或透析依赖者限量并监测容量负荷","hepatic":"严重肝硬化腹水者需按反应性少量给予","interact":"与血制品同通路需注意含钙液与血制品相容性（枸橼酸抗凝血液）；乳酸林格不宜与头孢曲松同通路"},{"name":"去甲肾上腺素（Noradrenaline）","dose":"0.05–0.5 µg/kg/min 中心静脉泵入，滴定至 MAP ≥65 mmHg；小剂量可经外周大静脉短期使用","note":"脓毒性休克一线升压药；心源性休克可联合多巴酚丁胺（2.5–10 µg/kg/min）","renal":"无需调整","hepatic":"无需调整","interact":"与三环类抗抑郁药、MAOIs 合用显著升压；外渗可致皮肤坏死，予酚妥拉明局部浸润"},{"name":"肾上腺素（Adrenaline）","dose":"过敏反应：0.3–0.5 mg 肌注（1 mg/mL 溶液，大腿外侧，必要时 5–15 分钟重复）；升压：0.01–0.5 µg/kg/min 泵入","note":"过敏性休克首选肌注，避免静脉推注（心律失常风险）","renal":"无需调整","hepatic":"无需调整","interact":"与 β 受体阻滞剂、卤化麻醉药合用致心律失常风险增加"},{"name":"血管加压素（Vasopressin）","dose":"0.01–0.04 U/min 持续泵入（不滴定），于去甲肾上腺素 >0.25–0.5 µg/kg/min 时加用","note":"脓毒性休克常用二线；心源性休克慎用（加重肺高压与肠缺血）","renal":"无需调整","hepatic":"无需调整","interact":"与催产素类药合用增强抗利尿效应"},{"name":"氢化可的松","dose":"200 mg/日，分 3–4 次静滴或持续泵入（如 50 mg q6h），用于液体与升压药仍难以维持 MAP 的脓毒性休克","note":"首先行 ACTH 试验并非必需；短疗程 5–7 天或至升压药撤除","renal":"无需调整","hepatic":"无需调整","interact":"与氟康唑、利福平影响代谢；注意高血糖与消化道出血风险"},{"name":"多巴酚丁胺","dose":"2.5–20 µg/kg/min 泵入，起始 2.5–5 µg/kg/min","note":"心源性休克或脓毒症伴低心输出量时加用；可致心动过速、心律失常与低血压","renal":"无需调整","hepatic":"无需调整","interact":"与 β 受体阻滞剂竞争受体，合用降低疗效"},{"name":"氨甲环酸（TXA）","dose":"创伤出血：1 g 10 分钟内静推后 1 g 输注 8 小时，伤后 3 小时内给予；产后出血：1 g 缓慢静推，30 分钟后可重复 1 g","note":"用于大出血早期，超过 3 小时创伤不推荐","renal":"肾衰者减量并监测癫痫风险","hepatic":"无需调整","interact":"与抗凝药/抗血小板药合用不增加大出血证据但需监测"}],"nonDrug":["病因处理优先：活动性出血止血（压迫、手术、介入）、张力性气胸减压、心包穿刺、急性心梗死 PCI、大面积肺栓塞溶栓","液体复苏策略：脓毒症早期按需补液后以“反应性-耐受性”原则驱动，后续使用去复苏（deresuscitation）避免液体过负荷","目标导向：MAP ≥65 mmHg、乳酸下降 ≥10%/2 小时、尿量 ≥0.5 mL/kg/h、毛细血管再充盈 ≤3 秒、ScvO₂ ≥70%（必要时）","输血：活动性出血以 Hb <70 g/L 为目标（ACS 患者 <80 g/L），大量输血按 1:1:1 比例（红细胞:血浆:血小板）","机械循环支持：心源性休克首选 VA-ECMO 或 Impella/IABP（AMI 合并机械并发症时评估）","神经源性休克：去甲肾上腺素或苯肾上腺素维持 MAP 80–90 mmHg，避免早期过量补液致肺水肿"],"life":["休克恢复后评估液体状态、营养支持（7 天前肠内营养优先），早期康复","脓毒症存活者需长期随访认知、肌无力与心理问题（脓毒症后综合征）","慢性病（心衰、肝硬化、过敏）患者教育识别早休克信号：尿量减少、口渴、皮肤湿冷、站立晕厥","药物过敏史记录并避免再暴露；高危患者备肾上腺素笔"]},"prog":"脓毒性休克 28 天病死率约 25%–40%，心源性休克约 30%–50%，梗阻性休克迅速纠正后预后较好。早期（1–3 小时）完成病因控制、液体反应性评估准确、乳酸 6 小时内清除者预后明显改善；持续升压药依赖 >48 小时、乳酸 >4 mmol/L 不降者预后差。","refs":["中华医学会急诊医学分会/中国医师协会急诊医师分会《脓毒症与脓毒性休克急诊诊疗中国专家共识》（2023）","中国医师协会急诊医师分会《中国急性循环衰竭（休克）急诊诊治专家共识》（2016）","Surviving Sepsis Campaign《2021 国际脓毒症与脓毒性休克管理指南》","《急性心力衰竭急诊管理中国专家共识》（2022）","Guyton 等 Circulation《休克新定义（Guyton 2020）》"]}]},{"id":"critical","name":"危重症","rank":2,"summary":"以“器官支持 + 病因控制 + 避免医源性损伤”为原则：ARDS 以肺保护性通气（小潮气量、高 PEEP、低驱动压）为基石，结合俯卧位与限制液体；AKI 以 KDIGO 分期、去除肾毒性药物与容量优化为先，CRRT 用于血流动力学不稳定、容量过负荷、严重高钾/酸中毒与尿毒症并发症，且需把握“何时开始”的时机。","compare":[{"diseaseId":"em_aki_crrt","dx":"48 小时内血肌酐升高 ≥26.5 µmol/L，或 7 天内升至 ≥1.5 倍基线；伴尿量减少，需排除肾前/肾后因素","key":"AKI 是肾功能的器官层面评价（KDIGO 分期 + CRRT 指征），ARDS 是肺的器官层面评价（PaO₂/FiO₂ + 肺保护性通气）"},{"diseaseId":"em_ards","dx":"急性起病（<1 周）、双肺浸润影不能用积液/塌陷解释、PaO₂/FiO₂ ≤300 mmHg 且 PEEP/CPAP ≥5 cmH₂O","key":"ARDS 的起点是 PaO₂/FiO₂ 与影像，AKI 的起点是肌酐/尿量；二者常同属 MODS 并互相加重（肺-肾串话）"}],"diseases":[{"id":"em_ards","name":"急性呼吸窘迫综合征","aka":["ARDS","急性呼吸窘迫综合征","柏林定义"],"rank":1,"basic":{"define":"多种原因引起的肺内或肺外急性炎症性肺损伤，导致肺泡-毛细血管屏障破坏、非心源性肺水肿与进行性低氧血症；按柏林（Berlin）定义需急性起病、双肺浸润、低氧（PaO₂/FiO₂ ≤300 mmHg）且不能用液体过负荷/心衰完全解释。","risk":["肺炎（细菌、病毒、真菌）与吸入性肺损伤（首位病因）","脓毒症与脓毒性休克、严重创伤与多发伤","急性胰腺炎、大量输血、中毒（百草枯、烟雾吸入、胃内容物吸入）","酒精滥用、肥胖、高龄、机械通气时潮气量过大等加重因素","免疫抑制、高海拔/高压氧相关"],"epi":"重症监护病房中 ARDS 约占机械通气患者的 10%–15%，病死率轻/中/重度分别为 27%/32%/45%（柏林定义队列）；我国 ICU 流行病学调查提示 ARDS 病死率约 30%–40%；新型冠状病毒感染大流行期间 ARDS 发病率显著升高。"},"patho":"肺泡-毛细血管膜损伤后富含蛋白的液体与炎性细胞涌入肺泡，透明膜形成、Ⅱ 型上皮细胞损伤导致表面活性物质减少、微肺不张与肺顺应性下降；同时肺内死腔增大与血流分布不均造成分流（Qs/Qt 升高）与顽固性低氧。病变呈“不均匀分布”——依赖区实变与非依赖区相对正常，导致大潮气量更易造成容积伤（volutrauma）与气压伤/萎陷伤，呼吸机所致肺损伤（VILI）进一步释放炎症介质引起多器官衰竭。","dx":{"criteria":["起病时间：已知临床诱因后 1 周内新出现或加重的呼吸症状（柏林定义）。","影像：X 线或 CT 双肺浸润影，不能用胸腔积液、肺叶塌陷或结节完全解释（有条件用床旁超声评估）。","肺水肿来源：呼吸衰竭不能完全由心力衰竭或液体过负荷解释，必要时用超声心动图或 BNP 排除心源性肺水肿。","氧合程度：PEEP/CPAP ≥5 cmH₂O 时 PaO₂/FiO₂（P/F）≤300 mmHg 为 ARDS；轻度 200<P/F≤300、中度 100<P/F≤200、重度 ≤100 mmHg。","SpO₂/FiO₂（S/F）≤315 可替代 P/F 用于无条件动脉血气者（需 SpO₂ ≤97% 时）。","驱动压（Pplat − PEEP）>15 cmH₂O、机械功（mechanical power）升高者与病死率显著相关。"],"workup":["动脉血气 + PaO₂/FiO₂ 动态监测；计算死腔分数（Vd/Vt）评估预后","床旁胸部超声：B 线、胸膜滑动、实变与心功能；肺部超声可替代部分影像","胸部 CT：评估病变分布与依赖区可复张性、并发症（气胸、纵隔气肿）","超声心动图：排除心源性肺水肿、评估右心功能（合并肺栓塞时）","病原学：痰/支气管肺泡灌洗液培养、PCR（含病毒、PCP、军团菌）、血培养；必要时支气管镜检查","炎症标志物：CRP、降钙素原、铁蛋白、乳酸；排除弥漫性肺泡出血（BAL 进行性血性回洗液）"],"grading":"柏林分级：轻度 P/F 200–300；中度 100–200；重度 ≤100 mmHg（PEEP ≥5 cmH₂O）；按病因分为肺源性（直接）与肺外源性（间接）；按常规氧疗/无创/有创呼吸支持分层治疗强度。"},"ddx":[{"name":"AKI 与 CRRT 指征","point":"与本类中“AKI 与 CRRT”的鉴别点：ARDS 的核心是肺内分流与低氧（P/F 下降、双肺浸润），AKI 的核心是肌酐升高与尿量减少；二者常合并于脓毒症 (MODS)，需同时评估容量负荷对肺的影响。"},{"name":"心源性肺水肿","point":"端坐呼吸、双肺湿啰音、颈静脉怒张、BNP 升高、超声见左室收缩功能下降及 E/e' 升高；利尿/扩血管后迅速改善。"},{"name":"医院获得性肺炎（无 ARDS）","point":"发热、脓痰、局部实变与白细胞升高，但氧合下降程度较轻、PaO₂/FiO₂ >300 mmHg。"},{"name":"弥漫性肺泡出血","point":"咯血、贫血、BAL 进行性血性回洗液，多伴自身免疫病或抗凝相关。"},{"name":"急性嗜酸性粒细胞性肺炎","point":"外周血与 BAL 嗜酸性粒细胞显著升高，激素治疗反应迅速。"}],"tx":{"drug":[{"name":"静脉镇静（丙泊酚/咪达唑仑）+ 镇痛（芬太尼/瑞芬太尼）","dose":"丙泊酚 0.5–4 mg/kg/h 泵入，目标 RASS −1~0（俯卧位或严重吸气努力时 −3~−4）；芬太尼 25–100 µg/h 或瑞芬太尼 0.05–0.2 µg/kg/min","note":"镇痛优先（analgesia-first）；每日镇静中断评估拔管可能；丙泊酚丙泊酚输注综合征（PRIS）需警惕长时间大剂量","renal":"丙泊酚无肾调整；咪达唑仑代谢产物蓄积于肾衰致过度镇静","hepatic":"严重肝病丙泊酚减量；咪达唑仑半衰期延长","interact":"与阿片类协同抑制呼吸与血压"},{"name":"肌松药（顺阿曲库铵/罗库溴铵）","dose":"顺阿曲库铵 0.15 mg/kg 静推后 1–3 µg/kg/min 泵入，或罗库溴铵 0.6–1.2 mg/kg 静推；用于重度 ARDS 早期严重人机不同步，疗程 ≤48 小时","note":"中重度 ARDS 早期（P/F <150）可在深镇静后使用；需完全镇静并监测 TOF，避免ICU 获得性肌无力","renal":"顺阿曲库铵经霍夫曼消除，肾衰竭不受影响；罗库溴铵需减量","hepatic":"顺阿曲库铵肝功能不全无需调整","interact":"与氨基糖苷类、镁剂合用时神经肌肉阻滞作用增强"},{"name":"糖皮质激素（地塞米松）","dose":"地塞米松 6 mg qd 静注，共 10 天（新冠相关 ARDS 方案）；或甲泼尼龙 1–2 mg/kg/d 用于其他病因早期中重度 ARDS（证据较弱）","note":"仅建议用于新冠相关 ARDS 及部分早期中重度 ARDS；晚期纤维增殖期获益有限；注意继发感染与高血糖","renal":"无需调整","hepatic":"无需调整","interact":"与氟喹诺酮合用增加肌腱断裂风险；与胰岛素拮抗"},{"name":"液体管理（限制性策略）","dose":"稳定期尿量 ≥0.5 mL/kg/h 时，利尿（呋塞米 10–40 mg 静推或泵入）或限制入量，目标累积液体负平衡；休克期补液不在此限","note":"FACTT 研究：限制性液体策略可缩短机械通气时间；避免过快利尿致低灌注","renal":"AKI 期慎用大剂量利尿剂，无效时考虑 CRRT","hepatic":"肝硬化者平衡容量与腹水","interact":"与非甾体抗炎药合用增加肾损伤"},{"name":"一氧化氮吸入（iNO）/ 前列环素吸入","dose":"iNO 5–20 ppm 持续吸入；依前列醇 10–50 ng/kg/min 雾化（仅用于右心衰竭或顽固性低氧的挽救）","note":"仅改善氧合，不降低病死率；停用时可能反弹，需逐渐减停","renal":"无需调整","hepatic":"无需调整","interact":"与 PDE5 抑制剂（西地那非）合用可致严重低血压"}],"nonDrug":["肺保护性通气：潮气量 6 mL/kg 预测体重（PBW），平台压 ≤30 cmH₂O，驱动压 ≤15 cmH₂O；容许性高碳酸血症（pH ≥7.20）","PEEP 滴定：按 ARDSnet FiO₂-PEEP 表或食管压/应力指数个体化滴定，避免过度膨胀","俯卧位通气：中重度 ARDS（P/F <150）推荐每日 ≥12~16 小时，需团队培训与并发症预防（压疮、导管脱出）","保守氧疗：目标 SpO₂ 90%–96%、PaO₂ 55–80 mmHg，避免高氧","无创支持/经鼻高流量（HFNC）：轻度 ARDS 可试用，1–2 小时无改善及早插管（ROX 指数 ≤4.88 提示失败）","ECMO：重度 ARDS（P/F <80 mmHg 或 pH <7.25 伴 PaCO₂ 高）经优化通气后仍低氧，无禁忌时启动 VV-ECMO","病因治疗：抗感染按指南覆盖并降阶梯、胸部物理治疗、限制性输血（Hb <70 g/L）","早期肠内营养，24–48 小时内启动，目标 70%–80% 热卡"],"life":["出院后 6–12 个月复查肺功能与 6 分钟步行距离，约 1/3 遗留限制性通气障碍或弥散功能下降","ICU 后综合征：肌无力、认知障碍与 PTSD，需康复与心理干预","戒烟、流感/肺炎疫苗、避免粉尘与有害气体暴露","明确病因者（如吸入性肺炎、胰腺炎）针对病因随访"]},"prog":"柏林定义队列住院病死率约 40%（轻 27%、中 32%、重 45%）；国内 ICU 报道约 30%–40%。低驱动压通气、俯卧位、ECMO 中心化治疗可改善存活。存活者约 50% 存在长期肺功能损害与运动耐量下降，部分出 ICU 后 1 年内仍依赖氧疗。","refs":["中华医学会呼吸病学分会危重症医学学组《急性呼吸窘迫综合征机械通气指南》（2016）","中国医师协会呼吸医师分会《急性呼吸窘迫综合征诊断与治疗中国专家共识》","ARDS Definition Task Force《ARDS 柏林定义（JAMA 2012）》","ATS/ESICM/SCCM《成人 ARDS 患者机械通气指南（2017）》","《新冠感染相关急性呼吸窘迫综合征诊治中国专家共识》（2023）"]},{"id":"em_aki_crrt","name":"急性肾损伤与 CRRT 指征","aka":["AKI","Acute Kidney Injury","连续性肾脏替代治疗","CRRT"],"rank":2,"basic":{"define":"7 天内血肌酐升高 ≥1.5 倍基线、48 小时内升高 ≥26.5 µmol/L（0.3 mg/dL），或尿量 <0.5 mL/kg/h 持续 6 小时以上的临床综合征；CRRT 是以连续性模式（CVVH/CVVHD/CVVHDF）缓慢清除溶质与液体、血流动力学耐受性好的肾脏替代方式。","risk":["脓毒症/脓毒性休克（最常见病因）、大手术（尤其心脏手术）、创伤与横纹肌溶解","肾毒性药物（氨基糖苷类、万古霉素、两性霉素 B、造影剂、NSAIDs）与中药肾毒成分（马兜铃酸）","低血容量、心力衰竭、肝硬化（肝肾综合征）与容量过负荷","慢性肾病、糖尿病、高龄、多器官衰竭（MODS）"],"epi":"住院患者 AKI 发生率约 10%–20%，ICU 患者可达 30%–60%，其中约 5%–10% 需肾脏替代治疗；AKI 使住院病死率升高 3–5 倍，约 10% 存活者遗留慢性肾脏病。我国重症 AKI 中脓毒症相关占比最高。"},"patho":"不同类型 AKI 机制不同：肾前性以有效循环血量减少、肾灌注下降为著（初期可逆）；肾实质性以缺血/毒性损伤小管上皮、炎症与微循环障碍为主（急性肾小管坏死），小管阻塞与回漏致滤过压下降；肾后性为尿路梗阻致逆行压力升高。CRRT 通过弥散（透析液）清除小分子，通过对流（置换液）清除中分子，可精确控制容量与电解质，并清除炎症介质（高流量 CVVH 的“免疫调节”作用证据有限）。","dx":{"criteria":["KDIGO 1 期：血肌酐升高 ≥26.5 µmol/L（48 小时内）或升至基线的 1.5–1.9 倍；尿量 <0.5 mL/kg/h 持续 6–12 小时。","KDIGO 2 期：血肌酐升至基线 2.0–2.9 倍；尿量 <0.5 mL/kg/h 持续 ≥12 小时。","KDIGO 3 期：血肌酐升至基线 ≥3 倍，或 ≥353.6 µmol/L（4 mg/dL）伴急性升高 ≥44.2 µmol/L，或开始肾脏替代治疗，或（<18 岁）eGFR <35 mL/min/1.73m²；尿量 <0.3 mL/kg/h ≥24 小时或无尿 ≥12 小时。","CRRT 启动指征：① 严重高钾血症（K⁺ ≥6.5 mmol/L 或心电图改变且内科治疗无效）；② 严重酸中毒（pH <7.20，HCO₃⁻ <12 mmol/L）；③ 尿毒症并发症（心包炎、脑病、出血倾向）；④ 容量过负荷合并心衰/ARDS 且利尿无效；⑤ 可透析毒物中毒（甲醇、乙二醇、锂、水杨酸）；⑥ 高分解代谢（BUN >25–30 mmol/L）。","“何时开始”原则：无危及生命指征的 AKI 不推荐早期常规启动（STARRT-AKI、AKIKI 研究示早期无获益），出现上述指征或病情急性恶化时启动。"],"workup":["血肌酐（动态）、尿素氮、电解质、血气、血渗透压；尿常规（管型、红细胞）、尿钠与 FEna（肾前性 FEna <1%，ATN 常 >2%）","床旁泌尿系超声：肾积水提示肾后性梗阻，需紧急解除","容量状态评估：下腔静脉超声、肺部 B 线、被动抬腿试验与体重变化","肌酸磷酸激酶（横纹肌溶解）、免疫学筛查（ANCA、抗 GBM 抗体等）与补体，必要时肾活检","药物核对与肾毒性药物停用；造影剂相关 AKI 评估","CRRT 相关：滤器前/后血样、滤器凝血监测、导管功能、CRRT 治疗剂量（20–25 mL/kg/h）"],"grading":"KDIGO 1–3 期；按病因分为肾前性、肾实质性（ATN、急性间质性肾炎、肾小球疾病、血管性）、肾后性；按尿量（少尿/非少尿）与是否需要 RRT 分层。"},"ddx":[{"name":"急性呼吸窘迫综合征","point":"与本类中“ARDS”的鉴别点：AKI 以肌酐升高、少尿与电解质紊乱为核心，ARDS 以 PaO₂/FiO₂ 下降与双肺浸润为核心；二者常同属脓毒症 MODS，容量过负荷会同时加重两者，需同步行 CRRT 容量控制。"},{"name":"慢性肾脏病急性加重","point":"既往 CKD 病史，肾脏缩小（超声皮质变薄），贫血与高磷，肌酐基线已升高；需以基线计算相对升高。"},{"name":"肾前性氮质血症","point":"容量不足、BUN/Cr 升高 >20:1、FEna <1%，补液后肌酐迅速下降；肾实质性损伤补液反应差。"},{"name":"梗阻性肾病","point":"超声见肾积水与输尿管扩张，突发少尿或波动性尿量，解除梗阻后改善（常用于急诊评估）。"},{"name":"横纹肌溶解相关性 AKI","point":"肌酸磷酸激酶显著升高、肌红蛋白尿（酱油色尿），尿潜血阳性但镜检无红细胞。"}],"tx":{"drug":[{"name":"呋塞米（速尿）","dose":"20–40 mg 静推，必要时 1–4 mg/min 持续泵入；或联合噻嗪类/螺内酯用于利尿剂抵抗","note":"仅用于容量过负荷，不能改善 AKI 预后；每次加量前先评估容量反应；袢利尿剂与 AKI 风险相关","renal":"AKI 中需加量，且监测血钾、血尿酸与耳毒性","hepatic":"肝硬化腹水需联合白蛋白并监测电解质与肾功能","interact":"与氨基糖苷类合用耳毒性增加；与 NSAIDs 合用利尿效果下降"},{"name":"碳酸氢钠","dose":"严重酸中毒 pH <7.20 时，5% 碳酸氢钠 100–150 mL 缓慢静滴，依据血气调整；不推荐常规用于造影剂肾病预防","note":"目标 pH ≥7.20–7.25；避免过量致高钠与碱中毒；与钙剂同用间隔冲管","renal":"肾功能衰竭易致容量与钠负荷","hepatic":"无需调整","interact":"与肾上腺素、钙剂同通路禁忌"},{"name":"高钾血症处理（葡萄糖酸钙/胰岛素+葡萄糖/沙丁胺醇）","dose":"10% 葡萄糖酸钙 10–20 mL 缓慢静推（5–10 分钟，心电图增宽时优先）；胰岛素 10 U + 50% 葡萄糖 25 g 静推；沙丁胺醇 10–20 mg 雾化；详见“高钾血症”条目","note":"上述均为临时措施，需联合降钾树脂或紧急 RRT 以彻底清除钾","renal":"肾衰竭者药物清除钾效果有限，RRT 指征更明确","hepatic":"无需调整","interact":"与 β 受体阻滞剂、ACEI/ARB 合用致血钾进一步升高"},{"name":"万古霉素（剂量按肾功能调整）","dose":"按肌酐清除率调整：CrCl >90 者 15–20 mg/kg q8–12h；CrCl 30–60 者 q24h；AKI/CRRT 时遵说明书并按血药谷浓度（10–20 µg/mL，严重感染 15–20）滴定","note":"CRRT 中建议提高负荷剂量并每 24 小时监测谷浓度","renal":"AKI 需延长间隔或减量，并监测谷浓度","hepatic":"无需调整","interact":"与氨基糖苷类、两性霉素 B 合用肾毒性叠加"},{"name":"CRRT 置换液抗凝（枸橼酸局部抗凝）","dose":"4% 枸橼酸钠按血流速 1.2–1.7 mmol/L 血流量输注于滤器前，经后置换补钙（10% 葡萄糖酸钙 5–10 mL/h）维持离子钙 >1.1 mmol/L","note":"出血风险高者首选局部枸橼酸抗凝；监测总钙/离子钙比值 >2.5 提示枸橼酸蓄积","renal":"肾衰竭者枸橼酸蓄积风险增加，需监测","hepatic":"严重肝病枸橼酸代谢减低，慎用","interact":"与含钙静脉药物同通路需注意"}],"nonDrug":["立即停用肾毒性药物与造影剂，优化容量：低血容量者补液，容量过负荷者利尿或限制入量","CRRT 模式：CVVHDF 最常用，血流速 4–6 mL/kg/min；剂量 20–25 mL/kg/h（脓毒症可至 35 mL/kg/h 但无明确获益）","血管通路：颈内静脉或股静脉（14–16 Fr 双腔导管），床旁超声引导，股静脉路径不影响导管留置时间","肾后性梗阻：经皮肾穿刺造瘘或输尿管支架紧急解除","高钾、酸中毒、尿毒症心包炎的药物治疗顺序：钙剂稳定心肌→胰岛素/葡萄糖转移→清除（RRT）","药物剂量核对：CRRT 患者多数按“低清除”与蛋白结合率重新计算，抗菌药参考 CRRT 剂量表"],"life":["出院后 1–3 个月复查肌酐与尿蛋白，评估 CKD 进展；避免 NSAIDs、造影剂与中药肾毒成分","恢复期容量与电解质管理，糖尿病与高血压控制以延缓 CKD","需要长期透析者转介肾内科规划血管通路，并宣教饮食与服药","RRT 短期并发症：滤器凝血、低体温、电解质紊乱与导管相关感染"]},"prog":"ICU AKI 病死率约 30%–50%，需要 RRT 的 AKI 病死率可达 50%–70%。约 90% 存活者在 1 年内肾功能部分恢复，但 10%–20% 进展为 CKD，需要长期透析者占 5%–10%。早期识别、避免肾毒性药、合理液体管理与及时启动 CRRT 可改善预后。","refs":["KDIGO《急性肾损伤临床实践指南（AKI 2012）》","中华医学会肾脏病学分会《成人急性肾损伤诊断与治疗指南》（2015）","中国医师协会肾脏内科医师分会《连续性肾脏替代治疗临床应用指南》（2021）","中国重症血液净化协作组《重症患者连续性肾脏替代治疗专家共识》","中华医学会急诊医学分会《急性肾损伤急诊诊治专家共识》"]}]},{"id":"toxic","name":"中毒与环境","rank":3,"summary":"以“脱离暴露—去污—解毒—器官支持”为轴：毒物类别决定去污与解毒剂选择，对乙酰氨基酚需按血浆浓度或时间窗启动 NAC；环境与化学中毒需识别特异性表现（CO 的血氧与代谢性酸中毒、烧伤的 TBSA 计算与 Parkland 公式、高钾的心电图改变），所有患者均需评估气道、酸碱与电解质紊乱并防遗漏合并损伤。","compare":[{"diseaseId":"em_apap","dx":"有意或过量服用含对乙酰氨基酚药物，4 小时后血浆浓度高于 Rumack-Matthew 曲线，或符合 NAC 启动时间点","key":"对乙酰氨基酚毒性主要是肝细胞坏死（ALT/AST 显著升高），早期可无症状；与 CO 中毒的神经-低氧表现和烧伤的皮肤损伤不同"},{"diseaseId":"em_co","dx":"燃烧环境暴露史、头痛/恶心/意识障碍、SpO₂ 正常但 COHb >3%（吸烟者 >5%）或 >10%（严重）","key":"CO 中毒的脉氧不可靠、需查 COHb；缺血性脑病与心肌损伤突出，需高浓度氧直至 COHb <5%"},{"diseaseId":"em_burn","dx":"皮肤热力/化学损伤，按“九分法”估 TBSA，成人超过 20% 需按 Parkland 公式补液","key":"烧伤以 TBSA 与深度分级并用 2–4 mL/kg/%TBSA 补液；高钾血症则以血钾与心电图（T 波高尖、P 波消失）判定并需离子转移"},{"diseaseId":"em_hyperk","dx":"血钾 >5.5 mmol/L（危重多 >6.5），心电图见 T 波高尖、PR 延长、QRS 增宽甚至正弦波，可伴肌无力与心律失常","key":"心电图改变可先于血钾数值恶化；钙剂稳定心肌细胞膜是第一步，再促钾内移与排钾"}],"diseases":[{"id":"em_apap","name":"对乙酰氨基酚中毒","aka":["Paracetamol Poisoning","醋氨酚中毒","APAP"],"rank":1,"basic":{"define":"过量摄入对乙酰氨基酚（成人单次 >7.5 g 或 >150 mg/kg；儿童 >150 mg/kg）或多次超量摄入，经肝 CYP2E1 代谢生成的 NAPQI 超过谷胱甘肽清除能力而致肝细胞坏死的中毒；早期可无症状，可进展为急性肝衰竭。","risk":["有意自伤服药，青少年与年轻女性多见","含对乙酰氨基酚的复方感冒药、镇痛药叠加服用或与酒精同时摄入","营养不良、禁食、慢性肝病、诱导 CYP 药物（卡马西平、苯妥英、异烟肼、利福平）者毒性阈值降低","儿童误服与哺乳期用药过量"],"epi":"对乙酰氨基酚是世界范围内药物过量最常见的原因之一；我国药物性肝损伤中，解热镇痛药相关 DILI 占比约 20%，对乙酰氨基酚相关急性肝衰竭病例逐年增加。规范 NAC 治疗者死亡/肝移植率 <5%，延误治疗则可升至 20%–30%。"},"patho":"对乙酰氨基酚大部分经葡萄糖醛酸化与硫酸化代谢，约 5%–10% 经 CYP2E1 生成活性中间产物 NAPQI。NAPQI 与肝细胞谷胱甘肽（GSH）结合解毒并经尿排出；过量时 GSH 耗竭，NAPQI 与细胞内蛋白共价结合致线粒体氧化应激、膜脂质过氧化与肝细胞坏死（以小叶中央区为主），严重时发生急性肝衰竭、脑水肿、凝血功能障碍与急性肾损伤。","dx":{"criteria":["服药剂量：成人单次 >7.5 g 或 >150 mg/kg；儿童 >150 mg/kg 或 4 小时内 >7.5 g；多次超量（>4 g/日超过 24 小时或 >75 mg/kg/日）需按时间窗评估。","血药浓度判读：单次急性摄入后 ≥4 小时，用 Rumack-Matthew 曲线：4 小时 150 µg/mL（1000 µmol/L）、6 小时 75 µg/mL、9 小时 37.5 µg/mL、12 小时 18.8 µg/mL、16 小时 9.4 µg/mL 等；超过该线需 NAC。","不可判读曲线者（服药时间不明、多次用药、缓释剂、儿童）按临床与肝功能评估，ALT 升高即启动 NAC。","肝损伤判定：ALT/AST >1000 U/L 提示明显肝损伤；伴 INR >1.5、低血糖、乳酸升高、脑病为急性肝衰竭（ALF）表现。","中毒分期：Ⅰ期（0–24 小时，无症状或恶心呕吐）、Ⅱ期（24–72 小时，ALT 升高）、Ⅲ期（72–96 小时，ALF）、Ⅳ期（恢复）。"],"workup":["服药剂量、时间、剂型（缓释片需额外考虑）与共服药物核实；毒物筛查（阿片类、苯二氮䓬类、水杨酸、酒精）","血浆对乙酰氨基酚浓度（4 小时及之后），标注具体采血时间点","肝功能（ALT、AST、胆红素）、INR、乳酸、血氨、血糖、肌酐、电解质","血气分析：早期可无异常，严重者代谢性酸中毒与乳酸升高","腹部超声与甲胎蛋白（评估肝衰竭/肝移植）；凝血因子 V 水平可用于预后判读","尿常规：血尿与肌红蛋白（合并横纹肌溶解或肾损伤）"],"grading":"按 Rumack-Matthew 曲线分层（“高于治疗线需 NAC”）；按肝功能状态分为无肝损伤、轻度肝损伤、急性肝衰竭（King's College 标准评估肝移植：pH <7.30，或 INR >6.5/PT >100 s + 肌酐 >300 µmol/L + 肝性脑病 Ⅲ/Ⅳ 级）。"},"ddx":[{"name":"一氧化碳中毒","point":"与本类中“一氧化碳中毒”的鉴别点：CO 中毒有燃烧环境暴露，意识障碍与脑缺血表现突出，COHb 升高，肝酶多正常或轻度升高；APAP 中毒以肝损伤为主，早期可无症状且 COHb 正常。"},{"name":"急性病毒性肝炎","point":"发热、乏力、黄疸、肝酶升高伴病毒学标志物阳性（甲型/乙型/戊型），无过量服药史。"},{"name":"其他药物性肝损伤（抗结核药、中药）","point":"用药史与药物性肝损伤因果关系评估（RUCAM），停药后肝酶改善；需与 APAP 剂量核对。"},{"name":"急性酒精性肝炎","point":"长期饮酒史、AST/ALT 比值 >2、GGT 与胆红素升高，常有肝大与腹水。"},{"name":"急性胆管炎","point":"发热+腹痛+黄疸（Charcot 三联征），腹部超声见胆管扩张，需抗感染与引流。"}],"tx":{"drug":[{"name":"乙酰半胱氨酸（NAC）静脉方案","dose":"成人 21 小时静脉方案：首剂 150 mg/kg 溶于 5% 葡萄糖 200 mL 静滴 1 小时；第二剂 50 mg/kg 溶于 500 mL 静滴 4 小时；第三剂 100 mg/kg 溶于 1000 mL 静滴 16 小时。疑肝损伤/ALF 者持续输注 100 mg/kg/24h 直至转氨酶下降","note":"时机最关键：距服药 8–10 小时内给药肝损伤风险显著下降；出现过敏样/类组胺反应（潮红、支气管痉挛）时减慢输注并抗组胺处理","renal":"肾功能不全无需调整剂量，但需监测容量","hepatic":"肝衰竭患者持续输注；NAC 可改善肝微循环","interact":"与活性炭同用时先洗胃后给药，口服 NAC 需与活性炭间隔 1 小时"},{"name":"乙酰半胱氨酸口服方案","dose":"首剂 140 mg/kg 口服/经胃管，之后 70 mg/kg q4h，共 17 次（72 小时）；口服呕吐者 1 小时后补服","note":"适合无静脉通路且意识清醒者；我国多用静脉方案","renal":"无需调整","hepatic":"无需调整","interact":"与活性炭同用须间隔"},{"name":"药用炭（活性炭）","dose":"1 g/kg（成人常用 50 g）口服或经胃管，宜在服药 1–4 小时内；缓释对乙酰氨基酚可延长至 8 小时","note":"意识障碍或气道未保护者禁用（误吸风险）；不与 NAC 同时给予","renal":"无需调整","hepatic":"无需调整","interact":"可吸附多种药物与 NAC"},{"name":"肝衰竭支持用药（按需）","dose":"乳果糖 30 mL q6h 口服（肝性脑病）；PPI 预防消化道出血；10% 葡萄糖输注纠正低血糖；支链氨基酸与营养支持遵医嘱","note":"需监测颅内压（脑水肿）与凝血，避免使用镇静药","renal":"慎用大剂量乳果糖致腹泻与电解质紊乱","hepatic":"需按 Child-Pugh 调整用量","interact":"遵说明书"}],"nonDrug":["气道与循环评估：意识障碍、呕吐或误吸风险高者插管保护气道后洗胃","洗胃：仅在服药 1 小时内（缓释剂可延至 4 小时）且毒物量大时考虑，宜用大孔胃管，洗胃液温度 37 ℃，避免误吸","缓释片中毒：延长 NAC 疗程并复查 4–6 小时肝功能与转氨酶","急性肝衰竭处理：ICU 监护、颅内压监测与甘露醇降颅压、纠正凝血（INR >2 出血时用维生素 K/FFP）、评估肝移植时机（King's College 标准或 MELD）","人工肝支持（血浆置换、MARS）用于移植前桥接，需在移植中心评估","精神心理评估与自杀风险评估（有意自伤者），必要时收入精神科"],"life":["出院前复查肝功能与 INR（症状改善后 2–3 天）；中毒症状消失、ALT 下降或稳定方可出院","公众教育与处方管理：避免复方感冒药叠加、酒精期间避免服用对乙酰氨基酚","自杀未遂者心理干预与随访，家庭药物管理","慢性用药者教育每日总量上限（成人 4 g/日，肝病/饮酒者 2 g/日）"]},"prog":"规范 NAC 治疗 8–10 小时内给药者病死率 <1%；延误治疗者急性肝衰竭发生率达 10%–20%，ALF 病死率 30%–50%，需肝移植。约 30% 患者出现暂时性肾损伤（多可恢复）。肝功能随访正常后远期预后良好。","refs":["中华医学会急诊医学分会中毒学组《急性中毒诊断与治疗中国专家共识》（2016）","中国医师协会急诊医师分会《急性中毒临床诊断与治疗指南》","《对乙酰氨基酚中毒诊治中国专家共识》","AASLD《急性肝衰竭管理指南》（2023）","AACT《乙酰半胱氨酸治疗对乙酰氨基酚中毒专家共识》"]},{"id":"em_co","name":"一氧化碳中毒","aka":["CO Poisoning","煤气中毒","Carbon Monoxide"],"rank":2,"basic":{"define":"吸入不完全燃烧产生的含碳气体（CO）后，CO 与血红蛋白竞争性结合生成碳氧血红蛋白（COHb），致组织缺氧为主的急性中毒；严重者可出现脑水肿、心肌损伤与迟发性脑病。","risk":["冬季燃煤取暖、燃气热水器安装/通风不当、炭火取暖","火灾烟雾吸入、车辆尾气与车库长时间怠速、柴油发电机室内使用","职业暴露（乙炔焊、燃气铸造、矿井）","老年、心血管病、贫血、妊娠与儿童更易发生严重中毒"],"epi":"我国每年一氧化碳中毒病例数以万计，冬季为高发期，多与燃煤/燃气取暖有关；重度中毒病死率约 1%–3%，幸存者中迟发性脑病发生率约 10%–30%（国内报道），高压氧治疗可降低其发生。"},"patho":"CO 与血红蛋白亲和力约为氧的 240 倍，形成 COHb 并左移氧解离曲线，致组织释氧障碍；CO 还与肌红蛋白、线粒体细胞色素 c 氧化酶结合，抑制细胞呼吸并产生脂质过氧化。脑与心脏氧需量最高、最先受损：轻度致头痛、恶心，重度出现脑水肿、去皮层状态、心肌缺血与心律失常；神经白质脱髓鞘与基底节病变是迟发性脑病的基础。COHb 半衰期约 4–6 小时（室内空气），吸高浓度氧时约 60–90 分钟，高压氧（2.5–3 ATA）可缩短至 20–30 分钟。","dx":{"criteria":["明确的含碳燃料不完全燃烧环境暴露史（多人同时发病更提示）","临床表现：头痛、头晕、恶心、乏力（轻）；意识障碍、抽搐、昏迷、皮肤樱桃红（少见）、心肌缺血（重）","COHb 测定：脉搏碳氧血氧仪（SpCO）或血气 COHb；吸烟者基线可达 5%–10%，非吸烟者 >3% 有意义；严重中毒 >25%–30%，但 COHb 水平与症状不完全平行","脉搏血氧饱和度（SpO₂）不能可靠反映缺氧（COHb 使 SpO₂ 假性正常）","代谢性酸中毒、乳酸升高与心肌损伤标志物升高提示重度中毒"],"workup":["血气分析（含 COHb、乳酸）与血常规","心电图与心肌肌钙蛋白（约 25%–30% 患者出现心肌损伤）","颅脑 CT：基底节区低密度、脑白质脱髓鞘（迟发性脑病）","脑电图与头颅 MRI（迟发性脑病评估）","拟高压氧者行胸部 X 线或 CT、眼底检查（排除禁忌）","确认环境来源并联系消防/燃气公司（防止二次中毒）"],"grading":"按临床表现分级：轻度（头痛、头晕、恶心，COHb <10%–20%）；中度（意识模糊、运动失调、胸闷，COHb 20%–40%）；重度（昏迷、抽搐、呼吸衰竭，COHb >40% 或伴心肌/神经系统损伤）；高压氧指征按症状与 COHb 综合判定。"},"ddx":[{"name":"对乙酰氨基酚中毒","point":"与本类中“对乙酰氨基酚中毒”的鉴别点：CO 中毒有燃烧环境暴露与 COHb 升高，以神经与心肌损伤为主；APAP 中毒早期可无症状，之后以转氨酶显著升高为特征。"},{"name":"急性脑血管病（脑梗死/脑出血）","point":"偏瘫、失语等局灶体征，头颅 CT/MRI 见梗死或出血，无 COHb 升高。"},{"name":"低血糖昏迷","point":"出汗、心悸、意识障碍，指尖血糖低，葡萄糖静推后迅速恢复。"},{"name":"缺氧性脑病（窒息、溺水）","point":"明确窒息史，PaO₂ 降低但 COHb 正常。"},{"name":"其他气体中毒（氰化物、硫化氢）","point":"火灾中毒常有氰化物共中毒（乳酸显著升高、高动力循环），需同时考虑羟钴胺解毒；硫化氢暴露有腐蛋味。"}],"tx":{"drug":[{"name":"高浓度氧疗（100% 氧气）","dose":"非重复呼吸面罩或储氧面罩 15 L/min，或气管插管后纯氧；持续至 COHb <5%（吸烟者 <10%）且症状缓解，通常 >6 小时","note":"氧疗是最基础的治疗，可缩短 COHb 半衰期；孕妇与心肌损伤者延长","renal":"无需调整","hepatic":"无需调整","interact":"无"},{"name":"高压氧（HBO）","dose":"2.5–3.0 ATA，每次 60–90 分钟，每日 1–2 次，疗程按病情 5–10 次","note":"适应证：意识障碍/昏迷、COHb >25%（孕妇 >15%–20%）、持续神经系统症状、心肌缺血或乳酸 >5 mmol/L；尽早开始获益最大","renal":"无需调整","hepatic":"无需调整","interact":"无（需先排除未处理的气胸）"},{"name":"甘露醇（脑水肿）","dose":"0.25–0.5 g/kg 静滴（20% 溶液，15–30 分钟内），q4–6h；或 3% 高渗盐水 100–200 mL 按需","note":"仅在明确脑水肿/颅内压升高时使用；监测尿量与渗透压","renal":"肾衰竭者慎用，改用高渗盐水并监测血钠","hepatic":"无需调整","interact":"与肾毒性药合用增加肾损伤"},{"name":"地西泮/咪达唑仑（抽搐控制）","dose":"地西泮 10 mg 缓慢静推（≤2 mg/min）或咪达唑仑 5–10 mg 静推；持续抽搐者咪达唑仑 0.05–0.2 mg/kg/h 泵入","note":"抽搐加重脑氧耗与脑水肿，需在气道保护下控制","renal":"咪达唑仑代谢产物在肾衰蓄积","hepatic":"肝病者减量","interact":"与阿片类协同抑制呼吸"},{"name":"碳酸氢钠","dose":"仅用于严重代谢性酸中毒 pH <7.20 或高钾时，50–100 mL 缓慢静滴，按血气调整","note":"不作为常规解毒；需先纠正缺氧与心肌支持","renal":"无需调整","hepatic":"无需调整","interact":"与钙剂同通路禁忌"}],"nonDrug":["立即脱离现场、开窗通风，救援者需佩戴自给式呼吸器避免二次中毒","气道与循环支持：昏迷、误吸或呼吸衰竭者气管插管；心律失常与心肌损伤者心电监护","高压氧舱治疗：按分级与指征尽快实施，需评估未处理气胸、中耳气压伤等禁忌","迟发性脑病：综合康复（运动、认知、高压氧）、营养神经与抗帕金森治疗，需长期随访","火灾烟雾中毒：联合评估氰化物中毒、气道热损伤与吸入性损伤，必要时气道湿化与支气管镜","孕妇重症：母体高压氧有助于胎儿氧供，产科与重症共同管理"],"life":["出院后 4–6 周神经心理评估，警惕迟发性脑病（记忆下降、步态异常、人格改变）","安装一氧化碳报警器，检查燃气热水器与烟道，避免室内明火取暖","急救教育：封闭空间内多人同时头痛、恶心时迅速开窗撤离","职业暴露者监测 COHb 并改善通风"]},"prog":"轻中度中毒经氧疗后预后良好；重度中毒（昏迷、COHb >40%）病死率约 1%–3%，约 10%–30% 出现迟发性脑病，多数在数月内改善，部分遗留认知与运动障碍。高龄、昏迷时间长、脑水肿与基线心血管病为不良预后因素；早期高压氧可降低迟发性脑病风险。","refs":["中华医学会高压氧医学分会《一氧化碳中毒临床治疗指南》（2012）","中华医学会急诊医学分会中毒学组《急性一氧化碳中毒诊治专家共识》","中国医师协会急诊医师分会《急性中毒诊断与治疗中国专家共识》（2016）","《一氧化碳中毒迟发性脑病诊治专家共识》","Undersea and Hyperbaric Medical Society《CO 中毒高压氧治疗适应证》"]},{"id":"em_burn","name":"烧伤面积评估与液体复苏","aka":["Burn","热烧伤","烧伤休克","Parkland 公式"],"rank":3,"basic":{"define":"热力、化学、电或放射线造成的皮肤及深部组织损伤；烧伤休克源于伤后毛细血管通透性增加致血浆外渗与低血容量，成人 TBSA >20%（儿童 >10%）即需按公式进行液体复苏。","risk":["火焰、热液、蒸汽与热金属接触；化学烧伤（强酸/强碱、氢氟酸）；电击伤与闪电伤","密闭空间火灾伴吸入性损伤（上气道热损伤、CO 与氰化物中毒）","老年、婴幼儿与基础心肺病者液体耐受性差，易发生容量过负荷","合并创伤（爆炸伤）与烟雾吸入致 ARDS"],"epi":"我国每年烧伤住院患者达数十万例，成人以火焰与热液烧伤为主；TBSA ≥20% 的成人烧伤约 10%–20% 需重症监护；合并吸入性损伤者病死率增加 2–3 倍；规范补液（Parkland 公式）与早期切痂可显著改善存活。"},"patho":"热损伤致蛋白变性、细胞坏死，形成凝固带与淤滞带（可逆区）；局部释放组胺、缓激肽与前列腺素使微血管通透性剧增，血浆与蛋白外渗到组织间隙，48 小时达高峰，导致有效循环血量骤减、血液浓缩与低血容量性休克（烧伤休克）。同时全身炎症反应综合征（SIRS）可进展为脓毒症与 MODS；电击伤可致深部肌肉坏死、横纹肌溶解与高钾。密闭空间火灾需同时警惕 CO 与氰化物中毒。","dx":{"criteria":["TBSA 估算（成人九分法）：头颈 9%、双上肢各 9%（共 18%）、躯干前 18%、躯干后 18%、双下肢各 18%（共 36%）、会阴 1%；手掌法：患者本人手掌及手指 ≈1% TBSA。","儿童九分法调整：头颈 18%、双下肢各 13.5%；婴幼儿与儿童宜用 Lund-Browder 图。","深度分级：Ⅰ 度（红斑、无水疱、痛）、浅Ⅱ 度（水疱、基底潮红、剧痛）、深Ⅱ 度（水疱小、基底苍白红白相间、痛觉减退）、Ⅲ 度（焦痂、蜡白/炭化、无痛觉）。","吸入性损伤提示：面部/口鼻周围烧伤、声音嘶哑、碳末痰、呛咳、呼吸困难、密闭空间烧伤史，需尽早纤维支气管镜。","补液指征：成人 TBSA >20%、儿童 >10% 按 Parkland 公式：伤后第一个 24 小时 4 mL × 体重(kg) × TBSA(%)，前 8 小时输入总量的一半，余量后 16 小时输入；第二个 24 小时以胶体/晶体调整（常用 0.5–1 mL/kg/%TBSA）。"],"workup":["TBSA 与深度评估（九分法/Lund-Browder），记录体重与伤后时间","血红蛋白与血细胞比容（血液浓缩）、电解质、血糖、血气、乳酸","肌酸磷酸激酶与肌红蛋白尿（电击伤/深度烧伤）、肾功能与尿量","碳氧血红蛋白与乳酸（密闭空间火灾）；疑氰化物中毒查乳酸与中心静脉血氧饱和度","心电图（电击伤、老年人）与胸片；纤维支气管镜评估吸入性损伤","创面培养（后期感染评估）与破伤风免疫状态"],"grading":"按 TBSA（<10%、10%–19%、20%–29%、30%–49%、50%–69%、70%–89%、≥90%）与深度分类；符合美国烧伤协会（ABA）标准者需转诊烧伤中心（TBSA >20%、面部/手/会阴/关节烧伤、吸入性损伤、电击伤、化学烧伤及特殊人群）。"},"ddx":[{"name":"高钾血症","point":"与本类中“高钾血症”的鉴别点：烧伤（尤其电击伤与深度烧伤）可因肌肉坏死致高钾，但以 TBSA 与创面为核心；高钾血症则以血钾 >5.5 mmol/L 与心电图改变为判据，以离子转移为主，补液不解决钾问题。"},{"name":"中毒性表皮坏死松解症（TEN）","point":"药物诱因，大面积表皮剥脱（Nikolsky 征阳性），黏膜受累；需烧伤样液体管理但病因是免疫性，需停用可疑药物与免疫治疗。"},{"name":"接触性皮炎","point":"局部红斑、瘙痒，无水疱或焦痂，无全身炎症反应。"},{"name":"坏死性筋膜炎","point":"进行性皮肤坏死、捻发音、剧痛与全身毒性，需紧急清创；与烧伤创面感染需鉴别。"},{"name":"电击伤相关心肌损伤","point":"电击后出现室颤/室速、ST-T 改变，需心电监护与心肌酶；属电击伤并发症需与热烧伤区别。"}],"tx":{"drug":[{"name":"乳酸林格液（Parkland 公式）","dose":"伤后第一个 24 小时：4 mL × 体重(kg) × TBSA(%)，前 8 小时给一半（从伤后时间起算），后 16 小时给另一半；第二个 24 小时按尿量调整，常用 0.5–1 mL/kg/%TBSA","note":"成人目标尿量 0.5–1 mL/kg/h（儿童 1–2 mL/kg/h）；超过计算量 1.5 倍仍少尿应排查吸入性损伤、腹腔间隙综合征等而非一味加量","renal":"肾功能不全者监测容量，必要时行 CRRT","hepatic":"严重肝病者慎用含乳酸液体（乳酸代谢障碍）","interact":"遵说明书"},{"name":"吗啡（镇痛）","dose":"2–5 mg 缓慢静推，按需 q2–4h；或芬太尼 25–50 µg 静推；创面处理前按需加量","note":"烧伤疼痛剧烈，需充分镇痛；老年与呼吸抑制风险者减量并监测","renal":"肾功能不全者吗啡代谢产物 M6G 蓄积，改用芬太尼","hepatic":"肝病者减量","interact":"与苯二氮䓬类合用呼吸抑制叠加"},{"name":"破伤风类毒素/人免疫球蛋白","dose":"未完成基础免疫者：破伤风类毒素 0.5 mL 肌注；污染创面且免疫史不清者加破伤风人免疫球蛋白 250 IU 肌注（不同部位）","note":"烧伤创面属污染创口，常规评估免疫状态","renal":"无需调整","hepatic":"无需调整","interact":"遵说明书"},{"name":"碳酸氢钠（碱化尿液）","dose":"肌红蛋白尿/血红蛋白尿时：5% 碳酸氢钠 100–150 mL 静滴，维持尿 pH >6.5；不常规用于烧伤","note":"仅在横纹肌溶解伴色素尿时使用；监测血 pH 与血钙（碱中毒致低钙手足搐搦）","renal":"AKI 时慎用容量负荷","hepatic":"无需调整","interact":"与钙剂同通路禁忌"},{"name":"葡萄糖酸钙凝胶（氢氟酸烧伤局部）","dose":"2.5% 葡萄糖酸钙凝胶局部涂敷并按摩；深部损伤可用 10% 葡萄糖酸钙皮下注射或动脉内灌注（遵烧伤中心方案）","note":"氢氟酸致低钙血症与致命性心律失常，需监测血钙与心电图","renal":"无需调整","hepatic":"无需调整","interact":"遵说明书"}],"nonDrug":["立即脱离热源、去除衣物与饰品，大面积烧伤用清洁湿敷覆盖，避免低体温","气道：吸入性损伤或面部/颈部烧伤者尽早气管插管（水肿可迅速进展）","创面处理：清创、减张切开（环形焦痂影响灌注或通气时行焦痂切开术）、磺胺嘧啶银或含银敷料覆盖","早期切痂与植皮：深度烧伤在液体复苏稳定后 3–7 天内行切痂，降低脓毒症风险","镇痛与镇静、营养支持（热卡按 Curreri/Harris-Benedict 估算，蛋白 1.5–2 g/kg/d）","疑似 CO/氰化物中毒：高浓度氧疗，氰化物用羟钴胺（须在有指引的烧伤中心）","电击伤：持续心电监护 ≥24 小时（心律失常风险），深部组织坏死需筋膜切开","严重烧伤按 ABA 标准转诊烧伤中心，避免在非专科机构延误"],"life":["创面愈合后弹力套、硅酮制剂预防瘢痕；关节部位早期功能锻炼","心理支持与 PTSD 筛查（大面积烧伤与容貌改变者高发）","居家安全：热水器温度 <50 ℃、吸烟与明火管理，儿童远离厨房与热源","伤残评估与职业康复、烧伤瘢痕癌变长期随访（Marjolin 溃疡）"]},"prog":"无吸入性损伤的中小面积烧伤预后良好；TBSA >40% 或伴吸入性损伤者病死率显著升高（Baux 评分：年龄+TBSA >90 时病死率高）。约 50% 的烧伤死亡与脓毒症相关，早期切痂与感染控制可改善存活。约 60%–70% 的重度烧伤存活者遗留瘢痕相关功能障碍。","refs":["中华医学会烧伤外科学分会《中国烧伤休克液体复苏专家共识》","中华医学会烧伤外科学分会《成人烧伤深度诊断与治疗专家共识》（2019）","中国医师协会烧伤科医师分会《烧伤早期处理与转诊中国专家共识》","American Burn Association《Advanced Burn Life Support（ABLS）》指南","中华医学会烧伤外科学分会《吸入性损伤诊断与治疗专家共识》"]},{"id":"em_hyperk","name":"高钾血症急症处理","aka":["Hyperkalemia","高血钾","高钾危象"],"rank":4,"basic":{"define":"血清钾 >5.5 mmol/L；当 K⁺ ≥6.5 mmol/L 或伴心电图改变（T 波高尖、P 波变平、QRS 增宽、正弦波）或神经肌肉无力时属急症，需立即“稳定心肌—转移钾—清除钾”三步处理。","risk":["慢性肾脏病（尤其 eGFR <30）与急性肾损伤、透析不充分","ACEI/ARB、醛固酮受体拮抗剂、保钾利尿剂、NSAIDs 与 β 受体阻滞剂","横纹肌溶解、肿瘤溶解综合征、严重创伤/烧伤与溶血","代谢性酸中毒、胰岛素缺乏/糖尿病酮症、低醛固酮症（Addison 病）","高钾饮食与含钾盐替代品、含钾中药与大量输注库存血"],"epi":"住院患者高钾血症发生率约 1%–10%，慢性肾病患者可达 40%–50%；血钾 >6.0 mmol/L 时院内死亡风险显著上升，重度高钾可在数分钟内致室颤或心脏停搏。老年人、CKD 与 RAAS 抑制剂使用者是高危人群。"},"patho":"钾平衡取决于摄入、细胞内外转移与肾脏排钾。肾排钾减少是主要机制（醛固酮作用不足或肾灌注下降）；细胞膜电位取决于细胞内外钾浓度比，血钾升高使静息膜电位减小、去极化阻滞，初期心肌兴奋性增高（T 波高尖），随后传导减慢（P 波变平、PR 延长、QRS 增宽）直至心室停搏；骨骼肌亦可出现无力与弛缓性瘫痪。酸中毒与胰岛素缺乏促使钾外移，碱中毒与胰岛素则促使钾进入细胞内。","dx":{"criteria":["血钾 >5.5 mmol/L 为高钾；5.5–5.9 轻度、6.0–6.4 中度、≥6.5 重度（急症）。","心电图改变（与血钾水平相关但个体差异大）：5.5–6.5 时 T 波高尖窄；6.5–7.5 时 P 波变平/PR 延长、QRS 增宽；>8 时正弦波与室颤/心脏骤停风险。","假性高钾需排除：溶血、采血管挤压/止血带时间过长、采血侧正在输液、血小板 >500×10⁹/L 或白细胞 >50×10⁹/L（需测血浆钾而非血清钾）。","同时评估：肾功能（eGFR）、血气（pH/HCO₃⁻）、血糖与胰岛素、醛固酮/肾素、横纹肌溶解（CK）与肿瘤溶解（尿酸、磷、LDH）。"],"workup":["即刻床旁心电图（无 T 波高尖不能排除），持续心电监护","复查血钾（不同采血点、尽快送检），必要时以血气血钾核实","肾功能、电解质、血糖、血气、CK、尿酸与磷；怀疑肾衰竭者查肾脏超声","药物核对：停用保钾药与含钾制品；接受含钾输液或输血者记录量","疑似肿瘤溶解或横纹肌溶解者行相应标志物检测"],"grading":"按血钾与心电图分为轻（5.5–5.9，无 ECG 改变）、中（6.0–6.4 或 T 波高尖）、重（≥6.5 或 QRS 增宽、正弦波，需紧急处理与 RRT）。"},"ddx":[{"name":"烧伤面积评估与液体复苏","point":"与本类中“烧伤”的鉴别点：烧伤致高钾是肌坏死后并发症，以 TBSA 与创面为核心并按 Parkland 补液；高钾血症以血钾与心电图判定，处理以离子转移与清除钾为主。"},{"name":"假性高钾血症","point":"无临床高危因素与心电图改变，采血前溶血/挤压，复查血浆钾正常。"},{"name":"低钾血症","point":"血钾 <3.5 mmol/L，T 波低平、U 波突出，可致心律失常与肌无力。"},{"name":"急性肾损伤","point":"肌酐升高伴少尿与高钾，是常见基础病因；需同时评价容量与透析指征。"},{"name":"横纹肌溶解","point":"肌肉疼痛、酱油色尿、CK 显著升高，可伴高钾、高磷与 AKI。"}],"tx":{"drug":[{"name":"葡萄糖酸钙（稳定心肌）","dose":"10% 葡萄糖酸钙 10–20 mL 缓慢静推（5–10 分钟），心电图改变持续或 10–20 分钟未改善可重复；10% 氯化钙 5–10 mL 仅经中心静脉","note":"钙剂不降低血钾，仅保护心肌 30–60 分钟；需心电监护下推注，纠正高钾必须同步转移与清除","renal":"无需调整，但注意容量与钙负荷","hepatic":"无需调整","interact":"与头孢曲松、碳酸氢钠同通路禁忌"},{"name":"胰岛素 + 葡萄糖（转移钾）","dose":"常规胰岛素 10 U 加 50% 葡萄糖 25 g（50 mL）静推（约 10 分钟），继以 10% 葡萄糖 50–75 mL/h 泵入监测血糖；血糖 >13.9 mmol/L 者可不加葡萄糖","note":"通常 15–30 分钟起效，维持 4–6 小时；需每小时监测血糖，低血糖是最常见不良反应；肾功能不全者低血糖风险更高","renal":"CKD 患者低血糖风险增高，延长葡萄糖输注并监测","hepatic":"严重肝病者葡萄糖需求增加","interact":"β 受体阻滞剂可延迟血糖回升"},{"name":"沙丁胺醇雾化（转移钾）","dose":"10–20 mg 雾化吸入（对常规剂量反应不足者可加倍），20–30 分钟起效，持续约 2 小时","note":"作为胰岛素-葡萄糖的辅助，不能单独替代；可致心动过速与震颤","renal":"无需调整","hepatic":"无需调整","interact":"与非选择性 β 受体阻滞剂合用效果减弱"},{"name":"碳酸氢钠（促进转移）","dose":"仅用于合并严重代谢性酸中毒者：5% 碳酸氢钠 100–150 mL 静滴；不推荐常规用于非酸中毒患者","note":"转移钾作用有限且可致容量负荷；勿与钙剂同通路","renal":"肾衰者防过量钠负荷","hepatic":"无需调整","interact":"与钙剂、肾上腺素同通路禁忌"},{"name":"降钾药物（树脂/新型钾结合剂）","dose":"聚苯乙烯磺酸钙 15 g 口服 q6h（最多 4 次/日）或灌肠 30–50 g；环硅酸锆钠 10 g tid 口服，48 小时后按血钾调整","note":"起效慢（数小时），用于非紧急或维持治疗；灌肠有罕见肠坏死报道","renal":"为肾衰常用，需监测钠负荷与水肿","hepatic":"无需调整","interact":"与其他口服药间隔 2–3 小时，肠道梗阻者禁用"}],"nonDrug":["三级处置原则：稳定心肌（钙剂）→ 转移钾入细胞内（胰岛素-葡萄糖、沙丁胺醇）→ 清除钾（利尿剂、树脂、RRT）","紧急透析指征：血钾 ≥6.5 mmol/L 伴心电图改变且内科治疗无效、合并严重 AKI/CKD 5 期、极高钾反复出现","停用所有保钾药物（ACEI/ARB、螺内酯、NSAIDs）、含钾静脉液体与中药","持续心电监护直至血钾 <5.5 mmol/L 且心电图恢复正常","合并酸中毒/低容量者纠正病因；横纹肌溶解者补液与碱化尿液","透析后反弹监测：每小时复查血钾，防再次升高"],"life":["饮食限钾教育（香蕉、橙、土豆、坚果、含钾盐替代品），必要时营养师指导","定期复查血钾与肾功能，尤其 CKD 与 RAAS 抑制剂/醛固酮拮抗剂使用者","避免自行使用 NSAIDs 与含钾中草药制剂","糖尿病与肾上腺功能不全者加强原发病管理"]},"prog":"及时处理者大多数血钾可在数小时内降至达标范围；重度高钾伴心电图改变而延误处理者心脏骤停风险显著升高。CKD 患者高钾常反复发作，6 个月内复发率约 20%–30%，需长期监测与饮食药物管理，必要时长期降钾药物或透析。","refs":["中华医学会肾脏病学分会《慢性肾脏病高钾血症管理中国专家共识》（2020）","中华医学会急诊医学分会《高钾血症急诊处理中国专家共识》","中国医师协会肾脏内科医师分会《高钾血症诊治专家共识》","KDIGO《慢性肾脏病评估与管理指南》（2024）","UK Kidney Association《高钾血症管理临床实践指南》（2023）"]}]},{"id":"em_organ_fail","name":"器官衰竭与电解质危象","rank":4,"summary":"代谢与电解质急症的共同逻辑是先稳定循环与渗透压再针对病因：补液与纠正速率决定成败，激素与降钙药物须按顺序使用。","compare":[{"diseaseId":"em_dka_emerg","dx":"血糖升高伴血酮阳性、阴离子间隙增大、pH<7.30（DKA）；或血糖>33.3 mmol/L、渗透压>320 mOsm/kg 伴意识障碍（HHS）","key":"DKA 以酮症酸中毒为核心；HHS 以极高血糖与高渗脱水为核心、酮体阴性"},{"diseaseId":"em_thyroid_storm","dx":"甲亢者遇感染、手术、停药等诱因出现高热>38.5 ℃、心率>130 次/分、房颤与中枢异常，BWPS ≥45 分","key":"体温与心率骤升、甲状腺肿大，无酮症与高渗脱水"},{"diseaseId":"em_adrenal_crisis","dx":"肾上腺功能不全者遇应激出现补液抵抗的低血压、低钠、高钾、低血糖与呕吐腹痛","key":"低钠、高钾、低血糖三联且升压药反应差，激素可迅速逆转"},{"diseaseId":"em_hypercalcemia","dx":"校正血钙>3.5 mmol/L 伴多尿、脱水、意识改变与 QT 缩短，多见于肿瘤或甲旁亢","key":"多尿脱水形成恶性循环，扩容后症状改善"},{"diseaseId":"em_hyponatremia","dx":"血钠<135 mmol/L，急症为<120 或伴抽搐；需同测血渗透压、尿渗透压与尿钠","key":"纠正速率≤8 mmol/L/24 h 是防渗透性脱髓鞘的关键"}],"diseases":[{"id":"em_dka_emerg","name":"糖尿病酮症酸中毒与高渗高血糖状态（急诊处置）","aka":["DKA","HHS"],"rank":1,"basic":{"define":"DKA 为胰岛素严重缺乏致酮体堆积与高阴离子间隙酸中毒；HHS 为相对胰岛素不足、极高血糖与高渗脱水而酮症不明显。急诊重点为分型分层、补液与胰岛素启动。","risk":["1 型与血糖控制差的 2 型糖尿病，胰岛素中断或漏用","感染、急性胰腺炎与心脑血管事件","糖皮质激素、SGLT2 抑制剂（可致正常血糖酮症）","妊娠、酗酒、创伤与手术应激"],"epi":"重度 DKA 病死率约 1%–5%；HHS 多见老年 2 型糖尿病，病死率 10%–20%。"},"patho":"胰岛素缺乏与升糖激素升高使脂肪分解加速，肝 β 氧化产生酮体致高阴离子间隙酸中毒；血糖超肾糖阈后渗透性利尿，失水 DKA 5–7 L、HHS 8–12 L。最危险是补液加胰岛素后血钾骤降与儿童脑水肿。","dx":{"criteria":["DKA：血糖>13.9 mmol/L，血 β-羟丁酸≥3.0 mmol/L 或尿酮强阳性，pH<7.30 且 HCO₃⁻<18，阴离子间隙>12；轻 7.25–7.30、中 7.00–<7.25、重 <7.00。","HHS：血糖>33.3 mmol/L，有效渗透压（2×Na⁺+血糖）>320 mOsm/kg，pH≥7.30 且血酮阴性或弱阳性。","SGLT2 抑制剂、饥饿、妊娠者可血糖<13.9 而酮症酸中毒。"],"workup":["床旁血糖 10 min 内；血酮、电解质、碳酸氢盐、肌酐、阴离子间隙、乳酸、渗透压","血常规、降钙素原、尿常规、胸部影像；高热者血培养"]},"ddx":[{"name":"甲状腺危象","point":"与本类中甲状腺危象的鉴别点：危象以高热与心率>130 次/分、甲亢病史为主，无酮症。"},{"name":"乳酸酸中毒","point":"乳酸升高而血酮不高，见于双胍类、休克与脓毒症。"},{"name":"急性胰腺炎","point":"脂肪酶>3 倍正常上限；DKA 腹痛多随酸中毒纠正缓解。"}],"tx":{"drug":[{"name":"0.9% 氯化钠","dose":"首 1 h 15–20 mL/kg（成人常 1–1.5 L，心肾功能不全减半），24 h 总量 4–6 L","note":"第 2 h 起血钠正常或偏高改 0.45%；儿童 10–20 mL/kg 分次防脑水肿","renal":"少尿者减慢","interact":"大剂量致高氯性酸中毒"},{"name":"普通胰岛素","dose":"血钾≥3.3 mmol/L 后 0.1 U/kg/h 泵入；血糖降至约 11.1 mmol/L 加 5% 葡萄糖并维持 0.05–0.1 U/kg/h","note":"降速目标 3–5 mmol/L/h，1 h 降幅<1 则加倍；不推荐大剂量推注","renal":"eGFR 下降者减量","interact":"随含糖液调整滴速"},{"name":"氯化钾","dose":"血钾 3.3–5.2 mmol/L 时每升补液加 20–40 mmol；<3.3 暂缓胰岛素并按 10–20 mmol/h 静脉补钾","note":"维持血钾 4–5 mmol/L，有尿量再积极补钾，2–4 h 复查","renal":"肾功能不全减量并心电监护","interact":"与 ACEI 合用易高钾"},{"name":"碳酸氢钠","dose":"仅 pH<6.9 时 50–100 mmol 缓慢静滴","note":"不常规使用","renal":"少尿者增容量负荷","interact":"与含钙液同通路可沉淀"}],"nonDrug":["解除诱因：抗感染、抗缺血、暂停 SGLT2 抑制剂","重度 DKA（pH<7.00）、HHS 意识障碍、血钾紊乱或休克者首剂补液与胰岛素后转 ICU","每小时血糖、每 2–4 h 血酮与电解质至阴离子间隙≤12；不可仅凭血糖下降停胰岛素，停泵前先给皮下胰岛素"],"life":["病日规则：发热呕吐时测酮体且基础胰岛素不中断"]},"prog":"24–48 h 可纠正；复发多与胰岛素中断和感染相关。","refs":["中国糖尿病酮症酸中毒诊治专家共识（2022）","中国高血糖危象诊断与治疗指南（2013）"]},{"id":"em_thyroid_storm","name":"甲状腺危象（急诊处置）","aka":["Thyroid Storm","甲亢危象"],"rank":2,"basic":{"define":"甲亢患者在感染、手术、创伤、停药或碘负荷等诱因下出现高热、心动过速、中枢神经与胃肠肝功能异常的极危重状态，需临床诊断并立即干预。","risk":["未治疗或治疗不规则的 Graves 病、毒性结节性甲状腺肿","感染（呼吸道最常见）、甲状腺手术、分娩","突然停用抗甲状腺药或碘剂；含碘造影剂与胺碘酮","老年可淡漠型起病，以房颤与心衰为主"],"epi":"住院甲亢患者中约 1%–2% 发生危象；病死率约 10%，延误可达 20%–30%。"},"patho":"甲状腺激素骤升使产热与氧耗增加，并上调肾上腺素能受体敏感性，故 β 受体阻滞剂可迅速控制心率。高热脱水、心衰与肾上腺储备耗竭相互加重，故须先抗甲状腺药阻断合成、再用碘剂阻断释放，并阻断外周转化与拮抗交感。","dx":{"criteria":["Burch-Wartofsky 评分：体温 37.2–37.7 ℃ 5 分、37.8–38.2 ℃ 10 分、38.3–38.8 ℃ 15 分、38.9–39.3 ℃ 20 分、≥39.4 ℃ 25 分；心率 99–109 次/分 5 分、110–119 次/分 10 分、120–129 次/分 15 分、130–139 次/分 20 分、≥140 次/分 25 分；房颤 +10 分。","神经：躁动 +10 分、谵妄或嗜睡 +20 分、抽搐昏迷 +30 分；呕吐腹泻腹痛 +10 分、黄疸 +20 分；有诱因 +10 分。","≥45 分高度提示危象、25–44 分可疑；临床怀疑即治疗，不等激素结果。TSH 降低、FT4/FT3 升高但水平与严重度不平行。"],"workup":["甲功与 TRAb（不等结果即治疗）；心电图与监护","血培养、胸部影像找诱因","肝功能、胆红素、血糖、电解质、CK；超声心动图"]},"ddx":[{"name":"糖尿病酮症酸中毒与高渗高血糖状态","point":"与本类中 DKA/HHS 的鉴别点：DKA 以血糖升高、血酮阳性与酸中毒为核心；危象以高热与心率快为主，血酮阴性。"},{"name":"脓毒症","point":"心率多与体温成比例，有感染灶且血培养阳性，甲功正常。"},{"name":"恶性高热与神经阻滞剂恶性综合征","point":"与麻醉史或抗精神病药相关，伴肌强直与 CK 显著升高。"},{"name":"拟交感或抗胆碱能药物过量","point":"瞳孔散大、皮肤干燥、毒物筛查阳性。"}],"tx":{"drug":[{"name":"丙硫氧嘧啶（PTU）","dose":"负荷 600 mg 口服或鼻胃管，此后 200–250 mg 每 4–6 h","note":"首选，同时抑制合成与外周 T4→T3 转化；肝损者改甲巯咪唑","hepatic":"肝损或粒缺者停药","interact":"与碘剂至少间隔 1 h"},{"name":"碘剂","dose":"PTU 后至少 1 h：复方碘溶液 5–10 滴每 6–8 h，或碘化钠 0.5–1 g 加入 500 mL 液体静滴每 8 h","note":"阻断激素释放；严禁在抗甲状腺药前用；胺碘酮所致者禁用","interact":"与硫脲类错开 1 h"},{"name":"普萘洛尔","dose":"20–80 mg 口服每 4–6 h，或 1–2 mg 缓慢静推后 1–5 mg/h 泵入","note":"心率目标 90–110 次/分并抑制 T4→T3；哮喘与心衰改用艾司洛尔","hepatic":"重度肝损减量","interact":"与洋地黄增心动过缓"},{"name":"氢化可的松","dose":"100 mg 静推后 100 mg 每 8 h（或 50 mg 每 6 h）","note":"补充肾上腺储备并抑制 T4→T3","interact":"升血糖"}],"nonDrug":["物理降温，禁用阿司匹林类退热药；补液 100–200 mL/h","查治诱因；顽固者血浆置换或血液灌流；房颤不稳者电复律","24–48 h 内体温下降、心率<120 次/分即有效，随后逐步减量"],"life":["甲亢规范治疗，避免自行停药","感染与手术应激时告知甲亢病史并加量"]},"prog":"24–72 h 缓解；合并心衰、休克与黄疸者预后差。","refs":["中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022）","ATA 甲亢管理指南（2016）"]},{"id":"em_adrenal_crisis","name":"肾上腺危象","aka":["Adrenal Crisis"],"rank":3,"basic":{"define":"肾上腺皮质功能不全者遇应激时皮质醇不足，以低血压休克、低钠、高钾、低血糖与消化道症状为特征的内分泌急症。","risk":["原发性肾上腺功能不全（自身免疫性肾上腺炎、结核、出血、转移瘤）","长期糖皮质激素突然减停或应激时未加量（继发性最常见）","垂体疾病、垂体术后与放疗后","抗凝中肾上腺出血、脓毒症、检查点抑制剂"],"epi":"原发性患病率约 5–15/10 万，约 5%–8% 曾发生危象；病死率约 2%–6%。"},"patho":"皮质醇缺乏使糖异生下降、血管对儿茶酚胺反应性降低，出现低血糖与补液抵抗的低血压；醛固酮缺乏（原发性）致钠丢失、钾潴留，形成低钠、高钾与轻度酸中毒。继发性者醛固酮多保留、无高钾。","dx":{"criteria":["顽固性低血压或休克、补液与升压药反应差，伴低钠（<130 mmol/L）与低血糖（<3.9 mmol/L）；原发性者常高钾（>5.0 mmol/L）。","乏力、恶心呕吐、腹痛（可似急腹症）；原发性者色素沉着；诱因多为感染、手术或突然停激素。","线索：嗜酸性粒细胞增多、尿素氮与肌酐升高。","治疗前留血皮质醇与 ACTH，但不得等待结果而延误给药；慢性者 ACTH 兴奋试验皮质醇峰值<500 nmol/L 可确认。"],"workup":["皮质醇与 ACTH（留样不停治疗）","电解质、血糖、肌酐、血气与乳酸；血常规、降钙素原、血培养、心电图","胸部或腹部 CT 寻感染灶"]},"ddx":[{"name":"甲状腺危象","point":"与本类中甲状腺危象的鉴别点：危象以高热与心动过速为主、低血压继发心衰；肾上腺危象心率偏慢，以低钠高钾低血糖为主。"},{"name":"脓毒症与感染性休克","point":"血培养阳性、乳酸升高；感染是危象最常见诱因，升压药抵抗时应考虑并存。"},{"name":"消化道急腹症","point":"有腹膜刺激征与影像阳性；危象腹痛无腹膜刺激，激素与补液后迅速缓解。"},{"name":"糖尿病酮症酸中毒","point":"血糖升高伴酮症，血钾趋低；危象血糖低或正常、血钾升高。"}],"tx":{"drug":[{"name":"氢化可的松","dose":"首剂 100 mg 静推，随后 50–100 mg 每 6 h 静滴；控制后 24–48 h 减为口服 15–25 mg/日","note":"兼具糖皮质与盐皮质活性，首选；合并脓毒症首日可用 200–300 mg","interact":"与利福平、苯妥英需加量"},{"name":"地塞米松","dose":"4 mg 静推每 6 h（需保留皮质醇检测时）","note":"无盐皮质活性，需同补 0.9% 氯化钠","interact":"遵说明书"},{"name":"0.9% 氯化钠","dose":"首 1 h 500–1000 mL（可 15–20 mL/kg），24 h 4–6 L 或更多，按尿量与血压调整","note":"低钠纠正≤8–10 mmol/L/24 h 以防脱髓鞘","renal":"少尿者减慢","interact":"遵说明书"},{"name":"葡萄糖","dose":"血糖<3.9 mmol/L 时 50% 葡萄糖 20–40 mL 静推，随后 10% 葡萄糖维持","note":"儿童用 2–3 mL/kg 的 10% 葡萄糖","interact":"遵说明书"},{"name":"去甲肾上腺素","dose":"补液与激素后仍低血压时 0.05–1 µg/kg/min 至 MAP ≥65 mmHg","note":"补充皮质醇后血管反应性恢复可减量","interact":"避免与碱性液同通路"}],"nonDrug":["1 h 内经验性抗感染并处理休克诱因；血钾>6.5 mmol/L 或心电异常时按高钾急症处理","应激剂量方案：发热或小手术加倍，大手术按需加量；携带激素警示卡与备用注射剂"],"life":["激素不可自行减停，应激时加倍并就医","规律随访电解质、血压与体重"]},"prog":"规范治疗数月内稳定；延误者病死率 10%–20%。","refs":["欧洲内分泌学会肾上腺危象管理指南（2016）","中国肾上腺皮质功能不全诊治专家共识（2019）"]},{"id":"em_hypercalcemia","name":"高钙危象","aka":["Hypercalcemic Crisis"],"rank":4,"basic":{"define":"校正血清总钙>3.5 mmol/L 伴多尿、脱水、意识障碍与心律失常的高危急症，多见于恶性肿瘤与原发性甲状旁腺功能亢进。","risk":["多发性骨髓瘤、乳腺癌骨转移、肺鳞癌、淋巴瘤（PTHrP 分泌）","原发性甲旁亢（危象多由脱水、感染、制动诱发）","噻嗪类利尿剂、维生素 D 过量、含钙药物","结节病与结核等肉芽肿病、长期透析"],"epi":"诊断前必须排肾前因；危象多由脱水、感染、制动诱发，血钙>4 mmol/L 时病死率明显升高。"},"patho":"PTHrP 或 PTH 使骨吸收与肾小管钙重吸收增加，肿瘤骨转移直接溶骨。血钙>3.0 mmol/L 时肾浓缩功能受损致多尿与失水，形成高钙、多尿、脱水、钙排泄减少、血钙更高的循环。","dx":{"criteria":["校正钙 = 实测钙 + 0.02×（40 − 白蛋白 g/L）；3.0–3.5 为中度，>3.5 mmol/L 为重度危象。","症状：多尿口渴、恶心呕吐；乏力肌无力；嗜睡、谵妄、昏迷；QT 缩短与心律失常。","PTH 升高提示甲旁亢；PTHrP 升高提示肿瘤相关；少尿与肾功能恶化提示进入钙危象循环。"],"workup":["总钙与白蛋白同步、离子钙；PTH、PTHrP、25-羟维生素 D、血磷、尿钙","心电图、肾功能与尿量记录；骨影像与蛋白电泳（骨髓瘤）"]},"ddx":[{"name":"低钠血症","point":"与本类中低钠血症的鉴别点：低钠者血钙正常、渗透压低并常抽搐；高钙危象血钙>3.5 mmol/L、QT 缩短。"},{"name":"高血糖危象","point":"血糖升高伴酮体或高渗，血钙多正常。"},{"name":"洋地黄中毒","point":"地高辛浓度升高、房室传导阻滞；高钙可增强其毒性。"},{"name":"中枢急性事件","point":"有局灶体征与影像改变，血钙正常。"}],"tx":{"drug":[{"name":"0.9% 氯化钠","dose":"首 1–2 h 200–500 mL 快速静滴，随后 4–6 L/24 h（200–300 mL/h）","note":"降钙基础；心功能不全者减量并测出入量","renal":"肾衰者减慢或透析","interact":"大剂量致高氯性酸中毒"},{"name":"唑来膦酸","dose":"4 mg 加入 100 mL 生理盐水静滴>15 min，48–72 h 起效，持续 2–4 周","note":"肿瘤相关高钙首选；给药前充分水化","renal":"CrCl<30 慎用或减量","interact":"与氨基糖苷类增低钙"},{"name":"降钙素","dose":"鲑降钙素 4 IU/kg 皮下或肌注每 12 h","note":"4–6 h 起效、48 h 后易逃逸，用于过渡","interact":"遵说明书"},{"name":"呋塞米","dose":"容量充分后 20–40 mg 静推每 6–12 h，维持尿量 100–200 mL/h","note":"禁在容量不足时单用","renal":"肾功能不全者滴定","interact":"与氨基糖苷类增耳肾毒性"},{"name":"地舒单抗","dose":"120 mg 皮下每 4 周（双膦酸盐禁忌或难治）","note":"降钙强，需监测低钙并补维生素 D","renal":"不依赖肾功能","interact":"序贯使用注意低钙"},{"name":"泼尼松","dose":"40–60 mg/日口服（肉芽肿病与淋巴瘤相关高钙）","note":"5–7 d 起效","interact":"监测血糖"}],"nonDrug":["停用噻嗪类、钙剂与维生素 D；鼓励活动，充分饮水","血液透析（低钙透析液）用于合并肾衰心衰或>4.5 mmol/L 难治者","病因治疗：肿瘤治疗、骨转移放疗、甲旁亢手术或西那卡塞；血钙<3.0 mmol/L 且意识与肾功能恢复后转出"],"life":["避免长期制动与过量补钙、维生素 D"]},"prog":"24–48 h 血钙下降 0.5–1.0 mmol/L；肿瘤相关者中位生存数月。","refs":["中国高钙血症诊治专家共识（2021）","中国原发性甲状旁腺功能亢进症诊疗指南（2018）"]},{"id":"em_hyponatremia","name":"低钠血症急症","aka":["Severe Hyponatremia","低钠脑病"],"rank":5,"basic":{"define":"血清钠<135 mmol/L；急症指<120 mmol/L 或出现抽搐、意识障碍等严重神经症状者。低钠致脑细胞水肿，同时是渗透性脱髓鞘综合征（ODS）风险最高的电解质紊乱。","risk":["SIADH（肺部感染、颅内病变、小细胞肺癌）与药物（卡马西平、SSRI）","噻嗪类利尿剂（老年人最常见）、心衰、肝硬化、肾病综合征","呕吐腹泻、大量出汗后只补低渗液","肾上腺皮质功能不全、甲减、慢性肾衰"],"epi":"住院患者发生率约 15%–20%；重度低钠占 3%–5%，伴神经症状者病死率显著升高。"},"patho":"血渗透压下降使水入脑细胞，<48 h 内尚未完成溶质适应，脑水肿可致脑疝。反之，对慢性低钠快速纠正时水分移出脑细胞致皱缩与髓鞘损伤（ODS），故纠正速率是主要可防可控的风险。","dx":{"criteria":["血钠<135 mmol/L；严重低钠<120 mmol/L 或伴抽搐、意识障碍与昏迷（低钠脑病）。","分型：低渗性（血渗透压<275 mOsm/kg）、等渗性（假性低钠：高血糖、高脂、高蛋白）、高渗性。","容量分型：低容量（尿钠<30 mmol/L）、等容量（SIADH，尿钠>30 且尿渗透压>100 mOsm/kg）、高容量（水肿、颈静脉充盈）。","急性指症状出现<48 h；纠正上限任何情况≤8 mmol/L/24 h，慢性、营养不良、酗酒、老年、低钾与肝病者≤6 mmol/L/24 h。"],"workup":["血钠（避免输液侧采血）、血渗透压、血糖、肌酐、尿素氮、血钾、白蛋白","补液前留取尿钠与尿渗透压","血气、血尿酸（SIADH 常低）、甲功与晨皮质醇"]},"ddx":[{"name":"高钙危象","point":"与本类中高钙危象的鉴别点：高钙者血钙升高、多尿脱水与 QT 缩短；低钠者血渗透压低、常伴抽搐。"},{"name":"SIADH","point":"等容量、尿钠>30 mmol/L、尿渗透压>100 mOsm/kg；治疗为限液或托伐普坦。"},{"name":"假性低钠","point":"实测渗透压正常，高血糖每升 5.6 mmol/L 血钠约降 1.7 mmol/L。"},{"name":"高容量性低钠","point":"心衰与肝硬化者水肿、尿钠<30 mmol/L，以限液利尿为主。"}],"tx":{"drug":[{"name":"3% 高渗氯化钠","dose":"100–150 mL（或 2 mL/kg）20 min 内静滴，可重复 1–2 次至症状缓解或血钠升高 4–6 mmol/L；其后每小时 1–2 mmol/L 滴定","note":"抽搐昏迷者 10 min 内给药；目标为止痉脱危而非血钠正常","renal":"少尿者警惕容量负荷","interact":"不可与含钙液同通路"},{"name":"0.9% 氯化钠","dose":"低容量者按 30–50 mL/kg/24 h 起补，每 4–6 h 复算累计升幅","note":"累计≤8 mmol/L/24 h，慢性者≤6；补钾后血钠会再升高","renal":"容量负荷者慎用","interact":"遵说明书"},{"name":"呋塞米","dose":"20–40 mg 静推，可配合高渗盐水增加自由水排出","note":"用于高容量或需控制纠正速率时","renal":"按肾功能调整","interact":"与氨基糖苷类增耳肾毒性"},{"name":"托伐普坦","dose":"15 mg 口服 qd 起，按血钠调整","note":"用于等容量或高容量性低钠；起始 24 h 必须密切监测，过度纠正可致 ODS","renal":"晚期 CKD 疗效下降","hepatic":"肝损者慎用","interact":"与 CYP3A4 抑制剂升浓度"},{"name":"去氨加压素","dose":"血钠上升超速时 1–2 µg 皮下或静注每 6–8 h，配合补液","note":"发现超速后尽早使用以再降血钠，减少 ODS","interact":"遵说明书"}],"nonDrug":["每 2–4 h 复查血钠，按目标曲线控制速率；超速时停高渗盐水，用 5% 葡萄糖或去氨加压素并会诊","SIADH 与高容量者限液（<1 L/日或 500 mL 加尿量）并治疗原发病，同时补钾补镁","ODS 高危者更保守；出现构音障碍、吞咽困难与共济失调时行 MRI；症状性低钠仍不稳者转 ICU"],"life":["避免大量饮纯水与极低溶质饮食，运动后补电解质"]},"prog":"及时高渗盐水可改善症状；纠正>12 mmol/L/24 h 时 ODS 风险显著上升。","refs":["欧洲低钠血症诊治指南（2014）","中国低钠血症诊治专家共识（2017）"]}]},{"id":"em_acute_sc","name":"急诊常见急症","rank":5,"summary":"急诊最讲究时间窗的五类急症：ACS 拼 10 min 内心电图与 D2B，卒中拼溶栓窗与取栓，脓毒症拼 1 h bundle，气道拼首次插管成功率与失败预案，过敏性休克拼肾上腺素越早越好。","compare":[{"diseaseId":"em_acs_emerg","dx":"缺血性胸痛伴心电图 ST-T 改变或肌钙蛋白动态升高；10 min 内完成并判读首份 12 导联心电图","key":"锚点是心电图加肌钙蛋白动态变化，STEMI 需即刻再灌注"},{"diseaseId":"em_stroke_emerg","dx":"突发局灶神经功能缺损且 CT 排除出血，NIHSS 记录，起病时间精确到分钟","key":"靠 FAST 与 NIHSS 识别；时间就是大脑，4.5 h 内溶栓"},{"diseaseId":"em_sepsis_emerg","dx":"疑似感染伴 SOFA 上升≥2 分或 qSOFA≥2 项；休克者乳酸>2 mmol/L 且需升压药","key":"感染加器官功能障碍，1 h 内抗生素与 30 mL/kg 晶体液"},{"diseaseId":"em_airway_emerg","dx":"不能维持气道通畅、通气或氧合，或 GCS≤8 伴误吸风险；需先评估困难气道","key":"插管指征优先于诊断分型，必须备失败预案"},{"diseaseId":"em_anaphylaxis","dx":"接触过敏原后数分钟内皮肤黏膜受累加呼吸或循环受累，或已知过敏原暴露后单纯低血压与支气管痉挛","key":"首选肾上腺素肌注，激素与抗组胺不能替代"}],"diseases":[{"id":"em_acs_emerg","name":"急性冠脉综合征急诊流程","aka":["ACS","急性胸痛流程"],"rank":1,"basic":{"define":"冠脉急性闭塞或严重狭窄致心肌缺血的综合征，包括 STEMI、NSTEMI 与不稳定型心绞痛。急诊重点是 10 min 内心电图、风险分层与再灌注路径。","risk":["吸烟、高血压、糖尿病、血脂异常，男性>45 岁与女性>55 岁","既往冠心病、PCI/CABG 史、外周动脉病","压榨样胸痛>20 min、放射痛、出汗；老年与女性可仅呼吸困难","可卡因等拟交感药物、剧烈运动"],"epi":"心血管病居我国居民死因首位；STEMI 规范再灌注可使院内病死率降至 4%–6%。"},"patho":"斑块破裂后血小板活化形成血栓使冠脉血流骤减。STEMI 为完全闭塞，2 h 内梗死面积扩展最快；NSTE-ACS 多为不完全闭塞伴微血管栓塞。缺血可致心功能下降、心律失常与心源性休克。","dx":{"criteria":["首份 12 导联心电图在首次医疗接触后 10 min 内完成并判读。","STEMI：相邻两导联新发 ST 抬高（V2–V3 男性≥0.2 mV、女性≥0.15 mV，其他导联≥0.1 mV），或新发左束支阻滞伴症状。","NSTEMI：ST 压低或 T 波倒置，肌钙蛋白超第 99 百分位且有升降变化；UA 为症状符合而肌钙蛋白阴性伴动态改变。","GRACE 评分>140 为高危；持续胸痛、血压<90 mmHg、肺水肿、V4R 抬高按急症处理。"],"workup":["12 导联心电图（下壁梗死加 V7–V9 与 V3R–V4R），不典型者 15–30 min 复测","高敏肌钙蛋白 0 h 与 1–3 h 动态","连续监护；血常规、凝血、肾功能、血糖、NT-proBNP","胸片；疑夹层或肺栓塞查 D-二聚体与 CTA"]},"ddx":[{"name":"急性脑梗死","point":"与本类中急性脑梗死的鉴别点：卒中为突发局灶神经缺损、心电图无缺血演变；ACS 以胸痛与心电图改变为主，两者可并存（心源性栓塞）。"},{"name":"主动脉夹层","point":"撕裂样痛向背部放射、双上肢血压差>20 mmHg；D-二聚体阴性基本排除。"},{"name":"肺栓塞","point":"突发呼吸困难与低氧、D-二聚体升高，CTPA 见充盈缺损。"},{"name":"急性心包炎","point":"胸痛随体位变化、弥漫性 ST 抬高与 PR 压低，无镜像改变。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"负荷 300 mg 嚼服，此后 75–100 mg qd","note":"无禁忌者尽早给","renal":"重度肾损慎用","hepatic":"严重肝病注意出血","interact":"与抗凝药合用增出血"},{"name":"替格瑞洛或氯吡格雷","dose":"替格瑞洛负荷 180 mg 后 90 mg bid；或氯吡格雷负荷 300–600 mg 后 75 mg qd","note":"替格瑞洛禁用于脑出血史与重度肝损","renal":"替格瑞洛重度肾损慎用","hepatic":"重度肝损禁用","interact":"奥美拉唑减弱氯吡格雷"},{"name":"抗凝（UFH 或依诺肝素）","dose":"UFH 60–70 U/kg 静推（最大 5000 U）后 12–15 U/kg/h；或依诺肝素 1 mg/kg 皮下 q12h（≥75 岁 0.75 mg/kg）","note":"出血高危改用比伐芦定","renal":"依诺肝素 CrCl<30 减半或改 UFH","interact":"与溶栓药出血叠加"},{"name":"硝酸甘油","dose":"0.4 mg 舌下每 5 min 最多 3 次；持续缺血 5–10 µg/min 泵入","note":"禁用于收缩压<90 mmHg、右室梗死与 24 h 内用 PDE5 抑制剂者","interact":"与西地那非致严重低血压"},{"name":"美托洛尔","dose":"无禁忌者 24 h 内 25–50 mg 口服 q12h","note":"禁用于心源性休克、Killip Ⅲ–Ⅳ、心率<50 次/分","interact":"与维拉帕米加重心动过缓"},{"name":"阿托伐他汀","dose":"80 mg 或 40 mg qd，入院即启动","note":"强化降脂","renal":"重度肾损减量","hepatic":"活动性肝病禁用","interact":"与克拉霉素增肌病风险"}],"nonDrug":["STEMI 首选直接 PCI：FMC2B≤90 min；不能及时 PCI 且起病<12 h 者 30 min 内溶栓，溶栓后 2–24 h 转 PCI 中心","NSTE-ACS 按 GRACE 分层造影：极高危 2 h、高危 24 h、中危 72 h 内；D2B≤90 min，总缺血时间<120 min","右室梗死伴低血压补液 500 mL，禁用硝酸酯与利尿剂；心源性休克紧急血运重建加去甲肾上腺素"],"life":["戒烟、控压控糖控脂与心脏康复","双抗通常 12 个月"]},"prog":"STEMI 再灌注者院内病死率 4%–6%、1 年 8%–10%；NSTEMI 1 年约 10%–15%。","refs":["急性 ST 段抬高型心肌梗死诊断和治疗指南（2019）","非 ST 段抬高型急性冠状动脉综合征诊断和治疗指南（2024）"]},{"id":"em_stroke_emerg","name":"急性脑梗死急诊流程","aka":["AIS"],"rank":2,"basic":{"define":"脑血管急性闭塞致脑组织缺血坏死，表现为突发局灶神经功能缺损。急诊核心是时间就是大脑：<4.5 h 溶栓，大血管闭塞 24 h 内取栓。","risk":["高血压、糖尿病、血脂异常、吸烟与肥胖","心房颤动等心源性栓塞、颈动脉狭窄","既往卒中或 TIA 史","高龄、口服避孕药、高凝状态"],"epi":"缺血性卒中占我国卒中 70%–80%；4.5 h 内到院者不足 30%。"},"patho":"栓子或原位血栓阻塞脑血管，缺血核心数分钟内坏死，半暗带依赖侧支循环可被挽救。缺血触发钙超载与血脑屏障破坏，增加出血转化。溶栓与取栓均须在时间窗内。","dx":{"criteria":["突发局灶缺损：面瘫、肢体无力、失语、视野缺损、共济失调；NIHSS 记录；最后正常时间精确到分钟。","急诊 CT 平扫 15 min 内排除出血即可诊断，不需等 MRI。","溶栓窗：起病<4.5 h、年龄≥18 岁、NIHSS≥2 或症状致功能障碍；替奈普酶 0.25 mg/kg 用于 0–4.5 h。","取栓：前循环大血管闭塞（颈内动脉或 M1）且<6 h、ASPECTS≥6；6–24 h 需影像不匹配筛选。","禁忌：近 3 个月颅内手术或梗死、颅内出血史、活动性出血、血压>185/110 mmHg 未控、血小板<100×10⁹/L、INR>1.7、血糖<2.8 mmol/L。"],"workup":["指尖血糖即刻；血常规、凝血（INR、APTT）、血小板、肌酐、电解质","头颅 CT 15 min 内，必要时 CTA/MRA；6–24 h 加 CT 灌注","心电图与肌钙蛋白（查房颤）、NIHSS 与 GCS"]},"ddx":[{"name":"急性冠脉综合征","point":"与本类中 ACS 的鉴别点：ACS 以胸痛、ST-T 改变与肌钙蛋白升高为主、无局灶体征；卒中靠 NIHSS 阳性。"},{"name":"低血糖性脑病","point":"血糖<2.8 mmol/L 可致偏瘫，补糖后数分钟恢复。"},{"name":"脑出血与蛛网膜下腔出血","point":"CT 见高密度影或基底池积血，溶栓前必须排除。"},{"name":"Todd 麻痹与偏头痛先兆","point":"发作后短暂偏瘫或扩散先兆，数小时内恢复。"}],"tx":{"drug":[{"name":"阿替普酶（rt-PA）","dose":"0.9 mg/kg（最大 90 mg）静滴 60 min，其中 10% 于 1 min 内静推；起病<4.5 h","note":"溶栓前后血压<185/110 mmHg；24 h 内不抗栓，24 h 后 CT 无出血再启动","hepatic":"凝血异常或重度肝病禁用","interact":"24 h 内避免抗凝与抗血小板药"},{"name":"替奈普酶（TNK）","dose":"0.25 mg/kg（最大 25 mg）单次静推，<4.5 h","note":"团注便于转运；大血管闭塞不应因此推迟取栓","interact":"注意出血风险"},{"name":"依达拉奉右莰醇","dose":"30 mg 静滴 bid，连续 14 d","note":"不替代再灌注治疗","renal":"肾损慎用","interact":"遵说明书"},{"name":"甘露醇","dose":"20% 甘露醇 0.25–0.5 g/kg 静滴 q6–8h（颅高压）","note":"低血压与少尿时避免","renal":"少尿者慎用","interact":"与肾毒性药物增肾损"},{"name":"拉贝洛尔","dose":"10–20 mg 静推，或尼卡地平泵入使血压<185/110 mmHg","note":"未溶栓者除非>220/120 mmHg 不急于降压","interact":"与维拉帕米注意心动过缓"},{"name":"阿司匹林","dose":"未溶栓者 100–300 mg 口服或鼻胃管，48 h 内启动","note":"溶栓者 24 h 后且 CT 无出血再启动","interact":"与抗凝药增颅内出血"}],"nonDrug":["卒中绿色通道：预通知、并行评估，DNT<60 min；大血管闭塞优先取栓，可桥接溶栓且不得延迟取栓","吞咽评估后再进食；SpO₂<94% 吸氧，体温>38 ℃ 物理降温，血糖 6–10 mmol/L","大面积梗死脑疝倾向转神经外科评估去骨瓣减压；卒中单元收治并早期康复"],"life":["二级预防：抗栓、他汀、控压控糖、房颤抗凝"]},"prog":"溶栓约 30%–40% 达 mRS 0–2，桥接取栓可升至 50%–60%。","refs":["中国急性缺血性脑卒中诊治指南（2023）","中国急性缺血性脑卒中静脉溶栓指导规范（2021）"]},{"id":"em_sepsis_emerg","name":"脓毒症 1 小时集束化治疗","aka":["Sepsis Bundle","Sepsis-3"],"rank":3,"basic":{"define":"脓毒症为对感染反应失调导致的危及生命的器官功能障碍；休克为其伴循环与代谢异常的状态。1 h bundle 指识别后 1 h 内完成血培养、乳酸、抗生素、晶体液与升压支持。","risk":["高龄、免疫抑制（糖尿病、化疗、长期激素、移植）","侵入性导管、机械通气、近期手术与创伤","慢性心肝肾肺功能不全、营养不良与酗酒","耐药菌定植与近期广谱抗生素使用"],"epi":"我国脓毒症住院病死率约 20%–30%，休克>40%；抗生素每延迟 1 h 病死率增加约 4%–8%。"},"patho":"感染触发固有免疫过度激活，炎性介质致内皮损伤、血管渗漏与微血栓，形成分布性休克；心肌抑制与氧利用障碍使乳酸升高。炎症与凝血互锁，可进展为 DIC 与多器官功能障碍。控制感染源是根本，抗生素与容量复苏是争取时间的手段。","dx":{"criteria":["Sepsis-3：疑似或确诊感染伴 SOFA 较基线急性上升≥2 分。","qSOFA 筛查≥2 项：呼吸≥22 次/分、意识改变、收缩压≤100 mmHg。","脓毒症休克：需升压药维持 MAP ≥65 mmHg 且乳酸>2 mmol/L。","乳酸≥4 mmol/L 为高危。血培养应在抗生素前留取至少 2 套，不因等待而延迟用药。"],"workup":["乳酸（1 h 内，>2 mmol/L 时 2–4 h 复测）与静脉血气","血培养 2 套、尿培养、痰与引流液培养","血常规、CRP、降钙素原、凝血、肝肾功能；胸片或 CT、腹部超声定位感染源"]},"ddx":[{"name":"急性冠脉综合征（心源性休克）","point":"与本类中 ACS 的鉴别点：心源性休克以胸痛、ST-T 改变与肌钙蛋白升高为核心、血培养阴性；脓毒症以感染证据与乳酸升高为主。"},{"name":"肾上腺危象","point":"低钠、高钾、低血糖，补液升压反应差；感染常为诱因。"},{"name":"急性胰腺炎并发 SIRS","point":"脂肪酶>3 倍正常上限、CT 见胰腺渗出。"},{"name":"肺栓塞致梗阻性休克","point":"右心负荷增重、D-二聚体升高、CTPA 见血栓。"}],"tx":{"drug":[{"name":"广谱抗生素","dose":"识别后 1 h 内静脉足量：哌拉西林他唑巴坦 4.5 g q6h 或头孢曲松 2 g qd；耐药风险者美罗培南 1 g q8h 延长输注，必要时加万古霉素或抗真菌药","note":"48–72 h 按培养与反应降阶梯","renal":"按 CrCl 调整维持量，首剂不减","interact":"注意与抗凝药相互作用"},{"name":"晶体液","dose":"首 3 h 内 30 mL/kg 平衡盐液或 0.9% 氯化钠（必要时按 3 mL/kg 复评容量反应性）","note":"补液后仍低血压即启动升压药","renal":"警惕容量过负荷","interact":"大剂量致高氯性酸中毒"},{"name":"去甲肾上腺素","dose":"0.05–1 µg/kg/min 至 MAP ≥65 mmHg；必要时加血管加压素 0.03 U/min","note":"尽早中心静脉给药","interact":"避免与碱性液同通路"},{"name":"氢化可的松","dose":"200 mg/日（50 mg 静推 q6h），用于难治性休克","note":"不常规使用","interact":"升血糖"}],"nonDrug":["1 h bundle 清单：测乳酸、抗生素前血培养、1 h 内抗生素、低血压或乳酸≥4 时 30 mL/kg 晶体液、低血压用升压药维持 MAP ≥65 mmHg","感染源控制：脓肿引流、胆管炎 ERCP、坏死组织清创、拔除感染导管（6–12 h 内）","氧疗 SpO₂ 92%–96%；ARDS 按 6 mL/kg 预测体重肺保护通气；尿量≥0.5 mL/kg/h"],"life":["出院随访感染灶与疗程"]},"prog":"完成 1 h bundle 者病死率约 25%–35%。","refs":["中国脓毒症/脓毒性休克急诊治疗指南（2018）","拯救脓毒症运动国际指南（2021）"]},{"id":"em_airway_emerg","name":"急诊气道管理（快速诱导插管与失败处理）","aka":["RSI","困难气道"],"rank":4,"basic":{"define":"对不能维持气道通畅、通气或氧合的危重患者，以快速诱导插管（RSI）建立确定人工气道；核心是首要计划加失败预案，预氧与生理优化是首次成功的前提。","risk":["GCS≤8、误吸与大量上消化道出血","严重低氧与呼吸肌疲劳（心衰、COPD、哮喘）","上气道梗阻（喉头水肿、会厌炎、颈部肿瘤、外伤）","困难气道：张口度<3 指、Mallampati Ⅲ–Ⅳ、甲颏距<6 cm、颈围>40 cm"],"epi":"急诊插管首次成功率约 80%–90%；每次额外尝试显著增加低氧与心跳骤停风险。"},"patho":"气道梗阻或通气不足致低氧与高碳酸血症；平卧位功能残气量下降，危重者预氧储备有限。肌松后失去自主呼吸，一旦首次失败即需立即行声门上气道或外科气道，故必须提前准备。","dx":{"criteria":["插管指征：气道保护丧失（GCS≤8、误吸风险）、气道梗阻、通气衰竭（pH<7.25）、氧合失败（PaO₂/FiO₂<150 或 SpO₂<90% 难纠正）。","预氧：纯氧面罩 3–5 min，危重者可用无创通气；SpO₂ 目标≥93%–95%。","困难气道预判：3-3-2 规则、Mallampati、LEMON 与 MOANS 评估面罩通气与外科气道可行性。","插管后确认：双肺听诊、胸廓起伏、ETCO₂ 波形，气囊压 20–30 cmH₂O。"],"workup":["气道评估与困难气道清单，设备核查（可视喉镜、多型号导管、喉罩、吸引器）","心电血压脉搏血氧与 ETCO₂ 监护；插管后胸片确认深度（距门齿男 21–23 cm、女 19–21 cm）"]},"ddx":[{"name":"脓毒症 1 小时集束化治疗","point":"与本类中脓毒症的鉴别点：脓毒症的气道问题多继发低氧与脑灌注不足，需与 1 h bundle 同步；单纯气道急症以梗阻与通气衰竭为主。"},{"name":"哮喘持续状态与 COPD 加重","point":"广泛哮鸣与呼气延长；静默肺与二氧化碳蓄积需插管。"},{"name":"上气道梗阻","point":"吸气性喘鸣、声音嘶哑与无法平卧，需清醒评估并备外科气道。"},{"name":"阿片类过量","point":"针尖瞳与呼吸抑制，纳洛酮可逆转。"}],"tx":{"drug":[{"name":"依托咪酯","dose":"0.3 mg/kg 静推（休克或>60 岁 0.15–0.3 mg/kg）","note":"对血压影响小，但可抑制肾上腺皮质功能","interact":"遵说明书"},{"name":"氯胺酮","dose":"1–2 mg/kg 静推（休克 0.5–1 mg/kg）","note":"利于休克与支气管痉挛，但升高颅压与眼压","interact":"与镇静药协同减量"},{"name":"丙泊酚","dose":"1.5–2.5 mg/kg 静推（休克 0.5–1 mg/kg 缓慢）","note":"明显降压，用于血流动力学稳定者","interact":"与阿片类加重低血压"},{"name":"琥珀胆碱","dose":"1–1.5 mg/kg 静推","note":"起效 45–60 s；禁用于高钾、挤压伤与烧伤>72 h、恶性高热史","renal":"肾衰伴高钾禁用","hepatic":"胆碱酯酶缺乏者禁用","interact":"与洋地黄增心律失常"},{"name":"罗库溴铵","dose":"0.6–1.2 mg/kg 静推（CICO 时 1.2 mg/kg）","note":"可用舒更葡糖 16 mg/kg 拮抗；高钾风险者首选","renal":"肾衰者作用延长","interact":"氨基糖苷类延长作用"},{"name":"去氧肾上腺素或去甲肾上腺素","dose":"插管前休克者去氧肾上腺素 50–100 µg 或去甲肾上腺素 5–10 µg 静推","note":"预防插管期骤停","interact":"与 MAOI 显著升压"}],"nonDrug":["RSI 七步：准备、预氧、生理优化、体位、诱导与肌松、置管（可视喉镜首选）、确认与固定","困难气道预案：可视喉镜、喉罩、双人面罩通气、环甲膜切开；CICO 立即外科气道，不反复试插","插管后按 6–8 mL/kg 预测体重设置通气；清醒纤支镜用于张口受限与颈部肿物"],"life":["气道湿化与气囊压监测；拔管前自主呼吸与漏气试验"]},"prog":"规范预氧下并发症约 10%–20%；CICO 发生率约 0.1%–0.3%，一旦发生脑损伤与死亡风险极高。","refs":["中国急诊气道管理专家共识（2017）","困难气道管理指南（中华医学会麻醉学分会，2021）"]},{"id":"em_anaphylaxis","name":"过敏性休克","aka":["Anaphylaxis","严重过敏反应"],"rank":5,"basic":{"define":"IgE 介导（少数非 IgE）的急性全身性超敏反应，接触过敏原后数分钟至数小时出现皮肤黏膜、呼吸、循环与消化道多系统受累；伴低血压或气道梗阻者即过敏性休克。","risk":["食物（坚果、花生、海鲜、鸡蛋、牛奶）","药物：青霉素类、头孢菌素、造影剂、肌松药、NSAIDs","蜂蜇、乳胶与运动诱发食物依赖型过敏","合并重度哮喘、肥大细胞增多症与既往严重过敏史","合用 β 受体阻滞剂与 ACEI"],"epi":"终生患病率约 0.5%–2%；及时肌注肾上腺素者病死率<1%，延误是主要死因。"},"patho":"变应原交联肥大细胞表面 IgE，脱颗粒释放组胺与白三烯，致血管扩张、血浆外渗与支气管痉挛。数分钟内有效循环血量可下降 20%–35%，形成分布性休克。肾上腺素以 α1 收缩血管、β2 舒张支气管、β1 支持心肌，是唯一可扭转病程的药物。","dx":{"criteria":["急性起病伴皮肤黏膜受累并符合任一：呼吸道症状（喘鸣、呼吸困难、低氧）、血压下降或终末器官功能障碍、严重胃肠症状。","无皮肤表现者：接触已知过敏原后出现低血压或支气管痉挛亦可诊断（约 10%–20% 无皮疹）。","低血压：成人收缩压<90 mmHg 或较基线降>30%；儿童 1–10 岁<70+2×年龄 mmHg。","分级：Ⅰ 级皮肤黏膜、Ⅱ 级中度呼吸或循环、Ⅲ 级严重低氧或休克、Ⅳ 级呼吸心跳骤停。","双相反应约 5%–20% 在 1–24 h 复发，需观察 4–6 h（重症 6–12 h）。"],"workup":["ABCDE 与持续监护；气道评估（声音嘶哑、吸气性喘鸣提示上气道梗阻）","心电图、血气、血糖与心肌标志物","类胰蛋白酶（1–2 h 采血，24 h 后复基线）"]},"ddx":[{"name":"脓毒症 1 小时集束化治疗","point":"与本类中脓毒症的鉴别点：脓毒症有发热、感染灶与血培养阳性，起病以小时计；过敏性休克数分钟内出现荨麻疹与喉水肿，对肾上腺素反应快。"},{"name":"血管迷走性晕厥","point":"体位或情绪诱因，心动过缓，平卧数分钟恢复，无呼吸困难。"},{"name":"遗传性血管性水肿","point":"反复面颈水肿、无荨麻疹、有家族史，对肾上腺素无效。"},{"name":"急性哮喘发作","point":"哮鸣与呼气延长，无皮疹与低血压。"}],"tx":{"drug":[{"name":"肾上腺素（肌注，一线）","dose":"成人 0.3–0.5 mg 肌注大腿外侧（股外侧肌），儿童 0.01 mg/kg 最大 0.3–0.5 mg；5–15 min 可重复","note":"越早越好，不必等诊断明确；肌注比皮下吸收快","interact":"β 阻滞剂降低疗效（可用胰高血糖素）"},{"name":"肾上腺素（静脉）","dose":"1 mg 稀释于 100 mL 生理盐水按 5–15 µg/min 泵入；骤停者 1 mg 静推每 3–5 min","note":"静脉仅限监护条件","interact":"同前"},{"name":"0.9% 氯化钠","dose":"成人 500–1000 mL 快速静滴，儿童 20 mL/kg","note":"与肾上腺素同时进行","interact":"遵说明书"},{"name":"沙丁胺醇","dose":"2.5–5 mg 雾化，必要时重复","note":"仅用于持久支气管痉挛","interact":"与 β 阻滞剂拮抗"},{"name":"苯海拉明","dose":"25–50 mg 肌注或静推每 4–6 h","note":"仅缓解皮肤症状，不治疗气道与循环","interact":"加重中枢抑制"},{"name":"甲泼尼龙","dose":"40–80 mg 静推，必要时重复","note":"起效数小时，用于防双相反应","interact":"升血糖"},{"name":"胰高血糖素","dose":"1–5 mg 静推或 1–2 mg/h 泵入（用 β 阻滞剂者）","note":"用于顽固性低血压","interact":"影响血糖"}],"nonDrug":["立即脱离过敏原：停药、换生理盐水通路、清除蜂刺与残留食物","体位平卧抬高下肢；喉水肿早期插管或环甲膜切开","监护 4–6 h（重症 6–12 h）观察双相反应；出院评估是否配备自动注射笔并标注过敏原"],"life":["避免过敏原，由过敏专科评估脱敏；随身携带自动注射笔"]},"prog":"及时肌注者多分钟缓解，病死率<1%；延误（尤其合并哮喘与 β 阻滞剂）可致骤停。","refs":["中国严重过敏反应诊疗指南（2020）","WAO 严重过敏反应指南（2020）"]}]}]},"endo":{"categories":[{"id":"dm","name":"糖尿病","rank":1,"summary":"以 HbA1c 与糖化/空腹/负荷后血糖确诊，二甲双胍为多数 2 型糖尿病起始基石；合并动脉粥样硬化性心血管病、心衰或 CKD 者优先联合 SGLT2i 或 GLP-1RA。急性代谢紊乱（DKA/HHS）以补液为第一要务，胰岛素按固定速率泵入并监测钾离子。","compare":[{"diseaseId":"dm_t2","dx":"HbA1c ≥6.5% 或 FPG ≥7.0 mmol/L 或 OGTT 2hPG ≥11.1 mmol/L 或随机血糖 ≥11.1 伴典型症状；无酮症、无酸中毒","key":"起病隐匿，C 肽与胰岛素可正常或偏高，胰岛素自身抗体阴性，无自发酮症倾向"},{"diseaseId":"dm_t1","dx":"多为青少年起病、三多一少明显，起病时即可有酮症；空腹/餐后 C 肽显著降低，GAD/IA-2/IAA 等自身抗体阳性","key":"绝对胰岛素缺乏、依赖胰岛素生存，停用胰岛素数小时至数日即可发生 DKA"},{"diseaseId":"dm_dka","dx":"血糖 >13.9 mmol/L + 血酮 ≥3.0 mmol/L（或尿酮强阳性）+ 血 pH <7.30 和/或 HCO3− <18 mmol/L + 阴离子间隙升高","key":"以酮症酸中毒为主，血糖可仅轻中度升高；有效血浆渗透压多 <320 mOsm/kg"},{"diseaseId":"dm_hhs","dx":"血糖 ≥33.3 mmol/L + 有效血浆渗透压 >320 mOsm/kg + 显著高渗脱水、意识障碍，酮体阴性或仅弱阳性，pH ≥7.30","key":"以极度高血糖与高渗为主，多见于老年 2 型；补液量更大、胰岛素需要量更小"}],"diseases":[{"id":"dm_t2","name":"2 型糖尿病","aka":["T2DM","成人型糖尿病","非胰岛素依赖型糖尿病"],"rank":1,"basic":{"define":"以胰岛素抵抗伴胰岛 β 细胞功能相对不足为特征的慢性高血糖疾病，占全部糖尿病的 90% 以上，起病隐匿，常与肥胖、血脂异常、高血压聚集出现。","risk":["超重/肥胖（BMI ≥24 kg/m²，腹型肥胖腰围男 ≥90 cm、女 ≥85 cm）","糖尿病家族史（一级亲属）","年龄 ≥40 岁；有妊娠期糖尿病或巨大儿分娩史","高血压、血脂异常、多囊卵巢综合征、代谢相关脂肪性肝病","长期久坐、高糖高脂饮食、吸烟、长期使用糖皮质激素或抗精神病药"],"epi":"我国成人糖尿病患病率约 11.2%–12.8%，患者逾 1.4 亿，居全球首位；糖尿病前期人群约 3.5 亿。约半数患者诊断时已存在并发症或合并症。"},"patho":"遗传易感背景下，长期能量过剩与脂肪异位沉积导致骨骼肌、肝脏和脂肪组织胰岛素抵抗，肝糖输出增加、外周葡萄糖摄取减少；为代偿高血糖，胰岛 β 细胞代偿性分泌增多，随 β 细胞去分化与凋亡而功能逐步衰竭。高血糖通过多元醇通路、蛋白非酶糖化（AGEs）、PKC 激活与氧化应激损伤微血管（视网膜、肾小球、周围神经）与大血管内皮，形成慢性并发症。","dx":{"criteria":["HbA1c ≥6.5%（须用 NGSP/标准化方法检测）","空腹血糖 FPG ≥7.0 mmol/L（空腹指至少 8 h 无热量摄入）","OGTT 2 小时血糖 ≥11.1 mmol/L（75 g 无水葡萄糖）","有典型高血糖症状（多饮、多尿、多食、体重下降）或高血糖危象者，随机血糖 ≥11.1 mmol/L 即可诊断","无典型症状者需改日复测确认；同一份血样两项指标均达诊断切点（如 FPG + HbA1c）可确诊","HbA1c 受贫血、血红蛋白病、妊娠、近期输血影响时以血糖为准","糖尿病前期：IFG 6.1–6.9 mmol/L 或 IGT 2hPG 7.8–11.0 mmol/L 或 HbA1c 5.7%–6.4%"],"workup":["初诊评估：HbA1c、空腹及餐后 2 h 血糖、血脂（TC/LDL-C/TG/HDL-C）、肝肾功能、尿白蛋白/肌酐比值（UACR）、eGFR","眼底检查（散瞳眼底照相或眼科会诊）；10 型糖尿病神经病变筛查（10 g 尼龙丝、128 Hz 音叉、针刺痛觉、温度觉、踝反射）","足部检查：皮肤、足背动脉搏动、畸形与胼胝；足溃疡风险分级","心电图；有症状或高危者行冠脉评估；血压每次就诊测量","血糖自我监测或 CGM；必要时 C 肽、胰岛素抗体以与 LADA/1 型鉴别","疑 MODY 或单基因糖尿病（25 岁以下起病、家族史强、非肥胖）者行基因检测"],"grading":"按血糖控制与合并症分层：控制目标多数成人 HbA1c <7.0%；病程短、预期寿命长、无心血管病者可 <6.5%；高龄、有严重低血糖史、预期寿命短或合并严重并发症者放宽至 <8.0%。按并发症分为无并发症/早期（微量白蛋白尿、轻度视网膜病变）/晚期（大量蛋白尿、eGFR 下降、增殖期视网膜病变、足溃疡）。"},"ddx":[{"name":"1 型糖尿病（dm_t1）","point":"与本类 dm_t1 的鉴别点：T2DM 多中年以上起病、体型偏胖、起病缓、无自发酮症、C 肽正常或偏高、抗体阴性；T1DM 起病急、消瘦、易酮症、C 肽低平、自身抗体阳性。成人隐匿起病者（LADA）可先按 T2DM 管理，抗体阳性且 C 肽快速下降者应转为胰岛素治疗。"},{"name":"糖尿病酮症酸中毒（dm_dka）","point":"与本类 dm_dka 的鉴别点：T2DM 稳定期无酮体、pH 正常；一旦出现恶心呕吐、腹痛、深大呼吸、血糖 >13.9 mmol/L 并血酮升高、pH <7.30 即为 DKA，需急诊补液与静脉胰岛素。"},{"name":"高渗高血糖综合征（dm_hhs）","point":"与本类 dm_hhs 的鉴别点：HHS 血糖 ≥33.3 mmol/L、有效渗透压 >320 mOsm/kg、酮体阴性、意识障碍明显，多见于老年 T2DM 伴感染或脱水。"},{"name":"应激性高血糖","point":"严重感染、创伤、手术、急性心脑血管事件或使用糖皮质激素期间血糖升高，去除诱因后血糖可恢复；既往无糖尿病史者应于病情稳定 6–8 周后复查 HbA1c。"},{"name":"其他特殊类型糖尿病","point":"胰源性（慢性胰腺炎、胰腺切除）、内分泌病（库欣综合征、肢端肥大症、甲亢、嗜铬细胞瘤）、药物性（糖皮质激素、噻嗪类、抗精神病药、免疫检查点抑制剂）、单基因糖尿病（MODY）。"},{"name":"肾性糖尿","point":"尿糖阳性但血糖正常，因肾小管 SGLT 重吸收阈值下降；妊娠期生理性肾糖阈降低亦可见，OGTT 正常可排除。"}],"tx":{"drug":[{"name":"二甲双胍","dose":"起始 500 mg bid 或 850 mg qd，随餐服用；每 1–2 周递增，常用维持量 1500–2000 mg/d 分 2–3 次，最大 2550 mg/d（缓释剂 2000 mg qn）","note":"无禁忌时所有 T2DM 一线用药，且贯穿全程；不增加体重、不引起低血糖，可使 HbA1c 下降 1.0%–1.5%。eGFR 30–45 起始减半并减少剂量，eGFR <30 禁用；造影检查前后需按造影剂类型暂停（eGFR <60 者碘造影前后停用）。长期使用监测维生素 B12。","renal":"eGFR ≥45 无需调整；eGFR 30–44 最大 1000 mg/d 且不新增；eGFR <30 禁用；eGFR <45 不做造影前需停药 48 h 并于复查肾功能后恢复","hepatic":"失代偿肝病、转氨酶 >3 倍正常上限者避免使用（乳酸清除下降）","interact":"与碘造影剂、氨基糖苷类、袢利尿剂、NSAIDs、ACEI/ARB 合用增加乳酸酸中毒风险；酒精增加乳酸生成；西咪替丁可升高血药浓度"},{"name":"达格列净（SGLT2i）","dose":"10 mg qd，晨服，可与或不与食物同服","note":"合并 ASCVD 或高危、心衰（HFrEF/HFpEF）或 CKD（eGFR ≥20）者无论 HbA1c 是否达标均应使用；合并慢性肾病者推荐 eGFR ≥20 起始。为「心肾保护」类证据最充分药物之一，可使心衰住院风险下降约 30%。注意生殖泌尿道感染、容量不足、非高血糖性酮症酸中毒（正常血糖 DKA）、围手术期停药 3–4 天。","renal":"eGFR ≥45 降糖疗效好；eGFR 25–45 降糖作用减弱但心肾获益保留；eGFR <20 不推荐起始（用于心衰时按说明书）；透析患者不用","hepatic":"重度肝损伤（Child-Pugh C）不推荐起始","interact":"与利尿剂合用加重容量不足与低血压；与胰岛素/磺脲类联用增加低血糖风险（需减量）；与酮症倾向者合用注意 euDKA"},{"name":"恩格列净（SGLT2i）","dose":"10 mg qd，晨服；可增至 25 mg qd","note":"适用人群同达格列净；EMPA-REG OUTCOME 研究显示合并 CVD 者心血管死亡下降 38%。","renal":"eGFR <30 不推荐起始（心衰适应证按说明书）；透析禁用","hepatic":"重度肝损伤慎用","interact":"同达格列净"},{"name":"司美格鲁肽（GLP-1RA，周制剂）","dose":"0.25 mg 皮下注射 qw 起始，4 周后 0.5 mg qw，必要时 4 周后增至 1.0 mg qw，最大 2.0 mg qw","note":"合并 ASCVD、超重/肥胖（BMI ≥27 或有肥胖相关合并症）、脂肪肝者优先；可显著减重（5%–15%）并降低主要心血管事件（SUSTAIN-6）。以恶心、腹胀、便秘等胃肠道反应为主，从小剂量起始缓慢滴定。有甲状腺髓样癌家族史、多发性内分泌腺瘤病 2 型者禁用。","renal":"eGFR ≥15 无需调整；eGFR <15 不推荐；脱水时可加重肾损伤","hepatic":"轻中度肝损伤无需调整；重度肝损伤经验有限，慎用","interact":"延缓胃排空，可能影响口服药吸收（如华法林 INR）；与胰岛素/磺脲类联用需减量；与 DPP-4i 联用获益叠加有限"},{"name":"利拉鲁肽（GLP-1RA，日制剂）","dose":"0.6 mg 皮下注射 qd 起始，1 周后 1.2 mg qd，可增至 1.8 mg qd","note":"心血管获益证据（LEADER），适用人群同司美格鲁肽；每日注射。","renal":"eGFR <30 不推荐（无数据）","hepatic":"轻中度无需调整；重度慎用","interact":"同司美格鲁肽"},{"name":"西格列汀（DPP-4i）","dose":"100 mg qd","note":"体重中性、低血糖风险极低，适合高龄、肾功能不全或多药合用者；降糖幅度中等（HbA1c 下降 0.5%–0.8%），无明确心血管保护作用。注意急性胰腺炎及大疱性类天疱疮风险。","renal":"eGFR 30–44：50 mg qd；eGFR <30：25 mg qd；透析：25 mg qd","hepatic":"轻中度无需调整；重度不推荐","interact":"与胰岛素/磺脲类合用低血糖风险增加；与地高辛合用轻微升高地高辛浓度"},{"name":"格列美脲（磺脲类）","dose":"起始 1–2 mg qd 早餐前，按血糖每 1–2 周递增 1–2 mg，常用 1–4 mg/d，最大 6 mg/d","note":"降糖强效、价格低廉，但低血糖与体重增加；老年、肾功能不全、进食不规律者慎用或避免。","renal":"eGFR 30–60 起始 1 mg 并谨慎滴定；eGFR <30 不推荐","hepatic":"重度肝损伤禁用（低血糖风险）","interact":"β 受体阻滞剂掩盖低血糖症状；氟康唑、克拉霉素抑制 CYP2C9 增加低血糖风险；糖皮质激素、噻嗪类减弱降糖作用"},{"name":"甘精胰岛素 U100（基础胰岛素）","dose":"起始 0.1–0.2 U/kg qn 固定时间皮下注射；按空腹血糖每 3 天调整 2–4 U，直至 FPG 4.4–7.0 mmol/L","note":"口服药联合后 HbA1c 仍 >7.5%–8% 或空腹血糖显著升高者启动；HbA1c >9% 伴明显高血糖症状可直接双胍+基础胰岛素。注射后不可随意更换时间，警惕夜间低血糖。","renal":"eGFR <30 胰岛素需要量下降，减量并加强监测","hepatic":"肝功能不全者糖异生减少，低血糖风险增加，减量","interact":"β 受体阻滞剂掩盖低血糖；糖皮质激素升高血糖；酒精可致延迟低血糖"}],"nonDrug":["代谢手术（胃旁路、袖状胃切除）：BMI ≥32.5 或 ≥27.5 且药物控制不佳伴合并症者考虑，术后可显著改善血糖甚至缓解","胰岛素泵（CSII）或持续葡萄糖监测（CGM）：血糖波动大、反复低血糖或需要精细控制者","每年至少 1 次糖尿病并发症筛查（眼底、UACR、eGFR、足部与神经检查）","合并肥胖者设置减重目标（3–6 个月减 5%–10% 体重）"],"life":["主食定量、粗细搭配，碳水化合物占 45%–60% 总能量；限盐 <5 g/d，限添加糖","每周至少 150 min 中等强度有氧运动（快走、骑车），每周 2–3 次抗阻训练；避免连续 2 天不运动","戒烟限酒；控制体重与腰围","自我血糖监测：注射胰岛素者每日至少 1–2 次，口服药者按需；定期查 HbA1c（每 3 个月）","血压目标 <130/80 mmHg，LDL-C 目标 <1.8 mmol/L（合并 ASCVD <1.4 mmol/L）","足部护理：每日检查，选合适鞋袜，避免赤足行走；每年足部风险分级","每年接种流感疫苗，按适应证接种肺炎球菌、乙肝疫苗"]},"prog":"早期严格控糖可延缓微血管并发症，且存在「代谢记忆」效应；病程 10 年以上者视网膜病变与肾病风险显著上升。心血管疾病为最主要死因，SGLT2i 与 GLP-1RA 可分别降低心衰住院与主要心血管事件。早发 T2DM 者并发症出现更早、预期寿命缩短更多。","refs":["中华医学会糖尿病学分会：中国 2 型糖尿病防治指南（2020 年版）","中国 2 型糖尿病防治指南（2024 年版，CDS）","国家基层糖尿病防治管理指南（2022）","ADA Standards of Care in Diabetes—2025","KDIGO 2022 Clinical Practice Guideline for Diabetes Management in CKD"]},{"id":"dm_t1","name":"1 型糖尿病","aka":["T1DM","胰岛素依赖型糖尿病","幼年型糖尿病"],"rank":2,"basic":{"define":"由自身免疫介导的胰岛 β 细胞破坏导致绝对胰岛素缺乏的糖尿病，须终身依赖胰岛素替代治疗，任何中断都可能迅速诱发 DKA。","risk":["儿童与青少年起病（高峰 4–6 岁与 10–14 岁），成人亦可发病","一级亲属患 1 型糖尿病","合并其他自身免疫病（桥本甲状腺炎、Graves 病、Addison 病、乳糜泻）","HLA-DR3/DR4-DQ8 等易感基因型","柯萨奇病毒等肠道病毒感染、维生素 D 缺乏等环境因素（相关性，非确证）"],"epi":"我国 1 型糖尿病约占糖尿病患者的 0.5%–1%，绝对患者数不少；儿童 0–14 岁发病率约 1.5–3/10 万人年，且呈上升趋势。成人迟发型（LADA）常被误诊为 2 型。"},"patho":"在遗传易感基础上，由胰岛自身抗原（GAD65、IA-2、胰岛素、ZnT8）驱动的 T 细胞介导自身免疫反应，选择性破坏 β 细胞。β 细胞功能在数月到数年内进行性丧失，胰岛素分泌绝对不足：基础胰岛素缺失使肝糖输出失控、空腹血糖升高；餐时胰岛素缺乏使餐后血糖剧烈波动；脂肪分解不受抑制，游离脂肪酸氧化生成酮体，故轻中度应激即可触发酮症酸中毒。","dx":{"criteria":["符合糖尿病诊断标准（同 2 型：HbA1c ≥6.5%、FPG ≥7.0、2hPG ≥11.1 或随机血糖 ≥11.1 伴症状）","存在胰岛自身抗体：GAD65 抗体最具敏感性，另可查 IA-2A、IAA、ZnT8A；任一项阳性支持 1 型","C 肽降低：空腹 C 肽 <0.2 nmol/L 提示显著 β 细胞衰竭；混合餐试验刺激后 C 肽峰值 <0.6 nmol/L","起病时酮症或 DKA 常见，BMI 多正常或偏低，无代谢综合征特征","成人起病者需与 LADA 鉴别：30 岁以上、6 个月内非肥胖且不需胰岛素即可控制者应查 GAD 抗体","儿童起病伴多饮多尿、体重快速下降、可能夜间遗尿"],"workup":["血糖谱（空腹 + 餐后 2 h + 睡前）、HbA1c、血/尿酮体","胰岛自身抗体组合（GAD65、IA-2A、IAA、ZnT8A）与空腹及餐后 C 肽","血气分析与电解质（起病时评估 DKA）","甲状腺功能与抗 TPO 抗体（自身免疫性甲状腺病筛查）","乳糜泻筛查（tTG-IgA）、维生素 B12、自身免疫性胃炎（内因子/壁细胞抗体）按需","骨密度（病程长者）、血脂、肾功能与 UACR、眼底","CGM 或胰岛素泵适配评估"],"grading":"按病程阶段：①临床前（1 期：≥2 种抗体阳性、血糖正常；2 期：抗体阳性 + 糖代谢异常但无症状；3 期：临床糖尿病）。血糖控制目标多数成人 HbA1c <7.0%（儿童青少年按年龄：<6 岁 <8.0%、6–12 岁 <7.5%、青春期 <7.0%）。"},"ddx":[{"name":"2 型糖尿病（dm_t2）","point":"与本类 dm_t2 的鉴别点：T2DM 多伴肥胖、胰岛素抵抗表现（黑棘皮、高血压、脂肪肝），C 肽正常/升高、抗体阴性、无自发酮症；T1DM 体型瘦、抗体阳性、C 肽低平。成人起病且消瘦、短期内需胰岛素者应按 LADA 检验抗体。"},{"name":"糖尿病酮症酸中毒（dm_dka）","point":"与本类 dm_dka 的鉴别点：T1DM 患者约 20%–30% 以 DKA 首诊；DKA 是急性并发症而非独立疾病，诊断按血糖 >13.9、血酮 ≥3.0、pH <7.30。已知 T1DM 出现呕吐腹痛、呼吸深快须立即查血酮，勿误为胃肠炎。"},{"name":"高渗高血糖综合征（dm_hhs）","point":"与本类 dm_hhs 的鉴别点：HHS 几乎不见于典型 T1DM（多见于老年 T2DM），特征是血糖 ≥33.3、渗透压 >320 而酮体阴性、pH 正常。"},{"name":"MODY（单基因糖尿病）","point":"常染色体显性遗传、25 岁前起病、连续三代家族史，自身抗体阴性、C 肽保留，部分类型（GCK-MODY）无需药物治疗；基因检测确诊。"},{"name":"胰腺外分泌疾病所致糖尿病（3c 型）","point":"慢性胰腺炎、胰腺切除、囊性纤维化后起病，伴脂肪泻、影像学胰腺萎缩或钙化，抗体阴性。"},{"name":"其他原因消瘦与多尿","point":"甲亢（怕热多汗、TSH 低）、尿崩症（大量低比重尿、血糖正常）、精神性多饮，需查血糖与尿糖排除。"}],"tx":{"drug":[{"name":"基础-餐时胰岛素方案（MDI）","dose":"每日总量起始 0.3–0.5 U/kg，初诊者 0.2–0.4 U/kg；其中 40%–50% 为基础胰岛素（甘精 U100/德谷/地特，qn 固定），其余按三餐平均分配（超短效：门冬/赖脯/赖谷，餐前 10–15 min 皮下注射）；按碳水化合物系数与校正因子调整","note":"多数 1 型糖尿病患者推荐；需教患者碳水化合物计数与剂量调整。青春期、感染、应激时需求量增加，运动或饮酒时减少。","renal":"eGFR <45 起胰岛素清除下降、需要量减少，逐步减量并加强监测","hepatic":"肝功能不全时糖异生减少，低血糖风险增加，减量","interact":"β 受体阻滞剂掩盖低血糖；糖皮质激素使需要量上升；单胺氧化酶抑制剂可增强降糖作用"},{"name":"德谷胰岛素（基础胰岛素类似物）","dose":"起始 0.1–0.2 U/kg qd（或由既往基础量转换，一日一次），固定或大致固定时间皮下注射，按空腹血糖每 2–3 天调整 2 U","note":"超长效，低血糖（尤其夜间）风险低于甘精 U100；日间剂量调整相对灵活。","renal":"eGFR <45 减量并加强监测","hepatic":"重度肝损伤减量并监测","interact":"同胰岛素共性（β 受体阻滞剂、糖皮质激素、酒精）"},{"name":"门冬胰岛素（餐时）","dose":"按餐前血糖与碳水摄入量给药，起步每次 4 U 或按总剂量 1/6 起，餐前即刻（0–10 min）皮下注射","note":"超短效类似物，吸收快、餐后血糖控制优于人胰岛素；胰岛素泵中作为常规用泵。","renal":"eGFR <30 需减量，低血糖风险增加","hepatic":"重度肝损伤减量","interact":"同胰岛素共性"},{"name":"赖脯胰岛素（餐时）","dose":"同门冬胰岛素，餐前 0–15 min 皮下注射，按碳水计数与校正因子计算","note":"可与门冬互为替代；避免与不同品牌胰岛素同时混抽（除非说明书允许）。","renal":"eGFR <30 减量","hepatic":"重度肝损伤减量","interact":"同胰岛素共性"},{"name":"普兰林肽（辅助）","dose":"起始 15 μg 皮下注射，随主餐（≥250 kcal 或 ≥30 g 碳水）；耐受后按说明书滴定","note":"国内可及性有限；可减少餐后血糖波动与体重，但增加低血糖风险，须与餐时胰岛素同步减量；与胃排空延迟药物合用时慎用。","renal":"eGFR <30 不推荐","hepatic":"轻中度无需调整；重度无数据","interact":"与胰岛素合用低血糖风险增加；抗胆碱能药（如部分解痉药）加重胃排空延迟"}],"nonDrug":["持续皮下胰岛素输注（CSII，胰岛素泵）：幼童、血糖波动大或反复低血糖者，需配合 CGM","持续葡萄糖监测（CGM）：推荐所有 1 型糖尿病使用，HbA1c 之外关注 TIR（目标 70%–180 mg/dL 内 ≥70%）","临床试验：1 期/2 期患者可考虑免疫干预（抗 CD3、teplizumab）延缓临床起病（国内尚未常规可及）","胰岛/胰腺移植：仅在合并终末期肾病需肾移植或严重反复低血糖者考虑","教育：DKA 预防与生病日规则（sick-day rules）"],"life":["学会碳水化合物计数与胰岛素剂量调整；随身携带糖块与胰高血糖素（或葡萄糖凝胶）","运动前查血糖，<5.6 mmol/L 先补碳水；运动时减少餐前胰岛素并监测","生病日规则：发热/呕吐时每 4 h 测血糖与血酮，不中断基础胰岛素，酮体阳性立即就医","定期筛查：每年眼底、UACR/eGFR、甲状腺功能、足部；儿童每 3–6 个月随访生长与青春期发育","避免空腹饮酒；驾驶前血糖 ≥5.0 mmol/L","心理支持与家庭参与：糖尿病困扰、进食障碍在青少年中常见"]},"prog":"须终身胰岛素治疗，现代 MDI/泵 + CGM 可将 HbA1c 控制在 7% 左右并显著减少严重低血糖。微血管并发症风险与血糖控制直接相关；合并肾病者 20–30 年后约 30%–40% 进展为终末期肾病。DKA 是最常见的急性致死原因，多与胰岛素中断、感染或泵故障有关。","refs":["中国 1 型糖尿病诊治指南（2021 版，中华医学会糖尿病学分会）","中国儿童 1 型糖尿病标准化诊断与治疗专家共识（2020 版）","中国成人 1 型糖尿病诊疗指南（2023）","ADA Standards of Care in Diabetes—2025（Type 1 Diabetes 章节）","ISPAD Clinical Practice Consensus Guidelines 2022"]},{"id":"dm_dka","name":"糖尿病酮症酸中毒","aka":["DKA","酮症酸中毒","糖尿病酮症"],"rank":3,"basic":{"define":"胰岛素绝对或相对缺乏与升糖激素（胰高血糖素、儿茶酚胺、皮质醇、生长激素）过度分泌共同导致的高血糖、高血酮与代谢性酸中毒综合征，为糖尿病最常见的急危重症之一。","risk":["1 型糖尿病（新发或胰岛素中断、泵故障）","感染（肺部、泌尿系、皮肤软组织）为最常见诱因","急性心肌梗死、脑卒中、胰腺炎、创伤、手术","胰岛素剂量不足、漏用、过期或保存不当","糖皮质激素、噻嗪类、SGLT2i（正常血糖性 DKA）、抗精神病药","妊娠、酗酒、进食障碍（饥饿性酮症叠加）"],"epi":"我国 DKA 占糖尿病急性并发症的 70%–80%，住院病死率约 1%–5%（老年与合并感染者更高）；SGLT2i 相关正常血糖性 DKA 近年报道增加，易被漏诊。"},"patho":"胰岛素缺乏使葡萄糖无法进入细胞，同时升糖激素促进肝糖原分解与糖异生，造成高血糖与渗透性利尿；脂肪组织脂解增强，游离脂肪酸在肝脏经 β 氧化生成大量乙酰辅酶 A，转为酮体（β-羟丁酸、乙酰乙酸、丙酮）。酮体为有机酸，消耗碳酸氢盐，形成高阴离子间隙代谢性酸中毒。渗透性利尿导致严重脱水（平均 5–8 L）与电解质丢失（钾丢失 3–5 mmol/kg）；血清钾因酸中毒与胰岛素缺乏从细胞内移出而早期可正常，补液与胰岛素治疗后迅速下降，是致命性心律失常的主要风险。","dx":{"criteria":["血糖 >13.9 mmol/L（约 250 mg/dL）；约 10% 患者为正常血糖性 DKA（血糖 <13.9），尤其使用 SGLT2i 或妊娠期","血酮 ≥3.0 mmol/L（β-羟丁酸，首选）或尿酮体 ≥2+（注意以硝基盐法为主，β-羟丁酸不显色，恢复期可出现假阴性）","动脉血 pH <7.30 和/或 HCO3− <18 mmol/L，阴离子间隙（Na+ − [Cl− + HCO3−]）>12 mmol/L","有效血浆渗透压 <320 mOsm/kg（与 HHS 鉴别）；意识状态可清醒至昏迷","临床线索：多尿多饮加重、恶心呕吐、腹痛（可误为急腹症）、Kussmaul 深大呼吸、呼气烂苹果味、脱水、心率快","严重程度：轻度 pH 7.25–7.30 且 HCO3− 15–18；中度 pH 7.00–7.24 且 HCO3− 10–15；重度 pH <7.00 且 HCO3− <10（伴意识障碍）"],"workup":["即刻：指尖血糖、血酮（β-羟丁酸）、血气分析（优先静脉血）、电解质（K/Na/Cl/Mg/P）、肾功能、阴离子间隙与校正钠","血常规、CRP、降钙素原；尿常规与尿培养、胸片、必要时血培养以寻找感染","心电图（找低钾的 U 波、高钾的 T 波改变、心肌缺血）","诱发因素筛查：心肌酶与心电图、腹部影像（胰腺炎）、妊娠试验（育龄女性）","每 2–4 h 复查血糖、血酮、电解质、血气直至酮体清除与阴离子间隙正常"],"grading":"按 pH 与 HCO3− 分轻/中/重度（见诊断标准第 6 条）；儿童另有 ISPAD 标准（pH <7.30、HCO3− <18、血糖 >11 mmol/L + 尿酮/血酮阳性）。"},"ddx":[{"name":"高渗高血糖综合征（dm_hhs）","point":"与本类 dm_hhs 的鉴别点：DKA 以酮症酸中毒为主，血糖常 13.9–33.3、血酮 ≥3.0、pH <7.30、渗透压多 <320；HHS 血糖 ≥33.3、有效渗透压 >320、酮体阴性或弱阳性、pH ≥7.30、意识障碍更重。二者可重叠（约 1/3 患者兼有两种特征），按酸中毒程度决定处理重心。"},{"name":"2 型糖尿病（dm_t2）/1 型糖尿病（dm_t1）稳定期","point":"与本类 dm_t1、dm_t2 的鉴别点：稳定期血糖可高但无血酮升高、无酸中毒、无 Kussmaul 呼吸；出现 pH <7.30 + 血酮 ≥3.0 即转为 DKA。新发 T1DM 以 DKA 首诊者约 20%–30%。"},{"name":"乳酸酸中毒（双胍相关或休克）","point":"pH 下降但血酮正常、乳酸 >5 mmol/L、阴离子间隙升高，血糖可正常或偏低；多见于休克、肝衰或大剂量双胍，处理以停双胍、补液、必要时 CRRT 为主。"},{"name":"饥饿性酮症（酒精性酮症酸中毒）","point":"长期饥饿或酗酒者血糖正常或偏低、血酮升高但血糖低，经补葡萄糖 + 生理盐水快速改善；需结合饮酒史与营养状况。"},{"name":"急性胰腺炎 / 外科急腹症","point":"腹痛剧烈、血淀粉酶/脂肪酶 ≥3 倍上限；但 DKA 本身可致腹痛与淀粉酶轻度升高，需在纠正酸中毒后复评，避免误开腹。"},{"name":"尿毒症性酸中毒、水杨酸中毒","point":"尿毒症时 eGFR 显著下降、阴离子间隙升高但酮体阴性；水杨酸中毒有耳鸣、呼吸深快、混合性酸碱失衡，可测得血药浓度。"}],"tx":{"drug":[{"name":"0.9% 氯化钠（补液）","dose":"第 1 小时 1000–1500 mL（心衰/肾功能不全者 500–1000 mL 并评估）；随后 250–500 mL/h，前 4–6 h 按 4–6 L 累计目标；血糖降至 11.1–13.9 mmol/L 时换为 5% 葡萄糖+0.45% 或 0.9% 氯化钠维持（同样速度），直至酮体清除","note":"补液是首要治疗，先于胰岛素；合并心衰、CKD 或老年患者需床旁/超声评估容量状态，避免肺水肿。补钾 <3.3 mmol/L 时应暂停胰岛素先补钾。","renal":"eGFR <30 或透析患者补液量与速度减半，监测尿量与心功能","hepatic":"重度肝损伤伴低白蛋白者易水肿，减慢速度","interact":"与保钾利尿剂、ACEI/ARB 合用注意高钾；大量生理盐水可致高氯性酸中毒，需复查阴离子间隙"},{"name":"常规胰岛素（短效，静脉泵入）","dose":"0.1 U/kg/h 持续静脉泵入（起始可予 0.1 U/kg 负荷，近年指南推荐可直接持续泵入而不必负荷）；目标血糖下降速度 2.8–4.2 mmol/L/h；血糖降至 11.1–13.9 mmol/L 时胰岛素减至 0.05 U/kg/h 并加葡萄糖；血酮 <0.6 mmol/L 且阴离子间隙正常、可经口进食后转皮下基础-餐时方案","note":"国内常用胰岛素泵入 0.1 U/kg/h，相当于 6–8 U/h；血酮下降速度 <0.5 mmol/L/h 或血糖下降不足应评估补液与胰岛素通路。转皮下胰岛素时须重叠 1–2 h 再停静脉泵，避免反弹。","renal":"肾功能不全时胰岛素清除下降，低血糖风险增加，需更频繁监测并酌情减至 0.05 U/kg/h","hepatic":"肝功能不全糖异生减少，减量并监测","interact":"β 受体阻滞剂掩盖低血糖；糖皮质激素升高血糖；补钾不足时胰岛素可诱发致命心律失常"},{"name":"氯化钾（补钾）","dose":"血钾 <5.2 mmol/L 且尿量 >30 mL/h 时，每升液体中加 10–20 mmol（最多 40 mmol/L，外周静脉不超过 10 mmol/h）；血钾 <3.3 mmol/L 时先以 20–40 mmol/h 补钾并暂停胰岛素，血钾 ≥3.3 再启动胰岛素泵入","note":"DKA 患者总体缺钾但血钾因酸中毒可正常或升高；补液和胰岛素后血钾迅速下降，需每 2–4 h 复查。心电图监测。","renal":"eGFR <30 或透析者降低补钾速度，警惕高钾","hepatic":"无特殊调整","interact":"与保钾利尿剂、ACEI/ARB、螺内酯合用加重高钾（尤其在补液后肾功能未恢复时）"},{"name":"碳酸氢钠","dose":"仅 pH <6.9 时考虑：50 mmol（5% 碳酸氢钠 100 mL）缓慢静滴，30–60 min 后复查；pH ≥7.0 不用","note":"常规补碱不改善预后，可加重低钾、细胞内酸中毒与反常性中枢酸中毒；仅在极重度酸中毒或高钾致心律失常时谨慎使用。","renal":"肾功能不全者补碱易致容量负荷与碱中毒，慎用","hepatic":"无特殊调整","interact":"与含钙液体同通路可沉淀；与儿茶酚胺在碱性液中失活，需分开通路"},{"name":"磷酸盐（按需）","dose":"血磷 <0.32 mmol/L 或出现呼吸肌无力、心功能不全时，遵医嘱补充磷（如磷酸钾 10–20 mmol 缓慢静滴，按体重与血磷滴定）","note":"DKA 补液与胰岛素可致低磷，但常规补磷无证据；仅在严重低磷伴症状时补充。","renal":"肾功能不全者慎用（易致钙磷沉积）","hepatic":"无特殊调整","interact":"与钙剂同用可致磷酸钙沉淀"}],"nonDrug":["持续心电、血氧与意识监测；记录出入量","积极寻找并处理诱因（抗感染、处理心肌梗死、解除泵故障、停药）","鼻胃管减压（呕吐频繁/意识障碍）；误吸预防；昏迷者按 Glasgow 评分评估","DKA 脑水肿（多见于儿童）：出现头痛、意识恶化、心率减慢与高血压时，立即予甘露醇 0.5–1 g/kg 或高渗盐水并减慢补液","儿童 DKA 补液更保守：48 h 内补齐脱水，避免快速纠正"],"life":["出院前完成「生病日规则」与胰岛素自我调整教育","常规测血酮：血糖 >13.9 mmol/L 或身体不适时测一次","不自行中断基础胰岛素；泵故障时立即改用注射","筛查并治疗抑郁、进食障碍（频繁 DKA 的常见心理根源）","SGLT2i 使用者围手术期、禁食、大量饮酒或急性病时暂停药物"]},"prog":"规范治疗下病死率约 1%–5%，主要死因为低钾性心律失常、感染、误吸与合并的心血管事件；老年、昏迷、严重感染与低血压者病死率显著升高。复发率高，常与胰岛素依从性差、心理社会因素、SGLT2i 使用或未诊断的糖尿病相关。及时识别诱因与规范补液、补钾可显著改善结局。","refs":["中国糖尿病防治指南（2020 年版，DKA 章节）","中国糖尿病酮症酸中毒与高渗高血糖综合征临床诊疗指南（2023）","糖尿病酮症酸中毒诊疗专家共识（中华医学会内分泌学分会）","ADA Standards of Care in Diabetes—2025（Hyperglycemic Crises 章节）","Joint British Diabetes Societies (JBDS) Inpatient Care Group: The Management of Diabetic Ketoacidosis, 2023"]},{"id":"dm_hhs","name":"糖尿病高渗高血糖综合征","aka":["HHS","高渗性非酮症糖尿病昏迷","HONK","高渗高血糖状态"],"rank":4,"basic":{"define":"以严重高血糖（≥33.3 mmol/L）、高血浆渗透压（>320 mOsm/kg）与重度脱水为特征、酮体阴性或轻度升高的糖尿病急性代谢紊乱，常伴意识障碍甚至昏迷，多发生于老年 2 型糖尿病患者。","risk":["老年 2 型糖尿病，尤其是新诊断、症状隐匿者","感染（肺炎、尿路感染、脓毒症）为最常见诱因","脱水：呕吐腹泻、摄水不足、利尿剂、腹膜透析","噻嗪类利尿剂、糖皮质激素、苯妥英钠、抗精神病药","急性心脑血管事件、近期手术、肠内营养（高渗配方）","认知障碍、独居、行动不便而无法自主饮水者"],"epi":"HHS 占糖尿病急性高血糖危象的 1/3 左右，病死率（约 10%–20%）明显高于 DKA；多见于 60 岁以上老年，平均年龄约 65–70 岁，国内报道病死率 15%–30%。约 1/3 患者既往未诊断糖尿病。"},"patho":"相对胰岛素不足（足以抑制酮体生成，但不足以控制血糖）与大量升糖激素共同作用，使肝脏持续糖异生、肌肉摄取葡萄糖减少，形成极度高血糖；严重高血糖造成渗透性利尿，丢失大量自由水（>10 L），失水多于失钠，导致高渗状态；高渗使脑细胞脱水、脑组织皱缩，出现意识障碍、抽搐与局灶神经体征。同时血液浓缩、黏滞度增高，血栓栓塞风险升高。酮体不显著的原因可能包括残留胰岛素足以抑制脂解、合并使用抑制脂肪分解的药物等。","dx":{"criteria":["血糖 ≥33.3 mmol/L（约 600 mg/dL）","有效血浆渗透压 >320 mOsm/kg；常用计算式：2×[Na+] + 血糖（mmol/L）（或 2×Na+ + 葡萄糖 mg/dL/18），部分文献加尿素","酮体阴性或弱阳性（血 β-羟丁酸 <3.0 mmol/L），动脉血 pH ≥7.30、HCO3− ≥18 mmol/L","显著脱水（体重丢失、皮肤弹性差、黏膜干燥、眼压低、心动过速）与进行性意识障碍（嗜睡至昏迷），可有癫痫发作、偏瘫、失语等局灶体征","多伴高钠或血钠正常但校正钠（每升高 5.6 mmol/L 血糖，Na+ 约下降 1.6 mmol/L）升高","与 DKA 可重叠（混合性高血糖危象），需同时评估 pH、血酮与渗透压"],"workup":["即刻血糖、血气、电解质（K/Na/Cl）、血尿素、肌酐、血浆渗透压、血酮","计算阴离子间隙与校正血钠；评估有效渗透压","感染筛查：血常规、CRP/PCT、尿培养、胸片/胸部 CT、血培养","心电图与心肌酶、头颅影像（意识障碍或局灶体征者排除卒中）","评估血栓栓塞风险（D-二聚体、下肢超声按需）；关注房颤风险","每 2–4 h 复查血糖、电解质与肾功能，避免血钠与渗透压下降过快"],"grading":"无官方分期；按意识状态（清醒/嗜睡/昏迷）与渗透压升高幅度判断严重程度；渗透压 >350 mOsm/kg 常伴昏迷，病死率显著升高。"},"ddx":[{"name":"糖尿病酮症酸中毒（dm_dka）","point":"与本类 dm_dka 的鉴别点：HHS 酮体阴性、pH ≥7.30、血糖 ≥33.3、渗透压 >320、意识障碍显著；DKA 血酮 ≥3.0、pH <7.30、有效渗透压多 <320、呼吸深快有烂苹果味。凡血糖 >33 且意识障碍者，必须同时查血酮与 pH。"},{"name":"1 型糖尿病（dm_t1）/2 型糖尿病（dm_t2）稳定期","point":"与本类 dm_t2、dm_t1 的鉴别点：稳态糖尿病患者虽可血糖升高，但无高渗脱水、渗透压 >320 与意识改变；出现上述表现即为 HHS 危象，需急诊补液。"},{"name":"急性脑血管病（脑梗死/脑出血）","point":"可致意识障碍与局灶体征，血糖可应激性升高，但通常 <33 mmol/L 且无高渗脱水；头颅 CT/MRI 可确诊。HHS 的局灶体征可在纠正渗透压后消失。"},{"name":"低钠血症性脑病 / 高钠血症","point":"血钠显著异常引起意识改变，但血糖不会 ≥33；注意 HHS 因高血糖稀释血钠，需用校正钠评估真实钠水平，避免误判。"},{"name":"尿毒症性脑病 / 肝性脑病","point":"尿素氮、肌酐显著升高或肝功能失代偿（氨升高、扑翼样震颤），血糖与渗透压一般正常；合并肾病者两类情况可重叠。"},{"name":"脓毒症脑病","point":"发热或低体温、血压下降、乳酸升高、PCT 升高；常为 HHS 的诱因而非替代诊断，需同时治疗感染与危象。"}],"tx":{"drug":[{"name":"0.9% 氯化钠（补液，首选）","dose":"第 1 小时 1000–1500 mL 静滴（无心衰者）；随后 250–500 mL/h，前 24 h 目标补充 6–10 L；血钠 >150 mmol/L 或校正钠明显升高时可改用 0.45% 氯化钠；血糖降至 13.9–16.7 mmol/L 时换为 5% 葡萄糖维持","note":"HHS 脱水程度（可达 12–15 L）比 DKA 更重，补液是决定预后的关键；但老年心功能不全者需分次、减慢速度，避免肺水肿与渗透压骤降。","renal":"eGFR <30 或心衰者减量并监测尿量、中心静脉压/床旁超声","hepatic":"肝硬化腹水者需谨慎评估容量，避免大量晶体液致腹水加重","interact":"大量生理盐水可致高氯性代谢性酸中毒；与利尿剂合用加重低钾"},{"name":"常规胰岛素（短效，静脉泵入）","dose":"起始 0.05–0.1 U/kg/h 持续静脉泵入（HHS 胰岛素抵抗程度低于 DKA，可低剂量起始）；血糖下降速度控制在 2.8–4.2 mmol/L/h；血糖降至 13.9–16.7 mmol/L 时减半并加葡萄糖，维持血糖 13.9–16.7 mmol/L 直至渗透压正常、神志恢复","note":"不要快速降糖降渗，渗透压下降速度 >5 mOsm/kg/h 可能诱发脑水肿与低血容量性休克；与 DKA 不同，HHS 酮体阴性，以血糖与渗透压为目标而非酮体。","renal":"肾功能不全者减量（0.05 U/kg/h）并加强血糖监测","hepatic":"重度肝损伤者减量","interact":"同 DKA：β 受体阻滞剂掩盖低血糖、糖皮质激素升糖、补钾不足诱发心律失常"},{"name":"氯化钾（按需补钾）","dose":"血钾 <5.0 mmol/L 且尿量正常时，每升液体加 10–20 mmol 氯化钾；血钾 <3.5 mmol/L 时先补钾再启动胰岛素；血钾 >5.5 mmol/L 且无尿时暂停补钾","note":"与 DKA 类似，HHS 总钾缺乏，但患者多为老年合并 CKD，高钾风险更高，需每 4 h 监测。","renal":"eGFR <30 降低补钾量并每 4 h 监测","hepatic":"无特殊调整","interact":"ACEI/ARB、保钾利尿剂合用注意高钾"},{"name":"低分子肝素（血栓预防）","dose":"如依诺肝素 40 mg 皮下注射 qd（按体重与出血风险调整，遵说明书）","note":"高渗、血液浓缩与卧床使 VTE 风险显著升高，无活动性出血者建议预防性抗凝直至可下床活动。","renal":"eGFR <30 减量或改用 UFH 并监测抗 Xa 因子","hepatic":"严重肝病伴凝血障碍者禁用","interact":"与抗血小板、NSAIDs、OAC 合用出血风险增加"}],"nonDrug":["明确并处理诱因：抗感染（HHS 最常由感染触发，需经验性抗菌后根据培养调整）、停用诱发药物（利尿剂、糖皮质激素）","密切监测意识、瞳孔、生命体征与出入量；昏迷者翻身拍背、预防压疮与误吸","查找卒中与心肌梗死等并存急性事件","恢复期评估认知功能与照护支持（独居老人常因摄水不足复发）","纠正后转入糖尿病长期管理方案"],"life":["老年人及认知障碍者设置定时饮水提醒，家属或护理员监督饮水量（每日 1500–2000 mL，心衰者遵医嘱）","血糖监测规范化：血糖 >16.7 mmol/L 时每 4 h 测血酮/尿酮","避免脱水诱因：腹泻呕吐时补液、夏季高温注意；使用利尿剂者复查电解质","出院后 1–2 周门诊复评血糖、电解质与渗透压，优化降糖方案","教育与预警：家属识别嗜睡、口干、尿量减少等早期信号"]},"prog":"病死率 10%–20%，显著高于 DKA；合并休克、感染、昏迷、心肌梗死或高龄者病死率可达 30% 以上。恢复期的关键为纠正脱水与诱因；复发与照护不足、利尿剂使用、感染控制不佳相关。规范化补液与缓慢降渗可降低脑水肿与低血容量休克风险。","refs":["中国糖尿病酮症酸中毒与高渗高血糖综合征临床诊疗指南（2023）","中国糖尿病防治指南（2020 年版，急性并发症章节）","内分泌代谢病急危重症诊疗中国专家共识","ADA Standards of Care in Diabetes—2025（Hyperglycemic Crises 章节）","UpToDate 相关专题：Hyperosmolar hyperglycemic state（HHS）成人管理要点"]}]},{"id":"thyroid","name":"甲状腺","rank":2,"summary":"甲状腺功能异常的诊断锚点是 TSH 与游离甲状腺激素，病因定位依靠 TRAb、超声与摄碘率。甲亢首选抗甲状腺药物，甲状腺危象以 PTU 大剂量阻断合成 + 碘剂阻断释放 + β 阻滞剂，且碘剂必须在 PTU 后 1 h 再用；甲减以左甲状腺素替代并按 TSH 滴定。","compare":[{"diseaseId":"thy_hypER","dx":"TSH 降低、FT4/FT3 升高；Graves 病 TRAb 阳性、弥漫性甲状腺肿伴血管杂音、伴突眼或胫前黏液性水肿；摄碘率增高","key":"甲状腺功能亢进本身，以 ATD 抑制合成并可治愈/长期控制"},{"diseaseId":"thy_storm","dx":"已知或疑诊甲亢基础上出现高热 >38.5 ℃、心动过速 >130 次/min、房颤、心衰、胃肠道-肝脏症状、意识障碍，Burch-Wartofsky 评分 ≥45","key":"甲亢的危重表现形式，病死率高，需 ICU 级别综合治疗，禁用单纯 ATD 处理"},{"diseaseId":"thy_hypo","dx":"TSH 升高、FT4 降低（亚临床：TSH 升高而 FT4 正常）；乏力、怕冷、便秘、体重增加、皮肤干燥、心动过缓","key":"甲状腺激素缺乏，方向与甲亢相反，治疗为补充而非抑制"}],"diseases":[{"id":"thy_hypER","name":"甲状腺功能亢进症（Graves 病）","aka":["甲亢","Graves 病","毒性弥漫性甲状腺肿","GD","Hyperthyroidism"],"rank":1,"basic":{"define":"由甲状腺合成和分泌过多甲状腺激素引起的高代谢综合征；Graves 病约占甲亢病因的 80%，为 TSH 受体抗体（TRAb）介导的自身免疫病，特征是弥漫性甲状腺肿、浸润性突眼与胫前黏液性水肿。","risk":["女性（男女比约 1:4–1:8），20–50 岁高发","自身免疫病家族史（Graves 病、桥本甲状腺炎、1 型糖尿病）","精神应激、创伤、感染","碘摄入过量（含碘造影剂、胺碘酮）","妊娠与产后（产后甲状腺炎/复发）；吸烟（加重突眼）"],"epi":"我国临床甲亢患病率约 0.78%–1.0%，亚临床甲亢约 2.6%；女性显著高于男性。Graves 病占全部甲亢病因约 80%，是青年女性甲亢最常见的原因。"},"patho":"TRAb 为刺激性抗体，与 TSH 受体结合后激活 Gs 蛋白-腺苷酸环化酶通路，持续刺激甲状腺激素合成与分泌、甲状腺细胞增生。甲状腺激素升高使基础代谢率增加、产热增多，并增强儿茶酚胺敏感性，出现心悸、震颤、多汗、体重下降。TRAb 亦作用于眼眶成纤维细胞与胫前皮肤，引起糖胺聚糖沉积与脂肪增生（突眼、黏液性水肿）。","dx":{"criteria":["临床甲亢：TSH <0.1 mIU/L（或低于参考下限）伴 FT4 和/或 FT3 升高","亚临床甲亢：TSH 低于参考下限而 FT4、FT3 正常（按 TSH 0.1–0.4 与 <0.1 区分轻重）","Graves 病确诊：TRAb 阳性（敏感性 90% 以上），或甲状腺摄碘率增高伴弥漫性摄取（>50%–60%），或甲状腺血流丰富；约 5% 患者 TRAb 阴性，但临床 + 摄碘率 + 超声支持","典型体征：弥漫性肿大、可闻及血管杂音与触及震颤；浸润性突眼（多为双侧，可单侧）；胫前黏液性水肿；甲亢性周期性麻痹（亚洲男性多见，伴低钾）","甲状腺超声：弥漫性肿大、血流丰富（「火海征」）；甲状腺伴硬结节需排除毒性结节性甲状腺肿（摄碘率见热结节）","除外甲状腺炎（亚急性、无痛性、产后）——此三者摄碘率降低；碘负荷致甲亢摄碘率亦低"],"workup":["甲状腺功能：TSH、FT4、FT3（必要时 TT3）；TRAb 或 TPOAb/TgAb","甲状腺超声 + 彩色多普勒；甲状腺 131I 或 99mTc 摄碘率与显像（鉴别病因，Graves 增高、甲状腺炎减低、结节为热结节）","心电图（房颤、窦性心动过速）；心脏超声（心衰、心脏扩大）","血常规（WBC 及中性粒细胞基线，用于 ATD 前后比较）、肝功能（ALT/AST、胆红素）、碱性磷酸酶","血钙、24 h 尿钙（甲亢性骨质疏松）、脊柱/髋部骨密度（绝经后及老年）","眼眶 CT/MRI（突眼、视神经受压评估）、眼压、视力与色觉","育龄女性妊娠试验与生育计划（影响治疗选择）"],"grading":"①按甲状腺功能：临床甲亢（TSH 低 + FT4/FT3 高）/ 亚临床甲亢（TSH 低 + FT4/FT3 正常）。②按病因：Graves 病 / 毒性多结节性甲状腺肿 / 毒性腺瘤 / 碘甲亢 / 甲状腺炎。③甲状腺相关眼病（EUGOGO）：轻度、中重度、威胁视力（视神经病变）。④ATD 治疗期间按 FT3/FT4 正常化程度调量。"},"ddx":[{"name":"甲状腺危象（thy_storm）","point":"与本类 thy_storm 的鉴别点：普通甲亢为稳定高代谢状态，可门诊管理；甲状腺危象为高热、心动过速 >130、意识障碍与多系统失代偿的危重状态（Burch-Wartofsky 评分 ≥45），需 ICU 综合抢救，治疗强度与药物组合完全不同。"},{"name":"甲状腺功能减退（thy_hypo）","point":"与本类 thy_hypo 的鉴别点：甲亢表现为怕热、多汗、心悸、体重下降、TSH 降低；甲减为怕冷、乏力、便秘、体重增加、TSH 升高、FT4 降低。妊娠期及治疗后需注意两者互相转化。"},{"name":"亚急性甲状腺炎 / 无痛性甲状腺炎 / 产后甲状腺炎","point":"甲亢相 FT4 升高但甲状腺摄碘率降低（分离现象），亚急性伴颈前痛、ESR 显著升高；无痛性与产后甲状腺炎多为自限性，一过性甲亢期禁用 ATD，以 β 阻滞剂对症为主。"},{"name":"外源性甲状腺激素摄入","point":"TSH 低、FT4 高而甲状腺不大、摄碘率低、甲状腺球蛋白（Tg）低；多有减肥药或误服史，停用后可恢复。"},{"name":"焦虑症 / 嗜铬细胞瘤","point":"心动过速、震颤、出汗，但甲状腺功能正常；嗜铬细胞瘤为阵发性高血压伴头痛、心悸、大汗三联征，血 / 尿甲氧基肾上腺素升高。"},{"name":"房颤、慢性腹泻、体重下降的其他原因","point":"老年甲亢以「淡漠型」房颤、消瘦、纳差就诊，易漏诊；甲状腺功能正常时需查胃肠镜与肿瘤筛查。"}],"tx":{"drug":[{"name":"甲巯咪唑（MMI）","dose":"起始 10–30 mg qd 口服：轻中度甲亢 10–15 mg/d，重度（FT4 显著升高、甲状腺肿大明显）30–40 mg/d；4–6 周后复查 FT4/FT3 正常时减至 5–10 mg/d，维持 12–18 个月；国内常用维持 2.5–10 mg/d","note":"国内及多数指南首选（妊娠前 3 个月除外）。起效需 2–4 周，初期可配合 β 阻滞剂。出现发热、咽痛须立即查血常规；肝酶轻中度升高（<3 倍）可观察，>3 倍或伴黄疸需停药。妊娠前 3 个月及哺乳期慎用（哺乳可用低剂量 10–20 mg/d 分次）。","renal":"轻中度肾功能不全无需调整；重度（eGFR <30）减量并监测","hepatic":"活动性肝病、重度肝损伤禁用；用药期间监测 ALT/AST 与胆红素","interact":"与华法林合用可改变 INR（甲亢恢复使华法林需要量降低）；β 阻滞剂共存；碘造影剂降低疗效；与地高辛合并需监测血药浓度"},{"name":"丙硫氧嘧啶（PTU）","dose":"起始 300–450 mg/d 分 2–3 次（严重者 600 mg/d）；FT4/FT3 恢复后减至 100–300 mg/d 维持，按甲状腺功能滴定","note":"适应证：妊娠前 3 个月、甲状腺危象、甲巯咪唑不耐受/过敏者。因可致暴发性肝坏死，儿童与成人均避免长期使用；重症肝病禁用。与 MMI 不可互换（换算比约 10:1）且不宜随意互相替代。","renal":"eGFR <50 减量；透析无补充剂量（仅用于危象时按病情滴定）","hepatic":"任何活动性肝病禁用；用药前后监测肝功能，出现黄疸或 ALT >3 倍即刻停药","interact":"增加华法林抗凝作用（需减量并监测 INR）；可降低 β 阻滞剂清除；与甲状腺激素替代联用无叠加安全性数据"},{"name":"普萘洛尔","dose":"10–20 mg tid–qid 口服，按心率调整（目标静息心率 <90 次/min，心率过快可增至 40 mg tid，最大 80–120 mg/d）","note":"控制心动过速、震颤、焦虑、伴房颤者控制心室率（多需加地高辛）；β 阻滞剂并非禁忌于甲亢性心衰，但需评估并小剂量起始。哮喘、重度心衰、房室阻滞者慎用/禁用，可改用阿替洛尔或美托洛尔。","renal":"无需调整","hepatic":"重度肝损伤慎用（半衰期延长）","interact":"与维拉帕米/地尔硫卓联用可致低血压与心动过缓；与胰岛素/口服降糖药合用掩盖低血糖症状；与利血平、可乐定协同降压"},{"name":"碘剂（复方碘溶液 / 卢戈液 / 碘化钾）","dose":"仅用于危象或术前准备：PTU 给药 1 h 后开始，复方碘溶液 5–10 滴（约 0.25–0.5 mL）q8h，或碘化钾饱和液按说明书；连用不超过 7–14 天","note":"大剂量碘通过抑制碘活化与激素释放（Wolff-Chaikoff 效应）迅速起效，但数日后可逸脱；碘剂必须滞后于 PTU 1 h，否则先成为激素合成底物。对碘过敏、孕妇禁用。","renal":"肾功能不全者慎用（碘蓄积）","hepatic":"无特殊调整","interact":"与锂剂合用可致甲状腺功能异常；碘造影剂叠加致甲亢加重"},{"name":"地高辛（合并房颤）","dose":"0.125–0.25 mg qd 口服，目标心率 60–100 次/min；甲亢恢复后减量（甲亢需要更高剂量）","note":"甲亢房颤常需 β 阻滞剂 + 地高辛联合控制心率；甲亢使地高辛分布容积增大，需较高剂量，甲亢纠正后应下调以避免中毒。","renal":"按 eGFR 减少剂量（eGFR 30–60 用常规量的一半；<30 每 2–3 天一次）","hepatic":"无需调整","interact":"与胺碘酮、维拉帕米、克拉霉素合用显著升高血药浓度，需减量 50% 并监测"}],"nonDrug":["放射性碘（131I）：成人 Graves 病、ATD 不耐受或复发者首选之一；禁忌于妊娠、哺乳、中重度活动性眼病（否则加重突眼）、计划 6 个月内妊娠者","甲状腺次全切除术：甲状腺巨大伴压迫、疑癌、131I 或 ATD 失败者；术前须用 ATD + β 阻滞剂 + 碘剂控制到甲功正常","β 阻滞剂对症；房颤者在甲亢控制后 4–6 周仍有房颤者考虑电复律/抗凝","突眼：吸烟者戒烟，眼睑闭合不全者用人工泪液/眼罩，活动性中重度眼病用 IV 甲泼尼龙冲击或生物制剂（替普妥尤单抗），威胁视力者行眼眶减压"],"life":["低碘饮食：避免海带紫菜、含碘造影剂、胺碘酮、碘含片；使用无碘盐按当地情况","戒烟（明确的突眼进展危险因素）","ATD 治疗初期每周查血常规与肝功能 1–2 次，之后每 2–4 周查甲功，稳定后每 1–3 个月","识别粒细胞缺乏与肝损伤预警：发热、咽痛、口腔溃疡、黄疸、深色尿须立即停药并查血常规肝功能","突眼者外出戴墨镜、抬高床头、控制盐摄入减轻眶周水肿","甲亢控制后可致骨质疏松，绝经后女性补钙与维生素 D","若妊娠：孕前 3 个月用 PTU，4–6 个月后多数转 MMI，每 2–4 周监测甲功（保持 FT4 于参考上限附近）"]},"prog":"ATD 疗程 12–18 个月，停药后约 40%–50% 可长期缓解，复发多在停药 1 年内，TRAb 持续阳性、甲状腺明显肿大、年轻与吸烟者复发率高。放射性碘治疗有效率高，但甲减发生率高（10 年后 50%–80% 需终身替代）。Graves 眼病约 3%–5% 为中重度。ATD 药物性粒细胞缺乏发生率约 0.2%–0.5%，多在用药首 2–3 个月内发生。","refs":["中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022，中华医学会内分泌学分会）","成人甲状腺功能减退症诊治指南（2017，中华医学会内分泌学分会）","甲状腺功能亢进症诊治指南（2022）","ATA 2016 Guideline for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis","EUGOGO 2021 欧洲甲状腺相关眼病共识"]},{"id":"thy_storm","name":"甲状腺危象","aka":["甲亢危象","Thyroid Storm","甲状腺风暴"],"rank":2,"basic":{"define":"甲状腺毒症的极度失代偿状态，表现为高热、显著心动过速（常伴房颤）、中枢神经系统与胃肠-肝脏系统功能障碍，多系统失代偿，未经治疗病死率极高。","risk":["未治疗或控制不佳的 Graves 病（最常见基础）","感染（肺炎最常见）","外科手术（尤其非甲状腺手术）与急性创伤、创伤","放射性碘治疗后短时间内激素释放增多","停用抗甲状腺药物、碘造影剂","妊娠分娩（围产期）、心肌梗死、脑卒中、糖尿病酮症酸中毒、肺栓塞"],"epi":"较罕见，占住院甲亢患者不足 2%，但病死率可达 20%–30%（历史报道 60% 以上，现代 ICU 支持下达 10%–20%，老年患者更高）。多见于 30–50 岁女性，未规范治疗的 Graves 病患者为高危人群。"},"patho":"在甲状腺激素水平急剧升高基础上，机体处于高水平应激状态，交感神经-儿茶酚胺敏感性剧增，组织对甲状腺激素的耐受性下降。甲状腺激素直接增加心肌β 受体密度与腺苷酸环化酶活性，导致心率增快、心输出量与心肌耗氧显著增加，可诱发房颤、心肌缺血与心衰。产热增加与体温调节中枢失代偿造成高热与脱水；肝脏葡萄糖与蛋白分解加速、肝细胞损伤，可致黄疸与肝衰竭；中枢神经系统出现震颤、谵妄、昏迷；胃肠道蠕动增强出现腹泻与呕吐。","dx":{"criteria":["甲状腺毒症证据：TSH 降低、FT4/FT3 升高（已确诊甲亢或新发）","高热：体温常 >38.5–39 ℃（多数 >38.5 ℃）","心血管系统：心动过速 >130 次/min，或房颤伴心室率 >130，或心衰","中枢神经系统：烦躁、谵妄、精神症状、癫痫、昏迷（须排除其他原因）","胃肠-肝脏系统：恶心、呕吐、腹泻、腹痛（可有肝大、黄疸、ALT/AST 显著升高）","Burch-Wartofsky 评分：体温、心率、神经系统、胃肠-肝、房颤、诱因各自赋分，≥45 分高度提示甲状腺危象；25–44 可疑，<25 不支持","无法完全排除时按「高度可疑」处理，不因等结果延误治疗；典型病例并非必须等甲状腺功能结果"],"workup":["立即：心电图、血糖、电解质（K/Na/Ca）、肾功能、肝功能、胆红素、血常规","甲状腺功能 TSH/FT4/FT3（转 ICU 前抽血，不必等结果）、T3（必要时）","感染筛查：血 / 尿 / 痰培养、CRP/PCT、胸片","心肌酶与心电图（缺血、心律失常）、心超评估心功能","凝血功能、D-二聚体（DIC/血栓风险）","寻找诱因：因停用 ATD、碘暴露、手术或近期 131I 治疗史；妊娠试验","血气分析与乳酸；意识障碍者头颅影像"],"grading":"Burch-Wartofsky 评分（BWPS）：<25 甲状腺危象可能性小；25–44 可疑；≥45 高度提示。评分项：体温（37.2–37.7 ℃ 5 分、37.8–38.2 ℃ 10 分、38.3–38.8 ℃ 15 分、38.9–39.3 ℃ 20 分、39.4–39.9 ℃ 25 分、≥40 ℃ 30 分）；心动过速（99–109 次/min 5 分至 ≥140 次/min 25 分；房颤 10 分）；中枢神经系统（轻 10 分、中度 20 分、重度 30 分）；胃肠-肝（中 10 分、重 20 分）；诱因（有 10 分）。"},"ddx":[{"name":"甲状腺功能亢进症（thy_hypER）","point":"与本类 thy_hypER 的鉴别点：普通甲亢虽可有心动过速与多汗，但无高热、无意识改变与多器官失代偿，Burch-Wartofsky 评分 <25；危象是甲亢的极端形式，须以 BWPS ≥45、多系统受累判断，任何鉴别不清的高热甲亢均应按危象处理。"},{"name":"甲状腺功能减退（thy_hypo）","point":"与本类 thy_hypo 的鉴别点：甲减可伴低体温、心动过缓、意识障碍（黏液性水肿昏迷），表现与甲亢危象相反；若患者在甲减基础上出现低体温昏迷、低钠与呼吸抑制，应考虑黏液性水肿昏迷。"},{"name":"脓毒症 / 脓毒性休克","point":"高热、心动过速、意识改变，但为感染所致，血培养阳性、PCT 高；两者可并存（感染为甲亢危象最常见诱因），应同时抗感染与抗甲状腺治疗。"},{"name":"恶性高热（麻醉相关）","point":"全麻中使用氟烷/琥珀胆碱后骤发高热、肌肉强直、CK 显著升高、高碳酸血症与高钾；有遗传倾向，治疗为丹曲林，与甲状腺无关。"},{"name":"抗精神病药恶性综合征（NMS）","point":"使用抗精神病药后高热、肌强直、意识改变、自主神经不稳定与 CK 升高，与甲亢危象的区别在于用药史与肌肉强直，治疗为停用抗精神病药、溴隐亭或丹曲林。"},{"name":"嗜铬细胞瘤危象 / 中枢神经系统感染","point":"阵发性高血压、头痛、大汗，血 / 尿甲氧基肾上腺素升高；脑膜炎 / 脑炎 CSF 异常、颈部抵抗。两者均可有高热与意识改变，须查甲状腺功能与影像鉴别。"}],"tx":{"drug":[{"name":"丙硫氧嘧啶（PTU，首选）","dose":"负荷 600 mg 口服或经鼻胃管（不能口服者研碎后管饲）；随后 200 mg q4–6h（即约 800–1200 mg/d），直至危象缓解（一般 3–7 天）后逐渐减量","note":"危象时首选 PTU：除阻断激素合成外，大剂量还可抑制外周 T4 向 T3 转化。给药后 1 h 方可给碘剂。若已用 PTU 且每日 >800 mg，可改为维持剂量。肝功能严重受损者改用甲巯咪唑（但失去抑制外周转化作用）。","renal":"eGFR <50 减量 25%–50%，仍可维持较高剂量至危象缓解","hepatic":"暴发性肝损伤禁用（改用甲巯咪唑）；用药前查肝功能，出现黄疸需评估停药","interact":"增强华法林抗凝作用；与碘剂必须错开 1 h；β 阻滞剂合用注意低血压与心动过缓"},{"name":"甲巯咪唑（替代）","dose":"20 mg q4–6h（约 80–120 mg/d）口服或管饲，危象缓解后减量","note":"仅在 PTU 禁忌（肝损伤、过敏）时使用；起效较 PTU 慢（激素库耗竭需时间），且不抑制外周 T4→T3 转化，故危象时疗程需更长。","renal":"eGFR <30 减量","hepatic":"PTU 相关肝损伤时可换用","interact":"同甲巯咪唑常规：华法林、碘造影剂"},{"name":"碘剂（复方碘溶液 / 碘化钾）","dose":"PTU 给药至少 1 h 后开始：复方碘溶液 5–10 滴（0.25–0.5 mL）口服或管饲 q8h，或碘化钾饱和液按说明书；危象缓解后停用","note":"大剂量碘快速抑制激素释放（Wolff-Chaikoff 效应），起效迅速；但必须先阻断合成，否则碘将作为合成底物使病情恶化。碘剂连续使用 1–2 周后作用可逸脱。碘过敏、妊娠禁用。","renal":"肾功能不全者慎用","hepatic":"无特殊调整","interact":"与锂剂合用致甲状腺功能变化；含碘造影剂不应同用"},{"name":"普萘洛尔（β 阻滞剂）","dose":"30–40 mg q6h 口服或经胃管（常用 60–120 mg/d）；不能口服或病情极重者用艾司洛尔 250–500 μg/kg 负荷后 50–100 μg/kg/min 静脉泵入，或普萘洛尔 1 mg/min 缓慢静注（总量 ≤10 mg，按心律与血压滴定）","note":"高剂量普萘洛尔还可抑制外周 T4 转 T3。伴房颤或心衰者需监测；支气管痉挛者改用选择性 β1 阻滞剂。","renal":"静脉用药肾功能不全无需调整；口服高剂量注意清除减慢","hepatic":"重度肝损伤减量","interact":"与地高辛、维拉帕米、地尔硫合用可致心动过缓或低血压；与儿茶酚胺耗竭剂协同"},{"name":"氢化可的松（糖皮质激素）","dose":"100 mg 静脉 q8h（或 100 mg 负荷后 50–100 mg q6–8h），直至危象缓解后逐步减停（一般 3–5 天）","note":"抑制外周 T4→T3 转化并预防相对肾上腺皮质功能不全（甲亢状态下皮质醇清除加速）。地塞米松 2 mg q6h 亦可替代。合并糖尿病者需加强血糖监测。","renal":"无需调整","hepatic":"重度肝损伤需监测血钠与水钠潴留","interact":"与胰岛素/口服降糖药拮抗；与 NSAIDs 合用增加消化道出血；与利福平/苯妥英加速代谢"},{"name":"对乙酰氨基酚（退热）","dose":"500–1000 mg 口服或栓剂，每 4–6 h 按需，24 h 总量 ≤2000 mg（危象伴肝损伤者 ≤1500 mg且需评估）","note":"高热时优先物理降温（冰毯、冰袋）与对乙酰氨基酚；阿司匹林可置换 T3 与 TBG 结合、升高游离激素，应避免使用。","renal":"eGFR <30 减量或延长间隔","hepatic":"肝损伤者慎用并限制剂量","interact":"饮酒与异烟肼/利福平增加肝毒性"}],"nonDrug":["ICU 监护：心电、血压、血氧、体温与意识监护；建立静脉通路","积极病因治疗与诱因处理（抗感染、停用碘剂或可能诱发药物、必要时手术）","补液与电解质纠正（高热与呕吐腹泻丢失大量液体，补葡萄糖、电解质）","营养支持：高热量、高蛋白、足量维生素；呕吐者鼻胃管或肠外营养","不推荐在危象急性期行甲状腺切除术（除非药物治疗无效且危及生命，需先控制）","房颤者控制心率与评估抗凝；出现心衰按心衰指南治疗；必要时血液净化清除激素（个案报告）"],"life":["危象缓解后转为常规甲亢长期管理（ATD 或 131I/手术）","明确并记录诱因，避免再次暴露","宣教：不自行停用抗甲状腺药物、出现发热或感染时及时就医","围手术期与非甲状腺手术前应先将甲状腺功能控制至正常","出院随访：每 1–2 周复查甲功，直至稳定"]},"prog":"尽管现代 ICU 支持，甲状腺危象病死率仍达 10%–20%（老年、合并心衰、休克、肝衰竭与未及时治疗者更高）。治疗关键在于早期识别（BWPS ≥45 即启动）与多药联合（PTU → 1 h 后碘剂 + 糖皮质激素 + β 阻滞剂 + 支持治疗），延误给药 12–24 h 即显著增加死亡风险。治疗后 24–48 h 内体温与心率应明显下降，否则需重新评估诱因。","refs":["中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022）","中华医学会内分泌学分会：甲状腺危象诊疗专家共识","ATA 2016 Guideline for Diagnosis and Management of Hyperthyroidism（Thyroid Storm 部分）","Burch HB, Wartofsky L. Life-threatening thyrotoxicosis. Thyroid storm. Endocrinol Metab Clin North Am 1993","UpToDate：Thyroid storm 管理（最新综述）"]},{"id":"thy_hypo","name":"甲状腺功能减退症","aka":["甲减","Hypothyroidism","桥本甲状腺炎","Hashimoto","黏液性水肿"],"rank":3,"basic":{"define":"甲状腺激素合成或分泌不足（原发性）或下丘脑-垂体病变（中枢性）导致的全身代谢减低综合征；成人最常见病因为桥本甲状腺炎，表现为 TSH 升高伴 FT4 降低（亚临床为 FT4 正常）。","risk":["女性（男女比约 5–10:1），30–60 岁高发","甲状腺自身抗体（TPOAb、TgAb）阳性，桥本甲状腺炎家族史","甲状腺手术、131I 治疗、颈部放疗","碘摄入过多或过少、胺碘酮、锂剂、干扰素、酪氨酸激酶抑制剂","垂体/下丘脑疾病（中枢性甲减）；妊娠期（需增加剂量）"],"epi":"我国成人临床甲减患病率约 1.0%–1.1%，亚临床甲减约 12%–17%，女性及老年人更高；甲状腺过氧化物酶抗体阳性率约 10%。"},"patho":"甲状腺激素（T4/T3）缺乏导致基础代谢率下降、产热减少，组织对儿茶酚胺反应减弱。原发性甲减时甲状腺自身抗体介导的淋巴细胞浸润与滤泡破坏，腺体萎缩伴纤维化；因甲状腺激素对垂体 TSH 的负反馈减弱，TSH 代偿性升高，是原发性甲减最敏感指标。组织水平表现为黏多糖（透明质酸）在皮肤、心肌、脑内沉积，形成黏液性水肿；心肌收缩力减弱、心率减慢、外周阻力增加；肠道蠕动减慢、胃肠排空延迟；骨髓造血功能减低，可致正细胞性贫血（合并缺铁或 B12 缺乏时加重）。","dx":{"criteria":["原发性临床甲减：TSH 升高（>参考上限，常 >4.2 mIU/L）伴 FT4 降低","原发性亚临床甲减：TSH 升高而 FT4 正常；TSH >10 mIU/L 推荐治疗，4.2–10 mIU/L 结合症状、抗体与心血管风险评估决定","中枢性甲减：FT4 降低而 TSH 正常或降低（TSH 无生物活性），需排查垂体瘤、席汉综合征、垂体手术/放疗","典型表现：乏力、怕冷、体重增加、便秘、嗜睡、记忆减退、皮肤干燥、声音嘶哑、面部眶周非凹陷性水肿、眉毛外侧稀疏；心率慢（<60 次/min）、心动过缓、心包积液","实验室支持：TPOAb/TgAb 阳性（桥本）、高血脂（TC 与 LDL-C 升高）、CK 升高、低钠血症、正细胞性贫血；心电图低电压、QT 延长","妊娠期甲减：TSH >4.0 mIU/L（早孕期）或 >4.2 mIU/L（中晚期）伴 TPOAb 阳性者需治疗；TPOAb 阴性者按当地参考区间","黏液性水肿昏迷：重度甲减 + 低体温 <35.5 ℃、意识障碍、低血压、心动过缓、低钠、低通气，病死率高达 30%–60%"],"workup":["TSH、FT4（必要时 FT3）、TPOAb、TgAb；中枢性甲减需查其他垂体激素轴（ACTH/皮质醇、LH/FSH、PRL、GH/IGF-1）与垂体 MRI","血脂、CK、肝功能、电解质（尤其血钠）、血常规","心电图与超声心动图（心包积液、心功能）；必要时 Holter","颈部超声（甲状腺萎缩、回声不均、结节）","妊娠期与育龄女性：妊娠前及孕早期查 TSH（孕早期目标 TSH <2.5 mIU/L，孕中晚期 <3.0 mIU/L）","老年人：评估是否合并冠心病（初治时替代剂量需谨慎）"],"grading":"按 TSH 与 FT4 分类：①临床甲减：TSH 升高 + FT4 降低；②亚临床甲减：TSH 升高 + FT4 正常（分轻度 4.2–10 mIU/L、重度 >10 mIU/L）；③中枢性甲减；④黏液性水肿昏迷。按严重程度与受累系统评估（血脂异常、心包积液、精神症状、贫血）。"},"ddx":[{"name":"甲状腺功能亢进症（thy_hypER）","point":"与本类 thy_hypER 的鉴别点：甲减为怕冷、体重增加、心动过缓、TSH 升高、FT4 降低；甲亢相反为怕热、体重下降、心动过速、TSH 降低。需注意 ATD 过量可致药物性甲减，调整剂量前必须明确。"},{"name":"甲状腺危象（thy_storm）","point":"与本类 thy_storm 的鉴别点：危象为高热、心动过速、意识改变与多器官失代偿（TSH 低、FT4 高）；甲减严重失代偿为低体温、心动过缓、低钠与低通气（黏液性水肿昏迷），两者临床方向完全相反，但都可致昏迷。"},{"name":"抑郁障碍 / 认知障碍（痴呆）","point":"甲减的乏力、嗜睡、记忆减退、情绪低落与抑郁高度重叠；所有新发抑郁、痴呆样表现者均应查 TSH，甲减纠正后部分认知改善。"},{"name":"CKD 导致的乏力与低钠","point":"肾功能不全可致乏力、水肿、低钠，但 TSH 正常；低钠伴高 CK 与高 TSH 更支持甲减。"},{"name":"肾病综合征 / 心衰所致水肿","point":"下肢水肿多为凹陷性，伴大量蛋白尿或心衰体征；甲减为黏液性水肿（非凹陷性）、眶周水肿、伴声音嘶哑与心动过缓，NT-proBNP 一般不高。"},{"name":"贫血（缺铁/巨幼）","point":"甲减贫血常为正细胞性；查铁代谢、B12、叶酸。桥本甲减可合并自身免疫性胃炎（B12 缺乏），需一并考虑。"}],"tx":{"drug":[{"name":"左甲状腺素钠（L-T4）","dose":"成人完全替代量按体重 1.6–1.8 μg/kg/d 晨起空腹（餐前 30–60 min）顿服；起始 25–50 μg/d，每 4–6 周增加 25 μg 直至 TSH 达标；老年人、冠心病或心衰者起始 12.5–25 μg/d，每 4–8 周递增 12.5 μg","note":"以 TSH 为调量指标（原发性甲减），目标 TSH 0.5–4.2 mIU/L（老年人与冠心病者可放宽至 4.0–6.0）；用药 6–8 周后复查 TSH。漏服应补服且避免次日加倍。亚临床甲减按 TSH 与抗体决定。","renal":"无需调整；重度肾功能不全者替代后可能纠正贫血与低钠，注意容量变化","hepatic":"重度肝病时可影响结合蛋白与代谢，需按 TSH 调整","interact":"与钙剂、铁剂、铝碳酸镁、质子泵抑制剂、考来烯胺同服显著降低吸收，须间隔 4 h 以上；华法林合用时需上调 L-T4 会增强抗凝效应；雌激素/妊娠增加需求；利福平、苯妥英加速代谢"},{"name":"左甲状腺素钠（妊娠期）","dose":"妊娠期需要量增加约 20%–30%，确诊妊娠后立即增加 20%–30%（每晨加 1–2 片 25 μg）或在孕 4–6 周内查 TSH 后调整；每 4 周复查 TSH（孕早期目标 <2.5 mIU/L）","note":"妊娠期甲状腺激素需求随 hCG 与 TBG 升高而增加；产后恢复至孕前剂量并 6 周复查。","renal":"无需调整","hepatic":"无需调整","interact":"同上；妊娠期口服铁、钙剂常见，须间隔服用"},{"name":"碘塞罗宁（L-T3，慎用）","dose":"仅用于黏液性水肿昏迷或需快速替代者：遵医嘱小剂量（如 5–10 μg 静脉/口服 q8h，按病情滴定）","note":"L-T3 起效快但易致心律失常与缺血事件，常规甲减不推荐；与 L-T4 联合替代对部分患者无效且增加风险。","renal":"无需调整","hepatic":"重度肝病慎用","interact":"增加华法林抗凝效应；与拟交感胺合用致心律失常"},{"name":"氢化可的松（合并肾上腺功能不全时）","dose":"黏液性水肿昏迷或怀疑合并肾上腺皮质功能不全时，先用氢化可的松 100 mg 静脉后 50 mg q6h，再启动甲状腺激素替代","note":"未处理的肾上腺皮质功能不全（席汉综合征、Addison 病）在用 L-T4 前必须先补糖皮质激素，否则诱发肾上腺危象。中枢性甲减必须首先排除并处理垂体-肾上腺轴缺陷。","renal":"无需调整","hepatic":"重度肝病注意水钠潴留","interact":"与胰岛素/降糖药拮抗；与利福平/苯妥英加速代谢"}],"nonDrug":["黏液性水肿昏迷：ICU 监护，机械通气支持、复温（避免快速复温）、静脉 L-T4 + 糖皮质激素、纠正低钠与低血糖、治疗诱因","黏液性水肿伴心包积液：大量积液致心包填塞者行心包穿刺引流，同时替代治疗","甲状腺结节/肿大压迫（桥本木样甲状腺肿）：必要时手术","定期监测：TSH 每 6–8 周至达标后每 6–12 个月；妊娠期每 4 周","血脂异常者甲减纠正后复查（部分可能无需降脂药）"],"life":["固定时间服药（晨起空腹），与早餐间隔至少 30–60 min；与其他药物间隔 4 h","不同品牌 L-T4 生物等效应不同，尽量固定品牌；换品牌后 6 周复查 TSH","低碘但不严格限碘；桥本甲状腺炎避免长期高碘（海带、含碘制剂）","监测体重、心率与症状变化；老年人注意心绞痛、心悸等过量表现","体重显著变化（±10%）、妊娠、添加新药或减重手术后需复查 TSH","避免含铁 / 钙 / 镁的复合维生素与 L-T4 同服"]},"prog":"规范替代治疗后预后良好，症状多在数周至数月内改善。桥本甲状腺炎者每年约 2%–4% 进展为临床甲减（TPOAb 阳性者更快）。未经治疗者心血管风险增加，血脂与动脉硬化加速；亚临床甲减（TSH >10）治疗可降低心衰与心血管事件风险。治疗不足使妊娠并发症（流产、早产、子代神经发育受限）风险升高。","refs":["成人甲状腺功能减退症诊治指南（2017，中华医学会内分泌学分会）","妊娠和产后甲状腺疾病诊治指南（第 2 版，2019）","甲状腺功能减退症基层诊疗指南（2019）","ATA 2014 Guidelines for the Treatment of Hypothyroidism","ETA 2021 Guidelines on the use of L-T4 in hypothyroidism"]}]},{"id":"adrenal","name":"肾上腺与垂体","rank":3,"summary":"肾上腺疾病的诊断遵循「定性—定位」两步：先以激素及功能试验确认激素分泌状态（醛固酮/肾素比、皮质醇节律与抑制试验、甲氧基肾上腺素），再以 CT/MRI 或肾上腺静脉采血定位。所有拟行肾上腺手术者须术前纠正醛固酮增多、皮质醇增多或儿茶酚胺释放风险。","compare":[{"diseaseId":"ad_pa","dx":"高血压 + 低血钾（约 1/3 患者血钾正常）；醛固酮/肾素比值（ARR）升高且醛固酮不被盐水负荷抑制，再经肾上腺 CT 与肾上腺静脉采血（AVS）分型","key":"醛固酮自主分泌伴肾素受抑，核心实验室特征是 ARR 升高 + 醛固酮抑制试验阳性"},{"diseaseId":"ad_cushing","dx":"向心性肥胖、满月脸、水牛背、紫纹、皮肤变薄、肌无力、高血压与糖代谢异常；1 mg 地塞米松抑制试验不抑制 + 24 h 尿游离皮质醇或午夜唾液皮质醇升高","key":"皮质醇增多且昼夜节律消失、不被地塞米松抑制；确诊后需 ACTH 区分 ACTH 依赖性（垂体/异位）与不依赖性（肾上腺）"},{"diseaseId":"ad_pheo","dx":"阵发性头痛、心悸、大汗「三联征」伴阵发性或持续性高血压；血浆游离甲氧基肾上腺素或 24 h 尿分馏甲氧基肾上腺素升高，影像见肾上腺肿物","key":"儿茶酚胺过量释放导致的交感兴奋与高血压危象，术前必须充分 α 阻断"}],"diseases":[{"id":"ad_pa","name":"原发性醛固酮增多症","aka":["原醛","PA","Conn 综合征","Primary Aldosteronism"],"rank":1,"basic":{"define":"肾上腺皮质自主分泌过量醛固酮、伴肾素-血管紧张素系统受抑的疾病，是继发性高血压最常见的内分泌原因，典型表现为高血压伴或不伴低血钾。","risk":["难治性高血压（≥3 种降压药仍不达标）","高血压伴自发性或利尿剂诱发的低血钾","高血压伴肾上腺意外瘤","早发高血压（<40 岁）或脑血管意外家族史（<40 岁）","高血压患者一级亲属患原醛","阻塞性睡眠呼吸暂停、房颤与高血压并存者"],"epi":"在高血压人群中原醛患病率约 5%–10%，难治性高血压中可达 17%–20%；我国高血压患者约 2.45 亿，估算原醛患者数千万，但确诊率不足 1%。双侧肾上腺增生约占 60%，单侧腺瘤约 30%–40%。"},"patho":"肾上腺球状带细胞自主分泌醛固酮，与盐皮质激素受体结合后促进远端肾小管钠重吸收与钾、氢排泄，导致水钠潴留、血容量扩张与肾素受抑；同时醛固酮直接作用于心肌、血管与肾脏，引起心肌纤维化、血管僵硬与肾损伤。过度钾排泄造成低钾性碱中毒、肌无力、心律失常与糖耐量异常。单侧者多为腺瘤（CYP11B2 突变或 KCNJ5 突变），双侧者多为特发性增生。","dx":{"criteria":["筛查对象：难治性高血压、高血压伴低血钾（自发性或利尿剂诱发）、高血压伴肾上腺结节、早发高血压或家族史者","筛查试验：血浆醛固酮浓度（PAC）与血浆肾素活性（PRA）比值 ARR；多数中心以 ARR >20–30（PAC 单位 ng/dL、PRA ng/mL/h）为切点，同时 PAC 需 >10–15 ng/dL（卧位）或 >15 ng/dL（立位）；以直接肾素浓度（DRC）替代时切点相应调整","筛查前准备：停用螺内酯/依普利酮 4–6 周，停用 ACEI/ARB、利尿剂 2 周；血压需控制时可选用α 阻滞剂或非二氢吡啶类钙拮抗剂","确诊试验：生理盐水输注试验（2 L 生理盐水 4 h 静滴后 PAC 不被抑制，>10 ng/dL 确诊，<5 基本排除）；或卡托普利试验、氟氢可的松抑制试验","分型：肾上腺 CT（薄层）；确诊且拟手术者行肾上腺静脉采血（AVS）判断单侧/双侧，成功率与选择性指数 SI ≥2","基因检测：年轻（<20 岁）或家族性原醛者行肾上腺皮质增生症（FH）与 KCNJ5 等基因检测"],"workup":["血钾、血气（代谢性碱中毒）、血钠、血镁","PAC、PRA/DRC 与 ARR；血尿醛固酮（可参考）、24 h 尿钾（低钾者 >30 mmol/d 提示肾性失钾）","肾上腺 CT 薄层（2–3 mm）增强扫描；双侧巨大增生或疑癌者 MRI","AVS（肾上腺静脉采血）：拟手术患者的金标准分型；CT 不能替代","各项靶器官评估：心脏超声（LVH）、UACR 与 eGFR、睡眠监测、糖耐量","疑库欣或其他肾上腺意外瘤合并者，同步查皮质醇节律与甲氧基肾上腺素"],"grading":"①分型：单侧腺瘤（APA）/ 单侧增生 / 双侧特发性增生（IHA）/ 糖皮质激素可治性原醛（GRA，家族性）/ 肾上腺癌（罕见）。②按靶器官损害分层（LVH、CKD、房颤、卒中）。③典型实验室：低钾 + 代谢性碱中毒 + 高醛固酮 + 低肾素。"},"ddx":[{"name":"库欣综合征（ad_cushing）","point":"与本类 ad_cushing 的鉴别点：原醛以高血压 + 低钾 + 高醛固酮低肾素为特征，无满月脸、紫纹、向心性肥胖与皮质醇节律消失；库欣患者皮质醇抑制试验异常、ACTH/皮质醇升高。原醛患者可合并亚临床库欣（肾上腺意外瘤），需同时筛查。"},{"name":"嗜铬细胞瘤（ad_pheo）","point":"与本类 ad_pheo 的鉴别点：原醛为持续性或难治性高血压伴低钾、血醛固酮高；嗜铬细胞瘤为阵发性高血压伴头痛、心悸、大汗三联征，血/尿甲氧基肾上腺素升高，醛固酮正常。"},{"name":"肾血管性高血压 / 肾实质病变","point":"肾动脉狭窄者肾素明显升高（与低肾素形成对照）、双肾大小不一、肾功能下降；原醛肾素被抑制。肾实质病变者 eGFR 下降、蛋白尿与贫血。"},{"name":"Liddle 综合征（假性醛固酮增多症）","point":"高血压 + 低钾 + 代谢性碱中毒但醛固酮与肾素均低（ENaC 基因突变）；螺内酯无效而阿米洛利/氨苯蝶啶有效，家族史支持。"},{"name":"药物性高血压伴低钾","point":"利尿剂、甘草制剂（甘草酸抑制 11β-HSD2）、糖皮质激素、生胃酮可致高血压与低钾；详细用药史是鉴别关键，停药后复测。"},{"name":"甲状腺功能亢进 / 糖尿病相关高血压","point":"甲亢可致收缩压升高与低钾性周期性麻痹，但 TSH 低、FT4 高；甲亢貌与甲功可鉴别。"}],"tx":{"drug":[{"name":"螺内酯","dose":"12.5–25 mg qd 起始，可逐步增至 100–200 mg/d 分次；常用 25–50 mg qd，按血压与血钾滴定","note":"双侧增生及术前准备的一线盐皮质激素受体拮抗剂；2–4 周复查血钾与肌酐（前 2 周尤其需监测高钾）。男性乳房发育、月经紊乱常致依从性下降。","renal":"eGFR <30 禁用；eGFR 30–50 减量并密切监测血钾","hepatic":"重度肝损伤慎用（代谢减慢）","interact":"与 ACEI/ARB、保钾利尿剂、NSAIDs 合用显著增加高钾风险；与地高辛合用升高地高辛浓度；与 CYP3A4 抑制剂增加暴露"},{"name":"依普利酮","dose":"25 mg qd 起始，可增至 25–50 mg bid（或 50 mg qd）","note":"选择性更高，抗雄激素副作用少，适合男性与育龄女性；降压效价较螺内酯弱；国内可及性有限。","renal":"eGFR <30 不推荐；eGFR 30–50 起始 25 mg qod","hepatic":"中度肝损伤起始 25 mg qod，重度避免","interact":"与 CYP3A4 强抑制剂（克拉霉素、伊曲康唑）禁用；与保钾利尿剂/ACEI 合用加重高钾"},{"name":"氨氯地平 / 非二氢吡啶类 CCB（联合降压）","dose":"氨氯地平 5–10 mg qd；或维拉帕米缓释剂 120–240 mg qd（筛查期用作不影响 ARR 的降压药）","note":"原醛患者常需 2–3 种降压药联合；筛查准备期可用非二氢吡啶类 CCB + α 阻滞剂，避免使用 ACEI/ARB/利尿剂干扰 ARR。","renal":"无需调整（氨氯地平）；维拉帕米重度肾功能不全慎用","hepatic":"氨氯地平重度肝损伤起始 2.5 mg；维拉帕米重度肝损伤减量","interact":"维拉帕米抑制 CYP3A4，升高他克莫司、辛伐他汀浓度；与 β 阻滞剂合用致心动过缓"},{"name":"多沙唑嗪（筛查准备期降压）","dose":"1–2 mg qn 起始，可增至 4–8 mg qd","note":"α1 阻滞剂对 ARR 影响小，可在停药筛查窗口期控制血压；首剂注意体位性低血压（睡前服用）。","renal":"无需调整","hepatic":"轻度减量，重度肝损伤避免","interact":"与 PDE5 抑制剂、α 阻滞剂合用加重低血压；与 β 阻滞剂合用注意体位性低血压"},{"name":"氯化钾（纠正低钾）","dose":"口服氯化钾 1–3 g tid（按血钾目标 3.5–4.0 mmol/L 滴定），遵医嘱","note":"术前与药物治疗初期纠正低钾与碱中毒；注意与螺内酯联用导致高钾。","renal":"eGFR <30 慎用并减量","hepatic":"无特殊调整","interact":"与保钾利尿剂、ACEI/ARB 合用注意高钾"}],"nonDrug":["单侧病变：腹腔镜肾上腺切除术（血压治愈率约 35%–50%，改善率 >90%）；术前不常规用药，但需纠正低钾与代谢性碱中毒","双侧增生：终身盐皮质激素受体拮抗剂药物治疗；不推荐不符 AVS 的单侧切除","经导管肾上腺动脉化学消融（TAAE）：不适合或拒绝手术的单侧病变者的替代选择（国内已有共识）","筛查全家（家族性原醛者）一级亲属血压与 ARR","术后每 3–6 个月复查血钾、醛固酮/肾素与血压；仅部分患者需长期降压药"],"life":["低钠饮食（钠 <2 g/d）有助于减少容量与降压","规律监测家庭血压与血钾（尤其使用螺内酯期间）","正常饮水，避免过度限水或大量利尿型饮品","停药期间严格按医嘱中断干扰 ARR 的药物，避免自行服用中草药（甘草类）","术后随访：术后早期监测低醛固酮（乏力、低血压、高钾）并短期补盐/补激素"]},"prog":"原醛显著增加心血管事件、房颤、卒中与肾功能恶化风险，独立于血压水平。单侧腺瘤术后约 35%–50% 血压完全缓解、90% 以上改善；双侧增生患者药物治疗控制在目标血压后预后良好，但心力衰竭与房颤风险仍偏高。早期识别与针对性治疗可明显改善远期结局。","refs":["原发性醛固酮增多症诊断治疗的专家共识（2020 版，中华医学会内分泌学分会）","中国高血压防治指南（2024 年修订版，继发性高血压章节）","原发性醛固酮增多症经导管肾上腺动脉化学消融中国专家共识（2022）","Endocrine Society Clinical Practice Guideline: Primary Aldosteronism Management（2016）","2020 ESH Guideline for the Management of Hypertension"]},{"id":"ad_cushing","name":"库欣综合征","aka":["Cushing 综合征","皮质醇增多症","Hypercortisolism","库欣病"],"rank":2,"basic":{"define":"因多种原因造成肾上腺皮质分泌过量糖皮质激素（主要为皮质醇）所致的临床综合征；ACTH 依赖性以垂体微腺瘤（库欣病）最常见，ACTH 不依赖性以肾上腺腺瘤与增生为主。","risk":["女性（库欣病男女比约 1:3–8），20–40 岁高发","长期外源性糖皮质激素使用（最常见医源性）","垂体腺瘤（库欣病约占 70%）","肾上腺腺瘤或大结节性增生、肾上腺癌（约 15%–20%）","异位 ACTH 综合征（小细胞肺癌、胸腺瘤、胰腺神经内分泌肿瘤）","长期酒精滥用（假性库欣）、重度抑郁"],"epi":"内源性库欣综合征年发病率约 2–3/100 万；临床呈「冰山」现象，实际患病率在肥胖与糖尿病门诊中可达 1%–5%。库欣病约占内源性者 70%，女性多见；异位 ACTH 综合征占 10%–15%，多见于 40 岁以上男性。"},"patho":"持续高水平皮质醇与盐皮质激素受体交叉作用，导致水钠潴留与高血压；促进肝糖异生、拮抗胰岛素作用，引起糖耐量与糖尿病；促使蛋白质分解，皮肤变薄、紫纹、肌萎缩；脂肪重新分布至腹部与颈背部；抑制骨形成与性腺轴（骨质疏松、闭经）。ACTH 依赖性者因 ACTH 促黑素细胞作用可见色素沉着；异位 ACTH 者多伴低钾、碱中毒与皮肤色素加深。皮质醇还抑制免疫功能，增加感染风险。","dx":{"criteria":["筛查对象：向心性肥胖、满月脸、水牛背、宽大紫纹、皮肤变薄易瘀、近端肌无力、难治性高血压、新发糖尿病、低骨量年轻患者、月经紊乱伴多毛","一线筛查试验（任一阳性即需确认）：①1 mg 过夜地塞米松抑制试验，晨 8 时皮质醇 >1.8 μg/dL（50 nmol/L）为不抑制；②24 h 尿游离皮质醇（≥2 次）升高；③午夜唾液或血皮质醇升高、昼夜节律消失","确诊（第二步）：两项不同筛查试验异常方可确诊；女性用口服避孕药或妊娠者改用尿游离皮质醇或午夜唾液","定位（第三步）：测 ACTH —— ACTH 降低（<10 pg/mL）提示肾上腺来源；ACTH 正常或升高（>20 pg/mL）提示 ACTH 依赖性，需垂体 MRI + 大剂量地塞米松抑制试验（2 mg q6h×8 次，皮质醇抑制 >50% 支持库欣病）","异位 ACTH：CRH 刺激试验无反应、大剂量 DST 不抑制、垂体 MRI 阴性、胸部/腹部 CT 或功能影像（Gallium-68 DOTATATE PET）","双侧肾上腺大结节样增生（BMAH）：双侧大结节、ACTH 低，可有 LHCG 受体或 ARM5 基因突变"],"workup":["1 mg 过夜 DST、24 h UFC、午夜唾液皮质醇；血 ACTH、血钾、血气","垂体 MRI（薄层增强）；大剂量 DST、CRH 刺激试验、双侧岩下窦采血（BIPSS）鉴别库欣病与异位 ACTH","肾上腺 CT（增强，肿瘤大小与密度）；必要时 MRI","合并症评估：OGTT/HbA1c、血脂、骨密度（DXA）、肌力、精神心理评估、睡眠呼吸暂停","感染筛查（结核潜伏感染、乙肝、CMV，尤其拟用免疫调节剂者）","需排除假性库欣：饮酒史、抑郁、肥胖 + PCOS，通常 UFC 正常、DST 可轻度异常"],"grading":"按病因：ACTH 依赖性（库欣病、异位 ACTH）/ ACTH 不依赖性（肾上腺腺瘤、BMAH、肾上腺癌）；外源性。按严重度：轻、中、重（根据皮质醇水平、并发症与精神症状）。术后评估：缓解、持续、复发。"},"ddx":[{"name":"原发性醛固酮增多症（ad_pa）","point":"与本类 ad_pa 的鉴别点：库欣以向心性肥胖、紫纹、肌无力、皮质醇不被抑制为特征，醛固酮可正常；原醛以高血压 + 低钾 + 高醛固酮低肾素为特征，无紫纹与满月脸。二者可并存于肾上腺意外瘤患者。"},{"name":"嗜铬细胞瘤（ad_pheo）","point":"与本类 ad_pheo 的鉴别点：嗜铬细胞瘤为阵发性高血压伴头痛、心悸、大汗，甲氧基肾上腺素升高，皮质醇节律多正常；库欣为持续高血压、体重增加与皮质醇节律消失。"},{"name":"代谢综合征 / 单纯性肥胖","point":"肥胖可有高血压、糖尿病与腹型肥胖，但缺乏紫纹、近端肌无力与皮肤变薄；库欣筛查试验阴性（DST 抑制、UFC 正常）。BMI 高而 UFC 正常者不支持库欣。"},{"name":"酒精性假性库欣 / 抑郁","point":"长期酗酒或重度抑郁可致 HPA 轴激活、DST 不抑制，但 UFC 多正常、午夜皮质醇节律保留，戒酒或抑郁缓解后恢复；ACTH 与影像学阴性。"},{"name":"多囊卵巢综合征（PCOS）","point":"育龄女性月经稀发、多毛、痤疮与肥胖，但无紫纹与肌无力，睾酮升高、LH/FSH 比值升高，皮质醇筛查正常。"},{"name":"外源性糖皮质激素使用","point":"长期口服/外用/吸入激素可致完全相同的体貌，但 ACTH 与皮质醇均低于正常（外源性抑制），详细用药史可避免误诊与误手术。"}],"tx":{"drug":[{"name":"酮康唑","dose":"200 mg bid 起始，按 24 h 尿游离皮质醇与耐受性每 1–2 周增加 200 mg，常用 400–1200 mg/d 分 2–3 次；作为术前准备或不能手术者的长期控制","note":"抑制类固醇合成，为国内最常用的皮质醇合成抑制剂；需监测肝功能（用药前 2 个月每 2 周查 ALT），女性可致月经紊乱；男性长期使用可致性腺功能减退。","renal":"无需调整","hepatic":"活动性肝病或 ALT >2 倍上限禁用；用药期间 ALT >3 倍需停药","interact":"强效 CYP3A4 抑制剂：升高辛伐他汀、他克莫司、咪达唑仑浓度；与质子泵抑制剂合用降低吸收；与利福平合用疗效降低"},{"name":"美替拉酮","dose":"起始 250 mg bid–qid，按皮质醇与尿 11-脱氧皮质醇滴定，常至 2–4 g/d；国内可及性有限","note":"抑制 11β-羟化酶，可快速降低皮质醇；可能致高血压、低钾、多毛与水肿（盐皮质激素前体蓄积）。","renal":"无需调整","hepatic":"重度肝损伤慎用","interact":"为 CYP2B6/CYP3A4 底物与抑制剂，可升高部分镇静药浓度；与依托咪酯合用有叠加肾上腺抑制"},{"name":"米非司酮（糖皮质激素受体拮抗剂）","dose":"300 mg qd 起始，按症状与耐受性滴定，常用 300–1200 mg/d","note":"阻断皮质醇受体，不降低皮质醇水平；用于癌症相关库欣或药物无法耐受者。可引起低钾、高血压（盐皮质激素作用）与子宫内膜异位样出血；妊娠禁用。","renal":"无需调整","hepatic":"重度肝损伤慎用","interact":"强效 CYP3A4 抑制：升高咪达唑仑、他克莫司、部分化疗药浓度；与地高辛合用需监测"},{"name":"米托坦","dose":"肾上腺皮质癌：1–2 g/d 起始分 3–4 次口服，逐步增至 6 g/d（按血药浓度 14–20 mg/L 调整）；库欣病辅助治疗按说明书小剂量起始","note":"抑制皮质醇合成并破坏肾上腺皮质细胞；需同时给予糖皮质激素替代（避免肾上腺危象），监测肝功能与血脂；起效需数周。","renal":"无需调整","hepatic":"肝损伤者减量并监测，严重者禁用","interact":"强效 CYP3A4 诱导剂，降低华法林、环孢素、部分化疗药浓度；与中枢抑制药合用加重嗜睡"},{"name":"螺内酯 / 降压降糖对症药物","dose":"螺内酯 25–100 mg/d（控制低钾与高血压）；二甲双胍等按需，遵医嘱","note":"库欣患者多需 2–3 种降压药且对螺内酯反应好；糖代谢异常需积极降糖以降低围术期风险。","renal":"螺内酯 eGFR <30 禁用","hepatic":"螺内酯重度肝病慎用","interact":"螺内酯与 ACEI/ARB 合用注意高钾"}],"nonDrug":["库欣病：经鼻蝶窦垂体腺瘤切除术为首选（缓解率 70%–90%，复发率 10%–30%）；术后如手术失败可考虑放疗（伽马刀）或双侧肾上腺切除（后需终身替代 + Nelson 综合征风险）","肾上腺腺瘤：腹腔镜单侧肾上腺切除术（>95% 缓解）；BMAH 或双侧增生者行双侧肾上腺切除 + 终身糖皮质激素替代","异位 ACTH：切除原发肿瘤（肺癌、胸腺瘤）为首选，无法手术者用抑制剂 + 靶向/化疗","术后：糖皮质激素替代（氢化可的松或泼尼松 6–12 个月，按 HPA 轴恢复情况逐渐减量），避免肾上腺危象","合并症管理：骨质疏松（双膦酸盐）、感染筛查与疫苗、VTE 风险评估、精神心理支持"],"life":["术后监测：早期识别肾上腺危象（乏力、低血压、恶心），应激时增加激素剂量（加量 2–3 倍）","低盐饮食与控制体重；规律运动与抗阻训练（改善肌萎缩与骨密度）","每 6–12 个月复查 24 h UFC 或午夜皮质醇以评估复发","终身随访骨密度、血糖、血脂与血压","精神症状（抑郁、焦虑、精神病性症状）常被忽视，需精神科协作","避免自行停用糖皮质激素（术后替代者）"]},"prog":"未经治疗者心血管事件与感染病死率显著升高（标准化死亡比 2–4 倍）。手术缓解后 5 年复发率约 10%–20%（库欣病），需长期随访。术后出现的肾上腺功能不全期可持续数月至 1–2 年，需激素替代教育。早期诊断与针对性手术可显著改善代谢、骨密度与生活质量。","refs":["库欣综合征诊断和治疗的专家共识（2011 / 2023 更新，中华医学会内分泌学分会）","中国肾上腺疾病诊治指南（肾上腺性高血压部分）","Endocrine Society Clinical Practice Guideline: Treatment of Cushing's Syndrome（2015）","2021 Pituitary Society Consensus on Diagnosis and Management of Cushing's Disease","中国垂体腺瘤诊治指南（2023）"]},{"id":"ad_pheo","name":"嗜铬细胞瘤与副神经节瘤","aka":["嗜铬细胞瘤","Pheochromocytoma","PPGL","副神经节瘤"],"rank":3,"basic":{"define":"起源于肾上腺髓质嗜铬细胞（嗜铬细胞瘤）或肾上腺外副神经节的嗜铬细胞（副神经节瘤）的神经内分泌肿瘤，分泌过量的儿茶酚胺（肾上腺素、去甲肾上腺素、多巴胺），导致阵发性或持续性高血压及多系统交感兴奋症状。","risk":["20–50 岁，男女相近","阵发性高血压伴头痛、心悸、大汗、面色苍白","家族性综合征：MEN2（RET）、VHL、NF1、SDH 基因突变（SDHB 恶性风险高），约 30%–40% 呈遗传性","肾上腺意外瘤；年轻（<20 岁）多发或双侧者高度提示遗传性","使用诱发药物：β 阻滞剂未 α 阻断时、糖皮质激素、甲氧氯普胺、拟交感药、麻醉诱导"],"epi":"年发病率约 2–8/100 万，肾上腺意外瘤中约 5%–10% 为嗜铬细胞瘤。遗传性比例高（30%–40%），其中 SDHB 突变者约 30%–70% 为恶性（转移）。约 10%–15% 为恶性/转移性。"},"patho":"肿瘤细胞合成并储存儿茶酚胺，分泌呈阵发性或持续性。肾上腺素作用于 β 受体，去甲肾上腺素作用于 α1 受体，导致血管收缩、血压骤升，伴心率增快与心肌耗氧增加；长期儿茶酚胺过量引起心肌肥厚、儿茶酚胺性心肌病与心律失常。肿瘤内出血或药物诱发大量释放时，可发生高血压危象、休克与多器官功能衰竭（嗜铬细胞瘤危象）。部分患者同时分泌 ACTH、VIP 或 IL-6，出现库欣样、腹泻或发热。","dx":{"criteria":["典型三联征：阵发性头痛、心悸、大汗（敏感性高），伴阵发性或持续性高血压（可伴体位性低血压）","生化确诊：血浆游离甲氧基肾上腺素（MN）与去甲氧基肾上腺素（NMN）升高 >参考上限 2–3 倍，或 24 h 尿分馏 MN/NMN 升高（多以敏感性与特异性均 >90%）；数值轻度升高（1–2 倍）需复查或行可乐定抑制试验","筛查前准备：停用对乙酰氨基酚、拉贝洛尔、三环类抗抑郁药、α 激动剂，避免咖啡因与应激；保持静息卧位 30 min 后采血","影像定位：肾上腺 CT（增强，肿瘤多 >3 cm、易坏死囊变）或 MRI；肾上腺外/转移者行 123I-MIBG 或 68Ga-DOTATATE PET/CT","基因检测：所有患者推荐至少检测 SDHB、RET、VHL、NF1、SDHD 等（双侧、多发、年轻、家族史者必须）","恶性判断：转移（淋巴结、肺、骨、肝）为唯一确诊标准，组织学（PASS 评分）仅供参考"],"workup":["血浆游离 MN/NMN、24 h 尿分馏 MN/NMN；必要时血浆儿茶酚胺","心电图与超声心动图（儿茶酚胺性心肌病、LVH）、心肌酶","血糖与 HbA1c（儿茶酚胺抑制胰岛素分泌，约 30% 血糖升高）","肾上腺 CT 增强；MIBG 或 DOTATATE PET/CT 用于全身评估","遗传学检测与家系筛查（一级亲属血压、生化筛查）","术前 24 h 血压与心率监测；评估血容量（体位性低血压者既往容量收缩）","麻醉科会诊、心脏评估"],"grading":"①按位置：肾上腺内 / 肾上腺外（副神经节瘤）/ 多发 / 转移。②按功能：肾上腺素型（心悸、血糖高）/ 去甲肾上腺素型（持续高血压、血管收缩）/ 多巴胺型（低血压、腹泻，恶性倾向）。③按性质：良性 vs 恶性（转移）。④危象：嗜铬细胞瘤危象为高血压与休克交替、多器官衰竭（病死率高）。"},"ddx":[{"name":"原发性醛固酮增多症（ad_pa）","point":"与本类 ad_pa 的鉴别点：嗜铬细胞瘤为阵发性高血压 + 三联征、MN/NMN 升高、醛固酮正常；原醛为持续性或难治性高血压伴低钾、高醛固酮低肾素、无阵发性三联征。"},{"name":"库欣综合征（ad_cushing）","point":"与本类 ad_cushing 的鉴别点：库欣为持续高血压、向心性肥胖、紫纹、皮质醇不被抑制；嗜铬细胞瘤体重多正常或下降、无紫纹、MN/NMN 升高。异位 ACTH 分泌的嗜铬细胞瘤罕见，需同时查皮质醇。"},{"name":"广泛性焦虑障碍 / 惊恐发作","point":"心悸、出汗、恐惧、濒死感，但发作时血压多不显著升高，MN/NMN 正常（焦虑可使 NE 轻度升高但不达 2–3 倍），无肾上腺占位。"},{"name":"甲状腺功能亢进","point":"心动过速、多汗、体重下降、震颤，但 TSH 低、FT4 高，血压以收缩压升高为主，MN/NMN 正常。"},{"name":"肾血管性高血压 / 恶性高血压","point":"血压极高伴头痛、视物模糊，但无阵发性心悸与大汗，肾素高、影像见肾动脉狭窄；MN/NMN 正常。"},{"name":"药物性高血压危象（可卡因、安非他明、利血平停药）","point":"有明确用药史，血压骤升伴心动过速与精神症状，停用后缓解；MN/NMN 可轻度升高但不超过 3 倍，影像学阴性。"}],"tx":{"drug":[{"name":"酚苄明（α1/α2 受体阻滞剂）","dose":"10 mg bid 起始，每 2–3 天递增 10 mg，常用 20–60 mg/d 分 2–3 次；术前至少 10–14 天，滴定至血压正常、出现体位性低血压、鼻塞等 α 阻断充分的迹象","note":"非选择性 α 阻滞剂，为术前准备的经典药物（国内常用）；因半衰期长，术前 1 天可停用（部分中心继续至手术当日）。剂量需足量以避免术中血压飙升。","renal":"无需调整","hepatic":"重度肝损伤减量（首过代谢减慢）","interact":"与 PDE5 抑制剂、α1 阻滞剂合用致严重低血压；与拟交感药（麻黄碱、某些复方感冒药）合用升高血压"},{"name":"多沙唑嗪（α1 受体阻滞剂）","dose":"1–2 mg qn 起始，逐步增至 4–8 mg qd（部分需至 16 mg/d），术前滴定 10–14 天","note":"选择性 α1 阻滞剂，体位性低血压与反射性心动过速较酚苄明轻，半衰期短；手术当日通常停用。首剂于睡前服用。","renal":"无需调整","hepatic":"中性，重度肝损伤减量或避免","interact":"与 PDE5 抑制剂合用注意低血压；与 β 阻滞剂合用需先 α 阻断"},{"name":"美托洛尔 / 阿替洛尔（β 阻滞剂）","dose":"在 α 阻滞剂实施 3–4 天后、出现心率增快（>90–100 次/min）时加用：美托洛尔 25–50 mg bid 或阿替洛尔 25–50 mg qd，按心率调整","note":"严禁在未 α 阻断时单独使用 β 阻滞剂（可致强烈的 α 缩血管反应与高血压危象）；以心率控制为目标。","renal":"阿替洛尔 eGFR <30 减量；美托洛尔无需调整","hepatic":"美托洛尔重度肝损伤减量","interact":"与维拉帕米/地尔硫卓合用致心动过缓与心衰；与拟交感药拮抗"},{"name":"硝苯地平 / 氨氯地平（补充降压）","dose":"控释硝苯地平 30 mg qd 或氨氯地平 5–10 mg qd，按血压滴定","note":"α 阻滞剂后仍有显著高血压时联合钙拮抗剂；部分中心考虑钙拮抗剂可作为 α 阻滞剂的补充。","renal":"无需调整","hepatic":"氨氯地平重度肝损伤起始 2.5 mg","interact":"硝苯地平与葡萄柚汁合用升高血药浓度；与 CYP3A4 抑制剂合用需减量"},{"name":"嗜铬细胞瘤危象抢救用药","dose":"酚妥拉明 1–5 mg 静脉缓慢推注，后以 0.5–1 mg/min 泵入（按血压滴定）；α 阻断后心动过速者加用艾司洛尔按说明书；低血压期以去甲肾上腺素/液体复苏维持，遵医嘱","note":"危象表现为高血压与休克交替、急性肺水肿与心肌损伤，需 ICU 与麻醉科协作；禁用单纯 β 阻滞剂。","renal":"肾血流减少时慎用，密切监测尿量","hepatic":"重度肝损伤减量","interact":"与 β 阻滞剂联用须先保证 α 阻断；与三环类抗抑郁药合用增强升压反应"}],"nonDrug":["手术切除为治愈手段：腹腔镜（<6 cm、无侵袭）或开放手术（巨大/侵袭/儿茶酚胺极高）；术前充分 α 阻断 ≥10–14 天","术前扩容：α 阻断后静脉输注晶体液 1–2 L/d（按心功能调整），减少术中低血压","术中监测：动脉血压、中心静脉压/心输出量；备酚妥拉明/硝普钠与去甲肾上腺素","转移 / 恶性：手术减瘤 + 131I-MIBG 治疗、肽受体放射性核素治疗（PRRT）、靶向治疗（舒尼替尼、贝伐珠单抗、依维莫司）","遗传性综合征（MEN2、VHL、SDH 突变）家系筛查：影像与生化监测（SDHB 突变者终身随访转移）"],"life":["术前避免诱发因素：禁用糖皮质激素、甲氧氯普胺、拟交感药、未 α 阻断的 β 阻滞剂","术后监测：儿茶酚胺骤降可致低血压与低血糖（术后 24–48 h 监测血糖）","终身随访：术后第 1 年每 6–12 个月复查生化、之后每年；遗传性者终身；影像对转移者每 6–12 个月","生活方式：避免剧烈运动与情绪激动（术前）；避免高酪胺饮食（部分患者）","家系筛查与遗传咨询；告知麻醉史（手术/牙科前需说明）","建议携带医疗警示卡"]},"prog":"充分 α 阻断后手术病死率已降至 <2%（历史上未经准备可达 50%）。约 80%–90% 术后血压恢复正常，约 30% 仍残留高血压（与长期儿茶酚胺致血管重塑有关）。遗传性与 SDHB 突变者需终身监测，恶性/转移者 5 年生存率约 50%（SDHB 相关者较低）。约 5%–10% 术后肿瘤复发/对侧新发，遗传性者更常见。","refs":["嗜铬细胞瘤和副神经节瘤诊断治疗的专家共识（2020 版，中华医学会内分泌学分会）","中国肾上腺意外瘤专家共识（2021）","Endocrine Society Clinical Practice Guideline: Pheochromocytoma and Paraganglioma（2014）","2023 WHO Classification of Endocrine and Neuroendocrine Tumours","中国遗传性嗜铬细胞瘤/副神经节瘤诊治专家共识"]}]},{"id":"metab","name":"代谢与骨","rank":4,"summary":"痛风按「急性期抗炎、发作间歇降尿酸」两步管理，降尿酸须达标（UA <360 μmol/L，有痛风石 <300 μmol/L）并持续，急性期不停用已开始降尿酸药。骨质疏松以 DXA 骨密度 T 值 ≤−2.5 或脆性骨折为诊断核心，先纠正钙与维生素 D 及继发因素，再选抗骨吸收或促骨形成药物并严格随访。","compare":[{"diseaseId":"gout","dx":"急性单关节炎（第一跖趾关节最常见）、血尿酸升高；关节液偏振光镜下见针状负双折射尿酸盐结晶为金标准，超声见双轨征、痛风石","key":"尿酸盐结晶沉积导致的炎症性关节炎，随血尿酸长期控制可溶解石与减少复发"},{"diseaseId":"op","dx":"DXA 骨密度 T 值 ≤−2.5（绝经后女性、≥50 岁男性）；或髋部/椎体脆性骨折；或既往髋部/椎体骨折","key":"骨量与骨质量下降致脆性骨折，治疗以改善骨强度与预防再骨折为目标，T 值不随钙剂提升"}],"diseases":[{"id":"gout","name":"痛风","aka":["痛风性关节炎","Gout","高尿酸血症相关关节炎"],"rank":1,"basic":{"define":"因长期高尿酸血症导致单钠尿酸盐（MSU）结晶沉积在关节、滑囊、肌腱与肾脏，引起急性炎症性关节炎与慢性痛风石病变的代谢性疾病。","risk":["男性（绝经前女性少见），40–60 岁高发","高嘌呤饮食（动物内脏、海鲜、浓肉汤、啤酒、含糖饮料）","肥胖、代谢综合征、糖尿病、高血压、血脂异常","肾脏病（eGFR 下降）、噻嗪类与袢利尿剂、小剂量阿司匹林、环孢素使用","痛风或高尿酸血症家族史；骨髓增殖性疾病、化疗后肿瘤溶解"],"epi":"我国成人高尿酸血症患病率约 13%–14%，痛风患病率约 1.1%–1.4%，男性显著高于女性；近 10 年呈上升和年轻化趋势。约 10%–20% 高尿酸血症者最终发展为痛风。"},"patho":"血尿酸超过 420 μmol/L（约 7 mg/dL，尿酸盐饱和浓度）后，MSU 结晶析出并沉积于关节与周围组织。结晶被巨噬细胞吞噬后激活 NALP3 炎症小体，IL-1β 大量释放，中性粒细胞浸润，引起剧烈的自限性急性关节炎（常在夜间发作、24 h 内达高峰）。反复发作后形成痛风石，侵蚀骨质与关节结构。尿酸由嘌呤代谢终产物生成，约 90% 的高尿酸血症由肾脏尿酸排泄减少引起。","dx":{"criteria":["急性关节炎：单关节（第一跖趾关节最经典）红肿热痛，24 h 内达高峰，可数日至 2 周自行缓解","金标准：关节液或痛风石抽吸物在偏振光显微镜下见针状、负双折射 MSU 结晶（阴性不能排除；化脓性与痛风可并存）","血尿酸：急性期可正常（发作时约 30% 患者血尿酸正常），不能以此排除；确诊需结合结晶或影像","超声：双轨征、暴风雪征、痛风石；双能 CT 可见尿酸盐沉积","高尿酸血症定义：正常嘌呤饮食下两次空腹血尿酸男 >420 μmol/L、女 >360 μmol/L","诊断评分：2015 ACR/EULAR 痛风分类标准（关节液结晶为确诊项，或临床 + 超声/双能 CT + 血尿酸 + 发作特点综合 ≥8 分）","特殊部位：足跟、髌骨滑囊、髋关节可受累；脊柱痛风表现为局限背痛 + 神经症状"],"workup":["血尿酸、血常规、ESR/CRP（发作期升高）、肾功能（eGFR）、肝功能、血糖与血脂","关节液：结晶镜检 + 细胞计数 + 革兰染色与培养（排除化脓性关节炎）","关节 X 线（慢性期见穿凿样骨质缺损、悬边征）、超声、双能 CT","24 h 尿尿酸（<600 mg/24 h 提示排泄减少型，>1000 mg 需查黄嘌呤代谢异常）","肾结石评估（泌尿系超声）、血压与心血管风险评估","排除继发因素：骨髓增殖性疾病、银屑病、铅中毒、药物（利尿剂、环孢素、低剂量阿司匹林）"],"grading":"①临床分期：无症状高尿酸血症、急性发作期、间歇期、慢性痛风石期。②2015 ACR/EULAR 评分（≥8 分确诊）。③严重程度：发作频率（≥2 次/年）、多关节、痛风石、影像学侵蚀、合并 CKD（≥2 期）。"},"ddx":[{"name":"骨质疏松症（op）","point":"与本类 op 的鉴别点：痛风为急性红肿热痛的炎症性单关节炎，CRP/ESR 升高、血尿酸高、关节液见尿酸盐结晶；骨质疏松多无急性关节红肿，表现为脆性骨折与腰背痛，DXA T 值 ≤−2.5，无高尿酸血症。"},{"name":"化脓性关节炎","point":"急性单关节炎 + 发热 + 关节液白细胞 >50,000/μL、中性粒 >90%、培养阳性；痛风亦可模拟，需镜检结晶并同时抗感染，二者可并存（免疫抑制者尤需警惕）。"},{"name":"焦磷酸钙沉积病（假性痛风）/ CPPD","point":"关节液见菱形、正双折射焦磷酸钙结晶，X 线见软骨钙化（膝关节、耻骨联合），多见于老年；血尿酸常正常。"},{"name":"类风湿关节炎（早期单关节型）","point":"持续 >6 周的多关节炎（腕、MCP、PIP 对称），晨僵 >1 h，RF/抗 CCP 阳性；痛风为发作性、单关节、夜间骤起。"},{"name":"蜂窝织炎 / 丹毒","point":"皮肤红肿、边界清楚、有淋巴管炎与发热，关节活动不受限；痛风有剧烈关节痛与压痛，可伴局部皮肤脱屑，必要时针吸或超声鉴别。"},{"name":"足部应力骨折 / 拇外翻急性炎症","point":"局部压痛 + 活动相关痛，X 线/CT 见骨折线；痛风多为夜间自发、伴血尿酸升高与超声改变。"}],"tx":{"drug":[{"name":"秋水仙碱","dose":"急性期：首剂 1 mg（0.5 mg×2 片），1 h 后 0.5 mg，12 h 后起 0.5 mg qd–bid，至症状缓解（单日总量 ≤2 mg，疗程 3–7 天）；预防：0.5 mg qd–bid，连用 3–6 个月","note":"应在发作 24–36 h 内尽早使用，越早越有效；低剂量方案与高剂量等效且腹泻更少，出现腹泻即停药。与他汀、贝特类、环孢素、克拉霉素合用增加肌病/中毒风险。","renal":"eGFR <30 禁用（或仅单次 0.5 mg 并严格评估）；透析患者避免；eGFR 30–60 减量并慎用","hepatic":"重度肝损伤禁用（经 CYP3A4 代谢，毒性蓄积）","interact":"与 CYP3A4（克拉霉素、酮康唑）及 P-糖蛋白抑制剂（环孢素、维拉帕米）合用显著升高毒性；与他汀类合用增加肌病；葡萄柚汁升高血药浓度"},{"name":"依托考昔（NSAIDs）","dose":"急性期 120 mg qd×8 天，后改 60 mg qd 至缓解；需用最短有效疗程","note":"NSAIDs 为急性期一线选择（与秋水仙碱、糖皮质激素并列）；有消化道溃疡、心脑血管病、心衰或 CKD 者慎用/禁用，老年人宜同时用 PPI。","renal":"eGFR <30 禁用；eGFR 30–60 慎用，监测肌酐与血钾","hepatic":"重度肝损伤禁用；8 天后转 60 mg 并复查肝功能","interact":"与 ACEI/ARB、利尿剂合用可致急性肾损伤、削弱降压；与抗凝药/抗血小板增加出血；与锂剂合用升高锂浓度"},{"name":"萘普生（NSAIDs）","dose":"急性期 500 mg bid（首日可 750 mg），疗程 3–7 天至缓解","note":"传统 NSAIDs 备选，需餐后服用；起效快但胃肠道反应最多见。","renal":"eGFR <60 慎用，<30 禁用","hepatic":"重度肝损伤禁用","interact":"同上（消化道出血、肾损伤、降压削弱）"},{"name":"泼尼松（口服糖皮质激素）","dose":"急性期 30–35 mg qd×3–5 天；或多关节受累时关节腔内注射复方倍他米松/曲安奈德按说明书","note":"适用于 NSAIDs/秋水仙碱禁忌（CKD、消化道出血、心衰）或发作剧烈者；短期使用无须渐减，但长期反复使用需监测血糖与骨量。","renal":"无需调整（CKD 者优于 NSAIDs）","hepatic":"重度肝损伤注意水钠潴留与血糖升高","interact":"与降糖药拮抗；与 NSAIDs 合用增加消化道出血；利福平/苯妥英加速代谢"},{"name":"别嘌醇（降尿酸，黄嘌呤氧化酶抑制剂）","dose":"起始 100 mg qd（CKD 者 50 mg qd），每 2–4 周递增 100 mg，直至血尿酸 <360 μmol/L（有痛风石 <300 μmol/L），常用 200–300 mg/d，最大 800 mg/d","note":"一线降尿酸药（HLA-B*5801 阴性者优先）；不推荐在急性发作时开始（已服用则不应停药）。起始阶段须联用秋水仙碱或 NSAIDs 预防发作（3–6 个月）。汉族人群 HLA-B*5801 阳性率约 10%–15%，用药前建议筛查以预防 Stevens-Johnson 综合征。","renal":"eGFR <60 起始 50–100 mg 并缓慢滴定；eGFR <30 减至 50–100 mg/d；透析患者 100 mg qd 或 3 次/周（按说明书）","hepatic":"重度肝损伤减量并监测肝功能","interact":"与硫唑嘌呤/6-巯基嘌呤合用致严重骨髓抑制（禁忌或大幅减量）；与氨苄西林/阿莫西林合用增加皮疹；噻嗪类利尿剂升高尿酸抵消疗效"},{"name":"非布司他（降尿酸）","dose":"起始 20–40 mg qd，2–4 周后按血尿酸增至 40–80 mg qd，目标同别嘌醇","note":"别嘌醇不耐受或疗效不足者；合并心血管疾病者需权衡心血管风险信号（CARES 研究），国内指南仍列为一线之一。","renal":"轻中度 CKD 无需调整；eGFR <30 起始 20 mg","hepatic":"轻中度无需调整；重度肝损伤慎用并监测","interact":"与硫唑嘌呤/6-MP 合用需大幅减量；与氨茶碱/茶碱合用需监测；强 CYP3A4 抑制剂可轻度升高血药浓度"},{"name":"苯溴马隆（促尿酸排泄）","dose":"25–50 mg qd 早餐后服，可增至 100 mg qd；2–4 周后按血尿酸调整","note":"适用于尿酸排泄减少型（24 h 尿尿酸 <600 mg）、无肾结石者；用药期间大量饮水（>2000 mL/d）、碱化尿液（尿 pH 6.2–6.8）；肝功能异常者禁用（曾有肝衰竭报告）。","renal":"eGFR <30 禁用；eGFR 30–60 减量并监测","hepatic":"肝功能不全者禁用；用药前后监测 ALT/AST","interact":"与水杨酸类（含阿司匹林 >75 mg/d）、吡嗪酰胺、乙胺丁醇合用降低疗效"},{"name":"培戈洛酶（难治性痛风）","dose":"8 mg 静脉输注 q2w（按说明书）；用药前筛查 G6PD 与抗体，须预先抗组胺/糖皮质激素","note":"国内可及性极为有限，仅用于常规降尿酸无效的重度痛风石性痛风；可诱发严重过敏反应与溶血（G6PD 缺乏者）。","renal":"严重肾功能不全慎用","hepatic":"重度肝损伤慎用","interact":"与其他降尿酸药联用数据有限；输注前后需停用其他降尿酸药以防尿酸快速波动"}],"nonDrug":["痛风石/关节破坏严重者行关节镜清理、痛风石切除（需在血尿酸控制后进行）","尿路结石：尿酸结石可碱化尿液 + 别嘌醇；磷酸钙结石避免过度碱化","急性发作关节局部冷敷、休息抬高患肢","降尿酸目标持续达标 6–12 个月以上再考虑停用，不推荐「发作才吃药」","合并 CKD 者可考虑 SGLT2i（兼有降尿酸作用）"],"life":["限制高嘌呤食物（内脏、浓肉汤、沙丁鱼、贝类），限制果糖饮料与酒精（尤其啤酒、白酒）","每日饮水 ≥2000 mL（心肾功能允许），促进尿酸排泄","减重（每月 1–2 kg，避免快速减重诱发急性发作）、规律中等强度运动","停用或替换诱发药物（噻嗪类/袢利尿剂、小剂量阿司匹林在无必要时）","长期随访监测血尿酸、肾功能与肝功能","避免受凉、关节外伤与剧烈运动后脱水"]},"prog":"规律达标降尿酸可使 90% 以上患者无发作，痛风石可在 1–3 年内溶解。未治疗者约 60% 在 1 年内复发，长期可致关节畸形、骨质破坏、尿酸性肾病与尿路结石。合并代谢综合征、CKD 与心血管病者预后更差，且血尿酸升高与高血压、CKD 进展独立相关。","refs":["中国高尿酸血症与痛风诊疗指南（2019，中华医学会内分泌学分会）","中国痛风诊疗指南（2016，中华医学会风湿病学分会）","2020 ACR Guideline for the Management of Gout","2015 ACR/EULAR Gout Classification Criteria"]},{"id":"op","name":"骨质疏松症","aka":["骨质疏松","Osteoporosis","OP","原发性骨质疏松症"],"rank":2,"basic":{"define":"以骨量减少、骨组织微结构破坏、骨脆性增加、易发生脆性骨折为特征的全身性骨病；DXA 测得 T 值 ≤−2.5 或发生髋部/椎体脆性骨折即可诊断（即使 T 值正常）。","risk":["绝经后女性（雌激素下降使骨吸收加速），≥65 岁男性","低 BMI、既往脆性骨折、髋部骨折家族史","长期糖皮质激素（≥5 mg/d 泼尼松等效 >3 个月）、PPI、抗癫痫药、芳香化酶抑制剂","吸烟、过量饮酒、缺乏运动、光照不足与钙/维生素 D 摄入不足","甲亢、甲状旁腺功能亢进、库欣、性腺功能减退、糖尿病、慢性肾病、吸收不良"],"epi":"我国 50 岁以上人群骨质疏松患病率女性约 32%、男性约 6%，65 岁以上女性超过 50%；40–49 岁人群低骨量率约 32.9%。骨质疏松性骨折（髋、椎体、腕）年发病在百万量级，髋部骨折后 1 年内病死率 20%–30%。"},"patho":"骨重建过程中，破骨细胞吸收与成骨细胞形成的耦联失衡，导致骨量丢失与微结构破坏（骨小梁变细断裂、皮质骨变薄多孔）。绝经后雌激素缺乏使破骨细胞凋亡减少、RANKL/OPG 比值升高、骨吸收活跃；老年人则有成骨细胞功能减退与骨形成不足（低转换状态）。糖皮质激素直接抑制成骨细胞并增加破骨细胞活性，早期即显著丢失骨量。骨强度下降后，轻微外力即可致脆性骨折，最常累及椎体（压缩）、髋部与桡骨远端。","dx":{"criteria":["DXA 骨密度 T 值 ≤−2.5（绝经后女性、≥50 岁男性，腰椎 1–4、股骨颈或全髋最常用）","髋部或椎体脆性骨折（低能量外伤），无论 T 值如何即可诊断骨质疏松","T 值 −1.0 至 −2.5 为低骨量（骨量减少）；T 值 ≥−1.0 为正常","椎体影像性骨折：胸腰段 X 线或 MRI/CT 见楔形、双凹或压缩变形（高度丢失 ≥20%）","继发因素需排除：血钙、磷、碱性磷酸酶、25-OH-VitD、PTH、TSH、肝肾功能、血尿钙、性激素、血/尿轻链（疑骨髓瘤）","FRAX（中国模型）10 年主要骨质疏松性骨折风险 ≥20% 或髋部骨折风险 ≥3% 可考虑干预","糖皮质激素性骨质疏松（GIOP）：泼尼松等效 ≥5 mg/d 超过 3 个月即应评估干预，T 值 ≤−1.5 或已发生低能量骨折者更强"],"workup":["DXA（腰椎 + 髋部，同一设备随访；治疗前基线，1–2 年后复查）","椎体压缩骨折筛查（胸腰椎侧位 X 线/VFA；必要时 MRI 鉴别新鲜骨折）","骨转换标志物：CTX（吸收）、P1NP（形成），用于评估依从性与疗效","血钙、磷、25-OH-VitD、PTH（排除甲旁亢）、碱性磷酸酶、24 h 尿钙、肝肾功能、TSH","男性查睾酮、PSA；女性查性激素与月经史；必要时骨髓穿刺/血尿轻链（骨髓瘤）","身高缩短 ≥4 cm 或新发背痛者行影像学评估","跌倒风险评估：视力、平衡、步态、致跌药物与环境"],"grading":"①按骨密度：正常（T ≥−1.0）、低骨量（−2.5 < T < −1.0）、骨质疏松（T ≤−2.5）、严重骨质疏松（骨质疏松 + 脆性骨折）。②按病因：原发性（绝经后 I 型、老年性 II 型）/ 继发性。③骨折风险分层：极高危（近期 ≥2 次骨折、T 值极低、大剂量糖皮质激素）、高危、普通。"},"ddx":[{"name":"痛风（gout）","point":"与本类 gout 的鉴别点：骨质疏松为慢性过程，无急性关节红肿热痛，以脆性骨折与腰背痛为主要表现，DXA 骨密度低、CRP 通常正常；痛风为发作性单关节炎、血尿酸高、关节液见尿酸盐结晶。痛风石在 X 线上可模拟骨侵蚀，但分布不同。"},{"name":"骨转移瘤 / 多发性骨髓瘤","point":"骨痛持续且夜间加重、贫血、高钙血症、蛋白电泳见 M 蛋白；X 线为溶骨性病变而非弥漫性骨密度减低；需骨髓穿刺确诊。DXA 不能排除此类病变。"},{"name":"原发性甲状旁腺功能亢进","point":"血钙升高、PTH 升高、24 h 尿钙升高、肾结石与骨膜下骨吸收（指骨桡侧缘），可致骨密度降低；需查碱性磷酸酶与颈部超声/核素扫描。"},{"name":"骨软化症（维生素 D 缺乏）","point":"骨痛与肌无力弥漫、碱性磷酸酶升高、25(OH)D 低、血磷低；X 线见假骨折线，与骨质疏松的骨密度降低不同，需先纠正维生素 D。"},{"name":"继发性骨质疏松（糖皮质激素/性腺功能减退）","point":"有明确用药史或低睾酮/低雌激素；治疗需同时处理病因（最小有效激素剂量、必要时性激素替代）。"},{"name":"腰椎退行性变 / 椎体血管瘤","point":"DXA 可因骨赘与钙化假性升高腰椎骨密度，此时以股骨颈/全髋为准；X 线见骨赘与硬化。"}],"tx":{"drug":[{"name":"碳酸钙 + 维生素 D3","dose":"元素钙 500–600 mg bid（总摄入 1000–1200 mg/d，含饮食）；维生素 D3 800–1200 IU qd；严重缺乏者先补负荷量","note":"所有骨质疏松患者的基础补充；钙分次服用（单次 ≤500 mg）吸收更好；不推荐单纯补钙与维生素 D 替代抗骨质疏松药物。","renal":"eGFR <30 慎用钙剂；高钙血症者禁用","hepatic":"无特殊调整","interact":"钙剂与左甲状腺素、喹诺酮类、四环素、铁剂间隔 2–4 h；噻嗪类利尿剂可致高钙"},{"name":"阿仑膦酸钠（双膦酸盐）","dose":"70 mg qw 或 10 mg qd 口服；晨起空腹用 200 mL 白水送服，服药后至少 30 min 保持直立、不进食","note":"多数患者一线抗骨吸收药；治疗 3–5 年后评估是否进入药物假期（高危者继续）。用药前纠正低钙与维生素 D 缺乏。","renal":"eGFR <35 禁用；eGFR 35–60 慎用","hepatic":"无需调整","interact":"与钙剂、铁剂、抗酸药、PPI 同服降低吸收；与 NSAIDs 合用增加消化道溃疡风险"},{"name":"唑来膦酸（静脉双膦酸盐）","dose":"5 mg 静脉滴注（≥15 min）每年 1 次，连用 3 年","note":"口服不耐受或依从性差者首选静脉方案；输注后 1–3 天可有流感样症状（对乙酰氨基酚处理）；注意低钙（预先补维生素 D 与钙）、肾毒性（输注前充分水化）与颌骨坏死（用药前口腔评估）。","renal":"eGFR <35 禁用","hepatic":"无需调整","interact":"与肾毒性药物（NSAIDs、氨基糖苷类）合用增加肾损伤；勿与含钙液体同通路输注"},{"name":"地舒单抗（RANKL 抑制剂）","dose":"60 mg 皮下注射 q6m","note":"双膦酸盐不耐受、肾功能不全或高骨折风险者；停药后骨密度快速下降与多发椎体骨折风险（停用后须双膦酸盐衔接或继续治疗）；用药前纠正低钙。","renal":"无需调整（重度 CKD 低钙风险高，需监测）","hepatic":"无需调整","interact":"不与其他抗骨吸收药联用；与他汀类无明确相互作用"},{"name":"特立帕肽（PTH 1-34，促骨形成）","dose":"20 μg 皮下注射 qd，疗程 ≤24 个月","note":"极高危者（多发脆性骨折、T 值 ≤−3.5、重症 GIOP）首选；之后序贯抗骨吸收药以维持骨密度；有骨肉瘤病史、Paget 病与骨转移者禁用（黑框警示）。","renal":"eGFR <30 禁用","hepatic":"重度肝损伤慎用","interact":"与地高辛合用需监测（高钙可致地高辛毒性）；与噻嗪类合用增加高钙风险"},{"name":"雷洛昔芬（选择性雌激素受体调节剂）","dose":"60 mg qd 口服","note":"绝经后轻中度骨质疏松、合并乳腺癌高风险者适用，可降低入侵性乳腺癌风险；有 VTE 史或活动性血栓者禁用；可加重潮热。","renal":"重度肾功能不全慎用","hepatic":"肝功能不全或胆汁淤积禁用","interact":"与华法林合用增强抗凝；考来烯胺降低吸收"},{"name":"糖皮质激素性骨质疏松（GIOP）预防","dose":"泼尼松等效 ≥5 mg/d 超过 3 个月者：补充钙与维生素 D，并加用双膦酸盐或地舒单抗（按风险分层），遵说明书","note":"激素治疗 3–6 个月内骨密度即显著下降，应尽早评估并启动预防；尽量使用最小有效剂量与最短疗程。","renal":"按所选药物调整（双膦酸盐 eGFR <35 禁用）","hepatic":"按所选药物调整","interact":"见各药条目"}],"nonDrug":["跌倒预防：平衡与肌力训练（太极、抗阻训练）、家居改造（照明、扶手、防滑）、视力矫正、减停致跌药物","脊柱微创治疗：椎体成形/后凸成形术用于保守治疗无效的疼痛性椎体压缩骨折（严格选择指征）","髋部骨折：尽早手术（48 h 内）+ 抗骨质疏松治疗，建立骨折联络服务（FLS）","使用双膦酸盐/地舒单抗前做牙科评估，减少颌骨坏死风险","治疗随访：DXA 每 1–2 年、骨转换标志物 3–6 个月评估依从性；治疗 3–5 年后评估药物假期"],"life":["每日钙摄入 1000–1200 mg（奶制品、豆制品、深绿色蔬菜），维生素 D 600–800 IU（老年 800–1200 IU）","每日 30 min 负重运动（快走、慢跑）+ 抗阻训练与平衡训练，每周 ≥3 次","充足日照（每日 15–30 min，避免暴晒）","戒烟、限酒；避免过量咖啡因与碳酸饮料","防跌倒：防滑鞋、夜间照明、浴室防滑垫、避免独自搬重物","长期糖皮质激素或 PPI 使用者定期评估骨密度","保持良好体位，避免长时间弯腰与负重"]},"prog":"规范抗骨质疏松治疗可使椎体骨折风险下降约 50%–70%、髋部骨折下降约 40%；依从性差（1 年停药率 >50%）是治疗失败的主要原因。发生过一次脆性骨折者再次骨折风险增加 2–10 倍。老年髋部骨折后 1 年内病死率高达 20%–30%，致残率高，故骨折后须衔接抗骨质疏松治疗与随访。","refs":["原发性骨质疏松症诊疗指南（2022 版，中华医学会骨质疏松和骨矿盐疾病分会）","中国骨质疏松症流行病学调查（2018）","中国糖皮质激素诱导的骨质疏松症诊治专家共识（2020）","2022 AACE/ACE Clinical Practice Guideline for the Diagnosis and Treatment of Postmenopausal Osteoporosis","NIH Consensus Development Panel on Osteoporosis Prevention, Diagnosis, and Therapy（2001）"]}]},{"id":"endo_extra","name":"内分泌其他","rank":5,"summary":"甲状腺炎症、结节/肿瘤与甲状旁腺疾病：甲状腺炎重在分清甲亢期/甲减期，甲状腺结节以超声 TI-RADS + TSH 定穿刺与功能，甲状旁腺病以校正钙与 PTH 联读。","compare":[{"diseaseId":"thy_thyroiditis","dx":"亚急性：颈前疼痛、发热、ESR 快、摄碘率低而 T4 高；桥本：无痛、TPOAb 高滴度、弥漫低回声","key":"疼痛 + ESR 快 + 摄碘率低 = 亚急性；无痛 + 抗体高 = 桥本"},{"diseaseId":"thy_thyroid_nodule","dx":"局灶性甲状腺结节，PTC 最常见；TI-RADS ≥4 类或伴淋巴结异常需穿刺","key":"TSH + TI-RADS 决定是否穿刺；功能自主结节不做 TSH 抑制"},{"diseaseId":"pt_hypopth","dx":"校正钙 <2.1 mmol/L + PTH 低或不适当地正常，手足搐搦、Chvostek 征阳性","key":"低钙 + PTH 低/正常"},{"diseaseId":"pt_hyperpth","dx":"校正钙 >2.6 mmol/L + PTH 升高；原发性多为单腺瘤，继发见于 CKD/透析","key":"高钙 + PTH 高；合并 CKD 者为继发"}],"diseases":[{"id":"thy_thyroiditis","name":"甲状腺炎","aka":["亚急性甲状腺炎","De Quervain 甲状腺炎","桥本甲状腺炎","桥本病","Hashimoto Thyroiditis"],"rank":1,"basic":{"define":"以甲状腺炎症损伤为共性的疾病。亚急性者多为病毒感染后肉芽肿性炎症，痛性肿伴一过性甲状腺毒症；桥本为自身免疫性慢性淋巴细胞浸润，先短暂甲亢、多进展为永久甲减。","risk":["上呼吸道病毒感染后（亚急性）","女性、30–50 岁，桥本男女比约 1:5–10","自身免疫病家族史或合并 1 型糖尿病、干燥综合征","产后甲状腺炎史","碘摄入异常"],"epi":"桥本是我国最常见甲减病因，女性患病率约 1%–2%；亚急性甲状腺炎约占甲状腺门诊 5%，多见于中青年女性。"},"patho":"亚急性：病毒触发细胞免疫，滤泡被多核巨细胞与肉芽肿破坏，激素漏入血致甲状腺毒症，摄碘率反低，恢复期摄碘率回升，多数自愈。桥本：T 细胞与 TPOAb/TgAb 介导滤泡破坏、淋巴细胞浸润与纤维化，激素合成不足。","dx":{"criteria":["亚急性：颈前疼痛可放射至耳/下颌，甲状腺肿大触痛、可发热；ESR >50 mm/h（常 >100），T4/T3 升高而摄碘率显著减低","亚急性：穿刺见多核巨细胞与肉芽肿","桥本：TPOAb 明显升高（常 >500 IU/mL）、TgAb 阳性，超声弥漫低回声不均质","桥本：破坏性甲亢期摄碘率低；继之亚临床甲减（TSH 高、FT4 正常），最终临床甲减","桥本结节增大或质硬时需穿刺排除乳头状癌/淋巴瘤","妊娠 TSH 上限：孕早期 2.5、孕中晚期 3.0 mIU/L"],"workup":["TSH、FT4、FT3、TPOAb、TgAb；亚急性加 ESR、CRP","摄碘率或彩超血流","甲状腺彩超","细针穿刺（亚急性确诊、桥本可疑结节）","必要时抗核抗体、血常规"],"grading":"亚急性：甲状腺毒症期→甲减/恢复期→恢复期；桥本：功能正常抗体阳性→亚临床甲减→临床甲减。"},"ddx":[{"name":"甲状腺结节与癌","point":"与本类中甲状腺结节与癌的鉴别：甲状腺炎多为弥漫性肿痛或弥漫低回声，无局灶恶性征象；桥本背景下孤立坚硬结节仍须穿刺。"},{"name":"Graves 病","point":"无压痛、摄碘率增高、TRAb 阳性，可伴突眼；亚急性为痛性肿 + 摄碘率低。"},{"name":"化脓性甲状腺炎","point":"高热、局部红肿热、白细胞高，超声见脓肿腔，需抗感染+引流。"},{"name":"甲状腺淋巴瘤","point":"老年桥本背景，数周内迅速增大、质硬伴压迫，活检见异型淋巴细胞。"},{"name":"产后无痛性甲状腺炎","point":"产后 1–6 个月，无痛、短暂甲亢后甲减，摄碘率低；以观察为主。"}],"tx":{"drug":[{"name":"泼尼松（亚急性）","dose":"20–40 mg/d 分次，症状 24–48 h 缓解后每周减 5 mg，总疗程 6–8 周；轻型可用布洛芬 400 mg tid","note":"减量过快易复发（10%–20%）；监测血糖血压","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血风险"},{"name":"普萘洛尔（亚急性甲状腺毒症期）","dose":"10–20 mg tid–qid","note":"仅对症；破坏性释放不用抗甲状腺药与放射性碘；哮喘者禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与钙通道阻滞剂合用致心动过缓"},{"name":"左甲状腺素（桥本甲减）","dose":"1.6–1.7 μg/kg/d 替代（成人常 50–100 μg/d 起），老年或合并冠心病 12.5–25 μg/d 起，每 4–6 周加量；目标 TSH 0.5–2.5 mIU/L","note":"晨起空腹服；6–8 周复查 TSH；亚临床甲减 TSH >10 mIU/L 应治疗，4–10 伴症状/抗体阳性/妊娠者亦治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"与铁剂、钙剂、PPI 间隔 4 h 以上"},{"name":"硒酵母（桥本辅助）","dose":"100–200 μg/d，6 个月后评估","note":"可降低抗体滴度，不替代 L-T4；超量致硒中毒","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["亚急性以休息、止痛为主，激素依赖复发的少数可局部放疗","桥本甲状腺明显肿大伴压迫或疑恶性者行甲状腺次全切除","妊娠期桥本 L-T4 需量增加 20%–30%，每 4 周复查 TSH"],"life":["亚急性 1–3 个月自愈，第 1、3、6 个月随访甲功","桥本未服药者每年查 TSH；服药者每 6–12 个月复查","妊娠期监测 TSH 并及时调量"]},"prog":"亚急性多自愈，约 5%–10% 永久甲减，复发率 2%–5%。桥本缓慢进展，每年约 2%–5% 由亚临床甲减转为临床甲减，规范替代后生活正常。","refs":["中华医学会内分泌学分会《甲状腺功能减退症诊治指南》2017","《中国甲状腺疾病诊治指南——甲状腺炎》2008","《内科学》第 9 版 第二十一章"]},{"id":"thy_thyroid_nodule","name":"甲状腺结节与癌（内分泌视角）","aka":["甲状腺结节","甲状腺癌","乳头状甲状腺癌","PTC","TI-RADS"],"rank":2,"basic":{"define":"甲状腺内影像学可区分的局灶性病变，多数良性；恶性中乳头状癌占 85% 以上。内分泌视角关注功能状态（TSH）、TI-RADS 风险分层、术后 TSH 抑制与 L-T4 管理。","risk":["童年颈部放射史","甲状腺癌家族史、MEN2、FAP","女性、30–50 岁","结节质硬、固定、伴声带麻痹或淋巴结肿大","桥本甲状腺炎背景"],"epi":"超声检出率 20%–70%，恶性占 5%–15%。我国甲状腺癌年发病约 22 万，女性居恶性肿瘤第 3 位，PTC 5 年生存 >95%。"},"patho":"PTC 多由 BRAF V600E 突变或 RET/PTC 重排驱动，淋巴道转移为主；滤泡癌经血行转移；髓样癌源自滤泡旁 C 细胞，与 RET 胚系突变相关；未分化癌由分化癌去分化而来，进展极快。","dx":{"criteria":["超声描述大小、边界、回声、纵横比、钙化、血流与淋巴结","C-TIRADS：3 类恶性 <2%，4A 2%–10%，4B 10%–50%，4C 50%–90%，5 类 >90%","穿刺指征：4 类且 ≥1.0 cm；3 类 ≥1.5–2.5 cm 或随访增大；5 类 ≥0.5 cm 伴淋巴结异常；伴声带麻痹/快速增大者不论大小","TSH 降低者先行核素显像，热结节多良性不穿刺；TSH 正常或升高按超声风险穿刺","细胞学 Bethesda Ⅰ–Ⅵ；术后 ATA 危险分层低/中/高危"],"workup":["甲状腺及颈部淋巴结超声","TSH、FT4、FT3；疑髓样癌查降钙素、CEA","细针穿刺 + 必要时 BRAF V600E 检测","TSH 低者核素显像","术前颈部增强 CT（巨大/胸骨后结节）、喉镜"],"grading":"C-TIRADS 定穿刺；Bethesda 定手术；ATA 危险分层定 TSH 抑制目标与 131I 治疗。"},"ddx":[{"name":"甲状腺炎","point":"与本类中甲状腺炎的鉴别：亚急性为弥漫痛性肿 + 摄碘率低，桥本为弥漫低回声 + 抗体高；结节为局灶性，桥本背景结节仍须穿刺。"},{"name":"甲状旁腺功能亢进","point":"结节位于甲状腺后并伴高钙、PTH 升高，应考虑甲状旁腺腺瘤。"},{"name":"多结节性甲状腺肿","point":"多发、大小不一、囊性变混杂，需对最高风险结节分别评级。"},{"name":"甲状腺淋巴瘤","point":"老年桥本、数周内迅速增大，切取活检 + 免疫组化确诊。"},{"name":"颈部淋巴结结核","point":"囊性、伴钙化、结核史，结核相关检查阳性。"}],"tx":{"drug":[{"name":"左甲状腺素（术后 TSH 抑制）","dose":"1.6–1.7 μg/kg/d 起，按危险分层设目标：高危 0.1–0.5、中危/低危 0.5–2.0 mIU/L；长期抑制者 5–10 年后可放宽","note":"良性结节不常规 TSH 抑制（骨质疏松、房颤风险）；每 6–8 周复查 TSH","renal":"遵说明书","hepatic":"遵说明书","interact":"与铁剂钙剂间隔 4 h；增强华法林作用"},{"name":"甲巯咪唑（热结节/毒性结节）","dose":"10–30 mg/d 起，甲功正常后减至 5–10 mg/d，疗程 12–18 个月；或行 131I","note":"用药前查血常规肝功，发热咽痛立即停药查血常规","renal":"遵说明书","hepatic":"遵说明书","interact":"增强华法林抗凝"},{"name":"仑伐替尼（碘难治性分化癌）","dose":"24 mg qd（索拉非尼 400 mg bid 替代）","note":"用于进展性不可手术病例；监测血压、蛋白尿、手足反应；多学科管理","renal":"重度不全慎用","hepatic":"Child-Pugh B/C 减量或禁用","interact":"CYP3A4 强抑制剂/诱导剂影响浓度"}],"nonDrug":["良性结节 >4 cm 或有压迫者手术；囊性可抽吸 + 无水乙醇硬化","PTC/FTC 行甲状腺近全切 + 淋巴结清扫，中高危加 131I 消融","髓样癌全切 + 中央区清扫，术前筛查 RET","热结节可选 131I 或手术"],"life":["良性结节 6–12 个月复查超声，稳定者每 1–2 年","术后 Tg、TgAb、TSH 每 6–12 个月 + 颈部超声","免疫抑制剂量下评估骨密度与心律"]},"prog":"良性结节恶变 <1%。低危 PTC 10 年疾病特异生存 >98%；高危及未分化癌预后差（未分化癌 1 年生存 <20%）。","refs":["《甲状腺结节超声恶性危险分层中国指南（C-TIRADS）》2020","《甲状腺结节和分化型甲状腺癌诊治指南》2023","国家卫健委《甲状腺癌诊疗指南（2022 年版）》","《内科学》第 9 版 第二十二章"]},{"id":"pt_hypopth","name":"甲状旁腺功能减退症","aka":["甲旁减","Hypoparathyroidism"],"rank":3,"basic":{"define":"PTH 分泌不足或作用缺陷所致低钙、高磷血症。最常见于颈部手术后损伤，表现为口周/肢端麻木、手足搐搦、癫痫、QT 延长。","risk":["甲状腺或甲状旁腺术后（永久性约 1%–3%）","颈部放疗、自体移植失败","APS-1、DiGeorge 综合征、CASR 激活突变","镁缺乏"],"epi":"获得性（术后）占 >75%，是甲状腺全切术后最常见并发症；普通人群患病率约 6–37/10 万。"},"patho":"PTH 减少使骨吸收与肾小管钙重吸收下降、尿磷排出减少 → 低钙高磷；神经肌肉兴奋性增高致搐搦、喉痉挛；长期低钙致白内障、基底节钙化、癫痫与 QT 延长。","dx":{"criteria":["校正钙 <2.1 mmol/L（白蛋白校正：实测钙 + 0.02 × (40 − 白蛋白 g/L)）","PTH 低或不适当地正常；血磷 >1.45 mmol/L、尿钙低","血镁 <0.7 mmol/L 提示合并镁缺乏，先补镁","Chvostek/Trousseau 征阳性，QT >440 ms","术后 iCa <1.1 mmol/L 或下降 >0.1 mmol/L 为高风险","术后 >6 个月不恢复为永久性"],"workup":["血钙、离子钙、白蛋白、磷、镁、AKP","PTH、25-OH-D","24 h 尿钙、尿磷","心电图、头颅 CT（基底节钙化）","必要时基因检测（CASR、GCM2、AIRE）"],"grading":"轻度（无症状生化低钙）/ 中重度（反复搐搦、癫痫、心肌痉挛需静脉补钙）。"},"ddx":[{"name":"甲状旁腺功能亢进","point":"与本类中甲状旁腺功能亢进的鉴别：甲旁亢为高钙 + 高 PTH，甲旁减为低钙 + 低/正常 PTH。"},{"name":"维生素 D 缺乏","point":"低钙、低磷、AKP 高、25-OH-D 低、PTH 代偿性升高。"},{"name":"CKD 低钙","point":"eGFR 显著下降、血磷高、继发甲旁亢（PTH 高）。"},{"name":"假性甲旁减","point":"低钙高磷但 PTH 高，伴 Albright 骨营养不良，GNAS 突变。"},{"name":"低镁血症","point":"低镁抑制 PTH 分泌并致靶器官抵抗，补镁后低钙纠正。"}],"tx":{"drug":[{"name":"葡萄糖酸钙（急性低钙静脉）","dose":"10% 葡萄糖酸钙 10–20 mL + 5% 葡萄糖 20 mL 缓推 10–20 min，续以 10% 50–100 mL 加入 500–1000 mL 液体 1–2 h 静滴","note":"避免外渗；洋地黄使用者慎用；同时查镁","renal":"肾功能不全监测钙磷与心电图","hepatic":"遵说明书","interact":"头孢曲松；增强洋地黄毒性"},{"name":"口服钙剂","dose":"元素钙 1–3 g/d（维持 1–1.5 g/d）分次餐后；抑酸时用枸橼酸钙","note":"目标血钙正常低限 2.0–2.1 mmol/L；24 h 尿钙 >6 mmol/d 加噻嗪类","renal":"CKD 慎用，钙磷乘积 <4.4 mg²/dL²","hepatic":"遵说明书","interact":"与 L-T4、铁剂、喹诺酮间隔 2–4 h"},{"name":"骨化三醇","dose":"0.25 μg qd 起，2–4 周滴定至 0.5–1.0 μg/d（维持多 0.5–0.75 μg/d），分 1–2 次","note":"起效快，高钙/高钙尿风险高，每 1–4 周查血钙与尿钙","renal":"肾功能不全减量并监测","hepatic":"遵说明书","interact":"与噻嗪类合用增加高钙风险"},{"name":"维生素 D3 / 阿法骨化醇（辅助）","dose":"D3 400–1000 IU/d（维持 25-OH-D >30 ng/mL）；阿法骨化醇 0.25–1.0 μg/d","note":"1α-羟化受损，以活性 D 为主","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"重组人 PTH（特立帕肽/rhPTH1-84）","dose":"rhPTH(1-84) 50 μg 皮下 q12h 起，按血钙调至 25–100 μg/d；国内可及性有限","note":"用于钙剂 + 活性 D 仍不能维持者，降低尿钙与肾钙化","renal":"重度不全不推荐","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["术中保留或自体移植甲状旁腺","术后第 1 天查 iCa，低者即口服钙 + 骨化三醇","合并低镁者先补镁"],"life":["血钙维持在正常低限，避免肾结石","每 3–6 个月查血钙、磷、镁、24 h 尿钙；每年肾功能、泌尿系超声、骨密度","妊娠期钙与活性 D 需求增加，加强监测"]},"prog":"暂时性术后甲旁减多 6 个月内恢复；永久性者规范替代后生活质量可接近正常，长期高钙尿可致肾钙化。急性重度低钙（喉痉挛、惊厥）可危及生命。","refs":["中华医学会骨质疏松和骨矿盐疾病分会《甲状旁腺功能减退症临床诊疗指南》2018","《内科学》第 9 版 第二十四章","Bilezikian JP, et al. JBMR 2016"]},{"id":"pt_hyperpth","name":"甲状旁腺功能亢进症","aka":["甲旁亢","原发性甲状旁腺功能亢进","PHPT","Hyperparathyroidism"],"rank":4,"basic":{"define":"PTH 分泌过多所致高钙与钙磷代谢异常。原发性（PHPT）多为单腺瘤，继发性（SHPT）见于 CKD 与透析患者，三发性见于肾移植后。","risk":["50–60 岁女性（男女比约 1:3）","颈部放疗史、MEN1/2A、FHH","CKD 4–5 期、长期透析","长期袢利尿剂、锂剂","钙摄入不足 / 长期抑酸"],"epi":"PHPT 是门诊高钙最常见病因（80%–90%）；我国 PHPT 平均年龄约 50 岁，约半数合并结石或骨量减低。SHPT 在透析患者中近乎普遍。"},"patho":"PTH 过量致骨吸收增加、肾钙重吸收增加、磷排泄增加 → 高钙低磷，骨皮质丢失、棕色瘤；高钙尿致结石与肾钙化。SHPT 由低钙、低 1,25-D 与高磷驱动甲状旁腺增生。","dx":{"criteria":["校正钙 >2.6 mmol/L（轻度 2.6–3.0、中度 3.0–3.5、重度 >3.5 或伴症状）","PTH 升高或不适当地正常（排除低钙、D 缺乏与 CKD）","血磷偏低（PHPT）或偏高（SHPT），AKP 可升高","FHH 时 24 h 尿钙低、尿钙/肌酐清除比 <0.01","SHPT：CKD PTH >9 倍上限或持续 >2 倍且上升","手术指征：血钙高于上限 0.25 mmol/L；尿钙 >10 mmol/d；T 值 <−2.5；eGFR <60；年龄 <50 岁；结石或肾钙化"],"workup":["校正钙、离子钙、磷、镁、AKP、PTH","25-OH-D、24 h 尿钙","eGFR、泌尿系超声、DXA（含桡骨 1/3）","颈部超声 + MIBI 或 4D-CT 定位"],"grading":"高钙程度轻/中/重；PHPT 定位（单腺瘤/增生/癌）；SHPT 按 KDIGO 以 PTH、钙、磷分层。"},"ddx":[{"name":"甲状旁腺功能减退","point":"与本类中甲状旁腺功能减退的鉴别：甲旁减为低钙 + 低 PTH，方向相反。"},{"name":"恶性肿瘤高钙（HHM）","point":"PTH 抑制、PTHrP 升高、进展快、消瘦。"},{"name":"家族性低尿钙性高钙（FHH）","point":"轻度高钙、尿钙低、无并发症，不需手术。"},{"name":"药物性高钙","point":"噻嗪类、锂剂、维生素 D 过量，停药后恢复。"},{"name":"多发性骨髓瘤","point":"高钙伴骨痛、贫血、球蛋白异常，PTH 受抑制。"}],"tx":{"drug":[{"name":"西那卡塞（SHPT）","dose":"25–30 mg qd 起，每 3–4 周上调，常用 30–90 mg/d（最大 180 mg/d）","note":"可致低钙，需监测；胃肠反应常见","renal":"透析者按血钙/PTH 滴定","hepatic":"Child-Pugh C 减量","interact":"CYP2D6 抑制剂升高浓度"},{"name":"骨化三醇 / 帕立骨化醇","dose":"骨化三醇 0.25–0.5 μg/d；帕立骨化醇 1–2 μg 透析后静注","note":"监测钙磷与钙磷乘积","renal":"按 KDIGO 调整","hepatic":"遵说明书","interact":"与噻嗪类增加高钙风险"},{"name":"磷结合剂","dose":"碳酸钙元素钙 1–1.5 g/d 餐中；高钙风险时用司维拉姆 800–1600 mg tid 或碳酸镧 750–1500 mg tid","note":"控磷是 SHPT 管理基础","renal":"必须监测钙磷","hepatic":"遵说明书","interact":"司维拉姆与其他药物间隔 1–2 h"},{"name":"高钙危象：补液 + 降钙素 + 双膦酸盐","dose":"生理盐水 200–300 mL/h；鲑降钙素 4 IU/kg 皮下 q12h；唑来膦酸 4 mg 静滴 15 min（无尿者透析）","note":"先补液后双膦酸盐；双膦酸盐 2–4 天起效","renal":"eGFR <30 慎用","hepatic":"遵说明书","interact":"双膦酸盐与造影剂注意肾毒性"}],"nonDrug":["PHPT 首选手术（单侧探查或次全切除 + 自体移植）","SHPT 药物无效者行甲状旁腺次全切除","术后低钙（骨饥饿）3–7 天需补钙 + 活性 D"],"life":["不手术者多饮水 >2 L/d、保证维生素 D、避免噻嗪类与锂剂","每 6–12 个月复查血钙、骨密度、肾功能与泌尿系超声","透析患者控磷、充分透析"]},"prog":"无症状轻度 PHPT 约 20%–25% 在 10 年内出现手术指征，手术治愈率 >95%。SHPT 未控制者心血管钙化与骨折风险显著升高。","refs":["中华医学会骨质疏松和骨矿盐疾病分会《原发性甲状旁腺功能亢进症诊疗指南》2022","《内科学》第 9 版 第二十四章","KDIGO 2017 CKD-MBD"]}]},{"id":"pituitary_water","name":"垂体与水盐代谢","rank":6,"summary":"垂体前叶以靶腺激素替代为核心，顺序先糖皮质激素后甲状腺激素；垂体瘤按分泌类型选药物或手术；尿崩症以去氨加压素为主，须区分中枢性与肾性。","compare":[{"diseaseId":"pit_hypopit","dx":"多轴受累（TSH/ACTH/性腺/IGF-1 低），感染/手术/放疗史，乏力、低钠、低血糖","key":"多轴缺乏 + 影像异常；先补糖皮质激素后补甲状腺素"},{"diseaseId":"pit_acromegaly","dx":"肢端肿大、面容粗大；OGTT 后 GH 谷值 >1 μg/L、IGF-1 升高","key":"OGTT GH 不被抑制 + IGF-1 升高"},{"diseaseId":"pit_prolactinoma","dx":"闭经溢乳 / 性功能减退，PRL 升高（>200 μg/mL 多见于大腺瘤）","key":"PRL >100 μg/mL 高度提示腺瘤"},{"diseaseId":"water_di","dx":"多尿 >3 L/d、尿比重 <1.005、尿渗透压低于血渗透压","key":"禁水试验不能浓缩，加去氨加压素后中枢性可浓缩"}],"diseases":[{"id":"pit_hypopit","name":"腺垂体功能减退症","aka":["垂体前叶功能减退","席汉综合征","Sheehan 综合征","Hypopituitarism"],"rank":1,"basic":{"define":"腺垂体一种或多种激素分泌不足，导致相应靶腺功能减退。最常见于产后大出血缺血（席汉）、垂体肿瘤/术后、放疗与颅咽管瘤。","risk":["产后大出血与休克（席汉）","垂体大腺瘤、垂体卒中、垂体手术或放疗","颅咽管瘤、鞍区放疗、颅脑创伤","自身免疫性垂体炎、免疫检查点抑制剂","空蝶鞍、结核或浸润性疾病"],"epi":"席汉仍是我国女性继发甲减与肾上腺皮质功能减退的重要病因；垂体大腺瘤术后新发垂体功能减退率约 30%–50%。"},"patho":"垂体缺血、压迫或破坏致 ACTH、TSH、LH/FSH、GH、PRL 减少。GH 与性腺轴最易受损，ACTH/TSH 相对较晚；继发甲减、肾上腺皮质功能减退与性腺功能减退，可伴低钠、低血糖、感染耐受力下降。","dx":{"criteria":["继发甲减：TSH 低或正常而 FT4 低","肾上腺轴：晨 8 时皮质醇 <138 nmol/L，ACTH 兴奋试验峰值 <18 μg/dL","性腺轴：LH/FSH 低伴雌二醇/睾酮低；GH 轴：IGF-1 低于年龄匹配下限","产后无乳、闭经、毛发脱落、低钠低血糖","MRI 见空蝶鞍或鞍区占位","免疫检查点相关：用药后 4–12 周乏力、低血压、低钠，ACTH/皮质醇低"],"workup":["晨 8 时皮质醇、ACTH 及兴奋试验","TSH、FT4、PRL","性激素、GH、IGF-1","血钠、血糖","垂体 MRI 增强、视野"],"grading":"按受累轴数：单轴（GH 轴最常见）、双轴、多轴。"},"ddx":[{"name":"肢端肥大症","point":"与本类中肢端肥大症的鉴别：肢大为 GH 过多、IGF-1 高、肢端面容改变；垂体功能减退为多轴缺乏，肢大术后亦可继发。"},{"name":"原发性甲减/原发性肾上腺皮质功能减退","point":"原发者 TSH/ACTH 升高，继发者降低或不适当地正常。"},{"name":"SIADH","point":"垂体功能减退低钠伴低皮质醇，补糖皮质激素后纠正；SIADH 皮质醇正常。"},{"name":"慢性疲劳/重症肌无力","point":"乏力消瘦易误诊，查靶腺激素 + 皮质醇鉴别。"},{"name":"泌乳素瘤","point":"PRL 升高、溢乳，需在多轴评估时同测 PRL。"}],"tx":{"drug":[{"name":"氢化可的松","dose":"15–25 mg/d 分 2–3 次（晨 10–15 mg + 午 5–10 mg）；应激时加量 2–3 倍，手术/重症按应激剂量；强的松替代 5–7.5 mg/d","note":"必须先补糖皮质激素后补甲状腺素，否则诱发肾上腺危象","renal":"遵说明书","hepatic":"遵说明书","interact":"利福平、卡马西平、苯妥英加速代谢需增量"},{"name":"左甲状腺素（继发甲减）","dose":"1.6 μg/kg/d（约 75–100 μg/d）起，老年/冠心病 12.5–25 μg/d 起，每 4–6 周加量；以 FT4 为目标","note":"TSH 不可靠，按 FT4 滴定；须在糖皮质激素充足后加量","renal":"遵说明书","hepatic":"遵说明书","interact":"与钙铁剂间隔 4 h；增强华法林"},{"name":"雌孕激素（女性）","dose":"雌二醇 1–2 mg/d + 周期性孕激素，维持月经与骨量；促生育用促性腺激素","note":"血栓、乳腺癌、子宫肌瘤者慎用","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"CYP3A4 诱导剂降低疗效"},{"name":"睾酮（男性）","dose":"十一酸睾酮 80–160 mg/d 或肌注 200 mg 每 2–4 周（按剂型）","note":"监测红细胞压积（>54% 减量）、肝功、PSA","renal":"遵说明书","hepatic":"定期监测肝功","interact":"增强抗凝药作用"},{"name":"重组人生长激素（成人有指征）","dose":"0.15–0.3 mg/d 皮下起，按 IGF-1 滴定","note":"监测血糖、水肿、关节痛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["垂体大腺瘤经蝶手术后必要时放疗","垂体卒中急诊手术减压 + 大剂量激素","ICI 相关垂体炎以替代治疗为主"],"life":["教育识别肾上腺危象，随身携带氢化可的松 100 mg 应急肌注","定期查 FT4、晨皮质醇、钠与骨密度，每年 MRI"]},"prog":"规范替代后生活质量接近正常；未识别肾上腺皮质功能减退者在感染、手术等应激时可发生危象，死亡率高。","refs":["中华医学会内分泌学分会《腺垂体功能减退症诊治专家共识》2015","《内科学》第 9 版 第二十六章","Endocrine Society 2016 Hormonal Replacement in Hypopituitarism"]},{"id":"pit_acromegaly","name":"肢端肥大症","aka":["Acromegaly","生长激素瘤","GH 瘤"],"rank":2,"basic":{"define":"垂体 GH 腺瘤（或异位 GHRH 分泌）导致 GH 与 IGF-1 长期过量，引起肢端与面部增生、内脏增大与代谢紊乱的慢性疾病。","risk":["垂体 GH 腺瘤（约占垂体瘤 10%）","异位 GHRH 分泌（类癌）、MEN1、McCune-Albright 综合征","30–50 岁，多数为垂体大腺瘤"],"epi":"患病率约 10–20/百万，诊断常延迟 5–10 年，多因面容改变或继发糖尿病、高血压就诊。"},"patho":"GH 与 IGF-1 过量促进软组织与骨骼生长、内脏增大；GH 抗胰岛素致胰岛素抵抗与糖尿病；心肌肥厚与舒张功能不全；气道软组织增生致睡眠呼吸暂停。","dx":{"criteria":["手足增大（鞋码/戒指变紧）、面容粗大（额窦突出、下颌前突、齿间隙增宽）、多汗、声音低沉、头痛、视野缺损、打鼾、关节痛","OGTT 后 GH 谷值不被抑制（<1.0 μg/L 提示缓解，<0.4 μg/L 为严格控制）","IGF-1 高于同年龄性别正常上限","垂体 MRI 增强示腺瘤","并发症筛查：血糖、血压、心超、结肠镜、睡眠监测"],"workup":["GH、IGF-1 及 OGTT","垂体 MRI 增强、视野","OGTT 血糖、HbA1c、血脂","心脏超声、睡眠监测、结肠镜","鞍区无肿瘤时查异位来源"],"grading":"术后 3 个月以 OGTT GH 谷值 + IGF-1 评估缓解；同时评估垂体功能与视野。"},"ddx":[{"name":"腺垂体功能减退症","point":"与本类中腺垂体功能减退的鉴别：肢大 GH/IGF-1 升高、肢端面容改变；减退为激素缺乏、IGF-1 低。"},{"name":"泌乳素瘤","point":"PRL 升高、闭经溢乳；可混合分泌（PRL+GH），需同测 PRL。"},{"name":"生理性面容改变","point":"妊娠、雌激素可使 IGF-1 升高，GH 可被抑制。"},{"name":"厚皮骨膜病","point":"杵状指、骨膜增生但 GH/IGF-1 正常。"},{"name":"甲状腺功能减退","point":"面虚肿、声低但 FT4 低、TSH 高。"}],"tx":{"drug":[{"name":"奥曲肽长效（SSA）","dose":"20 mg 肌注 q4w，按 GH/IGF-1 调至 30–40 mg q4w；短效 100 μg 皮下 q8h 过渡","note":"一线，50%–60% 可生化控制；肝胆结石约 20%、糖耐量改变","renal":"重度不全慎用","hepatic":"遵说明书","interact":"降低环孢素吸收；与降糖药合用需调整"},{"name":"培维索孟（GH 受体拮抗剂）","dose":"负荷 40 mg 皮下，此后 10–20 mg/d，按 IGF-1 调至最大 30 mg/d","note":"仅以 IGF-1 监测；转氨酶 >3 倍停药；国内可及性有限","renal":"遵说明书","hepatic":"肝功异常减量或停药","interact":"注意低血糖"},{"name":"卡麦角林","dose":"0.5 mg 每周 1–2 次起，可增至 1–3.5 mg/周","note":"适用于 PRL/GH 混合瘤；纯 GH 瘤疗效有限","renal":"遵说明书","hepatic":"遵说明书","interact":"大环内酯类、唑类增加浓度"}],"nonDrug":["经蝶手术为首选，术后 3 个月评估缓解","SSA 术前 3–6 个月可缩小大腺瘤、改善呼吸暂停","放疗用于残留或复发，3–5 年起效"],"life":["控制血压、血糖、血脂，治疗睡眠呼吸暂停","每年查 IGF-1，定期心超与结肠镜"]},"prog":"未治疗者心血管死亡率增加 2–3 倍，寿命减少约 10 年；微腺瘤手术治愈率 70%–90%，大腺瘤 <50%，SSA 可控制 50%–60%，控制良好者寿命接近正常。","refs":["中华医学会内分泌学分会《肢端肥大症诊治中国专家共识（2020 版）》","《内科学》第 9 版 第二十六章","Endocrine Society Acromegaly Guideline 2014"]},{"id":"pit_prolactinoma","name":"泌乳素瘤","aka":["催乳素瘤","Prolactinoma"],"rank":3,"basic":{"define":"分泌泌乳素的垂体腺瘤，是最常见的功能性垂体瘤；女性多为微腺瘤，男性多为大腺瘤。多巴胺受体激动剂为一线治疗。","risk":["女性 20–50 岁","MEN1、AIP 突变","长期使用抗精神病药、胃复安、多潘立酮等","原发性甲减、慢性肾衰、妊娠哺乳"],"epi":"女性患病率约 20–50/10 万；女性约 90% 为微腺瘤（<1 cm），男性以大腺瘤为主。"},"patho":"PRL 升高抑制 GnRH 节律，致 LH/FSH 与雌二醇/睾酮不足，出现闭经、溢乳、性功能减退与不育；大腺瘤压迫视交叉（双颞侧偏盲）与正常垂体。","dx":{"criteria":["女性闭经、溢乳、不孕；男性性欲减退、阳痿、乳房发育","PRL >25 ng/mL 为高 PRL；>100 高度提示腺瘤；>200 几乎肯定大腺瘤（巨腺瘤效应需稀释复核）","垂体 MRI 增强确诊并评估大小与侵犯","先排除药物、甲减、肾衰、妊娠","大腺瘤加查视野"],"workup":["PRL（必要时稀释）、TSH、FT4","LH、FSH、雌二醇或睾酮","垂体 MRI 增强、视野","用药史与妊娠史"],"grading":"微腺瘤（<10 mm）与大腺瘤（≥10 mm）；Knosp 分级评估海绵窦侵犯。"},"ddx":[{"name":"肢端肥大症","point":"与本类中肢端肥大症的鉴别：肢大 GH/IGF-1 升高、肢端面容改变；可共存于 PRL/GH 混合瘤。"},{"name":"无功能垂体腺瘤（垂体柄效应）","point":"PRL 轻中度升高（多 <100 ng/mL），大腺瘤而 PRL 显著升高者应考虑泌乳素瘤。"},{"name":"药物性高 PRL","point":"抗精神病药/促动力药史，MRI 无腺瘤，停药后下降。"},{"name":"原发性甲减","point":"TSH 高、FT4 低，补 L-T4 后 PRL 下降。"},{"name":"腺垂体功能减退","point":"多轴受累、PRL 降低，与泌乳素瘤相反。"}],"tx":{"drug":[{"name":"溴隐亭","dose":"1.25 mg 睡前起，渐增至 2.5–7.5 mg/d 分次（常 2.5 mg tid），最大 15 mg/d，餐后服","note":"恶心、头晕、体位性低血压；70%–80% 微腺瘤可 PRL 正常化并缩小肿瘤","renal":"重度不全慎用","hepatic":"肝功能不全减量","interact":"大环内酯类、唑类升高浓度"},{"name":"卡麦角林（一线）","dose":"0.25–0.5 mg，每周 1–2 次起，常用 0.5–2 mg/周（最大 2 mg/周）","note":"耐受性优于溴隐亭，80%–90% 正常化；常规剂量瓣膜风险低，仍建议定期心超","renal":"遵说明书","hepatic":"重度肝功不全减量","interact":"红霉素、伊曲康唑增加浓度"}],"nonDrug":["经蝶手术：药物无效或不耐受、进行性增大压迫视野、囊性/出血性肿瘤","大腺瘤急性压迫或卒中急诊手术","放疗用于药物与手术失败者，3–5 年起效","妊娠期多数停药，出现头痛/视力下降复查 MRI"],"life":["每 3–6 个月查 PRL，稳定后每年；每 1–2 年 MRI","服药初期注意体位性低血压，避免突然起身"]},"prog":"微腺瘤进展为大腺瘤仅 5%–10%。药物可使 80%–90% PRL 正常化、约 70% 大腺瘤缩小 >50%；停药后复发 30%–50%，长期控制者死亡率接近正常。","refs":["中华医学会内分泌学分会《垂体瘤诊治专家共识》2016","《内科学》第 9 版 第二十六章","Endocrine Society Hyperprolactinemia Guideline 2011"]},{"id":"water_di","name":"尿崩症","aka":["中枢性尿崩症","肾性尿崩症","Diabetes Insipidus","CDI","NDI"],"rank":4,"basic":{"define":"因抗利尿激素分泌不足（中枢性）或肾脏对其反应缺陷（肾性）致尿液不能浓缩，表现为多尿（成人 >3 L/d，可 10–20 L/d）、多饮与低渗尿。","risk":["颅咽管瘤、生殖细胞瘤、经蝶手术后（暂时性 1%–5%）","颅脑外伤、放射性损伤、自身免疫性下丘脑炎","锂剂、去甲金霉素、两性霉素 B、顺铂","AVP、AVPR2、AQP2 基因突变","高钙或低钾血症、慢性肾病"],"epi":"患病率约 3/10 万；术后暂时性尿崩多数 1–3 周恢复。"},"patho":"AVP 减少或集合管 AVPR2/AQP2 缺陷 → 集合管水通透性下降 → 大量低渗尿与高血渗；渴觉受损或意识障碍者无法饮水，迅速出现高钠血症。","dx":{"criteria":["多尿 >3 L/d，尿比重 <1.005、尿渗透压 <200 mOsm/kg，血渗透压正常或偏高","禁水试验（6–8 h 或至体重下降 3%）：尿不能浓缩；注射去氨加压素后中枢性尿渗透压升高 >50%，肾性无反应","查血钠、血渗透压、血糖、血钙、血钾","头颅 MRI 增强（垂体柄增粗提示肿瘤或组织细胞增生症）","原发性多饮：禁水后可浓缩、血钠偏低"],"workup":["24 h 尿量、尿比重与渗透压；血渗透压、血钠、血糖","禁水-加压素试验（住院监护）","垂体 MRI 与垂体前叶功能","用药史、电解质、必要时基因检测"],"grading":"轻度（<5 L/d）/中重度（>5 L/d）/完全性；中枢性、肾性、原发性多饮。"},"ddx":[{"name":"腺垂体功能减退症","point":"与本类中腺垂体功能减退的鉴别：尿崩为神经垂体受累，二者可共存（垂体术后）；单纯前叶减退无多尿。"},{"name":"糖尿病渗透性利尿","point":"血糖高、尿糖阳性，尿比重可偏正常。"},{"name":"原发性多饮","point":"尿量随饮水波动、血钠偏低、禁水后尿可浓缩。"},{"name":"高钙或低钾血症多尿","point":"查血钙、血钾即可鉴别，纠正后缓解。"},{"name":"渗透性利尿（甘露醇、大量蛋白尿）","point":"尿渗透压不低，用药史与尿蛋白可鉴别。"}],"tx":{"drug":[{"name":"去氨加压素（中枢性）","dose":"片剂 0.1–0.2 mg 口服 2–3 次/d；鼻喷 10–20 μg/d 分 2 次；长效皮下/肌注 1–4 μg 每 1–2 天（遵说明书，儿童按体重减量）","note":"限水防低钠血症，每 3–6 个月查血钠；术后暂时者可 1–5 μg 皮下 q8–12h 过渡","renal":"肾功能不全慎用（低钠风险）","hepatic":"遵说明书","interact":"三环类、卡马西平、NSAIDs 增强抗利尿作用"},{"name":"氢氯噻嗪（肾性）","dose":"25–50 mg/d 分次，联合低钠饮食（<2 g/d 钠）与阿米洛利 5–10 mg/d","note":"可减少尿量 30%–50%；监测血钾、血钠、尿酸","renal":"eGFR <30 疗效差","hepatic":"遵说明书","interact":"与去氨加压素合用加重低钠"},{"name":"吲哚美辛（肾性辅助）","dose":"25 mg bid–tid，短疗程与噻嗪类联用","note":"消化道与肾脏风险，严格短期使用","renal":"eGFR <60 慎用","hepatic":"遵说明书","interact":"与锂剂合用增加中毒"},{"name":"卡马西平/氯磺丙脲（部分性中枢性，备选）","dose":"卡马西平 100–200 mg bid–tid；氯磺丙脲 125–250 mg qd（老年慎用）","note":"疗效不如去氨加压素；注意低钠与低血糖","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"卡马西平为 CYP3A4 诱导剂"}],"nonDrug":["术后每小时监测尿量与血钠，尿量 >200 mL/h 且比重 <1.005 时开始去氨加压素","高钠血症伴意识障碍：缓慢纠钠（<10 mmol/L/24h）","肾性者低钠低蛋白饮食、充足饮水","垂体/下丘脑肿瘤按原发病处理"],"life":["随时可饮水，运动出汗时调量并测体重","随身携带医疗卡","规范限水，出现头痛、恶心、嗜睡立即查血钠"]},"prog":"中枢性尿崩多需终身替代，生活质量良好；术后暂时性者 1–3 个月恢复。主要风险为低钠血症与脱水/高钠血症。","refs":["中华医学会内分泌学分会《尿崩症诊治专家共识》2019","《内科学》第 9 版 第二十六章","Verbalis JG. Diabetes Insipidus. N Engl J Med 2019"]}]},{"id":"adrenal_more","name":"肾上腺其他疾病","rank":7,"summary":"肾上腺皮质功能减退的关键是「想到它」——低钠、低血压、色素沉着、乏力食欲差；一旦疑肾上腺危象，先抽血再立即给氢化可的松，不等结果。先天性肾上腺皮质增生症以 21-羟化酶缺乏为主，新生儿失盐型可致命。","compare":[{"diseaseId":"ad_addison","dx":"乏力、食欲减退、体重下降、低血压、低钠高钾、皮肤黏膜色素沉着；ACTH 兴奋试验皮质醇反应低下，血 ACTH 升高","key":"色素沉着 + 低钠高钾 + ACTH 升高是原发性特征；继发性者无色素沉着且 ACTH 低"},{"diseaseId":"ad_cah","dx":"新生儿期失盐危象（低钠、高钾、脱水、休克），或女性外生殖器男性化；17-OHP 显著升高","key":"新生儿失盐 + 外生殖器异常 + 17-OHP 升高；需与失盐性肾病鉴别"}],"diseases":[{"id":"ad_addison","name":"肾上腺皮质功能减退","aka":["Adrenal Insufficiency","Addison 病","原发性肾上腺皮质功能减退","肾上腺危象"],"rank":1,"basic":{"define":"肾上腺皮质分泌糖皮质激素（皮质醇）与盐皮质激素（醛固酮）不足所致的临床综合征。按病因分原发性（肾上腺本身破坏，Addison 病，ACTH 升高）与继发性（垂体或下丘脑病变致 ACTH 不足）。肾上腺危象是危及生命的急性失代偿状态。","risk":["**自身免疫性肾上腺炎（发达国家最常见，常合并其他自身免疫病——1 型/2 型 APS）**","**结核（我国及发展中国家的重要病因）**","双侧肾上腺出血（抗磷脂综合征、严重感染、抗凝治疗）","双侧肾上腺切除或肿瘤转移","长期糖皮质激素治疗后骤停（继发性）","垂体瘤、垂体手术或放疗、席汉综合征（继发性）","药物：酮康唑、依托咪酯、免疫检查点抑制剂"],"epi":"原发性肾上腺皮质功能减退的患病率约 4–11/10 万，女性略多，发病高峰 30–50 岁。我国结核所致者仍占相当比例。**肾上腺危象的病死率约 5%–10%（延误治疗者更高）。**"},"patho":"皮质醇缺乏导致：糖异生减少（低血糖）、血管对儿茶酚胺反应性下降（低血压、休克）、钠水排泄增加（低钠）、食欲与应激耐受力下降。**原发性者醛固酮同时缺乏**，导致更严重的低钠高钾、代谢性酸中毒与容量不足；同时因皮质醇对垂体的负反馈消失，ACTH（及黑素细胞刺激素 MSH）显著升高，造成皮肤黏膜色素沉着（牙龈、乳晕、瘢痕、掌纹）。继发性者醛固酮多正常（RAAS 完整），故高钾与酸中毒较轻、无色素沉着，但可伴其他垂体激素缺乏表现。","dx":{"criteria":["**慢性表现**：进行性乏力、食欲减退、体重下降、恶心呕吐、腹痛、低血压（尤其体位性）、低血糖、低钠、高钾、嗜盐","**色素沉着（原发性特有）**：暴露部位、摩擦部位、瘢痕、乳晕、牙龈、口腔黏膜","**实验室**：低血钠、高血钾、血尿素氮升高（肾前性）、轻度代谢性酸中毒、嗜酸性粒细胞增多、正细胞性贫血","**确诊试验——促肾上腺皮质激素（ACTH）兴奋试验**：静脉或肌注合成 ACTH 250 µg（或 1 µg 低剂量）后 30、60 分钟测皮质醇；**峰值皮质醇 <500 nmol/L（18 µg/dL）提示肾上腺皮质功能减退**","**基线激素**：晨间（8 时）皮质醇 <83 nmol/L 高度提示，>414 nmol/L 可基本排除；**血 ACTH 升高**提示原发性（继发性者降低或正常）","**肾上腺危象诊断**：已知或疑肾上腺功能减退者出现**低血压/休克 + 低钠 + 高钾 + 低血糖 + 不明原因发热**，且不能以其他原因解释"],"workup":["血清电解质、血糖、血尿素氮与肌酐、血气（酸中毒）、血常规","**晨间血皮质醇（8 时）与血 ACTH**","**ACTH 兴奋试验（确诊金标准，疑危象时不等待结果即开始治疗）**","醛固酮与肾素（原发性者醛固酮低、肾素高）","**自身抗体：21-羟化酶抗体（排除自身免疫性病因）**、甲状腺抗体、胰岛细胞抗体","**肾上腺 CT**（排除出血、结核、转移瘤、浸润性病变）","结核筛查（胸片、IGRA、必要时肾上腺活检）","头颅 MRI（疑继发性，评估垂体与下丘脑）","其他垂体激素评估（继发性者：TSH、LH/FSH、GH、ADH）"],"grading":"按病因分：原发性（Addison 病，ACTH 高）、继发性（ACTH 低）、三发性（下丘脑 CRH 不足）。按临床分：慢性（代偿期）、急性（肾上腺危象）。按严重度分：部分缺乏与完全缺乏（ACTH 兴奋试验峰值）。"},"ddx":[{"name":"先天性肾上腺皮质增生症（ad_cah）","point":"与 CAH 的鉴别：CAH 多于新生儿或儿童期发病，伴外生殖器异常或男性化，**17-OHP 显著升高**、雄激素升高；成人 Addison 病无男性化表现，21-羟化酶抗体可阳性。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"**表现相反**：原醛为高血压 + 低血钾（容量扩张、肾素受抑制）；肾上腺皮质功能减退为低血压 + 低钠高钾（容量不足、肾素升高）。"},{"name":"库欣综合征（ad_cushing）","point":"**表现相反**：库欣为皮质醇过多（向心性肥胖、紫纹、高血压、高血糖）；减退为皮质醇缺乏（消瘦、低血压、低血糖）。"},{"name":"嗜铬细胞瘤（ad_pheo）","point":"嗜铬细胞瘤为阵发性高血压、心悸与大汗，尿甲氧基肾上腺素升高；与低血压、低钠的肾上腺皮质功能减退相反。"},{"name":"低钠血症的其他原因","point":"SIADH（血容量正常、尿钠高、无脱水）、心力衰竭与肝硬化（有相应临床背景）；肾上腺皮质功能减退有**高血钾与容量不足**，ACTH 兴奋试验可鉴别。"},{"name":"慢性肾病（ckd_stage）","point":"有蛋白尿、肾萎缩、明显尿毒症表现；虽然也可有低钠高钾，但 ACTH-皮质醇轴正常。"},{"name":"抑郁症/慢性疲劳综合征","point":"乏力与食欲差但电解质正常、ACTH 兴奋试验正常、无色素沉着。"}],"tx":{"drug":[{"name":"氢化可的松（生理替代）","dose":"**15–25 mg/d 分 2–3 次**（晨起 10–15 mg、午后 5–10 mg，尽量模拟生理节律）；**应激时需增量**（轻中度应激 2–3 倍，重大手术/严重感染 5–10 倍）","note":"**首选氢化可的松**（与内源性皮质醇等效，便于按生理剂量调整）；需患者随身携带«应激剂量»说明卡；过量致体重增加、骨质疏松、高血糖","renal":"无需调整","hepatic":"肝病者监测","interact":"与利福平、苯妥英、卡马西平合用加速代谢（需增量）；与酮康唑合用抑制合成"},{"name":"氢化可的松（肾上腺危象抢救）","dose":"**首剂 100 mg 静脉推注**，随后 50–100 mg q6h 静脉或持续输注 200 mg/24h；危象缓解后逐渐减量","note":"**疑肾上腺危象立即给药，不等化验结果**（先抽血送检皮质醇与 ACTH，但不延迟治疗）；同时补充生理盐水（1 L/h 起始）与葡萄糖","renal":"无需调整","hepatic":"监测","interact":"同氢化可的松"},{"name":"氟氢可的松（原发性盐皮质激素替代）","dose":"0.05–0.2 mg qd 口服（晨起），按血压、血钠、血钾与水肿调整","note":"**原发性和双侧肾上腺切除者需要**（继发性者通常不需）；需监测血压、水肿与低血钾；可与食物同服减少胃部不适","renal":"肾功能不全者慎用（水肿与高血压）","hepatic":"肝病者监测","interact":"与排钾利尿剂合用增加低钾；与抗凝剂合用增强抗凝"},{"name":"泼尼松 / 地塞米松（替代选择）","dose":"泼尼松 3–5 mg/d（抗炎等效但盐皮质激素作用弱）；地塞米松 0.25–0.5 mg/d（无盐皮质激素活性）","note":"用于不能耐受氢化可的松或需减少服药次数者；**原发性者用泼尼松/地塞米松时需加用氟氢可的松**","renal":"无需调整","hepatic":"监测","interact":"与利福平、苯妥英合用加速代谢"},{"name":"葡萄糖与氯化钠（危象支持）","dose":"0.9% 氯化钠 1 L 首小时内快速输注，随后按血压与尿量调整；低血糖时 50% 葡萄糖 50 mL 静脉推注后持续输注（5%–10% 葡萄糖）","note":"**危象的两大核心是补液与糖皮质激素**；补液可纠正低血压、低钠与容量不足；需监测血糖（糖皮质激素可加重高血糖）","renal":"心衰或肾功能不全者缓慢输注并监测","hepatic":"无需调整","interact":"无特殊"},{"name":"氢化可的松口服（危象后过渡）","dose":"危象控制后（通常 24–72 小时）改为口服，逐渐减至维持量（15–25 mg/d）","note":"减量需缓慢（避免反弹）；同时评估并调整氟氢可的松剂量","renal":"无需调整","hepatic":"监测","interact":"同氢化可的松"}],"nonDrug":["**患者教育是治疗成败的关键**：识别应激情况、掌握应激剂量调整、随身携带急救卡与氢化可的松注射剂","**「病假日规则」**：发热、呕吐、腹泻、创伤、手术时激素需翻倍或增加 50%，不可停用","**呕吐无法口服时立即肌注或静脉给氢化可的松**","避免诱发危象的因素：感染、脱水、突然停药、双侧肾上腺手术","合并自身免疫病者需同步筛查（甲状腺、糖尿病、恶性贫血）","结核所致者需完成抗结核治疗"],"life":["**随身携带疾病卡/急救套件**（含氢化可的松 100 mg 注射剂、注射器与说明）","**避免自行停药**（骤然停药可致危象）","大量出汗或高温作业时增加盐摄入与氟氢可的松剂量","定期随访（每 3–6 个月）：电解质、血压、体重与症状；每年评估骨密度","妊娠期激素需求增加（孕晚期可增加 50%），需专科管理","避免使用酮康唑、依托咪酯等抑制皮质醇合成的药物"]},"prog":"规范替代治疗后预期寿命接近正常。**主要死亡风险是肾上腺危象（漏诊或患者未按应激剂量调整）**，一旦发生需立即抢救。约 1/3 的肾上腺危象需住院。合并自身免疫病者需长期随访其他内分泌腺功能。继发性者的预后取决于垂体病变本身。","refs":["《内科学》第 9 版（人民卫生出版社）肾上腺疾病章","2016 Endocrine Society Clinical Practice Guideline: Diagnosis and Treatment of Primary Adrenal Insufficiency","2020 EJE/ESE Guidelines on the Management of Adrenal Crisis in Adults","《中国肾上腺皮质功能减退症诊治专家共识》"]},{"id":"ad_cah","name":"先天性肾上腺皮质增生症","aka":["Congenital Adrenal Hyperplasia","CAH","21-羟化酶缺乏症"],"rank":2,"basic":{"define":"肾上腺皮质激素合成通路上某种酶的遗传性缺陷导致的疾病，最常见为 **21-羟化酶（CYP21A2）缺乏症（占 90% 以上）**，致皮质醇合成减少、ACTH 代偿性升高与肾上腺皮质增生的同时，雄激素合成过多。","risk":["**常染色体隐性遗传（CYP21A2 基因突变）**","**父母为携带者（每次妊娠患病风险 1/4）**","同胞患病","新生儿筛查（17-OHP）可早期发现"],"epi":"经典型 CAH 的发病率约 1/15000–1/16000 活产（21-羟化酶缺乏），我国已纳入新生儿筛查。非经典型（轻型）在普通人群中可达 1/200–1/1000，多为女性多毛或月经异常时才被发现。"},"patho":"21-羟化酶将 17-羟孕酮（17-OHP）转化为 11-脱氧皮质醇。酶活性降低时：① 皮质醇合成不足 → ACTH 升高 → 肾上腺皮质增生；② 前体物质（17-OHP、孕酮）堆积并被转向雄激素通路 → 脱氢表雄酮（DHEA）、雄烯二酮与睾酮升高。**按酶活性残留程度分三型**：失盐型（酶活性 <1%，醛固酮也缺乏，新生期失盐危象）、单纯男性化型（1%–2%，皮质醇不足但醛固酮尚可）、非经典型（20%–50%，无症状或轻型）。女性胎儿的雄激素过多导致外生殖器男性化（阴蒂肥大、阴唇融合）。","dx":{"criteria":["**新生儿期**：女性外生殖器性别不明/男性化（阴蒂肥大、大阴唇融合）；男性外生殖器正常（易被忽略），**失盐型在生后 1–4 周出现低钠、高钾、脱水、休克**","**实验室（关键）**：**17-羟孕酮（17-OHP）显著升高**（经典型 >100 nmol/L，失盐型可达 >300 nmol/L）；雄烯二酮与睾酮升高；肾素活性升高（失盐型）、醛固酮降低；血钠低、血钾高、代谢性酸中毒","**确诊——ACTH 兴奋试验（250 µg）后 17-OHP 反应**：经典型 >300 nmol/L；非经典型反应至 30–300 nmol/L","**基因检测（CYP21A2）**：确诊、分型与产前诊断/携带者筛查","新生儿筛查：干血片 17-OHP 升高（需注意早产与应激假阳性）","**电解质与肾素**（失盐型的紧迫监测）","影像：肾上腺 CT/超声（双侧增生，排除肿瘤）","**核型与超声**（外生殖器不明时确认性别）"],"workup":["**血清电解质、血糖、血气**（失盐危象评估）","**17-羟孕酮（17-OHP）**、雄烯二酮、睾酮、DHEAS","**醛固酮与肾素活性**（失盐型者醛固酮低、肾素高）","**ACTH 兴奋试验（确诊与分型）**","**CYP21A2 基因检测**（确诊、分型、产前诊断）","肾上腺超声/CT（评估增生程度）","**染色体核型与盆腔超声**（外生殖器性别不明时）","骨龄（儿童期雄激素过多致骨龄提前）"],"grading":"按 21-羟化酶活性分：**经典型失盐型（SW，酶活性 <1%，最重）**、**经典型单纯男性化型（SV，1%–2%）**、**非经典型（NC，20%–50%，轻型）**。按临床表现分：新生儿失盐危象、女性外生殖器男性化、儿童期假性性早熟、成年女性多毛与月经异常。"},"ddx":[{"name":"肾上腺皮质功能减退（ad_addison）","point":"与 Addison 病的鉴别：Addison 病**无雄激素过多表现**（无男性化或性早熟）、17-OHP 正常或轻度升高、21-羟化酶抗体可阳性；CAH 的 17-OHP 显著升高且伴雄激素过多。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"**表现相反**：原醛为高血压 + 低钾（容量扩张）；CAH 失盐型为低血压 + 低钠高钾（容量不足）。"},{"name":"库欣综合征（ad_cushing）","point":"皮质醇过多表现（肥胖、紫纹、高血压）；CAH 为皮质醇合成不足。"},{"name":"失盐性肾病与其他原因的新生儿低钠高钾","point":"早产、尿路梗阻、假性醛固酮减少症（PHA）也可致低钠高钾，但 17-OHP 正常、无外生殖器异常。"},{"name":"性早熟（ped_short_stature 相关）","point":"特发性中枢性性早熟者 GnRH 依赖、17-OHP 正常；CAH 所致为**假性性早熟**（GnRH 非依赖、17-OHP 高、骨龄明显提前）。"},{"name":"雄激素分泌肿瘤（肾上腺或卵巢）","point":"起病急、雄激素显著升高而 17-OHP 不高，影像见单侧肿块；CAH 为双侧增生伴 17-OHP 高。"},{"name":"外生殖器性别不明（其他原因）","point":"46,XY 的雄激素不敏感综合征或 5α-还原酶缺乏，17-OHP 正常、核型不同。"}],"tx":{"drug":[{"name":"氢化可的松（糖皮质激素替代）","dose":"儿童 **10–15 mg/(m²·d) 分 3 次**（婴儿可增加至 15–20，按生长与 17-OHP 滴定）；成人 15–25 mg/d 分 2–3 次","note":"**儿童必须用氢化可的松**（不用长效制剂，以免抑制生长）；目标是维持正常生长速度、骨龄进展与 17-OHP 在可接受范围（不应完全抑制）；**失盐危象时用大剂量（见抢救条目）**","renal":"无需调整","hepatic":"监测","interact":"与利福平、苯妥英、卡马西平合用加速代谢（需增量）"},{"name":"氟氢可的松（盐皮质激素替代）","dose":"婴儿 **0.1–0.2 mg/d**，儿童 0.05–0.1 mg/d，按血压、血钠、血钾与肾素活性调整","note":"**失盐型必需**；需监测血压与水肿、血钾。单纯男性化型与重症者也需要","renal":"肾功能不全慎用","hepatic":"监测","interact":"与排钾利尿剂合用增加低钾"},{"name":"氯化钠补充（新生儿失盐型）","dose":"元素钠 1–3 mmol/(kg·d) 分次（母乳含钠低，需额外补）；脱水休克时用 0.9% 生理盐水 10–20 mL/kg 扩容","note":"新生儿失盐型的常规补充（婴儿期需要，随辅食添加逐渐减少）；**危象时先扩容再给激素**","renal":"无","hepatic":"无","interact":"无特殊"},{"name":"氢化可的松（肾上腺危象抢救）","dose":"**首剂 50–100 mg/m² 静脉推注**（或按年龄：婴儿 25 mg、幼儿 50 mg、较大儿童 100 mg），随后 50–100 mg/m²/d 持续输注或分次","note":"**疑失盐危象立即给药**；同时扩容（生理盐水 10–20 mL/kg，必要时重复）与补糖","renal":"无需调整","hepatic":"监测","interact":"同氢化可的松"},{"name":"促性腺激素释放激素类似物（中枢性性早熟并发症）","dose":"亮丙瑞林 3.75 mg 肌注每 4 周（遵方案）","note":"用于长期雄激素控制不佳、骨龄快速进展导致中枢性（GnRH 依赖性）性早熟者；需监测骨龄与生长","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"无特殊"},{"name":"抗雄激素治疗（成年女性非经典型）","dose":"螺内酯 50–100 mg bid、或氟他胺（按专科方案）；联合口服避孕药调节月经","note":"非经典型 CAH 女性以多毛、痤疮与月经不规则为主要表现；糖皮质激素在成人非经典型中的获益有限","renal":"螺内酯在肾功能不全慎用（高钾）","hepatic":"肝病者慎用","interact":"螺内酯与 ACEI/ARB 合用致高钾"}],"nonDrug":["**新生儿筛查与产前诊断**：有家族史者可做 CYP21A2 基因检测与产前治疗评估","**女性外生殖器矫形手术**：争议较大（国际共识建议推迟至患者可参与决策的年龄，仅在功能受限时早期手术）","**性别认定与心理支持**：需多学科团队（内分泌、小儿外科、心理）协作","**生盐型婴儿期需监测生长、电解质与肾素活性**（频繁随访）","**成年期生育咨询**（女性可正常生育但需专科管理，阴道狭窄者需评估）","骨龄与终身高管理（避免过度激素抑制或不足）"],"life":["**终身激素替代**（不可自行停药或减量）","**应激剂量教育**（发热、手术、创伤时增量，呕吐时注射给药）","随身携带急救卡与氢化可的松注射剂","定期随访：儿童每 3 个月（生长、骨龄、17-OHP、电解质）；成人每 6 个月","性心理与生育咨询（女性患者生育率低于常人但多数可妊娠）","避免使用糖皮质激素以外的雄激素或促雄激素制剂"]},"prog":"规范替代治疗后大多数患者可获得正常生长与发育，成年身高可达遗传靶身高范围（轻至中度受限）。**失盐型若未及时诊断，病死率高（新生儿期）**。长期激素过量可致矮身材与骨质疏松；不足则致男性化进展与骨龄提前。成年期生育率下降（尤其女性），心血管代谢风险（肥胖、胰岛素抵抗）轻度升高。","refs":["《先天性肾上腺皮质增生症诊治专家共识》（中华医学会儿科学分会内分泌遗传代谢学组，2016）","2018 Endocrine Society Clinical Practice Guideline: Congenital Adrenal Hyperplasia Due to Steroid 21-Hydroxylase Deficiency","2020 International Consensus on Prenatal and Neonatal Screening for CAH","《中国新生儿疾病筛查技术规范（2010）》"]}]},{"id":"metabolic_more","name":"其他代谢性疾病","rank":8,"summary":"低血糖诊断靠 Whipple 三联征（症状 + 低血糖 + 纠正后缓解），关键在「发作时抽血」而非「平时抽血」；肥胖症的治疗门槛是 BMI 与合并症共同决定，代谢手术需符合指征。","compare":[{"diseaseId":"met_hypoglycemia","dx":"出现交感神经（心悸、出汗、震颤）与神经低血糖（意识模糊、行为异常、抽搐）症状，发作时血糖 <2.8 mmol/L（或糖尿病者 <3.9），纠正后症状缓解","key":"Whipple 三联征；**必须在发作时抽血**（血糖、胰岛素、C 肽、β-羟丁酸、磺脲类筛查）"},{"diseaseId":"met_obesity","dx":"BMI ≥28 kg/m²（中国标准）或 ≥30（WHO），伴腰围增大、代谢异常（血糖、血脂、血压）","key":"BMI 分层 + 合并症决定干预强度；BMI ≥32.5 且合并 T2DM 可考虑代谢手术"}],"diseases":[{"id":"met_hypoglycemia","name":"低血糖症","aka":["Hypoglycemia","低血糖","Whipple 三联征"],"rank":1,"basic":{"define":"由多种原因引起的血糖浓度过低（**非糖尿病成人 <2.8 mmol/L；糖尿病患者 ≤3.9 mmol/L**）所致的临床综合征，以交感神经兴奋与中枢神经系统功能障碍为主要表现。严重低血糖可致昏迷、抽搐与永久性脑损伤。","risk":["**糖尿病治疗（胰岛素、磺脲类、格列奈类）——最常见原因**","进食不足、饮酒（抑制糖异生）、剧烈运动","肝衰竭（糖原储备与糖异生障碍）","肾功能不全（胰岛素清除下降）","胰岛素瘤与其他神经内分泌肿瘤","肾上腺皮质功能减退、垂体功能减退","脓毒症、营养不良、妊娠、胃旁路术后（反应性低血糖）"],"epi":"胰岛素瘤的年发病率约 1/100 万（罕见但为内源性低血糖的最常见原因）。糖尿病患者中严重低血糖（需他人协助）的发生率约 1%–3%/年（强化治疗者更高）。"},"patho":"血糖下降时，机体首先抑制胰岛素分泌、增加胰高血糖素与肾上腺素分泌（交感反应，血糖约 3.6–3.9 mmol/L 启动），随后出现神经低血糖症状（血糖 <2.8–3.0 mmol/L）。**反复低血糖会损害低血糖反向调节（HAAF，hypoglycemia-associated autonomic failure）**，使交感警示症状消失、患者不能感知低血糖（「无感知性低血糖」），形成恶性循环。胰岛素瘤的胰岛素分泌不受低血糖抑制，导致空腹低血糖。大脑葡萄糖储备有限，持续严重低血糖可致神经元坏死（皮层、海马）。","dx":{"criteria":["**Whipple 三联征（诊断的必要条件）**：① 有低血糖症状（交感：心悸、出汗、震颤、饥饿、焦虑；神经低血糖：意识模糊、行为异常、视物模糊、抽搐、昏迷）；② **发作时测得低血糖**（非糖尿病者 <2.8 mmol/L，糖尿病者 ≤3.9 mmol/L）；③ 纠正血糖后症状缓解","**关键原则：必须在症状发作时抽血**（血糖、胰岛素、C 肽、β-羟丁酸、磺脲类药物筛查），症状缓解后的化验无法诊断","**疑胰岛素瘤时的 72 小时饥饿试验**（住院条件下）：出现症状且血糖 <2.8 mmol/L 时，**胰岛素 ≥3 µU/mL、C 肽 ≥0.6 ng/mL、β-羟丁酸 ≤2.7 mmol/L** 提示内源性胰岛素过多","**区分内源性与外源性**：外源性胰岛素使用者胰岛素高而 C 肽低（C 肽抑制）；磺脲类中毒者两者均高","糖尿病患者的低血糖分级：**1 级（<3.9 mmol/L）、2 级（<3.0 mmol/L）、3 级（严重，需他人协助）**","排除其他：肾上腺皮质功能减退（ACTH 兴奋试验）、垂体功能减退、肝肾功能衰竭"],"workup":["**发作时（关键）**：血糖、胰岛素、C 肽、β-羟丁酸、胰岛素抗体","**磺脲类药物血/尿筛查**（常用药者）","**72 小时饥饿试验**（疑胰岛素瘤，需在住院监测下）","肝肾功能、皮质醇与 ACTH（排除肾上腺/垂体功能减退）","**腹部 CT/MRI、内镜超声**（胰岛素瘤定位）","选择性动脉钙刺激试验（ASVS，定位困难时）","糖尿病者：评估降糖方案、肾功能、饮食与自我监测依从性","胃旁路术后与反应性低血糖：混合餐试验与血糖曲线"],"grading":"糖尿病者按美国糖尿病协会分级：1 级（<3.9 mmol/L，可自行处理）、2 级（<3.0 mmol/L，可自行处理）、3 级（严重，需他人协助）。非糖尿病者按病因分：空腹低血糖（胰岛素瘤、肝病、肾上腺功能减退）与餐后（反应性）低血糖。"},"ddx":[{"name":"肥胖症（met_obesity）","point":"与肥胖症的鉴别：肥胖症本身不引起低血糖（但胃旁路术后可致反应性低血糖）；表现为体重增加与代谢异常。"},{"name":"糖尿病酮症酸中毒（dm_dka）","point":"**表现相反**：DKA 为高血糖（>13.9 mmol/L）+ 酮症 + 酸中毒；低血糖为血糖过低，且**治疗 DKA 过程中可能出现低血糖（需监测）**。"},{"name":"肾上腺皮质功能减退（ad_addison）","point":"可与低血糖并存（皮质醇缺乏致糖异生减少），但伴低钠、高钾、色素沉着；需 ACTH 兴奋试验确认。"},{"name":"自主神经功能异常（惊恐发作）","point":"惊恐发作有交感症状（心悸、出汗）但血糖正常；低血糖的出汗多伴饥饿与意识改变。"},{"name":"脑血管事件（TIA/卒中）","point":"局灶神经缺损、血糖正常；低血糖可模拟卒中（「低血糖偏瘫」），**任何疑似卒中者必须立即测血糖**。"},{"name":"癫痫","point":"低血糖可诱发抽搐，二者可混淆；低血糖纠正后脑电与症状改善。"},{"name":"精神障碍与醉酒","point":"行为异常可被误认为醉酒；饮酒本身可致低血糖，需测血糖区分。"}],"tx":{"drug":[{"name":"葡萄糖（口服，意识清醒者）","dose":"**15–20 g 快速吸收碳水化合物**（葡萄糖片、含糖饮料 150–200 mL、蜂蜜）；15 分钟后复测血糖，仍 <3.9 mmol/L 则重复","note":"**「15-15 法则」**：15 g 糖 → 等 15 分钟 → 复测；症状缓解后需补充长效碳水（如饼干、面包）以防复发","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"50% 葡萄糖（静脉，意识障碍者）","dose":"**50% 葡萄糖 20–50 mL 静脉推注**（或 25% 葡萄糖 40–60 mL），随后 10% 葡萄糖持续输注（按血糖滴定）","note":"**意识障碍者禁止口服（误吸风险）**；推注后需持续输注以防复发；硫胺素缺乏风险者（酗酒）应先给硫胺素 100 mg","renal":"无","hepatic":"无","interact":"无特殊"},{"name":"胰高血糖素（无静脉通路时）","dose":"1 mg 肌注/皮下（儿童 0.5 mg），10–15 分钟可重复","note":"用于糖尿病患者的严重低血糖急救（可教家属使用）；**对磺脲类所致低血糖效果有限**（需静脉葡萄糖）","renal":"无需调整","hepatic":"肝病者效果差（糖原储备不足）","interact":"无特殊"},{"name":"奥曲肽（胰岛素瘤术前或不能手术）","dose":"50–100 µg 皮下 q8h，按血糖调整","note":"抑制胰岛素分泌，用于胰岛素瘤的术前控制或无法手术者；注意可能加重低血糖（抑制胰高血糖素）","renal":"无需调整","hepatic":"肝病者减量","interact":"与胰岛素、磺脲类合用增加低血糖"},{"name":"二氮嗪（胰岛素瘤，辅助）","dose":"50–100 mg tid 口服（成人），儿童按体重","note":"抑制胰岛素释放；不良反应为水钠潴留与多毛（可联用噻嗪类）","renal":"肾功能不全慎用","hepatic":"肝病者慎用","interact":"与噻嗪类利尿剂合用增强降压与升高血糖"},{"name":"硫胺素（维生素 B1）","dose":"100 mg 静脉/肌注，在给葡萄糖前或同时给予（酗酒与营养不良者）","note":"**预防 Wernicke 脑病**（先给糖后可诱发）；所有疑营养不良的低血糖患者应补充","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**糖尿病患者**：调整降糖方案（减少胰岛素/磺脲剂量）、加强血糖监测（必要时持续葡萄糖监测 CGM）、结构化教育（识别与处理低血糖）","**胰岛素瘤**：手术切除（首选，多数可治愈）；不能手术者用奥曲肽/二氮嗪 + 少量多餐","**胃旁路术后反应性低血糖**：低升糖指数饮食、少量多餐、避免高糖","**肾上腺/垂体功能减退**：补充相应激素","**严重低血糖昏迷**：除静脉葡萄糖外，需监测神经功能与血糖（持续输注直至稳定）","**「无感知性低血糖」**：放宽血糖目标数周以恢复感知（避免严格控糖）"],"life":["**随身携带快速升糖食品**（葡萄糖片/含糖饮料）与疾病识别卡","**家属与同事培训胰高血糖素使用**（严重低血糖时）","**避免空腹饮酒**（酒精抑制糖异生）","规律进餐与运动前适当加餐（运动可致迟发低血糖，需监测）","**糖尿病患者定期复查肾功能**（eGFR 下降时胰岛素/磺脲需减量）","驾驶安全（血糖 <5.0 mmol/L 时不应驾车，按当地规定）"]},"prog":"轻度低血糖经及时补糖可完全恢复。**严重或反复低血糖可致认知功能下降与心血管事件风险增加**（尤其老年人）。胰岛素瘤手术切除后约 90% 治愈，恶性者（约 10%）预后差。糖尿病患者的低血糖与死亡风险、心血管事件相关，需优化方案与教育。","refs":["《内科学》第 9 版（人民卫生出版社）低血糖症章","2024 ADA Standards of Care in Diabetes: Hypoglycemia（Section 6）","2009 Endocrine Society Clinical Practice Guideline: Evaluation and Management of Adult Hypoglycemic Disorders","《中国糖尿病患者低血糖管理的专家共识》（2018）"]},{"id":"met_obesity","name":"肥胖症","aka":["Obesity","肥胖","代谢综合征相关肥胖"],"rank":2,"basic":{"define":"由遗传、环境与行为因素共同作用导致体内脂肪过度蓄积，达到危害健康的程度。中国标准：**BMI ≥28 kg/m² 为肥胖，24–27.9 为超重**；WHO 标准：≥30 为肥胖。中心性肥胖（男性腰围 ≥90 cm、女性 ≥85 cm）与代谢风险关系更密切。","risk":["遗传（多基因，BMI 遗传度约 40%–70%）","高能量密度饮食与含糖饮料","体力活动不足与久坐","睡眠不足与心理社会压力","肠道菌群与内分泌干扰物（研究性）","药物（抗精神病药、糖皮质激素、胰岛素、部分抗抑郁药）","下丘脑性肥胖（颅咽管瘤、外伤、放疗）"],"epi":"我国成人超重率约 34%、肥胖率约 16%（《中国居民营养与慢性病状况报告 2020》），合计超过 50%。儿童青少年肥胖率亦快速上升。肥胖是 2 型糖尿病、高血压、心血管病、脂肪肝、OSA 与多种癌症的重要危险因素。"},"patho":"能量摄入长期超过消耗，脂肪组织（尤其内脏脂肪）扩张。内脏脂肪具有更高的脂解活性与炎性因子分泌（TNF-α、IL-6、瘦素抵抗、脂联素降低），导致**胰岛素抵抗**、异位脂肪沉积（肝、肌肉、心包）与慢性低度炎症，进而引起糖代谢异常、血脂异常、高血压与内皮功能障碍。下丘脑（弓状核 POMC/AgRP 神经元）调控食欲与能量平衡，瘦素-黑皮质素通路异常可致单基因肥胖。GLP-1 与 GIP 等肠促胰素参与食欲调节，是药物治疗的靶点。","dx":{"criteria":["**BMI 分级（中国标准）**：低体重 <18.5；正常 18.5–23.9；超重 24.0–27.9；**肥胖 ≥28.0**（其中 28.0–32.4 为轻度、32.5–37.4 为中度、≥37.5 为重度）","**腰围（中心性肥胖）**：男性 ≥90 cm、女性 ≥85 cm","**合并症评估**：2 型糖尿病或糖尿病前期、高血压、血脂异常、脂肪肝（MASLD）、OSA、高尿酸、多囊卵巢综合征、骨关节炎","**代谢综合征诊断**（具备以下 ≥3 项）：腹型肥胖（腰围超标）、TG ≥1.70 mmol/L、HDL-C <1.04 mmol/L（男）或 <1.30（女）、血压 ≥130/85 mmHg 或已治疗、空腹血糖 ≥5.6 mmol/L 或已诊断糖尿病","**继发性肥胖筛查线索**：短期内快速增重、向心性肥胖伴紫纹（库欣）、下丘脑病变（头痛、视野缺损、垂体功能异常）、甲状腺功能减退","需评估心理与进食行为（暴食障碍、夜食综合征）"],"workup":["身高、体重、BMI、腰围、臀围与体脂测定（生物电阻抗或 DXA）","**血糖与 HbA1c、血脂全套、尿酸、肝功能（ALT）、肝脏超声或 FibroScan**","甲状腺功能（TSH）、皮质醇（疑库欣时）","**睡眠监测（疑 OSA：打鼾、日间嗜睡、STOP-BANG 评分）**","血压与心血管风险评估","多囊卵巢综合征筛查（女性：月经史、雄激素、卵巢超声）","心理与进食行为评估（暴食、抑郁、焦虑）","必要时基因检测（早发严重肥胖、伴发育异常）"],"grading":"**BMI 分级（中国标准，见诊断标准）**；腰围（中心性肥胖）；**肥胖相关并发症分期（ Edmonton Obesity Staging System，0–4 期）** 用于决定干预强度；按病因分原发性（多基因 + 环境）与继发性（内分泌、药物、下丘脑、单基因）。"},"ddx":[{"name":"低血糖症（met_hypoglycemia）","point":"与低血糖的鉴别：低血糖为血糖过低（发作时 <2.8 mmol/L）伴交感与神经症状；肥胖者可有餐后反应性低血糖（尤其术后），但非肥胖本身的表现。"},{"name":"库欣综合征（ad_cushing）","point":"库欣为向心性肥胖 + 紫纹 + 满月脸 + 高血压 + 高血糖，皮质醇节律异常与地塞米松抑制试验阳性；单纯肥胖的紫纹多为淡白细纹（非紫红宽纹）。"},{"name":"甲状腺功能减退（thy_hypo）","point":"体重增加伴黏液性水肿、畏寒、便秘、TSH 升高；肥胖本身不引起明显甲减。"},{"name":"多囊卵巢综合征（ob_pcos）","point":"肥胖常与 PCOS 并存（约 50%–70% 的 PCOS 患者超重或肥胖）；PCOS 以月经稀发、高雄激素与卵巢多囊样改变为特征。"},{"name":"下丘脑性肥胖","point":"有颅脑手术、放疗、外伤或肿瘤史，伴头痛、视野缺损与其他垂体激素缺乏；起病常较急且体重增长迅速。"},{"name":"药物性体重增加","point":"有明确用药史（抗精神病药、糖皮质激素、胰岛素、部分抗抑郁药），停药或换药后体重可下降。"},{"name":"水肿（心、肝、肾源性）","point":"体重增加由体液潴留所致，伴水肿、腹水或心衰表现；BMI 与体脂不匹配。"}],"tx":{"drug":[{"name":"司美格鲁肽（GLP-1 受体激动剂）","dose":"**2.4 mg 皮下每周 1 次**（减重适应症，从 0.25 mg 起始，每 4 周递增）；糖尿病剂量 0.5–1 mg 每周","note":"**减重效果显著（约 10%–15% 体重）**，且有心血管获益（SELECT 研究）；不良反应为恶心、呕吐、腹泻（多在起始期）；禁用于甲状腺髓样癌或多发性内分泌腺瘤病 2 型病史者","renal":"重度肾功能不全慎用（脱水风险）","hepatic":"重度肝损害慎用","interact":"与胰岛素/磺脲类合用增加低血糖；延缓胃排空影响口服药吸收"},{"name":"利拉鲁肽（GLP-1 受体激动剂）","dose":"**3.0 mg 皮下每日 1 次**（减重）；糖尿病 1.2–1.8 mg qd","note":"减重约 5%–8%；每日注射；不良反应同司美格鲁肽","renal":"CrCl <30 慎用","hepatic":"重度肝损害慎用","interact":"同司美格鲁肽"},{"name":"替尔泊肽（GIP/GLP-1 双激动剂）","dose":"5 mg 皮下每周起始，每 4 周递增至 10–15 mg（减重适应症）","note":"**减重效果可达 15%–20%**（SURMOUNT 研究）；不良反应以胃肠道为主","renal":"重度肾功能不全慎用","hepatic":"重度肝损害慎用","interact":"同 GLP-1 类"},{"name":"奥利司他（脂肪酶抑制剂）","dose":"120 mg tid 随餐口服","note":"减少脂肪吸收约 30%，减重约 3%–5%；不良反应为脂肪泻与脂溶性维生素吸收不良（需补充 A/D/E/K）","renal":"无需调整","hepatic":"胆汁淤积者慎用","interact":"影响脂溶性维生素与环孢素吸收（间隔 2 小时）"},{"name":"芬特明/托吡酯复方（中枢性减重）","dose":"3.75/23 mg 起始，逐渐增至 15/92 mg qd（遵说明书）","note":"减重约 8%–10%；注意心率与血压升高、口干、感觉异常；**妊娠禁用（托吡酯致畸）**；我国可及性有限","renal":"中重度肾功能不全减量","hepatic":"肝病者减量","interact":"托吡酯降低口服避孕药效果；与碳酸酐酶抑制剂合用增加结石"},{"name":"二甲双胍（合并糖尿病/糖尿病前期）","dose":"500 mg bid 起始至 1000 mg bid","note":"对肥胖合并糖代谢异常者有益（体重中性或轻度下降）；不用于单纯减重的首选","renal":"eGFR <30 禁用；30–45 减量","hepatic":"重度肝病禁用","interact":"与造影剂合用需暂停（乳酸酸中毒风险）"},{"name":"维生素与微量元素（代谢手术后）","dose":"维生素 B12 肌注或口服大剂量、铁剂、钙与维生素 D、复合维生素（按术后方案）","note":"代谢手术后必需长期补充，防营养缺乏（尤其 B12、铁、叶酸、钙与维生素 D）","renal":"无需调整","hepatic":"无需调整","interact":"铁与钙需分开服用"}],"nonDrug":["**生活方式干预（所有患者的基石）**：每日能量缺口 500–750 kcal、增加蔬果与蛋白、限制含糖饮料与精制碳水；每周 ≥150 分钟中等强度运动 + 抗阻训练","**代谢手术（手术指征）**：**BMI ≥37.5 推荐手术**；**BMI 32.5–37.4 且合并 T2DM（或 ≥2 项代谢综合征组分）推荐手术**；**BMI 27.5–32.4 且 T2DM 药物控制不佳者可考虑**（中国标准）","**手术方式**：袖状胃切除（SG，最常用）、Roux-en-Y 胃旁路（RYGB，伴糖尿病或反流者优先）、可调节胃束带（少用）","行为治疗：自我监测（饮食与体重记录）、刺激控制、问题解决与预防复发","心理干预：暴食障碍、抑郁与焦虑需同步治疗","**OSA 者 CPAP 治疗**、脂肪肝者减重 ≥5%–10%（可显著改善肝脂肪与炎症）"],"life":["**设定现实目标**：减重 5%–10% 即可显著改善代谢指标（不需追求理想体重）","**长期管理**（肥胖是慢性病，需终身随访，避免「减重-反弹」循环）","睡眠充足（<6 小时/晚与体重增加相关）","运动处方需循序渐进（关节负担者从游泳、骑行开始）","**药物需长期使用**（停用 GLP-1 类后体重常反弹）","代谢手术后需终身营养随访与补充剂"]},"prog":"生活方式干预平均减重 3%–5%（1 年），药物 5%–20%（依药物），代谢手术 25%–30%（长期维持）。减重 5%–10% 可显著改善血糖、血脂与血压；≥10% 可改善脂肪肝与 OSA。**肥胖相关并发症（糖尿病、心血管病、某些癌症）是主要死亡风险**，减重可降低全因死亡率。手术后需警惕营养缺乏与体重反弹（约 20%–30% 在 5–10 年后部分反弹）。","refs":["《中国超重/肥胖医学营养治疗指南（2021）》（中国营养学会）","《中国肥胖及 2 型糖尿病外科治疗指南（2019 年版）》（中华医学会外科学分会）","2016 AACE/ACE Clinical Practice Guideline for Comprehensive Medical Care of Patients with Obesity","2022 AGA Clinical Practice Guideline on Pharmacological Interventions for Adults with Obesity","《中国居民营养与慢性病状况报告（2020 年）》（国家卫生健康委）"]}]},{"id":"thy_goiter","name":"甲状腺肿","rank":41,"summary":"先分清弥漫性或结节性、毒性与非毒性、碘缺乏或碘过量，再决定补碘、限碘、抑制、消融或手术；出现压迫、胸骨后或疑恶变者优先手术。","compare":[{"diseaseId":"thy_simple_goiter","dx":"甲状腺弥漫性肿大、质地均匀、TSH 正常、超声无局灶结节，尿碘可低（<100 µg/L）或高（≥300 µg/L）","key":"弥漫均匀肿大 + TSH 正常 + 无结节；补碘或限碘后体积可缩小"},{"diseaseId":"thy_nodular_goiter","dx":"超声见 ≥1 个结节（多为多发）、TSH 正常或降低，按 C-TIRADS 分级决定 FNA","key":"超声多发结节 + 囊性变/钙化；TSH 降低提示毒性结节，需核素显像"}],"diseases":[{"id":"thy_simple_goiter","name":"单纯性甲状腺肿","aka":["Simple Goiter","Non-toxic Goiter","非毒性弥漫性甲状腺肿","地方性甲状腺肿"],"rank":1,"basic":{"define":"非毒性、非炎性、非肿瘤性的甲状腺肿大，甲状腺功能正常（TSH 在参考范围），超声无局灶性结节或仅弥漫性增大。主要与碘缺乏或碘过量有关，早期为代偿性增生，晚期可纤维化并演变为结节性甲状腺肿。","risk":["碘缺乏：每日碘摄入 <50 µg，地方性甲状腺肿的主要病因","碘过量：水源性高碘地区、长期含碘药物（胺碘酮、含碘造影剂）、海藻类过量摄入","致甲状腺肿物质：十字花科蔬菜、木薯、硫氰酸盐、锂盐、过氯酸盐、硫脲类","生理性需碘增加：青春期、妊娠、哺乳期、绝经期女性","遗传性甲状腺激素合成酶缺陷或转运体缺陷","吸烟（硫氰酸盐负荷）、长期高氟饮水"],"epi":"我国自 1995 年实施全民食盐加碘后，地方性甲状腺肿患病率显著下降，碘缺乏病监测显示 8–10 岁儿童甲状腺肿大率已降至 5% 以下，多数省份人群碘营养处于适宜水平。水源性高碘地区仍分布于黄河流域及沿海部分县区，女性患病率约为男性 2–3 倍。"},"patho":"碘缺乏时甲状腺激素合成不足，垂体 TSH 代偿性升高，刺激滤泡上皮增生、滤泡扩张与胶质蓄积，形成弥漫性肿大；早期补碘后可以逆转。碘过量时高碘抑制甲状腺过氧化物酶（Wolff-Chaikoff 效应），部分个体不能发生碘脱逸，TSH 升高并出现甲状腺肿与甲减。长期反复增生与复旧导致纤维化、结节形成和钙化，此时形态学改变不可逆，并可因结节内出血而突然增大伴疼痛。甲状腺肿大压迫气管、食管与喉返神经，胸骨后甲状腺肿可致气道狭窄。","dx":{"criteria":["甲状腺体积增大：触诊超过胸锁乳突肌内缘或峡部增厚；超声甲状腺容积超过参考上限（成人女性 >18 mL、男性 >25 mL，儿童按年龄与体表面积判读）","甲状腺功能正常：TSH 0.4–4.0 mIU/L（按本实验室参考范围）、FT4 与 FT3 正常，无甲亢/甲减临床表现","自身抗体阴性或低滴度：TPOAb、TgAb 阴性或 < 参考上限 2 倍，TRAb 阴性","超声为弥漫性改变：实质回声均匀、无局灶性结节（出现 ≥1 个结节即归入结节性甲状腺肿）","碘营养评估：空腹尿碘中位数 <100 µg/L 为碘缺乏、100–299 µg/L 为适宜、≥300 µg/L 为碘过量；孕妇适宜区间 150–249 µg/L","排除甲状腺炎：无颈前疼痛、ESR 正常，超声无弥漫低回声或网格样改变","压迫评估：气管偏移或狭窄（CT 示气管最窄径 <8 mm 或较预期减少 >50%）、吞咽困难、声音嘶哑（声带麻痹）","排除浸润性病变与肿瘤：质地硬、固定、生长迅速或伴颈部淋巴结肿大者需进一步检查"],"workup":["甲状腺功能（TSH、FT4、FT3）＋TPOAb、TgAb、TRAb：确定功能状态与自身免疫背景","甲状腺超声：测量容积（长×宽×厚×0.479 或椭圆公式）、回声均匀性、血流、有无结节与钙化","尿碘测定（晨尿或 24 h 尿）：判断碘缺乏或碘过量，指导补碘或限碘","颈部 X 线或 CT：胸骨后甲状腺肿、气管受压、钙化定位；CT 可测气管最窄径","喉镜：声音嘶哑或拟手术者评估声带活动度","甲状腺核素显像与 FNA：核素显像仅用于疑异位甲状腺、毒性结节或胸骨后肿物性质不明时；FNA 仅在合并结节且符合穿刺指征时进行，弥漫性肿大本身不需穿刺"],"grading":"按形态分弥漫性与结节性；按功能分非毒性与毒性；按位置分颈前型与胸骨后型（坠入性）；按碘营养背景分碘缺乏性与碘过量性（水源性高碘）。临床可按 WHO/ICCIDD 分度：0 度不可触及、Ⅰ 度可触及但不可见、Ⅱ 度可见（颈部在正常位置即可见肿大）。"},"ddx":[{"name":"结节性甲状腺肿（thy_nodular_goiter）","point":"与本类中结节性甲状腺肿的鉴别：单纯性甲状腺肿为弥漫、均匀增大，超声无局灶结节、回声均匀；结节性甲状腺肿可触及或超声发现 ≥1 个结节，常伴囊性变、粗钙化与回声不均，TSH 可被自主分泌结节抑制。"},{"name":"桥本甲状腺炎（thy_thyroiditis）","point":"同样表现为弥漫性肿大，但质地韧如橡皮、超声呈弥漫低回声伴网格样改变、TPOAb/TgAb 高滴度，TSH 多升高；单纯性甲状腺肿抗体阴性、回声均匀。"},{"name":"Graves 病（thy_hypER）","point":"伴甲亢症状、弥漫性甲状腺肿伴血管杂音、突眼与胫前黏液性水肿，TSH 降低、FT4 升高、TRAb 阳性，超声血流丰富呈「火海征」。"},{"name":"甲状腺癌（thy_thyroid_nodule）","point":"质硬、固定、生长迅速，超声见实性低回声、微钙化、纵横比 >1、边缘不规则或颈部淋巴结异常；FNA 见癌细胞，单纯性甲状腺肿无上述征象。"},{"name":"亚急性甲状腺炎（thy_thyroiditis）","point":"病毒感染后发热、颈前剧痛并放射至耳后、ESR 明显增快、摄碘率降低而甲状腺激素升高（分离现象），超声见片状低回声区，激素治疗有效。"},{"name":"甲状舌管囊肿与异位甲状腺","point":"颈中线随吞咽上下移动的囊性肿物，超声为无回声或实性异位腺体，核素显像可定位；单纯性甲状腺肿为双侧弥漫增大。"},{"name":"颈部淋巴结肿大与淋巴瘤","point":"超声显示淋巴结结构（皮质/髓质分界、淋巴门），非甲状腺来源；淋巴瘤可在桥本背景上短期内迅速增大并压迫气道，需 FNA 或粗针活检。"}],"tx":{"drug":[{"name":"碘化钾（补碘）","dose":"碘缺乏者以碘计 100–200 µg/d（约碘化钾 130–260 µg/d）；或经加碘食盐摄入（我国食盐加碘量约 25 mg/kg）。成人推荐碘摄入 120 µg/d、孕妇 230 µg/d、哺乳期 240 µg/d","note":"仅用于确认碘缺乏者；碘过量或水源性高碘地区禁用，否则可加重甲状腺肿与甲减。补碘后 6–12 个月复查甲状腺容积与 TSH","renal":"无需调整","hepatic":"遵说明书","interact":"与抗甲状腺药物合用可致功能波动；胺碘酮、含碘造影剂叠加可致碘过量"},{"name":"左甲状腺素（L-T4）","dose":"25–50 µg qd 起始（老年或冠心病者 12.5–25 µg），每 4–6 周增加 25 µg，目标 TSH 0.5–2.0 mIU/L；仅用于 TSH >4.0 mIU/L 或补碘后仍进行性肿大者，6–12 个月评估疗效","note":"TSH 正常者不推荐常规使用抑制治疗（证据弱，且致心悸、骨量丢失、房颤）；服药前后 30–60 min 空腹","renal":"无需调整","hepatic":"遵说明书","interact":"钙剂、铁剂、考来烯胺、质子泵抑制剂需间隔 4 h；可增强华法林抗凝作用"}],"nonDrug":["手术：出现压迫症状（气管狭窄致呼吸困难、吞咽困难、声音嘶哑）、胸骨后甲状腺肿、怀疑恶变、肿大明显影响外观且内科治疗无效者，行甲状腺次全或近全切除；胸骨后型必要时胸骨劈开","限碘：碘过量地区改饮低碘水、停用含碘药物与造影剂、避免大量海藻类摄入","超声引导下无水乙醇注射或热消融：用于有症状的囊性结节或不耐受手术者，单纯弥漫性肿大不作为首选","放射性碘（131I）：仅用于合并毒性结节或甲亢者，单纯性甲状腺肿不推荐","术前评估：喉镜查声带、甲状腺功能与血钙基线，避免术后声带麻痹与低钙"],"life":["碘缺乏地区坚持食用合格加碘盐，孕妇与哺乳期增加富碘食物（海带、紫菜、海鱼），不盲目忌碘","戒烟，减少大量生食十字花科蔬菜与木薯；避免长期锂盐、含碘药物","每 6–12 个月复查甲状腺超声与 TSH；新出现结节按结节性甲状腺肿流程评估","术后 L-T4 替代者每 6–8 周复查 TSH 直至稳定，之后每 6–12 个月一次","胸骨后甲状腺肿者避免剧烈咳嗽与颈部过伸，出现突发呼吸困难立即就诊"]},"prog":"早期弥漫性肿大在纠正碘营养后 6–12 个月体积可缩小 10%–30%，多数可逆。病程长、已纤维化或形成结节者形态难以完全恢复，约 5%–10% 的多结节性甲状腺肿最终发展为毒性结节。胸骨后甲状腺肿少数可致急性气道压迫，需紧急处理。","refs":["中国居民补碘指南（2018，中华医学会地方病学分会、中国营养学会、中华医学会内分泌学分会）","中国甲状腺疾病诊治指南（2007，中华医学会内分泌学分会）","甲状腺结节和分化型甲状腺癌诊治指南（第二版，2023）","甲状腺功能减退症基层诊疗指南（2019，中华医学会）","GB/T 19380-2016 水源性高碘地区和地方性高碘甲状腺肿病区的划定"]},{"id":"thy_nodular_goiter","name":"结节性甲状腺肿","aka":["Nodular Goiter","Multinodular Goiter","多结节性甲状腺肿","非毒性结节性甲状腺肿"],"rank":2,"basic":{"define":"甲状腺内出现一个或多个结构或功能异常的结节，伴或不伴甲状腺体积增大，甲状腺功能多正常。是最常见的甲状腺疾病，需按超声风险分层决定是否穿刺，并区分非毒性与毒性结节。","risk":["碘缺乏或碘过量（长期碘营养异常）","女性、年龄 >40 岁，患病率随年龄上升","头颈部放射线暴露史（尤其儿童期）","甲状腺肿或甲状腺癌家族史","吸烟、桥本甲状腺炎背景","代谢综合征与肥胖（结节检出率升高）"],"epi":"高分辨率超声在成人中可检出甲状腺结节者约 20%–70%，女性约为男性 3–4 倍；我国成人甲状腺结节患病率约 20%–30%，其中恶性比例 5%–15%。多发结节多为良性增生性病变，但每个结节均需独立评估。"},"patho":"长期 TSH 刺激与碘营养异常使滤泡上皮增生与胶质蓄积不均，形成结节；结节内反复出血、囊性变、钙化与纤维化导致回声不均。部分结节获得自主分泌功能（毒性结节，Plummer 病），抑制 TSH 并使周围组织萎缩。部分结节累积 BRAF V600E、RAS、RET/PTC 等突变，进展为乳头状癌等恶性病变；结节性甲状腺肿背景并不降低恶性风险。","dx":{"criteria":["触诊或超声发现 ≥1 个甲状腺结节，以高分辨率超声为金标准（结节回声与周围实质不同）","甲状腺功能：非毒性者 TSH 正常（0.4–4.0 mIU/L）；TSH <0.4 mIU/L 提示自主分泌，需核素显像确认热结节","超声风险分层（C-TIRADS）：记录成分（实性/囊性）、回声、形态（纵横比）、边缘、强回声（微钙化）五项","FNA 指征（C-TIRADS）：4A 类 >1.5 cm、4B 类 >1.0 cm、4C 类 >0.5 cm、5 类 ≥0.5 cm；3 类 >2.5 cm 可考虑；1–2 类不穿刺","恶性超声征象：实性低回声、微钙化、纵横比 >1、边缘不规则或微分叶、被膜外侵犯、异常颈部淋巴结（囊性变、微钙化、淋巴门消失）","压迫评估：气管狭窄（CT 最窄径 <8 mm）、吞咽困难、声音嘶哑；胸骨后延伸","排除毒性多结节性甲状腺肿：TSH 抑制 + 核素显像多发「热结节」、周围组织受抑","疑髓样癌时查降钙素：>50 pg/mL 需进一步排除（MEN2 筛查）"],"workup":["甲状腺功能（TSH 首选，异常时加 FT4、FT3）＋TPOAb、TgAb","甲状腺超声（含颈部淋巴结区）：按 C-TIRADS 分级并记录结节三维径线，便于随访对比","超声引导下 FNA：按上述阈值执行，采用 Bethesda 细胞学报告系统（Ⅰ–Ⅵ）","甲状腺核素显像：TSH 降低时判断热结节；热结节一般不需 FNA","颈部 CT 与喉镜：胸骨后甲状腺肿、明显压迫、拟手术者评估气管与血管关系、声带活动度","分子检测：Bethesda Ⅲ/Ⅳ 类不确定结节可检测 BRAF、RAS、TERT、RET/PTC 等辅助决策"],"grading":"按数量分单发与多发；按功能分非毒性与毒性（毒性多结节性甲状腺肿）；按超声风险分 C-TIRADS 1–5 类；按细胞学分 Bethesda Ⅰ–Ⅵ 类；按位置分颈前型与胸骨后型。"},"ddx":[{"name":"单纯性甲状腺肿（thy_simple_goiter）","point":"与本类中单纯性甲状腺肿的鉴别：单纯性为弥漫均匀肿大、超声无局灶结节、TSH 正常；结节性甲状腺肿至少存在 1 个明确结节，常伴囊性变、粗钙化与回声不均，必要时需 FNA 排除恶性。"},{"name":"甲状腺癌（thy_thyroid_nodule）","point":"超声见实性低回声、微钙化、纵横比 >1、边缘不规则、被膜侵犯或淋巴结异常，FNA 为 Bethesda Ⅴ/Ⅵ 类；良性结节性甲状腺肿多为 Bethesda Ⅱ 类、边界清晰。"},{"name":"桥本甲状腺炎（thy_thyroiditis）","point":"弥漫低回声伴网格样改变、TPOAb 高滴度、TSH 多升高；其中的「假结节」在抗炎或随访后可变化，而真结节形态稳定。"},{"name":"毒性多结节性甲状腺肿（Plummer 病）","point":"TSH 被抑制（<0.1 mIU/L）、核素显像多发热结节伴周围组织受抑，老年患者常以房颤、消瘦为首发；非毒性者 TSH 正常、显像摄取均匀或不均但无热结节。"},{"name":"甲状腺囊肿与结节内出血","point":"结节突然增大伴疼痛，超声为无回声或液-液平面，FNA 抽出陈旧血性液后缩小；反复出血或抽吸后迅速复涨需警惕恶性。"},{"name":"亚急性甲状腺炎","point":"发热、颈前剧痛放射至耳后、ESR 增快、摄碘率降低，超声见片状低回声；结节性甲状腺肿无疼痛与炎症指标升高。"},{"name":"甲状旁腺囊肿与食管憩室","point":"位置偏后或偏下，随吞咽移动性差；超声与 CT 可定位，穿刺液查 PTH 可证实甲状旁腺来源。"}],"tx":{"drug":[{"name":"左甲状腺素（L-T4）","dose":"25–50 µg qd 起始，每 4–6 周增加 25 µg，目标 TSH 0.5–2.0 mIU/L；仅用于 TSH 升高或结节持续增大者，6–12 个月评估","note":"不推荐对 TSH 正常的良性结节常规行抑制治疗（不缩小结节，且致骨量丢失与房颤）；随访中结节体积增大 >50% 或径线增加 >2 mm 需重新评估","renal":"无需调整","hepatic":"遵说明书","interact":"钙剂、铁剂、PPI 间隔 4 h；增强华法林作用"},{"name":"甲巯咪唑（毒性结节）","dose":"10–30 mg/d 分 1–2 次口服，4–6 周甲状腺功能下降后减至 5–10 mg/d 维持；疗程 12–18 个月，但毒性结节停药复发率高，多需 131I 或手术根治","note":"用药前查血常规与肝功；出现发热、咽痛立即查粒细胞；妊娠早期禁用（改用丙硫氧嘧啶）","renal":"eGFR <30 减量并延长给药间隔","hepatic":"ALT 超过正常上限 3 倍停药；胆汁淤积性肝炎罕见但严重","interact":"与华法林合用增强抗凝；与 β 受体阻滞剂合用注意心动过缓"},{"name":"丙硫氧嘧啶（PTU）","dose":"100–150 mg q8h（最大 600 mg/d），起效后减量维持；仅用于妊娠早期、甲状腺危象或甲巯咪唑不耐受","note":"肝毒性高于甲巯咪唑，出现黄疸或深色尿立即停药；妊娠中晚期改用甲巯咪唑","renal":"eGFR <50 减量","hepatic":"活动性肝病或转氨酶 >3 倍上限禁用","interact":"增强华法林抗凝；与胺碘酮、含碘药物合用疗效下降"},{"name":"普萘洛尔（毒性结节症状控制）","dose":"10–20 mg tid–qid 口服，按心率调整（目标静息心率 70–90 次/min）；哮喘者改用阿替洛尔 25–50 mg qd","note":"仅控制心悸、震颤、焦虑，不改变甲状腺功能；长期使用注意心动过缓与支气管痉挛","renal":"无需调整","hepatic":"肝硬化者减量","interact":"与地高辛、维拉帕米合用加重心动过缓；可掩盖低血糖症状"}],"nonDrug":["手术：压迫症状（气管狭窄、呼吸困难、吞咽困难、声嘶）、胸骨后甲状腺肿、FNA Bethesda Ⅳ–Ⅵ 类或疑恶性、毒性结节不宜或不愿 131I、结节 >4 cm 进行性增大或影响外观；术式以甲状腺全切或近全切为主","放射性碘（131I）：毒性多结节性甲状腺肿的首选之一，尤其老年或手术高风险者；妊娠与哺乳期禁用，活动性甲状腺眼病慎用，治疗后甲减发生率高需终身替代","超声引导热消融（射频、微波、激光）：良性有症状结节，6–12 个月体积缩小 50%–80%，需排除恶性后实施","囊肿抽吸＋硬化（无水乙醇或聚桂醇）：反复出血性囊性结节，可重复 2–3 次","随访策略：良性结节（Bethesda Ⅱ）6–12 个月复查超声，稳定后每 1–2 年一次；超声高度可疑但 FNA 阴性者 12 个月内复查 FNA 或手术"],"life":["适碘饮食：不盲目忌碘也不额外补碘，碘过量地区改用低碘水；避免长期大量海带、紫菜","戒烟；避免颈部放射线暴露；有家族史者筛查一级亲属","每 6–12 个月复查甲状腺超声并保留图像对比；结节短期增大、声音嘶哑、吞咽困难立即就诊","术后或 131I 后每 6–8 周复查 TSH，稳定后每 6–12 个月一次，终身随访甲减","服用甲巯咪唑期间出现发热、咽痛、黄疸立即停药就诊"]},"prog":"绝大多数结节为良性，自然病程缓慢，年径线增长 >2 mm 或体积增加 >50% 需重新评估。毒性结节经 131I 或手术多可治愈，但甲减发生率高。良性结节中恶性比例 5%–15%，规范 FNA 可使多数甲状腺癌在早期被发现，预后良好。","refs":["甲状腺结节和分化型甲状腺癌诊治指南（第二版，2023，中华医学会内分泌学分会等）","中国甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022，中华医学会内分泌学分会）","中国居民补碘指南（2018，中华医学会地方病学分会等）","中国超声甲状腺结节恶性危险分层（C-TIRADS，2020）","2017 ACR TI-RADS 甲状腺结节超声风险分层（Tessler 等，J Am Coll Radiol 2017）"]}]},{"id":"ad_incidental","name":"肾上腺意外瘤","rank":42,"summary":"所有意外发现的肾上腺结节先做影像良恶性判断（CT 值、大小、边界）加激素功能筛查（1 mg 地塞米松抑制试验、醛固酮肾素比、血浆游离甲氧基肾上腺素），无功能且影像良性者随访，功能性或可疑恶性者手术。","compare":[{"diseaseId":"ad_incidentaloma","dx":"非肾上腺检查偶然发现、最大径 ≥1 cm 的肾上腺占位，无相关症状；平扫 CT ≤10 HU、边界清、<4 cm 提示良性腺瘤，须以 1 mg 地塞米松抑制试验、ARR、血浆游离甲氧基肾上腺素排除功能自主","key":"影像「≤10 HU + 边界清 + <4 cm」三联提示良性；无论大小均需三项激素筛查排除亚临床库欣、原醛与嗜铬细胞瘤"}],"diseases":[{"id":"ad_incidentaloma","name":"肾上腺意外瘤","aka":["Adrenal Incidentaloma","AI","肾上腺偶发瘤","肾上腺意外发现结节"],"rank":1,"basic":{"define":"因非肾上腺疾病或健康体检行影像学检查时偶然发现、最大径 ≥1 cm 的肾上腺占位，患者无肾上腺相关临床症状。它是一个影像学定义，病理性质涵盖良性无功能腺瘤、激素自主分泌肿瘤、嗜铬细胞瘤、皮质癌、转移瘤、囊肿与血肿等。","risk":["年龄 >40 岁，检出率随年龄增长明显升高","高血压、肥胖、糖尿病等代谢综合征组分（与皮质醇自主分泌相关）","既往恶性肿瘤史（肺癌、乳腺癌、肾癌、黑色素瘤），转移瘤风险显著升高","家族性内分泌肿瘤综合征：MEN2、VHL、NF1、FAP、Carney 综合征","双侧肾上腺病变（感染、出血、转移、先天性肾上腺增生）","吸烟、头颈部或腹部放疗史"],"epi":"腹部 CT 检查中肾上腺意外瘤的检出率约 3%–7%，60 岁以上人群可达 10%；尸检系列为 1.4%–8.7%。检出者中良性无功能腺瘤占 70%–80%，激素功能亢进 5%–15%（亚临床库欣最常见），恶性 2%–5%；合并已知恶性肿瘤者转移瘤比例可高达 30%–70%。"},"patho":"多数为肾上腺皮质腺瘤，起源于束状带，呈单克隆增生，细胞内富含脂质（CT 值低）且激素分泌效率低。部分腺瘤获得 cAMP/PKA 通路突变，出现皮质醇自主分泌（亚临床库欣），或球状带增生导致醛固酮自主分泌；髓质来源的嗜铬细胞瘤含儿茶酚胺颗粒，增强明显。皮质癌体积大、生长快，常伴坏死、出血、静脉癌栓与雄激素/皮质醇共同分泌。转移瘤多为双侧且影像不均质，囊肿、髓脂肪瘤与血肿则具有特征性密度。","dx":{"criteria":["影像学定义：因非肾上腺指征行 CT/MRI/超声偶然发现肾上腺结节，最大径 ≥1 cm，无肾上腺疾病相关症状与体征","良性影像征象：平扫 CT 值 ≤10 HU（富脂腺瘤）、边界清晰、形态规则、直径 <4 cm、密度均匀、无坏死或钙化","增强廓清：腺瘤 10 分钟绝对廓清率 >60%、相对廓清率 >40%（延迟 15 分钟计算），非腺瘤廓清率低","恶性影像征象：直径 >4 cm、平扫 CT 值 >20 HU、边缘不规则、坏死/出血/钙化、生长速度 >2 cm/年、静脉癌栓或淋巴结转移","皮质醇自主分泌筛查：1 mg 地塞米松抑制试验（1 mg ODST），次晨 8 时血皮质醇 <50 nmol/L（1.8 µg/dL）排除，50–138 nmol/L 为可能，>138 nmol/L（5 µg/dL）确诊库欣综合征","原醛筛查：高血压或低血钾者测血浆醛固酮浓度与肾素，ARR >20–30 且醛固酮 >15 ng/dL、肾素受抑制提示原发性醛固酮增多症","嗜铬细胞瘤筛查：血浆游离甲氧基肾上腺素（MNs）>3 倍正常上限诊断价值高，1–3 倍需复查或行激发试验","双侧或大结节病变：查晨 8 时皮质醇与 ACTH 排除肾上腺皮质功能不全；疑雄激素分泌者查 DHEA-S 与睾酮"],"workup":["肾上腺 CT 平扫＋增强（1–3 mm 薄层）：测 CT 值、大小、边界、均匀度、钙化与廓清率；CT 值 10–20 HU 灰区时加 MRI 化学位移成像判断细胞内脂质，疑转移瘤或皮质癌行 FDG-PET","1 mg 地塞米松抑制试验：所有患者均做；睡前 23–24 时服地塞米松 1 mg，次晨 8 时测皮质醇；女性服雌激素或妊娠者皮质醇结合球蛋白升高，结果需校正","醛固酮/肾素比值：仅限高血压或低血钾者；需停用螺内酯 4 周、利尿剂 2 周，β 阻滞剂与 ACEI/ARB 可升高或降低比值，需结合临床判读","血浆游离甲氧基肾上腺素：采血前静卧 30 min，避免咖啡因、对乙酰氨基酚、拉贝洛尔干扰；结果不确定时测 24 h 尿分馏甲氧基肾上腺素","FNA 活检：仅用于已排除嗜铬细胞瘤、疑转移瘤且不适合手术者；禁用于可切除的肾上腺肿瘤（针道种植与皮质癌破裂风险）","遗传学与家族史评估：年龄 <40 岁、双侧病变、多发肿瘤或有家族史者筛查 MEN2、VHL、NF1 等"],"grading":"按功能分无功能腺瘤、亚临床库欣（MACS）、库欣综合征、原发性醛固酮增多症、嗜铬细胞瘤、雄激素分泌肿瘤；按影像分良性（≤10 HU）与可疑（>10 HU 或 >4 cm）；按大小分 <4 cm 与 ≥4 cm；按侧别分单侧与双侧。"},"ddx":[{"name":"嗜铬细胞瘤（ad_pheo）","point":"本大类仅含肾上腺意外瘤一个条目，最易混淆且最不能漏诊的邻类疾病为嗜铬细胞瘤：可有阵发性高血压、心悸、大汗、头痛三联征，血浆游离甲氧基肾上腺素 >3 倍上限；影像 CT 值多 >10 HU 且增强明显。平扫 ≤10 HU 几乎可排除嗜铬细胞瘤，任何肾上腺占位在穿刺前必须先排除本病。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"高血压伴或不伴低血钾、ARR 升高、肾素受抑制、肾上腺可见腺瘤或双侧增生；意外瘤中约 1%–5% 为原醛，高血压患者必须筛查。"},{"name":"库欣综合征（ad_cushing）","point":"向心性肥胖、紫纹、满月脸、近端肌无力、高血压与高血糖，1 mg ODST 不被抑制、24 h 尿游离皮质醇升高；亚临床库欣仅有生化异常而无典型体征。"},{"name":"肾上腺皮质癌","point":"直径多 >4 cm（常 >6 cm）、CT 值 >20 HU、密度不均、坏死出血、边缘不规则、年增长 >2 cm，可伴雄激素过多（女性男性化）或皮质醇增多；预后差，需完整切除。"},{"name":"肾上腺转移瘤","point":"有肺癌、乳腺癌、肾癌或黑色素瘤病史，多为双侧、影像不均质、FDG-PET 高代谢，通常无激素分泌；FNA 可证实，但须先排除嗜铬细胞瘤。"},{"name":"肾上腺髓脂肪瘤","point":"CT 呈脂肪密度（−20 至 −100 HU）、无强化、无激素功能，体积大但质地柔软；与富脂腺瘤的鉴别在于脂肪密度更低且不含软组织成分。"},{"name":"肾上腺囊肿与血肿","point":"囊肿为无回声或水样密度、壁薄无强化；血肿有外伤、抗凝或应激史，CT 呈高密度后逐渐液化，随访缩小，激素筛查阴性。"},{"name":"肾上腺结核或真菌感染","point":"常双侧、肾上腺增大或萎缩伴钙化，可有低血压、低钠高钾与皮质功能减退；结核筛查（IGRA、胸片）与激素测定可鉴别。"}],"tx":{"drug":[{"name":"酚苄明（嗜铬细胞瘤术前准备）","dose":"10 mg bid 起始，每 2–3 天增加 10 mg，直至血压控制且无体位性低血压，术前持续 10–14 天；必要时加用 β 受体阻滞剂（须在 α 阻滞之后）","note":"确诊嗜铬细胞瘤后必须先用 α 阻滞剂扩容，再手术；突然停药可致高血压危象。术前高钠饮食与充分补液扩容","renal":"无需调整","hepatic":"遵说明书","interact":"与 β 阻滞剂单用可致血压骤升（先用 α）；与三环类抗抑郁药合用增强升压反应"},{"name":"米托坦（肾上腺皮质癌）","dose":"1–2 g/d 分 3–4 次口服起始，逐步加量至血药浓度 14–20 mg/L（最高 6 g/d）；同时补充氢化可的松，避免肾上腺危象","note":"仅用于肾上腺皮质癌；起效慢，需监测血药浓度、肝功与血脂；停药后仍可持续抑制类固醇合成数周","renal":"遵说明书","hepatic":"肝功不全者减量并密切监测","interact":"强效 CYP3A4 诱导剂，降低华法林、他汀、咪达唑仑、多数化疗药浓度"},{"name":"氢化可的松（术后或双侧切除替代）","dose":"15–25 mg/d 分 2–3 次（晨 10–15 mg、午后 5–10 mg）；应激时增至 2–3 倍，重大手术或感染 5–10 倍","note":"单侧腺瘤切除后对侧轴受抑，围手术期需覆盖应激剂量，出院前评估晨皮质醇或 ACTH 兴奋试验决定是否长期替代","renal":"无需调整","hepatic":"肝病者监测","interact":"利福平、苯妥英、卡马西平加速代谢需加量；与酮康唑合用抑制合成"},{"name":"酮康唑（库欣综合征术前控制）","dose":"200 mg tid 起始，按皮质醇与肝功调整，最大 1200 mg/d；术前 2–4 周开始","note":"抑制类固醇合成，用于手术前控制高皮质醇血症；需监测肝酶与皮质醇，警惕肾上腺皮质功能不全","renal":"无需调整","hepatic":"活动性肝病或转氨酶 >2 倍上限禁用；用药期间每 2 周查肝功","interact":"CYP3A4 抑制剂，升高环孢素、他汀、咪达唑仑浓度；抑酸药降低其吸收"},{"name":"螺内酯（原醛术前或不宜手术）","dose":"20–40 mg bid 起始，按血压与血钾调整至 100–300 mg/d；术前 3–4 周开始","note":"拮抗醛固酮受体，纠正低钾与高血压；单侧腺瘤首选腹腔镜切除，双侧增生长期药物","renal":"eGFR <30 慎用，监测高钾","hepatic":"遵说明书","interact":"与 ACEI/ARB、NSAIDs 合用增加高钾风险；降低地高辛清除"}],"nonDrug":["手术适应证：激素功能亢进（嗜铬细胞瘤、原醛单侧腺瘤、库欣腺瘤）、影像可疑恶性（>4 cm、CT 值 >20 HU、边缘不规则、坏死、年增长 >2 cm）、有恶性肿瘤史且为孤立病灶、亚临床库欣合并难控高血压/糖尿病/骨质疏松/肥胖","术式：腹腔镜肾上腺切除为首选（<6 cm、无侵犯）；疑皮质癌或 >6–8 cm 行开放手术，避免肿瘤破裂与针道种植","无功能且影像良性（≤10 HU、<4 cm）：6–12 个月复查 CT，稳定后每 1–2 年随访至 5 年；每年复查 1 mg ODST 共 5 年","亚临床库欣（MACS）：无合并症者每年复查 ODST 与 CT；出现高血压、糖尿病、骨质疏松进展或结节增大者手术","穿刺活检：仅用于疑转移瘤、已排除嗜铬细胞瘤且不适合手术者，禁用于可切除的肾上腺肿瘤","围手术期：嗜铬细胞瘤术前 α 阻滞 10–14 天并扩容；库欣术后糖皮质激素替代并逐步减量"],"life":["控制血压、血糖与体重，戒烟；代谢综合征组分改善可降低皮质醇自主分泌的心血管风险","单侧肾上腺切除后 6–12 周评估对侧肾上腺功能，必要时短期激素替代并教育应激剂量","每 6–12 个月复查影像与激素，连续 5 年；结节增大 >1 cm 或出现功能亢进提前手术","有家族史或年轻双侧病变者行遗传咨询与综合征筛查","随身携带疾病卡，发热、呕吐、外伤时及时增加糖皮质激素剂量并就医"]},"prog":"良性无功能腺瘤恶变率极低（<1/1000），规范随访即可。亚临床库欣约 10%–20% 在 5 年内进展为库欣综合征，且心血管事件与骨质疏松风险升高。肾上腺皮质癌预后差，5 年生存率 <30%；转移瘤预后取决于原发肿瘤。嗜铬细胞瘤手术治愈率高，但需终身随访复发。","refs":["肾上腺意外瘤多学科管理专家共识（2021）","欧洲内分泌学会（ESE/ENSAT）肾上腺意外瘤临床实践指南（2016）","库欣综合征专家共识（2011，中华医学会内分泌学分会）","原发性醛固酮增多症诊断治疗的专家共识（2020版）","嗜铬细胞瘤和副神经节瘤诊断治疗专家共识（2020版）"]}]},{"id":"dm_complications","name":"糖尿病慢性并发症","rank":43,"summary":"以 Wagner 分级与 IWGDF 风险分层驱动：感染、缺血、减压三条线同时评估，深部组织培养指导抗生素，4 周不愈或中重度缺血尽早血运重建。","compare":[{"diseaseId":"dm_foot","dx":"糖尿病病史 + 足部溃疡/坏疽，Wagner ≥1 级；合并感染时局部红肿热痛、脓性分泌物，探骨阳性或 MRI 提示骨髓炎；ABI ≤0.9 或 TcPO2 <30 mmHg 提示缺血","key":"Wagner 分级定深度、IWGDF/IDSA 定感染严重度、ABI/TcPO2 定缺血——三者共同决定清创时机、抗生素强度与是否血运重建"}],"diseases":[{"id":"dm_foot","name":"糖尿病足","aka":["Diabetic Foot","Diabetic Foot Ulcer","DFU","糖尿病足溃疡","糖尿病足病"],"rank":1,"basic":{"define":"糖尿病患者因周围神经病变、下肢动脉病变及感染共同作用，导致足部溃疡、坏疽或深部组织破坏的临床综合征。是糖尿病患者截肢的首位原因，按 Wagner 分级评估组织缺损深度，按 IWGDF 风险分层决定筛查频率与预防强度。","risk":["糖尿病病程 >10 年、血糖控制差（HbA1c >8%）","周围神经病变（保护性感觉丧失）与足畸形（锤状趾、爪形趾、𧿹外翻、扁平足）","下肢动脉病变（PAD）、既往足溃疡或截肢史","终末期肾病或透析、视力障碍、独居、依从性差","吸烟、营养不良（白蛋白 <30 g/L）、肥胖","足部护理不当：赤足行走、鞋袜不合适、自行修剪胼胝"],"epi":"糖尿病患者一生中发生足溃疡的风险约 19%–34%；我国 50 岁以上糖尿病患者糖尿病足年发病率约 8.1%。约 17% 的糖尿病足患者最终接受截肢，足溃疡患者 5 年病死率约 30%，大截肢后可达 50%–70%。"},"patho":"三重机制叠加：① 周围神经病变——感觉神经受损使压力与外伤不被感知，反复受压部位角化形成胼胝并最终破溃；自主神经病变致皮肤干燥、皲裂与血流调节异常；运动神经病变致足内在肌萎缩、足畸形与压力重新分布。② 缺血——糖尿病以膝下动脉（胫前、胫后、腓动脉）中膜钙化与多节段闭塞为特征，侧支代偿差，创面供血不足。③ 感染——溃疡深部定植后向软组织与骨蔓延，高血糖损害中性粒细胞趋化与吞噬、胶原合成及血管新生，使感染难以局限、创面愈合延迟。","dx":{"criteria":["糖尿病或糖代谢异常病史，足部出现溃疡、坏疽或深部组织破坏（Wagner ≥1 级）","Wagner 分级：0 级高危足无溃疡；1 级表浅溃疡未累及深部；2 级溃疡深达肌腱、关节囊或骨；3 级深部溃疡伴脓肿或骨髓炎；4 级局限性坏疽（趾、前足或足跟）；5 级全足坏疽","感染诊断（IWGDF/IDSA）：溃疡局部红肿热痛或脓性分泌物，至少 2 项炎症征象；白细胞 >11×10⁹/L、CRP >10 mg/L、PCT 升高支持诊断","感染严重度：轻度为表浅溃疡伴周围红斑 ≤2 cm；中度为红斑 >2 cm、深部组织受累、脓肿、坏疽或骨暴露；重度为合并全身炎症反应（体温 >38 ℃ 或 <36 ℃、心率 >90 次/min、呼吸 >20 次/min、白细胞 >12×10⁹/L 或 <4×10⁹/L）或休克","缺血评估：足背与胫后动脉搏动减弱或消失，ABI ≤0.9 为异常、>1.3 提示动脉钙化不可靠；趾臂指数 <0.7、经皮氧分压 <30 mmHg 提示愈合能力差","骨髓炎：探骨试验阳性（无菌探针可触及骨）、溃疡 >2 周不愈、骨暴露；X 线早期可阴性（40%–70%），MRI 为首选，骨活检/组织培养确诊","神经评估：10 g 尼龙单丝 4 点中 ≥1 点无感知为保护性感觉丧失（LOPS），128 Hz 振动觉与踝反射减弱","鉴别 Charcot 神经性关节病：足部红肿热但无溃疡或仅有胼胝、无脓性分泌物，X 线/CT 见骨折、脱位与骨碎片，需与感染区分"],"workup":["足部查体：溃疡部位、长宽深（cm）、基底、渗出、异味、周围红斑范围、探骨试验、足背与胫后动脉搏动","实验室：血常规、CRP、ESR、PCT、白蛋白、HbA1c、肌酐/eGFR、电解质；重度感染加血培养（阳性率约 30%）","病原学：清创后取深部组织或骨组织培养（优于拭子），同时做需氧/厌氧培养与药敏；浅表拭子易被定植菌污染，不推荐作为依据","影像：足部 X 线（异物、气体、骨破坏、Charcot）；疑骨髓炎首选 MRI（敏感度 90%、特异度 80%）；CT 评估骨破坏与手术规划","血管评估：ABI、TBI、趾端 TcPO2；拟血运重建者行下肢 CTA 或 DSA，评估膝下三支血管与足部流出道","创面评估：每 1–4 周测量面积与深度，4 周面积缩小 <50% 提示愈合前景差，需重新评估缺血、感染与减压"],"grading":"Wagner 0–5 级评估组织缺损深度；IWGDF 风险分层 0–3 级（0 极低：无 LOPS 无 PAD，每年筛查；1 低：LOPS 或 PAD，每 6–12 个月；2 中：LOPS+PAD 或 LOPS/PAD 合并足畸形，每 3–6 个月；3 高：LOPS 或 PAD 合并溃疡、截肢史或终末期肾病，每 1–3 个月）；感染按 IWGDF/IDSA 分轻、中、重度；血运按 WIfI 分级（创面、缺血、足感染）评估保肢概率。"},"ddx":[{"name":"下肢动脉硬化闭塞症（vs_aso）","point":"本大类仅含糖尿病足一个条目，最易混淆的邻类疾病为下肢动脉硬化闭塞症：后者以间歇性跛行、静息痛、足背动脉消失、ABI <0.9 为主，溃疡多位于趾端或足跟且疼痛明显；糖尿病足常为神经性溃疡（足底受压区、无痛、胼胝 surrounding），但两者可并存，糖尿病足合并 PAD 时缺血更重、膝下血管受累更多。"},{"name":"Charcot 神经性关节病","point":"急性期足部红肿热似感染，但无溃疡或脓性分泌物、无全身炎症反应；X 线/CT 见跖跗关节破坏、骨折脱位与骨碎片，MRI 以骨髓水肿、关节积液与骨碎裂为主而无脓肿或窦道；误当感染切开可致灾难性后果。"},{"name":"糖尿病周围神经病变性溃疡（神经性溃疡）","point":"足底受压区（第 1 跖骨头、足跟）、无痛、胼胝厚、足背动脉搏动可及、ABI 正常；与缺血性溃疡（趾端、疼痛、ABI 低）区分，决定是否需血运重建。"},{"name":"静脉性溃疡","point":"小腿下段内侧、表浅、渗出多、周围皮肤色素沉着与湿疹样变，伴下肢水肿与静脉曲张；足部动脉搏动正常，与糖尿病足的足底/趾端分布不同。"},{"name":"痛风性溃疡与钙化防御","point":"痛风石破溃排出白色尿酸盐结晶，血尿酸升高；钙化防御见于终末期肾病，皮肤坏死伴剧痛与紫癜，血钙磷乘积升高，两者均无典型神经性分布。"},{"name":"足部骨髓炎（非糖尿病）与骨肿瘤","point":"外伤或术后感染史、单骨病灶、无神经病变；骨肿瘤罕见，影像见骨破坏伴软组织肿块，活检确诊。"},{"name":"接触性皮炎与蜂窝织炎（非足溃疡）","point":"前者有接触史、瘙痒、边界清楚无溃疡；后者为皮肤感染但无深层组织缺损，需与糖尿病足合并感染鉴别以决定抗生素疗程。"}],"tx":{"drug":[{"name":"阿莫西林/克拉维酸（轻度感染）","dose":"625 mg tid 口服（或 1.2 g q8h 静滴），疗程 1–2 周；表浅溃疡无深部受累者 7–10 天","note":"覆盖革兰阳性球菌与部分革兰阴性菌及厌氧菌；用药前取深部组织培养；轻度感染且无骨暴露可门诊口服治疗","renal":"CrCl 10–30 mL/min 减量或延长间隔（遵说明书）","hepatic":"肝功不全者监测，既往胆汁淤积性黄疸史者禁用","interact":"与华法林合用可升高 INR；丙磺舒升高本品浓度"},{"name":"头孢曲松（中度感染，联合甲硝唑）","dose":"1–2 g qd 静滴，联合甲硝唑 500 mg q8h；疗程 2–3 周，骨髓炎延长至 3–6 周","note":"覆盖链球菌、金黄色葡萄球菌（MSSA）与肠杆菌科；不覆盖铜绿假单胞菌与 MRSA；疑厌氧菌混合感染必须联合甲硝唑","renal":"一般无需调整；合并肝肾功能不全时监测","hepatic":"肝硬化者无需减量，但需监测","interact":"与含钙输液同通路可形成沉淀（新生儿禁用）；与华法林合用增加出血风险"},{"name":"哌拉西林/他唑巴坦（中重度感染）","dose":"4.5 g q6–8h 静滴（延长输注 3–4 h 可提高疗效），疗程 2–3 周；骨髓炎 6 周","note":"覆盖铜绿假单胞菌、肠杆菌科与厌氧菌，是糖尿病足中重度感染的经验性首选之一；需结合本地药敏","renal":"CrCl 20–40 减至 3.375 g q8h，<20 减至 2.25 g q8h（遵说明书）","hepatic":"无需调整","interact":"与氨基糖苷类合用增加肾毒性；与丙磺舒合用升高浓度"},{"name":"万古霉素（MRSA 风险或重度感染）","dose":"15–20 mg/kg q8–12h 静滴（按实际体重，单次不超过 2 g），目标 AUC 400–600 mg·h/L 或谷浓度 15–20 mg/L；疗程按感染灶 2–6 周","note":"用于 MRSA 高发地区、既往 MRSA 定植、静脉吸毒或重度感染；需监测肾功与听力；不单独用于经验性治疗（需联合覆盖革兰阴性菌药物）","renal":"按 CrCl 调整剂量与间隔，eGFR <30 需延长至 q24–48h 并监测谷浓度","hepatic":"无需调整","interact":"与氨基糖苷类、两性霉素 B、造影剂合用增加肾毒性；与麻醉药合用可致红人综合征（需缓慢输注 ≥60 min）"},{"name":"甲硝唑（厌氧菌覆盖）","dose":"500 mg q8h 静滴或口服，疗程 1–2 周（骨髓炎联合方案中 6 周）","note":"糖尿病足感染常见厌氧菌（消化链球菌、拟杆菌），深部溃疡、恶臭或坏死组织必须覆盖","renal":"一般无需调整；透析日于透析后给药","hepatic":"重度肝病减量；用药期间禁酒","interact":"与华法林合用显著升高 INR；与双硫仑样反应（酒精）；与锂盐合用升高锂浓度"},{"name":"利奈唑胺（MRSA/革兰阳性耐药菌）","dose":"600 mg q12h 静滴或口服，疗程 2–4 周（骨髓炎可 6 周）","note":"替代万古霉素用于 MRSA 或万古霉素不耐受/肾衰者；口服生物利用度 100%，可序贯口服；疗程 >2 周需监测血常规与视力","renal":"无需调整","hepatic":"轻中度无需调整；重度肝硬化慎用","interact":"弱 MAO 抑制剂，与 SSRI、曲马多、度冷丁合用可致 5-羟色胺综合征；与肾上腺素能药物合用升压"},{"name":"达托霉素（MRSA 软组织感染）","dose":"4–6 mg/kg qd 静滴（皮肤软组织感染 4 mg/kg，菌血症/骨髓炎 6 mg/kg），疗程 2–4 周","note":"快速杀菌，可用于万古霉素耐药或肾毒性高风险者；不可用于肺炎（被肺表面活性物质灭活）","renal":"CrCl <30 减至 q48h 或按说明书调整；透析日透析后给药","hepatic":"无需调整","interact":"与他汀类合用增加肌病风险（建议停用他汀）；与氨基糖苷类合用增加肾毒性"}],"nonDrug":["减压：神经性前足或中足溃疡首选不可拆卸的全接触石膏（TCC），愈合率约 93%；禁忌或不耐受者用膝高/踝高可拆卸减压装置，三线为合脚鞋具＋毡制泡沫；后足溃疡减压证据有限，需个体化","清创：中重度感染尤其合并脓肿、湿性坏疽、气性坏疽或坏死性筋膜炎者 24–48 h 内急诊清创；严重缺血时先切开引流、不扩大清创，血运重建后再彻底清创；慢性溃疡 ≥6 周不愈伴纤维化基底或骨暴露者手术清创","血运重建：ABI ≤0.9 伴组织缺损、TcPO2 <30 mmHg、或规范治疗 4 周创面缩小 <50% 者行下肢 CTA/DSA；目标是恢复至少 1 条直达足部的动脉血流，优先重建溃疡供血动脉（angiosome 原则）；间歇性跛行 <200 m、静息痛或组织坏死为手术适应证","截肢：无法控制的严重感染、不可逆缺血且无法重建、不可治愈溃疡、恶性肿瘤累及或创伤无法修复者；小截肢（趾、经跖骨）尽量保留长度与负重功能，大截肢用于保肢失败者","创面处理：按 TIME 原则准备创床，彻底清创后非缺血创面可用负压治疗；高压氧仅用于标准治疗失败的缺血性创面；避免在缺血未纠正时行皮片/皮瓣移植","骨髓炎：彻底清创＋骨切除后抗生素 3 周；未彻底切除或无法手术者 6 周（部分需 12 周）；抗生素骨水泥仅作为辅助"],"life":["血糖控制：感染期以胰岛素为主，HbA1c 目标 <8%（老年、合并症多者放宽至 8.5%），避免低血糖；感染控制后逐步调整方案","足部护理：每日检查双足（足底用镜子）、温水洗脚后彻底擦干趾缝、涂润肤剂、不赤足行走、鞋袜宽松合脚、由专业人员修剪胼胝与趾甲","IWGDF 风险 2–3 级者每日监测双足皮肤温度，连续 2 天同一部位升高 >2.2 ℃ 提示炎症/溃疡前兆，减少负重并就诊","戒烟、控制血压（<130/80 mmHg）与血脂（LDL-C <1.8 mmol/L），纠正低白蛋白血症","溃疡愈合后穿治疗性鞋具，每 1–3 个月复查；既往截肢者终身随访，复发率 1 年内约 40%"]},"prog":"规范减压、清创、抗感染与血运重建后，神经性溃疡 12 周愈合率可达 70%–90%；合并 PAD 或骨髓炎者愈合率降至 50% 左右，复发率 1 年内约 40%、5 年约 65%。约 17% 患者最终截肢，足溃疡患者 5 年病死率约 30%，大截肢后可达 50%–70%，其预后劣于多数常见恶性肿瘤。","refs":["中国糖尿病足防治指南（2019版，中华医学会糖尿病学分会、中华医学会感染病学分会、中华医学会组织修复与再生分会）","中国糖尿病足防治实践指南（2025，中华烧伤与创面修复杂志）","国际糖尿病足工作组（IWGDF）糖尿病足感染诊断与治疗指南（2023）","国际糖尿病足工作组（IWGDF）糖尿病足预防与管理指南（2023）","中国2型糖尿病防治指南（2020年版，中华医学会糖尿病学分会）"]}]},{"id":"electrolyte","name":"水电解质紊乱","rank":44,"summary":"先算缺失量（自由水、总体钾、钙），再定纠正速度上限与给药浓度/速度，每 2–6 h 复查；纠正过快可致脑水肿、心律失常与转移性钙化。","compare":[{"diseaseId":"ele_hypernatremia","dx":"血清钠 >145 mmol/L，血浆渗透压 >295 mOsm/kg；自由水缺失 = 0.6×体重×(Na/140−1)，尿渗透压 <300 提示尿崩、>600 提示肾外失水","key":"血钠 >145 + 高渗；纠正速度 ≤0.5 mmol/L/h、≤10 mmol/L/24h，先补容量再补自由水"},{"diseaseId":"ele_hypokalemia","dx":"血清钾 <3.5 mmol/L，心电图 T 波低平、ST 压低、U 波（>0.1 mV）、QT 延长；尿钾 >20 mmol/d 提示肾性丢失","key":"血钾 <3.5 + U 波；外周补钾浓度 ≤40 mmol/L、速度 ≤10 mmol/h，伴低镁必须先补镁"},{"diseaseId":"ele_hypocalcemia","dx":"校正钙 <2.1 mmol/L 或游离钙 <1.1 mmol/L；Chvostek/Trousseau 征阳性、QTc >440 ms","key":"校正钙 = 实测钙 + 0.02×(40−白蛋白 g/L)；10% 葡萄糖酸钙 10–20 mL 10 min 静注，随后持续静滴"}],"diseases":[{"id":"ele_hypernatremia","name":"高钠血症","aka":["Hypernatremia","高血钠症","高渗性脱水"],"rank":1,"basic":{"define":"血清钠 >145 mmol/L 的高渗状态，由净水丢失（缺水）或钠摄入/潴留过多（钠多）引起。几乎总伴随水调节异常——渴感减退、无法饮水或 ADH 作用不足，单纯钠摄入过多在肾功能正常者少见。","risk":["渴感减退或无法自主饮水：老年人、意识障碍、气管插管、术后、精神疾病","水丢失增加：发热、大汗、烧伤、腹泻、渗透性利尿（甘露醇、高血糖、管饲）","尿崩症：中枢性（垂体术后、外伤、浸润）或肾性（锂盐、两性霉素 B、高钙、低钾）","钠摄入过多：大量高渗盐水、碳酸氢钠、高钠鼻饲配方、海水溺水","盐皮质激素过多：原发性醛固酮增多症、库欣综合征","医源性：透析液钠浓度过高、大量含钠液体复苏"],"epi":"住院患者高钠血症发生率约 1%–3%，ICU 可达 6%–10%；老年人、神经科与术后患者最常见。血钠 >150 mmol/L 时住院病死率约 20%–30%，>160 mmol/L 可达 40%–60%，且与纠正速度无关，提示其为重症标志。"},"patho":"细胞外液钠升高形成渗透梯度，细胞内水外移导致细胞皱缩。脑细胞皱缩牵拉脑膜血管，可致蛛网膜下腔出血、硬膜下血肿与静脉血栓；急性高钠（<48 h）时脑细胞尚无适应，症状出现早且重。慢性高钠（≥48 h）时脑细胞聚集肌醇、谷氨酰胺等有机溶质恢复容积，此时快速纠正使水迅速进入脑细胞，引发脑水肿、抽搐与脑疝。渴感与 ADH 是两大防御机制：渴感减退或 ADH 缺乏（尿崩）者即使轻度失水也会迅速出现高钠。","dx":{"criteria":["血清钠 >145 mmol/L；轻度 146–149、中度 150–159、重度 ≥160 mmol/L（危重阈值）","血浆渗透压升高：2×Na + 血糖(mmol/L) + BUN(mmol/L) >295 mOsm/kg；或 2×Na + 葡萄糖(mg/dL)/18 + BUN(mg/dL)/2.8","计算自由水缺失：总体水量 TBW = 0.6×体重(kg)（老年男性 0.5、老年女性 0.45、儿童 0.6）；水缺失(L) = TBW × (Na/140 − 1)","尿渗透压鉴别：尿渗透压 <300 mOsm/kg 且尿比重 <1.005 提示尿崩症（水利尿）；尿渗透压 >600–800 mOsm/kg 提示肾外失水（腹泻、发热、出汗）或钠摄入过多","尿钠鉴别：尿钠 <20 mmol/L 提示容量不足（肾外丢失）；尿钠 >40 mmol/L 且容量正常或增多提示钠摄入过多或盐皮质激素过多","尿崩症确诊：禁水试验 8 h 尿渗透压不升高（<300 mOsm/kg），皮下注射去氨加压素后中枢性者尿渗透压升高 >50%，肾性者无反应","容量状态评估：血压、心率、颈静脉、皮肤弹性、体重变化、超声下腔静脉；低容量者先补容量再算自由水缺失","排除高血糖所致假性高钠：血糖每升高 5.6 mmol/L，血钠约下降 1.6 mmol/L（未校正血钠），需用校正值判断"],"workup":["血钠、钾、氯、碳酸氢根、血糖、BUN、肌酐、白蛋白、血钙；同步血与尿渗透压、尿钠、尿比重、尿糖与尿酮体","每日体重与严格出入量记录；必要时中心静脉压或床旁超声评估容量","头颅 CT/MRI：意识障碍、抽搐或疑脑静脉血栓者；注意脑皱缩、蛛网膜下腔出血","禁水-加压素试验：疑尿崩症且病情允许时；高钠未纠正时不宜贸然禁水","垂体 MRI 与垂体前叶激素：中枢性尿崩或术后患者","药物史与管饲配方核查：甘露醇、高渗盐水、碳酸氢钠、高蛋白/高钠营养液"],"grading":"按容量分低容量（缺水为主）、等容量（尿崩症）、高容量（钠摄入过多或盐皮质激素过多）；按病程分急性（<48 h）与慢性（≥48 h）；按程度分轻度 146–149、中度 150–159、重度 ≥160 mmol/L。"},"ddx":[{"name":"低钾血症（ele_hypokalemia）","point":"与本类中低钾血症的鉴别：两者均可出现乏力、意识改变与心律失常，但高钠血症以高渗为核心（口渴、尿崩、发热、皮肤黏膜干燥、血钠 >145、血浆渗透压 >295），低钾血症血钠与渗透压正常，以肌无力、肠麻痹、U 波与 QT 延长为主。低钾本身可致肾性尿崩而继发高钠，需同时测血钾。"},{"name":"糖尿病高渗高血糖综合征（dm_hhs）","point":"血糖常 >33.3 mmol/L、血浆渗透压 >320 mOsm/kg、血钠因稀释可正常或降低，纠正血糖后血钠上升；高钠血症血糖正常，无酮症与严重脱水的高血糖背景。"},{"name":"尿崩症（water_di）","point":"中枢性或肾性尿崩表现为多尿（>3 L/d）、低比重尿（<1.005）、尿渗透压 <300 mOsm/kg，禁水后尿渗透压不升；高钠血症是其结果而非独立疾病，需查清病因。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"高血压伴低钾、ARR 升高、肾素受抑制，血钠轻度升高或正常高值，代谢性碱中毒；高钠血症以失水为主，血压多偏低，肾素因容量不足而升高。"},{"name":"钠摄入过多（医源性/饮食性）","point":"有大量高渗盐水、碳酸氢钠或高钠管饲史，尿钠 >40 mmol/L 且容量增多，停用钠后血钠迅速下降；缺水型高钠尿钠 <20 mmol/L。"},{"name":"高钙血症与低钾血症所致肾性尿崩","point":"血钙 >2.75 mmol/L 或血钾 <3.0 mmol/L 可损害肾浓缩功能，出现多尿与高钠；纠正钙/钾后尿浓缩功能恢复。"}],"tx":{"drug":[{"name":"0.9% 氯化钠（低容量期复苏）","dose":"首 1–2 h 10–20 mL/kg 快速静滴（成人 500–1000 mL），恢复血压与组织灌注；随后按自由水缺失计算改用 0.45% 氯化钠","note":"低容量性高钠先补等张液稳定循环，再补自由水；每 2–4 h 复查血钠，避免在复苏阶段血钠骤降","renal":"少尿或心衰者减量并监测尿量","hepatic":"肝硬化者注意容量负荷与腹水","interact":"与含钙输液同通路可能沉淀；大量生理盐水可致高氯性酸中毒"},{"name":"0.45% 氯化钠（补自由水）","dose":"按自由水缺失量的 1/2 于首个 24 h 补充，余量 24–48 h 补足，另加每日不显性失水 800–1000 mL；输注速度 1–2 mL/kg/h；目标血钠下降 ≤0.5 mmol/L/h、≤10 mmol/L/24h（慢性者 ≤8）","note":"举例：60 kg 男性、血钠 160 mmol/L，TBW = 36 L，水缺失 = 36×(160/140−1) ≈ 5.1 L；首日补 2.5 L 自由水＋不显性失水，余量次日补。急性高钠（<48 h，如溺水、大量高渗盐水）可 1 mmol/L/h 较快纠正","renal":"肾功能不全者易容量负荷，减量并监测尿量","hepatic":"遵说明书","interact":"不与血制品同通路；外周输注注意渗透性静脉炎"},{"name":"5% 葡萄糖注射液（自由水补充）","dose":"按缺失量静脉输注，速度 1–2 mL/kg/h；合并高血糖或酮症者按血糖加短效胰岛素（每 4–6 g 葡萄糖配 1 U）","note":"葡萄糖代谢后相当于纯水，适用于需要补自由水且血糖可控者；糖尿病患者需同步胰岛素，避免高血糖加重渗透性利尿","renal":"少尿者慎用，防水中毒","hepatic":"重度肝病者葡萄糖利用下降，监测血糖","interact":"与胰岛素同用需按血糖滴定；不与含钙液同通路"},{"name":"去氨加压素（中枢性尿崩）","dose":"急性期 1–2 µg 皮下或静注 qd–bid；维持治疗口服醋酸去氨加压素 0.1–0.2 mg tid，或鼻喷 10–20 µg qd–bid，按尿量与血钠调整","note":"用于中枢性尿崩所致高钠；用药后减少饮水可致低钠，需监测血钠；肾性尿崩无效","renal":"肾性尿崩禁用；eGFR <50 时低钠风险增加","hepatic":"遵说明书","interact":"与 NSAIDs、三环类抗抑郁药、卡马西平合用增强抗利尿作用，易致低钠"},{"name":"氢氯噻嗪（肾性尿崩）","dose":"25 mg bid–tid 口服，配合低钠饮食（钠 <2 g/d）与适量限水","note":"通过轻度容量不足增加近端钠水重吸收，减少尿量 30%–50%；对锂盐所致肾性尿崩有效","renal":"eGFR <30 疗效差，慎用","hepatic":"肝病者注意低钾与肝性脑病诱因","interact":"与锂盐合用升高锂浓度；与地高辛合用致低钾加重中毒"},{"name":"呋塞米（高容量型）","dose":"20–40 mg 静推或口服 qd–bid，配合限钠（钠 <2 g/d）","note":"用于钠摄入过多或盐皮质激素过多所致高容量性高钠；单独使用不补自由水会加重高钠，需同时补充水分","renal":"肾功能不全者加量，监测电解质","hepatic":"肝硬化者注意低钾与容量不足","interact":"与氨基糖苷类增加耳肾毒性；与锂盐合用升高锂浓度"}],"nonDrug":["纠正病因：停用高渗盐水、碳酸氢钠与高钠管饲，控制血糖与发热，治疗腹泻，停用致病药物（锂盐、两性霉素 B）","无法饮水者经鼻胃管补自由水，100–200 mL/h 分次给予，同时监测胃残余量与血钠","连续性肾脏替代治疗（CRRT）：血钠 >180 mmol/L、少尿/肾衰、纠正速度难以控制或合并严重酸碱紊乱时，使用低于血钠 10–15 mmol/L 的透析液缓慢降钠","血流动力学监测：低容量者监测尿量（目标 >0.5 mL/kg/h）、中心静脉压或下腔静脉变异度","纠正过快时处理：出现抽搐、意识恶化提示脑水肿，立即停低渗液，必要时用 3% 高渗盐水反向纠正并脱水治疗"],"life":["保证每日饮水 1500–2000 mL（心肾功能允许），口渴机制受损者定时定量喂水","发热、腹泻、大汗时额外补充水分与电解质，不单纯补盐片","记录每日出入量与体重，体重短期下降 >2% 提示失水","尿崩症患者随身携带去氨加压素与疾病卡，避免长时间无法饮水（如长途旅行、手术前禁食）","照护者教育：老年人、卧床与痴呆患者是高钠高危人群，夜间也需供水"]},"prog":"及时识别并纠正者多可完全恢复。血钠 >160 mmol/L 病死率 40%–60%，多死于原发病与合并症。纠正过快（>12 mmol/L/24h）可致脑水肿、抽搐与死亡，慢性高钠者尤其危险；存活者约 10%–20% 遗留认知或运动障碍。","refs":["实用内科学（第16版，人民卫生出版社，2022）水、电解质代谢紊乱篇","内科学（第9版，人民卫生出版社，2018）水、电解质代谢和酸碱平衡失常","UpToDate：高钠血症的病因、临床表现与治疗（2024）","Harrison's Principles of Internal Medicine（21st ed，2022）Disorders of Sodium Concentration"]},{"id":"ele_hypokalemia","name":"低钾血症","aka":["Hypokalemia","低血钾","钾缺乏"],"rank":2,"basic":{"define":"血清钾 <3.5 mmol/L。血清钾仅反映细胞外钾，血钾每下降 1 mmol/L 约代表总体钾缺失 200–400 mmol。按病因分为转移性（钾由细胞外移入细胞内）与丢失性（肾性或肾外丢失），后者占多数。","risk":["利尿剂（噻嗪类、袢利尿剂）与泻药、灌肠滥用","呕吐、腹泻、胃肠减压、肠瘘","原发性醛固酮增多症、库欣综合征、肾动脉狭窄","肾小管酸中毒、Bartter 综合征、Gitelman 综合征","胰岛素、β2 受体激动剂、碱中毒（细胞内转移）","低镁血症、大量出汗、进食不足、酗酒"],"epi":"住院患者约 20% 存在低钾血症，ICU 可达 30%–40%；服用噻嗪类利尿剂者 5%–10% 发生低钾。低钾合并低镁时补钾难以纠正，是临床常见的治疗失败原因。"},"patho":"钾是细胞内主要阳离子，细胞内外梯度由 Na⁺-K⁺-ATP 酶维持，受胰岛素、β2 受体、醛固酮与酸碱状态调节。低钾使细胞膜超极化，神经肌肉兴奋性下降，出现肌无力、腱反射减弱与肠麻痹；心肌复极延长，形成 ST 压低、T 波低平、U 波与 QT 延长，易发生室性早搏、尖端扭转型室速，尤其在洋地黄、低镁或心肌缺血时。慢性低钾还损害肾浓缩功能（肾性尿崩）、诱发代谢性碱中毒与胰岛素分泌障碍。","dx":{"criteria":["血清钾 <3.5 mmol/L；轻度 3.0–3.4、中度 2.5–2.9、重度 <2.5 mmol/L","心电图：T 波低平或倒置、ST 段压低、U 波（振幅 >0.1 mV 或高于同导联 T 波）、QT(U) 延长；重度出现室早、室速、尖端扭转型室速或洋地黄中毒","24 h 尿钾：>20–25 mmol/d 提示肾性丢失；<20 mmol/d 提示肾外丢失（呕吐、腹泻、出汗），但需结合利尿剂使用","随机尿钾/肌酐比或尿钾 >20 mmol/L 提示肾性丢失；尿氯 <20 mmol/L 提示呕吐或既往利尿剂，>40 mmol/L 提示现用利尿剂或 Bartter/Gitelman","血气与电解质：代谢性碱中毒（呕吐、利尿剂、原醛）或代谢性酸中毒（肾小管酸中毒、腹泻）；血镁 <0.7 mmol/L 需同时补镁","血压：高血压伴低钾需筛查原发性醛固酮增多症（ARR）、库欣综合征与肾血管性高血压；血压正常提示利尿剂、胃肠道丢失或肾小管病","排除转移性因素：近期胰岛素、β2 激动剂、碱中毒、甲亢周期性麻痹（查 TSH、FT4、FT3）","排除假性低钾：标本溶血、白细胞 >100×10⁹/L、采血后延迟送检可致假性结果，需复查"],"workup":["血钾复查（避免溶血、避免握拳）、血镁、血钠、血氯、碳酸氢根、血糖、肌酐；动脉血气判断代谢性碱中毒/酸中毒与阴离子间隙","24 h 尿钾、尿氯、尿 pH；必要时尿铵与尿阴离子间隙（肾小管酸中毒）","醛固酮/肾素比值：高血压者常规筛查，需停用干扰药物或校正","甲状腺功能：甲亢周期性麻痹（亚洲青年男性多见，发作时血钾低、尿钾低）","心电图：所有中重度低钾或伴心脏病者，注意 U 波与 QT 延长","肾小管功能与基因检测：年轻起病、家族史、伴低镁或肾钙化者评估 Bartter/Gitelman（SLC12A1、KCNJ1、CLCNKB、SLC12A3）"],"grading":"按血钾分轻度 3.0–3.4、中度 2.5–2.9、重度 <2.5 mmol/L；按病因分转移性与丢失性（肾性/肾外）；按心电图分单纯 T 波改变、U 波与 QT 延长、恶性室性心律失常三级。"},"ddx":[{"name":"低钙血症（ele_hypocalcemia）","point":"与本类中低钙血症的鉴别：两者均可有乏力与 QT 延长，但低钾血症以肌无力、腱反射减弱、肠麻痹、U 波（>0.1 mV）与 ST 压低为主，血钾 <3.5；低钙血症以手足搐搦、口周麻木、Chvostek/Trousseau 征阳性、QT 延长而 T 波直立为特征，血钙（校正后）<2.1 mmol/L。"},{"name":"高钠血症（ele_hypernatremia）","point":"同属水电解质紊乱，均可有乏力与意识改变；高钠以高渗、口渴、尿崩与血钠 >145 为特征，低钾血钠正常、以神经肌肉兴奋性下降与心律失常为主。低钾可致肾性尿崩而继发高钠。"},{"name":"原发性醛固酮增多症（ad_pa）","point":"高血压伴低钾、ARR >20–30、肾素受抑制、代谢性碱中毒，肾上腺 CT 可见腺瘤或双侧增生；是高血压合并低钾必须排除的病因。"},{"name":"肾小管酸中毒","point":"低钾伴高氯性代谢性酸中毒、尿 pH >5.5（远端型）、尿阴离子间隙负值、肾结石与骨病；与呕吐/利尿剂所致碱中毒性低钾相反。"},{"name":"Bartter 与 Gitelman 综合征","point":"年轻起病、血压正常、低钾伴代谢性碱中毒、肾素-醛固酮升高；Gitelman 伴低镁与低钙尿，Bartter 伴肾钙化与前列腺素升高，基因检测确诊。"},{"name":"低钾型周期性瘫痪（ne_periodic_paralysis）","point":"亚洲青年男性多见，饱食、剧烈运动后夜间突发四肢弛缓性瘫痪，血钾低而尿钾低（转移性），补钾后迅速恢复；发作间期血钾正常，甲状腺功能亢进者需治疗甲亢。"},{"name":"利尿剂与胃肠道丢失","point":"有用药、呕吐、腹泻或灌肠史，尿氯低（呕吐）或高（利尿剂），停用诱因后血钾回升；需与内在肾小管病鉴别。"},{"name":"低镁血症","point":"血镁 <0.7 mmol/L 常与低钾并存，单纯补钾难以纠正，需先补镁；常见于酗酒、腹泻、PPI 长期使用与顺铂化疗。"}],"tx":{"drug":[{"name":"氯化钾（口服）","dose":"10% 氯化钾口服液 10–20 mL（1–2 g，约 13–27 mmol 钾）tid–qid，或缓释片 1 g bid–tid；每日补钾 40–100 mmol，严重者不超过 200 mmol/d（约 15 g 氯化钾）","note":"首选口服，餐后服用减少胃肠刺激；缓释片不可嚼碎；1 g 氯化钾 ≈ 13.4 mmol 钾。合并代谢性碱中毒时氯化钾优于枸橼酸钾","renal":"eGFR <30 减量并监测血钾，避免高钾","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB、NSAIDs 合用增加高钾风险；与糖皮质激素合用降低血钾"},{"name":"氯化钾（静脉）","dose":"外周静脉浓度 ≤40 mmol/L（0.3% 氯化钾），速度 ≤10 mmol/h，单次 ≤20 mmol；中心静脉可在心电监护下提高至 20–40 mmol/h；严重低钾（<2.0 mmol/L 或心律失常）按 10–20 mmol/h 起始并每 1–2 h 复查","note":"严禁静脉推注；尿量 <30 mL/h 暂缓补钾；优先用生理盐水稀释（葡萄糖液诱发胰岛素释放可加重低钾）；外周输注注意静脉炎与疼痛","renal":"肾功能不全者减半速度并每 2–4 h 监测血钾","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB 合用增加高钾；与洋地黄合用需纠正低钾以防中毒，但补钾过快可致高钾"},{"name":"门冬氨酸钾镁","dose":"10–20 mL 加入 250–500 mL 5% 葡萄糖注射液静滴 qd（钾含量按说明书），或口服片 1–2 片 tid","note":"适用于低钾伴低镁或心肌应激性增高者；含钾量低于氯化钾，不能替代重度低钾的快速补钾","renal":"肾功能不全者慎用，监测血钾与血镁","hepatic":"重度肝病者慎用","interact":"与保钾利尿剂合用增加高钾风险"},{"name":"硫酸镁（纠正低镁）","dose":"25% 硫酸镁 10–20 mL（2.5–5 g）加入 250–500 mL 液体静滴 1–2 h；或 10% 硫酸镁 10 mL 稀释后缓慢静注；随后按血镁补充，口服门冬氨酸镁或氧化镁维持","note":"血镁 <0.7 mmol/L 时低钾难以纠正，必须同时补镁；补镁期间监测血压、腱反射与呼吸（镁中毒拮抗）","renal":"肾功能不全者减量 50% 并延长输注时间，防镁蓄积","hepatic":"遵说明书","interact":"与氨基糖苷类、顺铂、环孢素合用加重低镁；与肌松药合用增强神经肌肉阻滞"},{"name":"螺内酯（保钾利尿剂）","dose":"20–40 mg bid 口服，最大 100 mg/d；用于原发性醛固酮增多症术前或不宜手术者，或利尿剂所致低钾的辅助","note":"起效 2–3 天，与排钾利尿剂联用可减少钾丢失；肾功能不全者高钾风险高","renal":"eGFR <30 禁用或慎用；监测血钾与肌酐","hepatic":"肝硬化者注意男性乳房发育与月经紊乱","interact":"与 ACEI/ARB、NSAIDs、钾补充剂合用显著增加高钾风险"},{"name":"枸橼酸钾","dose":"10% 枸橼酸钾 10–20 mL tid 口服（1 g 枸橼酸钾约含 9 mmol 钾）；用于合并肾小管酸中毒、低枸橼酸尿或尿路结石者","note":"同时纠正代谢性酸中毒，适用于 RTA；不宜用于需要快速补钾的重度低钾","renal":"肾功能不全者减量，监测血钾","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB 合用增加高钾；与含铝抗酸药合用增加铝吸收"}],"nonDrug":["停用或调整致低钾药物：利尿剂、泻药、胰岛素过量、β2 激动剂；必须使用利尿剂者联合保钾利尿剂或补钾","治疗原发病：原醛单侧腺瘤腹腔镜切除、肾小管酸中毒补碱、Gitelman 补镁、甲亢周期性麻痹控制甲亢","心电监护指征：血钾 <2.5 mmol/L、合并心脏病或洋地黄、QT 延长、静脉补钾 >10 mmol/h","重度低钾伴恶性心律失常或无法静脉补钾者行血液透析（低钾透析液），需持续心电监护","监测频率：静脉补钾每 2–4 h 复查血钾，至 >3.5 mmol/L 后每日 1 次；同时复查血镁与肾功"],"life":["富钾饮食：香蕉、橙、土豆、菠菜、豆类、菌菇，每日钾摄入 3.5–4.7 g；肾功能不全者需限制","避免高钠加工食品与过量咖啡、酒精；大量出汗后补充含钾电解质饮料而非仅补水","服用利尿剂者每 1–3 个月复查血钾与肾功；出现乏力、心悸、便秘及时就诊","缓释钾片随餐整片吞服，不与保钾利尿剂或钾盐替代品叠加","低镁相关低钾者长期补充镁剂并复查血镁，避免长期 PPI 与酗酒"]},"prog":"轻中度低钾口服补钾后 24–48 h 可纠正，但总体钾缺失需数日补足（血钾每升高 1 mmol/L 约需 200–400 mmol 钾）。合并低镁未纠正者复发率高。重度低钾（<2.0 mmol/L）可致尖端扭转型室速、呼吸肌麻痹与横纹肌溶解，及时补钾多可逆转。","refs":["中国慢性肾脏病患者血钾管理实践专家共识（2020，中华医学会肾脏病学分会）","实用内科学（第16版，人民卫生出版社，2022）水、电解质代谢紊乱篇","内科学（第9版，人民卫生出版社，2018）水、电解质代谢和酸碱平衡失常","UpToDate：低钾血症的临床表现与治疗（2024）"]},{"id":"ele_hypocalcemia","name":"低钙血症","aka":["Hypocalcemia","低血钙","低钙性手足搐搦"],"rank":3,"basic":{"define":"血清总钙 <2.1 mmol/L（8.5 mg/dL）或游离钙 <1.1 mmol/L。总钙受白蛋白影响，低白蛋白者需用校正公式；游离钙在有酸碱失衡或低白蛋白时更可靠。按病因分为 PTH 依赖（甲旁减）与非 PTH 依赖（维生素 D 缺乏、低镁、慢性肾病、急性胰腺炎等）。","risk":["甲状腺全切或次全切、甲状旁腺手术（术后暂时性甲旁减 20%–30%）","自身免疫性多内分泌综合征 1 型、DiGeorge 综合征（先天性甲旁减）","低镁血症（甲状旁腺分泌与 PTH 作用受损）","维生素 D 缺乏、吸收不良、慢性肾病（1α 羟化障碍）","急性胰腺炎（皂化）、脓毒症、大量输血（枸橼酸螯合）","双膦酸盐、地舒单抗、化疗（低钙血症）、长期抗癫痫药"],"epi":"甲状腺全切后暂时性低钙血症发生率 20%–30%，永久性甲旁减 1%–4%；ICU 患者低钙发生率 20%–50%。我国北方冬季维生素 D 缺乏普遍，老年人与深肤色人群风险更高。"},"patho":"细胞外钙降低使神经肌肉阈电位下移、兴奋性增高，出现口周与肢端麻木、手足搐搦、喉痉挛与癫痫；心肌复极延长，QT 间期延长，可致低血压、心律失常与低钙性心肌病。PTH 不足时骨钙动员与肾小管钙重吸收减少、磷排泄减少（高磷），活性维生素 D 合成下降进一步降低肠钙吸收。慢性低钙导致骨矿化不足、基底节钙化、白内障与牙齿发育异常。","dx":{"criteria":["校正钙 <2.1 mmol/L：校正钙(mmol/L) = 实测总钙 + 0.02×(40 − 白蛋白 g/L)；或校正钙(mg/dL) = 实测钙 + 0.8×(4.0 − 白蛋白 g/dL)","游离钙 <1.1 mmol/L（正常 1.15–1.30 mmol/L），低白蛋白、碱中毒或危重患者以游离钙为准","神经肌肉兴奋性增高：口周/肢端麻木、手足搐搦、喉痉挛、癫痫；Chvostek 征（叩击面神经致口角抽动）敏感但特异度低，Trousseau 征（袖带充气至收缩压以上 3 min 诱发腕痉挛）特异性更高","心电图：QTc >440 ms、ST 段延长、T 波直立；严重者室速、心力衰竭、低血压","血磷升高、PTH 降低或正常低值提示甲旁减；PTH 升高提示维生素 D 缺乏、慢性肾病或 PTH 抵抗","术后低钙：甲状腺术后 24–48 h 内游离钙 <1.1 mmol/L 或校正钙 <2.0 mmol/L 需处理；术后 PTH <15 pg/mL 提示甲旁减风险高","慢性低钙：24 h 尿钙降低、头颅 CT 见基底节钙化、眼科检查见白内障；需与低钙性心肌病、癫痫鉴别","排除假性低钙：低白蛋白血症、标本 EDTA 污染、大量输液稀释"],"workup":["校正钙、游离钙、白蛋白、镁、磷、碱性磷酸酶；PTH、25(OH)D、1,25(OH)2D 与肾功能（eGFR）","血气（碱中毒使游离钙下降）、心电图（QTc）","甲状腺术后每 6–8 h 监测游离钙至 48–72 h，同时测 PTH","24 h 尿钙与尿肌酐：治疗中监测高钙尿（>300 mg/24h 需减量），治疗前低钙尿支持甲旁减","头颅 CT/MRI（基底节钙化、癫痫）、眼科裂隙灯（白内障）","疑遗传性甲旁减者查 AIRE 基因、22q11.2 缺失（DiGeorge）"],"grading":"按程度分轻度（2.0–2.1 mmol/L，无症状）、中度（1.8–2.0 mmol/L 或症状轻微）、重度（<1.8 mmol/L 或手足搐搦、喉痉挛、癫痫、QT 延长）；按病程分急性与慢性；按病因分 PTH 依赖（甲旁减）与非 PTH 依赖（维生素 D 缺乏、低镁、CKD、胰腺炎）。"},"ddx":[{"name":"低钾血症（ele_hypokalemia）","point":"与本类中低钾血症的鉴别：两者均可有乏力与 QT 延长，但低钙血症以手足搐搦、口周麻木、Chvostek/Trousseau 征阳性、QT 延长伴 T 波直立为特征；低钾血症以肌无力、腱反射减弱、肠麻痹、U 波与 ST 压低为主。两者可并存（如利尿剂＋低镁），需同时测血钾、血镁与血钙。"},{"name":"高钠血症（ele_hypernatremia）","point":"同属水电解质紊乱，严重者均可有意识障碍与抽搐；高钠以高渗、口渴、尿崩与血钠 >145 为特征，低钙血钠正常、以神经肌肉兴奋性增高与 QT 延长为主。"},{"name":"甲状旁腺功能减退症（pt_hypopth）","point":"低钙伴高磷、PTH 降低或正常低值，常有甲状腺手术史；是低钙血症最常见的病因，需长期口服钙＋活性维生素 D。"},{"name":"维生素 D 缺乏与骨软化症","point":"25(OH)D <20 ng/mL、PTH 升高、血磷低或正常、碱性磷酸酶升高，骨痛与近端肌无力；补维生素 D 后低钙纠正。"},{"name":"慢性肾脏病（CKD）相关低钙","point":"eGFR <30、高磷、PTH 显著升高、1,25(OH)2D 降低，常伴高钾与酸中毒；需限磷、补活性维生素 D。"},{"name":"急性胰腺炎","point":"上腹痛、血淀粉酶/脂肪酶升高、影像见胰腺渗出；低钙由脂肪皂化与低白蛋白所致，血钙 <1.75 mmol/L 提示重症。"},{"name":"碱中毒与过度换气","point":"游离钙下降而总钙正常，伴手足麻木与抽搐，血气示 pH 升高、PaCO2 降低；纠正通气后症状缓解。"},{"name":"脓毒症与大量输血","point":"脓毒症致低钙与低白蛋白，输血相关低钙由枸橼酸螯合，输注速度 >100 mL/min 或肝功不全时更易发生；测游离钙可证实。"}],"tx":{"drug":[{"name":"10% 葡萄糖酸钙（急性症状性低钙）","dose":"10–20 mL（1–2 g，含元素钙 2.3–4.6 mmol）加入 50–100 mL 5% 葡萄糖注射液，10 min 内缓慢静注；随后 10% 葡萄糖酸钙 100 mL（9.3 g，约 21.5 mmol 元素钙）加入 500–1000 mL 液体，以元素钙 0.5–1.5 mmol/kg/d 持续静滴","note":"首选外周静脉，避免外渗致组织坏死；注射时心电监护，速度过快可致低血压、心动过缓与心律失常；洋地黄化者减半速度","renal":"肾功能不全者减少维持量，监测血钙与尿钙","hepatic":"遵说明书","interact":"与头孢曲松同通路可沉淀；与洋地黄合用增加心律失常风险；与噻嗪类合用增加高钙风险"},{"name":"10% 氯化钙（紧急或中心静脉）","dose":"10 mL（1 g，含元素钙 273 mg/6.8 mmol）稀释至 20 mL 后 10 min 内缓慢静注；仅用于紧急情况或中心静脉通路","note":"元素钙浓度约为葡萄糖酸钙的 3 倍，刺激性大，外渗可致组织坏死与静脉硬化，禁用于外周小静脉与儿童外周","renal":"同葡萄糖酸钙，监测血钙","hepatic":"遵说明书","interact":"与碳酸氢钠、磷酸盐同通路可沉淀；与洋地黄合用增加毒性"},{"name":"碳酸钙（口服补钙）","dose":"元素钙 500–1000 mg bid–tid，餐中服用（1 g 碳酸钙含元素钙 400 mg）；每日元素钙总量 1–3 g 分次","note":"需胃酸帮助溶解，与 PPI 同服吸收下降；慢性甲旁减需与活性维生素 D 联用，目标血钙 2.0–2.1 mmol/L（正常低值）","renal":"eGFR <30 慎用，防高钙与转移性钙化；监测血钙磷","hepatic":"遵说明书","interact":"与左甲状腺素、铁剂、喹诺酮类、四环素间隔 2–4 h；与噻嗪类合用增加高钙"},{"name":"骨化三醇（活性维生素 D）","dose":"0.25–0.5 µg bid 起始，按血钙调整至 0.5–1.0 µg/d（最大 2 µg/d）；起效 1–2 天，需每周监测血钙直至稳定","note":"甲旁减首选活性维生素 D（肾脏 1α 羟化不足）；与钙剂联用，目标血钙正常低值；过量致高钙尿、肾结石与肾钙化","renal":"CKD 者无需调整剂量，但需监测钙磷乘积","hepatic":"遵说明书","interact":"与噻嗪类合用增加高钙；与洋地黄合用高钙诱发心律失常；与含镁抗酸药合用增加镁吸收"},{"name":"维生素 D3（胆钙化醇）","dose":"1000–2000 IU/d 维持；缺乏者 50000 IU/周×6–8 周（或 6000 IU/d×8 周）后改为维持量，目标 25(OH)D ≥30 ng/mL","note":"用于维生素 D 缺乏所致低钙，需经肝、肾羟化后起效（肾功能不全者改用骨化三醇）；起效需数周","renal":"CKD 4–5 期需用活性维生素 D","hepatic":"重度肝病者羟化不足，改用活性制剂","interact":"与噻嗪类合用增加高钙；与考来烯胺、奥利司他合用减少吸收"},{"name":"硫酸镁（伴低镁）","dose":"25% 硫酸镁 10 mL（2.5 g）加入 250 mL 液体静滴 1–2 h；随后口服镁剂维持，目标血镁 >0.7 mmol/L","note":"低镁不纠正时低钙难以纠正（PTH 分泌与作用受损）；补镁过程监测血压、腱反射与呼吸","renal":"肾功能不全者减量并延长输注，防镁蓄积","hepatic":"遵说明书","interact":"与氨基糖苷类、顺铂合用加重低镁；与肌松药合用增强阻滞"},{"name":"特立帕肽（重组人 PTH 1-34，难治性甲旁减）","dose":"20–40 µg 皮下 bid，按血钙与尿钙滴定；国内说明书适应证为骨质疏松，用于甲旁减属超说明书用药，需专科评估与知情同意","note":"用于钙剂＋活性维生素 D 仍不能维持血钙、或反复高钙尿/肾结石的难治性甲旁减；可减少钙剂用量并改善骨密度","renal":"eGFR <30 慎用（骨质疏松适应证下禁用）","hepatic":"遵说明书","interact":"与洋地黄合用增加高钙相关心律失常；与双膦酸盐序贯使用注意低钙"}],"nonDrug":["急性症状性低钙：立即静脉补钙并心电监护；喉痉挛或癫痫者保持气道通畅、吸氧，必要时气管插管","甲状腺/甲状旁腺术前评估维生素 D 状态并纠正缺乏；术后 24–48 h 每 6–8 h 监测游离钙，必要时自体甲状旁腺移植","慢性甲旁减：口服钙＋活性维生素 D，目标血钙 2.0–2.1 mmol/L（正常低值），24 h 尿钙 <300 mg，每年肾超声筛查结石与肾钙化","纠正低镁与维生素 D 缺乏；慢性肾病者限磷并使用活性维生素 D 与磷结合剂","监测：急性期每 4–6 h 测血钙，稳定后 1–2 周一次，长期每 3–6 个月复查血钙、尿钙与肾功"],"life":["富钙饮食：奶制品、豆制品、深绿色蔬菜，每日元素钙 1000–1200 mg；避免高磷加工食品与大量草酸（菠菜、浓茶）同服钙剂","充足日照（每日 15–30 min），肥胖、老年与深肤色者按需补充维生素 D","甲旁减患者随身携带钙剂与疾病卡，出现口周麻木、手足抽搐立即嚼服钙片并就医","避免过度换气与碱中毒（焦虑时缓慢呼吸），剧烈运动后补充含钙饮品","长期补钙者每年查尿钙、肾超声与血肌酐，防肾结石与肾功能损害"]},"prog":"急性低钙静脉补钙后数分钟至数小时症状缓解，但需持续输注直至口服方案起效。永久性甲旁减需终身钙＋活性维生素 D，约 30% 出现高钙尿或肾结石，10%–20% 发生基底节钙化。低钙性心肌病与心律失常在纠正血钙后可逆；严重喉痉挛与癫痫可致死。","refs":["甲状旁腺功能减退症临床诊疗指南（2018，中华医学会骨质疏松和骨矿盐疾病分会、中华医学会内分泌学分会代谢性骨病学组）","欧洲内分泌学会（ESE）甲状旁腺功能减退症临床实践指南（2015）","维生素 D 及其类似物临床应用共识（2018，中华医学会骨质疏松和骨矿盐疾病分会）","实用内科学（第16版，人民卫生出版社，2022）水、电解质代谢紊乱篇"]}]}]},"ent":{"categories":[{"id":"ent_infect","name":"感染与炎性","rank":1,"summary":"耳鼻咽喉感染以“定位+评估严重度+分层抗感染”为主线：中耳炎先区分单纯型/积液型/化脓型，鼻窦炎先区分病毒性与细菌性，咽扁桃体炎必须先做链球菌/EBV 鉴别再决定是否用抗生素；局部减充血、黏液促排与充分的镇痛退热是共同的基础措施。","compare":[{"diseaseId":"en_otitis","dx":"耳痛、发热，耳镜见鼓膜膨隆、充血或中耳积液/穿孔流脓；婴幼儿以抓耳、哭闹、夜醒为主","key":"耳镜鼓膜膨隆是诊断核心；<6 个月或重症用抗生素，轻症 2 岁以上可观察 48–72 h"},{"diseaseId":"en_sinusitis","dx":"鼻塞、黏脓涕、面颊或额部胀痛、嗅觉减退，症状 >10 天无改善或先轻后重；鼻内镜见中鼻道脓涕","key":"症状 >10 天不缓解或“双相病程”提示细菌性；首选阿莫西林克拉维酸，不建议常规影像"},{"diseaseId":"en_tonsillitis","dx":"咽痛、吞咽痛、发热，扁桃体红肿伴/不伴渗出；需 Centor/McIsaac 评分与快速链球菌检测","key":"渗出+颈淋巴结+无咳嗽提示 GAS；EBV 感染易误用氨苄西林致皮疹，需查异型淋巴细胞"}],"diseases":[{"id":"en_otitis","name":"急性中耳炎","aka":["AOM","Acute Otitis Media","中耳炎","急性化脓性中耳炎"],"rank":1,"basic":{"define":"中耳腔（含鼓室、乳突气房）的急性感染性炎症，多继发于上呼吸道感染后咽鼓管功能障碍。临床分为急性非化脓性（分泌性/积液型）与急性化脓性中耳炎，后者可有鼓膜穿孔流脓。","risk":["年龄 <2 岁（咽鼓管短、平、宽）","上呼吸道病毒感染、过敏性鼻炎导致咽鼓管黏膜肿胀","人工喂养（卧位喂奶）、安抚奶嘴使用","托幼机构集体生活、被动吸烟","免疫缺陷、腭裂、唐氏综合征","既往中耳炎反复发作史"],"epi":"儿童常见病，约 60%–80% 儿童在 3 岁前至少发生 1 次急性中耳炎，6–18 月龄为发病高峰；我国学龄前儿童患病率约 5%–10%，冬春季高发。"},"patho":"上呼吸道病毒或细菌经咽鼓管逆行进入中耳，咽鼓管因黏膜水肿、分泌物阻塞而通气障碍，中耳形成负压并渗出，继发细菌繁殖（肺炎链球菌、流感嗜血杆菌、卡他莫拉菌为主）产生脓性渗出，鼓膜受压膨隆；压力过高可致鼓膜缺血坏死穿孔、脓液外流。炎症累及乳突气房可形成急性乳突炎，婴幼儿因鼓室盖薄可并发脑膜炎。","dx":{"criteria":["急性起病（通常 <48–72 h）的耳痛（婴幼儿表现为抓耳、哭闹、夜醒、拒食）伴或不伴发热","耳镜检查必备：鼓膜明显膨隆（诊断价值最高）；或新发耳漏（非外耳道炎所致）；或轻度膨隆 + 近 48 h 耳痛，或鼓膜充血 + 耳痛 >48 h","鼓气耳镜/声导抗提示中耳积液（B 型鼓室图）支持诊断，单纯鼓膜充血不足以诊断","重症判定：中度以上耳痛或耳痛 >48 h，或体温 ≥39 ℃","鼓膜穿孔者可见搏动性脓性分泌物，听力多呈传导性下降 20–30 dB"],"workup":["耳镜检查（清理外耳道耵聍后），有条件用耳内镜或鼓气耳镜","声导抗/鼓室图：B 型曲线提示中耳积液","纯音测听（成人及能配合儿童）评估传导性听力损失","疑乳突炎：颞骨 CT；疑颅内并发症：头颅增强 MRI","反复发作（半年 ≥3 次或 1 年 ≥4 次）：查免疫功能、腺样体（鼻咽侧位片/鼻内镜）","发热伴耳后红肿压痛、耳廓前移者立即排查急性乳突炎"],"grading":"按病程分急性非化脓性/急性化脓性；按严重度分轻症（耳痛 <48 h、体温 <39 ℃）与重症；按病程分急性（<3 周）、亚急性、慢性（>3 个月）；反复发作型指 6 个月内 ≥3 次。"},"ddx":[{"name":"急性鼻窦炎","point":"与本类中鼻窦炎的鉴别点：中耳炎耳痛位于耳深部、耳镜见鼓膜膨隆；鼻窦炎以鼻塞脓涕+面颊/额部胀痛为主，耳镜正常。"},{"name":"急性外耳道炎（游泳耳）","point":"牵拉耳廓或压耳屏剧痛，外耳道弥漫红肿、有分泌物，鼓膜本身正常；糖尿病/免疫抑制者警惕恶性外耳道炎。"},{"name":"分泌性中耳炎","point":"无急性感染症状，以耳闷、听力下降为主，鼓膜内陷、可见液平或气泡，鼓室图 B 型；观察 3 个月，多数自行吸收。"},{"name":"咽鼓管功能障碍/气压创伤","point":"有飞行、潜水或快速升降压史，耳闷胀痛，鼓膜内陷或鼓室积血，无发热。"},{"name":"乳突炎","point":"中耳炎未控制的并发症：耳后红肿压痛、耳廓前移、发热，需静脉抗生素并评估乳突切开。"}],"tx":{"drug":[{"name":"阿莫西林（首选）","dose":"儿童 80–90 mg/kg/d 分 2 次口服（最大 2 g/d）；成人 500 mg tid 或 875 mg bid，疗程 5–10 天（<2 岁及重症 10 天）","note":"无青霉素过敏、近 30 天未用 β-内酰胺类者首选；用药 48–72 h 无改善需复评或换药","renal":"CrCl 10–30 mL/min 减量或延长给药间隔","hepatic":"轻中度无需调整，重度慎用","interact":"与华法林合用可增强抗凝；别嘌醇增加皮疹风险"},{"name":"阿莫西林克拉维酸钾","dose":"儿童 90 mg/kg/d（按阿莫西林组分）分 2 次；成人 625 mg tid 或 1 g bid","note":"用于近 30 天用过 β-内酰胺类、合并化脓性结膜炎、治疗失败或反复发作","renal":"CrCl <30 mL/min 改用常规剂型并减频","hepatic":"有报道胆汁淤积性肝炎，肝病史者慎用","interact":"同阿莫西林；可降低口服避孕药效果"},{"name":"头孢呋辛酯","dose":"儿童 10–15 mg/kg bid；成人 250–500 mg bid，疗程 5–10 天","note":"青霉素非速发型过敏者的替代；对肺炎链球菌青霉素不敏感株覆盖有限","renal":"CrCl <30 mL/min 减量","hepatic":"遵说明书","interact":"与抗酸药同服降低吸收，需间隔 2 h"},{"name":"对乙酰氨基酚/布洛芬（镇痛退热）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h（最大 75 mg/kg/d）；布洛芬 5–10 mg/kg q6–8h（6 月龄以上）","note":"疼痛管理是必需治疗而非可选；单用镇痛不能替代抗生素指征判断","renal":"布洛芬在脱水、肾功不全者慎用","hepatic":"肝功能不全者对乙酰氨基酚减量，日总量不超过 2 g","interact":"布洛芬与抗凝/抗血小板药合用增加出血风险"},{"name":"左氧氟沙星滴耳液","dose":"鼓膜穿孔者 5–10 滴患耳 tid，疗程 7–10 天","note":"仅用于鼓膜穿孔/耳漏或鼓膜置管者；鼓膜完整者不推荐局部抗生素","renal":"局部用药无需调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"盐酸羟甲唑啉喷鼻剂","dose":"成人及 >6 岁儿童每侧鼻孔 2–3 喷 bid，连续不超过 7 天","note":"短期减轻咽鼓管口黏膜水肿；>7 天可致药物性鼻炎","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与单胺氧化酶抑制剂同用"}],"nonDrug":["观察等待策略：≥2 岁、单侧、轻症、诊断不确定者，48–72 h 内复评，期间充分镇痛；<6 月龄一律用抗生素","鼓膜切开引流：鼓膜明显膨隆剧痛、抗生素 48–72 h 无效、或婴幼儿重症","鼓膜置管：反复急性中耳炎（半年 ≥3 次/1 年 ≥4 次）或持续积液 >3 个月伴听力下降 >20 dB","腺样体切除：合并腺样体肥大阻塞、反复发作的 ≥4 岁儿童可考虑","急性乳突炎：静脉抗生素 + 乳突切开，不缓解者及时手术"],"life":["6 个月内尽量避免卧位奶瓶喂养及安抚奶嘴","避免二手烟；积极治疗过敏性鼻炎与上呼吸道感染","接种肺炎球菌结合疫苗与流感疫苗可降低发病","游泳、洗澡时避免污水入耳（鼓膜穿孔者）","治疗后 4–6 周复查鼓膜与听力（尤其积液持续者）"]},"prog":"多数儿童急性中耳炎 3–7 天内症状自行缓解，抗生素治疗者临床失败率约 10%–20%。约 10%–30% 遗留中耳积液 3 个月以上，可致暂时性传导性听力损失，影响语言发育。严重并发症（乳突炎、面瘫、颅内感染）现已少见但需警惕。","refs":["中华医学会耳鼻咽喉头颈外科学分会《中耳炎临床分类和手术分型指南（2012）》","《儿童急性中耳炎诊疗——临床实践指南（2015 年制定）》","AAP Clinical Practice Guideline: Acute Otitis Media (2013)"]},{"id":"en_sinusitis","name":"鼻窦炎","aka":["急慢性鼻-鼻窦炎","CRS","Acute Rhinosinusitis","鼻窦感染"],"rank":2,"basic":{"define":"鼻窦黏膜的炎症性疾病，常与鼻黏膜炎症并存，故称鼻-鼻窦炎（rhinosinusitis）。按病程分急性（<4 周）、亚急性（4–12 周）、慢性（>12 周，可伴鼻息肉）与复发性急性。约 90%–98% 的急性鼻-鼻窦炎为病毒性上呼吸道感染的延续。","risk":["上呼吸道病毒感染（最常见诱因）","过敏性鼻炎、哮喘（同一气道疾病）","解剖变异：鼻中隔偏曲、中鼻道狭窄","牙源性感染（单侧、恶臭脓涕）","免疫缺陷、纤毛运动障碍、囊性纤维化","吸烟、空气污染、职业粉尘暴露","鼻窦手术史、鼻窦异物或肿瘤"],"epi":"急性鼻-鼻窦炎年发病率约 5%–10%，其中仅 0.5%–2% 转为细菌性；慢性鼻-鼻窦炎在我国患病率约 8%，与哮喘共病率 20%–30%。"},"patho":"病毒或过敏原导致鼻腔黏膜水肿、窦口鼻道复合体阻塞，窦腔通气引流受阻、氧分压下降，纤毛清除功能受损，分泌物潴留继发细菌增殖（肺炎链球菌、流感嗜血杆菌、卡他莫拉菌，慢性者以金黄色葡萄球菌、厌氧菌多见）。慢性鼻-鼻窦炎以 2 型炎症（嗜酸性粒细胞浸润、IL-4/IL-5/IL-13）为主，伴黏膜重塑与息肉形成；局部炎症可经鼻-支气管反射加重哮喘。","dx":{"criteria":["主要症状 ≥2 项：鼻塞/鼻堵、黏脓性鼻涕（前鼻或后鼻滴漏）、面部疼痛/胀痛或压迫感、嗅觉减退或丧失","急性细菌性（ABRS）判定：病程 ≥10 天无改善；或起病即高热（≥39 ℃）+脓涕+面部痛持续 ≥3–4 天；或“双相病程”（先好转再加重）","慢性鼻-鼻窦炎：症状持续 >12 周，伴鼻内镜见中鼻道脓性分泌物/黏膜水肿/息肉，或 CT 显示窦腔黏膜增厚","嗅觉丧失、单侧症状、涕中带血、视力改变需警惕肿瘤或真菌球","鼻内镜是首选检查，可直视中鼻道与窦口"],"workup":["鼻内镜检查：中鼻道、嗅裂脓涕与息肉定位，取分泌物培养（难治者）","鼻窦 CT（冠状位，Lund-Mackay 评分）：用于慢性、复发性、术前评估或疑并发症，急性无并发症者不常规做","过敏原检测（皮肤点刺或血清 sIgE）","血常规、CRP 辅助判断细菌感染","牙源性排查（单侧、恶臭）：口腔检查、牙科全景片","疑眶内/颅内并发症：增强 CT/MRI、眼科会诊、视力视野检查"],"grading":"分急性病毒性/急性细菌性/慢性（伴或不伴鼻息肉）/复发性急性；CT 用 Lund-Mackay（0–24 分，≥4 分提示阳性）；慢性者可用 SNOT-22 量表评估生活质量损害。"},"ddx":[{"name":"急性中耳炎","point":"与本类中急性中耳炎的鉴别点：中耳炎以耳痛+鼓膜膨隆为核心，鼻部症状轻；鼻窦炎以鼻塞脓涕+面部压痛为主，耳镜正常。"},{"name":"普通病毒性上呼吸道感染","point":"病程 <10 天自行缓解，脓涕在病毒感染早期亦常见，不自动提示细菌性；有“双相病程”或 >10 天不缓解才考虑抗生素。"},{"name":"过敏性鼻炎","point":"清水样涕、阵发喷嚏、眼痒，无面部胀痛与脓涕，抗组胺/激素喷鼻有效；但可合并鼻窦炎。"},{"name":"牙源性上颌窦炎","point":"单侧、恶臭味脓涕，牙痛或近期拔牙史，CT 见上颌窦底周围骨破坏，需牙科处理+抗厌氧菌。"},{"name":"鼻窦肿瘤（内翻性乳头状瘤、鼻咽癌）","point":"单侧持续症状、涕中带血、进行性鼻塞、麻木或视力障碍，需内镜活检与影像。"}],"tx":{"drug":[{"name":"阿莫西林克拉维酸钾（ABRS 首选）","dose":"成人 875/125 mg bid 或 625/125 mg tid；儿童 45 mg/kg/d（阿莫西林组分）分 2 次，疗程 5–10 天（推荐 7 天）","note":"近 30 天用过抗生素、或耐药风险高者首选用药；5–7 天无效需复评换药或影像","renal":"CrCl <30 mL/min 减量或延长间隔","hepatic":"肝病史者慎用，警惕胆汁淤积性肝炎","interact":"增强华法林作用；降低口服避孕药效果"},{"name":"多西环素","dose":"成人 100 mg bid，疗程 7 天","note":"青霉素过敏的成人替代方案","renal":"重度肾功能不全慎用","hepatic":"肝功能不全减量","interact":"与抗酸药、铁剂、钙剂螯合，需间隔 2 h；避免与异维 A 酸合用"},{"name":"左氧氟沙星","dose":"成人 500 mg qd（或 750 mg qd），疗程 5–7 天","note":"需保留用药，仅用于 β-内酰胺过敏且疗效失败者；18 岁以下不用","renal":"CrCl <50 mL/min 减量","hepatic":"遵说明书","interact":"与糖皮质激素合用增加肌腱断裂风险；避免与含铝镁抗酸药同服"},{"name":"糠酸莫米松鼻喷雾剂","dose":"成人及 ≥12 岁每侧 2 喷 qd（每喷 50 μg），症状控制后减至每侧 1 喷；慢性者连续使用 ≥12 周","note":"慢性鼻-鼻窦炎一线药物；急性期可缩短病程、减轻黏膜水肿","renal":"无需调整","hepatic":"遵说明书","interact":"与 CYP3A4 强抑制剂（如利托那韦）合用可增加全身暴露"},{"name":"生理性海水/高渗盐水鼻腔冲洗","dose":"每次每侧 10–20 mL，bid–tid，持续 2–4 周；高渗盐水（2%–3%）可用于黏膜明显水肿者","note":"安全有效的基础治疗，可改善鼻塞与黏液清除","renal":"无需调整","hepatic":"无需调整","interact":"无"},{"name":"布地奈德鼻腔雾化/雾化吸入（慢性伴息肉）","dose":"布地奈德混悬液 1 mg bid 鼻腔雾化，或鼻用激素喷剂基础上加用，疗程 8–12 周","note":"用于鼻息肉、术后预防复发；需监测鼻出血与局部刺激","renal":"无需调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["急性病毒性者以对症治疗与随访为主，不需抗生素与影像","慢性鼻-鼻窦炎充分内科治疗 12 周无效、伴鼻息肉或解剖异常者可鼻内镜手术（FESS）","鼻窦负压置换/上颌窦穿刺冲洗：用于儿童慢性鼻窦炎或上颌窦积脓","眶内/颅内并发症（眶周脓肿、脑膜炎）需静脉抗生素+眼科/神外会诊，必要时手术引流","真菌球性鼻窦炎需手术清除，无需抗真菌药"],"life":["积极治疗过敏性鼻炎与哮喘、控制吸烟与空气暴露","鼻腔冲洗每日 1–2 次，症状缓解后继续 2–4 周","阿司匹林加重性呼吸道疾病（AERD）者需避免 NSAIDs","术后定期内镜随访清理，防粘连与息肉复发","复发性者评估免疫球蛋白、纤毛功能与牙源性因素"]},"prog":"急性细菌性鼻-鼻窦炎经规范抗生素治疗后 80%–90% 在 1–2 周内缓解；慢性鼻-鼻窦炎内科+手术联合控制率约 80%，但存在复发，伴鼻息肉与哮喘者复发率更高。眶内或颅内并发症发生率 <1%，但需早期识别。","refs":["中华医学会耳鼻咽喉头颈外科学分会《慢性鼻-鼻窦炎诊断和治疗指南（2018，2022 修订）》","《中国变应性鼻炎诊断和治疗指南（2022，修订版）》","EPOS 2020: European Position Paper on Rhinosinusitis and Nasal Polyps"]},{"id":"en_tonsillitis","name":"咽扁桃体炎","aka":["急性扁桃体炎","咽炎","Acute Pharyngotonsillitis","链球菌性咽炎"],"rank":3,"basic":{"define":"咽黏膜及扁桃体的急性炎症，多由病毒（腺病毒、EBV、鼻病毒）引起，约 15%–30% 成人、20%–40% 儿童由 A 组链球菌（GAS，化脓性链球菌）引起。按病程分急性、慢性，按形态分卡他性、滤泡性、隐窝性（化脓性）。","risk":["学龄期儿童及青少年（5–15 岁 GAS 高发）","托幼机构、军营、集体宿舍等人群密集环境","免疫功能低下、疲劳、受凉","既往风湿热或链球菌感染史","扁桃体隐窝深、反复慢性感染","EBV 感染（传染性单核细胞增多症）"],"epi":"上呼吸道感染门诊最常见疾病之一，GAS 咽炎儿童年发病率可达 20%–30%，多在冬春季；我国抗生素在急性咽痛中不当使用率较高，需先评估链球菌可能性再用药。"},"patho":"病毒或 GAS 附着于咽部上皮，通过黏附素与 M 蛋白抵抗吞噬，释放链球菌溶血素 O、致热外毒素引起黏膜充血、扁桃体肿大与隐窝内脓栓。EBV 则感染 B 淋巴细胞，导致扁桃体弥漫渗出、颈部淋巴结肿大与肝脾受累。炎症可蔓延至扁桃体周围间隙（扁周脓肿）、咽后间隙或颌下间隙；未经治疗的 GAS 感染可诱发风湿热与急性链球菌感染后肾小球肾炎。","dx":{"criteria":["咽痛、吞咽痛（常为首发）、发热，可伴头痛、颈痛、腹痛、乏力","扁桃体红肿，隐窝口可见黄白脓栓；咽后壁充血","病毒性提示：咳嗽、流涕、声嘶、结膜炎、口腔溃疡；EBV：显著颈淋巴结肿大、肝脾肿大、眼睑水肿、皮疹","Centor/McIsaac 评分评估 GAS 可能（发热、无咳嗽、扁桃体渗出、颈前淋巴结压痛、年龄 3–14 岁 +1 / 15–44 岁 0 / ≥45 岁 −1）","快速链球菌抗原检测（RADT）+ 咽拭子培养：儿童阴性需培养确认，成人可仅用 RADT","GAS 诊断需病原学支持，不应仅凭临床","警惕扁周脓肿：单侧剧痛、“马铃薯音”、张口受限、悬雍垂偏移"],"workup":["口咽部视诊与触诊（颈部淋巴结、张口度）","快速 GAS 抗原检测/咽拭子培养（依据 Centor 评分决定）","血常规、CRP（鉴别细菌性/重症）；EBV 抗体（VCA-IgM）与异型淋巴细胞，必要时肝功","EBV 感染：淋巴细胞比例升高、肝酶升高、脾肿大（超声）","疑扁周脓肿：颈部增强 CT 或超声、口咽部穿刺","反复发作者：评估免疫球蛋白、扁桃体慢性炎症程度"],"grading":"Centor/McIsaac 评分（0–5）判断 GAS 概率；扁桃体按形态分度（Ⅰ–Ⅲ 度）；按病程分急性、慢性；并发扁周脓肿按严重度评估是否需引流。"},"ddx":[{"name":"急性中耳炎","point":"与本类中急性中耳炎的鉴别点：中耳炎耳痛+鼓膜膨隆为核心；咽扁桃体炎以咽痛、扁桃体渗出为主，耳部症状多为牵涉痛。"},{"name":"急性鼻窦炎","point":"与本类中鼻窦炎的鉴别点：鼻窦炎以脓性鼻涕+面部胀痛为主；咽扁桃体炎以咽痛、吞痛、发热吞咽困难为主。"},{"name":"传染性单核细胞增多症（EBV）","point":"咽痛伴显著颈淋巴结肿大、肝脾肿大、眼睑水肿，异型淋巴细胞 >10%，EBV-VCA-IgM 阳性；禁用氨苄西林（易致皮疹），避免剧烈运动防脾破裂。"},{"name":"扁桃体周围脓肿","point":"症状单侧化、张口受限、悬雍垂偏移、“热马铃薯音”，需穿刺/切开引流+静脉抗生素。"},{"name":"白喉/溃疡膜性咽炎","point":"咽部灰白色假膜不易剥离、强行剥离出血，伴中毒症状；我国少见但需报告。"},{"name":"HIV 急性感染/急性会厌炎","point":"会厌炎表现为流涎、声音含糊、严重吞咽困难，需避免用力压舌检查，立即气道评估。"}],"tx":{"drug":[{"name":"青霉素 V / 阿莫西林（GAS 首选）","dose":"青霉素 V 成人 500 mg bid 或 250 mg qid，儿童 250 mg bid–tid，疗程 10 天；阿莫西林 成人 500 mg bid–tid，儿童 50 mg/kg qd（最大 1 g）分 1–2 次，疗程 10 天","note":"确诊 GAS 才用；10 天疗程是预防风湿热的关键，不能缩短；不用于病毒性/EBV 咽炎","renal":"CrCl <30 mL/min 减量","hepatic":"遵说明书","interact":"阿莫西林+华法林可增强抗凝；EBV 感染时禁用以防皮疹"},{"name":"阿奇霉素","dose":"成人 500 mg qd×3 天；儿童 10–12 mg/kg qd×3 天","note":"青霉素速发型过敏者替代；我国 GAS 对红霉素耐药率较高，用药前最好依据药敏","renal":"重度肾功能不全慎用","hepatic":"肝病者慎用，警惕 QT 延长","interact":"与 QT 延长药物、华法林合用需谨慎"},{"name":"头孢呋辛酯/头孢氨苄","dose":"头孢氨苄 成人 500 mg bid，儿童 25 mg/kg/d 分 2 次，疗程 10 天","note":"非速发型青霉素过敏者可选；GAS 感染预防风湿热仍需足 10 天","renal":"CrCl <30 mL/min 减量","hepatic":"遵说明书","interact":"与华法林合用增加 INR，需监测"},{"name":"对乙酰氨基酚/布洛芬（镇痛退热）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h；布洛芬 5–10 mg/kg q6–8h，成人 400–600 mg tid","note":"镇痛是咽痛的核心治疗，可显著缩短恢复时间；GAS 感染者镇痛不能替代抗生素","renal":"布洛芬脱水/肾功不全者慎用","hepatic":"严重肝病者对乙酰氨基酚慎用","interact":"遵说明书"},{"name":"地塞米松（重症咽痛短期）","dose":"单剂 8–10 mg 口服/肌注（成人）或 0.15–0.6 mg/kg（儿童，最大 10 mg）","note":"单剂激素可短期缓解成人重度咽痛（24–48 h），需排除扁周脓肿与会厌炎","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血风险"},{"name":"0.12% 氯己定/复方硼砂含漱液","dose":"每次 10–15 mL 含漱 1 min，bid–qid","note":"局部清洁、缓解咽痛不适；不能替代抗感染","renal":"遵说明书","hepatic":"遵说明书","interact":"禁吞服"}],"nonDrug":["扁桃体周围脓肿：穿刺抽脓或切开引流 + 静脉抗生素，必要时气管切开（极重度）","扁桃体切除术指征：1 年内 GAS 咽炎 ≥7 次、或连续 2 年每年 ≥5 次、或连续 3 年每年 ≥3 次；伴阻塞性睡眠呼吸暂停、反复扁周脓肿","会厌炎/咽后脓肿：立即气道保护与静脉抗生素，需耳鼻喉急诊处理","EBV 感染：避免使用氨苄西林类，脾脏肿大者限制运动 4 周"],"life":["充分休息、饮水、软食；发热期卧床","居家隔离至体温正常、抗生素治疗 ≥24 h（GAS）","戒烟酒、避免辛辣刺激与过烫饮食","注意口腔卫生；扁桃体切除术后 2 周软食、避免剧烈运动","风湿热史者需长期二级预防（苄星青霉素）"]},"prog":"病毒性咽炎 3–5 天自行缓解；GAS 咽炎经规范 10 天抗生素治疗后 24–48 h 内症状明显缓解，未治疗者 7–10 天自愈但风湿热风险约 0.3%–3%。扁桃体切除术后 2 周内出血风险约 2%–5%，需警惕。","refs":["中华医学会耳鼻咽喉头颈外科学分会《急性扁桃体炎诊疗专家共识（2022）》","《抗菌药物临床应用指导原则（2015 年版）》","IDSA Clinical Practice Guideline for the Diagnosis and Management of Group A Streptococcal Pharyngitis (2012)"]}]},{"id":"ent_vertigo","name":"眩晕与听力","rank":2,"summary":"眩晕处置的第一步是“区分外周与中枢”：外周以旋转性眩晕+眼震方向不随注视改变+可伴听力/耳鸣为特征；中枢常有神经体征（复视、构音障碍、共济失调），HINTS 检查是关键。耳石症靠 Dix-Hallpike 诊断、Epley 复位治愈；梅尼埃病重在低频听力下降与发作期对症；突发性聋必须 72 h 内判断并尽早用激素，属耳科急症。","compare":[{"diseaseId":"en_bppv","dx":"头位改变（躺下、翻身、抬头）数秒后诱发 <1 min 旋转性眩晕伴眼震，Dix-Hallpike 或 Roll test 阳性，无听力下降","key":"位置性诱发+短暂（<1 min）+Dix-Hallpike 阳性；Epley/Semont 手法复位为首选，多一次复位即愈"},{"diseaseId":"en_md","dx":"反复发作性旋转性眩晕 20 min–12 h + 波动性低频感音神经性听力下降 + 耳鸣/耳闷胀，≥2 次发作且听力学证据","key":"眩晕发作>20 min 伴低频听力下降与耳闷；低盐饮食+倍他司汀，难治者鼓室注射庆大霉素/激素"},{"diseaseId":"en_snhl","dx":"72 h 内突发单侧感音神经性听力下降 ≥30 dB（相邻 3 个频率），可伴耳鸣、耳闷、眩晕","key":"耳科急症：72 h 内确诊并立即全身激素（可联合鼓室注药），高压氧辅助；越早治疗预后越好"}],"diseases":[{"id":"en_bppv","name":"良性阵发性位置性眩晕","aka":["BPPV","耳石症","Benign Paroxysmal Positional Vertigo","位置性眩晕"],"rank":1,"basic":{"define":"因椭圆囊斑的耳石（碳酸钙结晶）脱落进入半规管，头位变动时管腔内淋巴液流动刺激壶腹嵴，产生短暂旋转性眩晕的眼震性疾病，是最常见的周围性眩晕病因。按受累半规管分为后半规管（最多见，70%–90%）、水平半规管（10%–20%）与前半规管（<5%）型。","risk":["年龄 50–70 岁（发生率随年龄上升）","女性多于男性","头部外伤或剧烈摇头（“震荡性”BPPV）","长期卧床、颈部制动、缺乏运动","骨质疏松、维生素 D 缺乏","内耳疾病史（前庭神经炎、梅尼埃病）或内耳术后","偏头痛病史"],"epi":"终生患病率约 2.4%，年发病率约 0.6%，女性为男性约 2 倍，发病年龄多在 50–70 岁；复发率约 15%–50%，1 年复发率约 15%–20%。"},"patho":"耳石从椭圆囊斑变性脱落（沉积于半规管形成“管石症”，或黏附于壶腹嵴形成“嵴帽石症”）。头位改变时管石随重力在半规管内移动，形成淋巴液流动，使壶腹嵴偏离平衡位置，引起与头位改变方向一致、持续数秒至 1 分钟的眼震与眩晕；反复同一头位动作可致疲劳现象（眼震减弱）。","dx":{"criteria":["典型“位置性”眩晕：躺下、起床、翻身、抬头或低头时诱发，持续数秒至 <1 min，多无自主神经症状","Dix-Hallpike 试验（后半规管）：头向一侧转 45°后迅速仰卧悬头，出现潜伏期 1–5 s、上跳扭转型眼震（朝下耳），持续 <1 min","Roll test（水平半规管）：仰卧快速左右转头，出现水平向地性（向地型，管石症）或离地型（嵴帽石症）眼震","无听力下降、无耳鸣、无神经科体征是鉴别关键；眼震方向随注视方向改变（非中枢性垂直/扭转眼震）","HINTS 检查：Dix-Hallpike 引出向上-扭转眼震、头脉冲试验阴性、无眼偏斜可排除中枢"],"workup":["详细位置试验（Dix-Hallpike、Roll test、必要时正侧位试验）观察眼震方向与持续时间","纯音测听与声导抗：BPPV 听力正常，异常时应另寻病因","头脉冲试验（vHIT）、前庭肌源诱发电位（VEMP）辅助鉴定受累半规管/耳石器官","神经系统查体：排除中枢性眩晕；HINTS 三分法","影像学（头颅 MRI）仅在存在中枢体征、非典型眼震、外伤后或复发频繁时进行","维生素 D 水平、骨密度（反复发作/老年人群）"],"grading":"按半规管分为后半规管型、水平半规管型（向地/离地）、前半规管型与多管型；按病程分急性（<1 周）、复发型（≥2 次间隔 >1 周）、顽固型（1 年内 ≥2 次规范复位后复发）。"},"ddx":[{"name":"梅尼埃病","point":"与本类中梅尼埃病的鉴别点：BPPV 仅头位诱发、持续 <1 min、无听力下降；梅尼埃病发作持续 20 min 以上，伴波动性低频听力下降与耳闷。"},{"name":"突发性聋伴眩晕","point":"与本类中突发性聋的鉴别点：突聋有明确单侧听力骤降（≥30 dB），眩晕持续数小时至数天，无位置性眼震；BPPV 听力正常，眩晕仅秒级。"},{"name":"前庭神经炎","point":"持续数十小时至数天的剧烈旋转性眩晕，自发水平-旋转眼震（朝健侧），头脉冲试验阳性，无听力下降，与体位无关。"},{"name":"中枢性眩晕（小脑/脑干卒中、TIA）","point":"伴复视、构音障碍、吞咽困难、偏身麻木、共济失调（DANISH 提示词），HINTS 提示中枢，头脉冲正常伴方向改变眼震；立即 MRI/DWI。"},{"name":"体位性低血压/晕厥前状态","point":"站立时头昏、眼前发黑而非旋转，无眼震，卧位/坐位可缓解，测卧立位血压差 ≥20/10 mmHg。"},{"name":"颈椎性眩晕","point":"常与颈部转位相关但缺乏典型位置性眼震，需排除 BPPV；“颈性眩晕”证据有限，不应作为首选解释。"}],"tx":{"drug":[{"name":"甲磺酸倍他司汀","dose":"12 mg tid 口服，疗程 4–8 周","note":"可改善内耳微循环，缩短复位后残余头晕；非特异性眩晕可使用，BPPV 应以复位为主","renal":"遵说明书","hepatic":"遵说明书","interact":"抗组胺药可拮抗其作用"},{"name":"氟桂利嗪","dose":"5–10 mg 每晚口服，疗程 2–8 周","note":"钙通道阻滞剂，用于眩晕缓解；长期使用可致锥体外系症状与体重增加，老年人慎用","renal":"遵说明书","hepatic":"肝功能不全者慎用","interact":"与中枢抑制剂、酒精合用增强镇静；与 P-gp 抑制剂（胺碘酮）合用需谨慎"},{"name":"茶苯海明/异丙嗪（急性期）","dose":"茶苯海明 50 mg q6–8h；异丙嗪 12.5–25 mg q6h 肌注或口服（≤3 天）","note":"仅用于复位前极重度恶心呕吐者的短程对症，可抑制中枢代偿，不宜久用","renal":"遵说明书","hepatic":"遵说明书","interact":"抗胆碱能作用叠加（抗组胺药、三环类）；老年人致谵妄、尿潴留"},{"name":"昂丹司琼（严重呕吐）","dose":"4 mg 静脉/口服 q8h，短期使用","note":"用于急性期剧烈呕吐无法口服者；需留意 QT 间期","renal":"遵说明书","hepatic":"重度肝功不全者日剂量 ≤8 mg","interact":"与其他 QT 延长药物合用需监测心电图"}],"nonDrug":["后半规管型首选 Epley 手法复位（一次复位成功率 80%–90%，可重复 2–3 次）","水平半规管向地型：Barbecue（360° 翻滚）复位法；离地型（嵴帽石症）：Gufoni 法或健侧卧位","手法复位失败/不能耐受/颈腰椎病限制：可考虑前庭康复器械（如 TRV 椅）或手术（后壶腹神经切断、半规管填塞，极少用）","前庭康复训练：用于复位后残余头晕、反复发作、多管型及老年人防跌倒","复位后 48 h 避免低头、剧烈抬头与快速卧倒（证据有限，但临床常建议）"],"life":["避免诱发体位（低头系鞋带、理发仰头、快速翻身）","补充维生素 D、适量负重运动，骨质疏松者治疗骨病可降低复发","睡眠时垫高枕头 15–20°","老年人注意防跌倒；避免单独驾驶或登高","反复发作者记录发作日记，每月随访至少 3 个月"]},"prog":"手法复位后 70%–90% 患者 1–3 次内症状消失；但复位后可遗留数天至数周的非特异性头晕（残余性头晕），约 15%–50% 会复发，多在 1 年内。老年、骨密度低、多管受累者复发风险更高。总体良性，不影响寿命，但增加跌倒与骨折风险。","refs":["中华医学会耳鼻咽喉头颈外科学分会《良性阵发性位置性眩晕诊断和治疗指南（2017）》","Bárány Society: Clinical Practice Guideline for BPPV (2015, updated 2022)","AAO-HNSF Clinical Practice Guideline: Benign Paroxysmal Positional Vertigo (Update 2017)"]},{"id":"en_md","name":"梅尼埃病","aka":["Ménière's Disease","美尼尔病","内淋巴积水"],"rank":2,"basic":{"define":"以膜迷路积水（内淋巴积水）为病理特征、以反复发作性旋转性眩晕、波动性感音神经性听力下降、耳鸣与耳闷胀感为临床特征的内耳疾病。按 2015 Bárány 学会标准分为确定型（definite）、可能型（probable）与疑似型（possible）。","risk":["发病年龄 40–60 岁（高峰 40–50 岁）","女性略多见","家族聚集（约 5%–15% 有家族史）","自身免疫、病毒感染、内耳缺血","高盐饮食、精神压力、睡眠不足","过敏体质、偏头痛病史","头部外伤史"],"epi":"患病率约 50–200/10 万，年发病率约 15–50/10 万，40–60 岁为发病高峰，双侧受累在 10 年内约 15%–30%，20 年可达 40%。"},"patho":"内淋巴产生与吸收失衡导致膜迷路积水、前庭膜膨出，累及耳蜗与球囊/椭圆囊。积水急性加重时内淋巴压力骤升，前庭毛细胞受机械刺激产生发作性眩晕；长期反复积水致毛细胞退变、Corti 器萎缩，出现不可逆的感音神经性听力下降（早期以低频为主）；破裂学说认为前庭膜破裂后富钾内淋巴流入外淋巴，造成神经毒性。","dx":{"criteria":["确定型梅尼埃病（Bárány 2015）：①≥2 次自发性眩晕发作，每次持续 20 min–12 h；②至少一次纯音测听证实患耳低-中频感音神经性听力下降（至少 2 个连续频率下降 ≥30 dB 或较对侧差 ≥30 dB）；③患耳波动性听觉症状（听力、耳鸣或耳闷胀）；④不能用其他前庭疾病更好解释","可能型：典型眩晕发作 + 波动性听觉症状，但听力学证据不足","眩晕发作常伴恶心、呕吐、冷汗等自主神经症状，发作间期可完全正常","耳鸣多为低音调“嗡嗡”声，耳闷胀感可为发作先兆","发作期可见自发性水平-旋转眼震（向患侧或健侧）"],"workup":["纯音测听（发作期与间歇期均查，观察低频听阈波动）","声导抗、耳声发射（DPOAE、耳蜗电图 SP/AP 比值 >0.4 支持）","前庭功能检查：冷热试验（单侧减弱 >25%）、vHIT、VEMP（球囊/椭圆囊功能）","内耳 MRI（钆增强，3D-FLAIR）显示内淋巴积水，也可排除听神经瘤","排除性检查：甲状腺功能、性病学检查（梅毒）、自身抗体（ANA）、血糖","耳蜗电图/甘油试验（部分医院）辅助诊断"],"grading":"Bárány 2015 分确定型/可能型；听力按 WHO 分级（轻度 26–40 dBHL 至极重度 ≥91 dBHL）；按病程分早期（低频听力损失、可逆）、中期（中高频受累）、晚期（全频听力下降、前庭功能减退）；发作频率按 6 个月内发作次数记录。"},"ddx":[{"name":"良性阵发性位置性眩晕","point":"与本类中 BPPV 的鉴别点：BPPV 由头位变动诱发、持续 <1 min、无听力下降；梅尼埃病为自发性发作，持续 20 min 以上，伴波动性低频听力损失与耳闷。"},{"name":"突发性聋（伴眩晕型）","point":"与本类中突发性聋的鉴别点：突聋为 72 h 内单次听力骤降、通常不复发，眩晕持续数天；梅尼埃病听力呈反复波动、每次发作后可能恢复或渐降。"},{"name":"前庭性偏头痛","point":"眩晕发作 5 min–72 h，伴偏头痛特征（头痛、畏光畏声、视觉先兆），听力多正常或有轻度双侧感音神经性下降，有偏头痛史。"},{"name":"前庭神经炎","point":"单次持续性眩晕数天，无反复发作、无听力下降，冷热试验患侧减弱，恢复期 2–6 周。"},{"name":"听神经瘤","point":"渐进性单侧听力下降+耳鸣，MRI 内听道增强见占位，眩晕不典型（多为不稳感），小脑角征象。"},{"name":"迟发性膜迷路积水","point":"有既往单侧感音神经性聋（如突聋、腮腺炎后），同侧或对侧再出现梅尼埃样发作。"}],"tx":{"drug":[{"name":"甲磺酸倍他司汀","dose":"12–24 mg tid 口服（最大 48 mg tid），长期维持 3–6 个月","note":"改善内耳微循环，减少发作频率；为国内外一线基础治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"抗组胺药拮抗作用，避免同用"},{"name":"氢氯噻嗪/氨苯蝶啶（低盐利尿）","dose":"氢氯噻嗪 25 mg qd 或氨苯蝶啶 50–100 mg qd，监测电解质","note":"通过减容减少内淋巴，需配合限盐（每日 <2 g 钠）；注意低钾、低钠血症","renal":"重度肾功能不全禁用，CrCl <30 慎用","hepatic":"肝性脑病风险者慎用","interact":"与锂盐合用增加锂蓄积；NSAIDs 减弱利尿作用"},{"name":"地西泮/异丙嗪（急性发作对症）","dose":"地西泮 2.5–5 mg 口服或静推；异丙嗪 25 mg 肌注 q6h（≤3 天）","note":"仅用于发作期剧烈眩晕、呕吐；止吐后停用，避免长期使用影响前庭代偿","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与阿片类、酒精等中枢抑制剂合用致呼吸抑制"},{"name":"托吡酯（难治性或伴偏头痛）","dose":"起始 25 mg qn，2 周递增至 50–100 mg/d","note":"可减少发作频率；不良反应包括嗜睡、认知下降、肾结石，需缓慢滴定","renal":"CrCl <70 mL/min 减至半量","hepatic":"遵说明书","interact":"与碳酸酐酶抑制剂合用增加结石风险；可降低口服避孕药效果"},{"name":"地塞米松鼓室注射","dose":"地塞米松 5 mg/mL，每次 0.3–0.5 mL 鼓室注射，每周 1–2 次，共 4–6 次","note":"用于急性发作期或难治性梅尼埃病，可控制眩晕与保存听力，需专科操作","renal":"局部用药无需调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"庆大霉素鼓室注射（难治性/单侧）","dose":"40 mg/mL 每次 0.3–0.5 mL，单次注射后 4 周评估，必要时重复，单侧耳专用","note":"化学性迷路切除，适用于单侧、听力已损失且保守无效者；有听力进一步下降与失衡风险，需听力监测","renal":"局部用药无需调整","hepatic":"遵说明书","interact":"避免与其他耳毒性药物（袢利尿剂、氨基糖苷类全身用药）同用"}],"nonDrug":["生活方式管理：限盐、戒咖啡因与酒精、规律作息，是一线非药物措施","前庭康复训练：改善发作间期不稳感、促进前庭代偿","鼓室压力脉冲治疗（Meniett）：部分难治患者可选，证据强度中等","手术：保守治疗 6–12 个月无效、发作频繁严重影响生活者，可行内淋巴囊减压（疗效争议）、前庭神经切断（听力可保留）或迷路切除（听力已失者）","双侧受累者慎用破坏性手术，优先保守与康复"],"life":["低盐饮食（每日钠 <2 g）、避免高盐加工食品与味精","戒酒、限咖啡因与尼古丁，规律睡眠减少发作","发作时卧床、闭目、避光避声，避免跌倒外伤","避免高空作业与独自驾驶（发作不可预测）","定期复查听力（每 3–6 个月）与前庭功能，记录发作日记"]},"prog":"多数患者为发作-缓解型，约 60%–80% 发作频率随病程递减甚至停止，但约 30%–50% 出现进行性、不可逆的感音神经性听力下降。双侧受累风险随病程增加（10 年约 15%–30%），晚期可致平衡功能障碍，但不危及生命。","refs":["中华医学会耳鼻咽喉头颈外科学分会《梅尼埃病诊断和治疗指南（2017）》","Bárány Society: Diagnostic Criteria for Ménière's Disease (2015)","AAO-HNSF Clinical Practice Guideline: Ménière's Disease (2020)"]},{"id":"en_snhl","name":"突发性聋","aka":["SSNHL","Sudden Sensorineural Hearing Loss","特发性突聋","突发性听力损失"],"rank":3,"basic":{"define":"72 h 内突然发生的、原因不明的感音神经性听力损失，至少在相邻的 3 个频率听力下降 ≥30 dB（按我国 2015 年标准）。病因不明的称为特发性突发性聋（占多数），需排除听神经瘤、感染、血管性、免疫性等其他明确病因。","risk":["中老年（发病高峰 40–60 岁）","高血压、糖尿病、血脂异常、高同型半胱氨酸血症","吸烟、饮酒、精神紧张、睡眠不足","血管疾病（微血栓、血管痉挛、内耳缺血）","病毒感染史（腮腺炎病毒、巨细胞病毒、单纯疱疹病毒）","自身免疫性疾病","噪声暴露、气压创伤；头部外伤"],"epi":"年发病率约 5–20/10 万，近年呈上升与年轻化趋势；我国每年新发约 4 万–10 万例。约 30%–50% 未治疗者可自行部分恢复，但合并眩晕者预后较差。"},"patho":"主要机制包括内耳微循环障碍（血管痉挛、微血栓、血液黏稠度增高导致耳蜗毛细胞缺血缺氧）、病毒感染（病毒侵犯耳蜗与螺旋神经节）、自身免疫反应与膜迷路破裂。耳蜗毛细胞与外毛细胞受损后不能再生，缺血 30 min 即可出现不可逆坏死，故治疗窗口极短（发病 72 h 内、1–2 周内治疗最佳）。","dx":{"criteria":["72 h 内突然发生单侧（偶可双侧）听力下降","纯音测听：至少 3 个连续频率听阈下降 ≥30 dB（我国标准）或较对侧差 ≥15 dB（部分标准）","可伴耳鸣（约 80%）、耳闷胀、耳周麻木、眩晕（约 30%–50%）","听力图分型：低频下降型、高频下降型、平坦型（最常见，预后差）、全聋型","必须排除：听神经瘤（MRI）、梅尼埃病、血管性、感染性、免疫性、外伤性及药物性","双侧同时突发需警惕自身免疫病、梅毒、Cogan 综合征"],"workup":["纯音测听（双耳气骨导）+ 声导抗 + 耳声发射（DPOAE、OAE 对侧抑制）","内听道 + 延髓 MRI（钆增强）排除听神经瘤、多发性硬化；发病 1 个月内完成","血常规、血糖、血脂、肝肾功能、凝血功能、同型半胱氨酸","自身抗体（ANA、抗内耳抗体）、梅毒血清学、病毒抗原/抗体（按需）","眩晕者加查前庭功能（冷热试验、vHIT）与耳蜗电图","疑血管性（椎基底动脉狭窄）加做颈动脉超声/TCD"],"grading":"按听力图形分低频下降型、高频下降型、平坦型、全聋型；按听力损失程度分级：轻度 26–40 dB、中度 41–60 dB、重度 61–80 dB、极重度 81–90 dB、全聋 >90 dB；按预后分（平坦型+眩晕者预后差）。"},"ddx":[{"name":"梅尼埃病","point":"与本类中梅尼埃病的鉴别点：梅尼埃病为反复发作、低频听力波动可恢复、伴耳鸣/耳闷>20 min 眩晕；突聋为单次骤降、早期不恢复，复发少。"},{"name":"良性阵发性位置性眩晕","point":"与本类中 BPPV 的鉴别点：BPPV 无听力下降，眩晕仅头位诱发且 <1 min；突聋以听力骤降为主、眩晕持续数天，任何与听力下降同时出现的眩晕都应先按突聋处理。"},{"name":"听神经瘤（前庭神经鞘瘤）","point":"听力下降多为渐进性、伴单侧耳鸣与不稳感；MRI 内听道增强见占位。所有突聋患者应做 MRI。"},{"name":"前庭神经炎","point":"急性持续性眩晕数天，纯音测听正常；若伴听力下降（尤其低频）应按突聋处理。"},{"name":"耵聍栓塞/中耳积液（传导性听力下降）","point":"纯音测听气骨导差 >10 dB、耳镜检查见耵聍或中耳积液，声导抗 B/C 型；清理或治疗后可恢复。"},{"name":"自身免疫性内耳病/双耳突聋","point":"双侧对称、快速进展，ANA 或抗内耳抗体阳性，多伴其他自身免疫病，需大剂量激素+免疫抑制。"}],"tx":{"drug":[{"name":"泼尼松/甲泼尼龙（全身激素，首选）","dose":"泼尼松 1 mg/kg/d（最大 60 mg）晨起顿服，疗程 10–14 天后逐渐减量；或甲泼尼龙 40–80 mg/d 静脉×3–5 天后改口服","note":"发病 72 h 内用药获益最大，2 周内仍可尝试；需监测血糖、血压、消化道反应，结核/肝炎活动期、严重糖尿病与精神病史者需权衡","renal":"无需调整","hepatic":"肝功能不全者需调整剂量","interact":"与 NSAIDs 合用增加消化道出血；与 CYP3A4 抑制剂（酮康唑）合用增加暴露；拮抗降糖药"},{"name":"地塞米松鼓室注射（挽救/禁忌全身激素）","dose":"地塞米松 5 mg/mL，每次 0.3–0.5 mL 经鼓膜注入中耳，每周 1–2 次，共 4 次","note":"适合全身激素禁忌或疗效不佳者，可与全身治疗联合；保留听力、全身副作用小","renal":"无需调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"甲钴胺/维生素 B12","dose":"甲钴胺 0.5 mg tid 口服或 0.5 mg 隔日肌注","note":"神经营养辅助，证据有限但国内常用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"银杏叶提取物注射液","dose":"遵说明书（常用 17.5–35 mg 静滴 bid）","note":"改善内耳微循环，国内指南列为可选，证据等级有限；注意与抗凝药合用出血风险","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗凝/抗血小板药合用增加出血风险"},{"name":"前列地尔（改善微循环）","dose":"10 μg 加入生理盐水静滴 qd，疗程 7–10 天","note":"部分研究支持改善内耳血流，国内可选；禁用于严重心衰、青光眼","renal":"重度肾功不全慎用","hepatic":"遵说明书","interact":"与抗凝药合用增强出血"},{"name":"改善循环/抗凝辅助（巴曲酶等）","dose":"遵说明书","note":"国内部分医院用于平坦型/全聋型伴凝血异常者，需凝血监测；证据不统一，不作为常规","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗凝/抗血小板药合用增加出血"}],"nonDrug":["高压氧（HBOT）：发病 2 周内、尤其中重度突聋，与激素联合可提高听力恢复率；1.5–2.0 ATA、每日 1 次、共 10–20 次","前庭康复：伴眩晕、平衡障碍者早期介入","助听器/人工耳蜗：治疗 3 个月以上听力未恢复（≥70 dB 或全聋）者评估","鼓室注药：全身激素禁忌、或系统治疗后 2 周无效者挽救治疗","避免使用耳毒性药物（氨基糖苷类、袢利尿剂大剂量、顺铂）"],"life":["立即休息、避免噪声暴露与精神紧张","控制血压、血糖、血脂、体重，戒烟限酒","治疗 2 周复评听力，3 个月评估最终听力水平","单侧永久性听力损失者避免在噪声环境及嘈杂交通中依赖患耳，注意声源定位安全","随访心理支持：耳鸣与听力障碍可致焦虑抑郁，必要时心理干预"]},"prog":"未经治疗者约 30%–65% 部分或完全恢复；及时激素治疗者恢复率约 50%–70%。低频下降型预后最好，全聋型与平坦型伴眩晕者预后差。恢复多发生在 2 周内，3 个月后基本定型；对侧耳长期有亚临床受累风险，应随访。","refs":["中华医学会耳鼻咽喉头颈外科学分会《突发性聋诊断和治疗指南（2015）》","AAO-HNSF Clinical Practice Guideline: Sudden Hearing Loss (Update 2019)","Chinese Medical Association Consensus on Hyperbaric Oxygen Therapy for Sudden Deafness (2021)"]}]},{"id":"ent_tumor","name":"头颈肿瘤","rank":3,"summary":"头颈肿瘤遵循“症状→内镜/触诊定位→组织病理确诊→分期→多学科综合治疗”：鼻咽癌以 EBV 血清学与无痛性上颈肿块为入口，放疗为核心；喉癌以进行性声嘶为核心，早中期保喉、晚期全喉；颈部肿块按甲状腺/淋巴结/唾液腺三条路径鉴别；OSAHS 外科决策须先有 PSG 分型与 CPAP 评估。","compare":[{"diseaseId":"en_npc","dx":"回吸性血涕、单侧鼻塞/耳闷、上颈无痛性淋巴结肿大；鼻内镜见鼻咽部肿物，EBV VCA-IgA 升高","key":"EBV 抗体初筛+鼻内镜活检确诊；首选调强放疗 (IMRT)"},{"diseaseId":"en_larynx_ca","dx":"声嘶进行性 >2 周，可伴吞咽痛、颈部肿块、呼吸困难；电子喉镜见声带/室带肿物","key":"必须喉镜+活检；早期放疗或经口激光，中晚期喉部分/全切除"},{"diseaseId":"en_thyroid_neck","dx":"颈前肿块随吞咽移动、颈侧质韧淋巴结或耳下/颌下肿块；超声+细针穿刺 (FNA)","key":"先定位来源，FNA 细胞学 TIBSRTC 分级决定手术"},{"diseaseId":"en_osahs_surg","dx":"打鼾+目击呼吸暂停+日间嗜睡；PSG 示 AHI ≥5 伴症状或 ≥15","key":"PSG 诊断；CPAP 一线，手术限明确适应证或 CPAP 不耐受"}],"diseases":[{"id":"en_npc","name":"鼻咽癌","aka":["NPC","Nasopharyngeal Carcinoma","鼻咽恶性肿瘤"],"rank":1,"basic":{"define":"鼻咽黏膜上皮来源的恶性肿瘤，绝大多数为未分化型非角化性癌 (EBV 潜伏感染相关) 。部位隐蔽，确诊时多为局部晚期，颈部淋巴结转移率高。","risk":["EB 病毒感染 (VCA-IgA/EBNA1-IgA 高滴度)","广东、广西等华南地区及东南亚人群","咸鱼与腌制品 (亚硝胺) 长期摄入","吸烟、头颈放疗史、一级亲属鼻咽癌家族史","男性 (男女约 2–3:1) ，40–60 岁高发"],"epi":"我国年发病率 3–10/10 万，广东部分地区达 20–30/10 万。IMRT 时代Ⅰ–Ⅱ期 5 年生存率 >85%，Ⅳ期约 50%–60%。"},"patho":"EBV 潜伏蛋白 LMP1/LMP2/EBNA1 激活 NF-κB、PI3K/Akt 通路，促进增殖并免疫逃逸；肿瘤起自咽隐窝，上侵颅底与颅神经，向前侵鼻腔，经淋巴早期转移至咽后与颈深上组。WHO 分角化性 (Ⅰ) 、非角化性 (Ⅱ，我国多见) 、基底样 (Ⅲ) 三型。","dx":{"criteria":["必须有鼻咽活检病理确诊，影像与血清学不能替代","首发表现：无痛性上颈 (Ⅱ区) 肿块约 40%–60%、回吸性血涕/鼻塞约 30%、单侧耳闷与分泌性中耳炎约 20%","晚期：头痛、复视、面部麻木 (三叉神经) 、声嘶呛咳 (Ⅸ–Ⅻ 颅神经) 及远处骨/肺/肝转移","EBV VCA-IgA 与 EBNA1-IgA 双阳性支持诊断与筛查；血浆 EBV DNA 用于分期、疗效与复发监测","TNM (AJCC 第 8 版) ：T1 局限鼻咽或累及口咽/鼻腔；T2 咽旁间隙；T3 颅底/鼻窦；T4 颅内/颅神经/眼眶；N1 单侧 Ⅱ区或咽后 ≤6 cm，N2 双侧，N3 >6 cm 或锁骨上"],"workup":["电子鼻咽镜多点活检 (必要时 CT 引导) ，重点观察咽隐窝与顶后壁","鼻咽+颈部 MRI (首选) 或增强 CT，评估颅底与淋巴结","PET-CT 或骨扫描+胸腹 CT：Ⅲ–Ⅳ期分期与远处转移筛查","EBV DNA 定量 (基线、治疗中、随访) 与 VCA-IgA/EBNA1-IgA","颅神经查体、纯音测听；放疗前牙科处理","病理 EBER 原位杂交、CK、p40 免疫组化"],"grading":"WHO 病理 Ⅰ/Ⅱ/Ⅲ 型；AJCC 第 8 版 TNM 分Ⅰ–ⅣA/ⅣB/ⅣC 期；复发分局部区域复发与远处转移。"},"ddx":[{"name":"喉癌","point":"与本类中喉癌的鉴别：喉癌有声嘶、喉镜见声带肿物；鼻咽癌喉镜正常，以血涕、耳闷、颅神经症状及上颈淋巴结为主。"},{"name":"颈部肿块 (甲状腺/淋巴结)","point":"鼻咽癌常以颈部肿块首发，成人单侧上颈质硬淋巴结必须查鼻咽部+EBV 抗体与 DNA。"},{"name":"鼻咽 NK/T 细胞淋巴瘤","point":"涕血、恶臭坏死性病变、可伴高热；EBER 多阳性但病理为淋巴样细胞浸润，靠免疫表型 (CD56、TIA-1) 确诊，以放疗+化疗为主。"},{"name":"鼻咽炎/腺样体肥大","point":"黏膜光滑无溃疡占位；症状持续 >2 周单侧鼻塞或涕血者必须活检。"},{"name":"颅底脊索瘤","point":"以颅底骨破坏与复视为主要表现，MRI T2WI 高信号，病理见脊索样细胞。"}],"tx":{"drug":[{"name":"顺铂 (同步放化疗)","dose":"100 mg/m² q3w 共 3 周期，或 40 mg/m² 每周一次，由肿瘤科按体表面积与肾功能核定","note":"局部晚期 IMRT 同步顺铂为标准；需水化、止吐与耳肾毒性监测","renal":"CrCl <60 mL/min 减量或改卡铂","hepatic":"遵说明书","interact":"避免与氨基糖苷类、袢利尿剂同用"},{"name":"TPF 诱导化疗 (多西他赛+顺铂+5-FU)","dose":"多西他赛 60–75 mg/m² + 顺铂 60–75 mg/m² + 5-FU 600–750 mg/m²/d×5 d，q3w 共 3 周期","note":"用于 N2–N3 或肿瘤负荷大的局部晚期；需 G-CSF 支持","renal":"顺铂按 CrCl 调整","hepatic":"5-FU 肝功不全减量","interact":"5-FU 显著增强华法林抗凝"},{"name":"吉西他滨+顺铂 (复发转移一线)","dose":"吉西他滨 1000 mg/m² d1、d8 + 顺铂 80 mg/m² d1，q3w","note":"复发/转移性鼻咽癌一线，可联合 PD-1 抑制剂","renal":"按 CrCl 调整顺铂","hepatic":"遵说明书","interact":"耳肾毒性叠加"},{"name":"PD-1 抑制剂 (卡瑞利珠单抗/特瑞普利单抗)","dose":"遵说明书 (按体重或固定剂量，q2w–q3w 静滴)","note":"复发/转移二线及联合化疗；需监测免疫相关不良反应","renal":"遵说明书","hepatic":"遵说明书","interact":"长期激素可削弱疗效"}],"nonDrug":["IMRT：T1–T2N0 单纯放疗，原发灶 66–70 Gy/30–35 次，颈部预防 50–60 Gy","局部晚期：IMRT 同步顺铂 ± 诱导化疗，放疗后 3 个月评估残留","颈部残留淋巴结：放疗后 12 周 PET-CT 评估，SUV 高者行颈清扫","复发：再次放疗 (立体定向/近距) 或手术挽救；远处转移以全身治疗为主","放疗前牙科处理，放疗中与放疗后口腔、皮肤、听力保护"],"life":["放疗期高蛋白高热量饮食；放疗后每日张口练习 ≥3 年","口干者保持饮水、防治龋齿与放射性骨坏死","戒烟酒，避免腌制食品","前 2 年每 3 个月复查鼻咽镜+颈部 MRI+EBV DNA，第 3–5 年每 6 个月，之后每年","高发区人群 EBV 双抗体筛查，阳性者行鼻内镜检查"]},"prog":"Ⅰ–Ⅱ期 5 年总生存 85%–95%，Ⅲ期 75%–85%，ⅣA 期 60%–70%，ⅣB/ⅣC 期 20%–50%。主要失败模式为远处转移 (骨、肺、肝) 与局部复发；EBV DNA 复升是复发/转移的重要预警。","refs":["CSCO《鼻咽癌诊疗指南》(2023)","国家卫生健康委员会《肿瘤诊疗规范》(鼻咽癌分册)","NCCN Guidelines: Head and Neck Cancers – Nasopharyngeal Carcinoma (2023)"]},{"id":"en_larynx_ca","name":"喉癌","aka":["Laryngeal Cancer","Laryngeal Carcinoma","声带癌"],"rank":2,"basic":{"define":"喉黏膜上皮性恶性肿瘤，95% 以上为鳞状细胞癌。按部位分声门上型、声门型、声门下型。声门型早期即有声嘶、预后最好；声门上型症状隐匿且易伴颈淋巴结转移。","risk":["吸烟 (最重要，剂量-时间相关)","长期饮酒，与吸烟协同","男性，60–70 岁高发 (男女比 7–10:1)","职业接触石棉、木屑、镍、芥子气","头颈放疗史 (如鼻咽癌放疗后)","喉白斑、喉乳头状瘤等癌前病变"],"epi":"我国年发病率约 1.5–2/10 万，占头颈恶性肿瘤 10%–15%，声门型约占半数。早期声门癌 5 年生存率 >90%，晚期降至 40%–60%。"},"patho":"烟雾与酒精致喉黏膜多阶段癌变 (TP53 突变、CCND1 扩增、CDKN2A 缺失) 。声门区淋巴管稀少、早期少转移；声门上区淋巴丰富，易转移至颈深上组 (Ⅱ、Ⅲ区) ；声门下引流至气管旁。侵犯甲状软骨外可致声带固定与颈部肿块；侵犯气道引起呼吸困难。","dx":{"criteria":["声门型：声嘶持续 >2–3 周并进行性加重，可伴痰中带血","声门上型：咽异物感、吞咽痛、耳痛 (牵涉) 、颈部肿块 (约 30%–40% 首诊即有)","声门下型：早期无症状，进展后呼吸困难、喘鸣","电子纤维喉镜/支撑喉镜见肿物，表面糜烂或菜花状，声带活动受限","必须活检病理确诊；cN+ 行颈部增强 CT/MRI 与超声","TNM (声门型) ：T1 局限声带、活动正常；T2 声门上/下受累或活动受限；T3 内板破坏或声带固定；T4 穿破甲状软骨/侵犯喉外"],"workup":["电子纤维喉镜 (必要时 NBI) 与支撑喉镜病检","颈部增强 CT (骨窗) +MRI：评估软骨破坏、外侵与 Ⅱ–Ⅵ区淋巴结","胸部 CT、上消化道内镜；疑远处转移做 PET-CT","嗓音评估 (GRBAS、VHI) 、肺功能与吞咽评估","术前明确声带活动度以确定 T 分期"],"grading":"按部位分声门上型、声门型、声门下型；AJCC 第 8 版 TNM Ⅰ–ⅣC 期；病理分级 G1–G3；KPS/ECOG 功能评分。"},"ddx":[{"name":"鼻咽癌","point":"与本类中鼻咽癌的鉴别：鼻咽癌声嘶多为Ⅹ神经受累、声带麻痹而黏膜光滑，伴鼻塞血涕与上颈淋巴结；喉癌声带见肿物。"},{"name":"声带息肉/小结","point":"息肉多为前中 1/3 广基水肿样，与用声相关；小结双侧对称；均无糜烂与颈淋巴结，不能排除者须活检。"},{"name":"喉白斑/乳头状瘤","point":"白斑为白色斑块需活检排除原位癌；乳头状瘤呈多发乳头状、HPV-6/11 相关，反复切除随访。"},{"name":"喉结核","point":"后连合区鼠咬状溃疡或肉芽，伴肺结核表现，痰抗酸/核酸阳性。"},{"name":"接触性肉芽肿/声带麻痹","point":"肉芽肿位于声带突后连合，组织学为肉芽组织；声带麻痹者声带光滑固定，需查甲状腺/纵隔病变。"}],"tx":{"drug":[{"name":"顺铂 (同步放化疗)","dose":"100 mg/m² q3w 或 40 mg/m² 每周，与放疗同步，按肾功能核定","note":"用于 Ⅲ–Ⅳ期器官保留或术后高危辅助","renal":"CrCl <60 减量，<50 慎用","hepatic":"遵说明书","interact":"避免耳肾毒性药物合用"},{"name":"西妥昔单抗 (顺铂不耐受者放疗增敏)","dose":"首剂 400 mg/m²，此后 250 mg/m² 每周一次，与放疗同期","note":"注意皮疹、低镁血症与输液反应","renal":"遵说明书","hepatic":"遵说明书","interact":"与含铂方案合用骨髓抑制与腹泻增加"},{"name":"TPF 方案 (诱导/姑息)","dose":"多西他赛 75 mg/m² + 顺铂 75 mg/m² + 5-FU 750 mg/m²/d×5 d，q3w","note":"复发/转移或高危术后；需 G-CSF 支持","renal":"顺铂按 CrCl 调整","hepatic":"5-FU 肝功不全减量","interact":"5-FU 增强华法林作用"},{"name":"质子泵抑制剂 (放疗期黏膜/反流保护)","dose":"奥美拉唑 20 mg qd 或泮托拉唑 40 mg qd，放疗期至结束后 4–8 周","note":"减轻放射性食管炎与咽喉反流","renal":"无需调整","hepatic":"重度肝功不全减量","interact":"奥美拉唑降低氯吡格雷疗效"},{"name":"镇痛 (放疗黏膜炎/术后)","dose":"对乙酰氨基酚 500–1000 mg q6h (日 ≤3 g) ；中重度阿片类按滴定，遵说明书","note":"放疗第 3–5 周黏膜炎最重，需规范镇痛与营养支持","renal":"阿片类肾功不全减量","hepatic":"对乙酰氨基酚减量","interact":"与镇静药叠加呼吸抑制"}],"nonDrug":["T1–T2 声门型：经口 CO2 激光显微手术 (TOLS) 或放疗 66–70 Gy，局部控制相近","T3：喉部分切除 (垂直/环状软骨上) ±术后放疗；T4 或软骨广泛破坏行全喉切除+术后放疗","声门上型中晚期：喉部分切除或全喉切除+选择性颈清扫 (Ⅱ–Ⅳ区)","颈部处理：cN+ 颈清扫+术后放疗；声门上 cN0 可选择性颈清扫","器官保留方案：同期放化疗或诱导化疗+放疗，失败需全喉挽救","全喉切除后发音重建：气管食管发声瓣、电子喉、食管发声"],"life":["绝对戒烟戒酒，避免粉尘暴露","声嘶 >2 周 (尤其吸烟 >40 岁) 必须喉镜，不得按慢性喉炎处理","术后/放疗后嗓音康复训练","全喉切除者气道造口护理 (湿化、防水、防异物) ，接种流感与肺炎球菌疫苗","前 2 年每 1–3 个月复查喉镜与颈部超声/CT，第 3–5 年每 6 个月"]},"prog":"早期声门癌 5 年生存 85%–95%，局部控制 >85%；Ⅲ期约 60%–70%，Ⅳ期 30%–50%。复发多在 2–3 年内；第二原发癌 (肺、食管) 风险升高，需长期戒烟与随访。","refs":["国家卫生健康委员会《喉癌诊疗规范》(2022 年版)","《喉癌外科治疗专家共识》(2022)","NCCN Guidelines: Head and Neck Cancers – Larynx (2023)"]},{"id":"en_thyroid_neck","name":"颈部肿块鉴别","aka":["Neck Mass","颈部包块","甲状腺结节","颈部淋巴结肿大","腮腺/颌下腺肿瘤"],"rank":3,"basic":{"define":"颈部可触及的异常包块，按来源分甲状腺性、淋巴结性、唾液腺性与先天性 (甲状舌管囊肿、鳃裂囊肿) 。成人颈侧淋巴结肿大多为肿瘤转移，儿童多为炎性或先天性；任何颈部肿块均须先排除恶性。","risk":["年龄 >40 岁、男性、吸烟饮酒 (头颈鳞癌转移)","儿童期颈部放疗史→甲状腺癌","甲状腺癌家族史、MEN2","EBV 高发区 (鼻咽癌) 、HPV 相关口咽癌","慢性淋巴结炎、结核、猫抓病","桥本甲状腺炎伴结节、唾液腺放射线接触史"],"epi":"成人超声甲状腺结节检出率 20%–50%，恶性约 5%–15%；头颈癌颈部淋巴结转移率 30%–50%，约 3%–5% 以颈部肿块首诊。甲状舌管囊肿为最常见先天性颈前肿块。"},"patho":"颈部分区 (Ⅰ 颏下/颌下、Ⅱ 颈深上、Ⅲ 颈深中、Ⅳ 颈深下、Ⅴ 颈后三角、Ⅵ 中央区) 可定位来源：Ⅱ区多为鼻咽/口咽/喉，Ⅴ区为鼻咽/甲状腺，Ⅰ区为口腔/颌下腺，Ⅵ区为甲状腺。甲状腺结节中乳头状癌最常见 (淋巴转移倾向) ，髓样癌降钙素升高；唾液腺以腮腺多形性腺瘤最常见。","dx":{"criteria":["成人颈部肿块 >2 周不消退、质硬固定、进行性增大者须完成超声+穿刺，不得长期观察","质硬固定无痛提示恶性；囊性柔软多为良性/先天；搏动伴杂音警惕颈动脉体瘤","随吞咽上下移动提示甲状腺；耳下、咀嚼时胀痛提示腮腺；颌下三角为颌下腺/淋巴结","甲状腺结节：TI-RADS 超声分级 + FNA (TIBSRTC Ⅰ–Ⅵ) ，Ⅴ–Ⅵ级手术","成人颈侧单发质硬淋巴结：FNA 细胞学+洗脱液 EBV DNA、Tg 测定，同时查鼻咽镜、喉镜、口咽","伴发热压痛可先抗炎观察 2–4 周，不消退须进一步检查"],"workup":["颈部超声 (甲状腺、唾液腺、分区淋巴结) ：边界、钙化、淋巴结门","颈部增强 CT/MRI：与血管关系、深部范围、气道压迫；颈动脉体瘤禁活检","甲状腺功能、Tg (术后随访) 、降钙素与 CEA (疑髓样癌)","FNA 细胞学 (Bethesda/TIBSRTC 六级)","原发灶不明颈转移：鼻咽镜+喉镜，PET-CT，扁桃体/舌根切除活检","疑结核：T-SPOT、胸部 CT"],"grading":"甲状腺结节用 TI-RADS 1–5 级并决定 FNA；FNA 用 Bethesda 六级；淋巴结按 Ⅰ–Ⅵ区与良恶性影像标准 (门消失、囊性变、微钙化) ；甲状腺癌用 AJCC 第 8 版 TNM 与复发风险分层。"},"ddx":[{"name":"鼻咽癌","point":"与本类中鼻咽癌的鉴别：鼻咽癌以颈部肿块首发最常见，成人单侧无痛上颈淋巴结须查鼻咽镜+EBV；淋巴结 FNA 为鳞癌而鼻咽正常者按原发灶不明处理。"},{"name":"喉癌","point":"与本类中喉癌的鉴别：声门上型喉癌常以颈深上淋巴结增大首诊伴声嘶；颈部肿块伴声嘶必须喉镜。"},{"name":"反应性/感染性淋巴结炎","point":"有临近感染灶、压痛可活动，多 <1.5 cm，2–4 周消退；不消退质硬者需 FNA。"},{"name":"颈部淋巴结结核","point":"成串质韧、可破溃成窦道，低热盗汗，T-SPOT 阳性，抗结核治疗。"},{"name":"淋巴瘤","point":"多发对称橡皮样淋巴结伴 B 症状、肝脾大；需完整切除活检+免疫分型，FNA 不足。"},{"name":"甲状舌管囊肿/鳃裂囊肿","point":"颈前中线随伸舌上提者为甲状舌管囊肿；胸锁乳突肌前缘上 1/3 者为第二鳃裂囊肿；手术治疗。"},{"name":"颈动脉体瘤/神经鞘瘤","point":"颈动脉体瘤搏动性、可闻杂音、禁活检；神经鞘瘤可诱发放射痛。"}],"tx":{"drug":[{"name":"左甲状腺素 (甲状腺癌术后 TSH 抑制)","dose":"低危 1.5–2.0 μg/kg/d，中高危 2.0–2.5 μg/kg/d；4–6 周复查 TSH，目标低危 0.5–2.0、中危 0.1–0.5、高危 <0.1 mIU/L","note":"分化型甲状腺癌术后必需；老年与冠心病者小剂量起始","renal":"无需调整","hepatic":"遵说明书","interact":"与钙、铁、PPI 间隔 4 h；增强华法林作用"},{"name":"放射性碘-131","dose":"清甲 30–100 mCi，清灶 100–150 mCi，按危险分层由核医学确定","note":"用于全甲状腺切除后中高危；治疗前低碘饮食并停左甲状腺素或用 rhTSH","renal":"肾功不全者剂量个体化","hepatic":"遵说明书","interact":"与含碘造影剂、胺碘酮间隔足够时间"},{"name":"抗结核治疗 (淋巴结结核)","dose":"异烟肼 300 mg qd + 利福平 450–600 mg qd + 吡嗪酰胺 1.5 g qd + 乙胺丁醇 0.75–1.0 g qd×2 月，后异烟肼+利福平 4 月","note":"需肝功能监测；避免单纯切开形成窦道","renal":"乙胺丁醇肾功不全减量","hepatic":"肝病者调整方案并监测","interact":"利福平降低华法林、避孕药浓度"},{"name":"抗生素 (细菌性淋巴结炎)","dose":"阿莫西林克拉维酸钾 625/125 mg tid 或头孢呋辛 500 mg bid，5–10 天，遵说明书","note":"仅明确细菌感染时用，2–4 周不消退须进一步检查","renal":"CrCl <30 减量","hepatic":"肝病史慎用","interact":"增强华法林作用"},{"name":"泼尼松 (亚急性甲状腺炎)","dose":"起始 20–30 mg/d，2 周后每 1–2 周减 5 mg 至停，遵说明书","note":"NSAIDs 无效时用；监测血糖与骨密度","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血"}],"nonDrug":["甲状腺结节：FNA 为核心；良性 >4 cm 或压迫症状明显可手术，TIBSRTC Ⅴ/Ⅵ行腺叶切除+中央区清扫","分化型甲状腺癌：全甲状腺切除+中央/侧颈清扫，术后 RAI+TSH 抑制","原发灶不明颈转移：PET-CT+扁桃体/舌根活检；确认鳞癌按原发部位期别行颈清扫+放疗","腮腺多形性腺瘤浅叶切除+面神经保留；恶性肿瘤扩大切除+术后放疗","甲状舌管囊肿：Sistrunk 术切除至舌骨根部防复发","颈动脉体瘤：术前栓塞+血管外科联合切除"],"life":["成人颈部肿块 >2 周不消退或进行性增大须完成超声+穿刺","甲状腺癌术后长期左甲状腺素替代，每 6–12 个月复查颈部超声与肿瘤标志物","戒烟限酒；头颈放疗史者每年颈部体检","避免反复挤压或按摩肿块"]},"prog":"甲状腺乳头状癌 10 年生存率 >90%，早期复发率 10%–30%；髓样癌 10 年生存约 70%；未分化癌中位生存 <6 个月。原发灶不明颈转移治疗后 3 年生存约 60%–70%。甲状舌管囊肿完整切除后复发率 <3%。","refs":["中华医学会内分泌学分会《甲状腺结节和分化型甲状腺癌诊治指南》(2022)","中国抗癌协会《甲状腺癌诊疗指南》(2022 年版)","NCCN Guidelines: Thyroid Carcinoma (2023)"]},{"id":"en_osahs_surg","name":"阻塞性睡眠呼吸暂停 (外科视角)","aka":["OSAHS","OSA","鼾症","UPPP"],"rank":4,"basic":{"define":"睡眠中上气道反复塌陷导致呼吸暂停/低通气，引起间歇性低氧与睡眠结构破坏。诊断依据 PSG：AHI ≥5 伴症状，或 AHI ≥15。耳鼻喉科重点在识别解剖性狭窄并与 CPAP、减重综合决策，手术并非所有患者的一线。","risk":["肥胖 (BMI ≥28，中心性肥胖最重要)","男性、年龄 >40 岁、绝经后女性","小下颌/下颌后缩、舌体肥大、扁桃体肥大、鼻中隔偏曲","颈围增大 (男 >43 cm、女 >40 cm)","饮酒、镇静催眠药","甲状腺功能减退、肢端肥大症","儿童腺样体扁桃体肥大、张口呼吸"],"epi":"我国成人有症状 OSAHS 患病率约 3%–7%，AHI ≥5 者可达 20% 以上，男女比约 2–3:1；儿童 1%–5%，3–6 岁为高峰。是高血压、脑卒中、糖尿病与交通意外的独立危险因素。"},"patho":"睡眠期咽扩张肌张力降低、咽腔负压增大，叠加解剖性狭窄 (扁桃体肥大、软腭过长、舌后坠、下颌后缩) 致吸气相闭合。反复缺氧-复氧激活交感神经与氧化应激，形成高血压与代谢紊乱。手术通过解除解剖阻塞起效，以肥胖为主者获益有限。","dx":{"criteria":["响亮打鼾、目击呼吸暂停、夜间憋醒、夜尿多、晨起头痛与日间嗜睡 (ESS ≥9 异常)","PSG 诊断：AHI ≥5 伴症状，或 AHI ≥15 不论症状","严重度：轻度 5–14.9、中度 15–29.9、重度 ≥30 次/h；记录 ODI 与最低 SpO2","查体：BMI、颈围、鼻腔与咽部 (扁桃体分度、改良 Mallampati) 、颌面形态","Friedman 分型预测 UPPP 成功率，Ⅲ–Ⅳ型不宜单纯 UPPP","儿童以打鼾、张口呼吸、遗尿、注意力下降为主，可先家庭筛查，必要时 PSG"],"workup":["PSG (金标准) ：AHI、ODI、最低 SpO2、体位依赖性与睡眠结构","家庭睡眠呼吸监测 (HSAT) ：无合并症的中重度疑似者，不典型时做 PSG","电子纤维鼻咽喉镜 (清醒+必要时 DISE) 判断鼻、口咽、舌根、会厌塌陷平面","头颅侧位片/CBCT 评估下颌后缩；上气道 CT 测最小截面积","甲状腺功能、血压、血糖、心电图；术前 STOP-BANG 与心肺评估"],"grading":"按 AHI 分轻/中/重度；按塌陷部位分口咽型、舌根型、多平面型；Friedman 分型 Ⅰ–Ⅳ；ESS (0–24) ；儿童按 oAHI 分中度 (5–10) 与重度 (>10) 。"},"ddx":[{"name":"鼻咽癌","point":"与本类中鼻咽癌的鉴别：鼻咽癌以单侧鼻塞、血涕、耳闷与颈部肿块为主，打鼾为鼻塞继发；成人近期单侧鼻塞+鼻音改变须鼻内镜。"},{"name":"中枢性睡眠呼吸暂停","point":"PSG 中枢事件 ≥50%，常伴心衰、房颤、阿片类使用；CPAP 疗效差，心衰伴低射血分数者禁用 ASV。"},{"name":"单纯性鼾症","point":"打鼾但 AHI <5、无缺氧与嗜睡，减重与体位治疗即可。"},{"name":"睡眠期喉痉挛","point":"突发窒息感伴喉鸣，PSG 为吸气性喉鸣而非典型阻塞事件，喉镜见声带内收。"},{"name":"发作性睡病","point":"嗜睡突出，伴猝倒、睡眠瘫痪、入睡幻觉；MSLT 示 REM 潜伏期缩短，无呼吸事件。"},{"name":"甲状腺功能减退","point":"乏力、嗜睡、体重增加伴打鼾，TSH 升高，替代治疗后可改善，应常规筛查。"}],"tx":{"drug":[{"name":"莫达非尼 (CPAP 依从后的残余嗜睡)","dose":"100–200 mg 晨服，必要时至 400 mg/d，遵说明书","note":"仅缓解残余嗜睡，非病因治疗","renal":"重度肾功不全慎用","hepatic":"减量","interact":"降低口服避孕药效果"},{"name":"鼻用糖皮质激素 (合并鼻炎/鼻塞)","dose":"糠酸莫米松每侧 2 喷 qd 或糠酸氟替卡松每侧 1 喷 qd，4–12 周","note":"降低鼻阻力，轻度者可小幅降低 AHI，不能替代 CPAP","renal":"无需调整","hepatic":"遵说明书","interact":"与 CYP3A4 强抑制剂增加全身暴露"},{"name":"左甲状腺素 (合并甲减)","dose":"1.6 μg/kg/d 起始，4–6 周复查 TSH 调整，遵说明书","note":"甲减是可逆病因，中年女性与儿童尤需筛查","renal":"无需调整","hepatic":"遵说明书","interact":"与钙、铁、PPI 间隔 4 h"},{"name":"减重药物 (BMI ≥28 伴合并症)","dose":"遵说明书 (如司美格鲁肽按剂量递增)","note":"减重 10% 可使 AHI 下降约 26%，须与生活方式并行","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["CPAP：中重度一线，依从性 (每晚 ≥4 h) 是关键","口腔矫治器：轻中度且不耐受 CPAP 者，需牙科评估颞下颌关节","UPPP：扁桃体 Ⅲ–Ⅳ度、软腭过长、Friedman Ⅰ–Ⅱ型、CPAP 不耐受者；术前 DISE 定平面","改良术式：Z 腭成形、低温等离子射频；舌后坠可行舌根悬吊、下颌骨前移 (MMA)","鼻腔手术改善鼻阻力与 CPAP 依从性，单独治疗 OSAHS 效果有限","减重手术 (BMI ≥35 且保守失败) ：降低 AHI 最有效","儿童：腺样体扁桃体切除为重度儿童 OSAHS 一线 (成功率 70%–90%)"],"life":["减重是长期管理核心，体重减 10% 使 AHI 降约 26%","避免睡前饮酒与镇静药，侧卧睡眠","CPAP 规范培训与每月依从性随访，处理面罩漏气与皮损","与高血压、糖尿病、冠心病共管","术前戒烟 ≥2 周；术后 24 h 警惕出血与气道水肿，重度者术后监护"]},"prog":"未治疗者心血管事件风险增加 2–3 倍，中重度者交通事故风险增加 2–7 倍。CPAP 依从良好可降低血压与事件；UPPP 后 AHI 下降 ≥50% 者约 40%–60%，筛选良好者可达 70%。减重手术可使 80% 以上显著改善。","refs":["中华医学会耳鼻咽喉头颈外科学分会《OSAHS 诊断和外科治疗指南》(2020 修订)","中华医学会呼吸病学分会《阻塞性睡眠呼吸暂停诊治指南》(2015 修订版)","AAO-HNSF Clinical Practice Guideline: Surgical Management of Obstructive Sleep Apnea (2021)"]}]},{"id":"ent_airway_other","name":"气道与鼻部其他","rank":4,"summary":"本组先定位、后处理病因：鼻衄先分前/后鼻孔来源，后鼻孔出血需填塞或介入栓塞；声嘶 >2 周必须喉镜并鉴别良性、癌前病变；气道异物是幼儿急症，海姆立克与硬质支气管镜是核心；耳硬化症与面神经麻痹最容易与眩晕/感染疾病混淆，需声导抗+镫骨肌反射、House-Brackmann 分级把定位与严重度定死。","compare":[{"diseaseId":"en_epistaxis","dx":"鼻出血，前鼻孔滴出或向后流入咽部；鼻内镜定位 Little 区或鼻后部","key":"前鼻孔压迫+烧灼，后鼻孔需填塞或 DSA 栓塞，血流动力学不稳定先复苏"},{"diseaseId":"en_dysphonia","dx":"声嘶、气息声 >2 周；喉镜见息肉、白斑或声带突肉芽肿","key":"声嘶 >2 周必须喉镜；白斑须活检，肉芽肿以抗反流与嗓音治疗为主"},{"diseaseId":"en_airway_foreign","dx":"幼儿呛咳史，伴喘息、单侧呼吸音减弱或有“无症状间歇期”","key":"高度可疑即硬质支气管镜，不因影像阴性排除；完全梗阻先行海姆立克"},{"diseaseId":"en_otosclerosis","dx":"双侧渐进性传导性聋，妊娠后加重；鼓膜正常，声导抗 As 型，镫骨肌反射消失","key":"听骨链固定型传导性聋；镫骨手术或助听器"},{"diseaseId":"en_facial_nerve","dx":"单侧周围性面瘫 (含额肌) ，急性起病；Hunt 综合征伴耳痛、外耳道疱疹","key":"72 h 内激素 1 mg/kg/d，病毒性加阿昔洛韦；H-B 分级评估"}],"diseases":[{"id":"en_epistaxis","name":"鼻衄","aka":["Epistaxis","Nosebleed","鼻出血"],"rank":1,"basic":{"define":"鼻腔血管破裂出血。前鼻孔出血多来自鼻中隔 Little 区 (>90%，易自止) ；后鼻孔出血多来自蝶腭动脉及分支，量大难止，多见于老年与高血压者。按病因分局部性与全身性。","risk":["鼻中隔黏膜糜烂、干燥、挖鼻、外伤","鼻中隔偏曲、鼻内镜/鼻部术后、鼻腔肿瘤",">50 岁、高血压与动脉硬化 (后鼻孔出血为主)","抗凝/抗血小板药物 (华法林、NOAC、氯吡格雷)","HHT、血小板减少、凝血因子缺乏、肝病","空气干燥、冬季、化学刺激、鼻腔异物"],"epi":"约 60% 的人一生至少出现 1 次鼻衄，约 6% 需就医；儿童与 >50 岁双峰分布；后鼻孔出血占就医者 5%–10%，住院与输血需求高。"},"patho":"Little 区 (Kiesselbach 丛) 由颈外动脉上颌动脉分支与眼动脉筛前/筛后动脉吻合而成，黏膜干燥破损易出血。后鼻孔多源于蝶腭动脉或其分支破裂，血流入咽部，易被误认为消化道或呼吸道出血。全身因素经血小板功能、凝血因子缺乏或血管脆性增加加重出血。","dx":{"criteria":["先评估气道与循环：血压、心率、出血量 (呕血、黑便提示咽下) 、有无休克","前鼻孔：血自鼻孔流出、指压鼻翼有效；后鼻孔：向咽后壁流下、压迫无效、伴呕血或反复吞咽","鼻内镜定位出血点：鼻中隔前下部、中鼻道、下鼻甲后方、鼻咽部","出血 >20 min、填塞后仍活动或血流动力学不稳定者为急诊","全身评估：血压、Hb、PLT、PT/APTT/INR、肝肾功能","反复鼻衄需排查鼻腔/鼻咽肿瘤与遗传性出血性毛细血管扩张症 (HHT)"],"workup":["前鼻镜初查，清理血块后鼻内镜","血常规、凝血功能、肝肾功能；大出血交叉配血","疑后鼻孔出血或持续出血：鼻咽镜、鼻窦 CT","反复少量鼻衄伴鼻塞：鼻内镜+活检排除肿瘤","DSA：难治性后鼻孔出血的评估与栓塞","HHT 筛查：皮肤黏膜毛细管扩张、内脏 AVM、家族史"],"grading":"按来源分前鼻孔/后鼻孔；按严重度分轻度 (自止) 、中度 (需压迫/烧灼) 、重度 (难治、血流动力学不稳、需输血或栓塞) ；按病因分局部性/全身性。"},"ddx":[{"name":"后鼻孔来源鼻衄","point":"与本条前鼻孔出血的鉴别：后鼻孔出血量大、有咽部流血或呕血、压迫无效，需后鼻孔填塞或栓塞。"},{"name":"咯血/呕血误认","point":"咯血伴咳嗽、泡沫状鲜红；呕血为暗红咖啡色伴黑便；咽下血可致呕血，先查鼻腔确认出血源。"},{"name":"鼻腔/鼻咽肿瘤 (血管纤维瘤、鼻咽癌)","point":"青年男性反复大量鼻衄+单侧鼻塞警惕鼻咽血管纤维瘤 (禁盲目活检) ；成人单侧血涕伴耳闷警惕鼻咽癌。"},{"name":"遗传性出血性毛细血管扩张症","point":"儿童期起反复鼻衄、唇与指尖毛细血管扩张、家族史、内脏 AVM。"},{"name":"凝血障碍 (抗凝过量/肝病)","point":"INR 延长或血小板减少，伴牙龈出血与瘀斑，需纠正凝血同时局部处理。"}],"tx":{"drug":[{"name":"羟甲唑啉/麻黄碱滴鼻液 (收缩血管)","dose":"成人每侧 2–3 喷或棉片局部压迫，≤3 天，遵说明书","note":"填塞前收缩黏膜定位出血点；高血压、冠心病慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与 MAOI、三环类合用可致血压升高"},{"name":"维生素 K1/凝血酶原复合物 (抗凝过量)","dose":"维生素 K1 5–10 mg 静滴；PCC 由血液科按 INR 与体重确定","note":"华法林过量时使用；NOAC 有特异拮抗剂","renal":"PCC 无需调整","hepatic":"肝病者效果有限","interact":"维生素 K1 拮抗华法林"},{"name":"氨甲环酸 (反复出血/HHT)","dose":"口服 500–1000 mg tid 或静脉 1 g q8h，遵说明书","note":"抗纤溶辅助，需排除血栓风险","renal":"CrCl <30 减量","hepatic":"遵说明书","interact":"与口服避孕药合用增加血栓风险"},{"name":"铁剂 (慢性失血性贫血)","dose":"琥珀酸亚铁 0.1–0.2 g bid–tid 或硫酸亚铁 0.3 g bid，餐后服","note":"反复出血致缺铁时补充，监测 Hb","renal":"遵说明书","hepatic":"遵说明书","interact":"与四环素、喹诺酮、甲状腺素间隔 2–4 h"}],"nonDrug":["坐位前倾，双指紧捏鼻翼 10–15 min (头后仰、塞纸巾为误区)","化学 (硝酸银) 或电凝烧灼：出血点明确、出血停止后使用，双侧 Little 区不同时烧灼","鼻腔填塞：凡士林纱条或可吸收海绵，24–48 h 取出","后鼻孔填塞：球囊/纱球填塞首选，48–72 h，需抗生素预防中耳炎/鼻窦炎","内镜下蝶腭动脉/筛前动脉结扎：反复后鼻孔出血、填塞失败者","经导管动脉栓塞 (DSA) ：难治性大出血，成功率 >90%，警惕卒中风险","鼻中隔偏曲、血管瘤、肿瘤等处理原发病"],"life":["鼻腔湿润 (生理盐水喷雾、软膏涂 Little 区) ，冬季加湿","纠正挖鼻，避免用力擤鼻与热水澡","高血压者控压；抗凝/抗血小板者出血时权衡调整","反复者避免剧烈运动与桑拿","记录出血日记，每 3–6 个月随访"]},"prog":"约 90% 前鼻孔出血经压迫与烧灼止血，复发率 20%–30%；后鼻孔出血填塞或栓塞止血率 80%–95%，住院病死率 3%–5% (多为老年合并症) 。反复少量出血可致缺铁性贫血。","refs":["《鼻出血诊断和治疗专家共识》(2019)","AAO-HNSF Clinical Practice Guideline: Epistaxis (2020)"]},{"id":"en_dysphonia","name":"声带息肉与声带白斑、喉肉芽肿","aka":["Dysphonia","声嘶","声带息肉","声带白斑","喉接触性肉芽肿"],"rank":2,"basic":{"define":"声嘶持续 >2 周必须行喉镜检查。本条覆盖：声带息肉 (用声相关、多为单侧的广基水肿性隆起) 、声带白斑 (白色斑片，癌前病变，需活检) 、喉接触性肉芽肿 (声带突或杓状软骨的肉芽组织，多与插管、反流、用声不当相关) 。","risk":["职业用声者与长期喊叫","吸烟、饮酒 (白斑与喉癌前病变强相关)","反流性咽喉病 (LPR)","气管插管史、长时间全麻","慢性咳嗽、频繁清嗓、干燥粉尘","甲状腺功能减退、月经期嗓音变化","声带麻痹等其他发声障碍"],"epi":"职业用声人嗓音障碍患病率 20%–50%；声带息肉多见于 30–50 岁男性；白斑癌变率约 10%–20%，与吸烟及异型增生程度相关；插管后肉芽肿发生约 1%–3%。"},"patho":"息肉源于任克层水肿与基质改变：黏膜高速碰撞致微血管损伤、水肿与机化。白斑为上皮角化过度/不全或异型增生 (中、重度为癌前) 。肉芽肿为黏膜损伤后的炎症性肉芽组织，非真性肿瘤，常位于声带突后 1/3。","dx":{"criteria":["声嘶持续 >2 周 (吸烟者、>40 岁者 >2 周) 必须电子喉镜，不得按“咽喉炎”处理","息肉：单侧、前中 1/3、广基或半透明水肿样隆起，声门闭合不全、气息声","白斑：声带白色斑块，支撑喉镜活检明确有无异型增生/浸润癌","肉芽肿：声带突后连合或杓状软骨区肉芽样增生，伴清嗓、咽异物感","危险信号：吞咽痛、颈部肿块、耳痛、呼吸困难、体重下降→高度疑喉癌","嗓音评估：GRBAS、VHI-10、MPT 作基线"],"workup":["电子纤维喉镜 (含 NBI) ，必要时支撑喉镜看清并活检","嗓音评估 (GRBAS、VHI-10、最长发声时间)","白斑：支撑喉镜活检 (必要时染色) ，中/重度异型增生按癌前病变管理","反流评估：RSI、24 h 食管 pH-阻抗监测","声带麻痹者行胸部 CT 排除纵隔、甲状腺、喉返神经病变","高危吸烟者疑恶变：NBI+活检，必要时 PET-CT"],"grading":"按类型分息肉 (广基/带蒂) 、白斑 (单纯增生/轻中重度异型/原位癌) 、肉芽肿 (接触性/插管后/大杓状软骨) ；GRBAS 0–3 分；VHI-10 >11 提示明显损害。"},"ddx":[{"name":"喉癌","point":"与本组中喉癌的鉴别：喉癌为声带表面不规则、菜花状肿物伴糜烂、声带活动受限、颈淋巴结；声嘶 >2 周的吸烟饮酒者必须活检排除。"},{"name":"声带小结","point":"与息肉鉴别：小结双侧对称位于前中 1/3 交界，纤维性结节，嗓音训练可改善；息肉多单侧水肿样广基。"},{"name":"喉乳头状瘤","point":"多发乳头状血管丰富，HPV-6/11 相关，需反复切除+随访。"},{"name":"喉淀粉样变/喉结核","point":"淀粉样变为黄白结节、刚果红阳性；喉结核为后连合溃疡+肉芽伴肺结核表现。"},{"name":"声带麻痹/环杓关节脱位","point":"声带光滑但固定，需查甲状腺/胸部手术史与喉返神经损伤，脱位可复位。"},{"name":"肌紧张性发声障碍","point":"喉镜结构正常，发声时声门挤压痉挛，嗓音训练与心理干预有效。"}],"tx":{"drug":[{"name":"质子泵抑制剂 (LPR/肉芽肿)","dose":"奥美拉唑 20 mg bid 或埃索美拉唑 40 mg qd，餐前 30–60 min，8–12 周，必要时 6 个月","note":"喉咽反流是肉芽肿与声带水肿的重要诱因，需配合饮食与体位","renal":"重度肾功不全慎用","hepatic":"肝功不全减量","interact":"奥美拉唑降低氯吡格雷疗效，可改泮托拉唑"},{"name":"雾化吸入糖皮质激素 (术后/急性炎症)","dose":"布地奈德 1 mg 雾化 bid，1–2 周，遵说明书","note":"减轻术后黏膜水肿，不作长期治疗","renal":"无需调整","hepatic":"遵说明书","interact":"与强 CYP3A4 抑制剂增加暴露"},{"name":"黏液溶解剂","dose":"氨溴索 30 mg tid 或乙酰半胱氨酸 200 mg tid","note":"改善清嗓与黏液附着，配合饮水与蒸汽吸入","renal":"遵说明书","hepatic":"遵说明书","interact":"乙酰半胱氨酸不与抗生素同瓶静滴"},{"name":"伐尼克兰 (戒烟)","dose":"0.5 mg qd 起，1 周后 1 mg bid，共 12 周，遵说明书","note":"戒烟降低白斑恶变风险；精神疾病史者慎用","renal":"CrCl <30 减量","hepatic":"遵说明书","interact":"可与尼古丁替代联合"}],"nonDrug":["嗓音治疗 (嗓音卫生、发声训练) ：息肉、小结与功能性发声障碍的一线，8–12 周","声带息肉：嗓音治疗 6–8 周无效或影响职业者行支撑喉镜显微切除","声带白斑：活检+切除 (必要时激光) ，中/重度异型增生每 3–6 个月随访","肉芽肿：抗反流 8–12 周+嗓音治疗为主，手术复发率高","戒烟戒酒 (白斑必须)","职业用声者发声休息、呼吸支持训练，避免清嗓与喊叫"],"life":["每日饮水 1500–2000 mL，避免咖啡因与酒精","避免喊叫、耳语与频繁清嗓","使用扩音设备，每声歇 10–15 min","反流者夜间抬高床头、睡前 3 h 禁食","声嘶 >2 周或伴吞咽痛、颈部肿块立即就诊；白斑每 3–6 个月喉镜随访"]},"prog":"息肉显微手术后嗓音恢复率 80%–90%，用声方式未纠正者复发率 20%–30%。白斑切除后复发率 20%–40%，异型增生越重癌变率越高。接触性肉芽肿抗反流 6–8 周多缩小，手术复发率高。","refs":["《嗓音障碍疾病诊断和治疗指南》(2018)","《声带白斑诊断和治疗专家共识》(2021)"]},{"id":"en_airway_foreign","name":"气管支气管异物","aka":["Tracheobronchial Foreign Body","气道异物","气管异物"],"rank":3,"basic":{"define":"异物吸入并嵌顿于气管或支气管内的急症。多见 1–3 岁幼儿 (坚果、豆类、塑料小件) ；成人多为进食、醉酒、义齿或吞咽障碍。按位置分喉/气管异物 (可致窒息) 与支气管异物 (多为单侧，右侧较多) 。","risk":["1–3 岁幼儿 (咀嚼不充分、边玩边吃)","整颗坚果、葡萄、爆米花、果冻、硬糖","儿童口含笔帽、珠子等小件","成人醉酒、镇静/抗精神病药、癫痫、脑血管病","义齿松动、口腔感觉减退","气管插管误吸、气管切开术后"],"epi":"儿童气道异物是 1–3 岁婴幼儿意外死亡主要原因之一；坚果类占 60%–70%；右主支气管陡直宽短，异物更多。成人约 80% 发生于老年或吞咽障碍者。"},"patho":"异物致机械阻塞、黏膜损伤与气道痉挛。植物性异物析出脂肪酸与鞣酸引起化学性炎症、肉芽增生与远端肺不张/肺气肿，形成“无症状期”延误诊断。完全阻塞致窒息，部分阻塞可形成活瓣致纵隔气肿、气胸；停留 >1 周易并发肺炎、肺脓肿。","dx":{"criteria":["进食/玩耍时突发呛咳、喘息、发绀，随后转入“无症状间歇期”，必须追问呛咳史","完全梗阻：不能说话、不能咳嗽、双手抓喉，迅速发绀意识丧失","部分梗阻：阵咳、喘息、单侧呼吸音减弱、气管拍击音、喘鸣","同一部位反复“肺炎”或迁延不愈须高度怀疑异物","X 线：透视或呼气/卧位相见透光度不对称、纵隔摆动；CT 显示直接异物与肺不张","支气管镜是确诊与治疗的最终手段，高度可疑即镜检，不因影像阴性排除"],"workup":["病史 (呛咳时间、食物种类、进食动作) +查体 (呼吸音、三凹征、发绀)","胸部 X 线 (吸气/呼气相或卧位) 观察透光度差与纵隔摆动，CT 补充","合并肺炎或肺不张者 CT 评估远端肺组织","术前血气、SpO2 与麻醉/耳鼻喉/呼吸介入联合评估","不能配合的幼儿在全麻下行硬质支气管镜"],"grading":"按部位分喉、气管、支气管异物 (右>左) ；按阻塞程度分完全性与部分性；按病程分急性 (<72 h) 与延迟诊断 (>1 周，多伴肉芽与肺炎) 。"},"ddx":[{"name":"假性义膜性喉炎 (喉痉挛)","point":"与本组气道异物的鉴别：喉异物突发呛咳伴喉鸣、发声保留；哮吼伴发热与前驱上感、犬吠样咳嗽，激素有效，无呛咳史。"},{"name":"支气管哮喘","point":"反复发作、双肺广泛哮鸣音、支气管舒张剂有效；单侧喘鸣伴呛咳史应优先排除异物。"},{"name":"大叶性肺炎","point":"发热咳嗽脓痰；反复同一部位“肺炎”的儿童必须排查异物。"},{"name":"喉乳头状瘤/声门下狭窄","point":"渐进声嘶与喘鸣，喉镜见病变，无突发呛咳史。"},{"name":"会厌炎/咽后脓肿","point":"高热流涎、吞咽困难、颈部后仰，需谨慎气道评估。"}],"tx":{"drug":[{"name":"抗生素 (异物取出后继发感染)","dose":"阿莫西林克拉维酸钾 45 mg/kg/d 分 2 次，或头孢呋辛 30 mg/kg/d 分 2–3 次，遵说明书","note":"仅伴明确肺炎/肉芽感染时用，不能替代取出","renal":"CrCl <30 减量","hepatic":"肝病史慎用","interact":"增强华法林作用"},{"name":"地塞米松 (围术期喉水肿)","dose":"0.2–0.5 mg/kg 静注 (最大 10 mg) ，必要时 q8–12h","note":"预防与治疗硬质镜后声门下水肿","renal":"无需调整","hepatic":"遵说明书","interact":"与 NSAIDs 增加消化道出血"},{"name":"肾上腺素雾化 (喉水肿/痉挛)","dose":"1:1000 肾上腺素 0.5 mL/kg (最大 5 mL) 雾化，必要时 20 min 后重复","note":"为镜检争取时间，不能替代取出","renal":"遵说明书","hepatic":"遵说明书","interact":"β 受体阻滞剂可拮抗"},{"name":"镇痛镇静 (围术期)","dose":"按麻醉科方案 (丙泊酚、芬太尼等) ，遵说明书","note":"硬质支气管镜须全身麻醉","renal":"遵说明书","hepatic":"遵说明书","interact":"与镇静药叠加呼吸抑制"}],"nonDrug":["海姆立克 (腹部冲击) ：≥1 岁完全梗阻且清醒者；孕妇/肥胖者胸部推挤","<1 岁婴儿：背部拍击 5 次+胸部按压 5 次，头低脚高，禁腹部冲击；意识丧失即 CPR","硬质支气管镜取出：儿童首选，需全麻与耳鼻喉/麻醉配合","可弯曲支气管镜：成人、远端细小或硬质镜不可及者，用网篮/异物钳","喉部异物可直接取出，必要时环甲膜切开/气管切开创建气道","取出后复查镜检清除碎屑，观察肉芽与黏膜损伤","合并肺不张/肺脓肿者抗感染，必要时肺叶切除 (少见)"],"life":["1–3 岁避免整颗坚果、果冻、葡萄、爆米花；进食时不跑、不笑、不哭","玩具按年龄选择，避免 <3 cm 小零件","成人细嚼慢咽，醉酒/服药后勿边吃边说话，修复松动义齿","吞咽障碍老人行吞咽评估与食物性状调整","家庭成员掌握海姆立克与婴儿拍背法；取出后 2–4 周复查胸片"]},"prog":"及时取出者多完全恢复，支气管镜成功率 >95%，并发症 5%–10% (黏膜损伤、出血、气胸、喉水肿) 。延迟 >1 周者肉芽与肺炎发生率高，部分需多次镜检；完全梗阻未解除者窒息死亡风险高。","refs":["《儿童气道异物诊疗专家共识》(2020)","《气道异物诊断和治疗指南》(2022)"]},{"id":"en_otosclerosis","name":"耳硬化症","aka":["Otosclerosis","耳硬化","镫骨固定","传导性耳聋"],"rank":4,"basic":{"define":"骨迷路局灶性骨吸收与新骨形成的疾病，约 80%–90% 累及卵圆窗龛 (窗性耳硬化) ，致镫骨固定、传音受阻，出现渐进性传导性聋；少数累及耳蜗形成混合性聋。","risk":["20–40 岁起病 (高峰 20–30 岁)","女性略多见，妊娠与产后加重","家族史 (约 50%–60%，常染色体显性，外显率约 40%)","白人患病率高于亚裔与非洲裔","青春期、妊娠、绝经期激素变化","麻疹感染史 (证据有限)"],"epi":"白种人患病率 0.3%–0.5%，亚裔约 0.04%–0.1%，女性约为男性 2 倍；双侧受累 70%–80%，多不对称。"},"patho":"卵圆窗前缘的窗前裂出现异常骨吸收与海绵状成骨，病灶侵犯镫骨足板与环状韧带，使镫骨固定，形成低频为主、气骨导差 30–50 dB 的传导性聋；累及耳蜗底转则合并感音神经性聋。镫骨肌反射因镫骨固定而消失，中耳无积液。","dx":{"criteria":["20–40 岁起进行性传导性聋，妊娠、产后或劳累后加重","耳鸣 (60%–70%) 、Willis 误听 (嘈杂环境自觉听力更好)","鼓膜正常或轻度内陷，约 10% 见卵圆窗区 Schwartze 粉红征","纯音测听：气骨导差 20–50 dB，2000 Hz 骨导下降 (Carhart 切迹) 为特征","声导抗 A 型/As 型 (低峰) ，镫骨肌声反射消失或阈值升高 (诊断核心)","颞骨高分辨率 CT 可见卵圆窗前缘低密度灶"],"workup":["纯音测听 (气/骨导、言语识别率) +声导抗 (鼓室图、镫骨肌反射)","颞骨高分辨率 CT：评估卵圆窗龛密度与足板 (术前必需)","伴感音神经性成分者行 MRI 排除听神经瘤","耳镜排除外耳/鼓膜病变，鼓室图排除中耳积液","每 6–12 个月复查听力，记录气骨导差与骨导","术前前庭功能与对侧耳听力评估"],"grading":"临床分窗性 (传导性为主) 与蜗性/混合性；按范围分窗型、窗后型、广泛型；听力损失按轻/中/重/极重度分级；术前用气骨导差与言语识别率评估手术价值。"},"ddx":[{"name":"分泌性中耳炎","point":"与本组疾病的鉴别：分泌性中耳炎鼓膜内陷、可见液平，鼓室图 B 型；耳硬化鼓膜正常、A/As 型、镫骨肌反射消失。"},{"name":"突发性聋","point":"与本组突发性聋的鉴别：突聋 72 h 内突发感音神经性下降，无气骨导差；耳硬化为渐进性气骨导差、骨导相对保留。"},{"name":"听骨链畸形/外伤性脱位","point":"先天性者自幼听力差且不进展；外伤者突发传导性聋伴鼓室积血，CT 见听骨链中断。"},{"name":"粘连性中耳炎/鼓室硬化","point":"有慢性中耳炎与鼓膜穿孔史，鼓膜增厚钙斑，鼓室图 B/C 型。"},{"name":"耵聍栓塞/外耳道狭窄","point":"耳镜见耵聍或狭窄，取出后恢复。"},{"name":"听神经瘤","point":"单侧渐进感音神经性聋、言语识别率显著下降，MRI 见内听道占位。"}],"tx":{"drug":[{"name":"氟化钠 (活动期，证据有限)","dose":"遵说明书 (常用 20–30 mg/d 分次) ，须专科评估","note":"国内有争议，证据等级低，妊娠期禁用","renal":"肾功不全慎用 (氟蓄积)","hepatic":"遵说明书","interact":"钙剂、铝制剂影响吸收"},{"name":"双膦酸盐/骨代谢药物 (循证不足)","dose":"遵说明书，仅限研究或特殊病例","note":"不作常规治疗，不能替代手术与助听器","renal":"双膦酸盐肾功不全禁用","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["镫骨手术 (足板开窗+人工镫骨植入) ：气骨导差 ≥25–30 dB、言语识别率 >60% 且对侧听力好者获益最大，成功率 80%–95%","手术并发症：感音神经性聋 (<1%) 、眩晕、面瘫 (<0.5%) 、味觉改变、植入物移位","助听器：双侧或不愿/不适合手术者首选","骨锚式助听器 (BAHA) ：严重混合性聋或无法佩戴助听器者","人工耳蜗：晚期蜗性极重度聋","避免双侧同期手术"],"life":["妊娠与哺乳期听力常加重，孕前与产科/耳科共同评估","避免耳毒性药物","每年复查听力，气骨导差扩大或骨导下降及时复诊","术后 4 周避免剧烈运动、擤鼻与坐飞机","噪声环境佩戴防护，老年评估助听器与社交功能"]},"prog":"进展缓慢，病程可达数十年；术后 5 年气骨导差 <10 dB 者 70%–80%，10 年约 50%–60%。约 20%–30% 出现蜗性进展，终末期可致极重度聋。","refs":["《耳硬化症诊断与治疗指南》(2017)","《耳鼻咽喉头颈外科学》第 9 版，人民卫生出版社，耳硬化症章节"]},{"id":"en_facial_nerve","name":"面神经麻痹 (贝尔麻痹与 Hunt 综合征)","aka":["Bell's Palsy","特发性面神经麻痹","周围性面瘫","Ramsay Hunt 综合征"],"rank":5,"basic":{"define":"面神经下运动神经元损伤致同侧全部表情肌瘫痪 (含额肌) 。最常见为特发性面神经麻痹 (贝尔麻痹) ，其次为 VZV 再激活的 Hunt 综合征 (耳带状疱疹合并面瘫) 。二者均为周围性面瘫，须先排除中枢性、肿瘤与感染性疾病。","risk":["30–60 岁，男女相近","妊娠 (孕晚期风险约增 3 倍) 、产褥期","糖尿病、高血压、免疫抑制","劳累、受凉、精神压力","既往 VZV 感染史 (Hunt 综合征)","上感、HSV-1/EBV 再激活","约 10% 有家族史"],"epi":"贝尔麻痹年发病率约 15–30/10 万，为最常见单侧面瘫原因 (60%–75%) ；约 70% 完全恢复，10% 恢复不完全。Hunt 综合征占面瘫 7%–12%，恢复不完全者约 40%。"},"patho":"HSV-1 潜伏于膝状神经节，免疫低下或受凉时再激活，引起面神经水肿并在骨性面神经管 (内听道至膝状节段) 内受压，致脱髓鞘乃至轴索变性，恢复期可异常再生 (联动、面肌痉挛) 。Hunt 综合征为 VZV 再激活，累及面神经与耳部感觉神经，伴外耳道疱疹、耳痛、眩晕与听力下降。","dx":{"criteria":["单侧全表情肌瘫痪：额纹消失、蹙眉不能、闭眼不全 (Bell 征) 、鼻唇沟浅、口角下垂、鼓腮漏气","中枢性鉴别：中枢性面瘫额纹保留、仅下半面瘫，伴偏瘫/失语；周围性额肌亦受累","贝尔麻痹为排除性诊断：72 h 内达高峰、无耳部疱疹、无其他颅神经症状、无外伤/肿瘤史","Hunt 综合征：面瘫前后出现耳部/外耳道/鼓膜疱疹、耳痛、眩晕、听力下降","House-Brackmann 分级 (Ⅰ 正常、Ⅱ 轻度、Ⅲ 中度、Ⅳ 中重度、Ⅴ 重度、Ⅵ 完全麻痹) 作基线","伴眩晕、声嘶、面部麻木、腮腺肿块提示肿瘤或更高段病变"],"workup":["完整颅神经查体 (Ⅴ、Ⅵ、Ⅷ、Ⅸ–Ⅻ) 与耳鼻检查 (疱疹)","H-B 分级；发病 3–14 天可行面神经电图 (ENoG) ，变性 >90% 提示预后差","非典型、进行性加重 >3 周或伴颅神经症状者行头颅 MRI/颞骨 CT","Hunt 综合征：疱疹液 PCR 或 VZV 血清学","血糖、HIV 抗体 (双侧或多次复发) 、莱姆病血清学 (流行区)","腮腺超声 (面瘫伴腮腺肿块提示恶性肿瘤)"],"grading":"House-Brackmann Ⅰ–Ⅵ 级；ENoG 变性率；病程分急性期 (<1 周) 、恢复期 (3 周–6 个月) 与后遗症期 (>6 个月，联动/痉挛) 。"},"ddx":[{"name":"Hunt 综合征","point":"与本条贝尔麻痹的鉴别：Hunt 有外耳道/耳廓疱疹、耳痛、眩晕与听力下降；贝尔麻痹无耳部症状，二者抗病毒策略与预后不同。"},{"name":"中枢性面瘫 (脑卒中)","point":"额纹保留、仅下半面瘫，伴偏瘫失语；MRI 定位。"},{"name":"听神经瘤/桥小脑角肿瘤","point":"渐进性面瘫伴耳鸣、单侧感音神经性聋与共济失调，MRI 见占位。"},{"name":"腮腺肿瘤","point":"面瘫伴耳下/耳后肿块，恶性肿瘤侵犯面神经，需超声与穿刺。"},{"name":"中耳乳突炎并发面瘫","point":"耳内流脓、乳突区压痛，需抗生素+乳突切开与面神经减压。"},{"name":"莱姆病","point":"流行区蜱咬与游走性红斑，常双侧面瘫，伴脑膜炎，血清学阳性。"}],"tx":{"drug":[{"name":"泼尼松 (首选)","dose":"1 mg/kg/d (最大 60–80 mg/d) 起病 72 h 内开始，5–7 天后逐渐减量，总疗程 7–10 天；儿童 1–2 mg/kg/d (最大 60 mg)","note":"72 h 内使用可提高完全恢复率 (约 87% vs 64%) ；糖尿病、结核、活动性溃疡者需权衡并监测血糖","renal":"无需调整","hepatic":"肝功能不全者谨慎调整","interact":"与 NSAIDs 增加消化道出血；减弱降糖药效果"},{"name":"阿昔洛韦/伐昔洛韦","dose":"阿昔洛韦 400–800 mg 5 次/日×7–10 天 (或 5–10 mg/kg q8h 静滴) ；伐昔洛韦 1000 mg tid×7 天","note":"Hunt 综合征抗病毒+激素为一线；贝尔麻痹重症 (H-B Ⅴ–Ⅵ) 可联合","renal":"CrCl <50 mL/min 减量","hepatic":"遵说明书","interact":"丙磺舒增加血药浓度"},{"name":"泛昔洛韦 (Hunt 综合征)","dose":"500 mg tid×7 天，遵说明书","note":"可与激素同期开始","renal":"CrCl <60 mL/min 减量","hepatic":"遵说明书","interact":"遵说明书"},{"name":"人工泪液/眼膏 (暴露性角膜炎防护)","dose":"白天每 2–4 h 1 滴，夜间涂眼膏；遵说明书","note":"H-B Ⅳ级及以上闭眼不全者必须防护，必要时湿房镜或睑缘缝合","renal":"无需调整","hepatic":"无需调整","interact":"无"},{"name":"甲钴胺 (辅助)","dose":"0.5 mg tid 口服或 0.5 mg 隔日肌注","note":"神经营养，证据有限","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["眼部保护：日间人工泪液、夜间眼膏与眼罩，必要时湿房镜或睑缘缝合","面部康复训练：皱眉、闭眼、微笑、鼓腮每日 2–3 次，发病 2 周内开始","Hunt 综合征：抗病毒+激素，神经痛用加巴喷丁/普瑞巴林","闭眼不全 >3–6 个月不恢复：金板植入或肌肉吊带术","后遗联动/痉挛：肉毒素注射或选择性神经手术","保守 2 周无改善且 ENoG 变性 >90%：可考虑面神经减压 (争议大，专科评估)"],"life":["72 h 内就诊用药是关键，延误则恢复率下降","避免受凉吹风与过度劳累，保证睡眠","闭眼不全者外出戴镜、夜间眼罩，避免强光风沙","每 3–4 周复评 H-B；6 个月未恢复者评估联动与挛缩"]},"prog":"贝尔麻痹约 70% 完全恢复，72 h 内规范激素治疗者达 85%–90%，未治疗者约 60%–65%。Hunt 综合征恢复不完全率 30%–40%，合并眩晕与高龄者更差。面肌联动与痉挛多在 6 个月–2 年内出现。","refs":["《特发性面神经麻痹诊治中国专家共识》(2016)","《耳鼻咽喉头颈外科学》第 9 版，人民卫生出版社，面神经疾病章节","AAO-HNSF Clinical Practice Guideline: Bell's Palsy (2013)"]}]}]},"eye":{"categories":[{"id":"glaucoma_cat","name":"青光眼与白内障","rank":1,"summary":"白内障以视功能损害程度决定手术时机；青光眼管理的核心是保护视神经、控制眼压并识别房角机制，急性闭角型发作需分秒必争降眼压后行激光或手术解除解剖阻塞。","compare":[{"diseaseId":"ey_cataract","dx":"渐进性无痛性视力下降伴眩光、屈光度改变；裂隙灯见晶状体混浊，LOCS 分级；无眼压升高与视神经损害","key":"屈光间质混浊而眼底与眼压正常，术后视力可恢复"},{"diseaseId":"ey_aacg","dx":"突发的剧烈眼痛、头痛、恶心呕吐、视力骤降伴虹视；眼压常 >40 mmHg，结膜混合充血、角膜水肿、瞳孔中度散大且对光反射消失、前房浅","key":"症状发作性剧烈，眼压急骤升高且有房角关闭的解剖体征，对侧眼需预防性激光"},{"diseaseId":"ey_oag","dx":"早期无症状，查体见眼压 >21 mmHg、视盘杯盘比扩大（C/D >0.6 或双眼差 >0.2）、视网膜神经纤维层缺损、房角开放且无其他继发因素","key":"慢性进行性视神经病变，以视野缺损与 RNFL 变薄为主要证据，房角开放"}],"diseases":[{"id":"ey_cataract","name":"白内障","aka":["Cataract","年龄相关性白内障","老年性白内障"],"rank":1,"basic":{"define":"晶状体蛋白质变性使晶状体混浊、透明度下降、光学质量下降，导致渐进性无痛性视力下降的眼病；以年龄相关性白内障最常见，也可由糖尿病、外伤、用药与先天因素引起。","risk":["年龄（多见于 50 岁以上）","糖尿病与长期血糖控制不佳","长期紫外线暴露","吸烟、饮酒","长期使用糖皮质激素（口服或滴眼）","眼外伤、葡萄膜炎、高度近视","营养不良与氧化应激"],"epi":"白内障是全球首位致盲眼病；我国 60 岁以上人群患病率约 70%，80 岁以上接近 100%，是我国致盲和视力损伤的首要原因。"},"patho":"晶状体纤维蛋白氧化、交联与聚集，水分与离子平衡紊乱，晶状体逐渐硬化混浊。核性白内障使晶状体指数增大，早期出现近视漂移；皮质性混浊沿皮质纤维楔形发展；后囊下混浊位于视轴，对视力影响最明显。晶状体混浊导致散射与对比敏感度下降，而非单纯视力下降。","dx":{"criteria":["渐进性、无痛性视力下降，伴眩光、夜间视物困难、颜色变暗或近视漂移","裂隙灯检查见晶状体混浊，按 LOCS Ⅲ 分级（核、皮质、后囊下三型）","矫正视力下降且不能用其他眼病解释；对比敏感度下降","排除其他致视力下降眼病（眼底、视神经、角膜）"],"workup":["视力、最佳矫正视力（BCVA）、屈光检查","裂隙灯检查与散瞳后晶状体分级（LOCS Ⅲ）","眼压与眼底检查，排除青光眼与黄斑病变","对比敏感度与眩光试验","手术前：角膜内皮计数、眼轴与人工晶状体度数测量（IOLMaster）、眼底 OCT 排除黄斑病变","合并糖尿病者需评估视网膜情况并控制血糖"],"grading":"LOCS Ⅲ 分级：核性（NO1–NO6）、皮质性（C1–C5）、后囊下（P1–P5）；临床分期可按初发期、膨胀期、成熟期、过熟期划分（膨胀期可诱发闭角型青光眼）。"},"ddx":[{"name":"开角型青光眼（ey_oag）","point":"与本类 ey_oag 的鉴别点：白内障为屈光间质混浊，视觉症状为渐进性模糊与眩光，无眼压升高与视野缺损；青光眼以视盘结构改变、RNFL 变薄与视野缺损为特征，早期视力可正常。二者常并存，白内障术前须评估青光眼。"},{"name":"急性闭角型青光眼（ey_aacg）","point":"与本类 ey_aacg 的鉴别点：急性闭角发作伴剧痛、恶心呕吐与眼压骤升，角膜水肿而晶状体相对透明；白内障无痛，视力下降缓慢。白内障膨胀期可诱发房角关闭，需急诊降眼压后再处理白内障。"},{"name":"糖尿病视网膜病变（eye/retina）","point":"视力下降伴眼底出血、渗出与微血管瘤，常有糖尿病史；白内障可掩盖视网膜病变，术前需评估。"},{"name":"年龄相关性黄斑变性（eye/retina）","point":"中心视力下降、视物变形，眼底见玻璃膜疣、色素改变或 CNV（OCT 见视网膜下液），而屈光间质透明。"},{"name":"屈光不正与老视","point":"远近视力按屈光状态变化，针孔试验改善，晶状体透明，验光即可矫正。"}],"tx":{"drug":[{"name":"抗氧化补充剂（延缓进展，证据有限）","dose":"遵说明书；如维生素 C 500 mg qd、维生素 E 400 IU qd、叶黄素 10 mg qd（AREDS2 型配方）","note":"不能逆转已形成的白内障，仅在部分人群可能延缓核性混浊进展","renal":"遵说明书","hepatic":"遵说明书","interact":"高剂量维生素 E 与抗凝药合用增加出血风险"},{"name":"苄达赖嗪滴眼液","dose":"1 滴，每日 3 次","note":"国内常用于早期白内障，可延缓混浊进展，疗效证据有限","renal":"眼部局部用药，无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min 使用"},{"name":"吡诺克辛钠滴眼液","dose":"1 滴，每日 3–4 次","note":"用于早期老年性白内障，不能替代手术；术后停用","renal":"眼部局部用药，无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min 使用；滴眼液需避光保存"},{"name":"术前抗生素滴眼液（左氧氟沙星滴眼液）","dose":"术前 1 天每日 4–6 次，或术前 1–3 天使用","note":"用于围术期预防眼内炎；术后按医师方案继续","renal":"眼部局部用药，无特殊调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["白内障超声乳化联合人工晶状体植入术：视力下降影响日常工作生活或最佳矫正视力≤0.5（或 ≤0.3）为主要指征","术前需综合评估眼表、角膜内皮、眼底与全身状况，排查视网膜脱离/黄斑病变风险","成熟期或过熟期白内障、合并闭角型青光眼者，可考虑联合手术（青光眼白内障联合手术）","术后并发症：后囊膜混浊（PCO，Nd:YAG 激光切开）、眼内炎、黄斑囊样水肿、角膜内皮失代偿","单眼白内障致屈光参差者可提前手术以改善双眼视觉"],"life":["术后 1 周、1 个月、3 个月复查视力、眼压与眼底","术后避免揉眼、剧烈运动与污水入眼，按医嘱使用抗生素与糖皮质激素滴眼液","控制血糖与血压，糖尿病患者术前优化血糖","外出佩戴防紫外线太阳镜，减少紫外线暴露"]},"prog":"手术是唯一有效治疗，超声乳化术后约 95% 以上患者视力显著改善；后囊膜混浊是术后最常见远期并发症（术后 3–5 年发生率可达 20%–40%），可用 Nd:YAG 激光处理。未治疗者可导致成熟期、过熟期白内障并继发青光眼。","refs":["《中国白内障手术专家共识（2023）》","《成人白内障诊断和治疗专家共识（2021）》","《中国老年性白内障诊疗指南（2017）》","AAO Preferred Practice Pattern: Cataract in the Adult Eye（2021）"]},{"id":"ey_aacg","name":"急性闭角型青光眼","aka":["AACG","急性房角关闭","急性青光眼发作"],"rank":2,"basic":{"define":"因房角急性关闭导致房水外流受阻、眼压急剧升高的眼科急症，典型表现为突发眼痛、头痛、恶心呕吐与视力骤降，若未及时处理可致不可逆性视神经损害与失明。","risk":["远视眼、小眼球、浅前房、晶状体厚（解剖性窄房角）","女性（女性发病约为男性 2–4 倍）","年龄 >50 岁","家族史","暗环境停留、情绪激动、散瞳药或抗胆碱药","晶状体膨胀（白内障膨胀期）"],"epi":"我国急性闭角型青光眼在原发性青光眼中比例较高，女性多见，多发生于 50 岁以上；亚洲人群房角关闭的患病率明显高于白人。"},"patho":"晶状体与虹膜根部拥挤使周边虹膜贴近小梁网，瞳孔阻滞使后房压力升高、周边虹膜向前膨隆（iris bombé），房角突然关闭，房水排出障碍导致眼压急升至 40–80 mmHg。高眼压压迫视神经并致角膜内皮泵功能衰竭、角膜水肿；持续高眼压造成缺血性视神经损害。","dx":{"criteria":["突发性剧烈眼痛伴同侧头痛、恶心呕吐，视力骤降，看灯光有虹视","眼压常 >40 mmHg，部分可达 60–80 mmHg","体征：结膜混合充血、角膜水肿（雾状）、前房浅、瞳孔中度散大（4–6 mm）呈竖椭圆形且对光反射消失","房角镜检查：房角关闭（不可见小梁网后部），需在降眼压与角膜透明后检查","对侧眼常存在窄房角或前房浅，需评估并预防","需与急性虹膜睫状体炎（瞳孔缩小、KP、前房闪辉）鉴别"],"workup":["视力、眼压（Goldmann 或眼压计）、裂隙灯检查","超声生物显微镜（UBM）与前节 OCT：评估房角关闭、虹膜形态与晶状体厚度","房角镜（角膜透明且眼压控制后）","视野与 RNFL OCT：视神经损害评估（发作后）","全身检查：排除继发性房角关闭（晶状体膨胀、葡萄膜炎、新生血管、药物）","急性发作时先标记检查，避免徒手按压眼球"],"grading":"临床分期：临床前期、先兆期（小发作）、急性发作期、间歇缓解期、慢性进展期；另按 Shaffer 房角分级（0–Ⅳ级）评估关闭程度。"},"ddx":[{"name":"开角型青光眼（ey_oag）","point":"与本类 ey_oag 的鉴别点：急性闭角型发作伴剧痛、眼压骤升 >40 mmHg 与房角关闭；开角型青光眼无症状、房角开放，眼压轻中度升高，视神经损害缓慢进展。两者需以房角镜与 UBM 区分。"},{"name":"白内障（ey_cataract）","point":"与本类 ey_cataract 的鉴别点：白内障为无痛性渐进视力下降、眼压正常、前房深度正常；但膨胀期白内障可诱发急性房角关闭，如患者有晶状体膨胀与浅前房，应按急性闭角型处理。"},{"name":"急性虹膜睫状体炎","point":"眼痛与畏光，但瞳孔缩小、前房闪辉伴 KP，眼压正常或偏低；与闭角型瞳孔散大、眼压极高相反。"},{"name":"急性结膜炎与角膜溃疡","point":"异物感与分泌物增多，视力多正常，眼压正常，角膜可见浸润或溃疡灶，无前房浅。"},{"name":"继发性（新生血管性）青光眼","point":"糖尿病或视网膜中央静脉阻塞病史，虹膜表面与房角新生血管，眼压升高伴虹膜红变；需抗 VEGF 与全视网膜光凝处理原发病。"},{"name":"偏头痛与急性胃肠炎","point":"可因恶心呕吐与头痛误诊；注意检查眼部（眼压、瞳孔、角膜），眼压升高与虹视可提示闭角型发作。"}],"tx":{"drug":[{"name":"甘露醇（20% 注射液）","dose":"1–2 g/kg 静脉滴注，30–45 min 内快速滴注；常用 250 mL（50 g），必要时 6–8 h 后重复","note":"首选高渗剂，快速降低眼压；心肾功能不全者慎用，用药期间监测尿量与电解质","renal":"肾功能不全者慎用或减量，监测肌酐与尿量","hepatic":"遵说明书","interact":"与利尿剂、其他肾毒性药物合用增加肾损伤风险"},{"name":"毛果芸香碱滴眼液（1%–2%）","dose":"1–2 滴患眼，每 5–10 min 一次，共 4–6 次，随后每 1–2 h 一次","note":"在眼压开始下降后使用效果最佳（角膜水肿与括约肌缺血时缩瞳作用减弱）；可引起眉弓痛与调节痉挛；使用前先降眼压","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与抗胆碱能药全身应用可能拮抗缩瞳效果"},{"name":"噻吗洛尔滴眼液（0.5%）","dose":"1 滴患眼，每日 2 次","note":"β 受体阻滞剂，降低房水生成；哮喘、COPD、窦性心动过缓或二度以上房室传导阻滞者禁用","renal":"眼部局部用药，一般无调整","hepatic":"遵说明书","interact":"与全身 β 受体阻滞剂、维拉帕米合用加重心动过缓"},{"name":"布林佐胺滴眼液（1%）","dose":"1 滴患眼，每日 2–3 次（急性期可每 8 h 一次）","note":"碳酸酐酶抑制剂，减少房水生成；磺胺过敏者慎用","renal":"眼部局部用药，全身吸收少","hepatic":"遵说明书","interact":"与其他碳酸酐酶抑制剂（乙酰唑胺）联用可不叠加疗效，注意全身不良反应"},{"name":"乙酰唑胺片","dose":"250 mg 口服，每日 4 次（或 500 mg 顿服后 250 mg 每 6–8 h），短期使用","note":"全身碳酸酐酶抑制剂；注意肢端麻木、多尿、低钾与代谢性酸中毒，镰状细胞贫血禁用","renal":"eGFR <30 慎用或禁用","hepatic":"重度肝功能不全慎用","interact":"与阿司匹林合用增加毒性；与锂盐合用升高锂浓度"},{"name":"溴莫尼定滴眼液（0.15%–0.2%）","dose":"1 滴患眼，每日 2–3 次（急性期可每 8 h 一次）","note":"α2 受体激动剂，抑制房水生成；注意嗜睡、口干，儿童与婴儿慎用","renal":"眼部局部用药，一般无特别调整","hepatic":"遵说明书","interact":"与中枢镇静药、单胺氧化酶抑制剂合用加重低血压与嗜睡"}],"nonDrug":["急性发作期立即降眼压，同时禁散瞳、禁抬头过度与俯卧用药水","激光周边虹膜切开术（LPI）：急性发作控制后尽早行患眼及对侧眼预防性治疗","白内障合并房角关闭者可行白内障摘除联合房角分离术，可同时解决解剖拥挤","药物无法控制或伴视神经进行性损害者，行小梁切除术或引流管植入术","发作缓解后 6 周内完成房角与视神经功能评估，避免慢性化"],"life":["避免暗环境久留、情绪激动与一次性大量饮水（>500 mL）","禁用散瞳药与含抗胆碱成分药物（如阿托品、某些感冒药），就诊时主动告知青光眼病史","家族中 40 岁以上成员筛查房角与前房深度","规律随访眼压、视野与 RNFL，终身监测"]},"prog":"急性发作后若 24–48 h 内未有效降眼压，视神经损害可不可逆，部分患者视力难以恢复；发作后约半数患者未行 LPI 者会在 5 年内再次发作；对侧眼未经预防性 LPI 者发作风险高。","refs":["《中国青光眼指南（2020）》","《原发性闭角型青光眼诊疗专家共识（2022）》","AAO Preferred Practice Pattern: Primary Angle Closure Disease（2020）"]},{"id":"ey_oag","name":"原发性开角型青光眼","aka":["POAG","开角型青光眼","OAG"],"rank":3,"basic":{"define":"房角开放但房水外流阻力增加、眼压升高或正常，造成进行性视网膜神经节细胞与视神经轴突损害，形成特征性视盘改变与视野缺损的慢性眼病；早期多无症状。","risk":["年龄 >40 岁","青光眼家族史（一级亲属风险增加 3–6 倍）","眼压升高（>21 mmHg，但正常眼压也可发病）","高度近视、角膜中央厚度薄（<520 µm）","糖尿病、高血压、低灌注（夜间低血压）","长期使用糖皮质激素"],"epi":"原发性开角型青光眼是全球不可逆性致盲的首位原因；我国 40 岁以上人群患病率约 2%，其中约 90% 早期未被发现。"},"patho":"小梁网细胞外基质（黏多糖、胶原）沉积与内皮细胞减少使房水外流阻力增大，眼压升高；同时存在视神经轴突运输障碍、线粒体功能下降与微循环灌注不足，导致筛板区轴突进行性变性。角膜较薄、筛板结构薄弱者即使眼压正常也易发生损害。","dx":{"criteria":["眼压 >21 mmHg（正常眼压型青光眼眼压可 <21 mmHg）","视盘改变：杯盘比（C/D）>0.6、双眼 C/D 差 >0.2、盘沿变窄或切迹、盘沿出血","视网膜神经纤维层（RNFL）缺损，OCT 见厚度变薄","视野缺损：早期旁中心暗点、鼻侧阶梯，进展为弓形暗点、环形暗点与管状视野","房角开放且无继发因素（房角镜、UBM）","诊断需结构与功能损害相匹配，避免单指标判断"],"workup":["眼压测量（多次、不同时段，必要时 24 h 眼压曲线）","裂隙灯与眼底立体照相：视盘形态、盘沿与出血","OCT 测 RNFL 与视神经纤维层厚度","视野检查（Humphrey 24-2 或 30-2，至少 2 次可靠结果）","房角镜检查，必要时 UBM","角膜中央厚度、既往屈光状态与全身危险因素评估","视野进展的量化：GPA、平均偏差（MD）年下降速度"],"grading":"按视野缺损分期：早期（MD >−6 dB）、中期（−6 至 −12 dB）、晚期（<−12 dB）或终末期；Hodapp-Parrish-Anderson 分级用于综合评价。"},"ddx":[{"name":"急性闭角型青光眼（ey_aacg）","point":"与本类 ey_aacg 的鉴别点：开角型青光眼房角开放、无急性剧痛，视神经损害缓慢进展；急性闭角发作有剧痛、恶心呕吐、瞳孔散大与角膜水肿，眼压骤升 >40 mmHg。"},{"name":"白内障（ey_cataract）","point":"与本类 ey_cataract 的鉴别点：白内障为主观视力模糊、眩光与屈光改变，眼底与视野正常；青光眼早期视力正常但视野缺损、RNFL 变薄，二者可并存，术前须测量眼压并评估视神经。"},{"name":"高眼压症","point":"眼压 >21 mmHg 但视盘、RNFL 与视野均正常；需长期随访，按风险（角膜薄、C/D 大、家族史）决定是否治疗。"},{"name":"正常眼压性青光眼","point":"具有典型青光眼性视神经损害与视野缺损而眼压始终≤21 mmHg；需排查全身低灌注（夜间低血压、过度降压）与其他视神经病。"},{"name":"缺血性视神经病变","point":"急性视力下降、视野象限缺损、视盘水肿苍白，无盘沿进行性变窄；常伴高血压、糖尿病与小视神经杯。"},{"name":"压迫性视神经病变（垂体瘤、颅内占位）","point":"视野呈双颞侧偏盲或中心暗点，视盘苍白，需 MRI 与神经科评估。"}],"tx":{"drug":[{"name":"拉坦前列素滴眼液","dose":"1 滴，每晚 1 次（睡前）","note":"一线首选前列腺素类似物，降眼压幅度大、每日 1 次；注意结膜充血、睫毛增长、睫周色素沉着、虹膜色变","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与含硫柳汞的滴眼液合用可产生沉淀，需间隔 5 min"},{"name":"曲伏前列素滴眼液","dose":"1 滴，每晚 1 次","note":"前列腺素类似物替代选择，滴注后按压鼻泪管 1–2 min 减少全身吸收","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他眼表用药间隔 5 min"},{"name":"噻吗洛尔滴眼液（0.5%）","dose":"1 滴，每日 2 次","note":"β 受体阻滞剂；哮喘、窦性心动过缓、二度以上房室传导阻滞者禁用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与口服 β 受体阻滞剂、维拉帕米合用加重心动过缓"},{"name":"溴莫尼定滴眼液（0.2%）","dose":"1 滴，每日 2 次（间隔约 12 h）","note":"α2 受体激动剂；可致口干、嗜睡，2 岁以下儿童禁用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用可致高血压"},{"name":"布林佐胺滴眼液（1%）","dose":"1 滴，每日 2 次","note":"碳酸酐酶抑制剂，适用于对 β 受体阻滞剂禁忌者","renal":"眼部局部用药，全身吸收少","hepatic":"遵说明书","interact":"与其他碳酸酐酶抑制剂联用注意全身不良反应"},{"name":"复方制剂（如拉坦前列素/噻吗洛尔）","dose":"1 滴，每晚 1 次","note":"需两种药物联合时优先使用固定复方，提高依从性并减少防腐剂负荷","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["目标眼压：一般较基线降低 20%–30%，有进展者降低 30%–40%，晚期需更低目标","激光选择性小梁成形术（SLT）可作为首选或辅助治疗","药物与激光不能控制或依从性差者，行小梁切除术、引流管植入或微创青光眼手术（MIGS）","避免全身糖皮质激素与含拟交感成分药物，注意夜间低血压加重灌注障碍","白内障合并青光眼者可行联合手术"],"life":["每 3–6 个月复查眼压，每 6–12 个月复查视野与 OCT","坚持每日点药，按压鼻泪管减少全身吸收","避免一次性大量饮水（>500 mL），避免长期低头与屏气用力","睡前不使用含前列腺素类似物之外的其他滴眼液干扰夜间降眼压效果"]},"prog":"POAG 为不可逆的进行性视神经病变，确诊后多数患者在规律治疗下可维稳或延缓进展，但约 10%–15% 进展至单眼失明；未治疗者视野缺损进展迅速，晚期剩余视野决定生活质量。","refs":["《中国青光眼指南（2020）》","《原发性开角型青光眼诊疗专家共识（2022）》","AAO Preferred Practice Pattern: Primary Open-Angle Glaucoma（2020）"]}]},{"id":"retina","name":"眼底病","rank":2,"summary":"糖尿病视网膜病变重在分层筛查与全视网膜光凝；黄斑变性以抗 VEGF 治疗抑制新生血管渗漏；孔源性视网膜脱离需尽早封闭裂孔并复位视网膜，时间与手术效果直接相关。","compare":[{"diseaseId":"ey_dr","dx":"糖尿病史 + 眼底见微血管瘤、出血、硬性渗出、棉絮斑，重者新生血管与玻璃体积血；OCT 见黄斑水肿，FFA 见无灌注与渗漏","key":"以糖网分期（NPDR/PDR）与黄斑水肿为核心，双眼见症，需全身代谢控制"},{"diseaseId":"ey_amd","dx":"50 岁以上，近视、变形、中心暗点；眼底见玻璃膜疣与色素改变，湿性者 OCT 见视网膜下液与 CNV（FFA/ICGA 可确诊）","key":"中心视力受损而周边保留，湿性 AMD 需尽早抗 VEGF，延误则视力不可逆"},{"diseaseId":"ey_rd","dx":"无痛性突发视野缺损伴闪光感、飞蚊骤增，视网膜见裂孔与脱离，B 超见视网膜隆起与后运动消失","key":"常伴裂孔与玻璃体后脱离，需急诊手术（巩膜扣带或玻璃体切除）"}],"diseases":[{"id":"ey_dr","name":"糖尿病视网膜病变","aka":["DR","Diabetic Retinopathy","糖网"],"rank":1,"basic":{"define":"长期高血糖导致视网膜微血管损伤，出现微血管瘤、出血、渗出、棉絮斑、无灌注与新生血管的进行性眼底病变；可伴糖尿病黄斑水肿（DME），是工作年龄人群致盲的首位原因。","risk":["糖尿病病程（10 年以上风险显著升高）","血糖控制不佳（HbA1c 高）","高血压、血脂异常","糖尿病肾病与蛋白尿","妊娠","吸烟","肥胖与缺乏运动"],"epi":"我国糖尿病患者中约 20%–30% 存在视网膜病变，其中增殖期约占 5%；约 1/3 的糖尿病患者合并黄斑水肿。"},"patho":"高血糖致多元醇通路激活、AGEs 蓄积、蛋白激酶 C 活化与氧化应激，使视网膜毛细血管周细胞丢失、基底膜增厚、内皮功能障碍，形成微血管瘤、无灌注区与血-视网膜屏障破坏；视网膜缺血产生 VEGF，驱动新生血管与血管渗漏，导致玻璃体积血、牵拉性视网膜脱离与虹膜新生血管继发青光眼。","dx":{"criteria":["明确糖尿病病史","非增殖期（NPDR）：至少见微血管瘤与点状出血；中度可见硬性渗出与棉絮斑；重度符合 4-2-1 规则（4 个象限出血、2 个象限静脉串珠、1 个以上象限 IRMA）","增殖期（PDR）：视盘或其他部位新生血管（NVD/NVE）、玻璃体积血、视网膜前出血或纤维血管增殖","糖尿病黄斑水肿（DME）：黄斑中心区视网膜增厚或硬性渗出，OCT 中心凹厚度增加","筛查时机：1 型糖尿病病程 5 年起、2 型糖尿病确诊时即筛查，此后每年 1 次"],"workup":["散瞳眼底检查与眼底照相（可 45° 或超广角）","OCT：评估黄斑水肿、视网膜下液与玻璃体界面","眼底荧光血管造影（FFA）：评估无灌注区、新生血管与渗漏","视力、眼压与裂隙灯检查（评估新生血管性青光眼）","全身：HbA1c、血压、血脂、尿白蛋白/肌酐比值、肾功能","定期随访：轻度 NPDR 每年复查，重度或 PDR 每 3–6 个月"],"grading":"国际临床分级：无明显 DR、轻度 NPDR、中度 NPDR、重度 NPDR（4-2-1 规则）、PDR；合并 DME 时按有无及是否累及中心凹进一步分类。"},"ddx":[{"name":"年龄相关性黄斑变性（ey_amd）","point":"与本类 ey_amd 的鉴别点：DR 有糖尿病史，眼底以点状出血、微血管瘤与硬性渗出为特征，常双眼；AMD 多见于 50 岁以上，眼底为玻璃膜疣、色素改变与 CNV，OCT 见视网膜下液，多见于非糖尿病患者。"},{"name":"视网膜脱离（ey_rd）","point":"与本类 ey_rd 的鉴别点：DR 合并增殖期可出现牵拉性视网膜脱离；孔源性视网膜脱离有闪光感与飞蚊骤增，B 超见裂孔与视网膜隆起。DR 的玻璃体积血遮盖眼底时需 B 超鉴别。"},{"name":"高血压性视网膜病变","point":"双侧火焰状出血、棉絮斑与动脉变细、动静脉交叉压迫，常伴严重高血压（>180/110 mmHg）；与原发病控制相关。"},{"name":"视网膜中央静脉阻塞","point":"单眼突发无痛性视力下降，眼底四象限火焰状出血与静脉迂曲扩张，无明显棉絮斑，需排查血栓与青光眼。"},{"name":"视网膜静脉周围炎/炎症性血管炎","point":"年轻男性多见，周边静脉白鞘、反复玻璃体积血，需与结核等感染鉴别。"}],"tx":{"drug":[{"name":"雷珠单抗（玻璃体腔注射）","dose":"每次 0.5 mg（0.05 mL）玻璃体腔注射，起始每月 1 次，连续 3 个月，随后按需或延长间隔","note":"用于累及中心凹的糖尿病黄斑水肿；需无菌操作，监测眼压与眼内炎征象","renal":"全身吸收极低，一般无特殊调整","hepatic":"遵说明书","interact":"无系统意义相互作用；近期卒中或心肌梗死者慎用"},{"name":"阿柏西普（玻璃体腔注射）","dose":"每次 2 mg（0.05 mL），前 5 个月每月 1 次，之后每 2 个月 1 次","note":"用于 DME 与 PDR；疗效与注射频率依从性相关","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"康柏西普（玻璃体腔注射）","dose":"每次 0.5 mg（0.05 mL），起始每月 1 次连续 3 次，之后每 3 个月 1 次（遵说明书）","note":"国产抗 VEGF 药物，用于 DME","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"羟苯磺酸钙","dose":"500 mg 口服，每日 2–3 次","note":"辅助改善视网膜微循环，不能替代光凝与抗 VEGF；证据有限","renal":"重度肾功能不全慎用","hepatic":"遵说明书","interact":"遵说明书"},{"name":"复方血栓通胶囊（中成药，辅助）","dose":"遵说明书；常用 3 粒每日 3 次","note":"国内用于改善视网膜循环，证据有限，不作为主要治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["全视网膜光凝（PRP）：用于严重 NPDR 与 PDR，减少新生血管与玻璃体积血风险","局灶或格栅样光凝：非中心凹的局灶性 DME","玻璃体切除手术：玻璃体积血不吸收、牵拉性视网膜脱离或黄斑前膜","黄斑水肿不缓解者可行抗 VEGF 联合光凝或激素植入物","妊娠期 DME 需个体化处理，产后多可自行缓解"],"life":["严格控制 HbA1c（多数目标 <7%）、血压（<130/80 mmHg）与 LDL-C","每年散瞳眼底检查；妊娠期每 3 个月复查","出现视力骤降、飞蚊骤增需立即就诊（警惕玻璃体积血与视网膜脱离）","避免血糖骤然大幅波动（快速强化可短暂加重 DME）"]},"prog":"轻度 NPDR 10 年进展为 PDR 的风险约 25%，重度 NPDR 约 50%；及时 PRP 可使严重视力丧失风险下降约 50%；DME 经抗 VEGF 治疗后约 60%–70% 视力稳定或改善，延误治疗者视功能不可逆。","refs":["《中国糖尿病视网膜病变临床诊疗指南（2022）》","《糖尿病视网膜病变防治专家共识（2018）》","《中国 2 型糖尿病防治指南（2020 年版，并发症章节）》","AAO Preferred Practice Pattern: Diabetic Retinopathy（2020）"]},{"id":"ey_amd","name":"年龄相关性黄斑变性","aka":["AMD","Age-related Macular Degeneration","黄斑变性"],"rank":2,"basic":{"define":"50 岁以上人群因黄斑区光感受器与 RPE 退行性变（干性）或脉络膜新生血管（湿性）导致中心视力进行性下降的眼病，是老年人不可逆性中心视力丧失的主要原因。","risk":["年龄 >50 岁","吸烟（最强可控危险因素）","家族史与 CFH/ARMS2 基因多态性","高血压、心血管疾病","高脂肪饮食、肥胖","长期紫外线暴露","浅色虹膜"],"epi":"全球约 2 亿人患有 AMD；我国 50 岁以上人群患病率约 5%–10%，70 岁以上明显升高，湿性 AMD 约占 10%–15% 但导致 80% 以上的严重视力损害。"},"patho":"RPE 与 Bruch 膜代谢废物（脂褐素、补体激活产物）蓄积形成玻璃膜疣，局部慢性炎症与补体旁路激活（CFH）导致 RPE 与光感受器退行性变（干性）。若脉络膜毛细血管发生异常新生血管（CNV），则形成湿性 AMD：新生血管突破 RPE 引起视网膜下出血、渗出与视网膜下液，纤维化后形成盘状瘢痕。","dx":{"criteria":["年龄≥50 岁，中心视力下降、视物变形、中心暗点或对比敏感度下降，周边视野保留","干性：眼底见黄斑区玻璃膜疣（≥63 µm）、色素改变与地图状萎缩","湿性：OCT 见视网膜下液、视网膜内液或 RPE 脱离；FFA 见 CNV 渗漏，ICGA 用于区分典型与隐匿性 CNV","AMD 分期（AREDS 简化）：无 AMD、早期（小/中等玻璃膜疣）、中期（大玻璃膜疣或色素改变）、晚期（地图状萎缩或 CNV）","Amsler 方格表自测出现变形或暗点可作为居家筛查"],"workup":["最佳矫正视力与近视力，Amsler 方格表","裂隙灯与散瞳眼底检查、眼底彩色照相","OCT（首选）：评估视网膜下液、视网膜内液、RPE 与玻璃膜疣形态","FFA/ICGA：定位 CNV 类型与活动性（湿性）","散瞳 OCT 血管成像（OCTA）可无创显示 CNV","全身危险因素与用药（如抗凝药、补体抑制剂）评估"],"grading":"按 AREDS 分期：早期、中期、晚期；湿性按 CNV 类型分典型（Ⅰ型 RPE 下、Ⅱ型 上、Ⅲ型 视网膜血管瘤样增殖）与隐匿性；晚期分为地图状萎缩与新生血管性瘢痕。"},"ddx":[{"name":"糖尿病视网膜病变（ey_dr）","point":"与本类 ey_dr 的鉴别点：AMD 多见于无糖尿病史者，病变局限于黄斑区玻璃膜疣、CNV 与视网膜下液；DR 的出血、微血管瘤与渗出更广泛、沿血管分布，常伴 DME。"},{"name":"视网膜脱离（ey_rd）","point":"与本类 ey_rd 的鉴别点：AMD 因视网膜下液可致视物变形与中心暗点，但无裂孔与玻璃体后脱离；RRD 有闪光感与飞蚊骤增，视野缺损从周边向中心扩展，B 超见视网膜隆起。"},{"name":"中心性浆液性脉络膜视网膜病变（CSC）","point":"青壮年男性多见，有应激或激素使用史，黄斑区圆形神经上皮脱离，常自限；AMD 患者年龄更大且伴玻璃膜疣。"},{"name":"息肉状脉络膜血管病变（PCV）","point":"亚洲人群多见，ICGA 见息肉样病灶与分支血管网，常伴视网膜下出血与渗出；对抗 VEGF 反应较 AMD 差，必要时联合 PDT。"},{"name":"高度近视性黄斑病变","point":"高度近视病史伴眼轴延长（>26 mm）、后巩膜葡萄肿与漆裂纹，黄斑区可有 CNV 或萎缩；需结合屈光度与眼轴鉴别。"}],"tx":{"drug":[{"name":"雷珠单抗（玻璃体腔注射）","dose":"每次 0.5 mg（0.05 mL）玻璃体腔注射；起始每月 1 次连续 3 次，随后按需（PRN）或治疗-延长（T&E）方案","note":"湿性 AMD 一线治疗，越早注射视力获益越大；注射后监测眼压、眼内炎与视网膜脱离","renal":"全身吸收极低，一般无特殊调整","hepatic":"遵说明书","interact":"近期发生动脉血栓事件者慎用"},{"name":"阿柏西普（玻璃体腔注射）","dose":"每次 2 mg（0.05 mL），起始每月 1 次连续 3 次，之后每 2 个月 1 次，或按 T&E 调整","note":"可用于湿性 AMD 与 PCV，部分患者注射间隔可延长","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"康柏西普（玻璃体腔注射）","dose":"每次 0.5 mg（0.05 mL），起始每月 1 次连续 3 次，之后每 3 个月 1 次（遵说明书）","note":"国产抗 VEGF 药物，广泛用于湿性 AMD","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"维生素 C/维生素 E/锌/铜抗氧化配方（AREDS2，干性）","dose":"遵说明书；常见为维生素 C 500 mg、维生素 E 400 IU、氧化锌 80 mg、氧化铜 2 mg、叶黄素 10 mg、玉米黄质 2 mg 每日 1 次","note":"用于中期或晚期单眼 AMD 以降低对侧眼进展为晚期的风险，不能恢复已丧失视力","renal":"长期大剂量维生素 E 与抗凝药合用增加出血风险","hepatic":"遵说明书","interact":"高剂量维生素 E 与华法林合用需监测 INR"},{"name":"补体抑制剂（如玻璃体腔注射的 C3/C5 抑制剂，干性地图状萎缩）","dose":"遵说明书；玻璃体腔注射，按用药间隔方案执行","note":"可延缓干性 AMD 地图状萎缩进展，需与患者充分讨论获益与注射频率，国内可及性有限","renal":"遵说明书","hepatic":"遵说明书","interact":"可能增加眼内炎与新生血管转化风险"}],"nonDrug":["湿性 AMD：3–6 周内启动抗 VEGF，延误导致视力不可逆，治疗按 T&E 或 PRN 方案监测 OCT","光动力疗法（PDT）联合抗 VEGF 用于 PCV 或厚脉络膜相关 CNV","干性地图状萎缩目前无确切疗法，补体抑制与干细胞治疗处于研究阶段","Amsler 方格表居家自查，出现变形或暗点立即就诊"],"life":["戒烟（最强可控危险因素），控制血压与血脂","饮食富含深绿色蔬菜、ω-3 脂肪酸，必要时补充叶黄素与玉米黄质","户外佩戴防紫外线眼镜","低视力康复训练与助视器，心理支持"]},"prog":"干性 AMD 进展缓慢但不可逆，约 10%–15% 会转化为湿性；湿性 AMD 未经治疗 2 年内约 70% 患者视力降至 0.1 以下，规范抗 VEGF 治疗可使多数患者视力稳定或改善，但需长期随访注射。","refs":["《中国年龄相关性黄斑变性临床诊疗指南（2023）》","《湿性年龄相关性黄斑变性治疗专家共识（2022）》","AREDS2 研究（Lancet，2013）","AAO Preferred Practice Pattern: Age-Related Macular Degeneration（2019）"]},{"id":"ey_rd","name":"视网膜脱离","aka":["Retinal Detachment","RRD","孔源性视网膜脱离"],"rank":3,"basic":{"define":"视网膜神经上皮层与色素上皮层分离的眼病，按机制分为孔源性（视网膜裂孔伴液体积聚）、牵拉性（纤维增殖牵拉）与渗出性（炎症、肿瘤或血管病致液体渗出）；孔源性最常见且属眼科急症。","risk":["高度近视（眼轴 >26 mm）","年龄 40–70 岁","视网膜格子样变性与裂孔","白内障术后（尤其后囊破裂）","眼外伤","视网膜脱离家族史","糖尿病视网膜病变（牵拉性）"],"epi":"孔源性视网膜脱离年发病率约每 10 万人 10–20 例，高度近视人群风险显著升高；双眼发病约 5%–10%。"},"patho":"玻璃体液化、后脱离过程中牵拉视网膜，在格子样变性区域形成裂孔；液化的玻璃体经裂孔进入视网膜下腔，在重力作用下沿神经上皮与 RPE 之间扩展，形成脱离。黄斑区脱离超过数天即可造成光感受器不可逆损伤（持续 7 天以上预后显著变差）。牵拉性脱离则由增殖膜牵拉视网膜，渗出性脱离多无裂孔。","dx":{"criteria":["无痛性突发视野缺损（常有幕帘样遮挡感），可伴闪光感与飞蚊骤增","眼底见视网膜隆起、血管爬行于脱离区，可见视网膜裂孔与格子样变性","孔源性：可见裂孔与视网膜下液，常伴玻璃体后脱离","黄斑是否累及决定最佳手术时机与预后；黄斑未脱离者应在 24 h 内手术","屈光间质混浊（白内障、玻璃体积血）时以 B 超确诊"],"workup":["视力（含黄斑功能）、眼压、裂隙灯与散瞳后三面镜/间接检眼镜检查","巩膜压迫下检查周边视网膜，定位裂孔（裂孔多位于 1–2 个钟点范围内）","B 超：屈光间质不清时评估视网膜隆起、玻璃体后脱离与增殖","OCT：评估黄斑是否脱离与黄斑前膜","对侧眼筛查格子样变性与裂孔","排除渗出性脱离病因（炎症、肿瘤、Coats 病）需全身检查"],"grading":"按机制分为孔源性、牵拉性、渗出性；孔源性按范围（象限）、黄斑是否脱离、是否伴玻璃体积血分级；B 超可分级视网膜隆起程度。"},"ddx":[{"name":"糖尿病视网膜病变（ey_dr）","point":"与本类 ey_dr 的鉴别点：DR 的牵拉性脱离有长期糖尿病史与增殖膜，视力下降较缓；孔源性脱离伴闪光感与飞蚊骤增，B 超见裂孔与玻璃体后脱离。玻璃体积血时两者的 B 超均需仔细辨别。"},{"name":"年龄相关性黄斑变性（ey_amd）","point":"与本类 ey_amd 的鉴别点：AMD 为黄斑区中心视力下降与视物变形，无周边视野缺损与裂孔；RRD 的视野缺损从周边开始向中心扩展，B 超见视网膜隆起。"},{"name":"玻璃体后脱离伴飞蚊症","point":"闪光感与飞蚊为主，眼底见玻璃体环（Weiss 环），无视网膜隆起与裂孔；若伴裂孔则需激光封闭。"},{"name":"视网膜中央动脉阻塞","point":"突发无痛性视力丧失，眼底见视网膜苍白与黄斑樱桃红斑，无闪光感与飞蚊骤增，B 超视网膜平伏。"},{"name":"渗出性视网膜脱离（炎症、肿瘤）","point":"无裂孔，视网膜下液随体位移动，可伴葡萄膜炎或脉络膜肿瘤，需抗炎/抗感染或肿瘤治疗，不急于手术。"}],"tx":{"drug":[{"name":"局部麻醉药（利多卡因等，术中用）","dose":"遵说明书；常用 2% 利多卡因球后或局部浸润","note":"手术或激光前使用，注意过敏史与局部浸润范围","renal":"遵说明书","hepatic":"重度肝功能不全减量","interact":"与其他局麻药合用注意总量"},{"name":"毛果芸香碱滴眼液（孔源性术后支持）","dose":"1 滴，每日 3–4 次（遵医嘱）","note":"用于术后缩小瞳孔、减少粘连（部分方案，按术者习惯）；并非所有 RRD 术后必需","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与抗胆碱能药全身应用可拮抗缩瞳效果"},{"name":"左氧氟沙星滴眼液（围术期预防）","dose":"1 滴，每日 4–6 次，术前 1–3 天或术后按方案使用","note":"预防眼内炎与切口感染","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min"},{"name":"托吡卡胺滴眼液（术后散瞳/检查）","dose":"1 滴，按需（检查或术后防粘连方案）","note":"短效散瞳，需与术者方案一致；青光眼患者慎用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他抗胆碱能药合用加重散瞳"}],"nonDrug":["孔源性视网膜脱离：尽快手术复位，黄斑未脱离者 24 h 内手术，黄斑已脱离亦应 1 周内处理","巩膜扣带/环扎术：适用于周边裂孔与年轻、无增殖者","玻璃体切除术（PPV）联合气液交换与气体/硅油填充：适用于复杂、多发或后极部裂孔、牵拉性脱离","激光光凝：封闭裂孔（无脱离时）或术中固定","牵拉性脱离以 PPV 解除牵拉，渗出性以治疗原发病为主","术后体位按气体类型要求（面朝下或特定体位）以促进裂孔封闭"],"life":["术后 1 周、1 个月、3 个月复查，硅油眼需评估眼压与白内障","避免剧烈运动、跳水与高海拔飞行（气体填充者，直至气体吸收）","出现视力骤降、飞蚊骤增或闪光感加重立即就诊","对侧眼每 6–12 个月筛查周边视网膜"]},"prog":"黄斑未脱离且 24 h 内手术者约 90% 可达解剖复位，视力预后良好；黄斑脱离超过 7 天者术后视力显著下降；PVR 与再次脱离是主要失败原因（复发率约 10%–20%）。","refs":["《视网膜脱离手术技术专家共识（2022）》","《孔源性视网膜脱离临床诊疗指南（2019）》","AAO Preferred Practice Pattern: Retinal Detachment（2019）"]}]},{"id":"cornea_ocular","name":"角膜与眼表外病","rank":3,"summary":"角膜与眼表疾病的处置核心是明确病原与眼表状态：感染性角膜炎先取标本再强化点药，禁用激素；干眼按泪膜稳定性与分泌功能分层，从人工泪液到抗炎阶梯推进；圆锥角膜以地形图早期识别、用交联阻止进展；眼内炎属眼科急症，须数小时内完成穿刺注药。","compare":[{"diseaseId":"ey_keratitis","dx":"眼痛、畏光、流泪伴视力下降；裂隙灯见角膜浸润与上皮缺损（荧光素染色阳性），重者前房积脓；细菌性浸润边界模糊进展快，真菌性呈羽毛状边缘伴卫星灶，HSV 呈树枝状溃疡","key":"病灶形态与用药史提示病原，涂片/培养与共聚焦显微镜是病原学关键"},{"diseaseId":"ey_dry_eye","dx":"干涩、异物感、烧灼、眼疲劳、视物波动；BUT <10 s、Schirmer Ⅰ <10 mm/5 min、睑板腺功能障碍，角膜点状染色","key":"以泪膜稳定性与泪液分泌两项客观指标分层，无浸润灶"},{"diseaseId":"ey_keratoconus","dx":"青少年进行性近视散光加重；地形图见下方陡峭、最薄点 <500 µm、后表面高度异常；检影剪刀影、Fleischer 环与 Vogt 条纹","key":"角膜地形图与厚度是核心证据，双眼常不对称"},{"diseaseId":"ey_endophthalmitis","dx":"术后 1–7 天或内源性者视力骤降、眼红眼痛；前房积脓、玻璃体混浊、眼睑肿胀，B 超玻璃体回声增强","key":"前房积脓 + 玻璃体炎 + 近期手术史为三联征，需数小时内穿刺注药"}],"diseases":[{"id":"ey_keratitis","name":"角膜炎","aka":["Keratitis","感染性角膜炎","角膜溃疡","细菌性角膜炎","真菌性角膜炎","单纯疱疹病毒性角膜炎"],"rank":1,"basic":{"define":"角膜受病原（细菌、真菌、病毒、阿米巴）侵袭或免疫损伤而产生浸润、溃疡与基质溶解的眼病，可致穿孔、瘢痕与失明；按病原分细菌性、真菌性、单纯疱疹病毒性（HSV）与棘阿米巴性。","risk":["角膜外伤（植物性外伤、异物剔除后）","配戴角膜接触镜（过夜配戴、自来水清洗）","长期局部使用糖皮质激素或免疫抑制剂","眼表疾病与干眼、暴露性角膜病变","糖尿病与免疫抑制","HSV 感染史（诱因：发热、紫外线、应激、手术）"],"epi":"感染性角膜炎是全球第二位致盲原因；我国农村地区真菌性角膜炎占感染性角膜炎的 30%–40%，接触镜相关者以细菌（铜绿假单胞菌、葡萄球菌）与棘阿米巴为主；HSV 角膜炎是最常见的感染性角膜致盲原因之一。"},"patho":"上皮屏障破坏后病原侵入基质。细菌分泌蛋白酶与毒素致基质坏死与溶解，发展快可致后弹力层膨出或穿孔；真菌菌丝沿板层生长、炎症反应较缓，呈羽毛状边缘与卫星灶，对一般抗细菌药不敏感；HSV 潜伏于三叉神经节，再激活后上皮复制形成树枝状溃疡，反复发作致基质盘状水肿与新生血管；棘阿米巴以包囊存于镜盒，引起环形浸润与放射状角膜神经炎。","dx":{"criteria":["眼痛、畏光、流泪、异物感伴视力下降，球结膜睫状或混合充血","角膜上皮缺损、荧光素染色阳性，基质浸润与水肿，重者前房积脓、后弹力层膨出","细菌性：浸润边界模糊、24–48 h 内明显扩大、脓性分泌物，多见于接触镜或外伤后","真菌性：起病数天至数周、植物外伤史、灰白色羽毛状浸润、卫星灶与免疫环，前房积脓黏稠","HSV：上皮型树枝状（末端膨大）或地图状溃疡；基质型盘状水肿伴环形 KP；坏死型伴新生血管","棘阿米巴：接触镜史、环形浸润、放射状神经受累，疼痛与体征不匹配","需排除非感染性（神经营养性、暴露性、自身免疫性）角膜溃疡"],"workup":["视力、眼压（避免按压）、裂隙灯与荧光素染色、角膜知觉","角膜刮片：革兰染色、吉姆萨染色、真菌涂片（10% KOH 或 Calcofluor White）","刮取物培养：血琼脂、巧克力琼脂、沙氏培养基（真菌）、非营养琼脂覆大肠杆菌（棘阿米巴）；镜片与镜盒送培养","活体共聚焦显微镜：快速识别真菌菌丝与棘阿米巴包囊","HSV：临床诊断为主，疑难者行角膜拭子/房水 PCR","前节 OCT 与 B 超：评估溃疡深度、后弹力层膨出与眼内受累","严重或治疗反应差者行角膜活检"],"grading":"按部位分上皮型、基质型（浅/深，伴或不伴坏死）、内皮型；按严重度分轻度（浸润 <2 mm、无前房反应）、中度（2–6 mm、有前房反应）、重度（>6 mm、深基质受累、前房积脓或濒临穿孔）；HSV 分上皮型、基质型、内皮型、神经营养性。"},"ddx":[{"name":"干眼症（ey_dry_eye）","point":"与本类 ey_dry_eye 的鉴别点：干眼泪膜不稳定，上皮点状缺损多位于下方或暴露区，无浸润灶与脓性分泌物，BUT 与 Schirmer 异常；角膜炎有明确浸润灶、多单眼，伴明显睫状充血与前房反应。"},{"name":"眼内炎（ey_endophthalmitis）","point":"与本类 ey_endophthalmitis 的鉴别点：角膜炎病变以前节为主、玻璃体多清晰；眼内炎以玻璃体炎与前房积脓为主、常有内眼手术史。重度角膜炎可继发眼内炎，此时角膜病灶仍为原发来源。"},{"name":"圆锥角膜（ey_keratoconus）","point":"与本类 ey_keratoconus 的鉴别点：圆锥角膜无浸润与脓性分泌物，表现为进行性不规则散光与地形图下方陡峭变薄；角膜炎为急性眼红眼痛伴浸润灶。"},{"name":"非感染性角膜溃疡","point":"神经营养性者无眼痛而角膜知觉减退、缺损边缘卷曲；暴露性者见于眼睑闭合不全、缺损多在下部；自身免疫性者为周边环形变薄。以原发病处理为主，不盲目强化抗感染。"},{"name":"急性闭角型青光眼（eye/glaucoma_cat）","point":"眼痛伴头痛、恶心，眼压骤升 >40 mmHg 与角膜雾状水肿而无浸润灶；角膜炎眼压多正常或偏低。"}],"tx":{"drug":[{"name":"左氧氟沙星滴眼液 0.5%（细菌性强化期）","dose":"负荷 1 滴每 5–15 min 一次共 1 h；随后每 30 min 一次至症状缓解，之后每 1 h 一次，夜间每 2 h 一次；好转后按每 2–4 h 一次减频","note":"细菌性首选氟喹诺酮强化频点；禁忌加压包扎；假单胞菌感染尤需足频点药","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min"},{"name":"妥布霉素 0.3% 强化眼液 / 头孢唑林 50 mg/mL 强化眼液（细菌性联合或替代）","dose":"妥布霉素强化 1 滴每 30–60 min；头孢唑林强化按同频次，可与万古霉素 50 mg/mL 强化眼液交替","note":"革兰阳性球菌（连成链状/葡萄串状）时加万古霉素强化眼液；长期使用氨基糖苷类注意眼表毒性","renal":"眼部局部用药；全身氨基糖苷类按肾功能调整","hepatic":"遵说明书","interact":"与其他眼表药物间隔 5 min"},{"name":"氟康唑滴眼液 0.2%（真菌性）","dose":"1 滴每 1–2 h 一次（强化期），随后每 2–4 h 一次；可用 0.2% 氟康唑注射液代替滴眼","note":"真菌性以局部抗真菌为主；深基质受累或进展者联合那他霉素 5% 滴眼液并按需全身抗真菌","renal":"全身使用时 eGFR <50 减量","hepatic":"肝功能不全者监测肝酶","interact":"与华法林、口服降糖药合用作用增强；注意 CYP 相互作用"},{"name":"那他霉素滴眼液 5%（丝状真菌）","dose":"1 滴每 1–2 h 一次（首 24–48 h），随后每 2–4 h 一次","note":"丝状真菌一线外用抗真菌药；刺激性较强，必要时与氟康唑交替","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他眼表药物间隔 10 min"},{"name":"更昔洛韦眼用凝胶 0.15%（HSV 上皮型）","dose":"1 滴每日 5 次（清醒时每 3 h 一次），疗程 7–14 天","note":"上皮型一线；合并基质型或内皮型需联合全身抗病毒","renal":"眼部局部用药；全身用药肾功能不全需调整","hepatic":"遵说明书","interact":"与眼表其他药物间隔 5–10 min"},{"name":"阿昔洛韦/伐昔洛韦（HSV 基质型、内皮型、坏死型，口服）","dose":"阿昔洛韦 400 mg 口服每日 5 次；或伐昔洛韦 500 mg 口服每日 3 次；疗程 7–10 天，反复发作者维持 400 mg 每日 2 次","note":"基质型与内皮型需全身抗病毒；上皮型以局部为主，禁用激素","renal":"肾功能不全减量（肌酐清除率 <25 mL/min 时给药间隔延长至 12–24 h）","hepatic":"遵说明书","interact":"与肾毒性药物合用增加肾损伤；丙磺舒升高血药浓度"},{"name":"糖皮质激素滴眼液（仅在有效抗感染覆盖下，遵医师评估）","dose":"如 1% 泼尼松龙 1 滴每日 4 次起，逐周减量","note":"病原不明时禁用；真菌性与棘阿米巴禁用；细菌性在充分抗感染下可辅助减轻基质炎症，HSV 仅基质/内皮型在抗病毒覆盖下使用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"免疫抑制可加重感染"},{"name":"复方托吡卡胺滴眼液（睫状肌麻痹）","dose":"1 滴每日 2 次或按需","note":"减轻睫状肌痉挛与虹膜后粘连、缓解疼痛；前房浅者慎用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与抗胆碱能药全身应用加重散瞳"},{"name":"聚己缩胍（PHMB）0.02% / 氯己定 0.02%（棘阿米巴）","dose":"1 滴每 1 h 一次（强化期），随后逐步减频","note":"棘阿米巴角膜炎首选，疗程数周至数月，常需联合角膜移植","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5–10 min"}],"nonDrug":["先取标本（刮片/培养）再开始强化点药，不为求快省略病原学检查","禁止加压包扎与配戴接触镜；病原不明时禁用糖皮质激素","濒临穿孔：组织黏合剂（氰基丙烯酸酯）、羊膜覆盖或治疗性角膜移植","真菌性深基质受累或 1–2 周无效者按需全身抗真菌，眼科与感染科协作","就诊频率：强化期每日或隔日复查浸润大小、上皮修复与前房反应"],"life":["停戴接触镜至角膜完全愈合，镜片与镜盒规范消毒、不用自来水清洗","农事或机械作业佩戴护目镜；眼外伤后立即就诊，不自取植物性异物","HSV 反复发作者避免暴晒、过劳与滥用激素","按医嘱逐步减药，不因症状好转自行停药，避免复燃"]},"prog":"细菌性角膜炎在 24–48 h 内有效抗感染预后较好，延误可致穿孔与眼内炎；真菌性病程长（常 4–8 周），约 15%–30% 最终需角膜移植；HSV 角膜炎 1 年复发率约 20%–30%，反复基质型可致瘢痕与新生血管导致永久视力损害。","refs":["《中国感染性角膜病临床诊疗专家共识（2016）》","《细菌性角膜炎临床诊疗专家共识（2021）》","《单纯疱疹病毒性角膜炎临床诊疗专家共识（2023）》","葛坚、王宁利《眼科学》第 9 版（角膜病）"]},{"id":"ey_dry_eye","name":"干眼症","aka":["Dry Eye Disease","DED","干眼","角结膜干燥症"],"rank":2,"basic":{"define":"泪液与眼表内环境稳态失衡，表现为泪膜不稳定、眼表不适症状与眼表损伤；按机制分水液缺乏型、蒸发过强型（以睑板腺功能障碍 MGD 为主）与混合型。","risk":["年龄增长与女性（绝经后）","长期视屏使用、瞬目减少","长期配戴角膜接触镜","睑板腺功能障碍与睑缘炎","干燥综合征、类风湿关节炎","长期使用含防腐剂滴眼液、抗组胺药、异维 A 酸","低湿环境与空气污染"],"epi":"我国干眼症患病率约 21%–30%，中老年更高；视屏终端使用者与接触镜配戴者症状突出，MGD 相关蒸发过强型占多数。"},"patho":"泪腺分泌减少或睑板腺脂质异常使泪膜稳定性下降、渗透压升高；高渗刺激眼表上皮释放 IL-1β、TNF-α 与 MMP-9，激活固有免疫引起上皮损伤、黏蛋白减少与神经敏化，形成「泪膜不稳定—高渗—炎症—神经敏化」的恶性循环，可出现症状与体征不匹配的神经病理性干眼。","dx":{"criteria":["干涩、异物感、烧灼、眼痒、畏光、眼疲劳、视物波动（用眼后加重）","泪膜破裂时间（BUT）<10 s（<5 s 为重度）","Schirmer Ⅰ 试验（无表面麻醉，5 min）<10 mm（≤5 mm 提示明显泪液缺乏）","角膜荧光素染色或结膜丽丝胺绿染色阳性（下方或暴露区点状着色）","睑板腺功能：挤压见睑脂污浊、睑缘毛细血管扩张、腺口阻塞","症状加至少 1 项客观检查异常，并排除其他眼表疾病"],"workup":["询问用眼习惯、接触镜、全身疾病与用药（抗胆碱能药、抗抑郁药、抗组胺药、利尿剂）","BUT（荧光素或非接触式）、Schirmer Ⅰ、泪液渗透压与 MMP-9 快速检测","角膜与结膜染色、角膜知觉","睑板腺评分、睑缘照相、脂质层分析","泪液分泌极少或老年患者查抗 SSA/SSB 与血糖，排除干燥综合征","疑难病例行泪液蛋白/细胞因子检测"],"grading":"中国干眼专家共识按严重程度分 4 级：Ⅰ 级（轻度，BUT 缩短、轻度染色）；Ⅱ 级（中度，症状加重、需要频繁人工泪液）；Ⅲ 级（重度，明显角膜损伤、丝状角膜炎）；Ⅳ 级（极重度，角膜溃疡或瘢痕，常合并全身免疫病）。"},"ddx":[{"name":"角膜炎（ey_keratitis）","point":"与本类 ey_keratitis 的鉴别点：干眼为双侧慢性症状、浅表点状染色，无浸润灶与前房反应；角膜炎有局灶浸润、脓性分泌物、明显睫状充血与眼痛，多单眼。"},{"name":"圆锥角膜（ey_keratoconus）","point":"与本类 ey_keratoconus 的鉴别点：圆锥角膜视力进行性下降、不规则散光、地形图异常而泪膜多正常；干眼症状与 BUT/Schirmer 相关、地形图正常。"},{"name":"睑缘炎与睑板腺功能障碍","point":"MGD 是干眼最常见共存病因，睑缘红痒、睑脂异常、蒸发过强；两者常合并，需同时治疗睑缘与眼表。"},{"name":"过敏性结膜炎","point":"季节性眼痒、结膜乳头、水样分泌物，嗜酸性粒细胞阳性；干眼以干涩与烧灼为主，二者可重叠。"},{"name":"视屏终端相关视觉疲劳","point":"长时间用眼后眼胀、视物模糊，因瞬目减少致泪膜破裂；结合用眼时长与 BUT 变化鉴别，以用眼习惯调整为主。"}],"tx":{"drug":[{"name":"玻璃酸钠滴眼液 0.1%–0.3%","dose":"1 滴每日 3–4 次或按需；频繁使用（>6 次/日）或重度者选无防腐剂单剂量包装，每日 4–6 次","note":"一线基础治疗；长期频繁使用含防腐剂制剂加重眼表损伤","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min"},{"name":"羧甲基纤维素钠滴眼液 0.5%–1%","dose":"1 滴每日 3–4 次或按需","note":"黏滞性较高，适合睑缘周围干燥与夜间使用；可致短暂视物模糊","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min"},{"name":"环孢素滴眼液 0.05%（或 0.1% 乳液）","dose":"1 滴每日 2 次，双眼；起效常需 1–3 个月","note":"用于中重度干眼伴眼表炎症；可减少炎症、增加杯状细胞；注意刺痛与结膜充血","renal":"眼部局部用药，全身吸收极低","hepatic":"遵说明书","interact":"与其他眼表药物间隔 5–10 min"},{"name":"地夸磷索钠滴眼液 3%","dose":"1 滴每日 6 次","note":"促泪液与黏蛋白分泌，适合水液缺乏型，常与人工泪液联用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与其他滴眼液间隔 5 min"},{"name":"氟米龙滴眼液 0.1%（短期抗炎）","dose":"1 滴每日 2–3 次，疗程 2–4 周，遵医嘱逐步减量","note":"中重度炎症期短程使用；监测眼压与角膜上皮，禁止长期自行使用","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"与环孢素滴眼液可联合，注意眼压"},{"name":"自体血清滴眼液 20%（重度）","dose":"1 滴每日 4–6 次（按配置方案）","note":"含生长因子，用于重度干眼或眼表损伤；需无菌制备与冷链保存","renal":"不适用（自体局部制剂）","hepatic":"不适用（自体局部制剂）","interact":"与含防腐剂药物间隔 5–10 min"}],"nonDrug":["去除诱因：每 20 min 远眺 20 s、避免空调直吹、减少接触镜佩戴","MGD 治疗：40–45 ℃ 热敷 10–15 min、睑缘清洁与睑板腺按摩；可行强脉冲光（IPL）、热脉动或腺管疏通","泪道栓塞：Schirmer 低、需频繁人工泪液者可选可吸收或不可吸收栓","湿房镜、加湿器、睡前眼膏","角膜绷带镜、羊膜覆盖用于严重眼表损伤","干燥综合征等系统病需风湿免疫科联合治疗"],"life":["每日规律热敷与睑缘清洁并长期坚持","保持室内湿度、增加瞬目，减少风直吹","优先无防腐剂滴眼液，不自行长期使用激素","每 1–3 个月复查 BUT、Schirmer 与染色，按分型调方案"]},"prog":"多数轻中度干眼经人工泪液与眼表护理症状缓解，但多慢性反复；MGD 相关型需长期睑缘维护；Ⅲ–Ⅳ 级（丝状角膜炎、角膜溃疡、干燥综合征）预后较差，角膜溃疡可致穿孔与视力丧失。","refs":["《中国干眼专家共识（2020 年）》","《中国睑板腺功能障碍诊断与治疗专家共识（2017）》","葛坚、王宁利《眼科学》第 9 版（眼表疾病）","TFOS DEWS II Report（2017）"]},{"id":"ey_keratoconus","name":"圆锥角膜","aka":["Keratoconus","KC","角膜圆锥"],"rank":3,"basic":{"define":"以角膜中央或旁中央（多偏下方）进行性变薄、前突呈圆锥形的非炎症性角膜扩张病变，导致不规则散光与矫正视力进行性下降；多双眼发病（常不对称），青少年起病。","risk":["青春期至 30 岁（高峰 15–25 岁）","长期揉眼（最重要可控诱因）","过敏性结膜炎与春季角结膜炎、哮喘","唐氏综合征","结缔组织病（Marfan、Ehlers-Danlos）","家族史","长期配戴软性接触镜"],"epi":"患病率约 1/2000–1/500，亚洲部分地区基于地形图筛查的研究可高达 1/50；青少年期发病，是青少年角膜移植的主要适应证之一。"},"patho":"角膜基质胶原纤维排列紊乱、蛋白多糖减少、MMP 活性升高，基质变薄与力学强度下降；氧化应激与慢性揉眼造成的上皮损伤参与发病。角膜前突改变屈光力、产生不规则散光与高次像差；重者后弹力层破裂致急性角膜水肿（急性圆锥，hydrops）。","dx":{"criteria":["青少年起病，进行性近视与散光快速增加、频繁换镜仍矫正不佳","检影呈剪刀影、角膜反光不规则，最佳矫正视力下降","裂隙灯见 Fleischer 环、Vogt 条纹（压迫消失）、下方角膜变薄（Munson 征多见于重者）","角膜地形图（Scheimpflug）：下方陡峭、上下非对称，最大曲率 >47 D 或 Kmax 异常升高","最薄点 <500 µm，后表面高度图异常、BAD-D 指数升高","OCT 见上皮下与基质光密度增高，可作早期敏感指标","需与不规则散光的其他原因（准分子术后膨隆、PMD）鉴别"],"workup":["视力、验光（框架镜与硬镜矫正视力）、角膜曲率","角膜地形图/断层扫描：前/后表面高度、厚度、Kmax、BAD-D","超声测厚与 Scheimpflug 厚度交叉核对","裂隙灯查 Fleischer 环、Vogt 条纹、Munson 征","接触镜配戴者软镜停戴 1–2 周、硬镜停戴 2–4 周后复查，避免伪像","对侧眼筛查（双眼常不对称）","急性圆锥：观察角膜水肿与瘢痕，必要时 OCT","合并过敏性结膜炎者行过敏评估"],"grading":"Amsler-Krumeich 分级：Ⅰ 级（<48 D，最薄点 >500 µm）、Ⅱ 级（48–53 D，400–500 µm）、Ⅲ 级（>53 D，200–400 µm）、Ⅳ 级（>55 D、<200 µm 或瘢痕）；进展定义：12–18 个月内 Kmax 增加 ≥1.5 D 或最薄点减少 ≥25 µm。"},"ddx":[{"name":"角膜炎（ey_keratitis）","point":"与本类 ey_keratitis 的鉴别点：圆锥角膜无眼红眼痛与浸润灶，为进行性视力下降；急性圆锥（hydrops）可致急性水肿与视力骤降，易误为角膜炎，但无浸润灶且既往地形图异常。"},{"name":"干眼症（ey_dry_eye）","point":"与本类 ey_dry_eye 的鉴别点：干眼致泪膜不稳定与视力波动，地形图正常；圆锥角膜地形图见下方陡峭与变薄、泪膜指标多正常。"},{"name":"高度规则散光与近视散光","point":"框架镜或接触镜易矫正，地形图对称、无局部陡峭与变薄；圆锥角膜地形图非对称，矫正后仍有高次像差。"},{"name":"准分子激光术后角膜扩张","point":"有屈光手术史，术后数月至数年出现近视回退与不规则散光、地形图膨隆；靠病史鉴别，处理类似（交联加镜片）。"},{"name":"透明边缘性角膜变性（PMD）","point":"下方周边窄带变薄呈「啤酒杯底座」样伴明显散光；圆锥角膜变薄位于中央或旁中央下方。"}],"tx":{"drug":[{"name":"核黄素（维生素 B2）滴眼液 0.1%（紫外光交联术 CXL）","dose":"Dresden 方案：0.1% 核黄素（含 20% 右旋糖酐）每 3–5 min 一次点用 30 min，前房见核黄素后 UVA 365 nm、3 mW/cm² 照射 30 min，期间每 3–5 min 点药；加速方案遵术式规程","note":"交联用于阻止进展而非矫正视力；术后早期上皮缺损与疼痛、角膜雾状混浊需数月恢复","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"术后避免含防腐剂滴眼液直至上皮愈合"},{"name":"术后抗菌与糖皮质激素滴眼液","dose":"左氧氟沙星 0.5% 每日 4 次共 7–10 天；0.1% 氟米龙或 1% 泼尼松龙每日 4 次，遵医嘱逐月减量","note":"注意基质雾状混浊、角膜内皮与眼压","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"抗过敏滴眼液（合并过敏性结膜炎）","dose":"奥洛他定 0.1% 每日 2 次；必要时 0.1% 氟米龙每日 2 次短程（遵医嘱）","note":"控制揉眼与过敏炎症是延缓进展的重要环节","renal":"眼部局部用药，一般无特殊调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["角膜交联（CXL）：年轻、有进展证据或最薄点 <470 µm 者首选；对侧眼同时评估并考虑预防性交联","镜片矫正：框架镜可行者优先；较重者用硬性透气镜（RGP）、圆锥专用镜片或巩膜镜","角膜基质环植入：用于轻中度、不能耐受接触镜者，改善不规则散光","角膜移植：Ⅳ 级、瘢痕或不能配镜者行板层（DALK）或穿透性（PKP）角膜移植","急性圆锥：局部激素加高渗盐水点眼、绷带镜与睫状肌麻痹，多 6–10 周自行消退","严格禁止揉眼，配镜需地形图引导"],"life":["严格勿揉眼，避免眼球按压","每 3–6 个月复查地形图、Kmax、最薄点厚度与矫正视力","儿童与青少年进展快，交联后仍需长期随访","高度近视散光者行周边视网膜评估"]},"prog":"常在 30 岁后自然稳定，但青少年期进展较快；交联后 90% 以上可阻止进展，已丧失的视力无法恢复，需长期配镜或角膜移植；DALK 排斥风险低于 PKP，术后 5 年存活率 >90%。","refs":["《中国圆锥角膜诊断与治疗专家共识（2019）》","《角膜胶原交联术临床应用专家共识（2022）》","葛坚、王宁利《眼科学》第 9 版（角膜病）","Global Consensus on Keratoconus and Ectatic Diseases（2015）"]},{"id":"ey_endophthalmitis","name":"眼内炎","aka":["Endophthalmitis","术后眼内炎","内源性眼内炎","感染性眼内炎"],"rank":4,"basic":{"define":"眼球内组织（葡萄膜、玻璃体、视网膜）的严重感染性炎症，按来源分术后、外伤后、内源性（血源性播散）与滤过泡相关；起病急、进展快，是眼科最紧急的急症之一。","risk":["内眼手术（白内障术后约 0.03%–0.2%）","术中后囊破裂、玻璃体脱出、手术时间长","开放性眼外伤（尤其植物、土壤污染）","眼内异物残留","糖尿病、免疫抑制、长期全身激素","远处感染灶（肝脓肿、肺炎、心内膜炎、静脉吸毒）","青光眼滤过泡渗漏"],"epi":"白内障术后急性眼内炎约 70% 为凝固酶阴性葡萄球菌；外伤后眼内炎发生率约 3%–7%，芽孢杆菌（Bacillus）进展极快；内源性者以克雷伯菌、大肠埃希菌与肺炎链球菌常见，多伴全身脓毒症。"},"patho":"病原经切口、外伤通道或血行进入玻璃体并快速增殖；玻璃体缺乏有效免疫防御，细菌与毒素迅速扩散至视网膜与葡萄膜，引起玻璃体炎、血管渗漏与循环障碍。葡萄球菌与芽孢杆菌毒素强，可在 24–48 h 内造成视网膜坏死与不可逆视力丧失；内源性者原发病灶持续释菌。","dx":{"criteria":["近期内眼手术（术后 1–7 天）或外伤后，视力骤降伴眼红眼痛加重","前房积脓、前房闪辉、瞳孔区渗出膜、玻璃体混浊（絮状团块）","眼睑肿胀、结膜水肿，眼压可降低或升高","B 超玻璃体回声增强、密集点状回声与膜增厚，可伴视网膜脱离","房水与玻璃体穿刺涂片、革兰染色、培养与药敏，必要时 PCR","内源性者需查找原发灶（血培养、尿检、胸腹部影像、超声心动图）","疑真菌性（病程缓、玻璃体白色团块、免疫抑制）需真菌培养与涂片"],"workup":["视力、眼压、裂隙灯（前房、瞳孔、虹膜后粘连），可透见时查眼底","B 超（玻璃体、视网膜、巩膜完整性）","前房穿刺与玻璃体穿刺（0.1–0.2 mL）送涂片与培养，PPV 标本一并送检","内源性：血培养 2 套、CRP、降钙素原、肝功能、胸腹盆 CT、超声心动图","血糖、肾功能（抗生素剂量调整）、凝血","随访每 1–3 天复评视力、前房与玻璃体"],"grading":"按来源分术后、外伤、内源性、滤过泡相关；按病程分急性（<6 周，多为细菌）与慢性（数周至数月，低毒力球菌或丙酸杆菌）；视力仅光感或无光感提示预后差、应更积极手术。"},"ddx":[{"name":"角膜炎（ey_keratitis）","point":"与本类 ey_keratitis 的鉴别点：眼内炎以玻璃体炎与弥漫眼部炎症为主，角膜相对透明；角膜炎浸润局限于角膜、玻璃体多清晰。重度角膜溃疡可继发眼内炎，需同时处理两处。"},{"name":"干眼症（ey_dry_eye）","point":"与本类 ey_dry_eye 的鉴别点：干眼慢性干涩、无前房积脓与玻璃体混浊；眼内炎为急性剧痛伴视力骤降与弥漫炎症。"},{"name":"中毒性前节综合征（TASS）","point":"术后 12–48 h 前房大量细胞与前房积脓，但玻璃体多不受累，激素治疗后 24–48 h 迅速好转；眼内炎玻璃体受累明显并进行性加重。鉴别困难时按眼内炎穿刺注药更安全。"},{"name":"晶状体过敏性葡萄膜炎","point":"有晶状体皮质残留，前房渗出与 KP，无剧痛与明显玻璃体混浊，激素有效。"},{"name":"眼内淋巴瘤","point":"慢性复发性玻璃体炎，激素一过性有效、无前房积脓；玻璃体活检具诊断价值。"}],"tx":{"drug":[{"name":"万古霉素（玻璃体腔注射，革兰阳性菌）","dose":"1 mg/0.1 mL 玻璃体腔注入，单次，必要时 48–72 h 重复","note":"急性术后眼内炎经验性必选；注意配制浓度与无菌操作；不常规全身使用（玻璃体穿透差）","renal":"腔内注射全身吸收极低；全身使用时按肾功能调整","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"头孢他啶（玻璃体腔注射，革兰阴性菌）","dose":"2.25 mg/0.1 mL 玻璃体腔注入，单次；与万古霉素组成经典两药方案","note":"过敏者可用阿米卡星 0.4 mg/0.1 mL 替代（注意黄斑毒性）","renal":"腔内注射吸收极低；全身使用按 eGFR 调整","hepatic":"遵说明书","interact":"与氨基糖苷类联合增加肾毒性"},{"name":"地塞米松 0.4 mg（或曲安奈德 4 mg）玻璃体腔注射","dose":"0.1 mL 玻璃体腔注入，可与抗生素同次操作","note":"减轻炎症与视网膜损伤；真菌性慎用或不用，不能替代抗菌治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"免疫抑制可加重真菌与细菌感染"},{"name":"全身抗生素（严重、外伤或内源性）","dose":"莫西沙星 400 mg 静脉每日 1 次；或头孢曲松 1–2 g 每日 1 次，按病原与药敏调整；重症由感染科会诊制定","note":"血-视网膜屏障限制全身用药进入玻璃体，全身用药不能代替腔内注药","renal":"头孢曲松与莫西沙星一般无需按肾功能调整，肾功能不全仍应监测","hepatic":"莫西沙星重度肝损伤慎用","interact":"莫西沙星与 QT 延长药合用监测心电图；与含铝镁抗酸剂间隔 2 h"},{"name":"伏立康唑/两性霉素 B（真菌性）","dose":"腔内注射两性霉素 B 5 µg/0.1 mL 或伏立康唑 100 µg/0.1 mL；全身伏立康唑负荷 6 mg/kg 每 12 h 共 2 次，随后 4 mg/kg 每 12 h","note":"需眼科与感染科共同制定；伏立康唑玻璃体穿透好，监测肝功能与视觉异常","renal":"伏立康唑静脉制剂含环糊精，eGFR <50 改用口服；两性霉素 B 肾毒性明显","hepatic":"伏立康唑中重度肝损伤减量并监测肝酶","interact":"伏立康唑与多种 CYP3A4 底物（他克莫司、华法林、他汀）相互作用强烈"}],"nonDrug":["急诊处置：疑似眼内炎立即通知眼科，24 h 内完成玻璃体穿刺注药","常用方案：万古霉素 1 mg 加头孢他啶 2.25 mg 腔内注射，可加地塞米松 0.4 mg","玻璃体切除（PPV）：视力 ≤光感、玻璃体致密混浊、外伤或注药后 48 h 无改善者尽早手术","先穿刺注药再切除，房水与玻璃体标本均送培养","内源性者处理原发灶（肝脓肿引流、拔除导管），系统抗生素 4–6 周","外伤者修创与异物取出，污染伤口评估全身抗生素"],"life":["术后出现眼红加重、眼痛或视力下降立即就诊，不等待复诊日","糖尿病围术期控制血糖，免疫抑制者评估风险","内源性者全身感染随访与影像复查","多数患者最终视力 ≤0.1，需低视力康复"]},"prog":"急性术后眼内炎 24 h 内接受腔内注药者约 40%–60% 视力可恢复至 0.5 以上；仅光感或芽孢杆菌感染者预后差；内源性眼内炎总体视力预后差（多 <0.1），病死率随原发感染严重度升高。","refs":["《中国眼科手术后感染性眼内炎诊疗专家共识（2023）》","《眼内炎临床诊疗专家共识（2019）》","葛坚、王宁利《眼科学》第 9 版（眼外伤与眼内感染）","Endophthalmitis Vitrectomy Study（1995）"]}]},{"id":"ocular_trauma_strab","name":"眼外伤与屈光斜视","rank":4,"summary":"眼外伤先分「开放 vs 闭合、化学 vs 机械」：化学烧伤要立即大量冲洗（30 分钟以上）再谈其他，穿通伤禁冲洗禁压迫、给抗生素并急诊修补；斜弱视的关键是**在视觉发育关键期（<8 岁）发现并治疗**。","compare":[{"diseaseId":"ey_trauma","dx":"锐器或异物伤后眼球壁全层破裂、前房变浅、瞳孔变形、眼压降低、视力骤降","key":"禁冲洗、禁加压、禁揉眼；给抗生素与破伤风，急诊手术修补"},{"diseaseId":"ey_chem_burn","dx":"酸碱化学物入眼后剧痛、畏光流泪、结膜苍白、角膜混浊，pH 试纸异常","key":"治疗就是冲洗——立即、大量、持续 ≥30 分钟，碱烧伤比酸烧伤更重"},{"diseaseId":"ey_strabismus_amblyopia","dx":"眼位偏斜（内/外斜）、遮盖试验阳性；弱视者矫正视力低于同龄正常且无器质性病变","key":"弱视治疗有年龄窗口（<8 岁效果最好）；先矫正屈光不正再遮盖"},{"diseaseId":"ey_refractive","dx":"视力模糊、验光见球镜或柱镜度数异常，矫正视力可正常","key":"屈光不正矫正后视力正常，与弱视（矫正后仍差）的关键区别"},{"diseaseId":"ey_orbital_cellulitis","dx":"眼睑红肿热痛、眼球突出、眼球运动受限与疼痛、发热，CT 见眶内软组织密度增高","key":"与眶隔前蜂窝织炎的关键区别在眼球运动与视力受累——眶内者需静脉抗生素"}],"diseases":[{"id":"ey_trauma","name":"眼球穿通伤与眼内异物","aka":["Open Globe Injury","Penetrating Ocular Trauma","眼球破裂伤"],"rank":1,"basic":{"define":"眼球壁（角膜或巩膜）全层破裂的开放性眼外伤，可伴眼内异物、眼内组织脱出与外伤性白内障、视网膜脱离。是眼科急症，处理不当可致失明甚至交感性眼炎（对侧眼失明）。","risk":["工作中金属敲击、打磨（金属碎屑高速飞入）","锐器刺伤（刀、剪、笔）","爆炸伤与车祸","儿童玩耍（铅笔、玩具枪、激光笔）","未佩戴护目镜的作业"],"epi":"眼外伤是单眼盲的首要原因，其中开放性眼外伤约占 20%–30%。金属眼内异物在工地作业者中高发，交感性眼炎发生率约 0.2%–0.5%（伤后数周至数月）。"},"patho":"外力使眼球壁全层破裂，眼内容物（虹膜、晶状体、玻璃体）可脱出，眼压骤降；异物进入眼内可带菌并引起化脓性眼内炎；后期因外伤性炎症与免疫反应可发生交感性眼炎（针对葡萄膜抗原的自身免疫反应，累及对侧眼）。眼球破裂后血-眼屏障破坏，是眼内炎的高危基础（尤其含有机物的异物）。","dx":{"criteria":["外伤史（锐器、异物、爆炸）与视力骤降、眼痛、流泪","体征：眼球壁可见伤口（角膜或巩膜的裂口）、**前房变浅或消失**、瞳孔变形（虹膜嵌顿）、眼压降低（低于 5 mmHg）、眼内容物脱出、前房积血","**眼内异物**：金属异物可在 X 线/CT 上显影（CT 为首选，可显示金属与非金属异物及位置）；MRI **禁用于疑金属异物**（可致异物移动加重损伤）","B 超：评估玻璃体积血、视网膜脱离与异物位置（但禁用于疑开放性伤口未闭合时压迫眼球）","需排除：**禁做任何压迫性检查（眼压测量需轻柔或避免）**、禁冲洗、禁散瞳（除必要评估）","记录伤后视力（判断预后最重要的单因素）"],"workup":["**优先保护眼球**：戴眼罩（硬质）防止压迫，避免用力、咳嗽与呕吐","视力与瞳孔检查（相对性传入瞳孔传导阻滞提示视神经损伤）","眼眶 CT（首选，评估异物位置、眼球完整性、眶壁骨折、球后血肿）","**禁用 MRI（疑金属异物时）**","全身评估（多发伤按 ATLS 流程）、破伤风免疫状态","术前：血常规、凝血、必要时血型与交叉配血"],"grading":"按 Ocular Trauma Classification（Birmingham Eye Trauma Terminology, BETT）：开放 vs 闭合；按损伤类型分穿通伤、贯通伤、球内异物；按受伤分区：Ⅰ 区（角膜至角膜缘后 5 mm）、Ⅱ 区（角膜缘后 5 mm 至 10 mm）、Ⅲ 区（>10 mm），分区与预后显著相关。"},"ddx":[{"name":"化学烧伤（ey_chem_burn）","point":"与化学烧伤的鉴别：化学烧伤有明确化学物接触史、弥漫性角膜与结膜损伤、眼压多正常；穿通伤可见局限性伤口、前房变浅与眼压降低。"},{"name":"斜视与弱视（ey_strabismus_amblyopia）","point":"与斜弱视的鉴别：斜弱视无急性外伤史与眼球壁破损，眼位偏斜但眼球完整。"},{"name":"屈光不正（ey_refractive）","point":"与屈光不正的鉴别：屈光不正为慢性视力模糊、眼球完整、眼压正常；穿通伤为急性外伤后视力骤降。"},{"name":"眶周蜂窝织炎（ey_orbital_cellulitis）","point":"与眶内感染鉴别：眶内感染有红肿热痛与眼球运动受限，但眼球壁完整、无前房变浅；穿通伤可继发感染，两者需同时评估。"},{"name":"角膜擦伤（闭合性）","point":"角膜上皮缺损但角膜基质完整（荧光素染色见表面着色），前房深度正常、眼压正常；与穿通伤的关键区别在眼球壁是否全层破裂。"},{"name":"外伤性前房积血（闭合性）","point":"眼球完整、前房内血液沉积（可分层），但无角膜/巩膜裂口；常为钝挫伤所致。"}],"tx":{"drug":[{"name":"静脉抗生素（预防眼内炎）","dose":"开放性眼外伤常规给予：头孢唑林 1–2 g 静脉 q8h + 必要时加万古霉素（15–20 mg/kg q8–12h，疑 MRSA 或污染重）；眼内炎治疗需玻璃体腔注药（万古霉素 1 mg/0.1 mL + 头孢他啶 2.25 mg/0.1 mL）","note":"**所有开放眼外伤应尽早给抗生素**（静脉 + 局部）；眼内炎需急诊玻璃体腔注药与玻璃体切除","renal":"万古霉素按 CrCl 调整并监测谷浓度","hepatic":"头孢唑林无需调整","interact":"万古霉素与氨基糖苷类合用增加肾毒性"},{"name":"破伤风预防","dose":"未全程接种或接种史不明者：破伤风类毒素 0.5 mL 肌注 + 破伤风免疫球蛋白 250 IU 肌注（伤口污染重者）","note":"所有开放性眼外伤需评估破伤风免疫状态","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"局部抗生素滴眼液","dose":"左氧氟沙星 0.5% 滴眼液 q1h（术后或术前）；或妥布霉素滴眼液","note":"用于预防与治疗表面感染；**穿通伤未修补前不应冲洗或滴药**（会带入眼内）","renal":"无需调整","hepatic":"无需调整","interact":"氨基糖苷类滴眼液长期使用可致角膜毒性"},{"name":"睫状肌麻痹剂（术后/评估用）","dose":"阿托品 1% 或环喷托酯 1% 滴眼，每日 2–3 次（术后）","note":"用于麻痹睫状肌、减轻疼痛与预防虹膜后粘连；**术前散瞳需权衡（可能加重眼内容物脱出）**","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"镇痛（对乙酰氨基酚 / 阿片类）","dose":"对乙酰氨基酚 500–1000 mg q6h；剧痛可短期用阿片类；**禁用 NSAIDs（增加出血风险）**","note":"眼部外伤疼痛剧烈，需充分镇痛；避免恶心呕吐（增加眼压）","renal":"按 CrCl 调整","hepatic":"限量","interact":"NSAIDs 与抗凝合用出血风险（故禁用）"}],"nonDrug":["**急救原则：不冲洗、不压迫、不揉眼、不自行滴药**；用硬质眼罩保护（不压迫眼球），抬高床头，避免用力（打喷嚏、咳嗽时张口）","**急诊手术修补**：一期缝合眼球壁、恢复眼球完整性；原则上越早越好（多主张 24–48 小时内），眼内炎或大量眼内容物脱出者需立即","**眼内异物取出**：由专科通过外路或玻璃体切除取出（磁性异物可用磁铁，非磁性需显微手术）","二期手术：外伤性白内障摘除、玻璃体切除、视网膜脱离修复、青光眼引流","**交感性眼炎预防**：严重葡萄膜嵌顿者可在修补时切除脱出的葡萄膜组织；术后随访对侧眼（数月至数年）"],"life":["术后体位与活动限制（避免剧烈运动、提重物、屏气）","**单眼包扎与保护**，防止对侧眼受伤（伤后一侧失明者对侧眼保护尤为重要）","定期复查：1 周、1 个月、3 个月、半年（评估眼压、视网膜、对侧眼）","职业防护教育：金属作业戴护目镜（一级预防最有效）","长期随访对侧眼（交感性眼炎可在伤后数十年发生，出现畏光、视力下降需立即就诊）"]},"prog":"预后与受伤分区、伤后视力、有无眼内异物与感染密切相关：Ⅰ 区（角膜）且伤后视力 ≥20/200 者，最终视力 ≥20/40 的比例可达 60%–70%；Ⅲ 区（后巩膜）者预后显著差（视力 ≥20/40 者 <20%）。眼内炎未及时处理者视力丧失率极高。交感性眼炎经规范激素与免疫抑制治疗，约 50%–70% 可保留有用视力。","refs":["《眼科学》第 9 版（人民卫生出版社）眼外伤章","《机械性眼外伤无光感眼处理专家共识》（中华医学会眼科学分会，2019）","1996 Birmingham Eye Trauma Terminology (BETT) / Ocular Trauma Classification Group","2019 International Globe and Adnexal Trauma Epidemiology Study (IGATES) Report","《我国开放性眼外伤诊治专家共识》（2021）"]},{"id":"ey_chem_burn","name":"眼化学烧伤","aka":["Chemical Ocular Burn","眼化学伤","碱烧伤","酸烧伤"],"rank":2,"basic":{"define":"化学物质（酸、碱或其他刺激性物质）进入眼部造成的角膜、结膜与眼前段组织的化学性损伤。**碱性物质因可皂化脂肪与溶解蛋白而向深部渗透，损伤远重于酸性物质**。","risk":["工业事故（石灰、水泥、氨水、氢氧化钠、硫酸）","家庭清洁剂（管道疏通剂、漂白剂）","实验室化学品","电池破裂（碱性内容物）","儿童误将化学品当眼药水（包装混淆）"],"epi":"眼化学伤约占眼外伤的 7%–10%，其中碱烧伤约占 60%。职业性眼化学伤占工伤性眼外伤的相当比例，是导致角膜缘干细胞缺乏与永久性视力损害的重要原因。"},"patho":"**碱烧伤**：碱与组织脂肪发生皂化反应，并溶解蛋白质，破坏细胞膜，使化学物质持续向眼内渗透（可达前房），造成角膜基质溶解、虹膜与睫状体坏死、前房炎症；晚期因角膜缘干细胞破坏导致角膜结膜化、角膜新生血管与睑球粘连。**酸烧伤**：酸使组织蛋白凝固形成凝固层（痂皮），一定程度上限制了渗透，故损伤多限于表层，但强酸（氢氟酸除外）仍可致深层损伤。损伤深度决定预后，角膜缘缺血范围是最重要的预后指标。","dx":{"criteria":["明确的化学物接触史（记录化学品种类、浓度与接触时间）","**症状**：剧痛、畏光、流泪、眼睑痉挛、视力下降","**体征**：结膜充血、水肿或苍白（缺血）、角膜上皮缺损与混浊（荧光素染色）、角膜缘缺血（**最重要的预后指标**，按钟点记录受累范围）、前房炎症、严重者见角膜穿孔","**pH 测定（必需）**：结膜囊 pH >7.4 提示碱性物残留，需继续冲洗","评估眼睑与皮肤受累（化学物可继续损伤皮肤）","**Roper-Hall（Hughes）分级**与 **Dua 分级**（见下）"],"workup":["**立即冲洗（在检查之前）**：至少 30 分钟生理盐水或林格液冲洗，随后测结膜囊 pH","视力、瞳孔与眼球运动检查","裂隙灯检查：荧光素染色、角膜缘缺血范围、前房炎症与前房细胞","**前节 OCT 或超声**（评估角膜厚度与是否穿孔，需在冲洗后）","全身评估（化学物可经皮肤吸收或吸入，必要时毒理学评估）","记录化学品的 SDS（安全数据表）以指导后续治疗"],"grading":"**Roper-Hall（Hughes）分级**：Ⅰ 级——预后良好，角膜无混浊或仅轻度，角膜缘无缺血；Ⅱ 级——角膜轻度至中度混浊但虹膜细节可见，角膜缘缺血 <1/3；Ⅲ 级——角膜全层混浊、虹膜细节不可见、角膜缘缺血 1/3–1/2；Ⅳ 级——角膜混浊伴穿孔或前房积脓、角膜缘缺血 >1/2。**Dua 分级**按角膜缘缺血钟点数与角膜混浊更细化（Ⅰ–Ⅵ 级）。"},"ddx":[{"name":"眼球穿通伤（ey_trauma）","point":"与穿通伤的鉴别：化学烧伤有化学品接触史、弥漫性角膜与结膜损伤、眼压多正常或升高，无局部裂口；穿通伤有伤口、前房浅与眼压降低。**注意：电池破裂或爆炸可同时有化学伤与穿通伤**。"},{"name":"角膜炎（ey_keratitis）","point":"与角膜炎的鉴别：角膜炎为渐进性疼痛与角膜浸润，有病原（细菌/病毒/真菌）证据；化学烧伤为急性剧痛与明确化学品史。"},{"name":"斜视与弱视（ey_strabismus_amblyopia）","point":"与斜弱视鉴别：斜弱视无急性疼痛与化学物接触史。"},{"name":"屈光不正（ey_refractive）","point":"与屈光不正的鉴别：屈光不正为慢性视力模糊，无急性疼痛与角膜损伤。"},{"name":"眶周蜂窝织炎（ey_orbital_cellulitis）","point":"与眶内感染鉴别：眶内感染以红肿热痛与眼球突出为主，无化学品接触史，角膜完整。"},{"name":"紫外线性角膜病变（电光性眼炎）","point":"有紫外线暴露史（电焊、紫外线灯），双眼疼痛流泪但角膜上皮缺损呈弥漫点状，无化学品接触史，24–48 小时自愈。"}],"tx":{"drug":[{"name":"生理盐水 / 林格液（冲洗）","dose":"**立即用 1–2 L 生理盐水持续冲洗至少 30 分钟**（可用静脉输液管、洗眼器或冲眼壶）；随后测 pH，若 >7.4 继续冲洗","note":"**冲洗是唯一最重要且最紧急的治疗**，必须在任何检查之前开始；碱烧伤需延长冲洗时间；若颗粒物（石灰）残留须先行取出再冲洗","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"局部糖皮质激素（1% 醋酸泼尼松龙）","dose":"1% 醋酸泼尼松龙滴眼液 q1–2h（清醒时），疗程 7–10 天，随后逐渐减量","note":"**用于抑制前房炎症与减少角膜溶解**，但**角膜上皮未愈合前需谨慎**（激素抑制上皮修复并增加感染风险）；严重者需眼科严格监测","renal":"无需调整","hepatic":"无需调整","interact":"长期使用增加感染与青光眼风险"},{"name":"局部抗生素（预防感染）","dose":"左氧氟沙星 0.5% 或莫西沙星 0.5% 滴眼液 q1–2h；必要时加用杆菌肽/妥布霉素","note":"上皮缺损者需预防性抗生素（尤其角膜溶解与坏死组织存在时）","renal":"无需调整","hepatic":"无需调整","interact":"氨基糖苷类长期使用致角膜毒性"},{"name":"枸橼酸 / 抗坏血酸（维生素 C）全身补充（碱烧伤）","dose":"维生素 C 口服 1–2 g/d（或局部 10% 抗坏血酸滴眼）；枸橼酸钠局部滴眼（抑制多形核白细胞与胶原酶）","note":"**碱烧伤可致局部维生素 C 缺乏（其氧化产物堆积）与胶原溶解**，补充有助减少角膜融解（证据有限但广泛使用）","renal":"大剂量维生素 C 在肾功能不全者慎用","hepatic":"无需调整","interact":"无特殊"},{"name":"局部睫状肌麻痹剂（环喷托酯/阿托品）","dose":"环喷托酯 1% 或阿托品 1% 滴眼，每日 2–3 次","note":"缓解睫状肌痉挛所致疼痛、预防虹膜后粘连","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"局部胶原酶抑制剂（10% N-乙酰半胱氨酸）","dose":"10% N-乙酰半胱氨酸滴眼液 q2h（用于严重碱烧伤）","note":"抑制胶原酶活性以减少角膜溶解（证据有限）","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"口服镇痛","dose":"对乙酰氨基酚 500–1000 mg q6h；必要时阿片类","note":"化学烧伤疼痛剧烈，需充分镇痛（避免 NSAIDs 以防出血）","renal":"按 CrCl 调整","hepatic":"限量","interact":"—"}],"nonDrug":["**紧急冲洗（第一优先）**：就地取材，用自来水也可（不要因找生理盐水而延误），持续 ≥30 分钟","**清除残留颗粒（石灰、水泥）**：翻转眼睑、清除穹窿部颗粒后再冲洗","**羊膜移植（AMT）**：用于中重度（Roper-Hall Ⅲ/Ⅳ 级、Dua Ⅳ–Ⅵ）角膜缘缺血者，可促进上皮愈合、抑制炎症与减少瘢痕（伤后 1–2 周内效果最佳）","**角膜缘干细胞移植（CLET）**：晚期角膜缘干细胞缺乏者的治疗","睑球粘连分离与睑裂缝合（预防粘连）","严重角膜溶解/穿孔：结膜瓣遮盖或角膜移植（急诊或二期）","避免使用局部麻醉滴眼液长期镇痛（抑制上皮修复、角膜毒性）"],"life":["**职业防护**：戴护目镜、工作场所配备洗眼器（最重要的一级预防）","家庭化学品妥善存放，避免用饮料瓶盛装（儿童误伤）","发生化学伤时**先冲洗再就医**（不应等救护车而不冲洗）","长期随访：角膜上皮愈合、角膜新生血管、睑球粘连、青光眼（随访 ≥1 年）","视力康复：视情况配镜、角膜移植或人工角膜"]},"prog":"预后与分级高度相关：Roper-Hall Ⅰ/Ⅱ 级多数可获得良好视力；Ⅲ 级约 50% 遗留视力损害；Ⅳ 级（角膜缘缺血 >1/2 或穿孔）视力预后差，可致角膜盲。**碱烧伤预后劣于酸烧伤**。及时充分的冲洗可将预后改善一个等级以上——这是最重要的可干预因素。","refs":["《眼科学》第 9 版（人民卫生出版社）眼化学伤章","《我国眼化学烧伤诊断和治疗专家共识》（中华医学会眼科学分会，2019）","2012 Roper-Hall (Hughes) Classification of Ocular Chemical Burns（原始文献回顾）","2016 Dua Classification of Ocular Chemical Burns (Br J Ophthalmol)","2008 EUS/ESCRS Guidelines for Management of Chemical Injuries"]},{"id":"ey_strabismus_amblyopia","name":"斜视与弱视","aka":["Strabismus","Amblyopia","斜视","弱视","懒惰眼"],"rank":3,"basic":{"define":"斜视：双眼视轴不平行，一眼注视时另一眼偏斜（内斜、外斜或垂直斜）。弱视：视觉发育期内（通常 <8–9 岁）因异常视觉经验（斜视、屈光参差、屈光不正或形觉剥夺）导致单眼或双眼最佳矫正视力下降，且无器质性病变。","risk":["早产与低出生体重","家族史（斜视与屈光不正）","高度屈光不正与屈光参差（两眼度数相差 ≥1.00 D）","先天性白内障、上睑下垂、角膜混浊（形觉剥夺）","发育迟缓与神经系统异常","脑瘫与唐氏综合征"],"epi":"斜视患病率约 2%–4%（儿童）；弱视患病率约 1%–4%，是儿童单眼视力损害最常见的原因。**治疗窗口为视觉发育关键期（<8 岁，尤其 <6 岁）**，成人后治疗效果显著下降。"},"patho":"视觉发育存在「关键期」（出生至约 8 岁），期间异常的视觉经验（斜视导致双眼视觉竞争、屈光参差导致一眼长期模糊、形觉剥夺导致光线不能到达视网膜）使大脑视觉皮层的相应区域得不到正常刺激，形成皮层性视觉功能抑制。斜视若在早期未矫正，还会导致双眼视功能（立体视）发育障碍与异常视网膜对应。弱视不仅是视力下降，还伴有对比敏感度降低、空间定位与注视稳定性异常。","dx":{"criteria":["**斜视**：遮盖试验（交替遮盖）见眼球移动；角膜映光法（Hirschberg 试验）见光点偏离瞳孔中心；三棱镜遮盖试验定量偏斜度数；眼球运动检查（追视、扫视）评估各方向运动","内斜视：儿童内斜视最常见为**调节性内斜视**（远视 + 高 AC/A，需散瞳验光）；外斜视多为间歇性（疲劳、走神时出现）","**弱视诊断（需满足全部）**：① 最佳矫正视力低于同龄正常下限（3 岁 <0.5、4–5 岁 <0.6、≥6 岁 <0.8，或用对数视力表）；② 存在明确的弱视病因（斜视、屈光参差 ≥1.00 D、双眼高度屈光不正或形觉剥夺）；③ 无器质性眼病可解释视力下降","**散瞳验光（睫状肌麻痹验光）是儿童必需的检查**（阿托品 1% 或环喷托酯），可发现远视、散光与屈光参差","双眼视功能评估：立体视（Titmus 或 Random Dot）、融合功能、Worth 四点试验","**遮盖法评估**（家庭筛查）：单眼遮盖 1–2 小时观察患儿是否抗拒（抗拒提示被遮盖眼视力好，不抗拒提示弱视）"],"workup":["视力检查（按年龄选方法：婴幼儿用注视与追随、3 岁以上用图形/字母视力表）","**睫状肌麻痹验光**（阿托品 1% 每日 3 次×3 天或环喷托酯）","眼位与眼球运动检查（角膜映光、遮盖试验、三棱镜定量）","眼底与屈光间质检查（排除器质性病变：先天性白内障、视神经病变、视网膜病变）","双眼视功能与立体视评估","必要时头颅与眼眶影像（斜视伴神经系统体征、或内斜视 + 视乳头水肿）","婴幼儿需排除视网膜母细胞瘤（白瞳症）"],"grading":"斜视按方向分内斜、外斜、垂直斜（上/下斜）与旋转斜；按时间分恒定性、间歇性与隐斜；按病因分共同性（非麻痹性）与麻痹性。弱视按病因分斜视性、屈光参差性、屈光不正性与形觉剥夺性；按程度分轻（矫正视力 0.6–0.8）、中（0.2–0.5）、重（<0.2）。"},"ddx":[{"name":"屈光不正（ey_refractive）","point":"与屈光不正的鉴别：屈光不正矫正后视力正常、眼位正常；弱视的关键特征是**矫正后视力仍低**，且斜视者眼位偏斜。"},{"name":"眼球穿通伤（ey_trauma）","point":"与眼外伤的鉴别：外伤有急性病史与眼球结构破坏；斜弱视为慢性、无外伤史、眼球完整。"},{"name":"化学烧伤（ey_chem_burn）","point":"与化学烧伤的鉴别：有化学品接触史与急性剧痛、角膜损伤；斜弱视无急性症状。"},{"name":"先天性白内障（形觉剥夺性弱视的原因）","point":"白瞳、晶状体混浊，需在出生后数周内手术（否则形成不可逆形觉剥夺性弱视）；是弱视的病因而非替代诊断。"},{"name":"视网膜母细胞瘤","point":"白瞳症（猫眼）、斜视可为早期表现，需眼底检查与超声/CT 排除（婴幼儿斜视必查眼底）。"},{"name":"假性斜视（内眦赘皮）","point":"角膜映光与遮盖试验正常，外观似内斜实为内眦赘皮或鼻梁宽，随年龄改善。"},{"name":"眼球震颤","point":"节律性眼动，可伴视力低下（婴儿型眼球震颤），需与弱视鉴别（弱视眼多无眼球震颤，除形觉剥夺性）。"}],"tx":{"drug":[{"name":"阿托品滴眼液（压抑疗法）","dose":"1% 阿托品滴眼液，健眼每周 1–2 次（或 0.01% 低浓度每日一次）；疗程按视力反应调整（数周至数月）","note":"**阿托品压抑疗法是遮盖的替代方案**（ATS 研究显示与遮盖效果相当，依从性可能更好）；副作用包括畏光、面红、睫状肌麻痹（阅读困难）；1% 阿托品在幼儿可能致全身中毒（脸红、发热、心动过速）","renal":"无需调整","hepatic":"无需调整","interact":"与抗胆碱能药合用增加全身抗胆碱反应"},{"name":"睫状肌麻痹剂（验光用）","dose":"环喷托酯 1% 滴眼（验光前 30–45 分钟，共 2–3 次）或阿托品 1% 每日 3 次×3 天（内斜视与高度远视者）","note":"用于儿童散瞳验光；阿托品作用持续 2 周（需告知家长）","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"局部麻醉（斜视手术）","dose":"成人用 0.5% 丙美卡因或利多卡因滴眼；儿童全身麻醉","note":"儿童的斜视矫正手术需全麻","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"肉毒毒素 A（部分内斜视）","dose":"注射至内直肌（剂量按肌肉体积，遵专科方案，通常 1.25–2.5 U）","note":"用于小角度内斜视或术后残余斜视的替代治疗；需专科操作","renal":"无需调整","hepatic":"无需调整","interact":"与氨基糖苷类合用可能增强神经肌肉阻滞"}],"nonDrug":["**弱视治疗（在矫正屈光不正的基础上）**：","① **睫状肌麻痹验光 + 全屈光矫正眼镜**（第一步，尤其屈光参差与高度远视）；","② **遮盖疗法**：遮盖健眼，2–6 岁每天 2–6 小时（按弱视程度），是金标准；需定期复查（遮盖过度可致「遮盖性弱视」——健眼视力下降）；","③ **阿托品压抑疗法**（替代遮盖，适用于不能耐受遮盖者）；","④ **视觉训练**（精细目力活动、电脑辅助训练，作为辅助）；","**斜视矫正**：调节性内斜视靠戴镜（全矫远视）即可矫正；非调节性内斜视与间歇性外斜视需**手术矫正眼位**（通常在视觉发育关键期内完成，以利双眼视功能建立）；","**形觉剥夺（先天性白内障、上睑下垂）**：需尽早手术（出生后 6–8 周内），术后立即开始遮盖与屈光矫正","**筛查**：儿童 3 岁起应做视力筛查（我国规定学龄前儿童视力检查）"],"life":["严格遵医嘱遮盖时长（**过度遮盖可致健眼弱视**，必须定期复查）","遮盖期间鼓励近距离精细活动（穿珠、画画），提高依从性与疗效","佩戴眼镜需长期坚持（调节性内斜视者摘镜即复发）","定期复查视力、眼位与双眼视功能（每 1–3 个月）","治疗可持续至 8–10 岁，部分患儿需维持到视觉成熟；**成人弱视治疗近年有新的证据（知觉训练），但效果远逊于儿童期**"]},"prog":"弱视在关键期内治疗效果良好：<6 岁开始治疗者约 70%–90% 视力显著改善；7–9 岁效果下降；10 岁后治疗反应差（但近年研究显示成人仍有部分可塑性）。约 25% 的弱视在停止治疗后复发（尤其 <8 岁停药者），需随访至视觉成熟。间歇性外斜视进展为恒定性者双眼视功能受损；早期矫正者立体视恢复较好。","refs":["《眼科学》第 9 版（人民卫生出版社）斜视与弱视章","《弱视诊断专家共识（2021 年）》（中华医学会眼科学分会斜视与小儿眼科学组）","《中国儿童睫状肌麻痹验光及安全用药专家共识（2019）》","2017 American Academy of Ophthalmology Preferred Practice Pattern: Amblyopia","2012 Pediatric Eye Disease Investigator Group (PEDIG) Amblyopia Treatment Studies"]},{"id":"ey_refractive","name":"屈光不正","aka":["Refractive Error","近视","远视","散光","Myopia","Hyperopia","Astigmatism"],"rank":4,"basic":{"define":"眼在调节静止状态下，平行光线经屈光系统后不能聚焦于视网膜上，导致视物模糊。按焦点位置分近视（焦点在视网膜前）、远视（焦点在视网膜后）与散光（不同子午线屈光力不同）。","risk":["**近视**：遗传（父母近视）、长时间近距离用眼、户外活动不足（<2 小时/天）、光照不足、过早近距离阅读","**远视**：多为先天性（眼轴短）","**散光**：角膜形态不规则（多为先天性）","早产与低出生体重","糖尿病（血糖波动致屈光变化）"],"epi":"我国儿童青少年近视率居世界前列：小学生约 35%–45%、初中生约 70%、高中生约 80% 以上（国家卫健委 2020 年数据）。高度近视（>−6.00 D）占青少年约 10%，是视网膜脱离、黄斑病变与青光眼的高危因素。"},"patho":"屈光状态由眼轴长度与角膜/晶状体屈光力共同决定。**轴性近视**（最常见）：眼轴过度增长（正常成人约 24 mm），每增长 1 mm 约增加 −3.00 D。眼轴过度增长伴随巩膜变薄与生物力学改变，是高度近视并发症（后巩膜葡萄肿、视网膜变性、黄斑劈裂、视网膜脱离、开角型青光眼）的解剖基础。远视多为眼轴偏短；散光由角膜（或晶状体）各子午线曲率不一致所致。调节与集合的平衡（AC/A 比值）在屈光不正的症状表现中起重要作用。","dx":{"criteria":["症状：远视力模糊（近视）、近视力模糊或视疲劳（远视，年轻者可代偿）、视物变形或重影（散光）、眯眼、头痛与眼疲劳","**主观验光（插片/综合验光仪）与客观验光（检影/自动验光）**：确定球镜（S）、柱镜（C）与轴位（A）","**儿童必须睫状肌麻痹验光**（排除调节痉挛造成的假性近视）","近视分度（我国标准）：轻度 −0.50 至 −3.00 D、中度 −3.25 至 −6.00 D、高度 >−6.00 D","远视：按度数分低（<+2.00 D）、中（+2.00–+5.00 D）、高（>+5.00 D）","散光：按度数分低（<1.00 D）、中（1.00–2.00 D）、高（>2.00 D）","**眼轴测量（IOL Master/生物测量）**：评估近视进展与高度近视风险"],"workup":["视力（远/近）与最佳矫正视力","**睫状肌麻痹验光**（儿童与青少年必做）","检影验光与主觉验光","角膜曲率与眼轴长度（生物测量）","裂隙灯与眼底检查（高度近视者查周边视网膜变性、格子样变性、黄斑）","眼压与视盘评估（高度近视者青光眼风险升高）","双眼视功能与调节功能评估（视疲劳明显者）"],"grading":"近视按度数分轻/中/高度（见上）；按病程分稳定型与进展型（年增长 >0.50 D 为进展）；按有无眼底改变分单纯性近视与病理性近视（伴后巩膜葡萄肿、黄斑病变等）。"},"ddx":[{"name":"斜视与弱视（ey_strabismus_amblyopia）","point":"与弱视的关键鉴别：屈光不正**矫正后视力正常**；弱视矫正后视力仍低于正常且有明确弱视病因。屈光参差可同时导致屈光不正与弱视。"},{"name":"眼球穿通伤（ey_trauma）","point":"与眼外伤的鉴别：外伤有急性病史与眼球结构损伤；屈光不正为慢性、眼球完整。"},{"name":"化学烧伤（ey_chem_burn）","point":"与化学烧伤的鉴别：有化学品接触史与急性疼痛、角膜损伤。"},{"name":"角膜炎与干眼（ey_keratitis）","point":"可致视力波动与视疲劳，但验光结果正常、有角膜病变体征；屈光不正无角膜病变。"},{"name":"白内障（ey_cataract）","point":"渐进性视力下降伴晶状体混浊，验光可因晶状体屈光指数改变而呈现「近视漂移」；需裂隙灯区分。"},{"name":"糖尿病性屈光改变","point":"血糖波动致晶状体渗透性水肿，出现一过性近视或远视漂移，血糖控制后恢复；验光结果不稳定是线索。"},{"name":"圆锥角膜（ey_keratoconus）","point":"进行性散光与视力下降、角膜地形图见下方陡峭，与规则散光不同（散光不规则且矫正视力差）。"}],"tx":{"drug":[{"name":"低浓度阿托品（0.01%–0.05%，近视进展控制）","dose":"0.01% 阿托品滴眼液每晚 1 滴，或 0.025%/0.05%（按研究方案）；疗程通常 2 年，需监测","note":"**延缓儿童近视进展的有效手段**（LAMP 研究：0.05% 效果最佳但畏光更明显）；0.01% 反弹较明显；我国已有 0.01% 制剂获批（需按适应症）；用药前需验光、眼轴与调节功能评估","renal":"无需调整","hepatic":"无需调整","interact":"与其他抗胆碱药合用增加全身反应；与调节功能异常相关"},{"name":"环喷托酯 / 阿托品（验光用）","dose":"环喷托酯 1% 滴眼 2–3 次；阿托品 1% 每日 3 次×3 天（高度远视与内斜视）","note":"睫状肌麻痹验光必需","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"人工泪液（视疲劳与干眼共存时）","dose":"0.1%–0.3% 玻璃酸钠滴眼液，每日 3–4 次","note":"缓解长时间用眼后的干涩与视疲劳（非治疗屈光不正本身）","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**框架眼镜**：最安全、最常用的矫正方式（儿童与青少年首选）；儿童需全矫（尤其远视与屈光参差）以避免弱视","**角膜塑形镜（OK 镜）**：夜间佩戴，可矫正近视并延缓进展（需规范验配与随访，警惕感染性角膜炎）；适用于 −0.50 至 −6.00 D 的青少年","**离焦设计框架镜与软性接触镜**（周边离焦镜片、多焦软镜）：有延缓近视进展的证据","**角膜屈光手术（LASIK/SMILE/PRK）**：适用于屈光稳定（近 2 年变化 <0.50 D）、≥18 岁、角膜厚度足够的成人；术前需全面评估（角膜地形图排除圆锥角膜）","**有晶状体眼人工晶状体植入（ICL）**：适用于高度近视、角膜薄不宜激光手术者","**近视防控的行为干预**：**每天户外活动 ≥2 小时**（最强证据）、控制近距离用眼（20-20-20 法则）、保证充足光照与阅读距离 ≥33 cm"],"life":["**儿童青少年每半年验光与眼轴监测**（评估进展速度）","高度近视者（>−6.00 D）每年查眼底（周边视网膜变性、黄斑），避免剧烈碰撞性运动与跳水","出现闪光感、飞蚊突然增多、视野缺损立即就诊（视网膜脱离预警）","角膜接触镜需严格卫生（每日更换护理液、不戴镜睡觉、游泳时摘镜）","读写环境光照充足（≥300 lux）、桌椅高度合适","避免长时间连续近距离用眼（每 40 分钟休息 10 分钟）"]},"prog":"单纯性近视在成年后（约 18–20 岁）多趋于稳定；进展型近视（年增长 >0.50 D）可持续至成年，与高度近视并发症风险相关。高度近视者视网膜脱离风险约 1%–2%（较一般人群高 5–10 倍），黄斑病变与青光眼风险亦升高。干预措施（户外活动、低浓度阿托品、离焦镜片、OK 镜）可延缓进展约 30%–60%，但无法逆转。","refs":["《眼科学》第 9 版（人民卫生出版社）屈光不正章","《儿童青少年近视防控适宜技术指南（更新版）》（国家卫生健康委，2021）","《近视防治指南（2024 年版）》（国家卫生健康委）","2019 IMI – Clinical Myopia Control Trials and Instrumentation Report (Invest Ophthalmol Vis Sci)","2016 LAMP Study: Low-Concentration Atropine for Myopia Progression (Ophthalmology)"]},{"id":"ey_orbital_cellulitis","name":"眶周与眶内感染","aka":["Orbital Cellulitis","Preseptal Cellulitis","眶蜂窝织炎","眶隔前蜂窝织炎"],"rank":5,"basic":{"define":"眶隔前蜂窝织炎指眼睑与眶隔前软组织的感染；**眶内蜂窝织炎**指眶隔后组织的感染，可致眼球突出、运动受限、视神经损害与海绵窦血栓形成，是需要静脉抗生素与住院的急症。两者以眶隔为界。","risk":["鼻窦炎（尤其筛窦炎，是最常见的前驱）","面部皮肤感染、睑腺炎、泪囊炎","眼部外伤或术后","牙源性感染","免疫抑制、糖尿病、儿童（流感嗜血杆菌已因疫苗减少，现以肺炎链球菌与金葡菌为主）"],"epi":"眶内蜂窝织炎发病率约 1.6–2.5/10 万，儿童多见（平均 5–7 岁）。约 60%–80% 继发于鼻窦炎。成人中糖尿病与免疫抑制者的真菌性（毛霉）感染需警惕。"},"patho":"感染由邻近结构（筛窦、额窦、眼睑皮肤）直接蔓延或血行播散至眶内脂肪。眶内为封闭腔室，炎症水肿使眶内压升高，压迫视神经与眼动脉，可致视力丧失；感染可沿眶静脉蔓延至海绵窦（海绵窦血栓形成）。病原以肺炎链球菌、金黄色葡萄球菌、流感嗜血杆菌（未接种疫苗地区）为主；外伤后可为葡萄球菌或厌氧菌；糖尿病/免疫抑制者的毛霉病进展凶险（数天内可致死）。","dx":{"criteria":["**眶隔前**：眼睑红肿热痛，但**无眼球突出、无眼球运动受限、无视力下降**（眼球本身检查正常）","**眶内**：眼睑红肿 + **眼球突出** + **眼球运动受限与运动痛** + 结膜水肿 + 视力下降（可晚出现）+ 发热","**关键鉴别体征**：眼球运动受限与眼球突出提示眶内（需住院静脉抗生素）；仅有眼睑红肿且眼球运动正常多为眶隔前","危险信号（提示需急诊影像与专科处理）：视力下降、相对性传入瞳孔传导阻滞、眼球固定、剧烈疼痛、意识改变、双侧受累（海绵窦血栓）","**影像**：**眼眶增强 CT（首选）**——见眶内脂肪密度增高、眼外肌增粗、眶周脓肿（环形强化）、鼻窦积液与骨破坏；MRI 更敏感（尤其疑海绵窦血栓与颅内受累）","儿童需评估鼻窦（最常见感染源）"],"workup":["详细检查：视力、瞳孔（RAPD）、眼球运动（九个方向）、眼球突出测量（Hertel 突眼计）、眼压、眼底（视乳头水肿）","**眼眶增强 CT（平扫 + 增强）**——评估脓肿、鼻窦炎、骨膜下脓肿","血常规、CRP、PCT、血培养（阳性率约 20%–30%）","鼻窦评估（必要时耳鼻喉会诊）","**糖尿病与免疫抑制者**：鼻咽部检查、活检排除毛霉病（黑色焦痂）、血糖与免疫状态评估","腰椎穿刺与头颅 MRI（疑脑膜炎或海绵窦血栓）"],"grading":"按解剖分眶隔前（preseptal）与眶内（orbital），眶内再按 Chandler 分类：Ⅰ 期眶隔前蜂窝织炎；Ⅱ 期眶内蜂窝织炎；Ⅲ 期骨膜下脓肿；Ⅳ 期眶内脓肿；Ⅴ 期海绵窦血栓形成。分级决定治疗强度（Ⅲ 期以上常需手术引流）。"},"ddx":[{"name":"眼球穿通伤（ey_trauma）","point":"与穿通伤的鉴别：外伤后眼球壁破裂、前房变浅与眼压降低；眶内感染眼球完整但可有外伤史（外伤后感染需同时评估）。"},{"name":"斜视与弱视（ey_strabismus_amblyopia）","point":"与斜视的鉴别：斜视为慢性眼位偏斜、无红肿热痛与发热；眶内感染的眼球运动受限是急性、伴疼痛与炎症。"},{"name":"化学烧伤（ey_chem_burn）","point":"与化学烧伤的鉴别：有化学品接触史、角膜与结膜弥漫性损伤，无眼球突出。"},{"name":"屈光不正（ey_refractive）","point":"与屈光不正的鉴别：屈光不正无红肿、无疼痛与眼球突出。"},{"name":"甲状腺相关眼病（Graves 眼病）","point":"双眼或单眼眼球突出、眼睑退缩与运动受限，但**无急性红肿热痛与发热**，甲状腺功能异常或有自身抗体；病程慢性。"},{"name":"眶内假瘤（特发性眼眶炎性综合征）","point":"急性疼痛、眼球突出与运动受限，但**无发热与感染灶**（鼻窦正常），对激素反应迅速；需与感染鉴别（活检可确诊）。"},{"name":"海绵窦血栓形成","point":"双侧受累、眼球固定、脑神经麻痹（Ⅲ、Ⅳ、Ⅵ、“V1”）、意识改变，MRI/MRV 确诊；是眶内感染的最严重并发症。"},{"name":"毛霉病（免疫抑制者）","point":"糖尿病酮症酸中毒或免疫抑制者急性进展、鼻部黑色焦痂、剧烈疼痛，需紧急活检与两性霉素 B（病死率极高）。"}],"tx":{"drug":[{"name":"静脉抗生素（眶内蜂窝织炎，经验性）","dose":"**万古霉素 15–20 mg/kg q8–12h（覆盖 MRSA 与肺炎链球菌）+ 头孢曲松 2 g q12h 或头孢噻肟 2 g q6–8h（覆盖革兰阴性与流感嗜血杆菌）**；疑厌氧菌（牙源性/鼻窦）加甲硝唑 500 mg q8h；疗程 7–14 天（脓肿或并发症延长至 2–3 周）","note":"**眶内蜂窝织炎必须静脉抗生素并住院**；眶隔前者口服抗生素（阿莫西林克拉维酸 875/125 mg bid）可门诊治疗（儿童需随访）","renal":"万古霉素按 CrCl 调整并监测谷浓度；头孢曲松 CrCl <10 无需调整","hepatic":"头孢曲松在重度肝病减量；甲硝唑肝毒性低","interact":"万古霉素与氨基糖苷类合用增加肾毒性；头孢曲松与含钙输液（新生儿）禁用"},{"name":"口服抗生素（眶隔前蜂窝织炎）","dose":"阿莫西林克拉维酸钾 875/125 mg bid（成人）或按体重（儿童 45 mg/kg/d 分 2 次），疗程 7–10 天","note":"仅适用于眶隔前、无眼球运动受限与视力下降者；24–48 小时无改善或加重需升级为静脉治疗与影像","renal":"CrCl <30 减量","hepatic":"肝毒性（转氨酶升高），需监测","interact":"与华法林合用增强抗凝；与别嘌醇合用增加皮疹"},{"name":"两性霉素 B（毛霉病）","dose":"两性霉素 B 脂质体 5–10 mg/kg/d 静脉；联合泊沙康唑或艾沙康唑","note":"**毛霉病需紧急大剂量抗真菌 + 外科清创**，病死率高；需纠正糖尿病酮症酸中毒","renal":"脂质体肾毒性低于脱氧胆酸盐，仍需监测","hepatic":"肝毒性需监测","interact":"与肾毒性药物合用增加肾损伤；与唑类合用需注意"},{"name":"局部抗生素与鼻腔处理","dose":"左氧氟沙星滴眼液 q2h（合并结膜炎/角膜受累）；生理性海水鼻腔冲洗","note":"辅助治疗；鼻窦炎者需耳鼻喉评估是否需鼻窦手术引流","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"糖皮质激素（争议）","dose":"**不推荐在未充分抗生素覆盖时使用**；仅在明确非感染性（眶内假瘤）时使用","note":"激素可掩盖感染、加重细菌扩散；**在感染未被控制前使用激素是危险的**","renal":"无需调整","hepatic":"遵说明书","interact":"与抗凝、NSAIDs 合用增加消化道出血"}],"nonDrug":["**眶内蜂窝织炎：住院静脉抗生素 + 密切观察（每 6–12 小时评估视力、眼球运动与瞳孔）**","**外科引流**：骨膜下脓肿或眶内脓肿（Chandler Ⅲ/Ⅳ 期）、药物治疗 48–72 小时无改善、视力下降者，需经鼻内镜或外路引流","**鼻窦处理**：合并鼻窦炎者可考虑鼻窦穿刺/引流（与耳鼻喉协同）","眼睑湿敷与局部护理","**毛霉病**：紧急广泛清创（可需眶内容物剜除）以保命"],"life":["治疗期间每日评估视力与眼球运动（恶化提示脓肿形成或颅内蔓延）","儿童需警惕脑膜炎与海绵窦血栓（发热不退、意识改变、双侧受累）","糖尿病与免疫抑制者需严格控制血糖与免疫状态","鼻窦炎规范治疗（避免迁延为眶内感染）","出院后随访 1–2 周（评估残余肿胀与视力）"]},"prog":"眶隔前蜂窝织炎经口服抗生素多可完全恢复。眶内蜂窝织炎在规范静脉抗生素下约 90% 可治愈，但约 10%–20% 需手术引流。视力丧失风险约 5%–10%（视神经压迫或血管闭塞），海绵窦血栓病死率约 15%–30%。毛霉病进展凶险，病死率可达 30%–50%（延误治疗者更高）。","refs":["《眼科学》第 9 版（人民卫生出版社）眼眶病章","《我国眼眶蜂窝织炎诊疗专家共识》（中华医学会眼科学分会，2020）","2017 American Academy of Ophthalmology Preferred Practice Pattern: Orbital Cellulitis（相关章节）","2006 Chandler Classification of Orbital Complications of Sinusitis","2019 ERS/ESCMID Guideline: Mucormycosis（毛霉病部分）"]}]}]},"gen_surg":{"categories":[{"id":"acute_abd","name":"急腹症","rank":1,"summary":"抓住「时间窗」与「是否需要急诊手术」两条主线：先按腹膜刺激征、血流动力学与影像分级，再决定镇痛+禁食+补液观察或急诊剖腹探查/腹腔镜。","compare":[{"diseaseId":"gs_append","dx":"转移性右下腹痛 + 麦氏点压痛反跳痛，Alvarado ≥7 分或 AIR ≥8 分，超声见阑尾直径 >6 mm、不可压缩、周围脂肪回声增强","key":"疼痛先脐周后固定右下腹、麦氏点压痛，影像示阑尾增粗不可压缩"},{"diseaseId":"gs_chole","dx":"右上腹痛放射至右肩背，Murphy 征阳性，超声见胆囊壁增厚 ≥3 mm、胆囊结石、胆囊周围积液；按 TG18 做 I/II/III 级分级","key":"Murphy 征 + 影像示胆囊壁增厚伴结石，TG18 分级决定手术时机"},{"diseaseId":"gs_bowel_obst","dx":"腹胀、呕吐、停止排气排便 + 阵发性绞痛，立位腹平片/CT 见气液平面与肠管扩张（小肠 >3 cm、结肠 >6 cm），CT 为鉴别开闭袢与绞窄的金标准","key":"气液平面 + 肠管扩张；CT 需明确有无闭袢、绞窄与缺血"}],"diseases":[{"id":"gs_append","name":"急性阑尾炎","aka":["Appendicitis","Acute appendicitis"],"rank":1,"basic":{"define":"阑尾腔梗阻（粪石、淋巴滤泡增生）后继发细菌感染所致的急性炎症，可进展为坏疽、穿孔与弥漫性腹膜炎。","risk":["10–30 岁男性最常见","粪石/阑尾结石","阑尾过长、位置异常（盆腔、腹膜后）","饮食纤维摄入少、肠道感染"],"epi":"我国急性阑尾炎年发病率约 60–100/10 万，是急腹症手术的首位病因；终身患病风险约 7%–8%，穿孔率在 12–48 h 就诊者明显升高。"},"patho":"粪石或增生淋巴滤泡阻塞阑尾腔→黏液积聚腔内压升高→壁内静脉淤血、黏膜缺血糜烂→细菌（大肠埃希菌、拟杆菌等）聚集→坏疽穿孔→局部包裹形成脓肿或弥漫性腹膜炎。阑尾动脉为终末支，血供受损更易坏疽。","dx":{"criteria":["典型表现：先脐周/上腹隐痛，4–12 h 后转移并固定于右下腹，伴食欲减退、恶心，低热（≥38 ℃ 约见于 30%）","查体：麦氏点（脐与右髂前上棘连线中外 1/3）压痛、反跳痛；Rovsing 征、Blumberg 反跳痛、腰大肌征阳性提示腹膜受累","Alvarado 评分（MANTRELS，满分 10）：转移性右下腹痛 1、食欲不振 1、恶心呕吐 1、右下腹压痛 2、反跳痛 1、体温 ≥37.3 ℃ 1、白细胞 ≥10×10^9/L 2、中性粒细胞 ≥75% 1；≤4 分基本排除、5–6 分可疑、≥7 分高度怀疑","AIR 评分（Appendicitis Inflammatory Response，满分 12）：呕吐 1、右下腹压痛（轻 1/中 2/强 3）、反跳痛 1、体温 ≥38.5 ℃ 1、白细胞（10–14.9 为 1，≥15 为 2）、中性粒细胞比例（70%–84% 为 1，≥85% 为 2）、CRP（10–49 mg/L 为 1，≥50 mg/L 为 2）；0–4 分风险低、5–8 分可能、9–12 分高度可能","超声：阑尾盲端不可压缩、直径 >6 mm、壁厚 >2 mm、周围脂肪回声增强、粪石强回声伴声影","CT：阑尾增粗 >6 mm、壁强化、周围脂肪条索影、阑尾结石、腔外气体或脓肿提示穿孔；孕妇与儿童首选超声/MRI"],"workup":["血常规（白细胞与中性粒比例）、CRP，可联合 PCT 用于鉴别复杂型感染","尿常规排除输尿管结石、泌尿系感染；育龄女性必查 β-hCG","腹部超声（薄层、加压法）为一线影像；肥胖、超声阴性但临床高度怀疑者行平扫/增强 CT","儿童孕妇首选超声，必要时 MRI（无辐射）","老年人、免疫抑制者症状体征常不典型，白细胞可不高，应放宽 CT 指征","出现弥漫性腹膜炎、休克时按脓毒症处理：血培养、血乳酸、乳酸林格液复苏"],"grading":"临床分型：①单纯性（未穿孔，浆膜完整）；②化脓性/坏疽性；③穿孔性（局限性或弥漫性腹膜炎）；④阑尾周围脓肿（>4–5 cm 者优先经皮穿刺引流）。按 ESR（复杂型 0 vs 1）区分单纯与非复杂型，指导是否可用抗生素非手术方案。"},"ddx":[{"name":"急性胆囊炎（gs_chole）","point":"同属急腹症。急性胆囊炎疼痛固定于右上腹并放射右肩背、Murphy 征阳性，超声见胆囊壁增厚与结石；阑尾炎为转移性右下腹痛、麦氏点压痛。低位胆囊或腹膜后阑尾可混淆，需影像定位。"},{"name":"肠梗阻（gs_bowel_obst）","point":"同属急腹症。肠梗阻以腹胀、呕吐、停止排气排便、阵发性绞痛为主，腹平片见气液平面；阑尾炎较少大量呕吐与显著腹胀，若阑尾炎继发麻痹性肠梗阻需注意。"},{"name":"右侧输尿管结石","point":"绞痛向会阴放射、肉眼/镜下血尿明显、尿频尿急，CT 见输尿管结石伴肾积水；阑尾炎血压不高、无腰背部振水痛。"},{"name":"妇科急症（异位妊娠、卵巢囊肿扭转、盆腔炎）","point":"育龄女性必查 β-hCG 与妇科超声；异位妊娠有停经史、阴道流血、休克倾向；盆腔炎多双侧下腹压痛、宫颈举痛、分泌物增多。"},{"name":"梅克尔憩室炎","point":"多在儿童，位于右下腹但压痛更偏内侧（脐与右侧），超声/CT 见独立于阑尾的憩室，术中阑尾正常时需探查末端回肠 100 cm。"}],"tx":{"drug":[{"name":"头孢呋辛钠（术前预防）","dose":"1.5 g 静脉滴注，切皮前 30–60 min 单次；手术 >4 h 或出血 >1500 mL 术中追加 1 次","note":"青霉素/头孢过敏者改用克林霉素+庆大霉素或磷霉素类，遵说明书","renal":"CrCl <20 mL/min 减半或遵说明书","hepatic":"遵说明书","interact":"避免与含钙输液同通道（头孢曲松尤忌）"},{"name":"头孢曲松钠 + 甲硝唑","dose":"头孢曲松 2 g 静脉滴注 qd + 甲硝唑 0.5 g 静脉滴注 q8h；亦可用厄他培南 1 g qd 或哌拉西林他唑巴坦 4.5 g q8h","note":"用于化脓性、坏疽性、穿孔性等复杂型阑尾炎，合并腹膜污染属治疗性用药，疗程一般术后 3–5 天，脓肿/脓毒症延长至 7–10 天","renal":"CrCl <30 mL/min 头孢曲松无需调整，哌拉西林他唑巴坦需减量，遵说明书","hepatic":"遵说明书","interact":"头孢曲松不与含钙溶液同瓶；甲硝唑禁酒"},{"name":"对乙酰氨基酚/布洛芬（镇痛）","dose":"对乙酰氨基酚 0.5–1 g 口服或静滴 q6h（每日 ≤3 g）；或布洛芬 400 mg 口服 q8h；疼痛剧烈可用氟比洛芬酯 50 mg 静注 q8–12 h","note":"NSAIDs 可能掩盖腹膜炎体征，用药前后需反复腹部查体记录；阿片类（吗啡 5–10 mg 皮下/静注）用于剧烈疼痛，按需滴定","renal":"eGFR <30 慎用 NSAIDs；对乙酰氨基酚肾功能不全时延长给药间隔","hepatic":"肝病 Child-Pugh C 慎用对乙酰氨基酚（每日 ≤2 g），禁用于严重肝衰","interact":"NSAIDs 与抗凝药合用增加出血；羟考酮与 CYP3A4 抑制剂合用需减量"},{"name":"奥美拉唑（应激性溃疡预防）","dose":"40 mg 静脉注射 qd，用于休克、机械通气、大出血等应激性溃疡高危者","note":"低危者不需常规预防","renal":"遵说明书","hepatic":"严重肝功能不全减量","interact":"与氯吡格雷合用减弱其抗血小板作用"}],"nonDrug":["腹腔镜阑尾切除术为标准术式，诊断明确、无弥漫性腹膜炎者宜在诊断后 24 h 内完成；单纯性阑尾炎可考虑 12–24 h 内尽早手术","复杂性阑尾炎（穿孔、脓肿 >4 cm）首选经皮穿刺引流 + 抗生素，6–8 周后择期阑尾切除（间隔阑尾切除术）","单纯性阑尾炎在充分知情、可随访条件下，可选择含覆盖革兰阴性菌与厌氧菌的抗生素非手术方案（如头孢曲松+甲硝唑），失败率与复发率高于手术，需 1 年内随访","孕期阑尾炎应行手术，腹腔镜在孕早期与中期可安全使用，注意穿刺孔位置（宫底以上）","术前禁食 >6 h、补液、留置导尿（预计手术量大）"],"life":["术后 6 h 内早期下床活动，促进肠功能恢复","术后切口观察红肿渗液，腹腔镜穿刺孔感染率约 1%–2%","穿孔性阑尾炎术后警惕腹腔脓肿（术后 5–10 天发热、腹痛），必要时复查 CT","出院后 1 周复查伤口，2 周内避免剧烈运动与重体力"]},"prog":"单纯性阑尾炎行及时手术，并发症率 <5%、死亡率 <0.1%；穿孔性阑尾炎并发症率可达 15%–30%，60 岁以上患者死亡率显著升高。延误手术 >24–36 h 是穿孔与术后并发症的独立危险因素。","refs":["中国医师协会外科医师分会《成人急性阑尾炎诊治专家共识》2021","WSES Jerusalem Guidelines for Acute Appendicitis 2020","中华医学会外科学分会《外科常见感染性疾病抗菌药物应用指南》2019"]},{"id":"gs_chole","name":"急性胆囊炎","aka":["Acute cholecystitis","Acute calculous cholecystitis"],"rank":2,"basic":{"define":"胆囊颈/胆囊管被结石嵌顿梗阻、胆汁淤积继发细菌感染所致的胆囊急性炎症，是急性结石性胆囊炎的主要类型；无结石者占 5%–10%，多见危重患者。","risk":["胆囊结石（女性、40 岁以上、肥胖、多产者高发）","糖尿病、免疫抑制","长期禁食、肠外营养","近期胆囊支架/内镜操作","危重病（ICU 感染性胆囊炎）"],"epi":"我国成人胆囊结石患病率约 10%，其中每年 1%–2% 出现急性胆囊炎；急性胆囊炎占急腹症住院的 10%–15%，女性多于男性。"},"patho":"结石嵌顿于胆囊颈/胆囊管→胆囊内压升高、壁静脉回流受阻→黏膜缺血、水肿→磷脂酶 A2 释放与前列腺素合成→炎症介质浸润→细菌（肠源性革兰阴性菌与厌氧菌）继发感染→壁坏疽、穿孔或胆囊周围脓肿。持续梗阻可压迫胆总管致 Mirizzi 综合征。","dx":{"criteria":["部位定位：右上腹或上腹持续疼痛 >6 h，并放射至右肩背（A 项）","A 项 + 全身炎症（发热 ≥38 ℃、CRP ≥30 mg/L、白细胞 >10×10^9/L）为可疑诊断","A 项 + 影像学阳性（B 项：超声 Murphy 征阳性、胆囊壁增厚 >3 mm、胆囊周围积液）为确切诊断","超声为一线影像：胆囊增大（长径 >9 cm、横径 >4 cm）、壁增厚 ≥3 mm、胆囊颈部结石伴声影、Sonographic Murphy 征阳性","CT/MRI 用于怀疑坏疽、穿孔、胆囊周围脓肿或胆总管结石（MRCP 优于 CT）","必要时 HIDA 核素扫描：胆囊不显影而胆总管显影提示胆囊管梗阻","TG18 重度（Ⅲ级）判断：合并心血管异常（低血压需多巴胺 ≥5 μg/kg/min 或去甲肾上腺素）、神经系统异常（意识障碍）、呼吸异常（PaO2/FiO2 <300）、肾脏异常（少尿或肌酐 >2.0 mg/dL）、肝脏异常（PT-INR >1.5）、血液异常（血小板 <10×10^9/L）任一器官功能障碍"],"workup":["血常规、CRP、肝功能（TBIL、ALT、AST、ALP、GGT）、淀粉酶/脂肪酶、血电解质","腹部超声（含胆囊壁厚度、结石、胆管直径 >8 mm 提示胆管扩张）","拟手术者查凝血、心电图、胸部影像，评估分级（ASA、CCI 查尔森指数）","黄疸或胆管扩张者行 MRCP 或术中胆道造影排除胆总管结石","血培养用于重症、疑似脓毒症者","超声心动、肾功能等器官功能评估（TG18 Ⅲ级判定）"],"grading":"东京指南 TG18 分级：Grade Ⅰ（轻度）——轻度炎症，无不适宜手术的器官功能障碍，病程 <72 h 且选择手术，手术死亡率 0.5%、并发症 7%；Grade Ⅱ（中度）——白细胞 >18×10^9/L、右上腹可触及压痛包块、病程 >72 h、局部明显炎症（坏疽、脓肿、胆汁性腹膜炎、气肿性胆囊炎），手术死亡率 0.5%、并发症 15%；Grade Ⅲ（重度）——合并任一器官功能障碍（见 criteria），手术死亡率 6%、并发症 33%。另分 A（早期/晚期）与 S（手术风险：美国麻醉学会分级 ASA ≥3 或查尔森指数 CCI ≥6）。"},"ddx":[{"name":"急性阑尾炎（gs_append）","point":"同属急腹症。阑尾炎为转移性右下腹痛、麦氏点压痛；胆囊炎为右上腹痛放射右肩、Murphy 征阳性、超声见胆囊壁增厚。高位（盆位）阑尾的疼痛也可位于右上腹，结合影像定位。"},{"name":"肠梗阻（gs_bowel_obst）","point":"同属急腹症。肠梗阻以腹胀、呕吐、停止排气排便为主，腹平片见气液平面；胆囊炎少见大量呕吐，若结石性肠梗阻（Bouveret 综合征）则可出现，CT 见胆管内气体与近端小肠致密结石。"},{"name":"急性胆管炎","point":"Charcot 三联征（腹痛+寒战高热+黄疸），或 Reynolds 五联征（加休克与意识障碍），胆管扩张、胆红素显著升高；胆囊炎通常胆红素轻度升高 <4 mg/dL。"},{"name":"胆总管结石/胆绞痛","point":"阵发性绞痛，多在脂餐后 1–2 h，持续 <6 h 可自行缓解，无全身炎症与胆囊壁增厚，胆总管扩张提示结石。"},{"name":"消化性溃疡穿孔","point":"突发刀割样上腹痛并迅速弥漫，立位腹平片/CT 见膈下游离气体，腹肌板样强直，无 Murphy 征。"},{"name":"右下叶肺炎/胸膜炎","point":"伴咳嗽发热，胸片见浸润影，疼痛随呼吸加重，腹部无明显压痛，抗感染后迅速缓解。"}],"tx":{"drug":[{"name":"头孢曲松钠（术前预防或治疗）","dose":"预防：切皮前 30–60 min 2 g 静脉滴注单次；治疗：2 g qd，合并厌氧菌覆盖时加甲硝唑 0.5 g q8h","note":"适用于 Grade Ⅰ 或术前预防；青霉素过敏者改用克林霉素+庆大霉素或磷霉素，遵说明书","renal":"CrCl <10 无调整，透析后不需追加","hepatic":"严重肝功能不全慎用，遵说明书","interact":"不与含钙溶液同瓶使用"},{"name":"哌拉西林他唑巴坦","dose":"4.5 g 静脉滴注 q8h（q6h 用于重症／脓毒症），疗程 Grade Ⅱ–Ⅲ 一般 5–7 天，合并脓肿或脓毒症 7–14 天","note":"Grade Ⅱ/Ⅲ 首选含抗铜绿假单胞菌与厌氧菌的广谱方案；青霉素过敏者用碳青霉烯类（美罗培南 1 g q8h）","renal":"CrCl 20–40 mL/min 2.25 g q8h，<20 mL/min 2.25 g q12h，或遵说明书","hepatic":"肝衰竭时半衰期延长，遵说明书","interact":"与丙磺舒合用升高血药浓度；避免与氨基糖苷类同瓶"},{"name":"对乙酰氨基酚/氟比洛芬酯（镇痛）","dose":"对乙酰氨基酚 0.5–1 g 静滴 q6h（每日 ≤3 g）；氟比洛芬酯 50 mg 静注 q8–12 h；剧烈疼痛用哌替啶 50–100 mg 肌注或布桂嗪，按需","note":"胆囊炎疼痛评定需在镇痛后重复 Murphy 征，避免镇痛掩盖穿孔体征；禁食期间予静脉镇痛","renal":"NSAIDs 在 eGFR <30 禁用；哌替啶去甲哌替啶蓄积禁用于肾衰与老年人","hepatic":"肝病慎用对乙酰氨基酚","interact":"NSAIDs 与抗凝、利尿剂合用增加肾损风险"},{"name":"山莨菪碱/间苯三酚（解痉）","dose":"间苯三酚 40–80 mg 静脉滴注；山莨菪碱 10 mg 肌注（每日 1–2 次），青光眼、前列腺肥大者禁用","note":"用于明确痉挛性疼痛，需评估后使用；青光眼、前列腺增生禁用山莨菪碱","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗胆碱药合用加强口干心悸"},{"name":"依诺肝素（抗凝预防）","dose":"40 mg 皮下注射 qd，术前 12 h 停用；术后 8–12 h 恢复；高危 VTE 者 40 mg bid","note":"腹腔镜术后血栓预防，CrCl <30 减量或不主张用药，遵说明书","renal":"CrCl <30 mL/min 40 mg qd 或改用普通肝素","hepatic":"肝衰竭慎用，监测抗 Xa 因子","interact":"阿司匹林、NSAIDs、氯吡格雷增加出血"}],"nonDrug":["Grade Ⅰ：诊断后尽早（最好 72 h 内）行腹腔镜胆囊切除术（LC），急诊 LC 与延迟手术相比并发症与住院时间更低","Grade Ⅱ：经早期抗感染与支持后，如局部炎症明显但可耐受手术，仍应行早期 LC（72 h 内），由经验丰富医师操作","Grade Ⅲ：先器官支持与广谱抗感染，必要时经皮胆囊穿刺引流（PCD）；病情稳定后择期 LC；不能耐受手术者行 PCD + 长期置管或引流管拔出","手术高风险（CCI ≥6、ASA ≥3）者：PCD 为首选桥接；或经内镜胆囊引流（EUS-GBD）","合并胆总管结石：LC + 术中/术后 ERCP 取石，胆管炎者先行 ERCP","术后常规放置引流（高危 Grade Ⅱ/Ⅲ），24–48 h 评估拔除"],"life":["低脂饮食，急性期禁食、补液纠正电解质","糖尿病者控制血糖（目标 7.8–10 mmol/L），高血糖显著增加胆囊坏疽与切口感染风险","术后早期下床活动，警惕胆汁漏（腹痛、发热、引流黄绿色液体）需复查超声/CT 或 ERCP","胆囊切除后 10%–20% 出现短暂腹泻，低脂饮食 3–6 个月多可缓解"]},"prog":"及时手术者死亡率 <1%，Grade Ⅲ 仍约 6%；非手术保守治疗复发率 1 年内可达 20%–30%。老年、糖尿病、心血管病与 Grade Ⅲ 是死亡的主要危险因素；化脓/坏疽/穿孔征象者宜放宽手术指征。","refs":["Tokyo Guidelines 2018 (TG18) for acute cholecystitis","中华医学会外科学分会胆道外科学组《急性胆囊炎诊治指南》2018","中国医师协会外科医师分会《腹腔镜胆囊切除术规范化操作指南（2021 版）"]},{"id":"gs_bowel_obst","name":"肠梗阻","aka":["Small bowel obstruction","Mechanical bowel obstruction","肠栖阻"],"rank":3,"basic":{"define":"肠内容物因机械性或动力性因素不能顺利通过，表现为腹痛、呕吐、腹胀、停止排气排便；机械性肠梗阻需鉴别有无闭袢与绞窄。","risk":["腹部手术史（粘连性梗阻占小肠梗阻 60%–75%）","腹外疝（嵌顿）","消化道肿瘤","克罗恩病、放射性肠炎","胆石/异物、肠套叠（儿童）"],"epi":"小肠梗阻约占急腹症手术的 20%，粘连为首位病因；老年人结肠梗阻以结直肠癌与粪石/乙状结肠扭转为主，结直肠癌所致梗阻占 20%–30%。"},"patho":"机械性梗阻近端肠管扩张、肠腔内压升高→肠壁静脉回流受阻、水肿→动脉灌注障碍→肠壁坏死穿孔；肠腔内液体与气体大量丢失（呕吐/ sequestration）致低容量、低钾低氯性碱中毒。闭袢梗阻因近远端同时被堵，腔内压升高更快，绞窄风险最高。动力性梗阻（术后肠麻痹、假性梗阻）无机械性阻塞点。","dx":{"criteria":["四联症状：腹痛（阵发性绞痛或持续性伴阵发加重）、呕吐、腹胀、停止排气排便；早期高位梗阻可不腹胀，低位梗阻呕吐晚而腹胀重","查体：腹膨隆、肠型与蠕动波、压痛与腹膜刺激征（提示绞窄）、疝嵌顿部位、术后切口疝、腹股沟肿块","立位腹平片：阶梯状气液平面、肠管扩张（小肠 >3 cm、结肠 >6 cm、盲肠 >9 cm），结肠梗阻可见「咖啡豆征」（乙状结肠扭转）","CT（增强）：诊断金标准，明确梗阻部位、移行带、有无闭袢（U 形或 C 形扩张肠管）、肠壁强化减弱/无强化、肠壁积气、肠系膜积液与漩涡征（肠扭转）","超声：肠管扩张、肠蠕动亢进/消失、肠壁增厚、腹腔积液","实验室：白细胞、CRP、乳酸（升高提示绞窄/缺血）、电解质与肾功能、血气（碱中毒/酸中毒）"],"workup":["腹部立位/卧位平片作为初筛，CT 为确诊与病因评估","增强 CT 用于鉴别粘连、肿瘤、疝、内外疝与肠扭转","血型与交叉配血（拟手术者）、凝血功能、肝肾功能","乳酸 ≥2 mmol/L、白细胞 ≥15×10^9/L、CT 见肠缺血征象需紧急手术评估","结肠梗阻者经肛门泛影葡胺灌肠可同时诊断与治疗（粘连性小肠梗阻口服泛影葡胺亦有治疗作用）","怀疑乙状结肠扭转：腹部平片后行内镜下减压，评估肠壁活性"],"grading":"按机制分为：机械性（粘连、疝、肿瘤、肠套叠、肠扭转）与动力性（麻痹性、假性梗阻）。按血管受累分：单纯性 vs 绞窄性（血运障碍）。按部位分：高位小肠（呕吐早、腹胀轻）与低位小肠/结肠（腹胀重）。绞窄性征象：持续性剧痛、腹膜刺激征、发热与心动过速、乳酸升高、CT 肠壁无强化或积气。"},"ddx":[{"name":"急性阑尾炎（gs_append）","point":"同属急腹症。阑尾炎以转移性右下腹痛与局部压痛为主，呕吐轻、腹胀不明显；肠梗阻以全腹绞痛、大量呕吐与腹胀、无法排气为主，平片/CT 见气液平面与移行带。"},{"name":"急性胆囊炎（gs_chole）","point":"同属急腹症。胆囊炎疼痛固定于右上腹、Murphy 征阳性，超声见胆囊壁增厚；肠梗阻疼痛呈阵发性全腹绞痛伴腹胀，X 线/CT 见肠管扩张。"},{"name":"麻痹性肠梗阻","point":"术后、腹膜炎、电解质紊乱引起，无阵发性绞痛、全腹均匀膨隆、肠鸣音消失，平片见小肠与结肠普遍扩张而无移行带，CT 无机械性阻塞点。"},{"name":"急性胰腺炎","point":"上腹持续剧痛放射背部、血清脂肪酶/淀粉酶 >3 倍正常上限，CT 见胰腺水肿坏死；肠梗阻合并胰腺炎多为并发症或病因（胆石性）。"},{"name":"输尿管结石","point":"绞痛始于腰部沿输尿管向下放射至腹股沟，血尿，CT 尿路成像见结石与肾盂积水，肠管无扩张。"}],"tx":{"drug":[{"name":"乳酸林格液/生理盐水（液体复苏）","dose":"按体重 30 mL/kg 起始，前 24 h 常需 4–6 L，监测 CVP/尿量（目标 0.5–1.0 mL/kg/h）、电解质与乳酸","note":"梗阻常伴第三间隙丢失与低钾低氯性碱中毒，需补充钾（尿量 >30 mL/h 后 20–40 mmol/L 静脉补钾，遵说明书）","renal":"心肾功能不全者减速，必要时 CRRT 支撑","hepatic":"遵说明书","interact":""},{"name":"头孢呋辛 + 甲硝唑（预防/治疗）","dose":"手术预防：头孢呋辛 1.5 g 静脉滴注（切皮前 30–60 min）+ 甲硝唑 0.5 g；治疗：头孢曲松 2 g qd + 甲硝唑 0.5 g q8h，疗程按感染控制 3–7 天","note":"单纯性梗阻无需常规抗生素；合并缺血/穿孔/腹膜炎需覆盖革兰阴性菌与厌氧菌；绞窄或脓毒症升级为哌拉西林他唑巴坦 4.5 g q8h 或美罗培南 1 g q8h","renal":"CrCl <20 mL/min 头孢呋辛减量，遵说明书","hepatic":"遵说明书","interact":"甲硝唑禁酒；头孢曲松禁与含钙溶液同通道"},{"name":"对乙酰氨基酚/吗啡（镇痛）","dose":"对乙酰氨基酚 0.5–1 g 静滴 q6h；必要时吗啡 5–10 mg 皮下/静注，按需滴定至疼痛评分下降","note":"镇痛不改变手术指征判断，但需在镇痛前后记录腹部体征与肠鸣音；阿片类可加重肠麻痹，尽量短时","renal":"吗啡活性代谢物蓄积，肾衰减少剂量","hepatic":"肝功能不全按说明书调整","interact":"阿片类与抗胆碱药合用加重肠麻痹"},{"name":"生长抑素/奥曲肽（保守治疗辅助）","dose":"奥曲肽 0.1 mg 皮下注射 q8h，疗程 3–5 天","note":"用于肿瘤性/假性小肠梗阻减少肠液分泌，疗效证据有限，不作常规","renal":"肌酐 >30% 升高者需减量","hepatic":"遵说明书","interact":"与胰岛素合用血糖波动"},{"name":"昂丹司琼（止吐）","dose":"4–8 mg 静脉注射 q8h，避免与胃肠减压同时过量使用","note":"止吐不替代胃肠减压","renal":"遵说明书","hepatic":"重度肝损害每日 ≤8 mg","interact":"与 QT 延长药物合用注意监测心电图"}],"nonDrug":["禁食胃肠减压（鼻胃管减压在显著腹胀与呕吐者有效，不推荐所有粘连性梗阻常规使用）","液体与电解质复苏、纠正低钾低氯性碱中毒；监测尿量、乳酸与腹围","粘连性小肠梗阻首选保守治疗 24–72 h：禁食、胃肠减压、静脉补液；口服泛影葡胺（水溶性造影剂）可诊断与缩短病程","绞窄征象（持续剧痛、腹膜刺激、乳酸升高、CT 肠壁缺血）、闭袢梗阻、嵌顿疝、腹腔内高压：急诊手术","手术方式：腹腔镜探查（粘连松解）或开腹；肿瘤性梗阻行切除吻合或造口；乙状结肠扭转行内镜下减压，失败或复发者择期切除","结肠梗阻合并肿瘤、无法一期切除者，可行支架置入或造口后择期手术","老年与恶病质者行营养支持，必要时全肠外营养"],"life":["术后早期活动、嚼口香糖促进肠功能恢复，警惕粘连复发","粘连性梗阻复发率 1 年 10%、5 年 30%–40%，肠梗阻再手术史者复发更高","避免进食不易消化、产气食物急性期；恢复排气排便后逐步流质饮食","长期随访评估肿瘤性梗阻原发灶"]},"prog":"单纯性粘连性梗阻保守治疗成功率 60%–70%；绞窄性梗阻死亡率可达 10%–20%，与延误手术及肠管坏死长度相关。结肠梗阻合并穿孔死亡率 >30%。术后注意肠麻痹与再梗阻。","refs":["世界急诊外科学会（WSES）粘连性小肠梗阻管理指南 2017","中华医学会外科学分会《肠梗阻诊治专家共识》2019","Bologna Guidelines for Diagnosis and Management of Adhesive Small Bowel Obstruction 2017"]}]},{"id":"tumor_gi","name":"消化道肿瘤","rank":2,"summary":"以分期决定治疗：先完成增强 CT/内镜病理与肿瘤标志物，按 TNM 与 MDT 讨论手术、放化疗、靶向与免疫的组合；重点筛查慢性乙肝与 HCV 背景下的肝癌。","compare":[{"diseaseId":"gs_crc","dx":"便血/大便习改变 + CEA 升高，结肠镜活检确诊腺癌，增强 CT 完成 T/N/M 分期，直肠癌加盆 MRI","key":"结肠镜 + CEA；直肠癌需盆 MRI 评估环周切缘（CRM）"},{"diseaseId":"gs_gastric","dx":"胃镜 + 活检确诊腺癌；进展期需超声内镜（EUS）评估 T 分期，增强 CT 评估淋巴结与远处转移；HER2/PD-L1/MSI 检测","key":"胃镜活检 + EUS/CT；HER2、MSI、PD-L1 与 Claudin18.2 决定系统治疗"},{"diseaseId":"gs_hcc","dx":"有肝硬化背景，动态增强 CT/MRI 呈「快进快出」动脉期强化+门脉/延迟期廓清，或 AFPL3 ≥400 ng/mL + 典型影像；不推荐常规穿刺","key":"不穿刺即诊断：影像三联征或 AFP ≥400 ng/mL；同时须 Child-Pugh 与肿瘤负荷分级"}],"diseases":[{"id":"gs_crc","name":"结直肠癌","aka":["Colorectal cancer","CRC"],"rank":1,"basic":{"define":"发生于结肠或直肠黏膜的腺癌（>90%），多由腺瘤性息肉经 APC/KRAS/TP53 等突变累积演变而来，遗传性（Lynch、FAP）占 5%–10%。","risk":["50 岁以上、男性","红肉/加工肉摄入多、膳食纤维少、肥胖、饮酒、吸烟","炎症性肠病（病程 >8–10 年）","结直肠癌家族史、Lynch 综合征、FAP","2 型糖尿病"],"epi":"我国结直肠癌新发病例约 51.7 万/年，居恶性肿瘤第 2 位，死亡约 24 万/年；40–74 岁均为筛查适宜人群，城市发病率高于农村。"},"patho":"腺瘤-癌序列：APC 失活→KRAS 激活→TP53 缺失，逐步由腺瘤进展为浸润癌；近端结肠多为 MSI-H/锯齿状途径，右侧结肠以隆起型为主，左侧及直肠以降壁生长、伴肠腔环形狭窄更易梗阻。癌浸润浆膜及脉管/神经后可发生淋巴与血行转移（肝、肺）。","dx":{"criteria":["临床表现：便血/黏液血便、排便习惯与粪便性状改变、里急后重，或不明原因缺铁性贫血、体重下降、腹部包块；右半结肠以贫血、乏力为主要表现","结肠镜 + 活检为确诊金标准，须完成全结肠检查（结肠镜或 CT 结肠成像），排除同时性多发癌（2%–5%）","病理：腺癌为主，需报告分化程度、脉管/淋巴管/神经侵犯、切缘；T1 癌需评估黏膜下浸润深度（>1000 μm 或低分化者淋巴结转移风险高）","TNM 分期 AJCC 第 8 版：T1 黏膜下层、T2 肌层、T3 穿透肌层至浆膜下、T4a 穿透脏层腹膜、T4b 侵犯邻近器官；N1 1–3 枚、N2 ≥4 枚淋巴结；M1a 单个器官单个病灶、M1b 单个器官多个、M1c 腹膜转移","分期检查：胸腹盆增强 CT 为常规；直肠癌须行盆腔高分辨 MRI 评估 CRM（阳性 ≤1 mm）与环周切缘、壁外血管侵犯（EMVI）；MRI 亦为直肠癌新辅助后再分期首选","分子检测：RAS/BRAF 突变、MSI/dMMR（所有患者应检测，Lynch 筛查），HER2 扩增用于后线","肿瘤标志物：CEA、CA19-9 基线值，用于疗效与复发监测"],"workup":["全结肠镜 + 多点活检（避免仅取坏死组织）","胸、腹、盆腔增强 CT；直肠癌必加盆腔 MRI","肝功能、肾功能；PET-CT 用于 CEA 升高但常规影像阴性或疑难腹膜转移","基因检测：MSI/dMMR、RAS、BRAF V600E（转移性）","直肠癌：肛门括约肌功能评估（低位者），必要时肛管直肠腔内超声","癌胚抗原（CEA）术前基线，术后每 3 个月监测 2 年"],"grading":"TNM 分期（第 8 版）临床分组：Ⅰ期 T1–2N0M0；ⅡA T3N0、ⅡB T4aN0、ⅡC T4bN0；Ⅲ期任何 T、N1–2；Ⅳ期任何 M1。病理分级：高、中、低分化及未分化（低分化/黏液腺癌、印戒细胞癌预后差）。直肠癌按 MRI 评估：CRM（≤1 mm 为环周切缘阳性）、EMVI、肿瘤下缘距肛缘距离（低位 <5 cm）。"},"ddx":[{"name":"胃癌（gs_gastric）","point":"同属消化道肿瘤。右半结肠癌以缺铁性贫血、右上腹包块为主，易与胃癌混淆；胃镜可确诊胃癌，结肠镜确诊结直肠癌，两者可同时存在（同时性多原发癌约 1%–2%）。"},{"name":"肝细胞癌（gs_hcc）","point":"同属消化道肿瘤。结直肠癌肝转移与原发性肝癌需鉴别：肝转移瘤多有 CRC 病史、CEA 升高、影像呈「靶环征」与明显强化环；HCC 有乙肝/肝硬化背景、AFP 升高、动态增强呈快进快出。需病理或影像鉴别。"},{"name":"痔/肛裂","point":"便血多为鲜红色、附于粪便表面或滴出，无排便习惯改变与贫血，直肠指诊 + 结肠镜排除；40 岁以上便血须警惕合并肿瘤。"},{"name":"炎症性肠病（溃疡性结肠炎/克罗恩病）","point":"慢性腹泻、黏液脓血便伴腹痛与体重下降，内镜见连续性黏膜炎症与隐窝结构改变，活检组织病理可鉴别；IBD 本身为 CRC 危险因素。"},{"name":"憩室炎","point":"左下腹痛伴发热，CT 见憩室周围炎与增厚肠壁，黏膜完整、无肿块性病变，内镜复查排除肿瘤（约 1% 结肠癌以憩室炎样表现）。"},{"name":"缺血性结肠炎","point":"老年人突发左下腹痛、便血，内镜见节段性黏膜坏死（「纵行溃疡」），数日自限，2–6 周后复查肠镜排除肿瘤。"}],"tx":{"drug":[{"name":"头孢呋辛钠 + 甲硝唑（围术期预防）","dose":"切皮前 30–60 min 头孢呋辛 1.5 g 静脉滴注 + 甲硝唑 0.5 g；手术 >4 h 追加 1 次","note":"结直肠手术需覆盖革兰阴性菌与厌氧菌；切开后超过 4 h 或出血 >1500 mL 追加，术后 24 h 内停用","renal":"CrCl <20 mL/min 减量，遵说明书","hepatic":"遵说明书","interact":"甲硝唑与乙醇禁用"},{"name":"伊诺肝素（VTE 预防/抗凝桥接）","dose":"预防：40 mg 皮下 qd（高危 40 mg bid），术前 12 h 停药、术后 8–12 h 恢复；口服抗凝需桥接者：术前 5 天停华法林，INR ≤1.5 时手术，术后 24 h 恢复","note":"肿瘤大手术 VTE 风险高，术后预防 4 周；椎管内麻醉需遵守停药间隔（治疗量 ≥24 h）","renal":"CrCl <30 mL/min 减至 40 mg qd；<15 或透析时改用普通肝素","hepatic":"严重肝病伴凝血障碍时慎用","interact":"与 NSAIDs、抗血小板药同用增加出血"},{"name":"5-氟尿嘧啶 + 亚叶酸钙（FOLFOX/FOLFIRI 基础）","dose":"mFOLFOX6：奥沙利铂 85 mg/m² 静滴 d1 + 亚叶酸钙 400 mg/m² + 5-FU 400 mg/m² 静推后 2400 mg/m² 持续泵入 46 h，q2w；辅助化疗 Ⅲ期 3–6 个月，高危Ⅱ期 3–6 个月","note":"剂量限值按肾功能计算；mFOLFOX6 用于辅助化疗与转移一线；不可切除肝转移行转化治疗","renal":"CrCl <30 减量或禁用 5-FU 严剂，遵说明书；奥沙利铂 CrCl <30 慎用","hepatic":"胆红素 >3 倍上限者减量，遵说明书","interact":"与伊立替康（UGT1A1 基因型）联用时注意中性粒细胞减少；氟尿嘧啶与华法林合用延长 INR"},{"name":"卡培他滨（口服氟尿嘧啶）","dose":"1250 mg/m² 口服 bid d1–14，q3w；联合奥沙利铂（CAPOX）时 1000 mg/m² bid d1–14","note":"口服替代静脉 5-FU，用于辅助与晚期；手足综合征与腹泻常见","renal":"CrCl 30–49 mL/min 降至 75%，CrCl <30 禁用","hepatic":"肝功能不全减量，遵说明书","interact":"与华法林合用显著升高 INR，需监测"},{"name":"贝伐珠单抗（抗 VEGF，mCRC 一线）","dose":"5 mg/kg 静脉滴注 q2w（联合 FOLFOX）或 7.5 mg/kg q3w","note":"需与化疗联用，不得用于术后辅助；围手术期需停药 ≥4–6 周（择期手术前 4–6 周、术后 ≥4 周）","renal":"无需调整，需监测蛋白尿，2 级以上停用","hepatic":"遵说明书","interact":"与抗凝药增加出血与伤口愈合不良风险"},{"name":"西妥昔单抗（抗 EGFR，RAS/NRAF 野生型）","dose":"首剂 400 mg/m² 静滴 2 h，之后 250 mg/m² q1w；或 500 mg/m² q2w","note":"仅用于 RAS/NRAF 野生型；须经配体 PCR 或测序确认；常见痤疮样皮疹与低镁","renal":"遵说明书","hepatic":"遵说明书","interact":"与奥沙利铂联用不推荐；与含钙输液勿同通道"},{"name":"帕博利珠单抗（MSI-H/dMMR 免疫治疗）","dose":"200 mg 静滴 q3w 或 400 mg q6w；用于 MSI-H/dMMR 转移性一线及不可切除局部晚期","note":"MSI-H/dMMR 患者免疫单药疗效显著；需检测 MSI 或 MMR 蛋白表达","renal":"轻度/中度肾损无需调整，重度遵说明书","hepatic":"轻中度无需调整，重度慎用","interact":"警惕免疫相关不良反应（肠炎、肝炎、甲减），糖皮质激素处理"}],"nonDrug":["手术：结肠癌行根治性切除 + 区域淋巴结清扫，保证切缘阴性与淋巴结 ≥12 枚；直肠癌行全直肠系膜切除（TME），距肛缘 <6 cm 低位者注意保肛评估","直肠癌新辅助：局部进展期（cT3–4 或 N+）行新辅助放化疗（盆腔 50.4 Gy/28 f + 卡培他滨同步），或短程放疗（25 Gy/5 f）+ 手术","可切除肝/肺转移：同期或异期切除，追求 R0；不可切除者转化治疗（双药/三药 + 靶向）后评估切除","MSI-H 局部进展期可选新辅助免疫治疗（dostarlimab/帕博利珠单抗），为保器官提供路径","辅助化疗：Ⅲ期与高危Ⅱ期术后，CAPOX 3 个月或 FOLFOX 3–6 个月（根据危险度选择），dMMR Ⅱ期不推荐氟尿嘧啶单药辅助","腹膜转移：细胞减灭术（CRS）+ 腹腔热灌注化疗（HIPEC）选择性应用","术后随访：前 3 年每 3–6 个月 CEA 与胸腹盆 CT，3–5 年每 6–12 个月，5 年后每年 1 次；术后 1 年复查肠镜"],"life":["膳食纤维 25–30 g/d、限制红肉/加工肉、增加果蔬与乳制品；保持 BMI 18.5–24 kg/m²","术后造口患者需专业造口护理，24 h 内造口缺血监测","戒烟限酒、规律运动（每周 ≥150 min 中等强度）","奥沙利铂化疗期间避免冷刺激（神经毒性）","及时处理手足综合征、腹泻，避免化疗中断"]},"prog":"Ⅰ期 5 年生存率 >90%，Ⅱ期约 75%–85%，Ⅲ期约 60%–70%，Ⅳ期约 15%–20%（可切除肝转移术后 5 年生存 30%–50%）。早期筛查显著降低死亡率；直肠癌需关注局部复发与肛门功能。","refs":["CSCO 结直肠癌诊疗指南 2023","中国国家卫健委《结直肠癌诊疗指南（2022 版）》","NCCN Colorectal Cancer Guidelines 2024"]},{"id":"gs_gastric","name":"胃癌","aka":["Gastric cancer","GC"],"rank":2,"basic":{"define":"来源于胃黏膜上皮的恶性肿瘤，以腺癌为主（>90%），按 Lauren 分型为肠型与弥漫型；早期多无症状，进展期可有上腹痛、消瘦与消化道出血。","risk":["幽门螺杆菌（H. pylori）感染（最重要，Ⅰ类致癌原）","高盐、腌制与烟熏食物，低果蔬摄入","吸烟、饮酒","萎缩性胃炎、肠上皮化生、恶性贫血","胃癌家族史、CDH1 突变（遗传性弥漫型）","EBV 感染"],"epi":"我国胃癌新发约 40 万/年，死亡约 30 万/年，居恶性肿瘤第 3–4 位；我国早期胃癌检出率约 20%，远低于日韩（>50%），5 年生存与分期强相关。"},"patho":"H. pylori 与炎症→慢性萎缩性胃炎→肠上皮化生→异型增生（ dysplasia）→肠型胃癌（Correa 级联）；弥漫型（印戒细胞癌）与 CDH1 突变有关，不经过该级联。肿瘤浸润胃壁浆膜后可经淋巴管转移至胃周（1–12 站）及腹主动脉旁淋巴结，血行转移以肝、肺、骨、卵巢（Krukenberg）为主，腹膜转移亦常见。","dx":{"criteria":["临床表现：上腹痛/饱胀、食欲减退、消瘦、乏力、呕血黑便、贫血；部分以转移灶（卵巢包块、锁骨上淋巴结 Virchow）首发","胃镜 + 多点活检是确诊金标准；早期胃癌按巴黎分型评估，可疑病灶行大致活检（每块 >4 处）","早期胃癌内镜下定义：病变局限于黏膜或黏膜下层，不论有无淋巴结转移","进展期 T 分期以超声内镜（EUS）最准确（T1–2 敏感度约 80%），增强 CT 评估淋巴结与转移（肝、肺、腹膜）","腹腔镜探查 + 腹腔脱落细胞学（CY1）用于 T3/4 或浆膜受累者，明确有无腹膜转移","实验室：血常规、肝肾功能、CEA、CA19-9、CA72-4；H. pylori 检测（尿素呼气试验/病理/血清抗体）","分子检测：HER2 免疫组化 + FISH（IHC 3+ 或 2+/FISH+ 为阳性，阳性率约 10%–15%）；MSI/dMMR；PD-L1 CPS；Claudin 18.2（IHC）；EBER（EBV 相关）"],"workup":["胃镜活检（必要时反复深取）作为首要检查","全腹增强 CT（含腹膜）、胸部 CT；必要时 PET-CT 排查远处转移","EUS 评估 T 分期与部分淋巴结","腹腔镜探查（+腹腔积液细胞学）用于可切除的进展期或怀疑腹膜转移","HER2、MSI/dMMR、PD-L1 CPS、Claudin 18.2 检测（晚期者必查）","营养评估（NRS2002）、贫血纠正、术前肺功能与心功能"],"grading":"TNM 分期（第 8 版）：T1a 黏膜、T1b 黏膜下、T2 侵及肌层、T3 侵及浆膜下、T4a 穿透浆膜、T4b 侵犯邻近结构；N1 1–2 枚、N2 3–6 枚、N3a 7–15 枚、N3b >15 枚；M1 远处转移（含腹膜）。早期胃癌内镜下分为 0-Ⅰ（隆起）、0-Ⅱ（平坦）、0-Ⅲ（凹陷）。组织学按 Lauren 分型（肠型/弥漫型/混合型），并报告 WHO 分级与是否为印戒细胞癌。"},"ddx":[{"name":"结直肠癌（gs_crc）","point":"同属消化道肿瘤。胃癌以上腹痛、呕血黑便、胃镜见胃黏膜肿块为主；右半结肠癌以贫血、右下腹包块、CEA 升高为主，两者可通过胃镜与结肠镜区分，需注意同时性多原发癌。"},{"name":"肝细胞癌（gs_hcc）","point":"同属消化道肿瘤。胃底贲门癌可伴肝转移，需与原发性肝癌鉴别：HCC 由肝硬化背景、AFP 升高、影像快进快出；胃癌肝转移为多发、病灶边缘强化、CEA/CA19-9 更高，并有胃部原发灶。"},{"name":"胃淋巴瘤（MALT/弥漫大 B 细胞）","point":"胃镜下多发浅表溃疡、黏膜皱襞增厚，活检免疫组化（CD20+、CD3+）确诊；对 H. pylori 根除治疗部分有效，或需化疗+放疗，无需胃切除（除非出血/穿孔）。"},{"name":"胃间质瘤（GIST）","point":"黏膜下隆起肿块、表面光滑、中央可有脐凹，EUS 见起源于固有肌层的低回声肿块，免疫组化 CD117/CD34/DOG1 阳性；除非侵犯黏膜，活检易致出血。"},{"name":"消化性溃疡/胃炎","point":"有周期性上腹痛，胃镜下良性溃疡边界清晰、黏膜完整，活检确认无恶性细胞；H. pylori 阳性者根除后复查。"},{"name":"胰腺癌","point":"上腹隐痛并向背部放射，体重下降明显，CA19-9 升高，CT 见胰管扩张与胰腺肿块；可侵犯胃窦，胃镜下见外压或浸润，需影像确认。"}],"tx":{"drug":[{"name":"头孢呋辛钠 + 甲硝唑（围术期预防）","dose":"切皮前 30–60 min 头孢呋辛 1.5 g 静滴 + 甲硝唑 0.5 g；手术 >3–4 h 追加","note":"胃手术为清洁-污染切口，需覆盖革兰阴性菌与厌氧菌，术后 24 h 停用","renal":"CrCl <20 mL/min 减量，遵说明书","hepatic":"遵说明书","interact":"甲硝唑与乙醇禁用"},{"name":"奥沙利铂 + 替吉奥（SOX）","dose":"奥沙利铂 130 mg/m² 静滴 d1，替吉奥 40–60 mg/m² 口服 bid d1–14，q3w（体表面积 <1.25 m² 用 40 mg bid；1.25–1.5 m² 为 50 mg；≥1.5 m² 为 60 mg）","note":"晚期胃癌一线常用；围手术期化疗可用 SOX 或 XELOX 各 3 周期","renal":"替吉奥 CrCl <30 禁用或减量，遵说明书；奥沙利铂 CrCl <30 慎用","hepatic":"肝功能异常者调整羟甲基转移酶相关代谢，遵说明书","interact":"替吉奥与华法林合用延长 INR；与索利夫定类抗病毒药禁忌"},{"name":"曲妥珠单抗（HER2 阳性一线）","dose":"负荷 8 mg/kg 静滴，之后 6 mg/kg q3w；联合顺铂+氟尿嘧啶（或卡培他滨+奥沙利铂）","note":"仅用于 HER2 阳性（IHC 3+ 或 IHC2+/FISH+）；需基线与定期评估 LVEF（心功能异常者停用）","renal":"无需调整","hepatic":"遵说明书","interact":"与蒽环类合用增加心脏毒性"},{"name":"帕博利珠单抗（PD-L1 CPS ≥5 或 MSI-H）","dose":"200 mg 静滴 q3w 或 400 mg q6w，联合化疗一线","note":"CPS ≥1 亦可在部分人群使用，按 PD-L1 CPS 分层；MSI-H/dMMR 无论 CPS 均可使用","renal":"轻中度无需调整","hepatic":"轻中度无需调整，重度遵说明书","interact":"免疫相关不良反应需激素处理；与化疗联合在 HER2 阳性者需谨慎选择人群"},{"name":"佐妥昔单抗（Claudin 18.2 阳性）","dose":"负荷 800 mg/m² 静滴，之后 600 mg/m² q3w，联合 mFOLFOX6","note":"用于 Claudin 18.2 阳性、HER2 阴性的晚期胃癌一线；注意恶心、呕吐与输液反应，遵说明书","renal":"遵说明书","hepatic":"遵说明书","interact":"致吐强，需联合 5-HT3 受体拮抗剂+NK1 拮抗剂"},{"name":"奥美拉唑 40 mg（PPI）","dose":"40 mg 静脉微泵 q12h（禁食期间）或 20 mg 口服 qd，用于胃切除术后应激性溃疡与反流","note":"术后常规预防性 PPIs 使用，短期应用以减少吻合口溃疡","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与氯吡格雷相互作用"}],"nonDrug":["早期胃癌（T1a 分化型、≤2 cm 无溃疡，或 T1a 未分化 ≤2 cm）可行内镜黏膜下剥离术（ESD），无脉管侵犯、切缘阴性者无需追加手术","根治性胃切除：远端胃癌行远侧胃大部切除+D2 淋巴结清扫（≥15 枚淋巴结），近端或全胃切除+全胃切除术后重建（Roux-en-Y）","围手术期化疗：进展期（cT3–4 或 N+）行 3 周期术前化疗+手术+3 周期术后化疗（FLOT4 方案或 SOX/XELOX）","晚期不可切除：HER2 阳性用曲妥珠单抗+化疗；HER2 阴性 CPS ≥5 用免疫+化疗；Claudin 18.2 阳性用佐妥昔单抗+化疗","腹膜转移：腹腔热灌注化疗（HIPEC）+肿瘤细胞减灭术，选择性使用","H. pylori 阳性者行根治性根除治疗（铋剂四联 14 天）","术后随访：2 年内每 3–6 个月，2–5 年每 6–12 个月复查 CT/胃镜/肿瘤标志物"],"life":["少食多餐（每日 5–6 餐）、细嚼慢咽，全胃切除者注意倾倒综合征（饭后心悸、出汗、腹泻）","补充维生素 B12（全胃切除者，肌注或口服）、铁剂与钙剂","戒烟草与酒精，减少腌制、高盐食物","术后体重监测，营养支持（肠内营养优先）","胃癌术后复发性贫血与骨质疏松的长期管理"]},"prog":"早期胃癌（T1N0）5 年生存率 90% 以上；进展期根治术后 5 年生存率 40%–60%；晚期胃癌中位生存 12–18 个月。筛查（胃镜）提高早诊率是改善整体预后的关键；HER2 与免疫治疗延长晚期生存。","refs":["CSCO 胃癌诊疗指南 2023","中国国家卫健委《胃癌诊疗指南（2022 版）》","日本胃癌学会 Gastric Cancer Treatment Guidelines 2021 (6th ed)"]},{"id":"gs_hcc","name":"肝细胞癌","aka":["Hepatocellular carcinoma","HCC","原发性肝癌"],"rank":3,"basic":{"define":"起源于肝细胞的恶性肿瘤，占原发性肝癌 75%–85%，90% 以上发生在慢性肝病与肝硬化基础上；可分为孤立型、多结节型与弥漫型。","risk":["慢性乙型肝炎（我国约 70%–80% 的肝癌与之相关）","丙型肝炎肝硬化","酒精性肝病、代谢相关脂肪性肝病（MASLD）","黄曲霉毒素 B1 暴露","肝硬化、肝癌家族史","糖尿病、肥胖"],"epi":"我国肝癌新发约 37 万/年，死亡约 32 万/年，居恶性肿瘤死亡第 3 位；男性多于女性（约 2.5:1）。我国自 2020 年起 HBsAg 阳性者每 6 个月超声+AFP 筛查，可显著提高早期诊断率。"},"patho":"慢性肝炎→肝纤维化→肝硬化→再生结节→异型增生结节→HCC（多结节发生）；HCC 为富血供肿瘤，动脉供血为主、门静脉供血少，故动脉期明显强化、门静脉期/延迟期快速廓清（「快进快出」）。门静脉癌栓是血管侵犯的主要形式，易发生肝内播散与肺骨转移。","dx":{"criteria":["高危人群：HBsAg 阳性、HCV 感染、任何原因肝硬化、有肝癌家族史者，每 6 个月行腹部超声 + AFP 筛查","确诊标准（非侵入性）：在肝硬化基础上，动态增强 CT 或 MRI 呈动脉期明显强化、门静脉期/延迟期廓清（washout），可见「包膜」征，直径 ≥1 cm 可诊断（LI-RADS 5）","直径 1–2 cm 者影像不典型时，可行超声造影、增强 MRI 肝细胞特异性对比剂（普美显，EOB-MRI）或穿刺活检；EOB-MRI 肝胆期低信号可帮助鉴别","不推荐对可根治患者常规穿刺活检（针道种植风险约 1%–3%）；对影像不典型、需病理或移植评估时穿刺","AFP ≥400 ng/mL + 典型影像可辅助诊断；AFP 正常不能排除（约 30%–40% HCC AFP 正常）","肝功能评估：Child-Pugh 分级（A/B/C）与 ALBI 评分；门静脉压力/食管静脉曲张评估；HBV DNA、HCV RNA 检测","肿瘤负荷评估：肿瘤数目、最大径、血管侵犯（门静脉/肝静脉癌栓）、肝外转移；巴塞罗那分期（BCLC）决定治疗"],"workup":["肝功能、凝血、血常规、HBV DNA/HCV RNA、AFP、PIVKA-II（DCP）","动态增强 MRI（或 CT）为基线影像，可加 EOB-MRI 提高小病灶诊断","上消化道内镜（筛查食管胃底静脉曲张）、吲哚菁绿（ICG）15 min 滞留率（手术评估）","肺部 CT（排除肺转移）、骨扫描（有骨痛时）","肝穿刺活检（影像不典型时）、必要时 EUS 引导","全身状况评估（ECOG 评分）、营养与感染（HBV 抗病毒必要性）"],"grading":"BCLC 0/A/B/C/D 分期：0 期 单个 <2 cm、肝功能 A、ECOG 0；A 期 单个或 ≤3 个且最大 ≤3 cm、肝功能 A–B；B 期 多发无血管侵犯、肝功能 A–B；C 期 血管侵犯或肝外转移、肝功能 A–B、ECOG 1–2；D 期 终末期肝功能 C、ECOG 3–4。Child-Pugh 分级：A 5–6 分、B 7–9 分、C 10–15 分。中国分期（CNLC）：Ⅰa 单个 ≤5 cm；Ⅰb 单个 >5 cm 或 2–3 个最大 ≤3 cm；Ⅱa 2–3 个最大 >3 cm；Ⅱb 4 个以上且最大 ≤3 cm；Ⅲa 血管侵犯；Ⅲb 肝外转移；Ⅳ 肝功能 C。"},"ddx":[{"name":"结直肠癌肝转移（gs_crc）","point":"同属消化道肿瘤。结直肠癌肝转移瘤通常为多发、边缘强化「靶环征」、内部坏死，CEA 升高，有 CRC 病史；HCC 有肝硬化背景、AFP 升高、动态增强 fast-in fast-out、无治疗性结肠病病史。"},{"name":"胃癌（gs_gastric）","point":"同属消化道肿瘤。胃癌肝转移与原发性 HCC 需鉴别：胃癌以胃部症状与 CA72-4/CA19-9 升高、肝内多发转移；HCC 有 HBV 史、门静脉癌栓、AFP 升高。若病变不明均可胃镜与影像联合诊断。"},{"name":"肝血管瘤","point":"最常见的良性肝肿瘤，影像呈「早出晚归」：动脉期结节状边缘强化、门脉期逐渐充填、延迟期等/高信号，无廓清；AFP 正常、无肝硬化。"},{"name":"肝内胆管癌（ICC）","point":"有 CA19-9 升高，影像示边缘不规则强化、进行性延迟强化、胆管扩张与肝门淋巴结转移；病理可鉴别。HCC 动脉期高强化、廓清为典型特征。"},{"name":"局灶性结节增生（FNH）","point":"青年女性多见，动脉期明显均匀强化、中央瘢痕延迟强化、无廓清，多见于无肝病者；EOB-MRI 肝胆期等/高信号可鉴别。"},{"name":"肝脓肿","point":"发热、白细胞升高、脓毒症表现，影像呈环形强化「双环征」，中央液化，抗感染后可缩小；部分胆系感染的脓肿可合并胆管结石。"}],"tx":{"drug":[{"name":"恩替卡韦/替诺福韦（HBV 抗病毒）","dose":"恩替卡韦 0.5 mg 口服 qd（肝硬化失代偿或拉米夫定耐药者 1 mg qd）；或富马酸替诺福韦酯（TDF）300 mg qd、富马酸丙酚替诺福韦（TAF）25 mg qd","note":"所有 HBsAg 阳性 HCC 患者应接受强效低耐药核苷（酸）类似物治疗，无论 HBV DNA 水平；在介入、手术与化疗期间须持续用药以预防病毒再激活","renal":"TDF 肾毒性较高，CrCl <50 者改用 TAF 或恩替卡韦减量，遵说明书","hepatic":"无需调整剂量，但需监测肝功能","interact":"TDF 与 NSAIDs/肾毒性药物合用时监测肾功能"},{"name":"仑伐替尼（一线靶向）","dose":"体重 ≥60 kg：12 mg 口服 qd；<60 kg：8 mg qd，餐前或餐后固定时间服用","note":"不可切除 HCC 一线；常见高血压、蛋白尿、腹泻、甲状腺功能减退","renal":"CrCl <30 减量或慎用","hepatic":"Child-Pugh B 减量，C 级不推荐","interact":"避免与强 CYP3A4 抑制剂/诱导剂合用"},{"name":"索拉非尼（一线靶向，备选）","dose":"400 mg 口服 bid，持续给药","note":"晚期 HCC 一线备选；手足皮肤反应与腹泻常见","renal":"无需调整","hepatic":"Child-Pugh B 减量，C 级禁用","interact":"与 CYP3A4 诱导剂合用降低疗效"},{"name":"阿替利珠单抗 + 贝伐珠单抗（免疫联合抗 VEGF，一线）","dose":"阿替利珠单抗 1200 mg 静滴 + 贝伐珠单抗 15 mg/kg 静滴 q3w","note":"不可切除 HCC 的一线首选，需评估出血风险；用药前 6 个月内需治疗/评估食管静脉曲张并给予 β 受体阻滞剂或套扎；Child-Pugh B 不推荐","renal":"轻中度无需调整","hepatic":"Child-Pugh A 使用，B 慎用，C 禁用","interact":"贝伐珠单抗与抗凝药/NSAIDs 合用增加出血，避免用抗血小板药（除阿司匹林 ≤100 mg）"},{"name":"度伐利尤单抗 + 替西木单抗（双免疫，一线）","dose":"单次给药方案：替西木单抗 300 mg + 度伐利尤单抗 1500 mg q4w 共 4 次，之后度伐利尤单抗 1500 mg q4w 单药","note":"适用于不可切除 HCC、肝功能良好、食管静脉曲张出血风险可控者；Child-Pugh B/C 不用","renal":"轻中度无需调整","hepatic":"肝功能 Child-Pugh A–B 慎用","interact":"免疫相关不良事件风险高，注意肝炎、皮疹、内分泌异常"},{"name":"雷莫西尤单抗（靶向二线）","dose":"8 mg/kg 静滴 q2w，联合紫杉醇（遵说明书）或单药","note":"索拉非尼/仑伐替尼治疗失败后的二线；主要不良反应高血压与出血","renal":"无需调整","hepatic":"Child-Pugh B 慎用","interact":"与抗凝药合用增加出血"},{"name":"对乙酰氨基酚/羟考酮（癌痛镇痛）","dose":"对乙酰氨基酚 0.5–1 g 口服 q6h（每日 ≤2 g，肝硬化者）；羟考酮缓释片 10 mg 口服 q12h 起始，按需滴定；神经性疼痛加用普瑞巴林 75 mg bid","note":"按 WHO 三阶梯原则；肝硬化者避免 NSAIDs（肾损害与出血）；阿片类需监测便秘与肝性脑病","renal":"肾衰者阿片类减量，避免哌替啶","hepatic":"肝硬化者减少对乙酰氨基酚剂量，禁用 NSAIDs","interact":"羟基酮与 CYP3A4 抑制剂合用需减量"}],"nonDrug":["早期（CNLC Ⅰa，单个 ≤5 cm、肝功能 Child-Pugh A、无门脉高压）：手术切除（解剖性/非解剖性）为首选，5 年生存率 50%–70%；或射频消融（单个 ≤3 cm 且位置适宜）","BCLC 0/A 且肝功能差、门静脉高压者：肝移植（米兰标准：单个 ≤5 cm 或 ≤3 个且最大 ≤3 cm、无血管侵犯与肝外转移）","中期（BCLC B）：经导管动脉化疗栓塞（TACE），TACE 失败者改用靶向/免疫或系统治疗","TACE 联合靶向/免疫（如 TACE + 仑伐替尼 + 免疫）用于不可切除但可转化的中晚期（EMERALD-1、LEAP-012 等）","晚期（BCLC C）：系统治疗（阿替利珠单抗+贝伐珠单抗、度伐利尤单抗+替西木单抗、仑伐替尼、索拉非尼）或联合介入；门静脉主干癌栓者评估放疗或介入","术后高危复发者（微血管侵犯、肿瘤 >5 cm、多结节）行辅助治疗（核苷类似物+靶向/免疫、TACE 辅助）","术后随访：2 年内每 2–3 个月 AFP + 增强影像，2–5 年每 3–6 个月，5 年后每 6–12 个月；每次复查均需筛查食管静脉曲张"],"life":["绝对戒酒，控制体重，避免肝毒性药物（中草药、雄激素等）","规律抗病毒治疗，HBV DNA 抑制至 <20 IU/mL","低盐饮食（每日钠 <2 g），限制蛋白质摄入仅在肝性脑病发作期","筛查肝癌复发与门静脉高压并发症（腹水、曲张静脉出血）","接种乙肝疫苗（家庭成员 HBsAg 阴性者）","心理支持与姑息治疗早期介入"]},"prog":"早期 HCC 手术切除后 5 年生存率 50%–70%，射频消融对小肝癌（≤3 cm）可达 60%–70%；移植符合米兰标准者 5 年生存 70%。中晚期中位生存 12–24 个月，系统治疗已延长至 19–24 个月。肝硬化程度与肿瘤分期是预后独立因素，HBsAg 转归与抗病毒依从性影响长期生存。","refs":["中国抗癌协会肝癌专业委员会《原发性肝癌诊疗指南（2022 版）》","CSCO 肝癌诊疗指南 2023","BCLC Strategy for Prognosis and Treatment of HCC 2022"]}]},{"id":"breast_thy","name":"乳腺与甲状腺","rank":3,"summary":"主线是「影像分级 → 病理 → 分子分型 → 分层药物治疗（内分泌/TSH 抑制）+ 长期随访」；术前须同时写清 BI-RADS/TI-RADS 与病理分型，剂量按指南并监测不良反应。","compare":[{"diseaseId":"gs_breast_ca","dx":"无痛性单发肿块、质硬、边界不清、活动度差；BI-RADS ≥4 类；空芯针穿刺确诊浸润性癌后按 ER/PR/HER2 分子分型","key":"BI-RADS 5 类 + 病理浸润性癌；分子分型决定内分泌/抗 HER2 治疗"},{"diseaseId":"gs_thyroid_nodule","dx":"颈部无痛性结节，超声 TI-RADS 4–5 类伴微钙化、纵横比 >1、边缘不规则；FNA 按 Bethesda 分级，Ⅴ/Ⅵ 类确诊 DTC","key":"TI-RADS 分级 + FNA Bethesda 结果；微钙化与纵横比 >1 是关键"},{"diseaseId":"gs_hyperpth","dx":"高血钙 + 低血磷 + PTH 升高，可伴骨痛、肾结石、乏力；排除肾衰与维生素 D 缺乏后继发因素，定位靠 99mTc-MIBI + 颈部超声","key":"高钙低磷伴 PTH 升高，需先排除继发性甲旁亢"}],"diseases":[{"id":"gs_breast_ca","name":"乳腺癌","aka":["Breast cancer","Breast carcinoma"],"rank":1,"basic":{"define":"起源于乳腺导管或小叶上皮的恶性肿瘤，按分子表型分为 Luminal A/B、HER2 阳性型与三阴性型，以内分泌、抗 HER2 靶向、化疗与手术/放疗综合治疗为主。","risk":["女性，45–55 岁与 60–65 岁为双峰","BRCA1/2、PALB2 突变，一级亲属家族史","初潮 <12 岁、绝经 >55 岁、未育、未哺乳","长期雌激素暴露（激素替代、肥胖、饮酒）；不典型增生或胸部放疗史"],"epi":"我国女性乳腺癌居恶性肿瘤发病首位，年新发约 35–42 万例，高峰 45–55 岁（较欧美提前约 10 年）；早期 5 年生存率 >90%。"},"patho":"多起源于终末导管小叶单位，导管原位癌突破基底膜后成为浸润性癌。ER/PR 阳性依赖雌激素信号增殖，为内分泌治疗基础；HER2 过表达激活 PI3K/AKT 与 MAPK 通路；TNBC 侵袭性强，与 BRCA1 相关。转移多经淋巴至腋窝淋巴结，血行至骨、肺、肝、脑。","dx":{"criteria":["临床表现：无痛、质硬、单发、边界不清、活动度差肿块；血性单孔溢液、乳头回缩、橘皮样征、腋窝肿块","BI-RADS：0 类追加影像；1 阴性；2 良性；3 可能良性（≤2%，随访 3–6 个月）；4 类可疑（4A 2%–10%、4B 10%–50%、4C 50%–95%）；5 类高度可疑（≥95%）；6 类已活检证实恶性","金标准：空芯针穿刺行组织学分级 + ER/PR + HER2（IHC 3+ 或 FISH 扩增为阳性）+ Ki-67","分子分型：Luminal A（HR+/HER2−，Ki-67 <20%）；Luminal B（HR+/HER2− 且 Ki-67 ≥20%，或 HER2+）；HER2 阳性；三阴性","分期：AJCC 第 8 版 TNM（超声、钼靶、胸腹 CT、骨扫描，必要时 PET-CT）","小叶原位癌（LCIS）为高危标志而非癌；导管原位癌（DCIS）属 0 期"],"workup":["乳腺超声 + 钼靶（40 岁以上首选，致密腺体加 MRI）","确诊后分期：胸腹 CT 与骨扫描（Ⅲ期或有症状）","BRCA1/2 检测：≤50 岁、三阴性、双侧/男性、家族史","术前查血常规、肝肾功能与 LVEF"],"grading":"组织学分级（Nottingham：腺管形成、核多形性、核分裂象各 1–3 分，3–5 分 Ⅰ级、6–7 分 Ⅱ级、8–9 分 Ⅲ级）；分期按 AJCC 第 8 版；复发风险按 OncoType DX 21 基因或 CSCO 病理模型分层。"},"ddx":[{"name":"甲状腺结节与分化型甲状腺癌（gs_thyroid_nodule）","point":"同属乳腺与甲状腺疾病。乳腺癌肿块在乳腺腺体、质硬；甲状腺结节在颈前、随吞咽上下移动，TI-RADS 定位明确。二者均可伴淋巴结肿大，需按部位与影像区分。"},{"name":"乳腺纤维腺瘤","point":"青年女性多见，肿块光滑、活动度极大、无压痛，BI-RADS 3 类；随访 3–6 个月，>3 cm 者手术。"},{"name":"乳腺增生症","point":"周期性胀痛与月经相关、双侧多发结节感，BI-RADS 2–3 类；无痛单发质硬肿块需活检。"},{"name":"乳腺叶状肿瘤","point":"生长迅速、分叶状肿块，超声见囊性裂隙；交界性/恶性需广泛切除（切缘 1–2 cm）。"},{"name":"非哺乳期乳腺炎（浆细胞性/肉芽肿性）","point":"乳晕周围炎性肿块，伴红肿、瘘管与溢液；误诊为癌行根治手术可致严重损害。"}],"tx":{"drug":[{"name":"他莫昔芬（绝经前内分泌）","dose":"20 mg 口服 qd × 5 年（高危延长至 10 年）；高危化学预防 5 年","note":"每 6–12 个月妇科检查，异常阴道出血即查超声","renal":"无需调整，遵说明书","interact":"CYP2D6 抑制剂（帕罗西汀）降低疗效；与华法林合用监测 INR"},{"name":"芳香化酶抑制剂（绝经后首选）","dose":"来曲唑 2.5 mg 口服 qd（或阿那曲唑 1 mg、依西美坦 25 mg qd），5 年，可延长至 7–10 年","note":"仅用于绝经后或 OFS 后；每年骨密度，T 值 <−2.0 者补钙与维生素 D","renal":"轻中度无需调整，重度遵说明书","interact":"禁止与含雌激素制剂合用"},{"name":"戈舍瑞林（卵巢功能抑制 OFS）","dose":"3.6 mg 皮下注射 q28d，或 10.8 mg 每 12 周一次；中高危绝经前 2–5 年","note":"联合 AI；潮热、骨质疏松，需补钙与骨密度监测；停药后生育功能可恢复","renal":"无需调整，遵说明书","interact":"与 QT 延长药物合用需心电监测"},{"name":"曲妥珠单抗（HER2 阳性）","dose":"负荷 4 mg/kg 后 2 mg/kg qw；或负荷 8 mg/kg 后 6 mg/kg q3w；总疗程 1 年","note":"每 3 个月监测 LVEF，下降 >10% 且 <50% 暂停；与蒽环类序贯","renal":"轻中度无需调整，遵说明书","interact":"与蒽环类合用增加心衰风险"},{"name":"帕妥珠单抗（HER2 阳性高危）","dose":"负荷 840 mg 后 420 mg q3w，联合曲妥珠单抗与紫杉类；辅助 1 年","note":"淋巴结阳性者新辅助；腹泻与心功能下降，监测 LVEF","renal":"无需调整，遵说明书","interact":"与蒽环类同用心脏毒性增加"},{"name":"T-DM1（残余病灶强化）","dose":"3.6 mg/kg 静滴 q3w，共 14 疗程","note":"血小板减少最常见，每疗程前查血常规；转氨酶升高与周围神经病变","renal":"轻中度无需调整","interact":"强 CYP3A4 抑制剂增加暴露"},{"name":"多西他赛 + 环磷酰胺（TC）","dose":"多西他赛 75 mg/m² + 环磷酰胺 600 mg/m² 静滴 q21d × 4 周期","note":"前 1 天起地塞米松 8 mg bid ×3 天；中性粒细胞减少可予 G-CSF 一级预防","renal":"CrCl <30 减量，遵说明书","interact":"避免与强 CYP3A4 抑制剂同用"},{"name":"表柔比星 + 环磷酰胺（EC）","dose":"表柔比星 90–100 mg/m² + 环磷酰胺 600 mg/m² q21d × 4 周期，序贯紫杉类","note":"终身累积剂量 ≤900 mg/m²；胆红素 >3 mg/dL 减量 50%；化疗前测 LVEF；三联止吐","renal":"CrCl <30 减量","interact":"与曲妥珠单抗序贯使用，不同步"},{"name":"头孢呋辛钠（围术期预防）","dose":"1.5 g 静滴，切皮前 30–60 min 单次；手术 >3 h 追加 1.5 g","note":"仅在假体/扩张器植入时使用，24 h 内停用；过敏改用克林霉素 900 mg","renal":"CrCl <30 延长至 q12h","interact":"与华法林合用延长凝血酶原时间"},{"name":"对乙酰氨基酚/羟考酮（术后与癌痛）","dose":"对乙酰氨基酚 1 g q6h（每日 ≤3 g）；羟考酮缓释片 10 mg q12h 起始按需滴定；神经病理痛加普瑞巴林 75 mg bid","note":"术后慢性胸壁/腋窝痛约 20%–50%，采用多模式镇痛；肝硬化者对乙酰氨基酚每日 ≤2 g","renal":"肾衰者阿片类减量","interact":"羟考酮与 CYP3A4 抑制剂合用减量"}],"nonDrug":["DCIS：保乳 + 全乳放疗（50 Gy/25 次）+ 内分泌 5 年，切缘 ≥2 mm","早期浸润癌：保乳（切缘 1–2 mm）+ 前哨淋巴结活检 + 全乳放疗；多中心或 BRCA 突变者全乳切除","新辅助：HER2+ 或 TNBC ≥T2 或淋巴结阳性者首选，未达 pCR 者 T-DM1 或卡培他滨强化","术后放疗：保乳者常规；全乳切除者肿瘤 >5 cm、淋巴结 ≥4 枚或切缘阳性者行区域放疗","转移/高风险者：全身治疗为主，骨转移加双膦酸盐与局部放疗"],"life":["控制体重（BMI 18.5–24），每周 ≥150 min 中等强度运动","戒酒或每日 ≤1 份；避免含雌激素保健品与激素替代","坚持内分泌治疗 5–10 年，不可自行停药","钙 1000–1200 mg/d + 维生素 D，每年骨密度，防淋巴水肿"]},"prog":"5 年生存率 Ⅰ期约 98%、Ⅱ期约 90%、Ⅲ期约 70%；Luminal A 型预后最好，三阴性复发高峰在术后 1–3 年。Ⅳ 期中位生存 2–4 年，HR+ 转移者用 CDK4/6 抑制剂可达约 5 年。淋巴结数目、分子亚型与治疗依从性是主要预后因素。","refs":["中国抗癌协会乳腺癌专业委员会《中国乳腺癌诊治指南与规范（2022 年版）》","CSCO 乳腺癌诊疗指南 2023"]},{"id":"gs_thyroid_nodule","name":"甲状腺结节与分化型甲状腺癌","aka":["Thyroid nodule","Differentiated thyroid carcinoma","DTC"],"rank":2,"basic":{"define":"甲状腺结节是甲状腺内局灶性病变，成人超声发现率约 20%–50%；经细针穿刺确诊的乳头状癌（PTC）或滤泡状癌（FTC）统称分化型甲状腺癌（DTC），占甲状腺癌 90% 以上。","risk":["女性，40–60 岁；儿童期头颈部放射线暴露为最强危险因素","甲状腺癌家族史、MEN2、Cowden 综合征（PTEN 突变）","碘摄入异常；结节快速增大、声嘶、吞咽困难"],"epi":"我国甲状腺癌为近 20 年增长最快的恶性肿瘤，现居女性第 3 位，年新发约 22 万例，以微小癌（≤1 cm）为主。DTC 10 年生存率 >90%，高危者显著下降。"},"patho":"乳头状癌（PTC）占 80%–85%，多由 BRAF V600E 或 RET/PTC 驱动，经淋巴道转移；滤泡状癌（FTC）多伴 RAS 突变，经血行至骨与肺；髓样癌（MTC）源于滤泡旁 C 细胞，可伴 MEN2；未分化癌罕见、侵袭性强。","dx":{"criteria":["临床表现：颈前无痛性肿块、随吞咽移动；声嘶、吞咽/呼吸困难或颈淋巴结肿大提示恶性","TI-RADS：TR3 可能良性（2%–5%）、TR4 可疑（5%–80%）、TR5 高度可疑（>80%）；C-TIRADS 4A 2%–10%、4B 10%–50%、4C 50%–90%、5 >90%","恶性特征：实性低回声、边缘不规则、纵横比 >1、微钙化、甲状腺外侵犯、淋巴结囊性变","FNA 指征：TI-RADS 4、5 类 ≥1 cm（≥5 mm 且高危）；Bethesda Ⅰ–Ⅵ 类，Ⅴ/Ⅵ 类即恶性","FNA Ⅳ 类需分子检测（BRAF/RAS/TERT）或诊断性腺叶切除；疑 MTC 查降钙素（>100 pg/mL 高度提示）与 CEA","术后按 AJCC 第 8 版分期（≤55 岁仅分 Ⅰ 与 Ⅱ 期）"],"workup":["颈部高分辨率超声（含淋巴结分区）为首选，报告须含 TI-RADS 分类与最大径","FNA 细胞学 + BRAF V600E 检测（Ⅳ–Ⅴ 类）；声嘶者术前喉镜检查","颈部增强 CT 评估气管侵犯（拟 131I 者避免碘造影）","全切术后查 Tg + TgAb；131I 前低碘饮食 2 周；高危者行全身碘扫描与 PET-CT"],"grading":"TI-RADS（TR1–TR5）决定 FNA 指征；Bethesda 细胞学分级。术后风险分层：低危（清甲后 Tg <1 ng/mL、无淋巴结侵犯）、中危（淋巴结转移、被膜外或血管侵犯、BRAF 突变）、高危（肉眼残留、远处转移、Tg 持续升高）。"},"ddx":[{"name":"乳腺癌（gs_breast_ca）","point":"同属乳腺与甲状腺疾病。甲状腺结节在颈前、随吞咽移动；乳腺癌在乳腺腺体，伴乳头溢液或皮肤改变。两者均伴淋巴结肿大时需区分转移来源（甲状腺来源常伴微钙化囊性变）。"},{"name":"桥本甲状腺炎","point":"弥漫性肿大、质韧、TPOAb/TgAb 升高，超声呈弥漫不均质低回声；合并结节时按结节本身行 FNA。"},{"name":"亚急性甲状腺炎","point":"颈前痛向耳后放射、发热、触痛，ESR 增快，TSH 降低而摄碘率降低（分离现象）；病程自限。"},{"name":"甲状腺未分化癌","point":"老年患者短期迅速增大的硬质肿块、声嘶与呼吸困难，中位生存 <6 个月；需急诊气道评估。"}],"tx":{"drug":[{"name":"左甲状腺素（TSH 抑制）","dose":"1.6–1.7 μg/kg/d 口服 qd，晨起空腹 30–60 min；低危 TSH 0.5–2.0 mU/L、中危 0.1–0.5、高危 <0.1 mU/L（6–12 个月后按风险再评估）；老年或心脏病患者 25–50 μg/d 起步","note":"TSH <0.1 长期抑制增加房颤与骨质疏松风险，每 2–3 个月查 TSH，并监测骨密度","renal":"无需调整","interact":"钙、铁、质子泵抑制剂影响吸收需间隔 4 h；与华法林合用 INR 升高"},{"name":"碘-131（清甲/清灶）","dose":"清甲 30–100 mCi（1.11–3.7 GBq）口服；清灶 100–200 mCi（3.7–7.4 GBq），单次 ≤200 mCi","note":"仅用于全切术后高危/中危；治疗前低碘 2 周、停左甲状腺素 4 周（TSH >30 mU/L）或用重组人 TSH；按放射性防护隔离","renal":"肾功能不全者排泄减慢，需调整剂量","interact":"含碘造影剂、胺碘酮造成碘阻断，须停药足够时间后治疗"},{"name":"仑伐替尼/索拉非尼（碘难治性 DTC）","dose":"仑伐替尼 24 mg 口服 qd；或索拉非尼 400 mg bid；持续至进展","note":"高血压、蛋白尿、手足反应与腹泻常见；中重度肝损伤减量，每 2–4 周监测血压与尿蛋白","renal":"CrCl <30 减量或慎用","interact":"避免与强 CYP3A4 抑制剂/诱导剂合用"},{"name":"凡德他尼/卡博替尼（进展期 MTC）","dose":"凡德他尼 300 mg 口服 qd；或卡博替尼 140 mg qd","note":"监测 QT 延长、腹泻与高血压；RET 阳性者可选塞普替尼（遵说明书）","renal":"CrCl <50 减量","interact":"强 CYP3A4 抑制剂增加暴露"},{"name":"碳酸钙 + 骨化三醇（术后低钙）","dose":"碳酸钙元素钙 600–1200 mg 口服 bid–tid；骨化三醇 0.25–1 μg 口服 qd，按血钙调整","note":"术后 24–48 h 查血钙；<2.0 mmol/L 且有症状者葡萄糖酸钙 10% 10–20 mL 稀释后缓慢静注","renal":"监测血磷与钙磷乘积","interact":"与左甲状腺素间隔 4 h"},{"name":"头孢呋辛钠（围术期预防）","dose":"1.5 g 静滴，切皮前 30–60 min 单次","note":"清洁手术单次即可；过敏改用克林霉素 900 mg","renal":"CrCl <30 延长至 q12h","interact":"与华法林合用延长凝血时间"},{"name":"对乙酰氨基酚（术后镇痛）","dose":"1 g 口服/静注 q6h（每日 ≤3 g，肝硬化者 ≤2 g）；必要时曲马多 50–100 mg q6h（每日 ≤400 mg）","note":"颈部血肿表现为呼吸困难与颈部肿胀，须及时切开减压","renal":"肾衰者曲马多减量","interact":"曲马多与 SSRI 合用增加 5-羟色胺综合征风险"}],"nonDrug":["良性结节（TI-RADS 2–3 类、FNA Ⅱ 类）：每 6–12 个月超声随访","DTC 手术：低危 ≤4 cm 且对侧正常可行腺叶切除；>4 cm、双侧病变或淋巴结转移者全切 + 中央区清扫","侧区清扫（Ⅱ–Ⅴ 区）仅用于临床淋巴结转移者","术后 TSH 抑制 + 高危者 131I 清甲；随访 Tg、TgAb 与颈部超声","复发/转移：再手术、131I、外照射；骨转移加双膦酸盐与局部放疗","低危微小癌可主动监测（每 6 个月），增大 ≥3 mm 或现淋巴结转移时手术"],"life":["左甲状腺素固定时间空腹服用，与钙/铁/咖啡间隔 4 h","131I 前低碘饮食；平时无需严格限碘","定期复查颈部超声与甲功，TSH 按风险分层","识别手足麻木与抽搐（低钙）；声嘶者行嗓音康复","遗传性 MTC 家系行 RET 筛查与预防性甲状腺切除"]},"prog":"DTC 10 年生存率 >90%，乳头状癌 Ⅰ 期接近 100%；老年、肿瘤 >4 cm、淋巴结 ≥5 枚、血管侵犯者复发风险升高，低危复发率 <5%、中高危 10%–30%。MTC 10 年生存 60%–75%，未分化癌中位生存 <6 个月。","refs":["中华医学会内分泌学分会《甲状腺结节和分化型甲状腺癌诊治指南（2023 版）》","中华医学会核医学分会《分化型甲状腺癌 131I 治疗指南（2021 版）》"]},{"id":"gs_hyperpth","name":"甲状旁腺功能亢进","aka":["Primary hyperparathyroidism","PHPT","甲旁亢"],"rank":3,"basic":{"define":"甲状旁腺分泌过多 PTH 导致高血钙、低血磷与骨吸收增加的临床综合征；以原发（腺瘤 >85%、增生约 10%、癌 <1%）最常见，继发（慢性肾病、维生素 D 缺乏）与三发亦需认识。","risk":["中老年女性（绝经后 50–60 岁高发），男女比约 1:2–3","颈部放射线暴露、MEN1/MEN2A、CASR 突变（FHH）","长期锂剂；慢性肾病或维生素 D 缺乏（继发性）"],"epi":"发病率约 0.2%–0.8%，50 岁以上女性可达 1%–2%；无症状型（仅高钙与 PTH 升高）占 60%–80%，约 30% 合并骨质疏松。继发性甲旁亢在透析患者中几乎普遍存在。"},"patho":"PTH 升高使骨破骨细胞活化、肾远端小管钙重吸收与磷排泄增加、1α-羟化酶激活使 1,25(OH)2D 升高，导致高钙低磷。长期高 PTH 致骨皮质变薄、骨小梁稀疏（纤维囊性骨炎）。原发者多为单腺瘤，MEN1 相关者常为多腺体增生。","dx":{"criteria":["生化三联征：高血钙（校正钙 = 实测钙 + 0.02 × [40 − 白蛋白 g/L]）、低血磷、PTH 升高（>65 pg/mL）","鉴别原发与继发：原发者 24 h 尿钙升高或正常、无肾功能不全；继发者高钙少见","家族性低尿钙性高钙血症（FHH）：钙/肌酐清除率比值 <0.01，CASR 突变，禁用手术","定位：颈部超声（70%–80%）+ 99mTc-MIBI 双时相显像（80%–90%）；再手术者行 4D-CT","靶器官：骨密度 DXA（桡骨远端 1/3 最敏感）、肾脏超声（结石、钙化）"],"workup":["空腹血钙 ×2 次、PTH、白蛋白、25-OH-D、血磷、肌酐、碱性磷酸酶","24 h 尿钙与尿肌酐排除 FHH；肾结石者行泌尿系超声","颈部超声 + 99mTc-MIBI 定位；MEN1 可疑者查垂体 MRI 与胃泌素","血钙 >14 mg/dL（3.5 mmol/L）或高钙危象需急诊补液降钙；术中 PTH 监测（切除后 10 min 下降 >50% 为成功）"],"grading":"按血钙：轻度（高于正常上限 <0.25 mmol/L）、中度、重度（>14 mg/dL 或高钙危象）。手术适应证：血钙高于上限 0.25 mmol/L；T 值 ≤−2.5；年龄 <50 岁；24 h 尿钙 >400 mg 或有结石；肌酐清除率 <60 mL/min。继发性甲旁亢按 KDOQI 靶目标（CKD 5D 期 PTH 2–9 倍正常上限）。"},"ddx":[{"name":"甲状腺结节与分化型甲状腺癌（gs_thyroid_nodule）","point":"同属乳腺与甲状腺疾病。甲旁亢腺瘤位于甲状腺背侧、伴高钙与 PTH 升高，MIBI 延迟相区摄取；甲状腺结节随吞咽移动、TI-RADS 分级明确，钙磷正常。"},{"name":"恶性肿瘤相关高钙血症","point":"肺鳞癌、乳腺癌骨转移与骨髓瘤可致高钙，但 PTH 被抑制、PTHrP 升高；骨髓瘤伴贫血与骨穿见浆细胞；噻嗪类与锂剂也可致高钙，停药后缓解。"},{"name":"维生素 D 缺乏/继发性甲旁亢","point":"25-OH-D 低、血钙正常或偏低，PTH 代偿性升高；补足维生素 D 后 PTH 回降。"},{"name":"家族性低尿钙性高钙血症（FHH）","point":"轻度高钙、PTH 正常或轻度升高、尿钙极低（钙/肌酐清除率 <0.01）；属良性，手术无效且有害。"}],"tx":{"drug":[{"name":"西那卡塞（拟钙剂）","dose":"起始 30 mg 口服 qd，每 2–4 周按 PTH 与血钙调整，最大 90 mg qd","note":"手术禁忌者及透析继发性甲旁亢；恶心与低钙常见，启动后 1 周查血钙","renal":"透析患者可用，非透析肾衰慎用","interact":"强 CYP2D6 抑制剂增加暴露；质子泵抑制剂降低疗效"},{"name":"骨化三醇（继发性甲旁亢/术后）","dose":"0.25 μg 口服 qd 起始，每 2–4 周调整至 0.5–1 μg qd；术后低钙可临时加至 1–2 μg qd","note":"监测血钙与钙磷乘积，PTH <2 倍正常上限时减量","renal":"监测血磷","interact":"噻嗪类增加高钙风险"},{"name":"唑来膦酸（高钙危象/骨痛/不宜手术者）","dose":"4 mg 加入 0.9% 氯化钠注射液 100 mL 静滴 >15 min，复发可 7 天后重复；不宜手术而骨密度低者阿仑膦酸钠 70 mg 口服 qw 代替","note":"降钙主药，须与补液联合；输注后 24–48 h 监测血钙与肾功能；阿仑膦酸钠牙科手术前评估颌骨坏死","renal":"CrCl <35 减量或避免；阿仑膦酸钠 CrCl <35 禁用","interact":"与氨基糖苷类合用增加低钙"},{"name":"0.9% 氯化钠注射液（高钙危象）","dose":"首 1–2 h 200–300 mL/h 静滴，随后 100–200 mL/h 维持；老年心功能不全者减量","note":"首选大量补液；有尿后加呋塞米 20–40 mg 静注促排钙（血容量不足时禁用）","renal":"监测尿量，必要时血液透析","interact":"停用噻嗪类利尿剂"},{"name":"头孢呋辛钠（围术期预防）","dose":"1.5 g 静滴，切皮前 30–60 min 单次","note":"清洁手术单次即可；过敏改用克林霉素 900 mg","renal":"CrCl <30 延长至 q12h","interact":"与华法林合用延长凝血酶原时间"},{"name":"对乙酰氨基酚/羟考酮（术后与骨痛）","dose":"对乙酰氨基酚 1 g q6h（每日 ≤3 g）；骨痛明显者羟考酮缓释片 10 mg q12h 起始按需滴定","note":"骨痛以手术降 PTH 与唑来膦酸为主，阿片类短期辅助","renal":"肾衰者阿片类减量","interact":"羟考酮与 CYP3A4 抑制剂合用减量"}],"nonDrug":["有手术指征者首选甲状旁腺切除：单腺瘤行局麻小切口或腔镜，术前定位","多腺体增生（MEN1）行次全切除或全切 + 前臂自体移植，术中 PTH 监测","术后 24–72 h 饥饿骨综合征高发，口服钙 + 骨化三醇；重度低钙静注葡萄糖酸钙","不宜手术者：钙剂 + 骨化三醇 + 阿仑膦酸钠，饮水 ≥2 L 防结石","继发性甲旁亢：限磷、磷结合剂、活性维生素 D、拟钙剂；无效者甲状旁腺全切 + 自体移植","术后 1 周、1 个月、6 个月复查血钙与 PTH，之后每年；骨密度每 1–2 年"],"life":["每日饮水 ≥2 L（防脱水与肾结石），避免过量钙补充","停用噻嗪类利尿剂与含钙抑酸药","骨质疏松者负重运动 + 防跌倒，纠正维生素 D 缺乏","识别手足麻木与肌痉挛（术后低钙）","MEN1 家系行甲状旁腺、垂体、胰腺筛查"]},"prog":"单腺瘤切除后 95% 以上高钙与 PTH 迅速纠正，术后 1 年腰椎骨密度提升约 5%–10%；5 年复发率 <5%，多腺体增生者 10%–20%。未手术的无症状患者 10 年内约 25% 出现手术指征。高钙危象未及时处置死亡率可达 20% 以上。","refs":["中华医学会内分泌学分会《原发性甲状旁腺功能亢进症诊疗指南（2018 年版）》","中华医学会外科学分会《原发性甲状旁腺功能亢进症外科治疗专家共识（2021 版）》"]}]},{"id":"hernia_perianal","name":"疝与肛肠","rank":4,"summary":"一类是「可复位、可修补」的腹壁缺损，核心在 EHS 分型与修补方式（嵌顿需急诊手术）；一类是肛周疾病，核心在齿状线上下与分度，以及阶梯治疗；术后感染与肛瘘复发是主要关注点。","compare":[{"diseaseId":"gs_inguinal","dx":"站立/咳嗽时腹股沟区可复性肿物，平卧可回纳，内环口有咳嗽冲击感；EHS 分型为 L/M/F + Ⅰ–Ⅲ 缺损大小，超声确认疝囊","key":"可复性肿物 + 内环缺损；嵌顿时不可回纳伴剧痛与肠梗阻"},{"diseaseId":"gs_hemorrhoid","dx":"无痛性鲜血便、痔核脱出，分内痔（Goligher Ⅰ–Ⅳ 度）与外痔（血栓性剧痛），肛门镜见齿状线上方黏膜隆起，需排除直肠癌","key":"无痛性鲜血便 + 齿状线上下黏膜隆起；暗红色血伴排便习惯改变需肠镜"},{"diseaseId":"gs_perianal_abscess","dx":"肛周剧痛、坐立不安，局部红肿、触痛与波动感伴发热，多为肛腺感染扩散；MRI/经肛超声定位深部脓肿","key":"搏动性剧痛伴发热与波动感；切开引流为主，伴肛瘘者需识别内口"}],"diseases":[{"id":"gs_inguinal","name":"腹股沟疝","aka":["Inguinal hernia","Groin hernia"],"rank":1,"basic":{"define":"腹股沟区（内环、Hesselbach 三角、股环）腹壁缺损致腹腔内容物突出形成的疝，为腹外疝最常见类型，需修补腹股沟后壁。","risk":["男性（男女比约 9:1），婴幼儿鞘状突未闭","老年腹壁筋膜退变、胶原代谢异常","慢性咳嗽、便秘、前列腺增生、重体力劳动、腹水","吸烟、肥胖、家族史"],"epi":"终身患病风险男性约 27%、女性约 3%，居腹外疝首位（70%–80%）；我国年疝修补约 100 万例，斜疝占约 85%。急诊嵌顿率约 5%–10%。"},"patho":"腹横筋膜、腹横肌与腹内斜肌薄弱，腹内压升高时内容物经内环、腹股沟管突出（斜疝），或经 Hesselbach 三角（直疝），或经股环（股疝）。疝囊颈部狭窄时内容物卡压（嵌顿），系膜血管受压则绞窄缺血，肠坏死与腹膜炎可迅速进展。","dx":{"criteria":["站立/咳嗽/用力时腹股沟区可复性肿块，平卧或手推可消失；股疝肿块位于腹股沟韧带下方卵圆窝处","查体：外环口插入指尖、咳嗽有冲击感；可触及缺损大小；腹股沟韧带下缘肿块提示股疝","EHS 分型：解剖 L（斜疝）/M（直疝）/F（股疝）；缺损 Ⅰ 级 <1.5 cm、Ⅱ 级 1.5–3 cm、Ⅲ 级 >3 cm，如「M2」","超声（站立 + Valsalva）确认疝囊与缺损，敏感性 80%–90%","腔隙性危险：肿物不能回纳、持续剧痛、恶心呕吐，伴腹膜炎体征与发热，需急诊 CT","儿童斜疝多源于鞘状突未闭，1 岁以内部分自愈"],"workup":["腹股沟区超声（站立位 + Valsalva），双侧检查","评估慢性咳嗽、前列腺增生（尿流率/PSA）、便秘与腹水等复发因素","嵌顿/绞窄者：腹部 CT 平扫、血常规与乳酸","术前心肺与抗凝药评估；儿童与鞘膜积液鉴别（透光试验）"],"grading":"EHS 分型（L/M/F + Ⅰ/Ⅱ/Ⅲ 级缺损）；临床分为可复性、难复性、嵌顿性与绞窄性；合并直疝或股疝按合并型描述。部分文献用 Nyhus 分型（ⅢA 直疝、ⅢC 股疝、Ⅳ 复发疝）。"},"ddx":[{"name":"痔疾（gs_hemorrhoid）","point":"同属疝与肛肠疾病。腹股沟疝肿物在腹股沟区、可复性；痔在肛门直肠，以便血与脱出为主，便秘是二者共同诱因。"},{"name":"肛周脓肿与肛瘘（gs_perianal_abscess）","point":"同属疝与肛肠疾病。肛周脓肿为肛周红肿热痛、波动感与发热，不随体位变化；腹股沟疝位于腹股沟管走行区，平卧可回纳。"},{"name":"阴囊鞘膜积液","point":"阴囊增大、透光试验阳性、摸不到睾丸，超声见液性暗区包绕睾丸；疝内含肠管可见肠蠕动与气体回声。"},{"name":"精索静脉曲张","point":"站立时「蚯蚓状」团块，Valsalva 加重、平卧消失，超声见精索静脉 >3 mm 并反流；无内环口缺损。"},{"name":"睾丸扭转","point":"突发阴囊剧痛、睾丸上抬（Prehn 征阴性），彩超示睾丸血流明显减少；属急诊，6 h 内探查固定。"}],"tx":{"drug":[{"name":"头孢呋辛钠（围术期预防）","dose":"1.5 g 静滴，切皮前 30–60 min 单次；嵌顿/肠切除或糖尿病者术后 24–48 h 维持 1.5 g q8h","note":"植入补片者建议使用；过敏改用克林霉素 900 mg","renal":"CrCl <30 延长至 q12h","interact":"与华法林合用延长凝血酶原时间"},{"name":"对乙酰氨基酚 + 布洛芬（多模式镇痛）","dose":"对乙酰氨基酚 1 g 口服 q6h（每日 ≤3 g，肝硬化者 ≤2 g）；布洛芬 400 mg 口服 q6–8h；必要时曲马多 50–100 mg","note":"腹腔镜后肩痛（残气）可加镇痛并鼓励活动；肾功差者慎用 NSAIDs","renal":"CrCl <30 避免 NSAIDs","interact":"布洛芬与抗凝药合用增加出血"},{"name":"依诺肝素（血栓预防）","dose":"40 mg 皮下注射 qd，术后 6–12 h 开始至活动自如；高危（肿瘤、既往 VTE）延长 4 周","note":"按 Caprini 评分决定；椎管内麻醉者遵穿刺/拔管间隔；严重肝病者监测抗 Xa","renal":"CrCl <30 减半或改普通肝素","interact":"与抗血小板/NSAIDs 合用增加出血"},{"name":"奥美拉唑（应激性溃疡预防）","dose":"40 mg 静脉/口服 qd，术后用至恢复进食；溃疡史或长期 NSAIDs 者使用","renal":"无需调整","interact":"降低氯吡格雷活性，改用泮托拉唑"}],"nonDrug":["成人有症状者均应修补；无症状男性小疝可观察，女性股疝应尽早手术","Lichtenstein 无张力修补（开放、平片补片）：单侧初发疝标准术式，复发率 <2%","腹腔镜 TAPP/TEP：适用于双侧疝、复发疝与股疝，学习曲线较长","儿童鞘状突未闭行高位结扎（不用补片），1 岁后手术","嵌顿疝：手法复位仅限嵌顿 <12 h、无腹膜炎者，成功后 2–4 周择期修补；疑绞窄者急诊手术，肠坏死行切除，一般不做一期补片","术前优化：戒烟 4 周、治疗便秘与前列腺增生、减重","术后随访 1 周、1 个月与 1 年，评估复发、慢性疼痛与补片感染"],"life":["戒烟（术前至少 4 周），控制体重，避免慢性咳嗽、便秘与提重物","术后 1–2 周避免 >5 kg 提重物与剧烈运动，鼓励早期下床","多饮水、增加纤维防便秘；前列腺增生者规范治疗","术后慢性疼痛（>3 个月）约 5%–10%，识别神经痛并转疼痛科","肝硬化腹水者先控制腹水再择期手术"]},"prog":"无张力修补术后复发率 <2%；嵌顿疝死亡率随肠坏死升高（绞窄者约 5%–10%）。术后慢性疼痛 5%–10%，多数 6 个月内缓解；补片感染 <1%，需取出补片。","refs":["中华医学会外科学分会疝与腹壁外科学组《成人腹股沟疝诊断和治疗指南（2018 年版）》","HerniaSurge Group, International Guidelines for Groin Hernia Management 2018"]},{"id":"gs_hemorrhoid","name":"痔疾","aka":["Hemorrhoids","痔疮"],"rank":2,"basic":{"define":"肛垫（肛管黏膜下血管丛与结缔组织）支持结构松弛、血管丛扩张与病理性肥大下移所致；位于齿状线以上为内痔、以下为外痔，兼有者为混合痔。","risk":["长期便秘、排便用力与久蹲（>5 min）","久坐久站、妊娠与分娩、肥胖","低纤维饮食、饮水少、辛辣与饮酒","年龄 45–65 岁高发，肛垫随年龄松弛"],"epi":"痔是肛肠科最常见疾病，成人患病率约 4%–13%，45–65 岁为高峰；我国肛肠疾病调查中痔占约 60%–70%。多数为 Ⅰ–Ⅱ 度，仅约 5%–10% 需手术。"},"patho":"肛垫是正常解剖结构（含动静脉吻合的血管垫），当 Treitz 肌与支持韧带变性、肛管静息压增高、排便用力使肛垫下移并充血扩张时形成内痔。齿状线以上黏膜对痛觉不敏感，内痔多无痛；齿状线以下受躯体神经支配，外痔血栓形成时疼痛剧烈。","dx":{"criteria":["Goligher 分度：Ⅰ 度便时出血无脱出；Ⅱ 度脱出便后自行回纳；Ⅲ 度需手托回纳；Ⅳ 度脱出不能回纳（可嵌顿、坏死）","临床表现：无痛性便后鲜血（滴血或喷射）、肛门坠胀与脱出；血栓性外痔为肛缘突发紫蓝色剧痛肿块","查体：视诊见肛缘皮赘/外痔，肛门镜见齿状线上方紫红色黏膜隆起（截石位 3、7、11 点），指检排除直肠肿瘤","警示信号：暗红色血便/黏液血便、排便习惯改变、体重下降、贫血、>50 岁首次便血者必须结肠镜","混合痔：内痔与外痔并存，严重者环状脱出（环形痔）"],"workup":["肛门视诊 + 指检 + 肛门镜（蹲位用力更易发现脱出）","血常规评估贫血；凝血功能与大便隐血",">50 岁、有家族史或报警症状者行结肠镜","拟手术或伴失禁者行肛管直肠测压与经肛超声；排除炎症性肠病"],"grading":"内痔 Goligher Ⅰ–Ⅳ 度（决定治疗阶梯）；外痔分结缔组织性（皮赘）、静脉曲张性、炎性和血栓性；混合痔分单发、多发与环形痔；急性嵌顿内痔为特殊急诊类型。"},"ddx":[{"name":"腹股沟疝（gs_inguinal）","point":"同属疝与肛肠疾病。腹股沟疝为腹股沟区可复性肿块、随腹压变化；痔在肛门直肠、以便血和脱出为主，但便秘是二者共同诱因。"},{"name":"肛周脓肿与肛瘘（gs_perianal_abscess）","point":"同属疝与肛肠疾病。肛周脓肿为红肿热痛的波动性肿块伴发热；血栓性外痔亦为剧痛肿块，但表面光滑呈紫蓝色、无全身发热。"},{"name":"结直肠癌/直肠息肉","point":"便血伴排便习惯改变、里急后重、大便变细与体重下降，指检可及质硬肿块；严禁把「痔」作为便血的唯一解释。"},{"name":"肛裂","point":"排便时刀割样剧痛持续数小时，便后少量鲜血，肛管后正中线可见线性溃疡；痔以便后无痛滴血为主。"}],"tx":{"drug":[{"name":"地奥司明（黄酮类）","dose":"急性期 0.9 g 口服 bid（前 4 日）+ 0.45 g bid（后 3 日）；缓解期 0.5 g bid","note":"改善静脉张力与淋巴回流，用于急性出血与脱出水肿；孕妇可用","renal":"重度肾功能不全慎用","interact":"无明确严重相互作用"},{"name":"复方角菜酸酯栓（局部）","dose":"1 枚（角菜酸酯 0.3 g）塞肛 bid，疗程 1–2 周","note":"保护直肠黏膜；便血持续 >2 周需内镜复查","renal":"无需调整","interact":"避免与其他栓剂同时使用"},{"name":"乳果糖（软化大便）","dose":"起始 15–30 mL 口服 qd，维持 1–2 次软便/日","note":"减少排便用力，防复发；肝硬化伴脑病者可降氨","renal":"监测电解质","interact":"与抗酸药间隔 2 h"},{"name":"复方利多卡因乳膏（局部镇痛）","dose":"适量涂于肛缘 qd–bid，每日不超过 6 g，使用 ≤1 周","note":"用于血栓性外痔与术后疼痛；重度肝功不全慎用，注意局麻药总量","renal":"无需调整","interact":"与其他局麻药联用需计算总量"},{"name":"对乙酰氨基酚 + 布洛芬（疼痛）","dose":"对乙酰氨基酚 1 g 口服 q6h（每日 ≤3 g，肝硬化者 ≤2 g）；布洛芬 300–600 mg 口服 q6–8h 饭后","note":"用于血栓性外痔与术后疼痛；两药联合优于单药","renal":"CrCl <30 避免布洛芬","interact":"布洛芬与抗凝药合用增加出血"},{"name":"头孢呋辛钠（围术期预防）","dose":"1.5 g 静滴，切皮前 30–60 min 单次；糖尿病或脓肿者 1.5 g q8h × 24–48 h","note":"必要时加甲硝唑 0.5 g 静滴；术后观察切口感染","renal":"CrCl <30 延长至 q12h","interact":"与华法林合用延长凝血酶原时间"}],"nonDrug":["Ⅰ–Ⅱ 度：纤维饮食 + 温水坐浴（40 ℃，10 min，每日 2–3 次），必要时地奥司明与栓剂","Ⅰ–Ⅱ 度保守无效：门诊胶圈套扎（RBL，每 4 周一次，最多 3 次）、硬化剂注射或红外线凝固","Ⅲ 度：PPH（痔上黏膜环切）或多普勒引导痔动脉结扎（THD）","Ⅳ 度或混合痔：外剥内扎术（Milligan-Morgan）或 PPH + 外痔切除；血栓性外痔 72 h 内可切开取栓","急性嵌顿内痔：消肿 24–48 h 后择期手术，一般不急诊环切","妊娠期痔以保守为主；保守 2–4 周无效或反复出血者转外科"],"life":["膳食纤维 25–30 g/d，饮水 ≥1.5–2 L，保持 1–2 次成形软便","每次排便 ≤5 min，不用力屏气","避免久坐久站与长时间蹲厕","温水坐浴每日 2–3 次；限酒与辛辣，规律运动，减重","便血持续 2 周以上必须复查肠镜"]},"prog":"Ⅰ–Ⅱ 度以保守与门诊治疗为主，80% 症状可缓解，5 年复发率 10%–30%；胶圈套扎复发率最高；手术早期复发 5%–10%，10 年复发率约 15%–20%。主要危害为慢性失血性贫血与急性血栓/嵌顿疼痛。","refs":["中华医学会外科学分会肛肠外科学组《痔临床诊治指南（2006，2016 专家共识更新）》","中华中医药学会肛肠分会《痔疮诊疗指南（2021 版）》"]},{"id":"gs_perianal_abscess","name":"肛周脓肿与肛瘘","aka":["Perianal abscess and fistula","Anorectal abscess / fistula-in-ano"],"rank":3,"basic":{"define":"肛腺感染（隐窝腺学说）经括约肌间隙扩散形成的急性化脓性感染为肛周脓肿；脓肿破溃或切开后形成的慢性肉芽性管道为肛瘘，二者是同一疾病的不同阶段。","risk":["肛窦/肛腺隐窝感染（最常见，占 80%–90%）","克罗恩病（肛瘘发生率高、复发率更高）","糖尿病、免疫抑制（HIV、化疗）、白血病","结核、性传播疾病；男性（男女比约 3–5:1），20–40 岁高发"],"epi":"肛周脓肿年发病率约 1.5–5/万，男性显著多于女性；切开引流后约 30%–50% 形成肛瘘，克罗恩病相关肛瘘复发率可达 50% 以上。"},"patho":"齿状线的肛窦是感染入口，沿肛腺向括约肌间隙扩散：向下至皮下形成肛周脓肿，穿过外括约肌至坐骨直肠间隙、向上至盆直肠或直肠后间隙。脓肿引流后形成内口在齿状线、外口在肛周皮肤的瘘管（Goodsall 定律：外口在横线前方多放射状直通内口，后方多弯向后正中）。克罗恩病者炎症为透壁性，瘘管更复杂。","dx":{"criteria":["肛周脓肿：肛周持续剧痛、坐立不安、排便加重；局部红肿、皮温升高、触痛与波动感，可伴发热（38–39 ℃）与白细胞升高","深部脓肿（坐骨直肠窝、盆直肠）体征可不明显，仅肛门坠胀、排尿困难与全身感染表现，需 MRI/经肛超声","肛瘘：反复流脓/黏液、可见外口、间歇疼痛与瘙痒；指检可及条索状瘘管，肛门镜可见内口","Park 分型：括约肌间型（约 70%）、经括约肌型（约 25%）、括约肌上型（约 5%）、括约肌外型（<1%）","复杂瘘/克罗恩病相关：MRI 增强（金标准）或经肛超声判断内口、支管与括约肌受累"],"workup":["血常规、CRP、血糖与凝血；发热者血培养","脓肿以临床诊断为主，深部脓肿或免疫抑制者行盆腔 MRI 或经肛超声","肛瘘行 MRI（内口定位与分型）+ 麻醉下检查 + 术中亚甲蓝注射","排除克罗恩病：结肠镜 + 小肠影像（MRE/CTE）","糖尿病患者查糖化血红蛋白；切开引流时探查并记录内口位置"],"grading":"肛周脓肿按位置分：皮下、括约肌间、坐骨直肠窝、盆直肠、直肠后间隙。肛瘘按 Park 分型，并分低位与高位（累及 >30% 外括约肌）；复杂瘘指高位、多发、伴脓肿或克罗恩病者。"},"ddx":[{"name":"腹股沟疝（gs_inguinal）","point":"腹股沟疝为可复性肿物、无急性感染表现；肛周脓肿为固定于肛周的红肿热痛肿块伴发热。嵌顿疝继发感染可类似，需结合起始部位与肠梗阻判断。"},{"name":"痔疾（gs_hemorrhoid）","point":"同属疝与肛肠疾病。血栓性外痔为肛缘紫蓝色剧痛肿块，但无发热、白细胞升高与波动感；炎性外痔坐浴后迅速缓解。"},{"name":"化脓性汗腺炎","point":"腋窝、腹股沟、会阴多发复发性结节、窦道与瘢痕；肛周脓肿多为单发、与肛腺相通。"},{"name":"肛管直肠癌（黏液腺癌）","point":"肛周硬结与流脓，但质硬、固定、伴里急后重与体重下降；反复不愈的肛瘘需活检排除癌变。"}],"tx":{"drug":[{"name":"头孢呋辛钠 + 甲硝唑（抗感染）","dose":"1.5 g 静滴 q8h + 甲硝唑 0.5 g 静滴 q8h；好转后改口服头孢呋辛 0.5 g bid + 甲硝唑 0.4 g bid，共 5–7 天（复杂病例 2–4 周）","note":"覆盖肠道革兰阴性菌与厌氧菌；单纯脓肿切开引流即可，抗生素用于蜂窝织炎、发热、糖尿病与免疫抑制者；严重肝病者甲硝唑减量","renal":"CrCl <30 头孢呋辛延长间隔，甲硝唑减量","interact":"甲硝唑与华法林合用显著增加 INR；服药期间禁酒"},{"name":"哌拉西林他唑巴坦（重症/复杂感染）","dose":"4.5 g 静滴 q6–8h，肾功能不全按方案调整，疗程 7–14 天","note":"用于脓毒症、糖尿病坏死性筋膜炎倾向与深部间隙脓肿","renal":"CrCl 20–40 为 4.5 g q8h，<20 为 q12h","interact":"与甲氨蝶呤合用增加毒性；与抗凝药叠加出血风险"},{"name":"英夫利西单抗（克罗恩病肛瘘）","dose":"5 mg/kg 静滴，第 0、2、6 周诱导，之后每 8 周维持","note":"先控制活动性脓肿并挂线引流；用药前筛查结核与肝炎","renal":"无需调整，遵说明书","interact":"免疫抑制叠加增加感染；避免与其他生物制剂联用"},{"name":"硫唑嘌呤（克罗恩病肛瘘维持）","dose":"1.5–2.5 mg/kg/d 口服，分 1–2 次；起效需 8–12 周","note":"维持缓解；每 2–4 周监测血常规与肝功能至稳定，转氨酶升高 >2 倍时减量/停药","renal":"慎用","interact":"别嘌醇增加骨髓抑制；与 ACEI 合用增加白细胞减少"},{"name":"对乙酰氨基酚 + 布洛芬（镇痛）","dose":"对乙酰氨基酚 1 g 口服 q6h（每日 ≤3 g，肝硬化者 ≤2 g）；布洛芬 400 mg q8h 饭后（≤3 天）；剧痛加曲马多 50–100 mg q6h","note":"切开后疼痛多在 24–48 h 缓解；避免长期 NSAIDs","renal":"肾衰者不用 NSAIDs","interact":"NSAIDs 与抗凝药合用增加出血"},{"name":"利福平/异烟肼（结核性肛瘘）","dose":"利福平 10 mg/kg/d（≤600 mg）+ 异烟肼 5 mg/kg/d（≤300 mg）口服 qd，疗程 6–9 个月","note":"病理见干酪样坏死或抗酸杆菌阳性者使用；需传染病科会诊；出现黄疸停药","renal":"异烟肼减量，遵说明书","interact":"利福平降低口服避孕药、华法林与他汀疗效"}],"nonDrug":["肛周脓肿：一期切开引流（放射状切口，充分引流，脓腔填纱条）是核心治疗，抗生素不能替代引流","低位且内口明确者一期切开（fistulotomy）；高位或复杂者挂线分期处理，避免切断括约肌致失禁","低位肛瘘（括约肌间型）：瘘管切开术为金标准，治愈率 >90%","高位/复杂肛瘘：LIFT（括约肌间瘘管结扎）、推移瓣、瘘管填塞等括约肌保留技术","克罗恩病复杂肛瘘：引流 + 挂线 + 生物制剂，避免过度手术","术后每日换药 1–2 次并坐浴；反复不愈者行 MRI 与活检","术后 1 周、1 个月、3 个月随访，评估复发与括约肌功能"],"life":["便后温水清洗或坐浴，保持肛周清洁干燥","规律排便防便秘，不自行挤压或刺破肛周肿块","糖尿病严格控糖，HbA1c <7%","克罗恩病规范随访与戒烟","术后 1–2 周避免剧烈运动、久坐与长时间骑行","持续发热、红肿扩大或剧痛提示引流不畅或坏死性感染，须及时复诊"]},"prog":"单纯肛周脓肿切开后痊愈率 >90%，但约 30%–50% 继发肛瘘；低位肛瘘瘘管切开治愈率 >90%，复发率 <5%，括约肌功能不全约 5%–10%。克罗恩病相关肛瘘需生物制剂与手术联合，5 年复发率可达 50%。","refs":["中华医学会外科学分会结直肠肛门外科学组《肛周脓肿和肛瘘诊治指南（2011/2020 专家共识）》","中华医学会消化病学分会《炎症性肠病诊断与治疗的共识意见（2023 年·北京）》"]}]},{"id":"hbp_spleen","name":"门静脉高压与脾脏","rank":5,"summary":"门静脉高压看「肝功能储备 + 出血风险」定分流/断流/TIPS；脾脏病变先判破裂与脾功能亢进，再定保脾还是切除；肝脓肿以影像确诊、穿刺引流为核心，避免只靠抗生素拖延。","compare":[{"diseaseId":"gs_portal_htn","dx":"乙肝/丙肝或酒精性肝硬化背景，血小板与白细胞下降，超声见门静脉增宽、脾大，胃镜见食管胃底静脉曲张（Form 分度、红色征），HVPG ≥10 mmHg 或临床显著门脉高压","key":"胃镜定曲张程度与红色征，Child-Pugh/MELD 定手术耐受力"},{"diseaseId":"gs_splenectomy","dx":"外伤史 + 左上腹痛/失血性休克，超声见脾周积血、FAST 阳性，增强 CT 见脾实质裂伤与活动性对比剂外溢，按 AAST 分级","key":"血流动力学是否稳定决定保脾观察、介入栓塞还是开腹脾切除"},{"diseaseId":"gs_liver_abscess","dx":"持续高热、右上腹痛、肝区叩击痛，白细胞与 CRP 升高，超声/增强 CT 见肝内低密度囊性灶伴环形强化，脓腔液化","key":"影像见液化脓腔 >3 cm 需穿刺置管，单纯抗生素不足"}],"diseases":[{"id":"gs_portal_htn","name":"门静脉高压症","aka":["Portal hypertension","PHT","肝硬化门脉高压"],"rank":1,"basic":{"define":"各种原因导致门静脉系统血流受阻、门静脉压力升高（HVPG >5 mmHg，临床显著门脉高压 ≥10 mmHg）的综合征，主要表现为脾大伴脾功能亢进、食管胃底静脉曲张破裂出血和腹水。","risk":["乙型/丙型肝炎肝硬化（我国最主要病因）","酒精性肝病、代谢相关脂肪性肝病","血吸虫病、门静脉血栓、布加综合征","特发性非肝硬化门脉高压"],"epi":"我国肝硬化患者中约 30%–40% 存在食管胃底静脉曲张，其中约 1/3 会发生破裂出血；首次出血病死率可达 15%–20%，未治疗者 1 年内再出血率约 60%。"},"patho":"肝窦阻力增加（结构性与功能性）使门静脉压力升高，侧支循环开放形成食管胃底静脉曲张、痔静脉与腹壁静脉曲张；内脏血管扩张致高动力循环、有效血容量不足，激活肾素-血管紧张素-醛固酮系统形成腹水与肝肾综合征；脾脏淤血肿大伴脾功能亢进。曲张静脉壁张力（Laplace 定律）决定破裂风险。","dx":{"criteria":["有慢性肝病证据：肝功能异常、血小板 <100×10^9/L、门静脉宽度 >13 mm、脾厚径增大","胃镜见食管胃底静脉曲张并按 LDRf 描述（位置、直径、红色征），红色征（+）与粗大曲张为出血高危","HVPG ≥10 mmHg 为临床显著门脉高压；HVPG ≥12 mmHg 为曲张静脉出血阈值；HVPG ≥16 mmHg 提示预后差","超声/增强 CT 或 MR 见门静脉增宽、脾大、侧支血管；肝弹性成像提示肝硬化","门静脉血栓须以增强 CT 门静脉期或 MR 门静脉成像确认"],"workup":["肝功能（白蛋白、胆红素、凝血酶原时间）并计算 Child-Pugh 分级与 MELD 评分","血常规监测三系减少（脾功能亢进），血小板/白细胞动态下降更有意义","胃镜为首要评估，急性出血 12–24 h 内完成；无曲张者按肝功能分层每 1–2 年复查","腹部增强 CT/MRV 进行门静脉解剖与侧支评估，为 TIPS、断流术或分流术规划","排除肝细胞癌（AFP + 增强影像），并评估心肾功能以决定 TIPS 可行性"],"grading":"胃镜 LDRf 分型：L 位置（Le 食管、Lg 胃）、D 直径（D0.3–D5 分级）、Rf 红色征。Child-Pugh A/B/C 级，MELD 评分用于终末期评估；门脉高压性胃病按 NIEC 分级。"},"ddx":[{"name":"脾功能亢进与脾外伤（同大类 gs_splenectomy）","point":"同属脾脏病变。门脉高压性脾大伴门静脉增宽、肝功能异常与胃镜曲张，脾亢为继发性；脾破裂有外伤史、腹腔积血与休克倾向，无肝硬化背景与静脉曲张。"},{"name":"消化性溃疡出血","point":"溃疡出血有黑便/呕血，但胃镜见溃疡灶而非曲张静脉，无脾大、血小板降低与门静脉增宽；肝硬化患者可两者并存，须胃镜确诊。"},{"name":"布加综合征/门静脉血栓","point":"布加综合征见肝静脉或下腔静脉狭窄、尾状叶增大、腹水顽固；门静脉血栓见门静脉充盈缺损与海绵样变，需增强 CT/MRV 鉴别并影响 TIPS 路径规划。"},{"name":"血液病性脾大（白血病、淋巴瘤、骨髓纤维化）","point":"无门静脉增宽与食管静脉曲张，外周血涂片、骨髓检查与淋巴结活检可鉴别，必要时脾活检（有出血风险须谨慎）。"}],"tx":{"drug":[{"name":"生长抑素或奥曲肽（急性曲张破裂出血）","dose":"奥曲肽首剂 50 μg 静脉推注后 50 μg/h 持续泵入，维持 3–5 天；或生长抑素 250 μg 静推后 250 μg/h 泵入","note":"一线血管活性药物，在疑诊即开始，与内镜治疗联合","renal":"遵说明书","hepatic":"严重肝功能不全者无需大幅减量，但需监测血糖","interact":"与胰岛素、口服降糖药合用时可能影响血糖"},{"name":"特利加压素","dose":"2 mg 静脉缓慢推注（>1 min），每 4 h 一次，连续 24–48 h 后改为 1 mg 每 4 h，总疗程 ≤5 天","note":"收缩内脏血管；冠心病、严重高血压、低钠血症慎用，需监测血钠","renal":"肾功能不全者按规定减量并密切监测","hepatic":"遵说明书","interact":"与硝酸酯类合用可致低血压；避免与血管收缩药叠加"},{"name":"普萘洛尔或卡维地洛（一级、二级预防）","dose":"普萘洛尔起始 10–20 mg po bid，逐步滴定至静息心率下降 25% 或 55–60 次/min；卡维地洛起始 6.25 mg qd，可增至 12.5 mg qd（先评估有无低血压与支气管痉挛）","note":"NSBB 用于无出血的曲张静脉中高危与再出血预防；不耐受者改用内镜套扎","renal":"遵说明书","hepatic":"重度肝功能不全首剂减量","interact":"与钙通道阻滞剂、地高辛合用可致心动过缓或低血压"},{"name":"头孢曲松（出血预防感染）","dose":"1 g 静脉注射 qd，疗程 7 天（或至出血停止后 5 天）","note":"肝硬化合并消化道出血常规预防性抗菌治疗，可降低再出血与病死率","renal":"肌酐清除率 <10 mL/min 时每日剂量不超过 2 g","hepatic":"通常无需调整","interact":"与含钙溶液同瓶输注禁忌；与口服避孕药合用降低避孕效力"},{"name":"特利加压素联合白蛋白（1 型肝肾综合征）","dose":"特利加压素 1 mg q4–6h 静注（逐步加量）+ 白蛋白 1 g/kg 首日，此后 20–40 g/日，疗程 7–14 天","note":"用于 HRS-AKI，需同时停用利尿剂、扩容量评估","renal":"肾功能已衰竭，需监测容量与血钠","hepatic":"遵说明书","interact":"与去甲肾上腺素等收缩血管药不宜叠加"}],"nonDrug":["内镜治疗：急性出血首选内镜下套扎（EVL）或硬化剂/组织胶注射（胃底静脉曲张），套扎后 2–4 周复查并完成程序化套扎直至消除","三腔二囊管：仅作为内镜与药物无效的临时桥接（放置 ≤24 h），注意误吸与食管黏膜坏死","TIPS：药物/内镜治疗后仍有难治性出血、顽固性腹水或 HRS 者；Child-Pugh ≤13 分或 MELD ≤18 更适合，肝性脑病高危者慎用","外科分流/断流术：肝功能 Child-Pugh A–B、无严重肝性脑病且 TIPS 条件受限者，常用贲门周围血管离断术 + 脾切除（预防性分流术后肝性脑病率高）","非选择性 β 受体阻滞剂 + 内镜套扎联合预防再出血；脾功能亢进明显且血小板 <3–5×10^9/L 或反复出血者可考虑脾切除（须评估门脉血栓风险）","肝移植：终末期肝病（MELD 高分）与反复难治性出血或 HRS 的根治方案","门静脉血栓：可考虑抗凝治疗，与肝硬化出血风险权衡后个体化决定"],"life":["戒酒、避免肝毒性药物，规范抗病毒治疗（HBV 抗病毒可降低门脉压力与肝癌风险）","轻度限盐（每日钠 <2 g）控制腹水，避免大量放腹水不补白蛋白","气道/腹部压力骤增（剧烈咳嗽、便秘、举重）可诱发破裂，须教育","急性出血后 6 周内再出血风险最高，出院前完成二级预防方案","每 6 个月 AFP + 超声筛查肝癌；定期复查胃镜与血常规"]},"prog":"首次曲张静脉破裂出血病死率约 15%–20%，未行二级预防者 1 年内再出血率约 60%。规范药物 + 内镜治疗后 1 年生存率明显改善，可在 60%–80%；TIPS 术后出血控制率 >90%，但肝性脑病风险约 20%–30%。","refs":["肝硬化门静脉高压症食管、胃底静脉曲张破裂出血诊治专家共识","Baveno VII 门脉高压共识：2022 年","中华医学会肝病学分会：肝硬化腹水及相关并发症诊疗指南（2017 年）","外科学（第 9 版）·门静脉高压症"]},{"id":"gs_splenectomy","name":"脾破裂与脾切除适应证","aka":["Splenic rupture","Splenectomy","OPSI"],"rank":2,"basic":{"define":"脾脏外伤性破裂（钝性、穿透性）或自发性/病理性破裂，以及各类需行脾切除术的原发病（外伤、脾亢、血液病、脾脏肿瘤或囊肿）。","risk":["交通事故、坠落等钝性腹部外伤（左侧下位肋骨骨折提示）","脾大（血液病、门脉高压、感染性疾病）者轻微外力即可破裂","高能量伤合并多发伤","脾切除后 OPSI 风险：年龄 <5 岁或 >65 岁、免疫抑制状态"],"epi":"脾是腹部钝性外伤中最易损伤的实质脏器，占腹部闭合性损伤的 25%–40%；儿童保脾成功率可达 80%以上，成人约 60%–70%。脾切除后暴发性感染（OPSI）发生率约 0.2%–0.5%，病死率可达 50%–70%。"},"patho":"脾实质血管丰富、被膜薄，受冲击后先出现被膜下血肿、再进展为真性破裂与腹腔内出血；迟发性破裂（伤后 48 h 至数周）与被膜下血肿继续扩大有关。脾为滤过血液的免疫器官，切除后对荚膜细菌（肺炎链球菌、脑膜炎奈瑟菌、流感嗜血杆菌）清除能力下降，是 OPSI 的基础。","dx":{"criteria":["左上腹或左季肋区外伤史，左上腹痛、Left Shoulder 牵涉痛（Kehr 征），可伴休克","FAST 见脾周或腹腔游离液（多为不凝血）提示腹腔内出血","增强 CT 为最可靠检查：脾实质裂伤、包膜下血肿、活动性对比剂外溢（blush）提示仍需介入或手术","AAST 分级：Ⅰ 包膜下血肿 <10%、Ⅱ 10%–50%、Ⅲ >50% 或实质裂伤 >3 cm、Ⅳ 累及脾血管、Ⅴ 脾粉碎或血管离断","自发性脾破裂常与感染性单核细胞增多症、疟疾、血液病、脾肿瘤相关，需追问病史"],"workup":["生命体征、血常规与动态血红蛋白，乳酸与血型交叉配血","FAST 为先一步评估；血流动力学稳定者行增强 CT 明确分级与出血灶","疑似迟发性破裂者复查超声/CT","脾切除前评估血小板、凝血功能与疫苗接种史","血源性感染筛查（EBV、CMV）与脾脏病理检查（切除后必做）"],"grading":"AAST 脾损伤分级 Ⅰ–Ⅴ；血流动力学状态分为稳定型与非稳定型，是治疗决策的核心。"},"ddx":[{"name":"门静脉高压症（同大类 gs_portal_htn）","point":"同属脾脏相关疾病。门脉高压性脾大为慢性代偿性，无外伤史与腹腔积血，伴门静脉增宽、静脉曲张与肝功能异常；脾破裂为急性出血，须 FAST/CT 判断。"},{"name":"肝破裂","point":"肝破裂多以右上腹为主、出血量大且常伴胆汁漏，CT 可定位肝实质损伤；脾破裂出血多位于左上腹与脾周。多发伤可同时存在。"},{"name":"左肾损伤","point":"血尿明显、CT 泌尿系期见肾实质裂伤；肾周血肿以肾周间隙为界，脾损伤则以脾门与左季肋区为主。"},{"name":"血液病/感染性脾大","point":"无外伤却有左上腹痛者应考虑自发性破裂，须查外周血涂片、EBV 抗体与骨髓；切勿因无外伤史而排除破裂。"}],"tx":{"drug":[{"name":"肺炎球菌多糖/结合疫苗（脾切除前）","dose":"术前至少 14 天接种 13 价或 20 价肺炎球菌结合疫苗（PCV），后续补种 23 价多糖疫苗（PPSV23）（间隔 ≥8 周）；紧急手术者可术后 2 周内补种","note":"脾切除前后接种是预防 OPSI 的核心措施","renal":"遵说明书","hepatic":"遵说明书","interact":"免疫抑制剂应延后接种"},{"name":"脑膜炎球菌疫苗与 b 型流感嗜血杆菌疫苗","dose":"四价脑膜炎球菌结合疫苗（含 ACWY）单剂，必要时 5 年后加强；MenB 疫苗按说明书 2 剂；Hib 疫苗按免疫规划/说明书补种","note":"所有脾切除患者均应接种，儿童与成人剂量按说明书","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"口服青霉素预防（高危人群）","dose":"儿童/成人每日青霉素 V 预防，剂量按体重遵说明书；对青霉素过敏者改用大环内酯类（遵说明书）","note":"可选：主要针对低龄儿童及免疫缺陷者，通常持续至 5 岁或术后 1–2 年","renal":"肾功能不全者根据肌酐清除率调整","hepatic":"遵说明书","interact":"与别嘌醇合用皮疹风险增加"},{"name":"氨甲环酸（创伤出血辅助）","dose":"1 g 静脉缓慢推注（10 min 内）后 1 g 持续静滴 8 h，伤后 3 h 内给药最佳","note":"用于创伤性出血辅助，不替代手术止血","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与抗凝药合用需权衡血栓风险"}],"nonDrug":["血流动力学稳定、AAST Ⅰ–Ⅲ 级：非手术治疗，监护 + 液体复苏，必要时血管介入栓塞（活动性外溢者）","血流动力学不稳定、Ⅳ–Ⅴ 级或活动性大出血：剖腹探查脾切除，伴多发伤者损伤控制性手术","儿童与非手术失败风险低者优先保脾，成人保脾须严格监护并有随时开腹准备","选择性脾切除适应证：门脉高压脾亢伴明显血细胞减少、免疫性血小板减少（ITP）、遗传性球形红细胞增多症、脾囊肿/肿瘤、脾脓肿、脾梗死","部分脾动脉栓塞：作为脾亢与脾外伤的微创替代，保留部分脾功能","血吸虫病性脾大、门脉高压者须同时处理门脉高压（分流/断流）","腹腔镜脾切除适用于择期非外伤病例（脾大或外伤破裂者慎用）","术前 2 周完成疫苗接种；术后补充叶酸与嗜血性病原教育"],"life":["脾切除后终身警惕 OPSI：发热 ≥38.5 ℃ 立即就医并提示「无脾」，必要时经验性抗菌","携带疫苗记录与医疗警示卡；每 5 年复种肺炎球菌与脑膜炎球菌疫苗","重视犬/猫抓咬伤（脾切除后暴发性败血症风险），及时清创与抗菌","旅行至疟疾、脑膜炎流行区前咨询预防方案","术后 4–6 周血小板可升高，>1000×10^9/L 时评估抗血小板治疗（遵医嘱）"]},"prog":"血流动力学稳定采用非手术治疗者成功率约 60%–90%（视分级而定），保脾者术后再出血约 5%。脾切除后短期并发症主要为出血与胰漏，远期 OPSI 发生率 0.2%–0.5%，规范接种后可显著下降。","refs":["WSES：成人脾外伤管理指南（2019 年）","英国血液学会：脾切除后疫苗接种与预防（2011 年）","外科学（第 9 版）·脾破裂与脾切除术","中国创伤救治联盟：创伤性脾损伤诊治专家共识"]},{"id":"gs_liver_abscess","name":"肝脓肿（细菌性与阿米巴性）","aka":["Hepatic abscess","Pyogenic liver abscess","Amoebic liver abscess"],"rank":3,"basic":{"define":"肝脏受细菌（化脓性）或溶组织内阿米巴感染形成的局限性化脓性病灶，以化脓性肝脓肿最常见，须同时处理感染灶来源与引流。","risk":["胆道疾病（结石、胆管炎）——我国最常见来源","糖尿病血糖控制不良","门静脉感染（阑尾炎、憩室炎）与腹腔感染","肝炎后肝硬化、免疫抑制、长期使用质子泵抑制剂","阿米巴流行区接触史、粪口传播"],"epi":"化脓性肝脓肿年发病率约 2–20/10 万，我国以胆道来源为主，糖尿病合并者达 30%–50%；阿米巴肝脓肿在流行区占肝脓肿的 10%–20%，多见于青年男性。"},"patho":"病原体经胆道（最常见）、门静脉、肝动脉或直接蔓延进入肝脏，局部形成炎症—坏死—液化过程；胆道梗阻合并感染时易形成多发性微小脓肿。阿米巴滋养体经门静脉侵入肝脏，形成「巧克力色」脓液。脓肿破裂可致膈下、胸腔或腹腔感染。","dx":{"criteria":["持续畏寒高热（>38.5 ℃）、右上腹痛、肝区叩击痛、食欲减退，可有黄疸","白细胞升高（>10×10^9/L）伴中性粒细胞比例升高、CRP 明显升高、降钙素原升高、白蛋白下降","超声见肝内低回声/混合回声囊性灶，壁厚不规则、内可有分隔或气体；增强 CT 见环形强化灶，液化脓腔 <3 cm 为小脓肿","血培养与脓液培养（兼厌氧菌）阳性可确定病原；阿米巴性可见血清学阳性与典型「巧克力色」脓液","胆道来源者需超声/CT/MRCP 评估胆管结石与梗阻"],"workup":["血常规、肝肾功能、CRP、PCT、血培养（2 套，含厌氧瓶）","超声为初筛；增强 CT 或 MRI 判断脓肿数目、大小、位置与并发症（膈下、胸腔、腹腔）","阿米巴血清学（间接血凝/ELISA）与粪便查溶组织内阿米巴滋养体/包囊","疑似胆道来源者行 MRCP 或 ERCP；疑胆管下端梗阻者评估引流方案","穿刺/置管引流获取脓液做培养、涂片与药敏，必要时查阿米巴滋养体"],"grading":"按病原分：化脓性（单发或多发）、阿米巴性；按解剖分单发与多发、是否合并胆道梗阻；按并发症（破裂、脓毒症）评估。"},"ddx":[{"name":"脾破裂与脾切除（同大类 gs_splenectomy）","point":"同属腹部实质脏器感染/出血性病变。肝脓肿以高热为主、左上腹无明显外伤，影像见肝内脓肿；脾破裂为外伤后出血，FAST/CT 见脾周积血。"},{"name":"肝细胞癌坏死液化","point":"肝癌多有 AFP 升高、肝硬化背景与快进快出增强模式；脓肿壁厚且呈环形强化伴脓肿壁内积气与周围水肿，肿瘤坏死液化少见明显发热与白细胞升高。"},{"name":"胆管癌/胆囊癌合并感染","point":"胆管癌以梗阻性黄疸与胆管扩张为主，伴胆管截断或壁增厚；脓肿以全身感染为主、发热更突出，须增强影像与肿瘤标志物（CA19-9）鉴别。"},{"name":"肝囊肿合并感染","point":"肝囊肿壁菲薄、无症状，感染后出现发热与囊内液体浑浊；若原有囊肿病史且影像壁薄则考虑囊肿感染。"},{"name":"右膈下脓肿/隔下游离气体","point":"膈下脓肿多位于膈与肝之间，常有腹部术后或穿孔病史，影像可见膈下积液，位置与肝内脓肿不同。"}],"tx":{"drug":[{"name":"哌拉西林-他唑巴坦（经验性抗菌）","dose":"4.5 g 静脉滴注 q8h（严重感染按说明书调整）","note":"覆盖肠杆菌科与厌氧菌，胆道来源首选之一，须结合药敏调整","renal":"肌酐清除率 <40 mL/min 按说明书减量或延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度；避免与氨基糖苷类同瓶输注"},{"name":"头孢曲松 + 甲硝唑","dose":"头孢曲松 2 g 静脉滴注 qd；甲硝唑 0.5 g 静脉滴注 q8h","note":"覆盖胆道常见菌与厌氧菌，适用于不能耐受哌拉西林者","renal":"甲硝唑肾功能不全者延长间隔；头孢曲松一般无需调整","hepatic":"严重肝功能不全甲硝唑减量","interact":"甲硝唑与乙醇禁用；头孢曲松禁与含钙溶液同瓶"},{"name":"甲硝唑（阿米巴性肝脓肿）","dose":"0.5–0.75 g 口服或静脉 q8h，疗程 7–10 天","note":"阿米巴肝脓肿首选；可序贯替硝唑（遵说明书）","renal":"严重肾功能不全减量","hepatic":"肝功能严重受损者减量","interact":"用药期间及停药 72 h 内禁酒；与华法林合用增强抗凝"},{"name":"甲硝唑后序贯双碘喹啉/二氯尼特（清除肠内包囊）","dose":"按说明书，通常甲硝唑疗程后接肠内杀灭药物，剂量遵说明书","note":"阿米巴肝脓肿治疗后应根除肠道带虫状态，防止再感染","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"肠外营养/白蛋白支持","dose":"按需补充，白蛋白 20% 10–20 g/日或按体重 1 g/kg 使用（遵说明书）","note":"长期高热与摄入不足者注意营养支持","renal":"肾功能不全者避免大剂量白蛋白","hepatic":"肝功能不全需监测容量","interact":"遵说明书"}],"nonDrug":["穿刺引流指征：单发脓肿直径 ≥3–5 cm、液化明显、有脓毒症或保守治疗 48–72 h 无改善者，超声/CT 引导下穿刺或置管引流（首选）","小脓肿（<3 cm）且一般情况好可单纯抗生素治疗，但须密切复查影像","多发性脓肿或多房分隔者以抗菌 + 选择性大脓腔引流为主；微创/开腹引流用于破裂或引流失败","胆道梗阻合并胆管炎者行 ERCP 或 PTCD 解除梗阻，同期处理结石","脓毒症/脓肿破裂致弥漫性腹膜炎者外科引流（腹腔冲洗）","阿米巴性：大脓肿（>10 cm）或有破裂、左叶脓肿或治疗 5 天后无改善时行穿刺引流","糖尿病患者需同步控制血糖（胰岛素强化）"],"life":["疗程通常 4–6 周，须复查影像直至脓腔消失或明显缩小、症状消退后停药","阿米巴患者需加强粪便管理、饮水和食品卫生，家庭成员筛查","控制血糖、处理胆道结石/胆管狭窄等病因以防复发","出现高热不退、右上腹剧痛、呼吸困难须警惕脓肿破裂或膈下感染"]},"prog":"规范引流 + 抗菌治疗病死率降至 5%–10%，但伴脓毒症、多发性脓肿或糖尿病患者病死率可达 15%–30%。阿米巴性肝脓肿经甲硝唑 + 引流治疗后病死率约 1%–3%。","refs":["中国肝脓肿诊治专家共识","化脓性肝脓肿诊治专家共识（外科）","World Society for Emergency Surgery：肝脓肿管理指南（2019 年）","外科学（第 9 版）·肝脓肿"]}]},{"id":"biliary_other","name":"胆道与腹壁其他","rank":6,"summary":"胆道疾病按「有无梗阻、有无感染」分层：结石/息肉评估手术指征与恶变风险；AOSC 是急诊引流优先，ERCP/PTCD 在 24 h 内完成；胆道肿瘤重在早诊与根治性切除。腹壁疝须警惕嵌顿绞窄，外科感染须尽早切开引流而非单纯抗菌。","compare":[{"diseaseId":"gs_cholelithiasis","dx":"右上腹绞痛/胆绞痛史，超声见胆囊内强回声伴后方声影、可移动；息肉为附壁不强声影、不随体位移动，>10 mm 或快速增大者需手术","key":"超声区分结石与息肉，评估胆囊壁、胆总管扩张与恶变风险"},{"diseaseId":"gs_aosc","dx":"Charcot 三联征进展至 Reynolds 五联征（+休克、意识障碍），黄疸、右上腹痛、寒战高热，白细胞与胆红素显著升高、胆总管扩张、肝内外胆管扩张伴积脓","key":"Reynolds 五联征 + 胆道梗阻影像 = 急诊胆道减压指征"},{"diseaseId":"gs_cholangioca","dx":"进行性无痛性梗阻性黄疸，CA19-9 升高，MRCP/增强 CT 见胆管狭窄或占位、胆管扩张；胆囊癌多伴胆囊壁增厚/息肉样占位","key":"无痛性黄疸 + 胆管截断/壁增厚，需肿瘤标志物与病理确诊"},{"diseaseId":"gs_ventral_hernia","dx":"腹股沟区/原切口处可复性包块，咳嗽冲击感；嵌顿时包块不能回纳、局部剧痛伴肠梗阻表现，超声见疝囊内容物","key":"不可回纳 + 局部疼痛 + 肠梗阻 = 嵌顿须急诊手术"},{"diseaseId":"gs_surgical_infection","dx":"局部红、肿、热、痛或波动感，痈可见多脓头，丹毒为边界清楚的红斑，脓毒症按 SOFA ≥2 分判定","key":"皮下捻发音、皮肤坏死与剧痛提示产气菌感染（气性坏疽），需急诊清创而非单纯抗生素"}],"diseases":[{"id":"gs_cholelithiasis","name":"胆囊结石与胆囊息肉","aka":["Cholelithiasis","Gallbladder polyp","胆囊息肉样病变"],"rank":1,"basic":{"define":"胆囊结石为胆汁成分（胆固醇、胆色素、混合性）析出结晶形成结石；胆囊息肉为胆囊黏膜向腔内突出的隆起性病变，包括胆固醇性息肉、腺瘤性息肉与炎性息肉。","risk":["女性、40 岁以上、肥胖、多次妊娠（4F 特征）","高脂低纤维饮食、快速减重、长期禁食或全肠外营养","2 型糖尿病与代谢综合征","胆囊息肉：>50 岁、合并结石、单发、基底宽、无蒂、生长快（腺瘤性恶变风险高）"],"epi":"我国成人胆囊结石患病率约 6%–10%，女性高于男性；胆囊息肉检出率随超声普及升至 4%–7%，其中胆固醇性息肉占 60%–90%，腺瘤性息肉占约 5%–10%。"},"patho":"胆固醇过饱和胆汁 + 胆囊运动减弱 + 成核因子促使胆固醇结晶聚集；胆色素结石与胆道感染、溶血、胆道解剖异常有关。息肉多由胆固醇沉积于黏膜形成，腺瘤性息肉可经腺瘤—癌序列演变为胆囊癌。结石嵌顿于胆囊颈部或胆囊管可致急性胆囊炎、胆管梗阻、胰腺炎。","dx":{"criteria":["多数无症状（约 60%–80%），发作性右上腹隐痛或胆绞痛，饱食油腻后诱发，可放射至右肩背","超声为首选：胆囊内强回声团伴后方声影且随体位移动为结石；附壁回声不强声影者为息肉","胆囊息肉非胆固醇性/腺瘤性高危征象：单发、直径 >10 mm、基底宽、无蒂、血流丰富、合并结石、生长速度 >2 mm/年","有胆绞痛或胆囊炎表现者查白细胞、CRP、肝功能与胰酶以评估并发症","疑似胆管结石或胆管扩张者行 MRCP 或 EUS"],"workup":["腹部超声（空腹）评估结石数目、大小、胆囊壁厚度与胆囊收缩功能","肝功能与胆红素、碱性磷酸酶、GGT；异常提示胆管梗阻","血淀粉酶/脂肪酶排除并发急性胰腺炎","超声造影或增强 CT/MRI 评估可疑息肉的血供与基底","疑似恶变者查 CA19-9、CEA 并行增强 MRI/CT"],"grading":"胆囊结石按成分（胆固醇、胆色素、混合性）；息肉按病理（胆固醇性、炎性、腺瘤性、腺肌瘤性）。胆囊壁增厚 ≥4 mm 或伴结石者属高危。"},"ddx":[{"name":"胆囊癌与胆管癌（同大类 gs_cholangioca）","point":"同属胆道系统。胆囊息肉 >10 mm、单发宽基底或快速增大需警惕胆囊癌，增强 MRI 见息肉强化、胆囊壁连续性中断；胆管癌以胆管狭窄与黄疸为主、CA19-9 常明显升高。"},{"name":"急性梗阻性化脓性胆管炎（gs_aosc）","point":"胆管结石嵌顿可致 AOSC，表现为 Charcot 三联征与 Reynolds 五联征，需急诊引流；单纯胆囊结石一般无黄疸与休克。"},{"name":"急性胆囊炎（gs_chole）","point":"急性胆囊炎为结石嵌顿后炎症，Murphy 征阳性、胆囊壁增厚、胆囊周围渗出，属急性并发症，非单纯结石。"},{"name":"胃十二指肠疾病（消化性溃疡、胃炎）","point":"上腹痛与饱食相关，但胃镜见溃疡/炎症，超声胆囊无结石；注意两者可并存。"},{"name":"胆囊腺肌症","point":"胆囊壁局灶性增厚伴罗-阿氏窦，超声见壁内微囊或彗星尾征，通常良性，但难以完全排除恶变时需随访或手术。"}],"tx":{"drug":[{"name":"熊去氧胆酸","dose":"10–15 mg/kg/d，分 2–3 次口服，疗程 ≥6 个月","note":"仅用于胆固醇结石 <1.5 cm、胆囊功能良好且不手术者，溶石率约 30%–50%，停药后复发率高","renal":"遵说明书","hepatic":"肝功能不全及胆道梗阻者禁用","interact":"与考来烯胺等胆汁酸螯合剂合用降低吸收，需间隔服药"},{"name":"山莨菪碱/间苯三酚（胆绞痛解痉）","dose":"山莨菪碱 10 mg 肌注或静注（按需）；间苯三酚 40–80 mg 静滴","note":"缓解胆绞痛，注意青光眼与前列腺增生者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"抗胆碱药与其他抗胆碱能药合用副作用叠加"},{"name":"对乙酰氨基酚/双氯芬酸（镇痛）","dose":"对乙酰氨基酚 0.5–1 g 口服或静滴（日总量 ≤2 g，肝功能不全者减量）；双氯芬酸 75 mg 肌注（单次）","note":" NSAIDs 可缓解胆绞痛并降低急性胆囊炎进展风险，警惕消化道出血","renal":"肾功能不全者避免 NSAIDs","hepatic":"肝硬化者限制对乙酰氨基酚剂量","interact":"NSAIDs 与抗凝药合用增加出血风险"},{"name":"围术期预防性抗菌（如头孢呋辛）","dose":"头孢呋辛钠 1.5 g 静脉注射，术前 30–60 min 单次","note":"低危单纯胆囊切除可不用，高危或已感染按治疗剂量使用","renal":"重度肾功能不全减量","hepatic":"遵说明书","interact":"与口服避孕药合用降低避孕效力"}],"nonDrug":["胆囊结石手术指征：有症状的胆囊结石；结石 ≥2–3 cm；胆囊壁钙化/瓷化胆囊；合并胆囊息肉 ≥10 mm；合并糖尿病（可放宽）；胆囊壁增厚伴慢性胆囊炎；儿童或病程长者并发症风险增加","无症状胆囊结石：多数可观察，但合并糖尿病、免疫抑制、胆囊壁增厚或打算长期禁食者建议切除","胆囊息肉手术指征：直径 ≥10 mm；6–9 mm 合并高危因素（单发、基底宽、无蒂、合并结石、生长快、年龄 >50 岁）者倾向手术；<6 mm 且无危险因素者每 6–12 个月超声随访","腹腔镜胆囊切除为首选；术中发现胆总管结石可行腹腔镜胆总管探查（LCBDE）或术后 ERCP","胆绞痛反复发作者在发作间歇期择期手术","老年人或手术高危者行经皮经肝胆囊穿刺引流仅作为急性胆囊炎的桥接治疗"],"life":["规律进餐，避免长期禁食，控制体重与缓慢减重（每周减重 ≤1.5 kg 减少结石形成）","低脂饮食，减少油炸与高胆固醇食物","术后 2–4 周复查肝功能与超声，注意腹泻（约 5%–10%）","息肉观察期间每 6–12 个月超声，记录大小与形态变化"]},"prog":"无症状胆囊结石 10 年症状累积风险约 20%，年胆囊炎/并发症风险约 1%–2%。腹腔镜胆囊切除并发症率 <5%、手术病死率 <0.5%。胆囊息肉中腺瘤性息肉癌变风险约 5%–10%，直径 ≥10 mm 显著升高。","refs":["中国慢性胆囊炎、胆囊结石内科诊疗共识（2018 年）","胆囊良性疾病外科治疗的专家共识（2021 年）","TG18：东京指南胆囊炎诊治（2018 年）","外科学（第 9 版）·胆石病"]},{"id":"gs_aosc","name":"急性梗阻性化脓性胆管炎","aka":["Acute obstructive suppurative cholangitis","AOSC","急性重症胆管炎 ACST"],"rank":2,"basic":{"define":"胆道梗阻基础上继发化脓性感染，胆管内压力升高致脓性胆汁反流入血，引起全身严重感染和感染性休克的重症胆管炎，是胆道感染中最凶险的类型。","risk":["胆总管结石嵌顿（最常见病因，约占 60%–80%）","胆道术后狭窄、胆肠吻合口狭窄","胆管肿瘤、胰头癌、十二指肠乳头病变","既往 ERCP/PTCD 导管阻塞、先天性胆管扩张症"],"epi":"占胆道感染住院患者的 10%–20%，病死率仍达 10%–30%，合并休克与多器官功能障碍者病死率超过 30%。"},"patho":"胆道梗阻 → 胆管内压力升高（>20 cmH2O）→ 毛细胆管与胆管静脉间屏障破坏 → 细菌（革兰阴性肠杆菌、肠球菌、厌氧菌）与内毒素入血 → 全身炎症反应 → 休克、MODS。早期胆道减压是阻断病理进程的关键。","dx":{"criteria":["Charcot 三联征：右上腹痛、寒战高热、黄疸","Reynolds 五联征：Charcot 三联征 + 休克（血压下降、乳酸升高）+ 中枢神经系统抑制（意识模糊/谵妄），提示 AOSC","实验室：白细胞 >20×10^9/L 或明显降低、CRP/PCT 显著升高、胆红素与 ALP/GGT 升高、血培养阳性","影像：超声见胆总管内结石与肝内外胆管扩张；CT/MRCP 明确梗阻部位与病因","按 TG18 严重度分级：Ⅲ 级（重度，伴器官功能障碍）、Ⅱ 级（中度，白细胞 >12×10^9/L 或高热 ≥39 ℃ 等）、Ⅰ 级（轻度）"],"workup":["立即评估生命体征、乳酸、尿量与意识状态；必要时入 ICU","血培养 2 套（含厌氧）与胆汁培养、血常规、凝血、肝肾、血气、PCT","床旁超声为首选，血流动力学允许时行 CT/MRCP","心动超声与容量评估，指导液体复苏","排除胆总管肿瘤（CA19-9、增强影像）"],"grading":"TG18 严重度分级：Ⅰ 级轻度（经初期处理 24 h 内改善）、Ⅱ 级中度（需要早期胆道引流）、Ⅲ 级重度（器官功能障碍，须紧急引流与器官支持）。"},"ddx":[{"name":"胆囊结石与胆囊息肉（同大类 gs_cholelithiasis）","point":"胆囊结石一般不伴黄疸与休克，胆总管无扩张；AOSC 一定有胆道梗阻与全身炎症反应。"},{"name":"急性胆囊炎（gs_chole）","point":"急性胆囊炎无黄疸与休克，Murphy 征阳性，炎症局限；若出现黄疸、休克与意识障碍应升级为 AOSC 考虑。"},{"name":"急性胰腺炎","point":"上腹痛向腰背放射，血淀粉酶/脂肪酶升高 ≥3 倍，CT 见胰腺水肿/坏死；AOSC 以黄疸、寒战高热与胆管扩张为主，两者可合并存在（胆源性胰腺炎）。"},{"name":"胆管癌与胆囊癌合并感染","point":"胆管癌以无痛性黄疸为主，CA19-9 高，MRCP 见胆管截断，感染多为继发；若影像见占位且黄疸进行性加重需警惕。"},{"name":"肝脓肿","point":"肝脓肿以高热、右上腹痛、肝脏囊性病灶为主，胆管可不扩张；AOSC 有胆总管梗阻与胆管扩张，常合并肝脓肿。"}],"tx":{"drug":[{"name":"哌拉西林-他唑巴坦（经验性广谱抗菌）","dose":"4.5 g 静脉滴注 q6–8h（严重感染按说明书给药）","note":"覆盖肠杆菌、肠球菌与厌氧菌，须在留取培养后立即给药，后按药敏调整","renal":"肌酐清除率下降时按说明书减量或延长间隔","hepatic":"遵说明书","interact":"避免与氨基糖苷类同瓶输注"},{"name":"碳青霉烯类（美罗培南，重症/耐药风险）","dose":"1 g 静脉滴注 q8h（延长输注 3 h）","note":"用于脓毒症、既往 ESBL 感染或当地耐药率高者，与引流同等重要","renal":"肌酐清除率 <50 mL/min 按说明书减量","hepatic":"遵说明书","interact":"与丙戊酸钠合用显著降低其血药浓度，避免联用"},{"name":"液体复苏与去甲肾上腺素（感染性休克）","dose":"晶体液 30 mL/kg 初始复苏（成人心脏负荷可耐受时），去甲肾上腺素维持 MAP ≥65 mmHg，按血压滴定","note":"复苏后仍低血压者使用血管活性药，需监测乳酸与尿量","renal":"密切监测尿量","hepatic":"遵说明书","interact":"与β受体阻滞剂合用减弱升压作用"},{"name":"乌司他丁（辅助）","dose":"10 万 U 静脉滴注 q8–12h（遵说明书）","note":"抑制蛋白酶与炎症反应，为辅助治疗，不替代引流","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["紧急胆道减压是核心：Ⅲ 级须在 12–24 h 内完成引流，可在 ICU 支持下行 ERCP（鼻胆管引流 ENBD 或胆道支架）或 PTCD","ERCP 为首选：乳头切开 + 取石 + 鼻胆管引流；出血或凝血障碍者谨慎","PTCD：ERCP 失败或不可行时，超声引导穿刺置管引流；胆道高位梗阻或多发结石可联合 PTCD 与 ERCP","术后/胆道狭窄者行经皮经肝胆道镜（PTCS）取石或胆道成形","手术胆总管切开取石 + T 管引流：内镜与介入失败、穿孔或需同时处理胆囊时","胆囊切除：病情稳定后择期行胆囊切除（减少复发）","生命支持：呼吸与循环监护、血液净化（合并 AKI 时）"],"life":["出院后监测黄疸、发热、腹痛，警惕复发（尤其是未取净结石者）","处理病因（结石、狭窄）以防反复发作","PTCD/ENBD 带管者需定期冲管与换管，注意移位与堵塞","恢复期肝功能与胆管影像复查，必要时再次 ERCP 取石"]},"prog":"早期引流 + 抗菌 + 器官支持后病死率可降至 10% 以下；未能及时引流者病死率超过 20%。引流失败或延误（>24 h）是死亡的主要危险因素。","refs":["TG18：东京指南胆道感染诊疗（2018 年）","急性胆道系统感染的诊断和治疗指南（2021 年）","中国胆道感染诊治专家共识","外科学（第 9 版）·胆道感染"]},{"id":"gs_cholangioca","name":"胆管癌与胆囊癌","aka":["Cholangiocarcinoma","Gallbladder carcinoma","Cholangiocarcinoma perihilar"],"rank":3,"basic":{"define":"起源于胆管上皮的恶性肿瘤（按部位分肝内、肝门部、远端胆管癌）及起源于胆囊黏膜的胆囊癌，两者均以胆道梗阻或胆囊占位为主要表现，预后差。","risk":["胆管结石、肝内胆管结石反复胆道感染","原发性硬化性胆管炎、胆管囊肿、Carolis 病","肝吸虫感染（华支睾吸虫）","胆囊结石、胆囊息肉 >10 mm、瓷化胆囊、胆囊腺肌症伴结石","肝吸虫流行区人群、长期接触化学致癌物"],"epi":"我国胆管癌年发病率约 1–3/10 万，肝内胆管癌近年呈上升趋势；胆囊癌约占胆道恶性肿瘤的 80%–95%，女性多见，60–70 岁为发病高峰，合并胆囊结石者占 70%–90%。"},"patho":"胆管上皮在慢性炎症（结石、感染、PSC）驱动下发生异型增生→原位癌→浸润性癌；胆囊癌多经腺瘤—癌序列或胆囊黏膜不典型增生演变为腺癌（占 90% 以上）。肝门部胆管癌沿胆管壁向黏膜下浸润并易侵犯门静脉、肝动脉，呈「浸润性生长」，早期即沿神经丛扩散。","dx":{"criteria":["进行性无痛性梗阻性黄疸、皮肤瘙痒、陶土色便；肝内胆管癌可表现为腹痛与肝肿块而无黄疸","CA19-9 常升高（>37 U/mL），胆囊癌合并胆道梗阻时也可升高；CEA 可辅助","增强 CT/MRI：肝门部胆管癌见胆管壁增厚、管腔狭窄、肝内胆管扩张「软藤征」；胆囊癌见胆囊壁不规则增厚或腔内实性占位、增强后强化","MRCP 显示胆管狭窄部位与范围（Bismuth-Corlette 分型）；EUS/FNA 或 ERCP 刷检可获取细胞学","胆囊癌分期按 AJCC TNM 第 8 版（T1a 黏膜、T1b 肌层、T2 肌周、T3 浆膜/肝、T4 邻近器官）"],"workup":["增强 CT（肝胆胰多期）与 MRI/MRCP，评估肿瘤范围、胆管侵犯与血管受累","CA19-9、CEA、AFP；肝肾功能与凝血（决定手术耐受）","PET-CT 评估远处转移（可改善分期准确性）","胆道引流（PTCD/ENBD）与胆道镜检查/活检（PTCS 或 SpyGlass）","胆囊癌术中冰冻评估切缘与浸润深度（T1b 以上需肝脏切除或淋巴结清扫）"],"grading":"Bismuth-Corlette 肝门部胆管癌Ⅰ–Ⅳ 型；AJCC TNM 第 8 版分期；胆囊癌按浸润深度 T 分期决定术式范围。"},"ddx":[{"name":"胆囊结石与胆囊息肉（同大类 gs_cholelithiasis）","point":"胆结石与良性息肉无强化实性占位、无胆管浸润；胆囊癌有强化性壁增厚或不规则肿块伴转移，息肉 >10 mm 宽基底或增长快须高度警惕。"},{"name":"急性梗阻性化脓性胆管炎（gs_aosc）","point":"AOSC 以寒战高热、休克等急性炎症为主，黄疸可波动，引流后迅速改善；肿瘤性梗阻黄疸进行性加深，无急性感染但可合并继发感染，肿瘤标志物升高。"},{"name":"原发性硬化性胆管炎","point":"PSC 表现为多发性胆管狭窄与串珠样改变，合并 IBD 更多见，CA19-9 可轻度升高；若 PSC 患者狭窄进展迅速须排除胆管癌（刷检/活检）。"},{"name":"胰头癌/壶腹周围癌","point":"胰头癌致双管征（胆管与胰管均扩张）、CA19-9 高、CT 见胰头低强化肿块；壶腹癌可有波动性黄疸与消化道出血。"},{"name":"肝细胞癌","point":"多有肝硬化与 AFP 升高，增强 CT 呈「快进快出」，肝内胆管癌以周边强化延迟增强为主，需结合 AFP 与影像模式。"}],"tx":{"drug":[{"name":"吉西他滨 + 顺铂（晚期一线）","dose":"吉西他滨 1000 mg/m² 静脉滴注（d1、d8），顺铂 25 mg/m²（d1、d8），每 21 天 1 周期","note":"ABC-02 方案，晚期胆道癌标准一线；需评估肾功能并充分水化","renal":"肌酐清除率 <60 mL/min 慎用/减量，遵说明书","hepatic":"肝功能不全者按说明书调整","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"度伐利尤单抗 + 吉西他滨/顺铂（晚期一线，免疫联合）","dose":"度伐利尤单抗 1500 mg 静脉输注 d1（每 3 周），联合吉西他滨/顺铂按上述剂量","note":"TOPAZ-1 研究支持的免疫联合方案，需注意免疫相关不良事件","renal":"遵说明书","hepatic":"遵说明书；用药前排除自身免疫性疾病","interact":"避免与强效免疫抑制治疗同期使用"},{"name":"卡培他滨（术后辅助）","dose":"1250 mg/m² po bid，d1–d14，每 3 周，疗程 6 个月（BILCAP 方案）","note":"胆道癌根治术后辅助化疗，需监测手足综合征与骨髓抑制","renal":"肌酐清除率下降时按说明书减量","hepatic":"重度肝功能不全慎用","interact":"与华法林合用显著增强抗凝作用，需监测 INR"},{"name":"减黄支持：经皮胆道引流后纠正黄疸","dose":"维生素 K1 10 mg 肌注或静滴，按 INR 调整（如 10 mg qd × 3 天）","note":"梗阻性黄疸致维生素 K 吸收障碍、凝血异常，术前须纠正","renal":"遵说明书","hepatic":"肝功能不全者监测 INR","interact":"与抗凝药/抗血小板药的相互作用按说明书"}],"nonDrug":["胆管癌根治性切除：肝外胆管癌、肝门部Ⅰ–Ⅱ 型可行胆管切除 + 肝门淋巴结清扫 + 肝管空肠 Roux-en-Y 吻合；可切除者争取 R0 切除","肝内胆管癌：规则性肝切除 + 区域淋巴结清扫","胆囊癌：T1a 行单纯胆囊切除；T1b 及 T2 以上行胆囊切除 + 肝床楔形切除/部分肝切除 + 肝十二指肠韧带淋巴结清扫；腹腔镜术中发现须注意穿刺孔种植，必要时中转开腹","不可切除胆管癌的姑息引流：PTCD/内镜支架（金属支架）缓解黄疸","肝移植对严格筛选的肝门部胆管癌（Mayo 方案）仅限极少数中心","局部治疗：射频消融/TACE/钇-90 微球用于不可切除肝内胆管癌","晚期：化疗 + 免疫治疗，处理胆道感染、营养支持与疼痛管理"],"life":["戒烟酒，控制胆道结石与慢性胆道感染","胆囊结石/息肉患者按指征手术以防癌变","术后 3 个月内每 2 个月复查肿瘤标志物与影像，后每 3–6 个月","胆道支架者出现发热、黄疸加重须警惕梗阻与胆管炎"]},"prog":"胆囊癌整体 5 年生存率 <20%，T1a 可达 80% 以上，T3 以上低于 10%；胆管癌根治性切除后 5 年生存率约 20%–35%，肝门部胆管癌更差；不可切除者中位生存期约 12–15 个月（免疫联合后改善）。","refs":["中国胆道恶性肿瘤诊疗指南（2022 年）","胆囊癌规范化诊治专家共识","NCCN 胆道癌临床实践指南（2023 年）","外科学（第 9 版）·胆管癌与胆囊癌"]},{"id":"gs_ventral_hernia","name":"股疝与切口疝","aka":["Femoral hernia","Ventral hernia","Incisional hernia","腹壁疝"],"rank":4,"basic":{"define":"股疝为腹腔脏器经股环突入股管、在腹股沟韧带下方卵圆窝突出；切口疝为腹部手术后腹壁筋膜缺损处脏器突出，属腹壁疝（ventral hernia）的一种。","risk":["股疝：女性（尤其多产、经产妇）、高龄、腹内压升高（慢性咳嗽、便秘、前列腺增生）","切口疝：既往剖腹手术（尤其是切口感染、裂开、肥胖、糖尿病）、腹壁切口长度 >18 cm、术后感染","肥胖、营养不良、长期使用糖皮质激素、胶原代谢异常","吸烟、慢性阻塞性肺病、腹水"],"epi":"股疝占腹外疝的 2%–4%，但嵌顿率高达 40%–60%，是最易嵌顿的腹外疝；切口疝发生率在开放腹部手术后约 10%–20%，存在切口感染时可达 30%以上。"},"patho":"腹壁筋膜缺损 + 腹内压升高 → 腹腔内容物（多为小肠、网膜）经缺损突出。股环狭小（直径约 1–2 cm）、边界为坚韧韧带，股疝嵌顿后极易绞窄；切口疝因筋膜缘回缩、瘢痕组织脆弱，缺损常逐步扩大。嵌顿后静脉回流受阻 → 水肿 → 动脉缺血 → 肠绞窄、坏死。","dx":{"criteria":["股疝：腹股沟韧带下方卵圆窝处可复性包块，咳嗽冲击感较弱，易漏诊于肥胖或女性患者","切口疝：既往手术切口处包块，站立/咳嗽时增大、平卧可缩小或回纳，触诊可触及筋膜缺损（可测量缺损长径）","嵌顿：包块不能回纳、局部压痛明显、伴恶心呕吐、腹胀与停止排便排气（肠梗阻），超声见疝囊内液体与不可回纳团块","绞窄：局部红肿热痛、发热、白细胞升高、腹膜刺激征、脓毒症表现，属急症","超声/CT 评估缺损大小、疝囊内容物与肠管血运"],"workup":["站立位与卧位分别查体，咳嗽冲击感与可复性判断","超声为首选影像，CT 用于复杂疝（多发、巨大、复发）与术前规划（EHS 分型）","嵌顿时监测生命体征、腹部体征与乳酸","术前评估心肺功能、糖尿病控制与营养状态；切口疝测量缺损宽度与疝囊体积","疑似肠坏死时关注白细胞、CRP、PCT 与 CT 壁内积气"],"grading":"EHS 分类：按部位（M 中线、L 侧方）、缺损宽度（W1 <4 cm、W2 4–10 cm、W3 >10 cm）分型；股疝按是否可复、嵌顿、绞窄分级。"},"ddx":[{"name":"胆道与腹壁其他类内疾病（如胆囊结石与胆囊息肉 gs_cholelithiasis 等）","point":"同大类中胆囊结石、AOSC、胆道肿瘤以右上腹/黄疸表现为主，与腹壁疝的腹股沟或切口包块明显不同，按位置与影像可区分。"},{"name":"腹股沟疝","point":"腹股沟疝包块位于腹股沟韧带上方、可达阴囊，咳嗽冲击感强；股疝位于韧带下方（卵圆窝处），女性多见且嵌顿率高。"},{"name":"股静脉扩张/大隐静脉曲张结节","point":"质软、有波动，压迫后可缩小，无咳嗽冲击感与肠梗阻表现；超声见静脉管腔扩张。"},{"name":"腹壁肿瘤（脂肪瘤、纤维瘤、肉瘤）或转移瘤","point":"不能回纳、无咳嗽冲击感，质地硬，超声/CT 见实性肿块而非含气肠管；Sister Mary Joseph 结节提示腹腔恶性肿瘤。"},{"name":"腹直肌鞘血肿/脓肿","point":"有外伤、抗凝或感染病史，超声/CT 见腹壁肌鞘内液体回声而无筋膜缺损；局部疼痛与包块但 Murphy 征阴性与无疝环。"}],"tx":{"drug":[{"name":"头孢呋辛（围术期预防/嵌顿感染）","dose":"头孢呋辛钠 1.5 g 静脉注射，术前 30–60 min 单次；合并感染按治疗剂量 0.75–1.5 g q8h","note":"嵌顿疝患者预防性抗菌可降低术后切口感染风险","renal":"肌酐清除率 <20 mL/min 减量","hepatic":"遵说明书","interact":"与口服避孕药合用降低避孕效力"},{"name":"甲硝唑（合并肠管坏死时）","dose":"0.5 g 静脉滴注 q8h","note":"覆盖厌氧菌，肠绞窄坏死时联合使用","renal":"肾功能不全者延长给药间隔","hepatic":"肝功能不全减量","interact":"用药期间禁酒；与华法林合用时增强抗凝"},{"name":"质子泵抑制剂（围术期应激性溃疡预防，高危者）","dose":"奥美拉唑 40 mg 静脉推注 qd 或 q12h","note":"嵌顿疝合并肠梗阻仍需手术者，按应激性溃疡风险评估使用","renal":"遵说明书","hepatic":"严重肝功能不全减量","interact":"可能降低氯吡格雷活性代谢物浓度，间期使用"}],"nonDrug":["股疝一经诊断建议择期手术（嵌顿率高），推荐网片修补（Lichtenstein 或 McVay 法）；嵌顿者立即急诊手术，必要时开腹探查绞窄肠管","切口疝无嵌顿：缺损小且无症状者可观察；有症状或嵌顿风险大者行择期修补（IPOM、sublay 或开放补片修补），缺损 >10 cm 需评估腹壁重建","嵌顿疝处理原则：尽早手法复位仅限发病短、无绞窄征象者；成功后限期手术；绞窄或手法失败须急诊手术","术中必须探查疝囊内容物血供，坏死肠管行肠切除吻合，避免将坏死肠段还纳腹腔","急诊嵌顿修补尽量用清洁-污染条件下可行的修补方式，感染风险高者仅行简单修补，不放置大网片至污染区域","巨大切口疝术前评估腹腔容积（可考虑渐进性气腹或肉毒毒素扩张腹壁）","肥胖患者先行减重（或术前减重计划）可降低复发率"],"life":["术后 6–8 周避免提重物与剧烈咳嗽；慢性咳嗽与便秘需同步治疗","减重、戒烟、控制血糖，降低补片感染与复发风险","补片感染表现为持续疼痛、包块与发热，须及时就诊","随访 1 年复发率约 5%–10%，复发者需影像评估后再修补"]},"prog":"股疝嵌顿率 40%–60%，急诊手术病死率可达 5%–10%，其中肠绞窄切除者更高；择期股疝修补复发率约 2%–5%。切口疝补片修补复发率约 5%–15%，复杂巨大腹壁疝复发率可达 20%以上。","refs":["腹股沟疝与腹壁疝诊治指南（2021 年）","WSES：股疝管理指南（2017 年）","EHS 腹壁疝分类指南（2015 年）","外科学（第 9 版）·股疝与切口疝"]},{"id":"gs_surgical_infection","name":"外科感染（痈、丹毒、脓毒症）","aka":["Surgical infection","Carbuncle","Erysipelas","Surgical sepsis"],"rank":5,"basic":{"define":"需外科处理的感染性疾病，包括局限化脓性感染（急性蜂窝织炎、痈、疖、丹毒、脓肿）及由此进展的脓毒症；核心原则是「切开引流、清除坏死、源头控制」联合抗感染治疗。","risk":["糖尿病与血糖控制不良（痈、坏死性感染高发）","皮肤破损与长期卧床（压力性溃疡、褥疮）","免疫功能低下（糖皮质激素、化疗、器官移植）","丹毒：淋巴管阻塞、足癣与下肢水肿","外科手术、留置导管与器械相关感染"],"epi":"外科感染占外科急症相当比例，金黄色葡萄球菌与化脓性链球菌为皮肤软组织感染主要病原；脓毒症全球年发病约 4900 万例，病死率约 20%，术后脓毒症是外科死亡的重要原因。"},"patho":"细菌侵入皮肤/黏膜或局部组织后形成炎症反应，金黄色葡萄球菌等产生酶与毒素致组织坏死与脓肿形成。痈为多个相邻毛囊及其周围组织的急性化脓性感染，好发于颈项与背部，皮厚而不易溃破，常沿筋膜间隙扩散。丹毒为乙型溶血性链球菌引起皮肤及其网状淋巴管的急性炎症，蔓延快、界限清楚。感染扩散或毒素入血可致全身炎症反应综合征与脓毒症、感染性休克、MODS。","dx":{"criteria":["局部红、肿、热、痛，脓肿形成有波动感；痈表现为大片浸润性紫红色斑块、多个脓头、边界不清","丹毒：界限清楚、隆起、鲜红、局部灼热，进展迅速，伴发热与淋巴结肿大","全身表现：发热 >38.3 ℃ 或 <36 ℃、心率 >90 次/min、呼吸 >20 次/min、白细胞 >12×10^9/L 或 <4×10^9/L","脓毒症：感染 + 序贯器官衰竭评分（SOFA）较基线升高 ≥2 分；感染性休克：充分液体复苏后仍需血管活性药维持 MAP ≥65 mmHg 且乳酸 >2 mmol/L","脓液/血培养与降钙素原（PCT）辅助判断病原与病情"],"workup":["评估局部范围、波动感与淋巴管炎（红线）走行；检查血糖与糖尿病史","血常规、CRP、PCT、肝肾功能、乳酸、凝血","脓液培养与药敏、血培养 2 套；丹毒可取局部拭子","超声评估深部脓肿与积液范围；CT/MRI 用于深部感染（腹腔、盆腔、坏死性筋膜炎）","疑似坏死性筋膜炎（皮肤变黑、捻发音、疼痛与体征不符）行紧急手术探查"],"grading":"按感染部位与严重度：局部感染、全身炎症反应（SIRS）、脓毒症（SOFA ≥2）、感染性休克。丹毒与痈按范围与全身表现分级。"},"ddx":[{"name":"肝脓肿（同大类 gs_liver_abscess）","point":"同属需外科处理的感染。肝脓肿为腹腔内脏器感染，以高热与肝区叩击痛为主，需影像穿刺引流；体表痈/丹毒以皮肤局部红肿为主，位置不同。"},{"name":"坏死性筋膜炎","point":"为外科急症，进展迅速，皮肤变黑、出现水疱与捻发音，疼痛与体征不成比例；须紧急广泛清创，单纯抗菌不足。"},{"name":"蜂窝织炎 vs 丹毒","point":"蜂窝织炎界限不清、多见于下肢、可伴脓肿；丹毒界限清楚、鲜红色、有淋巴管炎，常累及面部或下肢。"},{"name":"深静脉血栓伴下肢肿胀","point":"下肢丹毒与 DVT 均有肿胀疼痛，丹毒有发热、皮肤红斑界限清楚与触痛；DVT 皮肤多无红斑，超声见静脉血栓。"},{"name":"炭疽/病毒性皮肤疹","point":"炭疽有接触史，溃疡呈焦痂样；带状疱疹沿神经分布呈簇状水疱，全身症状轻，与痈或丹毒表现不同。"}],"tx":{"drug":[{"name":"青霉素（丹毒首选）","dose":"青霉素 G 240 万–480 万 U 静脉滴注 q6–8h，疗程 10–14 天；或苄星青霉素 120 万 U 肌注（预防复发）","note":"按青霉素皮试；丹毒需足疗程以防复发，反复发作者可长期预防","renal":"肾功能不全者按说明书减量或延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度；勿与大剂量肝素同瓶"},{"name":"头孢呋辛/头孢唑林（皮肤软组织感染）","dose":"头孢呋辛钠 0.75–1.5 g 静脉滴注 q8h；头孢唑林 1 g q8h","note":"覆盖金葡菌与链球菌，符合临床经验用药；轻症可口服头孢类","renal":"肌酐清除率 <20 mL/min 调整剂量","hepatic":"遵说明书","interact":"与口服避孕药合用降低避孕效力"},{"name":"万古霉素（MRSA 风险/重症）","dose":"15–20 mg/kg 负荷 1 次，之后按 15 mg/kg q12h 静滴，监测谷浓度 15–20 mg/L（重症感染目标 15–20 mg/L）","note":"疑为 MRSA 或化脓性感染高风险者使用，注意肾毒性","renal":"按肌酐清除率调整剂量并监测血药浓度","hepatic":"遵说明书","interact":"与氨基糖苷类、利尿剂合用时肾毒性叠加"},{"name":"液体复苏与血管活性药（脓毒症/感染性休克）","dose":"晶体液 30 mL/kg 初始复苏（心脏负荷可耐受时），去甲肾上腺素滴定使 MAP ≥65 mmHg","note":"1 h 内完成初始复苏评估，4 小时内明确脓毒症诊断与抗菌时机","renal":"监测尿量与肌酐","hepatic":"遵说明书","interact":"与β受体阻滞剂合用减弱升压作用"},{"name":"对乙酰氨基酚/布洛芬（对症退热镇痛）","dose":"对乙酰氨基酚 0.5–1 g 口服，日总量 ≤2 g（肝功能不全者减量）；布洛芬 0.3–0.4 g 口服 tid","note":"仅对症，不替代引流与抗感染","renal":"肾功能不全避免 NSAIDs","hepatic":"肝功能不全限制对乙酰氨基酚","interact":"NSAIDs 与抗凝药合用增加出血风险"}],"nonDrug":["切开引流：所有脓肿（尤其是 >2 cm、有波动感者）都应切开引流；痈破溃后或已形成明显脓肿时行「十」字或「井」字切开，清除坏死组织并充分引流","丹毒：抬高患肢、局部湿热敷，处理足癣与下肢水肿等诱因，避免挤压与按摩以防扩散","脓毒症：1 h 内完成血培养并启动抗菌、液体复苏；3 h 内采血、1 h 内用药","源头控制：感染源尽早找到并处理（脓肿引流、坏死组织清除、导管拔除），力争 6–12 h 内完成","坏死性筋膜炎/深部感染：紧急广泛清创，必要时反复清创或截肢","营养支持与血糖控制：糖尿病者强化胰岛素；重症者肠内营养","免疫缺陷者调整免疫抑制方案（与专科协商）"],"life":["足癣、皮肤破损及时治疗，防止丹毒复发；反复丹毒者可长期低剂量青霉素预防","糖尿病患者控制血糖、注意足部护理与溃疡预防","术后患者保持切口清洁干燥，出现发热、红肿扩散立即就诊","脓毒症恢复期需随访器官功能与营养状态，早期康复"]},"prog":"局限性感染经引流与抗菌治疗后多可痊愈；丹毒复发率约 20%–30%。脓毒症总体病死率约 20%，感染性休克可达 40%–50%，早期识别、抗菌与源头控制可显著改善预后。","refs":["中国脓毒症/感染性休克急诊诊疗指南（2018 年）","Surviving Sepsis Campaign 脓毒症国际指南（2021 年）","中国皮肤软组织感染诊疗专家共识","外科学（第 9 版）·外科感染"]}]},{"id":"surg_infection","name":"外科感染与特定感染","rank":7,"summary":"主线是「高危病史 + 特征性体征 → 快速识别 → 专科处理（清创/抗毒素/免疫球蛋白/抗蛇毒血清）+ 抗感染与支持」；破伤风重在彻底的伤口处理、TIG 与镇静控痉挛；气性坏疽强调 6 小时内广泛切开减压；咬伤按 WHO 暴露分级处理，蛇咬伤以抗蛇毒血清与凝血监测为核心。","compare":[{"diseaseId":"gs_tetanus","dx":"外伤史后数日至数周出现张口困难、牙关紧闭、苦笑面容、颈项强直与角弓反张，声光刺激可诱发痉挛，神志清醒；临床诊断，不依赖细菌学","key":"苦笑面容 + 角弓反张 + 吞咽困难，刺激诱发痉挛而神志清楚"},{"diseaseId":"gs_gas_gangrene","dx":"严重创伤后 1–4 天局部剧痛肿胀与体征不成比例，皮肤由白转紫黑、水疱、捻发音与恶臭，伴高热与心动过速；X 线见肌间积气，涂片见粗大革兰阳性杆菌","key":"捻发音 + 恶臭 + X 线肌间积气，是最快的床边与影像判断"},{"diseaseId":"gs_bite","dx":"动物咬抓伤按 WHO Ⅰ/Ⅱ/Ⅲ 级暴露分级决定伤口处理、疫苗与免疫球蛋白；毒蛇咬伤见成对牙痕、进行性肿胀与皮下瘀斑，并出现凝血异常或神经麻痹","key":"暴露分级决定是否用免疫球蛋白；蛇咬伤看牙痕与凝血/神经毒性"}],"diseases":[{"id":"gs_tetanus","name":"破伤风","aka":["Tetanus","破伤风梭菌感染"],"rank":1,"basic":{"define":"破伤风梭状芽孢杆菌经伤口侵入，在厌氧环境中繁殖并释放痉挛毒素，引起以骨骼肌强直与阵发性痉挛为特征的中毒性疾病，可预防但病死率仍高。","risk":["深而窄小的刺伤（铁钉、木刺），泥土、粪便或铁锈污染的伤口","烧烫伤、动物咬伤、开放性骨折与压砸伤","新生儿脐带处理不当、产妇不洁流产","未完成基础免疫或全程接种后 >10 年未加强","糖尿病足溃疡、压疮、慢性中耳炎、注射吸毒"],"epi":"我国已实现孕产妇与新生儿破伤风消除，成人病例仍见于农村中老年与未规范免疫者；重症需机械通气者病死率约 10%–30%，新生儿破伤风更高。"},"patho":"芽孢在氧化还原电位低（< +50 mV）的伤口发芽繁殖，产生痉挛毒素、溶血毒素与破伤风溶素。痉挛毒素经运动神经轴突逆行至脊髓前角与脑干，抑制抑制性神经递质（GABA、甘氨酸）释放，使运动神经元去抑制而出现全身强直与阵发性痉挛。毒素一旦与神经组织结合即难以中和，抗毒素只能清除循环中的游离毒素。自主神经兴奋可致心动过速、血压剧烈波动与大汗，是重症死亡的重要原因。","dx":{"criteria":["创伤史（约 10%–20% 无明确伤口），潜伏期 3–21 天（平均 7–10 天），潜伏期越短、起病 48 h 内出现痉挛者病情越重","前驱期：乏力、头晕、咀嚼无力、局部肌肉发紧与反射亢进","典型表现：张口困难（最早）、牙关紧闭、颈项强直、吞咽困难","苦笑面容（蹙额、皱眉、口角上提）与角弓反张（头后仰、腰背过伸）；腹肌板样硬","声、光、触、饮等轻微刺激诱发阵发性痉挛，发作时神志清楚、剧痛，间隙期肌肉仍强直","咽肌与喉肌痉挛致喘鸣与窒息，吞咽困难致流涎；重症伴自主神经紊乱（心率 >120 次/min、血压波动、大汗），体温多正常或低热"],"workup":["以临床表现诊断，不等待细菌学；伤口厌氧培养与毒素 PCR 阳性率低，阴性不能排除","评估伤口部位、深浅、异物与坏死组织，判断是否形成厌氧环境","评估气道：张口度、咽反射、喉痉挛、血氧，必要时血气分析","血常规、电解质（多汗与痉挛致低钠低钙）、CK、肾功能、心电图","全程心电血压血氧监护，重症入 ICU；频繁痉挛者评估预防性气管插管","可疑者腰穿与头颅 CT/MRI 排除脑膜炎与颅内病变"],"grading":"Ablett 分级：Ⅰ 级轻度（肌强直轻、无或轻微吞咽困难）；Ⅱ 级中度（明显痉挛、吞咽困难、需药物控制）；Ⅲ 级重度（频繁痉挛、自主神经紊乱、需气管切开与机械通气）。"},"ddx":[{"name":"气性坏疽（同大类 gs_gas_gangrene）","point":"同为厌氧梭菌感染且有创伤史，但气性坏疽以伤口剧痛、肿胀、捻发音、皮肤坏死与恶臭伴毒血症为主，无全身痉挛；破伤风伤口常无特殊，核心是牙关紧闭、苦笑面容与角弓反张。"},{"name":"咬伤相关感染（同大类 gs_bite）","point":"犬蛇咬伤后可有张口与吞咽困难，需追问暴露史：狂犬病以恐水恐风与躁狂交替为特征，无持续强直痉挛；蛇咬伤有牙痕与神经毒表现。须核查破伤风疫苗接种史。"},{"name":"狂犬病","point":"有犬猫蝙蝠暴露史，早期伤口麻木蚁行感，典型恐水、恐风、咽肌痉挛与流涎，但无牙关紧闭与角弓反张，病死率接近 100%。"},{"name":"士的宁（马钱子碱）中毒","point":"痉挛似破伤风，但发作间歇期肌肉可完全松弛（无持续强直），有药物或毒鼠药接触史。"},{"name":"颞下颌关节病与扁桃体周围脓肿","point":"张口受限但无全身痉挛，局部有压痛、波动或炎性表现，超声与 CT 可鉴别。"},{"name":"细菌性脑膜炎","point":"高热、意识障碍与脑膜刺激征，CSF 异常；破伤风神志始终清楚。"}],"tx":{"drug":[{"name":"破伤风抗毒素（TAT，马血清）","dose":"1 万–2 万 U 加入 500 mL 生理盐水静滴，伤口周围可局部浸润；过敏者脱敏注射或改用 TIG","note":"仅中和游离毒素；必须皮试（1:10 稀释液 0.1 mL 皮内），皮试阳性按说明书脱敏；国内以 TAT 为主，TIG 供应有限","renal":"遵说明书","hepatic":"遵说明书","interact":"与镇静药无相互作用；过敏体质者慎用"},{"name":"破伤风免疫球蛋白（TIG，人源）","dose":"500–3000 IU 单次肌注（多点或伤口周围浸润），新生儿 500 IU","note":"无需皮试、半衰期长；与含吸附剂的类毒素疫苗分开部位注射","renal":"遵说明书","hepatic":"遵说明书","interact":"不宜与活疫苗同期接种"},{"name":"甲硝唑（抗厌氧菌）","dose":"0.5 g 静滴 q8h ×7–10 天；轻症 0.4 g 口服 tid","note":"抑制病原菌繁殖，不替代抗毒素；也可用青霉素 G","renal":"CrCl <30 延长至 q12–24h","hepatic":"重度肝功能不全减量","interact":"用药及停药后 3 天禁酒；与华法林合用增强抗凝"},{"name":"地西泮（控痉挛）","dose":"轻症 10 mg 缓慢静注，2–4 h 可按需重复；重症 0.1–0.2 mg/kg 静注后 5–10 mg/h 泵入，按痉挛控制滴定","note":"监测呼吸抑制与意识；频繁痉挛无法控制者应在气道保护下深度镇静","renal":"遵说明书","hepatic":"重度肝病延长半衰期，减量","interact":"与阿片类、其他镇静药合用加重呼吸抑制"},{"name":"咪达唑仑（持续镇静）","dose":"0.05–0.1 mg/kg 静注后 0.05–0.2 mg/kg/h 持续泵入，滴定至痉挛控制","note":"注意低血压与呼吸抑制；可与硫酸镁联用","renal":"重度肾衰可蓄积","hepatic":"重度肝病延长镇静，减量","interact":"CYP3A4 抑制剂（酮康唑、大环内酯类）增强作用"},{"name":"硫酸镁（辅助控痉挛）","dose":"负荷 30–50 mg/kg 静滴 30 min，维持 1–2 g/h，监测血镁与腱反射","note":"控制不自主痉挛与自主神经紊乱；深腱反射消失或血镁 >5 mmol/L 需减量","renal":"肾衰时减量并监测血镁","hepatic":"遵说明书","interact":"与钙通道阻滞剂、氨基糖苷类合用增加神经肌肉阻滞"},{"name":"艾司洛尔/拉贝洛尔（自主神经紊乱）","dose":"艾司洛尔 25–50 µg/kg/min 泵入或拉贝洛尔 10–20 mg 静注按需，按心率血压滴定","note":"心率 >120 次/min 或血压剧烈波动时使用；避免单用短效降压致骤降","renal":"遵说明书","hepatic":"遵说明书","interact":"与镇静药合用加重低血压"}],"nonDrug":["伤口处理（关键）：彻底清创、去除异物与坏死组织、敞开引流，3% 过氧化氢冲洗后再用生理盐水，不做一期缝合","隔离护理：单间暗室，避免声光风与触摸刺激，集中护理操作","气道管理：出现咽肌/喉肌痉挛、频繁肺部感染或需深度镇静者尽早气管切开（或经鼻插管过渡），窒息是主要死因","支持治疗：静脉营养或鼻饲、纠正水电解质紊乱、防舌咬伤与压疮","重症入 ICU 连续监护，必要时硬膜外镇痛辅助缓解痉挛","主动免疫：病愈不产生免疫，恢复期完成类毒素全程接种（0、1、6–12 个月）"],"life":["康复训练：痉挛致肌腱关节挛缩者理疗","伤口污染后及时评估是否需要 TIG/TAT 与疫苗加强","完成全程疫苗后再恢复体力劳动","随访 3–6 个月，关注吞咽恢复、呼吸功能与自主神经症状"]},"prog":"局限型多在数日内恢复；全身型未行气管切开与机械通气者病死率 40%–60%，有 ICU 支持时降至 10%–20%。潜伏期 <7 天、起病 48 h 内出现痉挛者预后差。重型常遗留肌力减退与关节僵硬。","refs":["破伤风诊疗规范（国家卫生健康委员会，2019 年版）","中国破伤风免疫预防专家共识（2018 年）","外科学（第 9 版）·破伤风","WHO 破伤风预防与治疗指南（2017 年）"]},{"id":"gs_gas_gangrene","name":"气性坏疽","aka":["Gas gangrene","梭菌性肌坏死","Clostridial myonecrosis"],"rank":2,"basic":{"define":"梭状芽孢杆菌（以产气荚膜梭菌最常见）引起的肌坏死性感染，以组织内大量产气、局部剧痛肿胀、皮肤坏死与全身毒血症为特征，属外科急症。","risk":["严重挤压伤与开放性骨折，尤其大腿、臀部、小腿大面积肌肉损伤","伤口被泥土、粪便、异物污染伴深部死腔与引流不畅","局部缺血、低血压与休克致组织氧张力下降（厌氧环境）","糖尿病、免疫功能低下与结直肠手术（诺维梭菌自发性感染）","恶性肿瘤周围缺血区、注射部位（罕见自发性）"],"epi":"创伤性气性坏疽在挤压伤与开放性骨折后可高达 1%–5%；产气荚膜梭菌型病死率约 10%–25%，诺维梭菌型病死率可达 50%–70%。"},"patho":"梭菌在低氧化还原电位环境中繁殖并释放多种毒素：α 毒素（卵磷脂酶 C）破坏细胞膜致肌肉坏死与溶血；θ 毒素致血管痉挛与缺血；胶原酶与透明质酸酶促进扩散。糖发酵产生氢、二氧化碳与氮气，沿肌间隙与筋膜扩散形成捻发音与恶臭。大量坏死组织吸收毒素引起脓毒症、感染性休克、急性肾损伤与多器官衰竭。","dx":{"criteria":["创伤后 1–4 天急剧进展，潜伏期越短越重","局部剧痛进行性加重、与体征不成比例；周围肿胀迅速蔓延，皮肤由苍白紧张转为铜色、紫红或紫黑色","典型体征：皮下捻发音、水疱或血性疱、溃口渗出血性恶臭液体、皮肤坏疽","全身：高热 >38.5 ℃、心动过速、烦躁、贫血与黄疸，尿少直至休克","渗出液涂片见大量粗大革兰阳性杆菌（白细胞少）可快速支持诊断；培养需 24–48 h，不能等待","X 线平片见软组织（肌间）积气呈羽毛状或蜂窝状；CT 更敏感，显示筋膜内气体与坏死范围","CK 明显升高、白细胞 >15×10^9/L、血红蛋白下降、乳酸升高提示进展"],"workup":["床旁评估创面与疼痛，行筋膜切开探查：肌肉呈熟肉样、无收缩、不出血即为坏死","渗出液革兰染色 + 厌氧培养药敏，术中冰冻切片评估坏死范围","X 线患肢软组织积气，必要时 CT/MRI 与超声","血常规、凝血、CK、肝肾功能、乳酸、血气与血培养","持续监测生命体征与尿量，评估休克与肾功能","临床 + 涂片 + 影像主导诊断，禁止等培养结果再手术"],"grading":"按范围分局限型（单块或单组肌群）与弥漫型（整个肢体或躯干）；伴感染性休克者为重症。"},"ddx":[{"name":"破伤风（同大类 gs_tetanus）","point":"同为厌氧梭菌感染且有创伤史；破伤风以牙关紧闭、苦笑面容与全身强直痉挛为主，伤口局部无大面积产气；气性坏疽以伤口剧痛、肿胀、捻发音、皮肤坏死与毒血症为核心。"},{"name":"咬伤后严重感染（同大类 gs_bite）","point":"深部咬伤污染重时也可继发梭菌感染，但单纯咬伤感染以边界性红热、脓液与淋巴结肿大为主，无捻发音与极速扩展；出现捻发音须按气性坏疽紧急切开。"},{"name":"梭菌性蜂窝织炎","point":"局限于皮肤与皮下、无肌坏死，进展较慢、毒血症轻；一旦穿透肌层出现捻发音即按气性坏疽处理。"},{"name":"坏死性筋膜炎","point":"多为链球菌或多菌种混合感染，病变沿筋膜扩散，有捻发音与皮肤变黑，与气性坏疽难以临床区分；两者一旦怀疑均须紧急手术探查。"},{"name":"骨筋膜室综合征","point":"被动牵拉痛与筋膜室内压升高但无捻发音与高热；筋膜切开后肌组织多仍有血供，有别于梭菌性坏死。"},{"name":"深静脉血栓","point":"肢体肿胀疼痛但无捻发音、皮肤坏疽与全身高热毒血症；超声可见静脉血栓。"}],"tx":{"drug":[{"name":"青霉素 G（大剂量，首选）","dose":"200 万–400 万 U 静滴 q4h（总量 1200 万–2400 万 U/d），须皮试","note":"大剂量长期用可致中枢神经毒性（癫痫），肾衰者减量；不能替代清创","renal":"CrCl <10 延长间隔并减量","hepatic":"遵说明书","interact":"与氨基糖苷类同瓶配伍失活；丙磺舒可升高血药浓度"},{"name":"克林霉素（抑制毒素生成）","dose":"600–900 mg 静滴 q8h，联合青霉素或用于青霉素过敏者","note":"抑制蛋白合成而减少 α 毒素产生；警惕艰难梭菌相关性腹泻","renal":"无需调整，重度遵说明书","hepatic":"重度肝病减量","interact":"与红霉素等大环内酯类竞争结合位点"},{"name":"甲硝唑（替代/联合）","dose":"0.5 g 静滴 q8h","note":"青霉素过敏者的替代，覆盖厌氧菌","renal":"CrCl <30 减量延长间隔","hepatic":"重度肝病减量","interact":"禁酒；与华法林合用监测 INR"},{"name":"美罗培南/哌拉西林-他唑巴坦（混合感染）","dose":"美罗培南 1 g 静滴 q8h；哌拉西林-他唑巴坦 4.5 g 静滴 q6–8h，均按肾功能调整","note":"创伤伤口常合并革兰阴性菌，菌种不明或污染重时联用","renal":"美罗培南 CrCl <50 减量；哌拉西林-他唑巴坦 CrCl <40 延长间隔","hepatic":"遵说明书","interact":"美罗培南显著降低丙戊酸浓度，避免合用"},{"name":"液体复苏与升压（脓毒症）","dose":"晶体液 30 mL/kg 起始复苏（耐受时），去甲肾上腺素滴定使 MAP ≥65 mmHg","note":"与手术同期进行，监测尿量与乳酸","renal":"监测肾功能","hepatic":"遵说明书","interact":"与β受体阻滞剂合用减弱升压"},{"name":"对乙酰氨基酚/阿片类（镇痛）","dose":"对乙酰氨基酚 0.5–1 g 口服（≤2 g/d）；重度疼痛遵说明书静注阿片类滴定","note":"镇痛不得延误手术；伤口痛持续加重须考虑再次清创","renal":"肾衰避免 NSAIDs","hepatic":"肝功能不全时减量","interact":"阿片类与镇静药合用加重呼吸抑制"}],"nonDrug":["急诊广泛切开：怀疑气性坏疽者 6 h 内手术，沿伤肢长轴多处纵行切开皮肤与筋膜，彻底清除坏死肌肉直至健康出血组织，术后敞开引流","肢体血运与功能尽失、坏死广泛或快速进展者行截肢（在健康组织平面截肢、残端敞开）","每日或隔日二次清创直至无坏死组织，必要时反复进手术室","局部用 3% 过氧化氢或高锰酸钾冲洗；高压氧辅助抑制厌氧菌，不能替代手术","隔离：单间或负压病房，敷料器械按感染性废物处理","营养与血糖控制、纠正贫血与低蛋白，重症入 ICU"],"life":["创面护理与康复，截肢者假肢适配与功能训练","创伤早期彻底清创、污染伤口避免一期缝合","糖尿病者控糖与足部护理","随访残端伤口与肢体功能，红肿再发立即就诊"]},"prog":"创伤型经早期广泛清创与大剂量抗感染后病死率约 10%–25%；休克、就诊延迟 >24 h 与需截肢者预后差。自发性诺维梭菌型常伴恶性肿瘤或结肠病变，病死率可至 50%–70%。存活者多遗留肢体功能缺失。","refs":["外科学（第 9 版）·气性坏疽","外科感染诊治专家共识（中国医师协会外科医师分会）","WSES 皮肤软组织感染管理指南（2020 年）","高压氧治疗临床应用规范（中华医学会高压氧医学分会）"]},{"id":"gs_bite","name":"咬伤（狂犬病暴露与蛇咬伤）","aka":["Animal bite","Rabies exposure","Snakebite","狂犬病暴露","毒蛇咬伤"],"rank":3,"basic":{"define":"动物（犬、猫、蝙蝠、野生动物）咬抓伤与毒蛇咬伤的总称。动物伤按 WHO 暴露分级完成狂犬病暴露后预防（伤口清洗 + 疫苗 + 必要时免疫球蛋白）并处理继发感染；蛇咬伤以制动、抗蛇毒血清与凝血功能监测为核心。","risk":["动物咬抓伤，即使伤口轻微也需评估狂犬病暴露等级","未接种或未规范免疫的犬猫及野生哺乳动物致伤；蝙蝠接触（含无可见伤口）","伤口位于头颈面部、手部或神经丰富部位，或深部咬伤","蛇咬伤：草丛、农田、山区夜间活动，未穿防护鞋，捕蛇或徒手抓蛇","老年人、儿童与酒后反应迟缓、延误就诊","糖尿病、免疫缺陷或长期用激素者感染风险高"],"epi":"我国狂犬病病例约 95% 由犬致伤，近年年报告发病数已降至个位数百例，病死率接近 100%；犬猫咬伤约占急诊动物伤的三分之二。蛇咬伤以南方多见，蝮蛇为主，银环蛇、眼镜蛇、五步蛇致死仍时有发生。"},"patho":"狂犬病毒经伤口周围神经逆行至中枢，潜伏期多 1–3 个月，伤口越靠近头颈与神经丰富处潜伏期越短。动物口腔为多菌种混合菌群（犬伤以犬咬二氧化碳嗜纤维菌与巴斯德菌为主，猫伤以巴斯德菌为主），致蜂窝织炎、脓肿、深部间隙感染甚至骨髓炎。蛇毒分神经毒（银环蛇、金环蛇，阻断神经肌肉接头或突触前膜致呼吸肌麻痹）、血循毒（五步蛇、蝰蛇，耗竭凝血因子、溶血、组织坏死）与混合毒（眼镜蛇、蝮蛇）。","dx":{"criteria":["狂犬病暴露分级（WHO）：Ⅰ 级——接触或喂养动物、完好皮肤被舔，可确认皮肤完好者无需处置；Ⅱ 级——裸露皮肤被轻咬、无出血的轻微抓伤或擦伤，须处理伤口并接种疫苗；Ⅲ 级——贯穿性皮肤咬伤抓伤（出血）、破损皮肤被舔、黏膜被唾液污染、暴露于蝙蝠，须处理伤口 + 被动免疫制剂 + 疫苗","伤口评估：部位、深度、贯通性、污染度，有无骨折、肌腱神经血管伤与关节腔穿通","蛇咬伤局部：成对（或单个）牙痕、剧痛、进行性肿胀、水疱与皮下瘀斑、淋巴管炎","血循毒：伤口渗血不止、牙龈出血、血尿、呕血，血小板下降、PT/APTT 延长、纤维蛋白原降低","神经毒：眼睑下垂、复视、构音与吞咽困难、流涎、肌无力，继之呼吸肌麻痹，局部症状可轻","全身中毒：低血压休克、急性肾损伤、横纹肌溶解（肌痛、酱油色尿、CK 升高）"],"workup":["动物伤：清创后评估深部结构，手部咬伤查 X 线排除骨折与异物","破伤风免疫史：全程接种 >10 年未加强或接种史不明者按污染伤口加强","记录致伤动物免疫与健康状况，必要时隔离观察 10 天；狂犬病处置与狂犬病门诊联动","蛇伤：床边 20 分钟全血凝固试验快速筛查凝血障碍，并送凝血常规、纤维蛋白原、血小板、D-二聚体","蛇伤每 2–4 h 复查血红蛋白、血小板、凝血与肾功能，动态评估进展","血常规、CRP、PCT、脓液/血培养评估继发感染","CK、尿常规、肾功能与心电图；神经毒蛇监测血氧与呼吸功能","超声/CT 评估深部脓肿、筋膜室压力增高或坏死性感染"],"grading":"狂犬病暴露按 WHO Ⅰ/Ⅱ/Ⅲ 级；蛇伤严重度（WHO）：0 级无中毒表现；Ⅰ 级轻度（局部肿胀 <15 cm 或轻度全身反应）；Ⅱ 级中度（肿胀 15–30 cm、中度全身症状）；Ⅲ 级重度（肿胀 >30 cm、快速进展、休克、严重凝血异常或神经麻痹）。"},"ddx":[{"name":"气性坏疽（同大类 gs_gas_gangrene）","point":"深部污染咬伤后可继发梭菌感染：肿胀极速扩展、皮肤变黑、恶臭、伴毒血症，与单纯咬伤感染的边界性红热不同，须紧急切开。"},{"name":"破伤风（同大类 gs_tetanus）","point":"咬伤后出现牙关紧闭、苦笑面容与角弓反张应考虑破伤风，而非蛇伤神经毒（后者致弛缓性麻痹而非强直痉挛）。"},{"name":"无毒蛇咬伤","point":"牙痕多呈一行细小锯齿状，无进行性肿胀与凝血/神经毒性；毒蛇有成对牙痕与凝血或神经症状，需动态观察。"},{"name":"狂犬病发作前期","point":"恐惧、躁动、恐水恐风，早期伤口麻木蚁行感，无牙关紧闭与角弓反张；须与破伤风鉴别并追问疫苗史。"},{"name":"蜂蜇伤过敏反应","point":"有蜇伤史，局部红肿伴荨麻疹、喘鸣与低血压；蛇咬伤以牙痕与局部进行性肿胀为主。"}],"tx":{"drug":[{"name":"狂犬病疫苗（人二倍体细胞或 Vero 细胞）","dose":"Essen 5 针法：0、3、7、14、28 天各 1 剂肌注（上臂三角肌）；2-1-1 法：0 天 2 剂、第 7 天 1 剂、第 21 天 1 剂；Ⅱ、Ⅲ 级均须全程接种","note":"严禁注射于臀部；再次暴露按间隔评估加强（3 个月内一般无需加强，3 个月至 1 年 0、3 天各 1 剂，>1 年全程）；接种期间避免剧烈运动","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与免疫抑制剂、氯喹、大剂量激素同用；与 RIG 分部位注射"},{"name":"狂犬病免疫球蛋白（RIG，Ⅲ 级必需）","dose":"人源 HRIG 20 IU/kg（马源 ERIG 40 IU/kg），在伤口周围与底部浸润注射，余量注于三角肌（与疫苗相距 >2 cm）","note":"尽早使用，最好 7 天内；超过 7 天且已接种疫苗者一般不再用；绝不可与疫苗同部位或同瓶","renal":"遵说明书","hepatic":"遵说明书","interact":"与疫苗注射部位分开，避免中和疫苗活性"},{"name":"蛇毒抗血清（抗蝮蛇/五步蛇/银环蛇及多价）","dose":"按说明书（常为 6000–10000 U/瓶）：通常 1–2 瓶加入 250–500 mL 液体 1 h 内静滴，重症追加；具体以说明书与病情为准","note":"用药前必须皮试，阳性者脱敏注射并备肾上腺素；尽早使用（力争 2 h 内），对已发生的坏死无效","renal":"一般不减量，警惕过敏与血清病","hepatic":"遵说明书","interact":"需备好肾上腺素等过敏抢救药"},{"name":"阿莫西林克拉维酸钾/头孢曲松（咬伤后感染）","dose":"阿莫西林克拉维酸钾 625 mg 口服 bid–tid ×5–7 天；中重度：头孢曲松 1–2 g 静滴 qd 或哌拉西林-他唑巴坦 4.5 g q8h","note":"经验治疗须覆盖巴斯德菌与厌氧菌；手部深部咬伤建议静脉用药并早期专科评估","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"与华法林合用监测 INR"},{"name":"破伤风类毒素 + TIG（联合免疫）","dose":"接种史不明或 >10 年未加强：类毒素 0.5 mL 肌注；污染伤口加 TIG 250 IU 肌注（分侧）","note":"可同日与狂犬疫苗不同部位接种","renal":"遵说明书","hepatic":"遵说明书","interact":"TIG 与疫苗分开部位注射"},{"name":"抗过敏（血清病/过敏反应）","dose":"地塞米松 5–10 mg 静注或甲泼尼龙 40–80 mg 静注；严重过敏用肾上腺素 0.3–0.5 mg 肌注","note":"仅用于过敏反应或血清病，不常规用于蛇伤","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"新斯的明（部分神经毒蛇辅助）","dose":"1.5 mg 肌注或静注，按需重复，须同时准备气管插管与机械通气","note":"不能替代气道支持，呼吸肌麻痹是主要死因","renal":"肾衰延长间隔","hepatic":"遵说明书","interact":"与阿托品合用拮抗胆碱能副作用"}],"nonDrug":["所有动物咬伤：立即用肥皂水与流动清水（或生理盐水）交替冲洗至少 15 分钟，再用碘伏消毒；不缝合不包扎（头面与深部伤口可延迟一期缝合或部分缝合）","Ⅱ、Ⅲ 级暴露须伤口处理 + 全程疫苗，Ⅲ 级加 RIG；不用强酸强碱，不用嘴吸吮","手部与深层咬伤：抬高患肢，评估肌腱神经血管与关节，必要时手术探查清创与引流","蛇咬伤现场：伤肢制动平放（低于心脏），去除戒指与紧身物；禁止切开排毒、口吸、结扎、冰敷与饮酒","蛇咬伤：生理盐水冲洗伤口，大面积坏死后期清创；纠正凝血异常用新鲜冰冻血浆/血小板，急性肾损伤行血液净化","所有蛇伤观察至少 6–24 h（神经毒蛇延至 48 h），动态评估凝血与呼吸"],"life":["伤口随访 3–7 天，出现红肿热痛与分泌物及时就诊","狂犬病预防：兽医等前暴露接种，犬只免疫与登记管理","蛇伤预防：野外穿高筒靴、带手电，不徒手翻石堆草丛","蛇伤后近期避免剧烈活动，随访肾功能与凝血，警惕迟发血清病"]},"prog":"狂犬病一旦发病病死率接近 100%，规范暴露后处置可有效预防。犬猫咬伤感染率约 5%–20%，手部更高。毒蛇咬伤及时使用抗蛇毒血清者病死率约 1%–5%，神经毒蛇早期呼吸肌麻痹是主要死因。","refs":["狂犬病暴露预防处置工作规范（2023 年版）","狂犬病预防控制技术指南（中国疾控中心，2016 年版）","中国蛇伤救治指南（中华医学会急诊医学分会，2018 年）","WHO 狂犬病暴露后预防指南（2018 年）","外科学（第 9 版）·咬伤与动物伤"]}]},{"id":"breast_benign_gut","name":"乳腺良性疾病与肠道其他","rank":8,"summary":"本分片覆盖乳腺良性疾病（哺乳期炎症、囊性增生、纤维腺瘤），主线是「BI-RADS 影像分级 → 可疑结节空芯针活检 → 分层随访或手术」；三者的核心鉴别是单侧急性炎症、双侧周期性疼痛与单发无痛活动肿块。","compare":[{"diseaseId":"gs_breast_inflam","dx":"哺乳期（产后 3–4 周多见）单侧乳房红肿热痛伴发热，脓肿形成时有波动感；超声见液化区，乳汁/脓液培养多为金黄色葡萄球菌","key":"哺乳期 + 局部红肿热痛 + 波动感，超声确认后穿刺或切开引流"},{"diseaseId":"gs_breast_hyperplasia","dx":"双侧乳房胀痛与月经周期同步，触及颗粒状结节状增厚、多发且压痛，随月经变化；超声示腺体结构紊乱与囊性变，BI-RADS 2–3 类","key":"疼痛随月经周期变化，双侧多发有压痛，无固定质硬肿块"},{"diseaseId":"gs_fibroadenoma","dx":"青年女性无痛单发肿块，质韧、边界清、活动度极大；超声见椭圆形低回声、纵横比 <1、包膜完整，BI-RADS 3 类","key":"无痛 + 活动度大 + 超声椭圆边界清，BI-RADS 3 类"},{"diseaseId":"gs_peritonitis","dx":"突发持续剧烈腹痛伴全腹压痛、反跳痛与腹肌板状强直，发热、脉搏增快、白细胞升高；立位 X 线见膈下游离气体或 CT 见气体与积液","key":"板状腹 + 反跳痛 + 气腹，休克或脏器破裂须紧急探查"},{"diseaseId":"gs_small_bowel_tumor","dx":"反复脐周或右下腹痛、消瘦、贫血，可有不完全性肠梗阻或反复肠套叠；CT 小肠造影或双气囊小肠镜发现肠壁肿块，病理定类型","key":"不明原因脐周腹痛 + 贫血/消瘦，小肠镜或 CTE 找到病灶"},{"diseaseId":"gs_anal_fissure","dx":"排便时刀割样剧痛，便后短暂缓解再持续数小时，伴少量鲜红血迹；肛管后正中线见纵行溃疡，慢性者伴前哨痔与肛乳头肥大","key":"周期性便时疼痛 + 后正中线裂口 + 前哨痔（肛裂三联征）"},{"diseaseId":"gs_rectal_prolapse","dx":"排便或久站后直肠黏膜或全层自肛门脱出，初可自行还纳、后期需手托或不能还纳；蹲位用力见同心环状黏膜，常伴肛门松弛与失禁","key":"脱出物呈同心环状皱襞，蹲位用力下视诊即可确认"},{"diseaseId":"gs_liver_cyst_hemangioma","dx":"多无症状、体检发现；超声见无回声单纯囊肿或高回声血管瘤结节，增强 CT/MRI 见血管瘤自边缘结节状向心性填充","key":"无症状 + 典型影像（囊肿无回声壁薄；血管瘤渐进性向心填充）"},{"diseaseId":"gs_pancreatic_net","dx":"胰岛素瘤见空腹低血糖伴 Whipple 三联征、同步胰岛素与 C 肽不适当升高；胃泌素瘤为反复难治性多发溃疡伴腹泻、空腹胃泌素显著升高","key":"特异性激素症状 + 相应激素升高，EUS 与生长抑素受体显像定位"}],"diseases":[{"id":"gs_breast_inflam","name":"急性乳腺炎与乳腺脓肿","aka":["Acute mastitis","Lactational mastitis","Breast abscess","急性化脓性乳腺炎"],"rank":1,"basic":{"define":"哺乳期乳腺的急性化脓性感染，多见于产后 3–4 周初产妇，以乳头皲裂或乳汁淤积使金黄色葡萄球菌侵入为始；病情进展可形成乳腺脓肿，需引流。非哺乳期乳腺炎（浆细胞性、肉芽肿性）为另一类疾病。","risk":["初产妇、产后 2–6 周及产后 6 个月内","乳头皲裂或内陷畸形，婴儿含接不良","乳汁淤积（未及时排空、乳头受压、断奶过急）","乳房受压、外力撞击与个人卫生差","免疫低下、糖尿病与吸烟（非哺乳期乳腺炎相关）"],"epi":"哺乳期急性乳腺炎发生率约 3%–20%，初产妇最常见；其中约 3%–11% 进展为脓肿，多在产褥期 2–4 周。"},"patho":"乳头皲裂或乳汁淤积使乳汁成为培养基，金黄色葡萄球菌（部分产 β-内酰胺酶）经裂口沿淋巴或乳管侵入，局部充血水肿与中性粒细胞浸润。炎性渗出不吸收即液化形成脓肿，可单房或多房，位于乳晕下或乳房后间隙，向皮肤溃破可形成乳瘘。细菌与毒素入血可致全身发热与脓毒症表现。","dx":{"criteria":["哺乳期（多在产后 3–4 周）乳房胀痛、搏动性跳痛，伴畏寒发热（38–39 ℃）","局部红、肿、热、压痛，可及边界不清硬块；腋窝淋巴结肿大压痛","脓肿形成：局部出现波动感、皮肤变薄发亮、压痛集中于一点，抗菌治疗 48–72 h 后仍不消退","白细胞 >10×10^9/L、中性粒细胞比例升高，CRP 升高","脓液或乳汁培养多为金黄色葡萄球菌，反复发作需考虑 MRSA","超声：炎性期腺体回声增强血流增多，脓肿期见低回声/无回声液化区，多房者见分隔","需排除炎性乳腺癌（局部红肿弥漫、无高热、抗菌无效、穿刺见癌细胞）"],"workup":["乳腺超声首选，评估脓肿部位、大小、数量与血流（哺乳期不用钼靶作首选）","血常规、CRP、PCT；乳汁/脓液培养 + 药敏","评估乳头皲裂与婴儿含接姿势（舌系带过短等）","脓肿穿刺抽脓送检，兼诊断与治疗","反复发作或非哺乳期乳腺炎行空芯针活检排除肿瘤与炎性乳癌"],"grading":"按病程分急性炎症期（未液化）、脓肿形成期（单房/多房）与慢性瘘管期；按部位分腺叶内、乳晕下与乳房后间隙。非哺乳期乳腺炎分浆细胞性、肉芽肿性与乳晕部导管扩张。"},"ddx":[{"name":"乳腺囊性增生（同大类 gs_breast_hyperplasia）","point":"为双侧、周期性、与月经相关胀痛，无发热与红肿；乳腺炎为单侧、哺乳期、短暂病程伴炎症表现。"},{"name":"乳腺纤维腺瘤（同大类 gs_fibroadenoma）","point":"青年女性无痛、边界清、活动度大的实性肿块，无红肿与发热；乳腺炎肿块边界不清、压痛并有全身炎症反应。"},{"name":"炎性乳腺癌","point":"乳房弥漫增大伴皮肤红肿橘皮样，无高热，抗菌治疗无效，病程较长；穿刺活检见肿瘤细胞，误诊后果严重。"},{"name":"积乳囊肿","point":"乳汁淤积形成囊性肿块，轻度胀痛但无发热与明显红肿，超声为无回声，穿刺抽出乳汁样液体。"},{"name":"叶状肿瘤伴出血坏死","point":"肿块数周内迅速增大、超声见分叶与囊性裂隙，皮肤可变薄但炎症反应轻，需活检鉴别。"}],"tx":{"drug":[{"name":"头孢拉定/头孢呋辛（哺乳期首选）","dose":"头孢拉定 0.5 g 口服 q6h；或头孢呋辛酯 0.25–0.5 g 口服 bid；重症头孢呋辛钠 0.75–1.5 g 静滴 q8h，疗程 7–14 天","note":"哺乳期可用，可继续哺乳；有脓液时按药敏调整","renal":"CrCl <30 调整剂量","hepatic":"遵说明书","interact":"与口服避孕药合用降低避孕效果"},{"name":"苯唑西林（敏感金葡菌）","dose":"1–2 g 静滴 q4–6h（皮试后）","note":"用于敏感菌，注意过敏反应与静脉炎","renal":"肾功能不全延长间隔","hepatic":"遵说明书","interact":"与华法林合用延长凝血酶原时间"},{"name":"阿奇霉素/红霉素（青霉素过敏）","dose":"阿奇霉素 0.5 g 口服 qd ×3–5 天；或红霉素 0.3–0.5 g 口服 tid","note":"哺乳期一般可用，观察婴儿胃肠反应；注意 QT 间期延长","renal":"遵说明书","hepatic":"肝功能不全注意肝毒性","interact":"与华法林、地高辛合用增强作用"},{"name":"万古霉素（MRSA）","dose":"15–20 mg/kg 静滴 q12h，目标谷浓度 15–20 mg/L","note":"仅用于培养证实 MRSA 或高危重症；不能替代引流","renal":"按肌酐清除率调整并监测浓度","hepatic":"遵说明书","interact":"与氨基糖苷类、利尿剂合用肾毒性叠加"},{"name":"对乙酰氨基酚/布洛芬（退热镇痛）","dose":"对乙酰氨基酚 0.5 g 口服 q6h（≤2 g/d）；布洛芬 0.2–0.4 g 口服 tid","note":"哺乳期可用，缓解发热与胀痛，不宜长期用 NSAIDs","renal":"肾功能不全慎用 NSAIDs","hepatic":"肝功能不全限对乙酰氨基酚","interact":"NSAIDs 与抗凝药合用增加出血"},{"name":"溴隐亭（决定断奶时）","dose":"2.5 mg 口服 bid ×14 天，或卡麦角林 0.5 mg bid ×8 天","note":"仅在患者决定断奶时短期使用，不作为脓肿常规治疗","renal":"遵说明书","hepatic":"重度肝病慎用","interact":"避免与大环内酯类、氟康唑及麦角类合用"}],"nonDrug":["脓肿形成即引流：<3 cm 单房行超声引导反复穿刺抽脓；>3 cm、多房或张力性脓肿行小切口切开（放射状切口、避免经乳晕切口），置引流条每日换药","患侧继续哺乳（不影响婴儿），喂哺前热敷、喂后冷敷；排空不畅者手法挤奶或吸奶器","乳头皲裂者矫正含接姿势并涂乳头霜；托带适度，注意休息饮水","抗感染 48–72 h 无改善、持续发热或肿块增大者复查超声排查脓肿","非哺乳期浆细胞性乳腺炎需活检定性，瘘管期行病变导管切除"],"life":["正确含接乳晕、按需哺乳与及时排空，避免突然断奶","哺乳前后清洁乳头，皲裂处涂乳头霜或乳汁","出院后 1 周复诊评估肿块与伤口；产后复查时排查残存硬块","复发者行乳汁/脓液培养并评估婴儿口腔情况"]},"prog":"早期规范抗感染并充分排乳者 >90% 在 48–72 h 内缓解而不成脓肿；脓肿引流后 70%–95% 可愈合，复发率约 10%，可遗留瘢痕与局部腺体破坏，一般不影响后续哺乳。","refs":["外科学（第 9 版）·乳房疾病·急性乳腺炎","中国哺乳期急性乳腺炎诊疗专家共识（2021 年）","非哺乳期乳腺炎诊治专家共识（2022 年）","WHO 哺乳期乳腺炎管理建议（2000 年）"]},{"id":"gs_breast_hyperplasia","name":"乳腺囊性增生","aka":["Cystic hyperplasia of breast","Fibrocystic change","乳腺囊性增生病","乳腺病"],"rank":2,"basic":{"define":"乳腺主质与间质不同程度的增生及退行性变，伴导管扩张与囊肿形成，为最常见的良性乳腺病变；本质为激素依赖性改变，伴不典型增生者癌变风险增加。","risk":["20–45 岁女性，以 30–40 岁最多","初潮早、绝经晚、未育或晚育、未哺乳","长期精神紧张、压力大与睡眠不足","高脂饮食、肥胖与长期使用含雌激素制品","家族乳腺癌史，尤其伴不典型增生者"],"epi":"约 50%–70% 的育龄女性体检或影像检查可见不同程度增生，绝经后多自行缓解；不典型增生者乳腺癌风险约为普通人群的 4–5 倍。"},"patho":"雌激素与孕激素比例失调使乳腺实质增生与复旧失衡，小叶与导管上皮增生、末梢导管扩张成囊、间质纤维化伴淋巴细胞浸润。增生组织对激素波动敏感，故经前加重、经后减轻。组织学分单纯性增生、硬化性腺病与不典型增生（ADH/ALH），后者属癌前病变。","dx":{"criteria":["乳房胀痛：双侧多发，可放射至肩背腋下，与月经周期相关（经前重、经后轻）","肿块：颗粒状、结节状或条索状增厚，边界不清、质中等、压痛，与皮肤无粘连，大小随周期变化","少数有乳头溢液，多为双侧多孔清亮或淡黄色","超声：腺体结构紊乱、回声不均、片状低回声、无回声囊肿与导管扩张，多为 BI-RADS 2 类","钼靶：斑片状密度增高，单纯增生表现不典型，40 岁以上加做","诊断关键在排除瘤样肿块：可疑实性结节行空芯针活检，不典型增生须病理证实"],"workup":["乳腺超声首选，40 岁以上加钼靶，每 6–12 个月复查","BI-RADS 3 类结节 3–6 个月复查，持续存在者穿刺","BI-RADS 4 类及以上行空芯针活检，明确单纯增生、不典型增生或原位癌","乳头溢液者行乳管镜排除导管内乳头状瘤","月经紊乱或合并子宫肌瘤者转妇科评估激素状态"],"grading":"组织学：单纯性增生、硬化性腺病、不典型导管/小叶增生（癌前病变）、伴原位癌（按癌处理）。临床按 BI-RADS 2 类随访、3 类短期随访、4 类以上活检。"},"ddx":[{"name":"急性乳腺炎（同大类 gs_breast_inflam）","point":"多见于哺乳期，单侧红肿热痛伴发热与波动感；囊性增生为双侧、无红肿发热、疼痛随周期变化。"},{"name":"乳腺纤维腺瘤（同大类 gs_fibroadenoma）","point":"无痛、边界清、活动度大的单发实性肿块，超声为边界清晰椭圆形低回声；增生以疼痛与颗粒感为主、多双侧多发。"},{"name":"乳腺癌","point":"无痛单发质硬、边界不清、活动度差，可伴皮肤橘皮样与腋窝淋巴结肿大；对持续存在的实性结节必须活检。"},{"name":"乳腺导管内乳头状瘤","point":"单侧单孔血性溢液，乳管镜见导管内肿物；增生溢液多为双侧多孔透明或淡黄色。"},{"name":"积乳囊肿","point":"哺乳期或哺乳后，无回声囊性肿块，穿刺抽出乳汁样液，无周期性疼痛。"}],"tx":{"drug":[{"name":"中成药对症（乳癖消等）","dose":"遵说明书，如乳癖消片 3–5 片口服 tid，疗程 1–3 个月","note":"用于缓解周期性疼痛与结节感，个体差异大，不替代随访","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"他莫昔芬（重疼痛短期试用）","dose":"10 mg 口服 bid ×3–6 个月，仅限重度疼痛且其他治疗无效时","note":"可显著缓解疼痛，但潮热、静脉血栓与子宫内膜增生风险限制其应用","renal":"遵说明书","hepatic":"遵说明书","interact":"与华法林合用监测 INR；CYP2D6 抑制剂减弱疗效"},{"name":"达那唑（短期试用）","dose":"100–200 mg 口服 qd，短期使用，遵说明书","note":"非主流，可致脂代谢异常与肝功能损害，需监测","renal":"遵说明书","hepatic":"肝功能异常者慎用","interact":"与抗凝药、降糖药合用需调整剂量"},{"name":"布洛芬（短期缓解疼痛）","dose":"0.2–0.4 g 口服 tid，疗程 ≤7 天","note":"仅对症止痛，不改变增生进程","renal":"肾功能不全禁用","hepatic":"肝功能不全减量","interact":"与抗凝药合用增加出血"},{"name":"双氯芬酸二乙胺乳胶剂（外涂）","dose":"外涂患处一日 3–4 次，遵说明书","note":"局部应用减少全身不良反应","renal":"遵说明书","hepatic":"遵说明书","interact":"不与其他 NSAIDs 叠加使用"}],"nonDrug":["首选观察与定期随访：无确切实性肿块者每 6–12 个月超声，40 岁以上加钼靶","手术/活检指征：BI-RADS 4 类及以上、穿刺见不典型增生或原位癌、单发肿块与癌不能鉴别、乳头溢液证实导管内病变、疼痛严重影响生活且药物无效","不典型增生者与专科讨论化学预防（他莫昔芬/芳香化酶抑制剂）与强化筛查","伴月经紊乱、子宫肌瘤者转妇科评估","心理疏导，解释良性自然病程"],"life":["佩戴承托良好、无钢圈胸罩，减少压迫","低脂饮食、控制体重、限制含雌激素保健品与药物","规律作息、减压与适度运动（有助减轻周期性疼痛）","自我检查 + 每年复查，出现固定肿块、溢液或皮肤改变及时就诊"]},"prog":"单纯性增生为良性过程，绝经后多缓解，预后良好；不典型增生者乳腺癌风险升高 4–5 倍，需密切随访。约 20% 患者仍反复疼痛与结节感。","refs":["外科学（第 9 版）·乳房疾病·乳腺囊性增生","中国抗癌协会乳腺癌诊治指南与规范（2021 年版）·良性疾病部分","乳腺良性疾病诊治专家共识（2020 年）","ACOG 乳腺良性病变临床实践"]},{"id":"gs_fibroadenoma","name":"乳腺纤维腺瘤","aka":["Fibroadenoma","纤维腺瘤","乳腺纤维腺瘤"],"rank":3,"basic":{"define":"由腺上皮与纤维组织构成的乳腺良性实体肿瘤，为青年女性最常见的乳腺良性肿瘤；多数单发、生长缓慢，少数多发，青春期巨大者称幼年型纤维腺瘤。","risk":["女性 15–35 岁，以 20–25 岁高发","妊娠与哺乳期雌激素升高时可能增大","家族中有纤维腺瘤或乳腺癌史","长期服用含雌激素药物或保健品（证据有限）","肥胖与高热量饮食"],"epi":"占乳腺良性肿瘤的 70%–80%，为青年女性乳腺肿块最常见原因，约 10%–25% 为多发；绝经后多退变为硬化性结节。"},"patho":"小叶内纤维组织与腺上皮同时增生，形成含纤维与腺体两种成分的良性肿瘤，有完整包膜，质韧有弹性、活动度大。组织学分管内型、管周型与混合型，可伴黏液样变与钙化。生长依赖激素，妊娠与哺乳期可增大；少数生长迅速、体积大的叶状肿瘤曾被误称巨大纤维腺瘤，故 >5 cm 或快速生长者需病理明确。","dx":{"criteria":["青年女性乳房无痛、边界清楚、活动度大的肿块，多单发、生长缓慢","体检：表面光滑、质韧有弹性、无压痛、与皮肤及周围无粘连，推动度大","超声：形态规则（椭圆形）、边界清晰、低回声均匀、纵横比 <1、有包膜，少量或无明显血流，BI-RADS 3 类","钼靶：卵圆形或分叶状致密影、边缘光滑（绝经后可见粗大钙化）","≥3 cm、生长迅速或 BI-RADS 4 类者行空芯针活检确诊","幼年型：青春期女性肿块迅速增大至 8 cm 以上、皮肤被撑薄"],"workup":["乳腺超声为首选，>40 岁加钼靶","BI-RADS 3 类 3–6 个月复查，稳定后改为 6–12 个月随访",">3 cm、短期增长快或 BI-RADS 4 类者空芯针活检","疑叶状肿瘤者完整切除后病理 + 免疫组化（CD34、bcl-2、Ki-67）","备孕前完成穿刺评估，明确诊断后再决定是否切除"],"grading":"组织学：管内型、管周型、混合型；临床分普通型（<3 cm、生长慢）与幼年型（<20 岁、快速生长、常 >8 cm）。BI-RADS 分级指导随访或活检。"},"ddx":[{"name":"乳腺囊性增生（同大类 gs_breast_hyperplasia）","point":"增生为双侧多发颗粒感结节伴周期性胀痛；纤维腺瘤多为单发、无痛、边界清、活动度极大且不随周期变化。"},{"name":"急性乳腺炎（同大类 gs_breast_inflam）","point":"哺乳期红肿热痛伴发热与波动感，超声见液化区；纤维腺瘤无炎症表现与发热。"},{"name":"叶状肿瘤","point":"影像相似，鉴别靠生长速度与病理（分叶、间质细胞丰富、CD34 阳性）；快速增大者应完整切除。"},{"name":"乳腺癌","point":"质硬、边界不清、固定，可伴乳头改变与腋窝淋巴结；中老年出现纤维腺瘤样肿块需警惕黏液癌或髓样癌。"},{"name":"单纯囊肿","point":"超声无回声、后方回声增强，穿刺抽液后消失；纤维腺瘤为实性低回声。"},{"name":"胰腺内分泌肿瘤（乳腺良性疾病与肠道其他大类 · 同大类另一分片，gs_pancreatic_net）","point":"均为无症状或隐匿表现：pNET 以低血糖、顽固溃疡与腹泻等激素症状为主，纤维腺瘤仅为局部无痛肿块，无内分泌表现。"}],"tx":{"drug":[{"name":"无特效药物（以观察与手术为主）","dose":"无；疼痛明显可短期对乙酰氨基酚 0.5 g 口服 q6h（≤2 g/d）","note":"激素调节药不用于纤维腺瘤常规治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"术后镇痛（对乙酰氨基酚/布洛芬）","dose":"对乙酰氨基酚 0.5–1 g 口服 q6h（≤2 g/d）；布洛芬 0.3 g 口服 tid 短期","note":"日间局麻手术，多不需阿片类","renal":"肾衰慎用 NSAIDs","hepatic":"肝功能不全减量","interact":"NSAIDs 与抗凝药合用增加出血"},{"name":"围术期预防用抗菌药（仅限手术时）","dose":"头孢唑林 1 g 术前 30–60 min 静注单次；过敏者克林霉素 600–900 mg 静滴","note":"单纯肿瘤切除为清洁手术，一般不需预防用药，仅在感染高危或免疫低下时使用","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"头孢与华法林合用延长凝血酶原时间"}],"nonDrug":["随访观察（多数 <3 cm、BI-RADS 3 类且稳定者）：每 6–12 个月超声，连续 2–3 年稳定者改为定期筛查","手术指征：>3 cm 或短期增长迅速、BI-RADS 4 类或穿刺可疑、患者强烈要求、有乳腺癌家族史、备孕且肿块较大、幼年型巨大纤维腺瘤","术式：开放切除（乳晕弧形切口兼顾美容）、超声引导真空辅助旋切（≤3 cm）、微创消融（射频/冷冻）","切除标本常规送病理，术中冰冻排除叶状肿瘤","备孕前告知妊娠期可能增大"],"life":["每月自检与定期超声，关注是否快速增大","避免长期使用含雌激素保健品；哺乳期增大者及时复查","术后 1 个月、6 个月复查切口与外形；复发者可行再次局部切除","控制体重、低脂饮食与规律运动"]},"prog":"良性肿瘤，多数长期稳定或缓慢生长，部分活检确诊者在数年内可缩小或消退，恶变率极低（<0.1%）。单纯切除后局部复发 <5%，多发者可能出现新病灶，需长期随访。","refs":["外科学（第 9 版）·乳房疾病·纤维腺瘤","中国抗癌协会乳腺癌诊治指南与规范（2021 年版）","乳腺良性结节超声引导真空辅助活检专家共识（2020 年）","ACR BI-RADS 超声词典（第 2 版）"]},{"id":"gs_peritonitis","name":"急性腹膜炎","aka":["Acute peritonitis","继发性腹膜炎","自发性细菌性腹膜炎（SBP）"],"rank":1,"basic":{"define":"腹膜壁层与脏层的急性炎症。继发性由腹内脏器穿孔、破裂、缺血或感染扩散引起，最常见；原发性（SBP）指无明确腹腔感染源的腹膜炎，多见于肝硬化腹水。","risk":["消化性溃疡穿孔、阑尾穿孔、胆囊穿孔与憩室穿孔","肠梗阻绞窄与外伤致空腔脏器破裂","术后吻合口漏、肠缺血与重症胰腺炎","肝硬化腹水、肾病综合征与腹膜透析（原发性）","免疫低下、长期使用质子泵抑制剂与糖皮质激素","老年人、糖尿病者症状不典型，易延误诊断"],"epi":"继发性腹膜炎以阑尾穿孔与溃疡穿孔最常见，病死率约 5%–10%，合并感染性休克可达 20%–50%；肝硬化腹水者 SBP 年发生率约 10%–30%，住院病死率 10%–20%。"},"patho":"消化液与细菌入腹引致化学性与感染性炎症，腹膜充血水肿并渗出纤维蛋白与中性粒细胞，细菌以大肠埃希菌、肠球菌与厌氧菌为主。壁层腹膜受刺激致持续剧痛与腹肌强直。毒素入血与第三间隙丢失可迅速进展为脓毒症及器官衰竭；被大网膜包裹则形成局限性脓肿。","dx":{"criteria":["腹痛：突发持续剧烈，深呼吸咳嗽时加重，起于原发灶后扩散至全腹","典型体征：压痛、反跳痛与腹肌紧张「板状腹」三联征，腹式呼吸受限，肠鸣音减弱或消失","全身：发热 38–39 ℃、心率 >100 次/min、恶心呕吐；脓毒症时低血压与意识改变","气腹：立位胸腹片见膈下气体（溃疡穿孔约 70%–80% 阳性），CT 更敏感","腹穿抽出脓液、消化液或浑浊液诊断价值最高","SBP：腹水多形核细胞 ≥250/mm³ 即可诊断","白细胞 >12×10^9/L 或 <4×10^9/L，CRP、PCT 与乳酸升高"],"workup":["生命体征监护，评估休克与器官功能","立位胸腹片查游离气体；腹部 CT 平扫 + 增强为首选","超声筛查腹水、胆囊与阑尾区域","腹穿观察外观（脓性、胆汁样、食物残渣），送常规、生化与培养","血常规、CRP、PCT、凝血、淀粉酶/脂肪酶、肝肾功能、血气与乳酸","育龄女性查血 HCG；警惕老年与免疫抑制者「症状轻、体征重」"],"grading":"按范围分局限性与弥漫性；按病因分继发性、原发性与三发性；按严重度用 Manheim 腹膜炎指数（Ⅰ–Ⅲ 级）评估风险与病死率。"},"ddx":[{"name":"小肠肿瘤（同大类 gs_small_bowel_tumor）","point":"小肠肿瘤可致肠套叠、梗阻甚至穿孔继发腹膜炎，但有反复脐周痛、消瘦与不完全梗阻前驱表现，需 CT 与病理明确原发灶。"},{"name":"肛裂（同大类 gs_anal_fissure）","point":"继发性肛裂伴局限性肛周感染可致全身发热，但病变局限在肛门周围，无全腹压痛与板状腹；腹膜炎的体征以腹部为主。"},{"name":"乳腺疾病（乳腺良性疾病与肠道其他大类 · 另一分片，gs_breast_inflam 等）","point":"哺乳期乳腺脓肿可伴高热与白细胞升高，但腹痛与腹膜刺激征缺如；腹膜炎的定位体征在腹部，两者以查体与超声鉴别。"},{"name":"急性肠梗阻（急腹症大类 gs_bowel_obst）","point":"阵发性绞痛、呕吐、腹胀与停止排气排便，可见肠型与气过水声、肠鸣音亢进；腹膜炎腹膜刺激征重、肠鸣音消失。绞窄后可转为腹膜炎。"},{"name":"急性阑尾炎（急腹症大类 gs_append）","point":"疼痛自脐周转移至右下腹、麦氏点压痛，腹膜刺激征局限；弥漫性腹膜炎为全腹板状腹、伴明显毒血症。"},{"name":"急性胰腺炎（重症）","point":"持续性上腹痛向背部放射，血淀粉酶/脂肪酶 >3 倍上限，早期腹膜刺激征轻；出血坏死型需 CT 评估。"}],"tx":{"drug":[{"name":"头孢曲松/头孢噻肟 + 甲硝唑（社区获得性）","dose":"头孢曲松 2 g 静滴 qd（或头孢噻肟 2 g q8h）+ 甲硝唑 0.5 g 静滴 q8h，疗程 5–7 天","note":"适用于社区获得性轻中度继发性腹膜炎，明确病原后降阶梯；手术引流是治愈关键","renal":"甲硝唑 CrCl <30 减量；头孢曲松遵说明书","hepatic":"头孢曲松重度肝病慎用；甲硝唑重度肝病减量","interact":"头孢曲松与含钙输液同瓶可沉淀；甲硝唑禁酒"},{"name":"哌拉西林-他唑巴坦/美罗培南（重症/医院获得性）","dose":"哌拉西林-他唑巴坦 4.5 g 静滴 q6–8h；或美罗培南 1 g 静滴 q8h，按培养与效果调整疗程","note":"覆盖革兰阴性菌与厌氧菌，医院获得性或耐药史者首选碳青霉烯类","renal":"哌拉西林-他唑巴坦 CrCl <40 延长间隔；美罗培南 CrCl <50 减量","hepatic":"遵说明书","interact":"美罗培南显著降低丙戊酸浓度，避免合用"},{"name":"万古霉素（MRSA 高危）","dose":"15–20 mg/kg 静滴 q12h，目标谷浓度 15–20 mg/L","note":"仅限 MRSA 定植、长期住院或危重者经验覆盖，非常规使用","renal":"按肌酐清除率调整并监测血药浓度","hepatic":"遵说明书","interact":"与氨基糖苷类、利尿剂合用增加肾毒性"},{"name":"头孢曲松 + 人血白蛋白（SBP）","dose":"头孢曲松 2 g 静滴 qd ×5–7 天；白蛋白 1.5 g/kg 第 1 天、1 g/kg 第 3 天静滴（肾功能不全或胆红素 >4 mg/dL 者）","note":"白蛋白减少肾衰竭与病死，为 SBP 标准辅助治疗","renal":"白蛋白不需调整；头孢曲松遵说明书","hepatic":"遵说明书","interact":"白蛋白可影响部分药物分布"},{"name":"诺氟沙星（SBP 二级预防）","dose":"400 mg 口服 qd，长期使用","note":"SBP 恢复后即开始预防，注意细菌耐药","renal":"CrCl <30 减量","hepatic":"慎用","interact":"与含铝镁抗酸剂、口服铁剂间隔 2 h"},{"name":"液体复苏与去甲肾上腺素（脓毒症）","dose":"晶体液 30 mL/kg 起始复苏，去甲肾上腺素 0.05–1 µg/kg/min 泵入维持 MAP ≥65 mmHg","note":"腹膜渗出致大量第三间隙丢失，术后需继续补液并监测乳酸与尿量","renal":"监测尿量","hepatic":"遵说明书","interact":"与β受体阻滞剂合用减弱升压"},{"name":"阿片类镇痛（术前谨慎）","dose":"吗啡 2–5 mg 静注或羟考酮 5–10 mg 口服，按需滴定","note":"适度镇痛改善配合度，但不得掩盖病情；疑诊腹膜炎应尽快手术","renal":"肾衰者代谢产物蓄积，减量","hepatic":"肝功能不全减量","interact":"与镇静药合用加重呼吸抑制"}],"nonDrug":["探查指征：穿孔、脏器破裂或肠绞窄；明确气腹；腹穿抽出脓性或消化液；保守 6–8 h 恶化","术式：剖腹探查处理原发病灶，温生理盐水冲洗 3–5 L 并放置引流；污染重者分期手术","非手术：原发性腹膜炎以抗感染为主；体征轻且无穿孔证据者可监护下保守","禁食、胃肠减压、留置导尿，纠正水电解质失衡；肠内营养、血栓预防与早期活动","SBP 72 h 无改善复查腹水并升级抗菌"],"life":["术后 5–10 天发热须查残余脓肿与肠瘘；早期肠内营养、下床活动以防肺炎与血栓","溃疡穿孔者术后根除幽门螺杆菌并维持 PPI；肝硬化腹水者长期预防 SBP"]},"prog":"继发性腹膜炎病死率约 5%–10%，合并感染性休克者可达 20%–50%，取决于原发病、控制时间与器官功能；术后残余脓肿约 5%–15%。SBP 治疗后 6 个月复发率 40%–70%，预防可降低再发。","refs":["外科学（第 9 版）·腹膜炎与腹腔感染","中国腹腔感染诊治指南（2019 年版）","WSES 腹膜炎与腹腔脓毒症管理指南（2021 年）","肝硬化腹水及自发性细菌性腹膜炎管理指南（中华医学会肝病学分会）"]},{"id":"gs_small_bowel_tumor","name":"小肠肿瘤（腺癌/间质瘤/淋巴瘤/类癌）","aka":["Small bowel tumor","小肠恶性肿瘤","Small intestinal malignancy"],"rank":2,"basic":{"define":"发生于十二指肠、空肠与回肠的肿瘤，以恶性为主；常见类型为腺癌、胃肠间质瘤（GIST）、淋巴瘤与神经内分泌肿瘤（类癌），常以小肠梗阻、出血或穿孔被发现。","risk":["克罗恩病、乳糜泻与 Lynch 综合征、家族性腺瘤性息肉病","免疫缺陷、自身免疫病或 EBV 感染（肠道淋巴瘤相关）","吸烟、饮酒与高脂饮食","腺癌与 GIST 多见于 40–70 岁，类癌 50–60 岁","回盲部慢性炎症（淋巴瘤）"],"epi":"小肠恶性肿瘤仅占消化道恶性肿瘤的 1%–3%，因检查受限常延误诊断；我国以腺癌最常见，其次为淋巴瘤与 GIST，回肠末端为淋巴瘤好发部位。"},"patho":"腺癌起自黏膜上皮，多呈环形狭窄致梗阻。GIST 源于 Cajal 间质细胞，外生生长、易出血坏死与播散，多伴 c-KIT/PDGFRA 突变。淋巴瘤多致肠段膨隆、穿孔与出血。类癌分泌 5-HT，肝转移后出现类癌综合征。","dx":{"criteria":["不明原因反复脐周或右下腹痛、腹胀伴体重下降，易误诊为胃肠功能紊乱","消化道出血：隐匿者以缺铁性贫血为主，显性者黑便或便血；可反复小肠梗阻或肠套叠","类癌综合征：皮肤潮红、腹泻、哮喘与右心瓣膜病","实验室：缺铁性贫血、粪隐血阳性；CgA 升高提示类癌，AFP/CEA/CA19-9 特异性差","CT/CTE 见肠壁增厚、肿块、靶征或肠套叠；双气囊小肠镜或胶囊内镜定位活检","免疫组化定类型：腺癌 CK20/CDX2；GIST CD117 与 DOG1 阳性；淋巴瘤 CD20/CD3/EBER；神经内分泌 Syn、CgA 阳性"],"workup":["全腹增强 CT + CTE；PET-CT 用于淋巴瘤与 GIST 分期","双气囊小肠镜或胶囊内镜（疑梗阻者先排除狭窄）并活检","十二指肠肿瘤行胃镜与超声内镜评估浸润深度","血常规、铁代谢、肝肾功能与标志物；类癌行 68Ga-DOTATATE PET","GIST 行基因检测（c-KIT 外显子 9/11/13/17、PDGFRA D842V）","淋巴瘤行骨髓活检与 Lugano 分期；评估营养并纠正贫血低蛋白"],"grading":"腺癌按 AJCC 第 8 版 TNM；GIST 按改良 NIH 危险度（大小 + 核分裂象）；淋巴瘤按 Lugano 分期；神经内分泌肿瘤按 TNM 与 Ki-67 分 G1（<3%）/G2（3%–20%）/G3（>20%）。"},"ddx":[{"name":"急性腹膜炎（同大类 gs_peritonitis）","point":"肿瘤穿孔或梗阻绞窄可继发腹膜炎，但多有前驱消瘦与反复腹痛史，需 CT 与病理找到原发灶。"},{"name":"肝囊肿与肝血管瘤（同大类 gs_liver_cyst_hemangioma）","point":"类癌及神经内分泌肿瘤肝转移在影像上可为富血供结节，与血管瘤易混；前者伴 CgA 升高、类癌综合征与原发小肠病灶。"},{"name":"克罗恩病","point":"也表现腹痛、腹泻、贫血与梗阻，内镜见纵行溃疡与鹅卵石样改变、病理见非干酪样肉芽肿；肿瘤多为中老年、病程短且进行性加重。"},{"name":"肠结核","point":"好发回盲部，低热、盗汗与腹泻便秘交替，活检见抗酸杆菌或肉芽肿，与淋巴瘤需病理鉴别。"},{"name":"粘连性肠梗阻","point":"有腹部手术史，CT 见移行带无肿块，减压抗炎后可缓解；肿瘤性梗阻常进行性加重伴贫血消瘦。"},{"name":"急性肠梗阻（急腹症大类 gs_bowel_obst）","point":"急性起病的机械性梗阻以绞痛与肠鸣音亢进为主，反复发作且伴消瘦贫血者应警惕肿瘤所致。"}],"tx":{"drug":[{"name":"伊马替尼（GIST）","dose":"400 mg 口服 qd；c-KIT 外显子 9 突变 800 mg/d；高危者术后辅助 3 年","note":"可作术前新辅助缩小肿瘤后手术；监测血常规、肝功能与体液潴留；PDGFRA D842V 突变不敏感","renal":"遵说明书","hepatic":"肝功能不全减量并监测","interact":"CYP3A4 强抑制剂升高浓度；质子泵抑制剂降低吸收"},{"name":"舒尼替尼（伊马替尼耐药 GIST）","dose":"50 mg 口服 qd 服 4 周停 2 周，或 37.5 mg qd 连续","note":"监测高血压、手足皮肤反应与甲状腺功能减退","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"CYP3A4 抑制剂增加暴露"},{"name":"R-CHOP（小肠 B 细胞淋巴瘤）","dose":"利妥昔单抗 375 mg/m² d1 + 环磷酰胺 750 mg/m² + 多柔比星 50 mg/m² + 长春新碱 1.4 mg/m²（≤2 mg）+ 泼尼松 100 mg d1–5，q21d ×6–8 周期","note":"注意肠穿孔风险与肿瘤溶解综合征；蒽环类有累积心脏毒性","renal":"CrCl <30 调整环磷酰胺","hepatic":"肝功能不全调整长春新碱与多柔比星","interact":"长春新碱经 CYP3A4 代谢，与唑类抗真菌药合用需谨慎"},{"name":"奥曲肽（类癌综合征）","dose":"奥曲肽 50–100 µg 皮下 q8h 起始，按症状调整；长效奥曲肽 20–30 mg 肌注 q4 周","note":"治疗前 24–48 h 不宜突然停药以免症状反跳；注意胆结石与血糖异常","renal":"遵说明书","hepatic":"重度肝病延长间隔","interact":"与胰岛素、磺脲类合用可加重低血糖"},{"name":"依维莫司（进展期 NET）","dose":"10 mg 口服 qd，联合长效奥曲肽","note":"用于进展期分化良好 NET；口腔炎、感染与代谢异常需监测","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂/诱导剂显著影响浓度；避免活疫苗"},{"name":"FOLFOX（腺癌化疗）","dose":"奥沙利铂 85 mg/m² + 亚叶酸钙 400 mg/m² + 5-FU 400 mg/m² 静注后 2400 mg/m² 持续 46 h，q14d","note":"小肠腺癌化疗证据有限，多参照结直肠癌，用于淋巴结阳性辅助或晚期","renal":"CrCl <30 调整 5-FU","hepatic":"肝功能不全调整 5-FU","interact":"5-FU 与华法林合用显著延长 INR"}],"nonDrug":["局限腺癌行肠段切除 + 淋巴结清扫；GIST 完整切除（R0、避免破裂），高危者术后伊马替尼辅助","梗阻/穿孔急诊切除病变肠段并吻合或造口，无法切除者行旁路手术","十二指肠肿瘤按部位行胰十二指肠切除、局部切除或节段切除","淋巴瘤以化疗为主，合并出血、梗阻或穿孔时手术；类癌切除原发灶，肝转移行消融或栓塞","梗阻与营养不良者肠外营养；MDT 制定分期治疗"],"life":["腺癌 2 年内每 3–6 个月查标志物与 CT；GIST 高危者随访 5–10 年","类癌避酒精与情绪应激；贫血者补铁；造口患者行护理培训"]},"prog":"小肠腺癌 5 年生存率约 30%，可切除者 50%–60%；局限 GIST 完整切除后 5 年生存 >70%，高危者辅助伊马替尼改善无复发生存；小肠 B 细胞淋巴瘤 5 年生存约 50%–60%；类癌生长缓慢，肝转移者中位生存 5–8 年。","refs":["外科学（第 9 版）·小肠疾病·小肠肿瘤","中国胃肠间质瘤诊断治疗共识（2021 年版）","CSCO 胃肠间质瘤诊疗指南（2022 年）","中国胃肠胰神经内分泌肿瘤专家共识（2021 年）"]},{"id":"gs_anal_fissure","name":"肛裂","aka":["Anal fissure","肛管溃疡","裂肛"],"rank":1,"basic":{"define":"齿状线以下肛管皮肤纵行裂开形成的小溃疡，多位于肛管后正中线；以周期性排便疼痛与少量便血为特征。分急性（<6 周、创面浅）与慢性（>6 周、瘢痕化伴前哨痔与肛乳头肥大）。","risk":["大便干燥便秘与排便机械性损伤（最常见）","长期腹泻或排便次数过多","分娩致肛门损伤（产妇高发）；肛窦炎等局部炎症","克罗恩病、结核、肿瘤等继发性病因"],"epi":"肛裂为肛肠科第二常见疾病，多见于 20–40 岁青壮年，约 90% 位于肛管后正中线，女性产后多见。"},"patho":"干硬粪便撕裂肛管皮肤，后正中线括约肌张力高、血供差（直肠下动脉终末支），裂伤后易缺血难愈。疼痛引发内括约肌痉挛，痉挛加重缺血与疼痛，形成恶性循环。慢性化后创缘增厚瘢痕化，下端形成前哨痔、上端形成肛乳头肥大，即肛裂三联征。","dx":{"criteria":["周期性疼痛：排便时如刀割样剧痛，便后短暂缓解（间歇期），随后因括约肌痉挛再痛数十分钟至数小时","便血：量少、鲜红，附着粪便表面或便纸染血，不与粪便混合","便秘为诱因也是结果，患者因惧痛减少排便","肛门视诊（轻轻分开臀沟）：后正中线纵行裂口，急性期创缘整齐色红，慢性期创缘增厚发白、基底可见内括约肌纤维","慢性肛裂三联征：肛裂 + 前哨痔 + 肛乳头肥大","侧方或多发裂口、边缘硬化、伴脓性分泌物时警惕克罗恩病、结核、梅毒或肿瘤"],"workup":["问诊疼痛周期与排便习惯；急性剧痛期不做指检或肛镜","视诊评估裂口位置形态，侧方裂口须排除克罗恩病","慢性难治或疑继发者行直肠镜/全结肠镜排除克罗恩病与直肠癌","边缘硬化或治疗无效者行局部活检；有脓性分泌物者行肛周超声或 MRI"],"grading":"按病程分急性肛裂（<6 周、创面新鲜）与慢性肛裂（≥6 周、瘢痕化伴前哨痔）；按病因分原发性（便秘相关）与继发性（克罗恩病、结核、肿瘤等）。"},"ddx":[{"name":"直肠脱垂（同大类 gs_rectal_prolapse）","point":"脱垂以肿物自肛门脱出为核心、多无明显疼痛；肛裂为便时刀割样剧痛伴少量鲜血，视诊见肛管裂口而无黏膜脱出。"},{"name":"肝囊肿与肝血管瘤（同大类 gs_liver_cyst_hemangioma）","point":"均为偶发或隐匿表现：肝脏病灶无肛门症状与便血，经超声定位；肛裂的疼痛与排便明确相关，二者不会混淆，但体检同时发现肝囊肿时勿将腹痛归因于囊肿。"},{"name":"血栓性外痔（疝与肛肠大类 gs_hemorrhoid）","point":"肛旁突然出现圆形紫暗肿物、持续剧痛且触痛明显，为血栓形成；肛裂疼痛与排便相关呈周期性，裂口位于后正中线。"},{"name":"肛周脓肿/肛瘘","point":"持续性跳痛伴发热、局部波动感与脓性分泌物；肛裂为周期性便时疼痛、无波动感。"},{"name":"肛管/直肠下段肿瘤","point":"溃疡不规则、质硬易出血，伴排便习惯改变与黏液血便，需活检；年龄大、边缘硬化者尤应警惕。"},{"name":"克罗恩病肛周病变","point":"裂口多位于侧方、多发，常伴瘘管与皮赘，疼痛不明显，伴腹痛腹泻；内镜与病理可确诊。"}],"tx":{"drug":[{"name":"硝酸甘油软膏（0.2%–0.4%）","dose":"约 0.5 g 涂于肛管裂口及下段，一日 2 次，疗程 4–8 周","note":"松弛内括约肌改善血供；头痛最常见（约 30%–50%），用药前告知；孕妇慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"禁与 PDE5 抑制剂及硝酸酯类合用，可致严重低血压"},{"name":"地尔硫䓬软膏（2%）","dose":"局部外用一日 2–3 次，疗程 4–8 周","note":"硝酸甘油不耐受者的替代；降压药使用者注意血压","renal":"遵说明书","hepatic":"遵说明书","interact":"与β阻滞剂、地高辛合用注意心动过缓与传导阻滞"},{"name":"肉毒杆菌毒素 A（局部注射）","dose":"每侧内括约肌 10–25 U，共 20–50 U，必要时 2–3 个月后重复","note":"一线药物无效的慢性肛裂，疗效约 60%–80%；可有一过性气体失禁，多可恢复","renal":"遵说明书","hepatic":"遵说明书","interact":"与氨基糖苷类合用可增强神经肌肉阻滞"},{"name":"乳果糖/聚卡波非钙（改善便秘）","dose":"乳果糖 15–30 mL 口服 qd；聚卡波非钙 1 g 口服 tid，充分饮水","note":"纠正便秘是预防复发的基础，疗程按排便情况长期调整","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他口服药间隔 1–2 h"},{"name":"甲硝唑（合并感染时）","dose":"0.4 g 口服 tid ×5–7 天","note":"单纯肛裂不需抗菌，仅合并感染或术后使用","renal":"CrCl <30 减量","hepatic":"重度肝病减量","interact":"禁酒；与华法林合用监测 INR"},{"name":"镇痛（对乙酰氨基酚，短期）","dose":"0.5 g 口服 q6h（≤2 g/d），或局麻药膏外用","note":"避免使用致便秘的强效止痛药","renal":"遵说明书","hepatic":"肝功能不全 ≤2 g/d","interact":"遵说明书"}],"nonDrug":["急性肛裂：保守治疗为主（治愈率约 80%–90%），膳食纤维 25–30 g/d、足量饮水、40 ℃ 温水坐浴每次 10–15 min，每日 2–3 次","药物 4–8 周无效行侧方内括约肌切开术（LIS），成功率 >90%，失禁风险 3%–10% 需术前告知","肛裂切除术 + 内括约肌切断：适用于合并前哨痔、肛乳头肥大或瘢痕化者","肛门扩张术失禁率高，已不推荐；继发性肛裂以治疗原发病为主","术后保持排便通畅、坐浴换药，多 1–2 周恢复"],"life":["定时排便、勿久蹲；多纤维素多饮水，少辛辣酒精","便后温水坐浴；术后 2–4 周复查，持续疼痛或失禁需复诊"]},"prog":"急性肛裂保守治疗 80%–90% 可愈合；慢性肛裂药物治愈率 50%–70%；侧方内括约肌切开成功率 >90%，失禁多为暂时性。复发率约 5%–10%，与便秘持续相关。","refs":["外科学（第 9 版）·肛管直肠疾病·肛裂","中国肛裂诊疗指南（2021 年版）","ASCRS 肛裂临床实践指南（2022 年）","中国慢性便秘诊治指南（2019 年）"]},{"id":"gs_rectal_prolapse","name":"直肠脱垂","aka":["Rectal prolapse","脱肛","完全性直肠脱垂"],"rank":2,"basic":{"define":"肛管、直肠黏膜或直肠全层向下移位脱出肛门外；仅黏膜脱出为不完全性脱垂，全层脱出为完全性脱垂（脱肛）。多见于老年人（女性）、儿童与体弱者，常伴盆底功能障碍和便秘。","risk":["老年人（女性患病率约为男性 6 倍）与多产妇盆底肌松弛","慢性便秘、慢性咳嗽、前列腺增生等使腹压长期增高","长期腹泻、寄生虫与营养不良；儿童发育不良与括约肌松弛","神经系统疾病（脊髓损伤）与长期卧床"],"epi":"成人以女性多见（约占 80%–90%），好发 40 岁以上；儿童 1–3 岁多见，多可随发育自愈。随人口老龄化患病率上升。"},"patho":"主要机制为滑动性疝学说（Douglas 窝过深、直肠陷入疝囊）与肠套叠学说，常并存盆底筋膜松弛与肛提肌分离。全层脱垂时黏膜摩擦致溃疡出血，反复脱出牵拉括约肌致失禁；脱出肠段可嵌顿绞窄。","dx":{"criteria":["初期排便时肿物自肛门脱出，便后可自行回纳","发展期需手助回纳，咳嗽、用力或久站即可脱出","后期不排便也脱出，无法回纳或反复嵌顿，伴黏液分泌物与里急后重","外观：完全性脱垂呈同心环状皱襞的圆柱状脱出（可达数厘米至 10 cm 以上）；不完全性为部分黏膜外翻、表面放射状红绒样","蹲位用力或排便后视诊最易发现；伴肛门括约肌松弛、肛管收缩力下降","可伴黏膜溃疡与出血","合并便秘者常有排便困难与手助排便"],"workup":["蹲位排便后视诊与指诊，评估脱出长度、黏膜形态与括约肌张力","直肠镜或乙状结肠镜排除肿瘤、息肉与炎症；便秘者行结肠传输试验","排粪造影与动态 MRI 评估直肠套叠、盆底下降与直肠前突","肛门直肠测压评估括约肌功能（术前必要）；女性评估盆腔器官脱垂"],"grading":"按脱出程度：Ⅰ 度（不全脱垂）；Ⅱ 度（全层脱出、便后自行回纳）；Ⅲ 度（全层脱出、需手托回纳或不能回纳，伴失禁）。"},"ddx":[{"name":"肛裂（同大类 gs_anal_fissure）","point":"肛裂以排便剧痛与少量鲜血为表现，无肿物脱出；脱肛以肿物脱出为主、疼痛不显著，呈环形黏膜。"},{"name":"肝囊肿与肝血管瘤（同大类 gs_liver_cyst_hemangioma）","point":"二者均多无腹痛；肝脏病灶见于右上腹、经影像发现，与肛门脱出无关，需避免将排便不适归因于囊肿。"},{"name":"内痔脱出（疝与肛肠大类 gs_hemorrhoid）","point":"内痔脱出物为暗红分叶状痔核（放射状）；完全性脱垂为同心环状皱襞、表面黏膜淡红，脱出较长。"},{"name":"直肠息肉/肿瘤","point":"肿物局限、带蒂或广基，表面不规则，伴黏液血便与里急后重；需内镜与活检鉴别。"},{"name":"肠套叠","point":"儿童急性发病，阵发性哭闹、果酱样便与腹部包块；直肠脱垂为慢性无痛性脱出。"},{"name":"阴道/子宫黏膜脱垂","point":"女性盆腔器官脱垂为阴道外肿物，需妇科检查鉴别。"}],"tx":{"drug":[{"name":"聚乙二醇/乳果糖（便秘治疗）","dose":"聚乙二醇 4000 散剂 10–20 g 口服 qd；乳果糖 15–30 mL qd，按排便调整","note":"纠正便秘可减少腹压与脱出，需长期维持","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他口服药间隔 1–2 h"},{"name":"琥珀酸亚铁（贫血）","dose":"0.1–0.2 g 口服 tid，餐后服；必要时静脉补铁","note":"长期脱出伴溃疡出血可致缺铁性贫血","renal":"遵说明书","hepatic":"遵说明书","interact":"与喹诺酮类、四环素间隔 2 h 以上"},{"name":"补中益气丸（中医辅助）","dose":"6–9 g 口服 bid–tid，遵说明书","note":"气虚下陷证辅助治疗，不替代手术","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"术后镇痛与通便","dose":"对乙酰氨基酚 0.5–1 g 口服 q6h（≤2 g/d）；乳果糖 15–30 mL qd","note":"术后尽早通便以减少复发，避免排便用力","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"NSAIDs 与抗凝药合用需监测"},{"name":"围术期预防用抗菌药","dose":"头孢唑林 1–2 g 术前 30–60 min 静注 + 甲硝唑 0.5 g 静滴，术后不超过 24 h","note":"经会阴手术为清洁-污染手术，预防可降低感染","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"甲硝唑禁酒"}],"nonDrug":["儿童：保守为主（纠正便秘、排便训练、硬化剂注射），多随发育自愈","成人 Ⅰ/Ⅱ 度：改善排便习惯 + 提肛训练；Ⅲ 度、保守无效或伴失禁者手术","经会阴：Delorme 术（黏膜袖状切除 + 括约肌折叠），适用于高龄或不能耐受经腹手术者；Altemeier 术（经会阴乙状结肠直肠切除吻合），用于脱出长段或嵌顿","经腹直肠固定术 ± 乙状结肠切除，复发率低但需较好耐受；老年体弱者可注射硬化剂","女性合并盆腔器官脱垂者同期行盆底重建","术后 6–8 周禁止排便用力与重体力活动"],"life":["定时排便、保持粪便软化；提肛运动每次 10–15 次、每日 3 次","治疗慢性咳嗽与前列腺增生以减少腹压；术后 3、6、12 个月复查"]},"prog":"儿童经保守多可自愈；成人手术成功率 80%–95%，复发率 5%–20%（经会阴术式较高）。术后大便失禁改善率 50%–80%，便秘改善常不完全。嵌顿未及时处理可致肠坏死与穿孔。","refs":["外科学（第 9 版）·直肠肛管疾病·直肠脱垂","中国直肠脱垂诊治专家共识（2022 年）","ASCRS 直肠脱垂临床实践指南（2017 年）","中国成人便秘诊治指南（2019 年）"]},{"id":"gs_liver_cyst_hemangioma","name":"肝囊肿与肝血管瘤","aka":["Hepatic cyst","Hepatic hemangioma","肝海绵状血管瘤","多囊肝"],"rank":3,"basic":{"define":"肝囊肿为肝内封闭的液体腔，多为先天性肝内胆管发育异常（单纯性囊肿），少数为寄生虫性或肿瘤性；肝血管瘤为最常见的肝脏良性血管性肿瘤，多数无症状，仅少数巨大者有压迫或破裂风险。","risk":["先天性：女性多见，多囊肝/多囊肾家族史（ADPLD/ADPKD）","30–60 岁女性高发；囊肿合并感染或出血时急性发病","肝血管瘤多见于 30–50 岁女性，与雌激素暴露可能相关","寄生虫性囊肿：牧区生活或犬羊接触史（棘球蚴病）"],"epi":"成人超声单纯性肝囊肿检出率约 1%–5%，女性居多；肝血管瘤是最常见良性肝肿瘤，尸检发现率 0.4%–20%，多 <4 cm 且多为单发。肝包虫病在牧区仍有散在发病。"},"patho":"单纯性囊肿为胚胎期胆管板发育异常致肝内胆管闭塞扩张，内衬胆管上皮、囊液清亮、不与胆管相通；增大时压迫邻近脏器致胀痛。血管瘤由扩张的海绵状血管腔与纤维间隔构成、血流缓慢，极少破裂。棘球蚴形成双层囊壁的包虫囊，破裂可致过敏性休克与腹腔种植。","dx":{"criteria":["多数无症状，体检超声发现","肝囊肿：增大者右上腹隐痛、胀满、餐后饱胀；超声见无回声区、边界清晰、壁薄光滑、后方回声增强，无分隔为单纯性囊肿","囊肿合并感染：发热、局部疼痛压痛、白细胞升高，囊内呈混浊回声","肝血管瘤：多为女性、<4 cm 无症状；超声为高回声、边界清楚均匀的团块；增强 CT 动脉期周边结节状强化、门脉期向中心填充，MRI T2 呈极高信号（灯泡征）","肝包虫：流行区居住史，超声见囊内分隔或囊中囊（车轮状），血清学抗体阳性","肿瘤标志物 AFP、CEA、CA19-9 阴性有助排除恶性"],"workup":["超声首选，每 6–12 个月随访大小变化","增强 CT/MRI 明确性质，尤其病灶 >4 cm 或影像不典型；MRI T2 极亮对血管瘤敏感","流行区者查包虫抗体与补体结合试验；肝功能与凝血评估手术耐受性"],"grading":"肝囊肿按大小分 <5 cm、5–10 cm、>10 cm；按病理分单纯性、多囊性、潴留性、肿瘤性（囊腺瘤/癌）与寄生虫性。血管瘤按 <4 cm、4–10 cm 与 >10 cm（巨大）分型。"},"ddx":[{"name":"肛裂（同大类 gs_anal_fissure）","point":"肛裂有明确周期性肛门痛与便血；肝脏病灶无肛门症状，诊断靠超声与增强影像。二者可在同一患者并存，腹痛归因须谨慎。"},{"name":"直肠脱垂（同大类 gs_rectal_prolapse）","point":"脱垂为肛门肿物与便秘相关；巨大肝囊肿可致腹胀但无肛门外翻，CT 见肝内液性灶。"},{"name":"肝细胞癌（消化道肿瘤大类 gs_hcc）","point":"多有乙肝或肝硬化背景，AFP 升高，增强 CT 呈快进快出，可伴坏死囊变；血管瘤呈渐进性向心填充，囊壁无强化。"},{"name":"肝脓肿（门静脉高压与脾脏大类 gs_liver_abscess）","point":"发热寒战、肝区叩击痛，超声见厚壁混杂回声与液平，白细胞与 CRP 明显升高；单纯囊肿无炎症表现。"},{"name":"肝囊腺瘤/囊腺癌","point":"囊壁厚而不规则、内有分隔与壁结节、可有钙化且进行性增大；单纯囊肿壁薄无实质成分强化。"},{"name":"转移性肝癌","point":"多发、有原发肿瘤史，呈牛眼征与边缘强化；必要时穿刺活检。"}],"tx":{"drug":[{"name":"无特效药物（随访与手术为主）","dose":"无；疼痛可用对乙酰氨基酚 0.5 g 口服 q6h（≤2 g/d）","note":"无药物可使囊肿或血管瘤缩小，不建议激素类或促性腺激素调节药","renal":"遵说明书","hepatic":"肝功能不全对乙酰氨基酚 ≤2 g/d","interact":"遵说明书"},{"name":"头孢曲松 + 甲硝唑（囊肿感染）","dose":"头孢曲松 2 g 静滴 qd + 甲硝唑 0.5 g 静滴 q8h，后依培养调整，疗程 2–4 周或更长","note":"囊肿感染需穿刺引流 + 抗感染联合","renal":"甲硝唑 CrCl <30 减量","hepatic":"头孢曲松重度肝病慎用","interact":"头孢曲松与含钙输液同瓶可沉淀"},{"name":"阿苯达唑（肝包虫）","dose":"10–15 mg/kg/d 分 2 次口服，疗程 3–6 个月，遵说明书","note":"用于不宜手术或围手术期辅助；监测肝功能与血常规（骨髓抑制）","renal":"遵说明书","hepatic":"肝功能异常者慎用","interact":"与地塞米松合用升高血药浓度"}],"nonDrug":["随访观察首选：无症状单纯囊肿 <10 cm 与稳定的血管瘤每 6–12 个月超声复查","肝囊肿手术指征：>10 cm 或进行性增大伴症状、合并感染出血破裂、可疑恶变；腹腔镜去顶开窗术为首选，感染时切开引流，老年 5–10 cm 单发者可穿刺 + 无水乙醇硬化","肝血管瘤手术指征：进行性增大 >10 cm 或出现症状（压迫、被膜牵拉痛）、破裂出血、不能排除恶性、合并 Kasabach-Merritt 综合征；以局部/肝段切除或射频消融为主","肝包虫病行囊肿摘除或肝部分切除，术中高渗盐水灭活防止囊液外溢，围术期抗寄生虫治疗","多囊肝终末期考虑肝移植"],"life":["血管瘤每 1–2 年、囊肿每年超声随访；巨大血管瘤避免右腹撞击与穿刺","妊娠或口服避孕药期间复查；术后随访肝功能与影像"]},"prog":"单纯性囊肿与无症状血管瘤预后良好，绝大多数无需治疗；血管瘤自发性破裂风险极低（<0.1%）。囊肿去顶术后症状缓解率 80%–95%，复发率 10%–20%；巨大血管瘤切除后罕见复发。","refs":["外科学（第 9 版）·肝疾病·肝囊肿与肝血管瘤","中国肝血管瘤诊断和治疗专家共识（2021 年）","肝囊肿诊治专家共识（2019 年）","肝棘球蚴病诊疗指南（WHO 2010 年，国内 2018 年）"]},{"id":"gs_pancreatic_net","name":"胰腺内分泌肿瘤","aka":["Pancreatic neuroendocrine tumor","pNET","功能性胰腺神经内分泌肿瘤"],"rank":4,"basic":{"define":"起源于胰岛细胞的肿瘤，分功能性（分泌过量激素引起典型综合征）与无功能性（多无症状或占位表现）。最常见的功能性类型为胰岛素瘤与胃泌素瘤，另可见胰高血糖素瘤、VIP 瘤与生长抑素瘤。","risk":["多发性内分泌腺瘤病 1 型（MEN1）：甲状旁腺功能亢进 + 胰岛细胞瘤（多为胃泌素瘤）","家族性胃泌素瘤与 Von Hippel-Lindau 病","散发病例以 40–70 岁多见，无功能性者稍晚","长期质子泵抑制剂使用可掩盖胃泌素瘤症状而延误诊断"],"epi":"我国胰腺神经内分泌肿瘤年发病率约 0.5/10 万且逐年上升；胰岛素瘤占功能性肿瘤约 70%，最常见，胃泌素瘤次之；约 10%–20% 与遗传综合征相关（以 MEN1 为主）。"},"patho":"胰岛细胞肿瘤分泌过量激素：胰岛素抑制肝糖输出并促外周利用致空腹低血糖；胃泌素刺激壁细胞致胃酸过多、难治性溃疡与腹泻；VIP 致水样泻、低钾与无胃酸；胰高血糖素致坏死性游走性红斑、糖尿病与消瘦。功能性肿瘤生长缓慢但可恶性；无功能性者常长至较大体积侵犯周围或发生肝转移才被发现。","dx":{"criteria":["胰岛素瘤 Whipple 三联征：① 空腹或运动后低血糖症状（心悸、出汗、震颤、意识模糊，重者昏迷）；② 发作时血糖 <2.8 mmol/L；③ 补糖后症状迅速缓解","发作时同步胰岛素 ≥3 µU/mL、C 肽 ≥0.6 ng/mL 且不适当升高，胰岛素/血糖比值升高","胃泌素瘤（Zollinger-Ellison 综合征）：反复难治与多发性溃疡、常位于十二指肠远端或空肠，伴腹泻；空腹胃泌素 >1000 pg/mL 高度提示，100–1000 pg/mL 需促胰液素激发试验（升高 >120 pg/mL）","VIP 瘤：大量水样泻、低钾与无胃酸（WDHA）；胰高血糖素瘤：坏死性游走性红斑与血糖升高","增强 CT/MRI 见胰腺内富血供结节；超声内镜（EUS）定位小病灶并可行细针穿刺","68Ga-DOTATATE PET/CT 等生长抑素受体显像显著提高病灶与转移检出率","免疫组化 Syn、CgA 及相应激素阳性，Ki-67 定分级"],"workup":["禁食试验查血糖与同步胰岛素、C 肽，计算比值","血清 CgA，按症状查胃泌素、VIP、胰高血糖素","增强多期薄层胰腺 CT 与 MRI，EUS 首选定位 <2 cm 病灶","68Ga-DOTATATE PET/CT 用于分期与寻找转移","MEN1 家族史者查 MEN1 基因、血钙与 PTH","肝脏增强 MRI/CT 评估转移；胃镜观察胃泌素瘤患者的溃疡与黏膜肥厚"],"grading":"WHO 神经内分泌肿瘤分级：G1（Ki-67 <3%）、G2（3%–20%）、G3（>20%）；按 AJCC 第 8 版 TNM 分期；功能性肿瘤按激素类型命名并评估综合征控制情况。"},"ddx":[{"name":"肛裂（同大类 gs_anal_fissure）","point":"VIP 瘤与类癌综合征的腹泻易被误认为肛肠疾病或排便异常；肛裂的疼痛局限在肛门、有硬便史，pNET 伴腹泻则有低钾与激素升高。"},{"name":"小肠肿瘤（乳腺良性疾病与肠道其他大类 · 同大类另一分片，gs_small_bowel_tumor）","point":"同属胃肠胰神经内分泌肿瘤；小肠类癌以潮红腹泻与右心病变为主，pNET 激素症状更特异（低血糖、顽固溃疡），定位（胰腺 vs 小肠）与激素谱是关键。"},{"name":"肝囊肿与肝血管瘤（同大类 gs_liver_cyst_hemangioma）","point":"pNET 肝转移可被误认为血管瘤或囊肿，转移灶呈快进快出强化、伴 CgA 与原发灶，需胰腺影像结合判断。"},{"name":"非胰岛素瘤性低血糖","point":"肝功能衰竭、肾上腺皮质功能不全、酗酒或降糖药过量均有原发病史，禁食试验中胰岛素与 C 肽均降低，与胰岛素瘤不同。"},{"name":"幽门螺杆菌相关性溃疡","point":"根除后可治愈、多单发；胃泌素瘤溃疡多发、难治、位置不典型（十二指肠远端/空肠），停用 PPI 后复发。"},{"name":"胰腺癌","point":"以无痛性黄疸、消瘦与胰管扩张为主，CA19-9 显著升高，无激素综合征；CT 见乏血供肿块，而 pNET 多为富血供。"}],"tx":{"drug":[{"name":"生长抑素类似物（奥曲肽/长效奥曲肽）","dose":"奥曲肽 50–100 µg 皮下 q8h；长效奥曲肽 20–30 mg 肌注 q4 周，按症状调整","note":"抑制激素分泌控制症状并具抗肿瘤作用；注意高血糖、胆结石与注射部位反应；胰岛素瘤需少量监测血糖以防抑制过度","renal":"遵说明书","hepatic":"重度肝病延长给药间隔","interact":"与胰岛素、磺脲类合用可加重低血糖"},{"name":"质子泵抑制剂（胃泌素瘤抗酸）","dose":"奥美拉唑 40–60 mg 口服 qd–bid，或埃索美拉唑 40 mg bid，可需 2–3 倍标准量，按胃酸控制滴定","note":"需长期大剂量，随意停药可致溃疡与穿孔复发；监测维生素 B12 与血镁","renal":"遵说明书","hepatic":"重度肝病减量","interact":"奥美拉唑可能减弱氯吡格雷作用；与华法林合用监测 INR"},{"name":"依维莫司（进展期）","dose":"10 mg 口服 qd，可联合长效奥曲肽","note":"用于进展性、分化良好、不可切除或转移的 pNET；注意口腔炎、感染、代谢紊乱与肺毒性","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂/诱导剂显著影响浓度；避免活疫苗"},{"name":"舒尼替尼（进展期）","dose":"37.5 mg 口服 qd 连续给药（或 50 mg qd 服 4 周停 2 周）","note":"监测高血压、手足皮肤反应与甲状腺功能减退","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"CYP3A4 抑制剂增加暴露"},{"name":"二氮嗪（胰岛素瘤低血糖控制）","dose":"100–200 mg 口服 q8h，按血糖滴定，最大 600 mg/d","note":"用于术前或手术禁忌者；水肿、多毛、高尿酸常见","renal":"遵说明书","hepatic":"遵说明书","interact":"与噻嗪类利尿剂合用可加重高血糖与高尿酸"},{"name":"胰高血糖素（严重低血糖急救）","dose":"成人 1 mg 肌注或皮下，儿童 0.5 mg，意识恢复后口服糖水","note":"用于意识障碍无法口服者，为急救过渡措施","renal":"遵说明书","hepatic":"遵说明书","interact":"与β阻滞剂合用减弱升糖反应"}],"nonDrug":["手术是治愈手段：胰岛素瘤行肿瘤摘除或有限胰腺切除，术前定位（EUS/选择性动脉定位）是成功关键；胃泌素瘤多见于十二指肠与胰头，行局部切除 + 淋巴结清扫","无功能性 pNET：局限者行胰十二指肠切除（Whipple）或远端胰切除；<2 cm 低级别者可观察","转移性：以系统治疗为主，肝转移可行减瘤手术（>90% 减瘤）、射频消融、肝动脉栓塞或选择性内放射治疗","MEN1 相关：先处理甲状旁腺病变，随访胰腺多发小肿瘤","术前低血糖管理：持续静滴葡萄糖、二氮嗪，必要时生长抑素","MDT 会诊：外科、内分泌、肿瘤内科与影像共同决策"],"life":["术后监测血糖、胰瘘与感染（引流液淀粉酶）","胰岛素瘤术后可有一过性高血糖，监测 1–2 周；低血糖复发需排查残留","胃泌素瘤长期 PPI 与胃镜随访；每 3–6 个月查 CgA、血糖/胃泌素与增强影像，MEN1 家系行遗传筛查"]},"prog":"胰岛素瘤多为良性单发，手术治愈率 >90%，恶性约 10%；胃泌素瘤原发于十二指肠者约 60% 有淋巴结转移，10 年生存率约 40%–70%。局限 pNET 5 年生存 >80%，转移者中位生存 3–5 年；G3 及神经内分泌癌预后差。","refs":["外科学（第 9 版）·胰腺疾病·胰岛细胞瘤","中国胰腺神经内分泌肿瘤诊疗指南（2021 年版）","中国胃肠胰神经内分泌肿瘤专家共识（2021 年）","NCCN 神经内分泌肿瘤临床实践指南（2022 年）","ENETS 胰岛素瘤与胃泌素瘤诊治共识（2016 年）"]}]},{"id":"thy_surg","name":"甲状腺外科（补充）","rank":41,"summary":"甲亢外科治疗的关键是术前把甲状腺功能、静息心率与基础代谢率压到安全区，术中保护喉返神经与甲状旁腺，术后 24–72 h 警惕颈部血肿、低钙抽搐与甲状腺危象。","compare":[],"diseases":[{"id":"gs_hyperthyroid_surg","name":"甲状腺功能亢进的外科治疗","aka":["Surgical treatment of hyperthyroidism","Graves 病外科治疗","甲状腺次全切除术"],"rank":1,"basic":{"define":"以手术方式切除大部分甲状腺组织、减少甲状腺激素合成与分泌，用于药物治疗失败或不耐受、存在局部压迫、胸骨后甲状腺肿或怀疑恶变的甲亢，以 Graves 病为主。术式多为甲状腺次全切除或近全切除，保留 2–6 g 腺体与后被膜以保护甲状旁腺与喉返神经。","risk":["自身免疫性甲状腺病家族史，Graves 病（TRAb 阳性）占甲亢 80%–85%","女性、20–40 岁生育期；妊娠期 hCG 相关甲状腺毒症","精神应激、感染、碘负荷（含碘造影剂、胺碘酮）诱发或加重","吸烟（加重 Graves 眼病，术后眼病进展风险升高）","巨大甲状腺肿、胸骨后延伸致气管受压，麻醉与插管风险高","未规范服药、自行停药导致术前甲亢控制不佳"],"epi":"我国成人甲亢患病率约 1.2%（临床甲亢 0.78%、亚临床甲亢 0.44%），Graves 病占 80%–85%，女性为男性的 4–6 倍；接受手术者约占甲亢患者的 5%–10%。"},"patho":"TRAb 持续刺激 TSH 受体，甲状腺弥漫增生、滤泡上皮增高、腺体血流丰富，激素合成与释放增加，外周 T4 向 T3 转化增强，形成高代谢、交感兴奋与心肌耗氧增加。术前碘剂通过 Wolff-Chaikoff 效应抑制激素释放，使腺体缩小、变硬、血供减少，便于手术。手术去除大部分腺体后激素水平下降，但术中挤压可使储存激素大量入血，加之应激、感染或术前准备不足，可诱发甲状腺危象。","dx":{"criteria":["甲亢确诊：TSH <0.1 mIU/L 伴 FT4 和/或 FT3 高于参考上限；Graves 病 TRAb 阳性（高于参考上限）或摄碘率增高、弥漫性血流丰富","压迫或局部指征：气管受压移位/狭窄、呼吸困难、吞咽困难、声音嘶哑；胸骨后甲状腺肿（CT 示腺体延伸至胸骨切迹以下）","怀疑恶变：超声 TI-RADS 4 类及以上结节、穿刺细胞学可疑或确诊癌、短期内迅速增大","药物控制不佳：规范抗甲状腺药治疗 12–18 个月停药后复发、药物不良反应（粒细胞 <0.5×10^9/L、ALT >3×ULN、严重皮疹/血管炎）、无法坚持服药与随访","特殊类型：毒性多结节性甲状腺肿、毒性腺瘤、结节性甲状腺肿继发甲亢；妊娠中期（孕 4–6 个月）药物控制不佳需手术者","术前准备达标：静息心率 <80 次/min、基础代谢率（BMR）<+20%、体重回升、情绪稳定、FT3/FT4 正常或接近正常、甲状腺血管杂音减弱","碘剂准备 10–14 天，腺体质地变硬、体积缩小；未用碘剂者术中出血与危象风险升高","暂缓手术：未控制的甲状腺危象、妊娠早期（<12 周）与晚期（>28 周）、严重心衰未纠正、近期发生粒细胞缺乏"],"workup":["甲功五项（TSH、FT3、FT4、TT3、TT4）+ TRAb，必要时甲状腺摄碘率与核素显像鉴别毒性腺瘤/结节性甲状腺肿","颈部超声：腺体体积（>40 mL 提示巨大）、结节数目与 TI-RADS 分级、血流丰富程度","颈部/胸部 CT（平扫+增强）：胸骨后延伸、气管最窄径与偏移、有无纵隔肿块，为麻醉插管与术式提供依据","纤维喉镜：术前声带活动基线，声嘶或既往颈部手术者必查","血钙、PTH、25-羟维生素 D、肝功、血常规（基线，评估抗甲状腺药不良反应与术后低钙风险）","心电图与心脏超声：房颤（心室率控制 <100 次/min）、心衰、瓣膜病；老年或甲状腺毒性心脏病者加查 BNP"],"grading":"按病因分 Graves 病、毒性多结节性甲状腺肿、毒性腺瘤（Plummer 病）；按手术范围分次全切除（保留 4–6 g，每侧 2–3 g）、近全切除（保留 1–2 g）与全切除（仅保留后被膜，用于可疑癌、重度活动性眼病或复发）；按术前风险分可耐受手术与需延迟手术（危象、粒细胞缺乏、严重心衰）。"},"ddx":[{"name":"甲状腺结节（gs_thyroid_nodule）","point":"与本类中甲亢的鉴别点：结节性甲状腺肿多为甲功正常、TRAb 阴性、核素扫描呈冷/温结节；甲亢为 TSH 抑制、FT3/FT4 升高、TRAb 阳性或摄碘率增高，伴心动过速与体重下降。毒性腺瘤需核素扫描见热结节、结节外腺体受抑。"},{"name":"甲状旁腺功能亢进（gs_hyperpth）","point":"同样可有乏力、骨痛与情绪改变，但以高钙（>2.6 mmol/L）、PTH 升高、泌尿系结石与骨囊肿为特征，甲状腺功能正常、无甲状腺肿大与血管杂音；甲亢血钙多正常或轻度升高。"},{"name":"亚急性甲状腺炎（甲状腺毒症期）","point":"病毒感染后颈前剧痛、发热，ESR 常 >50 mm/h、CRP 升高，摄碘率降低（分离现象），TRAb 阴性，自限性，禁手术，激素/NSAIDs 治疗有效。"},{"name":"桥本甲状腺炎甲状腺毒症期","point":"TPOAb、TgAb 高滴度，超声弥漫低回声、网格样改变，摄碘率低，甲状腺毒症短暂（数周–数月），多自行转入甲减，不首选手术。"},{"name":"焦虑症/心脏神经官能症","point":"心悸、多汗、手抖、失眠与甲亢相似，但甲状腺功能正常、无甲状腺肿大与血管杂音、体重稳定，心率随情绪波动，β 受体阻滞剂可缓解症状。"},{"name":"嗜铬细胞瘤","point":"阵发性高血压伴头痛、大汗、心悸三联征，血/尿甲氧基肾上腺素升高，CT 见肾上腺肿块；甲亢为持续性心动过速、脉压增大、FT4 升高，甲状腺肿大。"},{"name":"快速型房颤/贫血","point":"心率快、乏力、活动耐量下降，但甲状腺功能正常，房颤有明确心电图证据，贫血 Hb 下降；甲亢患者合并房颤时心室率对 β 阻滞剂反应较好，且伴 FT4 升高。"}],"tx":{"drug":[{"name":"甲巯咪唑（MMI）","dose":"起始 10–30 mg/d 口服（分 1–2 次），重症可 30–45 mg/d；甲功正常后每 2–4 周减 1/3，维持 5–10 mg qd，术前用至手术前 1–2 周与碘剂衔接","note":"术前首选的抗甲状腺药，起效 2–6 周。粒细胞缺乏发生率 0.3%–0.6%，多在前 3 个月，出现发热、咽痛立即查血常规并停药；皮疹、关节痛、胆汁淤积性黄疸需停药；妊娠早期（<12 周）禁用（胚胎病、皮肤缺损）","renal":"轻中度肾功能不全无需调整；重度（eGFR <30）减量并监测","hepatic":"ALT >3×ULN 停药；重度肝病禁用","interact":"与华法林合用增强抗凝，监测 INR；与 β 受体阻滞剂合用注意心动过缓；与碘剂/含碘造影剂合用疗效减弱"},{"name":"丙硫氧嘧啶（PTU）","dose":"300–450 mg/d 口服，分 3 次（100–150 mg tid），最大 600 mg/d；甲功正常后减至 50–100 mg/d 维持；甲状腺危象首剂 600–1000 mg 口服或鼻饲","note":"妊娠早期（<12 周）首选；抑制外周 T4 向 T3 转化，危象时优于 MMI。肝毒性可致暴发性肝衰竭（儿童更高），出现黄疸、深色尿立即停药；服药前 3 个月每 2 周查血常规与肝功","renal":"肾功能不全减量，重度肾损遵说明书","hepatic":"活动性肝病禁用；转氨酶升高 >2 倍需停药评估","interact":"与华法林合用明显增强抗凝（INR 升高），需减量监测；与 β 受体阻滞剂、地高辛合用注意心率与洋地黄浓度"},{"name":"复方碘口服溶液（Lugol 液）","dose":"术前 2 周开始：第 1 日每次 3 滴 tid，逐日每次加 1 滴至每次 16 滴 tid 并维持至手术；或每次 5–10 滴 tid，疗程 10–14 天","note":"仅用于术前准备与危象（危象时在 PTU 后 1 h 给药），单用于甲亢会出现逃逸而加重；服碘后腺体变硬、血供减少、术中出血减少。碘过敏、妊娠、哺乳期禁用；甲状腺全切后不需继续","renal":"遵说明书","hepatic":"遵说明书","interact":"与锂剂合用可致甲减与甲状腺肿；与含碘造影剂叠加致碘负荷过高；与保钾利尿剂合用注意高钾"},{"name":"普萘洛尔","dose":"10–20 mg 口服 tid–qid，必要时 30–40 mg q6h，目标静息心率 <80 次/min；危象 20–40 mg q6h 或 1–2 mg 稀释后缓慢静推（≤1 mg/min）","note":"控制心率、震颤与焦虑，并抑制外周 T4→T3；用至手术日晨。哮喘、COPD 急性期、二至三度房室传导阻滞、失代偿心衰禁用；糖尿病患者可掩盖低血糖症状","renal":"遵说明书，重度肾损慎用","hepatic":"肝首过代谢，肝硬化者减量","interact":"与地尔硫䓬/维拉帕米、地高辛合用致心动过缓与传导阻滞；与胰岛素/磺脲类合用掩盖低血糖；与利血平合用致交感抑制"},{"name":"美托洛尔/阿替洛尔（普萘洛尔不耐受时）","dose":"美托洛尔 25–50 mg 口服 bid；阿替洛尔 25–50 mg 口服 qd，目标心率 <80 次/min","note":"选择性 β1 阻滞剂，支气管痉挛风险低于普萘洛尔，但哮喘者仍慎用；不抑制 T4→T3，甲状腺毒症控制略弱","renal":"阿替洛尔经肾排泄，CrCl <35 mL/min 减量","hepatic":"美托洛尔经肝代谢，肝功能不全减量","interact":"与钙通道阻滞剂（维拉帕米、地尔硫䓬）合用致心动过缓；与可乐定合用停药反跳性高血压"},{"name":"氢化可的松（甲状腺危象）","dose":"100 mg 静脉滴注 q8h（或地塞米松 2 mg iv q6h），危象控制后逐渐减量","note":"抑制甲状腺激素释放与外周 T4→T3 转化，并防止危象时相对肾上腺皮质功能不全；仅用于危象或极重度甲亢术前，需同时控制感染、降温、补液","renal":"遵说明书","hepatic":"遵说明书，肝硬化者注意水钠潴留","interact":"与利福平、苯妥英、卡马西平合用加速代谢；与 NSAIDs 合用增加消化道出血；升高血糖，需调整降糖方案"},{"name":"葡萄糖酸钙 + 骨化三醇（术后低钙）","dose":"10% 葡萄糖酸钙 10–20 mL 稀释后缓慢静推（10 min 以上），必要时 q6–8h；口服碳酸钙 1–2 g tid + 骨化三醇 0.25–0.5 μg qd","note":"术后 24–72 h 监测血钙与症状（口周麻木、手足搐搦、Chvostek/Trousseau 征）；血钙 <1.9 mmol/L 或有症状者静脉补钙；注意外渗致组织坏死，洋地黄化患者静推钙剂可致心律失常","renal":"肾功能不全者骨化三醇减量，监测血钙磷","hepatic":"遵说明书","interact":"与噻嗪类利尿剂合用致高钙；与洋地黄合用增加洋地黄毒性；与考来烯胺合用减少吸收"}],"nonDrug":["手术方式：Graves 病行甲状腺次全切除或近全切除（保留 4–6 g）；毒性结节行一侧腺叶+对侧次全切除；可疑癌、重度活动性 Graves 眼病、复发者行全切除","术中神经监测（IONM）+ 甲状旁腺识别与保护（纳米碳负显影、必要时自体移植于胸锁乳突肌），可降低永久性声带麻痹与甲旁减","胸骨后甲状腺肿：多数可经颈部低位领式切口取出，巨大或后纵隔者需胸骨劈开/胸腔镜辅助；气管软化者术后保留气管插管入 ICU","妊娠期甲亢：妊娠中期（孕 4–6 个月）是唯一安全手术窗口；妊娠早期与晚期以药物为主","术前准备不充分（心率 >90 次/min、FT4 明显升高）时延期手术，予抗甲状腺药+碘剂+β 阻滞剂 2–3 周；严禁在未控制甲亢时急诊切除","术后床旁备气管切开包与负压引流，巨大甲状腺肿、气管受压者术后 24 h 入监护病房"],"life":["术后 1、3、6 个月复查甲功与血钙，此后每年 1 次；全切者终身左甲状腺素替代（约 1.6 μg/kg/d），维持 TSH 在目标范围","术后 2 周内避免剧烈活动与颈部过度后仰；出现颈部肿胀、呼吸困难、声嘶加重立即就诊","低碘饮食 2–4 周（避免海带、紫菜、含碘造影剂），吸烟者戒烟以降低眼病进展风险","计划妊娠者孕前复查甲功与 TRAb，妊娠期每 4–6 周复查，抗甲状腺药改用 PTU（孕早期）或 MMI（孕中晚期小剂量）"]},"prog":"规范手术的甲亢治愈率约 90%–95%，次全切除术后复发率 2%–5%；暂时性低钙 10%–30%，永久性甲旁减 1%–3%（全切可达 5%）；永久性喉返神经损伤在有经验的术者 <1%–2%。甲状腺危象未治死亡率可达 50%，规范救治后约 10%–30%。","refs":["中华医学会内分泌学分会：甲状腺功能亢进症和其他原因所致甲状腺毒症诊治指南（2022 年）","中华医学会内分泌学分会等：甲状腺结节和分化型甲状腺癌诊治指南（第二版，2023）","中国医师协会外科医师分会甲状腺外科医师委员会：甲状腺手术中甲状旁腺保护专家共识（2015）","外科学（第 9 版）·甲状腺疾病·甲状腺功能亢进的外科治疗","2016 年美国甲状腺协会（ATA）甲状腺功能亢进症诊治指南"]}]},{"id":"hernia_more","name":"腹外疝（补充）","rank":42,"summary":"脐疝与白线疝同属腹壁中线疝：疝环小、易嵌顿，成人不会自愈；婴幼儿脐疝多数可观察至 2 岁，成人脐疝与有症状的白线疝应修补，缺损 ≥2 cm、复发或合并腹水者加用补片。","compare":[{"diseaseId":"gs_umbilical_hernia","dx":"脐环处可复性包块，站立、咳嗽或哭闹时突出，平卧可回纳，可触及脐环缺损；嵌顿时包块变硬、触痛、不能还纳并出现肠梗阻","key":"缺损位于脐环本身，婴幼儿脐环 <2 cm 者 90% 在 2 岁内自愈，成人则不会自愈且嵌顿率约 10%–20%"},{"diseaseId":"gs_linea_alba","dx":"脐上白线区（多在脐上 2–5 cm）小而局限的包块或压痛点，仰卧抬头收缩腹肌时明显，常仅含腹膜外脂肪，包块大小与疼痛程度不成比例","key":"缺损位于脐上白线、疝环常 <1 cm，因环小坚韧更易嵌顿，超声/CT 见白线连续性中断"}],"diseases":[{"id":"gs_umbilical_hernia","name":"脐疝","aka":["Umbilical hernia","成人脐疝","婴幼儿脐疝"],"rank":1,"basic":{"define":"腹腔内脏器或腹膜外脂肪经脐环突出形成的腹外疝。分婴幼儿先天性（脐环闭合不全，多在 2 岁内自愈）与成人获得性（腹壁薄弱叠加腹内压增高，不会自愈且易嵌顿）。","risk":["肥胖（BMI ≥30）与腹壁脂肪堆积致脐环张力增高","多次妊娠、多产致腹直肌分离与脐环松弛","肝硬化腹水（腹压高、腹壁薄，脐疝可自发破裂）","慢性咳嗽/COPD、慢性便秘、前列腺增生致长期腹压增高","高龄、结缔组织病（Ehlers-Danlos 综合征）、长期激素使用","既往脐部手术或腹腔镜穿刺孔（脐部套管）"],"epi":"成人脐疝约占腹外疝的 6%–14%，女性多见（约 3:1），肥胖、多次妊娠与肝硬化腹水者高发；婴幼儿脐疝发生率约 10%–20%（早产儿更高），其中约 90% 在 2 岁内自愈。"},"patho":"脐环是腹壁闭合最晚、最薄弱处，仅由脐筋膜与瘢痕组织覆盖，缺乏肌层支撑。腹内压长期升高时腹膜外脂肪先经脐环突出形成脂肪疝，继而牵拉腹膜形成疝囊，大网膜与肠管进入。成人疝环小、边缘为致密瘢痕，内容物嵌顿后静脉回流受阻、水肿，迅速进展为绞窄；腹水患者腹壁张力高，疝囊壁薄，可发生自发性破裂致腹水外漏。","dx":{"criteria":["脐部可复性包块：站立、咳嗽、用力时增大，平卧或手托后消失，伴坠胀、隐痛或牵拉感","触诊可及脐环缺损，测量疝环直径：小 <1 cm、中 1–2 cm、大 >2 cm；咳嗽冲击感阳性","婴幼儿：脐部圆形柔软突起，哭闹时明显、安静平卧可回纳，皮肤完整无压痛；脐环 <2 cm 者 2 岁内自愈率 >90%，≥2 cm 或 4–5 岁仍未闭合考虑手术","嵌顿：包块突然增大、变硬、触痛明显、不能还纳，伴恶心呕吐、腹胀、停止排气排便（肠梗阻表现）","绞窄：发热 >38 ℃、局部红肿热痛、腹膜刺激征、白细胞 >15×10^9/L、乳酸 >2 mmol/L，提示肠坏死，需急诊手术","超声（站立位+Valsalva 动作）：确认疝环直径、疝囊颈宽度、内容物（大网膜/肠管）及有无积液、肠壁血流","腹部 CT：肥胖、嵌顿、腹水或需与白线疝/切口疝鉴别时首选，可评估缺损、内容物、肠壁强化与腹水程度","腹水患者：诊断性腹腔穿刺查细胞计数（PMN ≥250/μL 提示自发性细菌性腹膜炎），并评估 Child-Pugh 分级"],"workup":["站立位与仰卧位超声（配合 Valsalva）测量疝环与疝囊，判断可复性与内容物","腹部 CT（含 Valsalva 或立位）：拟诊嵌顿、肥胖、多发疝、腹水或既往腹部手术者必查","嵌顿者查血常规、乳酸、电解质、血气与腹部立位平片（气液平、肠管扩张）","腹水者查腹水常规/培养、Child-Pugh 与 MELD 评分，评估手术耐受性","术前评估腹壁缺损范围、腹直肌分离程度（>2 cm 需同期腹壁重建）与呼吸功能（巨大疝致腹腔内压升高）"],"grading":"按疝环直径分小（<1 cm）、中（1–2 cm）、大（>2 cm）；按病因分婴幼儿先天性、成人获得性原发性、复发性；按状态分可复性、难复性、嵌顿性、绞窄性。腹壁缺损按 EHS 中线分区：M1 剑突下、M2 上腹、M3 脐周、M4 下腹、M5 耻骨上，脐疝属 M3。"},"ddx":[{"name":"白线疝（gs_linea_alba）","point":"与本类中脐疝的鉴别点：白线疝缺损位于脐上腹白线（多在脐上 2–5 cm），包块小、常仅含脂肪、压痛明显；脐疝缺损就在脐环，包块位于脐部、可较大，婴幼儿有自愈可能。二者可同时存在（多发中线疝），CT 可明确缺损位置与数目。"},{"name":"腹股沟疝（gs_inguinal）","point":"包块位于腹股沟韧带上方、可降入阴囊，咳嗽冲击感在腹股沟管外环；脐疝位于脐部，与腹股沟区无关。二者并存时需分别评估，勿只处理一处。"},{"name":"腹壁切口疝（gs_ventral_hernia）","point":"有腹部手术史，缺损位于原切口（多为纵切口），疝环大、形态不规则、易致腹胀与便秘；脐疝无手术史、缺损在脐环。既往脐部手术者归为切口疝。"},{"name":"脐部脂肪瘤/皮脂腺囊肿","point":"包块固定、不能还纳、无咳嗽冲击感，超声见皮下脂肪或囊性结构、腹壁筋膜完整；脐疝可还纳、有疝环缺损、Valsalva 时增大。"},{"name":"腹壁子宫内膜异位症（脐部）","point":"育龄女性脐部结节，经期增大、疼痛并可有出血，包块固定无还纳，MRI 见脐部软组织结节；脐疝与月经周期无关、可还纳。"},{"name":"脐部转移结节（Sister Mary Joseph 结节）","point":"质硬、固定、无压痛、表面可溃破，常伴腹腔内恶性肿瘤（胃、卵巢、结肠）与腹水、消瘦；超声/CT 见实性肿块无疝环，穿刺活检确诊。"}],"tx":{"drug":[{"name":"头孢唑林（术前预防）","dose":"2 g 静脉滴注（体重 ≥80 kg 用 3 g），术前 30–60 min 单次；植入补片者手术超过 4 h 追加 1 g","note":"覆盖皮肤菌群（金黄色葡萄球菌、链球菌），补片植入属清洁-污染手术，预防用药可降低表浅与深部切口感染","renal":"单次预防剂量一般无需调整；CrCl <20 mL/min 需延长给药间隔并减量","hepatic":"遵说明书","interact":"与华法林合用可能增强抗凝，监测 INR；与氨基糖苷类同瓶混合可致沉淀"},{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日不超过 3 g（肝病或长期饮酒者 ≤2 g/d）","note":"术后基础镇痛，不影响血小板与肾功能；与阿片类联合可减少阿片用量","renal":"CrCl <30 mL/min 延长给药间隔至 q8h","hepatic":"肝功能不全者 ≤2 g/d，失代偿肝硬化禁用或极慎用","interact":"与华法林长期合用可升高 INR；与酒精、异烟肼合用增加肝毒性"},{"name":"布洛芬/塞来昔布（短期）","dose":"布洛芬 400 mg 口服 q8h 餐后（≤1.2 g/d，疗程 3–5 天）；或塞来昔布 200 mg 口服 bid","note":"减少阿片用量、利于早期下床；但可能影响补片整合与吻合口愈合，腹腔镜术后短期使用为宜，疝修补术后 48–72 h 后尽量停用","renal":"CrCl <30 mL/min 避免使用；与 ACEI/ARB、利尿剂合用增加急性肾损风险","hepatic":"肝硬化（Child-Pugh B/C）避免 NSAIDs，防肝肾综合征与出血","interact":"与抗凝/抗血小板药合用增加出血；与 ACEI/ARB+利尿剂合用致肾功能恶化；与锂剂合用升高锂浓度"},{"name":"乳果糖/聚乙二醇 4000（术后通便）","dose":"乳果糖 15–30 mL 口服 qd–bid；或聚乙二醇 4000 10–20 g 口服 qd，晨起顿服","note":"避免术后用力排便致腹压骤升与补片移位；腹胀明显或肠梗阻者禁用","renal":"聚乙二醇大剂量用于肠镜准备时肾功能不全者需水化；乳果糖慎用于高钾/失代偿肝硬化（肝性脑病可用）","hepatic":"乳果糖可用于肝性脑病，起始 30–45 mL q6–8h 后调整至每日 2–3 次软便","interact":"与其他口服药间隔 1–2 h，避免影响吸收"},{"name":"螺内酯 + 呋塞米（合并腹水者术前优化）","dose":"螺内酯 40–100 mg 口服 qd + 呋塞米 20–40 mg 口服 qd，按腹水与体重调整；目标体重下降 ≤0.5 kg/d（无水肿）或 ≤1 kg/d（有水肿）","note":"腹水控制后再择期修补可显著降低术后腹水漏与切口并发症；急诊嵌顿者不宜大量利尿，需先纠正容量与电解质","renal":"CrCl <30 mL/min 慎用；肌酐较基线升高 >26.5 μmol/L 或高钾 >5.5 mmol/L 减量/停药","hepatic":"肝硬化者监测肌酐、钠、钾；避免过度利尿诱发肝性脑病与肝肾综合征","interact":"螺内酯与 ACEI/ARB、补钾药合用致高钾；呋塞米与氨基糖苷类合用增加耳肾毒性；NSAIDs 削弱利尿效果"}],"nonDrug":["婴幼儿：脐环 <2 cm 观察至 2 岁（自愈率 >90%），不推荐硬币/绷带压迫（无效且易致皮肤损伤）；≥2 cm 或 4–5 岁未闭合行脐环修补/缝扎","成人：确诊后建议择期修补（嵌顿率约 10%–20%，急诊手术死亡率明显升高）；术式可选开放小切口修补或腹腔镜 IPOM/eTEP","补片修补指征：疝环 ≥2 cm、复发疝、肥胖（BMI ≥30）、腹水、免疫抑制、结缔组织病、多发或巨大中线缺损；补片置于 Sublay（腹膜前/肌后）或 IPOM 层","嵌顿/绞窄：急诊手术，肠管坏死行切除吻合；腹腔污染重者仅做组织缝合或分期修补（先关腹，二期补片），避免一期植入补片致感染","肝硬化腹水者：先内科优化（限盐、利尿，必要时 TIPS），择期修补同时行腹水管理；Child-Pugh C 级急诊手术风险极高，需多学科评估","肥胖者 BMI ≥35 建议先减重（生活方式或减重手术）再修补，可降低复发与切口并发症"],"life":["控制体重（BMI <30）、治疗慢性咳嗽/便秘/前列腺增生，减少腹压增高的诱因","腹水者限盐 5–6 g/d、规律利尿、每日测体重与腹围，避免腹水骤增","术后 6–8 周避免提 >10 kg 重物与剧烈腹压动作；补片修补者 3 个月内避免核心肌群高强度训练","术后 1、6、12 个月复查（超声/查体），补片修补复发率 1%–5%，单纯缝合 10%–15%"]},"prog":"择期补片修补复发率 1%–5%，单纯缝合修补 10%–15%；嵌顿急诊手术死亡率 1%–3%，合并肠绞窄坏死者可升至 10% 以上。婴幼儿脐环 <2 cm 者自愈率 >90%，术后并发症少见。","refs":["中华医学会外科学分会疝与腹壁外科学组：腹壁切口疝诊断和治疗指南（2018 年版）","中华医学会外科学分会疝与腹壁外科学组：腹股沟疝诊疗指南（2024 版）","中华医学会外科学分会疝与腹壁外科学组：成人腹股沟疝诊断和治疗指南（2018 年版）","外科学（第 9 版）·腹外疝·脐疝"]},{"id":"gs_linea_alba","name":"白线疝","aka":["Epigastric hernia","上腹疝","腹直肌间疝"],"rank":2,"basic":{"define":"腹腔内容物经腹白线（两侧腹直肌鞘在中线交织的腱膜）纤维间隙突出形成的腹外疝，约 90% 位于脐上，故又称上腹疝；疝环多 <1 cm，常以腹膜外脂肪为先导，疼痛可与包块大小不成比例。","risk":["腹白线腱膜交叉处先天性裂隙或腱膜薄弱（血管神经穿出点）","慢性腹压增高：慢性咳嗽、便秘、举重、腹水、吹奏乐器","肥胖与多次妊娠致腹直肌分离、白线增宽","中青年男性体力劳动者（反复负重）","结缔组织病（Ehlers-Danlos 综合征）致腱膜强度下降","既往上腹部手术或创伤致白线结构破坏"],"epi":"白线疝约占腹外疝的 0.4%–5%，30–50 岁男性多见，约 90% 位于脐上，约 20% 为多发缺损；尸检与影像研究中无症状白线缺损的发现率可达 5% 以上。"},"patho":"腹白线由腹外斜肌、腹内斜肌与腹横肌的腱膜在中线交织而成，其间有血管神经穿出的裂隙，是腹壁的力学薄弱点。腹压反复升高使腹膜外脂肪经裂隙突出，形成仅有脂肪的脂肪疝；随疝囊形成，大网膜与小肠可进入。疝环小且边缘为致密腱膜，内容物嵌顿后不易自行还纳，易发生绞窄；疼痛来自脂肪嵌顿、腹膜牵拉与疝环压迫神经，故小疝也可剧痛。","dx":{"criteria":["上腹中线局限性包块或压痛点，多在脐上 2–5 cm；站立、咳嗽、仰卧抬头（收缩腹肌）时明显，平卧放松后减轻或消失","多数包块直径 <2 cm、质软、边界不清；脂肪疝者仅触及皮下小结节伴明显局限压痛，无明确疝囊","疼痛为钝痛或牵拉痛，进食后、弯腰或用力时加重，可伴恶心、上腹不适，易被误诊为胃炎或胆囊疾病","嵌顿：包块突然变硬、剧痛、不能还纳，伴呕吐与肠梗阻；绞窄者出现发热、局部红肿与腹膜刺激征","超声（高频线阵探头，配合 Valsalva 与仰卧抬头）：见白线连续性中断，可测缺损宽度、疝囊深度与内容物，是首选筛查","腹部 CT（薄层）：术前评估金标准，可显示缺损位置与数目、疝内容物、腹直肌分离宽度（>2 cm 有临床意义）及有无嵌顿","诊断性要点：以疼痛为主而无明确包块者，需先排除胃十二指肠、胆囊、胰腺疾病，避免仅凭压痛行疝修补","多发缺损（≥2 处）需在 CT 上逐一标记，防止术中遗漏导致复发"],"workup":["站立位与仰卧抬头位超声对比，测量疝环直径与疝囊深度，判断内容物性质","腹部增强 CT（薄层 1 mm 重建）：评估多发缺损、腹直肌分离、疝内容物与有无绞窄，为补片大小与术式选择提供依据","上腹痛为主者查胃镜、腹部超声（胆囊/胰腺）、必要时 MRCP，排除消化性溃疡、胆石症、慢性胰腺炎","术前评估腹壁功能：腹直肌分离 >2–3 cm、巨大中线缺损者需同期腹壁重建（Rives-Stoppa/TAR）","嵌顿者查血常规、乳酸、电解质与腹部立位平片"],"grading":"按内容物分脂肪疝（仅腹膜外脂肪，无疝囊）与真疝（有疝囊及腹腔脏器）；按缺损直径分小 <1 cm、中 1–2 cm、大 >2 cm；按状态分可复性、嵌顿性、绞窄性；按位置分脐上（最常见）、脐下与多发。"},"ddx":[{"name":"脐疝（gs_umbilical_hernia）","point":"与本类中白线疝的鉴别点：脐疝缺损位于脐环本身、包块在脐部、可较大，婴幼儿可自愈；白线疝缺损在脐上白线、包块小、常为脂肪疝、压痛突出。两者可并存，CT 可见两处独立缺损。"},{"name":"腹壁切口疝（gs_ventral_hernia）","point":"有腹部手术史，缺损位于原切口、疝环大而不规则，常伴腹胀与排便困难；白线疝无手术史、缺损小、位于中线腱膜交叉处。"},{"name":"腹直肌鞘血肿","point":"抗凝治疗、剧烈咳嗽或外伤后突发腹部剧痛，可触及质硬包块但无还纳史，超声/CT 见腹直肌鞘内血肿、白线完整；白线疝有可复性包块与咳嗽冲击感。"},{"name":"腹壁脂肪瘤/皮脂腺囊肿","point":"包块缓慢增大、质软分叶、固定不能还纳，无压痛或仅轻压痛，超声见皮下脂肪层内高回声/囊性结构、腱膜完整；白线疝 Valsalva 时增大并有缺损。"},{"name":"慢性胃炎/消化性溃疡","point":"上腹隐痛或烧灼痛，与进食相关，可伴反酸嗳气，胃镜见黏膜病变；无腹壁包块与疝环，白线疝的疼痛在用力与收缩腹肌时加重。"},{"name":"腹壁子宫内膜异位症/硬纤维瘤","point":"育龄女性经期疼痛性结节（内异症）或缓慢增大的质硬固定肿块（硬纤维瘤，多见于既往手术瘢痕），CT/MRI 见实性肿块、无疝环；白线疝可还纳、有明确缺损。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日不超过 3 g（肝病或长期饮酒者 ≤2 g/d）","note":"术前疼痛与术后镇痛的基础用药，不增加出血风险，适合门诊修补","renal":"CrCl <30 mL/min 延长间隔至 q8h","hepatic":"肝功能不全 ≤2 g/d；失代偿肝硬化避免","interact":"长期与华法林合用升高 INR；与酒精、异烟肼合用增加肝毒性"},{"name":"塞来昔布/布洛芬（短期）","dose":"塞来昔布 200 mg 口服 bid；或布洛芬 400 mg 口服 q8h 餐后，疗程 ≤5 天","note":"用于炎症性疼痛与术后镇痛，减少阿片用量；补片植入后长期使用可能影响组织整合，建议短期","renal":"CrCl <30 mL/min 避免；老年或脱水者慎用","hepatic":"Child-Pugh B/C 避免 NSAIDs","interact":"与抗凝/抗血小板药合用增加出血；与 ACEI/ARB+利尿剂合用致肾损；与锂剂合用升高血锂"},{"name":"头孢唑林（术前预防）","dose":"2 g 静脉滴注（体重 ≥80 kg 3 g），术前 30–60 min 单次；手术 >4 h 追加 1 g","note":"开放或腹腔镜补片修补时预防手术部位感染；单纯小切口组织缝合可不用","renal":"单次预防剂量一般无需调整；CrCl <20 mL/min 延长间隔","hepatic":"遵说明书","interact":"与华法林合用可能增强抗凝，监测 INR"},{"name":"罗哌卡因（切口浸润/腹横肌平面阻滞）","dose":"0.5% 罗哌卡因 10–20 mL 切口各层浸润（总量 ≤3 mg/kg）；或 0.375% 20–30 mL 行 TAP 阻滞","note":"术后 8–12 h 镇痛，减少阿片用量与恶心呕吐；注意局麻药总量，避免血管内注射","renal":"遵说明书，严重肾损慎用","hepatic":"重度肝损降低清除率，减量","interact":"与其他局麻药叠加需计算总量；与 CYP1A2 抑制剂（氟伏沙明）合用升高血药浓度"},{"name":"乳果糖/聚乙二醇 4000（术后通便）","dose":"乳果糖 15–30 mL 口服 qd；或聚乙二醇 4000 10–20 g 口服 qd","note":"防止术后用力排便致腹压升高、补片移位与切口裂开","renal":"聚乙二醇肠镜准备时肾功能不全者需水化","hepatic":"乳果糖可用于肝性脑病，按排便调整","interact":"与其他口服药间隔 1–2 h"}],"nonDrug":["无症状、缺损 <1 cm 的脂肪疝可观察（每 6–12 个月查体+超声），但疼痛明显或患者焦虑者仍建议修补","有症状或疝环 ≥1 cm：开放小切口直接缝合（缺损 <1 cm、无张力）或腹腔镜 eTEP/IPOM 修补；缺损 >2 cm、复发、肥胖者加轻量补片","嵌顿/绞窄：急诊手术，切除坏死肠管；污染重者仅组织缝合，二期补片","合并腹直肌分离 >2–3 cm 或巨大中线缺损：同期行腹壁重建（Rives-Stoppa 后鞘前补片、必要时 TAR 松解）","以疼痛为主、无明确包块者先完成胃镜/腹部超声排除内科腹痛，避免术后症状不缓解","术后腹带支持 4–6 周（巨大缺损者 8 周），逐步恢复活动"],"life":["控制体重、治疗慢性咳嗽与便秘，避免长期负重与突然用力","术后 4–6 周避免提 >10 kg 重物与卷腹等核心训练；巨大缺损修补者延长至 8–12 周","术后 1、6、12 个月复查超声，注意复发（单纯缝合 10%–20%，补片 <5%）与慢性疼痛","持续上腹痛或包块再现者及时复诊，勿自行按胃病长期服药"]},"prog":"择期修补后症状缓解率 80%–90%，补片修补复发率 <5%，单纯缝合 10%–20%；术后慢性疼痛 2%–5%。嵌顿/绞窄急诊手术的并发症与死亡率显著高于择期修补。","refs":["中华医学会外科学分会疝与腹壁外科学组：腹壁切口疝诊断和治疗指南（2018 年版）","中华医学会外科学分会疝与腹壁外科学组：腹股沟疝诊疗指南（2024 版）","外科学（第 9 版）·腹外疝·白线疝","中华医学会外科学分会疝与腹壁外科学组：成人腹股沟疝诊断和治疗指南（2018 年版）"]}]},{"id":"abd_trauma","name":"腹部损伤","rank":43,"summary":"腹部损伤先复苏后定诊：血流动力学不稳定者直接剖腹或 FAST 导向手术，稳定者行增强 CT 定脏器与分级；脾以保脾与栓塞为主、肝靠填塞与修补、肠破裂早修、胰腺主胰管损伤决定切除范围。","compare":[],"diseases":[{"id":"gs_abd_trauma","name":"腹部损伤（肝脾胰肠）","aka":["Abdominal trauma","腹部创伤","肝脾破裂","外伤性肠破裂"],"rank":1,"basic":{"define":"外力导致的腹腔内脏器（肝、脾、胰等实质脏器，胃、小肠、结肠等空腔脏器及系膜血管）结构损伤，分钝性（撞击、挤压、减速）与穿透性（刀刺、火器）两类，常为多发伤的一部分，可表现为失血性休克或腹膜炎。","risk":["交通事故、高处坠落等减速伤（脾、肝、肠系膜血管）","刀刺伤、枪伤等穿透伤（肝、小肠、大血管）","安全带/方向盘撞击（座椅带征）致肠管、肠系膜与腰椎损伤","酒后或饱餐后腹部受击（胃扩张、肠管充盈易破裂）","儿童脾相对较大、包膜薄；凝血障碍/抗凝治疗者出血风险高","老年骨质疏松者跌倒致迟发性实质脏器破裂"],"epi":"腹部损伤约占创伤死亡的 10%，是创伤后第三位死因（次于颅脑与胸部损伤）；钝性伤约占 80%，其中脾最常受累（约 40%），肝次之（15%–20%）；穿透伤以肝、小肠与大血管损伤多见。"},"patho":"钝性伤通过直接挤压、减速剪切（活动度大的肠管与固定韧带附着处之间）与爆裂（空腔脏器内压骤升）致伤；实质脏器破裂出血入腹腔，失血量 >1500 mL 即出现失血性休克。空腔脏器破裂后消化液外溢，先引起化学性腹膜炎，6–12 h 后转为细菌性腹膜炎与脓毒症。胰腺横断或十二指肠破裂早期体征隐匿，胰液外漏可致后期胰瘘、腹腔脓肿与假性囊肿；腹膜后血肿可大量失血却不伴明显腹膜炎。","dx":{"criteria":["明确外伤机制与时间：减速伤、方向盘/安全带压痕、刀刺方向与深度、火器伤道；记录饮酒、抗凝药与既往腹部手术史","失血性休克：SBP <90 mmHg、HR >120 次/min、尿量 <0.5 mL/kg/h、乳酸 >2 mmol/L、Hb 进行性下降；对 1–2 L 晶体液复苏无反应提示活动性出血","腹膜刺激征（压痛、反跳痛、肌紧张）提示空腔脏器破裂或腹腔积血；单纯实质脏器出血早期可仅有腹胀、移动性浊音与休克","FAST（床旁超声）：腹腔游离液检出阈值约 200 mL，敏感度 80%–90%，可快速判断有无腹腔积血，但不能区分血液/肠液、不能定位脏器","增强 CT（门脉期+延迟期）：血流动力学稳定者的金标准，可显示造影剂外溢（活动性出血）、脏器 AAST 分级、游离气体、肠壁强化中断与腹膜后血肿","腹腔游离气体：立位胸腹平片膈下新月形气体仅 30%–50% 阳性；CT 见游离气体或肠壁缺损、造影剂外漏提示肠破裂，但约 1/3 小肠破裂早期无游离气体","淀粉酶/脂肪酶 >3×ULN 提示胰腺或十二指肠损伤，但敏感性有限；稳定患者疑主胰管损伤行 MRCP（敏感度 >90%）或 ERCP","诊断性腹腔灌洗（DPL）：红细胞 >100×10^9/L、白细胞 >0.5×10^9/L、淀粉酶升高或见胆汁/食物残渣为阳性；已多被 FAST 取代，用于基层或无 CT 条件","手术阈值：初始 24 h 需输红细胞 >4 U，或持续出血 >200 mL/h 连续 3 h，或复查 Hb 下降 >20 g/L 伴血流动力学不稳定"],"workup":["按 ATLS 顺序行一级、二级评估，同时建立两条大静脉通路、备血、启动大量输血方案；FAST 作为首轮筛查","血流动力学稳定者行全腹增强 CT（含延迟期），报告脏器 AAST 分级、活动性出血（blush）、腹膜后积气、肠壁与系膜异常","实验室：血常规、凝血功能、血型交叉、血气与乳酸、肝肾功能、淀粉酶/脂肪酶、心肌酶（减速伤）","疑胰腺/十二指肠损伤：稳定者 MRCP，术中疑胆胰管损伤行术中胆道造影或胰管造影","疑泌尿系损伤：CT 尿路造影（排泄期）或逆行膀胱造影（尿道口有血、骨盆骨折）","非手术治疗期间每 4–6 h 重复查体、每 6–12 h 复查 Hb 与乳酸；出现腹膜刺激征、Hb 下降 >20 g/L 或血流动力学恶化即中转手术"],"grading":"脾 AAST 分级：Ⅰ 包膜下血肿 <10% 表面积或裂伤深度 <1 cm；Ⅱ 血肿 10%–50% 或裂伤 1–3 cm；Ⅲ 血肿 >50% 或裂伤 >3 cm、包膜下血肿 >5 cm；Ⅳ 累及脾门血管致 >25% 血供丧失；Ⅴ 脾碎裂或脾门撕脱。肝 AAST：Ⅰ 包膜下血肿 <10% 或裂伤 <1 cm；Ⅱ 10%–50% 或 1–3 cm；Ⅲ >50% 或 >3 cm；Ⅳ 实质破坏 25%–75%（累及 1–3 个肝段）；Ⅴ >75% 或肝后下腔静脉/主肝静脉损伤；Ⅵ 肝撕脱。胰腺 AAST：Ⅰ 挫伤/浅裂伤无胰管损伤；Ⅱ 较大裂伤无胰管损伤；Ⅲ 远端横断或胰管损伤；Ⅳ 近端（肠系膜上静脉右侧）横断或胰管损伤；Ⅴ 胰头严重毁损。肠管按浆肌层撕裂、全层破裂、系膜撕裂伴血供障碍分级。"},"ddx":[{"name":"腹膜炎（gs_peritonitis，外科感染大类）","point":"与本类中腹部损伤的鉴别点：自发性/继发性腹膜炎有发热、全腹压痛与感染中毒表现，无外伤史与失血性休克；外伤后出现的腹膜炎必须按空腔脏器破裂处理，不能按内科腹膜炎保守观察。"},{"name":"肠梗阻（gs_bowel_obst，急腹症大类）","point":"阵发性绞痛、呕吐、腹胀、停止排气排便，多有腹部手术史与粘连；外伤性肠破裂为持续性腹痛、腹膜刺激征突出，伴外伤机制与游离气体/腹腔积液，早期即可有休克。"},{"name":"急性胰腺炎","point":"上腹持续痛向背部放射、血淀粉酶/脂肪酶 >3×ULN、CT 见胰周渗出与积液；外伤性胰腺损伤必须有明确外伤机制，淀粉酶升高幅度较小，MRCP 可显示主胰管断裂。"},{"name":"肾/输尿管结石","point":"腰腹部绞痛向会阴放射、镜下血尿、CT 见高密度结石与肾盂积水；外伤后血尿须先排除肾挫裂伤（增强 CT 排泄期见造影剂外溢、肾周血肿）。"},{"name":"腹壁软组织挫伤","point":"局部压痛、瘀斑，但无腹膜刺激征、无腹腔游离液、Hb 与乳酸稳定；需动态观察 24–48 h，警惕迟发性脾破裂（尤其儿童与抗凝者）。"},{"name":"骨盆骨折伴腹膜后血肿","point":"失血性休克但腹软、FAST 可阴性，CT 见骨盆骨折与腹膜后血肿，出血多来自骶前静脉丛；优先骨盆外固定与动脉栓塞，盲目剖腹探查会加重出血。"}],"tx":{"drug":[{"name":"氨甲环酸","dose":"伤后 3 h 内 1 g 静脉滴注（10 min 以上），随后 1 g 持续静滴 8 h；超过 3 h 不推荐使用","note":"抑制纤溶、降低创伤出血死亡率（CRASH-2/CRASH-3）；不替代止血手术与输血；肾功能不全者减量","renal":"CrCl <30 mL/min 减量（1 g 单次后不再维持或减半）","hepatic":"遵说明书","interact":"与抗凝药合用减弱疗效；与口服避孕药合用增加血栓风险"},{"name":"头孢曲松（+甲硝唑）","dose":"头孢曲松 2 g 静脉滴注 qd；合并厌氧菌污染时加甲硝唑 0.5 g 静脉滴注 q8h，疗程 4–7 天（源控制充分者）","note":"用于空腔脏器破裂、腹腔污染与剖腹探查围术期；强调术中冲洗与充分引流，抗菌药不能替代源控制","renal":"头孢曲松主要经胆道排泄，肾功能不全一般无需调整（同时肝肾功能不全者减量）","hepatic":"肝硬化者无需调整，但注意胆泥淤积","interact":"与含钙输液同瓶可致沉淀（新生儿禁用）；与华法林合用增加出血"},{"name":"甲硝唑","dose":"0.5 g 静脉滴注 q8h（或 0.5 g 口服 tid），疗程 4–7 天","note":"覆盖脆弱拟杆菌等厌氧菌，是结肠/直肠损伤与腹腔感染的基础用药","renal":"CrCl <10 mL/min 减量 50% 并延长间隔","hepatic":"重度肝功能不全（Child-Pugh C）减量 50%","interact":"用药期间及停药 72 h 内禁酒（双硫仑样反应）；与华法林合用升高 INR；与锂剂合用升高血锂"},{"name":"去甲肾上腺素（失血性休克辅助）","dose":"0.05–0.5 μg/kg/min 持续泵入，目标 MAP ≥65 mmHg；在控制出血与输血基础上使用","note":"创伤性失血性休克以止血+容量复苏+输血为主，血管活性药仅作过渡；冠心病、肠系膜缺血者慎用，避免外周外渗致坏死","renal":"遵说明书，少尿非禁忌但需保证肾灌注","hepatic":"遵说明书","interact":"与 β 受体阻滞剂合用致血压失控/心动过缓；与单胺氧化酶抑制剂合用致高血压危象；与卤化麻醉药合用致心律失常"},{"name":"芬太尼（镇痛）","dose":"25–50 μg 静脉缓慢推注，按镇痛评分每 10–15 min 追加，年老/休克者减半","note":"血流动力学相对稳定，可用于创伤镇痛；给药前完成腹部评估，避免大剂量掩盖腹膜刺激征；呼吸抑制者备纳洛酮","renal":"肾功能不全时反复给药可蓄积，延长间隔","hepatic":"肝功能不全者清除减慢，减量","interact":"与苯二氮䓬类合用致呼吸抑制；与 CYP3A4 抑制剂（唑类、大环内酯）合用作用增强"},{"name":"破伤风人免疫球蛋白 + 破伤风类毒素","dose":"破伤风人免疫球蛋白 250 IU 肌注（伤口污染重、受伤 >6 h 或免疫史不明者）；同时破伤风类毒素 0.5 mL 肌注，按程序完成后续接种","note":"所有穿透伤与污染伤口均应评估破伤风免疫状态；已全程免疫且 5 年内加强者可不重复","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫球蛋白同部位注射可中和疫苗，需更换注射部位"},{"name":"奥美拉唑（应激性溃疡预防）","dose":"40 mg 静脉滴注 qd，或 40 mg q12h（高危：机械通气 >48 h、休克、大出血）","note":"重症创伤、休克与机械通气者预防应激性溃疡出血；出血风险低者不需长期使用","renal":"肾功能不全无需调整","hepatic":"重度肝损减量，监测肝功能","interact":"抑制 CYP2C19，降低氯吡格雷活化（避免合用）；升高地西泮、苯妥英浓度"}],"nonDrug":["血流动力学不稳定（SBP <90 mmHg 对复苏无反应）或 FAST 阳性伴腹膜刺激征：立即剖腹探查；采用损伤控制策略（止血→填塞→临时关腹→ICU 复温纠正凝血，24–48 h 后二次探查）","脾损伤：AAST Ⅰ–Ⅲ 且稳定者非手术治疗（卧床、禁食、监测 Hb、备血）；有造影剂外溢行脾动脉栓塞（成功率 >90%）；手术优先保脾（缝合、部分切除、网片包裹），脾切除后接种肺炎链球菌、流感嗜血杆菌、脑膜炎奈瑟菌疫苗","肝损伤：Ⅰ–Ⅲ 级非手术治疗或血管造影栓塞；Ⅳ–Ⅴ 级手术行 Pringle 阻断（每次 15–20 min，间隔 5 min）、肝周填塞、清创缝合，必要时肝动脉结扎；严禁盲目深部缝合致血肿扩大","肠破裂：一期修补或切除吻合；腹腔污染重、休克、受伤 >6 h 者行损伤控制（肠外置/造口），系膜血供障碍者切除","胰腺损伤：Ⅰ–Ⅱ 级充分引流；Ⅲ 级远端切除（尽量保脾）+ 引流；Ⅳ–Ⅴ 级行胰十二指肠切除或清创引流，术后生长抑素与营养支持","介入：肝、脾、肾动脉造影栓塞用于造影剂外溢者；骨盆骨折腹膜后血肿行动脉栓塞；疑大血管损伤可行主动脉球囊阻断（REBOA）作为过渡"],"life":["非手术治疗期间禁食、卧床 48–72 h，每 6–12 h 复查 Hb 与腹部体征；2–3 个月内避免剧烈运动、碰撞与重体力劳动（迟发性破裂风险）","脾切除者建立疫苗接种记录卡，发热 >38.5 ℃ 立即就诊（暴发性脾切除后感染 OPSI），必要时预防性青霉素","出院后 1、3 个月复查超声/CT，观察血肿吸收、假性囊肿与腹腔脓肿；胰损伤者监测胰瘘与血糖","穿透伤患者筛查血源性感染（HBV、HCV、HIV），并按期随访"]},"prog":"脾损伤非手术治疗成功率 80%–90%，脾动脉栓塞止血成功率 >90%；肝损伤总死亡率 10%–15%，Ⅴ–Ⅵ 级可达 50%；肠破裂早期手术死亡率 <5%，延误 >24 h 升至 20%；胰腺损伤胰瘘发生率 20%–30%，多数经引流与营养支持自愈。","refs":["外科学（第 9 版）·腹部损伤","WSES 肝创伤指南（Liver trauma: WSES 2020 guidelines）","WSES 脾创伤分类与指南（Splenic trauma: WSES classification and guidelines, 2017）","ATLS 高级创伤生命支持（第 10 版，2018）","AAST 器官损伤分级（Organ Injury Scaling）2018 更新版：脾、肝、肾"]}]},{"id":"colorectal_polyp","name":"结直肠息肉","rank":44,"summary":"结直肠息肉按病理分腺瘤性、锯齿状与错构瘤性，癌变率随直径与绒毛成分上升；≤2 cm 以冷/热圈套与 EMR 内镜切除为主，>2 cm 或疑癌行 ESD/手术，>1 cm 或多发者 3 年复查结肠镜。","compare":[],"diseases":[{"id":"gs_colorectal_polyp","name":"结直肠息肉","aka":["Colorectal polyp","结直肠腺瘤","大肠息肉"],"rank":1,"basic":{"define":"结直肠黏膜表面向肠腔突出的隆起性病变。病理分肿瘤性（腺瘤性、锯齿状）与非肿瘤性（增生性、炎性、错构瘤性）；腺瘤—癌序列是最主要的结直肠癌发生途径。","risk":["年龄 ≥50 岁（40 岁后检出率明显上升）","高脂低纤维饮食、红肉与加工肉摄入多、饮酒、吸烟","肥胖（BMI ≥25）、缺乏运动、2 型糖尿病","一级亲属结直肠癌或腺瘤病史（风险约增加 2 倍）","炎症性肠病病程 >8–10 年（溃疡性结肠炎更显著）","遗传综合征：家族性腺瘤性息肉病（APC 突变）、Lynch 综合征（错配修复基因）"],"epi":"50 岁以上人群结肠镜腺瘤检出率约 20%–30%，男性高于女性；约 85% 的结直肠癌经腺瘤—癌序列发生，平均历时约 10 年；家族性腺瘤性息肉病患者 40 岁前癌变率接近 100%。"},"patho":"腺瘤经 APC 失活→KRAS 突变→TP53 缺失多步骤演进为癌，体积增大、绒毛成分增多与异型增生加重使癌变率上升。锯齿状途径经 BRAF 突变与 MLH1 启动子甲基化，传统锯齿状腺瘤与无蒂锯齿状病变（SSL）好发于右半结肠，易漏诊且进展较快。错构瘤性息肉（幼年性、Peutz-Jeghers）本身恶变率低，但综合征患者全消化道癌风险升高。","dx":{"criteria":["多数无症状，经筛查结肠镜发现；可有便血（鲜红附着粪便表面）、黏液便、排便习惯改变、下腹隐痛","右半结肠大息肉可致慢性缺铁性贫血（Hb <120 g/L、MCV <80 fL）与乏力，易被误诊为痔或肠易激","结肠镜下记录：部位、大小（用张开活检钳约 7 mm 或圈套器测量）、形态（Paris 分型 0-Ⅰp/Ⅰs/Ⅱa/Ⅱb/Ⅱc）、数目、表面结构（NBI/放大内镜 JNET 分型）","病理为确诊依据：管状腺瘤、绒毛状腺瘤（绒毛成分 >75%）、管状绒毛状腺瘤（25%–75%）、锯齿状病变（增生性息肉、SSL、传统锯齿状腺瘤）、错构瘤性","癌变高危特征：直径 >1 cm、绒毛成分 >25%、高级别上皮内瘤变、≥3 个腺瘤、广基扁平（LST）或表面凹陷","癌变率随大小上升：<5 mm 腺瘤 <0.1%；5–10 mm 约 1%；1–2 cm 约 10%；>2 cm 约 30%–50%（绒毛状更高）","粪便免疫化学试验（FIT）阳性（按试剂 cut-off，常用 100 ng/mL）提示需结肠镜；FIT 阴性不能排除息肉","遗传筛查：>100 枚息肉或 10–20 枚伴家族史疑 FAP（APC 基因）；按 Amsterdam/Bethesda 标准疑 Lynch 者查 MSI/dMMR"],"workup":["结肠镜为金标准，可同时切除；退镜时间 ≥6 min，右半结肠必要时翻转观察以减少 SSL 漏诊","染色内镜/放大内镜（NBI、BLI）判断腺管开口（pit pattern）或 JNET 分型，指导是否需 ESD 或外科手术","超声内镜：>2 cm 广基病变或疑黏膜下浸润，评估浸润深度与周边淋巴结","腹部增强 CT 或直肠 MRI：>2 cm 广基、疑癌变（JNET 2B/3、pit pattern Ⅴ）时分期，排除远处转移","实验室：血常规（贫血）、CEA、凝血功能（切除前停抗凝/抗血小板）","病理：所有切除标本送检，分块切除者标注部位与块数，评估切缘与浸润深度（T1 黏膜下浸润 <1000 μm 为 SM1）"],"grading":"按病理分肿瘤性（腺瘤：管状/绒毛状/管状绒毛状；锯齿状：增生性息肉/SSL/传统锯齿状腺瘤）与非肿瘤性（炎性、错构瘤性、淋巴样息肉）；按大小分微小 ≤5 mm、小 6–9 mm、大 ≥10 mm；按形态用 Paris 分型（0-Ⅰp、0-Ⅰs、0-Ⅱa、0-Ⅱb、0-Ⅱc、0-Ⅲ）；按异型增生分低级别与高级别；癌变分黏膜内癌（Tis）与黏膜下浸润癌（T1，按 SM1/SM2 分层）。"},"ddx":[{"name":"结直肠癌（gs_crc，消化道肿瘤大类）","point":"与本类中息肉的鉴别点：癌为质硬、脆、易出血的溃疡或菜花样肿块，表面结构紊乱（JNET 3、pit pattern Ⅴ），超声内镜/CT 见黏膜下浸润或淋巴结肿大，活检确诊；息肉表面光滑、有蒂或广基、可推动。>2 cm 广基息肉必须整块切除病理排除癌变。"},{"name":"家族性腺瘤性息肉病（FAP）","point":"结肠内数百至数千枚腺瘤（>100 枚）、多在 20–30 岁出现，常伴硬纤维瘤、骨瘤、视网膜色素上皮增生；散发性息肉通常 <10 枚。基因检测 APC 突变可确诊，需预防性结肠切除。"},{"name":"Peutz-Jeghers 综合征","point":"口唇/颊黏膜色素沉着 + 全消化道错构瘤性息肉（小肠为主），可致肠套叠；息肉病理为错构瘤（平滑肌树枝状分布），与腺瘤的腺体异型增生不同。"},{"name":"幼年性息肉病","point":"儿童多见，单发幼年性息肉常位于直肠、伴便血；息肉病型（>5 枚）有癌变风险。病理见囊性扩张腺体与炎症间质，无腺瘤样异型增生。"},{"name":"炎症性肠病假息肉","point":"溃疡性结肠炎/克罗恩病病程中，黏膜再生形成炎性假息肉，多发、形态不规则，周围黏膜有炎症、溃疡与瘢痕；病理为炎性肉芽组织，无腺瘤性改变，但需活检排除异型增生相关病变（DALM）。"},{"name":"结直肠黏膜下肿瘤（脂肪瘤/神经内分泌肿瘤/GIST）","point":"表面黏膜光滑、色泽正常，超声内镜见病变位于黏膜下层（脂肪瘤高回声、NET 低回声、GIST 低回声伴血流）；息肉起源于黏膜层，活检可区分。"},{"name":"痔/肛裂出血","point":"便血鲜红、滴血或便纸染血，伴肛门疼痛或脱出，肛门镜见痔核或裂口；结肠息肉出血多无痛、与粪便混合或附着表面，需结肠镜排除近端病变。"}],"tx":{"drug":[{"name":"复方聚乙二醇电解质散（肠道准备）","dose":"2–3 L 分次口服：检查前 1 日晚上 1 L + 检查当日术前 4–6 h 1–2 L，每 10–15 min 服 250 mL，至排出清水样便","note":"分次准备清洁度优于单次；末次服药距检查 ≥2 h；服药后走动促进排空，避免呕吐误吸","renal":"肾功能不全者需监测容量与电解质，避免脱水；心衰/肝硬化者减量并监测体重","hepatic":"失代偿肝硬化者慎用大容量准备，防低钠与肝性脑病","interact":"与其他口服药间隔 1–2 h；与利尿剂/ACEI 合用注意低钠、肾损"},{"name":"咪达唑仑 + 芬太尼（清醒镇静）","dose":"咪达唑仑 1–2 mg 静脉推注，必要时每次追加 0.5–1 mg；芬太尼 25–50 μg 静脉推注，按需追加 12.5–25 μg","note":"适用于门诊结肠镜；老年、肥胖、OSA 者减量；全程监测 SpO2 与血压，备氟马西尼与纳洛酮","renal":"肾功能不全者咪达唑仑代谢产物蓄积，减量","hepatic":"肝功能不全者清除减慢，减量并延长观察","interact":"与阿片类合用呼吸抑制；与 CYP3A4 抑制剂（唑类、大环内酯）合用镇静加深"},{"name":"丁溴东莨菪碱（解痉）","dose":"10–20 mg 静脉推注或肌注，检查前 5–10 min 给药，必要时 30 min 后重复 10 mg","note":"抑制肠蠕动便于观察与切除；青光眼、前列腺增生、心动过速者禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他抗胆碱药合用加重口干、尿潴留；与促动力药相互拮抗"},{"name":"塞来昔布（FAP 化学预防）","dose":"200–400 mg 口服 bid，长期使用需评估心血管与胃肠道风险","note":"仅用于家族性腺瘤性息肉病等高风险人群减少息肉负荷，不能替代结肠切除与内镜监测；散发性腺瘤不推荐常规使用","renal":"CrCl <30 mL/min 避免","hepatic":"Child-Pugh B/C 避免","interact":"与抗凝/抗血小板药合用增加出血；与 ACEI/ARB+利尿剂合用致肾损；与氟康唑合用升高血药浓度"},{"name":"阿司匹林（高危人群化学预防）","dose":"100 mg 口服 qd，长期服用","note":"对结直肠腺瘤/癌有二级预防证据，但增加消化道与颅内出血风险，不替代内镜随访；开始前评估出血风险与幽门螺杆菌状态","renal":"eGFR <30 慎用","hepatic":"肝硬化伴静脉曲张者禁用","interact":"与抗凝药、NSAIDs 合用出血风险叠加；与甲氨蝶呤合用增加骨髓抑制"}],"nonDrug":["≤5 mm 无蒂息肉：冷圈套息肉切除（CSP）或冷活检钳钳除；6–9 mm：CSP 为首选，完整切除率与热圈套相当且迟发出血少","10–20 mm：黏膜下注射后热圈套 EMR；>20 mm 或侧向发育型（LST）：EMR 分块切除或 ESD 整块切除，标本按 2–3 mm 连续切片病理","疑癌（JNET 2B/3、pit pattern Ⅴ、表面凹陷）：行 ESD 或外科切除；T1 黏膜下浸润 >1000 μm、脉管侵犯、低分化或切缘阳性者行肠切除+淋巴结清扫","随访间隔：低危（1–2 个 <10 mm 管状腺瘤、无高级别上皮内瘤变）5–10 年；高危（≥3 个腺瘤、任一 ≥10 mm、绒毛成分、高级别上皮内瘤变）3 年；>1 cm 或多发者 3 年复查；SSL ≥10 mm 或多发 3 年；FAP/Lynch 每年–2 年专科随访","分块切除或 >2 cm 病变：3–6 个月首次复查结肠镜评估切除部位瘢痕（活检排除残留）","抗凝/抗血小板药：择期内镜切除前按血栓风险停药（阿司匹林多不停，氯吡格雷停 5–7 天，华法林停 5 天并桥接），术后根据出血风险恢复"],"life":["减少红肉与加工肉，增加膳食纤维 25–30 g/d、蔬果与全谷物；戒烟限酒、每周 ≥150 min 中等强度运动","控制体重（BMI <25）与血糖，2 型糖尿病者定期筛查","45–50 岁起结肠镜筛查；一级亲属患癌者提前至 40 岁或比亲属发病年龄早 10 年开始","术后按风险分层复查，出现便血、排便习惯改变、不明原因贫血时提前复查"]},"prog":"内镜切除腺瘤可使结直肠癌发病率下降 70% 以上；高危腺瘤切除后 3 年进展期腺瘤检出率约 3%–10%，规范随访可进一步降低癌变与死亡风险。>2 cm 绒毛状腺瘤癌变率 30%–50%，需整块切除并短期复查；FAP 未手术者 40 岁前几乎均癌变。","refs":["国家癌症中心/中华医学会肿瘤学分会：中国结直肠癌筛查与早诊早治指南（2020，北京）","中华医学会消化内镜学分会：中国早期结直肠癌筛查及内镜诊治指南（2014 年，北京）","中华医学会消化内镜学分会：结直肠息肉门诊管理专家共识（2025，成都）","中国消化内镜诊疗相关肠道准备指南（2019，上海）","外科学（第 9 版）·结直肠息肉"]}]},{"id":"transplant","name":"器官移植","rank":45,"summary":"肾移植以 ABO/HLA/PRA 配型为前提、终身免疫抑制为代价；肌酐升高时先分排斥、CNI 肾毒、BK 病毒与感染四条线，移植肾穿刺活检是定诊与分型的关键。","compare":[],"diseases":[{"id":"gs_transplant","name":"器官移植（肾移植与排斥反应）","aka":["Renal transplantation","同种异体肾移植","移植肾排斥反应"],"rank":1,"basic":{"define":"将供者肾脏植入受者髂窝、以替代终末期肾病肾功能的外科治疗。同种异体移植需终身免疫抑制，排斥反应按发生时间与机制分为超急性、急性（细胞性/抗体介导）与慢性。","risk":["供受者 HLA 错配多（≥4/6 位点）、群体反应性抗体（PRA）>10% 的致敏受者","ABO 血型不相容或跨血型移植、既往输血/妊娠/移植史致敏","供者年龄 >60 岁、DCD（心脏死亡捐献）边缘供肾、冷缺血时间 >24 h","受者透析 >5 年、糖尿病、肥胖（BMI >30）、冠心病与外周血管病变","免疫抑制不足、自行减药或依从性差（青少年、抑郁患者）","CMV 血清学 D+/R−（供者阳性、受者阴性）为 CMV 病高危"],"epi":"我国每年肾移植约 1 万例，居实体器官移植首位；1 年移植肾存活率 >95%，5 年约 75%–80%，10 年约 60%；感染与心血管疾病是移植后主要死因。"},"patho":"同种异体识别经直接与间接提呈激活供者特异性 T 细胞，钙调神经磷酸酶通路（他克莫司/环孢素靶点）驱动 IL-2 转录与 T 细胞增殖，效应 T 细胞与供者特异性抗体（DSA）共同攻击移植物。超急性排斥由预存抗体（ABO/HLA）结合内皮→补体激活→血栓性微血管病，移植物迅速坏死。急性抗体介导排斥（ABMR）以 C4d 在管周毛细血管沉积、微血栓与内皮损伤为特征；慢性排斥表现为间质纤维化与肾小管萎缩（IFTA）、动脉内膜增厚，最终移植物失功。钙调神经磷酸酶抑制剂本身具肾血管收缩与肾小管毒性，可致条带状纤维化。","dx":{"criteria":["术前配型：ABO 血型相容（或按跨血型方案预处理）、HLA-A/B/DR 6 个位点配型（0–2 错配最佳）、PRA <10%（>10% 为致敏，>80% 为高致敏）、淋巴细胞毒交叉配型阴性（CDC-AHG <10%）与流式交叉配型阴性","术后肾功能：肌酐较基线升高 ≥26.5 μmol/L（0.3 mg/dL）或 ≥1.5 倍提示急性移植物功能不全；少尿 <0.5 mL/kg/h 持续 6 h 需紧急评估","超急性排斥：开放血流后数分钟至 24 h 内移植肾变硬、呈花斑状、无尿，术中冰冻见广泛血栓与中性粒细胞浸润，一旦发生需切除移植肾","急性排斥：多在术后 1 周–6 个月，发热、移植肾区胀痛、尿量减少、肌酐升高 ≥20%–30%、血压升高；超声阻力指数（RI）>0.8，需穿刺活检确诊","急性细胞性排斥（TCMR）Banff 分级：ⅠA 间质炎症 >25%、ⅠB >50%、ⅡA 中度动脉内膜炎、ⅡB 重度动脉内膜炎、Ⅲ 透壁性动脉炎伴坏死","慢性排斥/移植肾肾病：术后数月至数年肌酐缓慢升高、蛋白尿 >0.5 g/d、高血压与贫血；活检见 IFTA、动脉内膜增厚或慢性活动性 ABMR","药物浓度：他克莫司谷浓度（C0）0–3 个月 8–12 ng/mL、3–12 个月 6–10 ng/mL、>1 年 5–8 ng/mL；环孢素 C0 早期 150–300 ng/mL、C2 800–1200 ng/mL","DSA 与 C4d：术后 DSA 阳性（MFI 升高）提示 ABMR 风险；活检 C4d 在管周毛细血管沉积支持 ABMR 诊断"],"workup":["术前：ABO 血型、HLA 分型、PRA、交叉配型、CMV/EBV/乙肝/丙肝/HIV/结核筛查，心脏超声与髂动脉评估（钙化、狭窄）","术后每日肌酐、尿量、体重与血压；他克莫司谷浓度术后第 3 天起每周 2–3 次，稳定后每月 1 次","移植肾超声：术后即刻与每日（直至稳定），评估血流、RI、肾积水、血栓与周血肿","DSA 监测：术后 1、3、6、12 个月及肌酐升高时检测；高致敏者加密","移植肾穿刺活检：肌酐升高 >20%、蛋白尿 >0.5 g/d 或疑排斥时行超声引导穿刺，按 Banff 分类报告（TCMR、ABMR、IFTA、CNI 毒性）","感染监测：CMV DNA/pp65 每周–每 2 周（前 3 个月）、BK 病毒血 DNA 每月（前 6 个月）、PCP 临床与影像"],"grading":"按时间与机制分：超急性排斥（开放血流后分钟–24 h，抗体介导）、急性排斥（1 周–6 个月；急性细胞性 TCMR 按 Banff ⅠA/ⅠB/ⅡA/ⅡB/Ⅲ，急性抗体介导 ABMR）、慢性排斥（>6 个月，慢性活动性 ABMR、IFTA、移植肾动脉病变）。移植肾功能延迟恢复（DGF）定义为术后 1 周内需透析；急性肾损伤按 KDIGO 分期评估移植肾。"},"ddx":[{"name":"急性肾小管坏死/缺血-再灌注损伤（DGF）","point":"与本类中排斥反应的鉴别点：术后早期少尿、肌酐升高，但移植肾超声血流良好、无发热与肾区胀痛，他克莫司浓度在目标范围，活检无 C4d 沉积与动脉内膜炎，多在 1–2 周自行恢复；排斥多发生在术后 1 周后且伴炎症指标与 DSA 升高。"},{"name":"钙调神经磷酸酶抑制剂（CNI）肾毒性","point":"他克莫司谷浓度 >15 ng/mL，肌酐升高伴高钾、高尿酸、震颤，减量后改善；活检见肾小管空泡变性、条带状纤维化，无炎症浸润与 C4d 沉积。"},{"name":"BK 病毒肾病","point":"血 BK DNA >10^4 copies/mL、尿 Decoy 细胞阳性，活检见病毒包涵体、SV40 染色阳性与间质炎症（易误判为排斥）；处理以减少免疫抑制为主，加用抗排斥治疗会加重病毒复制。"},{"name":"急性肾盂肾炎/移植肾尿路感染","point":"发热、移植肾区叩痛、脓尿与尿培养阳性，可伴肾积水；抗感染后肌酐下降。排斥反应尿检以蛋白尿为主、尿培养阴性。"},{"name":"移植肾动脉狭窄/血栓","point":"术后 1–3 个月出现高血压、肌酐升高、超声见吻合口流速 >2.5 m/s 或紊乱血流，CTA/MRA 确诊；血栓者突发无尿、超声无血流，需急诊取栓。"},{"name":"血栓性微血管病（TMA）","point":"贫血、血小板 <100×10^9/L、LDH 升高、外周血见裂红细胞，活检见微血栓与内皮肿胀；需与超急性/ABMR 鉴别，治疗以血浆置换与停用致病药物为主。"},{"name":"原发病复发（IgA 肾病/膜性肾病）","point":"以蛋白尿（常 >1 g/d）与镜下血尿为主，肌酐升高较缓，活检免疫荧光见 IgA 或 IgG/C3 沉积；排斥以肌酐升高与炎症浸润为主。"},{"name":"药物相互作用致浓度异常","point":"加用唑类抗真菌药、大环内酯或地尔硫䓬后他克莫司浓度骤升，或利福平、卡马西平后骤降；伴震颤、高钾或肌酐波动，查药物清单与浓度即可识别。"}],"tx":{"drug":[{"name":"他克莫司（Tacrolimus）","dose":"0.05–0.1 mg/kg 口服 bid（或 0.15–0.2 mg/kg/d），术后 24–48 h 内启动；目标谷浓度 0–3 个月 8–12 ng/mL、3–12 个月 6–10 ng/mL、>1 年 5–8 ng/mL","note":"核心钙调神经磷酸酶抑制剂，需固定时间（q12h）空腹服用；肾毒性、震颤、高钾、高尿酸、新发糖尿病；CYP3A5 快代谢者需加量，建议缓释剂型 qd 提高依从性","renal":"移植肾功能延迟恢复时减量或延迟启动，配合巴利昔单抗诱导；急性肾损时监测谷浓度避免叠加毒性","hepatic":"主要经肝 CYP3A4 代谢，肝功能不全（Child-Pugh B/C）减量并密切监测谷浓度","interact":"CYP3A4 底物：唑类（氟康唑、伏立康唑、泊沙康唑）、大环内酯（克拉霉素、红霉素）、地尔硫䓬/维拉帕米、葡萄柚显著升高浓度；利福平、卡马西平、苯妥英、圣约翰草降低浓度；与 ACEI/ARB、保钾利尿剂合用致高钾"},{"name":"吗替麦考酚酯（MMF）","dose":"1 g 口服 bid（或麦考酚钠 720 mg bid），空腹或餐前 1 h；维持期可减至 0.5–0.75 g bid","note":"抗增殖药，抑制 IMPDH；胃肠道反应（腹泻、腹痛）常见，可换肠溶制剂；白细胞 <3×10^9/L 或血小板 <100×10^9/L 减量/停药；男女均需避孕（停药后女性 6 周、男性 90 天）","renal":"eGFR <25 mL/min 时不超过 1 g bid，密切监测血常规与感染","hepatic":"肝功能不全一般无需调整，但严重肝病伴低蛋白时游离药物增多，需监测毒性","interact":"与抗酸药/PPI 合用降低吸收（间隔 2 h）；与阿昔洛韦/更昔洛韦竞争肾小管分泌；利福平降低 MPA 暴露；活疫苗禁用"},{"name":"甲泼尼龙/泼尼松","dose":"术中甲泼尼龙 500–1000 mg 静脉滴注；术后第 1–3 天 250–500 mg/d 递减，改泼尼松 20–30 mg 口服 qd，3–6 个月减至 5–10 mg qd 维持","note":"三联方案的基础用药；感染、血糖升高、骨质疏松、消化性溃疡与体重增加常见；高免疫风险者不减停激素","renal":"遵说明书","hepatic":"肝功能不全时甲泼尼龙优于泼尼松（后者需肝转化）","interact":"与 CYP3A4 抑制剂（唑类）合用升高激素暴露；与 NSAIDs 合用增加消化道出血；降低降糖药疗效；与利福平合用疗效下降"},{"name":"巴利昔单抗（诱导治疗）","dose":"20 mg 静脉滴注，开放血流前与术后第 4 天各 1 次（共 2 剂）","note":"IL-2 受体拮抗剂，用于 DGF 高风险、老年或 CNI 需延迟启动者，减少早期急性排斥；过敏反应罕见，需备抢救","renal":"无需调整","hepatic":"遵说明书","interact":"与其他免疫抑制剂叠加增加感染风险；活疫苗禁用"},{"name":"兔抗人胸腺细胞免疫球蛋白（rATG）","dose":"诱导 1–1.5 mg/kg/d 静脉滴注 ×3–5 天；激素抵抗的急性细胞性排斥 1.5 mg/kg/d ×5–7 天","note":"强效 T 细胞清除，用于高免疫风险诱导与激素抵抗排斥；经中心静脉给药，前置抗组胺药与激素；血小板 <50×10^9/L 或白细胞 <2×10^9/L 暂停；CMV 再激活风险升高","renal":"无需调整，但需监测感染与血细胞","hepatic":"遵说明书","interact":"与其他免疫抑制剂叠加致机会性感染与 PTLD；活疫苗禁用"},{"name":"复方磺胺甲噁唑（SMZ-TMP，预防肺孢子菌肺炎）","dose":"SMZ 400 mg/TMP 80 mg，1 片口服 qd（或 2 片每周 3 次），术后即开始，疗程 6–12 个月（高危或 CMV 共感染者延长）","note":"预防 PCP 与部分尿路感染；磺胺过敏者改喷他脒 300 mg 雾化每月 1 次或氨苯砜 100 mg qd；注意高钾、肌酐升高（竞争肾小管分泌）与 G6PD 缺乏者溶血","renal":"CrCl 15–30 mL/min 减量 50%；<15 mL/min 遵说明书或改用喷他脒","hepatic":"遵说明书，重度肝病慎用","interact":"与华法林合用升高 INR；与甲氨蝶呤合用加重骨髓抑制；与 ACEI/ARB、保钾利尿剂合用致高钾"},{"name":"伐更昔洛韦（预防 CMV）","dose":"900 mg 口服 qd（肾功能正常）；D+/R− 高危用 3–6 个月，R+ 用 3 个月。按 CrCl 调整：50–69 为 450 mg qd；25–49 为 450 mg qod；10–24 为 450 mg 每周 2 次","note":"CMV 血清学 D+/R− 为最高危；用药期间每 1–2 周监测 CMV DNA 与血常规；中性粒细胞 <1.0×10^9/L 或血小板 <50×10^9/L 停药；致畸，需避孕","renal":"严格按 CrCl 调整剂量（见上），血液透析日透析后给药","hepatic":"肝功能不全无需调整，但需监测肝功","interact":"与 MMF 竞争肾小管分泌，叠加骨髓抑制；与齐多夫定合用加重粒细胞减少；丙磺舒升高血药浓度"},{"name":"更昔洛韦（CMV 病治疗）","dose":"5 mg/kg 静脉滴注 q12h（按 CrCl 调整），疗程 14–21 天，直至 CMV DNA 转阴；维持期可改伐更昔洛韦口服","note":"用于 CMV 肺炎、胃肠炎、视网膜炎；需中心静脉或外周大静脉，充分水化减少肾毒性；同时适当减少免疫抑制","renal":"按 CrCl 调整：50–69 为 2.5 mg/kg q12h；25–49 为 2.5 mg/kg qd；<25 遵说明书","hepatic":"遵说明书","interact":"与亚胺培南合用增加癫痫风险；与齐多夫定、MMF 叠加骨髓抑制；与丙磺舒升高浓度"}],"nonDrug":["供受体配型与脱敏：ABO 相容、HLA 0–2 错配优先；PRA >80% 者行血浆置换/IVIG 脱敏或配对交换（KPD）；边缘供肾（DCD、年龄 >60）采用低温机械灌注","手术：供肾植入髂窝，肾动脉与髂外/髂内动脉吻合、肾静脉与髂外静脉端侧吻合、输尿管与膀胱再植（Lich-Gregoir）+ 双 J 管，术后 4–6 周拔除","超急性排斥：一旦确认立即切除移植肾、恢复透析，再次移植需避开相应抗体并重新配型","急性排斥：超声引导穿刺活检按 Banff 分类指导治疗；细胞性→甲泼尼龙 500–1000 mg/d ×3 天冲击，抵抗者用 rATG；抗体介导→血浆置换+IVIG（100 mg/kg）+利妥昔单抗 375 mg/m²，必要时硼替佐米","慢性排斥/IFTA：无特效治疗，优化免疫抑制（减少 CNI 暴露、改用 mTOR 抑制剂）、控制血压 <130/80 mmHg、蛋白尿用 ACEI/ARB","移植后肿瘤与感染筛查：每年皮肤检查、PTLD 监测（EBV DNA）、结核与肝炎再激活评估"],"life":["终身规律服药，不可自行减量或停药；他克莫司固定 q12h 空腹服，避免葡萄柚、圣约翰草与自行服用中草药","每日测体重、血压、尿量与体温；肌酐升高 >20%、尿量减少 >1/3、发热 >38 ℃ 立即就诊","每年接种流感疫苗与肺炎疫苗（活疫苗禁用）；避免生食、接触宠物粪便与园艺土壤（弓形虫、隐球菌）","戒烟、防晒、控制体重与血糖；术后 1、3、6、12 个月随访，此后每 3–6 个月复查肌酐、浓度、尿蛋白与 DSA"]},"prog":"我国肾移植 1 年人/肾存活率 >95%/90%，5 年约 85%/75%；急性排斥发生率 10%–20%，其中 80%–90% 对激素冲击有效；慢性移植物失功与感染仍是 5–10 年失败的主因，感染是移植后 1 年内首要死因。","refs":["中华医学会器官移植学分会：中国肾移植排斥反应临床诊疗指南（2016 版）","中华医学会器官移植学分会：器官移植免疫抑制剂临床应用技术规范（2019 版）","中国医师协会器官移植医师分会：中国肾脏移植受者排斥反应临床诊疗指南（2025）","KDIGO 移植候选者评估与管理临床实践指南（2020）","外科学（第 9 版）·器官移植"]}]}]},"geriatric":{"categories":[{"id":"geriatric_syn","name":"老年综合征","rank":1,"summary":"跌倒、谵妄、衰弱与肌少症常相互交织，以老年综合评估（CGA）为核心，优先去除可逆诱因与非药物干预，避免过度镇静与身体约束。","compare":[{"diseaseId":"ge_frailty","dx":"Fried 表型 5 项中≥3 项（非刻意体重下降、疲乏、握力下降、步速减慢、活动量低）或 FRAIL 量表≥3 分；肌力与骨骼肌量低于同性别同龄标准定义肌少症","key":"慢性进行性储备下降，起病隐匿，以功能与肌肉量为核心指标"},{"diseaseId":"ge_falls","dx":"过去 1 年≥1 次跌倒即风险升高，≥2 次为反复跌倒；TUG ≥12 s、单腿站立 <5 s 提示步态/平衡受损","key":"以事件驱动的运动功能评估为主，重点找内外因（用药、视力、环境）"},{"diseaseId":"ge_delirium","dx":"急性起病（数小时至数天）、病程波动、注意力不集中，伴认知或意识水平改变；CAM 阳性（①+②且③或④）","key":"急性且波动，注意力障碍是核心，多可找到诱因（感染、药物、电解质）"}],"diseases":[{"id":"ge_frailty","name":"老年衰弱与肌少症","aka":["Frailty","Sarcopenia","衰弱综合征"],"rank":1,"basic":{"define":"衰弱是老年期生理储备下降、对内外应激易损性升高的临床状态；肌少症是进行性全身骨骼肌量与力量（及功能）下降的综合征，两者常并存并互为因果。","risk":["高龄（≥75 岁）","多重慢病与多重用药","营养不良、低蛋白摄入、咀嚼吞咽功能差","缺乏运动、长期卧床","认知障碍与抑郁","社会孤立、经济困难"],"epi":"我国社区老年人衰弱患病率约 10%–20%，住院与养老机构可达 40% 以上；60 岁以上人群肌少症患病率约 10%–20%，80 岁以上更高。"},"patho":"慢性低度炎症（IL-6、TNF-α）与线粒体功能下降使蛋白分解大于合成，Ⅱ型快肌纤维萎缩、神经肌肉接头退化；内分泌改变（睾酮下降、维生素 D 缺乏、胰岛素抵抗）与活动不足叠加，形成肌量减少—力量下降—活动减少的恶性循环，表现为步速慢、握力低与易跌倒。","dx":{"criteria":["Fried 衰弱表型：①非刻意体重下降（1 年 ≥4.5 kg 或 ≥5%）②自述疲乏 ③握力下降（男 <26 kg、女 <18 kg）④步速减慢（<0.8 m/s）⑤低体力活动；≥3 项为衰弱，1–2 项为衰弱前期","FRAIL 量表：疲乏、耐力下降、活动减少、体重下降、疾病>5 种，每项 1 分；≥3 分衰弱，1–2 分为衰弱前期","肌少症（AWGS 2019）：握力男 <28 kg、女 <18 kg 提示力量下降；四肢骨骼肌指数 DXA 男 <7.0、女 <5.4 kg/m²（BIA 男 <7.0、女 <5.7 kg/m²）；步速 <1.0 m/s 或 5 次起坐 ≥12 s 提示躯体功能下降","AWGS 2019 分类：肌量下降加力量下降为肌少症；再加功能下降为严重肌少症"],"workup":["握力计（优势手 2 次取大值）、6 m 步速、5 次起坐试验、TUG","体成分分析（DXA 或 BIA），小腿围男 <34 cm、女 <33 cm 提示风险","MNA-SF 营养评估，记录近 3–6 个月体重变化","血常规、白蛋白、前白蛋白、25-OH 维生素 D、肾功能、电解质、甲状腺功能、血糖","用药核查：致疲乏或肌病的药物（β 受体阻滞剂、镇静催眠药、他汀、过量降压药）","老年综合评估：认知、情绪、ADL/IADL、社会支持"],"grading":"病程分层：衰弱前期（Fried 1–2 项）、衰弱（≥3 项）；肌少症按 AWGS 2019 分为可能肌少症、肌少症、严重肌少症。"},"ddx":[{"name":"老年跌倒（ge_falls）","point":"与本类 ge_falls 的鉴别点：衰弱以持续性肌力与储备下降为主，跌倒是其后果之一；若跌倒突发、反复且与体位变化一致，应优先查药物性低血压、心律失常与视力环境因素，而非归于衰弱。"},{"name":"甲状腺功能减退","point":"TSH 升高、怕冷、水肿、反射延迟、血脂升高；衰弱老人甲减可仅表现为乏力与体重变化，需实验室排除。"},{"name":"抑郁与营养不良","point":"情绪低落、兴趣减退为主，GDS/PHQ-9 评估；伴低白蛋白、贫血与体重下降者需同时评估营养与消化吸收。"},{"name":"恶性肿瘤与慢性消耗性疾病","point":"短期明显体重下降伴食欲差、贫血、低白蛋白，需肿瘤筛查与炎症指标。"},{"name":"帕金森病","point":"静止性震颤、肌强直、运动迟缓，起病不对称，对左旋多巴有反应；单纯衰弱无震颤与强直。"}],"tx":{"drug":[{"name":"口服营养补充（乳清蛋白型）","dose":"每日额外补充能量 400–600 kcal、蛋白质 20–30 g，两餐间或睡前服用","note":"经口进食不足者使用；目标蛋白质 1.0–1.2 g/kg/d，均衡分配于三餐","renal":"eGFR <30 者蛋白 0.6–0.8 g/kg/d 并监测","hepatic":"遵说明书","interact":"与左旋多巴同服竞争氨基酸吸收，间隔 30–60 min"},{"name":"维生素 D3","dose":"800–1000 IU qd；25-OH-D <20 ng/mL 者首月可 1600–2000 IU qd，复测后维持","note":"改善肌力、减少跌倒相关损伤；3–6 个月复查 25-OH-D","renal":"CKD 者监测钙磷与 PTH","hepatic":"严重肝病活性化不足，可选骨化三醇 0.25 µg qd（遵医嘱）","interact":"与噻嗪类合用增加高钙血症风险"},{"name":"钙剂","dose":"元素钙 500–600 mg qd（含膳食总摄入 1000–1200 mg/d）","note":"与维生素 D 合用；胃酸缺乏者选柠檬酸钙","renal":"高钙血症、含钙结石者慎用","hepatic":"遵说明书","interact":"与左氧氟沙星、四环素、双膦酸盐间隔 2 h"},{"name":"睾酮（限确诊低睾酮男性）","dose":"遵说明书；需两次晨间睾酮确认低下后使用","note":"仅用于性腺功能减退者，需评估前列腺与心血管风险","renal":"遵说明书","hepatic":"肝功能异常者禁用","interact":"可增强华法林抗凝作用"}],"nonDrug":["抗阻训练为核心：每周 2–3 次渐进负荷，每次 20–30 min，联合平衡训练（太极）","营养支持：蛋白质均衡分配（每餐 25–30 g），必要时少量多餐","停用或减量致肌少/乏力的药物（镇静药、过量降压药、抗胆碱药）","口腔与吞咽功能维护、义齿修复，改善进食","对衰弱住院老人实施运动+营养+用药优化多学科干预"],"life":["每 3–6 个月复评握力、步速与体重","鼓励户外活动与日照，居家防跌倒改造","接种流感、肺炎球菌与带状疱疹疫苗，减少急性应激","评估家庭与社会支持，预防孤立"]},"prog":"衰弱与肌少症显著增加跌倒、住院、失能与死亡风险；衰弱前期经运动与营养干预可部分逆转，进入衰弱期后以延缓进展、维持功能为目标。","refs":["《老年人衰弱预防中国专家共识（2022）》","《肌肉减少症营养与运动管理中国专家共识（2023）》","AWGS 2019 肌少症共识（Asian Working Group for Sarcopenia）"]},{"id":"ge_falls","name":"老年跌倒","aka":["Falls","跌倒与跌倒风险评估"],"rank":2,"basic":{"define":"跌倒指意外倒地、躺倒或由高向低跌落于地面的事件；老年人 1 年内≥2 次为反复跌倒，需系统评估内外因并实施多学科干预。","risk":["年龄≥65 岁、既往跌倒史","多重用药（镇静催眠药、降压药、降糖药、抗胆碱药）","视力障碍、前庭功能下降、本体感觉减退","步态与平衡异常、肌少症、足部畸形","认知障碍、帕金森病、卒中后遗症","环境因素（灯光暗、地面湿滑、无扶手、鞋不合脚）","体位性低血压、心律失常、低血糖"],"epi":"跌倒是我国 65 岁以上老年人伤害死亡的首位原因；社区老年人每年约 30% 发生跌倒，其中约半数会再次跌倒。"},"patho":"跌倒为多因素叠加：感觉输入（视力、前庭、本体觉）减退、中枢整合（认知、锥体外系）障碍与运动输出（肌力、关节、足部）下降共同削弱姿势控制，再叠加药物性低血压、心律失常致脑灌注不足或环境障碍即可发生。跌倒后长时间卧位导致肌少、肺炎与压疮，形成失能循环。","dx":{"criteria":["有跌倒事件史即视为高危，需启动评估；1 年内≥2 次为反复跌倒","步态与平衡筛查：TUG ≥12 s、单腿站立 <5 s、BBS <45 分提示平衡受损","体位性低血压：卧位转立位 3 min 内收缩压下降≥20 mmHg 或舒张压下降≥10 mmHg","跌倒史需详问：时间、地点、先兆（头晕、心悸、黑矇）、用药变化、有无意识丧失"],"workup":["步态与平衡：TUG、单腿站立、5 次起坐，必要时 Tinetti 量表","神经系统：下肢肌力、本体感觉、Romberg、锥体外系体征、认知（MMSE/MoCA）","心血管：卧位与立位血压、心率，必要时动态心电图排除心律失常与晕厥","视力与听力筛查、鞋具与足部评估","血常规、电解质、血糖、肾功能、25-OH 维生素 D、甲状腺功能","用药核查：镇静催眠药、抗精神病药、降压药、利尿剂、α 受体阻滞剂、降糖药、抗胆碱能药"],"grading":"按场景分型：环境相关型（绊倒、滑倒）、内在因素型（晕厥、低血糖、低血压、认知障碍）、步态与平衡障碍型；随访强度按单次跌倒或反复跌倒划分。"},"ddx":[{"name":"老年衰弱与肌少症（ge_frailty）","point":"与本类 ge_frailty 的鉴别点：肌少症与衰弱是进行性储备下降的背景，跌倒为渐进性功能衰退的表现；若跌倒呈突发且能恢复至既往功能，应优先寻找急性诱因而非归因于衰弱。"},{"name":"晕厥（心源性、神经介导性）","point":"短暂意识丧失且快速自行恢复，伴黑矇、心悸或出汗；跌倒后不能回忆过程或无保护性反射者应警惕晕厥，需动态心电图与倾斜试验。"},{"name":"短暂性脑缺血发作/卒中","point":"突发单侧肢体无力、言语不清或视野缺损，数分钟至数小时缓解，需神经影像与 NIHSS 评估。"},{"name":"低血糖","point":"使用胰岛素或磺脲类者出现心慌、出汗、意识模糊，血糖 <3.9 mmol/L，纠正后迅速缓解。"},{"name":"帕金森病与正常压力性脑积水","point":"帕金森病伴静止性震颤与运动迟缓；正常压力性脑积水表现为步态冻结、认知下降与尿失禁三联征，影像见脑室扩大。"}],"tx":{"drug":[{"name":"维生素 D3","dose":"800–1000 IU qd","note":"改善平衡与肌力，合并缺乏者剂量上调","renal":"CKD 者监测血钙","hepatic":"遵说明书","interact":"与噻嗪类合用注意高钙血症"},{"name":"阿仑膦酸钠（合并骨质疏松者）","dose":"70 mg 每周 1 次，晨起空腹温水 200 mL 送服，服后直立 30 min 不进食","note":"仅用于骨质疏松，跌倒风险本身不是抗骨松治疗指征","renal":"eGFR <35 禁用","hepatic":"遵说明书","interact":"与钙剂、铁剂、抗酸药间隔 2 h"},{"name":"叶酸（仅高同型半胱氨酸血症者）","dose":"0.4–0.8 mg qd，需先查维生素 B12","note":"证据有限，不作常规推荐","renal":"遵说明书","hepatic":"遵说明书","interact":"与甲氨蝶呤、苯妥英钠相互作用"}],"nonDrug":["多学科跌倒门诊：平衡+力量训练每周 2–3 次，Otago 运动处方或太极","药物调整：停用或减量镇静催眠药、抗精神病药与致低血压药物","环境改造：照明、扶手、防滑地垫、去除门槛，鞋具防滑合脚","视力矫正、有指征者行白内障手术、验配助听器","跌倒后 48 h 内评估，无保护性反射者行头颅影像排除颅内出血","高危者可使用髋保护器（证据有限）"],"life":["教会患者跌倒后安全起身并配备呼叫设备","每半年复评步态、用药与居家环境","平衡与肌力训练长期坚持，避免长时间卧床"]},"prog":"一次跌倒后约半数老年人 1 年内会再次跌倒；髋部骨折后 1 年死亡率约 20%–30%，功能丧失率高。系统干预可减少跌倒约 30%。","refs":["《老年人跌倒干预技术指南（2011，原国家卫生部）》","《老年患者跌倒风险评估与干预专家共识（2021）》","《中国老年骨质疏松症诊疗指南（2022）》"]},{"id":"ge_delirium","name":"老年谵妄","aka":["Delirium","急性意识障碍","老年谵妄"],"rank":3,"basic":{"define":"谵妄是急性起病、病程波动、以注意力障碍为核心的神经精神综合征，常伴认知改变或意识水平改变，是老年住院与围术期常见并发症。","risk":["高龄（≥70 岁）、已有认知障碍或痴呆","疼痛、脱水、电解质紊乱","感染（泌尿道、呼吸道）","抗胆碱药、苯二氮䓬类、阿片类","手术、麻醉、ICU 环境","视力或听力剥夺、睡眠剥夺、身体约束"],"epi":"住院老年患者谵妄发生率约 10%–30%，髋部骨折手术后与 ICU 可达 50% 以上；谵妄使住院时间延长、死亡率增加，并升高出院后失能与痴呆风险。"},"patho":"多因素叠加导致神经递质失衡（乙酰胆碱不足、多巴胺过度、GABA 能增强）与神经炎症；围术期与感染时脑血流自动调节与血脑屏障功能下降进一步加重。已有认知障碍者脑储备下降，阈值更低，少量诱因即可诱发。","dx":{"criteria":["急性起病（数小时至数天）且病程波动","注意力障碍：难以维持或转移注意力，数字顺背/倒背、倒背月份出错","意识水平改变：嗜睡、淡漠或过度警觉","思维紊乱（语无伦次）或认知改变（定向障碍、幻觉、记忆下降）","CAM 阳性：①急性起病且波动 ②注意力障碍 ③意识水平改变或 ④思维紊乱；①+②且（③或④）即可诊断；ICU 用 CAM-ICU","运动亚型：高活动型（激越、幻觉）、低活动型（淡漠、嗜睡，最易漏诊）、混合型"],"workup":["入院 24 h 内完成首次 CAM 评估，此后每班次筛查","血常规、电解质、尿素氮/肌酐、血糖、血氨、血气、甲状腺功能","感染筛查：尿常规、胸片，必要时血培养","药物核查：抗胆碱药、苯二氮䓬、抗组胺药、阿片类、糖皮质激素","缺血性脑血管事件：局灶体征，必要时头颅 CT","疼痛评估（非语言表达者用 PAINAD）、便秘与尿潴留排查","严重度：CAM-S 短版 0–7 分，用于随访"],"grading":"运动亚型：高活动型、低活动型、混合型；严重度按 CAM-S 分轻度与重度。"},"ddx":[{"name":"老年衰弱与肌少症（ge_frailty）","point":"与本类 ge_frailty 的鉴别点：谵妄为急性、波动、以注意力障碍著称；衰弱是慢性进行性功能下降，注意力与意识通常完整。衰弱老人突发嗜睡、注意力涣散时应考虑谵妄。"},{"name":"老年跌倒（ge_falls）","point":"与本类 ge_falls 的鉴别点：跌倒是运动事件；谵妄可伴跌倒（低活动型尤易跌倒），但核心是注意力与意识改变。跌倒后精神状态改变需先排除颅内出血。"},{"name":"痴呆（阿尔茨海默病等）","point":"起病隐匿、记忆与认知缓慢下降，无急性波动；谵妄常叠加于痴呆之上，以起病时间与波动性区分。"},{"name":"抑郁","point":"情绪低落、兴趣减退持续数周，无意识水平波动，GDS/PHQ-9 评估；抑郁所致假性痴呆注意力通常保留。"},{"name":"非惊厥性癫痫状态","point":"持续或波动性意识改变、凝视、自动症，脑电图见持续痫样放电；病因不明的波动性意识障碍应做 EEG。"},{"name":"低血糖、低钠血症与尿毒症脑病","point":"血糖 <3.9 mmol/L、血钠 <125 mmol/L 或尿素氮显著升高，纠正后意识迅速改善。"}],"tx":{"drug":[{"name":"氟哌啶醇","dose":"0.25–0.5 mg 口服或肌注，按需每 4–6 h 重复，24 h 总量一般不超过 2–3 mg","note":"仅用于高活动型、有自伤伤人或不配合治疗者，非一线；QT 延长或帕金森病者避免","renal":"无需明显调整，按临床反应滴定","hepatic":"重度肝功能不全减量或避免","interact":"与胺碘酮、氟喹诺酮、昂丹司琼等延长 QT 药物合用增加心律失常风险；拮抗左旋多巴"},{"name":"喹硫平","dose":"12.5–25 mg 口服，必要时每 12 h 追加，一般不超过 50–100 mg/d","note":"可用于帕金森病相关谵妄；镇静与体位性低血压明显，需监测","renal":"遵说明书","hepatic":"肝功能不全起始剂量减半","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素）升高血药浓度；与其他镇静药合用过镇静风险"},{"name":"奥氮平","dose":"2.5 mg 口服或口崩片每日 1 次，最大 5 mg/d","note":"替代选择，注意代谢与过度镇静","renal":"遵说明书","hepatic":"重度肝功能不全减量","interact":"吸烟诱导 CYP1A2 降低疗效；氟伏沙明升高血药浓度"},{"name":"右美托咪定（ICU 环境）","dose":"遵说明书；常用 0.2–0.7 µg/kg/h 静脉泵入，按镇静目标滴定","note":"用于机械通气或需轻度镇静者，需 ICU 监护","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 β 受体阻滞剂、镇静药合用加重心动过缓与低血压"}],"nonDrug":["优先去除诱因：治疗感染、纠正脱水与电解质紊乱、停用致谵妄药物、处理疼痛与尿潴留/便秘","定向提示：时钟、日历、反复告知时间地点与人物","促进昼夜节律：白天开灯活动，夜间安静昏暗","佩戴眼镜与助听器，安排家属陪伴，避免不必要约束、导尿管与静脉通道","早期活动、经口进食饮水，集中护理操作保障夜间睡眠","高危患者（术后、髋部骨折）实施多组分预防方案（HELP）"],"life":["出院前评估认知与功能，向家属告知谵妄后跌倒与功能障碍风险","出院后 1–3 个月复评认知与 ADL，必要时转记忆门诊","随访用药清单，避免再次使用高风险药物"]},"prog":"多数在数天至数周内缓解，但约 20%–30% 可持续数月；发作后 1 年内痴呆风险显著升高，住院期间谵妄与死亡率增加相关。","refs":["《中国老年患者术后谵妄防治专家共识（2021）》","《老年患者谵妄诊疗中国专家共识（2022）》","Inouye SK 等，CAM 谵妄诊断（Annals of Internal Medicine）"]}]},{"id":"geriateic_mgmt","name":"老年慢病与用药","rank":2,"summary":"以功能状态与预期寿命设定个体化目标：高血压小剂量起始、缓慢滴定并防体位性低血压；多重用药按 Beers/STOPP 系统审查与逐步去处方；终末期以症状控制、舒适与预立医疗照护计划为优先。","compare":[{"diseaseId":"ge_htn","dx":"非同日 3 次诊室血压≥140/90 mmHg；≥80 岁或衰弱者可放宽至≥150/90 mmHg 启动治疗；家庭血压≥135/85 mmHg","key":"目标个体化：一般 65–79 岁 <140/90，可耐受者 <130/80，80 岁以上或衰弱者 <150/90 不强行下调"},{"diseaseId":"ge_polypharmacy","dx":"同时使用≥5 种药物为多重用药，≥10 种为严重多重用药；存在 Beers/STOPP 所列潜在不适当用药、重复用药或剂量未按肾功能调整","key":"以完整用药清单与逐条标准审查为核心，去处方的目的是减少不良反应而非单纯减药数量"},{"diseaseId":"ge_palliative","dx":"不可治愈疾病、功能持续下降（KPS ≤50、PPS <40），预期生存期有限（常以 6 个月为参考）","key":"以症状控制与生活质量为目标，提前完成预立医疗照护计划与心肺复苏意愿沟通"}],"diseases":[{"id":"ge_htn","name":"老年高血压","aka":["Elderly Hypertension","老年高血压"],"rank":1,"basic":{"define":"年龄≥65 岁、未用降压药情况下诊室血压≥140/90 mmHg 的高血压；老年高血压以单纯收缩期高血压多见，血压波动大，体位性低血压与餐后低血压发生率高。","risk":["年龄、遗传与盐敏感性","肥胖与缺乏运动","高盐饮食、饮酒","睡眠呼吸暂停","慢性肾脏病与糖尿病","多重用药（NSAIDs、糖皮质激素、含甘草制剂）"],"epi":"我国 65 岁以上人群高血压患病率约 55%–60%，80 岁以上超过 70%，控制率仍不足 30%。"},"patho":"大动脉弹性下降、胶原增多使收缩压升高而舒张压相对降低（单纯收缩期高血压）；压力感受器敏感性下降与动脉硬化使血压变异性增大；肾小动脉硬化与容量调节异常进一步加重。脑血管自动调节能力下降，对血压骤降耐受力差，易致脑灌注不足与跌倒。","dx":{"criteria":["非同日 3 次诊室测量收缩压≥140 mmHg 和/或舒张压≥90 mmHg","家庭自测血压≥135/85 mmHg；24 h 动态血压≥130/80 mmHg（白天≥135/85，夜间≥120/70）","≥80 岁或衰弱者可参照≥150/90 mmHg 作为启动阈值","体位性低血压：卧位转立位 3 min 内收缩压下降≥20 mmHg 或舒张压下降≥10 mmHg，需常规筛查","动态血压区分白大衣高血压与隐蔽性高血压"],"workup":["规范测量：坐位 5 min 后测双上臂，取较高侧，间隔 1–2 min 测 2–3 次取均值","卧位与立位血压、餐前与餐后 30–60 min 血压","24 h 动态血压评估夜间血压下降与变异性","血常规、电解质、肾功能、血糖、血脂、尿微量白蛋白、心电图、超声心动图","靶器官损害：左室肥厚、eGFR 下降、尿蛋白、颈动脉斑块","用药与依从性核查，注意 NSAIDs 与拟交感药"],"grading":"分级：1 级 140–159/90–99，2 级 160–179/100–109，3 级≥180/110 mmHg；老年人另分单纯收缩期高血压（收缩压≥140 且舒张压<90 mmHg）。"},"ddx":[{"name":"多重用药致血压异常（ge_polypharmacy）","point":"与本类 ge_polypharmacy 的鉴别点：NSAIDs、糖皮质激素、甘草、减充血剂可升高血压；降压药过量或联合用药可致体位性低血压与头晕，需结合用药时间与血压曲线判断。"},{"name":"终末期低血压（ge_palliative）","point":"与本类 ge_palliative 的鉴别点：终末期血压下降常为衰竭表现，不应强行升压，而应评估舒适度；存在低灌注症状时可与家属讨论减停降压药。"},{"name":"肾实质性高血压","point":"肾功能不全伴蛋白尿、贫血、夜尿增多，血压难控；查尿常规、肾脏超声与 eGFR。"},{"name":"肾动脉狭窄","point":"难治性高血压伴腹部血管杂音，使用 ACEI/ARB 后血肌酐明显升高，需肾动脉超声或 CTA。"},{"name":"原发性醛固酮增多症","point":"低钾伴难治性高血压、肾上腺腺瘤，查醛固酮/肾素比值（停螺内酯 4 周以上）。"},{"name":"嗜铬细胞瘤","point":"阵发性头痛、心悸、多汗三联征伴血压骤升，查血或尿甲氧基肾上腺素。"}],"tx":{"drug":[{"name":"苯磺酸氨氯地平","dose":"起始 2.5–5 mg qd，最大 10 mg qd；80 岁以上或衰弱者从 2.5 mg qd 起始","note":"老年单纯收缩期高血压首选，降压平稳、少致体位性低血压","renal":"无需调整","hepatic":"肝功能不全起始 2.5 mg qd","interact":"CYP3A4 抑制剂（克拉霉素、伊曲康唑）升高血药浓度；与辛伐他汀合用需限制辛伐他汀剂量不超过 20 mg"},{"name":"氯沙坦","dose":"起始 25–50 mg qd，常用 50–100 mg qd","note":"合并蛋白尿、糖尿病、心衰或左室肥厚者首选 ARB/ACEI；用药 1–2 周复查血钾与肌酐","renal":"eGFR <30 起始 25 mg 并监测；双侧肾动脉狭窄禁用","hepatic":"重度肝功能不全减量","interact":"与保钾利尿剂或补钾剂合用致高钾；与 NSAIDs 合用削弱降压并增加肾损伤"},{"name":"培哚普利","dose":"起始 2–4 mg qd，最大 8 mg qd","note":"干咳发生率较高，不耐受者换用 ARB","renal":"eGFR <30 起始 2 mg qd 并监测肌酐","hepatic":"遵说明书","interact":"与保钾利尿剂合用致高钾；与 NSAIDs 合用增加急性肾损伤风险"},{"name":"吲达帕胺缓释片","dose":"1.5 mg qd 晨服","note":"合并水肿或心衰者可选用；监测血钾、血钠、尿酸与血糖","renal":"eGFR <30 慎用或禁用","hepatic":"严重肝病禁用（肝性脑病风险）","interact":"与地高辛合用增加低钾相关心律失常风险；升高锂浓度"},{"name":"氢氯噻嗪","dose":"12.5–25 mg qd","note":"小剂量即可；夏季或进食差时注意低钠、低钾与脱水","renal":"eGFR <30 效果差，慎用","hepatic":"遵说明书","interact":"与 NSAIDs 合用降低降压疗效"}],"nonDrug":["限盐<5 g/d、控制体重、规律有氧运动、限酒戒烟","优先单片复方制剂（CCB+ARB/ACEI 或 ARB+噻嗪类）简化方案","小剂量起始、缓慢滴定，每次调整后 2–4 周评估坐位与站立血压、肾功能与血钾","晨起服药为主，有体位性低血压者避免夜间加量或改用短效制剂","家庭血压监测结合远程随访，提高依从性"],"life":["每日固定时间家庭自测血压并记录，避免餐后立即测量","防跌倒：起立缓慢、夜间照明、热水浴后不立即起身","每 3–6 个月复查肾功能、电解质与用药清单","衰弱或预期寿命有限者与家属共同讨论放宽目标值"]},"prog":"降压治疗显著降低卒中与心衰风险，收缩压每降低 10 mmHg 卒中风险约降低 30%；但过度降压增加跌倒、晕厥与急性肾损伤，需个体化目标与随访。","refs":["《中国老年高血压管理指南（2023）》","《中国高血压防治指南（2024 年修订版）》","《高龄老年人血压管理中国专家共识（2022）》"]},{"id":"ge_polypharmacy","name":"多重用药与潜在不适当用药","aka":["Polypharmacy","Beers 标准","PIM","多重用药","去处方"],"rank":2,"basic":{"define":"同时使用≥5 种药物为多重用药，多病共存者常难以避免；其中存在无明确适应证、重复、相互作用或 Beers/STOPP 所列潜在不适当用药者，属不合理用药，需系统审查与去处方。","risk":["慢病共存≥3 种","多专科各自开药、缺乏统一处方记录","高龄、衰弱、认知障碍","eGFR 下降致药物蓄积","使用镇静催眠药、抗胆碱药、NSAIDs、长效磺脲类","自行服用中成药与保健品"],"epi":"我国社区老年人多重用药比例约 40%，住院老年人可超过 70%；约 10%–30% 的老年住院由药物不良反应所致，多数可预防。"},"patho":"随年龄增长肝血流与 CYP 酶活性下降、肾小球滤过率降低、体脂比例上升而总体水分下降，药物清除减慢、脂溶性药物蓄积；脑内胆碱能储备下降使抗胆碱负荷更易引起认知障碍与跌倒，多药联用还叠加酶抑制、QT 延长与出血风险。","dx":{"criteria":["用药数量：≥5 种为多重用药，≥10 种为严重多重用药","存在 Beers 2023 所列潜在不适当用药：长效苯二氮䓬、第一代抗组胺药、长期 NSAIDs、长效磺脲类、抗胆碱能药等","存在重复用药（同类药或复方中同类成分）、剂量未按肾功能调整或明确不良相互作用","出现与用药时间或剂量相关的药物不良反应症状","依从性问题：漏服、重复服用、自行停药"],"workup":["收集完整用药清单：处方药、非处方药、中成药、保健品、外用药，并核对实际服法","按 Beers 2023 或 STOPP/START v3 逐条审查","抗胆碱负荷量表（ACB ≥3 提示高负荷）、镇静负荷评估","CKD-EPI 与 Cockcroft-Gault 核对经肾排泄药物剂量","肝功能、电解质、血糖、INR 等与用药相关的实验室指标","评估适应证是否仍存在，预期获益与剩余寿命是否匹配"],"grading":"Beers 2023 三分类：老年人应避免使用的药物、特定疾病状态下应避免的药物、需谨慎使用的药物；STOPP/START 用于识别应停与应开始而未尽（如骨松治疗、疫苗）的项目。"},"ddx":[{"name":"老年高血压治疗过度（ge_htn）","point":"与本类 ge_htn 的鉴别点：审查中发现降压药过多并伴体位性低血压与跌倒，应减量或去处方；若血压仍高于个体化目标，则不因药多而停用，需权衡靶器官保护。"},{"name":"终末期用药边界（ge_palliative）","point":"与本类 ge_palliative 的鉴别点：终末期可停用二级预防药（他汀、双膦酸盐、部分降压药），依据是剩余寿命与获益，而非单纯药物数量；镇痛与止吐药不应受限。"},{"name":"药物不良反应与原发疾病混淆","point":"加药或增量后 2 周内出现头晕、跌倒、意识模糊或疲乏，应考虑药物性；加药前即有相同症状者需寻找基础疾病。"},{"name":"药物诱发谵妄","point":"抗胆碱药、苯二氮䓬、阿片类可诱发急性谵妄，停药或减量后 24–72 h 改善支持药物诱因。"}],"tx":{"drug":[{"name":"质子泵抑制剂（长期使用者复核）","dose":"遵说明书；无明确指征者按需减量或停用","note":"长期无指征使用增加艰难梭菌感染、骨折与低镁风险","renal":"遵说明书","hepatic":"遵说明书","interact":"奥美拉唑、埃索美拉唑降低氯吡格雷活化，可改用泮托拉唑"},{"name":"苯二氮䓬类（逐步减停）","dose":"遵说明书；每 1–2 周减少原剂量 25%，末段更慢（10%–25%）","note":"突然停药可致反跳性失眠与焦虑；失眠优先认知行为治疗","renal":"长期使用者药物蓄积，减量速度放慢","hepatic":"肝功能不全选短半衰期药或减量","interact":"与阿片类合用显著增加呼吸抑制与跌倒风险"},{"name":"非甾体抗炎药（长期使用者复核）","dose":"遵说明书；尽量最短疗程、最低有效剂量，或改用外用制剂","note":"老年长期使用增加消化道出血、急性肾损伤与心衰加重风险","renal":"eGFR <30 避免使用","hepatic":"重度肝功能不全避免","interact":"与抗凝药、抗血小板药、ACEI/ARB、利尿剂（三联）合用风险显著升高"}],"nonDrug":["建立一人一册完整用药清单，由家庭医生或药师统一管理","实施用药重整：每次转科、出院、新开处方时核对","按 STOPP/START 逐条审查，区分应停与应开始而未尽的项目","去处方遵循一次一项、逐步减量、随访复评、记录在案的原则，优先停镇静催眠药、抗胆碱药与不必要 NSAIDs","认知障碍者使用分装药盒或家属协助给药","医师、药师、护士与家属共同决策"],"life":["就诊时携带全部药盒与清单，包括中成药与保健品","不自行加服他人药物，不因广告擅自换药","每 6 个月复查用药清单与肾功能","了解可致跌倒的药物并掌握应对方式"]},"prog":"合理去处方可减少药物不良反应、跌倒与住院并改善生活质量；但需监测撤药反应与疾病复发，避免因怕药多而停用必要的心血管二级预防。","refs":["《中国老年人潜在不适当用药判断标准（2017）》","《老年人多重用药安全管理专家共识（2023）》","Beers Criteria 2023（美国老年医学会 AGS）","STOPP/START 标准 v3（2023）"]},{"id":"ge_palliative","name":"终末期疾病与舒缓医疗","aka":["Palliative Care","安宁疗护","临终关怀","Hospice"],"rank":3,"basic":{"define":"终末期指疾病不可治愈、功能持续下降、预期生存期有限（常以 6 个月为参考）的状态；舒缓医疗以缓解疼痛与其他症状、改善生活质量为目标，可与抗肿瘤治疗同步进行。","risk":["晚期恶性肿瘤（肺癌、肝癌、胃癌、胰腺癌等）","终末期心衰（NYHA Ⅳ级）、终末期 COPD（GOLD Ⅳ级）","终末期肾病（eGFR <15 或衰弱透析者）","重度痴呆终末期、卒中后长期卧床","高龄衰弱、多器官功能衰竭"],"epi":"我国每年死亡约 1000 万例，接受规范安宁疗护的比例仍不足 10%；随着 65 岁以上人口超过 3 亿，舒缓医疗需求快速增长。"},"patho":"终末期各器官储备进行性耗竭：恶性肿瘤经局部侵犯与转移导致疼痛、梗阻与恶病质；器官衰竭表现为低灌注、容量失衡与代谢紊乱。疼痛多为伤害性与神经病理性混合；呼吸困难由肺水肿、胸水、气道阻力增加与呼吸肌疲劳共同造成；临终期常见躁动与濒死喉音，处理目标转为症状控制而非治愈。","dx":{"criteria":["不可治愈的进行性疾病且功能持续下降（KPS ≤50 或 PPS <40）","预期生存期有限（常以终末期 6 个月作为安宁疗护准入参考）","多项症状负担重（ESAS 多项≥4 分），以舒适为优先","患者与家属对预后有合理理解，愿意讨论治疗目标","反复住院、ICU 依赖或无益检查治疗"],"workup":["症状评估：ESAS（疼痛、乏力、恶心、呼吸困难、焦虑、抑郁）逐项量化","疼痛评估 NRS 0–10 分，区分伤害性与神经病理性疼痛","功能与预后：KPS、PPS、ADL，必要时用姑息预后指数（PPI）","实验室检查限于对症状管理有益者（血钙、血糖、肾功能），避免无谓重复","心理社会评估：HADS 焦虑抑郁、灵性需求、家属照护负担","预立医疗照护计划：生前预嘱、医疗代理人、心肺复苏意愿"],"grading":"疼痛分级：NRS 1–3 轻度、4–6 中度、7–10 重度；功能分级：KPS 100 至 0（死亡），PPS 按活动、摄食与意识综合分级。"},"ddx":[{"name":"老年高血压在终末期的管理边界（ge_htn）","point":"与本类 ge_htn 的鉴别点：终末期血压下降多为衰竭表现，不应按常规目标强化降压；仅血压升高伴明显症状（头痛、烦躁）时处理，以舒适为导向。"},{"name":"多重用药（ge_polypharmacy）","point":"与本类 ge_polypharmacy 的鉴别点：舒缓医疗去处方幅度可更大（停他汀、双膦酸盐、长期口服降糖药），但不能因药多限制镇痛与止吐药。"},{"name":"谵妄（ge_delirium）","point":"与本类 ge_delirium 的鉴别点：终末期谵妄常伴可逆诱因（脱水、感染、药物），应先排查；临终期躁动以舒适性镇静为主，原则不同于急性谵妄。"},{"name":"抑郁与病理性哀伤","point":"患者或家属持续绝望、无价值感、兴趣丧失超过 2 周需心理支持与必要药物治疗；正常哀伤多在数周至数月内缓解。"}],"tx":{"drug":[{"name":"吗啡（口服即释）","dose":"起始 5–10 mg q4h，衰弱或未用过阿片者 2.5–5 mg；爆发痛备总量 1/6–1/10 的速效剂量，按需滴定","note":"癌痛首选，同时缓解呼吸困难；同时处方缓泻剂预防便秘","renal":"eGFR <30 代谢产物蓄积，减量并延长给药间隔，必要时改用芬太尼","hepatic":"重度肝功能不全减量","interact":"与苯二氮䓬、镇静药合用增加呼吸抑制；禁与单胺氧化酶抑制剂合用"},{"name":"羟考酮缓释片","dose":"起始 10 mg q12h（老年人常 5–10 mg q12h）；爆发痛用即释剂，剂量为日总量 1/6–1/10","note":"中重度癌痛维持治疗；注意便秘与谵妄","renal":"eGFR <30 减量","hepatic":"重度肝功能不全起始减半","interact":"CYP3A4 抑制剂（克拉霉素、伊曲康唑）升高血药浓度，可致呼吸抑制"},{"name":"芬太尼透皮贴剂","dose":"起始 12–25 µg/h，每 72 h 更换；阿片未耐受者不从贴剂起始","note":"适用于不能口服或肾功能不全者；发热与皮肤温度升高时吸收增加","renal":"相对安全，但需监测","hepatic":"遵说明书","interact":"CYP3A4 抑制剂相互作用强，需减量"},{"name":"加巴喷丁（神经病理性疼痛）","dose":"起始 100 mg qn，逐步加至 300 mg tid；剂量按肾功能确定","note":"神经侵犯性疼痛或带状疱疹后神经痛；与阿片联用可减少阿片用量","renal":"CrCl 30–59 者 200–700 mg/d 分次；CrCl <30 减半","hepatic":"遵说明书","interact":"与阿片合用增加镇静与呼吸抑制；抗酸药减少吸收，间隔 2 h"},{"name":"地塞米松（恶性肠梗阻、颅高压、疼痛辅助）","dose":"4–8 mg qd 或分次，短期使用后逐步减量","note":"改善食欲与脑转移相关头痛；注意高血糖、消化道出血与感染","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血；降低降糖药疗效"},{"name":"咪达唑仑（临终期躁动/舒适性镇静）","dose":"遵说明书；0.5–1 mg 皮下或静脉给药，按需滴定以达到舒适为目标","note":"仅用于难治性濒死期症状，需与家属充分沟通并记录双效原则","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与阿片类合用增加呼吸抑制"}],"nonDrug":["预先明确治疗目标，讨论并签署不实施心肺复苏与预立医疗照护计划","多学科团队（医师、护士、药师、社工、心理、志愿者）负责症状管理与家属支持","疼痛：阿片阶梯用药联合体位、冷热敷、放松训练等非药物措施","呼吸困难：仅低氧者氧疗，阿片滴定，风扇吹面与体位调整","恶性肠梗阻：鼻胃管减压、止吐药（甲氧氯普胺、奥曲肽），必要时姑息性手术","向家属解释濒死期表现（呼吸节律改变、末梢发绀与温度下降）并做哀伤辅导"],"life":["优先居家或安宁疗护病房照护，减少不必要急诊与住院","制定应急预案：爆发痛、呼吸困难、出血时的联系方式与用药方案","定期沟通愿望与情感表达，完善生前预嘱","患者离世后对家属提供哀伤随访与心理支持"]},"prog":"规范舒缓医疗可改善终末期患者生活质量与症状控制，减少无益的急诊与 ICU 入住；部分研究显示早期整合舒缓医疗可改善生活质量和部分人群的生存。","refs":["《安宁疗护实践指南（试行，2017，国家卫生计生委）》","《中国癌症疼痛诊疗规范（2018 年版）》","《预立医疗照护计划中国专家共识（2023）》","WHO Palliative Care Guidance"]}]},{"id":"geriatric_org","name":"老年脏器疾病","rank":3,"summary":"老年脏器病的共同点是诊断指标需按年龄与体型校正、治疗需按衰弱与肾功能校正：HFpEF 重容量管理与 SGLT2i，不以强心减负为目标；CKD 用 CKD-EPI 2021 估 eGFR 并逐药核剂量；骨质疏松以 FRAX 与既往脆弱骨折定治疗门槛，三者均需同步评估跌倒与多重用药。","compare":[{"diseaseId":"ge_hfpef","dx":"心衰症状和/或体征，LVEF ≥50%，NT-proBNP 升高（非急性 ≥300 pg/mL；急性按年龄分层：<50 岁 450、50–75 岁 900、>75 岁 1800 pg/mL）或 BNP ≥100 pg/mL，伴 E/e′ >14 或左房容积指数 >34 mL/m² 等结构/功能异常；需排除淀粉样变、瓣膜病与肺病","key":"射血分数正常、舒张功能受损为核心，治疗以 SGLT2i 和容量管理为基石，不以强心利尿快速减负为目标"},{"diseaseId":"ge_ckd","dx":"肾结构或功能异常持续 ≥3 个月：eGFR <60 mL/min/1.73 m²（CKD-EPI 2021）和/或 UACR ≥30 mg/g；按 G1–G5 与 A1–A3 双指标分层","key":"以 eGFR 与白蛋白尿双指标分层；所有经肾排泄药按 eGFR 或 Cockcroft-Gault 逐一调整"},{"diseaseId":"ge_osteoporosis","dx":"DXA 股骨颈、全髋或腰椎 T 值 ≤ −2.5；或已发生髋部/椎体脆弱骨折（无论 T 值）；或 FRAX 10 年主要骨质疏松性骨折 ≥20%、髋部骨折 ≥3%","key":"以 FRAX 与既往脆弱骨折作治疗切点；唑来膦酸 5 mg 静脉每年 1 次用于高危或口服依从性差者"}],"diseases":[{"id":"ge_hfpef","name":"老年射血分数保留心衰","aka":["HFpEF","射血分数保留型心力衰竭","舒张性心衰","Diastolic Heart Failure"],"rank":1,"basic":{"define":"射血分数保留心衰（HFpEF）指具有心衰症状和/或体征、左室射血分数（LVEF）≥50%，并存在左室舒张功能不全或左房扩大等心脏结构/功能异常证据的临床综合征。老年患者约占全部心衰的一半以上，以女性、肥胖、高血压、房颤、糖尿病与 CKD 者高发。","risk":["高龄（≥70 岁）与女性","长期高血压致左室肥厚与心肌僵硬度增加","心房颤动","肥胖、糖尿病与代谢综合征","慢性肾脏病与贫血","衰弱、肌少症与活动受限","睡眠呼吸暂停"],"epi":"我国心衰患病率约 1.3%，65 岁以上约 5%，80 岁以上超过 10%；HFpEF 占老年心衰一半以上，1 年再住院率约 20%–30%，5 年死亡率与射血分数降低型心衰相近。"},"patho":"老年心肌间质纤维化与胶原交联增加、钙处理与肌丝磷酸化受损，使舒张期松弛延迟、左室僵硬度升高；肥胖相关系统性炎症、心外膜脂肪与微血管内皮炎症进一步加重心肌僵硬度。左房压升高使活动后肺毛细管楔压骤升而出现呼吸困难，常合并房颤、变时功能不全与右心功能不全。老年患者症状常以活动耐量下降、乏力为主，而非典型端坐呼吸。","dx":{"criteria":["心衰症状（劳累性呼吸困难、乏力、活动耐量下降）和/或体征（颈静脉怒张、肺部啰音、下肢水肿）","LVEF ≥50%（超声心动图双平面 Simpson 法）","利钠肽升高：非急性 NT-proBNP ≥300 pg/mL；急性按年龄分层 450（<50 岁）/ 900（50–75 岁）/ 1800 pg/mL（>75 岁）；BNP ≥100 pg/mL","超声结构/功能异常：E/e′ >14、左房容积指数 >34 mL/m²、左室质量指数升高、三尖瓣反流速度升高或肺动脉压升高","H2FPEF 评分 ≥6 分高度可能、≤1 分基本排除；HFA-PEFF 评分亦可辅助","需排除限制型心肌病、心脏淀粉样变（高龄、低电压、室壁增厚，查血清游离轻链与 ⁹⁹ᵐTc-PYP 显像）、瓣膜病与慢性肺病"],"workup":["NT-proBNP/BNP 及其年龄分层判读","经胸超声心动图：LVEF、E/e′、左房容积、右心功能、瓣膜与室壁厚度","心电图与动态心电图，评估房颤、房室传导与心律失常","血常规、肾功能、电解质、肝功能、血糖、甲状腺功能、铁蛋白与转铁蛋白饱和度","6 分钟步行或 4 m 步速、握力，结合衰弱量表判断治疗耐受度","胸片、肺功能（排除 COPD）与睡眠呼吸监测（肥胖或打鼾者）"],"grading":"按 NYHA 心功能分级（Ⅰ–Ⅳ级）；另按表型分为高血压型、肥胖代谢型、房颤型与淀粉样变型，表型决定治疗重点。"},"ddx":[{"name":"老年慢性肾脏病（ge_ckd）","point":"与本类 ge_ckd 的鉴别点：CKD 因水钠潴留可有水肿与呼吸困难、利钠肽升高，但超声无 E/e′ 升高或左房扩大，且以 eGFR 下降与 UACR 升高为客观异常；两者常并存，应先查 eGFR 与 UACR 判断水肿来源。"},{"name":"老年骨质疏松与脆弱骨折（ge_osteoporosis）","point":"与本类 ge_osteoporosis 的鉴别点：胸椎压缩骨折致驼背可限制胸廓活动、引起活动后气促，但无容量负荷体征且利钠肽正常；脊柱影像与 DXA 可区分。"},{"name":"慢性阻塞性肺疾病（COPD）","point":"长期吸烟史，肺功能 FEV1/FVC <0.70，活动后气促伴咳嗽咳痰，NT-proBNP 正常或轻度升高；可与心衰并存。"},{"name":"老年贫血（缺铁、肾性贫血）","point":"血红蛋白下降致乏力与活动耐量下降，BNP 可升高；查血常规与铁代谢，纠正贫血后症状改善支持贫血为主因。"},{"name":"心脏淀粉样变（ATTR-CM）","point":"高龄男性、腕管综合征史、心电图低电压与超声室壁增厚矛盾、纵向应变呈「心尖保留」型；核素显像可无创诊断，误诊为普通 HFpEF 会遗漏靶向治疗。"},{"name":"老年衰弱与肌少症导致的去适应","point":"以活动减少、乏力为主而无容量负荷体征，利钠肽正常，运动康复后改善；不应单凭乏力和高龄经验性使用利尿剂。"}],"tx":{"drug":[{"name":"达格列净","dose":"10 mg qd，晨服；eGFR ≥20 mL/min/1.73 m² 可启动，不必因肾功能轻度下降减量","note":"HFpEF 改善症状、减少心衰住院的证据最明确，老年首选；起效 2–4 周，起始 1–2 周血肌酐轻度上升 <30% 不必停药","renal":"eGFR 20–45 需先评估容量状态；eGFR <20 不推荐启动","hepatic":"重度肝功能不全慎用","interact":"与利尿剂合用增加容量不足；与胰岛素/磺脲类合用增加低血糖，需减量"},{"name":"恩格列净","dose":"10 mg qd，晨服；不按肾功能调整","note":"达格列净的替代方案；合并 2 型糖尿病者兼有降糖获益","renal":"eGFR ≥20 可用，<20 不推荐","hepatic":"遵说明书","interact":"与利尿剂合用需减量；CYP3A4 诱导剂（利福平）可降低疗效"},{"name":"螺内酯","dose":"起始 12.5 mg qd，可增至 25 mg qd；eGFR <45 或高龄者从 12.5 mg 隔日或 qd 起始","note":"减轻钠潴留、改善舒张功能；用药 1 周与 1 个月复查血钾与肌酐，血钾 >5.0 mmol/L 减量或停用","renal":"eGFR <30 慎用，12.5 mg 隔日起始并密切监测血钾","hepatic":"肝功能不全者监测电解质","interact":"与 ACEI/ARB、保钾利尿剂或补钾剂合用致高钾；与地高辛合用升高地高辛浓度"},{"name":"沙库巴曲缬沙坦","dose":"起始 50 mg bid（低血压或 eGFR <30 者 24/26 mg bid），2–4 周后逐步加倍至 200 mg bid","note":"合并高血压或容量负荷重者可选；收缩压 <100 mmHg 慎用","renal":"eGFR <30 起始 24/26 mg bid；与 ACEI 需间隔 36 h","hepatic":"重度肝功能不全禁用","interact":"禁与 ACEI 合用（血管性水肿，需间隔 36 h）；与保钾利尿剂合用致高钾；与西地那非合用致显著低血压"},{"name":"呋塞米","dose":"口服 20–40 mg qd 起始，按体重与水肿程度调整；急性加重可静脉 20–40 mg 后依尿量追加","note":"仅用于有容量负荷者，目标为体重回落至干重；过度利尿易致低血压、AKI 与跌倒","renal":"eGFR 下降时需加大剂量；与氨基糖苷类合用增加耳肾毒性","hepatic":"肝硬化者注意低钾诱发肝性脑病","interact":"与 NSAIDs 合用削弱利尿并增加肾损伤；与地高辛合用低钾增加中毒风险"},{"name":"比索洛尔","dose":"起始 1.25 mg qd，每 2 周递增至 2.5–5 mg qd；静息心率 <55 次/分或血压偏低时不加量","note":"用于合并房颤需控率或合并冠心病者；单纯 HFpEF 不常规加用，以免加重变时功能不全与乏力","renal":"eGFR <20 每日不超过 10 mg","hepatic":"重度肝功能不全减量","interact":"与维拉帕米、地尔硫䓬合用致心动过缓与传导阻滞"},{"name":"蔗糖铁（合并缺铁者）","dose":"200 mg 静脉滴注，每周 1–3 次，补至铁蛋白 >100 ng/mL 且转铁蛋白饱和度 >20%","note":"铁蛋白 <100 ng/mL，或 100–299 ng/mL 且转铁蛋白饱和度 <20% 者补铁可改善症状与生活质量","renal":"CKD 者按缺铁指标给药，监测铁蛋白与转铁蛋白饱和度","hepatic":"遵说明书","interact":"与口服铁剂间隔；首次给药备抗过敏处理"}],"nonDrug":["容量管理：每日体重、出入量与血压记录，3 日内体重增加 >2 kg 需调整利尿剂并就诊","运动康复：每周 3–5 次中等强度有氧加抗阻训练，改善 6 分钟步行距离与生活质量；衰弱者从坐位操与步行起步","合并房颤者按 CHA₂DS₂-VASc 评估抗凝，同时权衡出血与跌倒风险","筛查并治疗睡眠呼吸暂停、贫血与甲状腺功能异常","家庭监测加心衰门诊或远程随访，出院 7 天内复诊，减少再住院","终末期或极衰弱者以缓解呼吸困难与水肿为目标，必要时启动舒缓医疗讨论"],"life":["限钠 <5 g/d；有低钠血症者按医嘱限水 1.5–2 L/d","避免自行服用 NSAIDs、含麻黄碱或甘草的感冒药与中成药","接种流感与肺炎球菌疫苗，减少感染诱发急性加重","每日称重并记录，每 3 个月复查肾功能、电解质与 NT-proBNP","评估体位性低血压与跌倒风险，起立缓慢，夜间照明"]},"prog":"HFpEF 5 年死亡率约 50%–60%，再住院率高；SGLT2 抑制剂使心衰住院或心血管死亡风险降低约 20%。老年预后更多取决于衰弱、肾功能与共病负担，早期运动康复与容量管理可显著改善生活质量。","refs":["《中国心力衰竭诊断和治疗指南（2024）》","《射血分数保留的心力衰竭诊断与治疗中国专家共识（2023）》","《老年心力衰竭诊治中国专家共识（2022）》","2023 ACC/AHA/HFSA 心衰管理指南"]},{"id":"ge_ckd","name":"老年慢性肾病（eGFR 计算与用药调整）","aka":["CKD","慢性肾脏病","eGFR","CKD-EPI 2021","老年肾功能不全"],"rank":2,"basic":{"define":"慢性肾脏病（CKD）指肾脏结构或功能异常持续 ≥3 个月，表现为 eGFR <60 mL/min/1.73 m² 和/或尿白蛋白/肌酐比值（UACR）≥30 mg/g 等肾损伤标志。老年 CKD 多为高血压肾硬化、糖尿病肾病与肾动脉硬化所致，肌少症可使血肌酐偏低而 eGFR 被高估。","risk":["年龄增长（40 岁后 eGFR 每年约下降 1 mL/min/1.73 m²）","糖尿病与高血压","动脉粥样硬化与心力衰竭","长期使用 NSAIDs、PPI 或含马兜铃酸的草药","反复尿路梗阻、前列腺增生","肥胖、吸烟与高尿酸血症","造影剂与肾毒性药物暴露"],"epi":"我国成人 CKD 患病率约 8.2%，60 岁以上约 20%–30%，80 岁以上超过 30%；老年 CKD 知晓率不足 15%，多在查体或调整用药时才被发现。"},"patho":"肾小球硬化与肾小管间质纤维化致肾单位进行性丢失，健存肾单位高滤过形成「高滤过—硬化」恶性循环；RAAS 激活与醛固酮促进纤维化、氧化应激与炎症。老年肾脏浓缩功能下降、对脱水与容量负荷调节能力弱，易在感染、腹泻、利尿剂或 NSAIDs 作用下发生急性肾损伤（AKI）。CKD 使经肾排泄药物蓄积，同时影响维生素 D 活化、促红素生成与钾排泄，形成贫血、钙磷代谢紊乱与高钾血症。","dx":{"criteria":["eGFR <60 mL/min/1.73 m² 和/或存在肾损伤标志（UACR ≥30 mg/g、尿沉渣异常、影像结构异常、肾小管功能异常）持续 ≥3 个月","eGFR 用 CKD-EPI 2021（去种族系数）：eGFR = 142 × min(Scr/κ, 1)^α × max(Scr/κ, 1)^−1.200 × 0.9938^年龄 × 1.012（女性）；κ 男 0.9、女 0.7 mg/dL，α 男 −0.302、女 −0.241","药物剂量调整常用 Cockcroft-Gault：CrCl = [(140−年龄) × 体重 kg] / (72 × Scr mg/dL)，女性 ×0.85","分期：G1（≥90）、G2（60–89）、G3a（45–59）、G3b（30–44）、G4（15–29）、G5（<15）；白蛋白尿 A1（<30）、A2（30–300）、A3（>300 mg/g）","快速进展：eGFR 每年下降 >5 mL/min，或 3 个月内下降 >30%，需查梗阻、药物、心衰与脱水","UACR 应取晨尿，避免 24 h 内剧烈运动与发热；尿蛋白定量 >0.5 g/d 提示肾小球病"],"workup":["血肌酐、CKD-EPI 2021 eGFR、尿素氮；肌少或极端体重时加测胱抑素 C 联合评估","尿常规、UACR，必要时尿沉渣镜检与 24 h 尿蛋白","电解质（钾、钠、钙、磷）、碳酸氢盐、尿酸、白蛋白、血红蛋白、铁代谢、PTH、25-OH 维生素 D","肾脏超声（大小、皮质厚度、积水、结石、前列腺），必要时 CT 或磁共振","心电图与超声心动图（左室肥厚、心衰）评估心血管风险","用药清单逐条核对：二甲双胍、SGLT2i、ACEI/ARB、抗生素、抗凝药、加巴喷丁类、地高辛"],"grading":"KDIGO 分层：G1–G5 与 A1–A3 组合成风险热图；G3b 以上或 A3 为高危，需肾内科随访；G5 评估肾脏替代治疗，高龄衰弱者可选择保守（最大内科）治疗。"},"ddx":[{"name":"老年射血分数保留心衰（ge_hfpef）","point":"与本类 ge_hfpef 的鉴别点：心衰致肾灌注下降与静脉淤血，可出现 eGFR 一过性下降与肌酐升高（「心肾综合征」）；容量减轻后肌酐回落者以心衰为主，肌酐持续上升、蛋白尿明显且肾脏缩小者以 CKD 为主。"},{"name":"老年骨质疏松与脆弱骨折（ge_osteoporosis）","point":"与本类 ge_osteoporosis 的鉴别点：CKD 4–5 期可出现 CKD-MBD 相关骨折，表现为高磷、高 PTH、低 1,25-(OH)₂D，与原发性骨松不同；骨松诊断仍以 DXA 与 FRAX 为基础。"},{"name":"急性肾损伤（AKI）","point":"48 h 内血肌酐升高 ≥26.5 µmol/L 或 7 天内升至基线 1.5 倍、尿量减少；常有脱水、感染、造影剂或肾毒药物诱因，纠正后恢复；不足 3 个月不诊断 CKD。"},{"name":"糖尿病肾病","point":"糖尿病病程 ≥5–10 年、伴糖尿病视网膜病变、持续 UACR ≥30 mg/g 与 eGFR 下降；眼底检查与病程为关键鉴别点。"},{"name":"多发性骨髓瘤与轻链肾病","point":"老年贫血、高钙、骨痛加肾功能不全（CRAB）；血尿免疫固定电泳与游离轻链异常，不明原因 CKD 合并贫血与高钙需排除。"},{"name":"前列腺增生致梗阻性肾病","point":"男性夜尿增多、排尿困难、残余尿增多，超声见肾积水与膀胱壁增厚；解除梗阻后肾功能可部分恢复。"}],"tx":{"drug":[{"name":"氯沙坦","dose":"起始 25–50 mg qd，可增至 100 mg qd；2–4 周复查血钾与肌酐，肌酐升高 ≤30% 可继续并密切观察","note":"UACR ≥30 mg/g 且 eGFR ≥30 者首选；无蛋白尿的老年 CKD 不必常规使用，以免高钾与 AKI","renal":"eGFR <30 谨慎，起始后 1 周复查；双侧肾动脉狭窄禁用；腹泻或脱水时暂停","hepatic":"重度肝功能不全减量","interact":"与保钾利尿剂、补钾、复方磺胺甲噁唑合用致高钾；与 NSAIDs 合用增加 AKI 风险"},{"name":"达格列净","dose":"10 mg qd，eGFR ≥20 可用；不因 eGFR 下调而减量","note":"延缓 CKD 进展并减少心衰住院；起始后 1–2 周 eGFR 轻度下降属预期，不必停药","renal":"eGFR <20 不推荐启动；已在使用者进入透析后的取舍遵医嘱","hepatic":"重度肝功能不全慎用","interact":"与胰岛素/磺脲类合用注意低血糖；与利尿剂合用监测容量与泌尿生殖道感染"},{"name":"非奈利酮","dose":"按 eGFR 起始：≥60 者 20 mg qd，25–59 者 10 mg qd；4 周后按血钾调整；血钾 >5.0 mmol/L 不启动或减量","note":"用于 2 型糖尿病合并 CKD 且白蛋白尿者；起始与每次加量后 4 周复查血钾与 eGFR","renal":"eGFR <25 不推荐启动","hepatic":"重度肝功能不全不推荐","interact":"禁与强效 CYP3A4 抑制剂（克拉霉素、伊曲康唑、酮康唑）及保钾利尿剂合用；避免葡萄柚汁"},{"name":"复方 α-酮酸","dose":"每次 4–8 片，每日 3 次，随餐服用；按体重与蛋白摄入调整，遵说明书","note":"用于 G4–G5 低蛋白饮食（0.6 g/kg/d）时补充必需氨基酸；须保证足够热量","renal":"用于非透析期，高钙血症者慎用","hepatic":"重度肝功能不全慎用","interact":"与四环素、喹诺酮类同服影响吸收，间隔 2 h"},{"name":"碳酸氢钠","dose":"0.5–1.0 g，每日 2–3 次口服；目标血清碳酸氢盐 22–26 mmol/L","note":"用于代谢性酸中毒（HCO₃⁻ <22 mmol/L），可延缓 CKD 进展并改善营养状态","renal":"监测钠负荷与血压，心衰或水肿者慎用","hepatic":"遵说明书","interact":"改变尿液 pH，影响阿司匹林、锂等药物排泄"},{"name":"罗沙司他","dose":"按体重与血红蛋白起始，遵说明书；目标 Hb 100–120 g/L","note":"用于 CKD 肾性贫血（含非透析）口服治疗；需评估血栓风险与血压","renal":"CKD 3–5 期可用","hepatic":"重度肝功能不全不推荐","interact":"与他汀合用升高他汀暴露，需减量或换药；与磷结合剂间隔 1 h 以上"},{"name":"二甲双胍（eGFR 下降时的调整示例）","dose":"eGFR 45–59：最大 1000 mg/d；eGFR 30–44：不推荐起始，已用者减至 500 mg/d 并密切监测；eGFR <30：禁用","note":"老年 CKD 合并糖尿病常见，需逐次核对；急性病与造影检查期停药","renal":"eGFR <30 禁用；30–45 慎用并减量","hepatic":"重度肝功能不全禁用（乳酸酸中毒风险）","interact":"与碘造影剂合用增加乳酸酸中毒，检查前后停药；与利尿剂、NSAIDs 合用增加 AKI 风险"},{"name":"加巴喷丁（eGFR 调整示例）","dose":"eGFR 60–89：200–1200 mg bid；eGFR 30–59：200–700 mg qd；eGFR 15–29：200–700 mg 隔日；具体遵说明书","note":"老年神经病理性疼痛常用，未按肾功能调整易致嗜睡、跌倒与肌阵挛","renal":"按 CrCl 减量并延长间隔，血液透析后补量","hepatic":"遵说明书","interact":"与阿片类合用增加镇静与呼吸抑制"}],"nonDrug":["血压目标一般 <130/80 mmHg；≥80 岁或衰弱者 <140/90 mmHg 即可，避免过度降压致 AKI","蛋白摄入：G3 期 0.8 g/kg/d，G4–G5 非透析 0.6–0.8 g/kg/d 配合酮酸，警惕营养不良","限钠 <5 g/d；高钾者限钾；避免加工食品与含磷添加剂","避免 NSAIDs、含马兜铃酸草药与不必要造影剂；必须造影时评估风险并水化","接种流感、肺炎球菌与乙肝疫苗","G4 以上转肾内科，评估血管通路与保守治疗意愿；透析方式需与功能状态匹配"],"life":["就医时主动告知 CKD 分期与 eGFR，请医师核对药物剂量","腹泻、呕吐、发热或进食差时暂停 ACEI/ARB、SGLT2i、利尿剂与二甲双胍，并联系医生","每日自测血压与体重，注意水肿与尿量变化","每 3–6 个月复查肾功能、电解质、UACR 与血红蛋白；G4 以下每 1–3 个月","维持适度活动，避免因 CKD 过度限制蛋白而加重肌少与营养不良"]},"prog":"老年 CKD 进展速度差异悬殊，多数缓慢；控制血压、白蛋白尿与血糖，并联合 SGLT2i 与非奈利酮可使肾功能下降速度减慢约 30%–40%。心衰、感染与 AKI 是主要住院与死亡原因；G5 期若合并重度衰弱，保守治疗的生活质量可能优于透析。","refs":["《中国慢性肾脏病早期评价与管理指南（2024）》","《中国老年人慢性肾脏病诊治专家共识（2021）》","《慢性肾脏病诊疗指南（2023）》","KDIGO 2024 CKD 指南"]},{"id":"ge_osteoporosis","name":"老年骨质疏松与脆弱骨折","aka":["Osteoporosis","骨质疏松症","脆弱骨折","Fragility Fracture","FRAX"],"rank":3,"basic":{"define":"骨质疏松症是以骨量减少、骨微结构破坏、骨脆性增加和易骨折为特征的全身性骨病。老年骨质疏松为 70 岁以上或绝经后女性、65 岁以上男性的原发性骨质疏松；站立位或更低高度跌倒引起的骨折称脆弱骨折，常见于椎体、髋部、桡骨远端与肱骨近端。","risk":["高龄（≥65 岁女性、≥70 岁男性）","既往脆弱骨折（尤其椎体与髋部）","低体重（BMI <19）、肌少症与衰弱","长期糖皮质激素（≥5 mg 泼尼松等效 ≥3 个月）","跌倒风险高、视力与平衡障碍","吸烟、过量饮酒、缺乏负重运动","钙与维生素 D 不足、日照少","早绝经、性腺功能减退、甲亢、甲状旁腺功能亢进与 CKD"],"epi":"我国 50 岁以上人群骨质疏松患病率女性约 32%、男性约 6%，65 岁以上女性超过 50%；髋部骨折后 1 年死亡率约 20%，仅约 30% 患者恢复至骨折前活动能力。"},"patho":"骨重建由破骨细胞骨吸收与成骨细胞骨形成偶联完成，老年期性激素下降、维生素 D 缺乏与慢性炎症使吸收大于形成，骨小梁变细断裂、皮质骨孔隙化。跌倒冲击载荷超过骨强度即发生骨折；髋部骨折后制动、疼痛与手术应激迅速导致肌少症、肺炎、压疮与谵妄，形成「骨折—失能—再骨折」循环。椎体压缩骨折常隐匿，仅表现为身高缩短或驼背。","dx":{"criteria":["DXA 股骨颈、全髋或腰椎 L1–L4 T 值 ≤ −2.5 诊断为骨质疏松","已发生髋部或椎体脆弱骨折者，无论 T 值如何均诊断骨质疏松并需治疗","T 值 −1.0 至 −2.5 为骨量减少，≥−1.0 为正常","FRAX（中国模型）10 年主要骨质疏松性骨折 ≥20% 或髋部骨折 ≥3% 为高危，可启动治疗","椎体骨折识别：身高缩短 ≥4 cm、脊柱后凸或背痛，胸腰椎侧位 X 线或椎体骨折评估（VFA）见楔形/双凹变","骨转换标志物（PINP、β-CTX）用于疗效监测，不能替代 DXA 诊断"],"workup":["DXA 测股骨颈、全髋与腰椎；腰椎严重退变或骨折时以股骨颈为准","FRAX 计算（无 BMD 亦可，有 BMD 时加入股骨颈 T 值）","胸腰椎侧位 X 线或 VFA 筛查隐匿椎体骨折","继发性骨松筛查：钙、磷、碱性磷酸酶、25-OH 维生素 D、PTH、肝肾功能、甲状腺功能、睾酮（男性）、血清蛋白电泳与游离轻链","骨转换标志物：治疗前基线，治疗 3–6 个月复查","跌倒与肌少症评估：握力、步速、TUG、MNA-SF；必要时家居与视力评估","排除甲状旁腺功能亢进、甲亢、多发性骨髓瘤与骨转移"],"grading":"T 值分级：≥−1.0 正常、−1.0 至 −2.5 骨量减少、≤−2.5 骨质疏松；另分极高危（24 个月内发生髋部/椎体或多发骨折）。"},"ddx":[{"name":"老年慢性肾病（ge_ckd）","point":"与本类 ge_ckd 的鉴别点：CKD 4–5 期可发生 CKD-MBD（低 1,25-(OH)₂D、高磷、高 PTH）相关骨病，与原发性骨松不同；查 eGFR、PTH 与磷可区分，治疗须先纠正矿物质代谢。"},{"name":"老年射血分数保留心衰（ge_hfpef）","point":"与本类 ge_hfpef 的鉴别点：心衰致活动减少、利尿剂使用与摄食不足可加速骨丢失，但心脏症状与容量负荷体征是主要矛盾；两者并存时先稳定心衰，不宜过度限制饮食。"},{"name":"骨转移与多发性骨髓瘤","point":"疼痛进行性加重、夜间痛，伴贫血、高钙与肾功能不全；影像见溶骨性改变，免疫固定电泳与游离轻链异常，需血液科评估。"},{"name":"甲状旁腺功能亢进症","point":"血钙升高、PTH 升高、泌尿系结石与骨囊肿；原发性者以手术为主，不应单用双膦酸盐掩盖。"},{"name":"骨软化症（维生素 D 缺乏）","point":"骨痛、近端肌无力、碱性磷酸酶显著升高、25-OH 维生素 D 明显低下；补维生素 D 后骨痛与肌力改善，双膦酸盐对骨软化无效。"},{"name":"药物相关性骨痛（静脉双膦酸盐后）","point":"给药后 24–72 h 出现流感样症状（低热、肌痛）；若持续骨痛伴低钙，需与骨折或肿瘤骨痛区分，复查血钙与影像。"}],"tx":{"drug":[{"name":"唑来膦酸","dose":"5 mg 加入 100 mL 0.9% 氯化钠，静脉滴注不少于 15–30 min，每年 1 次；一般连续 3 年，极高危者可延长至 5–6 年","note":"用于高危、极高危及口服双膦酸盐不耐受或依从性差者；给药前纠正低钙与维生素 D 缺乏，给药后 1–2 周复查血钙","renal":"CrCl <35 mL/min 禁用；给药前必须计算 eGFR/CrCl 并查血肌酐","hepatic":"遵说明书","interact":"避免与氨基糖苷类、顺铂等肾毒性药合用；与钙剂分开输注；24–72 h 急性期反应可用对乙酰氨基酚对症"},{"name":"阿仑膦酸钠","dose":"70 mg 每周 1 次，或 10 mg qd；晨起空腹温水 200 mL 送服，服药后直立（不弯腰、不躺）30 min 且不进食","note":"口服双膦酸盐首选之一；反流性食管炎、吞咽困难或不能直立者禁用","renal":"eGFR <35 禁用","hepatic":"遵说明书","interact":"与钙剂、铁剂、抗酸药间隔至少 2 h；与 NSAIDs 合用增加消化道溃疡风险"},{"name":"地舒单抗","dose":"60 mg 皮下注射，每 6 个月 1 次","note":"可用于 eGFR 较低的老年患者；停药后骨密度迅速反弹、椎体骨折风险升高，不可漏用，停药需序贯其他抗骨松药","renal":"按 eGFR 不必调整，但 CKD 晚期低钙风险高，给药前纠正低钙","hepatic":"遵说明书","interact":"不与双膦酸盐联用；注意低钙与颌骨坏死风险"},{"name":"特立帕肽","dose":"20 µg 皮下注射，每日 1 次，疗程不超过 2 年","note":"用于多发椎体骨折或极高危老年患者；停药后需序贯抗骨吸收药","renal":"eGFR <30 禁用","hepatic":"遵说明书","interact":"与地高辛合用可因高钙增加心律失常风险；不与双膦酸盐同期使用"},{"name":"碳酸钙 D₃","dose":"每次 1 片（元素钙 600 mg + 维生素 D₃ 125 IU），每日 1–2 次随餐；元素钙总量 1000–1200 mg/d（含膳食）","note":"钙与维生素 D 是所有抗骨松药物的基础；胃酸缺乏或长期制酸者选柠檬酸钙","renal":"eGFR <30 或高钙血症者慎用，监测血钙与血磷","hepatic":"遵说明书","interact":"与左氧氟沙星、四环素、双膦酸盐间隔 2 h；与噻嗪类合用增加高钙风险"},{"name":"维生素 D₃","dose":"800–1200 IU qd；25-OH-D <20 ng/mL 者首月可 2000 IU qd 或分次补充，复查后调整","note":"改善肌力、降低跌倒；与钙剂协同","renal":"CKD 或 PTH 升高者可选骨化三醇 0.25 µg qd，遵医嘱","hepatic":"严重肝病活性化不足，可选活性形式","interact":"与噻嗪类、强心苷合用注意高钙"}],"nonDrug":["负重与抗阻运动（快走、抗阻训练、太极）每周 3–5 次，改善骨密度与平衡","髋部或椎体骨折后建立骨折联络服务（FLS）：12 个月内规范抗骨松治疗并复评依从性","防跌倒综合干预：环境改造、视力矫正、避免镇静药物、髋保护器","椎体压缩骨折：镇痛、支具，必要时间隙性椎体成形术","髋部骨折 24–48 h 内手术，围术期多学科管理，术后早期活动与谵妄预防","牙科治疗前评估颌骨坏死风险；治疗期间及停药后 1 年内避免不必要拔牙"],"life":["每日晒太阳 15–30 min，蛋白摄入 1.0–1.2 g/kg/d，戒烟限酒","按时用药：唑来膦酸每年 1 次，地舒单抗每 6 个月不可漏用","每 1–2 年复查 DXA，治疗 3–6 个月复查 PINP 与 β-CTX","告知牙科医师抗骨松药物使用史","新发背痛、身高缩短或轻微外伤后骨折立即就诊"]},"prog":"规范治疗可使椎体骨折风险降低约 40%–70%、髋部骨折降低约 40%–50%；但老年患者用药依从性常不足 50%，停药后骨密度迅速下降。既往椎体骨折者 2–3 年内再骨折风险最高，需尽快启动治疗。","refs":["《原发性骨质疏松症诊疗指南（2022）》","《中国老年骨质疏松症诊疗指南（2023）》","《老年人骨质疏松症诊疗专家共识（2021）》","FRAX 中国人群模型（2020 更新）"]}]},{"id":"geriatric_func","name":"功能与营养","rank":4,"summary":"以功能与营养为主线：肌少症按 AWGS 2019 用握力、步速与骨骼肌量分层，干预以抗阻训练加蛋白补充为核心；营养不良用 MNA-SF 筛查并以经口营养补充（ONS）为先；尿失禁与便秘先排查可逆因素，以行为治疗起步，避免长期导尿管与不当泻药依赖。","compare":[{"diseaseId":"ge_sarcopenia","dx":"AWGS 2019：握力男 <28 kg、女 <18 kg；5 次起坐 ≥12 s 或步速 <1.0 m/s；DXA 四肢骨骼肌指数男 <7.0、女 <5.4 kg/m²（BIA 男 <7.0、女 <5.7）。力量下降 + 肌量下降 = 肌少症，再加功能下降 = 严重肌少症","key":"以握力、步速与骨骼肌量三项客观指标分层，抗阻训练 + 蛋白 1.0–1.2 g/kg/d 为一线"},{"diseaseId":"ge_nutrition","dx":"MNA-SF 12–14 分正常、8–11 分有风险、0–7 分营养不良；或 BMI <18.5、近 3 个月体重下降 >5%，或 GLIM 表型+病因组合阳性","key":"筛查用 MNA-SF，治疗以经口可进食者的 ONS 加能量蛋白达标为目标，先处理可逆诱因"},{"diseaseId":"ge_incontinence","dx":"尿失禁：非自愿漏尿持续 ≥3 个月（压力性、急迫性、混合性）；便秘按罗马Ⅳ 标准，排便次数少、便干硬或排便费力/不尽感 ≥3 个月","key":"先排查可逆因素（感染、药物、便秘、活动受限），以行为治疗（膀胱训练、定时排便）为一线"}],"diseases":[{"id":"ge_sarcopenia","name":"肌少症（AWGS 诊断与阻力训练/蛋白补充）","aka":["Sarcopenia","骨骼肌减少症","AWGS 2019","老年肌少症"],"rank":1,"basic":{"define":"肌少症是以骨骼肌量减少、肌力下降和/或躯体功能减退为特征的进行性、全身性肌肉疾病，与跌倒、骨折、失能和死亡风险增加相关。按 AWGS 2019 分为可能肌少症（仅力量或功能下降）、肌少症（肌量加力量或功能下降）、严重肌少症（肌量、力量与功能均下降）。","risk":["高龄（≥65 岁，80 岁以上显著上升）","低体重、长期能量与蛋白质摄入不足","缺乏运动、久坐与长期卧床","慢性炎症性疾病（心衰、COPD、CKD、糖尿病、肿瘤）","多病共存与多重用药（糖皮质激素、PPI、他汀相关肌病）","牙齿缺失、咀嚼吞咽障碍与抑郁","跌倒史与骨折后制动"],"epi":"我国社区老年人肌少症患病率约 10%–20%，80 岁以上可达 30%–50%；养老机构与住院老人更高。肌少症老人跌倒风险约增加 2–3 倍。"},"patho":"随增龄发生运动单位重塑（α 运动神经元丢失致肌纤维再支配，Ⅱ型快肌纤维优先萎缩）、线粒体功能与蛋白合成效率下降；慢性低度炎症（IL-6、TNF-α）、胰岛素抵抗与低蛋白摄入使肌蛋白分解大于合成。性激素与维生素 D 不足进一步削弱肌力，活动减少与肌量下降互为因果，形成「废用—萎缩」循环。","dx":{"criteria":["AWGS 2019 肌力：握力男 <28 kg、女 <18 kg","AWGS 2019 躯体功能：5 次起坐 ≥12 s，或 6 m 步速 <1.0 m/s，或简易体能状况量表（SPPB）≤9 分","AWGS 2019 骨骼肌量：DXA 四肢骨骼肌指数（ASMI）男 <7.0、女 <5.4 kg/m²；BIA 男 <7.0、女 <5.7 kg/m²；小腿围男 <34 cm、女 <33 cm 可作替代筛查","分类：肌量下降加力量或功能下降为肌少症；肌量、力量与功能均下降为严重肌少症","筛查路径：小腿围或 SARC-F ≥4 分（SARC-CalF ≥11 分）提示需进一步评估","需排除继发原因：甲亢、骨软化、甲状旁腺功能异常、糖皮质激素肌病、恶性肿瘤与神经肌肉病"],"workup":["握力计（优势手 2 次取较大值）、6 m 常规步速、5 次起坐、SPPB、TUG","体成分分析（DXA 或 BIA）测 ASMI；卧位测小腿围（小腿最粗处）","营养评估：MNA-SF、24 h 膳食回顾或蛋白摄入估算","血常规、白蛋白、前白蛋白、25-OH 维生素 D、肌酐（可结合胱抑素 C）、TSH、睾酮（男性）、CRP","用药核查：糖皮质激素、他汀（肌痛伴 CK 升高）、长期 PPI、镇静药","肌力与功能呈非对称或快速下降时，行肌电图甚至肌活检排除神经肌肉病"],"grading":"AWGS 2019 三分类：可能肌少症、肌少症、严重肌少症；病因另分年龄相关原发性与疾病相关继发性。"},"ddx":[{"name":"老年营养不良（ge_nutrition）","point":"与本类 ge_nutrition 的鉴别点：营养不良以摄入不足与体重/白蛋白下降为核心，可伴肌量减少但握力与步速相对保留；肌少症以肌力与功能指标下降为核心。两者常共存，需分别评估蛋白摄入与握力/步速。"},{"name":"老年尿失禁与便秘（ge_incontinence）","point":"与本类 ge_incontinence 的鉴别点：慢性便秘加重腹压、影响活动意愿与盆底功能，长期可致活动减少而肌量下降；但肌少症本身不引起尿失禁，以排尿症状为主时应优先查泌尿与括约肌因素。"},{"name":"糖皮质激素性肌病","point":"长期激素后近端肌无力为主（蹲起、上楼困难），CK 正常，减量或停药后改善；须追问激素使用史。"},{"name":"甲状腺功能亢进与减退","point":"甲亢见消瘦、肌无力与震颤；甲减见乏力、水肿与肌酶升高。查 TSH 与 FT4 排除。"},{"name":"骨软化症与维生素 D 缺乏","point":"近端肌无力、骨痛、碱性磷酸酶升高、25-OH 维生素 D 低；补充维生素 D 后改善，与单纯肌少症不同。"},{"name":"帕金森病与卒中后偏瘫","point":"静止性震颤、肌强直伴运动迟缓，或单侧肢体无力；其肌量减少为继发，康复方案重点不同。"}],"tx":{"drug":[{"name":"乳清蛋白口服营养补充","dose":"每日 20–30 g 蛋白质，分两次于两餐间或抗阻训练后 30–60 min 内服用；总蛋白目标 1.0–1.2 g/kg/d（消耗性疾病可至 1.2–1.5 g/kg/d）","note":"膳食蛋白 <1.0 g/kg/d 者是核心适应人群；每餐 25–30 g 分散摄入优于集中一餐","renal":"eGFR <30 或透析者降至 0.6–0.8 g/kg/d 或按透析方案，需营养师指导","hepatic":"肝性脑病者限制动物蛋白并补充支链氨基酸，遵医嘱","interact":"与左旋多巴间隔 30–60 min，避免芳香族氨基酸竞争吸收"},{"name":"维生素 D₃","dose":"800–1000 IU qd；25-OH-D <20 ng/mL 者首月 1600–2000 IU qd，复查后调整","note":"改善肌力与平衡、降低跌倒；与钙剂联合对骨折预防更有效","renal":"CKD 者监测血钙与 PTH，必要时改用骨化三醇 0.25 µg qd（遵医嘱）","hepatic":"严重肝病选活性形式","interact":"与噻嗪类合用注意高钙血症"},{"name":"亮氨酸/支链氨基酸制剂","dose":"遵说明书；常见含亮氨酸 2–3 g/次，与蛋白补充同服","note":"部分研究示可刺激老年肌肉蛋白合成，证据有限，不作常规处方，仅在蛋白摄入达标困难时考虑","renal":"CKD 者慎用，避免额外氮负荷","hepatic":"肝性脑病者遵医嘱","interact":"与蛋白制剂同服无特殊禁忌"}],"nonDrug":["渐进抗阻训练为核心：每周 2–3 次，每肌群 2–3 组、8–12 RM，可用弹力带、坐位抬腿起步；单次 20–30 min","联合平衡与有氧训练：太极、八段锦、快走，每周 ≥150 min 中等强度","三餐均含优质蛋白（蛋、奶、鱼、瘦肉、大豆），必要时营养师制定食谱","口腔与吞咽评估，修复义齿、治疗牙周病，保障能咀嚼并吞咽蛋白食物","减停致肌少/肌病药物（激素减量、无指征 PPI 停用、他汀相关肌病评估）","住院老人早期活动与营养支持，减少制动","多学科管理（营养师、康复师、药师、护士）并开出家庭运动处方随访"],"life":["坚持抗阻运动，每 3 个月复评握力与步速判断是否改善","每日记录蛋白摄入，必要时用 ONS 补足","防跌倒：居家改造、避免夜间独行，跌倒后及时就医","接种流感与肺炎球菌疫苗，控制慢性炎症性疾病","戒烟限酒，保持日照与户外活动"]},"prog":"肌少症老人跌倒风险增加 2–3 倍，失能与死亡风险显著升高；抗阻训练结合充足蛋白可使肌力提高 20%–30%，改善步速与生活能力。衰弱前期部分可逆转，已进入严重肌少症者以维持功能与预防跌倒为目标。","refs":["《中国老年人肌少症诊疗专家共识（2021）》","AWGS 2019 肌少症共识（Asian Working Group for Sarcopenia）","《老年人营养不良与肌少症营养干预中国专家共识（2023）》","《中国老年患者营养支持技术专家共识（2021）》"]},{"id":"ge_nutrition","name":"老年营养不良（MNA-SF 与 ONS）","aka":["Malnutrition","营养不良","蛋白-能量营养不良","MNA-SF","ONS","口服营养补充"],"rank":2,"basic":{"define":"老年营养不良指因能量、蛋白质或其他营养素摄入不足或利用障碍导致的体重下降、肌肉与脂肪减少及功能受损状态，常见为蛋白-能量营养不良（PEM），可合并微量营养素缺乏（维生素 D、B12、铁）。筛查用 MNA-SF，诊断用 GLIM 或 MNA 长版。","risk":["高龄（≥70 岁）与衰弱","咀嚼吞咽障碍、牙齿缺失、义齿不合适","味觉嗅觉减退与食欲下降（生理性厌食）","认知障碍、抑郁与孤独进食","多重用药（PPI、二甲双胍、阿片类、地高辛）","急性病、手术、肿瘤、COPD、心衰与 CKD","社会经济因素：独居、贫困、行动不便"],"epi":"我国住院老年患者营养不良风险率约 40%–60%，社区老年人约 10%–20%，养老机构可超过 50%；营养不良使住院延长、感染与压疮风险增加、死亡率升高。"},"patho":"老年期食欲调节改变（瘦素与胆囊收缩素相对升高、胃排空延迟）与能量需求变化共同导致摄食减少；咀嚼吞咽障碍进一步限制食物选择，长期低蛋白使肌肉与内脏蛋白分解。急性疾病时炎症（IL-6、TNF-α）与厌食使分解代谢增强，形成「炎症—厌食—肌少」恶性循环，又削弱免疫与伤口愈合。","dx":{"criteria":["MNA-SF（6 项）：12–14 分正常，8–11 分有营养不良风险，0–7 分营养不良；0–11 分需进一步评估","MNA 长版（18 项）：≥24 分正常，17–23.5 分有风险，<17 分营养不良","GLIM 标准：至少 1 项表型（非自主体重下降 >5%、BMI <18.5 或肌肉量减少）+ 至少 1 项病因（摄食或吸收减少、疾病负担或炎症）","体重下降：近 3 个月 ≥5% 或 6 个月 ≥10% 为临床显著","BMI <18.5 kg/m² 提示营养不良；65 岁以上 BMI <20 亦可提示风险","微量营养素：25-OH 维生素 D、维生素 B12、叶酸、铁蛋白、锌"],"workup":["入院或就诊时用 MNA-SF 筛查，阳性者做 MNA 长版或 GLIM","体重、身高、BMI、近 3–6 个月体重变化与小腿围","24 h 膳食回顾或食物频次表估算能量与蛋白摄入；条件允许时用间接测热法","口腔、牙齿与吞咽功能评估（EAT-10、饮水试验）","白蛋白、前白蛋白、血常规、B12/叶酸、铁代谢、25-OH 维生素 D、电解质、肾功能、CRP","心理与社会评估：PHQ-9、孤独感、经济能力与供餐条件","不明原因体重下降者行消化内镜与甲状腺、肿瘤筛查"],"grading":"MNA-SF 三分类（正常、风险、营养不良）；MNA 长版分正常、风险与营养不良；另按体重下降比例与 BMI 分轻、中、重度。"},"ddx":[{"name":"肌少症（ge_sarcopenia）","point":"与本类 ge_sarcopenia 的鉴别点：肌少症以握力与步速下降为核心，肌量减少而摄食与体重可正常；营养不良以能量蛋白摄入不足与体重下降为核心。若握力正常而体重持续下降，先查摄入不足与器质性疾病。"},{"name":"老年尿失禁与便秘（ge_incontinence）","point":"与本类 ge_incontinence 的鉴别点：慢性便秘或腹胀致食欲下降、摄入减少，可继发营养不良；处理便秘后食欲与摄入改善，说明便秘为继发因素。"},{"name":"恶性肿瘤与慢性消耗性疾病","point":"短期明显体重下降伴贫血、CRP 升高、低白蛋白，需肿瘤筛查（胸腹 CT、内镜）；炎症性厌食常与营养不良并存。"},{"name":"抑郁症与社交孤立","point":"兴趣减退、早醒、无价值感、多日食欲不振，PHQ-9/GDS 评估；抗抑郁治疗与社交支持后进食改善。"},{"name":"甲状腺功能亢进与血糖控制不佳","point":"多食伴消瘦、心悸、手抖，或明显多尿多饮、血糖升高；查 TSH、FT4 与 HbA1c。"},{"name":"药物性厌食与味觉改变","point":"二甲双胍、PPI、地高辛、阿片类与部分抗抑郁药可致食欲减退、恶心与味觉异常；调整药物后改善。"}],"tx":{"drug":[{"name":"整蛋白型口服营养补充（ONS）","dose":"每次 200–250 mL（约 200–300 kcal），每日 2 次，于两餐之间服用；目标补充能量 400–600 kcal/d、蛋白质 20–30 g/d","note":"经口进食不足者首选；能量目标 25–30 kcal/kg/d、蛋白质 1.0–1.2 g/kg/d（应激期可 1.2–1.5）","renal":"eGFR <30 选低蛋白或肾病专用配方，监测血钾与血磷","hepatic":"肝性脑病者选支链氨基酸配方，遵医嘱","interact":"与左旋多巴间隔 30–60 min；与部分抗生素分开服用"},{"name":"短肽/预消化型肠内营养制剂","dose":"每次 200 mL，每日 2 次，按说明书配制，遵医嘱调整","note":"用于慢性胰腺炎、短肠综合征、重度吸收不良的老人；渗透压高，需缓慢小口服用","renal":"按肾功能选蛋白含量，监测电解质","hepatic":"遵说明书","interact":"管饲时勿与药物混合，给药前后冲管"},{"name":"维生素 B12（甲钴胺）","dose":"肌注 500 µg 隔日 1 次共 1–2 周，之后每 1–3 个月 500 µg 维持；轻度缺乏且吸收正常者可口服 1 mg qd","note":"长期 PPI、二甲双胍使用者与萎缩性胃炎老人易缺乏；缺乏可致乏力、贫血与周围神经病","renal":"遵说明书","hepatic":"遵说明书","interact":"与叶酸同补；单补叶酸可掩盖 B12 缺乏致神经损害"},{"name":"肠内营养粉（蛋白强化型，管饲备用）","dose":"遵说明书；按医嘱补充蛋白质 10–20 g/d 或能量 300–600 kcal/d","note":"用于经口摄入持续不足者，可作为 ONS 补充；经口不能进食且需长期支持时再考虑管饲，须评估衰弱与预后","renal":"肾病配方按 eGFR 选择","hepatic":"遵说明书","interact":"与口服药物分开 1 h 服用"}],"nonDrug":["提高食物热量密度：正常膳食中加油、全脂奶、蛋类与坚果粉，少量多餐（每日 5–6 次）","改善进餐环境与社交：鼓励与家人共同进餐，改善外观与气味，饭前适度活动刺激食欲","口腔与吞咽康复：义齿修复、治疗龋齿与牙周病、吞咽训练与改变食物性状（软食、糊状、增稠液体）","由营养师制定个体化食谱并随访，评估实际摄入量而非仅开补充剂","处理可逆诱因：停用致厌食药物、治疗便秘、管理抑郁与疼痛","经口摄入仍不足需支持时：短期鼻胃管、长期经皮内镜下胃造瘘（PEG），但衰弱与末期患者获益有限，需与家属讨论","住院老人执行营养筛查—评估—干预—监测流程（NRS-2002 与 MNA-SF 联合）"],"life":["每周固定时间称重并记录，体重下降 >5% 时就诊","独居或行动不便者利用社区送餐、老年食堂与家庭支持","ONS 安排在餐间饮用，避免替代正餐","每 1–3 个月复查体重、白蛋白与血红蛋白","与营养师与家庭医生定期随访，调整方案"]},"prog":"营养不良老人住院时间延长约 1.5–2 倍，感染、压疮、跌倒与死亡风险增加；ONS 与营养教育使能量与蛋白摄入提高 20%–40%，并降低再入院风险。早期识别与干预可部分逆转营养状态。","refs":["《老年患者营养评估与干预中国专家共识（2022）》","《中国老年营养筛查与评定标准专家共识（2023）》","MNA-SF（Mini Nutritional Assessment–Short Form）评估规范","GLIM 营养不良诊断标准（2019）"]},{"id":"ge_incontinence","name":"老年尿失禁与便秘","aka":["Urinary Incontinence","Constipation","尿失禁","便秘","膀胱过度活动症"],"rank":3,"basic":{"define":"老年尿失禁指非自愿的尿液漏出，持续 ≥3 个月，分压力性（腹压增加时漏尿）、急迫性（尿急伴不自主漏尿，常为膀胱过度活动）与混合性。老年便秘指排便次数减少、粪便干硬或排便费力、不尽感，按罗马Ⅳ 标准持续 ≥3 个月，需排除器质性梗阻。","risk":["高龄与女性多产（盆底松弛）","前列腺增生与膀胱出口梗阻","卒中、帕金森病、脊髓病变与糖尿病周围神经病变","认知障碍与活动受限（如厕困难）","利尿剂、抗胆碱药、钙通道阻滞剂（便秘）、阿片类","便秘本身加重尿失禁（膀胱内压与排便时腹压升高）","饮水不足、膳食纤维不足与长期卧床"],"epi":"我国社区老年人尿失禁患病率约 15%–30%，80 岁以上女性可达 40%，养老机构老人超过 50%；老年便秘患病率约 20%–30%，住院与卧床老人更高。"},"patho":"尿道括约肌与盆底肌随龄及多产退化使尿道闭合压下降，出现压力性尿失禁；逼尿肌不稳定收缩（OAB）与膀胱感觉过敏导致急迫性尿失禁，老年膀胱容量下降与夜间浓缩功能减弱致夜尿增多。便秘时粪便嵌塞压迫膀胱、增加腹压与残余尿，形成「便秘—尿失禁」互相加重。神经病变（糖尿病、卒中、帕金森）破坏排尿反射协调，导致逼尿肌-括约肌协同失调与充溢性尿失禁。","dx":{"criteria":["尿失禁：非自愿漏尿持续 ≥3 个月；分压力性（咳嗽、打喷嚏、提重物时漏尿）、急迫性（突发尿急伴漏尿）、混合性；另有充溢性（排空不全伴持续滴尿）与功能性（活动或认知障碍致无法如厕）","膀胱过度活动症（OAB）：尿急伴尿频与夜尿，伴或不伴急迫性尿失禁；3 天排尿日记日间排尿 ≥8 次或夜尿 ≥1 次","便秘（罗马Ⅳ）：排便 ≤2 次/周、粪干硬（Bristol 1–2 型）、排便费力、不尽感或需手法辅助，符合 ≥2 项且持续 ≥3 个月","充溢性尿失禁：排尿后残余尿 >100–150 mL 伴持续滴尿，提示出口梗阻或逼尿肌无力","警示症状（需专科与影像）：血尿、突发排尿困难、发热腹痛、体重下降或新发神经症状","可逆因素（DRIP）：谵妄、尿潴留、感染、药物、内分泌（高血糖/高钙）"],"workup":["3 天排尿日记（时间、尿量、漏尿、饮水、排便）","直肠指检（男性前列腺）与妇科检查（女性盆底与阴道萎缩）","尿常规与尿培养，排除感染与血尿","排尿后即刻残余尿超声，评估膀胱排空","血常规、血糖、电解质、血钙、TSH、肾功能","便秘伴报警症状（贫血、便血、体重下降）时行腹部平片或结肠镜","神经源性或术后等复杂病例行尿动力学检查","用药核查：利尿剂、抗胆碱药、钙拮抗剂、阿片类、三环抗抑郁药与镇静药"],"grading":"尿失禁按漏尿频率与护垫使用量分轻、中、重（1 h 尿垫试验）；便秘分为功能性便秘、慢传输型与盆底排便障碍型。"},"ddx":[{"name":"肌少症（ge_sarcopenia）","point":"与本类 ge_sarcopenia 的鉴别点：肌少症以握力与步速下降为主，可致活动受限与如厕困难（功能性尿失禁），但排尿本身正常；若步态与排尿障碍同时出现，应排查共同神经病因（如正常压力性脑积水）。"},{"name":"老年营养不良（ge_nutrition）","point":"与本类 ge_nutrition 的鉴别点：摄入减少与脱水可使便秘加重、尿液浓缩致尿频，但核心是体重与蛋白摄入下降；纠正便秘并补足水分后症状改善提示为继发改变。"},{"name":"尿路感染与前列腺炎","point":"尿频、尿急、尿痛伴发热或下腹不适，尿培养阳性；急性感染可诱发谵妄与尿失禁加重，抗感染后缓解。"},{"name":"膀胱结石、肿瘤与膀胱出口梗阻","point":"血尿、排尿中断、反复感染或残余尿增多；超声与膀胱镜确诊，需专科处理。"},{"name":"便秘的器质性病因（结直肠肿瘤、甲减、高钙、药物性）","point":"报警症状（便血、贫血、体重下降、排便习惯改变）或血钙、TSH 异常，需肠镜与实验室评估，不能仅按功能性便秘处理。"},{"name":"神经源性膀胱（糖尿病、卒中、帕金森、脊髓病变）","point":"排尿困难、残余尿增多或充溢性尿失禁伴下肢神经体征与糖尿病史；需尿动力学评估并制定导尿策略。"}],"tx":{"drug":[{"name":"索利那新","dose":"5 mg qd 起始，可增至 10 mg qd；eGFR <30 或中度肝功能不全者每日不超过 5 mg","note":"用于急迫性尿失禁/膀胱过度活动症；老年抗胆碱负荷高，警惕口干、便秘与认知影响，4–8 周评估疗效","renal":"eGFR <30 每日不超过 5 mg","hepatic":"中度肝功能不全每日不超过 5 mg；重度禁用","interact":"与琥珀酸美托洛尔合用升高其浓度；CYP3A4 强效抑制剂（酮康唑）升高本药浓度"},{"name":"米拉贝隆","dose":"25 mg qd 起始，可增至 50 mg qd；eGFR 30–59 每日不超过 25 mg","note":"β₃ 受体激动剂，无抗胆碱负荷，适合认知障碍或已便秘老人；注意血压升高","renal":"eGFR <30 不推荐；30–59 每日 ≤25 mg","hepatic":"重度肝功能不全不推荐","interact":"与地高辛合用升高地高辛浓度；强效 CYP3A4 抑制剂增加本药暴露"},{"name":"聚乙二醇 4000","dose":"每次 10–20 g，每日 1–2 次，溶于 200 mL 水或果汁；老年从 10 g/d 起始","note":"渗透性泻药，便秘一线；起效需 24–48 h，长期使用相对安全","renal":"遵说明书；大量液体负荷时注意电解质","hepatic":"遵说明书","interact":"与口服药物同服可能加快排便影响吸收，间隔 1–2 h"},{"name":"乳果糖","dose":"起始 15–30 mL/d（10–20 g），可增至 30–45 mL/d 分次；以每日 1–2 次软便为目标","note":"尤其适合合并肝病者；起效 1–2 天，初期可有腹胀排气","renal":"遵说明书","hepatic":"肝性脑病者可用于降血氨","interact":"与抗酸药同服降低疗效；制剂含少量糖，糖尿病患者注意血糖"},{"name":"普芦卡必利","dose":"1 mg qd 起始；老年与 eGFR <30 者从 1 mg qd 起始并观察","note":"用于对泻药反应不佳的慢性便秘；注意腹泻与心悸","renal":"eGFR <30 者 1 mg qd","hepatic":"重度肝功能不全禁用","interact":"与延长 QT 间期药物合用需谨慎"},{"name":"开塞露（甘油制剂，粪便嵌塞时）","dose":"1 支（10–20 mL）直肠给药，必要时使用；嵌塞者先灌肠（遵医嘱）后改口服方案","note":"仅用于急性或嵌塞，不作长期常规；直肠损伤或痔出血者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"无特殊"},{"name":"坦索罗辛（男性伴前列腺增生）","dose":"0.2 mg qd 睡前服，可增至 0.4 mg qd","note":"改善排尿困难与残余尿，减少充溢性尿失禁；睡前服用减少体位性低血压","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与降压药、PDE5 抑制剂合用加重低血压与头晕"}],"nonDrug":["行为治疗为一线：定时排尿（每 2–3 h）与膀胱训练，凯格尔盆底肌训练每日 3 组、每组 10 次，坚持 8–12 周","压力性尿失禁：盆底康复，必要时子宫托或吊带术（需评估功能与预期寿命）","便秘：定时排便（晨起或早餐后 30 min 内，利用胃结肠反射）、饮水 1.5–2 L/d（心衰与 CKD 按医嘱）、膳食纤维 25–30 g/d","如厕可及性：床旁便器、扶手、照明与去除障碍；认知障碍者定时引导如厕","停用或调整致尿失禁/便秘的药物（利尿剂、抗胆碱药、钙拮抗剂、阿片类）","避免长期留置导尿管；神经源性膀胱必要时清洁间歇导尿","盆底功能障碍者行生物反馈与排便训练"],"life":["记录排尿与排便日记，与医师讨论调整方案","保持每日活动与步行，促进结肠蠕动","夜间使用便器或夜灯，避免急行如厕跌倒","失禁者做好皮肤屏障护理，预防失禁性皮炎","每 3–6 个月复评症状、残余尿与药物清单"]},"prog":"老年尿失禁显著增加跌倒、失禁性皮炎、泌尿系感染与机构化风险；行为治疗加药物可使急迫性发作减少 50%–60%。便秘不处理可致粪便嵌塞、肠梗阻与谵妄，规律排便显著改善生活质量与如厕独立能力。","refs":["《中国老年尿失禁诊治专家共识（2022）》","《膀胱过度活动症诊断与治疗指南（2022）》","《中国慢性便秘诊治指南（2019）》","罗马Ⅳ 功能性胃肠病诊断标准（便秘部分）"]}]}]},"gi":{"categories":[{"id":"ugib","name":"上消化道出血","rank":1,"summary":"先容量复苏与风险分层（Blatchford/Glasgow-Blatchford），非静脉曲张性 24 h 内胃镜+PPI，静脉曲张性 12 h 内胃镜+生长抑素+预防性抗生素，必要时限制性输血与介入/手术止血。","compare":[{"diseaseId":"ugib_variceal","dx":"肝硬化/门脉高压背景，呕血或黑便，胃镜见食管胃静脉曲张伴红色征或活动性出血（喷血/渗血/白乳头/血痂）","key":"有门脉高压背景 + 胃镜见曲张静脉出血；治疗核心是生长抑素 + 抗生素 + 内镜套扎/硬化，禁用非选择性 NSAIDs 与强效止血药物替代方案"},{"diseaseId":"ugib_peptic","dx":"溃疡病史或 NSAIDs/抗血小板用药史，呕血/黑便，胃镜见胃或十二指肠溃疡伴 Forrrest 分级出血征象","key":"无门脉高压，胃镜见溃疡底血管裸露（Forrest Ⅱa）或活动性出血，PPI 静脉大剂量为基石"}],"diseases":[{"id":"ugib_variceal","name":"食管胃底静脉曲张破裂出血","aka":["EGVB","variceal bleeding","静脉曲张性上消化道出血"],"rank":1,"basic":{"define":"门静脉高压（多为肝硬化，肝静脉压力梯度 HVPG ≥10 mmHg，出血阈值通常 ≥12 mmHg）导致食管、胃底黏膜下静脉扩张破裂所致的急性失血，是肝硬化患者最常见的致死性并发症之一。","risk":["肝硬化失代偿（Child-Pugh C 级、MELD 高分）","曲张静脉直径大（>5 mm）、伴红色征（RC 阳性）","既往有静脉曲张出血史","大量饮酒、剧烈呕吐、腹压骤升","合并 HCC 或门静脉血栓","低血小板、凝血功能障碍、感染"],"epi":"约 50% 肝硬化患者存在食管胃静脉曲张，其中每年 5%–15% 发生破裂出血；首次出血病死率约 15%–20%，未行二级预防者 1 年内再出血率高达 60%。"},"patho":"肝硬化致肝内血管阻力增加与内脏高动力循环（一氧化氮介导的内脏血管扩张、门静脉血流量增加），门静脉压力升高并经胃左静脉、胃短静脉等侧支反流，形成食管下段与胃底黏膜下静脉曲张。曲张静脉壁薄、承受张力（依 Laplace 定律随直径增大而升高），在黏膜糜烂、腹压骤升或门脉压波动时破裂；大出血引起有效循环血量下降、肾素-血管紧张素-醛固酮系统激活，易继发肝肾综合征与肝性脑病。","dx":{"criteria":["有肝硬化/门脉高压证据（超声或 CT 示肝表面结节、脾大、门静脉增宽 >13 mm、侧支循环、腹水）+ 呕血/黑便/呕吐咖啡样物","胃镜为确诊金标准：见食管或胃底曲张静脉，伴活动性喷血/渗血、曲张静脉上白乳头（白色血栓头）、血痂或仅见曲张静脉而其他部位无出血灶（排除性诊断）","静脉曲张分级：轻度（直径 <5 mm、直行）、中度、重度（直径 ≥5 mm、串珠/结节/瘤状），重度或伴红色征者出血风险高","出血严重程度：Hb 下降 ≥20 g/L 或 HCT 下降 ≥6%，或需输血 ≥2 U；休克指数（心率/收缩压）≥1 提示显著失血","Child-Pugh 分级评估肝功能储备：A 级 5–6 分、B 级 7–9 分、C 级 10–15 分（胆红素、白蛋白、PT 延长、腹水、肝性脑病）"],"workup":["血常规、血型与交叉配血、凝血功能（PT/INR、纤维蛋白原）、肝肾功能与电解质、血氨、乳酸","床旁超声评估肝硬化形态、脾大、腹水、门静脉主干直径与血栓；可测门静脉血流速度","胃镜在血流动力学稳定后尽早进行（建议 12 h 内），同时具备内镜下治疗能力","HVPG 测定（≥10 mmHg 确诊临床显著门脉高压，≥12 mmHg 为出血阈值），多用于科研与疑难病例","评估是否合并 HCC（AFP + 增强 CT/MRI）、感染灶（腹水 PMN、降钙素原）","风险评分：Child-Pugh、MELD、AIMS65 与 Glasgow-Blatchford 评分辅助判断重症监护需求"],"grading":"按出血部位分为食管静脉曲张出血与胃静脉曲张出血（GOV1 沿胃小弯延伸、GOV2 位于胃底、IGV1 孤立胃底静脉曲张，后者出血凶险、治疗难度大）；按严重程度分为少量（无需输血、生命体征稳定）与大量（休克、需大量输血或持续活动性出血）。"},"ddx":[{"name":"消化性溃疡出血（ugib_peptic）","point":"与本类 ugib_peptic 的鉴别点：溃疡出血无门脉高压背景（无脾大、血小板正常、无腹水），胃镜见溃疡而非曲张静脉；门脉高压患者中约 20%–30% 的上消化道出血实际来自溃疡或门脉高压性胃病，需胃镜确诊后再决定是否用生长抑素。"},{"name":"门脉高压性胃病出血","point":"同为门脉高压并发症，但胃镜表现为胃黏膜马赛克样/蛇皮样充血水肿、樱桃红斑，无曲张静脉破裂；出血多为慢性渗血，治疗以降门脉压与 PPI 为主，不需套扎。"},{"name":"Mallory-Weiss 综合征（贲门黏膜撕裂）","point":"剧烈干呕/呕吐后呕血，胃镜见食管胃交界处纵行黏膜撕裂而非曲张静脉，多数自限，少数需内镜止血或介入。"},{"name":"Dieulafoy 病","point":"胃黏膜下恒径动脉破裂，出血凶猛但胃镜初查常漏诊（黏膜外观正常、间歇性喷血），无肝硬化背景。"},{"name":"上消化道恶性肿瘤出血","point":"伴消瘦、贫血进行性加重、胃镜见不规则溃疡或隆起性病变，活检病理确诊。"}],"tx":{"drug":[{"name":"生长抑素（somatostatin）","dose":"首剂 250 μg 静脉推注（>1 min），继以 250 μg/h 持续静脉泵入，出血停止后继续 2–5 天（多数 3 天），再逐步减停","note":"确诊或高度怀疑静脉曲张出血即用，不必等胃镜；可显著降低内脏血流与门静脉压力","renal":"严重肾功能不全者监测，一般无需调整","hepatic":"肝功能不全无需调整剂量","interact":"与胰岛素、口服降糖药合用可能引起血糖波动，监测血糖；与环孢素合用可能降低其血药浓度"},{"name":"奥曲肽（octreotide）","dose":"50 μg 静脉推注，继以 50 μg/h 持续泵入，维持 3–5 天","note":"无生长抑素时的替代；生长抑素类似物，可减少内脏血流量","renal":"严重肾功能不全者减量并监测","hepatic":"肝硬化者半衰期延长，需监测不良反应","interact":"与胰岛素、磺脲类合用可致低血糖；与环孢素合用影响其吸收"},{"name":"特利加压素（terlipressin）","dose":"2 mg 静脉推注 q4h，出血停止后 24 h 改为 1 mg q4h；肾功能不全或低钠者减量至 1 mg q4h（遵说明书与指南）","note":"血管加压素类似物，效果与生长抑素相当，适用于生长抑素不可得或合并肝肾综合征者","renal":"肾功能不全者慎用，警惕低钠血症与容量超负荷","hepatic":"Child-Pugh C 级慎用，易诱发缺血与低钠","interact":"与 β 受体阻滞剂合用增加心血管缺血事件风险"},{"name":"质子泵抑制剂（PPI，如埃索美拉唑/泮托拉唑）","dose":"埃索美拉唑 80 mg 静脉推注（负荷）后 8 mg/h 持续泵入 72 h；或泮托拉唑 80 mg 负荷后 8 mg/h 维持；亦可 40 mg iv q12h","note":"内镜治疗后常规使用，可减少再出血；大剂量持续泵入优于间断给药（Forrest Ⅰa–Ⅱb 病灶）","renal":"无需调整","hepatic":"重度肝功能不全减量，监测血药浓度相关不良反应","interact":"奥美拉唑/埃索美拉唑抑制 CYP2C19，可降低氯吡格雷活性；必要时改用泮托拉唑/雷贝拉唑"},{"name":"头孢曲松（预防性抗生素）","dose":"1 g 静脉滴注 qd，疗程 7 天（或至出血停止后 3 天）；肾功能不全或重症可调整","note":"所有肝硬化合并上消化道出血者均应预防性使用，可降低再出血率与病死率","renal":"CrCl <30 mL/min 仍可 1 g qd，无需大幅调整","hepatic":"无需调整","interact":"与钙剂同用可能形成沉淀（新生儿禁用）；与抗凝药合用可增加出血风险"},{"name":"普萘洛尔（二级预防）","dose":"起始 10–20 mg bid，每 2–3 天递增，目标静息心率下降 25% 或降至 55–60 次/分，最大耐受量（常用 20–40 mg bid）","note":"出血停止、稳定后启动，用于预防再出血；禁忌者可用卡维地洛或内镜套扎替代","renal":"肾功能不全者无需调整","hepatic":"肝病者首过效应降低，起始剂量宜小","interact":"与维拉帕米、地尔硫䓬、胺碘酮合用加重心动过缓与低血压"},{"name":"卡维地洛","dose":"起始 6.25 mg qd，可增至 12.5 mg qd（目标静息心率 55–60 次/分或耐受剂量）","note":"α/β 受体阻滞剂，降低 HVPG 效果优于普萘洛尔，但低血压者慎用","renal":"无需调整","hepatic":"重度肝功能不全（Child-Pugh C）慎用","interact":"与 CYP2D6 抑制剂（帕罗西汀、氟西汀）合用升高血药浓度"}],"nonDrug":["内镜下治疗：食管静脉曲张首选套扎（EVL），通常 2–4 周间隔重复套扎直至静脉曲张根除；胃底静脉曲张（GOV2/IGV1）首选组织黏合剂（氰基丙烯酸酯/α-氰基丙烯酸正丁酯）注射，也可选 TIPS","三腔二囊管压迫止血：仅作为大出血无法控制时过渡手段，置管 ≤24 h，需警惕误吸与食管黏膜坏死","经颈静脉肝内门体分流（TIPS）：药物+内镜治疗失败、Child-Pugh B/C 级高危再出血者；合并 HCC 及门静脉主干完全闭塞禁用","球囊闭塞逆行经静脉栓塞（BRTO）：胃底静脉曲张且合并自发性门体分流者","外科断流术（贲门周围血管离断术）或分流术：内镜与 TIPS 均不可行或失败者","限制性输血：Hb 目标 70–80 g/L（合并心血管疾病可放宽至 80–90 g/L），避免过度输血升高门脉压"],"life":["绝对戒酒，避免损伤肝脏的药物与保健品","避免剧烈呕吐、用力排便、提重物等腹压骤升行为","一级/二级预防长期 β 受体阻滞剂或定期内镜套扎","出血后 4–6 周复查胃镜，之后每 6–12 个月随访","抗病毒治疗（HBV/HCV）、控制体重与代谢性肝病可延缓门脉高压进展"]},"prog":"首次出血病死率约 15%–20%，Child-Pugh C 级者更高；早期（6 周内）再出血率约 30%–40%，1 年内可达 60%。规范药物+内镜+二级预防可将再出血率降至 20% 以下；反复出血或肝功能失代偿者应评估肝移植。","refs":["中华医学会消化病学分会《肝硬化门静脉高压食管胃静脉曲张出血的防治指南（2022年，北京）》","中华医学会肝病学分会《肝硬化诊治指南（2019年）》","Baveno VII 门静脉高压共识（2022）","2023 ESGE 食管胃静脉曲张内镜诊治指南"]},{"id":"ugib_peptic","name":"消化性溃疡出血","aka":["peptic ulcer bleeding","PUD bleeding","胃十二指肠溃疡出血"],"rank":2,"basic":{"define":"胃或十二指肠溃疡侵蚀黏膜下血管（常见于胃左动脉分支、胃十二指肠动脉）所致的急性上消化道出血，是非静脉曲张性上消化道出血最常见的病因。","risk":["幽门螺杆菌（H. pylori）感染","非甾体抗炎药（NSAIDs）、阿司匹林、抗凝药","年龄 >60 岁，合并心脑血管病、慢性肾病","吸烟、大量饮酒、严重应激（ICU 患者、烧伤、颅脑创伤）","既往消化性溃疡出血史","糖皮质激素与大剂量 NSAIDs 联用"],"epi":"消化性溃疡约占非静脉曲张性上消化道出血的 40%–50%，我国每年上消化道出血发病率约 60–100/10 万，消化性溃疡出血病死率约 5%–10%，老年与合并症多者更高。"},"patho":"溃疡形成源于攻击因子（胃酸胃蛋白酶、H. pylori、NSAIDs）与黏膜防御（黏液-碳酸氢盐屏障、前列腺素、黏膜血流）失衡。NSAIDs 抑制环氧化酶-1 减少前列腺素合成，削弱黏膜屏障；H. pylori 相关胃窦炎破坏黏膜完整性。溃疡深及黏膜下层时可能侵蚀裸露血管，血管壁被消化酶与酸侵蚀，形成假性动脉瘤（Forrest Ⅱa 裸露血管）后破裂。","dx":{"criteria":["有呕血、黑便或呕吐咖啡样物，伴或不伴失血性周围循环不足（头晕、心悸、血压下降）","粪隐血阳性或血性大便；Hb 下降 ≥20 g/L 提示显著出血","胃镜为诊断金标准：见胃或十二指肠溃疡伴出血征象即可诊断，Forrest 分级：Ⅰa 喷射性出血、Ⅰb 渗血、Ⅱa 裸露血管、Ⅱb 附着血凝块、Ⅱc 黑色基底、Ⅲ 清洁基底","Forrest Ⅰa–Ⅱb 为高危（再出血率分别为 55%、50%、43%、22%），Ⅱc 与 Ⅲ 为低危（<5%）","排除静脉曲张、Mallory-Weiss 撕裂、Dieulafoy 病及肿瘤出血"],"workup":["血常规、凝血功能、血型与交叉配血、肝肾功能、电解质","Glasgow-Blatchford 评分（≤1 分可门诊处理）与 Rockall 评分（评估再出血与死亡风险）","胃镜：血流动力学稳定前提下 24 h 内进行，高危或内镜止血指征者 12 h 内","H. pylori 检测：胃镜活检快速尿素酶试验或病理；近期使用抑酸药可用 ¹³C 呼气试验或粪便抗原","高危患者复查 Hb 与生命体征，必要时行 CT 血管造影（CTA）定位出血点"],"grading":"Forrest 分级是消化性溃疡出血最主要的分级方式：Ⅰa 喷射性出血、Ⅰb 渗血、Ⅱa 裸露血管、Ⅱb 附着血凝块、Ⅱc 黑色基底、Ⅲ 清洁基底。Ⅰa–Ⅱb 高危需内镜止血（注射+热凝或夹闭），Ⅱc–Ⅲ 低危可不做内镜治疗。"},"ddx":[{"name":"食管胃底静脉曲张破裂出血（ugib_variceal）","point":"与本类 ugib_variceal 的鉴别点：静脉曲张出血多伴肝硬化、脾大、腹水、血小板减少；胃镜见曲张静脉而非溃疡。若门脉高压患者出血部位不明，应先用生长抑素并尽早胃镜确认，避免对溃疡出血误用降门脉压药物而延误 PPI 治疗。"},{"name":"Mallory-Weiss 综合征","point":"剧烈呕吐后呕血，胃镜见贲门纵行黏膜撕裂（常 <1 cm），多数自限；与溃疡的 Forrrest 病灶不同。"},{"name":"Dieulafoy 病","point":"无溃疡、黏膜外观正常但见单支动脉破口间歇喷血，好发于胃体上部小弯侧，需内镜反复寻找或用血管造影定位。"},{"name":"糜烂性胃炎/急性胃黏膜病变","point":"多发浅表糜烂、渗血，常见于应激或 NSAIDs 使用，一般不会见裸露血管，治疗以 PPI 为主。"},{"name":"上消化道肿瘤出血","point":"消瘦、贫血、胃镜见不规则溃疡或隆起伴坏死，需多点活检病理学确诊。"}],"tx":{"drug":[{"name":"埃索美拉唑（静脉 PPI）","dose":"80 mg 静脉推注（>30 min）后 8 mg/h 持续泵入 72 h；高危病灶（Forrest Ⅰa–Ⅱb）内镜治疗后必须使用","note":"大剂量持续泵入维持胃内 pH >6，有助于血凝块稳定；72 h 后可改为口服 PPI，40 mg qd","renal":"无需调整","hepatic":"重度肝功能不全（Child-Pugh C）单剂不超过 40 mg，避免长期大剂量","interact":"抑制 CYP2C19，可降低氯吡格雷疗效；需抗血小板者改用泮托拉唑"},{"name":"泮托拉唑（静脉 PPI）","dose":"80 mg 静脉滴注（>15 min）后 8 mg/h 持续泵入 72 h；或 40 mg iv q12h","note":"CYP2C19 相互作用少，冠心病服用氯吡格雷者优先","renal":"CrCl <20 mL/min 不宜大剂量，遵说明书","hepatic":"重度肝病者每日最大剂量 40 mg（遵说明书）","interact":"与甲氨蝶呤、地高辛同类 PPI 相互作用小，优于奥美拉唑"},{"name":"奥美拉唑","dose":"80 mg 静脉负荷后 8 mg/h 持续泵入 72 h（与埃索美拉唑相当）；口服 20 mg qd 维持","note":"价格低，广泛可用；与氯吡格雷并用时需评估","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"强效 CYP2C19 抑制剂，显著降低氯吡格雷抗血小板作用，避免同用"},{"name":"氨甲环酸","dose":"1 g 静脉滴注（>10 min），必要时 8 h 后重复 1 g（部分地区经验用法）；不作为常规推荐","note":"近期研究（HALT-IT）未显示降低病死率且增加血栓事件，仅用于难治性出血部分中心","renal":"CrCl <30 mL/min 减半，透析患者减少剂量","hepatic":"无需调整","interact":"与口服避孕药、抗凝药合用增加血栓风险"},{"name":"H. pylori 根除方案（铋剂四联）","dose":"PPI 标准剂量 bid + 铋剂 220 mg bid + 阿莫西林 1000 mg bid + 克拉霉素 500 mg bid，疗程 14 天","note":"出血期可静脉 PPI，出血停止后启动根除治疗；青霉素过敏者以四环素 500 mg qid 或甲硝唑 400 mg qid 替代","renal":"阿莫西林 CrCl <30 减量；克拉霉素肾功能不全慎用","hepatic":"重度肝病者克拉霉素慎用，监测 QT","interact":"克拉霉素与他汀、胺碘酮、华法林相互作用显著，需评估"},{"name":"凝血酶（局部止血辅助）","dose":"遵说明书，内镜下局部喷洒或经胃管注入","note":"缺乏高质量证据，不作为主要止血手段，仅在内镜治疗联合方案中辅助使用","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与含碘消毒剂同用（可使其失活）"}],"nonDrug":["内镜止血为一线：Forrest Ⅰa–Ⅱb 采用注射（肾上腺素稀释液 1:10000）+ 热凝（双极/热探头）或机械夹闭（止血夹），联合优于单一方法","内镜治疗失败或无法控制的大出血（约 5%–10%）：经导管动脉栓塞（TAE）优于急诊外科手术；栓塞失败再行外科缝扎/切除","Rockall 评分高、多器官衰竭或高龄患者应收入 ICU 监测","停用 NSAIDs 与非必需的抗血小板/抗凝药；确需抗栓者评估恢复时机（一般止血后 3–7 天）","限制性输血：Hb 目标 70–80 g/L（合并症可 80–90 g/L）"],"life":["戒烟、限酒，规律饮食","根除 H. pylori 后 4–8 周复查呼气试验","长期 NSAIDs 使用者加用 PPI 保护","愈合后 6–8 周复查胃镜（尤其胃溃疡需除外恶性）","抗血小板/抗凝患者与心内科/神经内科共同制定用药方案"]},"prog":"内镜止血后 72 h 内再出血率约 10%–20%，Forrest Ⅰa/Ⅱa 病灶更高；规范 PPI 治疗与 H. pylori 根除后 1 年再出血率 <5%。老年、合并心肾疾病及休克就诊者病死率较高（约 10%）。","refs":["中华医学会消化内镜学分会《急性非静脉曲张性上消化道出血诊治指南（2023年，北京）》","中华医学会消化病学分会《第六次全国幽门螺杆菌感染处理共识报告（2022年）》","2021 ESGE 非静脉曲张性上消化道出血内镜诊疗指南","2020 ACG 溃疡出血管理指南"]}]},{"id":"cirrhosis","name":"肝硬化及其并发症","rank":2,"summary":"以病因治疗（抗病毒/戒酒/减重）与并发症防治为主线：腹水采用限钠+利尿剂阶梯治疗，自发性细菌性腹膜炎需 12 h 内诊断性穿刺并使用三代头孢，肝性脑病以乳果糖+利福昔明为主并寻找诱因。","compare":[{"diseaseId":"cirr_ascites","dx":"肝硬化背景出现腹部膨隆、移动性浊音阳性，超声见腹水；诊断性穿刺 SAAG ≥11 g/L 提示门脉高压性腹水","key":"SAAG ≥11 g/L 提示门脉高压性，治疗为限钠 88 mmol/d + 螺内酯±呋塞米"},{"diseaseId":"cirr_he","dx":"肝硬化患者出现意识障碍、定向力差、扑翼样震颤、语言行为改变，血氨升高，排除其他脑病","key":"血氨不是诊断必需但可辅助；核心是找诱因（消化道出血、感染、电解质紊乱、便秘）+ 乳果糖"},{"diseaseId":"cirr_sbp","dx":"腹水患者出现发热、腹痛，或不明原因病情恶化；腹水 PMN ≥250/μL 即诊断，腹水培养阳性可确诊","key":"腹水 PMN ≥250/μL 即可开始经验性头孢覆盖，培养阴性也不排除"}],"diseases":[{"id":"cirr_ascites","name":"肝硬化腹水","aka":["腹水","ascites","肝性腹水"],"rank":1,"basic":{"define":"肝硬化失代偿期最常见并发症，可表现为少量（超声发现）、中量（临床明显）与难治性腹水；门脉高压与有效循环血量不足共同导致水钠潴留。","risk":["肝硬化失代偿（Child-Pugh B/C 级）","门静脉高压（HVPG ≥12 mmHg）","高盐饮食","低白蛋白血症（<30 g/L）","肾素-血管紧张素-醛固酮系统激活","合并感染、消化道出血、HCC"],"epi":"约 50% 代偿期肝硬化患者在 10 年内出现腹水，腹水是肝硬化住院最常见的并发症，一旦出现腹水，5 年病死率可达 40%–50%。"},"patho":"门静脉高压使内脏毛细血管静水压升高，液体滤入腹腔；同时有效循环血量下降激活 RAAS 与交感神经，抗利尿激素释放增加，导致水钠潴留；低白蛋白血症降低血浆胶体渗透压。腹水形成后腹内压升高，进一步压迫下腔静脉与肾静脉，形成恶性循环；大量腹水可致疝、膈肌上抬、肝肾综合征。","dx":{"criteria":["腹围增加、移动性浊音阳性、液波震颤阳性，伴体重增加","腹部超声：可检出 ≥100 mL 腹水，定位积液并指导穿刺","诊断性腹腔穿刺：血清-腹水白蛋白梯度 SAAG = 血清白蛋白 − 腹水白蛋白；SAAG ≥11 g/L 提示门脉高压性腹水（准确率约 97%）","腹水蛋白 <25 g/L 提示易并发 SBP","腹水总量分级：1 级（超声可见，无明显症状）、2 级（中量，腹围增加）、3 级（大量，明显腹胀）","难治性腹水：限钠+足量利尿剂（螺内酯 400 mg/d + 呋塞米 160 mg/d）至少 1 周无反应，或近期复发需频繁放液"],"workup":["腹水常规（含细胞计数与分类）、腹水白蛋白与总蛋白、腹水培养（血培养瓶床边接种以提高阳性率）、腹水腺苷脱氨酶（结核性鉴别）","血常规、肝功能、肾功能、电解质（尤其血钠）、凝血功能","24 h 尿钠与尿钾评估钠排泄（<78 mmol/d 提示依从性差或利尿剂抵抗）","肝脏超声：肝硬化形态、门静脉主干与血栓、脾大、腹水程度","腹部增强 CT/MRI：评估 HCC、门脉血栓与腹膜后情况"],"grading":"分 1–3 级（超声可见/中量/大量）；按利尿剂反应分「利尿剂敏感型」与「难治性腹水」（4 周内至少 2 次大量放液或利尿剂无效）；按白蛋白与肾功能进一步分层，出现 HRS-AKI 需特殊处理。"},"ddx":[{"name":"自发性细菌性腹膜炎（cirr_sbp）","point":"与本类 cirr_sbp 的鉴别点：腹水本身不是 SBP，但 SBP 是腹水常见并发症，出现发热、腹痛或不明原因肾功能恶化时应随时穿刺；腹水 PMN ≥250/μL 即需抗生素，而单纯腹水 PMN 通常 <250/μL。"},{"name":"肝性脑病（cirr_he）","point":"与本类 cirr_he 的鉴别点：大量腹水可诱发低钠与脑病，腹水患者出现意识障碍时需查血氨与电解质，并排除 SBP 导致的肝肾综合征。"},{"name":"结核性腹膜炎","point":"SAAG <11 g/L、腹水 ADA 升高（>40 U/L）、淋巴细胞为主，伴发热盗汗，腹膜增厚，腹水抗酸染色/培养阳性率低。"},{"name":"腹膜癌病（卵巢癌、胃癌腹膜转移）","point":"SAAG <11 g/L、腹水细胞学阳性、CEA/CA125 升高，增强 CT 见腹膜结节。"},{"name":"心源性腹水（右心衰、缩窄性心包炎）","point":"SAAG ≥11 g/L 但腹水蛋白高（>25 g/L）、伴颈静脉怒张、肝颈静脉回流征阳性、BNP 升高，超声见右心扩大。"},{"name":"Budd-Chiari 综合征","point":"SAAG ≥11 g/L，伴肝大、腹痛、腹水顽固，超声示肝静脉狭窄/血栓与肝尾叶增大。"}],"tx":{"drug":[{"name":"螺内酯","dose":"起始 100 mg qd（或 40 mg qd，依剂型），每 3–5 天递增至 200 mg qd，最大 400 mg/d；单药优于呋塞米起始","note":"首选的保钾利尿剂，与呋塞米联用比例为 100 mg 螺内酯:40 mg 呋塞米","renal":"CrCl <30 mL/min 或高钾血症时禁用/减量","hepatic":"严重肝功能不全者可选择低剂量并监测","interact":"与 ACEI/ARB、NSAIDs、补钾药合用时高钾风险增高；与地高辛合用可升高地高辛浓度"},{"name":"呋塞米","dose":"无水肿者 20 mg qd 起始，有水肿者 40 mg qd 起始；最大 160 mg/d；与螺内酯比对","note":"腹水患者建议与螺内酯联用；过快利尿（>0.5 kg/d 无水肿、>1 kg/d 有水肿）诱发肾损伤","renal":"肾功能不全者大剂量使用，注意低钾与肾前性氮质血症","hepatic":"肝硬化患者低钾可诱发肝性脑病，需监测电解质","interact":"NSAIDs 降低利尿效果；与氨基糖苷类合用增加耳毒性"},{"name":"托伐普坦","dose":"起始 15 mg qd，可增至 30–60 mg qd；用药前需纠正低钠，注意纠正速度","note":"用于低钠血症合并腹水，纠正速度不宜过快（24 h 内 <8–10 mmol/L）","renal":"不推荐在严重肾功能不全（CrCl <10）使用","hepatic":"重度肝病慎用，监测肝酶","interact":"与强 CYP3A4 抑制剂（克拉霉素）合用升高血药浓度"},{"name":"人血白蛋白","dose":"大量放腹水（>5 L）时每放 1 L 腹水补充 6–8 g 白蛋白；或 20% 白蛋白 100 mL 放液后输注（经验用法）","note":"放液 >5 L 时预防循环功能障碍（PPCD）；低白蛋白 <25 g/L 者可考虑长期补充","renal":"无需调整","hepatic":"无特殊禁忌","interact":"与静脉营养液配伍需注意"},{"name":"利福昔明","dose":"550 mg bid（或 400 mg tid），与乳果糖联用于预防 SBP 与 HE","note":"用于肝性脑病预防或难治性腹水的二级预防（降低 SBP 风险），不替代乳果糖","renal":"CrCl <30 mL/min 不建议使用","hepatic":"Child-Pugh C 级建议减量或避免","interact":"影响口服避孕药效果；与华法林合用可能增强抗凝"},{"name":"诺氟沙星（SBP 一级预防）","dose":"400 mg qd 口服（或 400 mg bid，部分方案）","note":"仅用于腹水蛋白 <15 g/L、Child-Pugh B/C 或合并肝肾功能不全的高危患者","renal":"肾功能不全需减量","hepatic":"无需特殊调整","interact":"与华法林合用增强抗凝；与茶碱合用影响代谢"}],"nonDrug":["限钠：食盐 <5 g/d（钠 88 mmol/d），单纯限钠效果有限者不宜过度限制（<40 mmol/d 可致低钠）","腹腔穿刺放液：大量腹水伴呼吸困难或腹胀，单次可放 5–8 L，同时补充白蛋白","经颈静脉肝内门体分流（TIPS）：难治性腹水且肝功能尚可（Child-Pugh ≤9 分、MELD ≤18）者，可提高生存","难治性腹水合并 HRS 或反复 SBP 者评估肝移植","腹腔-静脉分流（LeVeen 分流）用于 TIPS 禁忌的难治性腹水"],"life":["每日称体重、记录腹围","限水：血钠 <125 mmol/L 时限水 <1000 mL/d","避免 NSAIDs、氨基糖苷类等肾毒性药物","戒酒、低盐饮食，控制蛋白质摄入（1.0–1.5 g/kg/d，不限制）","每 3 个月超声筛查 HCC，定期随访腹水情况"]},"prog":"腹水出现后中位生存期约 2–3 年，难治性腹水 1 年生存率约 50%。并发 SBP、HRS、HE 者预后差；规范治疗与适时 TIPS/肝移植可改善生存。","refs":["中华医学会肝病学分会《肝硬化腹水及相关并发症诊疗指南（2023年版）》","中华医学会肝病学分会《肝硬化诊治指南（2019年版）》","AASLD 肝硬化腹水与并发症管理指南（2021）","EASL 肝硬化失代偿管理临床实践指南（2018）"]},{"id":"cirr_he","name":"肝性脑病","aka":["HE","hepatic encephalopathy","肝性昏迷"],"rank":2,"basic":{"define":"由严重肝病或门体分流导致的代谢紊乱所致的中枢神经系统功能失调，以意识障碍、行为改变、认知障碍、运动异常（扑翼样震颤）与神经精神症状为特征，排除其他脑病后可诊断。","risk":["肝硬化失代偿（Child-Pugh C 级）","消化道出血（高蛋白负荷）","感染（尤其 SBP）、便秘","低钾/低钠、碱中毒","大量放腹水、过度利尿","镇静催眠药、阿片类、苯二氮䓬类","TIPS 术后、门体分流"],"epi":"约 30%–45% 肝硬化患者一生中会发生肝性脑病，TIPS 术后 3 个月内发生率约为 10%–20%，是肝硬化患者反复住院与病死的重要原因。"},"patho":"肝功能衰竭与门体分流使肠道来源的氨、硫醇、假性神经递质、γ-氨基丁酸（GABA）等毒性物质绕过肝脏进入体循环与脑，氨在星形胶质细胞内转化为谷氨酰胺引起细胞肿胀、脑水肿，并干扰神经递质传递；低钠、感染、炎症因子与氧化应激可加重脑损伤。","dx":{"criteria":["肝硬化/门体分流背景，出现意识水平下降、定向力障碍、行为异常、睡眠倒错或昏迷","扑翼样震颤（flapping tremor）阳性（需患者保持前伸双臂姿势）","血氨升高（>参考上限，通常 >35–50 μmol/L，但血氨正常不能排除 HE）","排除低血糖、代谢性酸中毒、尿毒症、药物/酒精中毒、颅内病变（必要时头颅 CT/MRI、腰穿）","神经心理测试（数字连接试验 NCT-A、NCT-B、抑制性控制测试）用于轻微型 HE 筛查：NCT-A >40 s 或 NCT-B >60 s 提示异常","West Haven 分级：0 级无异常；1 级轻度意识模糊、欣快/焦虑、计算力下降；2 级嗜睡、定向力障碍、扑翼样震颤明显；3 级嗜睡但可唤醒、言语不清；4 级昏迷"],"workup":["血氨（动脉血或静脉血均可，采血后立即送检）、血常规、肝功能、凝血、电解质（低钾、低钠）、肾功能、血葡萄糖","寻找诱因：粪隐血或胃管引流（消化道出血）、腹水穿刺（SBP）、感染指标、便秘与药物史","头颅 CT/MRI：排除颅内出血、脑梗死、脑水肿（4 级 HE 需评估脑水肿）","脑电图：可见弥漫性慢波与三相波，主要用于疑难病例","肝纤维化与肝功能评估：Child-Pugh、MELD 评分"],"grading":"West Haven 标准分为 0–4 级（0 级无异常，1 级轻度意识模糊，2 级嗜睡+定向力障碍，3 级嗜睡但可唤醒，4 级昏迷）；另有 Conn 分级与 SONIC 分级，临床常用 West Haven 分级。按起病分为急性、慢性复发与持续性 HE。"},"ddx":[{"name":"自发性细菌性腹膜炎（cirr_sbp）","point":"与本类 cirr_sbp 的鉴别点：SBP 本身可引起或加重 HE，出现 HE 时需常规腹水穿刺排除 SBP（腹水 PMN ≥250/μL）；SBP 患者通常伴发热或腹痛，单纯 HE 无腹水感染证据。"},{"name":"肝硬化腹水（cirr_ascites）","point":"与本类 cirr_ascites 的鉴别点：大量腹水可致低钠、低钾诱发 HE，腹水患者新发意识障碍需查电解质；腹水本身不引起扑翼样震颤。"},{"name":"低血糖性脑病","point":"肝硬化患者糖原储备低，易发空腹低血糖（<2.8 mmol/L），表现为出汗、心悸、意识模糊，补糖后迅速恢复，需立即测血糖。"},{"name":"酒精戒断性谵妄","point":"有大量饮酒史，停酒后 24–72 h 出现震颤、幻觉、心动过速、大汗，伴血氨可正常，与 HE 可叠加，需同时处理。"},{"name":"Wernicke 脑病（维生素 B1 缺乏）","point":"长期酗酒或营养不良者出现眼球震颤、共济失调、意识障碍三联征，MRI 见乳头体/导水管周围高信号，需立即补充硫胺素，补糖前先补 B1。"},{"name":"颅内出血/卒中、尿毒症脑病","point":"局灶体征、头颅影像异常、血尿素氮显著升高伴代谢性酸中毒，与 HE 的弥漫性意识障碍不同。"}],"tx":{"drug":[{"name":"乳果糖","dose":"口服 30–45 mL（或 20–30 g）tid–qid，调整至每日 2–3 次软便；不能口服者保留灌肠 300 mL 乳果糖 + 700 mL 生理盐水，保留 1 h，q4–6h","note":"一线治疗，通过酸化肠道减少氨吸收；需监测腹泻与电解质","renal":"肾功能不全者慎用大剂量（乳果糖在结肠发挥作用，一般安全，但腹泻可致脱水）","hepatic":"无需调整","interact":"与口服抗生素联用增加腹泻风险；与抗酸剂合用降低疗效"},{"name":"利福昔明","dose":"550 mg bid 口服（或 400 mg tid），长期维持用于 HE 二级预防","note":"不可吸收的肠道抗生素，与乳果糖联用可降低复发率（约 50%）","renal":"CrCl <30 mL/min 慎用/避免","hepatic":"Child-Pugh C 级慎用","interact":"与华法林合用增强抗凝，需监测 INR"},{"name":"门冬氨酸鸟氨酸","dose":"静脉滴注 10–20 g/d（溶于 5%–10% 葡萄糖或生理盐水 250–500 mL，输注 4 h 以上）；口服 3 g tid","note":"促进尿素循环与谷氨酰胺合成，用于急性 HE 降低血氨","renal":"严重肾功能不全（CrCl <10 mL/min）禁用或减量","hepatic":"无特殊调整","interact":"与含钙制剂同用可能沉淀"},{"name":"支链氨基酸（BCAA）","dose":"静脉输注 250–500 mL/d，或口服制剂（遵说明书）","note":"纠正氨基酸失衡，改善 HE 症状与营养状态","renal":"肾功能不全者注意含氮负荷","hepatic":"无需调整","interact":"与左旋多巴合用可降低其疗效"},{"name":"锌剂（硫酸锌/醋酸锌）","dose":"醋酸锌 220 mg bid（含元素锌 50 mg）","note":"辅助治疗，改善锌缺乏导致的尿素循环障碍，证据有限","renal":"肾功能不全者慎用","hepatic":"无需调整","interact":"与四环素、喹诺酮类合用降低其吸收，间隔 2 h"},{"name":"头孢曲松（合并感染时）","dose":"1 g 静脉滴注 qd（或按感染部位调整剂型）","note":"HE 合并 SBP 时使用，同时纠正诱因","renal":"CrCl <30 mL/min 无需大幅调整","hepatic":"无需调整","interact":"与钙剂同用沉淀（新生儿禁用）"}],"nonDrug":["去除诱因最关键：控制消化道出血、治疗感染、纠正低钾/低钠、停用镇静剂、解除便秘","1–2 级 HE 以乳果糖口服为主，3–4 级需静脉治疗与气道保护（必要时插管）","4 级 HE 伴脑水肿者需甘露醇/高渗盐水，监测颅内压，并尽快评估肝移植","TIPS 术后 HE 反复者，评估缩小支架或以球囊限流","轻微型 HE 需筛查并治疗，以防发生显性 HE"],"life":["避免高蛋白一次性大量摄入，蛋白质 1.0–1.5 g/kg/d，植物蛋白/BCAA 可优选","保持每日 2–3 次软便，规律使用乳果糖","绝对戒酒，避免镇静催眠药","预防便秘与感染，上消化道出血后预防性乳果糖","家属教育：识别早期性格改变、睡眠倒错"]},"prog":"显性 HE 是肝硬化患者预后不良的标志，首次发生 HE 后 1 年生存率约 40%–50%，复发率高（1 年内约 40%）。规范治疗与诱因控制可改善；反复 HE 应考虑肝移植。","refs":["中华医学会肝病学分会《肝硬化肝性脑病诊疗指南（2018年版）》","中华医学会消化病学分会《肝性脑病诊治共识（2022）》","EASL/AASLD 肝性脑病实践指南（2014）","AASLD 肝硬化并发症管理指南（2021）"]},{"id":"cirr_sbp","name":"自发性细菌性腹膜炎","aka":["SBP","spontaneous bacterial peritonitis","自发性腹膜炎"],"rank":3,"basic":{"define":"无腹腔内明确感染灶（如穿孔、脓肿）的腹水细菌感染，是肝硬化失代偿期常见且致命的并发症，多由肠道菌群易位引起。","risk":["腹水蛋白 <10 g/L（风险最高，<15 g/L 亦为高危）","Child-Pugh C 级、MELD 高分","既往 SBP 发作史","消化道出血","使用 PPI（长期）、免疫抑制","侵入性操作（内镜、穿刺、留置导管）"],"epi":"肝硬化住院腹水患者 SBP 发生率为 10%–30%，院外获得性约 3.5%。未治疗者病死率 >90%，规范治疗后病死率仍约 20%–30%，是肝硬化最常见的感染性死因。"},"patho":"肝硬化时肠道黏膜屏障受损、肠道菌群过度生长与细菌易位，同时肝脏网状内皮系统清除能力下降与腹水调理素活性降低（腹水蛋白低），细菌在腹水中繁殖引起炎症。常见病原体为大肠埃希菌、肺炎克雷伯菌等革兰阴性杆菌（约 60%–70%），近年产 ESBL 菌株与革兰阳性球菌比例上升。可进一步诱发全身炎症反应、肾功能恶化（HRS）与肝性脑病。","dx":{"criteria":["腹水患者出现发热（>37.8 ℃）、腹痛、反跳痛，或不明原因肝肾功能恶化、肝性脑病、低血压、外周血白细胞升高","诊断金标准：诊断性腹腔穿刺，腹水多形核中性粒细胞（PMN）≥250/μL","腹水培养阳性（血培养瓶床边接种，阳性率约 40%–60%）可确诊病原","培养阴性中性粒细胞性腹水（CNNA）：PMN ≥250/μL 但培养阴性，且无其他感染灶，按 SBP 处理","继发性腹膜炎鉴别：腹水总蛋白 >10 g/L、LDH 高于血清、葡萄糖 <2.8 mmol/L、CEA 升高或多种细菌混合生长时需警惕继发性","SBP 缓解标准：治疗 48 h 后复查腹水 PMN 下降 ≥25% 且培养转阴"],"workup":["床旁诊断性腹腔穿刺：腹水细胞计数与分类、腹水白蛋白、总蛋白、葡萄糖、LDH；同时接种血培养瓶（需氧+厌氧）","血常规、降钙素原、C 反应蛋白、肝肾功能、电解质、凝血功能","血培养（阳性率约 50%）、尿培养","腹部超声/CT：排除继发性腹膜炎（穿孔、脓肿、肠缺血）","治疗 48 h 后复查腹水 PMN 评估疗效；不缓解者需调整抗生素并重新评估"],"grading":"按获得场所分为社区获得性（院外）与医疗保健相关（住院 >48 h 或近期住院/侵入操作）；按致病菌分为革兰阴性杆菌、革兰阳性球菌与产 ESBL 或多重耐药菌。继发性腹膜炎需单独识别。"},"ddx":[{"name":"肝硬化腹水（cirr_ascites）","point":"与本类 cirr_ascites 的鉴别点：单纯腹水无发热、无腹痛，腹水 PMN <250/μL；腹水蛋白 <15 g/L 提示易感，治疗策略不同（限钠利尿 vs 抗生素+白蛋白）。"},{"name":"肝性脑病（cirr_he）","point":"与本类 cirr_he 的鉴别点：HE 可不伴发热与腹水感染，但 SBP 可诱发或加重 HE；腹水患者出现 HE 必须穿刺排除 SBP。"},{"name":"继发性腹膜炎（消化道穿孔、肠缺血）","point":"腹水 PMN 极高、多菌生长、腹水总蛋白 >10 g/L、葡萄糖低，伴急腹症与气腹，需外科处理，仅抗感染无效。"},{"name":"结核性腹膜炎","point":"亚急性起病、发热盗汗、腹水以淋巴细胞为主、ADA >40 U/L、SAAG <11 g/L，抗结核治疗有效。"},{"name":"急性胰腺炎合并腹水","point":"上腹痛向背放射、血淀粉酶/脂肪酶 >3 倍上限、CT 见胰腺渗出，腹水淀粉酶显著升高。"}],"tx":{"drug":[{"name":"头孢曲松","dose":"1 g 静脉滴注 qd（或 2 g qd 重症），疗程 5–7 天（多数 5 天）","note":"社区获得性 SBP 的一线经验性用药，覆盖革兰阴性杆菌","renal":"CrCl <30 mL/min 无需大幅调整，但需监测","hepatic":"无需调整","interact":"与含钙输液同管使用可沉淀；与华法林合用可能增强抗凝"},{"name":"头孢噻肟","dose":"2 g 静脉滴注 q8h，疗程 5–7 天","note":"国际指南推荐的经典方案，国内亦常用","renal":"CrCl <20 mL/min 减量至常规剂量一半","hepatic":"无需调整","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"哌拉西林-他唑巴坦","dose":"4.5 g 静脉滴注 q6–8h（重症或医疗保健相关感染）","note":"医疗保健相关或产 ESBL 风险高者选用，需结合当地耐药谱","renal":"CrCl 20–40 调整至 4.5 g q8h，<20 减量","hepatic":"无需调整","interact":"与甲氨蝶呤合用增加毒性；与华法林合用增加出血风险"},{"name":"美罗培南","dose":"1 g 静脉滴注 q8h（重症或 ESBL 感染）","note":"用于产 ESBL 肠杆菌或医院获得性重症感染，需防碳青霉烯耐药","renal":"CrCl 26–50 时 1 g q12h，10–25 时 0.5 g q12h，<10 时 0.5 g q24h","hepatic":"无需调整","interact":"与丙戊酸合用显著降低丙戊酸血药浓度"},{"name":"人血白蛋白","dose":"诊断当日 1.5 g/kg 静脉输注，第 3 天 1 g/kg","note":"与抗生素联用可显著降低 HRS 发生率与病死率","renal":"无需调整","hepatic":"无特殊限制","interact":"与静脉营养液配伍需注意"},{"name":"诺氟沙星（一级预防）","dose":"400 mg qd 口服","note":"适用于腹水蛋白 <15 g/L 且 Child-Pugh ≥9 或肾功能/血钠异常的 SBP 高危患者","renal":"CrCl <30 mL/min 减半","hepatic":"无需特殊调整","interact":"与华法林合用增强抗凝"},{"name":"复方新诺明（SBP 二级预防替代）","dose":"遵说明书，常为每周 3–5 天给药","note":"SBP 恢复后预防复发，喹诺酮耐药地区可考虑","renal":"肾功能不全减量","hepatic":"肝功能不全慎用","interact":"与华法林、磺脲类合用增加低血糖和出血风险"}],"nonDrug":["诊断性穿刺后立即开始经验性抗生素，不必等培养结果","48–72 h 复查腹水 PMN，不下降 ≥25% 需考虑继发性腹膜炎或耐药菌，调整方案并复查影像","SBP 恢复后启动二级预防（诺氟沙星或复方新诺明）长期口服","合并 HRS-AKI 者使用特利加压素+白蛋白","感染控制前避免大量放腹水与 TIPS 等侵入操作"],"life":["避免长期 PPI 与不必要抗生素使用","戒酒，保证营养，控制腹水","高危患者定期随访腹水蛋白，必要时预防性抗生素","出现发热、腹痛意外时立即就医，24 h 内穿刺","SBP 后评估肝移植指征"]},"prog":"规范治疗后病死率约 20%–30%，合并 HRS 者病死率 >50%。SBP 后 1 年复发率约 40%–70%，需长期二级预防；反复 SBP 是肝移植的重要指征。","refs":["中华医学会肝病学分会《肝硬化腹水及相关并发症诊疗指南（2023年版）》","中华医学会肝病学分会《肝硬化诊治指南（2019年版）》","AASLD 肝硬化腹水与并发症管理指南（2021）","EASL 肝硬化失代偿管理临床实践指南（2018）"]}]},{"id":"pancreas","name":"胰腺疾病","rank":3,"summary":"急性胰腺炎以「早期液体复苏 + 镇痛 + 早期肠内营养 + 病因处理」为核心，按修订 Atlanta 分级判断轻/中度重症/重症；高甘油三酯性胰腺炎需在降脂同时用胰岛素或血浆置换降 TG。","compare":[{"diseaseId":"ap_acute","dx":"符合以下 3 项中任意 2 项：典型上腹痛向背放射、血清淀粉酶/脂肪酶 >3 倍正常上限、腹部影像（CT/MRI/超声）见胰腺炎改变","key":"不依赖单一酶值；需 48 h 观察是否出现器官衰竭/局部并发症判定轻重度"},{"diseaseId":"ap_htg","dx":"胰腺炎表现 + 血清甘油三酯 ≥11.3 mmol/L（1000 mg/dL），或 5.65–11.3 mmol/L 伴乳糜血清，并排除其他病因","key":"TG 显著升高且常伴糖尿病/脂代谢异常；降 TG 是核心，胰岛素泵入与低脂饮食优先"}],"diseases":[{"id":"ap_acute","name":"急性胰腺炎","aka":["AP","acute pancreatitis","急性胰腺炎症"],"rank":1,"basic":{"define":"多种病因引起胰酶在胰腺内被激活，导致胰腺组织自身消化、水肿、出血甚至坏死的炎症反应，可波及全身多个器官系统。","risk":["胆道疾病（胆石症、胆道感染，国内首位病因）","大量饮酒","高甘油三酯血症（TG ≥11.3 mmol/L）","高钙血症、ERCP 术后、腹部外伤","某些药物（硫唑嘌呤、丙戊酸、GLP-1 受体激动剂罕见）","肥胖（BMI ≥28）、吸烟"],"epi":"我国急性胰腺炎年发病率约 13–45/10 万，近年随饮食结构与胆石症增加而上升；重症约占 10%–20%，重症病死率 20%–30%。"},"patho":"胰管梗阻（胆石嵌顿、Oddi 括约肌痉挛）、酒精刺激与高甘油三酯均使胰液排出受阻或胰蛋白酶过早激活；激活的胰酶（胰蛋白酶、磷脂酶 A2、弹性蛋白酶）引起腺泡损伤与自身消化，释放炎症介质（IL-6、TNF-α）导致全身炎症反应综合征（SIRS）、毛细血管渗漏与第三间隙液体丢失，进而发展为器官衰竭；胰腺坏死组织继发感染是后期死亡主因。","dx":{"criteria":["符合以下 3 项中的任意 2 项即可诊断：① 典型上腹痛（持续性、向背部放射、弯腰可缓解）；② 血清淀粉酶和/或脂肪酶 >3 倍正常上限；③ 增强 CT/MRI/超声见急性胰腺炎的影像学改变","脂肪酶诊断特异性优于淀粉酶（持续时间更长，3–5 天）；酶值高低与病情严重程度无关","修订 Atlanta 分级：轻症（无器官衰竭、无局部并发症）、中度重症（一过性器官衰竭 <48 h 或局部/全身并发症）、重症（持续性器官衰竭 >48 h，改良 Marshall 评分 ≥2 分）","改良 Marshall 评分：呼吸 PaO₂/FiO₂、循环收缩压与补液反应、肾脏血肌酐，任一项 ≥2 分提示相应器官衰竭","CT 严重指数（CTSI）≥7 分或 BISAP 评分 ≥3 分提示重症倾向","全身炎症反应：体温 >38 ℃ 或 <36 ℃、心率 >90 次/分、呼吸 >20 次/分、白细胞 >12×10⁹/L 或 <4×10⁹/L，符合 2 项以上为 SIRS"],"workup":["血淀粉酶、脂肪酶、血常规、C 反应蛋白（48 h 后 >150 mg/L 提示重症）、降钙素原、肝功能（ALT 升高提示胆源性）、血钙、甘油三酯、乳酸","腹部超声：筛查胆石与胆管扩张（胆源性评估）","增强 CT：发病 72 h 后评估胰腺坏死与积液，过早 CT 易低估","MRCP/ERCP：怀疑胆总管结石或胆管炎时","血气分析与胸片：评估呼吸功能","腹部 CT 或 MRI 联合临床评分动态评估，必要时复查（坏死性胰腺炎每 7–10 天）"],"grading":"修订 Atlanta 分级（2012）：① 轻症（MAP）：无器官衰竭、无局部或全身并发症，多在 1–2 周内恢复；② 中度重症（MSAP）：一过性器官衰竭（<48 h）和/或局部并发症（急性液体积聚、假性囊肿、包裹性坏死）或病情加重；③ 重症（SAP）：持续性器官衰竭 >48 h。局部并发症按亚特兰大分类：急性胰周液体积聚（APFC）、急性坏死物积聚（ANC）、胰腺假性囊肿（PPC，>4 周）、包裹性坏死（WON，>4 周）。"},"ddx":[{"name":"高甘油三酯性胰腺炎（ap_htg）","point":"与本类 ap_htg 的鉴别点：高甘油三酯性胰腺炎 TG ≥11.3 mmol/L 且乳糜血清明显，需降 TG 治疗；本类需排查胆石、酒精等病因，TG 正常或轻中度升高不能归因。两者可并存，需同时处理。"},{"name":"胆管结石嵌顿/急性胆管炎","point":"腹痛位于右上腹、Charcot 三联征（腹痛、发热、黄疸）、胆红素与 ALP/GGT 显著升高，超声或 MRCP 见胆管结石，常是胰腺炎病因，需 ERCP 取石。"},{"name":"消化性溃疡穿孔","point":"突发刀割样上腹痛、腹肌板状强直、肝浊音界消失、立位腹平片见膈下游离气体，淀粉酶可轻度升高但不超过 3 倍上限。"},{"name":"急性肠系膜缺血","point":"剧烈腹痛与腹部体征不成比例、房颤或动脉硬化史、乳酸升高，CTA 见肠系膜血管充盈缺损。"},{"name":"肠梗阻","point":"阵发性绞痛、呕吐、腹胀、停止排气排便，腹部立位片见阶梯状液平，CT 见扩张肠管与移行带。"},{"name":"心肌梗死（下壁）","point":"胸骨后压榨痛、心电图 ST 改变、肌钙蛋白升高，淀粉酶多为轻度升高，需心电图与心肌标志物排除。"}],"tx":{"drug":[{"name":"乳酸林格液（液体复苏）","dose":"按 5–10 mL/kg/h 起始，首个 24–48 h 以目标导向（尿量 ≥0.5 mL/kg/h、平均动脉压 ≥65 mmHg、心率 <120 次/分、红细胞压积与尿素氮下降）调整，初期可予 1500–2000 mL 负荷后降至 1.5–3 mL/kg/h（约 3 mL/kg/h 为常用维持速率）","note":"早期（<12–24 h）充分复苏关键；避免过快过量导致容量超负荷与腹腔间隔室综合征；优先平衡晶体（乳酸林格液优于生理盐水）","renal":"少尿性肾损伤者评估容量状态后调整，避免过量负荷","hepatic":"严重肝病者乳酸代谢延迟，监测血乳酸","interact":"含钙液体与头孢曲松同管可沉淀"},{"name":"哌替啶（镇痛）","dose":"25–50 mg 静脉注射，q4–6h，必要时用","note":"充分镇痛可减少交感兴奋与胰腺分泌；避免吗啡（可能增加 Oddi 括约肌压力），但指南认为此差异证据有限","renal":"重度肾功能不全者慎用（去甲哌替啶蓄积）","hepatic":"重度肝病者减量","interact":"与 MAO 抑制剂合用有严重相互作用，禁忌"},{"name":"对乙酰氨基酚（辅助镇痛）","dose":"1 g 口服或静脉 q6h，每日不超过 3 g（肝病患者 ≤2 g/d）","note":"非阿片类镇痛可作为基础镇痛，需注意肝功能","renal":"CrCl <30 mL/min 延长给药间隔","hepatic":"肝硬化或肝功能不全者每日最大 2 g","interact":"与华法林长期合用可升高 INR"},{"name":"头孢哌酮-舒巴坦（合并感染时）","dose":"3 g 静脉滴注 q8h（或 2 g q12h）","note":"仅用于胰腺坏死合并感染、胆管炎或明确感染，不常规预防性使用抗生素","renal":"CrCl <30 mL/min 调整给药间隔","hepatic":"胆道梗阻时注意排泄延迟","interact":"含 N-甲基硫代四唑结构，可致双硫仑样反应，用药期间禁酒"},{"name":"美罗培南（重症感染）","dose":"1 g 静脉滴注 q8h","note":"重症胰腺坏死感染、产 ESBL 风险高者选用","renal":"CrCl 26–50 时 1 g q12h，10–25 时 0.5 g q12h，<10 时 0.5 g q24h","hepatic":"无需调整","interact":"与丙戊酸合用降低丙戊酸浓度"},{"name":"生长抑素/奥曲肽（抑制分泌）","dose":"奥曲肽 0.1 mg 皮下注射 q8h 或 25–50 μg/h 静脉泵入；生长抑素 250 μg/h 静脉泵入","note":"用于重症或合并胰腺假性囊肿/胰瘘，常规轻症证据不足","renal":"肾功能不全者减量","hepatic":"肝硬化者半衰期延长","interact":"与胰岛素、口服降糖药合用可致血糖波动"},{"name":"乌司他丁（蛋白酶抑制剂）","dose":"10 万单位静脉滴注，q8–12h（遵说明书）","note":"国内常用辅助抗炎，重症可考虑，证据级别有限","renal":"肾功能不全者减量","hepatic":"无需调整","interact":"与同类蛋白酶抑制剂不联用"}],"nonDrug":["早期肠内营养：能耐受者 24–72 h 内启动经口或鼻肠管喂养（低脂），不要求肠道休息，可降低感染并发症与病死率","鼻空肠管 vs 鼻胃管：无证据支持鼻空肠优于鼻胃管；重症者优先鼻空肠","胆源性胰腺炎合并胆管炎或持续胆道梗阻：72 h 内 ERCP 取石；无胆管炎者不推荐急诊 ERCP","腹腔间隔室综合征：监测膀胱压，>20 mmHg 伴新发器官功能障碍时减压","坏死感染（WON）>4 周首选内镜下经胃引流（step-up approach），失败再外科清创","胆囊结石合并胰腺炎：本次发作后 2–4 周内行胆囊切除术（轻症可同次住院完成）"],"life":["急性期禁食时间尽量缩短，能耐受即进食低脂流质","戒酒（酒精性）与严格控制甘油三酯（高 TG 者）","出院后 4–8 周复查 CT 或超声评估假性囊肿","胆石症患者按时行胆囊切除","戒烟、控制体重，避免暴饮暴食"]},"prog":"轻症（MAP）病死率 <1%–2%，多 1 周内恢复；重症（SAP）病死率 20%–30%，伴持续性器官衰竭与感染性坏死时更高。约 10%–20% 患者出现假性囊肿或 WON，多数可自行吸收或经内镜/外科处理。","refs":["中华医学会外科学分会胰腺外科学组《中国急性胰腺炎诊治指南（2021年，北京）》","中华医学会消化病学分会《中国急性胰腺炎诊治指南（2021）》","IAP/APA 急性胰腺炎循证指南（2013）","2012 修订 Atlanta 急性胰腺炎分类国际共识"]},{"id":"ap_htg","name":"高甘油三酯性胰腺炎","aka":["HTG-AP","hypertriglyceridemia pancreatitis","高脂血症性胰腺炎"],"rank":2,"basic":{"define":"由严重高甘油三酯血症（通常 TG ≥11.3 mmol/L）引起的急性胰腺炎，占我国急性胰腺炎的 10%–20%，与代谢综合征、糖尿病和饮酒密切相关。","risk":["未控制的糖尿病（尤其 1 型与血糖控制差的 2 型）","代谢综合征、肥胖、非酒精性脂肪性肝病","大量饮酒","妊娠期高脂血症","某些药物（雌激素、他莫昔芬、糖皮质激素、异维 A 酸、部分抗精神病药）","家族性高甘油三酯血症"],"epi":"我国高甘油三酯性胰腺炎占急性胰腺炎的 10%–20%，在部分经济发达地区与年轻男性中比例更高；复发率高（1 年内 15%–30%），合并糖尿病者更易复发。"},"patho":"血浆 TG 过高时乳糜微粒与极低密度脂蛋白增多，血液黏度增加导致胰腺微循环障碍；同时高脂环境使游离脂肪酸大量释放，超过白蛋白结合能力后损伤腺泡细胞与毛细血管内皮，缺血-再灌注与酸中毒共同激活胰酶，形成恶性循环；乳糜血清使脂血性干扰淀粉酶测定，导致酶值假性偏低。","dx":{"criteria":["符合急性胰腺炎的诊断标准（腹痛 + 酶 >3 倍上限 + 影像，任 2 项）","血清甘油三酯 ≥11.3 mmol/L（1000 mg/dL），或 5.65–11.3 mmol/L 伴乳糜血清且排除其他病因","排除胆石（超声未见结石及胆管扩张）、酒精、高钙、药物、ERCP 等其他病因","脂血标本可致淀粉酶假性降低，需结合脂肪酶与影像判断","合并糖尿病者 HbA1c 与血糖监测有助于评估病因与复发风险","严重程度按修订 Atlanta 分级（MAP/MSAP/SAP），HTG-AP 更易出现器官衰竭与局部并发症"],"workup":["血清甘油三酯（空腹，轻度血脂异常者可非空腹）、总胆固醇、HDL-C、LDL-C","血淀粉酶与脂肪酶、血糖、HbA1c、血气（酸中毒）、乳酸","腹部超声与 CT：评估胰腺炎严重程度并排查胆源性","甲状腺功能（甲减可致高甘油三酯血症）","家族史与用药史评估，必要时行脂代谢遗传学筛查"],"grading":"按 TG 水平分为重度（5.65–11.3 mmol/L）与极重度（≥11.3 mmol/L）；按急性胰腺炎修订 Atlanta 分级 MAP/MSAP/SAP。TG 水平分级也用于复发性胰腺炎风险评估。"},"ddx":[{"name":"急性胰腺炎（ap_acute，其他病因）","point":"与本类 ap_acute 的鉴别点：胆源性者超声见胆结石、ALT 升高；酒精性者常有大量饮酒史；本类以 TG ≥11.3 mmol/L 与乳糜血清为核心。两者可并存，需同时行胆道超声与 TG 检测。"},{"name":"糖尿病酮症酸中毒","point":"高血糖、酮体阳性、代谢性酸中毒、脱水，可伴腹痛与淀粉酶轻度升高；DKA 也可并发胰腺炎，需测 TG 与行 CT 区分。"},{"name":"胆管结石/胆管炎","point":"胆红素与 ALP/GGT 显著升高、胆管扩张，MRCP 见结石；与 TG 无关。"},{"name":"肠系膜缺血","point":"腹痛剧烈而体征轻、乳酸升高、房颤史，CTA 见血管充盈缺损；乳糜血不常见。"},{"name":"胰腺癌所致梗阻性胰腺炎","point":"中老年、消瘦、CA19-9 升高，影像见胰管扩张与肿块，需增强 CT/EUS 排除。"}],"tx":{"drug":[{"name":"普通胰岛素（静脉泵入）","dose":"0.1 U/kg/h 持续静脉泵入，按血糖目标 6.1–8.3 mmol/L 调整（每 1–2 h 测血糖）；血糖 <5.6 mmol/L 时暂停并补充葡萄糖","note":"通过激活脂蛋白脂酶降低 TG，同时控制血糖；是 HTG-AP 一线降 TG 手段","renal":"肾功能不全者胰岛素清除减少，需更频繁监测血糖","hepatic":"肝功能不全者注意低血糖","interact":"与 β 受体阻滞剂合用可能掩盖低血糖症状"},{"name":"乳酸林格液（初始复苏）","dose":"5–10 mL/kg/h 起始，24 h 内 2500–4000 mL（心肾功能不全者酌减），目标尿量 ≥0.5 mL/kg/h","note":"早期积极液体复苏稀释血液黏度，改善胰腺微循环","renal":"肾功能不全者减慢速率，监测出入量","hepatic":"严重肝病者监测乳酸清除","interact":"与头孢曲松同管沉淀（新生儿）"},{"name":"低分子肝素（部分中心经验用法）","dose":"依诺肝素 40–60 mg 皮下注射 q12h（遵说明书，需评估出血风险）","note":"促进脂蛋白脂酶释放，降低 TG，但缺乏大样本证据，不作为常规","renal":"CrCl <30 mL/min 减量或改用普通肝素","hepatic":"严重肝病慎用","interact":"与抗血小板药联用增加出血"},{"name":"非诺贝特","dose":"200 mg qd 口服（微粒化 145 mg qd）","note":"急性期稳定后启动降 TG 治疗，TG 极高者出院前即开始","renal":"CrCl <60 mL/min 减量或避免（肌病风险）","hepatic":"活动性肝病或胆石症者禁用（增加胆汁胆固醇饱和度）","interact":"与他汀联用增加肌病风险，需监测 CK；与华法林合用增强抗凝"},{"name":"他汀类（如阿托伐他汀）","dose":"阿托伐他汀 10–20 mg qn 起始（遵说明书）","note":"以降低 LDL-C 与心血管风险为主，降 TG 作用有限；常与贝特联合","renal":"无需调整","hepatic":"活动性肝病禁用，监测肝酶","interact":"贝特类、环孢素合用增加肌病风险"},{"name":"高纯度 ω-3 脂肪酸","dose":"2–4 g/d 口服（遵说明书）","note":"辅助降低 TG（降幅约 20%–30%），安全性好","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝药合用可能轻度延长出血时间"},{"name":"哌替啶（镇痛）","dose":"25–50 mg 静脉注射，q4–6h","note":"与其他急性胰腺炎相同，充分镇痛","renal":"重度肾功能不全慎用","hepatic":"重度肝病者减量","interact":"与 MAO 抑制剂禁忌联用"}],"nonDrug":["血浆置换/血液灌流：TG 极高（>22.6 mmol/L）或合并器官衰竭、胰岛素治疗无效者，可快速降低 TG（证据有限，属挽救措施）","早期肠内营养（低脂、<20% 热量来自脂肪），必要时禁食仅短期","禁酒、停用可致高 TG 的药物（雌激素、糖皮质激素等）","血糖控制：胰岛素泵或强化治疗，避免血糖波动","重度肥胖者评估减重与代谢手术适应证"],"life":["长期低脂饮食（脂肪 <20% 总热量），戒酒","规律使用贝特类/ω-3 脂肪酸，目标 TG <5.65 mmol/L（低于胰腺炎阈值）","控制体重、血糖与 HbA1c（<7.0%）","每 3–6 个月复查血脂，复发者更密切","警惕家族性高甘油三酯血症，必要时筛查一级亲属"]},"prog":"重症比例与器官衰竭发生率高于胆源性胰腺炎；复发率高（1 年约 15%–30%），规范降 TG 治疗与戒酒可显著降低复发。合并糖尿病且血糖控制不佳者预后较差。","refs":["中华医学会外科学分会胰腺外科学组《中国急性胰腺炎诊治指南（2021年，北京）》","中国医师协会胰腺病学专业委员会《高甘油三酯血症性急性胰腺炎诊治急诊专家共识（2021）》","中华医学会内分泌学分会《中国血脂管理指南（2023年）》","2020 欧洲动脉硬化学会（EAS）血脂异常管理指南"]}]},{"id":"ibd","name":"炎症性肠病","rank":4,"summary":"溃疡性结肠炎病变局限于结肠黏膜、自直肠向近端连续分布，治疗以 5-ASA 为基石并按 Mayo 评分分级；克罗恩病为节段性透壁炎症，需按蒙特利尔分型评估部位与行为，中重度者尽早启动生物制剂与「达标治疗」。","compare":[{"diseaseId":"uc","dx":"反复黏液血便、里急后重，结肠镜见自直肠向近端连续弥漫性黏膜炎症（血管纹理消失、糜烂/溃疡）、病理为隐窝结构扭曲与基底浆细胞增多，无肉芽肿","key":"连续、直肠受累、限于黏膜层；治疗以 5-ASA 为基础，重度用激素/生物制剂"},{"diseaseId":"cd","dx":"腹痛、腹泻、体重下降，内镜见节段性、跳跃性病变（纵行溃疡、鹅卵石样、狭窄），可累及回肠末段与肛周，病理见非干酪样肉芽肿","key":"跳跃性、透壁性、可累及全消化道与肛周，需按部位与行为分型，重度/肛周病变首选抗 TNF 或抗整合素"}],"diseases":[{"id":"uc","name":"溃疡性结肠炎","aka":["UC","ulcerative colitis","慢性非特异性溃疡性结肠炎"],"rank":1,"basic":{"define":"病因未明的慢性非特异性肠道炎症，病变主要累及结肠黏膜与黏膜下层，自直肠开始向近端连续分布，临床以血性腹泻、黏液脓血便与里急后重为特点，呈反复发作与缓解交替。","risk":["发病高峰 20–49 岁，男性略多（欧美）","遗传易感（NOD2、HLA 区域等多基因）","肠道菌群失衡与黏膜免疫异常","吸烟对 UC 有一定保护作用（不同于 CD）","阑尾切除史、口服避孕药","精神应激、NSAIDs 使用可诱发复发"],"epi":"欧美发病率约 10–20/10 万，我国近 20 年发病率显著上升（约 1–3/10 万），患者年龄多在 20–49 岁，病程常迁延数十年。"},"patho":"遗传易感个体在肠道菌群、环境因素与免疫调节异常的共同作用下，Th2 样免疫反应与 IL-13 介导的黏膜屏障损伤导致上皮细胞凋亡增加、紧密连接破坏，中性粒细胞浸润形成隐窝脓肿；炎症由直肠向近端连续蔓延，病变局限于黏膜与黏膜下层，长期反复炎症增加结直肠癌风险。","dx":{"criteria":["临床表现：持续或反复发作的黏液血便、腹泻、腹痛、里急后重，病程 >4 周，排除感染性结肠炎","结肠镜：自直肠连续向近端弥漫性黏膜炎症，血管纹理模糊或消失、红斑、脆性增加、糜烂、浅溃疡，假息肉形成；直肠受累是必要条件（少数直肠豁免）","病理：隐窝结构扭曲（分支、缩短）、基底浆细胞增多、隐窝炎与隐窝脓肿，无非干酪样肉芽肿，炎症限于黏膜层","粪便培养、艰难梭菌毒素、寄生虫检查（至少 1 次）阴性以排除感染","疾病范围（蒙特利尔分型）：E1 直肠炎、E2 左半结肠炎（至脾曲）、E3 广泛结肠炎（超过脾曲）","疾病活动度（改良 Mayo 评分，0–12 分）：≤2 分且无直肠出血为临床缓解；3–5 分轻度、6–10 分中度、11–12 分重度"],"workup":["结肠镜 + 活检：首次诊断必备；重度急性发作避免全结肠镜以防穿孔，可行乙状结肠镜","粪便钙卫蛋白（>250 μg/g 提示活动）、CRP、ESR、血常规（贫血、血小板）、白蛋白","粪便艰难梭菌毒素与培养、寄生虫与致病菌培养","腹部平片（重度发作时排除中毒性巨结肠：结肠横径 >6 cm）","CMV 检测：重度激素抵抗者行肠黏膜 CMV-IgM/IHC 或 CMV DNA","随访：轻中度每 3–6 个月评估活动度，病程 8 年以上行结肠镜结肠癌监测"],"grading":"改良 Mayo 评分：排便次数、便血、内镜发现、医师总体评价各项 0–3 分。轻度 3–5 分、中度 6–10 分、重度 11–12 分。急性重度 UC（Montreal 标准）：≥6 次/d 血便，伴发热、心动过速、贫血（Hb <105 g/L）、ESR >30 mm/h 中至少 1 项。"},"ddx":[{"name":"克罗恩病（cd）","point":"与本类 cd 的鉴别点：UC 连续、自直肠开始、限于黏膜；CD 跳跃性、可累及回肠末段与肛周、透壁性、可有肉芽肿；UC 血便更突出，CD 以腹痛、瘘管与腹泻为主。约 10% 结肠IBD 难以分型（IBD-U）。"},{"name":"感染性结肠炎（沙门菌、志贺菌、弯曲菌、阿米巴）","point":"急性起病、有食物/旅行史与发热，粪便培养或阿米巴滋养体阳性，抗感染后迅速好转，无慢性隐窝结构改变。"},{"name":"缺血性结肠炎","point":"老年、动脉硬化或低血压史，突發腹痛后少量血便，病变多在结肠脾曲等分水岭区，呈节段性，内镜见纵行溃疡与黏膜苍白，自限性。"},{"name":"艰难梭菌感染性结肠炎","point":"近期抗生素使用史，粪便毒素/谷氨酸脱氢酶阳性，内镜见假膜性炎（黄色斑块），根治需停用诱因抗生素+口服万古霉素/非达霉素。"},{"name":"结直肠癌/淋巴瘤","point":"伴消瘦、贫血、肿块，肠镜见隆起性病变，多点活检病理确诊。"}],"tx":{"drug":[{"name":"美沙拉嗪（口服，轻中度）","dose":"2–4 g/d 分 2–4 次口服（E3 广泛型或中重度可 4 g/d），缓解后维持 2 g/d","note":"轻中度 UC 的一线诱导与维持治疗；疗效与剂量相关，直肠炎需联合局部制剂","renal":"CrCl <30 mL/min 慎用，监测肾功能（间质性肾炎风险）","hepatic":"肝功能不全者慎用","interact":"与硫唑嘌呤合用增加骨髓抑制风险；与 NSAIDs、肾毒性药物合用增加肾损伤"},{"name":"美沙拉嗪（灌肠/栓剂，直肠炎）","dose":"栓剂 1 g qd（或 500 mg bid）；灌肠剂 4 g/100 mL qn 或 2 g bid","note":"E1 直肠炎首选局部 5-ASA；与口服联合优于单药","renal":"同口服制剂","hepatic":"同口服制剂","interact":"同口服制剂"},{"name":"泼尼松（中度/重度诱导）","dose":"40 mg qd（0.75–1 mg/kg/d，最大 60 mg/d）口服，诱导缓解 4–8 周后按每周 5 mg 递减至停药","note":"用于中重度活动期诱导，不用于维持；重度发作可用静脉甲泼尼龙 40–60 mg/d","renal":"无需调整，注意水钠潴留","hepatic":"肝功能不全者需减量","interact":"与 NSAIDs 合用增加消化道出血；与活疫苗同用禁忌"},{"name":"甲泼尼龙（静脉，重度）","dose":"40–60 mg 静脉 qd，疗程 3–5 天","note":"急性重度 UC 首选；72 h 无效者评估英夫利西单抗或环孢素挽救治疗","renal":"无需调整","hepatic":"肝功能不全者减量","interact":"与CYP3A4 抑制剂合用升高血药浓度"},{"name":"布地奈德（MMX）","dose":"9 mg qd 口服，8 周；或局部泡沫/灌肠剂 2 mg qd","note":"局部作用于结肠，全身副作用小，适用于轻中度左半结肠炎","renal":"无需调整","hepatic":"重度肝功能不全（Child-Pugh C）避免使用","interact":"强 CYP3A4 抑制剂（酮康唑、葡萄柚汁）显著升高血药浓度"},{"name":"硫唑嘌呤（维持/激素依赖）","dose":"起始 1.5–2.5 mg/kg/d 口服（常用 50 mg/d 起始，渐增至 100–150 mg/d），需 8–12 周起效","note":"激素依赖或反复复发者维持治疗；用药前查 TPMT/NUDT15","renal":"肾功能不全者慎用","hepatic":"严重肝功能不全者禁用","interact":"与别嘌醇、非布司他合用显著增加骨髓抑制，需减量 75%"},{"name":"英夫利西单抗（抗 TNF）","dose":"5 mg/kg 静脉输注，0、2、6 周诱导，之后每 8 周维持；急性重度 UC 诱导可 5 mg/kg 单次（部分中心 10 mg/kg）","note":"中重度、激素抵抗/依赖或肛周病变者；用药前筛查结核与 HBV","renal":"无需调整","hepatic":"重度肝病者慎用，需监测肝酶","interact":"与免疫抑制剂联用增加感染与淋巴瘤风险；避免活疫苗"},{"name":"戈利木单抗/阿达木单抗（抗 TNF 皮下）","dose":"阿达木单抗 160 mg 第 1 天、80 mg 第 2 周，之后 40 mg 每 2 周；戈利木单抗 200 mg 第 0 周、100 mg 第 2 周，之后 100 mg 每 4 周","note":"患者偏好居家皮下给药时选择；同样需筛查结核与 HBV","renal":"无需调整","hepatic":"重度肝病者慎用","interact":"与硫唑嘌呤联用增加感染风险"},{"name":"维得利珠单抗（抗整合素）","dose":"300 mg 静脉输注，第 0、2、6 周诱导，之后每 8 周维持","note":"优先用于老年、合并感染/肿瘤风险者；选择性肠道淋巴细胞迁移抑制","renal":"无需调整","hepatic":"无需调整","interact":"免疫抑制叠加增加机会性感染风险"},{"name":"环孢素（重症挽救治疗）","dose":"2 mg/kg/d 持续静脉泵入，按血药浓度（目标 150–250 ng/mL）调整","note":"激素抵抗的急性重度 UC 挽救治疗二线（英夫利西单抗不可得时）；需监测血压、肾功能、血镁","renal":"肾功能不全者减量或禁用","hepatic":"重度肝病者慎用","interact":"强 CYP3A4 抑制剂（他汀、唑类抗真菌药）显著升高浓度；与他汀联用致肌病"}],"nonDrug":["急性重度 UC：住院、静脉激素，24–72 h 评估，失败者英夫利西单抗或环孢素挽救，5–7 天无效考虑急诊结肠切除","中毒性巨结肠：禁结肠镜与抗动力药，置肠减压、监测，48–72 h 无效手术解除","手术指征：难治性/激素依赖、急性重症内科治疗失败、结直肠癌/高级别异型增生、大出血或穿孔；术式为全结直肠切除+回肠储袋肛管吻合（IPAA）","结肠癌监测：病程 8 年后每 1–2 年结肠镜（伴原发性硬化性胆管炎者每年）","妊娠期：美沙拉嗪安全；重度发作仍用激素与抗 TNF；避免甲氨蝶呤、沙利度胺"],"life":["戒烟并非 UC 必需（与 CD 不同），但应在其他心血管风险下综合评估","避免 NSAIDs、抗生素滥用与精神应激","营养支持：铁、维生素 D、B12 监测补充","规律随访，按需行粪便钙卫蛋白监测（<250 μg/g 为缓解目标）","接种疫苗（流感、乙肝、肺炎球菌）并于免疫抑制前完成"]},"prog":"轻中度患者 5-ASA 维持下多数可获得长期缓解；约 15%–20% 重度发作需手术，急性重度 UC 住院病死率约 1%–3%。病程 8–10 年后结直肠癌风险增加，需规范监测。","refs":["中华医学会消化病学分会炎症性肠病学组《中国炎症性肠病诊断与治疗的共识意见（2018年，北京）》","中华医学会消化病学分会《炎症性肠病诊断与治疗规范（2023年版）》","2023 ACG 溃疡性结肠炎临床指南","2022 ECCO 溃疡性结肠炎治疗指南"]},{"id":"cd","name":"克罗恩病","aka":["CD","Crohn's disease","节段性肠炎"],"rank":2,"basic":{"define":"病因未明的慢性肉芽肿性炎症，可累及消化道任何部位（最常见回肠末段与结肠），呈节段性跳跃分布、透壁性炎症，可形成狭窄、瘘管与肛周病变。","risk":["发病高峰 20–30 岁，女性略多","遗传易感（NOD2/CARD15、ATG16L1、IL23R 等）","吸烟（显著增加风险与复发）","肠道菌群失衡（AIEC 等）与黏膜免疫异常","阑尾切除或重度胃肠炎后","饮食西化、城市生活"],"epi":"欧美发病率约 20/10 万；我国近年发病率明显上升（约 1–2/10 万），发病年龄多在 20–40 岁，儿童期发病者病程更进展性。"},"patho":"遗传易感个体在环境因素（吸烟、菌群）触发下，Th1/Th17 免疫反应激活，TNF-α、IL-12/23 推动慢性肉芽肿性炎症；炎症穿透肠壁各层（透壁性），导致纤维化狭窄、穿透性瘘管与肠外脓肿；黏膜淋巴细胞迁移（α4β7 整合素）在肠道炎症定位中起关键作用。病变呈节段性分布（跳跃区），末端回肠与右半结肠最常受累。","dx":{"criteria":["慢性或反复发作的腹痛、腹泻、体重下降，病程 >6 周，可伴肛周瘘管/脓肿、肠皮瘘或肠梗阻","内镜：节段性、跳跃性病变，纵行溃疡、鹅卵石样改变、肠腔狭窄，直肠常豁免；病理见非干酪样肉芽肿（阳性率 30%–50%）、裂隙状溃疡、透壁性炎症","影像（CTE/MRE）：肠壁增厚 >3 mm、靶征、肠周脂肪纤维化、瘘管与脓肿","蒙特利尔分型：年龄（A1 ≤16 岁、A2 17–40 岁、A3 >40 岁）、部位（L1 回肠末段、L2 结肠、L3 回结肠、L4 上消化道）、行为（B1 非狭窄非穿透、B2 狭窄、B3 穿透、p 肛周病变）","克罗恩病活动指数（CDAI）：<150 缓解；150–220 轻度；220–450 中度；>450 重度","钙卫蛋白 >250 μg/g 与 CRP 升高提示活动；排除肠结核、淋巴瘤、NSAIDs 肠病"],"workup":["结肠镜 + 回肠末段活检（必备）；上消化道内镜见于儿童与上消化道症状者","小肠 CT 成像（CTE）或磁共振小肠成像（MRE）：评估病变范围、狭窄、瘘管与脓肿","粪便钙卫蛋白、CRP、ESR、血常规、白蛋白、铁代谢、维生素 B12、叶酸","肛周评估（MRI、麻醉下检查）用于肛周病变","结核筛查（T-SPOT/PPD + 胸片）与 HBV 筛查：启动生物制剂前必查","病理复核与多学科讨论（IBD-MDT）以鉴别肠结核"],"grading":"按 CDAI 分缓解/轻度/中度/重度；按蒙特利尔分型（部位 L1–L4、行为 B1–B3、肛周病变 p）；按内镜 SES-CD 评分与影像评估 \"达标治疗\"（内镜缓解为 SES-CD ≤2 分，可伴孤立回肠狭窄）。"},"ddx":[{"name":"溃疡性结肠炎（uc）","point":"与本类 uc 的鉴别点：CD 跳跃性、可累及回肠末段与上消化道、透壁性、可见肉芽肿与肛周病变；UC 连续弥漫、限于黏膜、直肠必受累且血便更突出。约 10% 结肠段炎症难以分型（IBD-U），需长期随访。"},{"name":"肠结核","point":"常累及回盲部，伴低热、盗汗、PPD/T-SPOT 阳性、胸片见结核灶，内镜见环形溃疡（CD 多为纵行），病理见干酪样坏死；诊断不明时诊断性抗结核治疗 8–12 周。"},{"name":"肠淋巴瘤/小肠腺癌","point":"中老年、消瘦、贫血，CTE 见肿块性病变而非单纯肠壁增厚，多点或 EUS 穿刺活检病理确诊。"},{"name":"NSAIDs 相关性肠病","point":"长期 NSAIDs 用药史，停药后改善，小肠胶囊内镜见多发浅表溃疡（隔膜样狭窄），无透壁炎症与肉芽肿。"},{"name":"白塞病肠炎","point":"口腔与生殖器溃疡、眼部葡萄膜炎，内镜见回盲部圆形深大溃疡（非纵行），针刺试验阳性。"}],"tx":{"drug":[{"name":"泼尼松（诱导缓解）","dose":"40 mg qd（0.75–1 mg/kg/d，最大 60 mg/d）口服，2–4 周后递减，总疗程 8–12 周内停用","note":"用于中重度活动诱导，不用于维持；可联合硫唑嘌呤减少激素暴露","renal":"无需调整","hepatic":"肝功能不全者减量","interact":"与 NSAIDs 合用增加消化道并发症；活疫苗禁忌"},{"name":"布地奈德（回肠末段/回盲部轻中度）","dose":"9 mg qd 口服，8 周（维持 6 mg qd 最长 12 周）","note":"病变局限于回肠末段或回盲部轻中度者，全身不良反应小","renal":"无需调整","hepatic":"Child-Pugh C 级避免","interact":"强 CYP3A4 抑制剂显著升高血药浓度"},{"name":"美沙拉嗪（轻中度，有限证据）","dose":"3–4 g/d 口服，分次服","note":"仅用于结肠型/轻中度病变，诱导与维持证据较弱，不推荐用于重度或透壁病变","renal":"CrCl <30 mL/min 慎用","hepatic":"肝功能不全者慎用","interact":"与硫唑嘌呤合用增加骨髓抑制"},{"name":"硫唑嘌呤（维持/激素依赖）","dose":"1.5–2.5 mg/kg/d 口服，8–12 周起效；用药前查 TPMT/NUDT15","note":"维持缓解与减少激素依赖，与抗 TNF 联用可提高生物制剂疗效","renal":"肾功能不全者慎用","hepatic":"严重肝功能不全禁用","interact":"与别嘌醇/非布司他显著增加骨髓抑制，需减量 75%"},{"name":"甲氨蝶呤（不耐受硫唑嘌呤）","dose":"25 mg 肌注/皮下 每周一次（诱导可 25 mg 每周），联合叶酸 5 mg/wk 次日给予","note":"适用于硫唑嘌呤不耐受或合并关节症状；妊娠期禁用","renal":"CrCl <30 mL/min 慎用，需监测","hepatic":"严重肝病禁用，监测肝纤维化","interact":"与 NSAIDs、复方新诺明合用增加骨髓抑制"},{"name":"英夫利西单抗（抗 TNF）","dose":"5 mg/kg 静脉输注，0、2、6 周诱导，之后每 8 周维持；部分患者需增量至 10 mg/kg 或缩短间隔","note":"中重度活动、瘘管型肛周病变、激素依赖者的一线生物制剂；用药前筛查结核与 HBV","renal":"无需调整","hepatic":"监测肝酶，重度肝病慎用","interact":"与免疫抑制剂联用增加感染与淋巴瘤风险；活疫苗禁忌"},{"name":"阿达木单抗（抗 TNF 皮下）","dose":"160 mg 第 0 周、80 mg 第 2 周，之后 40 mg 每 2 周（重症可 40 mg 每周）","note":"患者可居家皮下注射；与硫唑嘌呤联用需权衡感染风险","renal":"无需调整","hepatic":"重度肝病慎用","interact":"免疫抑制叠加增加机会性感染"},{"name":"维得利珠单抗（抗整合素）","dose":"300 mg 静脉输注，第 0、2、6 周，之后每 8 周","note":"中重度活动、老年或感染/肿瘤风险高者优先推荐","renal":"无需调整","hepatic":"无需调整","interact":"免疫抑制叠加增加感染风险"},{"name":"乌司奴单抗（抗 p40/IL-12/23）","dose":"第 0 周静脉 6 mg/kg（部分按体重），第 8 周起皮下 90 mg q8–12 周","note":"抗 TNF 失败或不耐受者的重要选择；维持剂量可按体重与疗效调整","renal":"无需调整","hepatic":"无需调整","interact":"活疫苗禁忌；其他免疫抑制叠加需权衡"},{"name":"甲硝唑/环丙沙星（肛周病变）","dose":"甲硝唑 400 mg tid 或环丙沙星 500 mg bid，4–8 周（联合引流通畅）","note":"肛周瘘管作为抗 TNF 的辅助，需同时外科挂线引流","renal":"肾功能不全减量","hepatic":"肝功能不全者减量","interact":"甲硝唑与酒精呈双硫仑样反应；环丙沙星与含铝/镁抗酸剂降低吸收"},{"name":"肠内营养（儿童诱导）","dose":"全肠内营养（EEN）配方 100% 热量供给 6–8 周（遵说明书与能量需求）","note":"儿童与青少年 CD 诱导缓解的一线选择，可促进黏膜愈合与生长","renal":"肾功能不全调整蛋白与电解质","hepatic":"肝功能不全者用支链氨基酸配方","interact":"无需考虑药物相互作用"}],"nonDrug":["狭窄型：评估内镜下球囊扩张或外科狭窄成形术（保留肠管），避免反复切除导致短肠","穿透型/脓肿：经皮引流后抗 TNF + 抗生素，引流失败外科处理；瘘管需多学科评估","肛周病变：麻醉下检查、挂线引流、瘘管切开或括约肌保留手术","手术指征：完全性肠梗阻、脓肿/穿孔、内科治疗失败、癌变；术式为回盲部切除或狭窄成形术","戒烟是 CD 最重要且成本最低的干预","结肠癌监测：病程 8–10 年后每 1–3 年结肠镜"],"life":["绝对戒烟","营养评估与补充（铁、维生素 B12、维生素 D、锌）","定期粪便钙卫蛋白与 CRP 监测，实现达标治疗（内镜缓解）","接种疫苗，免疫抑制治疗前完成","妊娠期：控制在缓解期后再妊娠；抗 TNF 相对安全，避免甲氨蝶呤"]},"prog":"终身慢性反复病程，多数患者经历缓解-复发交替。约 50% 患者需在 10 年内接受手术，术后内镜下复发率高（1 年约 70%），需持续治疗。规范生物制剂与达标治疗可显著降低住院与手术率。","refs":["中华医学会消化病学分会炎症性肠病学组《中国炎症性肠病诊断与治疗的共识意见（2018年，北京）》","中华医学会消化病学分会《炎症性肠病诊断与治疗规范（2023年版）》","2021 中华医学会《克罗恩病诊治指南》","2021 ACG 克罗恩病管理指南","2019 ECCO 克罗恩病诊断与管理共识"]}]},{"id":"liver","name":"其他肝病","rank":5,"summary":"药物性肝损伤以 R 值分型、停药为第一位，重度需 N-乙酰半胱氨酸；慢性乙型肝炎以 HBcAg 与 HBV DNA 为启动抗病毒依据，首选恩替卡韦/替诺福韦，需长期治疗与肝癌监测。","compare":[{"diseaseId":"dili","dx":"有明确可疑药物/保健品暴露史，ALT/AST 或 ALP 升高超过正常上限（ALT >5 ULN 或 ALP >2 ULN），排除病毒性、自身免疫性、胆道梗阻等其他病因","key":"R 值 = (ALT/ULN)/(ALP/ULN) 判型：R ≥5 肝细胞型、2 < R < 5 混合型、R ≤2 胆汁淤积型；停药是首要措施"},{"diseaseId":"hbv","dx":"HBsAg 阳性 ≥6 个月，HBV DNA 可检测，伴 ALT 持续升高（>ULN–2×ULN）或肝组织学活动/纤维化","key":"DNA 水平 + ALT + 纤维化程度决定是否启动抗病毒（HBV DNA >2000 IU/mL + ALT 升高）"}],"diseases":[{"id":"dili","name":"药物性肝损伤","aka":["DILI","drug-induced liver injury","药物性肝炎"],"rank":1,"basic":{"define":"由各类处方药、非处方药、保健品、草药或膳食补充剂引起的肝损伤，是排他性诊断，按损伤类型分为肝细胞型、胆汁淤积型和混合型。","risk":["年龄 >55 岁、女性","原有肝病（HBV/HCV、脂肪肝、酒精性肝病）","多药合用、剂量过大（对乙酰氨基酚）","长期饮酒、营养不良","HLA 易感基因型（如阿巴卡韦 HLA-B*57:01、卡马西平 HLA-B*15:02）","草药与膳食补充剂滥用（何首乌、土三七等）"],"epi":"我国 DILI 年发病率估计约 23.8/10 万，草药与膳食补充剂（HDS）为主要病因之一（约 20%–30%），传统中草药相关报道比例高于欧美。多数可恢复，约 10%–15% 进展为慢性化，重症病例病死率 10%–20%。"},"patho":"两种主要机制：① 直接毒性（剂量依赖性，如对乙酰氨基酚经 CYP2E1 转化为 NAPQI 耗竭谷胱甘肽致线粒体损伤与坏死）；② 特异质反应（免疫介导或无免疫介导，与 HLA 基因型相关，如阿莫西林-克拉维酸、抗结核药）。胆汁淤积型多因药物抑制胆盐外排泵（BSEP）或损伤胆管上皮。","dx":{"criteria":["明确的药物/保健品暴露史，潜伏期数天至数月（特异质反应多为 5–90 天）","血清 ALT 或 AST >5×ULN 且 ALP 正常，或 ALP >2×ULN，或 ALT >3×ULN 伴总胆红素 >2×ULN（Hy's law 预警：ALT >3×ULN + TBIL >2×ULN 提示严重风险）","R 值 = (ALT/ULN ALT) / (ALP/ULN ALP)：R ≥5 肝细胞型、2 < R < 5 混合型、R ≤2 胆汁淤积型","排除病毒性肝炎（HBV/HCV/HEV/CMV/EBV）、自身免疫性肝炎、胆道梗阻、酒精与代谢性肝病","因果关系评估（RUCAM 量表）：≤2 分排除、3–5 分可能、6–8 分很可能、>8 分极可能","严重程度：1 级轻度（ALT 升高 <5×ULN 或 ALP <2×ULN）；2 级中度（≥2 项指标 >2×ULN 或 TBIL ≥2×ULN）；3 级重度（>5×ULN 或胆红素升高伴凝血障碍）；4 级急性肝衰竭；5 级致命"],"workup":["肝功能全套（ALT、AST、ALP、GGT、TBIL/DBIL、白蛋白）、INR、血常规、嗜酸性粒细胞","病毒学：HBsAg、抗-HCV/HCV RNA、抗-HAV IgM、抗-HEV IgM、CMV/EBV IgM","自身免疫指标：ANA、抗-LKM-1、抗-SMA、IgG、AMA（胆汁淤积型）","胆道影像（腹部超声/MRCP）排除梗阻；必要时肝活检（诊断不明或考虑自身免疫性肝炎）","详细用药史（含中药、保健品、剂量与时间），可用 LiverTox 数据库评估因果","停用可疑药物后 2–4 周复测肝功能评估恢复"],"grading":"按 R 值分型为肝细胞型、胆汁淤积型与混合型；按病程分为急性（<6 个月）与慢性（>6 个月）；按严重程度分 1–5 级（1 轻度、2 中度、3 重度、4 急性肝衰竭、5 致命）。慢性 DILI 定义为停药后 6 个月肝酶或胆红素仍异常。"},"ddx":[{"name":"慢性乙型肝炎（hbv）","point":"与本类 hbv 的鉴别点：DILI 需有可疑药物史且停药后肝酶下降；HBV 活动者 HBsAg 阳性 >6 个月、HBV DNA 高，无明确药物潜伏期。HBV 携带者可因药物诱发免疫清除导致急性发作，需同时查 HBV DNA。"},{"name":"自身免疫性肝炎（AIH）","point":"女性、ANA/抗-SMA 阳性、IgG 升高，肝活检见界面炎与玫瑰花结，激素治疗有效；DILI 亦可伴低滴度自身抗体，停药后多恢复。"},{"name":"急性病毒性肝炎（甲型/戊型）","point":"急性起病、伴发热、抗-HAV/HEV IgM 阳性，无药物暴露史或时间关系不匹配。"},{"name":"胆道梗阻（结石/肿瘤）","point":"ALP/GGT 显著升高、胆管扩张、TBIL 以直接胆红素为主，影像可定位梗阻。"},{"name":"酒精性肝病","point":"长期大量饮酒史，AST/ALT >2（AST 多 <300 U/L）、GGT 升高，戒酒后改善。"},{"name":"Budd-Chiari 综合征","point":"肝大、腹水、腹痛，影像见肝静脉/下腔静脉血栓，碱性磷酸酶升高，非药物相关。"}],"tx":{"drug":[{"name":"N-乙酰半胱氨酸（NAC）","dose":"对乙酰氨基酚中毒：口服 140 mg/kg 负荷后 70 mg/kg q4h 共 17 次；非对乙酰氨基酚所致肝衰竭：150 mg/kg 静脉（1 h）→ 50 mg/kg（4 h）→ 100 mg/kg（16 h）（部分中心）","note":"对乙酰氨基酚中毒特异性解毒剂；非对乙酰氨基酚急性肝衰竭早期使用可能获益，证据有限","renal":"无需调整","hepatic":"无特殊禁忌","interact":"与硝酸甘油合用可致低血压；与活性炭联用需间隔"},{"name":"异甘草酸镁","dose":"150 mg 静脉滴注 qd（可 200 mg），疗程 2–4 周","note":"国内常用抗炎保肝药，用于 ALT 显著升高的急性 DILI，可降低转氨酶","renal":"肾功能不全者减量","hepatic":"无特殊调整","interact":"与醛固酮拮抗剂合用可致低钾、水钠潴留"},{"name":"多烯磷脂酰胆碱","dose":"456 mg 口服 tid；或静脉 465 mg qd（遵说明书）","note":"修复肝细胞膜，用于胆汁淤积性或混合型 DILI","renal":"无需调整","hepatic":"无需调整","interact":"含苯甲醇，新生儿慎用"},{"name":"双环醇","dose":"25–50 mg 口服 tid","note":"国内常用降酶保肝药，用于轻中度肝细胞型 DILI","renal":"无需调整","hepatic":"重度肝病者慎用","interact":"与华法林合用可增强抗凝"},{"name":"熊去氧胆酸","dose":"10–15 mg/kg/d 口服，分 2–3 次（胆汁淤积型）","note":"用于胆汁淤积型 DILI，改善胆盐代谢","renal":"无需调整","hepatic":"胆道完全梗阻者禁用","interact":"与考来烯胺合用降低吸收；与环孢素合用影响其吸收"},{"name":"糖皮质激素","dose":"甲泼尼龙 0.5–1 mg/kg/d 口服（遵说明书，疗程个体化）","note":"仅用于药物超敏反应伴明显免疫介导（如DRESS）、或合并自身免疫性肝炎样表现；不常规使用","renal":"无需调整","hepatic":"重度肝衰竭者慎用","interact":"免疫抑制增加感染风险；活疫苗禁忌"}],"nonDrug":["立即停用可疑药物/保健品，是治疗的核心","重症（3 级以上）住院监测 INR、胆红素与脑病，警惕急性肝衰竭","急性肝衰竭：ICU 监护、病因治疗、评估肝移植（King's College 标准）","病因治疗（如对乙酰氨基酚中毒用 NAC），避免再次暴露","慢性 DILI：定期随访，慎用同类药物与其他潜在肝毒药物"],"life":["戒酒，避免多种药物叠加与中草药滥用","在病历中记录致敏药物，避免再次使用","恢复期每 2–4 周复查肝功能，直至正常","症状（乏力、黄疸、尿色加深）出现时立即复诊","保健品使用前咨询医生，有肝病史者更需谨慎"]},"prog":"多数 DILI 患者在停药后数周至数月内恢复，重型（Hy's law 阳性）约 10% 进展为肝衰竭；慢性 DILI 约 10%–15%。合并脂肪肝、老年人及多药合用时预后较差。","refs":["中华医学会肝病学分会药物性肝病学组《药物性肝损伤诊治指南（2015年版）》","中华医学会肝病学分会《药物性肝损伤诊治指南（2023年版）》","NIDDK LiverTox 数据库","EASL 药物性肝损伤临床实践指南（2019）"]},{"id":"hbv","name":"慢性乙型肝炎","aka":["CHB","chronic hepatitis B","慢乙肝"],"rank":2,"basic":{"define":"由乙型肝炎病毒（HBV）持续感染 ≥6 个月，HBsAg 持续阳性，伴肝脏炎症与纤维化的慢性进展性疾病，可发展为肝硬化与肝细胞癌（HCC）。","risk":["HBsAg 阳性母亲所生婴儿、围产期感染","血液接触、不洁注射、性传播","男性、年龄 >30 岁","长期大量饮酒、合并 HCV/HDV/脂肪肝","家族史中有 HBV 相关肝硬化或 HCC","免疫抑制治疗（激素、化疗、生物制剂）诱发再激活"],"epi":"我国一般人群 HBsAg 阳性率已从 9.75% 降至约 6%（约 7000 万–8000 万感染者），慢性乙肝患者约 2000 万–3000 万；HBV 相关 HCC 占我国 HCC 病因的 80% 以上。"},"patho":"HBV 感染肝细胞后，免疫清除阶段细胞毒性 T 细胞攻击表达 HBsAg 与 HBcAg 的肝细胞，形成反复的坏死-再生循环，促进纤维化与肝硬化；共价闭合环状 DNA（cccDNA）在肝细胞核内持续存在，难以彻底清除，是停药后复发的根源。HBV 基因组可整合入宿主 DNA，直接促进 HCC 发生（即使无肝硬化亦存在风险）。","dx":{"criteria":["HBsAg 阳性 ≥6 个月（或 HBsAg 阴性但抗-HBc 阳性伴 HBV DNA 阳性）","HBV DNA 可检测（实时荧光 PCR，检测下限通常 20 IU/mL）","HBeAg 阳性慢性感染（\"大三阳\"）或 HBeAg 阴性慢性感染（\"小三阳\"，前 C 区/核心启动子变异）","肝生物化学指标：ALT 持续升高（>ULN 至 2×ULN）或反复波动，否则需肝组织学评估","启动抗病毒治疗指征：① HBV DNA >2000 IU/mL 且 ALT > ULN（排除其他原因）；② 肝硬化（代偿或失代偿）；③ 有 HBV 相关肝硬化/HCC 家族史；④ 年龄 >30 岁且 DNA 阳性；⑤ 免疫抑制治疗或化疗前预防；⑥ 显著肝纤维化（≥F2）","抗病毒治疗目标：最大程度抑制 HBV DNA，ALT 复常，HBeAg 血清学转换，降低肝硬化与 HCC 风险"],"workup":["HBV 血清学五项（HBsAg、抗-HBs、HBeAg、抗-HBe、抗-HBc）；HBV DNA 定量","肝功能（ALT/AST/胆红素/白蛋白）、INR、血常规、甲胎蛋白","肝纤维化评估：FibroScan（肝硬度 <7.0 kPa 多无明显纤维化；≥12.5 kPa 提示肝硬化）、APRI、FIB-4；必要时肝活检","腹部超声（每 6 个月）与增强 CT/MRI（疑 HCC）；HCC 高危者每 6 个月 AFP + 超声","合并感染筛查：HCV、HDV、HIV；HBV 基因型与耐药检测（治疗失败者）","家族史评估与筛查家人（乙肝五项、HBV DNA）"],"grading":"自然史分四期：① HBeAg 阳性慢性感染（免疫耐受/肝炎轻微，DNA 高水平、ALT 正常）；② HBeAg 阳性慢性肝炎（免疫清除，DNA 高、ALT 升高）；③ HBeAg 阴性慢性感染（非活动性携带，DNA 低、ALT 正常）；④ HBeAg 阴性慢性肝炎（再活动，DNA 波动、ALT 升高）。纤维化按 Metavir 分期：F0–F4（F4 为肝硬化）。"},"ddx":[{"name":"药物性肝损伤（dili）","point":"与本类 dili 的鉴别点：DILI 需有明确药物暴露史，停药后恢复，HBsAg 可阴性；HBV 活动者有持续 HBsAg 阳性与 HBV DNA 高值。HBV 携带者使用免疫抑制药时可诱发再激活，需查 DNA 与预防性抗病毒。"},{"name":"丙型肝炎","point":"抗-HCV 与 HCV RNA 阳性，HBsAg 阴性；可合并 HBV 感染（重叠感染），需分别检测。"},{"name":"自身免疫性肝炎","point":"女性、ANA/抗-SMA 阳性、IgG 升高、肝活检界面炎；HBV 标志物阴性。"},{"name":"酒精性肝病","point":"AST/ALT >2、GGT 升高、MCV 增大，戒酒后改善，HBsAg 通常阴性。"},{"name":"非酒精性脂肪性肝病（NAFLD）","point":"超重/代谢综合征、超声见脂肪肝，ALT 轻度升高，HBsAg 阴性；可与 HBV 并存并加重肝病。"}],"tx":{"drug":[{"name":"恩替卡韦","dose":"0.5 mg qd 口服（空腹，餐前/后 2 h）；拉米夫定耐药者 1 mg qd","note":"高耐药屏障一线药物，长期治疗；勿随意停药（可致肝炎暴发）","renal":"CrCl 30–49 时 0.5 mg q48h；10–29 时 0.5 mg q72h；<10 或透析 0.5 mg q5–7 天（遵说明书）","hepatic":"无需调整","interact":"与环孢素、他克莫司合用可能升高血药浓度；避免与减毒活疫苗同用"},{"name":"富马酸替诺福韦二吡呋酯（TDF）","dose":"300 mg qd 口服（随餐）","note":"强效一线药物；长期使用注意肾小管损伤与骨密度下降","renal":"CrCl 30–49 时 300 mg q48h；10–29 时 q72–96h；<10 或透析遵说明书","hepatic":"无需调整","interact":"与阿德福韦、NSAIDs、氨基糖苷类合用增加肾毒性；与洛匹那韦/利托那韦增加 TDF 暴露"},{"name":"富马酸丙酚替诺福韦（TAF）","dose":"25 mg qd 口服（随餐）","note":"骨与肾毒性低于 TDF，优先用于老年或骨肾功能不全者","renal":"CrCl 15–29 时慎用，<15 或透析不推荐","hepatic":"重度肝功能不全（Child-Pugh C）慎用","interact":"与 P-gp 抑制剂（伊曲康唑）合用升高血药浓度；与利福平合用降低疗效"},{"name":"聚乙二醇干扰素 α（Peg-IFNα）","dose":"180 μg 皮下注射 每周一次，疗程 48 周（部分基因型 96 周）","note":"适用于年轻、HBeAg 阳性、DNA 中等、ALT 升高、无肝硬化优势人群，追求有限疗程与 HBsAg 清除；肝硬化失代偿禁用","renal":"CrCl 30–49 减量；<30 禁用","hepatic":"失代偿肝硬化禁用","interact":"与免疫抑制剂、细胞毒药物合用增加骨髓抑制"},{"name":"拉米夫定（不推荐单药）","dose":"100 mg qd 口服","note":"耐药率高（每年 15%–20%），仅用于特殊短期预防（如妊娠阻断），不推荐长期单药","renal":"CrCl <50 mL/min 减量","hepatic":"无需调整","interact":"与 TDF/ETV 联用时注意耐药叠加"},{"name":"乙肝免疫球蛋白（HBIG，围产期阻断）","dose":"新生儿出生后 12 h 内 100 IU 肌注（联合乙肝疫苗 10 μg 0、1、6 月）","note":"HBsAg 阳性母亲所生婴儿的标准阻断措施，联合疫苗阻断率 >95%","renal":"无需调整","hepatic":"无需调整","interact":"与活疫苗同用需间隔"}],"nonDrug":["长期抗病毒治疗（多数需终身），不可随意停药；停药标准严格限定（HBeAg 阳性者 DNA 检测不到、ALT 正常且 HBeAg 血清学转换后巩固 ≥1 年等）","代偿/失代偿肝硬化均需终身用药；失代偿者禁用干扰素","HCC 监测：每 6 个月腹部超声 + AFP（肝硬化、家族史、年龄 >30 岁男性等高风险者）","免疫抑制治疗（化疗、激素、抗 CD20）前预防性抗病毒（HBV DNA 阳性者均需；DNA 阴性但抗-HBc 阳性高危者亦需）","妊娠 24–28 周 HBV DNA >2×10⁵ IU/mL 者用 TDF 母婴阻断，产后可停药监测"],"life":["绝对戒酒，避免肝毒性药物与保健品","规律服药，依从性 >95%，不可漏服或自行停药","家庭成员筛查与接种乙肝疫苗","控制体重与代谢综合征（脂肪肝可加重病情）","每 3–6 个月复查 HBV DNA、肝功能与 AFP、超声"]},"prog":"未治疗的慢性乙肝 5 年内肝硬化发生率 8%–20%，肝硬化患者 5 年 HCC 风险 15%–20%。规范核苷（酸）类似物治疗可使肝硬化与 HCC 风险显著下降（约 50%–70%），但 HCC 风险不能完全消除，需终身监测。","refs":["中华医学会肝病学分会、中华医学会感染病学分会《慢性乙型肝炎防治指南（2022年版）》","中华医学会肝病学分会《原发性肝癌诊疗指南（2022年版）》","2023 EASL 乙型肝炎病毒感染管理临床实践指南","2022 AASLD 慢性乙型肝炎预防、诊断与治疗指南"]}]},{"id":"gut_upper","name":"上消化道与功能性肠病","rank":7,"summary":"症状-内镜-病理三线定位：反流与消化不良先排除器质病变（内镜、Hp），溃疡与胃炎围绕抑酸与根除 Hp，功能性胃肠病按罗马 IV 分型做症状导向治疗，以饮食与脑肠轴调节为长期基础。","compare":[{"diseaseId":"gi_gerd","dx":"典型烧心、反酸每周 ≥2 次并影响生活，PPI 试验有效，内镜可无黏膜破损（NERD）或见 LA 分级 A–D 级食管炎","key":"以反流症状 + PPI 应答为轴；有报警征象或 PPI 8 周无效时须内镜与 pH-阻抗监测"},{"diseaseId":"gi_pud","dx":"节律性上腹痛（DU 为空腹痛/夜间痛，GU 为餐后痛），内镜见 ≥0.5 cm 黏膜缺损，Hp 阳性或 NSAIDs 史","key":"内镜见明确溃疡灶且 GU 须活检排恶性；PPI 足疗程 + 根除 Hp + 停 NSAIDs"},{"diseaseId":"gi_fd","dx":"餐后饱胀、早饱、上腹痛或烧灼感 ≥6 个月、近 3 个月存在，内镜无器质性病变（含溃疡、肿瘤）","key":"功能性诊断：罗马 IV 症状 + 内镜阴性；无报警征象不做重复内镜，按 PDS/EPS 亚型选药"},{"diseaseId":"gi_ibs","dx":"腹痛近 3 个月每周 ≥1 天，伴排便相关或排便频率/性状改变，病程 ≥6 个月，无器质病变","key":"腹痛-排便关联 + Bristol 分型（IBS-C/D/M/U），红旗征阴性时按症状治疗"},{"diseaseId":"gi_gastritis","dx":"上腹隐痛、饱胀、嗳气，内镜见黏膜红白相间、以白为主、血管透见（萎缩），病理示慢性炎性细胞浸润与腺体萎缩","key":"与消化性溃疡的鉴别靠内镜见糜烂/溃疡而非单纯炎症；Hp 检测决定是否根除治疗"},{"diseaseId":"gi_hp","dx":"尿素呼气试验、粪便抗原或组织学/快速尿素酶试验阳性；血清抗体阳性仅提示既往或现症感染，不能判断根除","key":"现症感染与根除评估必须用呼气试验、粪便抗原或组织学，血清学不用于疗效判断"}],"diseases":[{"id":"gi_gerd","name":"胃食管反流病","aka":["GERD","Gastroesophageal reflux disease","反流性食管炎"],"rank":1,"basic":{"define":"胃十二指肠内容物反流至食管引起烧心、反酸等症状，或致食管黏膜损伤与并发症（狭窄、Barrett 食管）；分非糜烂性反流病（NERD）、反流性食管炎（RE）与 Barrett 食管。","risk":["肥胖与腹型肥胖","食管裂孔疝","高脂餐、浓咖啡、巧克力、酒精、吸烟","妊娠、腹压增高（便秘、束腰）","钙通道阻滞剂、硝酸酯、抗胆碱能药、茶碱","硬皮病等胃动力障碍"],"epi":"国内患病率约 2.5%–7.8% 并上升；RE 约占三分之一，Barrett 食管在反流人群中约 1%–2%。"},"patho":"下食管括约肌（LES）压力降低与一过性松弛（TLESR）增多为主因，合并食管裂孔疝时抗反流屏障失效。胃酸与胃蛋白酶（合并胆汁时更甚）损伤鳞状上皮致糜烂溃疡；食管清除力下降与胃排空延迟延长酸暴露。长期酸暴露致上皮肠化生（Barrett），可经异型增生进展为腺癌；内脏高敏感使部分 NERD 患者酸暴露正常仍出现症状。","dx":{"criteria":["典型烧心与反酸每周 ≥2 次且影响生活；或胸痛、嗳气、慢性咳嗽等不典型表现","PPI 试验：标准剂量 PPI 每日 1 次连用 2 周，症状明显缓解支持诊断（不能替代客观检查）","内镜可正常（NERD）或见黏膜破损，按洛杉矶（LA）分级评估","报警征象（吞咽困难、消瘦、贫血、呕血黑便、45 岁以上新发）须先内镜","难治性 GERD：双倍剂量 PPI 8 周症状不缓解，须 24 h pH-阻抗监测与食管测压"],"workup":["胃镜：评估食管炎分级、狭窄、Barrett（齿状线上移 ≥1 cm 并活检证实肠化），排除溃疡、肿瘤与嗜酸粒细胞性食管炎（活检嗜酸粒细胞 ≥15/HPF）","24 h 食管 pH-阻抗监测：酸暴露时间（AET）>6% 提示病理性反流，可识别弱酸/非酸反流，为难治性 GERD 关键检查","高分辨率食管测压：评估 LES 与蠕动，排除贲门失弛缓症（手术前必做）","胸痛为主者查心电图与冠脉评估；必要时胃排空检查"],"grading":"洛杉矶（LA）分级：A 级——黏膜破损长径 ≤5 mm；B 级——>5 mm 但未融合；C 级——融合且累及 <75% 周径；D 级——融合累及 ≥75% 周径。另分 NERD、RE、Barrett 食管。"},"ddx":[{"name":"功能性消化不良（gi_fd）","point":"与本类中 gi_fd 的鉴别点：FD 以餐后饱胀、早饱、上腹烧灼感为主且与进食量相关，烧心反酸非主导；PPI 8 周无效，pH-阻抗监测 AET 正常"},{"name":"消化性溃疡（gi_pud）","point":"GU 餐后上腹痛为主而非烧心，内镜见溃疡灶及周围水肿，须活检排恶性，Hp 常阳性"},{"name":"冠心病心绞痛","point":"压榨性胸骨后痛、与劳累相关、含服硝酸甘油缓解，发作时心电图 ST 改变；老年人不应把胸痛简单归因于反流"},{"name":"贲门失弛缓症","point":"进行性吞咽困难、反食、体重下降，测压示 LES 松弛障碍与蠕动缺失，钡餐示鸟嘴样狭窄"},{"name":"嗜酸粒细胞性食管炎","point":"青年男性、吞咽困难或食物嵌顿、过敏史，内镜见食管环与沟槽，活检嗜酸粒细胞 ≥15/HPF"}],"tx":{"drug":[{"name":"质子泵抑制剂（PPI）","dose":"标准剂量 qd 早餐前 30–60 min（奥美拉唑 20 mg、泮托拉唑 40 mg、雷贝拉唑 10 mg、艾司奥美拉唑 20 mg），疗程 8 周；C/D 级或症状未缓解可加倍/bid；有效后按需或最低剂量维持","note":"8 周愈合率 A/B 级 >90%、C/D 级 70%–80%；长期用药评估骨质疏松、低镁、维生素 B12 与艰难梭菌风险","renal":"多数无需调整，严重肾功能不全遵说明书","hepatic":"Child-Pugh C 减量或延长间隔，遵说明书","interact":"奥美拉唑/艾司奥美拉唑可能降低氯吡格雷活化，可换泮托拉唑或雷贝拉唑；影响华法林 INR 与甲氨蝶呤清除"},{"name":"钾离子竞争性酸阻滞剂（P-CAB）","dose":"伏诺拉生 20 mg qd，4–8 周；维持 10 mg qd（遵说明书）","note":"起效快、抑酸强、不受进餐影响，夜间酸突破少；适用于 PPI 反应不佳者","renal":"严格遵说明书，重度肾功能不全减量","hepatic":"肝功能不全慎用，遵说明书","interact":"经 CYP3A4 代谢，注意与强效抑制剂/诱导剂合用"},{"name":"促动力药","dose":"伊托必利 50 mg tid 餐前或莫沙必利 5 mg tid（遵说明书），4–8 周","note":"用于伴胃排空延迟、餐后饱胀明显者；不再使用西沙必利","renal":"伊托必利重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"避免与大环内酯类等延长 QT 药物合用；与抗胆碱药相互拮抗"},{"name":"海藻酸钠/抗酸剂","dose":"海藻酸钠-碳酸氢钠 10–20 mL 餐后与睡前；铝碳酸镁 1.0 g tid 餐后嚼服（遵说明书）","note":"形成「筏」屏障，用于餐后与夜间症状即时缓解，不替代 PPI 长期治疗","renal":"铝镁制剂肾功能不全者忌长期用","hepatic":"遵说明书","interact":"与喹诺酮、四环素、铁剂络合，间隔 1–2 h"},{"name":"巴氯芬（难治性补充）","dose":"5 mg tid，可增至 10–20 mg tid（遵说明书）","note":"抑制 TLESR，三线使用；镇静、头晕限制应用","renal":"经肾排泄，肾功能不全减量","hepatic":"遵说明书","interact":"与中枢抑制剂、阿片类合用加重镇静"}],"nonDrug":["腹腔镜 Nissen 胃底折叠术：PPI 依赖或不愿长期服药、客观证实病理性反流（AET >6% 或 RE）且食管动力正常者；术前必须测压与 pH 监测","经口无切口胃底折叠（TIF）适用于轻中度 GERD，长期疗效不及外科手术","大食管裂孔疝行疝修补+折叠术","Barrett 食管高级别异型增生：ESD 或射频消融 + 密集随访"],"life":["减重（BMI 下降 ≥3.5 kg/m² 可显著减少反流与酸暴露）","抬高床头 15–20 cm，睡前 3 h 不进食","戒烟限酒，减少个体触发食物；避免紧身衣物与增加腹压动作","长期 PPI 者每年复评；Barrett 无异性增生每 3–5 年内镜，低级别异型增生 6–12 个月复查"]},"prog":"多数患者 8 周 PPI 后缓解，复发率 50%–80%，常需按需或维持。Barrett 食管年癌变率约 0.1%–0.3%，合并异型增生者显著升高。难治性 GERD 与功能性烧心预后较差。","refs":["2020 年中国胃食管反流病专家共识","中国胃食管反流病多学科诊疗共识（2022）","2023 AGA Clinical Practice Guideline on GERD","内科学（第 9 版）第四篇 第三章 胃食管反流病","Lyon Consensus 2.0（2022，GERD 客观诊断）"]},{"id":"gi_gastritis","name":"慢性胃炎","aka":["Chronic gastritis","慢性萎缩性胃炎","CAG"],"rank":3,"basic":{"define":"不同病因所致胃黏膜慢性炎症，Hp 感染最常见；按病理分非萎缩性与萎缩性（含肠化、异型增生），按部位与自身抗体分 A 型（自身免疫、胃体为主）与 B 型（Hp 相关、胃窦为主）。","risk":["幽门螺杆菌感染（70%–80%）","高盐、腌制、烟熏饮食，蔬果不足","长期 NSAIDs、阿司匹林、PPI","胆汁反流、大量饮酒、吸烟","自身免疫与恶性贫血家族史","年龄增长与胃癌家族史"],"epi":"Hp 阳性者几乎均存在慢性活动性胃炎；萎缩性胃炎在 >50 岁人群约 20%–30%，自身免疫性 A 型胃炎约占 5%，女性多见。"},"patho":"Hp 定植胃窦表层，尿素酶产氨中和胃酸，VacA/CagA 直接损伤上皮并诱导 Th1/Th17 炎症，长期致腺体减少与纤维化，形成 Correa 级联（非萎缩性胃炎→萎缩→肠化→异型增生→胃癌）。A 型胃炎由 CD4+T 细胞破坏壁细胞，累及胃体胃底，致胃酸缺乏、内因子缺乏（维生素 B12 吸收障碍与恶性贫血）、高胃泌素血症，可伴增生性息肉与神经内分泌肿瘤。","dx":{"criteria":["症状不特异：上腹隐痛、腹胀、餐后饱胀、嗳气；A 型可有乏力、贫血、舌炎与周围神经病变","金标准为胃镜+黏膜活检病理；活检取胃窦 2 + 胃体 2 块（新悉尼系统），萎缩/肠化部位取材","萎缩表现：黏膜红白相间以白为主、血管透见、皱襞变平；病理示固有腺体减少","A 型胃炎：PGA/PGC 降低（PGR <3）、胃泌素-17 升高（胃体萎缩 >100 pmol/L）、抗壁细胞抗体（PCA）/抗内因子抗体（IFA）阳性、维生素 B12 降低","B 型胃炎：胃窦为主，Hp 检测阳性"],"workup":["胃镜+多点活检（≥5 块：胃窦 2 + 胃体 2 + 角 1），病理须写明萎缩、肠化、异型增生程度与 Hp 状态","Hp 检测：UBT、组织学或快速尿素酶；停 PPI 2 周、抗生素与铋剂 4 周后检测","血清学：胃蛋白酶原Ⅰ/Ⅱ与 PGR、胃泌素-17、PCA、IFA、维生素 B12、叶酸、铁蛋白","血常规（大细胞性贫血）、铁代谢；甲状腺抗体筛查自身免疫合并症","高风险者精查内镜（放大+染色内镜）靶向活检，行 OLGA/OLGIM 分期"],"grading":"按部位 A 型（胃体为主、自身免疫）/B 型（胃窦为主、Hp 相关）；按病理非萎缩性、萎缩性（轻/中/重度或 OLGA Ⅰ–Ⅳ 期）、肠化（OLGIM 分期）、异型增生（低/高级别）。"},"ddx":[{"name":"功能性消化不良（gi_fd）","point":"与本类中 gi_fd 的鉴别点：FD 内镜与活检无萎缩、肠化等器质改变；萎缩性胃炎以病理为准，症状与萎缩程度常不平行，二者可并存"},{"name":"胃溃疡与胃癌","point":"早期胃癌常于萎缩随访中经精查内镜发现；溃疡型病变边缘不规则、黏膜中断须多点活检"},{"name":"巨幼细胞性贫血","point":"A 型胃炎合并内因子缺乏可致大细胞贫血伴神经症状，需与叶酸缺乏、骨髓疾病鉴别，维生素 B12 与 IFA 有助定位"},{"name":"慢性胆囊炎/胆石症","point":"腹痛与油腻饮食相关、放射至右肩背，Murphy 征阳性，超声见胆囊壁增厚或结石；胃镜无显著病变"}],"tx":{"drug":[{"name":"根除 Hp 方案","dose":"参照「幽门螺杆菌感染」条目，铋剂四联 14 天；根除后 4–8 周 UBT 复查","note":"根除可减轻炎症、延缓萎缩，对已形成的肠化逆转有限","renal":"遵说明书","hepatic":"遵说明书","interact":"同根除方案"},{"name":"抑酸与黏膜保护","dose":"有烧心/上腹痛者 PPI 标准剂量 qd 4–8 周；瑞巴派特 0.1 g tid 或硫糖铝 1.0 g qid（遵说明书）","note":"黏膜保护剂对改善炎症与症状有辅助作用；萎缩性胃炎不宜长期滥用 PPI","renal":"铝镁制剂肾功能不全慎用","hepatic":"遵说明书","interact":"硫糖铝与四环素、喹诺酮络合，间隔 2 h"},{"name":"维生素 B12 替代（A 型）","dose":"氰钴胺 1000 μg 肌注 qd 或隔日连用 1–2 周，后每周 1 次至症状改善，再 1000 μg 每月 1 次维持；口服甲钴胺 500 μg tid 用于轻度缺乏","note":"同时评估铁、叶酸缺乏；重度贫血先纠正","renal":"遵说明书","hepatic":"遵说明书","interact":"大剂量维生素 C 可破坏 B12"},{"name":"促动力药","dose":"莫沙必利 5 mg tid 或伊托必利 50 mg tid 餐前 2–4 周（遵说明书）","note":"用于伴早饱、餐后饱胀或胆汁反流者","renal":"伊托必利重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"避免与延长 QT 药物同用"}],"nonDrug":["随访：中重度肠化或 OLGA/OLGIM Ⅲ–Ⅳ 期每 1–2 年精查内镜；轻度萎缩/肠化每 2–3 年；普通萎缩可 3 年复查","低级别异型增生：6–12 个月复查活检，局限病灶行 ESD","高级别异型增生：按早癌处理，ESD/EMR 或手术，术后 3–6 个月复查","A 型胃炎每年监测维生素 B12、血常规与铁蛋白；胃底神经内分泌肿瘤或 >1 cm 息肉内镜切除","筛查甲状腺病、1 型糖尿病等自身免疫合并症"],"life":["根除后分餐制、公筷防再感染","减少高盐腌制烟熏与霉变食物，增加新鲜蔬果","戒烟限酒，避免长期滥用 NSAIDs 与 PPI","胃癌家族史或高发区人群定期胃镜筛查"]},"prog":"Hp 根除后黏膜炎症多在 1 年内消退；萎缩与肠化部分可逆转但风险仍高，须按范围分层随访。A 型胃炎需终身 B12 替代，胃底神经内分泌肿瘤发生率约 5%。高级别异型增生年癌变率高，必须内镜干预。","refs":["中国慢性胃炎共识意见（2017 年，上海）","中国慢性胃炎诊疗指南（2022 年，北京）","第六次全国幽门螺杆菌感染处理共识报告（2022）","内科学（第 9 版）第四篇 第二章 慢性胃炎"]},{"id":"gi_hp","name":"幽门螺杆菌感染","aka":["Hp 感染","Helicobacter pylori infection","幽门螺杆菌"],"rank":2,"basic":{"define":"幽门螺杆菌定植胃黏膜引起的慢性感染，是慢性胃炎、消化性溃疡、胃 MALT 淋巴瘤与胃癌的明确致病因素，被 WHO 列为Ⅰ类致癌因子。","risk":["家庭内共餐与共用餐具（口-口/粪-口传播）","卫生条件差、饮用水污染","高感染率地区居住","消化性溃疡或胃癌家族史","免疫抑制"],"epi":"我国成人感染率约 40%–50%，儿童约 20%–30%；感染者约 15%–20% 发生消化性溃疡，1%–3% 发生胃癌。"},"patho":"Hp 靠鞭毛穿过黏液层、尿素酶产氨缓冲胃酸定植于胃小凹；CagA 经Ⅳ型分泌系统注入上皮细胞干扰增殖与促炎，VacA 形成膜孔致上皮空泡样变。Hp 激活中性粒细胞与 IL-8 致慢性活动性炎症，破坏黏液-碳酸氢盐屏障；胃窦感染致高胃泌素血症与胃酸增多，促十二指肠球部胃化生与溃疡。长期推进 Correa 级联致癌。","dx":{"criteria":["检测适应证：消化性溃疡、胃 MALT 淋巴瘤、慢性胃炎伴消化不良或黏膜萎缩/糜烂、早期胃癌内镜治疗后、长期 PPI/NSAIDs/阿司匹林者、缺铁性贫血与 ITP 原因不明者、胃癌家族史者","13C/14C 尿素呼气试验：敏感度与特异度均 >95%，首选非侵入检查；停 PPI 2 周、抗生素与铋剂 4 周后检测","侵入性检查：胃镜快速尿素酶试验、组织学（Warthin-Starry/Giemsa）、培养（药敏所需）","粪便抗原试验：敏感度与特异度 >90%，适用于儿童","血清抗体仅提示既往/现症感染，不能用于疗效判断","根除后复查：治疗结束 ≥4 周行 UBT 或粪便抗原"],"workup":["首选尿素呼气试验（13C 无放射性可用于儿童与孕妇）","拟行内镜者完成胃镜+活检+病理，同时评估萎缩与肿瘤；有条件行 Hp 培养与药敏或克拉霉素耐药基因检测","确认青霉素过敏史，必要时皮试；询问既往大环内酯与喹诺酮用药史（耐药风险）","复查不能用抗体；复查前同样停抗生素 4 周、PPI 2 周","同住家庭成员同期检测与治疗"],"grading":"无统一分级。按耐药：敏感、克拉霉素耐药（国内约 20%–50%）、左氧氟沙星耐药、双重耐药；按治疗史：初治、补救（首次失败）、多次失败（难治）。"},"ddx":[{"name":"慢性胃炎（gi_gastritis）","point":"与本类中 gi_gastritis 的鉴别点：慢性胃炎是病理诊断，Hp 感染是病因诊断，两者常并存，须靠 Hp 检测确认而非临床症状"},{"name":"功能性消化不良","point":"FD 为非 Hp 相关功能诊断；Hp 阳性 FD 根除后约 10%–15% 症状改善，应先根除"},{"name":"PPI/铋剂导致的检测假阴性","point":"抑酸药与铋剂抑制 Hp 活性致 UBT 与组织学假阴性，必须规范停药后复测，高度怀疑者改用粪便抗原或组织学复核"},{"name":"胃泌素瘤","point":"多发溃疡（可累及远端空肠）伴腹泻、胃泌素显著升高（>1000 pg/mL），与 Hp 阴性溃疡鉴别"}],"tx":{"drug":[{"name":"铋剂四联（PPI + 铋剂 + 2 种抗生素，14 天）","dose":"PPI 标准剂量 bid（奥美拉唑 20 mg、泮托拉唑 40 mg、雷贝拉唑 10 mg、艾司奥美拉唑 20 mg）+ 枸橼酸铋钾 220 mg bid 或胶体果胶铋 200 mg bid（餐前）+ 阿莫西林 1000 mg bid + 克拉霉素 500 mg bid（或呋喃唑酮 100 mg bid、甲硝唑 400 mg bid、四环素 500 mg qid、左氧氟沙星 500 mg qd），抗生素饭后服，共 14 天","note":"首选阿莫西林+克拉霉素或阿莫西林+呋喃唑酮；克拉霉素耐药 >15% 地区不用阿莫西林-克拉霉素；青霉素过敏以四环素+甲硝唑替代；不推荐 7–10 天短疗程","renal":"铋剂与呋喃唑酮肾功能不全慎用/禁用；四环素、甲硝唑肾功能不全减量","hepatic":"重度肝功能不全者铋剂、甲硝唑、克拉霉素慎用","interact":"克拉霉素抑制 CYP3A4 显著升高他汀暴露（横纹肌溶解），须停辛伐他汀/洛伐他汀或减量；亦升高他克莫司、华法林、地高辛浓度；铋剂与四环素错开服；甲硝唑与酒精间隔 72 h 以上"},{"name":"青霉素过敏方案","dose":"PPI + 铋剂 + 四环素 500 mg qid + 甲硝唑 400 mg tid（或呋喃唑酮 100 mg bid），14 天","note":"避免阿莫西林；克拉霉素耐药高发区慎用克拉霉素组合","renal":"四环素与甲硝唑肾功能不全慎用","hepatic":"重度肝病慎用","interact":"四环素与钙铁镁铝络合，与抗酸剂间隔 2 h；甲硝唑禁酒"},{"name":"补救治疗（初治失败）","dose":"PPI + 铋剂 + 阿莫西林 1000 mg bid + 左氧氟沙星 500 mg qd（或呋喃唑酮 100 mg bid），14 天；既往用过左氧氟沙星者改四环素+呋喃唑酮","note":"补救前评估既往用药与耐药，有条件行培养药敏或耐药基因检测","renal":"左氧氟沙星肾功能不全减量","hepatic":"遵说明书","interact":"左氧氟沙星与铝镁抗酸剂、铁锌剂络合（间隔 2 h）；延长 QT，禁与胺碘酮合用"},{"name":"益生菌（辅助）","dose":"布拉氏酵母菌 250 mg bid 或双歧杆菌三联活菌，与抗生素间隔 2 h，贯穿 14 天（遵说明书）","note":"可减轻抗生素相关腹泻，不能替代抗生素，提高根除率证据不一致","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗生素错开服用"}],"nonDrug":["首次失败可行补救；连续 2 次失败建议 Hp 培养药敏指导；抗生素种类重复不超过 2 次","以家庭为单位同查同治，降低再感染与传播","高发区成人及高危人群行筛查与根除（胃癌一级预防）","Hp 相关溃疡根除后一般无需长期 PPI 维持（除非持续 NSAIDs 等危险因素）","胃 MALT 淋巴瘤 Hp 阳性者首选根除，之后再评估放化疗"],"life":["分餐制与公筷，餐具消毒，避免口对口喂食婴幼儿","戒烟限酒、规律饮食、减少高盐腌制食物","根除后首次复查阴性即判为成功；溃疡或胃癌高危者继续胃镜随访","避免自行长期服 PPI 干扰检测"]},"prog":"规范铋剂四联 14 天根除率约 85%–90%；国内克拉霉素、甲硝唑、左氧氟沙星耐药率高，耐药是失败主因。成人再感染率每年约 1%–3%。根除可降低胃癌风险约 30%–40%，溃疡复发率由 >60% 降至 <5%。","refs":["第六次全国幽门螺杆菌感染处理共识报告（2022 年，广州）","中国幽门螺杆菌根除与胃癌防控的专家共识意见（2019 年，上海）","Maastricht VI/Florence 共识（2022）","内科学（第 9 版）第四篇 第一章 总论"]},{"id":"gi_pud","name":"消化性溃疡（非出血）","aka":["Peptic ulcer disease","PUD","胃溃疡","十二指肠溃疡"],"rank":4,"basic":{"define":"胃酸与胃蛋白酶消化自身黏膜形成的黏膜缺损，以胃溃疡（GU）与十二指肠溃疡（DU）最常见；本条目指无活动性出血、穿孔等并发症的阶段。","risk":["幽门螺杆菌感染（约 70%）","长期 NSAIDs、阿司匹林、抗血小板药","吸烟、应激、饮酒","O 型血、男性","合并 COPD、慢性肾病、肝硬化、胃泌素瘤"],"epi":"国内患病率 >10%，男多于女，DU 与 GU 约 3:1。DU 高峰 20–50 岁，GU 多为中老年；Hp 根除普及后 NSAIDs 相关溃疡比例上升。"},"patho":"侵袭因素（胃酸、胃蛋白酶、Hp、胆汁、NSAIDs、酒精）与防御因素（黏液-碳酸氢盐屏障、黏膜血流与前列腺素、上皮修复）失衡。DU 多与 Hp 致胃酸分泌增加及球部胃化生有关；GU 以屏障削弱为主，多与 Hp、NSAIDs、胆汁反流相关。NSAIDs 抑制 COX-1 削弱前列腺素介导的黏膜保护。","dx":{"criteria":["节律性上腹痛：DU 空腹痛与夜间痛、进食缓解；GU 餐后 0.5–1 h 痛","胃镜为金标准：局限性黏膜缺损（通常 ≥0.5 cm，覆白苔、周围充血水肿）；GU 须多点活检（每处 ≥2 块）排恶性，8–12 周复查胃镜确认愈合","Hp 检测必做","NSAIDs/抗血小板用药史是关键线索","记录报警征象：体重下降、呕血黑便、吞咽困难、贫血"],"workup":["胃镜+活检（GU 必活检）","Hp 检测：呼气试验或组织学","血常规、大便隐血，必要时铁代谢","评估抗栓药物使用与消化道出血风险","疑胃泌素瘤测空腹胃泌素；疑恶性行超声内镜或增强 CT"],"grading":"按部位：食管、胃（Ⅰ 型胃角/小弯、Ⅱ 型胃体、Ⅲ 型幽门前、Ⅳ 型近贲门）、十二指肠（球部）、复合性溃疡；按大小：小 <1 cm、中 1–2 cm、大 >2 cm、巨大 >3 cm；出血时用 Forrest 分级。"},"ddx":[{"name":"功能性消化不良（gi_fd）","point":"与本类中 gi_fd 的鉴别点：FD 内镜阴性，无黏膜缺损；症状以餐后饱胀早饱为主，非典型节律性空腹痛"},{"name":"溃疡型胃癌","point":"边缘隆起不规则、皱襞中断、胃壁僵硬（超声内镜示肌层受累），活检见癌细胞；GU 治疗后 8–12 周必须复查胃镜"},{"name":"慢性胃炎","point":"弥漫性黏膜炎症而无局限性缺损；两者可并存，以胃镜下有无溃疡灶为界"},{"name":"出血性溃疡（ugib 大类 ugib_peptic）","point":"同一病理基础出现呕血、黑便即按上消化道出血住院处理，与普通非出血溃疡路径不同"}],"tx":{"drug":[{"name":"PPI 抑酸","dose":"DU 标准剂量 qd 4–6 周；GU 6–8 周（复杂或大溃疡 8–12 周）。奥美拉唑 20 mg、泮托拉唑 40 mg、雷贝拉唑 10–20 mg、艾司奥美拉唑 20–40 mg 早餐前","note":"GU 必须治疗后复查胃镜确认愈合；愈合缓慢者加倍剂量","renal":"遵说明书","hepatic":"严重肝功能不全减量","interact":"奥美拉唑/艾司奥美拉唑可能降低氯吡格雷活化；长期评估低镁与 B12"},{"name":"根除 Hp 方案","dose":"见「幽门螺杆菌感染」：铋剂四联 14 天，之后 PPI 续用至溃疡愈合疗程","note":"Hp 阳性 DU/GU 必须根除，根除后复发率显著下降","renal":"遵说明书","hepatic":"遵说明书","interact":"同根除方案"},{"name":"NSAIDs 溃疡预防","dose":"需长期 NSAIDs/抗血小板者：PPI 标准剂量 qd 持续（奥美拉唑 20 mg 或雷贝拉唑 10 mg qd）；高危者 bid","note":"高危（≥65 岁、既往溃疡、合用激素/抗凝、大剂量 NSAIDs）建议 PPI 或米索前列醇；Hp 阳性者先根除；选择性 COX-2 抑制剂增加心血管风险","renal":"肾功能不全者 NSAIDs 慎用","hepatic":"重度肝病慎用 NSAIDs","interact":"米索前列醇致腹泻，孕妇禁用"},{"name":"黏膜保护剂","dose":"瑞巴派特 0.1 g tid 或硫糖铝 1.0 g qid，4–8 周（遵说明书）","note":"辅助改善愈合质量，单用适合轻症或 PPI 禁忌者","renal":"铝制剂肾功能不全慎用","hepatic":"遵说明书","interact":"硫糖铝与喹诺酮、四环素、铁剂络合，间隔 2 h"}],"nonDrug":["停用或减少 NSAIDs，必须使用者选最低剂量并联合 PPI 或 COX-2 抑制剂","冠心病长期抗血小板者不应因溃疡擅自停阿司匹林，应加 PPI 保护并双评估","GU 治疗后必须复查胃镜","难治性溃疡（8–12 周不愈合）评估耐药 Hp、NSAIDs、胃泌素瘤与恶性","穿孔、梗阻按并发症行内镜或外科处理"],"life":["戒烟限酒，规律饮食，避免过饱与刺激性食物（个体化）","避免自行服用含 NSAIDs 的复方感冒药与止痛药","根除后 4–8 周复查 Hp；愈合后评估是否需维持治疗","既往溃疡或长期 NSAIDs 者定期随访"]},"prog":"Hp 根除后 1 年复发率 <5%，未根除者 >60%；规范 PPI 疗程可使 80%–95% 溃疡愈合。出血、穿孔、梗阻是主要致死原因；GU 癌变率 <1%，须复查排除。","refs":["消化性溃疡诊断与治疗规范（2019 年，中华医学会消化病学分会）","中国消化性溃疡诊治指南（2022）","ACG Clinical Guideline: Treatment of Peptic Ulcer Disease（2021）","内科学（第 9 版）第四篇 第四章 消化性溃疡"]},{"id":"gi_fd","name":"功能性消化不良","aka":["Functional dyspepsia","FD","非溃疡性消化不良"],"rank":5,"basic":{"define":"起源于胃十二指肠区域、排除器质性疾病的消化不良症状群（餐后饱胀、早饱、上腹痛或烧灼感），按罗马 IV 分餐后不适综合征（PDS）与上腹痛综合征（EPS）。","risk":["女性、青年至中年，焦虑抑郁","Hp 感染（部分亚型）","进食过快、高脂、暴饮暴食","肠道菌群失衡与感染后","十二指肠嗜酸粒细胞/肥大细胞浸润、黏膜屏障受损","生活压力与睡眠障碍"],"epi":"全球消化不良症状患病率约 20%，国内功能性消化不良约 18%–23%，女性略多。"},"patho":"脑肠轴功能紊乱：胃排空延迟与胃容受性舒张受损致餐后饱胀早饱；内脏高敏感使正常胃扩张即引起疼痛；十二指肠黏膜屏障损害伴低度炎症；自主神经紊乱与心理社会因素放大症状。多数患者胃酸分泌正常，但部分对酸敏感，PPI 可部分有效。","dx":{"criteria":["至少 1 项：餐后饱胀不适、早饱、上腹痛、上腹烧灼感","病程 ≥6 个月且近 3 个月症状持续","内镜等检查未发现可解释症状的器质病变（无溃疡、糜烂、肿瘤、明显萎缩、食管炎）","分型：PDS（餐后饱胀、早饱、进食量减少）；EPS（上腹痛、烧灼感，不因排便或餐后缓解）","报警症状（>45 岁新发、消瘦、贫血、吞咽困难、呕血黑便、持续呕吐）须内镜"],"workup":["胃镜（含活检）：排除溃疡、胃癌、嗜酸粒细胞性胃肠炎、乳糜泻","Hp 检测（呼气试验），阳性者根除","血常规、甲状腺功能、血糖；必要时 tTG-IgA","腹部超声/CT：排除胆胰疾病","难治性：胃排空检查、胃电图与心理评估"],"grading":"罗马 IV 分型 PDS 与 EPS（可重叠）；不按严重程度分级，治疗按分型选择。"},"ddx":[{"name":"胃食管反流病（gi_gerd）","point":"与本类中 gi_gerd 的鉴别点：GERD 以烧心反酸为主，PPI 后明显缓解，pH-阻抗阳性；FD 烧灼感多局限上腹、与进食量相关，抗酸反应欠佳"},{"name":"消化性溃疡","point":"内镜见明确溃疡灶，DU 为空腹痛/夜间痛；FD 内镜阴性"},{"name":"慢性胃炎与早期胃癌","point":"存在黏膜萎缩、肠化或肿瘤，胃镜与活检可区分；早期胃癌可仅表现为消化不良症状"},{"name":"乳糜泻与嗜酸粒细胞性胃肠炎","point":"乳糜泻 tTG-IgA 阳性、小肠绒毛萎缩；嗜酸粒细胞性胃肠炎伴外周血嗜酸粒细胞升高与活检浸润"},{"name":"胆胰疾病","point":"腹痛放射至背部、伴黄疸或淀粉酶升高，超声/CT、MRCP 可鉴别"}],"tx":{"drug":[{"name":"Hp 根除（阳性者）","dose":"铋剂四联 14 天（见 Hp 条目），根除后 4–8 周复查","note":"根除后约 10%–15% 患者症状明显改善，是低成本收益措施","renal":"遵说明书","hepatic":"遵说明书","interact":"见根除方案"},{"name":"PPI 抑酸","dose":"EPS 首选：标准剂量 PPI qd 4–8 周；无效加倍或换 P-CAB 伏诺拉生 20 mg qd 4 周","note":"对 EPS 优于 PDS；PDS 以餐后饱胀为主者加促动力更合适","renal":"遵说明书","hepatic":"严重肝功能不全减量","interact":"见 PPI 条目"},{"name":"促动力药","dose":"PDS：伊托必利 50 mg tid 餐前或莫沙必利 5 mg tid，4–8 周（遵说明书）","note":"改善胃排空与早饱，疗效中等","renal":"伊托必利重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"避免与延长 QT 药物合用"},{"name":"中枢作用药物（难治性）","dose":"阿米替林 10–25 mg 睡前或丙米嗪 10–25 mg 睡前；米氮平 15 mg qn；坦度螺酮 10 mg tid（遵说明书）","note":"对 PPI/促动力无效者证据中等；小剂量起始，老年慎用抗胆碱能副作用","renal":"三环类严重肾功能不全减量","hepatic":"肝功能不全减量","interact":"与 MAOIs、延长 QT 药物相互作用多，须核对"},{"name":"黏膜保护与益生菌（辅助）","dose":"瑞巴派特 0.1 g tid 或硫糖铝 1 g qid 4 周；双歧杆菌制剂（遵说明书）","note":"证据等级较低，可作辅助","renal":"铝剂肾功能不全慎用","hepatic":"遵说明书","interact":"益生菌与抗生素错开 2 h"}],"nonDrug":["按分型治疗：PDS 促动力/调节容受性，EPS 抑酸，重叠型联合","认知行为治疗、催眠疗法、正念减压对难治性 FD 有循证支持","无报警症状且既往内镜阴性者不主张重复内镜","中医中药与针灸可个体化选择","病情进展（消瘦、吞咽困难、贫血）须重新评估"],"life":["少量多餐、细嚼慢咽，避免过饱与高脂饮食","规律作息、适度运动，减少咖啡因与酒精","处理焦虑抑郁与睡眠障碍","记录症状-饮食日记识别触发因素","每 3–6 个月随访评估症状与用药调整"]},"prog":"慢性反复发作，症状长期波动，约 50% 患者 5 年内改善。治疗以生活质量为目标，无需终身用药，以按需治疗为主；出现报警征象须重新检查。","refs":["中国功能性消化不良专家共识意见（2017 年，上海）","功能性胃肠病罗马 IV 标准（2016）","中国功能性消化不良诊治指南（2022）","内科学（第 9 版）第四篇 第六章 功能性疾病"]},{"id":"gi_ibs","name":"肠易激综合征","aka":["Irritable bowel syndrome","IBS","肠易激综合征"],"rank":6,"basic":{"define":"以腹痛、排便习惯与粪便性状改变为特征的慢性功能性肠病，按罗马 IV 分腹泻型（IBS-D）、便秘型（IBS-C）、混合型（IBS-M）与不定型（IBS-U），须排除器质性病变。","risk":["青年女性，焦虑抑郁与躯体化","既往肠道感染（感染后 IBS 约 10%）","食物不耐受（乳糖、FODMAP）","肠道菌群失调、胆汁酸代谢异常","生活压力与睡眠障碍","家族史与早期生活应激"],"epi":"全球患病率 5%–10%，我国约 2%–5%（罗马 IV），女性约为男性 2 倍，以腹泻型为主。"},"patho":"脑肠轴双向调节异常：腹泻型小肠转运加速、便秘型减慢；内脏高敏感（结肠扩张阈值下降，与肥大细胞活化、5-HT 信号增强相关）；肠道屏障通透性增加致低度免疫激活；菌群失衡（产甲烷菌、SIBO）与短链脂肪酸改变；中枢情绪-内脏调节失衡。感染后 IBS 与黏膜神经重塑、迷走神经改变有关。","dx":{"criteria":["罗马 IV：反复腹痛近 3 个月平均每周 ≥1 天，且满足 ≥2 项：①与排便相关；②伴排便频率改变；③伴粪便性状改变","症状出现 ≥6 个月且近 3 个月满足标准","分型（Bristol 粪便量表）：IBS-C 硬便 ≥25% 且稀便 <25%；IBS-D 稀便 ≥25% 且硬便 <25%；IBS-M 两者均 ≥25%；IBS-U 均不足 25%","红旗征象须排除器质病：>50 岁新发、贫血或便隐血阳性、消瘦、夜间症状、直肠出血、腹部肿块、IBD 或结直肠癌家族史","无报警征象且符合标准者可不必常规内镜"],"workup":["血常规、CRP、便常规+隐血；粪便钙卫蛋白（IBS 通常正常，升高提示 IBD）","乳糜泻血清学（tTG-IgA）、甲状腺功能","结肠镜：有报警征象或 >45–50 岁推荐；年轻典型症状者可选择性进行","乳糖与 SIBO 呼气试验；粪弹力蛋白酶排除胰腺外分泌不足","心理评估（SAS/SDS、PHQ-9）与 GI 症状量表"],"grading":"罗马 IV 分型 IBS-C、IBS-D、IBS-M、IBS-U（按 Bristol 比例）；部分共识按症状对生活质量的影响分轻/中/重度，用于治疗强度选择。"},"ddx":[{"name":"功能性消化不良（gi_fd）","point":"与本类中 gi_fd 的鉴别点：FD 症状在上腹（餐后饱胀、早饱），与排便无明确关系；IBS 以腹痛与排便频率/性状关联为核心，多在下腹"},{"name":"炎症性肠病","point":"便血或黏液脓血便、消瘦、夜间症状，CRP 与钙卫蛋白升高，结肠镜见连续性糜烂/溃疡"},{"name":"乳糖不耐受","point":"摄入乳制品后腹泻腹胀，乳糖呼气试验阳性，避乳糖后症状消失；常与 IBS 重叠"},{"name":"小肠细菌过度生长（SIBO）","point":"腹胀明显、呼气试验阳性，抗生素后改善"},{"name":"结直肠肿瘤与甲亢","point":"便血、贫血、消瘦或排便习惯进行性改变提示肿瘤；甲亢可致腹泻与体重下降，查甲功"}],"tx":{"drug":[{"name":"解痉剂（腹痛为主）","dose":"匹维溴铵 50 mg tid 餐时或奥替溴铵 40 mg tid，2–4 周；曲美布汀 0.1–0.2 g tid（遵说明书）","note":"缓解腹痛与痉挛，为短期对症，需评估疗效","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗胆碱药或钙通道阻滞剂合用可增强作用"},{"name":"益生菌","dose":"布拉氏酵母菌 250 mg bid 或双歧杆菌复方制剂，4–8 周（遵说明书）","note":"改善腹胀与整体症状，菌株疗效差异大，非治愈手段","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗生素错开 2 h；免疫抑制者慎用活菌"},{"name":"利福昔明（IBS-D）","dose":"550 mg tid 或 1200–1600 mg/d 分次，14 天（国内剂型遵说明书）；复发可重复疗程","note":"调节肠道菌群，减少腹胀腹泻；重复疗程效果维持较短，注意肝毒性","renal":"eGFR <30 慎用","hepatic":"肝功能不全慎用并监测","interact":"与 P-糖蛋白底物（地高辛）相互作用"},{"name":"止泻与通便（按型）","dose":"IBS-D：洛哌丁胺 首剂 4 mg 后按需 2 mg，日 ≤16 mg；IBS-C：聚乙二醇 17–34 g qd 或乳果糖 15–30 mL qd，或普芦卡必利 2 mg qd（遵说明书）","note":"洛哌丁胺仅用于急性症状控制，长期致便秘腹胀；IBS-C 优先渗透性泻剂","renal":"聚乙二醇大剂量肾功能不全慎用","hepatic":"遵说明书","interact":"洛哌丁胺与强 CYP3A4 抑制剂合用增加中枢抑制风险"},{"name":"中枢调节与心理药物（难治性）","dose":"阿米替林 10–25 mg 睡前（IBS-D）；氟西汀 20 mg qd 或帕罗西汀 20 mg qd（伴抑郁焦虑），8–12 周起效","note":"三环类抗胆碱能副作用可加重便秘，IBS-C 慎用","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"三环类禁与 MAOIs 合用；SSRI 与 NSAIDs/曲坦类合用增加出血风险"}],"nonDrug":["低 FODMAP 饮食（排除 4–6 周后逐步引入，需营养师指导）；增加可溶性纤维（洋车前子 3–5 g/d）","认知行为疗法、肠道导向催眠与正念训练对难治性患者有效","IBS-C 伴排便障碍行生物反馈与盆底肌训练","避免不必要反复检查与手术","随访症状与生活质量，关注精神共病"],"life":["规律三餐，避免暴饮暴食与高脂高糖","记录症状-食物-情绪日记","有氧运动、改善睡眠与压力管理","向患者说明不会发展为肿瘤或 IBD，减轻焦虑","症状模式改变或报警征象时重新评估（必要时结肠镜）"]},"prog":"慢性复发性良性疾病，约 50% 患者 5 年内改善，部分可自限；不增加结直肠癌与 IBD 风险，但显著影响生活质量与医疗资源使用。","refs":["中国肠易激综合征诊疗共识意见（2016 年，上海）","中国肠易激综合征专家共识（2020）","功能性胃肠病罗马 IV 标准（2016）","ACG Clinical Guideline: Management of IBS（2021）"]}]},{"id":"liver_metabolic","name":"代谢与酒精性肝病及肝衰竭","rank":8,"summary":"先量化饮酒与代谢因素，再分层纤维化（FIB-4/FibroScan）；酒精性与代谢相关脂肪性肝病以减重与戒酒为唯一能改变病程的措施，出现凝血障碍、脑病与器官衰竭即按肝衰竭处理，尽早评估肝移植。","compare":[{"diseaseId":"gi_nafld","dx":"代谢综合征背景（肥胖、糖尿病、高血压、血脂异常），影像脂肪肝，ALT 轻中度升高，排除酒精与病毒等其他病因","key":"代谢相关影像学脂肪肝 + 排除其他病因；减重 5%–10% 是核心治疗，GLP-1RA 用于合并 MASH 纤维化者"},{"diseaseId":"gi_ald","dx":"长期大量饮酒（男 ≥40 g/d、女 ≥20 g/d 持续 5 年），AST/ALT >2、GGT 与 MCV 升高；Maddrey DF ≥32 为重症酒精性肝炎","key":"饮酒史量化 + AST/ALT >2；DF ≥32 或 MELD >20 才考虑激素，且须先排除活动性感染"},{"diseaseId":"gi_hepatic_failure","dx":"黄疸进行性加深 + PTA ≤40% 或 INR ≥1.5 + 肝性脑病，或慢性肝病基础上出现器官衰竭（ACLF）","key":"凝血（PTA/INR）与脑病是分类轴；病因治疗 + 器官支持 + 急诊肝移植评估，人工肝仅作桥接"}],"diseases":[{"id":"gi_nafld","name":"代谢相关脂肪性肝病","aka":["MASLD","MAFLD","NAFLD","非酒精性脂肪性肝病","脂肪肝"],"rank":1,"basic":{"define":"肝细胞内三酰甘油过度沉积（≥5% 肝细胞含脂滴）并与超重/肥胖、胰岛素抵抗、代谢综合征密切相关，排除酒精、病毒、药物等其他病因的疾病谱，从单纯脂肪肝到脂肪性肝炎（MASH）、纤维化、肝硬化与肝癌。2023 年国际共识以 MASLD 取代 NAFLD，国内指南采用 MAFLD/MASLD 概念。","risk":["超重/肥胖（BMI ≥25 kg/m²，腹型肥胖）","2 型糖尿病与胰岛素抵抗","高甘油三酯、低 HDL-C、高血压","高果糖饮食、含糖饮料与高热量饮食","久坐少动、睡眠不足与睡眠呼吸暂停","多囊卵巢综合征、甲减；他莫昔芬、激素、甲氨蝶呤"],"epi":"我国成人患病率约 25%–30%，为慢性肝病首位病因；肥胖与糖尿病人群分别约 60%–80% 与 50%–70%。MASH 占 20%–30%，纤维化 F2 以上者进展风险明显升高。"},"patho":"「多重打击」学说：胰岛素抵抗使脂肪动员增加，肝内脂肪生成与 VLDL 输出失衡致脂肪堆积；脂毒性物（二酰甘油、神经酰胺、游离胆固醇）引起内质网应激与线粒体障碍，激活 NLRP3 与 Kupffer 细胞，产生气球样变与炎症（MASH）；肝星状细胞活化形成纤维化；肠菌群失调与胆汁酸代谢改变参与进展。纤维化是预测肝硬化和死亡的最强指标。","dx":{"criteria":["影像证实脂肪变（B 超「明亮肝」、肝脾 CT 比值 <1、MRI-PDFF ≥5%）或活检脂肪变 ≥5%","合并 ≥1 项代谢异常：BMI ≥25 kg/m²、腰围增大、血糖/HbA1c/糖尿病、血压、血脂异常","排除酒精性（男 <30 g/d、女 <20 g/d）、病毒性（HBsAg、抗 HCV）、自身免疫性、药物性肝损伤与遗传代谢病","ALT/AST 轻中度升高（多 <5×ULN），AST/ALT <1，GGT 与铁蛋白可升","FIB-4 ≥1.3 提示需 FibroScan；LSM ≥8 kPa 提示显著纤维化，≥12 kPa 提示进展期纤维化/肝硬化","MASH 确诊需活检：气球样变 + 小叶炎症 + 脂肪变，NAS ≥4 分"],"workup":["腹部超声首选；CT（肝/脾比值）或 MRI-PDFF 定量；瞬时弹性成像（FibroScan）测 LSM 与 CAP","FibroScan 分层：LSM ≥8 kPa 考虑 F2 以上，12–15 kPa 提示 F3–F4；CAP ≥248 dB/m 提示脂肪变；腹水与肥胖影响准确性，必要时用 XL 探头","FIB-4、NFS、APRI；必要时 MRE","肝活检：无创结果不确定、疑其他病因或需判断 MASH 分级者","代谢评估：空腹血糖、HbA1c、血脂、腰围、BMI、甲功、睡眠呼吸监测","病因排查：HBV/HCV 标志物、自身抗体、免疫球蛋白、铁蛋白与转铁蛋白饱和度、铜蓝蛋白（青年）"],"grading":"病理：脂肪变 0–3、小叶炎症 0–3、气球样变 0–2（NAS 0–8）；纤维化 F0–F4（F1 窦周、F2 显著、F3 桥接、F4 肝硬化）。弹性成像按 LSM <8、8–12、>12 kPa 分层。"},"ddx":[{"name":"酒精性肝病（gi_ald）","point":"与本类中 gi_ald 的鉴别点：有明确超量饮酒史（男 ≥40 g/d、女 ≥20 g/d），AST/ALT >2、GGT 与 MCV 显著升高；MASLD 饮酒在安全范围且以代谢异常为背景"},{"name":"丙型病毒性肝炎（gi_hcv）","point":"抗 HCV 与 HCV RNA 阳性；病毒学指标是区分关键，MASLD 可合并病毒感染"},{"name":"自身免疫性肝病（gi_aih_pbc）","point":"女性、自身抗体（ANA/ASMA/AMA-M2）阳性、IgG 或 IgM 升高，ALP 显著升高（PBC）或界面性肝炎（AIH）"},{"name":"药物性肝损伤（dili）","point":"有他莫昔芬、胺碘酮、甲氨蝶呤、激素等用药史，停药后肝功能改善，RUCAM 评分支持"},{"name":"血色病与 Wilson 病","point":"血色病转铁蛋白饱和度 >45%、铁蛋白升高；Wilson 病青年、铜蓝蛋白降低、24 h 尿铜升高与 K-F 环"}],"tx":{"drug":[{"name":"生活方式干预（减重为核心）","dose":"目标 1 年内减重 7%–10%；每周 ≥150 min 中等强度有氧 + 2 次抗阻训练；热量减少 500–750 kcal/d，减少含糖饮料与果糖","note":"减重 ≥5% 改善脂肪变，≥7% 改善炎症，≥10% 部分逆转纤维化","renal":"遵说明书","hepatic":"遵说明书","interact":"无"},{"name":"GLP-1 受体激动剂","dose":"司美格鲁肽 0.25 mg 皮下 qw 起始，逐增至 0.5–1.0 mg qw（MASH 用 2.4 mg，遵说明书）；替尔泊肽按说明书递增","note":"2025 年 FDA 批准司美格鲁肽 2.4 mg 用于 MASH 合并 F2–F3 纤维化；可改善组织学与体重。妊娠、胰腺炎史、甲状腺髓样癌家族史者禁用","renal":"轻中度可用，eGFR <30 慎用","hepatic":"严重肝功能不全数据有限，慎用","interact":"延缓胃排空影响口服药吸收；与胰岛素/磺脲类合用增加低血糖"},{"name":"改善胰岛素抵抗与代谢共病","dose":"吡格列酮 15–30 mg qd（伴 T2DM 或胰岛素抵抗）；二甲双胍 0.5 g bid 起始维持 HbA1c <7%；恩格列净 10 mg qd 等 SGLT2i（遵说明书）","note":"吡格列酮对 MASH 组织学有中等证据，但体重增加与水肿限制使用；二甲双胍不改善组织学但仍是 T2DM 一线","renal":"二甲双胍 eGFR <30 禁用、30–45 减量；SGLT2i 阈值遵说明书","hepatic":"严重肝功能不全吡格列酮禁用、二甲双胍慎用","interact":"吡格列酮与胰岛素合用增加水肿与心衰风险；二甲双胍与含碘对比剂暂停"},{"name":"维生素 E（非糖尿病 MASH）","dose":"800 IU/d，疗程 2 年（遵说明书）","note":"PIVENS 试验示改善非糖尿病 MASH 组织学；长期有出血与前列腺癌风险，糖尿病与肝硬化不推荐常规使用","renal":"遵说明书","hepatic":"肝硬化慎用大剂量","interact":"与抗凝/抗血小板药合用增加出血"},{"name":"降脂与共病管理","dose":"阿托伐他汀 10–40 mg qn 等，按血脂目标；无肝硬化者不因转氨酶轻升而停用他汀，ALT >3×ULN 需评估","note":"心血管事件是 MASLD 首要死因，他汀对肝脏安全；失代偿肝硬化慎用","renal":"重度肾功能不全减量","hepatic":"失代偿肝硬化与急性肝损伤时停用","interact":"与克拉霉素、伊曲康唑、吉非贝齐合用增加肌病风险"}],"nonDrug":["代谢/减重手术：BMI ≥32.5 伴 MASH 或 BMI ≥27.5 伴 T2DM 且生活方式与药物无效者，可显著改善肝组织学","MASH 伴 F2 以上纤维化为药物干预与随访重点，必要时肝活检","肝硬化者每 6 个月超声 + AFP 筛查 HCC，并筛查食管胃静脉曲张","避免或减量致脂肪肝药物（他莫昔芬、激素、甲氨蝶呤）","单纯脂肪肝无需肝活检，但须每年评估代谢与纤维化"],"life":["控制体重、腰围、血糖、血压、血脂","戒酒，限制含糖饮料与高果糖饮食","每周 150–300 min 运动，减少久坐","保证睡眠 7–8 h，筛查与治疗睡眠呼吸暂停","每年复查肝功能、FibroScan 与代谢指标；肝硬化 6 个月一次"]},"prog":"单纯脂肪肝多稳定，随代谢恶化可进展为 MASH 与纤维化；F2 以上者年肝硬化率约 2%–3%，MASH 肝硬化年 HCC 率约 1%–2%。减重 >10% 部分纤维化可逆转。首要死因为心血管事件。","refs":["代谢相关（非酒精性）脂肪性肝病防治指南（2024 年版）","中国非酒精性脂肪性肝病诊疗指南（2018 年更新版）","AASLD Practice Guidance on NAFLD（2023）","EASL–EASD–EASO Clinical Practice Guidelines for MASLD（2024）","内科学（第 9 版）第四篇 第十七章 非酒精性脂肪性肝病"]},{"id":"gi_ald","name":"酒精性肝病","aka":["Alcoholic liver disease","ALD","酒精性肝炎","酒精性肝硬化"],"rank":2,"basic":{"define":"长期大量饮酒（男 ≥40 g/d、女 ≥20 g/d 持续 5 年，或近 2 周 ≥80 g/d）所致肝损伤，包括脂肪肝、酒精性肝炎、肝纤维化与肝硬化；重症酒精性肝炎（SAH）可致肝衰竭与死亡。","risk":["长期大量饮酒（剂量-时间依赖）","女性（同剂量风险更高）","肥胖与蛋白质-热量营养不良","合并乙型或丙型肝炎","ALDH2 基因缺陷（亚洲人群常见）","吸烟与对乙酰氨基酚使用"],"epi":"我国酒精性肝病占住院慢性肝病约 10%–20% 并上升。SAH 28 天病死率 30%–50%，Maddrey DF ≥32 者显著升高。"},"patho":"酒精经 ADH 代谢为乙醛，形成蛋白加合物并致脂质过氧化与线粒体损伤；CYP2E1 途径产生大量活性氧并升高 NADH/NAD+，抑制脂肪酸氧化、促进合成形成脂肪肝。酒精致肠道通透性增加、内毒素入肝，激活 Kupffer 细胞释放 TNF-α、IL-6，诱导中性粒细胞浸润（酒精性肝炎）；感染与全身炎症反应触发慢加急性肝衰竭。肝硬化期表现为纤维间隔与门脉高压。","dx":{"criteria":["慢性大量饮酒史，量化每日饮酒量与年限（AUDIT-C 问卷）","AST/ALT >2（多在 <2×ULN），GGT 显著升高，MCV 增大；AST 与 GGT 升高最敏感","影像见脂肪肝、肝体积改变或肝硬化形态；排除其他肝病（HBV/HCV、自身抗体、药物）","酒精性肝炎：近期大量饮酒，TBil >2×ULN，AST/ALT >1.5 且 <400 U/L，伴肝大与白细胞升高","重症判定：Maddrey 判别函数 DF = 4.6 ×（患者 PT 秒数 − 对照 PT 秒数）+ 总胆红素（mg/dL），DF ≥32 提示 28 天死亡风险高","MELD >20 或 Glasgow 酒精性肝炎评分 ≥9 亦提示高危"],"workup":["肝功能（TBil、AST、ALT、ALP、GGT、白蛋白）、凝血（PT、INR）、血常规（MCV、血小板）、血氨","腹部超声/CT/MRI：脂肪肝、肝硬化、门脉高压、腹水、HCC；必要时 FibroScan（失代偿期偏高）","病因排查：HBsAg、HBV DNA、抗 HCV、自身抗体、免疫球蛋白、铁蛋白、铜蓝蛋白；必要时肝活检","感染筛查：血培养、胸片、腹水细胞学、尿培养（SAH 入院 1 周内常新发感染）","营养评估、电解质（低镁、低磷）、胰酶；酒精使用障碍（DSM-5）与戒断风险评估"],"grading":"酒精性脂肪肝、酒精性肝炎（DF <32 或 ≥32）、酒精性肝硬化（代偿/失代偿）；严重度亦可用 MELD、GAHS、ABIC 分层。"},"ddx":[{"name":"代谢相关脂肪性肝病（gi_nafld）","point":"与本类中 gi_nafld 的鉴别点：ALD 有超量饮酒史，AST/ALT >2、GGT 与 MCV 升高、中性粒细胞增多更显著；MASLD 以代谢综合征为背景且 AST/ALT <1"},{"name":"病毒性肝炎急性加重（gi_hcv / liver 大类 hbv）","point":"HBsAg 或 HCV RNA 阳性、HBV DNA 高载，ALT 常显著升高，无明确大量饮酒"},{"name":"自身免疫性肝病（gi_aih_pbc）","point":"女性、IgG 升高、ANA/ASMA/AMA-M2 阳性，活检见界面性肝炎或胆管病变；AIH 急性发作可类似 SAH"},{"name":"药物性肝损伤（dili）","point":"对乙酰氨基酚、抗结核药或中成药等可疑用药，有量效关系与停药后好转"},{"name":"脓毒症与胆道梗阻","point":"发热、白细胞升高伴胆红素升高，或全身感染伴多器官受累；影像与感染灶定位可鉴别"}],"tx":{"drug":[{"name":"戒酒与酒精使用障碍治疗","dose":"纳曲酮 50 mg qd（肝损伤者 25 mg 或停用）；阿坎酸 666 mg tid；双硫仑 250 mg qd（ALT >3×ULN 或心衰禁用）；苯二氮䓬类短期控制戒断","note":"戒酒是全部治疗前提；药物辅助须在肝功能允许下使用并监测","renal":"阿坎酸 eGFR <30 禁用","hepatic":"纳曲酮 ALT >5×ULN 禁用；双硫仑肝功能障碍禁用","interact":"双硫仑与含酒精制剂禁用；纳曲酮拮抗阿片类（术前停用）"},{"name":"糖皮质激素（重症酒精性肝炎）","dose":"泼尼松龙 40 mg qd 口服或静脉，28 天方案；7 天时 Lille 评分 >0.45 可停用","note":"适应证：Maddrey DF ≥32 或 MELD >20，且无活动性感染、消化道出血、急性肾损伤；可短期降低 28 天病死率，对长期生存获益有限（STOPAH 等）。用药前必须排除感染并确认诊断","renal":"慎用，注意水钠潴留与血糖","hepatic":"失代偿肝硬化与严重感染者禁用","interact":"与 NSAIDs 合用增加消化道出血；与酮康唑、克拉霉素合用增加暴露"},{"name":"营养支持","dose":"35–40 kcal/kg + 蛋白质 1.2–1.5 g/(kg·d)（理想体重）；口服营养补充优先，必要时鼻胃管；维生素 B1 100 mg 静注或肌注，叶酸 5 mg qd，复合维生素 B、锌与镁","note":"营养不良是独立预后因素，不限制蛋白质；补充 B1 预防 Wernicke 脑病","renal":"肾衰竭时调整蛋白与电解质","hepatic":"遵说明书","interact":"无明显相互作用"},{"name":"其他药物（选择）","dose":"N-乙酰半胱氨酸（按 150/50/100 mg/kg 静滴方案，用于对乙酰氨基酚中毒或重症辅助）；S-腺苷甲硫氨酸 1 g/d；己酮可可碱 400 mg tid（证据有限）；不推荐抗 TNF-α 药物","note":"NAC 对非对乙酰氨基酚病因证据较弱，可作为辅助","renal":"遵说明书","hepatic":"遵说明书","interact":"NAC 与硝酸甘油合用可致严重低血压"},{"name":"并发症处理","dose":"腹水：螺内酯 100 mg qd（可至 400 mg）+ 呋塞米 40 mg（可至 160 mg）；SBP：头孢曲松 1–2 g qd；肝性脑病：乳果糖 15–30 mL bid–tid 调整至 2–3 次软便；曲张出血按门脉高压流程","note":"SAH 急性肾损伤常见，避免大剂量利尿；SBP 须早期经验性抗生素","renal":"按 eGFR 调整利尿剂与抗生素","hepatic":"遵说明书","interact":"螺内酯与 ACEI/ARB 合用增加高钾"}],"nonDrug":["戒酒是核心，住院期间管理戒断综合征，联合心理支持","早期肝移植评估：6 个月戒酒期并非绝对条件，部分中心对首次 SAH 且无其他选择者行早期移植","人工肝（MARS/血浆置换）作为移植前桥接短期改善生化","腹水、静脉曲张出血、肝性脑病按相应流程处理","筛查治疗感染；对乙酰氨基酚 >2 g/d 慎用"],"life":["完全戒酒是唯一能改变疾病轨迹的措施，明确告知继续饮酒的致死风险","全程营养支持，蛋白质不限制","戒烟、控重、纠正维生素缺乏","定期随访肝功能、MELD、营养与心理状态","合并 HBV/HCV 者抗病毒治疗"]},"prog":"脂肪肝戒酒 4–6 周可逆；酒精性肝炎继续饮酒者 5 年肝硬化率 >50%。SAH 28 天病死率 30%–50%，Lille 评分 >0.45 提示激素无效。失代偿酒精性肝硬化中位生存约 5 年，戒酒可延长。","refs":["酒精性肝病诊疗指南（2018 年更新版）","中国酒精性肝病诊疗指南（2022）","EASL Clinical Practice Guidelines: Management of alcohol-related liver disease（2018）","内科学（第 9 版）第四篇 第十八章 酒精性肝病"]},{"id":"gi_hepatic_failure","name":"肝衰竭","aka":["Liver failure","急性肝衰竭","慢加急性肝衰竭","ACLF","ALF"],"rank":3,"basic":{"define":"多种因素（病毒、药物、酒精、自身免疫）引起的严重肝损伤，致合成、解毒、代谢与生物转化功能严重障碍，表现为黄疸、凝血功能障碍、肝性脑病与腹水。按病程分急性（ALF）、亚急性（SALF）、慢加急性（ACLF）与慢性（CLF）肝衰竭。","risk":["HBV 激活（国内最常见）","药物/毒物：对乙酰氨基酚、抗结核药、中草药、毒鹅膏蕈","酒精与自身免疫性肝炎急性发作","感染、消化道出血诱发 ACLF","脓毒症、休克与缺血性肝炎","基础肝硬化与门脉高压"],"epi":"国内以 HBV 相关为主，药物性比例上升。未移植 ALF 病死率 50%–80%；ACLF 28 天病死率随分级由 15% 升至 >50%。"},"patho":"肝细胞大量坏死是核心：病毒/药物直接毒性 + 固有免疫（cGAS-STING、NLRP3）与适应性免疫造成广泛损伤，再生不足。肝脏清除功能衰竭使内毒素与炎性因子（TNF-α、IL-6）蓄积，氨代谢障碍致脑水肿与肝性脑病；凝血因子合成减少与纤溶失衡致出血（PTA <40%）；低白蛋白与重度黄疸；全身炎症反应、循环不稳定与肝肾综合征常见，最终多器官衰竭。","dx":{"criteria":["ALF：既往无肝硬化，26 周内出现：①极度乏力等严重消化道症状；②黄疸进行性加深（TBil >171 μmol/L 或日升 ≥17.1 μmol/L）；③PTA ≤40% 或 INR ≥1.5（维生素 K 不能纠正）；④肝性脑病（Ⅱ 度及以上）；⑤腹水","SALF：26 周内出现上述表现，病程 >2 周至 26 周","ACLF：慢性肝病（含代偿期肝硬化）基础上短期出现急性肝损伤、黄疸与凝血障碍，伴或不伴脑病、腹水，并出现 ≥1 个器官衰竭","APASL 标准：黄疸（TBil ≥5 mg/dL 或 85 μmol/L）+ INR ≥1.5 或 PTA <40%，伴 4 周内腹水/脑病；EASL-CLIF 以器官衰竭分级","鉴别病毒性肝炎急性发作（ALT 极高但 PTA >40%）"],"workup":["肝功能、凝血（PTA、INR、纤维蛋白原、D-二聚体）、血氨、乳酸、血糖、电解质、肾功能、血气","病毒标志物：HBV 全套与 HBV DNA、HAV/HEV（妊娠）、HCV、EBV/CMV、HSV","毒物/药物：对乙酰氨基酚浓度、抗结核药、中成药、毒蘑菇","自身抗体与 IgG（AIH）、甲功、血清铜/铜蓝蛋白（青年急性肝衰竭须排除 Wilson 病）","腹部超声与多普勒、CT/MRI：评估肝脏体积与肝硬化；有脑病者头部 CT 与颅内压监测","经颈静脉肝活检用于病因不明者；感染筛查与出血风险评估"],"grading":"按病因与病程分 ALF、SALF、ACLF、CLF；ACLF 按 EASL-CLIF 1–3 级（器官衰竭数目）；肝性脑病按 West-Haven 0–Ⅳ 度；预后用 MELD、MELD-Na、APACHE Ⅱ 与 KCH 标准。"},"ddx":[{"name":"酒精性肝炎（gi_ald）","point":"与本类中 gi_ald 的鉴别点：SAH 有大量饮酒史、AST/ALT >2、Maddrey DF ≥32；一旦 PTA <40% 并出现肝性脑病即属肝衰竭范畴，按肝衰竭管理"},{"name":"代谢相关脂肪性肝病进展期（gi_nafld）","point":"MASLD 肝硬化失代偿可诱发 ACLF，需识别脂肪肝背景与代谢综合征；感染、出血是常见诱因"},{"name":"丙型/乙型病毒性肝炎急性加重（gi_hcv / liver hbv）","point":"病毒复制指标阳性；HBV 再激活（免疫抑制剂或 DAA 后）可致急性肝衰竭"},{"name":"自身免疫性肝炎急性发作（gi_aih_pbc）","point":"高 IgG、ANA/ASMA 阳性，须及时激素治疗并评估肝移植，病理为界面性肝炎"},{"name":"脓毒症与缺血性肝炎","point":"血压/心输出量下降、乳酸升高、ALT 短暂大幅升高，以原发病处理为主"}],"tx":{"drug":[{"name":"病因治疗","dose":"HBV：恩替卡韦 0.5 mg qd、替诺福韦酯 300 mg qd 或丙酚替诺福韦 25 mg qd；药物性：立即停可疑药，对乙酰氨基酚中毒用 N-乙酰半胱氨酸（150/50/100 mg/kg 方案）；AIH：泼尼松（龙）40 mg qd；Wilson 病：青霉胺/曲恩汀与锌剂","note":"病因治疗最关键，转诊前尽早启动；HBV 口服药起效慢时可联合 HBIG","renal":"核苷类肾功能不全减量","hepatic":"遵说明书","interact":"替诺福韦与 NSAIDs、氨基糖苷类合用增加肾损伤"},{"name":"乳果糖与利福昔明（肝性脑病）","dose":"乳果糖 15–30 mL bid 口服或 300 mL 灌肠（急性期），调整至每日 2–3 次软便；利福昔明 550 mg bid 预防复发","note":"乳果糖为一线；脑病伴脑水肿须头部抬高 30°、控制液体、甘露醇/高渗盐水降颅压","renal":"过量致腹泻脱水，肾功能不全者注意","hepatic":"遵说明书","interact":"利福昔明与华法林、地高辛的 P-gp 相互作用"},{"name":"凝血与出血防治","dose":"血小板 <10–20×10⁹/L 或活动性出血时输注；PTA <40% 伴活动性出血输注新鲜冰冻血浆；纤维蛋白原 <1.5 g/L 输冷沉淀；维生素 K1 10 mg qd 连用 3 天","note":"不推荐仅凭 INR 异常预防性大量输血浆（容量负荷与 TACO）；操作前可按 TEG 指导补充","renal":"大量血浆输注增加肺水肿风险","hepatic":"遵说明书","interact":"无"},{"name":"抗感染","dose":"经验性头孢曲松 1–2 g qd 或哌拉西林-他唑巴坦 4.5 g q6–8h；确诊后按培养调整，SBP 疗程 5–7 天","note":"免疫功能低下，感染常为死亡诱因，须早期筛查与经验治疗","renal":"按 eGFR 调整，遵说明书","hepatic":"遵说明书","interact":"头孢曲松与含钙输液禁同瓶"},{"name":"脑水肿与器官支持","dose":"20% 甘露醇 0.5–1 g/kg q4–6h（脑疝征象）；3% 高渗盐水目标血钠 145–150 mmol/L；N-乙酰半胱氨酸按体重静脉给药（ALF 早期）；PPI 预防应激性溃疡；CRRT 处理 AKI 与高氨血症（遵说明书）","note":"颅内压升高多在Ⅳ度脑病时出现；MARS/血浆置换人工肝可短期改善生化与脑病，为移植争取时间","renal":"甘露醇少尿者慎用；CRRT 按需","hepatic":"遵说明书","interact":"与其他肾毒性药物慎用"}],"nonDrug":["肝移植是 ALF 与部分 ACLF 的唯一根治手段：参考 KCH 标准、MELD 与 CLIF-C，尽早评估并登记","人工肝（血浆置换、MARS、DPMAS）改善短期生化与脑病，不能替代移植","ICU 监护：脑病Ⅲ/Ⅳ度气管插管、血流动力学支持、CRRT、营养（30–35 kcal/kg，蛋白质 1.2–1.5 g/kg）","避免镇静剂（除外机械通气）、NSAIDs、氨基糖苷类与肝毒性药物；纠正低血糖、低钾、低镁","妊娠期急性脂肪肝须终止妊娠；Wilson 病急性肝衰竭须紧急移植"],"life":["长期随访肝功能、MELD、影像与病毒指标；肝硬化者 6 个月 HCC 筛查与胃镜筛查","绝对戒酒，避免肝毒性药物；HBV 者终身抗病毒","营养支持与肌少症防治","教育患者识别脑病（性格改变、嗜睡、扑翼样震颤）与消化道出血","移植后免疫抑制管理、感染与排斥监测"]},"prog":"ALF 未移植病死率 50%–80%，脑水肿与多器官衰竭为主要死因，及时移植生存率 70%–80%。ACLF 28 天病死率 1 级约 15%、2 级 30%–40%、3 级 >50%；存活者常遗留肝硬化需长期管理。","refs":["肝衰竭诊治指南（2022 年版，中华医学会感染病学分会与肝病学分会）","APASL ACLF 共识（2019）","EASL Clinical Practical Guidelines on acute（fulminant）liver failure（2017）","内科学（第 9 版）第四篇 第二十四章 肝衰竭"]}]},{"id":"liver_auto","name":"自身免疫性肝病与病毒性肝炎（丙型）","rank":9,"summary":"免疫标志物先定性：AIH 看 IgG 与 ANA/ASMA（肝细胞型），PBC 看 AMA-M2 与 ALP（胆汁淤积型），PSC 看 MRCP 胆管串珠样；丙肝则靠抗 HCV+RNA 确证，泛基因型 DAA 12 周可治愈。AIH 与 PBC 需长期用药并监测应答。","compare":[{"diseaseId":"gi_aih_pbc","dx":"AIH：女性、IgG 升高、ANA/ASMA 阳性、界面性肝炎；PBC：ALP 升高、AMA-M2 阳性、非化脓性小胆管炎","key":"生化模式定位：肝细胞型（AIH，IgG/ANA/ASMA）与胆汁淤积型（PBC，AMA-M2/ALP）"},{"diseaseId":"gi_hcv","dx":"抗 HCV 阳性并经 HCV RNA 定量确认，伴肝功能异常与纤维化评估","key":"抗 HCV 筛查 → HCV RNA 确证；泛基因型 DAA（索磷布韦/维帕他韦 12 周）SVR12 >95%"},{"diseaseId":"gi_nafld","dx":"MASLD：影像脂肪肝 + 代谢综合征；ALD：超量饮酒、AST/ALT >2、Maddrey DF 评估","key":"酒精与代谢因素可叠加于病毒性肝炎或自身免疫性肝病，须逐项量化排除后再定性"}],"diseases":[{"id":"gi_aih_pbc","name":"自身免疫性肝病（AIH/PBC/PSC）","aka":["Autoimmune liver disease","AIH","PBC","PSC","自身免疫性肝炎","原发性胆汁性胆管炎"],"rank":1,"basic":{"define":"自身免疫介导的一组慢性肝病：自身免疫性肝炎（AIH）以界面性肝炎与高球蛋白血症为特征；原发性胆汁性胆管炎（PBC）为非化脓性小胆管破坏致胆汁淤积；原发性硬化性胆管炎（PSC）为肝内外胆管纤维化狭窄。三者可重叠（AIH-PBC 重叠综合征）。","risk":["女性（AIH 与 PBC 占 80%–90%），PSC 男多于女","合并其他自身免疫病（甲状腺病、干燥综合征、类风湿）","PBC 一级亲属家族史","PSC 合并炎症性肠病（60%–80% 为溃疡性结肠炎）","药物诱发（他汀、米诺环素等）"],"epi":"PBC 患病率约 19–40/10 万，AIH 约 16–20/10 万，PSC 约 6–16/10 万。PBC 以 40–60 岁女性为主；AIH 呈青年与绝经后双峰。"},"patho":"AIH：HLA-DR3/DR4 限制的 CD4+T 细胞针对肝细胞自身抗原（SLA/LP、CYP2D6）激活，引发界面性肝炎伴浆细胞浸润。PBC：抗线粒体抗体（AMA-M2，针对丙酮酸脱氢酶复合体 E2）与自身反应性 T 细胞破坏小胆管，胆汁酸潴留致肝细胞损伤与纤维化。PSC：胆管周围「洋葱皮样」纤维化，常与 IBD 肠道免疫激活相关，进展为胆管狭窄、胆管癌与结直肠癌。","dx":{"criteria":["AIH 简化评分（IAIHG 2008，总分 8）：ANA/ASMA ≥1:40（1 分）或 ≥1:80（2 分）、抗-LKM-1/抗-SLA 阳性（2 分）；IgG >ULN（1 分）或 >1.1×ULN（2 分）；组织学符合（1 分）或典型界面性肝炎伴玫瑰花结（2 分）；排除病毒性肝炎（2 分）；≥6 分可能、≥7 分确诊","AIH 生化：ALT/AST 显著升高，ALP 正常或轻升，IgG 升高 1.5–2 倍，ANA/ASMA 阳性约 70%–80%","PBC 诊断：ALP/GGT 升高 ≥6 个月、AMA 或 AMA-M2 阳性（敏感性 90%–95%）、活检非化脓性破坏性小胆管炎，三者满足 2 项即可诊断","PBC 支持指标：ALP >1.5×ULN、IgM 升高；AMA 阴性者需活检或抗-Sp100/抗-gp210 支持","PSC：MRCP 示肝内外胆管多发狭窄与扩张（串珠样），排除继发原因（胆囊切除、反复胆管炎、缺血），常伴 IBD，AMA 阴性"],"workup":["肝功能（ALT、AST、ALP、GGT、胆红素）、IgG、IgM、IgA、蛋白电泳","自身抗体：ANA、ASMA、抗-LKM-1、抗-SLA/LP、AMA/AMA-M2、抗-Sp100、抗-gp210","病毒标志物：HAV/HBV/HCV、EBV/CMV，排除病毒性肝炎","肝活检：AIH 与重叠综合征诊断与分级（界面性肝炎、浆细胞浸润、玫瑰花结）；PBC 见非化脓性胆管破坏；PSC 见同心圆纤维化","腹部超声与 MRCP（PSC 首选）；PSC 行结肠镜筛查 IBD 与结直肠肿瘤","评估肝硬化与门脉高压（弹性成像、胃镜）；胆红素 >2×ULN 提示预后差"],"grading":"AIH 按简化评分 ≥6 分可能、≥7 分确诊；PBC 按 UDCA 应答（巴黎Ⅱ标准：ALP ≤1.5×ULN 且 AST ≤1.5×ULN 且胆红素正常）分应答/不应答；PSC 分大胆管型与小胆管型（仅活检异常）。"},"ddx":[{"name":"丙型病毒性肝炎（gi_hcv）","point":"与本类中 gi_hcv 的鉴别点：HCV RNA 阳性是确证依据；HCV 感染可引起自身抗体阳性与抗-HCV 假阳性，须以病毒核酸排除"},{"name":"酒精性肝病（gi_ald）","point":"AST/ALT >2、GGT 与 MCV 升高、有超量饮酒史，IgG 不显著升高，自身抗体多阴性"},{"name":"代谢相关脂肪性肝病（gi_nafld）","point":"影像脂肪肝与代谢综合征背景，ALP 多正常、AMA 阴性；可伴 ANA 低滴度但不伴 IgG 显著升高与界面性肝炎"},{"name":"药物性肝损伤（dili）","point":"有米诺环素、他汀、抗结核药或中成药史，停药后恢复；药物性 AIH 停药后可缓解"},{"name":"胆管癌与胆管结石","point":"MRCP/ERCP 见狭窄或充盈缺损、结石；PSC 年胆管癌风险 0.5%–1%，狭窄须刷检/活检排查"}],"tx":{"drug":[{"name":"熊去氧胆酸（UDCA，PBC 一线）","dose":"13–15 mg/(kg·d)，分次或睡前一次（如 250 mg tid）；治疗 1 年评估生化应答（巴黎Ⅱ标准）","note":"PBC 唯一一线药物，可改善生化与延缓纤维化；约 40% 应答不足，可加奥贝胆酸 5 mg qd（可至 10 mg，失代偿肝硬化禁用）","renal":"无症状性肾功能不全无需调整","hepatic":"失代偿肝硬化与胆道完全梗阻禁用；PSC 大剂量（28–30 mg/kg/d）不推荐","interact":"考来烯胺、铝碳酸镁降低吸收，间隔 2–4 h"},{"name":"糖皮质激素与硫唑嘌呤（AIH 一线）","dose":"泼尼松（龙）0.5–1 mg/(kg·d)（30–40 mg qd）；联合方案泼尼松 30 mg qd 2 周后减至 15–20 mg qd，加硫唑嘌呤 50 mg qd（可至 1–1.5 mg/kg/d）；维持 2–3 年，生化缓解后缓慢减量","note":"目标为生化（ALT/AST 与 IgG 正常）与组织学缓解；硫唑嘌呤前查 TPMT/NUDT15 基因，监测骨髓抑制与胰腺炎","renal":"肾功能不全硫唑嘌呤减量","hepatic":"失代偿肝硬化禁用硫唑嘌呤","interact":"硫唑嘌呤与别嘌醇/非布司他合用须减至 1/4；与华法林合用降低抗凝效果"},{"name":"PSC 与重叠综合征","dose":"PSC：UDCA 13–15 mg/(kg·d) 改善生化；优势性狭窄行内镜扩张；重叠综合征按 UDCA + 激素/硫唑嘌呤（AIH 方案）","note":"PSC 合并 IBD 按 IBD 治疗；早期胆管扩张并抗生素预防胆管炎","renal":"遵说明书","hepatic":"遵说明书","interact":"见 UDCA 与硫唑嘌呤条目"},{"name":"二线/难治方案","dose":"AIH：布地奈德 3 mg tid（无肝硬化）、吗替麦考酚酯 0.5–1 g bid 或他克莫司；PBC：奥贝胆酸、非诺贝特 145 mg qd（遵说明书）","note":"布地奈德肝硬化者禁用（门体分流致全身暴露）；MMF 与他克莫司需专科管理","renal":"MMF 肾功能不全慎用；他克莫司有肾毒性","hepatic":"布地奈德肝硬化禁用；MMF 监测肝损伤","interact":"他克莫司与红霉素、克霉唑等 CYP3A4 抑制剂合用显著升高浓度"},{"name":"症状与并发症","dose":"PBC 瘙痒：考来烯胺 4 g qid（与其他药间隔 2–4 h）、利福平 150–300 mg bid、纳曲酮 50 mg qd 或舍曲林 50–100 mg qd；骨质疏松补钙+维生素 D，必要时双膦酸盐；补充脂溶性维生素 A/D/E/K","note":"瘙痒严重影响生活质量；PBC 骨质流失常见，需 DXA 筛查","renal":"双膦酸盐肾功能不全慎用；考来烯胺与利尿剂合用可致低钾","hepatic":"利福平肝毒性，监测肝功能","interact":"考来烯胺与地高辛、华法林、甲状腺素、UDCA 络合，须错开"}],"nonDrug":["肝移植：AIH 急性重症/失代偿、PBC 与 PSC 终末期；移植后 PBC/AIH 可复发需监测","PSC：ERCP 或经皮扩张优势性狭窄、必要时支架；CA19-9 与影像筛查胆管癌，合并 IBD 每 1–2 年结肠镜","PBC 与 AIH 多需长期甚至终身用药，不可自行停药","AIH 治疗 2–3 年完全缓解后可尝试停药，但复发率 >50% 需密切随访","PBC 肝硬化者每 6 个月 HCC 筛查"],"life":["避免饮酒与肝毒性药物，慎用对乙酰氨基酚","补钙与维生素 D、负重运动防骨质疏松","规律复查肝功能、IgG、自身抗体与肝脏硬度","AIH 妊娠需孕前控制活动，泼尼松与硫唑嘌呤可孕期继续（专科评估）","PSC 合并 IBD 定期肠镜；PBC 筛查其他自身免疫病"]},"prog":"PBC 接受 UDCA 者 60%–70% 应答良好，10–15 年生存接近正常；AIH 规范治疗后 80% 以上生化缓解但停药易复发；PSC 平均生存 10–15 年，约 40% 需肝移植，胆管癌终身风险 10%–15%。","refs":["自身免疫性肝炎诊断和治疗指南（2021 年，中华医学会肝病学分会）","原发性胆汁性胆管炎诊疗指南（2021 年）","原发性硬化性胆管炎诊断和治疗指南（2021）","EASL Clinical Practice Guidelines on AIH（2019）与 PBC（2017）","内科学（第 9 版）第四篇 第十九章 自身免疫性肝病"]},{"id":"gi_hcv","name":"丙型病毒性肝炎","aka":["Hepatitis C","HCV","丙型肝炎","丙肝"],"rank":2,"basic":{"define":"丙型肝炎病毒（HCV，单股正链 RNA 病毒）感染引起的肝脏疾病，可为急性或慢性，是肝硬化与肝细胞癌的重要病因；全口服直接抗病毒药物（DAA）问世后治愈率 >95%。","risk":["不安全注射与输血史（共用注射器、纹身、穿耳）","血液透析与器官移植","母婴传播（约 5%，合并 HIV 更高）","性接触（男男性行为、多性伴）","医务人员职业暴露","HIV/HBV 合并感染"],"epi":"全球约 5000 万人慢性感染；我国抗 HCV 阳性率约 0.43%–0.6%，慢性化率 50%–85%。基因型 1 型约 60%，2 型约 20%–25%。"},"patho":"病毒经 CD81、SR-B1、CLDN1 等受体进入肝细胞并大量复制。急性感染 6 个月内约 15%–40% 自发清除，60%–85% 转为慢性；慢性感染引起反复的 CD8+T 细胞介导肝细胞坏死与炎症，驱动纤维化、肝硬化与 HCC。核心蛋白与 NS5A 致脂肪变与代谢紊乱；HCV 复制还与混合冷球蛋白血症、MPGN、B 细胞淋巴瘤相关。","dx":{"criteria":["抗 HCV 抗体筛查阳性提示既往或现症感染，须进一步检测 HCV RNA","HCV RNA 阳性为现症感染确证依据：治疗前定量（下限 15 IU/mL），治疗后 12 周复测 SVR12 确认治愈","ALT 可正常或升高，AST/ALT 多 <1（肝硬化时倒置）；GGT 可轻升","纤维化评估：FibroScan（LSM ≥12.5 kPa 提示肝硬化）、APRI、FIB-4；必要时活检","筛查肝外表现：冷球蛋白血症、MPGN、B 细胞淋巴瘤、糖尿病","难治或多次失败者检测基因型与 NS5A 耐药相关变异（如 Y93H）"],"workup":["抗-HCV 筛查（疑似者与高危人群）；HCV RNA 定量确证","肝功能、血常规、INR、血小板与白蛋白","FibroScan/LSM、FIB-4/APRI；腹部超声与 MRI 评估肝硬化与 HCC","治疗前筛查 HBV（HBsAg、HBV DNA，预防 DAA 后 HBV 再激活）、HIV、eGFR、妊娠状态与药物相互作用","基因型与抗 NS5A 耐药变异（既往 DAA 失败者）","尿蛋白、冷球蛋白、血糖与甲状腺功能"],"grading":"按病程：急性、慢性、肝硬化（代偿/失代偿）；按基因型 1–6 型（1a/1b）；纤维化 F0–F4；按治疗史：初治、PR 失败、DAA 失败。"},"ddx":[{"name":"自身免疫性肝病（gi_aih_pbc）","point":"与本类中 gi_aih_pbc 的鉴别点：ANA/ASMA 伴 IgG 升高（AIH）或 AMA 阳性（PBC），HCV RNA 阴性；HCV 可致自身抗体阳性与抗-HCV 假阳性，须以 RNA 排除"},{"name":"乙型病毒性肝炎（liver 大类 hbv）","point":"HBsAg 阳性、HBV DNA 可测，ALT 升高常伴病毒高载；两者可重叠感染"},{"name":"代谢相关脂肪性肝病（gi_nafld）","point":"影像脂肪肝、代谢综合征背景，病毒学阴性，ALT 轻升"},{"name":"酒精性肝病（gi_ald）","point":"超量饮酒史、AST/ALT >2、MCV 升高；HCV 感染者 AST/ALT 多 <1"},{"name":"其他病因肝硬化与 HCC","point":"须排除 HBV 合并感染、酒精、代谢因素；HCC 用 AFP 与增强影像（LI-RADS）诊断"}],"tx":{"drug":[{"name":"索磷布韦/维帕他韦（SOF/VEL）","dose":"400 mg/100 mg qd × 12 周；无肝硬化或代偿期肝硬化、基因型 1–6 通用；失代偿（Child-Pugh B/C）加用利巴韦林或延长至 24 周（遵说明书）","note":"国内已纳入医保，为泛基因型首选；初治与部分 PR 失败者 SVR12 >95%；治疗前必须筛查 HBV 防再激活","renal":"eGFR ≥30 无需调整；<30 慎用，遵说明书或改用格卡瑞韦/哌仑他韦","hepatic":"轻中度无需调整；失代偿肝硬化须评估蛋白结合与 P-gp 相互作用，遵说明书","interact":"禁与胺碘酮合用（严重心动过缓）；与 PPI 合用需限制剂量（奥美拉唑 ≤20 mg）；利福平、卡马西平、苯妥英、圣约翰草显著降低浓度；与洛伐他汀/辛伐他汀合用增加肌病"},{"name":"格卡瑞韦/哌仑他韦（GLE/PIB）","dose":"300 mg/120 mg（3 片）qd 随餐，8 周（无肝硬化初治）、12 周（肝硬化或 PR 失败）、16 周（DAA 失败）","note":"泛基因型短疗程；不推荐用于失代偿肝硬化（Child-Pugh B/C）","renal":"轻中度无需调整；重度未推荐","hepatic":"失代偿肝硬化禁用","interact":"与利福平、卡马西平等强效 P-gp/CYP3A4 诱导剂矛盾；他汀类须调整或避免；禁与胺碘酮合用"},{"name":"索磷布韦/达拉他韦（SOF/DCV）与索磷布韦/雷迪帕韦（SOF/LDV）","dose":"SOF/DCV 400 mg/60 mg qd 12 周（失代偿 24 周或加利巴韦林）；SOF/LDV 400 mg/90 mg qd 12 周（无肝硬化初治可 8 周），DAA 经验者 16 周或加 RBV","note":"LDV 方案须筛查 NS5A 耐药变异（Y93H）；基因型 1、2、4–6 适用","renal":"eGFR <30 慎用 SOF","hepatic":"失代偿加 RBV 或延长疗程；LDV 需酸性环境，避免与大剂量 PPI 合用","interact":"禁与胺碘酮、利福平、卡马西平、圣约翰草合用"},{"name":"利巴韦林（联合用）","dose":"按体重 800–1200 mg/d 分次，与 DAA 联用于失代偿或难治者，疗程按方案","note":"有致畸性，育龄男女用药期间及后 6 个月避孕；溶血性贫血为主要不良反应","renal":"eGFR <50 慎用或减量，遵说明书","hepatic":"失代偿慎用并监测溶血","interact":"与齐多夫定拮抗；与华法林（INR 升高）、他汀（肌病）慎用"},{"name":"疗效监测","dose":"治疗后 12 周 HCV RNA 低于检测下限（SVR12）即为治愈；治疗中与结束后复查 HCV RNA","note":"SVR12 后丙肝视为治愈；肝硬化者仍需每 6 个月 HCC 筛查与门脉高压管理","renal":"遵说明书","hepatic":"遵说明书","interact":"无"}],"nonDrug":["HCV RNA 阳性者均评估并治疗（国内指南推荐全人群治疗），不受纤维化程度限制","失代偿肝硬化与 DAA 应个体化；儿童（≥3 岁）按体重用儿童剂型","HBV 合并感染：DAA 前评估 HBV 复制状态，治疗中监测 HBV DNA 与 ALT，必要时抗 HBV 预防再激活","肝移植后 HCV 复发：可行 DAA 清除以减少移植后复发","肝硬化者 6 个月超声 + AFP 筛查 HCC，并按需胃镜筛查食管静脉曲张","高危人群集中筛查（注射药使用者、透析者、1993 年前献血者）"],"life":["治疗期间戒酒，避免叠加肝损伤","筛查治疗 HBV、HIV 与代谢病","联用利巴韦林的育龄女性须避孕","治愈后仍需肝病随访（肝硬化者终身随访）","注射/性传播防护，避免再感染"]},"prog":"慢性 HCV 感染者 20%–30% 在 20–30 年内进展为肝硬化，肝硬化者年 HCC 率 2%–4%。DAA 治疗 SVR12 >95%，治愈可显著降低肝病死亡与 HCC 风险，但肝硬化者仍需持续 HCC 监测；冷球蛋白血症等肝外表现常可缓解。","refs":["丙型肝炎防治指南（2022 年版，中华医学会肝病学分会）","直接抗病毒药物治疗丙型肝炎专家共识（2020）","WHO Guidelines for the care and treatment of chronic HCV infection（2022）","内科学（第 9 版）第四篇 第十三章 丙型病毒性肝炎"]}]},{"id":"intestine_other","name":"肠道其他疾病（肠结核、缺血性肠病、吸收不良）","rank":9,"summary":"三者的共同入口是腹痛、腹泻与消瘦：肠结核靠结核证据 + 回盲部溃疡与干酪样肉芽肿，须与克罗恩病区分并抗结核 6–9 个月；缺血性肠病按急性与慢性分流，急性以早期血管评估与肠镜为关键；吸收不良先以粪便脂肪定量与血清学（tTG-IgA）定性，再向小肠镜与无麸质饮食落地。","compare":[{"diseaseId":"gi_intestinal_tb","dx":"腹痛、腹泻、低热盗汗与消瘦，右下腹包块；结肠镜见回盲部环形溃疡伴干酪样肉芽肿，T-SPOT 或抗酸染色阳性","key":"结核证据（T-SPOT、病理干酪样肉芽肿、抗酸）+ 回盲部受累；抗结核治疗有效为回顾性佐证"},{"diseaseId":"gi_ischemic_bowel","dx":"急性者突发腹痛与便血，腹痛程度与体征不符，血乳酸与 D-二聚体升高；慢性者餐后腹痛、体重下降与血管闭塞证据","key":"动脉粥样硬化/房颤背景 + 与体征不符的剧烈腹痛；CTA 见肠系膜血管闭塞或狭窄"},{"diseaseId":"gi_malabsorption","dx":"慢性腹泻、脂肪泻、消瘦与贫血；粪便脂肪定量 >7 g/日，乳糜泻者 tTG-IgA 阳性、十二指肠绒毛萎缩","key":"粪便脂肪定量 + 血清学定性：乳糜泻抗体阳性而无麸质饮食后可恢复"}],"diseases":[{"id":"gi_intestinal_tb","name":"肠结核与结核性腹膜炎","aka":["Intestinal tuberculosis","Tuberculous peritonitis","肠痨","腹膜结核"],"rank":1,"basic":{"define":"结核分枝杆菌侵犯肠道（多为回盲部）或腹膜引起的慢性特异性感染。肠结核以溃疡型与增生型为主，常继发于肺结核；结核性腹膜炎分渗出型、粘连型与干酪型，是腹腔结核最常见的表现形式之一。","risk":["肺结核或其他部位结核病史、结核密切接触史","免疫抑制：糖尿病、长期激素或免疫抑制剂、HIV 感染","营养不良、酗酒与肝硬化","饮用未经消毒的牛奶（牛型分枝杆菌）","青壮年女性（结核性腹膜炎以 20–40 岁女性多见）"],"epi":"我国结核病负担仍重，肠结核多见于青壮年，女性略多。肠结核好发于回盲部（占 80%–90%），其次为升结肠与横结肠。结核性腹膜炎约占肺外结核的 4%–10%，与肠结核常并存。"},"patho":"吞入的结核菌或血行播散至肠壁，在回盲部淋巴组织丰富、肠内容物停留时间长的部位形成干酪样坏死性肉芽肿。溃疡型沿肠壁环形淋巴管走行，呈环形溃疡，易致肠腔狭窄与穿孔；增生型以肉芽组织与纤维化为主，形成包块与梗阻。腹膜受累时渗出纤维蛋白性液体，机化后形成粘连与分隔，干酪型可形成结核性脓肿与瘘管。","dx":{"criteria":["症状：慢性腹痛（右下腹或脐周）、腹泻或便秘交替、午后低热、盗汗、乏力与体重下降；腹膜炎者腹胀、腹水与腹部揉面感","结肠镜见回盲部溃疡（环形、不规则、边缘鼠咬状）或增生性狭窄，活检见干酪样坏死性肉芽肿或抗酸杆菌","微生物学证据：组织或腹水抗酸染色、结核培养或核酸检测（Xpert MTB/RIF）阳性","免疫学证据：T-SPOT.TB 或 IGRA 阳性（提示感染，不能单独确诊）","腹水为渗出液：蛋白 >25–30 g/L、腺苷脱氨酶（ADA）>30–40 U/L、淋巴细胞为主，腹水 ADA 联合 T-SPOT 有助诊断","诊断性抗结核治疗 6–8 周有效为支持依据，但不宜单独作为确诊手段"],"workup":["结肠镜 + 多点活检（含溃疡边缘与正常黏膜交界处），组织送病理、抗酸染色、结核培养与 Xpert MTB/RIF","腹部 CT 或 CT 小肠造影：肠壁增厚、肠系膜淋巴结钙化或坏死、回盲部狭窄与腹水","胸片与胸部 CT 排查活动性肺结核","T-SPOT.TB、血沉、CRP、血红蛋白与白蛋白","腹水检查：细胞计数分类、蛋白、LDH、ADA、培养、Xpert","结核培养与药敏（必要时）"],"grading":"肠结核分溃疡型、增生型与混合型。结核性腹膜炎分渗出型（腹水为主）、粘连型（肠管粘连成团、易梗阻）、干酪型（结核性脓肿、瘘管）。按病变范围与并发症分轻、中、重度。"},"ddx":[{"name":"克罗恩病（IBD 大类 cd）","point":"与本科室 IBD 大类（gi_2）中克罗恩病的鉴别点：CD 为纵行溃疡与铺路石样改变、裂隙状非干酪样肉芽肿、肛周病变多见；肠结核为环形溃疡与干酪样肉芽肿，T-SPOT 阳性。"},{"name":"缺血性肠病（gi_ischemic_bowel）","point":"与本类同大类疾病（肠结核）鉴别：缺血性肠病多见于老年动脉硬化者、急性起病、血便为主、内镜见节段性黏膜坏死；肠结核为慢性低热与回盲部病变。"},{"name":"肠淋巴瘤","point":"回盲部肿块需与增生型肠结核鉴别；淋巴瘤活检见单一克隆性淋巴细胞浸润，PET-CT 与结核培养阴性可助鉴别。"},{"name":"腹水待查：肝硬化腹水与卵巢肿瘤腹膜转移","point":"腹水 SAAG <11 g/L 提示门脉高压性；结核性腹膜炎腹水为渗出液、ADA 高，卵巢肿瘤伴 CA125 升高与盆腹腔肿块需妇科评估。"},{"name":"结肠癌与家族性腺瘤性息肉病（gi_fap）","point":"与胰腺等其他大类疾病区分：FAP 以多发腺瘤与 APC 突变为主，肠镜下见数百枚息肉；肠结核的狭窄无息肉背景。"}],"tx":{"drug":[{"name":"异烟肼（H）","dose":"5 mg/kg/日（成人常 300 mg qd），空腹顿服；遵说明书","note":"核心杀菌药，需联合用药防耐药；治疗前后监测肝酶，补充维生素 B6 防周围神经炎。","renal":"肾功能不全按说明书调整","hepatic":"肝功能明显异常时暂停或调整并查原因","interact":"抑制 CYP 酶升高苯妥英钠、华法林浓度；与酒精合用增加肝毒性"},{"name":"利福平（R）","dose":"10 mg/kg/日（成人常 450–600 mg qd），空腹顿服；遵说明书","note":"与异烟肼构成强化期核心；服药后尿、泪与汗呈橘红色属正常。","renal":"肾功能不全一般无需调整","hepatic":"严重肝病慎用并监测","interact":"强 CYP3A4 诱导剂，降低口服避孕药、华法林、糖皮质激素与抗 HIV 药效"},{"name":"吡嗪酰胺（Z）","dose":"25 mg/kg/日（成人 1.5 g/日，体重 <50 kg 用 1.0 g）；遵说明书","note":"强化期 2 个月使用，杀灭细胞内菌；监测尿酸与肝功能。","renal":"肾功能不全按说明书减量或延长间隔","hepatic":"肝毒性较明显，定期监测肝酶","interact":"升高血尿酸，与别嘌醇等合用需监测"},{"name":"乙胺丁醇（E）","dose":"15 mg/kg/日（成人 0.75–1.0 g qd）；遵说明书","note":"抑菌药，强化期联合使用；用药前与期间查视力与色觉，警惕视神经炎。","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与其他视神经毒性药物合用加重风险"},{"name":"糖皮质激素（结核性腹膜炎重症渗出型）","dose":"泼尼松 20–30 mg/日，4–6 周后逐渐减量；遵说明书","note":"在有效抗结核基础上用于大量腹水或明显全身症状，缩短吸收时间；不得单用于活动性结核。","renal":"遵说明书","hepatic":"遵说明书","interact":"利福平加速其代谢，需增加剂量监测疗效"}],"nonDrug":["标准抗结核方案：强化期 2 个月异烟肼 + 利福平 + 吡嗪酰胺 + 乙胺丁醇，巩固期 4 个月异烟肼 + 利福平（总疗程 6 个月）；肠结核或严重腹膜炎可延长至 9 个月","完全性肠梗阻、急性穿孔、大出血或肠瘘需手术：切除病变肠段并一期吻合，同时继续抗结核","结核性腹膜炎大量腹水：限盐利尿，必要时腹腔穿刺放液；干酪型脓肿需引流","营养支持：高蛋白高热量饮食，贫血与低蛋白者补充铁剂与白蛋白","确诊后按结核病防治要求上报并督导服药（DOT）"],"life":["规律全程用药，避免自行停药；每月复查肝功、血常规与尿酸","治疗 2 个月末复查结肠镜或影像评估应答，无应答时复核诊断或考虑耐药","家庭成员与密切接触者筛查结核；合并 HIV 者抗结核与抗病毒治疗需协调顺序","治愈后 1 年内避免剧烈运动与腹部外伤，疤痕狭窄者随访肠梗阻症状"]},"prog":"规范抗结核治疗 6–9 个月后肠结核及结核性腹膜炎的临床治愈率可达 90% 以上，症状多在 2–4 周内缓解。约 20%–30% 肠结核会遗留肠腔狭窄，需内镜扩张或手术；耐药结核或延误诊断者肠梗阻、穿孔与瘘管风险增加。","refs":["《中国结核病防治工作技术指南（2021 年版）》","中华医学会结核病学分会《结核病诊疗指南（2017）》","《外科学》第 9 版 肠结核与结核性腹膜炎","WHO Global Tuberculosis Report 2023"]},{"id":"gi_ischemic_bowel","name":"缺血性肠病","aka":["Ischemic bowel disease","Intestinal ischemia","结肠缺血","缺血性结肠炎","肠系膜缺血"],"rank":2,"basic":{"define":"因肠系膜血管闭塞、狭窄或灌注不足导致肠壁缺血的一组疾病，包括急性肠系膜缺血（动脉栓塞、动脉血栓、静脉血栓、非闭塞性肠缺血）与慢性肠系膜缺血，以及结肠缺血（缺血性结肠炎）。缺血程度从可逆的黏膜损伤到全层坏死、穿孔。","risk":["高龄、动脉粥样硬化（慢性缺血与动脉血栓的主要原因）","心房颤动、心瓣膜病与近期心梗（动脉栓塞的主要来源）","低血压、休克、严重心衰、血液透析与脓毒症（非闭塞性肠缺血）","高凝状态（恶性肿瘤、口服避孕药、门脉高压）与脱水（静脉血栓）","便秘、低血容量与血管活性药物（结肠缺血）","既往腹部手术、放疗史"],"epi":"急性肠系膜缺血起病凶险，院内病死率约 30%–50%，占急性腹痛外科急腹症的 0.1%–0.3%。结肠缺血是缺血性肠病最常见的类型，年发病率约每 10 万人 10–20 例，多见于 60 岁以上人群；慢性肠系膜缺血约占 5%–10%。"},"patho":"肠壁对血流减少最敏感的部位是黏膜层，灌注下降时黏膜先发生缺血、坏死与通透性增加，可表现为肠腔内出血与蛋白漏出。动脉栓塞多位于肠系膜上动脉第一分支以远的走行区；动脉血栓在固有狭窄的基础上形成；静脉血栓致肠壁水肿、严重酸化与小血管痉挛。非闭塞性肠缺血是内脏血管痉挛的结果，肠壁呈斑片状坏死。慢性缺血为餐后血流需求增加与供血不足的矛盾，即肠绞痛。结肠侧支丰富，故常为自限性节段性缺血。","dx":{"criteria":["急性肠系膜缺血三联征：腹痛剧烈而体格检查与之不符、合并器质性心脏病、胃肠排空症状（强烈排便感或恶心呕吐）；可伴便血、呕血与休克","慢性肠系膜缺血：反复餐后腹痛（进食后 15–30 min 发作、持续 1–3 h）、体重下降与恐食","实验室：白细胞升高、血乳酸升高、D-二聚体升高、代谢性酸中毒、淀粉酶可轻度升高","CTA（动脉期 + 静脉期）为首选影像：见肠系膜上动脉充盈缺损、狭窄或血栓、肠壁增厚、肠壁积气与门静脉积气（提示坏死）","结肠缺血：内镜见节段性黏膜充血水肿、糜烂与纵行溃疡，病变与正常黏膜分界清晰，较缓起者见色素样改变","非闭塞性肠缺血以造影见血管通畅而血流不足为特点，需结合灌注压与临床表现"],"workup":["生命体征与腹部查体，评估休克与腹膜炎体征","血常规、血乳酸、血气分析、D-二聚体、淀粉酶、肝肾功能","心电图与心脏超声（寻找栓塞来源）","腹部 CTA（动脉期与静脉期）为确诊关键；肾功能不全者权衡对比剂风险","腹部平片与 CT 评估肠管扩张、积气与穿孔征象","结肠镜（病情稳定、无腹膜炎与坏死征象时）明确结肠缺血范围与严重度"],"grading":"结肠缺血内镜分级：Ⅰ 期为可逆的黏膜坏死与水肿，Ⅱ 期为黏膜溃疡（分为浅表与深在），Ⅲ 期为全层坏死（狭窄或坏疽）。按临床分型分为 Ⅰ 型（一过性黏膜缺血）、Ⅱ 型（狭窄型，Ⅱa 短期、Ⅱb 慢性）与 Ⅲ 型（坏疽型）。急性肠系膜缺血分为动脉栓塞型、动脉血栓型、静脉血栓型与非闭塞型。"},"ddx":[{"name":"肠结核与结核性腹膜炎（gi_intestinal_tb）","point":"与本类同大类疾病（肠结核）鉴别：慢性低热、盗汗与回盲部环形溃疡，T-SPOT 阳性；缺血性肠病起病急、以血便与血管病变为主。"},{"name":"吸收不良综合征（gi_malabsorption）","point":"与本类同大类疾病（肠结核）鉴别：吸收不良为慢性脂肪泻与消瘦，粪便脂肪定量升高；缺血性结肠炎为急性起病、血便为主、内镜见节段性黏膜坏死。"},{"name":"急性胰腺炎（ap_acute）","point":"与本科室胰腺大类（gi_2）中急性胰腺炎的鉴别点：胰腺炎为持续性上腹痛向背部放射、血淀粉酶与脂肪酶升高、CT 见胰腺坏死；缺血性肠病以腹痛与体征不符、乳酸升高为特点。"},{"name":"急性肠系膜静脉血栓","point":"静脉型多亚急性起病、CT 见肠系膜静脉血栓，需抗凝为主；动脉型需立即血管开通。"},{"name":"溃疡性结肠炎与克罗恩病（IBD 大类）","point":"与 IBD 大类的鉴别点：IBD 为慢性反复血便、连续弥漫性黏膜病变、多自发缓解复发；结肠缺血为节段性、突发血便、多见于老年血管病者。"}],"tx":{"drug":[{"name":"普通肝素或低分子肝素（静脉血栓型）","dose":"普通肝素按体重静脉泵入，维持 APTT 目标范围；或依诺肝素 1 mg/kg q12h 皮下；遵说明书","note":"肠系膜静脉血栓一经诊断即应抗凝，可降低复发与再手术率。","renal":"Ccr <30 ml/min 时低分子肝素减量或改用普通肝素","hepatic":"肝功能严重异常者监测出血风险","interact":"与抗血小板药、NSAIDs 合用增加出血"},{"name":"阿司匹林与他汀（动脉硬化基础治疗）","dose":"阿司匹林 100 mg qd；阿托伐他汀 20–40 mg qn；遵说明书","note":"慢性肠系膜缺血与心脑血管病患者需长期二级预防；不能代替血管开通。","renal":"重度肾功能不全慎用他汀大剂量","hepatic":"肝功能明显异常者慎用，监测肝酶","interact":"他汀与红霉素、唑类抗真菌药合用增加肌病风险"},{"name":"广谱抗生素（肠壁坏死与黏膜屏障破坏）","dose":"如哌拉西林他唑巴坦按说明书剂量；遵说明书","note":"覆盖革兰阴性菌与厌氧菌，减少细菌易位与败血症；不替代血管开通与手术。","renal":"按肌酐清除率减量","hepatic":"遵说明书","interact":"与华法林合用增加出血"},{"name":"罂粟碱（肠系膜血管痉挛，非闭塞型）","dose":"经肠系膜动脉导管持续泵入，剂量遵说明书；遵说明书","note":"用于非闭塞性肠缺血或术后辅助，须在介入导管条件下使用。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"镇痛与液体复苏","dose":"按需滴定；遵说明书","note":"疼痛剧烈者适度镇痛，但不得因此延误手术评估；液体复苏纠正低血容量与维护灌注。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["急性肠系膜缺血一经怀疑立即禁食、液体复苏、广谱抗菌并启动介入或外科会诊","血管开通：血栓或栓塞行经导管溶栓、抽吸与球囊扩张支架；动脉血栓者血栓切除","已坏死肠段行肠切除吻合，术中视生机决定切除范围；无条件重建者行二次探查","慢性肠系膜缺血：血管成形与支架或旁路手术，改善餐后腹痛与体重","结肠缺血：轻中度以禁食、补液、抗菌与观察为主，多在 1–2 周恢复；全层坏疽、广泛狭窄或穿孔才手术","避免使用收缩内脏血管的升压药（非闭塞型），必要时用多巴酚丁胺改善心输出"],"life":["出院后控制动脉粥样硬化危险因素：血压、血脂、血糖、戒烟","合并心房颤动者评估长期抗凝预防再栓塞","结肠缺血恢复后 6 周复查结肠镜排除狭窄，狭窄致梗阻者行球囊扩张或手术","慢性肠系膜缺血术后每 6–12 个月复查血管影像，监测支架通畅"]},"prog":"急性肠系膜缺血病死率高，动脉型若未在 12–24 h 内开通血管，肠坏死与病死率显著上升；静脉血栓型在抗凝下预后较好。结肠缺血多数在数日内缓解，约 15%–20% 形成暂时性狭窄，需手术的坏疽型约占 15%。慢性肠系膜缺血在血管重建后症状缓解率达 80%–90%。","refs":["中华医学会消化病学分会《缺血性肠病诊治中国专家建议（2019）》","《内科学》第 9 版 缺血性肠病","ACG Clinical Guideline: Management of Ischemic Colitis 2023","ESVS Clinical Practice Guidelines on Chronic Mesenteric Ischaemia 2020"]},{"id":"gi_malabsorption","name":"吸收不良综合征（含乳糜泻）","aka":["Malabsorption syndrome","Celiac disease","Coeliac disease","乳糜泻","麸质敏感性肠病","吸收不良"],"rank":3,"basic":{"define":"因消化、吸收或转运环节障碍导致营养素（脂肪、碳水化合物、蛋白质、维生素与矿物质）吸收不足的一组疾病，包括腔内消化不良、黏膜吸收障碍与淋巴转运障碍，可引起慢性腹泻、体重下降与营养不良。乳糜泻（麸质敏感性肠病）是免疫介导的小肠黏膜绒毛萎缩，为最常见的黏膜吸收障碍病因之一。","risk":["乳糜泻：欧洲人群遗传背景、HLA-DQ2/DQ8 阳性、1 型糖尿病与自身免疫甲状腺病","小肠黏膜病变（感染后、药物性、放射性肠炎）","肠道手术后（短肠综合征、胃大部切除、广泛回肠切除）","慢性胰腺炎与胰腺功能不全（gi_chronic_pancreatitis）","胆汁酸缺乏（胆道梗阻、回肠切除）与细菌过度生长","淋巴管扩张、Ménétrier 病与充血性心衰致蛋白丢失"],"epi":"乳糜泻在全球患病率约 0.5%–1%，我国既往认为少见，近年报道增多，多与腹泻、贫血或生长发育迟缓相关。吸收不良的病因分布随地区而异，慢性胰腺炎、细菌过度生长与炎症性肠病是门诊常见的继发因素；小肠细菌过度生长在老年人、糖尿病与胃酸抑制剂长期使用者中更常见。"},"patho":"消化吸收分三阶段：腔内水解（胰酶、胆汁酸）、刷状缘黏膜水解与吸收、淋巴或门脉转运。任一环节缺陷均可致吸收不良：胰腺外分泌不足时脂肪泻最明显；胆盐缺乏影响微胶粒形成；乳糜泻中麦胶蛋白肽激活 HLA-DQ2/DQ8 限制的 CD4+ T 细胞，引起黏膜炎症、隐窝增生与绒毛萎缩，吸收面积显著减少并伴屏障破坏。淋巴管阻塞或小肠广泛切除使乳糜微粒与脂溶性维生素吸收减少。各种病因最终导致脂肪、维生素与微量元素缺乏，表现为贫血、骨质疏松、凝血异常与体重下降。","dx":{"criteria":["症状：慢性腹泻（粪便量多、色淡、油污状与恶臭）、腹胀、体重下降、乏力、肌肉萎缩与水肿；可伴贫血、口角炎、夜盲、骨痛与出血倾向","粪脂定量（72 h 粪便脂肪）：每日 >7 g 提示脂肪吸收不良","乳糜泻血清学：组织型谷氨酰胺转移酶 IgA（tTG-IgA）敏感性与特异性约 95%，须排除 IgA 缺乏（同时查总 IgA）","十二指肠活检见绒毛萎缩、隐窝增生与上皮内淋巴细胞增多（Marsh 分期）为确诊依据","诊断乳糜泻需在无麸质饮食前进行检查，抗体与活检在摄入麸质期间进行","其他：粪便弹性蛋白酶 <200 μg/g 提示胰腺外分泌不足；氢呼气试验诊断乳糜泻相关乳糖不耐受或小肠细菌过度生长"],"workup":["营养评估：体重与 BMI、白蛋白、前白蛋白、血红蛋白与铁蛋白","粪便检查：粪脂定量、隐血、电解质与渗透压梯度（区分渗透性腹泻）","血清学：tTG-IgA、抗肌内膜抗体、总 IgA；必要时抗麦胶蛋白抗体","维生素与微量元素：叶酸、维生素 B12、25-羟维生素 D、维生素 K（INR）、钙、镁、锌","粪便弹性蛋白酶与粪钙卫蛋白","胃镜与十二指肠多点活检（球部 4 块以上、降部），必要时胶囊内镜或小肠镜","腹部 CT、小肠 CT 或 MR 评估肠壁增厚与淋巴结"],"grading":"乳糜泻黏膜损伤按 Marsh 分级：0 期正常；1 期上皮内淋巴细胞增多；2 期隐窝增生；3a 绒毛部分萎缩；3b 绒毛次全萎缩；3c 绒毛完全萎缩。临床分典型（腹泻与吸收不良）、非典型（贫血、骨病）与沉默型（无症状但血清学与病理阳性）。"},"ddx":[{"name":"肠结核与结核性腹膜炎（gi_intestinal_tb）","point":"与本类同大类疾病（肠结核）鉴别：肠结核为慢性低热、右下腹痛与回盲部病变；乳糜泻为麦胶摄入后腹泻、tTG-IgA 阳性与绒毛萎缩。"},{"name":"缺血性肠病（gi_ischemic_bowel）","point":"与本类同大类疾病（肠结核）鉴别：缺血性肠病为急性腹痛与血便伴血管病变；吸收不良为慢性脂肪泻与营养缺乏，粪便脂肪定量升高、tTG-IgA 可阳性。"},{"name":"慢性胰腺炎（gi_chronic_pancreatitis）","point":"与其他大类（pancreas_chronic_polyposis）鉴别：慢性胰腺炎有饮酒史、胰腺钙化与胰管扩张、粪弹性蛋白酶降低；乳糜泻为 tTG 阳性与绒毛萎缩。"},{"name":"小肠细菌过度生长（SIBO）","point":"以腹胀、腹泻与体重下降为主，氢呼气试验升高（空腹 ≥20 ppm 或 90 min 内升高 ≥20 ppm），抗生素治疗后改善。"},{"name":"克罗恩病（IBD 大类 cd）","point":"与 IBD 大类的鉴别点：CD 为节段性透壁炎症，可有瘘管与肛周病变，活检为肉芽肿；乳糜泻为弥漫性绒毛萎缩且无麸质饮食后恢复。"}],"tx":{"drug":[{"name":"无麸质饮食（乳糜泻根本治疗）","dose":"终生严格避免小麦、大麦、黑麦及其制品，按营养师方案执行；遵说明书","note":"非药物措施为核心，需注意交叉污染与隐性麸质；不作膳食干预者血清学与病理不会恢复。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"胰酶替代（胰腺外分泌不足）","dose":"每餐脂肪酶的起始剂量按说明书，随主餐加量；遵说明书","note":"需与餐同服或餐后服，按脂肪摄入量调整；保持餐中胃酸抑制可提高疗效。","renal":"遵说明书","hepatic":"遵说明书","interact":"与抑酸剂合用可减少肠溶包膜破坏"},{"name":"骨化三醇或维生素 D 与钙剂","dose":"按检测结果个体化，遵说明书","note":"用于乳糜泻或吸收不良导致的骨软化与骨质疏松，纠正后定期复查。","renal":"肾功能不全者慎用活性维生素 D 并监测血钙","hepatic":"遵说明书","interact":"与噻嗪类利尿剂合用增加高钙血症风险"},{"name":"维生素 B12 与叶酸","dose":"B12 肌注或口服按说明书；叶酸 5 mg/日；遵说明书","note":"吸收不良伴大细胞性贫血时补充，定期复查血象。","renal":"遵说明书","hepatic":"遵说明书","interact":"大剂量叶酸可掩盖 B12 缺乏的血液学表现，需同时评估"},{"name":"铁剂（缺铁性贫血）","dose":"口服铁剂按元素铁剂量，遵说明书；效果不佳时静脉补铁","note":"乳糜泻在无麸质饮食后吸收改善；口服不能耐受者改为静脉。","renal":"遵说明书","hepatic":"严重肝功能异常者慎用","interact":"与质子泵抑制剂、钙剂、四环素类合用降低吸收"},{"name":"利福昔明（小肠细菌过度生长）","dose":"400 mg q8h 或 550 mg q8h，疗程 1–2 周；遵说明书","note":"肠道内作用、全身吸收少，可重复疗程使用。","renal":"遵说明书","hepatic":"严重肝功能不全者慎用","interact":"对口服避孕药的效果可能降低"}],"nonDrug":["营养支持：乳糜泻者按营养师方案补充热量与维生素，严重营养不良或短肠者需肠内或肠外营养","治疗可逆病因：停用可疑药物、纠正细菌过度生长、治疗寄生虫（贾第虫）与胆汁酸缺乏","小肠狭窄或淋巴管疾病必要时手术，短肠综合征需长期营养管理","乳糜泻合并难治性者排除隐性麸质摄入与相关淋巴瘤，必要时激素或免疫抑制剂","随访小肠与结肠恶性肿瘤风险（乳糜泻者肠病相关 T 细胞淋巴瘤风险略升）"],"life":["乳糜泻确诊后每 6–12 个月复查 tTG-IgA，抗体滴度下降为依从性良好的指标","每年评估营养指标、骨密度（风险者 2 年复查）与生长发育（儿童）","避免盲目长期服用抑酸剂与抗菌药，防止细菌过度生长","酒精性胰腺炎者须戒酒并补充脂溶性维生素"]},"prog":"乳糜泻在严格无麸质饮食后多数 6–12 个月黏膜恢复，症状多在数周内改善；未依从者并发症（骨质疏松、不孕、恶性肿瘤风险升高）增加，约 5% 呈难治性。吸收不良若不纠正，长期可致严重营养不良与骨病；慢性胰腺炎致吸收不良者胰酶替代后血脂与体重可改善。","refs":["中华医学会消化病学分会《中国成人乳糜泻诊断和治疗共识意见（2023）》","《内科学》第 9 版 吸收不良综合征与乳糜泻","ACG Clinical Guidelines: Diagnosis and Management of Celiac Disease 2023","ESPGHAN/WSG 乳糜泻相关共识"]}]},{"id":"pancreas_chronic_polyposis","name":"慢性胰腺炎与遗传性息肉病","rank":10,"summary":"慢性胰腺炎以腹痛与胰腺内外分泌功能不全为双主线，治疗围绕镇痛、胰酶替代、内镜减压与营养支持，内镜无效时胰管引流或切除；家族性腺瘤性息肉病以 APC 致病突变为核心，几乎 100% 进展为结直肠癌，须在青春期后按息肉负荷与基因型决定预防性结肠切除时机。","compare":[{"diseaseId":"gi_chronic_pancreatitis","dx":"反复上腹痛向背部放射伴胰腺钙化、胰管不规则扩张与粪弹性蛋白酶降低；有长期饮酒史或特发性","key":"影像见钙化、胰管扩张与胰腺萎缩；功能不全（脂肪泻、糖尿病）"},{"diseaseId":"gi_fap","dx":"结肠镜见 ≥100 枚腺瘤性息肉（典型者数百至数千枚），常伴胚系 APC 突变；可伴十二指肠腺瘤、硬纤维瘤与先天性视网膜色素上皮肥厚","key":"息肉数量 + 基因与家系证据；未切除者结直肠癌风险近 100%"}],"diseases":[{"id":"gi_chronic_pancreatitis","name":"慢性胰腺炎","aka":["Chronic pancreatitis","CP","慢性复发性胰腺炎","胰腺慢性炎症"],"rank":1,"basic":{"define":"在各种病因作用下胰腺持续性炎症与纤维化，导致腺泡与胰岛进行性破坏、胰管变形狭窄，最终出现胰腺外分泌（脂肪泻、消化不良）与内分泌（糖耐量异常或糖尿病）功能不全，并伴反复腹痛。少数可进展为胰腺癌。","risk":["长期大量饮酒（我国首位病因，约占 30%–50%）","胆道疾病与胰管梗阻（结石、狭窄）","特发性与遗传性（PRSS1、SPINK1 突变）","吸烟（独立危险因素）","自身免疫性胰腺炎与热带钙化性胰腺炎","高钙血症、高脂血症与腹部外伤"],"epi":"我国慢性胰腺炎患病率约每 10 万人 10–40 例，近年随饮酒量增加而升高；男女比例接近。常见的发病年龄在 40–60 岁，特发性和遗传性者发病更早。确诊时约 30%–50% 已有胰腺外分泌不足，30%–60% 继发糖尿病。"},"patho":"多种损伤因素反复激活胰蛋白酶原，使腺泡细胞发生腺泡–导管化生并被纤维组织替代，胰管周围纤维化与蛋白栓形成导致胰管变形、扩张或狭窄。腺泡细胞丢失超过 90% 时出现外分泌不足，脂肪泻出现较晚；胰岛细胞呈灶性丢失，以 β 细胞受累为主，发生糖尿病（脆弱型、易低血糖）。纤维化与痛觉神经重塑使腹痛持续，微循环障碍与氧化应激加重损伤。","dx":{"criteria":["反复发作的上腹痛，向背部放射，进食后加重，镇痛药依赖","胰腺外分泌不足：脂肪泻（粪便量多、油污），粪弹性蛋白酶 <200 μg/g（重度 <100 μg/g）","胰腺内分泌不足：空腹血糖 ≥7.0 mmol/L 或 HbA1c ≥6.5%，病程中出现的糖尿病","影像学：CT 见胰腺钙化、胰管不规则扩张、腺体萎缩；MRCP 见胰管串珠样改变","内镜超声见胰腺实质与胰管的典型改变并活检确诊可疑肿块","符合 M-ANNHEIM 或 Manchester 诊断体系；无钙化者可结合 EUS 与功能试验"],"workup":["血淀粉酶与脂肪酶（发作期可升高，不用于确诊慢性状态）","粪弹性蛋白酶与粪脂定量、营养指标（白蛋白、维生素 D、A、E）","空腹血糖、HbA1c、OGTT","腹部增强 CT（首选）与 MRCP；胰胆管内镜（ERCP）用于治疗与评估","内镜超声（EUS）：评估狭窄、结石与早期实质改变，可细针穿刺排除癌变","肿瘤标志物 CA19-9 与 CEA（不能确诊，用于监测）","影像见可疑肿块或体重快速下降时行 EUS-FNA 或 PET-CT"],"grading":"M-ANNHEIM 严重度分级：0 期无功能不全；Ⅰ 期无功能不全；Ⅱ 期有胰腺外分泌或内分泌功能不全或并发症；Ⅲ 期需手术或内镜干预；Ⅳ 期不可逆手术并发症或终末期。Cambridge 影像分级 1–4 级（正常→胰管严重变形伴钙化）用于评估结构改变。"},"ddx":[{"name":"家族性腺瘤性息肉病（gi_fap）","point":"与本类同大类疾病（肠结核）鉴别：FAP 以结肠多发腺瘤与 APC 突变为核心，腹痛多来自肠梗阻；慢性胰腺炎为胰腺纤维化与钙化。"},{"name":"胰腺癌","point":"肿块型慢性胰腺炎与胰腺癌鉴别困难；后者进行性消瘦、CA19-9 显著升高、影像见肿块与血管侵犯，需 EUS-FNA 确诊。"},{"name":"自身免疫性胰腺炎","point":"见胰腺癌鉴别：IgG4 升高、影像见弥漫性腊肠样肿大与包膜样影，激素治疗有效，需防误诊。"},{"name":"消化性溃疡与胆道结石","point":"与上消化道大类（gi_1）中溃疡病鉴别：溃疡为上腹痛与反酸、抑酸治疗有效；慢性胰腺炎为向背部放射的持续性腹痛与脂肪泻。"},{"name":"吸收不良综合征（gi_malabsorption）","point":"与其他大类（intestine_other）鉴别：乳糜泻为 tTG 阳性与绒毛萎缩；此病粪弹性蛋白酶降低并伴胰腺钙化。"}],"tx":{"drug":[{"name":"胰酶肠溶胶囊（外分泌不足）","dose":"每主餐给予脂肪酶 ≥25000–50000 单位，随餐服用，可按脂肪摄入与效果增加；遵说明书","note":"需随餐或餐后立即服用，剂量按脂肪泻改善调整；可联用质子泵抑制剂提高活性。","renal":"遵说明书","hepatic":"遵说明书","interact":"含胰酶制剂与酸性药物同服可能破坏肠溶衣"},{"name":"镇痛治疗（腹痛）","dose":"按阶梯给药：对乙酰氨基酚或曲马多、弱阿片类，严重者强阿片类；遵说明书","note":"避免长期使用非甾体抗炎药（消化道与肾脏风险）；阿片类需评估依赖与肠麻痹。","renal":"肾功能不全按说明书调整","hepatic":"严重肝功能不全时阿片类需减量","interact":"阿片类与苯二氮类合用增加呼吸抑制风险"},{"name":"奥曲肽或生长抑素（胰瘘与难治性脂肪泻）","dose":"皮下注射或长效制剂，剂量遵说明书；遵说明书","note":"可抑制胰液分泌，改善部分难治性脂肪泻，但可致血糖升高与胆石。","renal":"遵说明书","hepatic":"遵说明书","interact":"降低环孢素吸收"},{"name":"质子泵抑制剂（辅助胰酶与消化性溃疡）","dose":"奥美拉唑 20 mg qd，必要时加倍；遵说明书","note":"提高胰酶疗效并防治十二指肠溃疡，长期使用者注意骨折与低镁。","renal":"遵说明书","hepatic":"遵说明书","interact":"与氯吡格雷合用可能降低抗血小板效果"},{"name":"胰岛素（继发糖尿病）","dose":"小剂量起始，按血糖调整，优先基础胰岛素；遵说明书","note":"胰腺源性糖尿病为脆弱型糖尿病，易低血糖，目标放宽（HbA1c 7%–8%）。","renal":"肾功能不全时低血糖风险增加，减量","hepatic":"肝功能不全时低血糖风险增加","interact":"与其他降糖药合用警惕低血糖"}],"nonDrug":["戒酒并戒烟，为一切治疗的前提","内镜治疗：胰管结石碎石（ESWL）、ERCP 取石、胰管支架减压，适用于胰管梗阻者；内镜引流可缓解 40%–60% 患者疼痛","手术指征：难治性疼痛、胰管扩张（>7 mm）、十二指肠或胆道梗阻、假性囊肿或瘘管；术式含胰管空肠吻合（Partington-Rochelle）、胰头切除（Beger、Frey）与全胰切除","营养支持：少量多餐、中链甘油三酯、重度营养不良或术后肠外营养","骨密度监测与补充钙与维生素 D","全胰切除者需终身胰酶与胰岛素替代"],"life":["终身戒酒戒烟，避免暴饮暴食（可诱发急性发作）","每 6–12 个月评估营养状态、血糖与肾功能，必要时补充脂溶性维生素","每年行 CT 或 MRCP 与 CA19-9 监测胰腺癌（长期病程者风险升高）","腹痛日记与镇痛依赖评估，必要时心理支持与疼痛专科管理"]},"prog":"病程迁延，疼痛与功能不全进行性加重；约 20%–30% 最终需手术，疼痛缓解率 70%–90%，但术后仍有再发与糖尿病加重。病程超过 10 年者胰腺癌风险显著上升（可达数倍至 20 倍），预后取决于功能不全进展与癌变。","refs":["中华医学会消化病学分会《中国慢性胰腺炎诊治指南（2018）》","中华医学会外科学分会胰腺外科学组《慢性胰腺炎临床诊疗指南（2014）》","《内科学》第 9 版 慢性胰腺炎","HaPanEU/UEG Guidelines on Chronic Pancreatitis 2017","AGA Clinical Practice Update on Chronic Pancreatitis 2020"]},{"id":"gi_fap","name":"家族性腺瘤性息肉病","aka":["FAP","Familial adenomatous polyposis","家族性结肠息肉病","腺瘤性息肉病"],"rank":2,"basic":{"define":"以 APC 基因（染色体 5q21）胚系致病突变引起的常染色体显性遗传性结直肠息肉病，典型者在 10–20 岁起结肠出现数十至数千枚腺瘤性息肉，几乎必然进展为结直肠癌。变异型包括衰减型 FAP（AFAP，息肉 <100 枚、发病更晚）与 MUTYH 相关息肉病（常染色体隐性）。","risk":["FAP 家族史（常染色体显性，外显率高）","APC 胚系致病突变携带者","AFAP 者息肉较少但仍有高癌变风险","合并硬化性硬纤维瘤（腹腔内）与十二指肠腺瘤者","MUTYH 双等位基因突变者（隐性息肉病）"],"epi":"FAP 在人群中发病率约每 10 万人 2–3 例，占所有结直肠癌的约 1%，我国估计每年新发病例数以千计。未手术者 80% 在 30 岁前已现癌症前病变，终身结直肠癌风险接近 100%，平均癌变年龄约 39–45 岁；合并十二指肠腺瘤的癌变风险约 3%–10%。"},"patho":"APC 是 Wnt 信号通路的负调控因子，突变导致 β-catenin 降解障碍与持续核内积聚，腺上皮无限增殖并形成腺瘤；随后 KRAS、TP53 等二次打击驱动腺瘤–癌序列。息肉在结肠内呈地毯式分布且同步多发，加之 APC 驱动的早期增殖，使癌变几乎不可逆。硬纤维瘤源于成纤维细胞与 β-catenin 异常激活；先天性视网膜色素上皮肥厚（CHRPE）为特征性眼表现。","dx":{"criteria":["结肠镜见典型 FAP：腺瘤性息肉 >100 枚（多在 10–20 岁起）；AFAP：10–100 枚、多见于左半结肠、发病较晚","基因检测：检出 APC 致病或可能致病变异；未检出者考虑 MUTYH 双等位变异","家族史：一级亲属已确诊 FAP 或结肠癌早发（<50 岁）","伴发表现：十二指肠腺瘤（>80%）、CHRPE（约 70%–80%）、硬纤维瘤与甲状腺乳头状癌","病理均为管状或管状绒毛状腺瘤，无错构瘤或幼年性息肉特点"],"workup":["结肠镜（全结肠，发现 >20 枚腺瘤即高度怀疑，需计数与活检）","上消化道内镜（胃、十二指肠）评估胃底腺息肉与十二指肠腺瘤（Spigelman 分级）","基因检测（APC 全外显子与拷贝数，家族成员级联筛查）","甲状腺超声（女性 ≥20 岁起）、腹部 CT 或 MRI（硬纤维瘤筛查）","眼科检查 CHRPE（辅助但非必需）","家系图与基因咨询，涉及生育规划者提供产前诊断或胚胎植入前遗传学检测","确诊后评估手术时机前需先完成全结肠评估与基因型分析"],"grading":"十二指肠腺瘤 Spigelman 分级：按息肉数量、大小、病理与异型性分为 0–Ⅳ 级，Ⅳ 级者十二指肠癌风险显著升高。FAP 表型分经典型（>100 枚息肉，早发）与衰减型（10–100 枚，晚发）；按基因型分与手术方式相关。"},"ddx":[{"name":"慢性胰腺炎（gi_chronic_pancreatitis）","point":"与本类同大类疾病（肠结核）鉴别：慢性胰腺炎以胰腺钙化与功能不全为主，无结肠息肉；FAP 以多发结肠腺瘤与 APC 突变为核心。"},{"name":" Lynch 综合征（遗传性非息肉病性结直肠癌）","point":"无多发性息肉背景，为错配修复基因突变，发病早但息肉数量少，需基因检测区分。"},{"name":"MUTYH 相关息肉病","point":"常染色体隐性，息肉 10–100 枚，双等位 MUTYH 突变，父母不发病；APC 突变阴性。"},{"name":"错构瘤性息肉病（Peutz-Jeghers 综合征与幼年性息肉病）","point":"Peutz-Jeghers 综合征以口唇色素斑与错构瘤为主；幼年性息肉病以儿童期便血与黏液性息肉为主，病理非腺瘤。"},{"name":"散发性多发腺瘤","point":"老年人数十枚腺瘤但无家族史与 APC 突变，多为吸烟、肥胖等生活方式相关。"}],"tx":{"drug":[{"name":"塞来昔布或舒林酸（化学预防）","dose":"塞来昔布 400 mg bid 或舒林酸 150 mg bid，用于保留直肠者；遵说明书","note":"可减少十二指肠与残留直肠腺瘤数量，但不能代替手术；注意心血管与胃肠道不良反应。","renal":"eGFR <30 慎用或禁用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、抗血小板药合用增加出血；与锂盐合用升高血锂"},{"name":"阿司匹林（辅助预防）","dose":"低剂量 100–300 mg qd，遵说明书","note":"证据有限，部分用于结肠切除后残留黏膜的复发预防，不能替代内镜随访。","renal":"重度肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"与抗凝药合用增加出血风险"}],"nonDrug":["手术时机：典型 FAP 在 15–20 岁确诊后、息肉密集或出现高级别上皮内瘤变时行预防性结肠切除，多数在 20 岁前后；AFAP 可延至 30–40 岁并以内镜随访为主","术式：全结肠切除 + 回肠贮袋肛管吻合（IPAA）为多数首选；直肠直肠切除 + 回肠造口适用于下段直肠受累者；保留直肠者需终生内镜监测","预防性切除后仍有残余直肠或贮袋腺瘤与癌变风险，需每 1–3 年内镜随访","十二指肠腺瘤按 Spigelman 分级随访：0–Ⅱ 级每 3–4 年内镜；Ⅲ–Ⅳ 级每 1–2 年，必要时内镜下切除或胰十二指肠切除","硬纤维瘤：手术易复发，以观察、激素或抗雌激素、酪氨酸激酶抑制剂（索拉非尼）为主","家族成员从 10–12 岁起每年结肠镜筛查，基因携带者按相同方案"],"life":["基因咨询与家系级联筛查，育龄者提供产前诊断或胚胎植入前遗传学检测","术后随访营养：IPAA 与回肠造口者补充 B12、脂溶性维生素与铁，监测水电解质","每年甲状腺超声（女性尤其），必要时腹部影像筛查硬纤维瘤与壶腹部肿瘤","戒烟限酒、控制体重与规律运动有助于降低残留黏膜的腺瘤复发"]},"prog":"未干预者几乎 100% 在 40 岁前后发生结直肠癌。预防性结肠切除后结直肠癌死亡风险大幅下降，但仍有贮袋或残留直肠癌风险（约 1%–5%）与十二指肠腺癌风险（约 3%–10%），需终身内镜随访。携带者总体生存接近普通人群，硬纤维瘤是影响术后质量与生存的重要并发症。","refs":["中国抗癌协会《中国结直肠癌及癌前病变筛查与诊治指南（2020）》","《中国家族性腺瘤性息肉病诊疗专家共识（2018）》","ESGE Guideline on Endoscopic Management of Hereditary Colorectal Cancer Syndromes 2021","NCCN Guidelines: Genetic/Familial High-Risk Assessment — Colorectal 2023"]}]},{"id":"gastritis_acute","name":"急性胃炎","rank":41,"summary":"急性胃炎是「诱因明确、内镜见糜烂与黏膜下出血」的急性胃黏膜损伤：先停致病药与酒精、再抑酸（PPI 为主）与黏膜保护，出血者 24 h 内镜 + Forrest 分级决定是否镜下止血；应激性溃疡预防只给高危人群，不做普遍预防。","compare":[],"diseases":[{"id":"gi_acute_gastritis","name":"急性胃炎","aka":["Acute gastritis","Acute gastric mucosal lesion","AGML","急性胃黏膜病变","应激性溃疡","Stress-related mucosal disease"],"rank":1,"basic":{"define":"由应激、非甾体抗炎药（NSAID）、酒精、感染或腐蚀性物质等病因引起的胃黏膜急性炎症与糜烂，内镜下以多发糜烂、瘀斑与黏膜下出血为特征，病变深度不超过黏膜肌层者为糜烂、超过者为急性溃疡。临床谱从无症状到上腹痛、恶心呕吐，重者以上消化道出血为首发表现。","risk":["NSAID（含阿司匹林）使用，尤其联用抗凝药、抗血小板药、糖皮质激素或 SSRI","酗酒、暴饮暴食、空腹饮酒与浓茶咖啡","重症应激：休克、大手术、严重创伤、烧伤 >35% TBSA（Curling 溃疡）、颅脑损伤（Cushing 溃疡）、机械通气 >48 h","凝血障碍：血小板 <50×10⁹/L、INR >1.5 或 APTT >2 倍正常","急性幽门螺杆菌感染、细菌毒素或病毒性胃肠炎","腐蚀性物质摄入、胃区放疗、化疗或胃动脉栓塞"],"epi":"患病率因内镜时机与定义差异很大：ICU 重症患者内镜下胃黏膜糜烂或瘀斑可达 50%–100%，但临床显性出血仅约 2%–6%；长期 NSAID 使用者内镜黏膜损伤约 20%–40%，多数无症状。我国上消化道出血病因中急性胃黏膜病变约占 5%–15%，应激性溃疡出血病死率仍高达 20%–50%。"},"patho":"胃黏膜屏障由黏液-碳酸氢盐层、上皮紧密连接、前列腺素与黏膜血流共同维持。NSAID 抑制 COX-1 使前列腺素合成减少，黏液与碳酸氢盐分泌下降、黏膜血流减少，加之药物直接损伤上皮；酒精溶解黏膜脂质层并引起微血管淤血；应激状态下内脏血流重分布、黏膜缺血再灌注产生氧自由基，酸反弥散进一步破坏上皮，形成多发糜烂与黏膜下出血。病变多位于胃底与胃体（应激性）或胃窦（NSAID、酒精、感染）。","dx":{"criteria":["诱因：起病前 1 周内使用 NSAID/阿司匹林、酗酒、应激事件（休克、大手术、创伤、机械通气、颅脑损伤）、不洁饮食或腐蚀物摄入","症状：上腹隐痛或烧灼痛、恶心呕吐、早饱、食欲下降；可完全无症状；出血者呕血或黑便；体检仅上腹压痛，无腹膜刺激征","实验室：出血者 Hb 下降，BUN 升高且 BUN/Cr 比值 >20 提示上消化道出血；粪便隐血阳性；白细胞可轻度升高","内镜（出血者 24–48 h 内）：胃黏膜弥漫充血水肿、多发糜烂（直径 <5 mm 的浅表缺损）、瘀斑与黏膜下出血；溃疡深度超过黏膜肌层者为急性溃疡","组织学：上皮坏死、中性粒细胞浸润、黏膜微血栓；急性 Hp 感染可见淋巴细胞与浆细胞浸润","排除标准：需排除消化性溃疡（溃疡 ≥5 mm、边界清楚、覆白苔）、胃癌、食管贲门黏膜撕裂、静脉曲张出血与血管畸形","出血严重度：Forrest 分级 Ia 喷射性出血、Ib 渗血、IIa 血管裸露、IIb 附着血凝块、IIc 黑色斑点、III 清洁基底；Ia–IIb 为高危再出血","重症判定：血流动力学不稳定（收缩压 <90 mmHg、心率 >100 次/分）、Hb <70 g/L 或需持续输血者按高危管理"],"workup":["血常规、血型、凝血四项（PT/APTT/FIB/D-二聚体）、肝肾功能与电解质","胃镜（出血 24 h 内）明确病变部位、范围与 Forrest 分级，必要时活检排除恶性与 Hp","Hp 检测：组织学（Giemsa 或免疫组化）或尿素呼气试验；急性出血期呼气试验可假阴性，建议 4 周后复查","腹部立位平片或 CT：怀疑穿孔（膈下游离气体）、梗阻或腐蚀性损伤时","出血者计算 Glasgow-Blatchford 评分（0–1 分可门诊管理）与 Rockall 评分评估再出血与死亡风险","腐蚀性损伤：禁急诊胃镜与插胃管（穿孔风险），24–48 h 后由有经验者轻柔内镜评估"],"grading":"病因分型：药物性（NSAID/阿司匹林）、酒精性、应激性（AGML）、感染性（急性 Hp、细菌毒素）、腐蚀性、放射性。内镜按病变范围与出血程度分轻（散在糜烂）、中（融合糜烂伴渗血）、重（广泛黏膜下出血或急性溃疡）；出血灶按 Forrest 分级，Ia–IIb 需内镜干预。"},"ddx":[{"name":"慢性胃炎（gi_gastritis）","point":"本大类仅含急性胃炎 1 个病，最易混淆的邻类疾病是慢性胃炎：慢性胃炎病程 >6 个月、症状与进食相关但程度轻、内镜以黏膜萎缩与肠上皮化生为特征；急性胃炎有明确诱因、1 周内起病、内镜见多发糜烂与黏膜下出血。"},{"name":"消化性溃疡（gi_pud）","point":"溃疡为直径 ≥5 mm、边界清楚、覆白苔或血痂的黏膜缺损，Hp 阳性率约 70%–90%，疼痛有周期性与节律性；急性胃炎为多发浅表糜烂、无明确溃疡壁。"},{"name":"上消化道出血（ugib_peptic / ugib_variceal）","point":"静脉曲张出血量大、呕鲜血、有肝硬化与门脉高压证据（血小板减少、脾大、腹水）；急性胃黏膜病变出血多为弥漫渗血、量相对小，内镜见弥漫糜烂而非孤立病灶。"},{"name":"功能性消化不良（gi_fd）","point":"症状 >3 个月、内镜无黏膜损伤、无报警症状；急性胃炎内镜必有糜烂或出血灶，且病程短。"},{"name":"胃癌","point":"内镜见不规则溃疡或肿块、边缘隆起、黏膜皱襞中断，活检确诊；伴消瘦、贫血、呕吐等报警症状者必须活检。"},{"name":"食管贲门黏膜撕裂（Mallory-Weiss 综合征）","point":"剧烈干呕或呕吐后呕血，内镜见贲门纵行黏膜撕裂；急性胃炎为胃体或胃窦弥漫糜烂、无撕裂。"},{"name":"急性胰腺炎（ap_acute）","point":"上腹痛向背部放射、伴恶心呕吐与腹胀，血淀粉酶或脂肪酶 >3 倍正常上限，CT 见胰腺渗出；胃镜无弥漫糜烂。"}],"tx":{"drug":[{"name":"奥美拉唑 / 艾司奥美拉唑（PPI，静脉或口服）","dose":"口服 20–40 mg qd（晨起餐前 30 min）；不能口服者奥美拉唑 40 mg 静滴 q12h；高危出血（Forrest Ia–IIb）80 mg 静脉推注后 8 mg/h 持续泵入 72 h","note":"抑酸目标胃内 pH >6 以稳定血凝块；应激性溃疡预防用 40 mg qd 即可，不需大剂量；长期使用注意低镁血症、维生素 B12 缺乏与骨折风险。","renal":"无需调整","hepatic":"严重肝功能不全（Child-Pugh C）减量至隔日 1 次","interact":"强抑制 CYP2C19，降低氯吡格雷活性（不推荐联用，需抗血小板者改用泮托拉唑或雷贝拉唑）；升高地西泮、苯妥英钠、华法林浓度"},{"name":"泮托拉唑","dose":"40 mg 静滴 qd–q12h；高危出血 80 mg 静推后 8 mg/h 持续 72 h；口服 40 mg qd","note":"对 CYP2C19 抑制弱，是双联抗血小板或 PCI 患者的首选 PPI；肝肾功能不全者安全性较好。","renal":"无需调整（重度透析患者遵说明书）","hepatic":"严重肝病减量，转氨酶明显升高者停药","interact":"与氯吡格雷相互作用小；可延迟甲氨蝶呤清除"},{"name":"法莫替丁","dose":"20 mg 口服 bid 或 20 mg 静滴 q12h；应激性溃疡预防 20 mg q12h","note":"H2 受体拮抗剂，用于 PPI 不耐受或轻症；抑酸强度弱于 PPI，活动性出血或高危者不首选。","renal":"CrCl <50 ml/min 减半或延长至 q24–48h","hepatic":"严重肝功能不全者减量","interact":"升高胃内 pH，降低酮康唑、伊曲康唑、阿扎那韦吸收；与华法林合用可延长 PT"},{"name":"硫糖铝","dose":"1 g 口服 qid（餐前 1 h 与睡前）或混悬液 10 ml qid","note":"在糜烂面形成保护膜并促进前列腺素合成与上皮修复；需酸性环境起效，不与抑酸药同服。","renal":"慢性肾衰竭者铝蓄积风险，慎用或短期使用","hepatic":"遵说明书","interact":"与氟喹诺酮、四环素、左甲状腺素、华法林、地高辛间隔至少 2 h"},{"name":"铝碳酸镁","dose":"1 g 嚼服 tid–qid（餐后 1–2 h 与睡前）","note":"中和胃酸并结合胆汁酸，适用于酒精或胆汁反流相关黏膜损伤；腹泻或便秘常见。","renal":"严重肾功能不全（CrCl <30 ml/min）禁用，铝镁可蓄积","hepatic":"遵说明书","interact":"与四环素、喹诺酮、铁剂、左甲状腺素间隔 1–2 h"},{"name":"米索前列醇","dose":"200 μg 口服 qid（餐后与睡前）；NSAID 相关溃疡预防可用 200 μg bid","note":"前列腺素 E1 类似物，是唯一针对 NSAID 黏膜损伤机制的预防药物；腹泻与腹绞痛常见，妊娠禁用（引起子宫收缩）。","renal":"重度肾功能不全慎用，遵说明书","hepatic":"遵说明书","interact":"与 NSAID 或镁剂合用加重腹泻"},{"name":"铋剂四联（根除幽门螺杆菌）","dose":"奥美拉唑 20 mg bid + 枸橼酸铋钾 220 mg bid + 阿莫西林 1 g bid + 克拉霉素 500 mg bid，共 14 天；青霉素过敏者改为四环素 500 mg qid + 甲硝唑 400 mg qid","note":"急性胃炎合并 Hp 感染（组织学或呼气试验阳性）者应根除；疗程结束至少 4 周后复查尿素呼气试验确认。","renal":"CrCl <30 ml/min 时铋剂与部分抗生素需调整，遵说明书","hepatic":"严重肝功能不全者克拉霉素减量或避免","interact":"铋剂降低四环素吸收（间隔 2 h）；克拉霉素为 CYP3A4 抑制剂，与他汀、华法林及 QT 延长药合用需谨慎"},{"name":"对乙酰氨基酚（止痛）","dose":"0.5 g 口服 q6h 按需，每日不超过 2 g（伴肝病者）；连续使用不超过 3 天","note":"急性胃炎止痛应避免 NSAID，改用对乙酰氨基酚；过量可致肝坏死。","renal":"CrCl <30 ml/min 延长给药间隔至 q8h","hepatic":"肝病者每日 ≤2 g 且禁酒；INR >1.5 或胆红素 >85 μmol/L 时避免","interact":"长期与华法林合用可升高 INR；酒精、异烟肼、卡马西平增加肝毒性"}],"nonDrug":["立即停用致病药物：NSAID 与阿司匹林；因心血管二级预防服用阿司匹林者不停药，改为加用 PPI（双联抗血小板者首选泮托拉唑）","应激性溃疡预防仅限高危人群：机械通气 >48 h、凝血障碍（血小板 <50×10⁹/L、INR >1.5）、休克需升压药、严重颅脑或脊髓损伤、烧伤 >35% TBSA、大剂量糖皮质激素、既往消化道出血史；低危者不预防","内镜下止血：Forrest Ia–IIb 者 24 h 内镜，采用钛夹、1:10000 肾上腺素注射或热凝，术后联合大剂量 PPI","腐蚀性损伤：禁止洗胃与插胃管（穿孔风险），24–48 h 内早期内镜评估，禁产气饮料，镇痛与营养支持","幽门螺杆菌阳性者根除治疗，家族成员同查同治","难治性出血：血管造影栓塞（胃左或胃十二指肠动脉）；手术（溃疡缝合、胃大部切除）仅用于内镜与介入均失败者"],"life":["戒酒，避免空腹饮酒、浓茶与咖啡，规律进食、少食多餐","必须使用 NSAID 时选最低有效剂量并联合 PPI 或米索前列醇，避免与抗凝药、糖皮质激素、SSRI 叠加","出血后 4–8 周复查胃镜确认愈合并排除恶性","长期 PPI 者每年评估必要性，监测血镁与维生素 B12","出现黑便、呕血、头晕心悸或立位晕厥立即就诊"]},"prog":"去除病因后多数患者 1–2 周黏膜修复、症状 3–7 天缓解。NSAID 相关者停药联合 PPI 预后良好；应激性溃疡并发大出血者病死率 20%–50%，取决于基础疾病与多器官功能衰竭程度。腐蚀性损伤可遗留幽门狭窄或食管狭窄，需长期随访。","refs":["《中国急性胃黏膜病变急诊专家共识》（中国医师协会急诊医师分会，2015）","《应激性溃疡防治专家建议（2015 版）》","《非甾体消炎药相关消化道溃疡与溃疡并发症的预防与治疗规范建议》（2017）","《中国慢性胃炎诊治指南（2022 年，上海）》","《急性非静脉曲张性上消化道出血诊治指南（2018 年，杭州）》"]}]},{"id":"viral_hepatitis_more","name":"其他病毒性肝炎","rank":42,"summary":"甲型与戊型均经粪口传播、多为急性自限性肝炎，靠抗-HAV IgM 与抗-HEV IgM/HEV RNA 区分；戊型在孕妇与免疫抑制者凶险（病死率 20%–25%、慢性化 60%–80%）。丁型是缺陷病毒，必须与 HBsAg 共存，重叠感染最易慢性化与重症化，聚乙二醇干扰素是基础治疗。","compare":[{"diseaseId":"gi_hav","dx":"不洁饮食或生食贝类后急性起病，ALT 常 500–5000 U/L，抗-HAV IgM 阳性；病程自限、无慢性化","key":"抗-HAV IgM 阳性 + 无慢性化；暴露后 2 周内接种疫苗可阻断发病"},{"diseaseId":"gi_hdv","dx":"HBsAg 阳性者出现 ALT 双峰或急性肝炎，抗-HDV IgM 与 HDV RNA 阳性；重叠感染 70%–90% 慢性化","key":"必须 HBsAg 共存；HBsAg 阳性者一律筛查抗-HDV，HDV RNA 是确诊与疗效金标准"},{"diseaseId":"gi_hev","dx":"水源或生食猪肉后急性肝炎，抗-HEV IgM 或 HEV RNA 阳性；孕妇感染病死率 20%–25%，免疫抑制者 HEV RNA 持续 >6 个月即慢性戊肝","key":"孕妇重症与免疫抑制者慢性化是两个标志性特征；慢性者用利巴韦林"}],"diseases":[{"id":"gi_hav","name":"甲型病毒性肝炎","aka":["Hepatitis A","甲肝","HAV 感染","传染性肝炎"],"rank":1,"basic":{"define":"甲型肝炎病毒（HAV，小 RNA 病毒科嗜肝病毒属）经粪口途径传播引起的急性肝脏炎症。临床多为急性自限性过程，无慢性化、无病毒携带状态，感染后可获终身免疫。","risk":["生食或半生食贝类（毛蚶、牡蛎）、不洁饮水与食物","卫生条件差的地区居住或旅行，托幼机构、集体单位、部队等聚集性场所","甲肝患者密切接触、家庭内传播","男男性行为、静脉药瘾","慢性肝病（HBV/HCV/肝硬化）基础上重叠感染，重症风险升高","免疫抑制、HIV 感染与老年（>50 岁）"],"epi":"我国自 2008 年将甲肝疫苗纳入扩大国家免疫规划后，报告发病率已降至 1/10 万以下，但生食海产品引起的点状暴发仍时有发生。儿童多为隐性感染，成人感染症状较重；总病死率 0.1%–0.3%，>50 岁及慢性肝病者可升至 1%–2%。"},"patho":"病毒经口摄入后在肠道上皮与局部淋巴结复制，经门静脉入肝，在肝细胞胞质内复制。肝细胞损伤主要不是病毒直接毒性，而是 CD8⁺ T 细胞与 NK 细胞针对感染肝细胞的免疫应答所致，因此 ALT 升高程度与病毒载量不平行。病毒随胆汁排入肠道，粪便排毒在黄疸出现前 2 周达高峰、黄疸后 1 周迅速下降，故潜伏期末传染性最强。HAV 不整合入宿主基因组、不建立持续感染，因而无慢性化。","dx":{"criteria":["流行病学：潜伏期 15–45 天（平均 30 天），发病前 2–6 周有不洁饮食/饮水、生食贝类或甲肝患者接触史","临床：急性起病，发热、乏力、纳差、恶心、右上腹不适，继而尿色加深、巩膜黄染；部分病例无黄疸，儿童多隐性感染","生化：ALT、AST 显著升高（常 500–5000 U/L，ALT > AST），总胆红素升高（黄疸型多 17–171 μmol/L），ALP 与 GGT 轻度升高","病原学：抗-HAV IgM 阳性是诊断急性感染的核心依据，发病 4–6 周内检出率最高，可持续 3–6 个月；抗-HAV IgG 阳性提示既往感染或疫苗接种","HAV RNA（RT-PCR）在潜伏期末与急性期可检出，临床多数不需检测","排除其他病因：HBV、HDV、HEV、EBV、CMV、单纯疱疹病毒、药物性肝损伤、自身免疫性肝炎、胆道梗阻","重症判定：PTA <40% 或 INR ≥1.5 伴肝性脑病为急性肝衰竭；病程 >12 周且胆红素 >171 μmol/L、瘙痒、ALP/GGT 明显升高者为淤胆型"],"workup":["肝功能全套（ALT/AST/ALP/GGT/TBil/DBil/白蛋白）、PT/INR、血常规（白细胞正常或偏低、淋巴细胞相对增多）","抗-HAV IgM 与 IgG；必要时 HAV RNA","HBV 五项、抗-HCV、抗-HEV IgM、EBV/CMV 抗体，排除重叠感染","腹部超声：排除胆道梗阻、胆囊壁增厚（肝炎常见）与肝硬化","重症监测：PTA、血氨、乳酸、血糖、肾功能与电解质，每 12–24 h 复查","育龄女性查妊娠状态（影响戊型鉴别与用药）"],"grading":"临床分型：急性黄疸型、急性无黄疸型、淤胆型（胆红素 >171 μmol/L、瘙痒、ALP/GGT 显著升高、病程 >12 周）与重症型（急性肝衰竭）。按病程只有急性感染（<6 个月），无慢性型与肝硬化型。"},"ddx":[{"name":"戊型病毒性肝炎（gi_hev）","point":"与本类中戊型肝炎的鉴别点：两者临床与生化几乎相同、均粪口传播、均急性自限，只能靠病原学区分——抗-HAV IgM 阳性为甲型，抗-HEV IgM 或 HEV RNA 阳性为戊型；戊型有水源/生食猪肉流行病学、孕妇病死率高达 20%–25%、免疫抑制者可慢性化，甲型无这些特征。"},{"name":"丁型病毒性肝炎（gi_hdv）","point":"与本类中丁型肝炎的鉴别点：丁型必须 HBsAg 阳性，抗-HDV IgM 与 HDV RNA 阳性，且易慢性化与重症化；甲型 HBsAg 阴性、无慢性化。"},{"name":"乙型病毒性肝炎急性感染（hbv）","point":"急性乙肝 HBsAg 阳性、抗-HBc IgM 高滴度、HBV DNA 可测；甲肝 HBsAg 阴性、抗-HAV IgM 阳性。"},{"name":"药物性肝损伤（dili）","point":"有明确用药史（抗结核药、中草药、对乙酰氨基酚、抗生素），停药后肝功能改善，RUCAM 评分支持；病毒标志物阴性，嗜酸性粒细胞可升高。"},{"name":"EBV / CMV 肝炎","point":"伴发热、咽痛、淋巴结肿大与异型淋巴细胞 >10%，EBV-VCA IgM 或 CMV-DNA 阳性；ALT 升高幅度通常低于甲肝。"},{"name":"胆总管结石或梗阻性黄疸","point":"腹痛、寒战高热、黄疸（Charcot 三联征），ALP/GGT 与胆红素升高而 ALT 升高幅度小，超声或 MRCP 见胆管扩张与结石。"},{"name":"自身免疫性肝炎（gi_aih_pbc）","point":"女性多见、球蛋白与 IgG 升高、ANA/ASMA 阳性、IgG4 升高，肝活检见界面性肝炎；病毒学标志物阴性，激素治疗有效。"}],"tx":{"drug":[{"name":"对乙酰氨基酚（退热与止痛）","dose":"0.5 g 口服 q6h 按需，每日不超过 2 g；避免与酒精同服","note":"急性肝炎时肝脏代谢储备下降，尽量少用、短期用；总量 >4 g/日或酗酒者肝毒性显著增加。","renal":"CrCl <30 ml/min 延长给药间隔至 q8h","hepatic":"肝病者每日 ≤2 g；INR >1.5 或胆红素 >85 μmol/L 时避免使用","interact":"长期与华法林合用升高 INR；酒精、异烟肼、卡马西平诱导肝毒性"},{"name":"异甘草酸镁","dose":"100–150 mg 加入 5% 葡萄糖注射液 250 ml 静滴 qd，疗程 2–4 周","note":"抗炎保肝，可加速 ALT 下降；假性醛固酮增多症（低钾、高血压、水肿）需监测血钾与血压。","renal":"重度肾功能不全慎用","hepatic":"重度黄疸或肝硬化者减量","interact":"与利尿剂、糖皮质激素合用加重低钾；低钾时强心苷毒性增加"},{"name":"还原型谷胱甘肽","dose":"1.2–1.8 g 加入 5% 葡萄糖 250 ml 静滴 qd，疗程 2–4 周","note":"抗氧化与解毒辅助治疗，证据有限，不作为核心治疗。","renal":"遵说明书","hepatic":"遵说明书","interact":"不宜与维生素 B12、甲萘醌、泛酸钙混合静滴"},{"name":"腺苷蛋氨酸（淤胆型）","dose":"0.5–1.0 g 静滴 qd，或 500 mg 口服 bid，疗程 2–4 周","note":"用于胆汁淤积型（胆红素 >171 μmol/L、瘙痒、ALP/GGT 升高），可改善瘙痒与生化。","renal":"遵说明书","hepatic":"遵说明书","interact":"个案报道与 5-羟色胺能药物合用出现 5-HT 综合征，联合时观察"},{"name":"熊去氧胆酸（淤胆型）","dose":"10–15 mg/(kg·d) 分 2–3 次口服，疗程 4–12 周","note":"改善胆汁淤积与瘙痒；胆道完全梗阻者禁用。","renal":"遵说明书","hepatic":"严重肝病或胆道梗阻禁用","interact":"与考来烯胺等阴离子交换树脂间隔 4 h；可增加环孢素吸收"},{"name":"维生素 K1（凝血障碍）","dose":"10 mg 肌注 qd，至 PT 恢复正常或出血停止","note":"用于 PT 延长者，纠正肝细胞合成维生素 K 依赖凝血因子不足；肝衰竭时效果差，需输注血浆。","renal":"无需调整","hepatic":"无需调整","interact":"与头孢类抗生素合用可能减弱疗效；拮抗华法林抗凝作用"}],"nonDrug":["以支持治疗为主：卧床休息、足够热量（30–35 kcal/kg）、补液与电解质，恶心呕吐明显者静脉补充葡萄糖与维生素","暴露后预防：暴露后 2 周内接种甲肝疫苗（≥1 岁）；<1 岁、免疫抑制、慢性肝病或疫苗禁忌者予人免疫球蛋白 0.02 ml/kg 肌注","隔离：消化道隔离至发病后 3 周（黄疸出现后 2 周）；密切接触者医学观察 45 天；托幼机构与集体单位暴发时开展应急接种","献血管理：确诊甲肝者治愈后 6 个月内暂缓献血，按当地血站规定执行","急性肝衰竭（PTA <40% 或 INR ≥1.5 伴肝性脑病）：转有肝移植条件中心，评估人工肝与肝移植，禁用镇静药与肝毒性药物","胆道梗阻或继发细菌感染（胆管炎）时行 ERCP 或抗感染治疗"],"life":["禁酒至少 6 个月（至肝功能完全正常），避免肝毒性药物与不明成分保健品","出院后 2 周、1 个月、3 个月复查肝功能，直至 ALT 与胆红素正常","儿童 18 月龄接种甲肝减毒活疫苗（国家免疫规划）；成人高危人群（旅行、慢性肝病、MSM、静脉药瘾）接种灭活疫苗 2 剂（0、6 月）","治愈后获终身免疫，无需长期隔离；家庭成员出现类似症状应检测抗-HAV IgM"]},"prog":"急性自限性过程，80%–95% 患者在 3 个月内临床与生化痊愈，2–4 周症状明显缓解。无慢性化、无肝硬化与病毒携带状态。总病死率 0.1%–0.3%，>50 岁与慢性肝病基础者可升至 1%–2%；急性肝衰竭罕见（<1%），但一旦发生病死率高，需尽早转移植中心。","refs":["《甲型病毒性肝炎诊断标准》（WS 298—2008，卫生部）","中华医学会传染病与寄生虫病学分会、肝病学分会《病毒性肝炎防治方案》（2000 年，西安）","CDC/ACIP: Prevention of Hepatitis A Virus Infection in the United States — Recommendations of the Advisory Committee on Immunization Practices, 2020 (MMWR Recomm Rep 2020;69:1–38)","WHO: Hepatitis A vaccines — WHO position paper (2022)"]},{"id":"gi_hdv","name":"丁型病毒性肝炎","aka":["Hepatitis D","丁肝","HDV 感染","Delta hepatitis","Hepatitis delta virus"],"rank":2,"basic":{"define":"丁型肝炎病毒（HDV）是缺陷型负链 RNA 病毒，必须借助乙型肝炎表面抗原（HBsAg）作为包膜才能组装成完整病毒颗粒并感染肝细胞，因此仅感染 HBsAg 阳性者。与 HBV 同时感染称协同感染（coinfection），在慢性 HBV 感染基础上感染称重叠感染（superinfection），后者最易慢性化与重症化。","risk":["HBsAg 阳性者（尤其静脉药瘾、男男性行为、多性伴、透析与多次输血者）","HBV 高流行区出生或移民、HDV 高流行地区旅行","HIV 或 HCV 合并感染（HBV 复制增强、进展加快）","静脉药瘾共用注射器（我国 HDV 主要传播途径之一）","HBsAg 阳性母亲的新生儿（围产期传播少见但可发生）"],"epi":"全球 HDV 感染者估计约 1200 万–7000 万（不同模型差异大），我国 HBsAg 阳性人群中抗-HDV 阳性率多数报道 <1%，但静脉药瘾者、西部地区与透析人群明显更高。HDV 重叠感染是进展最快的病毒性肝炎形式之一，从感染到肝硬化可短至 5–10 年。"},"patho":"HDV 基因组为约 1.7 kb 的环状负链 RNA，复制依赖宿主 RNA 聚合酶 II。HDAg 有两种异构体：小 HDAg（S-HDAg）促进复制，大 HDAg（L-HDAg）抑制复制并借助异戊二烯化与 HBsAg 结合完成病毒装配。肝细胞损伤由病毒直接细胞毒作用与宿主免疫应答共同介导，因此 ALT 升高与病毒载量有一定相关性。重叠感染时，既有的抗-HBs 免疫记忆不能清除 HDV，70%–90% 转为慢性；慢性 HDV 以持续炎症、快速纤维化与高肝衰竭风险为特征。","dx":{"criteria":["诊断前提：HBsAg 阳性（或 HBV DNA 可检出）；所有 HBsAg 阳性者均应筛查抗-HDV，无论肝功能是否异常","抗体：抗-HDV 总抗体（IgG）阳性提示感染；抗-HDV IgM 阳性提示急性感染或慢性感染活动期；免疫抑制者可抗体阴性，须依靠 HDV RNA","病原学金标准：HDV RNA（RT-PCR）阳性，多数商品化试剂定量下限 10–100 IU/mL；治疗中每 3–6 个月复查","组织学：肝组织 HDAg 免疫组化阳性可确诊，适用于 RNA 检测不可及时","协同感染：与 HBV 同时感染，抗-HDV IgM 一过性阳性、HDV RNA 短暂可测，临床类似单纯急性乙肝（可呈双相 ALT 升高），>95% 自限，<5% 转为慢性","重叠感染：HBsAg 已阳性者新发急性肝炎（ALT 双峰、抗-HDV IgM 高滴度、HDV RNA 持续），70%–90% 转为慢性，约 5%–10% 发生急性或亚急性肝衰竭","慢性丁肝：HDV RNA 持续 >6 个月，伴 ALT 波动、血小板 <150×10⁹/L、白蛋白下降、肝硬度（LSM）>12 kPa；肝硬化者按 Child-Pugh 与 MELD 评估","重症判定：PTA <40% 或 INR ≥1.5 伴肝性脑病为急性肝衰竭；慢性者出现腹水、肝性脑病、消化道出血为失代偿"],"workup":["HBsAg、HBeAg、HBV DNA 定量；抗-HDV IgM 与 IgG；HDV RNA 定量（基线、治疗 12/24/48 周、停药后 24 周）","肝功能（ALT/AST/TBil/白蛋白）、PT/INR、血常规（血小板）、AFP","腹部超声与肝脏硬度（FibroScan）：LSM >12 kPa 提示肝硬化，>20 kPa 提示临床显著门脉高压","胃镜筛查食管静脉曲张（肝硬化者每 1–2 年，中高危者需一级预防）","肝活检：病因不明或需评估纤维化时，组织查 HDAg、炎症分级与纤维化分期","HIV、HCV 筛查；HCC 监测每 6 个月超声 ± AFP；评估肝移植指征"],"grading":"按病程分急性（协同感染、重叠感染）与慢性（>6 个月）；按纤维化分 Metavir F0–F4 或 Ishak 分期；按肝功能分代偿与失代偿。抗病毒应答定义：HDV RNA 较基线下降 ≥2 log₁₀ 为部分应答，降至检测下限以下为完全应答；ALT 复常为生化应答。"},"ddx":[{"name":"甲型病毒性肝炎（gi_hav）","point":"与本类中甲型肝炎的鉴别点：甲型 HBsAg 阴性、抗-HAV IgM 阳性、无慢性化；丁型必须 HBsAg 阳性且抗-HDV IgM/HDV RNA 阳性，易慢性化并快速进展为肝硬化。"},{"name":"戊型病毒性肝炎（gi_hev）","point":"与本类中戊型肝炎的鉴别点：戊型抗-HEV IgM 或 HEV RNA 阳性、HBsAg 阴性、粪口传播；丁型经血与性传播、需 HBsAg 共存。免疫抑制者两者均可慢性化，但戊型用利巴韦林、丁型用干扰素。"},{"name":"慢性乙型肝炎（hbv）","point":"单纯慢性乙肝 HBV DNA 高、HBeAg 状态决定复制活跃度，ALT 波动与 DNA 平行，抗-HDV 阴性；合并 HDV 时 ALT 升高与 HBV DNA 水平不平行，且进展更快。"},{"name":"丙型病毒性肝炎（gi_hcv）","point":"抗-HCV 与 HCV RNA 阳性，可直接抗病毒治愈（DAA 方案 8–12 周，SVR >95%）；HDV 无 DAA 可用。"},{"name":"药物性肝损伤（dili）","point":"有明确用药史、停药后改善、RUCAM 评分支持，病毒标志物阴性；合并 HDV 者用药后 ALT 升高易被误判为 DILI，需查 HDV RNA。"},{"name":"自身免疫性肝病（gi_aih_pbc）","point":"AIH 以 ANA/ASMA 阳性、IgG 升高、界面性肝炎为特征；PBC 以 AMA 阳性、ALP/GGT 升高与胆管破坏为主；病毒学阴性、激素或熊去氧胆酸有效。"},{"name":"酒精性肝病（gi_ald）","point":"长期大量饮酒史（男 >40 g/d、女 >20 g/d 持续 5 年），AST/ALT >2、GGT 显著升高、MCV 增大；戒酒后改善，病毒标志物阴性。"}],"tx":{"drug":[{"name":"聚乙二醇干扰素 α-2a","dose":"180 μg 皮下注射 qw（或 PEG-IFN α-2b 1.5 μg/kg qw），疗程 48 周，可延长至 96 周","note":"目前证据最充分的抗 HDV 治疗，48 周疗程结束时 HDV RNA 转阴约 25%–30%，停药 24 周复发常见需继续随访；禁用于失代偿肝硬化、自身免疫病、妊娠、严重抑郁、中性粒细胞 <1.0×10⁹/L 或血小板 <50×10⁹/L。","renal":"CrCl <30 ml/min 慎用并减量，遵说明书","hepatic":"失代偿肝硬化（Child-Pugh B/C）禁用","interact":"与利巴韦林合用增加溶血与骨髓抑制；与茶碱、美沙酮等 CYP1A2 底物合用需监测浓度"},{"name":"布勒韦肽（Bulevirtide）","dose":"2 mg 皮下注射 qd；应答不佳可增至 10 mg qd（EMA 有条件批准，我国尚未上市）","note":"HBV/HDV 进入抑制剂（NTCP 抑制剂），可单用或联合 PEG-IFN；常见无症状胆汁酸升高（可达 60%），一般无需停药；失代偿肝硬化不推荐。","renal":"重度肾功能不全资料有限，遵说明书","hepatic":"失代偿肝硬化不推荐使用","interact":"与 OATP1B1/1B3 底物（他汀、利福平、环孢素）合用可升高后者浓度，需监测"},{"name":"恩替卡韦","dose":"0.5 mg 口服 qd（空腹，餐前或餐后 2 h）；拉米夫定耐药者 1 mg qd","note":"强效抑制 HBV DNA，对 HDV 无直接作用；HBV DNA 可检出者均应使用，以降低肝硬化与 HCC 风险，但不能替代抗 HDV 治疗。","renal":"CrCl 30–49 ml/min 每 48 h 1 次；10–29 每 72 h 1 次；<10 或透析每 7 天 1 次","hepatic":"无需调整","interact":"与食物同服降低吸收；与其他经肾小管分泌药物合用可升高血药浓度"},{"name":"富马酸替诺福韦二吡呋酯（TDF）","dose":"300 mg 口服 qd","note":"强效抑制 HBV DNA；注意肾小管损伤与骨密度下降，避免与高剂量 NSAID 或氨基糖苷类叠加。","renal":"CrCl 30–49 每 48 h 1 次；10–29 每 72–96 h 1 次；<10 或透析按说明书","hepatic":"无需调整","interact":"升高去羟肌苷浓度（禁忌联用）；与 NSAID、氨基糖苷类合用增加肾毒性"},{"name":"丙酚替诺福韦（TAF）","dose":"25 mg 口服 qd，随餐服用","note":"骨与肾安全性优于 TDF，适合骨质疏松或肾功能轻度受损者。","renal":"CrCl <15 ml/min 或透析者不推荐（资料有限）","hepatic":"Child-Pugh B/C 无需调整","interact":"与 P-gp 强诱导剂（利福平、卡马西平、苯妥英钠）合用降低血药浓度"},{"name":"反义寡核苷酸（研究性）","dose":"按临床试验方案给药（尚未获批，非常规用药）","note":"反义寡核苷酸（ASO）与 siRNA（如 elebsiran 联合 tobevibart）通过降低 HBsAg 与 HDV RNA 发挥作用，目前处于Ⅱ–Ⅲ期临床研究，仅推荐入组临床试验，不作为常规治疗。","renal":"不适用（研究阶段）","hepatic":"不适用（研究阶段）","interact":"不适用（研究阶段）"},{"name":"人血白蛋白 / 新鲜冰冻血浆（肝衰竭支持）","dose":"白蛋白 10–20 g 静滴 qd–qod（目标白蛋白 >30 g/L）；血浆 10–15 ml/kg 用于凝血障碍伴出血或侵入操作前","note":"失代偿或慢加急性肝衰竭的支持治疗，不能改善 HDV 感染本身；容量负荷过重者慎用白蛋白。","renal":"肾功能不全者注意容量与钠负荷","hepatic":"遵说明书","interact":"无特殊"}],"nonDrug":["所有 HBsAg 阳性者常规筛查抗-HDV——漏诊是当前最大问题，EASL 2023 将其列为强推荐","乙型肝炎疫苗：HDV 阴性家庭成员与性伴侣接种；HDV 本身无疫苗，预防依赖阻断 HBV 传播","失代偿肝硬化或慢加急性肝衰竭：评估肝移植；移植后长期乙肝免疫球蛋白（HBIG）联合核苷（酸）类似物预防再感染","肝硬化者每 6 个月超声 ± AFP 筛查 HCC；胃镜筛查静脉曲张，中高危者用普萘洛尔/卡维地洛或套扎行一级预防","避免饮酒、肝毒性药物与不必要免疫抑制（免疫抑制可加速 HDV 复制）","优先推荐入组临床试验（bulevirtide、siRNA/ASO 联合方案）"],"life":["严格戒酒，避免肝毒性中草药与保健品","每 3–6 个月复查肝功能、HDV RNA、HBV DNA、血常规、AFP 与腹部超声","干扰素治疗期间每月监测血常规与甲状腺功能，每 3 个月用 PHQ-9 评估抑郁","干扰素有流产风险，治疗期间及停药后 6 个月严格避孕","家庭成员与性伴侣筛查 HBsAg 并接种乙肝疫苗；不共用剃须刀、牙刷与注射器"]},"prog":"慢性丁型肝炎是进展最快的病毒性肝炎之一，5–10 年内约 30%–50% 进展为肝硬化，一旦失代偿 5 年生存率不足 50%。重叠感染较协同感染预后差，且可诱发急性或亚急性肝衰竭。PEG-IFN 可使约 1/4–1/3 患者获得 HDV RNA 持续转阴，bulevirtide 等新药可改善生化与纤维化，但根治仍困难，肝移植是终末期唯一治愈手段。","refs":["EASL Clinical Practice Guidelines on hepatitis delta virus (2023, Journal of Hepatology)","《慢性乙型肝炎防治指南（2022 年版）》（中华医学会感染病学分会、肝病学分会）","AASLD Guidance: Hepatitis B (2018)","WHO: Guidelines for the prevention, care and treatment of persons with chronic hepatitis B infection (2015)"]},{"id":"gi_hev","name":"戊型病毒性肝炎","aka":["Hepatitis E","戊肝","HEV 感染","肠道传播的非甲非乙型肝炎"],"rank":3,"basic":{"define":"戊型肝炎病毒（HEV，正链 RNA 病毒）经粪口途径（水源、食物）传播引起的急性肝脏炎症。基因 1、2 型仅感染人、经水源暴发；基因 3、4 型为人畜共患（猪为主要宿主），我国散发病例以基因 4 型为主。孕妇感染基因 1 型病死率高达 20%–25%，免疫抑制者可发展为慢性戊肝。","risk":["饮用被污染的水源、生食或半生食猪肉及其内脏（HEV-3/4）","戊肝流行区旅行或居住、洪涝灾害后水源污染","孕妇（尤其妊娠晚期，HEV-1 感染病死率 20%–25%）","慢性肝病基础（HBV/HCV/肝硬化、酒精性肝病），重叠感染易重症","免疫抑制：实体器官移植、造血干细胞移植、血液肿瘤化疗、HIV 感染（CD4 <200/μl）","老年男性（我国散发病例以中老年男性为主）"],"epi":"我国为戊肝高流行区，急性散发性病毒性肝炎中戊肝占比逐年上升，部分年份超过甲肝；基因 4 型为优势株，与生食猪肉制品相关。孕妇 HEV-1 感染病死率 20%–25%；实体器官移植受者感染 HEV-3 后慢性化率约 60%–80%。"},"patho":"HEV 经肠道吸收后经门静脉入肝，在肝细胞胞质内复制并释放病毒颗粒。基因 1/2 型引起急性自限性肝炎，肝损伤由病毒直接作用与细胞免疫共同介导；基因 3/4 型在免疫功能正常者多为无症状或轻型感染，但在免疫抑制者（T 细胞应答不足）可建立持续感染，HEV RNA 持续 >6 个月即慢性戊肝，进而快速纤维化。孕妇重症与激素水平、免疫偏移及病毒复制增强有关，可发生急性肝衰竭与产后出血。肝外表现包括神经型（Guillain-Barré 综合征、神经痛性肌萎缩）、肾小球肾炎、胰腺炎与溶血性贫血。","dx":{"criteria":["流行病学：潜伏期 15–60 天（平均 40 天），发病前 2–9 周有不洁饮水、生食猪肉或内脏、流行区旅行史","临床：急性起病，乏力、纳差、恶心、腹痛、低热，继而黄疸、尿色加深；淤胆型常见（瘙痒、陶土便、病程 >3 个月）","生化：ALT、AST 升高（常 200–2000 U/L），总胆红素升高；重型者胆红素 >171 μmol/L 且 PTA <40%","病原学：抗-HEV IgM 阳性提示急性感染（发病早期出现，可持续约 6 个月）；抗-HEV IgG 4 倍以上升高有诊断价值；免疫抑制者抗体常阴性","HEV RNA（RT-PCR）阳性是确诊与疗效监测的关键，免疫抑制或疑似慢性者必查","慢性戊肝：免疫抑制者 HEV RNA 持续 >6 个月，伴 ALT 波动与肝纤维化进展","排除其他病因：HAV、HBV、HCV、HDV、EBV/CMV、药物性肝损伤、自身免疫性肝炎、胆道梗阻、缺血性肝病","重症与肝外表现：PTA <40% 或 INR ≥1.5 伴肝性脑病为急性肝衰竭；注意神经症状、肾损害与血小板减少"],"workup":["肝功能全套、PT/INR、血常规、肾功能与电解质","抗-HEV IgM 与 IgG；免疫抑制、疑似慢性或抗体阴性者查 HEV RNA（定量）","HBV 五项、抗-HAV IgM、抗-HCV、EBV/CMV 抗体，排除重叠感染","腹部超声：排除胆道梗阻，评估肝硬化与腹水；必要时肝脏硬度测定","免疫抑制评估：移植史、化疗方案、HIV 状态与 CD4 计数","育龄女性查妊娠状态与孕周；孕妇每 48–72 h 监测 PTA 与胆红素"],"grading":"临床分型：急性黄疸型、急性无黄疸型、淤胆型（胆红素 >171 μmol/L、瘙痒、ALP/GGT 升高、病程 >3 个月）、重症型（急性肝衰竭）与慢性型（仅见于免疫抑制者，HEV RNA >6 个月）。基因型：1/2 型人源水源传播，3/4 型人畜共患。"},"ddx":[{"name":"甲型病毒性肝炎（gi_hav）","point":"与本类中甲型肝炎的鉴别点：两者临床与生化高度相似，靠病原学区分（抗-HEV IgM/HEV RNA  vs 抗-HAV IgM）；戊型有水源与生食猪肉流行病学、孕妇病死率高、免疫抑制者可慢性化，甲型无慢性化且疫苗保护明确。"},{"name":"丁型病毒性肝炎（gi_hdv）","point":"与本类中丁型肝炎的鉴别点：丁型需 HBsAg 阳性、经血/性传播、抗-HDV IgM 与 HDV RNA 阳性；戊型 HBsAg 阴性、粪口传播。"},{"name":"药物性肝损伤（dili）","point":"有明确用药史（抗结核药、中草药、抗生素、对乙酰氨基酚），停药后肝功能改善，RUCAM 评分支持，病毒标志物阴性；戊肝抗体或 RNA 阳性可排除。"},{"name":"EBV / CMV 肝炎","point":"发热、咽痛、淋巴结肿大、异型淋巴细胞 >10%，EBV-VCA IgM 或 CMV-DNA 阳性；ALT 升高幅度通常低于戊肝。"},{"name":"胆总管结石与急性胆管炎","point":"Charcot 三联征（腹痛、寒战高热、黄疸），ALP/GGT 显著升高而 ALT 升高幅度小，超声或 MRCP 见胆管扩张与结石。"},{"name":"自身免疫性肝炎（gi_aih_pbc）","point":"女性多见，IgG 与球蛋白升高、ANA/ASMA 阳性、肝活检见界面性肝炎；病毒学阴性，激素治疗有效。"},{"name":"妊娠期急性脂肪肝 / HELLP 综合征","point":"妊娠晚期出现恶心呕吐、右上腹痛、低血糖、血小板 <100×10⁹/L、LDH 升高、尿酸升高与凝血障碍，影像见脂肪肝；抗-HEV IgM/RNA 阴性，需产科急诊处理。"}],"tx":{"drug":[{"name":"利巴韦林（慢性戊肝）","dose":"600–800 mg/日 口服，分 2–3 次（按体重 15 mg/kg/日左右），疗程 12 周；12 周未转阴可延长至 24 周","note":"慢性戊肝（免疫抑制者 HEV RNA >6 个月）的一线治疗，停药后需监测复发；主要不良反应为溶血性贫血（Hb 下降 1–2 g/L 常见），治疗前查 G6PD；妊娠禁用（致畸）。","renal":"CrCl <50 ml/min 减量，遵说明书","hepatic":"失代偿肝硬化慎用（溶血加重肝损伤）","interact":"与硫唑嘌呤合用增加 6-甲基巯基嘌呤蓄积，骨髓抑制风险升高；与去羟肌苷合用可致乳酸酸中毒（禁忌）"},{"name":"聚乙二醇干扰素 α-2a（二线）","dose":"135–180 μg 皮下注射 qw，疗程 3–12 个月（病例系列剂量，循证证据有限）","note":"仅用于利巴韦林不耐受或治疗失败者；器官移植受者慎用（可诱发排斥与自身免疫），需与移植科共同决策。","renal":"CrCl <30 ml/min 减量，遵说明书","hepatic":"失代偿肝硬化禁用","interact":"与利巴韦林合用增加溶血与骨髓抑制"},{"name":"熊去氧胆酸（淤胆型）","dose":"10–15 mg/(kg·d) 分 2–3 次口服，疗程 4–12 周","note":"改善胆汁淤积型戊肝的瘙痒与生化指标；胆道完全梗阻者禁用。","renal":"遵说明书","hepatic":"严重肝病或胆道梗阻禁用","interact":"与考来烯胺间隔 4 h；可增加环孢素吸收"},{"name":"腺苷蛋氨酸（淤胆型）","dose":"0.5–1.0 g 静滴 qd 或 500 mg 口服 bid，疗程 2–4 周","note":"用于胆红素 >171 μmol/L、瘙痒明显的淤胆型患者。","renal":"遵说明书","hepatic":"遵说明书","interact":"与 5-羟色胺能药物合用需观察（个案 5-HT 综合征）"},{"name":"维生素 K1（凝血障碍）","dose":"10 mg 肌注 qd，至 PT 恢复或出血停止","note":"用于 PT 延长者；急性肝衰竭时合成功能严重受损，需输注新鲜冰冻血浆。","renal":"无需调整","hepatic":"无需调整","interact":"拮抗华法林；与头孢类合用可能减弱疗效"},{"name":"人血白蛋白（重症支持）","dose":"10–20 g 静滴 qd–qod，目标白蛋白 >30 g/L","note":"用于合并腹水或明显低白蛋白血症者；容量负荷过重、心功能不全者慎用。","renal":"注意钠水负荷","hepatic":"遵说明书","interact":"无特殊"}],"nonDrug":["急性戊肝以支持治疗为主，禁用利巴韦林（无证据且孕妇禁用）；补液、纠正电解质、必要时静脉营养","免疫抑制者慢性戊肝：先减少免疫抑制剂 20%–30%（与移植科协作），可使约 1/3 患者自行清除病毒，再考虑利巴韦林","孕妇感染：48–72 h 内评估 PTA、胆红素与血糖，尽早转有产科与肝移植条件的中心；终止妊娠时机由产科与家属共同决定","急性肝衰竭：转肝移植中心，评估人工肝与肝移植；禁用镇静药与肝毒性药物","供水与食品安全：流行区煮沸饮水、避免生食猪肉与内脏；集体单位暴发时开展卫生宣教与水源消毒","疫苗：重组戊肝疫苗（HEV 239，我国批准 ≥16 岁）0、1、6 月三剂，Ⅲ期试验保护率约 95%，用于高危人群（孕妇家属、慢性肝病、旅行者、献血者）"],"life":["禁酒 6 个月至肝功能正常；避免肝毒性药物与保健品","避免生食猪肉、内脏与贝类，饮用煮沸水；孕妇避免前往戊肝流行区","免疫抑制者每 3–6 个月监测 HEV RNA 与肝功能，尤其移植后与化疗期间","急性期隔离至发病后 3 周（粪口传播），密切接触者医学观察 60 天","治愈后复查肝功能至正常；慢性戊肝停药后每 3 个月复查 HEV RNA 至少 6 个月"]},"prog":"免疫功能正常者多为急性自限性过程，4–6 周临床恢复，病死率 0.2%–4%。孕妇感染 HEV-1 病死率 20%–25%，妊娠晚期最高，可发生急性肝衰竭、产后出血与死胎。免疫抑制者 60%–80% 转为慢性，其中约 10%–30% 在 2–5 年内进展为肝硬化；利巴韦林停药后复发常见，需长期随访 HEV RNA。","refs":["《戊型肝炎防治共识》（中华医学会肝病学分会，2022，中华肝脏病杂志 2022;30(8):820–831）","《戊型病毒性肝炎诊断标准》（WS 301—2008，卫生部）","《戊型病毒性肝炎诊疗规范》（中国医师协会感染科医师分会，2009）","EASL Clinical Practice Guidelines on hepatitis E virus infection (2018, Journal of Hepatology)","WHO: Hepatitis E vaccine — WHO position paper (2015)"]}]}]},"heme":{"categories":[{"id":"anemia","name":"贫血","rank":1,"summary":"按 MCV 与网织红细胞把贫血分为小细胞、正细胞、大细胞三类，再查铁代谢、叶酸/B12、骨髓与溶血指标；缺铁先补铁并找失血灶，巨幼贫补叶酸/B12 并警惕神经损害，再障以移植或免疫抑制为主。","compare":[{"diseaseId":"ida","dx":"小细胞低色素：Hb 降低、MCV <80 fL、MCH <27 pg，血清铁蛋白 <30 μg/L、转铁蛋白饱和度 <20%，补铁后网织红细胞上升","key":"小细胞低色素 + 铁蛋白降低；必须寻找慢性失血灶（消化道、月经量）"},{"diseaseId":"ma","dx":"大细胞性：MCV >100 fL，中性粒细胞核分叶过多，B12 或叶酸降低，骨髓巨幼样变；B12 缺乏可伴神经症状","key":"大细胞 + 核右移、舌炎或神经症状；B12 缺乏不得单用叶酸以免掩盖神经损害"},{"diseaseId":"aa","dx":"全血细胞减少（至少两系），网织红细胞绝对值 <40×10⁹/L，骨髓增生减低、脂肪化，无肝脾肿大与异常细胞","key":"全血细胞减少 + 网织红细胞低 + 骨髓空虚，脾不大；需先排除 PNH、MDS、白血病"}],"diseases":[{"id":"ida","name":"缺铁性贫血","aka":["IDA","Iron Deficiency Anemia"],"rank":1,"basic":{"define":"体内贮存铁耗尽导致血红蛋白合成不足的贫血，呈小细胞低色素性；须明确铁缺乏原因（慢性失血、摄入不足、吸收障碍、需求增加）。","risk":["育龄期女性月经过多、妊娠与哺乳期","婴幼儿与青春期铁需求增加","消化道慢性失血：溃疡、痔疮、消化道肿瘤、服用 NSAIDs 或阿司匹林","胃切除术后、萎缩性胃炎、幽门螺杆菌感染、慢性腹泻致吸收障碍","素食、长期饮浓茶、血液透析者铁丢失增加","男性和绝经后女性缺铁需警惕消化道肿瘤"],"epi":"全球约 1/3 人口存在铁缺乏；我国孕妇患病率约 10%–20%，婴幼儿与老年人高发。"},"patho":"贮存铁耗竭（铁蛋白先降）→ 血清铁与转铁蛋白饱和度降低 → 骨髓幼红细胞胞浆减少、体积变小，形成小细胞低色素性红细胞，网织红细胞不增高。长期缺铁可致舌炎、反甲与异食癖。","dx":{"criteria":["Hb 低于参考值下限：成年男性 <130 g/L，成年非妊娠女性 <120 g/L，妊娠女性 <110 g/L","小细胞低色素：MCV <80 fL，MCH <27 pg，MCHC <320 g/L","血清铁蛋白 <30 μg/L 提示贮存铁缺乏，<15 μg/L 可确诊；铁蛋白 30–100 μg/L 伴炎症时结合转铁蛋白饱和度 <20% 判断","血清铁降低、总铁结合力升高、转铁蛋白饱和度 <20%","诊断性治疗：足量口服铁剂后 2–4 周 Hb 上升 ≥10 g/L，网织红细胞 5–10 天上升","sTfR 升高，sTfR/Log 铁蛋白指数有助与慢性病贫血鉴别"],"workup":["血常规 + 网织红细胞 + 外周血涂片（红细胞大小不均、中心淡染区扩大）","血清铁、总铁结合力、转铁蛋白饱和度、血清铁蛋白","CRP：炎症时铁蛋白作为急性期反应物升高，需校正判读","粪隐血 + 月经量问诊；男性及绝经后女性建议胃肠镜","育龄女性妇科检查与超声；反复献血者、透析患者评估铁丢失"],"grading":"按 Hb 分度：轻度 正常下限–90 g/L；中度 60–90 g/L；重度 30–60 g/L；极重度 <30 g/L。按病因分摄入不足、需求增加、吸收障碍、慢性失血型。"},"ddx":[{"name":"巨幼细胞性贫血（ma）","point":"与本类 ma 的鉴别点：IDA 为小细胞低色素、铁蛋白低；巨幼贫为大细胞、中性粒细胞核分叶过多、B12/叶酸降低，可伴神经症状。"},{"name":"再生障碍性贫血（aa）","point":"与本类 aa 的鉴别点：IDA 为单纯贫血、骨髓红系增生活跃伴细胞左移；再障为全血细胞减少、网织红细胞绝对值显著降低、骨髓空虚。"},{"name":"慢性病贫血","point":"铁蛋白正常或升高（≥100 μg/L）、转铁蛋白饱和度正常偏低、sTfR 不升高，伴慢性感染、肿瘤、类风湿等基础病，补铁无效。"},{"name":"地中海贫血（轻型）","point":"小细胞但铁蛋白正常或升高、靶形红细胞、HbA2 升高；误用铁剂可致铁过载。"},{"name":"铁粒幼细胞性贫血","point":"铁蛋白与转铁蛋白饱和度升高，骨髓环形铁粒幼细胞 ≥15%，补铁无效。"}],"tx":{"drug":[{"name":"口服铁剂（硫酸亚铁/琥珀酸亚铁/多糖铁复合物）","dose":"元素铁 100–200 mg/d，成人可一日 1 次或隔日 1 次给药，餐前 1 h 或两餐间服；Hb 恢复后继续补铁 3–6 个月补足贮存铁（或至铁蛋白 >50 μg/L）","note":"餐后服可减轻胃肠道反应但吸收下降；避免与浓茶、咖啡、钙剂、抗酸药同服；治疗 2–4 周 Hb 应上升 ≥10 g/L","renal":"慢性肾脏病者口服吸收差，常需静脉铁，遵说明书","hepatic":"遵说明书；严重肝病伴铁过载者慎用","interact":"减低左甲状腺素、四环素类、氟喹诺酮、双膦酸盐吸收，间隔 2 h 以上"},{"name":"静脉铁剂（蔗糖铁/羧基麦芽糖铁/异麦芽糖酐铁）","dose":"按 Ganzoni 公式（体重 kg×(目标 Hb−实际 Hb)g/L×0.24 + 贮存铁 500 mg）计算总缺铁量，分次输注；单次上限与速率遵各自说明书","note":"口服无效、不耐受或需快速纠正者适用；首次输注缓慢并观察 30 min；禁用于铁过载、活动性感染、首孕三月","renal":"慢性肾脏病非透析、血液透析与腹膜透析均可使用，遵说明书","hepatic":"Child-Pugh B/C 慎用，遵说明书","interact":"避免与口服铁剂同期使用；不可与其他静脉药物同瓶混合"}],"nonDrug":["病因治疗：溃疡与幽门螺杆菌根除、痔疮处理、评估后停用致出血药物","月经过多：可用左炔诺孕酮宫内节育器或氨甲环酸，必要时手术","男性及绝经后女性应行胃肠镜排除消化道肿瘤","饮食：红肉、动物肝脏、血制品；避免大量浓茶与咖啡","Hb <60 g/L 或症状明显者输注浓缩红细胞，目标 Hb 70–80 g/L（老年、心血管病可放宽至 80–100 g/L）"],"life":["疗程结束后复查血常规与铁蛋白，确认贮存铁恢复","妊娠期按指南预防性补铁","长期服 NSAIDs 或抗血小板药者定期查粪隐血与血常规","忌自行长期大剂量服铁，以免铁过载"]},"prog":"去除病因并补足铁后多数完全纠正，Hb 于 4–8 周恢复正常。未找到失血灶者有漏诊消化道肿瘤风险；反复复发提示失血持续或吸收障碍。","refs":["中华医学会血液学分会红细胞疾病（贫血）学组. 铁缺乏症和缺铁性贫血诊治和预防多学科专家共识（2018）","中华医学会围产医学分会. 妊娠期铁缺乏和缺铁性贫血诊治指南（2014）","World Health Organization. Guideline on haemoglobin cutoffs to define anaemia (2024)"]},{"id":"ma","name":"巨幼细胞性贫血","aka":["Megaloblastic Anemia","维生素B12/叶酸缺乏性贫血"],"rank":2,"basic":{"define":"因维生素 B12 和/或叶酸缺乏致 DNA 合成障碍、骨髓出现巨幼样变的大细胞性贫血；B12 缺乏可同时累及神经系统（亚急性联合变性）。","risk":["老年人萎缩性胃炎、内因子缺乏（恶性贫血）、胃切除术后","长期严格素食者","回肠末端切除、克罗恩病、小肠细菌过度生长、阔节裂头绦虫感染","妊娠、哺乳、慢性溶血、血液透析等叶酸需求增加状态","长期服用甲氨蝶呤、苯妥英钠、复方新诺明、二甲双胍、质子泵抑制剂","酗酒、营养摄入不足"],"epi":"我国以叶酸缺乏为主；老年住院患者 B12 缺乏比例可达 10%–20%，长期服二甲双胍者风险升高。"},"patho":"叶酸缺乏使 dTMP 合成受阻、DNA 复制迟缓，核质发育不同步形成巨幼样变；B12 缺乏致甲基四氢叶酸「陷阱」与髓鞘合成障碍，出现脊髓后索/侧索与周围神经损害。无效造血致 LDH 升高与轻度黄疸。","dx":{"criteria":["Hb 降低，MCV 通常 >100 fL（常 110–140 fL），红细胞大小不均明显","中性粒细胞核分叶过多（5 叶 ≥5% 或见 6 叶以上），可见大卵圆形红细胞","常伴白细胞与血小板减少，LDH 升高、间接胆红素升高、网织红细胞偏低","血清 B12 <150 pmol/L 或叶酸 <6.8 nmol/L；B12 临界区（200–300 pg/mL）查甲基丙二酸与同型半胱氨酸","骨髓增生活跃、各系巨幼样变（巨幼红细胞、巨核细胞分叶过多），治疗前尽量完成","内因子抗体、胃壁细胞抗体阳性支持恶性贫血"],"workup":["血常规 + 网织红细胞 + 外周血涂片（重点看中性粒细胞核形态）","血清 B12、叶酸、同型半胱氨酸、甲基丙二酸","LDH、间接胆红素、结合珠蛋白，排除溶血","骨髓穿刺 + 活检（疑诊且无禁忌时）","内因子抗体、抗胃壁细胞抗体、胃镜","神经系统查体与脊髓 MRI（后索「倒 V 征」）、肌电图","治疗前留取标本，补充后血清水平与骨髓形态可迅速假性正常"],"grading":"分度同贫血标准。病因分型：B12 缺乏型（恶性贫血、摄入/吸收障碍）、叶酸缺乏型、药物干扰型、混合型。"},"ddx":[{"name":"缺铁性贫血（ida）","point":"与本类 ida 的鉴别点：巨幼贫为大细胞、核分叶过多、LDH 升高、B12/叶酸降低；IDA 为小细胞低色素、铁蛋白降低，两者亦可并存。"},{"name":"再生障碍性贫血（aa）","point":"与本类 aa 的鉴别点：两者均可全血细胞减少，但巨幼贫骨髓增生活跃伴巨幼样变、MCV 与 LDH 升高；再障骨髓空虚、网织红细胞低。"},{"name":"骨髓增生异常综合征（MDS）","point":"大细胞贫血与全血细胞减少相似，但 MDS 骨髓有病态造血与细胞遗传学异常，叶酸/B12 正常、补充无效。"},{"name":"酒精性肝病或甲减所致大细胞贫血","point":"叶酸/B12 正常，补充无效，随原发病改善而纠正。"},{"name":"药物相关大红细胞症（羟基脲、甲氨蝶呤、齐多夫定）","point":"用药史明确，常伴网织红细胞增多，停药或减量后恢复。"}],"tx":{"drug":[{"name":"维生素 B12（氰钴胺/甲钴胺）","dose":"无神经症状：肌注 100 μg 每日 1 次×2 周，后每周 1 次×4 周；有神经症状：肌注 1000 μg 每日 1 次×2 周，后每周 1 次×4 周，再每月 1 次终身维持；口服替代 1000 μg qd","note":"治疗 48–72 h 网织红细胞上升；治疗初期监测血钾","renal":"遵说明书；血液透析者需常规补充","hepatic":"遵说明书","interact":"大剂量维生素 C 同服可使 B12 失活；氯霉素、甲氨蝶呤可拮抗"},{"name":"叶酸","dose":"5 mg qd 口服，2–4 周血象恢复，疗程 3–6 个月或至病因去除；吸收不良者 5 mg tid","note":"未排除 B12 缺乏时单用叶酸可掩盖贫血但加重神经损害，须先查 B12","renal":"遵说明书","hepatic":"遵说明书","interact":"甲氨蝶呤、乙胺嘧啶、甲氧苄啶为叶酸拮抗剂，需亚叶酸钙解救"},{"name":"氯化钾（按需）","dose":"治疗初期出现低钾时按血钾水平补钾，口服或静脉，遵说明书","note":"重症巨幼贫造血恢复期血钾可骤降，需监测","renal":"肾功能不全者慎用","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB 合用注意高钾"}],"nonDrug":["纠正病因：萎缩性胃炎处理、幽门螺杆菌根除、小肠病变治疗、停用干扰药物、戒酒","严重贫血伴心血管失代偿者缓慢输注浓缩红细胞，观察血钾与心功能","合并缺铁时同时补铁","孕期与哺乳期按指南补充叶酸预防"],"life":["恶性贫血者终身 B12 维持，每 3–6 个月复查血常规","素食者长期 B12 补充","长期二甲双胍、PPI 使用者定期筛查 B12","戒烟限酒，均衡饮食"]},"prog":"补充后 4–8 周血象恢复，神经症状多在 6–12 个月内改善，但病程长的脊髓后索损害可遗留。恶性贫血需终身补充；未及时纠正可致不可逆神经损害。","refs":["中华医学会血液学分会红细胞疾病（贫血）学组. 巨幼细胞性贫血诊断与治疗专家共识","中华医学会消化病学分会. 慢性胃炎共识意见（2017，上海）","Devalia V, et al. Guidelines for the diagnosis and treatment of cobalamin and folate disorders. Br J Haematol 2014"]},{"id":"aa","name":"再生障碍性贫血","aka":["AA","再障","Aplastic Anemia"],"rank":3,"basic":{"define":"由免疫介导的骨髓造血干/祖细胞损伤导致骨髓衰竭，以全血细胞减少（至少两系）、骨髓增生减低、无肝脾肿大及无异常细胞浸润为特征；重型（SAA）需尽早免疫抑制或移植。","risk":["病毒感染：肝炎病毒、EBV/CMV、细小病毒 B19、HIV","药物与毒物：氯霉素、保泰松、抗甲状腺药、化疗药、苯及有机溶剂","电离辐射","自身免疫病与妊娠相关","约 70% 无明显诱因，为特发性免疫介导"],"epi":"我国再障年发病率约 0.74/10 万，东亚国家高于欧美；发病呈双峰分布（10–25 岁与 >60 岁）。"},"patho":"T 淋巴细胞（Th1/CTL）克隆性活化攻击造血干/祖细胞，伴 IFN-γ、TNF-α 过度表达，导致骨髓空泡化、无效造血。少数由药物毒性或病毒引起，后期可演变为 MDS、AML 或 PNH。","dx":{"criteria":["全血细胞减少，至少两系：Hb <100 g/L、中性粒细胞 <1.5×10⁹/L、血小板 <50×10⁹/L","网织红细胞绝对值 <40×10⁹/L（或纠正后 <1%）","骨髓涂片示增生减低，粒、红、巨核三系减少，非造血细胞比例增高","骨髓活检示造血组织 <30%（一般 <25%）、脂肪化，无明显纤维化","无肝脾淋巴结肿大，无异常细胞浸润","重型（SAA）：骨髓细胞 <25%，或 25%–50% 但残存造血 <30%；且中性粒细胞 <0.5×10⁹/L、血小板 <20×10⁹/L、网织红细胞 <20×10⁹/L 三项中满足两项；极重型（VSAA）为中性粒细胞 <0.2×10⁹/L","非重型（NSAA）：未达 SAA 标准"],"workup":["血常规（含网织红细胞绝对值）+ 外周血涂片：无原始细胞","骨髓穿刺（多部位）+ 骨髓活检：诊断与分级核心","流式细胞术 PNH 克隆检测（FLAER 法），约 20%–30% 合并 PNH 克隆","染色体核型、FISH 与 MDS 相关基因突变（排查低增生 MDS）","肝肾功能、病毒学（肝炎、EBV、CMV、HIV、细小病毒 B19）","血清铁蛋白、叶酸/B12，排除营养性贫血","胸腹部 CT 与浅表淋巴结超声，排除肿瘤浸润","HLA 配型与同胞供者筛查"],"grading":"按 Camitta 标准分重型（SAA）、极重型（VSAA）与非重型（NSAA）；按病因分特发性与继发性。"},"ddx":[{"name":"缺铁性贫血（ida）","point":"与本类 ida 的鉴别点：再障为全血细胞减少、网织红细胞绝对值降低、骨髓空虚；IDA 为单纯贫血、小细胞低色素、铁蛋白低、骨髓红系增生活跃。"},{"name":"巨幼细胞性贫血（ma）","point":"与本类 ma 的鉴别点：两者均可全血细胞减少，但巨幼贫骨髓增生活跃伴巨幼样变、LDH 升高、B12/叶酸降低；再障骨髓细胞减少。"},{"name":"低增生性骨髓增生异常综合征","point":"骨髓亦空虚，但 MDS 有病态造血、原始细胞增多、特征性染色体异常或基因突变，需骨髓活检与细胞遗传学鉴别。"},{"name":"急性白血病（低增生型）","point":"骨髓原始细胞 ≥20%，伴肝脾淋巴结肿大、骨痛；再障骨髓不见原始细胞增多。"},{"name":"脾功能亢进所致全血细胞减少","point":"脾大、门脉高压病史，骨髓增生活跃伴成熟停滞；再障脾不大、骨髓空虚。"},{"name":"系统性红斑狼疮活动期、噬血细胞综合征","point":"自身抗体阳性、发热、铁蛋白显著升高、纤维蛋白原降低，骨髓见噬血现象，原发病控制后血象恢复。"}],"tx":{"drug":[{"name":"抗胸腺细胞球蛋白（ATG/抗淋巴细胞球蛋白）","dose":"兔源 ATG 3–5 mg/kg/d 静滴 5 天；马源 ATG 20–40 mg/kg/d 连用 4–5 天；遵说明书及本院方案，需联合环孢素","note":"用于不适合移植的 SAA/NSAA（>35–40 岁或无同胞供者）；输注前预处理，预防过敏与血清病","renal":"肾功能不全者遵说明书，输注期间监测肾功能","hepatic":"遵说明书","interact":"与环孢素联用增强免疫抑制，感染风险增加"},{"name":"环孢素 A（CsA）","dose":"成人 3–5 mg/kg/d 口服分 2 次，按谷浓度调整（常见目标 150–250 μg/L，遵本院方案），疗程至少 6 个月，起效后缓慢减量","note":"监测血药浓度、肾功能、血压与电解质；每 3 个月减量约 25%，避免复发","renal":"肾毒性，需减量并监测肌酐与浓度","hepatic":"肝功能不全者减量，遵说明书","interact":"与酮康唑、伊曲康唑、红霉素、地尔硫䓬、西柚汁合用浓度升高；与利福平、卡马西平、苯妥英合用浓度降低"},{"name":"造血生长因子（G-CSF/EPO）","dose":"中性粒细胞持续 <0.5×10⁹/L 伴反复感染时可试用 G-CSF，遵说明书（常 5 μg/kg/d 皮下），不建议长期超过 3 个月；EPO 仅部分 NSAA 考虑，按体重与 Hb 滴定","note":"生长因子不能治愈再障；有克隆演化者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"艾曲泊帕/海曲泊帕（TPO 受体激动剂）","dose":"用于免疫抑制治疗反应不足或不耐受的 SAA（我国已批准用于再障），起始剂量遵说明书，按血小板计数滴定","note":"与 ATG+CsA 联合可提高疗效；监测肝功能与骨髓克隆演化","renal":"遵说明书","hepatic":"肝功能损害者慎用，监测转氨酶","interact":"与含多价阳离子药物（抗酸药、铁剂）间隔服用"},{"name":"成分输血支持","dose":"Hb <60 g/L 或有症状时输注去白细胞悬浮红细胞，目标 70–80 g/L；血小板 <10×10⁹/L（或 <20×10⁹/L 伴发热/出血）输注单采血小板","note":"拟移植者优先使用滤白/辐照血制品，避免亲属供者血液","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["异基因造血干细胞移植：SAA 年轻（<35–40 岁）、有 HLA 全合同胞供者者首选","ATG+CsA 联合免疫抑制治疗：无合适供者或年龄较大者首选","感染预防：抗细菌、抗真菌、抗病毒与肺孢子菌预防","口腔与皮肤护理、避免外伤；血清病与继发性血色病相应处理"],"life":["长期随访血常规与骨髓（每 3–6 个月），监测克隆演化","避免接触苯类溶剂、射线与致敏药物","环境卫生防护，发热立即就诊；免疫抑制期间避免活疫苗","女性妊娠前需血液科评估免疫抑制剂安全性"]},"prog":"SAA 未治疗 1 年病死率可 >70%，多死于感染或出血；免疫抑制治疗 5 年生存约 70%–80%，同胞移植年轻患者可达 90%。需长期随访克隆演化。","refs":["中华医学会血液学分会红细胞疾病（贫血）学组. 再生障碍性贫血诊断与治疗中国专家共识（2017）","中华医学会血液学分会. 获得性再生障碍性贫血诊断与治疗中国指南","Killick SB, et al. Guidelines for the diagnosis and management of adult aplastic anaemia. Br J Haematol 2016"]}]},{"id":"leuk","name":"血液肿瘤","rank":2,"summary":"急性白血病以「形态+免疫表型+遗传分子」分层治疗，APL 疑诊即用 ATRA；CML 以 TKI 治疗并按 BCR-ABL1 里程碑评估；骨髓瘤以 M 蛋白+克隆性浆细胞+CRAB/SLiM 诊断；淋巴瘤须完整活检与分期，侵袭性与惰性亚型策略迥异。","compare":[{"diseaseId":"aml","dx":"骨髓/外周血髓系原始细胞 ≥20%，或存在 t(15;17)、t(8;21)、inv(16) 等定义性遗传学异常；MPO/CD13/CD33 阳性","key":"髓系原始细胞 ≥20%（或特异性遗传学异常）+ 急性起病；须先排除 APL"},{"diseaseId":"cml","dx":"白细胞显著升高伴各阶段粒细胞、嗜碱性粒细胞增多、脾大；BCR-ABL1 融合基因或 Ph 染色体阳性","key":"BCR-ABL1 阳性即可确诊；外周血各阶段粒细胞增生而非原始细胞堆积"},{"diseaseId":"mm","dx":"血/尿单克隆 M 蛋白（或游离轻链比值异常）+ 骨髓浆细胞 ≥10% 或浆细胞瘤，伴 CRAB 或 SLiM 事件","key":"单克隆 M 蛋白 + 浆细胞克隆 + 靶器官损害；须与 MGUS/冒烟型鉴别"},{"diseaseId":"lymphoma","dx":"无痛性进行性淋巴结肿大或结外肿块，完整切除活检示淋巴组织肿瘤性增生，免疫组化确诊亚型，PET-CT 分期","key":"须完整淋巴结活检+免疫表型；反应性增生无克隆性基因重排"}],"diseases":[{"id":"aml","name":"急性髓系白血病","aka":["AML","急髓","Acute Myeloid Leukemia"],"rank":1,"basic":{"define":"髓系原始细胞克隆性增殖并抑制正常造血的急性白血病，按 WHO/ICC 分型结合遗传学与分子特征分类；表现为贫血、感染、出血及髓外浸润。","risk":["年龄 >60 岁","既往化疗/放疗（烷化剂、拓扑异构酶Ⅱ抑制剂）所致的治疗相关 AML","由 MDS、骨髓增殖性肿瘤等前驱血液病转化","苯、电离辐射等化学与物理因素暴露","遗传性易感基因（RUNX1、CEBPA、GATA2 胚系突变）"],"epi":"AML 最常见于成人急性白血病，我国年发病率约 1.6/10 万；60 岁以上占比过半，整体 5 年生存约 30%–40%。"},"patho":"造血干/祖细胞的染色体易位与基因突变（FLT3-ITD、NPM1、CEBPA、IDH1/2、TP53 等）致分化阻滞与增殖失控，白血病干细胞占优势并抑制正常造血。APL 的 t(15;17) 使早幼粒细胞分化障碍，并高发 DIC。","dx":{"criteria":["骨髓或外周血髓系原始细胞 ≥20%（WHO 2022/ICC 2022 部分类型已不以 20% 为界）","或存在 AML 定义性遗传学异常：t(15;17)/PML::RARA、t(8;21)/RUNX1::RUNX1T1、inv(16)/CBFB::MYH11、KMT2A 重排等","免疫表型：CD13、CD33、CD117、MPO 阳性（≥3%），常伴 CD34、HLA-DR","血常规示贫血、中性粒细胞减少与血小板减少，外周血见原始细胞","疑诊 APL 时立即查 PML-RARA，并抢先给予 ATRA，不等遗传学结果"],"workup":["血常规 + 外周血涂片（原始细胞比例、Auer 小体）","骨髓穿刺涂片、骨髓活检与铁染色","流式细胞术免疫分型","染色体核型 + FISH（PML-RARA、CBF、KMT2A）","分子检测：NPM1、FLT3-ITD/TKD、CEBPA、IDH1/2、RUNX1、ASXL1、TP53、KIT","凝血功能与 DIC 筛查、LDH、尿酸、肾功能与电解质","HLA 配型与供者筛查；高危、单核细胞型或治疗相关 AML 行腰穿","感染筛查与心脏功能评估（蒽环类前测 LVEF）"],"grading":"WHO 2022/ICC 2022 分型。ELN 2022 危险分层：有利（t(8;21)、inv(16)、NPM1 无不良、CEBPA bZIP）、中等、不良（TP53、-5/del(5q)、-7/del(7q)、KMT2A、复杂核型等）。"},"ddx":[{"name":"慢性髓性白血病急髓变（cml）","point":"与本类 cml 的鉴别点：CML 有 Ph 染色体/BCR-ABL1 阳性病史、脾大与各阶段粒细胞增生；AML 无 BCR-ABL1（除非 CML 急变）。"},{"name":"多发性骨髓瘤（mm）","point":"与本类 mm 的鉴别点：MM 为 M 蛋白、浆细胞 ≥10%、骨破坏与高钙，骨髓原始细胞不增多；AML 为髓系原始细胞增殖。"},{"name":"淋巴瘤（lymphoma）","point":"与本类 lymphoma 的鉴别点：淋巴瘤以淋巴结/结外肿块与淋巴系表型为主，仅部分骨髓侵犯；AML 以骨髓原始髓系细胞 ≥20% 与全血细胞减少为主。"},{"name":"骨髓增生异常综合征（MDS）","point":"MDS 原始细胞 <20%，以病态造血与血细胞减少为主，常伴 5q-、+8 等克隆异常；AML 原始细胞 ≥20%。"},{"name":"急性淋巴细胞白血病","point":"淋巴系抗原（CD19/CD79a/CD3/TdT）阳性、MPO 阴性，肝脾淋巴结肿大与中枢浸润多见；AML 髓系抗原与 MPO 阳性。"},{"name":"类白血病反应（严重感染）","point":"白细胞升高伴左移但原始细胞少见，无克隆性遗传学异常、NAP 积分升高，抗感染后恢复。"}],"tx":{"drug":[{"name":"标准「3+7」诱导（蒽环类+阿糖胞苷）","dose":"去甲氧柔红霉素 10–12 mg/m²/d 静滴 第 1–3 天，或柔红霉素 60–90 mg/m²/d 第 1–3 天；联合阿糖胞苷 100–200 mg/m²/d 持续静滴 第 1–7 天；具体遵本院方案与说明书","note":"适合 <60–65 岁、体能良好者；诱导后第 14–21 天评估骨髓并决定再诱导；控制蒽环类累积剂量","renal":"肾功能不全者阿糖胞苷减量；蒽环类遵说明书","hepatic":"胆红素 >3 mg/dL 时蒽环类减量，遵说明书","interact":"慎与其他骨髓抑制药物及致 QT 延长药物联用"},{"name":"去甲基化药物（阿扎胞苷/地西他滨）+ 维奈克拉","dose":"维奈克拉按说明书递增至目标剂量（常 400 mg qd，28 天；与唑类合用时减量）；阿扎胞苷 75 mg/m² 皮下/静滴 第 1–7 天，28 天一疗程；地西他滨 20 mg/m² 静滴 第 1–5 天","note":"不适合强化疗的老年/合并症多者首选；彻底预防肿瘤溶解综合征，粒细胞减少期加强支持","renal":"中重度肾功能不全者维奈克拉起始减量，遵说明书","hepatic":"重度肝功能不全者减量，遵说明书","interact":"维奈克拉为 CYP3A4 底物，与唑类抗真菌药、克拉霉素合用必须减量"},{"name":"FLT3 抑制剂（米哚妥林/吉瑞替尼）","dose":"米哚妥林 50 mg bid 口服（诱导第 8–21 天，巩固各疗程第 8–21 天）；吉瑞替尼 120 mg qd 用于 FLT3 突变复发/难治；遵说明书","note":"确认 FLT3-ITD/TKD 状态后使用；监测 QT、肝功能与分化综合征","renal":"遵说明书","hepatic":"中重度肝功能不全者减量","interact":"CYP3A4 底物，强效抑制剂/诱导剂需调整剂量；可延长 QT"},{"name":"全反式维甲酸（ATRA）+ 三氧化二砷（ATO，APL 专用）","dose":"ATRA 25–45 mg/m²/d 口服分 2 次（常约 45 mg/m²/d）；ATO 0.15 mg/kg/d 静滴；高危 APL 加蒽环类或羟基脲控白细胞；遵说明书及本院 APL 方案","note":"疑诊 APL 即抢先给药；警惕分化综合征与 QT 延长，纠正电解质并监测心电图","renal":"ATO 肾功能不全者监测，遵说明书","hepatic":"ATO 肝毒性常见，监测转氨酶","interact":"ATO 延长 QT，避免与胺碘酮、氟喹诺酮等致 QT 延长药物合用"},{"name":"移植相关：预处理与 GVHD 预防","dose":"预处理（如白消安+环磷酰胺、氟达拉滨+白消安）按中心方案与说明书；他克莫司或环孢素+吗替麦考酚酯预防 GVHD，剂量按血药浓度与方案","note":"中高危 CR1 优先移植；随访嵌合率、GVHD 与感染","renal":"他克莫司/环孢素肾毒性，按浓度调整","hepatic":"遵说明书","interact":"他克莫司/环孢素经 CYP3A4 代谢，与唑类抗真菌药合用需减量并监测浓度"},{"name":"鞘内中枢神经系统预防","dose":"甲氨蝶呤 10–15 mg + 地塞米松 5 mg 鞘注，或阿糖胞苷 30–50 mg 鞘注，次数按方案与脑脊液结果（遵说明书）","note":"鞘注前评估血小板与颅内压","renal":"遵说明书","hepatic":"遵说明书","interact":"与全身大剂量甲氨蝶呤合用注意神经毒性叠加"}],"nonDrug":["全血细胞减少期支持：保护性隔离、G-CSF 视方案、广谱抗感染","异基因造血干细胞移植：中高危 CR1、复发/难治缓解后；同胞或单倍体移植","肿瘤溶解综合征预防：水化、别嘌醇或拉布立酶、监测电解质与尿量","高危、单核细胞型、治疗相关 AML 行中枢预防性鞘注","MDT 讨论决定移植时机与供者"],"life":["化疗后恢复期接种非活疫苗，家庭成员接种可减少传播","长期随访心脏功能（蒽环类累积剂量）与生育保存咨询","复发监测：血常规、骨髓与残留病（NPM1 转录本、流式 MRD）","避免苯、放射线接触；有家族史者评估遗传易感"]},"prog":"年轻低危（CBF、NPM1 无 FLT3-ITD）完全缓解率 70%–80%，5 年生存可达 50%–70%；高危/老年 CR 率 40%–60%，5 年生存 <20%。APL 治愈率 >80%–90%，但早期出血死亡仍是主要风险。","refs":["中华医学会血液学分会白血病淋巴瘤学组. 中国成人急性髓系白血病（非 APL）诊疗指南（2021 年版）","中华医学会血液学分会. 中国急性早幼粒细胞白血病诊疗指南","Döhner H, et al. Diagnosis and management of AML in adults: 2022 ELN recommendations. Blood 2022"]},{"id":"cml","name":"慢性髓性白血病","aka":["CML","慢粒","Chronic Myeloid Leukemia"],"rank":2,"basic":{"define":"以 t(9;22)(q34;q11) 形成 BCR-ABL1 融合基因、编码持续活化酪氨酸激酶为特征的多能造血干细胞克隆性疾病，分慢性期、加速期与急变期，酪氨酸激酶抑制剂（TKI）为主要治疗。","risk":["电离辐射暴露（原子弹幸存者发病率显著升高）","年龄：中位发病年龄 45–60 岁","男性略多于女性","苯等化学暴露可能相关"],"epi":"CML 约占成人白血病的 15%–20%，我国年发病率约 0.4–0.6/10 万；TKI 普及后慢性期患者预期寿命已接近一般人群。"},"patho":"t(9;22) 使 ABL1 与 BCR 融合，BCR-ABL1 持续活化酪氨酸激酶，激活 RAS/MAPK、JAK-STAT、PI3K-AKT 通路，致髓系细胞克隆性增殖与凋亡抑制，分化功能保留（故外周血为各阶段粒细胞）。克隆积累遗传学异常（+8、i(17q)）可致急变。","dx":{"criteria":["白细胞显著升高（常 50–200×10⁹/L），中性中、晚幼粒与杆状核增高，嗜酸、嗜碱性粒细胞增多，原始细胞常 <5%","脾大，可伴贫血、血小板增多或减少、LDH 升高、NAP 积分降低","骨髓增生活跃以粒系为主，各阶段均见，嗜碱性粒细胞增多","Ph 染色体 t(9;22) 阳性或 BCR-ABL1 融合基因阳性（PCR/FISH），为确诊关键","加速期：原始细胞 10%–19%、新增克隆异常、白细胞不能控制、持续性血小板减少/增多、脾进行性肿大；急变期：原始细胞 ≥20% 或髓外原始细胞浸润"],"workup":["血常规 + 外周血涂片 + 白细胞分类","骨髓穿刺与活检（形态、纤维化、原始细胞比例）","染色体核型、FISH 与 BCR-ABL1 定量 PCR（基线国际标准 IS 水平）","BCR-ABL1 激酶区突变检测（TKI 耐药或进展时）","脾脏超声、肝肾功能、电解质、尿酸、LDH","排查 Ph+ 急性淋巴细胞白血病","育龄女性妊娠试验，妊娠期处理需特殊方案"],"grading":"分期为慢性期（CP）、加速期（AP）与急变期（BP）。预后评分：Sokal、Hasford/Euro 评分用于早期风险分层。"},"ddx":[{"name":"急性髓系白血病（aml）","point":"与本类 aml 的鉴别点：AML 急性起病、骨髓原始细胞 ≥20%、BCR-ABL1 阴性；CML 以各阶段粒细胞增生为主、BCR-ABL1 阳性，原始细胞 ≥20% 时诊断为 CML 急变。"},{"name":"多发性骨髓瘤（mm）","point":"与本类 mm 的鉴别点：MM 以 M 蛋白、浆细胞增多与骨破坏为主，无大量粒细胞增多与 Ph 染色体；CML 无 M 蛋白。"},{"name":"淋巴瘤（lymphoma）","point":"与本类 lymphoma 的鉴别点：淋巴瘤以无痛性淋巴结肿大与淋巴系表型增生为主，外周血少见大量粒细胞；CML 为粒系克隆、Ph 阳性。"},{"name":"类白血病反应","point":"严重感染、应激或 G-CSF 后白细胞升高但多 <50×10⁹/L、NAP 积分升高、BCR-ABL1 阴性、脾不大，去除病因后恢复。"},{"name":"骨髓增殖性肿瘤（PV/ET/PMF）","point":"BCR-ABL1 阴性，伴 JAK2 V617F、CALR 或 MPL 突变；以红细胞、血小板增多或骨髓纤维化为主。"},{"name":"Ph+ 急性淋巴细胞白血病","point":"同样 BCR-ABL1 阳性，但原始淋巴细胞 ≥20%、TdT/CD19 阳性、淋巴结肿大常见；需与 CML 淋巴系急变鉴别。"}],"tx":{"drug":[{"name":"伊马替尼（一代 TKI）","dose":"慢性期一线 400 mg qd 口服；加速/急变期 600–800 mg qd；与食物同服可减轻胃肠道反应","note":"疗效里程碑：3、6、12 个月 BCR-ABL1 分别 ≤10%、≤1%、≤0.1%（IS）；未达标需换药或查突变","renal":"重度肾功能不全者酌减，遵说明书","hepatic":"肝功能不全者减量并监测","interact":"CYP3A4 底物：酮康唑、红霉素升高浓度；利福平、苯妥英降低疗效"},{"name":"二代 TKI（达沙替尼/尼洛替尼/氟马替尼/博舒替尼）","dose":"达沙替尼慢性期 100 mg qd（或 50 mg bid）；尼洛替尼 300 mg bid（一线慢性期）；氟马替尼 600 mg qd；剂量与疗程遵说明书及本中心方案","note":"达沙替尼注意胸腔积液与肺动脉高压；尼洛替尼注意 QT 延长、胰腺炎、血糖升高（需空腹服用）","renal":"达沙替尼轻中度无需调整，重度遵说明书","hepatic":"尼洛替尼、达沙替尼肝功能不全者减量","interact":"尼洛替尼禁与强效 CYP3A4 抑制剂合用；达沙替尼与抗酸药间隔 2 h；二者均需监测 QT"},{"name":"三代 TKI（普纳替尼/奥雷巴替尼）","dose":"普纳替尼 45 mg qd（慢性期起效后减至 15 mg）；奥雷巴替尼 40 mg 隔日口服（T315I 突变）；遵说明书与中心方案","note":"普纳替尼需评估心血管风险；奥雷巴替尼监测血细胞减少与肝功能","renal":"遵说明书","hepatic":"重度肝功能不全者减量或停药","interact":"普纳替尼为 CYP3A4 底物，强效抑制剂/诱导剂需调整剂量；可延长 QT"},{"name":"羟基脲（桥接/妊娠期）","dose":"1–4 g/d 分次口服，按白细胞计数滴定（目标 WBC 10–20×10⁹/L）；妊娠期或 TKI 不耐受时使用","note":"仅作桥接或急性控制，不改变自然病程","renal":"肾功能不全者减量，遵说明书","hepatic":"遵说明书","interact":"与其他骨髓抑制药合用加重血细胞减少"}],"nonDrug":["TKI 为慢性期一线；3、6、12、18 个月及之后每 3–6 个月定量 BCR-ABL1 评估疗效","换药指征：未达早期反应里程碑、失去反应、不耐受或进展","TKI 停药试验：持续深度分子学反应（如 MR4.5 ≥2 年）且可严密监测者在医生指导下尝试","治疗无效者行激酶区突变检测，选敏感 TKI 或评估移植","脾大显著者避免剧烈运动以防脾破裂"],"life":["依从性决定疗效；按时复诊与定量 PCR 监测","避免西柚（影响 CYP3A4）同服，戒烟限酒","计划妊娠前与医生讨论停药或换药，育龄女性合理避孕","新发心悸、水肿、胸痛及时就诊（TKI 心血管不良反应）"]},"prog":"TKI 治疗后慢性期患者长期生存接近一般人群，部分患者可获得深度分子学反应并成功停药；进展至加速/急变期者预后差，急变期长期生存 <20%。","refs":["中华医学会血液学分会白血病淋巴瘤学组. 中国慢性髓性白血病诊断与治疗指南（2020 年版）","中华医学会血液学分会. 酪氨酸激酶抑制剂治疗慢性髓性白血病中国专家共识","Hochhaus A, et al. European LeukemiaNet 2020 recommendations for treating chronic myeloid leukemia. Leukemia 2020"]},{"id":"mm","name":"多发性骨髓瘤","aka":["MM","骨髓瘤","Multiple Myeloma"],"rank":3,"basic":{"define":"骨髓中克隆性浆细胞异常增殖并分泌单克隆免疫球蛋白或其片段，引起高钙、肾功能损害、贫血与骨破坏（CRAB）的系统性血液肿瘤，按 ISS/R-ISS 分层治疗。","risk":["年龄 >60 岁（中位发病 65–70 岁）","单克隆免疫球蛋白血症（MGUS）或冒烟型骨髓瘤病史","肥胖、职业接触农药/苯/辐射","家族史（少见）"],"epi":"MM 占血液系统恶性肿瘤约 10%，我国年发病率约 1–1.5/10 万；发病年龄较欧美年轻（中位约 60 岁）。"},"patho":"浆细胞克隆与骨髓微环境相互作用（IL-6、RANKL/OPG 失衡）致溶骨病变；轻链管型沉积致肾损害；骨髓浸润抑制造血；高黏滞与淀粉样变可致多系统表现。","dx":{"criteria":["血/尿单克隆 M 蛋白（血清 >10 g/L，或尿本周蛋白 >0.2 g/24 h，或血清游离轻链 κ/λ 比值异常），或组织活检证实单克隆浆细胞/淀粉样沉积","骨髓浆细胞 ≥10%，或病理证实的浆细胞瘤","至少 1 项骨髓瘤定义事件（CRAB/SLiM）：血钙 >2.75 mmol/L；肌酐 >173 μmol/L 或 CrCl <40 mL/min；Hb <100 g/L 或低于正常下限 20 g/L；≥1 处溶骨病变；游离轻链比 ≥100；骨髓浆细胞 ≥60%；MRI >1 处局灶病变 ≥5 mm","免疫表型：CD138+、CD38+、CD56+、CD19−、CD45−，轻链限制性"],"workup":["血清蛋白电泳、免疫固定电泳；24 h 尿蛋白电泳与免疫固定；血清游离轻链","血常规、肌酐、电解质、尿酸、白蛋白、β2 微球蛋白、LDH、CRP、血钙","骨髓穿刺（形态、流式、FISH）与骨髓浆细胞计数","全身低剂量 CT 或 PET-CT 评估骨病变，必要时 MRI","乙肝/HIV 筛查、心脏与周围神经基线评估","高危细胞遗传学筛查：del(17p)、t(4;14)、t(14;16)、1q21 扩增"],"grading":"分期：ISS（β2 微球蛋白+白蛋白）与 R-ISS（加 LDH 与高危细胞遗传学）。高危：del(17p)、t(4;14)、t(14;16)、1q21 ≥4 拷贝。状态分 MGUS、冒烟型（无定义性事件）与活动性 MM。"},"ddx":[{"name":"急性髓系白血病（aml）","point":"与本类 aml 的鉴别点：AML 以髓系原始细胞增多、全血细胞减少与发热为特征，无 M 蛋白与溶骨病变；MM 以 M 蛋白、浆细胞浸润与骨破坏为主。"},{"name":"慢性髓性白血病（cml）","point":"与本类 cml 的鉴别点：CML 为 BCR-ABL1 阳性、粒细胞极度增多与脾大；MM 为浆细胞克隆与 M 蛋白，无 Ph 染色体。"},{"name":"淋巴瘤（lymphoma）","point":"与本类 lymphoma 的鉴别点：部分淋巴瘤可分泌 IgM 型 M 蛋白（如华氏巨球蛋白血症），以淋巴结肿大与淋巴系表型为主；MM 多为 IgG/IgA 型，伴骨破坏与高钙。"},{"name":"MGUS 与冒烟型骨髓瘤","point":"M 蛋白 <30 g/L、浆细胞 <10%（冒烟型可 ≥10%），无 CRAB/SLiM 事件，需观察而非治疗。"},{"name":"转移性骨肿瘤与骨质疏松","point":"骨痛与病理性骨折但无 M 蛋白与骨髓浆细胞增多，可有原发肿瘤标志物。"},{"name":"原发性 AL 淀粉样变","point":"可伴轻链型 M 蛋白，但以心肌、肾脏、周围神经、舌肿大为主，刚果红染色阳性，骨髓浆细胞 <10%。"}],"tx":{"drug":[{"name":"硼替佐米（蛋白酶体抑制剂）","dose":"1.3 mg/m² 皮下注射（优选），按方案在第 1、4、8、11 天给药（21 或 28 天一疗程）；具体疗程遵说明书与中心方案","note":"皮下给药减少周围神经病变；常见血小板减少；带状疱疹需预防性抗病毒","renal":"肾功能不全无需调整；透析患者透析后给药","hepatic":"中重度肝功能不全者减量，遵说明书","interact":"CYP3A4 强抑制剂可升高浓度；合用降糖药注意低血糖"},{"name":"来那度胺（免疫调节剂）","dose":"25 mg/d 口服，第 1–14 天或第 1–21 天（按方案），28 天一疗程；维持治疗 10–15 mg/d；遵说明书","note":"需阿司匹林或低分子肝素预防血栓；中性粒细胞与血小板减少常见；妊娠绝对禁忌（致畸）","renal":"CrCl 30–59 mL/min 减至 10 mg/d；<30 mL/min 或透析者按说明书减量","hepatic":"肝功能不全者减量，遵说明书","interact":"与地塞米松等合用需注意感染与血栓风险"},{"name":"地塞米松","dose":"40 mg（或 20 mg）每周 1 次，与方案给药日匹配；具体遵说明书与中心方案","note":"长期使用需预防肺孢子菌肺炎与骨质疏松，监测血糖与血压","renal":"无需调整","hepatic":"遵说明书","interact":"CYP3A4 诱导剂；与非甾体抗炎药合用增加消化道出血与肾损害"},{"name":"达雷妥尤单抗（CD38 单抗）","dose":"16 mg/kg 静脉或 1800 mg 皮下注射，按方案给药（诱导期每周 1 次，后延长间隔）；遵说明书","note":"输注反应常见（首剂尤甚），需预处理；干扰血型鉴定与蛋白电泳；预防带状疱疹","renal":"无需调整剂量","hepatic":"遵说明书","interact":"与静脉免疫球蛋白间隔使用；常与 VRd 联合形成 D-VRd"},{"name":"骨靶向治疗（唑来膦酸/地舒单抗）","dose":"唑来膦酸 4 mg 静脉输注 每 3–4 周（或每 12 周）1 次，一般疗程 ≤2 年；地舒单抗 120 mg 皮下 每月 1 次；遵说明书","note":"用药前查牙科状况，预防下颌骨坏死；补钙与维生素 D，监测肾功能与低钙","renal":"唑来膦酸禁用于 CrCl <30 mL/min；地舒单抗可用但需监测低钙","hepatic":"遵说明书","interact":"与肾毒性药物合用需谨慎"}],"nonDrug":["适合移植者（一般 ≤70 岁、体能良好）：诱导 4–6 疗程→自体干细胞移植（马法兰 200 mg/m² 预处理，肾功能不全减至 140 mg/m²）→维持","不适合移植者：D-VRd 或 VRd 等治疗至进展或深度缓解后维持","高钙血症：水化、双膦酸盐、降钙素、糖皮质激素","肾功能不全：避免造影剂与肾毒性药物，充分水化；高黏滞血症行血浆置换","骨病：局部放疗、椎体成形术、骨科固定，预防跌倒"],"life":["定期复查血常规、肾功能、M 蛋白与游离轻链（每 2–3 个月）","灭活疫苗接种，带状疱疹预防","联合激素时预防血栓；定期牙科检查与口腔护理","避免剧烈活动致骨折；戒烟限酒，适度负重运动"]},"prog":"新药时代 MM 中位总生存已达 7–10 年，部分低危患者可达 10 年以上；高危细胞遗传学患者 5 年生存约 30%–40%。深度缓解（MRD 阴性）与肾功能恢复提示更好预后。","refs":["中国医师协会血液科医师分会. 中国多发性骨髓瘤诊治指南（2022 年修订）","中华医学会血液学分会. 多发性骨髓瘤骨病诊疗专家共识","中国临床肿瘤学会（CSCO）. 恶性血液病诊疗指南（2024）","Rajkumar SV, et al. IMWG updated criteria for the diagnosis of multiple myeloma. Lancet Oncol 2014"]},{"id":"lymphoma","name":"淋巴瘤","aka":["Lymphoma","霍奇金淋巴瘤","非霍奇金淋巴瘤","HL","NHL"],"rank":4,"basic":{"define":"起源于淋巴细胞（B、T 或 NK 细胞）的恶性克隆性肿瘤，分霍奇金淋巴瘤（HL）与非霍奇金淋巴瘤（NHL）；以无痛性淋巴结肿大或结外肿块为主，可伴发热、盗汗、体重下降（B 症状）。","risk":["免疫功能低下：HIV、器官移植后免疫抑制、自身免疫病","EB 病毒感染（HL、部分 NHL）、幽门螺杆菌（胃 MALT 淋巴瘤）","化学与放射线暴露、农药","家族史","年龄：HL 呈双峰（青年与老年），NHL 随年龄增长"],"epi":"我国淋巴瘤年发病率约 6–7/10 万；NHL 占 85%–90%，DLBCL 最常见（约 35%–40%），HL 约占 10%。"},"patho":"淋巴细胞获得染色体易位（t(14;18)/BCL2、t(8;14)/MYC、t(11;14)/CCND1）与基因突变（MYD88、CD79B、TP53），致凋亡抑制与持续增殖；微环境与免疫逃逸参与。HL 的 Reed-Sternberg 细胞起源于生发中心 B 细胞，伴大量炎症细胞背景。","dx":{"criteria":["无痛性、进行性淋巴结肿大或结外肿块，伴或不伴 B 症状","淋巴结完整切除活检或结外病灶活检为确诊依据，细针穿刺不足以确诊","免疫组化：HL 为 CD30+、CD15+、PAX5 弱阳性、CD45−、CD20−；DLBCL 为 CD20+、Ki-67 常 ≥40%；滤泡型 CD10+、BCL6+、BCL2+","PET-CT 为分期金标准，骨髓活检评估骨髓受累","Lugano 分期：Ⅰ期 1 个淋巴结区或单个结外；Ⅱ期 ≥2 个均在同一侧膈肌；Ⅲ期 膈肌两侧或脾受累；Ⅳ期 弥漫或广泛结外"],"workup":["完整淋巴结切除活检 + 免疫组化，必要时分子检测（MYC、BCL2、BCL6 重排、MYD88）","PET-CT 或全身增强 CT；骨髓穿刺与活检","血常规、LDH、β2 微球蛋白、尿酸、肝肾功能、白蛋白、CRP、ESR","HBV、HCV、HIV、梅毒血清学（抗 CD20 治疗前必须评估 HBV）","心脏功能（蒽环类前 LVEF）、生育保存与肺功能（博来霉素前）","胃 MALT 淋巴瘤：胃镜 + 幽门螺杆菌检测"],"grading":"Lugano Ⅰ–Ⅳ 期；病理分为经典型 HL 与 NHL 各亚型（侵袭性/惰性）。危险分层：HL 用 IPS；DLBCL 用 IPI 或 NCCN-IPI；滤泡性用 FLIPI；外周 T 用 PIT。疗效用 Deauville 评分（1–3 分阴性）。"},"ddx":[{"name":"多发性骨髓瘤（mm）","point":"与本类 mm 的鉴别点：MM 以 M 蛋白、骨髓浆细胞 ≥10% 与溶骨病变为主，淋巴结肿大少见；淋巴瘤以淋巴结/结外肿块与淋巴系表型增生为主。"},{"name":"急性髓系白血病（aml）","point":"与本类 aml 的鉴别点：AML 以骨髓原始髓系细胞 ≥20%、全血细胞减少为特征、起病急；淋巴瘤以淋巴结肿大与分期为主，仅部分骨髓侵犯。"},{"name":"慢性髓性白血病（cml）","point":"与本类 cml 的鉴别点：CML 为 BCR-ABL1 阳性、粒细胞极度增多伴脾大；淋巴瘤为淋巴系表型，无 BCR-ABL1。"},{"name":"反应性淋巴结增生（感染、结核、结节病）","point":"淋巴结结构保留、细胞多样、无克隆性重排；结核伴干酪样坏死与抗酸染色阳性。"},{"name":"转移性癌（淋巴结转移）","point":"淋巴结内见上皮细胞巢、CK 阳性，形态与淋巴瘤不同；需查找原发灶。"},{"name":"不明原因发热（感染/自身免疫病）","point":"发热但淋巴结反应性增生、PET 无高代谢病灶，抗感染或免疫治疗后恢复。"}],"tx":{"drug":[{"name":"R-CHOP（弥漫大 B 细胞淋巴瘤一线）","dose":"利妥昔单抗 375 mg/m² 静滴 第 1 天；环磷酰胺 750 mg/m²、多柔比星 50 mg/m²、长春新碱 1.4 mg/m²（上限 2 mg）静滴；泼尼松 100 mg/d 口服 第 1–5 天；每 21 天一疗程，共 6–8 疗程","note":"控制蒽环类累积剂量；治疗前筛查 HBV 并预防再激活；衰弱老年者可调整剂量","renal":"肾功能不全者环磷酰胺减量；长春新碱注意神经毒性","hepatic":"胆红素升高时多柔比星与长春新碱减量，遵说明书","interact":"多柔比星与曲妥珠单抗合用增加心脏毒性；治疗期间避免活疫苗"},{"name":"ABVD（霍奇金淋巴瘤经典方案）","dose":"多柔比星 25 mg/m²、博来霉素 10 mg/m²、长春碱 6 mg/m² 静推，达卡巴嗪 375 mg/m² 静滴，均第 1、15 天；每 28 天一疗程，早中期共 4–6 疗程","note":"博来霉素肺毒性（老年、吸烟者）需监测肺功能；中期 PET 阴性可降阶治疗","renal":"达卡巴嗪肾功能不全者减量，遵说明书","hepatic":"博来霉素与长春碱肝功能不全者慎用","interact":"避免与其他肺毒性药物合用"},{"name":"苯达莫司汀+利妥昔单抗（惰性 NHL）","dose":"苯达莫司汀 90 mg/m² 静滴 第 1–2 天；利妥昔单抗 375 mg/m² 第 1 天；每 28 天一疗程，共 6 疗程；遵说明书","note":"以血细胞减少与感染为主；可与新药联合或作二线","renal":"重度肾功能不全者慎用","hepatic":"遵说明书","interact":"与 CYP1A2 抑制剂（氟伏沙明、环丙沙星）合用升高浓度"},{"name":"BTK 抑制剂（伊布替尼/泽布替尼/阿可替尼）","dose":"伊布替尼 560 mg qd（套细胞淋巴瘤）或 420 mg qd（CLL/华氏巨球蛋白血症）；泽布替尼 160 mg bid；阿可替尼 100 mg bid；遵说明书","note":"长期治疗至进展；注意房颤、出血、高血压与感染","renal":"按说明书，重度肾功能不全者需评估","hepatic":"重度肝功能不全者减量，遵说明书","interact":"CYP3A4 底物：与唑类抗真菌药、克拉霉素合用需减量；与华法林等抗凝药合用增加出血"},{"name":"抗体偶联药物（维泊妥珠单抗/维布妥昔单抗）","dose":"维泊妥珠单抗 1.8 mg/kg 静脉输注 每 21 天；维布妥昔单抗 1.8 mg/kg 每 21 天；遵说明书与联合方案","note":"周围神经病变需监测；输注反应需预处理","renal":"遵说明书","hepatic":"重度肝功能不全者慎用","interact":"维布妥昔单抗与强 CYP3A4 抑制剂合用可增加神经毒性"},{"name":"累及部位放疗（早期 HL/局限性淋巴瘤）","dose":"受累部位放疗（ISRT）20–30 Gy（早中期 HL），按分期与病理由放疗科制定","note":"评估生育、二次肿瘤与心脏剂量限制；PET 阴性者可减量","renal":"遵说明书","hepatic":"遵说明书","interact":"与博来霉素同步增加肺毒性"}],"nonDrug":["自体/异基因造血干细胞移植：复发难治侵袭性淋巴瘤、高危套细胞淋巴瘤缓解后","CAR-T 细胞治疗：复发难治 DLBCL 与套细胞淋巴瘤（按获批适应证）","胃 MALT 淋巴瘤：幽门螺杆菌根除治疗，早期可观察","双打击/三打击淋巴瘤：高危，需强化方案与移植评估","中枢预防：高危 DLBCL（双打击、睾丸、中枢邻近部位）行鞘内化疗"],"life":["随访：前 2–3 年每 3 个月、之后每 6 个月复查，PET-CT 用于疗效与可疑复发","治疗前接种灭活疫苗，治疗期间避免活疫苗；HBV 携带者抗病毒预防","生育保存咨询与心脏、肺功能长期监测","戒烟、避免免疫抑制环境；长期生存者关注二次肿瘤与心血管风险"]},"prog":"经典型 HL 早中期 5 年生存 >90%，晚期约 70%–80%；DLBCL 采用 R-CHOP 约 60%–70% 可治愈；滤泡性中位生存 >10 年但难治愈；外周 T 与双打击淋巴瘤预后较差。","refs":["中国临床肿瘤学会（CSCO）. 淋巴瘤诊疗指南（2024）","中华医学会血液学分会. 中国弥漫大 B 细胞淋巴瘤诊断与治疗指南（2021）","中华医学会血液学分会. 中国霍奇金淋巴瘤诊断与治疗专家共识","Cheson BD, et al. Lugano classification. J Clin Oncol 2014"]}]},{"id":"coag","name":"止血与血栓","rank":3,"summary":"血小板减少先查涂片排除假性减少与 TMA；ITP 为排除性诊断，一线用糖皮质激素或 IVIG；DIC 以原发病治疗为核心、动态监测凝血并按分期补充或抗凝；TTP 为急症，确诊前即行血浆置换，常规禁用血小板输注。","compare":[{"diseaseId":"itp","dx":"孤立性血小板减少（<100×10⁹/L），无贫血/白细胞减少，涂片无异常细胞与碎裂红细胞，脾不大，骨髓巨核细胞正常或增多","key":"孤立血小板减少 + 其余血系与凝血正常；为排除性诊断"},{"diseaseId":"dic","dx":"有诱因（感染、肿瘤、产科、创伤），PLT 下降 + PT/APTT 延长 + 纤维蛋白原降低 + D-二聚体升高","key":"凝血指标全面异常（非孤血小板减少），纤维蛋白原下降、D-二聚体升高"},{"diseaseId":"ttp","dx":"微血管病性溶血（Hb 降、网织高、LDH 高）+ 血小板减少 + 涂片破碎红细胞 ≥1%，ADAMTS13 活性 <10%","key":"MAHA + 血小板减少 + 碎裂红细胞；禁常规血小板输注，立即血浆置换"}],"diseases":[{"id":"itp","name":"免疫性血小板减少症","aka":["ITP","特发性血小板减少性紫癜","Immune Thrombocytopenia"],"rank":1,"basic":{"define":"自身抗体介导的血小板破坏增加和生成不足所致的获得性孤立性血小板减少症，须排除其他原因；分新诊断（<3 个月）、持续性（3–12 个月）与慢性（>12 个月）。","risk":["任何年龄，成人育龄期女性多见","病毒感染（HIV、HCV、CMV、EBV、幽门螺杆菌）后","自身免疫病（SLE、抗磷脂综合征）","药物（奎宁、磺胺等）、疫苗接种后","妊娠期（需与妊娠期血小板减少症鉴别）"],"epi":"成人 ITP 年发病率约 3–9/10 万，60 岁以上升高；儿童多见急性自限型（高峰 2–5 岁），成人多为慢性过程。"},"patho":"B 细胞产生针对血小板糖蛋白（GPⅡb/Ⅲa、GPⅠb/Ⅸ）的自身抗体，介导脾脏巨噬细胞 Fcγ 受体依赖性清除；同时 T 细胞对巨核细胞的细胞毒作用与血小板生成素相对不足致血小板生成受损。","dx":{"criteria":["至少 2 次血常规证实血小板 <100×10⁹/L，且为孤立性血小板减少（Hb、白细胞正常）","皮肤黏膜出血（瘀点、瘀斑、鼻衄、牙龈出血）为主，无肝脾淋巴结肿大","外周血涂片示血小板减少、体积偏大，无异常细胞与破碎红细胞","抗血小板抗体阳性支持但不为诊断必需（敏感性/特异性有限）","骨髓：巨核细胞数正常或增多、成熟产板巨核减少，无异常细胞；>60 岁、有异常体征、拟切脾或治疗无效时建议检查","排除假性血小板减少（EDTA 依赖性聚集，换肝素抗凝或手工计数）、药物、HIV/HCV、SLE、抗磷脂综合征、TMA 与 MDS"],"workup":["血常规（人工计数复核）+ 外周血涂片","肝肾功能、PT/APTT、纤维蛋白原、D-二聚体、网织红细胞、胆红素与 LDH（排除 TMA）","病毒筛查：HIV、HCV、HBV、CMV/EBV；抗核抗体、抗磷脂抗体、甲状腺功能","幽门螺杆菌检测（呼气试验或粪便抗原）","骨髓穿刺（>60 岁、贫血/白细胞异常、涂片异常、拟切脾、治疗无反应）","妊娠者查尿蛋白、肝肾功能、血压，排除子痫前期/HELLP"],"grading":"按血小板计数分度：轻度 50–100×10⁹/L；中度 30–50×10⁹/L；重度 <30×10⁹/L；极重度 <10×10⁹/L。按病程分新诊断、持续性与慢性。出血评分（WHO 出血分级）指导治疗决策。"},"ddx":[{"name":"DIC（dic）","point":"与本类 dic 的鉴别点：ITP 为孤立性血小板减少、PT/APTT 与纤维蛋白原正常；DIC 伴 PT/APTT 延长、纤维蛋白原降低与 D-二聚体升高，有明确诱因。"},{"name":"血栓性微血管病（ttp）","point":"与本类 ttp 的鉴别点：TTP 伴微血管病性溶血（Hb 低、网织高、LDH 高）、碎裂红细胞、神经症状与肾损害；ITP 无溶血与碎裂红细胞。"},{"name":"药物性血小板减少","point":"有明确用药史（奎宁、磺胺、金盐、肝素等），停药后 5–7 天恢复，可伴严重出血。"},{"name":"假性血小板减少（EDTA 依赖性）","point":"血常规血小板低但无出血、涂片见血小板聚集，改用枸橼酸钠或肝素抗凝管复核可恢复正常。"},{"name":"MDS/白血病所致血小板减少","point":"伴贫血或白细胞异常、外周血或骨髓见异常细胞、病态造血，脾可大；ITP 骨髓无异常细胞。"}],"tx":{"drug":[{"name":"泼尼松（一线）","dose":"1 mg/kg/d 口服（一般不超过 80 mg/d），晨起顿服，2–4 周后按血小板反应缓慢减量，总疗程约 4–6 周；无反应者尽快减停","note":"需评估糖尿病、骨质疏松、消化性溃疡与感染风险；血小板 <30×10⁹/L 或有出血时使用，无症状轻度减少可观察","renal":"遵说明书","hepatic":"肝功能不全者注意糖皮质激素代谢，遵说明书","interact":"与非甾体抗炎药合用增加消化道出血；可降低降糖药疗效"},{"name":"大剂量地塞米松（替代一线方案）","dose":"40 mg/d 口服连用 4 天，每 2–4 周可重复 2–3 个疗程；或 0.4 mg/kg/d 口服 4 天；遵说明书与中心方案","note":"短期使用减少激素长期毒性；注意血糖与血压骤升、失眠","renal":"遵说明书","hepatic":"遵说明书","interact":"同泼尼松；与某些靶向药相互作用需查阅说明书"},{"name":"静脉注射免疫球蛋白（IVIG，一线/紧急）","dose":"0.4 g/kg/d 静脉滴注，连用 5 天；或 1 g/kg/d 连用 1–2 天（仅用于危急出血或术前快速提升，总量一般 ≤2 g/kg）；输注速率遵说明书","note":"用于严重出血、需快速提升或禁忌激素（妊娠、糖尿病、消化性溃疡）者；起效 24–48 h，疗效约 2–4 周；IgA 缺乏者慎用","renal":"肾功能不全者减量并缓慢输注（渗透性肾病风险）","hepatic":"遵说明书","interact":"与抗 CD20 单抗治疗间隔使用；输注时避免与其他药物同管"},{"name":"抗 D 免疫球蛋白（RhD 阳性、未切脾者）","dose":"50–75 μg/kg 静脉或肌注，单次，遵说明书","note":"可致溶血与 Hb 下降，需监测；RhD 阴性者禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与输血制品间隔使用"},{"name":"TPO 受体激动剂（艾曲泊帕/罗米司亭/阿伐曲泊帕）","dose":"艾曲泊帕 25–50 mg qd 口服（东亚人群常从 25 mg 起始），按血小板计数滴定；罗米司亭开始 1 μg/kg 皮下每周 1 次，按需滴定；遵说明书","note":"用于慢性/持续性 ITP 激素无效或需长期治疗者；艾曲泊帕需空腹（餐前或餐后 2 h）服用，监测肝功能与骨髓纤维化","renal":"遵说明书","hepatic":"艾曲泊帕肝功能异常者慎用，监测 ALT","interact":"艾曲泊帕与抗酸药、钙剂、铁剂、乳制品间隔 4 h 服用"},{"name":"利妥昔单抗（二线）","dose":"375 mg/m² 静脉滴注，每周 1 次，共 4 次；或 100 mg/m² 每周 1 次共 4 次；遵说明书","note":"慢性 ITP 有效率约 60%，起效需 4–8 周；筛查 HBV 并预防再激活","renal":"遵说明书","hepatic":"遵说明书","interact":"与活疫苗、其他免疫抑制剂合用增加感染风险"}],"nonDrug":["脾切除：二线治疗，适用于药物失败、病程 >6 个月、依赖激素/IVIG 或复发者；术前接种肺炎球菌、脑膜炎球菌、流感嗜血杆菌疫苗，术后按方案青霉素预防","严重出血（颅内、消化道大出血）：大剂量激素 + IVIG + 输注血小板，必要时急症脾切除、氨甲环酸辅助","幽门螺杆菌阳性者根除治疗，部分患者血小板可升高","避免影响血小板功能的药物（阿司匹林、NSAIDs）与接触性运动"],"life":["血小板 <30×10⁹/L 时避免剧烈活动与外伤，注意口腔卫生","手术或分娩前按目标血小板准备（一般 ≥50×10⁹/L，椎管内麻醉 ≥80×10⁹/L）","定期复查血常规，记录激素副作用与治疗反应","妊娠期 ITP 需血液科与产科共同管理，分娩前评估新生儿血小板"]},"prog":"儿童 ITP 约 70%–80% 在 6 个月内自发缓解；成人慢性者约 2/3 需长期治疗，但严重出血年发生率 <1%–2%。切脾后约 60%–70% 长期缓解；TPO 受体激动剂可使多数患者维持安全血小板水平。","refs":["中华医学会血液学分会血栓与止血学组. 成人原发免疫性血小板减少症诊断与治疗中国指南（2020 年版）","中华医学会血液学分会. 儿童原发性免疫性血小板减少症诊疗建议（2013）","Provan D, et al. Updated international consensus report on the investigation and management of primary immune thrombocytopenia. Blood Adv 2019"]},{"id":"dic","name":"弥散性血管内凝血","aka":["DIC","弥漫性血管内凝血","Disseminated Intravascular Coagulation"],"rank":2,"basic":{"define":"在严重感染、恶性肿瘤、产科并发症、严重创伤等诱因下凝血系统广泛激活、微血管内纤维蛋白沉积，导致凝血因子与血小板消耗、微血栓形成与继发纤溶亢进，临床表现为出血与器官功能障碍并存。","risk":["严重感染/脓毒症（革兰阴性菌、脑膜炎球菌）","恶性肿瘤：急性早幼粒细胞白血病、实体瘤（黏液腺癌）","产科：胎盘早剥、羊水栓塞、子痫、HELLP、死胎滞留","严重创伤、大手术、挤压综合征、烧伤","重症肝病、急性溶血性输血反应、毒蛇咬伤、重症胰腺炎"],"epi":"DIC 是危重症常见并发症，脓毒症患者发生率约 30%–50%；APL 初诊时 DIC 发生率高达 70%–90%，与早期出血死亡密切相关。"},"patho":"组织因子大量释放（损伤/肿瘤）或内毒素介导内皮细胞表达 TF，激活外源性凝血；生理性抗凝（AT、蛋白 C/S、TFPI）被消耗与下调；PAI-1 升高致微血栓沉积，继而纤溶酶原激活致纤维蛋白降解产物增加。微血栓引起肾、肺、肝缺血，消耗性低凝与纤溶亢进导致严重出血。","dx":{"criteria":["存在明确基础疾病或诱因，并有出血（瘀斑、穿刺点渗血、消化道/泌尿道出血）或多器官微血栓表现","血小板减少 <100×10⁹/L 或进行性下降（<50×10⁹/L 提示严重）","PT 延长 ≥3 s（或 INR >1.2）、APTT 延长","纤维蛋白原 <1.5 g/L 或进行性下降","D-二聚体显著升高、FDP 升高、3P 试验阳性","抗凝血酶活性下降、蛋白 C 活性降低（支持性证据）","ISTH 显性 DIC 评分 ≥5 分可确诊","外周血涂片见破碎红细胞（微血管病性溶血）"],"workup":["动态监测血常规、PT/APTT/INR、纤维蛋白原、D-二聚体/FDP（每 4–8 h 或随病情）","抗凝血酶、蛋白 C/S、凝血因子（Ⅴ、Ⅷ、Ⅹ）","外周血涂片（破碎红细胞、血小板形态）","肝功能、肾功能、LDH、胆红素、血乳酸","查找原发病：血培养、影像、产科超声、肿瘤评估与骨髓检查（疑 APL 立即查 PML-RARA）","ISTH 评分与病程分期"],"grading":"ISTH 显性 DIC 评分：PLT 降低（0–2 分）+ PT 延长（0–2 分）+ 纤维蛋白原降低（0–1 分）+ D-二聚体升高（0–2 分），≥5 分符合显性 DIC。病程分高凝血期、消耗性低凝期与继发纤溶亢进期。"},"ddx":[{"name":"免疫性血小板减少症（itp）","point":"与本类 itp 的鉴别点：ITP 为孤立性血小板减少、凝血指标正常；DIC 同时伴 PT/APTT 延长、纤维蛋白原降低与 D-二聚体显著升高。"},{"name":"血栓性微血管病（ttp）","point":"与本类 ttp 的鉴别点：TTP 以 MAHA 与血小板减少为主，PT/APTT 与纤维蛋白原多正常；DIC 凝血指标全面异常、纤维蛋白原低。"},{"name":"重症肝病性凝血障碍","point":"肝硬化 PT 延长、血小板减少但纤维蛋白原可正常或升高、凝血因子Ⅴ降低，无微血栓证据；DIC 有原发病加重的动态变化。"},{"name":"原发性纤溶亢进","point":"前列腺癌、某些蛇毒等所致纤维蛋白原显著降低、D-二聚体升高，但血小板与 PT 常正常。"},{"name":"HELLP 综合征/子痫前期","point":"妊娠晚期血小板减少、肝酶升高与溶血，可与 DIC 并存；需按产科急症评估并考虑终止妊娠。"}],"tx":{"drug":[{"name":"低分子肝素/普通肝素（以微血栓为主期）","dose":"依诺肝素 40–60 mg 皮下 q12h，或普通肝素持续泵入（APTT 维持 1.5–2.0 倍）；用于病因不能迅速去除、以微血栓或器官功能障碍为主者；遵说明书与中心方案","note":"禁用于活动性出血、近期手术、血小板 <30×10⁹/L 者；APL 相关 DIC 以纠正为主，抗凝需谨慎","renal":"CrCl <30 mL/min 用普通肝素或减量 LMWH","hepatic":"遵说明书；肝素过量用鱼精蛋白拮抗","interact":"与抗血小板药、抗凝药合用出血风险叠加"},{"name":"新鲜冰冻血浆（FFP）","dose":"10–15 mL/kg 静脉输注，用于 PT/APTT 显著延长伴活动性出血或需有创操作者；输注后复查凝血指标","note":"仅补充消耗性凝血因子，无出血时不作常规治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"注意容量负荷与输血反应"},{"name":"冷沉淀/纤维蛋白原浓缩剂","dose":"冷沉淀 1 U/10 kg，维持纤维蛋白原 ≥1.5 g/L（产科、创伤目标 1.5–2.0 g/L）；纤维蛋白原浓缩剂按需 1–2 g 输注；遵说明书","note":"纤维蛋白原 <1.5 g/L 且出血时应补充，补充后复查","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"血小板输注","dose":"血小板 <20×10⁹/L 伴活动性出血或需有创操作时输注单采血小板 1 个治疗量；目标计数按出血程度与术式（一般 ≥50×10⁹/L）","note":"DIC 中血小板消耗快，输注后需复查效果","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"抗凝血酶（AT）浓缩剂","dose":"AT 活性 <50%–60% 且有微血栓或肝素抵抗时考虑，剂量遵说明书；证据有限，需个体化","note":"脓毒症相关 DIC 研究结果不一致，仅特定情况使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与肝素合用增强抗凝，需监测 APTT"},{"name":"氨甲环酸（继发纤溶亢进为主时）","dose":"1 g 静脉缓慢推注后 1 g 维持 8 h，或按出血程度调整，遵说明书","note":"仅高纤溶为主导时考虑；高凝期单独使用可加重血栓","renal":"肾功能不全者减量，遵说明书","hepatic":"遵说明书","interact":"与雌激素类药物合用增加血栓风险"}],"nonDrug":["原发病治疗是核心：抗感染与感染源控制、产科并发症及时终止妊娠、APL 特异治疗（ATRA/ATO）、创伤止血与手术","APL 合并 DIC：早期 ATRA 联合支持治疗，避免不必要的肝素化与侵入操作","严重出血：局部压迫、内镜下止血、容量与血制品替代","器官功能障碍：CRRT、机械通气、升压药等器官支持","避免常规使用抗纤溶药物（高凝期）"],"life":["危重症监护，按诱因控制程度动态监测凝血并调整治疗","恢复期评估器官损害与血栓并发症；抗凝疗程依血栓性质与病史制定","产科患者随访凝血与新生儿情况","APL 患者长期随访白血病治疗与 DIC 防复发"]},"prog":"预后取决于基础疾病。脓毒症相关 DIC 病死率 30%–50%，APL 相关 DIC 经 ATRA 等特异治疗后显著改善；及时病因控制、动态监测与恰当的血制品支持是降低死亡的关键。","refs":["中华医学会血液学分会血栓与止血学组. 弥散性血管内凝血诊断与治疗中国专家共识（2017 年版）","中华医学会血液学分会. 中国急性早幼粒细胞白血病诊疗指南","Taylor FB Jr, et al. Towards definition, clinical and laboratory criteria for DIC. Thromb Haemost 2001"]},{"id":"ttp","name":"血栓性微血管病（含 TTP）","aka":["TMA","TTP","血栓性血小板减少性紫癜","Thrombotic Thrombocytopenic Purpura","HUS"],"rank":3,"basic":{"define":"以微血管病性溶血性贫血（MAHA）与血小板减少为核心的一组综合征，包括 ADAMTS13 缺乏所致血栓性血小板减少性紫癜（TTP）、补体旁路激活所致非典型溶血尿毒综合征（aHUS）及产志贺毒素 HUS（STEC-HUS）。","risk":["TTP：获得性 ADAMTS13 自身抗体（多为中年女性）、妊娠（约占 10%–20%）、严重感染","aHUS：补体调节基因（CFH、CFI、MCP、C3）突变或抗 CFH 抗体","STEC-HUS：产志贺毒素大肠杆菌 O157:H7 感染（儿童多见）","药物、自身免疫病、肿瘤、造血干细胞移植（继发性 TMA）"],"epi":"TTP 年发病率约 1–3/100 万，女性居多（约 3:1），未治疗存活率 <10%；及时血浆置换可降至 <20%。STEC-HUS 儿童多见；aHUS 少见但易复发。"},"patho":"TTP 中 ADAMTS13 活性严重降低（<10%），无法裂解 vWF 超大分子，vWF 多聚体在微血管内形成血小板血栓，致机械性溶血（破碎红细胞）与血小板消耗；aHUS 中补体旁路持续激活损伤内皮，同样形成微血栓。缺血累及肾、脑、心等器官。","dx":{"criteria":["MAHA：Hb 下降、网织红细胞升高、LDH 显著升高（常 >1000 U/L）、结合珠蛋白降低、间接胆红素升高、Coombs 试验阴性","血小板减少 <100×10⁹/L（TTP 常 <30×10⁹/L）","外周血涂片破碎红细胞 ≥1%，伴多形性红细胞","TTP 确诊：ADAMTS13 活性 <10%（获得性常伴抑制物）","经典五联征：MAHA、血小板减少、神经精神症状、肾功能损害、发热，但非必须全部具备","aHUS：ADAMTS13 活性 >10%，补体调节基因异常或抗 CFH 抗体，排除 STEC 感染","STEC-HUS：粪便志贺毒素或培养阳性"],"workup":["血常规 + 网织红细胞 + 外周血涂片（人工计数破碎红细胞）","LDH、间接胆红素、结合珠蛋白、Coombs 试验","PT/APTT、纤维蛋白原、D-二聚体（TMA 通常正常，与 DIC 鉴别）","肾功能、尿常规与尿蛋白定量","ADAMTS13 活性与抑制物（尽早送检，但不等待结果再开始血浆置换）","补体检查（CH50、C3、C4、抗 CFH 抗体）、粪便志贺毒素","头颅 CT/MRI、心电图与心肌酶，必要时肾活检","育龄女性妊娠试验"],"grading":"按病因分 TTP（遗传性/获得性）、HUS（STEC、aHUS、肺炎球菌相关）与继发性 TMA。严重度参考 ADAMTS13 活性与器官受累（神经、心脏）。"},"ddx":[{"name":"免疫性血小板减少症（itp）","point":"与本类 itp 的鉴别点：ITP 为孤立性血小板减少、Hb 与网织红细胞正常、无破碎红细胞、LDH 正常；TTP 伴 MAHA 与碎裂红细胞。"},{"name":"DIC（dic）","point":"与本类 dic 的鉴别点：TTP 的 PT/APTT 与纤维蛋白原正常、碎裂红细胞显著、ADAMTS13 极低；DIC 凝血指标全面异常并有脓毒症/产科/肿瘤等诱因。"},{"name":"STEC-HUS","point":"儿童多见，先有血性腹泻，肾功能损害突出，多可自限；TTP 成人多见、以神经症状为主、ADAMTS13 极低，处理不同。"},{"name":"Evans 综合征","point":"Coombs 阳性自身免疫性溶血伴 ITP，球形红细胞增多，破碎红细胞少、ADAMTS13 正常。"},{"name":"子痫前期/HELLP 综合征","point":"妊娠晚期高血压、蛋白尿、肝酶升高与血小板减少，终止妊娠后多缓解；TTP 分娩后仍活动且 ADAMTS13 低。"}],"tx":{"drug":[{"name":"血浆置换/新鲜冰冻血浆输注（首要治疗）","dose":"血浆置换 1–1.5 个血浆容量（约 40–60 mL/kg）/次，每日 1 次，直至血小板 >150×10⁹/L 且 LDH 正常连续 2 天；无法置换时输注 FFP 10–30 mL/kg","note":"疑诊即刻开始，不等 ADAMTS13 结果；置换液用新鲜冷冻血浆（不用冷沉淀）；难治时双倍置换","renal":"遵说明书","hepatic":"遵说明书","interact":"注意容量负荷与过敏反应"},{"name":"糖皮质激素（甲泼尼龙/泼尼松）","dose":"甲泼尼龙 1 mg/kg/d 静脉，或泼尼松 1 mg/kg/d 口服，与血浆置换同步，缓解后逐渐减量；遵说明书","note":"常与血浆置换联合；合并感染需评估","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道出血"},{"name":"利妥昔单抗","dose":"375 mg/m² 静脉，每周 1 次，共 4 次；用于难治/复发或初诊重症；遵说明书","note":"降低复发率；需筛查 HBV；起效需数周，期间继续血浆置换","renal":"遵说明书","hepatic":"遵说明书","interact":"与活疫苗间隔；与其他免疫抑制剂合用增加感染风险"},{"name":"卡普赛珠单抗（caplacizumab，抗 vWF 纳米抗体）","dose":"首次 11 mg（或 10 mg）静脉，随后 11 mg（或 10 mg）皮下每日 1 次，血浆置换期间同用，置换结束后继续 30 天；遵说明书与获批适应证","note":"加快血小板恢复、减少复发与死亡，但出血风险增加；部分地区未上市","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗血小板/抗凝药合用增加出血"},{"name":"依库珠单抗（补体 C5 抑制剂，aHUS）","dose":"成人 900 mg 静脉每周 1 次共 4 周，之后 1200 mg 每 2 周 1 次；儿童按体重（遵说明书）","note":"aHUS 首选；需脑膜炎球菌疫苗或抗生素预防；与血浆置换同期按说明书调整给药时机","renal":"遵说明书","hepatic":"遵说明书","interact":"与血浆输注同期需按说明书调整"},{"name":"血小板输注（严格限制）","dose":"仅在危及生命的活动性出血或急症手术前输注 1 个治疗量；TTP 中常规禁用","note":"预防性输注可加重微血栓，需同时加强血浆置换","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["血浆置换为首要治疗，同时加强神经、心脏、肾功能监护","难治性 TTP：双倍容量血浆置换、联合利妥昔单抗或卡普赛珠单抗","STEC-HUS：以支持治疗为主（水化、透析、避免抗动力药与抗生素），不宜血浆置换或依库珠单抗","aHUS：以依库珠单抗为主，补体基因异常者长期治疗","避免使用血小板刺激剂、雌激素与抗血小板药"],"life":["缓解后长期监测 ADAMTS13 活性与抑制物（复发高危者每 3–6 个月，妊娠期更密切）","妊娠期复发风险高，需血液科与产科联合管理","利妥昔单抗治疗后注意感染与 HBV 再激活","aHUS 长期补体监测与依库珠单抗维持"]},"prog":"TTP 未治疗病死率 >90%；及时血浆置换+激素后缓解率 70%–90%，仍有 10%–20% 死亡，复发率可达 30%–40%（ADAMTS13 持续 <10% 者更高）。aHUS 经依库珠单抗治疗后显著改善；STEC-HUS 多数恢复但部分遗留 CKD。","refs":["中华医学会血液学分会血栓与止血学组. 血栓性微血管病诊断与治疗中国专家共识","中华医学会血液学分会. 血栓性血小板减少性紫癜诊断与治疗中国专家共识","Zheng XL, et al. ISTH guidelines for treatment of thrombotic thrombocytopenic purpura. J Thromb Haemost 2020"]}]},{"id":"anemia_more","name":"其他贫血","rank":4,"summary":"网织红细胞升高伴间接胆红素、LDH 升高和结合珠蛋白降低提示溶血，先做 Coombs 与涂片分流免疫性与非免疫性。免疫性以糖皮质激素为一线，遗传性以去诱因、补叶酸和必要时输血为主；地中海贫血靠血红蛋白电泳确诊，输血依赖者必须规范祛铁。","compare":[{"diseaseId":"he_hemolytic","dx":"贫血 + 网织升高 + 间接胆红素与 LDH 升高、结合珠蛋白降低","key":"溶血总论：非结合胆红素升高伴网织升高即溶血，再以 Coombs 二分"},{"diseaseId":"he_hs","dx":"G6PD 缺乏：氧化性药物或蚕豆暴露后急性溶血、血红蛋白尿；HS：显性遗传、脾大、球形红细胞 >10%、渗透脆性增加","key":"球形红细胞 + 渗透脆性 → HS；诱因后血红蛋白尿 → G6PD"},{"diseaseId":"he_aiha","dx":"网织高 + Coombs（DAT）阳性，温抗体型多见、脾大、黄疸","key":"DAT 阳性是关键，温抗体型首选激素 1 mg/kg/d"},{"diseaseId":"he_thal","dx":"小细胞低色素而铁蛋白不低，HbA2 升高（β 型）或 HbH 包涵体（α 型），有南方地域家族史","key":"小细胞低色素 + 铁代谢正常 + 地域史，勿长期按缺铁补铁"}],"diseases":[{"id":"he_hemolytic","name":"溶血性贫血（总论）","aka":["Hemolytic Anemia","溶血性贫血","HA"],"rank":1,"basic":{"define":"红细胞寿命缩短、破坏加速而骨髓代偿不足所致的贫血。网织红细胞已明显升高但尚无贫血者为溶血状态，出现贫血即为溶血性贫血；按部位分血管内与血管外溶血，按病因分遗传性与获得性。","risk":["红细胞膜、酶（G6PD、丙酮酸激酶）或血红蛋白异常","自身免疫、药物（甲基多巴、头孢类）、支原体与 EBV 感染","微血管病（TMA、DIC、HELLP）与机械性溶血","阵发性睡眠性血红蛋白尿（PNH）、脾功能亢进"],"epi":"我国以自身免疫性溶血性贫血与 G6PD 缺乏症较常见，南方诸省 G6PD 缺乏与地中海贫血高发。溶血性贫血约占全部贫血的 5%～10%。"},"patho":"红细胞破坏超过骨髓代偿能力（可达 6～8 倍）时出现贫血。血管内溶血时游离血红蛋白耗竭结合珠蛋白，出现血红蛋白尿与含铁血黄素尿，可致急性肾损伤；血管外溶血由脾脏巨噬细胞清除，表现为脾大、黄疸与胆石症。慢性溶血消耗叶酸，儿童可致红系扩张与骨骼改变。","dx":{"criteria":["贫血伴网织红细胞升高（>0.02～0.04，绝对值 >100×10⁹/L）","间接胆红素与 LDH 升高、结合珠蛋白降低、游离血红蛋白升高","尿胆原与粪胆原增加；血管内溶血时尿隐血或含铁血黄素阳性而无镜下红细胞","涂片见球形红细胞、破碎红细胞、嗜多色性红细胞","定性后查病因：Coombs、G6PD 活性、渗透脆性、血红蛋白电泳、PNH 克隆"],"workup":["血常规 + 网织红细胞 + 外周血涂片","胆红素、LDH、结合珠蛋白、游离血红蛋白","尿常规（尿胆原、隐血）与尿含铁血黄素","直接与间接抗人球蛋白试验（Coombs）","G6PD 活性（溶血期及输血后可假性正常，宜恢复期复查）","血红蛋白电泳、渗透脆性、流式 PNH 克隆","腹部超声（脾大、胆石）、必要时骨髓检查"],"grading":"按部位分血管内（血红蛋白尿、含铁血黄素尿）与血管外溶血（脾大、黄疸、粪胆原增加）；按病程分急性与慢性；按病因分遗传性与获得性。"},"ddx":[{"name":"G6PD 缺乏症与遗传性球形红细胞增多症（he_hs）","point":"与本类 he_hs 的鉴别点：HS 见球形红细胞群与渗透脆性增加；G6PD 缺乏有氧化性诱因、Heinz 小体与血红蛋白尿。"},{"name":"自身免疫性溶血性贫血（he_aiha）","point":"与本类 he_aiha 的鉴别点：DAT 阳性是免疫性溶血的关键证据，总论阶段先完成 Coombs 再下结论。"},{"name":"缺铁性贫血（ida）","point":"与本科室 ida 的鉴别点：缺铁时网织不升、铁蛋白降低、间接胆红素正常。"},{"name":"微血管病性溶血（TTP/HUS）","point":"伴血小板减少、碎裂红细胞与肾或神经损害，属急症须立即分开处理。"}],"tx":{"drug":[{"name":"叶酸","dose":"5 mg qd 口服，长期补充；遵说明书","note":"慢性溶血红系增生旺盛致叶酸相对缺乏，不可单用叶酸替代病因治疗。","renal":"遵说明书","hepatic":"遵说明书","interact":"与甲氨蝶呤、乙胺嘧啶相互拮抗"},{"name":"碳酸氢钠","dose":"急性血管内溶血时静脉碱化尿液，遵说明书","note":"减少血红蛋白管型、保护肾功能，配合水化与利尿。","renal":"注意钠负荷","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["去除诱因：停药、控制感染、G6PD 缺乏者避蚕豆与氧化性药物","Hb <60 g/L 或有症状时输血，配血须做不规则抗体筛查","脾切除：用于 HS、脾功能亢进及内科无效的温抗体型 AIHA","PNH 用补体抑制剂，由血液专科评估","慢性溶血监测胆石症与铁过载"],"life":["避免劳累与感染；G6PD 缺乏者禁用磺胺、伯氨喹、呋喃妥因、萘","定期复查血常规、网织红细胞、胆红素与 LDH","妊娠期需多学科管理并补充叶酸"]},"prog":"预后取决于病因：G6PD 缺乏与 HS 避免诱因后多良好；AIHA 多数对激素有效但部分复发。慢性溶血需警惕胆石症、铁过载与儿童骨骼发育异常。","refs":["《内科学》第 9 版 溶血性贫血","中华医学会血液学分会《自身免疫性溶血性贫血诊断与治疗中国专家共识（2017 年版）》"]},{"id":"he_hs","name":"G6PD 缺乏症与遗传性球形红细胞增多症","aka":["G6PD Deficiency","Hereditary Spherocytosis","蚕豆病","HS"],"rank":2,"basic":{"define":"两类遗传性溶血性贫血：G6PD 缺乏症为 X 连锁磷酸戊糖途径酶缺陷，氧化应激下发生急性血管内溶血；遗传性球形红细胞增多症（HS）多为常染色体显性遗传的膜骨架蛋白缺陷，红细胞呈球形并在脾脏破坏增加。","risk":["G6PD 缺乏者男性多见，广东、广西、云南、海南等高发，可有新生儿黄疸","G6PD 诱因：蚕豆、伯氨喹、磺胺类、呋喃妥因、萘（樟脑丸）、感染","HS 约 75% 有显性遗传家族史，可伴胆石症与小腿溃疡","HS 可因感染或剧烈运动诱发溶血危象"],"epi":"我国 G6PD 缺乏症南方筛查阳性率约 4%～8%，广东部分人群达 5%～10%；HS 在西方发病率约 1/2000，我国较少见但为遗传性溶血的重要原因。"},"patho":"G6PD 缺乏时 NADPH 生成不足，谷胱甘肽系统无法清除氧化物，血红蛋白变性形成 Heinz 小体，膜脂质过氧化致血管内溶血。HS 中锚蛋白、带 3 蛋白、血影蛋白缺陷使红细胞膜面积减少、变形性下降，在脾脏微循环被扣留破坏，形成血管外溶血。","dx":{"criteria":["G6PD 缺乏：诱因后突发溶血，血红蛋白尿、黄疸、网织升高，G6PD 活性降低（溶血高峰与输血后可假性正常）","南方地区新生儿高胆红素血症应常规筛查 G6PD","HS：贫血伴网织升高，球形红细胞 >10%，MCHC >345 g/L，渗透脆性增加，有家族史","两者 Coombs 均阴性，须排除 AIHA 与地中海贫血"],"workup":["血常规 + 网织红细胞 + 外周血涂片","G6PD 活性测定或荧光斑点试验、Heinz 小体活体染色","红细胞渗透脆性试验（孵育后更敏感），HS 可加 EMA 结合试验","Coombs 试验与血红蛋白电泳","腹部超声看脾大与胆石；新生儿监测胆红素并查母婴血型"],"grading":"G6PD 缺乏按 WHO 酶活性分 5 型，Ⅲ型（10%～60%）在我国多见，仅诱因下溶血；HS 按 Hb 分轻（>110 g/L）、中（80～110 g/L）、重（<80 g/L）与极重（输血依赖）。"},"ddx":[{"name":"自身免疫性溶血性贫血（he_aiha）","point":"与本类 he_aiha 的鉴别点：AIHA 的 DAT 阳性、无家族史；本条两者 DAT 均阴性。"},{"name":"地中海贫血（he_thal）","point":"与本类 he_thal 的鉴别点：地贫为小细胞低色素伴 HbA2 升高；HS 的 MCHC 反而升高。"},{"name":"溶血性贫血总论（he_hemolytic）","point":"总论给出溶血判断框架，本条为其遗传性病因的具体化。"},{"name":"新生儿 ABO 或 Rh 溶血病","point":"新生儿黄疸需先以母婴血型与 Coombs 排除同种免疫性溶血。"}],"tx":{"drug":[{"name":"叶酸","dose":"5 mg qd 口服，长期补充；遵说明书","note":"儿童与妊娠期尤需补充。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"苯巴比妥（新生儿黄疸）","dose":"按体重个体化，遵说明书","note":"诱导葡萄糖醛酸转移酶，仅用于评估后的轻中度黄疸，重症以光疗或换血为主。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["G6PD 缺乏：去诱因，重症输红细胞（供血者亦需筛查 G6PD），水化碱化尿液护肾","新生儿 G6PD 缺乏性黄疸：光疗为主，极高胆红素换血预防胆红素脑病","HS：Hb <80 g/L 或输血依赖者行脾切除（建议 6 岁以上，术前接种肺炎链球菌、脑膜炎球菌与 Hib 疫苗）","HS 合并症状性胆石行胆囊切除；育龄患者遗传咨询与产前筛查"],"life":["G6PD 缺乏者随身携带警示卡，禁用蚕豆、磺胺、伯氨喹、呋喃妥因、萘","脾切除后终身预防感染，发热立即就医","定期复查血常规与胆红素，儿童关注生长发育"]},"prog":"G6PD 缺乏多终身无症状，避免诱因预后良好，严重溶血并发急性肾损伤可致命。HS 脾切除后贫血多可纠正，但须终身警惕脾切除后暴发性感染。","refs":["《内科学》第 9 版 溶血性贫血","中华医学会儿科学分会《葡萄糖-6-磷酸脱氢酶缺乏症筛查与诊断专家共识（2017）》"]},{"id":"he_aiha","name":"自身免疫性溶血性贫血","aka":["AIHA","Autoimmune Hemolytic Anemia","温抗体型自身免疫性溶血性贫血"],"rank":3,"basic":{"define":"自身抗体或补体介导红细胞破坏加速的获得性溶血性贫血，直接抗人球蛋白试验（DAT）多阳性。按反应温度分温抗体型（约 80%～90%）、冷抗体型与混合型，按病因分原发与继发。","risk":["温抗体型以中年女性多见，常伴系统性红斑狼疮等自身免疫病","继发于慢性淋巴细胞白血病、淋巴瘤、实体瘤（卵巢畸胎瘤）","感染：EBV、支原体肺炎、HIV、梅毒","药物：甲基多巴、青霉素类、头孢类、奎尼丁、利福平","妊娠期加重，抗体可经胎盘致新生儿溶血"],"epi":"成人年发病率约 1～3/10 万，温抗体型占多数，发病高峰 40～60 岁；冷抗体型多见于老年人，寒冷季节加重。"},"patho":"温抗体多为 IgG，与红细胞膜抗原结合后主要在脾脏经 Fcγ 受体介导的巨噬细胞清除（血管外溶血），部分激活补体。冷抗体多为 IgM，低温结合 I/i 抗原激活补体，C3b 包被红细胞在肝脏破坏。自身抗体还可抑制造血，加重贫血。","dx":{"criteria":["贫血、网织升高、间接胆红素与 LDH 升高、结合珠蛋白降低","DAT 阳性是关键证据；温抗体型多为 IgG 或 C3 阳性，冷抗体型多为 C3 阳性","温抗体型有黄疸与脾大；冷抗体型遇冷肢端发绀、冷凝集素效价 ≥1:64","排除 G6PD 缺乏、地贫、TMA、机械性溶血与 PNH","查继发因素：抗核抗体谱、淋巴增殖性疾病、胸腹 CT、感染与用药史"],"workup":["血常规 + 网织红细胞 + 涂片（球形红细胞、自身凝集）","DAT 与间接 Coombs（配血）、补体 C3/C4、免疫球蛋白定量","胆红素、LDH、结合珠蛋白、肾功能","冷凝集素效价、冷球蛋白、抗核抗体谱、抗磷脂抗体","胸腹 CT、淋巴结超声、必要时骨髓检查","血型与不规则抗体鉴定"],"grading":"温抗体型按 Hb 分轻（>100 g/L）、中（80～100 g/L）、重（<80 g/L）与危重（急性进展、需输血）；冷抗体型按冷凝集素效价与肢端缺血症状分级。"},"ddx":[{"name":"G6PD 缺乏与遗传性球形红细胞增多症（he_hs）","point":"与本类 he_hs 的鉴别点：两者 DAT 阴性、有家族史或酶缺陷；AIHA 的 DAT 阳性。"},{"name":"地中海贫血（he_thal）","point":"与本类 he_thal 的鉴别点：地贫 DAT 阴性、小细胞低色素伴 HbA2 升高。"},{"name":"微血管病性溶血（TTP/HUS）","point":"伴血小板减少、碎裂红细胞与 ADAMTS13 降低，DAT 阴性，须紧急血浆置换。"},{"name":"药物诱导的免疫性溶血","point":"有明确用药史，停药后溶血缓解，据此与原发性 AIHA 鉴别。"}],"tx":{"drug":[{"name":"泼尼松","dose":"1 mg/(kg·d) 口服（成人常 40～60 mg/d），Hb 正常后缓慢减量，多数于 4～6 个月内尝试停药","note":"温抗体型一线；3 周无反应判断无效并换方案，减量过快易复发。需补钙与维生素 D，监测血糖、血压与感染。","renal":"遵说明书","hepatic":"肝功能不全者遵说明书","interact":"与布洛芬等非甾体抗炎药合用增加消化道出血；酮康唑、伊曲康唑升高其浓度"},{"name":"利妥昔单抗","dose":"375 mg/m² 静滴，每周 1 次×4 次（或 100 mg 每周 1 次×4 次）；遵说明书","note":"激素无效、依赖或复发者的首选二线，冷抗体型常首选；警惕乙肝再激活与感染。","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用增加感染风险"},{"name":"环孢素 / 硫唑嘌呤","dose":"遵说明书，按体重或血药浓度调整","note":"用于激素无效或需减停激素者；硫唑嘌呤用药前查 TPMT 并监测血象。","renal":"环孢素有肾毒性，肾功能不全慎用","hepatic":"遵说明书","interact":"环孢素与唑类抗真菌药、大环内酯类合用浓度升高"},{"name":"静脉免疫球蛋白","dose":"0.4 g/(kg·d)×5 天；遵说明书","note":"用于重症、合并感染或妊娠期不宜大剂量激素者，起效快但维持短。","renal":"注意容量负荷与血栓","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["输血仅在 Hb <60 g/L 且有缺氧症状时缓慢滴注，完成交叉配血与抗体鉴定","脾切除：激素与利妥昔单抗无效的温抗体型二线选择，术前接种疫苗","血浆置换：重症冷抗体型或急性危重溶血时辅助","继发性 AIHA 针对原发病（停药、治疗肿瘤、控制狼疮）","妊娠期首选激素，避免脾切除，产科与血液科联合管理"],"life":["温抗体型避免感染与劳累；冷抗体型注意保暖，避免冷饮与冷水","长期激素者补钙、补维生素 D、监测骨密度","定期复查血常规、网织红细胞与 DAT，警惕复发"]},"prog":"温抗体型约 70%～80% 初始对激素有效，但减量后约半数复发，1/3 最终需二线治疗；冷抗体型对激素反应差。总体病死率约 5%～10%，主要死于感染与血栓。","refs":["《内科学》第 9 版 自身免疫性溶血性贫血","中华医学会血液学分会《成人自身免疫性溶血性贫血诊断与治疗中国专家共识（2023 年版）》"]},{"id":"he_thal","name":"地中海贫血","aka":["Thalassemia","珠蛋白生成障碍性贫血","海洋性贫血","地贫"],"rank":4,"basic":{"define":"珠蛋白基因缺失或突变致肽链合成减少，引起小细胞低色素性遗传性溶血性贫血。按受累链分 α 与 β 地中海贫血，临床分静止型、轻型、中间型与重型。","risk":["祖籍广东、广西、海南、云南、贵州、四川等高发区","父母双方均为携带者","家族史或既往生育过重型地贫患儿","近亲婚配"],"epi":"我国广东、广西 α 与 β 地贫携带率各约 5%～8%，部分地区达 10%；全球约 1.5% 人口为 β 地贫携带者。"},"patho":"α 与 β 链合成失衡，未配对链在幼红细胞内沉积形成包涵体，导致骨髓内无效造血与脾脏破坏；无效造血致骨髓扩张、骨骼畸形与髓外造血，同时抑制铁调素、增加肠道铁吸收，合并反复输血形成铁过载。","dx":{"criteria":["小细胞低色素贫血（MCV <80 fl、MCH <27 pg），铁蛋白与铁代谢不低","β 地贫：血红蛋白电泳 HbA2 >3.5%（携带者常 >4%）、HbF 升高","α 地贫：电泳多正常，HbH 病可见 HbH 包涵体","重型 β 地贫于出生 3～6 个月后出现进行性贫血、肝脾大与颅面畸形","基因检测是确诊与产前诊断的金标准"],"workup":["血常规 + 网织红细胞 + 涂片（靶形红细胞、嗜碱性点彩）","血清铁、铁蛋白、总铁结合力","血红蛋白电泳与 HbA2、HbF 定量；α 与 β 珠蛋白基因检测","肝铁浓度与心脏铁 T2*（反复输血者）","肝功能、胆红素、LDH、乙肝与丙肝筛查","肝脾超声与胆囊结石；家系筛查与遗传咨询"],"grading":"β 地贫：轻型（携带者）、中间型（Hb 60～90 g/L）、重型（Hb <60 g/L，需定期输血）。α 地贫：静止型与轻型近无症状，HbH 病为中间型，Hb Bart's 水肿胎为胎儿死亡。"},"ddx":[{"name":"缺铁性贫血（ida）","point":"与本科室 ida 的鉴别点：缺铁者铁蛋白降低、补铁有效；地贫铁蛋白不低、HbA2 升高、补铁无效。"},{"name":"遗传性球形红细胞增多症（he_hs）","point":"与本类 he_hs 的鉴别点：HS 为球形红细胞群、MCHC 升高；地贫为靶形红细胞。"},{"name":"慢性病性贫血","point":"伴慢性感染或肿瘤，铁蛋白正常或升高而血清铁与总铁结合力降低。"},{"name":"铁粒幼细胞性贫血","point":"环形铁粒幼细胞 >15%，属骨髓增生异常范畴，SF3B1 突变有助鉴别。"}],"tx":{"drug":[{"name":"去铁胺","dose":"20～60 mg/(kg·d) 皮下泵入 8～12 小时；遵说明书","note":"铁蛋白 >1000 µg/L 或输血 >10 单位时启动，监测铁蛋白与心铁 T2*。","renal":"肾功能不全需减量并监测","hepatic":"肝功能异常者监测","interact":"维生素 C 增加铁排泄但可加重心脏毒性，须在充分祛铁后小剂量使用"},{"name":"去铁酮","dose":"75～99 mg/(kg·d) 分 3 次口服；遵说明书","note":"对心脏铁清除较好；每 1～2 周监测中性粒细胞，警惕粒细胞缺乏。","renal":"肾功能不全需调整","hepatic":"肝功能异常者慎用","interact":"可与去铁胺联合增效，需监测血象"},{"name":"地拉罗司","dose":"20～30 mg/(kg·d) 口服每日 1 次；遵说明书","note":"口服方便；定期监测肾功能、尿蛋白与肝功能。","renal":"eGFR <40 者慎用或减量","hepatic":"重度肝损伤禁用","interact":"利福平、苯妥英等 CYP3A4 诱导剂降低其疗效"},{"name":"叶酸","dose":"5 mg qd 口服；遵说明书","note":"补充慢性溶血消耗。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"羟基脲（中间型或 HbH 病）","dose":"10～20 mg/(kg·d) 口服；遵说明书","note":"诱导 HbF、减少输血需求，监测血象。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["重型 β 地贫定期输血维持 Hb >90～100 g/L，输注去白细胞红细胞","输血依赖者规范祛铁，目标铁蛋白 <1000 µg/L，心铁 T2* <20 ms 提示过载","脾切除适用于输血需求大或脾功能亢进者，增加感染与血栓风险，儿童宜延迟","造血干细胞移植是重型 β 地贫的根治手段，优先 <14 岁且有 HLA 相合供者","产前诊断：孕 10～14 周绒毛或 16～20 周羊水基因检测"],"life":["高发区婚前与孕前筛查，遗传咨询与携带者宣教","输血者监测血源性感染，规范疫苗接种","避免误服铁剂，注意维生素 C 与祛铁剂配伍时机","患儿评估生长发育、骨密度与内分泌功能"]},"prog":"轻型与静止型无症状；HbH 病与中间型可长期存活但需间歇输血。重型 β 地贫不输血多在 5 岁内死亡，规律输血加祛铁可显著延长生存，铁过载性心脏病仍为主要死因。","refs":["《内科学》第 9 版 地中海贫血","中华医学会血液学分会《重型β地中海贫血的诊断和治疗指南（2017 年版）》","国家卫生健康委《地中海贫血防控方案（2019）》"]}]},{"id":"mds_mds","name":"骨髓增殖与淋巴","rank":5,"summary":"MDS 以血细胞减少伴病态造血为核心，按 IPSS-R 决定支持治疗或去甲基化；ALL 急性起病，流式与遗传学定型后按危险分层诱导；霍奇金淋巴瘤靠病理确诊，ABVD 为经典一线；PV 与 ET 以 JAK2/CALR/MPL 突变和血栓风险为中心，降细胞与抗栓并进。","compare":[{"diseaseId":"he_mds","dx":"中老年，贫血伴一系或多系减少，骨髓病态造血 ≥10%，原始细胞 <20%，可见 -5/del(5q)、-7、+8、del(20q)","key":"血细胞减少 + 病态造血 + 原始细胞 <20%，以 IPSS-R 分层"},{"diseaseId":"he_all","dx":"急性起病，贫血、出血、感染；骨髓原始淋巴细胞 ≥20%，表型为 B 或 T 系","key":"原始细胞 ≥20% 且为淋巴系，MRD 决定危险分层"},{"diseaseId":"he_hl","dx":"无痛性颈部或纵隔淋巴结肿大，病理见 Reed-Sternberg 细胞（CD15+、CD30+、CD20−）","key":"病理确诊，ABVD 为一线方案"},{"diseaseId":"he_mpn","dx":"PV：Hb 男 >165 g/L、女 >160 g/L 伴 JAK2 突变；ET：血小板 ≥450×10⁹/L 伴 JAK2/CALR/MPL 突变","key":"MPN 以驱动突变 + 骨髓增殖 + 血栓风险分层为核心"}],"diseases":[{"id":"he_mds","name":"骨髓增生异常综合征","aka":["MDS","Myelodysplastic Syndromes","骨髓增生异常综合征"],"rank":1,"basic":{"define":"起源于造血干细胞的克隆性疾病，以一系或多系病态造血、无效造血与血细胞减少为特征，有向急性髓系白血病转化风险；按原始细胞比例、环状铁粒幼细胞与 del(5q) 划分亚型。","risk":["年龄 >60 岁为最主要危险因素","既往化疗（烷化剂、拓扑异构酶抑制剂）或放疗","苯、甲醛等有机溶剂长期暴露","吸烟与胚系易感基因（GATA2、DDX41）突变","长期免疫抑制"],"epi":"发病率随年龄升高，>70 岁可达 30～50/10 万；西方中位发病年龄约 70 岁，我国报道较年轻，约 60 岁，男性略多。"},"patho":"造血干细胞获得性突变（SF3B1、TET2、ASXL1、SRSF2、DNMT3A、TP53 等）使异常克隆选择性扩增，正常造血受抑，出现无效红系生成与病态造血；表观遗传与剪接异常阻碍分化成熟。克隆演化中累积突变（尤其 TP53）促向 AML 转化。","dx":{"criteria":["持续 ≥4 个月的一系或多系减少：Hb <100 g/L、中性粒细胞 <1.8×10⁹/L 或血小板 <100×10⁹/L","骨髓一系或多系病态造血 ≥10%，或环状铁粒幼细胞 ≥15%（≥5% 伴 SF3B1 突变者亦可）","骨髓原始细胞 <20%（≥20% 诊断 AML，5%～19% 为伴原始细胞增多型）","有克隆性细胞遗传学异常或体细胞突变","排除维生素 B12 或叶酸缺乏、铜缺乏、药物、酒精、HIV、再障、PNH 与大颗粒淋巴细胞白血病"],"workup":["血常规 + 网织红细胞 + 涂片（颗粒减少、Pelger-Huët 样核、大红细胞）","骨髓穿刺与活检（增生程度、原始细胞、纤维化）","骨髓铁染色、流式细胞术","染色体核型与 FISH（-5/5q-、-7/7q-、20q-、+8）","二代测序（SF3B1、TET2、ASXL1、SRSF2、DNMT3A、TP53、RUNX1、EZH2）","维生素 B12、叶酸、血清铜、促甲状腺激素、HIV；自身抗体与 PNH 克隆"],"grading":"IPSS-R 按原始细胞比例、细胞遗传学、血红蛋白、血小板与中性粒细胞赋分：极低危 ≤1.5（中位生存 8.8 年）、低危 >1.5～3（5.3 年）、中危 >3～4.5（3.0 年）、高危 >4.5～6（1.6 年）、极高危 >6（0.8 年）。分子整合的 IPSS-M 可进一步细化。"},"ddx":[{"name":"急性淋巴细胞白血病（he_all）","point":"与本类 he_all 的鉴别点：ALL 原始细胞 ≥20% 且为淋巴系，起病急；MDS 原始细胞 <20%。"},{"name":"霍奇金淋巴瘤（he_hl）","point":"与本类 he_hl 的鉴别点：HL 以淋巴结肿大与 RS 细胞为特征，血象多正常。"},{"name":"真性红细胞增多症与原发性血小板增多症（he_mpn）","point":"与本类 he_mpn 的鉴别点：MPN 为红细胞或血小板增多伴驱动突变；MDS 以血细胞减少为主。"},{"name":"巨幼细胞性贫血（ma）","point":"与本科室 ma 的鉴别点：维生素 B12 或叶酸降低、中性粒细胞分叶过多，补充后恢复。"},{"name":"再生障碍性贫血（aa）","point":"与本科室 aa 的鉴别点：再障骨髓增生低下、无病态造血、网织极低。"}],"tx":{"drug":[{"name":"阿扎胞苷","dose":"75 mg/m² 皮下注射，每日 1 次×7 天，每 28 天 1 周期；遵说明书","note":"中高危或有原始细胞增多者的一线去甲基化药物，至少 4～6 周期评估疗效，监测骨髓抑制与感染。","renal":"肾功能不全者监测","hepatic":"肝功能不全者慎用","interact":"与其他骨髓抑制药合用加重血细胞减少"},{"name":"地西他滨","dose":"20 mg/m² 静滴每日 1 次×5 天，每 28 天 1 周期；遵说明书","note":"用于中高危、老年或不宜强化疗者，监测血象与感染。","renal":"遵说明书","hepatic":"肝功能不全者慎用","interact":"与其他骨髓抑制药合用加重抑制"},{"name":"来那度胺 / 沙利度胺","dose":"来那度胺 10 mg qd 口服（del(5q) 者）；遵说明书","note":"del(5q) 且输血依赖者首选，注意静脉血栓与致畸性。","renal":"来那度胺经肾排泄，肾功能不全需减量","hepatic":"遵说明书","interact":"与地塞米松合用增加血栓风险"},{"name":"促红细胞生成素","dose":"遵说明书，按体重个体化，目标 Hb ≤115 g/L","note":"用于低危 MDS 贫血，内源性促红素 <500 mU/mL 者反应率较高；8～12 周无效停用。","renal":"同用需监测血压","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["支持治疗：红细胞输注维持 Hb 70～90 g/L，血小板 <10×10⁹/L 或有出血时输注；G-CSF 用于反复中性粒细胞减少伴感染；预期生存 >1 年且输血 >20 个单位者祛铁","异基因造血干细胞移植是唯一治愈手段，适用于 IPSS-R 中高危且条件允许的年轻患者","低危以改善血细胞减少与生活质量为目标，高危以延缓转化与延长生存为目标","临床试验：维奈克拉联合去甲基化、IDH 抑制剂等","动态复查骨髓与染色体，更新危险分层"],"life":["接种流感与肺炎链球菌疫苗；中性粒细胞 <0.5×10⁹/L 伴发热立即经验性抗感染","避免骨髓抑制药物与非甾体抗炎药，注意出血观察","每 1～3 个月复查血常规，每 6～12 个月复查骨髓","输血依赖者监测铁过载与血制品感染"]},"prog":"预后异质性强：IPSS-R 低危中位生存 5～9 年，高危仅 1～2 年；约 25%～30% 转化为 AML。del(5q) 与 SF3B1 突变预后较好，复杂核型与 TP53 突变者差。","refs":["《内科学》第 9 版 骨髓增生异常综合征","中华医学会血液学分会《骨髓增生异常综合征中国诊断与治疗指南（2019 年版）》"]},{"id":"he_all","name":"急性淋巴细胞白血病","aka":["ALL","Acute Lymphoblastic Leukemia","急性淋巴细胞性白血病"],"rank":2,"basic":{"define":"淋巴系祖细胞克隆性增殖并广泛浸润骨髓、血液与髓外组织的急性白血病，骨髓原始淋巴细胞 ≥20%，或存在特定遗传学异常时比例更低亦可诊断；分 B-ALL 与 T-ALL。","risk":["儿童发病高峰 2～5 岁，成人随年龄上升且预后更差","遗传易感：唐氏综合征、Li-Fraumeni、Bloom 综合征、共济失调毛细血管扩张症","电离辐射、苯等溶剂暴露","由 MDS、MPN 转化或治疗相关"],"epi":"儿童急性白血病约 80% 为 ALL，年发病率约 3～4/10 万；成人 ALL 约占成人急性白血病 20%。我国儿童 ALL 5 年无事件生存已达 80% 以上，成人约 40%～50%。"},"patho":"淋巴系祖细胞发生易位与融合（B-ALL：BCR-ABL1、ETV6-RUNX1、TCF3-PBX1、KMT2A 重排；T-ALL：NOTCH1、TAL1），伴 IKZF1 缺失，导致增殖失控与分化阻滞。白血病细胞挤压正常造血引起贫血、感染与出血，并浸润中枢神经、睾丸与胸腺。","dx":{"criteria":["急性起病：贫血、发热与感染、皮肤瘀点瘀斑、骨痛、淋巴结与肝脾肿大；T-ALL 常有纵隔肿块","血红蛋白与血小板下降，白细胞可高可低，外周血见原始淋巴细胞","骨髓原始淋巴细胞 ≥20%","流式表型：B-ALL 为 CD19+、CD22+、TdT+、HLA-DR+；T-ALL 为胞质 CD3+、CD7+、CD5+","细胞遗传与分子：核型、FISH（BCR-ABL1、KMT2A、ETV6-RUNX1）、Ph 样融合基因、IKZF1 缺失","腰穿脑脊液细胞学与流式评估中枢受累（CNS1～3）"],"workup":["血常规 + 涂片 + 网织红细胞","凝血功能、LDH、尿酸、电解质与肾功能（肿瘤溶解风险评估）","骨髓涂片、活检与流式分型，建立 MRD 基础表型","染色体核型 + FISH + 分子检测","腰椎穿刺脑脊液细胞学与流式","胸腹 CT、纵隔评估（T-ALL）、男性儿童睾丸超声","心脏超声、乙肝丙肝 HIV 与 CMV 筛查","高危或拟移植者 HLA 配型，治疗前生育力保存"],"grading":"危险分层以年龄、白细胞数、遗传学与 MRD 为核心：儿童按 NCI 风险与诱导、巩固后 MRD（10⁻⁴～10⁻⁶）分低中高危；成人按 Ph 阴阳性、初诊白细胞 >30×10⁹/L（B-ALL）或 >100×10⁹/L（T-ALL）分组。中枢状态分 CNS-1（无原始细胞）、CNS-2（<5 个/µl）、CNS-3（≥5 个/µl 或有神经症状）。"},"ddx":[{"name":"骨髓增生异常综合征（he_mds）","point":"与本类 he_mds 的鉴别点：MDS 原始细胞 <20%、病态造血为主，起病隐匿。"},{"name":"霍奇金淋巴瘤（he_hl）","point":"与本类 he_hl 的鉴别点：HL 以淋巴结肿大与 RS 细胞为特征，骨髓浸润少见。"},{"name":"急性髓系白血病（aml）","point":"与本科室 aml 的鉴别点：AML 原始细胞为髓系（MPO+、CD13+、CD33+、CD117+），靠流式区分。"},{"name":"传染性单核细胞增多症","point":"EBV-VCA IgM 阳性、异型淋巴细胞增多，骨髓原始细胞不增高，可自限。"}],"tx":{"drug":[{"name":"长春新碱","dose":"1.4 mg/m²（单次最大 2 mg）静注，按方案每周或隔周","note":"诱导与巩固核心药物；注意周围神经毒性（便秘、手足麻木），避免外渗。","renal":"遵说明书","hepatic":"高胆红素或肝功能不全需减量","interact":"唑类等 CYP3A4 抑制剂加重神经毒性"},{"name":"泼尼松 / 地塞米松","dose":"泼尼松 60 mg/m²/d（或地塞米松 6 mg/m²/d）约 28 天，之后渐减","note":"诱导核心成分；注意血糖、感染与消化道出血，T-ALL 优先地塞米松以加强中枢覆盖。","renal":"遵说明书","hepatic":"肝功能不全者监测","interact":"CYP3A4 抑制剂升高血药浓度"},{"name":"柔红霉素 / 多柔比星","dose":"柔红霉素 30～60 mg/m²，按方案控制累积量（多柔比星累积 ≤400～500 mg/m²）","note":"蒽环类需基线评估心功能。","renal":"遵说明书","hepatic":"肝功能不全需减量","interact":"与曲妥珠单抗等合用心脏毒性叠加"},{"name":"培门冬酶","dose":"2500 U/m² 肌注，每 2 周 1 次；遵说明书","note":"ALL 特有药物，监测纤维蛋白原与抗凝血酶、胰腺炎与过敏。","renal":"遵说明书","hepatic":"肝功能异常常见，需监测","interact":"与蒽环类、激素叠加增加高凝与胰腺炎风险"},{"name":"环磷酰胺","dose":"按方案，常用 1000～1200 mg/m² 静滴","note":"用于高危或 T-ALL 方案；水化并用美司钠预防出血性膀胱炎。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与别嘌醇合用骨髓抑制加重"},{"name":"甲氨蝶呤（鞘内与大剂量）","dose":"鞘内 8～15 mg 每 1～2 周 1 次（按年龄与方案调整）；大剂量静滴按方案","note":"中枢预防与治疗核心；大剂量需亚叶酸钙解救，监测血药浓度与黏膜毒性。","renal":"肾功能不全禁用大剂量，可改鞘内","hepatic":"遵说明书","interact":"磺胺与非甾体抗炎药降低清除、增加毒性"},{"name":"伊马替尼 / 达沙替尼（Ph 阳性 ALL）","dose":"遵说明书，与化疗联合使用","note":"Ph 阳性 ALL 必须加用酪氨酸激酶抑制剂，可显著提高缓解率与移植前缓解深度。","renal":"遵说明书","hepatic":"遵说明书","interact":"唑类升高血药浓度；质子泵抑制剂降低达沙替尼吸收"},{"name":"别嘌醇 / 拉布立酶","dose":"别嘌醇 300 mg/d 按肾功能调整；高危者用拉布立酶，遵说明书","note":"诱导初期充分水化（>2 L/m²/d）并监测血钾、血磷、血钙与尿酸。","renal":"别嘌醇需按肾功能减量","hepatic":"遵说明书","interact":"别嘌醇与硫唑嘌呤或 6-巯基嘌呤合用需大幅减量"}],"nonDrug":["多药联合诱导、巩固与维持，成人疗程通常 2～3 年","腰穿鞘内注射预防中枢神经系统白血病","异基因造血干细胞移植：高危、MRD 持续阳性、复发或 Ph 阳性缓解后","CAR-T 细胞治疗与贝林妥欧单抗用于复发或难治患者","中枢放疗仅限特定高危或复发者，儿童尽量避免以保护认知","育龄患者治疗前进行精子或卵母细胞冻存"],"life":["中性粒细胞缺乏期预防用药，避免生冷食物与人群聚集","治疗期监测血象、肝功能、凝血与心脏超声（蒽环累积量）","远期监测骨密度、糖代谢、心脏毒性与继发肿瘤","儿童患者关注学业、生长与心理支持"]},"prog":"儿童 ALL 5 年总生存可达 85%～90%，成人约 45%～60%；Ph 阳性加用酪氨酸激酶抑制剂后明显改善。高龄、白细胞极高、复杂核型、IKZF1 缺失与 MRD 持续阳性者预后差。","refs":["《内科学》第 9 版 急性白血病","中国抗癌协会血液肿瘤专业委员会《中国成人急性淋巴细胞白血病诊断与治疗指南（2021 年版）》","中华医学会儿科学分会血液学组《儿童急性淋巴细胞白血病诊疗建议（第四次修订）》"]},{"id":"he_hl","name":"霍奇金淋巴瘤","aka":["Hodgkin Lymphoma","HL","霍奇金病"],"rank":3,"basic":{"define":"起源于生发中心 B 细胞的淋巴系统恶性肿瘤，以少数 Reed-Sternberg（RS）细胞与大量炎性背景细胞共存为病理特征；分经典型（约 95%）与结节性淋巴细胞为主型。","risk":["青壮年（20～34 岁）与 55 岁以上双峰发病","EBV 感染史，约 20%～40% 经典型 RS 细胞 EBV 阳性","免疫缺陷（HIV、移植后免疫抑制、自身免疫病）","一级亲属家族史，风险升高约 3～9 倍"],"epi":"我国经典型霍奇金淋巴瘤年发病率约 0.5～1/10 万，占淋巴瘤 8%～10%；男性多见，发病年龄较欧美提前。总体 5 年生存率 70%～90%。"},"patho":"RS 细胞经 NF-κB、JAK-STAT 与 PD-L1 通路逃避凋亡和免疫监视，并分泌趋化因子募集 T 细胞、嗜酸性粒细胞与组织细胞形成炎性背景。病变沿淋巴管连续性扩散（颈部→纵隔→腹膜后），可累及脾、骨与肺。","dx":{"criteria":["无痛性、进行性淋巴结肿大，颈部和锁骨上最常见，可伴纵隔肿块","B 症状：不明原因发热 >38 ℃、夜间盗汗、半年内体重下降 >10%","淋巴结完整切除活检见 RS 细胞与炎性背景（不推荐仅做细针穿刺）","免疫组化：CD15+、CD30+、CD20−、PAX5 弱阳性、LMP1 可阳性","PET-CT 结合 Ann Arbor 分期；B 症状记 B，局部结外记 E"],"workup":["完整淋巴结切除活检 + 免疫组化","血常规、血沉、LDH、肝肾功能、白蛋白、尿酸","PET-CT（分期与 Lugano 疗效评估）或增强 CT","骨髓活检：早期无不良因素者可免做，PET 阳性或血细胞异常时必做","心脏超声与肺功能基线（蒽环类与博来霉素耐受）","乙肝、丙肝、HIV 与 EBV 血清学，育龄女性妊娠试验","化疗前生育力保存咨询"],"grading":"Ann Arbor 分期：Ⅰ期单一淋巴区；Ⅱ期膈肌同侧 ≥2 个淋巴区；Ⅲ期膈肌两侧；Ⅳ期弥漫累及结外器官。疗效用 PET 的 Deauville 5 分法。早期不良因素为年龄 ≥50 岁、B 症状、血沉 ≥50（有 B 症状时 ≥30）、纵隔肿块比 ≥0.33、病变 ≥3 个区域，≥3 项为不良预后组；晚期用国际预后评分 7 项分层。"},"ddx":[{"name":"急性淋巴细胞白血病（he_all）","point":"与本类 he_all 的鉴别点：ALL 骨髓原始淋巴细胞 ≥20%，以贫血、出血与感染为主。"},{"name":"骨髓增生异常综合征（he_mds）","point":"与本类 he_mds 的鉴别点：MDS 血细胞减少伴病态造血，无 RS 细胞。"},{"name":"非霍奇金淋巴瘤（lymphoma）","point":"与本科室 lymphoma 的鉴别点：NHL 多为 CD20+ 且无 RS 细胞、呈跳跃式扩散。"},{"name":"淋巴结核","point":"低热盗汗、淋巴结粘连成串并干酪样坏死，IGRA 阳性，抗结核有效。"},{"name":"传染性单核细胞增多症","point":"发热、咽峡炎、颈部淋巴结肿大，EBV-VCA IgM 阳性，可自限。"}],"tx":{"drug":[{"name":"ABVD 方案（多柔比星 + 博来霉素 + 长春碱 + 达卡巴嗪）","dose":"多柔比星 25 mg/m² + 博来霉素 10 U/m² + 长春碱 6 mg/m² + 达卡巴嗪 375 mg/m²，第 1、15 天静注，28 天 1 周期","note":"经典一线方案，每 2 周期 PET-CT 评估。博来霉素注意肺毒性，多柔比星累积剂量 ≤400～450 mg/m²。","renal":"达卡巴嗪可致肾功能异常","hepatic":"多柔比星与长春碱肝功能不全需减量","interact":"博来霉素与 G-CSF 合用可能增加肺毒性；长春碱经 CYP3A4 代谢，唑类升高其浓度"},{"name":"G-CSF（支持治疗）","dose":"化疗后 24～48 小时起用，遵说明书","note":"降低中性粒细胞减少性发热风险。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"纳武利尤单抗 / 帕博利珠单抗","dose":"遵说明书，按体表面积或固定剂量","note":"用于复发或难治经典型 HL，尤其自体移植后复发者，客观缓解率约 70%。","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用降低疗效"}],"nonDrug":["早期无不良因素：ABVD×2～4 周期 + 受累部位放疗，或短程化疗后 PET 阴性者免放疗","早期不良预后：ABVD×4～6 周期 + 受累部位放疗，中期 PET 阳性者升级强化方案","晚期：ABVD×6～8 周期或强化方案（BEACOPP、维布妥昔单抗联合 AVD）","复发或难治：挽救化疗 + 自体造血干细胞移植，移植后可维持治疗","放疗采用受累部位照射，注意年轻患者生育与继发肿瘤风险"],"life":["化疗期预防感染，监测肺功能（博来霉素）与心脏超声（蒽环类）","长期随访甲状腺功能（颈部放疗）、心脏评估与继发肿瘤筛查","化疗结束 3～6 个月后可接种灭活疫苗，避免活疫苗","治疗前男性可精子冻存，女性可卵母细胞冻存"]},"prog":"早期治愈率 85%～95%，晚期 65%～80%；中期 PET 阴性者预后极好。远期需终身随访心肺毒性、继发肿瘤与甲状腺功能减退。","refs":["《内科学》第 9 版 淋巴瘤","中国抗癌协会淋巴瘤专业委员会《中国霍奇金淋巴瘤诊断与治疗指南（2023 年版）》"]},{"id":"he_mpn","name":"真性红细胞增多症与原发性血小板增多症","aka":["Polycythemia Vera","Essential Thrombocythemia","PV","ET","骨髓增殖性肿瘤"],"rank":4,"basic":{"define":"骨髓增殖性肿瘤（MPN）的两种经典表型：真性红细胞增多症（PV）以红系克隆性增殖、血红蛋白升高为特征；原发性血小板增多症（ET）以巨核系增殖、血小板持续增多为特征。两者均以血栓与出血风险为核心，可向骨髓纤维化或白血病转化。","risk":["年龄 >60 岁与既往血栓史为最主要血栓风险","JAK2 V617F 突变（PV 约 95%，ET 约 50%～60%），ET 还可见 CALR 或 MPL 突变","吸烟、高血压、糖尿病、高脂血症与肥胖","妊娠期血栓风险升高；脾切除后反应性血小板增多"],"epi":"PV 与 ET 年发病率各约 1～2.5/10 万，随年龄上升，中位发病年龄约 60 岁，男性略多。我国 PV 的 JAK2 V617F 阳性率约 95%，ET 约 55%。"},"patho":"JAK2 V617F 等驱动突变使 JAK-STAT 通路持续激活，祖细胞对促红素或血小板生成素过度敏感而克隆性扩增，红系或巨核系过度生成。红细胞容积升高致高黏滞，血小板功能异常与内皮损伤使血栓与出血并存；克隆演化可致骨髓纤维化或转化为 AML。","dx":{"criteria":["PV：Hb 男 >165 g/L、女 >160 g/L（或 Hct 男 >49%、女 >48%）；骨髓三系增生伴多形性巨核；JAK2 V617F 或外显子 12 突变；血清促红素降低","ET：血小板 ≥450×10⁹/L；骨髓巨核增生、体积大而成熟；不符合 PV、骨髓纤维化、CML、MDS；有 JAK2、CALR 或 MPL 突变","排除继发性红细胞增多（缺氧、睡眠呼吸暂停、肾肿瘤、促红素滥用、雄激素）","排除反应性血小板增多（缺铁、感染、炎症、脾切除、肿瘤），并与 BCR-ABL1 阳性的 CML 鉴别"],"workup":["反复血常规（Hb、Hct、血小板），必要时核素法测红细胞容积","JAK2 V617F、JAK2 外显子 12、CALR、MPL 检测，BCR-ABL1 阴性","骨髓穿刺与活检（增生程度、巨核形态、纤维化分级）","血清促红素（PV 常降低）与铁代谢","肝脾超声（脾大提示纤维化进展）","缺氧评估：血气、睡眠监测、肾脏超声；血压、血脂、血糖筛查"],"grading":"血栓风险：低危为年龄 <60 岁且无血栓史，高危为年龄 ≥60 岁或既往血栓史；ET 中 JAK2 突变与血小板 >1000×10⁹/L 亦增加风险，PV 的 Hct >45% 为独立风险。血小板 >1500×10⁹/L 时警惕获得性血管性血友病所致出血。"},"ddx":[{"name":"骨髓增生异常综合征（he_mds）","point":"与本类 he_mds 的鉴别点：MDS 以血细胞减少与病态造血为主；PV/ET 为增多伴驱动突变。"},{"name":"急性淋巴细胞白血病（he_all）","point":"与本类 he_all 的鉴别点：ALL 原始淋巴细胞 ≥20%、急性起病；PV/ET 为慢性病程。"},{"name":"慢性髓性白血病（cml）","point":"与本科室 cml 的鉴别点：CML 为 BCR-ABL1 阳性、粒系左移伴嗜碱性粒细胞增多与脾大。"},{"name":"继发性红细胞增多症","point":"慢性缺氧、肾肿瘤、促红素滥用或雄激素使用，促红素正常或升高，无 JAK2 突变。"},{"name":"反应性血小板增多","point":"缺铁、感染、炎症或脾切除后，血小板多 <1000×10⁹/L，原发病控制后恢复。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"75～100 mg qd 口服","note":"无禁忌者低危及高危均推荐用于预防血栓；有出血史者需评估后使用。","renal":"重度肾功能不全者慎用","hepatic":"重度肝损伤者慎用","interact":"与抗凝药、非甾体抗炎药合用出血风险增加"},{"name":"羟基脲","dose":"起始 15～20 mg/(kg·d) 口服，按血象调整；目标 Hct <45%（PV）或血小板 <400×10⁹/L（ET）","note":"高危 PV/ET 的降细胞一线用药；注意皮肤溃疡与口腔黏膜改变。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与放疗或其他骨髓抑制药合用加重抑制"},{"name":"聚乙二醇干扰素 α","dose":"遵说明书，按耐受性滴定","note":"适用于年轻、育龄期及羟基脲不耐受者，部分可达分子学缓解。","renal":"遵说明书","hepatic":"肝功能异常者监测","interact":"与其他骨髓抑制药合用加重抑制"},{"name":"芦可替尼","dose":"起始 10 mg bid 口服，按血象与疗效调整；遵说明书","note":"用于羟基脲失败或不耐受、脾大或症状明显者；不可骤停，警惕停药反跳。","renal":"肾功能不全需减量","hepatic":"肝功能不全需减量","interact":"酮康唑等 CYP3A4 抑制剂升高其浓度需减量，强诱导剂降低疗效"},{"name":"阿那格雷","dose":"起始 0.5 mg bid 口服；遵说明书","note":"ET 二线降血小板药，注意心悸、水肿与心力衰竭，高龄心脏病患者不推荐。","renal":"遵说明书","hepatic":"肝功能不全需减量","interact":"与抗血小板药合用增加出血风险"}],"nonDrug":["放血治疗（PV 首选）：维持 Hct <45%，每次 250～500 ml，每 2～4 周一次，缺铁时不宜盲目补铁","高危患者行降细胞治疗以降低血栓风险","严格控制血压、血脂、血糖，戒烟减重","血小板 >1500×10⁹/L 伴出血者评估获得性血管性血友病，必要时血小板单采","进展为骨髓纤维化者按骨髓纤维化管理，评估芦可替尼与移植","妊娠期抗栓策略由血液科与产科共同制定"],"life":["PV 每 4～8 周、ET 每 2～3 个月复查血常规与脾脏大小","充分饮水，避免脱水与长时间制动，尤其旅行与围手术期","手术或拔牙前评估是否需停阿司匹林，必要时低分子肝素桥接","关注瘙痒、皮肤灼热、盗汗及纤维化或白血病转化征象"]},"prog":"PV 中位生存约 15～20 年，ET 约 20 年，接近同龄人群；主要死因为血栓（约 30%～40%）与出血，10～15 年内约 5%～10% 转化为骨髓纤维化或 AML。年龄 >60 岁与既往血栓史为主要预后不良因素。","refs":["《内科学》第 9 版 骨髓增殖性肿瘤","中华医学会血液学分会《真性红细胞增多症诊断与治疗中国专家共识（2016 年版）》","中华医学会血液学分会《原发性血小板增多症诊断与治疗中国专家共识（2016 年版）》"]}]},{"id":"leuk_more","name":"白血病与骨髓衰竭","rank":6,"summary":"APL 是唯一「先救命后确诊」的白血病——疑诊即上全反式维A酸；CLL 治疗指征看疾病活动度而非淋巴细胞数；PNH 靠流式 CD55/CD59 缺失确诊，补体抑制剂可改变病程。","compare":[{"diseaseId":"he_apl","dx":"异常早幼粒细胞增多、PML-RARA 融合基因阳性，常伴 DIC 与出血倾向","key":"伴 DIC 的急性白血病首先要想到 APL；确诊前即应启动全反式维A酸"},{"diseaseId":"he_cll","dx":"外周血单克隆 B 淋巴细胞持续 ≥5×10⁹/L（或 <5×10⁹/L 但有骨髓浸润/淋巴结肿大）、smIg 弱阳性、CD5⁺CD23⁺","key":"多为老年、惰性病程；治疗看 Rai/Binet 分期与活动度指标，早期观察"},{"diseaseId":"he_pnh","dx":"慢性血管内溶血（Hb 尿、LDH 高、网织高）+ 流式见 CD55/CD59 缺失克隆，可伴血栓与全血细胞减少","key":"溶血 + 血栓 + 全血细胞减少的组合；流式 CD55/CD59 缺失是诊断依据"}],"diseases":[{"id":"he_apl","name":"急性早幼粒细胞白血病","aka":["Acute Promyelocytic Leukemia","APL","M3 型白血病","PML-RARA"],"rank":1,"basic":{"define":"以异常早幼粒细胞增生为特征的急性髓系白血病亚型（FAB 分型 M3），具有 t(15;17)(q24;q21) 易位形成 PML-RARA 融合基因，特征性表现为严重出血倾向与早期 DIC。","risk":["中年成人（中位约 40 岁，较其他 AML 年轻）","无明确环境危险因素（少数与既往化疗相关）","亚洲人群发病率相对较高"],"epi":"占急性髓系白血病的 5%–10%，我国发病年龄较西方年轻。**在维A酸 + 砷剂联合治疗时代，治愈率可达 85%–90%**，是成人白血病中预后最好的亚型之一。但早期出血死亡率仍约 5%–10%。"},"patho":"t(15;17) 使 15 号染色体上的 PML 基因与 17 号染色体上的 RARA 基因融合，形成 PML-RARA 融合蛋白。该蛋白以显性负性方式干扰维A酸受体功能，阻断早幼粒细胞向成熟粒细胞分化，导致细胞停滞于早幼粒阶段。全反式维A酸（ATRA）与三氧化二砷（ATO）通过不同机制降解 PML-RARA 蛋白，诱导细胞分化与凋亡——这是 APL 靶向分化治疗的经典范例。异常早幼粒细胞释放促凝物质（组织因子、癌性促凝物）激活凝血级联，导致 DIC 与致命性出血（尤其颅内出血）。","dx":{"criteria":["临床表现：乏力、贫血、发热、出血倾向（皮肤黏膜出血、鼻衄、牙龈出血、月经过多），**严重者以颅内出血或肺出血首发**","血常规：全血细胞减少或白细胞增高，外周血见异常早幼粒细胞（颗粒增多、Auer 小体成束——「柴捆细胞」）","**凝血功能：DIC 证据（PT 延长、纤维蛋白原降低、D-二聚体升高）——APL 最重要的特征之一**","骨髓：异常早幼粒细胞 ≥20%（多数 >50%）","**确诊依赖遗传学**：染色体核型 t(15;17)；FISH 或 RT-PCR 检出 PML-RARA 融合基因（**应在启动治疗前或同时送检，不得因等待结果而延误 ATRA**）","变异型：ZBTB16-RARA（t(11;17)）对 ATRA 不敏感，需按不同方案处理"],"workup":["血常规 + 外周血涂片（寻找柴捆细胞）","**凝血全套（PT/APTT/FIB/D-二聚体）、纤维蛋白降解产物** —— 基线且需每日监测","骨髓穿刺 + 活检（形态、免疫表型 CD13⁺CD33⁺CD34⁻HLA-DR⁻）","染色体核型分析 + FISH + RT-PCR（PML-RARA）","肝肾功能、LDH、尿酸、电解质（肿瘤溶解风险）","心脏超声（蒽环类前基线）、心电图（QTc，砷剂可延长 QT）","HLA 配型（高危/复发者备移植）"],"grading":"预后分层（PETHEMA/Sanz 评分）：白细胞 >10×10⁹/L 与血小板 <40×10⁹/L 为高危因素；低危（WBC ≤10 且 PLT >40）、中危（WBC ≤10 且 PLT ≤40）、高危（WBC >10）。危险度决定是否加用化疗或砷剂。"},"ddx":[{"name":"急性髓系白血病其他亚型（aml）","point":"与一般 AML 的鉴别：APL 的特征是异常早幼粒细胞、PML-RARA 阳性、**显著 DIC 与出血倾向**；其他 AML 的 DIC 较少见且程度轻。APL 不能用标准 3+7 方案（会加重 DIC）。"},{"name":"慢性淋巴细胞白血病（he_cll）","point":"与 CLL 的鉴别：CLL 为成熟小淋巴细胞增殖、病程惰性、无 DIC；APL 为急性起病、早幼粒细胞、出血倾向重。"},{"name":"阵发性睡眠性血红蛋白尿（he_pnh）","point":"与 PNH 的鉴别：PNH 为慢性血管内溶血伴血栓，无异常早幼粒细胞与 DIC；APL 的贫血源于骨髓衰竭而非溶血。"},{"name":"DIC（dic）","point":"APL 常继发 DIC，但原发 DIC 有明确诱因（感染、创伤、产科）且无白血病细胞；APL 的 DIC 需在治疗白血病的同时补充凝血因子。"},{"name":"急性淋巴细胞白血病（he_all）","point":"以原始淋巴细胞为主、POX 阴性、无 Auer 小体、无 PML-RARA。"},{"name":"巨幼细胞性贫血（ma）","point":"全血细胞减少但骨髓见巨幼样变、无异常早幼粒细胞与 Auer 小体，血清叶酸/B12 降低。"}],"tx":{"drug":[{"name":"全反式维A酸（ATRA）","dose":"诱导期 45 mg/(m²·d) 口服，分 2 次；持续至完全缓解（CR）或最长 90 天","note":"**疑诊 APL 即应立即启动，不等基因结果**——这是本病的核心治疗原则；主要不良反应为分化综合征（发热、体重增加、呼吸困难、肺浸润、胸腔/心包积液），一旦出现立即予地塞米松 10 mg q12h","renal":"无需调整","hepatic":"肝功能不全者慎用（可加重肝损）","interact":"与 CYP 抑制剂合用升高血药浓度；避免与四环素类同用（假性颅内高压）"},{"name":"三氧化二砷（ATO）","dose":"0.15 mg/(kg·d) 静脉滴注 2 小时，诱导期每日 1 次（联合 ATRA）；巩固期按方案间歇给药","note":"与 ATRA 联合（「双诱导」）是低中危 APL 的标准方案，治愈率 >90%；**需监测 QTc（>500 ms 暂停）与电解质（低钾低镁需纠正）**","renal":"肾功能不全者慎用（排泄减慢）","hepatic":"肝功能不全者减量","interact":"与其他延长 QT 药物合用增加 TdP 风险；与硫辛酸等含巯基药物合用可能降低疗效"},{"name":"地塞米松（分化综合征）","dose":"10 mg 静脉 q12h，至症状缓解后逐渐减量（通常 3–7 天）","note":"**分化综合征是 ATRA/ATO 治疗的致命并发症**（发生率 10%–25%），表现为发热、呼吸困难、体重增加、低血压、肺浸润；一旦怀疑立即用药，不需等确诊","renal":"无需调整","hepatic":"遵说明书","interact":"与抗凝、NSAIDs 合用增加消化道出血"},{"name":"蒽环类（去甲氧柔红霉素/柔红霉素，高危或联合方案）","dose":"去甲氧柔红霉素 6–12 mg/(m²·d) 静脉 ×3–4 天，或柔红霉素 45–60 mg/(m²·d) ×3 天（按方案）","note":"高危患者需联合化疗；**累积剂量需限制（柔红霉素 <550 mg/m²）以防心脏毒性**；需基线心超","renal":"肾功能不全减量","hepatic":"胆红素升高时减量","interact":"与曲妥珠单抗等心脏毒性药物合用需谨慎；CYP3A4 抑制剂升高浓度"},{"name":"新鲜冰冻血浆 / 冷沉淀 / 血小板（DIC 支持）","dose":"纤维蛋白原 <1.5 g/L 时输注冷沉淀（通常 10–20 U）或纤维蛋白原浓缩剂；血小板 <30×10⁹/L（或有出血时 <50×10⁹/L）输注血小板；PT 延长伴出血时输 FFP","note":"**APL 的 DIC 需积极补充凝血因子，不可因「怕加重血栓」而不补**；目标是维持纤维蛋白原 >1.5 g/L、血小板 >30–50×10⁹/L","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"别嘌醇 / 拉布立酶（肿瘤溶解预防）","dose":"别嘌醇 300 mg/d 口服（肾功能不全减量）；高危者用拉布立酶 0.2 mg/kg 静脉 qd","note":"APL 白细胞高者肿瘤溶解风险高；需充分水化与监测尿酸、钾、磷、钙","renal":"别嘌醇按 CrCl 减量；拉布立酶在 G6PD 缺乏者禁用（溶血）","hepatic":"无需调整","interact":"别嘌醇与硫唑嘌呤/6-巯基嘌呤合用需大幅减量（骨髓抑制）"},{"name":"复方磺胺甲噁唑（PCP 预防）","dose":"SMZ-TMP 480 mg qd 或 960 mg 每周 3 次，用于治疗期间 CD4 样免疫抑制状态","note":"强化治疗期间需预防卡氏肺孢子虫肺炎","renal":"CrCl <30 减量","hepatic":"肝病者慎用","interact":"与华法林合用增强抗凝；与甲氨蝶呤合用增加骨髓毒性"}],"nonDrug":["**尽早启动 ATRA（疑诊即用）**——这是降低早期出血死亡率最关键的措施","诱导期严密监测：每日凝血、血常规、电解质与容量状态","**避免腰椎穿刺与中心静脉置管等有创操作**（除非必需且在凝血纠正后）","高危患者完全缓解后评估**自体或异基因造血干细胞移植**","复发/难治者：砷剂再诱导、吉妥珠单抗、移植","PML-RARA 转阴后仍需完成巩固与维持治疗（通常 2 年）"],"life":["治疗期间避免剧烈活动与外伤（出血风险）","ATRA 相关皮肤干燥、口唇干裂可对症处理（润肤、润唇）","巩固期需定期监测 QTc、肝功能与血常规","完全缓解后随访：前 2 年每 3 个月、之后每 6 个月监测 PML-RARA（分子学复发先于血液学复发）","育龄女性治疗期间严格避孕（ATRA 与化疗均致畸）"]},"prog":"ATRA + 砷剂方案下，低中危 APL 的 5 年无病生存率 >90%，高危约 70%–80%，是预后最好的成人白血病。**早期（诱导期）死亡是主要失败原因**（约 5%–10%，多因出血或分化综合征），规范启动 ATRA 与支持治疗可显著降低。分子学复发可通过 PML-RARA 监测早期发现并再治疗。","refs":["《中国急性早幼粒细胞白血病诊疗指南（2018 年版）》（中华医学会血液学分会）","2019 European LeukemiaNet Recommendations for the Management of Acute Promyelocytic Leukemia (Blood)","2018 APL 亚洲共识（Asian APL Consensus）","《中国成人急性髓系白血病（非 APL）诊疗指南（2021 年版）》"]},{"id":"he_cll","name":"慢性淋巴细胞白血病","aka":["Chronic Lymphocytic Leukemia","CLL","慢性淋巴细胞白血病/小淋巴细胞淋巴瘤"],"rank":2,"basic":{"define":"以单克隆成熟小 B 淋巴细胞在血液、骨髓、淋巴结与脾脏进行性蓄积为特征的惰性淋巴增殖性疾病，与小型淋巴细胞淋巴瘤（SLL）为同一疾病的不同表现。","risk":["年龄（中位 70 岁，<40 岁罕见）","男性（约 2:1）","家族聚集（一级亲属风险升高 2–8 倍）","白种人高发（亚洲人群发病率显著低于欧美）","农药与除草剂暴露（部分研究提示）"],"epi":"欧美成人白血病中最常见类型（约占 30%–40%），亚洲发病率显著较低（我国约占白血病的 3%–5%）。我国发病年龄较西方年轻（中位约 60 岁）。"},"patho":"CLL 细胞的起源为抗原刺激后的 B 细胞，特征性表达 CD5、CD23、低水平表面免疫球蛋白（smIg）与 CD20 弱阳性。核心机制是**抗凋亡蛋白 BCL-2 过表达**导致细胞不能正常凋亡而在体内蓄积（而非增殖失控），这是维奈托克（BCL-2 抑制剂）的靶点。微环境（淋巴结基质细胞、 nurselike cells）提供生存信号。部分患者存在 del(17p)/TP53 异常或 del(11q)/ATM 缺失，预后差且对化疗不敏感，需用靶向药。","dx":{"criteria":["**外周血 B 淋巴细胞持续 ≥5×10⁹/L，持续 ≥3 个月**，且为单克隆","**流式细胞术免疫表型（诊断关键）**：CD5⁺、CD23⁺、CD20 弱阳性、smIg 弱阳性、CD19⁺、FMC7⁻、CD79b 弱阳性（**CLL 积分 4–5 分可确诊**）","外周血涂片见小、成熟形态的淋巴细胞，可见「涂抹细胞」（smudge cells）","骨髓：淋巴细胞 ≥40%（通常 >70%）","淋巴细胞 <5×10⁹/L 但伴有骨髓浸润/淋巴结肿大/脾大者仍可诊断 SLL（淋巴结肿大 + 无血象异常）","**需与套细胞淋巴瘤鉴别**：后者 CD5⁺ 但 CD23⁻、cyclin D1⁺/t(11;14)"],"workup":["血常规（淋巴细胞绝对值、血红蛋白、血小板）与涂片","**流式细胞免疫表型（外周血即可诊断）**","**FISH 检测 del(17p)、del(11q)、+12、del(13q)（预后与用药选择的关键）**","TP53 测序（del(17p) 阴性者也需检测突变）","IGHV 突变状态（预后分层）","β2-微球蛋白、LDH（预后）","直接抗人球蛋白试验（Coombs，评估自身免疫性溶血）","颈部/胸腹/盆腔 CT 或超声（评估淋巴结与脾脏）","乙型肝炎筛查（靶向药可致 HBV 再激活）、肾功能"],"grading":"**Binet 分期**：A 期——Hb ≥100 g/L、PLT ≥100×10⁹/L 且累及淋巴结区域 <3 个；B 期——同上血象但累及 ≥3 个区域；C 期——Hb <100 g/L 或 PLT <100×10⁹/L。**Rai 分期**：0 期（仅淋巴细胞增多）至 Ⅳ 期（血小板减少）。**治疗指征看疾病活动度**（见治疗部分），不以淋巴细胞计数为唯一依据。"},"ddx":[{"name":"急性早幼粒细胞白血病（he_apl）","point":"与 APL 的鉴别：APL 为急性起病、异常早幼粒、DIC 与出血；CLL 为惰性、成熟小淋巴细胞、无 DIC。"},{"name":"阵发性睡眠性血红蛋白尿（he_pnh）","point":"与 PNH 鉴别：PNH 为溶血性贫血 + 血栓 + 全血细胞减少；CLL 以淋巴细胞增殖为主，无 CD55/CD59 缺失。"},{"name":"套细胞淋巴瘤（MCL）","point":"**最需鉴别的类型**：MCL 为 CD5⁺ 但 CD23⁻、cyclin D1 阳性、t(11;14)，侵袭性强，预后远差于 CLL。"},{"name":"毛细胞白血病","point":"全血细胞减少、脾大、毛状胞质突起，流式 CD11c⁺CD25⁺CD103⁺、BRAF V600E 阳性。"},{"name":"华氏巨球蛋白血症（淋巴浆细胞淋巴瘤）","point":"IgM 单克隆免疫球蛋白血症、骨髓见淋巴浆细胞浸润、MYD88 L265P 突变。"},{"name":"反应性淋巴细胞增多","point":"有明确诱因（病毒感染、百日咳、应激），淋巴细胞为多克隆、短期自行恢复，无免疫表型异常。"},{"name":"小淋巴细胞淋巴瘤（SLL）","point":"同一疾病实体，区别在于血中淋巴细胞 <5×10⁹/L 而以淋巴结肿大为主。"}],"tx":{"drug":[{"name":"阿可替尼 / 伊布替尼（BTK 抑制剂）","dose":"阿可替尼 100 mg bid 口服；伊布替尼 420 mg qd 口服，持续至疾病进展或不耐受","note":"**一线首选（尤其 del(17p)/TP53 异常者）**；不良反应包括房颤（伊布替尼约 5%–10%）、高血压、出血与感染；阿可替尼房颤发生率较低","renal":"重度肾功能不全慎用（伊布替尼）","hepatic":"重度肝损害减量","interact":"伊布替尼为 CYP3A4 底物，与强抑制剂（酮康唑、克拉霉素）合用需减量；与抗血小板/抗凝合用增加出血"},{"name":"维奈托克（BCL-2 抑制剂）","dose":"**剂量递增**：第 1 周 20 mg qd，第 2 周 50 mg，第 3 周 100 mg，第 4 周 200 mg，第 5 周起 400 mg qd（遵方案）；联合奥妥珠单抗或单药","note":"**极高缓解率（含 del(17p)）**，固定疗程（约 12–24 个月）；**必须按递增方案以预防肿瘤溶解综合征**（尤其淋巴细胞 >25×10⁹/L 或淋巴结大者）；需监测中性粒细胞减少","renal":"重度肾功能不全慎用（肿瘤溶解风险）","hepatic":"重度肝损害减量（Child-Pugh C 减 50%）","interact":"**强 CYP3A4 抑制剂显著升高浓度（肿瘤溶解风险）**；与华法林合用增强抗凝；避免与 P-gp 抑制剂同用"},{"name":"奥妥珠单抗 / 利妥昔单抗（CD20 单抗）","dose":"奥妥珠单抗 1000 mg 静脉（分次给药，第 1 周期第 1、2、8、15 天，后续每周期第 1 天）；利妥昔单抗 375 mg/m² 每周 ×4 或按方案","note":"常与维奈托克或化疗联合；输注反应（首次尤其）、HBV 再激活（**用药前必须筛查并预防性抗病毒**）","renal":"无需调整","hepatic":"重度肝病慎用","interact":"活疫苗需推迟；与免疫抑制剂合用增加感染"},{"name":"苯丁酸氮芥 / 苯达莫司汀（化疗，老年或不适合靶向者）","dose":"苯丁酸氮芥 0.4–0.8 mg/kg 每 2 周（或 0.1 mg/kg/d 连续）；苯达莫司汀 90–100 mg/m² 静脉 ×2 天，每 28 天一周期","note":"靶向药普及后化疗地位下降，仅用于资源受限或特定情形；骨髓抑制与感染风险","renal":"苯达莫司汀在 CrCl <40 慎用","hepatic":"重度肝病减量","interact":"与 CYP1A2 抑制剂合用升高苯达莫司汀浓度"},{"name":"泼尼松（自身免疫性溶血/血小板减少并发症）","dose":"1 mg/kg/d 口服，按血象反应逐渐减量","note":"CLL 合并 AIHA 或 ITP 时使用（约 10%–25% 患者出现）；需同时评估 CLL 治疗指征","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"别嘌醇（肿瘤溶解预防）","dose":"300 mg/d 口服（CrCl <60 减量）","note":"维奈托克递增期与高淋巴细胞者必需；充分水化","renal":"按 CrCl 减量","hepatic":"无需调整","interact":"与硫唑嘌呤/6-MP 合用需大幅减量"}],"nonDrug":["**早期无症状者「观察等待」**（Binet A 且无活动指标）——早期治疗不改善生存","**治疗指征（IWCLL 标准）**：进行性骨髓衰竭（Hb <100 g/L 或 PLT <100×10⁹/L）；巨脾（>6 cm 肋下）或进行性脾大；巨淋巴结（>10 cm）或进行性淋巴结肿大；淋巴细胞倍增时间 <6 个月；自身免疫性血细胞减少对激素无效；疾病相关症状（盗汗、体重下降、乏力、发热）","异基因造血干细胞移植：年轻高危（del(17p)/TP53）且靶向治疗失败者","脾切除：巨脾伴症状或难治性血细胞减少","**所有患者需筛查 HBV 并预防性抗病毒**（尤其用 CD20 单抗者）","支持治疗：静脉丙种球蛋白（反复感染、低 IgG）、疫苗（灭活疫苗）"],"life":["定期随访：早期每 3–6 个月查血常规与体格检查","**感染预防**：肺炎球菌、流感、带状疱疹疫苗接种；注意低丙种球蛋白血症者补充 IVIG","BTK 抑制剂使用者：**警惕房颤与出血**（避免与抗凝/抗血小板随意联用），监测血压","维奈托克递增期：**严格按方案递增并监测电解质与肾功能**（肿瘤溶解）","育龄女性避孕（治疗期间）；避免活疫苗接种"]},"prog":"CLL 为惰性病程，中位生存期 5–10 年（Binet A 期可达 10 年以上，C 期约 3–5 年）。**del(17p)/TP53 异常者预后最差**（传统化疗中位生存 2–3 年，靶向治疗已显著改善）。约 10%–15% 发生 Rich 转化（向侵袭性淋巴瘤转化，预后极差）。靶向治疗时代总生存已显著延长。","refs":["《中国慢性淋巴细胞白血病/小淋巴细胞淋巴瘤的诊断与治疗指南（2022 年版）》（中华医学会血液学分会）","2018 International Workshop on CLL (iwCLL) Guidelines for Diagnosis, Indications for Treatment, Response Assessment (Blood)","2024 NCCN Guidelines for Chronic Lymphocytic Leukemia/Small Lymphocytic Lymphoma","《中国淋巴瘤诊疗指南（2022）》"]},{"id":"he_pnh","name":"阵发性睡眠性血红蛋白尿","aka":["Paroxysmal Nocturnal Hemoglobinuria","PNH","阵发性睡眠性血红蛋白尿症"],"rank":3,"basic":{"define":"由 PIGA 基因体细胞突变导致红细胞、白细胞与血小板膜上糖基磷脂酰肌醇（GPI）锚定蛋白缺失（尤其 CD55、CD59）的获得性克隆性疾病，临床三联征为**血管内溶血、血栓形成与骨髓衰竭**。","risk":["各年龄段均可发病（中位约 30–40 岁）","无明确环境或遗传危险因素（PIGA 突变为获得性体细胞突变）","可继发于再生障碍性贫血或 MDS（克隆演化）","亚洲人群发病率相对较高"],"epi":"年发病率约 1–1.5/100 万，患病率约 10–20/100 万。我国相对高发，中位发病年龄约 30 余岁。约 30%–40% 患者可自发缓解，但血栓与骨髓衰竭是主要死因。"},"patho":"PIGA 基因（X 染色体）体细胞突变使 GPI 锚合成障碍，导致所有 GPI 锚定蛋白缺失。其中 CD55（衰变加速因子）与 CD59（膜攻击复合物抑制因子）是补体调节蛋白，缺失使红细胞对补体介导的溶解高度敏感。**血管内溶血呈「睡眠后加重」的机制**：睡眠时呼吸中枢敏感性下降致轻度呼吸性酸中毒，补体激活增强。血栓形成是 PNH 最严重的并发症（机制包括补体激活血小板、游离血红蛋白清除 NO 致内皮损伤、微粒促凝），常见于肝静脉（Budd-Chiari）、脑静脉窦与肺栓塞。","dx":{"criteria":["临床三联征：① **慢性血管内溶血**（血红蛋白尿、尤其晨起首次尿色深；黄疸、LDH 显著升高、网织红细胞升高、结合珠蛋白降低）；② **血栓形成**（不寻常部位：肝静脉/门静脉、脑静脉窦、皮肤）；③ **骨髓衰竭**（全血细胞减少，可继发或并存 AA/MDS）","**确诊依据——流式细胞术检测 GPI 锚定蛋白缺失**：红细胞 CD59 与 CD55 缺失；粒细胞 CD24/CD16、单核细胞 CD14 缺失（**多系检测可提高敏感度，粒细胞克隆大小与血栓风险相关性更好**）","克隆大小：粒细胞克隆 ≥10%（小型克隆通常无症状，但需随访）；I 型（对补体敏感但不易溶血）、II 型（中度）、III 型（高度敏感）红细胞分型","**需排除其他溶血**：Coombs 试验阴性（与 AIHA 鉴别）、无破碎红细胞（与 TMA 鉴别）","骨髓：增生活跃或减低，可伴再生障碍性贫血表现","**凝血与血栓评估**：D-二聚体、腹部超声（Budd-Chiari 筛查）、必要时 CT/MR 静脉成像"],"workup":["**流式细胞术检测 CD55/CD59（红细胞、粒细胞、单核细胞）** —— 诊断金标准","血常规、网织红细胞、LDH、间接胆红素、结合珠蛋白、游离血红蛋白","直接与间接抗人球蛋白试验（Coombs，排除 AIHA）","外周血涂片（破碎红细胞，排除 TMA）、肾功能","骨髓穿刺 + 活检（评估骨髓衰竭与克隆演化）","腹部超声 / CT / MRV（肝静脉血栓筛查）、头颅 MRV（疑脑静脉窦血栓）","尿隐血与尿含铁血黄素（慢性血管内溶血证据）","染色体核型与 MDS 相关基因（并存 MDS 时）"],"grading":"按临床分型：经典型 PNH（溶血为主）、骨髓衰竭型（AA/PNH 综合征）、血栓型（少数但最凶险）。按粒细胞克隆大小分：小克隆（<10%，多无症状）、中等（10%–50%）、大克隆（>50%，溶血与血栓风险高）。"},"ddx":[{"name":"急性早幼粒细胞白血病（he_apl）","point":"与 APL 的鉴别：APL 为急性白血病、异常早幼粒、DIC 出血；PNH 为慢性溶血 + 血栓，无白血病细胞。"},{"name":"慢性淋巴细胞白血病（he_cll）","point":"与 CLL 的鉴别：CLL 为淋巴细胞增殖，无血管内溶血（少数合并 AIHA 但 Coombs 阳性）；PNH 的 Coombs 阴性、CD55/CD59 缺失。"},{"name":"自身免疫性溶血性贫血（he_aiha）","point":"**关键鉴别**：AIHA 的 Coombs 试验阳性、无 CD55/CD59 缺失、溶血多为血管外（脾大）；PNH 的 Coombs 阴性、血红蛋白尿突出、晨起加重。"},{"name":"血栓性微血管病（TTP/TMA）","point":"TMA 有破碎红细胞、血小板减少与肾功能损害，ADAMTS13 缺乏（TTP）；PNH 无破碎红细胞、血小板可减少但非消耗性、CD59 缺失。"},{"name":"再生障碍性贫血（aa）","point":"AA 为骨髓衰竭，无溶血证据；PNH 可与 AA 并存（AA-PNH 综合征），需流式检测明确。"},{"name":"遗传性球形红细胞增多症（he_hs）","point":"有家族史、球形红细胞、渗透脆性增加，Coombs 阴性但无 CD55/CD59 缺失。"}],"tx":{"drug":[{"name":"依库珠单抗（补体 C5 抑制剂）","dose":"前 4 周 600 mg 静脉每周 1 次，第 5 周 900 mg，之后 900 mg 每 2 周 1 次（或 1200 mg 每 2 周）；**需在脑膜炎球菌疫苗接种后 ≥2 周开始**","note":"**PNH 的一线靶向治疗**：可使 LDH 正常化、显著减少溶血与血栓（血栓风险降低约 85%），改善生活质量；**不改善骨髓衰竭**；需终身用药（停药可致溶血反跳）","renal":"肾功能不全无需调整","hepatic":"无需调整","interact":"与 IVIG 合用可能影响疗效；**活疫苗禁用**（除脑膜炎球菌疫苗需提前接种）；需预防性抗生素（不能等 2 周时）"},{"name":"雷夫利珠单抗 / 培古塞塔科普兰（长效 C5 抑制剂）","dose":"雷夫利珠单抗 3400 mg 静脉每 8 周；培古塞塔科普兰按体重皮下给药（遵说明书）","note":"长效制剂可改善依从性；同样需脑膜炎球菌疫苗与终身用药","renal":"无需调整","hepatic":"无需调整","interact":"同依库珠单抗"},{"name":"达那唑 / 低剂量糖皮质激素（部分溶血控制）","dose":"达那唑 200 mg tid 口服；泼尼松 0.3–0.5 mg/kg/d（短期）","note":"用于溶血较重但不适合或不能使用补体抑制剂者（证据有限）；激素长期使用副作用大，仅短期","renal":"无需调整","hepatic":"达那唑有肝毒性（可致胆汁淤积），需监测","interact":"达那唑与华法林合用增强抗凝（PNH 患者常用华法林预防血栓）"},{"name":"华法林（血栓二级预防）","dose":"目标 INR 2–3，长期（已发生血栓者通常终身）","note":"PNH 合并血栓首选长期抗凝；**DOAC 在 PNH 中证据有限**，华法林仍为主流；需评估出血风险","renal":"无需调整","hepatic":"肝病者慎用","interact":"与达那唑、胺碘酮、唑类抗真菌药合用增强抗凝"},{"name":"叶酸（慢性溶血支持）","dose":"5 mg qd 口服","note":"慢性溶血增加叶酸需求，补充可防巨幼变","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"铁剂（慢性血红蛋白尿丢铁）","dose":"口服铁剂元素铁 100–200 mg/d（需监测，避免过量致氧化损伤）","note":"慢性血红蛋白尿导致尿铁丢失，缺铁常见；但补铁可加重溶血（谨慎小剂量）","renal":"无需调整","hepatic":"无需调整","interact":"与抗酸药同服降低吸收"}],"nonDrug":["**所有患者需接种脑膜炎球菌疫苗**（四价结合疫苗 + B 型），补体抑制剂使用前提","**骨髓衰竭型（AA-PNH）**：免疫抑制治疗（抗胸腺细胞球蛋白 + 环孢素）或异基因造血干细胞移植","**异基因造血干细胞移植**：唯一根治手段，适用于严重骨髓衰竭、反复血栓、补体抑制剂无效或不可及者","输血（严重贫血时，需去白红细胞）","抗凝治疗（已发生血栓者）；**补体抑制剂本身可显著降低血栓风险**","避免诱因：感染、手术、剧烈运动、脱水（可诱发溶血危象）"],"life":["长期监测 LDH、网织红细胞、血红蛋白与粒细胞克隆大小（每 3–6 个月）","**警惕血栓症状**：腹痛与肝大（Budd-Chiari）、头痛与视物模糊（脑静脉窦）、胸痛与呼吸困难（肺栓塞），出现立即就诊","补体抑制剂者需注意感染（尤其脑膜炎球菌），发热立即就医","**不可自行停用依库珠单抗**（停药可致严重溶血反跳）","妊娠期管理复杂（补体抑制剂可继续使用，需多学科协作）","避免活疫苗接种；接种灭活疫苗（流感、肺炎球菌）"]},"prog":"未经靶向治疗者中位生存约 10–15 年，主要死因为血栓（约 40%–67%）与骨髓衰竭。**依库珠单抗时代预后显著改善**：血栓风险降低约 85%，生活质量与生存接近正常人群。约 30%–40% 患者在病程中自发缓解（克隆消失）。并存 AA 者预后取决于骨髓衰竭控制。","refs":["《阵发性睡眠性血红蛋白尿症诊断与治疗中国专家共识（2024 年版）》（中华医学会血液学分会）","2019 International PNH Interest Group (I-PIG) Consensus Guidelines for Diagnosis and Monitoring (Blood)","2018 Guidelines for the Diagnosis and Management of PNH (British Journal of Haematology)","2021 EHA/ESMO Recommendations on the Use of Complement Inhibitors in PNH"]}]},{"id":"coag_inherit","name":"遗传性凝血病与粒细胞疾病","rank":7,"summary":"遗传性出血病先定「哪条通路」：血友病为因子 VIII/IX 缺乏、APTT 延长而 PT 正常；vWD 为血小板黏附异常、出血时间延长而血小板计数正常。疑遗传性出血病者，用血浆不要用血小板作为首选。","compare":[{"diseaseId":"he_hemophilia","dx":"男性、关节与肌肉深部出血为主，APTT 延长、PT 正常，因子 VIII 或 IX 活性降低","key":"深部出血（关节/肌肉）+ APTT 延长；替代治疗按需或预防"},{"diseaseId":"he_vwd","dx":"黏膜出血为主（鼻衄、月经过多、拔牙后出血），出血时间延长、血小板计数正常、vWF 抗原与活性降低","key":"黏膜出血 + 血小板计数正常；轻型可用去氨加压素"},{"diseaseId":"he_agranulocytosis","dx":"中性粒细胞绝对值 <0.5×10⁹/L，伴高热与感染，常由药物引起","key":"粒缺伴发热是急症；G-CSF 与广谱抗生素"}],"diseases":[{"id":"he_hemophilia","name":"血友病","aka":["Hemophilia","血友病 A","血友病 B","因子 VIII 缺乏","因子 IX 缺乏"],"rank":1,"basic":{"define":"X 连锁隐性遗传的凝血因子缺乏性疾病：血友病 A 为因子 VIII（FVIII）缺乏，血友病 B 为因子 IX（FIX）缺乏。以关节、肌肉等深部反复出血为特征，可致关节畸形与残疾。","risk":["**男性发病，女性为携带者**（X 连锁隐性遗传）","母亲为携带者（FVIII/FIX 活性约 50%，可有轻度出血倾向）","约 30% 患者无家族史（新发突变）","约 1/3 的病例为自发性基因突变"],"epi":"血友病 A 发病率约 1/5000–10000 男性活产，血友病 B 约 1/25000–30000（A:B 约 4:1）。我国登记患者约数万，但诊断率估计不足 50%。按 FVIII/FIX 活性分型：重型 <1%、中间型 1%–5%、轻型 5%–40%。"},"patho":"因子 VIII 是凝血因子 IXa 的辅因子，因子 IX 是维生素 K 依赖性丝氨酸蛋白酶，二者共同参与内源性凝血途径的「tenase 复合物」形成，激活因子 X。缺乏时纤维蛋白形成延迟且不足，凝血块脆弱易被纤溶系统溶解，故表现为**延迟性、持续性出血**（而非血小板缺陷的即刻出血）。反复关节内出血（hemarthrosis）导致含铁血黄素沉积、滑膜增生与软骨破坏（血友病性关节病），是致残的主要原因。约 30% 的重型血友病 A 患者会产生**抑制物**（针对外源性 FVIII 的中和抗体），使替代治疗失效。","dx":{"criteria":["临床表现：**深部出血**为主——关节（膝、肘、踝）反复自发性或轻微外伤后出血、肌肉血肿（髂腰肌、小腿）、颅内出血（最危险）；**黏膜出血（鼻衄、牙龈）相对少见**","**初筛试验**：**APTT 延长而 PT 正常**（内源性途径），血小板计数与出血时间正常","**确诊：因子活性测定**——FVIII 或 FIX 活性降低（<40% 可诊断）","vWF 抗原与活性检测（排除 vWD，尤其女性或轻型）","抑制物检测（Bethesda 法或 Nijmegen 改良法，**重型患者治疗前与替代治疗反应下降时必查**）","分型（按活性）：重型 <1%、中间型 1%–5%、轻型 5%–40%","**基因检测（F8/F9）**：用于携带者筛查、产前诊断与抑制物风险评估"],"workup":["APTT、PT、纤维蛋白原、血小板计数（初筛）","**FVIII、FIX 活性测定**（确诊与分型）","**抑制物检测（Bethesda 法）** —— 治疗前基线，替代治疗反应差时复查","vWF 抗原/活性（排除 vWD）","F8/F9 基因检测（携带者与产前诊断）","影像：关节超声/MRI（评估关节病变，MRI 为金标准）、肌肉血肿超声","头颅 CT（疑颅内出血，**最紧急**）","家系调查（母亲与姐妹的携带者状态）"],"grading":"按因子活性分：重型 <1%（自发出血频繁，多需预防治疗）、中间型 1%–5%（外伤后出血，偶自发）、轻型 5%–40%（重大外伤或手术后出血）。按有无抑制物分：抑制物阳性（滴度 >0.6 BU，低反应型 <5 BU、高反应型 ≥5 BU）。关节病变按 Arnold-Hilgartner 或 Pettersson 评分。"},"ddx":[{"name":"血管性血友病（he_vwd）","point":"与 vWD 的鉴别：vWD 以**黏膜出血**（鼻衄、月经过多）为主、出血时间延长、vWF 抗原与活性降低；血友病为深部出血、APTT 延长而血管性血友病因子正常。"},{"name":"粒细胞缺乏症（he_agranulocytosis）","point":"与粒缺的鉴别：粒缺为感染与中性粒细胞缺乏，无出血表现与凝血异常。"},{"name":"获得性血友病 A（非遗传性）","point":"成年后（多为老年人或产后）新发严重出血、APTT 延长、FVIII 活性降低但**有抑制物**且无家族史；免疫抑制治疗为主。"},{"name":"DIC（dic）","point":"DIC 有明确诱因（感染、创伤、产科），同时伴血小板减少、PT 延长、纤维蛋白原降低与 D-二聚体升高；遗传性血友病的血小板与 PT 正常。"},{"name":"血小板功能缺陷（如血小板无力症）","point":"出血时间延长、血小板计数正常、血小板聚集试验异常；凝血因子活性正常。"},{"name":"其他凝血因子缺乏（因子 XI、XIII）","point":"因子 XI 缺乏 APTT 延长但出血轻；因子 XIII 缺乏为脐带残端出血与伤口愈合不良，常规 PT/APTT 均正常（需专项检测）。"}],"tx":{"drug":[{"name":"凝血因子 VIII 浓缩剂（血友病 A 替代治疗）","dose":"按需治疗：关节出血 20–30 IU/kg；肌肉血肿 30–40 IU/kg；颅内/危及生命出血 50–100 IU/kg 后维持 50%；**每 1 IU/kg 约提升 FVIII 活性 2%**；目标谷水平依出血部位而定（关节 ≥30%、重大出血 ≥50%–80%）","note":"**按需治疗（出血时）与预防治疗（规律输注以维持谷水平 ≥1%）**；预防治疗是防止关节病变的关键（儿童应尽早开始）；半衰期约 8–12 小时","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"凝血酶原复合物（PCC，血友病 B）","dose":"按 IX 活性目标给药：每 1 IU/kg 约提升 FIX 活性 0.8%–1%；关节出血 20–40 IU/kg，重大出血 60–80 IU/kg","note":"血友病 B 的首选替代；含 FII/VII/IX/X，**注意血栓风险（尤其大剂量、肝功能不全者）**","renal":"无需调整","hepatic":"肝功能不全者慎用（血栓风险）","interact":"与抗纤溶药合用（氨甲环酸）需间隔（有血栓风险争议）"},{"name":"艾美赛珠单抗（双特异性抗体，血友病 A 非因子治疗）","dose":"预防治疗：3 mg/kg 皮下每周 1 次，或 1.5 mg/kg 每 2 周，或 6 mg/kg 每 4 周","note":"**适用于含抑制物或不含抑制物的重型血友病 A**，可显著降低年出血率；需注意与 PCC/APCC 联用有血栓风险","renal":"无需调整","hepatic":"中度肝损害慎用","interact":"**避免与大剂量 PCC/APCC 联用（血栓性微血管病风险）**"},{"name":"去氨加压素（DDAVP，轻型血友病 A）","dose":"0.3 µg/kg 静脉滴注（>30 分钟）或鼻喷 150–300 µg，q12–24h","note":"**仅对轻型血友病 A 有效**（可提升 FVIII 2–4 倍）；对重型无效，血友病 B 基本无效；需监测血钠（低钠血症风险，尤其儿童与老人）","renal":"肾功能不全者慎用（低钠风险）","hepatic":"无需调整","interact":"与三环类抗抑郁药、NSAIDs 合用增加低钠风险"},{"name":"氨甲环酸（抗纤溶，辅助）","dose":"口服 15–25 mg/kg bid–tid；静脉 10 mg/kg q8h；用于黏膜出血与牙科操作","note":"作为替代治疗的辅助，对黏膜出血与拔牙特别有效；**血尿患者禁用**（可致血块阻塞输尿管）","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与口服避孕药合用增加血栓风险"},{"name":"凝血酶原复合物（活化型，APCC）或重组因子 VIIa（含抑制物出血）","dose":"APCC 50–100 IU/kg 静脉 q8–12h；rFVIIa 90 µg/kg q2–3h 至止血","note":"用于**含高滴度抑制物**患者的出血；需监测血栓并发症","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与艾美赛珠单抗联用增加 TMA 风险"},{"name":"艾米珠单抗（抑制物根除，免疫耐受诱导 ITI 方案）","dose":"ITI 方案：FVIII 50–100 IU/kg 每周 3 次（或按方案），持续数月至 2 年","note":"目的是清除抑制物；成功率 60%–80%（低滴度更高）；需在血友病中心进行","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**预防治疗**（重型患者规律输注以维持谷水平 ≥1%）：显著减少关节出血与致残，是儿童血友病的标准治疗","**急性出血的 RICE 原则**（休息、冰敷、加压、抬高）与关节制动","**颅内出血**：立即大剂量因子替代，神经外科评估与血压管理","**禁用肌肉注射**（出血风险），疫苗尽量皮下注射","**避免 NSAIDs 与阿司匹林**（影响血小板），镇痛首选对乙酰氨基酚与短期阿片类","关节置换/滑膜切除（终末期血友病性关节病）","**基因治疗**（近年已在国外获批用于血友病 A/B，国内尚在临床研究）"],"life":["**避免对抗性接触运动**（足球、橄榄球、拳击），但鼓励游泳与骑行（低碰撞风险运动）","家庭输液培训（患者或家长掌握自我输注）令早期治疗可行","**携带者女性**：FVIII 活性约 50%，可有月经量过多与产后出血；需评估并记录","牙科与手术前须告知医师并覆盖因子","登记与随访：国家血友病登记系统、每年关节评估（MRI/超声）","心理与社会支持（慢性病、频繁输注、遗传咨询）"]},"prog":"规范预防治疗可使重型血友病患者的年关节出血率降至 <2–3 次，关节功能接近正常，预期寿命接近一般人群。**抑制物的产生是最大挑战**（约 30% 重型血友病 A），使治疗复杂化与病死率升高。未治疗或治疗不足者常在 20–30 岁出现严重关节畸形与残疾。颅内出血是主要死因（死亡率约 20%）。","refs":["《血友病诊断与治疗中国专家共识（2021 年版）》（中华医学会血液学分会血栓与止血学组）","2020 World Federation of Hemophilia (WFH) Guidelines for the Management of Hemophilia (3rd edition)","2020 MASAC Guidelines on the Treatment of Hemophilia and Other Bleeding Disorders (NHF)","《中国血友病管理指南（2023）》"]},{"id":"he_vwd","name":"血管性血友病","aka":["von Willebrand Disease","vWD","血管性血友病因子缺乏"],"rank":2,"basic":{"define":"由血管性血友病因子（vWF）数量或质量异常所致的遗传性出血性疾病，是最常见的遗传性出血病（患病率约 1%，有症状者约 0.1%）。vWF 介导血小板黏附于受损血管内皮下，并作为载体稳定循环中的因子 VIII。","risk":["**常染色体遗传（多数为显性，1 型与 2 型；3 型为隐性）**","家族史（多数患者有明确家族史）","月经过多与产后出血的女性患者突出","O 型血人群 vWF 水平天然偏低（约 25% 低于正常下限，但多无出血症状）"],"epi":"患病率约 1%（以实验室指标计），有临床出血表现者约 0.1%（约 100/100 万）。1 型（数量减少）占 70%–80%，2 型（质量异常）占 15%–20%，3 型（几乎完全缺乏）罕见（约 1/100 万）。"},"patho":"vWF 由内皮细胞与巨核细胞合成，储存于 Weibel-Palade 小体与血小板 α 颗粒。其功能有二：① 在血流高剪切力下与血小板糖蛋白 Ib-IX-V 结合，介导血小板黏附（一期止血）；② 与因子 VIII 结合形成复合物，保护 FVIII 不被降解（缺乏 vWF 时 FVIII 亦降低）。2 型 vWD 分为 2A（vWF 多聚体异常，缺乏大分子多聚体）、2B（vWF 对血小板 GPIb 亲和力增高，致血小板清除、血小板减少）、2M（功能缺陷但多聚体正常）、2N（vWF 与 FVIII 结合力降低，类似轻型血友病 A）。","dx":{"criteria":["临床表现：**黏膜出血为主**——鼻衄、牙龈出血、皮肤瘀斑、**月经过多（女性最常见的出血表现）**、拔牙或手术后延迟性出血、产后出血；3 型可有类似血友病的关节与肌肉出血","初筛：**出血时间（或 PFA-100）延长、血小板计数正常、APTT 可正常或轻度延长**（因 FVIII 轻度降低）","**确诊三项**：vWF 抗原（vWF:Ag）、vWF 活性（vWF:RCo 或 VWF:GPIbM）、FVIII 活性；同时计算 vWF:RCo/vWF:Ag 比值","**分型**：1 型——三项均轻度降低（比值 >0.7）；2A 型——vWF:RCo 显著低于 vWF:Ag（比值 <0.7）、多聚体分析缺大分子多聚体；2B 型——低浓度利托霉素诱导血小板聚集（RIPA）增强、血小板减少；2M 型——vWF:RCo 降低而多聚体正常；2N 型——vWF:Ag 与 vWF:RCo 正常但 FVIII 显著降低（与血友病 A 混淆）","**需重复检测**（vWF 为急性期反应蛋白，感染、应激、妊娠、口服避孕药可使其升高导致假阴性）；建议在非应激状态、停用避孕药后复查 2–3 次","**应在一生中至少检测一次**（部分女性需在月经期外检测）"],"workup":["血常规、APTT、PT、纤维蛋白原","**vWF:Ag、vWF:RCo（或 VWF:GPIbM）、FVIII:C**","**vWF 多聚体分析**（分型关键，2A 与 2M 的区分）","**利托霉素诱导血小板聚集（RIPA）**（2B 型诊断，低浓度即增强）","血小板计数（2B 型常有轻度血小板减少）","**vWF 基因（VWF）检测**（分型困难、产前诊断、家族筛查）","出血评分（ISTH-BAT 或 Condensed MCMDM-1 VWD 问卷）","排除获得性 vWD（主动脉瓣狭窄、LVAD、肿瘤、甲状腺功能减退、药物）"],"grading":"**ISTH 分型**：1 型（部分量缺乏，多数显性遗传）；2A 型（质量异常伴大分子多聚体缺失）；2B 型（对血小板亲和力增高，RIPA 增强，血小板减少）；2M 型（质量异常但多聚体正常）；2N 型（与 FVIII 结合缺陷）；3 型（完全缺乏，隐性，出血最重）。按严重度分出轻（仅手术/外伤后出血）、中、重（3 型）。"},"ddx":[{"name":"血友病（he_hemophilia）","point":"与血友病的鉴别：血友病以**关节/肌肉深部出血**为主、APTT 明显延长、FVIII 或 FIX 显著降低、vWF 正常；vWD 以黏膜出血为主、vWF 异常。**2N 型 vWD 与轻型血友病 A 极易混淆**，需查 vWF:Ag 与多聚体。"},{"name":"粒细胞缺乏症（he_agranulocytosis）","point":"与粒缺的鉴别：粒缺为感染性表现，无出血；vWD 为出血性疾病。"},{"name":"血小板功能缺陷（血小板无力症、药物性）","point":"出血时间延长但 vWF 抗原与活性正常、血小板聚集试验异常；阿司匹林等药物史需询问。"},{"name":"免疫性血小板减少症（itp）","point":"**血小板计数显著减少**是关键区别；vWD 的血小板计数正常（2B 型可轻度降低）。"},{"name":"获得性 vWD","point":"老年、主动脉瓣狭窄（Heyde 综合征）、LVAD、肿瘤、甲状腺功能减退者出现 vWF 降低；无家族史与儿童期出血史。"},{"name":"遗传性毛细血管扩张症（HHT）","point":"反复鼻衄 + 皮肤黏膜毛细血管扩张 + 内脏动静脉畸形；vWF 正常。"}],"tx":{"drug":[{"name":"去氨加压素（DDAVP，1 型与部分 2A/2M 型）","dose":"0.3 µg/kg 静脉滴注（>30 分钟）或鼻喷 150–300 µg；或口服 0.1–0.2 mg/kg；**术前 30–60 分钟给药**","note":"**1 型首选**（可提升 FVIII 与 vWF 2–5 倍）；**2B 型禁用**（可致血小板减少加重与血栓）；3 型无效；需监测血钠（低钠血症，尤其儿童与老年人）与 tachyphylaxis（连续用药效应递减）","renal":"肾功能不全者慎用（低钠与蓄积）","hepatic":"无需调整","interact":"与三环类抗抑郁药、NSAIDs、SSRI 合用增加低钠风险"},{"name":"vWF/FVIII 浓缩剂（含 vWF 因子制剂）","dose":"按出血程度：轻微出血 20–40 IU/kg；重大手术/出血 40–60 IU/kg，每日或隔日；目标 vWF:RCo >50%（重大出血）或 >30%（轻微）","note":"**2 型、3 型与去氨加压素无效者的首选**；需监测 vWF:RCo 与 FVIII（含 vWF 制剂中 FVIII 比例高，反复给药可致 FVIII 过高与血栓）","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"氨甲环酸（抗纤溶，辅助）","dose":"口服 15–25 mg/kg bid–tid；静脉 10 mg/kg q8h；用于黏膜出血、拔牙与月经量多","note":"对黏膜出血尤其有效，常与去氨加压素或替代治疗联用；**血尿者禁用**","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与口服避孕药合用增加血栓风险"},{"name":"复方口服避孕药 / 左炔诺孕酮宫内缓释系统（月经过多）","dose":"按常规妇科剂量使用（如去氧孕烯炔雌醇片，或 LNG-IUS 放置）","note":"**vWD 女性月经过多的一线治疗**，可显著改善生活质量；需评估血栓风险","renal":"无需调整","hepatic":"肝病者慎用","interact":"与 CYP3A4 诱导剂合用降低避孕效果"},{"name":"抗纤溶 + 局部止血（牙科/小手术）","dose":"氨甲环酸漱口液（4.8%）含漱 2 分钟，每日 4 次，术前至术后 7 天","note":"牙科操作的标准化处理，可显著减少出血","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**出血评分与个体化方案**：按分型与出血表现制定（轻度 1 型仅在手术/外伤时处理）","**手术前需评估 vWF:FVIII 水平并制定替代方案**（尤其 2、3 型）","2B 型：**禁用去氨加压素**，需用 vWF 浓缩剂；孕期血小板可下降（需专科监测）","3 型：预防治疗（类似血友病）以防关节出血","局部止血措施（压迫、冰敷、明胶海绵）","孕期管理：vWF 随妊娠生理性升高，分娩后迅速下降（产后出血风险高），需产后监测 4–6 周"],"life":["**避免 NSAIDs 与阿司匹林**（加重黏膜出血）","避免对抗性运动与易外伤活动（3 型更严格）","牙科卫生（减少牙龈出血与拔牙需求）","**携带者与家系筛查**（常染色体遗传，子女风险 50%）","女性患者计划妊娠前应至血友病/血栓止血中心评估","随身携带疾病标识卡（手术/外伤时告知医师）"]},"prog":"1 型多数为轻型，生活质量接近正常，仅在手术与外伤时需处理。2 型与 3 型出血更重，3 型可类似重型血友病（反复关节出血）。规范的围手术期与产科管理可显著降低出血并发症。女性月经过多若未识别，可致慢性缺铁性贫血。整体预后良好，严重出血事件（尤其产后与术后）是主要风险。","refs":["《血管性血友病诊断与治疗中国专家共识（2021 年版）》（中华医学会血液学分会血栓与止血学组）","2021 ASH/ISTH/NHF/WFH Guideline on the Diagnosis and Management of von Willebrand Disease (Blood Advances)","2012 ISTH SSC on VWF Guidelines for the Diagnosis of von Willebrand Disease","《中国成人月经过多诊治专家共识》（妇科部分参照）"]},{"id":"he_agranulocytosis","name":"粒细胞缺乏症","aka":["Agranulocytosis","中性粒细胞缺乏症","Febrile Neutropenia","粒缺伴发热"],"rank":3,"basic":{"define":"外周血中性粒细胞绝对值（ANC）<0.5×10⁹/L（或 <1.0×10⁹/L 且预计 48 小时内降至 <0.5×10⁹/L）的状态，可导致严重细菌与真菌感染。**粒缺伴发热是血液科急症**，需立即经验性抗生素。","risk":["**药物（最常见）**：抗甲状腺药（甲巯咪唑、丙硫氧嘧啶）、氯氮平、抗癫痫药（卡马西平）、磺胺类、青霉素类、化疗药、免疫抑制剂","化疗与放疗（骨髓抑制）","自身免疫性（SLE、Felty 综合征）","感染（病毒、结核、败血症）","骨髓疾病（MDS、白血病、骨髓转移）","先天性（Kostmann 综合征等，罕见）"],"epi":"药物性粒缺的年发病率约 2–15/100 万。氯氮平相关粒缺发生率约 0.4%–0.8%，甲巯咪唑约 0.1%–0.5%。粒缺伴发热的病死率约 5%–10%（若不及时治疗可达 20%–30%）。"},"patho":"中性粒细胞是抵御细菌与真菌的第一道防线。当 ANC <0.5×10⁹/L 时，吞噬与杀菌能力严重下降，感染风险与严重程度急剧升高；ANC <0.1×10⁹/L 时感染几乎不可避免。粒缺时炎症反应减弱（**无脓性分泌物**，可无典型体征），故感染常隐匿进展，发热是唯一可靠信号。药物性粒缺的机制包括免疫介导（药物-抗体复合物致粒细胞破坏）与直接骨髓抑制（剂量依赖）。","dx":{"criteria":["**ANC <0.5×10⁹/L**（或 <1.0×10⁹/L 且预计 48 小时内下降至 <0.5×10⁹/L）","**粒缺伴发热的定义**：单次口腔温度 ≥38.3 ℃，或 ≥38.0 ℃ 持续 ≥1 小时，且 ANC <0.5×10⁹/L（或预计下降）","临床：发热、咽痛、口腔溃疡（坏死性牙龈炎）、肛周疼痛、肺部感染（可无咳嗽与痰）","**注意：粒缺患者可无明显感染灶体征**（无脓液、无红肿），故需系统筛查","用药史（详细询问近 8 周内所有新加药物，尤其抗甲状腺药、氯氮平、抗癫痫药、磺胺、NSAIDs）","外周血涂片（确认 ANC 降低并排除其他血细胞减少原因）"],"workup":["**血常规 + 分类（计算 ANC）+ 网织红细胞**","**血培养（外周 + 中心静脉各一套）、尿培养、痰培养、必要时皮肤/肛周拭子**","胸片或肺部 CT（**粒缺患者肺部感染可无影像表现，CT 更敏感**）","CRP、PCT、肝肾功能、电解质","**停用与记录可疑药物**（药物性粒缺的核心处理）","骨髓穿刺（持续粒缺 >2 周、疑血液病者）","自身免疫筛查（ANA、抗中性粒细胞抗体）","真菌感染筛查（长期粒缺 >7 天，G/GM 试验、肺部 CT）"],"grading":"按严重度分：轻度（ANC 1.0–1.5×10⁹/L）、中度（0.5–1.0）、重度（<0.5）、极重度（<0.1×10⁹/L）。化疗相关粒缺伴发热按 MASCC 评分（≥21 为低危，可考虑门诊口服抗生素）分低危与高危。"},"ddx":[{"name":"血友病（he_hemophilia）","point":"与血友病的鉴别：血友病为出血性疾病（APTT 延长、因子缺乏），无粒细胞减少与感染；粒缺为感染 + ANC 降低。"},{"name":"血管性血友病（he_vwd）","point":"与 vWD 的鉴别：vWD 为黏膜出血、vWF 异常，血细胞计数正常。"},{"name":"再生障碍性贫血（aa）","point":"AA 为全血细胞减少（贫血 + 粒缺 + 血小板减少）伴骨髓增生低下；单纯粒缺的贫血与血小板可正常。"},{"name":"急性白血病（aml/he_all）","point":"白血病可表现为粒缺，但骨髓见原始细胞增多、外周血见幼稚细胞；需骨髓确诊。"},{"name":"病毒感染（如 HIV、传染性单核细胞增多症）","point":"病毒性粒缺多为暂时性、可自限，伴原发病毒感染表现；需病毒学确认。"},{"name":"Felty 综合征（类风湿关节炎 + 脾大 + 粒缺）","point":"有长期 RA 病史与脾大，ANA 与 RF 阳性；与药物性粒缺的区别在病史。"},{"name":"MDS 相关粒缺","point":"骨髓见病态造血、染色体异常；需骨髓检查。"}],"tx":{"drug":[{"name":"哌拉西林他唑巴坦（经验性广谱抗生素，首选）","dose":"4.5 g 静脉 q6h（或 q8h 延长输注），**发热后 1 小时内给药**","note":"**粒缺伴发热必须在 60 分钟内启动经验性广谱抗生素**（覆盖假单胞菌与革兰阴性菌，这是降低病死率的关键）；疗程通常至 ANC >0.5×10⁹/L 且无感染灶 48 小时","renal":"按 CrCl 调整（CrCl 20–40：4.5 g q8h；<20：2.25 g q8h）","hepatic":"无需调整","interact":"与甲氨蝶呤合用增加毒性；与华法林合用增加出血"},{"name":"头孢吡肟 / 美罗培南（替代或升级）","dose":"头孢吡肟 2 g 静脉 q8h；美罗培南 1 g q8h（或延长输注）","note":"用于β内酰胺过敏、或血流动力学不稳定；美罗培南覆盖产 ESBL 菌","renal":"两者均按 CrCl 调整","hepatic":"美罗培南肝毒性低","interact":"美罗培南显著降低丙戊酸浓度（癫痫失控）"},{"name":"万古霉素（疑 MRSA 或导管相关感染）","dose":"15–20 mg/kg 静脉 q8–12h，目标谷浓度 15–20 mg/L","note":"**不推荐所有粒缺伴发热常规联合万古霉素**；用于疑导管感染、MRSA 定植、软组织感染、肺炎或血流动力学不稳定","renal":"严格按 CrCl 调整并监测","hepatic":"无需调整","interact":"与氨基糖苷、两性霉素 B 合用增加肾毒性"},{"name":"粒细胞集落刺激因子（G-CSF，非格司亭/培非格司亭）","dose":"非格司亭 5 µg/kg 皮下 qd（或培非格司亭 6 mg 皮下一次/周期）；药物性粒缺：**5 µg/kg qd 至 ANC >1.0×10⁹/L**","note":"**药物性粒缺可显著缩短病程**（尤其中重度）；化疗后预防性使用需按指南的风险评估（FN 风险 >20% 或既往 FN）；不良反应为骨痛","renal":"无需调整","hepatic":"无需调整","interact":"与化疗同时使用不推荐（间隔 24–48 小时）；与锂盐合用可增加白细胞"},{"name":"抗真菌药（长期粒缺，经验性或目标治疗）","dose":"经验性：卡泊芬净 70 mg 负荷后 50 mg qd，或伏立康唑 6 mg/kg q12h×2 次后 4 mg/kg q12h；脂质体两性霉素 B 3 mg/kg qd","note":"**持续粒缺 >7 天且发热不退**者需加用抗真菌药（侵袭性真菌感染风险高）；用伏立康唑需监测血药浓度与肝功能","renal":"卡泊芬净无需调整；伏立康唑静脉制剂在 CrCl <50 慎用（改用口服）","hepatic":"伏立康唑肝毒性，需监测；卡泊芬净中度肝损减量","interact":"伏立康唑禁忌与多种 CYP3A4 底物合用（他克莫司、西罗莫司需减量）"},{"name":"粒细胞输注（极重度、难治性感染）","dose":"由血库按方案提供（通常每日一次，至感染控制或 ANC 恢复）","note":"用于 ANC <0.1×10⁹/L 且难治性严重感染；需 HLA 配型与辐照，证据有限，仅特定中心开展","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**立即停用可疑药物**（药物性粒缺的首要措施）","**发热 60 分钟内启动经验性抗生素**（不可等待培养结果）","保护性隔离（单间、空气净化、限制探视、手卫生）","口腔护理（氯己定漱口）与肛周护理（防便秘与肛裂）","**避免直肠测温与直肠给药**（感染与出血风险）","粒缺期间避免生食（水果蔬菜需去皮或煮熟）、避免接触宠物与鲜花"],"life":["**发热（≥38.3 ℃）立即就医**，不可在家观察（患者与家属教育）","服药期间定期查血常规（抗甲状腺药、氯氮平需按规范监测：氯氮平前 18 周每周一次）","粒缺恢复后需明确病因并记录于病历（避免再次使用同类药物）","营养支持与充足睡眠（促进骨髓恢复）","化疗患者需了解 FN 风险与体温监测方法"]},"prog":"药物性粒缺在停药 + G-CSF 下多在 1–3 周恢复（病死率约 5%–10%，老年与合并感染更高）。化疗相关粒缺伴发热的病死率约 5%，MASCC 低危者可门诊口服治疗。**延迟抗生素是预后不良的最重要因素**（每延迟 1 小时病死率上升）。持续粒缺 >7 天者侵袭性真菌感染风险显著升高。","refs":["《中国中性粒细胞缺乏伴发热患者抗菌药物临床应用指南（2020 年版）》（中华医学会血液学分会）","2018 IDSA Clinical Practice Guideline for the Use of Antimicrobial Agents in Neutropenic Patients with Cancer (updated)","2019 ASCO/CCO Clinical Practice Guideline: Management of Febrile Neutropenia in Adult Cancer Patients","《抗甲状腺药物致粒细胞缺乏症诊治专家共识》（中华医学会内分泌学分会）"]}]},{"id":"mpn_more","name":"骨髓增殖性肿瘤（补充）","rank":41,"summary":"原发性骨髓纤维化是 BCR-ABL1 阴性的克隆性髓系肿瘤：脾大 + 泪滴状红细胞 + 骨髓纤维化 + JAK2/CALR/MPL 突变构成诊断骨架，DIPSS 决定预后与移植时机；有症状或脾大者首选芦可替尼，但必须按血小板分层起始并警惕停药反跳，唯一治愈手段是异基因移植。","compare":[{"diseaseId":"he_pmf","dx":"脾大、乏力盗汗、泪滴状红细胞与幼粒-幼红细胞，骨髓活检见巨核异型与网硬蛋白纤维化（MF-2/3），JAK2/CALR/MPL 突变或克隆性证据，BCR-ABL1 阴性","key":"骨髓纤维化 + 巨核异型 + 泪滴状红细胞；DIPSS 分层决定是否行异基因移植"}],"diseases":[{"id":"he_pmf","name":"原发性骨髓纤维化","aka":["Primary myelofibrosis","PMF","骨髓纤维化","原发性骨髓纤维化症","Myelofibrosis"],"rank":1,"basic":{"define":"原发性骨髓纤维化（PMF）是 BCR-ABL1 阴性的骨髓增殖性肿瘤（MPN），以克隆性髓系增殖、巨核细胞异型、进行性骨髓纤维化、髓外造血（脾大）与骨髓衰竭为特征。按纤维化程度分早期/纤维化前期（pre-PMF，MF-0/1）与明显纤维化期（overt PMF，MF-2/3），后者可继发于 PV 或 ET（post-PV/ET MF）。","risk":["年龄 >60 岁（中位发病 65 岁左右），男性略多","驱动突变：JAK2 V617F 约 50%–60%、CALR 外显子 9 约 25%–30%、MPL W515 约 5%–10%，三阴性 10%–15%","既往真性红细胞增多症或原发性血小板增多症进展（post-PV/ET MF）","苯、电离辐射、烷化剂或放疗暴露史","家族性 MPN（一级亲属患病）与 JAK2 胚系变异","高危突变：ASXL1、EZH2、SRSF2、IDH1/2、U2AF1 Q157（HMR 突变）"],"epi":"年发病率约 0.5–1.5/10 万，中位发病年龄 65 岁左右，我国发病年龄较西方略年轻。overt PMF 中位生存约 5–7 年，pre-PMF 生存接近同龄人群；10 年内约 10%–20% 转化为急性髓系白血病。"},"patho":"JAK2、CALR 或 MPL 突变激活 JAK-STAT 通路，使髓系祖细胞对细胞因子过度敏感并克隆性扩增。异常巨核细胞释放 TGF-β、PDGF 与 FGF，激活成纤维细胞与基质细胞，导致网硬蛋白与胶原在骨髓沉积、窦壁破坏与髓外造血。炎症因子（IL-6、TNF-α、IL-1β）引起发热、盗汗、体重下降与骨痛；脾脏承担髓外造血而进行性增大，并可致门脉高压。克隆演化获得 HMR 突变后增殖优势增强，是白血病转化的基础。","dx":{"criteria":["血常规与涂片：贫血（Hb <100 g/L 见于约 50%）、白细胞增多或减少、血小板增多或减少；外周血见泪滴状红细胞（dacrocyte）、幼粒-幼红细胞与巨大血小板；原始细胞 <20%（≥20% 为急性骨髓纤维化/AML）","脾大：可触及脾大见于 80%–90%，巨脾（肋下 >10 cm）提示髓外造血，可伴门脉高压、腹水与早饱","骨髓活检（诊断核心）：巨核细胞增生伴异型（核折叠、分叶过多、致密染色质、裸核），网硬蛋白/胶原纤维化按 WHO 分级 MF-2/3，常伴骨硬化与窦内造血；穿刺常干抽","克隆标志：JAK2 V617F 或外显子 12、CALR 外显子 9、MPL W515 阳性；三阴性者需 ASXL1/EZH2/SRSF2/IDH1/2/U2AF1 等体细胞突变或核型异常支持克隆性","排除标准：不符合 PV（Hb 男 >165 g/L、女 >160 g/L 且 EPO 降低）、ET（血小板 ≥450×10⁹/L 且无纤维化）、CML（BCR-ABL1 阳性）、MDS（病态造血）或其他髓系肿瘤","pre-PMF 与 overt PMF：pre-PMF 纤维化 MF-0/1、脾大不明显、血象轻中度异常但巨核异型显著；overt PMF 为 MF-2/3，常伴明显脾大、泪滴状红细胞与骨髓衰竭","DIPSS 分期：年龄 >65 岁（1 分）、全身症状（1 分）、Hb <100 g/L（2 分）、WBC >25×10⁹/L（1 分）、外周血原始细胞 ≥1%（1 分）；0 分低危、1 分中危-1、2 分中危-2、≥3 分高危"],"workup":["血常规 + 外周血涂片（泪滴状红细胞、幼粒-幼红细胞、原始细胞百分比）、网织红细胞、LDH、尿酸","骨髓穿刺与活检：活检长度应 ≥1.5 cm，报告增生程度、巨核形态、纤维化分级（MF-0–3）与骨硬化；必要时加做免疫组化（CD34、CD61）","分子检测：JAK2 V617F 与外显子 12、CALR、MPL；BCR-ABL1 必须阴性；二代测序覆盖 ASXL1、EZH2、SRSF2、IDH1/2、U2AF1、TP53","染色体核型分析（不良核型：复杂核型、+8、-7/7q-、i(17q)、inv(3)、-5/5q-、11q23、12p-）","腹部超声或 CT 评估脾大程度与门脉高压；血清 EPO（排除 PV）","HLA 配型与器官功能评估（年龄 <70 岁、DIPSS 中危-2/高危者备移植）；乙肝/丙肝/HIV 与结核筛查（芦可替尼治疗前）"],"grading":"DIPSS 中位生存：低危未达到、中危-1 约 14.2 年、中危-2 约 4 年、高危约 1.5 年。DIPSS-plus 在 DIPSS 基础上增加血小板 <100×10⁹/L、输血依赖与不良核型三项。MIPSS70/MIPSS70-plus 与 GIPSS 纳入 HMR 突变与核型，用于移植决策。pre-PMF 按 WHO 形态学标准与 MF 分级诊断。"},"ddx":[{"name":"真性红细胞增多症与原发性血小板增多症（he_mpn）","point":"本大类仅含原发性骨髓纤维化 1 个病，同属 MPN 的最近邻是 PV/ET：PV 以 Hb 男 >165 g/L、EPO 降低、骨髓三系增生为主，ET 以血小板 ≥450×10⁹/L、巨核大而成熟为主；两者网硬蛋白纤维化多为 MF-0/1、无泪滴状红细胞与幼粒-幼红细胞，脾大多轻。出现明显纤维化与脾大即应考虑 post-PV/ET MF。"},{"name":"慢性髓性白血病（cml）","point":"CML 为 BCR-ABL1 阳性，粒系左移、嗜碱性粒细胞增多、脾大明显，但巨核异型与网硬蛋白纤维化不突出；PMF 的 BCR-ABL1 阴性。"},{"name":"骨髓增生异常综合征（he_mds）","point":"MDS 以病态造血（环形铁粒幼细胞、粒系颗粒减少、多核红系）与血细胞减少为主，骨髓增生活跃但无成簇异型巨核，脾大少见；PMF 巨核异型显著且纤维化进行性加重。"},{"name":"急性骨髓纤维化 / 急性髓系白血病（aml）","point":"原始细胞 ≥20% 即诊断为 AML（急性全髓增殖伴骨髓纤维化者原始细胞可不高但病程凶险）；PMF 外周血与骨髓原始细胞 <20%，病程以年计。"},{"name":"毛细胞白血病或淋巴瘤骨髓浸润","point":"脾大 + 干抽 + 全血细胞减少需警惕：毛细胞白血病骨髓见毛细胞（CD11c/CD25/CD103/CD123 阳性），淋巴瘤见克隆性淋巴细胞；JAK2/CALR/MPL 阴性。"},{"name":"继发性骨髓纤维化","point":"转移癌、结核、自身免疫病、肾性骨病等可引起反应性纤维化，有原发病证据、脾大不明显、无 MPN 驱动突变，骨髓巨核形态正常。"},{"name":"肝硬化门脉高压性脾大","point":"肝功能异常、血小板减少与脾大，但骨髓无纤维化与巨核异型，影像见肝硬化结节、门静脉增宽与侧支循环；PMF 的肝功能多正常而脾大更显著。"}],"tx":{"drug":[{"name":"芦可替尼（Ruxolitinib）","dose":"按血小板分层起始：血小板 >200×10⁹/L 用 20 mg bid；100–200×10⁹/L 用 15 mg bid；50–<100×10⁹/L 用 5 mg bid；<50×10⁹/L 不推荐使用。每 2–4 周复查血象调整，血小板 <100×10⁹/L 减量、<50×10⁹/L 停药","note":"JAK1/2 抑制剂，可缩小脾脏（≥35%）、改善全身症状与生存；起效需 4–12 周。**不可骤停**——突然停药可致反跳性脾大、发热、低血压甚至休克样表现，需在 1–2 周内逐渐减量。主要不良反应为血小板减少、贫血、感染（带状疱疹、结核再激活）。","renal":"CrCl 15–59 ml/min 起始剂量减半；CrCl <15 ml/min 或透析者进一步减量并密切监测血象","hepatic":"Child-Pugh B/C 起始剂量减半，重度肝损伤慎用","interact":"强 CYP3A4 抑制剂（酮康唑、克拉霉素、利托那韦）使浓度升高，需减量约 50%；强诱导剂（利福平、卡马西平）降低疗效；与抗凝药、抗血小板药合用增加出血"},{"name":"羟基脲","dose":"起始 15–20 mg/(kg·d) 口服（常用 500 mg bid），按血象调整；目标 WBC <15×10⁹/L、血小板 <400×10⁹/L 或脾脏缩小","note":"用于高白细胞/血小板增多、脾大或芦可替尼不可及时的桥接治疗；起效快但不能改善纤维化。注意皮肤溃疡、口腔黏膜炎与骨髓抑制。","renal":"CrCl <60 ml/min 减量约 50%，透析后给药","hepatic":"肝功能不全者减量并监测血象","interact":"与其他骨髓抑制药或放疗合用加重骨髓抑制；与活疫苗合用可致播散性感染"},{"name":"聚乙二醇干扰素 α-2a","dose":"45–90 μg 皮下注射 qw 起始，按血象滴定（目标 WBC 4–10×10⁹/L、血小板 100–400×10⁹/L）","note":"适用于 pre-PMF、血小板增多或年轻患者，部分可获得驱动突变负荷下降与纤维化改善；起效慢（3–6 个月），耐受性差（流感样症状、抑郁、甲状腺功能异常）。","renal":"CrCl <30 ml/min 减量，遵说明书","hepatic":"失代偿肝病禁用","interact":"与骨髓抑制药合用加重血细胞减少；与茶碱等 CYP1A2 底物合用需监测"},{"name":"重组人促红素（EPO）","dose":"10 000 U 皮下 tiw 或 40 000 U 皮下 qw；目标 Hb 110–120 g/L，8–12 周 Hb 上升 <10 g/L 为无效停药","note":"用于贫血（Hb <100 g/L）且血清 EPO <500 mU/mL 者；Hb >120 g/L 增加血栓与死亡风险，不应追求正常化。","renal":"肾功能不全者按贫血治疗常规使用，注意血压","hepatic":"遵说明书","interact":"与 ACEI、ARB 合用可能减弱疗效；与铁剂联用需先纠正缺铁"},{"name":"达那唑","dose":"200 mg 口服 bid–tid，疗程 3–6 个月，有效后减至最低维持量","note":"用于贫血或血小板减少（尤其女性），起效慢；男性化（声音变粗、多毛）、肝功能异常、血脂升高与水肿常见。","renal":"肾功能不全或水肿者慎用","hepatic":"胆汁淤积性黄疸或肝功能明显异常者禁用","interact":"与华法林合用增强抗凝（需减量）；与他汀合用增加肌病风险"},{"name":"沙利度胺 / 来那度胺","dose":"沙利度胺 50–100 mg 口服 qn（低剂量，可联合泼尼松 0.5 mg/kg/d）；来那度胺 5–10 mg 口服 qd（伴 del(5q) 者 10 mg/d，21/28 天）","note":"用于贫血、血小板减少或脾大，单药缓解率有限；沙利度胺致镇静、便秘、周围神经病，两药均致畸，需严格避孕与血栓预防。","renal":"来那度胺按 CrCl 减量（30–59 减量，<30 透析后给药）；沙利度胺重度肾损慎用","hepatic":"肝功能不全者减量，遵说明书","interact":"与地塞米松合用血栓风险增加，需预防性抗凝；沙利度胺与中枢抑制药合用加重嗜睡"},{"name":"阿司匹林","dose":"75–100 mg 口服 qd","note":"仅用于血小板 >100×10⁹/L、无出血史与无严重血小板功能障碍者；PMF 出血风险高于 PV/ET，血小板低或凝血异常时不用。","renal":"CrCl <30 ml/min 慎用","hepatic":"严重肝病伴凝血障碍者禁用","interact":"与抗凝药、NSAID、SSRI 合用增加消化道出血；与甲氨蝶呤合用增加骨髓毒性"},{"name":"别嘌醇","dose":"300 mg 口服 qd（CrCl 60 以下减量：30–59 用 200 mg/d，15–29 用 100 mg/d）","note":"用于高尿酸血症与肿瘤溶解预防；起始从小剂量并监测皮疹（重症药疹风险，汉族 HLA-B*5801 携带者更高）。","renal":"按 CrCl 减量（见剂量栏）","hepatic":"肝功能不全者慎用并监测","interact":"与硫唑嘌呤/6-巯基嘌呤合用需减至原剂量 1/4–1/3（严重骨髓抑制）；与阿莫西林合用皮疹增加"}],"nonDrug":["异基因造血干细胞移植（allo-HSCT）：唯一可能治愈的手段。指征为年龄 <70 岁（体能好可放宽至 75 岁）、DIPSS 中危-2/高危或 DIPSS-plus 高危，或中危-1 伴输血依赖、难治性脾大、HMR 突变；5 年生存约 30%–50%，移植相关死亡 20%–30%","脾切除：仅用于药物难治性巨脾伴疼痛、反复输血依赖或门脉高压，且血小板 >50×10⁹/L、无严重凝血障碍；手术死亡率 5%–10%，术后血小板可骤升（>1000×10⁹/L 需降细胞与抗凝），并可能加速白血病转化","脾区低剂量放疗（0.1–1 Gy 分次）：用于疼痛性脾大或髓外造血，起效快但维持时间短","支持治疗：Hb <80 g/L 或有症状时输血（目标 80–100 g/L）；感染高危者预防性抗病毒（带状疱疹）与疫苗（流感、肺炎球菌）；痛风预防","门脉高压：普萘洛尔或卡维地洛降低门脉压力，食管静脉曲张中高危者套扎","临床试验：JAK 抑制剂联合方案、端粒酶抑制剂、BET 抑制剂等，尤其适合移植不合适者"],"life":["每 3–6 个月复查血常规、脾脏大小（触诊 + 超声）与 MPN-SAF TSS 症状评分，记录体重、盗汗与瘙痒","芦可替尼治疗前筛查乙肝、丙肝、HIV 与结核；治疗中监测带状疱疹并接种重组带状疱疹疫苗（活疫苗禁用）","输血依赖者每 3 个月查铁蛋白，>1000 μg/L 且预期生存 >1 年考虑祛铁治疗（地拉罗司）","避免脱水、长时间制动与高原旅行；围手术期评估血栓与出血风险，必要时低分子肝素桥接","育龄期严格避孕（芦可替尼有胚胎毒性）；痛风患者避免高嘌呤饮食与饮酒"]},"prog":"overt PMF 中位生存约 5–7 年，DIPSS 分层间差异从 1.5 年至 14 年；pre-PMF 生存接近同龄人群。10 年白血病转化率约 10%–20%，HMR 突变、原始细胞升高与不良核型者更高。allo-HSCT 可治愈但移植相关死亡 20%–30%；主要死因为骨髓衰竭、感染、出血、门脉高压与白血病转化。","refs":["《原发性骨髓纤维化诊断与治疗中国指南（2019 年版）》（中华医学会血液学分会白血病淋巴瘤学组）","WHO Classification of Tumours of Haematopoietic and Lymphoid Tissues（2017 第 4 版修订/2022 第 5 版）","IWG-MRT: DIPSS（2010）与 DIPSS-plus（2011）预后评分系统","NCCN Guidelines: Myeloproliferative Neoplasms（2024）"]}]},{"id":"transfusion","name":"输血与输血反应","rank":42,"summary":"成分输血的核心是「缺什么补什么、能不输就不输」：红细胞 Hb <60 g/L（或 <70 g/L 伴症状）、血小板 <10×10⁹/L 预防性输注是两条硬指征；输血反应先停药、再核对身份，急性溶血与细菌污染最凶险，TRALI 与 TACO 的鉴别决定用不用利尿剂。","compare":[{"diseaseId":"he_transfusion","dx":"有明确输血史，输血中或输血后出现发热、寒战、荨麻疹、溶血、低氧或容量负荷表现；结合 Hb/血小板反应、DAT、BNP 与影像分型","key":"先停输并核对身份；急性溶血（Hb 不升、血红蛋白尿、DAT 阳性）与细菌污染最危急，TRALI 忌利尿、TACO 需利尿"}],"diseases":[{"id":"he_transfusion","name":"输血与输血反应","aka":["Blood transfusion","Transfusion reaction","成分输血","输血不良反应","Transfusion medicine"],"rank":1,"basic":{"define":"成分输血是按血液成分（红细胞、血小板、血浆、冷沉淀）分别输注的替代治疗，遵循患者血液管理（PBM）原则：仅在成分缺乏导致临床后果时输注，并优先用单一成分、最小有效剂量。输血反应是输血过程中或输血后发生的任何不良事件，按时间分急性（≤24 h）与迟发（>24 h），按机制分免疫性与非免疫性；严重者可致休克、急性肺损伤或多器官衰竭。","risk":["反复输血或多次妊娠（HLA/血小板同种免疫，导致血小板输注无效与发热性非溶血反应）","ABO/RhD 血型不合或身份核对差错（急性溶血反应的首要原因）","IgA 缺乏、既往输血过敏史（过敏与类过敏反应）","心功能不全、肾功能不全、老年与低体重（TACO）","大量输注血浆或快速输血（TRALI、枸橼酸中毒、低体温）","免疫抑制、造血干细胞移植、亲属供血（TA-GVHD）与血液制品细菌污染"],"epi":"红细胞输注不良反应总发生率约 1%–3%。TACO 是最常见的严重输血反应（约 1/100–1/1000 次输血），TRALI 约 1/5000–1/10000；急性溶血性输血反应约 1/25 万–1/100 万，多为人为差错，病死率 5%–10%；细菌污染约 1/50 万（血小板制品更高）；TA-GVHD 病死率 >90%。"},"patho":"急性溶血性输血反应多因 ABO 不合，受者 IgM 抗体与供者红细胞结合、激活补体，导致血管内溶血、血红蛋白尿、肾小管阻塞与 DIC；迟发性溶血由 Rh、Kidd、Duffy 等同种 IgG 抗体介导，属血管外溶血。发热性非溶血反应由供者白细胞与受者抗体及细胞因子释放引起。过敏反应由供者血浆蛋白与受者 IgE 介导；IgA 缺乏者抗-IgA 可致严重类过敏反应。TRALI 是供者抗-HLA/抗-HNA 抗体激活受者中性粒细胞、损伤肺毛细血管内皮所致（非心源性肺水肿）；TACO 则是容量负荷超过心肺储备。TA-GVHD 源于供者 T 细胞在免疫抑制受者体内植入并攻击宿主组织。","dx":{"criteria":["红细胞输注指征：Hb <60 g/L 或 Hct <0.18 应输注；Hb 60–100 g/L 结合临床（活动性出血、心肌缺血、组织缺氧症状）决定；Hb >100 g/L 一般不需输注。限制性策略阈值 70 g/L（骨科手术与合并心血管疾病者可放宽至 80 g/L）","血小板输注指征：<10×10⁹/L 预防性输注；<20×10⁹/L 伴发热、感染或出血倾向；<50×10⁹/L 有活动性出血或行侵入性操作；<100×10⁹/L 行神经外科或眼科手术；ITP 不预防性输注（危及生命的颅内出血除外）","血浆输注指征：PT 或 APTT >1.5 倍正常上限伴活动性出血或术前，剂量 10–15 ml/kg；大量输血按 1:1:1 比例；不用于扩容、补充营养或纠正低白蛋白","冷沉淀指征：纤维蛋白原 <1.5 g/L（产科 <2.0 g/L）伴出血，剂量 1–2 U/10 kg","发热性非溶血反应：输血中或输血后 4 h 内体温较基线升高 ≥1℃ 且 ≥38℃，无溶血、无细菌污染证据","急性溶血反应：输血后 24 h 内 Hb 不升或下降、血浆游离血红蛋白升高、结合珠蛋白降低、间接胆红素与 LDH 升高、DAT 阳性、血红蛋白尿；可伴寒战、腰痛、低血压与 DIC","TRALI：输血后 6 h 内新发低氧（PaO₂/FiO₂ ≤300 或 SpO₂ <90%）、胸片双肺浸润、无循环超负荷证据（BNP 不高、CVP 不高、利尿无效）","TACO：输血后 6 h 内呼吸困难、双肺湿啰音、颈静脉怒张、血压升高、BNP 升高、胸片见肺水肿与心影增大，利尿后迅速改善；迟发溶血在输血后 3–14 天出现 Hb 下降、黄疸、DAT 阳性与新抗体"],"workup":["输血前核查：双人核对姓名、住院号、床号、ABO/RhD 血型、交叉配血结果、血袋编号、有效期与血液外观；床旁反问患者姓名并核对腕带","疑诊反应时立即：停止输血、保留静脉通路（0.9% 氯化钠）、复核身份与血袋标签、通知血库退回血袋与输血器","实验室：复查血常规、血浆游离血红蛋白、结合珠蛋白、LDH、间接胆红素、DAT、尿常规与尿血红蛋白、凝血四项与 D-二聚体、血培养（血袋与患者双份）","心肺评估：生命体征、中心静脉压、BNP/NT-proBNP、胸片或肺部超声、心脏超声（区分 TRALI 与 TACO）","免疫学：抗体筛查与鉴定（迟发溶血、血小板输注无效）、HLA/HPA 抗体（TRALI）、血清 IgA 与抗-IgA（严重过敏）","输血后疗效：红细胞输注后 24 h 复查 Hb；血小板输注后 1 h 与 24 h 计算 CCI，CCI <7.5（单位 ×10⁹/L·m²/10¹¹ 血小板）提示无效输注"],"grading":"按时间分急性（≤24 h）与迟发（>24 h）；按机制分免疫性（急性溶血、发热性非溶血、过敏、TRALI、迟发溶血、TA-GVHD、输血后紫癜）与非免疫性（细菌污染、TACO、低血压反应、空气栓塞、枸橼酸中毒、低体温、铁过载）。严重度按 ISBT 分级 1–4 级（1 轻度、2 中度、3 重度、4 死亡）。"},"ddx":[{"name":"自身免疫性溶血性贫血（he_aiha）","point":"本大类仅含输血与输血反应 1 个病，邻类最易混淆的是 AIHA：AIHA 无输血时间关系、DAT 阳性（IgG/C3d）、网织红细胞升高、间接胆红素升高，激素治疗有效；输血后溶血有明确输血史与时间窗（24 h 内或 3–14 天），急性溶血时 DAT 可阴性。"},{"name":"迟发性溶血性输血反应（he_transfusion 急性型的迟发形式）","point":"与本类中急性溶血反应的鉴别点：急性型在输血中或输血后 24 h 内出现寒战、腰痛、血红蛋白尿与 DIC；迟发型在输血后 3–14 天出现不明原因 Hb 下降、黄疸与 DAT 阳性，抗体筛查可发现新抗体（Rh、Kidd、Duffy）。"},{"name":"输血相关急性肺损伤（TRALI）","point":"与 TACO 的鉴别点：TRALI 在 6 h 内低氧、双肺浸润，但血压可偏低、BNP 不高、CVP 不高、利尿无效；TACO 有容量负荷证据、血压升高、BNP 升高、利尿有效。"},{"name":"严重过敏反应与 IgA 缺乏类过敏反应","point":"荨麻疹、喉头水肿、支气管痉挛与低血压在输血开始后数分钟内出现；IgA 缺乏者抗-IgA 抗体介导的类过敏可致休克，需用 IgA 缺乏血浆或洗涤红细胞。"},{"name":"细菌污染性输血反应与脓毒症","point":"寒战、高热（常 >39℃）、休克与 DIC，血小板制品更常见；血袋涂片革兰染色或培养阳性，患者血培养与血袋培养为同一菌株可确诊。"},{"name":"输血相关低血压反应","point":"少见，输血开始后收缩压下降 >30 mmHg 而无溶血、过敏或细菌污染证据，停输后迅速恢复；使用 ACEI 者风险升高。"},{"name":"输血后紫癜与血栓性微血管病","point":"输血后 5–12 天血小板骤降（常 <20×10⁹/L）伴出血，抗-HPA-1a 抗体阳性为输血后紫癜；TTP/DIC 有破碎红细胞、凝血异常与器官损害，需与溶血性输血反应区分。"}],"tx":{"drug":[{"name":"红细胞悬液","dose":"成人 1 U 提升 Hb 约 5 g/L；一般 1–2 U，1 U 在 2 h 内输完（总时长不超过 4 h）；心功能不全者 1 ml/(kg·h)，1 U 分 4 h 输注","note":"输注前 30 min 内测生命体征，前 15 min 慢速（<2 ml/min）并床旁观察；大出血时用加压输血器，需与血浆、血小板按 1:1:1 比例。","renal":"无需调整（肾功能不全者注意容量负荷）","hepatic":"无需调整","interact":"无（与静脉药物同管路时需用 0.9% 氯化钠冲管，避免与钙剂、乳酸林格液同输）"},{"name":"单采血小板","dose":"1 治疗量（≥2.5×10¹¹）提升血小板 20–30×10⁹/L；30–60 min 内输完，ABO 同型优先，RhD 阴性育龄女性应输 RhD 阴性血小板","note":"输注后 1 h 与 24 h 计算 CCI 评估疗效；反复输注无效者选 HLA 配合型或交叉配合型血小板；输注前轻摇血袋，禁止冷藏。","renal":"无","hepatic":"无","interact":"无"},{"name":"新鲜冰冻血浆（FFP）","dose":"10–15 ml/kg（成人 400–600 ml），ABO 相容，30–60 min 内输完；大量输血按 1:1:1 比例","note":"仅用于凝血因子缺乏伴出血或术前，输注前 37℃ 水浴融化并在 24 h 内使用；不用于扩容、补充营养或纠正低白蛋白。","renal":"容量负荷与枸橼酸蓄积风险，肾功能不全者减慢速度","hepatic":"无","interact":"无"},{"name":"冷沉淀","dose":"1–2 U/10 kg（成人常 10–20 U），维持纤维蛋白原 >1.5 g/L（产科 >2.0 g/L），快速输注","note":"用于纤维蛋白原缺乏（DIC、肝衰竭、大量输血、产科出血）；每袋含纤维蛋白原约 150–250 mg，输注后复查纤维蛋白原。","renal":"无","hepatic":"无","interact":"无"},{"name":"肾上腺素（过敏性休克）","dose":"0.3–0.5 mg（1:1000）大腿前外侧肌注，5–15 min 可重复；顽固性低血压 0.05–0.2 μg/(kg·min) 静脉泵入","note":"严重过敏反应的一线用药，糖皮质激素与抗组胺药不能替代；β 受体阻滞剂使用者反应差，可加用胰高血糖素。","renal":"无需调整","hepatic":"无需调整","interact":"三环类抗抑郁药、MAO 抑制剂增强升压反应；β 受体阻滞剂减弱反应；与卤代麻醉药合用增加心律失常"},{"name":"地塞米松（过敏反应辅助）","dose":"5–10 mg 静脉注射，必要时 6 h 后重复","note":"起效需 4–6 h，仅作为过敏反应的辅助用药，不能替代肾上腺素；对输血相关低血压无效。","renal":"无需调整","hepatic":"无需调整","interact":"与 NSAID 合用增加消化道出血；与降糖药合用升高血糖"},{"name":"苯海拉明（荨麻疹/瘙痒）","dose":"25–50 mg 肌注或静注，必要时 4–6 h 后重复","note":"仅缓解皮肤症状，不能预防或治疗过敏性休克；老年人慎用（谵妄、尿潴留、跌倒）。","renal":"CrCl <30 ml/min 减量或延长间隔","hepatic":"肝功能不全者减量","interact":"与中枢抑制药、抗胆碱药协同；与 MAO 抑制剂合用可致高热"},{"name":"呋塞米（TACO）","dose":"20–40 mg 静脉注射，必要时 1–2 h 后加倍；维持尿量 >1 ml/(kg·h)","note":"TACO 的核心处理是停输、坐位、限液与利尿；血压低或容量不足者不用，TRALI 禁用利尿剂。","renal":"大剂量或长期使用需按肾功能调整","hepatic":"肝硬化者注意低钾与肝性脑病","interact":"与氨基糖苷类合用增加耳毒性；与锂剂合用升高锂浓度"},{"name":"5% 碳酸氢钠（溶血反应碱化尿液）","dose":"125–250 ml 静脉滴注，目标尿 pH >7.0，根据血气调整","note":"仅在血红蛋白尿时考虑，证据有限；避免过度碱化导致低钙与代谢性碱中毒，容量负荷者慎用。","renal":"肾功能不全者慎用（钠负荷与碱中毒）","hepatic":"无","interact":"与钙剂同管路可沉淀；升高尿 pH 降低氟喹诺酮与水杨酸排泄"}],"nonDrug":["输血前核查是最高优先级：双人核对患者身份、血型、交叉配血、血袋编号与有效期，床旁反问姓名并核对腕带；核对不符一律不发、不输","急性溶血反应处置：立即停输、更换输血器、0.9% 氯化钠维持通路；水化 100–200 ml/h 维持尿量 >1 ml/(kg·h)；监测 DIC、血钾与肾功能，必要时碱化尿液或透析","TRALI：停输、氧疗（目标 SpO₂ ≥90%），必要时无创或有创机械通气（低潮气量 6 ml/kg 理想体重）；限制液体、不用利尿剂，多数 72 h 内缓解","TACO：停输、坐位、吸氧、呋塞米与限液，必要时无创通气；后续输血减慢速度并预防性利尿","特殊成分选择：辐照血（25–30 Gy）用于免疫抑制、造血干细胞移植、宫内输血与亲属供血；去白细胞制品用于反复发热性非溶血反应；洗涤红细胞用于 IgA 缺乏或严重过敏史","大量输血：按 1:1:1（红细胞:血浆:血小板）输注，监测体温、离子钙（枸橼酸中毒用 10% 葡萄糖酸钙 10 ml）、钾、pH 与凝血，预防低体温"],"life":["输血后 24 h 复查血常规评估疗效，记录输注量与 Hb/血小板反应","发生反应者写入病历与血库系统，标注相关抗体与禁忌成分，并向患者发放输血警示卡","反复输血者每 3–6 个月查铁蛋白，>1000 μg/L 考虑祛铁治疗；同时监测输血传播感染（HBV、HCV、HIV、梅毒）","输血后 1–2 周出现发热、黄疸或 Hb 再次下降需回院排查迟发溶血","择期手术患者术前 4 周评估贫血，缺铁者补铁（口服或静脉）、必要时 EPO，减少异体输血"]},"prog":"多数输血反应轻微，停药与对症处理后缓解。急性溶血性输血反应病死率 5%–10%，多与 ABO 不合的人为差错相关，早识别与积极水化可改善；TRALI 病死率 5%–25%；TACO 多可逆但延长住院；TA-GVHD 病死率 >90%，关键在辐照预防。规范核查与指征管理可避免大部分严重反应。","refs":["《临床输血技术规范》（卫医发〔2000〕184 号，卫生部）","《全血和成分血使用》（WS/T 623—2018，国家卫生健康委员会）","AABB: Red Blood Cell Transfusion — 2023 AABB International Guidelines (JAMA 2023;330:1892–1902)","AABB: Platelet Transfusion — A Clinical Practice Guideline (Annals of Internal Medicine 2015)"]}]}]},"id":{"categories":[{"id":"sepsis","name":"脓毒症与感染","rank":1,"summary":"以感染灶为起点，强调 1 h 集束化（血培养+乳酸+广谱抗菌+液体+升压药）与动态再评估；核心是把「发热/低灌注」尽快转化为可执行的病原学与器官支持方案。","compare":[{"diseaseId":"id_sepsis","dx":"确诊或疑似感染 + SOFA 评分较基线急性升高 ≥2 分（Sepsis-3），伴低血压需升压药维持 MAP ≥65 mmHg 且乳酸 >2 mmol/L 者为脓毒性休克","key":"有明确感染灶 + 器官功能急性恶化（SOFA +2）+ 乳酸升高"},{"diseaseId":"id_fuo","dx":"反复发热 ≥3 周、体温 >38.3 ℃ 至少 2 次，经 1 周以上规范门诊/住院评估仍未明确病因","key":"感染证据不足或反复培养阴性，需按感染/肿瘤/结缔组织病三类系统排查"}],"diseases":[{"id":"id_sepsis","name":"脓毒症与脓毒性休克","aka":["Sepsis","Septic shock","脓毒血症","感染性休克"],"rank":1,"basic":{"define":"脓毒症是机体对感染的反应失调导致危及生命的器官功能障碍，按 Sepsis-3 定义为感染基础上 SOFA 评分急性升高 ≥2 分；脓毒性休克是脓毒症合并严重循环、细胞代谢异常，需血管活性药维持 MAP ≥65 mmHg 且血乳酸 >2 mmol/L。","risk":["高龄（>65 岁）、婴幼儿与免疫抑制人群","糖尿病、肝硬化、慢性肾病、恶性肿瘤化疗后","长期激素/免疫抑制剂、广谱抗菌药暴露、侵入性导管与机械通气","近期手术、创伤、烧伤、胆道或泌尿道梗阻","肺炎、腹腔感染、尿路感染、皮肤软组织感染与导管相关血流感染是最常见来源"],"epi":"全球每年脓毒症发病约 4900 万例、相关死亡约 1100 万例；我国 ICU 脓毒症患病率约 20%，脓毒性休克院内病死率仍达 30%–40%。"},"patho":"病原体相关分子模式（PAMP）激活固有免疫，释放 TNF-α、IL-1、IL-6 等细胞因子，引起内皮糖萼脱落、毛细血管渗漏与微血栓形成；血管扩张与心肌抑制导致分布性休克，线粒体功能障碍与微循环分流造成组织氧利用障碍，乳酸升高。后期转为免疫麻痹与持续炎症-免疫抑制-分解代谢综合征（PICS）。","dx":{"criteria":["感染（确诊或疑似）+ SOFA 评分较基线急性升高 ≥2 分即诊断脓毒症（qSOFA ≥2 仅作床旁筛查预警，不能替代 SOFA）","脓毒性休克：充分液体复苏后仍需升压药维持 MAP ≥65 mmHg，且血乳酸 >2 mmol/L（排除低血容量等其他原因）","尽快（1 h 内）留取血培养至少 2 套（需氧+厌氧）及感染灶培养，抗菌药不应因取培养延迟超过 45 min","乳酸 ≥2 mmol/L 视为组织低灌注；乳酸 >4 mmol/L 提示高风险，需立即复苏","降钙素原可辅助判断细菌感染与疗程，但不得单独用于诊断或停药决定"],"workup":["血常规、CRP、PCT、血气（乳酸、BE、PaO2/FiO2）、凝血（DIC 筛查）、肝功能、肾功能、电解质、血糖","血培养双侧双套 + 痰/尿/腹腔引流液/脑脊液/伤口分泌物培养，必要时送 mNGS","影像学定位：胸部 CT、腹部超声/CT、超声心动图（评估容量与心功能）","床旁超声评估下腔静脉与肺部 B 线，指导液体反应性判断","每 2–4 h 复查乳酸直至下降；动态 SOFA 评估器官功能","免疫状态评估：淋巴细胞亚群、免疫球蛋白（反复重症或机会性感染时）"],"grading":"按感染部位与来源分类（肺源性、腹腔源性、泌尿源性、导管相关、皮肤软组织、中枢神经）；按器官受累采用 SOFA 0–24 分，评分越高病死率越高；按乳酸分层：<2 低风险、2–4 中风险、>4 mmol/L 高风险。"},"ddx":[{"name":"发热待查（id_fuo）","point":"与本类 id_fuo 的鉴别点：脓毒症有明确或高度疑似感染灶，SOFA 急性升高、乳酸升高、对液体与抗菌药快速反应；发热待查为长期反复发热且感染证据不足，器官功能相对稳定，需系统排查肿瘤与结缔组织病。"},{"name":"心源性休克","point":"血压低但肢端湿冷、颈静脉压升高、BNP 明显升高、床旁超声示 LVEF 下降或节段运动异常，肺部啰音与 B 线增多，通常无高热与感染灶。"},{"name":"低血容量性休克（失血/脱水）","point":"有失血、呕吐腹泻或第三间隙丢失病史，下腔静脉塌陷、对快速补液反应良好，血红蛋白或血细胞比容下降，乳酸纠正后不再反弹。"},{"name":"肾上腺危象","point":"难治性低血压伴低钠高钾、嗜酸性粒细胞增多，对升压药与补液反应差，血皮质醇 <500 nmol/L 或 ACTH 兴奋试验无反应，补氢化可的松后迅速改善。"},{"name":"急性肺栓塞","point":"突发呼吸困难与低氧、D-二聚体升高、右心负荷超声征象，乳酸可轻中度升高但少有高热，CTPA 可确诊。"}],"tx":{"drug":[{"name":"去甲肾上腺素","dose":"起始 0.05 μg/kg/min 泵入，按 MAP 65 mmHg 目标上调，常用 0.05–0.5 μg/kg/min；必要时加血管加压素 0.03 U/min","note":"脓毒性休克一线升压药，首选中心静脉输注；液体复苏 30 mL/kg 晶体后仍低血压即启动，不延迟","renal":"无需调整剂量，但少尿期需警惕容量过负荷；CRRT 不显著清除","hepatic":"重度肝功能障碍时清除下降，从最低剂量起并逐步滴定","interact":"与单胺氧化酶抑制剂、三环类抗抑郁药合用显著增强升压反应；外渗可致皮肤坏死，需酚妥拉明局部浸润"},{"name":"美罗培南","dose":"1 g q8h 静脉滴注（30 min–3 h）；重症或耐药风险高者 2 g q8h；延长输注 3 h 可提高达标率","note":"覆盖革兰阴性菌与厌氧菌的广谱碳青霉烯，经验性用于腹腔感染、医院获得性肺炎与脓毒症来源不明；确认病原后 24–48 h 降阶梯","renal":"CrCl >50 常规 1 g q8h；CrCl 26–50：1 g q12h；CrCl 10–25：0.5 g q12h；CrCl <10：0.5 g q24h；血液透析 0.5 g q24h（透析后追加）；CRRT：1 g q8h 或 0.5 g q8h 延长输注","hepatic":"轻中度无需调整；重度肝功能不全慎用并监测","interact":"丙戊酸血药浓度显著下降、可能诱发癫痫发作，禁用联用；与丙磺舒合用升高血药浓度"},{"name":"哌拉西林他唑巴坦","dose":"4.5 g q6h 静脉滴注（输注 3–4 h），重症可 4.5 g q6h 延长输注","note":"覆盖铜绿假单胞菌与厌氧菌，经验性治疗腹腔、肺部与中性粒细胞缺乏伴发热；需注意青霉素过敏史","renal":"CrCl >40：4.5 g q6h；CrCl 20–40：3.375 g q6h；CrCl <20（未透析）：2.25 g q6h；血液透析后追加 2.25 g；CRRT：4.5 g q8h 延长输注","hepatic":"无需调整","interact":"与万古霉素联用增加急性肾损伤风险，需监测肌酐；与甲氨蝶呤合用降低其清除，慎用"},{"name":"万古霉素","dose":"15–20 mg/kg q8–12h 静脉滴注（单次不超过 2 g），按 AUC/MIC 400–600 或谷浓度 15–20 mg/L 调整","note":"疑似 MRSA 或导管相关血流感染时经验性加用；须负荷 25–30 mg/kg","renal":"CrCl 50–90：15–20 mg/kg q12h；CrCl 20–49：15–20 mg/kg q24h；CrCl <20：负荷后按血药浓度延长间隔；CRRT：1 g q24h 或按浓度调整并监测谷浓度 10–15 mg/L","hepatic":"轻度无需调整，重度合并腹水时监测浓度","interact":"与氨基糖苷类、两性霉素 B、哌拉西林他唑巴坦合用增加肾毒性；与强效利尿剂合用注意耳毒性"},{"name":"氢化可的松","dose":"200 mg/d 静脉，持续泵入或 50 mg q6h，共 5–7 天","note":"用于液体与升压药仍不能维持 MAP ≥65 mmHg 的脓毒性休克，不用 ACTH 试验筛选","renal":"无需调整，注意水钠潴留与高血糖","hepatic":"重度肝功能不全需减量并延长给药间隔","interact":"与氟喹诺酮合用增加肌腱断裂风险；可降低抗糖尿病药疗效"},{"name":"平衡晶体液（复方电解质）","dose":"初始 30 mL/kg 于 3 h 内静滴，之后按灌注指标、毛细血管渗漏与心功能每次 250–500 mL 复测","note":"首选平衡盐液体，避免大量生理盐水导致高氯性酸中毒；白蛋白可用于肝硬化或需大量液体者","renal":"少尿/无尿者按容量与心功能严格限速，必要时 CRRT 同时管理容量","hepatic":"肝硬化者补充白蛋白","interact":"含钙平衡液与头孢曲松禁同一通路（沉淀）"}],"nonDrug":["1 h 集束化：测乳酸、取血培养、广谱抗菌药、低血压者 30 mL/kg 晶体、低血压持续即用升压药","感染源控制：脓肿引流、胆道减压（ERCP/PTBD）、坏死组织清创、拔除感染导管，原则上 6–12 h 内完成","器官支持：肺保护性通气（潮气量 6 mL/kg 理想体重、平台压 ≤30 cmH2O）、限制性输血（Hb <70 g/L）、CRRT（合并 AKI 或容量过负荷）","无创/有创血流动力学监测：动脉置管、CVP/PI/床旁超声评估容量反应性，避免被动抬腿试验假阳性","血糖控制 7.8–10.0 mmol/L；DVT 与应激性溃疡预防（有指征者）","免疫调节：胸腺肽 α1、rFVIIa 等仅限研究/特定场景，不常规推荐"],"life":["出院前评估去残留感染灶与抗菌疗程，疗程一般 7–10 天，取决于感染源控制与临床反应","感染灶已控制+临床稳定者可缩短疗程（如部分腹腔感染 4–5 天）并动态复查 PCT","康复期关注 ICU 后综合征（肌无力、认知障碍、PTSD），转康复与心理支持","控制糖尿病、慢性肝病、肾功能不全等基础病；避免侵入性导管置放时间过长"]},"prog":"住院病死率 25%–40%，脓毒性休克可达 30%–50%；存活者中约 1/3 遗留器官功能障碍或 ICU 后综合征。早期识别、1 h 内抗菌药与足量液体复苏、及时感染源控制显著改善预后。","refs":["拯救脓毒症运动（SSC）国际指南 2021","中国脓毒症/脓毒性休克急诊治疗指南 2018","中国脓毒症早期预防与阻断急诊专家共识 2020","Surviving Sepsis Campaign 2021（抗感染与血流动力学部分）"]},{"id":"id_fuo","name":"发热待查（不明原因发热 FUO）","aka":["FUO","Fever of Unknown Origin","不明原因发热"],"rank":2,"basic":{"define":"经典定义：反复发热 ≥3 周、体温 >38.3 ℃ 至少 2 次，经 ≥1 周规范住院评估（或 3 次门诊就诊）仍不能明确病因。按人群与情境分为经典型、医疗相关型、免疫缺陷型与旅行/地方性型四类。","risk":["免疫抑制：长期激素/免疫抑制剂、化疗、器官移植、HIV","近期出国旅行或接触动物、蜱虫、食用生肉/生奶","泌尿、胆道、腹膜/血管内装置等植入物","血液系统恶性肿瘤、实体瘤、淋巴瘤家族史","系统性自身免疫病（SLE、Still 病、血管炎）"],"epi":"经典型 FUO 病因构成大致为感染 35%–48%、结缔组织病（自身免疫病）15%–25%、肿瘤 10%–20%、原因不明 10%–20%；我国以感染与结核、淋巴瘤、成人 Still 病较常见，且随影像与分子诊断普及「不明原因」比例下降。"},"patho":"发热由外源性致热原（病原体、肿瘤坏死物）与内源性致热原（IL-1、IL-6、TNF-α、IFN-γ）作用于下丘脑体温调节中枢，使前列腺素 E2 合成增加而调定点上移。感染性以持续炎症因子释放为主，肿瘤性以坏死与肿瘤相关细胞因子为主，自身免疫病由免疫复合物与补体激活驱动；结构性病变（隐匿性脓肿、血管内感染）常表现为反复间歇热。","dx":{"criteria":["确认发热真实且持续：间隔 ≥1 天两次体温 >38.3 ℃，或 >38.0 ℃ 持续 ≥3 周；排除精神性发热与假热（可同时测直肠/口腔温，观察是否有症状与体温不符）","回顾 3 周全科用药史，排除药物热（发热伴皮疹、嗜酸性粒细胞升高、停药 72 h 内退热）","按「感染 → 结缔组织病 → 肿瘤 → 其他」顺序分步排查，避免无方向广谱扫查","重点定位：口腔鼻窦、牙、心脏瓣膜、腹腔/腹膜后、泌尿生殖道、植入物、骨髓","初始评估阴性者：腹部/盆腔 CT + PET-CT 定位隐匿灶；必要时骨髓穿刺与活检、肝/淋巴结活检","持续发热 >2 周、WBC/CRP/PCT 正常、自身抗体阳性者重点考虑自身免疫病，可经验性激素试验治疗"],"workup":["血常规+外周血涂片（异常淋巴细胞、破碎红细胞、异型淋巴细胞）","CRP、PCT、ESR、铁蛋白（>1000 μg/L 提示 Still 病/HLH/感染）","三套血培养（不同部位、不同时间）+ 痰/尿/脑脊液培养 + 尿常规","结核检查：IGRA、T-SPOT、胸片/胸部 CT；必要时淋巴结/骨髓活检抗酸染色与组织培养","病毒学：EBV、CMV、HIV、HBV/HCV、登革/布病、Q 热（按流行区）","免疫学：ANA、抗 dsDNA、补体、ANCA、类风湿因子、免疫球蛋白；IgG4","肿瘤：LDH、β2 微球蛋白、肿瘤标志物、PET-CT；持续异常或不明时骨髓穿刺","影像：胸腹盆 CT、超声心动图（人工瓣膜/心内膜炎）、下腔静脉/门静脉超声、MRI","新技术：mNGS（血液/病灶标本）、病原宏基因组与靶向 PCR，用于免疫抑制与反复培养阴性者"],"grading":"按情境分 4 类：经典型 FUO、医疗相关型（入院 ≥48 h 或装置/手术相关）、免疫缺陷型（中性粒细胞 <500/μL 或 CD4 <200/μL）、旅行相关型。<br>按病因归因分感染性、肿瘤性、结缔组织性、其他（药物热、内分泌、血栓栓塞）。"},"ddx":[{"name":"脓毒症与脓毒性休克（id_sepsis）","point":"与本类 id_sepsis 的鉴别点：脓毒症在感染灶 + 器官功能急性恶化（SOFA ≥2）基础上进展快、乳酸升高、抗菌药后迅速好转；FUO 病程长、器官功能多稳定、常规培养反复阴性。"},{"name":"药物热","point":"发热多出现在用药 7–10 天后，伴皮疹、嗜酸性粒细胞增多或肝损，患者一般情况好，停用可疑药后 48–72 h 退热。"},{"name":"成人 Still 病","point":"弛张热、一过性皮疹、关节痛三联征，铁蛋白显著升高（常 >1000 μg/L）、糖化铁蛋白下降，ANA/RF 阴性。"},{"name":"淋巴瘤（尤其霍奇金/侵袭性淋巴瘤）","point":"B 症状（盗汗、体重下降）、LDH 升高、淋巴结或脾大，PET-CT 与淋巴结/骨髓活检确诊。"},{"name":"亚急性感染性心内膜炎","point":"原有瓣膜病或人工瓣膜，新发杂音、脾大、杵状指、血培养间歇阳性，超声心动图见赘生物。"},{"name":"巨噬细胞活化综合征/HLH","point":"持续高热、血细胞两系以上减少、脾大、铁蛋白极高、甘油三酯升高、纤维蛋白原降低、骨髓见噬血现象。"}],"tx":{"drug":[{"name":"诊断性抗菌治疗（经验性）","dose":"无明确感染灶者不常规启动；高度怀疑细菌感染时可试用哌拉西林他唑巴坦 4.5 g q6–8h 或头孢曲松 2 g qd，观察 72 h 疗效","note":"原则：先取证、后治疗；盲目广谱抗菌药会掩盖病原并增加耐药，需在 72 h 内评估是否调整","renal":"哌拉西林他唑巴坦 CrCl >40 4.5 g q6h、20–40 3.375 g q6h、<20 2.25 g q6h；头孢曲松肾功能不全无需调整（同时有肝肾功能不全时慎用、监测）","hepatic":"头孢曲松在胆道淤积时致沉淀风险；哌拉西林他唑巴坦无需调整","interact":"头孢曲松与含钙输液同通路可沉淀；与华法林合用增强抗凝"},{"name":"抗结核经验治疗","dose":"高度怀疑播散性结核且活检证实困难时，按 2HRZE：异烟肼 5 mg/kg（300 mg qd）、利福平 10 mg/kg（450–600 mg qd）、吡嗪酰胺 25 mg/kg、乙胺丁醇 15 mg/kg","note":"仅在临床/影像/病理高度怀疑且获取证据失败时启动，启动后 2–4 周评估","renal":"异烟肼无需调整；利福平无需调整；吡嗪酰胺 CrCl <30 延长至 q24h 或 25–35 mg/kg tiw；乙胺丁醇 CrCl 10–50 延长至 q24–36h，<10 减为 15 mg/kg tiw","hepatic":"转氨酶 >3 倍正常上限或黄疸时停用肝毒性药物并评估","interact":"利福平强诱导 CYP3A4，显著降低口服避孕药、华法林、他汀、抗病毒药浓度"},{"name":"糖皮质激素（自身免疫病试验性治疗）","dose":"泼尼松 0.5–1 mg/kg/d（最大 60 mg/d）口服，或甲泼尼龙 40–80 mg/d 静脉；2–4 周后逐渐减量","note":"仅在感染证据充分排除、临床特征符合自身免疫病时试验性使用；同时严密监测感染再燃","renal":"无需调整","hepatic":"重度肝功能不全作用增强，需减量","interact":"与非甾体抗炎药合用增加消化道出血；与利福平合用激素暴露明显下降"},{"name":"对乙酰氨基酚（对症）","dose":"0.5 g q6h 口服，24 h 不超过 2 g（肝病或营养不良者 ≤1.5 g/d）","note":"仅用于退热缓解；不推荐常规联合非甾体抗炎药试验鉴别肿瘤热","renal":"CrCl <30 延长间隔至 q8h，并降低每日总量","hepatic":"活动性肝病、酒精性肝病慎用或禁用；总累积量注意","interact":"与华法林长期合用可升高 INR；与异烟肼、利福平合用增加肝毒性"}],"nonDrug":["建立系统化 FUO 排查路径表，逐项记录，避免重复检查与「撒网式」治疗","PET-CT 用于常规影像阴性、炎症指标持续升高者，可提高隐匿灶发现率","骨髓穿刺与活检适用于血细胞异常、铁蛋白显著升高或疑似血液肿瘤者","淋巴结、皮肤、肝活检（含培养与病理）对病因确定价值高","药物热排查：停用非必要药物，按时间轴记录体温变化","免疫抑制者评估 CMV、PCP、弓形虫、真菌与淋巴瘤，必要时 mNGS"],"life":["体温与用药日记，随访第 2、4、8 周复评，动态调整诊断假设","避免长期激素/广谱抗菌药叠加，防止掩盖病灶与继发真菌感染","退热后复查 CRP、铁蛋白、影像评估病灶变化","不明原因但病情稳定者，可考虑观察随访策略，每 3 个月门诊评估"]},"prog":"大多数 FUO 患者可在 6 个月内获得诊断，其中感染与自身免疫病预后较好；隐匿肿瘤或血液系统病变者预后取决于分期与早期治疗。约 10%–20% 最终仍不能明确病因，多数为自限性。","refs":["中国发热待查诊治专家共识 2017","不明原因发热诊断与治疗专家共识（2023 更新）","Harrison's Principles of Internal Medicine 21st ed., Fever of Unknown Origin"]}]},{"id":"viral_resistant","name":"病毒与耐药菌","rank":2,"summary":"以「疗程+病原分层」为核心：慢性乙肝长期抑制病毒并监测肾/骨安全；流感与新冠把握 48 h 抗病毒窗口；结核按 2HRZE/4HR 全程管理；碳青霉烯耐药菌按耐药表型选择联合方案并强调感控。","compare":[{"diseaseId":"id_hbv","dx":"HBsAg 阳性 >6 个月 + HBV DNA 高于阈值 + ALT 升高或肝纤维化证据；需按年龄与家族史评估启动抗病毒","key":"HBsAg 持续 >6 个月；一线药恩替卡韦/替诺福韦类，长期口服不可随意停药"},{"diseaseId":"id_flu","dx":"流感样症状 + 抗原/核酸阳性；重症或高危人群 48 h 内启动奥司他韦/巴洛沙韦","key":"发病 48 h 内用药最有效；重症与孕妇不论时间窗均用药"},{"diseaseId":"id_tb","dx":"抗酸染色/培养或 GeneXpert 阳性，或临床+影像+IGRA 支持；敏感性结核 2HRZE/4HR","key":"病原学为王；强化期 2 个月四药，巩固期 4 个月 HR；耐多药需全部换方案"},{"diseaseId":"id_crab","dx":"对亚胺培南/美罗培南耐药（MIC ≥4 mg/L）的肠杆菌目细菌感染，常见于 ICU、长住院与侵入装置患者","key":"按耐药机制选药：产 KPC 首选头孢他啶阿维巴坦，产 NDM 选多黏菌素/依托环素类联合；同时严格接触隔离"}],"diseases":[{"id":"id_hbv","name":"慢性乙型肝炎","aka":["CHB","Chronic Hepatitis B","慢乙肝"],"rank":1,"basic":{"define":"乙肝病毒（HBV）感染超过 6 个月，血清 HBsAg 阳性，可伴 HBV DNA 阳性、ALT 异常或肝组织学改变；按 HBeAg 状态与病毒复制分为 HBeAg 阳性/阴性慢性肝炎、非活动性携带与再激活等阶段。","risk":["母婴传播（我国最主要的传播途径）","不安全注射、输血史、血液透析、纹身与医美操作","多个性伴侣、男男性行为","家族史：父母或兄弟姐妹有肝硬化/肝癌","合并 HCV、HDV、HIV 感染、脂肪肝与酒精滥用","免疫抑制治疗（化疗、生物制剂、激素）诱发再激活"],"epi":"我国一般人群 HBsAg 携带率约 5.9%（约 7500 万人），慢性乙肝患者约 2000–3000 万；乙型肝炎相关肝硬化与肝癌每年新增肝癌病例占全球约 40% 以上。"},"patho":"HBV 经肝细胞 NTCP 受体进入细胞，以共价闭合环状 DNA（cccDNA）形式在核内长期存在，是难以根治的根源；病毒特异性 CD8⁺ T 细胞应答不足导致持续感染，免疫介导的肝细胞损伤引起反复炎症与纤维化，逐步进展为肝硬化和肝细胞癌（HBV DNA 整合入宿主基因组为致癌机制之一）。","dx":{"criteria":["HBsAg 阳性 ≥6 个月，或曾检出 HBV DNA 并有相关病史","需评估「三项」：HBV DNA 定量、ALT、肝纤维化/肝硬化程度","启动抗病毒指征（符合任一）：HBV DNA >2000 IU/mL 且 ALT >正常上限；或肝组织学 G≥2/S≥2；或已有肝硬化（代偿或失代偿）伴可检出 HBV DNA；或 HBV DNA >20000 IU/mL 且 ALT >正常上限 2 倍","特殊人群：年龄 >30 岁且 HBV DNA 阳性（无论 ALT）可考虑启动；肝硬化、肝癌家族史、接受免疫抑制治疗者放宽指征","ALT 正常上限推荐男性 30 U/L、女性 19 U/L（2022 版中国指南）","排除其他原因：HCV、HDV、HIV、酒精、药物、脂肪肝、自身免疫性肝病"],"workup":["肝功能全套、HBV DNA 定量（实时荧光 PCR，IU/mL）","乙肝血清学五项：HBsAg、抗-HBs、HBeAg、抗-HBe、抗-HBc；必要时抗-HBc IgM、HBV 基因型与耐药位点","肝脏影像：腹部超声（每年）、必要时肝脏弹性（FibroScan）评估纤维化分期","肝硬化者：胃镜评估食管胃底静脉曲张、AFP + 超声每 6 个月监测肝癌","基线肾功能与尿常规、血磷、eGFR（决定是否选 TDF/TAF）","HBV 再激活风险分层：接受抗 CD20 单抗、造血干细胞移植者需预防性抗病毒","家庭成员的乙肝筛查与疫苗接种"],"grading":"临床分期：① HBeAg 阳性慢性 HBV 感染（免疫耐受期，DNA 高、ALT 正常）；② HBeAg 阳性慢性乙型肝炎；③ HBeAg 阴性慢性 HBV 感染（非活动携带）；④ HBeAg 阴性慢性乙型肝炎；⑤ 肝硬化（代偿/失代偿）；⑥ 肝癌。肝组织炎症分级 G0–G4、纤维化分期 S0–S4。"},"ddx":[{"name":"流感与新冠（id_flu）","point":"与本类 id_flu 的鉴别点：流感/新冠为急性呼吸道感染，发热、肌痛、呼吸道症状突出，病程 1–2 周，HBsAg 阴性；慢乙肝多无症状或以乏力、腹胀、转氨酶持续异常起病，HBV DNA 阳性。"},{"name":"丙型病毒性肝炎","point":"抗-HCV 阳性、HCV RNA 阳性而 HBsAg 阴性；可经 DAA 方案 12 周治愈；合并 HBV 者需注意 DAA 相关 HBV 再激活。"},{"name":"脂肪性肝病（MASLD/MAFLD）","point":"B 超/CT 见弥漫性脂肪浸润，常伴肥胖、糖尿病、血脂异常，HBV DNA 阴性或低复制，ALT 轻中度升高，减重后改善。"},{"name":"自身免疫性肝炎","point":"女性为主，IgG 升高、ANA/抗平滑肌抗体阳性、界面性肝炎伴浆细胞浸润，对激素应答良好，病毒标志物阴性。"},{"name":"药物性肝损伤","point":"有明确用药史（抗结核药、中药、抗真菌药），停药后 ALT 改善，无肝病史时 R 值及型别（肝细胞型/胆汁淤积型）可助判读。"}],"tx":{"drug":[{"name":"恩替卡韦","dose":"0.5 mg qd 口服空腹（餐前或餐后 2 h）；失代偿期肝硬化、拉米夫定耐药者 1 mg qd","note":"一线核苷类高效低耐药；初治者 5 年耐药率约 1.2%；长期治疗需监测病毒学应答","renal":"CrCl ≥50：0.5 mg qd；CrCl 30–49：0.25 mg qd；CrCl 10–29：0.15 mg qd；CrCl <10 或血液透析：0.05 mg qd（按说明书；无 0.05 mg 规格时可间隔给药并请专科会诊）","hepatic":"失代偿期肝硬化剂量应加倍至 1 mg qd（遵说明书）","interact":"与阿德福韦/替诺福韦联合时谨防叠加肾毒性；与影响肾小管分泌药物（丙磺舒）合用可升高浓度"},{"name":"替诺福韦二吡呋酯（TDF）","dose":"300 mg qd 口服，可与食物同服；HBeAg 阳性者疗程 >4 年直至 HBeAg 血清学转换","note":"一线药物，妊娠期可用；长期使用注意肾小管与骨密度影响","renal":"CrCl 30–49：300 mg q48h；CrCl 10–29：300 mg q72–96h；CrCl <10 未透析：遵说明书；血液透析：透析后给药 300 mg q7d（遵说明书）","hepatic":"轻度无需调整；失代偿期肝硬化首选恩替卡韦或 TAF","interact":"与 NSAIDs、氨基糖苷类、两性霉素 B 等肾毒性药合用增加肾损害；可升高去羟肌苷浓度"},{"name":"富马酸丙酚替诺福韦（TAF）","dose":"25 mg qd 随餐口服","note":"骨肾安全性优于 TDF，适用于 ≥12 岁（体重 ≥35 kg）及 eGFR 15–29 者；妊娠期数据有限","renal":"CrCl ≥15 无需调整；CrCl <15 或透析患者不推荐使用（数据不足）","hepatic":"重度肝功能不全（Child-Pugh C）不推荐；失代偿期肝硬化慎用"},{"name":"聚乙二醇干扰素 α","dose":"聚乙二醇干扰素 α-2a 180 μg 皮下注射 qw（或 α-2b 1.5 μg/kg qw），疗程 48–96 周","note":"可选用于追求临床治愈（HBsAg 清除）的优势人群：年轻、HBeAg 阳性、HBV DNA <2×10⁸ IU/mL、ALT 升高；失代偿期肝硬化禁用","renal":"CrCl 30–49 减至 135 μg qw；CrCl 10–29 减至 90 μg qw；血液透析 90 μg qw","hepatic":"失代偿期肝硬化、自身免疫性肝炎禁用；治疗中监测 ALT","interact":"与利巴韦林合用可加重贫血；避免与骨髓抑制药物同用"}],"nonDrug":["肝硬化管理与肝癌监测：AFP + 超声每 6 个月；胃镜每 1–2 年评估静脉曲张","肝移植评估：失代偿期肝硬化、MELD 升高或小肝癌符合标准","新生儿 HBV 疫苗 + 乙肝免疫球蛋白阻断，HBsAg 阳性母亲孕期高病毒载量者妊娠 24–28 周启动 TDF","抗病毒治疗不应在没有停药指征时随意中断，停药需严密监测（停药后前 3 个月每月查肝功和 HBV DNA）"],"life":["戒酒，控制体重与代谢综合征，避免滥用中草药与保健品","治疗中每 3–6 个月复查 ALT、HBV DNA、AFP 和超声；使用 TDF 者监测肌酐、尿 β2-微球蛋白与血磷","家庭成员筛查、接种疫苗；避免不安全性行为与共用注射器","糖尿病或脂肪肝者控制血糖血脂，降低肝硬化与肝癌风险"]},"prog":"未经治疗者 5 年肝硬化发生率约 8%–20%，代偿期肝硬化 5 年进展为失代偿约 20%；规范抗病毒可显著减少肝硬化与肝癌，长期恩替卡韦/替诺福韦可使肝细胞癌风险下降约 50%–60%。HBsAg 自发清除率每年约 1%，抗病毒治疗后临床治愈率仍较低。","refs":["慢性乙型肝炎防治指南（2022 年版，中华医学会肝病学分会、感染病学分会）","EASL Clinical Practice Guidelines on Hepatitis B 2017","AASLD Guidance on Chronic Hepatitis B 2018"]},{"id":"id_flu","name":"流行性感冒与新型冠状病毒感染","aka":["Influenza","流感","COVID-19","新冠感染","SARS-CoV-2"],"rank":2,"basic":{"define":"流感由甲/乙型流感病毒经呼吸道传播，冬春季高发，表现为突发高热、肌痛、乏力与咳嗽，重症可并发病毒性肺炎与 ARDS；新冠感染由 SARS-CoV-2 引起，临床谱从无症状、上呼吸道感染到重症肺炎、血栓与多器官受累。","risk":["≥65 岁老年人、婴幼儿（<5 岁）、孕妇","慢性心肺疾病（哮喘、COPD）、糖尿病、肥胖（BMI ≥30）","免疫抑制、肿瘤、慢性肾病、肝硬化","未接种疫苗或接种史不足","聚集人群（学校、养老机构、医院）"],"epi":"流感每年冬春季流行，我国北方冬春季、南方冬夏双峰，年感染率可致 5%–10% 成人发病；新冠在 2022 年后转为季节性流行，老年人与免疫抑制者仍存在重症与死亡风险。"},"patho":"病毒血凝素（HA）结合呼吸道上皮细胞唾液酸受体侵入，RNA 聚合酶复制致细胞破坏与上皮屏障丧失；重症者过度释放 IL-6、IFN-γ 引起细胞因子风暴、肺泡-毛细血管屏障破坏与 ARDS，凝血激活致微血栓与静脉血栓栓塞；新冠可通过 ACE2 受体侵入多器官（内皮、心肌、肾、神经系统），并引起免疫失调（淋巴细胞减少、T 细胞耗竭）。","dx":{"criteria":["流感：流行季节突发高热（≥38 ℃）+ 肌痛/乏力/头痛 + 呼吸道症状，抗原检测（15 min）或者核酸检测（RT-PCR）阳性；重症或抗原阴性但临床高度怀疑者做核酸检测","新冠：SARS-CoV-2 核酸检测或抗原检测阳性，结合临床症状与影像","重症标准（任一）：呼吸频率 ≥30 次/min；静息 SpO2 ≤93%（或 PaO2/FiO2 <300）；需要机械通气；休克；合并其他器官衰竭","高危因素评估决定是否早期抗病毒：年龄、基础病、免疫状态、妊娠","血常规+淋巴细胞绝对值、CRP、D-二聚体、胸片/CT 评估病毒性肺炎"],"workup":["甲型/乙型流感病毒核酸检测或抗原（鼻咽拭子/口咽拭子）；新冠核酸/抗原","呼吸道多重病原体 PCR（RSV、腺病毒、支原体、肺炎链球菌）用于鉴别与合并感染","血常规、生化、CRP、PCT、血气分析、D-二聚体、凝血","胸部 CT：新冠肺炎表现为磨玻璃/斑片影，外周分布；细菌性肺炎为支气管肺炎实变","重症者查心肌酶、BNP、肝肾功能、铁蛋白","孕产妇、免疫抑制者查病毒载量与细胞免疫"],"grading":"流感：轻症、重症（肺炎/ARDS）、危重症（多器官衰竭）；新冠：轻型（上呼吸道症状，无肺炎）、中型（有肺炎，SpO2 ≥93%）、重型（任一重症标准）、危重型（需要机械通气或 ECMO、休克）。"},"ddx":[{"name":"慢性乙型肝炎（id_hbv）","point":"与本类 id_hbv 的鉴别点：慢乙肝急性发作可有乏力、食欲减退与转氨酶升高，但无流行季聚集史、呼吸道症状不明显，HBV 标志物阳性；流感/新冠以高热、呼吸道症状为主，ALT 多为轻度升高。"},{"name":"细菌性肺炎","point":"起病稍缓、咳脓痰、白细胞与中性粒细胞升高、PCT 明显升高，影像为叶段实变；病毒性肺炎以间质改变为主，PCT 常正常。"},{"name":"肺炎支原体肺炎","point":"多见于青少年与学龄儿童，干咳突出、咽痛、头痛，肺部体征轻而影像重（磨玻璃/网织状），大环内酯或四环素类治疗有效。"},{"name":"肺结核（id_tb）","point":"病程 >2 周、低热盗汗、消瘦，影像见上叶尖后段或下叶背段空洞、树芽征；IGRA/抗酸染色/培养阳性；抗病毒无效。"},{"name":"急性病毒性心肌炎","point":"感冒样症状后出现胸闷、心悸、肌钙蛋白与 CK-MB 升高、心电图 ST-T 改变，超声示室壁运动异常；流感/新冠重症并发症需鉴别"}],"tx":{"drug":[{"name":"奥司他韦","dose":"成人 75 mg bid 口服，疗程 5 天；重症/住院可延长至 10 天或至临床改善；预防剂量 75 mg qd ×7–10 天","note":"发病 48 h 内用药最有效；重症、孕妇、高危人群不论时间窗均应立即启用；肾功能不全按说明书调整","renal":"CrCl >60：75 mg bid；CrCl 30–60：30 mg bid；CrCl 10–30：30 mg qd；血液透析：30 mg 每次透析后立即给药；腹膜透析：30 mg qw","hepatic":"轻中度无需调整；重度肝功能不全慎用","interact":"与减毒活流感疫苗同时使用时抗病毒药可能抑制疫苗反应（服药 48 h 内不应接种减毒疫苗）"},{"name":"巴洛沙韦","dose":"成人单次口服 40 mg（体重 <80 kg）或 80 mg（≥80 kg），一次完成疗程","note":"单剂口服、依从性好，适用于 5 岁以上流感；不推荐严重肾或肝功能不全者；无免疫功能低下者的充分数据","renal":"CrCl 50–80：单次 40 mg；CrCl <50：单次 20 mg（遵说明书）；血液透析不推荐","hepatic":"重度肝功能不全不推荐","interact":"与含多价阳离子药物（抗酸剂、铁剂、钙剂、乳制品）需间隔 ≥2 h 服用；可降低口服激素类避孕药暴露"},{"name":"奈玛特韦/利托那韦（Paxlovid）","dose":"奈玛特韦 300 mg + 利托那韦 100 mg 每 12 h 口服，疗程 5 天；eGFR 30–60：奈玛特韦 150 mg + 利托那韦 100 mg bid","note":"用于新冠重症高危成人（≥65 岁或有基础病、免疫抑制）发病 ≤5 天内；eGFR <30 不推荐","renal":"CrCl 30–59：150/100 mg bid；CrCl <30 不推荐","hepatic":"Child-Pugh C 禁用；Child-Pugh B 个体化评估","interact":"强 CYP3A 抑制剂，禁与他汀类（辛伐他汀、洛伐他汀）、胺碘酮、伊伐布雷定、多重 CYP3A 底物联用；与华法林、Tacrolimus 合用需监测"},{"name":"对乙酰氨基酚（退热）","dose":"0.5 g 口服必要时 q6h，24 h 不超过 2 g","note":"退热缓解症状；避免与复方感冒药重复用同一成分","renal":"CrCl <30 延长间隔至 q8h","hepatic":"肝功能异常者每日 ≤1.5 g 或避免使用","interact":"与华法林、异烟肼、利福平合用增加肝毒性或升高 INR"},{"name":"地塞米松（重症新冠）","dose":"6 mg qd 口服或静脉，10 天","note":"仅用于需氧（氧疗/机械通气）的新冠重症患者；非重症不需氧者不推荐","renal":"无需调整","hepatic":"无需调整，注意高血糖与继发感染","interact":"与 NSAIDs 合用增加消化道出血；降低抗糖尿病药疗效"}],"nonDrug":["重症流感：O2 支持使 SpO2 ≥92%–95%，ARDS 按肺保护性通气（潮气量 6 mL/kg 理想体重、平台压 <30 cmH2O），必要时俯卧位；V-V ECMO 用于难治性低氧","新冠重症：氧疗、俯卧位、HFNC/无创通气，血栓风险高者按 D-二聚体分层预防或治疗性抗凝","孕妇、免疫抑制者的抗病毒治疗不应因时间窗延迟","流感疫苗每年接种；新冠疫苗按国家免疫规划加强；医务与老年人群中红区接种","严格手卫生与呼吸道隔离，流感患者体温正常 24 h 后可复课/复工"],"life":["退热后 24–48 h 避免剧烈运动，流感后 2 周内警惕心肌炎","充分补液、休息、营养支持；咳喘加重或 SpO2 下降超过 3% 立即就诊","老年人与慢性病患者随访 2–4 周评估心肺功能","隔离期至核酸检测阴性或症状缓解后（按当地疾控指南）；密切接触者观察 7–10 天"]},"prog":"季节性流感病死率约 0.1%–0.5%，高危老年人与孕妇可明显升高；重症新冠病死率 3%–10%（未接种疫苗者更高），已接种疫苗且及时抗病毒者可降至 <1%。重症肺炎后遗留肺纤维化与心肺功能下降者约 20%–30%。","refs":["流行性感冒诊疗方案（2020 年版，国家卫健委）","流行性感冒抗病毒药物治疗与预防应用中国专家共识（2023）","新型冠状病毒感染诊疗方案（试行第十版）","IDSA Influenza Guidelines 2018 Update"]},{"id":"id_tb","name":"肺结核","aka":["Tuberculosis","TB","肺痨"],"rank":3,"basic":{"define":"由结核分枝杆菌（MTB）引起的慢性传染病，以肺部受累最常见；凡满足病原学阳性，或临床+影像+免疫学支持且排除其他病因者可临床诊断。按是否耐药分为敏感结核、单耐药、多耐药、耐多药（MDR-TB）、广泛耐药（XDR-TB）。","risk":["与活动性肺结核患者密切接触","HIV 感染、糖尿病、慢性肾病、矽肺、恶性肿瘤与免疫抑制剂使用者","营养不良、酗酒、吸烟、居住拥挤","既往结核史（复发或再感染）","流动人口与医务人员等高暴露人群"],"epi":"我国为全球结核病高负担国家之一，2023 年估算新发肺结核约 74 万例，发病率约 52/10 万；耐多药结核占比约 1%–3%（新患者）至 10%–20%（复治患者），是主要公共卫生挑战。"},"patho":"MTB 经飞沫核吸入肺泡后被巨噬细胞吞噬但难以被杀灭，形成结核结节与干酪样坏死；细胞免疫（CD4⁺ Th1、IFN-γ）致肉芽肿形成与纤维化，空洞形成利于细菌排入气道造成传播。细菌在巨噬细胞内静息形成持留状态（潜伏感染）与复燃机制，免疫抑制时易进展为活动性结核。","dx":{"criteria":["病原学阳性：痰/支气管肺泡灌洗液抗酸染色涂片阳性，或培养出 MTB，或 GeneXpert MTB/RIF 阳性（同时报告利福平耐药）","临床诊断：典型影像（上叶尖后段或下叶背段浸润、空洞、树芽征）+ 临床症状（咳嗽 ≥2 周、低热、盗汗、消瘦）+ IGRA/T-SPOT 或 PPD 阳性，且排除其他病因","IGRA 阳性仅提示结核感染（含潜伏感染），不能区分活动性与结核病","HIV 合并者 CD4 <200 时肺结核影像不典型（无空洞、淋巴结肿大、粟粒型），应重视淋巴结穿刺与血培养（BACTEC）","群体筛查：密切接触者 IGRA 或 PPD；潜伏感染者 PPD 硬结 ≥15 mm 或 IGRA 阳性视为高危","耐药检测：肺结核病原学阳性者必须行 GeneXpert MTB/RIF 检测利福平耐药，必要时行表型药敏"],"workup":["痰抗酸染色 3 次 + 痰培养（BACTEC MGIT）+ GeneXpert MTB/RIF","胸片后前位与侧位；胸部 CT 评估空洞、支气管播散","IGRA（T-SPOT.TB/QFT）辅助诊断与接触者筛查","血常规、肝肾功能、血糖、HIV 与 HBV 检测（抗结核药肝毒性与相互作用评估）","支气管镜（BALF 送结核培养与 PCR）用于影像与痰阴性但高度可疑者","耐药评估：表型药敏 + 基因型（rpoB、katG、inhA、pncA、gyrA 位点）","视力与色觉（乙胺丁醇）、尿酸（吡嗪酰胺）、听力（氨基糖苷/贝达喹啉方案评估）"],"grading":"按部位分肺结核（I 型原发综合征、II 型血行播散、III 型继发性）、肺外结核；按涂片分级（1+、2+、3+、4+）；按耐药分类：敏感、单耐药、多耐药、耐多药（MDR，至少含异烟肼与利福平）、准广泛耐药（pre-XDR）、广泛耐药（XDR）。"},"ddx":[{"name":"流感与新冠（id_flu）","point":"与本类 id_flu 的鉴别点：流感/新冠起病急、高热与呼吸道症状显著、抗体/核酸阳性，影像为间质或磨玻璃改变，病程 1–2 周；肺结核病程 >2 周、低热盗汗、上叶空洞，IGRA 阳性。"},{"name":"非结核分枝杆菌（NTM）肺病","point":"慢性咳嗽与影像空洞与结核相似，但抗酸涂片阳性而 MTB 培养阴性、NTM 培养阳性；多见于支气管扩张、老年女性，MDT 方案与结核不同。"},{"name":"肺癌","point":"咳嗽或咯血，影像为占位、毛刺与分叶，无空洞或厚壁偏心空洞，肿瘤标志物与 CT 引导穿刺病理确诊，抗结核治疗无效。"},{"name":"肺脓肿","point":"起病急、高热、大量脓痰，白细胞与 PCT 显著升高，影像见液平空洞，抗菌药/引流治疗有效。"},{"name":"结节病","point":"双侧肺门淋巴结对称肿大、非干酪性肉芽肿，IGRA 阴性，影像以中上肺野结节与淋巴管周围分布，常伴高钙血症。"}],"tx":{"drug":[{"name":"异烟肼","dose":"5 mg/kg/d（成人 300 mg qd）口服；强化期 2 个月，巩固期 4 个月","note":"方案 2HRZE/4HR 的核心；治疗早期需监测肝功能，合并 HIV 或肝病者需权衡","renal":"肾功能不全无需调整，但血透患者建议透析后给药","hepatic":"肝功能不全者减量或间歇（每周 3 次）；急性肝衰竭禁用","interact":"慢乙酰化者与利福平、对乙酰氨基酚、酒精合用增肝毒性；与卡马西平、苯妥英钠合用抑制代谢"},{"name":"利福平","dose":"10 mg/kg/d（成人 450–600 mg qd，体重 <50 kg 用 450 mg），空腹晨服，强化期 2 个月+巩固期 4 个月","note":"强效杀菌，与异烟肼组成为核心方案；服药后尿液、汗液呈橘红色属正常","renal":"CrCl <30 无需调整；血液透析无需额外补充","hepatic":"肝功能不全或胆道梗阻慎用；黄疸需停药评估","interact":"强 CYP3A4/2C9 诱导剂，显著降低口服避孕药、华法林、他汀、蛋白酶抑制剂（PI）与部分抗结核药浓度"},{"name":"吡嗪酰胺","dose":"25 mg/kg/d（成人 1.0–1.5 g qd，或 50–70 kg 者 1.5 g），强化期 2 个月","note":"促空洞闭合与组织杀菌，用药早期监测尿酸与肝功；痛风患者慎用","renal":"CrCl ≥50 无需调整；CrCl <30：25–35 mg/kg/d 每周 3 次或遵说明书延长给药","hepatic":"肝功能受损者禁用或改为间歇方案","interact":"降低环孢素、他克莫司浓度（严格监测血药浓度）"},{"name":"乙胺丁醇","dose":"15 mg/kg/d（成人 1.0–1.25 g qd），强化期 2 个月","note":"用药期间监测视力与色觉，出现视物模糊或色觉异常立即停药；儿童注意辨色能力随访","renal":"CrCl 50–90：15 mg/kg qd；CrCl 10–50：15–25 mg/kg 每周 3 次；CrCl <10：15 mg/kg 每周 3 次","hepatic":"无需调整","interact":"与氨基糖苷类、乙硫异烟胺合用增加视神经毒性；与铝/镁抗酸剂同服减少吸收（间隔 2 h）"},{"name":"贝达喹啉（耐药结核）","dose":"400 mg qd 口服 ×2 周，之后 200 mg 每周 3 次，总疗程常 6 个月（联合方案中）","note":"用于 MDR-TB 联合方案；QTc 延长风险，需每周心电图监测，QTc >500 ms 停药","renal":"中重度肾功能不全需谨慎、监测","hepatic":"重度肝功能不全慎用并随访转氨酶","interact":"强 CYP3A4 抑制剂（伊曲康唑、利托那韦）升高暴露；与延长 QT 药物联用风险叠加"}],"nonDrug":["直接面视下督导治疗（DOT）保证依从与疗程完整性","传染期隔离：涂片阳性者呼吸道隔离至涂片转阴或治疗 ≥2 周且症状改善","密切接触者筛查（IGRA/PPD + 胸片），高危者可预防性治疗","耐药结核采用含贝达喹啉、普托马尼或德拉马尼的全口服方案，MDT 专科评估","大咯血、气胸、毁损肺、空洞无闭合者行支气管动脉栓塞或外科手术","卧床或免疫抑制者加强营养与肺康复训练"],"life":["全程规律服药，固定每日服药时间，避免漏服以及自行停药或减量","每月复查痰涂片和痰培养至转阴，疗程结束复查胸片与痰培养","全程监测肝功（第 2、4、8 周及之后定期）、视力、尿酸","加强营养（蛋白 ≥1.2 g/kg/d）、戒烟戒酒、休养与隔离管理","治疗后随访 2 年，警惕复发与再感染"]},"prog":"敏感肺结核规范治疗 6 个月治愈率达 85%–95%；复发率 <5%。MDR-TB 治愈率约 55%–60%（含贝达喹啉方案可升至 80% 以上），疗程长且不良反应多。延误诊断或不规律治疗是耐药和传播的主要原因。","refs":["中国结核病预防控制工作技术规范（2020 年版）","结核病诊疗规范（2021 年版，国家卫健委）","耐药结核病化学治疗指南（2019 年修订版，中国防痨协会）","WHO Global Tuberculosis Report 2023"]},{"id":"id_crab","name":"碳青霉烯耐药菌感染","aka":["CRE","CRAB","CRPA","碳青霉烯耐药肠杆菌目细菌","耐碳青霉烯类肺炎克雷伯菌"],"rank":4,"basic":{"define":"对亚胺培南、美罗培南或厄他培南中至少一种耐药（MIC ≥4 mg/L）的细菌感染，主要包括碳青霉烯耐药肠杆菌目（CRE）、铜绿假单胞菌（CRPA）和鲍曼不动杆菌（CRAB），是我国院内获得性感染与脓毒症的重要病因。","risk":["长期住院、ICU入住 ≥7 天","既往碳青霉烯类抗菌药暴露（尤其 90 天内使用）","侵入性装置：中心静脉导管、尿管、气管插管、引流管","实体器官移植、造血干细胞移植、免疫抑制治疗","机械通气、血液透析、近期手术（尤其腹部）","既往多重耐药菌定植（直肠、呼吸道、皮肤拭子筛查阳性）"],"epi":"我国 CHINET 监测显示碳青霉烯耐药肺炎克雷伯菌（CRKP）检出率约 20%–25%，耐碳青霉烯铜绿假单胞菌约 15%–25%，耐碳青霉烯鲍曼不动杆菌（CRAB）约 55%–70%，且地区差异大；CRKP 血流感染病死率可 >40%。"},"patho":"主要机制：产碳青霉烯酶（KPC、NDM 等金属酶、OXA-48 类）、外膜孔蛋白缺失（OmpK35/36）+ AmpC/ESBL 过表达、外排泵上调；碳青霉烯酶基因多位于可转移质粒上，导致院内水平传播。耐药菌定植后经黏膜屏障破坏、导管与机械通气侵入血流，内毒素与荚膜多糖致炎症失控与脓毒症。","dx":{"criteria":["药敏试验（MIC 法/纸片扩散）显示对碳青霉烯类耐药（MIC ≥4 mg/L 或抑菌圈 ≤19 mm），按 CLSI/EUCAST 判读","CRKP/CRE 应进一步行碳青霉烯酶表型与基因检测（mCIM/eCIM + PCR），确定 KPC、NDM、OXA-48 等，以指导用药","血流感染、VAP/HAP、腹腔感染、泌尿系感染、手术部位感染为主要表现；脓毒症者按 SOFA 评估","定植与感染需区分：痰培养阳性不等于肺炎，尿培养阳性需结合症状与尿常规；应有合理临床依据","2023 年 CHINET/CDDEP 报告判读标准可能不同，需以本实验室报告为准"],"workup":["血培养 2 套+目标部位培养（痰、尿、腹腔引流液、导管尖端），药敏定量 MIC","碳青霉烯酶基因检测（KPC、NDM、OXA-48、VIM、IMP）","CRP、PCT、血常规、血气、乳酸、肝肾功能","影像学定位（胸腹 CT、床旁超声）","定植筛查：入 ICU 或高危患者直肠拭子筛查 CRE","脓毒症者评估器官功能与休克状态，必要时器官支持"],"grading":"按病原：CRE（含 CRKP）、CRPA、CRAB；按耐药机制：产 KPC、产 NDM 等金属酶、产 OXA-48、非产酶型（外膜通透性下降+ESBL）；按感染部位：血流、肺部、腹腔、泌尿、手术部位、中枢神经。"},"ddx":[{"name":"慢性乙型肝炎（id_hbv）","point":"与本类 id_hbv 的鉴别点：CRAB/CRE 感染为急性院内感染或脓毒症表现，抗菌药使用史、装置、培养阳性为关键；慢乙肝为慢性 HBV 感染，以转氨酶和 HBV DNA 异常为主，无急性革兰阴性菌培养阳性。"},{"name":"脓毒症（id_sepsis）","point":"均为重症感染但病因谱不同：CRAB/CRE 感染是脓毒症的病因之一，需通过耐药表型与酶型鉴别以选择抗菌方案；敏感菌感染与耐药菌感染的初始经验治疗策略不同。"},{"name":"真菌感染（念珠菌/曲霉）","point":"长期广谱抗菌药与免疫抑制者的持续发热，1,3-β-D 葡聚糖（G 试验）或半乳甘露聚糖（GM）阳性，血/肺泡灌洗液真菌培养阳性，需覆盖抗真菌治疗。"},{"name":"导管相关血流感染（非耐药菌）","point":"导管尖端培养阳性但血培养为非耐药细菌（如表皮葡萄球菌），需拔管并覆盖革兰阳性球菌；CRE 感染常伴血流动力学不稳与脓毒症。"}],"tx":{"drug":[{"name":"头孢他啶阿维巴坦","dose":"2.5 g（头孢他啶 2 g + 阿维巴坦 0.5 g）q8h，静脉滴注 2 h","note":"产 KPC 或产 OXA-48 样酶 CRE 的首选；对产 NDM 金属酶无效（可联合氨曲南覆盖）；CRPA 耐药机制为外排/膜孔蛋白时效果不确定","renal":"CrCl >50：2.5 g q8h；CrCl 31–50：1.25 g q8h；CrCl 16–30：0.94 g q12h；CrCl 6–15：0.94 g q24h；CrCl ≤5 或透析：0.94 g q48h（透析后给药）","hepatic":"中度肝功能不全无需调整；重度者慎用、监测","interact":"与延长 QT 或肾毒性药物联用时注意叠加风险；与丙磺舒无显著相互作用"},{"name":"多黏菌素 B（多黏菌素 B 硫酸盐）","dose":"负荷 2.0–2.5 mg/kg（按体重）静脉，维持 1.25–1.5 mg/kg q12h，1 h 静滴；剂量按总药量计算，不按多黏菌素活性单位","note":"产 NDM 等金属酶 CRE、CRAB 的重要选择，常与替加环素/磷霉素联合；肾毒性发生率高（10%–50%）","renal":"多黏菌素 B 经非肾途径清除，无需按肾功能调整；多黏菌素 E 甲磺酸盐（黏菌素）需按 CrCl 调整：CrCl ≥80 150 mg CBA q12h，50–79 75–115 mg q12h，30–49 50–60 mg q12h，<30 遵说明书减量","hepatic":"无需调整，重度肝病注意转氨酶升高","interact":"与氨基糖苷类、万古霉素、两性霉素 B、NSAIDs 合用显著增加肾毒性；与肌松剂合用加重神经肌肉阻滞"},{"name":"替加环素","dose":"负荷 100 mg 静脉 30 min，之后 50 mg q12h（重症可 100 mg q12h，医师评估）；疗程 7–14 天","note":"覆盖 CRE 与 CRAB 的广谱四环素类，不覆盖铜绿假单胞菌；组织浓度高但血药浓度偏低，血流感染常需联合","renal":"轻中度无需调整；重度肾功能不全与血液透析患者慎用","hepatic":"Child-Pugh A 无需调整；B 减为 25 mg q12h；C 减为 25 mg q24h","interact":"与华法林合用降低 INR；与口服避孕药合用降低避孕效果；与含铝/钙抗酸剂间隔 2 h"},{"name":"美罗培南（碳青霉烯保留或高剂量）","dose":"2 g q8h 延长输注 3 h（MIC ≤8 mg/L 的非产酶或低水平耐药菌）；疑产碳青霉烯酶时应换用新药","note":"高剂量延长输注提高 %fT>MIC，可作为联合方案基础；对已产 KPC/NDM 的菌株单用无效","renal":"CrCl >50：2 g q8h；CrCl 26–50：2 g q12h；CrCl 10–25：1 g q12h；CrCl <10：1 g q24h；CRRT：1 g q8h 延长输注","hepatic":"无需调整","interact":"与丙戊酸合用显著降低其浓度，禁用联用"},{"name":"氨曲南（联合头孢他啶阿维巴坦）","dose":"2 g q6–8h 静脉滴注，与头孢他啶阿维巴坦联用","note":"产 NDM 金属酶 CRE 的联合方案之一（阿维巴坦抑制其他 β-内酰胺酶，氨曲南对金属酶稳定）","renal":"CrCl 30–60：2 g q8h；CrCl 15–29：1 g q8h；CrCl <15 或透析：1 g q12h","hepatic":"无需调整","interact":"与氨基糖苷类合用可能增加耳肾毒性；配伍需按说明书选择相容溶剂"}],"nonDrug":["严格接触隔离（单间或同类定植者集中安置），手卫生与环境消毒，必要时筛查密切接触者","感染源控制：拔除/更换导管、引流脓肿、清创坏死组织","抗菌药物管理：及时降阶梯，只对临床感染治疗、不对定植治疗，疗程 7–14 天并动态复查培养","脓毒症支持治疗：按 SSC 治疗指南进行液体复苏与器官支持","CRAB 感染可考虑联合方案（替加环素 + 多黏菌素 + 美罗培南）与雾化吸入多黏菌素（VAP）"],"life":["随访培养转阴或临床缓解后再转入普通病房，解除隔离需连续 ≥2 次间隔 24 h 的阴性培养","加强营养与功能康复，长期卧床/免疫抑制患者建立随访计划","出院后根据感染部位评估复发风险（尤其心内膜炎、骨关节感染）","合理使用抗菌药，避免自行停药或延长疗程"]},"prog":"CRE 血流感染病死率 30%–50%，CRAB 肺炎住院病死率可达 40%；使用体外敏感的新型 β-内酰胺酶抑制剂复方（头孢他啶阿维巴坦、美罗培南韦博巴坦）与早期感染源控制可显著改善预后。耐药基因质粒传播带来院内暴发风险。","refs":["中国碳青霉烯类耐药肠杆菌科细菌感染诊断与防控专家共识（2016）","耐碳青霉烯类肠杆菌目细菌感染诊治与防控中国专家共识（2023）","广泛耐药革兰阴性菌感染诊治专家共识（2022）","CHINET 中国细菌耐药监测网 2023 年度报告","IDSA Guidance on the Treatment of Antimicrobial-Resistant Gram-Negative Infections 2024"]}]},{"id":"cns_skin_inf","name":"中枢与皮肤软组织感染","rank":3,"summary":"中枢感染以「尽快取标本 + 足量穿透血脑屏障的药物」为核心：脑膜炎先做腰穿、糖皮质激素在首剂抗菌药前给予、头孢曲松 2 g q12h；脑炎一旦怀疑即予阿昔洛韦 10 mg/kg q8h。皮肤软组织感染以分级判断「能否口服、能否门诊」与「是否必须急诊切开」为主线，坏死性筋膜炎一旦怀疑即手术，不等影像。","compare":[{"diseaseId":"id_meningitis","dx":"发热 + 头痛/颈强直/意识改变，脑脊液压力升高、中性粒细胞为主、糖 <2.2 mmol/L（或脑脊液/血糖 <0.4）、蛋白 >1 g/L","key":"脑脊液中性粒细胞为主且糖低；糖皮质激素在首剂抗菌药前或同时给予"},{"diseaseId":"id_encephalitis","dx":"发热 + 意识障碍/精神行为异常 + 癫痫或局灶体征，脑脊液淋巴细胞为主、糖多正常，MRI 颞叶/边缘系统异常，HSV PCR 阳性","key":"意识障碍 + 发热 + 脑脊液淋巴细胞增多；阿昔洛韦不等 PCR 结果即启动"},{"diseaseId":"id_ssti","dx":"皮肤红肿热痛、脓疱/脓肿/蜂窝织炎；或皮肤坏死伴捻发音、与体征不符的剧痛、全身中毒","key":"剧痛与体征不符 + 进展快 + 捻发音/皮肤坏死 = 坏死性筋膜炎，需急诊手术探查"}],"diseases":[{"id":"id_meningitis","name":"细菌性脑膜炎","aka":["Bacterial meningitis","化脓性脑膜炎","急性细菌性脑膜炎"],"rank":1,"basic":{"define":"细菌经血行播散、邻近感染灶蔓延、颅脑外伤或神经外科操作进入蛛网膜下腔引起的化脓性炎症。成人以肺炎链球菌、脑膜炎奈瑟菌最常见，老年与免疫抑制者需警惕单核细胞增生李斯特菌；院内/术后以革兰阴性杆菌、金黄色葡萄球菌为主。","risk":["未接种肺炎链球菌、脑膜炎奈瑟菌疫苗","免疫抑制、糖尿病、酗酒、肝硬化、神经外科手术与分流管/人工耳蜗植入","中耳炎、鼻窦炎、乳突炎、脑脊液鼻漏与颅底骨折","托幼机构、宿舍等密集居住（脑膜炎奈瑟菌）"],"epi":"我国年发病率约 1–2/10 万；肺炎链球菌约占成人病原 40%–50%，院内及术后感染者耐药率高。规范治疗后成人病死率 10%–20%，10%–20% 幸存者遗留听力下降、认知障碍或癫痫。"},"patho":"病原体进入蛛网膜下腔后迅速复制，释放脂磷壁酸、肽聚糖与荚膜多糖，诱导 TNF-α、IL-1β、IL-6 大量释放；血脑屏障紧密连接破坏造成血管源性水肿与鞘内炎性渗出，脑脊液回吸收障碍形成交通性脑积水，颅内压升高可致脑疝；炎症性血管炎可致缺血性卒中，内耳毛细胞受累导致感音神经性聋。","dx":{"criteria":["发热、头痛、颈项强直三联征，伴意识改变；老年与免疫抑制者可仅发热 + 意识淡漠","脑脊液白细胞 >1000/μL（多 1000–5000/μL）、中性粒细胞 ≥80%，蛋白 >1 g/L，糖降低；乳酸 ≥3.5 mmol/L 支持细菌性","革兰涂片阳性率 60%–80%、培养阳性率 70%–85%，已用抗菌药者灵敏度明显下降","疑似者 30 min 内完成腰穿；抗菌药不得因腰穿延误 >30–60 min，血培养应在首剂前留取","有局灶体征、癫痫、GCS ≤10、免疫抑制或视乳头水肿者先行头颅 CT 排除占位与脑疝，CT 期间即开始经验性治疗","腰穿禁忌：穿刺部位感染、脑疝征象、血小板 <20×10⁹/L 或 INR >1.5（先纠正）、脊柱不稳定"],"workup":["脑脊液：压力、常规、生化、乳酸、革兰染色、培养、多重 PCR，必要时 mNGS","血培养 2 套（抗菌药前）、PCT、CRP、血常规；PCT 显著升高支持细菌感染","头颅 CT/MRI 增强：排除脑脓肿、脑水肿、梗死；MRI 对并发症更敏感","宿主因素：HIV、免疫球蛋白、补体、脾功能；反复发作者排查脑脊液漏","听力检查（治疗前与出院前各 1 次）；神经外科术后者脑室液培养 + 分流管影像"],"grading":"按病原：肺炎链球菌、脑膜炎奈瑟菌、李斯特菌、革兰阴性杆菌、金葡菌、无乳链球菌（新生儿）。意识用 GCS 评分；后遗症用改良 Rankin 量表与听力评估。"},"ddx":[{"name":"病毒性脑炎（id_encephalitis）","point":"与本类 id_encephalitis 的鉴别点：脑膜炎脑脊液中性粒细胞为主、糖低、乳酸高；脑炎以淋巴细胞为主、糖正常，核心是意识障碍与颞叶 MRI 病变，抗生素无效而阿昔洛韦有效。"},{"name":"皮肤软组织感染与坏死性筋膜炎（id_ssti）","point":"与本类 id_ssti 的鉴别点：SSTI 以皮肤红肿、脓肿、坏死为主，神经系统体征阴性；面部/头颈部 SSTI 可经静脉窦播散引起颅内感染，需同时评估。"},{"name":"结核性脑膜炎","point":"亚急性起病、低热盗汗，脑脊液单核为主、糖低、蛋白 1–3 g/L、氯化物降低，颅底强化与脑积水，抗酸染色/培养/mNGS 阳性。"},{"name":"蛛网膜下腔出血","point":"突发剧烈头痛，脑膜刺激征阳性，CT 见基底池高密度，无发热；脑脊液红细胞在多管标本间递减、黄变试验阳性。"},{"name":"脑脓肿","point":"局灶体征与进行性颅压升高，影像见环形强化病灶伴周围水肿，脑脊液常轻度异常或正常，需外科引流与长疗程治疗。"}],"tx":{"drug":[{"name":"头孢曲松","dose":"2 g q12h（4 g/d）静脉滴注 30–60 min，疗程 7–14 天（肺炎链球菌 10–14 天、脑膜炎奈瑟菌 5–7 天）；体重 >90 kg 或脑脊液浓度不足者 2 g q8h","note":"经验性方案骨架，覆盖肺炎链球菌与脑膜炎奈瑟菌；脑膜炎需高剂量维持脑脊液浓度 >MIC，不得以 1 g qd 常规替代","renal":"肾功能不全无需调整；中重度肾功能不全合并肝功能不全者减量（遵说明书）；透析无需追加","hepatic":"轻中度无需调整；重度肝损 + 肾衰竭时减量并监测","interact":"禁与含钙输液（乳酸林格液）同通路输注（沉淀风险）；与华法林合用增强抗凝"},{"name":"地塞米松","dose":"10 mg 静脉 q6h（或 0.15 mg/kg q6h）共 4 天，首剂在首次抗菌药前 10–20 min 或至少同时给予，按期停用","note":"减少肺炎链球菌脑膜炎的听力丧失与神经后遗症；已给抗菌药后再补激素获益下降，但仍可予首剂；耐青霉素肺炎链球菌、脓毒症进展者不作常规；结核性脑膜炎慎用","renal":"无需调整","hepatic":"无需调整；重度肝病注意低钾、高血糖","interact":"与 NSAIDs 合用增加消化道出血；与利福平、苯妥英钠合用激素暴露下降"},{"name":"万古霉素","dose":"15–20 mg/kg q8–12h 静脉（单次 ≤2 g），负荷 25–30 mg/kg；按 AUC/MIC ≥400 或谷浓度 15–20 mg/L 调整；仅用于耐青霉素肺炎链球菌/MRSA 高风险者","note":"经验性加用；病原与药敏明确后敏感菌株立即停用","renal":"CrCl 50–89：15–20 mg/kg q12h；CrCl 20–49：q24h；CrCl <20：负荷后按血药浓度定间隔；血液透析：每次透析后按浓度给药","hepatic":"轻度无需调整","interact":"与哌拉西林他唑巴坦、氨基糖苷类、两性霉素 B 合用增加急性肾损伤"},{"name":"氨苄西林","dose":"2 g q4h（12 g/d）静脉，用于 ≥50 岁、酗酒、肝硬化、免疫抑制或妊娠者经验性覆盖李斯特菌","note":"李斯特菌对头孢菌素天然耐药，上述人群必须加用","renal":"CrCl 15–29：2 g q6h；CrCl <15 或透析：2 g q12h，透析后追加 2 g","hepatic":"无需调整","interact":"与别嘌醇合用增加皮疹；与氨基糖苷类同瓶可失活（分开输注）"},{"name":"美罗培南","dose":"2 g q8h 静脉滴注（延长输注 3 h），用于院内/术后、革兰阴性杆菌或青霉素重度过敏者","note":"覆盖革兰阴性杆菌与厌氧菌，可用于脑脓肿与术后脑膜炎","renal":"CrCl 26–50：2 g q12h；CrCl 10–25：1 g q12h；CrCl <10：1 g q24h；CRRT：1 g q8h 延长输注","hepatic":"无需调整","interact":"与丙戊酸禁用联用（浓度骤降、癫痫风险）"},{"name":"阿昔洛韦","dose":"10 mg/kg q8h 静脉滴注 ≥1 h，仅在病原未明阶段与病毒性脑炎鉴别期短期合用；确诊细菌后 24–48 h 停用","note":"避免多种药物长期「全包围」；病原明确即降阶梯","renal":"CrCl 25–50：10 mg/kg q12h；CrCl 10–25：q24h；CrCl <10：5 mg/kg q24h；透析后给药","hepatic":"无需调整","interact":"与氨基糖苷类、两性霉素 B、多黏菌素合用增加肾损害"}],"nonDrug":["气道与循环支持、控制性氧疗；抬高床头 30°，避免低氧、低血压与高碳酸血症加重颅压","颅压升高：20% 甘露醇 0.5–1 g/kg 或 3% 高渗盐水，目标颅内压 <20 mmHg、脑灌注压 ≥60 mmHg；不单用大剂量激素降颅压","癫痫：发作时苯二氮䓬类终止，随后左乙拉西坦或苯妥英钠维持，不常规预防用药","感染源控制：脑脊液漏修补、鼻窦/乳突清创、拔除分流管或脑室外引流后重置","监测 SIADH（低钠血症），限制自由水","疫苗预防（肺炎链球菌结合疫苗、脑膜炎奈瑟菌疫苗）；无脾者青霉素预防","奈瑟菌脑膜炎密切接触者：利福平 600 mg q12h ×2 天，或环丙沙星 500 mg 单剂、头孢曲松 1 g 单剂肌注"],"life":["出院前完成听力、神经查体与认知评估，异常者进入康复随访","卧床期预防 DVT，渐次恢复活动，2–4 周内禁酒与剧烈运动","出院后 1–3 个月复查；癫痫者按神经科规范治疗，驾驶与高危作业需评估","反复脑膜炎者排查补体缺陷、免疫球蛋白缺乏与脑脊液漏"]},"prog":"成人病死率 10%–20%，肺炎链球菌脑膜炎可达 20%–30%，脑膜炎奈瑟菌 5%–10%；幸存者 10%–20% 遗留听力下降、认知障碍、癫痫或运动障碍。首剂抗菌药每延迟 1 h 均与不良预后相关。","refs":["中国成人社区获得性细菌性脑膜炎诊断与治疗专家共识（2023）","中国脑膜炎球菌疫苗预防接种专家共识（2023）","IDSA Practice Guidelines for the Management of Bacterial Meningitis 2004","ESCMID Guideline on Acute Bacterial Meningitis 2016"]},{"id":"id_encephalitis","name":"病毒性脑炎","aka":["Viral encephalitis","单纯疱疹病毒性脑炎","HSV encephalitis","乙型脑炎"],"rank":2,"basic":{"define":"病毒直接侵犯脑实质（少数为感染后免疫介导）导致的弥漫性或局灶性中枢神经炎症。成人最常见与最危重的是单纯疱疹病毒 1 型（HSV-1）脑炎；我国夏秋季需警惕流行性乙型脑炎；其他包括水痘-带状疱疹病毒、肠道病毒 71 型、EB 病毒、狂犬病病毒等。","risk":["未接种乙脑疫苗、居住于乙脑流行区或夏秋季蚊虫暴露","免疫抑制状态（激素、化疗、器官移植）","年龄 <14 岁或 >60 岁（重症风险高）","卫生条件差、居住拥挤（肠道病毒）","动物咬伤（狂犬病）"],"epi":"我国乙型脑炎年报告数百至千余例，7–9 月高发，病死率 5%–15%，存活者 20%–50% 遗留神经精神后遗症；HSV 脑炎是散发性病毒性脑炎首要病因，未治疗病死率 >70%，及时抗病毒降至 10%–20%。"},"patho":"HSV-1 多经三叉神经节或嗅束逆行至颞叶、额叶底面与边缘系统，引起坏死性脑炎（出血性坏死、神经元丢失、血管周围炎）；炎症与水肿形成颞叶占位效应与钩回疝风险。乙脑病毒经蚊媒叮咬后在单核-巨噬细胞系统扩增，血行突破血脑屏障，累及丘脑、基底节、脑干与脊髓前角，造成神经元坏死与胶质增生。","dx":{"criteria":["发热 + 意识障碍（精神行为异常、嗜睡至昏迷）+ 癫痫或局灶体征，多在 1 周内进展","脑脊液压力正常或偏高，白细胞 50–500/μL（淋巴细胞为主）、蛋白 0.5–1 g/L、糖与氯化物正常","脑脊液 HSV PCR 阳性为确诊依据；发病 3 天内可假阴性，48–72 h 后复查；PCR 阴性但临床与 MRI 高度符合时不停药","MRI：HSV 脑炎见颞叶、岛叶、扣带回不对称 T2/FLAIR 高信号伴出血或强化；乙脑见丘脑、基底节、脑干对称病变","脑电图：颞区周期性一侧性癫痫样放电（PLEDs）高度提示 HSV 脑炎，不能替代病原学","乙脑确诊：血清/脑脊液乙脑病毒 IgM 捕获法阳性或核酸阳性","起病 >2 周或抗病毒无效者应评估自身免疫性脑炎（抗 NMDAR、抗 LGI1 抗体）"],"workup":["脑脊液：常规、生化、乳酸、HSV/CMV/EBV/肠道病毒多重 PCR、mNGS；免疫抑制者加查隐球菌、结核与真菌","血常规、CRP、PCT、肝肾功能、电解质、血糖、血气（排除代谢与中毒原因）","头颅 MRI 增强（含 DWI/FLAIR），入院 24–48 h 内完成并复查评估进展","脑电图：癫痫样与周期性放电，意识障碍者持续监测","乙脑 IgM（血清与脑脊液）、登革等虫媒病原（按季节与地区）","HIV、免疫球蛋白、自身免疫性脑炎抗体谱；疑难重症可脑活检"],"grading":"按病原：HSV、水痘-带状疱疹病毒、乙脑病毒、肠道病毒、EBV/CMV；按临床：轻型（发热头痛）、普通型（轻度意识障碍）、重型（昏迷、频繁抽搐）、极重型（深昏迷、脑疝、中枢性呼吸衰竭）。"},"ddx":[{"name":"细菌性脑膜炎（id_meningitis）","point":"与本类 id_meningitis 的鉴别点：脑膜炎以脑膜刺激征、脑脊液中性粒细胞为主与糖低为核心，影像多无局灶脑实质改变；脑炎以意识障碍、癫痫与颞叶病变为核心，糖正常、细菌涂片与培养阴性。"},{"name":"皮肤软组织感染与坏死性筋膜炎（id_ssti）","point":"与本类 id_ssti 的鉴别点：带状疱疹伴发热与意识改变提示病毒脑炎；SSTI 本身无脑脊液细胞增多与颞叶病变。"},{"name":"自身免疫性脑炎","point":"精神行为异常、记忆减退、癫痫与运动障碍为主，脑脊液可仅轻度异常，抗神经元表面抗体阳性，激素 + 丙球/血浆置换有效。"},{"name":"结核性脑膜炎","point":"亚急性起病、低热盗汗与颅神经麻痹，脑脊液单核为主 + 糖显著降低 + 蛋白 >1 g/L，颅底强化与脑积水。"},{"name":"代谢性/中毒性脑病","point":"低血糖、肝性脑病、尿毒症、CO 中毒或药物接触史，脑脊液无细胞增多，纠正病因后迅速改善。"}],"tx":{"drug":[{"name":"阿昔洛韦","dose":"10 mg/kg q8h（按理想体重，单次一般 ≤800 mg）静脉滴注 ≥1 h，疗程 14–21 天；重症、MRI 残留病变或免疫抑制者 21 天并复查脑脊液 HSV PCR 转阴","note":"HSV 脑炎首选；疑似即启动，不等 PCR 或 MRI；肾毒性为主要不良反应，需充足水化、监测肌酐","renal":"CrCl 25–50：10 mg/kg q12h；CrCl 10–25：q24h；CrCl <10：5 mg/kg q24h；血液透析：透析后给药；CRRT：按 CrCl 10–25 后监测","hepatic":"轻中度无需调整；重度肝功能不全慎用","interact":"与氨基糖苷类、两性霉素 B、多黏菌素、他克莫司合用增加肾损害；与丙磺舒合用升高浓度"},{"name":"地塞米松","dose":"10 mg q6h 或 0.15 mg/kg q6h 静脉 4 天，伴显著脑水肿或中线移位时使用","note":"不作常规治疗；仅在明显占位效应/脑水肿时短期使用以降低脑疝风险","renal":"无需调整","hepatic":"无需调整；监测高血糖与继发感染","interact":"与 NSAIDs 合用增加消化道出血；影响免疫抑制药浓度"},{"name":"甘露醇 20%","dose":"0.5–1 g/kg 静脉快速滴注 q6–8h，按颅压与容量状态调整，疗程一般 ≤5 天","note":"控制脑水肿等待抗病毒起效；监测渗透压（目标 300–320 mOsm/L）、尿量与肾功能","renal":"少尿/无尿或肾功能不全者慎用或改 3% 高渗盐水；CRRT 患者可减量","hepatic":"无需调整","interact":"与利尿剂合用加重低钾与容量不足；与肾毒性药合用加重肾损害"},{"name":"左乙拉西坦","dose":"500 mg q12h 静脉或口服起始，按需上调至 1000 mg q12h；癫痫持续状态负荷 60 mg/kg（≤4.5 g）后维持","note":"用于控制发作，不预防性用于无发作患者","renal":"CrCl 30–50：250–750 mg q12h；CrCl <30：250–500 mg q12h；透析：负荷 750 mg 后 500–1000 mg q24h，透析后补 250–500 mg","hepatic":"Child-Pugh C 减量 50%","interact":"与丙戊酸无明显相互作用；与其他中枢抑制药合用加重嗜睡"}],"nonDrug":["ICU 监测：维持氧合（SpO2 ≥94%）、避免低钠血症、体温控制 ≤38.5 ℃、维持颅压与脑灌注","颅高压：抬高床头、限制液体、甘露醇或高渗盐水；难治者考虑去骨瓣减压（罕见）","病原治疗：VZV/EBV/CMV 者按病原选阿昔洛韦/更昔洛韦；乙脑无特异抗病毒药，以对症支持为主","抗体阳性合并自身免疫性脑炎：甲泼尼龙 1 g/d ×5 天 + 静脉丙种球蛋白 0.4 g/kg/d ×5 天，并行肿瘤筛查","GCS ≤8 或误吸风险高者气管插管；癫痫持续状态按阶梯用药","早期康复：被动活动、吞咽评估、言语与认知训练"],"life":["疗程结束复查脑脊液 HSV PCR、MRI 与脑电图，评估是否需延长","出院后 1、3、6 个月随访记忆、人格与运动功能，必要时神经心理测验","遗留癫痫者长期规范抗癫痫治疗，避免饮酒、睡眠剥夺；驾驶与高空作业需评估","乙脑流行区按免疫规划接种乙脑疫苗、防蚊灭蚊；孕妇与免疫抑制者避免进入疫区"]},"prog":"HSV 脑炎及时抗病毒病死率 10%–20%，未治疗 >70%；存活者 30%–50% 有记忆减退、人格改变或癫痫。乙脑病死率 5%–15%，存活者 20%–50% 遗留认知、运动或言语障碍。意识障碍程度、癫痫持续状态、MRI 病变范围与首剂时机为主要预后因素。","refs":["中国单纯疱疹病毒性脑炎诊治专家共识（2022）","流行性乙型脑炎诊断与治疗指南（中华医学会神经病学分会，2019）","中国自身免疫性脑炎诊治专家共识（2022）","IDSA Clinical Practice Guidelines: Encephalitis 2008"]},{"id":"id_ssti","name":"皮肤软组织感染与坏死性筋膜炎","aka":["SSTI","Skin and soft tissue infection","蜂窝织炎","坏死性筋膜炎","Necrotizing fasciitis"],"rank":3,"basic":{"define":"皮肤、皮下组织、筋膜与肌肉的感染性炎症。按层次分浅表（脓疱疮、毛囊炎、丹毒、蜂窝织炎）与复杂/深部（脓肿、深部软组织感染、坏死性筋膜炎、肌坏死）。坏死性筋膜炎（NF）沿筋膜层快速进展，可作为严重感染的首发表现。","risk":["糖尿病（约 1/3–1/2 的 NF 患者）、肥胖、外周血管病","皮肤破损、外伤、虫咬、注射毒品、术后切口","免疫抑制、长期激素、肝硬化、慢性肾病","水痘/带状疱疹皮损（儿童链球菌 NF）","足部溃疡与糖尿病足；MRSA 定植"],"epi":"皮肤软组织感染是急诊最常见感染之一，蜂窝织炎年发病率约 1–2/1000 人；NF 罕见（0.4–1/10 万），病死率 20%–35%，合并脓毒性休克 >50%。我国糖尿病足与术后切口感染是主要来源。"},"patho":"细菌经破损皮肤侵入，菌体成分与毒素激活中性粒细胞与补体，致红、热、痛与血管通透性增加；脓肿以中性粒细胞浸润与液化坏死为主。NF 分两型：I 型为需氧-厌氧混合（肠杆菌、脆弱拟杆菌、厌氧链球菌），II 型为单一细菌（A 群链球菌或社区 MRSA）产生链球菌致热外毒素与透明质酸酶，直接溶解筋膜与血管壁，致血栓形成、皮下神经坏死（早期即「痛觉减退」）与快速扩展，并引发中毒性休克。","dx":{"criteria":["浅表感染：局限红斑、脓疱或结痂，边界清，无全身中毒；丹毒边界隆起、扩展快","脓肿：波动感、局限性硬结与脓性渗出，床旁超声可定位","蜂窝织炎：红斑边界不清、皮温升高、触痛，常有淋巴管炎与区域淋巴结肿大","NF 红灯征象：剧痛与体征不符、数小时内快速扩展、皮肤苍白→暗红→紫黑坏死、捻发音或皮下气肿、大疱与皮肤感觉减退、低血压/乳酸升高/意识改变","LRINEC 评分（CRP、WBC、Hb、Na、Cr、血糖）≥6 提示 NF 可能性高，但低分不能排除，不能替代外科探查","糖尿病足按 Wagner 分级 + 感染程度（IDSA/IWGDF）判断是否住院、清创与截肢"],"workup":["血常规、CRP、PCT、乳酸、血糖、尿素氮/肌酐、电解质、肝功、凝血（DIC 筛查）","深部组织/脓液培养（需氧 + 厌氧 + 真菌）+ 血培养 2 套","床旁超声（脓肿、积液、皮下气体）；CT/MRI 评估筋膜与肌肉受累范围","床边切开探查（finger test）：筋膜是否易钝性分离、有无灰白坏死组织与「洗肉水」样渗液，为 NF 诊断金标准","脓性分泌物革兰染色与快速培养；必要时 MRSA 筛查","脓毒症者按 SOFA 评估器官功能与休克"],"grading":"按层次：浅表（脓疱疮、毛囊炎、丹毒）、蜂窝织炎、脓肿、复杂/深部感染（含 NF、肌坏死）；NF 分 I 型（混合菌）与 II 型（A 群链球菌/金葡菌）；按探查后病变程度分局限型与扩展型。"},"ddx":[{"name":"细菌性脑膜炎（id_meningitis）","point":"与本类 id_meningitis 的鉴别点：SSTI 以局部红肿热痛、脓性渗出与组织坏死为主，意识与颈强直多正常；金葡菌菌血症合并头面部 SSTI 时需警惕颅内播散。"},{"name":"病毒性脑炎（id_encephalitis）","point":"与本类 id_encephalitis 的鉴别点：带状疱疹伴发热与意识改变提示病毒脑炎；SSTI 本身不引起中枢神经体征。"},{"name":"深静脉血栓/浅静脉炎","point":"单侧下肢肿胀疼痛、皮温升高但无脓性渗出与创口，D-二聚体升高，超声见血栓。"},{"name":"痛风急性发作","point":"第一跖趾关节等突发剧痛红肿，血尿酸高，关节液见尿酸盐结晶，无脓毒表现，抗炎后迅速缓解。"},{"name":"糖尿病足溃疡（无感染缺血型）","point":"以足背动脉搏动减弱、跛行与缺血改变为主，无明显脓性渗出，需评估 ABPI/血管超声，先改善灌注再清创。"}],"tx":{"drug":[{"name":"头孢唑林","dose":"1–2 g q8h 静脉（重症或肥胖者 2 g q8h），疗程 5–10 天；MSSA 与链球菌一线","note":"不覆盖 MRSA 与厌氧菌","renal":"CrCl 20–50：1–2 g q12h；CrCl <20 或透析：1–2 g q24h，透析后追加一次","hepatic":"无需调整","interact":"与华法林合用增强抗凝；与呋塞米同一通路可沉淀"},{"name":"万古霉素","dose":"15–20 mg/kg q8–12h 静脉，按 AUC/MIC 400–600 或谷浓度 15–20 mg/L 调整；用于 MRSA 高风险或脓毒症患者","note":"社区 MRSA 流行区、注射毒品相关脓肿、术后重症感染经验性覆盖","renal":"CrCl 20–50：15–20 mg/kg q24h；CrCl <20：负荷后按浓度定间隔；血液透析：每次透析后 1 g 或按谷浓度","hepatic":"轻度无需调整","interact":"与哌拉西林他唑巴坦、氨基糖苷类、多黏菌素合用增加急性肾损伤"},{"name":"哌拉西林他唑巴坦","dose":"4.5 g q6h 静脉（延长输注 3 h），用于 NF 与糖尿病足混合感染经验方案","note":"覆盖革兰阴性菌与厌氧菌，是 I 型 NF 的骨架；疑铜绿假单胞菌或肠球菌时联合相应药物","renal":"CrCl 20–40：3.375 g q6h；CrCl <20：2.25 g q6h；血液透析后追加 2.25 g；CRRT：4.5 g q8h 延长输注","hepatic":"无需调整","interact":"与万古霉素合用增加急性肾损伤；与甲氨蝶呤合用降低其清除"},{"name":"克林霉素","dose":"600–900 mg q8h 静脉（或 300–450 mg q6–8h 口服），疗程 7–10 天","note":"抑制链球菌致热外毒素与 M 蛋白产生，是 A 群链球菌 NF 的重要辅助药；监测腹泻与艰难梭菌感染","renal":"无需调整；重度肾功能不全合并肝病时减量","hepatic":"重度肝功能不全减量","interact":"与大环内酯类合用拮抗；与肌松剂合用增强神经肌肉阻滞"},{"name":"利奈唑胺","dose":"600 mg q12h 静脉或口服，疗程按部位 7–14 天","note":"覆盖 MRSA 与耐药革兰阳性菌，口服生物利用度 100%；长期用需监测血象与视神经","renal":"无需按肾功能调整，透析与 CRRT 无需补充","hepatic":"轻中度无需调整；重度肝功能不全慎用","interact":"可逆性 MAO 抑制剂：与 SSRI/SNRI、拟肾上腺素药合用可致 5-羟色胺综合征或血压升高；与利福平合用降低暴露"},{"name":"复方磺胺甲噁唑","dose":"TMP 160 mg/SMZ 800 mg q12h 口服，用于社区 MRSA 非化脓性蜂窝织炎或口服序贯","note":"过敏、狼疮、G6PD 缺乏者慎用；不作深部/坏死性感染首选","renal":"CrCl 15–30：减量 50%；CrCl <15：不推荐","hepatic":"重度肝功能不全慎用","interact":"与华法林合用显著升高 INR；与 ACEI/ARB、保钾利尿剂合用致高钾"}],"nonDrug":["浅表蜂窝织炎：抬高患肢、局部冷敷；无全身症状且无糖尿病/免疫抑制者可 5 天口服（头孢氨苄或克林霉素）","脓肿：切开引流是核心；直径 ≥5 cm 或伴全身症状者加抗菌药，引流后 24–48 h 评估","NF：临床高度怀疑即刻急诊手术，不等 MRI；首次清创切除全部无活力组织，术后每 12–24 h 反复探查至无进展","感染源控制：筋膜切开减压、截肢评估；糖尿病足需减压、血管评估与必要时血管重建","高压氧为 NF 与糖尿病足感染的辅助治疗，不能替代清创与抗菌药","脓毒症按 SSC 复苏；血糖控制 7.8–10 mmol/L","抗菌药物管理：药敏明确后降阶梯，浅表感染 5–10 天，引流充分者不延长"],"life":["糖尿病足护理：每日检查、合适鞋袜、每 3–6 个月足部神经与血管评估","创面换药与负压引流，出院前安排伤口门诊与居家护理","NF 幸存者评估功能康复，需皮瓣移植者转整形外科","注射毒品相关感染者转介成瘾干预；复发脓肿者去定植（莫匹罗星鼻膏 + 氯己定洗浴）"]},"prog":"浅表蜂窝织炎规范治疗 5–10 天治愈率 >90%；深部与糖尿病足感染约 15%–25% 需截肢。NF 病死率 20%–35%，脓毒性休克与手术延迟（>24 h）是死亡最强预测因素，每延迟 1 h 均降低生存率。","refs":["中国皮肤软组织感染诊治专家共识（2021）","糖尿病足感染诊治中国专家共识（2023）","坏死性筋膜炎诊疗相关专家共识（2019）","IDSA Guidelines: Skin and Soft Tissue Infections 2014","WSES Guidelines on Necrotizing Soft Tissue Infections 2018"]}]},{"id":"zoonosis","name":"人畜共患与地方性感染","rank":4,"summary":"以「暴露史驱动诊断」为核心：问清蜱螨叮咬、羊牛猪接触、生乳饮用、稻田与洪水涉水史，再选检查与用药。四环素类（尤其多西环素）贯穿三者，但疗程与代替方案各异：恙虫病 7–14 天即可，布病需多西环素 + 利福平 6 周以上，钩体病首选青霉素/头孢曲松并警惕赫氏反应；均为法定报告传染病。","compare":[{"diseaseId":"id_scrub","dx":"疫区野外活动史 + 高热 + 叮咬处焦痂（部分患者无）+ 淋巴结肿大 + 皮疹；白细胞正常或降低、肝酶升高，外斐 OXK 或 IFA 阳性","key":"焦痂是特征性体征；多西环素 100 mg bid 起效快，24–48 h 退热"},{"diseaseId":"id_brucella","dx":"羊/牛/猪接触或生乳饮用史 + 波浪热、多汗、关节肌肉痛、肝脾与淋巴结肿大；血/骨髓培养或 SAT ≥1:160 阳性","key":"多西环素 + 利福平联合 6 周；单药与疗程不足是复发主因"},{"diseaseId":"id_lepto","dx":"污水/洪水/稻田接触史 + 发热、腓肠肌压痛、结膜充血；重症见黄疸、肾功衰竭或肺弥漫出血（Weil 病），PCR 或 MAT 阳性","key":"青霉素或头孢曲松早期有效；首剂须防赫氏反应，肺出血与黄疸性肾衰是主要死因"}],"diseases":[{"id":"id_scrub","name":"恙虫病（丛林斑疹伤寒）","aka":["Scrub typhus","Tsutsugamushi disease","丛林斑疹伤寒"],"rank":1,"basic":{"define":"由恙虫病东方体（Orientia tsutsugamushi）经携带病原的恙螨幼虫叮咬传播的自然疫源性疾病，以高热、焦痂、皮疹、淋巴结肿大与多器官受累为特征，重症可出现肺炎、脑膜脑炎、急性肾损伤与脓毒性休克。","risk":["夏秋季（南方 5–11 月、北方 6–9 月）在草地、林缘、河滩、农田劳作或露营","农田、果园、茶园作业与伐木者","野外露营、越野、垂钓者与农村老年人、儿童","环境差、鼠类密度高的居住区周边"],"epi":"我国恙虫病主要在长江以南及东南沿海（广东、福建、广西、云南、江苏、安徽），年报告数万例，集中在 6–10 月，农民与野外作业者为主。未治疗病死率 10%–30%，及时使用四环素类后 <2%。"},"patho":"恙螨幼虫叮咬时注入东方体，病原在局部真皮与单核-巨噬细胞系统内增殖，形成叮咬处坏死性溃疡与焦痂（周围红斑、中心黑痂），随后经血流播散。东方体侵犯血管内皮细胞，引起全身小血管炎、毛细血管通透性升高与血管周围炎症浸润，造成皮疹、间质性肺炎、脑膜脑炎、心肌炎与肝肾功能损害；重症与病原载量及 TNF-α、IFN-γ 释放相关。","dx":{"criteria":["发病前 1–3 周有草地/林地/农田暴露、户外活动或疫区居住旅行史","突发高热（39–40 ℃）、剧烈头痛、肌痛、结膜充血；约 50%–90% 有焦痂（无痛、直径 3–15 mm、中心黑色坏死痂伴红晕，常位于腋窝、腹股沟、会阴、腰腹等隐蔽处）","皮疹多在病程第 4–7 天出现，躯干向四肢扩展，多为斑丘疹；局部或全身淋巴结肿大","白细胞正常或降低、血小板减少、肝酶与 LDH 升高、低白蛋白；第 1 周后可见异型淋巴细胞","外斐试验 OXK ≥1:160 或双份 4 倍升高可辅助，第 2 周才阳转、特异性不足，阴性不能排除","确诊：IFA IgM/IgG 4 倍升高，或血/焦痂组织 PCR 阳性（第 1 周血液灵敏度较高）"],"workup":["全面查体：腋窝、腹股沟、腘窝、臀部、会阴、头皮寻找焦痂并拍照记录","血常规、CRP、PCT、肝肾功能、电解质、凝血、LDH、心肌酶","胸部 CT/胸片：间质浸润、胸腔积液","意识改变者腰穿：脑脊液单核细胞增多、蛋白轻度升高、糖正常","外斐试验（OXK）、IFA 双份血清、PCR（血/焦痂）","重症评估：血压、氧合、尿量、意识；心电图与超声心动图","排除出血热（汉坦病毒 IgM）、登革 NS1、疟疾涂片、伤寒血培养"],"grading":"① 轻型（发热 + 焦痂/皮疹，无器官受累）；② 普通型（轻度肝损伤或肺间质改变）；③ 重症（肺炎伴低氧、脑膜脑炎、AKI 或休克）；④ 危重型（多器官衰竭或脓毒性休克）。器官受累程度按 SOFA。"},"ddx":[{"name":"布氏杆菌病（id_brucella）","point":"与本类 id_brucella 的鉴别点：布病有牛羊猪接触或生乳史，以波浪热、多汗、关节肌肉痛为主，无焦痂、慢性化倾向明显，需双药 6 周；恙虫病起病急骤、有焦痂、多西环素 7–14 天短疗程可愈。"},{"name":"钩端螺旋体病（id_lepto）","point":"与本类 id_lepto 的鉴别点：钩体病有污水/洪水/鼠尿接触史，腓肠肌压痛与结膜充血突出，黄疸与肾功衰竭常见，无焦痂；恙虫病以血管炎、皮疹与肺炎为主，肾损害轻。"},{"name":"流行性出血热（肾综合征出血热）","point":"鼠类接触史，典型「三痛三红」与低血压休克期、少尿期接续，血小板显著下降、大量蛋白尿，出血热 IgM 阳性；无焦痂，白细胞常显著升高。"},{"name":"登革热","point":"伊蚊传播，突发高热伴剧烈骨肌痛、皮疹与白细胞/血小板下降，登革 NS1 或 IgM 阳性；无焦痂，出血倾向更显著。"},{"name":"药疹伴发热","point":"近期新增药物史，皮疹对称伴瘙痒、嗜酸性粒细胞升高，停药 1–2 周消退，无蜱螨暴露与焦痂。"}],"tx":{"drug":[{"name":"多西环素","dose":"100 mg q12h 口服（重症或不能口服者静脉），疗程 7–14 天；一般 48 h 内退热，退热后继续 3–7 天完成疗程","note":"恙虫病首选（成人、儿童均可）；起效快，早期用药显著降低病死率；退热即停药易复发","renal":"肾功能不全通常无需调整；血液透析无需追加剂量（遵说明书）；重度肾功能不全监测","hepatic":"肝功能不全慎用；严重肝病减量并监测","interact":"含铝/镁/钙抗酸剂、铁剂间隔 ≥2 h；与异维 A 酸合用增加颅压；与华法林合用增强抗凝"},{"name":"阿奇霉素","dose":"500 mg qd 口服或静脉（首日可 1 g），疗程 5–7 天","note":"孕妇、儿童或四环素类过敏者的替代，疗效略逊","renal":"CrCl <30 慎用并监测","hepatic":"肝功能不全慎用，黄疸时停药","interact":"与胺碘酮、氟喹诺酮合用增加 QT 延长；含铝/镁抗酸剂降低吸收"},{"name":"氯霉素","dose":"500 mg q6h（2 g/d），疗程 7–14 天；仅用于上述药物不可用的重症","note":"骨髓抑制风险，需监测血象","renal":"肾功能不全无需调整；肝肾功能同时受损时减量","hepatic":"重度肝损减量并监测血象","interact":"与甲氨蝶呤合用增加骨髓抑制；抑制华法林代谢"}],"nonDrug":["疫区发热 + 焦痂即开始多西环素，不等外斐或 PCR（延迟是死亡的主要可避免因素）","重症支持：低氧者氧疗/无创通气，ARDS 肺保护通气；脑膜脑炎控制惊厥与颅压；AKI 者必要时 CRRT","休克按 SSC 液体复苏与去甲肾上腺素；DIC 按需补充凝血因子","防护：穿长袖、涂驱避剂、扎裤脚，野外归来洗澡更衣并检查体表螨咬","灭鼠、清除杂草以降低恙螨密度","按乙类传染病（恙虫病）报告疾控部门"],"life":["完成全程治疗，避免体温正常即停药","出院后 1–2 周复查血常规与肝肾功能，重症延长至 1 个月","恢复期避免劳累与饮酒，再次发热及时复诊","疫区人群教育：识别焦痂、及时就医、个人防护（暂无可用疫苗）"]},"prog":"及时使用多西环素者病死率 <2%，用药后 24–48 h 显著退热；未治疗或延误者病死率 10%–30%，合并休克、ARDS 或脑膜脑炎者预后差。老年、糖尿病、慢性肺病与低白蛋白者更易重症。","refs":["恙虫病诊疗专家共识（中华医学会感染病学分会，2021）","中国恙虫病预防控制相关技术方案（中国疾控，2019）","WHO Informal Consultation on Scrub Typhus 2022","Mandell, Douglas and Bennett's Principles and Practice of Infectious Diseases, 9th ed."]},{"id":"id_brucella","name":"布氏杆菌病（布鲁菌病）","aka":["Brucellosis","波状热","马尔他热","波浪热"],"rank":2,"basic":{"define":"由布鲁菌属（我国主要为羊种 B. melitensis，其次牛种、猪种）引起的人畜共患传染病，主要通过接触病畜及其分泌物、流产胎盘、生乳或吸入含菌气溶胶感染，表现为长期发热、多汗、关节肌肉痛、肝脾与淋巴结肿大，易转为慢性与复发。","risk":["牧民、兽医、屠宰与皮毛加工、乳品加工者（职业暴露）","饮用未经巴氏消毒的生羊奶、牛奶及奶酪","接触流产病畜的胎盘、胎儿与分泌物（主要途径）","实验室人员处理布鲁菌培养物","食用未煮熟的羊肉、内脏与涮肉","牧区居民（内蒙古、新疆、西藏、青海、宁夏、甘肃）"],"epi":"我国 2015–2023 年每年报告约 3–5 万例，以内蒙古、新疆、山西、河北等北方农牧区为主，南方省份在增加；急性期规范治疗治愈率 >90%，疗程不足时复发率 5%–15%。"},"patho":"布鲁菌经皮肤破损、黏膜、消化道或呼吸道进入，被巨噬细胞吞噬后在网状内皮系统（肝、脾、骨髓、淋巴结）内驻留繁殖，内毒素与脂多糖诱导肉芽肿形成；细菌在巨噬细胞内长期存活、逃避清除，形成慢性感染与反复发作（波浪热源于细菌周期性释放入血）。肉芽肿累及关节、脊柱、心瓣膜与神经系统可致脊柱炎、感染性心内膜炎与神经布鲁菌病。","dx":{"criteria":["病畜（羊、牛、猪）接触、流产接触或生乳饮用史，或疫区居住工作；潜伏期 5–60 天（平均 2 周）","发热（波浪热或弛张热，午后至夜间升高）、大汗（湿透衣被）、乏力、游走性关节肌肉痛、腰痛，肝脾与淋巴结肿大；可伴睾丸炎、心内膜炎、脊柱炎","确诊：血/骨髓培养出布鲁菌（骨髓阳性率高于血培养；双相培养可提高检出率）","血清学：虎红平板凝集试验筛查，SAT ≥1:160 或双份 4 倍升高；ELISA、胶体金为补充","需病原学或血清学至少一项支持并结合临床；流行区临床 + 抗体阳性即可临床诊断","SAT 发热期可因前带现象假阴性，需骨髓培养与多次血培养"],"workup":["血培养（双相培养或 BACTEC，培养延长至 4 周），必要时骨髓穿刺培养","虎红平板凝集试验 + SAT 定量、ELISA、2-巯基乙醇试验","血常规（白细胞正常或降低、淋巴细胞相对增多）、CRP、ESR、肝功能","脊柱 MRI（腰痛/脊柱炎）、超声心动图（新杂音或栓塞事件）","关节/中枢受累者作影像与脑脊液（淋巴细胞增多、蛋白升高、抗体或培养阳性）","鉴别结核（肉芽肿性肝脾病变）、伤寒、淋巴瘤、莱姆病"],"grading":"按病程：急性（<2 个月）、亚急性（2–12 个月）、慢性（>12 个月或治疗后持续症状）；按临床型：单纯型、肝脾型、骨关节型（脊柱炎/骶髂关节炎）、神经型、心血管型（心内膜炎）、生殖系型（睾丸炎）。"},"ddx":[{"name":"恙虫病（id_scrub）","point":"与本类 id_scrub 的鉴别点：恙虫病急起高热伴焦痂、皮疹与血管炎，病程 1–3 周，多西环素单药 7–14 天即可；布病有牛羊猪或生乳史，以多汗、游走性关节痛、波浪热与慢性化为特点，需双药联合 ≥6 周。"},{"name":"钩端螺旋体病（id_lepto）","point":"与本类 id_lepto 的鉴别点：钩体病有洪水/污水接触史与腓肠肌压痛、黄疸与肾损害；布病黄疸少见，以脊柱炎、骶髂关节炎、睾丸炎为特点。"},{"name":"伤寒与副伤寒","point":"持续发热伴相对缓脉、玫瑰疹、腹胀与脾大，白细胞低，血/骨髓培养伤寒沙门菌阳性。"},{"name":"结核病","point":"长期低热、盗汗与消瘦，肺或淋巴结/脊柱病变，培养/IGRA/PCR 阳性；椎体破坏与冷脓肿更支持脊柱结核。"},{"name":"类风湿关节炎","point":"对称性小关节肿痛、晨僵 >1 h、RF/抗 CCP 阳性，无病原学证据；布病关节炎多不对称、累及大关节或骶髂关节，伴发热与血清学阳性。"}],"tx":{"drug":[{"name":"多西环素","dose":"100 mg q12h 口服，联合利福平至少 6 周；合并脊柱炎延长至 12 周（个别 3–6 个月）；<8 岁与妊娠期可改用复方磺胺甲噁唑 + 利福平（遵专科意见）","note":"联合方案核心药，单药易复发；联合利福平或链霉素使复发率降至 <5%","renal":"肾功能不全一般无需调整；血透无需额外剂量（遵说明书）","hepatic":"肝功能受损者慎用并监测","interact":"含铝/镁/钙抗酸剂、铁剂间隔 2 h；与利福平合用多西环素暴露下降但仍为指南首选组合；与华法林合用增强抗凝"},{"name":"利福平","dose":"600 mg qd（体重 <50 kg 用 450 mg）空腹晨服，联合多西环素共 6 周","note":"首选联合搭档，疗效与链霉素方案相当、口服方便；尿与汗液橘红色属正常","renal":"无需调整","hepatic":"肝功能不全或胆道梗阻慎用；黄疸或转氨酶 >3 倍上限伴症状时停药","interact":"CYP3A4 强诱导剂，降低华法林、口服避孕药、他汀与抗反转录病毒药浓度"},{"name":"链霉素","dose":"1 g qd 肌注（或 15 mg/kg/d）联合多西环素 6 周；老年及肾功能不全者 0.5–0.75 g qd","note":"替代利福平的联合方案；监测耳与前庭毒性，孕妇禁用","renal":"CrCl 10–50：1 g q24–72h 并按血药浓度调整；CrCl <10：1 g q72–96h；血液透析后给 0.5 g","hepatic":"无需调整","interact":"与万古霉素、呋塞米等合用增加耳肾毒性；与肌松药合加重神经肌肉阻滞"},{"name":"复方磺胺甲噁唑","dose":"TMP 160 mg/SMZ 800 mg q12h 口服，联合利福平或氨基糖苷类，疗程 6 周（用于不能使用多西环素者）","note":"儿童与妊娠期的替代方案；监测过敏、血象与肾功能","renal":"CrCl 15–30：减半；CrCl <15：不推荐","hepatic":"重度肝功能不全慎用","interact":"与华法林显著升高 INR；与 ACEI/ARB、保钾利尿剂合用致高钾"},{"name":"头孢曲松","dose":"2 g q12h 静脉，联合多西环素与利福平，疗程 4–6 个月（神经布鲁菌病与心内膜炎）","note":"强化方案，需感染科与神经科/心内科协作","renal":"无需调整；肝肾功能同时受损者减量","hepatic":"重度肝损伴肾损时慎用；胆道淤积注意胆泥","interact":"禁与含钙输液同通路；与华法林合用增强抗凝"}],"nonDrug":["双药联合、足疗程（≥6 周）为原则，不用单药，退热后不提前停药","合并脊柱炎者 MRI 随访与骨科评估，疗程延长至 12 周以上","心内膜炎须瓣膜评估，必要时瓣膜置换，抗感染 4–6 个月","关节积液穿刺减压并送培养；脾或腰大肌脓肿清创引流","职业防护：处理胎盘与流产物时戴手套口罩；实验室按 BSL-3 操作","疫区动物检疫与畜群免疫；乳品巴氏消毒，不饮生奶、不食生肉"],"life":["治疗期禁酒、规律作息；提前告知利福平使尿色变橘红","每 2 周复查血常规、肝肾功能、CRP/ESR","完成疗程后 6–12 个月随访（每 3 个月复查血清学），警惕复发","职业人群规范个人防护与暴露后健康监测；家属感染筛查"]},"prog":"急性期联合规范治疗 6 周治愈率约 90%，复发 <5%–10%（疗程不足与单药显著升高复发）；合并感染性心内膜炎病死率 25%–30%，脊柱炎可遗留慢性疼痛与畸形。慢性布病治疗反应差、易反复，需长期多学科管理。","refs":["布鲁菌病诊疗专家共识（中华医学会感染病学分会，2017）","布鲁菌病诊疗指南（试行，原卫生部，2012）","WHO/FAO/OIE Brucellosis in Humans and Animals 2006","布鲁菌病防控相关技术规范（2020）"]},{"id":"id_lepto","name":"钩端螺旋体病","aka":["Leptospirosis","钩体病","Weil 病","稻田热"],"rank":3,"basic":{"define":"由致病性钩端螺旋体（问号钩体，Leptospira interrogans 等血清群）经皮肤黏膜破损或结膜侵入引起的人畜共患传染病，主要宿主为鼠、猪与犬。临床从自限性发热性感染到黄疸、肾功能衰竭与肺弥漫性出血的 Weil 病不等。","risk":["稻田、池塘、河流、洪涝地段涉水劳作或游泳","鼠类与家畜（猪、牛、犬）接触、屠宰与饲养","洪水、内涝后 1–2 个月（暴发风险显著升高）","农村青壮年男性、雨季户外作业与下水道作业人员","免疫抑制者与酗酒者重症风险更高"],"epi":"我国钩体病以长江以南水稻种植区为主，夏秋季（7–9 月）高峰，与洪涝灾害密切相关；散发病例与局部暴发仍常见。重症 Weil 病病死率 5%–15%，肺弥漫性出血型 >50%。"},"patho":"钩体经皮肤破损、黏膜（口腔、眼结膜）在污染水或土壤中穿入，形成钩体血症（第 1 周），溶血素与内毒素样物质引起全身毛细血管内皮损伤与血管炎；器官定位期（第 2 周）钩体在肝、肾、肺、脑膜与肌肉内增殖，造成黄疸、肾小管间质损害与肾功能衰竭；肺毛细血管破坏导致弥漫性肺泡出血（主要致死原因），肌肉受累表现为腓肠肌压痛与坏死。","dx":{"criteria":["发病前 1–3 周有洪水、污水、稻田或池塘涉水/游泳史，或鼠畜接触史","初起突发高热、寒战、剧烈头痛、全身肌肉酸痛（腓肠肌压痛明显）、结膜充血，可有恶心呕吐与腹泻","第 4–7 天可缓解；部分进入第 2 周加重期：黄疸、少尿/无尿、出血倾向、脑膜刺激征（淋巴细胞性无菌性脑膜炎）","流行季节疫水接触 + 典型症状即可临床诊断并立即治疗","确诊：血（第 1 周最敏感）、尿（第 2 周）或脑脊液 PCR 阳性；MAT 双份血清 4 倍升高或单次 ≥1:400；ELISA IgM 阳性","早期暗视野显微镜阳性率低，不能作为排除依据"],"workup":["血常规：白细胞正常或轻中度升高；血小板减少；尿蛋白、镜下血尿与管型","肝功能：直接胆红素为主升高、ALT/AST 轻中度升高（与黄疸不成比例）、白蛋白下降；肾功能、电解质（低钾）","心肌酶、凝血（DIC 筛查）、血气与乳酸","胸部 CT：双肺磨玻璃/实变（弥漫性肺泡出血），可进展为 ARDS","血/尿/脑脊液 PCR 与双份血清 MAT/ELISA，标本送 CDC 或具条件实验室","心电图与超声心动图（心肌炎）；脑膜刺激征者腰穿","重症评估：黄疸、尿量、氧合、血流动力学与出血征象"],"grading":"临床型：流感伤寒型（轻）、肺出血型、黄疸出血型（Weil 病）、脑膜脑炎型、肾功能衰竭型；病程分钩体血症期、器官损害期与恢复期。"},"ddx":[{"name":"恙虫病（id_scrub）","point":"与本类 id_scrub 的鉴别点：恙虫病有蜱螨叮咬与焦痂、皮疹，黄疸少见，首选多西环素；钩体病有污水/稻田史、腓肠肌压痛，黄疸与肾损害突出，无焦痂，首选青霉素或头孢曲松。"},{"name":"布氏杆菌病（id_brucella）","point":"与本类 id_brucella 的鉴别点：布病有牛羊猪或生乳史，以多汗、波浪热、脊柱炎为主，黄疸与肺出血罕见；钩体病起病更急、肌痛与结膜充血更突出。"},{"name":"病毒性肝炎（急性）","point":"ALT/AST 显著升高（常 >1000 U/L）且与黄疸平行，病毒血清学阳性，无肌痛、结膜充血与疫水接触，肾功能多正常。"},{"name":"流行性出血热","point":"鼠类接触史，发热期→低血压期→少尿期阶梯进展，血小板显著下降与大量蛋白尿，出血热 IgM 阳性；钩体病以黄疸与肌痛为主。"},{"name":"急性肾损伤（其他原因）","point":"无疫水暴露与发热链，多为药物、脱水、心衰或梗阻所致，肾脏超声可发现梗阻。"}],"tx":{"drug":[{"name":"青霉素 G","dose":"轻症 160 万 U q8h 肌注/静滴；重症 240 万–320 万 U q6–8h 静脉；疗程 7–10 天；重症或晚期开始治疗者首剂减为 40 万–80 万 U 以减少赫氏反应","note":"早期使用可缩短病程、降低病死率；首剂后 0.5–8 h 可能出现赫氏反应（寒战高热、血压下降、病情一过性加重），给药前后监测并备好激素与补液","renal":"轻度无需调整；CrCl <30 按说明书减量或延长间隔，监测神经毒性","hepatic":"无需调整；重度肝病监测","interact":"与氨基糖苷类、万古霉素、呋塞米合用增加肾毒性；丙磺舒升高青霉素浓度"},{"name":"头孢曲松","dose":"1 g qd 静脉（重症 2 g qd），疗程 7–10 天","note":"青霉素过敏者替代；脑膜受累时优选","renal":"肾功能不全无需调整；合并肝功能不全时减量","hepatic":"重度肝功能不全伴肾衰竭时减量","interact":"禁与含钙输液同通路；与华法林合用增强抗凝"},{"name":"多西环素","dose":"100 mg q12h 口服或静脉，疗程 7 天","note":"青霉素严重过敏或轻型患者替代","renal":"肾功能不全一般无需调整；重度者监测","hepatic":"肝功能不全者慎用","interact":"抗酸剂、铁剂间隔 2 h；与华法林合用增强抗凝"},{"name":"去甲肾上腺素（重症支持）","dose":"0.05–0.5 μg/kg/min 中心静脉泵入，目标 MAP ≥65 mmHg","note":"用于肺出血型/Weil 病合并脓毒性休克；30 mL/kg 晶体后仍低血压即启动","renal":"无需调整；少尿期严格管理容量","hepatic":"重度肝功能障碍时谨慎滴定","interact":"与单胺氧化酶抑制剂合用显著增强升压效应；外渗可致皮肤坏死"}],"nonDrug":["早发现、早休息、早治疗：疑似即卧床、就地治疗，不宜长途转运","肺弥漫性出血型：绝对卧床、高流量氧疗/无创通气，必要时机械通气；避免大量快速补液，必要时血液净化","Weil 病/AKI：限液并按尿量调整、纠正电解质紊乱，必要时 CRRT，黄疸显著者保肝","脑膜脑炎：控制惊厥与颅压，必要时腰穿降颅压","DIC 与出血：按凝血指标补充血浆、血小板与冷沉淀","灭鼠、管好家畜与粪污，避免疫水涉水游泳；流行区重点人群按程序接种钩体疫苗","按乙类传染病报告疾控部门；洪涝后开展环境消毒与暴露者健康监测"],"life":["急性期卧床、禁酒，肺出血期避免任何增加心脏负荷的活动","恢复期 2–4 周复查肝功能、肾功能与尿常规；脑膜脑炎者随访 1–3 个月","后期眼葡萄膜炎（多在 4–6 个月）需眼科诊治","疫区与洪涝后作业者做好个人防护（防水靴、手套）与暴露后症状监测","职业暴露人群健康告知与疫苗接种"]},"prog":"轻症 1–2 周内自限恢复；重症 Weil 病病死率 5%–15%，以急性肾衰竭与心力衰竭为主要死因；肺弥漫性出血型病死率可达 50% 以上，多见于病程第 4–7 天。发病早期即用青霉素或头孢曲松可显著降低病死率，延误 >5 天预后明显变差。","refs":["中国钩端螺旋体病诊疗与防控专家共识（中华医学会感染病学分会，2020）","钩端螺旋体病诊断标准（WS 290-2008）","WHO Human Leptospirosis Guidance 2003","中国洪涝灾害卫生防病技术指南（国家卫健委，2021）"]}]}]},"neuro":{"categories":[{"id":"stroke","name":"脑血管病","rank":1,"summary":"急性脑梗死强调“时间就是大脑”：静脉溶栓 4.5 h 内、大血管闭塞机械取栓 6–24 h（影像筛选）；脑出血核心是血压平稳降至 130–140 mmHg 与防治血肿扩大；SAH 尽早病因治疗与防再出血。","compare":[{"diseaseId":"stk_ischemic","dx":"突发局灶性神经功能缺损 + CT 无出血，CT/MRI 见责任血管供血区梗死；起病时间明确者评估溶栓与取栓","key":"起病 4.5 h 内 rt-PA/替奈普酶静脉溶栓，大血管闭塞 24 h 内经影像筛选取栓"},{"diseaseId":"stk_ich","dx":"突发偏瘫/失语/意识障碍，头颅 CT 见高密度血肿（基底节、丘脑、脑叶、脑干、小脑）","key":"CT 高密度血肿，禁用溶栓抗栓；血压降至 130–140 mmHg"},{"diseaseId":"stk_sah","dx":"突发“雷击样”剧烈头痛、颈强直、CT 示基底池高密度，腰穿均匀血性脑脊液或黄变","key":"雷击样头痛 + 脑膜刺激征，需 CTA 找动脉瘤，尽早夹闭/介入栓塞"},{"diseaseId":"stk_tia","dx":"短暂性局灶神经功能缺损，通常 <1 h，无梗死灶（DWI 阴性）","key":"症状完全恢复、影像无急性梗死；需按 ABCD² 评分紧急二级预防"}],"diseases":[{"id":"stk_ischemic","name":"急性脑梗死","aka":["急性缺血性卒中","AIS","脑梗死","缺血性脑卒中"],"rank":1,"basic":{"define":"由脑动脉闭塞导致相应供血区脑组织缺血坏死的急性局灶性神经功能缺损，占全部卒中的 70%–80%；按 TOAST 分为大动脉粥样硬化型、心源性栓塞型、小血管闭塞型、其他明确病因型与不明原因型。","risk":["高血压（首要危险因素）","房颤等心源性栓塞（CHA₂DS₂-VASc 评分）","糖尿病、血脂异常","吸烟、饮酒","颈动脉粥样硬化斑块/狭窄","既往 TIA 或卒中史"],"epi":"我国卒中年新发病例约 240 万–300 万，缺血性卒中占 70% 以上；急性期病死率约 5%–10%，70% 的存活者遗留功能障碍。"},"patho":"动脉粥样硬化血栓形成或心源性栓子堵塞脑动脉，核心梗死区血流 <10 mL/100g/min 迅速不可逆坏死，周围“半暗带”血流 10–20 mL/100g/min 仅功能抑制、4.5 h 内可挽救。缺血后兴奋性氨基酸毒性、钙超载、炎症与血脑屏障破坏扩大损伤；再灌注可致出血转化。","dx":{"criteria":["突发局灶性神经功能缺损（偏瘫、偏身感觉障碍、失语、视野缺损、共济失调）或全面神经功能缺损，持续 >24 h 或影像见梗死灶","急诊 NIHSS 评分评估严重程度；发病时间（最后正常时间）明确至关重要","头颅 CT 排除出血（可早期见大脑中动脉高密度征、岛带征）","DWI 高信号、ADC 低信号确诊急性梗死；CTA/MRA 明确大血管闭塞","溶栓时间窗：起病 ≤4.5 h（阿替普酶）；替奈普酶 ≤4.5 h（0.25 mg/kg）","取栓时间窗：前循环大血管闭塞 6 h 内直接取栓；6–24 h 需 DAWN/DEFUSE-3 等影像筛选（梗死核心 <70 mL、不匹配比 ≥1.8）"],"workup":["急诊头颅 CT（平扫）+ 头颅 CTA（大血管评估）","血糖、凝血（INR、APTT）、血常规、血小板、肾功能、电解质、心肌酶","心电图、心脏超声（排查心源性栓塞，尤其房颤）","NIHSS、mRS 基线评分；吞咽功能筛查","头颅 MRI（DWI）/CTA/灌注成像（6–24 h 取栓筛选）","颈动脉超声、经颅多普勒；病因分型（TOAST）"],"grading":"NIHSS（0–42，越高越重）；TOAST 病因分型；ASPECTS（CT 早期缺血改变 0–10 分）；mRS（0–6）预后评分。"},"ddx":[{"name":"脑出血（stk_ich）","point":"与本类 stk_ich 的鉴别点：ICH 于 CT 见高密度血肿、血压常明显升高、头痛呕吐与意识障碍更突出；缺血性卒中 CT 常无出血，DWI 高信号。"},{"name":"蛛网膜下腔出血（stk_sah）","point":"与本类 stk_sah 的鉴别点：SAH 为雷击样头痛+脑膜刺激征，CT 见基底池高密度，多为动脉瘤破裂；缺血性卒中少有剧烈头痛。"},{"name":"短暂性脑缺血发作（stk_tia）","point":"与本类 stk_tia 的鉴别点：TIA 症状于 24 h 内（通常 <1 h）完全缓解、DWI 无急性梗死；脑梗死症状持续或影像见梗死灶。"},{"name":"低血糖性偏瘫","point":"血糖 <3.9 mmol/L 可模拟卒中，快速血糖测定并静脉补充葡萄糖后迅速恢复。"},{"name":"癫痫后 Todd 麻痹","point":"局灶抽搐后短暂肢体无力，可自行恢复，脑电图见痫样放电，影像无新发梗死。"}],"tx":{"drug":[{"name":"阿替普酶（rt-PA）静脉溶栓","dose":"0.9 mg/kg（最大 90 mg）：10% 于 1 min 内静脉推注，其余 60 min 静滴完毕；时间窗：起病 4.5 h 内","note":"溶栓前血压须 ≤185/110 mmHg；排除出血倾向、近期手术、颅内出血史等禁忌；溶栓后 24 h 内禁用抗栓、复查 CT 后再启动抗血小板","renal":"严重肾功能不全（eGFR <30）慎用","hepatic":"严重肝病、凝血障碍禁用","interact":"与抗凝、抗血小板药合用时停药 24 h；禁止与其他溶栓药联用"},{"name":"替奈普酶（TNK）静脉溶栓","dose":"0.25 mg/kg（最大 25 mg），单次静脉推注 5–10 s；时间窗 4.5 h 内","note":"与阿替普酶疗效相当或非劣，单次推注更便捷（2023–2024 循证更新）","renal":"严重肾功能不全慎用","hepatic":"严重肝病禁用","interact":"同阿替普酶"},{"name":"阿司匹林","dose":"未溶栓者 150–300 mg 顿服（起病后尽早）；溶栓者于溶栓 24 h 后复查 CT 无出血后 100 mg qd","note":"急性期基础抗血小板；非心源性栓塞患者长期二级预防","renal":"无需调整","hepatic":"活动性消化道出血禁用","interact":"与抗凝药合用增加出血；溶栓 24 h 内禁用"},{"name":"氯吡格雷","dose":"轻型卒中（NIHSS ≤3）或高危 TIA 者：氯吡格雷 300 mg 负荷后 75 mg qd，联合阿司匹林 21 天（POINT/CHANCE 方案）","note":"24 h 内启动双联抗血小板可降低早期复发；出血高危者单药","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"奥美拉唑降低疗效，改用泮托拉唑"},{"name":"阿托伐他汀","dose":"40–80 mg qn（强化降脂），目标 LDL-C <1.8 mmol/L 且降幅 ≥50%","note":"动脉粥样硬化型卒中无论基线血脂均应强化他汀","renal":"无需调整","hepatic":"活动性肝病禁用；ALT >3 倍上限停药","interact":"与贝特类、环孢素合用增加肌病风险"},{"name":"依达拉奉右莰醇","dose":"15 mL（含依达拉奉 30 mg/右莰醇 7.5 mg）静脉滴注 bid，疗程 14 天","note":"国内获批的神经保护剂，用于改善急性缺血性卒中功能结局（TASTE 研究）","renal":"严重肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"遵说明书"},{"name":"甘露醇（降颅压）","dose":"20% 甘露醇 125–250 mL 静脉快速滴注 q6–8h，根据颅高压表现调整","note":"用于大面积梗死伴脑水肿、占位效应；监测肾功与电解质","renal":"eGFR <30 慎用或减量","hepatic":"遵说明书","interact":"与肾毒性药物合用加重肾损害"},{"name":"丁苯酞","dose":"0.2 g 口服 tid 或 25 mg 静脉滴注 bid，疗程 14 天","note":"改善侧支循环与微循环，国内常用（证据等级中等）","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"遵说明书"}],"nonDrug":["机械取栓：前循环大血管（ICA、M1、M2）闭塞 6 h 内直接取栓；6–24 h 经 CTP/MRI 筛选（DAWN/DEFUSE-3 标准）；后循环闭塞（基底动脉）可放宽至 24 h","大面积梗死（恶性大脑中动脉综合征）伴脑疝征象：去骨瓣减压术（通常起病 48 h 内）","卒中单元管理：气道、吞咽、体温、血糖、血压（未溶栓者 <220/120 mmHg 可不急于降压；溶栓后 <185/110 mmHg）","静脉溶栓后 24 h 复查 CT，评估出血转化","心源性栓塞者抗凝启动时机（房颤一般 4–14 天，视梗死面积与出血风险）","颈动脉重度狭窄（>70%）且适合者可考虑颈动脉内膜剥脱/支架（发病 2 周内）"],"life":["早期康复（24–48 h 内病情稳定即开始），预防深静脉血栓、肺炎、压疮","二级预防：抗血小板/抗凝、他汀、降压（目标 <130/80 mmHg）、控糖、戒烟限酒","房颤患者长期口服抗凝（首选新型口服抗凝药），不推荐抗血小板替代","定期随访 NIHSS/mRS，筛查睡眠呼吸暂停与抑郁"]},"prog":"静脉溶栓可使良好预后（mRS 0–2）比例提高约 10%–13%，需 NNT 约 7–14；取栓使大血管闭塞患者 90 天良好预后率由约 20% 提升至 45%–60%。卒中复发 1 年约 10%–15%，控制危险因素是关键。","refs":["中国急性缺血性脑卒中诊治指南（2023，中华医学会神经病学分会）","中国缺血性卒中和 TIA 二级预防诊疗指南（2022）","AHA/ASA 急性缺血性卒中早期管理指南（2019，2023 更新）","中国脑卒中防治指导规范（2021 年版）"]},{"id":"stk_ich","name":"脑出血","aka":["自发性脑出血","ICH","脑溢血","Intracerebral Hemorrhage"],"rank":2,"basic":{"define":"非外伤性脑实质内血管破裂引起的出血，最常见于高血压性基底节、丘脑、脑干、小脑出血，占全部卒中的 10%–15%，但致死致残率最高。","risk":["高血压（最重要）","脑淀粉样血管病（老年脑叶出血）","抗凝/抗血小板药物使用","脑血管畸形、动脉瘤","吸烟、酗酒、肝病、血小板减少"],"epi":"我国 ICH 约占卒中的 20%–30%（高于欧美），1 个月病死率 30%–40%，约 1/3 患者 24 h 内血肿扩大。"},"patho":"长期高血压致豆纹动脉等穿支小动脉脂肪透明变性，破裂后形成血肿；血肿机械压迫与继发凝血级联激活、炎症、水肿扩大损伤。血肿扩大是早期恶化与预后不良的主要决定因素。","dx":{"criteria":["突发局灶神经功能缺损伴头痛、呕吐、意识障碍、血压显著升高","头颅 CT 见高密度血肿（按部位分基底节、丘脑、脑叶、脑干、小脑、脑室）","CTA“点征”（spot sign）提示血肿扩大风险","按 ICH 评分（GCS、年龄、血肿体积、脑室出血、幕下出血）评估预后","明确潜在病因：高血压、抗凝、CAA、血管畸形（年轻患者需 CTA/DSA）"],"workup":["急诊头颅 CT，必要时 CTA/CTV（排除大血管病因，识别点征）","血常规、凝血、肝肾功能、血糖、电解质","抗凝药物使用史（华法林测 INR；新型抗凝药考虑特定拮抗剂）","头颅 MRI（亚急性期、老年脑叶出血评估 CAA）","病情恶化时复查 CT（24 h 内血肿扩大）","年轻患者筛查脑血管畸形、烟雾病"],"grading":"ICH 评分（0–6）：GCS 3–4（2 分）、5–12（1 分）、13–15（0 分）；年龄 ≥80 岁（1 分）；血肿体积 ≥30 cm³（1 分）；脑室出血（1 分）；幕下出血（1 分）。0–6 分 30 天死亡率由 0% 升至约 97%。"},"ddx":[{"name":"急性脑梗死（stk_ischemic）","point":"与本类 stk_ischemic 的鉴别点：ICH 于 CT 见高密度血肿、血压更高、头痛呕吐更突出；缺血性卒中 CT 平扫无高密度，DWI 高信号。"},{"name":"蛛网膜下腔出血（stk_sah）","point":"与本类 stk_sah 的鉴别点：SAH 以雷击样头痛与脑膜刺激征为主，出血位于脑池/脑沟；ICH 为脑实质内血肿。"},{"name":"短暂性脑缺血发作（stk_tia）","point":"与本类 stk_tia 的鉴别点：TIA 症状完全恢复、CT 无血肿；ICH 症状持续并伴颅高压表现。"},{"name":"脑肿瘤卒中/转移瘤出血","point":"周边环形强化、周围明显水肿、无高血压病史，增强 MRI 有助鉴别。"},{"name":"淀粉样脑血管病（CAA）","point":"老年、脑叶（非基底节）出血、多发微出血，SWI 见皮质表面铁沉积。"}],"tx":{"drug":[{"name":"乌拉地尔/尼卡地平（降压）","dose":"乌拉地尔 12.5 mg iv 缓推后 5–40 mg/h 泵入；尼卡地平 5 mg/h 起，每 5–15 min 增 2.5 mg/h；收缩压 >220 mmHg 者静脉降压；150–220 mmHg 者可平稳降至 140 mmHg；目标 130–140 mmHg，避免降幅 >90 mmHg/小时","note":"早期（发病 6 h 内）强化降压至 130–140 mmHg 可减少血肿扩大（INTERACT2/ATACH-2）；避免血压波动","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"与其他降压药联用注意低血压"},{"name":"甘露醇/高渗盐水（降颅压）","dose":"20% 甘露醇 125–250 mL iv q6–8h（注意渗透压）；或 23.4% 高渗盐水 30–60 mL 中心静脉","note":"用于占位效应与脑疝征象；监测肾功能与血钠","renal":"eGFR <30 慎用甘露醇","hepatic":"遵说明书","interact":"遵说明书"},{"name":"维生素 K₁ + 凝血酶原复合物（华法林相关 ICH）","dose":"维生素 K₁ 5–10 mg iv；凝血酶原复合物（PCC）25–50 U/kg 静脉（按 INR 调整）","note":"华法林相关 ICH 首选 PCC+维生素 K₁，6 h 内纠正 INR","renal":"遵说明书","hepatic":"肝病相关凝血障碍者谨慎","interact":"遵说明书"},{"name":"伊达思珠单抗（Idarucizumab，达比加群拮抗）","dose":"5 g iv（2.5 g ×2 次，间隔 ≤15 min）","note":"达比加群相关 ICH 的特异性拮抗剂","renal":"严重肾功能不全时作用可能延迟","hepatic":"遵说明书","interact":"遵说明书"},{"name":"氨甲环酸","dose":"1 g iv（10 min 内）后续 1 g 8 h 内静滴；发病 8 h 内（TRANEXAMIC ACID 研究）可考虑","note":"用于血肿扩大高危或早期就诊患者，需评价血栓风险","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"与抗凝/抗凝逆转药合用需评价"},{"name":"抗癫痫药（预防性，不常规推荐）","dose":"癫痫发作时：左乙拉西坦 1000 mg iv 负荷，后 500–1000 mg bid；丙戊酸 15–20 mg/kg iv 负荷","note":"仅用于临床癫痫发作或脑电痫样放电，不推荐常规预防","renal":"左乙拉西坦 eGFR <60 减量","hepatic":"丙戊酸肝毒性，肝病慎用","interact":"丙戊酸与拉莫三嗪联用需减量"}],"nonDrug":["停用所有抗栓药物，纠正凝血障碍与血小板减少（血小板 <50×10⁹/L 时输注）","外科手术指征：小脑出血 >3 cm 或伴脑干受压/脑积水；幕上血肿 >30 mL、GCS 下降、浅表脑叶出血可考虑开颅或微创清除（ENRICH/MISTIE 证据）","脑室出血/脑积水：脑室外引流","头位抬高 30°，避免颈部受压，防止颅内压升高","避免常规使用糖皮质激素与预防性抗惊厥药","抗凝重启：权衡再出血与血栓风险，通常 4–8 周后评估"],"life":["急性期卧床，误吸预防与吞咽评估；营养支持","长期降压目标 <130/80 mmHg；控制血糖、戒烟限酒","康复训练（运动、言语、吞咽）尽早开始","定期复查血肿吸收与脑积水"]},"prog":"30 天病死率约 30%–40%，血肿扩大、初始 GCS 与出血部位是主要预后因素；存活者约 50% 遗留中重度功能障碍。复发率约 2%–3%/年，控制血压可显著降低。","refs":["中国脑出血诊治指南（2019，中华医学会神经病学分会）","AHA/ASA 自发性脑出血管理指南（2022）","中国急性脑梗死与脑出血诊疗规范（2023）","INTERACT2/ATACH-2 研究（2013/2016）"]},{"id":"stk_sah","name":"蛛网膜下腔出血","aka":["SAH","Subarachnoid Hemorrhage","原发性蛛网膜下腔出血"],"rank":3,"basic":{"define":"脑底部或脑表面血管破裂，血液流入蛛网膜下腔，最常见的自发性病因是颅内动脉瘤破裂（约 80%），其次为脑血管畸形与中脑周围非动脉瘤性出血。","risk":["颅内动脉瘤（女性、吸烟、高血压、多囊肾、家族史）","吸烟、酗酒","高血压","结缔组织病（Ehlers-Danlos、马凡）"],"epi":"自发性 SAH 年发病率约 6–10/10 万，占卒中的 5%；中位发病年龄约 55 岁，女性多于男性；病死率约 30%，10%–15% 到达医院前死亡。"},"patho":"动脉瘤破裂后局部高压血液冲入蛛网膜下腔，引起颅内压骤升与脑血流下降（意识障碍），随后血液分解产物刺激脑膜与脑血管，导致脑血管痉挛（3–14 天高峰）、炎症与神经功能损伤；再出血（24 h 内高峰）与脑积水、低钠血症为主要并发症。","dx":{"criteria":["突发“一生中最剧烈”的雷击样头痛（数秒内达高峰），常伴恶心呕吐、颈强直、畏光","可有意识丧失、局灶神经功能缺损（如动眼神经麻痹提示后交通动脉瘤）、眼底玻璃体下出血（Terson 综合征）","头颅 CT 见基底池、外侧裂、脑沟高密度（发病 6 h 内敏感性接近 100%，24 h 后下降）","CT 阴性或发病 >6 h 而临床高度怀疑：腰穿见均匀血性脑脊液或黄变（分光光度法）","CTA/DSA 发现责任动脉瘤；CTA 阴性而临床高度怀疑者需 DSA","Hunt-Hess 分级或 WFNS 分级评估严重程度，改良 Fisher 分级评估血管痉挛风险"],"workup":["急诊头颅 CT（平扫）+ CTA","腰穿（CT 阴性时，≥6 h 后行）查红细胞与黄变","DSA（金标准，明确动脉瘤的位置、大小、形态）","血常规、电解质（低钠）、血糖、凝血、心电图（心肌肌钙蛋白可升高）","脑脊液检查：排除感染（发热时）","转诊至有神经介入/神经外科中心"],"grading":"Hunt-Hess：Ⅰ 无症状/轻度头痛；Ⅱ 中度头痛、颈强直、颅神经麻痹；Ⅲ 意识模糊、轻度局灶缺损；Ⅳ 昏睡、偏瘫；Ⅴ 深昏迷、去大脑强直。改良 Fisher 分级用于评估血管痉挛风险。"},"ddx":[{"name":"脑出血（stk_ich）","point":"与本类 stk_ich 的鉴别点：ICH 为脑实质血肿、局灶体征突出；SAH 出血在脑池与脑沟、以雷击样头痛+脑膜刺激征为主。"},{"name":"急性脑梗死（stk_ischemic）","point":"与本类 stk_ischemic 的鉴别点：SAH 几乎均有剧烈头痛，CT 见蛛网膜下腔高密度；缺血性卒中头痛少见、CT 无出血。"},{"name":"短暂性脑缺血发作（stk_tia）","point":"与本类 stk_tia 的鉴别点：TIA 无头痛与脑膜刺激征，腰穿正常；SAH 脑脊液见红细胞或黄变。"},{"name":"原发性雷击样头痛","point":"剧烈头痛但 CT、腰穿、CTA 均正常，无神经功能缺损；仍须短期复查影像排除。"},{"name":"脑膜炎","point":"发热、脑膜刺激征，脑脊液白细胞升高；SAH 以红细胞为主，早期可伴发热需鉴别。"}],"tx":{"drug":[{"name":"尼莫地平（预防血管痉挛）","dose":"60 mg 口服 q4h（或鼻饲），疗程 21 天；低血压者减至 30 mg q4h","note":"仅证实可改善神经结局，并非直接解除血管痉挛；注意血压","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与 CYP3A4 抑制剂（唑类、大环内酯）升高浓度；与降压药合用加重低血压"},{"name":"氨甲环酸（早期短程）","dose":"1 g iv（10 min）后 1 g 8 h 内静滴，持续至动脉瘤处理（通常 <24–48 h）","note":"降低早期再出血风险（ULTRA 研究），不宜长期使用（血栓风险）","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"与抗纤溶药合用增加血栓风险"},{"name":"尼卡地平/拉贝洛尔（控制血压）","dose":"尼卡地平 5 mg/h 起静脉泵入；拉贝洛尔 10–20 mg iv 次，目标收缩压 <160 mmHg（未处理动脉瘤者）","note":"处理动脉瘤前控制血压以降低再出血风险；避免过度低血压影响灌注","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"遵说明书"},{"name":"甘露醇（颅高压）","dose":"20% 甘露醇 125–250 mL iv q6–8h，根据 ICP/神经功能调整","note":"用于脑水肿、颅高压；脑室外引流同步评估","renal":"eGFR <30 慎用","hepatic":"遵说明书","interact":"遵说明书"},{"name":"高渗盐水（低钠血症矫正）","dose":"3% 高渗盐水 100–250 mL 静脉或按血钠计算，目标血钠 135–140 mmol/L，矫正速度 <8–10 mmol/L·d","note":"SAH 低钠多为脑耗盐综合征，需鉴别 SIADH；纠正过快致渗透性脱髓鞘","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"镇静镇痛（芬太尼/丙泊酚）","dose":"芬太尼 25–100 μg iv 按需；丙泊酚 1–4 mg/kg/h 靶控镇静","note":"控制疼痛与躁动，降低颅内压与血压波动","renal":"遵说明书","hepatic":"丙泊酚长期输注注意丙泊酚输注综合征","interact":"与镇静药合用加重呼吸抑制"}],"nonDrug":["尽早病因治疗：介入栓塞（弹簧圈/支架辅助）或开颅夹闭，通常在发病 24–72 h 内（越早越好）","脑室外引流：急性脑积水伴意识障碍者","预防再出血：卧床、镇静、避免便秘与用力","监测癫痫、低钠、脑血管痉挛（经颅多普勒/CTA）","康复与随访；动脉瘤筛査一级亲属"],"life":["急性期卧床，避免用力排便（可用乳果糖）","戒烟、控制血压 <140/90 mmHg；定期随访动脉瘤（未处理者）","情绪支持与康复；认知功能评估"]},"prog":"30 天病死率约 30%，再出血病死率可达 60%–80%；早期手术与尼莫地平可改善预后。存活者约 50% 遗留认知功能障碍。","refs":["中国蛛网膜下腔出血诊治指南（2019，中华医学会神经病学分会）","AHA/ASA 动脉瘤性蛛网膜下腔出血管理指南（2023）","中国脑血管病一级预防指导规范（2021）","ULTRA 研究（2021）"]},{"id":"stk_tia","name":"短暂性脑缺血发作","aka":["TIA","Transient Ischemic Attack","一过性脑缺血发作"],"rank":4,"basic":{"define":"由脑、脊髓或视网膜局灶性缺血所致的短暂性神经功能障碍，通常持续数分钟至 1 h，无急性脑梗死证据（DWI 阴性），组织学定义取代了旧的“24 h 恢复”定义。","risk":["高血压、糖尿病、房颤","颈动脉狭窄/斑块","吸烟、高脂血症","既往卒中或 TIA","同型半胱氨酸升高"],"epi":"TIA 发病率约为卒中的 1/3–1/2，我国每年新发约 100 万；TIA 后 90 天内约 10%–15% 发生卒中，其中一半在 48 h 内。"},"patho":"与脑梗死相同：动脉粥样硬化斑块破裂释放栓子（颈动脉系统或椎基底动脉），或心源性微栓子短暂阻塞后自溶，造成可逆的局灶缺血。TIA 是卒中的高危预警信号。","dx":{"criteria":["突发局灶性神经功能缺损（单眼黑矇、偏瘫、失语、偏身感觉障碍等），症状于 24 h 内完全缓解（多数 <1 h）","头颅 MRI DWI 无弥散受限（无急性梗死灶）；若有梗死灶则诊断为脑梗死","排除其他短暂性神经症状（低血糖、偏头痛先兆、癫痫 Todd 麻痹等）","评估病因：颈动脉超声/CTA 寻找动脉粥样硬化斑块或狭窄；心电图/动态心电图排查房颤","ABCD² 评分 ≥4 为高危（年龄 ≥60 岁 1 分、血压 ≥140/90 1 分、单侧无力 2 分、语言障碍 1 分、症状持续 ≥60 min 2 分、糖尿病 1 分）","高危 TIA（ABCD² ≥4 或症状持续 >10 min）应在 24–48 h 内完成评估"],"workup":["NIHSS 与 ABCD² 评分","头颅 MRI（DWI）± 头颅 CT","颈动脉超声/CTA/MRA 评估狭窄","心电图、24–72 h 动态心电图（房颤）","超声心动图（左房血栓、瓣膜病）","血糖、血脂、HbA1c、同型半胱氨酸、凝血","TOAST 病因分型"],"grading":"ABCD²（0–7）预测短期卒中风险；ESRS 评分用于长期风险。"},"ddx":[{"name":"急性脑梗死（stk_ischemic）","point":"与本类 stk_ischemic 的鉴别点：脑梗死症状持续或 DWI 见弥散受限；TIA 症状完全恢复且 DWI 阴性。"},{"name":"脑出血（stk_ich）","point":"与本类 stk_ich 的鉴别点：ICH 有头痛呕吐、CT 见血肿，症状不会完全恢复；TIA 无出血。"},{"name":"蛛网膜下腔出血（stk_sah）","point":"与本类 stk_sah 的鉴别点：SAH 为雷击样头痛、脑膜刺激征，非仅局灶缺损。"},{"name":"低血糖","point":"交感兴奋、意识模糊、偏瘫样表现，血糖 <3.9 mmol/L，补糖后迅速恢复。"},{"name":"偏头痛先兆","point":"视觉闪烁、麻木等“阳性”症状，逐渐演变（>5 min）并伴头痛；TIA 多为“阴性”症状（无力、失语）。"}],"tx":{"drug":[{"name":"阿司匹林 + 氯吡格雷（急性期双抗）","dose":"阿司匹林 100 mg qd + 氯吡格雷 75 mg qd（首日氯吡格雷 300 mg 负荷），共 21 天；之后改为单药长期","note":"高危 TIA（ABCD² ≥4）24 h 内启动双抗可显著降低 90 天卒中风险（CHANCE/POINT）","renal":"无需调整","hepatic":"活动性出血禁用","interact":"奥美拉唑减低氯吡格雷疗效；与抗凝合用增加出血"},{"name":"阿托伐他汀/瑞舒伐他汀","dose":"阿托伐他汀 40–80 mg qn；目标 LDL-C <1.8 mmol/L 且降幅 ≥50%","note":"所有动脉粥样硬化型 TIA 均需强化他汀","renal":"瑞舒伐他汀 eGFR <30 减量","hepatic":"活动性肝病禁用","interact":"贝特类增加肌病风险"},{"name":"新型口服抗凝药（心源性栓塞）","dose":"利伐沙班 20 mg qd（CrCl 15–49 为 15 mg qd）；达比加群 150 mg bid（≥80 岁或高出血风险 110 mg bid）","note":"房颤相关 TIA 患者首选，需评估 CHA₂DS₂-VASc 与 HAS-BLED","renal":"CrCl <15 禁用；按 CrCl 调整","hepatic":"Child-Pugh B/C 慎用","interact":"与 P-gp/CYP3A4 抑制剂（维拉帕米、酮康唑）增加出血"},{"name":"降压治疗","dose":"氨氯地平 5 mg qd 起始，或培哚普利 4 mg qd；目标 <130/80 mmHg","note":"高血压是 TIA 最重要可控因素","renal":"按 eGFR 调整","hepatic":"重度肝功能不全慎用","interact":"ACEI 与保钾利尿剂高钾风险"}],"nonDrug":["颈动脉狭窄 >70%（症状性）者 2 周内行颈动脉内膜剥脱术（CEA）或支架（CAS）","心源性栓塞（房颤）者长期抗凝，不推荐抗血小板替代","住院或 24–48 h 内急诊评估，避免门诊延误","戒烟、控制体重、筛查睡眠呼吸暂停"],"life":["低盐低脂饮食、规律运动、戒烟限酒","坚持二级预防药物，不可自行停药","出现新症状立即就诊（FAST 识别）"]},"prog":"TIA 后 90 天卒中风险约 10%–15%，及时启动抗血小板+他汀+降压可降低约 80%；颈动脉狭窄干预可显著降低同侧卒中。","refs":["中国缺血性卒中和短暂性脑缺血发作二级预防指南（2022）","中国短暂性脑缺血发作临床诊疗指南（2022）","AHA/ASA TIA 管理指南（2021）","CHANCE/POINT 研究（2013/2018）"]}]},{"id":"epilepsy","name":"癫痫","rank":2,"summary":"以发作类型选择抗癫痫药物，单药首选、足量足疗程；全面强直阵挛发作与癫痫持续状态需按“ABC+首剂苯二氮䓬+二线抗癫痫药负荷”流程处理，持续状态 >30 min 病死率显著升高。","compare":[{"diseaseId":"epi_general","dx":"发作性意识丧失、双眼上翻、四肢强直-阵挛、口吐白沫、尿失禁，发作后嗜睡/朦胧，EEG 见全面性棘慢波","key":"发作持续 1–2 min 自行终止，发作后状态可恢复；首次发作需排除诱因"},{"diseaseId":"epi_se","dx":"全面性发作持续 ≥5 min，或两次发作间意识未恢复；或非惊厥性持续状态 EEG 见持续痫样放电 ≥30 min","key":"≥5 min 即视为持续状态，需立即苯二氮䓬+二线药负荷"}],"diseases":[{"id":"epi_general","name":"全面强直阵挛发作","aka":["GTCS","大发作","Generalized Tonic-Clonic Seizure"],"rank":1,"basic":{"define":"全面性发作的一种，表现为意识丧失、四肢强直、阵挛、可伴尿失禁与舌咬伤，发作后进入朦胧状态；可为特发性全面性癫痫或局灶起源继发全面化。","risk":["遗传/家族史、婴儿期热性惊厥","脑外伤、卒中、脑肿瘤、中枢感染","睡眠剥夺、饮酒、闪光刺激","不规律服抗癫痫药或突然停药","代谢紊乱（低血糖、低钠）"],"epi":"我国癫痫患病率约 7‰，活动性癫痫约 4.6‰；全面性发作占 30%–40%。多数患者经规范药物治疗可控制发作。"},"patho":"大脑神经元异常同步放电，涉及丘脑-皮质环路；离子通道（钠、钾、钙通道）功能异常或结构性病变（皮质发育不良、肿瘤、外伤瘢痕）导致兴奋-抑制失衡；抑制性 GABA 能网络减弱是药物治疗的基础。","dx":{"criteria":["发作性意识丧失、双眼上翻、四肢强直-阵挛，常伴舌咬伤、尿失禁，发作 1–2 分钟后自行终止","发作后朦胧/嗜睡、肌痛与头痛；家属或目击者描述对诊断极为重要","EEG：发作间期见全面性棘慢波（3 Hz 典型失神）或局灶痫样放电","头颅 MRI 排除结构性病因（尤其成人首次发作）","首次发作需排除低血糖、低钠、感染、中毒、心源性晕厥","诊断癫痫需 ≥2 次非诱发性发作（间隔 >24 h），或一次发作 + 复发风险 ≥60%"],"workup":["详细病史（发作前、发作时、发作后）与目击者描述","常规/睡眠 EEG（必要时 24 h 视频脑电）","头颅 MRI（3T，癫痫序列）","血糖、电解质、肝肾功能、血常规","心电图（排除长 QT 与晕厥）","育龄女性评估妊娠计划与叶酸"],"grading":"ILAE 2017 发作分类：局灶性（意识保留/受损）、全面性（强直阵挛、失神、肌阵挛、失张力）、起源不明；综合全面性癫痫需与局灶继发全面化鉴别。"},"ddx":[{"name":"癫痫持续状态（epi_se）","point":"与本类 epi_se 的鉴别点：GTCS 单次发作 1–2 min 自行终止；持续 ≥5 min 或发作间意识未恢复即进入持续状态，需立即急救。"},{"name":"心源性晕厥","point":"发作前有先兆（心悸、胸闷）、面色苍白、无舌咬伤与尿失禁，发作后意识迅速恢复，心电图/动态心电图有异常。"},{"name":"低血糖发作","point":"饥饿、出汗、心悸，血糖 <3.9 mmol/L，补糖后迅速缓解，EEG 无痫样放电。"},{"name":"非癫痫性心因性发作","point":"发作形式多变、闭眼、骨盆挺伸、无明显发作后状态，视频脑电无相应放电，心理评估有意义。"}],"tx":{"drug":[{"name":"丙戊酸钠","dose":"起始 10–15 mg/kg/d 分 1–2 次，每 1–2 周加量至 20–30 mg/kg/d（成人常用 0.5 g bid，最大 1.0–1.5 g/d）；血药浓度 50–100 μg/mL","note":"全面性发作一线；育龄女性禁用（致畸风险高）","renal":"无需调整；严重肾功能不全减量","hepatic":"肝功能不全禁用/减量；监测转氨酶","interact":"与拉莫三嗪联用增加拉莫三嗪浓度并致皮疹；与卡马西平、苯妥英互相影响浓度"},{"name":"左乙拉西坦","dose":"成人起始 500 mg bid，每 2 周加 500 mg，目标 1.5–3.0 g/d（最大 3.0 g/d）；儿童 20 mg/kg/d 起始，目标 40–60 mg/kg/d","note":"广谱、药物相互作用少，育龄女性相对安全","renal":"按 eGFR 调整：CrCl 50–80：2 g/d；30–50：1–2 g/d；<30：0.5–1 g/d","hepatic":"严重肝功能不全需减量","interact":"与其他药物相互作用少；注意嗜睡、行为异常"},{"name":"拉莫三嗪","dose":"单药起始 25 mg qd×2 周，后 50 mg qd×2 周，逐步增至 100–200 mg/d 维持","note":"可用的育龄女性替代；缓慢加量防重症皮疹（SJS）","renal":"无需调整；透析后需补量","hepatic":"肝功能不全减量","interact":"与丙戊酸联用时起始剂量减半并缓慢加量；卡马西平、苯妥英降低浓度"},{"name":"奥卡西平","dose":"起始 150 mg bid，每 3–7 天加 150 mg，目标 600–1200 mg/d（部分可至 2400 mg/d）","note":"可用于局灶继发全面化；注意低钠血症","renal":"CrCl <30 起始 150 mg qd 后加量","hepatic":"重度肝功能不全慎用","interact":"加快口服避孕药代谢；与卡马西平、苯妥英相互影响"},{"name":"托吡酯","dose":"起始 25 mg qd，每周加 25 mg，目标 100–200 mg/d 分 2 次","note":"广谱；注意认知减退、肾结石","renal":"按 CrCl 调整","hepatic":"重度肝功能不全慎用","interact":"与碳酸酐酶抑制剂合用增加结石风险"}],"nonDrug":["首次发作后评估复发风险，>60% 者（MRI 结构病变、EEG 痫样放电、夜间发作）建议治疗","药物难治性癫痫（≥2 种合适药物足量治疗仍发作）评估手术（前颞叶切除、立体定向毁损）、迷走神经刺激、反应性神经刺激","避免多药联用，单药不足时选用机制互补的 2 种药物","发作时保护患者、防跌伤、保持气道通畅","生酮饮食可作为儿童难治性癫痫的辅助治疗"],"life":["规律服药，不可突然停药；漏服后不要双倍补服","避免睡眠剥夺、大量饮酒、闪光刺激","育龄女性孕前补充叶酸（5 mg/d），避免丙戊酸","驾驶、游泳、高空作业限制（发作控制 6–12 个月后评估）"]},"prog":"约 60%–70% 患者服药后发作可控制；单药控制失败仅约 15%–20% 的尝试追加药物能完全控制，因此难治性癫痫应尽早评估手术。缓解 10 年后可在医生指导下逐步停药（约 30%–40% 复发）。","refs":["中国抗癫痫协会《中国癫痫临床诊疗指南》（2023 版）","ILAE 癫痫发作与癫痫分类（2017）","Cochrane 抗癫痫药物单药治疗系统评价（2022）","中国癫痫诊疗指南（第二版，2015）"]},{"id":"epi_se","name":"癫痫持续状态","aka":["Status Epilepticus","SE","惊厥性癫痫持续状态"],"rank":2,"basic":{"define":"癫痫发作持续 ≥5 min，或两次以上发作而间期意识未恢复至基线；非惊厥性持续状态以 EEG 持续痫样放电 ≥30 min 为定义。为神经科急症，需立即处理。","risk":["既往癫痫且不规律服药/突然停药","颅内感染、卒中、肿瘤、外伤","代谢紊乱（低血糖、低钠、低钙）","药物中毒/戒断（酒精、苯二氮䓬）","自身免疫性脑炎"],"epi":"年发病率约 10–41/10 万，儿童与老年人高发；持续 >30 min 病死率约 20%–30%，且持续时间越长预后越差。"},"patho":"持续发作导致兴奋性氨基酸（谷氨酸）释放与钙内流，神经元损伤；同时交感激活、乳酸酸中毒、高热、横纹肌溶解、肺水肿，最终多器官衰竭。长时间后 GABA 受体下调与 NMDA 上调，导致药物（苯二氮䓬类）敏感性下降。","dx":{"criteria":["持续发作 ≥5 min 或反复发作间意识未恢复","明确发作时间（目击者、家属）与既往发作病史、用药史","快速血糖、血电解质、血气、中毒筛查","EEG 明确是否为非惊厥性持续状态（昏迷患者出现持续性痫样放电）","分级：早期（0–10 min）、中期（10–30 min）、晚期（>30 min，难治性）；>60 min 为超难治性"],"workup":["气道、呼吸、循环与血糖检查（首 5 min 内）","床旁血糖、血气、电解质、肝肾功能、血常规","头颅 CT/MRI（怀疑结构性病因）","腰穿（怀疑脑膜炎/脑炎且无禁忌）","EEG 监测（难治性者持续监测，指导用药）","抗癫痫药物血药浓度（丙戊酸、苯妥英、卡马西平）"],"grading":"分阶段处理：早期（0–10 min）、中期（10–30 min）、难治性（>30 min）、超难治性（>24 h）；同期按 SE 病因（结构性、代谢性、感染性、免疫性）并行处理。"},"ddx":[{"name":"全面强直阵挛发作（epi_general）","point":"与本类 epi_general 的鉴别点：单次 GTCS <5 min 自行终止，意识恢复；持续 >5 min 或发作间期意识不恢复即为持续状态。"},{"name":"非癫痫性心因性发作（假性SE）","point":"发作形式多变、双眼紧闭、骨盆挺伸、意识保留部分，EEG 无痫样放电；但若无法鉴别仍需按 SE 处理。"},{"name":"低血糖性脑病","point":"血糖 <2.8 mmol/L，补糖后意识与抽搐改善；需先测血糖再给抗癫痫药。"},{"name":"药物中毒/戒断性抽搐","point":"有酒精/苯二氮䓬戒断史，或三环类/异烟肼中毒，伴中毒表现；处理以对症与解毒为主。"}],"tx":{"drug":[{"name":"地西泮（一线，静脉）","dose":"10 mg iv 缓慢推注（<2 mg/min，儿童 0.3 mg/kg，最大 10 mg），必要时 10–15 min 后重复 1 次，24 h 总量 ≤40 mg","note":"早期首选；建立静脉通路困难时可选咪达唑仑肌注 10 mg（儿童 0.2 mg/kg，最大 10 mg）","renal":"无需调整","hepatic":"重度肝功能不全作用延长，减量","interact":"与阿片类、其他镇静药合用增加呼吸抑制；丙戊酸可延长其作用"},{"name":"咪达唑仑（一线备选，肌注/鼻喷）","dose":"肌注 10 mg（儿童 0.2 mg/kg，最大 10 mg）；鼻喷 0.1 mg/kg；静脉 0.1–0.2 mg/kg 缓慢推注","note":"无静脉通路时优先肌注/鼻喷","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与其他镇静药合用抑制呼吸"},{"name":"丙戊酸钠（二线，静脉负荷）","dose":"15–20 mg/kg 静脉缓推（速度 ≤3 mg/kg/min），必要时 10 min 后可再给 10 mg/kg；随后 1 mg/kg/h 维持","note":"二线药物选择之一（剂量与左乙拉西坦、苯妥英相当）；肝病、线粒体病禁用","renal":"无需调整","hepatic":"肝功能不全禁用；监测凝血","interact":"与拉莫三嗪、卡马西平、苯巴比妥相互影响"},{"name":"左乙拉西坦（二线，静脉负荷）","dose":"60 mg/kg（最大 4500 mg）单次静脉负荷，速度 ≤5 mg/kg/min；随后 1000 mg q12h 维持","note":"二线首选之一，相互作用少","renal":"按 eGFR 减量维持剂量","hepatic":"严重肝功能不全减量","interact":"相互作用少"},{"name":"丙泊酚（三线，难治性 SE）","dose":"1–2 mg/kg 静推后 2–10 mg/kg/h 泵入（需气管插管与 ICU 监护）","note":"难治性 SE 需持续 EEG 监测，疗程 12–48 h 后缓慢减停","renal":"遵说明书","hepatic":"长期输注注意丙泊酚输注综合征","interact":"与其他镇静药协同"},{"name":"咪达唑仑持续输注（三线）","dose":"0.05–0.2 mg/kg/h 起，按 EEG 滴定至爆发-抑制（最大 2.0 mg/kg/h）","note":"难治性 SE 的麻醉药；监测血流动力学","renal":"遵说明书","hepatic":"肝功能不全可蓄积","interact":"与升压药有协同/拮抗复杂作用"}],"nonDrug":["首 5 min：气道保护、吸氧、监测、测血糖（低血糖立即 50% 葡萄糖 50 mL 静滴或 10% 葡萄糖）","中晚期：气管插管与机械通气（难治性 SE），ICU 监护","查找并纠正诱因：感染、代谢紊乱、卒中、药物毒性","头颅 CT/MRI、腰穿（怀疑感染）","持续 EEG 监测（难治性/昏迷患者）；目标非惊厥性 SE 病因治疗","自身免疫性脑炎相关 SE 可用激素冲击/血浆置换/免疫球蛋白"],"life":["出院后规范抗癫痫治疗，避免突然停药","家属培训识别发作与急救（发作超过 5 min 呼救）","定期复查 EEG 与药物浓度","记录发作日记，避免诱因（睡眠不足、饮酒）"]},"prog":"早期规范处理可使约 80% 的惊厥性 SE 停止；难治性 SE 病死率 30%–40%，超难治性 >50%。预后取决于病因与持续时间，年轻与病因可逆者较好。","refs":["中国癫痫持续状态诊治专家共识（2022）","中国抗癫痫协会《中国癫痫临床诊疗指南》（2023 版）","NCS 癫痫持续状态治疗指南（2016，2023 更新）","ILAE 癫痫持续状态定义与分类（2015）"]}]},{"id":"neck","name":"神经变性病","rank":3,"summary":"慢性进行性神经元退行性变，无法根治：帕金森病以多巴胺替代为核心，阿尔茨海默病以胆碱酯酶抑制剂/美金刚改善症状；两病均需长期、多学科管理与照护者支持。","compare":[{"diseaseId":"pd","dx":"运动迟缓 + 静止性震颤或肌强直（UK Brain Bank 标准），左旋多巴试验性治疗有效，DAT 显像示纹状体摄取下降","key":"运动症状为“迟缓+震颤/强直”，无早期显著认知与语言障碍；多巴胺能药物反应明显"},{"diseaseId":"ad","dx":"隐匿起病、进行性近事记忆减退 + 至少 1 个认知域受损，影响日常生活；MRI 见海马萎缩，CSF Aβ42↓/p-tau↑ 或 PET 支持","key":"以记忆为首发、语言/失用/视空间障碍；无锥体外系强直与静止性震颤"}],"diseases":[{"id":"pd","name":"帕金森病","aka":["PD","Parkinson's Disease","震颤麻痹"],"rank":1,"basic":{"define":"以中脑黑质多巴胺能神经元进行性变性、路易小体形成为病理特征的运动障碍疾病，临床表现为运动迟缓、静止性震颤、肌强直与姿势步态异常，并伴非运动症状。","risk":["年龄（60 岁以上高发）","男性略多","遗传因素（LRRK2、GBA、SNCA 等）","农药/重金属暴露","既往脑外伤"],"epi":"我国 65 岁以上人群患病率约 1.7%，估计患者超过 300 万，占全球约一半；发病年龄多在 60 岁左右，10%–15% 为早发型。"},"patho":"黑质致密部多巴胺能神经元变性使纹状体多巴胺减少，导致直接通路抑制减弱、间接通路过度活跃，出现运动迟缓与强直；α-突触核蛋白异常聚集形成路易小体，病理可沿 Braak 分期向脑干与皮质扩展，解释非运动症状的逐渐出现。","dx":{"criteria":["运动迟缓（动作启动缓慢、幅度减小、重复动作幅度递减）为必备","加静止性震颤（4–6 Hz，搓丸样）或肌强直（铅管样、齿轮样）","UK Brain Bank 诊断标准：单侧起病、进行性、对左旋多巴反应良好、病程 ≥10 年仍不对称","MDS 临床诊断标准（2015）：支持性标准（多巴胺能反应、异动症、嗅觉减退、DAT 显像异常）；红色警示（早期跌倒、快速进展、眼动异常、自主神经衰竭早期）","DAT-SPECT/PET 示纹状体摄取降低，有助与特发性震颤、药物性帕金森综合征鉴别","排除继发性帕金森综合征（药物、血管性、正常颅压脑积水）与帕金森叠加综合征"],"workup":["统一帕金森病评定量表（UPDRS/MDS-UPDRS）与 Hoehn-Yahr 分期","头颅 MRI（排除血管性、脑积水、Wilson 病）","DAT-SPECT/PET（诊断疑难时）","认知筛查（MoCA）、抑郁/焦虑量表、睡眠问卷（RBD）","血常规、肝肾功能、甲状腺功能（拟用左旋多巴者）","药物史（抗精神病药、甲氧氯普胺可致药源性帕金森综合征）"],"grading":"Hoehn-Yahr 分期：Ⅰ 单侧症状；Ⅱ 双侧、无平衡障碍；Ⅲ 姿势不稳、可独立生活；Ⅳ 严重残疾、可站立行走；Ⅴ 卧床。MDS-UPDRS 用于量化运动与非运动症状。"},"ddx":[{"name":"阿尔茨海默病（ad）","point":"与本类 ad 的鉴别点：PD 为运动迟缓+震颤/强直、认知在早期相对保留；AD 以记忆减退为主，早期无锥体外系体征。"},{"name":"特发性震颤","point":"姿势性/动作性震颤（写字、举杯时明显），无运动迟缓与肌强直，饮酒与普萘洛尔可缓解，DAT 显像正常。"},{"name":"多系统萎缩（MSA）","point":"早期严重自主神经衰竭（体位性低血压、尿潴留）、小脑性共济失调或声带麻痹，对左旋多巴反应差，MRI 见“十字面包征”。"},{"name":"进行性核上性麻痹（PSP）","point":"垂直核上性凝视麻痹、早期频繁跌倒、轴性强直，对左旋多巴反应差，MRI 见“蜂鸟征”。"},{"name":"药物性帕金森综合征","point":"使用抗精神病药（氟哌啶醇、利培酮）、甲氧氯普胺、氟桂利嗪等后出现对称性强直，停药后数周–数月可改善。"}],"tx":{"drug":[{"name":"复方左旋多巴（多巴丝肼片，左旋多巴+苄丝肼 4:1）","dose":"起始 62.5–125 mg（1/4–1/2 片 250 mg 规格）tid，餐前 1 h 或餐后 1.5 h；每 1–2 周增加 125 mg/d，维持 300–600 mg/d（左旋多巴）分 3–4 次；最大 ≤1000 mg/d","note":"最有效药物，运动症状明显者首选；早期可从小剂量起始减少异动症风险","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与 MAO-B 抑制剂（司来吉兰）合用可致高血压危象；与抗精神病药（多巴胺拮抗剂）疗效拮抗；与铁剂同服降低吸收"},{"name":"复方左旋多巴卡比多巴缓释片（息宁）","dose":"250–500 mg（左旋多巴含量）tid 起始，按运动波动调整，每日分 3–4 次","note":"用于剂末现象、夜间症状；吸收较慢，起效不如普通片","renal":"无需调整","hepatic":"慎用","interact":"同左旋多巴"},{"name":"普拉克索（多巴胺受体激动剂）","dose":"0.125 mg tid 起始，每周加 0.125 mg tid，目标 0.5–1.5 mg tid（最大 4.5 mg/d）","note":"早发型或老年患者可选；需监测冲动控制障碍、日间嗜睡","renal":"CrCl 30–50 起始 0.125 mg bid、最大 1.5 mg/d；<30 遵说明书","hepatic":"肝功能不全慎用","interact":"与抗精神病药拮抗；与降压药合用致低血压"},{"name":"罗匹尼罗","dose":"0.25 mg tid 起始，每周加 0.25 mg tid，目标 3–9 mg/d，最大 24 mg/d","note":"受体激动剂替代；注意幻觉与嗜睡","renal":"CrCl <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与 CYP1A2 抑制剂（环丙沙星）升高浓度"},{"name":"司来吉兰（MAO-B 抑制剂）","dose":"2.5–5 mg qd 早晨，最大 10 mg/d（>10 mg 抑制 MAO-A 需限酪胺）","note":"可延缓左旋多巴用量增加；与左旋多巴合用需减左旋多巴 10%–30%","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与左旋多巴、三环类、SSRI 合用增加高血压危象；避免与哌替啶"},{"name":"恩他卡朋（COMT 抑制剂）","dose":"200 mg 与每次左旋多巴同服，每日 ≤8 次（≤1600 mg/d）","note":"改善剂末现象，可减少左旋多巴剂量约 20%–30%","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与非选择性 MAO 抑制剂禁用；与铁剂、抗精神病药相互作用"},{"name":"金刚烷胺","dose":"100 mg qd–bid 起始，最大 400 mg/d 分次","note":"改善运动迟缓与异动症；晚间服用致失眠，下肢网状青斑","renal":"CrCl <60 减量；<30 隔日 100 mg","hepatic":"慎用","interact":"与抗胆碱药合用增加意识模糊"}],"nonDrug":["脑深部电刺激（DBS）：药物难治性运动波动/异动症、震颤为主型且认知良好的中晚期患者","康复治疗：物理治疗（步态、平衡）、言语与吞咽训练、作业治疗","持续皮下阿扑吗啡或左旋多巴肠凝胶（晚期运动并发症）","非运动症状管理：抑郁焦虑（SSRI）、便秘（聚乙二醇）、RBD（氯硝西泮）、体位性低血压（米多君）","避免抗精神病药（如必须用，选喹硫平/氯氮平）"],"life":["规律服药，不可突然停药（可致恶性综合征）","低脂、高纤维饮食预防便秘；分次少量蛋白（避免蛋白与左旋多巴竞争吸收时可采用低蛋白饮食）","防跌倒（居家环境改造）、太极与有氧运动","照护者教育与长期随访（每 3–6 个月）"]},"prog":"进展缓慢，Hoehn-Yahr Ⅲ 期通常出现在起病后 5–10 年；运动波动与异动症在左旋多巴治疗 5 年后见于约 50%。规范治疗可使预期寿命接近正常，晚期主要死因为肺炎与跌倒并发症。","refs":["中国帕金森病治疗指南（第四版，2020）","中国帕金森病诊断标准（2016）","MDS 帕金森病临床诊断标准（2015）","中国帕金森病脑深部电刺激疗法专家共识（2020）"]},{"id":"ad","name":"阿尔茨海默病","aka":["AD","Alzheimer's Disease","老年性痴呆"],"rank":2,"basic":{"define":"以进行性认知功能减退与日常生活能力下降为特征的神经退行性疾病，病理为 β-淀粉样蛋白（Aβ）沉积形成的老年斑与 tau 蛋白过度磷酸化形成的神经原纤维缠结，是最常见的痴呆病因（约 60%–70%）。","risk":["年龄（65 岁以上患病率约 5%，85 岁以上可达 20%–30%）","家族史与 APOE ε4 等位基因","女性","心血管危险因素（高血压、糖尿病、高同型半胱氨酸）","低教育水平、社交隔离","唐氏综合征"],"epi":"我国 60 岁以上痴呆患病率约 6%，患者超过 1500 万，其中 AD 约 1000 万；女性多于男性，农村患病率高于城市。"},"patho":"Aβ 前体蛋白（APP）异常裂解产生 Aβ42，寡聚体神经毒性并形成淀粉样斑块；tau 蛋白过度磷酸化形成神经原纤维缠结，导致突触丢失与神经元死亡。病变从内嗅皮质、海马开始，逐步累及新皮质。神经炎症、线粒体功能障碍与胆固醇代谢异常共同参与。","dx":{"criteria":["隐匿起病、进行性加重的近事记忆障碍，影响日常活动","至少 1 个其他认知域受损（语言、视空间、执行功能、注意力）","MMSE 或 MoCA 提示认知损害；CDR 评估功能分期","排除可逆性病因：甲状腺功能、维生素 B12、梅毒、抑郁、药物（抗胆碱能）、正常颅压脑积水","支持性生物标志物：MRI 海马与内侧颞叶萎缩（MTA 分级 ≥2）、CSF Aβ42↓/p-tau↑、Aβ PET 阳性、血液 p-tau217","按 NIA-AA 2018/2024 标准进行生物学定义与临床分期"],"workup":["病史（患者与知情者分别采集）+ 神经心理测评（MMSE、MoCA、CDR、ADAS-Cog）","头颅 MRI（海马萎缩、白质病变、微出血）","血液：甲状腺功能、维生素 B12、叶酸、同型半胱氨酸、梅毒/HIV、肝肾功能","抑郁筛查（GDS/HAMD）与精神行为症状评估","CSF 生物标志物或淀粉样 PET（可选，用于不典型或早发）","APOE 基因型（科研/药物选择，不做常规筛查）","日常生活能力评估（ADL/IADL）"],"grading":"临床分期：临床前期（无症状，生物标志物阳性）→ 轻度认知障碍（MCI，日常能力基本保留）→ 轻度痴呆 → 中度 → 重度（MMSE 21–26 轻、10–20 中、<10 重）。病理 Braak 分期与 Thal 分期用于研究。"},"ddx":[{"name":"帕金森病（pd）","point":"与本类 pd 的鉴别点：AD 以近事记忆减退为首发、无运动迟缓/强直/静止性震颤；PD 痴呆多在运动症状出现 1 年后，以执行与视空间障碍为主。"},{"name":"血管性痴呆","point":"阶梯式加重、有卒中史与局灶体征，MRI 见多发梗死或白质高信号（Fazekas 3 级），执行功能损害突出。"},{"name":"路易体痴呆（DLB）","point":"波动性认知、反复生动视幻觉、帕金森样体征、RBD；对神经阻滞剂高度敏感（易致恶性反应）。"},{"name":"额颞叶痴呆（FTD）","point":"早期人格改变、行为异常或语言障碍（语义性痴呆、进行性非流利性失语），记忆相对保留，MRI 见额颞叶萎缩。"},{"name":"抑郁性假性痴呆","point":"起病较快、情绪低落、回答“不知道”、睡眠食欲改变，抗抑郁治疗后可改善。"}],"tx":{"drug":[{"name":"多奈哌齐（胆碱酯酶抑制剂）","dose":"5 mg qn 起始，4 周后可增至 10 mg qn；重度可选 23 mg qn（需整片吞服）","note":"轻-中度首选；可延缓症状进展数月；心动过缓与晕厥风险","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与 β 受体阻滞剂、地高辛合用致心动过缓/传导阻滞；与抗胆碱能药拮抗"},{"name":"卡巴拉汀（利斯的明）","dose":"口服 1.5 mg bid 起始，每 2 周加 1.5 mg bid，目标 3–6 mg bid；或贴剂 4.6 mg/24h 起始，1 个月后 9.5 mg/24h","note":"可换用贴剂减少胃肠道反应","renal":"无需调整","hepatic":"轻度–中度减量，重度禁用","interact":"与抗胆碱能药拮抗；与 β 受体阻滞剂合用加重心动过缓"},{"name":"美金刚（NMDA 受体拮抗剂）","dose":"5 mg qd 起始，每周增 5 mg，目标 10 mg bid（20 mg/d）；中度-重度可先用","note":"用于中重度 AD，可改善精神行为症状；可与胆碱酯酶抑制剂联用","renal":"CrCl <30 减量（5 mg bid）","hepatic":"重度肝功能不全慎用","interact":"碱化尿液药物（碳酸酐酶抑制剂）降低排泄；与金刚烷胺合用注意中枢兴奋"},{"name":"仑卡奈单抗（Lecanemab，抗淀粉样蛋白单抗）","dose":"10 mg/kg 静脉输注，每 2 周 1 次；按说明书进行滴定/维持（具体遵说明书）","note":"用于早期 AD（MCI 或轻度痴呆且 Aβ 阳性）；需监测 ARIA（脑水肿/微出血），警惕 Aβ 清除相关风险","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗凝药合用时注意 ARIA 出血风险"},{"name":"喹硫平/利培酮（精神行为症状）","dose":"喹硫平 12.5–25 mg qn 起始，按需滴定，尽量短期低剂量；利培酮 0.25–0.5 mg qn","note":"仅用于严重幻觉、攻击、躁动且非药物无效时；增加死亡与卒中风险，需知情同意","renal":"按 CrCl 调整","hepatic":"肝功能不全减量","interact":"与胆碱酯酶抑制剂合用增加锥体外系反应与心动过缓"}],"nonDrug":["认知训练与行为干预，保持社交与规律运动","行为症状的非药物优先：环境调整、活动安排、照护者沟通","照护者支持与心理教育、日间照料与长期照护规划","驾乘与财务管理风险评估、防走失（定位设备）","避免抗胆碱能药物（苯海索、颠茄生物碱）"],"life":["地中海饮食、规律有氧运动、控血压/血糖、戒烟","保持社交与认知刺激（阅读、棋牌、学习）","定期随访（每 3–6 个月）评估认知与功能变化","照护者减压与喘息服务"]},"prog":"病程一般为 8–10 年；轻度 MCI 每年约 10%–15% 转化为痴呆。早期诊断与生活方式干预、抗 Aβ 治疗可延缓进展；晚期多因肺炎、跌倒、营养不良死亡。","refs":["中国阿尔茨海默病痴呆诊疗指南（2020 年版）","中国痴呆与认知障碍诊治指南（2023，中华医学会神经病学分会）","NIA-AA 阿尔茨海默病诊断标准（2018/2024）","中国阿尔茨海默病早期诊断与干预专家共识（2023）"]}]},{"id":"neuro_other","name":"其他神经免疫与神经肌病","rank":4,"summary":"免疫介导的周围神经、神经肌肉接头与中枢神经脱髓鞘疾病：GBS 以静脉免疫球蛋白/血浆置换为一线的急性病；MG 以胆碱酯酶抑制剂+免疫治疗维持；MS 以急性期激素冲刺、缓解期疾病修饰治疗预防复发。","compare":[{"diseaseId":"gb","dx":"急性对称性弛缓性瘫，反射消失，数天内进展，脑脊液蛋白-细胞分离，神经传导速度减慢","key":"上行性对称性无力+腱反射消失，脑脊液蛋白升高而细胞数正常"},{"diseaseId":"mg","dx":"波动性眼睑下垂/复视/吞咽困难/近端肢体无力，疲劳时加重，新斯的明试验阳性，抗 AChR 抗体阳性","key":"症状波动、晨轻暮重，胆碱酯酶抑制剂有效；肌电图重复神经刺激衰减"},{"diseaseId":"ms","dx":"青年复发缓解型神经功能缺损（视神经炎、复视、肢体麻木无力、共济失调），时间与空间多发性，MRI 见脱髓鞘斑块","key":"时间与空间多发性（McDonald 标准），寡克隆带阳性"}],"diseases":[{"id":"gb","name":"吉兰-巴雷综合征","aka":["GBS","Guillain-Barré Syndrome","格林-巴利综合征","急性炎症性脱髓鞘性多神经病"],"rank":1,"basic":{"define":"由免疫介导的急性周围神经病，多数在感染后 1–3 周出现对称性弛缓性肢体无力与腱反射消失，可分为急性炎性脱髓鞘性多神经根神经病（AIDP）、急性运动轴索神经病（AMAN）等亚型。","risk":["前驱感染（空肠弯曲菌、巨细胞病毒、EB 病毒、支原体、寨卡）","疫苗接种后（罕见）","手术、外伤","免疫抑制状态"],"epi":"年发病率约 1–2/10 万，随年龄增长升高；男性略多；约 20%–25% 需机械通气，病死率 3%–5%。"},"patho":"前驱感染后，病原体表面分子与周围神经髓鞘（GM1、GD1a 等神经节苷脂）发生分子模拟，产生交叉抗体，激活补体与巨噬细胞，导致节段性脱髓鞘（AIDP）或轴索变性（AMAN）。抗体与补体介导的神经根损伤为核心机制。","dx":{"criteria":["进行性、对称性肢体无力（下肢起病多见，可累及颅神经与呼吸肌），腱反射减弱或消失","病程进展 ≤4 周，之后进入平台期恢复","脑脊液蛋白-细胞分离：蛋白升高（>0.45 g/L）而白细胞 <10/mm³（约 2 周后出现）","神经传导：远端潜伏期延长、传导速度减慢、F 波异常、传导阻滞（AIDP）；复合肌肉动作电位波幅下降（AMAN）","存在前驱感染史","Brighton 诊断标准（2011）分级；鉴别急性脊髓炎、低钾性肌无力、重症肌无力"],"workup":["神经系统查体（肌力、腱反射、颅神经、呼吸功能）","脑脊液（蛋白、细胞数；必要时抗神经节苷脂抗体）","肌电图与神经传导速度","抗 GM1、GD1a、GQ1b 抗体（变异型如 Miller Fisher）","头颅与脊柱 MRI（排除脊髓压迫、炎性脱髓鞘）","肺功能（FVC、吸气负压），评估呼吸肌麻痹","心电图与自主神经功能评估"],"grading":"Brighton 标准（一级含双相病程、反射消失、脑脊液/肌电支持）；GBS 残疾评分（0–6，6 为死亡）；Erasmus GBS 预后评分。"},"ddx":[{"name":"重症肌无力（mg）","point":"与本类 mg 的鉴别点：GBS 为对称性驰缓性瘫、腱反射消失、脑脊液蛋白升高；MG 为波动性肌无力（晨轻暮重）、腱反射保留、新斯的明试验阳性、重复神经刺激衰减。"},{"name":"多发性硬化（ms）","point":"与本类 ms 的鉴别点：GBS 急性、对称、周围神经受累（反射消失）；MS 为中枢脱髓鞘（反射亢进、Babinski 阳性）、症状空间多发性、MRI 脑白质斑块。"},{"name":"急性脊髓炎（横贯性）","point":"有明确感觉平面与自主神经功能障碍（尿潴留），脊髓 MRI 见长节段高信号，腱反射早期可消失后亢进。"},{"name":"低钾性周期性麻痹","point":"反复发作、近端无力，血清钾降低、补钾后迅速恢复，无感觉障碍与脑脊液异常。"},{"name":"中国南方 AMAN 亚型（空肠弯曲菌相关）","point":"空肠弯曲菌前驱感染、抗 GM1 抗体阳性、肌电图呈轴索损害，恢复较慢。"}],"tx":{"drug":[{"name":"静注人免疫球蛋白（IVIG）","dose":"0.4 g/kg/d 静脉滴注，连用 5 天（总 2 g/kg）；或用 1 g/kg/d 连用 2 天","note":"发病 2 周内使用最有效；轻症（可独立行走）可观察或仍使用","renal":"肾功能不全者注意渗透性肾损伤，减慢输注","hepatic":"遵说明书","interact":"IgA 缺乏者可能发生过敏；与减毒活疫苗间隔"},{"name":"血浆置换","dose":"每次 40–50 mL/kg，共 4–6 次（隔日或每日），替代 IVIG","note":"与 IVIG 疗效相当，二者不推荐联合或交替","renal":"血液动力学不稳定者慎用","hepatic":"凝血功能异常者需补充","interact":"置换后需补充免疫球蛋白与凝血因子"},{"name":"镇痛（神经病理性疼痛）","dose":"加巴喷丁 300 mg tid 起始，可按需加至 600 mg tid；或普瑞巴林 75 mg bid","note":"GBS 疼痛明显者对症","renal":"按 CrCl 减量","hepatic":"重度肝功能不全慎用","interact":"与阿片类合用加重呼吸抑制（呼吸肌麻痹者慎用）"},{"name":"预防深静脉血栓（低分子肝素）","dose":"依诺肝素 40 mg 皮下 qd（卧床者）","note":"长期卧床、无法行走者","renal":"CrCl <30 改为普通肝素 5000 U 皮下 bid","hepatic":"凝血障碍者慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["呼吸功能监测：FVC <15–20 mL/kg 或下降 >30% 时考虑气管插管；ICU 监护","自主神经功能障碍（血压波动、心律失常）监护","康复：早期被动关节活动，防痉挛与压疮","避免使用糖皮质激素单药（无效）；不推荐单纯激素治疗","腹泻患者筛查空肠弯曲菌（治疗是否改变病程证据不足）"],"life":["长期康复训练（3–6 个月，部分 1–2 年）","心理支持与疲劳管理","恢复期监测复发（罕见）与慢性炎性脱髓鞘性多神经病（CIDP）转化"]},"prog":"约 80% 患者 6–12 个月内可独立行走；20%–25% 需机械通气；5%–10% 遗留严重残疾，病死率 3%–5%。AMAN 亚型恢复较慢，但多数可明显改善。","refs":["中国吉兰-巴雷综合征诊治指南（2019，中华医学会神经病学分会）","EAN/PNS 吉兰-巴雷综合征管理指南（2023）","中国急性炎性脱髓鞘性多发性神经根神经病诊治共识（2019）","Brighton 吉兰-巴雷综合征诊断标准（2011）"]},{"id":"mg","name":"重症肌无力","aka":["MG","Myasthenia Gravis","重症肌无力"],"rank":2,"basic":{"define":"由抗乙酰胆碱受体（AChR）抗体等自身抗体介导的神经肌肉接头传递障碍，表现为波动性骨骼肌无力（眼肌、延髓肌、四肢近端肌），活动后加重、休息后减轻，可为全身型或眼肌型。","risk":["胸腺异常（胸腺瘤约 10%–15%，胸腺增生约 70%）","20–40 岁女性与 50–70 岁男性双峰","抗 AChR、MuSK、LRP4 抗体阳性","感染、手术、药物可诱发危象"],"epi":"患病率约 150–300/100 万，我国估计患者约 20 万；女性略多。出现危象者病死率约 4%–8%。"},"patho":"抗 AChR 抗体通过补体激活、受体内吞降解与功能阻断，减少神经肌肉接头处 AChR 数量；MuSK 抗体则影响受体聚集。胸腺异常（滤泡增生或胸腺瘤）参与自身免疫启动。","dx":{"criteria":["波动性骨骼肌无力：上睑下垂、复视、咀嚼/吞咽困难、构音障碍、近端肢体无力，晨轻暮重、活动后加重","腱反射正常、感觉正常、无病理反射","新斯的明试验阳性（注射后 30–60 min 肌力明显改善）","重复神经刺激（低频 3 Hz）递减 ≥10%；单纤维肌电图颤抖增宽","抗 AChR 抗体阳性（约 80% 全身型、50% 眼肌型）；MuSK 抗体阳性（10%–15%）","胸部增强 CT/MRI 筛查胸腺瘤","排除 Lambert-Eaton（高频递增）、眼咽型肌营养不良、甲亢性肌病"],"workup":["新斯的明试验、冰袋试验（眼睑下垂）","肌电图重复神经刺激 + 单纤维肌电图","抗 AChR、MuSK、LRP4、Agrin 抗体","胸部 CT/MRI（胸腺瘤）","甲状腺功能（合并甲亢/甲减）与自身抗体筛查","MuSK 抗体阳性者检查颈部肌肉 MRI（萎缩）","呼吸功能（FVC）与吞咽评估（危象预警）"],"grading":"MGFA 临床分型：Ⅰ 眼肌型；Ⅱ 轻度全身型（Ⅱa 肢体为主、Ⅱb 延髓为主）；Ⅲ 中度（Ⅲa/Ⅲb）；Ⅳ 重度；Ⅴ 需插管。MGFA 治疗后状态分级（改善、缓解、加重）。"},"ddx":[{"name":"吉兰-巴雷综合征（gb）","point":"与本类 gb 的鉴别点：MG 为波动性无力、腱反射正常、无感觉障碍、新斯的明试验阳性；GBS 对称性驰缓性瘫、腱反射消失、脑脊液蛋白升高。"},{"name":"多发性硬化（ms）","point":"与本类 ms 的鉴别点：MG 无力在头部/肢体，无感觉障碍与共济失调，反射正常；MS 有感觉异常、反射亢进与中枢影像病灶。"},{"name":"Lambert-Eaton 肌无力综合征","point":"近端下肢无力为主、活动后初期改善（易化），高频重复刺激递增，常合并小细胞肺癌（副肿瘤），抗 VGCC 抗体阳性。"},{"name":"甲亢性肌病/甲状腺眼病","point":"球后突出、眼睑水肿、甲状腺功能异常，无力不呈波动性，新斯的明试验阴性。"},{"name":"脑干梗死（单侧眼睑下垂、复视）","point":"急性起病、常伴感觉/共济失调，MRI DWI 有责任病灶，不会波动。"}],"tx":{"drug":[{"name":"溴吡斯的明（胆碱酯酶抑制剂）","dose":"60 mg tid–qid 起始（最大 120 mg q4h），症状控制目标；儿童 1 mg/kg/d 起始","note":"对症治疗，改善波动性无力；注意胆碱能危象（腹痛、腹泻、流涎、瞳孔缩小）","renal":"肾功能不全减量","hepatic":"严重肝功能不全减量","interact":"与 β 受体阻滞剂、抗心律失常药合用加重心动过缓；与氨基糖苷类合用拮抗（慎用）"},{"name":"泼尼松（糖皮质激素）","dose":"起始 10–20 mg qd，每 3–5 天增加 5–10 mg 至 0.5–1 mg/kg/d（最大 60 mg）缓解后逐渐减量；或隔日疗法","note":"全身型一线免疫治疗；起始可能短暂加重（需住院观察），尤其延髓型","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与降糖药拮抗；与 CYP3A4 抑制剂增加暴露"},{"name":"硫唑嘌呤","dose":"1.5–2.5 mg/kg/d 口服，起效需 6–12 个月；用药前检测 TPMT/NUDT15","note":"激素助减剂，适用于长期维持；需监测血常规与肝功能","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与别嘌醇合用显著增加骨髓抑制（减至 25%）；与 ACEI 合用致白细胞减少"},{"name":"吗替麦考酚酯","dose":"0.5 g bid 起始，可增至 1 g bid","note":"激素助减剂，起效较慢；妊娠禁用","renal":"按肾功能减量","hepatic":"重度肝功能不全减量","interact":"与抗酸药分开；避免活疫苗"},{"name":"利妥昔单抗","dose":"375 mg/m² 静脉 qw×4 次，或 1 g iv 2 次（间隔 2 周）；或按说明书方案","note":"MuSK 抗体阳性者首选，或难治性/激素依赖的 AChR 型","renal":"无需调整","hepatic":"遵说明书","interact":"避免活疫苗；乙肝再激活筛查"},{"name":"依库珠单抗/依非库单抗（补体抑制剂）","dose":"遵说明书（按体重给药，静脉输注，定期维持）","note":"难治性 MG（尤其 AChR 抗体阳性）可选择；需注意脑膜炎球菌感染风险并接种疫苗","renal":"遵说明书","hepatic":"遵说明书","interact":"与 IVIG 等合用注意补体抑制叠加"}],"nonDrug":["胸腺切除：胸腺瘤者必切除；AChR 抗体阳性全身型 18–65 岁（非胸腺瘤）可考虑（MGTX 证据）","血浆置换/IVIG：肌无力危象、术前准备、急性加重","肌无力危象：ICU 监护、机械通气（FVC <15 mL/kg）、大剂量激素+IVIG/血浆置换，避免使用增加呼吸抑制的镇静药","避免诱发危象药物：氨基糖苷类、喹诺酮类、镁剂、β 阻滞剂、钙通道阻滞剂、某些抗精神病药、碘造影剂","眼肌型可先局部治疗或激素冲击"],"life":["规律作息，避免感染与过度劳累","定期评估呼吸与吞咽功能；随身携带疾病卡片","长期激素者骨质疏松预防；妊娠需多学科管理","胸腺切除后随访（MGFA-PIS）"]},"prog":"多数患者经免疫治疗可获得显著改善，约 30%–40% 可达药物缓解（MGFA PR）；胸腺瘤相关者预后受肿瘤影响。危象死亡率已降至约 4% 以下。","refs":["中国重症肌无力诊断和治疗指南（2020 版）","重症肌无力诊治中国专家共识（2022）","MGFA 重症肌无力管理共识（2021）","中国胸腺瘤合并重症肌无力外科治疗专家共识（2021）"]},{"id":"ms","name":"多发性硬化","aka":["MS","Multiple Sclerosis","多发性硬化症"],"rank":3,"basic":{"define":"以中枢神经系统（脑、脊髓、视神经）白质炎性脱髓鞘为特征、具有时间与空间多发性的自身免疫疾病，临床分为复发缓解型（RRMS）、继发进展型（SPMS）、原发进展型（PPMS）。","risk":["青年发病（20–40 岁，女性多见 2:1–3:1）","EB 病毒感染史（强关联）","维生素 D 缺乏、北方高纬度地区","吸烟","HLA-DRB1*15:01 等遗传易感性"],"epi":"我国发病率约 0.5–1/10 万，呈逐年增加趋势（女性增加更明显），多见于青年女性，亚洲以视神经脊髓炎谱系疾病（NMOSD）相对更多，需鉴别。"},"patho":"外周自身反应性 T 细胞被激活后穿过血脑屏障，与髓鞘抗原反应，引起局灶性脱髓鞘与轴索损伤；B 细胞、补体与巨噬细胞参与斑块形成。急性炎症与进行性神经退变（进展型）机制不同，后者以少突胶质细胞损伤与“慢性活动性炎症”为主。","dx":{"criteria":["急性或亚急性神经功能缺损（单侧视神经炎、复视、肢体麻木/无力、共济失调、括约肌障碍），持续 ≥24 h","时间多发性：临床/影像出现新病灶在不同时间（McDonald 2017 标准：不同时间出现新 T2 病灶或增强病灶）","空间多发性：≥4 个部位中 2 个受累（脑室旁、皮质/近皮质、幕下、脊髓）","CSF 寡克隆区带阳性（约 85%–90%）与 IgG 指数升高","血清/CSF 水通道蛋白 4（AQP4-IgG）与 MOG 抗体阴性（排除 NMOSD/MOGAD）","需排除感染、血管病、肿瘤、营养代谢病因"],"workup":["头颅与脊髓 MRI（平扫+增强，DWI）","CSF 寡克隆区带、IgG 指数、细胞数与蛋白","血清 AQP4-IgG、MOG-IgG（区分 NMOSD/MOGAD）","视觉诱发电位（VEP）、OCT（视神经）","诱发电位（体感/运动）、EDSS 评分","自身免疫筛查与感染筛查（HIV、梅毒、莱姆病）"],"grading":"McDonald 2017 诊断标准；EDSS（0–10）评估残疾；病程分型 RRMS/SPMS/PPMS；MSSS 评估疾病活动度。"},"ddx":[{"name":"吉兰-巴雷综合征（gb）","point":"与本类 gb 的鉴别点：MS 为中枢脱髓鞘（反射亢进、Babinski 阳性、MRI 白质病灶、寡克隆带）；GBS 为周围神经、对称性驰缓性瘫、反射消失。"},{"name":"重症肌无力（mg）","point":"与本类 mg 的鉴别点：MG 无感觉障碍与共济失调、腱反射正常、新斯的明试验阳性；MS 有感觉异常、中枢病灶与寡克隆带。"},{"name":"视神经脊髓炎谱系疾病（NMOSD）","point":"AQP4-IgG 阳性、视神经炎（常双侧/严重）+长节段横贯性脊髓炎（≥3 个椎体），脑部病灶少见，亚洲人群多见。"},{"name":"急性播散性脑脊髓炎（ADEM）","point":"感染后的单相病程，广泛白质病变伴意识障碍与脑病表现，多见于儿童，无寡克隆带持续阳性。"},{"name":"中枢神经系统血管炎","point":"多系统受累、ESR/CRP 升高，血管造影/活检见血管炎性改变，MRI 病灶多为缺血性分布。"}],"tx":{"drug":[{"name":"甲泼尼龙（急性期冲击）","dose":"1 g iv qd，连用 3–5 天，改口服泼尼松逐渐减量（约 1–2 周内停）","note":"急性复发首选；冲击期间保护胃黏膜、监测血糖与血压","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与 NSAIDs 合用消化道出血；与 CYP3A4 抑制剂增加暴露"},{"name":"血浆置换/IVIG（激素无效的重症复发）","dose":"血浆置换：每 2 天 1 次共 5 次（每次 1–1.5 个血浆容量）；IVIG 0.4 g/kg/d×5 天","note":"用于激素反应不佳的严重复发，尤其视神经炎","renal":"IVIG 注意渗透性肾损伤","hepatic":"遵说明书","interact":"血浆置换后补充凝血因子"},{"name":"干扰素 β（倍泰龙）","dose":"皮下注射 250 μg 隔日（IFNβ-1b）；或 22–44 μg 皮下 tiw（IFNβ-1a）","note":"RRMS 一线疾病修饰治疗（DMT），流感样症状可预服对乙酰氨基酚","renal":"无需调整","hepatic":"重度肝功能不全慎用，监测肝酶","interact":"与其他免疫抑制合用需评估"},{"name":"特立氟胺","dose":"7 mg qd 或 14 mg qd 口服","note":"RRMS 口服 DMT；妊娠禁忌（需洗脱），监测肝功能与血常规","renal":"无需调整","hepatic":"肝功能不全者需监测","interact":"与华法林、利福平相互作用；避免与来氟米特合用"},{"name":"富马酸二甲酯","dose":"120 mg bid×7 天后增至 240 mg bid","note":"RRMS 口服 DMT；潮红与胃肠道反应常见","renal":"重度肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与其他免疫抑制剂合用需评估"},{"name":"芬戈莫德","dose":"0.5 mg qd 口服","note":"RRMS 高效 DMT；首剂后 6 h 心电监测（心动过缓），注意黄斑水肿与感染","renal":"无需调整","hepatic":"重度肝功能不全禁用","interact":"与 β 受体阻滞剂、抗心律失常药合用致心动过缓"},{"name":"那他珠单抗/奥法木单抗/利妥昔单抗","dose":"遵说明书（静脉输注，按体重/方案）","note":"高效 DMT，用于活动性 RRMS；那他珠单抗需 JC 病毒抗体与 PML 风险评估","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他免疫抑制剂叠加增加感染风险"}],"nonDrug":["康复治疗：运动训练、平衡训练、疲劳管理","症状治疗：痉挛（巴氯芬/替扎尼定）、膀胱功能障碍、疼痛（普瑞巴林）、抑郁（SSRI）","定期随访 MRI 与 EDSS，评估 DMT 疗效（NEDA-3）","避免过度劳累与体温升高（Uhthoff 现象）","接种疫苗（免疫抑制前评估）"],"life":["戒烟、维生素 D 补充（1000–2000 IU/d）","规律有氧运动与认知训练","育龄女性 DMT 与妊娠计划管理","心理支持与患者教育"]},"prog":"RRMS 未治疗者 10–15 年约 50% 转 SPMS；高效 DMT 早期启动可显著延缓残疾进展。总体预后较既往改善，多数患者可维持工作与生活能力，寿命接近正常人。","refs":["中国多发性硬化诊断和治疗指南（2023 版）","中国视神经脊髓炎谱系疾病诊断与治疗指南（2023）","McDonald 多发性硬化诊断标准（2017 修订）","中国多发性硬化疾病修饰治疗专家共识（2022）"]}]},{"id":"headache_dementia","name":"头痛与痴呆","rank":5,"summary":"头痛先分原发与继发，红旗征决定是否需要影像；痴呆先分可逆与不可逆，波动性认知障碍伴真性视幻觉高度提示路易体痴呆。","compare":[{"diseaseId":"ne_migraine","dx":"反复发作、单侧搏动性中重度头痛，活动加重，伴恶心或畏光畏声，每次 4–72 h","key":"发作性、可完全缓解、有明确诱因（睡眠不足、月经、酒）"},{"diseaseId":"ne_tension_cluster","dx":"紧箍样轻中度头痛，或单侧眶周剧烈疼痛伴结膜充血、流涕、躁动（丛集性）","key":"紧张型：双侧压迫感、不伴呕吐；丛集性：每日定时发作、患者坐立不安"},{"diseaseId":"ne_vad","dx":"血管事件后 3 个月内起病、阶梯式加重、执行功能障碍突出，影像见多发梗死或白质病变","key":"阶梯式恶化 + 影像脑血管病变"},{"diseaseId":"ne_dlb","dx":"波动性认知障碍 + 真性视幻觉 + 自发性帕金森综合征，REM 睡眠行为障碍常早于认知下降","key":"认知波动 + 视幻觉 + 对神经阻滞剂高度敏感"}],"diseases":[{"id":"ne_migraine","name":"偏头痛","aka":["Migraine","有先兆偏头痛","无先兆偏头痛"],"rank":1,"basic":{"define":"反复发作的原发性头痛，典型表现为单侧、搏动性、中重度、活动后加重，持续 4–72 小时，伴恶心和/或畏光畏声。约 1/3 患者发作前有可逆的局灶神经症状（先兆，多为视觉）。","risk":["女性（男女比约 3:1）","一级亲属患病（遗传度约 40%–60%）","睡眠不足或过多、精神压力","月经期（雌激素撤退）","酒精、含酪胺食物、强光与噪音","肥胖与咖啡因过量"],"epi":"全球患病率约 12%–15%，我国约 9.3%；女性 20–40 岁为高峰。世界卫生组织列为第二大失能性疾病。"},"patho":"三叉神经血管系统激活是核心：硬脑膜血管周围三叉神经末梢释放 CGRP、P 物质与神经激肽 A，引起神经源性炎症与血管扩张；脑干中脑导水管周围灰质与三叉神经脊束核功能异常导致痛觉敏化。先兆由皮层扩散性抑制（CSD）引起，以约 3 mm/min 速度在皮层扩布，造成局部血流变化与神经元去极化。CGRP 通路是曲普坦类与 CGRP 单抗的共同靶点。","dx":{"criteria":["无先兆偏头痛（ICHD-3）：符合下列 2–4 项中的至少 2 项——单侧、搏动性、中或重度、日常活动加重或避免日常活动","且发作时至少 1 项——恶心和/或呕吐、畏光及畏声","且符合：未经治疗时发作持续 4–72 小时；发作 ≥5 次","有先兆偏头痛：至少 1 种完全可逆的先兆症状（视觉最常见，其次感觉、言语），先兆逐渐发展 ≥5 分钟、每项持续 5–60 分钟，头痛在先兆期间或 60 分钟内出现","慢性偏头痛：头痛 ≥15 天/月且其中 ≥8 天符合偏头痛特征，持续 >3 个月"],"workup":["典型发作者不需常规影像；按 ICHD-3 诊断即可确立","需影像（头颅 CT/MRI）的红旗征：50 岁后新发、突发剧烈（雷击样）、进行性加重、伴发热或颈强、伴局灶体征、癌症或免疫抑制病史、体位相关、妊娠或产褥期新发","评估药物过度使用：单纯镇痛药 ≥15 天/月或曲普坦/复方制剂 ≥10 天/月连续 >3 个月","记录头痛日记（发作频率、强度、诱因、用药）是疗效评估的基础"],"grading":"按发作频率分：发作性偏头痛（<15 天/月）与慢性偏头痛（≥15 天/月）；按先兆分：有先兆、无先兆、偏头痛等位症（如腹型、前庭性）。"},"ddx":[{"name":"紧张型头痛（ne_tension_cluster）","point":"与紧张型头痛的鉴别：紧张型双侧紧箍样、轻中度、不因活动加重、极少伴呕吐，发作时通常可继续工作。"},{"name":"丛集性头痛（ne_tension_cluster）","point":"与丛集性头痛的鉴别：丛集性单侧眶周钻痛、持续 15–180 分钟、伴同侧结膜充血/流泪/鼻塞，患者坐立不安；偏头痛患者多需静卧避光。"},{"name":"蛛网膜下腔出血","point":"雷击样头痛（数秒达峰）伴颈强、呕吐、意识改变；CT 在 6 小时内敏感度高，必要时腰穿见均匀血性/黄变。"},{"name":"颅内占位","point":"进行性加重、晨起明显、伴喷射性呕吐或局灶体征，需影像。"},{"name":"颞动脉炎","point":"≥50 岁、颞部压痛、ESR 显著升高、咀嚼停顿，需激素并排查视力威胁。"},{"name":"继发于高血压急症","point":"血压显著升高伴靶器官损害，降压后头痛缓解。"}],"tx":{"drug":[{"name":"布洛芬","dose":"400–600 mg 口服，单次；每月使用不超过 10–15 天以防药物过度使用性头痛","note":"轻中度发作首选 NSAIDs；消化道溃疡、肾功能不全慎用","renal":"eGFR <30 避免使用","hepatic":"重度肝病禁用","interact":"与抗凝、抗血小板合用增加消化道出血风险"},{"name":"对乙酰氨基酚","dose":"1000 mg 口服，单次；每日总量不超过 3 g","note":"妊娠期首选的急性期用药","renal":"CrCl <30 需延长给药间隔","hepatic":"肝病者每日 ≤2 g，活动性肝病禁用","interact":"长期大量饮酒者肝毒性增加"},{"name":"舒马曲坦（皮下）","dose":"6 mg 皮下注射，24 h 内不超过 12 mg","note":"发作早期使用效果最好；丛集性头痛也适用","renal":"严重肾功能不全禁用","hepatic":"重度肝损害禁用","interact":"24 h 内禁用麦角类；与 SSRI 合用警惕 5-HT 综合征"},{"name":"利扎曲普坦 / 佐米曲普坦（口服）","dose":"利扎曲普坦 10 mg 口服，2 h 后可重复，日最大 30 mg；佐米曲普坦 2.5–5 mg 口服，日最大 10 mg","note":"NSAIDs 无效的中重度发作首选曲普坦类","renal":"严重肾功能不全慎用","hepatic":"重度肝损害禁用","interact":"禁与麦角胺、MAO 抑制剂合用；与 SSRI/SNRI 合用需权衡 5-HT 综合征"},{"name":"甲氧氯普胺","dose":"10 mg 静脉或肌注，可与镇痛药联合","note":"兼具止吐与促胃动力，改善口服药吸收","renal":"CrCl <30 减量","hepatic":"遵说明书","interact":"与抗精神病药合用增加锥体外系反应"},{"name":"普萘洛尔（预防）","dose":"起始 40 mg bid 或缓释 80 mg qd，常用 40–120 mg/d，可增至 160 mg/d","note":"一线预防用药，需观察 8–12 周疗效；哮喘、心动过缓禁用","renal":"肾功能不全无需调整","hepatic":"肝硬化者显著减量","interact":"与维拉帕米/地尔硫卓合用可致心脏传导阻滞；掩盖低血糖"},{"name":"托吡酯（预防）","dose":"起始 25 mg qn，每周递增 25 mg，目标 50–100 mg/d（分 2 次），最大 200 mg/d","note":"减重与认知迟钝（找词困难）为常见不良反应；肾结石者慎用；妊娠期禁用（致畸）","renal":"CrCl <70 减半剂量","hepatic":"遵说明书","interact":"与口服避孕药合用降低避孕效果；与其他碳酸酐酶抑制剂合用增加结石风险"},{"name":"丙戊酸钠（预防）","dose":"400–800 mg/d 分 2 次；需监测血药浓度与肝功能","note":"育龄女性禁用（致畸与多囊卵巢）；肝病禁用","renal":"遵说明书","hepatic":"活动性肝病禁用","interact":"与拉莫三嗪合用显著增加皮疹（Steven-Johnson）风险"},{"name":"依瑞奈尤单抗（CGRP 受体单抗，预防）","dose":"70 mg 皮下每月 1 次或 140 mg 皮下每 2 周 1 次（遵说明书）","note":"难治性偏头痛（≥2 种预防药失败）可用；禁忌不多，主要用于每月 ≥4 天中重度头痛者","renal":"无需调整","hepatic":"遵说明书","interact":"无显著 CYP 相互作用"}],"nonDrug":["识别并规避诱因（睡眠规律、限制酒精与咖啡因、避免强光与噪音）","认知行为治疗与生物反馈：证据支持用于慢性偏头痛","规律有氧运动（每周 3 次、每次 30 分钟）可减少发作频率","枕神经阻滞或 A 型肉毒毒素注射：用于慢性偏头痛（每 12 周一次，需专科执行）","针灸：多项 RCT 显示与预防药物相当，可作为辅助"],"life":["建立头痛日记，记录发作频率与用药次数","严格控制急性期用药天数，防止药物过度使用性头痛","女性有先兆偏头痛者吸烟 + 口服避孕药显著增加缺血性卒中风险，应避免","育龄女性计划妊娠前需停用丙戊酸钠与托吡酯","心理筛查：慢性偏头痛常合并焦虑抑郁，需同时处理"]},"prog":"多数患者发作频率随年龄增长而减少，绝经后常明显缓解。慢性偏头痛者在规范预防与限制急性期用药后约 50%–70% 可转为发作性。药物过度使用与共病抑郁症是预后不良的预测因素。","refs":["《中国偏头痛诊治指南（2022 版）》（中华医学会神经病学分会）","《中国偏头痛诊断与治疗指南（2016）》","Headache Classification Committee of the IHS. ICHD-3. Cephalalgia 2018;38:1-211","2018 AHS/AAN Consensus Statement on Integrating New Migraine Treatments","2021 EHF Consensus on CGRP Monoclonal Antibodies"]},{"id":"ne_tension_cluster","name":"紧张型头痛与丛集性头痛","aka":["Tension-type Headache","TTH","Cluster Headache","CH"],"rank":2,"basic":{"define":"紧张型头痛：双侧压迫或紧箍样、轻至中度、不因日常活动加重、不伴呕吐、可有畏光或畏声但不同时存在。丛集性头痛：单侧眶周/颞部剧烈疼痛，伴同侧自主神经症状与躁动，呈丛集性发作（一段时期内每日定时发作）。","risk":["紧张型：女性多见，精神压力、睡眠障碍、颈肩肌筋膜触发点、焦虑抑郁","丛集性：男性显著多见（男:女约 3–4:1），吸烟与饮酒（发作期），下丘脑昼夜节律紊乱"],"epi":"紧张型头痛是最常见的原发性头痛，终生患病率约 30%–78%；丛集性头痛相对少见，患病率约 0.1%，男性高发、20–40 岁起病。"},"patho":"紧张型头痛：颅周肌肉持续性收缩与肌筋膜触发点致外周痛觉感受器敏化，长期可致中枢痛觉处理异常（中枢敏化与下行抑制减弱），与焦虑抑郁的共病尤为突出。丛集性头痛：下丘脑后部（尤其视交叉上核）参与昼夜节律启动，三叉-面神经反射激活导致同侧流泪、流涕与眼睑下垂；三叉神经血管系统与副交感（翼腭神经节）共同参与；发作期颈静脉 CGRP 显著升高。","dx":{"criteria":["紧张型头痛（ICHD-3）：发作持续 30 分钟至 7 天；至少符合 2 项——双侧、压迫或紧箍样（非搏动）、轻至中度、不因日常体力活动加重；且符合 2 项——无恶心呕吐、畏光与畏声不同时存在","慢性紧张型头痛：头痛 ≥15 天/月持续 >3 个月","丛集性头痛（ICHD-3）：至少 5 次发作；单侧眶周/眶上和或颞部重度疼痛持续 15–180 分钟；伴同侧至少 1 项——结膜充血/流泪、鼻塞/流涕、眼睑水肿、前额与面部出汗、瞳孔缩小/上睑下垂；或伴躁动","发作频率：隔日 1 次至每日 8 次；丛集期常持续数周至数月，缓解期 ≥1 个月","均为临床诊断，不依赖影像；首次发作需影像排除继发"],"workup":["确认头痛日记：发作时间点在丛集性头痛诊断中至关重要（常夜间同一时段）","首次发作或性质改变时行头颅增强 MRI 或 CT，临床疑垂体病变（垂体腺瘤可表现为周期性头痛）时加做垂体区薄层 MRI","眼部检查：急性闭角型青光眼可类似丛集性（但瞳孔散大、眼压高）","鉴别三叉神经痛：后者为瞬时电击样（数秒）触发痛，不伴自主神经症状"],"grading":"紧张型头痛分偶发性（<1 天/月）、频发性（1–14 天/月）与慢性（≥15 天/月）；丛集性头痛分发作性（丛集期 7 天–1 年，缓解期 ≥1 个月）与慢性（缓解期 <1 个月或丛集期 >1 年）。"},"ddx":[{"name":"偏头痛（ne_migraine）","point":"与偏头痛的鉴别：偏头痛单侧搏动性、活动加重、必有恶心或畏光畏声同时存在；紧张型双侧压迫感且能继续日常活动；丛集性为眶周钻痛并伴显著躁动。"},{"name":"三叉神经痛","point":"瞬时电击样（数秒至 2 分钟）、有扳机点（洗脸、刷牙）、不伴自主神经症状，卡马西平有效。"},{"name":"急性闭角型青光眼","point":"眼压显著升高、瞳孔中度散大固定、角膜水肿、视力骤降，为眼科急症。"},{"name":"鼻窦炎","point":"脓涕、发热、鼻窦区压痛，影像见窦腔液平。"},{"name":"颞下颌关节紊乱","point":"咀嚼/张口诱发、关节弹响、咬肌压痛。"},{"name":"继发性头痛红旗征","point":"雷击样、发热颈强、局灶体征、50 岁后新发、进行性加重、体位相关，需立即影像。"}],"tx":{"drug":[{"name":"布洛芬（紧张型）","dose":"200–400 mg 口服，发作时按需，每月不超过 15 天","note":"偶发性紧张型头痛可用；慢性者避免长期使用以防药物过度使用性头痛","renal":"eGFR <30 避免","hepatic":"重度肝病禁用","interact":"与抗凝合用增加出血"},{"name":"对乙酰氨基酚（紧张型）","dose":"500–1000 mg 口服，日不超过 3 g","note":"妊娠期首选","renal":"CrCl <30 延长间隔","hepatic":"每日 ≤2 g","interact":"长期饮酒增加肝毒性"},{"name":"阿米替林（紧张型预防）","dose":"起始 10–25 mg qn，逐渐增至 25–75 mg qn","note":"慢性紧张型头痛预防的一线；老年与前列腺增生者从 10 mg 起，注意口干、便秘、尿潴留与体位性低血压","renal":"遵说明书","hepatic":"肝病者减量","interact":"与 SSRI、曲普坦合用增加 5-HT 综合征风险；与抗胆碱药合用加重抗胆碱反应"},{"name":"高流量吸氧（丛集性）","dose":"100% 氧气 12 L/min，面罩（带储气袋）吸入 15 分钟，发作起始即用","note":"丛集性头痛急性期首选，无条件用曲普坦时尤为重要；需专用高流量面罩","renal":"无","hepatic":"无","interact":"COPD 患者注意二氧化碳潴留（丛集性头痛患者少见）"},{"name":"舒马曲坦（丛集性）","dose":"6 mg 皮下注射，24 h 内最多 12 mg；或鼻喷 20 mg","note":"起效快（约 15 分钟），急性期最有效的药物之一","renal":"严重肾功能不全禁用","hepatic":"重度肝损害禁用","interact":"禁与麦角类、MAO 抑制剂合用"},{"name":"维拉帕米（丛集性预防）","dose":"起始 80 mg tid，逐步增至 240–480 mg/d；起始前与每次加量后查心电图（观察 PR 间期）","note":"丛集性头痛预防的一线；需在丛集期开始前用至最大耐受剂量；观察便秘、水肿、心动过缓","renal":"遵说明书","hepatic":"肝硬化者减量","interact":"与 β 阻滞剂合用增加心脏传导阻滞风险；升高地高辛与辛伐他汀血药浓度"},{"name":"泼尼松（丛集性过渡治疗）","dose":"30–60 mg/d 口服，3–5 天后快速减量（约 10–14 天内撤停）","note":"用于维拉帕米起效前的过渡，不能作为长期维持；糖尿病、感染、骨质疏松者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道溃疡风险；降低降糖药效果"},{"name":"枕大神经阻滞（过渡）","dose":"利多卡因/布比卡因 + 甲泼尼龙，由专科操作","note":"起效快，可作为丛集期开始时的短期过渡","renal":"无","hepatic":"无","interact":"无特殊"}],"nonDrug":["识别并纠正颈肩肌筋膜触发点：物理治疗、颈部肌肉牵伸与放松训练","紧张型头痛的心理干预：认知行为治疗、放松训练与生物反馈有循证支持","丛集性头痛：避免酒精（发作期饮酒可在 1 小时内诱发发作）","丛集性头痛难治者可考虑枕大神经阻滞、蝶腭神经节阻滞或迷走神经刺激","避免长期卧床与睡眠不足（两者均可诱发）"],"life":["记录头痛日历，尤其记录丛集期的起始与结束，帮助提前用药","吸烟者建议戒烟（与丛集性头痛的慢性化相关）","慢性紧张型头痛常合并焦虑抑郁，需同步心理评估与干预","限制急性期用药天数（简单镇痛药 ≤15 天/月，曲普坦 ≤10 天/月）","驾车或高空作业者使用阿米替林初期注意日间嗜睡"]},"prog":"紧张型头痛多数病程良性、可自行缓解，但慢性化后与焦虑抑郁互为因果，需长期管理。丛集性头痛为发作性病程，约 10%–15% 转为慢性，吸烟与男性为慢性化危险因素；规范的维拉帕米预防可显著缩短丛集期。","refs":["《中国偏头痛诊治指南（2022 版）》（中华医学会神经病学分会）","Headache Classification Committee of the IHS. ICHD-3. Cephalalgia 2018;38:1-211","2016 AHS Evidence Assessment: Acute Treatment of Cluster Headache","2016 AHS Guideline: Prevention of Cluster Headache (verapamil)","《紧张型头痛诊疗专家共识》（中华医学会疼痛学分会）"]},{"id":"ne_vad","name":"血管性痴呆与额颞叶痴呆","aka":["Vascular Dementia","VaD","Frontotemporal Dementia","FTD"],"rank":3,"basic":{"define":"血管性痴呆：由脑血管病（缺血或出血）引起的认知障碍，强调认知下降与血管事件的时序关系及影像学证据，是仅次于阿尔茨海默病的第二位痴呆病因。额颞叶痴呆：以行为变异型（bvFTD）或语言变异型（原发性进行性失语）为核心，以额颞叶萎缩为特征，通常 45–65 岁起病。","risk":["血管性痴呆：高血压、糖尿病、血脂异常、房颤、吸烟、既往卒中或 TIA、白质病变严重","额颞叶痴呆：家族史（约 30%–40%，MAPT、GRN、C9orf72 突变）、年龄 45–65 岁"],"epi":"血管性痴呆约占全部痴呆的 15%–20%，亚洲人群中比例更高（约 20%–30%）；卒中后 3 个月内约 20%–30% 出现认知障碍。额颞叶痴呆是早发性痴呆（<65 岁）的第二常见原因，约占 10%–20%。"},"patho":"血管性痴呆：多发梗死（尤其是丘脑、基底节、角回等关键部位）、皮层下白质缺血（小血管病）、微出血与脑淀粉样血管病均可破坏皮层-皮层下环路，导致执行功能与信息处理速度下降；胆碱能通路（基底节-额叶）受累可解释部分患者对胆碱酯酶抑制剂的反应。额颞叶痴呆：TDP-43 或 Tau 蛋白异常聚集（GRN 突变致 TDP-43；MAPT 突变致 Tau），选择性累及额叶与颞叶前部，导致人格改变、脱抑制与语言障碍。","dx":{"criteria":["血管性痴呆（NINDS-AIREN 与 VASCOG 标准要点）：存在认知障碍（多个认知域受累，影响日常生活）且有脑血管病证据（病史、体征或影像）","且两者时间相关：认知障碍在卒中后 3 个月内发生，或呈阶梯式进展、波动性病程","影像支持：多发梗死、关键部位梗死（丘脑、角回、基底节）、广泛白质病变（Fazekas 3 级）或脑微出血","行为变异型额颞叶痴呆（Rascovsky 2011 标准，需满足 ≥3 项）：早期脱抑制、早期淡漠或惰性、早期同情/共情丧失、持续刻板或强迫行为、过度口欲（贪食甜食）、神经心理测验示执行功能相对保留而记忆相对保留","语言变异型：原发性进行性失语（语义型或非流利/语法缺失型），语言障碍为最早且最突出的表现"],"workup":["认知量表：MMSE（受教育程度影响大）、MoCA（对执行与视空间更敏感）、CDR 与 ADL 评估","影像：头颅 MRI（首选，评估梗死部位、白质病变 Fazekas 分级、内侧颞叶萎缩）；额颞叶痴呆见额叶与颞叶前部萎缩（MRI 或 SPECT/PET 低代谢）","血管评估：颈动脉超声、经颅多普勒、必要时 CTA/MRA；心源性栓塞评估（房颤、超声心动）","实验室：血常规、生化、甲状腺功能、维生素 B12、叶酸、梅毒血清学、HIV（可逆性病因筛查）","神经心理成套测验：区分皮层性（失语、失用）与皮层下性（执行与速度下降）模式","与阿尔茨海默病鉴别：AD 以近记忆受损为早期核心，影像见内侧颞叶萎缩；必要时 PET 或脑脊液 Aβ/tau"],"grading":"血管性痴呆按病因分：多发梗死性、关键部位梗死性、小血管病性（皮层下）、分水岭梗死性、出血性与混合性。额颞叶痴呆分行为变异型（bvFTD）、语义型原发性进行性失语（svPPA）与非流利/语法缺失型（nfvPPA）。"},"ddx":[{"name":"路易体痴呆（ne_dlb）","point":"与路易体痴呆的鉴别：DLB 以波动性认知、真性视幻觉与自发性帕金森综合征为特征，早期即对神经阻滞剂高度敏感；额颞叶痴呆以人格改变与语言障碍为核心，无显著视幻觉。"},{"name":"阿尔茨海默病","point":"AD 早期以近记忆（情景记忆）受损为核心，进展缓慢且无阶梯式恶化；额颞叶痴呆早期记忆相对保留而行为/语言突出。"},{"name":"偏头痛（ne_migraine）","point":"部分偏头痛患者主诉记忆下降与「脑雾」，但不满足认知障碍影响日常生活标准，且无影像血管病变。"},{"name":"抑郁性假性痴呆","point":"起病较急、症状与情绪相关、答案多「我不知道」、抗抑郁治疗后改善。"},{"name":"正常压力脑积水","point":"步态障碍 + 尿失禁 + 认知下降三联征，影像见脑室扩大与 DESH 征，放液试验后步态改善。"},{"name":"甲状腺功能减退与维生素 B12 缺乏","point":"可逆性认知障碍，化验即可确认，需常规筛查。"}],"tx":{"drug":[{"name":"多奈哌齐（血管性痴呆）","dose":"5 mg qn 起始，4 周后增至 10 mg qn","note":"对血管性痴呆的认知与整体功能有轻度改善（证据弱于 AD）；心动过缓、房室传导阻滞者慎用","renal":"无需调整","hepatic":"轻中度无需调整，重度慎用","interact":"与 β 阻滞剂、地高辛合用增加心动过缓与晕厥风险；与抗胆碱药作用相互拮抗"},{"name":"美金刚（血管性或混合性）","dose":"起始 5 mg qd，每周递增 5 mg，目标 20 mg/d","note":"用于中重度患者，可与胆碱酯酶抑制剂联用","renal":"CrCl <30 减半剂量","hepatic":"重度肝损害慎用","interact":"与金刚烷胺、右美沙芬合用增加中枢神经系统不良反应"},{"name":"阿司匹林（二级预防）","dose":"100 mg qd","note":"缺血性卒中/ TIA 后用于预防复发；无血管事件者不常规使用（一级预防证据不足）","renal":"eGFR <30 慎用","hepatic":"活动性肝病禁用","interact":"与抗凝或其他抗血小板合用增加出血风险"},{"name":"氯吡格雷","dose":"75 mg qd（阿司匹林不耐受或大动脉粥样硬化性卒中急性期后）","note":"与阿司匹林联用（双抗）仅在特定短期情形（如轻型卒中/高危 TIA 21 天）","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"避免与奥美拉唑、埃索美拉唑合用（CYP2C19 抑制降低活性代谢物生成）"},{"name":"他汀（阿托伐他汀/瑞舒伐他汀）","dose":"阿托伐他汀 20–40 mg qn；瑞舒伐他汀 10–20 mg qn","note":"按 ASCVD 极高危目标 LDL-C <1.4 mmol/L 且降幅 ≥50%","renal":"瑞舒伐他汀严重肾功能不全（CrCl <30）起始 5 mg","hepatic":"活动性肝病禁用；转氨酶 >3 倍上限评估停药","interact":"与贝特类、CYP3A4 抑制剂（大环内酯、唑类抗真菌药）合用增加肌病风险"},{"name":"SSRI（额颞叶痴呆行为症状）","dose":"西酞普兰 10–20 mg qd 或舍曲林 25–50 mg qd","note":"bvFTD 的脱抑制与强迫行为可试用 SSRI，证据有限；曲唑酮 25–50 mg qn 也可用于睡眠与激越","renal":"遵说明书","hepatic":"肝病者减量","interact":"与曲马多、曲普坦、MAO 抑制剂合用警惕 5-HT 综合征；与抗凝合用增加出血"},{"name":"抗精神病药（谨慎）","dose":"噻硫平 12.5–25 mg qn 起始，或奥氮平 2.5 mg qn","note":"仅在严重激越、自伤或伤人有风险时短期使用；黑框警告：痴呆患者使用增加死亡风险与脑血管事件","renal":"遵说明书","hepatic":"肝病者减量","interact":"与 QT 延长药物合用增加心律失常风险；与胆碱酯酶抑制剂合用增加锥体外系与抗胆碱反应"}],"nonDrug":["严格血管危险因素管控：血压（老年可耐受 SBP 130–140 mmHg）、血糖、血脂、戒烟","房颤患者规范抗凝（推荐 DOAC），预防再发栓塞","认知康复与行为干预：记忆辅助策略、环境调整与照护者培训","规律运动与地中海饮食：流行病学证据支持降低痴呆风险","额颞叶痴呆重点在行为管理与照护者支持，避免使用经典抗精神病药"],"life":["家居安全：防跌倒、防走失（定位设备与身份标识）、厨房与燃气安全","照护者负担筛查与支持（Zarit 量表），必要时引入日间照护或专业护理","驾车能力评估，中重度痴呆应停止驾驶","预先医疗照护计划与财务法律安排（尽早完成）","避免不必要的多重用药，尤其抗胆碱负荷高的药物（加重认知）"]},"prog":"血管性痴呆的病程呈阶梯式或波动性进展，5 年生存率约 50%–60%，与卒中复发、心血管事件和并存疾病相关；危险因素管控可延缓进展。额颞叶痴呆进展较 AD 快，诊断后中位生存 3–10 年，最终丧失自理能力，死因多为并发症（肺部感染、吞咽障碍）。","refs":["《中国痴呆与认知障碍诊治指南（2015）》及 2023 更新（中华医学会神经病学分会）","《血管性认知障碍诊治指南（2021）》（中华医学会神经病学分会）","Rascovsky K, et al. Sensitivity of revised diagnostic criteria for the behavioural variant of FTD. Brain 2011;134:2456-77","2021 NINDS-AIREN 与 VASCOG 标准（血管性认知障碍）","2018 AAN Position Statement: Driving and Dementia"]},{"id":"ne_dlb","name":"路易体痴呆","aka":["Dementia with Lewy Bodies","DLB"],"rank":4,"basic":{"define":"以波动性认知障碍、真性视幻觉、自发性帕金森综合征与 REM 睡眠行为障碍（RBD）为核心特征的神经变性性痴呆，脑内存在广泛的路易体（α-突触核蛋白沉积），是帕金森病痴呆（PDD）在病理谱上的延续。","risk":["年龄（多 60 岁以后）","男性略多见","RBD 作为前驱期标志（可早于痴呆数年）","APOE ε4 携带与部分 GBA 突变","帕金森病家族史"],"epi":"DLB 约占全部痴呆的 5%（10%–15% 含伴病理），在 60 岁以上人群中患病率约 0.4%–4%，是仅次于 AD 与血管性痴呆的第三位常见痴呆。"},"patho":"α-突触核蛋白异常聚集成路易体，广泛累及新皮层、边缘系统、伏隔核与脑干（黑质、蓝斑、迷走神经背核），并伴突触素与乙酰胆碱转移酶减少。皮层乙酰胆碱能缺损相对早而重，DLB 对胆碱酯酶抑制剂反应好；黑质多巴胺能神经元减少导致帕金森综合征。按 Braak 分期，病变由延髓向上进展，这可解释 REM 睡眠行为障碍常早于认知症状。DLB 与 AD 病理常并存（混合性病理）。","dx":{"criteria":["必需条件：渐进性认知下降，达到痴呆标准（影响日常独立生活能力），且早期即出现注意与执行/视空间功能障碍（近记忆障碍可不显著）","核心临床特征（满足 ≥2 项即可诊断为 probable DLB；1 项为 possible）：① 波动性认知（注意与警觉显著变化）；② 反复出现的真性视幻觉（通常形态清晰、细节丰富）；③ 自发性帕金森综合征（运动迟缓 + 强直或静止性震颤）；④ REM 睡眠行为障碍（多导睡眠图确诊或临床问卷高度可疑）","提示性生物标志物：基底节多巴胺转运体摄取降低（DAT-SPECT/PET）、心肌 MIBG 摄取降低、PSG 证实 RBD","支持性临床特征：反复跌倒与晕厥、对神经阻滞剂高度敏感、严重自主神经功能障碍（体位性低血压、便秘、尿失禁）、其他形式幻觉（视空间障碍、Capgras 妄想）"],"workup":["认知量表：MoCA 优于 MMSE（对注意与视空间更敏感）；CDR 与 ADL 评估","头颅 MRI：内侧颞叶萎缩相对轻（与 AD 鉴别的细节），但混合病理者不可靠","多巴胺转运体显像（DAT-SPECT/PET）：基底节摄取对称性降低支持 DLB（支持性证据）","多导睡眠图（PSG）：证实 RBD（REM 期肌张力失弛缓）是极强的提示性证据","自主神经检查：卧立位血压、心率变异性","排除可逆性病因：甲功、B12、梅毒、药物性（抗胆碱能负荷）"],"grading":"按 2017 年第四次 DLB 国际共识：probable DLB（痴呆 + ≥2 项核心特征，或 1 项核心特征 + ≥1 项提示性生物标志物）；possible DLB（痴呆 + 1 项核心特征，或核心特征缺失但提示性生物标志物阳性）。"},"ddx":[{"name":"血管性痴呆与额颞叶痴呆（ne_vad）","point":"与血管性痴呆的鉴别：血管性痴呆为阶梯式进展、影像见梗死或广泛白质病变，视幻觉少见；DLB 早期即波动性认知伴视幻觉。与额颞叶痴呆的鉴别：FTD 以人格改变与语言障碍为核心，无显著视幻觉。"},{"name":"偏头痛（ne_migraine）","point":"偏头痛患者常有「脑雾」但认知量表多正常，发作性而非进行性，影像无特殊；DLB 为进行性功能下降。"},{"name":"帕金森病痴呆（PDD）","point":"关键在时序：认知障碍在帕金森运动症状出现 1 年后才发生者为 PDD，早于或同时（1 年内）出现者为 DLB；两者病理谱相同，处理原则相近。"},{"name":"阿尔茨海默病","point":"AD 以近记忆受损为核心、早期无帕金森综合征与视幻觉，内侧颞叶与海马显著萎缩。"},{"name":"谵妄","point":"急性起病、注意力涣散、有明确诱因（感染、药物、电解质），去除诱因后恢复；DLB 的波动为慢性长期。"},{"name":"抗精神病药诱导的帕金森综合征","point":"有用药史，停药后数周至数月改善，无波动性认知与视幻觉谱。"}],"tx":{"drug":[{"name":"多奈哌齐","dose":"5 mg qn 起始，4 周后可增至 10 mg qn","note":"DLB 对胆碱酯酶抑制剂反应优于 AD（皮层胆碱能缺损更重），对认知与幻觉均有改善；心动过缓与晕厥风险（DLB 易合并体位性低血压）","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"与 β 阻滞剂、地高辛合用增加晕厥；抗胆碱药拮抗其作用"},{"name":"卡巴拉汀（经皮贴剂）","dose":"4.6 mg/24 h 贴片起始，每 4 周递增至 9.5 mg/24 h，最大 13.3 mg/24 h","note":"贴剂胃肠耐受性更好，适合吞咽困难或胃肠道敏感者；贴片部位需每日更换","renal":"遵说明书","hepatic":"重度肝损害慎用","interact":"同多奈哌齐"},{"name":"左旋多巴 / 卡比多巴（帕金森症状）","dose":"起始 左旋多巴 100 mg bid 或 tid，小剂量滴定","note":"对 DLB 的帕金森症状疗效不如帕金森病，且易诱发幻觉与体位性低血压，需小剂量起始","renal":"无需调整","hepatic":"遵说明书","interact":"禁与非选择性 MAO 抑制剂合用；与抗精神病药（D2 拮抗剂）作用相互拮抗"},{"name":"喹硫平（精神症状）","dose":"起始 12.5 mg qn，缓慢增至 25–50 mg qn","note":"DLB 患者对神经阻滞剂高度敏感，可出现严重僵直、意识障碍甚至致死性反应（黑框警告：痴呆患者使用增加死亡风险）；仅在必需时用最小剂量","renal":"遵说明书","hepatic":"肝病者减量","interact":"与其他 QT 延长药合用增加心律失常风险"},{"name":"氯氮平（难治性精神病性症状）","dose":"12.5–25 mg qn 起始，需监测血常规（粒细胞缺乏风险）","note":"锥体外系反应最少，但需每周血象监测（前 6 个月），不作为首选","renal":"遵说明书","hepatic":"肝病者慎用","interact":"与 CYP1A2 抑制剂（氟伏沙明、环丙沙星）合用显著升高血药浓度"},{"name":"米多君 / 氟氢可的松（体位性低血压）","dose":"米多君 2.5–5 mg tid（日间），氟氢可的松 0.1–0.3 mg qd","note":"先做非药物措施（弹力袜、增加盐与水摄入、缓慢起身、抬高床头）；米多君可致卧位高血压","renal":"肾功能不全者米多君慎用","hepatic":"遵说明书","interact":"米多君与 β 阻滞剂、三环类合用可致严重高血压"}],"nonDrug":["优先非药物管理行为与精神症状：识别诱因（疼痛、便秘、感染）、环境调整、照护者教育与安抚","跌倒预防：家居改造、助行器、体位性低血压的非药物处理（弹力袜、慢起立）","REM 睡眠行为障碍：卧室安全（移开尖锐物、床垫放地上），必要时用褪黑素或小剂量氯硝西泮（注意跌倒与呼吸抑制）","认知康复与物理治疗（平衡与步态训练）","避免抗胆碱能负荷高的药物与经典抗精神病药（氟哌啶醇、利培酮在 DLB 中尤其危险）"],"life":["建立药物清单并定期复核：任何新加药前评估对认知、血压与锥体外系的影响","照护者需知悉「对神经阻滞剂极度敏感」这一关键信息，就诊时主动告知","防走失与居家安全（波动性认知使走失风险高于 AD）","预先医疗照护计划，明确吞咽障碍与终末期的处理意愿","定期筛查抑郁（DLB 中常见）与便秘"]},"prog":"DLB 进展速度介于 AD 与 FTD 之间，诊断后中位生存约 5–8 年；认知下降与帕金森症状逐渐加重，晚期常因吞咽障碍、跌倒后并发症与感染死亡。照护者负担高于 AD（行为与睡眠问题突出）。早期识别药物敏感性可显著减少医源性伤害。","refs":["《中国痴呆与认知障碍诊治指南（2015）》及 2023 更新（中华医学会神经病学分会）","McKeith IG, et al. Diagnosis and management of dementia with Lewy bodies: Fourth consensus report of the DLB Consortium. Neurology 2017;89:88-100","2019 AAN Practice Guideline: Mild Cognitive Impairment","2015 EFNS/ENS Guidelines for the diagnosis and management of neuropathies（RBD 部分参照睡眠医学指南）"]}]},{"id":"cns_infect_spine","name":"中枢感染与脊髓疾病","rank":6,"summary":"脑膜炎先按「病原-时程-免疫状态」三维分层：细菌性要抢时间（腰穿禁忌先影像），结核与隐球菌看脑脊液糖氯与压力；脊髓病变的核心是尽早识别压迫与激素指征。","compare":[{"diseaseId":"ne_viral_enceph","dx":"发热 + 意识障碍或精神行为异常 + 局灶体征，脑脊液淋巴细胞为主、糖正常，MRI 见颞叶/额叶异常信号","key":"意识障碍突出而脑膜刺激征可轻；HSV 脑炎好发颞叶、需立即阿昔洛韦"},{"diseaseId":"ne_tb_meningitis","dx":"亚急性起病、低热盗汗、脑脊液压力高、蛋白显著升高、糖氯双低、淋巴细胞为主，基底池脑膜强化","key":"糖氯双低 + 蛋白极高 + 基底池强化；需四联抗结核并加激素"},{"diseaseId":"ne_cryptococcal","dx":"亚急性头痛发热、脑脊液墨汁染色或隐球菌抗原阳性、压力常显著升高，多见于免疫抑制者","key":"抗原阳性即可诊断；关键在控制颅内压与诱导期两性霉素 B"},{"diseaseId":"ne_myelitis","dx":"急性或亚急性截瘫、感觉平面、尿潴留，MRI 见脊髓异常信号，需排除压迫","key":"先影像排除压迫再谈激素；压迫需 24–48 小时内减压"},{"diseaseId":"ne_nmosd","dx":"视神经炎 + 长节段横贯性脊髓炎（≥3 个椎体），血清 AQP4-IgG 阳性","key":"长节段脊髓炎 + 顽固呕吐/呃逆；AQP4 阳性用利妥昔单抗预防复发"}],"diseases":[{"id":"ne_viral_enceph","name":"病毒性脑炎（含单纯疱疹病毒脑炎）","aka":["Viral Encephalitis","Herpes Simplex Encephalitis","HSE","HSV 脑炎"],"rank":1,"basic":{"define":"病毒感染所致脑实质炎症，以发热、头痛、意识障碍或精神行为异常、癫痫发作为主要表现。单纯疱疹病毒（HSV-1 为主）脑炎是最凶险、且唯一有特效治疗的类型，好发于颞叶与额叶下部。","risk":["免疫抑制（器官移植、HIV、长期激素）","新生儿与老年人","季节（肠道病毒、乙脑在夏秋季）","蜱虫与蚊虫叮咬暴露（乙脑、莱姆病）","口唇疱疹反复发作史（HSV 再激活）"],"epi":"我国病毒性脑炎年发病率约 3–7/10 万，HSV 脑炎约占病毒性脑炎的 10%–20%，未治疗病死率 >70%，治疗后仍有约 1/3 遗留神经功能缺损。乙脑在夏秋季、农村地区高发，儿童为主。"},"patho":"HSV-1 经嗅神经或三叉神经节逆行至脑，偏好累及颞叶内侧、额叶眶面与边缘系统（与病毒受体在这些区域高表达有关），造成出血性坏死与水肿，可致颞叶钩回疝。其他病毒（肠道病毒、乙脑病毒、水痘-带状疱疹）经血行播散，引起弥漫性神经元损伤与血管周围炎性浸润；免疫介导的损伤在感染后数日成为主导，故抗病毒治疗需尽早（病毒复制期仅数天）。","dx":{"criteria":["临床：急性起病（<1 周）发热 + 头痛 + 意识障碍（嗜睡至昏迷）或精神行为异常 + 癫痫（HSE 中约 40%–60%）+ 局灶神经体征","脑脊液（关键）：压力正常或升高，白细胞 10–500×10⁶/L 以淋巴细胞为主，蛋白轻中度升高，糖正常（HSE 可轻度降低）","HSE 的脑脊液 PCR：HSV-1 DNA 阳性（敏感度 96%、特异度 99%），但发病 72 小时后或已有出血性坏死时可为阴性","影像：MRI 为首选，见颞叶内侧、岛叶、额叶眶面 T2/FLAIR 高信号，可伴出血与强化（颞叶不对称是关键线索）；CT 早期可正常","脑电图：颞区周期性一侧性癫痫样放电（PLEDs）有提示价值","排除其他：细菌性脑膜炎、结核、隐球菌、自身免疫性脑炎（抗 NMDAR 等）、代谢性脑病"],"workup":["腰椎穿刺（先行头颅影像排除占位与脑疝风险）：压力、常规、生化、涂片、培养、病毒 PCR（HSV、VZV、肠道病毒、EBV、CMV）","头颅 MRI 平扫 + 增强（首选）/ CT（急症）","脑电图（必要时长程视频脑电）","血培养、血常规、CRP、PCT、肝肾功能、电解质","免疫状态评估（HIV、淋巴细胞亚群）；疑自身免疫性脑炎者查血清与脑脊液自身抗体","重症需监测颅内压与脑灌注"],"grading":"按病因分 HSV、肠道病毒、乙脑、VZV 等；按病情分轻（意识清楚、无癫痫）、中（嗜睡、癫痫）、重（昏迷、脑疝、需 ICU）。HSE 的影像分级：单侧颞叶局限 vs 双侧或合并额叶/基底节受累（后者预后差）。"},"ddx":[{"name":"结核性脑膜炎（ne_tb_meningitis）","point":"与结核性脑膜炎的鉴别：结脑为亚急性（1–2 周）起病、脑脊液糖氯双低、蛋白显著升高、基底池脑膜强化；HSE 为急性起病、糖多正常、颞叶实质病变为主。"},{"name":"隐球菌脑膜炎（ne_cryptococcal）","point":"与隐球菌脑膜炎的鉴别：隐球菌脑膜炎脑脊液压力极高、墨汁染色与隐球菌抗原阳性，MRI 多无明显实质病变（可见血管周围间隙扩大）；HSE 有颞叶高信号。"},{"name":"脊髓炎与脊髓压迫（ne_myelitis）","point":"与脊髓疾病的鉴别：脊髓病变表现为截瘫、感觉平面与括约肌障碍，无意识障碍与癫痫；HSE 以皮质症状为主。"},{"name":"细菌性脑膜炎","point":"急起高热、颈强直明显、脑脊液中性粒细胞为主、糖降低、涂片与培养阳性，需抗生素而非单纯抗病毒。"},{"name":"自身免疫性脑炎","point":"精神症状与癫痫突出、脑脊液可正常或轻度异常、自身抗体（抗 NMDAR、抗 LGI1）阳性，影像可累及边缘系统；需与 HSE 鉴别（两者可重叠，HSE 后可继发）。"},{"name":"代谢性脑病与中毒","point":"有肝肾功能异常、血糖或电解质紊乱、药物毒物接触史，脑脊液无炎症改变，纠正病因后改善。"}],"tx":{"drug":[{"name":"阿昔洛韦（HSE 首选）","dose":"10 mg/kg 静脉滴注 q8h（按理想体重，每次输注 ≥1 小时），疗程 14–21 天；肾功能不全按 CrCl 调整（CrCl 25–50：10 mg/kg q12h；10–25：10 mg/kg q24h；<10：2.5–5 mg/kg q24h）","note":"疑诊 HSE 即应经验性给药，不必等 PCR 结果；充分水化以防结晶性肾病；监测中性粒细胞与肾功能","renal":"严格按 CrCl 减量；透析患者需在透析后补量","hepatic":"无需调整","interact":"与丙磺舒合用升高血药浓度；与肾毒性药物（氨基糖苷、两性霉素 B、环孢素）合用增加肾损伤"},{"name":"伐昔洛韦（轻症或序贯口服）","dose":"1000 mg 口服 q8h，疗程 14–21 天","note":"生物利用度优于口服阿昔洛韦，用于轻症或静脉治疗后的序贯；重症不用","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"同阿昔洛韦"},{"name":"更昔洛韦（CMV 脑炎）","dose":"5 mg/kg 静脉滴注 q12h，疗程 2–3 周，随后维持","note":"用于 CMV 脑炎（多见于免疫抑制者）；骨髓抑制显著","renal":"按 CrCl 减量","hepatic":"无需调整","interact":"与齐多夫定、霉酚酸酯合用增加骨髓抑制"},{"name":"甘露醇 / 高渗盐水（颅内压升高）","dose":"甘露醇 0.25–1 g/kg 静脉快速滴注 q6–8h；或 3% 高渗盐水 2–5 mL/kg 静脉输注，目标血钠 145–155 mmol/L","note":"用于脑水肿与颅内高压；需监测渗透压、肾功能与电解质；避免过度脱水致低血压","renal":"少尿或无尿时禁用甘露醇，改用高渗盐水","hepatic":"无需调整","interact":"与肾毒性药物合用增加肾损伤"},{"name":"左乙拉西坦 / 丙戊酸钠（癫痫控制）","dose":"左乙拉西坦 500–1000 mg 静脉负荷，随后 500–1000 mg q12h；丙戊酸钠 15–20 mg/kg 静脉负荷，随后 1 mg/kg/h","note":"HSE 患者癫痫发生率高，需积极控制；癫痫持续状态按相应流程处理","renal":"左乙拉西坦按 CrCl 调整","hepatic":"丙戊酸钠肝病禁用","interact":"丙戊酸钠与碳青霉烯类合用显著降低浓度（癫痫失控）"},{"name":"地塞米松（HSE 辅助，争议）","dose":"不推荐常规使用；仅用于明确颅内高压或影像见明显水肿时短期 10 mg 静脉 q6h（3–4 天）","note":"HSE 中激素的证据不足（与细菌性脑膜炎不同），可能抑制病毒清除；仅在颅内高压时权衡使用","renal":"无需调整","hepatic":"遵说明书","interact":"与抗凝、NSAIDs 合用增加消化道出血"}],"nonDrug":["气道保护与重症监护（昏迷、癫痫持续状态、脑疝风险者）","控制颅内压：抬高床头 30°、避免颈静脉受压、维持正常血压与氧合","维持水电解质平衡与营养支持","疫苗预防：乙脑疫苗（我国计划免疫）、HSV 无疫苗","隔离与防护（肠道病毒、乙脑经蚊媒传播需防蚊）"],"life":["出院后神经心理评估与康复（记忆、语言、执行功能），HSE 后约 1/3 遗留缺陷","抗癫痫药需根据脑电与临床决定疗程（HSE 后癫痫可在数月至数年内出现）","定期复查 MRI 与脑电（尤其有癫痫发作者）","避免免疫抑制与过度疲劳（HSV 再激活诱因）","儿童需评估学习能力与行为问题"]},"prog":"HSE 未治疗病死率 >70%，规范阿昔洛韦治疗后降至约 20%–30%，但约 1/3 存活者遗留明显神经功能缺损（记忆障碍、癫痫、行为改变）。预后与治疗启动时间密切相关——意识障碍出现后每延迟 1 天，预后显著恶化。其他病毒性脑炎多数预后较好（肠道病毒、乙脑除外，乙脑重症病死率可达 20%）。","refs":["《中国单纯疱疹病毒性脑炎诊治专家共识》（中华医学会神经病学分会，2019）","《病毒性脑炎诊断与治疗中国专家共识》（2021）","2017 IDSA Clinical Practice Guidelines for the Management of Encephalitis","2020 EFNS-ENS Guidelines on the Management of Viral Encephalitis","《中国自身免疫性脑炎诊治专家共识（2022 年版）》"]},{"id":"ne_tb_meningitis","name":"结核性脑膜炎","aka":["Tuberculous Meningitis","TBM","结脑"],"rank":2,"basic":{"define":"结核分枝杆菌经血行播散至脑膜与脑实质所致的慢性中枢神经系统感染，是肺外结核中最严重的形式，起病隐匿、致残率与病死率高。","risk":["肺结核或肺外结核病史/接触史","HIV 感染（尤其 CD4 <200/µL）","免疫抑制治疗（激素、TNF-α 拮抗剂）","营养不良、糖尿病、酗酒","儿童与老年人","结核高流行地区居住"],"epi":"我国结核病高负担国家，结脑约占结核患者的 1%–5%，在结核性脑膜炎高发地区占成人细菌性脑膜炎的 20%–30%。未治疗病死率近 100%，规范治疗后病死率仍约 20%–30%，约 25% 遗留神经后遗症。"},"patho":"结核分枝杆菌经血行播散在脑膜与脑皮质形成 Rich 灶，破裂后进入蛛网膜下腔，引起以脑底（基底池）为主的渗出性炎症。渗出物包绕脑神经（Ⅱ、Ⅲ、Ⅵ、Ⅶ）与 Willis 环血管，导致脑积水（渗出物阻塞蛛网膜颗粒）、脑梗死（血管炎）与脑神经麻痹。颅内压升高与脑积水是致死的主要原因，故激素与降颅压治疗是核心辅助手段。","dx":{"criteria":["亚急性或慢性起病（1–2 周以上）：低热、盗汗、乏力、头痛、恶心呕吐、逐渐加重的意识障碍与颈强直","脑脊液典型改变：压力升高（常 >200 mmH₂O）、外观清亮或微浊、白细胞 100–500×10⁶/L 以淋巴细胞为主（早期可中性粒细胞为主）、**蛋白显著升高（常 >1 g/L）**、**糖与氯化物双低**（糖 <2.5 mmol/L，氯化物 <120 mmol/L）","病原学证据：脑脊液涂片抗酸染色（阳性率仅 10%–20%）、结核培养（需 4–6 周，敏感度 30%–50%）、GeneXpert MTB/RIF（敏感度约 60%–80%，可同时查利福平耐药）、mNGS","影像：增强 MRI 见**基底池脑膜强化**（最特征）、脑积水、结核瘤、梗死灶","诊断依据：临床 + 脑脊液典型改变 + 病原或影像支持；病原阴性但高度疑似时应经验性抗结核治疗（延误治疗显著增加病死率）"],"workup":["腰椎穿刺（测初压，必要时诊断性治疗同时降颅压）：常规、生化、涂片、培养、GeneXpert、mNGS","头颅 MRI 平扫 + 增强（基底池强化、脑积水、结核瘤、梗死）——优于 CT","胸部 CT（查找肺部活动性结核，约半数有肺部病灶）","PPD 皮试与 IGRA（γ 干扰素释放试验）：辅助证据，不能单独确诊","HIV 检测（所有结脑患者必须做）","肝肾功能、血常规（抗结核治疗前基线）、视力与色觉（乙胺丁醇）","重症监测：意识、瞳孔、颅内压与脑脊液引流"],"grading":"MRC 分期（英国医学研究委员会）：Ⅰ 期——意识清楚、无局灶体征；Ⅱ 期——意识模糊或轻度局灶体征（如脑神经麻痹）；Ⅲ 期——昏迷、严重神经缺陷。分期是预后与疗程的重要依据（Ⅲ 期病死率显著升高）。"},"ddx":[{"name":"病毒性脑炎（ne_viral_enceph）","point":"与病毒性脑炎的鉴别：病毒性脑炎急性起病（数天）、脑脊液糖多正常、蛋白轻中度升高，影像见颞叶实质病变；结脑为亚急性起病、糖氯双低、蛋白显著升高、基底池强化。"},{"name":"隐球菌脑膜炎（ne_cryptococcal）","point":"与隐球菌脑膜炎的鉴别：隐球菌者脑脊液压力极高、隐球菌抗原或墨汁染色阳性，多见于免疫抑制者，MRI 常无明显实质病变；结脑有基底池强化与脑积水、蛋白更高。"},{"name":"脊髓炎与脊髓压迫（ne_myelitis）","point":"与脊髓病变的鉴别：脊髓病变以截瘫、感觉平面为主，无脑膜刺激征与脑脊液糖氯双低；结脑可合并脊髓结核（表现两者重叠）需影像区分。"},{"name":"化脓性脑膜炎","point":"急起高热、脑脊液中性粒细胞为主、糖明显降低但蛋白不如结脑高，涂片与培养可查出细菌，起病速度快。"},{"name":"脑膜癌病","point":"有原发肿瘤病史，脑脊液找癌细胞阳性，糖可降低但蛋白升高不如结脑显著，影像见脑膜结节状强化。"},{"name":"神经梅毒","point":"有梅毒史，血清与脑脊液梅毒螺旋体抗体（TRUST/RPR 与 TPPA）阳性，脑脊液以淋巴细胞为主，可伴脑膜血管病变。"}],"tx":{"drug":[{"name":"异烟肼（INH）","dose":"5 mg/kg/d（成人常用 300 mg qd）口服或静脉，重症可增至 10 mg/kg/d；疗程 9–12 个月","note":"核心杀菌药；需同用维生素 B6 25–50 mg/d 预防神经毒性（尤其营养不良、酗酒、HIV、妊娠者）","renal":"无需调整（透析可清除，透析后补量）","hepatic":"肝毒性（转氨酶升高），肝病者需监测或减量；急性肝炎禁用","interact":"抑制 CYP450（可升高苯妥英、卡马西平、华法林浓度）；与利福平合用肝毒性叠加"},{"name":"利福平（RIF）","dose":"10 mg/kg/d（成人 450–600 mg qd，体重 <50 kg 用 450 mg），空腹口服，疗程 9–12 个月","note":"强效杀菌药，不可替代；服药后尿、泪、汗呈橙红色（需告知患者）；间歇给药可致流感样反应","renal":"无需调整","hepatic":"肝毒性显著，与 INH 联用时需监测；黄疸时停药评估","interact":"强 CYP3A4 诱导剂：显著降低华法林、口服避孕药、他汀、抗真菌药（伊曲康唑/伏立康唑）、蛋白酶抑制剂、糖皮质激素浓度"},{"name":"吡嗪酰胺（PZA）","dose":"25 mg/kg/d（成人 1.5 g qd 或分次），强化期 2 个月","note":"强化期关键药物，可缩短疗程；主要不良反应为高尿酸血症与肝毒性","renal":"CrCl <30 减量或延长间隔","hepatic":"肝毒性，肝病者慎用","interact":"升高尿酸（可诱发痛风）；与 INH/RIF 联用肝毒性叠加"},{"name":"乙胺丁醇（EMB）","dose":"15 mg/kg/d（成人 0.75–1.0 g qd），强化期 2 个月（耐药时延长）","note":"抑菌药，预防耐药；剂量相关视神经炎（需基线及每月查视力与色觉，尤其 15 mg/kg 以上或肾功能不全）","renal":"CrCl <30 减量并密切监测视力","hepatic":"无需调整","interact":"与神经毒性药物合用增加周围神经病风险"},{"name":"泼尼松（辅助激素，关键）","dose":"起始 1 mg/kg/d（最大 60 mg/d）口服，2–4 周后缓慢减量，总疗程 6–8 周（部分方案 3–4 周）","note":"**所有结脑患者（除非有禁忌）均应加用激素**——可显著降低病死率与神经后遗症（Ⅱ–Ⅳ 级证据）；需监测血糖、感染、消化道出血；HIV 合并者亦推荐","renal":"无需调整","hepatic":"肝病者监测","interact":"与利福平合用降低激素浓度（需适当增量）；与 NSAIDs 合用增加消化道溃疡"},{"name":"左氧氟沙星 / 莫西沙星（耐药或不能耐受时）","dose":"左氧氟沙星 750–1000 mg qd；莫西沙星 400 mg qd（用于耐多药结核方案）","note":"耐多药结核（MDR-TB）方案的组成部分；需按药敏与专科方案调整","renal":"左氧氟沙星按 CrCl 减量","hepatic":"莫西沙星肝毒性，需监测","interact":"与 QT 延长药物合用增加心律失常；与含铝镁抗酸剂间隔 2 小时"},{"name":"甘露醇 / 乙酰唑胺（脑积水与颅压）","dose":"甘露醇 0.25–1 g/kg q6–8h；乙酰唑胺 250–500 mg bid–tid（交通性脑积水）；脑室外引流用于急性梗阻","note":"脑积水是结脑致死主因，需积极处理；反复腰穿放液（降颅压）在部分中心使用","renal":"乙酰唑胺在肾功能不全时慎用（可致代谢性酸中毒与结石）","hepatic":"无需调整","interact":"乙酰唑胺与阿司匹林合用增加中枢毒性"}],"nonDrug":["降颅压：反复腰穿放液、脑室外引流、脑室-腹腔分流（交通性脑积水）","重症监护（Ⅲ 期需 ICU）与气道保护","营养支持与维生素 B6 补充","隔离：开放性肺结核者需呼吸道隔离至痰菌阴转","接触者筛查与预防性治疗"],"life":["严格全程规律服药（中断易致耐药与复发），使用 DOT（直接面视下服药）策略","每月监测肝功能、视力（乙胺丁醇）与血常规","疗程结束前复查脑脊液与影像，评估是否需延长疗程","遗留神经后遗症（脑神经麻痹、认知障碍、癫痫）需康复与专科随访","HIV 合并者需同时启动抗病毒治疗（时机由专科决定，注意药物相互作用）"]},"prog":"未治疗病死率近 100%；规范抗结核 + 激素后病死率约 20%–30%。预后与分期密切相关：Ⅰ 期患者病死率 <10%，Ⅲ 期可达 30%–50%。约 20%–25% 存活者遗留神经后遗症（脑神经麻痹、认知障碍、癫痫、脑积水需分流）。治疗延迟是预后不良的最重要可干预因素。","refs":["《中国结核病防治规划实施工作指南》及《结核性脑膜炎诊疗专家共识》（中华医学会结核病学分会）","2016 ATS/CDC/IDSA/ERS Clinical Practice Guidelines: Treatment of Drug-Susceptible Tuberculosis","2017 IDSA Clinical Practice Guidelines for Healthcare-Associated Ventriculitis and Meningitis（结核部分参照）","2019 WHO Guidelines for the Treatment of Drug-Resistant Tuberculosis","《中国中枢神经系统结核病诊疗专家共识》（2022）"]},{"id":"ne_cryptococcal","name":"隐球菌脑膜炎","aka":["Cryptococcal Meningitis","CM","新型隐球菌脑膜炎"],"rank":3,"basic":{"define":"由隐球菌（以新型隐球菌为主）经呼吸道吸入后血行播散至中枢神经系统引起的亚急性或慢性脑膜炎，常见于免疫抑制者（尤其 HIV/AIDS），但我国相当比例见于无明确免疫缺陷者。","risk":["HIV/AIDS（CD4 <100/µL 时风险最高）","长期糖皮质激素或免疫抑制剂治疗","器官移植受者","糖尿病、肝硬化、慢性肾病","接触鸽粪与土壤（环境暴露）","无明显基础疾病者（我国约 20%–40%）"],"epi":"我国年发病率约 0.5–1/10 万，在 HIV 感染者中达 5%–10%。无基础疾病者占相当比例，容易被误诊。病死率在规范治疗下约 15%–20%，未治疗几乎全部死亡。"},"patho":"隐球菌的多糖荚膜是主要毒力因子，可抵抗吞噬与补体清除。吸入后在肺形成原发灶，经血行播散至脑膜与脑实质，产生大量荚膜多糖，阻塞蛛网膜绒毛的脑脊液吸收通路，同时增加渗透压，导致**颅内压显著升高（常 >250 mmH₂O，甚至 >350 mmH₂O）**——这是致死与致残的主要原因。免疫重建炎症综合征（IRIS）在 HIV 患者启动抗逆转录病毒治疗后 2–12 周发生，表现为症状反跳。","dx":{"criteria":["亚急性或慢性起病：头痛（最常见，数周）、低热、恶心呕吐、颈强直，可伴视力下降、听力下降、意识改变与癫痫","脑脊液：压力**显著升高**（>250 mmH₂O 常见）、白细胞 20–200×10⁶/L 以淋巴细胞为主、蛋白轻中度升高、糖降低（常 <2.5 mmol/L）、氯化物降低","确诊关键——病原学：① 脑脊液隐球菌**荚膜抗原（CrAg）乳胶凝集或侧向层析法**阳性（敏感度 95%–100%，特异度 >95%）；② 墨汁染色见带荚膜的酵母细胞；③ 真菌培养阳性（2–5 天）；④ 血清 CrAg 阳性（HIV 者筛查价值高）","影像：MRI 见脑底部脑膜强化、血管周围间隙扩大（胶样假囊，具提示性）、隐球菌瘤；颅压高压导致的脑室扩大","必须同时评估免疫状态（HIV 检测）"],"workup":["腰椎穿刺：**首次即测初压**（颅压高需处理），常规、生化、隐球菌抗原、墨汁染色、真菌培养","血隐球菌抗原（CrAg）检测（HIV 者常规筛查）","头颅 MRI 平扫 + 增强","HIV 检测与 CD4 计数（所有患者）","肝肾功能、血常规（两性霉素 B 与氟胞嘧啶基线）","眼科检查（视神经受累与颅压引起的视乳头水肿）","免疫球蛋白、淋巴细胞亚群（无基础疾病者评估潜在免疫缺陷）"],"grading":"按宿主状态分 HIV 相关与非 HIV 相关；按病情分轻（无症状或轻症状、无颅高压）、中（有脑膜炎表现）、重（意识障碍、颅压极高、视力丧失）。颅压水平是独立预后因素。"},"ddx":[{"name":"结核性脑膜炎（ne_tb_meningitis）","point":"与结脑的鉴别：结脑蛋白升高更显著（常 >1 g/L）、有基底池强化与脑积水，抗酸染色或 GeneXpert 阳性；隐球菌的关键是 CrAg 抗原阳性与墨汁染色、颅压极高而蛋白升高相对轻。"},{"name":"病毒性脑炎（ne_viral_enceph）","point":"与病毒性脑炎的鉴别：病毒性脑炎急性起病、脑脊液糖正常、影像见颞叶实质病变；隐球菌为亚急性、糖低、CrAg 阳性、影像多无明显实质病变。"},{"name":"脊髓炎与脊髓压迫（ne_myelitis）","point":"与脊髓疾病的鉴别：脊髓病变为截瘫与感觉平面，无颅高压与脑膜刺激征；隐球菌脑膜炎以头痛与颅压高为主。"},{"name":"化脓性脑膜炎","point":"急起高热、中性粒细胞为主、糖极低、涂片与培养见细菌，起病与血象更急骤。"},{"name":"中枢神经系统淋巴瘤","point":"影像见单发或多发强化病灶、常见于免疫缺陷者，脑脊液细胞学与活检可确诊（隐球菌可有类似影像的隐球菌瘤，需抗原检测鉴别）。"},{"name":"自身免疫性脑炎","point":"以精神症状与癫痫为主，脑脊液糖正常、自身抗体阳性；隐球菌 CrAg 阳性可鉴别。"}],"tx":{"drug":[{"name":"两性霉素 B 脱氧胆酸盐（诱导期）","dose":"0.7–1.0 mg/kg/d 静脉滴注（避光、输注 4–6 小时），联合氟胞嘧啶，疗程 2 周；或两性霉素 B 脂质体 3–5 mg/kg/d","note":"诱导期核心药物；脱氧胆酸盐肾毒性与输液反应显著，需预水化、监测电解质（低钾、低镁）与肾功能；首选脂质体可显著降低肾毒性","renal":"CrCl <30 需减量或改用脂质体；透析患者剂量与时机需个体化","hepatic":"肝毒性较轻，需监测","interact":"与氨基糖苷类、环孢素、他克莫司、顺铂等肾毒性药物合用显著增加肾损伤；与洋地黄合用致低钾性心律失常"},{"name":"氟胞嘧啶（5-FC，联合）","dose":"25 mg/kg qid（100 mg/kg/d）口服或静脉，与两性霉素 B 联用 2 周","note":"与两性霉素 B 有协同作用，是诱导期标准联合方案的关键；剂量按肾功能严格调整，需监测血药浓度（目标 25–100 mg/L）以防骨髓抑制","renal":"严格按 CrCl 减量（CrCl 20–40 减至 25 mg/kg bid；<20 减至 25 mg/kg qd）","hepatic":"本品肝毒性轻，无需调整","interact":"与骨髓抑制药物（齐多夫定、更昔洛韦）合用增加骨髓毒性"},{"name":"氟康唑（巩固期与维持期）","dose":"巩固期 400–800 mg/d 口服 8 周；维持期 200 mg/d（非 HIV 者常需 6–12 个月，HIV 者需长期维持至 CD4 >200 持续 ≥6 个月并病毒抑制）","note":"巩固与维持期用药；高剂量需注意肝毒性与 QT 延长","renal":"CrCl <50 减量（首剂不减）","hepatic":"肝毒性，需监测肝功能","interact":"抑制 CYP2C9/CYP3A4，升高华法林、他汀、苯妥英、磺脲类、QT 延长药浓度"},{"name":"颅内压管理（核心干预）","dose":"反复腰椎穿刺放液（每次 20–30 mL，使颅压降至 <200 mmH₂O 或降至初始值一半）；必要时脑室外引流或脑室-腹腔分流；乙酰唑胺 250–500 mg bid（证据有限）","note":"**颅压升高是隐球菌脑膜炎死亡的首要原因**，控制颅压比抗真菌本身更紧急；每日或隔日腰穿放液是首选","renal":"乙酰唑胺在肾功能不全慎用","hepatic":"无需调整","interact":"无特殊"},{"name":"地塞米松（诱导期，争议）","dose":"不推荐常规使用；部分方案在诱导期用 0.3–0.4 mg/kg/d 短期（1–2 周）用于严重颅压升高或隐球菌瘤周围水肿","note":"近年试验（如 ACTA 试验）显示常规加用激素未改善生存、反可能增加不良反应与真菌清除延迟；仅在明确颅高压且放液无效时权衡使用","renal":"无需调整","hepatic":"遵说明书","interact":"与抗真菌药相互作用少"}],"nonDrug":["颅内压管理的阶梯：反复腰穿 → 脑室外引流 → 脑室-腹腔分流（约 10%–20% 需分流）","HIV 患者抗逆转录病毒治疗（ART）时机：通常在抗真菌诱导 2–4 周后启动（过早启动增加 IRIS 风险）","IRIS 处理：继续抗真菌，必要时短期激素","关闭水源与环境防护（避免鸽粪与土壤暴露）","支持治疗：营养、水电解质（两性霉素 B 致低钾需补充）"],"life":["治疗全程需监测颅压（症状与腰穿），复发在 6–12 个月内风险最高","长期随访：每 3 个月复查 CrAg 与临床（HIV 者至 CD4 恢复）","HIV 者需终身抗病毒治疗并定期评估","非 HIV 且无免疫抑制者，疗程结束后复发率较低但仍需随访 1 年","避免免疫抑制（若需长期激素，应评估 CrAg 筛查）"]},"prog":"规范治疗下病死率约 15%–20%（资源有限地区可达 40%）；颅压控制不佳、意识障碍、脑脊液真菌载量高与 HIV 合并者预后更差。单纯内科治疗无效的顽固高颅压需分流。约 10%–15% 出现复发（多在 6 个月内），HIV 患者需终身维持治疗直至免疫重建。","refs":["《中国隐球菌病诊治专家共识》（中华医学会感染病学分会，2018）","2010 IDSA Clinical Practice Guidelines for the Management of Cryptococcal Disease (Updated 2020)","2018 WHO Guidelines for the Diagnosis, Prevention and Management of Cryptococcal Disease in HIV-Infected Adults, Adolescents and Children","2022 Guideline for the Management of Cryptococcal Meningitis (IDSA, updated)","《中国 HIV/AIDS 合并隐球菌病诊疗专家共识》（2021）"]},{"id":"ne_myelitis","name":"脊髓炎与脊髓压迫症","aka":["Myelitis","Transverse Myelitis","Spinal Cord Compression","脊髓压迫症"],"rank":4,"basic":{"define":"脊髓炎指脊髓的炎症性病变（感染后免疫介导或直接感染），表现为急性或亚急性截瘫、感觉障碍平面与括约肌功能障碍；脊髓压迫症指由椎管内占位（肿瘤、脓肿、血肿、椎间盘突出、骨折）压迫脊髓所致的进行性神经功能障碍，是神经外科急症。","risk":["脊髓炎：前驱感染或疫苗接种（1–4 周）、自身免疫病（SLE、干燥综合征、视神经脊髓炎谱系）、多发性硬化","脊髓压迫：恶性肿瘤脊椎转移（最常见，乳腺/肺/前列腺）、硬膜外脓肿（糖尿病、静脉药瘾、免疫抑制）、外伤、椎间盘突出、血管畸形","两者均可与结核（Pott 病）相关"],"epi":"急性横贯性脊髓炎年发病率约 1–8/10 万；恶性肿瘤患者中约 5%–10% 发生脊髓压迫，其中约 20% 以脊髓压迫为首发表现。硬膜外脓肿占椎管感染的 1/3。"},"patho":"脊髓炎的病理为脊髓实质炎性脱髓鞘与轴索损伤，灰白质均受累（横贯性），胸段最常见；水肿与炎症可致继发性缺血与坏死，故早期大剂量激素减轻水肿是关键。脊髓压迫的病理为机械性压迫 + 静脉回流受阻所致的血管源性水肿，早期为可逆的传导阻滞，持续压迫导致缺血性脱髓鞘与轴索坏死（不可逆）。因此**压迫的治疗是时间依赖的：出现症状后 24–48 小时内减压可显著改善预后**。","dx":{"criteria":["脊髓炎：急性（数小时至数天）出现双侧对称或不对称的截瘫/四肢瘫、明确的**感觉平面**、膀胱直肠功能障碍（尿潴留最常见），早期可有脊髓休克（弛缓性瘫痪、反射消失）","MRI（必需）：T2 见脊髓内高信号（横贯性者累及多个节段），增强可见强化；需排除压迫（这是 MRI 的首要任务）","脑脊液：白细胞轻中度升高（淋巴细胞为主）、蛋白升高、糖正常；寡克隆区带与 IgG 指数在 MS 相关者阳性","脊髓压迫：进行性截瘫 + 感觉平面 + 括约肌障碍 + **根性疼痛（压迫节段对应皮节）**，MRI 见脊髓受压、脑脊液间隙消失；恶性转移常伴椎体破坏","鉴别需查：AQP4-IgG 与 MOG-IgG（视神经脊髓炎谱系）、自身抗体、维生素 B12（亚急性联合变性）、HIV/梅毒/HTLV-1"],"workup":["全脊髓 MRI 平扫 + 增强（颈胸腰全程，避免漏诊多发病灶）","腰椎穿刺：压力、常规、生化、细胞学、寡克隆区带、IgG 指数、病原（HSV、VZV、肠道病毒、结核）","血清 AQP4-IgG、MOG-IgG（视神经脊髓炎谱系与 MOG 抗体病）","自身抗体谱（ANA、抗 dsDNA、抗 SSA/SSB）、抗磷脂抗体","维生素 B12、叶酸、甲状腺功能、HIV、梅毒血清学","疑恶性压迫：全身 CT/PET-CT 寻找原发灶、脊柱 X 线","疑硬膜外脓肿：血培养、CRP/ESR、必要时穿刺（需谨慎）"],"grading":"脊髓炎按受累范围分横贯性（完全性）与部分性；按病程分急性（<4 周）与亚急性。脊髓压迫按 Frankel 分级或 ASIA 分级（A 完全性–E 正常）评估神经功能，是手术时机的依据。"},"ddx":[{"name":"病毒性脑炎（ne_viral_enceph）","point":"与病毒性脑炎的鉴别：脑炎以意识障碍、癫痫与精神症状为核心，无感觉平面与截瘫；脊髓炎以运动/感觉/括约肌三联征为主。但部分病毒（VZV、肠道病毒）可同时累及脑与脊髓。"},{"name":"结核性脑膜炎（ne_tb_meningitis）","point":"与结脑的鉴别：结脑以脑膜刺激征与脑脊液糖氯双低为主；结核性脊髓炎（Pott 病）有椎体破坏与椎旁脓肿，MRI 可明确。"},{"name":"隐球菌脑膜炎（ne_cryptococcal）","point":"与隐球菌脑膜炎的鉴别：隐球菌以颅高压头痛为主，CrAg 阳性，无明显感觉平面；脊髓受累罕见。"},{"name":"视神经脊髓炎谱系疾病（ne_nmosd）","point":"与 NMOSD 的鉴别：NMOSD 的脊髓炎为**长节段（≥3 个椎体）**、伴顽固呃逆呕吐与视神经炎，AQP4-IgG 阳性；单相脊髓炎（感染后）多为短节段、单次发作。"},{"name":"急性脊髓压迫（肿瘤/脓肿）","point":"关键鉴别：有根性疼痛、进行性加重、MRI 见脊髓受压与占位，需紧急减压；脊髓炎 MRI 无压迫、见髓内信号异常。"},{"name":"吉兰-巴雷综合征（gb）","point":"GBS 为弛缓性瘫痪（下肢为主）、感觉障碍轻、**括约肌功能多保留**、脑脊液蛋白-细胞分离，MRI 脊髓正常；脊髓炎有明确感觉平面与尿潴留。"},{"name":"亚急性联合变性（维生素 B12 缺乏）","point":"后索与侧索受累（深感觉障碍、Romberg 征阳性、痉挛性瘫），血清 B12 降低、MRI 见「倒 V 字」后索高信号。"}],"tx":{"drug":[{"name":"甲泼尼龙（急性脊髓炎冲击）","dose":"1000 mg 静脉滴注 qd×3–5 天（按体重 15–30 mg/kg，最大 1 g/d），随后口服泼尼松 1 mg/kg/d 并逐渐减量（4–6 周内撤停）","note":"急性横贯性脊髓炎的一线治疗（证据级别中等但广泛使用）；需监测血糖、感染、消化道出血与精神症状；**压迫性病变在减压前不主张用激素**（除肿瘤相关水肿）","renal":"无需调整","hepatic":"肝病者监测","interact":"与 NSAIDs 合用增加消化道溃疡；与利福平、苯妥英合用降低激素浓度"},{"name":"静脉注射免疫球蛋白（IVIG，替代或联合）","dose":"0.4 g/kg/d 静脉滴注 ×5 天","note":"用于激素效果不佳或不能耐受者；IgA 缺乏者慎用（过敏风险），需查 IgA 水平","renal":"肾功能不全慎用（含蔗糖制剂致渗透性肾病）","hepatic":"无需调整","interact":"活疫苗接种需推迟"},{"name":"血浆置换（重症或激素无效）","dose":"每次 1–1.5 个血浆容量，隔日一次，共 5–7 次","note":"用于重症或激素/IVIG 无效；需中心静脉通路，注意凝血与感染风险","renal":"无需调整","hepatic":"凝血障碍者慎用","interact":"置换后药物浓度下降，需补充"},{"name":"利妥昔单抗（NMOSD 预防复发）","dose":"1000 mg 静脉第 1、15 天（或 375 mg/m² 每周 ×4）；之后每 6 个月按 CD19 计数复治","note":"AQP4-IgG 阳性 NMOSD 的一线预防用药；用药前筛查乙肝与结核，监测输注反应","renal":"无需调整","hepatic":"重度肝病慎用","interact":"与活疫苗间隔；与其他免疫抑制剂合用增加感染风险"},{"name":"地塞米松（恶性脊髓压迫，减压前过渡）","dose":"16 mg 静脉/口服 qd（或 10 mg 负荷后 4–6 mg q6h），在确诊后立即给予，手术或放疗前持续","note":"激素可快速减轻瘤周水肿、缓解疼痛与神经症状，但**不能替代减压**；需同时用 PPI 保护胃黏膜；糖尿病者监测血糖","renal":"无需调整","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"抗生素（硬膜外脓肿）","dose":"经验性：万古霉素 15–20 mg/kg q8–12h + 头孢曲松 2 g q12h + 甲硝唑 500 mg q8h；按培养调整，疗程 4–6 周（合并骨髓炎 6–8 周）","note":"需与外科减压同步；病原以金黄色葡萄球菌最常见","renal":"万古霉素按 CrCl 调整并监测谷浓度","hepatic":"甲硝唑肝毒性低","interact":"万古霉素与氨基糖苷类合用增加肾毒性"}],"nonDrug":["**脊髓压迫：确诊后应尽快减压（24–48 小时内），手术或放疗（放疗敏感肿瘤）**——减压时机是预后最重要的决定因素","硬膜外脓肿：急诊椎板切除减压 + 引流 + 长疗程抗生素（单纯抗生素仅用于不能手术且神经功能稳定者）","脊髓炎：康复训练（早期被动活动防挛缩）、膀胱管理（间歇导尿）、预防压疮与深静脉血栓","恶性肿瘤压迫：放疗（30 Gy/10 次或 8 Gy 单次）+ 手术（椎体稳定者）+ 全身抗肿瘤治疗","脊柱不稳者需内固定"],"life":["康复：截瘫患者需专业康复（肌力训练、站立架、轮椅适配），早期介入效果更好","膀胱与肠道管理：间歇导尿、预防尿路感染与结石；便秘管理","压疮预防：每 2 小时翻身、减压床垫、皮肤检查","深静脉血栓预防：机械预防 + 药物预防（依诺肝素 40 mg qd）","自主神经反射异常（高位脊髓损伤）：识别头痛、血压骤升、出汗，立即解除诱因（尿潴留、便秘）"]},"prog":"急性横贯性脊髓炎约 1/3 完全恢复、1/3 部分恢复、1/3 遗留严重残疾；起病急、脊髓休克、感觉平面高与 MRI 病灶长是预后不良因素。脊髓压迫的预后取决于减压前的神经功能：能行走者减压后多可保留行走能力，截瘫 >48 小时者恢复率显著下降。NMOSD 复发率高（>80%），需长期免疫抑制预防。","refs":["《中国视神经脊髓炎谱系疾病诊断与治疗指南（2021 版）》（中华医学会神经病学分会）","《脊髓炎诊断与治疗中国专家共识》（2020）","2018 International Consensus Diagnostic Criteria for Neuromyelitis Optica Spectrum Disorders (Wingerchuk et al., Neurology)","2020 AAN Guideline: Corticosteroids for Acute Traumatic Spinal Cord Injury（激素争议部分参照）","2017 NICE Guideline: Spinal Metastasis and Metastatic Spinal Cord Compression"]},{"id":"ne_nmosd","name":"视神经脊髓炎谱系疾病","aka":["Neuromyelitis Optica Spectrum Disorder","NMOSD","NMO","Devic 病"],"rank":5,"basic":{"define":"以视神经炎与长节段横贯性脊髓炎为主要表现的中枢神经系统自身免疫性星形胶质细胞病，多数患者血清存在水通道蛋白-4（AQP4）抗体。近年亦识别出 MOG 抗体相关疾病（MOGAD）作为独立实体。","risk":["女性显著多见（AQP4 阳性者男女比约 9:1）","发病高峰 30–40 岁（MOGAD 与儿童更常见）","亚洲、非洲与拉美人群高发（我国相对高发）","合并自身免疫病（SLE、干燥综合征、甲状腺疾病）","部分由特定药物（如某些生物制剂）诱发"],"epi":"我国患病率约 1–3/10 万，显著高于欧美。AQP4-IgG 阳性者占 NMOSD 的 70%–80%；MOG-IgG 阳性者约占 10%–20%（儿童比例更高）。复发率极高（未治疗者 >80% 复发），致残累积快。"},"patho":"AQP4 是星形胶质细胞足突上的水通道蛋白，高度富集于视神经、脊髓、最后区（延髓呕吐中枢）与脑室周围。AQP4-IgG 与抗原结合后激活补体，导致星形胶质细胞损伤、继发脱髓鞘与神经元坏死（不同于 MS 的原发性脱髓鞘）。病灶区血管周围大量免疫球蛋白与补体沉积。最后区受累解释了 NMOSD 特征性的**顽固性呃逆与恶心呕吐**。MOG 抗体病则针对髓鞘少突胶质细胞糖蛋白，病灶较小、预后相对较好。","dx":{"criteria":["2015 国际诊断标准（AQP4-IgG 阳性者）：至少 1 项核心临床特征 + AQP4-IgG 阳性 + 排除其他诊断","2015 国际诊断标准（AQP4-IgG 阴性或未知者）：发病至少 2 项核心临床特征（其中至少 1 项为视神经炎、长节段横贯性脊髓炎或最后区综合征），且有相应 MRI 证据，加上其他支持条件","六大核心临床特征：① 视神经炎；② 急性脊髓炎；③ 最后区综合征（**无法解释的顽固性呃逆、恶心呕吐**）；④ 急性脑干综合征；⑤ 症状性间脑综合征；⑥ 症状性大脑综合征","脊髓 MRI 关键特征：**长节段横贯性脊髓炎（LETM，病灶 ≥3 个连续椎体节段）**，多位于颈段与胸段，伴脊髓肿胀","视神经 MRI：长节段视神经炎（>1/2 视神经长度）、视交叉受累","脑 MRI：可正常，或见脑室周围、室管膜周围病灶（与 MS 的 Dawson 手指不同）"],"workup":["血清 AQP4-IgG（细胞法检测最可靠，ELISA 易假阳性）；必要时脑脊液检测","血清 MOG-IgG（儿童、双侧视神经炎、MRI 见明显水肿者）","全脊髓 MRI + 视神经 MRI（压脂序列）+ 头颅 MRI 增强","脑脊液：细胞数增高（可 >50，中性粒细胞亦可见）、蛋白升高，寡克隆区带阳性率低（<20%，与 MS 不同）","自身免疫病筛查：ANA、抗 dsDNA、抗 SSA/SSB、甲状腺抗体","视力与视野、OCT（视网膜神经纤维层厚度）","肿瘤筛查（部分 NMOSD 与副肿瘤相关）"],"grading":"按抗体状态分 AQP4-IgG 阳性、MOG-IgG 阳性与双阴性（后者需严格排除其他诊断）。EDSS 评分评估残疾程度。发作次数与年复发率（ARR）用于评估疾病活动度。"},"ddx":[{"name":"脊髓炎与脊髓压迫（ne_myelitis）","point":"与急性横贯性脊髓炎的鉴别：单相特发性脊髓炎多为**短节段**（<3 椎体）、无视神经炎与最后区症状、AQP4 阴性；NMOSD 为长节段 + 反复发作 + 抗体阳性。"},{"name":"多发性硬化（ms）","point":"与 MS 的关键鉴别：MS 典型为短节段（<2 椎体）、偏心性脊髓病灶，脑脊液寡克隆区带阳性率高（>85%），脑 MRI 见 Dawson 手指样病灶；NMOSD 为长节段、脑 MRI 多正常或室管膜周围，AQP4 阳性。"},{"name":"病毒性脑炎（ne_viral_enceph）","point":"与脑炎的鉴别：脑炎以意识障碍与癫痫为主、无 LETM；NMOSD 的大脑综合征少见且常伴视神经或脊髓表现。"},{"name":"结核性脑膜炎（ne_tb_meningitis）","point":"与结脑的鉴别：结脑以脑膜刺激征和脑脊液糖氯双低为主，无长节段脊髓病灶；但结核性脊髓炎（Pott 病）需 MRI 排除。"},{"name":"MOG 抗体相关疾病（MOGAD）","point":"与 MOGAD 的鉴别：MOGAD 常见双侧视神经炎伴视乳头水肿、脊髓炎病灶多较短且可完全恢复、儿童多见；AQP4-IgG 阴性而 MOG-IgG 阳性。"},{"name":"吉兰-巴雷综合征（gb）","point":"与 GBS 的鉴别：GBS 为周围神经病（弛缓性瘫、腱反射消失、括约肌多保留）、MRI 脊髓正常、脑脊液蛋白-细胞分离；NMOSD 为中枢病变伴感觉平面与尿潴留。"}],"tx":{"drug":[{"name":"甲泼尼龙（急性发作）","dose":"1000 mg 静脉滴注 qd×3–5 天，随后口服泼尼松 1 mg/kg/d，并缓慢减量（部分需维持数月）","note":"急性期一线；减量过快易复发；激素依赖者需加用免疫抑制剂","renal":"无需调整","hepatic":"肝病者监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"血浆置换（激素无效或重症）","dose":"每次 1–1.5 个血浆容量，隔日一次，共 5–7 次；可与激素联合或序贯","note":"对大剂量激素反应不佳者有效（NMOSD 对 PE 的反应优于 MS）；需中心静脉通路","renal":"无需调整","hepatic":"凝血障碍慎用","interact":"置换后药物浓度下降"},{"name":"利妥昔单抗（一线预防复发）","dose":"1000 mg 静脉第 1、15 天（或 375 mg/m² 每周×4）；之后按 CD19⁺ B 细胞计数或每 6 个月复治（1000 mg）","note":"AQP4-IgG 阳性者首选预防用药（证据最强）；用药前查乙肝、结核与免疫球蛋白水平；监测输注反应","renal":"无需调整","hepatic":"重度肝病慎用","interact":"活疫苗需间隔；与免疫抑制剂合用增加感染风险"},{"name":"依库珠单抗（补体 C5 抑制剂）","dose":"900 mg 静脉每周×4，第 5 周 1200 mg，之后每 2 周 1200 mg","note":"AQP4-IgG 阳性且既往治疗失败者的高效选择（PREVENT 研究）；**需在脑膜炎球菌疫苗接种后 ≥2 周开始**（否则需抗生素预防），警惕脑膜炎球菌感染","renal":"无需调整","hepatic":"无需调整","interact":"与 IVIG 合用可能影响疗效；活疫苗禁用（除脑膜炎球菌疫苗需提前接种）"},{"name":"伊奈利珠单抗（抗 CD19）","dose":"300 mg 静脉第 1、15 天，之后每 6 个月 300 mg","note":"AQP4-IgG 阳性者的一线预防选择（N-MOmentum 研究）；需筛查乙肝","renal":"无需调整","hepatic":"重度肝病慎用","interact":"与其他免疫抑制剂合用增加感染风险"},{"name":"硫唑嘌呤（传统免疫抑制）","dose":"2–3 mg/kg/d 口服（起始 1 mg/kg/d，每 2 周递增）","note":"资源有限时的维持治疗；起效需 3–6 个月，需与激素重叠过渡；查 TPMT 活性","renal":"肾功能不全减量","hepatic":"肝病慎用","interact":"与别嘌醇合用需减至 1/4 剂量（骨髓抑制）；与 ACEI 合用可致白细胞减少"},{"name":"吗替麦考酚酯","dose":"1000 mg bid 口服（或 500 mg bid 起始）","note":"维持治疗替代选择；妊娠禁用（致畸）","renal":"CrCl <25 慎用","hepatic":"重度肝病慎用","interact":"与硫唑嘌呤禁联（骨髓抑制）；与抗酸药合用降低吸收"}],"nonDrug":["急性期：大剂量激素 + 血浆置换（激素无效时）","长期预防复发的免疫治疗是 NMOSD 的核心（不治疗者 >80% 复发）","康复：视力康复、运动功能训练、膀胱管理","避免诱发因素：过热（热水浴、桑拿）、感染、过度疲劳、某些疫苗","妊娠：计划妊娠前需讨论治疗方案（利妥昔单抗与霉酚酸酯妊娠禁用），产后复发风险升高"],"life":["长期随访：AQP4-IgG 滴度、EDSS、年复发率与 MRI","视力保护：视神经炎后残留视力损害常见，定期眼科随访","膀胱功能障碍者间歇导尿，预防尿路感染","避免使用可能诱发复发的药物（某些 TNF-α 拮抗剂与免疫检查点抑制剂有报道）","疾病教育与心理支持（青年女性、反复发作、致残率高带来的心理负担）"]},"prog":"未治疗者约 80%–90% 在 5 年内复发，且每次复发累积不可逆残疾（脊髓炎后可截瘫、视神经炎可致失明）。规范免疫抑制治疗可显著降低复发率与残疾进展。AQP4-IgG 阳性者预后差于 MOGAD；MOGAD 多数单相或复发次数少、恢复较好。病死率约 5%–10%（多因颈髓病变致呼吸衰竭）。","refs":["《中国视神经脊髓炎谱系疾病诊断与治疗指南（2021 版）》（中华医学会神经病学分会）","2015 International Panel for NMO Diagnosis (IPND) Criteria (Wingerchuk et al., Neurology 2015)","2023 International MOGAD Panel Proposed Criteria (Banwell et al., Lancet Neurol)","2021 AAN Practice Guideline: Treatment of Neuromyelitis Optica Spectrum Disorders","2020 EFNS/ENS Guidelines on the Diagnosis and Management of Neuromyelitis Optica"]}]},{"id":"neuro_degen_more","name":"神经变性与遗传病","rank":7,"summary":"以神经元进行性变性或遗传代谢缺陷为共同底座的病变：帕金森叠加综合征、运动神经元病等多属不可逆进展，治疗以症状控制、延缓失能与治疗决策沟通为主；肝豆状核变性是其中少数可治、须终生低铜饮食与驱铜的病种，遗传性共济失调则以对症与遗传咨询为主轴。","compare":[{"diseaseId":"ne_parkinson_plus","dx":"帕金森综合征基础上，发病 1 年内出现严重自主神经衰竭（MSA）、垂直凝视麻痹与反复跌倒（PSP）或皮质功能/失用（CBD），且对左旋多巴反应差","key":"多巴胺能反应差、早期跌倒与自主神经衰竭是核心；MRI 可见十字面包征、蜂鸟征或不对称皮质萎缩"},{"diseaseId":"ne_als","dx":"上下运动神经元同时受累，肌电图广泛神经源性损害，无感觉障碍与眼外肌受累","key":"感觉正常、无眼动障碍"},{"diseaseId":"ne_wilson","dx":"不明原因肝病或锥体外系症状的青少年，铜蓝蛋白降低、尿铜升高、K-F 环阳性","key":"40 岁以下不明原因肝炎或震颤必查铜蓝蛋白"},{"diseaseId":"ne_ataxia","dx":"慢性进行性共济失调，家系遗传方式明确，MRI 见小脑及脑干萎缩","key":"对称性小脑症状与家族史"},{"diseaseId":"ne_huntington","dx":"常染色体显性家族史，进行性舞蹈样动作伴认知下降与精神行为异常，HTT 基因 CAG 重复 ≥36 次可确诊","key":"与肝豆状核变性的鉴别靠铜代谢正常、无 K-F 环；与老年性舞蹈病靠家族史与基因检测"}],"diseases":[{"id":"ne_parkinson_plus","name":"帕金森叠加综合征（MSA/PSP/CBD）","aka":["Parkinson-plus","多系统萎缩","MSA","进行性核上性麻痹","PSP","皮质基底节变性","CBD"],"rank":1,"basic":{"define":"一组以帕金森综合征为表现、但叠加明显自主神经、小脑、眼球运动或皮质功能障碍的神经变性疾病，代表性三型为多系统萎缩（MSA）、进行性核上性麻痹（PSP）与皮质基底节变性（CBD），对多巴胺能药物反应差、进展快。","risk":["50–70 岁起病","散发病例为主，MSA 与 PSP 基本无明确家族聚集","CBD 可偶见家系（MAPT 等基因）","头部外伤史与 PSP 风险相关（流行病学证据弱）"],"epi":"MSA 患病率约 4–5/10 万，发病高峰 53–55 岁，平均生存 6–9 年；PSP 患病率约 6/10 万，CBD 更罕见，60–70 岁起病。三者合计约占帕金森综合征 10%–15%。"},"patho":"MSA 为少突胶质细胞内 α-突触核蛋白包涵体（GCIs）导致纹状体黑质与橄榄脑桥小脑系统变性；PSP 为 4R-tau 沉积于基底节、丘脑底核与脑干被盖，引起纹状体输出与眼动核团损害；CBD 为非对称性 4R-tau 皮质与基底节变性。共同点是纹状体多巴胺摄取早期即显著下降，故左旋多巴只给患者带来短暂且有限的收益。","dx":{"criteria":["核心共性：帕金森综合征（运动迟缓伴强直或震颤）+ 叠加特征，且左旋多巴仅短暂、有限改善或完全无反应","MSA 可能级：自主神经衰竭（尿失禁或尿潴留 + 勃起功能障碍/女性生殖器泌尿系统损害）+ 对左旋多巴反应差的帕金森综合征，或小脑性共济失调","MSA 红旗：3 年内出现严重言语障碍、3 年内需轮椅、早期严重吞咽困难、喉喘鸣、冷手冷脚、吸气性叹气","PSP 可能级：40 岁以上、隐匿起病、垂直核上性凝视麻痹或反复非诱发性跌倒（3 年内）或头部 MRI 中脑萎缩","CBD 可能级：非对称起病，皮质（失用、皮质感觉丧失、异己肢）与基底节（强直、肌张力障碍、肌阵挛）体征并存，进展快","所有患者应排除继发性帕金森综合征（抗精神病药、甲氧氯普胺、氟桂利嗪）、正常压力脑积水、血管性帕金森综合征与 Wilson 病"],"workup":["头颅 MRI：MSA 见壳核边缘高信号、脑桥十字面包征；PSP 见中脑萎缩（蜂鸟征）；CBD 见不对称皮质萎缩","DAT-SPECT/PET：证实纹状体多巴胺能缺损","自主神经评估：卧立位血压、残余尿超声、肛门括约肌肌电图","多导睡眠图：排查 RBD 与喉喘鸣","血清铜蓝蛋白、甲状腺功能、维生素 B12"],"grading":"MSA（2015 第二版共识）：以 MSA-P（帕金森型）或 MSA-C（小脑型）分型，分可能、很可能、确诊三级，确诊仅靠病理。PSP：以 Richardson 综合征型、PSP-帕金森型、PSP-进行性步态冻结型等临床变异型描述，Richardson 型预后最差。"},"ddx":[{"name":"运动神经元病（ne_als）","point":"与本类 ne_als 的鉴别点：ALS 有上下运动神经元体征（腱反射亢进、病理征、肌萎缩与肌束颤动）而无帕金森综合征与眼动障碍，肌电图示广泛神经源性损害；叠加综合征无锥体束特征性肌束颤动与病理反射组合。"},{"name":"帕金森病（pd）","point":"PD 发病 5 年内以运动迟缓与静止性震颤为主，自主神经衰竭轻，对左旋多巴反应良好持久；发病 1 年内即尿失禁、严重跌倒或凝视麻痹提示叠加综合征。"},{"name":"药物性帕金森综合征","point":"有抗精神病药、甲氧氯普胺、氟桂利嗪、利血平用药史，症状对称、停药后数周至数月减轻，无叠加特征与进展。"},{"name":"正常压力脑积水","point":"三联征步态失用、尿失禁与认知下降，MRI 见脑室扩大伴脑凸面脑沟变窄，放液试验后步态改善。"},{"name":"Wilson 病","point":"起病年龄轻（<40 岁），伴肝病、K-F 环与铜代谢异常，是可治性鉴别，不能漏查。"}],"tx":{"drug":[{"name":"复方左旋多巴（多巴丝肼）","dose":"62.5–125 mg tid 起始，试用 2–3 个月，最大不超过 300–400 mg/d（左旋多巴含量）；无效则逐渐停用","note":"仅约 30%–40% MSA、约 1/3 PSP 患者短期部分有效；应设明确时限，避免长期无效叠加以致异动与幻觉","renal":"无需调整","hepatic":"重度肝功能不全慎用","interact":"与单胺氧化酶抑制剂、抗精神病药相互作用见药品说明书"},{"name":"米多君（α1 受体激动剂）","dose":"2.5 mg tid 起始，必要时加至 10 mg tid，睡前 4 h 内不服用","note":"用于 MSA 体位性低血压，目标为卧位收缩压 <180 mmHg、站立 3 min 收缩压 ≥75 mmHg（或改善症状）","renal":"CrCl <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与降压药、三环类、氟氢可的松合用加重卧位高血压；与 MAO 抑制剂慎用"},{"name":"氟氢可的松","dose":"0.05–0.2 mg qd（低剂量起步）","note":"扩容升压，注意卧位高血压、低钾与水肿","renal":"肾功能不全慎用","hepatic":"遵说明书","interact":"增强排钾，与袢利尿剂合用需监测血钾"},{"name":"抗抑郁与行为症状用药","dose":"遵说明书，从小剂量起","note":"PSP/CBD 抑郁、淡漠与冲动行为可用 SSRIs；选用对锥体外系影响小的药物，避免第一代抗精神病药","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["早期多学科评估与治疗目标沟通：讨论胃造瘘、气切、鼻胃管等生命支持选项，签署预立医疗照护计划","康复：防跌倒训练、步态冻结的节律性听觉提示、缩窄基底助行器","MSA 吞咽困难：早期言语治疗、环咽肌切开选择性应用；睡眠呼吸障碍行 CPAP，喉喘鸣评估气管切开","PSP/CBD 眼睑痉挛与肌张力障碍可用肉毒毒素注射","体位性低血压：弹力袜、腹带、抬高床头、快饮水法、避免餐后与直立过久","照护者支持与心理干预，晚期考虑姑息治疗与家庭照护资源"],"life":["每 6–12 个月随访评估跌倒、吞咽、认知与情绪","避免脱水、饱餐与长时间站立以减轻体位性低血压","建立遗嘱、监护与照护安排，早期讨论预后问题"]},"prog":"MSA 平均生存 6–9 年，常见死因为吸入性肺炎与睡眠呼吸暂停/喉喘鸣；PSP Richardson 型确诊后平均生存 5–8 年，早期跌倒与吞咽困难为不良预后因素；CBD 多在 6–8 年内严重失能。","refs":["2015 中国帕金森病治疗指南（第三版）","多系统萎缩诊断与治疗中国专家共识（2017）","2017 国际运动障碍学会 MSA 诊断标准（第二版）"]},{"id":"ne_als","name":"运动神经元病（肌萎缩侧索硬化）","aka":["ALS","运动神经元病","渐冻症","Motor Neuron Disease"],"rank":2,"basic":{"define":"以上、下运动神经元进行性变性为特征的选择性神经系统疾病，表现为进行性肌无力、肌萎缩与肌束颤动，可累及延髓，感觉、眼外肌与括约肌常保留。肌萎缩侧索硬化（ALS）是其中最常见、最重型的类型。","risk":["发病高峰 55–75 岁","男性略多（约 1.2–1.5:1）","家族性占 5%–10%（C9orf72、SOD1、TARDBP、FUS 等）","吸烟、机械外伤、职业暴露（农药、重金属）证据有限"],"epi":"全球发病率约 1.5–2.5/10 万，患病率 3–5/10 万；我国尚缺乏全国性流行病学数据，估计患者约 10 万以上，平均发病年龄约 55 岁，延髓起病者以中老年女性相对多见。"},"patho":"运动皮质、脑干与脊髓前角 α 运动神经元及皮质脊髓/皮质延髓束变性，TDP-43 蛋白异常聚积是关键病理特征；谷氨酸能兴奋性毒性与氧化应激、线粒体功能障碍共同参与。","dx":{"criteria":["上、下运动神经元同时受累证据：肌张力增高、腱反射亢进、病理征 + 肌萎缩、肌束颤动、无力","延髓受累：舌肌萎缩与纤颤、构音障碍、吞咽困难、强哭强笑","进行性扩展（改良 El Escorial 与 Awaji 标准）：至少 2 个区域上下运动神经元受累，或 1 个区域上下运动神经元 + 肌电图广泛神经源性损害","无感觉障碍（可有轻度麻木，但不为主要表现）、无眼球活动障碍、无括约肌明显受累","排除颈病、颅颈交界畸形、多灶性运动神经病、甲亢肌病等"],"workup":["肌电图 + 神经传导：广泛分布的慢性与活动性神经源性损害，多区域失神经电位与巨大运动单位电位；感觉神经动作电位正常","颈椎与头颅 MRI：排除颈髓压迫、颈髓病变与颅颈畸形","运动诱发电位（MEP）与静息期测定（评估上运动神经元）","肺功能（FVC、最大吸气压力）、血气（夜间低通气筛查）","血：肌酸激酶（可轻中度升高）、甲状腺功能、维生素 B12、免疫电泳（排除副蛋白）","必要时基因检测（C9orf72、SOD1、TARDBP、FUS）","认知筛查（额颞叶功能）"],"grading":"按起病部位分 ALS-脊髓型、延髓型与呼吸型；按家族史分家族性与散发性；临床进展常用 ALSFRS-R 评分（48 分制）与用力肺活量（FVC）监测。"},"ddx":[{"name":"帕金森叠加综合征（ne_parkinson_plus）","point":"与本类 ne_parkinson_plus 的鉴别点：叠加综合征以帕金森综合征、自主神经衰竭、眼动障碍为核心，无广泛上运动神经元体征与肌束颤动的组合；ALS 无震颤、无凝视障碍、无早尿失禁。"},{"name":"颈椎病性神经根脊髓病","point":"颈痛、感觉平面或放射痛、MRI 见脊髓受压，肌电图损害与影像学受累节段一致；无进行性延髓症状。"},{"name":"多灶性运动神经病（MMN）","point":"不对称肢体无力、无上运动神经元体征、感觉正常，肌电图见传导阻滞，静注 IVIG 显著有效，是 ALS 的关键可治性鉴别。"},{"name":"脊髓性肌萎缩症（SMA）与肯尼迪病","point":"SMA 仅下运动神经元受累、进展慢、基因诊断（SMN1）；肯尼迪病为 X 连锁男性，伴内分泌异常（乳房发育、糖尿病），应查雄激素受体基因重复。"},{"name":"副肿瘤性运动神经元综合征","point":"多与淋巴瘤、肺癌相关，进展快，可伴感觉受累，查肿瘤标志物与 CT/PET。"}],"tx":{"drug":[{"name":"利鲁唑（谷氨酸释放抑制剂）","dose":"50 mg qid（每 12 h 一次），口服或经胃管，饭前 1 h 或饭后 2 h","note":"可延长生存约 2–3 个月；用药前与期间监测肝功能","renal":"重度肾功能不全慎用","hepatic":"ALT/AST 显著升高者禁用或减量观察，肝功能异常者慎用","interact":"经 CYP1A2 代谢，与咖啡因、茶碱、环丙沙星等合用升高浓度"},{"name":"依达拉奉（自由基清除剂）","dose":"60 mg 静滴（60 min 内）或 60 mg 皮下注射，连续给药 10–14 d 后停 14 d，按周期使用；具体遵说明书","note":"适用于早期或进展速度评估适中的 ALS，可降低功能评分下降速度；静脉给药需评估患者行动能力","renal":"遵说明书","hepatic":"遵说明书","interact":"与华法林合用可能影响凝血指标，需监测"},{"name":"苯丁酸钠/牛磺熊去氧胆酸（TUDCA）复方","dose":"遵说明书（国内可及性有限，需按当地审批使用）","note":"用于 ALS 延缓进展，须结合可及性与费用考虑","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"巴氯芬（解痉）","dose":"5 mg bid–tid 起始，每日可递增 5 mg，最大 80 mg/d","note":"缓解痉挛性瘫痪引起的肌张力增高与疼痛；注意过度无力与日间嗜睡","renal":"重度肾功能不全需减量（忌骤然停药）","hepatic":"遵说明书","interact":"与阿片类、镇静剂合用增加嗜睡与呼吸抑制"},{"name":"丁苯酞（国内研究证据）","dose":"遵说明书","note":"国内有研究提示可能改善 ALS 功能评分，尚非国际一线证据，可与患者充分沟通后使用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"唾液管理用药","dose":"吞咽障碍伴流涎者可用格隆溴铵等抗胆碱药，遵说明书","note":"流涎明显者先行行为与体位治疗，抗胆碱药易致分泌物黏稠、加重呼吸困难","renal":"遵说明书","hepatic":"遵说明书","interact":"抗胆碱能药与促动力药作用拮抗"}],"nonDrug":["无创通气（NIV）：FVC <50% 预测值或夜间低通气时启动，可延长生存","经皮内镜下胃造瘘（PEG）：体重下降 >10%、反复误吸或进食时间过长时评估","康复：防跌倒、关节活动度训练、佩戴踝足矫形器、言语治疗（辅助沟通设备）","流涎管理、痰液吸引与咳痰机、必要时气管切开（须充分沟通预后）","定期随访：每 3 个月评估 ALSFRS-R、FVC、营养状态与心理状态","多学科团队（神经、呼吸、康复、营养、社工）管理与照护者培训"],"life":["保持适度活动，避免过度疲劳与肌肉废用","高蛋白、高热量饮食，必要时胃管喂养","及早讨论生命支持与抢救意愿并记录，避免晚期急救冲突"]},"prog":"中位生存自起病约 3–5 年，约 20% 患者生存超过 5 年；延髓起病与呼吸起病者预后差，老年发病、诊断时 FVC 低、进展快（ALSFRS-R 每月下降 >1.1）提示预后不良。","refs":["中国肌萎缩侧索硬化诊断和治疗指南（2022）","中华医学会神经病学分会 肌萎缩侧索硬化诊疗共识（2023）","中国 ALS 多学科管理专家共识（2020）"]},{"id":"ne_huntington","name":"亨廷顿病","aka":["Huntington disease","HD","亨廷顿舞蹈病","大舞蹈病"],"rank":3,"basic":{"define":"常染色体显性遗传的神经退行性疾病，由 HTT 基因 CAG 三核苷酸重复扩增引起，典型三联征为舞蹈样动作、进行性认知下降与精神障碍，多在中年起病、逐渐失能。","risk":["HTT 基因 CAG 重复扩增（≥36 次致病）","阳性家族史（遗传早现使后代发病更早）","父系遗传时 CAG 重复更易扩增"],"epi":"患病率约 5–10/10 万，欧洲血统人群较高（约 5–12/10 万），亚洲人群约 0.1–3/10 万；我国报道较少但并非罕见，发病多在 30–50 岁。"},"patho":"突变 HTT 蛋白产生毒性片段，选择性损伤纹状体（尤其尾状核）中型多棘 GABA 能神经元，出现舞蹈样动作与认知、精神障碍；病程向大脑皮层扩展。","dx":{"criteria":["成年起病的进行性舞蹈样动作，逐渐加重","精神症状：易激惹、抑郁、淡漠、强迫，或精神病性症状，常早于运动症状数年至十年","认知：执行功能、注意与工作记忆下降，向痴呆进展","家族史阳性（约 5%–10% 无家族史，可能为新发突变、父系早现或家族史被掩盖）","基因确诊：携带 HTT 基因 CAG 重复 ≥36 次","少年型：20 岁前起病，肌强直、运动迟缓（Westphal 变异）、癫痫、认知与行为异常突出"],"workup":["HTT 基因测序：确诊金标准，须先进行遗传咨询与知情同意（无症状携带者尤其慎重）","头颅 MRI：尾状核头萎缩、侧脑室前角向外扩大（盒车征），MRS 见纹状体 NAA 下降","认知评估（MoCA、符号数字转换测验）与行为评估（易激惹量表）","运动评估：UHDRS（联合亨廷顿病评定量表）","排除获得性舞蹈症：SLE/抗磷脂综合征、妊娠舞蹈症、甲亢、药物、脑梗、棘红细胞增多症","少年型需与 Wilson 病鉴别，查铜代谢"],"grading":"按 CAG 次数：≤26 正常；27–35 中间等位（不发病但后代可扩增）；36–39 外显不全；≥40 致病（完全外显）。按起病年龄分成人型（<20 岁为少年型，多表现为肌强直与癫痫）。临床分期常以 TFC（功能容量评分）划分五期。"},"ddx":[{"name":"肝豆状核变性（ne_wilson）","point":"与本类 ne_wilson 的鉴别点：Wilson 病可有肝病、K-F 环与铜代谢异常，可为有家族史的青少年舞蹈样表现且可治疗；HD 患者肝功能与铜代谢正常、HTT 基因阳性。"},{"name":"遗传性共济失调（ne_ataxia）","point":"共济失调以步态不稳、肢体辨距不良为主，舞蹈动作不突出；HD 的舞蹈症与认知、精神症状组合更典型。"},{"name":"帕金森叠加综合征（ne_parkinson_plus）","point":"叠加综合征以帕金森综合征为主、无家族性舞蹈症史；HD 以舞蹈与失用性认知下降为主，无眼动或自主神经早发受累。"},{"name":"迟发性运动障碍","point":"有长期使用多巴胺拮抗剂（抗精神病药、止吐药）史，症状在停药或减量后出现，累及口面与舌；对因处理后缓解。"},{"name":"棘红细胞增多症（舞蹈症-棘红细胞增多症）","point":"外周血见棘红细胞、肌酸激酶升高、显著肌萎缩与自咬唇舌，血涂片与 VPS13A 基因可鉴别。"}],"tx":{"drug":[{"name":"丁苯那嗪（VMAT2 抑制剂）","dose":"12.5 mg qd 起始，第二周 12.5 mg bid，按反应每周递增 12.5 mg/d，最大 100 mg/d","note":"改善舞蹈症，使用前后筛查抑郁与自杀风险，监测帕金森样症状与静坐不能","renal":"无明确调整，遵说明书","hepatic":"中度以上肝功能不全需减量（经肝代谢）","interact":"与利血平禁忌合用；与抗抑郁药、MAO 抑制剂合用可能加重抑郁或镇静"},{"name":"氘代丁苯那嗪","dose":"6 mg qd 至 6 mg bid 起始，按需每 ≥1 周加 6 mg/d，最大 48 mg/d","note":"不良反应少于丁苯那嗪，需监测 QT 与抑郁；国内可及性依地区而定","renal":"遵说明书","hepatic":"重度肝功能不全禁用或减量","interact":"避免与延长 QT 的药物、强效 CYP2D6 抑制剂合用"},{"name":"氟哌啶醇（第一代抗精神病药）","dose":"0.5–1 mg bid 起始，逐渐调整，最大 8–10 mg/d","note":"用于控制严重舞蹈症或攻击行为，易引起帕金森样症状、迟发性运动障碍与嗜睡，仅短中期使用","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与延长 QT 的药物同用风险增加；与 MAO 抑制剂禁忌合用"},{"name":"喹硫平（第二代抗精神病药）","dose":"25 mg 睡前起始，逐渐加至 50–200 mg/日","note":"较适用于伴显著易激惹、幻觉与睡眠障碍者，体重增加与代谢影响较其他第二代药物轻","renal":"遵说明书","hepatic":"肝功能不全需减量","interact":"强效 CYP3A4 抑制剂升高浓度"},{"name":"奥氮平","dose":"2.5–5 mg 睡前起始，必要时加量","note":"改善易激惹与精神症状，注意体重增加与糖代谢异常","renal":"遵说明书","hepatic":"肝功能不全减低起始剂量","interact":"吸烟可诱导 CYP1A2 降低浓度"},{"name":"SSRIs（伴抑郁/焦虑）","dose":"遵说明书，从小剂量起","note":"抑郁是 HD 自杀风险的主要来源，应常规筛查并主动治疗","renal":"遵说明书","hepatic":"肝功能不全减半起始","interact":"与丁苯那嗪、曲马多等合用增加 5-HT 过多风险"},{"name":"金刚烷胺/巴氯芬（辅助）","dose":"遵说明书","note":"金刚烷胺可改善部分患者舞蹈动作与淡漠；少年型肌强直可用巴氯芬","renal":"金刚烷胺经肾排泄，肾功能不全需减量","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["物理与作业治疗：防跌倒、平衡与步态训练、进食辅助器具","言语与吞咽治疗：构音障碍训练、后期考虑胃管","认知与行为干预：结构化日常、环境提示、护理员培训","精神心理支持与家庭照护辅助，识别虐待与照护者负担","遗传咨询：常染色体显性、50% 传递风险；产前诊断与胚胎植入前检测可选"],"life":["定期监测体重、吞咽与跌倒风险","关注自杀风险，每 3–6 个月筛查抑郁与冲动","尊重无症状携带者的隐私与知情选择权利"]},"prog":"成年型自起病至死亡约 15–20 年，少年型进展快、多在 10–15 年内死亡；早期出现显著认知下降与吞咽困难、发病年龄轻（少年型）为不良预后因素，晚期多因吸入性肺炎与营养不良死亡。","refs":["中国亨廷顿病诊治指南（2019）","亨廷顿病临床管理中国专家共识（2021）","国际运动障碍学会 HD 诊疗指南（2019 更新）"]},{"id":"ne_wilson","name":"肝豆状核变性（Wilson 病）","aka":["Wilson disease","WD","肝豆状核变性","Wilson 病","铜代谢障碍"],"rank":4,"basic":{"define":"由 ATP7B 基因变异导致铜代谢与胆道排铜障碍、铜在肝、脑（尤其豆状核）、角膜与肾脏沉积的常染色体隐性遗传病，可表现肝炎、肝硬化、锥体外系症状与精神异常，不经治疗则致残致死，早期规范驱铜可获得近似正常的生活质量。","risk":["ATP7B 基因变异（近亲婚配增加风险）","兄弟姊妹中有确诊者","40 岁以下不明原因肝病","不明原因锥体外系症状或精神症状的青少年"],"epi":"全球发病约 1/3 万，致病基因携带率约 1/90；我国是受影响人口较多的国家，多在 5–35 岁起病，以肝型为首发者多于脑型。"},"patho":"ATP7B 功能缺失导致铜不能由肝细胞经胆汁排出，亦无法在血中与铜蓝蛋白结合，非铜蓝蛋白结合的游离铜增高，在肝细胞、基底节、角膜后弹力层与肾小管沉积；铜离子诱导氧化应激与线粒体损伤，依次产生脂肪肝-纤维化-肝硬化、锥体外系损害、Fanconi 样肾损伤与 K-F 环。","dx":{"criteria":["不明原因肝病（尤其 40 岁以下）+ 转氨酶升高或肝硬化","锥体外系症状：肢体震颤（安静或姿势性）、肌张力障碍、舞蹈样动作、构音障碍、步态异常","精神症状：抑郁、人格改变、易激惹、冲动或类精神分裂样表现","K-F 环（裂隙灯下角膜后弹力层棕绿色环）阳性率约 90% 以上（肝型可仅约 50%，脑型高）","血清铜蓝蛋白降低（<0.20 g/L，约 200 mg/L），须注意约 15% 患者正常或偏低假象","24 h 尿铜升高（一般 >100 μg；>40 μg 提示可疑），肝穿刺肝铜 >250 μg/g 干重为强支持","基因检测发现 ATP7B 复合杂合/纯合致病变异可确诊","莱比锡评分 ≥4 分确诊，3 分可能，2 分待观察（儿童患者）"],"workup":["裂隙灯检查 K-F 环（务必由眼科专科完成）","血清铜蓝蛋白、血清游离铜（计算）、24 h 尿铜；必要时青霉胺激发试验（先评估风险）","肝功能、凝血功能、Child-Pugh 与 MELD 评分，评估暴发型（伴 Coombs 阴性溶血、低 ALP 与 ALB 比例下降者提示暴发）","肝脏超声、弹性成像，必要时肝穿刺组织学与肝铜定量","头颅 MRI（基底节 T2 高信号、中脑大熊猫脸征、豆状核坏死）","ATP7B 全基因测序与家系筛查（一级亲属均需查）","血常规、尿常规、骨关节评估（骨减少症）"],"grading":"临床分型：肝型（急性肝炎型、慢性肝炎型、肝硬化型、暴发型）、脑型（锥体外系型、精神障碍型）、肾型、骨关节型与混合型；严重程度常用莱比锡评分评估。"},"ddx":[{"name":"亨廷顿病（ne_huntington）","point":"与本类 ne_huntington 的鉴别点：HD 有家族史、尾状核萎缩，无 K-F 环与铜代谢异常；Wilson 病有肝病与铜代谢指标阳性，为可治性，故青少年舞蹈症必查铜蓝蛋白。"},{"name":"遗传性共济失调（ne_ataxia）","point":"以共济失调为主、无肝受累与铜代谢异常，基因检测明确；Wilson 病脑型可有共济失调样表现，但伴 K-F 环与尿铜升高。"},{"name":"自身免疫性肝炎/PBC","point":"自身抗体（ANA、SMA、LKM1、AMA）阳性、IgG 升高、女性多见，铜代谢正常；但 Wilson 病可被误诊为 AIH，应常规排除。"},{"name":"酒精性与非酒精性脂肪性肝病","point":"有饮酒史或代谢危险因素，铜代谢指标正常，影像学脂肪肝表现，戒酒与减重后改善。"},{"name":"药物性锥体外系症状","point":"用药史明确（抗精神病药、甲氧氯普胺），停药后改善，无肝受累与铜代谢异常。"}],"tx":{"drug":[{"name":"D-青霉胺（首选驱铜药）","dose":"起始 250–500 mg/d，分 2 次口服，1–2 周后逐渐加至维持量 750–1500 mg/d（成人），分 2–3 次，餐前 1 h 或睡前服；儿童 20 mg/kg","note":"用药初期约 20%–30% 出现神经症状加重（易见于脑型），加量宜缓慢；需监测血尿常规（肾毒性、骨髓抑制）、蛋白尿与自身免疫反应","renal":"肾功能不全慎用，需减量并监测，遵说明书","hepatic":"肝功能不全不改变剂量，但需更密切监测","interact":"青霉胺为维生素 B6 拮抗剂，联合需补吡多辛；铁剂与抗酸剂降低吸收，应与本药间隔"},{"name":"曲恩汀（三亚乙基四胺）","dose":"起始 750–1500 mg/d，分 2–3 次，维持量 750–1500 mg/d","note":"青霉胺不耐受时的替代首选；亦可用于神经系统症状起始治疗；费用较高","renal":"遵说明书","hepatic":"遵说明书","interact":"与铁剂、抗酸剂间隔 2 h 以上"},{"name":"锌剂（醋酸锌/硫酸锌）","dose":"醋酸锌 50 mg tid（元素锌约 150 mg/d），或硫酸锌 220 mg tid；须空腹，餐前 1 h 与睡前","note":"通过诱导肠上皮金属硫蛋白阻断铜吸收，适用于无症状或维持期，起效慢、不宜单独用于活动性肝病或脑型","renal":"遵说明书","hepatic":"遵说明书","interact":"与青霉胺、四环素、喹诺酮类、铁剂需间隔 2 h 以上"},{"name":"二巯丙磺酸钠（DMPS）","dose":"静脉或肌注用药按说明书，国内常用于暴发型或重症起始驱铜","note":"国内经验用于病情严重者，需在专科监护下使用","renal":"肾功能不全慎用","hepatic":"遵说明书","interact":"遵说明书"},{"name":"吡多辛（维生素 B6）","dose":"10–30 mg/d 口服","note":"长期青霉胺治疗时预防 B6 缺乏与神经毒性","renal":"遵说明书","hepatic":"遵说明书","interact":"与左旋多巴合用降低后者疗效"},{"name":"对症治疗用药","dose":"遵说明书","note":"肌张力障碍可用苯海索或巴氯芬（注意抗胆碱药加重认知损害）；精神症状用喹硫平、奥氮平等低剂量；避免用高剂量抗精神病药","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["低铜饮食：避免动物肝脏、贝类、坚果、巧克力、蘑菇、豆类；饮水铜 >0.01 mg/L 地区需用蒸馏水或净水","暴发型肝衰竭：尽早评估肝移植（不等驱铜），采用 Wilson 病预后指数","肝移植：暴发型肝功能衰竭或对驱铜治疗无效的失代偿肝硬化","终生用药不可中断，中断治疗可致暴发与死亡","家系筛查：一级亲属查铜蓝蛋白、尿铜、K-F 环与基因，发现无症状患者尽早预防性治疗","定期随访：每 3–6 个月查肝功能、铜蓝蛋白、24 h 尿铜与血常规，维持 24 h 尿铜 200–500 μg","康复与言语治疗：构音、吞咽与步态训练"],"life":["终生治疗，切勿因症状改善自行停药","女性患者可妊娠，妊娠期间须在专科指导下维持驱铜（剂量可适度下调），避免停药导致暴发","避免过量饮酒、慎用肝毒性药物与含铜补充剂"]},"prog":"规范治疗后 10 年生存率可达 80% 以上，肝型优于脑型；诊断延迟、神经症状显著者常残留运动障碍；暴发型肝衰竭不经肝移植几乎均死亡。","refs":["中国肝豆状核变性诊断与治疗指南（2022）","中华医学会肝病学分会 遗传性铜代谢障碍诊治共识","国际 Wilson 病诊疗共识（EASL 2012）"]},{"id":"ne_ataxia","name":"遗传性共济失调","aka":["Hereditary ataxia","脊髓小脑性共济失调","SCA","Friedreich 共济失调","FRDA"],"rank":5,"basic":{"define":"一组以共济失调为共同表现、具有明显遗传异质性的慢性进行性神经系统变性疾病，以常染色体显性遗传的脊髓小脑性共济失调（SCA）最常见，另有 Friedreich 共济失调（FRDA）、遗传性痉挛性截瘫（HSP）等类型，可累及小脑、脊髓、脑干与周围神经。","risk":["常染色体显性（SCA，多由三核苷酸重复扩增引起，存在遗传早现）","常染色体隐性（FRDA，FXN 基因 GAA 重复；我国以 ARSACS 等可见）","近亲婚配"],"epi":"SCA 全球患病率约 1–5/10 万，我国以 SCA3（Machado-Joseph 病）最常见（占比大于 50%），多在 30–50 岁起病；FRDA 在白种人中患病率 1/5 万，我国相对少见。"},"patho":"三核苷酸/CAG 或其他重复扩增产生毒性 RNA 或异常蛋白，选择性损伤小脑 Purkinje 细胞、齿状核、脊髓后柱与脑干；不同亚型受累部位各有偏重，决定了共济失调、锥体束、眼动与周围神经表现的组合。","dx":{"criteria":["慢性进行性对称性共济失调：步态不稳为首发，逐渐出现肢体辨距不良、构音障碍、书写困难","眼动异常（凝视诱发性眼震、扫视缓慢）、指鼻与跟膝胫试验阳性","家族史提示遗传方式；SCA3 常伴突眼、肌萎缩、痉挛与末梢感觉减退；FRDA 伴下肢深感觉丧失、腱反射消失、肥厚型心肌病与糖尿病","排除获得性共济失调：酒精中毒、维生素 B1/B12 缺乏、甲状腺功能减退、多发性硬化、肿瘤/副肿瘤、中毒（苯妥英、甲硝唑、锂）与免疫性共济失调","基因检测确定亚型（多重连接探针与重复序列测定）"],"workup":["家系图绘制与遗传方式判定","头颅与脊髓 MRI：小脑、脑桥、延髓萎缩（十字面包征见于 MSA-C）","神经传导与肌电图：SCA3 常见轴索型感觉运动神经病","心脏评估（心电图、超声心动图）：FRDA 高发，晚期死因多为心肌病/心律失常","血糖与糖化血红蛋白（FRDA 伴糖尿病）","血：维生素 B1、B12、叶酸、甲状腺功能、同型半胱氨酸、抗麦胶蛋白抗体（乳糜泻）、抗 GAD 抗体","肿瘤筛查与自身抗体（年轻快速进展者排查副肿瘤）"],"grading":"按遗传方式分常显（SCA 1–48 等）、常隐（FRDA、ARSACS）、X 连锁与线粒体相关；临床常用国际协作共济失调评定量表（ICARS）与 SARA（0–40 分）评分。"},"ddx":[{"name":"多系统萎缩-小脑型（ne_parkinson_plus）","point":"与本类 ne_parkinson_plus 的鉴别点：MSA-C 起病年龄更晚（>50 岁）、进展更快（5 年内多需轮椅）、伴早发自主神经衰竭（体位性低血压、尿失禁）与 REM 睡眠行为障碍；遗传性共济失调多为家系、进展更慢、无严重早发自主神经衰竭。"},{"name":"维生素 B1/B12 缺乏性共济失调与酒精性小脑变性","point":"有营养缺乏或长期饮酒史，补充维生素后改善；B12 缺乏者伴后索体征、贫血与舌炎，同型半胱氨酸升高。"},{"name":"多发性硬化（ms）","point":"发作性复发缓解、时间空间多发性病灶，MRI 见典型白质脱髓鞘灶，免疫治疗有效；遗传性共济失调为渐进、对称、无发作性加重。"},{"name":"免疫介导性小脑共济失调（抗 GAD、肿瘤相关）","point":"亚急性起病（数周至数月）、进展较快、可伴其他自身免疫病或肿瘤，抗体阳性，免疫治疗可改善。"},{"name":"肝豆状核变性（ne_wilson）","point":"青少年共济失调伴肝病与精神症状，K-F 环与铜代谢异常，可治性极高，必须常规排除。"}],"tx":{"drug":[{"name":"丁螺环酮（5-HT1A 部分激动剂）","dose":"遵说明书（部分研究报告 15–30 mg/d 可改善共济失调评分）","note":"证据有限，可作经验性试用，注意头晕与恶心","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 MAO 抑制剂禁忌合用；与强效 CYP3A4 抑制剂升高浓度"},{"name":"利鲁唑（试用）","dose":"部分研究用于 SCA3 与 FRDA，50 mg bid 试用，遵说明书","note":"可轻度改善部分患者共济失调量表评分，非根治；需监测肝功能","renal":"重度肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"遵说明书"},{"name":"艾地苯醌（FRDA 线粒体靶向抗氧化）","dose":"遵说明书","note":"对 FRDA 心肌肥厚与神经功能有部分改善作用，疗效个体差异大","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"巴氯芬/加巴喷丁（痉挛）、美克洛嗪（眩晕）","dose":"遵说明书","note":"痉挛可用巴氯芬或加巴喷丁；共济失调性震颤可试用普萘洛尔、普里米酮","renal":"加巴喷丁需按肾功能减量","hepatic":"遵说明书","interact":"遵说明书"},{"name":"辅酶 Q10 与维生素 E","dose":"遵说明书","note":"部分亚型（如 FRDA）可能有获益，证据不足以推荐常规使用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["平衡与步态康复训练、核心肌群训练，有限证据显示可改善 SARA 评分","构音障碍的言语治疗、吞咽评估与进食器具","防跌倒：佩戴保护头具、家居改造、助行器具","FRDA 心脏监控：每年心电图与超声，警惕心肌病与心房颤动","遗传咨询与产前诊断"],"life":["保持规律活动、避免久坐与体重增加","每 6–12 个月随访 SARA、心脏与吞咽","安排照护者支持与辅助设备，讨论驾驶安全性"]},"prog":"SCA3 自起病至依赖轮椅约 10–15 年，晚期多死于吸入性肺炎；FRDA 多在起病后 10–20 年需轮椅，心肌病是主要死因；早发病、进展快与肌萎缩显著者预后较差。","refs":["遗传性共济失调诊断与治疗中国专家共识（2021）","脊髓小脑性共济失调诊疗中国专家共识","中华医学会神经病学分会 神经遗传病诊断指南"]}]},{"id":"neuro_immune_periph","name":"免疫周围神经与肌病","rank":8,"summary":"本类覆盖免疫介导的中枢/周围神经疾病、代谢性周围神经病与离子通道病：中枢免疫性脱髓鞘以激素冲击为主轴，CIDP 以激素、IVIG 与血浆置换三选一加维持治疗，糖尿病周围神经病以控糖与对症止痛为核心，周期性瘫痪按发作时血钾分层补钾或排钾，自主神经病则以生活方式干预加升压药为主。","compare":[{"diseaseId":"ne_adem","dx":"感染或疫苗接种后 1–3 周亚急性脑病表现（意识障碍、精神行为异常）+ 多灶性 CNS 局灶体征，MRI 见不对称、多发、边界不清的皮层下与深部白质病灶","key":"脑病症状为必备条件，病灶大、不对称、累及丘脑与基底节；儿童多于成人"},{"diseaseId":"ne_cidp","dx":"对称性近端与远端无力伴感觉减退，腱反射消失，进展超过 8 周；肌电图示脱髓鞘改变，CSF 蛋白显著升高","key":"病程超过 8 周是区别于急性免疫性周围神经病的关键，且对激素/IVIG 有反应"},{"diseaseId":"ne_dpn","dx":"糖尿病患者出现对称性远端手套袜套样麻木、疼痛或感觉减退，神经传导示轴索型或混合型损害","key":"长度依赖性对称性表现，以足部起病并向上发展"},{"diseaseId":"ne_periodic_paralysis","dx":"反复发作的弛缓性肢体肌无力，血钾可低、正常或高；发作间期肌力正常，基因检测可明确分型","key":"发作性与发作间期完全恢复，鉴别以发作时血钾为核心"},{"diseaseId":"ne_dysautonomia","dx":"直立性不耐受伴立位收缩压下降 ≥20 mmHg 或舒张压 ≥10 mmHg，或汗腺、胃肠动力障碍，无明确中枢病灶","key":"体位性血压变化与心率反应；需排除药物、容量不足与糖尿病原因"}],"diseases":[{"id":"ne_adem","name":"急性播散性脑脊髓炎","aka":["ADEM","Acute Disseminated Encephalomyelitis","感染后脑脊髓炎"],"rank":1,"basic":{"define":"常继发于病毒感染或疫苗接种后，由自身反应性 T 细胞介导、以脑与脊髓多灶性脱髓鞘为特征的急性免疫性疾病，临床突出表现为脑病（意识障碍、精神行为异常），MRI 见多发、不对称、较大的白质病灶，儿童多见、预后多良好。","risk":["儿童与青少年（多在 10 岁以下）","前驱感染（病毒性上呼吸道、肠道感染）1–3 周后","疫苗接种后（罕见）"],"epi":"儿童发病率约 0.3–0.6/10 万，成人较少；儿童 ADEM 中重症约 1%，>50% 在 1 年内恢复良好，约 10%–30% 后续转为多发性硬化。"},"patho":"分子模拟学说为主导：病原体抗原与髓鞘碱性蛋白等结构相似，诱导自身反应性 Th1/Th17 细胞攻击中枢髓鞘，导致血管周围炎性脱髓鞘，病灶以深部白质与皮层下为主、不对称；急性期需与中枢神经系统感染及 MS 首次发作区分。","dx":{"criteria":["急性/亚急性起病（数天–数周），伴意识障碍（嗜睡、谵妄、昏迷）或精神行为异常，脑病症状为必备","多灶性中枢神经系统体征：偏瘫、共济失调、脑神经受累、脊髓受累、癫痫发作","前驱感染或疫苗接种史（1–3 周内）有助诊断，但非必需","MRI：T2/FLAIR 上多发、不对称、边界不清的皮层下与深部白质大病灶，常累及丘脑与基底节；增强呈结节样或开环样强化","CSF：淋巴细胞轻度增多（一般 <100/μL）、蛋白轻度升高，寡克隆区带阴性或短暂阳性","排除病毒性脑炎与细菌性脑膜炎后启动激素治疗"],"workup":["头颅与全脊髓 MRI 增强，病情动态复查（新增孤立病灶需警惕 MS）","腰穿：压力、细胞计数、蛋白、糖、氯化物、涂片与培养、病毒 PCR/NGS、自身免疫脑炎抗体谱","血清 MOG 抗体：儿童 ADEM 阳性率 30%–50%，阳性提示 MOGAD，复发风险与病程不同","血常规、肝肾功能、甲状腺功能、自身免疫抗体、维生素 B12","脑电图（癫痫或意识障碍者）、视力与眼底检查","病程 >3 个月再发或新出现孤立病灶，须随访评估 MS 与 NMOSD 可能"],"grading":"无公认统一分级，按临床严重程度采用 mRS 或 McCrea 序贯评分；2013 年国际儿童多发性硬化研究组（IPMSSG）强调需满足脑病 + 多灶性 CNS 体征 + 影像改变的组合。"},"ddx":[{"name":"慢性炎性脱髓鞘性多发性神经病（ne_cidp）","point":"与本类 ne_cidp 的鉴别点：CIDP 病变在周围神经，表现为对称性弛缓无力与感觉障碍、无意识障碍与脑病，颅脑 MRI 正常；ADEM 以脑病 + 中枢病灶为必备。"},{"name":"多发性硬化首次发作","point":"MS 首次发作无脑病，病灶小（<1–2 cm）、边界清、脑室旁与近皮层分布，寡克隆区带阳性率 70%–90%；ADEM 病灶大、不对称、边界不清。"},{"name":"病毒性脑炎（单纯疱疹病毒）","point":"发热、头痛、精神行为异常、癫痫，MRI 累及颞叶内侧与岛叶，CSF 见 HSV PCR 阳性需抗病毒；ADEM 无发热与疱疹样病灶。"},{"name":"中枢神经系统原发性血管炎","point":"多发脑梗死与缺血灶、DSA 见血管狭窄与串珠样改变，无脑病潮起与感染前驱的典型过程。"},{"name":"视神经脊髓炎谱系疾病（ne_nmosd）","point":"视神经炎与长节段横贯性脊髓炎，CSF 细胞显著增多，AQP4 抗体阳性，无弥漫性不对称白质大病灶。"}],"tx":{"drug":[{"name":"甲泼尼龙（大剂量激素冲击）","dose":"成人 1 g/d 静滴 ×3–5 d（儿童 10–30 mg/kg/d，最大 1 g/d），随后口服泼尼松 1–2 mg/kg/d（成人 1 mg/kg）逐渐减量，疗程总 4–6 周","note":"首选治疗，尽早启动可缩短病程；减量不宜过快以免反跳，须监测血糖、血压与感染","renal":"肾功能不全无需调整","hepatic":"肝功能不全慎用，严重者需减量","interact":"与非甾体抗炎药合用增加消化道出血；与口服降糖药作用拮抗"},{"name":"静脉注射人免疫球蛋白（IVIG）","dose":"2 g/kg 总剂量，分 2–5 d 给予（常用 0.4 g/kg/d ×5 d）","note":"用于激素反应不佳、儿童首选或不能耐受激素者；注意 IgA 缺乏者过敏与血栓风险","renal":"肾功能不全慎用，优选无蔗糖稳定剂制剂","hepatic":"遵说明书","interact":"与活疫苗间隔；可能干扰血型与病毒学检测"},{"name":"血浆置换（TPE）","dose":"5–7 次，隔日 1 次（常用 1–1.5 个血浆量/次）","note":"用于激素无反应的重症或爆发型病例，须尽早使用；有血流动力学与凝血风险","renal":"血液透析患者需相应调整方案","hepatic":"凝血功能异常者需新鲜冰冻血浆替代","interact":"与 IVIG 间隔使用；置换后血药浓度下降需补充长效药"},{"name":"抗癫痫与支持治疗","dose":"遵说明书","note":"癫痫发作可用左乙拉西坦或丙戊酸；意识障碍者注意气道保护、营养与感染防治","renal":"左乙拉西坦经肾排泄，肾功能不全需减量","hepatic":"丙戊酸禁用于严重肝病","interact":"遵说明书"}],"nonDrug":["重症监护：意识障碍、癫痫持续状态或呼吸受累者需气道保护与监护","康复：早期床上被动活动、平衡与认知康复，防压疮与深静脉血栓","随访 MRI 与神经系统评估：3、6、12 个月，评估复发与新病灶","MOG 抗体阳性者须延长随访，注意视神经炎复发"],"life":["急性期休息，避免剧烈运动与过度疲劳","激素减量期间避免感染，出现发热或精神症状加重及时就诊","疫苗接种可推迟至恢复后，个体化评估"]},"prog":"儿童 ADEM 约 70%–90% 部分或完全恢复，多在 1 年内；约 10%–20% 遗留运动、认知或视力损害；成人预后较差，病死率可达 5%–10%，多因呼吸衰竭或严重脑水肿。","refs":["中国中枢神经系统炎性脱髓鞘疾病诊断与治疗指南（2021）","2012 中国多发性硬化及相关中枢神经系统脱髓鞘疾病诊断与治疗专家共识","国际儿童 MS 研究组 ADEM 诊断共识（2007/2013）"]},{"id":"ne_cidp","name":"慢性炎性脱髓鞘性多发性神经病","aka":["CIDP","Chronic Inflammatory Demyelinating Polyneuropathy","慢性吉兰-巴雷综合征"],"rank":2,"basic":{"define":"由细胞与体液免疫共同介导、以周围神经与神经根多发脱髓鞘为特征的获得性免疫性周围神经病，临床以对称性近远端无力与感觉减退、腱反射消失为突出表现，病程进展或复发持续超过 8 周，对激素、IVIG 与血浆置换等免疫治疗有良好反应。","risk":["40–60 岁多发，男性多于女性","多无明确前驱诱因（可有轻微感染）","可伴随糖尿病、单克隆丙种球蛋白病、系统性红斑狼疮等"],"epi":"患病率约 0.7–9/10 万，发病年龄高峰 40–60 岁；我国报道较少，综合医院神经科常见，男性约为女性的 1.5–2 倍。"},"patho":"巨噬细胞介导节段性脱髓鞘伴施万细胞修复不良、神经根与神经丛增粗，Th1/Th17 细胞与抗体共同参与；反复脱髓鞘后出现轴索继发损害，导致功能恢复不彻底。部分亚型（结区抗体阳性）急性期表现类似 GBS。","dx":{"criteria":["对称性四肢近端与远端无力，伴感觉减退、麻木或疼痛","腱反射减弱或消失（通常上下肢均有）","病程进展 ≥8 周（或复发超过 2 次，累计 >8 周）","肌电图示脱髓鞘：运动传导速度明显减慢、远端潜伏期延长、F 波潜伏期延长或消失、时间离散与传导阻滞；或超声/MRI 见神经根与神经丛增粗","脑脊液蛋白升高（>0.45 g/L）而细胞数正常（蛋白细胞分离）","排除糖尿病、IgM 抗 MAG 抗体相关神经病、遗传性神经病与中毒性神经病","治疗反应性可作为诊断支持（EAN/PNS 2021 共识将 8 周内反应纳入支持标准）"],"workup":["神经传导与肌电图（含 F 波、H 反射，必要时分段运动传导测定以发现传导阻滞）","周围神经系统超声或 MRI（神经根、臂丛、腰骶丛）观察增粗","腰穿：细胞计数、蛋白、糖、免疫球蛋白与寡克隆区带","血清蛋白电泳与免疫固定电泳（排除 IgM 单克隆并查抗 MAG 抗体）","血常规、血糖、糖化血红蛋白、甲状腺功能、维生素 B12、自身抗体（ANA、ENA）","必要时神经活检（脱髓鞘与洋葱球样改变，非必需）","排除感染（HIV、乙肝、梅毒）与药物性周围神经病"],"grading":"按病程分慢性进展型、复发缓解型与单相型；按临床分布分经典型、远端型、纯运动型、纯感觉型、多灶型与局灶型；严重程度用 INCAT 残疾评分（0–10）。"},"ddx":[{"name":"急性播散性脑脊髓炎（ne_adem）","point":"与本类 ne_adem 的鉴别点：ADEM 为中枢病变，有脑病与意识障碍、颅脑 MRI 多灶脱髓鞘；CIDP 无意识与中枢体征，病变局限于周围神经。"},{"name":"吉兰-巴雷综合征（gb）","point":"GBS 在 4 周内达高峰、多为上升性对称无力、脑脊液蛋白细胞分离在 2 周后出现；CIDP 进展超过 8 周或反复发作。"},{"name":"糖尿病性周围神经病（ne_dpn）","point":"DPN 以远端手套袜套样感觉障碍为主、少见近端无力与显著运动传导减慢，肌电图以轴索损害为主，免疫治疗无效。"},{"name":"遗传性运动感觉神经病（CMT）","point":"起病早、家族史阳性、手足畸形（高足弓、锤状趾），超声见神经增粗但免疫治疗无效，基因检测可鉴别。"},{"name":"IgM 抗 MAG 相关神经病","point":"老年、远端不对称感觉性共济失调与震颤突出，抗 MAG 抗体阳性，对常规 IVIG 常不佳，利妥昔单抗可能有效。"}],"tx":{"drug":[{"name":"泼尼松（糖皮质激素）","dose":"1 mg/kg/d（最大 60–80 mg/d）起始，维持 4–8 周，之后每 2–4 周减 5–10 mg 至最小有效量；亦可甲泼尼龙 1 g/d ×3–5 d 脉冲后口服","note":"我国经验与指南中将激素列为可及性高的首选之一；须同时补钙、维生素 D、护胃，监测血糖血压","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与非甾体抗炎药合用增加消化道出血"},{"name":"静脉注射人免疫球蛋白（IVIG）","dose":"负荷 2 g/kg 分 2–5 d，维持 0.4–1 g/kg 每 3–4 周，按 INCAT 评分调整间隔","note":"起效较激素快，适用于急性加重、妊娠与年轻患者；IgA 缺乏者慎用","renal":"肾功能不全慎用含蔗糖制剂","hepatic":"遵说明书","interact":"与活疫苗、血型检测相互影响"},{"name":"血浆置换（TPE）","dose":"每疗程 3–5 次隔日 1 次，或每周 2 次持续 4–6 周；维持方案按需重复","note":"用于激素/IVIG 无效或急性重症；需中心静脉通路、血小板与凝血评估","renal":"需调整置换液与抗凝","hepatic":"凝血功能障碍需新鲜冰冻血浆","interact":"与 IVIG 间隔使用，注意置换后药物清除"},{"name":"硫唑嘌呤（激素节省剂）","dose":"1–2 mg/kg/d 口服，起效需 3–6 个月","note":"用于减少激素用量与复发；用药前查 TPMT/NUDT15 活性（部分机构可查）","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用并减量","interact":"与别嘌醇合用显著增加骨髓抑制；减低华法林抗凝效果"},{"name":"甲氨蝶呤/霉酚酸酯（维持治疗）","dose":"甲氨蝶呤 7.5–15 mg 每周一次；霉酚酸酯 0.5–1 g bid，遵说明书","note":"用于复发性或激素依赖型 CIDP 的维持；霉酚酸酯须避孕，孕期禁用","renal":"霉酚酸酯在重度肾功能不全需减量","hepatic":"甲氨蝶呤肝功能异常时停用","interact":"甲氨蝶呤与磺胺类、非甾体抗炎药合用增加骨髓抑制"},{"name":"利妥昔单抗（难治性、抗体介导型）","dose":"遵说明书（常用 375 mg/m² 每周 ×4 次或 1000 mg ×2 次）","note":"用于抗结区抗体/抗 NF155 阳性或难治型，需筛查乙肝与结核","renal":"遵说明书","hepatic":"遵说明书","interact":"活疫苗间隔；与其他免疫抑制剂合用增加感染风险"},{"name":"加巴喷丁/普瑞巴林（神经痛对症）","dose":"遵说明书，从小剂量滴定","note":"缓解感觉异常与神经痛，不改变病程","renal":"按肌酐清除率减量","hepatic":"遵说明书","interact":"与阿片类、镇静剂合用增加呼吸抑制"}],"nonDrug":["足量康复训练：肌力、平衡与步态训练，防跌倒与关节挛缩","定期评估 INCAT 与握力、行走距离，动态调整治疗剂量与间隔","治疗目标为维持独立行走与生活自理，避免长期大剂量激素的骨质疏松与感染","疫苗接种（灭活）与感染预防；免疫抑制期间避免活疫苗","合并单克隆丙种球蛋白病者按血液科评估随访"],"life":["适度运动，避免剧烈疲劳诱发加重","激素维持期间低盐、补钙与维生素 D，监测骨密度","出现呼吸费力、吞咽困难或快速进展应及时复诊排除急性加重"]},"prog":"约 60%–70% 患者对免疫治疗有反应，但多数需长期维持；约 10%–15% 最终需轮椅或终身依赖治疗，少数自发缓解。年老、轴索损害重、治疗延迟者预后较差。","refs":["中国慢性炎性脱髓鞘性多发性神经根神经病诊治指南（2021）","EAN/PNS CIDP 诊断与治疗指南（2021）","中华医学会神经病学分会 周围神经病诊疗共识（2019）"]},{"id":"ne_dpn","name":"糖尿病性周围神经病","aka":["DPN","Diabetic Peripheral Neuropathy","糖尿病周围神经病变","痛性糖尿病神经病"],"rank":3,"basic":{"define":"糖尿病引起的、以周围神经受累为主的一组神经病变，最常见为远端对称性多发性感觉运动神经病（以足部麻木、疼痛与感觉减退为特征），可致足溃疡与截肢；诊断需结合糖尿病病程、症状体征，并排除其他病因。","risk":["糖尿病病程长（>10 年者约 50% 受累）","血糖控制不良（HbA1c 持续升高）","肥胖、高血压、脂代谢紊乱","长期饮酒与维生素 B12 缺乏（尤其长期二甲双胍）"],"epi":"我国糖尿病患者 DPN 患病率约 30%–50%（社区筛查约 25%–35%），其中痛性神经病变约占 10%–20%；因足溃疡导致的年截肢率可达 1%–3%。"},"patho":"高血糖引起多元醇通路激活、晚期糖基化终末产物（AGEs）沉积、氧化应激、微血管缺血与神经炎症，轴索与施万细胞受损，末梢短的感觉神经纤维最先受累，故呈长度依赖性对称性分布。","dx":{"criteria":["有糖尿病或糖代谢异常病程","远端对称性麻木、刺痛、烧灼痛或感觉减退，夜间加重；或以足部无痛与触觉减退为唯一表现","体征：袜套样感觉减退、双足震动觉减退、踝反射减弱或消失","10 g 尼龙丝检查：足部至少 1 点感觉缺失为阳性","排除其他病因（酒精、B12 缺乏、甲减、尿毒症、副蛋白、化疗药物）","非典型或不对称者需神经传导检查确认，通常为轴索型感觉运动神经损害"],"workup":["10 g 尼龙丝、128 Hz 音叉、针刺与温度觉检查","踝反射、肌力与足部外观（畸形、胼胝、皮肤干燥）","神经传导速度与肌电图（必要时）","HbA1c、空腹与餐后血糖、甲状腺功能、维生素 B12、叶酸、肾功能、尿蛋白、血脂","怀疑其他病因时查免疫固定电泳、自身抗体、梅毒与 HIV","足部血管评估（足背动脉搏动、ABI），排除缺血"],"grading":"症状分级常用多伦多临床神经病变评分（TCSS，0–19 分）与密歇根神经病变筛查表（MNSI）；疼痛程度用 0–10 分视觉模拟量表。"},"ddx":[{"name":"慢性炎性脱髓鞘性多发性神经病（ne_cidp）","point":"与本类 ne_cidp 的鉴别点：CIDP 以近远端同时受累的无力、运动传导明显减慢、脑脊液蛋白细胞分离为特征，免疫治疗有效；DPN 以对称远端感觉为主、免疫治疗无效。"},{"name":"维生素 B12 缺乏性周围神经病","point":"可有巨幼细胞贫血、舌炎与后索受累（位置觉与振动觉丧失），血清 B12 低或同型半胱氨酸升高，补充后改善。"},{"name":"酒精性周围神经病","point":"长期大量饮酒史、营养缺乏，感觉与运动同时受损，戒酒与补充 B 族维生素后改善。"},{"name":"尿毒症性周围神经病","point":"慢性肾衰竭患者出现对称性远端感觉运动障碍，透析可部分改善，血肌酐与尿素氮显著升高。"},{"name":"腰椎管狭窄所致神经根病","point":"症状呈节段性、随行走加重（间歇性跛行），单侧或不对称，MRI 见狭窄；DPN 为对称袜套样分布。"}],"tx":{"drug":[{"name":"普瑞巴林","dose":"75 mg bid 起始，可按需加至 150 mg bid，最大 300 mg bid（常用 150–600 mg/d）","note":"一线止痛药，注意嗜睡、头晕、水肿与体重增加；骤然停药可致焦虑反跳或癫痫","renal":"CrCl 30–60 减至 25–50 mg bid；CrCl 15–30 为 25–50 mg qd；<15 遵说明书","hepatic":"肝功能不全无需调整，但需监测","interact":"与阿片类、镇静催眠药、酒精合用增加呼吸抑制与嗜睡"},{"name":"度洛西汀","dose":"30 mg qd 起始 ×1–2 周，增至 60 mg qd；最高 120 mg/d","note":"一线止痛药，兼改善抑郁与睡眠；注意血压升高、恶心与性功能障碍","renal":"CrCl <30 不推荐使用","hepatic":"肝功能损害者慎用或避免使用","interact":"与 MAO 抑制剂禁忌合用；与曲马多等 5-HT 能药合用增加 5-HT 综合征"},{"name":"甲钴胺（维生素 B12 活性形式）","dose":"0.5 mg tid 口服，或 0.5–1 mg 肌注 隔日或每周 3 次","note":"国内指南推荐用于神经修复的辅助治疗，疗效证据中等","renal":"无需调整","hepatic":"遵说明书","interact":"与氯霉素合用可减弱疗效"},{"name":"α-硫辛酸","dose":"600 mg qd 口服，或 600 mg 静滴 qd ×2–4 周","note":"抗氧化，可改善部分疼痛与氧化应激指标，证据有限","renal":"遵说明书","hepatic":"遵说明书","interact":"可能增强降糖药作用，需监测血糖"},{"name":"依帕司他（醛糖还原酶抑制剂）","dose":"50 mg tid 餐前口服","note":"国内指南推荐用于改善神经病变症状，需定期查肝功能（可致尿色改变）","renal":"遵说明书","hepatic":"肝功能异常者慎用","interact":"遵说明书"},{"name":"阿米替林（二线）","dose":"10–25 mg 睡前起始，逐渐加至 25–75 mg/日","note":"老年与心血管疾病患者慎用，注意抗胆碱能副作用与 QT 延长","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 SSRI、曲马多合用增加 5-HT 综合征；延长 QT"},{"name":"曲马多（二线/辅助）","dose":"50 mg 按需，最大 400 mg/d（老年减量）","note":"对神经痛有效，但有成瘾与癫痫风险，须限制疗程","renal":"CrCl <30 延长给药间隔","hepatic":"重度肝功能不全禁用","interact":"与 SSRI 合用增加 5-HT 综合征与癫痫风险"}],"nonDrug":["血糖控制为核心：HbA1c 目标个体化，多数 7% 左右，年轻无并发症者可 <6.5%","足部护理：每日检查双足、穿合适鞋袜、修剪趾甲、防止烫伤与外伤","足溃疡高危者：减压鞋、矫形器，定期足病门诊随访","疼痛的非药物疗法：经皮电刺激、心理干预与睡眠管理","下肢血管评估与处理（ABI <0.9 提示外周动脉疾病）"],"life":["戒烟限酒，控制血压与血脂","避免赤足行走、热水泡脚过久与使用热水袋","每年筛查足部感觉与血管，评估糖尿病足风险"]},"prog":"DPN 出现后多不可逆，但控糖可延缓进展；约 10%–20% 痛性神经病变者疼痛可长期存在；足溃疡与感染是截肢的主要前奏，规范筛查可显著降低截肢风险。","refs":["中国糖尿病足防治指南（2019）","中国 2 型糖尿病防治指南（2020 版）神经病变章节","糖尿病周围神经病理性疼痛诊疗专家共识（2021）"]},{"id":"ne_periodic_paralysis","name":"周期性瘫痪（低钾型/正常钾型）","aka":["Periodic paralysis","低钾性周期性瘫痪","正常血钾型周期性瘫痪","家族性周期性麻痹"],"rank":4,"basic":{"define":"一组以反复发作的弛缓性骨骼肌无力为特征的离子通道病，发作时血钾可降低、正常或升高，发作间期肌力正常，基因诊断可确定亚型；低钾型最常见，正常钾型少见。","risk":["阳性家族史（常染色体显性，CACNA1S、SCN4A、KCNJ2 等变异）","高碳水化合物饮食、过饱、饮酒、剧烈运动后休息与寒冷","甲亢（甲状腺毒性周期性瘫痪）","男性多于女性"],"epi":"低钾型周期性瘫痪患病率约 1/10 万，多在 10–20 岁起病，男性多见；甲状腺毒性周期性瘫痪在我国华南地区尤为常见，男性青壮年甲亢者风险高。"},"patho":"骨骼肌电压门控钠/钙通道功能异常导致静息膜电位不稳定，发作时钾离子由细胞外向细胞内转移（低钾型），使肌纤维失极化而不能兴奋；正常钾型表现为对钾摄入敏感、可伴心律失常。甲亢通过 Na-K-ATP 酶活性上调加重细胞内钾转移。","dx":{"criteria":["反复发作的四肢弛缓性无力，常于夜间或清晨醒时发现，对称、近端重于远端","发作时血清钾低（<3.5 mmol/L，低钾型）或正常（3.5–5.0 mmol/L，正常钾型）","发作持续数小时至数天，补钾或休息后自行缓解；发作间期肌力正常、腱反射恢复","肌电图发作期复合肌肉动作电位波幅下降，运动试验后下降 ≥30%–40%；发作间期正常","心电图低钾型可见 U 波、QT 延长；注意正常钾型的心律失常","基因检测（CACNA1S、SCN4A、KCNJ2）可确诊","甲状腺功能检查排除甲状腺毒性周期性瘫痪"],"workup":["发作时与间期血清钾、钠、镁、磷酸盐、肌酸激酶（发作后可升）","甲状腺功能（TSH、FT3、FT4）","心电图与电解质同步监测（尤其正常钾型与严重低钾）","肌电图运动试验（长时运动试验或冷负荷）","基因检测：CACNA1S（低钾型 1 型）、SCN4A（低钾型 2 型/正常钾型）、KCNJ2（Andersen-Tawil 综合征）","评估继发性低钾原因：利尿剂、甘草、呕吐、腹泻、Gitelman 综合征、肾小管酸中毒"],"grading":"按发作时血清钾分低钾型、正常钾型与高钾型；发作严重程度以肌力分级（MRC 0–5 级）与发作频率评估。"},"ddx":[{"name":"慢性炎性脱髓鞘性多发性神经病（ne_cidp）","point":"与本类 ne_cidp 的鉴别点：CIDP 为持续性进展性无力伴感觉障碍与腱反射消失，血钾正常、脑脊液蛋白升高，无发作性缓解；周期性瘫痪发作间期完全正常且无感觉障碍。"},{"name":"吉兰-巴雷综合征（gb）","point":"GBS 有前驱感染史、数天内快速进展、反射消失、脑脊液蛋白细胞分离，血钾正常。"},{"name":"其他低钾性全身无力（甲状腺毒性、药物性、Gitelman 综合征）","point":"有明确病因（甲亢、利尿剂、甘草、肾小管病变），去除病因后不再发作。"},{"name":"重症肌无力（mg）","point":"波动性眼肌与球部无力、晨轻暮重、疲劳试验阳性、抗 AChR 抗体阳性，血钾正常；周期性瘫痪累及肢体、眼外肌不明显。"},{"name":"急性脊髓炎或脊髓压迫","point":"有感觉平面与括约肌功能障碍、病理征，MRI 见脊髓病变；周期性瘫痪无感觉与括约肌障碍。"}],"tx":{"drug":[{"name":"氯化钾（发作期补钾）","dose":"低钾型：口服氯化钾 10% 溶液 10–20 mL 或片剂 0.5–1 g，每 1–2 h 复查血钾，必要时重复，总量不超过 8 g/d；不能口服者仅在严密监测下静脉补钾；正常钾型补钾需谨慎","note":"低钾型以口服为主，避免快速静脉补钾引起心律失常；补钾期间监测血钾与心电图","renal":"肾功能不全者补钾须极慎，防高钾血症","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI、ARB 合用增加高钾风险"},{"name":"乙酰唑胺（预防低钾型）","dose":"250 mg bid–tid（部分患者 125 mg qd 起），按发作频率调整","note":"低钾型首选预防用药，可减少发作频率；注意代谢性酸中毒、肾结石与感觉异常","renal":"肾功能不全（CrCl <50）无效或慎用","hepatic":"肝硬化患者可能诱发肝性脑病","interact":"与噻嗪类、托吡酯、阿司匹林合用增加低钾与酸中毒风险"},{"name":"螺内酯（保钾利尿剂，预防）","dose":"遵说明书（常用 25–100 mg/d）","note":"减少钾丢失，常与乙酰唑胺联用；注意高钾血症与男性乳房发育","renal":"肾功能不全慎用","hepatic":"谨慎使用，定期监测血钾","interact":"与 ACEI/ARB、非甾体抗炎药合用增加高钾风险"},{"name":"氢氯噻嗪（正常钾型）","dose":"遵说明书（常用 12.5–25 mg qd 起）","note":"正常钾型预防用药，可轻度降低血钾；须监测血钾与尿酸","renal":"CrCl <30 一般无效","hepatic":"肝硬化慎用","interact":"与锂、地高辛、非甾体抗炎药相互作用"},{"name":"美托洛尔（甲亢相关）","dose":"遵说明书，按甲亢心率控制剂量","note":"甲状腺毒性周期性瘫痪者需抗甲状腺药物治疗甲亢，β 受体阻滞剂减轻发作","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["发作期静息与保暖，避免寒冷与剧烈运动后立即休息","严重呼吸肌受累或心律失常者需监护与机械通气（罕见但须识别）","甲亢者行抗甲状腺治疗（药物、I-131 或手术）","正常钾型发作时可补充氯化钠与葡萄糖，避免钾摄入诱发","遗传咨询与基因检测，家庭成员发作识别教育"],"life":["低碳水化合物、低盐、分次少量进食，避免过饱与大量甜食","避免饮酒、剧烈运动后骤停与冷暴露","保持规律作息，发作时记录诱因与血钾以调整预防用药"]},"prog":"低钾型多在 30 岁后发作逐渐减少，少数可出现持续性肌病（肌活检见空泡）；正常钾型与 Andersen-Tawil 综合征可伴致命性心律失常；甲亢相关者甲亢控制后不再发作。","refs":["中国神经肌肉疾病与离子通道病诊治专家共识（2019）","中华医学会神经病学分会 周期性麻痹诊治建议","中国甲状腺功能亢进症诊治指南（2022）相关章节"]},{"id":"ne_dysautonomia","name":"自主神经疾病（体位性低血压）","aka":["Autonomic neuropathy","体位性低血压","Orthostatic hypotension","自主神经功能不全"],"rank":5,"basic":{"define":"自主神经系统对心血管、汗腺、胃肠道与膀胱调节功能受损的一类疾病，以体位性低血压最常见、致残最重，表现为站立时头晕、视物模糊、黑蒙与晕厥，也可伴无汗、便秘、尿潴留与性功能障碍。","risk":["糖尿病病程长（糖尿病性自主神经病变）","老年人与长期卧床","帕金森病、多系统萎缩、Lewy 体痴呆等神经变性病","淀粉样变、自身免疫性自主神经节病","药物：降压药、α 受体阻滞剂、三环类、左旋多巴"],"epi":"社区老年人中体位性低血压患病率约 5%–30%（年龄越大、合并高血压与糖尿病越多）；糖尿病患者自主神经病变约占 20%–40%，6 年以上病程者更常见。"},"patho":"站立时血液淤积于下肢与内脏，需通过压力反射使交感张力升高、心率上升以维持血压；糖尿病、淀粉样变或神经变性使节段性去甲肾上腺素释放减少、压力感受器反射钝化，导致立位血压下降；年龄相关的动脉僵硬度增加、容量不足与药物（尤其 α 受体阻断）进一步加重。","dx":{"criteria":["站起时头晕、视物模糊、乏力、认知变慢或晕厥","卧立位血压：站立 3 min 内收缩压下降 ≥20 mmHg 或舒张压下降 ≥10 mmHg","神经源性自主神经衰竭：立位心率增加 <15 次/分（或心率增加 <0.5 次/分每 mmHg 收缩压下降）","伴随：无汗/少汗、餐后低血压、夜间卧位高血压、便秘、尿潴留、勃起功能障碍","排除容量不足、出血、脱水、药物、心源性所致血压下降"],"workup":["卧立位血压与心率（至少平卧 5 min，站 1、3 min 重复），必要时直立倾斜试验","24 h 动态血压：筛查夜间卧位高血压与餐后低血压","血常规、电解质、血糖、糖化血红蛋白、肾功能、甲状腺功能、皮质醇（排除肾上腺功能不全）","自主神经功能试验：Valsalva 试验、深呼吸心率变异、定量轴索反射出汗试验","血浆去甲肾上腺素（卧位与立位）与 123I-MIBG 心肌显像（鉴别神经节后病变）","α3 乙酰胆碱受体抗体（免疫性自主神经节病）","药物史：降压药、α 受体阻滞剂、抗抑郁药、左旋多巴、利尿剂"],"grading":"体位性低血压诊断标准：由卧位/坐位站立 3 min 内收缩压下降 ≥20 mmHg 或舒张压下降 ≥10 mmHg；神经源性者立位心率上升不足，提示交感反射受损。"},"ddx":[{"name":"帕金森叠加综合征（ne_parkinson_plus）","point":"与本类 ne_parkinson_plus 的鉴别点：MSA 的自主神经衰竭来得早且重（尿失禁 + 体位性低血压），并伴对左旋多巴反应差的帕金森综合征或小脑性共济失调；纯自主神经病变无锥体外系与小脑体征。"},{"name":"糖尿病性周围神经病（ne_dpn）","point":"DPN 以远端对称感觉障碍为主，自主神经受累可合并出现；若无糖尿病病史与其他神经症状，应排查免疫性自主神经节病、淀粉样变。"},{"name":"血管迷走性晕厥","point":"多为年轻人站立或情绪刺激下出现冷汗、恶心等前驱，血压与心率同时骤降、短暂意识丧失，间期正常；体位性低血压为持续站立性下降。"},{"name":"心源性晕厥","point":"运动或情绪诱发、无前驱，心电图与动态心电监护见心律失常或结构性心脏病，立位血压正常。"},{"name":"药物性低血压","point":"降压药、α 受体阻滞剂、抗精神病药或三环类使用后出现，调整药物后改善；无汗与胃肠症状通常不明显。"}],"tx":{"drug":[{"name":"米多君","dose":"2.5 mg bid–tid 起始，按需加至 10 mg tid；避免睡前 4 h 内服药","note":"一线升压药，注意卧位高血压、尿潴留与头皮麻木；用药前后测卧立位血压","renal":"CrCl <30 慎用","hepatic":"重度肝功能不全慎用","interact":"与 MAO 抑制剂、三环类、氟氢可的松并用有血压升高与心律失常风险"},{"name":"氟氢可的松","dose":"0.05–0.2 mg qd，按需增量","note":"增加容量升压，监测低钾、水肿与卧位高血压；老年人与心衰者慎用","renal":"肾功能不全慎用","hepatic":"遵说明书","interact":"增强排钾，与甘草、利尿剂合用加重低钾"},{"name":"屈昔多巴","dose":"100 mg tid 起始，按反应加至 200–600 mg tid","note":"用于神经源性体位性低血压；服药后需保持直立活动、避免长时间平卧","renal":"重度肾功能不全慎用","hepatic":"遵说明书","interact":"与非选择性 MAO 抑制剂禁忌合用；与三环类合用可能致高血压"},{"name":"甲氧明/去甲肾上腺素类（急症）","dose":"遵说明书","note":"严重晕厥伴外伤或血流动力学不稳定时按休克处理，非日常用药","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["第一线非药物：增加水与盐摄入（每日水 2–2.5 L、盐 6–10 g，需评估心肾功能）、症状前快速饮水 300–500 mL","弹力袜（压力 ≥30 mmHg）与腹带，避免长时间站立与餐后立即活动","睡眠时抬高床头 10–20 cm，减轻卧位高血压与夜尿增多","少量多餐、减少高碳水餐，餐后短时平卧","停用或减量致低血压药物（α 受体阻滞剂、降压药、三环类）","识别与治疗原发病：糖尿病控糖、胃肠动力障碍处理、α3 抗体阳性者按免疫性自主神经节病治疗"],"life":["起床与站立时缓慢，先坐 1–2 min 再站","识别症状与晕厥前驱，随身携带液体与就医信息卡","避免热水浴、饮酒与炎热环境，注意夜间如厕跌倒风险"]},"prog":"预后取决于病因：糖尿病性自主神经病变多随病程缓慢进展，与心血管死亡风险增加相关；神经源性体位性低血压（MSA、纯自主神经病）多逐渐加重、易致跌倒骨折；早期识别与生活干预可显著减少晕厥与卧床并发症。","refs":["中国体位性低血压诊治专家共识（2019）","糖尿病自主神经病变诊治中国专家共识（2021）","中国晕厥诊断与治疗指南（2018）相关章节"]}]},{"id":"cvd_more","name":"脑血管病（补充）","rank":41,"summary":"本类为脑血管病补充条目。颅内静脉窦血栓的核心是识别“头痛＋颅高压＋局灶体征”这一组合：D-二聚体用于低危者排除，MRV/CTV 用于确诊，抗凝是唯一被证实有效的基石治疗，即使已合并出血性梗死也不停用（HIT/VITT 与活动性大出血除外），疗程按诱因 3–6 个月或更长。","compare":[],"diseases":[{"id":"stk_cvst","name":"颅内静脉窦血栓","aka":["CVST","Cerebral Venous Sinus Thrombosis","颅内静脉窦血栓形成","脑静脉窦血栓","颅内静脉系统血栓形成"],"rank":1,"basic":{"define":"颅内静脉窦（上矢状窦、横窦、乙状窦、直窦、海绵窦）和/或皮层静脉内血栓形成，导致静脉回流受阻、颅内压升高及静脉性梗死或出血，是青年卒中的重要原因。","risk":["妊娠与产褥期，尤其产后 6 周内","口服复方避孕药或激素替代治疗","遗传性易栓症（因子 V Leiden、凝血酶原 G20210A、蛋白 C/S 或抗凝血酶缺乏）与抗磷脂综合征","局部感染（中耳炎、乳突炎、鼻窦炎、牙源性感染）","脱水、严重贫血、肥胖、头部外伤或腰椎穿刺后","COVID-19 感染及腺病毒载体疫苗接种后 VITT（罕见）"],"epi":"年发病率约 1.3–1.6/10 万，占全部卒中不足 1%，但占青年卒中约 0.5%–1%；女性多于男性（约 3:1），发病高峰 20–50 岁，产后与口服避孕药人群风险显著升高。"},"patho":"血栓使静脉窦引流受阻，毛细血管静水压升高，血脑屏障破坏，产生血管源性水肿与颅内压升高；皮层静脉受累时可出现静脉性梗死，因静脉压高、侧支循环差，约 30%–40% 合并点片状出血甚至血肿。上矢状窦血栓多致双下肢无力与癫痫，横窦血栓可仅表现为头痛与视乳头水肿，海绵窦血栓则出现眼球突出、结膜水肿与眼肌麻痹。","dx":{"criteria":["头痛为最常见症状（80%–90%），多呈进行性，卧位、咳嗽或用力时加重，可伴恶心呕吐、视物模糊与搏动性耳鸣","颅内压升高证据：视乳头水肿（约 30%–50%）、腰穿开放压 >250 mmH2O（>2.45 kPa）且无占位效应","局灶体征：偏瘫、失语、偏身感觉障碍；海绵窦型见眼睑下垂、眼球固定、结膜水肿与眼球突出","癫痫发作占 30%–40%，可为局灶性或全面性；意识障碍从嗜睡到昏迷提示广泛血栓或脑疝前期","D-二聚体 <500 μg/L（FEU）且临床低危时基本可排除；升高不特异（感染、妊娠、肿瘤、术后均可），不能单独确诊","确诊依赖神经影像：CTV 或 MRV 见窦内充盈缺损与“空三角征”；MRI 平扫血栓信号随时期变化，亚急性期 T1 呈高信号","腰穿：压力升高，细胞数正常或轻度增多，蛋白轻度升高，糖正常；用于排除感染性与癌性脑膜炎","需排除动脉性卒中、可逆性脑血管收缩综合征与特发性颅内压增高"],"workup":["急诊头颅 CT 平扫排除出血与占位，联合 CTV（首选，敏感度约 75%–100%）；孕妇或肾功能不全者选 MRV","MRI＋MRV：T1、T2、FLAIR、DWI、SWI，评估皮层静脉梗死、微出血与血栓时期（T1 高信号提示亚急性期）","DSA：仅在无创影像阴性而高度怀疑，或拟行血管内治疗时使用","腰穿：开放压、细胞计数、蛋白、糖、涂片与培养、隐球菌抗原、细胞学；大面积梗死或脑疝风险者先影像评估再谨慎操作","病因筛查：D-二聚体、凝血四项、抗磷脂抗体（狼疮抗凝物、抗 β2-GPI、抗心磷脂，间隔 12 周复查）、蛋白 C/S、抗凝血酶、因子 V Leiden 与凝血酶原基因、同型半胱氨酸、ESR/CRP、ANA、HIV、妊娠试验","感染源筛查：耳镜、乳突与鼻窦 CT、牙科检查；发热者血培养"],"grading":"按累及部位分上矢状窦、横窦/乙状窦、直窦、海绵窦与单纯皮层静脉血栓；按病因分感染性与非感染性；按严重程度结合意识水平（GCS）、是否合并静脉性梗死或出血、是否多窦受累及有无脑疝征象。"},"ddx":[{"name":"缺血性卒中（stk_ischemic）","point":"本大类仅含 CVST，最易混淆的是同科室“脑血管病”大类的缺血性卒中：CVST 多见于青年，起病相对缓慢，头痛与视乳头水肿突出、癫痫比例高，病灶不符合动脉供血区且常伴出血；缺血性卒中按血管分布、DWI 弥散受限，MRV/CTV 示静脉窦通畅。"},{"name":"特发性颅内压增高（IIH）","point":"育龄肥胖女性、慢性头痛与视乳头水肿，影像见空蝶鞍与视神经鞘增宽，静脉窦通畅、D-二聚体多正常；CVST 起病更急、可有局灶体征，MRV/CTV 见充盈缺损。"},{"name":"细菌性脑膜炎","point":"发热、脑膜刺激征，CSF 细胞显著增多、糖降低、病原学阳性；CVST 可继发于感染，须在抗凝前留取 CSF，两者可并存。"},{"name":"先兆偏头痛（ne_migraine）","point":"发作性、可逆的视觉或感觉先兆持续 5–60 min，头痛 4–72 h，发作间期完全正常，影像与静脉窦无异常；CVST 头痛持续进展并伴视乳头水肿与局灶体征。"},{"name":"可逆性脑血管收缩综合征（RCVS）","point":"反复雷击样头痛，DSA 见多发节段性血管狭窄（串珠样），1–3 个月可逆，静脉窦通畅；CVST 以进行性头痛与颅高压为主。"},{"name":"脑肿瘤或癌性脑膜炎","point":"进行性头痛与颅高压，MRI 见占位或弥漫脑膜强化，CSF 细胞学可查见肿瘤细胞；静脉窦通畅。"},{"name":"硬脑膜动静脉瘘","point":"搏动性耳鸣、头痛与视乳头水肿，DSA 见动静脉分流；单纯 MRV 易漏诊，需 DSA 确诊。"}],"tx":{"drug":[{"name":"低分子肝素（依诺肝素）","dose":"1 mg/kg 皮下注射 q12h（体重 >100 kg 或肾功能不全者按抗 Xa 因子调整；也可 1.5 mg/kg qd）","note":"急性期首选抗凝，影像确诊后尽快启动，不必等待病因筛查结果；合并出血性梗死仍应抗凝，HIT/VITT 与活动性大出血除外","renal":"CrCl <30 减为 1 mg/kg qd 或改用普通肝素","hepatic":"严重肝病伴凝血障碍者慎用，监测血小板","interact":"与抗血小板药、NSAIDs 合用增加出血；不与磺达肝癸钠联用"},{"name":"普通肝素","dose":"初始 80 U/kg 静推，继以 18 U/kg/h 泵入，按 APTT 调整（目标为正常上限的 1.5–2.5 倍）","note":"用于严重肾功能不全、广泛血栓或拟行血管内治疗者；需监测血小板防治 HIT","renal":"经网状内皮系统清除，肾功能不全无需减量，但需监测","hepatic":"肝硬化伴凝血障碍者慎用","interact":"与抗血小板药、NSAIDs、溶栓药合用显著增加出血"},{"name":"华法林","dose":"2.5–3 mg qd 起始（中国人群常用），与低分子肝素重叠至少 5 d，INR 达 2.0–3.0 后停肝素；维持目标 INR 2.0–3.0","note":"抗磷脂综合征（尤其三抗阳性）、重度遗传性易栓症与复发病例首选华法林而非 DOAC","renal":"肾功能不全无需调整，但需更频繁监测 INR","hepatic":"肝功能不全时凝血因子合成减少，需减量并密切监测 INR","interact":"与胺碘酮、甲硝唑、复方磺胺甲噁唑合用升高 INR；与利福平、卡马西平、圣约翰草合用降低疗效"},{"name":"利伐沙班","dose":"20 mg qd 随餐口服；CrCl 15–50 mL/min 减为 15 mg qd","note":"用于非抗磷脂综合征、无严重出血风险者的长期抗凝；CVST 证据少于华法林，妊娠期禁用","renal":"CrCl 15–50 减量，<15 避免使用","hepatic":"Child-Pugh B/C 避免使用","interact":"与酮康唑、利托那韦等强 CYP3A4/P-gp 抑制剂合用增加出血；与利福平、卡马西平合用降低疗效"},{"name":"甘露醇","dose":"20% 甘露醇 125–250 mL 静滴 q6–8h，按颅压、尿量与血浆渗透压调整","note":"用于颅高压症状明显或视力受威胁者；监测渗透压（目标 <320 mOsm/L）、肾功能与电解质","renal":"少尿或无尿者禁用","hepatic":"遵说明书","interact":"与肾毒性药物（氨基糖苷类、两性霉素 B）合用增加肾损伤"},{"name":"乙酰唑胺","dose":"500–1000 mg/d 分 2 次口服","note":"用于视乳头水肿进行性加重、视力受威胁者的辅助降颅压；需眼科定期查视野","renal":"肾功能不全慎用，易致代谢性酸中毒","hepatic":"肝硬化患者可诱发肝性脑病，慎用","interact":"与托吡酯、大剂量阿司匹林合用增加酸中毒与低钾风险"},{"name":"左乙拉西坦","dose":"500 mg bid 起始，按需加至 1000 mg bid","note":"仅用于已发生癫痫发作的患者，不推荐对所有 CVST 常规预防性抗癫痫","renal":"CrCl 50–80 为 1000 mg/d；30–50 为 750 mg/d；<30 为 500 mg/d","hepatic":"重度肝功能不全减量","interact":"经肾排泄，与丙戊酸无明显相互作用；避免与其他中枢抑制剂合用"}],"nonDrug":["抗凝疗程：暂时性诱因（妊娠、避孕药、感染、脱水）3 个月；特发性或轻度易栓症 6–12 个月；抗磷脂综合征、复发或重度遗传性易栓症长期抗凝","血管内治疗（窦内溶栓、机械取栓）：用于规范抗凝后仍恶化、广泛血栓伴意识障碍者，需在有经验的中心实施","去骨瓣减压：适用于恶性颅高压、脑疝征象或大面积静脉性梗死伴占位效应","感染性 CVST：足量抗感染＋乳突炎或鼻窦炎手术清创，抗凝不应中断","妊娠期：全程低分子肝素，产后继续至少 6 周且总疗程不少于 3 个月；停用口服避孕药并改用其他避孕方式"],"life":["避免脱水与长时间制动，发热、呕吐、腹泻时及时补液","控制体重、戒烟，产后与围手术期评估血栓风险","抗凝期间避免剧烈对抗性运动与随意合用 NSAIDs","3–6 个月复查 MRV 与视野，出现新发头痛、视力下降或肢体无力及时复诊"]},"prog":"规范抗凝后约 80% 患者可恢复独立生活（mRS 0–1）；急性期病死率 5%–10%，多死于脑疝或大面积静脉性梗死；约 2%–5% 复发，抗磷脂综合征与遗传性易栓症复发风险更高；10%–20% 遗留视力损害、认知障碍或癫痫。","refs":["中国颅内静脉系统血栓形成诊断和治疗指南（2015，中华医学会神经病学分会脑血管病学组）","欧洲卒中组织（ESO）颅内静脉窦血栓形成诊疗指南（2017）","AHA/ASA 颅内静脉窦血栓形成诊断与处理科学声明（2011）"]}]},{"id":"headache_more","name":"继发性头痛","rank":42,"summary":"本类聚焦由止痛药物使用不当引起的继发性头痛。识别关键是量化每月急性用药天数（单纯镇痛药 ≥15 天、曲普坦/阿片/复方制剂 ≥10 天），治疗核心是完全撤药联合规范预防用药，而非继续加用止痛药。","compare":[],"diseases":[{"id":"ne_moh","name":"药物过度使用性头痛","aka":["MOH","Medication Overuse Headache","药物过度使用性头痛","止痛药反跳性头痛","药物滥用性头痛"],"rank":1,"basic":{"define":"原发性头痛（多为偏头痛或紧张型头痛）患者长期、规律地过度使用急性期止痛药物，导致头痛频率增加、对药物依赖，停药后头痛可改善的继发性头痛。","risk":["女性，男女约 3:1","慢性偏头痛或慢性紧张型头痛、预防性治疗不充分","焦虑、抑郁、睡眠障碍与慢性疼痛","过度使用阿片类、巴比妥类或含咖啡因的复方镇痛药","吸烟与每日大量咖啡因摄入","低社会经济水平与自行购买非处方止痛药"],"epi":"全球患病率约 1%–2%，在慢性每日头痛人群中占 30%–50%；我国慢性头痛门诊中 MOH 约占 1/3，女性为男性的 3 倍，30–50 岁高发。"},"patho":"长期反复使用急性止痛药使三叉神经血管系统反复激活、三叉神经尾核与丘脑发生中枢敏化，中脑导水管周围灰质的下行疼痛调控功能减退；5-HT 与 CGRP 系统受体下调，停药后出现反跳性头痛与戒断症状，形成“用药—头痛加重—更多用药”的循环。","dx":{"criteria":["头痛 ≥15 天/月，且已存在原发性头痛（多为偏头痛）","规律过度使用急性对症药物超过 3 个月","单纯镇痛药（对乙酰氨基酚、NSAIDs、阿司匹林）≥15 天/月；曲普坦、阿片类、麦角胺或复方镇痛药 ≥10 天/月；多种药物合用 ≥10 天/月","停药后头痛频率下降（多在 2 个月内下降 ≥50%）支持诊断","不能用其他 ICHD-3 诊断更好解释","需有至少 4 周的头痛日记与用药日记（记录天数、剂量与药物种类）作为量化依据"],"workup":["头痛日记 ≥4 周：头痛天数、强度、急性药名称与剂量，特别注意复方感冒药与中成药中的咖啡因、对乙酰氨基酚","红旗征筛查：新发或突发雷击样头痛、进行性加重、夜间痛醒、发热、体重下降、局灶体征、50 岁后新发，阳性者行头颅 MRI/CT","量表：HIT-6、MIDAS、PHQ-9、GAD-7、匹兹堡睡眠质量指数","血常规、肝肾功能、电解质与血压（长期 NSAIDs 者评估胃肠与肾损害）","疑颅内高压/低压者查眼底与腰穿；疑睡眠呼吸暂停者行多导睡眠监测"],"grading":"ICHD-3 按过度使用药物分为 8 个亚型（麦角胺、曲普坦、单纯镇痛药、阿片类、复方镇痛药、多种药物、其他、未特定）；临床按是否合并慢性偏头痛、是否存在药物依赖或戒断症状分层。"},"ddx":[{"name":"慢性偏头痛（ne_migraine）","point":"本大类仅含 MOH，最易混淆的是同科室“头痛与痴呆”大类的慢性偏头痛：两者均 ≥15 天/月，但慢性偏头痛的急性药使用 <10–15 天/月，充分预防治疗后头痛可控制；MOH 的关键是药量超标且停药后改善，二者常并存，需同时处理。"},{"name":"慢性紧张型头痛（ne_tension_cluster）","point":"双侧压迫或紧箍样、轻中度、不伴呕吐、日常活动不加重；MOH 多为偏头痛样伴畏光畏声与活动加重。"},{"name":"颅内占位或颅内高压","point":"进行性加重、晨起呕吐、视乳头水肿与局灶体征，MRI 见占位或脑室扩大；MOH 影像正常且与用药量密切相关。"},{"name":"低颅压头痛","point":"直立 15 min 内加重、平卧缓解，有腰穿或外伤史，MRI 见硬膜强化与静脉窦扩张；MOH 无体位性特征。"},{"name":"巨细胞动脉炎（颞动脉炎）","point":"50 岁以上、颞部压痛、咀嚼无力、ESR 与 CRP 显著升高，可有视力威胁，激素治疗迅速有效。"},{"name":"睡眠呼吸暂停相关头痛","point":"晨起头痛、打鼾与日间嗜睡，多导睡眠监测 AHI ≥5 次/h，持续正压通气后头痛减少。"},{"name":"药物性头痛（硝酸酯类、钙拮抗剂、磷酸二酯酶抑制剂）","point":"头痛与用药时间明确相关，停药或减量后缓解，无急性止痛药过量史。"}],"tx":{"drug":[{"name":"停用过度使用药物（撤药治疗）","dose":"设定停药日：门诊 1–2 周内完全停用，住院可即刻停用；阿片类、巴比妥类、苯二氮䓬类按每周 10%–20% 递减","note":"完全撤药优于逐渐减量（阿片/巴比妥/苯二氮䓬除外）；撤药后反跳性头痛一般持续 2–10 天，需提前告知患者","renal":"遵说明书","hepatic":"遵说明书","interact":"撤药期避免再次使用同类止痛药，否则前功尽弃"},{"name":"泼尼松（撤药期桥接）","dose":"20–30 mg qd 口服，连用 3–5 d","note":"仅用于撤药期反跳性头痛较重者，证据不一致，不作常规推荐；糖尿病患者监测血糖","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血；与降糖药作用拮抗"},{"name":"托吡酯","dose":"25 mg 睡前起始，每周递增 25 mg，目标 50 mg bid（最大 200 mg/d）","note":"偏头痛预防一线，兼有减重作用，适合合并肥胖者；注意感觉异常、肾结石、认知减慢与言语找词困难","renal":"CrCl <70 剂量减半，<30 慎用","hepatic":"肝功能不全慎用","interact":"与乙酰唑胺、唑尼沙胺合用增加结石与代谢性酸中毒；<200 mg/d 时对口服避孕药影响小"},{"name":"坎地沙坦","dose":"16 mg qd 起始，可增至 32 mg qd","note":"ARB 类偏头痛预防用药，证据中等，适合合并高血压者；育龄女性需有效避孕","renal":"CrCl <30 慎用，监测血钾与肌酐","hepatic":"重度肝功能不全慎用","interact":"与保钾利尿剂、补钾剂合用致高钾；与锂合用增加锂中毒"},{"name":"普萘洛尔","dose":"40 mg bid 起始，可增至 120–240 mg/d；缓释制剂 80 mg qd 起始","note":"偏头痛预防一线；注意心动过缓、低血压、支气管痉挛、乏力与抑郁","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与维拉帕米、地尔硫䓬合用致心动过缓与传导阻滞；可掩盖低血糖症状"},{"name":"阿米替林","dose":"10–25 mg 睡前起始，每 1–2 周增加 10–25 mg，常用 25–75 mg/d","note":"合并慢性紧张型头痛、失眠或焦虑者优选；老年人注意抗胆碱能作用、体位性低血压与 QT 延长","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 SSRI/SNRI、曲马多合用增加 5-HT 综合征；延长 QT，避免与氟哌啶醇等合用"},{"name":"肉毒毒素 A","dose":"155–195 U 头颈肩部肌肉多点注射，每 12 周 1 次（PREEMPT 方案 31 个注射点）","note":"用于慢性偏头痛（≥15 天/月，其中 ≥8 天为偏头痛），对合并 MOH 者有效；需由有经验医师操作","renal":"遵说明书","hepatic":"遵说明书","interact":"与氨基糖苷类、肌肉松弛剂合用增加神经肌肉阻滞"},{"name":"CGRP 通路单抗（依瑞奈尤单抗/加卡奈珠单抗）","dose":"依瑞奈尤单抗 70 mg 皮下 qm（或 140 mg qm）；加卡奈珠单抗 240 mg 负荷后 120 mg qm，遵说明书","note":"用于慢性偏头痛合并 MOH 的预防，可减少急性药使用；国内可及性与费用受限，不通过肝肾代谢","renal":"无需调整","hepatic":"无需调整","interact":"不与 CGRP 受体拮抗剂联用；无显著药物相互作用"}],"nonDrug":["多学科管理：神经科、心理科与康复科协作，撤药前充分告知反跳性头痛的持续时间与应对方式","认知行为治疗、生物反馈与放松训练，作为撤药期的辅助手段","严格限制急性期用药：单纯镇痛药 ≤2–3 天/周，曲普坦 ≤2 天/周，任何药物每月不超过 10 天","住院或日间病房撤药方案：适用于门诊撤药失败、多种药物依赖或合并严重精神共病者","治疗共病：睡眠障碍、焦虑抑郁、睡眠呼吸暂停；避免使用阿片类与巴比妥类"],"life":["规律三餐、睡眠与有氧运动，避免过度疲劳与情绪应激","咖啡因摄入限制在 200 mg/d 以内","超重者减重，记录头痛与用药日记直至稳定 3 个月","不自行购买复方止痛药或感冒药，取药时主动告知医师头痛病史"]},"prog":"规范撤药联合预防治疗后，60%–70% 患者在 2–3 个月内头痛频率下降 ≥50%；1 年内复发率 20%–40%，阿片类或巴比妥类过度使用、合并抑郁及预防治疗不足者复发风险更高。","refs":["药物过度使用性头痛诊断与治疗中国专家共识（2025，中华医学会神经病学分会）","中国偏头痛诊治指南（2022 版）","国际头痛疾病分类第 3 版（ICHD-3，2018）"]}]},{"id":"cns_infect_more","name":"中枢神经系统感染（补充）","rank":43,"summary":"本类为中枢感染补充条目：神经梅毒依靠血清学＋CSF 白细胞/蛋白＋CSF-VDRL 确诊，青霉素 G 大剂量静滴 10–14 天为首选，须警惕吉海反应；朊蛋白病以快速进展性痴呆、MRI 皮层绸带征与 CSF RT-QuIC 为核心，无特效治疗，重点在排除可治性病因、感染控制与知情沟通。","compare":[{"diseaseId":"ne_neurosyphilis","dx":"梅毒血清学（RPR/TRUST＋TPPA）阳性，CSF 白细胞 >5/μL、蛋白 >0.45 g/L，CSF-VDRL 阳性可确诊；临床可为脑膜型、脑膜血管型、麻痹性痴呆或脊髓痨","key":"病程以月–年计，CSF 有细胞增多，青霉素治疗有效"},{"diseaseId":"ne_prion","dx":"快速进展性痴呆（多 <1 年）伴肌阵挛或小脑/锥体/锥体外系体征，MRI DWI 见皮层绸带征或基底节高信号，CSF RT-QuIC 阳性而细胞数正常","key":"病程以周–月计，CSF 无炎症、梅毒血清学阴性，抗感染治疗无效"}],"diseases":[{"id":"ne_neurosyphilis","name":"神经梅毒","aka":["Neurosyphilis","麻痹性痴呆","脊髓痨","General paresis","Tabes dorsalis"],"rank":1,"basic":{"define":"苍白密螺旋体（Treponema pallidum）在感染早期经血行或淋巴侵入中枢神经系统，经数年乃至数十年后引起脑膜、脑膜血管或脑实质损害的一组疾病，包括无症状型、脑膜型、脑膜血管型、麻痹性痴呆、脊髓痨及眼/耳梅毒。","risk":["不安全性行为，尤其男男性行为","HIV 合并感染（进展更快，可在早期出现）","早期梅毒未规范治疗或血清固定","妊娠期感染（可致先天梅毒）","免疫抑制状态或免疫抑制治疗"],"epi":"我国梅毒报告发病率约 30–35/10 万，神经梅毒约占梅毒患者的 3%–7%；HIV 合并者神经梅毒风险增加 2–3 倍，且潜伏期缩短。"},"patho":"螺旋体在二期梅毒时即可侵入脑脊液，早期以脑膜淋巴细胞与浆细胞浸润、脑膜增厚及小动脉内膜炎（Heubner 动脉炎）为主，导致脑膜血管型梗死；晚期出现皮层神经元丢失与胶质增生（麻痹性痴呆）、脊髓后索与后根脱髓鞘（脊髓痨）。HIV 患者启动 ART 后免疫重建可致症状暂时加重。","dx":{"criteria":["血清学：RPR/TRUST 阳性＋TPPA/TPHA/FTA-ABS 确认阳性；晚期神经梅毒约 20%–30% 血清 RPR 呈低滴度甚至阴性，但 TPPA 多持续阳性","CSF 白细胞 >5/μL（多为 10–100/μL，以淋巴细胞为主），蛋白 >0.5 g/L（部分标准 >0.45 g/L），糖正常或轻度降低","CSF-VDRL 阳性即可确诊（特异性 90%–100%，敏感性仅 30%–70%）；CSF FTA-ABS/TPPA 阴性有很高的阴性预测值","临床型：无症状型仅 CSF 异常；脑膜型见头痛、脑膜刺激征与脑神经麻痹（第 II、III、VI、VIII 对），多在感染后 1 年内；脑膜血管型呈卒中样起病，多为大脑中动脉分布，常无高血压、糖尿病等传统血管危险因素","麻痹性痴呆：人格改变、判断力下降、夸大妄想、言语含糊、Argyll Robertson 瞳孔（对光反射消失而调节反射存在）；脊髓痨：闪电样疼痛、感觉性共济失调、Romberg 阳性、括约肌障碍、膝反射消失与阿罗瞳孔","所有患者均需检测 HIV 抗体与 CD4 计数；眼梅毒表现为葡萄膜炎、视神经视网膜炎，耳梅毒表现为感音神经性耳聋与耳鸣"],"workup":["血清 RPR 滴度（固定同一种方法随访）＋TPPA 确认；HIV 抗体与 CD4/病毒载量","腰穿：开放压、细胞计数、蛋白、糖、CSF-VDRL、CSF-TPPA/FTA-ABS；治疗前必须留取基线标本","头颅 MRI 增强：脑膜强化、脑膜血管型见基底节或皮层梗死、麻痹性痴呆见额颞叶萎缩；脊髓 MRI 见后索萎缩或脊髓膜强化","眼科裂隙灯与眼底、纯音测听与脑干听觉诱发电位（疑眼/耳梅毒）","排除其他病因：CSF 隐球菌抗原、结核 PCR/IGRA、HSV PCR、自身免疫脑炎抗体、副肿瘤抗体、CSF 细胞学"],"grading":"按临床型分为无症状型、脑膜型、脑膜血管型、实质型（麻痹性痴呆、脊髓痨）与眼/耳梅毒；按感染时间分早期（<1 年）与晚期（>1 年）。"},"ddx":[{"name":"朊蛋白病（ne_prion）","point":"与本类 ne_prion 的鉴别点：朊蛋白病为快速进展性痴呆（数周–数月）伴肌阵挛与共济失调，MRI DWI 皮层绸带征，CSF RT-QuIC 阳性而细胞数正常、梅毒血清学阴性；麻痹性痴呆进展以月–年计，CSF 白细胞与蛋白升高、CSF-VDRL 阳性，青霉素治疗有效。"},{"name":"结核性脑膜炎（ne_tb_meningitis）","point":"亚急性发热头痛，CSF 蛋白显著升高（常 >1 g/L）、糖与氯化物明显降低，结核 PCR 或 IGRA 阳性，可见基底池脑膜强化与脑积水；脑膜血管型神经梅毒 CSF 糖多正常。"},{"name":"病毒性脑炎（ne_viral_enceph）","point":"急性发热、癫痫与意识障碍，MRI 累及颞叶内侧与岛叶，CSF HSV PCR 阳性，梅毒血清学阴性。"},{"name":"隐球菌性脑膜炎（ne_cryptococcal）","point":"多见于免疫抑制者，CSF 墨汁染色与隐球菌抗原阳性，颅内压显著升高，诱导治疗需两性霉素 B＋氟胞嘧啶。"},{"name":"缺血性卒中","point":"有高血压、糖尿病、房颤等危险因素，血管影像见动脉粥样硬化或闭塞；脑膜血管型神经梅毒多见于中青年、无传统危险因素且梅毒血清学阳性。"},{"name":"阿尔茨海默病","point":"隐袭进展数年的记忆障碍，无局灶体征与 CSF 细胞增多，梅毒血清学阴性；麻痹性痴呆多有性格改变与妄想且进展较快。"},{"name":"HIV 相关神经认知障碍","point":"HIV 阳性、CSF 病毒载量高，无梅毒血清学证据，规范 ART 后认知可改善；两者可合并存在，需同时评估。"}],"tx":{"drug":[{"name":"青霉素 G","dose":"1800–2400 万 U/d 静滴，每 4 h 300–400 万 U（或持续泵入），连用 10–14 d；合并 HIV 或重症者用 14 d","note":"首选方案，需住院完成；治疗前评估吉海反应风险，首剂后 2–8 h 密切观察","renal":"CrCl <15 减量至常规剂量的 50%–75%，血液透析后补充剂量，遵说明书","hepatic":"遵说明书","interact":"丙磺舒升高青霉素血药浓度；与氨基糖苷类同瓶配伍禁忌；大剂量可增强华法林抗凝"},{"name":"头孢曲松","dose":"2 g 静滴 qd，连用 10–14 d","note":"青霉素非速发型过敏或无法完成 10–14 天住院者的替代方案，脑脊液穿透性好","renal":"一般无需调整，透析患者不超过 2 g/d","hepatic":"遵说明书","interact":"与含钙输液同瓶禁忌（新生儿）；与华法林合用增加出血风险"},{"name":"普鲁卡因青霉素＋丙磺舒","dose":"普鲁卡因青霉素 240 万 U 肌注 qd＋丙磺舒 500 mg 口服 qid，连用 10–14 d","note":"门诊替代方案；注射部位疼痛明显，需备肾上腺素应对过敏反应，依从性较差","renal":"丙磺舒在 CrCl <30 mL/min 时避免使用","hepatic":"遵说明书","interact":"丙磺舒升高青霉素浓度，同时增加甲氨蝶呤、NSAIDs 的毒性"},{"name":"多西环素","dose":"100 mg 口服 bid，连用 28 d","note":"青霉素严重过敏且无法脱敏者的替代，CNS 穿透较差、证据有限，治疗后必须复查 CSF","renal":"CrCl <30 减量或延长给药间隔","hepatic":"重度肝功能不全慎用","interact":"与抗酸药、铁剂、钙剂间隔 2 h；增加光敏反应；与异维A酸合用增加颅内压"},{"name":"泼尼松（吉海反应预防）","dose":"30–40 mg/d 口服，于首剂青霉素前 1 d 开始，连用 3 d","note":"用于 CSF 白细胞显著升高、麻痹性痴呆或一般状况差者；吉海反应表现为发热、寒战、头痛加重与心动过速，多在首剂后 2–8 h 出现","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血；与降糖药作用拮抗"},{"name":"卡马西平（脊髓痨闪电样痛）","dose":"100 mg bid 起始，每周增加 100–200 mg，常用 400–800 mg/d","note":"闪电样疼痛对症治疗；用药前评估 HLA-B*1502（汉族人群 Stevens-Johnson 综合征风险）","renal":"遵说明书","hepatic":"肝功能不全慎用，定期查肝功能与血常规","interact":"强效 CYP3A4 诱导剂，降低口服避孕药、华法林、抗真菌药与部分抗癫痫药浓度"},{"name":"左乙拉西坦（合并癫痫）","dose":"500 mg bid 起始，按需加至 1500 mg bid","note":"用于脑膜/脑膜血管型合并癫痫发作者；不推荐对所有神经梅毒预防性用药","renal":"按 CrCl 调整（<30 减半至 500 mg bid 以下）","hepatic":"重度肝功能不全减量","interact":"经肾排泄，与丙戊酸无明显相互作用"}],"nonDrug":["治疗结束后每 6 个月复查 CSF 细胞计数与蛋白直至正常，通常需 2 年；CSF-VDRL 滴度可长期不降，不单独作为复发依据","HIV 合并者尽快启动 ART，警惕免疫重建炎症综合征导致症状短暂加重","性伴侣追踪与同步治疗，筛查淋病、衣原体、乙肝、丙肝等其他性传播感染","眼科与耳鼻喉科会诊；眼梅毒需局部糖皮质激素联合全身驱梅，防止视力丧失","神经康复与认知训练；癫痫患者规范抗癫痫治疗并评估驾驶与安全风险"],"life":["坚持安全性行为与避孕套使用，治疗期间避免饮酒","治疗后 6、12、24 个月复查血清 RPR 滴度，下降 ≥4 倍视为有效","妊娠期按同方案青霉素治疗（过敏者脱敏后使用），并随访新生儿","出现视力下降、听力减退、肢体无力或认知恶化及时复诊"]},"prog":"早期（脑膜型、脑膜血管型）规范治疗多可完全或部分恢复；麻痹性痴呆治疗后约 30%–40% 明显改善，多数遗留不同程度认知障碍；脊髓痨的闪电样痛与共济失调常难完全缓解；HIV 合并者复发率较高，需延长随访。","refs":["梅毒、淋病和生殖道沙眼衣原体感染诊疗指南（2020，中华医学会皮肤性病学分会）","美国 CDC 性传播感染治疗指南（2021）神经梅毒章节","欧洲 IUSTI/WHO 梅毒管理指南（2017）"]},{"id":"ne_prion","name":"朊蛋白病","aka":["Prion disease","Creutzfeldt-Jakob disease","CJD","克雅氏病","克-雅病","皮质-纹状体-脊髓变性"],"rank":2,"basic":{"define":"由异常折叠的朊蛋白（PrPSc）在中枢神经系统沉积所致的快速进展性、致死性神经变性病；散发性 CJD 占 85%–90%，其余为遗传性、医源性与变异型。","risk":["年龄 55–75 岁，sCJD 发病高峰 60–65 岁","PRNP 基因致病突变（家族性占 10%–15%）","医源性暴露：硬脑膜移植、垂体来源生长激素、角膜移植、未规范消毒的神经外科器械","变异型 CJD 与牛海绵状脑病暴露相关","多数散发病例无明确危险因素"],"epi":"全球 sCJD 年发病率约 1–2/100 万；我国尚无确切全国发病率，监测网络年报告数百例并随认识提高而增加；sCJD 中位发病年龄约 65 岁，vCJD 患者更年轻（多 <30 岁）。"},"patho":"正常朊蛋白 PrPC 的 α 螺旋构象转变为富含 β 折叠、抵抗蛋白酶 K 降解的 PrPSc，在神经元内聚集并诱导内质网应激与凋亡，形成皮层与深部灰质的海绵状空泡、星形胶质增生与神经元丢失。全病程无炎症反应，故 CSF 细胞数正常、影像无强化，血脑屏障完整。","dx":{"criteria":["快速进展性痴呆：病程 <2 年（sCJD 多 <1 年），从记忆、行为或视觉症状迅速进展至全面认知障碍","至少伴以下 2 项：肌阵挛、视觉或小脑症状（共济失调、眼球运动异常）、锥体束或锥体外系体征（痉挛、强直、舞蹈样动作）、无运动性缄默","MRI：DWI/FLAIR 见皮层绸带征（cortical ribboning）和/或尾状核、壳核高信号，敏感度 90% 以上；vCJD 见丘脑枕核高信号（hockey stick 征）","CSF：RT-QuIC 阳性（敏感度 90%–95%，特异度接近 99%）；14-3-3 蛋白阳性（敏感度约 85%，特异度较低，需结合临床）；总 tau 显著升高；细胞数正常（≤5/μL）","EEG：周期性尖慢复合波（1–2 Hz），仅 30%–50% 患者阳性，不是诊断必需条件","PRNP 基因测序发现致病突变支持遗传性 CJD，129 与 219 位密码子多态性影响表型与病程","排除可治性快速进展性痴呆（自身免疫性脑炎、甲状腺功能异常、维生素 B12 缺乏、神经梅毒、中枢淋巴瘤、中毒）","确诊需脑组织病理（海绵状变性、PrP 免疫组化）或 Western blot，临床多不行活检"],"workup":["头颅 MRI 含 DWI、FLAIR、SWI：发病 1–2 个月内最敏感，病情变化时复查","腰穿：细胞计数、蛋白、糖、RT-QuIC、14-3-3、总 tau、自身免疫脑炎抗体、副肿瘤抗体、梅毒与 HIV 血清学、细胞学","EEG 或视频脑电监测，寻找周期性尖慢复合波与癫痫样放电","PRNP 基因测序与三代家族史采集（遗传型可呈常染色体显性）","血液：甲状腺功能、维生素 B12、叶酸、同型半胱氨酸、肝肾功能、电解质、铜蓝蛋白、自身抗体、肿瘤标志物","胸腹盆 CT 与肿瘤筛查，排除副肿瘤综合征与中枢淋巴瘤"],"grading":"按病因分散发型（sCJD）、遗传型（gCJD）、医源型（iCJD）与变异型（vCJD）；sCJD 按 PRNP 129 密码子 MM/MV/VV 及 PrPSc 类型分 MM1、MV1、VV2 等分子亚型，病程与影像表现不同；临床分早期（精神行为或视觉症状）、中期（肌阵挛、进行性痴呆）、晚期（无运动性缄默、去皮层强直）。"},"ddx":[{"name":"神经梅毒（ne_neurosyphilis）","point":"与本类 ne_neurosyphilis 的鉴别点：麻痹性痴呆进展以月–年计，CSF 白细胞与蛋白升高、CSF-VDRL 阳性、血清梅毒抗体阳性，青霉素治疗有效；CJD 进展以周–月计，CSF 细胞数正常、RT-QuIC 阳性而梅毒血清学阴性。"},{"name":"自身免疫性脑炎","point":"亚急性精神行为异常、癫痫与运动障碍，血清或 CSF 抗 NMDAR、LGI1 等抗体阳性，MRI 见边缘系统高信号，免疫治疗有效。"},{"name":"阿尔茨海默病（ad）","point":"隐袭进展数年，以近事记忆障碍为主，无肌阵挛与快速恶化，MRI 见内侧颞叶萎缩，DWI 无皮层绸带征。"},{"name":"路易体痴呆（ne_dlb）","point":"波动性认知障碍、视幻觉、帕金森综合征与 REM 睡眠行为障碍，进展较慢，DWI 无皮层或基底节高信号。"},{"name":"血管性痴呆（ne_vad）","point":"阶梯式进展，有卒中史与血管危险因素，MRI 见多发梗死或广泛白质病变，无肌阵挛与特征性 DWI 改变。"},{"name":"代谢性或中毒性脑病","point":"甲状腺功能减退、维生素 B12 缺乏、低钠血症、锂中毒、Wernicke 脑病等，实验室检查异常，纠正病因后可逆。"},{"name":"中枢神经系统淋巴瘤","point":"MRI 见均匀强化的脑室旁团块，CSF 细胞学或立体定向活检确诊，糖皮质激素可短暂缩小病灶。"}],"tx":{"drug":[{"name":"氯硝西泮（肌阵挛）","dose":"0.5 mg 睡前起始，按需加至 0.5 mg bid–tid；老年人 0.25 mg 起始","note":"一线控制肌阵挛；注意嗜睡、跌倒与呼吸抑制，晚期患者慎防误吸","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与阿片类、其他苯二氮䓬类合用增加呼吸抑制"},{"name":"左乙拉西坦（肌阵挛/癫痫）","dose":"500 mg bid 起始，可加至 1000 mg bid","note":"用于肌阵挛与癫痫发作；部分患者出现激越或行为改变，需家属观察","renal":"按 CrCl 调整，<30 减量至 250–500 mg bid","hepatic":"重度肝功能不全减量","interact":"经肾排泄，与丙戊酸无明显相互作用"},{"name":"丙戊酸（肌阵挛二线）","dose":"500 mg bid 起始，按临床反应与血药浓度调整","note":"用于氯硝西泮效果不佳的肌阵挛；监测肝功能、血氨与血小板","renal":"遵说明书","hepatic":"严重肝病或有尿素循环障碍者禁用","interact":"与拉莫三嗪、阿司匹林、碳青霉烯类合用显著影响血药浓度或增加毒性"},{"name":"喹硫平（精神行为症状）","dose":"12.5–25 mg 睡前起始，按需加至 50–100 mg/d","note":"用于激越、幻觉与睡眠紊乱；痴呆相关精神病有增加死亡风险的黑框警告，需最低有效剂量","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素）升高血药浓度；延长 QT"},{"name":"奥氮平（激越/妄想）","dose":"2.5–5 mg 睡前口服","note":"喹硫平不耐受时的替代；注意体重增加、血糖升高与锥体外系反应","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与吸烟、卡马西平合用降低血药浓度；与苯二氮䓬类合用增加镇静"},{"name":"曲唑酮（睡眠与夜间躁动）","dose":"25–50 mg 睡前口服","note":"改善入睡困难与夜间躁动；注意体位性低血压与次日嗜睡","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 SSRI、曲马多合用增加 5-HT 综合征；与降压药合用增加低血压"},{"name":"舍曲林（抑郁与焦虑）","dose":"25 mg qd 起始，可加至 50–100 mg qd","note":"用于早期抑郁、焦虑与病理性哭泣；起效需 2–4 周，需家属配合观察","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与 NSAIDs 合用增加消化道出血；与曲马多、MAO 抑制剂合用增加 5-HT 综合征"}],"nonDrug":["无特效抗朊蛋白药物：奎纳克林、氟哌啶醇、多西环素等临床试验均未证实有效，不推荐超说明书使用","感染控制：脑组织、CSF 与血液按高危险物质处理；器械尽量一次性使用，可复用器械先浸泡 1 mol/L 氢氧化钠 1 h 或 134 ℃ 高压灭菌 18–60 min","CJD 高风险者不得作为角膜、硬脑膜与器官供体；避免使用尸体来源硬脑膜与垂体来源生长激素","吞咽困难者行鼻饲或经皮胃造瘘（个体化，需家属与伦理共同决策）；加强误吸、压疮与深静脉血栓预防","遗传咨询：gCJD 家系行 PRNP 基因检测与产前诊断咨询；按国家规定上报疾控 CJD 监测网络","早期进行预立医疗照护计划讨论，明确复苏意愿与临终地点，提供姑息与安宁疗护"],"life":["专人照护，防跌倒、走失与误吸；晚期以舒适护理为主","照料者接触血液、CSF、唾液时戴手套，污染物按感染性医疗废物处理","为家属提供心理支持与哀伤辅导，必要时转介社工与安宁疗护团队","避免不必要的侵入性操作与长途转运"]},"prog":"不可逆且致死：sCJD 中位生存 4–6 个月，约 80%–90% 在 1 年内死亡；vCJD 中位生存 13–14 个月；gCJD（如 E200K 突变）病程可略长。死亡原因多为吸入性肺炎、压疮感染与呼吸衰竭。","refs":["中华人民共和国卫生行业标准 WS/T 562—2017《克-雅病诊断》","WHO 传染性海绵状脑病监测标准（1998，2009 修订）","美国 CDC 克雅氏病诊断标准（2018 年修订，纳入 RT-QuIC）"]}]},{"id":"spinal_more","name":"脊髓疾病（补充）","rank":44,"summary":"本类为脊髓疾病补充条目。亚急性联合变性的识别要点是“后索＋侧索＋周围神经”的对称性组合，血清 B12 处于灰区时须依靠甲基丙二酸与同型半胱氨酸，MRI 后索“倒 V 征”有提示价值；治疗关键是尽早足量肌注甲钴胺并终身维持，同时查找并去除病因。","compare":[],"diseases":[{"id":"ne_scd","name":"亚急性联合变性","aka":["Subacute Combined Degeneration","SCD","脊髓亚急性联合变性","维生素 B12 缺乏性脊髓病","亚急性脊髓联合变性"],"rank":1,"basic":{"define":"维生素 B12（钴胺素）缺乏引起的脊髓后索、侧索与周围神经对称性变性，临床以深感觉障碍、感觉性共济失调与痉挛性截瘫为特征，早期补充 B12 可逆，延误则遗留永久性残疾。","risk":["长期严格素食或营养不良","胃大部切除、胃旁路术后或自身免疫性胃炎/恶性贫血（内因子抗体）","长期服用二甲双胍、质子泵抑制剂或 H2 受体拮抗剂","回肠切除、克罗恩病、小肠细菌过度生长","阔节裂头绦虫感染","一氧化二氮（笑气）滥用"],"epi":"一般人群 B12 缺乏约 5%–15%，60 岁以上可达 20%；B12 缺乏者中约 5%–10% 出现 SCD，发病年龄多在 40–60 岁，男女相近。"},"patho":"B12 是甲硫氨酸合成酶与甲基丙二酰辅酶 A 变位酶的辅酶，缺乏使同型半胱氨酸与甲基丙二酸蓄积、髓鞘碱性蛋白甲基化受损，导致脊髓后索与侧索对称性脱髓鞘、轴索变性及后期胶质增生；周围神经与视神经可同时受累，脑白质受累时出现认知与精神症状。","dx":{"criteria":["亚急性或慢性起病（数周–数月）的双足麻木、踩棉花感、行走不稳与下肢僵硬无力","后索体征：振动觉与位置觉减退、Romberg 阳性、感觉性共济失调；侧索体征：痉挛性截瘫、腱反射亢进、Babinski 阳性","合并周围神经病变时腱反射可减弱或消失，构成“后索＋侧索＋周围神经”三联征，易被误认为单纯周围神经病","血清 B12 <150 pmol/L（<200 pg/mL）支持诊断；150–300 pmol/L 为灰区，需查甲基丙二酸（MMA >0.4 μmol/L）与同型半胱氨酸（>15 μmol/L）升高","血常规示大细胞性贫血（MCV >100 fL），但约 30% 患者无贫血；可伴舌炎、食欲减退与体重下降","MRI：T2 轴位脊髓后索对称高信号（“倒 V 征”或“兔耳征”），矢状位见后索条状高信号，颈胸段多见，部分病例增强后强化","排除铜缺乏性脊髓病、HIV 空泡性脊髓病、脊髓痨、颈椎病性脊髓病与视神经脊髓炎谱系疾病"],"workup":["治疗前留取血清 B12、叶酸、甲基丙二酸、同型半胱氨酸，避免先补后查导致结果假性正常","血常规＋MCV、网织红细胞、LDH、间接胆红素（评估溶血与巨幼细胞贫血）","内因子抗体、胃壁细胞抗体、胃镜（萎缩性胃炎与恶性贫血）；必要时评估小肠吸收功能","脊髓 MRI 增强（颈胸段矢状位与轴位 T2），必要时头颅 MRI","铜、锌、极长链脂肪酸、HIV、梅毒血清学、甲状腺功能，鉴别其他脊髓病","消化道评估：回肠病变、小肠细菌过度生长、粪便查阔节裂头绦虫虫卵"],"grading":"按受累部位分脊髓型、脊髓＋周围神经型与脑型（认知与精神症状）；按病程分早期（髓鞘受累、可逆）与晚期（轴索变性、胶质增生）；功能评估用 mRS 或 EDSS。"},"ddx":[{"name":"脊髓炎（ne_myelitis）","point":"本大类仅含 SCD，最易混淆的是同科室“中枢感染与脊髓疾病”大类的脊髓炎：脊髓炎多为急性或亚急性起病，有明确感觉平面与括约肌障碍，CSF 细胞与蛋白升高，MRI 病灶不对称且常超过 3 个椎体；SCD 为对称性后索/侧索受累、无感觉平面、CSF 正常、B12 或 MMA 异常。"},{"name":"脊髓痨（ne_neurosyphilis）","point":"闪电样疼痛、阿罗瞳孔、膝反射消失与感觉性共济失调，血清与 CSF 梅毒学阳性；SCD 有 B12 缺乏证据而梅毒血清学阴性。"},{"name":"颈椎病性脊髓病","point":"手部精细动作障碍与上肢腱反射减弱、下肢痉挛，MRI 见椎间盘突出或椎管狭窄压迫脊髓；SCD 的 MRI 为髓内后索高信号而非外压性改变。"},{"name":"铜缺乏性脊髓病","point":"胃切除或长期过量补锌史，血清铜与铜蓝蛋白降低，表现与 SCD 极相似但 B12 正常，补铜后改善。"},{"name":"HIV 空泡性脊髓病","point":"HIV 阳性、CD4 显著降低，病理类似 SCD 但 B12 与 MMA 正常，抗病毒治疗后部分改善。"},{"name":"视神经脊髓炎谱系疾病（ne_nmosd）","point":"长节段横贯性脊髓炎伴视神经炎，AQP4 抗体阳性，MRI 病灶累及中央灰质且长度 ≥3 个椎体，B12 正常。"},{"name":"多发性硬化（ms）","point":"病灶不对称、时间与空间多发，寡克隆区带阳性，B12 正常，MRI 见脑室旁与近皮层病灶。"},{"name":"成人型肾上腺脑白质营养不良","point":"男性、进行性痉挛性截瘫伴肾上腺功能不全，极长链脂肪酸升高，MRI 见顶枕叶白质对称病变。"}],"tx":{"drug":[{"name":"甲钴胺（肌注诱导期）","dose":"1000 μg 肌注 qd，连用 2 周；随后 1000 μg 肌注每周 1 次，连用 4 周；再改为 1000 μg 每月 1 次维持","note":"首选方案；治疗 48–72 h 后网织红细胞上升，2–3 周神经症状开始改善；无明确可去除病因者需终身维持","renal":"无需调整","hepatic":"遵说明书","interact":"与氯霉素、大剂量维生素 C 同用可能降低疗效；不与同类 B12 制剂重复叠加"},{"name":"甲钴胺（口服）","dose":"500–1500 μg tid 口服（常用 500 μg tid）","note":"用于轻度缺乏、拒绝注射或维持期；吸收依赖内因子，胃切除与恶性贫血者口服效果差，应改肌注","renal":"无需调整","hepatic":"遵说明书","interact":"长期与质子泵抑制剂、H2 受体拮抗剂合用降低吸收"},{"name":"叶酸","dose":"5 mg qd 口服","note":"合并叶酸缺乏时补充，但必须先补 B12；单用叶酸可掩盖贫血而加重神经损害","renal":"遵说明书","hepatic":"遵说明书","interact":"与甲氨蝶呤、苯妥英、甲氧苄啶合用影响疗效或增加毒性"},{"name":"铁剂（合并缺铁时）","dose":"琥珀酸亚铁 100–200 mg tid 口服，或按元素铁 60–100 mg/d","note":"缺铁可加重 B12 缺乏的神经症状，需同时纠正；监测血红蛋白与网织红细胞","renal":"遵说明书","hepatic":"遵说明书","interact":"与钙剂、抗酸药、四环素间隔 2 h；与左旋多巴合用降低其吸收"},{"name":"吡喹酮（阔节裂头绦虫）","dose":"25 mg/kg 单次口服，餐后服用","note":"粪便查见虫卵或节片时驱虫，治疗后 1–3 个月复查粪便；家庭其他成员同时筛查","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"与地塞米松合用降低血药浓度；与氯喹合用增加抽搐风险"},{"name":"氯化钾（治疗初期监测补充）","dose":"遵说明书，按血钾结果口服氯化钾 1–2 g tid，维持血钾 3.5–5.0 mmol/L","note":"恶性贫血者快速纠正 B12 后可出现低钾血症，治疗前 2 周需监测血钾与心电图","renal":"肾功能不全者慎用，防高钾血症","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB 合用增加高钾风险"}],"nonDrug":["病因治疗：评估并尽量停用或替换二甲双胍、质子泵抑制剂；胃切除者终身补充；驱虫；治疗萎缩性胃炎与小肠病变","康复训练：平衡与步态训练、踝足矫形器、辅助器具，重点防跌倒","恶性贫血患者每 1–2 年评估胃镜与贫血指标（胃癌与胃类癌风险增加）","疗效监测：治疗后 1、3、6 个月复查血常规、B12、MMA、同型半胱氨酸，神经功能用 mRS 或 EDSS","避免一氧化二氮麻醉与滥用（可使 B12 失活，诱发急性脊髓病）"],"life":["终身 B12 补充：严格素食者、胃切除与恶性贫血患者不可自行停药","戒酒，均衡摄入肉、蛋、奶等 B12 来源","避免长期自行大剂量补锌（可致铜缺乏性脊髓病）","出现新发肢体麻木、行走不稳或视力下降及时复诊"]},"prog":"早期治疗 2–3 周内症状开始改善，6–12 个月多数可恢复独立行走；病程超过 3–6 个月、后索变性严重者常遗留痉挛性步态与感觉性共济失调；未治疗者可在数年内进展至卧床，并因跌倒、压疮与感染而预后不良。","refs":["英国血液学标准委员会（BCSH）钴胺素与叶酸缺乏诊治指南（2014）","Stabler SP. Vitamin B12 Deficiency. New England Journal of Medicine, 2013","中国营养学会：中国居民膳食营养素参考摄入量（2023 版）"]}]},{"id":"myopathy","name":"肌病","rank":45,"summary":"本类聚焦遗传性肌病。进行性肌营养不良的核心线索是男孩、自幼近端无力、Gowers 征与腓肠肌假性肥大伴 CK 上万，确诊靠基因检测（阴性者肌活检 dystrophin）；治疗以糖皮质激素延缓病程、心肌病与呼吸衰竭管理及遗传咨询为三大支柱。","compare":[],"diseases":[{"id":"ne_muscular_dystrophy","name":"进行性肌营养不良","aka":["Duchenne muscular dystrophy","DMD","Becker muscular dystrophy","BMD","杜氏肌营养不良","假肥大型肌营养不良","进行性假肥大性肌营养不良"],"rank":1,"basic":{"define":"由 Xp21 上 DMD 基因突变致抗肌萎缩蛋白（dystrophin）完全缺失或功能缺陷的 X 连锁隐性遗传性肌病；DMD 为蛋白几乎完全缺失，儿童期起病、进展快，BMD 为部分功能蛋白、起病晚且进展慢。","risk":["男性（X 连锁隐性遗传）","母亲为携带者（约 2/3 母亲为携带者，1/3 为新发突变）","家族史阳性；携带者女性可有轻度肌无力或心肌病","DMD 在活产男婴中发病率 1/3500–1/5000"],"epi":"DMD 在活产男婴中发病率 1/3500–1/5000，BMD 约 1/18000–1/30000；我国为 DMD 高发国家之一，估计患者数万例，多在 5 岁前起病，8–12 岁丧失独立行走能力。"},"patho":"dystrophin 连接细胞骨架与细胞外基质，缺失后肌细胞膜在收缩时机械损伤、钙内流、线粒体功能障碍与慢性炎症，肌纤维反复坏死再生，最终被脂肪与纤维组织替代而出现假性肥大；心肌与呼吸肌同样受累，导致扩张型心肌病与限制性通气障碍。","dx":{"criteria":["男孩 3–5 岁起病，进行性对称性近端无力：走路晚、易跌倒、跑跳落后、上楼梯与蹲起困难","体征：Gowers 征阳性（扶膝撑起）、腓肠肌假性肥大、腰椎前凸、鸭步、翼状肩胛、跟腱挛缩","血清 CK 显著升高：DMD 多在 10000–30000 U/L（正常上限的 50–100 倍以上），2 岁前即可升高；BMD 多为 500–5000 U/L","基因检测：MLPA 或多重 PCR 检出 DMD 基因缺失/重复（占 60%–70%），阴性者行全外显子或全基因测序找点突变","基因检测阴性而高度怀疑者行肌肉活检：dystrophin 免疫组化/免疫印迹示 DMD 表达 <5%，BMD 呈部分表达（30%–80%）","肌电图示肌源性损害（短小多相电位、时限缩短），但诊断价值低于基因与病理","心肌受累：心电图见 V1 高 R 波、深 Q 波与窦性心动过速，超声心动图或心脏 MRI 评估 LVEF 与心肌纤维化，10 岁起每年检查","呼吸受累：FVC <50% 预测值提示夜间通气不足风险，需查血气、夜间血氧与二氧化碳"],"workup":["血清 CK（显著升高）、肝功能（CK 干扰 AST/ALT 判读）、甲状腺功能","DMD 基因 MLPA＋测序；母亲及姐妹携带者检测（剂量分析＋测序）","肌肉活检（基因阴性时）：dystrophin 免疫组化、免疫印迹与组织学","心电图、超声心动图、心脏 MRI（≥6–7 岁首选，敏感度高于超声）","肺功能（FVC、MIP/MEP、咳嗽峰流速）、夜间血氧与经皮二氧化碳监测","脊柱 X 线（Cobb 角）、骨密度（激素治疗者）、眼科检查（地夫可特相关白内障）、认知与行为评估（约 1/3 有学习或行为问题）及生长发育/青春期评估"],"grading":"按蛋白表达与自然史分型：DMD（dystrophin <5%，12 岁前丧失行走）、中间型（5%–20%，行走能力维持至 12–16 岁）、BMD（>20%，16 岁后仍可行走）；按功能分为症状前期、早期可行走期、晚期可行走期与无行走能力期（轮椅依赖、呼吸/心脏受累）。"},"ddx":[{"name":"皮肌炎/多发性肌炎（rh_dm）","point":"本大类仅含进行性肌营养不良，最易混淆的是风湿免疫科的炎性肌病（rh_dm）：炎性肌病多有皮疹（Gottron 征、向阳疹）、肌痛、自身抗体（抗 Jo-1、Mi-2、MDA5）阳性与肌活检炎症证据，激素与免疫抑制治疗有效；DMD 为男孩自幼起病、CK 上万、基因检测可确诊，激素仅延缓进展。"},{"name":"脊髓性肌萎缩（SMA）","point":"婴儿或儿童近端无力、肌束颤动，CK 正常或轻度升高，SMN1 基因缺失，肌电图示广泛神经源性损害而非肌源性。"},{"name":"运动神经元病（ne_als）","point":"成年起病，上下运动神经元体征并存，肌束颤动与延髓麻痹突出，CK 轻中度升高，肌电图示广泛神经源性损害。"},{"name":"代谢性肌病（糖原贮积病、Pompe 病、脂质沉积性肌病）","point":"运动不耐受、肌痛、肌红蛋白尿，CK 波动性升高，肌肉活检酶学或基因确诊，多为常染色体隐性遗传。"},{"name":"先天性肌病（杆状体肌病、中央轴空病）","point":"生后即肌张力低下、运动发育迟缓，CK 正常或轻度升高，肌活检见特征性结构异常，基因检测可分型。"},{"name":"内分泌性肌病（甲状腺功能减退、库欣综合征）","point":"有相应内分泌表现，CK 轻中度升高，纠正内分泌异常后肌力与 CK 恢复。"},{"name":"药物性肌病（糖皮质激素、他汀、氯喹）","point":"有明确用药史，停药或减量后 CK 与肌力改善，无自幼起病与家族史。"}],"tx":{"drug":[{"name":"醋酸泼尼松","dose":"0.75 mg/kg/d 口服（最大 30 mg/d）；不能耐受时改周末方案（周六、周日各 5 mg/kg/d）或间歇方案（服 10 d 停 10 d）；丧失行走能力后减至 0.3–0.6 mg/kg/d","note":"国内唯一普遍可及、可延缓肌力下降的药物；进入平台期或倒退期（多在 4–5 岁）开始，<2 岁运动发育正常者不推荐","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血；与活疫苗同用可致疫苗株感染；降低生长激素疗效"},{"name":"地夫可特","dose":"0.9 mg/kg/d 口服（最大 36 mg/d）；不耐受时 0.45 mg/kg/d 或间歇方案（0.6 mg/kg/d，每月前 20 d）","note":"体重增加少于泼尼松，适合有肥胖倾向者，但白内障风险更高，需每年眼科检查；适用于 ≥5 岁","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与 CYP3A4 抑制剂（酮康唑、克拉霉素）合用升高血药浓度"},{"name":"伐莫洛龙","dose":"6 mg/kg/d 口服（最大 300 mg/d）；轻中度肝损伤 2 mg/kg/d（最大 100 mg/d）","note":"对身高与骨代谢影响较小，适用于 ≥2 岁；国内可及性有限","renal":"遵说明书","hepatic":"轻中度肝损伤减量，重度肝损伤不推荐","interact":"与 CYP3A4 强抑制剂合用需减量"},{"name":"依普利酮","dose":"25 mg qd 口服","note":"用于合并心肌病而 LVEF 尚正常者，可延缓 LVEF 下降；监测血钾与肾功能","renal":"CrCl <50 慎用，CrCl <30 禁用","hepatic":"重度肝功能不全慎用","interact":"与 ACEI/ARB、保钾利尿剂合用增加高钾血症"},{"name":"赖诺普利（DMD 心肌病）","dose":"2.5–5 mg qd 起始，按血压与耐受逐渐加量；LVEF <55% 时启动","note":"DMD 心肌病的标准心衰治疗基础用药；监测血压、血钾与肌酐","renal":"CrCl <30 减量起始","hepatic":"遵说明书","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低疗效并增加肾损伤"},{"name":"碳酸钙＋维生素 D","dose":"维生素 D 800–1000 IU/d＋元素钙 500–1000 mg/d 口服","note":"激素治疗期间的骨保护；每年查 25-羟维生素 D、血钙与骨密度","renal":"高钙血症或肾结石者慎用","hepatic":"遵说明书","interact":"与噻嗪类利尿剂合用增加高钙；与铁剂、四环素间隔 2 h"},{"name":"唑来膦酸","dose":"5 mg 静滴，每年 1 次（按骨密度与骨折风险调整）","note":"用于激素相关骨质疏松或椎体压缩骨折；用药前纠正低钙与维生素 D 缺乏","renal":"CrCl <35 禁用","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加低钙与肾毒性；与 NSAIDs 合用增加肾损伤"}],"nonDrug":["康复：每日被动与主动拉伸（跟腱、髂腰肌、腘绳肌）、夜间踝足矫形器、维持站立与行走，避免过度离心运动","呼吸管理：FVC <50% 预测值或夜间低通气时启动无创通气（BiPAP）；每年流感、肺炎链球菌与 RSV 疫苗；咳嗽峰流速下降者用机械性吸-呼气辅助","心脏管理：每年心电图＋超声或心脏 MRI；LVEF <55% 启动 ACEI/ARB，必要时加依普利酮与利尿剂；终末期评估心脏移植","骨科：Cobb 角 ≥20° 转诊，≥40°–50° 且进展者行脊柱矫形手术；跟腱挛缩影响行走者行松解术","营养与胃肠：吞咽困难或体重下降者行胃造瘘；激素相关肥胖者控制总热量并监测体重","遗传咨询：母亲与姐妹携带者检测，提供产前诊断（绒毛或羊水基因检测）与胚胎植入前遗传学检测"],"life":["避免全身麻醉与琥珀胆碱（横纹肌溶解与高钾风险），必须手术时选择全静脉麻醉并加强监测","适度低冲击运动（游泳、骑车），避免剧烈离心运动与过度疲劳","学校与心理支持，关注学习困难与社交参与","每 3–6 个月多学科随访（神经科、心脏科、呼吸科、康复科、骨科）"]},"prog":"DMD 自然病程为 8–12 岁丧失独立行走，20–30 岁多死于呼吸衰竭或心力衰竭；规范激素治疗联合无创通气与心衰管理可将生存期延长至 30 岁以上；BMD 进展慢，多数可行走至成年，但约 30%–40% 在 30–40 岁出现心肌病。","refs":["进行性假肥大性肌营养不良的糖皮质激素治疗循证指南（2025 版）","Duchenne 肌营养不良诊断与管理国际共识（Lancet Neurology，2018，三部分）","中国罕见病诊疗指南（2019 年版，国家卫生健康委员会）"]}]}]},"nsurg":{"categories":[{"id":"ns_trauma","name":"颅脑创伤","rank":1,"summary":"创伤性脑损伤以院前气道/循环稳定为前提，急诊 CT 明确血肿与占位，按「有占位先减压、无占位控颅压」的原则分流；硬膜外血肿强调时间窗内开颅，慢性硬膜下血肿首选钻孔引流，重型颅脑损伤以 ICP/CPP 目标化管理为核心。","compare":[{"diseaseId":"ns_edh","dx":"明确外伤史 + 伤后短暂昏迷—中间清醒期，CT 示颅骨内板下方双凸透镜形高密度影、跨颅缝但不跨硬脑膜窦","key":"双凸透镜形、可跨颅缝不跨骨缝缝合线，常伴同侧颅骨骨折，病情可在数小时内急剧恶化"},{"diseaseId":"ns_sdh","dx":"多为老年人或轻微外伤/跌倒后数周出现进行性头痛、认知下降、步态不稳，CT 示新月形低密度或混杂密度影、可跨越颅缝","key":"新月形、跨越颅缝、中线移位与血肿厚度不成比例，慢性者血肿呈等/低密度易漏诊"},{"diseaseId":"ns_tbi","dx":"伤后 GCS ≤8 分持续 >6 h（或初始 GCS ≤8）且非镇静所致，CT 可正常或见弥漫轴索损伤、脑肿胀","key":"以 GCS 与结构损伤分型，核心矛盾是颅内压升高（脑疝风险），治疗围绕 ICP <22 mmHg、CPP 60–70 mmHg"}],"diseases":[{"id":"ns_edh","name":"急性硬膜外血肿","aka":["急性硬脑膜外血肿","Epidural Hematoma","EDH","AEDH"],"rank":1,"basic":{"define":"外伤导致颅骨骨折撕裂脑膜中动脉或其分支（少数为静脉窦、板障静脉），血液积聚于颅骨内板与硬脑膜之间形成的占位性血肿，多位于颞顶部，病程进展快。","risk":["青少年与青年（20–40 岁）多见","颞部颅骨骨折（脑膜中动脉走行处）","交通事故、高处坠落、头部直接撞击","长期酗酒、服用抗血小板/抗凝药者出血风险更高"],"epi":"占全部颅脑创伤的 1%–3%，但占致死性颅脑创伤的 5%–15%；约 70%–80% 合并颅骨骨折，典型「中间清醒期」仅见于约 1/3 患者。"},"patho":"颞骨鳞部骨折撕裂脑膜中动脉后，动脉压驱动的快速出血在硬脑膜外形成局部高压力血肿，逐渐将硬脑膜自颅骨剥离并压迫脑实质。因血肿受颅缝处硬脑膜附着限制，呈双凸透镜形。颞部血肿早期即可压迫颞叶及钩回引起小脑幕切迹疝，故病情恶化常以分钟—小时计。","dx":{"criteria":["有明确头部外伤史，伴头痛、呕吐、意识障碍进行性加重或清醒—昏迷双向过程","瞳孔改变：同侧瞳孔散大、对光反射迟钝或消失（小脑幕切迹疝征象），伴对侧偏瘫","头颅 CT 平扫：颅骨内板下双凸透镜形（biconvex）均匀高密度影，多数伴局部颅骨线状骨折，中线移位 >5 mm 提示占位效应显著","卒中样起病者需与急性缺血性脑卒中鉴别，避免在未排除血肿前溶栓"],"workup":["首诊评估 ABC、GCS、双侧瞳孔，颈部制动","头颅 CT 平扫为金标准，需在伤后 30–60 min 内完成；骨窗观察骨折线","血常规、凝血功能、血型、生化；服抗凝药者查 INR、必要时查抗 Xa 活性","CT 血管造影（CTA）用于疑合并脑膜中动脉假性动脉瘤、颅底大血管损伤者","老年或疑颈椎损伤者加做颈椎 CT；意识障碍者行颈托保护直至排除颈椎损伤","随访 CT 于伤后 6–12 h 或神经状态恶化时复查，观察血肿扩大与迟发血肿"],"grading":"按 CT 表现分型：Ⅰ型（≤30 cm³，可保守）；Ⅱ型（>30 cm³ 但中线移位 <5 mm，可观察或钻孔）；Ⅲ型（>30 cm³，伴中线移位 >5 mm，需开颅）。按发病时间：急性（<3 d）、亚急性（3 d–3 周）、慢性（>3 周）。"},"ddx":[{"name":"慢性硬膜下血肿（ns_sdh）","point":"与本类 ns_sdh 的鉴别点：EDH 为外伤后数小时内起病、CT 呈双凸透镜形高密度、多不跨颅缝；CSDH 多为数周—数月病程、CT 呈新月形低/等密度、跨越颅缝、老年人多见。"},{"name":"重型颅脑损伤（ns_tbi）","point":"与本类 ns_tbi 的鉴别点：EDH 以单侧局灶占位血肿为特征、有明确血肿可切除；重型 TBI 的占位可仅为脑肿胀/弥漫损伤，GCS ≤8 且以 ICP 管理为主，常无局灶血肿。"},{"name":"急性硬膜下血肿","point":"常为对冲伤伴脑挫裂伤，CT 呈新月形高密度且沿脑表面广泛分布，病情进展更快、预后更差；EDH 以动脉性出血为主，手术清除后预后较好。"},{"name":"颅骨凹陷性骨折","point":"CT 骨窗直接显示骨折片内陷深度 >1 cm，需整复；血肿量可很小，局灶神经缺损与凹陷位置对应。"},{"name":"急性缺血性脑卒中","point":"无外伤史，起病突然、CT 早期多无明显高密度占位，可伴血管高密度征；EDH 有明显外伤与双凸高密度影，禁止误行溶栓。"}],"tx":{"drug":[{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注，15–30 min 内滴完；维持治疗 0.25–0.5 g/kg q4–6h，仅在血肿清除术前降低颅压争取时间","note":"建议监测渗透压间隙与尿量，目标血浆渗透压 ≤320 mOsm/L；不作为替代手术的手段，有占位者优先手术","renal":"肾功能不全、少尿者慎用或减量，必要时改用高渗盐水","hepatic":"遵说明书","interact":"与肾毒性药物（氨基糖苷类、顺铂）合用增加肾损伤风险"},{"name":"高渗盐水（3%–23.4%）","dose":"3% 氯化钠 2–5 mL/kg 静脉输注，或 23.4% 氯化钠 30 mL 经中心静脉单次推注（需中心静脉通路）","note":"用于低血压不宜使用甘露醇者、或甘露醇无效时；监测血钠（目标 145–155 mmol/L）与神经状态","renal":"","hepatic":"遵说明书","interact":"避免与经同一通路给予的阳离子药物混合"},{"name":"氨甲环酸","dose":"伤后 3 h 内负荷 1 g 静脉缓慢推注（>10 min），随后 1 g 静滴 8 h","note":"适用于伤后 3 h 内的颅脑创伤伴血肿或高危者（CRASH-3 证据），减少血肿进展与死亡，迟于 3 h 使用无获益","renal":"重度肾功能不全减量","hepatic":"遵说明书","interact":"与凝血酶原复合物、其他促凝药合用需评估血栓风险"},{"name":"维生素 K1","dose":"10 mg 静脉缓慢推注（>30 min），q12h 可重复，调整维持量至 INR <1.5","note":"口服华法林后发生血肿者立即使用，联合凝血酶原复合物（PCC）更快纠正","renal":"","hepatic":"严重肝病者需持续监测 INR","interact":"与头孢类等抑制维生素 K 合成的药物合用降低疗效"},{"name":"凝血酶原复合物（PCC，含 4 因子）","dose":"25–50 IU/kg 静脉滴注，按体重与 INR 调整，目标 INR ≤1.4","note":"用于口服抗凝药相关出血的紧急逆转，须与维生素 K 合用","renal":"遵说明书","hepatic":"","interact":"与抗凝药同用相互拮抗"},{"name":"苯妥英钠（或左乙拉西坦）","dose":"苯妥英钠 15–20 mg/kg 负荷（≤50 mg/min），随后 100 mg q8h；左乙拉西坦 500–1000 mg q12h 负荷后维持","note":"仅用于伤后 7 d 内早期创伤后癫痫预防，不推荐长期预防","renal":"左乙拉西坦按 CrCl 调整；苯妥英钠需监测血药浓度","hepatic":"苯妥英钠肝代谢，严重肝病减量","interact":"苯妥英钠诱导 CYP3A4，加速皮质类固醇、抗凝药代谢"}],"nonDrug":["存在下列情况立即急诊开颅血肿清除：血肿量 >30 cm³；任何体积伴 GCS ≤8；中线移位 >5 mm；瞳孔不等大伴意识下降；血肿进行性增大","GCS >8 且血肿 ≤30 cm³、厚度 <15 mm、中线移位 <5 mm 者可在 ICU 监测下保守，但需 24 h 内可随时开颅","小血肿伴神经功能恶化、但不具备急诊开颅条件时，可行钻孔引流或神经导航下经颅穿刺置管作为过渡","手术要点：标准颞部骨窗（考虑大骨瓣或去骨瓣减压），清除血肿后悬吊硬脑膜，必要时剪开硬膜检查硬膜下腔并清除合并的脑挫裂伤","术后复查 CT，留置硬膜下/硬膜外引流 24–48 h，引流量与凝血状态同步监测","颅骨骨折凹陷 >1 cm 或开放污染者同期处理颅骨整复/清创"],"life":["伤后 24–48 h 内严密监测意识、瞳孔与 GCS（每小时记录），保持头高位 30°、头居中避免颈静脉受压","早期启动抗癫痫治疗 7 d，发作停止后按需逐渐停药","出院后 3 个月内避免剧烈运动、用力排便与头部再次撞击","出院 4–6 周复查头颅 CT；口服抗凝药患者需神经外科与心内科共同评估恢复抗凝时机"]},"prog":"及时手术清除者死亡率约 5%–10%，多数可完全恢复认知功能；瞳孔已散大固定者死亡率可升至 50% 以上，意识丧失 >2 h 者预后明显变差。迟发性血肿（约 2%–4%）需术后持续警惕。","refs":["《中国颅脑创伤外科治疗指南》（中华医学会神经外科学分会，2017）","《创伤性脑损伤急性期管理指南》（美国脑创伤基金会 BTF 第 4 版，2016）","《颅脑创伤救治专家共识》（中国医师协会神经外科医师分会，2020）"]},{"id":"ns_sdh","name":"慢性硬膜下血肿","aka":["慢性硬脑膜下血肿","CSDH","Chronic Subdural Hematoma"],"rank":2,"basic":{"define":"头部轻微外伤后 3 周以上，硬脑膜与蛛网膜之间形成的由外膜、桥接静脉出血及血肿腔构成的进行性扩大的液体血肿，多见于老年脑萎缩人群。","risk":["年龄 >65 岁，脑萎缩使桥静脉受牵拉","抗凝药（华法林、NOACs）或抗血小板药使用","酗酒、癫痫、反复跌倒","颅内低压、分流术后、透析患者","男性多于女性"],"epi":"年发病率约 1–5/10 万，>70 岁人群可达 12–58/10 万；随着老龄化和抗栓药物普及，发病率持续上升，复发率约 10%–20%。"},"patho":"轻微外伤撕裂跨越硬膜下的桥接静脉形成薄层血肿，局部炎症使嗜酸性粒细胞浸润、纤维蛋白降解产物（如 D-二聚体、纤溶酶）升高，形成通透性高的外膜并持续渗出，同时新生毛细血管反复出血，血肿渗透压升高吸水和反复出血形成正反馈性扩大，最终压迫脑实质出现症状。内板吸收与脑组织复位速度不匹配决定血肿能否自行消退。","dx":{"criteria":["多为 60–80 岁老年人，伤后数周至数月出现症状，外伤可轻微甚至被遗忘","典型表现：进行性头痛、肢体无力或步态不稳、认知减退与反应迟钝、尿失禁；轴内或轴外体征依赖血肿部位","头颅 CT：沿颅骨内板新月形低密度影（部分混杂/等密度，等密度者易漏诊且需增强或 MRI 辨认），可跨越颅缝、多双侧","MRI（T1/T2 及 FLAR、DWI）用于等密度血肿、需与慢性缺血或肿瘤鉴别时；硬膜下血肿多无弥散受限","中线移位与血肿最大厚度及脑萎缩程度相关，血肿最大厚度 >10 mm 或中线移位 >5 mm 通常有手术指征"],"workup":["头颅 CT 平扫（骨窗与脑窗）为首选，双侧者注意中线移位是否与血肿量匹配","MRI 用于等密度血肿与脑梗死、脑膜转移、硬膜下水瘤的不典型病例","凝血功能、血常规、肝肾功能；服用 NOACs 者查抗 Xa/达比加群浓度与肾清除率","术前评估：出血风险（CHA2DS2-VASc/HAS-BLED）、神经功能评分（mRS、握力与步态）、心肺功能","术后 24–48 h 复查 CT，第 3–4 周随访 CT 判断复发"],"grading":"按 CT 密度分为高密度、等密度、低密度与混杂密度（混杂密度复发力更高）；按 Markwalder 分级：0 级 神经功能正常；Ⅰ级 轻度（头痛，无神经缺损）；Ⅱ级 中等（嗜睡、局灶体征）；Ⅲ级 严重（昏睡、偏瘫、共济障碍）；Ⅳ级 昏迷。"},"ddx":[{"name":"急性硬膜外血肿（ns_edh）","point":"与本类 ns_edh 的鉴别点：CSDH 病程以周—月计、CT 为新月形低/混杂密度、跨越颅缝；EDH 为小时—天内快速恶化、双凸透镜形高密度、有颅骨骨折。"},{"name":"重型颅脑损伤（ns_tbi）","point":"与本类 ns_tbi 的鉴别点：CSDH 多无明确近期重度外伤、GCS 多为轻度下降、可通过钻孔引流治愈；重型 TBI 有重度外伤、GCS ≤8、需 ICU 与 ICP 管理。"},{"name":"蛛网膜下腔出血","point":"突发剧烈头痛（雷击样）伴颈强、CT 呈脑沟裂高密度；CSDH 头痛渐进、CT 为脑表面新月形改变。"},{"name":"正常压力脑积水（NPH）","point":"以步态障碍、认知障碍、尿失禁三联征为主，CT 见脑室扩大而不伴血肿；部分 CSDH 可合并交通性脑积水，需复查影像与放液试验鉴别。"},{"name":"蛛网膜囊肿/硬膜下水瘤","point":"CT 示脑脊液密度、无占位效应演变、多无外伤史；需 MRI 鉴别并动态随访。"},{"name":"缺血性脑卒中","point":"偏瘫等局灶体征可与 CSDH 相似，但卒中起病突发、CTA/MRI 显示血管分布区梗死；在抗栓/溶栓之前应常规行头颅 CT 排除血肿。"}],"tx":{"drug":[{"name":"地塞米松","dose":"4–8 mg q12h 短期使用（3–5 d），症状缓解后减量，总疗程不宜超过 2 周","note":"仅用于轻症、无移位者或围手术期短期减轻脑水肿；长期使用增加感染与高血糖，有随机试验显示未能改善功能预后，不作为常规","renal":"遵说明书","hepatic":"严重肝功能不全者作用减弱，需监测","interact":"与抗凝药、降糖药合用需调整剂量；NSAIDs 合用增加消化道出血"},{"name":"阿托伐他汀","dose":"20 mg qn 口服，疗程 4–8 周（部分研究用 3 个月）","note":"国内小样本研究提示可促进血肿吸收、降低复发，用于保守治疗或术后辅助；疗效仍需更多证据","renal":"无需调整","hepatic":"活动性肝病禁用，ALT/AST >3 倍上限停药","interact":"与克拉霉素、伊曲康唑等 CYP3A4 抑制剂合用增加肌病风险"},{"name":"氨甲环酸","dose":"500 mg q8h 口服 7–21 d（部分方案为 1 g q8h 静滴 3 d 后转口服）","note":"用于减少血肿扩大与复发，适用于保守治疗及术后高危复发者，需评估血栓风险","renal":"CrCl <30 时减量或延长给药间隔","hepatic":"遵说明书","interact":"与其他促凝/抗纤溶药合用需监测血栓"},{"name":"凝血酶原复合物（PCC）","dose":"25–50 IU/kg 静脉滴注，或按说明书，目标 INR ≤1.4","note":"用于口服华法林相关 CSDH 的紧急逆转，配合维生素 K1 10 mg 静注","renal":"遵说明书","hepatic":"","interact":"与抗凝药作用相互拮抗"},{"name":"左乙拉西坦","dose":"500 mg q12h 口服，必要时 1000 mg 负荷后维持；疗程视是否出现癫痫而定","note":"有癫痫发作史或术后高风险者使用，单纯预防性用药尚无统一结论","renal":"CrCl <50 时减量，透析者补充剂量","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用可加重嗜睡"}],"nonDrug":["钻孔引流术（Burr-hole drainage）为首选：局部/全身麻醉下于血肿最厚处钻孔，置管或冲洗后留置引流 24–48 h；单孔与双孔引流疗效相近","血肿厚度 >10 mm、中线移位 >5 mm 或出现神经功能缺损者具备手术指征；轻症（Markwalder Ⅰ–Ⅱ级）可先保守并动态复查","手术前后停用替格瑞洛/氯吡格雷（一般 5–7 d）或华法林，桥接方案由神经外科与心内科共同决定","大量血肿或分隔型血肿可行内镜下清除/开颅清除；脑萎缩严重或反复复发者考虑脑膜中动脉栓塞（MMA embolization）","术后保持头低位（平卧或床头 <10°，约 24 h）、充分补液以促进脑组织复张；引流袋位置略高于耳廓水平，避免过度引流","复查 CT 于术后 24–48 h 与 2 周–3 个月各一次；血肿消退常需 1–3 个月"],"life":["出院后 1–3 个月内避免跌倒、弯腰提重物与剧烈运动，居家防滑并评估跌倒风险","抗栓药恢复时机个体化：一般在术后 2–4 周、经影像确认无复发后由专科共同决定；明确动脉血栓高危者可提前","老年人营养与康复训练（步态、认知）对功能恢复同样重要","告知家属再次出现头痛、反应变差、肢体无力时立即复诊复查 CT"]},"prog":"手术引流后 70%–90% 患者症状明显改善，死亡率约 3%–5%；复发率 10%–20%，老年、双侧、混合密度与继续抗凝者为高危。合并症多、术前 GCS 低者功能预后较差。","refs":["《慢性硬膜下血肿诊断与治疗中国专家共识》（中华医学会神经外科学分会，2021）","《英国神经外科慢性硬膜下血肿管理指南》（2020）","《中国颅脑创伤外科治疗指南》（2017）"]},{"id":"ns_tbi","name":"重型颅脑损伤","aka":["重型创伤性脑损伤","Severe TBI","sTBI","重度颅脑损伤"],"rank":3,"basic":{"define":"颅脑创伤后昏迷评分为 GCS 3–8 分（非镇静状态）持续超过 6 h 的严重脑损伤，伴或不伴局灶占位，治疗核心为预防与处理颅内高压及继发性脑损伤。","risk":["交通事故、高处坠落、暴力打击等高能量损伤","低血压（收缩压 <90 mmHg）与低氧血症（SpO₂ <90%）","服用抗凝/抗血小板药","年龄 >60 岁或多发复合伤","酗酒、既往颅脑手术史"],"epi":"重型 TBI 占颅脑创伤的 10%–15%，但占颅脑创伤死亡的 60% 以上；我国颅脑创伤年发病约 100–200/10 万，创伤是 45 岁以下人群首位死因，重型 TBI 病死率约 25%–35%。"},"patho":"原发性损伤（皮质挫裂、弥漫性轴索损伤、血管损伤）在伤后即刻发生；随后细胞毒性/血管源性脑水肿、炎症级联反应、兴奋性氨基酸毒性、氧化应激与血脑屏障破坏导致继发性损伤，颅内压升高引起脑灌注压下降与脑疝。低血压与低氧血症是独立恶化因素，因此场外气管插管、维持收缩压 ≥90 mmHg 与目标化 ICP 管理同等重要。","dx":{"criteria":["GCS ≤8 分（睁眼 1–4、语言 1–5、运动 1–6）为重型；9–12 分中型，13–15 分轻型","评估前须纠正镇静、低血糖、低氧血症、低灌注等可逆因素，避免误判为重型","瞳孔散大或不等大、去脑强直、GCS 进行性下降提示脑疝或占位效应","头颅 CT：按 Marshall 分型评价，存在弥漫性肿胀伴基底池消失、中线移位 >5 mm 或局灶性占位（>25 cm³）为高危","腰穿禁用于疑有颅内高压者；任何情况下不因颅内损伤而延误全身复苏"],"workup":["院前：气道/颈椎保护、维持 SpO₂ ≥94%、收缩压 ≥100 mmHg（成人）","首诊 15 min 内：GCS、瞳孔、生命体征；1 h 内完成头颅 CT，必要时加做颈椎、胸腹 CT 排查合并伤","动脉血气、乳酸、血糖、电解质、凝血功能与血型","ICP 监测指征：GCS 3–8 且 CT 异常；或 CT 正常但存在年龄 >40 岁、血压收缩压 <90 mmHg、单侧/双侧去大脑强直中 ≥2 项（「CT 正常重型 TBI 三联证」）","颈静脉球氧饱和度（SjvO₂）/脑组织氧分压（PbtO₂）用于严重低灌注/氧合下降者","连续脑电监测用于持续昏迷、怀疑非惊厥性发作或治疗性镇静者"],"grading":"GCS 分型（重型 3–8、中型 9–12、轻型 13–15）；CT 分型采用 Marshall 分级 Ⅰ–Ⅵ级；预后预测可用 IMPACT 或 CRASH 模型（结合年龄、GCS、瞳孔反应、CT 特征）。"},"ddx":[{"name":"急性硬膜外血肿（ns_edh）","point":"与本类 ns_edh 的鉴别点：EDH 为 CT 上明确可清除的单侧双凸透镜形血肿，切除后常可获得较好恢复；重型 TBI 的 CT 以脑肿胀/弥漫轴索损伤为主或伴小血肿，GCS ≤8 需长期 ICU 处理。"},{"name":"慢性硬膜下血肿（ns_sdh）","point":"与本类 ns_sdh 的鉴别点：重型 TBI 起病急骤、有明确创伤、GCS ≤8；CSDH 多为老年人周—月内隐匿进展、GCS 多为轻中度下降、治疗以钻孔引流为主。"},{"name":"中毒/代谢性脑病（酒精、镇静催眠药）","point":"GCS 下降但 CT 无相关占位、有明确药物/酒精史与血药浓度升高；阿片类可用纳洛酮试验性拮抗，须在排除颅内病变后才可归因。"},{"name":"低血糖/低氧性昏迷","point":"指尖血糖 <3.9 mmol/L 或 SpO₂ 显著下降，纠正后迅速清醒；GCS 改善明显则支持代谢性病因。"},{"name":"昏迷性癫痫发作/非惊厥性癫痫持续状态","point":"脑电监测见持续痫样放电，镇静/抗癫痫后好转；应与创伤性昏迷鉴别并同步清除发作。"}],"tx":{"drug":[{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注（15–30 min 内），维持 0.25–0.5 g/kg q4–6h；仅在存在 ICP 升高征象且全身情况允许时使用","note":"须在维持血压、容量的前提下使用；重复给药监测血浆渗透压（≤320 mOsm/L）与渗透压间隙（<20 mOsm/kg），甘露醇不作为单纯预防性治疗","renal":"肾功能不全或容量不足者慎用，必要时使用高渗盐水替代","hepatic":"","interact":"与肾毒性药物合用增加急性肾损伤风险"},{"name":"高渗盐水（3%–23.4%）","dose":"3% 氯化钠 2–5 mL/kg 静脉输注（30 min 内），或 23.4% 氯化钠 30 mL 中心静脉推注用于脑疝危象","note":"血钠目标 145–155 mmol/L；低血压、低容量者优于甘露醇；监测血钠与氯，避免快速纠正","renal":"心肾功能不全者注意容量负荷","hepatic":"遵说明书","interact":"避免与经同一通路给予的阳离子药物混合"},{"name":"丙泊酚","dose":"负荷 1–2 mg/kg，维持 20–60 μg/kg/min（约 1–4 mg/kg/h），滴定至维持 ICP <22 mmHg 与轻度镇静","note":"用于难治性颅高压的深度镇静/降颅压；长时间大剂量可致丙泊酚输注综合征（酸中毒、横纹肌溶解、心律失常），需监测甘油三酯、乳酸与 CK","renal":"无需调整","hepatic":"重度肝功能不全减量","interact":"与其他镇静药、阿片类合用加重呼吸循环抑制"},{"name":"芬太尼","dose":"负荷 0.5–1 μg/kg，维持 0.5–2 μg/kg/h 静脉泵入","note":"镇痛优先，控制疼痛与躁动以减少 ICP 波动；需与镇静联合","renal":"无需调整","hepatic":"严重肝病清除减慢，减量","interact":"与苯二氮䓬类合用明显增加呼吸抑制"},{"name":"去甲肾上腺素","dose":"0.05–0.5 μg/kg/min 中心静脉泵入，滴定至 CPP ≥60 mmHg（MAP 目标 80–90 mmHg）","note":"维持脑灌注压的关键；CPP 目标 60–70 mmHg，高于 70 mmHg 可能增加 ARDS 与肺损伤风险","renal":"","hepatic":"","interact":"与单胺氧化酶抑制剂、三环类抗抑郁药合用致血压剧升"},{"name":"氨甲环酸","dose":"伤后 3 h 内负荷 1 g 静注（>10 min），随后 1 g 静滴 8 h","note":"CRASH-3 研究支持用于轻中度颅脑创伤伴血肿者，减少血肿扩大与死亡；伤后 3 h 内为获益窗口","renal":"重度肾功能不全减量","hepatic":"","interact":"与其他促凝药合用需评估血栓风险"},{"name":"左乙拉西坦","dose":"负荷 1000 mg（缓慢静滴），随后 500–1000 mg q12h，疗程 7 d","note":"仅用于伤后 7 d 内早期惊厥预防；不建议超过 7 d 常规预防癫痫","renal":"CrCl <50 减量，透析者补充","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"}],"nonDrug":["院前与急诊：气管插管维持 SpO₂ ≥94%，维持收缩压 ≥100 mmHg（≥50 岁 110 mmHg），尽快完成 CT","颅内压管理阶梯：① 头高位 30°、颈静脉回流通畅、体温 36–37 °C、血糖 6–10 mmol/L、镇痛镇静；② 有占位者行血肿清除/去骨瓣减压；③ 脑脊液引流（EVD）目标 ICP <22 mmHg；④ 渗透治疗；⑤ 难治性颅高压：短程过度通气（PaCO₂ 30–35 mmHg，仅作过渡）、深度镇静、巴比妥昏迷、去骨瓣减压","ICP 监测指征见「检查」项；CPP = MAP − ICP，目标 60–70 mmHg","去骨瓣减压指征：弥漫性脑肿胀伴难治性 ICP 升高、伴或不伴占位病变的中间型者，应在伤后 24–48 h 内评估","伤后 72 h 内开始肠内营养，优先经鼻胃管；复合伤优先处理出血","预防深静脉血栓：伤后 24 h 内复查 CT 稳定后开始低分子肝素；必要时间歇性充气加压装置","早期康复：伤后 1 周内由康复科介入，处理痉挛、吞咽与肺部感染"],"life":["ICU 持续监测 ICP/CPP、脑电、体温与内环境；避免低氧、低血压、高热、高血糖与低钠血症","病情稳定后逐步撤离镇静与呼吸机，评估能否拔管与气道保护反射","出院后长期随访：认知、情绪与行为评估，预防二次损伤，戒酒并防止跌倒","家庭与照护者宣教：癫痫发作急救、压疮与误吸预防、康复训练计划"]},"prog":"重型 TBI 住院病死率约 25%–35%，幸存者中 50%–60% 遗留不同程度认知、运动或行为障碍；年龄 >65 岁、双侧瞳孔散大固定、合并低血压/低氧者预后极差。伤后 6–12 个月是神经功能恢复的主要窗口。","refs":["《颅脑创伤救治专家共识》（中国医师协会神经外科医师分会，2020）","《严重创伤性颅脑损伤管理指南》第 4 版（美国脑创伤基金会 BTF，2016）","《中国颅脑创伤外科治疗指南》（中华医学会神经外科学分会，2017）","CRASH-3 随机对照试验（Lancet，2019）"]}]},{"id":"ns_vasc_tumor","name":"脑血管与肿瘤","rank":2,"summary":"颅内动脉瘤破裂是自发性 SAH 的首要原因，以「早夹闭/栓塞 + 尼莫地平防治脑血管痉挛」为核心；脑胶质瘤遵循最大安全范围切除 + 放化疗（Stupp 方案）的多学科路径；脑膜瘤以 WHO 分级指导手术切除范围与术后辅助放疗。","compare":[{"diseaseId":"ns_aneurysm","dx":"突发剧烈头痛（雷击样）、颈强直、CT 示基底池/外侧裂高密度，CTA 或 DSA 证实动脉瘤","key":"雷击样头痛 + SAH + DSA 确诊动脉瘤；尼莫地平 60 mg q4h 预防迟发性脑缺血，尽早穿刺/夹闭"},{"diseaseId":"ns_glioma","dx":"亚急性起病的头痛、癫痫或局灶神经缺损，MRI 增强示不规则环形强化或弥漫浸润性 T2 高信号，无弥散受限为高密度","key":"浸润性生长、边界不清、多位于白质；IDH 与 1p/19q 共缺失决定分子分型与预后"},{"diseaseId":"ns_meningioma","dx":"成年女性多见，缓慢进展的局灶神经症状或癫痫，MRI 示以硬脑膜为宽基底的均匀强化肿块伴「脑膜尾征」","key":"脑外肿瘤、宽基底贴硬脑膜、T1 等信号/明显均匀强化、可有钙化与骨质增生；WHO 1 级多可手术治愈"}],"diseases":[{"id":"ns_aneurysm","name":"颅内动脉瘤与蛛网膜下腔出血","aka":["颅内动脉瘤破裂","蛛网膜下腔出血","SAH","aSAH","Intracranial Aneurysm"],"rank":1,"basic":{"define":"颅内动脉壁内膜与中膜缺陷处因血流动力学应力形成的囊状/梭形扩张，破裂后血液进入蛛网膜下腔，即动脉瘤性蛛网膜下腔出血（aSAH），属于神经外科急症。","risk":["动脉瘤破裂家族史（一级亲属）","吸烟与高血压","多囊肾（ADPKD）、Marfan 综合征、Ehlers-Danlos 综合征","女性 >40 岁、绝经后","酗酒与可卡因等兴奋剂滥用"],"epi":"普通人群未破裂颅内动脉瘤患病率约 3.2%（中国部分地区筛查数据相近），年破裂率 0.5%–1%，直径 ≥7 mm 明显升高；aSAH 约占全部卒中的 5%，年发病率约 6–10/10 万，好发 40–60 岁，病死率 30%–40%。"},"patho":"血流动力学应力致分叉部血管壁内膜弹力板与肌层缺失、变薄，形成囊状突起；瘤壁变薄后因炎症与基质金属蛋白酶作用逐渐脆弱。破裂后血液弥散于基底池，早期触发颅内压骤升与急性脑积水，随后红细胞降解产物（氧合血红蛋白）引起血管痉挛，激活凝血与炎症级联反应，导致迟发性脑缺血与再出血风险。","dx":{"criteria":["突发「一生中最剧烈」的雷击样头痛（<1 h 达峰），伴颈项强直、恶心呕吐、意识障碍或局灶缺损，约 1/3 有短暂意识丧失","头颅 CT 平扫：基底池、外侧裂或脑沟高密度血液；发病 6 h 内 CT 敏感度接近 100%，12 h 后逐降","CT 阴性而高度疑诊者，行腰穿：均匀血性脑脊液或黄变（分光光度法检测胆红素）可确诊","CTA 为首选血管成像，DSA 为诊断金标准，对直径 <3 mm 或微小动脉瘤更敏感","按改良 Fisher 评分与 WFNS/Hunt-Hess 分级评估病情与预后","破裂急性期 CTA 与 3D-DSA 明确瘤体、瘤颈与载瘤动脉关系，为夹闭/栓塞方案提供依据"],"workup":["首诊：生命体征、GCS、Hunt-Hess 与 WFNS 分级、瞳孔与局灶体征；建立静脉通路","头颅 CT 平扫（首诊 6 h 内最敏感）+ CTA；必要时急诊 DSA","腰穿（CT 阴性、疑诊者）或 MRI/MRA 用于延迟就诊者","经颅多普勒（TCD）每日监测大脑中动脉血流速度，提示脑血管痉挛","血常规、凝血、电解质、血糖、肾功能、心电图与心肌酶（神经源性心肌顿抑）","脑钠肽、胸片评估心肺并发症；脑积水者行 EVD 并监测 ICP"],"grading":"Hunt-Hess 分级：Ⅰ级 无症状或轻度头痛；Ⅱ级 中度至重度头痛、颈强、无局灶缺损；Ⅲ级 嗜睡、意识模糊或轻度局灶缺损；Ⅳ级 昏睡、偏瘫；Ⅴ级 深昏迷、去大脑强直。WFNS 分级：Ⅰ级 GCS 15 无缺损；Ⅱ级 GCS 13–14 无缺损；Ⅲ级 GCS 13–14 伴缺损；Ⅳ级 GCS 7–12；Ⅴ级 GCS 3–6。改良 Fisher 分级：1 级 无血液；2 级 弥漫性薄层（<1 mm）；3 级 局限性厚血块（>1 mm）；4 级 厚血块或脑室内积血。"},"ddx":[{"name":"脑胶质瘤（ns_glioma）","point":"与本类 ns_glioma 的鉴别点：aSAH 突发雷击样头痛，CT 见 SAH 高密度；胶质瘤起病隐匿、进行性局灶症状或癫痫，影像为脑内浸润性肿块，无 SAH。"},{"name":"脑膜瘤（ns_meningioma）","point":"与本类 ns_meningioma 的鉴别点：脑膜瘤为缓慢进展、CT/MRI 示宽基底硬膜外肿块；动脉瘤为突发头痛伴 SAH，CTA/DSA 显示血管性病变。"},{"name":"脑动静脉畸形/海绵状血管瘤出血","point":"多见于年轻患者，常合并脑实质内出血，CTA/DSA 见畸形血管团与引流静脉（海绵状血管瘤 DSA 通常阴性，MRI T2* 见爆米花样含铁血黄素环）。"},{"name":"垂体卒中","point":"突发头痛伴视力下降、眼肌麻痹与内分泌功能障碍，MRI 见鞍区肿块伴出血，可伴视野缺损。"},{"name":"可逆性脑血管收缩综合征（RCVS）/原发性雷击样头痛","point":"反复雷击样头痛，DSA 见多发节段性血管收缩（«串珠样»），无动脉瘤与 SAH；需排除后诊断，避免误行手术。"},{"name":"脑静脉窦血栓形成","point":"头痛渐进、可伴癫痫，MRV/CTV 见静脉窦充盈缺损，CT 可见空三角征。"}],"tx":{"drug":[{"name":"尼莫地平","dose":"60 mg 口服/鼻饲 q4h（mg 每 4 小时），共 21 d；无口服条件时 0.5–1 mg/h 静脉泵入（注意避光）","note":"aSAH 防治脑血管痉挛与迟发性脑缺血的一线用药，应在发病后尽早开始并持续 21 d；降压作用导致低血压者需减量而非停药","renal":"遵说明书","hepatic":"重度肝功能不全减量（CYP3A4 代谢）","interact":"为 CYP3A4 底物，与强抑制剂（克拉霉素、伊曲康唑）合用升高血药浓度；与抗高血压药合用可致显著低血压"},{"name":"氨甲环酸","dose":"1 g 静脉缓慢推注，随后 1 g/h 静滴或 1 g q6h，仅在无法在 24–48 h 内完成动脉瘤处理的超急性期短程使用","note":"用于转运或等待转运期间降低再出血风险，但增加缺血性并发症，一旦动脉瘤已处理立即停用","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与其他促凝药合用增加血栓风险"},{"name":"尼卡地平","dose":"起始 5 mg/h 静脉泵入，每 15 min 递增 2.5 mg/h，最大 15 mg/h，滴定至收缩压 <160 mmHg（MAP <110 mmHg），处理动脉瘤后恢复适度血压","note":"用于破裂后急性血压控制，避免过度降压引起脑缺血","renal":"无需调整","hepatic":"严重肝功能不全减量","interact":"与强 CYP3A4 抑制剂合用升高血药浓度"},{"name":"拉贝洛尔","dose":"10–20 mg 静脉缓慢推注，必要时每 10 min 重复或加倍，总量 ≤300 mg；或 0.5–2 mg/min 持续泵入","note":"合并心率增快时首选；避免用于哮喘、重度心动过缓与心衰失代偿","renal":"遵说明书","hepatic":"遵说明书","interact":"与维拉帕米/地尔硫䓬合用加重房室传导阻滞"},{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注，按 ICP 与神经状态 q4–6h 重复","note":"用于颅内压升高/脑疝征象者，需与脑脊液引流配合，不用于常规脱水","renal":"肾功能不全慎用","hepatic":"","interact":"与肾毒性药物合用加重肾损伤"},{"name":"左乙拉西坦","dose":"500–1000 mg q12h 口服或静滴；一般预防疗程 3–7 d，仅用于有癫痫发作或高风险患者","note":"aSAH 常规预防性抗癫痫存在争议，不推荐长期预防","renal":"按 CrCl 调整","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"},{"name":"依诺肝素","dose":"40 mg 皮下注射 qd，在动脉瘤处理完成后开始（通常在术后 24 h）","note":"用于制动患者预防深静脉血栓；动脉瘤未处理前禁用","renal":"CrCl <30 减量至 20 mg qd","hepatic":"严重肝病者慎用","interact":"与非甾体抗炎药、抗血小板药合用增加出血"}],"nonDrug":["尽早行动脉瘤「闭塞」：发病 72 h 内（越早越好）行血管内弹簧圈栓塞（含血流导向装置/支架辅助）或开颅夹闭，术式由瘤颈形态、位置与患者状态决定","合并急性脑积水者留置脑室外引流（EVD），必要时行腰大池引流控制颅压","迟发性脑缺血的处理：保持血容量正常（避免预防性扩容），尼莫地平基础上可行「3H」中的诱发高血压（有动脉瘤已处理为前提）；无效者行球囊血管成形或动脉内罂粟碱/尼莫地平灌注","颅内压升高：头高位、镇静、渗透治疗、EVD 引流；重者去骨瓣减压","早期处理并发症：神经源性肺水肿、心肌顿抑、低钠血症（注意区分 SIADH 与脑性盐耗综合征）","EVD 期间预防感染，缩短留置时间；出院前行 CTA/DSA 随访评估栓塞/夹闭效果"],"life":["绝对卧床至动脉瘤处理前，避免用力排便、剧烈咳嗽及情绪激动（必要时使用乳果糖与镇痛）","出院后 3 个月内避免重体力劳动与驾驶，规律服药并复查血压","戒烟、控制血压与血脂；未处理动脉瘤者每 6–12 个月影像随访，小动脉瘤（<5 mm）增长缓慢者可延长至 2–3 年","遗传性结缔组织病或多囊肾家族需筛查一级亲属（MRA/CTA）"]},"prog":"总体病死率 30%–40%，约 1/3 幸存者遗留认知或局灶功能缺损；再出血 24 h 内发生率约 4%–10%，第 2 周内累计可达 20%，是早期死亡主因。Hunt-Hess Ⅰ–Ⅲ级且早期闭塞动脉瘤者预后较好，Ⅳ–Ⅴ级病死率显著升高。","refs":["《中国脑血管病一级预防指南（2019）》","《颅内动脉瘤诊疗中国专家共识》（中华医学会神经外科学分会，2020）","《动脉瘤性蛛网膜下腔出血管理指南》（美国心脏协会/卒中协会 AHA/ASA，2012，2023 更新）","《未破裂颅内动脉瘤中国专家共识》（2021）"]},{"id":"ns_glioma","name":"脑胶质瘤","aka":["胶质瘤","神经胶质瘤","Glioma","高级别胶质瘤","GBM"],"rank":2,"basic":{"define":"起源于神经胶质细胞（星形细胞、少突胶质细胞等）的原发性颅内肿瘤，按 2021 年 WHO 分类以组织学形态 + 分子标志（IDH、1p/19q、CDKN2A/B、TERT 启动子）综合命名与分级（WHO 1–4 级）。","risk":["绝大多数为散发性，无明确家族史","电离辐射暴露","Li-Fraumeni 综合征、NF1、Turcot 综合征等遗传性肿瘤综合征（少数）","年龄与性别：成人多为 40–70 岁，男性稍多；少突胶质细胞瘤相对年轻"],"epi":"原发性中枢神经系统肿瘤发病率约 6–10/10 万，其中胶质瘤约占 40%–50%；最常见的高级别恶性脑肿瘤为胶质母细胞瘤（GBM），年发病率约 3–5/10 万，中位发病年龄约 60 岁。"},"patho":"低级别胶质瘤（IDH 突变型）通常起自皮质下白质，缓慢浸润生长并沿白质纤维束扩散；随着 CDKN2A/B 纯合缺失、TERT 启动子突变等累积，逐步恶变为高级别（WHO 4 级）。GBM 以微血管增殖、假栅栏状坏死与高度侵袭性为特征，IDH 野生型 GBM 多伴有 EGFR 扩增、TERT 启动子突变与 MGMT 启动子甲基化（后者预示对替莫唑胺敏感）；肿瘤的浸润性生长与血脑屏障使局部治疗难以根除。","dx":{"criteria":["临床表现：亚急性头痛（晨起明显）伴恶心呕吐、癫痫发作（成人新发癫痫需警惕）、局灶缺损（偏瘫、失语、视野缺损）或认知/人格改变","MRI 平扫 + 增强 + 灌注/DWI/MRS 为诊断核心：低级别胶质瘤多无强化，T2/FLAIR 高信号边界不清；GBM 表现为不规则环形强化伴中心坏死、明显灌注升高","需组织学与分子病理确诊：IDH1/2 测序、1p/19q 共缺失检测（FISH 或 MLPA）、MGMT 启动子甲基化、TERT、CDKN2A/B、BRAF V600E 等","不能手术或活检者，结合影像与 MRS（胆碱升高、NAA 降低、乳酸峰）诊断并定期随访","鉴别需排除转移瘤、脓肿、淋巴瘤、脱髓鞘假瘤（后者可有开环征与激素反应）","术前做功能 MRI（fMRI/DTT）评估语言、运动功能与功能区定位，指导最大安全切除"],"workup":["头颅 MRI 增强（含 FLAIR、DWI、灌注、MRS）+ 神经导航手术计划","全身 CT、PET 或腹部超声排查原发肿瘤（转移瘤鉴别）","血常规、凝血、肝肾功能、电解质；术前评估癫痫控制情况与糖皮质激素使用","术后 72 h 内 MRI 增强评估切除程度（早期术后增强可为手术残留/炎症混淆）","分子病理（IDH、1p/19q、MGMT、TERT、CDKN2A/B、BRAF、ATRX）并纳入整合诊断","神经认知与生活质量评估作为治疗前后随访基线"],"grading":"2021 WHO 分类：星形细胞瘤 IDH 突变型（2、3、4 级）；少突胶质细胞瘤 IDH 突变伴 1p/19q 共缺失（2、3 级）；胶质母细胞瘤 IDH 野生型（4 级）；其他（儿童型弥漫性胶质瘤、室管膜瘤等）。切除程度：全切（GTR）、次全切（STR，≥80%）、部分切除、活检。"},"ddx":[{"name":"颅内动脉瘤与蛛网膜下腔出血（ns_aneurysm）","point":"与本类 ns_aneurysm 的鉴别点：胶质瘤起病隐匿、症状进行性加重无雷击样头痛；MRI 见浸润性肿瘤而非基底池积血，CTA/DSA 无动脉瘤。"},{"name":"脑膜瘤（ns_meningioma）","point":"与本类 ns_meningioma 的鉴别点：脑膜瘤宽基底贴硬膜、均匀强化并见脑膜尾征，T2 中等信号；胶质瘤位于脑内、不均匀/环形强化、可伴坏死与灌注升高。"},{"name":"脑转移瘤","point":"多发病灶位于灰白质交界、水肿不成比例大、强化呈环形但壁完整（«靶征»），PET-CT 或胸腹部 CT 可发现原发灶。"},{"name":"脑脓肿","point":"有感染史或免疫功能低下，DWI 显示脓肿腔弥散受限（ADC 低），胶质瘤坏死腔弥散通常不受限（或仅有薄壁）。"},{"name":"原发性中枢神经系统淋巴瘤","point":"病灶多位于深部白质/室周，均匀明显强化、弥散受限，激素使用后可显著缩小；活检为确诊依据。"},{"name":"肿瘤样脱髓鞘病变","point":"多发、较小病灶分散出现，增强呈「开环征」，激素治疗后明显缩小，随访影像消退可支持诊断。"}],"tx":{"drug":[{"name":"替莫唑胺","dose":"新诊断 GBM 同步放化疗阶段 75 mg/m² qd 口服（与放疗 60 Gy/30 次同期），然后 6 个周期辅助：150 mg/m² d1–5，第二周期起 200 mg/m² d1–5，每 28 d 一周期","note":"MGMT 启动子甲基化者获益显著；需每周及每周期前血常规监测（尤其血小板、中性粒细胞）；高剂量需联合止吐","renal":"重度肾功能不全慎用（需个体化评估）","hepatic":"重度肝功能不全慎用","interact":"与抗癫痫药（卡马西平、苯妥英）合用降低血药浓度；避免与强 CYP3A4 诱导剂同服"},{"name":"左乙拉西坦","dose":"500 mg q12h 起始，必要时加至 1000–1500 mg q12h；有癫痫发作者长期使用，无发作者不建议预防性用药","note":"肿瘤相关癫痫的一线选择，与化疗药物相互作用少","renal":"CrCl <50 减量","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"},{"name":"地塞米松","dose":"4–16 mg/d 分次（1–2 mg q6h 或 4 mg q6–8h），用于瘤周水肿与颅压升高，症状缓解后尽快减量至停药","note":"减轻瘤周水肿，短期使用；长期使用增加肌病、高血糖、感染与胃溃疡风险","renal":"遵说明书","hepatic":"肝脏合成白蛋白降低者游离药物升高","interact":"增强降糖药需求、与 CYP3A4 诱导剂合用降低疗效"},{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注 q4–6h，仅用于颅高压/脑疝危象的过渡处理","note":"需同时评估手术减压；监测渗透压与肾功能","renal":"肾功能不全慎用","hepatic":"","interact":"与肾毒性药物合用增加急性肾损伤"},{"name":"贝伐珠单抗","dose":"10 mg/kg 静滴 q2w（或 15 mg/kg q3w）","note":"用于复发 GBM 的挽救治疗，可快速减轻瘤周水肿与神经症状，但总生存获益有限；需监测血压、蛋白尿、出血与血栓风险","renal":"无需调整","hepatic":"遵说明书","interact":"与抗凝药合用增加出血风险"},{"name":"丙戊酸钠","dose":"15 mg/kg/d 起始，分 1–2 次口服，逐渐加量至有效或血药浓度 50–100 μg/mL；可用 1000–1500 mg 缓释剂型","note":"次选抗癫痫药，需监测肝功能、血氨与血小板；慎与其他化疗联合","renal":"遵说明书","hepatic":"严重肝病、尿素循环障碍禁用","interact":"与卡马西平、拉莫三嗪相互影响血药浓度；与替莫唑胺合用可能增加骨髓抑制"}],"nonDrug":["最大安全范围切除是治疗基石：低级别位于功能区时需唤醒手术 + 皮层电刺激定位；GBM 全切可改善生存","瘤周水肿明显或颅高压者可先去骨瓣减压或行减压性切除，再行放化疗","术后放疗：低级别胶质瘤高危（>40 岁或次全切）行 54–60 Gy；GBM 行 60 Gy/30 次（同步 TMZ）","复发/进展：再次手术评估（距首次手术 >6 个月、KPS 较高者获益）、二次放疗、电场治疗（TTFields，新诊断 GBM）、临床试验","分子分型指导下靶向治疗：IDH 抑制剂（针对 IDH 突变型）、BRAF V600E 抑制剂（儿童型/部分成人），须在专科中心评估","多学科（MDT：神经外科、放疗、肿瘤内科、病理、影像、康复）制定个体化方案","康复：术后早期肢体功能、语言与认知康复，配合心理支持"],"life":["长期抗癫痫依从性、避免熬夜与饮酒；驾驶职业者需咨询是否适宜","每 2–4 个月复查 MRI（GBM）或 3–6 个月（低级别），出现新症状随时复查","激素长期使用者补钙/维生素 D，监测血糖、血压与感染","生育与职业咨询、心理支持与安宁疗护讨论（晚期患者）","参加临床试验前评估资格与获益/风险"]},"prog":"IDH 野生型 GBM 中位生存约 12–18 个月（全切 + 规范治疗可延长），5 年生存率 <10%；IDH 突变型星形细胞瘤预后较好（中位生存 >5 年）；少突胶质细胞瘤（1p/19q 共缺失）中位生存可达 10 年以上。MGMT 启动子甲基化、年轻、KPS 高、切除彻底为有利因素。","refs":["《中国中枢神经系统胶质瘤诊断与治疗指南（2022 年版）》（中华医学会神经外科学分会）","《胶质瘤多学科综合诊疗（MDT）中国专家共识》（2021）","WHO 中枢神经系统肿瘤分类第 5 版（2021）","《NCCN 中枢神经系统肿瘤指南（2023）》"]},{"id":"ns_meningioma","name":"脑膜瘤","aka":["Meningioma","良性脑膜瘤","脑膜瘤（WHO 1 级）"],"rank":3,"basic":{"define":"起源于蛛网膜帽状细胞的中枢神经系统最常见原发性肿瘤（占 35%–40%），绝大多数（约 80%）为 WHO 1 级良性，因位于脑外压迫脑组织产生症状，以手术切除为主要治疗。","risk":["中老年女性（女:男约 2–3:1）","2 型神经纤维瘤病（NF2）与家族性脑膜瘤","既往头颅放疗（儿童白血病放疗史等）","孕激素/雌激素受体的可能影响（孕激素使用与乳腺癌病史的相关性有报道）"],"epi":"中枢神经系统原发肿瘤中脑膜瘤约占 36%–38%，女性发病率约为男性 2–3 倍；多数在 60 岁以上诊断，多为偶然发现的无症状小肿瘤。"},"patho":"肿瘤自蛛网膜颗粒细胞起始，缓慢膨胀性生长，与硬脑膜呈宽基底附着，常致邻近骨质增生或侵蚀；通过压迫而非浸润造成神经症状。部分亚型（非典型 WHO 2 级、间变性 WHO 3 级）因染色体 22q 缺失、TERT 启动子突变、CDKN2A/B 缺失而侵袭性更强、复发率高。肿瘤富含血供（脑膜中动脉分支为供血动脉），术中出血与切除范围是预后关键。","dx":{"criteria":["症状进展缓慢，可持续数月至数年：局灶癫痫、头痛、视力减退（蝶骨嵴/鞍旁）、嗅觉丧失（嗅沟）、肢体无力（凸面）","MRI 增强：与硬脑膜宽基底相连、均匀明显强化、可见「脑膜尾征」，T1 等信号、T2 等/稍高信号，压迫相邻脑皮质","CT：等/稍高密度伴钙化（约 20%），邻近骨质增生或侵蚀（骨窗观察）","较大或位置复杂者行血管造影/DSA 或 CTA/MRV 评估血供与静脉窦受累情况","无症状偶然发现者：MRI 随访观察，小肿瘤生长率约 1–2 mm/年","术后病理确定 WHO 级别与 Ki-67，指导随访与辅助放疗"],"workup":["MRI 平扫+增强（首选）+ MRS（缺乏明显胆碱峰为特点，需与胶质瘤鉴别）","CT 骨窗；颅底病变时评估骨质破坏与颈动脉/海绵窦关系","视力、视野与内分泌评估（鞍区/鞍旁/视神经管型）","术前脑血管造影与必要的供血动脉栓塞（复杂颅底型）","神经导航、术中神经电生理监测与功能 MRI 术前规划","术后 3 个月内复查 MRI 作为随访基线"],"grading":"WHO 2021 分级：1 级（脑膜皮型、纤维型、过渡型、血管瘤型等，约 80%）；2 级（非典型，≥4 个核分裂/10 HPF 或脑侵犯，约 15%–20%）；3 级（间变性，约 1%–3%）。Simpson 切除分级：Ⅰ级 全切含附着硬膜与骨；Ⅱ级 全切+电凝硬膜；Ⅲ级 全切无电凝；Ⅳ级 次全切；Ⅴ级 减压/活检。"},"ddx":[{"name":"颅内动脉瘤与蛛网膜下腔出血（ns_aneurysm）","point":"与本类 ns_aneurysm 的鉴别点：脑膜瘤为缓慢进展的实性肿块、MRI 见脑膜尾征；动脉瘤为突发雷击样头痛与 SAH，CTA/DSA 示囊状血管病变。"},{"name":"脑胶质瘤（ns_glioma）","point":"与本类 ns_glioma 的鉴别点：脑膜瘤位于脑外、宽基底贴硬膜、T1 等信号且显著均匀强化；胶质瘤为脑内浸润性病变、T2 高信号边界不清、强化不规则。"},{"name":"脑转移瘤","point":"多发病灶、周围水肿明显、常有原发肿瘤病史；脑膜瘤为单发、宽基底、无水肿或水肿轻。"},{"name":"孤立性纤维性肿瘤/血管周细胞瘤（SFT/HPC）","point":"与脑膜瘤影像相似，但多为脑外、T2 低信号、明显不均匀强化且易出血；最终依赖病理（STAT6 阳性）。"},{"name":"垂体腺瘤","point":"位于鞍内、蝶鞍扩大，可伴内分泌亢进（泌乳素、GH、ACTH）与视野缺损；脑膜瘤为脑外压迫性病变但神经内分泌常正常。"}],"tx":{"drug":[{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注，术前/颅高压时 q4–6h 使用","note":"仅用于伴瘤周水肿或颅压升高者，非长期方案","renal":"肾功能不全慎用","hepatic":"","interact":"与肾毒性药物合用加重肾损伤"},{"name":"地塞米松","dose":"4–8 mg 静脉/口服 q6–8h，术后按水肿与神经状态 3–7 d 内减量","note":"用于缓解瘤周水肿、术后脑水肿；长期使用注意肌病、高血糖与感染","renal":"遵说明书","hepatic":"遵说明书","interact":"与华法林、抗癫痫药、降糖药存在相互作用"},{"name":"左乙拉西坦","dose":"500 mg q12h，必要时加至 1000 mg q12h","note":"有术前癫痫发作者术后继续应用；无发作者是否预防性用药取决于是否累及皮质功能区","renal":"CrCl <50 减量","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"},{"name":"依诺肝素","dose":"40 mg 皮下注射 qd，自术后 12–24 h 开始（按出血风险评估）","note":"用于术后深静脉血栓预防，尤其老年、卧床或下肢瘫痪者","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板/NSAIDs 合用增加出血"},{"name":"奥曲肽（生长抑素类似物）","dose":"100 μg 皮下注射 q8h 起始，可递增至 200–500 μg q8h（部分垂体/鞍区型），或依说明书","note":"用于合并肢端肥大症等其他内分泌相关疾病时的对症处理；对脑膜瘤本身无明确指征，需专科评估","renal":"遵说明书","hepatic":"遵说明书","interact":"与降糖药合用可影响血糖，可能与环孢素相互作用"}],"nonDrug":["有症状或有明确占位效应/生长者：手术切除是首选，力争 Simpson Ⅰ–Ⅱ级全切","颅底/静脉窦旁等高风险位置：可次全切除 + 术后放疗，或先行栓塞核心供血动脉减少出血","无症状小肿瘤（<2–3 cm）：MRI 随访观察，年增长 >1–2 mm 或出现症状后手术","立体定向放射外科（SRS，如伽马刀）：适用于直径 <3 cm、手术高危或次全切除术后残留者（边缘剂量 12–16 Gy）","WHO 2–3 级：术后放疗，复发者可再次手术 + 放疗或系统治疗（临床试验中）","静脉窦受累情况应在术前 MRV/DSA 明确，避免切除时误伤优势静脉窦","老年患者的整体功能评估（KPS、合并症）决定手术 vs 观察"],"life":["术后 3 个月、此后每年复查 MRI 增强；WHO 2–3 级者缩短至 6 个月一次","术后出现新发癫痫者继续抗癫痫，无发作者可在 3–6 个月后评估停药","控制血压、避免剧烈头部撞击；有癫痫史者注意睡眠与驾驶限制","NF2 或多发脑膜瘤患者需遗传咨询与全神经轴影像随访"]},"prog":"WHO 1 级全切（Simpson Ⅰ级）后 5 年复发率约 5%–10%，Simpson Ⅳ级可达 30%–40%；WHO 2 级 5 年复发率约 40%，WHO 3 级可达 60%–70%。手术并发症与肿瘤部位密切相关（颅底型风险更高），多数健康患者术后功能恢复良好。","refs":["《脑膜瘤诊断与治疗中国专家共识》（中华医学会神经外科学分会，2019）","WHO 中枢神经系统肿瘤分类第 5 版（2021）","《NCCN 中枢神经系统肿瘤指南（2023）》"]}]},{"id":"spine_neuro","name":"脊柱神经外科","rank":3,"summary":"脊柱神经外科：以影像与神经功能分级确定压迫部位与程度，再依是否进行性恶化决定减压时机——脊髓损伤按 ASIA 分级并尽早减压，脊髓型颈椎病确诊即手术，脊髓空洞先解除枕大孔区脑脊液梗阻。","compare":[{"diseaseId":"ns_sci","dx":"明确脊柱外伤史 + 损伤平面以下感觉/运动/括约肌功能障碍，CT 示椎体骨折脱位或椎管占位，MRI 示脊髓压迫或髓内高信号，按 ASIA 分级量化神经功能","key":"外伤起病、急性（<24 h）；ASIA 分级 + 脊柱稳定性评估决定手术减压时机与固定方式，需同时防治神经源性休克与自主神经反射异常"},{"diseaseId":"ns_csm","dx":"中老年慢性起病，上肢精细动作障碍、步态不稳、腱反射亢进与 Hoffmann 征阳性，MRI 示椎间盘突出/椎管狭窄压迫脊髓，JOA 评分量化功能","key":"非外伤性、进展缓慢；神经根病以根性放射痛为主可先保守，脊髓型一旦确诊并出现症状即考虑减压手术"},{"diseaseId":"ns_syrinx","dx":"分离性痛温觉丧失、手内在肌萎缩或进行性痉挛性瘫，MRI 见脊髓中央纵向脑脊液样空洞，并见小脑扁桃体下疝或颅颈交界畸形","key":"空洞是结果而非病因：必查枕大孔区畸形与脑脊液流动受阻，有症状者行后颅窝减压 + 硬膜成形"}],"diseases":[{"id":"ns_sci","name":"脊髓损伤","aka":["Spinal Cord Injury","SCI","创伤性脊髓损伤","脊髓损伤（ASIA 分级）"],"rank":1,"basic":{"define":"脊柱骨折、脱位或椎间盘突出等外力作用下，脊髓发生挫伤、压迫、缺血或撕裂，导致损伤平面以下感觉、运动与括约肌功能障碍的急性神经损害；按 ASIA 标准分级并评估脊柱稳定性，严重程度从完全性损伤到神经功能正常不等。","risk":["交通事故（首位病因）、高处坠落、跌倒（老年人多见）","颈椎或胸腰段爆裂骨折、椎体脱位、骨折脱位","老年人颈椎管狭窄基础上的轻微过伸伤（无骨折脱位型脊髓损伤）","脊柱强直、骨质疏松、既往颈椎手术史","运动损伤（跳水、体操、橄榄球）与暴力伤","饮酒与未佩戴安全带等可预防因素"],"epi":"我国年发病率约 (23–60)/100 万，颈髓占 50%–60%，男:女约 3:1。"},"patho":"原发性损伤为机械压迫与剪切致脊髓轴突断裂、出血；数小时内继发损伤启动（缺血、谷氨酸兴奋毒性、钙超载、炎症水肿），使损伤范围向上下扩展。完全性损伤急性期出现脊髓休克（弛缓性瘫痪、反射消失），数周后转为痉挛性瘫；高位颈髓损伤切断交感通路，导致神经源性休克与呼吸功能障碍。","dx":{"criteria":["明确外伤史，伤后立即或数小时内出现损伤平面以下感觉减退/消失、运动障碍（截瘫或四肢瘫）与括约肌功能障碍（尿潴留、肛门括约肌松弛）","伤后 72 h 内由有经验的医师完成 ASIA 神经学检查并分级，需同时记录感觉平面、运动平面、神经损伤平面、部分保留区（ZPP）与 ASIA 损伤分级（AIS A–E）","骶段保留（S4–5 感觉或肛门自主收缩）存在即为不完全性损伤；缺失且无运动则为 AIS A","高位颈髓损伤（C1–C4）伴呼吸困难、膈肌麻痹，需紧急评估气道与通气","颈椎中线压痛、棘突台阶感、椎旁肌痉挛提示脊柱不稳定，搬运中转颈托等器具固定","出现低血压伴心动过缓（神经源性休克）、损伤平面以下无汗、体位性低血压、括约肌失禁等自主神经功能异常"],"workup":["院前与急诊：脊柱制动（颈托 + 硬板床平托翻身），先处理 ABC，维持 SpO₂ ≥94% 与收缩压 ≥90 mmHg，避免二次搬动损伤","脊柱 CT（颈、胸、腰全程）：判断骨折、脱位、椎管侵占率与后柱复合体完整性，为首选骨性评估手段","脊柱 MRI（T1、T2 及压脂序列）：评估脊髓压迫、髓内水肿/出血（T2 高信号长度与预后相关）、韧带复合体损伤与椎间盘突出，为手术决策关键","ASIA 检查：肌力（0–5 级）、针刺与轻触觉（0–2 分）、肛门指检（自主收缩与深感觉），建议 72 h 后复查以判断是否脊髓休克","胸腹与骨盆 CT 排查合并伤；血气、乳酸、电解质（注意低钠血症）、血糖与凝血","全脊柱不稳时加做全脊柱 CT；疑椎动脉或主动脉损伤行 CTA"],"grading":"ASIA 损伤分级（AIS）：A 完全性（S4–5 无感觉与运动保留）；B 感觉不完全（损伤平面以下包括骶段有感觉但无运动）；C 运动不完全（骶段保留，损伤平面以下超过半数关键肌肌力 <3 级）；D 运动不完全（超过半数关键肌肌力 ≥3 级）；E 正常（感觉与运动均正常，可有异常反射）。另按损伤平面分颈髓（C1–C8）、胸髓（T1–T12）、腰骶髓；按病程分急性期（<1 个月）、亚急性（1–6 个月）与慢性期。"},"ddx":[{"name":"颈神经根病与脊髓型颈椎病（ns_csm）","point":"与本类 ns_csm 的鉴别点：SCI 有明确外伤与急性起病，ASIA 分级呈节段性障碍，影像见骨折脱位或急性髓内水肿；CSM 为慢性进展的退变压迫，JOA 进行性下降，无外伤与骨折脱位。"},{"name":"脑积水（ns_hydrocephalus）","point":"与本类 ns_hydrocephalus 的鉴别点：SCI 以损伤平面以下运动感觉障碍为核心，脑室正常；脑积水以头痛、认知下降与步态障碍为主。"},{"name":"急性脊髓炎/横贯性脊髓炎","point":"多无外伤或仅有轻微前驱感染，数小时—数天内进展为截瘫伴感觉平面与尿潴留，MRI 见髓内长节段 T2 高信号、无椎体骨折；脑脊液细胞数增多有助于鉴别。"},{"name":"无骨折脱位型颈髓损伤（SCIWORA）","point":"老年人过伸或儿童外伤后出现脊髓症状，X 线/CT 无骨折脱位，MRI 可见髓内高信号或椎管狭窄；仍需按 ASIA 分级处理并评估是否需减压。"},{"name":"脊髓硬膜外血肿/肿瘤致急性压迫","point":"可亚急性起病，MRI 见硬膜外梭形压迫或占位，无外伤或轻微；需紧急减压。"},{"name":"马尾综合征（腰椎间盘巨大突出）","point":"鞍区麻木、大小便障碍与双下肢弛缓性瘫，MRI 见巨大椎间盘压迫马尾，定位与脊髓损伤平面不同。"}],"tx":{"drug":[{"name":"甲泼尼龙（仅发病 8 h 内可选）","dose":"伤后 8 h 内非穿透性急性脊髓损伤：30 mg/kg 于 15 min 内静脉滴注，间歇 45 min 后以 5.4 mg/kg/h 持续泵入 23 h；超过 8 h 者不推荐使用","note":"争议治疗：2023 AOSpine 指南对 24 h 内急性 SCI 作弱推荐，国内多数脊柱外科与创伤中心已不常规使用或直接写不推荐；仅对伤后 8 h 内、无糖皮质激素禁忌（感染、消化道溃疡、严重糖尿病、脓毒症）的成人可个体化选用。不推荐以 24 h 或 48 h 延长方案替代；用药期间监测血糖、电解质、消化道出血与伤口感染","renal":"遵说明书","hepatic":"严重肝功能不全者作用增强，注意监测血糖与水肿","interact":"与非甾体抗炎药合用显著增加消化道出血与溃疡风险；与降糖药合用需上调降糖剂量"},{"name":"对乙酰氨基酚（镇痛首选）","dose":"0.5–1 g 口服或静脉 q6h，24 h 总量不超过 2 g（肝病或营养差者），一般成人不超过 4 g","note":"用于轴性疼痛与创伤后疼痛的基础镇痛，可与阿片类联合以减少阿片用量","renal":"CrCl <30 延长给药间隔","hepatic":"严重肝功能不全禁用或减量至 2 g/d 以下","interact":"与华法林长期合用可致 INR 升高；避免与其他含对乙酰氨基酚复方制剂叠加"},{"name":"曲马多（含阿片成分的镇痛备选）","dose":"50–100 mg 口服 q6h，单次不超过 100 mg，24 h 不超过 400 mg；可联用对乙酰氨基酚","note":"用于创伤后疼痛的基础镇痛，可与阿片类联用以减少阿片用量","renal":"CrCl <30 需减量并延长给药间隔","hepatic":"严重肝功能不全减量并监测","interact":"与 SSRI/SNRI、曲坦类合用增加 5-羟色胺综合征风险；与苯二氮䓬类合用加重呼吸抑制"},{"name":"依诺肝素","dose":"术后或伤后 24–48 h 经影像确认出血稳定后开始 40 mg 皮下注射 qd；合并下肢瘫痪、长期卧床者维持至康复期","note":"大剂量糖皮质激素期间预防应激性溃疡；长期使用注意骨折风险","renal":"CrCl <30 减量至 20 mg qd","hepatic":"严重肝病伴凝血障碍者慎用","interact":"与抗血小板药、NSAIDs 合用增加出血；硬膜外/鞘内麻醉及引流管拔除前后需评估穿刺时机"},{"name":"低分子肝素（达肝素钠）","dose":"5000 IU 皮下注射 qd（体重大者 5000 IU q12h），预防深静脉血栓","note":"用于脑脊液引流术后或需长期制动者；合并下肢瘫痪者维持至康复期","renal":"CrCl <30 减量或改为普通肝素","hepatic":"重度肝功能不全慎用","interact":"与抗凝/抗血小板药合用增加出血"},{"name":"纳洛酮-新斯的明（神经源性休克辅助）","dose":"遵说明书；低血压顽固者由专科评估使用，新斯的明常用 0.5 mg 静注并以心率监测","note":"用于 T6 以上损伤的自主神经反射异常：先排查尿潴留、便秘与压疮诱因","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗胆碱能药、β 受体阻滞剂相互作用可加重心动过缓；禁与阿托品类同时评估"},{"name":"去甲肾上腺素（神经源性休克）","dose":"0.05–0.5 μg/kg/min 中心静脉泵入，滴定至 MAP ≥65–85 mmHg（老年或既往高血压者偏高）","note":"目标为维持脊髓灌注压（MAP 65–90 mmHg）；需同时补液，避免容量过负荷；心动过缓者联合抗胆碱能药或小剂量多巴胺","renal":"遵说明书","hepatic":"遵说明书","interact":"与三环类抗抑郁药、单胺氧化酶抑制剂合用可致血压剧烈波动"},{"name":"依帕司他/甲钴胺（神经营养辅助）","dose":"甲钴胺 0.5 mg 口服 tid 或 0.5 mg 肌注 qd；依帕司他 50 mg 口服 tid","note":"国内常用于改善脊髓损伤后感觉障碍，证据等级有限，不作为核心治疗；疗程与选择遵专科意见","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["血流动力学目标：无出血禁忌者维持 MAP 65–90 mmHg（部分共识 85–90 mmHg）至少 5–7 d","手术时机：影像明确脊髓受压（骨折脱位、椎间盘突出、硬膜外血肿）者，在全身情况允许下于伤后 24 h 内行减压 + 固定/融合，越早越可能改善神经功能；完全性损伤亦有减压价值（缩短住院与并发症）","手术方式：前路（椎体次全切、ACDF/ACCF）或后路（椎板切除、椎板成形、侧块/椎弓根钉固定），合并骨折脱位需复位与三柱稳定性评估后行内固定融合","无骨折脱位型且无持续压迫者，先保守：颈托固定 3 个月、康复训练；进行性神经恶化时重新评估 MRI 并手术","导尿与肠道管理：早期留置尿管过渡，病情稳定后改为间歇清洁导尿，定时排便训练以降低尿路感染与便秘","并发症防治：压疮（2 h 翻身、气垫床、骶尾与足跟重点减压）、肺不张与肺炎（高位颈髓者早期介入呼吸训练，必要时气管切开）、深静脉血栓、异位骨化、痉挛与疼痛管理","自主神经反射异常（T6 以上损伤）：发作时取坐位、解除诱因（膀胱充盈、便秘、压疮），血压骤升者用短效降压药，避免反射性低血压","早期康复：伤后 1 周内由康复科介入，进行关节被动活动、坐位平衡、呼吸训练与功能作业训练"],"life":["出院前完成居家环境改造评估（无障碍、防跌倒、气垫床与辅助器具），培训家属转移与皮肤护理","长期间歇导尿规范与泌尿系超声监测；定期评估膀胱容量与残余尿","坚持康复锻炼与轮椅转移训练，避免二次跌倒与脊柱再次损伤","颈髓损伤者注意体温调节障碍（无汗致高热、低温），避免极端温度环境","定期随访（每 3 个月 ASIA 复查与 MRI），关注痉挛、神经病理性疼痛、抑郁与性功能康复"]},"prog":"AIS A 完全性损伤多数遗留下肢或四肢不可逆功能障碍，AIS C/D 不完全性损伤 1 年后约 80%–90% 可恢复至独立步行或借助器具步行；颈髓完全性损伤 1 年死亡率约 10%–15%，高位颈髓损伤伴呼吸衰竭者更高。伤后 6–12 个月为神经恢复的主要窗口，并发症（肺部感染、压疮、尿路感染、VTE）是急性期死亡主因。","refs":["《成人急性创伤性脊髓损伤诊疗指南》（中国康复医学会脊柱脊髓专业委员会，2021）","《急性脊柱脊髓损伤临床诊治专家共识》（中华医学会骨科学分会，2018）","《International Standards for Neurological Classification of Spinal Cord Injury》（ASIA，2019 修订版）","《AOSpine 急性脊髓损伤管理指南》（2023）","《颅脑与脊柱创伤一体化救治中国专家共识》（2020）"]},{"id":"ns_csm","name":"颈神经根病与脊髓型颈椎病","aka":["Cervical Radiculopathy","Cervical Spondylotic Myelopathy","CSM","颈神经根病","脊髓型颈椎病"],"rank":2,"basic":{"define":"颈椎退变（椎间盘突出、骨赘、关节突肥大、黄韧带肥厚或 OPLL）压迫神经根或颈髓所致的慢性病：压迫神经根表现为沿皮节放射的上肢痛麻（颈神经根病）；压迫颈髓表现为手部精细动作障碍、步态不稳与上运动神经元体征（脊髓型颈椎病，CSM）。","risk":["年龄 >50 岁，颈椎间盘退变与骨赘形成","先天性椎管狭窄（椎管矢状径 <13 mm，Pavlov 比值 <0.8）","长期伏案、低头作业等颈部负荷重的职业","后纵韧带骨化（OPLL）与黄韧带骨肥厚","颈椎外伤史、吸烟与肥胖"],"epi":"颈神经根病年发病率约 80–100/10 万；症状性 CSM 年发病率约 3–5/10 万。"},"patho":"椎间盘退变、突出与骨赘、钩椎关节增生使椎间孔与椎管矢状径缩小。神经根受压出现缺血与炎症介质（TNF-α、IL-6）介导的根性疼痛；颈髓受压致皮质脊髓束脱髓鞘与前角细胞丢失，T2 高信号提示髓内水肿或软化，动态压迫使病情慢性进展。","dx":{"criteria":["颈神经根病：颈肩痛向一侧上肢沿皮节放射，Spurling 试验阳性；相应肌节肌力下降与腱反射减弱；C5–6 突出压迫 C6（拇指、肱二头肌反射减弱）、C6–7 压迫 C7（中指、肱三头肌反射减弱）、C7–T1 压迫 C8（小指、手内在肌萎缩）","CSM 诊断：① 慢性进行性颈髓功能障碍（手笨拙、步态不稳、下肢僵硬）；② 上运动神经元体征（Hoffmann 征、Babinski 征阳性）；③ MRI 证实颈髓受压","JOA 评分（0–17 分：上肢运动 4、下肢运动 4、感觉 6、膀胱功能 3）或改良 mJOA（0–18 分）量化功能：15–17 分轻度、12–14 分中度、<12 分重度","T2 髓内高信号分级（无、模糊、清晰局限、清晰弥漫），弥漫高信号提示预后较差","影像与症状必须相符；无症状的影像学狭窄不作为手术指征"],"workup":["颈椎 MRI 平扫（首选）：评估椎间盘突出节段、脊髓受压与 T2 髓内信号","颈椎 CT 骨窗：评估骨赘、OPLL 厚度与范围、椎间孔狭窄；颈椎过伸过屈位 X 线评估曲度与稳定性","肌电图与神经传导：鉴别腕管/肘管卡压与肌萎缩侧索硬化（ALS），确认根性损害节段","JOA/mJOA 评分、握力、10 秒步行测试作为基线与随访","术前行屈伸位评估与麻醉风险评估，伴 OPLL 者备神经电生理监测"],"grading":"mJOA 轻（15–17）、中（12–14）、重（<12）；Nurick 分级 0–5（0 无脊髓症状、1 手笨拙但步态正常、2 轻度步态障碍可工作、3 需助行、4 需他人辅助、5 卧床或轮椅）。JOA 改善率 =（术后 − 术前）/（17 − 术前）× 100%。影像可按 Nagashima 与 K 线分型指导后路术式。"},"ddx":[{"name":"脊髓损伤（ns_sci）","point":"与本类 ns_sci 的鉴别点：CSM 无急性外伤、病程数月至数年，JOA 评分缓慢下降；SCI 有明确外伤、数小时内出现 ASIA 分级的节段性瘫痪，影像见骨折脱位或急性髓内水肿，属急症需 24 h 内评估减压。"},{"name":"脊髓空洞与枕大孔畸形（ns_syrinx）","point":"与本类 ns_syrinx 的鉴别点：CSM 以手笨拙与步态障碍、Hoffmann 征阳性为主，MRI 见椎间盘/骨赘压迫；脊髓空洞以分离性感觉障碍与肌萎缩为主，MRI 见髓内纵向液性空洞。"},{"name":"肌萎缩侧索硬化（ALS）","point":"上下运动神经元同时受累但无感觉障碍，肌电图见广泛失神经电位（多节段），颈椎 MRI 无法解释全部体征；误诊行颈椎手术风险极高。"},{"name":"腕管综合征/肘管综合征","point":"麻木局限于正中/尺神经分布，Phalen/Tinel 试验阳性，肌电图示腕部或肘部传导阻滞，而颈椎受压节段与症状不符。"},{"name":"颈髓肿瘤（室管膜瘤、星形细胞瘤）","point":"MRI 增强见强化肿块或囊性病变，进展数周至数月，可伴夜间痛与脑脊液蛋白升高。"},{"name":"颈椎结核/感染","point":"发热、夜间静息痛、椎间隙破坏与椎前软组织肿胀，MRI 强化伴 ESR/CRP 升高；需病理与抗感染/抗结核治疗。"}],"tx":{"drug":[{"name":"塞来昔布","dose":"200 mg 口服 qd（或 100 mg bid），疗程不超过 2–3 周用于急性疼痛期","note":"神经根型急性期抗炎镇痛；心血管病史与胃溃疡史者慎用","renal":"eGFR <30 禁用或慎用，避免长期使用","hepatic":"严重肝功能不全慎用","interact":"与抗凝药、抗血小板药合用增加消化道出血；与 ACEI/ARB 及利尿剂合用可致肾功能恶化"},{"name":"乙哌立松","dose":"50 mg 口服 tid，餐后服用，疗程一般 2–4 周","note":"中枢性肌松剂，缓解颈肩部肌肉痉挛与疼痛；注意肝功能与困倦","renal":"遵说明书","hepatic":"严重肝功能不全慎用，用药期间监测转氨酶","interact":"与其他中枢抑制剂合用可加重嗜睡"},{"name":"普瑞巴林","dose":"75 mg 口服 bid 起始，可增至 150 mg bid；按 CrCl 调整","note":"用于神经根性神经病理性疼痛；逐渐停药避免反跳","renal":"按 CrCl 减量：CrCl 30–60 减半，CrCl <30 起始 25–50 mg/d","hepatic":"遵说明书","interact":"与阿片类、苯二氮䓬类合用加重呼吸抑制与嗜睡"},{"name":"甲泼尼龙（脊髓型围手术期）","dose":"遵说明书；围手术期短期 30 mg/kg 静滴后递减，或小剂量 1–2 mg/kg 短期使用","note":"CSM 不推荐长期激素；围手术期短期使用有争议，需专科评估","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道出血；与降糖药合用需调整剂量"},{"name":"依诺肝素","dose":"术后 12–24 h 经影像确认无活动性出血后 40 mg 皮下注射 qd","note":"术后制动、下肢肌力差者首选；术前评估椎管内穿刺时机","renal":"CrCl <30 减至 20 mg qd","hepatic":"严重肝病慎用","interact":"与抗血小板药、NSAIDs 合用增加出血"}],"nonDrug":["神经根型保守 6–12 周：颈托短期制动（2–3 周，避免长期依赖）、颈椎牵引（3–5 kg，坐位间歇）、颈肌等长收缩训练；约 70%–80% 可缓解","神经根型手术指征：6–12 周规范保守无效、进行性肌力下降、MRI 明确椎间孔压迫且与症状一致；可选前路颈椎间盘切除融合（ACDF）/人工椎间盘置换或后路椎间孔减压","CSM：确诊并有症状者（即使轻症）应在评估后尽早减压手术；术式依节段数与曲度选择前路（ACDF/ACCF）或后路（椎板成形/椎板切除 + 侧块钉棒固定）","OPLL 超过 K 线或伴后凸者优先后路；需术中神经电生理监测，避免颈椎过伸位插管","术后颈托保护 4–6 周，逐步康复（颈深屈肌、肩胛稳定与平衡训练）","急性颈髓损伤合并 CSM 者按脊髓损伤处理，必要时急诊减压"],"life":["避免长时间低头伏案（每 30–40 min 活动颈部）、枕头过高与颈椎过伸按摩","保健操以等长收缩与颈深屈肌训练为主，不做剧烈旋转与甩头动作","CSM 患者防跌倒与颈部外伤（乘车系安全带），避免跳水、摔跤等高冲击运动","术后 1、3、6、12 个月复查颈椎 X 线/MRI，评估内固定与 JOA 变化","保守期间出现新发肌力下降、大小便异常或步态不稳，应立即复诊评估手术"]},"prog":"神经根型约 70%–80% 经保守 3 个月内明显缓解；CSM 自然病程多缓慢进展，约 20%–60% 在数年内恶化，轻中度者早期手术功能改善优于延迟手术。减压术后 JOA 改善率中位约 50%–70%，弥漫性 T2 高信号与病程 >12 个月者较差；C5 神经根麻痹为常见并发症（约 5%–10%）。","refs":["《脊髓型颈椎病诊疗中国专家共识》（中华医学会骨科学分会，2018）","《颈椎病诊治与康复指南（2010 版）》（中华医学会骨科学分会）","《颈椎退行性疾病手术与非手术治疗中国专家共识》（2020）","《AOSpine 退行性颈脊髓病临床实践指南》（2019）","《颈椎人工椎间盘置换术专家共识》（2019）"]},{"id":"ns_syrinx","name":"脊髓空洞与枕大孔畸形","aka":["脊髓空洞症","Syringomyelia","Chiari 畸形","小脑扁桃体下疝畸形","枕大孔区畸形"],"rank":3,"basic":{"define":"脊髓空洞（syringomyelia）指脊髓内形成与脑脊液性质相近的纵向液性空腔并逐渐扩大、压迫周围脊髓组织；多数继发于枕大孔区畸形（Chiari Ⅰ型畸形、颅底凹陷、后颅窝狭小）、外伤后蛛网膜粘连、髓内肿瘤或脊髓栓系，属「病因在枕大孔、病损在脊髓」的一类疾病。","risk":["先天性后颅窝狭小、颅底凹陷症、寰枕融合等枕大孔区畸形","外伤后蛛网膜粘连、脊柱侧弯矫形手术史","髓内肿瘤（室管膜瘤、血管母细胞瘤）与脊髓栓系","家族性 Chiari 畸形（少数），女性稍多"],"epi":"Chiari Ⅰ型检出率约 0.5%–3.6%，其中 4%–8% 合并空洞。"},"patho":"主流机制为脑脊液流体动力学障碍：枕大孔区狭窄或蛛网膜粘连使颅—椎管脑脊液压力梯度与搏动性流动受阻，脑脊液经中央管或背侧根入口区进入脊髓形成空洞，并随咳嗽、用力的颅压波动向上下扩大，压迫脊髓前连合（分离性痛温觉丧失）与侧索、前角（痉挛与肌萎缩）。","dx":{"criteria":["分离性感觉障碍：手/上肢及颈肩部痛温觉丧失而触觉保留，可伴手内在肌萎缩、爪形手；下肢痉挛性无力与步态不稳","可伴顽固性枕颈部疼痛（Valsalva 动作加重）、吞咽困难、声嘶或儿童脊柱侧弯","MRI 确诊：脊髓中央纵向液性腔（T1 低信号、T2 高信号，同脑脊液信号），常 >3 mm 并向上/下延伸","Chiari Ⅰ型影像标准：小脑扁桃体下缘低于枕骨大孔连线 ≥5 mm，伴后颅窝拥挤；<5 mm 但脑脊液流动受阻（Chiari 0 型）亦可致病","出现持续麻木、进展性肌萎缩或感觉障碍不对称时，必须增强 MRI 排除髓内肿瘤"],"workup":["全脊柱 MRI（矢状位 T1/T2，必要时增强）：明确空洞范围、Chiari 畸形与髓内肿瘤","颅颈交界区 CT 三维重建：颅底凹陷、寰枕融合与后颅窝容积","相位对比（cine）MRI：评估枕大孔区脑脊液流动受阻，也用于术后随访","颈椎屈伸位 X 线评估颅颈交界稳定性；合并侧弯者行脊柱全长 X 线测 Cobb 角"],"grading":"Chiari 畸形分型：Ⅰ型（扁桃体下疝 ≥5 mm，无脑积水）、Ⅰ.5 型（合并脑干下疝）、Ⅱ型（蚓部与四脑室下疝，多见于脊膜膨出）、Ⅲ型（枕部脑膜脑膨出）、Ⅳ型（小脑发育不全）。空洞按节段（颈段、颈胸段、全程）与是否偏心分型。"},"ddx":[{"name":"颈神经根病与脊髓型颈椎病（ns_csm）","point":"与本类 ns_csm 的鉴别点：脊髓空洞以分离性痛温觉障碍与手内在肌萎缩为特征，MRI 见髓内纵向液性腔；CSM 为退变性椎管狭窄压迫、Hoffmann 征阳性，无髓内空洞。"},{"name":"脊髓损伤（ns_sci）","point":"与本类 ns_sci 的鉴别点：SCI 有明确外伤、功能障碍与损伤平面严格对应、MRI 见挫伤水肿或髓内出血；脊髓空洞病程数年至数十年。"},{"name":"颈髓肿瘤（室管膜瘤、星形细胞瘤）","point":"MRI 见髓内或髓外占位伴脊髓增粗与强化，呈进行性加重、可夜间痛；空洞可为肿瘤的继发表现，需增强 MRI 明确。"},{"name":"多发性硬化/视神经脊髓炎谱系病","point":"斑片状脊髓病灶伴强化、可有视神经炎史；MRI 显示髓内病灶而非连续液性空洞，必要时查 AQP4-IgG。"},{"name":"运动神经元病（ALS）","point":"上下运动神经元同时受累但无感觉障碍，肌电图见广泛失神经；手肌萎缩者勿误认空洞。"},{"name":"带状疱疹后神经痛/枕神经痛","point":"疼痛位于皮节并有皮疹史或枕神经压痛，无分离性感觉丧失与脊髓影像异常。"}],"tx":{"drug":[{"name":"加巴喷丁（或普瑞巴林）","dose":"加巴喷丁 300 mg 口服 qn 起始，逐渐增至 300–600 mg tid；或普瑞巴林 75 mg bid","note":"用于空洞相关神经病理性疼痛，不改变空洞大小","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"与阿片类、苯二氮䓬类合用加重呼吸抑制与嗜睡"},{"name":"卡马西平","dose":"100 mg 口服 bid 起始，逐渐加至 200 mg q8–12h，监测血药浓度 4–12 μg/mL","note":"用于闪电样疼痛；用药前评估 HLA-B*1502","renal":"遵说明书","hepatic":"肝功能不全者慎用并减量","interact":"强 CYP3A4 诱导剂，降低避孕药、华法林与他药浓度"},{"name":"甘露醇","dose":"0.25–1 g/kg 静脉滴注 q4–6h","note":"仅于术后合并急性脑积水或颅压升高时使用，首选 EVD 引流","renal":"肾功能不全慎用","hepatic":"遵说明书","interact":"与肾毒性药物合用加重肾损伤"}],"nonDrug":["手术指征：有症状的 Chiari Ⅰ型畸形（进行性神经功能缺损或顽固枕颈部疼痛），伴或不伴空洞；无症状且空洞小者可随访","标准术式：后颅窝减压（枕骨下小骨窗 + C1 后弓切除）+ 硬膜成形术；有明确脑脊液流动受阻者应行硬膜扩大修补","不常规切除小脑扁桃体；空洞持续扩大且减压无效者行空洞—蛛网膜下腔分流或脊髓切开引流","颅底凹陷/寰枢不稳者行后路枕颈固定（必要时前路经口减压），单纯减压会加重不稳","继发性空洞处理原发病：髓内肿瘤切除、蛛网膜粘连松解、脊髓栓系松解","术后颈部制动 4–6 周，避免剧烈咳嗽、用力排便与举重"],"life":["避免 Valsalva 动作（举重、屏气用力、剧烈咳嗽），减少诱发头痛与症状加重","术后 3、6、12 个月复查颅颈交界与脊髓 MRI（含 cine MRI 评估脑脊液流动）","合并睡眠呼吸暂停者行 CPAP 治疗","青少年定期测脊柱，监测侧弯进展；合并栓系者终身随访","出现突发呼吸困难、吞咽呛咳或肢体无力加重时立即就诊"]},"prog":"后颅窝减压术后约 70%–80% 的枕颈部疼痛缓解，空洞缩小者约 40%–60%；已有感觉丧失与肌萎缩多为不完全恢复。术后并发症（脑脊液漏、无菌性脑膜炎、假性脑膜膨出）约 5%–15%，10 年内再手术率约 5%–20%；病程长、弥漫性感觉障碍者预后较差。","refs":["《Chiari 畸形合并脊髓空洞症诊断与治疗中国专家共识》（中华医学会神经外科学分会脊柱脊髓学组，2018）","《Chiari 畸形 Ⅰ 型诊治中国专家共识》（2019）","《Chiari Malformation Type Ⅰ 国际共识指南》（2019）","《脊髓空洞症诊断与治疗中国专家共识》（2021）","《后颅窝减压术中国专家共识》（2022）"]}]},{"id":"ns_other","name":"其他神经外科疾病","rank":4,"summary":"其他神经外科疾病：先判断病因与可逆性，再选最小有效干预——脑积水按是否梗阻选 ETV 或 V-P 分流，三叉神经痛以卡马西平为一线、难治者行微血管减压，硬膜下血肿复发重点评估引流、脑复张与抗栓。","compare":[{"diseaseId":"ns_hydrocephalus","dx":"进行性头痛、呕吐、视乳头水肿，或步态障碍 + 认知减退 + 尿失禁三联征；CT/MRI 示脑室扩大（Evan 指数 >0.3），区分梗阻性与交通性，NPH 需放液试验阳性","key":"以「是否梗阻」决定 ETV 还是 V-P 分流；NPH 必须先证实对放液试验/腰大池引流有反应"},{"diseaseId":"ns_trigeminal","dx":"单侧三叉神经二、三支分布区突发闪电样剧痛，持续数秒至 2 min，有扳机点，间歇期完全无痛，查体无客观感觉缺损","key":"阵发性 + 扳机点 + 无感觉缺失是核心；卡马西平一线，药物难治者行微血管减压"},{"diseaseId":"ns_chiari","dx":"老年人或抗栓治疗者轻微外伤后数周至数月出现头痛、认知减退、肢体无力、步态不稳；CT 示颅骨内板下新月形低/混杂密度影","key":"引流后 3 个月内影像或症状再现即为复发；处理重点是引流是否充分、脑是否复张与抗栓是否持续"}],"diseases":[{"id":"ns_hydrocephalus","name":"脑积水","aka":["Hydrocephalus","梗阻性脑积水","交通性脑积水","正常压力脑积水","NPH"],"rank":1,"basic":{"define":"脑脊液分泌、循环或吸收障碍导致脑室系统（和/或蛛网膜下腔）脑脊液异常积聚、脑室扩大的病理状态：按是否梗阻分为梗阻性脑积水、交通性脑积水，以及脑室扩大但颅内压正常（NPH）的特殊亚型，治疗核心是恢复脑脊液通路或分流。","risk":["颅内肿瘤、囊肿、出血或感染（脑膜脑炎、蛛网膜下腔出血后粘连）","颅脑创伤后与脑室出血后（PVH-IVH）","早产儿与新生儿颅内出血后（儿童脑积水主因）","脑膜炎后与结核性脑膜炎（国内常见）","先天性中脑导水管狭窄、Chiari 畸形、Dandy-Walker 畸形","老年人 NPH（特发性，病因不明）"],"epi":"成人患病率约 1%–2%；创伤后约 10%–20%，SAH 后约 20%；>65 岁特发性 NPH 约 1%–3%。"},"patho":"脑脊液主要由侧脑室脉络丛分泌（约 500 mL/d），经室间孔→三脑室→中脑导水管→四脑室→正中孔与外侧孔进入蛛网膜下腔，经蛛网膜颗粒吸收。梗阻性（非交通性）脑积水见于导水管狭窄、四脑室出口阻塞或占位，脑室与蛛网膜下腔不连通，脑室高压与室旁白质间质水肿导致认知与运动障碍；交通性脑积水为蛛网膜下腔吸收障碍（出血/炎症后），脑室整体扩大。NPH 的脑室扩大但腰椎穿刺压正常，可能为脑脊液搏动压增高与脑顺应性下降，表现为步态障碍、认知障碍与尿失禁「三联征」，对分流有反应性。","dx":{"criteria":["梗阻性：头痛、呕吐、视乳头水肿伴意识改变；影像见脑室系统近端扩张而梗阻远端（第四脑室或外侧裂池）不扩张，四脑室正常或缩小提示中脑导水管梗阻，四脑室同时扩大提示出口梗阻","交通性：脑室整体扩大伴蛛网膜下腔扩张或脑沟消失，常继发于 SAH、脑膜炎或创伤（三联前注意术后/感染史）","NPH：典型三联征（步态不稳起步困难、可呈磁吸步态；认知下降以执行与注意障碍为主；急迫性尿失禁），颅内压正常；影像 Evan 指数（侧脑室额角最大宽度/颅骨内板间最大距离）>0.3、侧脑室颞角扩大、顶盖角 <90°、外侧裂与脑沟不成比例扩大（DESH 征）","脑脊液放液试验（tap test）：腰穿放液 30–50 mL 后 24 h 内评估步态与认知，改善者分流获益概率较高；阴性者可做 3–5 d 腰大池外引流试验","鉴别需排除脑萎缩（ex vacuo 脑室扩大）、阿尔茨海默病与帕金森病","儿童脑积水见头围进行性增大、前囟隆起与落日眼"],"workup":["头颅 CT：脑室大小、Evan 指数、室旁间质水肿（额角周围低密度）与梗阻部位，急诊首选","头颅 MRI（T1/T2/FLAIR、DWI、稳态自由进动序列）：判断导水管狭窄、占位、Chiari 畸形与脑室壁水肿，为术前必需","NPH：腰穿测压（正常 6–25 cmH₂O 或 60–240 mmH₂O）、放液试验与改良步态评分（10 米步行时间与步数）、MMSE/MoCA 评估","腰大池外引流试验（连续 3–5 d 引流 10–15 mL/h）评估分流反应性，尤其放液试验模棱两可者","脑室/腰大池穿刺与脑脊液常规、生化、细胞学与病原学（排除感染性）","术后随访 CT/MRI 与分流装置功能评估（泵压试验、X 线片）"],"grading":"按病因与梗阻部位分：梗阻性（非交通性）、交通性、NPH（特发性/继发性）、外部性脑积水与代偿性（ex vacuo）脑室扩大（无需分流）。NPH 常用分级参考：改良 Rankin 量表与步态评分；影像评分参考 DESH 征与 Evan 指数。"},"ddx":[{"name":"三叉神经痛（ns_trigeminal）","point":"与本类 ns_trigeminal 的鉴别点：脑积水以头痛呕吐、视乳头水肿与脑室扩大为主；三叉神经痛为阵发性面部放电样疼痛，无颅压升高与脑室扩大。"},{"name":"慢性硬膜下血肿复发处理（ns_chiari）","point":"与本类 ns_chiari 的鉴别点：脑积水为脑室系统扩大、无硬膜下积血；CSDH 为硬膜下新月形积血伴中线移位，二者可并存（分流过度引流）。"},{"name":"脑萎缩（ex vacuo 脑室扩大）","point":"脑沟与脑室同步扩大、DESH 征阴性、放液试验无改善，以认知全面下降为主，不应行分流。"},{"name":"帕金森病","point":"静止性震颤、肌强直与左旋多巴反应性，步态为小碎步而非磁吸式；DESH 征阳性支持 NPH。"},{"name":"腰椎管狭窄（神经源性跛行）","point":"间歇性跛行与弯腰缓解、下肢放射痛，腰椎 MRI 见椎管狭窄；NPH 步态不稳不随姿势明显改变，影像以脑室扩大为主。"}],"tx":{"drug":[{"name":"乙酰唑胺（药物辅助）","dose":"遵说明书；成人常用 250 mg 口服 bid–qid，国内经验有限，短期用于等待手术或手术禁忌者","note":"减少脉络丛分泌，仅作过渡，不能替代分流；监测血钾与肾结石风险","renal":"肾功能不全慎用；结石史者禁用","hepatic":"遵说明书","interact":"与地高辛合用加重低钾血症；与锂剂合用增加锂中毒风险"},{"name":"甘露醇（急性颅高压）","dose":"0.25–1 g/kg 静脉滴注，15–30 min 滴完，q4–6h 按需重复","note":"仅用于脑疝危象或术前过渡；不用于 NPH 长期治疗","renal":"肾功能不全慎用或改用高渗盐水","hepatic":"遵说明书","interact":"与肾毒性药物合用增加急性肾损伤"},{"name":"氯沙坦","dose":"50–100 mg qd（部分试验用量）","note":"证据有限、非指南推荐；仅用于合并高血压者的对症降压，不替代分流","renal":"eGFR <30 需评估；高钾与低血压风险","hepatic":"重度肝功能不全减量","interact":"与保钾利尿剂、ACEI 合用增加高钾血症风险"}],"nonDrug":["梗阻性：首选内镜下第三脑室底造瘘术（ETV），适用于导水管狭窄、四脑室出口梗阻且脑室底解剖可行者；失败率约 10%–30%","交通性脑积水与 NPH：脑室-腹腔分流（V-P，可调压阀门）为标准方案；NPH 术前需放液试验或腰大池引流反应良好，术后 1 年约 70%–80% 步态改善","急性梗阻伴脑疝/昏迷：先急诊脑室外引流（EVD）稳定颅压，再处理病因（肿瘤切除、ETV）","分流失败或反复感染：可改 ETV 或脑室-心房分流；感染时拔除分流管 + 外引流 + 抗感染后再植入","过度引流并发症（硬膜下积液/血肿、裂隙脑室综合征）：调高分流阀压力或更换可调压阀门","儿童：梗阻性优先 ETV ± 脉络丛凝固；交通性需终身分流随访"],"life":["随身携带分流卡，了解阀门类型与压力设定；可调压阀门者避免强磁场","出现头痛呕吐、发热、切口红肿、腹部疼痛或意识改变时，警惕分流感染与梗阻，立即就医","NPH 患者出院后 3、6、12 个月复查步态评分与影像，评估是否需调整阀门压力","防跌倒与认知训练；避免用力排便、剧烈咳嗽与头部外伤","儿童定期测量头围并评估发育，青年期注意分流管长度与活动限制"]},"prog":"梗阻性脑积水 ETV 后 1 年成功率约 70%–80%，无分流管感染风险但失败需再处理；NPH 分流术后 1 年约 70%–80% 步态改善、约 50%–60% 认知改善，症状持续 >5 年者获益有限。分流感染率约 3%–10%，分流障碍 1 年内约 10%–20%，儿童更高；合并肿瘤或严重脑损伤者预后取决于原发病。","refs":["《中国脑积水诊疗指南》（中华医学会神经外科学分会，2019）","《成人正常压力脑积水诊治中国专家共识》（中华医学会神经外科学分会，2018）","《儿童先天性脑积水诊疗专家共识》（中国医师协会神经外科医师分会，2020）","《Guidelines for Management of Idiopathic Normal Pressure Hydrocephalus》（国际 NPH 指南第 4 版，2015）","《脑积水影像评估中国专家共识》（2020）"]},{"id":"ns_trigeminal","name":"三叉神经痛","aka":["原发性三叉神经痛","Trigeminal Neuralgia","TN","痛性抽搐"],"rank":2,"basic":{"define":"局限于三叉神经一支或多支分布区的阵发性、电击样剧痛，常由触碰、咀嚼、说话等非伤害性刺激诱发（扳机点）；多数由血管（多为小脑上动脉）在神经根进入区（REZ）压迫引起脱髓鞘与异常放电（经典型），少数继发于桥小脑角肿瘤或多发性硬化。","risk":["中老年女性（50–70 岁，女:男约 1.5–2:1）","高血压、动脉硬化致血管迂曲","多发性硬化（年轻患者需警惕）、桥小脑角肿瘤或蛛网膜囊肿","牙齿与口腔病灶常被误认牙痛而导致不必要的牙科治疗"],"epi":"年发病率约 4–13/10 万，患病率约 0.03%–0.3%，高峰 50–60 岁。"},"patho":"随年龄增长迂曲扩张的动脉（多为小脑上动脉）在神经根进入区搏动性压迫，使神经轴突脱髓鞘、相邻轴突间形成异常电接触（ephapse），轻微的触觉刺激被放大为异位放电，形成阵发性剧痛；长期压迫导致进行性脱髓鞘与中枢敏化。继发性者由肿瘤或炎症斑块压迫所致，去除病因后疼痛可缓解。","dx":{"criteria":["疼痛位于三叉神经一支或多支分布区（V1 眼支、V2 上颌支、V3 下颌支），单侧，极少双侧同时发生","阵发性、电击样、刀割样或针刺样剧痛，持续数秒至 2 min，间歇期完全无痛，有明确扳机点（刷牙、洗脸、咀嚼、说话可诱发）","查体无客观感觉缺失；出现持续麻木、角膜反射消失者须行增强 MRI 排除继发性病因","发病年龄 <40 岁或有神经缺损者，必须评估多发性硬化与桥小脑角占位","卡马西平试验性治疗显著缓解支持诊断"],"workup":["头颅 MRI 增强 + 高分辨 3D-TOF/3D-CISS 序列：评估神经血管压迫、桥小脑角占位与脱髓鞘斑块","口腔科与耳鼻喉科检查排除牙源性疼痛与鼻窦炎","卡马西平用药前行 HLA-B*1502 检测、肝肾功能与电解质，用药期间监测血钠","疼痛日记、NRS 评分与生活质量量表作为基线与随访","拟行 MVD 者行 MRA/CTA 评估责任血管与神经关系，并完成麻醉评估"],"grading":"按 ICHD-3 分为经典型（影像证实血管压迫）、继发性（肿瘤、多发性硬化）与特发性；术后疼痛结局采用巴罗神经学研究所（BNI）分级：Ⅰ 无痛不服药，Ⅱ 无痛偶尔服药，Ⅲ 药物控制下部分缓解，Ⅳ 无缓解，Ⅴ 加重。"},"ddx":[{"name":"脑积水（ns_hydrocephalus）","point":"与本类 ns_hydrocephalus 的鉴别点：三叉神经痛为阵发性面部放电样疼痛、间歇期完全无痛、无颅压升高；脑积水以头痛呕吐、视乳头水肿与脑室扩大为主。"},{"name":"慢性硬膜下血肿复发处理（ns_chiari）","point":"与本类 ns_chiari 的鉴别点：CSDH 为持续头痛、认知减退与局灶体征，CT 见硬膜下新月形积血；三叉神经痛影像无颅内占位改变。"},{"name":"牙源性疼痛","point":"局限于特定牙位、持续性钝痛或咬合痛，冷热刺激与叩痛阳性，口腔影像见龋坏或根尖病变；三叉神经痛为阵发性且扳机点在口周软组织。"},{"name":"带状疱疹后神经痛","point":"皮疹愈合后持续烧灼样疼痛 >3 个月，伴痛觉过敏与感觉减退，多累及 V1 支；有三叉神经区带状疱疹病史。"},{"name":"颞下颌关节紊乱","point":"咀嚼时耳前区疼痛伴关节弹响与张口受限，无电击样发作与精确扳机点。"},{"name":"丛集性头痛","point":"眶周剧痛伴结膜充血、流泪、鼻塞，持续 15–180 min 且呈周期性。"}],"tx":{"drug":[{"name":"卡马西平","dose":"起始 100 mg 口服 bid，每 1–2 d 加 100–200 mg，常用维持 400–800 mg/d 分 2–4 次，最大不超过 1200 mg/d，血药浓度 4–12 μg/mL","note":"一线药物，有效率约 70%–80%；用药前建议 HLA-B*1502 检测，出现皮疹立即停药；每半年复查肝酶与血钠","renal":"肾功能不全者减量","hepatic":"肝功能不全者慎用并监测","interact":"强 CYP3A4 诱导剂，降低口服避孕药、华法林及其他抗癫痫药浓度"},{"name":"奥卡西平","dose":"起始 300 mg 口服 bid，每 3–5 d 加 300 mg，维持 600–1200 mg/d 分 2 次","note":"卡马西平不耐受或疗效不佳者的替代；注意低钠血症，监测血钠；皮疹风险仍存在","renal":"CrCl <30 减量","hepatic":"严重肝功能不全减量","interact":"CYP3A4 诱导剂，可降低避孕药效果"},{"name":"A 型肉毒毒素（局部注射）","dose":"遵说明书；面部受累区域皮内/皮下多点注射，每 12–16 周一次，由有经验的医师操作","note":"药物难治或不能耐受者可选；避免与影响神经肌肉传导的药物合用","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与氨基糖苷类等影响神经肌肉传导的药物合用"}],"nonDrug":["微血管减压术（MVD）：药物难治或无法耐受者的首选术式，乙状窦后入路显微镜下以垫片隔离责任血管（多为小脑上动脉）与三叉神经根；术后即刻完全缓解率 80%–90%，10 年仍保持约 70%","MVD 术前须有 MRI 证实的神经血管压迫；风险包括听力下降、面瘫与脑脊液漏，应在有经验中心实施","高龄或不能耐受开颅者：经皮三叉神经半月节球囊压迫（PBC）或射频热凝，1 年有效率约 70%–80%，但面部感觉减退与复发风险较高，可重复治疗","立体定向放射外科（伽马刀）：神经根靶点 70–90 Gy，适用于高龄或不能开颅者，5 年缓解率约 50%–60%","继发性（肿瘤、多发性硬化）三叉神经痛先处理原发病；多发性硬化相关者以药物治疗为主"],"life":["进食温软、用健侧咀嚼，洗漱动作轻柔，避开扳机点","服药期间避免饮酒与驾驶（卡马西平致头晕、嗜睡与共济失调）","妊娠期用药须神经内科与产科共同评估","术后 1、6、12 个月复诊评估疼痛缓解与并发症；V1 支受累者定期眼科检查角膜","出现皮疹、发热或明显乏力时立即停药就医（警惕重症药疹与粒细胞缺乏）"]},"prog":"药物治疗初期约 70%–80% 有效，但约 30%–50% 在数年内出现剂量耐受与疗效下降；微血管减压术 10 年有效率约 70%；球囊压迫与射频的 1 年有效率约 70%–80%，可重复治疗。发病年龄 <40 岁或伴感觉障碍者预后取决于病因。","refs":["《三叉神经痛诊疗中国专家共识》（中华医学会神经外科学分会功能神经外科学组，2015）","《原发性三叉神经痛诊断和治疗中国专家共识》（2019）","《微血管减压术治疗三叉神经痛中国专家共识》（2021）","国际头痛疾病分类第 3 版（ICHD-3，2018）","《三叉神经痛药物治疗中国专家共识》（2020）"]},{"id":"ns_chiari","name":"慢性硬膜下血肿复发处理","aka":["复发性慢性硬膜下血肿","Recurrent Chronic Subdural Hematoma","rCSDH","CSDH 复发"],"rank":3,"basic":{"define":"慢性硬膜下血肿（CSDH）经钻孔引流或保守治疗后，同一侧硬膜下再次出现症状性血肿或液体积聚（多在术后 3 个月内，影像示血肿厚度增加或残腔不缩小并伴中线移位与症状复现），称为复发性慢性硬膜下血肿，是需二次手术干预的主要原因。","risk":["年龄 >70 岁、脑萎缩显著（脑复张差）","混合/等密度血肿、双侧血肿、血肿厚度 >15 mm","持续或过早恢复抗凝/抗血小板治疗","引流不充分、术后残余积气、硬膜下积液","酒精依赖、肝功能异常、透析与反复跌倒"],"epi":"CSDH 引流后临床复发率约 10%–20%，再复发率约 20%–30%。"},"patho":"CSDH 腔内存在纤溶亢进与炎症正反馈（外膜新生毛细血管渗漏、纤溶酶与 D-二聚体升高），使血肿反复扩大。钻孔引流仅解除占位，血肿腔与炎症外膜仍然残留；若脑复张不足（脑萎缩、术后过早下床、硬膜下积气）则残腔持续存在，持续抗栓或凝血障碍则腔壁毛细血管再出血。复发与「引流是否彻底、硬膜下腔是否闭合、抗栓状态是否纠正」三要素相关。","dx":{"criteria":["有 CSDH 钻孔引流或保守治疗史，术后随访期内症状再现：头痛、进行性肢体无力、反应迟钝、步态不稳、尿失禁或意识下降","复查头颅 CT 示原部位或邻近硬膜下新月形低/混杂密度积血，厚度 >10 mm 或中线移位 >5 mm，或残腔不缩小并反复增大","区分临床复发（症状再现需再手术）与影像复发（厚度增加而症状轻）","按时间分：术后 3 个月内为早期复发（多见于引流不充分与抗栓），>3 个月为晚期复发（脑复张差与持续抗栓）","须排除术后急性硬膜下血肿、硬膜下脓肿、张力性气颅与低颅压综合征"],"workup":["头颅 CT 平扫并与术前对比，测量最大厚度、中线移位、密度与分隔情况","MRI（T1/T2、DWI）鉴别等密度复发血肿、硬膜下积液与脓肿（DWI 弥散受限）","凝血功能、血常规、肝肾功能、INR、抗 Xa 活性或达比加群浓度，明确抗栓药物残留","评估脑复张：术后 CT 显示脑表面与内板间残腔；长期不复张者考虑腰大池引流或脑室腹腔分流","反复复发者行 CTA/MRA 排除硬脑膜动静脉瘘、脑膜中动脉异常供血","合并癫痫者行脑电图评估"],"grading":"按复发类型（影像复发、临床复发）；按 CT 密度（混杂/分层者复发高危、等密度、低密度）；临床严重度用 Markwalder 分级（0–Ⅳ）；影像形态可用 Nakaguchi 分型（均质型、层状型、分离型、小梁型）预测复发。"},"ddx":[{"name":"脑积水（ns_hydrocephalus）","point":"与本类 ns_hydrocephalus 的鉴别点：复发性 CSDH 有明确血肿史与硬膜下新月形积血、中线移位；脑积水为脑室系统扩大、无硬膜下积血。"},{"name":"三叉神经痛（ns_trigeminal）","point":"与本类 ns_trigeminal 的鉴别点：CSDH 为持续头痛伴局灶体征与认知改变、CT 见硬膜下积血；三叉神经痛为阵发性面部电击样疼痛、影像无占位。"},{"name":"术后硬膜下积液（水瘤）","point":"CT 呈均匀脑脊液密度、无液平，多可自行吸收；若占位效应明显并伴症状加重，需与复发血肿鉴别，可随访 MRI 观察密度变化。"},{"name":"术后颅内感染/硬膜下脓肿","point":"发热、切口渗液与意识改变，MRI 弥散受限伴环形强化，炎症指标升高；需拔管引流并抗感染，而非再次钻孔。"},{"name":"低颅压综合征","point":"直立时头痛加重、平卧缓解，MRI 见硬膜强化与静脉窦扩张；与过度引流或脑脊液漏有关，处理为补液、卧床与硬膜外血贴。"},{"name":"急性缺血性卒中/短暂性脑缺血","point":"突发局灶缺损、CT 见血管分布区低密度，无新月形积血；恢复抗栓前须影像排除血肿。"}],"tx":{"drug":[{"name":"氨甲环酸","dose":"500 mg 口服 q8h，疗程 7–21 d；复发高危者遵医嘱延长至 1–3 个月","note":"抑制血肿腔纤溶亢进以降低复发；须评估血栓栓塞风险，与抗栓药配合时需多学科决策","renal":"CrCl <30 减量或延长给药间隔","hepatic":"遵说明书","interact":"与其他促凝/抗纤溶药合用需监测血栓"},{"name":"阿托伐他汀","dose":"20 mg 口服 qn，疗程 4–12 周","note":"国内研究提示可促进血肿吸收、降低复发，为辅助用药而非手术替代；监测肝酶与肌痛","renal":"无需调整","hepatic":"活动性肝病禁用，ALT/AST >3 倍上限停用","interact":"与克拉霉素、伊曲康唑等 CYP3A4 抑制剂合用增加肌病风险"},{"name":"地塞米松","dose":"4–8 mg 口服/静脉 q12h，短期 3–5 d，症状缓解后快速减量停药","note":"仅围手术期短期减轻脑水肿或用于不宜手术的轻症；长期使用增加感染、高血糖与复发风险","renal":"遵说明书","hepatic":"严重肝病者代谢减慢","interact":"与降糖药、抗凝药、抗癫痫药相互作用"},{"name":"凝血酶原复合物（4 因子）","dose":"25–50 IU/kg 静脉滴注，按 INR 调整，目标 INR ≤1.4；配合维生素 K1 10 mg 静脉缓慢注射","note":"用于华法林相关复发出血的紧急逆转","renal":"遵说明书","hepatic":"严重肝病者剂量需个体化","interact":"与抗凝药作用相互拮抗"},{"name":"左乙拉西坦","dose":"500 mg 口服 q12h，必要时 1000 mg 负荷；有发作史者长期使用","note":"用于合并癫痫发作者；单纯预防复发证据不足","renal":"按 CrCl 调整","hepatic":"重度肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"}],"nonDrug":["再次钻孔引流指征：血肿厚度 >10 mm、中线移位 >5 mm 或症状明显；于血肿最厚处钻孔（可双孔），充分冲洗至引流液清亮并留置引流 24–48 h","促进脑复张：术后头低平卧（床头 <10°）24–48 h、充分补液、避免过度引流与残余积气","反复复发者：内镜下血肿腔清除、开颅血肿清除 + 硬膜扩大修补，或行脑膜中动脉栓塞（MMAE）降低复发","脑复张不良或持续硬膜下积液：腰大池引流 5–7 d，必要时脑室-腹腔分流","抗栓药物管理：影像稳定后 2–4 周恢复；动脉血栓高危者（近期支架、机械瓣）与心内科共同制定桥接方案"],"life":["出院后 1–3 个月防跌倒、防头部撞击，避免用力咳嗽与便秘","营养支持与康复训练（步态、认知），控制血压与血糖","家属宣教：头痛加重、反应变差、肢体无力或呕吐时立即复诊复查 CT","长期抗栓者建立用药与复查计划，不得自行停药或加药","戒酒；酒精依赖者需干预，否则复发风险高"]},"prog":"复发后再次钻孔引流约 70%–80% 症状改善，但再复发率约 20%–30%；脑膜中动脉栓塞可明显降低再手术率。持续抗栓、脑萎缩严重与炎症外膜残留者复发风险高；术前昏迷（Markwalder Ⅳ）者死亡风险显著升高。","refs":["《慢性硬膜下血肿诊断与治疗中国专家共识》（中华医学会神经外科学分会，2021）","《慢性硬膜下血肿复发的预防与处理中国专家共识》（2019）","《英国神经外科慢性硬膜下血肿管理指南》（2020）","《脑膜中动脉栓塞治疗慢性硬膜下血肿中国专家共识》（2022）","《慢性硬膜下血肿围手术期管理中国专家共识》（2021）"]}]},{"id":"ns_tumor_more","name":"颅内肿瘤（垂体、听神经、颅咽管、转移瘤）","rank":5,"summary":"鞍区、桥小脑角与转移瘤一类，共同点是影像定性加内分泌/颅神经评估，以手术或局部放疗为主；鞍区肿瘤先查激素，桥小脑角肿瘤先评估听面功能，转移瘤按 RPA/GPA 分层决定 SRS、手术或全脑放疗。","compare":[{"diseaseId":"ns_pituitary","dx":"鞍内占位伴内分泌异常（泌乳素瘤、肢端肥大、库欣病），MRI 见垂体柄偏移与微腺瘤低强化","key":"单一激素高分泌，视野双颞侧偏盲"},{"diseaseId":"ns_acoustic","dx":"单侧进行性听力下降伴耳鸣，MRI 见内听道内类圆形强化结节、内听道扩大","key":"桥小脑角占位，NF2 者双侧"},{"diseaseId":"ns_craniopharyngioma","dx":"鞍上囊实性占位伴钙化，儿童以颅高压与矮小起病，成人以视野缺损与性功能减退起病","key":"钙化囊性、年龄双峰、下丘脑症状"},{"diseaseId":"ns_brain_met","dx":"已知原发肿瘤者出现多发灰白质交界强化结节伴明显水肿","key":"多发灶加强水肿，有原发病史"}],"diseases":[{"id":"ns_pituitary","name":"垂体腺瘤","aka":["Pituitary Adenoma","垂体瘤","泌乳素瘤 Prolactinoma","生长激素瘤 GH Adenoma","ACTH 瘤"],"rank":1,"basic":{"define":"起源于腺垂体细胞的良性单克隆肿瘤，按大小分微腺瘤（<10 mm）与大腺瘤（≥10 mm），按功能分泌乳素瘤、生长激素瘤、ACTH 瘤、TSH 瘤与无功能性腺瘤。","risk":["多为散发，无明确环境危险因素","MEN1、AIP 突变、家族性孤立性垂体腺瘤为遗传背景","育龄女性与不明原因闭经泌乳者需警惕"],"epi":"占颅内肿瘤 10%–15%，尸检发现率 10%–20%；泌乳素瘤占功能性腺瘤约 40%–50%，女性高峰 20–50 岁。"},"patho":"腺瘤细胞单一克隆增殖，造成鞍区占位与激素高分泌。超过 10 mm 可压迫视交叉致双颞侧偏盲，压迫正常垂体致功能减退；侵入海绵窦可累及眼外肌与三叉神经眼支。泌乳素过多抑制 GnRH 致闭经泌乳，生长激素过多致肢端肥大，ACTH 过多致皮质醇增多。大腺瘤可发生瘤内出血（垂体卒中）。","dx":{"criteria":["泌乳素瘤：泌乳素 >200 ng/mL 高度提示大腺瘤，>250 ng/mL 基本确诊；100–200 ng/mL 需结合增强 MRI（巨大腺瘤可因垂体柄效应假性升高，一般 <150 ng/mL）","生长激素瘤：75 g 口服葡萄糖后 GH 不能抑制至 <1.0 ng/mL，且 IGF-1 高于同龄正常上限","ACTH 瘤：皮质醇昼夜节律消失、24 h 尿游离皮质醇升高、过夜 1 mg 及小剂量地塞米松抑制试验不被抑制，大剂量抑制试验被抑制","视力视野：双颞侧偏盲提示视交叉受压","垂体功能减退：晨 8 点皮质醇、FT4、睾酮/雌二醇与 FSH/LH 减低"],"workup":["鞍区增强 MRI 薄层（2–3 mm）冠状位重建，评估大小、海绵窦侵犯（Knosp 分级）与视交叉关系","基础激素全套：泌乳素、GH、IGF-1、ACTH、皮质醇、TSH、FT4、FSH/LH、性激素","视力、视野与眼底","怀疑库欣病且 MRI 阴性时行岩下窦静脉取血（BIPSS）","排除药物性高泌乳素（抗精神病药、甲氧氯普胺、质子泵抑制剂）与原发性甲减、肾功能不全"],"grading":"大小：微腺瘤 <10 mm、大腺瘤 10–40 mm、巨大腺瘤 ≥40 mm；Knosp 0–4 级评估海绵窦侵犯；功能性/无功能性分类。"},"ddx":[{"name":"颅咽管瘤","point":"与本类中颅咽管瘤的鉴别点：颅咽管瘤位于鞍上、囊实性并常伴钙化，表现为垂体-下丘脑轴多激素减退；垂体腺瘤以单一激素高分泌为主。"},{"name":"Rathke 裂囊肿","point":"纯囊性、无钙化与强化实性成分，多无症状。"},{"name":"淋巴细胞性垂体炎","point":"多见于妊娠晚期或产后，垂体弥漫增粗强化，常伴尿崩，可自限或需激素。"},{"name":"鞍结节脑膜瘤","point":"宽基底、脑膜尾征，多无内分泌异常。"},{"name":"视神经胶质瘤","point":"儿童多见，沿视神经梭形增粗，常合并 NF1。"}],"tx":{"drug":[{"name":"卡麦角林（泌乳素瘤首选）","dose":"起始 0.25–0.5 mg 口服 每周 1–2 次，按泌乳素每 4 周滴定，常用维持 0.5–2 mg/周","note":"约 80%–90% 患者泌乳素正常，大腺瘤约 2/3 缩小 ≥50%；妊娠期多可停药监测","renal":"重度肾功能不全慎用，遵说明书","hepatic":"重度肝损害慎用，遵说明书","interact":"避免与大环内酯类、强 CYP3A4 抑制剂及抗精神病药合用；注意体位性低血压与冲动控制障碍"},{"name":"溴隐亭","dose":"起始 1.25 mg 睡前，渐加至 2.5–7.5 mg/d 分次口服","note":"卡麦角林不可及时使用，胃肠道反应较重","renal":"遵说明书","hepatic":"遵说明书","interact":"与红霉素类、抗精神病药合用相互作用增加"},{"name":"奥曲肽长效制剂（生长激素瘤辅助）","dose":"20 mg 肌内注射 每 4 周 1 次，按 IGF-1 调至 10–30 mg","note":"不能手术或术后未缓解者使用，GH 需控制到随机 <1.0 ng/mL 且 IGF-1 正常","renal":"遵说明书","hepatic":"遵说明书","interact":"可降低环孢素吸收；注意胆结石与血糖异常"},{"name":"培维索孟（Pegvisomant）","dose":"负荷 80 mg 皮下，后 10–20 mg/d，按 IGF-1 滴定","note":"生长激素受体拮抗剂，IGF-1 正常率 70% 以上；须监测肝酶与瘤体","renal":"遵说明书","hepatic":"肝功能不全者禁用","interact":"注意监测转氨酶与肿瘤体积"},{"name":"酮康唑（ACTH 瘤术前或术后未缓解）","dose":"200–400 mg 每日 2 次口服，按皮质醇滴定","note":"抑制类固醇合成，须监测肝功能","renal":"遵说明书","hepatic":"肝损害者禁用或减量","interact":"强 CYP3A4 抑制剂，与苯妥英、利福平、抗凝药相互作用显著"}],"nonDrug":["经鼻内镜经蝶入路切除：微腺瘤、Knosp 0–2 级大腺瘤首选；无功能腺瘤伴视野缺损或 ≥20 mm、功能性腺瘤药物不能控制时手术","开颅/眉弓入路：巨大或明显向前颅窝、眉间扩展、鼻腔条件差者","生长激素瘤：经蝶手术为主要手段，微腺瘤缓解率 70%–80%，侵袭性大腺瘤明显下降，术后不缓解加用生长抑素类似物或放疗","ACTH 瘤：首选经蝶手术，复发者选双侧肾上腺切除（尼尔森综合征风险）、放疗或药物","立体定向放疗/伽玛刀：术后残留或复发者，须距视交叉 ≥3 mm，起效需 2–5 年"],"life":["术后 6–12 周及每次随访复查激素与鞍区 MRI","垂体功能减退者长期替代并定期评估","避免剧烈运动与憋气，警惕垂体卒中"]},"prog":"微腺瘤经蝶手术缓解率 80%–90%，大腺瘤 40%–70%，侵袭性者复发率可达 20%–30%。生长激素瘤控制达标后心血管与代谢并发症风险显著下降；ACTH 瘤长期缓解率约 65%–90%。","refs":["中国垂体腺瘤诊治专家共识（2021）","中国肢端肥大症诊治共识（2021）","库欣综合征诊断与治疗中国专家共识（2015）","The Endocrine Society Pituitary Incidentaloma Guideline 2011"]},{"id":"ns_acoustic","name":"听神经瘤（前庭神经鞘瘤）","aka":["Vestibular Schwannoma","Acoustic Neuroma","前庭神经鞘瘤"],"rank":2,"basic":{"define":"起源于前庭神经施万细胞的良性肿瘤，位于桥小脑角区，占该区肿瘤的 80%–90%；双侧者提示 2 型神经纤维瘤病（NF2）。","risk":["多为散发，占颅内肿瘤 6%–8%","NF2 基因（22q12）胚系突变者双侧发病","高剂量头颈部放疗史为可疑因素"],"epi":"年发病率约 1–2/10 万，发病高峰 40–60 岁，女性略多；随 MRI 普及微小瘤明显增多。"},"patho":"肿瘤自内听道向外生长，压迫耳蜗神经致感音神经性聋，推挤面神经致轻瘫，体积增大后压迫三叉神经、小脑与脑干。生长缓慢，平均每年 1–2 mm，部分可自行停止生长。巨大者可致脑积水和脑疝。","dx":{"criteria":["单侧感音神经性聋伴耳鸣，或突发性聋中约 1%–3% 由听神经瘤引起","纯音测听呈单侧或不对称感音神经性聋，言语识别率下降与听力损失不成比例最具提示意义","听觉脑干反应示Ⅰ–Ⅴ波间潜伏期延长","增强 MRI 示以内听道为中心的实性明显强化结节，内听道扩大呈喇叭口样（冰激凌凝锥征），为诊断金标准","NF2 诊断需双侧前庭神经鞘瘤，或一侧肿瘤加一级亲属患病"],"workup":["MRI 平扫+增强（薄层 3 mm 内耳道重建），测量最大径与内听道内延伸","纯音测听、言语分辨测试","面神经 House-Brackmann 分级与三叉神经功能评估","儿童及怀疑 NF2 者查全脊髓 MRI、眼底与皮肤，必要时基因检测","观察者每 6–12 个月 MRI 评估生长速度"],"grading":"Koos 分级：Ⅰ 内听道内，Ⅱ ≤20 mm，Ⅲ >20 mm 压迫脑干，Ⅳ >30 mm 并移位；AAO-HNS 听力 A–D 级评估听力保存可能。"},"ddx":[{"name":"垂体腺瘤","point":"与本类中垂体腺瘤的鉴别：鞍区占位以视力视野与激素异常为主；听神经瘤在桥小脑角，以听力下降与面神经症状为主。"},{"name":"桥小脑角脑膜瘤","point":"宽基底贴岩骨、有脑膜尾征、T2 信号中等；听神经瘤以内听道为中心并使之扩大。"},{"name":"表皮样囊肿","point":"ADC 显著受限、T1 低信号、无强化，包绕神经血管。"},{"name":"面神经鞘瘤","point":"沿面神经走行，伴面肌抽动；听力多正常。"},{"name":"桥小脑角转移瘤","point":"有原发病史、发展快、水肿明显，常伴颅内另病灶。"}],"tx":{"drug":[{"name":"泼尼松（仅合并突发聋时）","dose":"1 mg/kg/d 口服，一日不超过 60 mg，5–7 d 后递减","note":"对听神经瘤本身无治疗作用，不能缩小肿瘤","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他激素合用增加感染风险"},{"name":"贝伐珠单抗（NF2 疗效试验性用药）","dose":"5–7.5 mg/kg 每 2–3 周静脉滴注，按疗效与不良反应调整","note":"部分 NF2 患者听力与肿瘤体积改善，为超说明书/试验用法，须多学科讨论","renal":"遵说明书","hepatic":"遵说明书","interact":"注意出血、高血压与蛋白尿"}],"nonDrug":["观察随访：Koos Ⅰ 级或 <15 mm 且无症状或高龄者，每 6–12 个月 MRI","显微外科切除：Koos Ⅲ–Ⅳ 级、脑干受压或脑积水、随访快速生长；乙状窦后入路，面神经功能保留 HB Ⅰ–Ⅱ 级约 60%–80%，<2 cm 者听力保存可达 50%–70%","立体定向放射外科（伽玛刀）：≤2.5–3 cm 的残余或复发及高龄不耐受手术者，5 年肿瘤控制率 90%–95%","分次立体定向放疗：大于 3 cm 不宜手术者","伴脑积水者先行脑室-腹腔分流或三脑室造瘘"],"life":["随访中评估听力、面神经与三叉神经功能","NF2 患者家族筛查与生育咨询","放疗后 1 年内每 6 个月 MRI，后每年 1 次"]},"prog":"观察 3–5 年约 1/3 稳定、1/3 缓慢生长、1/3 增大。显微切除后 5 年复发率 5%–10%，伽玛刀后约 5%。延误诊断是术后听力与面神经功能下降的主要原因。","refs":["听神经瘤诊断与治疗中国专家共识（2019）","NF2 相关前庭神经鞘瘤管理国际共识（2018）","American Academy of Otolaryngology Vestibular Schwannoma Guideline 2012"]},{"id":"ns_craniopharyngioma","name":"颅咽管瘤","aka":["Craniopharyngioma","牙釉质型颅咽管瘤","乳头型颅咽管瘤"],"rank":3,"basic":{"define":"起源于 Rathke 囊残留上皮的良性胚胎残余肿瘤，位于鞍上或鞍内，分牙釉质型（ACP，多见于儿童、常伴钙化）与乳头型（PCP，多见于成人）。","risk":["发病呈儿童（5–14 岁）与成人（50–74 岁）双峰","无明确环境危险因素","牙釉质型与 CTNNB1 突变、乳头型与 BRAF V600E 突变相关"],"epi":"年发病率约 0.13–0.6/10 万；占儿童颅内肿瘤 5%–10%，为儿童鞍区最常见非神经上皮肿瘤。"},"patho":"肿瘤缓慢膨胀性生长，压迫视交叉、第三脑室前部与下丘脑，引起视力障碍、颅高压与下丘脑肥胖、嗜睡、食欲失控。囊液富含胆固醇结晶，破裂可致化学性脑膜炎。手术及肿瘤侵犯易致下丘脑-垂体轴功能紊乱与尿崩。","dx":{"criteria":["儿童：生长迟缓、肥胖、性发育迟缓、颅高压表现","成人：视力下降、双颞侧偏盲、性功能减退、多饮多尿","CT 见鞍上囊实性混杂密度病灶伴点状或蛋壳样钙化（牙釉质型约 70%–90%）","MRI 见鞍上囊实性占位，囊液 T1 可高可低、T2 高信号，实性部分强化","儿童须查 AFP、β-hCG 排除生殖细胞肿瘤"],"workup":["鞍区增强 MRI 薄层（矢状与冠状），明确下丘脑与视交叉关系","头颅 CT 评估钙化","全垂体激素全套与水盐代谢、尿比重","视力、视野与眼底","儿童查生长曲线与骨龄"],"grading":"按部位分鞍内型、鞍上型与脑室型；按下丘脑受累程度（BMI、MRI 包绕、功能缺失）评估切除程度；病理分 ACP 与 PCP。"},"ddx":[{"name":"垂体腺瘤","point":"与本类中垂体腺瘤的鉴别点：垂体腺瘤多自鞍内起病、极少钙化、以单一激素高分泌为主；颅咽管瘤往往为鞍上囊性伴钙化、多激素减退。"},{"name":"Rathke 裂囊肿","point":"纯囊性、无钙化、不强化，多无症状。"},{"name":"鞍区生殖细胞肿瘤","point":"儿童多见、尿崩早发，β-hCG/AFP 升高，MRI 多为强实性强化。"},{"name":"视路胶质瘤","point":"儿童多见、常合并 NF1，沿视束蔓延，T2 高信号无钙化。"},{"name":"脊索瘤","point":"以斜坡为中心、破坏骨质、T2 高信号分叶状。"}],"tx":{"drug":[{"name":"氢化可的松（术后替代）","dose":"10–12 mg/(m²·d) 分 2–3 次口服，应激时加倍","note":"术前确认垂体-肾上腺功能不全者先补激素；晨 8 点皮质醇 ≤100 μg/L 提示需替代","renal":"遵说明书","hepatic":"遵说明书","interact":"与利福平、苯妥英、抗凝药等相互作用"},{"name":"左甲状腺素","dose":"成人 1.6 μg/kg/d，老年或冠心病者 12.5–25 μg/d 起始渐加；儿童按年龄体重遵说明书","note":"先补糖皮质激素再补甲状腺素，以免诱发肾上腺危象","renal":"遵说明书","hepatic":"遵说明书","interact":"与铁剂、钙剂、质子泵抑制剂间隔 4 h 以上"},{"name":"去氨加压素（DDAVP）","dose":"儿童 5–10 μg 每日 2 次经鼻或 60–120 μg 口服分次；成人遵说明书","note":"从小剂量起始，避免水中毒与低钠血症","renal":"重度肾功能不全慎用，注意低钠","hepatic":"遵说明书","interact":"与利尿剂、卡马西平、氯丙嗪合用增强抗利尿作用"},{"name":"重组人生长激素（儿童 GH 缺乏）","dose":"0.025–0.05 mg/kg/d 每晚皮下注射，按 IGF-1 滴定","note":"确认 GH 缺乏后使用；怀疑肿瘤复发时暂缓","renal":"遵说明书","hepatic":"遵说明书","interact":"与糖皮质激素合用时需调整剂量"}],"nonDrug":["经鼻内镜扩大经蝶入路切除：鞍内及鞍上、无脑室扩大者首选","开颅入路：肿瘤大、侧向扩展、巨大钙化或经蝶难以达到者","下丘脑保护优先的次全切除：肿瘤包绕下丘脑的儿童，残余辅以放疗（3 年内进展率 50%–70%）","立体定向放疗：残余或复发、瘤体 2.5–3 cm 者，控制率 70%–90%","伴阻塞性脑积水者行脑室-腹腔分流"],"life":["终身内分泌随访，每 6–12 个月评估垂体功能与尿量","术后第 1 年每 3–6 个月 MRI，之后每年","下丘脑性肥胖需营养与体重管理"]},"prog":"全切后 5 年无复发生存约 70%–90%，但下丘脑损伤、肥胖与全垂体功能减退发生率升高；次全切加放疗约 60%–80%。肿瘤本身良性，终身复发与内分泌功能障碍是主要长期问题。","refs":["颅咽管瘤诊疗中国专家共识（2021）","European Society of Endocrinology Craniopharyngioma Guideline 2017"]},{"id":"ns_brain_met","name":"脑转移瘤","aka":["Brain Metastases","BM","颅内转移瘤"],"rank":4,"basic":{"define":"原发于颅外恶性肿瘤转移至脑实质、脑膜或颅骨的肿瘤，为成人最常见的颅内恶性肿瘤。","risk":["肺腺癌（约 40%–50%）、乳腺癌（15%–20%）、黑色素瘤（10%–15%）、结直肠癌、肾细胞癌","EGFR/ALK 阳性肺腺癌、三阴性或 HER2 阳性乳腺癌、BRAF 突变黑色素瘤风险更高","原发病灶未控制或广泛颅外转移"],"epi":"约 10%–30% 的成人肿瘤患者发生脑转移，肺癌占首位；尸检研究提示可达 20%–30%。"},"patho":"肿瘤细胞经血行播散穿破血脑屏障，好发于灰白质交界处（血管口径骤变处）。病灶引起明显血管源性水肿与血脑屏障破坏，出现颅高压与局灶缺损；多发灶使颅内压进一步升高。多数药物难以进入脑转移灶，故以局部治疗为主。","dx":{"criteria":["原发肿瘤史加新发头痛、癫痫、局灶缺损或认知改变","增强 MRI（3 mm 薄层）为金标准：灰白质交界强化结节，多伴明显瘤周水肿；≤5 mm 微转移需 3D 薄层序列","无 MRI 时增强 CT 替代，但 ≤5 mm 病灶灵敏度低","PET-CT 有助于鉴别单发转移与原发脑肿瘤","怀疑软脑膜转移时查脑脊液细胞学"],"workup":["全脑增强 MRI（T1 增强、T2 FLAIR、DWI）明确数目、部位与水肿","RPA 分层：KPS、年龄、原发灶是否控制、颅外转移数目","GPA 评分：年龄、KPS、颅外转移、脑转移数目（部分版本含分子分型）","分子检测（EGFR/ALK、HER2、BRAF）指导靶向或免疫治疗","多学科讨论局部治疗与全身治疗的顺序"],"grading":"GPA 0–4 分，0–1 分预后差、3.5–4 分预后好；RPA Ⅰ–Ⅲ 级，Ⅲ 级（KPS <70）预后最差。"},"ddx":[{"name":"垂体腺瘤","point":"与本类中垂体腺瘤的鉴别：垂体腺瘤位于鞍内、以激素异常与视野缺损为主；脑转移位于灰白质交界、常多发并有原发肿瘤史。"},{"name":"高级别胶质瘤","point":"多单发、不规则厚壁环形强化伴中心坏死；脑转移多位于灰白质交界、常多发。"},{"name":"原发性中枢神经系统淋巴瘤","point":"脑室周围均匀强化、弥散明显受限，激素后迅速缩小。"},{"name":"脑脓肿","point":"脓腔 DWI 显著高信号、环壁完整，伴发热等感染征象。"},{"name":"放射性坏死","point":"有放疗或 SRS 史，呈肥皂泡样强化，灌注 rCBV 低。"}],"tx":{"drug":[{"name":"地塞米松","dose":"有症状性水肿时 4–8 mg 静脉或口服 每 6 h，改善后渐减至停","note":"缓解瘤周水肿与颅高压；会影响 PET 与病理结果","renal":"遵说明书","hepatic":"遵说明书","interact":"与苯妥英、卡马西平、抗凝药合用需注意"},{"name":"左乙拉西坦（仅癫痫发作者）","dose":"起始 500 mg 口服 每日 2 次，可加至 1500 mg 每日 2 次","note":"不推荐常规预防性抗癫痫","renal":"CrCl 30–50 mL/min 减至 250–750 mg 每 12 h，<30 遵说明书","hepatic":"重度肝损害减量 50%","interact":"与丙戊酸合用注意血药浓度"},{"name":"分子靶向药物（按分型）","dose":"按病种方案（如 EGFR-TKI、ALK-TKI、HER2 阳性药物、BRAF+MEK 抑制剂），遵说明书","note":"EGFR/ALK 阳性肺腺癌无症状小脑转移可先行靶向，部分获颅内缓解","renal":"遵说明书","hepatic":"遵说明书","interact":"与 CYP3A4 诱导剂或抑制剂相互作用，遵说明书"}],"nonDrug":["立体定向放射外科（SRS）：1–4 个（部分中心至 10 个）转移灶、单灶 ≤3 cm、KPS ≥70，1 年局部控制率 70%–90%","手术切除：单发或可切的 2–3 个病灶、KPS ≥70、原发灶可控、有明显占位效应或需病理者；术后瘤床 SRS 可替代全脑放疗","全脑放疗（WBRT）：多发弥漫、无法局部治疗或复发挽救；常用 30 Gy/10 次或 20 Gy/5 次","分次立体定向放疗：>3 cm 或紧邻脑干、视交叉等敏感结构者","软脑膜转移：鞘内化疗、Ommaya 囊植入"],"life":["每 2–3 个月 MRI 随访至 2 年","记录 KPS 与神经系统功能基线","癫痫急救指导与认知康复"]},"prog":"GPA 0–1 分者中位生存约 2–3 个月，3.5–4 分者可达 11 个月以上；经手术或 SRS 治疗的单发脑转移中位生存 12 个月以上。复发高峰在治疗后 6–12 个月。","refs":["中国肺癌脑转移诊治专家共识（2017）","脑转移瘤外科与放射治疗中国专家共识（2021）","NCCN CNS Cancers Guidelines 2023"]}]},{"id":"ns_cerebro_other","name":"脑血管与感染（海绵状血管瘤、烟雾病、脑脓肿、面肌痉挛）","rank":6,"summary":"以异常血管、慢性低灌注、颅内感染与颅神经受压为核心：海绵状血管瘤反复少量出血形成爆米花样 MRI；烟雾病以颈内动脉末端闭塞加烟雾状侧支为特征，需血运重建；脑脓肿须影像定性加抗感染与立体定向穿刺；面肌痉挛靠微血管减压根治。","compare":[{"diseaseId":"ns_cavernoma","dx":"反复癫痫或少量出血，MRI T2 爆米花样伴完整含铁血黄素环，无强化","key":"爆米花征加环形低信号"},{"diseaseId":"ns_moyamoya","dx":"儿童缺血发作或成人脑出血，MRA/CTA 示双侧颈内动脉末端狭窄闭塞加烟雾状侧支","key":"烟雾血管加末端闭塞"},{"diseaseId":"ns_brain_abscess","dx":"发热头痛加局灶缺损，增强 MRI 环形强化、DWI 高信号脓腔伴水肿","key":"脓腔 DWI 高加感染征象"},{"diseaseId":"ns_hemifacial","dx":"一侧眼轮匝肌起病的阵发性抽动渐扩至口角，3D-TOF 示面神经根部血管襻","key":"半侧抽动而无其他神经体征"}],"diseases":[{"id":"ns_cavernoma","name":"海绵状血管瘤","aka":["Cavernous Malformation","Cavernoma","海绵状血管畸形","CCM"],"rank":1,"basic":{"define":"由扩张薄壁血窦（无正常脑组织、缺乏弹力层与平滑肌）组成的低流量血管畸形，可位于脑内、脑干或脊髓；分孤立性与多发性（家族性或放疗后）。","risk":["多为散发性孤立病灶","家族性由 KRIT1（CCM1）、MGC4607、PDCD10 基因突变引起，病灶多发","儿童期脑脊髓放疗后可诱发多发病灶","既往出血史、脑干或深部位置者再出血风险高"],"epi":"人群患病率约 0.16%–0.5%，多因其他原因行 MRI 偶然发现；发病高峰 30–40 岁。"},"patho":"病灶由血栓栓子与薄壁血窦构成，血流缓慢，无正常血管壁屏障，反复微出血形成含铁血黄素沉积环。出血多为低流量渗血，慢性反复出血致邻近胶质增生并诱发癫痫；脑干病灶出血虽小也可致严重致残。","dx":{"criteria":["反复癫痫发作或少量脑内出血，无高血压与动脉瘤病史","MRI T1/T2 混杂信号呈爆米花（popcorn）样，周围 T2 低信号含铁血黄素环","SWI/T2* 见显著磁敏感点灶，多发灶时更敏感","MRI 增强无或仅轻微强化","DSA 多为阴性，为特征性表现而非排除依据"],"workup":["MRI T1/T2/FLAIR 与 SWI 评估出血次数与含铁血黄素环","多发病灶者查全脑及脊髓 MRI、皮肤并考虑基因检测","癫痫者行脑电图定位","DSA 排除动静脉畸形","注意伴发发育性静脉异常，勿误切引流静脉"],"grading":"部位分幕上、脑干、脊髓；Zabramski Ⅰ 型（亚急性出血，T1/T2 高）、Ⅱ 型（爆米花）、Ⅲ 型（含铁血黄素为主）、Ⅳ 型（SWI 微灶）；脑干等深部年出血率约 2%–5%，幕上约 0.5%–1%。"},"ddx":[{"name":"烟雾病","point":"与本类中烟雾病的鉴别：烟雾病为末端动脉闭塞伴烟雾侧支，表现为缺血或出血发作；海绵状血管瘤为孤立混杂信号病灶，无大血管狭窄。"},{"name":"动静脉畸形","point":"DSA 见供血动脉、瘤囊与引流静脉，T2 见血管流空影；海绵状血管瘤无流空。"},{"name":"高血压性脑出血","point":"急性起病、多发于基底节或脑桥，CT 均匀高密度。"},{"name":"脑脓肿","point":"环形强化、DWI 亮脓腔，伴发热。"},{"name":"脑梗死伴出血转化","point":"与血管分布区一致，DWI 见确切梗死灶。"}],"tx":{"drug":[{"name":"左乙拉西坦（癫痫控制）","dose":"起始 500 mg 口服 每日 2 次，可按需至 1500 mg 每日 2 次","note":"首次癫痫发作后用药；偶然发现而无发作者不常规预防","renal":"CrCl 30–50 mL/min 减至 250–500 mg 每 12 h，<30 或透析遵说明书","hepatic":"重度肝损害减量 50%","interact":"与丙戊酸、卡马西平合用注意血药浓度"},{"name":"丙戊酸钠（替代抗癫痫）","dose":"起始 400 mg/d 分 2 次，渐加至 800–1200 mg/d，血药浓度 50–100 μg/mL","note":"育龄女性慎用（致畸风险）","renal":"遵说明书","hepatic":"肝功能损害者禁用或减量，警惕高氨脑病","interact":"抑制拉莫三嗪代谢，增强华法林与阿司匹林作用"}],"nonDrug":["症状性切除：反复出血、进行性神经缺损、难治性癫痫且病灶可及；术后癫痫控制满意率 70%–90%","脑干病灶经安全区入路（如四脑室底），须权衡功能损伤","放射外科仅用于手术不能及的高危脑干病例，疗效不确定","无症状幕上小病灶可观察加定期 MRI","伴发育性静脉异常者切除病灶但保留 DVA 引流"],"life":["避免剧烈运动、头部外伤与血压骤变","出血后 1–3 个月复查 MRI，之后每年或每 2 年","家族性患者定期全脑及脊髓 MRI，避免放疗","妊娠期咨询，多数可阴道分娩"]},"prog":"年出血率约 0.7%–1.5%，脑干与深部可达 2%–5%；再出血后风险升高至每年约 5%。多数患者长期稳定，癫痫常为长期问题；家族性者病灶多、复发风险高。","refs":["脑海绵状血管瘤诊断与治疗中国专家共识（2021）","AHA/ASA 脑与脊髓海绵状血管畸形管理指南 2017"]},{"id":"ns_moyamoya","name":"烟雾病","aka":["Moyamoya Disease","MMD","Willis 环自发性闭塞"],"rank":2,"basic":{"define":"以双侧颈内动脉末端及大脑前、中动脉起始段进行性狭窄或闭塞，伴基底节区烟雾状侧支血管为特征的特发性脑血管病；有明确继发原因者称烟雾综合征。","risk":["东亚人群发病率最高","成人以女性为主，儿童无性别差异","家族遗传倾向（RNF213 等位基因）","合并甲亢、镰状细胞病、NF1、唐氏综合征者为烟雾综合征"],"epi":"日本年发病率约 0.94/10 万，东亚发病高峰呈儿童（5–10 岁）与成人（30–50 岁）双峰。"},"patho":"颈内动脉末端及大脑前、中动脉近端渐进性狭窄闭塞，穿支血管代偿扩张形成纤细血管网，造影呈烟雾状。儿童以低灌注缺血为主，成人可表现为出血（脑室旁、基底节）或梗死。高碳酸或低碳酸通气反应受限，过度换气（哭闹、吹奏乐器）可诱发缺血发作。","dx":{"criteria":["诊断标准：颈内动脉末端及大脑前、中动脉近端狭窄或闭塞；其周围见异常血管网；病变为双侧（单侧者为可疑）；排除动脉粥样硬化、自身免疫病、脑膜炎等病因","Suzuki 分期：Ⅰ 期分叉部狭窄，Ⅱ 期烟雾血管出现，Ⅲ 期烟雾显著，Ⅳ 期烟雾减少，Ⅴ 期烟雾消失，Ⅵ 期主要脑动脉闭塞","CTA/MRA 见基底节区点片状增强血管影与脑室旁细小血管","出血型 CT 见脑室或基底节出血，缺血型见皮层与分水岭梗死","灌注成像示分水岭与额颞皮层低灌注"],"workup":["DSA（金标准）或 MRA+CTA 明确狭窄部位、Suzuki 分期与侧支","MRI 含 DWI、FLAIR 与 T2* 评估梗死与微出血","灌注评估及乙酰唑胺或 CO2 负荷试验评估脑血管储备","排除继发因素：血脂、同型半胱氨酸、自身免疫、梅毒","儿童评估发育与运动诱发史"],"grading":"Suzuki Ⅰ–Ⅵ 期；临床分型：缺血型、出血型、癫痫型、头痛型。"},"ddx":[{"name":"海绵状血管瘤","point":"与本类中海绵状血管瘤的鉴别：反复少量出血而 MRI 呈爆米花伴含铁血黄素环，大血管无明显狭窄；烟雾病有双侧末端闭塞与烟雾血管。"},{"name":"颅内动脉粥样硬化性狭窄","point":"多见于中老年、有高血压糖尿病高脂血症，狭窄局限且侧支网不明显，无烟雾血管。"},{"name":"颅内动脉夹层","point":"年轻患者伴颈痛或头颈外伤史，影像见双腔或内膜瓣，多单侧。"},{"name":"烟雾综合征","point":"影像类似但合并镰状细胞病、NF1、甲亢或放疗史等继发原因。"},{"name":"动脉瘤破裂","point":"突发蛛网膜下腔出血伴颈强，DSA 见动脉瘤。"}],"tx":{"drug":[{"name":"阿司匹林（儿童缺血型常用）","dose":"成人 100 mg 口服 每日 1 次；儿童 3–5 mg/kg/d 遵医嘱","note":"成人出血型不用；避免长期双联抗血小板","renal":"重度肾功能不全慎用","hepatic":"严重肝病禁用","interact":"与其他抗凝或抗血小板药合用增加出血"},{"name":"尼莫地平（辅助）","dose":"30 mg 口服 每日 3 次，遵说明书","note":"用于缓解缺血症状，不能逆转狭窄","renal":"遵说明书","hepatic":"肝功能不全者减量","interact":"与 CYP3A4 抑制剂合用需减量"},{"name":"甘露醇（出血型降颅压）","dose":"0.25–1 g/kg 每 6–8 h 静脉滴注，遵说明书","note":"脑室出血合并脑积水者须尽快行脑室外引流","renal":"肾功能不全者改用甘油果糖或减量","hepatic":"遵说明书","interact":"与肾毒性药物合用注意肾损害"}],"nonDrug":["血运重建术：直接（STA-MCA 搭桥）或间接（EDAS、EMS）吻合，缺血型为明确适应证，成人出血型亦推荐以降低再出血","手术时机：脑梗急性期后约 4–6 周、非发作期；双侧病变分期手术","出血型急性期：脑室穿刺引流与血肿清除","围术期维持正常血压、容量与 CO2，避免过度换气"],"life":["避免过度换气、哭闹、脱水与剧烈运动","血压维持在正常范围，儿童注意补液","术后每 6–12 个月影像随访搭桥通畅与灌注","家族筛查"]},"prog":"自然病程中约 60%–70% 最终出现梗死或出血；成人出血型 5 年再出血率约 20%–30%，儿童以反复 TIA 与认知下降为主。血运重建后 5 年缺血复发显著下降。","refs":["烟雾病诊断与治疗中国专家共识（2021）","AHA/ASA Moyamoya Disease Guideline 2021"]},{"id":"ns_brain_abscess","name":"脑脓肿","aka":["Brain Abscess","化脓性脑脓肿","颅内脓肿"],"rank":3,"basic":{"define":"化脓性细菌、真菌或原虫侵入脑实质形成的含脓腔与包膜的局灶性感染；按途径分邻近性（鼻窦、中耳、牙源性）、血源性（心内膜炎、肺部感染、发绀型先心病）与创伤术后。","risk":["慢性鼻窦炎、乳突炎、牙源性感染、中耳炎","发绀型先心病、感染性心内膜炎、化脓性肺疾病","颅脑创伤或开颅术、脑室引流","糖尿病、酗酒、免疫抑制"],"epi":"发病率约 0.3–1.8/10 万；成人 30–50 岁多见，及时诊治后病死率约 10%–15%。"},"patho":"病原体经邻近播散、血行或直接植入脑实质，早期为脑炎期水肿，继而中央坏死液化形成脓腔，周围胶质与纤维组织形成包膜。周围血管源性水肿可致颅高压与脑疝；破入脑室可致脑室炎与弥漫颅内感染。常见病原为链球菌、金黄色葡萄球菌与厌氧菌。","dx":{"criteria":["发热、头痛、呕吐、局灶神经体征或癫痫，部分患者无发热","增强 MRI：环形强化包膜，中央脓腔 T1 低、T2 高，且 DWI 显著高信号为特征","增强 CT 示低密度、环形强化与周围水肿，后颅窝敏感性低","脑脊液压力、白细胞与蛋白升高，糖降低，培养多阴性","穿刺脓液涂片、培养（需氧加厌氧加真菌）与药敏为确诊依据"],"workup":["血常规、CRP、ESR 与血培养","增强头颅 MRI（含 DWI）首选","寻找原发灶：鼻窦/乳突 CT、牙齿检查、胸片、心脏超声","颅高压或占位效应明显时禁忌腰椎穿刺","免疫缺陷者查 HIV、血糖与免疫球蛋白"],"grading":"按部位分大脑半球、小脑、脑干、多发；分脑炎期与脓肿形成期（后者需穿刺或手术）。"},"ddx":[{"name":"海绵状血管瘤","point":"与本类中海绵状血管瘤的鉴别：爆米花样伴含铁血黄素环，无强化与脓腔，无感染征象；脑脓肿脓腔 DWI 显著高信号并常伴发热。"},{"name":"脑转移瘤","point":"中心坏死区 DWI 多不亮、壁可呈结节状、有原发肿瘤史。"},{"name":"高级别胶质瘤","point":"环壁厚而不规则，DWI 环壁受限更明显。"},{"name":"亚急性脑梗死","point":"强化范围与血管区一致，DWI 为脑组织本身受限。"},{"name":"脑膜瘤（囊变型）","point":"宽基底与脑膜尾征，囊变区 DWI 不亮。"}],"tx":{"drug":[{"name":"头孢曲松","dose":"2 g 静脉滴注 每 12 h（儿童 50–100 mg/kg/d 分 2 次）","note":"常与甲硝唑联合，有金葡菌风险时加万古霉素；疗程一般 6–8 周","renal":"CrCl <10 mL/min 时 2 g 每日 1 次","hepatic":"遵说明书","interact":"新生儿禁与含钙输液同管使用"},{"name":"甲硝唑","dose":"500 mg 静脉滴注 每 8 h（儿童 7.5 mg/kg 每 8 h）","note":"覆盖厌氧菌，为主要联用药","renal":"遵说明书","hepatic":"重度肝功能不全减量，警惕周围神经病","interact":"与酒精（双硫仑样反应）、华法林合用需注意"},{"name":"万古霉素","dose":"15–20 mg/kg 静脉滴注 每 8–12 h，目标谷浓度 15–20 μg/mL","note":"用于葡萄球菌风险者（术后、创伤、心内膜炎）","renal":"按 CrCl 调整剂量并监测谷浓度","hepatic":"遵说明书","interact":"与氨基糖苷类、哌拉西林他唑巴坦合用增加肾毒性"},{"name":"美罗培南","dose":"2 g 静脉滴注 每 8 h（重症或术后医院获得性感染）","note":"培养结果前经验用药，随后按药敏调整","renal":"CrCl 25–50 mL/min 每 12 h 1 g，10–25 mL/min 每 12 h 0.5 g","hepatic":"遵说明书","interact":"与丙戊酸合用显著降低其血药浓度"},{"name":"地塞米松（严格适应证）","dose":"严重水肿或颅高压时 4–10 mg 静脉 每 6 h 短期使用后逐步停","note":"长期使用影响包膜形成与抗生素渗透","renal":"遵说明书","hepatic":"遵说明书","interact":"与苯妥英、抗凝药等相互作用"}],"nonDrug":["立体定向穿刺抽脓加引流：病灶 >2.5 cm、有明确脓腔、深部或功能区者首选","开颅切除：多房或复发、厚壁脓肿、小脑脓肿致脑干受压，或需同时清除硬膜外/硬膜下脓肿","破入脑室者行脑室外引流加脑室内抗生素","处理原发灶：鼻窦手术、乳突根治、拔除病牙、心内膜炎专科治疗","抗感染疗程 6–8 周，临床与影像明显好转者可短至 4–6 周"],"life":["每 2–4 周复查 MRI（含 DWI）评估脓腔","癫痫者抗癫痫治疗至少 1 年并随访脑电图","血糖与免疫状态管理","高危患者预防与早诊教育"]},"prog":"早期诊断加合理抗感染加引流或切除可使病死率约 10%–15%；破入脑室者病死率超过 30%。约 30% 遗留癫痫或认知障碍。","refs":["脑脓肿诊断与治疗中国专家共识（2020）","中国中枢神经系统感染诊治专家共识（2015）","IDSA 医疗相关脑室炎与脑膜炎治疗指南 2017"]},{"id":"ns_hemifacial","name":"面肌痉挛","aka":["Hemifacial Spasm","HFS","半面痉挛"],"rank":4,"basic":{"define":"以一侧面神经支配区肌肉（自眼轮匝肌起始并扩展至颊部与口角）阵发性不自主抽搐为特征的神经肌肉疾病，多由血管压迫面神经根部所致。","risk":["40–60 岁高发，女性略多于男性","桥小脑角血管襻（小脑前下、后下动脉或椎动脉）压迫面神经 REZ 区","桥小脑角占位（听神经瘤、脑膜瘤、表皮样囊肿）继发者占 1%–5%","面瘫恢复不全后"],"epi":"年发病率约 1–2/10 万，患病率约 10–20/10 万，亚洲人群较高。"},"patho":"面神经根部受邻近血管襻慢性搏动性压迫，导致脱髓鞘与异位兴奋灶，脱髓鞘处轴突间假突触传导引起同步放电，表现为阵发性面部肌肉抽搐。药物与肉毒毒素仅症状控制，只有微血管减压可根治。","dx":{"criteria":["一侧面部阵发性不自主抽搐，多自眼轮匝肌起病并扩展至口角与颈阔肌","紧张、疲劳、说话或咀嚼时加重，入睡后多减轻或消失","神经系统查体无其他异常，无面部感觉障碍","肌电图可示异常肌反应（侧向扩散）","3D-TOF MRA/FIESTA 显示面神经根部血管襻并排除桥小脑角占位"],"workup":["面、三叉、听神经与后组颅神经查体","3D-TOF MRA 或 FIESTA 序列排除占位与判断责任血管","必要时肌电图与神经电生理","记录痉挛频率与诱因","合并三叉神经痛时同时评估"],"grading":"按病因分原发性（血管压迫）与继发性（占位或脱髓鞘）；Cohen 分级 0 级无痉挛至 4 级影响功能活动。"},"ddx":[{"name":"脑脓肿","point":"与本类中脑脓肿的鉴别：脑脓肿以发热、颅高压与局灶缺损为主，影像见环形强化脓腔；面肌痉挛为半侧面肌阵发性抽动，无占位与感染征象。"},{"name":"三叉神经痛","point":"电击样剧痛伴扳机点，无肌肉抽搐；面肌痉挛为不自主抽动而无痛。"},{"name":"局灶性癫痫","point":"抽搐短暂，伴意识改变与脑电图异常。"},{"name":"梅杰综合征","point":"双侧对称眼睑痉挛伴下颌肌张力障碍，常影响吞咽与说话。"},{"name":"听神经瘤继发面肌痉挛","point":"伴听力下降与耳鸣，MRI 可见桥小脑角占位。"}],"tx":{"drug":[{"name":"A 型肉毒毒素（首选症状治疗）","dose":"面部受累肌群点状肌内注射，单侧总量一般 12.5–30 U，每 3–6 个月重复，按痉挛范围调整","note":"90% 以上患者缓解 2–4 个月；过量或过频可致上睑下垂与表情僵硬","renal":"遵说明书","hepatic":"遵说明书","interact":"与氨基糖苷类、神经肌肉阻滞剂合用增强作用"},{"name":"卡马西平","dose":"起始 100 mg 口服 每日 2 次，可按需至 200 mg 每日 3 次","note":"仅用于轻症短期缓解，疗效个体差异大","renal":"遵说明书","hepatic":"肝功能损害者禁用或减量","interact":"强 CYP3A4 诱导剂，降低抗凝药、口服避孕药及部分抗癫痫药浓度"},{"name":"氯硝西泮（辅助）","dose":"0.5 mg 睡前口服，可加至 1 mg 每日 2 次","note":"长期使用注意依赖与嗜睡","renal":"遵说明书","hepatic":"肝功能损害者慎用","interact":"与酒精、阿片类、镇静药合用可致呼吸抑制"}],"nonDrug":["显微血管减压术（MVD）：唯一根治手段，经乙状窦后入路分离并置入 Teflon 垫片，有效率 90%–95%，复发率 5%–10%","MVD 并发症：面瘫约 2%–5%，听力下降 <2%，脑脊液漏与小脑梗死罕见","肉毒毒素注射：适用于不愿手术、高龄或合并症多者","继发性者切除桥小脑角占位","面神经射频或部分切断仅作体弱者姑息，后遗症多"],"life":["避免紧张与疲劳，记录发作诱因","肉毒毒素注射后 2 周复诊评估，3–6 个月重复注射","MVD 术后 1 年与 3 年复诊评估复发","长期面部抽搐影响社交者给予心理支持"]},"prog":"自然病程多缓慢加重，少数可自行缓解但不持久。微血管减压术长期治愈率 85%–90%；肉毒毒素需长期重复注射。","refs":["面肌痉挛诊断与治疗中国专家共识（2021）","中国神经外科微血管减压术专家共识（2019）"]}]},{"id":"cvd_nsurg_more","name":"脑血管畸形","rank":41,"summary":"脑动静脉畸形以 DSA 明确 nidus、供血与引流静脉，用 Spetzler-Martin 分级决定治疗方式：低级别首选显微切除，深部或 ≤3 cm 者选伽玛刀，高流量者术前栓塞减流；未破裂者需权衡年出血率与治疗风险，妊娠与癫痫须单独管理。","compare":[],"diseases":[{"id":"ns_avm","name":"脑动静脉畸形","aka":["AVM","Brain arteriovenous malformation","脑血管畸形","脑动静脉畸形"],"rank":1,"basic":{"define":"脑动静脉畸形是脑内动脉与静脉之间缺乏毛细血管床、经畸形血管团（nidus）直接交通的先天性血管发育异常，可表现为脑出血、癫痫、头痛或进行性神经功能缺损。","risk":["发病高峰 20–40 岁，男性略多","既往破裂出血（再出血风险最高的因素）","畸形团位于深部（基底节、丘脑、脑干）或幕下","深静脉引流、单一引流静脉或引流静脉狭窄","供血动脉血流相关动脉瘤、静脉瘤样扩张","妊娠（血容量与心输出量增加 30%–50%）、遗传性出血性毛细血管扩张症与 CM-AVM 综合征"],"epi":"人群检出率约 10–18/10 万，占自发性颅内出血的 2%–5%；未破裂者年出血率 2%–4%，破裂后首年再出血率约 6%，此后回落至 2%–4%/年。首次出血死亡率 10%–30%，致残率 30%–50%。"},"patho":"胚胎期血管发育异常使动脉血经 nidus 直接流入静脉，缺乏毛细血管阻力，形成高流量低阻力环路；供血动脉扩张迂曲，引流静脉动脉化并瘤样扩张。nidus 内压力高、管壁薄，加之血流相关动脉瘤，构成破裂的解剖基础；盗血现象与静脉高压致周围脑组织慢性缺血与胶质增生，成为癫痫灶。出血多为脑实质内，可破入脑室或蛛网膜下腔。","dx":{"criteria":["青壮年自发性脑叶出血、癫痫（20%–40% 以癫痫起病）或渐进性头痛与局灶神经功能缺损","头颅 CT 见脑实质出血（可伴钙化或等密度血管影）；CTA/MRA 见畸形血管团与增粗引流静脉","DSA 为确诊金标准：明确 nidus 大小、供血动脉（皮层支/穿支）、引流静脉（浅/深）、有无血流相关动脉瘤或静脉狭窄","MRI T2/SWI 见流空影与含铁血黄素环，FLAIR 见周围胶质增生；灌注成像评估盗血范围","Spetzler-Martin 分级：nidus <3 cm 计 1 分、3–6 cm 计 2 分、>6 cm 计 3 分；位于功能区（感觉运动、语言、视觉、丘脑/下丘脑、脑干、小脑脚、深部核团）计 1 分；深静脉引流计 1 分；总分 I–V 级","破裂风险：未破裂 2%–4%/年；既往破裂、深部位置、单一或深静脉引流、伴血流相关动脉瘤者更高","癫痫评估：发作类型、EEG 放电部位与 nidus 的关系，区分 AVM 相关癫痫与继发性癫痫","妊娠期：孕前或孕早期完成 DSA/MRI 评估，妊娠期出血风险升高，需产科与神外联合管理"],"workup":["DSA 全脑血管造影（双侧颈内、颈外、椎动脉），为诊断与治疗决策的核心","MRI+MRA、SWI、FLAIR；功能 MRI/DTI 评估 nidus 与皮质功能区、白质束的关系","CT 平扫（急性出血）与 CTA（急诊筛查）；CT 灌注评估盗血","EEG（癫痫者）与神经心理评估（优势半球病变）","遗传与家族筛查：HHT（鼻衄、毛细血管扩张、内脏 AVM）、CM-AVM（RASA1/EPHB4 突变）","血流相关动脉瘤与静脉高压评估（DSA 动态期与 3D 重建）"],"grading":"Spetzler-Martin（SM）分级：大小、功能区、深静脉引流三项之和，I–V 级；Spetzler-Ponce 分层：A 为 SM I–II（手术风险低）、B 为 SM III、C 为 SM IV–V（手术风险高）。Lawton-Young 补充分级加入年龄、是否破裂与 nidus 是否弥漫，用于预测手术结局。SM I–II 级手术永久致残率 <5%，IV–V 级可达 15%–20%。"},"ddx":[{"name":"颅内动脉瘤与蛛网膜下腔出血（ns_aneurysm）","point":"与本类（脑血管畸形）邻类疾病 ns_aneurysm 的鉴别点：动脉瘤多位于 Willis 环及分支，破裂以蛛网膜下腔出血为主，DSA 见瘤囊与载瘤动脉；AVM 多为脑实质出血，DSA 见 nidus 与早显引流静脉。"},{"name":"海绵状血管瘤（ns_cavernoma）","point":"MRI 呈爆米花样混杂信号伴含铁血黄素环、无流空影，DSA 阴性（隐匿性血管畸形）；出血多为少量反复，癫痫常见。"},{"name":"烟雾病（ns_moyamoya）","point":"双侧颈内动脉末端或大脑中动脉近端狭窄闭塞伴颅底烟雾状侧支，DSA 无 nidus；儿童与青年缺血性卒中多见。"},{"name":"硬脑膜动静脉瘘（DAVF）","point":"供血来自硬脑膜动脉、瘘口位于硬膜，DSA 静脉期早显；AVM 供血为脑动脉，二者治疗路径不同。"},{"name":"发育性静脉异常（DVA）","point":"水母头样引流静脉汇入单一收集静脉，DSA 仅静脉期异常，无动脉期分流；多无症状，无需治疗。"},{"name":"胶质瘤或转移瘤伴出血","point":"瘤周水肿明显、占位效应与强化方式不同，DSA 无 nidus；MRI 增强与病理确诊。"},{"name":"继发性癫痫（海马硬化、皮质发育不良）","point":"MRI 见海马萎缩或信号异常、皮质增厚，无血管团与流空影；EEG 定位与影像一致。"}],"tx":{"drug":[{"name":"左乙拉西坦","dose":"500 mg bid 起始，按发作控制每 2 周加 500 mg，常用 1000–1500 mg bid","note":"局灶性发作首选之一，药物相互作用少，妊娠相对安全（仍需孕前评估）；仅用于有癫痫发作者，不推荐未破裂无发作患者预防性用药。","renal":"CrCl 50–80：500–1000 mg q12h；30–50：250–750 mg q12h；<30：250–500 mg q12h；透析后追加 250–500 mg","hepatic":"重度肝损减量 50%","interact":"无显著 CYP 相互作用；与阿片类、苯二氮䓬类叠加镇静"},{"name":"奥卡西平","dose":"300 mg bid 起始，每 3 天加 300 mg，维持 900–1200 mg/日分 2 次","note":"局灶性发作；低钠血症发生率约 2%–3%，老年人需监测血钠。","renal":"CrCl<30 起始 300 mg qd，缓慢加量","hepatic":"轻中度无需调整，重度慎用","interact":"与卡马西平、苯妥英互相降低浓度；降低口服避孕药效果；与利尿剂合用加重低钠"},{"name":"丙戊酸钠","dose":"15–20 mg/kg/日分 2 次口服，按血药浓度调整（有效 50–100 µg/mL）","note":"全面性发作；育龄女性禁用（致畸与神经发育损害），用药前及用药中监测肝酶与血氨。","renal":"遵说明书","hepatic":"肝病或不明原因转氨酶升高者禁用","interact":"抑制拉莫三嗪代谢需减量；与碳青霉烯类合用血药浓度骤降；与苯巴比妥、卡马西平互相影响"},{"name":"地西泮","dose":"癫痫持续状态 10 mg 静脉推注（速度 ≤5 mg/min），必要时 5–10 min 重复；儿童 0.3 mg/kg","note":"需气道与呼吸监测，备好复苏设备。","renal":"遵说明书","hepatic":"重度肝损半衰期延长，减量","interact":"与阿片类、其他苯二氮䓬类叠加呼吸抑制"},{"name":"甘露醇","dose":"20% 甘露醇 0.25–1 g/kg 静脉滴注 20–30 min，q4–6h（急性颅内压增高或脑疝征象）","note":"监测血浆渗透压（目标 300–320 mOsm/L）、肾功能与尿量；低血压、少尿者慎用。","renal":"少尿或无尿者禁用或减量","hepatic":"遵说明书","interact":"与氨基糖苷类、万古霉素等肾毒性药物叠加肾损"},{"name":"拉贝洛尔","dose":"10–20 mg 静脉推注，必要时每 10 min 重复；或 1–2 mg/min 泵入，目标收缩压 <140 mmHg","note":"用于急性出血期与围手术期血压控制，避免过度降压致脑灌注不足。","renal":"遵说明书","hepatic":"重度肝损减量","interact":"与维拉帕米、地尔硫䓬合用加重心动过缓与传导阻滞；与硝酸酯类叠加低血压"}],"nonDrug":["显微手术切除：SM I–II 级首选，治愈率 >95%，永久致残率 <5%；SM III 级经多学科评估后决定","立体定向放射外科（伽玛刀）：nidus ≤3 cm、深部或手术高风险（SM I–III），边缘剂量 15–25 Gy，闭塞率 2 年 60%–70%、3 年 70%–80%；潜伏期内仍有出血风险","血管内栓塞：术前减流（减少 nidus 体积 30%–50%）、靶向栓塞血流相关动脉瘤与深部供血；单纯栓塞治愈率 10%–20%，并发症 5%–10%；多模态联合（栓塞+显微手术或放射外科）用于 SM III–V 级","破裂急性期：血肿清除并争取一期切除可切除的 AVM；深部或高危者仅清除血肿、二期处理","保守观察：SM IV–V、无症状、高龄或合并症多者；控制血压，除另有指征外避免抗凝与抗血小板","妊娠管理：孕前治疗为最佳；孕期未处理者产科与神外联合随访，分娩方式个体化"],"life":["血压控制 <140/90 mmHg，戒烟、避免过量饮酒","癫痫者规律服药、避免睡眠剥夺与闪光刺激；育龄女性孕前调整抗癫痫药并补叶酸 5 mg/日","未处理的高危 AVM 避免剧烈对抗性运动与用力憋气","治疗后 3–6 个月复查 DSA 确认闭塞，其后每 1–2 年 MRI/MRA 随访","计划妊娠前必须完成影像评估与治疗决策"]},"prog":"未破裂 AVM 年出血率 2%–4%，首次出血死亡率 10%–30%；SM I–II 级显微手术治愈率 >95%，伽玛刀 3 年闭塞率 70%–80%。SM IV–V 级治疗风险高，多倾向保守观察，5 年累积出血风险可达 10%–15%；规范的多学科决策可显著改善功能结局。","refs":["中华医学会神经外科学分会《脑动静脉畸形多学科诊疗专家共识》（中华神经外科杂志 2024）","中华医学会神经外科学分会介入学组《脑动静脉畸形介入治疗中国专家共识》（2017）","Spetzler RF, Martin NA. A proposed grading system for arteriovenous malformations. J Neurosurg. 1986;65(4):476-483","Lawton MT, et al. A supplementary grading scale for selecting patients with brain arteriovenous malformations for surgery. Neurosurgery. 2010;66(4):702-713"]}]},{"id":"icp","name":"颅内压增高与脑疝","rank":42,"summary":"颅内压增高是神经外科共有的危重病理生理状态，核心是 Monro-Kellie 代偿耗竭后的压力陡升与脑灌注压下降；识别瞳孔与 GCS 变化、区分小脑幕切迹疝与枕大孔疝，按阶梯使用甘露醇/高渗盐水、短时过度通气与去骨瓣减压。","compare":[],"diseases":[{"id":"ns_ich_herniation","name":"颅内压增高与脑疝","aka":["Intracranial hypertension","Increased ICP","Brain herniation","颅内高压","小脑幕切迹疝","枕大孔疝","颞叶钩回疝"],"rank":1,"basic":{"define":"颅内压（ICP）持续 >20 mmHg 即为颅内压增高；当压力梯度使脑组织从高压腔向低压腔移位、压迫脑干与颅神经时称脑疝，是神经外科最危急的综合征，可在数分钟内致死。","risk":["颅脑创伤（硬膜外/硬膜下血肿、脑挫裂伤、弥漫性轴索损伤）","颅内占位（胶质瘤、转移瘤、脑膜瘤、脑脓肿、血肿）","大面积脑梗死或脑出血伴水肿、蛛网膜下腔出血后脑积水","颅内感染、静脉窦血栓、暴发性肝衰竭","脑积水（梗阻性或交通性）、特发性颅内压增高","低钠血症、癫痫持续状态、高热与缺氧加重脑水肿"],"epi":"重型颅脑创伤（GCS ≤8）中约 50%–60% 出现颅内压增高，其中 20%–30% 发生脑疝；脑疝一旦发生，未及时处理死亡率 >50%，双侧瞳孔散大者死亡率 >80%。"},"patho":"颅腔为骨性闭合腔，内容物（脑组织约 80%、血液 10%、脑脊液 10%）中任一容积增加即引起 ICP 上升，初期靠脑脊液与静脉血排出代偿（Monro-Kellie 学说），代偿耗竭后压力-容积曲线陡升。ICP 升高使脑灌注压（CPP=MAP−ICP）下降，脑血流减少致缺血与细胞毒性水肿，形成恶性循环。幕上占位使颞叶海马钩回经小脑幕切迹下移（小脑幕切迹疝），压迫动眼神经与大脑后动脉，并致脑干轴向移位与出血；幕下占位或小脑扁桃体下移入枕大孔（枕大孔疝）直接压迫延髓呼吸循环中枢。","dx":{"criteria":["头痛（晨起及咳嗽、用力时加重）、喷射性呕吐、视乳头水肿（ICP 持续升高 >2 周方出现）三联征","意识障碍由嗜睡进展至昏睡、昏迷；GCS 较基线下降 ≥2 分提示恶化","瞳孔：一侧散大、对光反射消失提示同侧小脑幕切迹疝；双侧散大固定提示脑干功能衰竭","生命体征：Cushing 反应——收缩压升高、脉压增大、心率 <60 次/分、呼吸不规则，为脑疝晚期","运动体征：对侧肢体偏瘫、病理征阳性；去大脑强直（四肢伸性强直）提示中脑受累","影像：CT/MRI 见占位、中线移位 >5 mm、基底池受压或消失、脑室受压、环池消失；幕下病变见第四脑室受压与脑干变形","有创 ICP 监测指征：GCS 3–8 且 CT 异常（血肿、挫伤、水肿、基底池受压），或 GCS 3–8 且 CT 正常但年龄 >40 岁、收缩压 <90 mmHg 或单侧瞳孔散大；ICP >20 mmHg 持续 >5 min 为治疗阈值","分型鉴别：小脑幕切迹疝有同侧瞳孔散大、对侧偏瘫与意识恶化；枕大孔疝可突发呼吸骤停、双侧瞳孔散大而无先兆"],"workup":["急诊 ABC、GCS、双侧瞳孔大小与对光反射、生命体征与指尖血糖","头颅 CT 平扫（15–30 min 内）：出血、占位、中线移位、基底池与脑室大小","CTA/CTV：怀疑血管性病变或静脉窦血栓时","有创 ICP 监测（脑室型或脑实质型）并计算 CPP；脑室引流兼作治疗","血气、电解质（尤其血钠）、渗透压、凝血、肝肾功能；疑感染时腰穿须先排除脑疝","经颅多普勒（TCD）评估脑血流，辅助判断脑死亡"],"grading":"ICP 分级：正常 5–15 mmHg；轻度 15–20 mmHg；中度 20–40 mmHg；重度 >40 mmHg。脑疝分型：①小脑幕切迹疝（颞叶钩回疝、中央疝）；②枕大孔疝（小脑扁桃体疝）；③大脑镰下疝（扣带回疝）；④小脑幕裂孔上疝（小脑蚓部疝）。GCS 3–8 为重型。"},"ddx":[{"name":"重型颅脑损伤（ns_tbi）","point":"与本类（颅内压增高与脑疝）邻类疾病 ns_tbi 的鉴别点：TBI 是病因诊断、脑疝是其并发症；TBI 有明确外伤史与 CT 见颅骨骨折、硬膜外/下血肿或脑挫裂伤，脑疝为病程中瞳孔散大、GCS 骤降与 Cushing 反应的危急阶段。"},{"name":"急性硬膜外血肿（ns_edh）","point":"典型中间清醒期，CT 见双凸透镜形高密度影；脑疝为其进展结果，需急诊清除血肿。"},{"name":"恶性大脑中动脉梗死","point":"起病急、偏瘫与失语，CT 早期低密度不明显，24–48 h 出现大面积水肿与中线移位；无外伤史。"},{"name":"脑出血","point":"CT 见基底节、丘脑或脑叶高密度血肿，血压显著升高；可与脑疝并存，需同时处理血压与颅压。"},{"name":"蛛网膜下腔出血","point":"突发剧烈头痛、颈项强直，CT 见基底池高密度；脑疝少见，除非再出血或急性脑积水。"},{"name":"颅内感染或脑脓肿","point":"发热、脑膜刺激征，CT/MRI 见环形强化病灶；腰穿前必须排除脑疝。"},{"name":"代谢性脑病（低血糖、肝性脑病、高渗状态）","point":"瞳孔与头眼反射多正常、无局灶体征与中线移位，血糖、血氨或渗透压异常可纠正。"},{"name":"癫痫持续状态","point":"抽搐后意识障碍，EEG 见持续放电；瞳孔可散大但影像无占位与中线移位。"}],"tx":{"drug":[{"name":"甘露醇","dose":"20% 甘露醇 0.25–1 g/kg 静脉滴注 15–30 min，q4–6h；脑疝危象可用 1 g/kg 快速滴注","note":"渗透性利尿，15–30 min 起效、维持 4–6 h；监测血浆渗透压 ≤320 mOsm/L、肾功能与尿量，低血容量者先纠正。","renal":"少尿、无尿或严重肾功能不全者禁用或减量","hepatic":"遵说明书","interact":"与氨基糖苷类、万古霉素、顺铂等肾毒性药叠加肾损；与锂盐合用升高锂浓度"},{"name":"高渗盐水（3%、7.5%、23.4%）","dose":"3% 氯化钠 2–5 mL/kg 静脉输注 15–30 min；脑疝危象用 23.4% 氯化钠 30 mL 经中心静脉推注；目标血钠 145–155 mmol/L","note":"扩容同时降颅压，血流动力学不稳定者优于甘露醇；每 4–6 h 监测血钠，24 h 升幅不超过 10–12 mmol/L。","renal":"心衰、肺水肿、少尿者慎用","hepatic":"遵说明书","interact":"与利尿剂合用加重电解质紊乱；避免与含钙液同通路"},{"name":"呋塞米","dose":"20–40 mg 静脉推注，可与甘露醇联用（0.5–1 mg/kg）","note":"减少脑脊液生成并利尿，增强甘露醇效果；监测血钾与容量状态。","renal":"肾功能不全者需增大剂量，注意耳毒性","hepatic":"肝硬化者警惕低钾诱发肝性脑病","interact":"与氨基糖苷类叠加耳肾毒性；与地高辛合用时低钾致中毒"},{"name":"丙泊酚","dose":"1–2 mg/kg 静推诱导，0.5–4 mg/(kg·h) 泵入维持镇静，目标 RASS −4 至 −5","note":"用于难治性颅高压的镇静与代谢抑制，需气管插管与血流动力学监测；警惕丙泊酚输注综合征（>4 mg/kg/h 或 >48 h）。","renal":"遵说明书","hepatic":"肝损者减量","interact":"与阿片类、苯二氮䓬类叠加呼吸抑制与低血压"},{"name":"芬太尼或瑞芬太尼","dose":"芬太尼 1–2 µg/kg 静推后 0.5–2 µg/(kg·h) 泵入；或瑞芬太尼 0.05–0.2 µg/(kg·min)","note":"镇痛可减少躁动与 ICP 波动，避免低血压与呼吸抑制。","renal":"瑞芬太尼经酯酶代谢，肾衰无需调整","hepatic":"芬太尼经肝代谢，重度肝损减量","interact":"与镇静药协同加重呼吸抑制与低血压"},{"name":"去甲肾上腺素","dose":"0.05–0.5 µg/(kg·min) 泵入，维持 MAP ≥80 mmHg、CPP 60–70 mmHg","note":"颅高压时保证脑灌注，避免 CPP <60 mmHg；有创动脉压监测。","renal":"遵说明书","hepatic":"遵说明书","interact":"与单胺氧化酶抑制剂合用可致高血压危象；与卤化麻醉药合用增加心律失常"},{"name":"地塞米松","dose":"颅内肿瘤相关水肿：负荷 10 mg 静注后 4 mg q6h，或 4–10 mg q6h，最短疗程并尽快减量","note":"仅用于肿瘤或脓肿周围血管源性水肿，不推荐用于颅脑创伤（增加死亡率）；监测血糖与消化道出血。","renal":"遵说明书","hepatic":"重度肝损可能需要减量","interact":"与 NSAIDs 叠加消化道出血；苯妥英、利福平降低疗效；升高血糖并降低降糖药效果"}],"nonDrug":["体位：床头抬高 30°，头部保持中立，避免颈部屈曲与颈静脉受压","气道与氧合：GCS ≤8 气管插管，PaO₂ >80 mmHg、PaCO₂ 维持 35–40 mmHg，避免低氧与高碳酸血症","过度通气仅作急救：PaCO₂ 30–35 mmHg，持续不超过 30–60 min，至手术减压准备完成即停；不用于常规预防","脑室穿刺引流：梗阻性脑积水或需 ICP 监测时，快速放液 5–10 mL 降颅压并建立监测通道","去骨瓣减压指征：重型 TBI 难治性 ICP >25 mmHg 持续 >1 h、GCS ≤8 且 CT 见弥漫性损伤或血肿；恶性大脑中动脉梗死（>50% 供血区、意识障碍、中线移位 >5 mm）48 h 内；大面积小脑梗死/出血伴脑干受压","病因手术：血肿清除、肿瘤切除、脓肿引流、脑积水分流；同时控制癫痫、体温（32–36 ℃）与血糖 6–10 mmol/L"],"life":["ICU 监护：每小时评估 GCS 与瞳孔，ICP/CPP 连续监测，维持 CPP 60–70 mmHg","避免诱发 ICP 升高的因素：躁动、疼痛、呛咳、便秘、高热、癫痫与低氧","康复期 3–6 个月复查 CT/MRI 与认知、运动功能；去骨瓣者 3–6 个月行颅骨修补","长期卧床者间歇气压预防深静脉血栓（出血稳定后药物预防）、防治压疮与肺部感染"]},"prog":"颅内压增高是重型颅脑损伤死亡的主因。脑疝发生后即使及时手术，死亡率仍达 40%–60%，双侧瞳孔散大者 >80%；规范 ICP/CPP 目标管理与及时去骨瓣减压可降低死亡率，但增加植物状态与重度残疾比例，存活者约 30%–50% 遗留中重度残疾。","refs":["《中国颅脑创伤外科手术指南》（2009）","《颅脑创伤去骨瓣减压术中国专家共识》（2013）","Carney N, et al. Guidelines for the Management of Severe Traumatic Brain Injury, 4th Edition. Neurosurgery. 2017;80(1):6-15","中华医学会神经病学分会《中国脑出血诊治指南（2019）》","《王忠诚神经外科学》颅内压增高与脑疝章节"]}]},{"id":"ns_congenital","name":"先天性畸形","rank":43,"summary":"神经管闭合不全强调产前筛查与围孕期叶酸预防；开放型脊髓脊膜膨出应在出生后 24–48 h 内闭合，同时评估脑积水与 Chiari II 畸形，终身多学科随访神经、泌尿与矫形功能。","compare":[],"diseases":[{"id":"ns_neural_tube","name":"颅裂与脊柱裂","aka":["Neural tube defects","NTD","Spina bifida","脊髓脊膜膨出","Myelomeningocele","颅裂","脑膜膨出","Encephalocele"],"rank":1,"basic":{"define":"神经管闭合不全指胚胎第 3–4 周神经管闭合失败所致的先天性中枢神经系统畸形，包括颅裂（脑膜膨出、脑膜脑膨出）与脊柱裂（隐性脊柱裂、脊膜膨出、脊髓脊膜膨出）；开放型病变出生时即见囊性包块，需尽早手术闭合。","risk":["孕前及孕早期叶酸缺乏（规范补充可降低 50%–70% 风险）","既往生育神经管缺陷儿（再发风险约 2%–5%）","母亲肥胖（BMI ≥30）或孕前糖尿病（HbA1c 控制不佳）","孕早期高热、服用丙戊酸钠或卡马西平等抗癫痫药","家族史与 MTHFR 等基因多态性、胃旁路术后吸收不良","低社会经济水平、吸烟与酗酒"],"epi":"我国神经管缺陷发生率约 0.5‰–1‰（北方高于南方），自 2009 年推广孕前增补叶酸后显著下降；脊柱裂占神经管缺陷的 50% 以上，脊髓脊膜膨出最常见。全球活产儿发生率约 1‰。"},"patho":"胚胎第 3 周神经板折叠、第 4 周前后神经孔闭合，闭合失败使神经组织暴露于羊水，继发神经基板破坏与进行性神经功能损害。开放型病变因羊水刺激与脑脊液漏，约 80%–90% 合并 Chiari II 畸形（小脑扁桃体、蚓部与第四脑室下疝）与脑积水。颅裂多见枕部，脑膜或脑组织经骨缺损疝出，可合并小头畸形、脑积水与视交叉/垂体异常。隐性脊柱裂为椎弓闭合不全但神经组织未疝出，局部皮肤可有毛发、色素沉着、皮窦或脂肪瘤。","dx":{"criteria":["产前：孕 18–22 周超声见颅骨柠檬征、小脑香蕉征、脑室扩张与脊柱连续性中断；母血清 AFP 升高（开放型约 80%–90%）","出生后：腰骶部中线囊性包块，表面为薄膜或已破溃渗液，透光试验阳性；伴下肢弛缓性瘫、足畸形（马蹄内翻足）、肛门括约肌松弛与尿潴留","颅裂：枕部或鼻根部囊性包块，可伴头围增大、落日眼与视力障碍","脑积水：头围增速 >2 SD、前囟饱满、头皮静脉怒张、落日眼；超声见脑室指数 >0.5","Chiari II：MRI 见小脑扁桃体下疝 >5 mm、第四脑室下拉、顶盖变形；可伴呼吸暂停与吞咽困难","隐性脊柱裂：局部皮肤标志（毛发丛、皮窦、血管瘤、脂肪瘤）或遗尿、便秘、下肢不对称；MRI 见脊髓圆锥低于 L2–L3（脊髓栓系）","术前评估：囊壁是否完整（破裂者 24 h 内手术）、下肢运动与感觉平面、括约肌功能、头围与脑室大小","排除综合征型：合并多发畸形者行染色体微阵列或全外显子检测"],"workup":["产前超声与母血清 AFP；高危者行胎儿 MRI","出生后头颅与全脊柱 MRI（T1/T2）：评估 Chiari II、脑积水、脊髓栓系、脂肪瘤与脊髓纵裂","头颅超声（前囟）动态监测脑室大小；CT 用于骨性结构评估","尿动力学与残余尿、双肾超声：评估神经源性膀胱与上尿路","下肢 X 线（髋脱位、马蹄内翻足）与运动发育评估","遗传咨询与叶酸代谢基因（MTHFR C677T）检测（尤其再发者）"],"grading":"按部位分颅裂（枕部、额鼻部、眶部）与脊柱裂（颈、胸、腰、骶）；按病理分隐性脊柱裂、脊膜膨出、脊髓脊膜膨出（最常见且预后最差）、脊髓裂/脊髓外露。按功能分完全性与不完全性，按是否合并脑积水与 Chiari II 分层；临床以病变平面（胸、腰、骶）与运动平面描述严重度。"},"ddx":[{"name":"Chiari 畸形（ns_chiari）","point":"与本类（先天性畸形）邻类疾病 ns_chiari 的鉴别点：Chiari 畸形以枕颈部疼痛、上肢麻木、吞咽困难与脊髓空洞为主，无腰骶部囊性包块；脊髓脊膜膨出出生即有背部中线包块、下肢瘫与脑积水，且多数合并继发性 Chiari II。"},{"name":"骶尾部畸胎瘤","point":"骶前或骶后实性/囊实性包块，AFP 升高，影像见骶骨前肿块与丰富血供；无椎管后部骨缺损与神经组织疝出。"},{"name":"单纯脊膜膨出","point":"囊内仅脑脊液与脊膜、无神经组织，透光试验阳性，神经功能多正常；脊髓脊膜膨出囊内含神经基板，伴瘫痪与括约肌障碍。"},{"name":"脂肪脊髓脊膜膨出/脊髓栓系","point":"腰骶部脂肪包块与皮肤标志，MRI 见脂肪瘤与圆锥低位；可至儿童期才出现症状，需早期松解。"},{"name":"脊髓纵裂或椎管内肠源性囊肿","point":"MRI 见骨性或纤维分隔、椎管内囊肿，无皮下囊性包块与表面破溃。"},{"name":"新生儿骶部血管瘤或皮下脂肪瘤","point":"无椎管缺损与神经组织疝出，MRI 可明确；若合并皮窦需警惕隐性神经管缺陷。"},{"name":"脑积水（ns_hydrocephalus）","point":"头围增大与脑室扩张但无背部包块；脊柱裂常合并脑积水，二者为因果而非替代关系。"}],"tx":{"drug":[{"name":"叶酸","dose":"孕前 3 个月至孕早期 0.4–0.8 mg qd；既往神经管缺陷生育史者 4 mg qd（孕前 1 个月至孕 12 周）","note":"一级预防最有效手段，可降低 50%–70% 风险；高热或服用抗癫痫药者需加量，但不可自行停抗癫痫药。","renal":"遵说明书","hepatic":"遵说明书","interact":"甲氨蝶呤、苯妥英、苯巴比妥降低叶酸疗效；与抗癫痫药同用时需监测发作"},{"name":"头孢唑林（围手术期预防）","dose":"新生儿 30 mg/kg 静脉，术前 30–60 min 给药；成人 1–2 g 静脉","note":"囊壁完整者术前预防；囊壁破裂或已有感染征象者按脑膜炎方案升级。","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度；与华法林合用可延长 INR"},{"name":"万古霉素联合美罗培南（囊壁破裂/脑膜炎）","dose":"万古霉素 15 mg/kg q6–12h（按日龄、肾功能与谷浓度 15–20 µg/mL 调整）；美罗培南儿童 40 mg/kg q8h、成人 2 g q8h","note":"囊壁破裂超过 24 h 或已有脑膜炎征象时经验性使用，覆盖金黄色葡萄球菌与革兰阴性菌，随后按培养调整。","renal":"按 CrCl 与血药浓度调整","hepatic":"遵说明书","interact":"万古霉素与氨基糖苷类、两性霉素 B 叠加肾毒性；美罗培南降低丙戊酸浓度"},{"name":"甘露醇","dose":"20% 甘露醇 0.25–0.5 g/kg 静脉滴注 30 min，q6–8h（脑积水急性颅高压）","note":"仅作术前过渡，新生儿慎用并监测渗透压与容量；根本治疗为脑脊液引流或分流。","renal":"少尿者慎用","hepatic":"遵说明书","interact":"与肾毒性药物叠加肾损"},{"name":"左乙拉西坦","dose":"儿童负荷 10–20 mg/kg，随后 10–30 mg/kg q12h；成人 500 mg bid 起始","note":"用于 Chiari II 或术后癫痫发作；不推荐无发作患者常规预防。","renal":"按 CrCl 调整","hepatic":"重度肝损减量","interact":"无显著 CYP 相互作用；与镇静药叠加中枢抑制"}],"nonDrug":["开放型脊髓脊膜膨出：出生后 24–48 h 内手术闭合（囊壁完整者亦然）；术前俯卧位、无菌湿盐水纱布覆盖、避免压迫，破溃者 24 h 内手术并静脉抗生素；由神经外科、产科、新生儿科、泌尿外科与康复科共同管理","脑积水：约 80%–90% 需脑室-腹腔分流，多在闭合术后数日内进行；也可行内镜下第三脑室造瘘，但 Chiari II 者成功率较低","Chiari II 出现呼吸暂停、吞咽困难或脊髓空洞进展者行后颅窝减压+硬膜成形","颅裂：脑膜膨出/脑膜脑膨出切除修补，合并脑积水者同期或分期分流","隐性脊柱裂/脊髓栓系：有神经症状或圆锥低位伴脂肪瘤者行栓系松解术","产前干预：孕 19–25 周行胎儿镜或开放胎儿修补，可减少分流依赖并改善运动功能，但增加早产与子宫破裂风险"],"life":["终身随访：每年评估头围、身高体重、神经功能、括约肌功能、肾超声与尿动力学；警惕分流管功能障碍（头痛、呕吐、嗜睡）","清洁间歇导尿管理神经源性膀胱，预防上尿路损害","康复：下肢矫形器、作业治疗、髋关节与足畸形矫治，学校与心理支持","再次妊娠前 4 mg/日叶酸，孕前 1 个月开始；哺乳期 0.4–0.8 mg/日","迟发并发症：生长突增期脊髓栓系、分流感染或梗阻、压疮与乳胶过敏（避免乳胶制品）"]},"prog":"脊髓脊膜膨出患儿约 80%–90% 需分流，约 70%–80% 智力正常（依赖脑积水控制）；下肢功能取决于病变平面，骶部病变多可独立行走，胸腰段病变多需轮椅。规范多学科管理使 80% 以上存活至成年，肾功能衰竭与分流并发症是主要晚期死亡原因；叶酸强化可使再发风险下降 50%–70%。","refs":["中华医学会神经外科学分会小儿神经外科学组《先天性脊柱裂的常见类型及手术对策专家共识》（中华神经外科杂志 2016;32(4):331-335）","卫生部《增补叶酸预防神经管缺陷项目管理方案》（2009）","Adzick NS, et al. A randomized trial of prenatal versus postnatal repair of myelomeningocele. N Engl J Med. 2011;364(11):993-1004","USPSTF: Folic Acid Supplementation for the Prevention of Neural Tube Defects (2017)","《小儿神经外科学》神经管闭合不全章节"]}]}]},"obgyn":{"categories":[{"id":"ob_emerg","name":"产科急症","rank":1,"summary":"以「快速评估–容量复苏–病因处理」为轴：产后出血强调宫缩剂阶梯+子宫按摩+输血和止血手段；子痫前期以硫酸镁防抽搐、控制血压、及时终止妊娠为核心；胎盘早剥一旦确诊且母胎不稳应尽快剖宫产。","compare":[{"diseaseId":"ob_pph","dx":"胎儿娩出后 24 h 内阴道分娩出血 ≥500 mL、剖宫产 ≥1000 mL，或任何引起血流动力学不稳定的出血；子宫收缩乏力最常见","key":"出血量达标准 + 子宫软、宫底升高、按压阴道有血块排出，无严重腹痛及胎盘早剥证据"},{"diseaseId":"ob_preecl","dx":"妊娠 20 周后新发血压 ≥140/90 mmHg 且伴蛋白尿（≥0.3 g/24 h 或尿蛋白/肌酐 ≥0.3）或肾、肝、神经、血液、胎盘任一器官受累表现","key":"以高血压 + 蛋白尿/器官受累为核心，出血非主要表现，硫酸镁为主要预防抽搐手段"},{"diseaseId":"ob_abruption","dx":"妊娠 20 周后突发持续性腹痛 + 阴道流血（可为隐性）+ 子宫张力增高、板状腹，胎心异常或胎儿窘迫，超声见胎盘后血肿","key":"腹痛 + 板状子宫 + 胎心异常，出血量与休克程度不成比例（隐性出血）"}],"diseases":[{"id":"ob_pph","name":"产后出血","aka":["PPH","Postpartum Hemorrhage"],"rank":1,"basic":{"define":"胎儿娩出后 24 h 内，阴道分娩者出血量 ≥500 mL、剖宫产者 ≥1000 mL；或出血后出现低血容量表现（心率 >110 次/分、收缩压下降、血红蛋白下降 ≥10 g/L 等）即诊断，不依赖出血量是否达到阈值。","risk":["子宫收缩乏力：产程延长、缩宫素引产、多胎妊娠、羊水过多、巨大儿、多产次","胎盘因素：前置胎盘、胎盘植入谱系疾病、胎盘滞留、副胎盘","软产道损伤：急产、手术助产（产钳/胎吸）、会阴侧切","凝血功能障碍：重度子痫前期、HELLP、胎盘早剥、死胎、羊水栓塞、原发血液病","子宫过度膨胀与肌瘤、既往剖宫产史、肥胖、贫血、高龄"],"epi":"全球每年约 8 万孕产妇死于产后出血，是最主要可预防的孕产妇死亡原因。我国产后出血仍是孕产妇死亡的前 2 位原因，占孕产妇死亡的 15%–20%；宫缩乏力占病因的 70%–80%。"},"patho":"四大病因以「4T」记忆：Tone（张力，宫缩乏力）、Trauma（创伤，产道裂伤、子宫破裂、血肿）、Tissue（组织，胎盘残留/植入）、Thrombin（凝血，凝血病）。持续出血导致低血容量性休克、组织低灌注，进而引起稀释性凝血病、纤维蛋白原快速消耗（<2 g/L 时出血难止）、酸中毒与低体温，形成「致死性三联征」。","dx":{"criteria":["产后出血量评估：称重法（敷料血量差 1 g≈1 mL）+ 容积法，目测法常低估 30%–50%","失血程度分级：轻度 500–1000 mL 无休克；中度 1000–1500 mL 伴心动过速、脉压减小；重度 >1500 mL 或出现休克指数（心率/收缩压）>1.0","休克指数 ≥1.0 提示失血约 20% 以上，≥1.5 提示中度失血性休克，应启动大量输血准备","胎盘娩出后检查胎盘完整性，缺胎盘小叶或边缘血管断裂提示胎盘残留"],"workup":["生命体征、意识、尿量、休克指数（连续评估，每 5–15 min）","血常规、凝血四项（PT、APTT、纤维蛋白原、D-二聚体）、肝肾功能、电解质、血型与交叉配血","超声：宫腔有无残留、子宫下段及阔韧带有无血肿","软产道与宫颈、阴道穹窿、子宫下段逐段检查排除裂伤和子宫破裂","纤维蛋白原 <2.0 g/L 或 DIC 指标异常提示需尽早补充凝血因子"],"grading":"按失血量分：轻度（500–1000 mL，生命体征稳定）、中度（1000–1500 mL）、重度（>1500 mL 或血流动力学不稳定）；WHO 亦按子宫收缩乏力阶梯处理分为一线（子宫按摩+缩宫素）、二线（其他宫缩剂/氨甲环酸）、三线（压迫、动脉栓塞、B-Lynch 缝合）、四线（子宫切除）。"},"ddx":[{"name":"胎盘早剥（ob_abruption）","point":"与本类 ob_abruption 的鉴别点：胎盘早剥发生在分娩前，伴突发持续性腹痛、板状子宫、胎心异常，阴道流血可为隐性；产后出血发生于胎儿娩出后，腹痛较轻，宫缩乏力时子宫软而大。"},{"name":"子痫前期合并 HELLP（ob_preecl）","point":"与本类 ob_preecl 的鉴别点：HELLP 表现为溶血、转氨酶升高、血小板减少，出血常伴凝血异常但血压与蛋白尿改变更突出；单纯宫缩乏力型 PPH 血小板与肝酶多正常。"},{"name":"不全子宫破裂 / 软产道裂伤","point":"血红蛋白下降伴腹痛加重、胎心减速或进入母体血流不恢复，需阴道手术助产史或瘢痕子宫史，检查见血肿或裂口。"},{"name":"子宫内翻","point":"胎盘娩出后突发剧烈下腹痛、阴道大量出血伴休克，阴道内触及球形肿物、宫底触及不清，需立即手法复位（子宫松弛下）。"},{"name":"凝血功能障碍（羊水栓塞、DIC）","point":"突发呼吸困难、紫绀、抽搐、休克与出血并有，血小板和纤维蛋白原快速下降，发生于产程或产后短时内，病死率极高。"}],"tx":{"drug":[{"name":"缩宫素（催产素）","dose":"预防：胎儿娩出后立即 10 U 肌注或加入 500 mL 生理盐水静脉滴注（10–20 U）；治疗：10 U 肌注 + 10–20 U 加入 500 mL 乳酸林格液静滴，必要时 20–40 U 加入 500–1000 mL 液体中维持","note":"宫缩乏力性产后出血一线用药，可重复；大剂量快速静注可引起低血压（尤其椎管内麻醉后）","renal":"遵说明书","hepatic":"遵说明书","interact":"与麦角新碱、米索前列醇联用可叠加高血压和宫缩过度风险；避免与速效拟交感药同用"},{"name":"卡贝缩宫素","dose":"100 µg 产后单次静脉缓慢推注（1 min 以上）或肌注","note":"长效缩宫素类似物，单次给药；不用于有宫缩剂敏感性阴道分娩禁忌者","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他宫缩剂在大剂量下叠加，可出现胎儿心动过缓（产时）"},{"name":"米索前列醇","dose":"产后出血：800 µg 舌下含服（首选）或 600 µg 口服、或直肠给药；宫缩剂无效时可用","note":"缩宫素无效时首选前列腺素类；舌下吸收快但胃肠反应显著，可致寒战、发热、腹泻","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他前列腺素类合用；青光眼、哮喘、严重心血管病慎用"},{"name":"卡前列素氨丁三醇","dose":"250 µg 肌注（或子宫肌层注射），必要时每 15–90 min 可重复，总量一般不超过 2 mg（8 剂）","note":"子宫收缩作用强，适用于宫缩乏力经缩宫素无效者；哮喘、心脏病患者避免使用（可引起支气管痉挛）","renal":"遵说明书","hepatic":"遵说明书","interact":"不与其他前列腺素合用；慎与主动脉夹层高危、肺动脉高压、子痫前期严重高血压者联用"},{"name":"氨甲环酸","dose":"产后出血确诊或高度怀疑时 1 g 静脉缓慢滴注（>10 min），30 min 内开始最佳；若 30 min 后仍出血或 24 h 内复发出血，可再给 1 g；不推荐超过 2 g/24 h 的常规单次给药方案，需按临床判断","note":"WOMAN 研究显示可减少约 1/3 的产后出血死亡；开腹手术中可用 1 g 局部（生理盐水 100 mL 稀释后胎盘附着面涂抹或灌注）","renal":"eGFR <30 时减量（按说明书），严重肾功能不全慎用大剂量","hepatic":"遵说明书","interact":"与抗凝药同用可能拮抗抗凝效果；可与其他止血措施并用"},{"name":"晶体液与血制品","dose":"首批 500–1000 mL 乳酸林格液快速输注，随后按休克与尿量限制联用；输血按「1:1:1」（红细胞:新鲜冰冻血浆:血小板）大量输血方案，血红蛋白目标 ≥70–80 g/L，纤维蛋白原目标 ≥2.0 g/L","note":"避免过度晶体扩容引起稀释性凝血病与水肿；纤维蛋白原 <2.0 g/L 时补充冷沉淀或纤维蛋白原","renal":"急性肾损伤风险高，注意尿量 ≥0.5 mL/kg/h","hepatic":"遵说明书","interact":"遵说明书"},{"name":"去氧肾上腺素 / 麻黄碱","dose":"去氧肾上腺素 40–100 µg 单次静推（可重复，必要时 25–50 µg/min 泵入）；麻黄碱 5–10 mg 单次静推","note":"用于椎管内麻醉后低血压或容量复苏后仍低血压时维持灌注压，心率慢时选麻黄碱、心率快时选去氧肾上腺素","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与麦角新碱叠加升压效应"}],"nonDrug":["子宫按摩与双手压迫：持续 15–30 min，可与宫缩剂同时进行，每 5 min 重新评估子宫硬度与出血量","子宫压迫缝合（B-Lynch、Hayman、垂直/横向压迫缝合）：宫缩剂+压迫无效且出血仍活跃时，剖宫产或开腹中实施","宫腔填塞（Bakri 球囊、纱布条）：阴道分娩可在产房操作，宫缩剂无效的宫缩乏力型首选之一；24–48 h 后取出","盆腔动脉结扎或经导管动脉栓塞（UAE）：有介入条件的医院，血流动力学相对稳定时优先；栓塞后需监测缺血与再出血","子宫切除：上述手段无效的大出血、胎盘植入或子宫破裂无法修复时，不应延迟决定","如为胎盘残留，在充分宫缩剂与输血准备下行清宫；胎盘植入不强行剥离，转剖宫产+子宫切除或保守处理","关闭创面：软产道裂伤、宫颈裂伤、会阴血肿彻底缝合止血","重症监测：转入重症监护，监测血压、心率、尿量、凝血与血红蛋白，警惕席汉综合征和急性肾损伤"],"life":["产后 2 h 内严密观察宫底高度、阴道流血与生命体征（每 15 min 一次）","补铁与贫血纠正，产后 42 d 复查血红蛋白与铁代谢","再次妊娠间隔建议 >12–18 个月，前次产后出血原因不明者需行产后随访","心理筛查：产后出血与产后抑郁、PTSD 相关，产后 6 周做爱丁堡量表筛查"]},"prog":"宫缩乏力型经子宫按摩+缩宫素+米索前列醇约 80%–90% 可控制；需子宫切除者约占分娩总数 0.05%–0.1%，是产后出血死亡的终末手段。及时识别与早期氨甲环酸显著降低病死率，延迟识别 3 h 以上病死率明显上升。","refs":["中华医学会妇产科学分会产科学组. 产后出血预防与处理指南（2023）","WHO. Postpartum haemorrhage: prevention and treatment (2022)","WOMAN Trial Collaborators. Lancet 2017;389:2105-2116","ACOG Practice Bulletin No. 183: Postpartum Hemorrhage (2017, reaffirmed 2023)"]},{"id":"ob_preecl","name":"子痫前期与子痫","aka":["Preeclampsia","Eclampsia","妊娠期高血压疾病"],"rank":2,"basic":{"define":"子痫前期为妊娠 20 周后新发高血压（≥140/90 mmHg，两次间隔 4 h 以上）伴蛋白尿（≥0.3 g/24 h）或任一器官受累（肾、肝、血液、神经、胎盘）；伴持续性高血压 ≥160/110 mmHg 或有剧烈头痛、视觉症状、上腹痛、肺水肿等为重度。子痫为子痫前期基础上发生不能用其他原因解释的抽搐。","risk":["初产妇、年龄 ≥40 岁、孕前 BMI >30","既往子痫前期或妊娠期高血压病史（复发率约 10%–25%）","多胎妊娠、慢性高血压、肾脏疾病、糖尿病、抗磷脂综合征","辅助生殖妊娠、胎盘异常、家族史","两次妊娠间隔 >10 年、SLE"],"epi":"全球约 2%–8% 的妊娠并发子痫前期，是孕产妇死亡的第二大原因。我国妊娠期高血压疾病患病率约 5%–10%，其中子痫前期约 2%–5%；子痫发生率约 0.2%，东欧/非洲更高。"},"patho":"孕早中期胎盘滋养细胞侵袭不足、胎盘螺旋动脉重塑障碍，导致胎盘缺血缺氧，释放可溶性 Flt-1（sFlt-1）、内皮素等抗血管生成物质，引起全身毛细血管内皮损伤与血管痉挛：外周阻力升高、血管通透性增加（水肿、肺水肿、脑水肿）、微血栓形成与凝血激活。肾脏表现为肾小球内皮增生与蛋白尿；脑部过度灌注导致头痛、视物模糊、抽搐（可逆性后部脑病综合征）。","dx":{"criteria":["妊娠 20 周后血压 ≥140/90 mmHg（间隔 4 h 两次）并有尿蛋白 ≥0.3 g/24 h（或尿蛋白/肌酐 ≥0.3、试纸 ≥2+）","或血压 ≥140/90 mmHg 且伴任一器官受累：血小板 <100×10⁹/L、转氨酶 >2 倍正常上限、肌酐 >1.1 mg/dL（或较基线升高 30%）、肺水肿、新发头痛/视物模糊/上腹部痛","重度子痫前期：≥160/110 mmHg 持续 >15 min，或伴前述中枢神经、肝、肾、肺、血液功能不全表现","子痫：典型抽搐一次或多次，可伴昏迷，排除癫痫、低血糖、脑血管意外等","HELLP 综合征：溶血（LDH ≥600 U/L、外周血涂片见破碎红细胞）、转氨酶升高（AST ≥70 U/L）、血小板 <100×10⁹/L"],"workup":["血压测量（坐位、右臂、休息 5 min 后，袖带合适、两次间隔 4 h），24 h 动态血压必要时","尿蛋白：24 h 定量为首选，或尿蛋白/肌酐比值；试纸法作为筛查","血常规+血小板、肝功（AST/ALT、LDH、胆红素）、肾功能（肌酐、尿素氮、尿酸）、凝血、电解质","胎心监护（NST）、B 超生物物理评分、脐动脉 S/D 与羊水指数评估胎儿","子宫动脉多普勒与 sFlt-1/PlGF 比值可辅助早发型子痫前期风险分层（部分地区可用）","怀疑 HELLP 需乳酸脱氢酶、血浆游离血红蛋白与外周血涂片"],"grading":"按起病时间：早发型（<34 周）与晚发型（≥34 周）；按病情：子痫前期（不伴/伴严重表现）、子痫；HELLP 按 Tennessee 分类（完全型：LDH ≥600 U/L、AST/ALT ≥70 U/L、血小板 <100×10⁹/L；部分型只满足 1–2 项）。"},"ddx":[{"name":"产后出血（ob_pph）","point":"与本类 ob_pph 的鉴别点：子痫前期可有血小板减少和转氨酶升高，但核心为妊娠 20 周后高血压 + 蛋白尿，多数无大量出血；产后出血以失血为主，血压下降，蛋白尿多无。"},{"name":"胎盘早剥（ob_abruption）","point":"与本类 ob_abruption 的鉴别点：胎盘早剥以腹痛与阴道流血为主、子宫呈板状硬、胎心异常，可伴高血压；子痫前期腹痛多在上腹（肝包膜牵张），腹胀且子宫张力正常或轻度增高。"},{"name":"慢性高血压合并妊娠","point":"妊娠 20 周前或孕前已有血压升高，无新发蛋白尿或器官功能进行性恶化；需查血压病史、是否正在用降压药。"},{"name":"妊娠期急性脂肪肝","point":"多发生于孕晚期，持续恶心呕吐、黄疸、低血糖、凝血障碍与肝性脑病，转氨酶升高更明显，血压升高可不显著。"},{"name":"癫痫、低血糖、脑血管意外","point":"子痫多发生于孕晚期或产后 48 h 内，伴高血压与蛋白尿；非妊娠期癫痫或脑血管病需查血糖、头颅影像与神经系统体征。"}],"tx":{"drug":[{"name":"硫酸镁（预防/治疗抽搐）","dose":"负荷 4–6 g（常用 4 g）20% 硫酸镁 20 mL 加入 100 mL 葡萄糖静滴 15–20 min 内完成，随后 1–2 g/h 持续泵入；子痫抽搐持续或复发时可追加 2 g 缓慢静推（5–10 min）或 8–10 mL 20% 硫酸镁加入 10 mL 葡萄糖缓慢静注","note":"重度子痫前期与子痫首选；膝反射存在、呼吸 ≥16 次/分、尿量 ≥25 mL/h 为继续用药条件，每小时监测","renal":"肾功能不全（肌酐 >100 µmol/L 或 eGFR <30）减半量或减慢泵速；急性肾衰竭禁用常规剂量","hepatic":"遵说明书","interact":"与氨基糖苷类、肌肉松弛剂、钙通道阻滞剂合用可加重神经肌肉抑制；与 β 受体激动剂合用可致肺水肿"},{"name":"硫酸镁中毒拮抗：葡萄糖酸钙","dose":"出现呼吸抑制、膝反射消失、心动过缓时立即停药，10% 葡萄糖酸钙 10 mL 缓慢静推（10 min 以上）","note":"中毒早期为膝反射减弱、恶心、面部潮红、口干；血镁 >3.5–5 mmol/L 可致呼吸抑制","renal":"肾功能不全时硫酸镁蓄积风险高，需更频繁监测","hepatic":"遵说明书","interact":"与洋地黄类药物同用钙剂需谨慎（洋地黄中毒风险）"},{"name":"拉贝洛尔","dose":"口服 100–200 mg bid–tid（最大 2400 mg/d）；急性重度高血压：20 mg 静脉缓推（2 min 以上），10 min 后可加倍重复（40、80 mg），一般最大单次 80 mg、总量 300 mg","note":"α/β 受体阻滞剂，一线降压；避免二线单用 β 阻滞剂。哮喘、心动过缓<55 次/分、房室传导阻滞者禁用或慎用","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"与维拉帕米合用增加房室传导阻滞；与硫酸镁合用需监测心率"},{"name":"硝苯地平（缓释片）","dose":"口服 30 mg qd 起始，最大 120 mg/d；急性降压可短效 10 mg 口服（非舌下，30–60 min 起效）","note":"钙通道阻滞剂，用于口服降压替代；与硫酸镁合用注意血压下降过快","renal":"遵说明书","hepatic":"严重肝功能不全减量","interact":"避免与强 CYP3A4 抑制剂（克拉霉素、伊曲康唑）同用；与镁剂合用可致神经肌肉阻滞"},{"name":"甲基多巴","dose":"口服 250 mg bid–tid 起始，最大 2 g/d","note":"孕期长期用药安全性证据充分，可用于慢性高血压；可致嗜睡、口干","renal":"肾功能不全减量","hepatic":"活动性肝病、既往用药相关肝炎禁用；定期查肝功能","interact":"与 MAO 抑制剂合用可致高血压危象，避免"},{"name":"尼卡地平（静脉）","dose":"起始 2.5 mg/h 静脉泵入，每 15 min 可加倍至 5–15 mg/h，最大 15 mg/h","note":"可用于拉贝洛尔禁忌时；需有中心静脉或严密监测","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与其他降压药叠加；避免与强 CYP3A4 抑制剂合用"},{"name":"地塞米松（促胎肺成熟）","dose":"孕 24–34 周且有 7 d 内可能早产风险者：6 mg 肌注 q12h ×4 次（或倍他米松 12 mg 肌注 q24h ×2 次）","note":"用于早发型子痫前期需提前终止妊娠时促胎肺成熟，不用于治疗 HELLP 本身","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"糖皮质激素（HELLP）","dose":"仅用于孕 34 周前促胎肺成熟；大剂量地塞米松推进血小板升高的证据不足，不推荐常规用于治疗 HELLP","note":"HELLP 根本治疗是终止妊娠，激素非一线","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["终止妊娠是子痫前期/子痫的唯一根治手段：≥37 周确诊即终止；34–37 周根据母胎情况决定；<34 周无严重表现可严密监测保守治疗，以促胎肺成熟","出现抽搐、肺水肿、HELLP、胎盘功能衰竭、胎儿窘迫等严重表现时，不因孕周小而延迟终止","子痫抽搐时侧卧位、防误吸、保持气道通畅、吸氧、建立静脉通道，抽搐时避免强行按压；抽搐控制后及时终止妊娠","分娩方式：无产科禁忌且宫颈条件好可引产，胎龄小、胎儿窘迫或宫颈条件不佳时推荐剖宫产","产后监测：产后 48–72 h 是血压高峰，仍需硫酸镁与降压，产后 6 周复查血压、尿蛋白与肾功能","产后高血压可持续或新发（迟发型子痫前期），出院前应宣教头痛、视物模糊、胸闷、抽搐等预警症状"],"life":["低盐饮食但不过度限盐，优质蛋白摄入；控制体重增长","高危及既往子痫前期者，孕 12–16 周起每日阿司匹林 100–150 mg 至孕 36 周预防","补钙：低钙地区每日补钙 1–2 g 可降低子痫前期风险","后续随访：既往子痫前期妇女远期高血压、缺血性心脏病、脑卒中、慢性肾病风险升高 2–4 倍，产后 6 个月与每年血压筛查","如再次妊娠，孕早中期即建档并评估，产后 6 周重新评估心血管风险"]},"prog":"早发型、重度子痫前期与 HELLP 预后较差，母体死亡风险显著升高；围产儿死亡率与孕周相关，因早产与胎盘功能不全。规范产检与及时终止妊娠可将子痫发生率降低 50% 以上；子痫抽搐后母体死亡约 1%，再次妊娠复发率约 15%。","refs":["中华医学会妇产科学分会妊娠期高血压疾病学组. 妊娠期高血压疾病诊治指南（2020）","ACOG Practice Bulletin No. 222: Gestational Hypertension and Preeclampsia (2020)","NICE. Hypertension in pregnancy: diagnosis and management (NG133, 2023 update)","中华医学会妇产科学分会产科学组. HELLP 综合征诊治指南（2015）"]},{"id":"ob_abruption","name":"胎盘早剥","aka":["Placental Abruption","Abruptio Placentae"],"rank":3,"basic":{"define":"妊娠 20 周后至胎儿娩出前，正常位置的胎盘全部或部分从子宫壁剥离，可引起母体出血、休克、DIC 和胎儿窘迫/胎死宫内。","risk":["既往胎盘早剥史（复发率约 10%–15%）","重度子痫前期/妊娠期高血压、慢性高血压","外伤（腹部撞击、摔倒、车祸）、外倒转术、羊膜腔穿刺","羊水过多时突然破膜（宫腔压力骤降）、多胎妊娠","吸烟、可卡因、高龄、经产、胎盘早剥家族史","绒毛膜羊膜炎、胎膜早破、子宫肌瘤尤其是黏膜下肌瘤"],"epi":"发生率约 0.4%–1%，是产科出血性急症之一，约占围产儿死亡的 15%–20%；母体死亡风险较正常妊娠高 7–10 倍，漏诊或延迟处理时更高。"},"patho":"底蜕膜层血管破裂出血，形成胎盘后血肿，血肿增大使胎盘与子宫壁分离，剥离面越大出血越多。血液可经宫颈外流（显性出血），也可积聚在宫腔内（隐性出血，常量可达 1000–2000 mL 以上，常被低估）。血肿刺激子宫肌层致持续强直收缩、胎盘后组织释放凝血活酶激活凝血系统，引起 DIC；广泛剥离致胎儿急性缺氧或死亡。","dx":{"criteria":["妊娠 20 周后突发持续性腹痛（占 70% 以上）、腰背痛、阴道流血（可仅为少量血性分泌物）","子宫张力增高、压痛、呈板状硬；子宫底进行性升高提示宫腔内积血","胎心异常：心动过速、晚期减速、基线变异消失甚至胎心消失","母体血流动力学与出血量不成比例（隐性出血型），可出现休克","超声见胎盘后或胎盘边缘血肿、胎盘增厚（≥5 cm）、胎盘与子宫壁间无回声区；超声阴性不排除","产后检查胎盘母体面见暗红色血块压迫区（压迹）"],"workup":["连续胎心监护（NST/CST），异常需立即决定分娩","超声：胎盘位置与厚度、胎盘后血肿、胎儿情况、羊水","血常规、凝血四项、纤维蛋白原、D-二聚体、肝肾功能、血型与交叉配血","胎儿监护与产科超声同时评估，缩短决策时间","胎盘早剥分级（Sher）：Ⅰ度 少量出血、子宫轻压痛、胎心正常；Ⅱ度 中等出血、子宫有压痛、胎心异常；Ⅲ度 大量出血、休克或 DIC、常伴胎死宫内"],"grading":"Sher 分级（Ⅰ/Ⅱ/Ⅲ度）；Page 分类（显性出血、隐性出血、混合型）；按面积分为轻（<1/3）与重（>1/3 或胎儿窘迫）。"},"ddx":[{"name":"产后出血（ob_pph）","point":"与本类 ob_pph 的鉴别点：胎盘早剥发生于胎儿娩出前，突出持续性腹痛和板状子宫、胎心异常；产后出血发生于胎儿娩出后，宫缩乏力时子宫软大无痛，胎盘已娩出。"},{"name":"子痫前期/子痫（ob_preecl）","point":"与本类 ob_preecl 的鉴别点：子痫前期以高血压+蛋白尿为诊断基础，腹痛多在上腹且呈非持续性，子宫张力正常；胎盘早剥腹痛持续、子宫板状硬、流血与休克不符，可继发于重度子痫前期。"},{"name":"前置胎盘","point":"无诱因无痛性反复阴道流血，胎心多正常，子宫软，超声见胎盘覆盖宫颈内口；胎盘早剥有腹痛与子宫张力增高。"},{"name":"子宫破裂","point":"有剖宫产或子宫手术史，产程中突发撕裂样下腹痛、宫缩停止、胎心异常，腹部可触及胎儿肢体，阴道流血少但内出血重。"},{"name":"急性阑尾炎/泌尿系结石","point":"腹痛位置（转移性右下腹或腰腹绞痛）、无子宫张力增高、无阴道流血，胎心正常，超声可见相应病变。"}],"tx":{"drug":[{"name":"晶体液与血制品（复苏）","dose":"迅速建立 2 条粗静脉通道，先给 500–1000 mL 乳酸林格液，随后按失血量与血红蛋白输注红细胞；纤维蛋白原 <2.0 g/L 补充冷沉淀、纤维蛋白原或新鲜冰冻血浆；大量出血按 1:1:1 输注","note":"隐性出血常至休克才被发现，输血启动不应等到血红蛋白结果回报；目标尿量 ≥0.5 mL/kg/h","renal":"急性肾损伤风险高，监测尿量与肌酐","hepatic":"遵说明书","interact":"遵说明书"},{"name":"氨甲环酸","dose":"确诊或高度怀疑胎盘早剥伴活动性出血时 1 g 静脉缓慢滴注（>10 min），必要时 30 min 后可再给 1 g","note":"用于减少出血，不替代终止妊娠；胎儿娩出前使用需权衡利弊，通常用于母体出血量大时","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"与抗凝药同用可拮抗抗凝效果"},{"name":"宫缩抑制剂（慎用）","dose":"仅用于孕 <34 周、Ⅰ度早剥、胎心正常、母体稳定且需促胎肺成熟时，短程使用：硝苯地平 20 mg 口服（必要时 30 min 后重复），或阿托西班按说明书","note":"Ⅱ度以上、胎儿窘迫、DIC 或母体不稳时禁用宫缩抑制剂；不推荐 β 受体激动剂（加重肺水肿）","renal":"遵说明书","hepatic":"遵说明书","interact":"硝苯地平与硫酸镁合用注意血压下降与神经肌肉阻滞"},{"name":"地塞米松（促胎肺成熟）","dose":"孕 24–34 周且计划 7 d 内分娩者：6 mg 肌注 q12h ×4 次；不可为等待激素完成而延迟剖宫产","note":"母体 DIC 或需紧急分娩时激素不改变时机","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"硫酸镁（胎儿神经保护）","dose":"孕 <32 周预计 24 h 内分娩时：负荷 4 g 静滴 20 min，继以 1 g/h 维持至分娩；母体低血压或肾功不全时减量","note":"用于降低早产儿脑瘫风险，须在母体稳定、无禁忌时使用","renal":"肾功能不全减量并监测膝反射","hepatic":"遵说明书","interact":"与钙通道阻滞剂、氨基糖苷类合用增加神经肌肉抑制"}],"nonDrug":["确诊胎盘早剥后无论胎龄，均应尽快终止妊娠：Ⅰ度 32–34 周以上可在严密监护下短期期待，<34 周可孕 24–34 周观察至促胎肺成熟完成","Ⅱ度以上、胎儿窘迫或母体不稳定：立即剖宫产，不因胎儿死亡而延迟","阴道分娩条件：Ⅰ度、胎心良好、宫颈成熟者可在严密胎心监护下引产，产程中随时转剖宫产","开腹时探查子宫：若子宫卒中（Couvelaire 子宫）但收缩尚可，尽量保留子宫；子宫不收缩、出血不能控制时行子宫切除或压迫缝合","纠正 DIC：补充纤维蛋白原、血小板、新鲜冰冻血浆，纠正酸中毒与低体温","术中术后严密监测凝血、尿量、血红蛋白和休克指标，警惕急性肾损伤与席汉综合征"],"life":["既往胎盘早剥者再次妊娠需提前建档，孕中晚期加强监测血压、胎动与超声","戒烟、避免外伤、控制高血压是主要可干预措施","产后心理评估与哀伤辅导（胎死宫内者）","产后 6 周复查凝血、血压、肾功能；出现疲劳、闭经、低血压/低血糖需排查席汉综合征"]},"prog":"母体死亡率约 1%（隐性出血型更高），围产儿死亡率约 10%–20%，其中Ⅲ度可高达 30%–50%。存活胎儿中约 10%–15% 有神经系统后遗症。及时剖宫产（母体稳定条件下 30 min 内决策至分娩）可显著改善围产结局。","refs":["中华医学会妇产科学分会产科学组. 胎盘早剥诊治指南（2015，2019 修订版）","ACOG Practice Bulletin No. 189: Placental Accreta Spectrum; RCOG Green-top Guideline No. 63: Antepartum Haemorrhage (2011, updated 2022)","FIGO. Placental abruption: best practice advice (2019)"]}]},{"id":"ob_normal","name":"妊娠常见合并症与异常","rank":2,"summary":"妊娠期糖尿病以「饮食运动为基础、血糖监测为判断、胰岛素为主要药物」；异位妊娠强调血 β-hCG 与经阴道超声联合诊断、按是否破裂与生命体征决定手术或药物保守治疗。","compare":[{"diseaseId":"ob_gdm","dx":"孕 24–28 周 75 g OGTT：空腹 ≥5.1 mmol/L、1 h ≥10.0 mmol/L、2 h ≥8.5 mmol/L 任一项即可诊断","key":"无痛、以血糖异常为核心，超声无宫外妊娠证据，母胎多稳定"},{"diseaseId":"ob_ectopic","dx":"停经 + 下腹单侧痛 + 少量阴道流血，血 β-hCG 升高但倍增不良，经阴道超声见宫外妊娠囊或附件包块、宫腔内无孕囊","key":"早期可无症状，破裂时突发撕裂样腹痛+休克+腹膜刺激征，需急诊手术"}],"diseases":[{"id":"ob_gdm","name":"妊娠期糖尿病","aka":["GDM","Gestational Diabetes Mellitus"],"rank":1,"basic":{"define":"妊娠期首次发现或发生的糖代谢异常，未达到显性糖尿病诊断标准者；包括孕前已知糖尿病（PGDM）及妊娠期新发现者。多数在孕 24–28 周筛查时确诊。","risk":["孕前 BMI ≥24（中国标准）、年龄 ≥35 岁","糖尿病家族史（一级亲属）","既往 GDM 史或巨大儿（≥4000 g）分娩史、死胎、先天畸形儿史","多囊卵巢综合征、妊娠期高血压","本次妊娠羊水过多、胎儿大于孕龄、反复外阴阴道假丝酵母菌病"],"epi":"我国 GDM 患病率约 10%–15%，并随孕前肥胖增加而上升；约 50% 的 GDM 产妇产后 10 年内发展为 2 型糖尿病。"},"patho":"妊娠中晚期胎盘分泌的胎盘生乳素、孕激素、皮质醇等具有抗胰岛素作用，加之体重增加与脂肪沉积使胰岛素敏感性下降 50%–60%，若胰岛 β 细胞分泌不能相应代偿则出现高血糖。高血糖经胎盘使胎儿高胰岛素血症，引起巨大儿、新生儿低血糖、新生儿呼吸窘迫综合征及子代远期肥胖/糖尿病风险增加。","dx":{"criteria":["孕 24–28 周（高危者首次产检即查）行 75 g OGTT，三项界值：空腹 ≥5.1 mmol/L、服糖后 1 h ≥10.0 mmol/L、2 h ≥8.5 mmol/L；任一项达到即可诊断 GDM","孕早期空腹血糖 ≥7.0 mmol/L 或 HbA1c ≥6.5%（标准化检测）或随机血糖 ≥11.1 mmol/L 伴症状，诊断显性糖尿病","孕早期空腹血糖 5.1–6.9 mmol/L 亦按 GDM 管理","妊娠期血糖控制目标：空腹 <5.3 mmol/L、餐后 1 h <7.8 mmol/L、餐后 2 h <6.7 mmol/L；HbA1c <6.0%（避免 <5.5% 以减少低血糖）"],"workup":["75 g OGTT（空腹至少 8 h），推荐孕 24–28 周","空腹血糖与 HbA1c（孕早期）","尿酮体、肝肾功能、血脂、甲状腺功能（GDM 常合并甲减）","胎儿超声：生长指标、羊水指数、胎盘；孕晚期评估胎儿生长与巨大儿风险","产后 6–12 周 75 g OGTT 重新分类（产后 6–12 周复查，之后每 1–3 年查一次）"],"grading":"GDM 按是否需要胰岛素分：A1GDM（饮食运动可控制，仅饮食治疗）与 A2GDM（需药物/胰岛素）；White 分类中 A1/A2 为妊娠期糖尿病，B 以上为孕前糖尿病合并妊娠。"},"ddx":[{"name":"异位妊娠（ob_ectopic）","point":"与本类 ob_ectopic 的鉴别点：GDM 无腹痛与阴道流血，β-hCG 倍增规律、宫腔内见孕囊；异位妊娠以腹痛+停经后阴道流血+超声宫外妊娠证据为主。"},{"name":"孕前 1 型或 2 型糖尿病","point":"孕前已诊断或孕早期空腹血糖 ≥7.0 mmol/L、HbA1c ≥6.5%，常伴酮症倾向与并发症（视网膜、肾病），需与 GDM 区分管理强度。"},{"name":"糖尿病酮症酸中毒","point":"血糖 >13.9 mmol/L 伴酮症、酸中毒、脱水与恶心呕吐，可发生在孕中晚期的 GDM 患者，需急诊处理。"},{"name":"妊娠期生理性尿糖","point":"孕期肾糖阈下降可致尿糖阳性而血糖正常，不能凭尿糖诊断 GDM。"}],"tx":{"drug":[{"name":"门冬胰岛素（速效）","dose":"起始 0.1–0.2 U/kg 餐前即刻皮下注射，或按 0.3–0.5 U/kg/d 起分次与基础；根据餐后 1 h 血糖调整，每次 1–2 U 递增","note":"孕期首选胰岛素类似物；进餐时皮下注射，餐后血糖监测","renal":"肾功能不全需减量，监测低血糖","hepatic":"肝功能不全减量","interact":"与 β 受体阻滞剂同用掩盖低血糖症状；与糖皮质激素合用需增加剂量"},{"name":"中性鱼精蛋白（NPH）或地特胰岛素（基础）","dose":"起始 0.1–0.2 U/kg 睡前皮下注射；按空腹血糖每升高 1 mmol/L 增加 0.1–0.2 U/kg 或按需 2–4 U 上调","note":"与餐时胰岛素联用；地特胰岛素孕期安全性证据充分","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"同胰岛素类；避免与其他胰岛素混用不同品牌"},{"name":"二甲双胍","dose":"500 mg bid 起始（餐后服），可逐渐增至 1000 mg bid；国内指南不推荐作为孕期一线，仅在胰岛素不足或拒绝胰岛素、知情同意下使用","note":"可透过胎盘，长期子代安全性证据有限；我国多数中心以胰岛素为首选","renal":"eGFR <45 禁用，eGFR 45–59 减量","hepatic":"肝功能不全（转氨酶 >2 倍 ULN）禁用","interact":"碘造影剂检查前后停用；与酒精合用增加乳酸酸中毒"},{"name":"格列本脲","dose":"2.5 mg qd 起始，早餐前服，逐渐增至 5–10 mg/d（最大 20 mg/d）；国内不作为常规推荐","note":"妊娠期可跨越胎盘但胎儿低血糖风险低于胰岛素；中国指南不推荐常规使用","renal":"肾功能不全慎用，低血糖风险增加","hepatic":"严重肝功能不全禁用","interact":"与磺胺类、水杨酸类合用增加低血糖风险"}],"nonDrug":["饮食：总热量 25–30 kcal/kg（理想体重），碳水化合物占 50%–60%、蛋白质 15%–20%、脂肪 25%–30%，少量多餐（3 主餐 + 2–3 次加餐）","运动：每周 ≥150 min 中等强度有氧（步行、孕妇瑜伽），餐后 30 min 步行 20–30 min 可降低餐后血糖","血糖自我监测：诊断后每日 4 次（空腹 + 三餐后 1–2 h），如稳定可减少至每周数天","孕晚期胎儿监测与超声评估生长；巨大儿（估计 >4.5 kg）考虑剖宫产","产后 6–12 周 OGTT 复查，之后每 1–3 年筛查","GDM 产后哺乳可降低子代 2 型糖尿病风险，应鼓励"],"life":["孕前 BMI ≥24 者孕前减重 5%–10% 可降低 GDM 风险","产后体重管理与运动，预防 2 型糖尿病","再次妊娠前复查血糖，孕早期即筛查","妊娠期血糖控制目标与监测频率按个体化；HbA1c 目标 <6.0%（不伴低血糖）","产后随访包括新生儿血糖监测（出生后 1、2、4、6 h）"]},"prog":"经饮食运动管理约 70%–80% 的 GDM 可达标；10%–20% 需胰岛素。GDM 孕妇子痫前期、剖宫产率、巨大儿率均升高；子代出生后低血糖、高胆红素血症风险增加。良好控制可将围产儿并发症显著降低。","refs":["中华医学会妇产科学分会产科学组. 妊娠合并糖尿病诊治指南（2014，2022 修订版）","ADA. Standards of Care in Diabetes—2024: Management of Diabetes in Pregnancy","ACOG Practice Bulletin No. 190: Gestational Diabetes Mellitus (2018, reaffirmed 2022)","中国医师协会妇产科医师分会. 妊娠期高血糖诊治指南（2023）"]},{"id":"ob_ectopic","name":"异位妊娠","aka":["Ectopic Pregnancy","宫外孕"],"rank":2,"basic":{"define":"受精卵在子宫体腔以外着床，以输卵管妊娠最常见（约 95%，壶腹部居多），也可发生在卵巢、宫颈、腹腔、剖宫产切口瘢痕。破裂可致致命性腹腔内出血。","risk":["盆腔炎性疾病/沙眼衣原体感染史","既往输卵管手术史（结扎、复通）与输卵管妊娠史","宫内节育器使用、辅助生殖技术（ART）","吸烟、年龄 >35 岁","子宫内膜异位症、重复异位妊娠（复发风险约 10%–25%）"],"epi":"我国异位妊娠占妊娠总数约 1%–2%，是早孕期母体死亡的首位原因；及时院前救治可使死亡率降至 <0.1%，延误诊断可升至 10% 以上。"},"patho":"受精卵因输卵管结构或功能异常未能及时进入宫腔，在输卵管壶腹部/峡部着床。着床后滋养细胞侵入管壁，胚胎继续发育使管腔膨胀，管壁缺乏蜕膜保护，至 6–8 周因绒毛侵蚀、管壁破裂，导致腹腔内大出血。输卵管妊娠流产时也可经伞端流入腹腔。","dx":{"criteria":["停经（约 6–8 周，部分患者无明显停经）、阴道少量不规则流血（暗红色、量少、持续数天）、腹痛（单侧、钝痛或撕裂样剧痛）","血 β-hCG：与正常宫内孕比较，48 h 倍增 <66%、或平台/下降提示异位妊娠；单次 β-hCG ≥1500–2000 IU/L（经阴道超声）而宫腔内无孕囊，高度提示异位","经阴道超声：宫腔内未见孕囊、见附件区包块或宫外妊娠囊（超声「甜甜圈征」）、盆腔积液/积血；宫内有孕囊也不能完全排除同时异位（异位双胎）","破裂型：血压下降、心率增快、腹部压痛与反跳痛、移动性浊音、后穹窿穿刺抽出不凝血","血型与 Rh 阴性者需备抗 D 免疫球蛋白"],"workup":["血 β-hCG 定量（24–48 h 复查动态变化）与孕酮（异位妊娠孕酮常 <15 ng/mL）","经阴道超声（比经腹部超声更敏感）","血常规、凝血、血型与交叉配血、肝肾功能","腹腔穿刺或后穹窿穿刺（不稳定者）以及剖腹探查前评估","胸片与心电图（术前）"],"grading":"按位置分类：输卵管（壶腹部、峡部、伞部、间质部）、卵巢、宫颈、腹腔、剖宫产瘢痕；间质部与剖宫产瘢痕妊娠破裂出血更多，风险最高。按状态：未破裂型与破裂型（血流动力学不稳定）。"},"ddx":[{"name":"妊娠期糖尿病/宫内早孕（ob_gdm）","point":"与本类 ob_gdm 的鉴别点：GDM 与正常宫内孕无腹痛及阴道流血，β-hCG 48 h 倍增良好、超声宫腔内可见孕囊；异位妊娠为停经+腹痛+流血，宫腔空虚、附件见包块。"},{"name":"黄体破裂或卵巢囊肿破裂","point":"常发生在月经周期后半段（黄体期），突发下腹痛伴腹膜刺激征，但 β-hCG 阴性，多无停经史。"},{"name":"早期流产（难免流产）","point":"阴道流血量多，伴下腹阵发性痛，超声见宫内孕囊变形/下移、宫颈口扩张；β-hCG 下降模式与异位相似时依靠超声定位。"},{"name":"盆腔炎性疾病/阑尾炎","point":"发热、脓性分泌物或转移性右下腹痛、白细胞升高，无停经及 β-hCG 升高（需排除合并妊娠）。"},{"name":"卵巢扭转","point":"突发一侧下腹剧痛伴恶心呕吐，超声见增大的卵巢、血流信号减少，β-hCG 阴性。"}],"tx":{"drug":[{"name":"甲氨蝶呤（MTX）","dose":"单次方案：50 mg/m² 肌注（按体表面积计算），第 4、7 天测 β-hCG，下降 <15% 予第 2 剂；多剂量方案（1 mg/kg 肌注 d1、3、5、7，隔日亚叶酸钙 0.1 mg/kg 肌注 d2、4、6、8），需监测血常规、肝功能","note":"适应证：血流动力学稳定、无破裂、包块 <3.5–4 cm、β-hCG <3000–5000 IU/L、无胎心搏动、肝肾功能与血象正常；期间避免叶酸、NSAIDs、酒精与日晒","renal":"eGFR <30 禁用或减量；肌酐 >1.5 mg/dL 不推荐使用","hepatic":"活动性肝病禁用，AST/ALT >2 倍 ULN 慎用","interact":"NSAIDs（尤其布洛芬）增加毒性；避免与氟尿嘧啶、磺胺类、四环素、丙磺舒同用"},{"name":"米非司酮","dose":"国内部分机构用于异位妊娠药物保守治疗，与 MTX 联用 50 mg 口服 bid（小样本），按机构方案执行","note":"循证证据有限，非一线；用药后需密切监测 β-hCG 与超声，出现腹痛加重提示可能破裂","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 MTX 合用风险叠加，注意监测"},{"name":"Rh 免疫球蛋白（抗 D）","dose":"Rh 阴性且未致敏者，妊娠早期流产/异位妊娠处理后 72 h 内肌注 250–300 µg（国内常用 250–300 µg）","note":"预防 Rh 同种免疫","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["血流动力学不稳定或破裂：立即行腹腔镜或开腹输卵管切除术，同时复苏与输血","未破裂、有生育要求且输卵管损伤轻：腹腔镜输卵管切开取胚术（保留输卵管），术后监测 β-hCG","期待疗法：仅适用于 β-hCG <200 IU/L 并稳定下降、包块小、无症状者，需每周监测至阴性","剖宫产瘢痕妊娠：多学科评估（妇产、介入、超声），可行子宫动脉栓塞后清宫或 MTX 预处理，严禁盲目清宫","间质部妊娠/宫颈妊娠：出血风险高，需介入下处理并备血"],"life":["治疗后每周测 β-hCG 至正常（MTX 后 2–3 周内多数转阴）","术后 1–3 个月内避免妊娠，规律随访","再次妊娠需孕早期超声确认宫内孕（复发风险 10%–25%）","心理支持与生育指导"]},"prog":"早期诊断者 MTX 治疗成功率约 80%–90%；诊治延误与破裂出血仍为孕产妇死亡首要原因。输卵管切除后再次宫内妊娠率约 50%–60%，保留输卵管者异位复发风险稍高。","refs":["中华医学会妇产科学分会. 异位妊娠诊治专家共识（2017，2022 更新）","ACOG Practice Bulletin No. 193: Tubal Ectopic Pregnancy (2018, reaffirmed 2023)","NICE. Ectopic pregnancy and miscarriage: diagnosis and initial management (NG126, 2023)","WHO. Guideline on the management of ectopic pregnancy (2021)"]}]},{"id":"gyn_tumor","name":"妇科肿瘤","rank":3,"summary":"宫颈癌以 HPV 筛查+阴道镜活检分级，早中期手术/放疗为主；子宫内膜癌以绝经后出血为线索，内膜活检确诊、手术分期为基石；卵巢肿瘤以超声与 CA125 评估风险，恶性者行肿瘤细胞减灭术+铂类化疗。","compare":[{"diseaseId":"ob_cervical","dx":"HPV 持续感染相关，阴道流血（接触性出血）、分泌物增多；宫颈细胞学/HPV 异常经阴道镜活检病理确诊，FIGO 分期","key":"宫颈原发病灶 + 阴道镜活检证实鳞癌/腺癌，HPV 高危型多阳性"},{"diseaseId":"ob_endo_ca","dx":"绝经后阴道流血或围绝经期异常子宫出血，超声内膜厚度 >4 mm（绝经后）时行内膜活检确诊","key":"病变位于宫腔内子宫内膜，诊断性刮宫/宫腔镜活检为确诊手段"},{"diseaseId":"ob_ovarian","dx":"盆腔包块伴腹胀、腹水，超声见复杂囊实性包块、CA125 与 HE4 升高，RMI 评估；确诊依赖手术病理","key":"附件区包块 + CA125 升高 + 腹水，多为上皮性卵巢癌"}],"diseases":[{"id":"ob_cervical","name":"子宫颈癌","aka":["Cervical Cancer","宫颈癌"],"rank":1,"basic":{"define":"发生于子宫颈上皮的恶性肿瘤，主要为鳞状细胞癌（约 70%–80%）与腺癌（约 15%–20%），与高危型人乳头瘤病毒（HPV，主要为 16、18 型）持续感染密切相关，通过癌前病变（CIN）逐步进展。","risk":["高危型 HPV 持续感染（16、18 型为主）","多个性伴侣、首次性生活年龄 <18 岁、性传播感染史","免疫抑制（HIV、器官移植后免疫抑制）","吸烟（含二手烟）","多次妊娠分娩、长期口服避孕药、从不筛查或筛查间隔过长"],"epi":"全球每年新发约 60 万例、死亡约 34 万例，是我国女性生殖系统最常见的恶性肿瘤，年新发约 11 万例、死亡约 6 万例；我国发病率自 30 岁起上升，40–60 岁为高峰，近年年轻化趋势明显。"},"patho":"HPV E6/E7 蛋白分别降解 p53 与 pRb，使细胞周期失控、基因组不稳定，宫颈上皮在持续感染下经历 CIN1→CIN2/3→浸润癌的多阶段过程（平均 10–15 年）。浸润癌突破基底膜后经淋巴管转移至盆腔、腹主动脉旁淋巴结；腺癌易发生卵巢转移与腹腔播散。","dx":{"criteria":["有性生活的女性 21 岁起或 25 岁起筛查（我国推荐 25–64 岁），HPV 检测 + 细胞学（TCT）联合筛查","细胞学异常（ASC-US 以上）或 HPV16/18 阳性→阴道镜检查+活检；活检 CIN2 及以上需治疗并除外浸润癌","确诊依赖宫颈组织病理学，需明确组织学类型、分级与浸润深度、脉管间隙浸润","FIGO 2018 分期：Ⅰ期局限于宫颈（ⅠA 间质浸润深度 ≤5 mm、宽度 ≤7 mm；ⅠB 为浸润深度 >5 mm 或宽度 >7 mm）；Ⅱ期 超出子宫但未达盆壁/阴道下 1/3；Ⅲ期 累及阴道下 1/3 或盆壁/肾盂积水无功能肾/盆腔或腹主动脉旁淋巴结转移；Ⅳ期 侵犯膀胱/直肠黏膜（ⅣA）或远处转移（ⅣB）","影像分期依据：盆腔与腹主动脉旁淋巴结评估、膀胱/直肠受累评估"],"workup":["妇科检查：宫颈外观、触诊肿块大小与穹窿受累、三合诊评估宫旁组织","宫颈活检（多点咬检）、宫颈管搔刮，必要时锥切（LEEP/冷刀锥切）以明确浸润深度","盆腔+腹主动脉旁 MRI 或 PET-CT 评估宫旁、淋巴结与远处转移","胸腹盆 CT 评估腹腔与肺转移","SCC-Ag 与 CA125 基线（鳞癌与腺癌），用于随访","血常规、肝肾功能、HIV 检测，必要时膀胱镜/肠镜"],"grading":"FIGO 2018 分期（ⅠA1–ⅢC2、ⅣA/ⅣB）；组织学分级 G1–G3；鳞癌用 SCC-Ag 随访，腺癌用 CA125。"},"ddx":[{"name":"子宫内膜癌（ob_endo_ca）","point":"与本类 ob_endo_ca 的鉴别点：宫颈癌出血多为接触性（性生活后）、宫颈可见病灶或呈菜花状，阴道镜活检阳性；子宫内膜癌出血来自宫腔，宫颈外观正常，诊刮/宫腔镜内膜活检确诊，多为绝经后女性。"},{"name":"卵巢肿瘤（ob_ovarian）","point":"与本类 ob_ovarian 的鉴别点：卵巢癌以附件区包块、腹水、CA125/HE4 升高为主，宫颈多为正常；宫颈癌以宫颈原发病灶与 HPV 阳性为核心，转移至卵巢者少见。"},{"name":"宫颈鳞状上皮内病变（CIN）","point":"癌前病变，诊断性锥切后无基底膜突破、无间质浸润；早期浸润癌（ⅠA）需以锥切标本病理明确。"},{"name":"宫颈炎、宫颈息肉、黏膜下肌瘤脱出","point":"反复接触性出血但活检无恶性；息肉可摘除送病理，肌瘤可见蒂部连于宫颈管可触及。"}],"tx":{"drug":[{"name":"顺铂（同步放化疗）","dose":"放疗期间每周 40 mg/m² 静脉滴注（单次最大 70 mg），共 5–6 周","note":"局部晚期（ⅡB–ⅣA）标准方案为同步放化疗；需充分水化、止吐与监测肾功能","renal":"eGFR <60 慎用或减量，<30 禁用；顺铂主要经肾排泄，监测肌酐与镁","hepatic":"肝功能不全慎用","interact":"与氨基糖苷类、两性霉素 B 合用增加肾毒性；与袢利尿剂合用加重耳毒性"},{"name":"紫杉醇+顺铂（或卡铂）","dose":"紫杉醇 135–175 mg/m² + 顺铂 50–75 mg/m²（或卡铂 AUC 5）静脉滴注，q3w，4–6 周期","note":"用于复发/转移或ⅠB2–ⅡA2 期辅助/新辅助；紫杉醇需预处理防过敏","renal":"卡铂替代顺铂可降低肾毒性；紫杉醇经胆汁排泄，肾功能不全通常无需调整","hepatic":"紫杉醇在胆红素 >1.5 倍 ULN 或转氨酶 >10 倍 ULN 禁用；胆红素 1.5–3 倍需减量","interact":"紫杉醇与酮康唑、红霉素等 CYP3A4 抑制剂合用增加毒性；与顺铂联用有叠加神经毒性"},{"name":"帕博利珠单抗（PD-1 抑制剂）","dose":"200 mg 静脉滴注 q3w 或 400 mg q6w，用于 PD-L1 阳性（CPS ≥1）复发/转移期一线联合化疗","note":"用药期间监测免疫相关不良反应（甲状腺、肺炎、结肠炎、肝损）","renal":"轻中度无需调整，重度数据有限","hepatic":"重度肝功能不全慎用","interact":"与免疫抑制剂同用可能降低疗效；避免在严重感染活动期使用"},{"name":"贝伐珠单抗","dose":"15 mg/kg 静脉滴注 q3w，联合化疗用于复发/转移性宫颈癌","note":"禁用于近期咯血、手术创面未愈或瘘管形成者；用药前需控血压","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗血小板/抗凝药同用增加出血风险"},{"name":"重组人粒细胞集落刺激因子（G-CSF）","dose":"化疗后中性粒细胞 <1.0×10⁹/L 时 5 µg/kg 皮下注射 qd，至中性粒细胞恢复","note":"预防/治疗化疗后粒细胞减少","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["癌前病变（CIN2/3）：LEEP 或冷刀锥切，保留生育功能；切缘阳性者 4–6 个月复查","早期（ⅠA–ⅠB1、ⅡA1）：广泛子宫切除+盆腔淋巴结切除（或前哨淋巴结活检），年轻者可保留卵巢；有生育要求者 ⅠA1 无脉管浸润、ⅠB1（≤2 cm）可考虑保留生育的广泛宫颈切除/锥切","局部晚期（ⅠB2–ⅣA）：同步放化疗（体外放疗+腔内近距离放疗）为标准，5 年生存率约 60%–70%","复发/转移：一线化疗联合 PD-1 抑制剂与贝伐珠单抗，二线可选 Tisotumab vedotin 等","放疗并发症：放射性肠炎、膀胱炎、阴道狭窄，需阴道扩张器定期扩张","术后随访：治疗结束后 2 年内每 3–4 个月复查妇科检查、细胞学/HPV、SCC-Ag 与影像"],"life":["筛查是主要预防手段：25–64 岁 HPV 检测每 5 年或细胞学每 3 年（联合筛查每 5 年）","HPV 疫苗：9–45 岁女性可接种，最佳接种年龄 9–14 岁，二价/四价/九价在预防效果上均可降低宫颈癌风险","戒烟、安全性行为、避免过早性生活","术后 1 年内避免提重物与性交；盆底肌锻炼与性心理咨询","保留生育的年轻患者需谨慎评估并密切随访"]},"prog":"Ⅰ期 5 年生存率约 90%，Ⅱ期约 70%–75%，Ⅲ期约 45%–60%，Ⅳ期约 15%–20%。筛查覆盖良好的地区发病率显著下降；我国两癌筛查项目已覆盖多数适龄妇女，年轻化与腺癌比例上升是需要关注的变化。","refs":["中华医学会妇科肿瘤学分会. 子宫颈癌诊断与治疗指南（2021 版）","国家卫生健康委员会. 子宫颈癌筛查工作方案（2022）","FIGO Cancer Report 2021: Cervical Cancer Staging","NCCN Guidelines: Cervical Cancer, Version 2.2024","WHO. Global strategy to accelerate the elimination of cervical cancer (2020)"]},{"id":"ob_endo_ca","name":"子宫内膜癌","aka":["Endometrial Cancer","子宫内膜样腺癌"],"rank":2,"basic":{"define":"起源于子宫内膜上皮的恶性肿瘤，以子宫内膜样腺癌最常见（约 80%），分为雌激素依赖型（Ⅰ型，多发生于肥胖、绝经后，预后好）与非雌激素依赖型（Ⅱ型，多见浆液性癌、透明细胞癌，恶性度高）。","risk":["肥胖、糖尿病、高血压（「三联征」）与代谢综合征","长期无排卵（多囊卵巢综合征）、初潮早、绝经晚、未育","长期雌激素替代治疗（无孕激素拮抗）、他莫昔芬使用","林奇综合征（MLH1/MSH2/MSH6/PMS2 胚系突变），内膜癌是其主要表现之一","年龄 ≥55 岁、既往盆腔放疗史"],"epi":"发病率居我国女性生殖系统恶性肿瘤第 2 位，且逐年上升，年新发达 8 万例以上；多数为绝经后女性，平均发病年龄约 60 岁，40 岁以下仅约 5%。"},"patho":"Ⅰ型：长期无孕激素拮抗的雌激素刺激使内膜增生→非典型增生→癌变，PTEN、PIK3CA、KRAS 等基因突变常见，早期局限于内膜、生长缓慢。Ⅱ型：起源于萎缩性子宫内膜，p53 突变常见，侵袭性强、早期即可发生腹腔与淋巴结转移。内膜癌转移主要经淋巴道（至盆腔与腹主动脉旁淋巴结）与腹腔种植。","dx":{"criteria":["绝经后阴道流血（占 90% 以上），或围绝经期异常子宫出血、月经紊乱伴内膜增厚","绝经后阴道超声内膜厚度 >4–5 mm 需进一步评估，>10 mm 高度可疑；内膜不均匀、血流信号丰富需警惕","确诊依赖子宫内膜活检：门诊内膜取样（Pipelle）或诊断性刮宫+宫腔镜直视活检","FIGO 2009 分期（手术病理分期）：Ⅰ期 局限于子宫；Ⅱ期 侵犯宫颈间质；Ⅲ期 局部或区域扩散（ⅢA 侵及浆膜层/附件，ⅢB 阴道/宫旁，ⅢC 淋巴结转移）；Ⅳ期 膀胱/直肠黏膜侵犯或远处转移","分子分型（2020 WHO/TCGA）：POLE 超突变型（预后最好）、微卫星不稳定型（拷贝数低）、低拷贝数型（p53 野生型）、高拷贝数型（p53 异常，预后最差）"],"workup":["妇科检查、经阴道/经腹超声（内膜厚度、肌层浸润、宫颈受累）","盆腔 MRI 评估肌层浸润深度、宫颈间质侵犯与淋巴结","CA125（尤其浆液性癌与晚期病例）、胸腹盆 CT 评估远处转移","分子检测：MMR/MSI、p53、POLE（部分中心常规开展）及胚系检测（<60 岁或有家族史者排查林奇综合征）","术前评估：心肺功能、凝血、血常规与肝肾功能"],"grading":"FIGO 2009 手术分期；组织学分级 G1–G3（基于实性生长区比例：≤5%、6%–50%、>50%）；子宫内膜样癌还可按分子分型分层。"},"ddx":[{"name":"子宫颈癌（ob_cervical）","point":"与本类 ob_cervical 的鉴别点：内膜癌以宫腔内病变为主、绝经后出血、宫颈外观正常或仅为癌组织自颈口溢出；宫颈癌有接触性出血、可见宫颈病灶、HPV 阳性、阴道镜活检确诊。"},{"name":"卵巢肿瘤（ob_ovarian）","point":"与本类 ob_ovarian 的鉴别点：卵巢癌以附件包块、腹水、CA125/HE4 升高为主，内膜可正常或萎缩；内膜癌主要表现异常子宫出血，超声见内膜增厚，附件多正常。"},{"name":"子宫内膜增生（非典型增生）","point":"癌前病变，宫腔镜或诊刮后病理见腺体拥挤、结构复杂但无间质浸润；确诊内膜癌需病理见浸润，切缘评估需靠连续切片。"},{"name":"子宫内膜息肉、萎缩性阴道炎出血","point":"超声见宫腔内高回声团、血流不丰富，宫腔镜/诊刮病理为良性息肉；萎缩性内膜出血多量少、内膜薄（<4 mm）。"},{"name":"子宫黏膜下肌瘤变性","point":"超声见边界清晰的低回声结节、血流环绕，无内膜增厚与异常出血的典型表现，活检可排除。"}],"tx":{"drug":[{"name":"紫杉醇+卡铂","dose":"紫杉醇 175 mg/m² + 卡铂 AUC 5–6 静脉滴注 q3w，3–6 周期；用于Ⅲ–Ⅳ期或高危Ⅰ–Ⅱ期辅助治疗","note":"内膜癌标准一线化疗；需预处理防紫杉醇过敏","renal":"卡铂按 Calvert 公式根据 eGFR 调整；eGFR <30 慎用","hepatic":"紫杉醇在胆红素 >1.5 倍 ULN 或 AST >10 倍 ULN 禁用","interact":"紫杉醇与 CYP3A4 抑制剂合用增加毒性；卡铂避免与氨基糖苷类同用"},{"name":"甲地孕酮/醋酸甲羟孕酮","dose":"甲地孕酮 160 mg qd 或甲羟孕酮 200–400 mg qd 口服；用于激素受体阳性复发/转移期或年轻早期患者保留生育的孕激素治疗","note":"仅用于雌激素受体/孕激素受体阳性、低级别内膜样癌；保留生育者 6 个月复查内膜活检评估","renal":"遵说明书","hepatic":"肝功能不全慎用；注意血栓栓塞风险","interact":"与利福平、苯妥英等酶诱导剂合用降低疗效；与华法林合用影响凝血"},{"name":"来曲唑","dose":"2.5 mg qd 口服；用于激素受体阳性复发/转移期或保留生育辅助","note":"芳香化酶抑制剂，绝经后或联合 GnRH-a 时使用","renal":"重度肾功能不全慎用","hepatic":"严重肝功能不全减量","interact":"与强 CYP3A4 抑制剂合用增加血药浓度"},{"name":"帕博利珠单抗（dMMR/MSI-H）","dose":"200 mg 静脉滴注 q3w 或 400 mg q6w，用于 dMMR/MSI-H 复发/转移性内膜癌","note":"用于检测为 dMMR/MSI-H 的患者，二线或一线联合化疗","renal":"轻中度无需调整","hepatic":"重度数据有限","interact":"免疫相关不良反应需激素处理；避免与免疫抑制剂同用"},{"name":"仑伐替尼+帕博利珠单抗","dose":"仑伐替尼 20 mg qd 口服 + 帕博利珠单抗 200 mg q3w，用于 pMMR 复发/晚期内膜癌","note":"需监测高血压、蛋白尿、手足综合征与甲状腺功能","renal":"仑伐替尼重度肾功能不全慎用","hepatic":"仑伐替尼肝功能不全减量","interact":"仑伐替尼与强 CYP3A4 抑制剂合用需减量"}],"nonDrug":["全子宫+双附件切除+盆腔/腹主动脉旁淋巴结评估（前哨淋巴结活检）为标准术式；深肌层浸润或高级别者行分期手术","早期低危（ⅠA 高分化、无肌层浸润）可仅行单纯子宫切除+双侧附件切除，不必系统淋巴结清扫","Ⅱ期（宫颈间质受累）行广泛子宫切除+淋巴结清扫，或放疗","高危（Ⅲ期以上、浆液性癌、p53 异常）术后辅助化疗±放疗","无法手术（高龄、合并症多）者行单纯放疗或新辅助化疗后手术","年轻早期（ⅠA G1、无肌层浸润）有生育要求者，可在严密监测下用孕激素保守治疗 6–9 个月，缓解后尽快妊娠","随访：术后 2–3 年内每 3–6 个月复查妇科检查、CA125、盆腔超声/CT"],"life":["控制体重、治疗糖尿病与高血压（降低复发与死亡风险）","避免无孕激素拮抗的雌激素替代治疗；需激素治疗者加用孕激素","林奇综合征家系行胚系基因检测与早期筛查","术后盆底康复、淋巴水肿防护与性功能恢复指导","心理支持与长期生存随访（合并症管理）"]},"prog":"多数为早期（Ⅰ期约占 70%），5 年总生存率约 80%–90%；Ⅲ期约 60%，Ⅳ期约 20%–25%。浆液性癌与 p53 异常型预后明显较差。分子分型已成为指导辅助治疗与预后的重要依据。","refs":["中华医学会妇科肿瘤学分会. 子宫内膜癌诊断与治疗指南（2023 版）","FIGO Cancer Report 2023: Endometrial Cancer","NCCN Guidelines: Uterine Neoplasms, Version 2.2024","ESGO/ESTRO/ESP Guidelines for the Management of Patients with Endometrial Carcinoma (2021)"]},{"id":"ob_ovarian","name":"卵巢肿瘤","aka":["Ovarian Tumor","Ovarian Cancer","卵巢癌"],"rank":3,"basic":{"define":"卵巢来源的肿瘤，分为上皮性（约 90%，含浆液性、黏液性、子宫内膜样、透明细胞癌）、生殖细胞、性索间质与转移性肿瘤。上皮性卵巢癌起病隐匿，约 70% 发现时已为晚期。","risk":["BRCA1/BRCA2 胚系突变（BRCA1 终生风险约 40%–50%，BRCA2 约 15%–25%）","家族史（卵巢癌、乳腺癌、林奇综合征）、未育与初潮早/绝经晚","子宫内膜异位症（与透明细胞癌、子宫内膜样癌相关）","年龄 ≥50 岁、肥胖、长期无排卵","保护因素：多次妊娠、长期口服避孕药、哺乳、输卵管结扎"],"epi":"我国年新发约 6 万例，死亡约 3.5 万例，死亡率居妇科恶性肿瘤首位；以 50–70 岁为高峰，上皮性卵巢癌中约 70% 为 FIGO Ⅲ–Ⅳ期。"},"patho":"多数高级别浆液性癌起源于输卵管上皮（STIC），经输卵管伞端脱落种植于卵巢表面与腹膜，早期即可发生腹腔内播散，腹水是典型表现。黏液性癌多由良性囊腺瘤逐步演变；生殖细胞肿瘤多见于年轻女性，生长快但化疗敏感度高。卵巢癌转移以腹腔种植与淋巴转移为主，血行转移少见。","dx":{"criteria":["盆腔包块伴腹胀、食欲下降、腹围增大、腹痛、消瘦（非特异，常被误为消化不良）","经阴道超声：复杂囊实性包块、分隔厚 >3 mm、实性成分、腹水、血流阻力指数低；卵巢恶性肿瘤风险指数（RMI）= CA125 × 绝经状态（M）","CA125 升高（>35 U/mL）与 HE4 联合（ROMA 评分）提高特异性；CA125 受子宫内膜异位症、妊娠、PID 影响","确诊依赖手术切除标本的病理，腹水细胞学见腺癌细胞提示腹膜播散","FIGO 2014 分期（手术分期）：Ⅰ期 局限于卵巢；Ⅱ期 盆腔扩散；Ⅲ期 盆腔外腹膜/腹水/腹膜后淋巴结转移；Ⅳ期 远隔转移（含胸膜腔积液伴细胞学阳性、肝实质转移）"],"workup":["妇科检查与经阴道/经腹超声（三维、血流），必要时盆腔 MRI","CA125、HE4 与 CEA、AFP、β-hCG（年轻女性加查）、LDH","胸腹盆增强 CT 评估腹膜、大网膜、肝肺与淋巴结；PET-CT 用于可疑复发","胃肠镜或 CA19-9/CEA 异常时排除胃肠道转移（Krukenberg 瘤）","BRCA1/2 胚系与肿瘤 HRD 检测（指导 PARP 抑制剂）","腹水穿刺细胞学（可辅助诊断）；腹水大量者术前判断"],"grading":"FIGO 2014 分期；组织学分级 G1–G3；RMI≥200 或 IOTA 模型提示恶性可能；上皮性卵巢癌按分子亚型（高级别浆液性、低级别浆液性、黏液性、子宫内膜样、透明细胞）区分。"},"ddx":[{"name":"子宫内膜癌（ob_endo_ca）","point":"与本类 ob_endo_ca 的鉴别点：内膜癌以异常子宫出血、内膜增厚为主要表现，卵巢多正常；卵巢癌以附件包块、腹水、CA125/HE4 升高为主，出血多非主要症状。"},{"name":"子宫颈癌（ob_cervical）","point":"与本类 ob_cervical 的鉴别点：宫颈癌有宫颈原发病灶、HPV 阳性、接触性出血；卵巢癌附件包块为主，宫颈正常（需排除宫颈腺癌转移至卵巢）。"},{"name":"卵巢良性囊肿（卵泡囊肿、黄体囊肿、子宫内膜异位囊肿）","point":"超声见薄壁、单房、无实性成分，CA125 多正常或轻度升高；行 6–8 周随访或超声联合 ROMA 评估，恶性特征明显者手术。"},{"name":"卵巢巧克力囊肿（子宫内膜异位症）","point":"超声见均质内异液囊肿（「毛玻璃」样），伴痛经与不孕史，CA125 轻中度升高，需结合病史与影像特征鉴别。"},{"name":"胃肠道转移癌（Krukenberg 瘤）与肝硬化腹水","point":"双侧卵巢实性包块 + 消化道症状/CA19-9 升高提示胃源转移，需胃肠镜；肝硬化腹水伴肝功异常、门脉高压征象，无附件包块。"}],"tx":{"drug":[{"name":"紫杉醇+卡铂","dose":"紫杉醇 175 mg/m² + 卡铂 AUC 5–6，静脉滴注 q3w，6 周期（或周疗紫杉醇 80 mg/m² + 卡铂 AUC 6 q3w）","note":"上皮性卵巢癌一线化疗标准；需预防紫杉醇过敏反应","renal":"卡铂按 eGFR 调整剂量；eGFR <30 慎用","hepatic":"紫杉醇胆红素 >1.5 倍 ULN 或 AST >10 倍 ULN 禁用","interact":"与 CYP3A4 抑制剂合用增加紫杉醇毒性；避免与氨基糖苷类合用增加肾毒性"},{"name":"奥拉帕利（PARP 抑制剂）","dose":"维持治疗 300 mg bid 口服（或 150 mg bid 联合贝伐珠单抗），持续 2 年或至进展","note":"用于 BRCA 突变或 HRD 阳性初治后维持、复发性铂敏感患者维持；需监测贫血与血细胞计数","renal":"eGFR <30 不推荐","hepatic":"重度肝功能不全不推荐","interact":"避免与强 CYP3A4 抑制剂（伊曲康唑、克拉霉素）或诱导剂（利福平）同用；避免西柚汁"},{"name":"贝伐珠单抗","dose":"15 mg/kg q3w 静脉滴注，联合化疗或维持至进展","note":"用于晚期上皮性卵巢癌一线或复发；术前 4–6 周需停用以避免创面愈合不良","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗凝药/抗血小板药合用增加出血；与舒尼替尼合用可致微血管病性溶血"},{"name":"卡铂（腹腔热灌注化疗 HIPEC 方案中）","dose":"卡铂 800 mg/m² 腹腔灌注（40–43 ℃，60–90 min），按机构方案执行，仅用于完全肿瘤细胞减灭的特定患者","note":"HIPEC 在部分中心用于晚期卵巢癌，需多学科与温度、灌注管理经验","renal":"按体表面积与 eGFR 制定，术后监测肾功能","hepatic":"遵说明书","interact":"遵说明书"},{"name":"博来霉素+依托泊苷+顺铂（BEP，生殖细胞肿瘤）","dose":"博来霉素 30 U 肌注/静滴（每周 1 次，共 9 次）+ 依托泊苷 100 mg/m² d1–5 + 顺铂 20 mg/m² d1–5，q3w，3–4 周期","note":"用于卵巢恶性生殖细胞肿瘤（无性细胞瘤、未成熟畸胎瘤），对保留生育者多可行保留生育手术+化疗","renal":"顺铂需水化；eGFR <60 减量或换卡铂","hepatic":"博来霉素在严重肺功能不全者禁用","interact":"博来霉素与放疗/氧气叠加致肺纤维化"},{"name":"顺铂/卡铂腹腔化疗","dose":"腹腔顺铂 75–100 mg/m²（或卡铂 AUC 5–6）联合静脉紫杉醇，用于完全肿瘤细胞减灭的复发/初治患者，按机构方案","note":"需严格评估腹膜与术后残余，注意肾毒性、腹腔感染与疼痛","renal":"腹腔顺铂需充分水化与监测肾功能","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["全面分期手术（早期）：腹腔冲洗液细胞学、全子宫双附件切除、大网膜切除、盆腔与腹主动脉旁淋巴结清扫","晚期：肿瘤细胞减灭术（R0 为目标），晚期伴大量腹水、腹腔广泛播散、一般情况差者首选新辅助化疗 3 周期后手术","年轻生育要求者、早期低危（ⅠA G1）可行保留生育手术（单侧附件+全面分期）","BRCA 突变家系：建议 35–40 岁后完成生育行预防性输卵管卵巢切除","腹水引流：腹腔穿刺放液可缓解腹胀；抽液后尽快开始化疗","随访：2 年内每 3 个月复查 CA125、妇科检查、影像，之后逐渐延长"],"life":["规律随访与 CA125 监测，警惕腹胀、食欲下降复发信号","遗传咨询：BRCA 阳性者建议检测一级亲属","营养与运动支持，化疗期间监测体重与口服摄入","心理支持，晚期患者早期引入姑息治疗可改善生活质量","口服避孕药与输卵管结扎可降低卵巢癌风险，可作高危人群的讨论选项"]},"prog":"年龄标准化 5 年生存率约 45%–50%，Ⅰ期可达 90%，Ⅲ–Ⅳ期约 30%。初治完全减灭+PARP 维持可显著延长无进展生存；复发多在 2–3 年内出现，需长期随访。","refs":["中华医学会妇科肿瘤学分会. 卵巢恶性肿瘤诊断与治疗指南（2021 版）","FIGO Cancer Report 2021: Ovarian Cancer Staging","NCCN Guidelines: Ovarian Cancer Including Fallopian Tube Cancer and Primary Peritoneal Cancer, Version 1.2024","ESGO/ISUOG/IOTA/ESGE Consensus Statement on preoperative diagnosis of ovarian tumors (2021)"]}]},{"id":"gyn_benign","name":"妇科良性疾病","rank":4,"summary":"子宫肌瘤与子宫内膜异位症常伴经量增多、痛经或盆腔痛，诊断以症状+超声为主，治疗按症状严重度、年龄与生育目的分层：观察随访、激素/非激素药物或手术。","compare":[{"diseaseId":"ob_fibroid","dx":"经量增多、经期延长、盆腔压迫症状（尿频、排便困难）、可触及增大的子宫；超声见子宫肌层内边界清晰低回声结节","key":"月经改变多为经量增多而非痛经为主，超声见肌层内结节"},{"diseaseId":"ob_endo","dx":"进行性加重的痛经、性交痛、慢性盆腔痛与不孕；腹腔镜见盆腔内膜异位病灶、卵巢巧克力囊肿","key":"以周期性疼痛和不孕为核心，病灶位于子宫外/盆腔腹膜、卵巢或深部浸润"}],"diseases":[{"id":"ob_fibroid","name":"子宫肌瘤","aka":["Uterine Fibroid","Leiomyoma","子宫平滑肌瘤"],"rank":1,"basic":{"define":"由子宫平滑肌细胞与成纤维细胞增生形成的良性肿瘤，可单发或多发，按位置分为肌壁间（最常见）、浆膜下与黏膜下肌瘤。育龄期女性中最常见的良性盆腔肿瘤。","risk":["育龄期女性（生育年龄最易发生）、30–50 岁","非洲裔女性发病率与症状严重程度更高","肥胖、初潮早","未育、晚育","一级亲属有子宫肌瘤史、高血压"],"epi":"育龄期女性中约 20%–30% 有症状性肌瘤，尸检或超声发现率可达 50%–70%；我国育龄女性患病率估计 25% 以上，是子宫切除最常见原因之一。"},"patho":"肌瘤为单克隆性平滑肌细胞过度增生，依赖雌、孕激素：孕期增大、绝经后萎缩。肌瘤可发生退行性变（红色变性、囊性变、钙化、肉瘤样变罕见）。黏膜下肌瘤使宫腔面积增大、内膜血管扭曲，致经量增多与经期延长；浆膜下肌瘤增大至一定体积压迫膀胱与直肠；部分肌瘤引起不孕或流产（影响宫腔形态与着床）。","dx":{"criteria":["经量增多（月经过多，>80 mL）、经期延长 >7 d、贫血（血红蛋白下降）","盆腔压迫症状：尿频、尿潴留、便秘、下腹坠胀，或腹部可触及包块","可有痛经（多为肌瘤变性或黏膜下肌瘤），也可无症状（体检发现）","超声诊断标准：子宫肌层内圆形/椭圆形低回声、边界清晰、伴假包膜、内部血流信号呈环状；彩色多普勒见周边血流","MRI 用于疑肉瘤变（快速增大、>10 cm、血流丰富）、定位精确与手术规划"],"workup":["妇科检查（子宫增大、不规则、硬、可触及结节）","经阴道/经腹超声（测量肌瘤数量、位置、大小、是否压迫宫腔）","血常规与铁代谢（评估贫血）、凝血功能（术中出血风险评估）","宫腔镜（黏膜下肌瘤致不孕/出血者）","MRI（鉴别肌瘤与腺肌症、肉瘤）","有生育要求者行输卵管评估与宫腔形态评估"],"grading":"按位置分级：黏膜下（FIGO 0–2 型）、肌壁间（FIGO 3–5 型）、浆膜下（FIGO 6–7 型）；按症状可为无症状、轻度、中重度；肌瘤大小以最大径测量（cm）。"},"ddx":[{"name":"子宫内膜异位症（ob_endo）","point":"与本类 ob_endo 的鉴别点：肌瘤以经量增多、子宫增大为主，痛经多为继发且渐进；内异症以进行性痛经、性交痛、不孕为核心，超声见巧克力囊肿或子宫后壁旋涡状腺肌病特征。"},{"name":"子宫腺肌病","point":"子宫均匀增大、质硬、压痛，超声见肌层回声不均、斑片状无回声（「瑞士奶酪」样）、内膜-肌层交界模糊；与肌瘤（局灶、结节状、假包膜）鉴别，MRI 确诊率高。"},{"name":"子宫肉瘤","point":"绝经后快速增大、短期内显著生长、血流极丰富、MRI 见坏死或出血；需术后病理确诊，术前行多学科评估。"},{"name":"子宫内膜息肉、子宫内膜癌","point":"息肉见宫腔内高回声团、蒂部血流，突出于宫腔；肌瘤多位于肌层，内膜癌需内膜活检排除（尤其绝经后出血）。"},{"name":"卵巢囊肿/卵巢肿瘤","point":"超声见附件区囊性/实性包块与子宫分开，与肌瘤（子宫来源）鉴别，必要时 MRI 或手术。"}],"tx":{"drug":[{"name":"左炔诺孕酮宫内缓释系统（LNG-IUS，曼月乐）","dose":"52 mg 宫内放置 5 年，用于经量增多伴肌瘤","note":"对黏膜下肌瘤效果差（可能脱落）；放置前排除宫腔变形与恶性","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"与酶诱导剂（利福平、卡马西平）合用可能降低疗效"},{"name":"氨甲环酸","dose":"经期 1 g 口服 qd–qid（每日总量 3–4 g），或 0.5 g tid，经期用 3–5 d","note":"非激素止血，适用于经量增多但无避孕需求者","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"与抗凝药同用可拮抗；血栓高危者慎用"},{"name":"布洛芬/萘普生","dose":"布洛芬 400 mg q8h 或萘普生 500 mg bid，经期前 1–2 d 至经期第 3 天","note":"仅缓解痛经与轻中度经量增多，不缩小肌瘤","renal":"eGFR <30 禁用或减量；用药期间监测肾功能","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、SSRIs 合用增加消化道出血；与 ACEI/ARB、利尿剂合用降低肾血流"},{"name":"GnRH-a（亮丙瑞林/戈舍瑞林）","dose":"亮丙瑞林 3.75 mg 皮下注射 q4w（或 11.25 mg 缓释剂 q12w），疗程一般 3–6 个月；术前 2–3 个月用于缩小肌瘤、纠正贫血（术前贫血 Hb <80 g/L 者）","note":"可逆性低雌激素状态，长期使用需反向添加雌激素以减轻骨质流失；停药后肌瘤可恢复增长","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他性激素或口服避孕药同用时需停用后者"},{"name":"米非司酮","dose":"2.5–5 mg qd 口服，疗程 3–6 个月（超说明书用药，需知情同意）","note":"可使肌瘤缩小 30%–50%、改善贫血；长期使用注意子宫内膜增生与肝功能","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 CYP3A4 抑制剂合用增加血药浓度；避免与利福平同用"},{"name":"复方口服避孕药","dose":"按具体制剂，1 片 qd，连续或周期性服用；用于控制经量","note":"不缩小肌瘤，可减少经量；>35 岁吸烟者、血栓高危、乳腺癌史者禁用","renal":"遵说明书","hepatic":"活动性肝病禁用","interact":"与酶诱导剂同用降低疗效；与影响凝血药物慎用"}],"nonDrug":["无症状肌瘤：每 6–12 个月超声随访即可","子宫动脉栓塞术（UAE）：可显著缩小肌瘤、改善症状，保留子宫但影响生育（不推荐未生育者首选）","高强度聚焦超声（HIFU）：适用于有症状、无生育要求或拒绝手术的肌壁间肌瘤，需保留内膜完整性","宫腔镜肌瘤切除（TCRM）：黏膜下肌瘤致经量增多或不孕首选，可保留生育","腹腔镜/开腹肌瘤剔除术：保留生育、肌瘤体积大或症状重者；术前评估肌瘤数目与宫腔贯通风险","子宫切除术：无生育要求、症状重、肌瘤多发或复发者，是根治手段，可选择全切或次全切","合并贫血：口服铁剂或术前输血/静脉铁纠正后手术"],"life":["控制体重、均衡饮食，减少高脂高糖摄入","定期随访：症状变化时随时评估","有生育要求者术后注意避孕 3–6 个月并评估妊娠时机（瘢痕子宫）","术后盆底肌锻炼、预防盆腔粘连相关并发症"]},"prog":"多数肌瘤生长缓慢，绝经后自然萎缩；症状性肌瘤经治疗可显著改善生活质量。肌瘤剔除术后 5 年复发率约 15%–30%，多发性肌瘤更高（>50%）；肌瘤恶变率为 0.2%–0.7%（肉瘤变）。","refs":["中华医学会妇产科学分会子宫肌瘤学组. 子宫肌瘤的诊治中国专家共识（2017）","ACOG Practice Bulletin No. 228: Management of Symptomatic Uterine Leiomyomas (2021)","NICE. Heavy menstrual bleeding: assessment and management (NG88, 2018, updated 2023)"]},{"id":"ob_endo","name":"子宫内膜异位症","aka":["Endometriosis","内异症","巧克力囊肿"],"rank":2,"basic":{"define":"具有活性的子宫内膜组织（腺体与间质）出现在子宫腔以外的部位（盆腔腹膜、卵巢、深部浸润），形成周期性出血与炎症、纤维化。多见于育龄期女性（25–45 岁），主要临床表现为慢性盆腔痛、进行性痛经与不孕。","risk":["育龄期女性（25–45 岁），初潮早、经期长、经量多（逆行经血多）","未育、晚育、避孕方式不当","一级亲属内异症病史（遗传易感性）","生殖道梗阻（如处女膜闭锁）致经血逆流","免疫异常、子宫内膜异位症家族史"],"epi":"育龄期女性发病率约 5%–15%，慢性盆腔痛女性中约 40%–70%，不孕女性中约 30%–50%；全球约 1.76 亿女性受累，我国估计患者数千万，平均延误诊断 7–10 年。"},"patho":"主要学说为经血逆流-种植学说（Sampson）与体腔上皮化生学说；遗传与免疫异常、局部炎症与血管生成也有贡献。逆行经血中的子宫内膜细胞在腹膜种植、周期性出血，引起局部无菌性炎症、纤维化与粘连。卵巢受累时形成巧克力囊肿（陈旧血性囊液），深部浸润病灶（DIE）累及直肠、子宫骶韧带、膀胱，导致疼痛和不孕。局部炎症因子影响卵子与胚胎质量、输卵管蠕动。","dx":{"criteria":["进行性加重的继发性痛经（非经期亦可痛）、慢性盆腔痛、性交痛、排便痛（深部浸润型）","不孕（约 30%–50% 患者合并不孕）","腹腔镜是诊断金标准，可见盆腔腹膜紫蓝色结节、粘连、巧克力囊肿与深部浸润病灶；病理证实为子宫内膜腺体与间质","影像学（超声/MRI）可提示，但不能替代病理；巧克力囊肿超声示「毛玻璃」样内部回声、壁厚","深部浸润型内异症：MRI 见骶韧带、直肠阴道隔、肠壁结节"],"workup":["妇科检查：子宫后倾固定、附件包块、后穹窿触痛结节（DIE 典型）","经阴道超声：卵巢巧克力囊肿、后陷凹积液与粘连","MRI：DIE 与肠壁受累评估，术前规划","CA125 可轻中度升高，用于疗效与复发监测","腹腔镜+病理为确诊手段，兼具治疗作用","合并不孕者行输卵管通畅检查与卵巢储备评估（AMH）"],"grading":"ASRM 分期（Ⅰ–Ⅳ期，按病灶大小、深度、粘连、巧克力囊肿评分）；按类型分为腹膜型、卵巢型（巧克力囊肿）、深部浸润型（DIE，含肠道、泌尿道、会阴）；ENZIAN 分类针对 DIE。"},"ddx":[{"name":"子宫肌瘤（ob_fibroid）","point":"与本类 ob_fibroid 的鉴别点：肌瘤以经量增多、子宫增大为主，超声见肌层低回声结节；内异症以进行性痛经、性交痛、不孕为核心，病灶位于盆腔腹膜/卵巢/深部。"},{"name":"子宫腺肌病","point":"痛经与经量增多并存、子宫均匀增大质硬，超声见肌层回声不均与内膜-肌层交界模糊；与内异症常合并存在，需综合判断。"},{"name":"盆腔炎性疾病（PID）","point":"下腹痛、发热、脓性分泌物、宫颈举痛，抗感染治疗有效，无周期性疼痛；内异症为周期性、无发热。"},{"name":"卵巢恶性肿瘤","point":"卵巢包块伴腹水、CA125 显著升高、消瘦；巧克力囊肿 CA125 多轻中度升高（<200 U/mL）、实性成分少。绝经后新发内异症样包块需警惕恶变。"},{"name":"肠易激综合征、慢性盆腔炎症综合征","point":"疼痛不为周期性、无盆腔包块与影像学病灶；需排除内异症后按功能性疾病管理。"}],"tx":{"drug":[{"name":"复方口服避孕药（低剂量，含屈螺酮/炔雌醇）","dose":"1 片 qd 连续服用（可用 21+7 或连续 84 d），作为一线经验性治疗","note":"应用于疼痛明显但自愿避孕者；连续服用可减少周期性出血与疼痛","renal":"遵说明书","hepatic":"活动性肝病禁用；血栓高危慎用","interact":"与酶诱导剂（利福平、卡马西平）合用降低疗效"},{"name":"地诺孕素","dose":"2 mg qd 口服，长期使用（疗程 6 个月以上可延续至 5 年）","note":"可缩小巧克力囊肿、减轻疼痛；常见不规则出血，用药初期明显，需告知","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与酶诱导剂合用可能降低疗效；与 CYP3A4 抑制剂合用增加血药浓度"},{"name":"GnRH-a（亮丙瑞林/戈舍瑞林）","dose":"亮丙瑞林 3.75 mg 皮下注射 q4w，疗程 3–6 个月；长期使用需反向添加低剂量雌孕激素以保护骨密度","note":"适用于中重度疼痛、术前缩小病灶或复发性内异症；可致潮热、骨密度降低（>6 个月需反向添加）","renal":"遵说明书","hepatic":"遵说明书","interact":"停用口服避孕药后使用"},{"name":"非甾体抗炎药","dose":"布洛芬 400 mg q8h 或萘普生 500 mg bid，经期前 1–2 d 起始至疼痛缓解","note":"对症止痛，不能抑制病灶，适合轻中度疼痛辅助","renal":"肾功能不全减量，eGFR <30 禁用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、SSRIs 合用增加出血风险"},{"name":"左炔诺孕酮宫内缓释系统（LNG-IUS）","dose":"52 mg 宫内放置 5 年","note":"对痛经与经量增多有效；DIE 或严重宫腔变形者可能效果有限","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"遵说明书"},{"name":"米非司酮","dose":"5–10 mg qd 口服，短期使用 3–6 个月（超说明书，需知情同意）","note":"用于中重度疼痛的短期治疗，需监测肝功能","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与 CYP3A4 抑制剂合用增加血药浓度"}],"nonDrug":["腹腔镜手术：切除可见病灶、剥除巧克力囊肿（保护卵巢储备）、分离粘连；适用于药物无效、包块 >4 cm、DIE 致肠道/泌尿道症状或合并不孕","保留生育功能的手术以疼痛缓解和生育为目标，术后药物维持可延缓复发","合并不孕者：Ⅰ–Ⅱ期可先期待/促排卵+IUI，Ⅲ–Ⅳ期或输卵管病变者推荐 IVF","DIE 累及肠道/膀胱者需多学科（妇产+胃肠/泌尿外科）评估，必要时肠段切除","术后药物（地诺孕素、GnRH-a、COC）维持 6–12 个月降低复发","根治性手术（全子宫+双侧附件切除）仅用于无生育要求、症状重或围绝经期者"],"life":["规律运动（每周 150 min 有氧）与低脂饮食有助于减轻症状","热敷、放松训练、疼痛认知行为治疗作为辅助","生育计划：术后尽早妊娠（6–12 个月内），避免长期等待","长期随访：术后 2 年内每 3–6 个月复查，警惕复发与巧克力囊肿恶变","心理支持：慢性疼痛与内异症相关的焦虑抑郁需评估"]},"prog":"药物可显著缓解疼痛、延缓病灶进展，但不能根治；停药物复发率高（术后 5 年约 40%–50%）。腹腔镜保守手术 5 年疼痛缓解率约 50%–70%，合并不孕者术后自然妊娠率约 30%–50%。","refs":["中华医学会妇产科学分会子宫内膜异位症协作组. 子宫内膜异位症的诊治指南（2021 版）","ESHRE Guideline: Endometriosis (2022)","NICE. Endometriosis: diagnosis and management (NG73, 2017, updated 2024)","ACOG Practice Bulletin No. 114: Management of Endometriosis (2010, reaffirmed 2020)"]}]},{"id":"pregnancy_htn","name":"妊娠期高血压疾病与产科其他","rank":5,"summary":"妊娠期高血压疾病的关键是区分慢性/妊娠期高血压与子痫前期：有无蛋白尿或器官受损决定是否按子痫前期处理，≥160/110 mmHg 即急症降压解痉。ICP 以瘙痒加空腹胆汁酸升高为特征，熊去氧胆酸一线，重度者 36～37 周终止。胎膜早破与早产重在明确孕周与感染，34 周前抑宫缩、促肺成熟与硫酸镁脑保护；晚期产后出血与胎盘植入重在术前识别高危胎盘与分级止血。","compare":[{"diseaseId":"ob_gh","dx":"妊娠 20 周后新发血压 ≥140/90 mmHg，无蛋白尿与器官受损，产后 12 周内恢复","key":"血压升高但无蛋白尿与靶器官损害，分界在于器官受累"},{"diseaseId":"ob_icp","dx":"中晚孕期皮肤瘙痒（夜间、掌跖为著），无原发皮疹，空腹血清总胆汁酸升高","key":"瘙痒 + 胆汁酸升高，肝酶轻度异常，血压多正常"},{"diseaseId":"ob_prom","dx":"阴道流液，窥器见羊水流出，pH ≥6.5、羊齿状结晶阳性，羊水指数下降","key":"孕周与破膜时间决定处理路径，警惕绒毛膜羊膜炎"},{"diseaseId":"ob_pph_late","dx":"分娩 24 小时后至产后 12 周阴道大量流血，超声见宫腔残留或胎盘后低回声带消失","key":"晚期出血伴胎盘植入超声征象，警惕宫缩乏力与感染"}],"diseases":[{"id":"ob_gh","name":"妊娠期高血压与慢性高血压","aka":["Gestational Hypertension","Chronic Hypertension in Pregnancy"],"rank":1,"basic":{"define":"妊娠 20 周后首次出现血压 ≥140/90 mmHg、无蛋白尿及器官受损、产后 12 周恢复者称妊娠期高血压；孕前已存在或产后 12 周持续者为慢性高血压。二者均可进展为子痫前期。","risk":["高龄 ≥35 岁、初产妇","孕前肥胖（BMI ≥28）","慢性高血压、慢性肾病、糖尿病","多胎妊娠、既往子痫前期或家族史","SLE、抗磷脂综合征"],"epi":"妊娠期高血压约占妊娠 5%～10%，其中约 25%～50% 进展为子痫前期；慢性高血压合并妊娠约 3%～5%。"},"patho":"滋养细胞侵入不足致螺旋动脉重铸障碍，胎盘缺血释放 sFlt-1 等抗血管生成因子，引起内皮功能障碍与外周阻力升高。慢性高血压者孕前已有血管重塑异常，叠加妊娠期容量扩张更易出现蛋白尿与器官受损。","dx":{"criteria":["同一手臂至少 2 次、间隔 ≥4 小时测量，收缩压 ≥140 和/或舒张压 ≥90 mmHg","妊娠期高血压：孕 20 周后新发，尿蛋白阴性，无血小板减少、肝肾功能异常、肺水肿或神经症状","慢性高血压：孕 20 周前或孕前已诊断，或产后 12 周仍 ≥140/90 mmHg","重度：收缩压 ≥160 和/或舒张压 ≥110 mmHg，持续 15 分钟以上","出现蛋白尿或任一器官受损（血小板 <100×10⁹/L、肌酐 >97 μmol/L、转氨酶升高 2 倍、肺水肿）即转子痫前期"],"workup":["坐位休息 5 分钟后双上肢测量，袖带规格适宜","尿常规与 24 小时尿蛋白定量，或尿蛋白/肌酐比值","血常规、肝肾功能、乳酸脱氢酶、尿酸、凝血功能","胎儿超声评估生长与羊水，脐动脉血流多普勒","NST 每周 1～2 次；年轻顽固性高血压查肾动脉超声、ANA、抗磷脂抗体"],"grading":"轻度 140～159/90～109 mmHg；重度 ≥160/110 mmHg。按病程分妊娠期高血压、慢性高血压合并妊娠与子痫前期前期。"},"ddx":[{"name":"妊娠期肝内胆汁淤积症（ob_icp）","point":"与本类 ob_icp 的鉴别点：ICP 以瘙痒与胆汁酸升高为主、血压多正常；二者并存时按子痫前期严密监护。"},{"name":"胎膜早破与早产（ob_prom）","point":"与本类 ob_prom 的鉴别点：本文无阴道流液，早产多为医源性终止妊娠的结果。"},{"name":"晚期产后出血与胎盘植入（ob_pph_late）","point":"与本类 ob_pph_late 的鉴别点：本文发生于孕期，后者发生于产后 24 小时后且以出血为主。"},{"name":"慢性肾脏病继发高血压","point":"孕前已有蛋白尿、肌酐升高或血尿，血压升高早于 20 周，需肾内科评估。"},{"name":"白大衣高血压","point":"诊室血压高而家庭或动态血压正常，需家庭监测确认。"}],"tx":{"drug":[{"name":"拉贝洛尔","dose":"口服 100 mg bid 起，可增至 200 mg bid～400 mg tid；急症 20 mg 缓慢静推，10 分钟可重复，累积 ≤300 mg；遵说明书","note":"妊娠期一线降压药，兼 α、β 受体阻滞作用。","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与非二氢吡啶钙通道阻滞剂合用可致低血压"},{"name":"硝苯地平缓释片","dose":"口服 30 mg qd 起，可增至 30～60 mg qd；急症短效片 10 mg 口服，20 分钟可重复，避免舌下含服；遵说明书","note":"钙通道阻滞剂，妊娠期一线。","renal":"遵说明书","hepatic":"肝功能不全需减量","interact":"与硫酸镁合用可加重神经肌肉阻滞与低血压"},{"name":"硫酸镁","dose":"负荷 4～5 g 静滴 20～30 分钟，维持 1～2 g/h；遵说明书","note":"重度高血压或子痫前期征象时解痉与预防子痫；监测膝反射、呼吸 ≥16 次/分、尿量 ≥25 ml/h，中毒用葡萄糖酸钙。","renal":"肾功能不全需减量并延长监测","hepatic":"遵说明书","interact":"与硝苯地平、拉贝洛尔合用增加低血压"},{"name":"阿司匹林（预防）","dose":"75～150 mg qd，孕 12～16 周开始至 36 周；遵说明书","note":"用于高危孕妇，降低早发型子痫前期风险；分娩前 5～7 天停药。","renal":"肾功能不全慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药合用增加出血风险"}],"nonDrug":["降压目标：无器官受损 <140/90 mmHg，有器官受损 <130/80 mmHg，舒张压不低于 80 mmHg","每周监测血压与尿蛋白，出现蛋白尿或器官异常按子痫前期处理","终止妊娠：无并发症 37～39 周；重度高血压、子痫前期或胎儿窘迫随时终止","慢性高血压孕前评估靶器官并停用 ACEI/ARB"],"life":["家庭血压每日早晚监测并记录","出现头痛、视物模糊、上腹不适立即就诊","产后 6～12 周复查血压与尿蛋白，转内科长期管理"]},"prog":"多数产后 12 周内恢复，但约 25%～50% 进展为子痫前期，远期高血压与卒中风险为一般人群 2～3 倍。慢性高血压者子痫前期、胎儿生长受限与早产风险明显增高。","refs":["中华医学会妇产科学分会妊娠期高血压疾病学组《妊娠期高血压疾病诊治指南（2020）》","《妇产科学》第 9 版（人民卫生出版社，2018）"]},{"id":"ob_icp","name":"妊娠期肝内胆汁淤积症","aka":["ICP","Intrahepatic Cholestasis of Pregnancy"],"rank":2,"basic":{"define":"妊娠中晚期特有的肝内胆汁淤积，以皮肤瘙痒与空腹血清总胆汁酸升高为特征，无原发皮疹、黄疸少见，产后数日缓解，再孕易复发。主要危害为胎儿突然宫内死亡与早产。","risk":["ICP 既往史（再孕复发率 40%～70%）","家族史、多胎妊娠","丙型肝炎、胆结石或胆道手术史","辅助生殖受孕","年龄 ≥35 岁"],"epi":"我国长江流域与西南地区较高，报告约 1%～6%；多在孕 28～32 周出现。"},"patho":"雌、孕激素代谢产物升高，抑制胆盐输出泵（BSEP/ABCB11）与 MDR3（ABCB4），致胆汁酸排泄障碍，遗传易感与环境共同作用。胆汁酸在胎盘蓄积可致绒毛间隙血流减少与胎儿急性缺氧。","dx":{"criteria":["中晚孕期皮肤瘙痒，夜间加重，掌跖与腹部为著，无原发皮疹","空腹血清总胆汁酸 ≥10 μmol/L 提示 ICP；≥40 为重度，≥100 为极重度","丙氨酸氨基转移酶轻中度升高（多低于正常上限 5 倍），胆红素多正常","排除病毒性肝炎、自身免疫性肝病、妊娠期急性脂肪肝与 HELLP 综合征","分娩后 2～6 周复查胆汁酸与肝酶恢复正常"],"workup":["空腹 ≥8 小时测总胆汁酸，用药前及 1 周后复查","肝功能、胆红素、凝血功能、血常规、血糖","甲～戊型肝炎标志物、EBV/CMV；追问用药史排除药物性肝损","肝胆超声排除胆石症与胆道梗阻，必要时 MRCP；ANA、AMA、甲状腺功能"],"grading":"按空腹胆汁酸：10～39 μmol/L 轻度；40～99 重度；≥100 极重度，终止妊娠时机不同。"},"ddx":[{"name":"妊娠期高血压与慢性高血压（ob_gh）","point":"与本类 ob_gh 的鉴别点：本文以瘙痒与胆汁酸升高为核心、血压正常；后者以血压升高为主、无瘙痒。"},{"name":"胎膜早破与早产（ob_prom）","point":"与本类 ob_prom 的鉴别点：ICP 可致自发性早产，出现流液或规律宫缩时按胎膜早破处理。"},{"name":"晚期产后出血与胎盘植入（ob_pph_late）","point":"与本类 ob_pph_late 的鉴别点：ICP 因脂溶性维生素吸收障碍致凝血因子不足，产后出血风险增加，需产前补维生素 K。"},{"name":"妊娠期急性脂肪肝","point":"孕晚期乏力呕吐、黄疸、低血糖与凝血障碍，可多器官衰竭，需紧急终止妊娠。"},{"name":"HELLP 综合征","point":"溶血、肝酶升高、血小板减少，伴高血压蛋白尿，需与 ICP 区分。"}],"tx":{"drug":[{"name":"熊去氧胆酸（UDCA）","dose":"10～15 mg/kg/d 分 2～3 次口服，可增至 15～20 mg/kg/d；遵说明书","note":"降低胆汁酸、缓解瘙痒并改善围产结局；1 周后复查评估疗效。","renal":"严重肾功能不全慎用","hepatic":"胆道完全梗阻者禁用","interact":"与考来烯胺合用降低吸收，需间隔 4 小时"},{"name":"S-腺苷蛋氨酸","dose":"500～1000 mg 静滴或肌注 qd；遵说明书","note":"UDCA 疗效不佳或不耐受时的辅助用药。","renal":"遵说明书","hepatic":"遵说明书","interact":"与选择性 5-羟色胺再摄取抑制剂合用警惕血清素综合征"},{"name":"维生素 K1","dose":"10 mg 肌内注射每周 1 次（产前）；遵说明书","note":"预防产后出血与新生儿维生素 K 缺乏性出血。","renal":"遵说明书","hepatic":"遵说明书","interact":"拮抗华法林抗凝作用"}],"nonDrug":["轻度（<40 μmol/L）无并发症：38～39 周终止；重度（40～99）：36～37 周；极重度（≥100）：36 周左右评估终止","胎儿监护：轻度每周 1 次 NST，重度每周 2 次以上；胎心异常或宫缩频繁即处理","无产科指征可阴道分娩，产程中持续胎心监护","34 周前出现早产征象给糖皮质激素促胎肺成熟"],"life":["少量多餐，避免长时间空腹与高脂辛辣饮食","记录瘙痒程度与睡眠影响，加重即就诊","产后 6 周复查，未恢复者转消化内科","再次妊娠 14 周前复查胆汁酸纳入高危管理"]},"prog":"预后良好，产后数日瘙痒缓解、2～6 周肝功能恢复。胎死宫内风险随胆汁酸升高而增加，极重度者可 >10%，及时终止妊娠可显著降低风险。复发率 40%～70%。","refs":["中华医学会妇产科学分会产科学组《妊娠期肝内胆汁淤积症诊疗指南（2015，2021 年更新）》","《妇产科学》第 9 版（人民卫生出版社，2018）"]},{"id":"ob_prom","name":"胎膜早破与早产","aka":["PROM","PPROM","Preterm Labor"],"rank":3,"basic":{"define":"胎膜早破指临产前胎膜自然破裂，分足月（≥37 周）与未足月（<37 周，PPROM）；早产指孕 28 周至不足 37 周分娩，二者常互为因果。","risk":["既往早产或胎膜早破史","生殖道感染（细菌性阴道病、支原体、淋球菌）","多胎妊娠、羊水过多","宫颈机能不全、宫颈锥切史","妊娠期糖尿病、子痫前期、ICP","吸烟"],"epi":"我国早产率约 6%～7%，为新生儿死亡首位原因；胎膜早破约占分娩总数 2%～5%，其中 PPROM 约 1%。"},"patho":"感染与炎症是核心：细菌上行释放炎性介质与基质金属蛋白酶，降解胎膜胶原致破裂，并刺激宫缩。早产儿面临呼吸窘迫综合征、坏死性小肠结肠炎与脑室内出血。","dx":{"criteria":["主诉阴道流液，窥器见羊水自宫颈口流出","阴道液 pH ≥6.5、羊齿状结晶阳性，或 PAMG-1 检测阳性","羊水指数明显下降或最大垂直暗区 <2 cm","早产：规律宫缩伴宫颈进行性改变，或经阴道超声宫颈长度 ≤20 mm","警惕绒毛膜羊膜炎：体温 ≥38 ℃、子宫压痛、胎心过速、分泌物异味、白细胞升高"],"workup":["窥器检查宫颈与分泌物，避免不必要阴道指诊；经阴道超声测宫颈长度","羊水检测：pH、羊齿状结晶、PAMG-1 或 IGFBP-1；胎心与宫缩监护","血常规、CRP、降钙素原；疑难时羊水穿刺查白细胞、葡萄糖、培养；宫颈分泌物培养与 GBS 筛查"],"grading":"按孕周：<34 周（抑宫缩、促肺成熟）；34～36⁺⁶ 周（个体化）；≥37 周足月胎膜早破，24 小时内引产。另按有无感染分层。"},"ddx":[{"name":"妊娠期高血压与慢性高血压（ob_gh）","point":"与本类 ob_gh 的鉴别点：两者均无阴道流液；早产可为子痫前期的医源性结果，胎儿生长受限需一并评估。"},{"name":"妊娠期肝内胆汁淤积症（ob_icp）","point":"与本类 ob_icp 的鉴别点：ICP 也可致自发性早产，但以瘙痒和胆汁酸升高为特征，无破膜。"},{"name":"晚期产后出血与胎盘植入（ob_pph_late）","point":"与本类 ob_pph_late 的鉴别点：胎膜早破的问题是感染、脐带脱垂与早产；晚期产后出血发生于产后 24 小时后。"},{"name":"压力性尿失禁与阴道分泌物增多","point":"漏尿或感染性分泌物增多，pH 与羊齿状结晶阴性，无持续流液。"},{"name":"生理性宫缩（假临产）","point":"宫缩不规律、强度不增加、无宫颈改变。"}],"tx":{"drug":[{"name":"硫酸镁（胎儿脑保护）","dose":"负荷 4 g 静滴 20～30 分钟，维持 1 g/h 至分娩或最长 24 小时；遵说明书","note":"用于孕 24～32 周（部分指南至 33⁺⁶ 周）即将早产者，降低脑瘫风险；监测膝反射、呼吸、尿量。","renal":"肾功能不全需减量并延长监测","hepatic":"遵说明书","interact":"与钙通道阻滞剂、氨基糖苷类合用增加神经肌肉阻滞"},{"name":"地塞米松（促胎肺成熟）","dose":"6 mg 肌内注射每 12 小时 1 次，共 4 次；遵说明书","note":"用于孕 24～34 周（部分至 36⁺⁶ 周）有早产风险者，24 小时内完成效果最佳。","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加胃肠道风险"},{"name":"硝苯地平（宫缩抑制）","dose":"负荷 20 mg 口服，之后 10～20 mg 每 6～8 小时；遵说明书","note":"一线宫缩抑制剂，争取 48 小时促肺成熟时间；绒毛膜羊膜炎或 <24 周者不用。","renal":"遵说明书","hepatic":"肝功能不全需减量","interact":"与硫酸镁合用增加低血压与阻滞风险"},{"name":"阿托西班（二线宫缩抑制）","dose":"负荷 6.75 mg 静推 1 分钟，维持 18 mg/h 3 小时，再 6 mg/h 至 45 小时；遵说明书","note":"催产素受体拮抗剂，不良反应少，用于硝苯地平禁忌或无效者。","renal":"遵说明书","hepatic":"遵说明书","interact":"与催产素拮抗，避免同期使用"},{"name":"氨苄西林 + 红霉素（PPROM 预防感染）","dose":"氨苄西林 2 g 静滴 q6h 共 48 小时后阿莫西林 500 mg 口服 bid 共 5 天；红霉素 250 mg 静滴 q6h 共 48 小时后口服共 5 天；遵说明书","note":"延长孕周并降低新生儿感染；避免用阿莫西林-克拉维酸。","renal":"肾功能不全需调整","hepatic":"肝功能不全慎用","interact":"红霉素与华法林、地高辛合用增加毒性"},{"name":"青霉素 G 或头孢唑林（GBS 预防）","dose":"青霉素 G 首剂 500 万 U 静滴后续 250 万 U q4h 至分娩；或头孢唑林 2 g 首剂后 1 g q8h；遵说明书","note":"GBS 定植或状态不明且破膜 ≥18 小时者产时预防。","renal":"肾功能不全需调整","hepatic":"遵说明书","interact":"头孢唑林与华法林合用增加出血风险"}],"nonDrug":["足月 PROM：无感染与胎儿窘迫时 24 小时内引产，避免长时间期待","PPROM <34 周：期待治疗，卧床、避免阴道指诊、监测感染与胎儿","34～36⁺⁶ 周 PPROM：多主张终止妊娠，减少绒毛膜羊膜炎与新生儿脓毒症","脐带脱垂：抬高臀部并紧急剖宫产，先露高者破膜后避免下床","绒毛膜羊膜炎：抗感染并立即终止妊娠，不论孕周"],"life":["识别发热、腹痛、分泌物异味与胎动减少","避免性生活与盆浴直至分娩","早产儿转新生儿科并鼓励母乳喂养","下次妊娠早期筛查宫颈长度"]},"prog":"足月 PROM 及时引产预后良好。PPROM 潜伏期与孕周负相关，绒毛膜羊膜炎约 20%～30%。≥32 周早产儿存活率 >95%，<28 周约 70%～85%，存活者约 10% 存在脑瘫或认知障碍。","refs":["中华医学会妇产科学分会产科学组《妊娠期胎膜早破诊断与处理指南（2015）》","中华医学会妇产科学分会产科学组《早产临床诊断与治疗指南（2021 更新）》"]},{"id":"ob_pph_late","name":"晚期产后出血与胎盘植入","aka":["Late Postpartum Hemorrhage","Placenta Accreta Spectrum","PAS"],"rank":4,"basic":{"define":"晚期产后出血指分娩 24 小时后至产后 12 周内阴道大量流血，多见于产后 1～2 周。胎盘植入谱系疾病（PAS）指胎盘绒毛异常侵入肌层（植入）、深达肌层（深层植入）或穿透浆膜累及膀胱直肠（穿透性），是致命性出血与子宫切除的重要原因。","risk":["前置胎盘（PAS 最主要危险因素）","剖宫产史，次数越多风险越高","子宫肌瘤剔除、宫腔镜电切、刮宫史","高龄 ≥35 岁、多产","既往胎盘滞留或徒手剥离胎盘"],"epi":"晚期产后出血占产后出血的 1%～2%，病因依次为胎盘胎膜残留、子宫复旧不全、附着面感染；前置胎盘伴剖宫产史者 PAS 发生率可达 10%～30%。"},"patho":"残留组织妨碍子宫收缩与内膜再生，继发感染坏死致血管开放。PAS 为蜕膜缺失、滋养细胞侵入过深，胎盘与肌层无分界，剥离即大出血。","dx":{"criteria":["分娩 24 小时后阴道流血量多，伴血块、腹痛或发热，严重者休克","子宫复旧不全：子宫较同期产褥大而软、宫底下降延迟，恶露增多有异味","PAS 产前：前置胎盘合并剖宫产史，超声见胎盘后低回声带消失、胎盘陷窝、肌层 <1 mm、膀胱界面中断与桥接血管","MRI 用于超声不明确或疑宫旁/膀胱受累","胎盘娩出后 30 分钟仍未剥离伴出血需考虑植入"],"workup":["追问分娩方式、胎盘是否完整、有无徒手剥离与产程长短","妇科检查子宫大小与压痛；超声评估宫腔残留、子宫下段肌层与胎盘附着处血流","血常规、凝血功能、纤维蛋白原、肝肾功能；出血多者交叉配血，血 HCG 排除滋养细胞疾病","PAS 产前多学科会诊（产科、麻醉、泌尿外科、介入、血库）"],"grading":"PAS 按侵入深度分粘连、植入与穿透性；晚期产后出血按失血量分轻度 <1000 ml、中度 1000～2000 ml、重度 >2000 ml 或伴休克。"},"ddx":[{"name":"妊娠期高血压与慢性高血压（ob_gh）","point":"与本类 ob_gh 的鉴别点：本文发生于产后 24 小时后，后者发生于孕期；子痫前期可继发 DIC 加重产后出血。"},{"name":"妊娠期肝内胆汁淤积症（ob_icp）","point":"与本类 ob_icp 的鉴别点：ICP 因维生素 K 吸收障碍致凝血因子不足、增加产后出血，但为即刻产后出血而非晚期。"},{"name":"胎膜早破与早产（ob_prom）","point":"与本类 ob_prom 的鉴别点：胎膜早破伴绒毛膜羊膜炎可致复旧不全与晚期出血，需追问破膜时间与感染征象。"},{"name":"妊娠滋养细胞疾病","point":"血 HCG 持续升高或下降后复升，超声见蜂窝状富血供病灶，可伴咳血。"},{"name":"产褥感染与子宫内膜炎","point":"以发热、腹痛、恶露异味为主，出血量可不多，抗感染结合超声排除残留。"}],"tx":{"drug":[{"name":"缩宫素","dose":"10 U 肌内注射或 10～20 U 加入 500 ml 液体静滴；遵说明书","note":"促子宫收缩；快速静推可致低血压。","renal":"遵说明书","hepatic":"遵说明书","interact":"与前列腺素类合用增加子宫强直收缩风险"},{"name":"卡前列素氨丁三醇","dose":"250 μg 深部肌内注射，每 15～90 分钟可重复，总量 ≤2 mg；遵说明书","note":"用于缩宫素无效的顽固性宫缩乏力；哮喘与严重心血管病禁用。","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加支气管痉挛风险"},{"name":"米索前列醇","dose":"600 μg 口服或 800～1000 μg 直肠单次给药；遵说明书","note":"适合基层资源有限场景；青光眼与哮喘者慎用。","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他前列腺素类合用增加子宫破裂风险"},{"name":"头孢呋辛 + 甲硝唑","dose":"头孢呋辛 1.5 g 静滴 q8h + 甲硝唑 0.5 g 静滴 q8h，疗程 5～7 天；遵说明书","note":"用于子宫内膜炎与残留继发感染，获培养结果后调整。","renal":"肾功能不全需调整","hepatic":"甲硝唑肝功能不全减量","interact":"甲硝唑与酒精禁忌；头孢类与华法林合用增加出血"},{"name":"氨甲环酸","dose":"1 g 静滴 10 分钟，必要时 30 分钟后重复 1 g；遵说明书","note":"止血辅助，不替代病因处理；PAS 术中权衡血栓风险。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与抗凝药作用拮抗"}],"nonDrug":["残留者行清宫或宫腔镜去除，同时抗感染与促宫缩","子宫复旧不全：按摩子宫、排空膀胱、促宫缩；感染者引流","PAS 计划性剖宫产（一般 34～36 周），多学科团队联合手术","术中胎盘原位保留并行子宫切除，避免强行剥离；腹主动脉球囊阻断或髂内动脉栓塞","B-Lynch 缝合、宫腔球囊或盆腔填塞用于宫缩乏力","子宫动脉栓塞用于稳定且希望保留生育者；保守失败或穿透性植入行子宫切除"],"life":["产褥期注意恶露量与气味，出现大量血块或发热及时就诊","贫血者补铁随访血红蛋白","PAS 保守治疗者长期随访 HCG、超声与月经恢复","计划再孕者孕前咨询"]},"prog":"晚期产后出血经清宫、抗感染与促宫缩多能迅速止血，延误可致休克与席汉综合征。PAS 是产科最凶险的出血原因之一，计划性多学科手术显著降低出血量与子宫切除率。","refs":["中华医学会妇产科学分会产科学组《产后出血预防与处理指南（2014）》《前置胎盘的诊断与处理指南（2020）》","FIGO Consensus Guidelines on Placenta Accreta Spectrum Disorders (2018)"]}]},{"id":"gyn_other","name":"妇科其他","rank":6,"summary":"异常子宫出血先用 FIGO PALM-COEIN 分类明确病因，育龄期先排除妊娠，围绝经期重视内膜取样，青春期以调周期为主。盆腔炎性疾病以下腹痛、宫颈举痛与附件压痛为最低诊断标准，抗生素覆盖淋球菌、衣原体与厌氧菌。宫颈上皮内瘤变以 HPV 与细胞学筛查为基础，HSIL 需阴道镜评估与切除治疗。","compare":[{"diseaseId":"ob_aub","dx":"月经周期、经期长度、经量或非经期出血任一异常，影响生活或伴贫血","key":"出血模式异常，先排除妊娠再按 PALM-COEIN 查找病因"},{"diseaseId":"ob_pid","dx":"下腹痛伴宫颈举痛或子宫/附件压痛，可有发热与脓性分泌物","key":"盆腔压痛为主要体征，联合抗生素覆盖淋球菌与衣原体"},{"diseaseId":"ob_cin","dx":"多无症状，HPV 阳性或细胞学异常后经阴道镜活检确认，分 LSIL/HSIL","key":"筛查发现、病理确诊，关键在阴道镜评估与术后随访"}],"diseases":[{"id":"ob_aub","name":"异常子宫出血","aka":["AUB","Abnormal Uterine Bleeding","PALM-COEIN"],"rank":1,"basic":{"define":"指与正常月经的周期频率、规律性、经期长度或经量任一不符、源于宫腔的出血，需排除妊娠与器质性病变。按 FIGO PALM-COEIN 分结构性（PALM）与非结构性（COEIN）。","risk":["多囊卵巢综合征、肥胖、甲状腺功能异常","子宫内膜息肉、子宫肌瘤、子宫腺肌病","子宫内膜增生或内膜癌（围绝经期、肥胖、糖尿病）","凝血功能障碍（青春期月经过多者约 20%）","宫内节育器、避孕药、抗凝药使用"],"epi":"为妇科门诊最常见主诉之一，育龄期约 10%～30% 曾发生；PALM-COEIN 中排卵障碍（AUB-O）与内膜息肉最常见。"},"patho":"无排卵或排卵障碍时内膜受单一雌激素刺激而增生、缺乏孕激素转化，出现不规则剥脱。息肉与肌瘤改变宫腔形态；腺肌病使内膜侵入肌层、收缩不良；凝血异常致经量增多。","dx":{"criteria":["正常月经：周期 21～35 天、经期 3～7 天、经量 5～80 ml、相邻周期相差 ≤7 天","异常：周期 <21 或 >35 天、经期 >7 天、经量 >80 ml 或非经期出血，持续 >3 个月","育龄期必须先查血或尿 HCG，排除妊娠相关出血","按 PALM-COEIN 逐项排查：息肉、腺肌病、肌瘤、恶性与不典型增生；凝血、排卵障碍、内膜局部异常、医源性、未分类","年龄 ≥45 岁或高危者须行子宫内膜活检"],"workup":["血常规评估贫血，凝血功能（APTT、PT、纤维蛋白原、vWF 活性）","HCG、甲状腺功能、泌乳素、性激素六项（必要时睾酮）","经阴道超声评估内膜厚度、息肉、肌瘤、腺肌病与宫腔形态","宫腔镜检查与定位活检：疑息肉、内膜异常或药物治疗无效","盆腔 MRI 评估肌瘤分型与腺肌病范围"],"grading":"FIGO PALM-COEIN：结构性包括息肉、腺肌病、平滑肌瘤（FIGO 0～8 型）、恶性与不典型增生；非结构性包括凝血、排卵障碍、内膜局部异常、医源性、未分类。"},"ddx":[{"name":"盆腔炎性疾病（ob_pid）","point":"与本类 ob_pid 的鉴别点：PID 以下腹痛、宫颈举痛与发热为主；AUB 以月经失控为主而无盆腔压痛。"},{"name":"宫颈上皮内瘤变与宫颈癌（ob_cin）","point":"与本类 ob_cin 的鉴别点：宫颈病变多为接触性出血（同房后），需 HPV、细胞学与阴道镜活检筛选。"},{"name":"异位妊娠与先兆流产","point":"育龄期 AUB 必须查 HCG；异位妊娠伴腹痛、附件包块，破裂时腹腔内出血致休克。"},{"name":"子宫内膜癌","point":"围绝经期或绝经后出血、超声内膜增厚、肥胖糖尿病风险人群，需内膜活检确认。"}],"tx":{"drug":[{"name":"左炔诺孕酮宫内释放系统（LNG-IUS）","dose":"宫腔内放置 1 个，有效期 5 年；遵说明书","note":"AUB-O、腺肌病与特发性月经过多的一线长期治疗，显著减少经量并改善贫血。","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"与酶诱导剂合用降低疗效"},{"name":"复方短效口服避孕药","dose":"按说明书周期性服用 3～6 个周期；遵说明书","note":"用于 AUB-O 的周期调节与止血；血栓高危者禁用。","renal":"遵说明书","hepatic":"肝功能异常者禁用","interact":"与抗癫痫药、利福平合用降低避孕效果"},{"name":"地屈孕酮","dose":"10 mg bid，经期第 11～25 天或周期性使用；遵说明书","note":"用于排卵障碍性 AUB 与子宫内膜增生不伴不典型增生，保护内膜。","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与酶诱导剂合用降低疗效"},{"name":"氨甲环酸","dose":"1 g 口服每日 3 次，经期使用；遵说明书","note":"抗纤溶药，可减少经量 30%～55%，适用于急性月经过多与凝血异常。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与抗凝药作用拮抗"},{"name":"布洛芬（非甾体抗炎药）","dose":"400 mg 每 6～8 小时口服，经期使用；遵说明书","note":"抑制前列腺素合成，减少经量并缓解痛经；消化道溃疡或肾病患者慎用。","renal":"eGFR <30 者慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"GnRH-a（亮丙瑞林）","dose":"3.75 mg 皮下注射每 4 周 1 次，共 3～6 次；遵说明书","note":"用于腺肌病与肌瘤术前缩瘤；长期使用需反向添加雌激素防骨丢失。","renal":"遵说明书","hepatic":"遵说明书","interact":"注意骨密度相关药物叠加"}],"nonDrug":["宫腔镜下息肉切除是息肉所致 AUB 的首选","黏膜下肌瘤（FIGO 0～2 型）宫腔镜切除；肌壁间肌瘤伴症状行剔除或子宫切除","子宫内膜增生不伴不典型增生：孕激素 3～6 个月后复查活检","不典型增生或内膜癌：全子宫切除 ± 双附件切除，按生育要求个体化","急性大出血：扩宫刮宫或宫腔球囊填塞并纠正贫血","青春期 AUB-O 以调周期、纠贫血为主，慎用刮宫"],"life":["记录月经日记评估疗效","贫血者补铁，Hb <70 g/L 或有症状者输血","肥胖者减重改善排卵障碍"]},"prog":"结构性病变经手术或 LNG-IUS 治疗多可显著改善；排卵障碍者停药后易复发需长期管理。围绝经期 AUB 需警惕内膜癌，早诊者 5 年生存率 >90%。","refs":["中华医学会妇产科学分会妇科内分泌学组《异常子宫出血诊断与治疗指南（2022）》","《妇产科学》第 9 版（人民卫生出版社，2018）"]},{"id":"ob_pid","name":"盆腔炎性疾病","aka":["PID","Pelvic Inflammatory Disease","急性盆腔炎"],"rank":2,"basic":{"define":"女性上生殖道（子宫、输卵管、卵巢、盆腔腹膜）的感染性疾病，包括子宫内膜炎、输卵管炎、输卵管卵巢脓肿与盆腔腹膜炎。多为性传播病原体上行感染，可致不孕、异位妊娠与慢性盆腔痛。","risk":["多个性伴侣或无保护性行为，衣原体/淋球菌感染","年龄 <25 岁","既往 PID 或宫腔操作史（人流、上环）","细菌性阴道病、频繁阴道冲洗","性伴侣有淋病或衣原体感染"],"epi":"育龄女性发病率约 1%～2%；一次 PID 发作后输卵管性不孕风险约 8%～12%，三次发作后升至 40%～60%。"},"patho":"衣原体与淋球菌自宫颈上行至宫腔与输卵管，引起黏膜水肿、脓性渗出与纤毛破坏，炎症扩展形成脓肿；厌氧菌参与混合感染，反复炎症致输卵管粘连闭塞。","dx":{"criteria":["最低诊断标准（三项之一）：下腹压痛、宫颈举痛或子宫/附件区压痛","附加标准：口温 >38.3 ℃、脓性分泌物、分泌物镜检白细胞增多、血沉加快、CRP 升高、淋球菌或衣原体阳性","特异标准：内膜活检示内膜炎、超声/MRI 示输卵管增厚与盆腔积液、腹腔镜见输卵管充血与脓性渗出","发热、下腹痛加剧伴恶心呕吐提示腹膜炎或输卵管卵巢脓肿","排除异位妊娠（HCG）、阑尾炎、子宫内膜异位症与泌尿道感染"],"workup":["双合诊评估宫颈举痛、附件压痛与包块；盆腔超声评估输卵管增厚、脓肿与盆腔积液","宫颈分泌物衣原体与淋球菌核酸检测，性伴侣同步筛查；阴道分泌物常规与细菌性阴道病检测","血常规、CRP，HCG 排除妊娠；必要时血培养","治疗 48～72 小时无改善或诊断不明时腹腔镜"],"grading":"轻度（门诊口服）；中重度（发热明显、脓肿、妊娠或免疫抑制者住院静脉用药）；按病程分急性、慢性与复发性。"},"ddx":[{"name":"异常子宫出血（ob_aub）","point":"与本类 ob_aub 的鉴别点：AUB 以月经失控为主、无盆腔压痛；PID 的出血继发于内膜炎且伴明显压痛。"},{"name":"宫颈上皮内瘤变（ob_cin）","point":"与本类 ob_cin 的鉴别点：CIN 多无症状或接触性出血，无发热与盆腔压痛。"},{"name":"异位妊娠与黄体破裂","point":"急性下腹痛伴 HCG 阳性、盆腔包块与腹膜刺激征，内出血致休克；PID 多有发热与脓性分泌物。"},{"name":"急性阑尾炎","point":"转移性右下腹痛、麦氏点压痛与反跳痛，无宫颈举痛。"},{"name":"卵巢囊肿扭转与子宫内膜异位症","point":"扭转突下腹绞痛、超声示血流信号消失；内异症为周期性疼痛与不孕，无发热。"}],"tx":{"drug":[{"name":"头孢曲松 + 多西环素 + 甲硝唑（住院）","dose":"头孢曲松 1 g 静脉或肌内 qd；多西环素 100 mg 静脉 q12h；甲硝唑 500 mg 静脉 q12h；遵说明书","note":"住院标准三联方案，覆盖淋球菌、衣原体与厌氧菌；头孢西丁 + 多西环素亦为一线。","renal":"肾功能不全时需调整","hepatic":"多西环素与甲硝唑肝功不全慎用","interact":"多西环素与抗酸药、钙剂合用降低吸收"},{"name":"克林霉素 + 庆大霉素（替代）","dose":"克林霉素 900 mg 静脉 q8h；庆大霉素负荷 2 mg/kg 后 1.5 mg/kg q8h；遵说明书","note":"青霉素过敏者适用；监测肾功能与血药浓度。","renal":"按 eGFR 调整并监测谷浓度","hepatic":"克林霉素需减量","interact":"氨基糖苷类与袢利尿剂合用增加耳毒性"},{"name":"氧氟沙星 + 甲硝唑（门诊）","dose":"氧氟沙星 400 mg 口服 bid + 甲硝唑 500 mg 口服 bid，共 14 天；遵说明书","note":"喹诺酮耐药地区慎用；妊娠与哺乳期禁用。","renal":"肾功能不全需减量","hepatic":"严重肝功能不全慎用","interact":"与含铝镁抗酸剂同用降低吸收；与华法林合用增加出血"},{"name":"头孢曲松 + 多西环素 + 甲硝唑（门诊首选）","dose":"头孢曲松 500 mg 肌内注射单次 + 多西环素 100 mg 口服 bid + 甲硝唑 500 mg 口服 bid，共 14 天；遵说明书","note":"规避喹诺酮耐药；妊娠期以阿奇霉素替代多西环素。","renal":"肾功能不全需调整","hepatic":"肝功能不全慎用","interact":"甲硝唑与酒精禁忌；多西环素致光敏"}],"nonDrug":["性伴侣接受筛查与治疗，治疗期间避免性生活直至双方疗程结束","输卵管卵巢脓肿：静脉抗感染 48～72 小时无改善或脓肿 >7 cm 行引流或腹腔镜","妊娠合并 PID：住院静脉治疗，改用妊娠安全方案","IUD 可保留，不必因 PID 取出","慢性盆腔痛伴粘连者可行腹腔镜粘连松解"],"life":["完成 14 天足疗程，避免自行停药","性伴侣同步治疗预防再感染","治疗后 3～6 个月复查衣原体与淋球菌"]},"prog":"及时足疗程治疗者 90% 以上缓解；延误或重复感染者 10%～15% 发生输卵管性不孕，异位妊娠风险升高 6～10 倍，慢性盆腔痛约占 18%～30%。脓肿破裂可致弥漫性腹膜炎与脓毒症。","refs":["中华医学会妇产科学分会感染性疾病协作组《盆腔炎性疾病诊治规范（修订版）》","《妇产科学》第 9 版（人民卫生出版社，2018）","CDC Sexually Transmitted Infections Treatment Guidelines (2021)"]},{"id":"ob_cin","name":"宫颈上皮内瘤变与 HPV 感染","aka":["CIN","Cervical Intraepithelial Neoplasia","宫颈癌前病变"],"rank":3,"basic":{"define":"宫颈上皮内瘤变（CIN）指宫颈鳞状上皮被异型细胞取代的癌前病变，按异型细胞占据上皮层次分 CIN1（LSIL）、CIN2 与 CIN3（HSIL）。高级别 CIN 是宫颈鳞癌的直接癌前病变，高危 HPV 持续感染为必要病因。","risk":["高危型 HPV 持续感染（16、18 型风险最高）","首次性生活年龄过早、多个性伴侣","多产、长期口服避孕药","吸烟、免疫抑制（HIV、器官移植）","宫颈慢性炎症"],"epi":"我国 35～64 岁女性 HPV 感染率约 10%～15%，多为一过性；高危 HPV 持续 10 年者 CIN3 或癌风险约 20%～30%。"},"patho":"高危型 HPV 的 E6、E7 蛋白降解 p53 与 pRb 抑癌蛋白，使细胞周期失控、凋亡受抑与染色体不稳定，导致上皮层内异型增生。持续感染数年至十余年可突破基底膜成为浸润癌。","dx":{"criteria":["高危 HPV 阳性：16/18 型阳性直接阴道镜，其他型结合细胞学分流","细胞学异常：ASC-US 及以上，包括 LSIL、HSIL 与不典型腺细胞","阴道镜见醋酸白上皮、碘不染色、点状或镶嵌血管，取活检定位","病理分 CIN1、CIN2、CIN3；CIN2 需 p16 免疫组化辅助判读","CIN3 累及腺体者需锥切病理与早期浸润癌鉴别"],"workup":["25～64 岁以高危 HPV 联合细胞学筛查（每 5 年）或单独 HPV/细胞学（每 3 年）","阴道镜可疑处多点活检，必要时宫颈管搔刮","CIN2/CIN3 或细胞学高度异常而阴道镜未见病灶者行 LEEP 或冷刀锥切","HPV 分型指导随访；p16/Ki-67 双染辅助分级；HIV 或免疫抑制者缩短筛查间隔"],"grading":"CIN1（LSIL）约 60% 可自行消退；CIN2（HSIL）回归与进展并存，25～30 岁以下可观察后治疗；CIN3（HSIL）进展为浸润癌风险最高，需切除治疗。"},"ddx":[{"name":"异常子宫出血（ob_aub）","point":"与本类 ob_aub 的鉴别点：AUB 源于宫腔与内膜、表现为周期与经量异常；宫颈病变出血多为接触性，需妇科检查与活检区分。"},{"name":"盆腔炎性疾病（ob_pid）","point":"与本类 ob_pid 的鉴别点：PID 以下腹痛、宫颈举痛与脓性分泌物为主并伴发热；CIN 多无症状、由筛查发现。"},{"name":"宫颈息肉与柱状上皮外移","point":"柱状上皮外移呈红色区但碘试验与细胞学正常；息肉为外生赘生物，需活检确认。"},{"name":"宫颈癌（早期）","point":"活检见浸润突破基底膜，可表现为接触性出血与阴道排液，需锥切或根治性手术分期。"}],"tx":{"drug":[{"name":"HPV 预防性疫苗（九价/四价/二价）","dose":"9～14 岁 2 剂（0、6～12 个月）；15 岁及以上 3 剂（0、1～2、6 个月）；遵说明书","note":"一级预防，可预防 70% 以上宫颈癌；接种后仍需定期筛查、不能替代筛查。","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用可能降低免疫应答"},{"name":"干扰素栓/凝胶（局部，辅助）","dose":"遵说明书","note":"CIN1 与 HPV 阳性者的辅助干预，证据有限，不能替代切除治疗，不用于 CIN2/CIN3。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["CIN1 以随访为主，细胞学与 HPV 每年复查；持续 2 年不消退或 HPV16/18 阳性者复查阴道镜","CIN2/CIN3 首选宫颈锥切（LEEP 或冷刀锥切），青春期患者可个体化观察","妊娠期 CIN2/CIN3 推迟至产后 6～8 周复查，仅疑浸润癌时活检","切缘阳性者 6 个月内复查 HPV 与细胞学，可重复切除或随访","锥切后妊娠告知早产与胎膜早破风险"],"life":["HPV 阳性者按 1 年随访，必要时阴道镜","戒烟、减少性伴侣数并坚持使用安全套","锥切后 2 年内每 6 个月复查 HPV 与细胞学","疫苗与筛查联合是最有效预防"]},"prog":"CIN1 半数以上自然消退，CIN3 未治疗约 30%～50% 在 30 年内进展为浸润癌。锥切后复发率约 5%～10%，与切缘状态与 HPV 持续感染相关。","refs":["中华医学会妇科肿瘤学分会《子宫颈癌诊断与治疗指南（2021 年版）》","国家卫生健康委员会《宫颈癌筛查工作方案（2022 年版）》","ASCCP Risk-Based Management Consensus Guidelines (2019)"]}]},{"id":"obgyn_endocrine","name":"妇科内分泌与代谢","rank":7,"summary":"多囊卵巢综合征以鹿特丹标准（排卵障碍、高雄激素、卵巢多囊样改变三项中二项）为主轴，须先排除其他高雄或排卵障碍病因；治疗按需求分流：无生育要求者以生活方式与短效口服避孕药调经，伴胰岛素抵抗加用二甲双胍，有生育要求者用来曲唑促排卵并防 OHSS。","compare":[{"diseaseId":"ob_pcos","dx":"月经稀发或闭经 + 临床或生化高雄激素 + 超声卵巢多囊样改变（单侧卵泡 ≥12 个或卵巢体积 ≥10 ml），三项中 ≥2 项且排除其他病因","key":"鹿特丹标准三项中二项；排卵障碍 + 高雄 + 多囊卵巢三联中的任意组合"}],"diseases":[{"id":"ob_pcos","name":"多囊卵巢综合征","aka":["PCOS","Polycystic ovary syndrome","多囊卵巢","Stein-Leventhal 综合征"],"rank":1,"basic":{"define":"以排卵障碍、高雄激素表现与卵巢多囊样改变为特征的育龄期女性内分泌代谢疾病，常伴胰岛素抵抗、肥胖、血脂异常与子宫内膜增生风险，是育龄妇女无排卵性不孕最常见的原因。","risk":["育龄期女性，尤其 20–35 岁","超重或肥胖（BMI ≥24 kg/m²），腹型肥胖更显著","一级亲属 PCOS 或 2 型糖尿病家族史","青春期肾上腺功能初现提前（阴毛早现）","高糖高脂饮食、久坐缺少运动","抗癫痫药（丙戊酸）等长期用药"],"epi":"我国育龄期女性 PCOS 患病率约为 5%–10%，是排卵障碍性不孕的首要病因，约占无排卵性不孕的 70%–80%。约 50%–70% 患者存在胰岛素抵抗，合并肥胖者比例更高。"},"patho":"下丘脑–垂体–卵巢轴反馈异常使 LH 脉冲频率增高而 FSH 相对不足，卵泡停滞于小窦卵泡期不能成熟，形成多囊样改变并持续无排卵；无排卵与无孕激素对抗使子宫内膜长期暴露于雌激素。卵巢膜细胞在 LH 刺激下雄激素合成增加，同时 SHBG 下降，游离雄激素升高。胰岛素抵抗通过高胰岛素抑制肝脏 SHBG 合成并增强卵巢雄激素合成，形成高雄与高胰岛素的恶性循环。","dx":{"criteria":["适用对象：育龄期及围青春期女性，需符合青春期及更年期不同诊断要点","月经稀发或闭经：月经周期 >35 天，或每年 <8 次","临床高雄：Ferriman-Gallwey 评分 ≥4–6 分（中国常用阈值 ≥4 分），或中重度痤疮、女性型脱发；生化高雄：总睾酮 >2.5–3.0 nmol/L 或高于实验室上限","卵巢多囊样改变：盆腔超声见单侧或双侧卵巢 ≥12 个直径 2–9 mm 卵泡，或卵巢体积 ≥10 ml（新版共识以卵泡数 ≥20 个为阈值时需结合其他条件）","上述排卵障碍、高雄激素、多囊卵巢三项中符合 ≥2 项，并排除其他疾病","中国诊断标准强调排除性：甲状腺疾病、高泌乳素血症、非典型先天性肾上腺皮质增生（17-OHP）、库欣综合征、卵巢或肾上腺分泌雄激素肿瘤"],"workup":["病史与月经生育史、体重变化、多毛与痤疮评分、家族史","性激素六项（月经第 2–4 天）：LH/FSH 比值 >2 提示异常；睾酮、硫酸脱氢表雄酮","17-羟孕酮（排除 21-羟化酶缺陷，>2–4 nmol/L 需 ACTH 兴奋试验）","甲状腺功能、泌乳素（排除甲减与高泌乳素血症）","糖代谢：空腹血糖、空腹胰岛素、糖化血红蛋白，必要时 OGTT 与胰岛素释放试验，计算 HOMA-IR","血脂、肝功、尿酸；盆腔超声评估卵巢多囊样改变与内膜厚度","早卵泡期（月经第 2–5 天）经阴道超声","筛查心理健康与睡眠呼吸暂停（打鼾、嗜睡）"],"grading":"按表型分 A 型（排卵障碍 + 高雄 + 多囊卵巢）、B 型（排卵障碍 + 高雄）、C 型（高雄 + 多囊卵巢）、D 型（排卵障碍 + 多囊卵巢）。Ferriman-Gallwey 评分 ≥4–6 提示临床高雄。BMI ≥24 为超重、≥28 为肥胖（中国标准）。内膜厚度 ≥10 mm 且长期无排卵需警惕增生。"},"ddx":[{"name":"高泌乳素血症与甲状腺功能异常（妇科其他大类功能疾病）","point":"与本类及 obgyn_3 中功能性疾病鉴别：泌乳素升高或 TSH 异常致月经稀发与排卵障碍，但无典型高雄与多囊样改变，纠正原发病后月经恢复。"},{"name":"非典型先天性肾上腺皮质增生（21-羟化酶缺陷）","point":"17-羟孕酮 >2 nmol/L 需 ACTH 兴奋试验确认；伴雄激素增高但超声卵巢多囊改变不典型。"},{"name":"库欣综合征","point":"向心性肥胖、紫纹、满月脸伴高血压、血糖升高，皮质醇节律与深夜唾液皮质醇异常。"},{"name":"分泌雄激素的卵巢或肾上腺肿瘤","point":"快速进展的男性化（声音变粗、阴蒂肥大），睾酮或 DHEAS 显著升高，影像见单侧肿块。"},{"name":"特发性多毛症","point":"单纯多毛而无排卵障碍与多囊卵巢，月经规律，雄激素多在正常范围。"}],"tx":{"drug":[{"name":"复方短效口服避孕药（炔雌醇环丙孕酮、屈螺酮炔雌醇）","dose":"每日 1 片，21 天活性片后停药 7 天，规范周期服用；遵说明书","note":"无生育要求者调整月经周期与降低雄激素的一线用药，疗程 3–6 个月后评估。","renal":"遵说明书","hepatic":"肝功能异常、既往胆汁淤积者禁用或慎用","interact":"与诱导肝酶的抗癫痫药、利福平合用降低避孕效果；吸烟 >35 岁女性血栓风险增加"},{"name":"二甲双胍","dose":"起始 500 mg bid 餐后服，按耐受逐渐增至 1000–1500 mg/日（最大 2000 mg/日）；遵说明书","note":"用于合并胰岛素抵抗、糖耐量异常或肥胖者，改善胰岛素敏感性并助月经恢复；促排卵前可使用 2–3 个月。","renal":"eGFR <45 ml/min/1.73m² 减量，<30 禁用","hepatic":"严重肝功能不全禁用","interact":"含碘造影剂检查前后需暂停；与酒精、肾毒药物合用增加乳酸酸中毒风险"},{"name":"来曲唑","dose":"月经第 3–5 天起 2.5 mg qd 共 5 天；无排卵者可增至 5 mg；遵说明书","note":"已婚雌酚之后的首选促排卵药，单排优势卵泡、OHSS 风险低于克罗米芬；需监测卵泡与内膜。","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"与雌激素类药物合用效果减弱；妊娠期禁用"},{"name":"克罗米芬（枸橼酸氯米芬）","dose":"月经第 3–5 天起 50 mg qd 共 5 天，无效可在下一周期增至 100 mg；遵说明书","note":"抗雌激素作用可致内膜薄与宫颈黏液差，来曲唑不可及时使用。","renal":"遵说明书","hepatic":"肝功能异常慎用","interact":"与抗雌激素药合用相互拮抗"},{"name":"螺内酯（抗高雄辅助）","dose":"20–25 mg qd，可增至 50–100 mg/日，疗程 6 个月以上；遵说明书","note":"用于多毛，需联合避孕措施防致畸；起效慢，需与口服避孕药并用。","renal":"肾功能不全与高钾风险者慎用","hepatic":"遵说明书","interact":"与 ACEI、ARB、保钾利尿剂合用致高钾；与口服避孕药合用可能干扰周期"},{"name":"地屈孕酮（周期性撤退出血）","dose":"10–20 mg/日，连用 10–14 天，每月一周期；遵说明书","note":"用于避孕药不耐受或无生育要求者保护子宫内膜，不能降低雄激素。","renal":"遵说明书","hepatic":"严重肝功能不全者慎用","interact":"与肝酶诱导剂合用代谢加快"}],"nonDrug":["生活方式干预为一线：超重者减重 5%–10% 可恢复排卵并改善代谢","有生育要求者促排卵，必要时宫腔内人工授精或体外受精；促排周期需超声监测卵泡与 OHSS","子宫内膜保护：长期无排卵、内膜增厚者先行孕激素周期治疗或诊刮排除增生","多毛与痤疮可联合光电脱毛、外用维 A 酸或过氧苯甲酰","合并 OSA 者转诊呼吸科评估 CPAP"],"life":["规律有氧运动 ≥150 min/周，减少精制糖与高 GI 食物，增加膳食纤维","监测体重、腰围与血压；每年复查空腹血糖、血脂与肝功能","备孕者提前 3 个月补充叶酸 0.4 mg/日，减重后再促排卵成功率更高","长期闭经者定期监测内膜厚度，避免无孕激素保护的长期雌激素暴露"]},"prog":"经生活方式干预与药物后约 50%–60% 无生育要求者可恢复规律月经；促排卵治疗单周期排卵率约 70%–80%，累积妊娠率可达 40%–70%。PCOS 患者远期 2 型糖尿病风险增加 2–4 倍、子宫内膜癌风险增加 2–6 倍，且妊娠期糖尿病与妊娠期高血压风险升高，需终身随访。","refs":["中华医学会妇产科学分会内分泌学组《多囊卵巢综合征中国诊疗指南（2018 年版）》","《多囊卵巢综合征诊治内分泌专家共识》","国际循证指南 PCOS Guideline 2023（Monash）","《妇产科学》第 9 版 多囊卵巢综合征"]}]}]},"onco":{"categories":[{"id":"thoracic","name":"胸部肿瘤","rank":1,"summary":"肺癌按 TNM 与驱动基因分层：可切除者手术±辅助，局部晚期同步放化疗后免疫巩固，晚期靶向或免疫联合化疗；食管癌以手术为核心联合围手术期治疗。","compare":[{"diseaseId":"on_lung_nsclc","dx":"影像见肺结节/肿块，病理证实腺癌/鳞癌/大细胞癌，已明确 TNM 与 EGFR/ALK/ROS1","key":"腺癌为主，驱动基因阳性率高，可分型后首选靶向"},{"diseaseId":"on_lung_sclc","dx":"病理见小蓝圆细胞、核分裂多、N/C 比高，Syn/CgA/CD56 阳性，Ki-67 多 >50%，多有纵隔融合淋巴结","key":"倍增快、易早转移，驱动基因无价值，化疗±免疫±放疗为主"},{"diseaseId":"on_esoph","dx":"吞咽困难，胃镜活检证实鳞癌或腺癌，超声内镜评估浸润深度与局部淋巴结","key":"原发在食管壁，鳞癌占我国 90% 以上"}],"diseases":[{"id":"on_lung_nsclc","name":"非小细胞肺癌","aka":["NSCLC","肺癌","肺腺癌","肺鳞癌","驱动基因阳性肺癌"],"rank":1,"basic":{"define":"起源于支气管黏膜上皮及腺体的恶性肿瘤，占肺癌 80%–85%，含腺癌、鳞癌、大细胞癌；治疗由 TNM 与分子分型决定。","risk":["吸烟（含二手烟）","年龄 ≥50 岁，尤重度吸烟者","石棉、砷、铬、氡等职业暴露","COPD、肺纤维化、陈旧结核瘢痕","一级亲属肺癌家族史","空气污染与室内油烟"],"epi":"我国肺癌居发病与死亡首位，年新发超 100 万；亚洲不吸烟腺癌患者 EGFR 突变率可达 40%–50%。"},"patho":"EGFR、KRAS 等原癌基因激活与 TP53、RB 等抑癌基因失活驱动，腺癌常见 EGFR 突变与 ALK/ROS1/RET 融合；肿瘤促血管生成并抑制局部免疫（PD-L1/PD-1），经淋巴与血行转移至纵隔淋巴结、对侧肺、骨、肝、脑、肾上腺。","dx":{"criteria":["组织或细胞学病理证实非小细胞肺癌为金标准","腺癌及不吸烟鳞癌常规检测 EGFR、ALK、ROS1、BRAF、KRAS、MET 14 跳跃、RET、HER2、NTRK；组织不足可用 ctDNA 补充","PD-L1 TPS/CPS 作为免疫治疗伴随诊断","TNM 第 8 版：>3–5 cm 为 T2，>5–7 cm 为 T3，>7 cm 或侵及膈肌/纵隔/心脏/大血管/喉返神经为 T4；N1 同侧肺门、N2 同侧纵隔、N3 对侧纵隔/锁骨上；M1a 胸膜播散或对侧肺结节，M1c 多发远处转移","Ⅰ期 T1–2a N0；Ⅱ期 T2b–3 N1 或 T1–2 N1；Ⅲ期 N2/局部进展；Ⅳ期 任何 M1"],"workup":["胸部+上腹增强 CT；拟根治者行 PET/CT","头颅 MRI 增强：Ⅱ期以上或腺癌常规","EBUS-TBNA 或纵隔镜：可疑 N2 须病理证实","纤支镜或 CT 引导穿刺取组织行病理与分子检测","肺功能、DLCO、血气；骨扫描；CEA、CYFRA21-1 辅助监测"],"grading":"TNM 第 8 版 Ⅰ–Ⅳ 期；分子分型：EGFR 敏感突变、ALK/ROS1/RET/NTRK 融合、KRAS G12C、BRAF V600E、MET 14 跳跃、PD-L1 TPS ≥50%。"},"ddx":[{"name":"小细胞肺癌（on_lung_sclc）","point":"与本类 on_lung_sclc 的鉴别点：NSCLC 生长较慢、腺癌多含磨玻璃成分；SCLC 为中央型大肿块、倍增快，小蓝圆细胞伴神经内分泌标志物阳性，不检测驱动基因。"},{"name":"食管癌（on_esoph）","point":"与本类 on_esoph 的鉴别点：食管癌以吞咽困难为主、病灶在食管壁；肺癌以咳嗽咯血为主，肺门病灶压迫食管时需胃镜定位原发。"},{"name":"肺结核球","point":"上叶尖后段、钙化伴卫星灶，T-SPOT 阳性，痰分枝杆菌核酸可确诊；PET 高摄取不能排除。"},{"name":"肺孤立性转移瘤","point":"多有原发肿瘤史，多发、边界清楚；单发时靠免疫组化（TTF-1、p40）判断来源。"},{"name":"机化性肺炎","point":"游走性斑片影、激素治疗有效，穿刺活检可确诊。"}],"tx":{"drug":[{"name":"奥希替尼（第三代 EGFR-TKI）","dose":"80 mg qd 口服；一线 EGFR 19del/L858R 晚期、T790M 阳性二线；疗程按 CSCO/NCCN 指南与影像评估确定","note":"皮疹、腹泻、甲沟炎；警惕间质性肺炎与 QTc 延长","renal":"eGFR 15–30 监测使用，终末期遵说明书","hepatic":"重度减量或慎用","interact":"强效 CYP3A 诱导剂（利福平）显著降浓度"},{"name":"阿来替尼（ALK-TKI）","dose":"600 mg bid 口服；ALK 融合晚期一线首选之一，疗程按指南确定","note":"穿透血脑屏障好；便秘、水肿、肌痛、心动过缓","renal":"重度肾损遵说明书","hepatic":"重度肝功能不全减量","interact":"避免强效 CYP3A 抑制剂/诱导剂"},{"name":"克唑替尼（ALK/ROS1 阳性）","dose":"250 mg bid 口服；ROS1 融合一线/ALK 后线；按说明书","note":"视觉障碍、恶心、肝损，监测视力与心电图","renal":"eGFR <30 减量","hepatic":"肝损起始剂量下调","interact":"避免强效 CYP3A 抑制剂"},{"name":"帕博利珠单抗（PD-1 抑制剂）","dose":"200 mg q3w 或 400 mg q6w 静滴；PD-L1 高表达一线单药、联合化疗一线、Ⅲ期同步放化疗后巩固；按指南执行","note":"可致免疫性肺炎、甲状腺炎、肝炎；活动性自身免疫病慎用","renal":"无需调整","hepatic":"重度资料有限","interact":"避免长期大剂量激素（止吐剂量除外）"},{"name":"含铂双药化疗（AP/TP）","dose":"培美曲塞 500 mg/m²+顺铂 75 mg/m² 或卡铂 AUC 5–6 q3w（非鳞癌）；鳞癌用紫杉醇+铂类；按 CSCO/NCCN 指南与体表面积调整","note":"培美曲塞前需地塞米松、叶酸、维生素 B12 预处理","renal":"培美曲塞 CrCl <45 不用；顺铂 eGFR <60 慎用","hepatic":"肝功能不全需调整","interact":"培美曲塞与 NSAIDs 延迟排泄"},{"name":"安罗替尼（多靶点抗血管）","dose":"12 mg qd 服 2 周停 1 周；Ⅲ线及以上，按 CSCO 指南确定","note":"高血压、手足皮肤反应、出血；中央型鳞癌慎用","renal":"重度肾损慎用","hepatic":"重度肝损慎用","interact":"与抗凝药合用增加出血"}],"nonDrug":["Ⅰ–Ⅱ期及部分ⅢA：解剖性肺叶切除+系统淋巴结清扫，按分期行辅助化疗或靶向/免疫","不可切除Ⅲ期：同步放化疗后免疫巩固（PD-L1 ≥1%）","寡转移：SBRT、消融或减症手术；脑转移 ≤4 个病灶优先 SRS","胸腔积液/气道梗阻：胸膜固定、气道支架、姑息放疗"],"life":["戒烟并避免二手烟；COPD 者肺康复","每 2–3 个月复查胸部 CT 与肿瘤标志物","TKI 期间监测皮疹、肝功与心电图；免疫治疗记录不良反应","营养与有氧运动，避免活疫苗"]},"prog":"Ⅰ期完全切除 5 年生存 70%–90%，Ⅲ期 20%–35%，Ⅳ期 5%–10%；EGFR/ALK 阳性者可中位生存数年。","refs":["CSCO 非小细胞肺癌诊疗指南（2024）","NCCN Non-Small Cell Lung Cancer（2024）","IASLC 第 8 版肺癌 TNM 分期"]},{"id":"on_lung_sclc","name":"小细胞肺癌","aka":["SCLC","小细胞癌","局限期小细胞肺癌","广泛期小细胞肺癌"],"rank":2,"basic":{"define":"起源于神经内分泌细胞的高侵袭性肺癌，约占肺癌 13%–15%，倍增快，按 VALG 分局限期与广泛期。","risk":["重度吸烟（包年数为独立危险因素）","中位发病 65 岁，男性略多","电离辐射、石棉暴露","COPD 与肺纤维化","肿瘤家族史"],"epi":"我国 SCLC 占肺癌约 12%–15%；局限期 5 年生存 20%–25%，广泛期 2%–5%。"},"patho":"RB1 与 TP53 双失活驱动，细胞小、核分裂活跃，易早期血行与淋巴转移；可伴副肿瘤综合征（SIADH 低钠、异位 ACTH、Lambert-Eaton）。化疗初期高度敏感但易快速耐药，脑转移率高。","dx":{"criteria":["病理见小蓝圆细胞（胞浆少、染色质细颗粒状、N/C 比高），核分裂 >11/2 mm²","Syn、CgA、CD56、INSM1 至少 1–2 项阳性，Ki-67 多 50%–100%","VALG 分期：局限期=病变限于一侧胸腔、可单一放疗野覆盖且无胸腔外转移；广泛期=超出或伴恶性胸/心包积液","必须行头颅 MRI、胸腹增强 CT、骨扫描或 PET/CT；基线血钠（SIADH）、LDH、NSE"],"workup":["胸腹增强 CT；PET/CT 首选初始分期","头颅 MRI 增强（不能以 CT 替代）","骨扫描评估骨转移；肺功能以兼容放疗","NSE、ProGRP 动态监测"],"grading":"VALG 局限期/广泛期；复发分敏感（一线结束后 ≥90 天）与耐药（<90 天）。"},"ddx":[{"name":"非小细胞肺癌（on_lung_nsclc）","point":"与本类 on_lung_nsclc 的鉴别点：SCLC 细胞小、Ki-67 高、神经内分泌标志物阳性、纵隔淋巴结融合；NSCLC 细胞较大、可见腺管或角化珠。"},{"name":"食管癌（on_esoph）","point":"与本类 on_esoph 的鉴别点：食管癌原发在食管壁；SCLC 为纵隔病灶压迫食管时才出现吞咽困难，伴融合淋巴结。"},{"name":"肺典型/不典型类癌","point":"类癌生长慢、典型类癌 Ki-67 <3%；SCLC Ki-67 >50%、多发转移。"},{"name":"纵隔淋巴瘤","point":"可有纵隔大肿块与 B 症状，流式与免疫表型可确诊。"},{"name":"纵隔淋巴结结核","point":"低热盗汗、结核接触史，涂片/核酸阳性，病灶伴钙化坏死。"}],"tx":{"drug":[{"name":"依托泊苷+铂类（EP/EC）","dose":"依托泊苷 100 mg/m² d1–3+顺铂 75 mg/m² 或卡铂 AUC 5 d1，q3w；按 CSCO/NCCN 指南与体表面积调整","note":"局限与广泛期基础方案；广泛期联合 PD-L1；肾功差者优选卡铂","renal":"顺铂需水化并随 CrCl 减量；卡铂按 Calvert 公式","hepatic":"依托泊苷重度肝损减量","interact":"顺铂与氨基糖苷类叠加肾毒"},{"name":"伊立替康+铂类（IP）","dose":"伊立替康 175 mg/m² 或 60–65 mg/m² d1、8+顺铂/卡铂，q3w；按指南与体表面积调整","note":"迟发性腹泻与骨髓抑制，备洛哌丁胺","renal":"肾功能不全慎用","hepatic":"胆红素 >1.5 倍上限减量","interact":"UGT1A1 *28 纯合者毒性增加"},{"name":"阿替利珠单抗（PD-L1）","dose":"1200 mg q3w 联合 EP/EC 4 周期后单药维持；广泛期一线；按指南执行","note":"延长总生存；监测免疫性肺炎与肝功","renal":"无需调整","hepatic":"重度慎用","interact":"避免大剂量激素同时启动"},{"name":"度伐利尤单抗（PD-L1）","dose":"1500 mg q3w 联合 EP 后单药维持；广泛期一线；按指南执行","note":"与阿替利珠单抗同类，不联合交替","renal":"无需调整","hepatic":"轻中度无需调整","interact":"禁用活疫苗"},{"name":"拓扑替康（二线）","dose":"1.5 mg/m² 静滴 d1–5 q3w，或口服 2.3 mg/m² d1–5 q3w；敏感复发；按说明书减量","note":"骨髓抑制明显，需 G-CSF 支持","renal":"CrCl 降低需减量","hepatic":"重度肝损减量","interact":"P-gp 抑制剂升高浓度"}],"nonDrug":["局限期：化疗第 1 周期内尽早启动胸部放疗；完全缓解者评估全脑预防照射","广泛期：化疗+免疫为基础，放疗用于症状缓解或寡转移","T1–2N0 局限期可评估手术（少见）","上腔静脉受压、气道梗阻：急诊放疗或支架"],"life":["绝对戒烟；监测血象与肝肾功能","每 2–3 周期复查胸部 CT，治疗后 3 个月头颅 MRI","SIADH 者限水并纠正低钠；三联预防性止吐与营养支持"]},"prog":"局限期中位生存 15–25 个月、5 年生存 20%–25%；广泛期中位生存 10–13 个月，5 年生存 <5%。耐药复发预后极差。","refs":["CSCO 小细胞肺癌诊疗指南（2024）","NCCN Small Cell Lung Cancer（2024）"]},{"id":"on_esoph","name":"食管癌","aka":["食管鳞癌","ESCC","食管腺癌","食道癌"],"rank":3,"basic":{"define":"起源于食管黏膜上皮的恶性肿瘤，我国 90% 以上为鳞癌，腺癌多见于下段与胃食管交界；手术为核心联合围手术期放化疗与免疫。","risk":["吸烟与长期大量饮酒（协同）","烫食、腌制与霉变食物","维生素 A/C、叶酸、锌缺乏","Barrett 食管与反流（腺癌）","食管白斑、腐蚀性狭窄、贲门失弛缓症","肥胖（腺癌相关）"],"epi":"我国年新发约 22–25 万，地域聚集（太行山区、潮汕、苏北）；总体 5 年生存 20%–30%。"},"patho":"长期理化刺激引起慢性炎症—异型增生—原位癌—浸润癌；鳞癌多在胸中段，可侵犯主动脉、气管、心包并经食管旁与纵隔淋巴结转移；腺癌由 Barrett 化生进展，晚期可形成食管气管瘘。","dx":{"criteria":["胃镜+组织活检为金标准，须明确组织学类型","典型表现：进行性吞咽困难、胸骨后痛、消瘦；喉返神经受累可声嘶","TNM 第 8 版：T1 黏膜下层内、T2 肌层、T3 外膜、T4 侵及周围结构；N1 1–2 枚、N2 3–6 枚、N3 ≥7 枚；M1 远处转移","EUS 判断 T 与局部 N；按距门齿分上段 15–25、中段 25–33、下段 33–40 cm","T1a 可行内镜 ESD，术前放大内镜+超声评估深度"],"workup":["胃镜+碘染/NBI+活检，记录长度、环周与部位","超声内镜：T 与局部 N；颈部超声排除锁骨上转移","颈胸腹增强 CT，必要时 PET/CT","心肺功能、营养评估（白蛋白、BMI）","新辅助前完成 PD-L1、HER2 检测"],"grading":"TNM 第 8 版；分颈段、胸上/中/下段与胃食管交界（Siewert 分型）；浅表型依深度 M1–M3 与 SM。"},"ddx":[{"name":"非小细胞肺癌（on_lung_nsclc）","point":"与本类 on_lung_nsclc 的鉴别点：食管癌以吞咽困难首发、胃镜见黏膜病变；肺癌原发在肺内，纵隔淋巴结压迫食管时胃镜黏膜多正常。"},{"name":"小细胞肺癌（on_lung_sclc）","point":"与本类 on_lung_sclc 的鉴别点：SCLC 压迫食管伴低钠与纵隔巨大团块；食管癌病灶在食管壁内，内镜与 EUS 可区分。"},{"name":"贲门失弛缓症","point":"液固均困难、间歇性，造影见「鸟嘴样」狭窄与食管扩张；需与肿瘤假性贲门失弛缓鉴别。"},{"name":"良性食管狭窄","point":"腐蚀剂误服或长期反流史，狭窄段长且对称、黏膜光滑。"},{"name":"食管平滑肌瘤","point":"黏膜下隆起、黏膜完整，EUS 见均匀低回声肿块，生长慢。"}],"tx":{"drug":[{"name":"氟尿嘧啶+铂类（新辅助）","dose":"顺铂 75–80 mg/m²+5-FU 750–1000 mg/m²/d 持续输注；或紫杉醇+卡铂（CROSS）；按 CSCO/NCCN 指南与体表面积调整","note":"局部晚期鳞癌首选新辅助同步放化疗，腺癌常用围手术期化疗","renal":"顺铂 CrCl <50 减量或改卡铂","hepatic":"肝功能不全需调整剂量","interact":"5-FU 与华法林显著增强抗凝"},{"name":"卡培他滨","dose":"1000–1250 mg/m² bid d1–14 q3w；替代输注 5-FU；按说明书","note":"手足综合征与腹泻；≥2 级腹泻停药补液","renal":"CrCl 30–50 减量，<30 禁用","hepatic":"重度慎用","interact":"与华法林增加出血"},{"name":"帕博利珠单抗","dose":"200 mg q3w；鳞癌新辅助或一线联合铂+氟尿嘧啶；按说明书","note":"PD-L1 CPS 选人群；食管瘘或活动性感染为相对禁忌","renal":"无需调整","hepatic":"轻中度无需调整","interact":"避免大剂量激素同时使用"},{"name":"纳武利尤单抗","dose":"240 mg q2w、360 mg q3w 或 480 mg q4w；新辅助放化疗+术后辅助或晚期后线；按指南执行","note":"联合放化疗可延长无事件生存","renal":"无需调整","hepatic":"轻中度无需调整","interact":"禁用活疫苗"},{"name":"曲妥珠单抗（HER2 阳性腺癌）","dose":"首剂 8 mg/kg，之后 6 mg/kg q3w；联合铂+氟尿嘧啶；按说明书","note":"首次输注监测过敏；每 3 个月评估 LVEF","renal":"无需调整","hepatic":"轻中度无需调整","interact":"避免与蒽环类联用"}],"nonDrug":["T1a 无淋巴结转移：内镜黏膜下剥离术（ESD）","T1b–T2N0：食管切除+二野/三野淋巴结清扫","局部晚期：新辅助放化疗或化疗+手术；不可切除者根治性放疗 50–60 Gy","晚期：化疗/免疫/靶向；梗阻行支架、营养管或姑息放疗","食管气管瘘：禁食、覆膜支架置入与抗感染"],"life":["戒烟酒，避免烫食与腌制霉变食物；高发区胃镜筛查","术后少量多餐，吻合口狭窄可扩张；管理反流与倾倒综合征","每 3–6 个月复查胃镜/增强 CT"]},"prog":"T1a 内镜治疗 5 年生存 >90%；Ⅰ期手术 60%–70%；局部晚期新辅助+手术 30%–45%；转移性中位生存 10–15 个月。","refs":["CSCO 食管癌诊疗指南（2024）","中国食管癌筛查与早诊早治指南（2020）","NCCN Esophageal/EGJ Cancers（2024）"]}]},{"id":"gi_tumor","name":"消化肿瘤","rank":2,"summary":"胃癌与结直肠癌以规范分期、外科根治+围手术期治疗为核心，HER2、MSI/dMMR、RAS/BRAF 决定靶向与免疫；肝细胞癌按 Child-Pugh 与 BCLC 双轨决策。","compare":[{"diseaseId":"on_gastric","dx":"上腹痛、消瘦、贫血或黑便，胃镜活检证实腺癌，EUS+胸腹增强 CT 完成 cTNM","key":"胃镜病理为金标准，须检测 HER2、MSI/MMR 与 PD-L1"},{"diseaseId":"on_crc","dx":"便血、排便习惯改变、贫血或腹痛，结肠镜活检证实腺癌，胸腹盆腔增强 CT 分期","key":"常规检测 RAS/BRAF、MSI/MMR；直肠癌需骨盆 MRI 评估环周切缘"},{"diseaseId":"on_hcc","dx":"肝硬化/肝炎背景+肝内实性占位，动态增强「快进快出」，AFP 辅助","key":"多数可影像临床诊断，Child-Pugh 与 BCLC 决定治疗"}],"diseases":[{"id":"on_gastric","name":"胃癌","aka":["胃腺癌","胃部恶性肿瘤","印戒细胞癌"],"rank":1,"basic":{"define":"起源于胃黏膜上皮的恶性肿瘤，多为腺癌（肠型与弥漫型），我国以进展期为主；按 cTNM 与 HER2、MSI/dMMR、PD-L1 分层。","risk":["幽门螺杆菌感染（最重要可干预因素）","高盐、腌制与熏制食物","吸烟与大量饮酒","萎缩性胃炎、肠化生、异型增生","残胃与恶性贫血","胃癌家族史与 EBV 感染"],"epi":"我国年新发约 48 万，居发病第 5、死亡第 3 位；早期胃癌比例仅约 20%，根治术后 5 年生存约 50%。"},"patho":"H. pylori 感染引发慢性炎症→萎缩→肠化生→异型增生→肠型腺癌（Correa 级联）；弥漫型（印戒细胞）与 CDH1 突变相关，呈皮革胃浸润。侵出浆膜后经腹膜播散，沿胃周 1–16 站淋巴结转移，血行转移以肝为主。","dx":{"criteria":["胃镜+多点活检（≥6 块）病理证实腺癌为金标准","必须检测 HER2（IHC+FISH）、MSI/MMR 与 PD-L1 CPS","TNM 第 8 版：T1 黏膜/黏膜下、T2 肌层、T3 浆膜下、T4a 穿透浆膜、T4b 侵犯邻近结构；N1 1–2 枚、N2 3–6 枚、N3 ≥7 枚；M1 腹膜或远处转移","EUS 评估 cT 与局部淋巴结；可疑腹膜转移加腹腔镜探查+细胞学","胃食管交界癌按 Siewert 分型 Ⅰ–Ⅲ 决定手术与清扫范围"],"workup":["胃镜+多点活检，幽门螺杆菌检测","胸腹盆腔增强 CT 与超声内镜；进展期行腹腔镜探查+细胞学","MSI/MMR、HER2、PD-L1 CPS","营养评估、贫血与铁代谢"],"grading":"TNM 第 8 版 Ⅰ–Ⅳ 期；Lauren 分型肠型/弥漫型/混合型；分级 G1–G3；分子亚型（EBV、MSI、染色体不稳定、基因组稳定）。"},"ddx":[{"name":"结直肠癌（on_crc）","point":"与本类 on_crc 的鉴别点：胃癌以上腹痛、早饱、消瘦、黑便为主；结直肠癌以便血、排便改变、肠梗阻或贫血为主，结肠镜定位。"},{"name":"肝细胞癌（on_hcc）","point":"与本类 on_hcc 的鉴别点：HCC 多有肝硬化背景、「快进快出」且 AFP 升高；胃癌肝转移有胃内原发灶与 CEA/CA19-9 升高。"},{"name":"胃淋巴瘤","point":"病理为淋巴组织增生、CD20 阳性，胃壁弥漫增厚；H. pylori 根除可使 MALT 淋巴瘤缓解。"},{"name":"良性胃溃疡","point":"形态规则、活检良性，PPI 治疗 6–8 周可愈合。"},{"name":"胃间质瘤","point":"黏膜下外生性肿块，CD117/DOG1 阳性，生长慢。"}],"tx":{"drug":[{"name":"奥沙利铂+卡培他滨（XELOX）","dose":"奥沙利铂 130 mg/m² d1+卡培他滨 1000 mg/m² bid d1–14，q3w；按 CSCO/NCCN 指南与体表面积调整","note":"奥沙利铂累积神经毒性，≥2 级感觉异常减量","renal":"卡培他滨 CrCl 30–50 减量、<30 禁用","hepatic":"卡培他滨重度肝损慎用","interact":"卡培他滨与华法林增加出血"},{"name":"替吉奥（S-1）","dose":"按体表面积：<1.25 m² 40 mg、1.25–1.5 m² 50 mg、>1.5 m² 60 mg，bid 服 4 周停 2 周；单药或联合铂类；按指南调整","note":"亚洲人耐受好；腹泻、口炎、色素沉着、骨髓抑制","renal":"CrCl <30 禁用或减量","hepatic":"肝功能不全减量","interact":"不可与卡培他滨等氟尿嘧啶类联用"},{"name":"曲妥珠单抗（HER2 阳性）","dose":"首剂 8 mg/kg，之后 6 mg/kg q3w，联合氟尿嘧啶类+铂类；按说明书","note":"仅 IHC 3+ 或 IHC 2+ 且 FISH 阳性适用","renal":"无需调整","hepatic":"轻中度无需调整","interact":"避免与蒽环类联用"},{"name":"帕博利珠单抗","dose":"200 mg q3w 或 400 mg q6w；PD-L1 CPS ≥5（或 ≥1）联合化疗一线及 MSI-H 晚期；按指南执行","note":"按 CPS 选人群；免疫相关不良反应需早期识别","renal":"无需调整","hepatic":"轻中度无需调整","interact":"避免大剂量激素同时使用"},{"name":"雷莫西尤单抗（VEGFR-2）","dose":"8 mg/kg q2w 联合紫杉醇；HER2 阴性二线；遵说明书","note":"高血压、蛋白尿、出血需监测","renal":"重度肾损慎用","hepatic":"重度肝损慎用","interact":"与抗凝药注意出血"},{"name":"阿帕替尼","dose":"850 mg qd 餐后 30 分钟服；三线及以后；按说明书减量","note":"高血压、手足皮肤反应、蛋白尿","renal":"重度肾损慎用","hepatic":"重度肝损减量","interact":"CYP3A4 抑制剂/诱导剂影响浓度"}],"nonDrug":["早期 T1a：内镜黏膜下剥离术（ESD），需分化型、无溃疡且 ≤2 cm 等绝对适应证","进展期：D2 根治性胃切除+淋巴结清扫，细胞学阳性按转移处理","围手术期化疗用于 cT3–4 或 N+，术后辅助一般 6 周期","晚期：系统治疗+减症手术；梗阻行营养管或支架"],"life":["根除幽门螺杆菌，少腌制高盐，戒烟限酒","前 2 年每 3–6 个月复查胃镜与增强 CT","全胃切除者补维生素 B12、铁、叶酸；少量多餐","体重与白蛋白监测，必要时营养支持"]},"prog":"早期 ESD/根治术后 5 年生存 >90%；Ⅱ–Ⅲ 期 40%–60%；Ⅳ 期中位生存 12–18 个月。弥漫型与低分化预后差。","refs":["CSCO 胃癌诊疗指南（2024）","中国胃癌筛查与早诊早治指南（2022，北京）","NCCN Gastric Cancer（2024）"]},{"id":"on_crc","name":"结直肠癌","aka":["CRC","大肠癌","结肠癌","直肠癌"],"rank":2,"basic":{"define":"起源于结肠或直肠黏膜上皮的恶性肿瘤，90% 以上为腺癌，多经腺瘤—癌序列发生；以根治性手术为核心，RAS/BRAF/MSI 决定治疗。","risk":["年龄 ≥50 岁，近年年轻化明显","红肉/加工肉多、纤维少、肥胖、少运动","结直肠腺瘤或既往结直肠癌史","炎症性肠病（UC 病程 >8–10 年）","家族史或 Lynch 综合征、FAP","吸烟与大量饮酒"],"epi":"我国年新发约 51 万，居发病第 2、死亡第 4 位；早期 5 年生存 >90%，晚期不足 20%。"},"patho":"APC—KRAS—TP53 腺瘤癌序列驱动多数结肠癌；MSI-H/dMMR 见于 Lynch 综合征与约 15% 散发者；BRAF V600E 多见于右半结肠。肿瘤分层侵犯肠壁，经肠周淋巴结转移，血行转移以肝、肺为主。","dx":{"criteria":["结肠镜+活检病理证实腺癌为金标准；80% 以上直肠癌可经指检触及","检测 RAS（KRAS/NRAS）与 BRAF、MSI/MMR，晚期加做 HER2","TNM 第 8 版：T1 黏膜下、T2 肌层、T3 浆膜下、T4a 穿透腹膜、T4b 侵犯邻近器官；N1 1–3 枚、N2 ≥4 枚；M1b 多器官或腹膜转移","直肠癌需高分辨 MRI 评估环周切缘（CRM）与括约肌受累"],"workup":["全结肠镜；CEA、CA19-9 基线","胸腹盆腔增强 CT；直肠癌加盆腔 MRI","病理分化、脉管/神经侵犯、肿瘤出芽","<50 岁或多发原发者行 MMR+胚系检测"],"grading":"TNM 第 8 版 Ⅰ–Ⅳ 期；直肠癌距肛缘 ≤5 cm 低位、5–10 cm 中位、>10 cm 高位；分子分型 MSI-H/dMMR、RAS/BRAF 突变、HER2 扩增。"},"ddx":[{"name":"胃癌（on_gastric）","point":"与本类 on_gastric 的鉴别点：结直肠癌以便血、排便改变、贫血为主；胃癌以上腹痛、早饱、消瘦为主。肝转移来源可由 CK7/CK20、CDX2 判断。"},{"name":"肝细胞癌（on_hcc）","point":"与本类 on_hcc 的鉴别点：HCC 有肝硬化背景与「快进快出」、AFP 升高；结直肠癌肝转移呈「牛眼征」、CEA 升高。"},{"name":"痔/肛裂","point":"便鲜血伴肛门痛，指检见痔核/裂口；40 岁以上首次便血应完成全结肠镜。"},{"name":"炎症性肠病","point":"慢性黏液脓血便、弥漫黏膜病变；IBD 是癌变高危，狭窄处多点活检。"},{"name":"肠结核/憩室炎","point":"肠结核多位于回盲部、有干酪样肉芽肿；憩室炎 CT 见憩室与渗出，抗感染后改善。"}],"tx":{"drug":[{"name":"FOLFOX（奥沙利铂+亚叶酸钙+5-FU）","dose":"奥沙利铂 85 mg/m²+亚叶酸钙 400 mg/m²+5-FU 400 mg/m² 静推后 2400 mg/m² 输注 46 h，q2w；按 CSCO/NCCN 指南与体表面积调整","note":"辅助疗程受神经毒性限制，持续感觉异常减量或停用","renal":"CrCl <30 慎用","hepatic":"肝功能不全减量","interact":"5-FU 与华法林显著增强抗凝"},{"name":"FOLFIRI（伊立替康+氟尿嘧啶类）","dose":"伊立替康 180 mg/m² d1+亚叶酸钙/5-FU 同 FOLFOX，q2w；按说明书","note":"迟发性腹泻（用药 5–7 天）备洛哌丁胺","renal":"肾功能不全减量","hepatic":"胆红素升高者减量","interact":"UGT1A1 *28 纯合者毒性增加"},{"name":"贝伐珠单抗","dose":"5 mg/kg q2w 或 7.5 mg/kg q3w 联合化疗至进展；遵说明书","note":"高血压、蛋白尿、出血、血栓；术后 4–6 周内慎用","renal":"重度肾损慎用","hepatic":"轻中度无需调整","interact":"与抗凝/抗血小板合用增加出血"},{"name":"西妥昔单抗（RAS 野生型）","dose":"首剂 400 mg/m² 后 250 mg/m² 每周一次，或 500 mg/m² q2w；RAS 野生型；按说明书","note":"须确认 RAS 与 BRAF 野生型；皮疹为主，预防性保湿防晒","renal":"无需调整","hepatic":"轻中度无需调整","interact":"与伊立替康联合增加腹泻"},{"name":"FOLFOXIRI（三药强化）","dose":"5-FU/亚叶酸钙+奥沙利铂+伊立替康；体能好、可转化切除者；按说明书","note":"骨髓抑制与腹泻明显，需 G-CSF，严格筛选 PS 0–1","renal":"肾功能不全慎用","hepatic":"肝功能不全减量","interact":"联合贝伐珠单抗可提高转化切除率"},{"name":"帕博利珠单抗/纳武利尤单抗（MSI-H/dMMR）","dose":"帕博利珠单抗 200 mg q3w 或 400 mg q6w；纳武利尤单抗 240 mg q2w 或 360 mg q3w；MSI-H 晚期；按指南执行","note":"仅 MSI-H/dMMR 推荐单药免疫；MSS 不常规使用","renal":"无需调整","hepatic":"轻中度无需调整","interact":"避免大剂量激素同时使用"}],"nonDrug":["结肠癌：根治性切除+区域淋巴结清扫，可腹腔镜或机器人","直肠癌：按 MRI 选择全直肠系膜切除（TME），低位评估保肛","早期 T1N0 内镜切除后免手术，需病理低危","局部进展期直肠癌：长程放化疗或短程放疗后手术，或全程新辅助","肝/肺寡转移：切除、消融，转化治疗后再评估；梗阻行支架或造口"],"life":["戒烟限酒，少红肉加工肉，增纤维与运动","50 岁以上（或 40 岁起有家族史）结肠镜筛查","术后 CEA 每 3–6 个月，CT 每年 1 次，术后 1 年结肠镜","造口患者规范造口护理"]},"prog":"Ⅰ期 5 年生存 >90%，Ⅱ期约 80%，Ⅲ期 60%–70%，Ⅳ期 15%–20%（可切除肝转移 40%–50%）。","refs":["CSCO 结直肠癌诊疗指南（2024）","中国结直肠癌筛查与早诊早治指南（2020，北京）","NCCN Colon/Rectal Cancer（2024）"]},{"id":"on_hcc","name":"肝细胞癌","aka":["HCC","原发性肝癌","肝癌"],"rank":3,"basic":{"define":"起源于肝细胞的恶性肿瘤，约占原发性肝癌 85%–90%，多发生于 HBV/HCV 相关肝硬化背景；治疗须同时考虑 BCLC 分期与 Child-Pugh 肝功能。","risk":["慢性 HBV 或 HCV 感染（我国以 HBV 为主）","酒精性肝病与脂肪性肝病","肝硬化（任何病因）","黄曲霉毒素与饮水污染","男性、>40 岁、肝硬化家族史","糖尿病与肥胖"],"epi":"我国年新发约 38 万，居发病第 4–5、死亡第 2 位；5 年生存 12%–15%，早期手术/消融可达 60%–70%。"},"patho":"慢性炎症—纤维化—肝硬化—异型增生结节—HCC 多步癌变，常伴 TERT、CTNNB1、TP53 改变；HCC 富血供，影像「快进快出」，易侵犯门静脉形成癌栓并血行转移至肺、骨。","dx":{"criteria":["肝硬化或慢性肝炎背景下，动态增强 CT/MRI「快进快出」可临床诊断，无需活检","影像不典型或结节 <1 cm 需活检或 3–4 个月复查","AFP ≥400 μg/L 持续 4 周或 ≥200 μg/L 持续 8 周且影像支持可辅助诊断，不可单独诊断","BCLC：0 单个 <2 cm；A 单个或 ≤3 个且均 ≤3 cm；B 多结节；C 门脉侵犯/肝外转移，PS 1–2；D Child-Pugh C 或 PS >2"],"workup":["动态增强 CT 或 MRI（EOB-MRI 用于小结节）","AFP、PIVKA-II、肝功能、HBV/HCV 与 HBV-DNA","白蛋白、胆红素、INR、血小板计算 Child-Pugh","胸部 CT 与骨扫描；胃镜筛查静脉曲张","ICG R15 评估肝储备"],"grading":"BCLC 0–D 期；CNLC Ⅰa–Ⅳ 期；Child-Pugh A/B/C 级；Milan 标准（单个 ≤5 cm 或 ≤3 个且均 ≤3 cm，无血管侵犯与肝外转移）。"},"ddx":[{"name":"胃癌（on_gastric）","point":"与本类 on_gastric 的鉴别点：HCC 在肝病背景下「快进快出」、AFP/PIVKA-II 升高；胃癌肝转移多发、不典型强化，有胃部原发灶与 CEA/CA19-9 升高。"},{"name":"结直肠癌（on_crc）","point":"与本类 on_crc 的鉴别点：结直肠癌肝转移呈「牛眼征」、CEA 升高，结肠镜见原发灶；HCC 多有肝硬化与门脉癌栓。"},{"name":"肝血管瘤","point":"边缘结节状强化向中心填充（「早出晚归」），AFP 正常，随访稳定。"},{"name":"肝内胆管细胞癌","point":"CA19-9 升高，延迟渐进性强化伴胆管扩张；确诊靠活检。"},{"name":"肝脓肿/其他肝转移瘤","point":"肝脓肿发热、液化坏死环形强化，抗感染引流有效；转移瘤需活检与免疫组化寻原发灶。"}],"tx":{"drug":[{"name":"仑伐替尼","dose":"体重 ≥60 kg 12 mg qd，<60 kg 8 mg qd；Child-Pugh A、PS 0–2 一线，可联合 PD-1；按指南执行","note":"高血压、蛋白尿、腹泻、甲减；每月监测血压与尿蛋白","renal":"重度肾损慎用","hepatic":"仅限 Child-Pugh A；B/C 不推荐","interact":"CYP3A4 诱导剂降低疗效"},{"name":"索拉非尼","dose":"400 mg bid 口服；晚期一线或不能耐受仑伐替尼时；按指南执行","note":"空腹或低脂饮食服用；手足皮肤反应常见","renal":"重度肾损慎用","hepatic":"Child-Pugh B 减量；C 不推荐","interact":"与华法林相互作用"},{"name":"阿替利珠单抗+贝伐珠单抗（T+A）","dose":"阿替利珠单抗 1200 mg+贝伐珠单抗 15 mg/kg q3w；Child-Pugh A、PS 0–2、无高出血风险者一线；按指南执行","note":"延长总生存；治疗前 6 个月内胃镜筛查静脉曲张","renal":"贝伐珠单抗重度肾损慎用","hepatic":"仅限 Child-Pugh A","interact":"贝伐珠单抗增加出血，避免与抗凝叠加"},{"name":"信迪利单抗+贝伐珠单抗类似物","dose":"信迪利单抗 200 mg q3w+贝伐珠单抗类似物 15 mg/kg q3w；晚期一线；按指南执行","note":"同为免疫+抗 VEGF，评估出血风险","renal":"轻中度无需调整","hepatic":"仅限 Child-Pugh A","interact":"与抗凝叠加出血风险"},{"name":"瑞戈非尼","dose":"160 mg qd 服 3 周停 1 周；索拉非尼失败后二线；按指南执行","note":"手足皮肤反应、乏力、腹泻；起始可减至 120 mg","renal":"重度肾损慎用","hepatic":"Child-Pugh B–C 不推荐","interact":"与华法林增强抗凝"}],"nonDrug":["BCLC 0/A：肝切除、射频/微波消融、肝移植（Milan/UCSF 标准）","BCLC B：TACE 或 TACE 联合靶向/免疫","BCLC C：系统治疗；门脉癌栓或寡转移可转化后评估手术","BCLC D：最佳支持治疗（止痛、营养、腹水与肝性脑病）","HBV 相关 HCC 全程抗病毒；HCV 用 DAA 治疗"],"life":["严格戒酒；肝硬化者每 6 个月超声+AFP 筛查","HBV 感染者长期抗病毒","避免肝毒性药物与含马兜铃酸草药","术后每 3 个月复查增强 CT/MRI 与 AFP"]},"prog":"BCLC 0/A 根治后 5 年生存 60%–70%，年复发率 10%–15%；BCLC B 中位生存 20–26 个月；BCLC C 系统治疗约 18–22 个月。","refs":["原发性肝癌诊疗指南（2024 年版，国家卫健委）","CSCO 原发性肝癌诊疗指南（2024）","中国肝癌分期方案（CNLC 2022）"]}]},{"id":"onco_emerg","name":"肿瘤急症与支持","rank":3,"summary":"肿瘤急症处置决定短期预后：肿瘤溶解综合征以高钾/高磷/高尿酸/低钙为核心，上腔静脉综合征以气道通畅与快速减压为先，癌痛以 WHO 三阶与规范化吗啡滴定实现可控镇痛。","compare":[{"diseaseId":"on_tls","dx":"治疗启动 12–72 h 内高钾、高磷、高尿酸、低钙中 ≥2 项异常，伴/不伴肾损伤、心律失常或抽搐","key":"多见于 Burkitt 淋巴瘤与急性白血病化疗后，尿量与肾功能是关键"},{"diseaseId":"on_svc","dx":"面颈与上肢水肿、颈胸部静脉扩张、端坐呼吸，胸部增强 CT 见上腔静脉受压或血栓","key":"气道与颅压优先，CT 明确原因，按病理与血栓机制分流"},{"diseaseId":"on_pain","dx":"肿瘤病史伴持续疼痛（NRS 1–3 轻、4–6 中、7–10 重），性质与部位与病灶相符","key":"WHO 三阶给药并按需滴定，而非按病情直接给高剂量"}],"diseases":[{"id":"on_tls","name":"肿瘤溶解综合征","aka":["TLS","Tumor Lysis Syndrome","急性肿瘤溶解综合征"],"rank":1,"basic":{"define":"大量肿瘤细胞快速破坏致钾、磷与尿酸大量释放，引起高钾、高磷、高尿酸与继发低钙血症，可并发急性肾损伤、心律失常与多脏器衰竭。","risk":["Burkitt 淋巴瘤、急性淋巴细胞/髓系白血病","化疗前高 WBC、瘤块 >10 cm、LDH 显著升高","治疗高度敏感的淋巴瘤或生殖细胞肿瘤首次化疗后","既往肾功能不全、脱水或尿酸盐肾病","大剂量激素、小分子靶向或双特异性抗体启动"],"epi":"Burkitt 淋巴瘤化疗后可达 20%–30%；所有高增殖血液肿瘤启动治疗者须风险分层预防并监测 ≥72 h。"},"patho":"治疗后肿瘤细胞大量凋亡坏死，钾、磷与核酸释放；嘌呤氧化为尿酸在肾小管结晶形成尿酸盐肾病；高磷与钙沉积进一步伤肾；低钙由高磷结合所致，可引起神经肌肉兴奋与心律失常。","dx":{"criteria":["实验室 TLS：化疗前 3 天至化疗后 7 天 ≥2 项：钾 ≥6.0 mmol/L；磷 ≥1.45 mmol/L；尿酸 ≥476 μmol/L；校正钙 ≤1.75 mmol/L","临床 TLS：实验室 TLS+≥1 项：肌酐 ≥1.5 倍上限、少尿（24 h <400 mL 或 0.5 mL/kg/h 持续 6 h）、心律失常/猝死、抽搐","高危者治疗前及第 4、8、12、24、48、72 h 监测","风险分层：低危（血细胞正常、LDH 不高）、中危（WBC ≥25×10⁹/L 或 LDH ≥2 倍上限）、高危（Burkitt/ALL、巨大瘤块、肾功能不全）","心电监测高钾 T 波高尖与低钙 QT 延长"],"workup":["钾、磷、尿酸、钙（含校正钙）、肌酐、尿素氮，每 4–8 h 复查","尿量与尿 pH 小时计；心电图评估心律失常","肾脏超声排除梗阻","高危者化疗前 LDH 与肿瘤负荷影像"],"grading":"Cairo-Bishop 实验性与临床性 TLS；风险分层低/中/高危。"},"ddx":[{"name":"上腔静脉综合征（on_svc）","point":"与本类 on_svc 的鉴别点：TLS 以电解质与肾功能紊乱为核心，无面颈肿胀与颈静脉怒张；SVC 以头颈上肢水肿、静脉怒张与呼吸窘迫为主。二者可并存，需分别监测。"},{"name":"癌性疼痛（on_pain）","point":"与本类 on_pain 的鉴别点：TLS 的腹痛/肾绞痛伴高钾、高磷与肌酐升高；癌痛以 NRS 与阿片反应评估，须先排除器官损伤。"},{"name":"肾前性肾损伤","point":"尿钠低、补液后肌酐迅速下降；TLS 相关 AKI 伴高尿酸、高钾与高磷。"},{"name":"梗阻性肾病","point":"超声见肾积水，解除后恢复；TLS 为肾实质/结晶型损伤。"},{"name":"肾上腺危象","point":"低钠、高钾、低血压伴皮质醇低；TLS 高钾常伴高磷/高尿酸而无低钠休克。"}],"tx":{"drug":[{"name":"别嘌醇","dose":"低/中危预防 300 mg/d，肾功不全起始 100 mg/d，化疗前 1–2 天开始；按说明书与肾功能调整","note":"仅阻断新生成尿酸；汉族 HLA-B*5801 阳性者严重药疹风险高","renal":"按 CrCl 调整；CrCl <15 或透析遵说明书","hepatic":"重度肝损减量","interact":"与硫唑嘌呤/6-MP 合用须减量"},{"name":"拉布立酶","dose":"0.2 mg/kg 静滴 qd 持续 3–7 天，用于高危或临床 TLS；国内可及性有限，按说明书执行","note":"快速分解尿酸；G6PD 缺乏者禁用；可致尿酸假性低值","renal":"无需调整","hepatic":"轻中度无需调整","interact":"不可与其他药物同管输注"},{"name":"非布司他","dose":"40 mg qd 起始，必要时增量；别嘌醇不耐受或需长期降尿酸时替代；遵说明书","note":"起效慢，不适用于急性降尿酸","renal":"轻中度无需调整，重度遵说明书","hepatic":"重度肝损慎用","interact":"与硫唑嘌呤/6-MP 须大幅减量"},{"name":"水化（生理盐水）","dose":"化疗前 24–48 h 开始，生理盐水 2.5–3 L/m²/d 或维持尿量 80–100 mL/m²/h；按说明书","note":"预防核心；避免含钾液体；少尿者收容监护","renal":"少尿性 AKI 减量并监测肺水肿","hepatic":"肝硬化腹水者限制钠水","interact":"注意配伍禁忌"},{"name":"降钾（葡萄糖酸钙±胰岛素+葡萄糖+β2 激动剂）","dose":"血钾 ≥6.5 mmol/L 或心电图改变：10% 葡萄糖酸钙 10–20 mL 缓推，随后胰岛素加葡萄糖、沙丁胺醇雾化；遵急救指南","note":"持续心电监测；排钾与利尿或透析衔接","renal":"少尿者优先透析","hepatic":"警惕低血糖","interact":"停用 ACEI/ARB、保钾利尿剂"}],"nonDrug":["高危者化疗前预防性水化与降尿酸，逐日监测电解质","少尿或利尿无反应、持续高钾者血液透析","肿瘤负荷极高者暂缓或减量化疗","低钙仅在抽搐或心律失常时补钙"],"life":["记录出入量与体重，尿量 <0.5 mL/kg/h 连续 2 h 报告","化疗后 72 h 内继续监测电解质"]},"prog":"及时预防者死亡率 <10%；临床 TLS 伴少尿或多器官受累者 30%–50%。","refs":["中国肿瘤溶解综合征诊疗专家共识（2022）","NCCN Tumor Lysis Syndrome（2024）"]},{"id":"on_svc","name":"上腔静脉综合征","aka":["SVCS","Superior Vena Cava Syndrome","上腔静脉压迫综合征"],"rank":2,"basic":{"define":"上腔静脉受肿瘤压迫或血栓阻塞，导致头颈与上肢静脉回流受阻及侧支开放，表现为面颈水肿、颈胸部静脉扩张与呼吸困难。","risk":["纵隔肿块：小细胞/非小细胞肺癌、淋巴瘤","纵隔淋巴结转移或巨大纵隔肿块","中心静脉导管/起搏器相关血栓（良性占 20%–40%）","纵隔纤维化、甲状腺肿、主动脉瘤","放疗后纤维化"],"epi":"恶性 SVC 中肺癌占 60%–70%、淋巴瘤 10%–20%；随中心静脉置管增多，血栓性原因上升。"},"patho":"SVC 壁薄、压力低，易被纵隔肿块外压，狭窄 >60%–80% 或合并血栓时头颈与上肢回流受阻，经奇静脉、内乳与胸壁静脉建立侧支；静脉压升高可致脑水肿与喉水肿、气道狭窄。","dx":{"criteria":["面颈与上肢肿胀、颈静脉怒张、胸壁静脉侧支扩张、端坐呼吸、声嘶","胸部增强 CT 为确诊首选，明确压迫/血栓与纵隔肿块","压迫程度分轻 <50%、中 50%–80%、重 >80%","须尽量取得病理后才行靶向/化疗","意识改变、喘鸣或吸气性喉鸣提示气道与颅内高压，属急症"],"workup":["胸部增强 CT 优先于平片，评估气道受压与血栓","纵隔穿刺/EBUS-TBNA 或胸水细胞学取病理","纤维支气管镜评估气道狭窄","头颅 CT/MRI；血管超声评估导管相关血栓"],"grading":"按狭窄程度轻/中/重度；功能上分无症状、有症状可自理、需急诊（端坐呼吸/脑症状/气道狭窄）。"},"ddx":[{"name":"肿瘤溶解综合征（on_tls）","point":"与本类 on_tls 的鉴别点：SVC 以头颈上肢水肿、静脉怒张与端坐呼吸为主，电解质正常；TLS 以高钾、高磷、高尿酸与肾损伤为核心。"},{"name":"癌性疼痛（on_pain）","point":"与本类 on_pain 的鉴别点：SVC 的胸骨后压迫伴体位性水肿与静脉怒张；癌痛需镇痛处方与滴定，无静脉回流受阻。"},{"name":"心包填塞","point":"端坐呼吸与颈静脉怒张伴奇脉、低血压，超声见心包积液与右室塌陷。"},{"name":"纵隔纤维化","point":"病程长、无肿瘤肿块，CT 见纤维化与钙化。"},{"name":"胸骨后甲状腺肿","point":"颈前肿块随吞咽移动，超声与穿刺确诊。"}],"tx":{"drug":[{"name":"地塞米松","dose":"激素敏感肿瘤（淋巴瘤、胸腺瘤等）所致 SVC 常用 10–20 mg 静推或静滴，后续按病理与方案确定；遵说明书","note":"缓解肿瘤周水肿与颅压；未取病理前大剂量激素可掩盖诊断","renal":"无需调整","hepatic":"肝功能不全需调整","interact":"与 NSAIDs 合用增加消化道出血"},{"name":"呋塞米（利尿）","dose":"水肿或脑水肿明显者 20–40 mg 静脉推注；按尿量、电解质与说明书滴定","note":"仅对症减容量，须在有效循环血量充足时使用","renal":"肾功不全增量并监测；严重低钾/低钠慎用","hepatic":"肝硬化者警惕肝性脑病","interact":"与氨基糖苷类叠加耳肾毒"},{"name":"低分子肝素（血栓性 SVC）","dose":"依诺肝素 1 mg/kg 皮下 q12h 或等效剂量；确诊血栓或导管相关时使用，按 CrCl 与说明书调整","note":"平衡出血风险；肿瘤合并血栓者长期抗凝 ≥3–6 个月","renal":"CrCl <30 减量或改普通肝素","hepatic":"肝硬化/血小板低者评估出血","interact":"与抗血小板药合用增加出血"},{"name":"病理导向化疗/靶向","dose":"按原发肿瘤标准方案（SCLC 的 EP、淋巴瘤 R-CHOP、EGFR 突变 NSCLC 奥希替尼等），按指南与体表面积调整","note":"敏感肿瘤 1–2 周内显著减轻压迫；避免未确诊盲目治疗","renal":"按具体药物调整","hepatic":"按具体药物调整","interact":"按具体方案评估"}],"nonDrug":["半坐位、吸氧；喉水肿或气道狭窄备插管与气道支架","血管内覆膜支架数小时缓解症状，适用于化疗不敏感或需快速减压","局部放疗起效需 1–2 周，适用于放疗敏感肿瘤","急性致命性血栓性 SVC 可溶栓（评估出血）","脑水肿：抬高床头、激素、限液，必要时高渗治疗"],"life":["避免上肢与右侧中心静脉穿刺，必要时改股静脉","睡眠抬高头位，避免长时间低头","抗凝期间观察出血，复查 CT 评估支架通畅"]},"prog":"取决于原发肿瘤：小细胞肺癌与淋巴瘤多可迅速缓解；气道受累、脑水肿、顽固血栓与治疗抵抗预后差。","refs":["中国上腔静脉综合征诊断与治疗专家共识（2021）","NCCN Lymphoma/Small Cell Lung Cancer（2024）"]},{"id":"on_pain","name":"癌性疼痛（癌痛规范化治疗）","aka":["癌痛","Cancer Pain","肿瘤疼痛规范化诊疗"],"rank":3,"basic":{"define":"肿瘤或其治疗直接引起的疼痛，按机制分为伤害性（内脏/躯体）、神经病理性与混合性；规范治疗依据 WHO 三阶、按需致效与阿片滴定。","risk":["晚期实体瘤（骨转移、胰腺癌、腹膜后肿瘤）","肿瘤侵犯神经或神经丛","骨转移与病理性骨折","化疗所致周围神经病变（CIPN）与放疗后神经痛","既往慢性痛或合并焦虑抑郁"],"epi":"我国约 50%–70% 肿瘤患者经历疼痛，其中 30%–50% 为中重度；规范三阶治疗可使 70%–90% 获有效控制。"},"patho":"肿瘤侵犯骨、软组织与内脏引起伤害性疼痛（骨膜牵张、包膜牵拉、空腔脏器痉挛）；侵犯神经或化疗导致神经病理性疼痛（灼痛、电击样、异常性疼痛）；持续疼痛引起外周与中枢敏化，叠加情绪与睡眠障碍形成恶性循环。","dx":{"criteria":["NRS 0–10：1–3 轻度、4–6 中度、7–10 重度；交流困难者用面部表情量表","评估含部位、性质、诱因、持续时间、对睡眠与活动影响及既往用药","区分机制（伤害性/神经病理性/混合性）与病因，识别爆发痛","首次评估后 24 h 内复评，调整剂量期间至少每 4 h 或按需评估","区分阿片耐受与阿片诱导痛觉过敏（增量反加重）","同时筛查焦虑、抑郁与失眠"],"workup":["疼痛评估单：部位、性质、NRS、爆发痛次数与诱因","相应部位影像：骨扫描/CT/MRI","神经病理性疼痛筛查（DN4）；肝肾功能与电解质","便秘、恶心、嗜睡与呼吸抑制监测"],"grading":"WHO 三阶：一阶 NSAIDs/对乙酰氨基酚±辅助；二阶弱阿片（曲马多、可待因）+非阿片±辅助；三阶强阿片（吗啡、羟考酮、芬太尼）+非阿片±辅助。"},"ddx":[{"name":"上腔静脉综合征（on_svc）","point":"与本类 on_svc 的鉴别点：SVC 的胸痛与头面胀痛伴颈静脉怒张、面颈水肿与端坐呼吸；癌痛按 WHO 三阶滴定，无血管受压体征。"},{"name":"肿瘤溶解综合征（on_tls）","point":"与本类 on_tls 的鉴别点：TLS 的腹痛或肾绞痛伴高钾、少尿与肌酐升高；癌痛以 NRS 与镇痛反应评估，无电解质紊乱。"},{"name":"病理性骨折","point":"突发剧痛伴畸形与活动受限，影像见骨折线，需骨科处理。"},{"name":"CIPN/放疗后神经痛","point":"灼痛、电击样、麻木，DN4 ≥4；主药为普瑞巴林/加巴喷丁，阿片为辅。"},{"name":"非肿瘤性慢性痛","point":"与活动/静息关系明显、无对应病灶；骨质疏松者需维生素 D/钙与抗骨破坏治疗。"}],"tx":{"drug":[{"name":"对乙酰氨基酚（第一阶）","dose":"每次 0.5 g，每 4–6 h 可重复，日剂量不超过 2 g（肝病者更严）；遵说明书","note":"第一阶起点；不长期大剂量，注意肝毒","renal":"严重肾损慎用","hepatic":"肝硬化减量或避免","interact":"长期与华法林合用升高 INR；避免复方叠加"},{"name":"NSAIDs（布洛芬/塞来昔布等）","dose":"按说明书剂量（如塞来昔布 200 mg qd–bid），评估消化道、肾与心血管风险后短期使用","note":"骨转移疼痛有效；溃疡、肾功不全或抗凝者慎用，联合 PPI","renal":"eGFR <30 避免使用","hepatic":"肝硬化避免","interact":"与抗凝/抗血小板增加出血；与 ACEI/ARB/利尿剂增加肾损伤"},{"name":"曲马多（第二阶）","dose":"50–100 mg 起，每 6–8 h 一次，日剂量按说明书上限（通常 ≤400 mg/d）","note":"癫痫史与使用曲坦类者慎用","renal":"CrCl <30 减量并延长间隔","hepatic":"肝功能不全减量","interact":"与 SSRIs/SNRIs/MAOIs 合用 5-HT 综合征风险"},{"name":"吗啡（第三阶，即释/缓释）","dose":"即释起始 5–15 mg q4h，NRS ≥7 者可 10–20 mg；随后按 24 h 总量换算缓释制剂；等效换算与滴定按指南与说明书","note":"顺序为评估—给药—再评估；缓释剂不作滴定初始；便秘需预防性通便","renal":"CrCl <30 减量或延长间隔（M6G 蓄积），可改芬太尼透皮","hepatic":"重度肝损减量并延长间隔","interact":"与苯二氮䓬/镇静药合用增加呼吸抑制；禁与 MAOI 合用"},{"name":"羟考酮（第三阶）","dose":"即释 5–10 mg q4–6h；缓释 10 mg q12h 起始（未用阿片者），按 24 h 总量滴定；遵说明书","note":"兼具内脏镇痛；缓释片不得掰碎碾碎","renal":"轻中度无需调整，重度减量","hepatic":"重度肝损减量并延长间隔","interact":"CYP3A4 抑制剂显著升浓度；与苯二氮䓬类抑制呼吸"},{"name":"芬太尼透皮贴（第三阶）","dose":"口服困难或稳定慢性疼痛，按 24 h 吗啡等效剂量换算，一般自 25 μg/h 起，每 72 h 更换；遵说明书","note":"起效需 12–24 h；发热或热源可加速吸收致过量","renal":"无需调整","hepatic":"重度肝损慎用","interact":"CYP3A4 抑制剂升高浓度；禁与 MAOI 合用"},{"name":"普瑞巴林（神经病理性辅助）","dose":"75 mg bid 起始，按耐受增量（常用 150–300 mg/d，最大 600 mg/d）；按肾功能与说明书调整","note":"用于骨转移神经压迫与 CIPN；需缓慢减停","renal":"按 CrCl 减量并延长间隔","hepatic":"无需调整","interact":"与阿片/镇静药合用增加中枢与呼吸抑制"},{"name":"唑来膦酸/地舒单抗（骨转移）","dose":"唑来膦酸 4 mg 静滴 q3–4w（肾功不全减量或延迟）或地舒单抗 120 mg 皮下 q4w；遵说明书","note":"补充钙与维生素 D；警惕低钙与颌骨坏死（治疗前口腔检查）","renal":"唑来膦酸 eGFR <30 不推荐；地舒单抗重度肾损慎用","hepatic":"无需调整","interact":"与 NSAIDs 合用增加肾损伤"}],"nonDrug":["骨转移局部放疗（8 Gy 单次或 20–30 Gy 分次）明显缓解骨痛","神经阻滞/腹腔神经丛毁损用于胰腺癌、腹膜后内脏痛","椎体成形术用于椎体转移骨痛","爆发痛在缓释方案上按需即释阿片（约日总量 10%–15%）","多学科疼痛管理；PCA 泵用于难治性重度疼痛或快速滴定"],"life":["疼痛日记：每日 NRS、爆发痛次数与用药","阿片启动即用缓泻剂预防便秘","缓释片整片吞服，贴剂贴无毛干燥皮肤并远离热源","家中备纳洛酮，家属识别呼吸抑制（嗜睡、呼吸 <8 次/分、针尖样瞳孔）","不自行停药或加量，每 1–2 周复诊评估"]},"prog":"规范三阶治疗后 70%–90% 的癌痛可有效控制；镇痛不足与心理共病、爆发痛频繁及剂量不足相关。","refs":["癌症疼痛诊疗规范（2018 年版，国家卫健委）","中国癌症疼痛诊疗指南（2023）","NCCN Adult Cancer Pain（2024）"]}]},{"id":"solid_other","name":"其他常见实体瘤","rank":4,"summary":"乳腺癌、前列腺癌、卵巢癌以分子分型或标志物驱动内分泌/靶向治疗，胰腺癌与宫颈癌以可切除性评估和放化疗安排为核心；化疗方案按 CSCO/NCCN 与体表面积调整。","compare":[{"diseaseId":"on_breast_ca","dx":"乳腺肿块超声+钼靶 BI-RADS 评估，空芯针活检病理+ER/PR/HER2/Ki-67 分型","key":"以 ER/PR/HER2 分型决定内分泌、抗 HER2 或化疗"},{"diseaseId":"on_pancreatic","dx":"梗阻性黄疸或消瘦，增强 CT 三联期见低密度占位，CA19-9 升高，EUS-FNA 取病理","key":"CA19-9 不用于诊断，关键在可切除性血管评估"},{"diseaseId":"on_prostate","dx":"PSA 升高或排尿症状，前列腺穿刺 Gleason 评分/ISUP 分级组","key":"PSA 筛查+穿刺分级，ADT 为转移性治疗基石"},{"diseaseId":"on_ovarian","dx":"腹胀腹水、盆腔包块，CA125 升高，手术病理证实，FIGO 分期","key":"CA125+腹水细胞学，BRCA 决定 PARP 维持"},{"diseaseId":"on_cervical","dx":"接触性出血，HPV 检测阳性，宫颈活检+FIGO 分期","key":"与 HPV 强相关，局部晚期行同步放化疗"}],"diseases":[{"id":"on_breast_ca","name":"乳腺癌","aka":["Breast Cancer","乳腺恶性肿瘤","Luminal 型乳腺癌","三阴性乳腺癌","HER2 阳性乳腺癌"],"rank":1,"basic":{"define":"起源于乳腺导管或小叶上皮的恶性肿瘤，以分子分型（Luminal A/B、HER2 阳性、三阴性）决定全身治疗模式。","risk":["女性、年龄 >40 岁","BRCA1/2、PALB2 等胚系突变","一级亲属乳腺癌/卵巢癌家族史","初潮早、未育或晚育、未哺乳","绝经后肥胖或长期雌激素暴露","胸部放疗史"],"epi":"我国女性发病首位，年新发约 35 万例；发病年龄较欧美提前约 10 年，45–55 岁为高峰。"},"patho":"导管上皮在雌激素受体、HER2 信号与 BRCA 同源重组缺陷驱动下增殖，突破基底膜后浸润。ER 阳性者依赖雌激素通路；HER2 扩增激活 PI3K/MAPK 促增殖；三阴性者侵袭性强。易经淋巴至腋窝淋巴结、血行至骨肝肺脑。","dx":{"criteria":["空芯针穿刺活检病理确诊为浸润性癌（金标准），细针穿刺仅用于淋巴结","分子分型：ER/PR ≥1% 为阳性；HER2 IHC 3+ 或 2+ 且 FISH 扩增为阳性；Ki-67 <20% 多归 Luminal A","Luminal 样：激素受体阳性、HER2 阴性；HER2 阳性：无论激素受体；三阴性：三者均阴性","TNM 第 8 版结合解剖与生物学分期；临床为 cTNM，术后为 pTNM","腋窝淋巴结临床阴性者可行前哨淋巴结活检"],"workup":["双乳超声+钼靶（致密腺体加 MRI），BI-RADS 分级","胸腹增强 CT、骨扫描或 PET/CT：Ⅲ期及以上或有转移症状","血常规、肝肾功能、CEA/CA15-3 基线","年轻或三阴性/有家族史者行 BRCA1/2 胚系检测","心脏超声：拟用蒽环类或抗 HER2 治疗前"],"grading":"组织学分级诺丁汉（Elston-Ellis）Ⅰ–Ⅲ级；分子分型 Luminal A、Luminal B（HER2 阴性/阳性）、HER2 阳性（非 Luminal）、三阴性；临床分期 0–Ⅳ 期。"},"ddx":[{"name":"卵巢癌（on_ovarian）","point":"与本类 on_ovarian 的鉴别点：卵巢癌以腹胀、腹水、CA125 显著升高为主；乳腺原发灶术后出现远处病灶时需免疫组化（GATA3、PAX8）判定来源。"},{"name":"胰腺癌（on_pancreatic）","point":"与本类 on_pancreatic 的鉴别点：胰腺癌多为梗阻性黄疸、CA19-9 升高；乳腺癌肝转移可无黄疸，靠影像与病理。"},{"name":"纤维腺瘤","point":"青年女性、边界清、活动度好、BI-RADS 3 类，随访或穿刺排除。"},{"name":"乳腺增生/囊性病变","point":"与月经周期相关胀痛、多发囊性结节，影像 BI-RADS 2 类。"},{"name":"浆细胞性乳腺炎","point":"非哺乳期乳头溢液、红肿窦道，抗炎后穿刺活检排除癌。"}],"tx":{"drug":[{"name":"他莫昔芬","dose":"20 mg qd 口服，绝经前 Luminal 型辅助内分泌 5–10 年；按 CSCO 指南与复发风险调整","note":"子宫内膜增厚、血栓、潮热；每 6–12 个月妇科超声","renal":"遵说明书","hepatic":"重度肝损慎用","interact":"帕罗西汀、氟西汀等强效 CYP2D6 抑制剂降低活性代谢物"},{"name":"芳香化酶抑制剂（来曲唑/阿那曲唑）","dose":"来曲唑 2.5 mg qd 或阿那曲唑 1 mg qd 口服；绝经后 Luminal 型辅助或晚期，5 年；按 CSCO 指南执行","note":"骨关节痛、骨质疏松、血脂异常；监测骨密度并补钙","renal":"重度肾损遵说明书","hepatic":"中度以上肝损减量","interact":"不与他莫昔芬同用"},{"name":"氟维司群","dose":"500 mg 肌注 d1、d15、d29 后每月 1 次；HR 阳性晚期内分泌治疗后进展","note":"注射部位反应；与他莫昔芬无交叉耐药","renal":"轻中度无需调整","hepatic":"重度慎用","interact":"无重大相互作用"},{"name":"CDK4/6 抑制剂（哌柏西利/阿贝西利）","dose":"哌柏西利 125 mg qd 服 21 天停 7 天，联合 AI 或氟维司群；HR 阳性 HER2 阴性晚期一线；按 CSCO 指南与血象调整","note":"中性粒细胞减少、腹泻（阿贝西利）；定期血常规","renal":"重度肾损减量","hepatic":"中重度肝损减量","interact":"强效 CYP3A4 抑制剂需减量"},{"name":"曲妥珠单抗+帕妥珠单抗（双靶）","dose":"曲妥珠单抗首剂 8 mg/kg 后 6 mg/kg q3w，帕妥珠单抗首剂 840 mg 后 420 mg q3w 静滴；HER2 阳性早期辅助或晚期一线，疗程 1 年或至进展；按 CSCO/NCCN 与体表面积调整","note":"须监测 LVEF，基线及每 3 个月；与蒽环类序贯使用","renal":"无需调整","hepatic":"无需调整","interact":"避免与蒽环类同时使用"},{"name":"恩美曲妥珠单抗/德曲妥珠单抗","dose":"T-DM1 3.6 mg/kg q3w；T-DXd 5.4 mg/kg q3w 静滴；HER2 阳性新辅助未 pCR 或晚期二线；按 CSCO 指南执行","note":"T-DXd 可致间质性肺病，需定期高分辨 CT","renal":"遵说明书","hepatic":"中重度肝损慎用","interact":"避免强效 CYP3A4 抑制剂（T-DXd）"},{"name":"蒽环/紫杉类化疗（AC-T、TC）","dose":"AC：多柔比星 60 mg/m²+环磷酰胺 600 mg/m² q3w×4 序贯多西他赛 100 mg/m²×4；TC：多西他赛 75 mg/m²+环磷酰胺 600 mg/m² q3w×4；按 CSCO 指南与体表面积调整","note":"蒽环类累积心脏毒性（终身 550 mg/m²）、骨髓抑制、脱发","renal":"环磷酰胺 CrCl <30 减量","hepatic":"多柔比星胆红素升高减量","interact":"避免与其他心脏毒性药物同用"},{"name":"铂类+紫杉（三阴性）","dose":"紫杉醇 80 mg/m² 周疗或白蛋白紫杉醇 125 mg/m² d1、d8+卡铂 AUC 5 q3w；BRCA 突变者可选铂类为主；按 CSCO/NCCN 与体表面积调整","note":"三阴性或 BRCA 突变者铂类疗效更佳；注意神经毒性","renal":"卡铂按 Calvert 公式依肾功能调整","hepatic":"紫杉醇肝损减量","interact":"紫杉醇经 CYP2C8/3A4 代谢"}],"nonDrug":["早期：保乳手术+前哨淋巴结活检；多中心病灶或肿瘤过大行全乳切除","放疗：保乳术后常规；全切后按腋窝阳性数、切缘等高危因素","新辅助：HER2 阳性或三阴性、肿瘤 >2 cm 或腋窝阳性者优先新辅助","重建：术后即刻或延期假体/自体皮瓣重建，需与放疗衔接","寡转移：全身治疗基础上可考虑手术或立体定向放疗"],"life":["控制体重、限酒、规律运动每周 ≥150 分钟","内分泌治疗期间每 1–2 年骨密度检测，酌情骨改良药物","每 3–6 个月随访 3 年，之后每 6–12 个月"]},"prog":"我国乳腺癌 5 年生存率约 83%，早期可超 90%；三阴性复发高峰在术后 1–3 年，HER2 阳性经双靶治疗预后显著改善。","refs":["CSCO 乳腺癌诊疗指南 2024","中国抗癌协会乳腺癌诊治指南与规范（2023 版）","NCCN Breast Cancer Guidelines Version 2024"]},{"id":"on_pancreatic","name":"胰腺癌","aka":["Pancreatic Cancer","胰腺导管腺癌","PDAC"],"rank":2,"basic":{"define":"起源于胰腺导管上皮的恶性肿瘤，95% 为导管腺癌；治疗由可切除性评估决定。","risk":["吸烟","慢性胰腺炎","新发糖尿病，尤其 <1 年、年龄 >50 岁","肥胖","BRCA2、CDKN2A、PALB2 等胚系突变","长期芳香胺类化学物暴露"],"epi":"我国发病率持续上升，5 年生存率约 8%–10%；起病隐匿，仅 15%–20% 初诊可切除。"},"patho":"KRAS 突变（>90%）联合 TP53、SMAD4、CDKN2A 改变，促结缔组织增生基质包裹肿瘤，形成缺氧低灌注微环境，导致化疗耐药与免疫排斥。早期侵犯胰周神经丛与血管，晚期血行转移至肝与腹膜。","dx":{"criteria":["组织或细胞学病理证实腺癌为金标准；影像典型而术前无病理者可直接手术","增强 CT 三联期（动脉期、胰腺期、门脉期）为主要诊断与分期影像","CA19-9 升高（<37 U/ml 为正常）支持诊断与监测；Lewis 抗原阴性者可不升高，胆道梗阻可假性升高","无痛性黄疸、体重下降、新发糖尿病为典型表现","可切除性：肿瘤未接触 SMA、腹腔干、肝总动脉，SMV/PV 无侵犯为可切除；接触 <180° 或可重建为交界可切除；包绕血管或远处转移为不可切除"],"workup":["胸腹盆腔增强 CT 三联期（首选）或 MRI/MRCP","EUS 及 FNA：需新辅助化疗或诊断存疑时","PET/CT：可疑远处转移或复发","CA19-9、CEA、胆红素、凝血与营养评估","可切除者行腹腔镜探查排除腹膜转移"],"grading":"按可切除性：可切除、交界可切除（BR-PDAC）、局部进展（LAPC）、转移性；组织学分级 1–3 级（AJCC 第 8 版）。"},"ddx":[{"name":"乳腺癌（on_breast_ca）","point":"与本类 on_breast_ca 的鉴别点：乳腺癌多见女性、以乳腺肿块首发；胰腺癌以黄疸、消瘦、CA19-9 升高为主，影像见胰管扩张。"},{"name":"卵巢癌（on_ovarian）","point":"与本类 on_ovarian 的鉴别点：卵巢癌以盆腔包块、腹水、CA125 升高为特征；胰腺癌腹水多为腹膜播散晚期，胰腺原发灶明确。"},{"name":"肿块型慢性胰腺炎","point":"长期酗酒史、胰管钙化串珠样改变，CA19-9 多正常；穿刺可助鉴别，假阴性常见。"},{"name":"胆总管结石/胆管癌","point":"结石为一过性黄疸伴胆绞痛；胆管癌以 CA19-9 升高、肝内胆管扩张为主。"},{"name":"胰腺神经内分泌肿瘤","point":"多富血供、生长慢，可伴低血糖或潮红，Ki-67 分级低。"}],"tx":{"drug":[{"name":"FOLFIRINOX","dose":"奥沙利铂 85 mg/m²+亚叶酸钙 400 mg/m²+伊立替康 180 mg/m² d1，5-FU 400 mg/m² 静推后 2400 mg/m² 持续 46 h，q2w；ECOG 0–1 者一线或新辅助；按 CSCO/NCCN 与体表面积调整","note":"骨髓抑制、腹泻、神经毒性；建议 G-CSF 一级预防，PS≥2 者用改良方案","renal":"CrCl <30 慎用奥沙利铂","hepatic":"胆红素 >1.5 倍减量","interact":"伊立替康与强效 CYP3A4 抑制剂合用需减量"},{"name":"吉西他滨+白蛋白紫杉醇（AG）","dose":"白蛋白紫杉醇 125 mg/m²+吉西他滨 1000 mg/m² 静滴 d1、d8、d15，q4w；按 CSCO 指南与体表面积调整","note":"骨髓抑制、周围神经毒性、乏力；d15 前评估血象","renal":"吉西他滨肾损慎用","hepatic":"肝转移/肝损者减量","interact":"与华法林合用增加出血"},{"name":"吉西他滨单药","dose":"1000 mg/m² 静滴 d1、d8、d15，q4w；体能状态差者；按说明书执行","note":"骨髓抑制、流感样症状","renal":"CrCl <30 减量或延后","hepatic":"重度肝损慎用","interact":"遵说明书"},{"name":"S-1（替吉奥）","dose":"按体表面积 40–60 mg bid 口服 d1–14，q3w；可联合吉西他滨；按说明书执行","note":"腹泻、手足综合征、骨髓抑制","renal":"CrCl <30 禁用","hepatic":"重度肝损减量","interact":"避免与其他氟尿嘧啶类合用；与华法林相互作用"},{"name":"奥拉帕利（BRCA 突变维持）","dose":"300 mg bid 口服；铂类敏感且 BRCA1/2 胚系突变者的维持治疗；按 CSCO 指南执行","note":"贫血、乏力；定期血常规","renal":"中重度肾损减量","hepatic":"重度肝损慎用","interact":"避免强效 CYP3A4 抑制剂/诱导剂"}],"nonDrug":["可切除：胰十二指肠切除或胰体尾切除+区域淋巴结清扫，R0 切缘为关键，术后辅助化疗 6 个月","交界可切除/局部进展：FOLFIRINOX 或 AG 新辅助 4–6 周期后再次评估手术","梗阻性黄疸：ERCP 支架减黄或经皮肝穿引流","胃出口梗阻：十二指肠支架或胃肠吻合","疼痛：腹腔神经丛阻滞联合规范阿片镇痛"],"life":["胰酶替代（脂肪泻者）、高蛋白高热量饮食","术后新发糖尿病需内分泌随访","每 2–3 个月复查 CA19-9 与腹部 CT"]},"prog":"总体 5 年生存率 <10%；R0 切除后中位生存 20–25 个月，转移性 6–11 个月；BRCA 突变者可获益于铂类与 PARP 维持。","refs":["CSCO 胰腺癌诊疗指南 2024","中国胰腺癌综合诊治指南（2022 版）","NCCN Pancreatic Adenocarcinoma Version 2024"]},{"id":"on_prostate","name":"前列腺癌","aka":["Prostate Cancer","前列腺腺癌","转移性前列腺癌","去势抵抗性前列腺癌","CRPC"],"rank":3,"basic":{"define":"起源于前列腺腺上皮的恶性肿瘤，以 PSA 筛查、Gleason 评分与 TNM 分期判断风险，治疗以内分泌治疗（ADT）为基石。","risk":["年龄 >50 岁，或 >45 岁且有家族史","一级亲属前列腺癌或 BRCA2 相关乳腺癌家族史","高脂饮食、肥胖","种系 BRCA2、HOXB13 突变"],"epi":"我国男性泌尿系统肿瘤发病首位，近年发病率明显上升，约 60% 初诊即为中晚期。"},"patho":"雄激素受体（AR）信号是生长核心驱动，初始对去势敏感；长期去势后经 AR 扩增/突变与 PI3K、Wnt 旁路激活转为去势抵抗。常见转移至骨（成骨性）与淋巴结，内脏转移提示预后差。","dx":{"criteria":["PSA >4 ng/ml 为穿刺指征之一；4–10 ng/ml 灰区结合 fPSA/tPSA 比值（<0.16 提示恶性）","MRI PI-RADS ≥3 且 PSA 升高者行靶向+系统穿刺（≥10–12 针）","Gleason 评分对应 ISUP 分级组：1 组 6 分、2 组 3+4=7、3 组 4+3=7、4 组 8 分、5 组 9–10 分","PSA >20 ng/ml 或高危者行骨扫描+盆腔 MRI 或 PSMA PET/CT","去势抵抗（CRPC）：睾酮 <50 ng/dl 且 PSA 持续升高或影像进展"],"workup":["复查 PSA 及游离/总 PSA，排除感染与操作干扰","多参数 MRI（T2、DWI、DCE）评估 PI-RADS","穿刺病理+ISUP 分级；高危者检测 BRCA、MSI/dMMR","骨扫描或 PSMA PET/CT；转移者查碱性磷酸酶、血钙","基线血常规、肝肾功能与睾酮"],"grading":"ISUP 分级组 1–5 组；D'Amico 危险分层：低危 PSA <10 且 GS ≤6 且 cT1–2a；中危 PSA 10–20 或 GS 7 或 cT2b；高危 PSA >20 或 GS ≥8 或 ≥cT2c。"},"ddx":[{"name":"乳腺癌（on_breast_ca）","point":"与本类 on_breast_ca 的鉴别点：乳腺癌多见于女性；男性出现骨转移病灶时，PSA、NKX3.1 阳性提示前列腺来源，需免疫组化明确。"},{"name":"胰腺癌（on_pancreatic）","point":"与本类 on_pancreatic 的鉴别点：胰腺癌以黄疸、CA19-9 升高为主；前列腺癌骨转移多以骨痛、ALP 升高首诊，PSA 显著升高可鉴别。"},{"name":"良性前列腺增生","point":"下尿路症状为主，fPSA/tPSA >0.16，MRI PI-RADS 低，穿刺阴性。"},{"name":"前列腺炎","point":"尿痛、会阴痛，PSA 一过性升高，抗感染后复查下降。"},{"name":"膀胱癌","point":"无痛性肉眼血尿为主，膀胱镜见占位，PSA 多正常。"}],"tx":{"drug":[{"name":"戈舍瑞林/亮丙瑞林（LHRH 激动剂）","dose":"戈舍瑞林 3.6 mg 皮下 q4w 或 10.8 mg q12w；亮丙瑞林 3.75 mg 肌注 q4w；按 CSCO 指南执行","note":"首剂可致睾酮一过性升高，骨转移高危者需桥接抗雄药；潮热、骨质疏松","renal":"无需调整","hepatic":"重度肝损慎用","interact":"遵说明书"},{"name":"地加瑞克（LHRH 拮抗剂）","dose":"首剂 240 mg 皮下，28 天后 80 mg q4w；无需抗雄桥接；遵说明书","note":"适合骨转移高危或脊髓压迫风险者快速降睾酮","renal":"轻中度无需调整","hepatic":"重度肝损慎用","interact":"遵说明书"},{"name":"阿比特龙+泼尼松","dose":"阿比特龙 1000 mg qd 空腹口服+泼尼松 5 mg bid；mHSPC 或 CRPC；按 CSCO 指南执行","note":"监测低钾、高血压、水肿；须联用激素","renal":"重度肾损慎用","hepatic":"重度肝损禁用","interact":"强效 CYP3A4 诱导剂降低浓度"},{"name":"恩扎卢胺","dose":"160 mg qd 口服；mHSPC、CRPC 或高危非转移性者；按 CSCO 指南执行","note":"乏力、高血压、癫痫风险、跌倒骨折","renal":"轻中度无需调整","hepatic":"重度肝损减量","interact":"强效 CYP3A4 抑制剂/诱导剂需调整"},{"name":"阿帕他胺/达罗他胺","dose":"阿帕他胺 240 mg qd 或达罗他胺 600 mg bid 口服；mHSPC 或 nmCRPC；按 CSCO 指南执行","note":"皮疹、骨折跌倒、甲状腺功能异常","renal":"重度肾损慎用","hepatic":"重度肝损减量","interact":"强效 CYP3A4 抑制剂调整剂量"},{"name":"多西他赛","dose":"75 mg/m² q3w 静滴+泼尼松 5 mg bid；mCRPC 或高瘤负荷 mHSPC；按 CSCO/NCCN 与体表面积调整","note":"骨髓抑制、周围神经毒性、体液潴留","renal":"轻中度无需调整","hepatic":"肝损减量","interact":"强效 CYP3A4 抑制剂需减量"},{"name":"奥拉帕利（PARP 抑制剂）","dose":"300 mg bid 口服；BRCA1/2 或 HRR 突变 mCRPC；按 CSCO 指南执行","note":"贫血、乏力；监测血常规","renal":"中重度肾损减量","hepatic":"重度肝损慎用","interact":"避免强效 CYP3A4 抑制剂/诱导剂"}],"nonDrug":["低危局限期：主动监测或根治性手术/外照射放疗/近距离放疗","中高危局限期：根治性手术+淋巴结清扫，或放疗+ADT（高危 2–3 年）","转移性：ADT 联合新型内分泌药或化疗，高危可三联","寡转移：原发灶放疗、转移灶立体定向放疗","骨转移：局部放疗，脊髓压迫风险者骨科干预"],"life":["ADT 期间监测骨密度，补钙+维生素 D","关注代谢综合征、心血管风险与肌少症，规律运动","每 3 个月测 PSA 与睾酮"]},"prog":"局限期 5 年生存率 >95%，局部晚期约 80%；mHSPC 中位生存 4–5 年，CRPC 阶段 2–3 年；PSA 倍增时间与内脏转移为主要不良因素。","refs":["CSCO 前列腺癌诊疗指南 2024","中国前列腺癌筛查与早诊早治指南（2022）","NCCN Prostate Cancer Version 2024"]},{"id":"on_ovarian","name":"卵巢癌","aka":["Ovarian Cancer","上皮性卵巢癌","输卵管癌","原发性腹膜癌"],"rank":4,"basic":{"define":"起源于卵巢或输卵管上皮的恶性肿瘤，以 CA125 与 FIGO 分期评估；治疗为手术+紫杉/铂类化疗，BRCA 状态决定 PARP 维持。","risk":["BRCA1/2 胚系突变","Lynch 综合征","未产、初潮早、绝经晚","子宫内膜异位症（透明细胞/子宫内膜样癌）","一级亲属卵巢癌或乳腺癌家族史"],"epi":"我国女性妇科肿瘤死亡首位，年新发约 6 万例；70% 初诊为Ⅲ–Ⅳ期，5 年生存率约 40%。"},"patho":"高级别浆液性癌最常见（约 70%），几乎均伴 TP53 突变，部分存在同源重组修复缺陷（HRD）；BRCA 突变者 HRD 阳性，对铂类与 PARP 抑制剂敏感。主要经腹膜腔种植播散，常伴大量腹水。","dx":{"criteria":["手术病理证实上皮性癌（含输卵管癌、原发腹膜癌）为金标准","CA125 >35 U/ml 升高，联合 HE4 计算 ROMA 指数提高特异性；黏液性癌查 CEA/CA19-9","FIGO 2014 分期：Ⅰ期局限于卵巢；Ⅱ期盆腔内扩散；Ⅲ期腹膜转移或腹膜后淋巴结；Ⅳ期远处转移","腹水细胞学找到腺癌细胞提示Ⅲc 及以上","BRCA1/2 胚系+体系及 HRD 检测为 PARP 适应证依据"],"workup":["经阴道超声+盆腔/腹部增强 CT 或 MRI；胸部 CT","CA125、HE4、CEA、CA19-9、AFP、hCG（年轻者排除生殖细胞肿瘤）","腹水或胸水穿刺细胞学","BRCA1/2 与 HRD 检测；MSI/dMMR 检测","胃肠镜：可疑胃肠道原发或黏液性癌时"],"grading":"FIGO Ⅰ–Ⅳ 期；组织学分为高级别浆液性、低级别浆液性、子宫内膜样、透明细胞、黏液性等。"},"ddx":[{"name":"乳腺癌（on_breast_ca）","point":"与本类 on_breast_ca 的鉴别点：乳腺癌以乳腺肿块首发，CA125 一般不显著升高；卵巢癌以腹胀、盆腔包块、腹水为主，BRCA 突变者两者风险均升高。"},{"name":"胰腺癌（on_pancreatic）","point":"与本类 on_pancreatic 的鉴别点：胰腺癌以黄疸、CA19-9 升高、胰腺低密度占位为主；卵巢癌有腹水但无胰管扩张，CA125 显著升高。"},{"name":"结核性腹膜炎","point":"低热盗汗，腹水 ADA 升高、T-SPOT 阳性，细胞学阴性。"},{"name":"卵巢良性囊肿或子宫内膜异位囊肿","point":"囊性、边界清、CA125 轻升，MRI 见巧克力囊肿特征。"},{"name":"胃肠道肿瘤卵巢转移（Krukenberg 瘤）","point":"双侧卵巢实性肿物，CEA/CA19-9 升高，胃肠镜可找到原发灶。"}],"tx":{"drug":[{"name":"紫杉醇+卡铂（TC 方案）","dose":"紫杉醇 175 mg/m²+卡铂 AUC 5–6 静滴 q3w×6，或紫杉醇 80 mg/m² 周疗+卡铂 AUC 2 周疗；按 CSCO/NCCN 与体表面积调整","note":"神经毒性、骨髓抑制、过敏反应；卡铂按 Calvert 公式依肾功能计算","renal":"卡铂按 CrCl 调整","hepatic":"紫杉醇肝损减量","interact":"紫杉醇经 CYP2C8/3A4 代谢"},{"name":"卡铂+多西他赛","dose":"卡铂 AUC 5+多西他赛 75 mg/m² q3w；紫杉醇过敏或不耐受时替代","note":"骨髓抑制、水肿、脱发","renal":"按肾功能调整卡铂","hepatic":"肝损减量","interact":"强效 CYP3A4 抑制剂需减量"},{"name":"贝伐珠单抗","dose":"15 mg/kg q3w 静滴，联合化疗一线并维持；高危（Ⅳ期或残留多）者；按 CSCO 指南执行","note":"高血压、蛋白尿、血栓、肠穿孔；近期手术或肠梗阻者慎用","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝药合用增加出血"},{"name":"奥拉帕利/尼拉帕利（PARP 抑制剂）","dose":"奥拉帕利 300 mg bid 或尼拉帕利按体重与血小板个体化 200–300 mg qd 口服；BRCA/HRD 阳性一线维持或铂敏感复发维持；按 CSCO 指南执行","note":"贫血、血小板减少、乏力；监测血常规","renal":"中重度肾损减量","hepatic":"重度肝损慎用","interact":"避免强效 CYP3A4 抑制剂/诱导剂"},{"name":"脂质体多柔比星+卡铂","dose":"脂质体多柔比星 30 mg/m²+卡铂 AUC 5 q4w；铂敏感复发；按 CSCO 指南与体表面积调整","note":"手足综合征、骨髓抑制","renal":"按肾功能调整卡铂","hepatic":"肝损减量","interact":"避免与其他蒽环类叠加"},{"name":"拓扑替康或吉西他滨（铂耐药）","dose":"拓扑替康 1.25 mg/m² d1–5 q3w，或吉西他滨 1000 mg/m² d1、d8 q3w；可联合贝伐珠单抗","note":"骨髓抑制为主","renal":"肾损减量","hepatic":"肝损减量","interact":"遵说明书"}],"nonDrug":["初始肿瘤细胞减灭术（PDS）：早期全面分期，Ⅲ–Ⅳ期力争 R0","新辅助化疗+间歇性减灭术（NACT-IDS）：广泛转移或体力差者","BRCA 突变完成生育者可考虑预防性输卵管卵巢切除","复发：铂敏感（>6 个月）再次减灭+含铂化疗；铂耐药以非铂单药±贝伐珠单抗","腹腔热灌注化疗：部分中心用于减灭术后"],"life":["BRCA 突变者家属遗传咨询与基因检测","PARP 维持期间每 4 周监测血常规","每 2–4 个月复查 CA125 与影像"]},"prog":"整体 5 年生存率约 40%–45%；Ⅰ期 >90%，Ⅲ期约 40%，Ⅳ期 <20%；BRCA 突变者对铂类与 PARP 维持反应更好。","refs":["CSCO 卵巢癌诊疗指南 2024","中国卵巢癌维持治疗指南（2022）","NCCN Ovarian Cancer Version 2024"]},{"id":"on_cervical","name":"子宫颈癌","aka":["Cervical Cancer","宫颈癌","宫颈鳞癌","宫颈癌前病变"],"rank":5,"basic":{"define":"发生于子宫颈上皮的恶性肿瘤，几乎均由高危型 HPV 持续感染引起；早期以手术为主，局部晚期行同步放化疗。","risk":["高危型 HPV 持续感染（16、18 型为主）","多个性伴侣或性伴 HPV 阳性","早婚早育、多产","吸烟","免疫抑制（HIV、器官移植）","未接种 HPV 疫苗、未规律筛查"],"epi":"我国女性生殖系统肿瘤发病首位，年新发约 11 万例；发病高峰 45–55 岁。"},"patho":"高危 HPV 的 E6/E7 蛋白分别降解 p53 与 Rb，使细胞周期失控，经 CIN1→CIN2/3→浸润癌演进。鳞癌占 70%–80%，腺癌约 15%–20%；浸润深度与脉管侵犯决定淋巴结转移风险。","dx":{"criteria":["宫颈活检或锥切病理证实浸润癌为金标准","HPV 检测（16/18 分型）用于筛查与分流，TCT 异常者行阴道镜活检","FIGO 2018 分期：Ⅰ期局限于宫颈；Ⅱ期超出子宫未达盆壁或下 1/3 阴道；Ⅲ期达盆壁或下 1/3 阴道，或肾盂积水/区域淋巴结阳性；Ⅳ期侵犯膀胱直肠黏膜或远处转移","分期以临床检查+MRI/PET-CT 为准，淋巴结阳性可上调分期","可疑膀胱/直肠侵犯需膀胱镜与肠镜"],"workup":["妇科双合诊/三合诊评估宫旁与盆壁","盆腔 MRI+胸腹 CT；必要时 PET/CT","SCC 抗原、CEA、CA125 基线","肾功能评估，肾盂积水者置输尿管支架","腺癌可行 p16、HPV 检测辅助分型"],"grading":"FIGO 2018 ⅠA1–ⅣB；组织学类型为鳞癌、腺癌、腺鳞癌等；分级 G1–G3。"},"ddx":[{"name":"卵巢癌（on_ovarian）","point":"与本类 on_ovarian 的鉴别点：卵巢癌以盆腔包块、腹水、CA125 升高为主，宫颈外观多正常；宫颈癌以接触性出血、宫颈肿物为特征。"},{"name":"乳腺癌（on_breast_ca）","point":"与本类 on_breast_ca 的鉴别点：宫颈癌骨转移者需与乳腺癌骨转移鉴别，p16 与 HPV 原位杂交可证实宫颈来源。"},{"name":"宫颈息肉/糜烂样改变","point":"接触性出血但病灶表浅质软，阴道镜及活检可排除癌。"},{"name":"子宫内膜癌","point":"绝经后阴道流血为主，影像见内膜增厚，分段诊刮确诊。"},{"name":"宫颈结核或梅毒溃疡","point":"伴全身感染征象，抗感染后愈合，活检见肉芽肿或螺旋体。"}],"tx":{"drug":[{"name":"顺铂（同步放化疗）","dose":"40 mg/m² 静滴 qw，或 75 mg/m² q3w，与放疗同步；ⅡB–ⅣA 期标准治疗；按 CSCO/NCCN 与体表面积调整","note":"需水化与止吐；监测肾功能、电解质与听力","renal":"eGFR <60 慎用或改用卡铂","hepatic":"重度肝损慎用","interact":"避免与其他肾毒性药物合用"},{"name":"紫杉醇+顺铂（TP 方案）","dose":"紫杉醇 135–175 mg/m²+顺铂 50 mg/m² q3w，一般 6 周期；复发/转移性一线；按 CSCO/NCCN 与体表面积调整","note":"神经毒性、骨髓抑制、肾毒性；紫杉醇需预处理","renal":"顺铂不耐受改用卡铂 AUC 5","hepatic":"紫杉醇肝损减量","interact":"紫杉醇经 CYP2C8/3A4 代谢"},{"name":"贝伐珠单抗","dose":"15 mg/kg q3w 静滴，联合铂类化疗至进展；复发/转移性；按 CSCO 指南执行","note":"高血压、蛋白尿、肠瘘风险","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝药合用增加出血"},{"name":"帕博利珠单抗","dose":"200 mg q3w 静滴，联合含铂化疗±贝伐珠单抗；PD-L1 CPS ≥1 的复发/转移性；按 CSCO 指南执行","note":"免疫相关不良反应；活动性自身免疫病慎用","renal":"无需调整","hepatic":"重度资料有限","interact":"避免长期大剂量激素"},{"name":"拓扑替康（二线）","dose":"1.25 mg/m² d1–5 q3w 静滴；铂类耐药复发","note":"骨髓抑制为主","renal":"肾损减量","hepatic":"肝损减量","interact":"遵说明书"},{"name":"白蛋白紫杉醇","dose":"260 mg/m² q3w 或 125 mg/m² qw×3 停 1 周；紫杉醇过敏或二线","note":"神经毒性、骨髓抑制","renal":"重度肾损慎用","hepatic":"重度肝损减量","interact":"遵说明书"}],"nonDrug":["ⅠA1 无脉管侵犯：宫颈锥切；ⅠA2–ⅠB2：广泛子宫切除+盆腔淋巴结清扫±腹主动脉旁清扫","ⅠB3–ⅡA2 及部分ⅡB：同步放化疗或手术，需术前评估","ⅡB–ⅣA：根治性同步放化疗，近距离后装放疗为核心","ⅣB/复发：全身化疗±贝伐珠单抗±免疫治疗；孤立转移灶可手术或放疗","肾盂积水：输尿管支架或经皮肾造瘘","早期保留生育：根治性宫颈切除+盆腔淋巴结活检"],"life":["HPV 疫苗一级预防，接种后仍需筛查","筛查：25–29 岁每 3 年 TCT；30–65 岁每 5 年 HPV+TCT 联合","治疗后前 2 年每 3 个月复查妇科检查与 SCC 抗原","放疗后阴道扩张防粘连，重视性功能与心理支持"]},"prog":"早期（Ⅰ–ⅡA）5 年生存率 80%–90%，局部晚期（ⅡB–ⅣA）约 60%–70%，ⅣB <20%；疫苗与规范筛查可显著降低发病。","refs":["CSCO 宫颈癌诊疗指南 2024","子宫颈癌综合防控指南（2022）","NCCN Cervical Cancer Version 2024"]}]},{"id":"onco_support","name":"肿瘤支持与并发症","rank":5,"summary":"粒缺伴发热重在 FN 风险分层与 1 小时内经验性抗生素；恶性积液以引流+胸膜固定为主；骨转移规范用骨改良药物并掌握放疗指征；irAE 按分级决定停药与激素。","compare":[{"diseaseId":"on_neutropenic_fever","dx":"化疗后 ANC <0.5×10⁹/L，单次口温 ≥38.3℃ 或 ≥38.0℃ 持续 1 h","key":"1 小时内经验性广谱抗生素，不等培养"},{"diseaseId":"on_malig_effusion","dx":"影像见胸/腹腔积液，穿刺细胞学或病理证实恶性细胞","key":"引流缓解症状+胸膜固定防复发"},{"diseaseId":"on_bone_met","dx":"骨痛/病理性骨折/高钙血症，骨扫描或 MRI/PET 见骨病灶","key":"骨改良药物+局部放疗防 SREs"},{"diseaseId":"on_immunotherapy_tox","dx":"ICI 使用后出现甲状腺、肺、肠、心肌等炎症，排除感染与进展","key":"按 CTCAE 分级决定停药与激素"}],"diseases":[{"id":"on_neutropenic_fever","name":"粒细胞缺乏伴发热","aka":["FN","Febrile Neutropenia","粒缺伴发热","中性粒细胞减少性发热"],"rank":1,"basic":{"define":"化疗后 ANC <0.5×10⁹/L 或预计 48 h 内降至 <0.5×10⁹/L，同时单次口温 ≥38.3℃ 或 ≥38.0℃ 持续 1 h，即为 FN。","risk":["含蒽环类/紫杉类的强化化疗（FN 风险 >20%）","年龄 ≥65 岁","既往化疗后曾发生 FN","骨髓浸润或广泛放疗史","合并糖尿病、慢性肝肾病、营养不良","粒缺持续 >7 天"],"epi":"实体瘤化疗 FN 发生率约 10%–20%，强化方案可 >30%；合并菌血症者病死率 10%–20%，延误抗生素每小时增加死亡风险。"},"patho":"骨髓抑制致黏膜屏障破坏，肠道菌群移位，多为革兰阴性杆菌与革兰阳性球菌。粒缺时无典型脓性渗出，局部症状轻而全身炎症重，易进展为脓毒症与休克。","dx":{"criteria":["ANC <0.5×10⁹/L，或 <1.0×10⁹/L 且预计 48 h 内降至 <0.5","腋温 ≥38.5℃ 或口温 ≥38.3℃ 单次，或口温 ≥38.0℃ 持续 1 h","两条同时具备方可诊断 FN","ANC <0.1×10⁹/L 持续 >7 天属高危，需密切监测","合并低血压或器官功能不全者按脓毒症处理"],"workup":["双上肢及导管侧同时各采 1 套血培养（需氧+厌氧）","血常规+分类、CRP、降钙素原、肝肾功能、电解质、凝血","尿常规+尿培养、痰培养","胸部 CT；腹部超声或 CT 排查腹腔感染","高危者查 G 试验/GM 试验，疑难病例行 mNGS"],"grading":"MASCC 评分 ≥21 为低危，可口服或门诊治疗；<21 或 ANC <0.1×10⁹/L、粒缺 >7 天、低血压、肺炎、腹腔感染者为高危。"},"ddx":[{"name":"免疫相关不良反应（on_immunotherapy_tox）","point":"与本类 on_immunotherapy_tox 的鉴别点：irAE 发热多伴特定器官炎症、ANC 正常，抗生素无效而激素有效；FN 以粒缺为核心，需立即经验性抗生素。"},{"name":"肿瘤热","point":"肿瘤负荷大，发热但 ANC 正常、无感染灶，抗生素无效。"},{"name":"药物热","point":"用药后数天出现，可伴皮疹或嗜酸性粒细胞增多，停药后缓解。"},{"name":"输血反应","point":"输血后立即寒战发热，伴皮疹或溶血表现。"},{"name":"导管相关感染","point":"导管出口红肿流脓，导管与外周血培养同菌且时间差提示导管来源。"}],"tx":{"drug":[{"name":"哌拉西林他唑巴坦","dose":"4.5 g 静滴 q6h 或 q8h（延长输注）；高危 FN 经验性单药，1 小时内给药；遵说明书","note":"覆盖假单胞菌；青霉素过敏改用头孢他啶或碳青霉烯","renal":"CrCl 20–40 减量 q8h，<20 减量 q12h","hepatic":"无需调整","interact":"与甲氨蝶呤合用增加毒性；与华法林合用增加出血"},{"name":"头孢吡肟或美罗培南","dose":"头孢吡肟 2 g 静滴 q8h 或美罗培南 1 g q8h（延长输注）；β-内酰胺过敏或耐药风险时替代；遵说明书","note":"美罗培南可诱发癫痫；为耐药革兰阴性菌首选","renal":"美罗培南 CrCl 25–50 减量 q12h，<25 q24h","hepatic":"无需调整","interact":"美罗培南降低丙戊酸浓度，癫痫患者禁用合用"},{"name":"万古霉素或利奈唑胺（加用）","dose":"怀疑革兰阳性感染（导管、皮肤软组织、肺炎、休克）时加用：万古霉素 15 mg/kg q12h 静滴，谷浓度 15–20 mg/L；或利奈唑胺 600 mg q12h；遵说明书","note":"万古霉素监测肾功能与谷浓度；利奈唑胺注意血小板减少","renal":"万古霉素按 CrCl 调整","hepatic":"利奈唑胺重度肝损慎用","interact":"利奈唑胺与 SSRI 合用致 5-HT 综合征"},{"name":"嗜麦芽窄食单胞菌靶向方案","dose":"头孢他啶/头孢吡肟 2 g q8h 联合阿米卡星 15 mg/kg qd（按肾功能延长间隔），或复方磺胺甲噁唑 15–20 mg/kg（TMP 组分）分次给药；须依据药敏，遵说明书","note":"嗜麦芽窄食单胞菌多重耐药，多需联合；氨基糖苷类监测耳肾毒性","renal":"氨基糖苷按 CrCl 延长间隔；磺胺 CrCl <30 减量","hepatic":"磺胺类肝损慎用","interact":"氨基糖苷类不与万古霉素、顺铂同用"},{"name":"卡泊芬净或伏立康唑（经验性抗真菌）","dose":"卡泊芬净 70 mg 负荷后 50 mg qd，或伏立康唑 6 mg/kg 负荷后 4 mg/kg q12h；持续发热 ≥4–7 天且粒缺未恢复者；遵说明书","note":"不作初始经验治疗；GM 阳性或影像见真菌灶时启用","renal":"卡泊芬净无需调整；伏立康唑静滴在 CrCl <50 慎用","hepatic":"伏立康唑肝损减量","interact":"伏立康唑与华法林、他克莫司相互作用显著"},{"name":"G-CSF（非格司亭/培非格司亭）","dose":"非格司亭 5 μg/kg qd 皮下至 ANC ≥2.0×10⁹/L；培非格司亭 6 mg 于化疗后 24 h 单次皮下；FN 风险 ≥20% 方案作一级预防；FN 治疗期间仅高危者使用；遵说明书","note":"化疗后 24–72 h 起用；骨痛为主要副作用","renal":"无需调整","hepatic":"无需调整","interact":"白血病患者避免与化疗同时使用"}],"nonDrug":["采血培养后 1 小时内首剂抗生素；高危者住院静脉给药","低危（MASCC ≥21）可口服莫西沙星+阿莫西林克拉维酸，48–72 h 无改善改静脉","疑似导管感染或脓毒症时拔除中心静脉导管","严格手卫生与保护性隔离，避免生食","血流动力学不稳定按脓毒症集束化治疗：液体复苏、血管活性药、氧疗"],"life":["化疗前评估 FN 风险，≥20% 方案预防性 G-CSF","化疗后 7–14 天每日测体温，发热立即就诊，勿自行用退热药","口腔护理、软毛牙刷、防便秘，减少黏膜损伤"]},"prog":"恰当处理下病死率约 5%–10%，合并脓毒症休克可升至 30%–50%；低危组 <1%；ANC 恢复且发热消退 48 h 可考虑降阶或停药。","refs":["中国中性粒细胞缺乏伴发热患者抗菌药物临床应用指南（2023 版）","CSCO 肿瘤放化疗相关中性粒细胞减少症规范化管理指南 2021","IDSA Febrile Neutropenia Guideline 2010"]},{"id":"on_malig_effusion","name":"恶性胸腔积液与腹水","aka":["Malignant Pleural Effusion","Malignant Ascites","MPE","恶性胸水","癌性腹水"],"rank":2,"basic":{"define":"肿瘤直接侵犯或转移至胸膜、腹膜引起的积液，积液细胞学或活检证实恶性细胞；常见于肺癌、乳腺癌、卵巢癌与消化道肿瘤。","risk":["晚期肺癌（尤其腺癌）胸膜播散","乳腺癌胸膜/腹膜转移","卵巢癌腹膜播散","消化道肿瘤腹膜转移","淋巴瘤致淋巴管阻塞"],"epi":"约 15% 的恶性肿瘤患者出现恶性胸腔积液，肺癌占 1/3；卵巢癌与消化道肿瘤是恶性腹水主要来源，出现腹水中位生存 3–6 个月。"},"patho":"肿瘤侵犯胸膜、腹膜使毛细血管通透性增加，淋巴孔堵塞与淋巴结转移阻碍回流，肿瘤分泌 VEGF 进一步增加通透性。胸腔积液压迫肺致呼吸困难，腹水使膈肌上抬、腹腔压升高。","dx":{"criteria":["诊断性穿刺：胸水多为渗出液（积液蛋白/血清蛋白 >0.5，或 LDH >血清上限 2/3）","细胞学找到恶性细胞或胸膜/腹膜活检病理证实为金标准","胸水 CEA、CA125、CA15-3 免疫组化协助判断来源","重复穿刺阴性但高度怀疑者行胸腔镜胸膜活检","积液量按影像评估：少量 <500 ml、中量 500–1500 ml、大量 >1500 ml"],"workup":["胸部或腹部超声定位引导穿刺，记录积液量与分隔","胸水或腹水常规、生化、细胞学，加 ADA、T-SPOT 排除结核","胸腹增强 CT 评估原发灶、胸膜结节与淋巴结","腹水 SAAG（血清-腹水白蛋白梯度）评估有无门脉高压","血常规、白蛋白、凝血与肝肾功能"],"grading":"无统一分级；按积液量与呼吸困难 mMRC 分级（0–4）综合评估。"},"ddx":[{"name":"骨转移与 SREs（on_bone_met）","point":"与本类 on_bone_met 的鉴别点：骨转移以骨痛、病理性骨折、高钙血症为主，无需抽液；恶性积液以呼吸困难或腹胀、积液细胞学阳性为核心。"},{"name":"结核性胸膜炎/腹膜炎","point":"低热盗汗，ADA >40 U/L、T-SPOT 阳性，细胞学阴性，抗结核治疗有效。"},{"name":"心衰/低蛋白漏出液","point":"双侧胸水、利钠肽升高、利尿有效，符合漏出液标准。"},{"name":"肝硬化腹水","point":"有肝病背景，SAAG ≥11 g/L 伴门脉高压征象，细胞学阴性。"},{"name":"免疫相关性浆膜炎","point":"免疫治疗后出现，伴其他器官 irAE，激素有效，细胞学阴性。"}],"tx":{"drug":[{"name":"博来霉素（胸膜固定）","dose":"60 IU 溶于 50 ml 生理盐水胸腔注入，夹管 1–4 h 后引流，可重复 1–3 次；肺完全复张后使用；遵说明书","note":"胸痛与发热常见；积液 pH ≤7.2 或肺复张不全者固定失败率高","renal":"重度肾损慎用","hepatic":"遵说明书","interact":"避免与其他肺毒性药物合用"},{"name":"滑石粉（胸膜固定）","dose":"医用滑石粉 4–5 g 悬液胸腔注入，或胸腔镜下喷洒 2–5 g；复发性恶性胸水有效率 >95%；遵说明书与操作规范","note":"需完全肺复张；术后发热胸痛常见，罕见急性呼吸窘迫","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"贝伐珠单抗（胸腔/腹腔灌注）","dose":"4–7.5 mg/kg 胸腔或腹腔注射，联合全身化疗 q3w；仅限指南推荐与经验证的适应证","note":"高血压、出血、肠穿孔风险，需个体化","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝药合用增加出血"},{"name":"重组人血管内皮抑制素（胸腔灌注）","dose":"45–60 mg 胸腔注入，每周 1–2 次，共 3–4 次；联合全身化疗；按指南与说明书执行","note":"局部刺激疼痛；监测心脏事件","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他抗血管药物叠加"},{"name":"利尿剂（呋塞米/螺内酯）","dose":"螺内酯 40–100 mg qd±呋塞米 20–40 mg qd；仅用于合并门脉高压或心衰者，恶性腹水单用利尿获益有限","note":"监测电解质与尿量","renal":"监测 CrCl，避免过度利尿","hepatic":"肝硬化者监测血氨","interact":"NSAIDs 削弱利尿作用"},{"name":"托伐普坦（腹水伴低钠）","dose":"15 mg qd 起始，按血钠调整，疗程 ≤28 天；用于合并明显稀释性低钠者；遵说明书","note":"须缓慢纠正血钠，过快致渗透性脱髓鞘","renal":"CrCl <10 禁用","hepatic":"重度肝损禁用","interact":"禁与克拉霉素、伊曲康唑等强效 CYP3A4 抑制剂合用"}],"nonDrug":["治疗性抽液：胸水首日 ≤1000 ml、之后每次 ≤1500 ml 缓慢引流，防复张性肺水肿","腹水每次抽 3000–5000 ml，按每升 6–8 g 补充白蛋白","胸膜固定：经引流或胸腔镜注入滑石粉/博来霉素，适用于肺完全复张且预计生存 >2–3 个月者","持续引流导管（PleurX）：复张不全或需频繁抽液者居家引流","顽固性腹水可结合全身化疗或靶向治疗（如卵巢癌用贝伐珠单抗）"],"life":["抽液后 6–24 h 复查影像，警惕气胸与复张性肺水肿","低盐饮食（钠 <2 g/d），腹水者限水（除非低钠）","引流期间监测血压、心率、白蛋白与电解质"]},"prog":"恶性胸腔积液确诊后中位生存 3–12 个月（肺癌约 4–7 个月、乳腺癌 8–12 个月）；恶性腹水中位生存 3–6 个月；反复积液与低蛋白提示预后差。","refs":["中国恶性胸腔积液诊断与治疗专家共识（2022）","CSCO 恶性浆膜腔积液诊疗指南 2023","ATS Guideline: Management of Malignant Pleural Effusions 2018"]},{"id":"on_bone_met","name":"骨转移与骨相关事件","aka":["Bone Metastasis","SREs","骨转移","骨相关事件","骨改良药物"],"rank":3,"basic":{"define":"恶性肿瘤转移至骨骼，引起骨痛、病理性骨折、脊髓压迫、高钙血症等骨相关事件（SREs）；常见于乳腺癌、前列腺癌、肺癌、肾癌与多发性骨髓瘤。","risk":["乳腺癌（激素受体阳性者骨转移率高）","前列腺癌（成骨性转移）","肺癌（生存期短）","肾癌与甲状腺癌（溶骨性、富血供）","既往骨转移或高钙血症史","长期大剂量糖皮质激素"],"epi":"约 65%–75% 的晚期乳腺癌/前列腺癌与 30%–40% 的晚期肺癌发生骨转移；发生 SRE 后中位生存显著缩短。"},"patho":"肿瘤分泌 PTHrP、IL-6、TNF-α 激活破骨细胞形成溶骨性病灶，或使成骨细胞异常增殖形成成骨性病灶。病理性骨折、脊髓压迫与高钙血症是主要致残致死并发症。","dx":{"criteria":["骨痛（夜间及负重痛加重）伴影像见骨破坏或成骨病灶","骨扫描敏感但特异低；MRI 对骨髓与脊髓受压敏感；CT 显示骨破坏；PET/CT 全身评估","碱性磷酸酶、钙、磷与骨转换标志物辅助监测","首次发现孤立骨病灶需活检明确病理来源","SREs 定义：病理性骨折、脊髓压迫、需放疗或手术、高钙血症"],"workup":["全身骨扫描或 PET/CT 评估转移范围","脊柱 MRI：有背痛或神经症状时评估脊髓压迫","血钙、白蛋白、ALP、肌酐、eGFR 与尿白蛋白","用药前口腔与牙科检查","必要时骨病灶穿刺活检与免疫组化"],"grading":"Mirels 评分评估长骨病理性骨折风险，总分 ≥9 分建议预防性内固定；脊髓压迫以 Tokuhashi/Tomita 评分评估手术与预后。"},"ddx":[{"name":"恶性胸腔积液与腹水（on_malig_effusion）","point":"与本类 on_malig_effusion 的鉴别点：恶性积液以呼吸困难或腹胀为主，需抽液与胸膜固定；骨转移以骨痛、骨折、高钙血症为主。"},{"name":"免疫相关不良反应（on_immunotherapy_tox）","point":"与本类 on_immunotherapy_tox 的鉴别点：免疫治疗后的肌炎或关节炎可似骨痛，但无骨破坏，影像与 ALP 正常，激素有效。"},{"name":"骨质疏松/骨关节炎","point":"弥漫性骨密度下降，骨扫描无局灶高摄取，MRI 无异常信号。"},{"name":"多发性骨髓瘤","point":"穿凿样溶骨病灶无成骨反应，血/尿免疫固定电泳见 M 蛋白，骨髓浆细胞 >10%。"},{"name":"骨结核/化脓性骨髓炎","point":"发热、局部红肿，MRI 见椎间盘受累与椎旁脓肿，穿刺培养可确诊。"}],"tx":{"drug":[{"name":"唑来膦酸","dose":"4 mg 静滴 q4w，输注 ≥15 min；肾损时 CrCl 30–50 用 3 mg，CrCl <30 慎用；高钙血症 4 mg 单次；遵说明书","note":"用药前补钙+维生素 D；监测 CrCl 与血钙；颌骨坏死与房颤风险","renal":"CrCl <30 慎用，高钙血症者用 3 mg","hepatic":"无需调整","interact":"氨基糖苷类增加低钙风险；NSAIDs 加重肾损"},{"name":"地舒单抗","dose":"120 mg 皮下 q4w；实体瘤骨转移；高钙血症时第 2 周加 180 mg 单次，之后 120 mg q4w；遵说明书","note":"需补钙+维生素 D，肾损者低钙血症可严重；停药需桥接防骨吸收反跳","renal":"CrCl <30 或透析者慎用，密切监测血钙","hepatic":"无需调整","interact":"不与双膦酸盐联用"},{"name":"伊班膦酸","dose":"6 mg 静滴 q3w–q4w；唑来膦酸不耐受时替代；遵说明书","note":"低钙、肾毒性；输注前充分水化","renal":"CrCl <30 慎用","hepatic":"无需调整","interact":"同双膦酸盐类"},{"name":"对乙酰氨基酚/NSAIDs（骨痛镇痛）","dose":"对乙酰氨基酚 0.5–1 g q6h（最大 4 g/d）；NSAIDs 按说明书短程使用","note":"骨转移伴肾损者慎用 NSAIDs","renal":"CrCl <30 慎用 NSAIDs","hepatic":"肝功能不全减量","interact":"NSAIDs 与双膦酸盐同用增加肾毒性"},{"name":"阿片类（中重度骨痛）","dose":"羟考酮缓释片 10 mg q12h 或吗啡缓释片 30 mg q12h 起始，按需滴定；遵循 WHO 三阶梯；遵说明书","note":"便秘、恶心、呼吸抑制；联用止吐与缓泻剂","renal":"肾功能不全避免吗啡，改用芬太尼透皮或氢可酮","hepatic":"重度肝损减量","interact":"避免与苯二氮䓬类合用"},{"name":"镭-223（前列腺癌骨转移）","dose":"55 kBq/kg 静注 q4w×6；限 mCRPC 骨转移且无内脏转移者；遵说明书","note":"骨髓抑制；监测血象与骨扫描","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他骨髓抑制治疗重叠"}],"nonDrug":["局部放疗指征：承重骨痛、脊髓压迫早期（24–48 h 内激素+放疗或手术）、高骨折风险、术后辅助放疗","单次 8 Gy 与分次 30 Gy 止痛相当；已骨折或神经压迫者优先手术内固定/减压","Mirels ≥9 分长骨转移灶行预防性内固定","脊柱转移无运动神经损伤者外照射；有神经损伤按评分选椎体切除+内固定或姑息放疗","椎体成形/后凸成形术用于疼痛剧烈的压缩性骨折","放射性核素（锶-89、钐-153）：广泛骨痛且骨髓功能尚可"],"life":["补钙 1000–1200 mg/d+维生素 D 800–1000 IU/d","跌倒预防、助行器、避免负重","口腔卫生与定期牙科检查，防颌骨坏死","每 3 个月监测钙、ALP、CrCl"]},"prog":"骨转移多为不可治愈，中位生存因原发瘤而异（乳腺 2–3 年、前列腺 2–4 年、肺癌 6–12 个月）；规范骨改良药物可降低 SRE 风险约 30%–40%。","refs":["CSCO 骨与软组织肿瘤诊疗指南 2024（骨转移部分）","中国恶性肿瘤骨转移诊疗专家共识（2019 版）","ESMO Clinical Practice Guideline: Bone Metastases 2023"]},{"id":"on_immunotherapy_tox","name":"免疫相关不良反应","aka":["irAE","Immune-Related Adverse Events","免疫检查点抑制剂不良反应","免疫性甲状腺炎","免疫性肺炎","免疫性结肠炎","免疫性心肌炎"],"rank":4,"basic":{"define":"免疫检查点抑制剂（ICI：PD-1/PD-L1/CTLA-4 抑制剂）引起的自身免疫样器官损伤，可累及皮肤、甲状腺、肺、肠、肝、垂体与心肌，按 CTCAE 分级处理。","risk":["CTLA-4 与 PD-1 抑制剂联合（毒性叠加）","既往自身免疫病（炎症性肠病、类风湿、银屑病）","既往 irAE 史","器官移植、HIV 或慢性乙肝","高肿瘤负荷与基线炎症指标升高"],"epi":"单药 ICI 任意级别 irAE 约 30%–40%，联合治疗达 60%–80%，3–4 级 5%–15%；心肌炎罕见（<1%）但病死率 25%–50%。"},"patho":"PD-1/PD-L1 或 CTLA-4 通路阻断使 T 细胞失去外周耐受，针对甲状腺过氧化物酶、结肠上皮、心肌肌钙蛋白等自身抗原发生克隆扩增与细胞毒损伤。CTLA-4 阻断更易累及肠道与垂体，PD-1 阻断更易致肺炎、甲状腺炎与心肌炎。","dx":{"criteria":["ICI 使用期间或停药后数周至数月新发器官相关症状（呼吸困难、腹泻、乏力、心悸）","CTCAE 5.0 分级：1 级轻度；2 级影响日常活动；3 级重度、需住院；4 级危及生命","甲状腺炎：TSH/FT4 异常，多先甲亢后甲减，抗体常阳性","免疫性肺炎：CT 见新发磨玻璃影或网格影，需排除感染与进展","免疫性结肠炎：腹泻 ≥4 次/日伴腹痛，肠镜见黏膜炎症，粪钙卫蛋白升高","免疫性心肌炎：肌钙蛋白升高、心电图与超声异常，心脏 MRI 确诊"],"workup":["基线及每周期：血常规、肝肾功能、TSH/FT4；联合治疗加肌钙蛋白与心电图","呼吸道症状：胸部高分辨 CT、血气、病原学（含 CMV、PCP）","腹泻：粪培养、艰难梭菌毒素、粪钙卫蛋白，必要时肠镜活检","疑似心肌炎：肌钙蛋白、BNP、心电图、心脏超声、心脏 MRI","垂体炎：皮质醇、ACTH、甲状腺与性激素、垂体 MRI"],"grading":"CTCAE 5.0 通用分级；肺炎按影像与氧合，结肠炎按腹泻与腹痛，心肌炎按肌钙蛋白、心功能与血流动力学细分。"},"ddx":[{"name":"粒细胞缺乏伴发热（on_neutropenic_fever）","point":"与本类 on_neutropenic_fever 的鉴别点：FN 有 ANC <0.5×10⁹/L 与高热，需 1 小时内广谱抗生素；irAE 发热伴器官炎症、ANC 正常、抗生素无效。"},{"name":"恶性胸腔积液与腹水（on_malig_effusion）","point":"与本类 on_malig_effusion 的鉴别点：irAE 浆膜炎积液多双侧少量，激素有效、细胞学阴性；恶性积液多单侧大量，细胞学阳性。"},{"name":"细菌性肺炎","point":"脓痰、白细胞与 PCT 升高、痰培养阳性、抗生素有效。"},{"name":"肿瘤进展或假性进展","point":"影像增大但症状稳定，需重复影像与活检，irAE 常伴多器官受累。"},{"name":"艰难梭菌结肠炎","point":"近期抗生素史，粪毒素阳性，停用或针对性治疗后好转。"}],"tx":{"drug":[{"name":"泼尼松/甲泼尼龙","dose":"2 级：泼尼松 0.5–1 mg/kg/d 口服，4–6 周逐渐减停；3 级：甲泼尼龙 1–2 mg/kg/d 静滴，改善后转口服缓慢减量；4 级：甲泼尼龙 1 g/d 冲击 3–5 天；遵 CSCO/NCCN irAE 指南","note":"不得骤停；预防 PCP、真菌与消化道出血；监测血糖","renal":"无需调整","hepatic":"无需调整","interact":"与其他免疫抑制剂合用增加感染风险"},{"name":"英夫利西单抗","dose":"5 mg/kg 静滴，2 周后重复；用于激素 48–72 h 无效的 3 级结肠炎或肺炎；遵指南","note":"用药前筛查结核与乙肝；监测感染","renal":"无需调整","hepatic":"无需调整","interact":"避免与其他 TNF 抑制剂合用"},{"name":"吗替麦考酚酯/他克莫司","dose":"吗替麦考酚酯 500–1000 mg bid，或他克莫司按血药浓度调整；用于激素+英夫利西无效的重度 irAE；遵指南并请专科会诊","note":"监测血药浓度、血象与感染","renal":"遵说明书","hepatic":"遵说明书","interact":"他克莫司与 CYP3A4 药物相互作用显著"},{"name":"左甲状腺素（甲减替代）","dose":"按体重 1.6 μg/kg/d 起始，老年或心脏病者 25–50 μg/d 起始缓慢加量；遵说明书","note":"每 4–6 周复查 TSH 调整；空腹服用，避开钙铁剂","renal":"无需调整","hepatic":"无需调整","interact":"抑酸剂与钙铁剂降低吸收"},{"name":"洛哌丁胺（轻度腹泻）","dose":"4 mg 起服，之后每次便后 2 mg，最大 16 mg/d；仅用于 1 级结肠炎","note":"感染性腹泻禁用；3 级结肠炎禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"心肌炎对症（美托洛尔缓释片）","dose":"23.75–47.5 mg qd 起始，按心率与血压调整；心衰者按指南加 ACEI/ARB 与利尿剂；须与大剂量激素同步，心脏科会诊","note":"需监护病房观察；避免新增心脏毒性化疗","renal":"遵说明书","hepatic":"遵说明书","interact":"与钙通道阻滞剂合用致心动过缓"}],"nonDrug":["1 级：多可继续 ICI 并密切监测，通常不用激素","2 级：暂停 ICI，激素 0.5–1 mg/kg/d，恢复至 1 级后减停并评估重启","3–4 级：住院大剂量激素，48–72 h 无效加免疫抑制剂；心脏、神经、肺炎 3 级以上多永久停用 ICI","免疫性肺炎 3 级需吸氧，4 级机械通气","免疫性结肠炎 3 级以上需肠镜评估，必要时肠外营养，警惕中毒性巨结肠","免疫性心肌炎：监护病房、心电监护、大剂量激素±ATG/吗替麦考酚酯"],"life":["治疗前筛查自身免疫病、甲功、乙肝/HIV 与结核","每周期评估症状与甲功、肝功；联合治疗加心脏指标","教育患者腹泻、气促、心悸、皮疹及时就诊，勿自行用退热药掩盖发热"]},"prog":"多数 1–2 级 irAE 经激素可恢复，少数遗留永久性甲减或垂体功能低下；心肌炎与 4 级肺炎病死率高（心肌炎 25%–50%），早期识别与及时激素最关键。","refs":["CSCO 免疫检查点抑制剂相关的毒性管理指南 2023","NCCN Management of Immunotherapy-Related Toxicities Version 2024","ESMO Management of Toxicities from Immunotherapy 2022"]}]}]},"ortho":{"categories":[{"id":"fracture","name":"骨折","rank":1,"summary":"髋部与长骨干骨折是骨科最常见的急诊手术来源：先评估全身状况与软组织（开放伤、骨筋膜室）、复位并可靠固定以恢复力线与早期活动，老年髋部骨折强调 48 h 内手术、围术期抗凝与抗骨质疏松治疗并举。","compare":[{"diseaseId":"or_femur_neck","dx":"多为低能量跌倒后髋部疼痛、不能负重，患肢短缩外旋，X 线见股骨头下至股骨颈基底部骨折线，CT/MRI 用于隐匿性骨折","key":"骨折线位于关节囊内（股骨颈），血供破坏重、股骨头坏死与不愈合风险高，老年移位型首选关节置换"},{"diseaseId":"or_intertroch","dx":"跌倒后髋部剧痛不能站立，大转子区压痛伴皮下瘀斑，患肢明显短缩外旋，X 线见骨折线经大小转子间","key":"属囊外骨折，股骨头血供多保留、骨不连与头坏死少见，以髓内钉坚强内固定为主"},{"diseaseId":"or_tibial","dx":"小腿外伤后肿胀疼痛畸形，可触及反常活动与骨擦感，X 线见胫骨或胫腓骨干骨折线，须评估开放性、神经血管与骨筋膜室","key":"软组织条件与开放伤分级决定手术时机，优先警惕骨筋膜室综合征"}],"diseases":[{"id":"or_femur_neck","name":"股骨颈骨折","aka":["Femoral Neck Fracture","FNF","股骨头下骨折","髋部骨折"],"rank":1,"basic":{"define":"股骨头下至股骨颈基底部之间的骨折，位于关节囊内，属囊内骨折；多见于老年人低能量跌倒，青壮年多为高能量损伤。","risk":["年龄 >65 岁、女性绝经后","骨质疏松/骨密度 T 值 ≤ −2.5","跌倒史、视力障碍、步态不稳","长期使用糖皮质激素、镇静催眠药","高能量外伤（青壮年）"],"epi":"股骨颈骨折约占髋部骨折的 50%；我国 65 岁以上人群髋部骨折发病率约 1%，女性高于男性，预计 2050 年髋部骨折例数将超过 100 万例/年；伤后 1 年死亡率约 15%–25%。"},"patho":"股骨颈血供主要来自旋股内侧动脉升支（支持带血管），骨折移位后血管扭曲或撕裂，股骨头缺血坏死率随移位程度升高；同时关节囊内出血使囊内压升高进一步影响灌注。骨折端为松质骨-皮质骨移行区，剪力大，愈合能力差，加之老年患者骨质疏松与卧床并发症，共同导致高不愈合率与高病死率。","dx":{"criteria":["病史：跌倒后髋部疼痛、不能负重行走，老年患者可仅诉膝部放射痛","体征：患肢短缩、外旋（多 45°–60°）、腹股沟中点压痛、轴向叩击痛阳性；无大腿肿胀瘀斑","X 线正侧位：骨折线位于股骨头下至股骨颈基底部；Garden 分型须在正侧位双向评估","X 线阴性而临床高度怀疑时行 CT（层厚 ≤2 mm）或 MRI，后者对隐匿性骨折敏感度接近 100%","排除同侧股骨干、桡骨远端、肱骨近端等合并损伤，评估基础疾病与用药"],"workup":["骨盆正位 + 患髋正侧位 X 线，必要时加摄股骨全长","髋关节 CT 三维重建：判断移位、后倾与粉碎程度，指导内固定选择","MRI：X 线与 CT 阴性但体检阳性的隐匿性骨折","术前：血常规、凝血、生化、心电图、胸片、心脏超声（必要时）、下肢静脉超声","骨密度检测（DXA）与骨质疏松评估（必要时查 25-OH 维生素 D、甲状旁腺素）","老年患者行衰弱评估（衰弱量表）、谵妄风险与营养风险筛查"],"grading":"Garden 分型：Ⅰ型 不完全骨折/外展嵌插；Ⅱ型 完全骨折但无移位；Ⅲ型 完全骨折部分移位（股骨头小梁与髋臼小梁不平行）；Ⅳ型 完全骨折完全移位（股骨头小梁重新与髋臼平行）。Ⅰ、Ⅱ型为无移位，Ⅲ、Ⅳ型为移位型。亦可采用 Pauwels 角分型（按骨折线与水平线夹角评估剪切力）与 AO/OTA 31-B 分型。"},"ddx":[{"name":"股骨转子间骨折（or_intertroch）","point":"与本类 or_intertroch 的鉴别点：转子间骨折为囊外骨折，局部肿胀、皮下瘀斑明显，患肢外旋可达 90°，X 线骨折线经大、小转子；股骨颈骨折外旋多为 45°–60°，无明显肿胀瘀斑，骨折线位于关节囊内。"},{"name":"胫腓骨骨折（or_tibial）","point":"与本类 or_tibial 的鉴别点：胫腓骨骨折部位在小腿，有局部畸形、反常活动与骨擦感；股骨颈骨折疼痛在髋部，膝部放射痛易被误认为膝关节病变，查体髋关节活动痛阳性即可区分。"},{"name":"髋关节脱位","point":"多为高能量损伤，后脱位患肢屈曲、内收、内旋、短缩，前脱位外旋外展，X 线见股骨头脱出髋臼，常伴髋臼后壁骨折。"},{"name":"髋部软组织挫伤/转子滑囊炎","point":"可负重行走，疼痛局限、无短缩与外旋，X 线、CT、MRI 均无骨折线。"}],"tx":{"drug":[{"name":"头孢呋辛（围术期预防）","dose":"1.5 g 静脉滴注，术前 0.5–1 h 给药，手术时间 >3 h 或出血 >1500 mL 术中追加 1 次；术后 24 h 内停药","note":"β-内酰胺类过敏者改用克林霉素 0.6–0.9 g 或万古霉素 1 g 静滴","renal":"eGFR <30 时减量或延长给药间期，遵说明书","hepatic":"严重肝功能不全慎用","interact":"与华法林合用可增强抗凝作用，需监测 INR"},{"name":"依诺肝素（静脉血栓预防）","dose":"40 mg 皮下注射 q24h，术后 6–12 h（确认无活动性出血）开始；或磺达肝癸钠 2.5 mg 皮下注射 qd","note":"预防持续至术后 28–35 天（髋部骨折与髋关节置换属血栓极高危）","renal":"CrCl 15–30 mL/min 减为 30 mg q24h；CrCl <15 用普通肝素 5000 U 皮下注射 bid","hepatic":"严重肝病伴凝血障碍者慎用","interact":"与 NSAIDs、抗血小板药联用增加出血；与磺达肝癸钠不叠加使用"},{"name":"帕瑞昔布钠（镇痛）","dose":"40 mg 静脉注射 q12h，疗程不超过 3 天，之后改口服 NSAIDs 或对乙酰氨基酚 0.5–1 g q6h","note":"多模式镇痛：神经阻滞（髂筋膜/股神经阻滞）+ 对乙酰氨基酚 + NSAIDs，减少阿片用量；老年患者避免长期 NSAIDs","renal":"eGFR <30 禁用；用药期间监测肌酐、尿量","hepatic":"重度肝功能不全禁用","interact":"与抗凝药联用增加出血与消化道损伤；避免与其他 NSAIDs 叠加"},{"name":"碳酸钙 D3 片（抗骨质疏松）","dose":"元素钙 600 mg + 维生素 D3 125 IU，每日 1–2 次口服","note":"所有髋部骨折患者均应评估并启动抗骨质疏松治疗；骨折联络服务（FLS）管理","renal":"慢性肾脏病 4–5 期改用骨化三醇，遵说明书","hepatic":"遵说明书","interact":"与喹诺酮类、四环素类间隔 2 h 以上服用"},{"name":"唑来膦酸（抗骨质疏松）","dose":"5 mg 静脉滴注，每年 1 次，输注时间 ≥15 min","note":"急性期后使用；术前 eGFR 须 ≥35 mL/min，注意一过性流感样症状、低钙血症与颌骨坏死风险（先处理口腔问题）","renal":"CrCl <35 mL/min 禁用","hepatic":"遵说明书","interact":"避免与含钙输液同瓶；与 NSAIDs 合用增加肾损伤风险"}],"nonDrug":["无移位（Garden Ⅰ、Ⅱ型）且身体条件差者：可选择保守治疗（卧床牵引/防旋鞋），但须尽早床边活动以降低卧床并发症","移位型（Garden Ⅲ、Ⅳ型）老年患者：首选人工股骨头置换或全髋关节置换，年龄 <65–70 岁且活动量大者优选全髋置换","青壮年（<65 岁）：优先保髋，解剖复位后空心螺钉（3 枚）或动力髋螺钉内固定；复位不满意或颈后粉碎者考虑股骨颈内侧支撑钢板","骨质疏松老年无移位骨折：可考虑股骨颈系统（FNS）或空心螺钉，术后早期非负重训练","老年髋部骨折应纳入快速通道，力争 48 h 内手术；术前纠正贫血、电解质紊乱与容量不足","术后 24 h 内开始坐起、48 h 内在助行器辅助下下地，防跌倒宣教与居家环境改造"],"life":["术后 6 周、3 个月、6 个月、12 个月复查 X 线评估愈合与假体位置","坚持抗骨质疏松治疗并每年复查骨密度与用药依从性","补充优质蛋白与维生素 D，跌倒风险筛查（视力、步态、家庭环境、镇静药物）","戒烟限酒，避免长期使用苯二氮䓬类与过量镇静药"]},"prog":"无移位骨折不愈合率约 5%–10%，移位型可高达 20%–30%；移位型股骨头缺血坏死率约 10%–30%，多在伤后 2 年内出现。老年移位型骨折行关节置换后多数可恢复至伤前行走能力，但伤后 1 年死亡率约 15%–25%，合并痴呆、多病共存与延迟手术者更高。","refs":["中华医学会骨科学分会创伤骨科学组《成人股骨颈骨折诊治专家共识》2021","中华医学会骨科学分会《中国老年髋部骨折诊疗与管理专家共识》2017","《中国骨科手术加速康复——髋关节置换围手术期管理专家共识》2021","《中国创伤骨科患者围手术期静脉血栓栓塞症预防指南》2021","AAOS Management of Hip Fractures in Older Adults, 2021"]},{"id":"or_intertroch","name":"股骨转子间骨折","aka":["Intertrochanteric Fracture","ITF","转子间骨折","股骨粗隆间骨折"],"rank":2,"basic":{"define":"自股骨大转子至小转子连线区域的骨折，位于关节囊外，属囊外骨折；随年龄增长以低能量跌倒为主。","risk":["高龄、女性","骨质疏松","跌倒与步态失衡","合并心脑血管病、糖尿病、慢性肾病","抗凝/抗血小板药物使用"],"epi":"我国髋部骨折中，转子间骨折约占 45%–50%，随年龄增长其占比上升；患者平均年龄高于股骨颈骨折，合并症多、手术与麻醉风险相应增加。"},"patho":"骨折多为间接暴力（跌倒时大转子着地，内翻/外旋应力）所致，骨折线经大、小转子，属松质骨区，血供丰富，股骨头坏死与骨不连少见；但内侧皮质（小转子区）粉碎者失去内侧支撑，内翻塌陷与内固定切出风险增加。骨折后失血量常达 500–1000 mL，隐匿性失血与贫血是围术期主要问题。","dx":{"criteria":["跌倒后髋部剧痛、不能站立行走","患肢明显短缩、外旋（可达 90°），大转子区压痛，可见大腿近外侧皮下瘀斑","骨盆正位 + 髋关节侧位 X 线：骨折线经大转子至小转子；必要时加股骨全长排除转子下延伸","CT 三维重建用于评估小转子是否受累、骨折线是否累及转子下及后壁粉碎","老年患者入院评估 Hb、凝血、心电图与用药（尤其抗凝药）"],"workup":["正侧位 X 线为确诊基础，三维 CT 辅助分型与髓内钉入点规划","血型、交叉配血、血常规动态复查（伤后 24–48 h Hb 可继续下降）","心脏超声、BNP、心电图：合并心血管病的老年患者术前评估与输血/麻醉策略","下肢静脉超声筛查术前深静脉血栓（非急诊时限可先完成筛查）","评估骨质疏松、营养状态与谵妄风险"],"grading":"常用 AO/OTA 31-A 分型：A1 经转子简单骨折（两段）；A2 转子间粉碎骨折；A3 反转子间骨折（骨折线从小转子向外上方延伸，合并转子下延伸）。Evans 分型与之近似：Ⅰ型（稳定，含 Ⅰa 无移位、Ⅰb 复位后稳定）、Ⅱ型（不稳定，含 Ⅱa 内侧皮质粉碎、Ⅱb 反转子）。"},"ddx":[{"name":"股骨颈骨折（or_femur_neck）","point":"与本类 or_femur_neck 的鉴别点：转子间骨折局部肿胀瘀斑明显、外旋可达 90°、大转子压痛突出，X 线骨折线经转子；股骨颈骨折为囊内骨折，无明显肿胀，外旋多 <60°，以关节置换为主。"},{"name":"胫腓骨骨折（or_tibial）","point":"与本类 or_tibial 的鉴别点：胫腓骨骨折在小腿，局部畸形与反常活动；转子间骨折虽有膝部放射痛，但髋部压痛、患肢短缩外旋显著，X 线定位明确。"},{"name":"股骨转子下骨折","point":"骨折线主要位于小转子下方 5 cm 内，AO 归为 32 型；反转子间骨折可向转子下延伸，需 CT 明确，影响内固定长度选择（长髓内钉 vs 短钉）。"},{"name":"病理性骨折（转移瘤/多发性骨髓瘤）","point":"轻微外伤即骨折、X 线见溶骨性破坏与骨皮质变薄，需结合肿瘤史、血钙、M 蛋白与 MRI/穿刺活检。"}],"tx":{"drug":[{"name":"头孢唑林（围术期预防）","dose":"2 g 静脉滴注（体重 >120 kg 用 3 g），术前 0.5–1 h 给药，手术 >3 h 追加；术后 24 h 内停药","note":"β-内酰胺类过敏者可换克林霉素 0.6–0.9 g；MRSA 定植者加用万古霉素 1 g","renal":"肾功能不全者按说明书延长给药间期","hepatic":"遵说明书","interact":"避免与氨基糖苷类同瓶输注"},{"name":"依诺肝素（静脉血栓预防）","dose":"40 mg 皮下注射 q24h，术后 12–24 h 开始；高危（既往 VTE、肿瘤）可 40 mg q12h；预防至术后 28–35 天","note":"术前已服用华法林/DOAC 者需评估桥接或延迟手术；必要时查抗 Xa 因子","renal":"CrCl 15–30 mL/min 减为 30 mg q24h","hepatic":"严重肝病伴凝血障碍慎用","interact":"与 NSAIDs、抗血小板药合用增加出血风险"},{"name":"氨甲环酸","dose":"1 g 静脉滴注（术前 15 min 或切皮前），术后 3 h 可再给 1 g；可局部 1 g 关节腔内灌注","note":"减少围术期失血与输血需求，不增加血栓事件；有活动性血栓病史者权衡使用","renal":"CrCl 30–60 减量，<30 慎用，遵说明书","hepatic":"遵说明书","interact":"与抗凝药合用需评估出血风险"},{"name":"对乙酰氨基酚（镇痛）","dose":"0.5–1 g 口服或静脉 q6h，每日不超过 4 g（老年、肝功能异常者 ≤3 g/日）","note":"过敏者改克林霉素","renal":"eGFR <30 延长给药间期","hepatic":"肝硬化、肝功能失代偿每日 ≤2 g","interact":"与华法林长期合用可升高 INR；避免与其他含对乙酰氨基酚复方制剂叠加"},{"name":"唑来膦酸（抗骨质疏松）","dose":"5 mg 静脉滴注，每年 1 次（骨折术后急性期过后使用）","note":"术前需 eGFR ≥35 mL/min，先处理口腔问题，注意低钙血症","renal":"CrCl <35 mL/min 禁用","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加肾损伤风险"}],"nonDrug":["稳定型（AO 31-A1、Evans Ⅰ型）：股骨近端髓内钉（PFNA/InterTAN 等）为目前主流；亦可采用动力髋螺钉（DHS）","不稳定型（AO 31-A2、A3 反转子间、累及转子下）：长髓内钉或股骨近端髓内钉加强型，避免 DHS 失败","手术力争 48 h 内完成；术前纠正贫血与电解质紊乱，必要时输血使 Hb ≥80 g/L（合并心血管病可提高至 90–100 g/L）","极度衰弱、麻醉高危且不能耐受手术者，可保守治疗（牵引+卧床），但需强化压疮、肺炎与血栓预防","术后早期床旁坐起、助行器下非负重或部分负重行走，根据骨折稳定性与骨质决定负重时间"],"life":["术后 1、3、6、12 个月复查 X 线，关注内翻塌陷、螺钉切出与髓内钉远端骨折","系统抗骨质疏松治疗（钙、维生素 D、双膦酸盐或地舒单抗）+ 跌倒干预","营养支持：每日蛋白 1.2–1.5 g/kg，纠正维生素 D 缺乏","术后 1 年内避免高冲击活动，跌倒高风险患者使用辅助器具"]},"prog":"髓内钉固定后骨折愈合率 >95%，再手术率约 5%–10%（主要为内翻塌陷、螺钉切出、远端骨折）；伤后 1 年死亡率约 20%，与高龄、合并症、延迟手术与谵妄相关。早期手术与多学科共管可显著降低住院死亡率与住院日。","refs":["中华医学会骨科学分会创伤骨科学组《老年股骨转子间骨折诊疗指南》2020","《中国老年髋部骨折诊疗与管理专家共识》2017","《中国创伤骨科患者围手术期静脉血栓栓塞症预防指南》2021","NICE Hip fracture: management (CG124), 2023 update"]},{"id":"or_tibial","name":"胫腓骨骨折","aka":["胫骨干骨折","Tibial Shaft Fracture","胫骨骨折","开放性胫腓骨骨折"],"rank":3,"basic":{"define":"胫骨与/或腓骨于关节面以下至踝关节面以上区域的骨折，胫骨干因其前内侧皮下、血供差，是长骨干骨折中开放性与不愈合、感染风险最高的部位。","risk":["高能量交通伤、摩托车伤、坠落伤","开放性损伤（Gustilo 分型决定预后）","吸烟（显著降低愈合率）","糖尿病、周围血管病、营养不良","老年骨质疏松、低能量跌倒（多为胫骨平台或远端）"],"epi":"胫骨干骨折约占成人长骨骨折的 10%–15%，其中开放性骨折占 20%–30%；胫骨是长骨中开放性骨折与骨不连发生率最高的部位之一。"},"patho":"胫骨前内侧缺乏肌肉覆盖，血供主要来自胫后动脉骨膜支与滋养动脉，中下段骨折易破坏血供，导致延迟愈合与不愈合。开放性骨折时污染与软组织剥离、腓骨完整造成的力线失衡、筋膜室内压升高，共同引发感染、畸形愈合与骨筋膜室综合征。胫骨与腓骨近端骨折合并小腿肿胀需警惕骨筋膜室综合征，远端骨折易合并胫腓联合损伤。","dx":{"criteria":["外伤后小腿肿胀、疼痛、畸形、反常活动，不能负重","X 线正侧位含膝、踝关节（必要时摄股骨全长与全胫腓骨），明确骨折线、粉碎程度与腓骨受累情况","开放性骨折记录伤口部位、大小、污染程度与软组织碾挫，按 Gustilo-Anderson 分型","评估神经（腓总神经足背感觉、踝背伸）与血管（足背/胫后动脉搏动、毛细血管充盈）","评估骨筋膜室：与损伤程度不相称的剧痛、被动伸趾痛、筋膜室紧张、感觉异常","CT 适用于关节内骨折（平台、Pilon）与可疑隐匿骨折"],"workup":["小腿全长正侧位 X 线 + 膝关节/踝关节正侧位","开放性骨折取伤口深部拭子培养并记录，术前即在急诊完成清创","血管损伤疑虑时行踝肱指数（ABI）或 CTA","骨筋膜室压测定（正常 <10 mmHg，差值 <30 mmHg 提示需切开）","血常规、凝血、炎症指标；多处伤者按 ATLS 顺序评估","吸烟、糖尿病与营养状态评估以预测愈合"],"grading":"1）AO/OTA 42 型：A 简单、B 楔形、C 复杂；2）开放性骨折 Gustilo-Anderson 分型：Ⅰ型 伤口 <1 cm 清洁；Ⅱ型 伤口 >1 cm 无明显软组织损伤；ⅢA 软组织广泛撕裂但可覆盖骨折端；ⅢB 软组织缺损需皮瓣覆盖；ⅢC 合并需修复的血管损伤。3）Rüedi-Allgöwer 分型用于 Pilon 骨折，Schatzker 分型用于胫骨平台骨折。"},"ddx":[{"name":"股骨颈骨折（or_femur_neck）","point":"与本类 or_femur_neck 的鉴别点：股骨颈骨折痛点与压痛在髋部，患肢短缩外旋，局部无小腿畸形；胫腓骨骨折畸形与压痛均在小腿，常伴开放伤口或软组织损伤。"},{"name":"股骨转子间骨折（or_intertroch）","point":"与本类 or_intertroch 的鉴别点：转子间骨折以髋痛、外旋 90° 为特征，膝部可有放射痛；胫腓骨骨折踝上活动可引起局部剧痛，X 线定位直接区分。"},{"name":"骨筋膜室综合征（or_compartment）","point":"两者既是因果也需鉴别：胫腓骨骨折后出现与损伤不成比例的剧痛、被动伸趾痛、筋膜室紧张与感觉异常提示合并骨筋膜室综合征，需急症筋膜切开，而非加大镇痛。"},{"name":"小腿肌肉拉伤/腓肠肌撕裂","point":"多见于运动时突然发力，「网球腿」有明确撕裂感与压痛，X 线无骨折线，MRI 见肌肉内血肿。"}],"tx":{"drug":[{"name":"头孢呋辛（围术期/开放性骨折预防）","dose":"开放性骨折急诊 1.5 g 静脉滴注，之后 1.5 g q8h 至 24 h（清除创面后按医嘱）；闭合性骨折围术期同剂量、术后 24 h 内停药","note":"Ⅲ型开放伤联合氨基糖苷类（如阿米卡星），粪便污染或厌氧菌污染加用甲硝唑；结合当地创伤抗菌药物规范","renal":"按 eGFR 调整剂量，遵说明书","hepatic":"遵说明书","interact":"与氨基糖苷类联用需监测肾功能"},{"name":"氨甲环酸","dose":"1 g 静脉滴注（伤后 3 h 内），手术中或术后 3 h 内可追加 1 g；局部 1–2 g 术中浸泡","note":"减少围术期出血；创伤患者伤后 3 h 内使用获益，超过 3 h 使用可能增加死亡风险，应避免","renal":"CrCl 30–60 减量，<30 慎用","hepatic":"遵说明书","interact":"与抗凝药、抗血小板药合用需评估出血"},{"name":"依诺肝素（静脉血栓预防）","dose":"40 mg 皮下注射 qd，入院即开始（除外活动性出血），术后按医嘱恢复；预防持续至术后 28–35 天或至恢复负重","note":"胫腓骨骨折（尤其制动、肿胀明显时）为 VTE 高危","renal":"CrCl 15–30 mL/min 减量至 30 mg qd","hepatic":"严重肝病伴凝血障碍慎用","interact":"与 NSAIDs 合用增加出血"},{"name":"帕瑞昔布钠（镇痛）","dose":"40 mg 静脉注射 q12h，≤3 天；之后口服塞来昔布或对乙酰氨基酚","note":"警惕掩盖骨筋膜室综合征","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药合用增加出血与消化道损伤"},{"name":"依诺肝素（VTE 预防）","dose":"40 mg 皮下 qd，入院即开始，术后至 28–35 天","note":"VTE 高危，制动期尤需","renal":"CrCl 15–30 减至 30 mg qd","hepatic":"凝血障碍慎用","interact":"与 NSAIDs 合用易出血"}],"nonDrug":["髓内钉为胫骨干骨折金标准，扩髓可促血运与愈合；开放伤充分清创后可内固定","外固定架：Gustilo ⅢC、严重污染、骨缺损或软组织差者先行跨关节外固定，二期转内固定","钢板螺钉：适用于靠近干骺端的骨折与髓内钉入点受限者；开放伤污染重者避免一期内固定","开放骨折及早（争取 6–8 h，不晚于 24 h）清创、固定与创面处理（VSD），必要时分期重建","腓骨固定：胫骨远端/平台骨折与下胫腓损伤需恢复长度与稳定","合并骨筋膜室综合征应立即（1–2 h 内）筋膜切开，不等影像","骨不连（4–6 月无愈合）：查明原因，考虑动力化、扩髓植骨或 Ilizarov 骨搬移"],"life":["术后 2–4 周、6–8 周、3 个月、6 个月复查 X 线；负重时间由骨折稳定性决定（髓内钉固定且稳定者可早期部分负重）","戒烟（吸烟者骨不连风险约翻倍），保证蛋白与维生素 D 摄入","开放性骨折创面护理、伤口分级随访；术后感染表现为持续疼痛与渗液需及时复诊","指导踝关节与膝关节功能锻炼，预防关节僵硬；康复期避免过早跑跳"]},"prog":"闭合性胫骨干骨折髓内钉治疗愈合率约 90%–95%，骨不连率 5%–10%；开放性骨折感染率随 Gustilo 分型升高（ⅢB/ⅢC 可达 10%–25%），深部感染需清创、去内固定与骨重建。Ⅰ型开放性骨折愈合后功能多可恢复良好，严重软组织损伤与血管损伤者可能遗留慢性疼痛或截肢。","refs":["中华医学会骨科学分会创伤骨科学组《胫骨远端骨折诊疗指南》2023","《中国开放性骨折诊断与治疗专家共识》2019","《中国创伤骨科患者围手术期静脉血栓栓塞症预防指南》2021","OTA/AO Principles of Fracture Management, 2018"]}]},{"id":"spine","name":"脊柱","rank":2,"summary":"脊柱疾病的共同主线是神经结构受压或力学不稳：以病史+查体定位、影像相关性为诊断核心，多数腰椎退行性病变先保守 4–12 周，出现进行性神经功能损害、马尾综合征或明确压迫对应症状时才有手术指征；老年压缩骨折以疼痛为主，微创强化仅适用于保守无效的特定患者。","compare":[{"diseaseId":"or_ldh","dx":"腰痛伴单侧下肢放射痛，直腿抬高试验阳性，沿神经根分布区感觉运动异常，MRI 见椎间盘突出压迫神经根","key":"症状呈单侧皮节/肌节定位，多见于 L4–5、L5–S1，常随休息与时间缓解"},{"diseaseId":"or_stenosis","dx":"中老年行走数分钟后下肢酸胀麻木、弯腰蹲坐可缓解（间歇性跛行），MRI/CT 示椎管矢状径显著减小、黄韧带肥厚","key":"症状与体位相关、多为双侧广泛分布，神经源性跛行与血管源性跛行需鉴别"},{"diseaseId":"or_ovcf","dx":"老年人轻微外伤或无明显外伤后突发腰背剧痛、翻身困难，X 线示椎体楔形变，MRI 压脂像呈高信号提示新鲜骨折","key":"局部棘突叩击痛明显、无神经根放射痛，影像为新近骨折而非单纯退变"}],"diseases":[{"id":"or_ldh","name":"腰椎间盘突出症","aka":["Lumbar Disc Herniation","LDH","腰椎间盘突出","腰突症"],"rank":1,"basic":{"define":"腰椎间盘髓核组织局限性突出超出椎间隙后缘，压迫或刺激相应神经根/马尾，产生根性症状和体征的临床综合征。","risk":["20–50 岁长期弯腰搬重物、久坐职业","肥胖、缺乏运动导致腰背肌薄弱","吸烟（椎间盘营养障碍）","震动暴露（职业司机）","家族史与遗传易感"],"epi":"腰椎间盘突出症占腰痛就诊患者的约 10%–15%；最常见节段为 L4–5 与 L5–S1（合计约 90%），好发于 30–50 岁，男女之比约 2:1。"},"patho":"椎间盘退变后纤维环发生裂隙，髓核在轴向压力与屈曲负荷下向后外侧突出，最常压迫同侧下位神经根（旁中央型）；中央型巨大突出可压迫马尾。局部还可产生炎性介质（TNF-α、IL-6、磷脂酶 A2）导致神经根化学性炎症，这解释了部分患者影像突出与症状不平行。突出物可自发吸收，尤其是游离型。","dx":{"criteria":["腰痛伴单侧下肢放射痛，沿神经根分布区（皮节）分布，咳嗽、打喷嚏、久坐时加重","神经定位体征：L4 根（L3–4 突出）——股四头肌肌力下降、膝反射减弱、小腿内侧感觉减退；L5 根（L4–5）——足背伸/趾伸肌力下降、小腿外侧与足背感觉减退、胫前肌力弱；S1 根（L5–S1）——足跖屈肌力下降、跟腱反射减弱、足外侧感觉减退","直腿抬高试验（SLR）<60°，股神经牵拉试验（L2–L4）阳性","影像与临床定位一致方可诊断：MRI 示突出物压迫相应神经根","马尾综合征警示：鞍区麻木、大小便功能障碍、双下肢进行性无力，需急诊 MRI 与手术"],"workup":["腰椎正侧位/动力位 X 线：评估曲度、椎间隙高度、滑脱与不稳","腰椎 MRI 平扫（不含增强）：首选，评估突出类型（膨出/突出/脱出/游离）、位置与神经根受压","CT：钙化型突出、骨性椎管狭窄或 MRI 禁忌时","肌电图/神经传导：症状与影像不符、多节段病变或需排除周围神经病变（糖尿病周围神经病、腓总神经卡压）时","康复前期评估：核心肌力、直腿抬高与功能评分（ODI、VAS）"],"grading":"临床分型：①膨出型（Bulging）；②突出型（Protrusion，基底宽大于突出高度）；③脱出型（Extrusion）；④游离型（Sequestration）；⑤许莫氏结节（Schmorl 结节，多为无症状型）。按位置分为后外侧型（旁中央型）、椎间孔型与极外侧型、中央型。"},"ddx":[{"name":"腰椎管狭窄症（or_stenosis）","point":"与本类 or_stenosis 的鉴别点：突出症表现为单侧根性放射痛，SLR 阳性，与其皮节对应；退变性椎管狭窄以双侧神经源性间歇性跛行（弯腰缓解）为主，SLR 多为阴性，影像为椎管整体狭窄而非单纯椎间盘突出。"},{"name":"骨质疏松性椎体压缩骨折（or_ovcf）","point":"与本类 or_ovcf 的鉴别点：OVCF 为局部棘突叩击痛、体位性疼痛（翻身起坐困难），无放射痛与 SLR 阳性，MRI 压脂呈高信号；椎间盘突出为放射性痛、跟性体征。"},{"name":"骨质疏松性椎体压缩骨折合并骨赘/椎管狭窄","point":"老年患者两者常并存：急性损伤后突发疼痛并伴下肢放射痛时，应注意是否合并神经根受压，不宜将症状全部归因于陈旧压缩骨折。"},{"name":"血管源性跛行（下肢动脉硬化闭塞症）","point":"行走诱发，但站立即缓解（而非弯腰/坐下），ABI 降低、足背动脉搏动减弱，无根性感觉障碍。"},{"name":"梨状肌综合征/髋关节病变","point":"臀部局限性疼痛、梨状肌紧张试验阳性；髋关节病变为腹股沟区痛伴内旋受限；均无相应皮节感觉改变与 MRI 神经根压迫。"}],"tx":{"drug":[{"name":"塞来昔布（NSAIDs，急性期）","dose":"200 mg 口服 bid，疗程 1–2 周；无效或不耐受换用其他 NSAIDs","note":"非急性期不长用；高危加 PPI","renal":"eGFR <30 禁用；用药期间监测肾功能","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、抗血小板药联用增加消化道出血风险"},{"name":"甲钴胺（神经营养）","dose":"0.5 mg 口服 tid，或 0.5 mg 肌内注射 qd–qod；疗程 4–8 周","note":"辅助治疗，缺乏高质量证据但临床常用；症状缓解后可停用","renal":"遵说明书","hepatic":"遵说明书","interact":"与氯霉素等骨髓抑制药物合用需谨慎"},{"name":"甘露醇/激素（急性严重根性痛）","dose":"20% 甘露醇 250 mL 静脉滴注 q8–q12h，短程（≤3 天）；或地塞米松 5–10 mg 静脉滴注 qd，短程","note":"短程，用于急性根性痛伴水肿时","renal":"甘露醇在 eGFR 降低者慎用；激素需监测血糖","hepatic":"遵说明书","interact":"甘露醇与肾毒性药物联用增加肾损害风险"},{"name":"对乙酰氨基酚（镇痛）","dose":"0.5–1 g 口服 q6h，每日不超过 3–4 g","note":"与 NSAIDs 交替使用可减少后者总量；用于胃病或肾功能不全者首选的单纯镇痛方案之一","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与其他含对乙酰氨基酚复方制剂叠加"},{"name":"普瑞巴林/加巴喷丁（神经病理性痛）","dose":"普瑞巴林 75 mg qn 起，逐渐加至 75 mg bid（最大 300 mg/日）；加巴喷丁从 300 mg qn 起，按耐受性滴定","note":"存在神经病理性疼痛特征（烧灼、电击样、夜间痛）者考虑，按体重与肾功能滴定","renal":"按 CrCl 调整（普瑞巴林 CrCl 30–60 为 25–50 mg bid，<30 为 25 mg qd 或隔日）","hepatic":"重度肝功能不全慎用","interact":"与阿片类、苯二氮䓬类合用增加呼吸抑制与嗜睡"},{"name":"头孢唑林+依诺肝素（手术患者预防）","dose":"手术：头孢唑林 1–2 g 静注术前 0.5–1 h 单次（术后 24 h 内停），依诺肝素 40 mg 皮下 qd 术后 12–24 h 起至下床活动","note":"仅限减压手术；保守者早期活动、踝泵","renal":"CrCl 15–30 mL/min 减为 30 mg qd","hepatic":"显著凝血障碍者慎用","interact":"与 NSAIDs、抗血小板药合用增加出血"}],"nonDrug":["保守治疗为首选（约 80%–90% 可缓解）：4–6 周内避免弯腰负重，短程卧床（≤2–3 天）后尽早活动","物理治疗：核心稳定训练、神经根滑动训练、牵引与手法治疗（需专业评估，急性期慎牵引）","硬膜外或椎间孔阻滞/选择性神经根阻滞（影像引导）：用于持续根性痛、药物控制不佳者","手术指征：保守 6–12 周无效且疼痛影响生活；进行性神经功能损害（肌力下降）；马尾综合征（急诊）；椎间盘突出伴明显运动障碍","术式：椎板间开窗髓核摘除（后路显微/内镜）、椎间孔镜或椎间盘镜微创摘除；伴不稳或滑脱者考虑融合","青少年与运动员行椎间盘突出：内镜减压优先以保留运动节段"],"life":["避免久坐（每 30–45 min 起身）、正确搬物姿势（屈膝下蹲、物贴近身体）","规律运动：游泳、核心肌群训练、步行；避免急性期弯腰负重与旋转负荷","体重控制（BMI <24）、戒烟","术后 6 周内避免弯腰搬重物与久坐驾驶；3 个月内渐进恢复运动","随诊：保守治疗 4 周复评；术后 2 周、6 周、3 个月、6 个月复查"]},"prog":"保守治疗 6 周内约 70%–80% 症状明显缓解，游离型突出物可自发吸收；术后满意率约 85%–95%，椎间盘再突出率约 5%–15%，需二次手术约 5%。进行性运动障碍与马尾综合征患者如延误手术，可能遗留永久性神经功能缺损。","refs":["中华医学会骨科学分会脊柱外科学组《腰椎间盘突出症诊疗指南》2020","《中国腰椎间盘突出症的诊断和康复治疗指南》2022","中国康复医学会《腰椎间盘突出症临床诊疗护理指南》2019","NASS Clinical Guidelines: Diagnosis and Treatment of Lumbar Disc Herniation with Radiculopathy, 2012（2023 更新）"]},{"id":"or_stenosis","name":"腰椎管狭窄症","aka":["腰椎椎管狭窄","Lumbar Spinal Stenosis","LSS","退变性椎管狭窄"],"rank":2,"basic":{"define":"因椎间盘退变、黄韧带肥厚、小关节增生或椎体滑脱等原因致腰椎中央椎管或神经根管容量减小，压迫马尾或神经根，引起间歇性跛行与神经源性症状的临床综合征。","risk":["年龄 >50 岁（退变为主要病因）","长期重体力劳动与振动暴露","腰椎滑脱、后凸畸形","肥胖、骨质疏松","先天性椎管发育狭小（Trevor 病/侏儒症等少见）"],"epi":"在 65 岁以上人群中有症状腰椎管狭窄的患病率约 10%，是老年腰椎手术的首位原因；影像学椎管狭窄（无或轻症状）在同龄人群中可达 20%–30%。"},"patho":"椎间盘退变与塌陷使椎间隙变窄，黄韧带在退变基础上增厚（可超过 5 mm）并向后膨出，小关节与关节囊增生肥厚，共同导致椎管矢状径与横径减小。行走时下肢肌肉需氧增加、神经根血供相对不足，加重充血水肿，产生假性间歇性跛行；弯腰或坐位时椎管横截面积增加约 10%–20%，症状因此缓解。退变性滑脱与侧隐窝狭窄可同时存在，导致双侧症状。","dx":{"criteria":["神经源性间歇性跛行：行走一定距离（通常数十至数百米）后出现双下肢酸胀、麻木、无力，弯腰、蹲坐或休息数分钟可缓解；骑行、上楼梯时不明显","症状常为双侧或广泛，可伴会阴区麻木；查体：腰椎过伸试验可诱发症状，通常无明显神经根定位体征；也可合并单侧根性痛","影像学与临床一致：CT/MRI 示中央椎管前后径 <10 mm（相对狭窄）或 <5 mm（绝对狭窄），侧隐窝 <3 mm 提示神经根管狭窄；黄韧带 >5 mm 提示肥厚","排除血管源性跛行、周围神经病变与髋关节病变","评估脊柱力线：动力位 X 线判断退变性滑脱及其稳定性（滑脱 >2 mm 或 >10° 提示不稳定）"],"workup":["腰椎正侧位与过伸过屈位 X 线：曲度、椎间隙、滑脱（Meyerding 分级）与关节突退变","腰椎 MRI：明确椎管狭窄节段、马尾受压程度与伴发的椎间盘突出、囊肿","CT 与三维重建：骨性狭窄、关节突增生与钙化","肌电图/神经传导：识别合并周围神经病变（糖尿病、腓总神经卡压）","踝肱指数（ABI）与下肢动脉超声：鉴别血管源性跛行","功能性评估：步行距离（平地持续行走时间）、ODI 与 Zurich 跛行量表"],"grading":"按解剖部位分：中央型（椎管中央狭窄）、侧隐窝型（侧隐窝 <3 mm）、椎间孔型。Schizas 分级（MRI T2/T1 矢状位）：A 级 马尾神经根仍可分辨；B 级 根丝聚集但仍可见部分脑脊液；C 级 根丝聚集、脑脊液信号仅剩一薄层（无灰区称 C1，有灰区 C2）；D 级 整个椎管被根丝填充无脑脊液信号（完全阻滞）。退变性滑脱按 Meyerding 分级（Ⅰ–Ⅳ度，Ⅴ度 完全滑脱）。"},"ddx":[{"name":"腰椎间盘突出症（or_ldh）","point":"与本类 or_ldh 的鉴别点：椎间盘突出以单侧根性痛为主，SLR 阳性，有明确皮节定位；椎管狭窄以双侧间歇性跛行为主，SLR 多阴性，MRI 为整体椎管狭窄与黄韧带肥厚。"},{"name":"骨质疏松性椎体压缩骨折（or_ovcf）","point":"与本类 or_ovcf 的鉴别点：OVCF 突出表现为急性局部叩痛、体位改变时剧痛，影像为新近骨折；椎管狭窄为慢性进行性跛行，影像为椎管容量减小而非椎体形态崩解。但老年患者可因椎体压缩后凸而加重继发狭窄。"},{"name":"血管源性间歇性跛行","point":"站立即可缓解（而非弯腰），足背动脉搏动减弱、ABI <0.9，跛行距离固定不受姿势影响，影像学椎管无明显狭窄。"},{"name":"糖尿病周围神经病变","point":"对称性袜套样感觉减退、神经传导异常，休息时也有症状，与行走姿势无关。"}],"tx":{"drug":[{"name":"塞来昔布（镇痛-消炎）","dose":"200 mg 口服 qd–bid，间歇使用，疗程 2–4 周","note":"老年人与消化道高危者加 PPI","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、抗血小板药联用增加消化道出血"},{"name":"洛索洛芬钠（NSAIDs）","dose":"60 mg 口服 tid，餐后服用，疗程 2–4 周，症状缓解后减停","note":"用于继发神经根痛/腰痛","renal":"eGFR <30 禁用；eGFR 30–60 慎用并监测肾功能","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、抗血小板药合用增加出血；避免与其他 NSAIDs 叠加"},{"name":"普瑞巴林（神经病理性痛）","dose":"从 75 mg qn 起，按耐受逐渐加量至 75 mg bid（最大 300 mg/日）","note":"改善夜间痛与烧灼样感觉异常；有头晕、嗜睡与跌倒风险，老年患者低剂量起","renal":"按 CrCl 调整剂量","hepatic":"重度肝功能不全慎用","interact":"与阿片类、苯二氮䓬类合用增加呼吸抑制"},{"name":"依替膦酸二钠/降钙素（辅助）","dose":"鲑鱼降钙素 50 IU 皮下或肌内注射 qd，或 200 IU 鼻喷 qd；疗程 ≤4–8 周","note":"部分患者短期缓解神经源性跛行与骨痛（证据等级较低），疗程不宜过长","renal":"遵说明书","hepatic":"遵说明书","interact":"与双膦酸盐伍用需间隔给药"},{"name":"甲钴胺（神经营养）","dose":"0.5 mg 口服 tid 或 0.5 mg 肌内注射 qod，疗程 4–8 周","note":"个体差异大，对症辅助治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"头孢唑林+依诺肝素（手术患者预防）","dose":"头孢唑林 1–2 g 静注术前 0.5–1 h 单次；依诺肝素 40 mg 皮下 qd 术后起","note":"仅减压/融合术者；保守者步行训练","renal":"CrCl 15–30 mL/min 减为 30 mg qd","hepatic":"显著凝血障碍慎用","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["有症状者先保守 3–6 个月：避免长时间站立与后伸腰，腹带/腰围短程使用，症状明显者短程卧床","个体化康复：腰椎屈曲运动、核心训练、步行（可先使用助行器）、有监督的物理治疗（牵引与手法需谨慎，避免加重后伸）","硬膜外激素注射或选择性神经根阻滞：用于保守治疗效果不佳者，可短期缓解","手术指征：保守 3–6 个月无效、跛行距离 <100–200 m 影响生活、进行性神经功能损害、马尾综合征","术式：单纯减压（椎板切除、椎间孔扩大）适用于无滑脱的退变性狭窄；合并退变性滑脱（>2 mm）或需广泛切除时，行减压+融合（后外侧融合、PLIF/TLIF 或微创内固定）","老年或不能耐受开放手术者：微创（内镜/通道下）减压可作为备选，需结合减压范围与脊柱稳定性评估","术后早期康复，避免长期卧床与去适应"],"life":["体重管理（减轻脊柱负荷）、戒烟","规律低冲击有氧运动（游泳、骑车）结合核心肌群训练","家庭环境防跌倒（照明、扶手、地面防滑）","保守治疗每 4–8 周评估症状与步行距离；术后 1、3、6、12 个月复查影像与功能"]},"prog":"多数患者症状轻度进展，约 30%–40% 在 3–5 年内出现症状加重；中重度狭窄保守治疗满意率约 20%，手术减压 5 年满意率约 70%–80%。合并退变性滑脱且未融合者术后再手术率约 10%–15%（主要为滑脱进展与相邻节段退变）。","refs":["中华医学会骨科学分会脊柱外科学组《退变性腰椎侧凸诊治专家共识》2018","《腰椎管狭窄症诊疗专家共识》2021","《中国康复医学会腰椎管狭窄症康复治疗指南》2022","NASS Clinical Guidelines: Diagnosis and Treatment of Degenerative Lumbar Spinal Stenosis, 2011（更新版）"]},{"id":"or_ovcf","name":"骨质疏松性椎体压缩骨折","aka":["OVCF","Osteoporotic Vertebral Compression Fracture","椎体压缩骨折","脆性骨折"],"rank":3,"basic":{"define":"在骨质疏松基础上、由轻微外伤（低能量跌倒、搬轻物、咳嗽）或无明确外伤引起的椎体压缩性骨折，属脆性骨折。","risk":["绝经后女性、年龄 >65 岁男性","骨密度 T 值 ≤ −2.5 或既往脆性骨折史","长期糖皮质激素（≥3 个月，剂量 ≥5 mg/d 泼尼松当量）","吸烟、过量饮酒、低体重（BMI <18.5）","糖尿病、类风湿关节炎、甲状腺功能亢进等继发因素"],"epi":"我国 50 岁以上人群椎体压缩骨折的患病率约 15%，女性高于男性；约 2/3 的椎体压缩骨折为隐匿性（无明确外伤史、未就诊），患者发生再次骨折的风险增加 3–5 倍。"},"patho":"骨质疏松使椎体骨小梁微结构破坏（水平骨小梁减少、垂直骨小梁变细），在轴向压缩与屈曲负荷下椎体前缘塌陷呈楔形，后壁完整者少见神经损伤。骨折后局部微环境血肿与炎症导致持续疼痛与活动受限，长期卧床又加重骨丢失与肌少症，形成「骨折—制动—再骨折」的恶性循环。","dx":{"criteria":["老年人轻微外伤或无外伤后突发腰背痛，翻身、起坐、站立时加重，卧床可缓解","查体：骨折椎棘突明显叩击痛与压痛，脊柱后凸畸形，无神经根放射症状","X 线正侧位：椎体前缘高度丢失 ≥20%–25% 或椎体高度下降 >4 mm 判定为压缩骨折（Genant 半定量分级）","MRI（T1、T2 压脂或 STIR）：新鲜骨折呈高信号；是区分新鲜/陈旧、决定 PVP/PKP 的关键；X 线与 MRI 不符时加做 CT","排除病理性骨折（肿瘤、感染）：MRI 见椎弓根或椎体后部破坏、软组织肿块、液体信号，或反复同一部位骨折","所有患者完成骨密度检测（DXA，腰椎与髋部）及继发性骨质疏松筛查"],"workup":["胸腰椎正侧位 X 线与骨密度检测（DXA）","MRI 全脊柱（T1、T2、STIR）：判断新旧、是否多发、有无脊髓/神经压迫","CT：评估后壁完整性与椎弓根（穿刺路径）","实验室：血钙、磷、碱性磷酸酶、25-OH 维生素 D、PTH、甲状腺功能、肝肾功能、M 蛋白与肿瘤标志物（排除骨髓瘤/转移瘤）","疼痛与功能评估（VAS、ODI）、跌倒与衰弱风险评估"],"grading":"Genant 半定量分型：0 级 高度正常；1 级（轻度）椎体高度下降 20%–25%；2 级（中度）25%–40%；3 级（重度）>40%。按形态分：楔形、双凹形、压缩形。按时间分：急性（≤4–6 周）、亚急性、陈旧性。PVP/PKP 适应证：MRI 证实的新鲜或亚急性骨折（保守治疗 1–3 周疼痛无缓解）、椎体后壁相对完整、无明显神经压迫、压缩程度一般 <70%（需结合个体化）。"},"ddx":[{"name":"腰椎间盘突出症（or_ldh）","point":"与本类 or_ldh 的鉴别点：椎间盘突出表现为下肢放射痛与 SLR 阳性；OVCF 疼痛局限于骨折椎体，为体位性剧痛，无皮节定位体征，MRI 为椎体水肿而非椎间盘压迫神经根。"},{"name":"腰椎管狭窄症（or_stenosis）","point":"与本类 or_stenosis 的鉴别点：OVCF 起病急、有明确诱因、局部叩痛明显；椎管狭窄为慢性进行性跛行，无急性局部叩痛，影像为椎管容量减小。"},{"name":"病理性骨折（转移瘤/多发性骨髓瘤）","point":"静息痛、夜间痛突出，MRI 或 CT 示椎弓根破坏（「猫头鹰眼征」）、软组织肿块；需肿瘤史、M 蛋白与穿刺活检，PVP 前必须先排除。"},{"name":"化脓性脊柱炎","point":"发热、局部压痛、白细胞与 CRP/ESR 显著升高，MRI 见椎间隙与相邻椎体异常信号（椎间盘受累），血培养阳性。"}],"tx":{"drug":[{"name":"头孢唑林（PVP/PKP 预防）","dose":"1–2 g 静滴，术前 0.5–1 h 单次","note":"仅穿刺/成形术；过敏改克林霉素","renal":"按 eGFR 调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"对乙酰氨基酚（急性期镇痛）","dose":"0.5–1 g 口服 q6h，每日 ≤3 g（老年）","note":"急性期多模式镇痛，尽早用支具","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与复方制剂叠加"},{"name":"地舒单抗（抗骨质疏松）","dose":"60 mg 皮下 q6m；同时补钙与维生素 D","note":"强效抗骨吸收药；不可随意停药，需有后续方案","renal":"CrCl <30 慎用（低钙血症风险），监测血钙","hepatic":"遵说明书","interact":"与其他抗骨吸收药不同用"},{"name":"唑来膦酸（抗骨质疏松）","dose":"5 mg 静滴 q12m（先纠正低钙与维生素 D）","note":"术前 eGFR ≥35；注意颌骨坏死","renal":"CrCl <35 mL/min 禁用","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加肾损伤风险"},{"name":"碳酸钙 D3 + 活性维生素 D","dose":"元素钙 600 mg bid（总 1000–1200 mg/日）+ 维生素 D3 800–1200 IU/日","note":"基础用药，复查血钙与 25-OH 维生素 D","renal":"CKD 4–5 期改用骨化三醇，监测血钙磷","hepatic":"遵说明书","interact":"与喹诺酮类、四环素类间隔 ≥2 h"},{"name":"降钙素（辅助）","dose":"鲑鱼降钙素 50 IU 皮下/肌注 qd 或鼻喷 200 IU qd，疗程 ≤4 周","note":"短程缓解急性期疼痛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"依诺肝素（VTE 预防）","dose":"40 mg 皮下 qd，制动期间用，恢复下地后停","note":"卧床者","renal":"CrCl 15–30 减至 30 mg qd","hepatic":"凝血障碍慎用","interact":"与 NSAIDs 合用易出血"}],"nonDrug":["保守治疗（无神经症状、可耐受）：镇痛 + 支具（胸腰骶支具）保护 6–8 周，避免长期卧床","PVP/PKP 适应证：MRI 证实的新鲜/亚急性骨折、剧烈疼痛经 1–3 周保守无效、后壁基本完整、无严重神经压迫；禁忌：感染、凝血障碍、不能俯卧、后壁破裂伴椎管内骨块压迫；高度丢失 <1/3 不作排除标准","PKP 可部分恢复椎体高度、减少骨水泥渗漏，骨质疏松严重或球囊扩张后高度恢复不佳者可选 PVP","神经压迫或椎体后壁破裂致椎管内占位者考虑后路减压+椎体强化/内固定","跌倒预防：平衡训练、视力矫正、居家改造；纳入骨折联络服务（FLS）"],"life":["抗骨质疏松治疗至少 3–5 年，每年复查骨密度；PVP/PKP 术后仍需抗骨质疏松，否则相邻椎体再骨折风险升高","补充蛋白（1.0–1.2 g/kg/d）与维生素 D，戒烟限酒","负重运动（步行、快走）与抗阻训练，防跌倒训练","术后 1 个月、3 个月复查 X 线；新发背痛及时复查 MRI"]},"prog":"保守治疗多数疼痛在 4–8 周缓解，但椎体进一步塌陷与后凸进展常见；PVP/PKP 术后 24–48 h 疼痛多在 1–3 天内显著缓解（有效率为 70%–90%），骨水泥渗漏率约 5%–15%（多为无症状）。首次发生椎体骨折后 1–2 年内再骨折风险增加 3–5 倍，规范抗骨质疏松治疗可降低约 50%–70%。","refs":["中华医学会骨质疏松和骨矿盐疾病分会《原发性骨质疏松症诊疗指南（2022）》","《骨质疏松性椎体压缩骨折诊治专家共识》2022","《中国骨质疏松性骨折诊疗指南》2018","《中国疼痛科经皮椎体成形术操作规范（2023）》","Endocrine Society & ASBMR Osteoporotic Vertebral Fracture / Vertebroplasty Consensus, 2020"]}]},{"id":"joint","name":"关节","rank":3,"summary":"关节疾病的处置分水岭是「炎症」与「感染」：退行性骨关节炎以阶梯化保守治疗和终末期关节置换为主，而化脓性关节炎必须早期穿刺确诊、48 h 内关节冲洗引流并足疗程全身抗菌治疗，诊断延误直接影响关节功能甚至关节存留。","compare":[{"diseaseId":"or_knee_oa","dx":"中老年负重活动后膝痛、上下楼梯与久蹲起立加重，晨僵 <30 min；X 线见关节间隙非对称变窄、骨赘、软骨下骨硬化","key":"慢性进行性、无全身炎症表现，ESR/CRP 正常，关节液为黏稠、白细胞计数低"},{"diseaseId":"or_septic_arthritis","dx":"急性关节红、肿、热、剧痛伴活动受限，常伴发热或全身感染灶；关节液混浊、白细胞常 >50×10⁹/L、中性粒细胞比例高，涂片/培养阳性","key":"起病数小时至数天、全身炎症反应 + 关节液白细胞极高度升高，须即刻关节穿刺及冲洗引流"}],"diseases":[{"id":"or_knee_oa","name":"膝骨关节炎（膝关节骨性关节炎）","aka":["Knee Osteoarthritis","KOA","膝关节骨关节炎","退行性膝关节病"],"rank":1,"basic":{"define":"以关节软骨进行性退变、软骨下骨重塑与骨质增生为特征的慢性退变性关节病，主要表现为负重活动相关关节痛、短暂晨僵与功能受限。","risk":["年龄 >50 岁、女性绝经后","BMI ≥24 kg/m²（肥胖是最强可调控因素）","既往膝关节外伤（半月板、交叉韧带、骨折）","长期蹲跪、重体力劳动与运动过度","遗传与下肢力线异常（O 型腿/膝内翻）"],"epi":"我国 50 岁以上人群膝关节骨关节炎的患病率约 8%，60 岁以上超过 10%，女性约为男性的 2 倍；是老年人疼痛与残疾的主要原因之一。"},"patho":"机械负荷与炎症介质共同作用于软骨细胞，分解代谢（MMP-13、ADAMTS）超过合成代谢，软骨基质丢失、软骨下骨硬化与骨髓水肿、半月板退变撕裂，关节囊与滑膜慢性低度炎症。力线异常（内翻）使内侧间室负荷集中，造成非对称性狭窄；游离体与滑膜皱襞可诱发机械症状与急性积液。","dx":{"criteria":["关节痛：近 1 个月内反复膝痛，负重活动或上下楼梯加重，休息可缓解","晨僵 ≤30 min，活动时骨摩擦音（感），关节肿胀或积液","年龄 ≥50 岁，膝关节活动时骨性膨大，无局部热感","X 线：关节间隙非对称性变窄（以内侧多见）、骨赘形成、软骨下骨硬化与囊性变","典型者不必依赖影像即可临床诊断；影像严重程度与症状常不平行"],"workup":["双膝负重位（站立）正侧位 X 线与髌骨轴位片，必要时下肢全长片评估力线","MRI：用于疑似半月板/韧带损伤、骨髓水肿、囊肿及排除其他病（不作为常规）","关节穿刺：渗出明显或需与化脓性关节炎、痛风鉴别时，查细胞数、晶体与培养","炎症指标（ESR、CRP）正常支持退变性诊断；升高需排查炎性关节病或感染","功能评估：WOMAC、VAS 与步行能力"],"grading":"Kellgren-Lawrence（K-L）分级：0 级 正常；Ⅰ级 可疑骨赘；Ⅱ级 明确骨赘、关节间隙可疑变窄；Ⅲ级 关节间隙明显变窄伴骨赘与硬化；Ⅳ级 关节间隙消失、严重骨质增生与畸形。"},"ddx":[{"name":"化脓性关节炎（or_septic_arthritis）","point":"与本类 or_septic_arthritis 的鉴别点：膝 OA 为慢性负重痛、无全身炎症、ESR/CRP 多正常、关节液黏稠且白细胞低；化脓性关节炎急性起病、关节红热剧痛伴发热、关节液白细胞通常 >50×10⁹/L，需紧急穿刺与冲洗。"},{"name":"痛风性关节炎","point":"单关节突发红肿热痛、常夜间发作，第一跖趾关节多见；关节液见针状负双折射尿酸盐结晶，血尿酸可正常。"},{"name":"类风湿关节炎","point":"对称性小关节与腕、MCP、PIP 受累，晨僵 >1 h，RF/抗 CCP 阳性，X 线早期为边缘侵蚀而非以骨赘为主。"}],"tx":{"drug":[{"name":"塞来昔布（NSAIDs）","dose":"200 mg 口服 qd–bid，按需间歇使用；可外敷氟比洛芬凝胶贴膏/diclofenac 凝胶","note":"短期按需用于疼痛急性期；老年与心血管高危者用最低有效剂量、最短疗程，并加用 PPI","renal":"eGFR <30 禁用；eGFR 30–60 慎用并监测肾功能","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、抗血小板药联用增加消化道出血；与 ACEI/ARB、利尿剂合用增加肾损害"},{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日 ≤3 g（老年）；与 NSAIDs 交替","note":"NSAIDs 有禁忌或不耐受时的主要镇痛选择","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与其他含对乙酰氨基酚复方制剂叠加"},{"name":"氨基葡萄糖/硫酸软骨素","dose":"硫酸氨基葡萄糖 750 mg 口服 bid，或 500 mg tid，疗程 3–6 个月","note":"部分指南建议性推荐用于疼痛缓解，个体反应差异大，不用于疼痛明显者替代 NSAIDs","renal":"遵说明书","hepatic":"遵说明书","interact":"与华法林合用时监测 INR"},{"name":"关节腔注射玻璃酸钠","dose":"2–2.5 mL 关节腔内注射，每周 1 次，连续 3–5 次为一个疗程（不同制剂按说明书）","note":"用于 NSAIDs 效果不佳的中度 OA；严格无菌操作，注射后 48 h 内避免剧烈活动","renal":"遵说明书","hepatic":"遵说明书","interact":"无特殊"},{"name":"糖皮质激素（关节腔注射）","dose":"复方倍他米松 1 mL（或曲安奈德 40 mg）关节腔内注射，同一关节每年不超过 3–4 次且间隔 ≥3 个月","note":"急性积液、疼痛剧烈时短期缓解；注意感染（禁忌用于怀疑感染时）、软骨损伤与高血糖","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道溃疡风险"},{"name":"头孢唑林（置换围术期预防）+依诺肝素","dose":"头孢唑林 1–2 g 静注术前 0.5–1 h 单次，术后 24 h 内停；依诺肝素 40 mg 皮下 qd，术后 12–24 h 起至术后 14 天（高危 28–35 天）","note":"仅限单髁/全膝置换等手术；保守者早期下地、踝泵","renal":"CrCl 15–30 mL/min 减为 30 mg qd","hepatic":"显著凝血障碍慎用","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["所有患者均接受基础保守治疗：健康教育、体重管理（BMI 降至 <24 可显著减痛）、股四头肌与臀肌力量训练、低冲击有氧运动（游泳、骑车）","辅助器具：外侧（内翻膝）支具、手杖、减震鞋垫；物理治疗（热疗、经皮电刺激）","关节镜清理：不推荐用于单纯骨关节炎；仅适用于明确机械症状（交锁、游离体）且其他治疗无效者","胫骨高位截骨（HTO）：年龄 <60–65 岁、内侧室孤立性 OA、膝内翻、活动量大、膝关节屈曲 >90° 且对侧间室正常者","单髁置换：年龄 >60 岁、内侧室孤立病变、前后交叉韧带功能良好、力线畸形 <15° 者可选择","全膝关节置换（TKA）：K-L Ⅲ–Ⅳ级、疼痛严重影响睡眠与行走、保守治疗 ≥6 个月无效、年龄一般 >60 岁；围术期应有规范化镇痛与康复路径"],"life":["每日 30 min 中等强度有氧运动，避免蹲跪、爬山与爬楼梯训练","控制体重、戒烟；均衡饮食，适量补充蛋白质与维生素 D","术后 6 周、3 个月、1 年复查假体位置与功能；持续肌肉训练预防远期松动","避免用创可贴/「偏方」延误诊治；出现关节突然红肿热痛需排除感染与痛风"]},"prog":"膝关节骨关节炎进展缓慢，多数患者经保守治疗可长期维持功能；K-L Ⅲ–Ⅳ级者 TKA 术后 10 年假体生存率约 95%，满意率约 80%–90%，主要远期问题为假体松动、聚乙烯磨损与假体周围感染（发生率约 1%–2%）。","refs":["中华医学会骨科学分会关节外科学组《骨关节炎诊疗指南（2018 年版）》","《中国髌股关节骨关节炎诊疗指南（2020 年版）》","《膝骨关节炎阶梯治疗专家共识（2018 年版）》","《中国骨科手术加速康复——全膝关节置换围手术期管理专家共识》","OARSI Guidelines for the Non-surgical Management of Knee, Hip, and Polyarticular Osteoarthritis, 2019"]},{"id":"or_septic_arthritis","name":"化脓性关节炎","aka":["Suppurative Arthritis","Septic Arthritis","细菌性关节炎","感染性关节炎"],"rank":2,"basic":{"define":"由细菌（少数为真菌、结核）直接侵入关节腔引起的急性化脓性关节感染，以关节红、肿、热、痛与功能障碍为主要表现，属骨科急症。","risk":["人工关节置换术后（假体周围感染）","开放性关节损伤、关节腔穿刺/注射","糖尿病、免疫抑制、长期使用糖皮质激素或生物制剂","静脉药瘾、菌血症、皮肤软组织感染","关节内注射史、类风湿关节炎、肝硬化、慢性肾病"],"epi":"成人化脓性关节炎年发病率约 2–10 例/10 万人，膝关节最常见（约占 50%），其次为髋、肩；金黄色葡萄球菌占 60%–70%，髋关节感染与老年、假体感染病死率较高（住院死亡率约 5%–10%）。"},"patho":"细菌经血行播散、直接侵入（外伤、穿刺、手术）或邻近软组织感染扩散进入血供丰富的滑膜，滑膜充血水肿并产生大量中性粒细胞渗出；细菌毒素与溶酶体酶迅速破坏软骨蛋白多糖与胶原，通常在 1–2 周内造成不可逆软骨损伤，后期关节纤维化、强直。髋关节等深部关节因症状隐匿，破坏更重。","dx":{"criteria":["急性单关节红、肿、热、剧痛，关节于半屈位、拒绝活动；全身发热、寒战可见","关节穿刺为确诊关键：关节液混浊、脓性，白细胞常 >50×10⁹/L（部分标准 >20×10⁹/L），中性粒细胞比例 >75%–90%","关节液涂片革兰染色见细菌、培养阳性（血培养与关节液培养同时留取）","Kocher 标准（儿童髋关节感染）：发热 >38.5 ℃、不能负重、ESR >40 mm/h、WBC >12×10⁹/L，4 项全满足时预测概率 >99%","影像学：早期 X 线无明显异常；超声可发现关节积液并引导穿刺；MRI 用于髋关节及骨髓炎评估；CT 用于骨破坏与深部脓肿"],"workup":["关节穿刺：细胞分类计数、革兰染色、培养（需氧+厌氧）、必要时查晶体；留置穿刺液送检","血常规、CRP、ESR、降钙素原、血培养（抗生素使用前 2 套）","关节超声：确认积液并引导穿刺","X 线与 MRI：评估软骨下骨破坏、邻近骨髓炎与脓肿","假体关节：按 PJI 指南关节液培养+α-防御素、必要时行组织学与微生物培养","免疫状态评估：血糖/HbA1c、肝肾功能、HIV 与免疫抑制药使用史"],"grading":"按病程分：急性（≤2 周）、亚急性/慢性（>2 周，多为低毒力菌或结核）；按部位分：自体关节感染、假体周围感染（PJI，按 Delta-PJI 共识分为急性、慢性、部分Ⅰ期翻修）；结核性关节炎起病隐匿、以滑膜结核与后期冷脓肿为特点。"},"ddx":[{"name":"膝骨关节炎（or_knee_oa）","point":"与本类 or_knee_oa 的鉴别点：化脓性关节炎为急性起病、全身炎症反应明显、关节液白细胞极高且培养阳性；膝 OA 为慢性负重痛、关节无红热、ESR/CRP 多正常，两者关节穿刺结果截然不同。"},{"name":"痛风急性发作","point":"可呈暴发性单关节红肿热痛，血尿酸与病程不一定典型；关节液见负双折射针状尿酸盐结晶、细菌培养阴性。痛风合并感染并非不可能，需两者同时评估。"},{"name":"假体周围感染（PJI）","point":"人工关节置换术后出现关节持续疼痛、僵硬与窦道，需按 PJI 诊断标准（MSTS/ICM 2018 标准：关节液/组织培养、白细胞计数、α-防御素、CRP/ESR）综合判定，处理方式与自体关节感染不同。"}],"tx":{"drug":[{"name":"头孢唑林（经验性抗菌，疑似 MSSA）","dose":"2 g 静脉滴注 q8h，直至培养结果回报后目标性治疗","note":"取关节液与血培养后立即开始；根据药敏与临床反应调整，总疗程自体关节感染一般 3–4 周（非复杂病例），由感染科会诊确定","renal":"按 eGFR 调整剂量与给药间期，遵说明书","hepatic":"遵说明书","interact":"避免与氨基糖苷类同瓶"},{"name":"万古霉素（经验性覆盖 MRSA）","dose":"15–20 mg/kg 静脉滴注 q8–12h，按体重滴定，监测谷浓度（目标 15–20 mg/L）或 AUC24/MIC 400–600","note":"MRSA 流行区或重症患者与 β-内酰胺类联合经验治疗；有痛风史者注意加重风险","renal":"按 CrCl 与血药浓度调整；监测肾功能与听力","hepatic":"遵说明书","interact":"与氨基糖苷类、袢利尿剂合用增加肾毒性"},{"name":"头孢曲松（经验性覆盖淋球菌）","dose":"1 g 静脉滴注 qd（或肌注），疗程 7–14 天","note":"性活跃年轻患者、疑似淋球菌关节炎时使用；同时筛查并治疗沙眼衣原体合并感染","renal":"轻中度肾功能不全无需调整，重度慎用","hepatic":"遵说明书","interact":"与含钙输液同瓶可形成沉淀，避免同时输注"},{"name":"对乙酰氨基酚（镇痛）","dose":"0.5–1 g 口服 q6h，每日 ≤3 g","note":"镇痛避免使用 NSAIDs（可能加重感染与肾损伤、影响骨愈合），首选对乙酰氨基酚，必要时短期阿片类","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与复方制剂叠加"},{"name":"低分子肝素（预防）","dose":"依诺肝素 40 mg 皮下注射 qd，术后（排除活动性出血后）开始","note":"化脓性关节炎制动患者 VTE 风险升高，预防持续至恢复活动","renal":"CrCl 15–30 mL/min 减量至 30 mg qd","hepatic":"显著凝血障碍慎用","interact":"与抗菌药中头孢哌酮等含 NMTT 侧链者合用增加出血"}],"nonDrug":["关节穿刺抽液后立即静脉抗感染，24–48 h 内关节冲洗或引流：自动冲洗或关节镜清理为常用方式","膝关节：关节镜清理（切除坏死滑膜、去除游离软骨片）+ 持续冲洗引流 48–72 h，视引流液情况拔管","髋关节：髋关节切开引流或关节镜下冲洗；深部关节感染且破坏严重者可行关节切除/成形（Girdlestone 术）","患肢制动于功能位（膝 20°–30° 屈曲），减轻痉挛痛，早期在镇痛下进行被动活动防强直","持续监测 CRP、WBC 与体温，抗菌治疗 48–72 h 无效需再次评估引流是否充分、是否有耐药菌或深部脓肿","假体周围感染：根据病程与假体稳定性选择保留假体清创（DAIR）、一期/二期翻修框架下处理"],"life":["总疗程中 CRP 正常化、体温与关节症状缓解后可考虑序贯口服抗菌药完成疗程，由感染科评估","出院后 2 周、1 个月、3 个月复查 CRP/ESR 与关节超声，警惕复发","功能康复：早期被动活动、渐进主动活动与肌力训练，避免负重期过长导致屈曲挛缩","控制血糖、戒烟、治疗牙周与其他隐匿感染灶（假体患者尤其重要）"]},"prog":"及时（<24–48 h）诊断并引流+抗菌治疗者关节功能保全率约 80% 以上；延误 >1 周或由 MRSA、革兰阴性菌致病者关节破坏与功能障碍显著增加，死亡率可达 5%–10%。髋关节与假体感染预后较差，需长期功能随访。","refs":["中华医学会骨科学分会关节外科学组《人工关节假体周围感染诊断与治疗专家共识》2019","《中国骨科感染性疾病诊疗指南》2021","《中国开放性骨折诊断与治疗专家共识》2019（关节开放伤处理部分）","IDSA Clinical Practice Guidelines for the Diagnosis and Management of Native Joint and Prosthetic Joint Infection, 2012/2013"]}]},{"id":"sports_infect","name":"运动与感染","rank":4,"summary":"本类疾病的核心是「先排除致命的急症再谈功能」：ACL 损伤以重建恢复稳定性和运动能力为主，血源性骨髓炎以早期足疗程抗菌+必要时清创为核心，骨筋膜室综合征是唯一需要争分夺秒切开减压的骨科急症，任何延迟都可能造成不可逆的肌肉坏死与切肢。","compare":[{"diseaseId":"or_acl","dx":"非接触性扭转后关节内「啪」声、迅速肿胀伴不稳定感，Lachman 试验与轴移试验阳性，MRI 见前交叉韧带连续性中断","key":"急性关节积血 + Lachman 阳性；无全身炎症，关节液为血性而非脓性"},{"diseaseId":"or_osteomyelitis","dx":"持续性骨深部疼痛伴局部压痛、发热，实验室见 WBC/CRP/ESR 升高，X 线早期可正常，MRI 见骨髓水肿与脓肿，血培养或骨活检培养阳性","key":"疼痛深在且定位在骨、局部软组织红热不明显；MRI 为骨髓信号异常，抗菌需长疗程"},{"diseaseId":"or_compartment","dx":"肢体外伤或长时间制动后出现与损伤不相称的剧痛、被动牵拉痛、筋膜室紧张、感觉异常，进展至肌力下降与无脉，筋膜室内压 >30 mmHg 或与舒张压差 <30 mmHg","key":"被动牵拉痛是最早最敏感的体征，脉多正常；需急诊筋膜切开，任何影像等待均有风险"}],"diseases":[{"id":"or_acl","name":"前交叉韧带损伤（ACL 损伤）","aka":["ACL Tear","Anterior Cruciate Ligament Injury","前交叉韧带断裂","膝关节不稳定"],"rank":1,"basic":{"define":"前交叉韧带（ACL）因膝关节过度伸展、外翻或减速旋转时负荷超过其强度而发生部分或完全撕裂，导致膝关节前向与旋转不稳定。","risk":["篮球、足球、滑雪、手球等急停转向项目","女性运动员（解剖与激素因素，风险约 2–4 倍）","既往 ACL 损伤或对侧损伤史","过伸落地、膝盖外翻姿势","与地面摩擦过大的鞋钉/场地"],"epi":"一般人群中 ACL 损伤年发病率约 30–78 例/10 万人，运动人群中更高；女性足球与篮球运动员发病率可达男性的 2–4 倍。约 50%–65% 患者合并半月板损伤，其中内侧半月板常为不可修复的部位。"},"patho":"ACL 是限制胫骨前移与内旋的重要结构，损伤后膝关节失去前向稳定性，反复的胫股关节微脱位与剪切力导致半月板（尤其桶柄样撕裂）与软骨损伤，长期引起早期骨关节炎。急性期关节内积血引起肿胀与股四头肌抑制；本体感觉缺失进一步加重不稳感与二次损伤风险。","dx":{"criteria":["典型受伤机制：非接触性急停、落地扭转或外翻伤，可闻及「啪」声，随后数小时内关节迅速肿胀（血性）","不稳定感：走路感到打软腿、不能急转或在此方向发力","Lachman 试验（敏感度最高）、轴移试验（Pivot Shift）阳性；前抽屉试验提示但敏感度较低","MRI：ACL 连续性中断、信号增高、成角或断端移位；同时评估半月板、内外侧副韧带、后交叉韧带与软骨","KT-1000/2000 关节应力测试或应力位 X 线：量化胫骨前移差值（>3 mm 提示异常）"],"workup":["膝关节正侧位与负重位 X 线：排除骨折（胫骨髁间棘撕脱、Segond 骨折提示 ACL 损伤）","膝关节 MRI：确诊并评估合并伤","急性期关节穿刺：张力性积液明显时抽液缓解疼痛，为血性无并发症时无需常规穿刺","功能评估：单腿跳距离、Y 平衡、Hop 测试与不对称度（二次损伤高危评估）","青少年：注意骨骺未闭合，需评估 Tanner 分期（决定重建方式是否保留骨骺）"],"grading":"按损伤程度（MRI）：Ⅰ度 韧带内高信号、形态完整（扭伤）；Ⅱ度 部分撕裂；Ⅲ度 完全断裂。完全断裂者再按撕裂部位（近端、股骨端撕脱、中段、远端）与慢性程度（<3 个月急性、>3 个月慢性）分类；合并半月板损伤需记录是否可修复。"},"ddx":[{"name":"骨髓炎（or_osteomyelitis）","point":"与本类 or_osteomyelitis 的鉴别点：ACL 损伤为急性运动伤后关节内血性积血、Lachman/轴移阳性，无持续骨深部压痛与炎症指标显著升高；骨髓炎疼痛深在定位骨、局部无明显积液、CRP/ESR 显著升高、MRI 为骨髓信号异常。"},{"name":"骨筋膜室综合征（or_compartment）","point":"与本类 or_compartment 的鉴别点：ACL 损伤的肿胀与疼痛局限于膝关节且可随抽液/冰敷缓解，无筋膜室紧张；骨筋膜室综合征为与损伤不相称的剧痛、被动牵拉痛、感觉运动障碍进行性加重。"},{"name":"膝骨关节炎（or_knee_oa）","point":"与 or_knee_oa（关节大类）的鉴别点：ACL 损伤为急性运动伤、关节迅速积血肿胀、Lachman/轴移阳性；膝 OA 为慢性负重痛、无急性积血，X 线以骨赘与间隙变窄为主。"},{"name":"后交叉韧带（PCL）/内侧副韧带（MCL）损伤","point":"PCL 损伤多为屈膝时胫骨上端前方受撞击，后抽屉试验阳性、胫骨后沉；MCL 损伤为外翻应力痛、内侧关节间隙压痛，外翻应力位 X 线开口增大。"},{"name":"髌骨脱位/复发性髌股不稳","point":"髌骨向外侧移位史、恐惧试验阳性、Q 角增大与高位髌骨，MRI 见髌骨内侧支持带撕裂与软骨损伤。"}],"tx":{"drug":[{"name":"依诺肝素（重建术后 VTE 预防）","dose":"40 mg 皮下注射 qd，术后 12–24 h 开始，至可完全负重或出院后 14–21 天（按风险评估）","note":"ACL 重建术后 VTE 风险较低，鼓励早期活动和踝泵；高危（肥胖、既往 VTE、口服避孕药）延长预防","renal":"CrCl 15–30 mL/min 减为 30 mg qd","hepatic":"显著凝血障碍慎用","interact":"与 NSAIDs 合用增加出血"},{"name":"对乙酰氨基酚（急性期镇痛）","dose":"0.5–1 g 口服 q6h，每日 ≤3 g","note":"伤后 1–2 周内首选；避免长期使用 NSAIDs 以免影响韧带-骨界面愈合","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免复方制剂叠加"},{"name":"塞来昔布（急性期抗炎）","dose":"200 mg 口服 bid，疗程 ≤7–10 天","note":"短期用于急性期肿痛；重建术后尽量避免长时间使用（愈合期慎用 NSAIDs）","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"头孢呋辛（重建术后预防）","dose":"1.5 g 静脉滴注，术前 0.5–1 h 单次给药；手术 >3 h 追加 1 次，术后 24 h 内停药","note":"仅用于手术患者；β-内酰胺过敏者换克林霉素","renal":"按 eGFR 调整剂量与给药间期","hepatic":"遵说明书","interact":"与华法林合用可增强抗凝作用"}],"nonDrug":["急性期处理：RICE 原则（休息、冰敷、加压包扎、抬高），支具与拐杖部分负重，消肿后尽早康复","保守（非手术）适应证：部分撕裂、日常活动量低、单纯前向不稳定且经康复后无打软腿、拒绝手术或高龄患者；康复需包含股四头肌/腘绳肌力量、本体感觉与神经肌肉控制训练","手术重建适应证：年轻（一般 <40 岁、活跃人群）完全断裂、合并可修复半月板撕裂（尤其桶柄样）、反复关节不稳与打软腿、竞技运动或高风险职业；理想手术时机为肿胀消退、活动度基本恢复（伤后 3 周左右），过早手术增加关节纤维化风险","术式：自体腘绳肌腱或骨-髌腱-骨（BTB）单束/双束重建，股骨端可用悬吊或界面螺钉固定；骨骺未闭青少年采用保留骨骺技术","术后康复分阶段：早期（0–2 周）被动活动与股四头肌激活；中期肌力与平衡；后期（9–12 个月）专项运动与重返赛场测试","合并半月板：修复优先（尤其外周红区），修复后限制负重 4–6 周，防负重拉伸"],"life":["重返运动需满足功能测试标准（双下肢肌力差 <10%、单腿跳对称性 >90%、主观无恐惧），一般术后 9–12 个月","神经肌肉控制训练（落地缓冲、减速转向技术）可降低再损伤风险","术后 2 周、6 周、3 个月、6 个月、12 个月门诊复查；定期评估腘绳肌与股四头肌力量比（H/Q 比）","女性运动员加强落地技术与核心稳定性训练；必要时佩戴支具"]},"prog":"保守治疗患者约 30%–50% 仍因不稳而最终接受重建；重建后 5 年移植体失败率约 3%–10%，年轻竞技运动员再伤率显著升高。合并半月板切除者 10–15 年内骨关节炎风险增加 3–5 倍；即使重建，远期仍可能出现关节退变。","refs":["中华医学会运动医疗分会《前交叉韧带损伤诊疗指南（2019）》","《中国前交叉韧带重建术后康复专家共识（2019）》","《中国运动医学康复指南——前交叉韧带重建术后康复》","ESSKA/AAOS Management of Anterior Cruciate Ligament Injuries, 2019/2022"]},{"id":"or_osteomyelitis","name":"骨髓炎","aka":["Osteomyelitis","急性血源性骨髓炎","慢性骨髓炎","骨感染"],"rank":2,"basic":{"define":"由细菌（少数为结核、真菌）感染骨组织（骨髓、皮质骨、骨膜）引起的炎症性疾病，按病程分为急性（<2 周）与慢性，按来源分为血源性、创伤/术后与外源性（邻近软组织感染蔓延）。","risk":["开放性骨折、术后内固定/假体植入","糖尿病足溃疡、下肢缺血","菌血症（金黄色葡萄球菌）、静脉药瘾","免疫抑制、长期糖皮质激素与生物制剂","儿童生长发育期（血供丰富的干骺端）"],"epi":"急性血源性骨髓炎好发于儿童长骨干骺端（胫骨近端、股骨远端，约占 60%），金黄色葡萄球菌占 70%–80%；成人则多以创伤/术后与糖尿病足相关，合并糖尿病与周围血管病者致残率显著升高。"},"patho":"血源性感染时细菌在干骺端毛细血管环滞留并增殖，形成局部脓肿；脓肿沿哈佛管与福尔克曼管扩散，在骨膜下形成骨膜脓肿，破坏骨膜血供导致骨段坏死形成死骨，同时刺激骨膜新生骨形成包壳。慢性期形成被生物膜包裹的死骨与窦道，抗菌药物难以渗透，需手术清除。创伤/术后感染多为生物膜相关，与内固定/假体材料表面相关。","dx":{"criteria":["持续性骨深部疼痛、局部压痛，伴发热（急性期）或窦道、反复流脓（慢性期）","实验室：WBC、CRP 升高，ESR 显著升高；PCT 可用于区分脓毒症","性培养：血培养（抗菌药物前 2–3 套）、窦道分泌物或深部穿刺/组织活检培养（窦道分泌物培养易被污染，不能替代骨活检）","X 线：急性期 10–14 天内常无异常，之后见骨质疏松、骨膜反应与骨破坏；慢性期见死骨与包壳","MRI：骨髓水肿、骨膜下与软组织脓肿，敏感度高；CT 用于评估死骨与硬化；核素显像（³⁶⁷Ga、FDG-PET）用于多灶或疑难病例","诊断金标准：骨活检（组织病理+微生物培养）"],"workup":["血液：血常规、CRP、ESR、PCT、血培养 ×2；糖尿病者查血糖/HbA1c 与下肢血管（ABI、CTA）","影像：X 线为基线；疑似时尽早 MRI（含压脂序列）；慢性/术后感染行 CT 评估死骨与内固定","深部骨活检：在抗菌药物使用前或停用 48 h 后获取，同时送病理与培养（含厌氧、真菌、结核）","超声评估软组织脓肿与窦道走行","评估感染灶与异物（内固定、假体、死骨）及其稳定性"],"grading":"1）Cierny-Mader 解剖分型：Ⅰ型 髓内型；Ⅱ型 浅表型（骨表面）；Ⅲ型 局限型（死骨+骨腔，稳定性保留）；Ⅳ型 弥漫型（不稳定，需骨重建）；合并宿主因素（A 健康、B 局部/全身受损、C 禁忌手术）。2）急性血源性骨髓炎按病程为急性（<2 周）与慢性（>2 周/病程迁延、有死骨与窦道）。3）儿童亚急性/慢性可为 Brodie 脓肿（局限性骨内脓肿）。"},"ddx":[{"name":"前交叉韧带损伤（or_acl）","point":"与本类 or_acl 的鉴别点：ACL 损伤以关节内急性血性积液、Lachman/轴移阳性为特点，无持续骨深部压痛与炎症指标显著升高；骨髓炎疼痛定位骨、局部无明显积液、CRP/ESR 显著升高、MRI 为骨髓信号异常。"},{"name":"骨筋膜室综合征（or_compartment）","point":"与本类 or_compartment 的鉴别点：两者均可表现为剧烈骨/肢体疼痛，但骨筋膜室综合征以筋膜室紧张、被动牵拉痛与进行性感觉运动障碍为特征、进展迅猛；骨髓炎疼痛持续而进展缓慢，伴发热与炎症指标升高。"},{"name":"骨肿瘤（尤文肉瘤、骨肉瘤、转移瘤）","point":"同为「骨痛+发热+炎症指标升高」，尤文肉瘤常被误诊为骨髓炎；需 MR 增强与病理活检；肿瘤患者血象常有贫血，病变破坏呈浸润性。"},{"name":"化脓性关节炎","point":"感染位于关节腔而非骨髓，关节肿痛突出、关节液脓性；儿童髋关节感染须注意股骨头颈骨髓炎与关节感染并存。"}],"tx":{"drug":[{"name":"头孢唑林（经验性抗菌，MSSA 覆盖）","dose":"2 g 静脉滴注 q8h，获得培养与药敏后调整为目标性治疗","note":"取血培养与骨活检后立即开始；总疗程一般：急性血源性 4–6 周，慢性/术后 6 周（静脉或口服高生物利用度药物序贯，由感染科决定）","renal":"按 eGFR 调整剂量与给药间期","hepatic":"遵说明书","interact":"遵说明书"},{"name":"依诺肝素（VTE 预防）","dose":"40 mg 皮下注射 qd，制动期间使用","note":"长期卧床与制动患者血栓风险升高；活动性出血时暂缓","renal":"CrCl 15–30 mL/min 减量","hepatic":"显著凝血障碍慎用","interact":"与利福平联用时抗凝效果可能下降，监测"},{"name":"万古霉素（MRSA 经验覆盖）","dose":"15–20 mg/kg 静脉滴注 q8–12h，按体重滴定，监测谷浓度 15–20 mg/L 或 AUC24/MIC 400–600","note":"与 β-内酰胺类联合经验治疗直至培养回报；注意肾功能与听力监护","renal":"按 CrCl 调整；避免与肾毒性药物联用","hepatic":"遵说明书","interact":"与氨基糖苷类、利尿剂合用增加肾毒性"},{"name":"利福平（生物膜相关感染联合用药）","dose":"450–600 mg 口服 qd，常与头孢唑林等联合用于内固定/假体相关葡萄球菌感染，按感染科意见使用","note":"单药易产生耐药，必须联合；可使体液呈橙红色（需告知患者），并影响多种药物代谢","renal":"遵说明书","hepatic":"肝病、黄疸者慎用；用药期间监测肝功能","interact":"强效 CYP 诱导剂，可降低华法林、口服避孕药、他汀、抗真菌药等多种药物血药浓度"},{"name":"对乙酰氨基酚（镇痛）","dose":"0.5–1 g 口服 q6h，每日 ≤3 g","note":"长疗程中使用避免 NSAIDs（影响骨愈合与肾功能）；必要时短期阿片类按阶梯使用","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免复方制剂叠加"}],"nonDrug":["骨活检与培养是决策前提；未取得培养前不得盲目长疗程使用抗菌药","急性血源性骨髓炎（儿童为主）：多可仅用抗菌药治疗；脓肿明显者行经皮穿刺引流或切开引流","慢性骨髓炎：手术清创为关键——彻底去除死骨、窦道与坏死组织，有内固定/假体感染者根据稳定性与病程决定切除/保留（DAIR、保留内固定以清创）","死骨与骨缺损：可采用抗生素骨水泥间隔/珠链（局部高浓度释放），分期骨重建；Ilizarov 骨搬移适用于大段缺损","封闭负压引流（VSD）用于软组织缺损与开放性感染创面","糖尿病患者必须强化血糖控制与下肢血运评估（必要时血管重建）","软组织覆盖：清除后需皮瓣/肌瓣覆盖裸露骨面，降低复发"],"life":["抗菌疗程中每 2 周复查 CRP/ESR、肝肾功能与血药浓度（万古霉素、利福平时）","出院后 1、3、6、12 个月随访，关注窦道复发、内固定松动与病理性骨折","营养支持（蛋白 1.2–1.5 g/kg/日），戒烟，血糖达标（HbA1c <7.5%）","患者教育：出现窦道渗液、发热、局部红肿须及时复诊；不可自行停抗菌药"]},"prog":"急性血源性骨髓炎在及时足疗程抗菌治疗下治愈率 >80%，但合并脓肿或延迟诊断者转为慢性的风险可达 20%–30%。慢性骨髓炎经彻底清创+抗菌治疗后 1 年复发率约 10%–20%，需长期随访；内固定相关感染保留内固定的失败率约 10%–15%。","refs":["中华医学会骨科学分会创伤骨科学组《急性血源性骨髓炎诊疗专家共识》2020","《中国创伤骨科内固定相关感染诊疗专家共识》2021","《中国糖尿病足防治指南（2019 版）》","IDSA Clinical Practice Guideline for the Diagnosis and Treatment of Native Vertebral Osteomyelitis, 2015"]},{"id":"or_compartment","name":"骨筋膜室综合征","aka":["Compartment Syndrome","ACS","急性骨筋膜室综合征","筋膜间隙综合征"],"rank":3,"basic":{"define":"由骨、骨间膜、肌间隔与深筋膜构成的骨筋膜室内压力升高，导致室内毛细血管灌注下降、肌肉与神经缺血坏死的急性骨科急症，最常见于小腿前臂。","risk":["长骨骨折（胫骨骨折最常见）、肘关节周围骨折","挤压伤、闭合性软组织损伤","肢体长时间制动/石膏过紧、止血带时间过长","急性肢体缺血再灌注（血管重建术后）","意识障碍、镇静镇痛（掩盖症状）、服用抗凝药、剧烈运动后（慢性运动性骨筋膜室）"],"epi":"胫骨骨折后急性骨筋膜室综合征的发生率约 3%–10%，年轻男性与高能量损伤更多见；前臂骨折（尤其儿童肱骨髁上骨折）后发生率约 1%；延迟切开（>6–8 h）是肌肉坏死与切肢的主要可预防因素。"},"patho":"筋膜室内压力升高使静脉回流受阻、渗出增加，形成「压力升高—血供下降」的恶性循环；当筋膜室内压超过毛细血管灌注压时，肌肉与神经缺血。肌肉缺血 4 h 开始出现不可逆改变，6–12 h 可发生广泛坏死，神经损伤出现更早；后期出现肌肉纤维化（Volkmann 挛缩）、感觉运动障碍与肾功能损害（横纹肌溶解）。","dx":{"criteria":["核心临床征象：与损伤程度不相称的剧烈疼痛（镇痛后仍不缓解）、被动牵拉痛（最敏感体征，被动伸趾/伸腕痛）","查体：筋膜室紧张（「木板样」）、相应肌力下降、感觉异常（最早出现的感觉减退区）、后期苍白与无脉（均为晚期征象）","压力测定：筋膜室内压 >30 mmHg，或与舒张压差（ΔP）<30 mmHg（亦可用 MAP − 筋膜室压 <40 mmHg）提示需切开","立即行动原则：临床高度怀疑即应手术，不应等待压力测定或影像结果；脉多可触及不能排除","警惕镇静/昏迷患者无法表述疼痛，需以压力测定为主"],"workup":["床旁筋膜室压测定：成人正常 <10–12 mmHg，>30 mmHg 或 ΔP <30 mmHg 支持诊断；儿童阈值较成人低","X 线明确骨折与力线；必要时多普勒超声/CTA 排除主干血管损伤","血钾、肌酸激酶（CK）、肌酐、尿量、尿隐血/肌红蛋白：监测横纹肌溶解与急性肾损伤（CK 可 >5000 U/L）","血气、碱缺失与血乳酸：反映缺血与休克程度","若已行筋膜切开：术中直接观察肌肉活力（颜色、收缩性、毛细血管出血）作为金标准"],"grading":"急性骨筋膜室综合征无统一分级，临床可描述为：早期（疼痛+牵拉痛为主）、进展期（肌力下降、感觉障碍、肿胀紧张）、晚期（无脉、瘫痪、皮肤坏死）。慢性运动性骨筋膜室综合征按运动前后筋膜室内压（静息 >15 mmHg、运动后 1 min >30 mmHg 或运动后 5 min >20 mmHg）诊断。"},"ddx":[{"name":"前交叉韧带损伤（or_acl）","point":"与本类 or_acl 的鉴别点：ACL 损伤为关节内急性积血与不稳定，膝关节肿胀但肢体远端筋膜室不紧张，无被动牵拉痛与感觉运动障碍；骨筋膜室综合征的疼痛不局限于关节面、筋膜室明显紧张。"},{"name":"骨髓炎（or_osteomyelitis）","point":"与本类 or_osteomyelitis 的鉴别点：骨髓炎起病相对缓慢、以骨深部持续痛与发热为主，无筋膜室紧张与被动牵拉痛等急性缺血体征；两者进展速度截然不同，不能以等待炎症指标来决定是否切开。"},{"name":"动脉损伤/急性肢体缺血","point":"表现为「5P」中的苍白、无脉、冰冷与疼痛，伴搏动消失；ABI 降低、多普勒无血流。可同时合并骨筋膜室综合征，血管重建后需继续监测筋膜室压。"},{"name":"深静脉血栓/蜂窝织炎","point":"肢体肿胀与疼痛但无明显被动牵拉痛与感觉运动障碍；DVT 超声可确诊，蜂窝织炎有皮肤红斑与发热。两者不能解释不成比例的剧痛与筋膜室紧张。"}],"tx":{"drug":[{"name":"对乙酰氨基酚（镇痛，仅作为辅助）","dose":"0.5–1 g 静脉/口服 q6h，每日 ≤3 g","note":"镇痛不能替代减压，且须避免阿片类过度镇静掩盖病情；疼痛与体征不符即为警示，不应以增加镇痛拖延切开","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免复方制剂叠加"},{"name":"依诺肝素（VTE 预防）","dose":"40 mg 皮下注射 qd，出血风险控制后开始","note":"切开减压术后卧床期间使用；创面渗血多时推迟至稳定","renal":"CrCl 15–30 mL/min 减量","hepatic":"显著凝血障碍慎用","interact":"与抗凝药合用增加出血"},{"name":"头孢唑林（围术期预防，筋膜切开时）","dose":"1–2 g 静脉滴注，切皮前 0.5–1 h 单次；如合并开放伤或污染按治疗性用药","note":"筋膜切开属污染手术，需覆盖葡萄球菌与革兰阴性菌；术后根据创面情况决定疗程","renal":"按 eGFR 调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"甘露醇（针对横纹肌溶解/组织水肿）","dose":"20% 甘露醇 125–250 mL 静脉滴注，q8–q12h，短程使用（须与充分补液同期）","note":"证据有限，不作为切开减压的替代；主要针对明显肿胀与肾损伤保护，监测尿量与渗透压","renal":"eGFR 降低、少尿者慎用或禁用","hepatic":"遵说明书","interact":"与肾毒性药物合用增加肾损害"},{"name":"碳酸氢钠（碱化尿液，横纹肌溶解时）","dose":"5% 碳酸氢钠静脉滴注，按尿 pH 滴定（目标尿 pH >6.5），遵医嘱按体重滴定","note":"用于肌红蛋白尿导致的急性肾损伤预防，须与等渗晶体液复苏同时进行","renal":"少尿或容量过负荷者慎用","hepatic":"遵说明书","interact":"避免与含钙输液同瓶"}],"nonDrug":["确诊或高度怀疑即行紧急筋膜切开减压（确诊后 1–2 h 内）：小腿经 2 个切口（前外侧与后内侧）彻底切开 4 个筋膜室，前臂切开掌侧与背侧筋膜室，不缝合皮肤","术中必须切除无活力的肌肉（判断标准：颜色、收缩性、毛细血管出血、刺激反应），必要时二次探查（48–72 h）","创面不予一期缝合：延迟 3–7 天，采用 VSD 负压封闭引流，分期植皮/皮瓣覆盖","去除过紧的石膏/绷带与止血带，患肢置于心脏水平（不宜抬高，因抬高降低灌注压）；禁用冷敷或加压","充分液体复苏，碱化尿液，监测 CK、肌酐与尿量，预防横纹肌溶解相关急性肾损伤与低钾/高钾血症","解除导致压力升高的因素：内固定转为外固定，必要时切开骨筋膜与肌筋膜；血管损伤者尽早重建","后期功能重建：肌肉挛缩松解、神经松解（Volkmann 挛缩）","慢性运动性骨筋膜室综合征：诊断明确后行受累筋膜室筋膜切开术（门诊择期）"],"life":["筋膜切开术后 48–72 h 再次探查，创面分期处理；出院前评估伤口与功能","康复：早期被动活动防挛缩，创面稳定后进行主动肌力与感觉训练；后期长程随访足下垂、感觉恢复","运动人群注意训练负荷循序渐进，避免在脱水或疲劳状态下骑行/越野跑；出现运动后小腿肿胀紧张需评价慢性骨筋膜室","患者宣教：既往筋膜切开患者在患肢出现新发肿胀、疼痛时及时就诊"]},"prog":"在 6–8 h 内完成筋膜切开者肢体功能多可保全；延迟超过 8–12 h 者不可逆肌肉坏死与神经损伤风险显著增加，可遗留 Volkmann 挛缩与永久性感觉运动障碍。横纹肌溶解合并急性肾损伤者病死率约 5%–10%；严重挤压伤需截肢的比例约 5%–15%。","refs":["中华医学会骨科学分会创伤骨科学组《急性骨筋膜室综合征诊治专家共识》2021","《中国挤压综合征临床诊疗专家共识》2019","《中国创伤骨科患者围手术期静脉血栓栓塞症预防指南》2021","WOA/ISFR Acute Compartment Syndrome Consensus, 2019"]}]},{"id":"fracture_more","name":"其他部位骨折与脱位","rank":5,"summary":"远端与关节周围骨折追求恢复关节面与力线、可靠固定后早期活动；骨盆与髋臼骨折先按创伤急救控制出血与血流动力学，再谈固定；关节脱位须尽早复位，并在复位前后评估神经血管、复查影像排除合并骨折。","compare":[{"diseaseId":"or_distal_radius","dx":"撑地跌倒后腕部肿痛畸形，X 线见桡骨远端 3 cm 内骨折","key":"Colles（背侧移位、餐叉样）／Smith（掌侧移位、铲状）／Barton（关节面剪切）；关节面台阶与掌倾角决定是否手术"},{"diseaseId":"or_humerus","dx":"肩或上臂外伤后疼痛活动受限，X 线见肱骨近端或骨干骨折","key":"近端按 Neer 四部分分型定手术；骨干桡神经损伤多为神经失用，观察 3 个月多可恢复"},{"diseaseId":"or_ankle","dx":"踝部扭转后肿痛不能负重，X 线见内外踝或后踝骨折","key":"Lauge-Hansen 与 Danis-Weber 分型决定踝穴复位与下胫腓是否固定"},{"diseaseId":"or_pelvis","dx":"高能量伤后骨盆区疼痛、挤压试验阳性，可伴休克与血尿","key":"先按血流动力学不稳定处理（骨盆带+输血+DSA），髋臼以 CT 判断负重顶"},{"diseaseId":"or_dislocation","dx":"关节畸形、空虚、弹性固定，X 线见骨端脱出关节面","key":"复位前后均记录神经血管（腋神经、坐骨神经），复位后复片/CT 排除骨块"}],"diseases":[{"id":"or_distal_radius","name":"桡骨远端骨折","aka":["Colles 骨折","Smith 骨折","Barton 骨折","Distal Radius Fracture","DRF"],"rank":1,"basic":{"define":"桡骨远端关节面近侧 3 cm 以内的骨折，可伴尺骨茎突或下尺桡关节（DRUJ）损伤；按骨块移位方向分 Colles（背侧）、Smith（掌侧）与 Barton（关节面剪切）型。","risk":["中老年女性骨质疏松","青壮年高能量交通伤、坠落伤","跌倒手掌或手背撑地","镇静药与步态不稳","既往腕部骨折史"],"epi":"约占成人全身骨折的 1/6，是最常见的上肢骨折；老年低能量者女性约占 70%，青壮年多为高能量伤。"},"patho":"桡骨远端以松质骨为主，轴向压缩致干骺端嵌插粉碎：Colles 远端向背侧桡侧移位并背倾，Smith 反向掌倾。关节面台阶导致创伤性关节炎，下尺桡韧带撕裂致 DRUJ 不稳，腕管容积减小可压迫正中神经。","dx":{"criteria":["跌倒后腕肿痛、活动受限，Colles 呈「餐叉样」畸形，Smith 呈「铲状」畸形","桡骨远端压痛；尺骨茎突压痛提示合并尺骨茎突骨折或 DRUJ 损伤","X 线正侧位测掌倾角（约 11°）、尺偏角（22°–24°）与桡骨高度；关节面台阶或移位 >2 mm 倾向手术","关节内粉碎加做 CT；DRUJ 与隐匿骨折可行 MRI","必须记录正中神经感觉与桡动脉搏动"],"workup":["腕关节正侧位 X 线（必要时斜位、舟骨位）；肿胀重者复位临时固定后复片","CT 三维重建：关节内粉碎、Barton 型、尺骨茎突基底","神经电生理或超声：正中神经卡压患者"],"grading":"按移位方向：Colles、Smith、Barton（掌/背侧）、Chauffeur；AO/OTA 23 型 A 关节外、B 部分关节内、C 完全关节内。"},"ddx":[{"name":"肱骨近端与肱骨干骨折（or_humerus）","point":"与本类 or_humerus 的鉴别点：肱骨骨折肿痛在肩与上臂，肩关节活动痛阳性；本骨折压痛与畸形均在腕部，肘肩活动正常。"},{"name":"踝部骨折（or_ankle）","point":"与本类 or_ankle 的鉴别点：本骨折在腕部，腕活动与拇指对掌诱发剧痛；踝部骨折在内、外踝压痛且不能负重。"},{"name":"腕舟骨骨折","point":"鼻烟窝压痛突出，正侧位 X 线常阴性，需舟骨位或 CT/MRI；常与本骨折并存而漏诊。"},{"name":"月骨周围脱位","point":"腕中部压痛，侧位 X 线月骨与头状骨轴线不连续（「茶壶倾倒征」）。"},{"name":"腕部软组织扭伤","point":"无明显畸形与骨性压痛，X 线正常；需警惕症状轻却有隐匿骨折。"}],"tx":{"drug":[{"name":"塞来昔布","dose":"200 mg 口服 bid，3–7 天后按需减量","note":"老年注意消化道与肾脏风险，可联合对乙酰氨基酚","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、抗血小板药合用增加出血"},{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日 ≤3 g（老年/肝病 ≤2 g）","note":"与 NSAIDs 交替使用可减少后者总量","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与其他含该成分复方叠加"},{"name":"碳酸钙 D3 + 维生素 D","dose":"元素钙 1000–1200 mg/日 + 维生素 D3 800–1200 IU/日","note":"老年低能量骨折须同时评估并治疗骨质疏松","renal":"CKD 4–5 期改骨化三醇","hepatic":"遵说明书","interact":"与喹诺酮类、四环素类间隔 2 h"}],"nonDrug":["可接受位置（掌倾角 >−10°、桡骨高度丢失 <2 mm、台阶 <2 mm）者闭合复位 + 管型石膏/夹板 4–6 周（老年常用）","不稳定型（关节内粉碎、背倾 >15°、短缩 >3 mm、掌侧移位）或青壮年：掌侧锁定钢板内固定为主流；严重粉碎可加外固定架/克氏针","Barton 型与 DRUJ 不稳者固定桡骨并评估 TFCC/尺骨茎突，必要时修复","复位后 1 及 7–10 天复片评估再移位；正中神经卡压保守无效者行腕管松解"],"life":["抬高患肢、冰敷 48 h，手指主动屈伸减轻肿胀","术后 2 周、6 周、3 个月、6 个月复查 X 线，老年防跌倒与抗骨质疏松随访"]},"prog":"保守治疗 6 周临床愈合率约 80%–90%，复位丢失率 20%–30%（老年粉碎型更高）；掌侧钢板功能优良率约 80%–90%，腕管综合征约 3%–5%，关节面台阶 >2 mm 者易发创伤性关节炎。","refs":["《外科学》第 9 版（人民卫生出版社）桡骨远端骨折章","中华医学会骨科学分会创伤骨科学组《桡骨远端骨折诊疗指南》2019","《中国骨质疏松性骨折诊疗指南》2018"]},{"id":"or_humerus","name":"肱骨近端与肱骨干骨折","aka":["Proximal Humerus Fracture","Humeral Shaft Fracture","肱骨外科颈骨折","Holstein-Lewis 骨折"],"rank":2,"basic":{"define":"肱骨头下至外科颈的肱骨近端骨折，与外科颈以下至髁上的肱骨干骨折；老年人多为低能量跌倒，青壮年多为高能量伤。","risk":["老年骨质疏松跌倒","癫痫、电击（可致双侧骨折或脱位）","肩部直接暴力、投掷运动","交通伤、枪弹伤（骨干）","吸烟、糖尿病影响愈合"],"epi":"肱骨近端骨折居老年骨折第 3 位（约占全身 5%–6%）；肱骨干骨折约占全身 1%–3%，桡神经损伤率 10%–20%。"},"patho":"近端为松质骨、血供丰富，多数可保守愈合；但肱骨头血供来自旋肱前动脉前支，四部分移位骨折缺血坏死率约 5%–25%。肱骨干中下 1/3 桡神经紧贴桡神经沟，损伤多为神经失用，3–4 个月常恢复。","dx":{"criteria":["肩或上臂外伤后疼痛、肿胀、活动受限，骨干骨折可及反常活动与骨擦感","近端查腋神经（三角肌区感觉、外展）与肱动脉搏动","骨干查腕背伸、拇指外展、虎口区感觉（桡神经）与桡动脉搏动","X 线正侧位；骨干需含肩、肘关节；近端加肩胛 Y 位或腋位，必要时 CT","血管搏动减弱或上肢缺血者行 CTA/血管超声"],"workup":["肩关节正位 + 肩胛 Y 位 + 腋位；肱骨干正侧位含上下关节","CT 三维重建计算移位、结节粉碎与头颈分离","疑骨折-脱位头劈裂者行 MRI 或 CT 关节造影；神经电生理评估"],"grading":"Neer 分型依 4 个解剖部分（头、大结节、小结节、骨干），移位 >1 cm 或成角 >45° 记为一个移位部分：1–2 部分多保守，3 部分手术倾向，4 部分手术。肱骨干 AO/OTA 12 型；中下 1/3 螺旋骨折（Holstein-Lewis）桡神经损伤高危。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与本类 or_distal_radius 的鉴别点：本骨折肿痛在肩与上臂，外展与上臂旋转诱发痛；桡骨远端骨折畸形在腕部。"},{"name":"肩关节脱位（or_dislocation）","point":"与本类 or_dislocation 的鉴别点：脱位呈方肩、关节空虚、Dugas 征阳性；本骨折需排除骨折-脱位（头劈裂型）。"},{"name":"锁骨骨折","point":"压痛与畸形在锁骨，肩部下沉；可与本骨折并存，拍片时应同时观察锁骨。"},{"name":"肩袖撕裂（老年）","point":"X 线无骨折线，外展无力伴疼痛，MRI 见肌腱损伤。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日 ≤3–4 g（老年 ≤3 g）","note":"保守者前臂吊带配合多模式镇痛","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免与其他含该成分复方叠加"},{"name":"塞来昔布","dose":"200 mg 口服 qd–bid，5–7 天","note":"消化道高危加 PPI","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"甲钴胺","dose":"0.5 mg 口服 tid 或 0.5 mg 肌注 qod，4–8 周","note":"桡神经观察期辅助，证据有限，需配合腕背伸支具","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["近端 1–2 部分：颈腕吊带或外展支具 3–4 周，早期钟摆运动，6 周起主动辅助训练","近端 3 部分：年轻者锁定钢板，老年可保守或髓内钉；4 部分与头劈裂：老年首选反式肩关节置换","骨干：功能支具适用于轻度移位闭合骨折；手术指征为开放伤、血管伤、需探查的神经伤、浮肘/浮肩、多发伤或保守失败，首选髓内钉或钢板"],"life":["早期手指、腕、肘活动，防冻结肩与肌肉萎缩","桡神经损伤者腕背伸支具并每 4–6 周评估恢复；戒烟与补钙、维生素 D"]},"prog":"近端 1–2 部分 80%–90% 保守后功能良好；4 部分缺血坏死约 5%–25%；骨干保守愈合 85%–95%，骨不连 2%–10%；桡神经损伤 70%–90% 在 3–6 个月完全恢复。","refs":["《外科学》第 9 版（人民卫生出版社）肱骨近端与肱骨干骨折章","中华医学会骨科学分会创伤骨科学组《肱骨近端骨折诊疗专家共识》2015","AAOS Management of Proximal Humerus Fractures, 2023"]},{"id":"or_ankle","name":"踝部骨折","aka":["踝关节骨折","Ankle Fracture","Lauge-Hansen 分型","Danis-Weber 分型"],"rank":3,"basic":{"define":"内踝、外踝或后踝（胫骨远端关节面）在扭伤或直接暴力下的骨折，常伴三角韧带与下胫腓联合损伤，本质是踝关节「环」结构破坏。","risk":["运动扭伤（篮球、足球、滑雪）","跌倒与高处坠落（Pilon 型高能量）","老年骨质疏松低能量跌倒","既往踝扭伤与慢性不稳","肥胖与糖尿病"],"epi":"约占全身骨折 9%，为下肢最常见关节内骨折之一；旋后外旋型占 40%–70%。"},"patho":"踝关节由内外踝、下胫腓联合与内外侧韧带构成环形结构。旋后外旋型常为 Weber B，旋前外旋型为高位腓骨（Weber C）伴下胫腓分离；后踝骨折 >25%–30% 关节面常需固定以维持距骨位置，复位不良导致创伤性关节炎与慢性不稳。","dx":{"criteria":["扭伤或外伤后踝部肿胀、疼痛、不能负重，内外踝局限性压痛与瘀斑","挤压试验或外旋应力试验评估下胫腓联合","踝关节正侧位 + 踝穴位 X 线；内踝间隙 >4 mm、胫腓间隙 >5 mm 提示下胫腓分离","CT 三维重建评估后踝与关节面；MRI 用于韧带与隐匿骨折","记录开放伤、水疱与足背/胫后动脉搏动、腓神经感觉"],"workup":["踝关节正侧位 + 踝穴位；必要时全胫腓骨片排除高位腓骨骨折（Maisonneuve）","CT 三维重建：后踝骨块体积与关节面台阶","MRI：三角韧带/ATFL 损伤与慢性不稳"],"grading":"Lauge-Hansen 四型：旋后内收、旋后外旋（SER，最常见）、旋前外展、旋前外旋（高位腓骨）。Danis-Weber：A 关节面以下（多稳定）、B 关节面水平、C 关节面以上伴下胫腓分离（不稳）。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与本类 or_distal_radius 的鉴别点：本骨折在小腿远端、不能负重；桡骨远端骨折压痛在腕部。"},{"name":"肱骨近端与肱骨干骨折（or_humerus）","point":"与本类 or_humerus 的鉴别点：肱骨骨折在上肢，肩关节活动与上臂旋转痛；本骨折踝背屈与负重痛。"},{"name":"踝外侧韧带扭伤","point":"无骨性压痛、X 线正常；严重扭伤可与外踝撕脱骨折并存，需摄片确认。"},{"name":"Maisonneuve 骨折","point":"内踝压痛伴内侧不稳，但腓骨高位骨折易漏，须沿腓骨全长触诊并摄全胫腓骨片。"},{"name":"跟骨骨折","point":"足跟瘀斑（Mondor 征）、跟部横径增宽、高处坠落史，X 线跟骨侧位可鉴别。"}],"tx":{"drug":[{"name":"头孢唑林","dose":"1–2 g 静脉滴注，切皮前 0.5–1 h，术后 24 h 内停；开放骨折按 Gustilo 分型延长","note":"β-内酰胺类过敏改克林霉素","renal":"按 eGFR 调整","hepatic":"遵说明书","interact":"避免与氨基糖苷类同瓶"},{"name":"洛索洛芬钠","dose":"60 mg 口服 tid，餐后，5–7 天","note":"老年联合 PPI","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"依诺肝素","dose":"40 mg 皮下注射 q24h，入院或术后 12–24 h 起，约 14 天或至恢复行走","note":"BMI >40 可考虑 q12h","renal":"CrCl 15–30 mL/min 减为 30 mg q24h","hepatic":"凝血障碍者慎用","interact":"与 NSAIDs 合用增加出血"},{"name":"氨甲环酸","dose":"1 g 静脉滴注，切皮前 15 min；可局部 1 g 浸泡","note":"有血栓史者权衡","renal":"CrCl 30–60 减量，<30 慎用","hepatic":"遵说明书","interact":"与抗凝药合用需评估出血"}],"nonDrug":["无移位或稳定型（Weber A、单纯外踝无移位）：短腿石膏或步行靴 4–6 周","不稳型（双踝/三踝、下胫腓分离、踝穴增宽）：切开复位内固定，腓骨钢板 + 内踝螺钉/张力带","后踝 >25%–30% 关节面或移位 >2 mm 需固定；下胫腓不稳用 3.5 mm 螺钉或弹性固定并复查踝穴","软组织损伤重、水疱、开放伤：先跨关节外固定或石膏，5–14 天软组织恢复后 ORIF"],"life":["抬高患肢、早期踝泵与足趾活动防血栓；非负重期用助行器","术后 4–6 周开始渐进负重，复查 X 线与踝穴；康复含踝活动度、腓骨肌与本体感觉训练"]},"prog":"解剖复位固定后 80%–90% 获得良好功能；下胫腓未正确复位者创伤性关节炎可达 30%–50%；感染率 1%–5%，内固定取出率 10%–20%。","refs":["《外科学》第 9 版（人民卫生出版社）踝部骨折章","中华医学会骨科学分会创伤骨科学组《踝关节骨折诊疗指南》2018","《下胫腓联合损伤诊疗专家共识》2020"]},{"id":"or_pelvis","name":"骨盆与髋臼骨折","aka":["Pelvic Fracture","Acetabular Fracture","骨盆环骨折","Tile 分型","Judet-Letournel 分型"],"rank":4,"basic":{"define":"骨盆环（骶骨与双侧髂骨、耻骨/坐骨支构成）或髋臼（髂、坐、耻骨合成的关节窝）在高能量暴力下的骨折，常伴血流动力学不稳定与多发伤。","risk":["交通伤、摩托车伤、高处坠落","建筑物倒塌或机械碾压","老年人低能量跌倒（耻骨支骨折）","骨质疏松（老年髋臼骨折）","合并颅脑、腹腔脏器、泌尿系统与大血管损伤"],"epi":"约占全身骨折 3%；骨盆环骨折伴血流动力学不稳定者死亡率 20%–40%；髋臼骨折约占骨盆损伤 1/3。"},"patho":"骨盆环依赖前后两柱完整；开书样（APC）暴力使环张开，撕裂骶髂韧带与骶前静脉丛，形成腹膜后血肿，是失血性休克主要来源；侧方挤压（LC）内旋压缩出血相对少；垂直剪切（VS）致半骨盆上移并伴神经血管损伤。髋臼骨折预后取决于负重顶是否受累与关节面台阶。","dx":{"criteria":["高能量创伤后骨盆区疼痛、不能站立或翻身","骨盆挤压/分离试验疼痛、会阴或腹股沟瘀斑、双下肢不等长、足外旋","生命体征不稳定者按 ATLS 优先评估气道、呼吸、循环","必查泌尿生殖（血尿、尿道口滴血、导尿失败、直肠指检）、神经（会阴感觉）与血管（足背/股动脉搏动）","骨盆正位、入口位与出口位 X 线；稳定后 CT 三维重建，髋臼加 Judet 斜位","FAST 超声与腹部增强 CT 排查合并出血"],"workup":["ATLS 评估与 ISS 评分；不稳定者边复苏边排查出血源","床旁 FAST + 增强 CT；持续不稳疑盆腔动脉出血行 DSA 栓塞","尿常规、尿道造影（疑尿道损伤先不盲目导尿）、膀胱造影","Hb、凝血、乳酸、血栓弹力图、交叉配血"],"grading":"Tile 分型：A 稳定，B 旋转不稳定但垂直稳定（B1 开书、B2 侧方挤压、B3 双侧），C 旋转与垂直均不稳定。髋臼 Judet-Letournel：简单型（后壁、后柱、前壁、前柱、横形）与复合型（T 形、后柱+后壁、横形+后壁、前柱+后半横形、双柱）。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与本类 or_distal_radius 的鉴别点：本类为躯干下部高能量伤，常伴休克与脏器损伤；桡骨远端为腕部局限性损伤。"},{"name":"肱骨近端与肱骨干骨折（or_humerus）","point":"与本类 or_humerus 的鉴别点：肱骨骨折一般不影响血流动力学；本类以挤压试验阳性、失血性休克为特点。"},{"name":"关节脱位中的髋脱位（or_dislocation）","point":"与本类 or_dislocation 的鉴别点：髋脱位 X 线为股骨头脱出髋臼（常伴后壁骨折）；本类压痛更广泛，需 CT 定位。"},{"name":"股骨近端骨折（老年跌倒）","point":"股骨颈/转子间骨折患肢短缩外旋明显；耻骨支骨折以腹股沟压痛、翻身痛为主。"},{"name":"脊柱骨折伴脊髓损伤","point":"高能量伤常二者并存，需脊柱 CT/MRI，不能仅以骨盆所见解释神经体征。"}],"tx":{"drug":[{"name":"氨甲环酸","dose":"伤后 3 h 内 1 g 静脉滴注（10 min），随后 1 g 维持 8 h","note":"超过 3 h 使用可能增加死亡风险，不应再用","renal":"CrCl 30–60 减量，<30 慎用","hepatic":"遵说明书","interact":"与抗凝药同用需评估出血"},{"name":"头孢唑林","dose":"2 g 静脉滴注（>120 kg 用 3 g），入院尽早给药，切皮前再给，术后 24 h 内停","note":"合并肠道或泌尿生殖道损伤加甲硝唑/氨基糖苷类","renal":"按 eGFR 调整","hepatic":"遵说明书","interact":"避免与氨基糖苷类同瓶"},{"name":"依诺肝素","dose":"40 mg 皮下注射 q24h，伤后 24–48 h 出血可控后开始，持续至恢复行走（多 4–6 周）","note":"VTE 极高危，需动态评估出血","renal":"CrCl 15–30 mL/min 减为 30 mg q24h","hepatic":"凝血障碍者慎用","interact":"与 NSAIDs 合用增加出血"},{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服/静脉 q6h，每日 ≤3 g","note":"阿片类注意低血压与呼吸抑制","renal":"eGFR <30 延长给药间期","hepatic":"肝功能异常每日 ≤2 g","interact":"避免复方叠加"}],"nonDrug":["血流动力学不稳定：立即骨盆束缚带/床单于大转子水平闭合骨盆环，限制翻身，持续监测","大量输血按 1:1:1 或等比例启动，用血栓弹力图指导；持续腹膜后出血行经导管动脉栓塞，必要时球囊阻断，可与外固定+腹膜外填塞联合","骨盆外固定架用于 Tile B/C 临时或确定性固定；C 型后环需骶髂螺钉/钢板内固定","开放骨盆骨折：清创 + 抗菌药 + 外固定 + 负压引流，直肠/阴道损伤行造口","髋臼骨折：移位 >2 mm、负重顶受累或关节内游离骨块，1–2 周内切开复位内固定；老年按活动能力选择保守、内固定或全髋置换","尿道/膀胱损伤先耻骨上造瘘后二期修复"],"life":["急性期 ICU 监测生命体征、Hb、乳酸、尿量；骨折稳定后渐进负重","VTE 预防至恢复行走，定期下肢静脉超声；长期关注步态、肠道与性功能康复"]},"prog":"Tile A 保守预后好；Tile C 合并休克者死亡率 20%–40%，主要死于失血性休克与多发伤。髋臼骨折解剖复位（台阶 <2 mm）后 10 年创伤性关节炎 10%–30%，与复位质量正相关。","refs":["《外科学》第 9 版（人民卫生出版社）骨盆骨折、髋臼骨折章","中华医学会创伤学分会骨与关节损伤学组《骨盆骨折诊疗专家共识》2021","《严重创伤出血与凝血病处理指南（中国版）》2020"]},{"id":"or_dislocation","name":"关节脱位","aka":["肩关节脱位","肘关节脱位","髋关节脱位","Joint Dislocation","Shoulder Dislocation"],"rank":5,"basic":{"define":"关节骨端失去正常对合关系，分完全脱位与半脱位；以创伤性肩前脱位最常见，其次为肘、髋脱位。","risk":["运动创伤（肩外展外旋摔地、投掷）","高处坠落、交通伤（髋、肘）","既往肩脱位史（复发率高）","全身性关节松弛","癫痫发作或电击"],"epi":"肩脱位约占全身关节脱位 50%，95% 以上为前脱位；20 岁以下首次前脱位复发率 70%–90%。髋脱位多为高能量伤，约占创伤性大关节脱位 2%–5%。"},"patho":"脱位撕裂关节囊与韧带：肩前脱位致盂唇撕裂（Bankart）及肱骨头后外侧 Hill-Sachs 压缩骨折；髋后脱位多因膝部撞击仪表板，常伴髋臼后壁骨折与坐骨神经牵拉伤；肘后脱位可伴内上髁或桡骨头骨折及尺神经损伤。","dx":{"criteria":["外伤后关节剧痛畸形、关节盂空虚，弹性固定于特定体位","肩前脱位方肩、Dugas 征阳性；后脱位固定于内旋位","肩查腋神经与臂丛；髋查坐骨神经、股神经与股动脉；肘查桡/尺/正中神经与桡动脉","X 线：肩正位 + 腋位/Y 位，肘正侧位，髋正位 + 侧位/骨盆平片，必要时 Judet 斜位","复位后复片排除大结节、外科颈、桡骨头、髋臼后壁等骨折"],"workup":["脱位关节正侧位 X 线；髋脱位与肱骨头缺损加 CT 三维重建","神经损伤行肌电图；复位后 MRI/关节镜评估 Bankart、Hill-Sachs 与肩袖","高能量伤行 ABI/CTA 评估血管"],"grading":"肩：前脱位（喙突下型最常见）与后脱位。髋：后脱位、前脱位、中心性脱位。肘：后脱位、后外侧脱位、前脱位（伴骨折称复杂性脱位）。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与本类 or_distal_radius 的鉴别点：桡骨远端骨折腕部畸形但腕骨与桡骨关系正常；腕关节脱位（月骨周围脱位）侧位片轴线紊乱。"},{"name":"肱骨近端与肱骨干骨折（or_humerus）","point":"与本类 or_humerus 的鉴别点：肱骨近端骨折残留关节对合关系、X 线见骨折线；脱位为对合丧失、方肩与弹性固定。"},{"name":"骨盆与髋臼骨折（or_pelvis）","point":"与本类 or_pelvis 的鉴别点：二者可同存；单纯髋脱位复位后需 CT 确认后壁完整，血流动力学不稳者优先考虑骨盆骨折出血。"},{"name":"关节周围软组织扭伤","point":"无畸形与弹性固定，X 线对合正常；脱位复位后仍需 MRI 评估盂唇与韧带。"}],"tx":{"drug":[{"name":"咪达唑仑 + 芬太尼（复位镇静）","dose":"咪达唑仑 1–2 mg、芬太尼 25–50 μg 静脉缓慢推注，按反应小量追加（遵医嘱）","note":"须监护、吸氧并备纳洛酮/氟马西尼；老年与气道风险高者考虑全麻","renal":"肾功能不全减量","hepatic":"肝功能不全延长作用，减量","interact":"与阿片类/镇静药联用明显增加呼吸抑制"},{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，每日 ≤3–4 g","note":"减少阿片用量","renal":"eGFR <30 延长给药间期","hepatic":"肝功能不全每日 ≤2 g","interact":"避免复方叠加"},{"name":"洛索洛芬钠","dose":"60 mg 口服 tid，餐后，3–7 天","note":"消化道高危加 PPI","renal":"eGFR <30 禁用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"依诺肝素","dose":"40 mg 皮下注射 q24h，术后 12–24 h 起至恢复活动","note":"髋脱位、老年与长时间制动尤其需要","renal":"CrCl 15–30 mL/min 减为 30 mg q24h","hepatic":"凝血障碍者慎用","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["肩前脱位：Stimson 悬吊法、肩胛骨手法或外旋法复位（Kocher 法已不推荐），三角巾悬吊 2–3 周；<25 岁或骨性 Bankart 者考虑关节镜修复","合并大结节骨折复位不全（>5 mm）内固定；肩袖撕裂按程度处理","髋脱位：麻醉下 6 h 内闭合复位，复位后牵引/支具 6 周，非负重 6–8 周；后壁不稳者内固定；合并股骨头骨折（Pipkin）小骨块切除、大骨块内固定或老年置换","肘脱位牵引复位后评估稳定性；膝/踝关节脱位立即复位并评估腘动脉与腓神经","所有脱位复位后复片，48–72 h 再复片"],"life":["复位后冰敷抬高，按医嘱渐进活动","肩脱位 8–12 周内避免外展外旋投掷；髋脱位 6 周内避免屈髋 >90°、内收内旋","神经损伤每 4–6 周复查肌力感觉，配合理疗支具"]},"prog":"肩首次前脱位复位成功率 >95%，年轻患者复发 70%–90%，关节镜稳定术后复发 5%–15%。髋脱位 6 h 内复位股骨头坏死约 5%–10%，>24 h 可达 20% 以上。","refs":["《外科学》第 9 版（人民卫生出版社）关节脱位章","中华医学会骨科学分会关节外科学组《肩关节前脱位诊治专家共识》2022","AAOS Management of Anterior Shoulder Instability, 2019"]}]},{"id":"bone_tumor_other","name":"骨病与骨肿瘤","rank":6,"summary":"核心是「影像定性 + 分期 + 多学科决策」：股骨头坏死靠 MRI 早诊、ARCO 分期决定保髋或置换；骨肉瘤必须先活检、按 Enneking 分期规范新辅助化疗再保肢；脆性骨折在固定骨折同时启动抗骨质疏松与防再骨折；DDH 按年龄分层治疗。","compare":[{"diseaseId":"or_onfh","dx":"青壮年腹股沟区隐痛、内旋外展受限，X 线早期正常，MRI 见负重区 T2 双线征","key":"关键在塌陷前（ARCO Ⅰ–Ⅱ）保髋；塌陷后以关节置换为主"},{"diseaseId":"or_bone_tumor","dx":"青少年长骨干骺端疼痛肿物、夜间痛，X 线见破坏与 Codman 三角、日光放射样骨膜反应","key":"必须活检 + Enneking 分期，新辅助化疗→保肢→辅助化疗，忌「先切再查」"},{"diseaseId":"or_osteoporosis_fx","dx":"绝经后女性或老年男性轻微外力后髋部/腕部骨折，骨密度 T 值 ≤ −2.5","key":"按部位固定或置换，同时启动抗骨质疏松与 FLS 管理"},{"diseaseId":"or_ddh","dx":"婴幼儿腿纹不对称、外展受限、Ortolani/Barlow 阳性，超声/X 线示髋臼指数增大","key":"年龄决定治疗：吊带→闭合复位→截骨→成人全髋置换"}],"diseases":[{"id":"or_onfh","name":"股骨头坏死","aka":["ONFH","Osteonecrosis of the Femoral Head","股骨头缺血性坏死","AVN"],"rank":1,"basic":{"define":"股骨头血供中断或受损致骨髓成分与骨细胞死亡及修复反应，最终引起股骨头结构改变、塌陷与关节功能障碍。","risk":["长期或大剂量糖皮质激素","酗酒","股骨颈骨折、髋关节脱位后（创伤性）","减压病、镰状细胞病","SLE、器官移植后免疫抑制、凝血异常"],"epi":"我国非创伤性患者估计超过 800 万，30–50 岁男性多见；激素性约 30%–50%、酒精性 20%–30%；双侧受累率 40%–80%。"},"patho":"激素致骨髓脂肪细胞肥大、脂质栓塞与内皮损伤，酒精影响脂代谢与微循环，造成软骨下骨缺血；修复期在坏死区旁形成纤维组织与骨折，负重面失去支撑而塌陷。坏死区边界清楚，MRI 呈双线征（T2 低信号外带+高信号内带）。","dx":{"criteria":["腹股沟或臀部隐痛、可放射至大腿前内侧，「C 征」阳性，活动后加重","髋内旋、外展受限，跛行或 Trendelenburg 征","X 线早期正常；进展见软骨下硬化、囊变、新月征与塌陷","MRI 为首选早诊（敏感度 >90%）：T1 低信号、T2 双线征，位于上外侧负重区","需明确激素用量、饮酒史，并排除髋 OA、DDH、滑膜炎与结核"],"workup":["双髋 MRI（含压脂序列），对侧无症状者亦需筛查；骨盆与双髋 X 线","CT 三维重建评估新月征与塌陷风险，术前规划","凝血、脂代谢、骨密度；髋关节功能评分（HHS）与关节间隙评估"],"grading":"ARCO 分期（2019）：Ⅰ 期 X 线/CT 正常、MRI 阳性（按范围 A <15%、B 15%–30%、C >30%）；Ⅱ 期 见硬化囊变无新月征；Ⅲ 期 软骨下骨折/新月征并塌陷（ⅢA ≤2 mm、ⅢB >2 mm）；Ⅳ 期 关节间隙狭窄伴髋臼继发改变。"},"ddx":[{"name":"骨肿瘤总论与骨肉瘤（or_bone_tumor）","point":"与本类 or_bone_tumor 的鉴别点：骨肉瘤多见于青少年干骺端，有软组织肿块、骨膜反应与 ALP 升高；ONFH 坏死区边界清楚、无软组织肿块。"},{"name":"骨质疏松性骨折综合管理（or_osteoporosis_fx）","point":"与本类 or_osteoporosis_fx 的鉴别点：ONFH 多见于青壮年、病变局限；脆性骨折为老年低能量骨折与骨密度降低，股骨颈骨折后可继发 ONFH。"},{"name":"发育性髋关节发育不良（or_ddh）","point":"与本类 or_ddh 的鉴别点：DDH 以髋臼覆盖不足、髋臼指数增大为特征；ONFH 为股骨头内坏死，髋臼早期形态正常。"},{"name":"髋关节一过性滑膜炎","point":"急性起病可有发热与关节积液，MRI 见积液但无软骨下坏死区。"},{"name":"腰椎间盘源性疼痛","point":"疼痛沿下肢放射、腰部活动诱发；ONFH 定位腹股沟，髋内旋受限。"}],"tx":{"drug":[{"name":"阿仑膦酸钠","dose":"70 mg 口服，每周 1 次，晨起空腹 200 mL 清水送服，服后 30 min 保持直立","note":"证据有限，主要用于早期（ARCO Ⅰ–Ⅱ）辅助；需补钙与维生素 D","renal":"CrCl <35 mL/min 禁用","hepatic":"遵说明书","interact":"与钙、铁、镁制剂及餐食间隔 ≥30 min"},{"name":"依诺肝素（抗凝尝试）","dose":"40–60 mg 皮下注射 qd，12 周（证据有限）","note":"用于部分早期或凝血异常相关病例，须专科指导","renal":"CrCl 15–30 减为 30 mg qd","hepatic":"凝血障碍禁用","interact":"与抗血小板药、NSAIDs 合用增加出血"},{"name":"对乙酰氨基酚/塞来昔布","dose":"对乙酰氨基酚 0.5–1 g q6h（每日 ≤3 g），或塞来昔布 200 mg qd–bid 短程","note":"仅对症，不宜长期依赖 NSAIDs","renal":"eGFR <30 禁用 NSAIDs","hepatic":"肝功能不全减量","interact":"与抗凝药合用增加出血"},{"name":"依诺肝素（置换后 VTE 预防）","dose":"40 mg 皮下注射 q24h，术后 12–24 h 起，至术后 28–35 天","note":"髋置换属 VTE 极高危","renal":"CrCl 15–30 减为 30 mg qd","hepatic":"凝血障碍者权衡","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["ARCO Ⅰ–Ⅱ 期：髓芯减压（可联合植骨或浓集骨髓细胞），亦可行带血管蒂骨瓣移植、截骨术；保髋窗口在塌陷前，坏死范围 >30% 者成功率明显下降","ARCO Ⅲ–Ⅳ 期：全髋关节置换首选，青壮年选择陶瓷-陶瓷或高交联聚乙烯界面","SLE、移植患者与内科协作控制激素用量，避免自行骤停","一侧已塌陷置换时，对侧无症状但 MRI 阳性者尽早保髋干预"],"life":["减少负重（拐杖/助行器）减轻股骨头应力；戒酒，避免自行使用激素","保髋术后 3、6、12 个月复查 MRI/X 线，置换后按常规随访；突发剧痛不能负重须立即复查"]},"prog":"未治疗者约 70%–80% 在 2–4 年内塌陷；保髋在 ARCO Ⅱ 期成功率 60%–80%，Ⅲ 期明显下降。全髋置换 10 年假体生存率 >95%。","refs":["中华医学会骨科学分会关节外科学组《股骨头坏死临床诊疗规范（2020 版）》","中国医师协会骨科医师分会《成人股骨头坏死诊疗标准专家共识（2021 修订）》","ARCO 国际标准（2019）"]},{"id":"or_bone_tumor","name":"骨肿瘤总论与骨肉瘤","aka":["Osteosarcoma","骨肉瘤","Enneking 分期","Bone Tumor","原发性恶性骨肿瘤"],"rank":2,"basic":{"define":"骨肿瘤指骨、软骨、骨膜及附属组织来源的肿瘤，分原发性与继发性（转移瘤）；骨肉瘤是最常见的原发性恶性骨肿瘤，好发于青少年长骨干骺端。","risk":["青少年快速生长期（10–20 岁高峰）","Paget 病、骨纤维异常增殖症、既往放疗（继发性）","RB1、p53 等基因突变","慢性骨髓炎/骨梗死（罕见）"],"epi":"骨肉瘤占原发性恶性骨肿瘤 35%–45%，呈青少年与 >60 岁继发性双峰；我国年发病率约 2–3/100 万；肺转移为主要死因。"},"patho":"肿瘤性成骨细胞产生骨样基质，多位于股骨远端（约 40%）、胫骨近端（约 20%）、肱骨近端（约 10%）干骺端；突破骨皮质形成软组织肿块与骨膜反应（Codman 三角、日光放射样）。早期经血行转移至肺，故必须全身分期与新辅助化疗。","dx":{"criteria":["青少年干骺端疼痛（夜间痛、休息不缓解）伴硬性肿块、皮温升高、关节活动受限","X 线：偏心性溶骨成骨混合破坏、边界不清、骨膜反应与软组织肿块","MRI（增强）确定肿瘤范围、跳跃灶与神经血管受累，是保肢规划关键","必须穿刺活检（粗针或切开），活检通道须可一并切除","ALP、LDH 升高提示肿瘤负荷；胸部 CT 与骨扫描/PET-CT 完成分期"],"workup":["部位正侧位 X 线 + 胸部薄层 CT；部位 MRI 与全身骨扫描","多学科讨论后穿刺活检，规划活检通道","血常规、肝肾功能、心肌酶、心电图（化疗前评估）；青年患者生育力保存咨询"],"grading":"Enneking 外科分期：ⅠA/ⅠB（G1）、ⅡA/ⅡB（G2）、Ⅲ（有转移）。病理亚型：经典型（成骨/成软骨/成纤维）、毛细血管扩张型、小细胞型、骨旁型、继发性。化疗反应按 Huvos 分级（坏死 >90% 为良好）。"},"ddx":[{"name":"股骨头坏死（or_onfh）","point":"与本类 or_onfh 的鉴别点：ONFH 为负重区坏死带与双线征，无骨膜反应与软组织肿块、ALP 正常；骨肉瘤边界不清破坏伴骨膜反应与肿块。"},{"name":"骨质疏松性骨折综合管理（or_osteoporosis_fx）","point":"与本类 or_osteoporosis_fx 的鉴别点：转移瘤或继发肉瘤可在骨质疏松背景上呈溶骨破坏，需 MRI/活检排除病理骨折。"},{"name":"发育性髋关节发育不良（or_ddh）","point":"与本类 or_ddh 的鉴别点：DDH 为髋臼覆盖不足，无破坏性病灶与软组织肿块。"},{"name":"尤文肉瘤","point":"多见于儿童，长骨骨干或骨盆，X 线呈葱皮样骨膜反应，需分子病理（EWSR1 重排）确诊。"},{"name":"骨巨细胞瘤","point":"20–40 岁长骨骨端，偏心膨胀性溶骨、无骨膜反应、ALP 正常，多可刮除植骨。"},{"name":"慢性骨髓炎","point":"有窦道、骨硬化与破坏并存，培养与病理可鉴别；无化脓表现的不典型骨破坏须警惕恶性肿瘤。"}],"tx":{"drug":[{"name":"甲氨蝶呤（大剂量）","dose":"12 g/m² 静脉滴注 4–6 h，亚叶酸钙解救，每 2 周重复（按国内骨肉瘤方案执行）","note":"须在有经验科室执行，监测血药浓度、肝肾功能与黏膜炎","renal":"肾功能不全禁用或减量，监测 MTX 浓度","hepatic":"肝功能不全慎用并减量","interact":"与 NSAIDs、水杨酸盐合用延迟排泄增加毒性"},{"name":"多柔比星","dose":"60–75 mg/m² 静脉滴注，每 3 周 1 次，累积剂量一般 ≤450–550 mg/m²","note":"剂量相关心脏毒性，监测 LVEF；避免外渗","renal":"按说明书调整","hepatic":"胆红素升高需减量","interact":"与其他心脏毒性药物联用增加心衰风险"},{"name":"顺铂","dose":"90–120 mg/m² 静脉滴注（充分水化），每 3 周；按方案调整","note":"强致吐、肾毒性、耳毒性与神经毒性，监测肌酐与听力","renal":"肾功能不全减量或禁用","hepatic":"遵说明书","interact":"与氨基糖苷类等肾毒性药物合用增加肾损伤"},{"name":"异环磷酰胺","dose":"按方案 1.8–3 g/m² 静脉滴注（合用美司钠）","note":"美司钠预防出血性膀胱炎，监测血尿与骨髓抑制","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与顺铂合用增加骨髓毒性"},{"name":"地舒单抗（骨巨细胞瘤）","dose":"120 mg 皮下注射 q4w（首月第 8、15 天加用 1 次）","note":"仅用于不可切除或需保留关节的骨巨细胞瘤；注意低钙与颌骨坏死","renal":"CrCl <30 慎用，监测血钙","hepatic":"遵说明书","interact":"与其他调钙药物合用需监测血钙"}],"nonDrug":["MDT 决策：骨科肿瘤、肿瘤内科、影像、病理与放疗共同讨论活检与路径","标准路径：新辅助化疗 8–10 周评估 → 广泛边界切除 + 重建或截肢 → 依化疗反应调整辅助化疗","保肢重建：肿瘤型假体、异体骨或带血管骨移植，须保证广泛边界；骨肉瘤对放疗不敏感","肺转移：可切除者行转移灶切除；严格规划活检通道，避免污染正常间室"],"life":["化疗期口腔护理、感染防护与营养支持","随访：术后 2 年内每 3 个月、2–5 年每 6 个月、5 年后每年复查局部影像与胸部 CT","关注心脏毒性、耳毒性与生育功能等远期并发症"]},"prog":"局限期经规范新辅助化疗 + 保肢 5 年生存率 60%–70%（未化疗时代仅 15%–20%），化疗反应良好者更好。肺转移者 5 年生存率 20%–30%，完全切除转移灶可达 40% 左右。","refs":["《外科学》第 9 版（人民卫生出版社）骨肿瘤章","中华医学会骨科学分会骨肿瘤学组《骨肉瘤临床诊疗规范（2022 版）》","NCCN Guidelines: Bone Cancer, 2024"]},{"id":"or_osteoporosis_fx","name":"骨质疏松性骨折综合管理","aka":["脆性骨折","Osteoporotic Fracture","FLS","骨折联络服务","髋部脆性骨折"],"rank":3,"basic":{"define":"在骨质疏松基础上由轻微外力（站立高度以下跌倒）引起的骨折，常见于椎体、髋部、桡骨远端与肱骨近端；本条侧重髋部与腕部脆性骨折的全程管理（椎体见 or_ovcf）。","risk":["绝经后女性、70 岁以上男性","骨密度 T 值 ≤ −2.5 或既往脆性骨折","长期糖皮质激素、抗癫痫药、质子泵抑制剂","低体重、吸烟、过量饮酒","跌倒风险（视力、平衡、镇静药、居家环境）"],"epi":"我国 50 岁以上骨质疏松患病率女性约 32.1%、男性约 6%；65 岁以上髋部骨折发病率约 1%；髋部骨折后 1 年死亡率 15%–25%。"},"patho":"骨小梁变细断裂、皮质孔隙增加，骨强度下降致低能量应力即骨折；髋部骨折位于松质骨与皮质移行区，血供与愈合能力受损。骨折后疼痛与制动加速骨丢失与肌少症，形成「骨折—制动—再骨折」循环，与跌倒易感因素互为因果。","dx":{"criteria":["轻微外力后髋部、腕部或背部疼痛；髋部骨折不能站立，腕部骨折局部畸形压痛","髋部：X 线见股骨颈或转子间骨折；X 线阴性而高度怀疑行 MRI 或 CT","腕部：X 线见桡骨远端骨折，评估关节面与 DRUJ","DXA T 值 ≤ −2.5，或已发生髋部/椎体脆性骨折即可临床诊断骨质疏松","排除继发因素：血钙磷、25-OH 维生素 D、PTH、甲功、M 蛋白、肝肾功能"],"workup":["骨折部位 X 线，髋部含侧位与股骨全长；DXA（L1–L4 与股骨颈）","25-OH 维生素 D、血钙磷、PTH、甲功、M 蛋白与激素水平","胸腰椎 X 线筛查无症状椎体骨折；跌倒评估（视力、步态平衡、用药）"],"grading":"按部位：髋部（股骨颈 Garden、转子间 AO/OTA 31-A）、腕部（Colles/Smith/Barton，AO 23）。再骨折风险：既往脆性骨折、T 值 ≤ −3.0、激素使用或高跌倒风险为极高危。"},"ddx":[{"name":"股骨头坏死（or_onfh）","point":"与本类 or_onfh 的鉴别点：ONFH 多见于青壮年、病变局限；脆性骨折有低能量外伤与 DXA 降低；股骨颈骨折后可继发 ONFH 需随访。"},{"name":"骨肿瘤总论与骨肉瘤（or_bone_tumor）","point":"与本类 or_bone_tumor 的鉴别点：转移瘤致病理骨折可表现似低能量骨折，但 MRI 见骨破坏与软组织肿块。"},{"name":"发育性髋关节发育不良（or_ddh）","point":"与本类 or_ddh 的鉴别点：DDH 自幼起病、髋臼覆盖不足；老年髋部骨折起病突然、X 线骨折线明确。"},{"name":"骨质疏松性椎体压缩骨折（or_ovcf，见 ortho_1）","point":"椎体骨折处理见 ortho_1；本条不重复，但各类脆性骨折须共同纳入抗骨质疏松管理。"},{"name":"骨软化症/甲状旁腺功能亢进","point":"全身骨痛、骨畸形与无力，血钙磷与 PTH 异常，需实验室检查排除继发因素。"}],"tx":{"drug":[{"name":"碳酸钙 D3 + 维生素 D","dose":"元素钙 1000–1200 mg/日（含饮食），维生素 D3 800–1200 IU/日","note":"基础治疗；25-OH 维生素 D ≤20 ng/mL 需更高剂量纠正","renal":"CKD 4–5 期用骨化三醇，监测血钙磷","hepatic":"遵说明书","interact":"与喹诺酮类、四环素类间隔 ≥2 h"},{"name":"唑来膦酸","dose":"5 mg 静脉滴注，每年 1 次，输注 ≥15 min；术前 eGFR ≥35 mL/min","note":"髋部骨折围术期 24–72 h 内可使用，注意低钙血症与颌骨坏死","renal":"CrCl <35 mL/min 禁用","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加肾损伤；不与含钙输液同瓶"},{"name":"地舒单抗","dose":"60 mg 皮下注射 q6m，停药须有后续方案","note":"适用于肾功能不全或高骨折风险者；注意低钙与颌骨坏死","renal":"CrCl <30 慎用，监测血钙","hepatic":"遵说明书","interact":"不与其他抗骨吸收药叠加"},{"name":"特立帕肽","dose":"20 μg 皮下注射 qd，疗程 ≤24 个月","note":"用于严重骨质疏松、多发脆性骨折或双膦酸盐失败者；停药后接抗骨吸收药","renal":"eGFR <30 不推荐","hepatic":"遵说明书","interact":"与钙剂同用需监测血钙"},{"name":"依诺肝素","dose":"40 mg 皮下注射 q24h，按围术期方案，至术后 28–35 天","note":"髋部骨折与手术属 VTE 极高危","renal":"CrCl 15–30 mL/min 减为 30 mg qd","hepatic":"凝血障碍者慎用","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["髋部脆性骨折：移位型股骨颈老年患者人工股骨头/全髋置换，转子间骨折髓内钉，力争 48 h 内手术","腕部脆性骨折：无移位者闭合复位石膏/夹板，不稳定或关节内移位者掌侧钢板","建立骨折联络服务（FLS）：骨折后即启动抗骨质疏松评估、用药与随访","首次脆性骨折即启动抗骨质疏松，不等待骨密度；长期激素使用者视为极高危","跌倒预防：平衡与肌力训练、视力矫正、居家改造、停用不必要镇静药"],"life":["每年复查骨密度与 25-OH 维生素 D，评估依从性","每周至少 3 次负重运动与平衡训练；戒烟限酒，保证日照与蛋白摄入","骨质疏松药物通常持续 3–5 年，不得随意停药"]},"prog":"首次椎体骨折后 1–2 年再骨折风险增加 3–5 倍；髋部骨折 1 年死亡率 15%–25%，20%–30% 丧失独立行走能力。规范抗骨质疏松可降低再骨折约 50%–70%。","refs":["中华医学会骨质疏松和骨矿盐疾病分会《原发性骨质疏松症诊疗指南（2022 年版）》","《中国骨质疏松性骨折诊疗指南》2018","《骨质疏松性骨折诊疗与管理专家共识》2020"]},{"id":"or_ddh","name":"发育性髋关节发育不良","aka":["DDH","Developmental Dysplasia of the Hip","先天性髋关节脱位","CDH"],"rank":4,"basic":{"define":"婴幼儿与儿童期髋臼发育缺陷及股骨头/髋臼关系异常的谱系性病变，从轻度髋臼发育不良、半脱位到完全脱位，部分患者成年后才出现症状。","risk":["女性（约为男性 4–6 倍）","臀位产（尤其单臀位）","家族史","羊水过少、第一胎、巨大儿与下肢伸直绑缚襁褓","合并斜颈、马蹄内翻足"],"epi":"我国新生儿筛查阳性率约 1%–3%，需治疗者约 0.1%–0.2%；未治疗完全脱位者成年后几乎均出现严重骨关节炎。"},"patho":"髋臼变浅、前外侧覆盖不足，股骨头失去同心圆对应关系；出生后关节松弛与下肢伸直内收的襁褓方式加重脱位。脱位后髋臼进一步变浅、圆韧带拉长、臼内脂肪增生使复位困难，持续异常应力最终导致骨关节炎。","dx":{"criteria":["新生儿与婴儿：Ortolani 征、Barlow 征、髋外展受限、腿纹/臀纹不对称","学步期：跛行、Trendelenburg 征、单腿站立不稳、患肢相对短缩","超声（<6 月龄，Graf 法）：α 角 <60° 或覆盖率 <50%","X 线（>6 月龄）：髋臼指数增大（婴儿 >25°–30°）、股骨头骨化中心位于外下象限、Shenton 线中断","MRI/关节造影用于复杂病例与复位后评估；CT 用于成人截骨规划"],"workup":["新生儿体格筛查 + 高危因素，按当地政策行超声筛查","髋关节正位 X 线（>6 月龄）：髋臼指数与骨化中心位置；成人骨盆 CT 三维重建（CE 角、Sharp 角）"],"grading":"Graf 超声：Ⅰ α ≥60°；Ⅱ α 50°–59°（Ⅱa 生理性、Ⅱb 延迟）；Ⅲ α <43° 伴股骨头移位；Ⅳ 完全脱出。成人 Crowe 分型：Ⅰ <50%、Ⅱ 50%–75%、Ⅲ 75%–100%、Ⅳ >100%（骨盆高度）。"},"ddx":[{"name":"股骨头坏死（or_onfh）","point":"与本类 or_onfh 的鉴别点：ONFH 为股骨头负重区坏死与双线征，髋臼形态多正常；DDH 为髋臼覆盖不足、髋臼指数增大。"},{"name":"骨肿瘤总论与骨肉瘤（or_bone_tumor）","point":"与本类 or_bone_tumor 的鉴别点：DDH 为发育性结构异常，无破坏性病灶与软组织肿块。"},{"name":"骨质疏松性骨折综合管理（or_osteoporosis_fx）","point":"与本类 or_osteoporosis_fx 的鉴别点：髋部脆性骨折有明确跌倒与骨折线；DDH 自幼起病、渐进性疼痛。"},{"name":"髋关节一过性滑膜炎","point":"3–8 岁儿童急性跛行伴积液，数日至 2 周自愈，髋臼形态正常。"},{"name":"股骨头骨骺滑脱（SCFE）","point":"10–16 岁跛行伴膝/髋痛，X 线示骨骺后移（「冰山征」），需急诊固定。"}],"tx":{"drug":[{"name":"对乙酰氨基酚（术后镇痛）","dose":"儿童 10–15 mg/kg 口服 q4–6h（单次最大 1 g）","note":"按体重计算，避免复方叠加","renal":"肾功能不全延长给药间期","hepatic":"肝功能不全慎用或减量","interact":"避免与其他含该成分复方同用"},{"name":"布洛芬（>6 个月患儿）","dose":"5–10 mg/kg 口服 q6–8h，餐后，短期使用","note":"注意消化道与肾脏反应","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与抗凝药、其他 NSAIDs 合用增加出血"},{"name":"头孢唑林（围术期预防）","dose":"儿童 30 mg/kg 静脉滴注（成人 1–2 g），切皮前 0.5–1 h，术后 24 h 内停","note":"过敏改克林霉素，按体重计算","renal":"按 eGFR 调整","hepatic":"遵说明书","interact":"遵说明书"},{"name":"依诺肝素（成人截骨/置换）","dose":"40 mg 皮下注射 q24h，术后 12–24 h 起，14–35 天","note":"儿童仅高危个体化使用","renal":"CrCl 15–30 减为 30 mg qd","hepatic":"凝血障碍慎用","interact":"与 NSAIDs 合用增加出血"}],"nonDrug":["0–6 个月：Pavlik 吊带（屈髋约 100°–110°、外展 45°–60°），每周超声复查调整，多数 3–6 个月治愈","6–18 个月：麻醉下闭合复位 + 髋人字石膏 8–12 周（必要时内收肌松解），关节造影/MRI 确认同心圆复位",">18 个月或闭合复位失败：切开复位 + 骨盆截骨（Salter/Pemberton/Dega）+ 股骨短缩旋转截骨","学龄与青少年按覆盖情况行骨盆截骨（PAO/三联截骨）；成人 Crowe Ⅲ–Ⅳ 伴骨关节炎行全髋关节置换","宣教纠正下肢伸直绑缚的襁褓方式，坚持早期筛查与随访"],"life":["吊带/石膏期皮肤护理与定期复查；随访至骨骼成熟，每 3–6 个月复查","拆除支具后渐进负重、步态评估与物理治疗；控制体重、避免高冲击活动"]},"prog":"早期（<6 个月）Pavlik 吊带成功率 80%–95%，残余髋臼发育不良 5%–15%；1 岁内闭合复位成功率较高，>18 个月常需切开复位。治疗后股骨头坏死（AVN）约 5%–10%。成人全髋置换 10 年假体生存率 >90%。","refs":["《外科学》第 9 版（人民卫生出版社）发育性髋关节发育不良章","中华医学会小儿外科学分会《发育性髋关节发育不良诊疗专家共识（2017）》","AAOS Detection and Nonoperative Management of Pediatric DDH in Infants Up to Six Months of Age, 2022"]}]},{"id":"fracture_upper_limb","name":"上肢骨折与脱位","rank":7,"summary":"上肢骨折的核心是「血管神经评估 + 分型决定术式」：先查桡/尺/正中/腋神经与远端脉搏，再按部位分型（Neer、Gartland、Schatzker 类），切开复位内固定的指征取决于移位与关节内受累程度。","compare":[{"diseaseId":"or_clavicle","dx":"外伤后肩部疼痛、触及骨擦感，X 线见锁骨中外 1/3 骨折，可伴臂丛或锁骨下血管损伤","key":"移位 >2 cm、短缩或成角明显的成人锁骨中段骨折推荐手术；儿童多保守"},{"diseaseId":"or_humeral_proximal","dx":"老年跌倒后肩痛、活动受限，X 线（含腋位或肩胛骨 Y 位）按 Neer 四部分分型","key":"Neer 一/二部分保守，三/四部分或伴脱位需手术（反式肩关节置换常见于高龄）"},{"diseaseId":"or_humeral_shaft","dx":"上臂中部疼痛肿胀、畸形，需重点查**桡神经**（垂腕、拇指背伸无力）","key":"桡神经损伤是最常见的合并症；多数可保守并早期功能锻炼"},{"diseaseId":"or_supracondylar","dx":"儿童多见，肘部肿胀与疼痛，X 线侧位见「脂肪垫征」阳性；按 Gartland 分型","key":"Gartland IIb/III 型需闭合复位经皮克针固定；重点查**肱动脉与正中神经（骨筋膜室综合征风险）**"},{"diseaseId":"or_forearm_fx","dx":"尺桡骨双骨折或单骨折（孟氏/盖氏），需评估旋转与下尺桡关节","key":"成人与明显移位者需切开复位加压钢板；孟氏/盖氏损伤易漏诊下尺桡脱位"},{"diseaseId":"or_scaphoid","dx":"跌倒手掌着地后腕部鼻烟窝压痛，早期 X 线可阴性","key":"**X 线阴性但高度怀疑时按骨折处理**（石膏制动 2 周后复查或直接 MRI/CT），否则易致不愈合与缺血坏死"}],"diseases":[{"id":"or_clavicle","name":"锁骨骨折","aka":["Clavicle Fracture","锁骨中段骨折"],"rank":1,"basic":{"define":"锁骨在外力下发生断裂，多见于中段（约 80%），其次为远端（15%）与近端（5%）。是儿童与青壮年最常见的骨折之一。","risk":["跌倒致肩部着地（自行车、滑雪）","机动车事故（高能量）","竞技运动（橄榄球、摔跤）","新生儿产伤（巨大儿、肩难产）"],"epi":"占全部骨折的 2.6%–4%，占肩带骨折的 44%–66%，中段骨折占 80%。新生儿产伤性锁骨骨折发生率约 0.5%–1%。"},"patho":"锁骨呈「S」形，中段是形态转换点（内为胸锁乳突肌止点、外为喙锁韧带附着），也是最薄弱处，故外力下最易断裂。近端骨折块受胸锁乳突肌牵拉向上移位，远端受上肢重力牵拉向下移位，形成典型成角与短缩。移位的骨块可压迫臂丛神经（表现为上肢麻木无力）或锁骨下动静脉（少见但危及生命）。","dx":{"criteria":["外伤后肩锁区疼痛、肿胀、压痛，可见皮下瘀斑与骨性隆起，患肢拒动（幼儿表现为不愿抬臂、哭闹）","X 线（必需）：正位片评估骨折部位与移位；**加拍腋位或头尾斜位**评估前后移位；必要时加拍对侧对比","移位程度：短缩 >2 cm、完全移位（无骨接触）、成角 >30°、或存在「帐篷样」皮肤（骨块顶起皮肤）为手术指征相关指标","合并伤筛查：上肢麻木/无力（臂丛）、桡动脉搏动减弱与上肢肿胀淤青（锁骨下血管）、气胸（同侧呼吸音降低）","新生儿：X 线或超声（产伤，多表现为「假性瘫痪」——不活动但无真实神经损伤）"],"workup":["锁骨正位 + 腋位 X 线（或肩胛骨 Y 位）","上肢血管与神经查体：桡动脉搏动、上肢感觉与肌力","胸部 X 线（高能量伤、疑气胸或肋骨骨折）","若皮肤受压变薄或存在开放性伤口，需急诊手术评估","老年人需评估骨质疏松与跌倒风险"],"grading":"按部位分：近端（内侧 1/3）、中段（中 1/3）、远端（外侧 1/3）；远端骨折按 Neer 分型（Ⅰ 型：韧带间无移位；Ⅱ 型：喙锁韧带内侧移位；Ⅲ 型：关节内）；按移位程度分完全/不完全；按稳定性分稳定型与不稳定型。"},"ddx":[{"name":"肩锁关节脱位","point":"与肩锁关节脱位的鉴别：压痛局限于肩锁关节（锁骨远端），「钢琴键征」（压下锁骨远端松手后弹起）阳性，X 线见喙锁间距增宽；锁骨骨折可见骨折线。"},{"name":"肩关节脱位（or_dislocation）","point":"与肩关节脱位的鉴别：肩关节脱位呈「方肩」畸形、Dugas 征阳性，X 线见肱骨头脱出髋臼；锁骨骨折的畸形位于锁骨区，肱骨头位置正常。"},{"name":"肩袖损伤","point":"以主动活动受限但被动活动度接近正常、夜间痛为特征，无骨擦感，MRI 见肌腱撕裂。"},{"name":"肋骨骨折","point":"压痛点在肋骨、胸廓挤压试验阳性，深呼吸与咳嗽时加重，X 线见肋骨骨折线。"},{"name":"臂丛神经损伤","point":"感觉运动障碍是其核心，锁骨骨折可合并；但神经损伤早期需排除血肿压迫、骨折块压迫，需反复查体。"},{"name":"新生儿产伤假性瘫痪","point":"产伤性锁骨骨折多无需处理，需与臂丛损伤（Erb 麻痹：患肢内收内旋、不活动）鉴别，必要时肌电图。"}],"tx":{"drug":[{"name":"对乙酰氨基酚 / 布洛芬（镇痛）","dose":"对乙酰氨基酚 500–1000 mg q6h（日不超过 4 g）；布洛芬 400–600 mg q6–8h","note":"多模式镇痛基础；老年与肾功能不全者需调整","renal":"布洛芬在 eGFR <30 避免；对乙酰氨基酚 CrCl <30 延长给药间隔","hepatic":"对乙酰氨基酚肝病者日不超过 2 g","interact":"NSAIDs 与抗凝合用增加出血；与 ACEI/ARB 合用降低降压效果并增加肾损伤"},{"name":"阿片类（重度疼痛短期）","dose":"曲马多 50–100 mg q6h（最大 400 mg/d）；或羟考酮 5 mg q6h 短期","note":"仅在 NSAIDs 与对乙酰氨基酚不能控制时短期使用（尤其老年人避免长期）；注意便秘与跌倒风险","renal":"曲马多 CrCl <30 延长间隔","hepatic":"肝病者减量","interact":"曲马多与 SSRI 合用增加 5-HT 综合征与癫痫风险；与苯二氮卓类合用增加呼吸抑制"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟静脉滴注（体重 >80 kg 用 2 g）","note":"仅用于手术患者；开放性伤口或合并其他损伤时按情况延长","renal":"CrCl <30 术后减量","hepatic":"无需调整","interact":"与华法林合用增加出血（术后监测 INR）"},{"name":"钙剂与维生素 D（老年）","dose":"元素钙 500–1000 mg/d、维生素 D 800–1000 IU/d","note":"骨质疏松者的基础治疗，同时启动抗骨质疏松药（见骨质疏松条目）","renal":"肾功能不全慎用钙剂","hepatic":"无需调整","interact":"钙剂与铁剂、四环素间隔 2 小时"}],"nonDrug":["保守治疗（成人无移位或儿童）：**吊带固定 3–4 周**（儿童 2–3 周），手指与腕关节早期活动，2 周后复查 X 线","手术指征（成人）：短缩 >2 cm、完全移位、成角 >30°、皮肤帐篷征、神经血管受累、多发伤或肩胛带不稳定、骨不连","手术方式：**锁骨钩钢板或锁定钢板内固定**（中段）；远端骨折根据喙锁韧带状态选张力带或钩钢板","儿童：即使有移位也多可保守，锁骨再塑形能力强（婴幼儿几乎总能完全塑形）","术后康复：早期钟摆与被动活动，4–6 周后逐步增强，避免过早负重"],"life":["吊带期间注意腋下皮肤护理，避免压迫性溃疡","睡眠时半卧位或患侧垫枕，减轻牵拉痛","4–6 周复查 X 线评估骨痂，逐步恢复日常活动","术后 6–12 周内避免对抗性运动与提重物","戒烟（吸烟显著增加骨不连率，是锁骨骨不连的独立危险因素）"]},"prog":"儿童与无移位成人骨折保守治疗预后良好，骨不连率 <1%–3%。存在移位或短缩的成人锁骨骨折保守治疗骨不连率可达 5%–15%，手术可降低该风险。大多数患者肩关节功能可完全恢复；开放性骨折、合并神经血管损伤者预后较差。","refs":["《外科学》第 9 版（人民卫生出版社）上肢骨折章","《临床诊疗指南·骨科分册》（中华医学会）","2007 Orthopaedic Trauma Association (OTA) Fracture Classification","2018 Canadian Orthopaedic Trauma Society Clavicle Fracture Trial (COSTS) 长期随访"]},{"id":"or_humeral_proximal","name":"肱骨近端骨折","aka":["Proximal Humerus Fracture","PHF","Neer 分型"],"rank":2,"basic":{"define":"肱骨近端（外科颈、解剖颈、大结节、小结节）发生的骨折，是老年人第三常见骨折（仅次于髋部与桡骨远端），与骨质疏松密切相关。","risk":["老年女性（骨质疏松）","低能量跌倒（地面跌倒）","高能量外伤（青壮年：机动车、高处坠落）","肩关节脱位合并骨折","癫痫发作或电击（强烈肌肉收缩致骨折-脱位）"],"epi":"年发病率约 2–3/1000，60 岁以上显著升高（>60 岁女性可达 8/1000）。我国随人口老龄化，发病率持续上升。约 20% 合并肩袖损伤，约 10%–20% 为粉碎性四部分骨折。"},"patho":"肱骨近端由四个骨块组成（肱骨头、大结节、小结节、肱骨干），受肩袖肌肉牵拉各骨块移位方向不同：大结节受冈上肌牵拉向上后，小结节受肩胛下肌牵拉向前内，肱骨头多保持中立或旋转，肱骨干受胸大肌牵拉向内前。粉碎与移位程度决定肱骨头血供（前内侧动脉等）是否受损，进而决定肱骨头缺血坏死风险（四部分骨折可高达 30%–50%）。","dx":{"criteria":["外伤后肩部疼痛、肿胀、活动受限，可有皮下瘀斑与骨性隆起","X 线三位置（**肩关节正位、腋位或肩胛骨 Y 位**）：单一正位片易低估移位，必须要有两个互相垂直的投影","Neer 四部分分型：以移位 >1 cm 或成角 >45° 作为「分离骨块」的标准，按分离的骨块数分为一部分、二部分、三部分、四部分骨折","需警惕合并肩关节脱位（约 10%）、血管神经损伤（腋动脉与腋神经）","骨折-脱位：肱骨头向前或向后脱位，后脱位易漏诊（需腋位片与 CT）","CT（三维重建）：用于复杂性骨折的术前评估与分型"],"workup":["肩关节正位 + 腋位（或 Y 位）X 线","CT 三维重建（移位复杂、拟手术或分型不确定时）","腋神经功能评估（三角肌外侧皮肤感觉、外展力量）、桡动脉搏动","老年患者评估骨密度、跌倒原因（药物、眩晕、视力）","排除长骨其他部位与胸部合并损伤（高能量伤）"],"grading":"Neer 分型（一部分至四部分，另分骨折-脱位型）；AO/OTA 分型（11-A/B/C）；按是否累及解剖颈与肱骨头血供风险分级（解剖颈骨折、四部分骨折坏死率高）。"},"ddx":[{"name":"肩关节脱位（or_dislocation）","point":"与肩关节脱位的鉴别：脱位见「方肩」畸形、Dugas 征阳性，X 线见肱骨头脱出髋室；PHF 的肱骨头仍在关节内（除骨折-脱位型），可见骨折线。"},{"name":"肩袖撕裂","point":"以主动外展受限、夜间痛与「落臂征」为特征，无骨折线，MRI 见肌腱断裂。"},{"name":"锁骨骨折（or_clavicle）","point":"压痛在锁骨区，X 线见锁骨骨折线；PHF 的压痛在肩前外侧与肱骨近端。"},{"name":"肩关节骨关节炎","point":"慢性疼痛、活动受限、X 线见关节间隙变窄与骨赘，无急性外伤史与骨折线。"},{"name":"肱骨干骨折（or_humeral_shaft）","point":"疼痛与畸形位于上臂中段，需重点查桡神经；PHF 位于肩部、活动时肩部痛更明显。"},{"name":"肱骨近端病理性骨折","point":"有肿瘤病史或影像见骨质破坏区（溶骨或成骨），需与骨质疏松性骨折区分，必要时 MRI 与活检。"}],"tx":{"drug":[{"name":"多模式镇痛（对乙酰氨基酚 + NSAIDs）","dose":"对乙酰氨基酚 500–1000 mg q6h；布洛芬 400–600 mg q6–8h，或塞来昔布 200 mg bid","note":"老年患者尽量少用阿片类（跌倒、谵妄风险）；塞来昔布胃肠道耐受性更好","renal":"eGFR <30 避免 NSAIDs","hepatic":"对乙酰氨基酚日 ≤2 g（肝病）","interact":"NSAIDs 与抗凝、抗血小板合用增加出血；塞来昔布与华法林合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟静脉；MRSA 定植者改用万古霉素 15 mg/kg","note":"肩关节置换或内固定手术常规预防；术后 24 小时内停药","renal":"万古霉素按 CrCl 调整","hepatic":"无需调整","interact":"万古霉素与麻醉药（尤其肌松剂）需注意"},{"name":"抗骨质疏松治疗（老年基础治疗）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；唑来膦酸 5 mg 静脉每年 1 次或地舒单抗 60 mg 皮下每 6 个月","note":"**骨折后是启动抗骨质疏松治疗的最佳时机**（FLS 骨折联络服务），可显著降低再骨折风险；唑来膦酸需监测肾功能与血钙","renal":"唑来膦酸 CrCl <35 禁用；地舒单抗肾功能不全可用（注意低钙）","hepatic":"无需调整","interact":"地舒单抗与糖皮质激素合用增加低钙风险；停用地舒单抗需桥接双膦酸盐（否则椎体骨折反跳）"},{"name":"氨甲环酸（手术患者）","dose":"1 g 静脉术前 15–30 分钟，必要时术后 3 小时内再给 1 g","note":"减少围术期失血与输血需求；证据支持用于关节置换与创伤手术","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与抗凝药合用需权衡（活动性血栓者禁用）"}],"nonDrug":["保守治疗（一部分、二部分无显著移位、高龄不能耐受手术者）：**吊带固定 3–4 周，早期（1 周内）开始钟摆运动**，避免长期制动导致僵硬","手术指征：三/四部分骨折、移位 >1 cm 或成角 >45°、骨折-脱位、开放骨折、合并神经血管损伤、保守失败","手术方式：**锁定钢板切开复位内固定（ORIF）**（青壮年、骨质量好）；**反式肩关节置换（RSA）**（老年四部分骨折、骨质量差、肩袖功能差）；半肩置换适用于部分老年患者","经皮穿针或髓内钉（部分二部分骨折）","康复：保守者 1 周内开始被动前屈，4–6 周后主动活动；术后按固定强度分阶段"],"life":["骨折后立即进行跌倒风险评估与居家改造（防滑、夜间照明、扶手）","抗骨质疏松治疗与随访（骨密度 1–2 年复查）","戒烟限酒，保证蛋白与钙摄入","逐步恢复日常自理与肩关节功能锻炼（僵硬是常见后遗症，需坚持康复）","定期复查 X 线（2、6、12 周）评估骨痂与内固定位置"]},"prog":"一部分与二部分骨折保守治疗后约 80% 可获得良好功能（Mayo 肘关节或 Constant 评分）。三/四部分骨折术后功能恢复差异大，反式肩关节置换在老年患者中前屈与外展改善显著。肱骨头缺血坏死在四部分骨折与解剖颈骨折中风险最高（可达 30%–50%），术后需影像随访。整体 1 年死亡率（老年）约 5%–10%，与合并症和跌倒再发相关。","refs":["《外科学》第 9 版（人民卫生出版社）上肢骨折章","2015 AO Foundation Proximal Humerus Fracture Classification","2019 AAOS Clinical Practice Guideline: Management of Proximal Humerus Fractures","《中国骨质疏松性骨折诊疗指南》（中华医学会骨质疏松和骨矿盐疾病分会，2022）"]},{"id":"or_humeral_shaft","name":"肱骨干骨折","aka":["Humeral Shaft Fracture","桡神经损伤相关骨折"],"rank":3,"basic":{"define":"肱骨外科颈下 1–2 cm 至肱骨髁上之间的骨折，以中段最常见，是**桡神经损伤风险最高**的长骨骨折之一。","risk":["高能量外伤（机动车、运动）","老年人跌倒（尤其合并骨质疏松）","投掷运动（投掷骨折，螺旋形）","枪伤或开放性损伤"],"epi":"占全部骨折的 1%–3%，占肱骨骨折的 20%。桡神经损伤发生率约 8%–12%（闭合骨折约 6%，开放性可达 20%）。"},"patho":"肱骨干中段后方有桡神经沟，桡神经紧贴骨面绕行，故中段骨折（尤其螺旋形）极易损伤桡神经。骨折端受三角肌（近端外展）与胸大肌、背阔肌（远端内收）牵拉形成典型成角。血供方面，肱骨干有滋养动脉（中段进入），高能量骨折可破坏血供导致延迟愈合或不愈合（尤其横形、粉碎或分离明显的骨折）。","dx":{"criteria":["外伤后上臂肿胀、疼痛、畸形、异常活动与骨擦感","**必查桡神经功能**：腕背伸（垂腕）、拇指背伸与拇指外展、第一骨间背侧肌力量、虎口区皮肤感觉","X 线（正侧位，包含肩与肘关节）：评估骨折部位、类型（横形、斜形、螺旋形、粉碎）与移位","开放性骨折需记录伤口位置与污染程度（Gustilo 分型）","合并血管损伤：桡动脉搏动消失、前臂缺血表现（少见但需警惕）"],"workup":["肱骨正侧位 X 线（含肩、肘）","神经检查（桡神经为主，兼查正中与尺神经）","血管评估（脉搏、必要时多普勒或 CTA）","全身评估（多发伤时按 ATLS 流程）","术后或随访时肌电图（神经损伤 3–4 周后评估恢复）"],"grading":"按部位分近端（外科颈下 1/3）、中段（最常见）与远端（髁上）；按形态分横形、斜形、螺旋形、粉碎形；开放骨折用 Gustilo-Anderson 分型；桡神经损伤分暂时性神经失用（多在 3–4 个月恢复）与轴索断裂/断裂（需手术探查）。"},"ddx":[{"name":"肱骨近端骨折（or_humeral_proximal）","point":"与 PHF 的鉴别：PHF 位于肩部（外科颈以上），肩关节活动痛明显；肱骨干骨折位于上臂中段，肘与肩关节本身可被动活动。"},{"name":"锁骨骨折（or_clavicle）","point":"压痛在锁骨，X 线见锁骨骨折线，无垂腕。"},{"name":"肱骨远端（髁上）骨折","point":"疼痛与畸形靠近肘部，需查肱动脉与前臂筋膜室（骨筋膜室综合征风险）。"},{"name":"桡神经损伤（非骨折性）","point":"「星期六夜麻痹」（长时间压迫）、铅中毒或糖尿病性单神经病可有垂腕但无骨折，X 线与 MRI 可区分。"},{"name":"肱骨病理性骨折","point":"影像见溶骨破坏与皮质变薄，有肿瘤病史，需与原发或转移瘤鉴别。"},{"name":"肩袖损伤","point":"无畸形与骨擦感，主动外展受限但被动正常，X 线无骨折。"}],"tx":{"drug":[{"name":"多模式镇痛","dose":"对乙酰氨基酚 500–1000 mg q6h + 布洛芬 400–600 mg q6–8h（或塞来昔布 200 mg bid）","note":"神经损伤疼痛可加用加巴喷丁 300 mg qn 起始（滴定至 900–1800 mg/d）或普瑞巴林 75 mg bid","renal":"NSAIDs 与加巴喷丁均需按 CrCl 调整","hepatic":"对乙酰氨基酚限量","interact":"加巴喷丁与阿片类/苯二氮卓类合用增加呼吸抑制"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；开放性骨折按 Gustilo 分型加用氨基糖苷或延长疗程","note":"开放骨折需尽早（1–2 小时内）给药并彻底清创","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"骨形态发生蛋白或自体骨移植（骨不连）","dose":"用于骨折不愈合或延迟愈合的手术中，遵手术方案","note":"需评估不愈合原因（感染、血供、稳定性）","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**保守治疗（首选）**：功能性支具（Sarmiento 支具）或 U 形石膏，适用于无移位或可接受的对位（成角 <20°、短缩 <3 cm、旋转 <30°）；优点是不愈合率约 5%（与手术相近）且神经损伤多为暂时性","**手术指征**：骨折端分离 >3 cm、横形骨折（愈合慢）、病理性骨折、多发伤、双侧肱骨干骨折、开放骨折、血管损伤、**桡神经损伤见于开放骨折或闭合复位后加重**、保守治疗失败","手术方式：**髓内钉**（横形、粉碎）、**切开复位钢板螺丝钉**（ORIF，尤其远端或需要早期活动者）","桡神经处理：闭合骨折合并桡神经麻痹可先**观察 3 个月**（多数为神经失用，自发恢复率 >70%）；开放骨折或骨折端嵌压者应早期探查；3 个月无恢复迹象者行肌电图与神经探查","康复：早期手指、腕与肩关节主动活动（固定期间），骨折愈合后（6–8 周）逐步抗阻训练"],"life":["支具/石膏期间每周复查，注意腋下与肘部皮肤压疮","垂腕者使用腕手支具（防止腕部屈曲挛缩），并进行被动腕背伸练习","神经损伤后感觉缺失者注意保护患手（防烫伤与割伤）","戒烟（显著影响骨折愈合）","定期 X 线复查（2、4、8、12 周），关注延迟愈合（>4 个月无骨痂）"]},"prog":"保守治疗的不愈合率约 5%–10%（横形骨折与分离明显者更高），手术可达 >95% 愈合率。桡神经损伤约 70%–90% 在 3–6 个月内自发恢复（多为神经失用）；若持续不恢复需手术，神经移植后功能恢复约 60%–80%（以腕背伸恢复为指标）。合并血管损伤或开放污染者预后较差。","refs":["《外科学》第 9 版（人民卫生出版社）上肢骨折章","2020 AO Foundation Humeral Shaft Fracture Management Guidelines","2019 Journal of Orthopaedic Trauma: Humeral Shaft Fractures – Nonoperative versus Operative (systematic review)","《外周神经损伤临床诊疗指南》（中华医学会手外科学分会）"]},{"id":"or_supracondylar","name":"肱骨髁上骨折","aka":["Supracondylar Fracture","Gartland 分型","儿童肘部骨折"],"rank":4,"basic":{"define":"肱骨远端髁上部（鹰嘴窝水平）的骨折，是儿童最常见的肘部骨折（占儿童肘部骨折 60%–70%），也是儿童肘关节损伤中**最易并发骨筋膜室综合征与血管损伤**的骨折。","risk":["儿童（高峰 5–8 岁）","跌倒时肘部伸直、手掌着地（伸直型，占 95% 以上）","高能量跌落（高处、游乐设施）","肘部过伸体位"],"epi":"占儿童全部骨折的 3%，占儿童肘部骨折的 60%–70%。约 10%–20% 伴有不同程度的血管神经受累，骨筋膜室综合征发生率约 0.1%–1%（但后果严重）。"},"patho":"伸直型骨折远端向后移位，肱骨远端前方的肱动脉与正中神经可被近端骨块（骨折尖刺）压迫、牵拉甚至损伤。肱骨远端前方有肘前筋膜，后方有肱三头肌腱膜，骨折后出血与水肿使前臂筋膜室压力升高，形成骨筋膜室综合征（前臂与手部永久性缺血坏死风险）。肘内翻是晚期最常见的畸形（约 10%–30%，与复位不良与内侧柱塌陷有关）。","dx":{"criteria":["跌倒后肘部肿痛、拒动，可有畸形与假性瘫痪（哭闹、不愿用患肢）","**X 线（必需）**：肘关节正侧位，判断 Gartland 分型：","Gartland Ⅰ 型：无移位（侧位见前侧皮质完整）","Gartland Ⅱ 型：有移位但后侧皮质完整（需分 Ⅱa 无旋转、Ⅱb 有旋转、Ⅱc 完全移位）","Gartland Ⅲ 型：完全移位（骨皮质无接触）","**脂肪垫征（fat pad sign）**：侧位片见前方脂肪垫抬高（所谓「帆船征」）提示关节内积液/隐匿骨折，X 线看似正常但有此征时须按骨折处理","**必查血管与神经**：桡动脉搏动、手部毛细血管充盈、皮肤温度与颜色；正中神经（拇指对掌、示指感觉）与桡神经功能","警惕骨筋膜室综合征：前臂张力性肿胀、「5P」征（pain、pallor、paresthesia、paralysis、pulselessness）"],"workup":["肘关节正侧位 X 线（必要时对比健侧）","血管评估：桡动脉搏动、多普勒、必要时 CTA（脉弱或无脉）","神经查体记录（正中、桡、尺神经）","测前臂筋膜室压力（疑骨筋膜室综合征时，>30 mmHg 或舒张压差 <30 mmHg 需减压）","多发伤者按 ATLS 评估"],"grading":"Gartland 分型（Ⅰ、Ⅱ、Ⅲ，Ⅱ 型再分 a/b/c）；另有 Wilkins 改良分型与 Judet 分型（评估旋转）；血管损伤按有无脉搏分型（pink pulseless hand 与 pulseless hand 的处理不同）。"},"ddx":[{"name":"肱骨外髁骨折","point":"外侧肿胀与压痛，X 线见外髁骨块移位，属于关节内骨折（易致骨不连与肘外翻），处理与髁上骨折不同。"},{"name":"肘关节脱位（or_dislocation）","point":"儿童少见，肘关节对位关系丧失（桡骨头与肱骨小头不对应），可合并骨折。髁上骨折的关节对位正常（除完全移位）。"},{"name":"肱骨内上髁骨折","point":"内侧压痛，可伴尺神经损伤；X 线见内上髁撕脱或骨块进入关节。"},{"name":"桡骨小头半脱位（牵拉肘）","point":"幼儿被牵拉手臂后哭闹、不愿用患肢，X 线正常，手法复位（旋后屈肘）即刻恢复。"},{"name":"孟氏骨折（尺骨近端骨折合并桡骨头脱位）","point":"尺骨近端骨折 + 桡骨头脱位，需同时处理两处；与髁上骨折的 X 线表现不同。"},{"name":"肱骨远端骨骺分离","point":"婴幼儿（<2 岁）以软骨为主，X 线可能仅见肿胀，需超声或 MRI 确诊。"}],"tx":{"drug":[{"name":"镇痛（对乙酰氨基酚 / 布洛芬，按体重）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h（日不超过 75 mg/kg）；布洛芬 5–10 mg/kg q6–8h","note":"儿童镇痛基础；避免使用阿司匹林（瑞氏综合征）","renal":"肾功能不全慎用 NSAIDs","hepatic":"肝病者对乙酰氨基酚减量","interact":"布洛芬与糖皮质激素合用增加消化道出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 25–50 mg/kg 术前 30–60 分钟静脉（最大 1–2 g）","note":"用于闭合复位经皮克针固定或切开手术；克针留存期间注意针道护理与感染监测","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"镇静与镇痛（复位时）","dose":"氯胺酮 1–2 mg/kg 静脉（需监护），或丙泊酚 1–2 mg/kg（需气道管理）；联合芬太尼 1–2 µg/kg","note":"儿童闭合复位需充分镇静与镇痛，避免暴力复位加重血管损伤","renal":"遵说明书","hepatic":"遵说明书","interact":"氯胺酮与苯二氮卓类合用增加呼吸抑制"},{"name":"甘露醇（骨筋膜室综合征警觉期，慎用）","dose":"0.5–1 g/kg 静脉快速滴注（仅在减压准备期间短期使用）","note":"**不能替代筋膜切开减压**；仅在早期高张力、尚未达减压指征时短期使用并密切监测","renal":"少尿时禁用","hepatic":"无需调整","interact":"与肾毒性药物合用增加肾损伤"}],"nonDrug":["Gartland Ⅰ 型：**长臂石膏后托固定 3 周**（屈肘 90°），1 周复查 X 线","Gartland Ⅱ/Ⅲ 型：**闭合复位 + 经皮克针固定（CRPP）**，术后石膏固定 3–4 周，克针 3–4 周后拔除","Gartland Ⅲ 型伴血管损伤、开放骨折或复位失败：**急诊切开复位内固定**（探查肱动脉）","**Pink pulseless hand（手部灌注好但无脉）**：复位固定后观察，若灌注良好可保守；若灌注差或进行性缺血，需立即探查血管","**骨筋膜室综合征**：一旦确诊（压力 >30 mmHg 或临床明确）立即**前臂筋膜切开减压**，不得延误","肘内翻的预防：强调解剖复位（尤其内侧柱与冠状面力线），避免反复复位"],"life":["石膏固定期间每日检查手指血运、感觉与肿胀（家长教育，出现剧痛、苍白、麻木立即就诊）","克针针道护理：保持干燥，每周清洁，发现红肿渗液就诊","石膏拆除后开始肘关节屈伸与前臂旋转功能训练（避免暴力被动牵拉）","3、6、12 个月复查 X 线，评估提携角与有无肘内翻（必要时矯形）","避免过早恢复剧烈运动与跌倒（骨折愈合后 6–8 周再参与）"]},"prog":"Gartland Ⅰ 与 Ⅱ 型闭合复位后功能恢复优良率 >90%。Ⅲ 型治疗后约 10%–30% 出现肘内翻（多数为轻度，不影响功能）。骨筋膜室综合征若在 6–12 小时内减压，多数可避免永久性缺血损伤；延误可致 Volkmann 缺血性肌挛缩（严重残疾）。血管损伤及时修复者预后良好。","refs":["《外科学》第 9 版（人民卫生出版社）儿童骨折章","《实用骨科学》第 5 版（胥少汀等）","2018 AAOS Clinical Practice Guideline: The Treatment of Pediatric Supracondylar Humerus Fractures","2006 Gartland Classification of Supracondylar Fractures (original description and modifications)"]},{"id":"or_forearm_fx","name":"尺桡骨干骨折（含孟氏与盖氏损伤）","aka":["Forearm Fracture","Monteggia Fracture","Galeazzi Fracture","孟氏骨折","盖氏损伤"],"rank":5,"basic":{"define":"尺骨与桡骨干的骨折（双骨折或单骨折）。两种特殊类型：**孟氏骨折**（尺骨近端骨折 + 桡骨头脱位）与**盖氏损伤**（桡骨远端骨折 + 下尺桡关节脱位），因容易漏诊脱位而具有特殊临床意义。","risk":["儿童跌倒（手掌着地，双骨折多见）","高能量外伤（机动车、斗殴——所谓「警棍骨折」）","成人单骨骨折多为直接打击","骨质疏松（老年低能量跌倒）"],"epi":"前臂骨折占全部骨折的 10%–14%，儿童与青少年高发。孟氏骨折约占前臂骨折的 1%–2%（儿童中 Bado Ⅰ 型多见）；盖氏损伤占前臂骨折的 3%–7%。"},"patho":"前臂的旋转功能依赖尺桡骨之间的完整关系（上、下尺桡关节与骨间膜）。双骨折时骨间膜撕裂使旋转功能丧失，若复位不良（尤其旋转对位），将导致前臂旋前/旋后受限。孟氏骨折的机制是前臂极度旋前时跌倒，桡骨头向前脱位（Bado Ⅰ）或向后（Bado Ⅱ）；盖氏损伤为桡骨远端 1/3 骨折后下尺桡关节被撕裂，需同时修复。骨间膜与三角纤维软骨复合体（TFCC）的完整性决定预后。","dx":{"criteria":["外伤后前臂肿痛、畸形、旋转受限、异常活动","X 线（**必需包含肘与腕关节**）：正侧位，评估骨折部位、类型与旋转对位","**孟氏骨折的诊断条件**：尺骨近端骨折（任何类型）+ 桡骨头脱位。**关键线索：正位片见桡骨头未指向肱骨小头（桡骨头轴线不通过肱骨小头）**","**盖氏损伤**：桡骨远端 1/3 骨折 + 下尺桡关节分离（正位片见下尺桡间隙 >2 mm 或侧位见尺骨远端向背侧脱位）","儿童：桡骨头可因弹性回位而自动复位，易漏诊（需拍摄对侧对比）","软组织评估：前臂肿胀程度、神经血管（正中、尺、桡神经；桡动脉）"],"workup":["前臂正侧位 X 线（含肘腕关节，必要时双侧对比）","必要时 CT（复杂骨折、关节内受累、术前规划）","神经血管查体（桡/尺动脉、正中/尺神经）","评估骨筋膜室压力（高能量骨折、严重肿胀者）","开放骨折行清创与细菌培养"],"grading":"双骨折按部位（近、中、远 1/3）与类型（横形、斜形、粉碎）分；孟氏骨折按 **Bado 分型**（Ⅰ 型：桡骨头前脱位 + 尺骨近端前成角；Ⅱ 型：后脱位；Ⅲ 型：外侧脱位；Ⅳ 型：双骨骨折 + 桡骨头骨折/脱位）；盖氏损伤按是否合并 TFCC 撕裂分级。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与桡骨远端骨折的鉴别：后者位于腕部，远端骨折块向背侧（Colles）或掌侧（Smith）移位；盖氏损伤的桡骨骨折在远端 1/3 且伴下尺桡关节脱位。"},{"name":"肱骨髁上骨折（or_supracondylar）","point":"疼痛与畸形靠近肘部，X 线见髁上骨折线；前臂骨折位于尺桡骨，肘关节对位正常。"},{"name":"肘关节脱位（or_dislocation）","point":"肘关节对位丧失（桡骨头与肱骨小头不对应），可无骨折；孟氏骨折为尺骨骨折伴桡骨头脱位（肘关节本身对位可正常）。"},{"name":"桡骨小头半脱位（牵拉肘）","point":"幼儿牵拉后哭闹、不愿用患肢，X 线正常（无骨折），手法复位即刻恢复。"},{"name":"前臂骨筋膜室综合征","point":"张力性肿胀与「5P」征，需急诊减压；可继发于双骨折，两者需同时评估。"},{"name":"病理性骨折","point":"影像见骨质破坏，有肿瘤或代谢性骨病史，需与原发或转移瘤鉴别。"}],"tx":{"drug":[{"name":"多模式镇痛","dose":"对乙酰氨基酚 500–1000 mg q6h + 布洛芬 400–600 mg q6–8h；必要时短期阿片类","note":"缓解疼痛利于早期功能锻炼","renal":"NSAIDs 按 CrCl 调整","hepatic":"对乙酰氨基酚限量","interact":"NSAIDs 与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟静脉；开放骨折按 Gustilo 加用氨基糖苷并延长","note":"开放骨折需 1–2 小时内给药并彻底清创","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"抗骨质疏松（老年患者）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；唑来膦酸 5 mg/年或地舒单抗 60 mg/6 月","note":"老年低能量骨折提示骨质疏松，需启动治疗以防再骨折","renal":"唑来膦酸 CrCl <35 禁用","hepatic":"无需调整","interact":"地舒单抗停用需桥接"}],"nonDrug":["**成人双骨折：切开复位加压钢板内固定（ORIF）为金标准**（前臂旋转功能要求解剖复位），术后早期（1–2 周）开始手指与腕活动","**儿童双骨折**：多数可闭合复位 + 长臂石膏固定（可接受成角 ≤10°、旋转 ≤30°，再塑形能力强）；不稳定或复位失败者用弹性髓内钉","**孟氏骨折**：成人 ORIF 尺骨 + 桡骨头复位（必要时环状韧带修复）；儿童多数可闭合复位 + 石膏（Bado Ⅰ 型），桡骨头需确认复位","**盖氏损伤**：桡骨 ORIF + 下尺桡关节复位固定（必要时 TFCC 修复或克针固定 4–6 周）","合并骨筋膜室综合征：急诊筋膜切开","康复：术后 4–6 周开始前臂旋转训练，逐步抗阻"],"life":["石膏或支具期间抬高患肢减轻肿胀，注意手指血运与感觉","戒烟（显著影响骨折愈合）","固定期间进行手指、肩、腕的主动活动防止僵硬","术后 2、6、12 周复查 X 线，评估对位与骨痂","恢复期避免提重物与对抗性运动（一般 3 个月后）"]},"prog":"成人双骨折 ORIF 后愈合率 >95%，前臂旋转功能优良率约 85%–90%。孟氏骨折若漏诊桡骨头脱位，可致慢性肘痛与活动受限（故强调 X 线必须包含肘关节）。盖氏损伤漏诊下尺桡脱位可致腕痛与握力下降。儿童再塑形能力强，预后多良好。骨筋膜室综合征是影响预后的关键并发症。","refs":["《外科学》第 9 版（人民卫生出版社）前臂骨折章","《实用骨科学》第 5 版","1998 Bado Classification of Monteggia Fracture-Dislocations","2016 Journal of Hand Surgery: Galeazzi Fracture-Dislocations – A Systematic Review"]},{"id":"or_scaphoid","name":"腕舟骨骨折","aka":["Scaphoid Fracture","舟状骨骨折","腕骨骨折"],"rank":6,"basic":{"define":"腕舟骨（最大的腕骨，连接近排与远排）的骨折，是腕部最常见的腕骨骨折。因血供主要从远端进入（逆行供血），近极骨折易发生缺血性坏死与不愈合。","risk":["青年男性（20–30 岁高峰）","跌倒时手掌撑地（FOOSH 损伤）","竞技运动（滑雪、滑板、篮球）","机动车事故"],"epi":"占腕骨骨折的 60%–70%，年发病率约 1.2/1000。约 10%–20% 因早期 X 线阴性而漏诊，导致不愈合与缺血坏死。"},"patho":"舟骨的血供约 80% 来自桡动脉分支经背侧嵴进入，且为**逆行血流**（从远端向近端），故近极骨折（近 1/3）的血供被切断，缺血坏死风险最高（可达 30%–40%）。舟骨跨越腕中关节，其完整性对腕关节生物力学至关重要；不愈合将导致腕关节不稳（SNAC）与进行性骨关节炎。","dx":{"criteria":["跌倒后腕部疼痛，**鼻烟窝压痛**（最重要体征）、舟骨结节压痛、腕背伸时疼痛","X 线（**四位置**）：正位、侧位、**舟骨位（腕关节尺偏后前位）**、旋前斜位。四位置联合可提高检出率，但早期（伤后 1–2 周）X 线阴性率仍达 20%–30%","**关键原则：X 线阴性但临床高度怀疑时，按骨折处理**——石膏/支具制动 2 周后复查 X 线，或直接行 CT/MRI（MRI 敏感度 >95%，是早期确诊金标准）","晚期表现：腕关节桡侧疼痛、握力下降、活动受限","并发症筛查：缺血性坏死（近极骨折）、不愈合（纤维性连接伴疼痛）"],"workup":["腕关节四位置 X 线（含舟骨位）","必要时 CT（评估骨折线与愈合、皮质骨桥）或 MRI（早期诊断与评估血供/坏死）","骨扫描（敏感性高但特异性低，现已少用）","腕关节镜（用于评估不愈合与软骨损伤）","长期不愈合者评估 SNAC 腕关节炎分期"],"grading":"按部位分：结节（远 1/3）、腰部（中 1/3，最常见约 70%）、近极（近 1/3，坏死风险最高）；按骨折线方向分稳定（横行）与不稳定（斜行，与腕关节活动方向呈夹角）；按病程分急性（<4 周）、延迟（4–12 周）、不愈合（>12 周或 6 个月）；Herbert 分型（A/B/C/D）与 Mayo 分型常用于研究。"},"ddx":[{"name":"桡骨远端骨折（or_distal_radius）","point":"与桡骨远端骨折的鉴别：后者压痛在桡骨远端与腕背，X 线见桡骨远端骨折线；舟骨骨折的压痛主要在鼻烟窝，X 线需舟骨位才易显示。"},{"name":"舟骨-月骨分离（SL 韧带损伤）","point":"腕关节疼痛与弹响，X 线（握拳位）见舟月间隙增宽（Terry Thomas 征 >3 mm），MRI 或关节镜确诊；无骨折线。"},{"name":"三角纤维软骨复合体（TFCC）损伤","point":"尺侧腕痛、旋转时加重，MRI 见 TFCC 撕裂；舟骨骨折以桡侧痛为主。"},{"name":"第一掌骨基底骨折（Bennett/Rolando）","point":"拇指基底压痛与活动痛，X 线见第一掌骨基底骨折，不在舟骨位置。"},{"name":"腕关节扭伤","point":"排除性诊断；X 线与 MRI 均无骨质异常，但若鼻烟窝压痛明显仍需按隐匿舟骨骨折处理并复查。"},{"name":"月骨缺血性坏死（Kienböck 病）","point":"腕背中央痛、MRI 见月骨信号异常，与舟骨骨折部位不同。"}],"tx":{"drug":[{"name":"镇痛（对乙酰氨基酚 / 布洛芬）","dose":"对乙酰氨基酚 500–1000 mg q6h；布洛芬 400–600 mg q6–8h","note":"对症处理；疼痛持续提示可能存在不愈合或坏死","renal":"NSAIDs 按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟","note":"用于经皮或切开内固定、植骨手术","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"骨形态发生蛋白/自体骨移植（不愈合）","dose":"手术中植入（带血管蒂骨移植或游离骨块）","note":"不愈合的标准治疗为植骨 + 内固定；带血管蒂移植用于近极坏死","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**无移位（稳定）骨折：长臂或短臂拇指人字形石膏/支具固定 6–10 周**（含拇指掌指关节），每 2–4 周复查 X 线确认无移位","**移位 >1 mm、不稳定或近极骨折：经皮或切开复位螺钉内固定**（可缩短固定时间、提高愈合率）","**不愈合：切开复位 + 自体骨移植 + 内固定**（愈合率可达 90% 以上）","**近极缺血性坏死：带血管蒂骨移植（如 1,2-ICSRA）或腕骨部分切除**","康复：固定期间活动手指与肘肩；拆除固定后逐步腕关节活动与握力训练"],"life":["石膏期间保持干燥，注意拇指与腕部皮肤护理","严格遵守固定时长（过早活动是不愈合的重要原因）","戒烟（吸烟显著增加不愈合率，是独立危险因素）","定期复查 X 线（每 2–4 周）直至骨折线消失或可见骨桥","运动员需在影像确认愈合后方可恢复对抗性运动（通常 3–6 个月）"]},"prog":"无移位腰部骨折保守治疗愈合率约 90%–95%；移位 >1 mm 者不愈合风险显著增加（可达 30%–50%）。近极骨折缺血坏死率约 30%–40%，即使愈合也可能晚期塌陷。不愈合可致腕关节 SNAC 骨关节炎、持续疼痛与握力下降。早期诊断与规范固定是改善预后的关键。","refs":["《外科学》第 9 版（人民卫生出版社）腕部骨折章","《实用骨科学》第 5 版","2010 Journal of the American Academy of Orthopaedic Surgeons: Scaphoid Fractures – Diagnosis and Management","2019 British Society for Surgery of the Hand Evidence for Surgical Treatment (BEST) – Scaphoid Fracture"]}]},{"id":"fracture_lower_more","name":"下肢与骨盆骨折","rank":8,"summary":"下肢骨折先看「是否能负重」与「关节面是否受累」：关节面台阶 >2 mm 需解剖复位；骨盆骨折先看血流动力学——不稳定骨盆骨折首要是止血（骨盆带、外固定、血管造影栓塞），而不是先拍片分型。","compare":[{"diseaseId":"or_femur_shaft","dx":"大腿中段肿痛畸形、短缩与外旋，X 线见股骨干骨折；需查股动脉与坐骨神经","key":"股骨干骨折出血量大（可达 1–2 L），是脂肪栓塞与休克的高危骨折"},{"diseaseId":"or_patella","dx":"膝前肿痛、不能主动伸膝、可触及骨折间隙，X 线见髌骨分离 >3 mm 或关节面台阶","key":"分离 >3 mm 或关节面不平整需手术；伸膝装置完整性决定术式"},{"diseaseId":"or_tibial_plateau","dx":"膝部轴向暴力后肿痛、关节积血，CT 见平台劈裂或塌陷（Schatzker 分型）","key":"关节面台阶 >2 mm 或髁部塌陷需手术支撑；常合并半月板与韧带损伤"},{"diseaseId":"or_ankle_fx","dx":"踝部肿痛、畸形与压痛，X 线按 Lauge-Hansen 机制与 Danis-Weber 分类","key":"核心是「踝穴解剖复位」；后踝 >25% 关节面或踝穴不稳需手术"},{"diseaseId":"or_calcaneus","dx":"高处坠落足跟着地后跟部肿痛、足跟增宽，X 线见 Böhler 角 <20°、Gissane 角异常","key":"常为高处坠落伤，需同时排查腰椎与骨盆骨折；皮肤条件决定手术时机"},{"diseaseId":"or_pelvic_fx","dx":"高能量外伤后骨盆区疼痛，X 线/CT 见环断裂；血流动力学不稳定者血压难维持","key":"血流动力学不稳定是首要矛盾——骨盆带固定 + 外固定 + 血管造影栓塞，先救命后分型"}],"diseases":[{"id":"or_femur_shaft","name":"股骨干骨折","aka":["Femoral Shaft Fracture","股骨干骨折"],"rank":1,"basic":{"define":"股骨小转子下 5 cm 至股骨髁上 5 cm 之间的骨干骨折，多为高能量创伤所致，因股骨周围肌肉丰厚、血供丰富，骨折后出血量大，是**失血性休克与脂肪栓塞的高危骨折**。","risk":["高能量创伤（机动车事故、高处坠落）","老年人低能量跌倒（骨质疏松，多为横形或斜形）","病理性骨折（骨转移瘤、Paget 病）","运动损伤（少见，多为疲劳骨折）"],"epi":"占全身骨折的 1%–3%，多见于青壮年男性。闭合性股骨干骨折的平均失血量约 1–1.5 L（可达循环血量的 20%–30%），开放性骨折出血更多。"},"patho":"股骨周围有丰富的肌群与滋养动脉（第二穿动脉为主要血供），骨折后肌肉断端出血形成大血肿，加上骨膜与骨髓出血，可致显著失血与休克。骨折端受肌肉牵拉形成典型畸形：近折端受髂腰肌与臀中肌牵拉屈曲外展，远折端受内收肌群牵拉内收，故表现为短缩与外旋畸形。髓腔内脂肪与骨髓进入撕裂的静脉窦可致**脂肪栓塞综合征**（多发生于伤后 24–72 小时）。股动脉与坐骨神经可被骨折端压迫或刺伤。","dx":{"criteria":["外伤后大腿疼痛、肿胀、畸形、异常活动与骨擦感，患肢短缩与外旋","**X 线（正侧位，含髋与膝）**：评估骨折部位（近、中、远 1/3）、类型（横形、斜形、螺旋形、粉碎）与移位","**必查血管与神经**：足背动脉与胫后动脉搏动、远端毛细血管充盈、坐骨神经与腓总神经功能（足背伸、感觉）","**血流动力学评估**：脉搏、血压、血红蛋白与乳酸（警惕失血性休克）","开放骨折需记录伤口与 Gustilo 分型","**警惕脂肪栓塞**：伤后 24–72 小时出现呼吸困难、意识障碍与瘀点疹（胸前、腋下、结膜）","老年人需排查病理性骨折（影像见骨质破坏区）"],"workup":["股骨正侧位 X 线（含髋关节与膝关节，避免漏诊合并损伤）","血管评估（脉搏、多普勒、必要时 CTA）","血常规、凝血、血型与交叉配血（**失血量大，需备血**）、乳酸","胸部 CT 或胸片（多发伤筛查，脂肪栓塞评估）","全身创伤评估（按 ATLS 流程，注意合并颅脑、胸部与腹部损伤）","术前：心电图、肝肾功能（老年人）"],"grading":"按部位分近端（转子下）、中段、远端（髁上）；按形态分横形、斜形、螺旋形、粉碎形、节段形；按 AO/OTA 分型（32-A/B/C）；开放骨折用 Gustilo-Anderson 分型。"},"ddx":[{"name":"股骨转子间骨折（or_intertroch）","point":"与转子间骨折的鉴别：转子间骨折位于髋部（股骨颈基底部至小转子），表现为患肢短缩外旋（可达 90°）、髋部压痛；股骨干骨折的畸形位于大腿中段，髋部本身无压痛。"},{"name":"股骨颈骨折（or_femur_neck）","point":"股骨颈骨折为囊内骨折，患肢短缩外旋（约 45°–60°）、腹股沟中点压痛，X 线见股骨颈骨折线；股骨干骨折在骨干。"},{"name":"髌骨骨折（or_patella）","point":"疼痛与肿胀在膝前，不能主动伸膝；股骨干骨折位于大腿，膝关节可主动活动（除合并损伤）。"},{"name":"胫骨平台骨折（or_tibial_plateau）","point":"膝部轴向暴力后关节积血与关节面塌陷；股骨干骨折为骨干骨折，关节面完整。"},{"name":"踝部骨折（or_ankle_fx）","point":"疼痛与畸形在踝部，X 线见踝部骨折；股骨干骨折的远端血运与神经需评估但踝部本身无骨折。"},{"name":"骨盆骨折（or_pelvic_fx）","point":"骨盆环骨折，可伴血流动力学不稳定；股骨干骨折的骨盆本身完整（但高能量伤可同时存在）。"},{"name":"病理性骨折（骨转移）","point":"影像见溶骨性破坏、皮质中断，有肿瘤病史；需与原发创伤性骨折区分并评估原发灶。"}],"tx":{"drug":[{"name":"镇痛（多模式，含阿片类）","dose":"对乙酰氨基酚 1 g q6h + 布洛芬 400–600 mg q6–8h；剧痛用吗啡 3–5 mg 静脉滴定或芬太尼","note":"严重创伤疼痛剧烈，需充分镇痛；注意低血容量时的低血压与呼吸抑制","renal":"NSAIDs 在低血容量/肾功能不全时避免","hepatic":"对乙酰氨基酚限量","interact":"阿片类与镇静药合用增加呼吸抑制"},{"name":"氨甲环酸（抗纤溶）","dose":"1 g 静脉 10 分钟内（伤后 3 小时内给药效果最佳），随后 1 g 输注 8 小时","note":"**创伤出血可降低病死率**（CRASH-2 研究）；不增加血栓风险；开放骨折与大量输血时尤其适用","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与抗凝药合用需权衡（活动性血栓者禁用）"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟（体重 >80 kg 用 2 g）；开放骨折按 Gustilo 分型（Ⅲ 型加氨基糖苷或延长）","note":"**开放骨折需在 1 小时内给药**并彻底清创；闭合骨折 24 小时内停药","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"低分子肝素（静脉血栓预防）","dose":"依诺肝素 40 mg 皮下 qd（术后或入院后 12–24 小时开始，视出血风险）","note":"**骨盆与下肢骨折是 VTE 高危**，需机械 + 药物预防；有出血风险时先用机械预防","renal":"CrCl <30 减为 30 mg qd","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"高渗盐水 / 甘露醇（脂肪栓塞，谨慎）","dose":"仅在明确脑水肿时使用，遵重症方案","note":"脂肪栓塞的核心治疗是**支持治疗（氧疗、机械通气）**，激素与肝素证据不足，不推荐常规使用","renal":"少尿时禁用甘露醇","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**急救：患肢临时固定（夹板或牵引）以减少出血与疼痛**；开放骨折覆盖无菌敷料，不现场复位","**液体复苏与输血**（按 ATLS 原则，限制性液体复苏至血压允许范围内）","**手术固定**：闭合复位髓内钉（**金标准**，适用于大多数股骨干骨折）；钢板螺钉（远端或髓腔狭窄/感染时）；外固定架（严重开放、污染或多发伤 Damage Control）","**开放骨折**：急诊清创（6–8 小时内）+ 抗生素 + 稳定固定","**脂肪栓塞**：以支持治疗为主（氧疗、必要时机械通气）","老年人病理性骨折：髓内钉 + 骨水泥强化，评估原发肿瘤"],"life":["**绝对戒烟**（显著影响骨折愈合）","术后早期功能锻炼（股四头肌等长收缩、踝泵），防肌肉萎缩与 VTE","负重时间依固定方式与影像决定（髓内钉通常 6–12 周部分负重）","**VTE 预防持续至术后 4–6 周**（下肢骨折为高危）","营养支持（蛋白与钙），老年患者启动抗骨质疏松治疗","定期复查 X 线（4、8、12、24 周）评估骨痂与内固定"]},"prog":"髓内钉固定后愈合率 >95%，不愈合率约 2%–5%（开放骨折与吸烟者更高）。**主要风险在于伤后早期的失血性休克与脂肪栓塞**，及时固定可显著降低。功能恢复通常良好（多数在 6 个月内恢复日常活动），但肌肉力量恢复需 1 年以上。开放骨折的感染率约 5%–15%（随 Gustilo 分级升高）。","refs":["《外科学》第 9 版（人民卫生出版社）下肢骨折章","2014 CRASH-2 Trial: Tranexamic Acid in Trauma Patients (Lancet)","2018 AO Foundation Femoral Shaft Fracture Management (AO Surgery Reference)","《中国创伤性休克与骨盆骨折诊疗指南》（2021）"]},{"id":"or_patella","name":"髌骨骨折","aka":["Patella Fracture","膝盖骨骨折"],"rank":2,"basic":{"define":"髌骨（人体最大的籽骨，位于股四头肌腱内）的骨折，按形态分为横形（最常见）、粉碎性、纵形（边缘型）与撕脱型。髌骨是伸膝装置的重要组成部分，其完整性决定能否主动伸膝。","risk":["直接暴力（膝前撞击，如跌落时膝着地、仪表盘伤）——多为粉碎性","间接暴力（股四头肌突然强力收缩，如跌倒时为防摔倒而猛力伸膝）——多为横形","骨质疏松（老年人）","膝关节手术史（人工关节置换后髌骨骨折）"],"epi":"占全身骨折的 1%，占膝关节周围骨折的约 10%。多见于 20–50 岁男性（高能量）与老年人（低能量跌倒）。约 30%–40% 为粉碎性。"},"patho":"髌骨在伸膝过程中作为支点增加股四头肌的力臂。骨折后伸膝装置可能失效：横形骨折时股四头肌牵拉近端骨块向上移位（分离），若分离 >3 mm 或关节面台阶 >1–2 mm，将导致伸膝无力与创伤性髌股关节炎。粉碎性骨折的关节面破坏更严重，且骨折块血供差（髌骨为无骨膜覆盖，血供主要来自膝周血管网）。**开放性骨折**（直接暴力致皮肤破裂）感染风险高。","dx":{"criteria":["膝前疼痛、肿胀、压痛，**不能主动伸膝（伸膝装置失效的关键体征）**","可触及骨折间隙与浮髌试验阳性（关节积血）","**X 线（正侧位 + 轴位，即日出位）**：见骨折线、分离距离与关节面台阶；纵形骨折在正位片易漏诊（需轴位片）","**分离 >3 mm 或关节面台阶 >1–2 mm 为手术指征**","需排除双侧髌骨（先天性）与二分髌骨（副骨化中心，边缘光滑、无骨折线）","疑软组织损伤或游离骨块时行 MRI","**开放性骨折**需记录伤口并清创"],"workup":["膝关节正侧位 + 髌骨轴位（日出位）X 线","CT（粉碎性骨折、术前规划）","MRI（疑软骨、韧带合并损伤或纵形骨折）","膝关节穿刺（张力性关节积血时减压，可送检脂肪滴——提示骨折）","血管神经检查（膝关节周围）与伤口评估","老年患者评估骨密度与跌倒原因"],"grading":"按形态分：横形、粉碎性、纵形（边缘）、撕脱型（上下极）、星状；按分离程度分无移位（<3 mm）与移位；按关节面受累分关节内与关节外；开放骨折用 Gustilo 分型。"},"ddx":[{"name":"股骨干骨折（or_femur_shaft）","point":"与股骨干骨折的鉴别：疼痛与畸形位于大腿中段，膝关节本身可主动活动；髌骨骨折在膝前、不能主动伸膝。"},{"name":"胫骨平台骨折（or_tibial_plateau）","point":"轴向暴力致关节面塌陷，压痛在胫骨近端，X 线/CT 见平台骨折；髌骨骨折的压痛在髌骨本身。"},{"name":"踝部骨折（or_ankle_fx）","point":"疼痛在踝部；与髌骨骨折部位不同。"},{"name":"骨盆骨折（or_pelvic_fx）","point":"骨盆区疼痛与血流动力学不稳定；与膝关节无关。"},{"name":"股四头肌腱断裂或髌腱断裂","point":"不能主动伸膝，但 X 线见髌骨位置异常（髌骨上移或下移）而无骨折；MRI 见肌腱断裂。**这是最需鉴别的软组织损伤**。"},{"name":"二分髌骨","point":"先天性变异（多在外上极），边缘光滑、双侧对称、无骨折线与急性压痛；无需处理。"},{"name":"膝关节骨关节炎（or_knee_oa）","point":"慢性疼痛、活动后加重、X 线见关节间隙变窄与骨赘；无急性骨折线。"}],"tx":{"drug":[{"name":"镇痛（多模式）","dose":"对乙酰氨基酚 1 g q6h + 布洛芬 400–600 mg q6–8h；剧痛可短期阿片类","note":"关节积血张力高时先行穿刺减压以缓解疼痛","renal":"NSAIDs 按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；开放骨折按 Gustilo 延长","note":"髌骨位置表浅，开放骨折与术后感染风险相对高","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg 皮下 qd，术后 12–24 小时开始（视出血风险）","note":"膝关节手术与下肢制动是 VTE 危险因素","renal":"CrCl <30 减为 30 mg qd","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**无移位（分离 <3 mm、关节面平整）**：长腿石膏或支具伸直位固定 4–6 周，早期可部分负重，逐步功能锻炼","**移位或关节面不平（手术指征）**：张力带钢丝（横形骨折）、空心螺钉（简单横形）、**髌骨环扎或钢板（粉碎性）**、部分髌骨切除（小骨块无法固定）","**全髌骨切除**：仅用于严重粉碎无法重建者（伸膝力减弱约 30%–40%）","开放骨折：急诊清创 + 内固定 + 抗生素","康复：术后早期被动活动与股四头肌等长收缩，逐步增加活动度（避免过早负重导致内固定失效）"],"life":["**避免长期制动**（可致膝关节僵硬与肌肉萎缩）","康复训练需坚持 3–6 个月（股四头肌力量恢复是功能关键）","术后 6–12 周内避免跪姿与深蹲","老年患者防跌倒（家居改造、助行器）与抗骨质疏松治疗","定期复查 X 线评估骨痂与内固定位置"]},"prog":"无移位骨折保守治疗的功能恢复优良率 >90%；手术固定后约 80%–90% 获得良好功能。**并发症包括膝关节僵硬（最常见）、内固定物刺激（约 20%–30% 需二次取出）、创伤性髌股关节炎与不愈合（＜5%）**。粉碎性与开放骨折预后相对差。","refs":["《外科学》第 9 版（人民卫生出版社）膝关节周围骨折章","2020 AO Foundation Patella Fracture Management (AO Surgery Reference)","《实用骨科学》第 5 版（胥少汀等）髌骨骨折章"]},{"id":"or_tibial_plateau","name":"胫骨平台骨折","aka":["Tibial Plateau Fracture","Schatzker 分型"],"rank":3,"basic":{"define":"胫骨近端关节面（内、外侧平台）的骨折，多为膝关节遭受轴向或外翻/内翻暴力所致，属**关节内骨折**，治疗核心是恢复关节面平整与下肢力线，以防止创伤性关节炎。","risk":["高能量创伤（机动车、高处坠落）——多为复杂骨折","老年人低能量跌倒（骨质疏松）——多为外侧平台劈裂或塌陷","运动损伤（滑雪、坠落时膝受力）","合并韧带或半月板损伤（约 50% 患者存在）"],"epi":"占全身骨折的 1%–2%，占膝关节周围骨折的 8%。高能量损伤多见于青壮年男性，低能量损伤多见于骨质疏松的老年人。约 10%–30% 合并血管损伤（高能量骨折，尤其 Schatzker Ⅳ/Ⅴ/Ⅵ 型）。"},"patho":"膝关节的轴向暴力使股骨髁撞击胫骨平台，导致劈裂、塌陷或两者兼有（Schatzker 分型基础）。外侧平台因骨质疏松更易塌陷；内侧平台骨折多提示更高能量损伤，且常伴韧带断裂与腓总神经/腘动脉损伤。关节面塌陷与不平整直接导致接触应力异常，是**创伤性关节炎**的病理基础（塌陷 >2 mm 即显著增加关节炎风险）。膝关节周围软组织薄、术后肿胀与伤口并发症率高。","dx":{"criteria":["膝关节外伤后肿胀、疼痛、不能负重，关节积血（浮髌试验阳性）","**X 线（正侧位 + 斜位）**：见平台劈裂、塌陷或粉碎；需评估髁部宽度与关节面","**CT（平扫 + 三维重建，必需）**：明确骨折形态、关节面塌陷程度与骨块位置，是 Schatzker 分型与手术规划的依据","**Schatzker 分型**：Ⅰ 型——外侧平台单纯劈裂；Ⅱ 型——外侧平台劈裂 + 塌陷；Ⅲ 型——外侧平台单纯塌陷；Ⅳ 型——内侧平台骨折；Ⅴ 型——双平台骨折；Ⅵ 型——双平台骨折伴干骺端与骨干分离","**血管神经评估**：足背动脉与胫后动脉搏动、腓总神经功能（尤其 Ⅳ/Ⅴ/Ⅵ 型）","MRI（评估半月板、韧带与软骨合并损伤）","需警惕骨筋膜室综合征（小腿肿胀进行性加重）"],"workup":["膝关节正侧位 + 斜位 X 线","**CT 三维重建（必需）**","MRI（韧带与半月板评估，尤其拟行关节镜时）","血管评估（脉搏、多普勒、必要时 CTA——高能量骨折血管损伤率 10%–30%）","腓总神经功能检查（足背伸、感觉）","小腿骨筋膜室压力监测（高度肿胀时）","全身创伤评估（高能量伤按 ATLS）"],"grading":"**Schatzker 分型（Ⅰ–Ⅵ 型）** 是临床与手术决策的核心；AO/OTA 分型（41-B/C）；按软组织条件评估（Tscherne 分型），决定手术时机。"},"ddx":[{"name":"股骨干骨折（or_femur_shaft）","point":"疼痛与畸形位于大腿中段；胫骨平台骨折在膝关节、关节内有积血与塌陷。"},{"name":"髌骨骨折（or_patella）","point":"压痛在髌骨前、不能主动伸膝；胫骨平台骨折的压痛在膝关节线附近，伸膝装置多完整。"},{"name":"踝部骨折（or_ankle_fx）","point":"疼痛在踝部；与膝部无关。"},{"name":"骨盆骨折（or_pelvic_fx）","point":"骨盆区痛与血流动力学不稳定；与膝部无关。"},{"name":"膝关节韧带损伤（ACL/半月板）","point":"可有关节积血与不稳，但 X 线/CT 无骨折；需 MRI 区分（两者常合并）。"},{"name":"股骨髁骨折","point":"骨折在股骨远端，CT 可明确区分（术前必需）。"},{"name":"骨筋膜室综合征（or_compartment）","point":"小腿进行性肿胀、被动牵拉痛与神经改变，可继发于平台骨折，需紧急减压。"}],"tx":{"drug":[{"name":"镇痛与关节减压","dose":"对乙酰氨基酚 1 g q6h + 布洛芬 400–600 mg q6–8h；张力性关节积血行穿刺减压","note":"关节积血张力高时穿刺可显著缓解疼痛并降低骨筋膜室压力","renal":"NSAIDs 按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；开放骨折按 Gustilo 延长","note":"**胫骨平台骨折的伤口并发症率高，规范预防很重要**","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg qd 皮下，术后或入院后 12–24 小时开始","note":"下肢骨折与制动是 VTE 高危；持续至术后 4–6 周","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"抗骨质疏松（老年患者）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；唑来膦酸 5 mg/年或地舒单抗 60 mg/6 月","note":"老年低能量平台的塌陷常与骨质疏松相关，需同步治疗","renal":"唑来膦酸 CrCl <35 禁用","hepatic":"无需调整","interact":"地舒单抗停用需桥接"}],"nonDrug":["**无移位或塌陷 <2 mm**：非手术（长腿支具、避免负重 6–8 周、早期被动活动）","**手术指征**：关节面塌陷 >2 mm、髁部增宽 >5 mm、膝关节不稳、髁间棘撕脱影响稳定","**手术方式**：切开复位 + 支撑钢板（外侧用锁定钢板，内侧用支撑钢板）+ 植骨（塌陷区）；关节镜辅助复位（部分 Ⅰ/Ⅱ/Ⅲ 型）","**Schatzker Ⅵ 型**：常需双钢板或外固定架临时跨越（Damage Control），待软组织改善后二次手术","**软组织优先原则**：严重肿胀或水疱时延迟手术（7–14 天），以降低伤口并发症","**骨筋膜室综合征**：立即筋膜切开","康复：早期非负重被动活动（防僵硬），8–12 周后逐步负重"],"life":["**严格遵医嘱负重计划**（过早负重致内固定失效与塌陷）","膝关节活动度训练需长期坚持（僵硬是常见并发症）","**创伤性关节炎**可能在数年后出现（关节面不平者风险高），需长期随访","戒烟（影响骨愈合与伤口）","老年患者防跌倒与抗骨质疏松","运动恢复需在肌力与稳定性达标后（通常 6–12 个月）"]},"prog":"无移位骨折保守治疗的功能恢复良好。手术固定后约 70%–85% 获得良好功能，但**创伤性关节炎的发生率可达 20%–40%**（尤其关节面复位不佳或 Ⅴ/Ⅵ 型），多数在 5–10 年内出现。伤口并发症与感染率约 5%–15%（高能量与软组织条件差者更高）。膝关节僵硬常见，需长期康复。","refs":["《外科学》第 9 版（人民卫生出版社）膝关节周围骨折章","1979 Schatzker Classification of Tibial Plateau Fractures (original description)","2020 AO Foundation Tibial Plateau Fracture Management (AO Surgery Reference)","《实用骨科学》第 5 版（胥少汀等）"]},{"id":"or_ankle_fx","name":"踝部骨折","aka":["Ankle Fracture","踝关节骨折","Lauge-Hansen 分型","Danis-Weber 分型"],"rank":4,"basic":{"define":"踝关节周围骨结构（内踝、外踝、后踝）的骨折，常伴韧带损伤与踝穴不稳定。按受伤机制（Lauge-Hansen）与腓骨骨折水平（Danis-Weber）分类，治疗核心是**恢复踝穴的解剖关系与稳定性**。","risk":["扭伤（足部固定而小腿内旋/外旋）——最常见","高处坠落与机动车事故（高能量，多为复杂骨折）","运动损伤（篮球、足球、排球）","骨质疏松（老年人低能量骨折）","既往踝关节不稳"],"epi":"是最常见的下肢骨折之一（年发病率约 1–2/1000）。踝部骨折约占全身骨折的 9%。Danis-Weber B 型最常见。"},"patho":"踝穴由内踝、外踝与胫骨下关节面构成，由下胫腓联合（syndesmosis）与内外侧韧带复合体维持稳定。受伤时足的位置（旋前/旋后）与受力方向（外旋/内收/外展）决定骨折模式（Lauge-Hansen）：旋后-外旋（SER）最常见，依次为旋后-内收（SA）、旋前-外旋（PER）、旋前-外展（PA）。**下胫腓联合的完整性是决定是否需要手术的关键**——其损伤时踝穴增宽，导致踝关节不稳与创伤性关节炎。","dx":{"criteria":["踝部疼痛、肿胀、压痛与畸形，不能负重","**X 线（踝关节正位、侧位与踝穴位/Mortise 位）**：评估内踝、外踝、后踝与踝穴宽度（内踝间隙 >4 mm 或下胫腓重叠 <1 mm 提示不稳）","**Danis-Weber 分型**（按腓骨骨折水平）：A——下胫腓联合以下（稳定）；B——下胫腓联合水平（可稳定或不稳定）；C——下胫腓联合以上（不稳定，伴联合损伤）","**Lauge-Hansen 分型**（按受伤机制）：SER（最常见）、SA、PER、PA","**应力位 X 线或重力应力位**：评估踝穴稳定性（内侧间隙增宽 >4 mm 提示需手术）","**后踝骨折 >25%–30% 关节面**（CT 评估）提示需固定","CT（复杂骨折、术前规划）；MRI（韧带与软骨损伤）","**警惕开放骨折与皮肤条件**（水疱、张力性肿胀影响手术时机）"],"workup":["踝关节正位、侧位与踝穴位（Mortise）X 线","应力位 X 线（评估下胫腓与内侧间隙稳定）","CT（复杂/粉碎骨折、后踝评估、术前规划）","血管神经检查（足背动脉、胫后动脉、腓神经浅支）","评估皮肤条件（水疱、张力、擦伤）与软组织肿胀","老年患者评估骨密度与跌倒风险"],"grading":"**Danis-Weber 分型（A/B/C）** 与 **Lauge-Hansen 分型（SER/SA/PER/PA）** 是主要分类；按稳定性分稳定型（无移位、内侧结构完整）与不稳定型（需手术）；开放骨折用 Gustilo 分型。"},"ddx":[{"name":"股骨干骨折（or_femur_shaft）","point":"疼痛与畸形位于大腿；踝部骨折在踝关节周围。"},{"name":"髌骨骨折（or_patella）","point":"膝前疼痛与不能伸膝；与踝部无关。"},{"name":"胫骨平台骨折（or_tibial_plateau）","point":"膝部轴向暴力后关节面塌陷；踝部骨折在踝关节。"},{"name":"骨盆骨折（or_pelvic_fx）","point":"骨盆区疼痛与休克；与踝部无关。"},{"name":"踝关节扭伤（外侧韧带损伤）","point":"**最需鉴别**：扭伤无骨折线，压痛在外踝前下方（ATFL），应力位无踝穴增宽；但严重扭伤（距腓前韧带完全断裂）也可致不稳，需应力位与 MRI 区分。"},{"name":"跟骨骨折（or_calcaneus）","point":"足跟部肿痛、增宽与 Böhler 角减小；踝部骨折的压痛在踝周。"},{"name":"下胫腓联合损伤（无骨折的 syndesmosis injury，高位踝扭伤）","point":"踝关节上方疼痛（下胫腓处）、挤压试验（squeeze test）阳性，X 线可正常，MRI 见联合韧带撕裂；易漏诊并致慢性不稳。"}],"tx":{"drug":[{"name":"镇痛与消肿","dose":"对乙酰氨基酚 1 g q6h + 布洛芬 400–600 mg q6–8h；抬高患肢、冰敷","note":"肿胀明显时抬高患肢与早期冷敷有助于减轻水肿与疼痛","renal":"NSAIDs 按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；开放骨折按 Gustilo 延长","note":"踝部软组织薄，感染后果严重，需规范预防","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg qd 皮下，术后 12–24 小时开始（视出血风险）","note":"下肢制动与手术为 VTE 危险因素；高危者持续至术后 4 周","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**稳定型（Weber A、无移位、内侧结构完整）**：短腿石膏或助行靴制动 4–6 周，逐步负重","**不稳定型（Weber B/C 伴踝穴增宽、双踝/三踝骨折）**：**切开复位内固定（ORIF）**——外踝钢板 + 内踝螺钉/张力带；下胫腓联合损伤需螺钉或 TightRope 固定","**后踝骨折 >25% 关节面**：需固定以恢复后侧稳定与关节面","**手术时机**：软组织肿胀明显时延迟（7–14 天，待皮纹征出现），避免伤口并发症","**开放骨折**：急诊清创 + 抗生素 + 固定","康复：术后早期非负重活动度训练，6–8 周后逐步负重"],"life":["**遵医嘱负重计划**（过早负重致内固定失效与踝穴增宽）","踝关节活动度与腓骨肌力量训练（防慢性不稳）","抬高患肢、弹力袜（减轻术后肿胀）","**长期随访创伤性关节炎**（关节面不平与联合损伤者风险高，5–10 年内出现）","老年患者防跌倒与抗骨质疏松","运动恢复：通常在 3–6 个月，需踝关节稳定与肌力达标"]},"prog":"稳定型骨折保守治疗的功能恢复优良率 >90%。手术固定后约 80%–85% 获得良好功能，但**创伤性关节炎发生率约 10%–30%**（关节面复位不佳与下胫腓联合损伤者更高）。感染与伤口并发症约 2%–10%（糖尿病与吸烟者更高）。慢性踝关节不稳可致反复扭伤，需康复训练。","refs":["《外科学》第 9 版（人民卫生出版社）踝部骨折章","1950 Lauge-Hansen Classification of Ankle Fractures (original description)","2020 AO Foundation Ankle Fracture Management (AO Surgery Reference)","《实用骨科学》第 5 版（胥少汀等）"]},{"id":"or_calcaneus","name":"跟骨骨折","aka":["Calcaneus Fracture","跟骨骨折","Böhler 角"],"rank":5,"basic":{"define":"跟骨（人体最大的跗骨，承载身体重量传递至地面）的骨折，多为高处坠落时足跟着地所致，约 75% 累及距下关节面（关节内骨折）。常合并脊柱与骨盆损伤，需系统排查。","risk":["**高处坠落足跟着地（典型机制）**","机动车事故（足部挤压）","骨质疏松（老年人低能量）","糖尿病与周围血管病（伤口愈合差）","吸烟（显著增加伤口并发症）"],"epi":"占跗骨骨折的 60%，占全身骨折的 1%–2%。约 10% 为双侧，**约 10%–15% 合并脊柱骨折（胸腰段压缩骨折）**，因此需同时评估脊柱。"},"patho":"轴向暴力通过距骨撞击跟骨，导致跟骨压缩、增宽与高度丢失，距下关节面塌陷（Sanders 分型）。跟骨外形改变导致：① 足弓塌陷与跟腱力臂改变；② 腓骨肌腱撞击（跟骨增宽）；③ 距下关节不平整 → 创伤性关节炎与慢性疼痛。跟骨外侧皮肤薄、血供差，**术后伤口并发症（裂开、感染）发生率高达 10%–25%**，是手术决策的重要制约因素。跟骨为松质骨，骨折后出血可致足底筋膜室压力升高。","dx":{"criteria":["高处坠落或挤压后足跟剧痛、肿胀、增宽与瘀斑（**足底瘀斑——Mondor 征**）","不能负重，跟骨挤压试验（从两侧挤压跟骨）阳性","**X 线（足正位、侧位与轴位/Harris 位）**：侧位见**Böhler 角 <20°（正常 25°–40°）**与 **Gissane 角异常**、跟骨高度丢失；轴位见增宽与内翻","**CT（必需）**：评估关节面受累（Sanders 分型）、骨块位置与手术规划","**必须排查合并损伤**：脊柱（胸腰段 X 线/CT）、骨盆、对侧跟骨、颅底与下肢","**软组织评估**：水疱、张力性肿胀、开放伤口（决定手术时机）","足底筋膜室压力（高度肿胀时）"],"workup":["足正位、侧位与轴位（Harris）X 线","**跟骨 CT（平扫 + 三维重建）**","**全脊柱（尤其胸腰段）X 线或 CT** —— 高处坠落必查","骨盆 X 线（高处坠落）","足底筋膜室压力监测（疑骨筋膜室综合征）","血糖与血管评估（糖尿病与周围血管病影响手术决策）","开放骨折清创与培养"],"grading":"**Sanders 分型**（基于冠状位 CT，按后关节面骨折线数目与位置分 Ⅰ–Ⅳ 型）是手术决策的核心；另有 Essex-Lopresti 分型（舌型/关节塌陷型）。按关节内/外分；按软组织条件（Tscherne）评估手术时机。"},"ddx":[{"name":"踝部骨折（or_ankle_fx）","point":"疼痛与压痛在踝周，X 线见踝部骨折；跟骨骨折的肿胀与增宽在足跟，Böhler 角减小。"},{"name":"股骨干骨折（or_femur_shaft）","point":"大腿疼痛与畸形；与足跟无关。"},{"name":"髌骨骨折（or_patella）","point":"膝前疼痛；与足跟无关。"},{"name":"胫骨平台骨折（or_tibial_plateau）","point":"膝部轴向暴力后关节面塌陷；跟骨骨折为足跟部。"},{"name":"骨盆骨折（or_pelvic_fx）","point":"骨盆区疼痛与休克；高处坠落时两者可并存，需同时评估。"},{"name":"距骨骨折","point":"距骨体/颈骨折，压痛在踝前与距下区，CT 可区分（距骨缺血坏死风险高）。"},{"name":"足底筋膜炎","point":"慢性足跟痛、晨起第一步痛，无外伤史与骨折线，超声/MRI 见筋膜增厚。"},{"name":"跟腱断裂","point":"足跟后方疼痛、Thompson 试验阳性、不能单足提踵，X 线无骨折（可伴跟骨撕脱小骨片）。"}],"tx":{"drug":[{"name":"镇痛与消肿","dose":"对乙酰氨基酚 1 g q6h + 布洛芬 400–600 mg q6–8h；抬高患肢、冰敷","note":"严重肿胀期需抬高患肢与冷敷，避免过早手术","renal":"NSAIDs 按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；开放骨折按 Gustilo 延长","note":"**跟骨骨折伤口并发症率高，抗生素预防与严格无菌操作尤其重要**","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg qd 皮下，入院或术后 12–24 小时开始","note":"下肢制动 + 创伤为 VTE 高危（高处坠落伤更需注意）","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"抗骨质疏松（老年患者）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；必要时双膦酸盐","note":"老年低能量跟骨骨折提示骨质疏松","renal":"唑来膦酸 CrCl <35 禁用","hepatic":"无需调整","interact":"地舒单抗停用需桥接"}],"nonDrug":["**非手术（Sanders Ⅰ 型、无移位、不能耐受手术、软组织条件差）**：短腿石膏或支具非负重 6–8 周，早期活动度训练","**手术指征**：Sanders Ⅱ–Ⅲ 型伴关节面移位、跟骨高度/宽度显著改变、跟骨内翻","**手术时机关键**：**待「皮纹征」出现（通常伤后 7–14 天）**，待肿胀消退后手术可显著降低伤口并发症","**手术方式**：外侧扩大入路切开复位 + 钢板内固定；微创经皮撬拨（部分舌型骨折）；**严重软组织条件差者用外固定架或保守**","**合并脊柱骨折**需同时评估与处理","康复：早期非负重踝与足趾活动，8–12 周后逐步负重"],"life":["**严格戒烟**（吸烟显著增加伤口裂开与感染风险）","抬高患肢、严格遵医嘱负重计划","**长期随访创伤性距下关节炎**（关节内骨折后 5–10 年发生率可达 20%–40%）","穿合适鞋具（足弓支撑）与足踝康复训练","糖尿病与周围血管病者需严格血糖控制与伤口监测","出现足跟持续疼痛与僵硬需评估距下关节融合的可能性"]},"prog":"非手术治疗的功能结果差异较大（约 50%–70% 良好）。手术复位可改善关节面与外形，但**伤口并发症率高达 10%–25%**（吸烟、糖尿病与延迟手术是主要风险因素）。功能障碍（足跟痛、距下关节僵硬、不能长距离行走）常见，约 20%–40% 最终需距下关节融合。整体恢复期长（常需 1–2 年）。","refs":["《外科学》第 9 版（人民卫生出版社）足部骨折章","1993 Sanders Classification of Calcaneal Fractures (original description)","2020 AO Foundation Calcaneus Fracture Management (AO Surgery Reference)","《实用骨科学》第 5 版（胥少汀等）"]},{"id":"or_pelvic_fx","name":"骨盆骨折","aka":["Pelvic Fracture","骨盆环骨折","Tile 分型","血流动力学不稳定骨盆骨折"],"rank":6,"basic":{"define":"骨盆环（骶骨、髂骨、耻骨与坐骨构成的环状结构）的骨折，多由高能量创伤所致。**约 10%–20% 伴血流动力学不稳定**，是创伤早期可预防性死亡的主要原因之一。","risk":["高能量创伤（机动车事故、行人被撞、高处坠落、挤压伤）","老年人低能量跌倒（骨质疏松，多为耻骨支骨折）","合并伤多（颅脑、胸部、腹部、泌尿生殖系）"],"epi":"占全身骨折的 3%–8%，但病死率高达 5%–20%（血流动力学不稳定者可达 30%–50%）。骨盆骨折是创伤后大出血的主要来源（腹膜后间隙可容纳 4–5 L 血液）。"},"patho":"骨盆环由前后两个弓构成：后弓（骶骨 + 骶髂关节 + 髂骨）承担主要负重，前弓（耻骨支 + 耻骨联合）提供稳定。高能量暴力可使环破裂（开书型、侧方压缩型、垂直剪切型），导致：① **腹膜后大出血**（髂血管、骶前静脉丛、骨折端渗血）；② 盆腔脏器损伤（膀胱、尿道、直肠、阴道）；③ 神经损伤（腰骶丛、坐骨神经）。骨盆容积增大（开书型）可显著增加出血量。","dx":{"criteria":["高能量外伤史 + 骨盆区疼痛、压痛、不能负重；**挤压试验与分离试验阳性**","**血流动力学评估优先**：血压、心率、乳酸、对液体复苏的反应（**这是第一位的判断，先于影像分型**）","**X 线（骨盆正位）**：快速筛查；见环断裂、耻骨联合分离（>2.5 cm 提示开书型）、骶髂关节增宽","**CT（平扫 + 三维重建）**：明确骨折形态、骶髂关节与髋臼受累","**FAST 超声**（腹腔积血）与 **骨盆带试验**（用骨盆带临时固定后血压改善提示骨盆源性出血）","**分型**：Tile 分型（A 稳定、B 旋转不稳、C 旋转与垂直均不稳）；AO/OTA 分型；Young-Burgess 分型（LC 侧方压缩、APC 前后压缩、VS 垂直剪切、CM 混合）","**排查合并伤**：膀胱尿道（血尿、尿道口滴血、直肠指检）、直肠（指检血迹）、阴道（女性）、神经（下肢感觉运动）","**危及生命的出血**：血流动力学不稳定且影像见血肿或造影剂外溢"],"workup":["**按 ATLS 流程**：气道、呼吸、循环优先（骨盆骨折的出血可致命）","骨盆正位 X 线（快速）","**FAST 超声（腹腔与心包）**","**骨盆 CT（平扫 + 增强 + 三维）**：血流动力学稳定后","**血管造影（DSA）与栓塞**：血流动力学不稳定且 CT 见造影剂外溢/血肿时（**这是救命的干预**）","血常规、凝血、血型与交叉配血、乳酸、血气","尿常规与尿道造影（疑尿道损伤时，**先造影再插管**）","直肠指检与阴道检查（开放骨折）","神经功能评估（腰骶丛）"],"grading":"**Tile 分型**：A 型（稳定，环完整或仅单处断裂）、B 型（旋转不稳定、垂直稳定）、C 型（旋转与垂直均不稳定）。**Young-Burgess 分型**（LC/APC/VS/CM）与出血风险相关。按血流动力学分：稳定、一过性反应、无反应（持续不稳定）。开放骨盆骨折（经会阴/臀/阴道）为特殊高危类型。"},"ddx":[{"name":"股骨干骨折（or_femur_shaft）","point":"大腿疼痛与畸形，骨盆本身无压痛；高能量伤可同时存在（需同时评估）。"},{"name":"髌骨骨折（or_patella）","point":"膝前疼痛；与骨盆无关。"},{"name":"胫骨平台骨折（or_tibial_plateau）","point":"膝部关节面塌陷；与骨盆无关。"},{"name":"踝部骨折（or_ankle_fx）","point":"踝部疼痛；与骨盆无关。"},{"name":"跟骨骨折（or_calcaneus）","point":"足跟疼痛与增宽；高处坠落时两者常并存，需同时排查。"},{"name":"髋臼骨折","point":"髋关节疼痛与活动受限，CT 见髋臼受累（可伴股骨头中心性脱位）；与骨盆环骨折常合并。"},{"name":"腰椎骨折","point":"腰背疼痛与神经症状；需脊柱影像区分（高能量伤常合并）。"},{"name":"腹膜后血肿（非骨折性）","point":"抗凝治疗、血管病变或医源性所致；无骨盆骨折线，但同样可致失血性休克。"}],"tx":{"drug":[{"name":"液体复苏与大量输血方案（MTP）","dose":"**限制性液体复苏**（目标 SBP 80–90 mmHg 至出血控制）；大量输血按 1:1:1（红细胞:血浆:血小板）比例","note":"**避免过量晶体液**（稀释性凝血病、低体温与酸中毒「致死三联征」）；优先血制品","renal":"无","hepatic":"无","interact":"无"},{"name":"氨甲环酸（抗纤溶）","dose":"1 g 静脉 10 分钟内，随后 1 g 输注 8 小时（伤后 3 小时内给药效果最佳）","note":"创伤出血可降低病死率（CRASH-2）；骨盆骨折出血尤其适用","renal":"CrCl <30 减量","hepatic":"无需调整","interact":"与抗凝药合用需权衡"},{"name":"围术期抗生素预防（开放骨盆骨折）","dose":"头孢唑林 2 g 静脉 + 甲硝唑 500 mg（覆盖厌氧菌，尤其直肠/阴道开放）；按 Gustilo 延长至 48–72 小时","note":"**开放骨盆骨折（经会阴/臀/阴道）感染与死亡风险极高，需尽早广谱抗生素与清创**","renal":"按 CrCl 调整","hepatic":"甲硝唑肝毒性低","interact":"头孢唑林与华法林合用增加出血"},{"name":"低分子肝素（VTE 预防，出血控制后）","dose":"依诺肝素 40 mg qd 皮下，出血稳定后 24–48 小时开始","note":"骨盆骨折是 VTE 极高危（DVT 发生率可达 30%–60%）；**出血未控制时仅用机械预防**","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"镇痛（多模式）","dose":"对乙酰氨基酚 1 g q6h + 阿片类滴定；**避免 NSAIDs（出血风险）**","note":"充分镇痛有助于配合固定与转运；阿片类注意低血压与呼吸抑制","renal":"按 CrCl 调整","hepatic":"限量","interact":"阿片类与镇静药合用增加呼吸抑制"}],"nonDrug":["**首要：骨盆带（pelvic binder）临时固定**（在髂前上棘水平，可缩小骨盆容积、减少出血与稳定骨折）——**这是急救阶段最有效的措施之一**","**血流动力学不稳定**：外固定架（前环）+ 腹膜外填塞（PPP）+ **血管造影栓塞（DSA）**；「Damage Control」策略（先止血稳定，ICU 复苏后再确定性手术）","**稳定型（Tile A）**：卧床或助行器非负重 6–12 周，逐步负重","**不稳定型（Tile B/C）**：外固定架或内固定（前环钢板 + 后环骶髂螺钉）","**开放骨盆骨折**：急诊清创 + 填塞 + 骨盆稳定 + 造口转流（直肠损伤时）","**合并脏器损伤**：膀胱/尿道修复、直肠修复、血管修复（按损伤情况）"],"life":["**长期康复**（骨盆骨折的恢复期长，常需 3–6 个月部分负重）","**VTE 预防**持续至术后 4–6 周（极高危）","神经损伤（腰骶丛）需康复评估与随访","泌尿生殖系并发症（尿道狭窄、性功能障碍）需专科随访","**心理支持**（高能量创伤后的 PTSD 与情绪障碍常见）","老年患者防跌倒与抗骨质疏松治疗"]},"prog":"稳定型骨盆骨折预后良好（多数在 3–6 个月内恢复行走）。**血流动力学不稳定者的病死率 30%–50%**，主要死于大出血与合并伤（颅脑、胸部）。开放骨盆骨折病死率更高（可达 30%–50%）。长期并发症包括慢性疼痛、步态异常、性功能障碍与 VTE。及时的血流动力学控制（骨盆带 + 栓塞/填塞）是改善生存的关键。","refs":["《外科学》第 9 版（人民卫生出版社）骨盆骨折章","2019 WSES Guidelines on Pelvic Trauma (World Journal of Emergency Surgery)","2011 Young-Burgess Classification of Pelvic Ring Disruptions (original description)","2013 CRASH-2 Trial: Tranexamic Acid in Trauma (Lancet)","《中国骨盆骨折诊疗指南》（2021）"]}]},{"id":"ortho_hand_tumor","name":"手外、软组织与骨肿瘤","rank":9,"summary":"手外伤看「分区 + 缺血时间 + 组织组合」；周围神经损伤按 Seddon 分级决定观察还是手术；骨肿瘤的铁律是**先分期、再活检、后切除**，活检通道必须能被后续切除一并带走。","compare":[{"diseaseId":"or_hand_injury","dx":"手部开放性损伤伴肌腱、神经、血管或骨损伤，需按 Zancolli 分区评估；断指需记录冷缺血时间","key":"断指再植的时限与分区决定策略；冷缺血一般不超过 12–24 小时"},{"diseaseId":"or_periph_nerve_inj","dx":"外伤后相应神经支配区的感觉与运动障碍，Tinel 征沿神经走行；按 Seddon 分级（神经失用/轴索断裂/神经断裂）","key":"神经失用多可自行恢复（数周至 3 个月）；神经断裂需手术修复"},{"diseaseId":"or_lumbar_spondylolisthesis","dx":"腰痛伴下肢放射痛，X 线侧位见椎体向前滑移（Meyerding 分度），过伸位可见峡部裂","key":"滑脱程度 + 稳定性 + 神经症状决定保守还是融合"},{"diseaseId":"or_ra_surgery","dx":"类风湿关节炎病程中出现顽固性滑膜炎、关节破坏或畸形（尺偏、纽扣花、天鹅颈），影像见关节间隙消失","key":"滑膜切除在早期、关节置换在晚期；需与药物治疗同步"},{"diseaseId":"or_bone_tb","dx":"低热盗汗 + 局部疼痛与肌萎缩，影像见骨质破坏与椎旁脓肿（脊柱结核 Pott 病），结核菌素/IGRA 阳性","key":"结核性破坏以骨质破坏与冷脓肿为主，无新生骨；化脓性感染有骨膜反应与新生骨"},{"diseaseId":"or_giant_cell_tumor","dx":"20–40 岁、长骨骨端偏心性溶骨性破坏、无硬化边（Campanacci 分级），呈「肥皂泡样」","key":"骨端偏心溶骨 + 无硬化边；刮除 + 骨水泥为经典治疗，复发率约 10%–25%"},{"diseaseId":"or_ewing","dx":"儿童青少年长骨骨干或骨盆疼痛肿胀，X 线见「葱皮样」骨膜反应，活检见小圆蓝细胞、EWSR1 易位","key":"小圆蓝细胞肿瘤 + 葱皮样骨膜反应；需新辅助化疗 + 广泛切除"},{"diseaseId":"or_meniscus","dx":"膝扭伤后关节间隙压痛、McMurray 试验阳性、交锁或打软腿，MRI 见半月板撕裂","key":"桶柄状撕裂与交锁需手术；稳定的小撕裂可保守"},{"diseaseId":"or_rotator_cuff","dx":"肩外展疼痛弧（60°–120°）、夜间痛、Neer 与 Hawkins 试验阳性，MRI 见肩袖撕裂","key":"全层撕裂在年轻活动者需修复；老年退变性撕裂可保守"}],"diseases":[{"id":"or_hand_injury","name":"手外伤与断指再植","aka":["Hand Injury","Finger Replantation","断指再植","手部开放性损伤"],"rank":1,"basic":{"define":"手部各种开放性/闭合性损伤，包括皮肤软组织、肌腱、神经、血管与骨关节损伤。断指再植指将完全或不全离断的手指通过显微外科技术重新接回并恢复血运。","risk":["**工伤（电锯、冲压机、切割机）——最常见**","家庭意外（刀具、玻璃）","交通与运动损伤","爆炸伤与挤压伤（组织挫伤重，再植条件差）","吸烟与糖尿病（影响再植存活）"],"epi":"手外伤占急诊创伤的 10%–20%，是工伤致残的主要原因之一。断指再植的成功率在条件良好的锐性离断中可达 90% 以上，撕脱性与挤压性离断显著降低。"},"patho":"手部结构精细、分区明确（Zancolli 分区：Ⅰ 区——远节指骨至中节指骨中段；Ⅱ 区——中节指骨中段至近节指骨中段（「无人区」，屈肌腱在狭窄鞘内，粘连风险最高）；Ⅲ 区——近节指骨至掌指关节；Ⅳ 区——掌部；Ⅴ 区——腕部）。**缺血耐受性**：肌肉对缺血最敏感（4–6 小时后不可逆），手指以皮肤、骨与肌腱为主，冷缺血（4 ℃）可耐受 12–24 小时。再植的关键是**血管吻合质量**（动脉供血与静脉回流），静脉危象（淤血）比动脉危象更常见且更难处理。","dx":{"criteria":["详细记录：损伤机制（锐性/撕脱/挤压/爆炸）、时间、污染程度、**断指的冷缺血时间与保存方式**","**系统检查（按「骨、关节、肌腱、神经、血管」顺序）**：","血管：指端颜色、温度、毛细血管充盈时间、**Allen 试验**、多普勒探测指动脉","神经：两点辨别觉（正常 <6 mm）、各指感觉与肌力（正中/尺/桡神经）","肌腱：主动屈伸功能（分别评估屈指深/浅肌腱与伸肌腱）","骨与关节：畸形、异常活动、X 线（正侧位，含腕与掌骨）","**再植适应证评估**：锐性离断、缺血时间短（冷缺血 <12–24 小时）、创面相对整齐、患者全身情况允许","**再植禁忌/相对禁忌**：严重挤压或撕脱、多平面离断、严重污染、合并危及生命的损伤、精神疾病、严重血管病变"],"workup":["手部正侧位 X 线（含腕关节、掌骨与指骨）","创面照片记录（便于术前规划）","血管评估（多普勒、必要时血管造影）","神经功能记录（术前基线）","**断指保存**：无菌纱布包裹后放入塑料袋，再置于冰水混合物中（**不可直接接触冰块或浸泡**），标记时间","血常规、凝血、血型与交叉配血、破伤风免疫状态","合并伤评估（多发伤按 ATLS）"],"grading":"按 Zancolli 分区（Ⅰ–Ⅴ 区，Ⅱ 区预后最差）；按离断类型分：**完全离断、不全离断（有软组织相连）、多平面离断**；按损伤性质分：锐性（再植条件好）、挤压性、撕脱性、爆炸性（条件差）；开放骨折按 Gustilo 分型。"},"ddx":[{"name":"周围神经损伤（or_periph_nerve_inj）","point":"与周围神经损伤的鉴别：单纯神经损伤无开放性伤口与血管断裂，手指血运正常；手外伤合并神经损伤需同时修复。"},{"name":"腰椎滑脱（or_lumbar_spondylolisthesis）","point":"与脊柱疾病的鉴别：表现为腰痛与下肢放射痛，无手部损伤。"},{"name":"类风湿关节炎上肢畸形（or_ra_surgery）","point":"RA 的手指畸形为慢性、对称性、无急性创伤史；手外伤为急性损伤。"},{"name":"骨与关节结核（or_bone_tb）","point":"结核为慢性破坏性病变，无急性创伤；两者可通过病史与影像区分。"},{"name":"骨巨细胞瘤（or_giant_cell_tumor）","point":"骨肿瘤为慢性疼痛与肿胀，影像见骨质破坏；无急性伤口与缺血。"},{"name":"单纯屈肌腱或伸肌腱断裂","point":"可无伤口（闭合性断裂，如锤状指），或为小切口伤；需与完全性手外伤区分并单独修复。"},{"name":"手指感染（脓性指头炎、腱鞘炎）","point":"红肿胀痛与发热，无创伤性断裂；腱鞘炎有 Kanavel 四征。"}],"tx":{"drug":[{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 静脉（或头孢呋辛 1.5 g），术前 30–60 分钟；污染重者加氨基糖苷或延长至 48 小时","note":"开放性手外伤感染风险高（尤其挤压与污染伤）；需彻底清创（大量生理盐水冲洗）","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"破伤风预防","dose":"破伤风类毒素 0.5 mL 肌注（未全程接种者）+ 破伤风免疫球蛋白 250 IU（污染重或接种史不明）","note":"所有开放性手外伤均需评估破伤风免疫状态","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"低分子肝素（再植后抗凝，争议）","dose":"依诺肝素 40 mg 皮下 qd 或按方案（部分中心使用）","note":"用于再植后的抗凝（预防吻合口血栓），但证据不一致且增加出血与血肿风险；需按各中心方案","renal":"CrCl <30 减量","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"罂粟碱 / 前列腺素（血管痉挛处理）","dose":"罂粟碱局部外用（30 mg/mL 湿敷血管）；或前列地尔静脉（10 µg qd，部分方案）","note":"用于术中与术后血管痉挛；需同时保温、镇痛与镇静（交感兴奋可致痉挛）","renal":"无需调整","hepatic":"无需调整","interact":"与降压药合用增加低血压"},{"name":"镇痛与镇静","dose":"对乙酰氨基酚 + 阿片类（滴定）；必要时镇静（再植早期）","note":"疼痛与焦虑可致交感兴奋与血管痉挛，术后需充分镇痛","renal":"按 CrCl 调整","hepatic":"限量","interact":"阿片类与镇静药合用增加呼吸抑制"},{"name":"抗生素（术后感染）","dose":"哌拉西林他唑巴坦 4.5 g q6–8h 或按培养调整","note":"再植失败与感染是主要并发症；感染时需及时清创与引流","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与甲氨蝶呤合用增加毒性"}],"nonDrug":["**急救：止血（加压包扎，避免止血带长时间使用）、无菌敷料覆盖、断指正确保存（干燥冷藏）**","**清创（彻底，是再植成功的前提）**：去除无活力组织、彻底冲洗（生理盐水 3–9 L）","**再植手术**：骨固定（克氏针/微型钢板）→ 伸肌腱 → 屈肌腱 → 指动脉（2 条优先）→ 指静脉（2–3 条）→ 指神经 → 皮肤覆盖","**断指再植顺序原则**：先骨后肌腱再血管神经，缩短缺血时间","**术后「三抗」**：抗痉挛（保温、镇痛、罂粟碱）、抗凝（部分中心）、抗感染","**静脉危象**：水蛭疗法（医用水蛭吸血）、拔甲放血、重新吻合；**动脉危象**：解痉、探查重吻合","手部康复：早期保护性活动、渐进性屈伸训练、感觉再教育（神经修复后）"],"life":["**绝对戒烟**（尼古丁致血管痉挛，是再植失败的重要危险因素）","**保温**（术后 1 周保持室温 25–27 ℃，患手局部保温）","避免咖啡因与情绪激动（交感兴奋）","**密切观察指端血运**（每 1–2 小时：颜色、温度、充盈、张力）","康复训练需长期坚持（肌腱粘连与关节僵硬是主要后遗症）","职业康复与功能评定（工伤鉴定）"]},"prog":"锐性离断、冷缺血 <12 小时、单指再植的存活率 >90%；挤压/撕脱性、多指或多平面离断显著降低（60%–80%）。**再植失败多发生在术后 24–72 小时（血管危象）**。功能恢复取决于损伤分区与神经修复：Ⅱ 区屈肌腱粘连常见，感觉恢复需 1–2 年（两点辨别觉）。多数患者恢复基本生活自理，但精细操作与力量可能受限。","refs":["《外科学》第 9 版（人民卫生出版社）手外伤与断指再植章","《实用骨科学》第 5 版（胥少汀等）","2019 IFSSH (International Federation of Societies for Surgery of the Hand) Replantation Guidelines","《断指再植与组织移植中国专家共识》（中华医学会显微外科学分会）"]},{"id":"or_periph_nerve_inj","name":"周围神经损伤","aka":["Peripheral Nerve Injury","Seddon 分级","神经损伤"],"rank":2,"basic":{"define":"四肢周围神经因外伤（切割、牵拉、压迫、缺血）或医源性因素导致的结构与功能损害，表现为相应支配区的感觉、运动与自主神经功能障碍。按 Seddon 分级分为神经失用、轴索断裂与神经断裂。","risk":["**开放性切割伤（玻璃、刀具——神经断裂）**","骨折与关节脱位（肱骨干骨折致桡神经、髋脱位致坐骨神经）","牵拉伤（臂丛牵拉、产伤）","挤压伤与长时间压迫（止血带、石膏、体位）","注射性损伤（臀部注射致坐骨神经）","医源性（手术中误伤）"],"epi":"周围神经损伤占创伤的 2%–3%，上肢多于下肢。桡神经、正中神经、尺神经与腓总神经最常受累。产伤性臂丛损伤发生率约 0.1%–0.4% 活产。"},"patho":"**Seddon 三级**：① **神经失用（neurapraxia）**——髓鞘损伤而轴索完整，传导阻滞，数周至 3 个月自行恢复，无沃勒变性；② **轴索断裂（axonotmesis）**——轴索断裂而神经内膜管完整，远端发生沃勒变性，轴索以 1–3 mm/d 速度再生，多能恢复（时间依距离）；③ **神经断裂（neurotmesis）**——神经完全断裂（含神经外膜），无自发恢复可能，需手术修复。神经再生的速度与距离决定预后：损伤位置越高（如臂丛根性）、距离靶器官越远，恢复越差、越不完全。Sunderland 进一步将轴索断裂细分为 Ⅱ–Ⅳ 度，神经断裂为 Ⅴ 度。","dx":{"criteria":["**感觉障碍**：相应皮节区麻木、痛觉与触觉减退；两点辨别觉（正常 <6 mm）与单丝试验（Semmes-Weinstein）","**运动障碍**：相应肌群的肌力下降（MRC 0–5 级）、肌萎缩（数周后）","**自主神经障碍**：皮肤干燥、脱屑、温度改变与指甲改变","**Tinel 征**：叩击神经走行处诱发放射性麻痛，其位置可反映再生进展","**定位诊断**（关键）：桡神经——垂腕与虎口区感觉减退；正中神经——猿手、拇指对掌不能；尺神经——爪形手、骨间肌萎缩；腓总神经——足下垂；坐骨神经——足下垂 + 小腿外侧感觉障碍","**电生理（肌电图与神经传导，伤后 3–4 周才有意义）**：区分神经失用与轴索/神经断裂，评估再生","**高频超声与 MRI（MR 神经成像）**：评估神经连续性、断端与神经瘤"],"workup":["详细损伤机制与时间、伤口位置与深度","系统感觉（两点辨别、单丝）与运动（MRC 肌力）评估，记录基线","**电生理检查（EMG + NCV，伤后 3–4 周）**","**高频超声（评估神经连续性、断端、瘢痕）**","MRI（臂丛或复杂损伤，MR 神经成像）","X 线（合并骨折与脱位）","定期复查（每 4–8 周）观察 Tinel 征进展与功能恢复"],"grading":"**Seddon 分级**：神经失用（Ⅰ）、轴索断裂（Ⅱ）、神经断裂（Ⅲ）；**Sunderland 分级**（Ⅰ–Ⅴ）；**MRC 肌力分级**（0–5）；按损伤机制分切割、牵拉、压迫、缺血、注射性。"},"ddx":[{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：手外伤有开放性伤口与血管/肌腱断裂，可合并神经损伤；单纯神经损伤无伤口与血管受损。"},{"name":"腰椎滑脱（or_lumbar_spondylolisthesis）","point":"与腰椎滑脱的鉴别：滑脱致腰骶神经根受压，症状在腰与下肢，无上肢或周围神经干的局部体征。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 可致腕管综合征（正中神经压迫）与关节畸形，但为慢性、对称性、有全身表现；周围神经外伤为急性。"},{"name":"颈椎病（神经根型）","point":"神经根性分布、颈部活动诱发、Spurling 试验阳性；周围神经损伤的体征沿神经干分布（如桡神经在肱骨中段）。"},{"name":"吉兰-巴雷综合征（gb）","point":"对称性、上升性弛缓性瘫痪、腱反射消失、脑脊液蛋白-细胞分离；周围神经外伤为局灶性。"},{"name":"糖尿病性周围神经病（ne_dpn）","point":"对称性、远端为主（袜套样）感觉障碍、有长期糖尿病史；外伤性神经损伤为局灶、单侧。"},{"name":"神经卡压综合征（腕管、肘管）","point":"慢性渐进性、夜间麻醒、特定体位诱发；与急性外伤性损伤的病史不同。"}],"tx":{"drug":[{"name":"神经营养药（甲钴胺、维生素 B1/B6）","dose":"甲钴胺 0.5 mg 静脉/肌注 每周 3 次 或口服 0.5 mg tid；维生素 B1 100 mg 肌注 qd","note":"辅助神经营养，证据有限但广泛使用；不可替代手术修复","renal":"无需调整","hepatic":"无需调整","interact":"大剂量维生素 B6 长期使用可致神经病变"},{"name":"镇痛（神经病理性疼痛）","dose":"加巴喷丁 300 mg qn 起始，滴定至 900–3600 mg/d；普瑞巴林 75 mg bid 起始，至 150–300 mg bid；或度洛西汀 30–60 mg qd","note":"用于神经损伤后的神经病理性疼痛；需按肾功能调整（加巴喷丁）","renal":"加巴喷丁与普瑞巴林按 CrCl 减量","hepatic":"度洛西汀肝病者慎用","interact":"与阿片类、苯二氮卓类合用增加呼吸抑制"},{"name":"围术期抗生素预防（开放性损伤）","dose":"头孢唑林 1–2 g 术前 30–60 分钟","note":"开放性神经损伤需清创与抗生素","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"肉毒毒素（部分痉挛）","dose":"按痉挛肌群注射（遵专科方案）","note":"用于神经修复后肌力不平衡所致的痉挛；非常规使用","renal":"无需调整","hepatic":"无需调整","interact":"与氨基糖苷类合用增强神经肌肉阻滞"},{"name":"糖皮质激素（争议，仅急性压迫）","dose":"急性压迫性神经病（如桡神经麻痹早期）可短期使用，剂量遵方案","note":"证据不足；**不推荐常规用于外伤性神经断裂**","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡"}],"nonDrug":["**神经失用与轴索断裂（Ⅱ 度）**：保守治疗——支具保护（防畸形与挛缩）、关节被动活动、定期电生理复查（每 4–8 周），观察 3–6 个月","**神经断裂（Ⅲ 度/Ⅴ 度）或观察无恢复**：**手术修复**——神经外膜或束膜缝合（无张力）、神经移植（自体腓肠神经）、神经导管（短距离缺损）","**手术时机**：切割伤争取一期修复（24–72 小时内，清洁伤口）；牵拉伤与污染伤可延迟（2–4 周，待界限清晰）","**神经移位术**：近端神经不可用时的替代（如臂丛根性撕脱用副神经或肋间神经移位）","功能重建：肌腱移位（神经不可恢复时）、关节融合","**康复**：感觉再教育（触觉定位、两点辨别训练）、肌力训练、支具防止畸形（垂腕用腕手支具，足下垂用踝足支具）"],"life":["**感觉缺失区保护**（防烫伤、割伤与压疮——患者常不自知）","**定期功能评估**（Tinel 征进展、肌力与感觉，每 4–8 周）","避免患肢长时间受压或体位不当（石膏与支具需检查）","**戒烟**（吸烟影响神经再生与微循环）","心理支持（长期功能障碍与疼痛影响情绪与职业）","职业康复：多数周围神经损伤后可恢复部分功能，但严重损伤可能改变职业"]},"prog":"神经失用多在 4–12 周内完全恢复。轴索断裂的恢复取决于再生距离（1–3 mm/d）：腕部损伤（距离短）预后好，臂丛近端损伤预后差。神经断裂经显微修复后约 60%–80% 获得部分功能恢复（感觉优于运动，近端优于远端）。**完全恢复罕见**（尤其高位、长距离、混合神经）。感觉恢复需 1–2 年，运动恢复更慢。","refs":["《外科学》第 9 版（人民卫生出版社）周围神经损伤章","《实用骨科学》第 5 版（胥少汀等）","2003 Seddon and Sunderland Classification of Nerve Injury (historical reference)","2018 American Academy of Orthopaedic Surgeons (AAOS) Appropriate Use Criteria: Management of Peripheral Nerve Injury"]},{"id":"or_lumbar_spondylolisthesis","name":"腰椎滑脱","aka":["Lumbar Spondylolisthesis","腰椎滑脱症","Meyerding 分度"],"rank":3,"basic":{"define":"腰椎椎体相对于下位椎体向前（或向后）滑移，最常见于 L4/5 与 L5/S1。按病因分为峡部裂性（最常见，多见于青少年）、退变性（老年人，多 L4/5）、创伤性、病理性与发育不良性。","risk":["**峡部裂性：青少年运动（体操、举重、投掷、游泳），反复过伸**","退变性：老年人（椎间盘退变与关节突关节炎）","腰椎过度前凸与腹肌薄弱","遗传因素（峡部裂有家族聚集）","创伤与既往腰椎手术"],"epi":"一般人群的腰椎滑脱患病率约 5%–6%（峡部裂性多见于青少年，退变性多见于 50 岁以上）。退变性滑脱在女性中更常见（约 3–9%）。L5 峡部裂是最常见的类型。"},"patho":"**峡部裂性**：椎弓峡部（pars interarticularis）在反复过伸与旋转应力下发生疲劳骨折，若未愈合则峡部裂开，椎体在重力与剪切力下滑移。**退变性**：椎间盘退变致椎间隙变窄与关节突关节不稳，加上黄韧带肥厚，形成滑移与椎管狭窄。滑移导致椎管与神经根管狭窄（尤其 L5 神经根在 L5/S1 水平受压），出现神经源性间歇性跛行与放射痛。滑脱程度（Meyerding 分度）与稳定性决定症状严重度与治疗。","dx":{"criteria":["**症状**：腰痛（久站、后伸加重）、下肢放射痛与麻木（神经根受压）、**神经源性间歇性跛行**（行走后下肢沉重乏力，弯腰或坐下缓解）","**体征**：腰部压痛、腰椎前凸增加（滑脱明显者可见「台阶感」）、直腿抬高试验可阳性、下肢肌力与感觉评估","**X 线（腰椎正侧位 + 双斜位 + 动力位过伸过屈）**：侧位见椎体前移（**Meyerding 分度**：Ⅰ 度 <25%、Ⅱ 度 25%–50%、Ⅲ 度 50%–75%、Ⅳ 度 75%–100%、Ⅴ 度 >100%（脊椎滑脱）；斜位见「苏格兰犬项圈」征（峡部裂）；动力位评估不稳（滑移 >3 mm 或角度变化 >10°）","**MRI（评估椎间盘退变、椎管狭窄与神经根受压）**","CT（明确峡部裂与骨性结构）","**需评估稳定性**（动力位）与神经功能（必要时肌电图）"],"workup":["腰椎正侧位、双斜位与过伸过屈动力位 X 线","**MRI（首选）**：评估椎管狭窄、椎间盘突出与神经根受压","CT（骨性结构与峡部裂的细节）","神经功能评估（肌力、感觉、腱反射）与间歇性跛行评估","电生理（疑神经损害时）","骨质疏松评估（老年退变性滑脱）","WHO 功能评估（ODI 或 JOA 评分）"],"grading":"**Meyerding 分度（Ⅰ–Ⅴ 度）**；按病因分峡部裂性、退变性、创伤性、病理性、发育不良性；按稳定性（动力位滑移）分稳定与不稳；临床按症状分：无症状、单纯腰痛、伴神经根症状、伴椎管狭窄（间歇性跛行）。"},"ddx":[{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：损伤在手部，无腰痛与下肢症状。"},{"name":"周围神经损伤（or_periph_nerve_inj）","point":"与周围神经损伤的鉴别：周围神经为局灶性损伤（沿神经干）；腰椎滑脱的神经症状为神经根性、与体位和行走相关。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 可累及颈椎（寰枢椎半脱位）但主要影响外周关节；与腰椎滑脱的病理机制不同。"},{"name":"腰椎间盘突出症（or_ldh）","point":"椎间盘突出以单侧神经根痛为主，直腿抬高试验强阳性；滑脱伴椎管狭窄以间歇性跛行为主，影像见椎体前移。"},{"name":"腰椎管狭窄症（or_stenosis）","point":"**常与退变性滑脱并存**；单纯狭窄无椎体滑移，而滑脱者需同时处理不稳。"},{"name":"血管性间歇性跛行（下肢 ASO）","point":"行走后小腿肌肉痛、休息即缓解、足背动脉搏动减弱、ABI 降低；神经源性跛行需弯腰或坐下才缓解，且步行距离固定。"},{"name":"骨质疏松性椎体压缩骨折（or_ovcf）","point":"急性腰痛、影像见椎体压缩变形而非滑移；多见于老年骨质疏松者。"}],"tx":{"drug":[{"name":"非甾体抗炎药（急性期）","dose":"塞来昔布 200 mg bid 或布洛芬 400–600 mg q6–8h，短期（2–4 周）","note":"用于腰痛与神经根炎症；长期使用需评估消化道与心血管风险","renal":"eGFR <30 避免","hepatic":"重度肝病禁用","interact":"与抗凝、抗血小板合用增加消化道出血"},{"name":"神经营养与神经病理性疼痛药物","dose":"甲钴胺 0.5 mg tid；加巴喷丁 300 mg qn 滴定至 900–1800 mg/d 或普瑞巴林 75 mg bid","note":"用于神经根性疼痛与麻木；需按肾功能调整","renal":"加巴喷丁/普瑞巴林按 CrCl 减量","hepatic":"无需调整","interact":"与阿片类、镇静药合用增加呼吸抑制"},{"name":"肌肉松弛剂（急性期）","dose":"乙哌立松 50 mg tid 或替扎尼定 2–4 mg qn","note":"短期缓解肌肉痉挛；替扎尼定注意低血压与肝毒性","renal":"替扎尼定肾功能不全减量","hepatic":"替扎尼定肝病者禁用","interact":"替扎尼定与 CYP1A2 抑制剂（氟伏沙明、环丙沙星）合用显著升高浓度"},{"name":"抗骨质疏松（退变性/老年）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；唑来膦酸 5 mg/年或地舒单抗 60 mg/6 月","note":"老年退变性滑脱常伴骨质疏松，需同步治疗","renal":"唑来膦酸 CrCl <35 禁用","hepatic":"无需调整","interact":"地舒单抗停用需桥接"},{"name":"骨形态发生蛋白（融合手术辅助）","dose":"按手术方案植骨（off-label 使用需评估）","note":"用于融合手术提高融合率，尤其翻修病例；需注意异位骨化与炎症反应","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"}],"nonDrug":["**保守治疗（多数患者，尤其 Ⅰ–Ⅱ 度且稳定）**：核心肌群（腹肌与多裂肌）训练、屈曲方向运动（避免过伸）、物理治疗、体重管理","**支具**：短期腰围（急性期），长期使用无证据","**硬膜外激素注射**：短期缓解神经根症状（证据中等）","**手术指征**：保守 3–6 个月无效、进行性神经功能缺损（肌力下降）、严重椎管狭窄（间歇性跛行影响生活）、**不稳（动力位滑移进展）或 Ⅲ 度以上滑脱**","**手术方式**：后路减压 + 椎弓根螺钉内固定 + 椎间融合（PLIF/TLIF）是标准；峡部裂性青少年可考虑峡部修复（Buck 螺钉）或原位融合","**康复**：术后早期下床（支具），核心训练与步态训练"],"life":["**避免腰椎过度后伸与旋转**（尤其峡部裂性青少年，需调整运动项目）","核心肌群训练（腹横肌、多裂肌）需长期坚持","体重管理（减轻腰椎负荷）","**戒烟**（显著降低融合率）","定期复查（保守者每 6–12 个月；术后 3、6、12 个月影像）","术后避免重体力劳动与弯腰搬重物（3–6 个月）"]},"prog":"多数 Ⅰ–Ⅱ 度滑脱经保守治疗症状可控，滑移进展者约 10%–20%（青少年峡部裂性进展风险更高，需定期影像）。手术融合率 >90%（单节段），术后症状改善率约 70%–85%。**融合失败、邻近节段退变与内固定失败**是主要远期问题。退变性滑脱术后需继续抗骨质疏松治疗。","refs":["《外科学》第 9 版（人民卫生出版社）脊柱疾病章","2014 North American Spine Society (NASS) Evidence-Based Clinical Guidelines for Degenerative Lumbar Spondylolisthesis","2016 AOSpine Guidelines on the Management of Lumbar Spondylolisthesis","《中国腰椎滑脱症诊疗指南》（2021）"]},{"id":"or_ra_surgery","name":"类风湿关节炎的外科治疗","aka":["Rheumatoid Arthritis Surgery","RA 外科治疗","滑膜切除术"],"rank":4,"basic":{"define":"针对类风湿关节炎（RA）在药物治疗基础上、出现的顽固性滑膜炎、关节破坏与畸形所施行的手术干预，包括滑膜切除、肌腱修复/重建、关节融合与人工关节置换。外科治疗是药物治疗的补充而非替代。","risk":["**长期未控制的活动性 RA（尤其未用改善病情抗风湿药 DMARDs）**","类风湿因子与抗 CCP 抗体高滴度","吸烟","关节外表现（类风湿结节、血管炎、间质性肺病）","长期糖皮质激素使用（骨质疏松与感染风险）"],"epi":"RA 在我国患病率约 0.3%–0.4%，女性多见（约 3:1）。约 20%–30% 的患者在病程中需接受某种形式的手术（随生物制剂普及，手术率有所下降）。手与腕关节最常受累。"},"patho":"RA 的滑膜炎症（增生性滑膜炎、血管翳形成）侵蚀软骨与软骨下骨，造成关节间隙变窄与骨破坏。在手部：**尺偏畸形**（掌指关节尺偏与半脱位）、**纽扣花畸形**（近指间关节屈曲、远指间关节过伸）、**天鹅颈畸形**（近指间过伸、远指间屈曲）、**腕关节掌侧半脱位与尺骨远端背侧突起**；肌腱受累可致自发性断裂（尤其尺侧腕伸肌腱与拇长伸肌腱）。颈椎可受累（寰枢椎半脱位，麻醉插管时风险高）。","dx":{"criteria":["**已确诊 RA**（2010 ACR/EULAR 分类标准或临床诊断），并有药物治疗（至少一种 DMARDs，通常含甲氨蝶呤）规范治疗 3–6 个月后的持续活动","**手术指征**：① 顽固性滑膜炎（药物与关节腔注射无效）；② 关节破坏与疼痛影响生活（影像见关节间隙消失）；③ 肌腱断裂或即将断裂（需急诊修复）；④ 严重畸形影响功能；⑤ 关节不稳","**影像**：X 线见关节间隙变窄、边缘性侵蚀、畸形；MRI 或超声见滑膜增生与血管翳","**评估颈椎**：RA 病程长或有颈部症状者需颈椎动力位 X 线/MRI（寰枢椎半脱位，全身麻醉前必需）","**功能评分**：HAQ、DASH（上肢）、患者特定功能量表","**评估药物状态**（生物制剂与免疫抑制剂术前需停用时机）"],"workup":["手、腕、膝、髋等受累关节的 X 线（正侧位）","**颈椎动力位 X 线与 MRI（术前必需）**","ESR、CRP（疾病活动度）、RF、抗 CCP","血常规、肝肾功能、凝血（术前）","**感染筛查**（乙肝、结核、HIV）与术前预防","骨密度（长期激素者）","功能评估（HAQ、DASH）与康复计划"],"grading":"按手术类型分：滑膜切除（早期）、肌腱修复/重建、关节融合、人工关节置换（晚期）；按关节破坏程度（Larsen 分级或 Sharp 评分）评估；按功能状态（HAQ）评估。"},"ddx":[{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：手外伤为急性创伤、单侧；RA 畸形为慢性、对称、多关节受累，有自身抗体。"},{"name":"骨与关节结核（or_bone_tb）","point":"结核为单关节破坏（多为脊柱与髋膝），有低热盗汗与结核证据；RA 为对称性多关节、RF/抗 CCP 阳性。"},{"name":"骨巨细胞瘤（or_giant_cell_tumor）","point":"骨肿瘤为局部骨质破坏与肿块，无对称性多关节炎。"},{"name":"骨关节炎（or_knee_oa）","point":"OA 多见于老年、负重关节（膝、髋）、有骨赘与硬化，晨僵 <30 分钟；RA 为对称性小关节、晨僵 >1 小时、侵蚀性破坏。"},{"name":"银屑病关节炎（rh_psa）","point":"有银屑病皮损、远端指间关节受累、附着点炎与「笔帽铅笔」征；RF 多阴性。"},{"name":"痛风性关节炎","point":"急性单关节红肿热痛、血尿酸升高、穿刺见尿酸盐结晶；无对称性畸形。"},{"name":"腕管综合征（继发于 RA）","point":"RA 腕关节滑膜炎可致正中神经压迫；需同时评估 RA 的全身活动与腕关节病变。"}],"tx":{"drug":[{"name":"甲氨蝶呤（围术期管理）","dose":"**通常不停用**（多数证据支持继续使用，不增加感染）；如停药，一般术前 1 周停、术后 1–2 周恢复（遵风湿科意见）","note":"围术期药物管理需风湿科与外科协作；甲氨蝶呤在肾功不全者需减量","renal":"CrCl <30 禁用","hepatic":"肝病与酗酒禁用","interact":"与磺胺类（复方新诺明）合用增加骨髓抑制；与 NSAIDs 合用增加毒性"},{"name":"生物制剂（TNF-α 抑制剂等围术期）","dose":"**术前停用 1 个给药周期**（依药物半衰期：依那西普约 1–2 周、阿达木单抗约 2 周、托珠单抗约 4 周），术后伤口愈合（通常 1–2 周）且无感染后恢复","note":"**生物制剂增加围术期感染风险，需按指南停药**；用药前必须筛查结核与乙肝","renal":"无需调整","hepatic":"重度肝病慎用","interact":"与活疫苗禁用；与其他免疫抑制剂合用增加感染"},{"name":"糖皮质激素（应激剂量）","dose":"长期使用泼尼松 >5 mg/d 者围术期需应激剂量（如氢化可的松 50–100 mg 术中），术后快速减回原剂量","note":"长期激素者存在肾上腺抑制风险，需应激覆盖；同时注意伤口愈合与感染","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟；免疫抑制者按需延长","note":"RA 患者（尤其用生物制剂与激素者）感染风险高，需规范预防","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg 皮下 qd","note":"下肢关节置换与制动为 VTE 高危；RA 患者常伴心血管风险","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"抗骨质疏松（长期激素者）","dose":"钙 500–1000 mg/d + 维生素 D 800–1000 IU/d；双膦酸盐（唑来膦酸 5 mg/年）按骨密度与 FRAX 决定","note":"糖皮质激素性骨质疏松风险高，需评估并治疗","renal":"唑来膦酸 CrCl <35 禁用","hepatic":"无需调整","interact":"地舒单抗停用需桥接"}],"nonDrug":["**滑膜切除术**：早期顽固性滑膜炎（药物无效、关节未破坏），可开放或关节镜，能缓解疼痛并延缓破坏","**肌腱修复与重建**：尺侧腕伸肌腱断裂需重建（伸肌腱转移）；拇长伸肌腱断裂需示指固有伸肌腱转移","**关节融合**：腕关节融合（严重破坏、疼痛、不能置换时）；手指关节融合（稳定但丧失活动）","**人工关节置换**：掌指关节置换（硅胶假体，改善外观与部分功能）、髋/膝关节置换（严重破坏者，效果显著）","**颈椎手术**：寰枢椎不稳（半脱位 >8–9 mm 或有脊髓压迫）需融合固定","康复：术后早期保护性活动、渐进训练；手部功能训练与辅助器具"],"life":["**围术期药物管理须与风湿科共同决定**（不可自行停用或继续生物制剂）","**颈髓风险提示**：RA 患者麻醉插管前必须评估颈椎（寰枢椎半脱位）","术后感染监测（免疫抑制者发热需立即评估）","**持续 DMARDs 治疗**（手术不替代药物，控制疾病活动可减少进一步破坏）","功能康复与辅助器具（写字、进食辅助）","戒烟（RA 疾病活动与术后并发症的危险因素）"]},"prog":"滑膜切除可短期缓解症状，但长期（5–10 年）效果有限（滑膜可再生）。人工关节置换的 10 年假体生存率 >90%（髋膝），患者满意度高。手部小关节置换的长期效果逊于大关节。**疾病活动控制（药物治疗）是决定长期功能的关键**，手术主要解决已发生的结构损害。围术期感染与伤口并发症在免疫抑制患者中风险升高。","refs":["《外科学》第 9 版（人民卫生出版社）关节炎外科治疗章","2017 American College of Rheumatology/American Association of Hip and Knee Surgeons Guideline for Perioperative Management of Antirheumatic Medication","《中国类风湿关节炎诊疗指南（2018）》","2019 EULAR Recommendations for the Management of Rheumatoid Arthritis with Synthetic and Biological DMARDs（围术期部分）"]},{"id":"or_bone_tb","name":"骨与关节结核","aka":["Skeletal Tuberculosis","骨关节结核","脊柱结核","Pott 病"],"rank":5,"basic":{"define":"结核分枝杆菌经血行播散至骨与关节所致的慢性特异性感染，以**脊柱结核（Pott 病，约占 50%）**最常见，其次为髋、膝与骶髂关节。以骨质破坏、冷脓肿与窦道形成为特征，是发展中国家骨关节感染的重要病因。","risk":["**肺结核或其他肺外结核病史/接触史**","结核高流行地区（我国仍为高负担国家）","免疫抑制（HIV、糖尿病、长期激素、生物制剂）","营养不良、酗酒","儿童与青壮年"],"epi":"骨关节结核约占全部结核的 1%–3%，占肺外结核的 10%–15%。我国每年新发骨关节结核数万例，脊柱是最常见部位（50%），其次为髋（15%）与膝（10%）。"},"patho":"结核菌经血行播散至骨与关节的松质骨（椎体、骨骺、滑膜），形成结核性肉芽肿与干酪样坏死。**与化脓性感染的关键差异**：结核以**骨质破坏为主而新生骨少**（「骨型」破坏），进展缓慢，周围骨质疏松明显；冷脓肿（寒性脓肿）无明显红肿热痛，可沿筋膜间隙流注（腰大肌脓肿、咽后脓肿）；晚期可形成窦道与继发感染。脊柱结核累及椎体前部，导致椎体塌陷与**后凸畸形（驼背）**；脓肿与肉芽组织压迫脊髓可致截瘫（Pott 截瘫，约 10%–30%）。","dx":{"criteria":["**慢性起病**：低热、盗汗、乏力、食欲减退、体重下降（结核中毒症状），局部疼痛与肌痉挛","**脊柱结核**：背痛、椎旁肌痉挛（夜间痛）、后凸畸形、**下肢无力或截瘫（Pott 截瘫）**","**髋/膝关节结核**：单关节慢性肿痛、活动受限、肌萎缩；「夜啼」（儿童夜间痛醒）","**影像（关键）**：X 线见**椎体前缘骨质破坏、椎间隙变窄、椎旁软组织肿胀（冷脓肿）**；CT 见骨质破坏与死骨；**MRI 最敏感**（椎体水肿、椎间盘受累、椎旁与硬膜外脓肿、脊髓受压）","**病原学**：穿刺脓液或活检组织抗酸染色、结核培养、**GeneXpert MTB/RIF**、mNGS","**免疫学**：PPD 皮试与 **IGRA（γ 干扰素释放试验）** 辅助（不能单独确诊）","**与化脓性脊柱炎鉴别**：化脓性起病急、高热、骨质破坏进展快且伴明显新生骨与骨膜反应；结核为慢性、破坏为主、冷脓肿"],"workup":["**脊柱/关节 X 线（正侧位）与 MRI（首选影像）**","CT（骨质破坏与死骨细节）","**穿刺活检（影像引导下）**：组织病理（干酪样坏死、肉芽肿）+ 抗酸染色 + 培养 + GeneXpert + mNGS","IGRA 与 PPD","胸部 CT（寻找肺结核，约 1/3–1/2 合并）","ESR、CRP、血常规","HIV 检测（所有结核患者）","肝功能与视色觉（抗结核前基线）","神经功能评估（脊柱结核：肌力、感觉、括约肌功能）"],"grading":"**脊柱结核按部位与范围分**（椎体、椎间盘、附件）；按神经功能分（Frankel 或 ASIA 分级：A 完全性–E 正常）；按脓肿范围（椎旁、腰大肌、硬膜外）与脊柱稳定性（是否需内固定）。关节结核按病程分：单纯滑膜型（早期）、骨型（破坏期）、全关节型（晚期）。"},"ddx":[{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"与 RA 的鉴别：RA 为对称性多关节炎、RF/抗 CCP 阳性、无冷脓肿与结核证据；骨结核多为单关节、有结核中毒症状与病原学证据。"},{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：外伤为急性事件；骨结核为慢性破坏性病程。"},{"name":"周围神经损伤（or_periph_nerve_inj）","point":"与周围神经损伤的鉴别：结核性截瘫源于脊髓压迫（有椎体破坏与脓肿），MRI 可明确；周围神经损伤为神经本身的创伤。"},{"name":"腰椎滑脱（or_lumbar_spondylolisthesis）","point":"与滑脱的鉴别：滑脱为椎体前移与峡部裂，无骨质破坏与冷脓肿；结核见椎体破坏与椎间隙变窄。"},{"name":"化脓性脊柱炎","point":"起病急、高热、白细胞与 CRP 显著升高、骨质破坏进展快且伴新生骨与骨膜反应，血培养或穿刺培养多为金葡菌。"},{"name":"骨巨细胞瘤（or_giant_cell_tumor）","point":"骨巨细胞瘤为骨端偏心溶骨性破坏、无冷脓肿与全身结核症状，活检可鉴别。"},{"name":"骨转移瘤","point":"多见于老年人、有原发肿瘤史，影像见溶骨或成骨性破坏（椎弓根常受累而椎间盘多保留，此为与感染的重要区别）。"},{"name":"布氏杆菌性脊柱炎","point":"有牛羊接触史、波浪热、血清凝集试验阳性；影像与结核相似但少见巨大冷脓肿。"}],"tx":{"drug":[{"name":"异烟肼（INH）","dose":"5 mg/kg/d（成人 300 mg qd）口服，疗程 9–12 个月（骨关节结核通常 12 个月）","note":"核心杀菌药；同用维生素 B6 25–50 mg/d 预防神经毒性","renal":"无需调整（透析后补量）","hepatic":"肝毒性需监测；急性肝炎禁用","interact":"抑制 CYP450（升高苯妥英、华法林浓度）；与利福平合用肝毒性叠加"},{"name":"利福平（RIF）","dose":"10 mg/kg/d（成人 450–600 mg qd）空腹口服，疗程 9–12 个月","note":"不可替代；尿液与泪液呈橙红色（告知患者）","renal":"无需调整","hepatic":"肝毒性显著，需监测","interact":"强 CYP3A4 诱导剂（降低华法林、口服避孕药、他汀、抗真菌药、糖皮质激素浓度）"},{"name":"吡嗪酰胺（PZA）","dose":"25 mg/kg/d（成人 1.5 g qd），强化期 2–3 个月","note":"强化期关键药；不良反应为高尿酸血症与肝毒性","renal":"CrCl <30 减量或延长间隔","hepatic":"肝病者慎用","interact":"升高尿酸（可诱发痛风）"},{"name":"乙胺丁醇（EMB）","dose":"15 mg/kg/d（成人 0.75–1.0 g qd），强化期 2–3 个月（耐药时延长）","note":"预防耐药；剂量相关视神经炎（需基线及每月查视力与色觉）","renal":"CrCl <30 减量并监测视力","hepatic":"无需调整","interact":"与神经毒性药物合用增加周围神经病"},{"name":"左氧氟沙星 / 莫西沙星（耐药或不能耐受）","dose":"左氧氟沙星 750–1000 mg qd；莫西沙星 400 mg qd（耐多药方案）","note":"用于耐多药结核方案；需按药敏与专科方案","renal":"左氧氟沙星按 CrCl 减量","hepatic":"莫西沙星肝毒性需监测","interact":"与 QT 延长药合用增加心律失常"},{"name":"糖皮质激素（争议，仅特定情形）","dose":"**不常规推荐**；仅在结核性脑膜炎或严重脊髓水肿时短期使用","note":"骨关节结核的激素使用证据不足，可能影响愈合；**不推荐常规加用**","renal":"无需调整","hepatic":"监测","interact":"与利福平合用降低激素浓度"}],"nonDrug":["**药物治疗是基础（12 个月规范四联）**，多数患者可单纯药物治疗痊愈","**手术指征**：① 神经功能受损（Pott 截瘫，尤其药物无效或进行性加重）；② 脊柱不稳或严重后凸畸形；③ 大脓肿压迫或需引流；④ 诊断不明需活检；⑤ 药物治疗失败","**手术方式**：病灶清除（前路或后路）+ 植骨融合 + 内固定（后路椎弓根螺钉）","**制动与支具**：脊柱结核早期需卧床或支具保护（防塌陷与畸形加重）","**神经功能监测**：截瘫患者需密切评估肌力与括约肌功能","营养支持（高蛋白、高热量）与休息"],"life":["**全程规律服药（DOT 策略）**，不可中断（防耐药与复发）","每月监测肝功能、视力（乙胺丁醇）与血常规","**接触者筛查**与预防性治疗","康复训练（脊柱结核后需核心肌群训练与姿势管理）","**长期随访（至少 2 年）**：影像（每 3–6 个月）、ESR/CRP 与神经功能","HIV 合并者需同时抗病毒治疗（注意药物相互作用）"]},"prog":"规范抗结核治疗下，骨关节结核的治愈率 >90%。**Pott 截瘫经及时减压，约 70%–80% 可恢复行走能力**（完全性截瘫超过 48–72 小时者恢复率下降）。后凸畸形的进展在儿童期更明显（需长期随访）。复发率约 2%–5%（多见于治疗不规律者）。耐药结核的预后显著变差。","refs":["《外科学》第 9 版（人民卫生出版社）骨与关节结核章","《中国骨与关节结核诊疗指南》（中华医学会结核病学分会，2019）","2016 ATS/CDC/IDSA/ERS Clinical Practice Guidelines: Treatment of Drug-Susceptible Tuberculosis","2019 WHO Guidelines for the Treatment of Drug-Resistant Tuberculosis","《脊柱结核诊断与治疗中国专家共识》（2021）"]},{"id":"or_giant_cell_tumor","name":"骨巨细胞瘤","aka":["Giant Cell Tumor of Bone","GCTB","骨巨细胞瘤","Campanacci 分级"],"rank":6,"basic":{"define":"由单核基质细胞（肿瘤性）与多核巨细胞（反应性）组成的原发性骨肿瘤，具有**局部侵袭性**（可破坏骨皮质与软组织）与**肺转移潜能**（约 2%–3%），WHO 分类为「中间型（局部侵袭性/罕见转移）」。","risk":["**20–40 岁（骨骼成熟后）**","女性略多","长骨骨端（股骨远端、胫骨近端、桡骨远端最常见）","少数与 Paget 病相关（老年）","既往放射治疗史（罕见）"],"epi":"占原发性骨肿瘤的约 5%，占良性骨肿瘤的约 20%。我国发病率略高于西方。发病高峰 20–40 岁（骨龄成熟后），罕见 <15 岁。"},"patho":"肿瘤性单核基质细胞表达 RANKL，招募并激活破骨细胞样多核巨细胞，导致溶骨性破坏。肿瘤生长活跃，可穿透骨皮质形成软组织肿块（Campanacci Ⅲ 级）。**局部复发率较高（刮除术后 10%–25%，取决于手术方式与辅助处理）**；约 2%–3% 发生肺转移（多为良性转移，切除后预后较好）。罕见情况下可发生恶性转化（多为放疗后）。","dx":{"criteria":["**症状**：长骨骨端（股骨远端、胫骨近端、桡骨远端）局部疼痛与肿胀，可有病理性骨折","**X 线（特征性）**：**长骨骨端偏心性、溶骨性、膨胀性破坏**，**无硬化边**、呈「肥皂泡样」；可突破骨皮质形成软组织肿块，无骨膜反应（除骨折）","**MRI**：评估软组织侵犯范围与关节受累（术前必需）","**CT**：评估骨皮质完整性与骨破坏细节","**活检（必需，术前）**：组织学见单核基质细胞 + 多核巨细胞；需排除其他含巨细胞的病变（甲状旁腺功能亢进性棕色瘤、动脉瘤样骨囊肿、软骨母细胞瘤）","**需排除棕色瘤**：查血钙、磷、PTH（甲旁亢所致者治疗原发病）","**Campanacci 分级**（影像）：Ⅰ 级——潜伏（边界清楚、骨皮质完整）；Ⅱ 级——活动（边界较清、骨皮质变薄）；Ⅲ 级——侵袭（边界不清、骨皮质突破、软组织肿块）"],"workup":["受累部位 X 线（正侧位）","**MRI（软组织与关节受累评估，必需）**","CT（骨皮质与骨破坏细节）","**穿刺或切开活检（术前必需）**","**血钙、磷、PTH（排除甲状旁腺功能亢进的棕色瘤）**","胸部 CT（转移筛查，初诊与随访）","全身骨扫描或 PET-CT（多发或转移评估）","碱性磷酸酶（骨破坏活跃时升高）"],"grading":"**Campanacci 分级（Ⅰ–Ⅲ 级）** 决定手术方式；按 Enneking 外科分期（多数为良性或侵袭性良性，少数为恶性）；按是否转移（肺转移 2%–3%）。"},"ddx":[{"name":"骨与关节结核（or_bone_tb）","point":"与骨结核的鉴别：结核有结核中毒症状、冷脓肿、骨质破坏伴骨质疏松，影像无「肥皂泡样」膨胀；GCT 为纯溶骨膨胀性病变、无脓肿。"},{"name":"尤文肉瘤（or_ewing）","point":"尤文肉瘤多见于儿童青少年、长骨**骨干**、有「葱皮样」骨膜反应与小圆蓝细胞；GCT 在骨端、无骨膜反应、含多核巨细胞。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 为对称性多关节炎与侵蚀性破坏，无「肥皂泡样」孤立病灶与巨细胞肿瘤。"},{"name":"甲状旁腺功能亢进性棕色瘤","point":"**最需鉴别**：血钙高、PTH 高、多发病灶，切除甲状旁腺后骨病变消退；单纯 GCT 的血钙与 PTH 正常。"},{"name":"动脉瘤样骨囊肿","point":"多见于 20 岁以下、影像见液-液平面（MRI），组织学见囊性血腔；与 GCT 可并存（继发性 ABC）。"},{"name":"骨肉瘤","point":"骨肉瘤多见于青少年长骨干骺端，有肿瘤骨与日光放射样骨膜反应、碱性磷酸酶显著升高；GCT 为溶骨性无成骨。"},{"name":"软骨母细胞瘤","point":"多见于青少年骨骺、有小钙化点，组织学见软骨母细胞与「鸡笼样」钙化。"}],"tx":{"drug":[{"name":"地舒单抗（RANKL 抑制剂，不可手术或需降期时）","dose":"120 mg 皮下 每 4 周 1 次（首月第 8、15 天各加 1 次负荷剂量）；疗程按方案（通常 6–12 个月）","note":"**用于骶骨、脊柱等难以完整切除的 GCT，或术前降期（减少出血与软组织侵犯）**；可致低钙血症（需补钙与维生素 D）与颌骨坏死（用药前口腔评估）","renal":"肾功能不全者低钙风险增加（需监测）","hepatic":"无需调整","interact":"与双膦酸盐不宜联用；与免疫抑制剂合用增加感染风险"},{"name":"双膦酸盐（辅助，证据有限）","dose":"唑来膦酸 4 mg 静脉每 4 周（部分方案）","note":"抑制破骨细胞活性，可作为辅助（尤其不可手术者）；注意肾毒性与颌骨坏死","renal":"CrCl <35 禁用","hepatic":"无需调整","interact":"与 NSAIDs 合用增加肾毒性"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟","note":"骨肿瘤手术（尤其重建）感染后果严重，需规范预防","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用增加出血"},{"name":"低分子肝素（VTE 预防）","dose":"依诺肝素 40 mg 皮下 qd（术后 12–24 小时开始）","note":"下肢肿瘤手术与制动为 VTE 危险因素","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"},{"name":"镇痛（多模式）","dose":"对乙酰氨基酚 + 弱阿片类；术后按需强阿片类","note":"骨肿瘤疼痛常较重，需充分镇痛","renal":"按 CrCl 调整","hepatic":"限量","interact":"阿片类与镇静药合用增加呼吸抑制"}],"nonDrug":["**手术是首选治疗**：","**Campanacci Ⅰ/Ⅱ 级**：**病灶刮除 + 高速磨钻 + 化学/热辅助（苯酚、液氮或骨水泥）+ 植骨/骨水泥填充**；复发率约 10%–25%","**Campanacci Ⅲ 级或复发**：扩大刮除或**整块切除 + 重建（肿瘤假体、大段异体骨、腓骨移植）**","**不可切除部位（骶骨、脊柱）**：地舒单抗降期后手术，或放疗（GCT 对放疗中等敏感，但放疗后有恶性转化风险）","**肺转移**：手术切除（转移灶切除后 5 年生存率 >90%，多为良性转移）","**功能重建与康复**：关节保留或假体重建，术后长期功能训练"],"life":["**长期随访（至少 5 年，最好 10 年）**：局部复发多在 2–3 年内，需定期影像（每 3–6 个月）","**胸部 CT 随访**（肺转移筛查，尤其 Ⅲ 级与复发者）","地舒单抗使用者：**补钙与维生素 D、监测血钙、口腔卫生（防颌骨坏死）、不可骤停**（停药后骨破坏反跳，需桥接）","**关节功能保护**（避免高冲击运动，术后按医嘱负重）","心理支持（骨肿瘤患者对复发与截肢的焦虑）","戒烟（影响骨愈合与总体预后）"]},"prog":"刮除 + 辅助处理后 5 年局部控制率约 75%–90%（Campanacci Ⅲ 级与骶骨病变复发率更高）。**肺转移率 2%–3%**，转移灶切除后预后良好（5 年生存 >90%）。恶性转化罕见（多与放疗相关）。地舒单抗显著改变了不可手术病例的预后，但需注意停药反跳与长期用药的不良反应。","refs":["《外科学》第 9 版（人民卫生出版社）骨肿瘤章","2013 Campanacci Classification of Giant Cell Tumor of Bone（原始分类回顾）","2015 Giant Cell Tumor of Bone: ESMO–EURACAN Clinical Practice Guidelines","2021 Denosumab for Giant Cell Tumor of Bone: Systematic Review (J Bone Oncol)","《中国骨巨细胞瘤诊疗指南》（2020）"]},{"id":"or_ewing","name":"尤文肉瘤","aka":["Ewing Sarcoma","ES","尤文氏肉瘤","小圆蓝细胞肿瘤"],"rank":7,"basic":{"define":"由小圆蓝细胞组成的高度恶性原发性骨与软组织肿瘤，特征性分子改变为 **EWSR1 基因与 ETS 家族转录因子（最常见 FLI1）的易位 t(11;22)**，多见于儿童与青少年。","risk":["**儿童与青少年（高峰 10–20 岁）**","男性略多（约 1.5:1）","白种人发病率高于亚洲人与非洲裔","长骨骨干与骨盆、肋骨","少数有家族性（伴 TP53 或 Retinoblastoma 突变者风险升高）"],"epi":"年发病率约 1–3/100 万（儿童青少年中为第二常见的原发性恶性骨肿瘤，仅次于骨肉瘤）。我国 5–20 岁高发。约 20%–25% 就诊时已有转移（肺、骨、骨髓）。"},"patho":"EWSR1-FLI1 融合蛋白作为异常转录因子，重编程基因表达，阻断间充质干细胞分化并促进增殖。肿瘤生长迅速，穿透骨皮质形成大的软组织肿块，伴明显骨膜反应（「葱皮样」或「日光放射样」）。尤文肉瘤对**化疗与放疗均敏感**，这是其与骨肉瘤的重要区别，也是治疗策略（新辅助化疗 + 局部控制）的基础。","dx":{"criteria":["**症状**：局部疼痛（常为间歇性、夜间加重）、肿胀、可触及肿块；可有发热、体重下降等全身症状（易误诊为骨髓炎）","**X 线**：长骨**骨干或干骺端**的渗透性溶骨性破坏，边界不清；**「葱皮样」骨膜反应**（多层反应性新骨）；可见软组织肿块与 Codman 三角","**MRI（必需）**：评估骨内范围、软组织肿块与神经血管关系","**活检（必需，术前）**：组织学见小圆蓝细胞；**分子检测（EWSR1 易位，FISH 或 RT-PCR）是确诊关键**","**分期检查**：胸部 CT（肺转移）、全身骨扫描或 PET-CT、骨髓穿刺（转移评估）","**需与骨髓炎、骨肉瘤、淋巴瘤、神经母细胞瘤骨转移鉴别**"],"workup":["受累部位 X 线（正侧位）","**MRI（局部范围与软组织肿块）**","**CT（骨皮质破坏与肺转移筛查）**","**活检（切开或粗针穿刺，需有经验的骨肿瘤中心）** + 分子检测（EWSR1）","**全身分期：PET-CT 或骨扫描 + 胸部 CT + 骨髓穿刺**","血常规、LDH（预后相关）、碱性磷酸酶、ESR/CRP","心脏超声（蒽环类前基线）与肾功能（化疗前）","听力检查（铂类与异环磷酰胺前）"],"grading":"按部位分：长骨（股骨、胫骨）、骨盆、肋骨、软组织（骨外尤文肉瘤）；按分期分：局限性与转移性（肺/骨/骨髓）；按 Enneking 外科分期（ⅡB 为最常见）；风险分层（转移、肿瘤体积 >200 mL、LDH 升高、骨盆部位为不良预后）。"},"ddx":[{"name":"骨巨细胞瘤（or_giant_cell_tumor）","point":"GCT 发生于骨端（骨骼成熟后 20–40 岁）、纯溶骨膨胀性、无骨膜反应、含多核巨细胞；尤文肉瘤在骨干、有葱皮样骨膜反应、小圆蓝细胞。"},{"name":"骨与关节结核（or_bone_tb）","point":"结核为慢性破坏伴冷脓肿、有结核证据；尤文肉瘤进展快、有巨大软组织肿块与葱皮样骨膜反应。"},{"name":"骨肉瘤","point":"骨肉瘤在干骺端、有肿瘤骨与日光放射样骨膜反应、碱性磷酸酶显著升高；尤文肉瘤在骨干、以溶骨为主、对放疗敏感。"},{"name":"急性骨髓炎（or_osteomyelitis）","point":"**最易误诊**：高热、局部红肿热痛、血培养阳性；影像早期见软组织肿胀，后期骨破坏与骨膜反应。**活检与分子检测是鉴别关键**（小圆蓝细胞 + EWSR1 易位为尤文肉瘤）。"},{"name":"淋巴瘤骨受累","point":"多见于成人、影像见渗透性破坏但骨皮质相对保留，活检见大淋巴细胞（非小圆蓝）、无 EWSR1 易位。"},{"name":"神经母细胞瘤骨转移","point":"多见于幼儿、有原发灶（肾上腺）、尿儿茶酚胺代谢物升高；活检与分子检测可鉴别。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 为多关节对称性炎症，无孤立性破坏性肿块。"}],"tx":{"drug":[{"name":"VDC/IE 方案（新辅助化疗，标准）","dose":"**VDC**：长春新碱 1.5 mg/m² + 多柔比星 75 mg/m² + 环磷酰胺 1200 mg/m²；**IE**：异环磷酰胺 1800 mg/m²/d×5 + 依托泊苷 100 mg/m²/d×5；两方案交替（每 2–3 周一周期，共 14–17 周期，按方案）","note":"**尤文肉瘤必须行新辅助化疗（术前缩小肿瘤、消灭微转移）**；剂量按体表面积计算（此处仅为方案框架，具体按 CSCO/NCCN 与体表面积调整）；需 G-CSF 支持；**心脏毒性（多柔比星累积剂量限制）与肾毒性（异环磷酰胺，需美司钠）**","renal":"异环磷酰胺在肾功能不全时减量；顺铂与异环磷酰胺需充分水化","hepatic":"长春新碱肝病者减量；多柔比星胆红素升高时减量","interact":"异环磷酰胺需联用美司钠（预防出血性膀胱炎）；与活疫苗禁用"},{"name":"美司钠（ uroprotection ）","dose":"按异环磷酰胺剂量的 60%–100% 分次静脉给药（0、4、8 小时）","note":"预防异环磷酰胺所致的出血性膀胱炎","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"G-CSF（非格司亭/培非格司亭）","dose":"非格司亭 5 µg/kg 皮下 qd（化疗后 24–48 小时开始）或培非格司亭 6 mg 每周期 1 次","note":"VDC/IE 方案骨髓抑制重，需常规预防性 G-CSF","renal":"无需调整","hepatic":"无需调整","interact":"与化疗同时使用不推荐"},{"name":"止吐方案（高致吐化疗）","dose":"5-HT3 拮抗剂（帕洛诺司琼 0.25 mg 静脉）+ 地塞米松 10 mg + NK1 拮抗剂（阿瑞匹坦 125 mg）","note":"VDC/IE 为高致吐方案，需三联止吐预防","renal":"按 CrCl 调整","hepatic":"阿瑞匹坦肝病者慎用","interact":"阿瑞匹坦为 CYP3A4 中度抑制剂（影响多种药物）"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟","note":"广泛切除与重建后感染风险高","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"双膦酸盐（骨转移/骨保护，辅助）","dose":"唑来膦酸 4 mg 静脉每 4 周","note":"用于骨转移或多发骨病变者的骨相关事件预防；注意肾毒性与颌骨坏死","renal":"CrCl <35 禁用","hepatic":"无需调整","interact":"与 NSAIDs 合用增加肾毒性"}],"nonDrug":["**新辅助化疗（约 3–5 个月）→ 局部控制 → 辅助化疗（总疗程约 6–12 个月）**","**局部控制**：广泛切除 + 重建（可保留肢体者）；**对化疗反应好者也可选择根治性放疗**（尤文肉瘤对放疗敏感，可用于难以切除的部位如骨盆、脊柱）","**截肢**：肿瘤巨大、广泛侵犯神经血管或保肢不可行时","**肺转移**：手术切除转移灶（可提高生存）；全肺放疗（部分方案）","**复发/难治**：二线化疗（拓扑替康 + 环磷酰胺、伊立替康 + 替莫唑胺）、靶向（IGF-1R 抗体）、免疫治疗（研究性）","**康复与假体功能训练**（保肢术后）"],"life":["**长期随访**：局部复发与转移（肺、骨、骨髓）多见于治疗后 2–5 年；每 3 个月影像（前 2 年）、之后每 6 个月","**心脏功能监测**（蒽环类累积剂量，每年心超）","**肾功能与听力监测**（铂类与异环磷酰胺）","**生育力保护**（化疗前讨论精子/卵子冻存）","继发肿瘤风险（放疗与烷化剂，长期随访）","心理社会支持与学业/职业康复（患者多为青少年）"]},"prog":"**局限性尤文肉瘤的 5 年生存率约 65%–75%**（规范多学科治疗下）；转移性者约 20%–30%。不良预后因素：转移（肺/骨/骨髓）、肿瘤体积大（>200 mL）、骨盆部位、LDH 升高、化疗反应差（坏死 <90%）。复发后预后差（5 年生存 <20%）。","refs":["《外科学》第 9 版（人民卫生出版社）骨肿瘤章","2021 ESMO–EURACAN–GENTURIS Clinical Practice Guidelines for Bone Sarcomas","2018 Ewing Sarcoma: Current Management and Future Directions (Nature Reviews Clinical Oncology)","2023 NCCN Guidelines for Bone Cancer","《中国骨与软组织肉瘤诊疗指南（2022）》"]},{"id":"or_meniscus","name":"半月板损伤","aka":["Meniscus Tear","Meniscal Injury","半月板撕裂"],"rank":8,"basic":{"define":"膝关节内、外侧半月板的撕裂性损伤，多由旋转暴力（屈膝位旋转）引起，也可为退变性磨损所致。半月板承担膝关节载荷传递与稳定功能，损伤后可致疼痛、交锁与关节退变。","risk":["**运动损伤（足球、篮球、摔跤——屈膝旋转）**","**中老年退变性撕裂（常无明确外伤）**","膝关节不稳（ACL 损伤）","体重与职业负荷","既往膝关节手术"],"epi":"半月板撕裂是最常见的膝关节损伤之一，男性多于女性。急性撕裂多见于 20–40 岁运动人群；退变性撕裂多见于 50 岁以上（常伴骨关节炎）。内侧半月板损伤约为外侧的 2–3 倍。"},"patho":"半月板由纤维软骨构成，仅外周 10%–30%（红区）有血供，中央（白区）无血供。**红区撕裂**有愈合潜能（可缝合），**白区撕裂**几乎不能愈合（需部分切除）。半月板承担膝关节 50%–70% 的载荷并参与稳定；切除后接触应力显著增加，长期可致骨关节炎。按形态分：纵形撕裂（含**桶柄状撕裂**——可移位至髁间窝致交锁）、水平撕裂、放射状撕裂、瓣状撕裂与复杂撕裂。","dx":{"criteria":["**症状**：膝关节间隙疼痛（内侧或外侧）、肿胀、打软腿、**交锁（突然不能伸膝）**、蹲起与旋转时加重","**体征**：关节间隙压痛、**McMurray 试验阳性**（屈膝旋转时出现弹响伴疼痛）、Apley 研磨试验、关节积液（浮髌试验）","**X 线**：排除骨折与骨关节炎（关节间隙变窄、骨赘）；**X 线不能显示半月板**","**MRI（首选影像）**：敏感度与特异度均 >90%；按信号分级（Ⅰ 级为退变、Ⅱ 级为线性信号未达关节面、**Ⅲ 级为达关节面——撕裂**）；评估撕裂形态（桶柄状、纵形、放射状）与稳定性","**需评估合并损伤**：ACL/MCL 断裂、软骨损伤","**桶柄状撕裂**的 MRI 征象：髁间窝内「双 PCL 征」、半月板「领结」缺失"],"workup":["膝关节正侧位 X 线（排除骨折与骨关节炎）","**膝关节 MRI（必需）**：撕裂形态、稳定性与合并损伤","关节积液穿刺（急性期减压，可送检）","韧带稳定性评估（Lachman 试验、内翻/外翻应力试验）","功能评分（Lysholm、IKDC）","评估骨关节炎（OARSI 或 Kellgren-Lawrence 分级，决定治疗策略）"],"grading":"按部位分：内侧/外侧；按血供分：红-红区（外周 3 mm）、红-白区、白-白区；按形态分：纵形、桶柄状、水平、放射状、瓣状、复杂；按病因分：急性外伤性、退变性；按稳定性分：稳定（<5 mm 移位）与不稳定。"},"ddx":[{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：损伤在手部；无膝部症状。"},{"name":"周围神经损伤（or_periph_nerve_inj）","point":"与周围神经损伤的鉴别：表现为神经支配区的感觉运动障碍；半月板损伤为膝关节机械症状。"},{"name":"腰椎滑脱（or_lumbar_spondylolisthesis）","point":"滑脱致下肢放射痛，坐骨神经分布，与膝部旋转动作无关；半月板损伤为关节间隙压痛与 McMurray 阳性。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 可累及膝关节（滑膜炎与破坏）但为对称性多关节、有全身表现；半月板损伤为单膝机械症状。"},{"name":"骨关节炎（or_knee_oa）","point":"**常与退变性半月板撕裂并存**；OA 以负重痛、关节间隙变窄与骨赘为主，撕裂可为继发改变。治疗重点不同（OA 以保守为主）。"},{"name":"前交叉韧带（ACL）损伤（or_acl）","point":"急性肿胀（24 小时内大量积血）、Lachman 试验阳性、不稳定感；可与半月板撕裂合并（约 50%）。"},{"name":"髌股关节疼痛综合征","point":"膝前痛（上下楼梯与久坐加重）、髌骨研磨试验阳性，关节间隙无压痛。"},{"name":"膝关节游离体","point":"可致交锁，X 线与 CT 见游离骨块；半月板撕裂在 MRI 上可辨。"}],"tx":{"drug":[{"name":"非甾体抗炎药（急性期）","dose":"布洛芬 400–600 mg q6–8h 或塞来昔布 200 mg bid，短期（1–2 周）","note":"缓解疼痛与炎症；长期使用需评估消化道与心血管风险","renal":"eGFR <30 避免","hepatic":"重度肝病禁用","interact":"与抗凝、抗血小板合用增加消化道出血"},{"name":"关节腔注射（糖皮质激素，短期）","dose":"复方倍他米松 1 mL 或曲安奈德 40 mg 关节腔注射（单次，必要时 3 个月后重复）","note":"短期缓解疼痛与炎症；**频繁注射（每年 >3–4 次）可加速软骨损伤**","renal":"无需调整","hepatic":"监测","interact":"与抗凝合用增加出血风险（注射部位）"},{"name":"关节腔注射（玻璃酸钠）","dose":"2 mL 关节腔注射，每周 1 次 ×5 次或单次高分子量制剂","note":"用于骨关节炎相关的疼痛（证据中等，个体差异大）；半月板急性撕裂非主要适应证","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"镇痛（术后）","dose":"对乙酰氨基酚 + 弱阿片类；必要时神经阻滞（收肌管阻滞）","note":"关节镜术后多模式镇痛可减少阿片类用量","renal":"按 CrCl 调整","hepatic":"限量","interact":"阿片类与镇静药合用增加呼吸抑制"},{"name":"低分子肝素（VTE 预防，高危者）","dose":"依诺肝素 40 mg 皮下 qd","note":"关节镜手术的 VTE 风险较低，仅高危者（既往 VTE、肿瘤、制动）使用","renal":"CrCl <30 减为 30 mg","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**保守治疗（稳定撕裂、退变性撕裂）**：休息、冰敷、股四头肌与腘绳肌强化、本体感觉训练；多数退变性撕裂经 6–12 周康复可改善","**手术指征**：交锁（桶柄状撕裂）、急性大撕裂（尤其红区）、保守治疗失败的机械症状","**手术方式**：**关节镜下缝合（红区、年轻患者优先，保留半月板）**；**部分半月板切除**（白区不可缝合、退变性撕裂）；**极少全切除**（仅严重碎裂无法保留时）","**桶柄状撕裂**需尽早手术（移位块可致软骨损伤）","**康复**：术后早期关节活动度训练，4–6 周渐进负重，强化训练 3–6 个月","**体重管理**（减轻膝关节负荷，尤其退变性撕裂）"],"life":["**股四头肌强化训练是长期核心**（保护膝关节、减少复发）","避免深蹲、跪姿与旋转性运动（恢复期内）","运动恢复需循序渐进（缝合术后 4–6 个月才能恢复对抗性运动）","**退变性撕裂者需了解**：半月板切除不能治愈骨关节炎，减重与肌力训练更重要","出现交锁、无法伸膝需立即就诊","职业与运动指导（避免重复性屈膝旋转）"]},"prog":"保守治疗的稳定撕裂约 70%–80% 症状改善。缝合术后愈合率约 70%–90%（取决于血供区、年龄与撕裂形态）。**部分切除术后短期效果好（>85% 满意），但长期（10–20 年）骨关节炎发生率增加（约 2–3 倍的相对风险）**。因此现代理念强调「能缝不切、能少切不多切」。退变性撕裂合并 OA 者，手术获益有限（随机研究显示与保守治疗相近）。","refs":["《外科学》第 9 版（人民卫生出版社）膝关节损伤章","2019 ESSKA Meniscus Consensus Project: Save the Meniscus","2016 AAOS Clinical Practice Guideline: Management of Osteoarthritis of the Knee（非手术治疗）","《中国膝关节半月板损伤诊疗专家共识》（2021）"]},{"id":"or_rotator_cuff","name":"肩袖损伤","aka":["Rotator Cuff Tear","肩袖撕裂","肩袖损伤"],"rank":9,"basic":{"define":"肩袖（冈上肌、冈下肌、小圆肌、肩胛下肌）肌腱的撕裂性损伤，最常见于冈上肌腱。按病因分急性外伤性（年轻人，常伴肩关节脱位）与退变性（中老年，慢性磨损）。","risk":["**年龄（50 岁以上退变性撕裂显著增加，60 岁以上约 25%–30% 有撕裂）**","**肩峰下撞击与肩峰形态（钩状肩峰）**","重复过顶运动（游泳、投掷、羽毛球）","肩关节脱位（尤其 >40 岁者合并肩袖撕裂约 30%–40%）","吸烟、糖尿病（影响肌腱愈合）","肩胛骨运动异常与姿势不良"],"epi":"肩袖撕裂是最常见的肩部疾病之一，患病率随年龄增加（50 岁约 13%、60 岁约 20%、70 岁约 30%、80 岁约 50%，含无症状撕裂）。"},"patho":"肩袖肌腱在肩峰下间隙反复撞击与磨损，导致肌腱退变（黏液样变性、钙化）与撕裂。**退变性撕裂常从关节侧或滑囊侧开始，逐渐进展为全层撕裂**。撕裂后肩袖的力偶失衡（尤其冈上肌功能丧失），导致肱骨头上移与疼痛弧。巨大撕裂（>5 cm 或累及 ≥2 条肌腱）可致**肩袖关节病（cuff tear arthropathy）**——肱骨头上移、肩峰下间隙变窄与关节破坏。肌腱止点的血供（「危险区」）与吸烟、糖尿病影响愈合。","dx":{"criteria":["**症状**：肩外展与上举疼痛（**疼痛弧 60°–120°**）、夜间痛（患侧卧位加重）、**无力（不能主动上举或外展）**、梳头/穿衣困难","**体征**：**Neer 撞击试验**（前屈内旋诱发疼痛）、**Hawkins-Kennedy 试验**（屈肘 90° 内旋诱发疼痛）、**Jobe 试验（空罐试验，冈上肌）**、**落臂试验（重度撕裂）**、外旋抗阻（冈下肌）、内旋抗阻（肩胛下肌）、**肩峰下压痛**","**X 线**：评估肩峰形态（钩状）、肱骨头位置（上移提示巨大撕裂）、关节间隙（cuff tear arthropathy）与钙化","**MRI（首选影像）**：评估撕裂部位、大小、回缩程度、脂肪浸润（Goutallier 分级）与肌腱质量；**超声（动态评估，成本低，依赖操作者）**","**撕裂程度**：全层 vs 部分（关节侧/滑囊侧，>50% 厚度常需手术）；**撕裂大小**（小 <1 cm、中 1–3 cm、大 3–5 cm、巨大 >5 cm）","需评估**肩关节僵硬（冻结肩）与颈椎病（颈源性肩痛）**"],"workup":["肩关节正位、冈上肌出口位（Y 位）与腋位 X 线","**MRI（首选，评估撕裂与脂肪浸润）或高频超声**","体格检查（撞击试验、肌力与活动度记录）","颈椎评估（颈源性肩痛，Spurling 试验）","功能评分（Constant-Murley、ASES、UCLA）","糖尿病与吸烟状态（影响治疗决策与愈合）"],"grading":"按撕裂深度分：部分撕裂（关节侧/滑囊侧/腱内）与全层撕裂；按大小分：小（<1 cm）、中（1–3 cm）、大（3–5 cm）、巨大（>5 cm 或 ≥2 条肌腱）；**Goutallier 脂肪浸润分级（0–4）** 是修复预后的重要指标；按病因分急性外伤、退变性、慢性进展。"},"ddx":[{"name":"手外伤与断指再植（or_hand_injury）","point":"与手外伤的鉴别：手部急性损伤，与肩部无关。"},{"name":"周围神经损伤（or_periph_nerve_inj）","point":"与神经损伤的鉴别：腋神经损伤可致三角肌萎缩与外展无力，但肌电图与感觉分布可鉴别；肩袖撕裂的无力在特定方向（外展/外旋）。"},{"name":"腰椎滑脱（or_lumbar_spondylolisthesis）","point":"与腰椎疾病的鉴别：症状在腰与下肢；无肩部体征。"},{"name":"类风湿关节炎外科治疗（or_ra_surgery）","point":"RA 可累及肩关节（滑膜炎与破坏）但为对称性多关节、有全身表现；肩袖撕裂为单独的肌腱病变。"},{"name":"肩峰下撞击综合征","point":"**常为肩袖撕裂的前驱**：撞击试验阳性但无全层撕裂（MRI 见肌腱炎或滑囊炎）；治疗以保守为主。"},{"name":"冻结肩（粘连性关节囊炎）","point":"**主动与被动活动度均受限**（尤其外旋），MRI 见关节囊增厚；肩袖撕裂以主动活动受限而被动活动度多保留。"},{"name":"钙化性肌腱炎","point":"急性剧痛、X 线见肩袖内钙化灶；可与肩袖撕裂并存。"},{"name":"颈椎病（C5 神经根）","point":"颈源性肩痛、Spurling 试验阳性、神经根分布的感觉异常；肩部检查（撞击试验）阴性。"}],"tx":{"drug":[{"name":"非甾体抗炎药","dose":"塞来昔布 200 mg bid 或布洛芬 400–600 mg q6–8h，短期（2–4 周）","note":"缓解疼痛与炎症；长期使用需评估风险","renal":"eGFR <30 避免","hepatic":"重度肝病禁用","interact":"与抗凝、抗血小板合用增加消化道出血"},{"name":"肩峰下糖皮质激素注射","dose":"复方倍他米松 1 mL + 利多卡因（超声引导下注射，单次，可 3 个月后重复）","note":"短期缓解疼痛（尤其撞击综合征）；**反复注射可致肌腱质量下降，不建议 >3 次/年**；注射后需避免短期内过度活动","renal":"无需调整","hepatic":"监测","interact":"与抗凝合用增加注射部位出血"},{"name":"透明质酸注射（争议）","dose":"按制剂方案（部分研究支持）","note":"证据有限，不推荐常规使用","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"围术期抗生素预防","dose":"头孢唑林 1–2 g 术前 30–60 分钟","note":"肩关节镜手术后感染率低（<1%），但一旦发生后果严重","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与华法林合用"},{"name":"镇痛（术后，含区域阻滞）","dose":"肌间沟臂丛阻滞（罗哌卡因 0.5% 20–30 mL）+ 对乙酰氨基酚 + 弱阿片类","note":"肩袖修复术后疼痛明显，区域阻滞可显著减少阿片类用量","renal":"按 CrCl 调整","hepatic":"限量","interact":"局麻药与阿片类合用注意呼吸抑制"}],"nonDrug":["**保守治疗（多数患者首选）**：物理治疗（肩胛骨稳定训练、肩袖强化、活动度训练）、避免过顶动作与疼痛性活动，疗程 6–12 周","**手术指征**：① 急性外伤性撕裂（尤其年轻、运动需求高）；② 保守治疗 3–6 个月失败的疼痛与功能障碍；③ 大或巨大撕裂（进展风险高，尤其中年患者）；④ 部分撕裂 >50% 厚度","**手术方式**：**关节镜下肩袖修复（锚钉缝合）**；巨大不可修复撕裂可考虑**上关节囊重建（SCR）**、肌腱转位（背阔肌/胸大肌）或反式肩关节置换（合并 cuff tear arthropathy 的老年患者）","**部分撕裂**：关节侧清理或转为全层后修复（>50% 厚度）","**术后康复**：0–6 周保护（支具、被动活动）；6–12 周主动辅助与主动活动；12 周后强化训练（愈合需 6–12 周）"],"life":["**戒烟**（显著影响肌腱愈合与修复后再撕裂率）","控制血糖（糖尿病者的修复失败率更高）","**术后严格遵康复方案**（过早主动活动可致修复失败）","避免长期过顶运动与重复投掷（运动员需技术调整）","**长期随访**：修复后再撕裂率 10%–30%（与撕裂大小、脂肪浸润、年龄相关）","家庭训练（弹力带肩袖强化）需长期坚持"]},"prog":"保守治疗对中小撕裂与撞击综合征的有效率约 60%–80%。**关节镜修复的短期（1–2 年）满意率约 80%–90%，但影像学再撕裂率 10%–30%**（巨大撕裂可达 40%–90%）。预后不良因素：巨大撕裂、Goutallier 脂肪浸润 ≥3 级、年龄 >65 岁、吸烟、糖尿病。不可修复撕裂的长期功能下降与 cuff tear arthropathy 风险需密切随访。","refs":["《外科学》第 9 版（人民卫生出版社）肩关节损伤章","2019 AAOS Clinical Practice Guideline: Management of Rotator Cuff Injuries","2018 European Society for Surgery of the Shoulder and the Elbow (SECEC) Consensus on Rotator Cuff Tears","Goutallier Classification of Fatty Infiltration (1994)","《中国肩袖损伤诊疗指南》（2022）"]}]},{"id":"spine_trauma","name":"脊柱骨折","rank":41,"summary":"脊柱骨折的处置顺序是「先救命、再保神经、后稳脊柱」：先按 ATLS 处理血流动力学与合并伤，再用 ASIA 标准记录神经平面；稳定性用 Denis 三柱判断，是否手术用 TLICS（≥5 分手术、≤3 分保守）与 AOSpine 分型决定，椎体高度丢失 >50%、后凸 >20°–30%、椎管占位 >40% 是常用的影像学手术阈值。","compare":[],"diseases":[{"id":"or_spine_fx","name":"脊柱骨折","aka":["Spinal Fracture","Vertebral Fracture","Thoracolumbar Fracture","胸腰椎骨折","脊柱骨折脱位"],"rank":1,"basic":{"define":"脊柱骨折指椎体、附件或韧带复合体在外力作用下连续性中断，胸腰段（T11–L2）是最常见部位。按 Denis 三柱理论判断稳定性、按 TLICS 与 AOSpine 分型决定是否手术；约 10%–20% 合并脊髓、圆锥或马尾损伤。","risk":["高能量创伤：机动车事故、高处坠落、重物砸伤（胸腰段最多见）","老年人低能量跌倒（骨质疏松，多为楔形压缩骨折）","长期糖皮质激素、绝经后骨质疏松、维生素 D 缺乏","强直性脊柱炎、DISH（弥漫性特发性骨增生）——轻微外力即可发生不稳定的过伸剪切骨折","脊柱转移瘤、多发性骨髓瘤（病理性骨折）","颈段损伤多见于跳水、骑车跌倒、交通事故（安全带伤致屈曲-牵张损伤）"],"epi":"脊柱骨折占全身骨折约 5%–6%，胸腰段（T11–L2）占脊柱骨折的 60% 以上；约 10%–20% 合并脊髓损伤，颈段骨折合并脊髓损伤的比例最高（可达 40%）。高能量伤者中约 10%–20% 存在多节段椎体骨折，容易漏诊。"},"patho":"Denis 三柱：前柱为前纵韧带与前 2/3 椎体及纤维环，中柱为后纵韧带与后 1/3 椎体及纤维环，后柱为椎弓、关节突、黄韧带与棘间/棘上韧带。屈曲-压缩伤仅累及前柱（楔形压缩）；轴向压缩使中柱受累、骨块突入椎管（爆裂骨折）；屈曲-牵张伤撕裂后柱张力带（Chance 骨折、安全带伤）；剪切-旋转伤累及三柱，最不稳定。脊髓损伤由原发机械压迫与挫伤，加上继发水肿、缺血、炎症级联反应共同造成；T12–L1 以下为马尾，损伤表现为下运动神经元性瘫痪与括约肌功能障碍。","dx":{"criteria":["明确外伤史 + 局部疼痛、压痛、叩击痛、脊柱活动受限；颈段损伤可伴头颈姿势异常、吞咽困难或枕部疼痛。","神经学评估按 ASIA 标准：记录感觉平面（28 个皮节，针刺与轻触 0–2 分）、运动平面（10 组关键肌，0–5 级）、骶段保留（S4–5 感觉与肛门自主收缩）；无骶段保留为完全性损伤（ASIA A）。","Denis 三柱中 ≥2 柱受累即为不稳定；中柱受累是爆裂骨折与不稳定的关键（单纯前柱压缩属稳定）。","影像学手术阈值：椎体前缘高度丢失 >50%、局部后凸 >20°–30°、椎管占位 >40%–50%、棘突间距较相邻节段增宽 >1.5 倍（提示后柱韧带复合体 PLC 损伤）。","TLICS 评分：形态（压缩 1、爆裂 2、平移/旋转 3、牵张 4）+ PLC（完整 0、可疑 2、断裂 3）+ 神经（完整 0、神经根 2、完全脊髓 2、不完全脊髓 3、马尾 3）；≥5 分手术，≤3 分保守，4 分可保守可手术。","MRI T2/STIR 高信号提示 PLC 损伤、脊髓水肿或出血、椎间盘损伤；伤后 24–72 小时内检查最有价值。","老年低能量跌倒：腰背痛 + X 线楔形变，MRI STIR 高信号提示新鲜骨折；需与陈旧楔形变、转移瘤鉴别（后者椎弓根破坏、伴软组织肿块）。","合并伤筛查：胸腰段骨折常合并肋骨骨折、血气胸、腹腔脏器伤、骨盆环骨折；骶骨骨折与骨盆损伤可致腹膜后大出血。"],"workup":["全脊柱 X 线正侧位（颈、胸、腰分段拍摄；高能量伤需全脊柱，避免漏诊跳跃性骨折）","CT 薄层 + 矢状位/冠状位重建：评估椎体后壁破裂、椎弓根间距、关节突交锁、椎管占位与棘突间距","MRI（T1/T2/STIR）：脊髓信号、PLC、椎间盘、隐匿骨折；有神经症状者必查","ASIA 神经学检查：入院、术前、术后 72 小时、出院与随访各记录一次","实验室：血常规、凝血、电解质、血糖、乳酸；老年患者查 DXA（T ≤ −2.5 诊断骨质疏松）","合并伤：胸腹 CT/FAST、骨盆 X 线，疑大血管损伤时行主动脉 CTA"],"grading":"① Denis 分型：压缩型、爆裂型、屈曲-牵张型（Chance）、骨折脱位型；② AOSpine 胸腰段分型：A0–A4（压缩/爆裂，A4 为完全爆裂）、B1–B3（张力带失败）、C（移位/脱位），神经分级 N0（无损伤）–N4（完全脊髓损伤），M1/M2 为终板或后凸修饰；③ TLICS 0–10 分指导手术决策。"},"ddx":[{"name":"骨质疏松性椎体压缩骨折（or_ovcf）","point":"最易混淆的邻类疾病：低能量跌倒后腰背痛、X 线见上终板楔形压缩，但中柱与后柱完整、无神经症状，MRI STIR 高信号提示新鲜骨折；创伤性脊柱骨折有明确高能量暴力，CT 见后壁破裂、椎弓根间距增宽或 PLC 损伤。"},{"name":"脊柱转移瘤病理性骨折","point":"无明确外伤或轻微外力即骨折，以夜间痛为主，X 线/CT 见椎弓根破坏（猫头鹰眨眼征）、椎体后壁相对完整而附件破坏，MRI 见异常信号贯穿椎体并伴软组织肿块；必要时活检确诊。"},{"name":"强直性脊柱炎/DISH 过伸损伤","point":"轻微跌倒后剧烈颈背痛，X 线见竹节样脊柱或连续性骨赘，骨折线常横贯三柱（剪切骨折），极易漏诊；需 CT 三维重建，按不稳定骨折处理。"},{"name":"脊髓震荡（spinal concussion）","point":"伤后短暂感觉运动丧失，24–48 小时内完全恢复，影像无骨折脱位与脊髓信号异常；与不完全性脊髓损伤的鉴别靠动态 ASIA 评分。"},{"name":"腰椎间盘突出伴马尾综合征（or_ldh）","point":"无骨折，突发鞍区麻木、尿潴留、双下肢无力，MRI 见巨大中央型间盘突出压迫马尾；脊柱骨折所致马尾损伤有明确骨折与椎管占位。"},{"name":"无骨折脱位型颈髓损伤（SCIWORA）","point":"老年人跌倒后颈部痛、四肢无力，X 线/CT 无骨折，MRI 见脊髓高信号（常伴发育性椎管狭窄）；易被误认为脑梗死，需查颈椎 MRI。"},{"name":"骨盆骨折（or_pelvis）","point":"骨盆挤压-分离试验阳性、血流动力学不稳定，X 线/CT 见骨盆环断裂；脊柱骨折者骨盆检查阴性，但高能量伤可两者并存，需同时评估。"},{"name":"腹膜后血肿/腹腔脏器损伤","point":"胸腰段骨折后腹胀、腹痛、血压下降，FAST 见腹腔或腹膜后积液；需与失血性休克的其他来源鉴别，先处理出血再谈脊柱固定。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"口服 0.5–1 g q6h，24 小时不超过 3 g；老年、低体重或肝病者不超过 2 g/d","note":"基础镇痛药，可与其他镇痛药联合；疼痛剧烈时需加阿片类，不要单靠加量对乙酰氨基酚","renal":"CrCl <30 延长给药间隔至 q8h","hepatic":"肝硬化、活动性肝病减至 ≤2 g/d 或避免使用","interact":"长期大剂量与华法林合用可升高 INR；与酒精、异烟肼、卡马西平合用增加肝毒性"},{"name":"塞来昔布（或布洛芬）","dose":"塞来昔布 200 mg 口服 q12h；或布洛芬 400 mg 口服 q8h，餐后服，疗程尽量 ≤7 天","note":"用于急性期疼痛与软组织肿胀；脊柱融合术后 4–6 周内尽量避免长期使用（理论上抑制骨融合，证据尚有争议）","renal":"CrCl <30 避免使用；用药前评估容量状态","hepatic":"重度肝功能不全（Child-Pugh C）禁用","interact":"与抗凝/抗血小板药、ACEI/ARB、利尿剂、锂剂合用风险增加；与糖皮质激素合用增加消化道出血"},{"name":"吗啡（或羟考酮）","dose":"吗啡 5–10 mg 口服 q4h 按需，剧痛可静脉 2–4 mg 缓慢滴定；或羟考酮 5 mg 口服 q6h","note":"中重度疼痛首选；老年人、睡眠呼吸暂停、合并颅脑伤者减量；同时给予缓泻剂预防便秘","renal":"CrCl <30 减量并延长间隔（代谢产物蓄积，易过度镇静）","hepatic":"肝硬化减量 50% 并延长间隔","interact":"与苯二氮䓬类、加巴喷丁类、抗组胺药合用增加呼吸抑制"},{"name":"头孢唑林（围术期预防）","dose":"1–2 g 静脉术前 30–60 分钟（体重 >80 kg 用 2 g）；手术超过 4 小时或失血 >1500 mL 术中追加 1 次，术后 ≤24 小时停药","note":"覆盖金黄色葡萄球菌与表皮葡萄球菌；内固定植入手术必须预防用药；青霉素速发型过敏者改用克林霉素","renal":"CrCl <30 术后减量或延长间隔","hepatic":"无需调整","interact":"与华法林合用可增加出血风险"},{"name":"依诺肝素（静脉血栓预防）","dose":"40 mg 皮下 qd，术后 12–24 小时开始（出血风险高者延迟至 24–48 小时）；脊髓损伤患者预防持续 8–12 周","note":"脊髓损伤是 VTE 极高危人群（未预防者 DVT 可达 60%–80%），需机械（间歇充气加压）+ 药物联合预防","renal":"CrCl <30 减为 30 mg 皮下 qd","hepatic":"重度肝病、凝血障碍者慎用","interact":"与抗血小板药、NSAIDs 合用增加出血；与椎管内麻醉需按规范间隔给药"},{"name":"甲泼尼龙（争议，仅选择性使用）","dose":"伤后 8 小时内：甲泼尼龙 30 mg/kg 静脉 15 分钟负荷，继以 5.4 mg/kg/h 持续 23 小时","note":"AANS/CNS 指南不推荐常规用于急性脊髓损伤（神经功能获益未证实，感染、消化道出血、高血糖风险增加）；不得用于穿透性脊髓损伤；仅在个别中心对急性颈髓不全损伤选择性使用","renal":"无明确调整资料，遵说明书","hepatic":"无明确调整资料，遵说明书","interact":"与 NSAIDs 合用显著增加消化道出血；可升高血糖、加重感染"}],"nonDrug":["急救与制动：颈托/脊柱板固定，轴线翻身；血流动力学不稳定者先复苏（骨盆带、止血、输血），再行影像检查","保守治疗：TLICS ≤3 分且 PLC 完整者卧床 2–6 周后佩带胸腰骶支具（TLSO）8–12 周，早期离床活动；单纯压缩骨折后凸 <20° 可保守","手术指征：TLICS ≥5 分；椎体高度丢失 >50%、后凸 >20°–30°、椎管占位 >40%–50%；PLC 损伤；进行性神经功能障碍；骨折脱位","术式选择：后路短节段椎弓根螺钉固定（最常用，可加伤椎椎体成形/骨水泥强化）；前路椎体切除植骨融合（严重前柱塌陷）；经皮微创螺钉（无神经症状的 A 型骨折）；骨折脱位需前后路联合或长节段固定","脊髓损伤：颈髓不全损伤争取 24 小时内减压；维持平均动脉压 85–90 mmHg 5–7 天，避免低血压与低氧","早期康复与并发症预防：每 2 小时翻身防压疮、间歇导尿、呼吸训练（颈髓损伤）、痉挛与神经病理性疼痛管理"],"life":["支具佩戴 8–12 周，佩戴期间避免弯腰、负重与突然扭转；每 2–4 周复查支具贴合度","绝对戒烟（吸烟使融合率下降、假关节率升高）","老年患者启动抗骨质疏松治疗：钙 1000–1200 mg/d + 维生素 D 800–1200 IU/d，必要时抗骨吸收药物","术后 6 周、3 个月、6 个月、12 个月复查 X 线，评估内固定位置、后凸矫正丢失与融合","重体力劳动与驾驶一般术后 3–6 个月逐步恢复；脊髓损伤者需终身随访泌尿、皮肤与呼吸功能"]},"prog":"无神经损伤的 A 型骨折经保守或手术后功能恢复良好（>90% 恢复日常生活）。不完全性脊髓损伤约 50%–70% 可恢复独立行走，完全性脊髓损伤的神经恢复有限。主要并发症为深静脉血栓、压疮、肺炎、尿路感染与内固定失败/后凸矫正丢失（短节段固定约 5%–15%）。","refs":["《成人胸腰椎骨折内固定术后康复治疗循证指南（2025 版）》（中国医师协会骨科医师分会脊柱创伤学组）","Vaccaro AR, et al. AOSpine Thoracolumbar Spine Injury Classification System. Spine 2013;38:2028–2037","Vaccaro AR, et al. The Thoracolumbar Injury Classification and Severity Score (TLICS). Spine 2005;30:2325–2333","ASIA/ISCoS. International Standards for Neurological Classification of Spinal Cord Injury, Revised 2019","《外科学》第 9 版（人民卫生出版社）脊柱骨折章"]}]},{"id":"deformity","name":"脊柱与四肢畸形","rank":42,"summary":"三类畸形的共同原则是「按生长潜能与可塑性决定干预强度」：脊柱侧凸看 Cobb 角 + Risser 征，斜颈看年龄与被动活动度，马蹄内翻足看 Dimeglio 分型与开始治疗的时机；支具与石膏的依从性往往比术式更决定结局。","compare":[{"diseaseId":"or_scoliosis","dx":"站立位 Cobb 角 ≥10°、Adam 前屈试验阳性、椎体旋转（Nash-Moe），Risser 0–2 提示高进展风险","key":"按 Cobb 角分层：<25° 观察、25–40° 支具 16–23 h/d、>40–50° 手术；左侧胸弯须查 MRI 排除脊髓病变"},{"diseaseId":"or_torticollis","dx":"头偏向患侧、下颌转向健侧，患侧胸锁乳突肌可触及条索，被动旋转较健侧减少 ≥15°","key":"年龄决定治疗：1 岁内手法牵伸 + 体位疗法，1 岁后残留挛缩或面部不对称行胸锁乳突肌松解"},{"diseaseId":"or_clubfoot","dx":"出生即见高弓、前足内收、后足内翻、马蹄四联畸形，Dimeglio/Pirani 评分定量，被动不能矫正至中立位","key":"Ponseti 序贯石膏 + 经皮跟腱切断 + 支具至 4–5 岁；支具依从性是复发最强预测因素"}],"diseases":[{"id":"or_scoliosis","name":"脊柱侧凸","aka":["Scoliosis","Adolescent Idiopathic Scoliosis","AIS","青少年特发性脊柱侧凸"],"rank":1,"basic":{"define":"脊柱侧凸是脊柱在冠状面向侧方弯曲（站立位 X 线 Cobb 角 ≥10°）并伴椎体旋转的三维畸形，同时存在矢状面（胸椎后凸减少、腰椎前凸）与轴位（椎体旋转、肋骨隆起）改变。青少年特发性脊柱侧凸（AIS）占全部病例约 80%，是青春期最常见的脊柱畸形。","risk":["女性：AIS 女:男约 4–7:1，Cobb 角 >30° 者女性占绝大多数","青春期生长高峰（女孩 10–12 岁、男孩 12–14 岁），Risser 0–2 时进展最快","一级亲属患病（家族聚集，风险较普通人群升高约 2–3 倍）","神经肌肉疾病：脑瘫、脊髓性肌萎缩（SMA）、Duchenne 肌营养不良","先天性椎体畸形（半椎体、分节不良、蝴蝶椎）","结缔组织病：马方综合征、Ehlers-Danlos 综合征"],"epi":"Cobb 角 ≥10° 的患病率约 2%–3%，≥20° 约 0.3%–0.5%，≥40° 约 0.1%；女性进展风险显著高于男性。胸弯以右侧多见，左侧胸弯需警惕脊髓空洞、Chiari 畸形或脊髓肿瘤。"},"patho":"遗传异质性是基础（多基因遗传叠加少数单基因突变），再叠加神经肌肉控制异常、前庭与本体感觉失衡。畸形自我加重遵循 Hueter-Volkmann 定律：椎体压力侧骺板生长受抑、张力侧生长加速，形成「侧凸—不对称负荷—侧凸加重」的恶性循环。椎体旋转使肋骨向背侧隆起（剃刀背），胸廓容积下降；Cobb 角 >70°–100° 时可出现限制性通气障碍、低氧血症与肺心病。","dx":{"criteria":["站立位全脊柱正侧位 X 线（含双侧髂嵴）：Cobb 角 ≥10° 诊断脊柱侧凸；<10° 称脊柱不对称（spinal asymmetry），不作诊断但需随访。","Cobb 角测量：取侧弯上、下端椎终板的垂线交角；多弯时分别测量，以最大弯为准。","Adam 前屈试验：双膝伸直、前屈 90°，背部不对称或躯干旋转角（ATR）≥7° 者需拍片；ATR <5° 可先观察。","椎体旋转度按 Nash-Moe 分 0–Ⅳ 度；Risser 征 0–5 级（髂骨翼骨化范围 0%、25%、50%、75%、100%、完全融合），Risser 0–2 为高生长潜能。","神经查体：腹壁反射、双下肢肌力与感觉、病理反射、括约肌功能；年龄 <10 岁、左侧胸弯、疼痛性侧凸、快速进展（>1°/月）或存在神经体征者必须查全脊柱 MRI。","肺功能：Cobb 角 >70° 或胸弯明显者查 FVC、FEV1 与动脉血气；限制性通气障碍表现为 TLC <70% 预计值、FVC 下降。","拟手术者查心肺运动试验、超声心动图（马方综合征需测主动脉根部直径）、凝血功能与血型。"],"workup":["站立位全脊柱长片正侧位（含颈椎至骨盆）；侧屈位或悬吊位片评估柔韧性","全脊柱 MRI：指征为年龄 <10 岁、左侧胸弯、疼痛、神经体征、快速进展、非典型曲线（排除脊髓空洞、Chiari 畸形、脊髓栓系、肿瘤）","肺功能 + 血气（Cobb >70°）、超声心动图（马方综合征/先天性心脏病）","骨龄：Risser 征 + 手腕骨龄（Sanders 分型），结合月经初潮时间判断剩余生长潜能","术前：血常规、凝血、肝肾功能、交叉配血，建立脊髓监护（MEP/SEP）基线"],"grading":"① 病因：特发性（婴儿型 <3 岁、少儿型 4–9 岁、青少年型 ≥10 岁）、先天性、神经肌肉性、综合征性；② Cobb 角：<10° 脊柱不对称，10–25° 轻度，25–40° 中度，>40° 重度；③ Risser 0–5 评估剩余生长潜能；④ Lenke 分型（1–6 型，腰弯修正 A/B/C）指导融合节段选择；⑤ 矢状面按 SRS-Schwab 分型（PI-LL、PT、SVA）评估。"},"ddx":[{"name":"先天性肌性斜颈（or_torticollis）","point":"与本类中先天性肌性斜颈的鉴别：斜颈表现为头向患侧偏、下颌转向健侧，胸锁乳突肌可触及条索或包块，脊柱本身无结构性侧凸（Adam 试验阴性）；脊柱侧凸为躯干三维畸形（侧凸 + 椎体旋转 + 胸廓不对称），颈部姿势性偏斜不伴胸锁乳突肌挛缩。注意斜颈长期未矫正可致继发性颈胸段代偿弯，需站立位全脊柱片鉴别。"},{"name":"先天性椎体畸形（半椎体/分节不良/蝴蝶椎）","point":"婴幼儿期即发现，曲线僵硬、进展快，常伴椎体楔变、蝴蝶椎或分节不良；X 线/CT 三维重建见椎体形态异常，MRI 需排除脊髓纵裂与栓系。"},{"name":"神经肌肉疾病所致躯干畸形（脑瘫、SMA、DMD）","point":"长 C 形弯、骨盆倾斜明显，伴原发病的运动发育落后、肌张力异常或肌萎缩；坐位平衡差、支具耐受性低，常需骨盆固定型支具或生长棒。"},{"name":"脊髓空洞症/Chiari 畸形","point":"多为左侧胸弯，伴上肢感觉分离、手内在肌萎缩、颈肩痛或共济失调；MRI 见脊髓中央高信号或小脑扁桃体下疝 >5 mm，需先处理神经外科问题。"},{"name":"马方综合征","point":"身材高大、蜘蛛指、晶状体脱位、主动脉根部扩张（>40 mm）；侧凸常为双弯且进展快，需心脏评估后再决定手术时机。"},{"name":"脊柱结核/化脓性脊柱炎","point":"疼痛、夜间痛、低热，ESR/CRP 升高，X 线见椎体破坏与椎间隙变窄，MRI 见椎旁脓肿；应先抗结核/抗感染治疗，而非矫形。"},{"name":"姿势性侧凸","point":"站立时明显、坐位或前屈时消失，侧屈位片可完全矫正，无椎体旋转与肋骨隆起；无需支具，纠正姿势与核心肌力训练即可。"},{"name":"双下肢不等长","point":"骨盆倾斜致代偿性腰弯，短肢侧垫高 1–2 cm 后侧凸消失；双下肢全长片测量可确诊。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"儿童 10–15 mg/kg 口服 q6h，24 小时 ≤75 mg/kg；成人 0.5–1 g q6h，24 小时 ≤3 g","note":"支具压迫处疼痛与术后基础镇痛；总量需合并计算复方感冒药中的对乙酰氨基酚","renal":"CrCl <30 延长给药间隔至 q8h","hepatic":"肝硬化/活动性肝病减至 ≤2 g/d 或避免","interact":"长期大剂量与华法林合用可升高 INR；与酒精、异烟肼合用增加肝毒性"},{"name":"布洛芬","dose":"儿童 5–10 mg/kg 口服 q6–8h（24 小时 ≤40 mg/kg）；成人 400 mg q8h，餐后服","note":"用于支具不适或术后短期镇痛；脊柱融合术后 4–6 周内尽量避免长期使用（理论上有抑制骨融合风险，证据尚有争议）","renal":"CrCl <30 避免使用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、ACEI/ARB、利尿剂、锂剂合用风险增加"},{"name":"氨甲环酸","dose":"负荷 10–20 mg/kg（≤1 g）静脉 15–30 分钟，维持 10 mg/kg/h 至术毕（或 10 mg/kg/h 持续 5 小时）","note":"后路矫形手术失血量可减少 30%–40%，降低输血率；既往血栓史、活动性血栓者禁用","renal":"CrCl <30 减量（主要经肾排泄）","hepatic":"无需调整","interact":"与抗凝药、抗血小板药合用增加出血风险"},{"name":"头孢唑林（围术期预防）","dose":"30 mg/kg（≤2 g）静脉术前 30–60 分钟；手术 >4 小时或失血 >1500 mL 追加 1 次，术后 ≤24 小时","note":"脊柱内固定手术属清洁-污染切口，必须预防用药；青霉素速发型过敏改用克林霉素","renal":"CrCl <30 术后减量或延长间隔","hepatic":"无需调整","interact":"与华法林合用可增加出血风险"},{"name":"吗啡（术后 PCA）","dose":"PCA：背景 10–20 μg/kg/h，单次 10–20 μg/kg，锁定 6–10 分钟，按疼痛评分与呼吸频率滴定","note":"青少年脊柱融合术后疼痛剧烈，PCA 优于按需肌注；需监测呼吸抑制、恶心、瘙痒与肠麻痹，常规联用止吐与缓泻","renal":"CrCl <30 减量并延长间隔（代谢产物蓄积）","hepatic":"肝硬化减量","interact":"与苯二氮䓬类、加巴喷丁类合用增加呼吸抑制"}],"nonDrug":["观察随访：Cobb 10–25° 且 Risser 3–5（生长接近结束）者每 6–12 个月复查站立位全脊柱片；进展 >5°/年或累计 >10° 需升级治疗","支具治疗：Cobb 25–40° 且 Risser 0–2（或月经初潮前/初潮 1 年内），全天佩戴 16–23 小时（BrAIST 研究：每日 ≥12.9 小时有效，≥18 小时成功率更高），至 Risser 4–5 或月经初潮后 2 年；Cobb <25° 不推荐支具","手术治疗：Cobb >40–50°（生长期 >40°、骨骼成熟后 >50°）或每年进展 >5°、胸弯 >60° 影响肺功能、腰弯 >45° 伴疼痛；后路椎弓根螺钉矫形融合，按 Lenke 分型选择融合节段，尽量保留活动节段","生长友好技术：年龄 <10 岁、生长潜能大者可用生长棒（growing rod）；VBT（椎体拴系）适应证严格（Cobb 30–65°、柔韧性好、Risser 0–2）","极重度（Cobb >100°）或僵硬弯：术前 Halo 牵引或一期前后路松解，先改善肺功能再矫形","康复与安全保障：Schroth 特定体操、核心肌群与呼吸训练（不能替代支具或手术）；术中脊髓监护（MEP/SEP）+ 唤醒试验"],"life":["支具佩戴时间需记录（部分支具配温度传感器），每日不足 13 小时基本无效","每 6 个月复查至骨骼成熟；成年后每 2–3 年随访一次（>50° 的胸弯仍可缓慢进展）","避免单侧负重与长期不对称姿势；可游泳、慢跑，术后 6 个月内避免对抗性运动与重物负重","重度侧凸女性妊娠前评估肺功能与麻醉风险；马方综合征每年查主动脉超声","学校筛查（Adam 试验）与心理支持：支具治疗青少年抑郁与体像障碍发生率明显升高"]},"prog":"进展风险取决于 Cobb 角与 Risser 征：Risser 0–1 且 Cobb 20–29° 者进展风险约 60%–70%，Cobb 30–39° 可达 70%–80%，Risser 3–4 且 Cobb <30° 者 <10%。支具可使治疗成功率从 48% 提高到 72%（BrAIST 随机对照研究）。后路融合术后矫形率 50%–70%，永久性神经损伤 <1%，假关节率 1%–3%。","refs":["《中国青少年脊柱侧凸筛查临床实践指南及路径指引》（2020）","2016 SOSORT Guidelines: Orthopaedic and Rehabilitation Treatment of Idiopathic Scoliosis during Growth","Weinstein SL, et al. Effects of Bracing in Adolescents with Idiopathic Scoliosis. N Engl J Med 2013（BrAIST 研究）","Lenke LG, et al. Adolescent Idiopathic Scoliosis: A New Classification. J Bone Joint Surg Am 2001","《外科学》第 9 版（人民卫生出版社）脊柱侧凸章"]},{"id":"or_torticollis","name":"先天性肌性斜颈","aka":["Congenital Muscular Torticollis","CMT","斜颈","胸锁乳突肌挛缩"],"rank":2,"basic":{"define":"先天性肌性斜颈是胸锁乳突肌（SCM）纤维化挛缩引起的头颈姿势性畸形：头偏向患侧、下颌转向健侧，伴颈部被动活动受限，可继发斜头畸形与面部不对称。","risk":["臀位产（尤其臀位，风险显著升高）","初产、巨大儿、产程延长","宫内拥挤（多胎、羊水过少）","生后长期仰卧同一侧（姿势性斜颈）","约 10%–20% 合并发育性髋关节发育不良（DDH），需常规筛查髋关节"],"epi":"发病率约 0.3%–2%（活产儿），右侧略多（约 60%），其中约 10%–20% 为姿势型（无 SCM 包块）。生后 2–3 周出现 SCM 硬结，2–6 个月最明显，多数在 1 岁内消退；80%–90% 经保守治疗可恢复。"},"patho":"宫内姿势异常或产伤致 SCM 局部缺血、静脉回流受阻，肌纤维间质水肿、纤维化并被纤维组织替代，肌肉长度缩短形成持续牵拉。长期头颈偏斜使患侧颅面受压（同侧枕部变平、对侧额部前突），半侧面部发育受限（眼、耳位置下移），并可继发颈胸段代偿性侧凸。SCM 的「包块」并非真正血肿，而是纤维化的肌组织。","dx":{"criteria":["头偏向患侧、下颌转向健侧，颈部主动与被动旋转/侧屈受限。","患侧 SCM 中下 1/3 可触及硬结或条索（生后 2–3 周出现），质硬、无压痛、随肌肉移动。","被动旋转度：患侧较健侧减少 ≥15°，或绝对旋转 <80°（正常婴儿被动旋转约 100°–110°、侧屈约 70°）即为异常。","头颅形态：斜头畸形（同侧枕部扁平、对侧额部前突）、面部不对称（双眼/双耳连线偏移 >5 mm）。","颈部超声：患侧 SCM 较健侧增厚 >2 mm，或见局灶性低回声包块，可评估纤维化程度并随访。","排除骨性斜颈：颈椎 X 线/CT（Klippel-Feil 综合征、半椎体、分节不良）；外伤或上呼吸道感染后突发斜颈者查寰枢椎 CT，排除旋转固定。","眼科检查排除眼性斜颈（上斜肌麻痹）；伴呕吐、共济失调、眼球震颤者查头颅 MRI，排除后颅窝肿瘤。","髋关节超声（Graf 分型，<6 个月）或骨盆 X 线，筛查 DDH。"],"workup":["颈部超声：测量双侧 SCM 厚度、回声与包块范围，作为基线与随访依据","髋关节超声（<6 个月）或骨盆正位片，筛查 DDH","颈椎 X 线/CT：>6 个月、非典型表现或保守治疗 3–6 个月无效时","眼科会诊（遮盖试验、眼位与眼球运动），排除眼性斜颈","头颅 MRI：伴神经体征、呕吐、共济失调或斜颈进行性加重时","标准化照片（正位、俯卧抬头位）每 3 个月记录面部与头颅对称性"],"grading":"① 临床分型：SCM 肿块型（最常见）、姿势型（无包块、仅姿势偏斜）、肌性斜颈伴面部不对称；② 严重度：轻度（被动旋转受限 <15°）、中度（15°–30°）、重度（>30° 或固定畸形）；③ 超声按 SCM 厚度与回声分级用于随访。"},"ddx":[{"name":"脊柱侧凸（or_scoliosis）","point":"与本类中脊柱侧凸的鉴别：斜颈为颈部姿势性偏斜、胸锁乳突肌可触及挛缩条索、颈椎被动旋转受限，脊柱无结构性侧凸、Adam 前屈试验阴性；脊柱侧凸为躯干不对称伴椎体旋转与肋骨隆起。斜颈长期未矫正可致继发性颈胸段代偿弯，需站立位全脊柱片区分。"},{"name":"骨性斜颈（Klippel-Feil 综合征/半椎体）","point":"短颈、后发际低、颈椎各方向活动均受限，X 线/CT 见颈椎融合或半椎体；牵伸治疗无改善，常伴其他系统畸形。"},{"name":"寰枢椎旋转固定（Grisel 综合征）","point":"上呼吸道感染或轻微外伤后突发斜颈，颈部拒动、疼痛明显，CT 见寰齿间距增宽或 C1 侧块旋转固定；需牵引/固定，禁忌强行手法扳动。"},{"name":"眼性斜颈","point":"头位偏斜以代偿眼肌麻痹（多为上斜肌麻痹）引起的复视或代偿头位，遮盖一眼后头位改善，颈部活动正常、无 SCM 挛缩。"},{"name":"后颅窝肿瘤/神经源性斜颈","point":"伴晨起头痛、呕吐、共济失调、眼球震颤，斜颈为强迫头位；头颅 MRI 确诊，按神经外科处理。"},{"name":"姿势性斜颈","point":"无 SCM 包块与挛缩，被动活动正常，改变体位或吸引注意力时头位可自行矫正，无需手术。"},{"name":"颈部淋巴结炎/脓肿","point":"发热、局部红肿压痛、颈部包块，超声见液化区；抗感染或切开引流后斜颈缓解。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"10–15 mg/kg 口服 q6h，24 小时 ≤75 mg/kg","note":"术后与手法治疗后疼痛；3 个月以下婴儿慎用并减量","renal":"CrCl <30 延长给药间隔","hepatic":"肝功能不全减量，活动性肝病避免","interact":"长期大剂量与华法林合用可升高 INR"},{"name":"布洛芬","dose":"5–10 mg/kg 口服 q6–8h，24 小时 ≤40 mg/kg，餐后服","note":"术后镇痛；6 个月以下婴儿慎用；脱水或肾功能不全时避免","renal":"CrCl <30 避免","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、利尿剂、ACEI/ARB 合用风险增加"},{"name":"A 型肉毒毒素（选择性）","dose":"onabotulinumtoxinA 1–2 U/kg，患侧 SCM 超声引导下 2–3 点注射，单次总量一般 ≤50 U","note":"仅用于 >1 岁残留挛缩或术后复发的辅助治疗，属超说明书用药，须知情同意；注射后 2 周起配合牵伸康复","renal":"无明确调整资料，遵说明书","hepatic":"无明确调整资料，遵说明书","interact":"与氨基糖苷类、肌松药合用可增强神经肌肉阻滞"},{"name":"头孢唑林（围术期预防）","dose":"30 mg/kg（≤2 g）静脉术前 30–60 分钟，术后 ≤24 小时","note":"SCM 松解术为清洁切口，感染风险低，单次给药即可","renal":"CrCl <30 减量或延长间隔","hepatic":"无需调整","interact":"与华法林合用可增加出血风险"}],"nonDrug":["1 岁内首选保守：家长手法牵伸——固定患侧肩部，头向健侧侧屈 + 向患侧旋转，每个动作维持 10–15 秒、重复 10–15 次，每日 4–6 次（累计 30–60 分钟）","体位疗法：俯卧抬头训练、用玩具/声音诱导向患侧转头；睡眠时交替头位，避免长期固定一侧","物理治疗：每周 2–3 次专业手法与被动活动，配合热疗；每月评估被动旋转度与面部对称性","斜头畸形：6 个月内以体位矫正为主；重度者 4–6 个月开始颅骨矫形帽，佩戴 3–6 个月","手术：>1 岁保守 3–6 个月无效、被动旋转受限 >15°–30°、面部不对称进行性加重或 SCM 明显条索，行单极（远端）或双极松解 + 部分切除；术后颈托/支具 2–4 周 + 康复 3–6 个月","合并 DDH 者同步按 DDH 方案处理（Pavlik 吊带或支具），避免只治斜颈漏诊髋关节"],"life":["家庭牵伸的依从性决定疗效，需教会家长并每月复评手法是否到位","睡姿与喂奶方向交替，避免患儿长期偏向一侧","每 3 个月拍照对比头颅与面部对称性，直至 2 岁","学龄期关注坐姿、书写姿势与视力，斜颈复发或出现代偿性侧凸时及时复诊","术后 1、3、6 个月复查颈部活动度，坚持主动旋转训练"]},"prog":"1 岁内保守治疗 80%–90% 有效，平均 3–6 个月恢复。未治疗者面部不对称在 1 岁后逐渐固定，5–6 岁后难以完全逆转。手术后被动旋转平均改善 20°–30°，复发率 5%–10%（>5 岁手术、双侧或综合征型更高）。斜头畸形在 1 岁内多可自行改善。","refs":["Kaplan SL, et al. Physical Therapy Management of Congenital Muscular Torticollis: 2024 Evidence-Based Clinical Practice Guideline（APTA 儿科物理治疗学会）","《实用小儿骨科学》（第 2 版，潘少川主编，人民卫生出版社）","《小儿外科学》（第 6 版，人民卫生出版社）先天性肌性斜颈章"]},{"id":"or_clubfoot","name":"先天性马蹄内翻足","aka":["Congenital Talipes Equinovarus","CTEV","Clubfoot","马蹄足"],"rank":3,"basic":{"define":"先天性马蹄内翻足是出生时即存在的足部三维畸形，包括高弓（cavus）、前足内收（adductus）、后足内翻（varus）与踝跖屈（equinus）。约 80% 为特发性，20% 合并神经肌肉疾病或综合征。","risk":["男性（男女比约 2:1）","同胞患病（再发风险约 2%–8%）","宫内拥挤、羊水过少、多胎","合并脊髓脊膜膨出、脊髓性肌萎缩、多关节挛缩","综合征：Larsen 综合征、Edwards 综合征、18 三体"],"epi":"发病率约 1–2/1000 活产儿（不同人群 0.6–6.8/1000），男性约为女性 2 倍，双侧约占 50%；我国约 1‰–2‰。"},"patho":"胚胎期足部发育停滞：距骨颈短、距骨头跖屈内偏，舟骨向内跖侧移位，跟骨内翻、马蹄，跟骰关节内移；胫后肌与腓骨肌力失衡，跟腱与跖筋膜挛缩。生后早期以软组织挛缩为主（可塑期），随负重与生长出现骨性畸形与关节面适应，故治疗应在生后 1–2 周内开始。","dx":{"criteria":["出生即见典型四联畸形：高弓、前足内收、后足内翻、踝跖屈；足跟小且内翻，足外侧缘突出。","被动矫正试验：不能将足被动背屈至中立位（背屈 ≥15°）并外翻，僵硬感明显；体位性足内翻可被动完全矫正。","Dimeglio 评分（0–20 分）：按马蹄、内翻、内收、高弓各 0–4 分加被动矫正度评分，Ⅰ 级 0–4（良性）、Ⅱ 级 5–9（中度）、Ⅲ 级 10–14（重度）、Ⅳ 级 15–20（极重度）。","Pirani 评分（0–6 分，中足 3 项 + 后足 3 项）：>1 分需治疗，≥5 分为重度；每次石膏前后对比。","负重年龄后：跟骨内翻、前足内收残留、足外侧胼胝、鞋外侧磨损，提示未矫正或复发。","X 线（负重正侧位，>6 个月）：正位距跟角正常 20°–40°、侧位 25°–50°，马蹄内翻足显著减小甚至为负值；距舟骨重叠提示畸形未矫正。","全身评估：脊柱（隐性脊柱裂、皮毛窦、脂肪瘤）、髋关节（DDH）、神经系统（肌力、感觉、反射）；双侧或伴其他畸形者查心脏与泌尿系超声。","排除姿势性足内翻：被动可完全矫正、无僵硬，数周内自行恢复，不需石膏。"],"workup":["每次石膏前后用 Dimeglio 与 Pirani 评分量化畸形与矫正进度","髋关节超声筛查 DDH（马蹄内翻足合并 DDH 约 5%–10%）","骶尾部超声或全脊柱 MRI（<6 个月）：双侧、伴神经体征或骶部皮肤异常者，排除脊髓栓系/脊髓脊膜膨出","X 线负重正侧位（>6 个月或复发时）评估距跟角与距舟关系","遗传与综合征筛查：面部特征、心脏超声、泌尿系超声，必要时染色体/基因检测","步态与足底压力分析（随访期）评估残留畸形与负重分布"],"grading":"① Dimeglio Ⅰ–Ⅳ 级；② Pirani 0–6 分；③ 病因：特发性（约 80%）、综合征性（合并神经肌肉或染色体异常）；④ 特殊类型：复杂型马蹄足（足短粗、深屈褶、对标准 Ponseti 反应差，需改良技术）。"},"ddx":[{"name":"先天性肌性斜颈（or_torticollis）","point":"与本类中先天性肌性斜颈的鉴别：两者均为出生即可见的先天性畸形，且可同时出现在多关节挛缩、Larsen 综合征等全身性疾病中，需全身筛查；斜颈为颈部旋转受限与头位偏斜、足部形态正常，马蹄内翻足为足部四联畸形、颈部查体正常。"},{"name":"姿势性（胎位性）足内翻","point":"宫内姿势所致，被动可完全矫正至中立位，无跟腱挛缩与足跟内翻，数周内自愈，不需石膏。"},{"name":"神经源性马蹄足（脊髓脊膜膨出、SMA、脑瘫）","point":"伴下肢肌力/感觉异常、脊柱或骶部皮肤异常（包块、皮毛窦、色素斑），畸形僵硬、复发率高；需脊柱超声/MRI 与神经科评估。"},{"name":"先天性垂直距骨","point":"足底呈摇椅底、距骨头在足底可触及，X 线见距骨垂直、跟舟关节脱位；治疗为 Dobbs 反向 Ponseti 法，矫正方向与马蹄内翻足相反。"},{"name":"高弓内翻足（Charcot-Marie-Tooth）","point":"学龄期起病，腓骨肌萎缩、足弓高，感觉正常，家族史阳性，畸形进行性加重；需肌电图与基因检测。"},{"name":"多关节挛缩症（arthrogryposis）","point":"多关节固定畸形、肌容积减少、皮肤光滑，髋膝同时受累，Ponseti 反应差，常需多次手术。"},{"name":"胫骨内旋/股骨前倾所致足内偏","point":"足形态正常，仅行走时足尖内指，被动外旋小腿可矫正，无后足内翻与马蹄；随生长多自行改善。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"10–15 mg/kg 口服 q6h，24 小时 ≤75 mg/kg","note":"石膏塑形后与跟腱切断后疼痛；3 个月以下婴儿慎用","renal":"CrCl <30 延长给药间隔","hepatic":"肝功能不全减量，活动性肝病避免","interact":"长期大剂量与华法林合用可升高 INR"},{"name":"布洛芬","dose":"5–10 mg/kg 口服 q6–8h，24 小时 ≤40 mg/kg，餐后服","note":"跟腱切断后 24–48 小时镇痛；6 个月以下婴儿慎用","renal":"CrCl <30 避免","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、利尿剂合用风险增加"},{"name":"利多卡因（局部麻醉）","dose":"1% 利多卡因 0.3–1 mL 于跟腱两侧局部浸润，总量不超过 4 mg/kg（不加肾上腺素）","note":"经皮跟腱切断多在门诊局麻下完成；注射前回抽，避免注入血管","renal":"无明确调整资料，遵说明书","hepatic":"重度肝功能不全减量（首过代谢下降）","interact":"与其他酰胺类局麻药合用增加全身毒性"},{"name":"头孢唑林（围术期预防）","dose":"30 mg/kg（≤2 g）静脉术前 30–60 分钟，术后 ≤24 小时","note":"仅用于复发再手术、后内侧松解或截骨等开放手术；单纯经皮跟腱切断不需预防用药","renal":"CrCl <30 减量或延长间隔","hepatic":"无需调整","interact":"与华法林合用可增加出血风险"}],"nonDrug":["Ponseti 序贯石膏：生后 1–2 周开始，每周 1 次手法（先纠正高弓，再外展前足纠正内收，然后外旋纠正内翻，最后背屈纠正马蹄），长腿石膏屈膝 90°；一般 5–7 次（多数 5–6 次），最后一次石膏维持 3 周","经皮跟腱切断：约 80%–90% 患儿需切断以纠正马蹄，门诊局麻下完成，术后石膏 3 周再进入支具阶段","支具（足外展矫形器，Denis Browne 支具）：切断后立即佩戴，前 3 个月 23 h/d，之后夜间 12–14 h，维持至 4–5 岁；依从性是复发的最强预测因素","复发处理：<5 岁再次 Ponseti 石膏；动态性前足旋后/内收复发（>3–4 岁）行胫前肌外移；跟腱挛缩行延长；僵硬复发（>5 岁）慎行广泛后内侧松解，必要时截骨或 Ilizarov 外固定","复杂型/综合征型：采用改良 Ponseti（短腿石膏、避免过度外展），小儿骨科与康复科联合管理","随访：<1 岁每 2–3 个月、1–4 岁每 6 个月，评估足跟外翻、背屈度、鞋磨损与步态"],"life":["支具依从性是成败关键：向家长明确每日佩戴时长，复诊时检查支具磨损与皮肤压痕","鞋袜宽松，观察足外侧有无胼胝与皮肤破溃","治疗成功后鼓励正常跑跳与体育活动，无需限制运动","家长学会自查：足跟是否外翻、能否背屈 15°、站立时足外侧是否负重","成年后定期随访踝关节活动度与疼痛，避免长期高跟鞋或长时间站立"]},"prog":"特发性马蹄内翻足 Ponseti 治疗成功率 >90%，复发率 10%–30%（支具依从性差者可达 50%），多在 4–5 岁前发生；约 20%–30% 需一次以上额外手术。长期功能良好，患足略小、踝背屈轻度受限常见，多数可正常运动。","refs":["Ponseti IV. Congenital Clubfoot: Fundamentals of Treatment. Oxford University Press, 1996","《Ilizarov 技术治疗成人僵硬型马蹄内翻足临床诊疗专家共识（2019 版）》（中华骨与关节外科杂志 2019;12(11):841–847）","Dimeglio A, et al. Classification of Clubfoot. J Pediatr Orthop B 1995;4:129–136","《小儿外科学》（第 6 版，人民卫生出版社）先天性马蹄内翻足章"]}]},{"id":"bone_tumor_more","name":"良性骨肿瘤","rank":43,"summary":"良性骨肿瘤的处理核心是「影像定性 + 生长行为监测」：先看病变与母骨的皮质、髓腔是否连续，再看软骨帽厚度与有无骨膜反应、软组织肿块；无症状且稳定的骨软骨瘤观察即可，出现疼痛、增大或软骨帽增厚才需切除并排除恶变。","compare":[],"diseases":[{"id":"or_osteochondroma","name":"骨软骨瘤","aka":["Osteochondroma","Exostosis","外生骨疣","遗传性多发性骨软骨瘤"],"rank":1,"basic":{"define":"骨软骨瘤（外生骨疣）是最常见的良性骨肿瘤，由与母骨皮质、髓腔相连续的骨性突起及其表面覆盖的软骨帽构成。单发性多见；多发性者称遗传性多发性骨软骨瘤（HME）。","risk":["生长期青少年（多在 10–20 岁发现）","男性略多（约 1.5–2:1）","EXT1/EXT2 基因突变（HME，常染色体显性遗传）","既往局部放疗史（继发性骨软骨瘤）","多发性、骨盆或肩胛骨病变（恶变风险更高）"],"epi":"占良性骨肿瘤的 20%–50%，是最常见的良性骨肿瘤；多在 10–30 岁因无痛性包块或体检发现，男性略多。HME 发病率约 1/50,000。"},"patho":"起源于骺板软骨的错位或骨膜下生长，随骨骼生长向外突出；软骨帽通过软骨内成骨形成蒂部松质骨，并与母骨髓腔相通，这是影像诊断的基础。软骨帽厚度随年龄递减（儿童可达 2–3 cm，成人通常 <1 cm）。成年后软骨帽继续增厚、出现疼痛与生长，提示恶变为继发性软骨肉瘤（多为低级别）。","dx":{"criteria":["无痛性骨性包块，表面光滑、与骨固定、不可推动，多见于股骨远端与胫骨近端（膝关节周围约占 40%–50%）。","疼痛提示并发症：机械摩擦/滑囊炎、蒂部骨折、神经或血管压迫、恶变。","X 线：骨性突起，皮质与髓腔与母骨连续（诊断性特征）；分蒂型（背离关节生长）与广基底型；软骨帽不显影或见点状钙化。","MRI（T2/增强）：测量软骨帽厚度——成人 >1.5 cm、儿童 >2 cm，或随访年增厚 >2 mm 提示恶变可能；同时评估软组织受压与髓腔连续性。","生长行为：与骨骼同步生长；骨骼成熟后病变继续增大是恶变最重要的警示。","CT：复杂部位（骨盆、肩胛骨、脊柱）评估蒂部与母骨关系、椎管内受压与蒂部骨折。","多发性（HME）：膝、肩、踝、骨盆多处病变，常伴身材矮小、肢体不等长、前臂/小腿弯曲（Madelung 畸形）；终身恶变风险约 1%–5%。","实验室无特异性指标；碱性磷酸酶正常（恶变或骨折时可轻度升高）；活检仅在疑恶变时进行（表浅活检易误判为低级别软骨肉瘤）。"],"workup":["X 线正侧位（含邻近关节全长），确认皮质与髓腔连续性、蒂型与广基底型","MRI（T1/T2/增强）：测量软骨帽厚度、评估软骨帽分叶与软组织侵犯，是疑恶变的首选","CT：骨盆、肩胛骨、脊柱等复杂部位，评估与母骨关系及椎管占位","全身骨扫描或全身 MRI（低剂量方案）：多发性病变评估分布与活动性","遗传咨询与 EXT1/EXT2 基因检测（HME 家系）","活检：仅对疑恶变者，由骨肿瘤中心行穿刺或切开活检，避免表浅取材"],"grading":"① 形态：蒂型（pedunculated）与广基底型（sessile）；② 数目：单发性与多发性（HME）；③ 软骨帽厚度用于恶变风险分层（成人 >1.5 cm 为警戒线）；④ 继发恶变为软骨肉瘤（多为Ⅰ–Ⅱ级，按 Enneking 分期）。"},"ddx":[{"name":"骨巨细胞瘤（or_giant_cell_tumor）","point":"最易混淆的邻类良性骨肿瘤：位于骨骺、偏心性溶骨破坏、无软骨帽、无皮质与髓腔连续，MRI 可见液-液平面；骨软骨瘤位于干骺端、为骨性突起且皮质髓腔与母骨相通。"},{"name":"骨肉瘤（or_bone_tumor）","point":"疼痛进行性加重、夜间痛，X 线见骨质破坏、骨膜反应（Codman 三角、日光放射），碱性磷酸酶升高，髓腔不连续；骨软骨瘤多无症状、皮质与髓腔连续。"},{"name":"骨旁骨肉瘤","point":"附着于股骨远端后侧皮质表面，X 线见线样透亮间隙（string sign）分隔肿瘤与皮质，髓腔不连续，CT/MRI 见软组织成分；骨软骨瘤与母骨髓腔相通。"},{"name":"继发性软骨肉瘤（恶变）","point":"原有骨软骨瘤处出现疼痛、包块增大，软骨帽 >1.5–2 cm 且厚度进行性增加，MRI 见软骨帽分叶、周围水肿或软组织侵犯；需广泛切除。"},{"name":"骨化性肌炎","point":"明确外伤史，2–6 周内快速增大伴疼痛，X 线见层状/蛋壳样骨化、与骨皮质不连续，MRI 见周边水肿；随访可缩小。"},{"name":"骨瘤/骨岛","point":"致密骨性结节，无软骨帽，位于颅面骨或骨内，X 线见均匀高密度、无蒂部与软骨帽。"},{"name":"滑膜软骨瘤病","point":"关节内多发钙化结节伴关节积液，X 线见关节周围多发钙化、与骨无连续；关节镜可确诊并治疗。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"0.5–1 g 口服 q6h，24 小时 ≤3 g；儿童 10–15 mg/kg q6h","note":"包块受压或术后镇痛；合并复方感冒药时需累计总量","renal":"CrCl <30 延长给药间隔至 q8h","hepatic":"肝硬化/活动性肝病减至 ≤2 g/d 或避免","interact":"长期大剂量与华法林合用可升高 INR"},{"name":"塞来昔布","dose":"200 mg 口服 qd–q12h，短期（≤7 天）","note":"用于滑囊炎或术后急性疼痛；有心血管病史者慎用","renal":"CrCl <30 避免使用","hepatic":"重度肝功能不全禁用","interact":"与抗凝药、ACEI/ARB、利尿剂合用风险增加"},{"name":"罗哌卡因（局部浸润）","dose":"0.25% 罗哌卡因 10–20 mL 切口与骨膜浸润，总量不超过 3 mg/kg","note":"切除术后局部镇痛，减少阿片用量；注射前回抽避免血管内注射","renal":"无明确调整资料，遵说明书","hepatic":"重度肝功能不全减量（主要经肝代谢）","interact":"与其他酰胺类局麻药合用增加全身毒性"},{"name":"头孢唑林（围术期预防）","dose":"1–2 g 静脉术前 30–60 分钟（体重 >80 kg 用 2 g），术后 ≤24 小时","note":"肿瘤切除手术预防用药；青霉素速发型过敏改用克林霉素","renal":"CrCl <30 术后减量或延长间隔","hepatic":"无需调整","interact":"与华法林合用可增加出血风险"}],"nonDrug":["观察：无症状、无生长、无压迫者每 6–12 个月复查 X 线至骨骼成熟，之后每 1–2 年或出现症状时复查","手术指征：疼痛或机械症状、关节活动受限、神经血管压迫、蒂部骨折、影响生长或造成畸形（前臂/小腿弯曲、肢体不等长）、骨骼成熟后继续增大、软骨帽 >1.5–2 cm 疑恶变、外观要求","术式：边缘切除——连同软骨帽与骨膜完整切除至正常骨，残留软骨帽是复发主因；骨盆/肩胛骨等深部病变行基底广泛切除；脊柱病变压迫脊髓者行椎板切除 + 病变切除","禁忌：不做病变内刮除；疑恶变者不做简单边缘切除，应转骨肿瘤中心行广泛切除 + 活检","多发性（HME）：仅处理有症状或疑恶变者，不做预防性切除；每年临床评估，出现疼痛或增大时行 MRI"],"life":["避免局部反复撞击与摩擦，运动时使用护具（膝、踝周围病变）","每月自测包块大小并记录，发现短期明显增大及时就诊","骨骼成熟后仍需长期随访（恶变可发生于成年后）","HME 家系行遗传咨询与 EXT1/EXT2 检测，子女儿童期筛查","出现夜间痛、静息痛或包块快速增大，立即复查 MRI 排除恶变"]},"prog":"单发性骨软骨瘤预后极好，恶变率 <1%；HME 终身恶变风险约 1%–5%（骨盆、肩胛骨病变更高）。儿童期切除后复发率 2%–5%（多因软骨帽残留）。继发软骨肉瘤多为低级别，广泛切除后 5 年生存率 >80%。","refs":["WHO Classification of Tumours: Soft Tissue and Bone Tumours, 5th ed. (2020)","《原发性软骨肉瘤临床诊疗专家共识（2026 年版）》","《骨肉瘤诊疗指南（2025 年版）》","《外科学》第 9 版（人民卫生出版社）骨肿瘤章"]}]}]},"peds":{"categories":[{"id":"ped_infect","name":"感染与发热","rank":1,"summary":"儿童发热按年龄分层：<3 个月一律视为危重信号，需完整评估与经验抗感染；较大儿童以「是否存在脓毒症/重症肺炎/脑膜炎」为判断轴。用药以体重或体表面积计算，退热首选对乙酰氨基酚或布洛芬单药，不交替、不联用。","compare":[{"diseaseId":"ped_fever","dx":"腋温 ≥37.3 ℃（或肛温 ≥38 ℃）即发热；<6 个月发热必须就医，评估隐匿性菌血症与尿路感染风险","key":"以体温升高为唯一或主要表现，缺乏定位体征，需结合年龄与危险信号判断"},{"diseaseId":"ped_pneumonia","dx":"发热 + 咳嗽/呼吸增快 + 肺部啰音或呼吸音减低，胸片见斑片状浸润影；呼吸增快为最关键床边指标","key":"有呼吸急促、三凹征、肺部固定湿啰音等呼吸系统定位体征"},{"diseaseId":"ped_hfmd","dx":"发热伴口腔疱疹/溃疡、手掌足底臀部斑丘疹或疱疹，柯萨奇 A16 或 EV71 型感染","key":"手足口三部皮疹 + 口腔疱疹，诊断高度依赖皮疹分布"}],"diseases":[{"id":"ped_fever","name":"儿童发热","aka":["Fever in Children","发热待查"],"rank":1,"basic":{"define":"儿童体温升高超过正常范围：腋温 ≥37.3 ℃、口温 ≥37.8 ℃、肛温 ≥38.0 ℃。按病程分为急性发热（<7 d，多为感染）与不明原因发热（FUO，≥7–14 d 未明确）。发热本身是免疫反应，不是疾病的严重程度指标，评估重点是「有无严重细菌感染或危重症」。","risk":["年龄 <3 个月（尤其是 <28 天新生儿）发热，严重细菌感染风险高","未接种或接种不全（尤其肺炎链球菌、流感嗜血杆菌、脑膜炎球菌疫苗）","免疫缺陷、肾病综合征、脾切除、长期激素或免疫抑制剂使用","中心静脉导管、脑室分流、近期手术或明确感染灶（中耳炎、腹腔）","营养不良、贫血、先天性心脏病"],"epi":"儿童急性发热多由病毒性呼吸道感染或胃肠炎引起，约 80%–90% 为自限性。3–36 个月发热儿童中隐匿性菌血症发生率已降至 1%–2%（疫苗普及后），<3 个月婴儿严重细菌感染占 8%–12%。"},"patho":"病原体或致热原激活单核-巨噬细胞释放 IL-1、IL-6、TNF-α 等内源性致热原，作用于下丘脑体温调节中枢，通过前列腺素 E2 合成使体温调定点上移，引起产热增加、散热减少。高热可增加心率和代谢率（每升高 1 ℃ 心率约增 10 次/分），婴幼儿易因发热引起惊厥（6 个月–5 岁，约 2%–5%）。","dx":{"criteria":["腋温 ≥37.3 ℃ 或肛温 ≥38.0 ℃，结合测量方式与测量时间","<3 个月婴儿发热（≥38 ℃ 肛温）视为急症，需血培养、尿培养、腰穿（<28 d 或一般情况差者）并经验性抗生素","3–6 个月发热：CRP/降钙素原、尿常规（导尿或清洁中段尿）、血培养，高危者住院观察","危险信号（红灯征）：嗜睡/难以唤醒、皮肤苍白或发绀、毛细血管再充盈 >3 s、呼吸急促、脱水、皮疹压之不褪色、颈部强直、抽搐、3–6 个月体温 ≥39 ℃","耶鲁观察量表或 NICE 交通灯分级可用于分层（绿/黄/红）"],"workup":["完整生命体征与系统查体（咽部、鼓膜、肺部、腹部、皮肤、颈抵抗、原始反射）","血常规+CRP；必要时降钙素原（PCT >0.5 ng/mL 提示细菌感染可能）","尿常规与尿培养（3–24 个月无法定位发热者必须查）","血培养（<3 个月、疑脓毒症、免疫缺陷者）","胸片（有呼吸道症状或呼吸增快者）、腹部超声（疑腹腔感染）","腰穿：<28 天一律做；1–3 个月一般情况差或血象提示细菌感染；拒做需经验性覆盖脑膜炎"],"grading":"NICE 交通灯分级：绿色（一般情况好、皮肤正常、呼吸正常、无脱水、无危险信号）可居家观察；黄色（苍白、进食减少、心率呼吸增快、3–6 个月 ≥39 ℃）需评估与随访；红色（面色苍白/发绀、嗜睡、呼吸窘迫、脱水、抽搐、颈强直）需急诊处理。"},"ddx":[{"name":"儿童肺炎（ped_pneumonia）","point":"与本类 ped_pneumonia 的鉴别点：肺炎有呼吸增快、三凹征、肺部湿啰音或呼吸音减低，胸片见浸润影；单纯发热可无呼吸系统体征。"},{"name":"手足口病（ped_hfmd）","point":"与本类 ped_hfmd 的鉴别点：手足口病有典型口腔疱疹与手足臀部皮疹，多有接触史；发热本身不伴特征性皮疹。"},{"name":"病毒性上呼吸道感染、幼儿急疹","point":"幼儿急疹表现为热退后出疹（<2 岁），一般情况好；上感有流涕、咽红等表现，为自限性。"},{"name":"尿路感染","point":"发热可为唯一表现（尤其 <2 岁），尿常规白细胞增多、亚硝酸盐阳性，尿培养阳性；需导尿或清洁中段尿。"},{"name":"中耳炎、化脓性脑膜炎、关节炎、骨髓炎、川崎病","point":"需查体定位：鼓膜充血膨隆；脑膜刺激征与颈抵抗；关节红肿热痛；川崎病发热 ≥5 d 伴结膜充血、草莓舌、手足硬肿、皮疹与颈淋巴结肿大。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"口服每次 10–15 mg/kg，q4–6h，24 h 不超过 4 次，每日最大剂量 75 mg/kg（不超过 4 g/d）；3 个月以下婴儿需医生评估后使用","note":"WHO 与国内指南均作为首选退热药；不推荐用于无不适感的常规预防性退热","renal":"肾功能不全延长给药间隔","hepatic":"肝功能不全减量，最大 2 g/d 或更保守；避免与其他含对乙酰氨基酚复方制剂叠加致肝损","interact":"与酶诱导剂（卡马西平、苯巴比妥）合用增加肝毒性；避免与含相同成分复方药合用"},{"name":"布洛芬","dose":"口服每次 5–10 mg/kg，q6–8h，24 h 不超过 4 次，每日最大剂量 40 mg/kg；6 个月及以上适用","note":"退热效果与对乙酰氨基酚相当，持续时间略长；不推荐与对乙酰氨基酚交替或联合使用（增加用药错误与肾损伤风险）","renal":"脱水、肾功能不全、肾病综合征时禁用或慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、氨基糖苷类合用增加出血与肾毒性；与 ACEI/ARB 合用降低肾血流"},{"name":"头孢曲松（经验性抗感染）","dose":"50–75 mg/kg/d 静脉滴注 qd（最大 2 g/d）；疑细菌性脑膜炎时 100 mg/kg/d 分 1–2 次（最大 4 g/d）","note":"用于 <3 个月发热、可疑脓毒症、重症肺炎等经验性治疗；<3 个月常联合氨苄西林覆盖李斯特菌","renal":"肾功能不全无需调整，但需监测；禁与含钙溶液同用（新生儿）","hepatic":"严重肝功能不全可减量","interact":"禁与含钙输液经同一通路（新生儿可形成沉淀）；与氨基糖苷类分开给药"},{"name":"阿莫西林","dose":"口服 20–40 mg/kg/d 分 2–3 次（最大 1.5–2 g/d），用于疑似细菌性上呼吸道感染或 <5 岁肺炎轻症经验治疗","note":"WHO 儿童肺炎经验治疗为阿莫西林（5 d 疗程），疗效与静脉方案相近","renal":"eGFR <30 延长给药间隔","hepatic":"肝功能不全慎用","interact":"与别嘌醇合用增加皮疹；丙磺舒延长清除"},{"name":"奥司他韦","dose":"治疗：≤15 kg 30 mg bid，>15–23 kg 45 mg bid，>23–40 kg 60 mg bid，>40 kg 75 mg bid；共 5 d","note":"流感流行季节、有流感样症状且高危儿童（<2 岁、哮喘、免疫缺陷）在发病 48 h 内使用；不用于普通感冒","renal":"eGFR 30–60 减量至隔日 1 次；<30 或透析按说明书调整","hepatic":"严重肝功能不全慎用","interact":"与减毒活疫苗合用需间隔；与丙磺舒合用增加血药浓度"},{"name":"静脉补液（发热脱水）","dose":"口服补液盐（ORS III）为首选，按 50–100 mL/kg（4 h 内）少量多次；不能口服者静脉 0.9% 生理盐水 20 mL/kg 于 20–30 min 快速扩容，必要时重复（每次 20 mL/kg，1 h 内累计不超过 3 次）","note":"发热伴呕吐、进食差需评估脱水程度（轻/中/重度），脱水婴儿尽量避免含糖饮料","renal":"少尿或疑肾衰竭时按尿量限制","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["3 个月以下发热婴儿一律就医、完善评估并住院观察，必要时经验性抗感染","3–6 个月发热 ≥39 ℃ 且一般情况差者住院；一般情况好者可门诊随访 24–48 h","物理降温：温水擦浴可短期改善舒适度，但不推荐常规使用；禁酒精擦浴（致中毒）","退热目标是缓解不适而非降至正常，发热本身无需治疗到体温正常","家长教育与预警症状告知（抽搐、嗜睡、皮疹、呼吸困难、少尿、拒食）","退热药间隔至少 4–6 h，不同药物交替需记录时间与剂量，避免过量"],"life":["多饮水、清淡饮食，母乳喂养婴儿增加哺乳次数","退热后 24–48 h 观察精神、进食与尿量","体温测量标准化：电子腋温或肛温，避免额温枪的误差","预防：疫苗接种、勤洗手、避免接触呼吸道感染者","家长培训：掌握危险信号与退热药剂量计算"]},"prog":"绝大多数儿童发热为病毒性感染，3–5 d 内自限，预后良好。严重细菌感染（脓毒症、脑膜炎）是发热最主要的危险；早期识别危险信号、及时评估可将不良后果显著降低。幼儿急疹等热退后出疹为良性过程。","refs":["中华医学会儿科学分会. 儿童发热诊治专家共识（2021）","NICE. Fever in under 5s: assessment and initial management (NG143, 2021 update)","WHO. Pocket book of hospital care for children (2013, 2nd ed.)","AAP. Fever and your child (2022)"]},{"id":"ped_pneumonia","name":"儿童肺炎","aka":["Pediatric Pneumonia","肺炎"],"rank":2,"basic":{"define":"肺实质的感染性炎症，常见病原为肺炎链球菌、流感嗜血杆菌、呼吸道合胞病毒（RSV）、肺炎支原体等；<5 岁儿童以下呼吸道感染为主，重症可致呼吸衰竭与脓毒症。","risk":["年龄 <5 岁（尤其 <1 岁）、早产儿低出生体重","未接种肺炎球菌结合疫苗（PCV）、流感疫苗","营养不良、维生素 A 缺乏、缺铁性贫血","被动吸烟、室内空气污染、近亲托幼呼吸道病原交叉","先天性心脏病、免疫缺陷、囊性纤维化、神经肌肉病（误吸风险）"],"epi":"全球每年约 7 亿例儿童肺炎，是 <5 岁儿童死亡的首要感染性原因（占儿童死亡的 14%–15%）。我国 <5 岁儿童肺炎发病率约 7%–10%/年，婴幼儿住院肺炎以 RSV 与肺炎链球菌为主，学龄期以肺炎支原体为主。"},"patho":"病原经呼吸道吸入或血行播散，在肺泡引起渗出性炎症（宏观呈实变影）。肺泡毛细血管充血、肺泡内渗出液与炎性细胞积聚阻碍气体交换，导致低氧血症；炎症介质系统释放引起发热与全身反应。婴幼儿因气道纤细、分泌物清除能力差，易发生痰栓与肺不张；RSV 感染常累及细支气管，出现喘息与呼吸窘迫。","dx":{"criteria":["有发热、咳嗽、呼吸增快、三凹征、鼻翼扇动、发绀","呼吸增快标准（WHO）：<60 次/分（<2 个月）、≥50 次/分（2–12 个月）、≥40 次/分（1–5 岁）","肺部固定细湿啰音或呼吸音减低；婴幼儿有时仅有呼吸急促与三凹征","胸片：肺段或肺叶实变、斑片状浸润影、支气管充气征；单侧胸腔积液提示重症","重症肺炎：SpO₂ <92%（室内空气）、发绀、三凹征明显、嗜睡/激惹、拒食、脱水、持续高热、休克或肺外并发症"],"workup":["生命体征、呼吸频率与 SpO₂（脉搏血氧监测）","胸片（住院或疑并发症者），不需常规复查；肺超声可选","血常规、CRP、PCT（区分病毒与细菌不敏感但有助于重症评估）","鼻咽拭子呼吸道病原核酸（RSV、流感、腺病毒、肺炎支原体、肺炎链球菌）","血培养（住院重症、脓毒症、<3 个月发热）","胸腔超声/穿刺（疑胸腔积液或脓胸）；厌氧或特殊病例可考虑支气管镜","评估水电平衡与营养状况"],"grading":"按严重程度：轻症（能门诊治疗、无低氧、能进食）与重症（需要住院、低氧、呼吸窘迫、全身中毒症状）；WHO 分为无肺炎、肺炎、重症肺炎；也可用 BTS/CURB 儿童住院标准（年龄、SpO₂、进食与呼吸做功）。"},"ddx":[{"name":"手足口病（ped_hfmd）","point":"与本类 ped_hfmd 的鉴别点：手足口病以口腔疱疹与手足皮疹为主，肺部体征多无，重症才会出现呼吸增快；肺炎无特征性皮疹。"},{"name":"儿童发热（ped_fever）","point":"与本类 ped_fever 的鉴别点：无法定位的发热缺乏肺部啰音与呼吸增快；肺炎依靠呼吸系统体征与胸片定位。"},{"name":"毛细支气管炎（ped_bronchiolitis）","point":"多见于 <2 岁婴儿，以喘息、呼气相延长、三凹征为主，胸片见过度充气，病原多为 RSV；与肺炎鉴别需结合呼吸音与影像。"},{"name":"支气管哮喘急性发作/异物吸入","point":"哮喘有反复喘息史、支气管舒张剂有效；异物吸入常有呛咳史、单侧呼吸音减低，胸片透光度不均，必要时支气管镜。"},{"name":"肺结核、支气管扩张、囊性纤维化","point":"病程长、反复或迁延不愈，需查结核菌素/IGRA、胸部 CT、汗液氯化物等；急性肺炎经规范治疗 48–72 h 应好转。"}],"tx":{"drug":[{"name":"阿莫西林","dose":"口服 80–90 mg/kg/d 分 2 次（最大 3–4 g/d），疗程 5–7 d；轻症门诊首选","note":"WHO 与 BTS 均推荐阿莫西林为 <5 岁门诊肺炎一线；体重 <10 kg 时 80 mg/kg/d","renal":"eGFR <30 延长间隔","hepatic":"肝功能不全慎用","interact":"与别嘌醇合用增加皮疹；丙磺舒延长清除"},{"name":"阿莫西林克拉维酸钾","dose":"按阿莫西林 45–90 mg/kg/d 分 2–3 次口服；静脉 25–30 mg/kg q6–8h","note":"用于疑产 β-内酰胺酶病原、治疗 48–72 h 无效或中耳炎并发者","renal":"eGFR <30 延长间隔","hepatic":"胆汁淤积性肝炎风险，疗程 >2 周时监测肝功能","interact":"与别嘌醇增加皮疹；与华法林合用增加 INR"},{"name":"头孢呋辛（静脉）","dose":"静脉 50–75 mg/kg/d 分 3 次（最大 4.5 g/d）；口服头孢呋辛酯 20–30 mg/kg/d 分 2 次","note":"阿莫西林无效或过敏（非速发型）时替代","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"与丙磺舒延长清除；避免与大剂量氨基糖苷类联用"},{"name":"头孢曲松（住院/重症）","dose":"50–80 mg/kg/d 静脉滴注 qd（最大 4 g/d）；疑并脓胸或脓毒症不减量","note":"重症肺炎或不能口服者；疗程 7–10 d，脓肿/并发症延长至 2–3 周","renal":"无需调整，注意胆泥淤积","hepatic":"严重肝功能不全可减量","interact":"新生儿禁与含钙输液同通路；高胆红素血症者慎用"},{"name":"阿奇霉素（疑支原体）","dose":"口服 10 mg/kg（最大 500 mg）qd ×3 d，或第 1 天 10 mg/kg 后第 2–5 天 5 mg/kg qd；静脉 10 mg/kg qd","note":"学龄期肺炎、大环内酯类流行株地区经验治疗；注意大环内酯耐药（我国支原体耐药率高）","renal":"eGFR <30 慎用","hepatic":"肝功能不全慎用","interact":"与 QT 延长药物（胺碘酮、西沙必利）合用增加心律失常；避免与铝/镁抗酸剂同服"},{"name":"克拉霉素","dose":"15 mg/kg/d 分 2 次（最大 1 g/d），疗程 7–10 d","note":"阿奇霉素耐药或疗效差时替代；可与阿莫西林联合用于非典型病原","renal":"eGFR <30 减量","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂，与华法林、他汀、秋水仙碱合用增加毒性"},{"name":"氧疗","dose":"SpO₂ <92%（室内空气）时，鼻导管 0.5–2 L/min 或面罩；目标 SpO₂ ≥92%（有基础肺病或贫血者 ≥94%）","note":"低氧血症是重症的关键指标，及时给氧可改善预后","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"对乙酰氨基酚/布洛芬（退热）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h（每日 ≤75 mg/kg）；布洛芬 5–10 mg/kg q6–8h（6 个月以上，每日 ≤40 mg/kg）","note":"仅用于缓解发热不适；退热不改变肺炎病程","renal":"布洛芬在脱水或肾功能不全者慎用","hepatic":"肝功能不全时对乙酰氨基酚减量","interact":"避免与含相同成分复方药同用"}],"nonDrug":["轻症可门诊口服抗生素治疗，24–48 h 复诊评估（呼吸频率、SpO₂、进食、精神）","住院指征：SpO₂ <92%、呼吸窘迫、无法口服、年龄 <3 个月、脓毒症、胸腔积液或并发症","胸腔积液/脓胸：超声定位后穿刺引流，必要时胸腔闭式引流+全身抗生素","呼吸衰竭：高流量鼻导管氧疗（HFNC）或 CPAP，无效时机械通气","氧合与液体管理：监测尿量与电解质，避免过量补液致肺水肿"],"life":["按国家免疫规划接种 PCV13、Hib、流感疫苗与百日咳疫苗","家庭环境通风、避免被动吸烟、母乳喂养 ≥6 个月","治疗后随访：咳嗽可持续 2–4 周，复诊评估是否需复查胸片","营养支持与维生素 A 补充（贫困/营养不良地区）","家长教育：呼吸增快、拒食、发绀、嗜睡等需立即就诊"]},"prog":"多数经规范抗生素治疗 48–72 h 退热改善，预后良好。重症肺炎（低氧血症、脓胸、脑膜炎等并发症）病死率明显升高；<5 岁儿童肺炎是主要可预防死亡原因，疫苗与营养干预显著降低死亡率。","refs":["中华医学会儿科学分会呼吸学组. 儿童社区获得性肺炎诊疗规范（2019 版）","WHO. Revised WHO classification and treatment of childhood pneumonia at health facilities (2014)","BTS Guidelines for the Management of Community Acquired Pneumonia in Children (2011, updated 2023)","PIDS/IDSA. The Management of Community-Acquired Pneumonia in Infants and Children Older Than 3 Months (2011)"]},{"id":"ped_hfmd","name":"手足口病","aka":["HFMD","Hand-Foot-Mouth Disease","肠道病毒感染"],"rank":3,"basic":{"define":"由肠道病毒（柯萨奇 A 组 16 型最常见，肠道病毒 71 型 EV71 重症多）引起的急性传染病，主要发生于 <5 岁儿童，表现为发热、口腔疱疹与手足臀等部位皮疹，少数可并发脑干脑炎、神经源性肺水肿而致死。","risk":["年龄 <5 岁，尤其 1–3 岁（托幼机构聚集）","EV71 感染（重症比例高，脑干脑炎与肺出血风险）","与患儿密切接触、共用玩具与餐具","夏秋季高发（4–7 月为发病高峰）","免疫缺陷、营养不良、既往重症史"],"epi":"我国自 2008 年将手足口病纳入丙类法定报告传染病，年报告病例约 200 万例以上，重症病例约占 0.2%–0.5%，死亡以 EV71 感染为主。主要发生于 6 月龄—5 岁儿童，聚集于托幼机构。"},"patho":"病毒经消化道、呼吸道飞沫与接触传播，先在上呼吸道与肠道黏膜复制，继而经血行播散至皮肤黏膜（形成疱疹）。EV71 可侵入中枢神经系统，引起脑干脑炎、无菌性脑膜炎等；脑干炎症使交感神经过度兴奋，导致体循环血管收缩、大量血液转移至肺循环，出现神经源性肺水肿与肺出血，是主要死因。重症多在发病 2–5 d 内迅速进展。","dx":{"criteria":["发热（多为低至中度，38–39 ℃）伴咽痛、拒食、流涎","口腔黏膜（咽峡、软腭、舌、颊黏膜）散在疱疹或溃疡","手掌、足底、臀部（有时膝、肘）斑丘疹或疱疹，疱内液体少，疱疹不痛不痒","流行病学：发病前 7–10 d 有接触史或托幼机构聚集发病","实验室：鼻咽拭子/疱疹液/粪便肠道病毒核酸检测阳性（EV71 阳性者警惕重症）","重症预警：持续高热 3 d 不退、精神差/嗜睡/易惊、肢体抖动/肌阵挛、呼吸心率增快、出冷汗、高血压或低血压、外周血白细胞 >15×10⁹/L"],"workup":["体温与精神状态、呼吸频率、心率评估","口腔与手、足、臀部皮疹查体（记录分布）","血常规（白细胞显著升高提示重症）、血糖（>8.3 mmol/L 提示神经源性应激）、CRP","肠道病毒核酸（咽拭子/粪便），必要时脑脊液与胸片","重症：心肌酶、胸片（肺水肿）、头颅 MRI（脑干）、脑电图、血糖与乳酸监测","体检心率和血压，警惕神经源性肺水肿"],"grading":"临床分型：普通型（手、足、口、臀皮疹+发热，可自限）；重症重型（神经系统受累：脑膜炎、脑炎、脑干脑炎、急性弛缓性麻痹）；危重型（心肺功能衰竭前期或衰竭期：神经源性肺水肿、肺出血、休克）。"},"ddx":[{"name":"儿童肺炎（ped_pneumonia）","point":"与本类 ped_pneumonia 的鉴别点：肺炎以呼吸增快、肺部啰音与胸片浸润影为主，缺乏口腔与手足皮疹；手足口病皮疹分布特征明确。"},{"name":"儿童发热（ped_fever）","point":"与本类 ped_fever 的鉴别点：手足口病有典型三部皮疹与口腔疱疹，诊断有特异性；单纯发热缺乏皮疹定位。"},{"name":"疱疹性咽峡炎","point":"同属肠道病毒，但仅咽峡部疱疹，无手足皮疹，全身症状轻，多不需住院，需与手足口病区分隔离管理。"},{"name":"水痘","point":"皮疹呈向心性分布（躯干为主），分批出现丘疹、水疱、结痂三期同时存在，伴瘙痒，与水痘-带状疱疹病毒相关。"},{"name":"疱疹性口炎、药疹、多形红斑","point":"口炎为单纯疱疹病毒所致，仅口腔黏膜疱疹；药疹有用药史、皮疹弥漫，缺乏口腔疱疹与手足分布。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"10–15 mg/kg 口服 q4–6h，每日 ≤75 mg/kg（最大 4 g/d）；用于退热与缓解口痛","note":"普通型对症即可，退热不以降至正常为目标","renal":"肾功能不全延长间隔","hepatic":"肝功能不全减量；避免与含对乙酰氨基酚复方药叠加","interact":"与酶诱导剂合用增加肝毒性"},{"name":"布洛芬","dose":"5–10 mg/kg 口服 q6–8h，每日 ≤40 mg/kg，6 个月以上","note":"退热与缓解疼痛；避免与对乙酰氨基酚交替","renal":"脱水时慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药合用增加出血"},{"name":"α 干扰素（喷雾/雾化）","dose":"α2b 干扰素 20 万–40 万 IU 雾化吸入，2 次/日，疗程 3–5 d（国内方案）","note":"抗病毒辅助治疗，证据等级有限；不应替代重症的对症与支持","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"利巴韦林（重症/酌情）","dose":"10–15 mg/kg/d 分 2 次静脉滴注，疗程 3–5 d；国内部分方案用于重症，循证证据不足","note":"有致畸性，育龄女性禁用；贫血与长期使用需监测血象","renal":"肾功能不全减量","hepatic":"严重肝功能不全禁用","interact":"与齐多夫定合用增加贫血"},{"name":"免疫球蛋白（IVIG）","dose":"重症/危重型：1 g/kg/d 静脉滴注 ×2 d，可重复；总量一般不超过 2 g/kg（按临床评估）","note":"用于中和病毒与免疫调节；需监测心功能与容量负荷","renal":"肾功能不全慎用，注意容量负荷","hepatic":"遵说明书","interact":"与减毒活疫苗需间隔 3 个月以上"},{"name":"甲泼尼龙（重症）","dose":"1–2 mg/kg/d 分次静脉，疗程 3–5 d，之后按病情减停；仅用于重症中枢神经系统受累","note":"休克或明显颅内高压时可短程大剂量（按急诊方案），需与甘露醇等降颅压联合，避免长期使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与非甾体抗炎药合用增加消化道溃疡；与利尿剂合用增加低钾"},{"name":"甘露醇（降颅压）","dose":"0.5–1 g/kg 静脉快速滴注（30 min 内）q6–8h，按颅压情况调整","note":"用于重症脑干脑炎伴颅高压；需监测血渗透压与尿量","renal":"无尿或严重心功能不全禁用","hepatic":"遵说明书","interact":"与其他肾毒性药物联用需谨慎"},{"name":"米力农/多巴胺（心肺衰竭期）","dose":"米力农 0.375–0.75 µg/kg/min 静脉泵入；多巴胺 5–10 µg/kg/min 按血压调整；同时限制液体入量","note":"用于神经源性肺水肿/心功能衰竭期，需重症监护条件","renal":"按肾功能调整用量","hepatic":"遵说明书","interact":"米力农与儿茶酚胺合用增加心律失常风险"}],"nonDrug":["普通型居家隔离：隔离至症状消失后 1 周（不少于发病后 2 周），避免去幼儿园与公共场所","口腔护理：生理盐水漱口或温凉流质饮食，减少口痛拒食","重症监护：重型/危重型立即转至有儿科重症救治能力医院，监测呼吸、血压、血糖与神经系统体征","神经源性肺水肿：限制液体、利尿、正压通气，必要时机械通气","必要时腰椎穿刺（疑脑膜炎）与脑电图、头颅 MRI","疫苗：EV71 灭活疫苗（6 月龄–5 岁），可降低 EV71 相关重症与死亡"],"life":["勤洗手（尤其处理患儿粪便与分泌物后）、玩具与餐具清洗消毒","患儿餐具、毛巾专用，托幼机构晨检与隔离","流行季节少去人群密集场所；室内通风","预后随访：重症存活者需 3–6 个月神经发育与运动评估","家长教育：出现持续高热、嗜睡、肢体抖动、呼吸急促应立即就医"]},"prog":"普通型 5–7 d 自限，预后良好；重型约 0.2%–0.5%，及时识别与干预可降低死亡率；EV71 脑干脑炎相关危重型病死率约 0.3%–0.5%（及时救治可进一步降低），存活者约 10%–20% 遗留神经系统后遗症（肢体瘫痪、吞咽困难等）。","refs":["国家卫生健康委员会. 手足口病诊疗指南（2018 年版）","中华医学会儿科学分会. 手足口病临床诊疗专家共识（2017）","WHO. A guide to clinical management and public health response for hand, foot and mouth disease (HFMD), 2011","国家免疫规划：EV71 灭活疫苗使用技术指南（2016）"]}]},{"id":"ped_gi","name":"消化与补液","rank":2,"summary":"儿童腹泻以口服补液盐（ORS）与补锌为核心，抗生素仅用于细菌性痢疾等特定指征；肠套叠以「阵发性哭闹+果酱样便+腹部腊肠样包块」三联征为线索，超声「靶环征」确诊，空气/钡灌肠复位为首选。","compare":[{"diseaseId":"ped_diarrhea","dx":"每日排便 ≥3 次，稀便或水样便，伴或不伴呕吐、发热；评估脱水程度（轻/中/重度）","key":"以排稀便频次增多为主，脱水程度决定补液途径"},{"diseaseId":"ped_intuss","dx":"6 个月—2 岁婴儿阵发性哭闹（蜷缩、踢腿）、呕吐、果酱样血便，腹部可触及腊肠样包块，超声见「靶环征」","key":"阵发性腹痛+呕吐+果酱样便三联征，超声靶环征"}],"diseases":[{"id":"ped_diarrhea","name":"儿童腹泻与口服补液","aka":["Acute Diarrhea","小儿腹泻病","急性胃肠炎"],"rank":1,"basic":{"define":"儿童每日排便次数增多（≥3 次）伴大便性状改变（稀便、水样便或黏液脓血便），病程 <14 d 为急性腹泻。主要病原为轮状病毒、诺如病毒、致病性大肠埃希菌与沙门菌。按脱水程度分为轻、中、重度，脱水的识别与补液是死亡风险的关键。","risk":["年龄 6 个月—2 岁（轮状病毒易感）、早产儿","未接种轮状病毒疫苗","卫生条件差、不安全饮用水、营养不良","近期使用抗生素（艰难梭菌）、免疫缺陷","托幼机构聚集性暴发"],"epi":"全球 <5 岁儿童每年约 17 亿例腹泻，约 50 万例死亡（多为可预防的脱水与营养不良）。我国 5 岁以下儿童腹泻发病率约 0.8–1.0 次/年，轮状病毒为 6–24 月龄住院腹泻的首位病原，秋冬季节高发。"},"patho":"病毒（轮状、诺如）侵犯小肠绒毛上皮，导致绒毛破坏与双糖酶活性下降，形成渗透性腹泻；同时减少钠-葡萄糖共转运体功能，水分吸收障碍。细菌性腹泻通过肠毒素（如霍乱毒素、产毒性大肠埃希菌）分泌性腹泻或侵袭肠黏膜（沙门菌、志贺菌）引起炎症与黏液脓血便。大量水与电解质（钠、钾、氯）丢失，引起等渗或低渗性脱水、代谢性酸中毒与低钾血症，是死亡的主要原因。","dx":{"criteria":["每日排便 ≥3 次，或大便性状明显变稀；可伴呕吐、腹痛、发热","脱水评估：轻度（体重丢失 ≤5%，口渴、尿略少）；中度（6%–9%，精神萎靡、眼窝凹陷、皮肤弹性差、尿量减少）；重度（≥10%，意识障碍、休克、无尿、四肢凉）","血便或黏液便、高热、里急后重提示侵袭性细菌感染（志贺菌、沙门菌、弯曲菌、致病性大肠埃希菌）","以下为重症预警：<6 个月、体重丢失 >10%、频繁呕吐无法口服、血便、高热 >39 ℃、抽搐、意识改变","病程 >14 d 为迁延性/慢性腹泻，需评估乳糖不耐受、炎症性肠病、寄生虫等"],"workup":["体重、生命体征、尿量与皮肤弹性、毛细血管再充盈、前囟（婴儿）","大便常规与隐血，必要时大便培养与轮状病毒/诺如病毒抗原","血电解质、血尿素氮/肌酐、血气（中重度脱水或意识改变）","血常规与 CRP（疑细菌感染、高热或血便）","尿量监测与体重复测（评估补液效果）"],"grading":"脱水分级：轻度（≤5%）、中度（6%–9%）、重度（≥10%）；WHO 以「无/有些/重度脱水」三分类指导补液途径；慢性腹泻按病程分类（<14 d 急性、14–30 d 迁延、>30 d 慢性）。"},"ddx":[{"name":"肠套叠（ped_intuss）","point":"与本类 ped_intuss 的鉴别点：肠套叠以阵发性哭闹、呕吐、果酱样便和腹部包块为特征，超声见「靶环征」，无全身感染中毒表现；单纯腹泻以排便次数增多为先导，无包块与周期性哭闹。"},{"name":"病毒性胃肠炎","point":"轮状/诺如病毒所致，水样便无黏液脓血，可伴呼吸道症状，一般 3–7 d 自限；与细菌性腹泻的鉴别在于大便常规与培养。"},{"name":"食物过敏（牛奶蛋白过敏）、乳糖不耐受","point":"进食后出现腹泻、湿疹或生长发育迟滞，回避过敏原后改善；婴儿多为配方奶喂养或母乳母亲饮食摄入相关。"},{"name":"肠梗阻、阑尾炎、坏死性小肠结肠炎","point":"呕吐胆汁、腹胀、肠鸣音减弱或亢进、腹肌紧张与压痛，腹部立位片见液平，需急诊外科评估。"},{"name":"尿路感染、伤寒、疟疾","point":"发热伴腹泻但尿常规异常或血培养阳性；腹泻不突出而全身症状重，需鉴别与血液学检查。"}],"tx":{"drug":[{"name":"口服补液盐（ORS III，低渗）","dose":"轻中度脱水：50–100 mL/kg，4 h 内少量多次口服（每次 5–10 mL，2–3 min 一次）；<6 个月每次 5–10 mL；每排一次稀便后补充 <2 岁 50–100 mL、>2 岁 100–200 mL","note":"一线治疗，WHO 推荐低渗 ORS（钠 75 mmol/L、葡萄糖 75 mmol/L）；含葡萄糖可促进钠吸收，避免自制糖盐水（配比不准）","renal":"无尿或少尿时监测尿量后继续补液，肾功能不全时注意高钾","hepatic":"遵说明书","interact":"不与其他含糖饮料同服，以免钠浓度被稀释"},{"name":"静脉补液（中重度脱水或口服失败）","dose":"重度脱水：0.9% 生理盐水 20 mL/kg 于 20 min 内快速静滴，必要时重复（1 h 内最多 3 次，总量 60 mL/kg）；随后按累计损失量（中度 50–100 mL/kg、重度 100–150 mL/kg）+ 维持量（<1 岁 100–150 mL/kg/d，1–3 岁 80–100 mL/kg/d）用 1/2–1/3 张液体补充 24 h","note":"补液过程中监测心率、尿量、皮肤弹性，警惕低血糖与低钠血症；<1 岁婴儿注意避免低钠液体过量","renal":"无尿时限制液体，注意高钾血症","hepatic":"遵说明书","interact":"遵说明书"},{"name":"葡萄糖酸锌/硫酸锌","dose":"元素锌 10–20 mg/d，疗程 10–14 d；6 个月以下 10 mg/d，6 个月以上 20 mg/d","note":"WHO 推荐腹泻儿童补锌，可缩短病程约 25%、减少复发；糖浆或片剂均可","renal":"遵说明书","hepatic":"遵说明书","interact":"与四环素类、喹诺酮类合用降低吸收（间隔 2 h）；高剂量锌可致呕吐"},{"name":"蒙脱石散","dose":"1 岁以下 1 g tid，1–2 岁 1–1.5 g tid，>2 岁 3 g tid，饭前服","note":"吸附肠毒素、保护黏膜；需与口服药物间隔 1–2 h","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他口服药同服降低吸收（间隔 1–2 h）"},{"name":"益生菌（布拉氏酵母菌/鼠李糖乳杆菌）","dose":"布拉氏酵母菌 250–500 mg（5–10×10⁹ CFU）bid；鼠李糖乳杆菌 GG 10⁹–10¹⁰ CFU/d，疗程 5–7 d","note":"用于急性水样泻辅助治疗；免疫缺陷或中心静脉置管者慎用布拉氏酵母菌（真菌血症风险）","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗真菌药合用降低酵母菌效力"},{"name":"头孢曲松（细菌性痢疾/重症细菌性腹泻）","dose":"50–75 mg/kg/d 静脉 qd（最大 2 g/d），疗程 5 d；或阿奇霉素 10 mg/kg qd 口服（最大 500 mg）×3–5 d","note":"仅用于血便、高热、中毒症状或培养证实的侵袭性细菌感染；病毒性腹泻不用抗生素","renal":"肾功能不全无需调整","hepatic":"严重肝功能不全减量","interact":"新生儿禁与含钙输液同通路"},{"name":"消旋卡多曲","dose":"1.5 mg/kg tid 口服（最大 6 mg/kg/d），疗程 5 d","note":"减少肠分泌，国内可选用；不推荐用于 <3 个月婴儿","renal":"肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与地高辛合用可增加洋地黄毒性风险"}],"nonDrug":["轻中度脱水首选口服补液，不宜常规静脉输液","继续喂养：母乳喂养不中断，年长儿给予易消化饮食（米粥、面条），无需禁食","禁用止泻药（洛哌丁胺等）于儿童，尤其在腹泻性发热或血便时；也不推荐常规止吐药（昂丹司琼可用于呕吐影响口服补液时，需单次按体重）","监测：体重、尿量、精神状态，4–6 h 复评脱水程度","隔离与手卫生，粪口传播预防；轮状病毒疫苗为预防关键"],"life":["补液后 4–6 h 复评体重与尿量，达脱水纠正目标后继续按需补充","恢复饮食后少量多餐，避免高糖饮料与果汁（渗透性腹泻加重）","补锌疗程 10–14 d 完整执行","预防：接种轮状病毒疫苗（6 周龄起），改善饮水与卫生","家长教育：识别脱水信号（少尿、眼窝凹陷、精神差、哭泣无泪），掌握 ORS 配制"]},"prog":"病毒性腹泻多为 3–7 d 自限；及时口服补液可使脱水相关病死率下降 90% 以上。迁延性腹泻需警惕乳糖不耐受与营养不良，长期随访生长发育。","refs":["中华医学会儿科学分会消化学组. 中国儿童急性感染性腹泻病临床实践指南（2020 版）","WHO. The treatment of diarrhoea: a manual for physicians and other senior health workers (2005)","ESPID/ESPGHAN. European Society for Paediatric Gastroenterology, Hepatology and Nutrition/ESPID evidence-based guidelines for the management of acute gastroenteritis in children in Europe (2014)","WHO. Zinc supplementation in the management of diarrhoea (2016)"]},{"id":"ped_intuss","name":"肠套叠","aka":["Intussusception","回结肠套叠"],"rank":2,"basic":{"define":"一段肠管及其系膜套入邻近肠腔内，导致肠腔梗阻与血供障碍，是婴幼儿最常见的急腹症之一。以回结肠套叠最常见（占 80%–90%），好发于 6 个月—2 岁，男孩多于女孩。","risk":["年龄 6–18 个月（高峰）、男孩（男:女约 2:1–3:1）","肠系膜淋巴结炎、病毒性感染（腺病毒、轮状病毒疫苗后罕见）","解剖异常（梅克尔憩室、息肉、淋巴瘤为继发性套叠的病理起点）","既往肠套叠史（复发率约 5%–10%）","囊性纤维化、过敏性紫癜（Henoch-Schönlein 紫癜）"],"epi":"我国婴幼儿肠套叠发病率约 1.5–4/1000 活产儿，是 <2 岁儿童急腹症最常见原因。早期诊断与空气灌肠复位可使需手术比例降至 10% 以下，延误可致肠坏死与穿孔。"},"patho":"近端肠管套入远端肠腔后，套入部肠壁与系膜被挤压，致静脉回流受阻、黏膜水肿出血，继而动脉血供障碍、肠壁坏死穿孔。肠系膜淋巴结肿大、肠道病毒感染被认为是常见诱因；套入部形成「腊肠样」包块，梗阻近端肠管扩张、呕吐。","dx":{"criteria":["典型三联征：阵发性哭闹（每 5–20 min 发作，持续数分钟）+ 呕吐 + 果酱样黏液血便（约 60% 病例，出现较晚）","腹部触诊：右上腹或脐周可触及腊肠样包块，有压痛","超声：横切面「靶环征」（同心圆）、纵切面「假肾征」，敏感度 >95%","腹部立位片：肠梗阻征象（液平、肠管扩张），一般不做钡餐","出现腹胀明显、腹肌紧张、肠鸣音消失提示肠穿孔或坏死，需急诊手术"],"workup":["腹部超声（确诊与套叠范围、套入部血供、腹胀程度）","腹部立位 X 片评估梗阻与穿孔（膈下游离气体）","血常规、电解质与血气（脱水与呕吐丢失）","查体：腹部包块、肠鸣音、腹肌紧张、直肠指检（指套染血）","术前评估：凝血、血型、心肺功能"],"grading":"按病程：急性（<48 h）、亚急性（2–5 d）、慢性（>5 d，多为继发性）；按病因：原发性（特发性，占 90%）与继发性（病理性起点）；按状态：无肠坏死/肠坏死/穿孔。超声可提示复位可能性（套入深度、血流信号）。"},"ddx":[{"name":"儿童腹泻与口服补液（ped_diarrhea）","point":"与本类 ped_diarrhea 的鉴别点：肠套叠以阵发性哭闹+呕吐+果酱样便及腹部包块为特征，超声靶环征；腹泻以排便次数增多为主，无腹部包块与周期性哭闹。"},{"name":"急性阑尾炎","point":"多见于 >5 岁，转移性右下腹痛、麦氏点压痛与反跳痛、发热，超声见肿大阑尾；婴幼儿少见，超声可鉴别。"},{"name":"梅克尔憩室出血","point":"无痛性大量暗红色血便（无阵发性哭闹与包块），Tc-99m 扫描阳性；肠套叠出血多为少量果酱样。"},{"name":"肠系膜淋巴结炎、胃肠炎伴肠痉挛","point":"腹痛不呈周期性、无包块与血便，超声见淋巴结肿大但无靶环征。"},{"name":"幽门梗阻、肠旋转不良扭转","point":"喷射性呕吐（无胆汁）、右上腹包块（肥厚性幽门狭窄）；肠扭转为胆汁性呕吐与腹胀，腹痛持续，腹部立位片与超声协助鉴别。"}],"tx":{"drug":[{"name":"镇静/解痉（灌肠复位辅助）","dose":"复位前酌情使用咪达唑仑 0.1–0.2 mg/kg 静脉或口服（需监护呼吸），或按麻醉科方案；不推荐常规使用阿托品","note":"灌肠复位需在儿科/外科监护下进行，镇静可减少患儿哭闹与腹压，但也可能掩盖穿孔表现","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"咪达唑仑与阿片类合用加重呼吸抑制"},{"name":"静脉补液","dose":"0.9% 生理盐水 20 mL/kg 快速静滴，按脱水程度补充；呕吐频繁者加维持量","note":"复位前纠正脱水与电解质紊乱，降低肠坏死风险","renal":"少尿时慢速补液","hepatic":"遵说明书","interact":"遵说明书"},{"name":"对乙酰氨基酚（镇痛/退热）","dose":"10–15 mg/kg q4–6h，每日 ≤75 mg/kg","note":"仅用于缓解疼痛，不掩盖急腹症判断；腹痛持续加重需立即外科评估","renal":"肾功能不全延长间隔","hepatic":"肝功能不全减量","interact":"与酶诱导剂合用增加肝毒性"},{"name":"头孢呋辛/头孢曲松（合并感染/手术预防）","dose":"头孢呋辛 50 mg/kg/d 分 3 次静脉，术前 30 min 一次；术中污染严重时延长至 5–7 d","note":"仅用于手术预防或合并肠坏死","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["空气灌肠复位（首选）：压力 60–80 mmHg（约 8–10 kPa，视年龄与设备），灌肠前排除穿孔与腹膜炎；成功率约 80%–90%","超声引导下生理盐水灌肠复位：部分中心用于无透视条件，适应证同空气灌肠","水压/钡剂灌肠：空气灌肠不宜时选用，需注意造影剂吸收与穿孔后的腹膜炎风险","复位后观察：48 h 内复发性套叠约 5%–10%，可重复灌肠；出现血便加重、腹膜炎需手术","手术指征：灌肠失败、穿孔/腹膜炎、病程 >48–72 h 伴危重、休克、复发多次、疑继发性套叠","手术方式：开腹/腹腔镜复位，肠坏死需切除吻合；合并病理性起点（梅克尔憩室等）需处理","液体复苏与营养支持：术后禁食、胃肠减压，恢复肠鸣音后逐步喂养"],"life":["复位后 1–2 周复诊，警惕复发与再次套叠","预防复发：注意轮状病毒疫苗接种时机；有继发性病因者随访原发病","家长教育：再次出现阵发性哭闹、呕吐、果酱样便需立即就诊","术后营养与发育随访，尤其肠切除者","避免延误：发病 >48 h 复位成功率下降，需尽早诊断"]},"prog":"及时空气灌肠复位成功者预后良好，住院 <48 h；灌肠失败约 10%–20% 需手术，病死率 <0.1%；延迟诊断伴肠坏死穿孔者病死率与并发症显著增加。","refs":["中华医学会儿科学分会. 儿童肠套叠诊疗专家共识（2021）","AAP/ACR. Appropriateness Criteria: Intussusception in Children (2021)","WHO. Rotavirus vaccines and intussusception (position paper 2013, updated 2024)","ESPID. Management of intussusception in children (2019)"]}]},{"id":"ped_neuro","name":"神经与新生儿","rank":3,"summary":"热性惊厥主要为止惊与病因排查，单纯型不需长期抗癫痫药；新生儿黄疸以小时龄胆红素曲线分层，光疗与换血的阈值按 Bhutani 曲线与高风险因素决定，警惕胆红素脑病。","compare":[{"diseaseId":"ped_febrile_seizure","dx":"6 个月—5 岁儿童发热（>38 ℃）期间出现的惊厥，无中枢神经系统感染证据，既往无无热惊厥史","key":"惊厥发生于发热期，单纯型 <15 min、24 h 内仅 1 次、全面性"},{"diseaseId":"ped_jaundice","dx":"新生儿皮肤与巩膜黄染，血清总胆红素超过同龄小时龄的第 95/75 百分位，需按小时龄评估","key":"出生后 24 h 内出现或以小时龄胆红素曲线超出阈值"}],"diseases":[{"id":"ped_febrile_seizure","name":"热性惊厥","aka":["Febrile Seizure","热性惊厥","高热惊厥"],"rank":1,"basic":{"define":"6 个月—5 岁儿童在发热（通常 >38 ℃）期间出现的惊厥，无中枢神经系统感染与代谢异常的证据，既往无无热惊厥史。分为单纯型（全面性发作 <15 min、24 h 内仅 1 次）与复杂型（局灶性、持续时间 ≥15 min、24 h 内 ≥2 次）。","risk":["年龄 6 个月—5 岁（高峰 12–18 个月）","一级亲属热性惊厥史（遗传易感性）","发热性疾病（尤其病毒性上呼吸道感染、幼儿急疹）","复杂型发作、发作年龄 <12 个月者复发风险高","缺铁性贫血、疫苗接种后发热"],"epi":"5 岁以下儿童中约 2%–5% 至少发生过一次热性惊厥，是儿童期最常见的惊厥原因；约 30%–40% 会复发，多数在首次发作后 1–2 年内。单纯型占 70%–80%，预后良好。"},"patho":"发热使发育中大脑（未成熟海马与皮层）神经元兴奋性升高，谷氨酸能传递增强、GABA 抑制减弱；遗传背景（离子通道与炎症介质相关基因）使惊厥阈值降低。发作时皮层神经元同步异常放电，可致短暂低氧、代谢增快与脑水肿风险（持续状态时）。单纯型发作多为全面性，发作后短暂嗜睡与肌张力低可解释为发作后状态。","dx":{"criteria":["年龄 6 个月—5 岁，发热（通常 >38 ℃）期间出现惊厥","单纯型：全面性（非局灶）、持续时间 <15 min、24 h 内仅 1 次、发作后神经系统检查正常","复杂型：局灶性、持续时间 ≥15 min、24 h 内 ≥2 次、发作后有局灶性神经体征","排除中枢神经系统感染：脑膜刺激征、意识持续异常、异常前囟、严重中毒症状需行腰穿","既往无无热惊厥史（否则考虑癫痫）","惊厥持续 >5 min 视为惊厥持续状态，需立即止惊"],"workup":["生命体征、血糖、体温与神经系统查体（发作后 30–60 min 复评）","血常规、CRP、电解质、血糖（疑感染或代谢异常）","无脑膜刺激征且一般情况好的单纯型，不推荐常规腰穿或脑电图","复杂型或 <12 个月：脑电图（发作后 2 周）、头颅影像（MRI）评估结构性病因","体温与惊厥发作关系记录，必要时病毒检测"],"grading":"分型：单纯型与复杂型；发作持续时间分：短暂（<5 min）、持续（5–15 min）、惊厥持续状态（≥5 min 需干预，≥30 min 为持续状态）；复发风险评分可辅助（年龄 <18 个月、首次发作体温低、发作距发热时间短者复发风险高）。"},"ddx":[{"name":"新生儿黄疸（ped_jaundice）","point":"与本类 ped_jaundice 的鉴别点：黄疸出现于新生儿期（<28 d），以皮肤黄染与胆红素升高为主，可伴胆红素脑病而出现嗜睡、肌张力低下；热性惊厥发生于 6 个月—5 岁发热儿童，黄疸非其特征。"},{"name":"化脓性脑膜炎/病毒性脑炎","point":"发热伴意识障碍、颈强直、前囟膨隆、抽搐或局灶体征，需腰穿确诊；热性惊厥发作后 30 min 内意识应恢复。"},{"name":"癫痫（首次发作）","point":"无热惊厥或反复发作，脑电图见痫样放电；热性惊厥仅发生于发热期。"},{"name":"低血糖、低钙血症、低钠血症","point":"血糖 <2.6 mmol/L 或电解质异常可致惊厥，需急查血糖与电解质；纠正后不再发作。"},{"name":"寒战、屏气发作、晕厥","point":"寒战无意识丧失；屏气发作有情绪诱因、发绀、短暂意识丧失后恢复；晕厥为脑灌注不足所致，无发热期关联。"}],"tx":{"drug":[{"name":"地西泮（直肠给药）","dose":"0.5 mg/kg 直肠给药（最大 10 mg），发作 >5 min 时使用；可重复 1 次（间隔 5 min）","note":"院前或家中首选止惊方式；无直肠剂型时可用生理盐水稀释后保留灌肠","renal":"肾功能不全慎用","hepatic":"严重肝功能不全延长作用时间","interact":"与苯巴比妥、丙戊酸合用增加呼吸抑制"},{"name":"地西泮（静脉）","dose":"0.2–0.5 mg/kg 静脉缓慢推注（最大 10 mg），速度 ≤1 mg/min；必要时 5 min 后重复 1 次","note":"医院内首选；注意呼吸抑制与低血压，需备复苏设备与吸氧","renal":"肾功能不全延长作用","hepatic":"严重肝功能不全减量并延长观察","interact":"与阿片类合用加重呼吸抑制"},{"name":"劳拉西泮（静脉）","dose":"0.05–0.1 mg/kg 静脉推注（最大 2 mg），可 5 min 后重复 1 次","note":"持续时间较地西泮长，适用于反复发作或持续状态；需监护呼吸","renal":"重度肾功能不全减量","hepatic":"严重肝功能不全减量","interact":"与丙泊酚、阿片类合用加重呼吸抑制"},{"name":"对乙酰氨基酚/布洛芬（退热）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h（每日 ≤75 mg/kg）；布洛芬 5–10 mg/kg q6–8h（6 个月以上，每日 ≤40 mg/kg）","note":"退热药可缓解发热不适，但不能预防惊厥复发；不推荐为预防惊厥而长期规律使用","renal":"布洛芬在脱水时慎用","hepatic":"肝功能不全时对乙酰氨基酚减量","interact":"避免与含相同成分复方药同用"},{"name":"左乙拉西坦（复杂型/复发频繁，预防性）","dose":"起始 10–20 mg/kg/d 分 2 次口服，可逐渐增至 40–60 mg/kg/d；仅在反复发作或复杂型、家长充分知情后按癫痫专科意见使用","note":"单纯型热性惊厥不推荐常规预防用药；间歇性预防与长期预防的获益少于副作用","renal":"eGFR 50–80 减量 50%，<30 减量 75%","hepatic":"严重肝功能不全减量","interact":"与其他中枢抑制剂合用加重嗜睡"}],"nonDrug":["侧卧位、松开衣领、防误吸；不要强行按压肢体或向口内塞物品","记录发作开始时间与形态，观察面色、呼吸与意识恢复情况","发作 >5 min：启动止惊处理；发作持续状态：气道保护、氧疗、静脉通路，按癫痫持续状态流程","发作停止后评估病因（发热源、血糖、电解质）并观察 30–60 min 意识恢复","家长教育与宣教：识别惊厥、家庭急救（地西泮直肠给药）、急救呼叫时机","单纯型热性惊厥复发风险可解释，不需常规长期抗癫痫药；复杂型由儿科神经专科评估"],"life":["发热时及时退热、多饮水、观察精神状态","避免儿童游泳或独自接触危险环境时无人看护（惊厥相关风险）","预后与随访：单纯型不会导致智力下降或发育迟缓；复发多在 1–2 年内","心理支持与家庭急救培训","复杂型者规律随访脑电图与神经发育评估"]},"prog":"单纯型热性惊厥预后极好，不影响智力与认知发育；约 30%–40% 复发，多在首 2 年内。此后癫痫发病率约 1%–2%（相比正常儿童 0.5%–1% 轻度升高）；复杂型、发作前已有发育异常、家族癫痫史者风险较高。","refs":["中华医学会儿科学分会神经学组. 热性惊厥诊断治疗与管理专家共识（2016，2019 更新）","AAP. Clinical Practice Guideline: Neurodiagnostic Evaluation of the Child With a Simple Febrile Seizure (2011)","ILAE. Definition of Status Epilepticus (2015)","NICE. Epilepsies: diagnosis and management (CG137, 2022)"]},{"id":"ped_jaundice","name":"新生儿黄疸","aka":["Neonatal Jaundice","Neonatal Hyperbilirubinemia","新生儿高胆红素血症"],"rank":2,"basic":{"define":"新生儿期因胆红素代谢特点（红细胞寿命短、肝酶活性低、肠肝循环增加）出现皮肤与巩膜黄染，血清总胆红素（TSB）超过同龄小时龄的干预阈值即为病理性黄疸。分生理性与病理性；重症可致胆红素脑病（核黄疸）。","risk":["早产（<37 周）、低出生体重、小于胎龄儿","出生后 24 h 内出现黄疸（提示溶血）","G6PD 缺乏症、Rh 或 ABO 血型不合溶血","母乳喂养不足、体重下降 >8%–10%、脱水","头盆血肿、皮下瘀斑、感染（败血症）、肝炎、胆道闭锁"],"epi":"足月新生儿约 60% 在生后 1 周内出现可见黄疸，早产儿可达 80%；需光疗者约 5%–10%，需换血者 <0.1%。我国 G6PD 缺乏症高发地区（华南、西南）黄疸导致胆红素脑病风险较高。"},"patho":"新生儿红细胞寿命短（70–90 d）、红细胞数量多，出生后分解产生大量胆红素（成人 2 倍）；肝细胞摄取、结合（UGT1A1 活性低）、排泄能力不足；肠道内 β-葡萄糖醛酸苷酶活性高，使结合胆红素水解后经肠肝循环再吸收增加。溶血（Rh/ABO 不合、G6PD 缺乏）使胆红素生成进一步增加，超过肝处理能力，未结合胆红素（脂溶性）透过血脑屏障沉积于基底节、海马与脑干核团，引起胆红素脑病。","dx":{"criteria":["出生后 24 h 内出现黄疸或黄疸进展迅速（每日 TSB 上升 >5 mg/dL 或 >85 µmol/L）→ 病理性，需立即评估","TSB 超过小时龄第 95 百分位（Bhutani 曲线）或达光疗阈值 → 高胆红素血症","皮肤黄染部位可粗略估计胆红素：头面部约 5–6 mg/dL、胸腹部 10–12 mg/dL、四肢 15 mg/dL、手足心 >15–20 mg/dL（不可替代 TSB）","危险信号：嗜睡、吸吮力弱、肌张力低下或增高、尖叫、角弓反张 → 警惕胆红素脑病","生理性黄疸：生后 2–3 d 出现、足月儿 4–5 d 达高峰（TSB <12.9 mg/dL 即 <221 µmol/L）、7–10 d 消退；早产儿可延至 3–4 周","病理性：24 h 内出现、TSB 上升过快、足月儿 TSB >221 µmol/L（12.9 mg/dL）、黄疸持续 >2 周（足月）或 >4 周（早产）、结合胆红素 >1–2 mg/dL"],"workup":["经皮胆红素（TcB）筛查（>35 周），HsT 与小时龄对应评估","血清总胆红素（TSB）与直接胆红素：TcB 接近阈值或需换血时必须测 TSB","血型（母婴 ABO 与 Rh）、直接抗人球蛋白试验（Coombs）","血常规（红细胞、血红蛋白、网织红细胞、外周血涂片）","G6PD 活性检测（高发地区/家族史/溶血者）","肝功能、甲功（甲减可致黄疸延长）、尿常规与尿胆原","疑胆道闭锁：直接胆红素升高、大便颜色变浅、腹部超声与肝胆核素扫描"],"grading":"按小时龄胆红素百分位（Bhutani 曲线：低危、中低危、中高危、高危）；按严重程度：轻度（TSB 超过阈值但低于换血阈值）、重度（达换血阈值）、极重度（TSB ≥25 mg/dL 或 428 µmol/L）；胆红素脑病分急性期（肌张力低下→增高、嗜睡、尖叫）与慢性期（手足徐动、听力障碍、智力发育落后）。"},"ddx":[{"name":"热性惊厥（ped_febrile_seizure）","point":"与本类 ped_febrile_seizure 的鉴别点：热性惊厥发生于 6 个月—5 岁发热期，表现为抽搐；新生儿黄疸以皮肤黄染与 TSB 升高为主，胆红素脑病也可出现肌张力改变但无发热性抽搐典型表现。"},{"name":"新生儿肝炎、先天性胆道闭锁","point":"结合胆红素升高（>1 mg/dL 或 >17 µmol/L）、大便颜色变浅、肝脾肿大，胆道闭锁需在 60 d 内手术（Kasai），延误预后差。"},{"name":"母乳性黄疸","point":"母乳喂养良好、一般情况好，TSB 在生后 4–7 d 达峰后缓慢下降，可持续 4–12 周；停止母乳 24–48 h 黄疸明显下降可确诊（不常规停喂）。"},{"name":"溶血性疾病（Rh/ABO 不合、G6PD 缺乏）","point":"生后 24 h 内出现黄疸、贫血、网织红细胞升高、Coombs 阳性；G6PD 缺乏在接触氧化性药物/蚕豆后加重。"},{"name":"败血症、先天性感染（TORCH）","point":"伴发热/体温不升、反应差、喂养困难、肝脾肿大与皮疹，血培养与 TORCH 抗体可鉴别。"}],"tx":{"drug":[{"name":"光疗（干预手段，非药物）","dose":"标准光疗：波长 430–490 nm 蓝光，光照强度 ≥30 µW/(cm²·nm)，照射面积尽可能大；间歇光疗或连续光疗按机构方案。阈值按小时龄与风险分层（足月儿生后 24–48 h 约 12–15 mg/dL，72 h 后 15–17 mg/dL；早产/高危更低）","note":"光照期间监测体温、液体摄入与尿量；遮盖眼睛与生殖器；任何光疗均需在 TSB 曲线指导下开始与停止","renal":"遵说明书","hepatic":"遵说明书","interact":"光照可降低核黄素水平，长时间光疗可补充"},{"name":"静脉免疫球蛋白（IVIG）","dose":"Rh 或 ABO 溶血且光疗下 TSB 仍快速上升或接近换血阈值：0.5–1 g/kg 静脉滴注（2–4 h），必要时 12 h 后重复 1 次","note":"可减少换血需要，但不能替代换血；需监测溶血与贫血","renal":"肾功能不全时注意容量负荷","hepatic":"遵说明书","interact":"与减毒活疫苗需间隔 3 个月以上"},{"name":"白蛋白（换血辅助）","dose":"TSB 接近换血阈值且有低白蛋白血症时 1 g/kg 静脉输注（换血前 2–4 h），按机构方案","note":"结合游离胆红素，减少进入脑组织；不作为常规使用","renal":"心功能不全者限制液体与速度","hepatic":"遵说明书","interact":"遵说明书"},{"name":"苯巴比妥（肝酶诱导，少用）","dose":"5 mg/kg/d 分 2 次口服或静脉，疗程 3–5 d，仅用于 UGT1A1 缺陷（Gilbert/Crigler-Najjar）或需长期降胆红素者，按专科意见","note":"非常规治疗手段；可致嗜睡、呼吸抑制","renal":"肾功能不全减量","hepatic":"肝功能不全避免大剂量","interact":"与地西泮合用增加呼吸抑制；酶诱导作用影响其他药物代谢"},{"name":"锌原卟啉/锡原卟啉（研究性）","dose":"按专科研究方案，不推荐常规临床使用","note":"抑制血红素加氧酶，目前不作为标准治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"换血（治疗手段，非药物）","dose":"双倍血量换血（约 160–180 mL/kg），采用与母血型相容的浓缩红细胞+新鲜冰冻血浆；指征为 TSB 达换血阈值或已有胆红素脑病征象","note":"需在有新生儿重症监护条件的机构进行；换血后 2–4 h 复查 TSB 并继续光疗","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["建立小时龄-胆红素曲线评估，出院前对所有新生儿测 TcB/TSB 并评估随访时间","频繁喂养（每日 8–12 次），保证足够摄入，减少肠肝循环；母乳喂养不足者补充配方奶","高胆红素血症的随访：出院后 24–48 h、72 h 复测；TSB 接近阈值者更频繁","光疗期间监测体温、体重、尿量与大便，防止脱水","胆道闭锁需在 60 d 内行 Kasai 手术，直接胆红素升高 + 大便色浅者立即转诊","G6PD 缺乏者避免氧化性药物（磺胺类、呋喃类、萘）与蚕豆"],"life":["家庭观察：皮肤黄染范围、精神、喂养与尿便颜色；教会家长识别危险信号","长期随访：重度高胆红素血症患儿 3–6 个月听性脑干反应（ABR）与神经发育评估","G6PD 缺乏症筛查与家族宣教（我国华南、西南高发）","胆道闭锁术后随访肝功能与营养（脂溶性维生素）","预防 Rh 溶血：Rh 阴性母亲孕期与产后抗 D 免疫球蛋白"]},"prog":"轻中度黄疸经光疗多可缓解，无后遗症；TSB ≥20 mg/dL（342 µmol/L）时风险显著增加，达换血阈值未及时干预可致胆红素脑病（急性期死亡率约 5%–10%，存活者多数遗留手足徐动、听力障碍与认知损害）。及时筛查与治疗可将严重后果几乎降至零。","refs":["中华医学会儿科学分会新生儿学组. 新生儿高胆红素血症诊断和治疗专家共识（2014，2022 修订）","AAP. Clinical Practice Guideline Revision: Management of Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation (2022)","NICE. Jaundice in newborn babies under 28 days (CG98, 2016, updated 2023)","国家卫生健康委. 新生儿疾病筛查管理办法与 G6PD 缺乏症筛查（2010）"]}]},{"id":"ped_resp","name":"呼吸与其他","rank":4,"summary":"毛细支气管炎以支持治疗为主，不常规使用支气管舒张剂或激素；儿童哮喘按阶梯方案以吸入激素为基础，急性发作首选 SABA 吸入；川崎病需在发病 10 d 内使用 IVIG 与阿司匹林，冠脉监测贯穿全程。","compare":[{"diseaseId":"ped_bronchiolitis","dx":"2 岁以下（高峰 2–6 个月）婴儿急性起病，流涕、低热后出现喘息与呼气相延长、三凹征，胸片见过度充气","key":"<2 岁首次喘息、以病毒（RSV）为诱因，一般情况与进食尚可"},{"diseaseId":"ped_asthma","dx":"反复发作的喘息、气促、胸闷与咳嗽，夜间及运动后加重，支气管舒张试验或 PEF 变异率支持，有过敏史或家族史","key":"反复喘息史 + 支气管舒张剂有效 + 过敏背景"},{"diseaseId":"ped_kawasaki","dx":"发热 ≥5 d 伴双侧球结膜充血、口唇皲裂/草莓舌、手足硬肿或脱皮、多形性皮疹、颈淋巴结 >1.5 cm，5 项中 ≥4 项即可典型诊断","key":"持续高热 + 多系统黏膜皮肤表现，CRP/血沉显著升高、血小板后期升高"}],"diseases":[{"id":"ped_bronchiolitis","name":"毛细支气管炎","aka":["Bronchiolitis","RSV 毛细支气管炎"],"rank":1,"basic":{"define":"2 岁以下婴幼儿由病毒感染引起的细支气管炎症与阻塞，以呼吸道合胞病毒（RSV）最常见，表现为流涕、咳嗽、喘息与呼吸增快，是婴儿住院的最常见呼吸道原因。","risk":["年龄 2–6 个月、早产（<37 周）、低出生体重","先天性心脏病、慢性肺疾病（BPD）、免疫缺陷","母乳喂养时间短、托幼机构接触、烟雾暴露","秋冬季节（RSV 流行期为 10 月至次年 3 月）、家庭内感染者","21 三体综合征、神经肌肉疾病"],"epi":"RSV 是世界范围内婴幼儿下呼吸道感染的首位病原，全球每年约 3300 万例 RSV 相关下呼吸道感染，<5 岁儿童约 10 万例死亡。我国婴幼儿住院下呼吸道感染中 RSV 阳性率约 20%–30%，<6 个月婴儿重症比例最高。"},"patho":"RSV 感染细支气管上皮细胞，引起上皮坏死、黏膜下水肿与黏液分泌增多，细支气管管腔狭窄甚至阻塞；呼气时小气道塌陷，形成气体陷闭与过度充气（胸片见肺气肿样表现）。阻塞与肺不张区域导致通气/血流比例失调与低氧血症；婴儿呼吸肌与胸壁顺应性差，易出现呼吸衰竭。","dx":{"criteria":["2 岁以下婴儿，先有流涕、低热、咳嗽 1–3 d，继之出现呼吸增快、喘息、三凹征、鼻翼扇动","听诊：双肺弥漫性哮鸣音、细湿啰音，呼气相延长；严重时呼吸音减低","SpO₂ <92% 提示低氧；呼吸频率 >70 次/分、拒食、呼吸暂停、嗜睡为重症信号","鼻咽拭子 RSV 抗原/核酸检测阳性支持诊断（不影响治疗决策）","胸片非必需，若摄片见过度充气、斑片状浸润与肺不张；避免常规胸片"],"workup":["呼吸频率、SpO₂、三凹征与哺乳能力评估（Apgar 样呼吸窘迫评分可选）","鼻咽拭子快速 RSV 抗原/核酸（住院或需隔离者）","血气（重症或呼吸窘迫明显者）","胸片仅在疑并发症或诊断不明时","补液与营养评估；监测呼吸暂停（<2 个月或早产儿）"],"grading":"按病情严重度：轻（进食良好、SpO₂ ≥92%、呼吸做功轻）、中（三凹征、呼吸增快、SpO₂ 90%–92%）、重（呼吸窘迫、SpO₂ <90%、呼吸暂停、拒食、需氧疗或机械支持）。"},"ddx":[{"name":"儿童哮喘（ped_asthma）","point":"与本类 ped_asthma 的鉴别点：毛细支气管炎为 2 岁以下首次喘息、病毒诱因、支气管舒张剂无效；哮喘为反复发作喘息、过敏史、支气管舒张试验阳性且对 SABA 有效。"},{"name":"川崎病（ped_kawasaki）","point":"与本类 ped_kawasaki 的鉴别点：川崎病发热 ≥5 d 伴黏膜皮肤表现、颈淋巴结与 CRP 显著升高；毛细支气管炎以呼吸道症状与喘息为主，发热多为低热。"},{"name":"儿童肺炎（细菌性）","point":"高热、肺部固定湿啰音、胸片见叶段实变，需抗生素；毛细支气管炎多为病毒所致、双肺弥漫哮鸣音。"},{"name":"气道异物吸入","point":"突发呛咳、单侧呼吸音减低与哮鸣，胸片透光度不均，需支气管镜确诊；毛细支气管炎多为双侧、有病毒前驱症状。"},{"name":"先天性气道畸形、百日咳","point":"反复喘息/喉鸣自幼出现（气管软化）；百日咳有阵发性痉咳与鸡鸣样回声，白细胞升高，需 PCR 确诊。"}],"tx":{"drug":[{"name":"氧疗（支持治疗）","dose":"SpO₂ <90%–92% 时给氧（低流量温湿化鼻导管 0.5–2 L/min），目标 SpO₂ ≥92%，不追求更高","note":"给氧是唯一确定有效的支持措施之一；避免高浓度吸氧过度使用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"0.9% 高渗盐水雾化","dose":"3% 高渗盐水 4 mL 雾化，每日 3 次，疗程 3–5 d；可联合沙丁胺醇雾化（部分中心）","note":"可减轻黏膜水肿、改善气道清除；证据中等，不作为所有患者常规","renal":"遵说明书","hepatic":"遵说明书","interact":"与沙丁胺醇雾化同用可增加支气管舒张效果"},{"name":"沙丁胺醇雾化（试验性）","dose":"2.5 mg（0.5 mL 雾化液）用生理盐水稀释至 3–4 mL 雾化，1 次试验性治疗（10–15 min）；有效者继续，无效停用","note":"不常规推荐；约 10%–25% 患儿有短暂反应，观察呼吸做功是否改善","renal":"遵说明书","hepatic":"遵说明书","interact":"与利尿剂合用可致低钾"},{"name":"吸入肾上腺素（重症，试验性）","dose":"1:1000 肾上腺素 0.5 mL 加入 0.9% 生理盐水 3.5 mL 雾化（3 mL），按需重复，1 次后评估","note":"不推荐常规使用；仅在重症/呼吸窘迫且排除其他病因时短期试用，效果不确定","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂同用可拮抗"},{"name":"糖皮质激素（不推荐常规）","dose":"不推荐常规全身或吸入激素；仅在合并哮喘样反应或拔管后气道水肿时按专科意见使用","note":"多项 RCT 显示激素不缩短病程、不减少住院，且可能延长病毒排出","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"静脉补液/鼻饲喂养","dose":"不能维持摄入者：经口/鼻胃管少量多次喂养；禁食者静脉补液维持（1/5–1/4 张，按生理需要量 100 mL/kg/d 起）","note":"避免过量补液（RSV 感染易致 ADH 分泌增多而低钠）","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"利巴韦林（不推荐）","dose":"不推荐常规使用；仅在免疫缺陷或重症合并 RSV 时按专科意见雾化或静脉使用","note":"疗效不确定，有致畸性与操作风险","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与齐多夫定合用增加贫血"}],"nonDrug":["鼻腔吸痰（生理盐水）在喂养前进行，改善通气与进食","呼吸支持：高流量鼻导管氧疗（HFNC，2 L/kg/min）或 CPAP，用于中度呼吸窘迫；无效时气管插管机械通气","住院指征：呼吸暂停、低氧、拒食、脱水、年龄 <3 个月、早产或有基础疾病","监测呼吸暂停（<2 个月或早产婴儿）与心率血氧","抗 RSV 单克隆抗体（帕利珠单抗）用于高危婴儿季节预防（按当地指南）"],"life":["手卫生、避免接触呼吸道感染者；流行季节减少聚集","烟雾暴露环境完全避免；坚持母乳喂养","出院后 1–2 周随访：喘鸣可能持续 2–4 周，注意再次呼吸增快","早产儿或有基础疾病者需呼吸专科随访，评估反复喘息与哮喘发展","家长教育：呼吸做功、进食量与尿量观察，危险信号及时就诊"]},"prog":"多数病例 7–10 d 内好转，住院约 2%–5%；病死率 <0.1%（高危婴儿更高）。约 30%–40% 患儿后续出现反复喘息，部分发展为哮喘。RSV 疫苗接种（孕母或婴儿）与单抗为预防关键。","refs":["中华医学会儿科学分会呼吸学组. 毛细支气管炎诊治专家共识（2014，2020 更新）","AAP. Clinical Practice Guideline: The Diagnosis, Management, and Prevention of Bronchiolitis (2014, updated 2024)","NICE. Bronchiolitis in children: diagnosis and management (NG9, 2015, updated 2023)","WHO. RSV immunization products (2023)"]},{"id":"ped_asthma","name":"儿童哮喘","aka":["Childhood Asthma","支气管哮喘"],"rank":2,"basic":{"define":"以慢性气道炎症与气道高反应性为特征的异质性疾病，表现为反复发作的喘息、气促、胸闷与咳嗽，多在夜间或清晨加重，可逆性气流受限。儿童哮喘常与过敏（湿疹、过敏性鼻炎）共病。","risk":["父母哮喘或过敏性疾病史","婴儿期湿疹、食物过敏（牛奶、鸡蛋）","早期呼吸道病毒感染（RSV 毛细支气管炎）、反复喘息","被动吸烟、室内尘螨、霉菌、宠物皮屑","肥胖、城市生活方式、空气污染"],"epi":"我国城市儿童哮喘患病率约 3%–7%，且逐年上升；<6 岁儿童反复喘息常见，部分随年龄自行缓解。儿童哮喘未控制率仍较高（约 20%–30%），急性发作是急诊与住院的重要原因。"},"patho":"以 Th2 型免疫反应为主导的慢性气道炎症，嗜酸性粒细胞与肥大细胞浸润，气道平滑肌增生、基底膜增厚与黏液腺增生（气道重塑）。过敏原、病毒感染、运动、冷空气、烟雾等触发支气管收缩与黏液分泌增加，出现可逆性气流受限；急性重症发作可因黏液栓与气道痉挛致呼吸衰竭。","dx":{"criteria":["反复发作的喘息、气促、胸闷或咳嗽（≥3 次），夜间/清晨或运动后加重","支气管舒张剂或抗炎治疗后症状缓解","肺功能（≥5–6 岁）：FEV₁/FVC <0.90，FEV₁ 改善率 ≥12% 且绝对值增加 ≥200 mL（支气管舒张试验阳性）；或 PEF 日变异率 >13%","无肺功能条件（<5 岁）：依据病史、体征与治疗反应诊断，需排除其他喘息原因","过敏原皮肤点刺或血清 sIgE 阳性、嗜酸性粒细胞升高支持诊断","急性发作严重度评估：说话方式、呼吸频率、三凹征、SpO₂、PEF（FEV₁）"],"workup":["肺功能（FEV₁、FVC、FEV₁/FVC 与支气管舒张试验）","PEF 日记或家用峰流速监测（≥5 岁）","过敏原检测（皮肤点刺或 sIgE）：尘螨、花粉、宠物皮屑、霉菌","血嗜酸性粒细胞计数、IgE（评估表型，指导生物制剂）","急性发作：SpO₂、PEF、血气（重症）、胸片（疑气胸/肺炎）","6 岁以下喘息：评估危险因素（特应性家族史、湿疹、食物过敏、鼻塞/流涕）辅助诊断"],"grading":"按控制水平（GINA）：控制、部分控制、未控制；按严重度分级（治疗前）：间歇（第 1 级）至重度持续（第 4/5 级）；急性发作分级（轻度/中度/重度/危及生命）。"},"ddx":[{"name":"毛细支气管炎（ped_bronchiolitis）","point":"与本类 ped_bronchiolitis 的鉴别点：毛细支气管炎为 2 岁以下首次喘息、RSV 诱发、支气管舒张剂无效；哮喘是反复发作、过敏背景、对 SABA 与吸入激素反应好。"},{"name":"川崎病（ped_kawasaki）","point":"与本类 ped_kawasaki 的鉴别点：川崎病为持续高热+黏膜皮肤改变+冠脉病变，不伴反复喘息；哮喘症状以气道症状为主、无黏膜皮疹。"},{"name":"气道异物吸入","point":"有呛咳史、突发单侧哮鸣与呼吸音减低，胸片透光度不均，支气管镜可确诊；哮喘为双侧、反复、可逆。"},{"name":"胃食管反流、慢性咳嗽相关病因（上气道咳嗽综合征）","point":"咳嗽为主要表现、夜间或进食后加重，无严重喘息与气流受限；需结合病史与抗反流试验治疗。"},{"name":"先天性气道狭窄、囊性纤维化、支气管扩张","point":"喘息自幼持续、治疗反应差，影像见支气管扩张/肺实变，需胸部高分辨率 CT、汗液氯化物（CF）确诊。"}],"tx":{"drug":[{"name":"沙丁胺醇（短效 β₂ 受体激动剂，SABA）","dose":"定量气雾剂（100 µg/揿）：1–2 揿/次，q4–6h，按需；雾化：0.15 mg/kg/次（最小 2.5 mg，最大 5 mg）加入生理盐水 3 mL 雾化，q20 min ×3 次（急性发作），之后按需","note":"急性发作首选；MDI+储雾罐与雾化等效；长期单用 SABA 不控制炎症，必须联合吸入激素","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂（含滴眼液）同用可拮抗；与利尿剂合用可致低钾"},{"name":"布地奈德（吸入激素，ICS）","dose":"雾化：0.5–1 mg/次 bid；MDI（200 µg/揿）或干粉：低剂量 200–400 µg/d，中剂量 400–800 µg/d（6–11 岁）","note":"长期控制治疗的基础；需每日规律使用，用后漱口，监测身高与口腔真菌","renal":"遵说明书","hepatic":"严重肝功能不全慎用","interact":"与强 CYP3A4 抑制剂（酮康唑、利托那韦）合用增加全身激素效应"},{"name":"孟鲁司特","dose":"6 个月–5 岁 4 mg qn 口服；6–14 岁 5 mg qn；≥15 岁 10 mg qn","note":"作为加用治疗或运动诱发哮喘；注意神经精神不良反应（激惹、噩梦）","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"与苯巴比妥等酶诱导剂合用降低血药浓度"},{"name":"口服泼尼松（急性发作）","dose":"1–2 mg/kg/d（最大 40 mg/d）口服，疗程 3–5 d；不需逐渐减量","note":"中重度发作时早期使用可减少复发；短期使用安全性好","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道溃疡风险"},{"name":"甲泼尼龙（重症发作，静脉）","dose":"0.5–1 mg/kg q6h 静脉（最大 40 mg/次），根据病情 24–48 h 后减量/改口服","note":"用于无法口服或重度发作合并呼吸窘迫","renal":"遵说明书","hepatic":"遵说明书","interact":"与利尿剂合用注意低钾"},{"name":"异丙托溴铵（重度发作联合）","dose":"雾化 250–500 µg/次，联合沙丁胺醇 q20 min ×3 次，之后 q4–6h；<6 岁 250 µg/次","note":"与 SABA 联用可改善重度发作的肺功能，不用于长期控制","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他抗胆碱能药合用增加口干、尿潴留"},{"name":"硫酸镁（重度/危及生命发作）","dose":"40–50 mg/kg 静脉缓慢滴注（20 min 以上，最大 2 g），仅用于对 SABA/异丙托溴铵/激素反应不佳的重度发作","note":"需监测血压与呼吸抑制；肾功能不全减量","renal":"肾功能不全减量并监测血镁","hepatic":"遵说明书","interact":"与神经肌肉阻滞剂、钙通道阻滞剂合用加重肌无力与低血压"},{"name":"奥马珠单抗（重度过敏性哮喘，≥12 岁）","dose":"按 IgE 与体重 150–600 mg 皮下注射 q2–4w，按说明书剂量表","note":"用于中重度过敏性哮喘且控制不佳者，需过敏专科评估","renal":"遵说明书","hepatic":"遵说明书","interact":"与减毒活疫苗间隔；注射液不可与其他药物混合"}],"nonDrug":["长期控制（GINA 阶梯）：第 1 级 按需 SABA；第 2 级 ICS 低剂量（<5 岁可按需 ICS+SABA 或单纯按需 SABA）；第 3 级 ICS 中剂量；第 4 级 ICS 中/高剂量+LAMA 或 LTRA；第 5 级 加生物制剂","急性发作：SABA 吸入 + 氧疗（目标 SpO₂ 94%–98%）+ 早期全身激素；重度加异丙托溴铵与硫酸镁","吸入装置与技巧教育：MDI 配合储雾罐（<5 岁必须用），每次复诊检查技术","书面哮喘行动计划（GINA/中国儿童哮喘行动计划），家长掌握急性发作处理与就医时机","过敏原回避：尘螨防控、宠物、烟草烟雾；必要时过敏原免疫治疗（≥5 岁）","控制不佳需评估依从性、吸入技术、共病（鼻炎、肥胖、反流）与诊断正确性"],"life":["规律运动（运动前 15 min 预防性吸入 SABA 可减少运动诱发发作）","避免烟草烟雾、空气污染与已知诱发因素","每 3–6 个月复诊评估控制水平与调整治疗，阶梯上下调整","每年流感疫苗接种；新冠等呼吸道感染期间加强管理","学龄期儿童哮喘 50%–70% 可长期缓解，需定期评估"]},"prog":"多数儿童哮喘经规范 ICS 治疗可良好控制；约 50%–70% 在青春期症状缓解，但肺功能下降与复发风险存在。急性重症发作（尤其是 PEF <50% 预计值或 SpO₂ <92%）可危及生命，约 50% 的哮喘死亡与治疗不足相关。","refs":["中华医学会儿科学分会呼吸学组. 儿童支气管哮喘诊断与防治指南（2020 年版）","GINA. Global Strategy for Asthma Management and Prevention (2024)","中国儿童哮喘行动计划（CCAAP，2017，2021 更新）","EAACI/ERS. Pediatric asthma management guidelines (2021)"]},{"id":"ped_kawasaki","name":"川崎病","aka":["Kawasaki Disease","KD","皮肤黏膜淋巴结综合征"],"rank":3,"basic":{"define":"一种急性自限性全身中小血管炎，好发于 6 个月—5 岁儿童，主要累及冠状动脉，可致冠状动脉瘤、血栓与心肌梗死。典型表现为发热 ≥5 d 伴 5 项主要临床特征中的 ≥4 项；不完全川崎病需结合实验室与超声诊断。","risk":["年龄 6 个月—5 岁（高峰 1–2 岁），男孩多于女孩（1.5:1）","亚裔儿童（日本、韩国、中国发病率高）","既往川崎病或家族史","冬季与早春高发、感染后触发（病原尚未确定）","不完全型、<6 个月婴儿与 >5 岁儿童诊断困难、冠脉风险高"],"epi":"日本发病率最高（约 300–350/10 万 5 岁以下儿童），我国城市呈上升趋势，估计约 50–100/10 万。我国已成为儿童获得性心脏病首位病因，未治疗者约 20%–25% 发生冠状动脉瘤。"},"patho":"全身中等血管炎，以冠状动脉最易受累：血管内皮损伤、炎性细胞浸润与内膜增生，急性期冠状动脉壁水肿，2–4 周后出现冠状动脉扩张与动脉瘤。近年认为病原体经呼吸道入侵后触发异常免疫激活（IL-1β、TNF-α 等），在遗传易感儿童中引起血管炎。冠脉瘤可血栓形成致心肌缺血。","dx":{"criteria":["发热 ≥5 d（可不完全退热，对抗生素无效）+ 以下 5 项中 ≥4 项：①双侧球结膜充血无渗出；②口唇与口腔改变（口唇红裂、草莓舌、咽部充血）；③手足急性期红肿、2–3 周后指端膜状脱皮；④多形性皮疹（躯干为主、非水疱性）；⑤颈部淋巴结肿大（≥1.5 cm，单侧）","不完全（非典型）川崎病：发热 ≥5 d 且主要表现 <4 项，婴儿（尤其 <6 个月）可出现肛周脱皮、卡介苗接种处红斑、无菌性脓尿","实验室支持：CRP ≥30 mg/L、ESR ≥40 mm/h、白细胞 ≥15×10⁹/L、贫血、血小板 ≥450×10⁹/L（第 2 周后）、ALT 升高、白蛋白 ≤30 g/L、尿白细胞增多","超声心动图：冠状动脉扩张（Z 值 ≥2.5）或动脉瘤（Z 值 ≥3 或 ≥4）","需排除猩红热、麻疹、腺病毒感染、多形红斑、系统性幼年特发性关节炎等"],"workup":["血常规（白细胞、血小板）、CRP、ESR、肝功能、白蛋白、电解质","尿常规（无菌性脓尿）、血培养（排除脓毒症）、病毒抗体/核酸（腺病毒、EBV）","超声心动图（基线，发病 10 d 内必须做；随访 2 周、6–8 周、6–12 个月）","心电图与肌钙蛋白（心肌受累评估）","ASO/咽拭子培养（猩红热鉴别）","冠脉 Z 值计算（按体表面积）"],"grading":"临床分型：典型/不完全川崎病；冠脉分级（AHA 2017）：无受累（Z <2）、仅扩张（Z 2–<2.5）、小动脉瘤（Z ≥2.5–<5）、中动脉瘤（Z ≥5–<10，或绝对值 <8 mm）、巨大动脉瘤（Z ≥10 或绝对值 ≥8 mm）。"},"ddx":[{"name":"毛细支气管炎（ped_bronchiolitis）","point":"与本类 ped_bronchiolitis 的鉴别点：川崎病发热持续 ≥5 d 伴黏膜皮肤改变、CRP 显著升高与冠脉病变；毛细支气管炎以喘息与呼吸增快为主，2 岁以下。"},{"name":"儿童哮喘（ped_asthma）","point":"与本类 ped_asthma 的鉴别点：哮喘以反复喘息、肺功能可逆为主，无持续高热与黏膜皮肤改变；川崎病不伴气道痉挛与喘息。"},{"name":"猩红热","point":"A 组链球菌所致，发热伴咽峡炎、草莓舌与全身弥漫性红斑，抗感染治疗有效，ASO 与咽培养阳性，冠脉正常；川崎病对青霉素无效、唇红皲裂明显。"},{"name":"腺病毒感染、麻疹、幼儿急疹","point":"腺病毒可致高热结膜充血但无冠脉病变与血小板延迟升高；麻疹有 Koplik 斑与卡他期症状；幼儿急疹热退后出疹。"},{"name":"系统性幼年特发性关节炎（sJIA）、多形红斑、中毒性休克综合征","point":"sJIA 关节症状突出、发热呈间歇性，IL-1 拮抗剂有效；多形红斑有靶形皮疹与口唇糜烂；TSS 有低血压与弥漫性皮疹、血培养阳性。"}],"tx":{"drug":[{"name":"静脉注射免疫球蛋白（IVIG）","dose":"2 g/kg 单次静脉滴注（10–12 h 输注完成，最大一般按 100 g 计），发病 10 d 内使用最佳；可提前至第 5 天（发热 ≥5 d 且诊断确立）","note":"标准一线治疗，可使冠脉瘤风险从 20%–25% 降至约 5%；输注中监测血压、心率与过敏反应","renal":"肾功能不全者注意容量负荷与渗透性肾病","hepatic":"遵说明书","interact":"与减毒活疫苗需间隔 3 个月以上（麻疹疫苗需 11 个月）"},{"name":"阿司匹林","dose":"急性期：30–50 mg/kg/d 分 3–4 次口服（或 80–100 mg/kg/d，按机构方案），体温正常 48–72 h 后减至 3–5 mg/kg/d qd，继续 6–8 周；无冠脉受累者 6–8 周后可停用","note":"大剂量抗炎、小剂量抗血小板；勿与 IVIG 同时前 1 d 停用以避免加重（按机构方案）","renal":"肾功能不全减量","hepatic":"肝功能不全慎用","interact":"与布洛芬同用影响抗血小板作用；与抗凝药/NSAIDs 合用增加出血"},{"name":"英夫利西单抗（难治性川崎病）","dose":"5 mg/kg 单次静脉滴注（IVIG 无反应且持续发热者），必要时 2 周后重复","note":"用于 IVIG 抵抗（输注后 36 h 仍发热）者；需筛查结核（IGRA/胸片）与肝炎","renal":"遵说明书","hepatic":"活动性肝病禁用","interact":"与减毒活疫苗间隔；合并免疫抑制剂时感染风险增加"},{"name":"甲泼尼龙（IVIG 抵抗/高风险）","dose":"冲击 10–30 mg/kg/d 静脉 ×1–3 d，或 2 mg/kg/d 静滴；随后口服泼尼松 2 mg/kg/d 逐渐减量（4–6 周）","note":"用于 IVIG 无反应者或高危评分（Kobayashi 评分 ≥5）预测 IVIG 抵抗者，可与 IVIG 联合","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs 合用增加消化道出血；与利尿剂合用低钾"},{"name":"氯吡格雷/华法林（冠脉瘤抗栓）","dose":"氯吡格雷：>1 岁 1 mg/kg/d qd（最大 75 mg/d）；华法林：按 INR 目标 2.0–2.5（中/巨大动脉瘤），<1 岁需更高剂量及监测","note":"小/中动脉瘤阿司匹林+氯吡格雷；巨大动脉瘤或血栓时应考虑华法林或低分子肝素，需心血管专科管理","renal":"华法林肾功不全需更频繁监测 INR","hepatic":"严重肝病出血风险增加","interact":"氯吡格雷与奥美拉唑/埃索美拉唑合用可能降低活性；华法林与多种药物食物相互作用"},{"name":"双嘧达莫/依诺肝素（特殊方案）","dose":"依诺肝素 1 mg/kg 皮下注射 q12h（<2 个月 1.5 mg/kg q12h），监测抗 Xa 因子 0.5–1.0 IU/mL；用于婴幼儿巨大动脉瘤抗凝","note":"按心血管专科方案；需监测出血与肾功能","renal":"eGFR <30 减量","hepatic":"严重肝病慎用","interact":"与 NSAIDs、抗血小板药合用增加出血"}],"nonDrug":["确诊后尽早（发热 10 d 内）启动 IVIG+阿司匹林，延迟治疗增加冠脉瘤风险","IVIG 抵抗：再次 IVIG 2 g/kg 或糖皮质激素/英夫利西单抗，按机构流程","超声心动图全程监测：诊断时、IVIG 后 24–48 h、第 2 周、6–8 周、6–12 个月；冠脉瘤者更频繁","冠脉巨大动脉瘤需心血管外科评估（血栓、狭窄），必要时介入或搭桥","未诊断明确而持续发热 ≥5 d 的婴幼儿需重复超声与试验性治疗（按专科意见）","避免为减少发热而使用非甾体抗炎药（需阿司匹林抗血小板）"],"life":["阿司匹林治疗期间避免剧烈运动与接触性活动（出血风险）","冠脉瘤者避免高冲击运动，定期心内科随访与运动评估","呼吸道感染时警惕再发（部分患儿随访可出现类似症状）","IVIG 后 11 个月内接种麻疹疫苗需重新接种","长期随访：冠脉情况决定运动、妊娠与职业选择，成人期需心血管专科管理"]},"prog":"经 IVIG 治疗约 5% 发生冠状动脉瘤；未治疗者约 20%–25%，其中 1%–2% 发展为巨大动脉瘤。IVIG 抵抗（约 10%–20%）者冠脉风险更高。冠脉正常者在 6–8 周后可停药，但仍需 1 年、5 年随访；巨大动脉瘤可致心肌梗死，远期需长期抗栓。","refs":["中华医学会儿科学分会心血管学组. 川崎病诊断和急性期治疗专家共识（2022）","AHA Scientific Statement: Diagnosis, Treatment, and Long-Term Management of Kawasaki Disease (2017)","日本川崎病学会. 川崎病诊断指南（第 6 版，2020）","RAISE study: Kobayashi score and IVIG resistance (2012)"]}]},{"id":"neonatal","name":"新生儿疾病","rank":5,"summary":"新生儿问题的核心是「按日龄与体重定剂量、按小时龄定干预窗口」：NRDS 靠产前激素与出生后肺表面活性物质，HIE 的亚低温必须在生后 6 小时内启动。","compare":[{"diseaseId":"ped_nrds","dx":"早产儿生后数小时内进行性呼吸困难、呻吟、三凹征，胸片见磨玻璃样改变与支气管充气征","key":"早产 + 进行性呼吸窘迫 + 胸片磨玻璃影，肺表面活性物质有效"},{"diseaseId":"ped_asphyxia","dx":"Apgar 低分、脐动脉血气 pH <7.0 或 BE ≤−12 mmol/L，生后出现意识与肌张力异常、惊厥","key":"有明确围生期窒息史 + 多器官受累，亚低温窗口 6 小时内"},{"diseaseId":"ped_nnj_hemo","dx":"母子血型不合，生后 24 小时内出现黄疸并快速进展，Coombs 试验阳性，血红蛋白下降","key":"24 小时内出现黄疸 + 血型不合 + 溶血证据"},{"diseaseId":"ped_sepsis_neonatal","dx":"体温不稳、反应差、喂养困难、呼吸暂停，血培养阳性；早发型 ≤72 小时、晚发型 >72 小时","key":"非特异性症状为主，血培养是金标准，需按日龄调剂量"}],"diseases":[{"id":"ped_nrds","name":"新生儿呼吸窘迫综合征","aka":["Neonatal Respiratory Distress Syndrome","NRDS","肺透明膜病","HMD"],"rank":1,"basic":{"define":"因肺表面活性物质（PS）缺乏导致的进行性肺泡萎陷与呼吸窘迫，主要见于早产儿，胎龄越小发生率越高，是早产儿死亡与并发症的主要原因之一。","risk":["早产（最主要：<28 周发生率约 60%–80%，32–34 周约 15%–25%）","母亲糖尿病（胎儿高胰岛素抑制 PS 合成）","剖宫产未临产（缺乏应激性儿茶酚胺释放）","围生期窒息、宫内感染","多胎、Rh 血型不合、男婴"],"epi":"我国早产儿中 NRDS 发生率约 5%–10%，<32 周早产儿可达 30%–50%。随产前糖皮质激素规范使用与 PS 普及，病死率已显著下降。"},"patho":"肺表面活性物质由 II 型肺泡上皮细胞合成，主要成分为磷脂酰胆碱与表面活性蛋白（SP-A/B/C/D），作用是降低肺泡表面张力、防止呼气末肺泡萎陷。PS 缺乏时肺泡在呼气末大量萎陷，功能残气量下降，形成肺内右向左分流与通气/血流比例失调，导致低氧血症与二氧化碳潴留；同时因肺泡反复开放-萎陷造成气压伤与炎性介质释放，可进展为支气管肺发育不良（BPD）。病理上见透明膜形成（渗出性纤维蛋白沉积于肺泡壁），故旧称肺透明膜病。","dx":{"criteria":["早产儿（尤其 <34 周）生后 6 小时内出现进行性呼吸困难：呼吸急促（>60 次/分）、呻吟、鼻扇、三凹征、发绀","胸片（生后 6–12 小时最典型）：I 级为细颗粒状磨玻璃影；II 级见支气管充气征（air bronchogram）；III 级心影与膈肌轮廓模糊；IV 级呈「白肺」","血气：低氧血症，早期 PaCO₂ 可正常或偏低（过度通气），后期升高；需排除其他原因","肺部超声（近年首选床旁）：见「白肺」、双肺点消失、胸膜线异常与 A 线消失","注意与 B 组链球菌肺炎、胎粪吸入综合征、暂时性呼吸增快（TTN）鉴别"],"workup":["生后即刻：血糖、血气、血常规、CRP、血培养（排除感染）","胸片或床旁肺超声（诊断与分级）","监测经皮血氧饱和度（目标 SpO₂ 90%–95%，早产儿避免高氧）与经皮二氧化碳","心脏超声：排除先天性心脏病与持续性肺动脉高压（PPHN）","产前评估：羊水磷脂酰甘油或 L/S 比值（已少用）；胃液振荡试验（泡沫试验）辅助判断 PS 成熟度"],"grading":"胸片分 I–IV 级（见诊断标准）；临床按是否需要机械通气分为轻（仅需 CPAP）与重（需气管插管与 PS 治疗）。"},"ddx":[{"name":"新生儿败血症与 B 组链球菌肺炎（ped_sepsis_neonatal）","point":"与新生儿败血症的鉴别：GBS 肺炎胸片可类似 NRDS，但常有母亲发热、胎膜早破 ≥18 小时、生后早期即出现休克与 CRP 升高，血培养阳性；NRDS 以早产为主要背景、感染指标通常不高。"},{"name":"新生儿窒息与 HIE（ped_asphyxia）","point":"与 HIE 的鉴别：HIE 有明确窒息史与 Apgar 低分，表现为多器官受累（肾、心、肝）与神经系统异常；NRDS 以呼吸系统表现为主，无持续性神经系统异常。"},{"name":"胎粪吸入综合征","point":"多见于足月或过期产、有羊水胎粪污染史，胸片见斑片状浸润、肺过度充气与气漏，PS 治疗反应不如 NRDS。"},{"name":"新生儿暂时性呼吸增快（TTN）","point":"多见于剖宫产足月儿，生后数小时呼吸急促但 24–72 小时自行缓解，胸片见叶间裂积液与肺门血管纹理增粗，无需 PS。"},{"name":"持续性肺动脉高压（PPHN）","point":"严重低氧血症与导管前后血氧差 >5%，心脏超声见右向左分流与肺动脉压升高，需 iNO。"}],"tx":{"drug":[{"name":"猪肺磷脂注射液（肺表面活性物质）","dose":"首剂 100–200 mg/kg（2.5–5 mL/kg）气管内滴入，必要时 6–12 小时后重复 100 mg/kg，最多 3–4 次；给药前尽量吸净气道分泌物，分左右侧卧位各半量","note":"确诊或高度怀疑即应早期给药（INSURE 技术：插管-注药-拔管后 CPAP）；给药期间可能出现短暂血氧下降、心动过缓、肺出血","renal":"无需调整","hepatic":"无需调整","interact":"给药通路勿与其他药物同用；避免与吸痰同时进行"},{"name":"产前地塞米松（母亲用药）","dose":"母亲 24 周–34 周有早产风险时：地塞米松 6 mg 肌注 q12h×4 次；或倍他米松 12 mg 肌注 q24h×2 次","note":"是降低 NRDS 发生率与严重度最有效的措施；34–36 周且 7 天内可能分娩者可考虑（证据较弱）；糖尿病母亲需加强血糖监测","renal":"遵说明书","hepatic":"遵说明书","interact":"母亲使用可升高血糖；与保胎药（利托君）合用可致肺水肿"},{"name":"咖啡因枸橼酸盐","dose":"负荷量 20 mg/kg 静脉/口服，24 小时后维持 5–10 mg/kg qd","note":"用于早产儿呼吸暂停与拔管前，可减少 BPD 与拔管失败；心率 >180 次/分时减量","renal":"无需调整","hepatic":"重度肝损害减量","interact":"与茶碱类不宜同用；可增强 β 激动剂的心率效应"},{"name":"注射用青霉素 / 氨苄西林（排除感染时）","dose":"经验性抗感染：氨苄西林 50 mg/kg q12h（日龄 ≤7 天）或 q8h（>7 天）静脉滴注 + 庆大霉素 4–5 mg/kg q24h–q48h","note":"NRDS 与 GBS 肺炎难以鉴别时应先经验性用药，血培养 48–72 小时阴性可停","renal":"庆大霉素按胎龄与肾功能延长间隔并监测血药浓度","hepatic":"无需调整","interact":"氨苄西林与氨基糖苷类同瓶混合可致失活，需分开输注"}],"nonDrug":["无创通气：CPAP 5–8 cmH₂O 是 NRDS 首选初始呼吸支持（避免气管插管）","机械通气：CPAP 失败或 FiO₂ >0.4 时考虑，采用肺保护策略（潮气量 4–6 mL/kg、适当 PEEP 5–6 cmH₂O）","目标氧合：早产儿 SpO₂ 90%–95%，PaO₂ 50–80 mmHg，避免高氧（视网膜病变风险）","保温与液体管理：暖箱中性温度、限制液量（早期 60–80 mL/kg/d 起）以防肺水肿与 PDA","INSURE 技术（插管-给 PS-快速拔管至 CPAP）可减少机械通气时间"],"life":["出院后随访：肺功能与 BPD 评估、视网膜病变（ROP）筛查（生后 4–6 周或矫正胎龄 31–32 周起）","听力筛查与神经发育随访（矫正月龄 6、12、24 个月）","家长教育：识别呼吸增快、喂养困难与发绀等复发征象","避免被动吸烟与呼吸道感染，按计划接种（早产儿按实际月龄接种）"]},"prog":"规范 PS 与无创通气下，<32 周 NRDS 存活率 >90%。主要并发症为 BPD（约 20%–30% 极早产儿）、PDA、ROP、颅内出血与坏死性小肠结肠炎。存活者多数神经发育结局良好，但极早产儿运动与认知落后风险仍升高。","refs":["《新生儿呼吸窘迫综合征诊断和治疗专家共识》（中华医学会儿科学分会新生儿学组，2018）","《早产儿支气管肺发育不良临床诊疗指南》（中华医学会儿科学分会，2023）","2019 European Consensus Guidelines on the Management of RDS (updated 2019/2022)","《中国新生儿复苏指南（2021）》"]},{"id":"ped_asphyxia","name":"新生儿窒息与缺氧缺血性脑病","aka":["Neonatal Asphyxia","Hypoxic-Ischemic Encephalopathy","HIE"],"rank":2,"basic":{"define":"新生儿窒息指生后不能建立正常呼吸循环导致低氧血症与代谢性酸中毒；缺氧缺血性脑病（HIE）是窒息后最严重的中枢神经系统并发症，以意识障碍、肌张力异常与惊厥为特征，是新生儿死亡与远期神经残疾（脑瘫、智力低下）的主要原因。","risk":["母亲因素：妊娠期高血压、糖尿病、胎盘早剥、前置胎盘、严重贫血、感染","分娩因素：产程延长、产钳/胎吸助产、肩难产、脐带脱垂或绕颈、胎位异常","胎儿因素：早产、巨大儿、宫内生长受限、先天畸形","急产、子宫破裂、严重胎心率异常（晚期减速、变异缺失）"],"epi":"我国新生儿窒息发生率约 3%–10%，其中 HIE 发生率约 1‰–2‰ 活产儿；中重度 HIE 中约 25%–30% 遗留神经发育障碍。"},"patho":"窒息早期为缺氧性损伤，随后再灌注引起继发性能量衰竭与细胞毒性水肿。核心机制：ATP 消耗致 Na⁺/K⁺-ATP 酶失能（细胞肿胀）、Ca²⁺ 内流激活蛋白酶与磷脂酶、兴奋性氨基酸（谷氨酸）释放致兴奋性毒性、自由基与炎性因子产生、迟发性细胞死亡（发生于生后 6–48 小时，是亚低温治疗的靶窗口）。未成熟脑以基底节、丘脑、脑干与脑白质受累为主，足月儿多见基底节丘脑与分水岭区损伤。","dx":{"criteria":["必须有明确的围生期窒息证据（三条同时具备）：① 脐动脉血气 pH <7.0 或 BE ≤−12 mmol/L；② Apgar 评分 1 分钟 ≤3 分且 5 分钟 ≤5 分（或需正压通气 >10 分钟）；③ 生后立即出现多器官功能损害（肾、心、肝、肺、凝血）","神经系统表现（Sarnat 分级）：轻度——过度警觉、肌张力正常或稍高、反射活跃、无惊厥；中度——嗜睡、肌张力低下、原始反射减弱、惊厥、自主神经功能障碍；重度——昏迷、肌张力松软、原始反射消失、频繁惊厥、脑干功能受累","评估需在生后 12–24 小时内完成，并在 72 小时内动态复查","排除其他原因：先天代谢病、颅内感染、遗传性脑病、新生儿肌病"],"workup":["脐动脉血气（最客观的窒息证据）、Apgar 评分、首次血气","aEEG（振幅整合脑电图）或常规 EEG：重症监护下的连续脑电监测，背景抑制或惊厥是关键判断依据","头颅超声（经前囟）：早期见脑水肿（脑实质回声增强、脑沟变浅），后期见基底节损伤与囊性变","头颅 MRI（生后 4–10 天为最佳窗口）：DWI 见基底节、丘脑、内囊后肢或分水岭区弥散受限，是评估损伤部位与预后的金标准","多器官评估：肾功能（尿量、肌酐）、心肌酶与心电图、肝功能、凝血、血糖与电解质","听力与视觉诱发电位（急性期后可做）"],"grading":"Sarnat 分级（轻/中/重），中重度是亚低温治疗指征。影像学按损伤模式分：基底节-丘脑型（重度窒息，预后差）、分水岭型（部分窒息，预后相对好）、弥漫型。"},"ddx":[{"name":"新生儿呼吸窘迫综合征（ped_nrds）","point":"与 NRDS 的鉴别：NRDS 以早产为背景、呼吸窘迫为主、无乏氧缺血的多器官损害，不伴持续神经系统异常与惊厥；HIE 有明确窒息证据与神经系统表现。"},{"name":"新生儿败血症与化脓性脑膜炎（ped_sepsis_neonatal）","point":"与败血症/脑膜炎的鉴别：感染常有母亲发热、胎膜早破、CRP 与 PCT 升高、血/脑脊液培养阳性；HIE 感染指标通常正常，但两者可并存，需常规排除。"},{"name":"先天性代谢病","point":"生后数天出现喂养困难、呕吐、酸中毒、高氨血症，无窒息史，血氨基酸与尿有机酸分析可确诊。"},{"name":"先天性心脏病","point":"发绀型先心病（如 TGA）可表现为低氧，但心脏超声见结构异常，无窒息与多器官受损。"},{"name":"新生儿惊厥的其他原因","point":"低钙、低血糖、低钠、维生素 B6 依赖、遗传性癫痫，需生化与脑电检查鉴别。"},{"name":"新生儿溶血病（ped_nnj_hemo）","point":"严重高血压红素可致胆红素脑病（核黄疸），表现为肌张力增高与角弓反张，但无窒息史，胆红素显著升高。"}],"tx":{"drug":[{"name":"亚低温治疗（全身或选择性头部降温）","dose":"目标体温 33.5–34.5 ℃（直肠），持续 72 小时，随后 6–8 小时内缓慢复温；必须在生后 6 小时内启动（越早越好）","note":"中重度 HIE 唯一有循证依据的神经保护治疗，可降低死亡与重度残疾风险（NNT 约 7–9）；实施需具备监护条件，避免心动过缓与凝血障碍","renal":"无","hepatic":"无","interact":"降温期间药物代谢减慢，镇静与抗癫痫药需调整剂量"},{"name":"苯巴比妥（惊厥控制）","dose":"负荷量 20 mg/kg 静脉缓慢推注（>20 分钟），必要时追加 10 mg/kg 至总量 40 mg/kg；维持 3–5 mg/kg/d","note":"一线抗惊厥；负荷后需监测呼吸抑制与低血压；亚低温期间清除减慢需减量","renal":"肾功能不全时延长间隔","hepatic":"肝病者减量","interact":"与苯二氮卓类合用增加呼吸抑制；诱导 CYP3A4 降低多种药物浓度"},{"name":"左乙拉西坦（替代或联合）","dose":"20–40 mg/kg 静脉/口服负荷，维持 10–30 mg/kg q12h","note":"不良反应较苯巴比妥少，可作为二线或替代；肾功能不全需按 CrCl 调整","renal":"CrCl <50 减量，<30 延长间隔","hepatic":"重度肝损害需减量","interact":"与苯二氮卓类有协同镇静"},{"name":"葡萄糖（低血糖纠正）","dose":"10% 葡萄糖 2 mL/kg 静脉推注，随后维持 4–6 mg/kg/min 输注（目标血糖 4–6 mmol/L）","note":"窒息患儿易发生低血糖，需在入院即刻测血糖；避免快速大剂量推注高渗糖（加重渗透性损伤）","renal":"无","hepatic":"无","interact":"无"},{"name":"多巴胺（低血压或心功能不全）","dose":"5–10 µg/kg/min 静脉泵入，按血压滴定，最大 20 µg/kg/min","note":"窒息后心肌受损与血管麻痹常见，需维持 MAP 在胎龄对应值以上以保证脑灌注；注意心动过速与外渗坏死","renal":"无","hepatic":"无","interact":"与 β 阻滞剂作用拮抗；MAO 抑制剂显著增强作用"},{"name":"甘露醇（脑水肿，慎用）","dose":"0.25–0.5 g/kg 静脉快速滴注 q6–8h，仅用于明确颅内高压征象时","note":"HIE 常规不推荐脱水治疗；仅在出现颅内高压临床征象时短期使用，并监测渗透压与尿量","renal":"少尿/无尿时禁用或减量","hepatic":"无","interact":"与肾毒性药物合用增加肾损伤风险"}],"nonDrug":["复苏：严格执行《中国新生儿复苏指南》，按 ABC 顺序，正压通气与胸外按压（3:1 比例）","保温与氧疗：避免低体温与高氧血症（多数 HIE 复苏后不主张吸入高浓度氧）","严格液体与电解质管理：限制液量（首日 40–60 mL/kg）以防脑水肿与心衰，监测尿量","呼吸支持：常需机械通气，目标 PaCO₂ 35–45 mmHg（避免过度通气致脑血流下降）","亚低温治疗需在有资质的 NICU 中心进行，转运前可先行被动降温"],"life":["出院后长期神经发育随访：运动（脑瘫筛查）、认知、语言、视听功能，至少至学龄期","康复干预：早期物理治疗、作业治疗与语言训练，6 个月内开始效果更好","抗癫痫药需在神经专科随访下逐渐减停（通常惊厥控制后 6–12 个月、脑电正常）","家庭支持与家长教育：喂养、体位管理与并发症预防（误吸、压疮）","生后 1 个月内完成听力筛查与眼底检查"]},"prog":"轻度 HIE 预后良好（>95% 无后遗症）；中度未治疗者约 20%–30% 遗留残疾，亚低温治疗后降至约 15%–20%；重度者病死率约 25%–50%，存活者中约 60%–80% 有严重神经发育障碍。基底节-丘脑损伤、持续惊厥、aEEG 背景抑制与喂养困难是预后不良的预测因素。","refs":["《新生儿缺氧缺血性脑病诊断标准》（中华医学会儿科学分会新生儿学组，2005）及后续修订","《中国新生儿复苏指南（2021 年修订版）》","2014 ACOG Task Force on Neonatal Encephalopathy and Cerebral Palsy","2018/2022 Cochrane Review: Hypothermia for newborns with hypoxic-ischaemic encephalopathy","《新生儿惊厥诊断与治疗专家共识》（中华医学会儿科学分会，2019）"]},{"id":"ped_nnj_hemo","name":"新生儿溶血病与新生儿贫血","aka":["Hemolytic Disease of the Newborn","HDN","新生儿高胆红素血症"],"rank":3,"basic":{"define":"新生儿溶血病指母子血型不合导致母体抗体经胎盘进入胎儿循环，破坏胎儿红细胞引起的溶血性贫血与黄疸，最常见为 ABO 血型不合（约占 85%）与 Rh 血型不合。新生儿贫血指生后 2 周内静脉血血红蛋白 <145 g/L（或毛细血管血 <130 g/L），可分为失血性、溶血性与生成不足三类。","risk":["母亲 O 型、胎儿 A 型或 B 型（ABO 溶血）","Rh 阴性母亲孕育 Rh 阳性胎儿（第二胎风险高）","既往有新生儿黄疸需光疗或换血史","G6PD 缺乏（我国南方高发，可致严重黄疸）","早产、双胎输血综合征、胎母输血、脐带异常致失血"],"epi":"ABO 血型不合约占妊娠的 15%–20%，但仅约 10% 发生临床可见的溶血病；Rh 溶血在未做产前预防地区发生率约 1/1000 活产。我国南方 G6PD 缺乏症患病率约 3%–8%（广东、广西）。"},"patho":"母体产生的 IgG 类血型抗体通过胎盘进入胎儿循环，与胎儿红细胞表面抗原结合，在网状内皮系统被巨噬细胞吞噬破坏（血管外溶血），导致贫血、黄疸与髓外造血（肝脾肿大）。溶血产生大量未结合胆红素，新生儿肝酶（UGT1A1）活性低、白蛋白结合能力有限、血脑屏障未成熟，游离胆红素可沉积于基底节与脑干核团，造成胆红素脑病（核黄疸）。Rh 溶血因抗体持久、可影响后续妊娠，且贫血程度通常重于 ABO 溶血。","dx":{"criteria":["黄疸出现早（ABO 溶血常在生后 24–48 小时，Rh 溶血可在 24 小时内）且进展快，血清总胆红素上升速度 >5 mg/dL/d（>85 µmol/L/d）","母子血型不合且有溶血证据：Coombs 试验（直接抗人球蛋白试验）阳性（ABO 溶血可为弱阳性或阴性，Rh 溶血多为强阳性）","血红蛋白下降、网织红细胞升高（>6%）、外周血见有核红细胞增多、球形红细胞","出生时脐血 Hb <14 g/dL 或脐血胆红素 >4 mg/dL 提示溶血严重","黄疸干预阈值按小时龄、胎龄与危险因素对照 AAP 列线图（≥35 周）或早产儿专用曲线","新生儿贫血诊断：生后 2 周内静脉血 Hb <145 g/L（毛细血管血 <130 g/L）；生后 2–4 周 <100 g/L 为显著贫血"],"workup":["母子血型（ABO 与 Rh）、直接抗人球蛋白试验（DAT）、抗体释放试验","血常规（Hb、Hct、网织红细胞、有核红细胞）、外周血涂片","血清总胆红素与直接胆红素：判断是否需要光疗或换血；经皮胆红素仅用于筛查","G6PD 活性测定（尤其南方人群与不明原因严重黄疸）","血型抗体效价（Rh 溶血母亲监测）与产前超声（胎儿贫血评估，MCA 收缩期峰值流速）","疑失血性者：头颅超声、腹部超声、母血涂片查胎儿红细胞（Kleihauer-Betke 试验）"],"grading":"黄疸按小时龄胆红素的百分位与危险因素分区：低危、中低危、中高危、高危（对应观察、光疗、换血阈值）；新生儿贫血按 Hb 分轻（90–120 g/L）、中（60–90 g/L）、重（<60 g/L）。"},"ddx":[{"name":"新生儿呼吸窘迫综合征（ped_nrds）","point":"与 NRDS 的鉴别：NRDS 以呼吸窘迫与早产为特征，无血型不合与溶血指标异常；严重贫血本身可致呼吸急促，但血红蛋白与网织红细胞可鉴别。"},{"name":"新生儿窒息与 HIE（ped_asphyxia）","point":"与 HIE 的鉴别：窒息患儿可有红蛋白升高（血液浓缩）与多器官受损，无血型不合；HIE 的神经系统表现（意识与肌张力异常）在严重黄疸中提示胆红素脑病时需特别区分——胆红素脑病有胆红素显著升高。"},{"name":"新生儿败血症（ped_sepsis_neonatal）","point":"感染可抑制肝酶并加重黄疸，同时引起贫血（DIC 或骨髓抑制），但感染指标升高、血培养阳性，无血型不合。"},{"name":"母乳性黄疸","point":"生后 1 周后出现、进展慢、婴儿一般情况好，无溶血证据与贫血。"},{"name":"先天性胆道闭锁","point":"以直接胆红素升高为主（>1 mg/dL 或 >20% 总胆红素），大便灰白，需早诊（60 天内 Kasai 手术）。"},{"name":"遗传性球形红细胞增多症","point":"家族史、球形红细胞增多、渗透脆性增高，Coombs 阴性。"}],"tx":{"drug":[{"name":"抗-D 免疫球蛋白（产前/产后预防）","dose":"产前：孕 28 周 300 µg 肌注；产后：Rh 阴性未致敏母亲分娩 Rh 阳性婴儿后 72 小时内 300 µg 肌注","note":"是预防 Rh 溶血的基石，使发生率降至约 0.1%；需在流产、羊膜腔穿刺、产前出血等可能致敏的事件后 72 小时内补注","renal":"无","hepatic":"无","interact":"无特殊"},{"name":"注射用免疫球蛋白（IVIG）","dose":"用于同种免疫性溶血且胆红素接近换血阈值者：0.5–1 g/kg 静脉滴注，必要时 12 小时后重复","note":"可减少换血需求，但不能替代光疗；Rh 溶血效果优于 ABO；需在光疗基础上使用","renal":"肾功能不全慎用（含蔗糖制剂可致渗透性肾病）","hepatic":"无","interact":"活疫苗接种需推迟（被动抗体干扰）"},{"name":"重组人促红细胞生成素（EPO，早产儿贫血）","dose":"200–300 IU/kg 皮下，每周 3 次；或 750–1000 IU/kg 每周 1 次（遵说明书）","note":"用于早产儿贫血预防与治疗，需保证铁剂充足；Hb <70 g/L（有症状）或 <60 g/L（无症状）考虑输血","renal":"无","hepatic":"无","interact":"无特殊"},{"name":"铁剂（营养性/恢复期贫血）","dose":"元素铁 3–6 mg/kg/d 口服，分 1–2 次，餐间服用；疗程至 Hb 正常后 6–8 周补足储备","note":"早产儿生后 2–4 周起预防性补铁 2–4 mg/kg/d；与维生素 C 同服促进吸收，与奶同服影响吸收","renal":"无","hepatic":"无","interact":"与抗酸药、钙剂、茶同服降低吸收；过量可致中毒（儿童误服 20 mg/kg 元素铁即可中毒）"},{"name":"苯巴比妥（诱导肝酶，限用）","dose":"5 mg/kg/d 分 2 次，连用 3–5 天","note":"仅用于肝酶成熟延迟所致黄疸，起效需 3–5 天，不是急性严重黄疸的解决办法；不推荐常规使用","renal":"减量","hepatic":"肝病慎用","interact":"镇静、呼吸抑制；诱导多种药物代谢"}],"nonDrug":["光疗：按小时龄胆红素阈值启动（AAP 2022 列线图）；双面 LED 蓝光（460–490 nm）效果最佳，需遮蔽眼睛与会阴，监测体温、液体与体重","换血治疗：达换血阈值（通常为光疗阈值的两倍或出现急性胆红素脑病征象）时进行；双倍血量换血（160–180 mL/kg）可移除抗体与胆红素","严重胎儿贫血：宫内输血（MCA-PSV >1.5 MoM 时评估）","早产儿贫血：限制采血量、延迟脐带结扎（60–90 秒）可减少输血需求","强化喂养与保证液体入量（光疗期间不显性失水增加 20%–30%）"],"life":["生后 24 小时内出现黄疸必须查血清胆红素并住院观察","出院前评估黄疸风险，48–72 小时复查经皮或血清胆红素（尤其 ABO 不合与 G6PD 缺乏者）","家长教育：识别嗜睡、喂养差、肌张力改变（胆红素脑病预警）立即就医","Rh 阴性母亲应知晓后续妊娠需监测抗体效价","G6PD 缺乏者避免接触樟脑丸、蚕豆与氧化性药物（磺胺、呋喃类、抗疟药）"]},"prog":"ABO 溶血通常较轻，光疗即可控制，预后良好；Rh 溶血较重，未干预者可致死或遗留胆红素脑病后遗症（手足徐动、高频听力丧失、上视麻痹、牙釉质发育不良）。规范产前抗-D 预防与生后光疗/换血后，良好结局率 >95%。早产儿贫血多在生后 4–8 周达最低点，随后自行恢复。","refs":["《新生儿高胆红素血症诊断和治疗专家共识》（中华医学会儿科学分会新生儿学组，2014）","《新生儿溶血病诊疗专家共识》（中华医学会儿科学分会，2015）","2022 AAP Clinical Practice Guideline Revision: Management of Hyperbilirubinemia in the Newborn Infant ≥35 Weeks' Gestation","2019 NICE Guideline: Jaundice in newborn babies under 28 days","《中国输血技术操作规程（新生儿换血部分）》"]},{"id":"ped_sepsis_neonatal","name":"新生儿败血症","aka":["Neonatal Sepsis","早发型败血症","EOS","晚发型败血症","LOS"],"rank":4,"basic":{"define":"新生儿期病原体（细菌、真菌、病毒）侵入血液循环并在其中繁殖、产生毒素所致的全身性感染。按发病时间分早发型（生后 ≤72 小时或 ≤7 天，多为母婴垂直传播）与晚发型（>72 小时或 >7 天，多为院内感染或社区获得，常伴脑膜炎）。","risk":["早发型：母亲绒毛膜羊膜炎（发热 ≥38 ℃、胎膜早破 ≥18 小时、羊水臭味）、产道 B 组链球菌定植、母亲尿路感染、早产（<37 周）与低出生体重","晚发型：早产与低出生体重（尤其 <1500 g）、中心静脉导管、机械通气、长期静脉营养、广谱抗生素使用、肠外营养","其他：侵入性操作、坏死性小肠结肠炎（NEC）、免疫缺陷"],"epi":"我国新生儿早发型败血症发生率约 0.5–3‰ 活产儿，极低出生体重儿晚发型败血症发生率可达 20%–30%。革兰阴性杆菌（大肠埃希菌、克雷伯菌）与凝固酶阴性葡萄球菌（CoNS，晚发型多见）为主要病原。"},"patho":"新生儿免疫系统不成熟（IgG 依赖母源转移、补体活性低、中性粒细胞储备与功能不足、树突状细胞功能弱）使感染易播散。病原体相关分子模式激活 TLR 后释放 TNF-α、IL-1β、IL-6 等细胞因子，导致全身血管扩张、毛细血管渗漏与心肌抑制（脓毒性休克）；同时激活凝血系统致 DIC 与出血。早发型因病原来自产道与羊水，以肺炎为常见首发表现；晚发型常以导管相关血流感染与脑膜炎为主。","dx":{"criteria":["临床表现非特异：体温不稳（发热或低体温）、反应差、喂养困难、吸吮无力、呼吸暂停或呼吸窘迫、皮肤花色或脓疱、黄疸加重、腹胀与呕吐、惊厥","血培养是金标准：需两管不同部位血培养，每管至少 1 mL（儿童瓶），已用抗生素者应延长孵育或使用抗菌药物吸附瓶","炎症指标：CRP（生后 6–12 小时开始升高，24–48 小时高峰）与 PCT（生后 24–48 小时生理高峰，此后升高提示感染）；CRP 反复正常可作为停药参考，但单次正常不能排除","有脑膜炎表现或血培养阳性应做腰穿（脑脊液白细胞、蛋白、糖、涂片与培养）；早发型败血症中脑膜炎比例可达 10%–20%","自细胞计数与分类：早期白细胞减少（<5×10⁹/L）或不成熟中性粒细胞比例（I/T >0.2）提示感染"],"workup":["血培养（两管）、尿常规与尿培养（晚发型必查）、脑脊液检查（疑脑膜炎）","血常规、CRP、PCT、血气、血糖、电解质、肝功能、凝血功能","胸片（早发型常合肺炎）与腹部超声（疑 NEC 时）","必要时查真菌（长期广谱抗生素与静脉营养者）与病毒（HSV、肠道病毒、巨细胞病毒）","寻找感染灶：脐部、皮肤、口腔黏膜、导管入口、眼底"],"grading":"按发病时间分早发型（≤72 小时）与晚发型（>72 小时）；按临床表现与循环状态分脓毒症与脓毒性休克（需升压药并伴乳酸升高与灌注不良）。"},"ddx":[{"name":"新生儿呼吸窘迫综合征（ped_nrds）","point":"与 NRDS 的鉴别：NRDS 以早产与进行性呼吸窘迫为特征、胸片磨玻璃影、PS 有效、感染指标正常；GBS 肺炎可酷似 NRDS，需血培养与母亲病史鉴别。"},{"name":"新生儿窒息与 HIE（ped_asphyxia）","point":"与 HIE 的鉴别：HIE 有明确围生期窒息证据（脐血气 pH <7.0、Apgar 低分），表现为神经系统异常为主；败血症可有休克与多器官受损，但无窒息史且炎症指标升高。"},{"name":"新生儿溶血病（ped_nnj_hemo）","point":"与溶血病的鉴别：溶血病以黄疸与贫血为主，Coombs 阳性、血型不合，感染指标正常。"},{"name":"先天性代谢病","point":"以喂养困难、呕吐、酸中毒、高氨血症为表现，无感染灶，血氨与血/尿代谢筛查阳性。"},{"name":"坏死性小肠结肠炎（NEC）","point":"以腹胀、血便与喂养不耐受为主要表现，腹部 X 线见肠壁积气（pneumatosis），可继发败血症；两者可并存。"},{"name":"先天性感染（TORCH）","point":"巨细胞病毒、风疹、弓形虫等，有母亲感染史、生后见肝脾肿大、小头、视网膜病变与颅内钙化。"}],"tx":{"drug":[{"name":"氨苄西林（早发型经验性治疗）","dose":"50 mg/kg 静脉滴注 q12h（日龄 ≤7 天）、q8h（>7 天）；疑脑膜炎时加至 100 mg/kg q8h","note":"覆盖 B 组链球菌与李斯特菌；需与其他药物联合直到血培养结果","renal":"肾功能不全（少尿/无尿）延长间隔","hepatic":"无需调整","interact":"与氨基糖苷类同瓶混合可使后者失活，需分开输注"},{"name":"庆大霉素（早发型联合）","dose":"早产儿：4–5 mg/kg q24h–q48h；足月儿：4–5 mg/kg q24h；需监测血药浓度（谷浓度 <2 mg/L）","note":"与氨苄西林联合是早发型败血症标准经验方案；注意耳肾毒性，疗程通常 7–10 天","renal":"按肾功能延长间隔，监测血药浓度","hepatic":"无需调整","interact":"与呋塞米、万古霉素合用增加耳肾毒性；与神经肌肉阻滞剂合用可加重阻滞"},{"name":"抗生素升级：美罗培南（重症或院内感染）","dose":"20–40 mg/kg 静脉滴注 q8h（30 分钟以上），疑脑膜炎时 40 mg/kg q8h（疗程与剂量遵说明书）","note":"用于碳青霉烯敏感的重症感染或院内革兰阴性菌；需考虑碳青霉烯耐药风险，按当地药敏调整","renal":"CrCl <30 时延长间隔或减量","hepatic":"轻度无需调整","interact":"与丙戊酸钠合用显著降低后者血药浓度（可致癫痫失控）"},{"name":"万古霉素（晚发型/CoNS 感染）","dose":"15 mg/kg q12h–q24h（按日龄与体重调整），目标谷浓度 10–15 mg/L（重症 15–20 mg/L），需药物监测","note":"用于疑导管相关感染或 MRSA 定植者；单用不足以覆盖革兰阴性菌","renal":"严格按 CrCl 调整并监测血药浓度","hepatic":"无需调整","interact":"与氨基糖苷类、袢利尿剂合用增加耳肾毒性"},{"name":"氟康唑（真菌感染）","dose":"念珠菌血症：6–12 mg/kg/d，按体重与肾功能调整，疗程至血培养阴性后 14 天","note":"长期广谱抗生素 + 静脉营养的早产儿为高危；需眼部与心超筛查排除播散灶","renal":"CrCl <50 减量","hepatic":"肝毒性，需监测","interact":"与 CYP2C9 底物（苯妥英、华法林）合用升高后者浓度"},{"name":"多巴胺 / 去甲肾上腺素（脓毒性休克）","dose":"多巴胺 5–10 µg/kg/min 起始，按血压滴定；去甲肾上腺素 0.05–0.3 µg/kg/min","note":"目标 MAP 按胎龄对应值（生后 1 天约为胎龄週数 mmHg 的估计值）；液体复苏首剂 10 mL/kg（疑似心功能不全者分次缓慢推注）","renal":"无","hepatic":"无","interact":"多巴胺与 β 阻滞剂拮抗；与非选择性 MAO 抑制剂合用可致危象"},{"name":"静脉注射免疫球蛋白（IVIG，重症或早产儿）","dose":"0.5 g/kg 静脉滴注（必要时重复）","note":"证据有限，主要用于重症脓毒症与部分早产儿；新生儿无脾者预防方案另议","renal":"肾功能不全慎用","hepatic":"无","interact":"推迟活疫苗接种"}],"nonDrug":["呼吸循环支持：氧疗与机械通气、液体复苏（10–20 mL/kg 分次）、血管活性药物","感染源控制：拔除感染的导管与引流脓肿，处理 NEC（禁食、胃肠减压、抗生素）","保温与血糖管理：维持中性温度与血糖 4–6 mmol/L","早发型败血症：疑诊即治疗，血培养 48–72 小时阴性且临床稳定可在 36–48 小时停用抗生素（需结合 CRP 动态）","B 组链球菌定植母亲的产时抗生素预防（青霉素 G 首剂 500 万 U 静脉，后续 250 万 U q4h，直至分娩）"],"life":["出院后随访：生长发育、神经发育（疑脑膜炎者需听力筛查与头颅影像）","B 组链球菌脑膜炎存活者需监测神经发育后遗症（脑积水、听力丧失、癫痫）","早产儿出院后加强营养与免疫接种（按实际月龄接种）","家长教育：识别发热、喂养差、呼吸暂停与嗜睡等早期征象","院内感染预防：严格手卫生、导管管理与抗生素合理使用（抗菌药物管理计划）"]},"prog":"早发型败血症病死率约 10%–20%（极早产儿更高），晚发型约 5%–15%。并发症包括脑膜炎（约 30%–50% 存活者有神经发育后遗症）、脓毒性休克、DIC 与 NEC。早期识别、及时抗生素与器官支持显著改善结局；抗生素延迟 1 小时即可增加病死率。","refs":["《新生儿败血症诊断及治疗专家共识》（中华医学会儿科学分会新生儿学组，2019）","《新生儿B族链球菌感染诊断和治疗专家共识》（中华医学会儿科学分会新生儿学组，2021）","2021 NICE Guideline: Neonatal infection – antibiotics for prevention and treatment","2018 AAP/AHA/IDSA Management of Neonates With Suspected or Proven Early-Onset Bacterial Sepsis","《新生儿监护病房医院感染防控技术规范》"]}]},{"id":"ped_nutri","name":"营养与生长疾病","rank":6,"summary":"生长与营养问题靠「量」说话：贫血看血红蛋白与铁蛋白、佝偻病看血钙磷与碱性磷酸酶、矮小看身高曲线与年生长速率，所有补充剂必须按公斤体重计算。","compare":[{"diseaseId":"ped_ida","dx":"6 月龄后喂养以纯奶为主、嗜睡乏力面色苍白，Hb 低于年龄对应界值、MCV 小、血清铁蛋白 <12 µg/L","key":"小细胞低色素 + 铁蛋白降低，铁剂治疗后网织红细胞上升"},{"diseaseId":"ped_rickets","dx":"多汗、夜惊、枕秃、方颅、肋骨串珠、手足镯，血 25-(OH)D <30 nmol/L、碱性磷酸酶升高、骨端增宽","key":"骨龄滞后 + 25-(OH)D 降低 + 血磷低、ALP 高"},{"diseaseId":"ped_malnutrition","dx":"体重/身高或年龄别体重低于同年龄标准差，伴皮下脂肪减少、肌萎缩、免疫力下降","key":"按 WHO 分型（消瘦型/水肿型/混合型），以体重与身长比值评估程度"},{"diseaseId":"ped_short_stature","dx":"身高低于同性别同年龄第 3 百分位或 −2 SD，年生长速率 <5 cm/年（4–6 岁后）","key":"生长曲线持续低位伴速率下降，骨龄与靶身高评估决定是否需生长激素"},{"diseaseId":"ped_hsp","dx":"双下肢对称性可触及紫癜、腹痛、关节痛，30%–50% 出现血尿或蛋白尿","key":"紫癜 + 腹痛/关节痛/肾损害四联，血小板计数正常"}],"diseases":[{"id":"ped_ida","name":"营养性缺铁性贫血","aka":["Nutritional Iron Deficiency Anemia","IDA"],"rank":1,"basic":{"define":"因体内铁缺乏导致血红蛋白合成不足所致的小细胞低色素性贫血，是婴幼儿最常见的营养性贫血，6 月龄至 3 岁高发。","risk":["6 月龄后未及时添加富铁辅食，长期纯奶或母乳喂养未补铁","早产与低出生体重（铁储备少、需求大）","生长发育快（青春期也可高发）","慢性失血（牛奶蛋白过敏致肠道少量出血、钩虫感染、月经量多）","铁吸收障碍（慢性腹泻、乳糜泻、胃切除后）"],"epi":"我国 6 月龄–2 岁儿童 IDA 患病率约 10%–20%（欠发达地区可达 30%），青春期女孩约 5%–10%。WHO 估计全球 5 岁以下儿童贫血中约半数由缺铁引起。"},"patho":"铁是血红蛋白、肌红蛋白与多种酶的辅基。铁缺乏分三期：铁减少期（储存铁下降、铁蛋白降低而 Hb 正常）、红细胞生成缺铁期（转铁蛋白饱和度下降、红细胞内游离原卟啉升高）、缺铁性贫血期（Hb 下降，呈小细胞低色素）。铁缺乏不仅引起贫血，还影响神经递质合成与髓鞘化，可致注意力与认知发育受损（即使 Hb 正常时也存在）。","dx":{"criteria":["血红蛋白低于年龄界值（WHO/中国标准）：6 月–5 岁 <110 g/L；5–11 岁 <115 g/L；12–14 岁 <120 g/L；成年女性 <120 g/L、男性 <130 g/L","红细胞指数：MCV <80 fl、MCH <27 pg、MCHC <310 g/L（小细胞低色素）","血清铁蛋白 <12 µg/L（<5 岁）或 <15 µg/L（≥5 岁）提示铁储备耗尽（炎热症或感染时铁蛋白可升高，需结合 CRP）","转铁蛋白饱和度 <15%–16%，总铁结合力升高，血清铁降低","铁剂治疗试验：规范补铁 2–4 周后网织红细胞升高（>治疗前 2 倍）与 Hb 上升 ≥10 g/L，可回顾性支持诊断"],"workup":["血常规 + 网织红细胞 + 外周血涂片（中央淡染区扩大）","血清铁蛋白、血清铁、总铁结合力、转铁蛋白饱和度","CRP（排除炎症对铁蛋白的影响）","大便常规 + 隐血（查慢性失血）、粪寄生虫（流行区）","长期贫血不缓解者：血红蛋白电泳（排除地中海贫血）、骨髓铁染色（金标准，少用）、胃肠镜（疑消化道失血）"],"grading":"按 Hb 分度（WHO）：轻度——低于界值但 ≥90 g/L；中度 60–89 g/L；重度 30–59 g/L；极重度 <30 g/L。"},"ddx":[{"name":"维生素 D 缺乏性佝偻病（ped_rickets）","point":"与佝偻病的鉴别：佝偻病以骨骼改变为主（方颅、肋骨串珠、O/X 腿），血钙磷与维生素 D 异常但 Hb 可正常；两者常并存于营养不良儿童。"},{"name":"儿童营养不良（ped_malnutrition）","point":"与营养不良的鉴别：重度营养不良伴贫血多为混合性（铁、叶酸、蛋白同时缺乏），表现为正细胞或大细胞贫血；单纯 IDA 以小细胞低色素为主且体重多正常。"},{"name":"地中海贫血","point":"有家族史与地域性（南方），HbA2 升高或基因检测阳性，铁剂与铁蛋白正常或升高，网织红细胞升高，MCV 显著降低而 Hb 下降相对轻。"},{"name":"慢性病贫血","point":"有慢性感染、炎症或肿瘤背景，铁蛋白正常或升高、转铁蛋白饱和度降低，CRP/ESR 升高。"},{"name":"巨幼细胞性贫血","point":"由叶酸或 B12 缺乏引起，MCV 升高而非降低，中性粒细胞分叶过多。"},{"name":"溶血性贫血","point":"网织红细胞显著升高、间接胆红素升高、LDH 升高，Coombs 试验阳性或见球形红细胞。"}],"tx":{"drug":[{"name":"口服铁剂（硫酸亚铁 / 富马酸亚铁 / 蛋白琥珀酸铁）","dose":"元素铁 4–6 mg/kg/d，分 2–3 次，餐间口服（单次不超过 1–2 mg/kg 吸收更佳）；疗程至 Hb 正常后继续补 4–8 周以补足储备","note":"首选口服；与维生素 C 同服促进吸收；Hb <30 g/L 或伴心功能不全时先输血再补铁","renal":"无需调整","hepatic":"无需调整","interact":"与牛奶、茶、咖啡、钙剂、抗酸药同服降低吸收（间隔 2 小时）；与四环素类、喹诺酮类合用降低后者吸收"},{"name":"维生素 C","dose":"50–100 mg 与铁剂同服","note":"可将三价铁还原为二价铁，显著提高吸收率","renal":"大量（>2 g/d）慎用于肾功能不全者","hepatic":"无需调整","interact":"无特殊"},{"name":"右旋糖酐铁（静脉铁，极少用）","dose":"按缺铁量计算，遵说明书；仅供不能耐受口服或吸收障碍者","note":"儿童静脉铁需严格监护，有过敏性休克风险，仅在有条件的医疗机构使用","renal":"无","hepatic":"重度肝病慎用","interact":"与口服铁剂不宜同用"},{"name":"促红细胞生成素（EPO）","dose":"仅用于慢性肾病或早产儿相关贫血，剂量遵说明书","note":"不用于单纯营养性 IDA","renal":"剂量按肾病指南调整","hepatic":"遵说明书","interact":"无特殊"}],"nonDrug":["输血指征：Hb <60 g/L（有症状者 <70 g/L）或伴心功能不全、严重感染；需缓慢输注（浓缩红细胞 5–10 mL/kg）","辅食强化：6 月龄起添加强化铁米粉、红肉泥、动物肝脏（每周 1–2 次）、深绿色蔬菜","早产儿预防：生后 2–4 周起补元素铁 2–4 mg/kg/d，至 1 岁","纠正不良喂养：避免 1 岁前以纯牛奶为主（不仅缺铁且可致肠道失血）","治疗原发病：驱虫、治疗慢性腹泻与牛奶蛋白过敏"],"life":["养成均衡饮食与规律体检习惯，学龄前每年查血常规","青春期女孩注意月经量过多者需查铁代谢","服用铁剂期间大便变黑属正常，需提前告知家长（避免误认为消化道出血）","铁剂应放于儿童无法触及处（误食 20–60 mg/kg 元素铁可致命）","治疗后 2–4 周复查血常规评估反应，之后 3 个月复查确认储备恢复"]},"prog":"规范补铁 2–4 周网织红细胞上升，1–2 个月 Hb 恢复正常，预后良好。但神经认知影响可能不完全可逆，早期识别与预防更为重要。反复 IDA 需查明慢性失血原因。","refs":["《儿童缺铁性贫血诊断与治疗建议》（中华儿科杂志，2008）及后续更新","《儿童铁缺乏和缺铁性贫血防治专家共识》（中华医学会儿科学分会，2022）","WHO Guideline: Daily iron supplementation in infants and children, 2016","《中国 0–6 岁儿童营养发展报告》（国家卫生健康委）"]},{"id":"ped_rickets","name":"维生素 D 缺乏性佝偻病与手足搐搦症","aka":["Rickets","Vitamin D Deficiency Rickets","维生素 D 缺乏性手足搐搦症"],"rank":2,"basic":{"define":"因维生素 D 缺乏导致钙磷代谢紊乱、骨矿化障碍所致的全身性慢性营养性疾病，多见于 2 岁以下婴幼儿；其急性表现（低钙惊厥）称为维生素 D 缺乏性手足搐搦症。","risk":["母乳喂养未补充维生素 D（母乳含量极低）","日照不足（北方冬季、长期室内、空气污染、过度防晒）","早产与低出生体重、双胎","生长过快（婴儿期与青春期）","母亲妊娠期维生素 D 缺乏","慢性腹泻、肝胆或肾脏疾病影响转化"],"epi":"我国婴幼儿佝偻病患病率已显著下降，但维生素 D 不足与缺乏率仍高（儿童青少年约 20%–50%）。北方地区冬季与纯母乳喂养未补充者高发。"},"patho":"维生素 D 经皮肤（UVB 照射 7-脱氢胆固醇）或食物摄入，在肝脏转化为 25-(OH)D，再在肾脏经 1α-羟化酶转化为活性 1,25-(OH)₂D。后者促进肠道钙吸收、骨矿化与肾小管钙重吸收。缺乏时肠道钙吸收下降，血钙下降刺激 PTH 分泌（继发性甲旁亢），导致肾排磷增加、血磷下降，钙磷乘积下降致骨样组织矿化障碍，形成佝偻病的骨骼改变。急性严重低钙时可致神经肌肉兴奋性增高（手足搐搦、喉痉挛、惊厥）。","dx":{"criteria":["病史：日照不足、未补充维生素 D、早产或生长过快","临床表现分期：① 初期——多汗、夜惊、烦躁、枕秃（3 月龄左右）；② 激期——骨骼改变：<6 月见颅骨软化（乒乓头）、方颅（8–9 月）、肋骨串珠、手足镯（6 月后）、鸡胸/漏斗胸、O 型腿（1 岁后站立行走）或 X 型腿；③ 恢复期——症状消失、骨骼体征逐渐减轻；④ 后遗症期——3 岁后遗留骨骼畸形","血生化：25-(OH)D <30 nmol/L（12 ng/mL）为缺乏，30–50 nmol/L 为不足；激期血清磷明显降低、碱性磷酸酶升高，血钙正常或偏低","X 线（腕部正位）：干骺端增宽、杯口状凹陷与毛刷状改变，骨化中心出现延迟，骨密度普遍降低","手足搐搦症：血清总钙 <1.75 mmol/L（7 mg/dL）或离子钙 <1.0 mmol/L，表现为惊厥、手足搐搦（腕足痉挛）或喉痉挛（最危险）"],"workup":["血 25-(OH)D（首选指标）、血钙、血磷、碱性磷酸酶、PTH","血镁（低镁可致顽固性低钙）、肾功能与电解质","腕部 X 线（评估骨化中心与干骺端改变）","疑肾性佝偻病者查血肌酐、血气（肾小管酸中毒）与尿钙磷","疑低磷性佝偻病者查血磷（显著降低）与家族史、基因检测"],"grading":"临床分四期（初期、激期、恢复期、后遗症期）；按血 25-(OH)D 水平分充足（≥50 nmol/L）、不足（30–49.9）、缺乏（<30）、严重缺乏（<12.5）。"},"ddx":[{"name":"营养性缺铁性贫血（ped_ida）","point":"与 IDA 的鉴别：IDA 以贫血为核心（小细胞低色素），骨骼改变不突出；但两者常并存于同一营养不良儿童，需同时评估。"},{"name":"儿童营养不良（ped_malnutrition）","point":"与营养不良的鉴别：营养不良以体重/身长比例下降为主，可伴多种营养素缺乏；单纯佝偻病体重多正常而骨骼体征突出。"},{"name":"低磷性佝偻病（家族性）","point":"血磷显著降低而血钙与 25-(OH)D 正常，有家族史（X 连锁显性），对常规维生素 D 剂量反应差，需补磷与活性维生素 D。"},{"name":"肾性佝偻病","point":"有慢性肾脏病背景（eGFR 下降、蛋白尿），血钙低、血磷高、PTH 显著升高，需按 CKD-MBD 管理。"},{"name":"肾小管酸中毒","point":"以低钾、代谢性酸中毒、尿 pH 不适当升高为特征，可致佝偻病与生长迟缓，血气可确诊。"},{"name":"软骨发育不全","point":"四肢短小、头大、前额突出，但血生化与 25-(OH)D 正常，为遗传性骨骼发育异常。"}],"tx":{"drug":[{"name":"维生素 D3（胆钙化醇）","dose":"活动期：2000–4000 IU/d 口服，持续 1 个月后改为预防量 400–800 IU/d；或单次大剂量 15 万–30 万 IU 口服（遵国内共识），1 个月后复查","note":"首选口服 D3；避免肌注（吸收不稳定且易过量）；治疗期间同补钙剂","renal":"肾功能不全者需用活性维生素 D（骨化三醇），普通 D3 转化受限","hepatic":"重度肝病者需用 25-(OH)D 制剂","interact":"与苯巴比妥、苯妥英、利福平合用加速代谢降低疗效；与噻嗪类合用增加高钙风险"},{"name":"钙剂（葡萄糖酸钙 / 碳酸钙）","dose":"元素钙 1 岁内 300–600 mg/d、1–3 岁 600–800 mg/d，分次口服；手足搐搦急性期：10% 葡萄糖酸钙 5–10 mL 加等量葡萄糖液缓慢静脉推注（10 分钟以上），必要时重复","note":"急性低钙惊厥首选静脉钙剂，需心电监护（心动过缓与组织坏死风险，切勿外渗）；症状控制后改为口服并加维生素 D","renal":"肾功能不全者慎用（高钙风险）","hepatic":"无需调整","interact":"与铁剂、四环素、喹诺酮类同服降低吸收（间隔 2 小时）；与洋地黄合用增加心律失常风险（禁用静脉钙）"},{"name":"骨化三醇（活性维生素 D）","dose":"0.25–0.5 µg/d 口服，用于肾性佝偻病或肝功能严重受损者，需监测血钙","note":"起效快但高钙风险高，需每 2–4 周监测血钙与尿钙","renal":"为肾性骨病首选","hepatic":"无需肝脏转化，适合肝病者","interact":"与噻嗪类利尿剂合用增加高钙血症风险；与含镁抗酸药合用可致高镁血症"},{"name":"硫酸镁（低镁相关顽固性低钙）","dose":"25% 硫酸镁 0.1–0.2 mL/kg 深部肌注或稀释后缓慢静滴（遵说明书）","note":"低钙搐搦对钙剂反应差时应查血镁，低镁不纠正则低钙难以纠正","renal":"肾功能不全时禁用或极谨慎使用（高镁血症致呼吸抑制）","hepatic":"无需调整","interact":"与神经肌肉阻滞剂合用加重阻滞"}],"nonDrug":["增加户外活动与日照：每天 1–2 小时（避免暴晒与紫外线强烈时段），暴露面部与手足","激期避免过早站立行走（防止下肢畸形加重），恢复期后再逐步负重","后遗症期骨骼畸形：轻度随生长自行矫正，重度（如严重 O 型腿影响行走）需骨科评估","喉痉挛的紧急处理：保持气道通畅、吸氧，必要时气管插管（可致命）","孕妇与乳母补充维生素 D（400–1000 IU/d）以改善新生儿储备"],"life":["预防：生后数天起每日补充维生素 D 400 IU，早产儿 800–1000 IU/d（3 个月后改 400 IU），至 2 岁（北方可延长至 3 岁）","辅食添加含钙丰富食物（奶制品、豆制品、深绿色蔬菜）","定期随访：治疗 1 个月复查血生化与骨骼体征，3 个月评估 X 线恢复","避免滥用大剂量维生素 D（过量可致高钙血症、肾钙化）","青春期快速生长者若日照不足，建议评估 25-(OH)D"]},"prog":"早期诊断与规范补充维生素 D 后 2–4 周症状改善，1–2 个月血生化恢复，骨骼改变在生长过程中逐渐减轻；3 岁后遗留的骨骼畸形（如鸡胸、O 型腿）多数可自行改善，严重者需骨科干预。手足搐搦症经及时处理预后良好，但喉痉挛可致死。","refs":["《维生素 D 缺乏性佝偻病防治建议》（中华儿科杂志，2008）","《儿童维生素 D 缺乏性佝偻病诊治建议》（中华医学会儿科学分会儿童保健学组）","2016 Global Consensus Recommendations on Prevention and Management of Nutritional Rickets","《中国儿童维生素 A、维生素 D 临床应用专家共识（2021）》"]},{"id":"ped_malnutrition","name":"儿童营养不良与生长迟缓","aka":["Protein-Energy Malnutrition","PEM","消瘦型","水肿型","kwashiorkor","marasmus"],"rank":3,"basic":{"define":"因能量与蛋白质摄入不足或吸收利用障碍导致的营养缺乏状态，表现为体重与身长增长落后、皮下脂肪减少、肌肉萎缩与器官功能减退，包括消瘦型（marasmus）、水肿型（kwashiorkor）与混合型。","risk":["贫困与食物不安全、喂养不当（过早断奶、辅食质量差）","慢性腹泻、吸收不良（乳糜泻、囊性纤维化）","反复感染（结核、HIV、寄生虫）","早产与低出生体重","慢性疾病（先天性心脏病、慢性肾病、肝病、肿瘤）","挑食与喂养行为问题、心理社会剥夺"],"epi":"WHO 估计全球 5 岁以下儿童约 13% 存在消瘦、6.7% 生长迟缓。我国农村地区 5 岁以下儿童生长迟缓率约 4%–6%，城市约 1%–2%；重症营养不良已少见但仍在偏远地区存在。"},"patho":"能量与蛋白摄入不足时，机体先动员糖原与脂肪，随后分解肌肉蛋白供能（消瘦型），导致体重下降与肌肉萎缩；长期蛋白缺乏时肝脏合成白蛋白下降致低蛋白血症与水肿（水肿型），同时抗氧化物质（谷胱甘肽）与脂蛋白合成减少，可致脂肪肝。营养不良使免疫（T 细胞、分泌型 IgA、补体）与黏膜屏障受损，易反复感染；心脏与胃肠黏膜萎缩（吸收功能进一步下降），形成恶性循环。恢复期快速喂养可诱发「再喂养综合征」（低磷、低钾、低镁与心衰）。","dx":{"criteria":["按 WHO 生长标准（0–5 岁）：年龄别身高 Z 值 <-2 为生长迟缓；身高别体重 Z 值 <-2 为消瘦（中度），<-3 为重度；年龄别体重 Z 值 <-2 为低体重","或中上臂围（MUAC）：6–59 月龄 <125 mm 提示中度、<115 mm 提示重度营养不良","水肿型：双下肢凹陷性水肿、皮肤改变（脱屑、色素沉着）、头发稀疏变色，常有低白蛋白血症","伴发表现：免疫力低下（反复感染）、贫血、维生素 A 缺乏（夜盲、角膜干燥）、锌缺乏（皮炎、腹泻）、低血糖与低体温","需评估并存疾病：慢性腹泻、结核、HIV、先天性心脏病与肾病"],"workup":["生长测量：体重、身长/身高、头围、中上臂围，绘于 WHO 生长曲线","血常规、白蛋白、前白蛋白、电解质（钾、磷、镁）、血糖、肝肾功能","维生素与微量元素：维生素 A、D、B12、叶酸、铁蛋白、锌","排查病因：大便常规与寄生虫、粪钙卫蛋白、乳糜泻血清学、结核筛查（PPD/IGRA）、HIV、尿常规","心功能评估（心肌萎缩者易心衰）与心电图（低钾改变）"],"grading":"WHO 分型：消瘦型（marasmus，以能量缺乏为主，体重显著下降）、水肿型（kwashiorkor，以蛋白缺乏为主，有水肿）、混合型。按 Z 值分中度（-2 至 -3）与重度（<-3）。"},"ddx":[{"name":"营养性缺铁性贫血（ped_ida）","point":"与 IDA 的鉴别：IDA 以血红蛋白下降为核心，体重可正常；营养不良常伴随多种营养素缺乏，包括铁、锌、维生素 A。"},{"name":"维生素 D 缺乏性佝偻病（ped_rickets）","point":"与佝偻病的鉴别：佝偻病以骨骼改变（方颅、串珠）为特征，体重多正常；两者常并存于同一患儿。"},{"name":"矮小症与性早熟（ped_short_stature）","point":"与矮小症的鉴别：单纯矮小者身高低但体重/身高比例正常、营养状态良好；营养不良者身高别体重低（消瘦）。"},{"name":"生长激素缺乏症","point":"身材匀称性矮小、年生长速率 <4 cm，体重相对正常，IGF-1 降低，生长激素激发试验异常。"},{"name":"慢性肾病与肾小管酸中毒","point":"有蛋白尿、血肌酐升高或代谢性酸中毒，生长落后为继发表现。"},{"name":"先天性心脏病","point":"有杂音、发绀或心衰表现，喂养困难与能量消耗增加导致生长落后，心脏超声可确诊。"}],"tx":{"drug":[{"name":"维生素 A（重度营养不良常规补充）","dose":"6–11 月龄 10 万 IU 单次；≥12 月龄 20 万 IU 单次，24 小时与 2 周后各重复 1 次（WHO 方案）","note":"可降低病死率与失明风险；一次大剂量优于每日小剂量；妊娠期禁用大剂量","renal":"无需调整","hepatic":"肝病者慎用大剂量","interact":"与维生素 E 合用减少氧化损失；过量可致颅高压与肝损"},{"name":"锌剂（硫酸锌/葡萄糖酸锌）","dose":"元素锌 10–20 mg/d（<6 月 10 mg，≥6 月 20 mg），疗程 10–14 天","note":"WHO 推荐腹泻与营养不良常规补锌，可缩短腹泻病程并改善食欲；与铁剂分开服用","renal":"无需调整","hepatic":"无需调整","interact":"与铁、钙、铜同服竞争吸收（间隔 2 小时）"},{"name":"叶酸与多种维生素","dose":"叶酸 5 mg/d 起始（缺乏者），多种维生素制剂按说明书","note":"重度营养不良常伴多种维生素缺乏，需综合补充","renal":"无需调整","hepatic":"无需调整","interact":"大剂量叶酸可掩盖 B12 缺乏的血液学表现"},{"name":"口服补液盐与电解质纠正","dose":"按脱水程度给 ORS 50–100 mL/kg（4 小时内）；低钾者补钾 3–4 mmol/kg/d，低磷者口服磷酸盐","note":"再喂养综合征的预防核心是缓慢增加能量并纠正电解质；重症者需住院监测","renal":"肾功能不全者慎补钾与磷","hepatic":"无需调整","interact":"ORS 与含糖饮料同用加重腹泻"},{"name":"抗生素（并存感染时）","dose":"按感染部位与病原选择，剂量按体重；WHO 对重症营养不良常规推荐广谱抗生素（如阿莫西林）","note":"重症营养不良（尤其水肿型）常规给予抗生素可降低病死率，即使无明显感染灶","renal":"按 CrCl 调整","hepatic":"肝病者减量","interact":"按具体药物"},{"name":"重组人生长激素（确诊 GHD 后）","dose":"0.1–0.15 IU/kg/d 皮下注射 qn（约 0.025–0.035 mg/kg/d）","note":"仅用于确诊生长激素缺乏、特发性矮小或特定综合征；营养不良本身不适用，应先纠正营养","renal":"CKD 相关矮小需专科评估","hepatic":"慎用","interact":"糖皮质激素拮抗其促生长作用"}],"nonDrug":["WHO 十步康复法：低血糖与低体温处理、脱水与电解质纠正、抗感染、纠正微量营养素缺乏、缓慢喂养（F-75 起始）、追赶生长（F-100/RUTF）、刺激与情感支持、随访准备","再喂养综合征监测：前 48 小时每 4–6 小时查电解质（磷、钾、镁），能量从 80–100 kcal/kg/d 起始，每 24–48 小时递增 20–30 kcal/kg/d","重度营养不良住院治疗：前 24 小时优先处理低血糖（10% 葡萄糖 5 mL/kg）、低体温与感染","喂养技巧指导与辅食质量改善（能量密度、蛋白质与微量营养素）","心理社会评估：贫困、忽视与喂养行为问题需同步干预"],"life":["定期监测生长曲线（每 1–3 个月），评估追赶生长速率（目标 2 周内体重增长 ≥10 g/kg/d）","出院后持续营养支持与家长教育（高能量密度食谱、少量多餐）","按计划完成疫苗接种（营养不良儿童接种安全且必要）","发育筛查：运动、语言与认知评估，必要时早期干预","长期随访至生长正常，警惕反复营养不良背后的慢性病或社会问题"]},"prog":"轻度与中度营养不良经规范营养支持后多可完全恢复；重度（尤其水肿型）住院病死率仍达 5%–20%，死亡高峰在入院后 24–48 小时（低血糖、低体温、感染与心衰）。及早识别再喂养综合征与感染可显著改善预后。长期营养不良可致认知发育落后与成年身高受限。","refs":["《儿童营养不良诊断与治疗专家共识》（中华医学会儿科学分会，2021）","WHO. Guideline: Updates on the management of severe acute malnutrition in infants and children, 2013","WHO. Management of Severe Malnutrition: A Manual for Physicians and Other Senior Health Workers, 1999","《中国 0–6 岁儿童营养发展报告》（国家卫生健康委）"]},{"id":"ped_short_stature","name":"矮小症与性早熟","aka":["Short Stature","Growth Hormone Deficiency","Precocious Puberty","中枢性性早熟"],"rank":4,"basic":{"define":"矮小症：身高低于同年龄、同性别正常儿童身高均值减 2 个标准差（约第 3 百分位），或年生长速率低于正常。性早熟：女孩 8 岁前、男孩 9 岁前出现第二性征发育，按机制分为中枢性（GnRH 依赖性）与外周性（非 GnRH 依赖性）。","risk":["矮小：家族性矮小、宫内生长迟缓（SGA）未追赶、生长激素缺乏、甲状腺功能减退、慢性病（肾病、IBD、乳糜泻）、Turner 综合征、骨骼发育不良","性早熟：女性特发性（约 80%–90%）、肥胖、中枢神经系统病变（肿瘤、外伤、感染）、先天性肾上腺皮质增生、McCune-Albright 综合征、外源性性激素暴露"],"epi":"我国儿童矮小症患病率约 3%；特发性中枢性性早熟在女孩中的发生率约 1/5000–1/10000，女孩显著多于男孩（约 10:1）。近年因肥胖增加，性早熟发病率有上升趋势。"},"patho":"身高由遗传（约占 80%）与环境（营养、睡眠、运动、内分泌）共同决定。生长激素（GH）由垂体脉冲式分泌，经肝脏产生 IGF-1 促进骨骺软骨细胞增殖与分化；GH 分泌受 GHRH 与生长抑素调节，并与甲状腺激素、性激素、糖皮质激素协同。性早熟时下丘脑-垂体-性腺轴提前激活（中枢性），性激素促骨骺加速成熟，虽短期身高增长快但骨骺提前闭合，最终成年身高受损。","dx":{"criteria":["矮小症诊断：身高 <同种族同性别同年龄第 3 百分位或 <-2 SD；或身高在第 3–10 百分位但年生长速率 <5 cm/年（4 岁至青春期前）；或骨龄落后 >2 岁","需计算遗传靶身高（男：(父身高+母身高+13)/2；女：(父身高+母身高−13)/2，±5 cm）与身高标准差积分（HtSDS）","生长激素缺乏：需两项 GH 激发试验（胰岛素低血糖、精氨酸、左旋多巴、可乐定）峰值均 <10 ng/mL；IGF-1 与 IGFBP-3 降低","Turner 综合征：女孩矮小伴颈蹼、肘外翻、乳房不发育，染色体核型 45,X 或其嵌合体","中枢性性早熟：女孩 8 岁前乳房发育、男孩 9 岁前睾丸增大（≥4 mL）；GnRH 激发试验 LH 峰值 >5 IU/L（或 >基础值 3 倍）支持中枢性；骨龄超前 ≥1 岁；子宫卵巢超声见容积增大","外周性性早熟：GnRH 激发试验 LH 无反应，需查性激素（雌二醇/睾酮）、肾上腺雄激素（DHEAS）、hCG、甲状腺功能与影像"],"workup":["精确身高与体重测量、生长曲线绘制、年生长速率计算","骨龄（左手腕 X 线，Greulich-Pyle 法）","IGF-1、IGFBP-3；GH 激发试验（需专科进行）","甲状腺功能、肝肾功能、血常规、ESR、乳糜泻血清学（排查慢性病）","女孩：染色体核型（排除 Turner）、盆腔超声（子宫卵巢发育）","性早熟：GnRH 激发试验、性激素、肾上腺雄激素、头颅 MRI（尤其男孩与 6 岁前起病女孩，排查颅内病变）","男孩性早熟必须查 hCG 与睾丸超声（排除分泌 hCG 的肿瘤）"],"grading":"矮小按 HtSDS 分：<-2 为矮小，<-3 为严重矮小。性早熟按发病机制分中枢性（GnRH 依赖性、真性）与外周性（非 GnRH 依赖性、假性），按发病年龄分早发（女孩 <6 岁、男孩 <9 岁需警惕器质性病变）。"},"ddx":[{"name":"营养性缺铁性贫血（ped_ida）","point":"与 IDA 的鉴别：慢性贫血可致生长落后，但纠正贫血后生长恢复；单纯 IDA 身高速率改变不明显。"},{"name":"儿童营养不良（ped_malnutrition）","point":"与营养不良的鉴别：营养不良者体重/身高比例低（消瘦），身高可落后但营养改善后追赶生长；内分泌性矮小者体重/身高比例多正常。"},{"name":"维生素 D 缺乏性佝偻病（ped_rickets）","point":"与佝偻病的鉴别：佝偻病有骨骼畸形（O/X 腿）与血生化异常，身长可落后；25-(OH)D 与碱性磷酸酶可明确。"},{"name":"家族性矮小与体质性青春发育延迟","point":"家族性矮小：父母身高也矮、骨龄与年龄相符、生长速率正常；体质性延迟：骨龄落后、青春期发育晚但最终身高正常（「晚长」）。"},{"name":"甲状腺功能减退","point":"身材不匀称（上部量/下部量比值增大）、骨龄显著落后、TSH 升高、T4 降低，伴智力与代谢改变。"},{"name":"生长激素缺乏症","point":"匀称性矮小、年生长速率 <4 cm、IGF-1 低、GH 激发试验峰值 <10 ng/mL，GH 治疗反应好。"}],"tx":{"drug":[{"name":"重组人生长激素（rhGH）","dose":"0.1–0.15 IU/kg/d（约 0.025–0.035 mg/kg/d）皮下注射，每晚 1 次；疗程至骨骺闭合或达到满意身高（通常 2–5 年）","note":"适用于确诊 GHD、Turner 综合征、SGA 未追赶、特发性矮小（需符合指征）等；治疗前需排除肿瘤与骨骺已闭合；监测身高、IGF-1、血糖、甲状腺功能与股骨头","renal":"CKD 相关矮小需肾病专科评估剂量","hepatic":"慎用，监测肝功能","interact":"糖皮质激素拮抗促生长作用；甲状腺素缺乏时会降低疗效（需同时纠正）"},{"name":"GnRH 类似物（亮丙瑞林 / 曲普瑞林）","dose":"亮丙瑞林 3.75 mg 肌注每 4 周 1 次（或 11.25 mg 每 12 周）；曲普瑞林 3.75 mg 肌注每 4 周 1 次；疗程至骨龄 12–12.5 岁（女孩）或 13–13.5 岁（男孩）","note":"仅用于中枢性性早熟；需每 3–6 个月监测身高、骨龄与性激素；预测成年身高改善有限（约 3–7 cm），需与家长充分沟通","renal":"无需调整","hepatic":"重度肝损害慎用","interact":"初期可有一过性性激素升高（需告知可能出现短暂阴道出血）"},{"name":"左甲状腺素钠（甲减所致矮小）","dose":"儿童替代量按体重：1–5 岁 4–6 µg/kg/d，6–12 岁 3–5 µg/kg/d，起始用小剂量逐步加量；每 4–8 周复查 TSH","note":"甲减是矮小可逆病因中最重要的一个，必须常规筛查","renal":"无需调整","hepatic":"无需调整","interact":"钙剂、铁剂、豆制品与黄豆配方奶降低吸收（间隔 4 小时）；苯妥英、利福平加速代谢"},{"name":"钙剂与维生素 D（辅助）","dose":"维生素 D 400–800 IU/d、元素钙 500–800 mg/d（按年龄）","note":"保证骨矿化基础供给，非矮小主治疗","renal":"肾功能不全慎用","hepatic":"遵说明书","interact":"钙与铁、四环素分开服用"}],"nonDrug":["充足睡眠：生长激素主要在深睡眠期脉冲分泌，学龄儿童需 9–11 小时","规律运动：跳绳、篮球、游泳等纵向运动有助于骨骼生长","均衡营养：保证蛋白质与钙摄入，避免肥胖（肥胖可致性早熟）","心理支持：矮小儿童易有自卑、社交回避，需关注心理健康","性早熟儿童需心理辅导与家庭教育（对早发育的身体变化做好解释）"],"life":["定期监测身高体重并绘制生长曲线（每 3–6 个月），计算年生长速率","性早熟者监测骨龄（每 6–12 个月）与预测成年身高","避免接触含性激素的化妆品、保健品与环境内分泌干扰物","控制体重：儿童期肥胖与性早熟及成年矮小相关","rhGH 治疗期间按医嘱复查 IGF-1、空腹血糖与甲状腺功能"]},"prog":"家族性矮小与体质性延迟者最终身高多在正常低限；GHD 经 rhGH 治疗可获 5–10 cm 身高改善，起始年龄越小、疗程越长效果越好。特发性中枢性性早熟经 GnRHa 治疗可改善成年身高约 3–7 cm，但需权衡成本与获益。器质性病变（颅内肿瘤、先天性肾上腺皮质增生）所致者预后取决于原发病治疗。","refs":["《矮小症儿童诊疗规范》（中华医学会儿科学分会内分泌遗传代谢学组，2019）","《中枢性性早熟诊断与治疗共识（2015）》及 2022 更新（中华医学会儿科学分会）","2016 International Guideline: Diagnosis and Treatment of Growth Hormone Deficiency in Children and Adolescents (GH Research Society)","2019 ESPE/LWPES Consensus Statement on Precocious Puberty","《中国儿童生长发育迟缓诊疗指南》"]},{"id":"ped_hsp","name":"过敏性紫癜（IgA 血管炎）","aka":["Henoch-Schönlein Purpura","HSP","IgA Vasculitis","IgAV"],"rank":5,"basic":{"define":"以 IgA 免疫复合物沉积为特征的小血管炎，典型四联征为可触及的紫癜样皮疹、腹痛、关节痛与肾脏受累，是儿童最常见的系统性血管炎，多数自限。","risk":["3–10 岁儿童（高峰 4–7 岁）","男孩略多见","上呼吸道感染后（约半数有前驱感染史）","季节（秋季与冬季高发）","家族史与遗传易感（HLA 相关）"],"epi":"发病率约 10–20/10 万儿童/年，我国儿童高发；约 30%–50% 出现肾脏受累（紫癜性肾炎），其中约 1%–3% 进展为终末期肾病。"},"patho":"IgA1 分子铰链区糖基化异常（半乳糖缺乏的 Gd-IgA1）形成免疫复合物，沉积于小血管壁与肾小球系膜区，激活补体旁路途径，引起中性粒细胞浸润与血管壁坏死性炎症。皮肤与胃肠道黏膜下血管受累致紫癜与腹痛（可进展为肠套叠或肠穿孔），关节滑膜血管受累致关节痛，肾小球受累形成 IgA 肾病样病变（紫癜性肾炎）。","dx":{"criteria":["可触及的紫癜（必具条件）：双下肢与臀部对称分布、压之不褪色的斑丘疹，可融合成片，无血小板减少","以下 4 项中至少 1 项：① 弥漫性腹痛（餐后加重，可伴呕吐、便血、肠套叠）；② 关节炎或关节痛（多为膝踝大关节，非游走性、无变形）；③ 肾脏受累（血尿和/或蛋白尿）；④ 活检示 IgA 沉积（皮肤或肾）","发病年龄 ≤10 岁（支持条件，儿童与成人表现不同）","血小板计数与凝血功能正常（排除血小板减少性紫癜与凝血病）","IgA 免疫荧光沉积（皮肤活检或肾活检）为确诊依据，但多数典型病例不需活检"],"workup":["血常规（血小板正常是关键）、凝血功能（PT/APTT）","尿常规 + 尿沉渣镜检 + 24 小时尿蛋白定量或尿蛋白/肌酐比值（所有患儿必须反复查）","血肌酐、尿素氮、电解质、肝功能、白蛋白","腹部超声（疑肠套叠时首选）、大便隐血","免疫学：血清 IgA（约 50%–70% 升高）、补体 C3/C4（正常）；ANCA 与 ANA 多为阴性","肾脏受累且严重者：肾活检（系膜区 IgA 沉积为特征，按 ISKDC 分级评估新月体比例）"],"grading":"皮疹按分布与形态评估；肾脏受累按 ISKDC 分级（Ⅰ 轻微、Ⅱ 系膜增生、Ⅲ 局灶/弥漫增生或新月体 <50%、Ⅳ 新月体 50%–75%、Ⅴ 新月体 >75%、Ⅵ 膜性肾病样）。临床分轻（仅有镜下血尿）、中（肉眼血尿或轻微蛋白尿）、重（肾病范围蛋白尿或肾功能下降）。"},"ddx":[{"name":"营养性缺铁性贫血（ped_ida）","point":"与 IDA 的鉴别：IDA 为贫血，无紫癜与关节痛，血小板正常；两者可并存（消化道失血），需注意 HSP 患儿出现贫血时应评估消化道出血。"},{"name":"免疫性血小板减少症（ITP）","point":"与 ITP 的鉴别：ITP 的紫癜为针尖样出血点、压之不褪色但不可触及，且血小板显著减少（<100×10⁹/L）；HSP 的紫癜可触及且血小板正常。"},{"name":"川崎病","point":"川崎病以发热 5 天以上、多形性皮疹、结膜充血、口腔黏膜改变、颈部淋巴结肿大与手足硬肿脱皮为特征，并有冠状动脉损害，无紫癜与血小板正常。"},{"name":"特发性关节痛与生长痛","point":"无紫癜、无肾脏受累，关节痛夜间为主、不影响活动。"},{"name":"急性阑尾炎 / 肠套叠","point":"HSP 腹痛可误诊为外科急腹症；紫癜出现于腹痛之后（约 10%–20% 腹痛先于皮疹），需按禁食观察与超声评估，警惕肠套叠（尤其回盲部）。"},{"name":"IgA 肾病","point":"仅有肾脏受累（反复血尿/蛋白尿）而无全身紫癜、关节痛与腹痛，肾活检病理相同，需临床与皮肤体现区分。"}],"tx":{"drug":[{"name":"对乙酰氨基酚 / 布洛芬（关节痛与轻症对症）","dose":"对乙酰氨基酚 10–15 mg/kg q4–6h（日不超过 5 次）；布洛芬 5–10 mg/kg q6–8h","note":"轻症 HSP 主要对症处理；避免使用水杨酸类（儿童瑞氏综合征风险）","renal":"肾功能受累时避免 NSAIDs","hepatic":"肝病者减量，对乙酰氨基酚日总量不超过 75 mg/kg","interact":"NSAIDs 与激素合用增加消化道出血风险"},{"name":"糖皮质激素（泼尼松 / 甲泼尼龙）","dose":"口服泼尼松 1 mg/kg/d（最大 60 mg/d），疗程通常 2–4 周后逐渐减量；严重腹痛或肾炎重者静脉甲泼尼龙 1–2 mg/kg/d 后改口服；重度肾炎冲击治疗 15–30 mg/kg/d（最大 1 g/d）连用 3 天","note":"激素可缩短腹痛与关节痛，但不能预防肾脏受累（证据不支持常规用于预防）；重度肾炎伴新月体时冲击治疗有证据支持。需注意激素对生长与感染的影响","renal":"无需减量","hepatic":"肝病者监测","interact":"与 NSAIDs 合用增加消化道溃疡；升高血糖；活疫苗禁用"},{"name":"ACEI / ARB（蛋白尿控制）","dose":"依那普利 0.1–0.5 mg/kg/d（分 1–2 次）或缬沙坦 1–2 mg/kg/d，按血压滴定","note":"用于持续性蛋白尿（>4 mg/m²/h 或尿蛋白/肌酐 >0.2）以保护肾功能；需监测肾功能与血钾","renal":"Cr 升高 >30% 时评估减量；肌酐清除率极低时慎用","hepatic":"重度肝病慎用","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低降压效果并增加肾损伤"},{"name":"环磷酰胺（重症肾炎）","dose":"静脉 500–750 mg/m² 每月 1 次（或口服 2 mg/kg/d），共 6 个月，遵用药方案","note":"用于 ISKDC Ⅲ–Ⅳ 级或肾功能进展者，常与激素联合；需监测血象、肝功能与出血性膀胱炎（充分水化）","renal":"CrCl <30 减量","hepatic":"肝病者慎用","interact":"与别嘌醇合用增加骨髓抑制；与磺胺药合用增加膀胱毒性"},{"name":"用药期间的感染预防","dose":"按需；激素联合免疫抑制剂者按规范预防卡氏肺孢子虫肺炎（复方磺胺甲噁唑）","note":"重度免疫抑制治疗期间需常规评估是否需要预防","renal":"磺胺类在肾功能不全需减量","hepatic":"肝病慎用","interact":"磺胺类与其他药物相互作用多，需逐一核对"}],"nonDrug":["卧床休息与避免剧烈运动（皮疹与关节痛期）","腹痛明显者禁食或流质饮食，必要时胃肠外营养；警惕肠套叠（超声监测）与肠穿孔","反复监测尿常规（前 6 个月内每 1–2 周一次，之后 6–12 个月每 1–2 个月一次）","重症肾炎或肾病综合征表现者考虑肾活检与免疫抑制方案加强","关节痛局部制动与物理治疗"],"life":["绝大多数（约 95%）在 1–2 个月内皮疹消退，但约 1/3 会复发（多在 6 个月内）","家长教育：紫癜复发、腹痛加重、血便、尿色改变（血尿）需立即就诊","长期肾脏随访：尿常规与血压至少随访 2–5 年（部分肾炎在数年后才出现）","无明确食物过敏原时不推荐广泛忌口；如明确某种食物诱发可短期回避","学龄儿童皮疹期间可继续上学，但需避免剧烈运动"]},"prog":"多数患儿 4–6 周内自愈，病死率 <1%。约 1/3 复发。肾脏受累者多数在 6 个月内缓解，但约 1%–3% 进展为终末期肾病。持续蛋白尿、高血压、新月体比例 >50%、起病年龄较大是肾脏预后不良的预测因素，需长期随访。","refs":["《儿童过敏性紫癜诊治建议》（中华医学会儿科学分会免疫学组，2013）及后续修订","2010 EULAR/PRINTO/PRES Classification Criteria for Henoch-Schönlein Purpura","2019 Single Hub and Access point for paediatric Rheumatology in Europe (SHARE) Recommendations for Diagnosis and Management of IgA Vasculitis","《儿童紫癜性肾炎诊治循证指南》（中华医学会儿科学分会肾脏学组，2016）"]}]}]},"psych":{"categories":[{"id":"mood","name":"心境障碍","rank":1,"summary":"抑郁障碍以足量足疗程抗抑郁药+心理治疗为主，治疗前须筛查双相；双相障碍以心境稳定剂为基石，躁狂期避免单用抗抑郁药，锂盐需监测血药浓度与肾功能。","compare":[{"diseaseId":"ps_depression","dx":"持续 ≥2 周的心境低落或兴趣/愉悦感减退，伴 ≥4 项（共 5 项）症状如食欲/体重改变、失眠或嗜睡、精神运动迟滞或激越、疲乏、无价值感、注意力下降、自杀观念","key":"仅有抑郁相、无（轻）躁狂史，病程呈发作性、间歇期基本恢复"},{"diseaseId":"ps_bipolar","dx":"至少 1 次躁狂发作（≥1 周，心情高涨或易激惹+活动增多等 ≥3 项，显著功能损害或需住院）或轻躁狂（≥4 d，可观察的功能改变），可伴抑郁发作","key":"有无（轻）躁狂发作史是分水岭，抗抑郁药可能诱发转躁"}],"diseases":[{"id":"ps_depression","name":"抑郁障碍","aka":["Major Depressive Disorder","MDD","重性抑郁障碍"],"rank":1,"basic":{"define":"以显著而持久的心境低落、兴趣与愉悦感减退为核心，伴认知与躯体症状，病程 ≥2 周且造成功能损害的一组精神障碍；单次发作可为轻度、中度或重度（伴/不伴精神病性症状），反复发作为复发性抑郁障碍。","risk":["女性（患病率约为男性 2 倍）、青年与中年人群","一级亲属抑郁障碍史（遗传度约 30%–40%）","童年期创伤、负性生活事件、慢性压力","慢性躯体疾病（心血管病、糖尿病、肿瘤、慢性疼痛）","物质滥用、产后、老年独居、缺乏社会支持"],"epi":"我国成人抑郁障碍终生患病率约 6.8%，12 个月患病率约 3.6%；全球约 2.8 亿人受累，是伤残损失健康生命年（YLDs）首位原因。识别率与治疗率仍低，规范治疗率不足 20%。"},"patho":"单胺假说（5-HT、NE、DA 功能不足）仍是主流抗抑郁药基础，但更强调神经可塑性：慢性应激使 HPA 轴亢进、海马神经发生减少、前额叶-边缘系统环路功能异常。谷氨酸与 GABA 系统、炎症因子（IL-6、TNF-α）与肠道菌群也参与。心理社会因素通过认知偏差（负性认知三角）与行为退缩维持症状。","dx":{"criteria":["核心症状（≥2 项，且至少 1 项为①或②）：①心境低落；②兴趣与愉悦感减退","附加症状（需总计 ≥5 项，持续 ≥2 周）：③食欲或体重明显改变；④失眠或嗜睡；⑤精神运动迟滞或激越；⑥疲乏或精力减退；⑦无价值感或过度自责；⑧注意力下降、犹豫不决；⑨反复想到死亡或自杀","症状造成显著痛苦或功能损害（社交、职业或其他重要领域）","排除双相障碍（须询问躁狂/轻躁狂史）、物质或躯体疾病所致、精神分裂症谱系","重度伴精神病性症状：出现与心境一致的妄想/幻觉（如罪恶妄想、虚无妄想）","PHQ-9 ≥10 提示中度以上抑郁，需进一步评估；HAMD-17 用于疗效评估","自杀风险评估：念头、计划、手段可获得性、既往尝试史"],"workup":["精神检查：心境、兴趣、精力、睡眠、食欲、精神运动、认知、自杀观念与精神病性症状","PHQ-9、HAMD-17 与 GAD-7（评估共病焦虑）","甲状腺功能（甲减可致抑郁）、血常规、肝肾功能、电解质","老年或认知下降者：认知筛查（MMSE/MoCA）、维生素 B12 与叶酸","疑双相：筛查轻躁狂症状（MDQ/心境障碍问卷）","必要时尿毒物筛查（物质滥用）"],"grading":"按严重度：轻度（症状少、功能轻度受损，PHQ-9 5–9）、中度（PHQ-9 10–14 或 HAMD 17–24）、重度（PHQ-9 ≥15 或 HAMD >24，伴明显功能损害）；按病程：单次发作、复发性（≥2 次发作，间隔 ≥2 个月）、慢性（≥2 年持续）；伴/不伴精神病性症状、伴焦虑痛苦。"},"ddx":[{"name":"双相障碍（ps_bipolar）","point":"与本类 ps_bipolar 的鉴别点：抑郁障碍无躁狂/轻躁狂发作史；双相抑郁常有早发、发作频繁、非典型（嗜睡、贪食、铅样麻痹）、家族双相史，抗抑郁药单用可诱发转躁。"},{"name":"广泛性焦虑障碍（ps_gad）","point":"与本类 ps_gad 的鉴别点：GAD 以持续 6 个月以上的过度担忧为核心、无明确对象，抑郁症状位居其次；抑郁障碍以心境低落与兴趣减退为主，焦虑为继发。"},{"name":"精神分裂症（ps_schizo）","point":"与本类 ps_schizo 的鉴别点：精神分裂症以幻觉、妄想与思维形式障碍为核心，情感平淡、意志减退，抑郁症状可共存但非主要；抑郁伴精神病性症状时妄想与心境一致。"},{"name":"甲状腺功能减退、贫血、维生素 B12 缺乏","point":"可表现为淡漠、疲乏与情绪低落，实验室检查异常（TSH 升高、血红蛋白低、B12 低），纠正后症状改善。"},{"name":"哀伤反应、适应障碍","point":"哀伤反应与丧失事件相关、可自行缓解，不满足症状持续 ≥2 周与功能损害标准；适应障碍在应激后 3 个月内出现，程度较轻。"}],"tx":{"drug":[{"name":"舍曲林","dose":"起始 50 mg qd 早餐后服，1–2 周内可增至 100 mg qd；一般有效剂量 50–200 mg/d（最大 200 mg/d），起效 2–4 周，足量足疗程 6–8 周评估疗效","note":"SSRI 一线，安全性高、药物相互作用少；老年起始 25 mg qd；常见恶心、失眠、性功能障碍与出汗","renal":"轻中度无需调整，重度慎用","hepatic":"轻中度肝功能不全减半，重度慎用或禁用","interact":"与 MAOI 禁忌（间隔 14 d）；与曲马多、曲坦类、NSAIDs 合用增加 5-HT 综合征与出血风险；与华法林合用增加出血"},{"name":"艾司西酞普兰","dose":"起始 10 mg qd，1 周后可增至 20 mg qd（一般 10–20 mg/d，最大 20 mg/d）；老年 5 mg qd 起始，最大 10 mg/d","note":"SSRI 中疗效与耐受性平衡好；65 岁以上剂量不超过 10 mg/d（QT 间期风险）","renal":"重度肾功能不全慎用","hepatic":"肝功能不全减量（最大 10 mg/d）","interact":"与 MAOI 禁忌；与 QT 延长药（胺碘酮、氟哌啶醇）合用需监测心电图；与 NSAIDs 合用增加出血"},{"name":"文拉法辛","dose":"起始 75 mg qd 缓释制剂，1 周内可增至 150 mg qd；一般 150–225 mg/d（最大 225 mg/d）；减药需缓慢（每周减 75 mg）","note":"SNRI，适用于伴疼痛或难治性抑郁；血压升高、出汗与停药综合征（眩晕、恶心）明显","renal":"eGFR <30 减量 50%，透析患者慎用","hepatic":"肝功能不全减量","interact":"与 MAOI 禁忌；与曲马多/曲坦类合用 5-HT 综合征风险；与利尿剂合用低钠血症风险"},{"name":"米氮平","dose":"起始 15 mg qn 睡前，1–2 周后可增至 30 mg qn（一般 15–45 mg/d，最大 45 mg/d）","note":"适用于伴失眠与食欲下降的抑郁；嗜睡与体重增加明显，镇静作用强","renal":"eGFR <30 减量","hepatic":"肝功能不全减量","interact":"与苯二氮䓬类、阿片类合用增加中枢抑制；与曲马多合用 5-HT 综合征风险"},{"name":"阿戈美拉汀","dose":"25 mg qn 睡前口服，疗效不足可增至 50 mg qn；起效 2 周内评估","note":"褪黑素受体激动剂+5-HT2C 拮抗，改善睡眠节律；须监测肝功能（用药前、3 周、6 周后定期）","renal":"重度肾功能不全禁用","hepatic":"肝功能受损（ALT >3 倍 ULN）或活动性肝病禁用；用药中 ALT >3 倍需停药","interact":"与强 CYP1A2 抑制剂（氟伏沙明）禁忌；避免饮酒"},{"name":"伏硫西汀","dose":"起始 10 mg qd，可增至 20 mg qd（5–20 mg/d）；起效 2–4 周","note":"对认知症状与功能改善可能更优；恶心常见，性功能影响较少","renal":"轻中度无需调整，重度慎用","hepatic":"重度肝功能不全慎用","interact":"与 MAOI 禁忌；与强 CYP2D6 抑制剂合用需调整"},{"name":"曲唑酮（辅助改善睡眠）","dose":"25–50 mg qn 睡前（可增至 100 mg qn），作为低剂量辅助使用，不作为单药抗抑郁","note":"主要利用其镇静作用改善失眠；高剂量时才具抗抑郁效应","renal":"慎用","hepatic":"肝功能不全慎用","interact":"与 MAOI 禁忌；与 QT 延长药物合用注意心电图"},{"name":"艾司氯胺酮鼻喷剂（难治性抑郁）","dose":"56 mg 或 84 mg 鼻喷，每周 2 次（诱导期），按疗效减至每周 1 次或每 2 周 1 次；须在有资质的医疗机构使用，给药后观察 ≥2 h","note":"用于 ≥2 种抗抑郁药足量足疗程无效的难治性抑郁；可致解离、血压升高与滥用风险","renal":"遵说明书","hepatic":"重度肝功能不全慎用","interact":"与中枢抑制剂合用增强镇静；避免与 MAOI 同用"}],"nonDrug":["心理治疗：认知行为治疗（CBT）与 interpersonal therapy（IPT）为一线，轻度抑郁可单独使用","物理治疗：重复经颅磁刺激（rTMS）用于药物不耐受或难治性抑郁；无抽搐电休克（MECT）用于重度伴精神病性症状、高自杀风险或拒食脱水者","光疗：季节性情感障碍首选（10 000 lux，每日 30 min，晨间）","治疗分期：急性期 6–12 周（目标缓解）、巩固期 4–9 个月（防复燃）、维持期（复发 ≥2–3 次者至少 2 年）","联合治疗：中重度推荐药物+心理治疗联合；难治性抑郁（≥2 种药物足量足疗程无效）考虑增效（锂盐、甲状腺素、非典型抗精神病药）","共病管理：慢性疼痛、心血管病、失眠与物质滥用需同时处理"],"life":["规律作息、适度运动（每周 150 min 中等强度运动有抗抑郁效应）、限制酒精","社会支持与家庭参与：心理教育减少病耻感，识别复发早期信号","随访：急性期每 1–2 周复诊，巩固期 4 周、维持期 3 个月一次；PHQ-9 监测","自杀风险管理：制定安全计划、限制手段可获得性、紧急联系人","妊娠/哺乳期用药需精神科与产科共同评估，避免突然停药"]},"prog":"首次发作经规范治疗约 60%–70% 可在 6–8 周内缓解；未巩固治疗者 6 个月内复燃率约 40%，复发 ≥3 次者长期维持治疗可降低复发约 50%。约 20%–30% 发展为慢性或难治性抑郁。自杀风险在急性期与治疗初期（尤其年轻患者）需重点监测。","refs":["中华医学会精神医学分会. 中国抑郁障碍防治指南（2015 年版，2021 修订）","APA. Practice Guideline for the Treatment of Patients with Major Depressive Disorder (2010, 2023 update)","NICE. Depression in adults: treatment and management (NG222, 2022)","CANMAT. 2023 Update on Guidelines for the Management of Adults with Major Depressive Disorder"]},{"id":"ps_bipolar","name":"双相障碍","aka":["Bipolar Disorder","双相情感障碍","躁郁症"],"rank":2,"basic":{"define":"以躁狂/轻躁狂发作与抑郁发作交替或混合出现为特征的心境障碍，分为双相Ⅰ型（至少 1 次躁狂发作，可伴或不伴抑郁）、双相Ⅱ型（至少 1 次轻躁狂发作+≥1 次抑郁发作）与环性心境障碍。","risk":["一级亲属双相障碍史（遗传度最高，约 60%–85%）","发病年龄早（<20 岁）、抑郁首次发作且病程长","睡眠剥夺、季节性变化（春季躁狂、冬季抑郁）","物质滥用（酒精、可卡因）、抗抑郁药诱发转躁","生活事件、产后（产后精神病与双相风险相关）"],"epi":"全球终身患病率约 1%–2.4%（双相谱系可达 4%），我国约 0.6%–1%；发病高峰 15–25 岁，男女患病率相近。诊断延迟平均 5–10 年，约 60%–70% 患者首次就诊为抑郁发作。"},"patho":"多基因遗传背景参与（CACNA1C、ANK3 等），叠加昼夜节律与生物钟紊乱、HPA 轴失调与线粒体能量代谢异常。神经影像显示前额叶-边缘系统（杏仁核、伏隔核）情绪调节环路失衡。锂盐通过抑制 GSK-3β 与 IP3 信号发挥心境稳定作用；睡眠节律紊乱与躁狂发作关系密切。","dx":{"criteria":["躁狂发作：心境高涨或易激惹，活动/精力增加，持续 ≥1 周（或需住院），伴以下 ≥3 项（易激惹时为 ≥4 项）：言语增多、意念飘忽、注意力分散、活动增多、睡眠需要减少、夸大、轻率行为（挥霍、冲动性行为）；显著功能损害或伴精神病性症状","轻躁狂：持续 ≥4 d，症状与躁狂相似但未致显著功能受损、无精神病性症状、不需住院，他人可观察到的变化","抑郁发作：满足抑郁障碍诊断标准，常为非典型表现（嗜睡、贪食、铅样麻痹）","混合特征：抑郁发作中出现 ≥3 项躁狂症状或躁狂发作中出现 ≥3 项抑郁症状","排除物质/药物所致（可卡因、皮质类固醇）、躯体疾病（甲亢）与分裂情感性障碍","筛查工具：MDQ、心境障碍问卷与家族史询问"],"workup":["详细病史：发作形式、频率、有无轻躁狂（常被忽略）、家族史、既往抗抑郁药反应（诱发转躁）","精神检查与自杀/冲动风险评估","YMRS（躁狂）或 MADRS/HAMD（抑郁）量表","甲状腺功能、电解质（锂盐患者）、血常规、肝肾功能、心电图（基线）","尿毒物筛查（物质滥用与鉴别）","妊娠计划评估（锂盐与丙戊酸致畸风险）"],"grading":"双相Ⅰ型（≥1 次躁狂发作）、Ⅱ型（≥1 次轻躁狂+≥1 次抑郁，无躁狂）、环性心境障碍（≥2 年轻躁狂与抑郁交替，未达到发作标准）；按当前相：躁狂、混合、抑郁、缓解；按严重度与精神病性症状分层。"},"ddx":[{"name":"抑郁障碍（ps_depression）","point":"与本类 ps_depression 的鉴别点：双相障碍必须有（轻）躁狂发作史；抑郁障碍为单纯抑郁相、无躁狂史、家族史中双相少见。误诊为单相抑郁而单用抗抑郁药可致转躁与快速循环。"},{"name":"广泛性焦虑障碍（ps_gad）","point":"与本类 ps_gad 的鉴别点：GAD 为持续担忧与焦虑躯体症状，无发作性心境高涨、活动增多与睡眠需要减少；双相躁狂期之易激惹可误为焦虑。"},{"name":"精神分裂症（ps_schizo）","point":"与本类 ps_schizo 的鉴别点：精神分裂症以幻觉妄想与阴性症状为核心、情感平淡；双相躁狂伴精神病性症状时与心境密切相关，间歇期基本恢复。"},{"name":"甲状腺功能亢进","point":"心悸、消瘦、多汗、易激惹与活动增多，TSH 降低、FT3/FT4 升高；甲亢需与躁狂鉴别，治疗甲亢后心境改善。"},{"name":"物质/药物诱发（可卡因、类固醇）","point":"有明确用药史，症状在中毒/戒断期出现，停药后缓解，尿毒物筛查阳性。"}],"tx":{"drug":[{"name":"碳酸锂","dose":"起始 0.25–0.5 g bid–tid 口服（缓释制剂 0.9–1.2 g/d 分 2–3 次），按血药浓度调整至 0.6–1.2 mmol/L；急性躁狂 0.8–1.2 mmol/L，维持 0.6–0.8 mmol/L；老年中毒风险高，起始剂量减半","note":"躁狂期一线与维持期金标准；起效需 1–2 周，急性期常联合抗精神病药；治疗前查肾功能、甲状腺与心电图","renal":"肾小管排泄，eGFR <60 减量并缩短监测间隔；脱水、NSAIDs、ACEI 与低盐饮食使锂浓度升高（中毒风险）","hepatic":"经肾排泄，肝功能影响小","interact":"与利尿剂（噻嗪类）、ACEI/ARB、NSAIDs、四环素合用显著升高血锂；与甲硝唑合用升高血锂；避免低盐饮食"},{"name":"丙戊酸盐（丙戊酸钠）","dose":"起始 500 mg/d 分 1–2 次口服，逐渐增至 750–1500 mg/d（躁狂急性期可按 20–30 mg/kg/d 起，最大 60 mg/kg/d 且不超过 3 g/d）；治疗血药浓度 50–100 µg/mL","note":"急性躁狂疗效快，混合发作与快速循环适用；育龄女性禁用（神经管缺陷 1%–2%、多囊卵巢与认知影响），需严格避孕","renal":"肾功能不全减量","hepatic":"肝功能不全禁用或减量；监测转氨酶、血氨（高氨血症脑病）与血小板","interact":"与卡马西平（双向相互作用）需监测；与阿司匹林、布洛芬合用增加出血；与拉莫三嗪合用需缓慢加量（皮疹风险）"},{"name":"拉莫三嗪","dose":"第 1–2 周 25 mg qd，第 3–4 周 50 mg qd，第 5 周起 100 mg qd，之后每周增加 50 mg 至维持 100–200 mg/d（与丙戊酸合用时按说明书减半剂量并更缓慢滴定）","note":"双相抑郁维持与预防复发；缓慢加量防严重皮疹（SJS/TEN，发生率约 0.1%–0.8%），出现皮疹立即停药","renal":"肾功能不全减量（透析患者需调整）","hepatic":"肝功能不全减量并缓慢加量","interact":"与丙戊酸合用显著升高浓度并增加皮疹风险；与卡马西平、口服避孕药合用降低浓度"},{"name":"喹硫平","dose":"躁狂：起始 100 mg qd（睡前），每日增量至 400–800 mg/d 分 1–2 次；双相抑郁：300 mg qn 睡前；维持 300–600 mg/d","note":"覆盖躁狂、混合与抑郁三相，最常用于双相各相；代谢副作用（体重、血糖、血脂）显著，需定期监测","renal":"轻中度无需调整","hepatic":"肝功能不全减量，起始 25 mg qd","interact":"CYP3A4 底物，与酮康唑、红霉素合用升高浓度；与卡马西平合用降低浓度；避免饮酒"},{"name":"奥氮平","dose":"躁狂：起始 10–15 mg qn，可增至 20 mg/d；与锂盐/丙戊酸联用时起始 10 mg qn","note":"急性躁狂起效快；代谢副作用突出，需监测血糖、血脂与体重","renal":"轻度无需调整","hepatic":"肝功能不全减量","interact":"CYP1A2 底物，吸烟与氟伏沙明影响浓度；其他见抗精神病药共性"},{"name":"阿立哌唑","dose":"躁狂：起始 15 mg qd，可增至 30 mg/d；辅助维持 15–30 mg/d；双相抑郁辅助治疗可用 5–10 mg","note":"代谢副作用较轻，用于躁狂与维持；静坐不能与锥体外系反应需关注","renal":"重度肾功能不全减量","hepatic":"肝功能不全减量","interact":"与强 CYP2D6 抑制剂（氟西汀、帕罗西汀）合用减量"},{"name":"鲁拉西酮（双相抑郁）","dose":"起始 20–40 mg qd 随餐服，可增至 80–120 mg/d；起效需 2 周以上","note":"双相抑郁一线之二；需餐后服用，代谢影响较小","renal":"重度肾功能不全禁用或减量","hepatic":"中度肝功能不全减量，严重肝功能不全禁用","interact":"与强 CYP3A4 抑制剂合用减量；与地高辛/华法林合用需监测"},{"name":"阿普唑仑（短期急性激越/失眠）","dose":"0.25–0.5 mg 口服，tid 或按需（最大 4 mg/d），仅短期使用（1–2 周）；老年起始 0.25 mg qd–bid","note":"不用于长期维持，避免与阿片类合用；有依赖与跌倒风险","renal":"轻中度无需调整","hepatic":"肝功能不全减量并延长间隔","interact":"与阿片类、其他中枢抑制剂合用加重呼吸抑制（黑框警告）"}],"nonDrug":["急性躁狂：心境稳定剂+抗精神病药快速控制，必要时短期苯二氮䓬类；伴精神病性症状或激越者住院治疗","双相抑郁：优先心境稳定剂（锂盐、拉莫三嗪、喹硫平），避免抗抑郁药单用；必要时限用抗抑郁药+心境稳定剂，警惕转躁","心理社会干预：心理教育、家庭聚焦治疗、社会节律治疗（规律作息）与 CBT 可减少复发","物理治疗：有严重自杀倾向、紧张症或药物难治者行 MECT；rTMS 用于双相抑郁","妊娠与哺乳：丙戊酸禁用，锂盐在孕早期有致畸风险需专科评估；产后精神病高风险者产后应密切监测","复发监测：社会节律治疗与情绪日记，识别睡眠减少等前驱症状"],"life":["规律作息与睡眠卫生（固定起床时间，避免熬夜与倒时差）","戒酒、禁用可卡因等兴奋剂；谨慎使用糖皮质激素","心理教育与家庭支持：减少病耻感与家庭冲突","长期随访：每 1–3 个月复诊，锂盐患者每 3–6 个月查血锂、肾功能、甲状腺","生育计划与避孕咨询（尤其丙戊酸）"]},"prog":"双相障碍为慢性复发性病程，约 60%–70% 患者可维持缓解，但延误治疗与反复发作导致认知损害与功能下降。锂盐维持治疗可使复发风险下降约 40%–50%。自杀风险约 10%–15%（高于一般人群 20–30 倍），需长期监测。","refs":["中华医学会精神医学分会. 中国双相障碍防治指南（2015 年版，2021 修订）","CANMAT/ISBD. 2018 Guidelines for the Management of Patients with Bipolar Disorder（2023 更新）","APA. Practice Guideline for the Treatment of Patients with Bipolar Disorder (2002, 2005 update)"]}]},{"id":"psychotic_anxiety","name":"精神病性与焦虑障碍","rank":2,"summary":"精神分裂症以第二代抗精神病药单药治疗为核心，注意代谢、锥体外系与高泌乳素副作用，氯氮平用于难治性病例但需监测血象；广泛性焦虑障碍以 SSRI/SNRI 为基础，短期可联合加巴喷丁或丁螺环酮，苯二氮䓬仅限短期。","compare":[{"diseaseId":"ps_schizo","dx":"≥6 个月病程（其中 ≥1 个月活动期）出现 ≥2 项：幻觉、妄想、言语紊乱、严重紊乱或紧张症行为、阴性症状（情感平淡、意志减退），近 2 项之一为核心；伴社交/职业功能下降","key":"幻觉妄想+思维形式障碍+阴性症状，现实检验能力受损"},{"diseaseId":"ps_gad","dx":"持续 ≥6 个月的过度焦虑与担忧，难以控制，伴 ≥3 项（易疲劳、注意力不集中、易激惹、肌肉紧张、睡眠障碍、坐立不安）","key":"无幻觉妄想，现实检验完整，核心为持续担忧"}],"diseases":[{"id":"ps_schizo","name":"精神分裂症","aka":["Schizophrenia","精神分裂症"],"rank":1,"basic":{"define":"以感知、思维、情感与意志行为等多方面障碍为特征的重性精神疾病，核心表现为幻觉（以幻听最常见）、妄想、思维形式障碍与阴性症状，病程迁延、常伴不同程度社会功能衰退。","risk":["一级亲属精神分裂症史（遗传度约 80%）","发病年龄早（男性 15–25 岁，女性 25–35 岁）","围产期并发症（早产、产伤、缺氧）","童年期创伤、移民与城市生活、社会隔离","大麻等物质使用（尤其青少年）、冬季出生"],"epi":"全球终生患病率约 0.3%–0.7%，我国约 0.6%；发病高峰为青少年晚期至 30 岁，男女患病率相近，女性发病稍晚。精神分裂症占全球疾病负担的约 0.5%，是致残率最高的精神疾病之一。"},"patho":"多巴胺假说：中脑边缘系统 D2 受体功能亢进（阳性症状）、前额叶 D1 功能不足（阴性症状与认知损害）。谷氨酸（NMDA 受体）功能减退、GABA 中间神经元异常、免疫炎症与神经发育缺陷共同参与。神经影像示脑室扩大、海马与前额叶灰质体积减少；抗精神病药通过阻断 D2 受体改善阳性症状。","dx":{"criteria":["特征性症状（≥2 项，其中 ≥1 项来自①–③）：①幻觉；②妄想；③言语紊乱（思维散漫）；④严重紊乱或紧张症行为；⑤阴性症状（情感平淡、言语贫乏、意志减退）","社会/职业功能明显低于发病前水平（工作、人际关系、自我照料）","症状持续 ≥6 个月，其中包括 ≥1 个月的活动期症状","排除分裂情感性障碍、双相障碍伴精神病性症状、物质/药物所致与躯体疾病所致精神病性障碍","需评估自责妄想/幻听命令的性质（伤害自己或他人）与暴力风险","部分患者缺乏自知力，需结合知情者信息"],"workup":["精神检查：幻觉、妄想内容、思维形式、情感与意志、自知力、紧张症评估","PANSS（阳性与阴性症状量表）评估基线与疗效","甲状腺功能、血常规、肝肾功能、血糖、血脂、泌乳素、电解质、心电图（抗精神病药前）","尿毒物筛查（排除物质所致）","头颅影像（首发、神经系统体征或年龄 >40 岁者）与 EEG（疑癫痫/脑病）","妊娠计划评估（女性育龄期）"],"grading":"按病程：首发、复发、慢性；按症状维度：阳性症状、阴性症状、认知与情感症状；按严重度：PANSS 总分与 CGI；按治疗反应：难治性（≥2 种不同抗精神病药足量足疗程 ≥6 周无效）可考虑氯氮平。"},"ddx":[{"name":"广泛性焦虑障碍（ps_gad）","point":"与本类 ps_gad 的鉴别点：GAD 现实检验完整、无幻觉妄想，担忧对象明确且可被现实检验；精神分裂症出现幻觉、妄想与思维形式障碍，自知力受损。"},{"name":"双相障碍伴精神病性症状（ps_bipolar）","point":"与本类 ps_bipolar 的鉴别点：双相患者的精神病性症状与心境相一致性（躁狂期夸大妄想、抑郁期罪恶妄想），心境正常期精神症状消失；分裂情感性障碍为精神病性症状与心境症状同时持续。"},{"name":"抑郁障碍伴精神病性特征（ps_depression）","point":"与本类 ps_depression 的鉴别点：抑郁性精神病性症状为罪感、贫穷或虚无妄想，与心境一致，随抗抑郁治疗改善；精神分裂症的精神病性症状不限于心境发作期。"},{"name":"物质/药物所致精神病性障碍（甲基苯丙胺、大麻、皮质类固醇）","point":"有明确用药史，症状出现于使用或戒断期，尿毒物筛查阳性，停药后数天–数周缓解。"},{"name":"器质性精神病（脑炎、颞叶癫痫、自身免疫性脑炎）","point":"有神经系统体征、意识波动、癫痫发作或发热，头颅 MRI/EEG 与抗体检测异常；抗 NMDAR 脑炎可表现为精神症状与紧张症。"}],"tx":{"drug":[{"name":"奥氮平","dose":"起始 5–10 mg qn 口服，1–2 周内按需增至 10–20 mg/d（最大 20 mg/d）；急性激越可肌注 5–10 mg（最大 20 mg/d）","note":"疗效确切，适用于首发与复发；体重增加、血糖血脂升高与镇静明显，需基线并每 3–6 个月监测代谢指标","renal":"轻中度无需调整","hepatic":"肝功能不全减量","interact":"CYP1A2 底物：吸烟降低浓度，氟伏沙明显著升高浓度（需减量）；避免与中枢抑制剂/酒精合用"},{"name":"利培酮","dose":"起始 1–2 mg qd 或 bid，逐渐增至 4–6 mg/d（最大 8–16 mg/d）；长效注射剂（微球）25–50 mg 肌注 q2w","note":"一线之一；高泌乳素血症（月经紊乱、溢乳、性功能障碍）与锥体外系反应常见，需监测","renal":"eGFR <30 起始减半、最大 4 mg/d","hepatic":"肝功能不全起始减半","interact":"CYP2D6 底物，与氟西汀、帕罗西汀合用升高浓度；与 QT 延长药合用需心电图"},{"name":"阿立哌唑","dose":"起始 10–15 mg qd，可增至 15–30 mg/d；长效注射剂 400 mg 肌注 q4w（可在第 1 周接 400 mg 缓释肌注）","note":"代谢副作用较轻，D2 部分激动剂，适用于首发与维持；静坐不能、激越需关注","renal":"重度肾功能不全减量","hepatic":"肝功能不全减量","interact":"强 CYP2D6 抑制剂（氟西汀、帕罗西汀）或 CYP3A4 抑制剂合用需减量"},{"name":"帕利哌酮","dose":"缓释片 6 mg qd 起始（空腹晨服），可增至 9–12 mg/d；长效注射剂 150 mg 肌注首日、100 mg 1 周后，此后 75 mg q4w（按说明书）","note":"利培酮活性代谢物；QT 间期延长与高泌乳素风险，肝肾功能不全需减量","renal":"eGFR <50 起始 3 mg qd、最大 6 mg/d","hepatic":"肝功能不全起始减量","interact":"CYP2D6/3A4 抑制剂合用需减量；与 QT 延长药合用监测心电图"},{"name":"氯氮平","dose":"起始 12.5–25 mg qd 或 bid 口服，每日增量 25–50 mg，目标 200–600 mg/d（血药浓度 350–600 ng/mL）；需缓慢加量并监测血象","note":"难治性精神分裂症（≥2 种抗精神病药无效）首选，对自杀风险有独特作用；粒细胞缺乏发生率 0.5%–1%，需每周查血常规前 18 周，之后每 2 周","renal":"重度肾功能不全慎用","hepatic":"肝功能不全减量","interact":"与卡马西平合用增加粒细胞缺乏（禁用）；与氟伏沙明、西咪替丁、红霉素合用升高浓度；吸烟降低浓度；避免与其他骨髓抑制药物合用"},{"name":"氨磺必利","dose":"阳性症状起始 400–800 mg/d 分 2 次，目标 400–800 mg/d（最大 1200 mg/d）；阴性症状 50–300 mg/d","note":"需餐前服（提高吸收），QT 间期延长与高泌乳素风险；老年人与肾功能不全减量","renal":"eGFR <30 禁用或减量（按说明书）","hepatic":"肝功能影响小","interact":"与 QT 延长药合用增加心律失常；避免与强效 CYP3A4 抑制剂合用"},{"name":"氟哌啶醇（急性激越，短期肌注）","dose":"5 mg 肌注（老年 0.5–1 mg），必要时 30 min–1 h 后重复，24 h 内最大 15 mg；或口服 5–20 mg/d 分次","note":"强烈 D2 阻断剂，锥体外系反应与迟发性运动障碍风险高，不用于长期；与苯二氮䓬联用需监测呼吸","renal":"肾功能不全减量","hepatic":"肝功能不全减量","interact":"与 QT 延长药合用增加尖端扭转型室速；与锂盐合用增加神经毒性"},{"name":"苯海索（抗胆碱能纠正锥体外系反应）","dose":"2 mg 口服 bid–tid，最大 6 mg/d；老年起始 2 mg/d，逐渐加量","note":"只用于药源性锥体外系反应或迟发性肌张力障碍，不常规联合使用（加重认知与便秘）；抗胆碱能精神症状慎用","renal":"慎用","hepatic":"慎用","interact":"与抗胆碱能药（抗组胺药、三环类）合用加重口干、尿潴留与认知损害"}],"nonDrug":["抗精神病药治疗原则：单药、足量、足疗程（首发≥1 年，复发≥2–5 年，慢性长期）；缓慢加量并缓慢减量","长效注射抗精神病药（LAI）：用于依从性差、反复发作者（利培酮微球、帕利哌酮、阿立哌唑、奥氮平长效）","心理社会干预：认知行为治疗（针对难治性症状）、家庭干预（减少高情感表达）、社会技能训练与职业康复","急性激越/攻击：环境安抚、去激惹化技术，必要时短期约束（按规范）与肌注用药；避免体罚与过度约束","氯氮平治疗：难治性患者、反复自杀或攻击行为；需监测血象、血糖、血脂、心肌炎（前 2 个月）","电休克（MECT）：紧张症、严重拒食、攻击或药物无效时使用"],"life":["戒烟与减少大麻使用（大麻加重阳性症状）","代谢监测：体重、腰围、血压、空腹血糖、血脂（基线并每 3–6 个月）","家属心理教育：识别复发前驱症状（睡眠减少、多疑、异常言行）","社区管理与就业支持，长期随访减少复发与再入院","自杀与暴力风险评估贯穿全程；合并抑郁或物质滥用需同时治疗"]},"prog":"抗精神病药可使约 60%–70% 患者阳性症状显著改善；首发后约 80% 复发（未维持治疗者），维持治疗降低复发 3–5 倍。约 20%–30% 为难治性，氯氮平可使其中约 30%–50% 获得改善。发病至治疗间隔（DUP）越长预后越差。","refs":["中华医学会精神医学分会. 中国精神分裂症防治指南（第二版，2015；2022 修订）","APA. Practice Guideline for the Treatment of Patients with Schizophrenia (2020)","NICE. Psychosis and schizophrenia in adults: prevention and management (CG178, 2014, updated 2023)","中国精神分裂症早期干预专家共识（2019）"]},{"id":"ps_gad","name":"广泛性焦虑障碍","aka":["Generalized Anxiety Disorder","GAD","广泛性焦虑"],"rank":2,"basic":{"define":"以持续、过度且难以控制的担忧为特征，担忧对象不限于某一特定情境，伴持续的躯体紧张与警觉性增高，病程 ≥6 个月，显著影响日常功能。常与抑郁、躯体症状及睡眠障碍共病。","risk":["女性（患病率约为男性 2 倍）","童年期焦虑/抑制性气质","慢性应激、生活事件与慢性躯体疾病","一级亲属焦虑障碍史","物质使用（咖啡因、酒精）与睡眠不足"],"epi":"全球终生患病率约 5%–6%，我国约 4%–5%；多在 20–30 岁起病，起病隐匿、病程迁延，平均就诊延迟 5–10 年，常以躯体症状（心悸、胸闷、失眠）首诊于内科。"},"patho":"杏仁核-前额叶环路过度激活与自主神经警觉性升高；GABA-A 受体功能下降、5-HT 与 NE 系统失调；HPA 轴亢进。认知模型强调对威胁的过度估计与对担忧的「正性信念」（认为担忧有保护作用）维持症状。慢性焦虑与心血管疾病、肠易激综合征共病相关。","dx":{"criteria":["过度担忧与焦虑，持续 ≥6 个月，难以控制，担忧涉及多个方面（工作、健康、家庭）","伴 ≥3 项（儿童 ≥1 项）：①坐立不安或紧张感；②易疲劳；③注意力不集中；④易激惹；⑤肌肉紧张；⑥睡眠障碍","症状导致显著痛苦或功能损害","排除物质使用（咖啡因、苯丙胺）、躯体疾病（甲亢、心律失常）与其他精神障碍（尤其抑郁与惊恐障碍）","GAD-7 ≥10 提示中度焦虑，需进一步评估"],"workup":["GAD-7、HAMA 量表评估严重度","甲状腺功能、心电图（心悸/胸闷者）、血常规、血糖","尿毒物/咖啡因摄入评估","抑郁与惊恐障碍筛查（常共病）","严重失眠或躯体症状需评估共病与睡眠障碍"],"grading":"按严重度：轻度（GAD-7 5–9）、中度（10–14）、重度（15–21）；按病程：首发与慢性（>1 年）；伴惊恐障碍、社交焦虑或抑郁等共病需单独记录。"},"ddx":[{"name":"精神分裂症（ps_schizo）","point":"与本类 ps_schizo 的鉴别点：GAD 现实检验完整、无幻觉妄想，担忧可被现实检验；精神分裂症有幻觉、妄想与思维形式障碍，自语自笑与行为异常。"},{"name":"抑郁障碍（ps_depression）","point":"与本类 ps_depression 的鉴别点：GAD 以持续担忧与躯体紧张为核心，抑郁症状较轻或继发；抑郁障碍以心境低落与兴趣减退为核心，焦虑为中重度时仅为附加症状。"},{"name":"惊恐障碍","point":"反复不可预期的惊恐发作（数分钟内达峰：心悸、窒息感、濒死感），发作间期有预期性焦虑；GAD 为持续性担忧、无明确发作。"},{"name":"甲状腺功能亢进","point":"TSH 降低、FT3/FT4 升高，伴体重下降、心动过速与震颤；焦虑症状可随甲亢控制而缓解。"},{"name":"心绞痛、心律失常、哮喘","point":"胸闷、心悸需心电图与心肺检查；GAD 的躯体症状多在静息或夜间加重，运动后减轻，而器质性病变与运动相关。"}],"tx":{"drug":[{"name":"艾司西酞普兰","dose":"起始 10 mg qd，1 周后可增至 20 mg qd（一般 10–20 mg/d）；起效 2–4 周，8–12 周评估疗效；维持至少 12 个月","note":"SSRI 一线，GAD 证据充分；早期可加重焦虑，起始剂量宜低并告知","renal":"重度肾功能不全慎用","hepatic":"肝功能不全减量（最大 10 mg/d）","interact":"与 MAOI 禁忌（间隔 14 d）；与 QT 延长药合用监测心电图；与 NSAIDs 合用增加出血"},{"name":"舍曲林","dose":"起始 25–50 mg qd，可逐渐增至 100–200 mg/d；起效 2–4 周","note":"一线 SSRI；老年起始 25 mg qd","renal":"轻中度无需调整","hepatic":"肝功能不全减量","interact":"与 MAOI 禁忌；与曲马多/曲坦类合用 5-HT 综合征风险"},{"name":"帕罗西汀","dose":"起始 10–20 mg qd（早餐后），可增至 40–50 mg/d（GAD 最大 50 mg/d）；起始剂量低并缓慢加量","note":"对 GAD 与社交焦虑疗效好；抗胆碱能与停药反应明显，停药需缓慢减量","renal":"eGFR <30 减量","hepatic":"肝功能不全减量","interact":"强 CYP2D6 抑制剂，与三环类、抗精神病药合用需调整；与 MAOI 禁忌"},{"name":"文拉法辛","dose":"起始 37.5–75 mg qd 缓释，可增至 150–225 mg/d；起效 1–2 周，4–6 周评估","note":"SNRI 一线，对躯体焦虑与共病抑郁效果好；需监测血压（>225 mg/d 时）","renal":"eGFR <30 减量 50%","hepatic":"肝功能不全减量","interact":"与 MAOI 禁忌；与曲马多/曲坦类合用 5-HT 综合征风险"},{"name":"度洛西汀","dose":"起始 60 mg qd，可增至 120 mg qd（最大 120 mg/d）；起效 2–4 周","note":"SNRI，适用于焦虑伴慢性疼痛；需监测血压与肝功能","renal":"eGFR <30 禁用","hepatic":"肝功能不全（ALT >2 倍 ULN 或活动性肝病）禁用","interact":"强 CYP1A2（氟伏沙明）或 CYP2D6 抑制剂合用需调整；避免与 MAOI 合用"},{"name":"丁螺环酮","dose":"起始 5 mg bid–tid 口服，每 2–3 天增 5 mg，一般 15–30 mg/d（最大 60 mg/d）","note":"5-HT1A 部分激动剂，无依赖与镇静，起效 1–2 周；常作为增效或替代","renal":"eGFR <30 慎用","hepatic":"肝功能不全减量","interact":"与 MAOI 禁忌；与强 CYP3A4 抑制剂（酮康唑）合用需减量"},{"name":"坦度螺酮（5-HT1A 部分激动剂）","dose":"10 mg 口服 tid，可增至 20 mg tid（最大 60 mg/d）；起效 1–2 周","note":"国内常用且无依赖，适用于广泛性焦虑的长期治疗","renal":"重度肾功能不全慎用","hepatic":"肝功能不全减量","interact":"与 MAOI 禁忌"},{"name":"阿普唑仑（短期，急性焦虑/睡眠）","dose":"0.4 mg 口服 tid 或按需（最大 4 mg/d），疗程一般 ≤2–4 周；老年 0.2 mg qd–bid","note":"仅用于起始或急性加重期过渡，因依赖、认知损害与跌倒风险不宜长期","renal":"轻中度无需调整","hepatic":"肝功能不全减量并延长间隔","interact":"与阿片类、酒精合用加重呼吸抑制（黑框警告）；与唑类抗真菌药合用升高浓度"}],"nonDrug":["认知行为治疗（CBT）为一线心理治疗，与药物疗效相当，且效应持久；可单独用于轻中度","心理教育、放松训练、正念减压与运动干预","治疗顺序：轻中度可选 CBT 或 SSRI 单用；中重度推荐药物+CBT 联合","起效时间与疗程：药物起效 2–4 周，需 8–12 周足量评估；缓解后维持 ≥12 个月，缓慢停药","共病管理：伴抑郁、睡眠障碍与躯体疾病时需综合治疗；避免长期使用苯二氮䓬","睡眠卫生与咖啡因/酒精限制"],"life":["规律作息与运动（有氧运动可降低焦虑水平）","减少咖啡因、尼古丁与酒精摄入","压力管理与时间安排，设定可实现的担忧时间（「担忧时段」技术）","定期随访：急性期每 1–2 周、维持期每 1–3 个月","对于躯体化症状明显者，避免反复过度检查，建立信任与解释"]},"prog":"约 50%–60% 患者经规范治疗可缓解；起病早、病程长、合并抑郁或人格障碍者预后较差。复发率约 30%–50%（停药后 1 年内），需维持治疗 ≥12 个月并缓慢停药。","refs":["中华医学会精神医学分会. 中国焦虑障碍防治指南（2010，2019/2022 修订）","NICE. Generalised anxiety disorder and panic disorder in adults: management (CG113, 2011, updated 2020)","Canadian Anxiety Guidelines Initiative Group (2014)","APA. Guideline for the Treatment of Anxiety Disorders (2023 draft)"]}]},{"id":"emerg_psych","name":"精神科急症","rank":3,"summary":"谵妄以「找病因、护安全、对症少量用药」为原则，首选非药物干预，氟哌啶醇为首选药物并需监测 QT；酒精戒断按 CIWA-Ar 评分分层给药，苯二氮䓬类为基石，地西泮为首选，震颤谵妄需大剂量并纠正硫胺素、镁与电解质。","compare":[{"diseaseId":"ps_delirium","dx":"急性起病（数小时–数日）、注意力与意识水平波动、认知障碍（定向力、记忆、言语）随昼夜波动，常见于老年、感染、药物或手术后；可表现为高活动型、低活动型或混合型","key":"急性起病+注意力与意识波动+病情昼夜起伏，常伴躯体病因"},{"diseaseId":"ps_withdrawal","dx":"长期大量饮酒者突然减量或停酒后 6–24 h 出现震颤、出汗、心率加快、焦虑与失眠；12–48 h 可发生癫痫发作，48–96 h 出现震颤谵妄；CIWA-Ar 评分量化严重度","key":"停酒后按时间轴出现自主神经亢进，对苯二氮䓬迅速反应"}],"diseases":[{"id":"ps_delirium","name":"谵妄","aka":["Delirium","急性意识模糊状态","谵妄状态"],"rank":1,"basic":{"define":"一种急性、可逆的神经精神综合征，以注意力障碍、意识水平波动与认知功能改变为核心，常由躯体疾病、药物、中毒或环境因素诱发；在住院老年患者中患病率约 10%–30%，术后达 15%–50%，是死亡率与功能下降的独立危险因素。","risk":["高龄（≥65 岁）、认知障碍/痴呆","严重躯体疾病（感染、呼吸衰竭、心衰、肾衰、肝衰）、骨折与烧伤","多种用药（抗胆碱能药、苯二氮䓬、阿片类、糖皮质激素）、戒断状态","围手术期、ICU 留置导管、疼痛、睡眠剥夺、感觉剥夺（无眼镜/助听器）","脱水、电解质紊乱、低血糖、尿潴留与便秘"],"epi":"一般住院患者约 10%–30%，ICU 约 30%–50%，髋部骨折术后达 20%–50%；高龄者可达 50% 以上。谵妄使住院时间延长 2–3 倍，出院后 1 年死亡率升高 2–3 倍。低活动型占 40%–60%，常被漏诊。"},"patho":"神经元能量代谢不足与神经递质失衡：乙酰胆碱功能下降（抗胆碱能药物诱发），多巴胺过度活动（产生幻觉与激越），GABA/谷氨酸失调与神经炎症（IL-6、TNF-α）使血脑屏障通透性增加。睡眠-觉醒节律紊乱、慢性应激与皮质醇升高亦参与。不同病因（感染、药物、戒断、代谢）通过上述共同通路导致可逆的皮层-边缘系统功能障碍。","dx":{"criteria":["CAM（Confusion Assessment Method）四项：①急性起病或病情波动；②注意力障碍；③思维紊乱（言语不连贯、话题跳跃）；④意识水平改变（嗜睡或过度警觉）；①+② 加 ③或④ 阳性可诊断","病程数小时至数天，症状随昼夜波动（夜间加重）","分型：高活动型（激越、幻觉、多语、躁动，易识别）、低活动型（嗜睡、反应迟缓、情感淡漠，易漏诊）、混合型","4AT 床旁快速筛查（≥4 分提示谵妄）适用于急诊与非精神科病房","必须寻找病因：感染、代谢、电解质、低血糖、缺氧、药物（尤其抗胆碱能药与苯二氮䓬）、戒断、颅内病变","与痴呆鉴别：谵妄为急性起病与波动性，痴呆为慢性隐匿性认知下降"],"workup":["CAM/4AT 评估与生命体征、SpO₂、血糖","血常规、电解质（钠、钾、钙、镁）、肾功能、肝功能、血糖、血气、甲状腺功能","尿常规与培养、血培养（疑感染）；胸片（肺炎）","血药浓度（苯二氮䓬、三环类、锂盐、地高辛、抗胆碱能药）与尿毒物筛查","心电图（QT 间期、电解质影响因素）、头颅 CT/MRI（局灶体征、外伤、疑卒中）","腰穿：发热+脑膜刺激征或免疫抑制者","EEG：疑非惊厥性癫痫或严重代谢性脑病"],"grading":"CAM 阳/阴性；4AT 0–12 分（≥4 提示谵妄）；按活动型分：高活动型、低活动型、混合型；按严重度（DRS-98 或 ICDSC/ICU-CAM-ICU）；按病因分类（躯体、物质所致、戒断、多因素）。"},"ddx":[{"name":"酒精戒断（ps_withdrawal）","point":"与本类 ps_withdrawal 的鉴别点：谵妄可见于多种病因（感染、药物、代谢）；酒精戒断性谵妄（震颤谵妄）有长期酗酒史、停酒后 48–96 h 起病，伴明显自主神经亢进（心动过速、高热、出汗）与震颤，苯二氮䓬可迅速改善。"},{"name":"痴呆（阿尔茨海默病、血管性痴呆）","point":"慢性、隐匿起病，进行性认知下降，注意力相对保留，无急性波动；谵妄常发生在痴呆基础上（痴呆是谵妄的最大危险因素）。"},{"name":"抑郁症（假性痴呆）","point":"以心境低落与兴趣减退为主，认知下降与情绪相关，起病较缓，注意力检查可配合，无意识水平波动与幻觉。"},{"name":"非惊厥性癫痫持续状态、抗 NMDAR 脑炎","point":"意识改变伴 EEG 痫样放电或脑脊液抗体阳性；脑炎可有发热、头痛、精神行为异常与癫痫，需头颅 MRI 与腰穿。"},{"name":"急性精神病性障碍（精神分裂症急性发作）","point":"以幻觉妄想为核心、意识清晰、注意力基本保留，无明显急性波动与躯体病因；谵妄的幻觉多为片段性、视觉性，伴意识模糊。"}],"tx":{"drug":[{"name":"氟哌啶醇（首选用药）","dose":"口服 0.5–1 mg q2–4h 按需（老年 0.25–0.5 mg 起始，最大 5 mg/d）；肌注/静脉 0.5–1 mg（老年 0.25–0.5 mg），必要时 30–60 min 后重复，24 h 总量一般 ≤5–10 mg；需监测 QT 间期","note":"用于高活动型伴严重激越、幻觉或攻击行为，且非药物干预无效时；对有帕金森病、路易体痴呆者避免（加重锥体外系症状），改用喹硫平","renal":"肾功能不全减量（活性代谢物蓄积）","hepatic":"肝功能不全减量","interact":"与 QT 延长药（胺碘酮、氟喹诺酮、大环内酯）合用增加尖端扭转型室速；与锂盐合用增加神经毒性"},{"name":"喹硫平（替代，尤其帕金森/路易体痴呆）","dose":"12.5–25 mg 口服 qn 起始，按需增至 25–50 mg bid（老年最大约 100–200 mg/d）","note":"锥体外系反应少，适用于帕金森病与路易体痴呆患者；镇静与体位性低血压需监测","renal":"轻中度无需调整","hepatic":"肝功能不全减量并缓慢加量","interact":"CYP3A4 底物，与酮康唑、红霉素合用升高浓度；与中枢抑制剂叠加镇静"},{"name":"奥氮平（激越/攻击）","dose":"口服 2.5–5 mg qn 起始，可按需增至 10 mg/d（老年最大 5–10 mg/d）；肌注 2.5–5 mg（老年慎用）","note":"镇静强，用于急性激越；可致体位性低血压与过度镇静，避免用于意识明显抑制者","renal":"轻中度无需调整","hepatic":"肝功能不全减量","interact":"CYP1A2 底物：氟伏沙明升高浓度；吸烟降低浓度；与阿片类合用加重呼吸抑制"},{"name":"右美托咪定（ICU 谵妄/激越）","dose":"0.2–0.7 µg/kg/h 静脉泵入，按镇静水平滴定；需持续心电、血压监测","note":"用于 ICU 机械通气者的镇静与谵妄控制；可致心动过缓与低血压，不作为常规长期镇静","renal":"遵说明书","hepatic":"肝功能不全需减量并缓慢滴定","interact":"与 β 受体阻滞剂、丙泊酚合用加重低血压与心动过缓"},{"name":"苯二氮䓬类（仅限酒精戒断或特定情况）","dose":"劳拉西泮 0.5–1 mg 口服/静脉 q2–4h 按需（老年 0.25–0.5 mg）；地西泮 5 mg 口服/静脉；仅用于酒精/苯二氮䓬戒断相关谵妄或严重焦虑，不常规用于非戒断性谵妄","note":"非戒断性谵妄使用苯二氮䓬可加重意识模糊与跌倒（老年尤其），应避免；酒精戒断性谵妄为其首选","renal":"轻中度无需调整，重度减量","hepatic":"肝功能不全减量并延长间隔","interact":"与阿片类、其他中枢抑制剂合用加重呼吸抑制（黑框警告）"}],"nonDrug":["优先寻找并纠正病因：感染治疗、停用致谵妄药物、纠正低氧/低血糖/电解质紊乱、解除尿潴留与便秘、镇痛","非药物干预（一线）：定向力支持（时钟、日历、告知时间与地点）、家属陪伴、眼镜与助听器、白天光照与夜间昏暗、减少夜间操作与噪声、早期活动与睡眠保护","环境安全：防跌倒（床栏、低位床）、防拔管（必要时约束但按规范短期使用）","抗精神病药仅用于严重激越、幻觉、攻击或威胁安全时，且短期、低剂量、按需使用；症状控制后尽快减停","避免使用抗胆碱能药（苯海索、抗组胺药）与长效苯二氮䓬","对低活动型谵妄注意营养、补液与功能康复，避免被忽视"],"life":["出院前评估认知与功能，必要时转介康复与记忆门诊","跌倒与药物管理教育：避免多药联用与抗胆碱能药物","家属教育：识别谵妄（突然变糊涂、夜间加重）并及时就医","预防：住院高危患者（高龄、认知障碍、髋部骨折）实施多学科预防计划（HELP 方案）","谵妄后认知功能下降可持续数月，需随访与心理支持"]},"prog":"谵妄症状在病因纠正后多在数天内改善（平均 3–7 d），但住院期间病死率约 20%–30%（合并基础病者更高），出院后 1 年死亡风险增加 2–3 倍。约 30%–50% 患者出院时仍有认知损害或功能下降，需长期随访。","refs":["中华医学会精神医学分会. 中国谵妄防治专家共识（2019）","NICE. Delirium: prevention, diagnosis and management (CG103, 2010, updated 2023)","Inouye SK, et al. Delirium in elderly people. Lancet 2014;383:911-922","APA. Practice Guideline for the Treatment of Patients with Delirium (1999)"]},{"id":"ps_withdrawal","name":"酒精戒断综合征","aka":["Alcohol Withdrawal Syndrome","AWS","震颤谵妄"],"rank":2,"basic":{"define":"长期大量饮酒者突然减量或停酒后，因中枢神经系统抑制性适应（GABA 功能下降、谷氨酸能过度激活）而出现的神经精神症状群，从轻度震颤、焦虑、失眠到癫痫发作与震颤谵妄（DT）。","risk":["长期大量饮酒（每日 >4 标准杯或 >60 g 酒精）、每日饮酒史","既往戒断发作或震颤谵妄史（复发风险高 2–4 倍）","老年人、合并肝病与营养不良","合并感染、创伤、骨折、手术后或禁食（住院戒断风险高）","同时使用苯二氮䓬类或镇静药"],"epi":"约 50% 的酒精依赖者住院期间出现戒断症状，约 3%–5% 发展为震颤谵妄；震颤谵妄病死率达 5%–15%（未治疗时可达 20%–35%）。我国住院患者中酒精相关障碍与戒断识别率仍偏低。"},"patho":"长期酒精暴露使 GABA-A 受体下调、NMDA 受体上调（兴奋性适应）。突然停酒后，抑制性 GABA 活性锐减而兴奋性谷氨酸能过度激活，出现自主神经亢进（交感兴奋、心率加快、出汗）、震颤与癫痫阈值下降。持续兴奋与炎症可致震颤谵妄：意识模糊、幻觉、高热、自主神经剧烈波动与脱水。低镁、低钾、低血糖与硫胺素缺乏加重症状并增加并发症。","dx":{"criteria":["有长期大量饮酒史，末次饮酒后出现症状：6–24 h 震颤、出汗、焦虑、失眠、恶心；12–48 h 癫痫发作（多全面性）；48–96 h 震颤谵妄（意识模糊+幻觉+高热+心动过速）","CIWA-Ar 评分（10 项，0–67 分）量化严重度：<8 轻度、8–15 中度、>15 重度（或需药物干预）","自主神经亢进：心率 >100 次/分、收缩压升高、出汗、瞳孔扩大、震颤","震颤谵妄：意识模糊、定向障碍、视/听幻觉、明显震颤、发热（>38 ℃）、心动过速、血压波动、脱水","排除其他原因：低血糖、感染、肝性脑病、药物中毒/戒断（苯二氮䓬）、癫痫、颅内病变"],"workup":["详细饮酒史（酒量、频度、末次饮酒时间）、既往戒断/癫痫/DT 史","CIWA-Ar 评分每 4–8 h（重度每 1–2 h）","血糖（立即测）、电解质（钾、镁、钙）、血常规、肝功能、凝血、血氨、肾功能","心电图（QT、心律失常、低钾影响）与生命体征","尿毒物筛查、血/尿酒精浓度（辅助）","感染筛查（胸片、尿常规、血培养）；疑 DT 头颅 CT（排除外伤/卒中）","硫胺素与营养状态评估（Wernicke 脑病风险）"],"grading":"按 CIWA-Ar：轻度（<8，可支持治疗）、中度（8–15，症状触发给药）、重度（>15，规律给药并住院）；按临床阶段：自主神经症状（6–24 h）、癫痫（12–48 h）、震颤谵妄（48–96 h）；DT 为最严重阶段，需 ICU 监护。"},"ddx":[{"name":"谵妄（ps_delirium，非戒断性）","point":"与本类 ps_delirium 的鉴别点：非戒断性谵妄可由感染、药物、代谢等引起，不伴停酒时间轴与典型自主神经亢进；酒精戒断性 DT 有明确停酒后 48–96 h 起病、震颤与大汗，苯二氮䓬迅速改善。"},{"name":"苯二氮䓬/镇静催眠药戒断","point":"症状与酒精戒断相似，但无饮酒史、有长期苯二氮䓬使用史，戒断时间轴不同（短效药物 1–2 d，长效 3–7 d），尿检可帮助鉴别。"},{"name":"低血糖、甲状腺危象","point":"低血糖可致出汗、心悸、意识改变，血糖 <3.9 mmol/L 且补糖后迅速改善；甲亢有 TSH 降低与甲状腺肿大，戒断者不能仅凭症状判断。"},{"name":"肝性脑病","point":"肝硬化患者停酒后出现意识改变，伴扑翼样震颤、血氨升高、黄疸与腹水；可与戒断重叠，需同时治疗。"},{"name":"感染、创伤、癫痫（原发性）","point":"发热与局灶体征、脑膜刺激征、头颅外伤需 CT/腰穿；戒断性癫痫多为全面性且无局灶体征，但首次发作需排除器质性病因。"}],"tx":{"drug":[{"name":"地西泮（首选苯二氮䓬）","dose":"症状触发给药：CIWA-Ar 8–15 时 10–20 mg 口服 q1–2h 至评分下降；重度/DT：10–20 mg 口服或静脉 q1–2h，按需增量（DT 可需 100 mg/d 以上，需 ICU 严密监测）；负荷方案：10 mg 口服/静脉 q6h ×4 次，之后按评分调整；疗程一般 3–5 d 后逐渐减量","note":"长效苯二氮䓬，作用平稳，是戒断治疗金标准；需监测呼吸抑制与过度镇静（尤其老年、COPD、肝功能不全）","renal":"轻中度无需调整，重度慎用","hepatic":"重度肝功能不全半衰期延长，减量并缩短疗程，可选劳拉西泮（不经肝脏氧化代谢）","interact":"与阿片类、其他中枢抑制剂合用加重呼吸抑制（黑框警告）；经 CYP2C19/3A4 代谢，与奥美拉唑、酮康唑相互作用"},{"name":"劳拉西泮（替代，肝功能不全者）","dose":"症状触发：1–2 mg 口服/静脉 q2–4h 按需；DT 时 2–4 mg 静脉 q15–30 min 直至控制；负荷 1–2 mg q2h 至评分下降","note":"经葡萄糖醛酸化代谢，肝功能不全者安全；半衰期中等，适合住院滴定","renal":"轻中度无需调整","hepatic":"肝功能不全优选（主要经葡萄糖醛酸化）","interact":"与其他中枢抑制剂联用加倍呼吸抑制"},{"name":"硫胺素（维生素 B₁）","dose":"100–300 mg 静脉/肌注，在葡萄糖输注前或同时给予；疑 Wernicke 脑病者 500 mg 静脉 q8h ×2 d，之后 250–500 mg qd ×3–5 d，再改为口服 100 mg tid","note":"预防 Wernicke 脑病（眼肌麻痹、共济失调、意识模糊），酒精依赖者常规补充；葡萄糖输注前必须给予硫胺素","renal":"遵说明书","hepatic":"遵说明书","interact":"部分药物（如氟尿嘧啶）可拮抗硫胺素作用"},{"name":"硫酸镁（纠正低镁）","dose":"低镁（<0.7 mmol/L）或震颤/癫痫：25% 硫酸镁 2–4 g 加入生理盐水 100 mL 静脉滴注（1–2 h），必要时重复；监测膝反射与呼吸","note":"低镁是戒断性癫痫与心律失常的危险因素，需补充；肾功能不全减量并监测血镁","renal":"eGFR <30 减量并监测血镁","hepatic":"遵说明书","interact":"与神经肌肉阻滞剂、钙通道阻滞剂合用加重肌无力与低血压"},{"name":"纳洛酮/双硫仑/阿坎酸（维持戒酒）","dose":"纳洛酮 50 mg qd 口服（戒断期间不开始，需戒酒后）；阿坎酸 666 mg tid 口服；双硫仑 250 mg qd（需患者知情并监测肝功能）","note":"用于戒断治疗后的长期维持，减少复发；双硫仑与酒精反应严重，肝功能不全禁用","renal":"纳洛酮 eGFR <30 减量；阿坎酸重度肾功能不全减量","hepatic":"双硫仑活动性肝病禁用；纳洛酮重度肝功能不全慎用","interact":"纳洛酮与阿片类相拮抗；双硫仑与含酒精制剂（漱口水、糖浆）产生双硫仑样反应"},{"name":"多巴胺拮抗剂/止吐药（辅助）","dose":"甲氧氯普胺 10 mg 静脉 q6h（短期）；昂丹司琼 4–8 mg 静脉 q8h；避免使用氟哌啶醇作为 DT 首选","note":"仅止吐辅助；甲氧氯普胺可致锥体外系反应，酒精依赖者慎用","renal":"甲氧氯普胺肾功能不全减量","hepatic":"遵说明书","interact":"昂丹司琼与 QT 延长药合用注意心电图；甲氧氯普胺与抗精神病药合用增加 EPS"}],"nonDrug":["环境：安静的病房、夜间照明、定向力支持；避免强光与噪音；必要时专人看护（防跌倒与自伤）","液体与营养：静脉补液纠正脱水，维持电解质（钾 4.0–5.0 mmol/L、镁 ≥0.8 mmol/L），葡萄糖输注前给硫胺素","体温与生命体征：DT 患者每 15–30 min 监测心率、血压、体温与尿量；高热（>38.5 ℃）需物理降温并寻找感染","监测：CIWA-Ar 评分与镇静水平（RASS）每 1–2 h，调整苯二氮䓬剂量","癫痫发作：发作超过 5 min 或短时内反复发作按癫痫持续状态处理（静脉苯二氮䓬）；首次发作需头颅 CT 与 EEG","戒断期禁止突然停药，按方案逐渐减量；期间避免使用抗精神病药替代苯二氮䓬（降低癫痫阈值）"],"life":["戒断处理完成后进入长期戒酒维持：纳洛酮/阿坎酸/双硫仑 + 心理社会干预（CBT、动机增强治疗、互助小组）","营养与维生素补充，纠正叶酸、B 族维生素缺乏；随访肝功能与超声","家庭支持与酒精相关肝病随访（FibroScan/超声）","孕期酒精依赖者需产科与精神科联合管理，避免戒断性癫痫","复发识别：饮酒量增加、戒断症状再现时及时就诊"]},"prog":"轻度戒断 3–5 d 内自行缓解；癫痫发作多短暂自限但需处理；震颤谵妄未治疗病死率 5%–15%，重视ICU监护与苯二氮䓬滴定可显著降低。戒断后 1 年内复发率高（约 50%–70%），需要长期维持治疗与社会支持。","refs":["中华医学会精神医学分会. 酒精相关障碍诊疗指南（2020）","ASAM. The ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020)","NICE. Alcohol-use disorders: diagnosis and management of physical complications (CG100, 2010, updated 2017)","WHO. The ICD-10 Classification of Mental and Behavioural Disorders: alcohol dependence"]}]},{"id":"anxiety_spectrum","name":"焦虑与应激相关障碍","rank":4,"summary":"强迫与PTSD以心理治疗为主、药物足量长程辅助：OCD需SSRI高剂量并维持1-2年；PTSD首选创伤聚焦CBT或EMDR；惊恐与社交焦虑首选SSRI、起效前短期用苯二氮䓬；躯体症状障碍合理排除器质性病因后以CBT重建认知。SSRI/SNRI有自杀观念黑框警告(<25岁及治疗初期)、苯二氮䓬有与阿片类合用致呼吸抑制的黑框警告。","compare":[{"diseaseId":"ps_ocd","dx":"强迫思维引焦虑并以仪式中和、耗时>1 h/d、Y-BOCS评估","key":"强迫思维与行为循环、需高剂量SSRI"},{"diseaseId":"ps_ptsd","dx":"明确创伤后再体验、回避与高警觉三联征>1个月","key":"有创伤时间点、一线为心理治疗"},{"diseaseId":"ps_panic","dx":"非预期惊恐发作数分钟达峰、≥1个月担心再发或回避","key":"发作性自主神经风暴、间期正常"},{"diseaseId":"ps_social_anxiety","dx":"社交情境持续≥6个月怕负面评价、回避或强忍","key":"由社交情境触发、呈回避模式"},{"diseaseId":"ps_somatic","dx":"多系统躯体症状伴过度关注与反复就医>6个月","key":"先排除器质病因、症状与证据不成比例"}],"diseases":[{"id":"ps_ocd","name":"强迫症","aka":["OCD","Obsessive-Compulsive Disorder","强迫性障碍"],"rank":1,"basic":{"define":"反复、侵入、难以抵抗的强迫思维，以及为缓解焦虑的重复仪式；耗时且致显著痛苦或功能损害、自知力可中度至缺失。","risk":["一级亲属患病、早发者遗传度约40%","多起病于青少年、产后为发病高峰","儿童链球菌感染后可急性起病","共病焦虑抑郁、抽动障碍"],"epi":"终生患病率约2%-3%、我国约1.6%-2.4%；起病到首治平均延迟7-11年。"},"patho":"皮质-纹状体-丘脑-皮质环路过度激活伴5-HT功能异常、可解释SSRI有效而NE再摄取抑制剂无效；仪式短期缓解焦虑形成负强化。","dx":{"criteria":["反复侵入性强迫思维、多不受欢迎并引起焦虑","强迫行为(洗涤、检查、计数)旨在减焦虑、与事件无现实联系或过度","耗时>1 h/d或显著痛苦、功能损害","排除物质、躯体疾病及精分等所致","Y-BOCS：8-15轻、16-23中、24-31重、32-40极重","评估自知力与共病抽动"],"workup":["症状与回避清单、耗时；Y-BOCS、PHQ-9、GAD-7","甲功、血常规；儿童骤起病查链球菌证据"],"grading":"按Y-BOCS分轻/中/重/极重；按自知力分良好/差/缺乏；难治指≥2种足量方案12周无效。"},"ddx":[{"name":"惊恐障碍(ps_panic)","point":"惊恐突发10-20 min缓解；OCD慢性、每日由思维触发以仪式缓解。"},{"name":"社交焦虑障碍(ps_social_anxiety)","point":"后者核心为怕负面评价；OCD社交回避继发于仪式耗时。"},{"name":"广泛性焦虑障碍(ps_gad)","point":"GAD为弥散担忧、无固定侵入思维与仪式。"},{"name":"精神分裂症(ps_schizo)","point":"精分强迫可为妄想性伴阴性症状；OCD多保留质疑。"},{"name":"抽动障碍与强迫型人格","point":"抽动为不自主运动；强迫型人格无侵入思维。"}],"tx":{"drug":[{"name":"氟西汀","dose":"20 mg qd起、目标40-60 mg/d、足量12周评估","note":"剂量高于抑郁、起效6-12周；黑框：<25岁初期自杀观念风险升高。","renal":"重度肾损遵说明书减量","hepatic":"肝损减量","interact":"CYP2D6强抑制；与MAOI禁忌；与NSAIDs或抗凝药增出血"},{"name":"舍曲林","dose":"50 mg qd起、可至150-200 mg/d","note":"相互作用少、常作一线；缓解后维持1-2年。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与华法林监测出血；与曲马多警惕5-HT综合征"},{"name":"氟伏沙明","dose":"50 mg qn起、至200-300 mg/d分次","note":"CYP1A2、2C19强抑制。","renal":"重度肾损减量","hepatic":"肝损低剂量起","interact":"禁与替扎尼定、硫利达嗪合用；升高氯氮平、茶碱浓度"},{"name":"氯米帕明(二线)","dose":"25 mg qn起、每3-5天加25 mg、100-250 mg/d","note":"心脏毒性、过量致死性高、用前查心电图。","renal":"肾损慎用","hepatic":"肝损减量","interact":"与MAOI禁忌；与SSRI合用致5-HT综合征；降低癫痫阈值"},{"name":"利培酮/阿立哌唑(增效)","dose":"利培酮0.5 mg qn起至1-4 mg/d；阿立哌唑2-5 mg/d起至10-15 mg/d","note":"黑框：老年痴呆相关精神病者死亡风险增加。","renal":"利培酮重度肾损减半","hepatic":"利培酮重度肝损慎用","interact":"CYP2D6或3A4抑制剂升高利培酮浓度"}],"nonDrug":["暴露与反应预防(ERP)为金标准、12-20次、与SSRI合用优于单药","认知治疗修正高估威胁与过度责任感","家庭干预减少家属代为完成仪式","深部脑刺激仅限高度难治病例"],"life":["每日30-60 min暴露练习","缓解后SSRI至少维持1-2年","避免骤停；限制酒精咖啡因","仪式耗时增加即复诊"]},"prog":"病程多慢性波动、约60%持续或反复；ERP加足量SSRI约50%-60%有效、仅约20%完全缓解。早发、共病抽动者预后差。","refs":["中国强迫症防治指南(2016)","中国精神障碍诊疗规范(2020)","NICE CG31 OCD and BDD"]},{"id":"ps_ptsd","name":"创伤后应激障碍","aka":["PTSD","Post-Traumatic Stress Disorder","创伤后应激"],"rank":2,"basic":{"define":"暴露于死亡威胁、严重伤害或性暴力后、出现侵入性再体验、持续回避与高警觉>1个月、造成显著功能损害。","risk":["女性、既往创伤、低社会支持","人际暴力、性侵或战争","创伤时解离或麻木","既往精神病史、物质滥用"],"epi":"终生患病率约6%-8%；我国12个月约0.3%-0.5%、灾难后1个月可达10%-30%、约1/3迁延难治。"},"patho":"恐惧条件化过度与消退障碍：杏仁核过度激活、vmPFC抑制减弱、海马体积减小致线索泛化；急性期儿茶酚胺升高而HPA轴负反馈受抑。回避通过负强化维持症状。","dx":{"criteria":["暴露于创伤事件、含职业性接触创伤细节","再体验≥1项：闯入性记忆、噩梦、闪回、线索触发强烈反应","回避≥1项：回避创伤相关想法、感受或人物地点","负性认知情绪≥2项：细节遗忘、持续自责、兴趣减少、疏离","警觉改变≥2项：易激惹、鲁莽、过度警觉、惊跳增强、睡眠障碍","病程>1个月；PCL-5≥33提示可能PTSD"],"workup":["PCL-5、CAPS-5访谈；PHQ-9、AUDIT与自杀风险","排除颅脑伤后遗症、慢性疼痛、甲亢；睡眠差者筛OSA"],"grading":"按DSM-5分轻/中/重(PCL-5 0-80)；复杂型PTSD另伴情感调节障碍与自我概念受损；≥6个月起病为迟发型。"},"ddx":[{"name":"惊恐障碍(ps_panic)","point":"惊恐非预期突发10-20 min；PTSD惊恐样反应由创伤线索触发伴闪回。"},{"name":"强迫症(ps_ocd)","point":"OCD侵入伴仪式；PTSD侵入直接复现创伤场景。"},{"name":"躯体症状障碍(ps_somatic)","point":"以多系统症状与过度就医为主、无创伤再体验。"},{"name":"抑郁障碍(ps_depression)","point":"抑郁认知弥散无创伤触发点；PTSD有创伤时间、常共病。"},{"name":"边缘型人格障碍(ps_personality)","point":"BPD早发以人际不稳为核心；创伤症状晚发者更支持PTSD。"}],"tx":{"drug":[{"name":"舍曲林(一线)","dose":"25-50 mg qd起、1-2周后100-200 mg/d","note":"单药疗效弱于心理治疗；黑框：<25岁初期自杀观念风险升高。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与华法林增出血；与曲马多警惕5-HT综合征"},{"name":"帕罗西汀","dose":"20 mg qd起、可至40 mg/d(最高50 mg)","note":"撤药反应明显需缓慢减停；黑框同上。","renal":"重度肾损20 mg/d起","hepatic":"肝损10 mg qd起","interact":"CYP2D6强抑制；与MAOI、硫利达嗪禁忌"},{"name":"哌唑嗪(噩梦增效)","dose":"1 mg qn起、常用2-15 mg qn","note":"首剂体位性低血压与晕厥、须卧床前服。","renal":"慎用","hepatic":"肝损减量","interact":"与PDE5抑制剂或降压药合用致严重低血压"},{"name":"喹硫平(难治性增效)","dose":"25-50 mg qn起至150-300 mg qn","note":"黑框：老年痴呆相关精神病者死亡风险增加。","renal":"肾损慎用","hepatic":"肝损低剂量起","interact":"CYP3A4抑制剂或诱导剂显著影响浓度"}],"nonDrug":["创伤聚焦CBT与延长暴露(PE)为一线、12-18次","EMDR为并列一线","高自杀风险或BPD者先稳定化再处理创伤","灾后1个月内以心理急救观察为主"],"life":["建立安全环境与安全计划","戒酒或限量","家属创伤知情沟通、不强迫讲述","每4-8周复评PCL-5"]},"prog":"约30%-50%患者3个月内缓解、其余可慢性化；共病抑郁与自杀风险升高。规范心理治疗约60%-70%明显改善。","refs":["中国创伤后应激障碍防治指南(2015)","中国精神障碍诊疗规范(2020)","NICE NG116 PTSD"]},{"id":"ps_panic","name":"惊恐障碍","aka":["Panic Disorder","Panic Attack","惊恐发作","广场恐怖"],"rank":3,"basic":{"define":"反复非预期性惊恐发作(恐惧数分钟内达峰)、持续≥1个月担心再发或其后果、或出现行为改变、可伴广场恐怖。","risk":["女性为男性2-3倍、起病高峰20-25岁","焦虑敏感性高、对心悸气促过度警觉","一级亲属患病、遗传度约40%","咖啡因、酒精、可卡因；甲亢可致类似发作"],"epi":"全球终生患病率约1.7%-4.7%、我国约0.3%-0.6%；约1/3伴广场恐怖、近半数首诊误为心脏病。"},"patho":"杏仁核-岛叶-前额叶对躯体感觉过度敏感：灾难化解读心悸眩晕、触发交感激活与换气过度、低碳酸血症加重头晕麻木形成正反馈。回避行为负强化维持病程。","dx":{"criteria":["反复非预期发作、数分钟内达峰(多10-20 min)","伴≥4项：心悸、出汗、震颤、气短、胸痛、恶心、头晕、寒战潮热、解体、怕失控、怕死","发作后≥1个月担心再发或行为改变回避","排除甲亢、心律失常、低血糖、嗜铬细胞瘤、哮喘与物质所致","评估广场恐怖范围与共病抑郁"],"workup":["PDSS、HAMA、GAD-7","心电图、动态心电图(疑心律失常)","电解质、血糖、甲功、血钙","40岁以上不典型胸痛排除ACS；疑哮喘查肺功能"],"grading":"按类型分非预期、情境触发、情境倾向性；分伴或不伴广场恐怖；按PDSS分轻/中/重。"},"ddx":[{"name":"强迫症(ps_ocd)","point":"OCD由侵入思维触发、慢性伴仪式；惊恐发作性、间期可无症状。"},{"name":"社交焦虑障碍(ps_social_anxiety)","point":"社交焦虑由被审视情境驱动、独处缓解；惊恐可非预期突发。"},{"name":"PTSD(ps_ptsd)","point":"PTSD惊恐样反应由创伤线索或闪回触发伴回避。"},{"name":"广泛性焦虑障碍(ps_gad)","point":"GAD为慢性弥散担忧、无数分钟达峰的发作。"},{"name":"冠心病与心律失常","point":"ACS胸痛持续数分钟以上伴心电图与肌钙蛋白异常；惊恐间期正常、首发须排除。"},{"name":"甲亢、嗜铬细胞瘤、低血糖","point":"分别有TSH降低、阵发高血压伴大汗、Whipple三联征。"}],"tx":{"drug":[{"name":"舍曲林","dose":"12.5-25 mg qd起、1周后50 mg、可至150-200 mg/d","note":"一线、4-8周起效、早期可加重焦虑；黑框：<25岁初期自杀观念风险升高。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与NSAIDs、华法林增出血"},{"name":"帕罗西汀","dose":"10 mg qd起、1周后20 mg、可至40-60 mg/d","note":"起效快但撤药反应常见；黑框同上。","renal":"重度肾损10 mg/d起","hepatic":"肝损10 mg/d起","interact":"CYP2D6强抑制、升高TCAs浓度；与MAOI禁忌"},{"name":"艾司西酞普兰","dose":"5-10 mg qd起、10-20 mg/d(最大20 mg)","note":"QTC延长风险、心脏病者监测心电图。","renal":"重度肾损减量","hepatic":"肝损最大10 mg/d","interact":"与MAOI禁忌；避免与QT延长药联用"},{"name":"阿普唑仑(短期桥接)","dose":"0.25-0.5 mg bid-tid按需、仅2-4周","note":"黑框：与阿片类合用致严重呼吸抑制与死亡；长期致依赖。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"与阿片类、酒精协同抑制呼吸；CYP3A4抑制剂升高浓度"},{"name":"劳拉西泮(替代桥接)","dose":"0.5-1 mg bid-tid按需","note":"半衰期10-20 h适合桥接；黑框同阿普唑仑。","renal":"肾损慎用","hepatic":"严重肝损禁用","interact":"与阿片类、酒精、丙戊酸加强镇静"}],"nonDrug":["CBT(认知重建加内感受性与情境暴露)为一线、12-16次","呼吸训练与渐进肌肉放松","发作时用接地技术、不以逃避应对","难治者SSRI联用CBT、必要时加丁螺环酮"],"life":["戒咖啡因、尼古丁与酒精","逐级情境暴露","限制反复躯体检查与自查","稳定后SSRI维持12个月再缓慢减停"]},"prog":"慢性波动、约1/3长期不愈；规范治疗70%-80%显著改善、停药后复发25%-50%。伴广场恐怖或就诊延迟者预后差。","refs":["中国焦虑障碍防治指南(2016)","中国精神障碍诊疗规范(2020)","NICE CG113 GAD and panic disorder"]},{"id":"ps_social_anxiety","name":"社交焦虑障碍与特定恐怖症","aka":["Social Anxiety Disorder","SAD","社交焦虑症","Specific Phobia","特定恐怖症"],"rank":4,"basic":{"define":"社交焦虑：对被审视的社交或表演情境持续≥6个月显著恐惧负面评价、回避或强忍。特定恐怖症：对特定物体或情境(动物、高度、飞行、血液注射、密闭空间)过度恐惧与回避。","risk":["女性多见；社交焦虑起病13-24岁、恐怖症7-13岁","行为抑制气质、童年被欺凌","一级亲属焦虑障碍、遗传度约30%-50%","共病抑郁与酒精使用障碍"],"epi":"社交焦虑终生约3%-7%(我国约2%-3%)；特定恐怖症约5%-10%、治疗率不足20%。"},"patho":"社交焦虑以自我聚焦注意力与负性自我意象为核心、伴事后反刍、杏仁核对轻蔑面孔过度反应；安全行为阻止预期失调学习。特定恐怖症为条件化与消退失败、血液注射型有血管迷走性晕厥。","dx":{"criteria":["对≥1种被审视情境显著害怕(发言、进食、与陌生人交谈)","怕表现焦虑症状或遭负面评价；情境几乎必然引发恐惧","回避或强忍伴强烈焦虑≥6个月且有功能损害","排除物质、口吃震颤及惊恐、GAD、躯体变形障碍","恐怖症：对特定对象显著恐惧≥6个月、接触几乎立即焦虑","社交焦虑分表演型与广泛型"],"workup":["LSAS、SPIN、SIAS；共病筛查","震颤口吃等必要时专科评估","血液注射型查晕厥史与心电图","排除甲亢与物质所致"],"grading":"LSAS：0-50轻、50-70中、70-90重、90-144很重；恐怖症按刺激类型与能否独自接触分级。"},"ddx":[{"name":"惊恐障碍(ps_panic)","point":"惊恐可独处非预期突发；社交焦虑由社交情境预期触发。"},{"name":"强迫症(ps_ocd)","point":"OCD有侵入思维与仪式；社交焦虑独处时明显减轻。"},{"name":"躯体症状障碍(ps_somatic)","point":"后者关注症状与患病恐惧；社交焦虑的颤抖是「被看到」的媒介。"},{"name":"PTSD(ps_ptsd)","point":"PTSD社交回避继发于创伤线索伴再体验；社交焦虑为多年预期恐惧。"},{"name":"回避型人格障碍(ps_personality)","point":"后者为广泛自卑、早年起病；社交焦虑可局限特定情境。"},{"name":"广泛性焦虑障碍(ps_gad)","point":"GAD担忧弥散、无特定社交情境恐惧。"}],"tx":{"drug":[{"name":"舍曲林","dose":"25 mg qd起、1周后50 mg、可至200 mg/d","note":"一线、起效6-12周；黑框：<25岁初期自杀观念风险升高。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与华法林、NSAIDs增出血"},{"name":"帕罗西汀","dose":"10-20 mg qd起、可至40-60 mg/d","note":"起效快、撤药反应明显；黑框同上。","renal":"重度肾损减量","hepatic":"肝损10 mg起","interact":"CYP2D6强抑制；与MAOI禁忌"},{"name":"文拉法辛缓释","dose":"37.5-75 mg qd起、渐至150-225 mg/d","note":"剂量依赖性血压升高、停药缓慢减量。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"与MAOI禁忌；与曲马多警惕5-HT综合征"},{"name":"普萘洛尔(表演型按需)","dose":"10-20 mg 表演前30-60 min单次","note":"仅缓解手抖心悸；哮喘、心动过缓、房室阻滞禁用。","renal":"肾损慎用","hepatic":"肝损减量","interact":"与维拉帕米、地尔硫卓合用致心动过缓；可掩盖低血糖"},{"name":"奥沙西泮/劳拉西泮(按需)","dose":"奥沙西泮10-15 mg或劳拉西泮0.5-1 mg","note":"仅限重要场合；黑框：与阿片类合用致呼吸抑制。","renal":"肾损减量","hepatic":"严重肝病禁用","interact":"与阿片类、酒精协同抑制"}],"nonDrug":["CBT为一线：注意力再训练、行为实验、角色扮演与录像反馈","团体CBT便于现场练习","恐怖症用系统脱敏或虚拟现实暴露、集中暴露常可治愈","血液注射型用肌紧张法防晕厥"],"life":["从点餐到当众演讲逐级暴露","减少低头、玩手机等安全行为","戒酒精自我用药","学校单位提供渐进参与支持"]},"prog":"社交焦虑慢性波动、平均病程15-20年；CBT约70%显著改善、SSRI约50%-60%有效。特定恐怖症自然缓解不足20%、暴露治疗改善可达80%以上。","refs":["中国焦虑障碍防治指南(2016)","中国精神障碍诊疗规范(2020)","Canadian Social Anxiety Disorder Guidelines(2014)"]},{"id":"ps_somatic","name":"躯体形式障碍与疾病焦虑","aka":["Somatic Symptom Disorder","Illness Anxiety Disorder","Hypochondriasis","躯体症状障碍","疑病症"],"rank":5,"basic":{"define":"躯体症状障碍：≥1种躯体症状伴与严重度不成比例的持续思维、焦虑与行为>6个月。疾病焦虑：对患严重疾病的先占观念≥6个月、躯体症状轻或缺失。","risk":["女性约2倍；童年躯体化经验与健康关注习得","共病焦虑抑郁、神经质与述情障碍","不必要检查与手术史、医源性强化","共病IBS、纤维肌痛"],"epi":"一般人群约5%-7%；基层医疗中20%-30%就诊者症状难以充分用器质病变解释、共病焦虑抑郁达50%-70%。"},"patho":"症状感知-归因-灾难化放大环路：对心跳肠鸣过度警觉并灾难化解读、唤起焦虑、交感激活又加重躯体感受。内感受精确度异常与岛叶过度激活有实验证据；家属强化维持病程。","dx":{"criteria":["≥1种持续困扰的躯体症状并中断日常生活","伴与严重度不成比例的持续思维","对健康过度关注、为症状花费过多精力>6个月","疾病焦虑：患病先占观念≥6个月、分求助型或回避型","排除惊恐、抑郁、躯体变形障碍","完成必要而非无穷尽的排除性检查"],"workup":["血常规、生化、甲功、必要时心电图、胸片","汇总既往检查避免重复","PHQ-15、SSS-8、HAI、PHQ-9、GAD-7","按罗马Ⅳ评估功能性综合征；必要时精神科会诊"],"grading":"按症状负荷(PHQ-15：5-9、10-14、≥15)与心理行为反应两维分轻/中/重。"},"ddx":[{"name":"惊恐障碍(ps_panic)","point":"惊恐为发作性短时心肺症状风暴；躯体症状障碍为持续多系统症状伴过度就医。"},{"name":"广泛性焦虑障碍(ps_gad)","point":"GAD担忧弥散；躯体症状障碍健康关注固定且以躯体症状为主诉。"},{"name":"强迫症(ps_ocd)","point":"OCD反复检查为仪式；躯体症状障碍反复就诊为求确认。"},{"name":"社交焦虑障碍(ps_social_anxiety)","point":"后者回避社交；躯体症状障碍回避疾病与检查。"},{"name":"抑郁障碍(ps_depression)","point":"抑郁躯体症状随心境改善缓解；躯体症状障碍持续>6个月且不成比例。"},{"name":"隐匿性器质疾病(甲亢、SLE、MS、副肿瘤)","point":"有客观阳性体征与化验影像证据、须先排除并定期复核。"},{"name":"躯体变形障碍、做作性障碍与诈病","point":"分别以外观缺陷、扮演病人与外部获益为动机。"}],"tx":{"drug":[{"name":"舍曲林","dose":"25-50 mg qd起、渐至100-200 mg/d","note":"可改善共病焦虑抑郁；黑框：<25岁初期自杀观念风险升高。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与NSAIDs、抗凝药增出血"},{"name":"氟西汀","dose":"20 mg qd起、可至40-60 mg/d","note":"撤药反应轻；疗程6-12个月。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"CYP2D6抑制剂；与MAOI、曲马多禁忌"},{"name":"文拉法辛缓释(共病疼痛)","dose":"75 mg qd起、可至150-225 mg/d","note":"用于共病纤维肌痛样疼痛；监测血压。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"与MAOI禁忌；5-HT综合征风险"},{"name":"曲唑酮/米氮平(助眠)","dose":"曲唑酮25-50 mg qn；米氮平7.5-15 mg qn","note":"仅针对共病失眠；米氮平注意体重增加。","renal":"肾损慎用","hepatic":"肝损减量","interact":"与曲马多、MAOI合用有5-HT综合征风险"}],"nonDrug":["CBT为一线：修正灾难化归因、限制反复检查与网络自查、渐进减少就诊","分级躯体活动、避免卧床与患者角色强化","正念认知疗法与接纳承诺疗法","与患者约定单次就诊原则与随访间隔","多学科沟通统一目标、家属教育"],"life":["记症状日记并限时自查","规律作息与有氧运动","以功能与生活质量为目标","共病器质疾病者每6-12个月评估"]},"prog":"慢性波动、单用药物改善有限；CBT可使约40%-50%症状与过度关注显著减轻。病程>2年、共病人格障碍者预后差。","refs":["中国精神障碍分类与诊断标准(CCMD-3)","中国精神障碍诊疗规范(2020)","中国躯体形式障碍诊治专家共识(2017)"]}]},{"id":"psych_other","name":"其他精神障碍","rank":5,"summary":"人格障碍以心理治疗为核心、药物仅对症；进食障碍先纠正低体重与电解质紊乱、再喂养综合征为致命风险；产后抑郁用EPDS筛查、产后精神病属急症；成人ADHD以兴奋剂或托莫西汀长期治疗；慢性失眠以CBT-I为一线、唑吡坦仅限短期。精神药物须核对黑框警告(自杀观念、滥用依赖、老年痴呆死亡风险、呼吸抑制)与相互作用。","compare":[{"diseaseId":"ps_personality","dx":"人格特质长期僵化、早年发病跨情境损害；BPD以情绪不稳与冲动自伤为核心","key":"人格模式早发持续、药物仅辅助"},{"diseaseId":"ps_eating","dx":"厌食BMI<17.5伴怕胖与体像障碍；贪食为暴食加代偿、每周≥1次≥3个月","key":"先评估低钾、心律失常与再喂养风险"},{"diseaseId":"ps_postpartum","dx":"产后抑郁4周内起病、EPDS≥13；产后精神病2周内急性幻觉妄想","key":"EPDS筛查、产后精神病立即急诊"},{"diseaseId":"ps_adhd","dx":"注意缺陷和/或多动冲动早于12岁、≥2个领域损害","key":"症状须回溯至12岁前"},{"diseaseId":"ps_insomnia","dx":"入睡困难或早醒伴日间损害、每周≥3次≥3个月","key":"首选CBT-I、药物为短期次选"}],"diseases":[{"id":"ps_personality","name":"人格障碍(A/B/C 组与边缘型人格障碍)","aka":["Personality Disorder","边缘型人格障碍","BPD","Borderline Personality Disorder"],"rank":1,"basic":{"define":"人格特质长期僵化偏离文化期望、起于成年早期、多情境致痛苦或功能损害。A组(偏执、分裂样、分裂型)、B组(反社会、边缘、表演、自恋)、C组(回避、依赖、强迫型)。","risk":["童年虐待与忽视、BPD中60%-75%有虐待史","BPD遗传度约40%-70%","早年依恋紊乱与情感无效化","A组与精分谱系遗传相关、C组与焦虑易感相关"],"epi":"一般人群约9%-13%、BPD约1%-2%；BPD自杀未遂终生风险约70%、自杀死亡约8%-10%。"},"patho":"遗传易感(冲动性与情绪反应性)叠加早年逆境：自伤被用作调节强烈情绪的手段、形成怕被抛弃-冲突-内疚-自伤循环。杏仁核过度激活、前额叶调节减弱；情感无效化环境阻碍自我安抚。","dx":{"criteria":["人格特质持久僵化、起于成年早期、跨情境致损害","BPD需≥5/9项：怕被抛弃、理想化与贬低、身份紊乱、冲动、自伤威胁、情绪不稳、空虚、愤怒失控、应激性偏执","A组：偏执(不信任)、分裂样(疏离淡漠)、分裂型(奇特信念)","C组：回避(自卑抑制)、依赖(过度依附)、强迫型(完美刻板)","排除物质、器质疾病与精分双相所致","单独评估自伤与自杀风险"],"workup":["人格评估结合长期观察与知情人信息(SCID-5-PD)","自伤史与C-SSRS自杀评估","共病筛查PHQ-9、AUDIT、SCOFF、PTSD","尿毒物筛查排除物质所致"],"grading":"DSM-5按A/B/C三组；ICD-11改为维度(负性情感、疏离、强迫性、去抑制、精神病性)；BPD按自伤风险与依从性分层。"},"ddx":[{"name":"PTSD(ps_ptsd)","point":"PTSD有创伤时间点以再体验为核心；BPD人际不稳与身份紊乱早发跨情境。"},{"name":"抑郁障碍(ps_depression)","point":"抑郁发作性、间歇期基本恢复；BPD情绪随人际事件数小时内波动。"},{"name":"双相障碍(ps_bipolar)","point":"双相情绪起伏持续数天伴精力增多；BPD为小时级波动。"},{"name":"精神分裂症(ps_schizo)","point":"分裂型人格信念短暂、无持续幻觉妄想与功能衰退。"},{"name":"进食障碍(ps_eating)与成人ADHD(ps_adhd)","point":"B组冲动贯穿自我概念与人际；ADHD或暴食为独立行为控制问题。"}],"tx":{"drug":[{"name":"舍曲林/氟西汀(抑郁样症状)","dose":"舍曲林50-200 mg/d；氟西汀20-40 mg/d","note":"仅对症、可加重冲动；黑框：<25岁初期自杀观念风险升高。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"与MAOI禁忌；与其他5-HT能药警惕5-HT综合征"},{"name":"拉莫三嗪","dose":"25 mg qd连2周、每2周加倍、维持100-200 mg/d","note":"须缓慢滴定防Stevens-Johnson综合征、出现皮疹即停药。","renal":"肾损减量","hepatic":"肝损减量、重度避免","interact":"丙戊酸使其浓度加倍；卡马西平与口服避孕药降低浓度"},{"name":"喹硫平/奥氮平(短期控制)","dose":"喹硫平25-50 mg qn起至100-200 mg/d；奥氮平2.5-5 mg起","note":"短期数周对症；黑框：老年痴呆相关精神病者死亡风险增加。","renal":"遵说明书","hepatic":"肝损减量","interact":"CYP3A4抑制剂升高喹硫平浓度；吸烟降低奥氮平浓度"},{"name":"纳曲酮(共病酒精依赖)","dose":"50 mg qd","note":"有肝损伤风险、定期监测肝功能。","renal":"肾损慎用","hepatic":"急性肝炎或肝衰竭禁用","interact":"拮抗阿片类镇痛；与硫利达嗪合用增加嗜睡"}],"nonDrug":["辨证行为治疗(DBT)为BPD一线、个体加团体技能训练、降低自伤与自杀未遂","心智化治疗、移情焦点治疗与图式治疗亦有证据","C组适用CBT与社交技能训练","危机干预用安全计划、避免长期住院强化退行","家属教育降低家庭情绪负荷"],"life":["固定治疗框架与危机联络方式","自伤工具清除、药物由家属保管","规律睡眠运动、戒酒与非法物质","30-40岁后冲动性自然下降、不宜过早悲观判断"]},"prog":"BPD约50%在10年内症状缓解、自伤随年龄减少、约10%自杀死亡、但社会功能损害持续；心理治疗是改善预后的关键。","refs":["中国精神障碍诊疗规范(2020)","中国边缘型人格障碍诊疗指南(2021)","NICE CG78 Borderline personality disorder"]},{"id":"ps_eating","name":"进食障碍(神经性厌食与神经性贪食)","aka":["Eating Disorders","神经性厌食","Anorexia Nervosa","AN","神经性贪食","Bulimia Nervosa","BN"],"rank":2,"basic":{"define":"神经性厌食：限制能量致显著低体重(BMI<17.5)、强烈怕胖或阻止增重伴体像障碍、分限制型与暴食清除型。神经性贪食：反复暴食加不当代偿(催吐、泻药、过度运动)、每周≥1次、≥3个月、体重多正常。","risk":["青少年女孩、起病高峰15-19岁","舞蹈、体操、赛艇等以体重为核心的项目","完美主义、低自尊、体像不满","AN遗传度约50%-60%；童年性虐待","1型糖尿病为减重减用胰岛素"],"epi":"AN终生约0.4%(女性最高2%-4%)、BN约1%-2%。AN标化死亡率为普通人群5-6倍、为最致命的精神障碍之一。"},"patho":"饥饿使HPA轴亢进、低T3、性腺轴抑制(闭经)、并放大强迫与体像歪曲；5-HT功能异常与过度控制相关。贪食的暴食-清除循环以情绪调节为核心、清除短暂缓解焦虑内疚形成负强化。","dx":{"criteria":["AN：显著低体重(WHO：轻17-18.5、中16-16.99、重15-15.99、极重<15)","AN：强烈怕胖或阻止增重、伴体像障碍、以体重体形评价自我","AN：可伴闭经、须排除其他原因低体重","BN：反复暴食且失控、每周≥1次、≥3个月","BN：反复不当代偿(催吐、泻药、利尿剂、过度运动)","评估共病抑郁、自伤与电解质紊乱"],"workup":["体重BMI、心率血压体温与体位性低血压","钾钠镁磷钙、肾功能、白蛋白、血糖","心电图：心率<60或QTC>450 ms提示需急诊","TSH、FT4、FSH/LH；病程>6-12个月查骨密度","EAT-26、EDE-Q、SCOFF","反复呕吐者查食管炎、龋齿与腮腺肿大"],"grading":"AN按WHO BMI四级、分限制型与暴食清除型；BN按频率(每周≥3次为重)；住院指征见BMI<14-15、生命体征不稳、低钾、自杀风险。"},"ddx":[{"name":"躯体症状障碍(ps_somatic)","point":"后者以多系统症状与过度就医为核心、无体重控制与体像障碍。"},{"name":"强迫症(ps_ocd)","point":"OCD食物仪式非自我价值核心、无显著低体重与体像扭曲。"},{"name":"抑郁障碍(ps_depression)","point":"抑郁食欲减退但无怕胖与体像障碍。"},{"name":"暴食障碍(BED)","point":"BED无规律清除、体重常肥胖；BN有固定代偿。"},{"name":"器质性消瘦(甲亢、IBD、糖尿病、肿瘤)","point":"有客观生化影像证据且无怕胖。"},{"name":"物质或药物所致(可卡因、甲状腺素过量)","point":"有明确使用史、停药后体重恢复。"}],"tx":{"drug":[{"name":"氟西汀(BN一线)","dose":"BN 60 mg qd；AN体重恢复后20-60 mg/d","note":"减少暴食清除约50%-70%；AN低体重期须先恢复体重；黑框：<25岁初期自杀观念风险升高。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"CYP2D6强抑制；与MAOI禁忌；与曲马多警惕5-HT综合征"},{"name":"奥氮平(AN促体重、辅助)","dose":"2.5-5 mg qn起、可至10 mg/d","note":"代谢副作用显著；黑框：老年痴呆相关精神病者死亡风险增加。","renal":"遵说明书","hepatic":"肝损减量","interact":"吸烟、卡马西平降低浓度；与氟西汀合用升高浓度"},{"name":"托吡酯(BN暴食、辅助)","dose":"25 mg qn起、渐至100-400 mg/d","note":"非正式适应证须伦理评估；有肾结石、酸中毒与认知变慢风险。","renal":"重度肾损减半","hepatic":"肝损慎用","interact":"与碳酸酐酶抑制剂增加结石风险；与丙戊酸致高氨血症"},{"name":"硫胺素与磷酸盐(再喂养预防)","dose":"硫胺素100 mg qd(重者q8h)；低磷者按检验值补充","note":"再喂养期每12-24 h监测磷钾镁；低磷<0.3 mmol/L可致心衰与心律失常。","renal":"补钾补磷防高钾高磷","hepatic":"遵说明书","interact":"含铝镁制酸剂影响磷酸盐吸收"}],"nonDrug":["营养康复起始20-30 kcal/kg/d、逐增至40-60 kcal/kg/d、住院每周增重0.5-1 kg","再喂养综合征前72 h每日查电解质、纠正低磷低钾低镁","青少年AN一线为FBT(Maudsley法)、成人CBT-E","BN一线CBT-E加营养教育与规律进餐","住院指征：BMI<14-15、生命体征不稳、严重低钾、快速减重或自伤风险"],"life":["规律三餐加2-3次加餐","家属避免评论身材食物、部分盲测体重","每周测体重1-2次；AN缓解后随访1年","营养稳定后逐步恢复运动"]},"prog":"AN约50%完全恢复、30%部分恢复、20%慢性化、标化死亡率5%-6%；BN经CBT约50%-70%显著改善但复发率高。早识别与营养恢复决定转归。","refs":["中国进食障碍防治指南(2017)","中国精神障碍诊疗规范(2020)","NICE NG69 Eating disorders"]},{"id":"ps_postpartum","name":"产后抑郁与产褥期精神病","aka":["Postpartum Depression","PPD","产后抑郁","Postpartum Psychosis","产褥期精神病"],"rank":3,"basic":{"define":"产后抑郁：妊娠期或产后4周内(延伸至12个月)的重性抑郁发作、EPDS≥13提示可能。产褥期精神病：产后2周内(多为3-10天)急性起病、躁狂或抑郁症状伴幻觉妄想与意识混乱、属急症。","risk":["既往抑郁或双相史(复发30%-50%)、既往产后抑郁史","孕期产后焦虑、睡眠剥夺","缺乏伴侣支持、伴侣暴力、单亲、经济困难","分娩并发症、早产儿","双相障碍者产后风险20%-50%"],"epi":"产后抑郁10%-15%、我国约15%-20%；产褥期精神病约1-2/1000分娩、自杀与杀婴风险高。"},"patho":"雌二醇与孕激素骤降、睡眠剥夺、催乳素升高与HPA轴改变使情绪调节失衡；产后免疫炎症激活与抑郁相关。双相患者产后因节律紊乱与睡眠剥夺触发躁狂。","dx":{"criteria":["产后4周内(筛查至12个月)符合重性抑郁发作标准并致功能损害","EPDS≥13提示可能抑郁、≥10需进一步评估、阳性须评估自杀风险","与产后忧郁鉴别：3-5天情绪波动、<2周自行缓解","产褥期精神病：2周内急性起病、情绪剧烈波动、幻觉妄想、严重失眠","须评估伤婴与自伤风险","产后躁狂或混合症状提示双相障碍"],"workup":["EPDS于产后1周、6周、3个月筛查；PHQ-9、GAD-7、MDQ","甲功(产后甲状腺炎)、血常规、维生素D","评估自杀与杀婴意念","产褥期精神病：精神检查与意识状态、必要时脑影像与毒物筛查"],"grading":"产后抑郁按EPDS分轻/中/重；产褥期精神病按自伤或伤婴风险分层、≥1项需紧急住院。"},"ddx":[{"name":"抑郁障碍与双相障碍(ps_depression/ps_bipolar)","point":"产后抑郁标准同重性抑郁；产后躁狂或精神病性症状应诊断双相或精神病性障碍。"},{"name":"谵妄(ps_delirium)","point":"谵妄以注意力与意识波动为核心、见于产褥感染、子痫；产后精神病意识清晰。"},{"name":"PTSD(ps_ptsd)","point":"分娩创伤PTSD以闪回噩梦与回避为主；产后抑郁以情绪低落为主。"},{"name":"躯体症状障碍(ps_somatic)","point":"产后盆底不适常见、伴过度关注时评估健康焦虑。"},{"name":"产后甲状腺炎与贫血","point":"产后3-6个月甲功异常致抑郁心悸、纠正后改善。"}],"tx":{"drug":[{"name":"舍曲林(哺乳首选)","dose":"25-50 mg qd起至50-150 mg/d、哺乳期常用50-100 mg/d","note":"乳汁渗透低；黑框：<25岁初期自杀观念风险升高。","renal":"一般无需调整","hepatic":"肝损减量","interact":"与MAOI禁忌；与NSAIDs增出血；不与曲马多合用"},{"name":"帕罗西汀","dose":"20 mg qd起、可至40 mg/d","note":"乳汁量低、新生儿偶有喂养差；黑框同上。","renal":"重度肾损减量","hepatic":"肝损减量","interact":"CYP2D6抑制剂；与MAOI禁忌"},{"name":"去甲替林(哺乳替代)","dose":"25-50 mg qd起至75-150 mg qd睡前","note":"过量致死性心律失常、须监测血药浓度与心电图。","renal":"肾损减量","hepatic":"肝损减量","interact":"与MAOI禁忌；与氟西汀、帕罗西汀合用升高浓度"},{"name":"锂盐","dose":"300 mg bid-tid起、急性期0.8-1.0 mmol/L、维持0.6-0.8 mmol/L","note":"黑框：孕期可致Epstein心脏畸形；哺乳期婴儿血锂达母体30%-50%、须监测。","renal":"肾损按浓度调整；NSAIDs、ACEI致蓄积","hepatic":"需监测","interact":"噻嗪类、NSAIDs、ACEI或ARB升高血锂；与氟哌啶醇有神经毒性"},{"name":"奥氮平/喹硫平","dose":"奥氮平5-10 mg qn至15-20 mg/d；喹硫平50-100 mg qn起至300-600 mg/d","note":"黑框：老年痴呆相关精神病者死亡风险增加。","renal":"遵说明书","hepatic":"肝损减量","interact":"吸烟降低奥氮平浓度；与QT延长药合用心电监护"}],"nonDrug":["一线心理治疗为CBT与人际心理治疗","产褥期精神病立即精神科急诊并住院","评估杀婴风险、必要时母婴分离","严重拒食或自杀者住院、必要时MECT","产后6周与6个月重复EPDS筛查"],"life":["保证每晚4-5小时连续睡眠、家属分担夜护","建立照护分工与休息日","哺乳期用药与精神科儿科共同评估婴儿喂养","双相史者产后1-2周起预防性心境稳定剂"]},"prog":"产后抑郁未治疗可持续6-12个月、复发约40%。产褥期精神病及时治疗80%以上数周内缓解、但复发率>50%。","refs":["中国产后抑郁障碍防治指南(2020)","中国精神障碍诊疗规范(2020)","NICE CG192 Antenatal and postnatal mental health"]},{"id":"ps_adhd","name":"注意力缺陷多动障碍(成人)","aka":["ADHD","Adult ADHD","成人多动症","注意缺陷多动障碍"],"rank":4,"basic":{"define":"注意缺陷和/或多动-冲动为特征的神经发育障碍、症状早于12岁、持续≥6个月、在≥2个领域造成损害。成人多以拖延、组织困难、冲动决策与人际冲突就诊。","risk":["一级亲属患病、遗传度约70%-80%","早产低体重、孕期烟草暴露、铅暴露","成人男女比例趋近1.5:1","共病焦虑抑郁与物质使用障碍达60%-80%"],"epi":"成人患病率约2.5%-5%、我国估计2%-3%、就诊率不足10%；约50%-60%儿童症状持续至成年、其中2/3残留损害。"},"patho":"前额叶-纹状体-小脑环路发育延迟、尾状核体积偏小、多巴胺转运体异常。NE与DA功能不足为哌甲酯(阻断DAT与NET)与托莫西汀(抑制NET)的药理基础；长期失败经验导致回避。","dx":{"criteria":["成人≥5项注意缺陷：难以维持注意、拖延、丢三落四、易分心、组织困难","和/或≥5项多动冲动：坐立不安、过度交谈、抢答、无法等待、打断他人","早于12岁出现、须有童年寄证(成绩单、老师评语)","存在于≥2个情境并造成功能损害","不能用焦虑、抑郁、双相、人格障碍或物质使用解释","ASRS A部分≥4项为阳性、确诊用DIVA-5等访谈"],"workup":["童年史与学校记录、伴侣提供的事例","ASRS v1.1、CAARS、DIVA-5","共病筛查PHQ-9、GAD-7、MDQ、AUDIT、STOP-BANG","认知测验仅辅助、学习障碍另评估","用药前测血压心率、心电图(心血管风险者)、肝功","排除甲亢、睡眠呼吸暂停、贫血与药物性注意力损害"],"grading":"按表现型分注意缺陷为主型、多动冲动为主型、混合型；按功能损害分轻/中/重。"},"ddx":[{"name":"人格障碍(ps_personality)","point":"B组冲动贯穿自我概念与人际、无童年注意缺陷史。"},{"name":"进食障碍(ps_eating)","point":"暴食失控为独立行为控制问题、无童年注意缺陷证据。"},{"name":"失眠障碍(ps_insomnia)","point":"睡眠不足致注意力下降、补充睡眠后改善。"},{"name":"抑郁与焦虑障碍(ps_depression/ps_gad)","point":"后者注意力损害随情绪缓解；ADHD须12岁前持续证据。"},{"name":"双相障碍(ps_bipolar)","point":"躁狂活动增多冲动呈发作性伴睡眠需求减少；ADHD为持续性。"},{"name":"睡眠呼吸暂停与甲亢","point":"有AHI≥5或TSH降低证据、治疗原发病后恢复。"}],"tx":{"drug":[{"name":"哌甲酯缓释片(一线)","dose":"18 mg qd晨服起、每周加18 mg、常用36-54 mg/d(最大72 mg/d)","note":"黑框：长期滥用可致依赖；结构心脏病、严重心律失常、未控高血压禁用；监测血压心率体重。","renal":"遵说明书","hepatic":"肝损慎用","interact":"与MAOI禁忌(高血压危象、停药14天)；与华法林、SSRI因CYP2D6抑制升高浓度"},{"name":"托莫西汀(一线替代)","dose":"40 mg qd起、1周后80 mg qd、可至100 mg/d、起效2-4周","note":"无滥用潜力；黑框：儿童青少年可出现自杀观念；注意血压与心率。","renal":"重度肾损遵说明书减量","hepatic":"Child-Pugh B减半、C减至25%","interact":"CYP2D6强抑制剂使其浓度升高需减量；与MAOI禁忌"},{"name":"胍法辛缓释(辅助)","dose":"1 mg qn起、渐至1-4 mg/d","note":"突然停药致反跳性高血压、需数周减量。","renal":"肾损减量","hepatic":"肝损减量","interact":"与镇静药、β阻滞剂加强降压与镇静"}],"nonDrug":["CBT：拖延、时间管理、任务分解与情绪调节、12-16次","执行功能教练与日程提醒系统","正念训练改善注意力与冲动","工作学业合理便利：安静工位、任务拆分、延长时间","父母或伴侣心理教育、减少污名"],"life":["每3-6个月监测血压、心率与体重","避免与酒精同用；有滥用史者优选非兴奋剂或长效剂型","固定作息与清单化工具","兴奋剂每2-4周调整、托莫西汀4-6周评估"]},"prog":"约2/3成人残留损害；规范药物治疗70%-80%有效但需长期维持；共病是预后不良的独立因素。","refs":["中国注意缺陷多动障碍防治指南(第二版、2015)","中国成人ADHD诊疗专家共识(2023)","NICE NG87 ADHD diagnosis and management"]},{"id":"ps_insomnia","name":"失眠障碍","aka":["Insomnia Disorder","慢性失眠","失眠症"],"rank":5,"basic":{"define":"入睡困难、睡眠维持困难或早醒、伴日间功能损害(疲劳、注意力下降、情绪不稳)、每周≥3次、持续≥3个月、在足够睡眠机会下仍出现、不能由其他睡眠障碍解释。","risk":["女性约为男性1.5倍、老年人早醒更多","负性生活事件、慢性压力、焦虑抑郁(共病40%-50%)","轮班工作、跨时区飞行、作息不规律","慢性疼痛、心血管病、更年期症状","酒精、咖啡因、糖皮质激素、β阻滞剂"],"epi":"一般人群失眠症状约30%、符合诊断者6%-10%；我国成人约10%-15%、约50%可自然缓解但复发率高、抑郁风险约升高2倍。"},"patho":"3P模型：易感(睡眠反应性)、诱发(压力疾病)与维持(不良睡眠行为、灾难化认知)因素。过度觉醒假说：HPA轴与交感亢进、夜间皮质醇与体温升高；床-清醒条件化焦虑使失眠慢性化。","dx":{"criteria":["入睡潜伏期>30 min或夜间觉醒≥2次或总睡眠<6 h、每周≥3次≥3个月","日间功能损害：疲劳、注意力记忆下降、情绪不稳","在适当睡眠时机与环境仍失眠","排除睡眠呼吸暂停、不安腿、昼夜节律障碍与物质药物所致","ISI：8-14亚临床、15-21中度、22-28重度","评估共病焦虑抑郁与催眠药使用"],"workup":["睡眠日记1-2周","ISI、PSQI、PHQ-9、GAD-7；STOP-BANG与RLS问卷","体检：BMI、颈围、鼻咽通畅度、甲状腺","PSG用于疑OSA、发作性睡病、RLS或治疗无效者","甲功、血常规、铁蛋白"],"grading":"按病程分急性(<3个月)与慢性；按ISI分轻/中/重；分单纯失眠与共病失眠；心理生理性失眠为经典亚型。"},"ddx":[{"name":"抑郁与焦虑障碍(ps_depression/ps_gad)","point":"其失眠随情绪改善缓解、心境低落为原发；失眠障碍可独立存在。"},{"name":"成人ADHD(ps_adhd)","point":"ADHD入睡难源于拖延与屏幕时间、伴童年注意缺陷证据。"},{"name":"睡眠呼吸暂停(OSA)","point":"有打鼾、目击呼吸暂停与嗜睡、AHI≥5可确诊；安眠药加重呼吸抑制。"},{"name":"不安腿综合征(RLS)","point":"静息时下肢活动冲动、活动后缓解、铁蛋白低者补铁有效。"},{"name":"昼夜节律障碍(延迟睡眠相)","point":"入睡与起床整体后移但睡眠时长正常。"},{"name":"双相障碍躁狂期","point":"睡眠需求减少伴精力增高、属发作性。"}],"tx":{"drug":[{"name":"唑吡坦(短期)","dose":"10 mg 睡前即刻(老年或女性5 mg)、不超过4周、按需间断","note":"黑框：与阿片类合用致严重呼吸抑制与死亡；可致睡行、梦驾、出现即停药；禁与酒精同用。","renal":"肾损慎用","hepatic":"肝损5 mg起","interact":"与阿片类、酒精协同抑制呼吸；CYP3A4抑制剂升高浓度、利福平降低疗效"},{"name":"右佐匹克隆","dose":"1-3 mg 睡前(老年1 mg起)","note":"次日残留轻但可依赖；黑框同唑吡坦；口苦常见。","renal":"重度肾损慎用","hepatic":"重度肝损1 mg起","interact":"CYP3A4抑制剂升高浓度；与酒精阿片类加强抑制"},{"name":"曲唑酮(助眠)","dose":"25-50 mg 睡前、最多100 mg","note":"晨起嗜睡、体位性低血压与罕见阴茎异常勃起。","renal":"肾损慎用","hepatic":"肝损减量","interact":"CYP3A4抑制剂升高浓度；与SSRI警惕5-HT综合征"},{"name":"雷美替胺","dose":"8 mg 睡前30 min","note":"无依赖风险但疗效中等；国内可及性有限。","renal":"重度肾损慎用","hepatic":"重度肝损禁用","interact":"氟伏沙明显著升高浓度、避免合用"},{"name":"艾司唑仑/阿普唑仑(老年慎用)","dose":"艾司唑仑1-2 mg或阿普唑仑0.4 mg睡前、仅2-4周","note":"黑框：与阿片类合用致呼吸抑制；老年跌倒与谵妄风险、Beers标准应避免。","renal":"肾损减量","hepatic":"肝损减量、严重肝病慎用","interact":"与阿片类酒精协同；CYP3A4抑制剂升高浓度"}],"nonDrug":["CBT-I为一线：睡眠限制、刺激控制、认知重构与放松训练、4-8次、长期优于药物且无依赖","压缩卧床时间接近实际睡眠再逐步延长；卧床20 min不能入睡即离床","矛盾意向法、渐进肌肉放松与正念冥想","光照疗法与固定作息、适用老人节律紊乱","共病抑郁焦虑同治、OSA用CPAP；妊娠哺乳期优先非药物"],"life":["固定起床时间、白天小睡≤30 min且不晚于15:00","睡前4-6 h避咖啡因、2 h避酒精与大餐","卧室安静黑暗凉爽、不在床上工作玩手机","规律有氧运动、睡前3 h避免剧烈运动","稳定后2-4周缓慢减半药量"]},"prog":"急性失眠随压力消退缓解；慢性失眠易复发、CBT-I使约70%患者主观改善。长期安眠药致依赖与效果衰减、未治疗者抑郁与心血管风险升高。","refs":["中国成人失眠诊断与治疗指南(2017版)","中国失眠症诊断和治疗指南(2017)","AASM Pharmacologic Treatment of Chronic Insomnia(2017)"]}]},{"id":"psych_dev_dissoc","name":"发育与分离障碍","rank":6,"summary":"本类两种障碍都在精神科其他条目里常被误判：智力障碍需以标准化智测与适应功能为依据、以支持性照护与共病治疗为主体；分离（转换）障碍以排除器质性疾病为前提、以心理治疗为主，药物仅针对共病症状，切忌纠缠于「装病」而延误真正病因。","compare":[{"diseaseId":"ps_mr","dx":"发育期起病、IQ <70 且适应功能缺陷（交流、社交、自理等）同时存在，经标准化智力量表与适应行为量表确认，排除感觉、运动与教育环境因素","key":"认知与适应功能双重缺陷、起病于发育期；共病癫痫、先天畸形与行为问题是重要照护点"},{"diseaseId":"ps_dissociative","dx":"在冲突或应激背景下出现急性运动、感觉或意识改变，与神经解剖及电生理检查不符，症状随暗示变化，且患者非故意制造","key":"症状与神经解剖不符、暗示可改变、非伪装；器质性病因需先排除"}],"diseases":[{"id":"ps_mr","name":"精神发育迟滞与智力障碍","aka":["Mental Retardation","Intellectual Disability","智力障碍","智能发育障碍"],"rank":1,"basic":{"define":"在发育期内起病、以一般智力显著低于同龄水平（IQ <70，约低于均数 2 个标准差）并伴适应功能障碍（交流、社交、自理、学习、工作等）为特征的一组发育性疾病；须同时满足智力与适应功能两项缺陷，并排除感官、躯体限制与教育机会不足。","risk":["染色体异常（Down 综合征、脆性 X 综合征）与基因变异","围产期窒息、早产、低出生体重与新生儿黄疸（核黄疸）","宫内感染（TORCH）、孕母饮酒与药物暴露","出生后重度营养不良、铅中毒、颅内感染与头部外伤","父母近亲婚配与家族遗传史"],"epi":"我国学龄儿童智力障碍患病率约 0.5%–1%，占残疾儿童首位；轻度约占 85%，中重度占 15% 左右；男女之比约 1.4:1，农村高于城市。"},"patho":"神经发育早期（胚胎至 3 岁）神经元增殖、迁移、突触形成与髓鞘化过程中受到遗传或环境损伤，导致皮层网络连接与突触可塑性下降；不同病因受累部位不同（染色体病常弥漫受累，代谢病可累及白质），决定了合并癫痫、行为与感官障碍的差异。","dx":{"criteria":["起病于发育期（18 岁前），智力与适应功能发育落后于同龄","标准化智力测验 IQ <70（常用韦氏量表），须在专业人员评估下完成","精神发育迟滞（ICD-10 F70–F79）分级：轻度 IQ 50–69、中度 35–49、重度 20–34、极重度 <20","适应功能缺陷：至少一项日常功能较同龄显著受限，常用文兰适应行为量表（VABS）","须同时满足智力缺陷与适应缺陷，单一 IQ 低不足以诊断","排除感觉损害（耳聋、失明）、运动限制（脑瘫）、缺乏教育机会与情绪障碍导致的评估失真"],"workup":["智力测评：韦氏智力量表（WISC/WAIS）、社会适应能力量表（VABS、儿童适应行为量表）","病因筛查：染色体核型与芯片（CMA），必要时脆性 X、甲功、血尿氨基酸与有机酸代谢筛查","头颅 MRI（小头、畸形、癫痫或退行者）与脑电图（癫痫或行为异常者）","听觉与视觉评估（耳声发射、行为测听、视力筛查）","行为与精神共病筛查：ADHD、孤独症谱系、情绪障碍、冲动攻击","生长与营养评估、喂养与吞咽（中重度患儿）","家族史与孕期、围产期病史（产程缺氧、黄疸、感染）"],"grading":"按 IQ 分级：轻度 50–69（可经教育获得基本读写与简单技能，约占 85%）；中度 35–49（可学会基本自理与交流，需部分支持）；重度 20–34（需持续支持，生活不能完全自理）；极重度 <20（全部生活领域依赖照护）。"},"ddx":[{"name":"分离（转换）性障碍（ps_dissociative）","point":"与本类 ps_dissociative 的鉴别点：智力障碍自发育期持续存在、智力与适应功能长期落后；分离障碍为在冲突或应激后突然出现的认知与运动功能改变，业已具备的正常能力突然丧失，暗示性明显。"},{"name":"孤独症谱系障碍","point":"以社交沟通质的缺陷与刻板重复行为为核心，早期（3 岁前）即可见社交性微笑、共同注意缺乏；部分患儿合并智力障碍，但社交本质性缺陷与刻板兴趣是诊断核心。"},{"name":"特定学习障碍与注意缺陷多动障碍","point":"智力与整体适应能力正常，障碍局限于阅读、书写、计算或注意力；学业困难不足以诊断为智力障碍。"},{"name":"进行性脑病（如粘多糖病、苯丙酮尿症）","point":"已获得的技能进行性消退，伴肝脾肿大、骨骼改变或皮肤毛发改变，代谢筛查与 MRI 可鉴别；智力障碍则为早期稳定或缓慢进步的落后。"},{"name":"聋哑与重度营养不良","point":"听障或严重营养不良可造成学习与交流困难，矫正感官障碍与营养后改善，非智力缺陷。"}],"tx":{"drug":[{"name":"利培酮（伴攻击、破坏行为）","dose":"0.25–0.5 mg bid 起始，缓慢加量，常用 1–2 mg/d，最大依说明书；短期使用","note":"仅用于严重攻击与自伤、行为治疗效果不佳时的短期对症；注意锥体外系反应、代谢与高催乳素血症","renal":"肾功能不全慎用","hepatic":"肝功能不全需减量","interact":"与延长 QT 的药物、强效 CYP2D6 抑制剂合用需谨慎"},{"name":"阿立哌唑","dose":"1–2.5 mg qd 起始，按需调整（成人或青少年按说明书）","note":"用于伴冲动攻击与易激惹者，代谢不良反应相对轻，但需监测镇静与锥体外系反应","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与强效 CYP3A4/CYP2D6 抑制剂合用需减量"},{"name":"哌甲酯（伴多动注意缺陷）","dose":"遵说明书，从小剂量起；中重度智力障碍者慎用","note":"共病 ADHD 时可用，但易诱发激越、失眠与食欲下降，须严密监测","renal":"遵说明书","hepatic":"遵说明书","interact":"与 MAO 抑制剂禁忌合用；与抗精神病药合用增加心血管风险"},{"name":"SSRIs（伴抑郁、焦虑、强迫）","dose":"遵说明书，从小剂量起","note":"共病情绪障碍时使用；部分患者可出现激越与行为激活，需减半起始并密切观察","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与曲马多等 5-HT 能药合用增加 5-HT 综合征风险"},{"name":"氯硝西泮（伴癫痫或睡眠障碍）","dose":"遵说明书","note":"短期使用改善睡眠与癫痫，长期易致认知与行为抑制与耐受","renal":"遵说明书","hepatic":"重度肝功能不全减量","interact":"与阿片类、镇静剂合用增加呼吸抑制"}],"nonDrug":["早期干预：0–6 岁为关键窗口，言语、作业、物理与感知训练并重","教育安置：轻度以随班就读 + 资源教室为主，中度以上特殊教育或康复机构","行为治疗：正性强化、结构化作息、社交技能训练，家长培训与家庭支持","共病筛查与治疗：癫痫、ADHD、孤独症与情绪障碍","成年期转衔：职业康复与支持性就业；严重者需监护与托养","病因诊断后的遗传咨询，避免近亲婚配与再生育风险"],"life":["建立规律睡眠与生活制度，避免过度保护","营养与体重管理（抗精神病药易致体重增加）","癫痫发作的急救教育与安全防护（浴室、厨房、交通）"]},"prog":"预后取决于病因与严重程度：轻度智力障碍经教育可基本自理、从事简单工作；中重度需终身部分或完全支持，寿命随医疗照护改善而延长；合并癫痫、严重畸形与自闭行为者为不良预后因素。","refs":["中国精神发育迟滞防治康复指南","中华医学会精神医学分会 精神发育迟滞诊疗指南","ICD-10 精神与行为障碍分类（F70–F79）","2018 智力障碍的评定与康复中国专家共识"]},{"id":"ps_dissociative","name":"分离（转换）性障碍","aka":["Dissociative and Conversion Disorder","歇斯底里","癔症","Hysteria","转换障碍"],"rank":2,"basic":{"define":"在心理冲突或应激背景下，出现以运动、感觉或意识改变为主的临床综合征，症状不符合神经系统解剖与生理规律，且并非患者故意制造或伪装，常起病急、可因暗示改变；器质性病因必须先排除。","risk":["女性多见（约 2–10:1）","青年与青少年（10–35 岁）","人格暗示性强、情绪化、表演型或依赖型特质","既往有躯体化障碍或类似发作史","家庭冲突、创伤、学业与婚恋压力、被忽视与暴力经历"],"epi":"综合医院门诊约占 5%–15% 的患者存在不能完全用器质性疾病解释的症状；我国大型医院神经科与急诊中常见，女性多于男性，农村基层就诊者比例较高。"},"patho":"心理动力学与神经影像学提示情感应激下的运动相关皮层与边缘系统功能异常：运动执行被压抑而运动意念保留，感觉信号的整合被改变；神经生物学上属可逆性的功能联结改变，与器质损伤不同，因此神经系统检查常呈阴性或与主诉不符。","dx":{"criteria":["存在可识别的心理应激或冲突事件；起病多突然、与情境关联密切","症状不符合神经解剖规律：如单瘫或截瘫不伴反射与肌张力改变、感觉障碍不呈神经皮节分布（常见正中线分界或手套袜套样）、失明但视觉诱发电位正常、失音但发声与咳嗽正常","症状受暗示影响：在言语或治疗暗示下可部分或完全恢复，也易被新的暗示改变或复制","无法用已知的神经系统或其他躯体疾病解释，且症状并非故意产生（不同于伪装与做作性障碍）","常合并情感爆发、意识朦胧或分离性身份体验；无自知力或存在矛盾心理","排除器质性病因后，需随访观察（至少 6 个月），部分 MS、卒中、肌无力早期可被误判"],"workup":["完整神经系统查体：肌力、反射、肌张力、病理征、感觉分布与共济运动","头颅与脊髓 MRI、脑电图（必要时），排除结构性病变与癫痫","可疑症状的辅助检查：视觉诱发电位与视野（失明）、肌电图与神经传导（无力）、喉镜（失音）","血：电解质、甲状腺功能、自身抗体与感染筛查（依据症状定位）","心理评估：SCL-90、分离与躯体症状量表、焦虑抑郁量表","持续异常应复查并探讨心因线索，避免一开始就下功能性疾病结论"],"grading":"ICD-10 将转换与分离性障碍分类为分离性运动障碍（F44.4）、分离性抽搐/痉挛（F44.5）、分离性感觉丧失（F44.6）、分离性朦胧与出神状态（F44.3）等；ICD-11 将其归入解离性障碍类别，按主导症状亚型描述。"},"ddx":[{"name":"精神发育迟滞与智力障碍（ps_mr）","point":"与本类 ps_mr 的鉴别点：智力障碍自发育期持续存在、智力与适应功能长期落后；分离障碍为在冲突或应激后突然出现的认知与运动功能改变，业已具备的正常能力突然丧失，暗示性明显。"},{"name":"多发性硬化","point":"首次发作可表现为视神经炎、肢体无力与感觉异常，呈空间与时间多发性，MRI 见脱髓鞘灶、脑脊液寡克隆区带阳性；症状不受暗示影响，且随病程出现新病灶。"},{"name":"癫痫（尤其复杂部分性发作与非癫痫性发作）","point":"癫痫发作有刻板模式、持续数分钟、发作后困倦，视频脑电图可捕捉发作期癫痫样放电；非癫痫性发作无癫痫样放电、发作可较久或受暗示改变，需视频EEG 鉴别。"},{"name":"急性肌张力障碍与重症肌无力","point":"肌张力障碍有药物史（抗精神病药、甲氧氯普胺），休息与睡眠时改善；MG 为疲劳性无力、抗 AChR 抗体阳性、新斯的明试验有效，均不随暗示变化。"},{"name":"做作性障碍与诈病","point":"做作性障碍存在故意的症状模仿以获取医疗关注，诈病则以明确的外在利益（赔偿、回避责任）为目的；分离障碍的症状为非故意产生，暗示与情绪关联更明显。"}],"tx":{"drug":[{"name":"SSRIs（伴焦虑、抑郁或强迫）","dose":"遵说明书，从小剂量起","note":"针对共病焦虑与抑郁，改善整体情绪后可减少发作；不作为转换症状的特异性治疗","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与 5-HT 能药合用增加 5-HT 综合征风险"},{"name":"舍曲林","dose":"25–50 mg qd 起始，按需增至 100–200 mg/d，遵说明书","note":"用于伴抑郁或躯体化症状者，起效需 2–4 周；注意胃肠道反应与激越","renal":"遵说明书","hepatic":"肝功能不全减量起始","interact":"与曲马多、MAO 抑制剂等 5-HT 能药合用增加 5-HT 综合征"},{"name":"劳拉西泮/地西泮（急性情绪暴发、伴激越）","dose":"遵说明书，短期按需；急性情感爆发可小剂量肌注或口服","note":"仅短期对症，避免长期苯二氮䓬类依赖与共济失调","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"与阿片类、酒精合用增加呼吸抑制风险"},{"name":"小剂量抗精神病药（激越或短暂精神病性症状）","dose":"遵说明书，如奥氮平 2.5–5 mg 睡前，短期使用","note":"仅用于明显激越、攻击或短暂幻觉，不作为常规；注意锥体外系反应与镇静","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"延长 QT 药物需谨慎合用"}],"nonDrug":["心理治疗为核心：认知行为治疗、暗示疗法与心理教育，识别应激与症状的关联，避免责备「装病」","明确诊断具有治疗价值：解释症状与神经解剖不符、避免反复不必要的检查与过度关注","康复：从被动活动与物理治疗开始，逐步恢复运动与感觉功能","家庭与学校环境干预：减轻继发获益与压力源，停止特殊对待与频繁就医","多科协作：神经科、精神科与康复科联合评估与管理","随访：首发后 3–6 个月复诊，警惕后期出现真正器质性疾病"],"life":["规律作息、适度运动与压力管理训练","避免反复急诊、反复影像与不必要的住院（防止医疗化）","恢复期逐渐回归学习与工作，避免角色病化"]},"prog":"多数首发患者经解释、暗示治疗与心理干预后症状可迅速缓解；约 30%–50% 仍有复发或症状迁延，合并躯体化与人格障碍者预后较差；需要随访以避免漏诊器质病变。","refs":["中国分离（转换）性障碍诊疗指南","中华医学会精神医学分会 分离性障碍诊疗指南","ICD-10 精神与行为障碍分类（F44）","2016 转换障碍诊治中国专家共识"]}]}]},"renal":{"categories":[{"id":"ckd","name":"慢性肾脏病","rank":1,"summary":"以 eGFR 与白蛋白尿双维度分期，核心是延缓肾功能下降（RAAS 抑制剂、SGLT2 抑制剂、非奈利酮）与并发症管理；糖尿病肾病是我国 CKD 首位病因。","compare":[{"diseaseId":"ckd_stage","dx":"肾脏结构或功能异常 ≥3 个月，伴或不伴 eGFR <60 mL/min/1.73m² 或 UACR ≥30 mg/g","key":"病程 ≥3 个月是区别于 AKI 的核心；G1–G5 与 A1–A3 双维分期"},{"diseaseId":"ckd_dkd","dx":"糖尿病病程中持续白蛋白尿和/或 eGFR 下降，排除其他肾脏病，典型者伴糖尿病视网膜病变","key":"先有糖尿病、白蛋白尿先于 eGFR 下降、伴视网膜病变"}],"diseases":[{"id":"ckd_stage","name":"慢性肾脏病（诊断与分期管理）","aka":["CKD","慢性肾衰竭","Chronic Kidney Disease"],"rank":1,"basic":{"define":"各种原因引起的肾脏结构或功能异常持续 ≥3 个月，可表现为肾损伤标志（白蛋白尿、尿沉渣异常、影像学异常、病理异常、肾小管功能异常）或 GFR <60 mL/min/1.73m²。","risk":["糖尿病（首要病因）","高血压","老年、动脉粥样硬化性心血管病","反复泌尿系感染、梗阻性肾病、结石","自身免疫病与家族性肾病（多囊肾、Alport）","长期使用肾毒性药物（NSAIDs、马兜铃酸类中药）"],"epi":"我国成人 CKD 患病率约 8.2%–10.8%，知晓率不足 15%；糖尿病肾病与高血压肾损害占病因构成一半以上。"},"patho":"残余肾单位代偿性高滤过与肾小球内高压，导致足细胞损伤、蛋白尿与肾小管间质纤维化；RAAS 与交感激活、炎症介质与氧化应激共同驱动肾单位进行性丢失。","dx":{"criteria":["病程 ≥3 个月（与 AKI 的关键区别）","eGFR <60 mL/min/1.73m²，或肾损伤标志持续 ≥3 个月（UACR ≥30 mg/g、尿沉渣异常、影像学异常、病理异常、肾小管功能异常）","GFR 分期：G1 ≥90、G2 60–89、G3a 45–59、G3b 30–44、G4 15–29、G5 <15 mL/min/1.73m²","白蛋白尿分期：A1 <30 mg/g、A2 30–300 mg/g、A3 >300 mg/g","G3aA1 起属中危以上，G4–G5 各 A 分级均为极高危，建议肾科专诊"],"workup":["血肌酐 + CKD-EPI（2021）估算 eGFR","随机尿 UACR 或 24 h 尿蛋白定量；单次异常需 3–6 个月内复查确认","尿常规 + 尿沉渣：血尿、红细胞管型提示肾小球疾病","肾脏超声：大小、皮质厚度、积水/结石/囊性病变","血常规、钙磷、PTH、25-OH 维生素 D、CO2 结合力、钾、尿酸、血脂、HbA1c","免疫学（年轻、血尿、快速进展者）：ANA、抗 dsDNA、补体、ANCA、抗 GBM","肾活检指征：病因不明、蛋白尿 >1 g/d、活动性尿沉渣、肾功能快速下降"],"grading":"KDIGO 2012/2024 热图：G1–G5 × A1–A3 共 15 格，分低危/中危/高危/极高危，决定复查频率与转诊。"},"ddx":[{"name":"糖尿病肾病（ckd_dkd）","point":"与本类 ckd_dkd 的鉴别点：本例为非糖尿病或病因未明的 CKD；DKD 要求糖尿病基础、白蛋白尿先于 eGFR 下降、伴视网膜病变、多为无血尿的渐进进展。"},{"name":"急性肾损伤（aki_aki）","point":"与 aki 大类 aki_aki 的鉴别点：AKI 为 48 h 内 Scr 升高 ≥26.5 μmol/L 或 7 天内升至基线 1.5 倍以上，肾脏大小正常、可部分逆转；CKD 病程 ≥3 个月、肾脏常缩小。"},{"name":"CKD 基础上的急性肾损伤（A on C）","point":"原有 CKD 者 Scr 较基线上升 ≥50%，需同时按 AKI 处理并寻找诱因（感染、脱水、肾毒性药物、梗阻）。"},{"name":"心肾综合征","point":"心衰致肾淤血与灌注不足，BNP 升高、颈静脉压升高，利尿后肾功能可改善。"}],"tx":{"drug":[{"name":"ACEI/ARB","dose":"缬沙坦 80 mg qd 起始，可增至 160–320 mg qd；贝那普利 5–10 mg qd 起始，可增至 20–40 mg qd，按血压与耐受性滴定","note":"蛋白尿（A2/A3）患者一线基础治疗；起始或加量后 2–4 周复查肌酐与血钾","renal":"GFR <30 仍可用但需密切监测；Scr 升幅 >30% 或 K >5.5 mmol/L 时减量","hepatic":"重度肝功能不全慎用（贝那普利需经肝活化）","interact":"与保钾利尿剂、非奈利酮、NSAIDs 联用升高高钾风险；禁用 ACEI+ARB 联合"},{"name":"SGLT2 抑制剂（达格列净/恩格列净）","dose":"达格列净 10 mg qd；恩格列净 10 mg qd；起始无需按 eGFR 滴定","note":"eGFR ≥20 的 CKD（伴或不伴糖尿病）均推荐，可降低肾功能进展与心衰住院","renal":"eGFR <20 不推荐起始，已用者可继续至透析开始","hepatic":"重度肝功能不全慎用","interact":"与利尿剂联用注意容量不足；围手术期停用 3 天"},{"name":"非奈利酮","dose":"eGFR 25–60 且 K ≤4.8：10 mg qd；eGFR ≥60 且 K ≤4.8：20 mg qd；4 周后按血钾调整（K ≤4.8 加量，4.9–5.5 维持，>5.5 暂停）","note":"主要用于 2 型糖尿病相关 CKD 伴白蛋白尿（A2/A3）","renal":"eGFR <25 不推荐起始","hepatic":"重度肝功能不全（Child-Pugh C）禁用","interact":"强 CYP3A4 抑制剂（伊曲康唑、克拉霉素）禁用；避免补钾制剂"},{"name":"碳酸钙（磷结合剂）","dose":"0.5–1 g 随餐嚼服 tid，按血磷滴定；目标血磷 0.87–1.45 mmol/L","note":"用于 G3b 以上高磷血症，同时限磷饮食","renal":"随肾功能下降按需增量","hepatic":"遵说明书","interact":"与四环素、喹诺酮类、左甲状腺素同服需间隔 2 h 以上"},{"name":"骨化三醇/阿法骨化醇","dose":"骨化三醇 0.25 μg qd 起始，按 PTH 与血钙滴定；目标 iPTH 正常上限的 2–9 倍","note":"用于 CKD-MBD，监测血钙、磷、PTH","renal":"无需调整","hepatic":"遵说明书","interact":"与噻嗪类利尿剂合用增加高钙血症风险"},{"name":"罗沙司他/重组人促红细胞生成素","dose":"Hb <100 g/L 且铁储备充足时启动；罗沙司他按体重 100 mg（45–60 kg）或 120 mg（≥60 kg）tiw；rHuEPO 按说明书个体化，目标 Hb 100–115 g/L","note":"先纠正绝对性缺铁；Hb 不宜纠正至 >130 g/L","renal":"透析与非透析者剂量不同，遵说明书","hepatic":"重度肝功能不全减量并监测","interact":"ACEI/ARB 可能降低促红素疗效"},{"name":"碳酸氢钠","dose":"0.5–1 g tid 口服，按 CO2 结合力滴定，目标 ≥22 mmol/L","note":"用于代谢性酸中毒（HCO3⁻ <22 mmol/L），可延缓 CKD 进展","renal":"晚期注意钠负荷与容量","hepatic":"遵说明书","interact":"碱化尿液影响某些经肾排泄药物"}],"nonDrug":["肾替代治疗准备：G5 期评估透析通路（自体动静脉内瘘提前 3–6 个月建立）、腹膜透析、肾移植","血压目标：有蛋白尿者 <130/80 mmHg；老年或衰弱者个体化","避免肾毒性药物：NSAIDs、氨基糖苷类；造影前后水化并停用二甲双胍","纠治梗阻、控制感染、处理高钾与心衰等并发症","接种流感、肺炎球菌、乙肝疫苗"],"life":["限盐 <5 g/d；蛋白摄入 0.6–0.8 g/kg/d（G3b 以上低蛋白饮食 + 复方α-酮酸）","控糖 HbA1c 多数 <7.0%；LDL-C <1.8 mmol/L（极高危 <1.4 mmol/L）","戒烟、限酒、规律有氧运动","随访：低-中危每年 1 次，高危每 3–6 个月，极高危每 3 个月复查 eGFR、UACR、电解质"]},"prog":"以 eGFR 年下降速率判断，>5 mL/min/1.73m²/年或 A3 蛋白尿者属快速进展；规范 RAAS+SGLT2i+非奈利酮可延缓进展约 20%–40%。G5 期需肾替代治疗，透析患者 5 年生存率约 50%，肾移植为最优选择。","refs":["KDIGO 2024 慢性肾脏病评估与管理临床实践指南","中国慢性肾脏病早期评价与管理指南（2023）","中国慢性肾脏病矿物质和骨异常诊治指南（2019）","中国肾性贫血诊疗临床实践指南（2021）"]},{"id":"ckd_dkd","name":"糖尿病肾病","aka":["DKD","Diabetic Kidney Disease","糖尿病肾脏病"],"rank":2,"basic":{"define":"糖尿病导致的慢性肾脏病，通常表现为持续性白蛋白尿（UACR ≥30 mg/g）和/或 eGFR 下降持续 ≥3 个月，排除其他原发性/继发性肾脏病。","risk":["糖尿病病程长（1 型 >10 年）","血糖控制不佳（HbA1c >8%）","高血压、血脂异常","肥胖、吸烟","糖尿病视网膜病变","反复泌尿系感染"],"epi":"我国糖尿病患者 DKD 患病率约 20%–40%，糖尿病肾病已成为住院 CKD 患者首位病因（约 20%–27%）。"},"patho":"持续高血糖致系膜基质扩张、基底膜增厚、足细胞损伤与结节性硬化（Kimmelstiel-Wilson 结节）；高滤过 + RAAS 激活 + 内皮功能障碍导致蛋白尿与 GFR 下降。2 型糖尿病也可表现为无蛋白尿的 eGFR 下降型。","dx":{"criteria":["明确糖尿病且病程通常 ≥5 年（1 型）","持续白蛋白尿：3–6 个月内 3 次 UACR 至少 2 次 ≥30 mg/g，或 24 h 尿蛋白 ≥0.5 g","和/或 eGFR <60 mL/min/1.73m² 持续 ≥3 个月","伴糖尿病视网膜病变或周围/自主神经病变支持诊断","提示非糖尿病肾病、建议活检：无蛋白尿而 eGFR 快速下降、血尿伴管型、1 型病程 <5 年即出现蛋白尿、24 h 蛋白尿 >3.5 g、eGFR 每月下降 >1 mL/min"],"workup":["UACR、24 h 尿蛋白定量","eGFR（CKD-EPI 2021）、血肌酐","眼底检查（寻找视网膜病变）","肾脏超声","HbA1c、血脂、尿酸、血钾、血压、体重","排除其他病因：尿沉渣、免疫学，必要时肾活检"],"grading":"病理分级（Tervaert 分型）：Ⅰ 基底膜增厚；Ⅱ 系膜扩张（a 轻度/b 重度）；Ⅲ 结节性硬化；Ⅳ 晚期肾小球硬化（硬化率 >50%）。临床按 G/A 分期管理。"},"ddx":[{"name":"慢性肾脏病（非糖尿病病因）（ckd_stage）","point":"与本类 ckd_stage 的鉴别点：DKD 糖尿病在先、白蛋白尿先于 eGFR 下降、常伴视网膜病变；非糖尿病 CKD 病因明确、常有血尿/管型、无视网膜病变。"},{"name":"高血压肾损害","point":"长期高血压、左室肥厚、高血压视网膜病变，蛋白尿多 <1 g/d、血尿少见，无糖尿病史者不支持 DKD。"},{"name":"非糖尿病肾病合并糖尿病（NDKD）","point":"糖尿病但蛋白尿骤增、伴血尿或管型、活检见 IgA 沉积或足细胞病，需活检明确。"},{"name":"膜性肾病（gn_mn）","point":"与肾小球疾病大类 gn_mn 的鉴别点：MN 多有抗 PLA2R 抗体、肾病综合征突出、与糖尿病病程不符，病理见上皮侧颗粒样沉积。"}],"tx":{"drug":[{"name":"ACEI/ARB","dose":"缬沙坦 80 mg qd 起始，可增至 160–320 mg qd；氯沙坦 50 mg qd；厄贝沙坦 150–300 mg qd，2–4 周复查肌酐/血钾后滴定","note":"A2/A3 且无 AKI 者一线；不推荐 ACEI 与 ARB 联用","renal":"Scr 升幅 ≤30% 可耐受；>30% 排查肾动脉狭窄或容量不足","hepatic":"重度肝病慎用","interact":"与 NSAIDs、保钾利尿剂、非奈利酮联用升高高钾风险"},{"name":"SGLT2 抑制剂","dose":"达格列净 10 mg qd；恩格列净 10 mg qd；卡格列净 eGFR <60 时 100 mg qd","note":"合并 DKD 的 2 型糖尿病患者均推荐，无论是否已用 RAAS 抑制剂","renal":"eGFR <20 不起始","hepatic":"重度肝功能不全慎用","interact":"与利尿剂联用注意容量；围术期停用 3 天"},{"name":"非奈利酮","dose":"eGFR ≥60：20 mg qd；eGFR 25–60：10 mg qd；4 周后按血钾调整","note":"2 型糖尿病合并白蛋白尿 CKD 的心肾保护","renal":"eGFR <25 不推荐","hepatic":"重度肝功能不全禁用","interact":"强 CYP3A4 抑制剂禁用；避免补钾制剂"},{"name":"GLP-1 受体激动剂","dose":"司美格鲁肽 0.25 mg 皮下 qw 起始，4 周后 0.5 mg qw；利拉鲁肽 0.6 mg qd 起始，每周递增 0.6 mg 至 1.8 mg qd","note":"合并肥胖或动脉粥样硬化性心血管病者优先，可减少蛋白尿","renal":"eGFR <15 不推荐","hepatic":"重度肝功能不全慎用","interact":"与磺脲类/胰岛素合用注意低血糖"},{"name":"二甲双胍","dose":"eGFR ≥45：0.5 g bid–1 g bid；eGFR 30–44：减至 ≤1 g/d 并定期评估；eGFR <30 禁用","note":"乳酸酸中毒风险随肾功能下降升高；造影前停用","renal":"见上","hepatic":"严重肝功能不全禁用","interact":"含碘对比剂、酒精增加乳酸酸中毒风险"}],"nonDrug":["血压目标 <130/80 mmHg（可耐受者）","血糖目标个体化，多数 HbA1c <7.0%；老年或低血糖高危者 7.5%–8.0%","限盐 <5 g/d，体重管理（BMI <24）","处理高钾、贫血、CKD-MBD；eGFR <30 转肾科"],"life":["每年至少 1 次 UACR + eGFR 筛查；已有 DKD 者每 3–6 个月复查","戒烟、蛋白 0.8 g/kg/d","眼底筛查、足部护理、神经病变筛查"]},"prog":"A3 蛋白尿者 10 年进入 ESRD 的风险可 >50%；RAAS 抑制剂 + SGLT2i + 非奈利酮三联可显著延缓 eGFR 下降。合并心血管病者总体死亡风险高于 ESRD 风险。","refs":["KDIGO 2024 慢性肾脏病评估与管理临床实践指南","中国糖尿病肾脏病防治临床实践指南（2021）","中国 2 型糖尿病防治指南（2020 年版）","ADA Standards of Care in Diabetes—2024"]}]},{"id":"aki","name":"急性肾损伤","rank":2,"summary":"按 KDIGO 以肌酐与尿量分期（1–3 期），核心是识别诱因（肾前性、肾性、肾后性）并尽早干预；肝肾综合征属功能性 AKI，需白蛋白+血管收缩剂桥接肝移植。","compare":[{"diseaseId":"aki_aki","dx":"48 h 内血肌酐升高 ≥26.5 μmol/L，或 7 天内升至基线 1.5 倍以上，或尿量 <0.5 mL/kg/h 持续 6 h","key":"符合 KDIGO 时间与幅度标准，并区分肾前性/肾性/肾后性"},{"diseaseId":"aki_hrs","dx":"肝硬化伴腹水者出现 AKI，白蛋白扩容后不缓解，无休克、肾毒性药物与结构性肾病","key":"功能性肾损伤，尿钠 <10 mmol/L，扩容无效"}],"diseases":[{"id":"aki_aki","name":"急性肾损伤","aka":["AKI","急性肾衰竭","Acute Kidney Injury"],"rank":1,"basic":{"define":"由多种病因引起的肾功能短期内（数小时至数天）急剧下降的临床综合征，按 KDIGO 标准以肌酐升高与尿量减少定义，分为肾前性、肾实质性（肾小管、间质、肾小球、血管）与肾后性三类。","risk":["高龄、CKD 基础","脓毒症、休克、大手术","肾毒性药物（氨基糖苷类、万古霉素、NSAIDs、两性霉素 B、顺铂、造影剂）","容量不足（呕吐、腹泻、利尿剂过量、出血）","心力衰竭、肝硬化","尿路梗阻（前列腺增生、结石、肿瘤）"],"epi":"住院患者 AKI 发生率约 10%–20%，ICU 可达 30%–60%；需肾替代治疗者病死率 40%–60%，约 20%–30% 转为 CKD。"},"patho":"肾前性低灌注持续则转为急性肾小管坏死（上皮坏死脱落、管型阻塞）；肾后性梗阻使肾盂压力升高、GFR 下降；炎症、微血栓（DIC、TMA）与肾毒性可直接损伤小管与间质。","dx":{"criteria":["1 期：Scr 48 h 内升高 ≥26.5 μmol/L，或升至基线 1.5–1.9 倍；尿量 <0.5 mL/kg/h 持续 6–12 h","2 期：Scr 升至基线 2.0–2.9 倍；尿量 <0.5 mL/kg/h 持续 ≥12 h","3 期：Scr 升至基线 ≥3 倍，或 Scr ≥353.6 μmol/L 且急性上升 ≥44.2 μmol/L，或开始肾替代治疗；尿量 <0.3 mL/kg/h 持续 ≥24 h 或无尿 ≥12 h","明确肾前性/肾性/肾后性，并评估容量状态与用药史"],"workup":["血肌酐、尿素氮（BUN/Scr >20 提示肾前性）","尿量、体重、出入量；必要时下腔静脉超声评估容量","尿常规与沉渣：泥棕色颗粒管型（ATN）、红细胞管型（肾炎）、嗜酸性粒细胞（间质性肾炎）","尿钠与 FENa：肾前性 FENa <1%、尿钠 <20 mmol/L；ATN FENa >2%、尿钠 >40 mmol/L（利尿剂时不可靠）","肾脏超声：肾积水、双肾大小；有梗阻立即解除","电解质、酸碱、CK、溶血指标（LDH、网织红、涂片）、自身抗体"],"grading":"KDIGO 1–3 期（见诊断标准）；分级决定肾替代时机与药物剂量调整。"},"ddx":[{"name":"肝肾综合征（aki_hrs）","point":"与本类 aki_hrs 的鉴别点：HRS 见于肝硬化腹水，尿钠 <10 mmol/L、无血尿、白蛋白扩容 48 h 无效；普通 AKI 病因多样、可有管型与病理性尿沉渣。"},{"name":"慢性肾脏病（ckd_stage）","point":"与 ckd 大类 ckd_stage 的鉴别点：CKD 病程 ≥3 个月、肾脏缩小、贫血与钙磷紊乱出现早；AKI 病程短、肾脏大小正常、部分可逆。"},{"name":"急进性肾小球肾炎","point":"血尿、蛋白尿、红细胞管型突出，低补体、ANCA 或抗 GBM 阳性，需肾活检（新月体）；必要时血浆置换与激素冲击。"},{"name":"急性间质性肾炎","point":"新近用药（NSAIDs、抗生素、PPI）、发热、皮疹、嗜酸性粒细胞增多，停药后部分恢复，必要时激素。"}],"tx":{"drug":[{"name":"0.9% 氯化钠/平衡盐液（扩容）","dose":"低血容量者 20–30 mL/kg 快速补充后按维持量；心衰/肺水肿者避免大剂量","note":"肾前性 AKI 尽早纠正容量；脓毒症优先平衡盐液","renal":"透析患者严格限容","hepatic":"肝硬化腹水扩容首选白蛋白（1 g/kg，最多 100 g）","interact":"大量生理盐水致高氯性代谢性酸中毒"},{"name":"呋塞米","dose":"40–80 mg iv 起始，无反应可加倍（至 200 mg 静滴）；仅用于容量超负荷","note":"不改善 AKI 预后或生存率，不用于单纯少尿","renal":"AKI 时需加量","hepatic":"肝硬化慎用以免诱发 HRS","interact":"与氨基糖苷类合用增加耳毒性"},{"name":"碳酸氢钠（纠酸）","dose":"pH <7.20 或 HCO3⁻ <12 mmol/L 时补碱，目标 pH ≥7.20","note":"内科治疗无效或容量难以耐受时透析","renal":"注意容量","hepatic":"遵说明书","interact":"碱化尿液影响经肾排泄药物"},{"name":"高钾血症处理","dose":"10% 葡萄糖酸钙 10–20 mL iv 缓推；10% 葡萄糖 500 mL + 胰岛素 10 U 静滴；沙丁胺醇雾化 10–20 mg；聚苯乙烯磺酸钙 15–30 g 口服/灌肠","note":"K >6.5 mmol/L 或伴心电图改变时紧急处理并评估透析","renal":"高钾提示需尽早肾替代","hepatic":"遵说明书","interact":"β 受体阻滞剂削弱胰岛素降钾效果"}],"nonDrug":["停用肾毒性药物（NSAIDs、氨基糖苷类、两性霉素 B、万古霉素），按 eGFR 调整剂量","解除梗阻：导尿、双 J 管、经皮肾造瘘（肾后性）","肾替代指征：难治性高钾（K >6.5）、pH <7.20、肺水肿、尿毒症心包炎/脑病、可透析药物中毒","脓毒症按 3 h/6 h bundle 复苏，避免过度液体负荷","造影前评估，最小剂量对比剂；停用二甲双胍 48 h"],"life":["重症每小时记录尿量，每日体重，每 6–12 h 复查肌酐","营养支持：肠内优先，危重症蛋白 1.0–1.5 g/kg/d","AKI 恢复后 3 个月内复查肾功能与尿常规，长期 CKD 风险随访"]},"prog":"社区获得性 AKI 多可完全恢复；住院/ICU 获得性 AKI 病死率 30%–50%，需肾替代者更高。约 20%–30% 遗留肾功能不全或转为 CKD。","refs":["KDIGO 2012 急性肾损伤临床实践指南","中国急性肾损伤临床实践指南（2015，中华医学会肾脏病学分会）","急性肾损伤诊治专家共识（2017，中华医学会重症医学分会）"]},{"id":"aki_hrs","name":"肝肾综合征","aka":["HRS","Hepatorenal Syndrome"],"rank":2,"basic":{"define":"肝硬化失代偿期（或急性肝衰竭）发生的功能性肾功能不全，表现为 AKI 而无结构性肾损伤证据，与内脏血管扩张、肾血管收缩相关。","risk":["肝硬化失代偿伴腹水","自发性细菌性腹膜炎（常见诱因）","大量放腹水未扩容、过度利尿、消化道出血","NSAIDs 等肾毒性药物","重度腹水、低钠血症、MELD 高分"],"epi":"肝硬化腹水患者 1 年 HRS 发生率约 18%，5 年约 40%；HRS-AKI 未治疗者中位生存期 <3 个月。"},"patho":"门脉高压致内脏动脉扩张、有效循环血量不足，激活 RAAS、抗利尿激素与交感神经，引起肾血管收缩与 GFR 下降；内毒素与炎性介质加重肾灌注不良。肾脏结构正常，肝移植后常改善。","dx":{"criteria":["肝硬化伴腹水且符合 KDIGO AKI 标准","停用利尿剂并白蛋白扩容（1 g/kg，最多 100 g）至少 2 天无缓解","无休克、无近期肾毒性药物使用","无蛋白尿（UACR <50 mg/mmol）、无血尿、超声无梗阻与结构性肾病","尿钠 <10 mmol/L 支持功能性肾损伤"],"workup":["每日尿量与肌酐，判断 AKI 分期与扩容反应","白蛋白扩容试验后 48 h 复查肌酐","尿常规、尿钠、肾脏超声","诊断性放腹水查中性粒细胞（>250/mm³ 诊断 SBP）","肝功能、MELD、电解质、血钠、大便隐血","排除 ATN（尿钠 >40 mmol/L、颗粒管型）"],"grading":"ICA 2019 分类：HRS-AKI、HRS-NAKI；旧型 1 型（快速进展，中位存活 <1 月）与 2 型（缓慢、难治性腹水）。"},"ddx":[{"name":"急性肾损伤（非 HRS）（aki_aki）","point":"与本类 aki_aki 的鉴别点：HRS 见于肝硬化腹水、尿钠 <10 mmol/L、扩容不缓解、无管型；普通 AKI 多有明确诱因与病理性尿沉渣。"},{"name":"肝硬化合并肾前性氮质血症","point":"利尿过猛、腹泻、消化道出血致容量不足，补液后 Scr 24–48 h 内下降；HRS 扩容后不缓解。"},{"name":"急性肾小管坏死（ATN）","point":"尿钠 >40 mmol/L、FENa >2%、泥棕色颗粒管型，多由脓毒症或肾毒性药物引起。"},{"name":"慢性肾脏病（ckd_stage）","point":"与 ckd 大类 ckd_stage 的鉴别点：CKD 有 ≥3 个月病史、肾脏缩小、贫血与钙磷紊乱明显、蛋白尿阳性；HRS 为急性功能性、肾脏大小正常。"}],"tx":{"drug":[{"name":"人血白蛋白","dose":"扩容试验 1 g/kg（最多 100 g）iv；联合特利加压素时首日 1 g/kg，之后 20–40 g/d 维持","note":"兼作诊断与治疗；与血管收缩剂联合使用","renal":"无需调整","hepatic":"可用，注意容量负荷","interact":"遵说明书"},{"name":"特利加压素","dose":"1 mg iv q4–6h，48 h 无反应渐增至 2 mg q4h（最大 12 mg/d），疗程 ≤14 天","note":"HRS-AKI 一线血管收缩剂；国内可及性有限，需警惕缺血性并发症","renal":"肌酐无改善时停用","hepatic":"Child-Pugh C 需减量","interact":"与 β 阻滞剂、硝酸酯合用加重低钠"},{"name":"去甲肾上腺素","dose":"0.005–0.03 μg/kg/min 静脉泵入，需中心静脉与重症监护","note":"特利加压素不可及时替代","renal":"遵说明书","hepatic":"注意肝缺血风险","interact":"增强其他升压药作用"},{"name":"米多君 + 奥曲肽","dose":"米多君 7.5–12.5 mg 口服 tid；奥曲肽 100 μg 皮下 tid，可增至 200 μg tid","note":"资源有限时的替代，需与白蛋白联用","renal":"遵说明书","hepatic":"遵说明书","interact":"米多君与 MAO 抑制剂、三环类合用升压风险"},{"name":"利福昔明（预防 SBP）","dose":"550 mg bid 或 400 mg tid 口服","note":"降低自发性腹膜炎及 HRS 诱发风险","renal":"遵说明书","hepatic":"可使用","interact":"遵说明书"}],"nonDrug":["停用利尿剂与肾毒性药物；放腹水时补白蛋白 6–8 g/L 腹水","治疗诱因：SBP 用头孢曲松 2 g qd，并补白蛋白 1.5 g/kg（第 1 天）、1 g/kg（第 3 天）","肾替代仅作肝移植前桥接或 AKI 3 期难治并发症","肝移植为根治手段，按 MELD 优先分配","监测血钠（特利加压素可致低钠血症）"],"life":["限盐 <5 g/d，个体化限液","每 1–2 天监测肌酐、尿量、电解质","戒酒、防感染；非移植候选者讨论姑息/安宁疗护"]},"prog":"1 型未治疗中位生存 <1 个月、2 型 <6 个月；特利加压素+白蛋白可使约 40%–60% 逆转但复发率高。肝移植后 1 年生存 70%–80%。","refs":["中国肝硬化腹水及并发症诊疗指南（2023）","国际腹水俱乐部（ICA）肝肾综合征诊断标准（2019）","EASL 肝硬化失代偿与肝肾综合征管理指南（2018）"]}]},{"id":"gnd","name":"肾小球疾病","rank":3,"summary":"以蛋白尿、血尿、水肿与肾功能损害为共同表现，需依据免疫荧光与病理分型（IgA、膜性、微小病变等）；肾病综合征以糖皮质激素为核心，重症或激素依赖者加免疫抑制剂/靶向生物制剂。","compare":[{"diseaseId":"gn_iga","dx":"反复发作性肉眼血尿（上呼吸道感染后 24–72 h），伴或不伴蛋白尿；免疫荧光示 IgA 为主的系膜区沉积","key":"感染后 1–3 天出现血尿、补体 C3 正常，IgA 系膜沉积为确诊依据"},{"diseaseId":"gn_mn","dx":"肾病综合征 + 抗 PLA2R 抗体阳性；免疫荧光示 IgG/C3 沿基底膜颗粒样沉积、电镜见钉突","key":"抗 PLA2R 抗体特异性高，可替代部分活检；多为中老年男性"},{"diseaseId":"gn_mcd","dx":"突发大量蛋白尿、低白蛋白血症与水肿，血压与肾功能多正常，光镜基本正常、电镜足突弥漫融合","key":"激素 8 周内缓解率 >80%，以低分子量蛋白尿为主"},{"diseaseId":"gn_ns","dx":"蛋白尿 >3.5 g/d、血浆白蛋白 <30 g/L、水肿、高脂血症","key":"是综合征而非病因，需寻找继发因素并活检确定病理类型"}],"diseases":[{"id":"gn_iga","name":"IgA 肾病","aka":["IgAN","Berger 病","IgA Nephropathy"],"rank":1,"basic":{"define":"以肾小球系膜区 IgA 沉积为特征的肾小球肾炎，临床谱从无症状镜下血尿到快速进展性肾衰竭，是我国最常见的原发性肾小球疾病。","risk":["上呼吸道或消化道感染后血尿发作","男性、青少年及青年","反复扁桃体炎","蛋白尿持续 >1 g/d","高血压、高尿酸血症","肝硬化、银屑病等黏膜免疫相关疾病"],"epi":"我国肾活检病例中 IgA 肾病约 30%–40%（最常见原发肾小球病）；20 年肾存活率约 60%–70%。"},"patho":"“四重打击”学说：黏膜免疫异常产生半乳糖缺陷型 IgA1（Gd-IgA1）→ 循环抗糖基抗体结合形成免疫复合物 → 补体旁路激活 → 系膜细胞增生、基质扩张与足细胞损伤。","dx":{"criteria":["发作性肉眼血尿：感染（咽炎、胃肠炎）后 24–72 h 出现，持续数小时至数天（急性链球菌感染后肾炎为 1–3 周潜伏期）","镜下血尿（尿沉渣红细胞 >5/HPF）+ 蛋白尿（常见 0.5–2 g/d）","补体 C3、C4 正常（持续低补体提示其他病因）","确诊依赖肾活检：系膜区 IgA 沉积为主、伴 C3，光镜见系膜增生","病理 Oxford MEST-C 分型；持续蛋白尿 >1 g/d、高血压、eGFR 年下降 >1 mL/min 为高危"],"workup":["尿常规 + 尿沉渣（红细胞形态、红管型）","24 h 尿蛋白定量或 UACR","血肌酐、eGFR、C3/C4、血清 IgA、血清游离轻链","肾脏超声、肾活检","排除继发 IgA 沉积：肝硬化、IgA 血管炎（过敏性紫癜）、银屑病、强直性脊柱炎"],"grading":"Oxford MEST-C 评分：M（系膜增生）、E（毛细血管内增生）、S（节段硬化）、T（小管萎缩/间质纤维化 T0/T1/T2）、C（新月体）；T2 预后最差。"},"ddx":[{"name":"膜性肾病（gn_mn）","point":"与本类 gn_mn 的鉴别点：IgA 以血尿突出、蛋白尿多中度、补体正常、年轻人；MN 以肾病综合征为主、抗 PLA2R 抗体阳性、多中老年。"},{"name":"微小病变（gn_mcd）","point":"与本类 gn_mcd 的鉴别点：MCD 为突发大量蛋白尿、光镜正常、激素敏感；IgA 血尿显著、有系膜增生与 IgA 沉积。"},{"name":"肾病综合征（gn_ns）","point":"与本类 gn_ns 的鉴别点：IgA 多为肾炎型；若呈典型肾病综合征需评估是否合并足细胞病变，并活检确认。"},{"name":"急性链球菌感染后肾小球肾炎","point":"感染后 1–3 周出现血尿、水肿、高血压，补体 C3 明显降低并于 6–8 周恢复；IgA 为 1–3 天内、补体正常。"},{"name":"IgA 血管炎（过敏性紫癜性肾炎）","point":"有可触性紫癜、关节痛、腹痛，肾活检表现类似，但存在系统性的皮肤与消化道损害。"}],"tx":{"drug":[{"name":"ACEI/ARB","dose":"缬沙坦 80–160 mg qd 或依那普利 5–10 mg qd，按血压与蛋白尿滴定，目标蛋白尿 <0.5–1 g/d","note":"所有有蛋白尿者应试用 ≥3 个月，为基础治疗","renal":"Scr 升幅 ≤30% 可继续","hepatic":"重度肝功能不全慎用","interact":"不推荐与 ARB 联用；与 NSAIDs 合用致 AKI"},{"name":"SGLT2 抑制剂","dose":"达格列净 10 mg qd","note":"eGFR ≥20 者可作为减少蛋白尿的辅助治疗","renal":"eGFR <20 不起始","hepatic":"重度肝功能不全慎用","interact":"与利尿剂联用注意容量"},{"name":"布地奈德靶向缓释胶囊（Nefecon）","dose":"16 mg qd 口服 9 个月，停药时 2 周内 8 mg→4 mg 递减","note":"针对高危 IgA 肾病（蛋白尿 ≥1 g/d、eGFR ≥35）的肠道黏膜免疫治疗","renal":"eGFR <30 慎用","hepatic":"重度肝功能不全慎用","interact":"CYP3A4 抑制剂（酮康唑等）升高血药浓度"},{"name":"糖皮质激素（泼尼松）","dose":"0.5–1 mg/kg/d（最大 60 mg）口服，4–8 周后减量；或甲泼尼龙 0.5 g iv×3 d 后改口服；总疗程 ≤6 个月","note":"用于蛋白尿 >1 g/d 且 eGFR >50 的高危患者，需权衡感染风险","renal":"eGFR <30 获益有限","hepatic":"肝功能不全慎用","interact":"与 NSAIDs 合用增加消化道出血；长期用需补钙与维生素 D"},{"name":"环磷酰胺","dose":"0.5–1.0 g/m² 静脉冲击每月 1 次×6 个月，或 2 mg/kg/d 口服 3 个月","note":"用于激素依赖/抵抗或快速进展（新月体）者，注意骨髓抑制与性腺毒性","renal":"eGFR <30 减量","hepatic":"重度肝功能不全慎用","interact":"与别嘌醇合用增加骨髓抑制"},{"name":"吗替麦考酚酯","dose":"0.5–1.0 g bid 口服（儿童 15–23 mg/kg/d）","note":"激素替代或挽救治疗；妊娠禁用","renal":"eGFR <25 减量","hepatic":"重度肝功能不全减量","interact":"含镁/铝抗酸剂减少吸收；避免活疫苗"},{"name":"来氟米特","dose":"20 mg qd 口服","note":"可选免疫抑制剂；育龄女性需严格避孕","renal":"eGFR <30 慎用","hepatic":"肝功能不全禁用","interact":"利福平降低疗效；监测转氨酶"}],"nonDrug":["反复扁桃体炎诱发血尿者可考虑扁桃体切除（中国指南有条件推荐）","控制血压 <130/80 mmHg","新月体性（C1 以上）可激素冲击 + 环磷酰胺/利妥昔单抗","避免 NSAIDs 与肾毒性药物"],"life":["限盐 <5 g/d；戒烟；适度运动","每 3–6 个月监测尿蛋白与 eGFR","生育期女性使用免疫抑制剂前咨询避孕"]},"prog":"20 年肾存活约 60%–70%；持续蛋白尿 >1 g/d、高血压与 T2 病变为独立危险因素。补体旁路与肠道免疫靶向治疗可进一步延缓进展。","refs":["KDIGO 2021 肾小球疾病临床实践指南","中国 IgA 肾病临床诊疗指南（2023，中国医师协会肾脏内科医师分会）","IgA 肾病诊治中国专家共识（2021）"]},{"id":"gn_mn","name":"膜性肾病","aka":["MN","Membranous Nephropathy"],"rank":2,"basic":{"define":"以肾小球基底膜上皮侧免疫复合物沉积、基底膜增厚为特征的肾小球疾病，约 70%–80% 为原发性（抗 PLA2R 抗体相关），其余为继发性（狼疮、肿瘤、药物、乙肝/丙肝）。","risk":["中老年（40–60 岁）男性","抗 PLA2R 抗体阳性","恶性肿瘤（老年需筛查）","HBV/HCV 感染、狼疮","NSAIDs、青霉胺、金制剂等药物"],"epi":"我国 MN 约占原发性肾小球疾病的 20%–25%，近 10 年发病率上升，与 PM2.5 等环境污染暴露相关。"},"patho":"抗 PLA2R（约 70%–80%）或 THSD7A 抗体与足细胞抗原在上皮侧形成原位免疫复合物，激活补体（C5b-9），损伤足细胞与基底膜，形成大量蛋白尿与上皮侧沉积。","dx":{"criteria":["肾病综合征表现：蛋白尿 >3.5 g/d、血浆白蛋白 <30 g/L、水肿、高脂血症","血清抗 PLA2R 抗体阳性（特异性 >95%，可替代部分活检）","肾活检：基底膜弥漫增厚、PASM 见钉突；IgG（尤 IgG4）与 C3 沿基底膜颗粒样沉积；电镜见上皮侧致密物","排除继发因素：ANA、抗 dsDNA、HBV/HCV、肿瘤筛查","KDIGO 危险分层：低危（蛋白尿 <4 g/d、eGFR 正常、抗 PLA2R <50 RU/mL）、中危（4–8 g/d）、高危（>8 g/d 或 eGFR 下降）"],"workup":["24 h 尿蛋白定量、血清白蛋白、UACR","抗 PLA2R 抗体滴度（ELISA 定量）","血肌酐、eGFR、血脂、血糖","ANA/抗 dsDNA、补体、HBV/HCV/HIV、肿瘤标志物","肾脏超声 + 肾活检","老年患者肿瘤筛查（胸部 CT、肠镜、前列腺/乳腺检查）"],"grading":"病理分期（Ehrenreich-Churg）：Ⅰ 上皮侧致密物无基底膜增生；Ⅱ 钉突形成；Ⅲ 致密物被包埋；Ⅳ 基底膜不规则增厚伴致密物吸收。"},"ddx":[{"name":"IgA 肾病（gn_iga）","point":"与本类 gn_iga 的鉴别点：MN 以肾病综合征为主、抗 PLA2R 阳性、中老年；IgA 以反复发作血尿为主、补体正常、年轻人。"},{"name":"微小病变（gn_mcd）","point":"与本类 gn_mcd 的鉴别点：MCD 光镜基本正常、免疫荧光阴性、激素高度敏感；MN 基底膜增厚、颗粒样沉积、激素反应慢。"},{"name":"肾病综合征（gn_ns）","point":"与本类 gn_ns 的鉴别点：MN 是成人 NS 常见病理类型（约 20%–30%），需活检或抗 PLA2R 抗体确认；儿童及青年突发 NS 更可能是 MCD。"},{"name":"糖尿病肾病（ckd_dkd）","point":"与 ckd 大类 ckd_dkd 的鉴别点：DKD 有糖尿病史、伴视网膜病变、无免疫复合物颗粒样沉积；MN 常有 PLA2R 抗体阳性。"},{"name":"狼疮性肾炎（Ⅴ型）","point":"多系统表现、ANA/抗 dsDNA 阳性、低补体，病理可为膜型，需全套免疫学评估。"}],"tx":{"drug":[{"name":"ACEI/ARB","dose":"缬沙坦 80–160 mg qd 或依那普利 5–20 mg qd，按血压滴定","note":"所有患者的基础治疗；低危者先观察 6 个月","renal":"Scr 升幅 ≤30% 可继续","hepatic":"重度肝功能不全慎用","interact":"不推荐与 ARB 联用"},{"name":"呋塞米（±螺内酯）","dose":"呋塞米 20–40 mg qd–bid；可加螺内酯 20 mg qd（注意高钾）","note":"水肿明显者；低白蛋白血症时利尿效果差","renal":"按容量调整","hepatic":"肝硬化慎用螺内酯","interact":"与 ACEI/ARB 合用高钾风险"},{"name":"利妥昔单抗","dose":"1 g iv 于第 1、15 天（共 2 g）；或 375 mg/m² qw×4 次；按 B 细胞计数与抗体滴度决定复治","note":"中-高危原发性 MN 的一线免疫治疗（KDIGO 2021）","renal":"无需调整","hepatic":"遵说明书","interact":"避免活疫苗；与免疫抑制剂联用增加感染"},{"name":"环磷酰胺 + 糖皮质激素（改良 Ponticelli 方案）","dose":"第 1–3 月：甲泼尼龙 1 g iv×3 d，随后泼尼松 0.5 mg/kg/d×27 d；第 4–6 月：环磷酰胺 2.0–2.5 mg/kg/d 口服","note":"高危或利妥昔单抗不可及时；注意骨髓抑制与性腺毒性","renal":"eGFR <30 减量","hepatic":"重度肝功能不全慎用","interact":"与别嘌醇合用增加骨髓抑制"},{"name":"钙调神经磷酸酶抑制剂","dose":"环孢素 3.5 mg/kg/d 分 2 次（谷浓度 125–175 ng/mL）；或他克莫司 0.05–0.1 mg/kg/d 分 2 次（谷浓度 5–10 ng/mL），疗程 6–12 个月","note":"与低剂量激素联用，用于激素抵抗或不能耐受环磷酰胺者","renal":"eGFR 下降时减量，监测血药浓度与肾毒性","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂（唑类、克拉霉素、葡萄柚）升高浓度"}],"nonDrug":["低危者先观察 6 个月，约 30% 自发缓解","筛查并治疗继发病因（肿瘤、HBV、狼疮、药物）","血栓预防：白蛋白 <25 g/L 且蛋白尿 >10 g/d 者可考虑预防性抗凝（评估出血）","避免肾毒性药物"],"life":["限盐 <5 g/d；蛋白摄入 0.8–1.0 g/kg/d","免疫抑制期间预防肺孢子菌（TMP-SMX）与乙肝再激活","每 3 个月监测尿蛋白、白蛋白、抗 PLA2R 滴度与肾功能"]},"prog":"约 1/3 自发缓解、1/3 持续蛋白尿但肾功能稳定、1/3 进展至 ESRD（10 年约 30%–40%）。抗 PLA2R 滴度的免疫学缓解早于临床缓解，是监测复发的关键指标。","refs":["KDIGO 2021 肾小球疾病临床实践指南","中国成人原发性膜性肾病诊疗专家共识（2021）","中国原发性肾小球疾病诊治指南（2024）"]},{"id":"gn_mcd","name":"微小病变型肾病","aka":["MCD","Minimal Change Disease","微小病变","脂性肾病"],"rank":3,"basic":{"define":"光镜下肾小球基本正常、电镜下足突弥漫融合的原发性肾小球病，临床表现为突发肾病综合征，对糖皮质激素高度敏感。","risk":["儿童（2–6 岁高峰）与年轻成人","呼吸道感染、过敏","NSAIDs 等药物（成人继发）","霍奇金淋巴瘤（继发）"],"epi":"儿童肾病综合征中约 80%–90% 为 MCD；成人原发性 NS 中约 10%–15%。男女比例约 1.5–2:1。"},"patho":"T 细胞功能异常导致循环通透性因子损伤足细胞，引起足突融合与滤过屏障破坏；蛋白质以低分子量蛋白丢失为主，继发高脂血症与高凝状态。","dx":{"criteria":["突发大量蛋白尿（成人 >3.5 g/d，儿童 >50 mg/kg/d）、低白蛋白血症（<30 g/L）、水肿、高脂血症","选择性蛋白尿为主，镜下血尿少见（约 20%–30% 微量）","肾功能多数正常、血压正常、补体正常","肾活检：光镜基本正常，免疫荧光阴性，电镜足突弥漫融合","激素敏感：泼尼松 1 mg/kg/d（儿童 60 mg/m²/d）8 周内完全缓解（儿童 ≥90%，成人约 80%）"],"workup":["24 h 尿蛋白定量、血清白蛋白、血脂","尿常规 + 尿沉渣","血肌酐、eGFR、C3/C4、血糖","肾脏超声（双肾增大、皮质回声增强）","肾活检（成人 NS 常规；儿童典型表现且激素敏感者可免）","继发因素排查：药物史、肿瘤筛查（成人 >50 岁）"],"grading":"临床分型：激素敏感型（SSNS）、激素依赖型（SDNS，减量/停药 2 周内复发）、频繁复发型（FRNS，6 个月内 ≥2 次或 1 年内 ≥4 次）、激素抵抗型（SRNS）。"},"ddx":[{"name":"IgA 肾病（gn_iga）","point":"与本类 gn_iga 的鉴别点：MCD 突发 NS、镜下血尿少见、补体正常；IgA 以发作性血尿为主、蛋白尿中度、系膜区 IgA 沉积。"},{"name":"膜性肾病（gn_mn）","point":"与本类 gn_mn 的鉴别点：MN 多中老年、抗 PLA2R 阳性、光镜基底膜增厚、激素反应慢；MCD 年轻、激素快速敏感。"},{"name":"肾病综合征（gn_ns）","point":"与本类 gn_ns 的鉴别点：MCD 是 NS 的常见病理类型，尤其儿童；NS 为综合征描述，需活检明确病理并排除继发因素。"},{"name":"局灶节段性肾小球硬化（FSGS）","point":"同样表现 NS，但见节段硬化与间质纤维化，激素抵抗多见，预后差于 MCD。"},{"name":"IgA 血管炎/狼疮性肾炎（MCD 样表现）","point":"有紫癜、关节痛、系统表现或自身抗体阳性，提示继发。"}],"tx":{"drug":[{"name":"泼尼松","dose":"成人 1 mg/kg/d（最大 60 mg）晨顿服，4–8 周完全缓解后缓慢减量，总疗程约 6 个月；儿童 60 mg/m²/d（最大 60 mg），4–6 周后改为间歇减量","note":"首选；激素敏感者 8 周内缓解；频繁复发者需加免疫抑制剂","renal":"肾功能正常时无需调整","hepatic":"肝功能不全慎用；肝病者改泼尼松龙","interact":"长期使用需补钙与维生素 D；与 CYP3A4 抑制剂相互作用"},{"name":"环磷酰胺","dose":"1.5–2.0 mg/kg/d 口服 8–12 周（儿童 2 mg/kg/d）","note":"用于频繁复发/激素依赖；成人累积剂量 <36 g","renal":"eGFR 下降减量","hepatic":"慎用","interact":"别嘌醇增加骨髓抑制"},{"name":"环孢素","dose":"3–5 mg/kg/d 分 2 次，谷浓度 100–150 ng/mL，疗程 1–2 年","note":"激素抵抗或依赖者的替代，监测肾毒性","renal":"长期使用需监测血肌酐","hepatic":"肝功能不全减量","interact":"强 CYP3A4 抑制剂升高浓度"},{"name":"他克莫司","dose":"0.05–0.1 mg/kg/d 分 2 次，谷浓度 5–10 ng/mL","note":"激素依赖/频繁复发的替代","renal":"监测血药浓度与肾功能","hepatic":"减量","interact":"CYP3A4 相互作用"},{"name":"吗替麦考酚酯","dose":"0.5–1.0 g bid（儿童 600–1200 mg/m²/d 分 2 次）","note":"频繁复发型可用；妊娠禁用","renal":"eGFR <25 减量","hepatic":"重度肝功能不全减量","interact":"与抗酸药分开服用"},{"name":"呋塞米（辅助消肿）","dose":"20–40 mg qd–bid；严重低白蛋白血症时可先输 20% 人血白蛋白 50–100 mL 后利尿","note":"仅对症，不改变病程","renal":"按容量调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["激素抵抗者（成人 8–12 周、儿童 4 周无缓解）需重新评估病理（FSGS？）并行基因检测","缓解期避免感染诱因，及时治疗感染灶","白蛋白 <20 g/L 时评估预防性抗凝","严重水肿限盐限液"],"life":["低盐 <3–5 g/d，缓解后逐步恢复","长期激素者监测骨密度、补钙+维生素 D、胃黏膜保护","儿童关注生长发育；免疫抑制期间禁用活疫苗"]},"prog":"儿童激素敏感率 >90%，但约 50%–70% 会复发；成人激素缓解率约 80%，远期复发率高。少数转为 FSGS 或出现 AKI。","refs":["KDIGO 2021 肾小球疾病临床实践指南","中国成人肾病综合征免疫抑制治疗专家共识（2019）","儿童激素敏感型肾病综合征诊疗循证指南（2021，中华医学会儿科学分会）"]},{"id":"gn_ns","name":"肾病综合征","aka":["NS","Nephrotic Syndrome"],"rank":4,"basic":{"define":"以大量蛋白尿（>3.5 g/d）、低白蛋白血症（<30 g/L）、水肿与高脂血症为特征的临床综合征；符合前两条即可诊断，需进一步明确病因与病理类型。","risk":["感染（腹膜炎、肺炎、蜂窝织炎）","血栓栓塞（尤其肾静脉血栓）","急性肾损伤","蛋白质营养不良与脂代谢紊乱","继发因素（糖尿病、狼疮、乙肝、肿瘤、药物）"],"epi":"我国成人肾病综合征年发病率约 1/10 万，病理以膜性肾病、IgA 肾病、微小病变为主；儿童以微小病变为第一病因。"},"patho":"肾小球滤过屏障（内皮、基底膜、足细胞）损伤导致大量蛋白漏出，白蛋白下降引起胶体渗透压降低与水肿；肝脏代偿合成脂蛋白与凝血因子，形成高脂血症与高凝状态。","dx":{"criteria":["大量蛋白尿：24 h 尿蛋白 >3.5 g/d，或 UACR >300 mg/g 伴低白蛋白","低白蛋白血症：血浆白蛋白 <30 g/L","水肿（眼睑、下肢甚至胸腹水）","高脂血症（胆固醇、LDL 升高）","排除继发病因：糖尿病、狼疮、乙肝/丙肝、HIV、淀粉样变、肿瘤、药物","病理类型决定治疗：MCD、MN、IgA、FSGS、MPGN、狼疮性肾炎等"],"workup":["24 h 尿蛋白定量、UACR、血白蛋白、血脂、D-二聚体、纤维蛋白原、AT-III","血肌酐、eGFR、电解质、血糖、HbA1c","免疫学：ANA、抗 dsDNA、补体、ANCA、抗 PLA2R、血清蛋白电泳与免疫固定电泳","感染筛查：HBV、HCV、HIV、梅毒","肾脏超声 + 肾活检（成人必需，除有明确禁忌）","并发症评估：肾静脉血栓（超声/CT）、感染（白细胞、CRP）、AKI（肌酐）"],"grading":"按病理类型（MCD、MN、FSGS、IgAN、MPGN、狼疮性肾炎分型）分层治疗与预后。"},"ddx":[{"name":"IgA 肾病（gn_iga）","point":"与本类 gn_iga 的鉴别点：IgA 多为肾炎型（血尿+中度蛋白尿），部分可呈 NS；需活检确认系膜 IgA 沉积。"},{"name":"膜性肾病（gn_mn）","point":"与本类 gn_mn 的鉴别点：MN 是成人 NS 最常见病理类型，抗 PLA2R 抗体阳性，需活检或血清学确认。"},{"name":"微小病变（gn_mcd）","point":"与本类 gn_mcd 的鉴别点：MCD 突发 NS、激素敏感、病理基本正常；NS 为综合征，需活检区分病理类型。"},{"name":"糖尿病肾病（ckd_dkd）","point":"与 ckd 大类 ckd_dkd 的鉴别点：DKD 有长期糖尿病史，蛋白尿逐渐出现（非突发），伴视网膜病变。"},{"name":"心源性水肿/肝硬化腹水","point":"BNP 升高、颈静脉压升高或肝病背景，无明显大量蛋白尿，水肿以下肢/腹水为主。"}],"tx":{"drug":[{"name":"ACEI/ARB","dose":"依那普利 5–10 mg qd 或缬沙坦 80–160 mg qd，按血压滴定至足量","note":"所有蛋白尿性 NS 的基础治疗，监测肌酐与血钾","renal":"Scr 升幅 >30% 减量","hepatic":"重度肝功能不全慎用","interact":"不推荐与 ARB 联用；与螺内酯合用高钾"},{"name":"呋塞米 + 螺内酯","dose":"呋塞米 20–40 mg qd–bid，螺内酯 20 mg qd；可改托拉塞米 10–20 mg qd","note":"水肿对症；低白蛋白时利尿效果差，可输白蛋白后利尿","renal":"按容量与电解质调整","hepatic":"肝硬化慎用","interact":"NSAIDs 减弱利尿"},{"name":"糖皮质激素（泼尼松）","dose":"按病理类型：MCD 1 mg/kg/d（最大 60 mg）4–8 周；IgA 0.5–1 mg/kg/d；FSGS 1 mg/kg/d 4–16 周","note":"须依病理类型决定；激素抵抗者加免疫抑制剂","renal":"肾功能不全慎用","hepatic":"肝功能不全时用泼尼松龙","interact":"见各病理条目"},{"name":"他汀类药物","dose":"阿托伐他汀 20 mg qn 或瑞舒伐他汀 10 mg qn","note":"NS 继发高脂血症，改善心血管风险","renal":"瑞舒伐他汀 eGFR <30 减量","hepatic":"活动性肝病禁用","interact":"与环孢素合用增加肌病风险"},{"name":"预防性抗凝","dose":"低分子肝素（如依诺肝素 40 mg 皮下 qd）或华法林（INR 2–3）","note":"白蛋白 <20–25 g/L 且蛋白尿 >10 g/d 者可考虑，需评估出血风险","renal":"eGFR <30 减量并监测抗 Xa","hepatic":"肝硬化出血风险高","interact":"与 NSAIDs、抗血小板药合用增加出血"}],"nonDrug":["肾活检明确病理类型，按类型选择免疫抑制方案","控制感染；接种肺炎球菌、流感疫苗","血栓高危者行肾静脉超声","难治性水肿可间断输注人血白蛋白","限盐 <5 g/d，按尿量调整液量"],"life":["蛋白摄入 0.8–1.0 g/kg/d，避免高蛋白加重漏出","预防感染；合并糖尿病/高血压者强化管理","定期复查尿蛋白、白蛋白、肾功能与凝血，复发时及早复诊"]},"prog":"预后取决于病理类型与治疗反应：MCD 大多缓解但复发多见；MN 约 1/3 自发缓解；FSGS 与 MPGN 预后较差。血栓、感染与 AKI 是急性期主要死亡原因。","refs":["KDIGO 2021 肾小球疾病临床实践指南","中国成人肾病综合征免疫抑制治疗专家共识（2019）","中国原发性肾小球疾病诊治指南（2024）"]}]},{"id":"gn_more","name":"其他肾小球病","rank":4,"summary":"急性感染后肾炎、急进性肾炎、FSGS 与膜增生性肾炎：均为免疫性肾小球损伤，关键是查补体（C3/C4）与肾功能下降速度，急进性者尽早活检并考虑甲泼尼龙冲击。","compare":[{"diseaseId":"gn_agn","dx":"链球菌感染后 1–3 周水肿、血尿、高血压，C3 下降且 6–8 周内恢复，ASO 升高","key":"感染后 1–3 周 + C3 下降且 8 周内恢复正常"},{"diseaseId":"gn_rpgn","dx":"数周内 eGFR 快速下降，活检见新月体（≥50%），ANCA 或抗 GBM 可阳性","key":"肾功能数周内快速恶化 + 活检新月体，需紧急免疫抑制"},{"diseaseId":"gn_fsgs","dx":"大量蛋白尿、高血压、肾功能进行性下降；光镜局灶节段硬化、电镜足突弥漫融合","key":"激素抵抗型肾病综合征需激素 + 钙调磷酸酶抑制剂，预后差于 MCD"},{"diseaseId":"gn_mpgn","dx":"血尿 + 蛋白尿 + 持续低补体（C3），电镜见内皮下/系膜区沉积与双轨征","key":"持续性低补体 + 病理双轨征，需查感染与单克隆免疫球蛋白"}],"diseases":[{"id":"gn_agn","name":"急性链球菌感染后肾小球肾炎","aka":["急性肾小球肾炎","APSGN","Acute Post-streptococcal Glomerulonephritis"],"rank":1,"basic":{"define":"A 组 β 溶血性链球菌感染（咽炎或皮肤感染）后 1–3 周发生的急性肾炎综合征，表现为血尿、蛋白尿、水肿、高血压与一过性肾功能减退，儿童多见、多数自限。","risk":["儿童（5–12 岁）及青壮年","链球菌性咽炎或脓疱疮流行期","居住拥挤、卫生条件差","皮肤感染（脓疱病）","营养不良"],"epi":"儿童急性肾炎最常见原因，占 >90%；成人亦可发生但较少，发展中国家更常见。"},"patho":"链球菌抗原植入肾小球后激活补体替代途径，形成上皮下免疫复合物沉积（「驼峰」），引发弥漫毛细血管内增生与中性粒细胞浸润，致滤过率下降、钠水潴留与血尿。","dx":{"criteria":["前驱感染后 1–3 周（咽炎 7–14 天，皮肤感染 2–3 周）出现血尿（多为茶色肉眼血尿）","补体 C3 下降，C4 正常，6–8 周内恢复正常（持续低补体提示其他病因）","ASO 或抗 DNA 酶 B 升高（咽部感染尤明显）","水肿（晨起眼睑颜面）、高血压、少尿，肌酐轻度升高","肾活检：毛细血管内增生性肾炎，电镜上皮下驼峰，免疫荧光 C3 + IgG 颗粒沉积"],"workup":["尿常规 + 尿沉渣（畸形红细胞、红细胞管型）","肌酐、eGFR、电解质、C3/C4","ASO、抗 DNA 酶 B、咽培养或皮肤拭子","腹部超声（排除梗阻）、血压监测","存在非典型表现时肾活检"],"grading":"亚临床/显性/重症（少尿、高钾、心衰、高血压脑病）。"},"ddx":[{"name":"急进性肾小球肾炎","point":"与本类中急进性肾小球肾炎的鉴别：APSGN 肾功能多在 1–2 周内改善；RPGN 持续恶化、新月体 >50%、ANCA/抗 GBM 阳性。"},{"name":"IgA 肾病","point":"与已有 IgA 肾病鉴别：IgA 肾病在感染后 1–3 天出现血尿，补体正常；APSGN 有 1–3 周潜伏期且 C3 下降。"},{"name":"膜增生性肾小球肾炎","point":"低补体超过 8 周、蛋白尿更重，提示 MPGN 或 C3 肾小球病。"},{"name":"尿路感染","point":"尿路感染者有尿频、尿急、发热与脓尿，菌尿阳性，肾功能正常。"},{"name":"过敏性紫癜性肾炎","point":"伴可触及紫癜、关节痛与腹痛，IgA 沉积为主。"}],"tx":{"drug":[{"name":"青霉素（清除链球菌）","dose":"青霉素 V 250–500 mg tid 口服 10 天，或苄星青霉素 60 万–120 万 U 单次肌注（按年龄）","note":"仅阻断传播、清除携带，不改变肾炎病程；过敏者改用红霉素","renal":"轻度不全无需调整","hepatic":"遵说明书","interact":"丙磺舒延长半衰期"},{"name":"呋塞米（水肿/容量负荷）","dose":"20–40 mg qd–bid 口服或静注，按尿量与体重调整","note":"减轻水肿与高血压；避免过度利尿致肾灌注不足","renal":"eGFR 降低时加量或改静脉","hepatic":"遵说明书","interact":"与氨基糖苷类合用增加耳毒性"},{"name":"氨氯地平（高血压）","dose":"2.5–5 mg qd，按血压调整；儿童 0.1–0.2 mg/kg/d","note":"容量型高血压优先限盐利尿；必要时联合 ACEI/ARB","renal":"遵说明书","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂升高浓度"},{"name":"高钾血症处理","dose":"血钾 >6.0 mmol/L 或心电图改变：10% 葡萄糖酸钙 10 mL 静推；胰岛素 10 U + 50% 葡萄糖 25 g 静滴；沙丁胺醇雾化；聚苯乙烯磺酸钙（降钾树脂）15 g tid","note":"急性少尿高钾是最主要致死原因，顽固者透析","renal":"肾功能不全加大剂量并监测","hepatic":"遵说明书","interact":"保钾药、RAAS 抑制剂加重高钾"}],"nonDrug":["限盐（<2 g/d 钠）、少尿者限水，卧床休息","严重少尿、心衰、肺水肿、高钾难纠正时血液透析","一般不用糖皮质激素，仅活检证实新月体性肾炎的重症者用"],"life":["水肿与高血压消退后渐恢复活动，随访尿常规与血肌酐至 6–12 个月","镜下血尿可持续 1–2 年，每年尿检","扁桃体反复感染者不常规切除"]},"prog":"儿童 >95% 完全恢复，成人恢复率约 60%–80%；约 5%–10% 成人进展为 CKD。合并新月体或持续大量蛋白尿者预后较差。","refs":["《内科学》第 9 版 第五篇 急性肾小球肾炎","中华医学会儿科学分会肾脏学组《急性链球菌感染后肾小球肾炎诊治指南》2015","KDIGO Glomerular Diseases Guideline 2021（感染后肾小球肾炎章节）"]},{"id":"gn_rpgn","name":"急进性肾小球肾炎","aka":["新月体性肾小球肾炎","RPíndice","RPGN","Rapidly Progressive Glomerulonephritis"],"rank":2,"basic":{"define":"以急性肾炎综合征起病、肾功能在数周至数月内迅速恶化的一组肾小球疾病，病理为广泛新月体（>50% 肾小球），不及时治疗多在 1 年内进入终末期肾病。","risk":["抗 GBM 病（Goodpasture，尤年轻男性吸烟者）","ANCA 相关血管炎（55 岁以上多见）","免疫复合物介导：狼疮、感染后、IgA、冷球蛋白","吸烟、碳氢化合物暴露、感染（抗 GBM）","既往免疫抑制或抗 GBM/ANCA 阳性"],"epi":"占肾活检 2%–5%；我国以 ANCA 相关（约 60%）与免疫复合物型为主，抗 GBM 型较少。"},"patho":"抗 GBM 抗体结合 IV 型胶原 α3 链，或 ANCA 激活中性粒细胞致毛细血管壁坏死；纤维蛋白在包曼囊沉积 → 壁层上皮增生形成新月体，压迫毛细血管袢使滤过率骤降，纤维化后肾小球硬化。","dx":{"criteria":["血尿（常肉眼血尿）、蛋白尿与肾功能在数周内进行性恶化（eGFR 下降 >30%/3 个月或肌酐翻倍）","尿沉渣见多种畸形红细胞、红细胞管型；常伴少尿","分型：Ⅰ型抗 GBM 阳性（可伴肺出血）；Ⅱ型免疫复合物（狼疮、感染后）；Ⅲ型 ANCA 阳性（MPO 或 PR3）","肾活检为确诊关键：>50% 肾小球新月体，免疫荧光示线状（Ⅰ型）、颗粒状（Ⅱ型）或寡免疫（Ⅲ型）沉积","治疗前评估：抗 GBM、ANCA、ANA/dsDNA、ANCA 分型、补体、HBV/HCV、肺 CT"],"workup":["血肌酐、eGFR 动态、尿常规与沉渣","抗 GBM 抗体、ANCA（MPO/PR3）、ANA、抗 dsDNA","胸部 CT（肺出血）、肺功能（DLCO 升高）","肾活检（含免疫荧光与电镜）","感染筛查、嗜酸性粒细胞（EGPA）"],"grading":"按新月体比例与纤维化程度判断可逆性；ANCA 血管炎可依 Berden 分型（局灶/新月体/混合/硬化型）。"},"ddx":[{"name":"急性链球菌感染后肾小球肾炎","point":"与本类中急性链球菌感染后肾小球肾炎的鉴别：APSGN 肾功多 1–2 周改善、C3 8 周恢复；RPGN 进行性恶化。"},{"name":"IgA 肾病","point":"慢进展为主，少数伴新月体（→ 新月体性 IgA 肾病）；感染后 1–3 天血尿，通常肾功能正常。"},{"name":"急性肾小管坏死","point":"有缺血/毒物史，尿钠高、棕色颗粒管型，无血尿与大量蛋白尿。"},{"name":"狼疮性肾炎","point":"女性、多系统受累（皮疹、关节炎、低补体、ANA/dsDNA 阳性）。"},{"name":"血栓性微血管病","point":"血小板减少、破碎红细胞、ADAMTS13 缺乏，肾功能与蛋白尿并存。"}],"tx":{"drug":[{"name":"甲泼尼龙冲击","dose":"500–1000 mg/d 静脉滴注 × 3 天，随后口服泼尼松 1 mg/kg/d（最大 60–80 mg/d），4–8 周后渐减","note":"确诊后尽早启动；监测感染、血糖、血压、消化道出血；泼尼松 ≥20 mg/d 联用免疫抑制剂者预防卡氏肺孢子虫","renal":"冲击前评估容量与心功能","hepatic":"遵说明书","interact":"CYP3A4 抑制剂升高浓度；与 NSAIDs 合用增加溃疡风险"},{"name":"环磷酰胺","dose":"口服 2–3 mg/kg/d，或静脉 15 mg/kg（最大 1 g）每 2 周 × 3 次后隔月；诱导 6 个月后转维持","note":"重症/肺出血首选；监测血常规（中性粒细胞 >1.5×10⁹/L）、肝功、出血性膀胱炎（充分水化）","renal":"eGFR <30 减量 25%–50%","hepatic":"肝功能不全减量","interact":"别嘌醇增加骨髓抑制；增强华法林抗凝"},{"name":"利妥昔单抗","dose":"375 mg/m² 每周 1 次 × 4 次，或 1000 mg 第 1、15 天","note":"ANCA 血管炎诱导与维持的有效替代（环磷酰胺禁忌时）；筛查乙肝，高载量者先抗病毒","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用增加感染"},{"name":"血浆置换（抗 GBM 型首选）","dose":"每次置换 4 L（60 mL/kg），每日 1 次 × 14 天或至抗体转阴","note":"合并肺出血时尤其必要；置换后补 IVIG","renal":"遵说明书","hepatic":"遵说明书","interact":"置换后免疫抑制剂需在置换后给"},{"name":"硫唑嘌呤（维持期）","dose":"1.5–2 mg/kg/d 口服，或利妥昔单抗维持，疗程 18–24 个月（ANCA 血管炎）","note":"维持期不可过早停药（复发率高）；监测血常规","renal":"遵说明书","hepatic":"遵说明书","interact":"与别嘌醇叠加骨髓抑制"}],"nonDrug":["抗 GBM 病：血浆置换 + 激素 + 环磷酰胺（±利妥昔）","起病即需透析但新月体可逆者积极免疫抑制，部分可脱离透析","肺出血、急性肾衰需呼吸机/CRRT 支持","诱导 6 个月评估，无效者转维持透析"],"life":["诱导期每周查血常规、肝功、肌酐与抗体滴度","预防卡氏肺孢子虫（SMZ-TMP 800/160 mg 隔日）、监测乙肝再激活","避免吸烟与造影剂等肾毒性暴露"]},"prog":"抗 GBM 型起病即需透析者 90% 不恢复；ANCA 型 6 个月缓解率 70%–90%，1–3 年复发率 20%–40%。未治疗者多在数月内进入终末期肾病。","refs":["中华医学会肾脏病学分会《中国急进性肾小球肾炎诊治指南》2021","《内科学》第 9 版 第五篇 急进性肾小球肾炎","KDIGO 2024 Clinical Practice Guideline for the Management of ANCA-associated Vasculitis","KDIGO Glomerular Diseases Guideline 2021（抗 GBM 病）"]},{"id":"gn_fsgs","name":"局灶节段性肾小球硬化","aka":["FSGS","Focal Segmental Glomerulosclerosis"],"rank":3,"basic":{"define":"以部分肾小球的节段性硬化及足细胞损伤为特征的肾小球病，常表现为大量蛋白尿或肾病综合征，激素抵抗比例高、预后差于微小病变。","risk":["非洲裔（APOL1 风险等位基因）","肥胖（肥胖相关 FSGS）、代谢综合征","HIV、干扰素、锂剂、海洛因","家族性足细胞基因突变（NPHS1/2、WT1、INF2）","肾单位减少（反流性肾病、单肾）"],"epi":"占成人原发性肾病综合征 20%–35%，非洲裔中约 50%；我国约 10%–20%，是青年人 ESRD 的重要病因。"},"patho":"足细胞损伤（循环因子或基因/APOL1 易感）→ 足突融合、足细胞脱落 → 节段性毛细血管袢硬化；持续足细胞丢失致球性硬化，蛋白尿加重间质纤维化。","dx":{"criteria":["大量蛋白尿（多 >3.5 g/d，肾病综合征范围）伴水肿、高血压","尿沉渣可有镜下血尿，肾功能可正常或下降","肾活检：局灶节段性硬化（光镜）、电镜足突弥漫融合、免疫荧光 IgM 与 C3 节段沉积；需排除继发因素","激素抵抗：足量激素（1 mg/kg 或 60–80 mg/d）儿童 8 周、成人 8–16 周未缓解","遗传性/继发性：查 HIV、干扰素史、家族史；儿童可做足细胞基因检测"],"workup":["24 h 尿蛋白或 UACR、血白蛋白、血脂、肌酐/eGFR","肾活检（含 IF、电镜）","HIV、HBV/HCV、结核筛查","家族史与必要基因检测、APOL1 考虑","糖耐量、体重指数（肥胖相关）"],"grading":"Columbia 分型：非特异型（NOS）、门部型、细胞型、顶端型（tip lesion）；顶端型与细胞型激素反应较好。"},"ddx":[{"name":"急进性肾小球肾炎","point":"与本类中急进性肾小球肾炎的鉴别：RPGN 新月体 >50%、肾功能数周恶化；FSGS 以蛋白尿为主。"},{"name":"微小病变（MCD）","point":"MCD 起病急、光镜正常、激素 8 周缓解 >80%；FSGS 有节段硬化、激素抵抗更常见。"},{"name":"膜性肾病","point":"中老年、抗 PLA2R 阳性，病理上皮下颗粒沉积，FSGS 为节段硬化与足突融合。"},{"name":"IgA 肾病","point":"以系膜增生与 IgA 沉积为特征，蛋白尿多 <2 g/d，FSGS 以大量蛋白尿为主。"},{"name":"糖尿病肾病","point":"K-W 结节、基底膜增厚，长期糖尿病史，常伴视网膜病变。"}],"tx":{"drug":[{"name":"泼尼松（初治）","dose":"1 mg/kg/d（最大 80 mg/d，晨服）或隔日 2 mg/kg × 8 周，有效者渐减，总疗程 6 个月；8–16 周无缓解加免疫抑制剂","note":"成人完全缓解率仅约 20%–30%；减量宜慢以防复发","renal":"遵说明书","hepatic":"遵说明书","interact":"与 NSAIDs、利尿剂合用增加溃疡与低钾"},{"name":"环孢素 A","dose":"3–5 mg/kg/d 分 2 次，谷浓度 100–150 ng/mL，疗程 ≥6 个月；3 个月无反应停药","note":"激素抵抗型的一线替代；监测肾功能、血压、血镁，少食高钾食物","renal":"肌酐上升 >30% 减量","hepatic":"肝功能不全减量","interact":"酮康唑、维拉帕米、地尔硫䓬升高浓度"},{"name":"他克莫司","dose":"0.05–0.1 mg/kg/d 分 2 次，谷浓度 5–10 ng/mL（诱导）或 3–8 ng/mL（维持）","note":"激素抵抗型有效；监测血糖、血镁与神经毒性","renal":"eGFR <60 慎用，监测肌酐","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂/诱导剂显著影响浓度"},{"name":"吗替麦考酚酯（辅助）","dose":"0.5–1 g bid（儿童 600–1200 mg/m²/d），常与激素或钙调磷酸酶抑制剂联用","note":"用于激素抵抗或复发；致畸，妊娠禁用","renal":"遵说明书","hepatic":"遵说明书","interact":"与阿昔洛韦、别嘌醇合用增加骨髓抑制"},{"name":"ACEI/ARB（保肾基础）","dose":"雷米普利 2.5–10 mg qd 或缬沙坦 80–160 mg qd，加量至耐受；血压目标 <125/75 mmHg（蛋白尿 >1 g/d）","note":"所有 FSGS 患者的基础治疗；监测肌酐与血钾","renal":"肌酐上升 >30% 减量","hepatic":"遵说明书","interact":"与螺内酯/补钾合用致高钾；与 NSAIDs 合用降低滤过"}],"nonDrug":["激素抵抗型：激素 + 钙调磷酸酶抑制剂，无效可考虑利妥昔单抗","继发性：控制体重、治疗 HIV、停用干扰素/锂剂","终末期：透析或肾移植，移植后复发率 20%–30%"],"life":["限盐（<6 g/d）、控制体重、血压 <125/75 mmHg","他汀调脂（LDL-C <2.6 mmol/L）","每 3–6 个月查肌酐与 24 h 尿蛋白或 UACR"]},"prog":"激素敏感者预后与 MCD 相近；激素抵抗者 5–10 年内约 30%–50% 进展为 ESRD。顶端型缓解率较高，塌陷型（HIV 相关）进展快。","refs":["中华医学会肾脏病学分会《原发性肾病综合征诊疗指南》（2021 相关更新）","《内科学》第 9 版 第五篇 局灶节段性肾小球硬化","KDIGO Glomerular Diseases Guideline 2021（FSGS 章节）"]},{"id":"gn_mpgn","name":"膜增生性肾小球肾炎","aka":["MPGN","系膜毛细血管性肾小球肾炎","膜性增生性肾小球肾炎","Membranoproliferative Glomerulonephritis"],"rank":4,"basic":{"define":"以系膜细胞增生、系膜基质插入内皮下（双轨）、基底膜增厚为特征的慢性肾小球肾炎，按免疫荧光分为免疫复合物型与 C3 肾小球病（补体替代途径异常）。","risk":["HBV/HCV 感染（我国重要病因）","冷球蛋白血症（合并丙肝）","单克隆免疫球蛋白血症（如骨髓瘤、华氏巨球蛋白血症）","狼疮性肾炎","补体替代途径调节异常（C3 肾炎因子）","年龄 8–30 岁，青壮年多见"],"epi":"原发性 MPGN 占儿童肾病综合征 10%–20%、成人 5%–10%；我国继发性（HBV/HCV）比例较高，近年单克隆免疫球蛋白相关者增多。"},"patho":"免疫复合物或补体替代途径激活产物沉积于系膜与内皮下，C5b-9 损伤内皮与系膜，内皮增生与基质扩张形成双轨；持续补体激活致进行性硬化与 CKD。","dx":{"criteria":["蛋白尿（常 1–4 g/d，部分达肾病范围）、血尿（早期肉眼）、高血压与肾功能减退","补体 C3 持续降低，C4 在免疫复合物型可降低（II 型 C3 低而 C4 正常）","肾活检：系膜增生 + 毛细血管壁增厚 + 双轨征（PASM 染色），电镜内皮下/系膜沉积，C3 ± IgG","按 IF 分型：Ⅰ型 IgG+C3+C4、Ⅱ型纯 C3（C3 肾小球病）、Ⅲ型二者兼有","必须排查继发：HBV/HCV、冷球蛋白、血尿免疫固定电泳与游离轻链、ANA/dsDNA"],"workup":["补体 C3/C4（动态）、尿蛋白定量、eGFR","HBV、HCV、HIV 筛查","冷球蛋白、类风湿因子","血清蛋白电泳 + 免疫固定电泳、血清游离轻链","ANA、抗 dsDNA、抗 C3 肾炎因子（C3 肾小球病）","肾活检（光镜 + IF + 电镜）"],"grading":"按沉积物类型：免疫复合物型（Ⅰ/Ⅲ）与 C3 肾小球病（原Ⅱ型）；补体持续低者预后差。"},"ddx":[{"name":"局灶节段性肾小球硬化","point":"与本类中 FSGS 的鉴别：FSGS 为节段硬化、足突融合、补体正常；MPGN 有内皮下沉积与双轨。"},{"name":"IgA 肾病","point":"IgA 系膜区沉积、补体正常；MPGN 补体持续低、IF 以 C3 ± IgG 为主。"},{"name":"膜性肾病","point":"上皮下颗粒沉积（非内皮下），抗 PLA2R 阳性，无低补体。"},{"name":"狼疮性肾炎 IV 型","point":"MPGN 样病理改变但伴全身狼疮表现与高滴度 dsDNA。"},{"name":"糖尿病肾病","point":"K-W 结节、弥漫基底膜增厚，糖尿病史与视网膜病变；无低补体。"}],"tx":{"drug":[{"name":"泼尼松（原发性免疫复合物型）","dose":"1 mg/kg/d 隔日（最大 80 mg），疗程 ≥6 个月，遵专科方案","note":"原发性 MPGN 疗效有限，成人不推荐长期大剂量；伴肾病综合征者可试用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"吗替麦考酚酯","dose":"0.5–1 g bid 口服，疗程 6–12 个月","note":"作激素节约剂；致畸，育龄女性需避孕；监测血常规","renal":"遵说明书","hepatic":"遵说明书","interact":"与阿昔洛韦、别嘌醇合用增加骨髓抑制"},{"name":"依库珠单抗（C5 抑制剂，C3 肾小球病）","dose":"900 mg 静脉每周 × 4 次，后 1200 mg 每 2 周（遵说明书）","note":"用于补体介导的 C3 肾小球病；需接种脑膜炎球菌疫苗并评估感染风险；国内可及性有限","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"ACEI/ARB（基础治疗）","dose":"依那普利 5–10 mg bid 或氯沙坦 50–100 mg qd；目标 <130/80 mmHg，蛋白尿 >1 g/d 者 <125/75","note":"减少蛋白尿、延缓进展；监测血钾与肌酐","renal":"肌酐上升 >30% 减量","hepatic":"遵说明书","interact":"与保钾利尿剂合用致高钾"},{"name":"抗病毒（HBV/HCV 相关）","dose":"HBV：恩替卡韦 0.5 mg qd 或替诺福韦 300 mg qd；HCV：索磷布韦 + 维帕他韦（按基因型）","note":"继发 MPGN 的核心治疗，病毒清除后蛋白尿可改善；免疫抑制前须先抗病毒","renal":"恩替卡韦 eGFR <30 减量；索磷布韦方案重度肾损慎用","hepatic":"遵说明书","interact":"利福平降低恩替卡韦疗效"}],"nonDrug":["继发性（感染、冷球蛋白、单克隆免疫球蛋白）以治疗原发病为主","难治性 C3 肾小球病可考虑血浆置换或依库珠单抗","终末期：透析或移植（C3G 移植后复发率约 50%）"],"life":["限盐、控制血压 <130/80 mmHg（蛋白尿者 <125/75）","调脂，每 3–6 个月查肾功能与尿蛋白","监测乙肝/丙肝病毒载量与肝功"]},"prog":"病程多慢性进行，5–10 年内约半数进展为 ESRD；C3 肾小球病移植后复发率 50%–70%。继发于感染者治疗后部分可缓解。","refs":["中华医学会肾脏病学分会《原发性肾病综合征诊疗指南》（MPGN 章节）","《内科学》第 9 版 第五篇 膜增生性肾小球肾炎","KDIGO Glomerular Diseases Guideline 2021（MPGN/C3G 章节）"]}]},{"id":"renal_other","name":"肾其他疾病","rank":5,"summary":"多囊肾、尿路感染、肾小管酸中毒与梗阻性肾病：重点区分结构、感染、酸碱与梗阻问题，及时解除梗阻与控制感染。","compare":[{"diseaseId":"renal_pkd","dx":"双肾多发囊肿、肾脏增大、家族史、高血压，可合并肝囊肿与颅内动脉瘤","key":"家族史 + 双肾多发囊肿（<40 岁者需 ≥3 个囊肿），eGFR 快速下降需托伐普坦"},{"diseaseId":"renal_uti","dx":"尿频尿急尿痛（膀胱炎）或发热、腰痛、肋脊角叩痛（肾盂肾炎），尿培养阳性","key":"发热 + 腰痛为上尿路感染，需静脉抗生素并评估梗阻"},{"diseaseId":"renal_rta","dx":"高氯性正常阴离子间隙代谢性酸中毒，伴血钾与尿 pH 异常，分 1/2/4 型","key":"正常阴离子间隙代谢性酸中毒 + 阴离子间隙正常，据血钾与尿 pH 分型"},{"diseaseId":"renal_obstruct","dx":"少尿/无尿、肾功能快速恶化，超声见肾积水，解除梗阻后改善","key":"肾后性 AKI：超声示积水、解除梗阻后肾功能恢复"}],"diseases":[{"id":"renal_pkd","name":"常染色体显性多囊肾病","aka":["ADPKD","多囊肾","Autosomal Dominant Polycystic Kidney Disease"],"rank":1,"basic":{"define":"PKD1 或 PKD2 突变的遗传性囊肿性肾病，双肾囊肿进行性增大，致高血压与慢性肾衰竭，可合并肝囊肿、颅内动脉瘤与憩室病。","risk":["家族史（约 85% 有明确家族史）","PKD1 突变（占 78%–85%，病情更重）","高血压、大量吸烟、高盐饮食、蛋白尿","男性（同等基因型下病情更重）"],"epi":"患病率约 1/400–1/1000，占 ESRD 的 5%–10%。"},"patho":"多囊蛋白异常使初级纤毛 cAMP/mTOR 通路失调 → 小管上皮增生并分泌液体形成囊肿；囊肿扩张使肾体积增大、RAAS 激活致高血压，逐步出现硬化与间质纤维化。","dx":{"criteria":["双肾多发囊肿、肾脏增大；Pei 标准：<30 岁双肾 ≥3 个囊肿，30–39 岁 ≥3 个，40–59 岁每肾 ≥2 个，≥60 岁每肾 ≥4 个","高血压（eGFR 正常时即可出现）、腰胁痛、血尿、泌尿系感染或结石","家族史，必要时 PKD1/PKD2 基因检测（尤其不典型或需家族筛查）","MRI 测肾脏总体积（TKV）年增长 >5%，或 eGFR 每年下降 >5 mL/min/1.73m² 为快速进展","24 h 尿蛋白 >0.5 g/d、血压控制不佳为高危","筛查肝囊肿、颅内动脉瘤（有家族史或症状时 MRA）、结肠憩室与疝"],"workup":["肾脏超声（首选筛查）、腹部 MRI（体积评估）、CT（结石/感染）","eGFR、尿蛋白定量、血压与血脂","肝脏超声、家族成员筛查（20–30 岁起）","MRA（有家族性动脉瘤史或提示性症状）","基因检测（PKD1/PKD2）"],"grading":"Mayo 影像分型（1A–1E、2A–2E）按校正 TKV 预测进展：1C–1E 为快速进展，据此决定托伐普坦。"},"ddx":[{"name":"尿路感染","point":"与本类中尿路感染的鉴别：ADPKD 可合并囊肿感染（发热、腰痛、囊壁增厚），需长疗程脂溶性抗生素；单纯 UTI 无肾脏增大与囊肿。"},{"name":"单纯性肾囊肿","point":"囊肿少而小、肾功能正常、无家族史；ADPKD 双肾多发且肾脏增大。"},{"name":"常染色体隐性多囊肾","point":"婴儿/儿童发病、肝纤维化突出，ARPKHD1 突变，与成人显性型不同。"},{"name":"获得性囊性肾病（CKD 相关）","point":"长期透析后出现囊肿，肾脏多为缩小而非增大。"},{"name":"多囊性肾发育不良 / 肾积水","point":"单侧或多房性改变，超声与影像可区分，无家族遗传模式。"}],"tx":{"drug":[{"name":"托伐普坦（V2 受体拮抗剂）","dose":"起始 45/15 mg（晨 45 mg + 下午 15 mg）分 2 次口服，渐加至 90/30 mg 或 120/30 mg；用于 18–55 岁、eGFR ≥30 的快速进展者（Mayo 1C–1E）","note":"需大量饮水防高钠与脱水；首年每月查肝功，出现乏力、纳差、浓茶尿立即停药查肝功（可致肝衰竭）；既往肝病者禁用","renal":"eGFR <30 不推荐起始，需密切监测钠","hepatic":"Child-Pugh B/C 或肝病者禁用","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素）显著升高浓度需减量；避免强诱导剂"},{"name":"缬沙坦（或 ACEI）","dose":"80–160 mg qd，按血压加量；目标 ≤110/75 mmHg（<50 岁且 eGFR ≥60、可耐受者）或 <130/80 mmHg","note":"严格控压是延缓囊肿增长的核心；监测肌酐与血钾","renal":"肌酐上升 >30% 减量","hepatic":"遵说明书","interact":"与保钾利尿剂、NSAIDs 合用风险增加"},{"name":"普萘洛尔（部分研究，不常规推荐）","dose":"儿童 ADPKD 研究中 1–2 mg/kg/d，需专科评估","note":"成人证据不足，不推荐常规使用","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"枸橼酸钾（合并低枸橼酸尿结石）","dose":"10–20 mEq bid–tid，按尿枸橼酸调整","note":"预防结石；注意高钾与胃肠反应","renal":"eGFR <30 慎用（高钾）","hepatic":"遵说明书","interact":"与保钾利尿剂/ACEI 合用增加高钾"}],"nonDrug":["大量饮水（尿量 >2.5–3 L/d）抑制囊肿增长","囊肿感染：穿刺引流 + 脂溶性抗生素（环丙沙星、甲硝唑），疗程 2–4 周","囊肿出血或巨大囊肿压迫：穿刺硬化或腹腔镜去顶减压","终末期：透析或肾移植（术前排查颅内动脉瘤）"],"life":["严格控压、限盐（<5 g/d）、戒烟、低蛋白饮食（0.8 g/kg/d）","每 6–12 个月查 eGFR、尿蛋白与血压；每 1–2 年 MRI 测体积","家族成员 20–30 岁起超声筛查"]},"prog":"约 50% 在 60 岁前进展为 ESRD（PKD1 更早）；托伐普坦减缓 eGFR 下降与囊肿增长；颅内动脉瘤破裂是重要死因。","refs":["中华医学会肾脏病学分会《常染色体显性多囊肾病诊治指南》2018","《内科学》第 9 版 第五篇 多囊肾病","KDIGO Conference: ADPKD 2019","EMA/HAS 托伐普坦适应证评估"]},{"id":"renal_uti","name":"尿路感染","aka":["急性肾盂肾炎","膀胱炎","UTI","Urinary Tract Infection","Acute Pyelonephritis"],"rank":2,"basic":{"define":"病原微生物在尿路繁殖引起的感染，按部位分膀胱炎/尿道炎与肾盂肾炎，按有无复杂因素分单纯性与复杂性；女性高发。","risk":["女性（尿道短、性活动、绝经后雌激素缺乏）","糖尿病、免疫抑制、结石或梗阻、留置导管","妊娠、前列腺增生（男性）","导尿与泌尿系操作史","ESBL 产酶菌流行"],"epi":"女性一生中约 50%–60% 至少发生一次 UTI，年发病率约 10%；肾盂肾炎占 UTI 的 5%–10%，多见于育龄女性与老年男性。"},"patho":"致病菌（大肠埃希菌占 70%–95%）经尿道逆行上升，P 菌毛黏附尿路上皮致膀胱炎（尿路刺激症状）；上行至肾盂与肾实质致肾盂肾炎（中性粒细胞浸润、微脓肿），合并梗阻时易致脓毒症。","dx":{"criteria":["膀胱炎：尿频、尿急、尿痛、耻骨上不适，无发热或仅有低热；尿常规白细胞增多、亚硝酸盐阳性","急性肾盂肾炎：发热 >38 ℃、寒战、腰痛、肋脊角叩痛、恶心呕吐，可伴膀胱刺激征","尿培养：清洁中段尿 ≥10⁵ CFU/mL（有症状者 ≥10³）；肾盂肾炎血培养 15%–20% 阳性","尿常规：白细胞酯酶与亚硝酸盐阳性，镜下白细胞 >5/HPF，可有白细胞管型","复杂因素：结石、梗阻、糖尿病、导管、妊娠、免疫抑制、男性、医院获得性","脓毒症预警：qSOFA ≥2、乳酸 >2 mmol/L、血压下降"],"workup":["尿常规 + 尿沉渣、尿培养 + 药敏","血常规、CRP、降钙素原、血培养（发热者）","肌酐、电解质、血糖","泌尿系超声（结石、积水、脓肿）；男性加前列腺检查","妊娠试验（育龄女性）"],"grading":"单纯性/复杂性；下尿路/上尿路；合并脓毒症、气肿性肾盂肾炎或肾周脓肿为重症。"},"ddx":[{"name":"常染色体显性多囊肾病","point":"与本类中多囊肾的鉴别：ADPKD 以腰腹痛、血尿、囊肿感染为主，家族史 + 双肾多发囊肿；UTI 以尿路刺激症状与尿培养阳性为主。"},{"name":"梗阻性肾病","point":"结石或前列腺增生致肾积水并合并感染；超声见积水，解除梗阻后感染缓解。"},{"name":"急性阑尾炎/盆腔炎","point":"右下腹或下腹痛伴发热，尿检可轻度异常，但尿培养阴性、影像见阑尾或附件异常。"},{"name":"间质性膀胱炎","point":"慢性尿频尿急但尿培养反复阴性，症状与膀胱充盈相关。"}],"tx":{"drug":[{"name":"呋喃妥因（单纯性膀胱炎）","dose":"100 mg bid 口服 × 5 天","note":"仅用于下尿路；eGFR <30 禁用；长期预防 50–100 mg 睡前","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用","interact":"与碳酸氢钠合用降低疗效"},{"name":"磷霉素氨丁三醇","dose":"3 g 单剂口服，或 3 g 每 3 天 1 次 × 3 次","note":"单剂依从性好；妊娠期相对安全","renal":"遵说明书","hepatic":"遵说明书","interact":"与甲氧氯普胺合用降低吸收"},{"name":"头孢曲松（急性肾盂肾炎）","dose":"1–2 g 静脉 qd（重症 2 g q12h），改善后转口服；疗程 7 天（女性）或 10–14 天（男性/复杂性）","note":"覆盖常见革兰阴性菌；ESBL 或近期抗生素暴露者按药敏（如美罗培南 1 g q8h）","renal":"eGFR <10 减量并监测","hepatic":"遵说明书","interact":"与华法林合用需监测"},{"name":"左氧氟沙星（门诊肾盂肾炎）","dose":"500 mg qd 口服 × 7 天（或 750 mg qd × 5 天），据肾功能调整","note":"非妊娠、无 QT 延长风险者；警惕肌腱病与中枢反应","renal":"eGFR <30 减量或延长间隔","hepatic":"遵说明书","interact":"与抗酸剂、钙剂间隔 2 h；增强华法林"},{"name":"厄他培南（ESBL 或重症）","dose":"1 g qd 静脉（或美罗培南 1 g q8h），据药敏调整","note":"用于 ESBL 产酶菌、重症脓毒症；不覆盖铜绿假单胞菌与肠球菌","renal":"eGFR <30 减量或延长间隔","hepatic":"遵说明书","interact":"丙戊酸钠降低其浓度"},{"name":"头孢呋辛酯（妊娠期/轻症）","dose":"250–500 mg bid × 7 天","note":"妊娠期可选；妊娠末期避免呋喃妥因","renal":"eGFR <30 减量","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["高热、呕吐或多器官受累者住院；梗阻合并感染须急诊解除（双 J 管或肾造瘘）","反复 UTI：评估结构异常、规范导尿管理、绝经后局部雌激素","肾周脓肿：经皮引流 + 长疗程抗生素"],"life":["每日饮水 1.5–2 L、不憋尿、性交后排尿","膀胱炎 2–3 天不缓解或发热即复诊","足疗程用药，避免自行停药"]},"prog":"单纯性膀胱炎 5 天疗程治愈率 >90%；肾盂肾炎多 2–3 天退热。合并梗阻或 ESBL 感染时脓毒症死亡率高。约 25%–30% 女性 6 个月内复发。","refs":["中华医学会泌尿外科学分会《中国泌尿外科和男科疾病诊断治疗指南（2019 版）》尿路感染章节","中华医学会儿科学分会肾脏学组《儿童泌尿系感染诊治循证指南》2016","IDSA/ESCMID Asymptomatic Bacteriuria Guideline 2019","EAU Guidelines on Urological Infections 2023"]},{"id":"renal_rta","name":"肾小管酸中毒","aka":["RTA","Renal Tubular Acidosis","远端肾小管酸中毒","近端肾小管酸中毒"],"rank":3,"basic":{"define":"肾小管酸化与排酸功能缺陷所致高氯性正常阴离子间隙代谢性酸中毒，分为 1 型（远端）、2 型（近端）、4 型（高钾性）与 3 型（混合）。","risk":["自身免疫病（干燥综合征、SLE、桥本）","两性霉素 B、锂剂、托吡酯、氨基糖苷类（1 型）","重金属（铅、镉）与甲苯暴露","Fanconi 综合征（多发性骨髓瘤、药物、遗传）","糖尿病肾病、前列腺梗阻、低醛固酮血症（4 型）"],"epi":"1 型多见于成人，常继发于干燥综合征/狼疮；2 型多见于儿童（胱氨酸病、范可尼综合征）；4 型见于 CKD 与醛固酮不足。"},"patho":"1 型：α 插入细胞 H⁺-ATP 酶缺陷，尿 pH 持续 >5.5，枸橼酸排泄减少、钙磷流失致肾结石。2 型：近端小管 HCO₃⁻ 重吸收阈值降低，大量 HCO₃⁻ 漏出（耗竭后尿可酸化 <5.5）。4 型：醛固酮不足或抵抗，钠重吸收减少、钾与氢排泌受阻。","dx":{"criteria":["高氯性（血氯 >110 mmol/L）正常阴离子间隙（AG = Na − Cl − HCO₃ <12）代谢性酸中毒，HCO₃⁻ 多在 12–18 mmol/L","1 型：低血钾、尿 pH >5.5（酸负荷后仍不能酸化），尿钙高、易结石","2 型：低钾为主，尿 pH <5.5，补碱后尿 pH 升高（HCO₃⁻ 大量排出），可伴 Fanconi 综合征","4 型：高钾 + 酸中毒，eGFR 轻中度下降，醛固酮低或抵抗","需与腹泻鉴别（同为高氯性酸中毒但尿 pH <5.5）","儿童多表现为生长迟缓、佝偻病/骨软化；成人可表现为骨质疏松与骨痛"],"workup":["动脉/静脉血气 + 电解质（AG、血钾、血氯）","尿 pH、尿阴离子间隙、尿钾与尿枸橼酸","血醛固酮、肾素（4 型）","血肌酐、血糖、血钙磷、AKP、25-OH-D","超声或 X 线（肾结石/肾钙化）、骨密度","原发病筛查：ANA、抗 SSA/SSB（干燥综合征）、免疫球蛋白"],"grading":"1 型（远端）/2 型（近端）/4 型（高钾）；轻度（HCO₃⁻ 18–22）、中重度（<15）。"},"ddx":[{"name":"梗阻性肾病","point":"与本类中梗阻性肾病的鉴别：梗阻可致 AKI 与高钾性酸中毒，但超声见肾积水；RTA 无梗阻。"},{"name":"慢性肾脏病","point":"CKD 在 eGFR 明显下降时也可出现酸中毒；RTA 患者 eGFR 可接近正常。"},{"name":"腹泻性酸中毒","point":"高氯性、血钾低，但尿 pH <5.5 且无肾钙化，病史有腹泻。"},{"name":"糖尿病酮症/乳酸性酸中毒","point":"阴离子间隙升高的酸中毒（AG >12），查血糖与乳酸。"},{"name":"原发性醛固酮增多症","point":"典型为低钾与碱中毒、高血压，与 4 型 RTA（高钾酸中毒）相反。"}],"tx":{"drug":[{"name":"枸橼酸钾（1 型碱剂首选）","dose":"1–3 mEq/kg/d 分 3–4 次（成人常 20–40 mEq/d），按血 HCO₃⁻ 与尿 pH 调整","note":"枸橼酸同时降低尿钙、减少结石；目标 HCO₃⁻ 22–24 mmol/L（儿童 20–22）","renal":"eGFR <30 高钾风险，慎用并监测","hepatic":"遵说明书","interact":"与保钾利尿剂、ACEI/ARB 合用致高钾"},{"name":"碳酸氢钠（2 型/急症纠酸）","dose":"1–3 mEq/kg/d 分 3–4 次；2 型常需 5–10 mEq/kg/d 并联用噻嗪类；急症 5% 碳酸氢钠 100–250 mL 静脉","note":"2 型补碱量大易致容量负荷与低钾，需同时补钾","renal":"遵说明书","hepatic":"遵说明书","interact":"与含铝/镁抗酸剂合用可致铝中毒"},{"name":"氢氯噻嗪（2 型，减少尿钙）","dose":"12.5–25 mg qd–bid 口服","note":"轻度容量收缩增加近端 HCO₃⁻ 重吸收；监测血钾、尿酸","renal":"eGFR <30 疗效差","hepatic":"遵说明书","interact":"与锂剂合用增加锂中毒"},{"name":"氟氢可的松（4 型伴醛固酮低下）","dose":"0.05–0.2 mg/d 口服，按血钾与血压调整","note":"用于醛固酮低下所致 4 型；监测血压与水肿","renal":"遵说明书","hepatic":"遵说明书","interact":"与排钾利尿剂合用致低钾"},{"name":"降钾措施（4 型）","dose":"聚苯乙烯磺酸钙 15 g tid 或环硅酸锆钠 10 g tid；必要时胰岛素+葡萄糖、碳酸氢钠","note":"低钾饮食（<3 g/d）；纠酸可同时降钾；停用保钾药物","renal":"环硅酸锆钠 eGFR 低时减量","hepatic":"遵说明书","interact":"与 ACEI/ARB、螺内酯叠加高钾"}],"nonDrug":["治疗原发病：停用致病药物（锂、两性霉素 B、托吡酯），治疗自身免疫病","1 型结石：大量饮水（尿量 >2 L/d），必要时碎石或手术","4 型：解除梗阻、控制糖尿病/前列腺病"],"life":["开始每月、稳定后每 3–6 个月查血气、电解质与尿 pH","儿童监测生长与骨病；成人每 1–2 年测骨密度","避免高钙饮食与维生素 D 过量"]},"prog":"1 型不纠碱易致结石、肾钙化与 CKD 进展；2 型儿童多可逆，成人合并 Fanconi 者取决于原发病；4 型进展较慢但心血管风险高。","refs":["《内科学》第 9 版 第五篇 肾小管性酸中毒","中华医学会肾脏病学分会《肾小管酸中毒诊治专家共识》2019","Palmer BF, et al. Renal Tubular Acidosis. Am J Med 2018","KDIGO 2024 CKD 指南（代谢性酸中毒章节）"]},{"id":"renal_obstruct","name":"梗阻性肾病与肾后性 AKI","aka":["梗阻性肾病","肾后性急性肾损伤","Post-renal AKI","Obstructive Nephropathy"],"rank":4,"basic":{"define":"尿路引流受阻所致的肾脏结构与功能损害，分急性（肾后性 AKI）与慢性（梗阻性肾病）；按部位分上尿路（输尿管以上）与下尿路（膀胱、尿道）。","risk":["老年男性前列腺增生、前列腺癌","泌尿系结石（输尿管结石最常见）","妊娠子宫压迫、妇科肿瘤压迫或侵犯","神经源性膀胱、导尿管堵塞","腹腔/盆腔手术后、腹膜后纤维化","血块、真菌球、抗胆碱能药物"],"epi":"占 AKI 的 5%–10%；老年男性以前列腺增生相关梗阻常见；仅双侧梗阻或孤立肾单侧梗阻才致显著肾功能减退。"},"patho":"梗阻初期肾盂压升高，肾血流与 GFR 下降、小管重吸收钠水增加；持续梗阻致小管扩张萎缩与间质纤维化，RAAS 与 TGF-β 加重损伤；解除后出现梗阻后利尿。","dx":{"criteria":["少尿、无尿或排尿困难 + 肌酐快速上升（24 h 内 >0.3 mg/dL 或较基线升高 50%）","结石：突发腰腹绞痛向会阴放射、血尿；仅双侧或孤立肾梗阻才致 AKI","下尿路梗阻：排尿淋漓、尿线细、尿潴留、膀胱充盈（触诊/超声）","超声：肾盂肾盏积水（肾结石可见强回声与声影）；CT（平扫）为结石金标准","解除梗阻后肾功能快速改善（多在 24–72 h 明显改善）","慢性梗阻：肾功能渐进下降、肾皮质变薄"],"workup":["血肌酐、eGFR、电解质、酸碱","尿常规、尿培养（合并感染）","泌尿系超声（首选筛查）、平扫 CT（结石/肿瘤/压迫）","膀胱残余尿量测定、尿流动力学","必要时逆行造影/MRU、肿瘤标志物（PSA）"],"grading":"急性/慢性；单侧/双侧；是否合并感染（梗阻合并感染属泌尿外科急症）与无尿、高钾等急危指征。"},"ddx":[{"name":"肾小管酸中毒","point":"与本类中肾小管酸中毒的鉴别：RTA 为高氯性酸中毒，超声无积水；梗阻性 AKI 超声见积水且解除后肌酐下降。"},{"name":"急性肾小管坏死","point":"有缺血/肾毒性因素，尿钠高、尿沉渣见棕色颗粒管型，超声无积水。"},{"name":"尿路感染","point":"可合并梗阻；单纯 UTI 超声无积水，梗阻合并感染须紧急引流。"},{"name":"慢性肾脏病","point":"双侧对称性萎缩与 CKD 缓慢进展，超声肾皮质变薄但无积水或仅轻度。"},{"name":"腹膜后纤维化/肿瘤","point":"双侧输尿管狭窄伴肾积水，CT 见腹膜后软组织包绕，需病理确诊。"}],"tx":{"drug":[{"name":"坦索罗辛（排石辅助）","dose":"0.4 mg qd，排石期 4–6 周","note":"用于 ≤10 mm 输尿管结石排石与镇痛；首剂体位性低血压","renal":"遵说明书","hepatic":"遵说明书","interact":"与 PDE5 抑制剂、降压药合用加重低血压"},{"name":"高钾血症急诊处理","dose":"血钾 >6.0 mmol/L 或心电图改变：10% 葡萄糖酸钙 10 mL 静推；胰岛素 10 U + 50% 葡萄糖 25 g；沙丁胺醇雾化；降钾树脂 15 g tid","note":"高钾是梗阻性 AKI 首要死因；顽固者立即透析","renal":"肾功能不全加大剂量并监测","hepatic":"遵说明书","interact":"遵说明书"},{"name":"头孢曲松（梗阻合并感染）","dose":"1–2 g 静滴 qd，解除梗阻后按培养调整；医院获得性者用哌拉西林他唑巴坦 4.5 g q6–8h","note":"先引流（支架或肾造瘘）再抗感染；反复插管操作可加重脓毒症","renal":"哌拉西林他唑巴坦 eGFR <40 减量","hepatic":"遵说明书","interact":"头孢曲松与含钙输液禁忌"},{"name":"非那雄胺（前列腺增生慢性梗阻）","dose":"5 mg qd（前列腺体积 >30 mL），可与坦索罗辛 0.4 mg qd 联合","note":"起效需 6 个月；PSA 判读需 ×2；联合治疗降低急性尿潴留风险","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"遵说明书"}],"nonDrug":["急性梗阻首选双 J 管或经皮肾造瘘（感染性梗阻、肾积水伴肾衰必做）","输尿管结石 <6 mm 多自行排出；6–10 mm 体外碎石；>10 mm 或嵌顿行输尿管镜/经皮肾镜","前列腺增生反复尿潴留或肾功受损者行 TURP；尿道狭窄行扩张或成形","神经源性膀胱行清洁间歇导尿"],"life":["解除后监测梗阻后利尿：尿量 >4 L/d 时补液并查电解质","结石患者多饮水（尿量 >2.5 L/d）、限草酸与钠","前列腺增生者慎用抗胆碱能药"]},"prog":"及时解除者肌酐多在 24–72 h 内下降；梗阻持续数周以上肾功能恢复不完全，>4–6 周可遗留不可逆损害。感染性梗阻未引流时脓毒症死亡率高。","refs":["中华医学会泌尿外科学分会《中国泌尿外科和男科疾病诊断治疗指南（2019 版）》尿石症/前列腺增生章节","《内科学》第 9 版 第五篇 梗阻性肾病","KDIGO AKI Clinical Practice Guideline 2012","EAU Guidelines on Urolithiasis 2023"]}]},{"id":"gn_secondary","name":"继发性肾小球疾病","rank":6,"summary":"继发性肾小球病的诊断靠「肾外表现 + 免疫学 + 肾活检」三件套：狼疮性肾炎看 ANA/抗 dsDNA 与 ISN/RPS 分型，紫癜性肾炎看皮肤紫癜史，系膜增生性肾炎多为病理描述而非独立疾病。","compare":[{"diseaseId":"gn_lupus","dx":"SLE 患者出现蛋白尿和/或血尿、肾功能下降，ANA 与抗 dsDNA 阳性、补体降低，肾活检按 ISN/RPS 分型（Ⅲ/Ⅳ 型为增殖性）","key":"多系统受累 + 自身抗体阳性 + 补体低；Ⅲ/Ⅳ 型需积极免疫抑制"},{"diseaseId":"gn_hspn","dx":"过敏性紫癜病程中出现血尿/蛋白尿，肾活检见系膜区 IgA 沉积（与 IgA 肾病病理相同）","key":"有可触及紫癜、腹痛或关节痛史；按 ISKDC 分级评估新月体比例"},{"diseaseId":"gn_mesangial","dx":"肾活检见系膜细胞与基质增生，免疫荧光见系膜区 IgA/IgG/IgM 或 C3 沉积","key":"是病理形态诊断；需排除 IgA 肾病、狼疮性肾炎与感染后肾炎后才成立"}],"diseases":[{"id":"gn_lupus","name":"狼疮性肾炎","aka":["Lupus Nephritis","LN","狼疮肾炎"],"rank":1,"basic":{"define":"系统性红斑狼疮（SLE）累及肾脏所致的免疫复合物介导性肾小球肾炎，是 SLE 最常见且影响预后的重要脏器损害，约 50%–60% 的 SLE 患者在病程中出现肾脏受累。","risk":["**女性（尤其育龄女性，SLE 发病率女:男约 9:1）**","非洲裔、亚裔与西班牙裔人群发病率与严重度更高","ANA 与抗 dsDNA 阳性、补体 C3/C4 降低","抗 Sm、抗核小体抗体阳性","年轻发病、病程长、未规范治疗"],"epi":"SLE 在我国患病率约 30–70/10 万，其中约 50%–60% 出现狼疮性肾炎。亚洲人群的增殖性（Ⅲ/Ⅳ 型）比例较高。狼疮性肾炎是 SLE 患者死亡与终末期肾病的主要原因之一。"},"patho":"免疫复合物（DNA-抗 DNA 抗体）在肾小球沉积，激活补体（经典途径）并招募中性粒细胞与单核细胞，造成内皮与系膜损伤。按病理分为六型：Ⅰ 型（轻微系膜病变）、Ⅱ 型（系膜增生）、Ⅲ 型（局灶增殖，<50% 肾小球受累）、Ⅳ 型（弥漫增殖，≥50%）、Ⅴ 型（膜性）、Ⅵ 型（硬化性）。Ⅲ/Ⅳ 型为活动性增殖性病变，可迅速致肾功能恶化；Ⅴ 型表现为肾病综合征但进展较慢。**「活动性病变」（毛细血管内增生、新月体、核碎裂）与「慢性化病变」（硬化、纤维性新月体、间质纤维化）的比例决定治疗强度与预后**。","dx":{"criteria":["SLE 患者出现下列任一：**蛋白尿 ≥0.5 g/d（或尿蛋白/肌酐比值 ≥0.5）**、**活动性尿沉渣**（血尿、脓尿、红细胞管型）、肾功能不明原因下降","ANA 阳性（几乎所有患者）与抗 dsDNA 阳性（特异性较高，与疾病活动相关）、补体 C3/C4 降低","**肾活检是诊断与分型的金标准**（有肾脏受累表现者应行活检，除非有禁忌）","**ISN/RPS 分型**（2003 年，2018 年修订）：Ⅰ 轻微系膜；Ⅱ 系膜增生；Ⅲ 局灶增殖（A/C 活动/慢性）；Ⅳ 弥漫增殖（A/C）；Ⅴ 膜性；Ⅵ 晚期硬化（>90% 肾小球球性硬化）","需评估活动性指数（AI）与慢性化指数（CI）","排除其他原因（感染后肾炎、ANCA 相关血管炎、药物性）"],"workup":["尿常规 + 尿沉渣镜检（红细胞管型）、24 小时尿蛋白定量或尿蛋白/肌酐比值","血肌酐、eGFR、白蛋白、血脂","**免疫学：ANA、抗 dsDNA、抗 Sm、补体 C3/C4**（动态监测疾病活动）","**肾活检（光镜 + 免疫荧光 + 电镜）** —— 分型与治疗决策的核心","抗磷脂抗体（APS 并存时影响治疗）","评估其他脏器受累（皮肤、关节、血液、神经系统）","感染筛查（乙肝、结核、CMV，免疫抑制前）"],"grading":"**ISN/RPS 分型（Ⅰ–Ⅵ 型）** 是核心；按活动性（A）、活动 + 慢性（A/C）、慢性（C）标注；按临床分：无症状性血尿/蛋白尿、肾病综合征、急性肾炎综合征、急进性肾炎、慢性肾衰竭。"},"ddx":[{"name":"紫癜性肾炎（gn_hspn）","point":"与紫癜性肾炎的鉴别：后者有可触及紫癜、腹痛与关节痛，ANA 与抗 dsDNA 阴性，免疫荧光以 IgA 沉积为主；狼疮性肾炎为「满堂亮」（IgG/IgA/IgM/C3/C1q 均沉积）且 ANA 阳性。"},{"name":"系膜增生性肾小球肾炎（gn_mesangial）","point":"与系膜增生性肾炎的鉴别：后者无 SLE 的系统表现与自身抗体；狼疮性肾炎需满足 SLE 分类标准。"},{"name":"IgA 肾病（gn_iga）","point":"以发作性肉眼血尿（上感后）为特点，免疫荧光仅 IgA 与 C3 沉积；狼疮性肾炎为多克隆免疫球蛋白沉积伴 C1q。"},{"name":"膜性肾病（gn_mn）","point":"狼疮性 Ⅴ 型与原发性膜性肾病病理相似，但前者有 SLE 表现与自身抗体；需查抗 PLA2R 抗体（原发性多为阳性）。"},{"name":"ANCA 相关血管炎肾损害","point":"ANCA 阳性、寡免疫复合物沉积（免疫荧光阴性或弱），常伴肺受累；狼疮性肾炎免疫复合物丰富。"},{"name":"感染后肾小球肾炎","point":"有链球菌感染史、C3 降低而 C4 正常（狼疮两者均低）、免疫荧光见「驼峰样」沉积；多在数周内恢复。"}],"tx":{"drug":[{"name":"糖皮质激素（泼尼松/甲泼尼龙）","dose":"**诱导期**：甲泼尼龙 500–1000 mg 静脉冲击 ×3 天（重症 Ⅲ/Ⅳ 型），随后泼尼松 0.5–1 mg/kg/d（最大 60 mg/d）口服；**维持期**逐渐减至 ≤7.5 mg/d","note":"**激素是所有增殖性狼疮性肾炎的基础**；需预防骨质疏松、PCP（复方磺胺甲噁唑）、胃黏膜保护；长期使用注意感染与血糖","renal":"无需调整","hepatic":"肝病者监测","interact":"与 NSAIDs 合用增加消化道溃疡；与利福平合用降低浓度"},{"name":"吗替麦考酚酯（MMF，诱导与维持）","dose":"诱导：1–1.5 g bid 口服（或 2 g/d）；维持：0.5–1 g bid","note":"**Ⅲ/Ⅳ 型的一线诱导用药**（与激素联用，疗效不劣于环磷酰胺且生殖毒性较低）；**妊娠禁用（致畸）**；需监测血象与感染（尤其 CMV）","renal":"CrCl <25 慎用（减量）","hepatic":"重度肝病慎用","interact":"与硫唑嘌呤禁联（骨髓抑制）；与抗酸药/铁剂合用降低吸收；与阿昔洛韦合用升高浓度"},{"name":"环磷酰胺（CTX，重症或 MMF 不耐受）","dose":"**低剂量方案**：500 mg 静脉每 2 周 ×6 次（Euro-Lupus 方案）；或高剂量：0.5–1 g/m² 静脉每月 1 次 ×6 次；口服 1–2 mg/kg/d","note":"用于弥漫增殖性（Ⅳ 型）、新月体或肾功能快速恶化者；**生殖毒性（卵巢早衰、不育）**，育龄女性需评估并考虑卵巢保护；需充分水化防出血性膀胱炎","renal":"CrCl <30 减量（活性代谢物蓄积）","hepatic":"肝病者减量","interact":"与别嘌醇合用增加骨髓抑制；与磺胺药合用增加膀胱毒性"},{"name":"贝利尤单抗（BLyS 抑制剂）","dose":"10 mg/kg 静脉第 0、14、28 天，之后每 4 周（或 200 mg 皮下每周）","note":"用于活动性 SLE 与狼疮性肾炎（尤其联合 MMF）；可减少激素用量；需监测感染","renal":"无需调整","hepatic":"重度肝病慎用","interact":"与免疫抑制剂合用增加感染风险；活疫苗禁用"},{"name":"伏环孢素（钙调磷酸酶抑制剂，Ⅴ 型或联合）","dose":"23.7 mg bid 口服（或按方案），需监测血药浓度","note":"用于膜性（Ⅴ 型）狼疮性肾炎或联合诱导；需监测肾功能与血压","renal":"eGFR <30 慎用","hepatic":"肝病者减量","interact":"CYP3A4 底物，与唑类抗真菌药、地尔硫卓合用升高浓度（肾毒性）"},{"name":"羟氯喹（基础治疗）","dose":"200–400 mg/d 口服（按体重 ≤5 mg/kg/d）","note":"**所有 SLE 患者均应使用**（降低复发、血栓与器官损害，改善生存）；需每年眼科筛查（视网膜毒性）","renal":"CrCl <30 减量","hepatic":"肝病者慎用","interact":"与 QT 延长药物合用需监测；与抗酸药合用降低吸收"},{"name":"复方磺胺甲噁唑（PCP 预防）","dose":"SMZ-TMP 480 mg qd 或 960 mg 每周 3 次","note":"大剂量激素 + 免疫抑制剂期间需预防卡氏肺孢子虫肺炎","renal":"CrCl <30 减量","hepatic":"肝病者慎用","interact":"与华法林合用增强抗凝；与甲氨蝶呤合用增加骨髓毒性"}],"nonDrug":["**肾活检是治疗决策的前提**（Ⅲ/Ⅳ 型需积极免疫抑制；Ⅴ 型单纯可保守）","**控制血压（目标 <130/80 mmHg，蛋白尿者用 ACEI/ARB）与蛋白尿**","避免肾毒性药物（NSAIDs、氨基糖苷类、造影剂）","**妊娠管理**：活动期避孕；计划妊娠需病情稳定 ≥6 个月（停用 MMF/CTX，改为硫唑嘌呤或钙调磷酸酶抑制剂）","终末期肾病者行透析或肾移植（移植前需病情稳定）","疫苗接种（灭活疫苗；免疫抑制期禁用活疫苗）"],"life":["**严格防晒**（紫外线可诱发狼疮活动）","避孕与生育计划（MMF、CTX、甲氨蝶呤致畸）","定期随访：尿蛋白、肌酐、补体、抗 dsDNA（每 1–3 个月）","感染预防（免疫抑制期避免人群密集场所，发热立即就医）","**羟氯喹眼科筛查**（每年一次，尤其用药 >5 年）","骨健康管理（激素长期使用需补钙与维生素 D、骨密度监测）"]},"prog":"Ⅲ/Ⅳ 型狼疮性肾炎经规范诱导 + 维持治疗，完全或部分缓解率约 60%–80%，5 年肾脏生存率 >80%。**未治疗或治疗不充分者约 10%–30% 在 10 年内进展至终末期肾病**。复发率约 30%–40%（需长期维持治疗）。Ⅴ 型进展较慢但蛋白尿持续者预后亦不佳。种族（非洲裔、西班牙裔）与延迟治疗是不良预后因素。","refs":["《中国狼疮肾炎诊断和诊疗指南（2021 年版）》（中华医学会肾脏病学分会）","2024 KDIGO Clinical Practice Guideline for the Management of Lupus Nephritis","2019 EULAR/ERA-EDTA Recommendations for the Management of Lupus Nephritis","2003 ISN/RPS Classification of Lupus Nephritis (revised 2018)","《2020 中国系统性红斑狼疮诊疗指南》"]},{"id":"gn_hspn","name":"紫癜性肾炎","aka":["Henoch-Schönlein Purpura Nephritis","HSPN","IgA 血管炎肾损害"],"rank":2,"basic":{"define":"过敏性紫癜（IgA 血管炎）病程中出现的肾小球受累，是儿童与青少年继发性肾小球疾病中最常见的类型，也是决定 HSP 远期预后的关键。","risk":["**儿童与青少年（3–15 岁高峰）**","过敏性紫癜病程中出现血尿与蛋白尿（约 30%–50%）","起病年龄较大（>10 岁）者肾脏受累更重","反复发作的紫癜","腹痛明显者（消化道受累提示更重的全身炎症）"],"epi":"过敏性紫癜是儿童最常见的系统性血管炎（发病率约 10–20/10 万儿童/年）。约 30%–50% 出现肾脏受累，其中约 1%–3% 进展为终末期肾病。成人 HSP 的肾脏受累率更高（可达 50%–85%）且更重。"},"patho":"与 IgA 肾病相同，为含 IgA1 的免疫复合物（半乳糖缺乏的 Gd-IgA1）在肾小球系膜区沉积，激活补体旁路途径，引起系膜细胞增生与基质扩张；重症可见毛细血管内增生、新月体形成（可致急进性肾衰竭）。肾脏病变的严重度按 ISKDC 分级与新月体比例评估，是治疗强度的依据。","dx":{"criteria":["**过敏性紫癜（IgA 血管炎）确诊**：可触及的紫癜（下肢与臀部为主、压之不褪色）+ 至少 1 项（弥漫性腹痛、关节痛/关节炎、肾脏受累、活检见 IgA 沉积）","**肾脏受累表现**：镜下或肉眼血尿、蛋白尿（可至肾病范围）、高血压、肾功能下降","尿检筛查：**所有 HSP 患儿在起病 6 个月内需反复查尿常规**（每 1–2 周），因肾脏受累可延迟出现","**肾活检指征**：肾病范围蛋白尿、肾功能下降、持续性高血压、或病程 >4 周仍有明显蛋白尿","**ISKDC 分级**（肾活检）：Ⅰ 轻微；Ⅱ 单纯系膜增生；Ⅲ 局灶/弥漫增生或新月体 <50%；Ⅳ 新月体 50%–75%；Ⅴ 新月体 >75%；Ⅵ 膜性肾病样改变","免疫荧光：系膜区 **IgA 沉积为主**（伴 C3），与 IgA 肾病相同；需排除狼疮性肾炎（ANA 阴性）"],"workup":["尿常规 + 尿沉渣（血尿、红细胞管型）、24 小时尿蛋白或尿蛋白/肌酐比值","血肌酐、eGFR、白蛋白、血压","血常规（血小板正常是关键）、凝血功能","ANA、抗 dsDNA、补体 C3/C4（排除狼疮）","ASO（链球菌感染证据）、乙肝与丙肝筛查","腹部超声（肠套叠、肠壁增厚）","**肾活检（重症或诊断不明时）**","皮肤活检（疑诊不典型，见 IgA 沉积可确诊）"],"grading":"**ISKDC 病理分级（Ⅰ–Ⅵ）**；临床按表现分：孤立性血尿（最轻）、血尿 + 蛋白尿（非肾病范围）、肾病综合征、急进性肾炎（最重）。按新月体比例（<50%、50%–75%、>75%）评估。"},"ddx":[{"name":"狼疮性肾炎（gn_lupus）","point":"与狼疮性肾炎的鉴别：后者有 SLE 的多系统表现（皮疹、关节炎、血液学异常）、ANA 与抗 dsDNA 阳性、补体降低，免疫荧光「满堂亮」；紫癜性肾炎为 IgA 为主沉积、ANA 阴性。"},{"name":"系膜增生性肾小球肾炎（gn_mesangial）","point":"与系膜增生性肾炎的鉴别：后者为病理形态描述，无紫癜与消化道症状；紫癜性肾炎有明确的 HSP 病史。"},{"name":"IgA 肾病（gn_iga）","point":"**两者病理相同**；区别在于临床表现——IgA 肾病为单纯的肾小球疾病（发作性肉眼血尿），紫癜性肾炎有可触及紫癜与多系统受累。"},{"name":"免疫性血小板减少症（itp）","point":"ITP 的紫癜为针尖样出血点、**血小板显著减少**；紫癜性肾炎的血小板正常且皮疹可触及。"},{"name":"急性链球菌感染后肾小球肾炎（gn_agn）","point":"有链球菌前驱感染、C3 降低（6–8 周恢复）、免疫荧光见驼峰沉积；无 IgA 为主的紫癜皮疹。"},{"name":"ANCA 相关血管炎","point":"ANCA 阳性、寡免疫沉积、常累及肺；紫癜性肾炎免疫荧光 IgA 阳性。"}],"tx":{"drug":[{"name":"ACEI / ARB（蛋白尿控制）","dose":"依那普利 0.1–0.5 mg/kg/d（儿童）或 5–20 mg/d（成人）；缬沙坦 1–2 mg/kg/d","note":"**持续性蛋白尿（>4 mg/m²/h 或尿蛋白/肌酐 >0.2）者应使用**以保护肾功能；需监测血钾与肌酐","renal":"Cr 升高 >30% 时评估减量；双侧肾动脉狭窄禁用","hepatic":"重度肝病慎用","interact":"与保钾利尿剂合用致高钾；与 NSAIDs 合用降低疗效并增加肾损伤"},{"name":"糖皮质激素（泼尼松）","dose":"肾病范围蛋白尿或 ISKDC Ⅲ 级以上：泼尼松 1–2 mg/kg/d（最大 60 mg/d），疗程 4–8 周后逐渐减量，总疗程 6–12 个月","note":"**重症紫癜性肾炎的核心治疗**；轻症（孤立性血尿）不需激素。需监测血压、血糖与感染","renal":"无需调整","hepatic":"肝功能监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"甲泼尼龙冲击（急进性肾炎）","dose":"15–30 mg/kg/d（最大 1 g/d）静脉 ×3 天，随后改口服","note":"用于快速进展的肾功能恶化或广泛新月体（>50%）；需监测血压与感染","renal":"无需调整","hepatic":"监测","interact":"同泼尼松"},{"name":"环磷酰胺（重症/激素依赖）","dose":"静脉 500–750 mg/m² 每月 1 次（共 6 次）或口服 2 mg/kg/d；联合激素","note":"用于激素抵抗、反复复发或病理见广泛新月体者；**生殖毒性**，青春期前后需权衡","renal":"CrCl <30 减量","hepatic":"肝病者慎用","interact":"与别嘌醇合用增加骨髓抑制"},{"name":"吗替麦考酚酯（激素依赖/复发）","dose":"儿童 600–1200 mg/m²/d 分 2 次；成人 1–1.5 g/d 分 2 次","note":"作为激素节约剂用于反复复发者；**妊娠禁用**","renal":"CrCl <25 慎用","hepatic":"重度肝病慎用","interact":"与硫唑嘌呤禁联；与抗酸药合用降低吸收"},{"name":"抗凝与抗血小板（争议）","dose":"双嘧达莫 3–5 mg/kg/d 或低分子肝素（部分方案）","note":"部分中国方案用于重度紫癜性肾炎（改善微循环），但国际证据有限；需评估出血风险","renal":"低分子肝素按 CrCl 调整","hepatic":"肝病者慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**所有 HSP 患儿需在 6 个月内反复查尿常规**（早期发现肾脏受累）","卧床休息（急性期），避免剧烈运动","**外科评估**：剧烈腹痛需警惕肠套叠（超声监测），必要时禁食与外科会诊","轻症（仅镜下血尿）：无需免疫抑制，长期随访","**终末期肾病**：透析或肾移植（移植后紫癜性肾炎可复发，约 10%–30%）","扁桃体切除（反复扁桃体炎诱发者，证据有限）"],"life":["**长期随访（至少 2–5 年）**：尿常规、血压、肾功能（部分肾炎在数年后才出现）","避免已知诱发因素（部分与食物或药物过敏相关）","急性期皮疹与关节痛可对症处理","复发时（紫癜再现）需重新评估尿检","育龄女性妊娠前需评估肾功能与疾病活动"]},"prog":"约 50%–70% 的紫癜性肾炎在数月内缓解；约 30% 反复发作；**约 1%–3%（成人可达 10%–20%）进展为终末期肾病**。预后不良因素：起病年龄大、肾病范围蛋白尿、高血压、病理见广泛新月体（>50%）、持续性肾功能下降。规范激素 ± 免疫抑制可显著改善重症预后；轻症预后良好。","refs":["《儿童紫癜性肾炎诊治循证指南》（中华医学会儿科学分会肾脏学组，2016）","2010 EULAR/PRINTO/PRES Classification Criteria for Henoch-Schönlein Purpura","2019 SHARE Recommendations for Diagnosis and Management of IgA Vasculitis in Childhood","2012 Kidney Disease: Improving Global Outcomes (KDIGO) Glomerulonephritis Work Group Report（IgA 肾病与 HSPN 章节）"]},{"id":"gn_mesangial","name":"系膜增生性肾小球肾炎","aka":["Mesangial Proliferative Glomerulonephritis","MsPGN","系膜增生性肾炎"],"rank":3,"basic":{"define":"以肾小球系膜细胞增生与系膜基质增多为病理特征的一组肾小球疾病，是**病理形态学诊断**而非独立疾病实体。按免疫荧光可分为 IgA 沉积为主型（即 IgA 肾病）与非 IgA 型（IgG/IgM/C3 沉积或免疫荧光阴性）。","risk":["青少年与青壮年（我国原发性肾小球疾病中比例较高）","反复上呼吸道感染（部分病例与黏膜免疫相关）","家族史（少数）","继发于系统性疾病的可能（需排除）"],"epi":"在我国原发性肾小球疾病肾活检中，系膜增生性肾小球肾炎约占 10%–30%（远高于欧美），是原发性肾病综合征与血尿的常见病理类型。"},"patho":"系膜细胞增生与基质扩张使系膜区增宽，压迫毛细血管袢，导致滤过面积减少与滤过屏障受损。免疫荧光见免疫复合物在系膜区沉积（IgA、IgG 或 IgM + C3），提示免疫复合物介导。若沉积物以 IgA 为主且血清 IgA 升高、无系统性疾病，则归为 IgA 肾病；若以 IgM 沉积为主，可能与微小病变相关（IgM 肾病）；若免疫荧光阴性，需考虑非免疫性机制。病理上需评估是否伴节段性硬化（FSGS 样病变，预后较差）。","dx":{"criteria":["**肾活检是唯一确诊方式**：光镜见系膜细胞增生（每个系膜区 ≥3 个细胞）与基质增多，毛细血管袢开放","**免疫荧光分型**：IgA 为主（归入 IgA 肾病）；IgG 或 IgM 为主 + C3；C3 单独（需排除 C3 肾小球病）；免疫荧光阴性（需排除其他）","临床表现多样：无症状性血尿/蛋白尿（最常见）、肾病综合征、慢性肾炎综合征","**需排除继发性病因**：狼疮性肾炎（ANA、抗 dsDNA）、紫癜性肾炎（紫癜史）、感染相关（乙肝、丙肝、HIV）、药物","电镜：系膜区电子致密物沉积，足突可部分融合（融合程度与蛋白尿相关）","**必须与其他病理类型鉴别**（尤其 IgA 肾病、FSGS、微小病变）"],"workup":["尿常规 + 尿沉渣、24 小时尿蛋白或尿蛋白/肌酐比值","血肌酐、eGFR、白蛋白、血脂","**血清 IgA 与补体 C3**（IgA 升高提示 IgA 肾病）","ANA、抗 dsDNA（排除狼疮）、乙肝/丙肝/HIV 筛查","**肾活检（光镜 + 免疫荧光 + 电镜）** —— 唯一确诊方式","肾脏超声（大小与皮质厚度）","血压与眼底（慢性肾病评估）"],"grading":"按免疫荧光分：IgA 为主型（≈IgA 肾病）、非 IgA 型（IgG/IgM/C3）；按病理严重度分：轻度（系膜增生 <50% 肾小球）、中度、重度（弥漫增生 + 节段性硬化）；按 WHO 或半定量评分评估活动性与慢性化。"},"ddx":[{"name":"狼疮性肾炎（gn_lupus）","point":"与狼疮性肾炎的鉴别：后者需满足 SLE 分类标准（多系统受累 + ANA/抗 dsDNA 阳性 + 补体降低），免疫荧光「满堂亮」（含 C1q）；系膜增生性肾炎无系统表现与自身抗体。"},{"name":"紫癜性肾炎（gn_hspn）","point":"与紫癜性肾炎的鉴别：后者有可触及紫癜、腹痛或关节痛史；病理上两者可相同（IgA 沉积），区别在临床。"},{"name":"IgA 肾病（gn_iga）","point":"**最需鉴别的类型**：若免疫荧光以 IgA 为主沉积且血清 IgA 升高，则应诊断为 IgA 肾病（系膜增生性只是其病理表现之一）。"},{"name":"微小病变型肾病（gn_mcd）","point":"光镜下系膜正常或轻微，电镜见足突弥漫融合；系膜增生性肾炎的系膜增生更明显（若伴 IgM 沉积需注意「IgM 肾病」）。"},{"name":"局灶节段性肾小球硬化（gn_fsgs）","point":"病理见节段性硬化与足突融合，预后较系膜增生性更差；需在活检中仔细寻找硬化灶（易漏诊）。"},{"name":"感染后肾小球肾炎（gn_agn）","point":"有链球菌感染史、C3 降低、免疫荧光见「驼峰样」上皮下沉积；系膜增生性肾炎为系膜区沉积、C3 多正常。"}],"tx":{"drug":[{"name":"ACEI / ARB（基础治疗）","dose":"依那普利 5–20 mg/d 或缬沙坦 80–160 mg/d，按血压与蛋白尿滴定","note":"**所有伴蛋白尿者均应使用**（降蛋白尿、延缓肾功能进展，独立于降压作用）；需监测血钾与肌酐","renal":"Cr 升高 >30% 需评估；双侧肾动脉狭窄禁用","hepatic":"重度肝病慎用","interact":"与保钾利尿剂合用致高钾；与 NSAIDs 合用增加肾损伤"},{"name":"糖皮质激素（泼尼松，肾病综合征者）","dose":"1 mg/kg/d（最大 60–80 mg/d）口服 8–12 周，有效者逐渐减量，总疗程 6–12 个月","note":"用于合并肾病综合征者；单纯血尿或轻度蛋白尿不需激素；需监测血压、血糖与感染","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"环磷酰胺 / 钙调磷酸酶抑制剂（激素依赖或抵抗）","dose":"环磷酰胺 1.5–2 mg/kg/d 或静脉每月 1 次；他克莫司 0.05–0.1 mg/kg/d 分 2 次（监测血药浓度）","note":"用于频繁复发、激素依赖或抵抗者；钙调磷酸酶抑制剂需监测肾功能与血糖","renal":"他克莫司在肾功能不全时减量","hepatic":"他克莫司肝毒性，监测","interact":"他克莫司为 CYP3A4 底物（唑类抗真菌药、地尔硫卓显著升高浓度）"},{"name":"抗凝与抗血小板（部分中国方案）","dose":"双嘧达莫 75–150 mg tid 或低剂量肝素（按方案）","note":"在部分国内中心用于 IgA 或系膜增生性肾炎（改善微循环），但国际指南不推荐常规使用；需评估出血风险","renal":"低分子肝素按 CrCl 调整","hepatic":"肝病者慎用","interact":"与抗血小板药合用增加出血"},{"name":"鱼油（ω-3 脂肪酸，IgA 肾病证据）","dose":"1.2–3.6 g/d 口服","note":"针对 IgA 肾病（系膜增生性若归入 IgA 类可能适用），证据有限；可作为辅助","renal":"无需调整","hepatic":"无需调整","interact":"与抗凝合用增加出血风险"}],"nonDrug":["**控制血压（<130/80 mmHg）与蛋白尿（<0.5–1 g/d）** 是延缓进展的核心","限盐（<5 g/d）、优质低蛋白饮食（0.8 g/kg/d，肾功能下降时）","避免肾毒性药物（NSAIDs、氨基糖苷类）与造影剂","**扁桃体切除**：仅对反复扁桃体炎诱发的 IgA 肾病有争议性获益","戒烟、控制体重与血脂","定期监测肾功能与尿蛋白（每 3–6 个月）"],"life":["**长期随访**（多数为缓慢进展，需 5–10 年甚至终身随访）","上呼吸道感染后出现肉眼血尿属常见现象（IgA 相关），不必恐慌但需就诊","育龄女性妊娠前需评估肾功能与血压（妊娠可加重蛋白尿）","避免过度劳累与感染（可诱发发作）","疫苗接种（流感、肺炎球菌）"]},"prog":"预后差异大：单纯血尿或轻度蛋白尿者长期稳定（10 年肾脏生存 >90%）；伴肾病综合征、高血压、持续蛋白尿 >1 g/d 或病理见节段性硬化者，10–20 年内约 20%–40% 进展至终末期肾病。若归入 IgA 肾病范畴，其预后评估（如 MEST-C 评分）适用。","refs":["《肾小球疾病诊断与治疗中国专家共识》（中华医学会肾脏病学分会）","《内科学》第 9 版（人民卫生出版社）原发性肾小球疾病章","2021 KDIGO Clinical Practice Guideline for the Management of Glomerular Diseases","《中国 IgA 肾病诊治指南（2021）》"]}]},{"id":"renal_tubulo","name":"肾小管间质与血管性肾病","rank":7,"summary":"间质性肾炎的关键是「找药、找感染、找代谢病因」，停药往往比用药更有效；高血压肾损害看「长期高血压 + 夜尿增多 + 轻度蛋白尿」的组合，ACEI/ARB 是基石。","compare":[{"diseaseId":"renal_ain","dx":"有长期用药史（NSAIDs、质子泵抑制剂、锂、中药）或反复感染史，表现为夜尿增多、肾小管功能受损（尿浓缩能力下降）、轻度蛋白尿与 eGFR 缓慢下降","key":"肾小管功能受损突出而蛋白尿轻；停药后部分可稳定或改善"},{"diseaseId":"renal_htn_nephrosclerosis","dx":"长期高血压（常 >5–10 年）、夜尿增多、轻度至中度蛋白尿、左室肥厚与眼底改变，肾脏缩小、皮质变薄","key":"高血压病史是前提；控制血压（ACEI/ARB）可延缓进展"}],"diseases":[{"id":"renal_ain","name":"慢性间质性肾炎","aka":["Chronic Interstitial Nephritis","CIN","慢性肾小管间质性肾炎","药物性肾损害"],"rank":1,"basic":{"define":"以肾小管间质慢性炎症与纤维化为主要病理改变、肾小球相对保留的一组疾病。是导致不明原因慢性肾脏病与终末期肾病的重要原因之一（我国部分地区占比可达 10%–20%），**多数由药物、感染或代谢因素引起**。","risk":["**药物（最常见）**：长期使用 NSAIDs、质子泵抑制剂、锂盐、马兜铃酸类中药（含关木通、广防己）、环孢素与他克莫司、化疗药（顺铂）","反复尿路感染与梗阻","代谢因素：高尿酸血症、高钙血症、低钾血症","自身免疫病（干燥综合征、狼疮、结节病）","重金属（铅、镉）与职业暴露","放射治疗"],"epi":"我国慢性间质性肾炎在慢性肾脏病病因中约占 10%–20%（部分地区更高，与含马兜铃酸中药的既往使用相关）。老年人因多重用药与肾功能储备下降而风险更高。"},"patho":"毒性物质或免疫反应损伤肾小管上皮细胞，引起间质炎性细胞浸润（淋巴细胞、单核细胞）与纤维化。**肾小管损伤导致浓缩功能下降（夜尿增多）、酸化功能受损（肾小管酸中毒）、钠钾调节异常**；间质纤维化压迫管周毛细血管，造成缺血与进一步纤维化，最终肾小球硬化。与肾小球疾病不同，**间质性肾炎的蛋白尿通常较轻（<1–2 g/d，多为小管性蛋白尿）**，而肾小管功能损害突出，这是鉴别要点。","dx":{"criteria":["**长期用药史（详细追问 5–10 年内的所有药物，含中草药与保健品）** 或反复感染史","临床表现：**夜尿增多（最早期、最典型）**、多尿、乏力、轻度水肿；晚期出现贫血与肾衰竭","**实验室特点**：轻度蛋白尿（<1–2 g/d，以小分子蛋白为主，如 β2-微球蛋白升高）、**肾性糖尿（血糖正常时尿糖阳性）**、尿 pH 异常、低分子量蛋白尿、肾小管酸中毒（阴离子间隙正常的高氯性代谢性酸中毒、血钾可低）","**eGFR 缓慢下降**、血肌酐逐渐升高","影像：**双肾缩小、皮质变薄、表面不光整**（超声/CT），**无肾积水**（排除梗阻）","**肾活检（确诊与病因鉴别）**：间质纤维化、炎性细胞浸润、肾小管萎缩","**必须排除其他慢性肾脏病**：慢性肾小球肾炎（蛋白尿多）、高血压肾损害、多囊肾（影像）、梗阻性肾病（影像）"],"workup":["**详细用药史（含中药、保健品、止痛药）** —— 诊断的关键","尿常规、尿沉渣、24 小时尿蛋白或尿蛋白/肌酐比值（**通常较轻**）","**尿小分子蛋白（β2-微球蛋白、α1-微球蛋白、NAG 酶）** —— 肾小管损伤标志","**尿糖（血糖正常者）与尿 pH**、血气（肾小管酸中毒）、血钾、血钠","血肌酐、eGFR、血红蛋白（贫血）","**肾脏超声/CT（双肾缩小、皮质变薄、无积水）**","自身抗体（ANA、抗 SSA/SSB，干燥综合征）、血尿酸与血钙","**肾活检（确诊与病因）**","尿培养与泌尿系超声（排除慢性感染与梗阻）"],"grading":"按病因分：药物性、感染性、代谢性（高尿酸、高钙、低钾）、免疫性、职业性、特发性；按病理分：活动性（炎性浸润）与慢性化（纤维化与肾小管萎缩）；按肾功能分 CKD 分期（G1–G5）。"},"ddx":[{"name":"高血压肾损害（renal_htn_nephrosclerosis）","point":"与高血压肾损害的鉴别：后者有长期高血压史（多 >10 年）、常伴左室肥厚与眼底改变、蛋白尿可更多；间质性肾炎的肾小管功能损害更突出而蛋白尿轻。"},{"name":"慢性肾小球肾炎（ckd_stage）","point":"与慢性肾炎的鉴别：肾小球肾炎的**蛋白尿多（常 >1–2 g/d，可至肾病范围）**、可见红细胞管型；间质性肾炎以肾小管功能受损为主。"},{"name":"梗阻性肾病（renal_obstruct）","point":"影像见肾积水与输尿管扩张，解除梗阻后肾功能可改善；间质性肾炎无积水。"},{"name":"急性间质性肾炎（药物性急性）","point":"急性起病（数天至数周）、可伴发热皮疹与嗜酸性粒细胞增多、肾功能快速下降；慢性者病程 >3–6 个月、以纤维化为主。"},{"name":"多囊肾（renal_pkd）","point":"影像见双肾多发囊肿与肾脏增大；与间质性肾炎的双肾缩小相反。"},{"name":"干燥综合征肾损害","point":"有口干、眼干、抗 SSA/SSB 阳性，肾活检见间质淋巴细胞浸润；属间质性肾炎的继发病因之一。"}],"tx":{"drug":[{"name":"停用致病药物（最重要）","dose":"立即停用可疑药物（NSAIDs、质子泵抑制剂、锂盐、含马兜铃酸中药等）","note":"**停药是慢性间质性肾炎最重要且最有效的干预**；早期停药者肾功能可部分恢复或稳定，晚期纤维化者仅能延缓进展","renal":"—","hepatic":"—","interact":"—"},{"name":"糖皮质激素（活动性炎症期）","dose":"泼尼松 0.5–1 mg/kg/d 口服 2–4 周后逐渐减量（总疗程 2–3 个月）","note":"用于肾活检见明显活动性炎症或急性成分（药物性、自身免疫性）者；已形成广泛纤维化者获益有限","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"纠正代谢因素","dose":"高尿酸血症：别嘌醇 100–300 mg/d（按 CrCl 减量）或非布司他 20–40 mg/d，目标血尿酸 <360 μmol/L；高钙血症：纠正原发病、补液；低钾血症：补钾","note":"代谢性病因（高尿酸、高钙、低钾）需同时纠正，否则间质损伤持续","renal":"别嘌醇与非布司他需按 CrCl 减量","hepatic":"非布司他肝毒性需监测","interact":"别嘌醇与硫唑嘌呤/6-MP 合用需大幅减量"},{"name":"碳酸氢钠（肾小管酸中毒）","dose":"1–3 mmol/kg/d 分次口服（目标血碳酸氢根 >22 mmol/L）","note":"纠正代谢性酸中毒可延缓 CKD 进展（尤其酸中毒明显者）；需监测血钠与容量","renal":"注意钠负荷（心衰与水肿者慎用）","hepatic":"无需调整","interact":"与含钙制剂合用可致碱中毒；影响多种药物排泄（水杨酸、锂）"},{"name":"ACEI / ARB（蛋白尿与进展控制）","dose":"依那普利 5–20 mg/d 或缬沙坦 80–160 mg/d（按血压与耐受性滴定）","note":"适用于伴蛋白尿与高血压者；间质性肾炎本身蛋白尿较轻，获益不如肾小球疾病明确","renal":"监测肌酐与血钾","hepatic":"重度肝病慎用","interact":"与保钾利尿剂合用致高钾"},{"name":"促红细胞生成素与铁剂（肾性贫血）","dose":"EPO 按体重与血红蛋白调整（目标 Hb 100–115 g/L）；铁剂补充（目标 TSAT >20%、铁蛋白 >100 ng/mL）","note":"慢性间质性肾炎易出现贫血（促红细胞生成素合成减少）","renal":"无","hepatic":"无","interact":"无特殊"}],"nonDrug":["**避免再次使用致病药物**（记录在病历与患者卡上）","**避免肾毒性药物**（NSAIDs、氨基糖苷类、造影剂）","控制血压（<130/80 mmHg）、限盐、适量蛋白饮食（0.8 g/kg/d）","**中药与保健品需谨慎**（马兜铃酸类已禁用，但市面上仍存在混杂产品）","避免脱水与容量不足（加重肾灌注下降）","终末期肾病：透析或肾移植"],"life":["**用药前告知医师肾功能情况**（所有处方需按 eGFR 调整）","定期监测肾功能（每 3–6 个月）、尿蛋白与电解质","避免自行服用止痛药与中草药","控制尿酸（低嘌呤饮食）、钙与钾的摄入（按化验调整）","疫苗接种（流感、肺炎球菌、乙肝）"]},"prog":"早期停药者约 30%–50% 肾功能可部分恢复或稳定；已发生广泛间质纤维化者多为不可逆，进展速度差异大（部分患者数年内进入终末期）。**药物性慢性间质性肾炎的预后取决于累积剂量与暴露时长**。终末期肾病需透析或移植，移植后预后良好（无复发）。","refs":["《内科学》第 9 版（人民卫生出版社）间质性肾炎章","2021 KDIGO Clinical Practice Guideline for the Management of Glomerular Diseases（间质性肾炎章节参照）","《中国慢性肾脏病早期评价与管理指南》（2023）","2019 International Consensus on Drug-Induced Interstitial Nephritis (KI Reports)"]},{"id":"renal_htn_nephrosclerosis","name":"高血压肾损害","aka":["Hypertensive Nephrosclerosis","良性小动脉性肾硬化","高血压肾病","Hypertensive Nephropathy"],"rank":2,"basic":{"define":"长期未控制的高血压导致肾小动脉硬化（入球小动脉玻璃样变、弓形动脉与叶间动脉内膜增厚）与肾实质缺血，引起夜尿增多、轻度蛋白尿与缓慢进展的肾功能下降。是慢性肾脏病的第二位常见病因（仅次于糖尿病肾病）。","risk":["**长期高血压（通常 >5–10 年，血压控制不佳）**","老年人与非洲裔人群（更易发生）","合并糖尿病、高尿酸血症、肥胖与代谢综合征","吸烟","高血压家族史与盐敏感"],"epi":"高血压肾损害占终末期肾病病因的 20%–30%（不同国家差异大）。我国 CKD 病因中高血压肾损害约占 15%–20%。**高血压与 CKD 互为因果**（高血压致肾损害，肾损害加重高血压），形成恶性循环。"},"patho":"长期高压使肾小动脉发生玻璃样变性（入球小动脉）与内膜纤维性增厚（弓形与叶间动脉），管腔狭窄致肾实质慢性缺血，肾小球出现缺血性硬化（球性硬化）与肾小管萎缩、间质纤维化。同时，肾小球内高压（由系统性高血压传导）造成足细胞损伤与蛋白尿，进一步激活 RAAS 与炎症，形成进展循环。**肾脏病理表现为「良性肾小动脉硬化」**，与恶性高血压的纤维素样坏死不同。","dx":{"criteria":["**长期高血压病史（通常 ≥5–10 年）**，且血压控制不佳","**夜尿增多（最早期的肾小管浓缩功能下降表现）**，可伴轻度水肿","**蛋白尿：通常为轻度至中度（<1 g/d，常 <0.5 g/d）**，罕见肾病范围；尿沉渣多无明显血尿或红细胞管型","**肾功能缓慢下降**（eGFR 逐年下降）","**肾脏影像**：双肾缩小、皮质变薄、表面可呈细颗粒状（超声/CT）","**其他靶器官损害证据**：左室肥厚（心超/心电图）、高血压视网膜病变（Keith-Wagener 分级）、颈动脉内膜增厚","**排除其他 CKD 病因**：糖尿病肾病（糖尿病史、大量蛋白尿）、慢性肾小球肾炎（蛋白尿多、血尿）、间质性肾炎、梗阻性肾病","**肾活检（仅在不典型或诊断不明时）**：见小动脉硬化、缺血性肾小球硬化与间质纤维化"],"workup":["尿常规 + 尿沉渣、24 小时尿蛋白或尿蛋白/肌酐比值（**多 <1 g/g**）","血肌酐、eGFR（**用 CKD-EPI 2021，不用 MDRD**）、胱抑素 C","**血压测量（双上肢、必要时动态血压监测）**","**心电图与心脏超声（左室肥厚）**、眼底检查（视网膜病变）","**肾脏超声（大小、皮质厚度、有无积水）**","血糖与 HbA1c（排除糖尿病肾病）、血脂、尿酸","自身抗体与补体（排除肾小球疾病）、乙肝/丙肝","**肾活检（不典型病例）**"],"grading":"按病理分：良性小动脉性肾硬化（玻璃样变、缺血性硬化）与恶性肾硬化（纤维素样坏死，见于恶性高血压）；按肾功能分 CKD 分期（G1–G5）+ 白蛋白尿分期（A1–A3）；高血压心血管风险分层（低危至高危）。"},"ddx":[{"name":"慢性间质性肾炎（renal_ain）","point":"与间质性肾炎的鉴别：后者有明确药物或感染史，肾小管功能损害更突出（肾性糖尿、肾小管酸中毒），无长期高血压与左室肥厚。"},{"name":"慢性肾小球肾炎（ckd_stage）","point":"与慢性肾炎的鉴别：肾小球肾炎的**蛋白尿更多（常 >1–2 g/d）**、可见血尿与红细胞管型、常伴低白蛋白血症；高血压肾损害的蛋白尿轻。"},{"name":"糖尿病肾病（ckd_dkd）","point":"**最需鉴别**：糖尿病肾病有长期糖尿病史、**大量蛋白尿（常 >0.5 g/d 且逐渐增加至肾病范围）**、视网膜病变与糖尿病病程平行；高血压肾损害的蛋白尿轻且眼底为高血压性改变。"},{"name":"恶性高血压肾损害","point":"血压显著升高（舒张压 >130 mmHg）伴视网膜出血渗出（Ⅲ–Ⅳ 级）、肾功能快速恶化、可伴微血管病性溶血；需急诊降压。"},{"name":"缺血性肾病（肾动脉狭窄）","point":"有动脉粥样硬化或大动脉炎背景，影像见肾动脉狭窄、双肾大小差异 >1.5 cm；ACEI/ARB 后肌酐显著升高是线索。"},{"name":"多囊肾（renal_pkd）","point":"双肾增大 + 多发囊肿 + 家族史；与高血压肾损害的肾脏缩小相反。"}],"tx":{"drug":[{"name":"ACEI / ARB（首选）","dose":"依那普利 5–20 mg/d 或缬沙坦 80–320 mg/d、氯沙坦 50–100 mg/d，按血压滴定至最大耐受剂量","note":"**高血压肾损害的一线降压药**，可降低肾小球内压、减少蛋白尿、延缓进展（不依赖降压幅度）；需监测血肌酐（升高 <30% 可接受）与血钾","renal":"Cr 升高 >30% 需评估；双侧肾动脉狭窄禁用","hepatic":"重度肝病慎用","interact":"与保钾利尿剂、补钾剂合用致高钾；与 NSAIDs 合用降低疗效并增加肾损伤"},{"name":"钙通道阻滞剂（氨氯地平/硝苯地平控释）","dose":"氨氯地平 5–10 mg qd；硝苯地平控释 30–60 mg qd","note":"用于不能耐受 ACEI/ARB 或需联合降压者；降压平稳，对肾功能无不良影响","renal":"无需调整","hepatic":"肝病者减量","interact":"与 CYP3A4 抑制剂合用升高浓度；与 β 阻滞剂合用注意心衰"},{"name":"噻嗪类或袢利尿剂","dose":"氢氯噻嗪 12.5–25 mg qd（eGFR >30）；呋塞米 20–40 mg qd（eGFR <30 或容量负荷重）","note":"用于容量负荷过重或难控高血压；需监测电解质（低钾、低钠）与尿酸","renal":"eGFR <30 时噻嗪类效果差，改用袢利尿剂","hepatic":"肝硬化者注意低钾与肝性脑病","interact":"与锂盐合用增加锂中毒；与 NSAIDs 合用降低利尿效果"},{"name":"β 受体阻滞剂（美托洛尔/比索洛尔）","dose":"美托洛尔缓释 47.5–95 mg qd 或比索洛尔 5–10 mg qd","note":"用于合并冠心病、心衰或心率快者；单药降压效果弱于 ACEI/ARB 与 CCB","renal":"无需调整","hepatic":"肝病者减量","interact":"与维拉帕米、地尔硫卓合用增加传导阻滞与心衰风险"},{"name":"SGLT2 抑制剂（达格列净/恩格列净）","dose":"达格列净 10 mg qd 或恩格列净 10 mg qd","note":"**近年证据支持用于 CKD（含非糖尿病）延缓进展**（DAPA-CKD、EMPA-KIDNEY）；可降低 eGFR 下降速率与心血管事件；注意生殖道感染","renal":"eGFR ≥20 可用","hepatic":"重度肝损害慎用","interact":"与利尿剂合用注意容量不足"},{"name":"他汀（阿托伐他汀/瑞舒伐他汀）","dose":"阿托伐他汀 20–40 mg qn 或瑞舒伐他汀 10 mg qn","note":"高血压合并 CKD 为心血管极高危，需调脂治疗","renal":"瑞舒伐他汀 CrCl <30 起始 5 mg","hepatic":"活动性肝病禁用","interact":"与 CYP3A4 抑制剂合用增加肌病风险"},{"name":"促红细胞生成素（肾性贫血）","dose":"按体重给药，目标 Hb 100–115 g/L（避免 >130 g/L）","note":"CKD 贫血的标准治疗；需同时补铁","renal":"无","hepatic":"无","interact":"无特殊"}],"nonDrug":["**严格血压控制（目标 <130/80 mmHg，蛋白尿者更严格）** —— 是延缓进展的核心","**限盐（<5 g/d）**、减重、规律运动、戒烟限酒","**避免肾毒性药物**（NSAIDs、氨基糖苷类、造影剂）","**动态血压监测**（评估夜间血压与「非杓型」）","CKD 并发症管理：贫血、钙磷代谢、酸中毒","终末期肾病：透析或肾移植"],"life":["**家庭血压监测**（每日早晚各一次，记录）","定期随访：每 3–6 个月查 eGFR、尿蛋白、血钾","**避免脱水**（腹泻、高温、过度利尿可致急性肾损伤）","低蛋白饮食（0.8 g/kg/d，透析者增加）与低磷饮食（晚期）","疫苗接种（流感、肺炎球菌、乙肝）","心血管风险评估与综合管理（高血压、血脂、血糖、戒烟）"]},"prog":"规范的血压控制可将 eGFR 下降速率从每年 5–10 mL/min 减缓至 1–2 mL/min，显著延缓终末期肾病。**蛋白尿水平与血压控制是预后的最强预测因子**。合并糖尿病、吸烟与未控制血压者进展更快。终末期肾病需替代治疗，肾移植后预后良好但原发病（高血压）持续存在。","refs":["《中国高血压防治指南（2024 年修订版）》（中华医学会心血管病学分会）","2021 KDIGO Clinical Practice Guideline for Blood Pressure Management in CKD","2024 KDIGO Clinical Practice Guideline for the Evaluation and Management of CKD","《中国慢性肾脏病早期评价与管理指南》（2023）","2021 DAPA-CKD Trial (NEJM) 与 2022 EMPA-KIDNEY Trial (NEJM)"]}]},{"id":"dialysis","name":"血液净化","rank":41,"summary":"血液净化的核心是把握启动时机与模式选择：CKD 5 期 eGFR<10 或出现尿毒症并发症、难治性高钾/酸中毒/容量负荷时启动，HD 与 PD 按残余肾功能、心血管稳定性与腹部条件个体化选择，并以 Kt/V、容量与矿物质代谢为质控指标。","compare":[],"diseases":[{"id":"renal_dialysis","name":"血液净化（血液透析与腹膜透析）","aka":["Hemodialysis","Peritoneal dialysis","HD","PD","血液透析","腹膜透析","维持性透析","肾脏替代治疗"],"rank":1,"basic":{"define":"血液净化指通过体外循环（血液透析/血液滤过）或腹膜（腹膜透析）清除代谢废物、纠正水电解质与酸碱失衡、替代部分肾脏功能的治疗；用于终末期肾病（ESRD）维持治疗，以及急性肾损伤、难治性高钾、肺水肿与可透析毒物中毒等急症。","risk":["糖尿病肾病（我国 ESRD 首位病因，约占 25%–30%）","高血压肾损害、慢性肾小球肾炎与多囊肾","急性肾损伤（脓毒症、大手术、肾毒性药物）","高龄、心力衰竭与外周血管病（透析低血压与通路困难）","既往腹部手术、疝、腹膜粘连或腹膜功能不全（PD 相对禁忌）","依从性差、饮水不控制与透析不充分"],"epi":"我国维持性血液透析患者已超过 80 万例，腹膜透析约 15 万例，年新增透析患者约 10 万–15 万例，HD 占 85% 以上；ESRD 患病率约 400–500/百万。"},"patho":"肾小球滤过功能丧失使尿素、肌酐、胍类与中分子物质蓄积，水钠潴留致容量负荷与高血压，氢离子与钾排泄障碍致代谢性酸中毒与高钾血症，活性维生素 D 与促红素生成减少致肾性骨病与贫血。HD 依赖弥散清除小分子、超滤清除水分；PD 依赖腹膜毛细血管与透析液间的弥散及葡萄糖/艾考糊精的渗透性超滤。两者均不能完全替代内分泌与代谢功能，残余肾功能对预后至关重要，PD 者残余肾功能下降相对较慢。","dx":{"criteria":["CKD 5 期透析指征：eGFR <10 mL/(min·1.73 m²)（糖尿病肾病可提前至 <15），或虽 eGFR 未达阈值但出现尿毒症症状","急诊透析指征（AEIOU）：难治性高钾血症（血钾 >6.5 mmol/L 或 ECG 出现改变且药物无效）；代谢性酸中毒（pH <7.1 或 HCO₃⁻ <10 mmol/L）；容量负荷过重（急性肺水肿、利尿剂无效）；尿毒症并发症（心包炎、脑病、出血倾向、顽固恶心呕吐）；可透析毒物中毒","尿毒症症状：乏力、食欲减退、恶心呕吐、皮肤瘙痒、睡眠障碍与体重下降；难以纠正的贫血与营养不良","容量负荷：血压难以控制、外周水肿、肺水肿、左室肥厚或心衰；HD 透析间期体重增长超过干体重 5%","高钾与酸中毒：血钾 >5.5 mmol/L 需饮食与药物干预，>6.5 mmol/L 或伴 ECG 改变需急诊透析；HCO₃⁻ <22 mmol/L 为代谢性酸中毒","透析充分性：HD 单室 Kt/V ≥1.2（每周 3 次、每次 4 h，目标 1.2–1.4）；PD 每周总 Kt/V ≥1.7、肌酐清除率 ≥50 L/(week·1.73 m²)","HD 血管通路：自体动静脉内瘘（AVF）首选，成熟需 6–8 周（静脉直径 ≥5 mm、血流量 ≥500 mL/min、距皮深度 <6 mm）；人工血管（AVG）需 2–4 周；中心静脉导管仅作临时或过渡","PD 适应证与禁忌：腹膜面积足够、无腹部大手术或疝；相对禁忌包括新发腹部手术、疝、炎症性肠病、严重肥胖与反复腹膜炎"],"workup":["肾功能（肌酐、尿素、eGFR）、电解质（钾、钠、钙、磷、镁）、血气/HCO₃⁻、白蛋白、血红蛋白、铁代谢、iPTH 与 25-OH 维生素 D","尿量、干体重、透析间期体重增长与家庭血压记录","HD：Kt/V（在线清除率或公式）、透析前后尿素、血流量与透析器面积；通路超声评估流量与狭窄","PD：腹膜平衡试验（PET，4 h D/P 肌酐比值）、每周 Kt/V 与肌酐清除率；腹透液浑浊时行常规、细胞计数与培养","心脏超声（左室肥厚、心包积液）、胸部 X 线（肺水肿、导管位置）与腹部超声（多囊肾、腹水）","血管通路评估：Duplex 超声，必要时血管造影；PD 导管出口处与隧道评估"],"grading":"CKD 分期 G1–G5（G5 为 eGFR <15）。透析充分性分级：HD Kt/V ≥1.2 达标、1.0–1.2 边缘、<1.0 不足；PD 每周 Kt/V ≥1.7 达标。HD 按频率分常规（3 次/周）、递增（2 次/周）与每日短时/夜间透析；PD 按模式分持续不卧床腹膜透析（CAPD）与自动化腹膜透析（APD）。"},"ddx":[{"name":"急性肾损伤（aki_aki）","point":"与本类（血液净化）的鉴别点：AKI 是否启动透析取决于难治性高钾、酸中毒、容量负荷与尿毒症并发症，而非肌酐绝对值；CKD 5 期 eGFR <10 且症状明显者进入维持性透析，两者透析处方与肾功能恢复预期不同。"},{"name":"慢性肾脏病 5 期（ckd_stage）","point":"CKD 5 期是透析前状态，eGFR <15 但无尿毒症症状者可先保守治疗并准备通路；透析是替代治疗手段而非独立疾病。"},{"name":"心力衰竭致肺水肿","point":"心衰者 eGFR 可正常、BNP 显著升高、对利尿剂有反应；透析者肺水肿多伴透析间期体重增长过多与超滤不足。"},{"name":"非肾性高钾血症","point":"溶血、横纹肌溶解、醛固酮减少症可致高钾而肾功能正常；透析仅用于难治性或合并肾衰者。"},{"name":"腹膜透析相关腹膜炎与继发性腹膜炎","point":"PD 腹膜炎腹透液浑浊、白细胞 >100/µL（中性粒 >50%）、培养阳性，多无全腹压痛；继发性腹膜炎有原发病灶、气腹或脓毒症表现，需外科处理。"},{"name":"透析失衡综合征与脑卒中/低血糖","point":"失衡综合征见于首次或高效透析后 3–24 h，表现为头痛、恶心、抽搐与意识障碍，血尿素下降过快；CT 无新发病灶且血糖正常。"},{"name":"透析低血压与心源性休克","point":"透析低血压多发生于超滤过快（>1.0–1.3 L/h）或餐后，减慢超滤、补液后恢复；心源性休克伴心肌损伤标志物升高与心功能下降。"}],"tx":{"drug":[{"name":"重组人促红素（ESA）","dose":"100–150 IU/kg 皮下注射，每周 2–3 次；或达依泊汀 α 0.45 µg/kg 每周 1 次；目标 Hb 100–120 g/L","note":"纠正肾性贫血，用药前先补铁（TSAT >20%、铁蛋白 >100 ng/mL）；Hb 上升过快（>10 g/L/月）或 >130 g/L 增加血栓与死亡风险。","renal":"透析患者按说明书使用，Hb 达标后减量维持","hepatic":"遵说明书","interact":"与 ACEI/ARB 合用可能轻度降低反应性；避免与其他 ESA 叠加"},{"name":"蔗糖铁","dose":"100–200 mg 加入 100 mL 生理盐水静滴 30 min，每周 1–3 次；累计补铁量按 Ganzoni 公式计算","note":"透析患者静脉补铁首选；首次输注备急救设备并观察 30 min，避免与促红素同日大剂量叠加。","renal":"透析患者常用，按说明书","hepatic":"严重肝损慎用","interact":"与口服铁剂错开使用；不与其他静脉药物同通路混合"},{"name":"碳酸钙（磷结合剂）","dose":"0.5–1 g 餐中嚼服 tid，按血磷调整；目标血磷 1.13–1.78 mmol/L","note":"廉价易得，但高钙血症与血管钙化风险；血钙 >2.5 mmol/L 或 Ca×P >4.4 mmol²/L² 时改用非钙结合剂。","renal":"透析患者可用，需监测血钙","hepatic":"遵说明书","interact":"与四环素、喹诺酮类、左甲状腺素同服降低吸收，需间隔 2 h"},{"name":"司维拉姆","dose":"800–1600 mg 餐中服用 tid，按血磷调整","note":"非钙磷结合剂，适用于高钙血症、血管钙化或钙负荷过高者；主要不良反应为胃肠道不适。","renal":"无需调整","hepatic":"遵说明书","interact":"可降低脂溶性维生素与部分药物吸收；与环丙沙星间隔 2 h"},{"name":"骨化三醇","dose":"0.25 µg qd 口服，按 iPTH 与血钙调整；CKD 5D 目标 iPTH 150–300 pg/mL","note":"活性维生素 D，抑制继发性甲旁亢；需同时监测钙、磷，避免高钙与无动力骨病。","renal":"透析患者常用，按说明书","hepatic":"遵说明书","interact":"与噻嗪类、钙剂合用加重高钙；与地高辛合用高钙可致心律失常"},{"name":"碳酸氢钠","dose":"1–2 g tid 口服，目标 HCO₃⁻ ≥22 mmol/L","note":"纠正代谢性酸中毒、延缓 CKD 进展；监测血钠与容量，避免加重高血压与水肿。","renal":"透析患者按透析液与口服量调整","hepatic":"遵说明书","interact":"与四环素、喹诺酮类合用降低吸收；与含钙制剂间隔服用"},{"name":"氨氯地平","dose":"5 mg qd 口服，可增至 10 mg qd","note":"透析患者高血压常用，钙通道阻滞剂不被透析清除；容量控制仍是降压基础。","renal":"无需调整","hepatic":"肝功能不全减量","interact":"CYP3A4 抑制剂升高血药浓度；与辛伐他汀合用增加肌病风险（辛伐他汀限 20 mg）"},{"name":"万古霉素联合头孢他啶（腹膜透析相关腹膜炎，腹腔内给药）","dose":"万古霉素 15–30 mg/kg（或 1 g）加入 2 L 腹透液留腹 6 h，每 5–7 天 1 次；头孢他啶 1 g 负荷后 125–250 mg/L 每袋维持","note":"留取腹透液培养后立即经验性给药，覆盖革兰阳性与阴性菌；按培养与药敏调整，疗程一般 2–3 周。","renal":"按血药浓度与残余肾功能调整","hepatic":"遵说明书","interact":"万古霉素与氨基糖苷类叠加耳肾毒性；头孢他啶与含钙输液同通路可能沉淀"}],"nonDrug":["HD 通路：AVF 首选（多取非优势手桡动脉-头静脉），术前血管超声评估；AVG 用于血管条件差者；中心静脉导管仅临时使用，感染与狭窄风险高","HD 处方：3 次/周、每次 4 h，血流量 250–300 mL/min，透析液流量 500 mL/min；超滤率控制在 1.0–1.3 L/h 以下以减少低血压","PD 处方：CAPD 每日 4 次、每次 2 L 留腹 4–6 h；APD 夜间循环；初始低容量（1.5–2 L）避免疝与渗漏","模式选择：PD 适合残余肾功能较好、心血管不稳定、需居家治疗且无腹部禁忌者；HD 适合腹部手术/疝、腹膜功能差或需快速清除者","肾移植为最优替代治疗，透析期间应评估移植指征与配型","通路监测：AVF 每 3 个月超声，狭窄 >50% 伴流量下降行经皮腔内血管成形；PD 导管置入后 2 周开始使用，出口处每日护理"],"life":["饮食：优质蛋白 HD 1.0–1.2 g/(kg·d)、PD 1.0–1.3 g/(kg·d)，热量 30–35 kcal/(kg·d)；限钠 <2 g/日，血钾 >5.5 mmol/L 时限钾 <2000 mg/日，限磷 800–1000 mg/日","每日测体重与血压；HD 透析间期体重增长不超过干体重 5%（一般 ≤2–3 kg）","保护通路侧肢体：避免测血压、抽血与提重物；PD 者避免盆浴与游泳，出口处保持干燥","疫苗接种：乙肝（加倍剂量）、流感（每年）、肺炎球菌与新冠疫苗；乙肝表面抗体 <10 mIU/mL 需加强","定期复查：每月血常规、电解质与肾功能；每 3 个月 Kt/V、营养评估与 iPTH；每年心脏超声与胸片"]},"prog":"我国 HD 患者 5 年生存率约 60%–70%，PD 相近；心血管疾病占透析患者死亡的 40%–50%，透析患者年死亡率约 10%–15%。规范 Kt/V、容量控制与贫血/矿物质代谢管理可显著改善生存；肾移植后 10 年存活率 >80%（活体供肾更优）。","refs":["国家卫生健康委办公厅《血液净化标准操作规程（2021 版）》（国卫办医函〔2021〕552 号）","中国医师协会肾脏内科医师分会血液透析充分性协作组《中国血液透析充分性临床实践指南》（中华医学杂志 2015;95(34):2748-2753）","《腹膜透析标准操作规程》（2010）","KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease","KDOQI Clinical Practice Guideline for Hemodialysis Adequacy: 2015 Update"]}]}]},"resp":{"categories":[{"id":"pe","name":"肺栓塞","rank":1,"summary":"以“先分层、后决策”为核心：确诊后即刻按血流动力学稳定性分为高危（休克/持续低血压）与非高危，非高危再以 sPESI 与右心功能/肌钙蛋白分为中高危、中低危与低危；低危者可早期离院，中高危需密切监护，高危需全身溶栓或介入取栓。所有患者均需足量抗凝，并筛查诱因、评估抗凝疗程与 CTEPH 风险。","compare":[{"diseaseId":"pe_acute","dx":"突发呼吸困难/胸痛 + 有诱因 + D-二聚体升高、CTPA 见充盈缺损；低血压者直接按高危处理","key":"急性起病、右心负荷表现（颈静脉怒张、P2 亢进、右心扩大）、D-二聚体与 CTPA 阳性；抗凝/溶栓为核心"},{"diseaseId":"pe_chronic","dx":"急性 PE 后抗凝 ≥3 个月仍活动后气促，V/Q 扫描呈多发节段性灌注缺损，右心导管 mPAP ≥20 mmHg","key":"症状持续数月、进行性右心衰、无急性血栓可消退征象；需终身抗凝并评估 BPA 或 PEA 手术"}],"diseases":[{"id":"pe_acute","name":"急性肺栓塞","aka":["Acute PE","APE","肺血栓栓塞症 PTE"],"rank":1,"basic":{"define":"内源性或外源性栓子（绝大多数来自下肢深静脉）阻塞肺动脉或其分支，引起肺循环与右心功能障碍的临床综合征；急性 PE 与 DVT 合称静脉血栓栓塞症（VTE）。","risk":["近期手术（尤其髋膝关节置换、腹部大手术）、骨折与创伤、长期制动/卧床","既往 VTE 史、恶性肿瘤（尤其活动期化疗中）、妊娠与产褥期、口服避孕药或激素替代","易栓症（抗凝血酶/蛋白 C/蛋白 S 缺陷、因子 V Leiden、抗磷脂综合征）","肥胖、高龄、吸烟、心力衰竭、慢性肺部疾病、炎症性肠病","中心静脉导管、起搏器导线等血管内装置"],"epi":"急性 PE 是第三大常见心血管急症，年发病率约 39–115/10 万；未治疗者病死率可达 25%–30%，经规范诊治可降至 2%–8%；约 3%–5% 的急性 PE 属高危（伴休克）。"},"patho":"栓子堵塞肺动脉使肺血管床横截面积骤减，肺血管阻力急升，右室后负荷增加致右室扩张、室间隔左移、左室舒张受限与心输出量下降，形成梗阻性休克。缺血肺组织释放血栓素与 5-羟色胺加重血管收缩；同时肺泡死腔增大与表面活性物质减少可致低氧血症与肺不张；约 10% 病例出现肺梗死与胸膜性胸痛、咯血。","dx":{"criteria":["临床可能性评估：Wells 评分（DVT 症状 3、PE 可能性大于其他诊断 3、心率 >100 次/分 1.5、近 4 周制动或手术 1.5、既往 VTE 1.5、咯血 1、恶性肿瘤 1），>4 分为“可能”，≤4 分为“不太可能”；或修订 Geneva 评分（0–3 低、4–10 中、≥11 高）。","疑诊且血流动力学稳定：按可能性分层使用“YEARS”或年龄校正 D-二聚体——Wells ≤4 且 D-二聚体 <1000 ng/mL（FEU）、或 Wells >4 且 <500 ng/mL 可排除；>50 岁者界值可用年龄×10 ng/mL。","确诊影像：CT 肺动脉造影（CTPA）为首选；V/Q 扫描适用于碘造影剂禁忌或妊娠；下肢静脉超声发现近端 DVT 可支持诊断。","血流动力学不稳定（收缩压 <90 mmHg 或下降 ≥40 mmHg 持续 >15 分钟，非心律失常、低血容量或脓毒症所致）时，床旁超声见右心扩大/RV 功能障碍可支持经验性再灌注，不必等待 CTPA。","危险分层：高危＝休克或持续低血压；非高危用 sPESI（年龄 >80、肿瘤、慢性心肺疾病、心率 ≥110、收缩压 <100、SpO₂ <90% 各 1 分，0 分为低危）结合右心功能（超声或 CT 右室/左室比值 >0.9、BNP 升高）与肌钙蛋白分层。"],"workup":["血气分析：低氧、低碳酸血症、肺泡-动脉氧分压差增大，但约 20% 患者血气可正常","D-二聚体：敏感性高、特异性低，适用于排除而非确诊；住院、肿瘤、老年、妊娠者常假阳性","心电图：窦性心动过速最常见，可出现 SⅠQⅢTⅢ、右束支传导阻滞、V1–V4 T 波倒置","超声心动图：评估右室扩大、室间隔平直（D 字征）、三尖瓣反流速度与肺动脉收缩压，动态随访对中危患者决策关键","CTPA：直接显示充盈缺损并可评估右室/左室比值；肾功能不全者注意造影剂肾病","肌钙蛋白、BNP/NT-proBNP：反映右室心肌损伤与张力，用于中危细分"],"grading":"高危（伴休克/低血压）→ 全身溶栓或介入取栓；中高危（sPESI ≥1 + 右心功能不全 + 肌钙蛋白升高，血压正常）→ 抗凝 + 严密监护，恶化时补救溶栓；中低危（sPESI ≥1 或右心功能/肌钙蛋白其一阳性）→ 住院抗凝；低危（sPESI 0 且右心功能、肌钙蛋白均正常、社会支持良好）→ 可考虑早期离院口服抗凝。"},"ddx":[{"name":"慢性血栓栓塞性肺动脉高压","point":"与本类中 CTEPH 的鉴别点：急性 PE 起病急、伴明确诱因、D-二聚体高、CTPA 见新鲜充盈缺损可随抗凝消退；CTEPH 为急性事件后症状持续 >3 个月不缓解、逐步加重右心衰，影像见机化附壁血栓/网带样改变，需 V/Q 扫描与右心导管确认。"},{"name":"急性冠脉综合征","point":"胸痛伴 ST-T 改变与肌钙蛋白升高；但 ACS 多为压榨性胸骨后痛、无低氧、D-二聚体不显著升高，冠脉造影可明确。"},{"name":"主动脉夹层","point":"撕裂样胸背痛、双上肢血压差、纵隔增宽；CTPA 时需同时观察主动脉（必要时主动脉 CTA）。"},{"name":"肺炎","point":"发热、咳脓痰、肺部湿啰音，影像为实变而非血管内充盈缺损；但 PE 可继发肺梗死并伴低热。"},{"name":"自发性气胸","point":"突发单侧胸痛与呼吸困难，患侧呼吸音消失、叩诊鼓音，胸片即可确诊。"},{"name":"心包填塞","point":"低血压伴颈静脉怒张、心音低钝、超声见心包积液与右心塌陷；PE 右心扩大但无心包积液。"}],"tx":{"drug":[{"name":"普通肝素（UFH）静脉","dose":"负荷 80 U/kg 静推，继以 18 U/kg/h 泵入，按 APTT 目标 1.5–2.5 倍（或抗 Xa 0.3–0.7 IU/mL）调整","note":"高危患者首选，因可被鱼精蛋白快速拮抗，便于随时溶栓或手术；溶栓后继续用 UFH","renal":"主要经网状内皮清除，肾衰竭可安全使用；仍需监测 APTT","hepatic":"严重肝病伴凝血障碍者慎用，需监测","interact":"与抗血小板药、NSAIDs、溶栓药合用出血风险叠加"},{"name":"低分子肝素（依诺肝素）皮下","dose":"100 IU/kg（约 1 mg/kg）q12h；或 150 IU/kg（1.5 mg/kg）qd；中高危/高危者建议 q12h 方案","note":"非高危患者首选起始抗凝；孕中期/晚期与肿瘤相关血栓亦为常用选择","renal":"CrCl <30 mL/min 减量至 1 mg/kg qd；肾衰或极低体重者建议换用 UFH 并监测抗 Xa","hepatic":"严重肝功能不全者出血风险增加，慎用","interact":"勿与其他抗凝药重叠过量；与 NSAIDs、SSRI 合用增加出血"},{"name":"磺达肝癸钠（fondaparinux）皮下","dose":"体重 <50 kg：5 mg qd；50–100 kg：7.5 mg qd；>100 kg：10 mg qd","note":"肝素诱导的血小板减少症（HIT）病史者可选用；肾清除依赖性强","renal":"CrCl <30 mL/min 禁用","hepatic":"严重肝病慎用","interact":"不与 UFH/LMWH 联用"},{"name":"利伐沙班（口服）","dose":"15 mg bid 口服 21 天，之后 20 mg qd 长期维持，可与食物同服","note":"单药方案，起始无需肝素重叠；不推荐作为高危（休克）患者的首选","renal":"CrCl 15–49 mL/min 维持 15 mg qd；CrCl <15 mL/min 不推荐","hepatic":"Child-Pugh B/C 或凝血障碍者禁用","interact":"强效 CYP3A4+P-gp 双抑制剂（酮康唑、利托那韦）禁用；与抗血小板药合用出血增加"},{"name":"阿哌沙班（口服）","dose":"10 mg bid 口服 7 天，之后 5 mg bid 维持；存在 ≥2 项减量因素（年龄 ≥80 岁、体重 ≤60 kg、肌酐 ≥133 µmol/L）时减量至 2.5 mg bid","note":"出血风险低于华法林，适合肿瘤与非肿瘤 VTE","renal":"CrCl <15 mL/min 或透析患者不推荐使用","hepatic":"Child-Pugh C 禁用","interact":"强效双抑制剂/诱导剂避免联用"},{"name":"华法林（口服）","dose":"起始 2.5–3 mg qd（老年人、消瘦、心衰者 1.5–2 mg），目标 INR 2.0–3.0；需与肝素重叠至少 5 天且 INR ≥2.0 连续 2 天方可停肝素","note":"抗磷脂综合征、机械瓣、严重肾功能不全者优选；起效慢，前 3–5 天需叠加肝素","renal":"肾功能不全者药效不稳定，INR 波动大","hepatic":"严重肝病禁用","interact":"与华法林相互作用药物极多（胺碘酮、唑类抗真菌药、喹诺酮、NSAIDs），需频繁监测 INR"},{"name":"阿替普酶（rt-PA）静脉溶栓","dose":"100 mg 于 2 小时内静脉泵入（中国急性 PE 诊疗指南方案）；或按体重 0.6 mg/kg 于 15 分钟内静推（最大 50 mg，低出血风险方案）","note":"仅用于高危 PE 或中高危出现血流动力学恶化；溶栓前确认无绝对禁忌（近期颅内出血、活动性内出血、近期颅脑手术）","renal":"无需按肾功能调整","hepatic":"严重肝病伴凝血障碍为相对禁忌","interact":"溶栓期间停用其他抗凝与抗血小板药，结束后复查 APTT 再恢复肝素"},{"name":"尿激酶（UK）静脉溶栓","dose":"20000 U/kg 于 2 小时内静脉滴注（最大 150 万 U），亦可经导管肺动脉内局部给药","note":"国内常用替代方案，价格低；需与最新版指南固定剂量方案核对","renal":"遵说明书","hepatic":"遵说明书","interact":"同阿替普酶"}],"nonDrug":["下腔静脉滤器：抗凝绝对禁忌或抗凝下仍反复复发的 PE，不推荐常规放置；放置后尽可能恢复抗凝","导管导向溶栓（CDT）或经导管机械碎栓：中高危或高危且溶栓禁忌/失败者的替代","外科肺动脉取栓：高危患者全身溶栓绝对禁忌或失败时的挽救治疗","体外膜肺氧合（ECMO）：高危 PE 伴顽固性休克或心脏骤停的桥接支持","疗程决策：一过性诱因（手术/制动）3 个月；特发性 VTE 至少 3 个月后评估延长抗凝；肿瘤相关与复发 VTE 建议延长（>3 个月或无限期）","基础疾病与诱因处理：下肢 DVT 同期评估、制动解除、停用口服避孕药"],"life":["抗凝期间避免剧烈接触性运动，剃须用电动剃须刀；观察皮下淤斑、黑便、血尿","华法林患者每 4 周复查 INR；DOAC 定期复查肾功能（至少每年，老年人更频）","术后/长途旅行（>6 小时）鼓励足踝活动、弹力袜或预防性抗凝","治疗后 3 个月及 6 个月复查超声心动图与症状评估，筛查 CTEPH","出血风险教育：合并抗血小板药、NSAIDs 时需医生评估"]},"prog":"规范抗凝后 30 天病死率约 5%–10%，高危组可达 15%–30%；约 50% 患者治疗后仍有活动后气促与运动耐量下降。复发风险在无诱因/肿瘤相关/既往复发者最高；急性 PE 后 2 年约 0.4%–4.6% 发展为 CTEPH，需长期随访。","refs":["中华医学会呼吸病学分会肺栓塞与肺血管病学组《肺血栓栓塞症诊治与预防指南》（2018）","中国医师协会呼吸医师分会《急性肺栓塞诊断与治疗中国专家共识》（2018）","ESC《2019 急性肺栓塞诊断与管理指南》","CHEST《静脉血栓栓塞症抗栓治疗指南（第 10 版）》（2021）","《中国血栓性疾病防治指南》（2022）"]},{"id":"pe_chronic","name":"慢性血栓栓塞性肺动脉高压","aka":["CTEPH","慢性血栓栓塞性肺高血压"],"rank":2,"basic":{"define":"急性 PE 后血栓未完全溶解、机化并阻塞肺血管，导致肺血管阻力持续升高与右心衰；定义为经 3 个月以上有效抗凝后，右心导管测得 mPAP ≥20 mmHg、PAWP ≤15 mmHg 且肺血管阻力升高，同时影像证实慢性血栓。","risk":["急性 PE 病史（尤其初次即伴肺动脉收缩压升高、大块血栓、残余血栓）","复发性、无诱因 DVT/PE；抗凝不充分或不规律","脾切除、脑室-心房分流、起搏器/中心静脉导管、骨髓增殖性肿瘤","抗磷脂综合征与易栓症、非 O 型血、甲状腺功能替代治疗","肥胖、糖尿病等代谢因素"],"epi":"急性 PE 后 2 年内 CTEPH 累积发生率约 0.4%–4.6%；我国肺高血压注册研究中 CTEPH 在肺动脉高压中占比约 40% 以上，是第 4 组肺高血压中最常见的一类。"},"patho":"残留血栓在 3–6 个月内逐渐机化、纤维化并收缩，形成网状、带状、附壁内衬样阻塞，累及主、叶、段级肺动脉。主要阻塞导致非阻塞区血管剪切力升高，诱发微血管病与类似 PAH 的远端小血管病变，形成“大血管阻塞 + 小血管重塑”双重阻力，最终右心泵衰竭。","dx":{"criteria":["临床前驱：有明确 VTE 史（约 25% 患者无明确急性 PE 病史），经 ≥3 个月规范抗凝后仍有进行性活动后气促、运动耐量下降。","右心导管（诊断金标准）：静息 mPAP ≥20 mmHg、PAWP ≤15 mmHg、肺血管阻力 >2 WU（部分共识 >3 WU）；第 4 组肺高血压需影像证实慢性血栓。","影像：V/Q 扫描示单发或多发、肺段/亚段性灌注缺损伴通气正常（不匹配），敏感性高于 CTPA；CTPA 示偏心性附壁血栓、网状/带状影、血管突然截断、支气管动脉扩张等机化征象。","功能分级：WHO 功能分级 II–IV 级；6 分钟步行距离、NT-proBNP 用于风险分层。"],"workup":["V/Q 扫描或 SPECT：筛查首选，阴性基本可排除 CTEPH","CTPA + 肺动脉造影：评估血栓可手术性（近端/远端）","右心导管 + 肺动脉造影：确诊与技术可操作性评估，为 BPA 术前必查","超声心动图：估测肺动脉收缩压、右室功能，排除左心或瓣膜病","肺功能与血气：多呈限制性/混合性通气障碍与弥散下降、低氧血症","易栓症筛查、肿瘤筛查；必要时评估合并的肺内动静脉分流"],"grading":"按梗阻部位分 Ⅰ 级（主肺动脉）、Ⅱ 级（叶级）、Ⅲ 级（段级）、Ⅳ 级（亚段及远端）——Ⅰ–Ⅱ 级适合 PEA 手术；按 WHO 功能分级 II–IV 评估病情；按治疗可行性分为可手术、不可手术但可 BPA、不可手术仅药物治疗三组。"},"ddx":[{"name":"急性肺栓塞","point":"与本类中急性 PE 的鉴别点：CTEPH 病程以月计、进行性加重，抗凝后症状不缓解；急性 PE 在数天内呼吸困难达高峰后缓解，影像为可消退的新鲜充盈缺损，D-二聚体显著升高，无慢性机化征象。"},{"name":"特发性肺动脉高压（PAH）","point":"同属肺高血压但无 VTE 史与慢性血栓影像；V/Q 扫描无灌注缺损，右心导管仅有小血管性阻力升高。"},{"name":"慢性阻塞性肺疾病","point":"吸烟史、慢性咳嗽咳痰、肺功能示 FEV1/FVC <0.70；CTEPH 患者肺功能多正常或有弥散障碍，V/Q 呈现不匹配缺损。"},{"name":"左心疾病相关肺高血压","point":"PAWP >15 mmHg，伴舒张功能减退或瓣膜病；CTEPH 的 PAWP ≤15 mmHg。"},{"name":"大动脉炎累及肺动脉","point":"年轻女性、炎症指标升高、全身动脉受累；影像示血管壁增厚而非腔内机化血栓。"}],"tx":{"drug":[{"name":"华法林（长期抗凝）","dose":"目标 INR 2.0–3.0，长期甚至终身使用","note":"所有 CTEPH 患者均需长期抗凝；不建议症状缓解后停用","renal":"遵说明书","hepatic":"严重肝病禁用","interact":"注意与利奥西呱等药物的相互作用"},{"name":"利伐沙班（替代抗凝）","dose":"20 mg qd（CrCl 15–49 mL/min：15 mg qd）","note":"可用于替代华法林，但抗磷脂综合征患者仍建议华法林","renal":"CrCl <15 mL/min 不推荐","hepatic":"Child-Pugh B/C 禁用","interact":"同 PTE；与利奥西呱联用无显著相互作用"},{"name":"利奥西呱（riociguat，sGC 激动剂）","dose":"起始 1 mg tid，按耐受每 2 周递增 0.5 mg，最大 2.5 mg tid；收缩压 <95 mmHg 或其他低血压风险者起始 0.5 mg tid","note":"唯一获批用于 CTEPH 的药物（CHEST-1 研究）；可与 BPA 联合","renal":"CrCl <15 mL/min 不推荐；重度肾损害慎用","hepatic":"Child-Pugh B/C 禁用","interact":"禁与 PDE5 抑制剂（西地那非、他达拉非）联用——可致严重低血压"},{"name":"马昔腾坦（macitentan，ERA）","dose":"10 mg qd 口服（起始 5 mg，部分患者以 5–10 mg 维持）","note":"CTEPH 中可作为联合治疗或利奥西呱不耐受时的选择；需监测肝功能","renal":"遵说明书","hepatic":"肝酶 >3 倍正常上限者停药；Child-Pugh C 不推荐","interact":"强效 CYP3A4 抑制剂慎用"},{"name":"曲前列尼尔（前列环素类似物）","dose":"皮下或静脉泵注，起始 1.25 ng/kg/min，按耐受每 1–4 周缓慢递增（遵说明书与专科经验）","note":"WHO 功能 IV 级患者桥接治疗或合并小血管病变者","renal":"遵说明书","hepatic":"Child-Pugh B/C 禁用（起始剂量需特别注意）","interact":"避免与强效 CYP2C8 抑制剂合用"}],"nonDrug":["肺动脉内膜剥脱术（PEA）：可手术 CTEPH 的首选治愈手段，适应证为近端（Ⅰ–Ⅱ 级）主干/叶级病变，术后 5 年生存率 >80%","球囊肺动脉成形术（BPA）：不可手术或 PEA 术后残余肺高血压，可多期分次进行；与利奥西呱联合时先药物后 BPA 更安全","长期氧疗：静息或活动后 SpO₂ ≤88% 者","肺移植：远端病变且药物/BPA 均无效的终末期患者","利尿剂（口服，按容积状态调整）、必要时正性肌力药；避免低血压","不推荐常规使用抗血小板药；推荐接种流感、肺炎球菌疫苗"],"life":["避免妊娠；育龄女性使用 ERA 类药物需双重避孕","避免高原暴露、长时间航空；必要时吸氧","定期复查：每 3–6 个月 6MWD、NT-proBNP、超声；治疗前后随访右心导管","参加肺高血压专病随访；运动康复训练可改善运动耐量","筛查与治疗铁缺乏（静脉补铁有助于改善运动耐量）"]},"prog":"未经治疗者中位生存期仅数年；可手术者 PEA 术后 5 年生存率约 80%–90%，不可手术者药物治疗 5 年生存率约 50%–60%。BPA 联合药物治疗可显著改善血流动力学与 6MWD，但残余肺高血压常见，需长期抗凝与定期随访。","refs":["中华医学会呼吸病学分会《慢性血栓栓塞性肺动脉高压诊断与治疗中国专家共识》（2022）","中国肺动脉高压诊断与治疗指南（2021）","ESC/ERS《2022 肺高血压诊断与治疗指南》","ERS 声明《慢性血栓栓塞性肺疾病与 CTEPH 的评估与管理》（2019）"]}]},{"id":"copd","name":"慢性气道疾病","rank":2,"summary":"涵盖 COPD（急性加重与稳定期）与哮喘（急性发作与长期管理），共同点是慢性气道阻塞与可逆性差异。首要步骤均为肺功能（FEV1/FVC 与支气管舒张试验）与诱因评估；COPD 以 LABA+LAMA 为基础、ICS 仅给有加重史 + 嗜酸性粒细胞升高者；哮喘以 ICS 为基石，急性发作用 SABA + 全身激素，控制期按阶梯方案调整。","compare":[{"diseaseId":"copd_ae","dx":"COPD 患者短期内呼吸困难、咳嗽/痰量加重超出日常，需调整治疗；常伴脓痰、低氧或高碳酸血症","key":"加重诱因多为感染；治疗 = SABA + 全身激素 + 必要时抗菌 + 无创通气；ICS 只在 eos ≥300 或有反复加重时长期使用"},{"diseaseId":"copd_stable","dx":"吸入支气管扩张剂后 FEV1/FVC <0.70，并进行性气流受限、慢性咳嗽咳痰或气促","key":"FEV1/FVC <0.70 固定气流受限；稳定期以 LABA+LAMA 长期维持 + 戒烟、肺康复、疫苗接种"},{"diseaseId":"asthma_ae","dx":"哮喘患者喘息、气促、胸闷、咳嗽急性加重，PEF 较个人最佳值下降 >20%，可伴低氧","key":"以气道痉挛为主，SABA 雾化或 pMDI + 全身激素为一线；危及生命者需 ICU 评估"},{"diseaseId":"asthma_ctrl","dx":"反复发作性喘息、气促、胸闷，可变气流受限（支气管舒张试验 FEV1 改善 ≥12% 且 ≥200 mL，或 PEF 变异率 >10%）","key":"可变、发作性、夜间多发 + 过敏史；ICS 为基础，按阶梯调整，避免单用 SABA"}],"diseases":[{"id":"copd_ae","name":"COPD 急性加重","aka":["AECOPD","慢性阻塞性肺疾病急性加重"],"rank":1,"basic":{"define":"慢性阻塞性肺疾病患者呼吸困难、咳嗽和（或）咳痰症状在短期内明显加重，超出日常变异范围，需要调整原有治疗方案。","risk":["呼吸道感染（病毒、细菌），约占加重诱因 70%–80%","空气污染、烟雾刺激、寒冷季节","用药依从性差、吸入技术错误或自行停用支气管扩张剂","合并症失控（心力衰竭、房颤、肺栓塞）、气胸、误吸","既往加重频繁（≥2 次/年）者再加重风险高"],"epi":"我国 40 岁以上人群 COPD 患病率约 13.6%，AECOPD 每年发生 1–3 次者常见；约 20%–30% 的住院 AECOPD 患者合并高碳酸血症需无创通气；住院病死率 3%–10%。"},"patho":"气道与肺泡黏膜炎症加重，黏液高分泌使痰液黏稠、纤毛清除功能下降，气道阻力进一步升高致呼气性气流受限加重与内源性 PEEP 增高；通气/血流失调与肺泡通气不足引起低氧血症伴（或）高碳酸血症。长期反复加重促进气道重塑与肺功能加速下降。","dx":{"criteria":["基础条件：既往确诊 COPD（吸入支气管扩张剂后 FEV1/FVC <0.70）。","症状加重符合 3 项主症中至少 2 项——呼吸困难加重、痰量增加、痰液变脓性，持续时间 ≤14 天。","严重度分级（中国 AECOPD 共识）：Ⅰ 级以 SABA 即能缓解；Ⅱ 级需 SABA + 全身激素和（或）抗菌药；Ⅲ 级伴呼吸衰竭、急性右心衰/水钠潴留或意识障碍。","重度加重的识别：呼吸困难 VAS ≥5 分、呼吸频率 ≥25 次/分、心率 ≥110 次/分、静息 SpO₂ <90%、使用辅助呼吸肌、急性意识改变或需呼吸机支持。"],"workup":["动脉血气（吸空气）：PaO₂ <60 mmHg 伴或不伴 PaCO₂ >50 mmHg 提示呼吸衰竭","胸片/CT：排除肺炎、气胸、肺栓塞、心力衰竭；常规 AECOPD 中约 5%–10% 合并气胸","血常规 + CRP + PCT：脓痰 + CRP/PCT 升高提示细菌感染，指导抗菌药使用","痰培养与药敏：脓痰、机械通气或近期住院/抗生素患者","心电图、肌钙蛋白/BNP：怀疑合并心梗、心衰或肺栓塞时","肺功能不常规于急性期进行，恢复 6–8 周后评估"],"grading":"Ⅰ 级（轻，SABA 可缓解）；Ⅱ 级（中，需抗菌药和/或激素）；Ⅲ 级（重，伴呼吸衰竭或右心衰）。伴急性意识障碍、严重呼吸性酸中毒（pH <7.25）或血流动力学不稳定者按 ICU 管理。"},"ddx":[{"name":"COPD 稳定期","point":"与本类中 COPD 稳定期的鉴别点：稳定期症状在个人日常变异范围内、无需调整治疗；若症状在 ≤14 天内显著加重并需抗生素、激素或急诊就诊，即进入急性加重。"},{"name":"哮喘急性发作","point":"与本类中哮喘急性发作的鉴别点：哮喘多自幼起病、有过敏史、气流受限可逆（支气管舒张试验阳性）、血嗜酸性粒细胞升高；AECOPD 多为中老年吸烟者、气流受限不可逆。"},{"name":"肺炎","point":"发热、湿啰音、影像新发实变；但 AECOPD 可合并肺炎，需胸片鉴别并影响抗菌药选择。"},{"name":"气胸","point":"突发一侧胸痛、呼吸困难显著加重，患侧呼吸音消失；老年 COPD 患者自发性气胸常见，需紧急胸片/超声。"},{"name":"心力衰竭","point":"端坐呼吸、下肢水肿、BNP 升高、双下肺湿啰音；COPD 患者合并心衰常见。"},{"name":"肺栓塞","point":"突发呼吸困难、低氧与右心负荷征象，D-二聚体升高，需 CTPA 鉴别。"}],"tx":{"drug":[{"name":"沙丁胺醇（SABA）雾化","dose":"2.5–5 mg 雾化吸入 q4–6h，必要时 q20min 连续 3 次；或 pMDI 100 µg/揿，4–8 揿 q1–4h（加储雾罐）","note":"急性期首选缓解支气管痉挛；pMDI + 储雾罐可替代雾化，疗效相当","renal":"无需调整","hepatic":"无需调整","interact":"与非选择性 β 受体阻滞剂合用减弱疗效；与利尿剂合用可低钾"},{"name":"异丙托溴铵（SAMA）雾化","dose":"0.5 mg 雾化 q6h，可与沙丁胺醇混合雾化","note":"联合 SABA 改善肺功能优于单药","renal":"重度肾损害者慎用（抗胆碱能效应蓄积）","hepatic":"遵说明书","interact":"与其他抗胆碱能药合用注意尿潴留、青光眼风险"},{"name":"甲泼尼龙琥珀酸钠","dose":"40 mg 静脉 qd（或 40 mg q12h）连用 5 天；口服泼尼松 30–40 mg qd 5 天为等效替代","note":"缩短恢复时间、改善氧合与 FEV1，疗程 5 天足够；延长无益","renal":"无需调整","hepatic":"严重肝病者需减量并监测","interact":"与氟喹诺酮合用增加肌腱断裂风险；注意血糖升高"},{"name":"阿莫西林/克拉维酸","dose":"875/125 mg 口服 bid；或 1.2 g 静滴 q8h","note":"用于脓痰 + CRP 升高或需机械通气者；常见病原为流感嗜血杆菌、肺炎链球菌、卡他莫拉菌","renal":"CrCl <30 mL/min 减量或延长给药间隔","hepatic":"有胆汁淤积型肝损伤史者慎用","interact":"与华法林合用可延长 INR"},{"name":"左氧氟沙星","dose":"500–750 mg 口服/静滴 qd","note":"有耐药风险或近期抗生素使用史者；避免用于 QT 延长者","renal":"CrCl <50 mL/min 减量（500 mg 改隔日或 250 mg qd）","hepatic":"重症肝损害慎用","interact":"避免与胺碘酮、西沙必利合用；与糖皮质激素合用增加肌腱断裂"},{"name":"布地奈德/福莫特罗（ICS/LABA）","dose":"160/4.5 µg 每吸，2 吸 bid；或 320/9 µg 1 吸 bid","note":"急性加重期间继续原维持吸入方案，勿停用；出院后可作为维持方案","renal":"无需调整","hepatic":"重度肝病时福莫特罗血药浓度升高，需监测","interact":"避免与非选择性 β 阻滞剂合用"}],"nonDrug":["控制性氧疗：目标 SpO₂ 88%–92%（COPD 保留低氧驱动），鼻导管或文丘里面罩","无创正压通气（NIV）：急性呼吸性酸中毒（pH ≤7.35 且 PaCO₂ >45 mmHg）或呼吸窘迫时的首选，可降低插管率与病死率","有创机械通气：NIV 失败、意识障碍、严重血流动力学不稳定、气道保护能力差","经鼻高流量氧疗（HFNC）：NIV 不耐受者的替代","肺康复：出院后 4 周内启动可减少再住院；出院前完成吸入器技术培训","戒烟支持、疫苗接种（流感、肺炎球菌、RSV、新冠）","痰液清除：祛痰药、气道廓清技术；严重者考虑支气管镜吸痰"],"life":["出院后 1–4 周内复诊，评估症状、吸入技术、氧疗与康复依从性","制定书面行动计划（症状恶化时如何加用 SABA、何时就诊）","家庭氧疗 ≥15 h/d 用于静息低氧患者；无创通气用于慢性高碳酸血症者","避免吸烟与空气污染、寒冷季节接种疫苗、适度运动"]},"prog":"住院 AECOPD 病死率约 3%–10%，需机械通气者可达 20%–30%；加重后肺功能与生活质量常恢复不完全，6 个月内再加重率约 30%–40%。反复加重者 FEV1 下降更快。","refs":["中华医学会呼吸病学分会慢性阻塞性肺疾病学组《慢性阻塞性肺疾病诊治指南（2021 年修订版）》","《慢性阻塞性肺疾病急性加重（AECOPD）诊治中国专家共识》（2017）","GOLD《慢性阻塞性肺疾病全球倡议报告》（2025）","ATS/ERS《COPD 急性加重管理临床实践指南》（2020）"]},{"id":"copd_stable","name":"COPD 稳定期","aka":["COPD","慢阻肺","慢性阻塞性肺疾病"],"rank":2,"basic":{"define":"以持续气流受限为特征的常见、可预防可治疗的慢性气道疾病，气流受限呈进行性发展；诊断需吸入支气管扩张剂后 FEV1/FVC <0.70。","risk":["吸烟（最重要危险因素）、二手烟","生物燃料烟雾、职业粉尘与化学物质暴露（矿山、纺织、焊接）","室内空气污染（通风不良、燃煤/柴草做饭取暖）","反复呼吸道感染、儿童期肺发育不良","α1-抗胰蛋白酶缺乏（少见，早发肺气肿）、哮喘-慢阻肺重叠"],"epi":"我国 40 岁以上人群患病率约 13.7%，60 岁以上超过 27%，估算患者近 1 亿；肺功能检查普及率不足 10%，诊断严重不足。"},"patho":"长期暴露于有害颗粒与气体引起气道与肺实质的慢性炎症，中性粒细胞、巨噬细胞与 CD8⁺ T 细胞浸润，氧化应激与蛋白酶-抗蛋白酶失衡导致小气道纤维化与狭窄、肺气肿性肺泡破坏。气道阻力增加与弹性回缩力下降引起呼气性气流受限与肺过度充气，运动时动态过度充气加重呼吸困难。","dx":{"criteria":["必需条件：吸入支气管扩张剂后 FEV1/FVC <0.70（金标准），并排除其他气流受限疾病。","症状：慢性咳嗽、咳痰、活动后气促（mMRC ≥1 或 CAT ≥10）；可有喘息、胸闷、体重下降。","危险因素暴露史（吸烟、粉尘、生物燃料），常伴反复急性加重史。","气流受限严重度（GOLD）：GOLD 1 轻度 FEV1 ≥80% 预计值；GOLD 2 中度 50%–79%；GOLD 3 重度 30%–49%；GOLD 4 极重度 <30%。","评估分组（ABE）：mMRC 0–1 且 CAT <10 为低症状；A 组（低症状、≤1 次中重度加重）；B 组（高症状、≤1 次加重）；E 组（≥2 次中重度加重或 ≥1 次住院）。"],"workup":["肺功能（支气管舒张试验）：确诊与分级必备，至少重复测量 3 次取最佳值","胸部 CT：评估肺气肿表型、支气管壁增厚、合并支气管扩张并排除肺癌","血嗜酸性粒细胞（eos）：eos ≥300 cells/µL 提示更可能从 ICS 获益","6 分钟步行试验、mMRC、CAT 评分","血气/脉搏血氧：FEV1 <50% 预计值或出现呼衰征象时","α1-抗胰蛋白酶检测：早发（<45 岁）、非吸烟者肺气肿、有家族史","心电图/心脏超声：评估合并心血管病与肺动脉高压"],"grading":"GOLD 气流受限分级 1–4（FEV1 占预计值百分比）；临床分组 A、B、E；mMRC 0–4 级；CAT 0–40 分。"},"ddx":[{"name":"COPD 急性加重","point":"与本类中 AECOPD 的鉴别点：稳定期症状平稳、无需调整用药；急性加重为 3 项主症在 ≤14 天内加重超日常变异、需改变治疗。"},{"name":"支气管哮喘","point":"与本类中哮喘长期管理的鉴别点：哮喘多为儿童/青年起病、过敏性与发作性喘息、气流受限可逆（FEV1 改善 ≥12% 且 ≥200 mL），eos 与 FeNO 升高；COPD 多为中老年吸烟者、不可逆气流受限。"},{"name":"支气管扩张症","point":"大量脓痰、反复咯血，HRCT 见“印戒征”、双轨征；可合并气流受限。"},{"name":"弥漫性泛细支气管炎","point":"慢性咳痰 + 活动后气促，CT 见小叶中心性结节与末梢气腔增大，常伴鼻窦炎。"},{"name":"慢性心力衰竭","point":"端坐呼吸、双肺底湿啰音、BNP 升高、左室射血分数降低；肺功能可呈混合性障碍。"},{"name":"尘肺/职业性肺病","point":"明确职业粉尘接触史，CT 见弥漫性结节/网格影；与肺气肿并存时需同时管理。"}],"tx":{"drug":[{"name":"噻托溴铵（LAMA）","dose":"18 µg 吸入 qd（HandiHaler）或 2.5 µg 2 吸 qd（Respimat）","note":"B/E 组首选支气管扩张剂；减少急性加重、改善生活质量；低症状 A 组可单药","renal":"重度肾功能不全（CrCl <30 mL/min）者慎用","hepatic":"无需调整","interact":"与其他抗胆碱能药合用注意尿潴留、青光眼"},{"name":"沙美特罗/氟替卡松（LABA/ICS）","dose":"50/250 µg 或 50/500 µg 每吸，1 吸 bid","note":"用于 eos ≥300 cells/µL 并反复加重者；ICS 不单独用于 COPD","renal":"无需调整","hepatic":"严重肝病时氟替卡松蓄积，需监测","interact":"强 CYP3A4 抑制剂（酮康唑、利托那韦）可升高氟替卡松暴露，增加库欣综合征风险"},{"name":"布地奈德/福莫特罗/格隆溴铵（三联）","dose":"5/160/18 µg 每吸，2 吸 bid（其他规格按说明书）","note":"E 组且 eos ≥300 或反复加重者的可选起始方案；三联较 LABA/LAMA 可减少严重急性加重","renal":"遵说明书","hepatic":"重度肝病需监测","interact":"避免与非选择性 β 阻滞剂合用"},{"name":"茚达特罗/格隆溴铵（LABA/LAMA）","dose":"110/50 µg 1 吸 qd（Breezhaler）","note":"B 组与 E 组（eos <300）的常用双支扩方案，减少急性加重","renal":"重度肾损害者慎用","hepatic":"重度肝损害者慎用","interact":"同 LAMA 与 LABA 类注意事项"},{"name":"沙丁胺醇（按需 SABA）","dose":"100 µg/揿，1–2 揿按需，不超过 8–12 揿/日","note":"仅作症状缓解；不建议长期单用 SABA 替代维持治疗","renal":"无需调整","hepatic":"无需调整","interact":"与 β 阻滞剂、利尿剂注意相互作用"},{"name":"罗氟司特（PDE4 抑制剂）","dose":"500 µg qd 口服（部分患者从 250 µg 起始，4 周后加量）","note":"用于 FEV1 <50%、慢性支气管炎表型且反复加重者；体重下降、腹泻为主要不良反应","renal":"CrCl <50 mL/min 减量至 250 µg qd","hepatic":"重度肝功能不全禁用","interact":"与强效 CYP3A4 诱导剂合用疗效降低"},{"name":"阿奇霉素（长期小剂量维持）","dose":"250 mg qd 或 500 mg 每周 3 次，12 个月后评估疗效","note":"仅用于规范治疗后仍反复加重的重度 COPD；需监测 QT 与听力","renal":"CrCl <30 mL/min 慎用或减量","hepatic":"严重肝病禁用","interact":"与胺碘酮、莫西沙星等合用延长 QT；可增加地高辛毒性"}],"nonDrug":["戒烟：任何阶段戒烟均延缓肺功能下降，是唯一最有效的干预","肺康复：每周 ≥2 次、共 6–12 周的运动训练与教育，改善 mMRC、CAT 与住院率","长期家庭氧疗：静息 PaO₂ ≤55 mmHg 或 SpO₂ ≤88%，或 PaO₂ 56–59 mmHg 伴肺心病/红细胞增多，>15 h/d","肺减容（外科或支气管镜活瓣/热蒸汽消融）：上叶为主肺气肿、过度充气显著、康复后运动耐量仍低者","肺移植：FEV1 <20%–25%、中重度高碳酸血症、反复加重且生活质量严重受损者","疫苗接种：流感、肺炎球菌、新冠、RSV（≥60 岁）"],"life":["每年至少 1–2 次随访并重复肺功能；eos 与加重频率变化后重新分组","吸入器使用技术培训与依从性评估（常见失败原因为技术错误）","避免冬季寒冷暴露与空气污染；家中通风；戒烟门诊随访","营养支持（BMI <21 建议增重）、肌肉力量训练、预防跌倒","筛查焦虑抑郁、骨质疏松；吸烟 ≥30 包年者低剂量 CT 筛查肺癌"]},"prog":"FEV1 年均下降约 30–60 mL（吸烟者更快）；规范吸入治疗与肺康复可减少急性加重、提高生活质量并可能延缓 FEV1 下降。合并肺动脉高压、频繁加重与肺癌是主要死亡风险。","refs":["中华医学会呼吸病学分会慢性阻塞性肺疾病学组《慢性阻塞性肺疾病诊治指南（2021 年修订版）》","《中国慢性阻塞性肺疾病基层诊疗与管理指南》（2024）","GOLD《慢性阻塞性肺疾病全球倡议报告》（2025）","ATS/ERS《COPD 吸入治疗管理临床实践指南》（2019/2020 更新）"]},{"id":"asthma_ae","name":"哮喘急性发作","aka":["Asthma exacerbation","哮喘急性加重"],"rank":3,"basic":{"define":"支气管哮喘患者喘息、气促、胸闷、咳嗽等原有症状急性加重、超出日常变异，需调整缓解药物或就医的临床状态；严重者可发展为哮喘持续状态并危及生命。","risk":["反复急性发作史（尤其近 1 年因哮喘住院或急诊）","未规律使用 ICS 或 ICS 用量不足、单用 SABA","呼吸道病毒感染（鼻病毒、流感）、过敏原暴露（花粉、尘螨、宠物）","阿司匹林/NSAIDs、β 受体阻滞剂、空气污染、吸烟","肥胖、过敏性鼻炎/鼻窦炎、胃食管反流、妊娠、焦虑抑郁"],"epi":"我国 20 岁及以上人群哮喘患病率约 4.2%，患者约 4570 万；约 40%–50% 患者每年至少发生一次急性发作，是哮喘经济负担的主要来源。"},"patho":"过敏性/非过敏性炎症驱动气道平滑肌收缩、黏膜水肿与黏液栓形成，导致气道阻力急剧升高与肺过度充气；严重时小气道几乎完全阻塞，产生急性低氧血症与高碳酸血症，伴呼吸肌疲劳。外周血嗜酸性粒细胞与 FeNO 升高提示 T2 型炎症。","dx":{"criteria":["已知诊断哮喘或符合哮喘诊断标准（典型发作性症状 + 可变气流受限证据）。","发作症状：气促、喘息、咳嗽、胸闷加重，夜间或凌晨显著；PEF 较个人最佳值或预计值下降 >20%。","严重度分级（GINA）：轻度至中度——能说整句、SpO₂ 90%–95%、PEF >50%；重度——只能说词组、端坐、呼吸频率 >30 次/分、辅助呼吸肌参与、心率 >120 次/分、SpO₂ <90%、PEF ≤50%；危及生命——嗜睡/意识模糊、沉默胸、发组、PEF <33%。","哮喘持续状态：严重发作对初始 SABA 与激素治疗无反应、出现高碳酸血症（PaCO₂ 正常或升高）或呼吸肌疲劳者，需转入 ICU。"],"workup":["脉搏血氧饱和度：连续监测，发作期间目标 SpO₂ 93%–95%","PEF（若可行）：PEF <50% 预计值提示重度发作","动脉/静脉血气：发作持续或重度者，PaCO₂ 正常或升高为危险信号","胸片：怀疑气胸、肺炎或低氧与临床表现不匹配时；不常规","血嗜酸性粒细胞、FeNO：评估 T2 炎症与生物制剂适用性","心电图：β2 激动剂可致窦性心动过速、低钾与 QT 改变"],"grading":"GINA 严重度：轻度至中度 / 重度 / 危及生命；ICU 收治标准：意识改变、呼吸肌疲劳、沉默胸、PEF <33%、需机械通气。"},"ddx":[{"name":"COPD 急性加重","point":"与本类中 AECOPD 的鉴别点：COPD 患者多有长期吸烟史与不可逆气流受限，加重诱因多为感染、脓痰与发热更常见、对 SABA 反应较慢；哮喘患者多有过敏史、发作性与可逆气流受限。"},{"name":"哮喘长期管理（慢性持续期）","point":"与本类中哮喘长期管理的鉴别点：慢性持续期症状集中于夜间或运动后、可通过 ICS 维持治疗达标；急性发作是症状超出日常变异、需急诊处理的急性事件。"},{"name":"上气道功能障碍/声带功能障碍","point":"吸气性喘鸣、发声与呼吸困难不匹配，SpO₂ 多正常，支气管舒张剂无效；可通过激发试验与喉镜鉴别。"},{"name":"异物吸入","point":"突发呛咳、单侧呼吸音减低、呼出气不对称；儿童更常见，影像与支气管镜可确诊。"},{"name":"急性左心衰竭","point":"端坐呼吸、咳粉红色泡沫痰、双肺弥漫湿啰音、BNP 显著升高；β2 激动剂疗效差。"},{"name":"自发性气胸","point":"突发一侧胸痛伴呼吸困难，患侧呼吸音消失、叩诊鼓音；哮喘治疗后不缓解时需排查。"}],"tx":{"drug":[{"name":"沙丁胺醇（SABA）雾化","dose":"2.5–5 mg 雾化，q20min 连续 3 次，之后按需 q1–4h；或 pMDI 100 µg/揿，4–10 揿每 20 分钟 1 次（加储雾罐）","note":"一线缓解药物；重度发作可持续雾化，但需注意震颤、心动过速与低钾","renal":"无需调整","hepatic":"无需调整","interact":"与利尿剂合用加重低钾；与糖皮质激素合用轻度低钾"},{"name":"异丙托溴铵（SAMA）雾化","dose":"0.5 mg 雾化 q4–6h，可与沙丁胺醇混合","note":"中重度发作联合 SABA 可进一步改善肺功能、减少住院","renal":"重度肾损害慎用","hepatic":"遵说明书","interact":"与 SABA 联用为常用组合"},{"name":"全身糖皮质激素——泼尼松口服","dose":"40–50 mg qd（或接体重 0.5–1 mg/kg，最大 40–50 mg）连用 5–7 天，无需逐渐减量","note":"中重度发作均应尽早使用；口服与静脉等效，能口服者优先口服","renal":"无需调整","hepatic":"无需调整（严重肝功能不全者改用静脉）","interact":"监测血糖与血压；与氟喹诺酮合用增加肌腱病变风险"},{"name":"甲泼尼龙琥珀酸钠静脉","dose":"40–80 mg 静脉 qd–q12h，疗程 5–7 天","note":"用于不能口服、重度或危及生命发作；无证据支持超大剂量激素","renal":"无需调整","hepatic":"遵说明书","interact":"同全身激素"},{"name":"硫酸镁静脉（辅助）","dose":"2 g 静脉滴注 20–30 分钟（部分方案 1.2–2 g/h 泵入）","note":"用于 SABA 与激素初始治疗无反应的重度发作","renal":"CrCl <30 mL/min 者减量并监测血镁与反射","hepatic":"遵说明书","interact":"避免与其他神经肌肉阻滞剂合用"},{"name":"肾上腺素皮下/肌注","dose":"0.3–0.5 mg（1:1000）皮下或肌注，必要时 20 分钟后重复","note":"用于危及生命或合并过敏性休克的发作；老年人、冠心病者慎用","renal":"无需调整","hepatic":"无需调整","interact":"与 β 阻滞剂合用可致血压升高与支气管痉挛加重"},{"name":"布地奈德/福莫特罗（稳定后维持）","dose":"160/4.5 µg 每吸，1–2 吸 bid","note":"急诊出院后继续 ICS 维持，避免单用 SABA；出院时评估并调整长期方案","renal":"无需调整","hepatic":"重度肝病时需监测","interact":"参见 ICS/LABA 注意事项"}],"nonDrug":["氧疗：目标 SpO₂ 93%–95%（儿童 94%–98%）","无创通气（NIV）用于意识不受影响、呼吸窘迫的重度发作；有创机械通气用于意识障碍、沉默胸、PaCO₂ 进行性升高，需低呼吸频率、长呼气时间并注意动态过度充气","避免常规全身镇静与胸部理疗","危及生命发作转入 ICU，必要时评估 ECMO","出院前：吸入技术再培训、书面行动计划、1–2 周内随访、评估是否需升级长期控制药","识别并避免诱因（病毒感染、过敏原、NSAIDs、β 阻滞剂）"],"life":["出院后 1 周内复诊，评估 SABA 使用次数与夜间症状","禁用单用 SABA；规律使用含 ICS 的药物","哮喘行动计划：按 PEF 或症状分区处理，症状加重时及时用急救药并就诊","接种流感与肺炎球菌疫苗；妊娠期需继续维持治疗而非停药","吸烟患者戒烟，肥胖患者减重"]},"prog":"多数急性发作在 1–2 周内缓解；约 10%–20% 的住院患者复发，重度发作者再次发作风险高。含 ICS 的规范治疗可显著减少再住院与病死率；未规律使用 ICS 是致死性哮喘的重要危险因素。","refs":["中华医学会呼吸病学分会哮喘学组《支气管哮喘防治指南（2020 年版）》","《支气管哮喘急性发作评估及处理中国专家共识》（2018）","《中国哮喘患者管理指南》（2023）","GINA《哮喘全球防治与预防策略》（2025）"]},{"id":"asthma_ctrl","name":"哮喘长期管理","aka":["Asthma long-term management","慢性持续期哮喘","控制期哮喘"],"rank":4,"basic":{"define":"对已确诊哮喘、处于非急性发作期患者的长期药物治疗与随访评估，目标为达到并维持症状控制、减少未来急性发作风险与改善生活质量。","risk":["过敏性疾病合并（过敏性鼻炎、湿疹、食物过敏）、家族过敏史","吸烟、肥胖、缺乏运动","阿司匹林/NSAIDs 不耐受、职业性过敏原","未规律 ICS、吸入技术错误、依从性差","心理压力、焦虑抑郁、社会经济因素"],"epi":"我国 20 岁以上人群中有 4570 万哮喘患者，但达到症状控制者不足 20%；儿童患病率约 7.7%，控制率同样偏低。"},"patho":"慢性气道炎症（以 T2 型嗜酸性粒细胞炎症为主）导致气道高反应性与可逆性气流受限；长期控制不佳可引起气道重塑、不可逆气流受限与气道狭窄。ICS 可抑制炎症、降低气道高反应性与急性发作风险，是长期治疗的基石。","dx":{"criteria":["反复发作性喘息、气促、胸闷和/或咳嗽，常与接触过敏原、冷空气、运动或病毒相关，夜间或清晨加重。","可变气流受限证据之一：支气管舒张试验阳性（吸入 SABA 后 FEV1 增加 ≥12% 且 ≥200 mL）；PEF 平均日变异率 >10%–15%；支气管激发试验阳性；或 4 周内 FEV1 改善 ≥12% 且 ≥200 mL。","控制水平评估（过去 4 周）：日间症状 ≤2 次/周、夜间不醒、SABA 使用 ≤2 次/周、无活动受限，四项均无＝完全控制；1–2 项＝部分控制；3–4 项＝未控制。","未来风险因素：≥1 次/年的中重度急性发作、FEV1 低、SABA 过度使用、吸烟、eos 高、无 ICS 处方。"],"workup":["肺功能 + 支气管舒张试验：每 2–4 个月复查，评估控制与治疗反应","PEF 日记：早晚各测，计算日间/周间变异率","血嗜酸性粒细胞、总 IgE、FeNO：评估 T2 炎症、指导 ICS 剂量与生物制剂","过敏原皮肤点刺或特异性 IgE：识别可避免诱因","ACT（哮喘控制测试）或 ACQ：门诊定量评估控制","胸片或 CT：排除其他疾病，必要时评估气道重塑或变应性支气管肺曲霉病"],"grading":"GINA/中国指南阶梯治疗 1–5 级：按需低剂量 ICS-福莫特罗、低剂量 ICS 维持、低剂量 ICS-LABA、中/高剂量 ICS-LABA + LAMA/生物制剂；控制水平完全/部分/未控制。"},"ddx":[{"name":"COPD 稳定期","point":"与本类中 COPD 稳定期的鉴别点：COPD 以吸烟与长期暴露为主、气流受限不可逆、肺气肿影像学改变；哮喘常有过敏史、可逆气流受限、对 ICS 反应好。"},{"name":"哮喘急性发作","point":"与本类中哮喘急性发作的鉴别点：急性发作是症状超出日常变异、需强化缓解药与全身激素的事件；长期管理针对非发作期的维持治疗与达标评估。"},{"name":"过敏性肺炎","point":"职业/环境暴露后出现发热、干咳、气促与弥散功能显著下降，CT 见磨玻璃影，脱离暴露后改善。"},{"name":"变应性支气管肺曲霉病（ABPA）","point":"总 IgE >1000 IU/mL、烟曲霉特异性 IgE 阳性、CT 见中心性支气管扩张伴痰栓，需激素 + 抗真菌治疗。"},{"name":"嗜酸性肉芽肿性多血管炎（EGPA）","point":"哮喘病史 + 鼻息肉/皮疹/周围神经病变 + eos >1.5×10⁹/L，ANCA 可阳性，易与重度哮喘混淆。"},{"name":"气管支气管软化","point":"慢性刺激性干咳，肺功能流量-容积环呈截断样改变；支气管镜或动态 CT 可诊断。"}],"tx":{"drug":[{"name":"布地奈德/福莫特罗（按需或 MART）","dose":"160/4.5 µg 每吸：Step 1–2 按需 1 吸；Step 3–4 MART 维持 1–2 吸 bid，另按需每次 1 吸（每日总量 ≤12 吸）；Step 5 维持 2 吸 bid 起","note":"GINA Track 1 首选；减少依赖单用 SABA；急性发作时可用于缓解但不取代全身激素","renal":"无需调整","hepatic":"重度肝病需监测","interact":"避免与非选择性 β 阻滞剂合用"},{"name":"沙美特罗/氟替卡松（ICS/LABA）","dose":"50/100 µg、50/250 µg 或 50/500 µg，1 吸 bid（Step 3–4）；重症哮喘可用至 2 吸 bid","note":"GINA Track 2（维持 ICS + 按需 SABA）；Step 5 可用 500 µg 规格","renal":"无需调整","hepatic":"重度肝病时氟替卡松暴露升高","interact":"强效 CYP3A4 抑制剂可增加系统性糖皮质激素暴露"},{"name":"孟鲁司特（白三烯受体拮抗剂）","dose":"10 mg qd 口服（成人）；6–14 岁 5 mg；2–5 岁 4 mg","note":"作为附加治疗减少轻中度发作；须告知神经精神不良反应（黑框警告）","renal":"无需调整","hepatic":"中重度肝病者慎用","interact":"与 CYP2C8 抑制剂（吉非贝齐）合用可升高暴露"},{"name":"噻托溴铵（LAMA，附加治疗）","dose":"2.5 µg 2 吸 qd（Respimat）或 18 µg qd（HandiHaler）","note":"Step 4–5 未控制者加用，可减少急性发作","renal":"CrCl <30 mL/min 慎用","hepatic":"无需调整","interact":"与其他抗胆碱能药合用注意尿潴留、青光眼"},{"name":"美泊利珠单抗（抗 IL-5，生物制剂）","dose":"100 mg 皮下 q4w（部分表型 300 mg q4w，遵产品说明书与适应证）","note":"用于 eos ≥150–300 cells/µL、重度嗜酸性哮喘且高剂量 ICS-LABA 仍发作；需专科评估","renal":"无需调整","hepatic":"遵说明书","interact":"无需特别注意"},{"name":"奥马珠单抗（抗 IgE）","dose":"按体重与总 IgE 计算，每 2 周或 4 周皮下注射（150–600 mg/次），剂量遵说明书","note":"用于中重度过敏性哮喘、总 IgE 与体重在适用范围内；需在注射后观察","renal":"无需调整","hepatic":"无需调整","interact":"无显著 CYP 相互作用"},{"name":"沙丁胺醇（按需缓解药）","dose":"100 µg/揿，1–2 揿按需；SABA 使用 >2 次/周提示控制不佳，应升级治疗","note":"不推荐单用 SABA；GINA 推荐低剂量 ICS 作为任何 SABA 使用者的基础","renal":"无需调整","hepatic":"无需调整","interact":"同 SABA"}],"nonDrug":["阶梯治疗：Step 1 低剂量 ICS 按需/规律；Step 2 低剂量 ICS；Step 3 低剂量 ICS-LABA（或中剂量 ICS）；Step 4 中/高剂量 ICS-LABA + LAMA/白三烯受体拮抗剂；Step 5 生物制剂、口服激素或支气管热成形术","降阶梯：达到控制 ≥3 个月后，先降剂量、再降频率，不可贸然停用 ICS","支气管热成形术：重度哮喘、规范药物仍控制不佳者","避免诱因：尘螨控制、宠物与花粉回避、戒烟、疫苗接种","管理合并症：过敏性鼻炎（鼻用激素 + 抗组胺）、肥胖、胃食管反流、OSAHS"],"life":["每 1–3 个月评估控制（ACT/ACQ），稳定后 3–6 个月复诊","每次就诊检查吸入技术并复述行动计划","运动可正常进行，运动前必要时热身或用 SABA 预防","妊娠：持续使用 ICS，哮喘未控制对胎儿风险高于药物","儿童与家长教育、学校哮喘行动计划；成年后定期肺功能"]},"prog":"以 ICS 为基础的阶梯治疗可使 60%–80% 患者达到良好控制并显著降低急性发作与死亡风险；未控制者气道重塑加速，FEV1 进行性下降；重度哮喘占比约 5%–10%，但消耗 50% 以上医疗资源。","refs":["中华医学会呼吸病学分会哮喘学组《支气管哮喘防治指南（2020 年版）》","《中国哮喘患者管理指南》（2023）","《支气管哮喘长期管理中国专家共识》（2022）","GINA《哮喘全球防治与预防策略》（2025）"]}]},{"id":"pneumonia","name":"肺炎","rank":3,"summary":"肺炎按获得场所分社区获得性（CAP）与医院获得性（HAP，含呼吸机相关肺炎 VAP）；诊断需临床感染征象 + 新发肺部实变影像。CAP 以 CURB-65/PSI 决定诊疗场所，HAP/VAP 关注多重耐药菌（MDR）风险并初始足量覆盖、48–72 小时降阶梯。肺炎链球菌是 CAP 首位病原，HAP 以铜绿假单胞菌、鲍曼不动杆菌与肺炎克雷伯菌为主。","compare":[{"diseaseId":"cap_comm","dx":"社区发病，发热/咳脓痰/胸痛 + 肺部湿啰音或实变体征，影像见新发浸润影；按 CURB-65 分层","key":"入院 48 小时内送血培养 + 痰培养，β-内酰胺 + 大环内酯/喹诺酮；CURB-65 ≥2 需住院"},{"diseaseId":"hap","dx":"入院 ≥48 小时后或出院后 90 天内新发肺炎；气管插管 ≥48 小时后发生的肺炎为 VAP","key":"耐药风险高，需覆盖铜绿假单胞菌、不动杆菌与 MRSA 高危者；按影像 + 下呼吸道标本培养指导降阶梯"}],"diseases":[{"id":"cap_comm","name":"社区获得性肺炎","aka":["CAP","Community-acquired pneumonia"],"rank":1,"basic":{"define":"在医院外罹患的感染性肺实质（含肺泡壁，即广义上的肺间质）炎症，包括具有明确潜伏期的病原体感染而在入院后于潜伏期内发病的肺炎。","risk":["年龄 ≥65 岁、婴幼儿与老年人","慢性基础病：COPD、支气管扩张、糖尿病、心衰、慢性肝/肾病","吸烟、酗酒、营养不良与吞咽障碍（误吸风险）","免疫抑制（激素、化疗、器官移植、HIV）","近期流感/新冠感染、集体居住（养老院、监狱）"],"epi":"我国 CAP 成人年发病率约 7.5–11.7/1000，≥65 岁人群可 >30/1000；是老年人与婴幼儿的主要感染性死因之一。"},"patho":"病原体经呼吸道吸入（肺炎链球菌、流感嗜血杆菌、肺炎支原体）或误吸（厌氧菌），或经血行播散至肺泡，触发肺泡巨噬细胞与中性粒细胞的炎症反应，肺泡充满炎性渗出物导致肺实变；肺内分流与通气/血流失调产生低氧血症。典型肺炎链球菌肺炎呈大叶实变，支原体肺炎以支气管周围间质炎症为主。","dx":{"criteria":["社区发病，具备以下新近出现的咳嗽、咳痰或原有呼吸道症状加重，伴或不伴脓痰、胸痛、呼吸困难、咯血。","发热（部分老年/免疫抑制者可不发热）。","肺实变体征和（或）闻及湿性啰音。","外周血 WBC >10×10⁹/L 或 <4×10⁹/L，伴或不伴核左移。","胸部 X 线或 CT 示新发的斑片状浸润影、叶或段实变影、间质性改变，伴或不伴胸腔积液。","诊断成立：第 1–4 项中任一项 + 第 5 项，并排除肺结核、肺部肿瘤、肺栓塞、肺不张等。","严重度分层：CURB-65（意识障碍、尿素氮 >7 mmol/L、呼吸频率 ≥30 次/分、收缩压 <90 mmHg 或舒张压 ≤60 mmHg、年龄 ≥65 岁，每项 1 分）——0–1 分门诊、2 分住院、≥3 分考虑 ICU；PSI 评分Ⅰ–Ⅱ 级门诊、Ⅳ–Ⅴ 级住院。"],"workup":["胸片/CT：诊断基础，24–48 小时复查判断疗效；CT 对早期与间质型肺炎更敏感","血常规、CRP、PCT：炎症与细菌感染评估、指导抗生素停用","合格痰涂片革兰染色 + 痰培养：ICU、抗生素无效或有耐药风险者","住院患者：血培养 ≥2 套（尤其重症或计划针对 MRSA/假单胞菌治疗）、支原体/衣原体抗体、军团菌尿抗原","血氧饱和度/血气：判断低氧、呼吸衰竭与是否需要 ICU","流感/新冠等病毒快速检测：流行季节","胸腔积液：超声评估并穿刺行常规、生化、培养、ADA（排除结核）"],"grading":"按诊疗场所：门诊（CURB-65 0–1）、普通病房（CURB-65 2）、ICU（CURB-65 ≥3、需机械通气或脓毒性休克）；重症 CAP：需有创通气、需血管活性药的脓毒性休克，或符合 3 项次要标准。"},"ddx":[{"name":"医院获得性肺炎","point":"与本类中 HAP 的鉴别点：CAP 为社区发病、病原以肺炎链球菌、支原体、流感嗜血杆菌为主；HAP 为入院 ≥48 小时后发生，病原以革兰阴性杆菌与 MRSA 为主、耐药风险高，初始经验治疗需覆盖 MDR。"},{"name":"肺结核","point":"亚急性/慢性病程，低热盗汗消瘦，CT 见上叶尖后段/下叶背段空洞、树芽征与卫星灶；痰抗酸染色、结核分枝杆菌核酸、IGRA 阳性。"},{"name":"肺栓塞","point":"突发呼吸困难与胸痛，D-二聚体升高，CTPA 见充盈缺损；PE 可伴肺梗死性肺炎。"},{"name":"肺癌伴阻塞性肺炎","point":"反复同一部位肺炎、抗生素后影像不吸收，CT 见支气管截断或占位；需支气管镜与穿刺活检。"},{"name":"心力衰竭","point":"端坐呼吸、双肺底湿啰音、BNP 升高、心影增大，利尿后肺部改变迅速吸收。"},{"name":"支气管扩张症伴感染","point":"反复咳大量脓痰，HRCT 见柱状/囊状支气管扩张；与肺炎共存时需长期气道管理。"}],"tx":{"drug":[{"name":"阿莫西林（门诊轻症）","dose":"0.5–1 g 口服 tid（日剂量 1.5–4 g）；或阿莫西林/克拉维酸 625 mg tid","note":"门诊无基础病、轻症患者可选；肺炎链球菌耐药率高的地区需联合","renal":"CrCl <30 mL/min 减量或延长给药间隔","hepatic":"轻中度无需调整；严重肝病慎用","interact":"与别嘌醇合用皮疹增加；与华法林合用可延长 INR"},{"name":"头孢曲松（普通病房）","dose":"1–2 g 静滴 qd","note":"覆盖肺炎链球菌、流感嗜血杆菌与多数肠杆菌，对非典型病原无效；国内指南推荐与阿奇霉素或莫西沙星联合","renal":"一般无需调整","hepatic":"无需调整","interact":"与含钙溶液不可同瓶滴注（新生儿）"},{"name":"阿奇霉素（联合方案）","dose":"0.5 g 静脉/口服 qd（首日可加倍，疗程 3–5 天）","note":"覆盖肺炎支原体、衣原体、军团菌；大环内酯耐药肺炎支原体在我国常见，疗效不佳时需换药","renal":"CrCl <30 mL/min 慎用或减量","hepatic":"严重肝功能不全者禁用/慎用","interact":"与胺碘酮、氟喹诺酮合用延长 QT；与华法林合用增加出血"},{"name":"莫西沙星（单药或联合）","dose":"0.4 g 静滴/口服 qd","note":"覆盖肺炎链球菌与非典型病原的单药方案（门诊与住院均可用）；不建议用于 QT 延长或重症肌无力者","renal":"肾功能不全无需调整","hepatic":"Child-Pugh C 慎用；肝毒性罕见但需警惕","interact":"禁与胺碘酮、索他洛尔、西沙必利合用；与糖皮质激素合用增加肌腱断裂"},{"name":"哌拉西林/他唑巴坦（重症/耐药风险）","dose":"4.5 g 静滴 q8h（延长输注可 q6h）","note":"重症 CAP 或有铜绿假单胞菌风险者的 β-内酰胺选择，常联合氟喹诺酮/大环内酯","renal":"CrCl 20–40 mL/min 4.5 g q8h；CrCl <20 mL/min 2.25 g q8h","hepatic":"无需调整","interact":"与万古霉素合用增加急性肾损伤风险"},{"name":"奥司他韦（流感并发肺炎）","dose":"75 mg 口服 bid，疗程 5 天（重症可延长）","note":"流行季节疑似/确诊流感者尽早使用，重症住院患者不受 48 小时限制","renal":"CrCl 30–60 mL/min 30 mg bid；CrCl 10–30 mL/min 30 mg qd；透析遵说明书","hepatic":"无需调整","interact":"与减毒活疫苗同期不推荐"}],"nonDrug":["氧疗与呼吸支持：SpO₂ 目标 ≥90%（COPD 患者 88%–92%）；必要时 HFNC/无创通气/有创通气","液体复苏：脓毒性休克者按 30 mL/kg 晶体液起始并动态评估","胸腔积液引流：中大量积液或脓胸需置管引流","抗生素疗程：一般 5–7 天，重症或并发症延长；临床稳定 + PCT 下降后停药","48–72 小时评估疗效：无改善需复查影像、病原学与评估并发症（脓胸、肺脓肿）","疫苗接种（肺炎球菌、流感、新冠）用于 ≥65 岁及高危人群"],"life":["戒烟；治疗基础病（糖尿病血糖控制、心衰管理）","出院 1–2 周复诊，4–6 周复查胸片确认吸收（尤其吸烟、>50 岁男性）","卧床期间早期活动、防误吸（进食体位、吞咽评估）","老年人、COPD 患者每年接种流感疫苗并按程序接种肺炎球菌疫苗"]},"prog":"门诊 CAP 病死率 <1%，普通病房约 5%–10%，ICU 可达 20%–30%；48–72 小时无改善提示耐药、非感染性病因或并发症。老年人与有基础病者恢复较慢，部分出现持续肺部炎症与功能下降。","refs":["中华医学会呼吸病学分会《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国成人社区获得性肺炎基层诊疗指南》（2019）","IDSA/ATS《成人社区获得性肺炎诊治临床实践指南》（2019）","《国家抗微生物治疗指南（第 3 版）》（2022）"]},{"id":"hap","name":"医院获得性肺炎","aka":["HAP","Hospital-acquired pneumonia","VAP（呼吸机相关肺炎）"],"rank":2,"basic":{"define":"患者入院时不存在、也不处于感染潜伏期，而于入院 ≥48 小时后在医院（包括老年护理院、康复院）内发生的肺炎；气管插管或气管切开患者于拔管后 48 小时内发生的肺炎为呼吸机相关肺炎（VAP）。","risk":["机械通气与人工气道（VAP 风险约 1%–2.5%/日通气）","意识障碍、吞咽障碍与误吸、胃管留置、仰卧位","近期广谱抗生素使用（尤其 ≥90 天）、免疫抑制、ICU 住院时间长","手术（尤其胸腹部）、镇静剂使用、COPD、糖尿病、慢性肾病","医院环境因素：多重耐药菌定植、手卫生依从性低、呼吸机管路污染"],"epi":"HAP 是医院获得性感染的首位之一，VAP 在机械通气患者中发生率约 5%–15%；我国 ICU 中 VAP 病原以鲍曼不动杆菌、铜绿假单胞菌与肺炎克雷伯菌为主，耐药率高，病死率可达 20%–40%。"},"patho":"口咽部与胃肠道革兰阴性杆菌定植、误吸（尤其仰卧与镇静状态）是主要机制；气管插管绕过上气道防御，生物膜在导管表面形成并反复种植到下呼吸道。宿主防御受损（机械通气损伤、营养不良、免疫抑制）与生物膜共同导致持续感染与耐药菌选择。","dx":{"criteria":["入院 ≥48 小时后（或出院后 90 天内）新发肺炎；VAP 为气管插管/切开并机械通气 ≥48 小时后发生。","临床征象：发热 ≥38 ℃、脓性气道分泌物、肺部湿啰音/实变体征、白细胞增多或减少、氧合恶化。","影像学：新发或进展性肺部浸润影（需排除肺不张、肺水肿、肺栓塞、ARDS 等其他病因）。","临床肺部感染评分（CPIS）：体温、白细胞、分泌物、氧合、胸片、气管吸出物培养，>6 分提示肺炎；敏感性有限，需结合临床。","定义区分：HAP 不含机械通气患者；VAP 为插管 ≥48 小时后发生；拔管后 48 小时内发生者称拔管后肺炎。"],"workup":["胸部 CT/床旁胸片：判断浸润影与并发症（实变、胸腔积液、肺脓肿）","气管吸出物/支气管肺泡灌洗（BAL）定量培养：BAL ≥10⁴ CFU/mL、保护性标本刷 ≥10³ CFU/mL 有助鉴别定植","血培养 2 套、胸腔积液培养；必要时军团菌/病毒检测","血常规、CRP、PCT、血气与乳酸：评估严重度与治疗反应","耐药风险筛查：近期住院与抗生素暴露、MRSA/铜绿假单胞菌定植史、当地 ICU 耐药流行病学","胸部超声：评估胸腔积液与肺实变，可引导穿刺"],"grading":"按发生时间分早发型（≤4–5 天，多为敏感菌）与晚发型（>5 天，MDR 风险高）；MDR 危险因素：前 90 天静脉抗生素、住院 ≥5 天、脓毒性休克、ARDS、急性肾替代治疗、当地耐药高发。严重度按是否需机械通气、休克与多器官衰竭评估。"},"ddx":[{"name":"社区获得性肺炎","point":"与本类中 CAP 的鉴别点：HAP 发生于入院 ≥48 小时后、病原以革兰阴性杆菌与 MRSA 为主、需覆盖耐药菌；CAP 病原较“社区化”，经验用药偏窄。"},{"name":"肺不张","point":"术后或长期卧床出现低通气与肺部浸润影，影像见肺容积缩小、叶间裂移位；通过吸痰、体位引流、支气管镜可迅速改善。"},{"name":"肺水肿/急性呼吸窘迫综合征","point":"弥漫双肺磨玻璃影、BNP 升高或符合 ARDS 柏林标准（P/F ≤300 且 PEEP ≥5 cmH₂O）；HAP 可合并 ARDS，需同时处理。"},{"name":"肺栓塞","point":"血流动力学不稳定、D-二聚体升高、右心扩大；卧床/术后患者需 CTPA 排查。"},{"name":"侵袭性肺曲霉病","point":"免疫抑制患者（粒细胞缺乏、长期激素、移植后），CT 见晕轮征或空气新月征；需 GM/G 试验与抗真菌治疗。"},{"name":"脓胸/纵隔感染","point":"持续发热、胸腔积液脓性、胸膜增厚；需胸腔穿刺/引流，不能仅靠抗生素。"}],"tx":{"drug":[{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静滴 q6h–q8h（延长输注 3–4 小时）","note":"HAP/VAP 基础 β-内酰胺，覆盖铜绿假单胞菌与多数肠杆菌；需根据当地药敏与剂量优化","renal":"CrCl 20–40 mL/min 4.5 g q8h；CrCl <20 mL/min 2.25 g q8h","hepatic":"无需调整","interact":"与万古霉素合用增加 AKI；与丙磺舒合用升高血药浓度"},{"name":"头孢哌酮/舒巴坦","dose":"2 g 静滴 q8h（严重感染可 3 g q8h）","note":"国内 MDR 鲍曼不动杆菌常用方案，需联合其他药物；舒巴坦对不动杆菌有活性","renal":"CrCl <30 mL/min 需减量","hepatic":"凝血功能障碍者监测维生素 K；肝功能不全需调整","interact":"与华法林合用增加出血；饮酒后使用可致双硫仑样反应"},{"name":"美罗培南（碳青霉烯）","dose":"1 g 静滴 q8h（重症/耐药菌可 2 g q8h，延长输注 3 小时）","note":"MDR 肠杆菌或产 ESBL 菌的优选；结合血药浓度监测（TDM）优化","renal":"CrCl 25–50 mL/min 1 g q12h；CrCl <25 mL/min 0.5 g q12h；透析后追加","hepatic":"无需调整","interact":"与丙戊酸合用显著降低丙戊酸浓度（癫痫发作风险）——避免联用"},{"name":"万古霉素（覆盖 MRSA）","dose":"负荷 25–30 mg/kg 静滴（基于实际体重，最大 3 g），维持按 AUC 400–600 mg·h/L 或谷浓度 15–20 mg/L 调整","note":"用于 MRSA 高风险 HAP/VAP 或已知 MRSA 定植；建议 TDM","renal":"按 CrCl 调整给药间隔并 TDM；AKI 时先 15 mg/kg 并监测","hepatic":"无需调整","interact":"与哌拉西林/他唑巴坦合用 AKI 风险增加；与氨基糖苷类合用肾毒性叠加"},{"name":"利奈唑胺（覆盖 MRSA 替代）","dose":"600 mg 静滴/口服 q12h","note":"MRSA 或万古霉素不耐受者；肺组织穿透好，但需监测血小板","renal":"无需调整","hepatic":"严重肝功能不全者慎用","interact":"与 SSRI/SNRI 合用可能引发 5-羟色胺综合征"},{"name":"阿米卡星（联合治疗）","dose":"15–20 mg/kg 静滴 qd，按血药浓度调整（谷浓度 <5 mg/L）","note":"用于耐药革兰阴性杆菌（尤其不动杆菌、铜绿假单胞菌）的联合方案，不宜单药","renal":"按 CrCl 调整剂量与间隔并有 TDM","hepatic":"无需调整","interact":"与其他肾毒性药物（万古霉素、两性霉素 B、大剂量利尿剂）合用需密切监测"},{"name":"替加环素（替代/联合）","dose":"首剂 200 mg 静滴，之后 100 mg q12h","note":"用于 MDR 鲍曼不动杆菌的联合治疗；不作为单药治疗 VAP 的首选","renal":"无需调整","hepatic":"Child-Pugh B/C 需减量（100 mg 负荷后 25 mg q12h）","interact":"与华法林合用可延长 INR"}],"nonDrug":["及时启动：诊断明确后 1–4 小时内开始经验性抗感染治疗；延误治疗显著增加病死率","降阶梯：48–72 小时根据培养与临床反应降至窄谱；疗程一般 7 天（重症或耐药菌可延长至 10–14 天）","VAP 预防组合：抬高床头 30°–45°、每日唤醒与撤机评估、口腔护理、避免不必要的镇静与抑酸过度、呼吸机管路仅在有污染或损坏时更换","气道管理：吸痰、体位引流、早期活动与肺康复","胸腔积液/脓胸引流、肺脓肿必要时引流或切除","呼吸支持与循环管理：HFNC、NIV 或机械通气；休克时液体与血管活性药"],"life":["加强手卫生与接触隔离，感染者单间或同类同室","营养支持与早期活动，减少镇静深度，实施每日唤醒","监测抗生素相关艰难梭菌感染与急性肾损伤","出院/转科时明确抗生素疗程与复查影像时间","定期反馈当地 ICU 耐药菌谱，指导经验用药"]},"prog":"HAP 病死率约 15%–30%，VAP 病死率 20%–40%；延迟合适抗生素治疗每增加 1 小时病死率上升。多数患者 7 天疗程足够，但 MDR 菌感染、ARDS 与免疫抑制者需要更长疗程与反复评估。","refs":["中华医学会呼吸病学分会《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南（2018 年版）》","《中国成人医院获得性肺炎与呼吸机相关性肺炎诊疗指南解读》（2018）","ATS/IDSA《医院获得性肺炎与呼吸机相关性肺炎治疗指南》（2016）","《国家抗微生物治疗指南（第 3 版）》（2022）"]}]},{"id":"resp_fail","name":"呼吸衰竭与 ARDS","rank":4,"summary":"I 型呼衰以单纯低氧（PaO₂ <60 mmHg、PaCO₂ 正常或降低）为特征，以氧疗加病因治疗为主；ARDS 是急性弥漫性炎症性肺损伤所致顽固低氧，按柏林定义以 PEEP ≥5 cmH₂O 下的 P/F 比值分级；OSAHS 则以夜间间歇性低氧与日间嗜睡为特征。三者鉴别的关键为血气 + 影像 + 睡眠监测。","compare":[{"diseaseId":"arf_type1","dx":"海平面静息吸空气时 PaO₂ <60 mmHg、PaCO₂ 正常或 <50 mmHg；影像可为肺水肿、肺不张、肺炎等","key":"单纯低氧血症，提高 FiO₂ 后低氧多可改善；需按病因区分心源性肺水肿、肺炎、肺栓塞等"},{"diseaseId":"ards","dx":"急性起病（≤1 周）、双肺弥漫浸润影、不能完全用左心衰解释、PEEP ≥5 cmH₂O 时 P/F ≤300 mmHg","key":"顽固低氧 + 双肺渗出 + 需 PEEP；柏林分级 P/F 200–300 轻、100–200 中、<100 重；小潮气量通气为核心"},{"diseaseId":"osahs","dx":"夜间打鼾、憋醒、日间嗜睡 + 睡眠监测 AHI ≥5 次/时（伴症状）或 ≥15 次/时","key":"夜间低氧与睡眠碎片化（AHI），CPAP 为一线；日间血气多正常"}],"diseases":[{"id":"arf_type1","name":"I 型呼吸衰竭","aka":["Type I respiratory failure","低氧性呼吸衰竭"],"rank":1,"basic":{"define":"在海平面静息状态吸空气条件下，PaO₂ <60 mmHg，伴 PaCO₂ 正常或降低（不高于 50 mmHg），主要反映氧合障碍。","risk":["肺部感染（肺炎、肺脓肿）、支气管痉挛与肺不张","急性肺损伤/ARDS、肺栓塞、肺水肿（心源性或非心源性）","间质性肺疾病急性加重（如 IPF 急性加重）","肺内分流（肝肺综合征、肺动静脉瘘）、高原低氧","严重肥胖、胸壁畸形等导致的高氧需求状态"],"epi":"呼吸衰竭在住院患者中并不少见；I 型呼衰占 ICU 呼吸衰竭的多半，重症 I 型呼衰病死率 20%–40%，取决于基础病因。"},"patho":"核心机制为肺内通气/血流（V/Q）比例失调、真性分流与弥散障碍，导致动脉血氧分压下降，而 CO₂ 因弥散能力强且常伴代偿性通气增加而不升高（甚至降低）。当分流率 >30% 时，单纯提高 FiO₂ 往往不能纠正低氧，需 PEEP/复张或针对病因治疗。","dx":{"criteria":["海平面静息、未吸氧状态下 PaO₂ <60 mmHg，且 PaCO₂ 正常或 <50 mmHg。","按氧合指数 PaO₂/FiO₂ 分级：轻度 >300 mmHg；中度 200–300；重度 <200（与 ARDS 分级口径相近，但无 PEEP 强制要求）。","需评估是否合并高碳酸血症倾向（呼吸肌疲劳、COPD 背景），防止进展为 II 型呼衰。","影像学与病因：胸片/CT 判断实变、间质改变、胸腔积液、心影；必要时 CTPA 排除 PE、超声心动图评估心源性疾病。"],"workup":["动脉血气（吸空气或已知 FiO₂）：计算 P/F 与 A-a 氧分压差","脉搏血氧连续监测，必要时 SpO₂ 与 PaO₂ 对照（贫血时偏差）","胸片/胸部 CT：明确病因（肺炎、肺水肿、肺不张、气胸、间质病）","超声心动图/BNP：评估左心衰与心源性肺水肿","D-二聚体、CTPA：疑诊肺栓塞时","机械通气参数与 PEEP 效应评估；必要时评估肺复张性"],"grading":"按 PaO₂/FiO₂ 分轻、中、重度；按病因分肺源性（肺炎、ARDS、肺水肿）与肺外性（肺栓塞、分流）；按治疗响应分是否需要 HFNC、NIV 或有创通气。"},"ddx":[{"name":"急性呼吸窘迫综合征","point":"与本类中 ARDS 的鉴别点：ARDS 是特定诱因下 1 周内急性起病、双肺弥漫渗出且 PEEP ≥5 cmH₂O 时 P/F ≤300；I 型呼衰是更宽泛的综合征，单纯肺水肿或肺炎早期可无 ARDS 特征性的 PEEP 依赖与双肺弥漫受累。"},{"name":"睡眠呼吸暂停低通气综合征","point":"与本类中 OSAHS 的鉴别点：OSAHS 夜间低氧呈间歇性下降、日间清醒血氧常正常；I 型呼衰为持续的日间低氧血症。"},{"name":"心源性肺水肿","point":"端坐呼吸、粉红色泡沫痰、BNP 显著升高、双下肺湿啰音；利尿与扩血管后迅速改善。"},{"name":"COPD 伴 II 型呼衰","point":"PaCO₂ 升高、pH 代偿、长期吸烟与气流受限；I 型呼衰 PaCO₂ 正常或降低，需警惕向混合型过渡。"},{"name":"肺栓塞","point":"D-二聚体高、右心扩大与肺动脉高压，CTPA 见充盈缺损；可解释顽固低氧但需同时处理。"},{"name":"高原肺水肿","point":"快速上升海拔后出现气促与低氧，吸氧或下撤后迅速改善。"}],"tx":{"drug":[{"name":"氧疗（经鼻导管/文丘里/HFNC）","dose":"FiO₂ 滴定使 SpO₂ 90%–96%（PaO₂ 60–80 mmHg）；HFNC 流量 30–60 L/min、FiO₂ 0.3–0.6 起","note":"首选非侵入性氧合支持；HFNC 较常规氧疗可减少插管，尤其 ARDS 早期；长期 FiO₂ >0.6 需警惕氧中毒","renal":"不适用","hepatic":"不适用","interact":"注意吸收性肺不张"},{"name":"呋塞米（合并心源性肺水肿时）","dose":"20–40 mg 静脉推注，或按既往剂量个体化（必要时持续泵入，遵医嘱）","note":"仅用于容量负荷过重/心源性肺水肿；监测电解质与尿量","renal":"肾功能不全需加大剂量；尿少时警惕 AKI","hepatic":"低蛋白血症时作用减弱","interact":"与氨基糖苷类合用增加耳毒性与肾毒性；低钾时增加地高辛毒性"},{"name":"沙丁胺醇（可逆性气道痉挛）","dose":"2.5–5 mg 雾化 q4–6h，或 pMDI 4–8 揿 q1–4h","note":"仅在有明确可逆性气道痉挛时使用；ARDS 气道并非主要矛盾","renal":"无需调整","hepatic":"无需调整","interact":"与非选择性 β 阻滞剂合用降低疗效"},{"name":"尼可刹米（中枢呼吸兴奋剂）","dose":"遵说明书（缓慢静滴，按呼吸频率与神志调整，须在监护条件下使用）","note":"不推荐用于 ARDS；可能增加呼吸肌耗氧；仅在特定过渡场景考虑","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["病因治疗：抗感染、抗凝、抗炎、纠正容量或心功能、解除气道阻塞","无创通气（NIV）：意识清楚、血流动力学稳定、能保护气道者；HFNC 可用于轻度低氧","有创机械通气：呼吸窘迫、意识改变、P/F 恶化；初始采用潮气量 6–8 mL/kg 理想体重、平台压 <30 cmH₂O","PEEP 滴定与肺复张：改善氧合，避免过度复张与气压伤","俯卧位通气：中重度患者可改善氧合（详见 ARDS）","ECMO：常规通气失败的重度低氧（需中心资质）","肺康复与早期活动；营养支持"],"life":["ICU 期间预防呼吸机相关肺炎、深静脉血栓、谵妄与压力性损伤","出院后 6–12 个月随访肺功能、运动耐量与心理评估","戒烟、疫苗接种与基础病管理","避免自行调节高浓度氧；家庭氧疗者按处方使用"]},"prog":"取决于病因：单纯肺炎或肺水肿导致的轻中度 I 型呼衰经治疗多可恢复；合并 ARDS 者病死率 30%–45%；幸存者常有持续的肺功能与运动功能受限，需要康复随访。","refs":["《内科学（第 9 版）》呼吸系统疾病·呼吸衰竭章","中华医学会呼吸病学分会《呼吸衰竭诊断与治疗指南》（2005 年及后续修订版）","《中国成人急性呼吸窘迫综合征诊断与治疗指南》（2024）","ERS/ATS 急性呼吸衰竭氧疗指南（2017 及后续更新）"]},{"id":"ards","name":"急性呼吸窘迫综合征","aka":["ARDS","Acute Respiratory Distress Syndrome"],"rank":2,"basic":{"define":"由肺内或肺外原因引起的急性弥漫性炎症性肺损伤，以顽固性低氧血症为特征，肺泡-毛细血管屏障破坏致富含蛋白的水肿液蓄积与肺顺应性下降，影像示双肺浸润影且不能完全用左心衰解释。","risk":["脓毒症（最常见诱因之一）、重症肺炎（尤其病毒性）","严重创伤、大量输血、误吸、肺挫伤","急性胰腺炎、药物/输血反应、溺水","吸入性损伤与产科并发症","免疫抑制与大剂量化疗"],"epi":"ARDS 约占 ICU 患者的 10%–20%；中国多中心研究显示 ICU 中 ARDS 并不少见；病死率随严重度升高，重度 ARDS 病死率可达 40%–50%。"},"patho":"肺泡上皮与毛细血管内皮损伤使屏障通透性增加，含蛋白的渗出液充满肺泡，形成非心源性肺水肿；肺内分流率增高引起顽固低氧；肺泡表面活性物质减少使肺泡塌陷，肺顺应性下降。病理分为渗出期（约 1–7 天，弥漫性肺泡损伤伴透明膜）、增生期与纤维化期，部分患者遗留肺纤维化与长期功能损害。","dx":{"criteria":["柏林定义（2012）① 起病时间 ≤1 周内已知临床诱因或症状新发/加重；② 胸片或 CT 示双肺弥漫性浸润影，不能完全由肺不张、肺叶或叶段实变、肺部结节或胸腔积液解释；③ 浸润影不能完全用心力衰竭或容量负荷过重解释；④ 氧合：PEEP ≥5 cmH₂O 时 PaO₂/FiO₂ ≤300 mmHg。","分级：轻度 200 < P/F ≤300；中度 100 < P/F ≤200；重度 P/F ≤100（均在 PEEP ≥5 cmH₂O 条件下评价）。","SpO₂/FiO₂ 可作为替代（S/F ≤315 对应 P/F ≤300），但首选动脉血气。","需与心源性肺水肿鉴别：BNP/NT-proBNP、超声心动图评估左室收缩与舒张功能，但两者可并存。"],"workup":["动脉血气：在 PEEP ≥5 cmH₂O 下测 P/F 比值，避免过早取样高估氧合","胸片/CT：双肺磨玻璃影、实变、重力依赖分布；CT 评估可复张性","超声心动图/BNP：排除左心衰与心源性肺水肿","病原学：痰/BAL 培养、PCT、病毒核酸（流感、新冠）、曲霉抗原（免疫抑制）","血流动力学监测：床旁超声或 PICCO 评估容量状态","寻找并治疗诱因与并发症（气胸、纵隔气肿、肺栓塞）"],"grading":"柏林定义分级：轻度（P/F 200–300）、中度（100–200）、重度（≤100）；按诱因分肺源性（肺炎/吸入）与肺外源性（脓毒症、创伤）；按治疗阶段分常规通气、俯卧位与 ECMO。"},"ddx":[{"name":"I 型呼吸衰竭","point":"与本类中 I 型呼衰的鉴别点：I 型呼衰为更宽泛的综合征，不一定有双肺弥漫渗出；ARDS 强调 1 周内急性起病、PEEP ≥5 cmH₂O 下 P/F ≤300 与双肺非心源性浸润影。"},{"name":"睡眠呼吸暂停低通气综合征","point":"与本类中 OSAHS 的鉴别点：OSAHS 为睡眠相关间歇低氧，日间清醒 PaO₂ 与影像通常正常；ARDS 为急性持续低氧与双肺浸润，需与肥胖低通气综合征鉴别。"},{"name":"心源性肺水肿","point":"端坐呼吸、双下肺湿啰音、BNP 显著升高、利尿后快速吸收、超声见左室功能不全；鉴别不清时可参考 PAWP ≤18 mmHg 支持 ARDS。"},{"name":"弥漫性肺泡出血","point":"咯血、进行性贫血、CT 示弥漫磨玻璃影；BAL 见血性回收液与含铁血黄素巨噬细胞。"},{"name":"急性嗜酸性粒细胞性肺炎","point":"急性发热 + 低氧，BAL 嗜酸性粒细胞 >25%，对糖皮质激素迅速反应。"},{"name":"间质性肺疾病急性加重","point":"既往 IPF 病史，HRCT 见原有蜂窝影基础上新发磨玻璃影；预后差。"}],"tx":{"drug":[{"name":"镇静与肌松（丙泊酚/咪达唑仑/顺阿曲库铵）","dose":"丙泊酚 1–4 mg/kg/h 泵入；咪达唑仑 0.05–0.1 mg/kg/h；中重度 ARDS 早期可短程使用肌松药，剂量遵说明书按体重泵入","note":"深镇静用于严重人机对抗或俯卧位；肌松仅限早期重度 ARDS 且需加强监护","renal":"丙泊酚与咪达唑仑需减量并延长监测；顺阿曲库铵在器官衰竭时作用延长","hepatic":"丙泊酚在肝衰竭时慎用；咪达唑仑需减量","interact":"丙泊酚与阿片类合用致低血压；注意丙泊酚输注综合征"},{"name":"地塞米松（中重度 ARDS 早期）","dose":"6 mg qd 口服/静注共 10 天（DEXA-ARDS 方案）；或甲泼尼龙 1 mg/kg qd（部分方案，疗程按研究方案执行）","note":"用于中重度 ARDS 早期，可缩短机械通气时间；脓毒症相关 ARDS 仍按脓毒症指南决定激素","renal":"无需调整","hepatic":"遵说明书","interact":"监测血糖；与氟喹诺酮联用增加肌腱病变风险"},{"name":"呋塞米（容量管理与负平衡）","dose":"20–40 mg 静脉推注，按容量状态与尿量个体化调整（遵医嘱）","note":"仅适用于容量负荷过重且循环稳定者；脓毒症休克早期仍需液体复苏","renal":"AKI 时慎用，避免过度利尿","hepatic":"遵说明书","interact":"监测电解质；与肾毒性药物合用需谨慎"}],"nonDrug":["小潮气量通气：6 mL/kg 理想体重（可低至 4 mL/kg），平台压 ≤30 cmH₂O，允许性高碳酸血症（pH ≥7.20）","合适 PEEP 与 FiO₂：按 PEEP/FiO₂ 表或床旁力学/电阻抗滴定，避免肺泡反复开闭与气压伤","俯卧位通气：每日 ≥12–16 小时，尤其 P/F <150 mmHg（PROSEVA 研究证实降低病死率）；注意面部压伤与管路安全","肺复张手法仅在血压允许、评估可复张性后进行；不推荐常规强力复张","无创通气/HFNC：仅用于轻度或拔管后支持，避免延误插管","ECMO：常规通气 + 俯卧位 + 肌松后仍 P/F <80 mmHg 或 pH <7.25 的挽救治疗，需中心资质","治疗原发病与并发症：抗感染、脓毒症集束化治疗、气胸/纵隔气肿减压","早期肠内营养、血糖控制、DVT 与应激性溃疡预防"],"life":["康复：早期被动活动、渐进式肢体训练、呼吸肌锻炼","出院后 3、6、12 个月复查肺功能、6 分钟步行与胸部影像","关注 ICU 后综合征（肌无力、认知与心理障碍），提供多学科随访","戒烟并按计划接种流感/肺炎球菌疫苗"]},"prog":"中重度 ARDS 病死率 30%–45%，重度可达 50%；小潮气量通气、俯卧位与 ECMO 可降低病死率。存活者部分遗留肺功能异常与运动耐量下降，少数进展为肺纤维化。","refs":["《中国成人急性呼吸窘迫综合征诊断与治疗指南》（2024）","中华医学会重症医学分会《急性呼吸窘迫综合征诊断治疗指南》（2012）","ARDS 柏林定义（ARDS Definition Task Force，JAMA 2012）","ATS/ERS/SCCM 机械通气指南（2023）"]},{"id":"osahs","name":"阻塞性睡眠呼吸暂停低通气综合征","aka":["OSAHS","阻塞性睡眠呼吸暂停","OSA"],"rank":3,"basic":{"define":"睡眠期间上气道反复塌陷，导致呼吸暂停和（或）低通气，伴间歇性低氧、睡眠碎片化和日间嗜睡；是心脑血管疾病、代谢紊乱与交通事故的重要危险因素。","risk":["肥胖（BMI ≥30 kg/m²、颈围增大、咽部脂肪沉积）","下颌后缩、舌体肥大、扁桃体肥大与鼻中隔偏曲","男性、绝经后女性、年龄 >40 岁","饮酒、镇静催眠药、吸烟、甲状腺功能减退","家族史与颅面畸形（唐氏综合征、Pierre Robin 序列）"],"epi":"我国 30–69 岁人群 OSAHS 患病率约 23.6%，中重度约 8.8%；在肥胖与中老年人群中更常见，绝大多数患者未获诊断。"},"patho":"睡眠时咽部肌肉张力下降（尤其 REM 期），咽腔负压致软腭、舌根与咽侧壁塌陷，出现气流停止（呼吸暂停）或通气量下降（低通气），引起反复低氧与 CO₂ 潴留、微觉醒、交感神经激活。长期可导致全身炎症、内皮功能障碍、高血压与代谢紊乱。","dx":{"criteria":["临床：夜间打鼾、他人观察到的呼吸暂停或憋醒、白天嗜睡（ESS ≥10）、夜尿增多、晨起头痛与口干。","多导睡眠监测（PSG）为金标准：AHI ≥5 次/小时伴典型症状或并发症（高血压、冠心病、糖尿病）；或 AHI ≥15 次/小时无论有无症状。","AHI 分级：轻度 5–14.9、中度 15–29.9、重度 ≥30 次/小时（成人）。","低氧评估：氧减指数（ODI）、最低 SpO₂、SpO₂ <90% 的时间占比。","便携式睡眠监测：用于高度怀疑、无严重心肺合并症者，阳性需专科确认。"],"workup":["多导睡眠监测：含脑电、眼电、下颌肌电、呼吸气流、胸腹运动、SpO₂、体位、心电图","Epworth 嗜睡量表（ESS）与 STOP-Bang 问卷初筛","上气道评估：耳鼻喉科查鼻咽喉与扁桃体、Mallampati 分级，必要时 CT/MRI 评估气道空间","合并症筛查：血压监测、空腹血糖/糖化血红蛋白、血脂、甲状腺功能、心电图","日间血气与肺功能：重度肥胖低通气患者评估是否合并高碳酸血症","必要时食道压监测评估上气道阻力"],"grading":"AHI 分级（轻度 5–14.9、中度 15–29.9、重度 ≥30）；按合并症分单纯性 OSAHS 与合并高血压、冠心病、糖尿病、COPD（重叠综合征）或肥胖低通气综合征；按日间嗜睡与夜间低氧程度评估驾驶风险与手术/CPAP 指征。"},"ddx":[{"name":"I 型呼吸衰竭","point":"与本类中 I 型呼衰的鉴别点：OSAHS 低氧为睡眠期间歇性，日间清醒血气多正常；若日间清醒 PaO₂ 持续 <60 mmHg，应评估合并 COPD 或肥胖低通气，而非单纯 OSAHS。"},{"name":"急性呼吸窘迫综合征","point":"与本类中 ARDS 的鉴别点：ARDS 为急性低氧与双肺浸润影需呼吸支持；OSAHS 为慢性夜间低氧、结构影像正常。"},{"name":"肥胖低通气综合征（OHS）","point":"BMI ≥30、日间 PaCO₂ >45 mmHg、睡眠呼吸紊乱与嗜睡；需无创通气（BPAP）而非仅 CPAP。"},{"name":"中枢性睡眠呼吸暂停","point":"呼吸努力缺失（胸腹运动消失）、多见于心力衰竭或卒中；PSG 可区分事件类型。"},{"name":"发作性睡病","point":"日间嗜睡严重伴猝倒、入睡幻觉与睡眠麻痹，MSLT 见睡眠潜伏期缩短与早期 REM；AHI 可正常。"},{"name":"甲状腺功能减退","point":"乏力、嗜睡、体重增加与舌体肥大，甲功异常；OSAHS 可继发于甲减，需同时治疗。"}],"tx":{"drug":[{"name":"持续气道正压通气（CPAP）","dose":"压力 5–20 cmH₂O 按滴定确定（自动滴定或 PSG 滴定），每晚使用 ≥4–6 小时","note":"中重度 OSAHS 一线治疗；依从性是疗效关键，需随访调整面罩与压力","renal":"不适用","hepatic":"不适用","interact":"与镇静催眠药联用会降低咽喉肌张力，影响疗效"},{"name":"口腔矫治器（下颌前移装置）","dose":"夜间佩戴，下颌前伸量由口腔科结合睡眠监测与耐受情况确定","note":"适用于轻中度、下颌后缩或不能耐受 CPAP 者；需定期评估牙列与颞下颌关节","renal":"不适用","hepatic":"不适用","interact":"不适用"},{"name":"莫达非尼/阿莫达非尼（残余嗜睡）","dose":"莫达非尼 100–200 mg qd（早晨）；阿莫达非尼 150–250 mg qd（遵医嘱）","note":"仅用于 CPAP 规范治疗后的残余嗜睡，不作为 OSAHS 主治疗","renal":"严重肾损害慎用","hepatic":"严重肝损害者减量","interact":"可降低口服避孕药效果；与 CYP3A4 底物相互作用"},{"name":"减重药物（奥利司他/司美格鲁肽）","dose":"奥利司他 120 mg tid 餐时服；司美格鲁肽 0.25 mg 起始并按说明书递增（体重管理适应证）","note":"减重 10% 可显著降低 AHI，作为辅助而非替代 CPAP","renal":"奥利司他重度肾损害慎用；司美格鲁肽重度肾损害慎用","hepatic":"重度肝损害慎用","interact":"奥利司他影响脂溶性维生素吸收；司美格鲁肽延迟胃排空影响口服药吸收"},{"name":"鼻用糖皮质激素（合并过敏性鼻炎时）","dose":"糠酸莫米松 100 µg 每鼻孔 qd，或丙酸氟替卡松 100 µg 每鼻孔 qd","note":"改善鼻塞可部分降低 AHI；不能替代 CPAP","renal":"无需调整","hepatic":"无需调整","interact":"与其他糖皮质激素合用注意全身效应（少见）"}],"nonDrug":["减重与生活方式干预：目标减轻体重 10% 以上、侧卧睡眠、避免睡前饮酒与镇静药","上气道手术：悬雍垂腭咽成形术等，适用于不能耐受 CPAP 的软腭后气道塌陷；必要时行正颌手术（下颌前移术）","儿童扁桃体/腺样体切除术（儿童 OSAHS 一线手术）","鼻腔手术（鼻中隔偏曲、息肉）改善 CPAP 依从性","舌下神经刺激：CPAP 失败且解剖适合者","驾驶与职业安全：ESS ≥10 或未控制者需评估驾驶风险；职业驾驶者定期复核"],"life":["CPAP 每夜 ≥4 小时、≥70% 夜次使用；面罩每 3–6 个月更换","每年复查 AHI/依从性与体重；减重 5%–10% 可使 AHI 降低 20%–30%","戒烟、限酒，睡前 3 小时不饮酒","合并高血压/糖尿病者需多学科管理；围术期气道风险高者加强监护","儿童患者需监测生长发育与学习成绩"]},"prog":"未治疗的中重度 OSAHS 与心血管事件、卒中和全因死亡风险增加相关，也与糖尿病控制不佳、脂肪肝和交通事故有关；CPAP 依从性良好者可显著改善日间症状、血压与生活质量，但硬性心血管终点改善的证据有限。","refs":["中华医学会呼吸病学分会睡眠呼吸障碍学组《阻塞性睡眠呼吸暂停低通气综合征诊治指南（2011 修订版）》","《成人阻塞性睡眠呼吸暂停多学科诊疗指南》（2018）","《中国成人阻塞性睡眠呼吸暂停基层诊疗指南》（2019）","AASM《成人阻塞性睡眠呼吸暂停诊断与治疗指南》（2018 及后续更新）"]}]},{"id":"airway_infect","name":"气道与感染性疾病","rank":5,"summary":"以“病原-结构-宿主”三条线索处置：先判断是结构性气道疾病（支扩、毁损肺）还是感染性疾病（肺脓肿、结核、NTM、真菌），再结合宿主免疫状态与影像学特征（支扩的印戒征、肺脓肿的空洞液平、结核的尖后段空洞与树芽征、曲霉的晕轮征/空气新月征）决定经验用药；凡有咯血先评估出血量与窒息风险，凡有结构性毁损者必须同期做气道清除与基础病控制，否则单纯抗生素难以治愈。","compare":[{"diseaseId":"resp_bronchiectasis","dx":"长期咳嗽咳大量脓痰，HRCT 见支气管内径大于伴行血管、气道不得收窄至远端（印戒征/双轨征）","key":"痰量多、反复急性加重，HRCT 结构改变为诊断基础；以气道清除 + 急性期抗菌为主，不作长期全身抗生素"},{"diseaseId":"resp_ntm","dx":"基础结构性肺病（支扩、旧结核）患者慢性咳嗽，反复痰非结核分枝杆菌培养阳性且影像与临床相符","key":"影像似结核但无传染性、常耐药；需痰培养菌种鉴定 + 药敏，大环内酯为核心，疗程多 ≥12 个月"},{"diseaseId":"resp_fungal","dx":"免疫抑制宿主发热不退，胸部 CT 见结节伴晕轮征或空洞内空气新月征，GM 试验或隐球菌荚膜抗原阳性","key":"宿主免疫状态是第一线索；影像征象 + 抗原/真菌学证据驱动，抗真菌疗程长且需处理免疫抑制"},{"diseaseId":"resp_lung_abscess","dx":"高热、咳大量脓臭痰，胸片/CT 见厚壁空洞伴气液平面，多为厌氧菌吸入后 1–2 周形成","key":"空洞伴液平 + 脓臭痰；抗生素需覆盖厌氧菌且疗程长（6–8 周），体位引流是关键辅助治疗"},{"diseaseId":"resp_tb","dx":"低热盗汗消瘦，影像见上叶尖后段/下叶背段渗出、空洞、树芽征与卫星灶，痰涂片抗酸阳性或结核分枝杆菌核酸阳性","key":"慢性全身中毒症状 + 尖后段好发 + 传染性；需按传染病法上报并规律 6 个月联合化疗"}],"diseases":[{"id":"resp_bronchiectasis","name":"支气管扩张症","aka":["Bronchiectasis","支扩","支气管扩张"],"rank":1,"basic":{"define":"由于反复感染与炎症导致支气管壁破坏、管腔不可逆性扩张的结构性肺病；按形态分为柱状、囊状与静脉曲张型，临床以慢性咳嗽、大量脓痰与反复咯血为核心表现。","risk":["儿童期下呼吸道感染（麻疹、百日咳、重症肺炎）","肺结核后遗毁损、非结核分枝杆菌感染","免疫功能缺陷（低丙种球蛋白血症、IgG 亚类缺陷）、原发性纤毛运动障碍","变应性支气管肺曲霉病（ABPA）、哮喘合并嗜酸性炎症","气道阻塞（异物、肿瘤、淋巴结压迫）与反复误吸","结缔组织病（类风湿关节炎、干燥综合征）及炎症性肠病"],"epi":"我国 40 岁以上人群基于 CT 的支扩患病率约 1.2%，随年龄增长上升；女性多于男性。支扩患者年均急性加重 1–3 次，反复加重者肺功能下降更快、病死率显著升高。"},"patho":"感染与炎症形成“黏液-细菌-炎症”恶性循环：气道纤毛清除功能受损致分泌物潴留，铜绿假单胞菌、流感嗜血杆菌等定植并释放蛋白酶与毒素，中性粒细胞浸润释放弹性蛋白酶破坏支气管壁弹力纤维与软骨，管腔扩张、管壁血管增生迂曲（支气管动脉肥大），形成咯血的解剖基础。扩张气道失去清除能力又加重潴留，最终出现进行性气流受限、低氧血症与铜绿假单胞菌耐药定植。","dx":{"criteria":["临床线索：咳嗽咳痰 ≥8 周、痰量多且脓性、反复咯血、反复同一部位肺部感染；听诊可闻及固定部位粗湿啰音。","HRCT 为诊断金标准（层厚 ≤1 mm）：支气管内径大于伴行肺动脉直径（印戒征），或气道自中心向外周走行时管径未见逐渐变细；柱状型呈双轨征，囊状型呈蜂窝样簇状囊腔。","痰培养与药敏（含铜绿假单胞菌筛查）：治疗前或加重期必须留取；痰量增多、脓性提示细菌负荷增加。","肺功能：评估气流受限与 FEV₁ 下降幅度；弥散功能多正常。","病因筛查：总 IgG 与 IgG 亚类、血清总 IgE 与烟曲霉特异性 IgE、自身抗体（ANA、抗 CCP、抗 SSA）、α₁-抗胰蛋白酶（年轻/下叶为主者）、纤毛功能检查。","分级：结合 FEV₁、mMRC 呼吸困难、既往急性加重次数与铜绿假单胞菌定植评估严重度；BSI 与 FACED 评分可用于预后分层。"],"workup":["胸部高分辨率 CT：明确扩张范围（叶/段分布）与囊状程度，评估是否合并黏液栓、毁损肺","痰涂片革兰染色 + 培养 + 药敏，必要时诱导痰或支气管镜采样","血常规、CRP、PCT（加重期鉴别细菌感染）、免疫球蛋白","支气管镜检查：咯血定位、排除异物/肿瘤、清理黏液栓","咯血患者行支气管动脉 CTA：评估出血动脉及支气管动脉-肺动脉分流","血气分析：重度支扩伴低氧者评估呼吸衰竭"],"grading":"按扩张范围：局限型（单叶）与弥漫型（多叶/双肺）；按形态：柱状（轻度）、静脉曲张型（中度）、囊状（重度）。咯血按量：少量（<30 mL/24 h）、中等（30–200 mL/24 h）、大咯血（>200 mL/24 h 或 >100 mL/h，或任何引起气道阻塞/血流动力学不稳者）。"},"ddx":[{"name":"肺脓肿","point":"与本类中肺脓肿的鉴别点：支扩为慢性反复咳嗽咳痰、影像见管腔扩张的簇状气道，不以空洞液平为主；肺脓肿起病急、高热、脓臭痰、单个厚壁空洞伴液平。支扩伴厌氧菌感染时可形成“支扩合并感染性空洞”，需按疗程抗厌氧菌治疗。"},{"name":"慢性阻塞性肺疾病","point":"长期吸烟、FEV₁/FVC <0.70、肺气肿表现为主、痰量相对少；两者可共存，COPD 患者影像出现扩张气道即为 COPD-支扩重叠。"},{"name":"肺结核","point":"低热盗汗消瘦 + 上叶尖后段空洞/树芽征，痰抗酸涂片或结核核酸阳性；结核后遗支扩者痰菌多为阴性，需反复验证。"},{"name":"囊性纤维化","point":"我国罕见；儿童起病、反复呼吸道与胰腺外分泌功能不全、汗液氯离子 >60 mmol/L；年轻弥漫性支扩伴消化不良者需筛查。"},{"name":"闭塞性细支气管炎","point":"HRCT 显示马赛克灌注与空气潴留，不出现明显气道扩张；多见于移植后或吸入性损伤。"},{"name":"变应性支气管肺曲霉病","point":"哮喘史 + 血总 IgE 升高、烟曲霉特异性 IgE/IgG 阳性、外周血嗜酸性粒细胞增多，CT 见中心性支扩与黏液栓（指套征）。"}],"tx":{"drug":[{"name":"氨溴索（气道清除）","dose":"30–60 mg 口服 tid；或 15–30 mg 静注 bid–tid","note":"降低痰液黏稠度，配合物理排痰与充足饮水；疗效个体差异大","renal":"严重肾功能不全者延长给药间隔","hepatic":"遵说明书","interact":"与中枢性镇咳药合用可致痰液潴留"},{"name":"乙酰半胱氨酸（雾化）","dose":"10% 溶液 3 mL 雾化 bid–tid（或 0.2 g 雾化 bid）","note":"溶解黏液栓，雾化前后需充分排痰；哮喘患者警惕诱发支气管痉挛","renal":"遵说明书","hepatic":"遵说明书","interact":"不宜与强力镇咳药同时使用"},{"name":"阿莫西林/克拉维酸（轻中度加重）","dose":"625 mg 口服 tid（或 1.0 g bid）","note":"无铜绿假单胞菌定植、既往药敏敏感者的首选经验用药；疗程一般 7–14 天","renal":"CrCl <30 mL/min 减量或延长间隔","hepatic":"肝功能异常者慎用并监测","interact":"与别嘌醇合用皮疹增加；与华法林合用可延长 INR"},{"name":"左氧氟沙星（加重期替代）","dose":"0.5 g 口服/静滴 qd（重症 0.75 g qd）","note":"覆盖流感嗜血杆菌、卡他莫拉菌、部分铜绿假单胞菌；我国肺炎链球菌/肠杆菌耐药率较高，需参考药敏","renal":"CrCl 20–49 mL/min 0.5 g qd；CrCl <20 mL/min 遵说明书减量","hepatic":"严重肝功能不全者慎用","interact":"禁与胺碘酮、索他洛尔合用；避免与含铝镁抗酸剂、铁剂同服"},{"name":"哌拉西林/他唑巴坦（重症或铜绿假单胞菌感染）","dose":"4.5 g 静滴 q8h（延长输注 3–4 小时更佳）","note":"存在铜绿假单胞菌定植、近期住院或广谱抗生素暴露者的经验覆盖；获得药敏后降阶梯","renal":"CrCl 20–40 mL/min 4.5 g q8h；CrCl <20 mL/min 2.25 g q8h","hepatic":"无需调整","interact":"与万古霉素合用增加急性肾损伤风险"},{"name":"头孢他啶（铜绿假单胞菌）","dose":"2 g 静滴 q8h（延长输注 3 小时）；日剂量不超过 6 g","note":"针对铜绿假单胞菌的替代选择；用药前尽量取得药敏，避免单药耐药泛化","renal":"CrCl 31–50 mL/min 1 g q12h；CrCl 16–30 mL/min 1 g q24h；<15 mL/min 0.5 g q24h","hepatic":"无需调整","interact":"与氨基糖苷类合用肾毒性叠加"},{"name":"阿奇霉素（长期维持，选择性使用）","dose":"250 mg 口服 qd（或每周 3 次）","note":"用于每年急性加重 ≥3 次者减少加重，需先排除 NTM 感染并评估 QT；我国大环内酯耐药率高，疗效有限","renal":"CrCl <30 mL/min 慎用","hepatic":"严重肝病者禁用","interact":"延长 QT；与华法林合用增加出血"},{"name":"垂体后叶素（大咯血止血）","dose":"6–12 U 加入 5% 葡萄糖 20–40 mL 缓慢静推（10–15 分钟），继以 12–24 U 加入 250–500 mL 液体中持续泵入","note":"收缩支气管动脉与肺血管，用于中等以上咯血；高血压、冠心病、妊娠者禁用或慎用；出现腹痛、面色苍白需减速","renal":"遵说明书","hepatic":"遵说明书","interact":"与缩宫素、麦角类合用升压反应增强"},{"name":"蛇毒血凝酶（辅助止血）","dose":"1–2 kU 静注/肌注，必要时 q6–8h 重复","note":"辅助止血，不能替代支气管动脉栓塞；DIC、血栓高危者慎用","renal":"遵说明书","hepatic":"遵说明书","interact":"不宜与其他促凝药大剂量联用"},{"name":"氨甲环酸（咯血辅助）","dose":"0.5–1 g 静脉滴注 q8h；或 1 g 口服 tid","note":"减少纤溶亢进的黏膜渗血，不适用于大量动脉性出血","renal":"CrCl 降低时减量","hepatic":"遵说明书","interact":"与口服避孕药合用血栓风险增加"}],"nonDrug":["气道清除技术为长期管理核心：体位引流、主动呼吸循环技术、振荡呼气末正压（OPEP）、高频胸壁振荡；每日 ≥1–2 次，痰多者 3–4 次","急性加重期雾化吸入 β₂ 受体激动剂/异丙托溴铵改善痰液排出，合并气流受限者规律使用 LAMA","支气管动脉栓塞术：大咯血或反复咯血内科止血无效者的首选微创止血手段","外科手术切除：局限型支扩（单叶/单段）反复感染或反复大咯血、内科及栓塞失败、肺功能可耐受者","肺移植：双肺弥漫性毁损、反复感染且内科治疗失败","高剂量吸入性糖皮质激素仅限合并哮喘/ABPA 者；不推荐用于普通支扩的长期维持治疗"],"life":["戒烟、每年接种流感疫苗、肺炎球菌疫苗（PCV13/PPSV23）与新冠疫苗","每日足量饮水（1500–2000 mL，心肾功能允许），保持痰液稀释","避免误吸：进食细嚼慢咽、卧床者床头抬高；胃食管反流者抑酸治疗","每 6–12 个月复查痰培养与肺功能；脓性痰量增加、咯血加重及时就诊","大咯血时保持患侧卧位、头偏向一侧防止窒息，立即呼叫急救"]},"prog":"支扩为慢性进行性疾病，年均 1–2 次急性加重；伴铜绿假单胞菌定植、每年加重 ≥3 次、FEV₁ <50% 预计值者预后较差。规范化气道清除与急性加重治疗可显著减少住院、延缓 FEV₁ 下降；局限型支扩手术后可获长期缓解。","refs":["中华医学会呼吸病学分会《支气管扩张症诊治中国专家共识》（2021）","《支气管扩张症急性加重期诊疗中国专家共识》（2023）","ERS《成人支气管扩张症管理指南》（2017）","《内科学》第 9 版 第二篇 呼吸系统疾病"]},{"id":"resp_lung_abscess","name":"肺脓肿","aka":["Lung Abscess","原发性肺脓肿"],"rank":2,"basic":{"define":"肺组织化脓性炎症导致坏死、液化并形成厚壁空洞的疾病，多由厌氧菌为主的混合感染引起；按感染途径分为吸入性（原发性）、血源性（继发性）与继发于支气管阻塞/肺部疾病三类。","risk":["意识障碍与误吸：醉酒、癫痫发作、全身麻醉、脑血管病后吞咽障碍、镇静催眠药过量","口腔卫生差、牙周病、龋齿（厌氧菌来源）","鼻窦炎、扁桃体炎、牙源性感染","免疫功能低下、糖尿病、长期糖皮质激素","支气管阻塞（肿瘤、异物、狭窄）与支扩后感染","皮肤软组织感染、静脉药瘾或感染性心内膜炎（血源性）"],"epi":"抗生素时代后原发性肺脓肿明显减少，但仍占住院肺部感染的一部分；以中老年男性、有误吸危险因素者多见。右肺多于左肺，下叶背段与上叶后段为好发部位（与吸入体位有关）。血源性肺脓肿多见于金黄色葡萄球菌败血症与静脉药瘾者，双肺多发。"},"patho":"误吸含厌氧菌（消化链球菌、梭杆菌、普雷沃菌、拟杆菌等）的口咽分泌物至重力依赖区，局部炎症引起小血管栓塞、组织坏死液化，形成单个或多个厚壁空洞。坏死组织与细菌经支气管排出后脓腔内出现气液平面。血源性者细菌经血循环播散形成双肺多发小脓肿。病程超过 3 个月、空洞壁纤维化增厚难以闭合者称慢性肺脓肿。","dx":{"criteria":["急性起病（多为误吸后 1–2 周）：高热、寒战、乏力，初为干咳或少量黏液痰，7–10 天后咳出大量脓痰或脓臭痰（厌氧菌感染典型），可伴咯血。","影像：胸片示大片浓密浸润影中有圆形透亮区与气液平面；胸部增强 CT 显示厚壁空洞（壁厚 >2 mm）、内缘不规则、周围渗出，可区分肿块性空洞与囊性病变。","实验室：白细胞与中性粒细胞升高、CRP 显著升高；痰涂片见大量中性粒细胞与混合菌群。","病原学：治疗前留取合格痰液或经支气管镜/CT 引导穿刺获取脓液行厌氧与需氧培养；血源性者血培养阳性率高。","血源性肺脓肿：血培养（金葡菌、克雷伯菌等）+ 心脏超声排除感染性心内膜炎 + 寻找原发灶。","排除性评估：年龄 >50 岁、上叶前段或非典型部位、无明确误吸史者需支气管镜排除支气管肺癌与异物。"],"workup":["胸部 X 线 + 增强 CT（评估空洞大小、壁厚、有无分隔与胸膜受累）","痰涂片革兰染色、抗酸染色、真菌涂片与培养，需氧+厌氧培养、药敏","血培养（体温高峰时双侧双瓶）、血常规、CRP、PCT、肝肾功能","支气管镜：取样并排除气道阻塞、异物，可同时行局部灌洗","经皮肺穿刺抽脓：影像不典型、抗生素无效或需鉴别者","合并脓胸者行胸腔穿刺/置管引流并行胸水培养"],"grading":"按病程：急性（<6 周）、亚急性（6 周–3 个月）、慢性（>3 个月）。按病因：吸入性（原发性）、血源性（继发性）、继发于支气管阻塞。按空洞大小：<3 cm（内科多可闭合）、3–6 cm、>6 cm（闭合慢、常需介入/手术）。"},"ddx":[{"name":"支气管扩张症","point":"与本类中支气管扩张症的鉴别点：肺脓肿为急性高热 + 单个厚壁空洞伴液平、脓臭痰；支扩为慢性反复咳脓痰、影像以气道扩张为主。支扩合并感染可形成空洞，需按肺脓肿思路延长抗厌氧菌疗程。"},{"name":"空洞型肺结核","point":"低热盗汗、病程长、上叶尖后段空洞壁薄、周围有卫星灶与树芽征，痰抗酸涂片/结核核酸阳性；肺脓肿为急性高热、厚壁空洞伴液平。"},{"name":"肺癌伴空洞形成","point":"中老年、消瘦、吸烟，空洞壁厚而不规则、偏心、内壁结节、无或少量液平，抗感染后不缩小；需支气管镜与穿刺活检。"},{"name":"肺囊肿继发感染","point":"既往已知肺囊肿（薄壁、均匀圆形），囊壁薄而光滑，感染时囊内出现液平；抗感染后壁仍薄。"},{"name":"肺真菌球/侵袭性肺曲霉病","point":"免疫抑制宿主，空洞内见可移动球形病灶（新月征），GM 试验阳性；影像多变，需抗真菌治疗。"},{"name":"隔离肺/先天性肺畸形感染","point":"青年、反复同一部位感染，增强 CT 见异常体循环动脉供血；明确后需手术切除。"}],"tx":{"drug":[{"name":"阿莫西林/克拉维酸（初始经验）","dose":"1.2 g 静滴 q8h（或 1.0 g 口服 bid，病情稳定后序贯）","note":"覆盖多数口腔厌氧菌与链球菌，为吸入性肺脓肿的经验首选之一","renal":"CrCl <30 mL/min 减量或延长间隔","hepatic":"肝功能异常者慎用","interact":"与华法林合用可延长 INR"},{"name":"克林霉素","dose":"600–900 mg 静滴 q8h（序贯 300 mg 口服 q8h）","note":"对厌氧菌（尤其拟杆菌属）与金葡菌均有活性；我国部分厌氧菌对其耐药率较高，需药敏","renal":"无需调整","hepatic":"严重肝功能不全者减量","interact":"与大环内酯类拮抗；与神经肌肉阻滞剂合用增强阻滞"},{"name":"莫西沙星（替代/序贯）","dose":"0.4 g 静滴/口服 qd","note":"覆盖部分厌氧菌及肺炎链球菌、非典型病原，可作序贯口服；产超广谱 β-内酰胺酶风险者不宜","renal":"肾功能不全无需调整","hepatic":"Child-Pugh C 慎用","interact":"延长 QT，禁与胺碘酮合用"},{"name":"头孢哌酮/舒巴坦（重症或医院获得性）","dose":"2–3 g 静滴 q8h","note":"覆盖革兰阴性菌与部分厌氧菌，适用于重症、合并脓胸或院内获得感染者","renal":"CrCl <30 mL/min 需减量","hepatic":"肝功能障碍者监测凝血功能，必要时补充维生素 K","interact":"与华法林合用增加出血"},{"name":"甲硝唑（联合覆盖厌氧菌）","dose":"0.5 g 静滴 q8h（或 0.4 g 口服 tid）","note":"与 β-内酰胺联合强化厌氧菌覆盖，尤其脓液异味明显或拟杆菌感染","renal":"CrCl <30 mL/min 减量","hepatic":"严重肝病者减量","interact":"与酒精合用致双硫仑样反应"},{"name":"万古霉素（疑似金葡菌/血源性）","dose":"15–20 mg/kg 静滴 q8–12h，按 AUC 400–600 mg·h/L 或谷浓度调整","note":"血源性肺脓肿、静脉药瘾者、MRSA 高风险者经验覆盖；需 TDM","renal":"按 CrCl 调整并 TDM","hepatic":"无需调整","interact":"与哌拉西林/他唑巴坦、氨基糖苷类合用肾毒性叠加"}],"nonDrug":["体位引流：按脓肿部位取高位引流（如舌叶脓肿取仰卧略低位、下叶背段取俯卧头低位），每日 2–3 次，每次 15–20 分钟，配合雾化化痰与拍背","疗程 6–8 周，直至体温正常、症状消失、影像上空洞缩小或仅留薄壁稳定（不能以影像完全吸收为停药标准）","脓胸或脓肿破入胸腔者行胸腔置管引流，必要时胸腔内注射尿激酶促引流","介入治疗：经皮穿刺抽脓/置管引流（空洞 ≥6 cm、内科治疗 2 周无效）；支气管镜下引流与灌洗","外科手术：内科治疗 ≥3 个月空洞不闭合、反复大咯血、合并支气管胸膜瘘或需鉴别肺癌者，行肺叶切除","处理原发病：牙科治疗、改善吞咽功能、控制癫痫、解除支气管阻塞"],"life":["戒烟限酒；卧床或意识障碍者床头抬高 30°，加强口腔护理","治疗期间加强营养支持（高蛋白），监测体重与白蛋白","规律服药与复诊：每 2–4 周复查影像，不可自行停药，否则易慢性化","出现大量咯血或突发气促、胸痛（疑似支气管胸膜瘘）立即就诊"]},"prog":"规范抗感染并有效引流后，约 80%–90% 的急性肺脓肿可痊愈；空洞闭合多在 2–3 个月内。老年、免疫抑制、空洞 >6 cm、合并脓胸或延误治疗者易转为慢性肺脓肿，需外科处理。院内感染或血源性者病死率可达 10%–20%。","refs":["《内科学》第 9 版 第二篇 肺脓肿","中华医学会呼吸病学分会《社区获得性肺炎诊断和治疗指南》（2016）","中国医师协会呼吸医师分会《吸入性肺炎诊治中国专家共识》（2020）","IDSA/ATS《成人医院获得性肺炎与呼吸机相关性肺炎管理指南》（2016）"]},{"id":"resp_tb","name":"肺结核","aka":["Pulmonary Tuberculosis","PTB","肺结核病"],"rank":3,"basic":{"define":"由结核分枝杆菌引起的肺部慢性传染病，病理上以干酪样坏死、结核结节与空洞形成为特征；按病情分为原发型、血行播散型、继发型（浸润性、纤维空洞性、结核球）、结核性胸膜炎等类型。","risk":["与活动性肺结核患者密切接触（家庭、集体宿舍、医疗机构）","HIV 感染与 CD4 <200/µL、糖尿病、矽肺、慢性肾功能不全与透析","长期糖皮质激素或生物调节剂（TNF-α 抑制剂）治疗、器官移植后免疫抑制","营养不良、酗酒、吸烟、老年低体重、恶性肿瘤化疗中","既往结核病史（复发/再燃）、未经规律治疗者"],"epi":"我国为全球结核病高负担国家之一，每年新发结核病患者约 70 余万例，结核病年发病率约 50–60/10 万；其中肺结核占 85% 以上。规范治疗者治愈率可达 90% 以上；原发耐多药率与利福平耐药率需持续监测。"},"patho":"结核分枝杆菌经飞沫核吸入后由肺泡巨噬细胞吞噬却不能杀灭，细菌在细胞内繁殖并诱导 Th1 型细胞免疫（CD4⁺ T 细胞释放 IFN-γ），3–6 周形成由上皮样细胞、朗汉斯巨细胞包裹的肉芽肿与干酪样坏死。免疫缺陷时干酪样物质液化形成空洞，细菌经支气管播散（树芽征、对侧播散）；反复破坏后形成毁损肺（大面积纤维空洞、肺容积缩小，常合并支气管扩张、曲霉球、反复咯血与呼吸衰竭）。","dx":{"criteria":["病原学阳性肺结核：以下任一项阳性①痰涂片抗酸（或荧光）染色阳性；②结核分枝杆菌培养阳性；③结核分枝杆菌核酸检测（PCR/MTB-DNA、Xpert MTB/RIF）阳性。","病原学阴性肺结核：典型临床与影像表现、排除其他诊断，并结合 IGRA/T-SPOT 及诊断性治疗。","典型影像：上叶尖后段、下叶背段好发；渗出性斑片影、结节、干酪性空洞（壁较薄、内壁光滑）、树芽征、卫星灶；血行播散型呈弥漫性大小均匀粟粒状结节（“三均匀”）。","全身中毒症状：午后低热、盗汗、乏力、消瘦、月经失调；呼吸道症状：咳嗽 >2 周、咳血丝痰；咯血常见且可致命。","分期：进展期（新出现或增大）、好转期（吸收缩小）、稳定期（空洞闭合、病灶稳定 ≥6 个月且痰菌阴性 ≥2 次）。","耐药评估：所有新发患者需做利福平耐药快速检测；耐多药结核病（MDR-TB）指同时耐异烟肼与利福平。"],"workup":["痰涂片 3 次（晨痰、夜间痰、即时痰）、痰培养 + 药敏（利福平、异烟肼、氟喹诺酮类）","结核分枝杆菌核酸检测、Xpert MTB/RIF Ultra（同时检测利福平耐药）","PPD 与 γ 干扰素释放试验（IGRA/T-SPOT）：辅助判断感染，不能区分潜伏与活动性","胸部 CT：评估空洞、毁损肺、支气管扩张、结核性胸膜炎；咯血者加做支气管动脉 CTA 与支气管镜","血气分析与肺功能：毁损肺评估呼吸储备","HIV 抗体筛查、血糖、肝肾功能（抗结核前基线）、视力与色觉（乙胺丁醇前）"],"grading":"按病原学：涂片阳性、培养阳性、病原学阴性、未痰检。按耐药：单耐药、多耐药、耐多药（MDR-TB）、准广泛耐药（pre-XDR）、广泛耐药（XDR）。按病情：初治（未接受抗结核治疗或治疗 <1 个月）、复治、慢性排菌（经 ≥2 个疗程仍痰菌阳性）。"},"ddx":[{"name":"肺脓肿","point":"与本类中肺脓肿的鉴别点：肺脓肿起病急、高热、脓臭痰、单个厚壁空洞伴明显液平；肺结核为慢性低热盗汗、尖后段薄壁空洞伴卫星灶，抗酸染色及结核核酸阳性。"},{"name":"非结核分枝杆菌肺病","point":"与本类中 NTM 肺病的鉴别点：影像几乎无法区分，但 NTM 多伴基础结构性肺病（支扩、旧结核）、抗酸涂片可为阳性而结核核酸阴性，需痰培养菌种鉴定。"},{"name":"肺真菌病（曲霉/隐球菌）","point":"曲霉球多见于既有结核空洞内，影像呈新月征；隐球菌结节多不形成大空洞，荚膜抗原阳性；GM 试验与抗原检测可鉴别。"},{"name":"支气管肺癌","point":"中老年吸烟、无中毒症状，影像见分叶毛刺肿块或偏心厚壁空洞，痰菌阴性；但肺癌可与结核并存、结核瘢痕亦可癌变，需随访与活检。"},{"name":"细菌性肺炎","point":"急性起病、高热、黄脓痰、病程短，抗生素 1–2 周吸收；影像无空洞与卫星灶，痰结核检查阴性。"},{"name":"尘肺/矽肺","point":"职业接触史，双肺弥漫小结节伴网状影、淋巴结蛋壳样钙化，痰菌阴性；可合并结核（尘肺结核）。"}],"tx":{"drug":[{"name":"异烟肼（H）","dose":"0.3 g 口服 qd（或 5 mg/kg，最大 0.3 g）","note":"杀菌剂，穿透力强；治疗前必查肝功能，用药后 2–4 周及每月监测；出现黄疸、乏力、食欲减退立即停药","renal":"肾功能不全者遵说明书减量或延长间隔","hepatic":"活动性肝病者禁用或慎用；合用利福平或饮酒者肝毒性增加","interact":"抑制 CYP 酶，升高苯妥英钠、华法林浓度；与酒精合用肝毒性显著增加"},{"name":"利福平（R）","dose":"体重 <50 kg：0.45 g qd；≥50 kg：0.6 g qd，空腹（餐前 1 小时）口服","note":"杀菌剂，可缩短疗程；尿、泪、痰呈橘红色为正常现象；疗程中监测肝功能与血常规","renal":"肾功能不全者无需调整剂量","hepatic":"严重肝功能不全或胆道梗阻者禁用","interact":"强效 CYP450/P-gp 诱导剂，显著降低口服避孕药、华法林、他汀、抗真菌药、抗病毒药浓度"},{"name":"吡嗪酰胺（Z）","dose":"25 mg/kg（体重 <50 kg：1.5 g qd；≥50 kg：2.0 g qd），强化期使用","note":"酸性环境杀菌，降低复发；可致高尿酸血症与痛风发作，监测尿酸；肝毒性在强化期最突出","renal":"CrCl <30 mL/min 慎用或减量并延长间隔","hepatic":"严重肝病者禁用","interact":"与他汀类合用肌病风险增加"},{"name":"乙胺丁醇（E）","dose":"15 mg/kg（体重 <50 kg：0.75 g；50–70 kg：1.0 g；>70 kg：1.25 g）qd","note":"抑菌剂；可致球后视神经炎与红绿色觉异常，用药前及每月查视力与色觉，异常立即停药","renal":"CrCl <30 mL/min 减量并延长间隔","hepatic":"无需调整","interact":"与乙硫异烟胺、利奈唑胺合用视神经毒性叠加"},{"name":"链霉素（S）","dose":"0.75 g 肌注 qd（体重 <50 kg 0.5 g）","note":"用于部分耐药方案强化期；耳毒性（前庭损害）与肾毒性明显，需监测听力与肌酐","renal":"肾功能不全者严格减量并监测血药浓度","hepatic":"遵说明书","interact":"与万古霉素、呋塞米等耳肾毒性药合用叠加"},{"name":"莫西沙星（耐多药方案 Mfx 组分）","dose":"0.4 g 口服/静滴 qd","note":"MDR-TB 长疗程方案核心药物之一；必须与至少其他 3 种有效药联合，绝不单药","renal":"无需调整","hepatic":"Child-Pugh C 慎用","interact":"延长 QT，禁与胺碘酮合用"},{"name":"贝达喹啉（耐多药方案 Bdq）","dose":"前 2 周 400 mg qd，之后 200 mg 每周 3 次（隔日方案遵指南）","note":"仅用于 MDR-TB 方案，需结核病专科管理；监测 QTc 与肝酶","renal":"轻中度无需调整；重度/透析遵说明书","hepatic":"中重度肝功能不全者慎用","interact":"CYP3A4 底物，强效诱导剂（利福平）降低其浓度"},{"name":"维生素 B6（吡哆醇）","dose":"10–25 mg 口服 qd","note":"与异烟肼同用预防周围神经炎，营养不良、糖尿病、酗酒者尤为重要","renal":"遵说明书","hepatic":"遵说明书","interact":"大剂量可降低左旋多巴疗效"},{"name":"垂体后叶素（大咯血）","dose":"6–12 U 加入 20–40 mL 葡萄糖缓慢静推，继以 12–24 U 加入 250–500 mL 液体持续静脉泵入","note":"毁损肺大咯血时内科止血首选药物；高血压与冠心病者禁用或极低剂量谨慎使用","renal":"遵说明书","hepatic":"遵说明书","interact":"与缩宫素、麦角类合用升压反应增强"}],"nonDrug":["标准初治方案 2HRZE/4HR：强化期异烟肼+利福平+吡嗪酰胺+乙胺丁醇 2 个月，继续期异烟肼+利福平 4 个月（共 6 个月），每日服药，不可间歇漏服","复治/耐药者按国家结核病防治方案由专科制定（MDR-TB 长疗程 ≥18–20 个月或短疗程 9–12 个月方案，含贝达喹啉、氟喹诺酮等）","大咯血：患侧卧位、畅通气道；支气管动脉栓塞术为首选止血；出血部位局限且内科与栓塞失败者行外科切除","毁损肺：反复感染、大咯血或合并曲霉球、支气管胸膜瘘者，充分抗结核后择期肺叶或全肺切除","结核性胸膜炎伴中大量积液者胸腔穿刺/置管引流，减少胸膜增厚粘连","法定传染病报告：疑似或确诊肺结核须 24 小时内网络直报；密切接触者筛查与潜伏感染预防性治疗"],"life":["规律服药、按时复查：治疗 2 个月末查痰涂片与培养，之后每月查痰与肝功能，疗程结束复查影像","全程禁酒，避免肝毒性药物；出现皮肤黄染、酱油色尿、视力变化、耳鸣立即复诊","与家人分室或通风良好处居住，咳嗽掩口鼻、戴口罩，痰液消毒处理；强化期传染性最强","加强营养（高蛋白、高维生素），保证充足睡眠与体重回升","治愈后每年随访 1–2 年，注意复发与毁损肺相关咯血"]},"prog":"初治菌阳肺结核规范化疗 6 个月治愈率可达 90%–95%；复治与耐多药者治愈率明显降低（MDR-TB 全球治疗成功率约 60%）。我国结核病病死率仍以晚期就诊、毁损肺合并大咯血/呼吸衰竭为主要死因；糖尿病与 HIV 共感染、治疗不规律者复发率高。","refs":["《内科学》第 9 版 第二篇 肺结核","中华医学会结核病学分会《肺结核诊断和治疗指南》（2018）","国家卫生健康委员会《结核病诊疗规范（2018 年版）》","WHO《Global Tuberculosis Report 2023》与《结核病整合指南（2022 模块 4：治疗）》"]},{"id":"resp_ntm","name":"非结核分枝杆菌肺病","aka":["Nontuberculous Mycobacterial Lung Disease","NTM-PD","鸟-胞内分枝杆菌复合群肺病（MAC）"],"rank":4,"basic":{"define":"除结核分枝杆菌复合群与麻风分枝杆菌以外的分枝杆菌（非结核分枝杆菌，NTM）感染肺实质引起的慢性传染病；最常见病原为鸟-胞内分枝杆菌复合群（MAC）、脓肿分枝杆菌、堪萨斯分枝杆菌与龟分枝杆菌。","risk":["基础结构性肺病：支气管扩张（尤其“Lady Windermere 综合征”）、COPD、陈旧性肺结核、尘肺、肺间质纤维化","免疫缺陷：HIV（CD4 <50/µL）、抗 IFN-γ 自身抗体、器官移植后、长期激素与 TNF-α 抑制剂","长期胃食管反流与吸入、脊柱侧弯、漏斗胸等胸廓畸形","老年女性、低体重、身材细长","环境暴露：热水浴缸、水暖系统气溶胶、土壤粉尘"],"epi":"我国 NTM 在分枝杆菌培养阳性标本中的分离率逐年上升，部分机构已明显超过结核分枝杆菌的 10%；既往感染过结核、结构性肺病者为本病高危群体。NTM 人际传播证据有限，不作为法定传染病管理。"},"patho":"NTM 广泛存在于水与土壤环境，经吸入气溶胶或误吸进入气道后黏附于受损气道上皮并形成生物膜，逃避巨噬细胞杀伤。Th1 细胞免疫受损（抗 IFN-γ 自身抗体、HIV、免疫抑制剂）或结构性肺病（支扩、纤维空洞）时局部清除力下降，形成多发结节、树芽征、空洞与支扩样改变；纤维空洞型病变多见于既往吸烟与 COPD 男性，进展更快、预后较差。","dx":{"criteria":["临床：慢性咳嗽、咳痰 ≥3 个月，乏力消瘦，或反复加重而抗结核治疗无效；影像与临床均不能单独确诊。","影像两种主要表型：①结节性支扩型——双肺中叶/舌叶为主的多发小结节、树芽征伴柱状或囊状支扩；②纤维空洞型——上叶为主的纤维化、厚壁空洞、胸膜增厚，类似肺结核。","微生物学（ATS/ERS/ESCMID/IDSA 2007 与 2020 更新）须同时满足：①有相应临床症状或影像异常；②至少 2 次痰培养阳性（或 1 次支气管灌洗液培养阳性）；③排除其他可解释的疾病。","菌种鉴定与药敏：16S rRNA、hsp65、rpoB 测序或线性探针；MAC 测克拉霉素敏感度，脓肿分枝杆菌测克拉霉素与阿米卡星敏感度，堪萨斯分枝杆菌测利福平敏感度。","鉴别结核：结核分枝杆菌核酸检测（PCR/Xpert）阴性而抗酸涂片阳性是重要提示；IGRA 阳性不能排除 NTM。"],"workup":["痰抗酸涂片 + 分枝杆菌培养（固体/液体）+ 菌种鉴定（至少 2 份标本）","结核分枝杆菌核酸检测（排除结核）、IGRA","胸部高分辨率 CT：结节、树芽征、支扩、空洞与纤维化范围","支气管镜检查 + 支气管肺泡灌洗（无法咳痰或痰阴性时）","免疫评估：HIV 抗体、血清 IgG、抗 IFN-γ 自身抗体（成人起病且无明确危险因素的多发结节性支扩者）","肺功能与血气：评估气流受限与呼吸储备"],"grading":"按影像表型：结节性支扩型（预后较好）、纤维空洞型（进展快、病死率高）；按病原：MAC、脓肿分枝杆菌、堪萨斯、龟分枝杆菌等；MAC 分克拉霉素敏感与耐药。不良预后因素：BMI <18.5、空洞、全身炎症、快速进展。"},"ddx":[{"name":"肺结核","point":"与本类中肺结核的鉴别点：NTM 常有支扩/COPD/旧结核等基础病、双肺中叶舌叶结节性支扩，结核核酸与 Xpert 阴性，需 ≥2 次痰培养 NTM 阳性并菌种鉴定；肺结核有明确传染性且抗结核治疗有效。两者影像可高度重叠，必须靠培养与分子检测区分。"},{"name":"支气管扩张症","point":"与本类中支扩的鉴别点：支扩是结构诊断、NTM 是病原诊断；NTM 肺病常合并支扩但伴多发小结节与树芽征，反复痰培养 NTM 阳性；单纯支扩无结节播散。"},{"name":"肺脓肿","point":"急性高热、脓臭痰、厚壁空洞液平、厌氧菌为主；NTM 病程以月计、无液平，培养需 4–8 周才报告，易被误认作“慢性感染”。"},{"name":"肺真菌病（曲霉/隐球菌）","point":"曲霉球在既有空洞内形成新月征，GM 试验阳性；隐球菌荚膜抗原高滴度；真菌与分枝杆菌培养可区分。"},{"name":"尘肺","point":"职业粉尘接触史，双肺小结节伴网状影，痰分枝杆菌培养阴性；但尘肺是 NTM 的易感基础，需同时评估。"},{"name":"支气管肺癌","point":"肿块或结节伴纵隔淋巴结增大、无树芽征、PET/CT 高代谢；老年 NTM 患者可合并肺癌，须病理鉴别。"}],"tx":{"drug":[{"name":"阿奇霉素（MAC 方案核心）","dose":"500–600 mg 口服 qd（或 250 mg bid），与其他药物联合","note":"大环内酯是 MAC 肺病疗效基石；用药前须确认克拉霉素/阿奇霉素敏感，方案需 ≥3 种药物并含阿米卡星（静脉或雾化）","renal":"CrCl <30 mL/min 减量或延长给药间隔","hepatic":"严重肝功能不全者慎用","interact":"延长 QT；与华法林、他汀合用增加风险"},{"name":"利福布汀（MAC 方案）","dose":"300 mg 口服 qd（体重 <45 kg 或不能耐受时 150 mg qd）","note":"对 MAC 活性优于利福平、药物相互作用稍少；监测肝酶、中性粒细胞与葡萄膜炎","renal":"CrCl <30 mL/min 减至 150 mg qd 或隔日","hepatic":"严重肝病者慎用","interact":"CYP3A4 诱导剂，降低华法林、抗病毒药、激素浓度"},{"name":"乙胺丁醇（MAC 方案）","dose":"15 mg/kg 口服 qd","note":"MAC 方案第三药；定期查视力与色觉，出现异常立即停药","renal":"CrCl <30 mL/min 减量并延长间隔","hepatic":"无需调整","interact":"视神经毒性与利奈唑胺叠加"},{"name":"阿米卡星（重症/空洞/耐药）","dose":"静脉 15 mg/kg qd（按 AUC 或谷浓度 <5 mg/L 调整）；或雾化吸入 400 mg bid","note":"重症、空洞型或既往大环内酯治疗失败者加入 2–3 个月；雾化可减少全身毒性","renal":"按 CrCl 调整并 TDM","hepatic":"无需调整","interact":"与其他耳肾毒性药合用叠加"},{"name":"克拉霉素（大环内酯敏感者）","dose":"500 mg 口服 bid（体重 <50 kg 时 500 mg qd）","note":"与阿奇霉素二选一；克拉霉素耐药菌株不宜使用含大环内酯方案","renal":"CrCl <30 mL/min 减半","hepatic":"肝功能异常者慎用","interact":"强效 CYP3A4 抑制剂，与辛伐他汀、胺碘酮、秋水仙碱合用风险大"},{"name":"利奈唑胺（耐药/难治 MAC 或脓肿分枝杆菌）","dose":"600 mg 口服/静滴 qd–q12h，按耐受性与血液学指标调整","note":"骨髓抑制、周围与视神经病变风险高，每 2–4 周监测血常规与视力","renal":"无需调整","hepatic":"严重肝功能不全者慎用","interact":"与 SSRI 合用致 5-羟色胺综合征"},{"name":"替加环素（脓肿分枝杆菌重症）","dose":"首剂 100 mg 静滴，之后 50 mg q12h（住院评估下使用）","note":"脓肿分枝杆菌大环内酯耐药时考虑，常联合头孢西丁、阿米卡星；恶心呕吐常见","renal":"无需调整","hepatic":"Child-Pugh B/C 减量","interact":"延长凝血酶原时间，与华法林合用需加强监测"}],"nonDrug":["治疗指征：有症状且培养阳性者才需治疗；无症状或惰性者（尤其老年女性）可观察随访，避免“培养阳性即治疗”","MAC 方案：阿奇霉素（或克拉霉素）+ 利福布汀 + 乙胺丁醇，痰培养转阴后继续 12 个月，总疗程一般 15–18 个月；重症或空洞者强化期加静脉/雾化阿米卡星","脓肿分枝杆菌：克拉霉素敏感者用大环内酯 + 头孢西丁/亚胺培南 + 阿米卡星；大环内酯耐药者预后差、多需手术","疗程中每 1–3 个月复查痰培养，痰培养转阴是治疗有效的关键指标","外科切除：局限病变、大环内酯耐药、内科治疗失败或大咯血时行肺段/肺叶切除","同步治疗基础病：支扩气道清除、胃食管反流控制、减少不必要的免疫抑制","菌种鉴定前若结核不能排除，先按结核处理并隔离，避免延误"],"life":["避免接触热水浴缸、喷泉等气溶胶水源，室内保持通风干燥","长期气道清除（体位引流、OPEP）与充足营养；BMI 恢复与感染控制同等重要","遵嘱长期服药并每 2–4 周复查肝肾功能、血常规与视力；中途停药极易耐药复发","每 3–6 个月复查胸部 CT 与痰培养，评估疗效与是否需要手术"]},"prog":"结节性支扩型 MAC 规范三联治疗后约 50%–60% 可获得痰菌转阴，但复发/再感染率接近 30%；空洞纤维型、大环内酯耐药（尤其脓肿分枝杆菌）与免疫缺陷者预后差，5 年病死率可达 20%–40%。治疗耐受性差、中断治疗是主要失败原因。","refs":["中华医学会结核病学分会《非结核分枝杆菌肺病诊断和治疗指南》（2022 更新）","ATS/ERS/ESCMID/IDSA《Treatment of Nontuberculous Mycobacterial Pulmonary Disease: An Official Clinical Practice Guideline》（2020）","《内科学》第 9 版 第二篇 非结核分枝杆菌肺病"]},{"id":"resp_fungal","name":"肺真菌病（肺曲霉病与肺隐球菌病）","aka":["Pulmonary Fungal Infection","肺曲霉病","肺隐球菌病","Invasive Pulmonary Aspergillosis"],"rank":5,"basic":{"define":"真菌侵入肺组织或气道引起的感染性疾病。本节聚焦临床上最重要的两类：①肺曲霉病——侵袭性肺曲霉病（IPA）、慢性肺曲霉病（CPA，含曲霉球）与变应性支气管肺曲霉病（ABPA）；②肺隐球菌病——由新型隐球菌引起，可表现为孤立肺结节或播散性感染。","risk":["侵袭性肺曲霉病：持续中性粒细胞缺乏 ≥10 天、造血干细胞移植、实体器官移植、长期大剂量激素（泼尼松 ≥20 mg/d 超过 3 周）、血液系统恶性肿瘤、重型流感/COVID-19 后继发","慢性肺曲霉病：陈旧性结核空洞、支扩、COPD、肺间质病等结构性肺病","ABPA：哮喘与囊性纤维化患者","肺隐球菌病：HIV 感染（CD4 <100/µL）、器官移植后、长期激素治疗；我国逾半数为无明确基础疾病的免疫正常者","环境暴露：鸽粪、霉变谷物、施工粉尘与装修后潮湿环境"],"epi":"侵袭性肺曲霉病在血液科与 ICU 患者中发病率逐年上升，未治疗者病死率高达 50%–90%；肺隐球菌病多见于 40–60 岁男性，免疫正常者约占一半，常为体检发现的肺部结节。"},"patho":"曲霉孢子吸入后，正常宿主由肺泡巨噬细胞与中性粒细胞清除；中性粒细胞缺乏或激素抑制时孢子萌发成菌丝并侵袭血管，形成血栓性坏死与出血性梗死（影像晕轮征代表出血性梗死）。慢性肺曲霉病因空洞内黏膜清除障碍，菌丝在空腔内形成真菌球，可侵蚀血管致咯血。隐球菌厚荚膜抑制吞噬、逃避免疫识别，可经血行播散至中枢神经系统引起隐球菌脑膜炎。","dx":{"criteria":["侵袭性肺曲霉病（EORTC/MSGERC 2020 分层）：宿主因素 + 临床/影像表现 + 真菌学证据（GM 试验、G 试验、痰/灌洗液/血培养或 PCR）；典型影像为结节伴晕轮征、空洞内空气新月征、致密实变伴楔形梗死。","半乳甘露聚糖（GM）试验：血清或 BALF 的 OD 指数 ≥0.5（单次）或连续 ≥0.7 提示阳性；BALF 的敏感性与特异性优于血清。","慢性肺曲霉病：影像见空洞内真菌球 + 血清曲霉特异性 IgG（沉淀素）或曲霉 IgE 升高、培养阳性，伴慢性咳嗽、咯血与体重下降 ≥3 个月。","ABPA：哮喘史 + 血总 IgE >1000 IU/mL + 烟曲霉特异性 IgE 阳性 + 血清嗜酸性粒细胞 >500/µL + 中心性支扩或黏液栓（指套征）。","肺隐球菌病：血清隐球菌荚膜抗原（CrAg）乳胶凝集或侧流免疫层析阳性（滴度与播散相关），或肺组织病理见有荚膜酵母；无症状结节型 CrAg 可阴性，需活检确诊。","所有肺隐球菌者须腰穿查脑脊液（细胞数、蛋白、CrAg）排除隐球菌脑膜炎；HIV 者同时查 CD4。"],"workup":["胸部 CT（薄层）：晕轮征、新月征、空洞与真菌球；随访评估空洞变化","血清 GM 试验、G 试验（血清与 BALF），曲霉特异性 IgG/IgE，血隐球菌荚膜抗原","痰液与支气管肺泡灌洗液真菌涂片、培养（曲霉、隐球菌、毛霉）与药敏","血培养、血常规与中性粒细胞计数、免疫功能评估（HIV、IgG、淋巴细胞亚群）","肺隐球菌：头颅 MRI 与腰穿脑脊液隐球菌抗原与培养","病理：经支气管镜或 CT 引导穿刺活检（肉芽肿内菌丝或酵母）"],"grading":"肺曲霉病分型：侵袭性（IPA）、慢性（CPA，含曲霉球与慢性空洞性 CPA）、变应性（ABPA）。IPA 按确诊（proven）、临床诊断（probable）、拟诊（possible）分级。肺隐球菌病分：局限型（孤立结节/肺炎型）与播散型（合并脑膜炎、皮肤/骨病变）。"},"ddx":[{"name":"非结核分枝杆菌肺病","point":"与本类中 NTM 肺病的鉴别点：NTM 为慢性病程、影像以结节与树芽征 + 支扩为主、分枝杆菌培养阳性；曲霉球在既有空洞内形成可移动真菌球与新月征、曲霉 IgG 阳性；隐球菌结节需 CrAg 或病理鉴别。"},{"name":"肺结核","point":"结核空洞壁较薄、多伴卫星灶与树芽征，痰抗酸涂片阳性；但肺结核空洞是 CPA 最常见的前驱病变，两者可共存。"},{"name":"肺脓肿","point":"曲霉球不伴脓性痰与高热，空洞液平少见；急性肺脓肿为厚壁空洞 + 气液平 + 脓臭痰，抗真菌无效。"},{"name":"支气管肺癌","point":"隐匿型隐球菌结节可酷似肺癌，但 CrAg 阳性、PET 代谢相对低；仍需穿刺病理明确。"},{"name":"毛霉病","point":"糖尿病酮症酸中毒或免疫抑制者，影像多为中心性大实变、反晕轮征，鼻窦眼眶受累；曲霉与毛霉需病理/培养鉴别，药物不同。"},{"name":"支气管哮喘急性加重（ABPA 误诊）","point":"哮喘患者反复黏液栓、中心性支扩、总 IgE 显著升高、嗜酸性粒细胞增多与烟曲霉特异性 IgE 阳性提示 ABPA，治疗以激素为主。"}],"tx":{"drug":[{"name":"伏立康唑（侵袭性肺曲霉病首选）","dose":"负荷 6 mg/kg 静滴 q12h（首日 2 次），维持 4 mg/kg q12h 静滴；口服维持 200 mg q12h（体重 <40 kg 时 100 mg q12h）","note":"一线用药；建议 TDM（谷浓度 1–5.5 mg/L）；视觉异常、肝酶升高与 QT 延长为常见不良反应","renal":"CrCl <50 mL/min 时静脉制剂辅料蓄积，建议改用口服","hepatic":"轻中度肝功能不全者维持量减半；Child-Pugh C 慎用","interact":"CYP2C19/3A4 抑制剂与底物；禁与他汀、胺碘酮、特非那定合用；利福平、卡马西平显著降低其浓度"},{"name":"两性霉素 B 脱氧胆酸盐（重症/耐药/联合）","dose":"起始 0.1–0.25 mg/kg/d 静滴，逐日递增至 0.5–0.7 mg/kg/d（累积总剂量视病情 1.5–3 g）","note":"用 5% 葡萄糖稀释（禁用生理盐水），输注前补钾与抗过敏预处理；监测肌酐、血钾、血镁","renal":"肾毒性突出，CrCl 降低或肌酐翻倍时减量并水化补钾","hepatic":"肝功能异常者监测并减量","interact":"与氨基糖苷类、万古霉素、环孢素等肾毒性药叠加"},{"name":"两性霉素 B 脂质体（L-AmB）","dose":"3–5 mg/kg 静滴 qd","note":"肾毒性明显低于脱氧胆酸盐，推荐用于需长期大剂量者","renal":"仍需监测肌酐与电解质，必要时减量","hepatic":"遵说明书","interact":"同两性霉素 B"},{"name":"氟康唑（隐球菌巩固/维持）","dose":"肺隐球菌病（无脑膜炎、免疫正常）：400 mg 口服 qd，疗程 6 个月；播散性感染巩固期 400–800 mg qd","note":"隐球菌维持期药物，疗程取决于宿主免疫状态；隐球菌脑膜炎需先以两性霉素 B + 氟胞嘧啶诱导","renal":"CrCl 11–50 mL/min 减半；<11 mL/min 或透析遵说明书减量","hepatic":"严重肝功能不全者慎用","interact":"CYP 抑制剂，升高华法林、苯妥英、他汀与磺脲类浓度"},{"name":"伊曲康唑（慢性肺曲霉病）","dose":"胶囊 200 mg 口服 bid（或口服液 200 mg bid）","note":"CPA 一线口服药，需 TDM（谷浓度 >1 mg/L）；胶囊吸收依赖酸性环境，需随餐或酸性饮料服用","renal":"CrCl <30 mL/min 慎用","hepatic":"肝功能异常者慎用，治疗前与治疗中查肝酶","interact":"CYP3A4 抑制剂，与辛伐他汀、地高辛合用需警惕"},{"name":"氟胞嘧啶（5-FC，隐球菌联合）","dose":"25 mg/kg 口服 q6h（隐球菌脑膜炎诱导期联合两性霉素 B）","note":"必须联合用药，单药易耐药；监测骨髓抑制","renal":"按 CrCl 调整剂量并 TDM","hepatic":"肝功能异常者慎用","interact":"与两性霉素 B 联用可增强抗真菌效应"},{"name":"卡泊芬净（曲霉挽救/联合）","dose":"首日 70 mg 静滴，之后 50 mg qd","note":"用于伏立康唑不耐受、部分耐药或联合治疗；对隐球菌无效","renal":"无需调整","hepatic":"Child-Pugh B 减至 35 mg qd；C 慎用","interact":"与环孢素合用肝毒性增加"}],"nonDrug":["侵袭性肺曲霉病疗程依免疫抑制持续时间与影像吸收而定（一般 6–12 周以上）；持续中性粒细胞缺乏者需更长","慢性肺曲霉病：伊曲康唑/伏立康唑口服 ≥6 个月，评估影像与症状；空洞反复咯血者行支气管动脉栓塞","手术：单发曲霉球反复大咯血、内科与介入止血失败，或局限病灶内科无效者行肺叶切除（需评估肺功能并术中抗真菌覆盖）","肺隐球菌病（免疫正常、孤立结节、无中枢受累）：氟康唑 400 mg qd 口服 6 个月，每 2–3 个月复查 CrAg 与影像","肺隐球菌脑膜炎：两性霉素 B 脂质体 + 氟胞嘧啶诱导 2 周，氟康唑巩固 8 周，HIV 者维持至 CD4 >100/µL 持续 ≥12 个月","减少免疫抑制：G-CSF、调整激素与免疫抑制剂是 IPA 治疗关键环节；ABPA 用泼尼松 0.5 mg/kg/d 2 周后逐渐减量 + 伊曲康唑","环境控制：住院高危患者使用层流病房、HEPA 过滤与防霉措施"],"life":["避免接触霉变谷物、鸽粪、装修粉尘与潮湿发霉的墙面/空调","使用伏立康唑期间避免强光直晒（光敏反应），定期查视力与皮肤","长期抗真菌者每 2–4 周复查肝肾功能与电解质；疗程内不可自行停药","免疫抑制患者出现发热伴肺部影像改变需立即就诊，不可等待培养结果","严格控制血糖（糖尿病是多种真菌感染的重要危险因素）"]},"prog":"侵袭性肺曲霉病是免疫抑制患者的主要致死性感染，未治疗者病死率近 100%，规范治疗后降至 30%–50%；慢性肺曲霉病 5 年病死率约 50%–85%，反复咯血与呼吸衰竭为主要死因。免疫正常者的肺隐球菌病预后良好，氟康唑 6 个月治愈率 >90%；合并中枢播散者病死率仍达 15%–30%。","refs":["中华医学会呼吸病学分会《肺真菌病诊断和治疗专家共识》（2017）","中华医学会器官移植学分会《中国实体器官移植受者侵袭性真菌病临床诊疗规范》（2019）","《慢性肺曲霉病诊治中国专家共识》（2023）","IDSA《Practice Guidelines for the Diagnosis and Management of Aspergillosis》（2016）","IDSA《Clinical Practice Guidelines for the Management of Cryptococcal Disease》（2010）"]}]},{"id":"ild","name":"间质性肺病与其他","rank":6,"summary":"以“多学科诊断（MDD）+ HRCT 表型”为框架：先通过病史（职业/环境暴露、用药、结缔组织病表现、家族史）与 HRCT 将 ILD 分为 UIP、NSIP、机化性肺炎、过敏性肺炎等表型，再由多学科讨论决定是否需外科肺活检；确诊 IPF 后以抗纤维化治疗、肺康复与氧疗为主，免疫抑制仅在特定表型（NSIP、机化性肺炎、结节病）中使用。胸腔积液与气胸则按“漏出 vs 渗出、闭合 vs 开放、抽气 vs 引流”的决策链处理。","compare":[{"diseaseId":"ild_ipf","dx":"≥60 岁男性、渐进性劳力性气促 + 双下肺底爆裂音，HRCT 呈 UIP 型（胸膜下/基底为主的蜂窝肺、牵拉性支扩）","key":"UIP 型 HRCT 是诊断核心；抗纤维化药物延缓 FVC 下降，激素无效且有害"},{"diseaseId":"ild_sarcoid","dx":"青年女性、无症状或干咳气促，双肺门对称性淋巴结肿大 + 沿淋巴管走行的小结节（Scadding 分期 I–IV）","key":"结节沿支气管血管束与胸膜下分布、双侧肺门淋巴结对称肿大；有症状或脏器功能受损时才是激素指征"},{"diseaseId":"ild_hypersensitivity","dx":"明确的有机粉尘/化学暴露（鸟禽、霉变、加湿器），HRCT 见弥漫磨玻璃影 + 小叶中心结节 + 空气潴留","key":"暴露史 + 远离抗原后改善；以抗原回避为核心，慢性纤维化进展者考虑抗纤维化"},{"diseaseId":"ild_pleural_effusion","dx":"胸闷气促伴患侧叩诊浊音、呼吸音减低，X 线见肋膈角变钝/外高内低弧形影；Light 标准区分漏出与渗出","key":"先判断漏出还是渗出，再按渗出液病因（结核、肿瘤、肺炎）针对性检查；不明原因需胸膜活检"},{"diseaseId":"ild_pneumothorax_med","dx":"突发单侧胸痛与呼吸困难，患侧呼吸音消失、叩诊鼓音，X 线见肺压缩带与胸膜线","key":"按大小与症状分级：小量闭合性首选抽气观察，大量/张力性/复发性需闭式引流，复发者胸膜固定"}],"diseases":[{"id":"ild_ipf","name":"特发性肺纤维化","aka":["Idiopathic Pulmonary Fibrosis","IPF","特发性间质性肺炎（IIP）之一"],"rank":1,"basic":{"define":"原因不明、以慢性进行性纤维化性间质性肺病为特征的特发性间质性肺炎，病理与影像表现为普通型间质性肺炎（UIP）；多见于中老年男性，确诊后中位生存 3–5 年。","risk":["年龄 >60 岁、男性、吸烟（含既往吸烟）","职业粉尘暴露：金属粉尘、木屑、石棉、二氧化硅","慢性胃食管反流（误吸）","遗传易感：TERT、TERC、SFTPC 等基因变异、家族性 IPF","环境暴露与病毒（EB 病毒）感染"],"epi":"IPF 患病率随年龄显著上升，估计 50–70/10 万，65 岁以上可达 200/10 万以上；男性多于女性，确诊时中位年龄约 65 岁。我国尚无确切流行病学登记数据，但门诊与住院病例逐年增加。"},"patho":"反复的肺泡上皮微小损伤（易感基因、吸烟、胃食管反流、环境暴露共同作用）启动异常修复反应：上皮细胞分泌 TGF-β、PDGF、FGF 等促纤维化因子，成纤维细胞/肌纤维母细胞在胸膜下区域增殖形成成纤维细胞灶，细胞外基质过度沉积。组织收缩形成牵拉性支气管扩张与蜂窝肺，肺泡-毛细血管弥散屏障增厚导致劳力性低氧，晚期出现肺动脉高压与右心衰。","dx":{"criteria":["诊断前提：排除其他已知原因的 ILD（暴露、结缔组织病、药物性等），尤其需排查结缔组织病相关 ILD 与慢性纤维化型过敏性肺炎。","IPF 诊断需满足：①UIP 型 HRCT，或 UIP 型病理 + 相应 HRCT 表型；②排除其他 ILD 病因。","UIP 型 HRCT（ATS/ERS/JRS/ALAT 2018）需同时具备：病变以胸膜下、基底段为主；网格影；蜂窝肺伴或不伴牵拉性支扩；且无不符合 UIP 的特征（广泛磨玻璃影、远离蜂窝区的明显实变、弥漫微结节、囊性病变、马赛克灌注）。","临床：渐进性劳力性气促（mMRC 进行性加重）、干咳、双下肺底爆裂音（Velcro 啰音）、杵状指；≥6 个月缓慢进展最典型。","肺功能：限制性通气障碍（TLC 下降）、DLCO 降低；FVC 年下降 >10% 预计值或 DLCO 下降 >15% 提示快速进展。","急性加重（AE-IPF）：临床恶化 ≤1 个月，HRCT 新出现双肺弥漫磨玻璃影/实变，不能用感染、心衰或栓塞解释。"],"workup":["高分辨率 CT（肺窗与纵隔窗）：UIP 型判断核心；建议 6–12 个月复查对比进展","肺功能（含 TLC 与 DLCO）+ 6 分钟步行试验（含血氧监测）","结缔组织病筛查：ANA、抗 CCP、抗 SSA/SSB、类风湿因子、肌炎抗体谱","职业与环境暴露史、用药史、反流症状与睡眠呼吸筛查","外科肺活检（VATS）：HRCT 不典型且需鉴别时可考虑，但高龄与肺功能差者风险高；经支气管冷冻活检可作为替代","多学科讨论（MDD）：呼吸科、影像科、病理科共同作出最终诊断"],"grading":"HRCT 表型：UIP 型、可能 UIP（probable UIP）、不确定 UIP、不符合 UIP。功能分级：轻度（FVC ≥75% 预计值、DLCO ≥55%）、中度（FVC 55%–75%、DLCO 35%–55%）、重度（FVC <55%、DLCO <35%）。"},"ddx":[{"name":"过敏性肺炎（慢性纤维化型）","point":"与本类中过敏性肺炎的鉴别点：HP 常有明确抗原暴露、影像见小叶中心结节与空气潴留，脱离抗原后稳定；IPF 无暴露史、以蜂窝肺为标志，FVC 持续下降。"},{"name":"结节病Ⅳ期","point":"与本类中结节病的鉴别点：结节病多为青年女性、上叶为主的沿支气管血管束结节与支气管周围纤维化，可伴双侧肺门淋巴结肿大；IPF 为下肺为主的蜂窝肺。"},{"name":"结缔组织病相关 ILD（RA-ILD、SSc-ILD）","point":"有雷诺现象、关节肿痛、皮肤改变、抗 CCP/ANA/肌炎抗体阳性；UIP 型 RA-ILD 影像可与 IPF 完全一致，必须筛查自身抗体。"},{"name":"石棉肺/尘肺","point":"明确职业接触史、胸膜斑与钙化、上叶为主的结节影；IPF 为胸膜下蜂窝肺且无胸膜斑。"},{"name":"慢性心衰伴间质性肺水肿","point":"劳力性气促 + 夜间阵发性呼吸困难，BNP/NT-proBNP 升高、心影增大，利尿后浸润迅速改善。"},{"name":"非特异性间质性肺炎（NSIP）","point":"影像以下叶为主的磨玻璃影与网格影、蜂窝肺少见，激素/免疫抑制剂治疗反应好；IPF 以蜂窝肺为主且激素无效。"}],"tx":{"drug":[{"name":"吡非尼酮","dose":"起始 267 mg 口服 tid（第 1 周），第 2 周 534 mg tid，第 3 周起维持 801 mg tid（日总量 2403 mg）","note":"延缓 FVC 下降的标准化抗纤维化药物；与食物同服可减轻恶心；前 3 个月每月查肝酶，之后每 3 个月；需长期维持","renal":"轻中度肾功能不全无需调整；严重肾功能不全慎用","hepatic":"中重度肝功能不全者不推荐；转氨酶 >3 倍正常上限伴胆红素升高时停药","interact":"强效 CYP1A2 抑制剂（氟伏沙明）、依诺沙星可显著升高血药浓度"},{"name":"尼达尼布","dose":"150 mg 口服 bid；耐受性差时减至 100 mg bid","note":"延缓 FVC 下降；腹泻最常见（约 60%），给予止泻与补液可改善耐受；与食物同服减少胃部不适","renal":"轻中度无需调整；重度肾功能不全慎用","hepatic":"Child-Pugh B 减至 100 mg bid；Child-Pugh C 不推荐","interact":"P-gp 抑制剂（酮康唑等）可升高浓度；强效 CYP3A4 抑制剂需慎用"},{"name":"乙酰半胱氨酸（抗氧化，辅助）","dose":"600 mg 口服 tid","note":"可作为辅助治疗，证据强度弱于吡非尼酮/尼达尼布，不宜替代抗纤维化药","renal":"遵说明书","hepatic":"遵说明书","interact":"与强力镇咳药、活性炭合用降低疗效"},{"name":"泼尼松 + 硫唑嘌呤 + N-乙酰半胱氨酸（不推荐用于 IPF）","dose":"泼尼松 0.5 mg/kg/d 逐渐减量 + 硫唑嘌呤 2 mg/kg/d（该经典三联方案已被证实增加病死率与住院，IPF 中不推荐）","note":"列出仅为警示：IPF 不作为常规激素适应证；仅在急性加重或合并其他疾病时短程使用激素","renal":"硫唑嘌呤在肾功能不全时需减量","hepatic":"硫唑嘌呤肝功能异常者慎用","interact":"硫唑嘌呤与别嘌醇合用需大幅减量"},{"name":"奥美拉唑（合并胃食管反流时）","dose":"20 mg 口服 qd–bid（或同类 PPI）","note":"减轻误吸相关上皮损伤；仅在合并反流症状或客观证据时使用，不作为 IPF 常规治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"与伏立康唑、氯吡格雷合用影响疗效"}],"nonDrug":["长期家庭氧疗：静息或运动时 SpO₂ ≤88%（或 PaO₂ ≤55 mmHg，或 <60 mmHg 伴肺心病）者每日 ≥15 小时","肺康复训练：改善 6 分钟步行距离与呼吸困难评分，是综合管理的一部分","肺移植评估：≤65–70 岁、FVC 下降快、DLCO <40% 或伴肺动脉高压进展者应尽早评估","抗纤维化药物长期维持与剂量滴定：不能随意停药，停药常伴 FVC 快速下降","合并肺动脉高压（右心导管确诊）者按肺高血压流程治疗；合并胃食管反流与睡眠呼吸暂停需同步处理","急性加重：寻找诱因（感染、误吸、栓塞），给予氧疗、短程激素、必要时无创通气与抗感染"],"life":["戒烟、避免粉尘及有害气体暴露，做好职业防护","每天家庭氧疗按时长使用，便携式氧疗便于外出活动","家中监测指尖 SpO₂ 与体重变化；气促评分或 6 分钟步行距离下降及时复诊","规律服用抗纤维化药，每 3–6 个月复查肝肾功能与肺功能","加强营养、接种流感与肺炎球菌疫苗（感染是急性加重最常见诱因）"]},"prog":"IPF 为不可逆的进行性纤维化疾病，确诊后中位生存 3–5 年；死亡主因为呼吸衰竭、急性加重与合并症（肺癌、肺动脉高压、心血管事件）。抗纤维化治疗可延缓 FVC 下降约 50%，但无法逆转纤维化；肺移植可显著改善生存。","refs":["中华医学会呼吸病学分会《特发性肺纤维化诊断和治疗中国专家共识》（2016）","ATS/ERS/JRS/ALAT《Diagnosis of Idiopathic Pulmonary Fibrosis: An Official Clinical Practice Guideline》（2018）","ATS/ERS/JRS/ALAT《Treatment of IPF: An Official Clinical Practice Guideline》（2022）","《内科学》第 9 版 第二篇 间质性肺疾病"]},{"id":"ild_pleural_effusion","name":"胸腔积液","aka":["Pleural Effusion","胸水","胸腔积液鉴别诊断"],"rank":2,"basic":{"define":"胸膜腔内液体产生超过吸收所致的异常聚积，可为漏出液或渗出液；是多种系统疾病（心衰、肝硬化、结核、恶性肿瘤、肺炎）的常见共同表现，诊断的关键在于明确病因。","risk":["心力衰竭、肝硬化、低蛋白血症、肾病综合征（漏出液）","结核性胸膜炎（我国最常见的渗出性病因之一）","肺癌、乳腺癌、淋巴瘤与间皮瘤等恶性肿瘤胸膜转移","肺炎旁胸腔积液与脓胸","肺栓塞、胰腺炎、结缔组织病","药物性（胺碘酮、甲氨蝶呤、达沙替尼）、石棉暴露"],"epi":"心力衰竭与肺炎是我国住院患者最常见的胸腔积液病因，结核性胸膜炎在青壮年中占比高；恶性胸腔积液在肿瘤患者中发生率约 15%，以肺癌与乳腺癌最常见。"},"patho":"漏出液由系统性因素造成：静水压升高（心衰）、胶体渗透压降低（低蛋白血症、肝硬化）或淋巴回流受阻；渗出液由局部胸膜炎症或肿瘤侵犯导致毛细血管通透性增加、淋巴引流阻塞，伴蛋白与细胞成分外漏。结核性胸膜炎为迟发型超敏反应性渗出，脓胸则为细菌直接感染形成的脓性积液。","dx":{"criteria":["Light 标准（符合任一项即为渗出液）：①胸水总蛋白/血清总蛋白 >0.5；②胸水 LDH/血清 LDH >0.6；③胸水 LDH >血清 LDH 正常上限的 2/3。三项全不符合为漏出液。","辅助指标：胸水蛋白梯度（血清总蛋白 − 胸水总蛋白）>31 g/L 提示漏出液；胸水/血清白蛋白梯度 <12 g/L 提示渗出液。","外观与生化：脓性（脓胸）、血性（肿瘤、结核、创伤、肺栓塞；红细胞 >10 万/µL 即血胸）、乳糜状（乳糜胸，TG >1.24 mmol/L）、黏稠（间皮瘤透明质酸）。","胸水葡萄糖 <3.3 mmol/L 提示结核、类风湿、脓胸或恶性肿瘤；pH <7.20 与 LDH >1000 U/L 提示复杂性肺炎旁积液或脓胸，需引流。","结核性胸膜炎：胸水腺苷脱氨酶（ADA）>40 U/L、胸水 IFN-γ 升高、胸水结核核酸与培养（涂片阳性率低）；胸膜活检阳性率最高。","恶性积液：胸水细胞学（首次约 60%），重复穿刺可提高阳性率；肿瘤标志物与胸膜活检（胸腔镜首选）"],"workup":["胸部 X 线与胸部 CT：评估积液量、有无肺实变/肿块、纵隔淋巴结与胸膜增厚结节","胸部超声：定位穿刺点、估算积液量、评估分隔与胸膜病变","胸腔穿刺（20–50 mL）：常规（细胞数、分类）、蛋白、LDH、葡萄糖、ADA、CEA/肿瘤标志物、结核核酸与培养、细菌涂片与培养、细胞学","必要时血气（胸水 pH）、乳糜试验、淀粉酶（胰腺炎/食管破裂）、类风湿因子","胸膜活检（超声/CT 引导经皮穿刺）与内科胸腔镜（直视下活检，结核与恶性病因诊断率 >90%）","漏出液者重点查心功能（BNP、超声心动图）、肝功能、白蛋白、尿蛋白"],"grading":"按性质：漏出液/渗出液/脓胸/血胸/乳糜胸。按量：少量（<500 mL 或仅肋膈角变钝）、中量（500–1500 mL 或不超过第 6 后肋间）、大量（>1500 mL 或超过第 6 后肋间、伴纵隔移位）。按病因：感染性（肺炎旁、结核、脓胸）、肿瘤性、心源性、肝源性、其他。"},"ddx":[{"name":"自发性气胸","point":"与本类中气胸的鉴别点：气胸叩诊鼓音、呼吸音完全消失，X 线见胸膜线外无肺纹理；胸腔积液为叩诊浊音、语颤减弱、无胸膜线，超声见无回声区。"},{"name":"心力衰竭（漏出液）","point":"多为双侧、右多于左，伴颈静脉怒张、BNP 升高与心影增大；利尿后减少，Light 标准符合漏出液。"},{"name":"结核性胸膜炎","point":"青壮年、午后低热盗汗，胸水 ADA >40 U/L、淋巴细胞为主，胸膜活检见干酪性肉芽肿；需与恶性积液靠细胞学与活检鉴别。"},{"name":"恶性胸腔积液","point":"中老年、消瘦、胸水增长迅速，大量或包裹、血性，胸水 CEA 升高，细胞学阳性；胸膜活检/胸腔镜可确诊。"},{"name":"肺炎旁积液与脓胸","point":"发热、脓痰、肺部实变，胸水中性粒细胞为主、pH <7.20、LDH >1000 U/L、葡萄糖低，可培养出致病菌；需引流。"},{"name":"肺栓塞（胸膜性胸痛）","point":"突发胸痛气促伴少量胸腔积液，D-二聚体与 CTPA 阳性；积液多为渗出液，抗凝治疗后吸收。"}],"tx":{"drug":[{"name":"呋塞米（心衰漏出液）","dose":"20–40 mg 口服 qd（或静推 20–40 mg），按尿量与体重调整","note":"漏出液以治疗原发病为主，不常规胸腔穿刺抽液；利尿需监测电解质","renal":"肾功能不全者可能需要更高剂量","hepatic":"肝硬化者需联合螺内酯并监测血氨","interact":"与氨基糖苷类合用耳毒性增加"},{"name":"抗结核方案（结核性胸膜炎：2HRZE/4HR）","dose":"异烟肼 0.3 g qd + 利福平 0.45–0.6 g qd + 吡嗪酰胺 1.5–2.0 g qd + 乙胺丁醇 0.75–1.0 g qd，强化 2 个月后改 4HR","note":"按肺结核同样方案治疗，总疗程 6 个月；大量胸水者可短期（4–6 周）加用中低剂量激素以减少胸膜增厚","renal":"按 CrCl 调整异烟肼、乙胺丁醇与吡嗪酰胺","hepatic":"治疗前查肝功，肝功能异常者需评估并监测","interact":"利福平强效 CYP 诱导剂，影响多种药物浓度"},{"name":"头孢曲松 + 甲硝唑（肺炎旁积液）","dose":"头孢曲松 2 g 静滴 qd + 甲硝唑 0.5 g 静滴 q8h","note":"合并厌氧菌感染风险或脓胸时加抗厌氧菌；脓胸需引流而非单纯抗生素","renal":"头孢曲松一般无需调整；甲硝唑 CrCl <30 mL/min 减量","hepatic":"严重肝病者监测","interact":"头孢曲松与含钙输液不可同瓶（新生儿）"},{"name":"尿激酶（脓胸/包裹性积液胸腔内注射）","dose":"10 万 U 加入生理盐水 20–30 mL 经胸管注入，夹管 2–4 小时后引流，每日 1 次，可连用 3 天","note":"促进分隔脓腔引流；有出血倾向或活动性咯血者禁用","renal":"遵说明书","hepatic":"凝血障碍者禁用","interact":"避免与抗凝/抗血小板药大剂量叠用"}],"nonDrug":["胸腔穿刺抽液：诊断性 20–50 mL；治疗性首次不超过 1000 mL，之后每次 ≤1000–1500 mL，避免复张性肺水肿","胸腔闭式引流：脓胸、复杂性肺炎旁积液（pH <7.20）、大量积液致呼吸困难、恶性积液反复复发","胸膜固定术：恶性胸水反复且肺可完全复张者，行滑石粉胸膜固定或留置胸膜导管","恶性积液：胸腔内化疗（顺铂、博来霉素）或抗血管生成药（贝伐珠单抗/重组人血管内皮抑制素）","结核性胸膜炎：中大量积液应尽早抽液或置管引流，减少胸膜增厚与肺功能损失","内科胸腔镜：不明原因渗出性积液的诊断金标准，必要时胸膜剥脱或黏连松解","胸腔积液是“表征”，必须同时治疗原发病（心衰、肝硬化、感染、肿瘤）"],"life":["限盐（心衰/肝硬化者每日 <5 g），按医嘱利尿并每天称重","结核性胸膜炎规律抗结核 6 个月，定期复查肝功能与胸片","恶性积液者定期复查超声评估积液量；胸管留置者注意出口护理防感染","出现进行性气促、发热或胸痛加重及时就诊，不自行增减利尿剂"]},"prog":"预后取决于病因：心衰漏出液经治疗可完全吸收；结核性胸膜炎规范治疗治愈率 >95%，但约 20% 遗留胸膜增厚或肺功能下降；恶性胸腔积液中位生存 4–7 个月（肺癌、乳腺癌较好）；脓胸经充分引流与抗菌治疗病死率 <5%，延误引流者明显上升。","refs":["《内科学》第 9 版 第二篇 胸腔积液","中华医学会呼吸病学分会《恶性胸腔积液诊断和治疗中国专家共识》（2022）","中华医学会结核病学分会《结核性胸膜炎治疗指南》（2017）","BTS《Pleural Disease Guideline》（2010）"]},{"id":"ild_pneumothorax_med","name":"自发性气胸（内科处理视角）","aka":["Spontaneous Pneumothorax","气胸","原发性自发性气胸（PSP）"],"rank":3,"basic":{"define":"无外伤或人为因素情况下肺组织与脏层胸膜破裂、气体进入胸膜腔形成的气胸。原发性（PSP）见于无基础肺病者（多为胸膜下肺大疱破裂），继发性（SSP）见于 COPD、结核、支扩、间质性肺病、肺脓肿等基础疾病，后者常起病重、并发症多。","risk":["年轻瘦高男性（PSP 典型人群），吸烟是明确的剂量依赖危险因素","基础肺病：COPD、肺结核与尘肺（SSP 最常见）、支扩、间质性肺病","月经期反复发作（子宫内膜异位症，月经性气胸）","飞行、潜水与高空低压环境、剧烈气压变化","家族性易感：Birt-Hogg-Dubé 综合征、马方综合征"],"epi":"PSP 年发病率约 7–18/10 万（男性更高），SSP 在 COPD 患者中年发病率可达数百/10 万；复发率 PSP 约 30%（再次发作后更高），SSP 更高，是临床随访与预防重点。"},"patho":"PSP 以胸膜下肺小疱（bleb）/肺大疱破裂为主，气体自破口进入胸膜腔；SSP 在基础肺病（肺气肿、纤维化、空洞）基础上局部结构破坏形成瘘口，肺泡与胸膜腔持续漏气。气体集聚使胸膜腔内压升高、肺被压缩、静脉回流受阻、通气/血流比例失调；张力性气胸时胸膜腔内压持续高于大气压，可致纵隔移位、腔静脉受压与心输出量骤降，需紧急减压。","dx":{"criteria":["症状：突发单侧胸痛（针刺样或刀割样）随后出现呼吸困难，多于静息时发作；部分患者仅表现为胸闷气促。","体征：患侧胸廓饱满、呼吸运动减弱，叩诊鼓音，语颤与呼吸音减弱/消失，大量气胸时气管向健侧移位，可有皮下气肿。","影像：立位胸片见外带无肺纹理透亮区与脏层胸膜线，测量胸膜线宽度判断大小；CT 对少量气胸与小肺大疱更敏感，并可评估基础肺病变。","大小分级（BTS 2010）：胸膜线宽度 <2 cm 为小量，≥2 cm 为大量。","张力性气胸：低血压、颈静脉怒张、严重呼吸困难、气管偏移，为临床诊断，需立即减压，不能等待影像。","继发性气胸：需评估基础病与呼吸储备（血气、肺功能），警惕呼吸衰竭快速进展。"],"workup":["后前位胸片（立位），必要时加侧卧位或 CT 确认小量气胸，并观察胸腔积液与肺不张","胸部 CT：SSP 评估肺气肿/肺大疱/空洞分布，长期随访评估复发风险","血气分析：SSP 与大量气胸常伴低氧与呼吸性碱中毒，监测呼吸衰竭","床旁超声：肺滑动征消失是快速筛查手段，适合急诊与不能搬动者","心电图：排除急性冠脉事件与气胸导致的 ST 改变"],"grading":"按病因：原发性（PSP）/继发性（SSP）/特殊类型（月经性、外伤性、医源性）。按大小：小量（胸膜线 <2 cm）、大量（≥2 cm）。按机制：闭合性、开放性、张力性。按临床：稳定（呼吸循环平稳）与不稳定。"},"ddx":[{"name":"胸腔积液","point":"与本类中胸腔积液的鉴别点：胸水叩诊浊音、呼吸音减弱而非消失、X 线见弧形密度增高影；气胸叩诊鼓音、胸膜线外无肺纹理。"},{"name":"肺大疱","point":"大疱壁薄而光滑、内部可见少许肺纹理与分隔，可长期无变化；气胸的胸膜线贴附胸壁、外带完全无肺纹理，CT 可明确区分。"},{"name":"急性心肌梗死","point":"胸痛呈压榨性，伴 ST 段抬高/压低与肌钙蛋白升高，无气胸体征；但气胸可诱发心律失常与 ST-T 改变，需结合胸片。"},{"name":"肺栓塞","point":"突发呼吸困难伴胸痛，D-二聚体升高与 CTPA 阳性；气胸有明确气胸影像征象，两者罕见并存。"},{"name":"COPD 急性加重（SSP 误诊）","point":"COPD 患者突发气促加重、单侧呼吸音降低与胸廓饱满，应常规拍胸片排除 SSP；仅按 COPD 加重处理会延误引流。"}],"tx":{"drug":[{"name":"氧气（高流量）","dose":"普通面罩或鼻导管，按 SpO₂ 目标调节（一般 2–6 L/min；SpO₂ 目标 94%–98%，COPD 患者 88%–92%）","note":"提高血氧有利于胸腔内氮气吸收，小量闭合性气胸可加速复张；避免长期高浓度氧致氧中毒","renal":"无关","hepatic":"无关","interact":"无"},{"name":"2% 利多卡因（穿刺/置管局部麻醉）","dose":"3–5 mL 于穿刺点皮内与胸壁各层注射","note":"抽气或置管前局部麻醉，注药前回抽避免误入血管","renal":"遵说明书","hepatic":"严重肝功能不全者减量","interact":"与胺碘酮、β 受体阻滞剂合用可加重心脏抑制"},{"name":"吗啡（置管后镇痛）","dose":"2–5 mg 静脉缓慢推注，必要时 10–30 分钟后重复（总量遵医嘱）","note":"缓解胸膜痛与置管不适，注意呼吸抑制；SSP 伴呼吸衰竭者慎用","renal":"肾功能不全者减量并延长间隔","hepatic":"严重肝病者减量","interact":"与镇静药合用呼吸抑制叠加"},{"name":"阿莫西林/克拉维酸（SSP 合并感染时）","dose":"1.2 g 静滴 q8h","note":"不常规用于单纯 PSP；SSP 合并胸腔积液、置管引流或基础病感染者考虑","renal":"CrCl <30 mL/min 减量","hepatic":"严重肝病者慎用","interact":"与华法林合用延长 INR"}],"nonDrug":["稳定性小量气胸（胸膜线 <2 cm、症状轻微）PSP：观察 + 吸氧，24–48 小时复查胸片；SSP 小量也需住院观察","稳定性大量 PSP：首选简单抽气（第 2 前肋间锁骨中线或第 4–5 肋间腋中线，16–18G 针 + 三通阀），抽至肺复张或患者耐受；抽气失败（排气 >4 L 或 24–48 小时不缓解）改置管","SSP 与不稳定者：胸腔闭式引流（细管 8–14F 或粗管 24–28F），持续漏气者加负压 −10～−20 cmH₂O；漏气停止、肺复张后夹管观察再拔管","张力性气胸：立即在第 2 前肋间锁骨中线穿刺减压，随后置管，不可等待影像","复发预防：同侧复发 ≥2 次、对侧有病史、双侧气胸、高危职业（飞行员、潜水员）或 SSP，行胸膜固定（滑石粉）或胸腔镜下肺大疱切除 + 胸膜摩擦","SSP 同步治疗基础病：COPD 规范化管理、抗结核治疗、戒烟","飞行与潜水：气胸完全复张且影像稳定前禁止飞行与潜水（一般需 2–4 周后经专科评估）"],"life":["急性期卧床，避免剧烈咳嗽、用力与屏气；便秘者给缓泻剂","戒烟是降低复发最重要的措施，PSP 首次发作后持续戒烟可显著减少复发","出院后 1–2 周复查胸片，1 个月内避免剧烈运动、举重与乘坐飞机","反复气胸者建议行胸膜固定术，避免潜水与高压环境","了解复发警示症状：突发胸痛与气促立即就医"]},"prog":"PSP 经抽气或观察后多数 1–2 周内复张，90% 患者可恢复；但复发率约 30%（第二次发作后 >40%），胸膜固定术可将复发率降至 <5%。SSP 住院时间更长、病死率显著更高（COPD 患者可达 10%），需长期管理基础病。","refs":["《内科学》第 9 版 第二篇 自发性气胸","中华医学会呼吸病学分会《自发性气胸临床路径（2018 年版）》","BTS《Pleural Disease Guideline 2010: Management of spontaneous pneumothorax》（2010）"]},{"id":"ild_sarcoid","name":"结节病","aka":["Sarcoidosis","肺结节病"],"rank":4,"basic":{"define":"病因未明的多系统肉芽肿性疾病，以非干酪样坏死性上皮样细胞肉芽肿为病理特征；最常见受累器官为肺与双侧肺门淋巴结（约 90%），也可累及皮肤、眼、心脏、肝脾与神经系统。","risk":["20–40 岁青壮年，女性略多于男性（我国女性发病高峰约 30–50 岁）","非吸烟者更常见（吸烟可能降低风险）","职业与环境暴露：金属粉尘、农药、霉菌与建筑尘","遗传易感（HLA-DRB1 等）与免疫调节异常（Th1 型反应、Treg 功能低下）"],"epi":"全球发病率差异很大（北欧约 5–40/10 万），我国以中青年发病为主，随体检普及检出率上升；多数患者（尤其 Scadding I、II 期）可自行缓解，约 20%–30% 发展为慢性进展并致纤维化。"},"patho":"未知抗原经抗原呈递细胞激活 CD4⁺ T 细胞，释放 IL-2、IFN-γ 与 TNF-α，募集单核/巨噬细胞在受累器官形成非干酪性肉芽肿。肉芽肿多沿淋巴管走行分布（支气管血管束、胸膜下、小叶间隔），早期可完全吸收；持续存在则刺激成纤维细胞增生，出现支气管周围纤维化、肺容积缩小、牵拉性支扩与蜂窝样改变（Ⅳ 期），并可致心脏传导阻滞、眼葡萄膜炎与神经系统病变。","dx":{"criteria":["三项符合：①相容的临床与影像表现；②非干酪样坏死性肉芽肿组织病理；③排除其他可引起相似肉芽肿的疾病（结核、真菌、过敏性肺炎、肿瘤、淋巴瘤）。","X 线 Scadding 分期：0 期正常；Ⅰ 期双侧肺门淋巴结肿大（BHL）；Ⅱ 期 BHL + 肺内浸润；Ⅲ 期肺内浸润而无 BHL；Ⅳ 期肺纤维化（肺容积缩小、蜂窝样改变、支气管扩张）。","典型 HRCT：沿支气管血管束、小叶间隔与胸膜下分布的小结节（淋巴周围分布），伴双侧对称性肺门与纵隔淋巴结肿大（无坏死，可有蛋壳样钙化）；Ⅳ 期为上叶为主纤维化与牵拉性支扩。","血清学：血清 ACE 升高（敏感性一般，不能单独诊断）、高钙血症（少见）、CRP、淋巴细胞减少、肝肾功能。","肺外评估：心电图/动态心电与心脏 MRI（心脏结节病）、眼科裂隙灯、皮肤、神经系统、肝脾超声。"],"workup":["胸片、胸部 HRCT 与 PET/CT（活动性肉芽肿呈高代谢，可用于疗效评估）","支气管镜：经支气管肺活检（TBLB）与经支气管针吸活检（TBNA，EBUS-TBNA 对淋巴结敏感性高）","支气管肺泡灌洗液（BALF）：CD4/CD8 >3.5 支持诊断","血清 ACE、血钙、肝肾功能、结核菌素试验与 IGRA（排除结核）","眼科裂隙灯 + 眼底；心电图 + 24 小时动态心电 + 心脏 MRI（有症状或筛查指征者）","皮肤/结膜病灶活检（最易获得）；必要时纵隔镜或 VATS 活检"],"grading":"Scadding 分期（0–Ⅳ 期）为基础；结合器官受累（肺、眼、心脏、神经、皮肤、肝脾）与是否需干预；严重度以肺功能（FVC、DLCO）、6 分钟步行与圣乔治呼吸问卷评估。"},"ddx":[{"name":"特发性肺纤维化","point":"与本类中 IPF 的鉴别点：IPF 为下肺为主的蜂窝肺、无肺门淋巴结肿大、FVC 持续下降且激素无效；结节病多见青年、双侧肺门对称肿大 + 沿淋巴周围结节，可自发缓解。"},{"name":"过敏性肺炎","point":"有明确抗原暴露，HRCT 小叶中心结节 + 磨玻璃影 + 空气潴留，BALF 淋巴细胞高但 CD4/CD8 <1，病理见松散性肉芽肿；结节病 CD4/CD8 >3.5。"},{"name":"肺结核","point":"低热盗汗、空洞与树芽征、抗酸涂片或结核核酸阳性；结节病为非干酪性肉芽肿，但需排除结核与结节病并存。"},{"name":"淋巴瘤","point":"纵隔/肺门淋巴结显著肿大伴融合、上腔静脉综合征，PET 高代谢；需活检病理（结节病为肉芽肿）。"},{"name":"肺癌伴肺门淋巴结转移","point":"中老年吸烟、肺部原发肿块伴不对称淋巴结肿大、PET/CT 高代谢；EBUS 活检确诊。"},{"name":"尘肺/矽肺","point":"职业接触史 + 双侧小结节、淋巴结蛋壳样钙化；结节病淋巴结多为对称肿大，结节不以蛋壳样钙化为特征。"}],"tx":{"drug":[{"name":"泼尼松（激素治疗）","dose":"初始 0.5 mg/kg/d（或 20–40 mg/d）口服 4–6 周，有效者每 2–4 周减 5–10 mg 至 5–10 mg/d 维持 6–12 个月后逐步减停","note":"激素指征：症状明显的气道/肺实质受累、进展性肺病、眼（后葡萄膜炎、视神经受累）、心脏（传导阻滞、心律失常）、神经系统、高钙血症与肝脾功能受累；无症状 Ⅰ 期不治疗","renal":"肾功能不全者无需调整（需监测）","hepatic":"肝功能异常者慎用，可同时护肝","interact":"与 NSAIDs、利福平、苯妥英合用影响浓度与疗效；降糖作用减弱"},{"name":"甲氨蝶呤（激素节省剂）","dose":"7.5–15 mg 口服每周 1 次，加叶酸 5–10 mg/周（非同日）","note":"用于激素减量困难或反复复发、慢性肺受累；每周一次，误用每日服药可致严重骨髓抑制","renal":"CrCl <50 mL/min 慎用或禁用","hepatic":"肝纤维化与肝硬化者禁用","interact":"与甲氧苄啶/复方磺胺、NSAIDs 合用增加毒性"},{"name":"硫唑嘌呤","dose":"1–2 mg/kg/d 口服","note":"激素节省剂，需监测血常规与肝酶；用药前可检测 TPMT 活性","renal":"肾功能不全者减量","hepatic":"肝功能不全者慎用","interact":"与别嘌醇合用需减量至 1/4"},{"name":"英夫利西单抗（难治性/心脏或神经结节病）","dose":"5 mg/kg 静脉输注第 0、2、6 周，之后每 4–8 周一次","note":"仅用于激素与免疫抑制剂无效的难治性病例；治疗前筛查结核与乙型肝炎","renal":"无需调整","hepatic":"遵说明书","interact":"与其他免疫抑制剂合用感染风险叠加"},{"name":"羟氯喹（皮肤/关节受累）","dose":"200 mg 口服 qd–bid","note":"用于轻度皮肤、关节与神经肌病受累；长期使用需定期查眼底","renal":"肾功能不全者减量","hepatic":"肝功能不全者慎用","interact":"与 QT 延长药物合用需注意"}],"nonDrug":["观察等待：无症状或症状轻微（尤其 Ⅰ、Ⅱ 期、肺功能正常）者每 3–6 个月随访胸片与肺功能，多数可自行缓解","心脏结节病：高度房室传导阻滞需植入起搏器或 ICD，抗心律失常药与激素联合；心脏 MRI 与 PET 评估活动性与疗效","眼结节病：局部/全身激素与免疫抑制剂，必要时眼科手术","神经结节病：激素与免疫抑制剂，严重者用生物制剂","肺移植：Ⅳ 期终末期纤维化伴呼吸衰竭与肺动脉高压","高钙血症：补液、限钙与避光、必要时激素"],"life":["戒烟，避免粉尘与职业暴露，接种流感与肺炎球菌疫苗","规律随访 3–6 个月：胸片、肺功能、血清 ACE 与肝肾功能；激素治疗者同时监测血糖、骨密度与血压","激素治疗期间补钙与维生素 D，必要时抗骨质疏松治疗","心脏结节病患者避免剧烈运动与脱水，出现晕厥、心悸立即就诊","皮肤与眼部症状变化及时就诊，眼部定期裂隙灯检查"]},"prog":"60%–70% 患者可自行缓解或长期稳定，20%–30% 进展为慢性纤维化；死亡的 85% 与肺纤维化、心脏受累或神经系统病变相关。心脏结节病伴心衰者预后最差；Ⅰ 期缓解率最高。","refs":["ATS/ERS/JRS/ALAT《Diagnosis and Detection of Sarcoidosis: An Official ATS Clinical Practice Guideline》（2020）","中华医学会呼吸病学分会《结节病诊断和治疗专家共识》（2019）","《内科学》第 9 版 第二篇 结节病"]},{"id":"ild_hypersensitivity","name":"过敏性肺炎","aka":["Hypersensitivity Pneumonitis","HP","外源性过敏性肺泡炎（EAA）"],"rank":5,"basic":{"define":"易感个体反复吸入有机粉尘或小分子化学物质后发生的免疫介导的弥漫性肺实质与气道炎症；按病程分为急性（暴露后数小时至数天）、亚急性（数周至数月）与慢性（数月至数年，伴纤维化）三型。","risk":["鸟禽类抗原（鸽子、鹦鹉、鸡）——鸟禽饲养者肺","霉变植物/谷物粉尘——农民肺（放线菌、曲霉）","热带木材粉尘、蘑菇工人肺","空调、加湿器与温泉气溶胶（“加湿器肺”）、室内霉菌","金属加工液（非结核分枝杆菌、真菌）——工人肺","强酸/异氰酸酯类等化学物质（低分子量抗原）"],"epi":"过敏性肺炎在我国中老年女性（与鸟禽饲养相关）就诊者中并不少见；特异性暴露的人群发病率资料有限，但农村与职业暴露人群（农民肺）累及率更高。诊断最大难点是与 IPF、NSIP 及结缔组织病相关 ILD 鉴别。"},"patho":"抗原吸入后 4–8 小时，致敏个体发生 Ⅲ 型（免疫复合物）与 Ⅳ 型（T 细胞介导）超敏反应：BALF 显示淋巴细胞显著增多（常 >50%，CD4/CD8 <1，慢性纤维化时可变），肺泡壁与细支气管周围形成松散的非干酪性肉芽肿。反复暴露转为慢性，可形成纤维化与蜂窝肺，其纤维化过程类似 IPF，部分慢性 HP 与 IPF 难以区分。","dx":{"criteria":["暴露史：详询鸟类、霉变植物、空调/加湿器、农场、金属加工液等暴露；症状与暴露有明确时间关系（暴露后数小时气促、发热、寒战、咳嗽，离开后 24–48 小时改善）。","HRCT 急性/亚急性型：双肺弥漫磨玻璃影、小叶中心结节、空气潴留（马赛克灌注）、细支气管壁增厚；慢性型：网格影、牵拉性支扩、蜂窝肺。","肺功能：限制性通气障碍、DLCO 降低；急性期可有低氧；慢性期可有混合性通气障碍。","诊断参考标准（ATS/JRS/ALAT 2020）：结合暴露识别、影像表型（典型/相容/不典型）、BALF 淋巴细胞 >30%、特异性 IgG 抗体、诱发试验与病理（松散肉芽肿、细胞性细支气管炎）。","抗原特异性 IgG：阳性支持暴露，但不能区分致敏与疾病。","诱发试验：仅在安全环境中谨慎进行，可能引起严重反应。"],"workup":["胸部 HRCT（仰卧 + 俯卧深呼吸后）：磨玻璃影、小叶中心结节、马赛克灌注、牵拉性支扩","肺功能（含 DLCO、TLC）与 6 分钟步行","BALF 细胞分类：淋巴细胞 >30%（常 >50%），CD4/CD8 <1 支持 HP","血清特异性 IgG（鸟禽、曲霉、放线菌）与常规免疫球蛋白","经支气管肺活检或冷冻活检（取得肺实质）：松散非干酪性肉芽肿与细胞性细支气管炎","排除其他 ILD：自身抗体谱（ANA、抗 CCP、肌炎抗体），必要时 MDD"],"grading":"按病程：急性、亚急性、慢性（纤维化型）。按影像：典型 HP（磨玻璃 + 空气潴留 + 小叶中心结节）、相容 HP、不典型 HP。按严重度：FVC、DLCO 与低氧程度评估；慢性纤维化型预后与 IPF 相近。"},"ddx":[{"name":"特发性肺纤维化","point":"与本类中 IPF 的鉴别点：HP 有明确抗原暴露、影像有磨玻璃/空气潴留/小叶中心结节、BALF 淋巴细胞 >30%；IPF 无暴露史、以蜂窝肺为主、BALF 淋巴细胞正常。慢性纤维化型 HP 可与 IPF 难以区分，需 MDD。"},{"name":"结节病","point":"结节病双侧肺门淋巴结对称肿大 + 沿淋巴周围小结节，BALF CD4/CD8 >3.5；HP 为小叶中心结节 + 磨玻璃 + 空气潴留，CD4/CD8 <1，与暴露相关。"},{"name":"非特异性间质性肺炎（NSIP）","point":"NSIP 为下叶与胸膜下磨玻璃影与网格影、少见空气潴留与结节；需自身抗体与暴露史鉴别，部分 NSIP 实为未识别的慢性 HP。"},{"name":"尘肺","point":"有石英/煤尘等无机粉尘职业史，肺内多发结节伴网状影与淋巴结蛋壳样钙化；HP 为有机粉尘与淋巴细胞性肺泡炎。"},{"name":"病毒性肺炎（急性型误诊）","point":"急性 HP 暴露后数小时发热、乏力、干咳、双肺弥漫磨玻璃影，易误为流感/病毒性肺炎；但明显与抗原暴露相关且可重复发生。"},{"name":"结缔组织病相关 ILD","point":"有雷诺现象、关节痛、皮疹与自身抗体阳性；HP 需筛查自身抗体，并注意两种疾病可并存。"}],"tx":{"drug":[{"name":"泼尼松（中重度/急性发作）","dose":"急性型 0.5–1 mg/kg/d（如 30–60 mg/d）口服 2–4 周后逐渐减量，总疗程 3–6 个月","note":"仅用于症状显著或肺功能受损、且不能完全脱离抗原者；慢性纤维化型激素证据有限","renal":"无需调整","hepatic":"肝功能异常者慎用","interact":"与 NSAIDs 合用增加消化道出血风险"},{"name":"吗替麦考酚酯（慢性/激素依赖型）","dose":"0.5–1.0 g 口服 bid，按耐受性与白细胞调整","note":"作为慢性进展型 HP 的激素节省剂，疗效证据有限","renal":"CrCl <30 mL/min 慎用","hepatic":"肝功能异常者慎用","interact":"与丙磺舒、阿昔洛韦合用升高血药浓度"},{"name":"尼达尼布（慢性纤维化型 HP）","dose":"150 mg 口服 bid（耐受差者 100 mg bid）","note":"INBUILD 研究显示可延缓纤维化型 HP 的 FVC 下降；不替代抗原回避，需个体化讨论","renal":"轻中度无需调整","hepatic":"Child-Pugh B 减至 100 mg bid，C 不推荐","interact":"P-gp 抑制剂可升高浓度"},{"name":"沙丁胺醇/异丙托溴铵（缓解气道症状）","dose":"沙丁胺醇 100–200 µg 吸入按需（每日 ≤4 次）；或异丙托溴铵 20–40 µg 吸入 bid","note":"伴气道痉挛或空气潴留者缓解气促，不改变病程","renal":"遵说明书","hepatic":"遵说明书","interact":"非选择性 β 受体阻滞剂可拮抗"}],"nonDrug":["抗原回避是核心：识别并彻底移除引发抗原的家禽、霉变植物、加湿器、空调系统或职业暴露","环境改造：除湿防霉、安装高效过滤与通风设施，必要时更换工作场所或岗位","长期随访：脱离抗原后每 3–6 个月评估肺功能与影像；慢性纤维化型需长期随访","家庭氧疗与肺康复：低氧与运动耐量下降者","肺移植：进展性慢性纤维化型 HP 伴呼吸衰竭","急性发作支持治疗：氧疗、卧床，必要时短期激素"],"life":["避免饲养鸟禽、接触霉变谷物与使用加湿器（或彻底清洁消毒）","职业暴露者做好防护（口罩、通风），必要时调离岗位","戒烟并接种流感、肺炎球菌疫苗，减少急性加重诱因","定期复查肺功能与 HRCT；再暴露后出现气促立即就医"]},"prog":"急性与亚急性型在脱离抗原后多数可完全恢复；反复暴露者约 5%–10% 进展为慢性纤维化。慢性纤维化型 HP 的生存期近似 IPF，中位生存 5–10 年，且可发生急性加重。及时识别并去除抗原是决定预后的关键。","refs":["ATS/JRS/ALAT《Diagnosis of Hypersensitivity Pneumonitis in Adults: An Official ATS/ERS/JRS/ALAT Clinical Practice Guideline》（2020）","中华医学会呼吸病学分会《过敏性肺炎诊断和治疗中国专家共识》（2022）","《内科学》第 9 版 第二篇 过敏性肺炎"]}]},{"id":"uri_occupational","name":"上呼吸道感染与职业性肺病","rank":8,"summary":"上感多为自限性、抗生素无效；职业性肺病的关键在**职业暴露史**——接尘工种、工龄与影像形态（结节、纤维化、胸膜斑）三者结合才能诊断，确诊后首要处理是脱离暴露与劳动能力鉴定。","compare":[{"diseaseId":"resp_uri","dx":"鼻塞流涕咽痛、低热，咽部充血，肺部听诊清晰，血象多正常，3–7 天自限","key":"症状局限上呼吸道、肺无体征、自限；抗生素无效"},{"diseaseId":"resp_acute_bronchitis","dx":"上感后咳嗽持续 >5 天、痰少，可有哮鸣音，胸片无浸润","key":"咳嗽为主而肺部无实变；多数为病毒性，不推荐常规抗生素"},{"diseaseId":"resp_pneumoconiosis","dx":"长期接尘史（矽尘、煤尘、石棉）+ 胸片/CT 见结节或弥漫纤维化 + 排除其他间质性病","key":"职业史是必要条件；矽肺以小结节与融合团块为主，石棉肺伴胸膜斑与胸膜钙化"},{"diseaseId":"resp_asbestosis","dx":"石棉暴露 >10 年、双下肺网格影与胸膜斑，限制性通气障碍与 DLCO 降低","key":"胸膜斑是特征性标志；合并肺癌与间皮瘤风险显著升高"}],"diseases":[{"id":"resp_uri","name":"急性上呼吸道感染","aka":["Acute Upper Respiratory Tract Infection","URI","普通感冒"],"rank":1,"basic":{"define":"鼻腔、咽或喉部急性炎症的统称，多由病毒引起（鼻病毒、冠状病毒、腺病毒、呼吸道合胞病毒、副流感病毒），呈自限性。广义包括普通感冒、急性咽炎、急性扁桃体炎、急性喉炎与急性鼻窦炎。","risk":["季节交替与寒冷季节（秋冬高发）","人群密集场所（学校、托幼机构）","免疫力低下、疲劳与睡眠不足","吸烟与被动吸烟","婴幼儿与老年人","基础呼吸道疾病（哮喘、COPD）"],"epi":"成人每年 2–4 次，儿童每年 6–8 次，是门急诊最常见的疾病。约 70%–80% 由病毒引起，抗生素治疗无效且无益。"},"patho":"病毒侵入鼻咽部黏膜上皮细胞，在细胞内复制并引起局部炎症与上皮损伤，释放组胺与缓激肽等介质，导致血管扩张、通透性增加与腺体分泌亢进（鼻塞、流涕、打喷嚏）。全身症状（发热、乏力、肌痛）由细胞因子（IL-1、IL-6、TNF-α）介导。黏膜修复通常需 1–2 周，故咳嗽可持续较久。继发细菌感染（如中耳炎、鼻窦炎、肺炎）多见于免疫低下或有基础病者。","dx":{"criteria":["症状：鼻塞、流清涕、打喷嚏、咽痛、轻度咳嗽、低热（<38.5 ℃），全身症状轻","体征：鼻黏膜充血水肿、咽部轻中度充血、无肺部啰音","病程自限：多数 5–7 天缓解，咳嗽可持续 2–3 周","**需警惕非上感的线索（「红旗」）**：高热 >39 ℃ 持续 3 天以上、呼吸困难、胸痛、咯血、意识改变、单侧扁桃体肿大伴悬雍垂偏移、颈部淋巴结明显肿大","甲型流感流行季节出现高热 + 肌痛，需考虑流感（可抗原/核酸检测）"],"workup":["多数无需检查，临床诊断即可","血常规：病毒性多正常或淋巴细胞比例升高；细菌性见中性粒细胞与 CRP 升高","流感/新冠核酸或抗原（流行季、有接触史或高危人群）","咽拭子培养（疑链球菌性咽炎：高热、扁桃体渗出、无咳嗽、颈部淋巴结肿大）","胸片（疑下呼吸道感染、持续发热或肺部有体征时）","血 CRP/PCT（不推荐常规，但可用于鉴别细菌感染）"],"grading":"按部位分：普通感冒、急性咽炎、急性扁桃体炎（可伴渗出）、急性喉炎（声嘶、犬吠样咳）、急性鼻窦炎；按病原分病毒性与细菌性。"},"ddx":[{"name":"急性气管支气管炎（resp_acute_bronchitis）","point":"与急性支气管炎的鉴别：上感症状集中鼻咽、无深部咳痰与肺部体征；急性支气管炎以持续咳嗽为主（>5 天）、可有哮鸣音，胸片无实变。"},{"name":"尘肺与职业性肺病（resp_pneumoconiosis）","point":"与尘肺的鉴别：尘肺为慢性进行性呼吸困难与影像异常，无急性上感症状；两者可并存（尘肺患者易发上感）。"},{"name":"石棉肺（resp_asbestosis）","point":"与石棉肺的鉴别：石棉肺为慢性限制性通气障碍与胸膜斑，无急性鼻咽症状。"},{"name":"流行性感冒","point":"流感以高热（>38.5 ℃）、明显肌痛、乏力为特征，全身症状重而鼻部症状轻，抗原/核酸阳性。"},{"name":"细菌性咽扁桃体炎（A 组链球菌）","point":"高热、扁桃体化脓性渗出、无咳嗽、颈前淋巴结肿大与皮疹，咽拭子培养或快速抗原阳性，需抗生素。"},{"name":"过敏性鼻炎","point":"以打喷嚏、清水样涕、鼻痒与眼痒为主，无发热与咽痛，季节性或常年性发作，抗组胺药有效。"},{"name":"新冠与肺炎早期","point":"持续发热、干咳、气促与嗅觉丧失，核酸阳性；肺部 CT 见磨玻璃影。"}],"tx":{"drug":[{"name":"对乙酰氨基酚 / 布洛芬（解热镇痛）","dose":"对乙酰氨基酚 500–1000 mg q6h（日不超过 4 g）；布洛芬 400–600 mg q6–8h","note":"仅用于缓解发热与咽痛，不缩短病程；两种不建议同时常规叠加","renal":"NSAIDs 在 eGFR <30 避免；对乙酰氨基酚 CrCl <30 延长间隔","hepatic":"肝病者对乙酰氨基酚日 ≤2 g","interact":"NSAIDs 与抗凝合用增加出血；与 ACEI/ARB 合用降低降压效果"},{"name":"奥司他韦（流感）","dose":"75 mg bid 口服 ×5 天（肾功能不全：CrCl 30–60 减为 30 mg bid；CrCl 10–30 减为 30 mg qd）","note":"**仅用于确诊或高度疑似流感**（发病 48 小时内效果最好），对普通感冒无效；高危人群即使超过 48 小时也应使用","renal":"按 CrCl 调整（见剂量）","hepatic":"重度肝损害无需调整","interact":"与减毒活流感疫苗需间隔 2 周以上"},{"name":"复方感冒制剂（对乙酰氨基酚 + 伪麻黄碱 + 右美沙芬等）","dose":"按说明书，注意复方中已含对乙酰氨基酚（避免与其他退热药叠加过量）","note":"仅缓解症状；**多种复方药叠加是门诊对乙酰氨基酚过量的常见原因**，必须核对成分","renal":"伪麻黄碱在肾功能不全者慎用","hepatic":"肝病者慎用","interact":"伪麻黄碱与 MAO 抑制剂合用可致高血压危象；与 β 阻滞剂、降压药作用拮抗"},{"name":"阿莫西林（明确细菌感染时）","dose":"500 mg q8h 口服 ×5–7 天（链球菌性咽炎：500 mg bid ×10 天）","note":"**不用于病毒性上感**；仅用于确诊细菌性咽扁桃体炎、中耳炎或鼻窦炎","renal":"CrCl <30 延长间隔","hepatic":"无需调整","interact":"与别嘌醇合用增加皮疹；与口服避孕药无明确相互作用但需提示"},{"name":"氯己定/复方硼砂含漱液（咽喉局部）","dose":"按说明书含漱，每日 3–4 次","note":"局部缓解咽痛，证据有限但安全","renal":"无","hepatic":"无","interact":"无特殊"}],"nonDrug":["休息、多饮水（每日 1.5–2 L）、保持室内通风与湿度","生理盐水鼻腔冲洗可缓解鼻塞（安全有效，优于多数减充血剂喷雾的长期使用）","不推荐常规使用抗生素（对病毒无效，增加耐药与不良反应）","不推荐常规使用糖皮质激素与复方抗菌药","流感季节前接种流感疫苗（每年一次）"],"life":["症状缓解前避免剧烈运动与过度劳累","注意手卫生与咳嗽礼仪（减少传播）","咳嗽持续 >3 周需就诊评估（排除咳嗽变异性哮喘、百日咳、鼻后滴漏）","体温 >39 ℃ 持续 3 天、气促、胸痛或咯血立即就诊","婴幼儿、老年人与慢性病患者需警惕下呼吸道感染"]},"prog":"绝大多数自限，5–7 天症状缓解，咳嗽可持续 2–3 周。并发症包括中耳炎、鼻窦炎、支气管炎与（少见）肺炎；老年人、婴幼儿与免疫抑制者可出现重症。整体预后良好，无后遗症。","refs":["《内科学》第 9 版（人民卫生出版社）呼吸系统疾病·急性上呼吸道感染章","《中国成人普通感冒规范诊治的专家共识》（2012）","2015 NICE Clinical Knowledge Summaries: Common Cold","2021 国家卫生健康委《流行性感冒诊疗方案（2020 年版）》"]},{"id":"resp_acute_bronchitis","name":"急性气管支气管炎","aka":["Acute Bronchitis","急性支气管炎"],"rank":2,"basic":{"define":"气管-支气管黏膜的急性炎症，以咳嗽为主要表现，通常继发于上呼吸道感染，多为病毒性（流感病毒、腺病毒、RSV、鼻病毒、冠状病毒），病程多自限。","risk":["上呼吸道感染后（最常见）","吸烟与被动吸烟","空气污染与职业性刺激物","冷空气刺激","慢性气道疾病（COPD、哮喘）患者","免疫抑制"],"epi":"是门诊抗生素滥用的主要原因之一。我国门诊急性支气管炎中约 70%–90% 为病毒性，但抗生素处方率长期偏高。"},"patho":"病毒或刺激物损伤气管-支气管黏膜上皮，引起纤毛上皮脱落、黏液腺增生与分泌物增多，气道反应性一过性增高（部分患者出现哮鸣音与气道高反应性）。黏膜修复需 2–3 周，故咳嗽可持续较久（「感染后咳嗽」）。继发细菌感染较少见（<10%），多见于有基础气道疾病或免疫抑制者。","dx":{"criteria":["咳嗽为主要或唯一症状，起病初期为干咳，后可伴少量黏液痰，可持续 2–3 周","可有轻度发热、乏力与胸骨后不适；无明显呼吸困难","体征：肺部听诊可正常，或闻及散在干、湿啰音与哮鸣音（提示气道高反应）","胸片：**无肺实变**（用于排除肺炎，不是诊断必需）","**不支持细菌感染的线索**：无高热、无脓性痰大量增多、血常规与 CRP 正常、无肺部局灶体征","需排除肺炎、哮喘、百日咳、咳嗽变异性哮喘与上气道咳嗽综合征"],"workup":["多数为临床诊断；胸片用于疑肺炎或病程迁延者","血常规与 CRP（不作为常规，但可用于评估是否需要进一步检查）","肺炎支原体/衣原体抗体或核酸（青少年、集体单位流行）","百日咳核酸（阵发性痉挛性咳嗽、吸气性「回勾」、病程 >2 周）","肺功能与支气管舒张试验（咳嗽 >8 周，疑咳嗽变异性哮喘）","痰培养（仅在使用抗生素前、疑细菌感染或免疫抑制者）"],"grading":"按病程分急性（<3 周）与迁延性（3–8 周，多为感染后咳嗽）；按病原分病毒性与细菌性（少见）；按有无哮鸣音分单纯型与喘息型（后者提示气道高反应性）。"},"ddx":[{"name":"急性上呼吸道感染（resp_uri）","point":"与上感的鉴别：上感以鼻塞流涕咽痛为主、病程短、咳嗽轻；急性支气管炎的咳嗽更突出且持续 >5 天，可伴哮鸣音。"},{"name":"尘肺与职业性肺病（resp_pneumoconiosis）","point":"与尘肺的鉴别：尘肺有接尘职业史与慢性进行性影像改变；急性支气管炎无粉尘暴露史与影像异常。"},{"name":"石棉肺（resp_asbestosis）","point":"与石棉肺的鉴别：石棉肺有石棉暴露史、胸膜斑与限制性通气障碍；急性支气管炎胸片正常、肺功能正常。"},{"name":"社区获得性肺炎（cap_comm）","point":"肺炎有高热、脓痰、肺部实变体征，胸片见浸润影（**这是核心鉴别点**），CURB-65 评估严重度。"},{"name":"咳嗽变异性哮喘","point":"以夜间与清晨干咳为主、无感染前驱、支气管激发试验阳性、支气管舒张剂有效。"},{"name":"上气道咳嗽综合征（鼻后滴漏）","point":"有鼻塞、流涕与咽部黏液感，检查见鼻咽部分泌物，抗组胺与鼻用激素有效。"},{"name":"百日咳","point":"阵发性痉挛性咳嗽伴吸气性「回勾」，可致呕吐与发绀，病程 >2 周，核酸或培养阳性。"}],"tx":{"drug":[{"name":"对乙酰氨基酚 / 布洛芬（对症）","dose":"对乙酰氨基酚 500–1000 mg q6h；布洛芬 400–600 mg q6–8h（必要时）","note":"缓解发热与胸骨后不适；不需常规使用","renal":"按 CrCl 调整","hepatic":"限量","interact":"与抗凝合用增加出血"},{"name":"右美沙芬（镇咳）","dose":"15–30 mg q6–8h 口服（日最大 120 mg）","note":"仅用于影响睡眠的剧烈干咳，**不推荐用于有痰咳嗽**（妨碍排痰）；过量可致中枢抑制与 5-HT 综合征","renal":"CrCl <30 减量","hepatic":"肝病者减量","interact":"与 SSRI、MAO 抑制剂合用增加 5-HT 综合征风险"},{"name":"愈创木酚甘油醚/氨溴索（祛痰）","dose":"氨溴索 30 mg tid 口服；愈创木酚甘油醚 200–400 mg q4h","note":"对痰液黏稠者有一定帮助，证据有限但安全","renal":"氨溴索在重度肾功能不全减量","hepatic":"无需调整","interact":"氨溴索与镇咳药合用可致痰液滞留"},{"name":"沙丁胺醇（喘息型）","dose":"100–200 µg 吸入，必要时每 4–6 小时一次；或雾化 2.5 mg","note":"仅用于伴哮鸣音或气道高反应者，可缓解气道痉挛","renal":"无需调整","hepatic":"无需调整","interact":"与 β 阻滞剂作用拮抗；与非保钾利尿剂合用可致低钾"},{"name":"抗生素（不推荐常规使用）","dose":"仅在明确细菌感染时选用：阿莫西林 500 mg q8h 或阿奇霉素 500 mg qd ×3 天（支原体）","note":"**病毒性急性支气管炎抗生素无效**，且增加耐药与不良反应；我国指南明确不推荐常规使用抗生素","renal":"按 CrCl 调整","hepatic":"阿奇霉素肝毒性需监测","interact":"阿奇霉素与 QT 延长药物合用增加心律失常；与华法林合用增强抗凝"}],"nonDrug":["休息、多饮水与湿化空气（加湿器或蒸汽）","戒烟与避免冷空气、烟雾刺激","蜂蜜（成人 1–2 勺）可缓解夜间咳嗽（证据支持，1 岁以下禁用）","呼吸训练与体位排痰（有痰者）","不推荐常规使用糖皮质激素吸入或全身用药"],"life":["咳嗽持续 >3 周需复查（排除肺炎、百日咳、咳嗽变异性哮喘）","咳嗽 >8 周进入慢性咳嗽流程评估","流感季节接种疫苗，减少复发","避免滥用抗生素（明确的教育内容）","有基础气道疾病者需评估是否诱发了急性加重"]},"prog":"多数自限，咳嗽在 2–3 周内缓解，但约 25%–50% 患者咳嗽可持续 >2 周（感染后咳嗽），少数达 8 周。无后遗症；老年人、吸烟者与有基础气道疾病者病程较长。","refs":["《内科学》第 9 版（人民卫生出版社）呼吸系统疾病·急性气管支气管炎章","《中国成人急性气管-支气管炎诊治专家共识》（2018）","2006 ACP/CDC Principles of Appropriate Antibiotic Use for Acute Bronchitis in Adults","2017 NICE Guideline: Cough (acute) – antimicrobial prescribing"]},{"id":"resp_pneumoconiosis","name":"尘肺病（矽肺与煤工尘肺）","aka":["Pneumoconiosis","Silicosis","Coal Workers' Pneumoconiosis","矽肺","煤工尘肺"],"rank":3,"basic":{"define":"长期吸入生产性粉尘（游离二氧化硅、煤尘等）并在肺内潴留所致的以肺组织弥漫性纤维化为主的全身性疾病，是我国最主要的职业病（约占职业病总数的 80% 以上）。按粉尘种类分为矽肺、煤工尘肺、石棉肺、其他尘肺等 13 种。","risk":["**职业性接尘史（诊断的必要条件）**：矿山开采、隧道掘进、石材加工、铸造、喷砂（矽尘）；煤矿采掘（煤尘）；石棉制品、造船、建筑拆除（石棉）","接尘工龄长、粉尘浓度高、防护差","吸烟（协同加重，且增加肺癌风险）","个体易感性（硅肺与遗传多态性相关）"],"epi":"我国累计报告尘肺病例超过 90 万例，现患约 40 余万，新发病例仍以每年约 1 万例的速度增加（近年有所下降）。矽肺是最常见类型，煤工尘肺次之。矽肺患者肺结核合并率高达 20%–50%，且肺癌风险升高。"},"patho":"吸入的游离二氧化硅颗粒（直径 <5 µm）沉积于肺泡，被肺泡巨噬细胞吞噬但不能被降解，导致巨噬细胞死亡并释放炎性介质（IL-1、TNF-α、转化生长因子 β）与氧自由基，激活成纤维细胞，形成以矽结节（同心圆状胶原纤维）为特征的纤维化。矽结节可融合成团块（进行性大块纤维化，PMF）。粉尘还损伤肺泡巨噬细胞的杀菌功能，故结核与感染风险显著升高。石棉纤维则致弥漫性肺间质纤维化、胸膜斑与间皮瘤。","dx":{"criteria":["**可靠的职业性粉尘接触史**（工种、粉尘性质、接尘工龄、防护情况）——这是诊断尘肺的必备条件","**影像学表现**：高千伏胸片或（更敏感）胸部 CT/HRCT","矽肺：双上肺为主的小圆形结节（直径 1–10 mm）、可融合成团块（PMF）、肺门淋巴结蛋壳样钙化","煤工尘肺：小结节影（多中下肺）、可融合成团块（PMF）","石棉肺：双下肺网格影、胸膜斑（**特征性**）、胸膜钙化、蜂窝影","肺功能：早期可正常，进展后出现限制性通气障碍与 DLCO 降低（矽肺多为限制性）","**诊断依据**：《尘肺病诊断标准》（GBZ 70）——结合职业史、影像学（胸片或 CT）与集体诊断（职业病诊断机构）","鉴别需排除：粟粒性肺结核、结节病、转移性肺癌、特发性肺纤维化、过敏性肺炎"],"workup":["详细职业史（工种、粉尘种类、起止时间、防护措施、同工种工人患病情况）","**高千伏胸片（后前位）**——职业病诊断的法定依据；CT/HRCT 用于早期发现与鉴别","肺功能（含 DLCO）与动脉血气","结核筛查：痰抗酸染色、培养、GeneXpert、PPD/IGRA、胸片（矽肺合并结核率极高）","血常规、CRP、自身抗体（鉴别结缔组织病相关间质性肺病）","必要时支气管镜或肺活检（鉴别诊断困难时）","职业病诊断需由具备资质的职业病诊断机构集体诊断"],"grading":"按 GBZ 70 分：**壹期、贰期、叁期**尘肺（依据小结节密集度与有无大阴影）；国际劳工组织（ILO）分类按小阴影密集度（0–3）与类型（圆形/不规则）分级；矽肺按病程分急性（高浓度暴露后数年）、加速型（5–15 年）与慢性（>15 年）。"},"ddx":[{"name":"急性上呼吸道感染（resp_uri）","point":"与上感的鉴别：上感为急性自限性鼻咽症状；尘肺为慢性进行性呼吸困难与影像纤维化，且有明确接尘史。"},{"name":"急性气管支气管炎（resp_acute_bronchitis）","point":"与急性支气管炎的鉴别：后者为短期咳嗽、影像正常；尘肺的咳嗽与气促为慢性进行性，影像有结节或纤维化。"},{"name":"石棉肺（resp_asbestosis）","point":"与石棉肺的鉴别：石棉肺以双下肺网格影与胸膜斑为特征、限制性通气障碍突出；矽肺以中上肺小结节与融合团块为主，肺门淋巴结蛋壳样钙化。"},{"name":"粟粒性肺结核","point":"影像见粟粒样均匀分布结节（大小一致），伴高热与结核中毒症状，痰或血培养可阳性；尘肺结节大小不一、上肺为主、病程慢性。"},{"name":"结节病","point":"双侧肺门对称性淋巴结肿大、沿淋巴管分布的结节、血管紧张素转化酶升高，影像与尘肺不同（无接尘史）。"},{"name":"转移性肺癌","point":"多发大小不等的结节、有原发肿瘤病史，进展快；尘肺结节多为小圆形、缓慢进展。"},{"name":"特发性肺纤维化（ild_ipf）","point":"HRCT 见蜂窝影与牵拉性支气管扩张（UIP 型）、无接尘史与胸膜斑。"}],"tx":{"drug":[{"name":"目前无特效治疗药物","dose":"尘肺尚无能够逆转纤维化的药物；以下为对症与并发症治疗","note":"**全肺灌洗（大容量肺灌洗）**在部分中心用于早期矽肺，可清除部分粉尘与巨噬细胞，但证据有限，不作为常规推荐","renal":"—","hepatic":"—","interact":"—"},{"name":"抗结核治疗（合并结核时）","dose":"按标准方案：2HRZE/4HR（异烟肼 5 mg/kg/d、利福平 10 mg/kg/d、吡嗪酰胺 25 mg/kg/d、乙胺丁醇 15 mg/kg/d），疗程可延长至 9–12 个月","note":"**矽肺合并结核率极高，须常规筛查**；矽肺合并结核的治疗反应较差、疗程需延长","renal":"乙胺丁醇按 CrCl 减量","hepatic":"监测肝毒性（异烟肼+利福平）","interact":"利福平强效诱导 CYP3A4，降低多种药物浓度"},{"name":"支气管舒张剂（合并气流受限时）","dose":"噻托溴铵 18 µg 吸入 qd，或沙美特罗/氟替卡松 50/250 µg 吸入 bid","note":"尘肺常合并气流受限，按 COPD 管理使用 LAMA/LABA","renal":"无需调整","hepatic":"无需调整","interact":"噻托溴铵与抗胆碱药合用增加抗胆碱副作用"},{"name":"糖皮质激素（PMF 快速进展，争议）","dose":"泼尼松 0.5–1 mg/kg/d 短期（4–8 周）后减量，仅在影像快速进展或合并自身免疫特征时考虑","note":"**证据不足**，不推荐常规使用；需权衡感染（尤其结核）风险","renal":"无需调整","hepatic":"监测","interact":"与抗结核药合用需注意利福平降低激素浓度"},{"name":"N-乙酰半胱氨酸（抗氧化，辅助）","dose":"600 mg bid–tid 口服","note":"抗氧化与祛痰，证据有限；可用于合并气流受限者","renal":"无需调整","hepatic":"无需调整","interact":"与镇咳药合用可致痰液滞留"},{"name":"氧疗（合并慢性呼衰）","dose":"长期家庭氧疗：静息 PaO₂ ≤55 mmHg 或 SpO₂ ≤88% 时，每日 ≥15 小时，流量 1–2 L/min","note":"可改善生存与生活质量（证据来自 COPD，尘肺合并呼衰同理）","renal":"无","hepatic":"无","interact":"无"}],"nonDrug":["**脱离粉尘暴露（最关键的一级预防与进展控制措施）**，调离接尘岗位","**职业病诊断与劳动能力鉴定**（患者依法享有的权利，影响工伤待遇与赔偿）","肺康复（运动训练、呼吸肌训练、营养支持）","疫苗接种（流感、肺炎球菌）","肺移植（终末期尘肺合并严重呼吸衰竭者）","大容量全肺灌洗（选择性用于早期、粉尘负荷大者，需专科评估）"],"life":["**绝对戒烟**（吸烟协同加重肺功能下降并显著增加肺癌风险）","定期复查：每 6–12 个月肺功能与影像（叁期或快速进展者更密切）","结核筛查（每年胸片 + 症状筛查；矽肺者建议 IGRA）","职业健康监护：接尘工人的上岗前、在岗期间（按 GBZ 188）与离岗时体检","防护教育：正确佩戴防尘口罩（KN95 及以上）、湿式作业与通风"]},"prog":"尘肺为不可逆的进行性纤维化疾病，即使脱离粉尘仍可继续进展（尤其矽肺）。壹期患者脱离暴露后多数生存期接近正常；叁期矽肺 5 年生存率显著下降（合并结核或肺心病者更差）。主要死因为呼吸衰竭、肺结核、肺心病与肺癌（矽肺者肺癌风险升高）。早期诊断 + 脱离暴露 + 并发症管理可显著延缓进展。","refs":["《尘肺病诊断标准》GBZ 70-2015（中华人民共和国国家职业卫生标准）","《职业性尘肺病的诊断》（国家卫生健康委）","《内科学》第 9 版（人民卫生出版社）职业性肺病章","2019 ATS/ERS Clinical Practice Guideline: Diagnosis and Detection of Occupational Lung Disease","ILO International Classification of Radiographs of Pneumoconioses (2011 revision)"]},{"id":"resp_asbestosis","name":"石棉肺","aka":["Asbestosis","石棉沉着病"],"rank":4,"basic":{"define":"长期吸入石棉纤维所致的弥漫性肺间质纤维化，是尘肺的一种。与矽肺不同，石棉肺以**双下肺为主的弥漫性纤维化**与**胸膜斑**为特征，并与恶性间皮瘤和肺癌的风险显著升高相关。","risk":["**石棉职业暴露（必要条件）**：石棉开采与加工、造船与修船、建筑拆除与保温材料、汽车刹车片、纺织","暴露剂量与年限（通常潜伏期 15–30 年）","吸烟（与石棉协同，肺癌风险倍增）","暴露后延迟发病（潜伏期长，离岗后仍可发病）"],"epi":"我国石棉相关疾病报告数逐年上升。石棉暴露者肺癌风险较一般人群高 5 倍（吸烟者可达 50 倍以上）；间皮瘤几乎均与石棉暴露相关（潜伏期 20–40 年）。"},"patho":"石棉纤维（尤其长度 >5 µm 的角闪石类）沉积于肺泡与胸膜，巨噬细胞吞噬失败后释放氧自由基与炎性介质，激活成纤维细胞导致弥漫性肺间质纤维化（从呼吸性细支气管周围开始，逐渐扩展至胸膜下）。石棉纤维可直接穿入胸膜引起胸膜斑（纤维化斑块）与胸膜钙化，并可通过染色体损伤与慢性炎症诱导间皮细胞恶变（间皮瘤）。石棉的致纤维化与致癌机制相对独立。","dx":{"criteria":["明确的石棉暴露史（工种、年限，通常 >10 年；但极高浓度暴露可在较短时间后发病）","影像：**双下肺与胸膜下为主的网格影、蜂窝影**；**胸膜斑（最特征，常在膈肌与侧胸壁）与胸膜钙化**；HRCT 更敏感","肺功能：**限制性通气障碍（TLC 与 FVC 降低）与 DLCO 降低**","体征：双下肺吸气末细湿啰音（velcro 啰音）、杵状指（晚期）","诊断同尘肺：职业史 + 影像 + 肺功能，由职业病诊断机构集体诊断","需警惕并存：肺癌（随访筛查）与间皮瘤（胸膜增厚伴胸腔积液时）"],"workup":["详细职业史（含间接暴露：家属清洗工作服、居住于石棉厂附近）","高千伏胸片 + HRCT（评估肺间质与胸膜斑）","肺功能（含肺容积与 DLCO）与 6 分钟步行试验","动脉血气（静息与运动）","痰检石棉小体（辅助，非诊断标准）","肺癌筛查（低剂量 CT，吸烟者尤其）与间皮瘤评估（胸腔积液者胸水细胞学/胸膜活检）","结核与结缔组织病筛查（鉴别）"],"grading":"按 GBZ 70 分期（壹/贰/叁期；石棉肺多见于壹、贰期）；按影像分网格影范围与有无蜂窝肺；按肺功能分轻（FVC 70%–80%）、中（50%–69%）、重（<50%）。"},"ddx":[{"name":"急性上呼吸道感染（resp_uri）","point":"与上感鉴别：上感急性自限，无纤维化影像与限制性通气障碍；石棉肺为慢性进行性。"},{"name":"急性气管支气管炎（resp_acute_bronchitis）","point":"与急性支气管炎鉴别：后者影像与肺功能正常；石棉肺有胸膜斑与限制性障碍。"},{"name":"尘肺与职业性肺病（resp_pneumoconiosis）","point":"与矽肺的鉴别：矽肺为中上肺小结节与融合团块、肺门蛋壳样钙化；石棉肺为双下肺网格影与胸膜斑，限制性障碍更突出。"},{"name":"特发性肺纤维化（ild_ipf）","point":"IPF 与石棉肺影像可相似（UIP 型），但**无石棉暴露史与胸膜斑**；有胸膜斑与明确暴露史时优先考虑石棉肺。"},{"name":"结缔组织病相关间质性肺病","point":"有皮疹、关节痛、雷诺现象与自身抗体（ANA、抗 SSA、抗合成酶）阳性；石棉肺无自身免疫表现。"},{"name":"间皮瘤","point":"胸膜增厚呈结节状伴大量胸腔积液、胸痛明显，胸水细胞学或胸膜活检确诊；石棉肺为良性纤维化（但两者可并存）。"},{"name":"肺癌","point":"孤立或分叶状肿块、有毛刺与强化，PET-CT 高代谢；石棉肺属弥漫性网格影（但需筛查并存肺癌）。"}],"tx":{"drug":[{"name":"无特效抗纤维化药物（现有药物证据有限）","dose":"石棉肺本身无获批抗纤维化治疗；可参照 IPF 使用吡非尼酮/尼达尼布（证据不足，需个体化）","note":"抗纤维化药物在石棉肺中的证据远少于 IPF，需与患者充分讨论利弊与费用","renal":"尼达尼布在重度肾损害慎用","hepatic":"两者均有肝毒性，需监测转氨酶","interact":"尼达尼布是 P-gp 底物，与 P-gp 抑制剂合用升高浓度；吡非尼酮与 CYP1A2 抑制剂（氟伏沙明）合用禁忌"},{"name":"支气管舒张剂（合并气流受限）","dose":"噻托溴铵 18 µg qd 或 LABA/LAMA 联合吸入","note":"石棉肺可合并小气道病变与气流受限，按 COPD 管理","renal":"无需调整","hepatic":"无需调整","interact":"抗胆碱药合用增加副作用"},{"name":"氧疗（低氧血症）","dose":"长期家庭氧疗：静息 PaO₂ ≤55 mmHg 或 SpO₂ ≤88%，每日 ≥15 小时","note":"改善生存与运动耐量","renal":"无","hepatic":"无","interact":"无"},{"name":"疫苗接种与感染预防","dose":"流感疫苗每年一次、肺炎球菌疫苗按年龄与基础病接种","note":"石棉肺患者肺部感染风险高，且感染可诱发急性加重","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"抗结核治疗（合并结核时）","dose":"按标准方案 2HRZE/4HR","note":"石棉肺合并结核率低于矽肺，但仍需筛查","renal":"按 CrCl 调整","hepatic":"监测肝毒性","interact":"利福平诱导 CYP3A4"}],"nonDrug":["**脱离石棉暴露**（进展控制的基础）","职业病诊断与劳动能力鉴定（享有工伤待遇）","肺康复（运动训练、营养支持）","**肺癌筛查：每年低剂量 CT（吸烟者尤其）**","间皮瘤监测（胸痛 + 胸腔积液时行胸水检查与胸膜活检）","肺移植（终末期）"],"life":["**绝对戒烟**（石棉与吸烟协同致肺癌，戒烟是最重要的可干预措施）","职业史告知所有接诊医生（离岗后数十年仍可发病）","定期肺功能与影像随访（每 6–12 个月）","家庭成员需注意间接暴露（工作服清洗）","居住环境中石棉材料的处理需专业机构（避免自行拆除）"]},"prog":"石棉肺进展缓慢但不可逆，从暴露到发病潜伏期 15–30 年，离岗后仍可进展。早期脱离暴露者肺功能下降较慢；进展至蜂窝肺者预后类似 IPF（中位生存 3–5 年）。主要死因为呼吸衰竭、肺癌与间皮瘤。**肺癌与间皮瘤是石棉相关的最致命后果**，长期随访与筛查至关重要。","refs":["《尘肺病诊断标准》GBZ 70-2015","《内科学》第 9 版（人民卫生出版社）职业性肺病章","2010 ATS Official Statement: Diagnosis and Initial Management of Nonmalignant Diseases Related to Asbestos","2017 ERS/ATS Clinical Practice Guideline: Diagnosis of Idiopathic Pulmonary Fibrosis（鉴别参照）","IARC Monographs Volume 100C: Asbestos (2012)"]}]},{"id":"cap_etiologic","name":"肺炎的病原学类型","rank":9,"summary":"同为大叶或支气管肺炎，病原决定痰色、影像形态、好发人群与首选药：肺炎链球菌（铁锈色痰、肺叶实变）是 CAP 首位细菌病原；流感后骤起高热、多发肺脓肿与肺气囊提示金黄色葡萄球菌；老年与酗酒者砖红色胶冻痰、上叶后段实变提示肺炎克雷伯菌；青少年干咳而体征轻、胸片重听诊轻提示肺炎支原体；痰少、双肺弥漫磨玻璃或间质改变提示病毒性肺炎。病原未明时按年龄与严重度经验覆盖，明确后立即降阶梯，48–72 小时无效需重新评估病原与并发症。","compare":[{"diseaseId":"resp_pneumococcus","dx":"骤起高热寒战、胸痛、铁锈色痰；胸片示肺叶实变伴支气管充气征；痰见革兰阳性双球菌、尿抗原阳性","key":"青霉素敏感者首选青霉素 G/阿莫西林，MIC ≥2 mg/L 改头孢曲松或呼吸喹诺酮"},{"diseaseId":"resp_staph_pneumonia","dx":"流感后或高热不退，脓血痰；CT 见多发肺脓肿、肺气囊、脓气胸；培养金黄色葡萄球菌阳性","key":"苯唑西林（MSSA）或万古霉素（MRSA）足量足疗程，脓胸与脓肿必须引流"},{"diseaseId":"resp_klebsiella","dx":"老年、酗酒或基础病者，中毒症状重，砖红色胶冻痰；上叶后段致密实变、叶间裂膨出","key":"耐药风险高，重症首选碳青霉烯，确诊后按药敏与酶型降阶梯"},{"diseaseId":"resp_mycoplasma","dx":"青少年或集体单位聚集，阵发性干咳而体征轻，胸片见斑片或间质浸润，核酸检测阳性","key":"首选大环内酯；我国耐药率高，48–72 小时无效换多西环素或喹诺酮"},{"diseaseId":"resp_viral_pneumonia","dx":"流感/RSV/CMV 背景，痰少、呼吸困难进行性加重，双肺磨玻璃、淋巴细胞减少，核酸阳性","key":"抗病毒有窗口（流感 48 小时内，重症不限），警惕 5–7 天后继发细菌感染"}],"diseases":[{"id":"resp_pneumococcus","name":"肺炎链球菌肺炎","aka":["Pneumococcal pneumonia","大叶性肺炎","肺炎球菌肺炎"],"rank":1,"basic":{"define":"由肺炎链球菌（Streptococcus pneumoniae）引起的肺实质炎症，是社区获得性肺炎（CAP）最常见的细菌性病原，典型者呈肺叶或肺段大叶实变。","risk":["年龄两端：婴幼儿与 ≥65 岁","COPD、糖尿病、慢性心/肝/肾病、镰状细胞贫血","脾切除或无脾功能（暴发性感染高危）","HIV、恶性肿瘤、长期激素或免疫抑制剂","吸烟、酗酒、近期流感等呼吸道病毒感染","未接种肺炎球菌疫苗"],"epi":"肺炎链球菌约占成人 CAP 可确诊细菌病原的 30%–50%，我国亦为首位；侵袭性肺炎球菌病在老年人病死率可达 15% 以上，有菌血症者更高。"},"patho":"定植于鼻咽部，病毒感染后随分泌物吸入下叶；荚膜抗吞噬、肺炎链球菌溶血素损伤肺泡上皮，炎症经 Kohn 孔蔓延使整个肺叶受累，呈充血水肿、红色肝变、灰色肝变与消散四期。约 20%–30% 合并菌血症，可并发脓胸、肺脓肿、心包炎或脑膜炎。","dx":{"criteria":["急性起病，寒战高热（39–41 ℃）、患侧针刺样胸痛（呼吸咳嗽加重）、咳嗽咳痰。","铁锈色痰（红细胞被血红蛋白分解所致，仅 10%–20% 出现，不作为必需条件）。","体检：叩诊浊音、语颤增强、支气管呼吸音与湿啰音；伴胸膜炎可闻及摩擦音。","影像：胸片见肺叶或肺段实变伴支气管充气征，下叶多见。","血常规白细胞升高伴中性粒核左移，CRP 与 PCT 升高；老年可白细胞减少。","病原：痰革兰染色见白细胞内革兰阳性双球菌、痰培养、血培养、尿肺炎球菌抗原（不受抗生素影响）。","确诊需病原学证据，不能仅凭痰色。"],"workup":["胸片正侧位，住院者建议 CT 评估实变范围与是否合并胸腔积液","合格痰涂片 + 培养、血培养 ≥2 套、尿抗原","血常规、CRP、PCT、肝肾功能与电解质","血气或指脉氧，严重者加测乳酸","胸腔超声与穿刺（有积液时做常规、生化、培养与肺炎球菌抗原）","CURB-65 或 PSI 评估严重度，决定门诊或住院"],"grading":"按影像分大叶性、支气管肺炎与间质性肺炎；按严重度用 CURB-65/PSI 分层；伴菌血症、脓胸或脑膜炎归为侵袭性肺炎球菌病，按重症处理。"},"ddx":[{"name":"肺炎克雷伯菌肺炎","point":"与本类中肺炎克雷伯菌肺炎的鉴别点：克雷伯菌多见于老年与酗酒者，痰为砖红色胶冻样而非铁锈色，上叶后段实变伴叶间裂膨出、易坏死，痰涂片见革兰阴性杆菌，肺炎球菌尿抗原阴性。"},{"name":"葡萄球菌肺炎","point":"与本类中葡萄球菌肺炎的鉴别点：葡萄球菌多有流感后或静脉吸毒史，脓血痰，影像为多发肺脓肿与肺气囊、易气胸；肺炎球菌为肺叶均匀实变。"},{"name":"肺炎支原体肺炎","point":"与本类中肺炎支原体肺炎的鉴别点：支原体多见于青少年，干咳为主、体征轻、白细胞多正常，β-内酰胺无效；肺炎球菌大叶实变、白细胞高、青霉素有效。"},{"name":"肺栓塞","point":"突发呼吸困难与胸痛，发热不显著，D-二聚体升高，CTPA 见充盈缺损。"},{"name":"肺结核","point":"亚急性病程、低热盗汗，好发上叶尖后段，有空洞与树芽征，抗酸染色与结核核酸阳性。"}],"tx":{"drug":[{"name":"青霉素 G","dose":"轻中度 160 万–240 万 U 静滴 q6h（日总量 480 万–960 万 U）；重症遵说明书加量分次静滴","note":"青霉素敏感（MIC ≤2 mg/L）的首选；用药前皮试，警惕过敏性休克","renal":"肾功能不全减量或延长间隔","hepatic":"无需调整","interact":"不宜与大环内酯、四环素类联用（减效）；丙磺舒升高血药浓度"},{"name":"阿莫西林","dose":"1 g 口服 tid 或 0.5 g tid（日剂量 1.5–4 g）","note":"门诊轻症首选，生物利用度高；青霉素耐药株不单独使用","renal":"CrCl <30 mL/min 减量或延长间隔","hepatic":"轻中度无需调整","interact":"与别嘌醇合用皮疹增多；与华法林合用需监测 INR"},{"name":"头孢曲松","dose":"1–2 g 静滴 qd，重症 2 g q12h","note":"青霉素过敏（非速发型）或 MIC 2–4 mg/L 者首选；对非典型病原无效，重症需联合","renal":"一般无需调整","hepatic":"无需调整","interact":"新生儿禁与含钙输液同瓶；与华法林相互作用"},{"name":"阿奇霉素","dose":"0.5 g 静滴/口服 qd，疗程 3–5 天","note":"覆盖非典型病原，重症 CAP 常与 β-内酰胺联用；我国肺炎球菌大环内酯耐药较普遍，不作单药首选","renal":"CrCl <30 mL/min 慎用或减量","hepatic":"严重肝功能不全禁用","interact":"延长 QT；与华法林合用增加出血"},{"name":"莫西沙星","dose":"0.4 g 静滴/口服 qd","note":"青霉素过敏或高耐药地区的替代方案，评估 QT 与肌腱风险","renal":"无需调整","hepatic":"Child-Pugh C 慎用","interact":"禁与胺碘酮、索他洛尔合用；与糖皮质激素合用增加肌腱断裂"},{"name":"万古霉素","dose":"15–20 mg/kg 静滴 q8–12h，按 AUC/MIC 400–600 调整","note":"仅用于青霉素与头孢菌素均过敏的重症患者或确认耐药","renal":"按 CrCl 与血药浓度调整","hepatic":"无需调整","interact":"与哌拉西林/他唑巴坦合用增加急性肾损伤"}],"nonDrug":["氧疗：SpO₂ 目标 ≥90%（COPD 88%–92%），必要时 HFNC/无创/有创通气","脓胸或中量以上胸腔积液置管引流","疗程 5–7 天，临床稳定即可停药；菌血症 10–14 天，脓胸与原发灶并发症延长","接种肺炎球菌结合疫苗与多糖疫苗（≥65 岁及高危人群）","48–72 小时无效需复查影像与病原，警惕脓胸或诊断错误"],"life":["戒烟限酒，控制糖尿病等基础病","出院 4–6 周复查胸片确认吸收（吸烟者与老年人需排除阻塞性病变）","脾切除者接种疫苗，发热时警惕暴发性感染"]},"prog":"敏感株规范治疗后病死率 <5%，门诊多 3–5 天退热；菌血症、老年与基础病者病死率 15%–30%。约 5%–10% 遗留胸膜增厚或肺不张；反复同一部位复发需排查结构或免疫缺陷病变。","refs":["中华医学会呼吸病学分会《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国成人社区获得性肺炎基层诊疗指南》（2019）","《国家抗微生物治疗指南（第 3 版）》（2022）"]},{"id":"resp_staph_pneumonia","name":"葡萄球菌肺炎","aka":["Staphylococcal pneumonia","金黄色葡萄球菌肺炎","MRSA 肺炎"],"rank":2,"basic":{"define":"由金黄色葡萄球菌引起的坏死性肺炎，可为原发性（吸入性，常继发于流感）或继发性（血源性，来自皮肤软组织、骨髓炎、导管或静脉吸毒感染）。","risk":["流感或麻疹后病毒性肺炎继发","静脉吸毒、皮肤软组织感染、血管内导管","糖尿病、慢性肾病与血液透析","囊性纤维化、支气管扩张及 ICU 住院（MRSA 定植）","机械通气、近期广谱抗生素或糖皮质激素","早产儿与新生儿"],"epi":"金黄色葡萄球菌约占 CAP 细菌病原的 3%–5%，但流感后继发肺炎中可达 20%–30%；我国 ICU 中 MRSA 分离比例可达 20%–40%，MRSA 肺炎病死率 30%–50%。"},"patho":"经吸入或血行到达肺，α-溶血素、杀白细胞素（PVL）等毒素破坏上皮与中性粒细胞，引起急性化脓坏死性肺炎；脓液经支气管排出形成薄壁肺气囊，可破裂致气胸或脓气胸。血源性者以多发外周结节浸润为主；PVL 阳性株坏死与出血更重。","dx":{"criteria":["流感或上呼吸道感染后数日内体温再度骤升、寒战，脓血痰或咯血，呼吸困难进行性加重。","血源性者伴皮肤感染、骨髓炎、静脉吸毒或导管感染史。","影像：多发斑片与结节状实变，短期内出现肺气囊、肺脓肿、气胸或脓气胸，动态变化是重要线索。","白细胞显著升高或减少，CRP/PCT 明显升高，流感后淋巴细胞减少。","病原：痰或气管吸出物培养出金黄色葡萄球菌、血培养（血源性阳性率高）、胸腔积液培养，PVL 基因可选查。","以药敏区分 MSSA（苯唑西林 MIC ≤2 mg/L）与 MRSA，作为选药依据。"],"workup":["胸部 CT：评估肺脓肿、肺气囊与胸膜病变","血培养 ≥2 套、痰/气管吸出物培养与革兰染色（簇状革兰阳性球菌）","胸腔超声与穿刺引流，胸水做常规、生化与培养","超声心动图：静脉吸毒或脓毒血症者排查心内膜炎","流感与新冠核酸检测","血气、乳酸、肝肾功能与凝血"],"grading":"按来源分原发吸入性与继发血源性；按药敏分 MSSA 与 MRSA；按并发症分单纯肺炎、肺脓肿、肺气囊与脓气胸。"},"ddx":[{"name":"肺炎链球菌肺炎","point":"与本类中肺炎链球菌肺炎的鉴别点：肺炎球菌为肺叶均匀实变与铁锈色痰，少见肺脓肿与肺气囊；葡萄球菌多继发于流感，脓血痰、影像迅速出现空洞、肺气囊与气胸。"},{"name":"肺炎克雷伯菌肺炎","point":"与本类中肺炎克雷伯菌肺炎的鉴别点：克雷伯菌痰为砖红色胶冻样、好发上叶后段、以组织坏死为特征，患者多为老年或酗酒者；葡萄球菌更常见于青年流感后或血源性感染，伴肺气囊。"},{"name":"病毒性肺炎","point":"与本类中病毒性肺炎的鉴别点：病毒性肺炎以弥漫磨玻璃/间质改变为主，无脓肿与肺气囊；病毒感染期间症状再加重、出现脓痰与空洞，应考虑继发葡萄球菌感染。"},{"name":"肺结核（空洞型）","point":"慢性病程、上叶尖后段、厚壁空洞伴卫星灶，抗酸染色与结核核酸阳性。"},{"name":"肺鳞癌伴空洞","point":"厚壁偏心空洞伴壁结节，病程较长，需支气管镜与病理。"}],"tx":{"drug":[{"name":"苯唑西林（MSSA）","dose":"2 g 静滴 q4–6h，疗程 2–3 周；并发脓胸或肺脓肿 4–6 周","note":"MSSA 首选，疗效优于万古霉素；用药前皮试","renal":"CrCl <30 mL/min 延长间隔或减量","hepatic":"轻中度无需调整","interact":"与氨基糖苷类合用增加肾毒性"},{"name":"头孢唑林（MSSA 替代）","dose":"1–2 g 静滴 q8h","note":"苯唑西林不可用时选用","renal":"按 CrCl 调整间隔","hepatic":"无需调整","interact":"与华法林合用需监测 INR"},{"name":"万古霉素（MRSA）","dose":"15–20 mg/kg 静滴 q8–12h，按 AUC/MIC 400–600 调整；疗程 2–3 周，并发症 4–6 周","note":"MRSA 肺炎首选，肺组织穿透差，须足剂量并监测血药浓度","renal":"按 CrCl 与 AUC 调整间隔","hepatic":"无需调整","interact":"与哌拉西林/他唑巴坦、氨基糖苷类合用增加肾毒性"},{"name":"利奈唑胺（MRSA 替代）","dose":"600 mg 静滴/口服 q12h，疗程 10–14 天","note":"肺组织穿透好，适用于万古霉素疗效不佳或肾功能不全；长期使用注意骨髓抑制与周围神经病","renal":"无需调整（透析后遵说明书）","hepatic":"Child-Pugh B/C 慎用","interact":"弱 MAO 抑制，禁与拟肾上腺素、5-HT 再摄取抑制剂合用"},{"name":"克林霉素","dose":"600 mg 静滴 q8h","note":"抑制毒素产生，可用于 MSSA 或 PVL 阳性社区株的联合治疗；MRSA 需药敏支持","renal":"无需调整","hepatic":"重度肝病减量；警惕艰难梭菌相关性腹泻","interact":"与神经肌肉阻滞剂协同；与大环内酯类拮抗"},{"name":"头孢曲松（流感后联合）","dose":"1–2 g 静滴 qd，与抗葡萄球菌药联用","note":"怀疑流感后混合感染（肺炎球菌、流感嗜血杆菌）时叠加使用","renal":"一般无需调整","hepatic":"无需调整","interact":"新生儿禁与含钙输液同瓶；与华法林相互作用"}],"nonDrug":["脓胸与肺脓肿尽早胸腔闭式引流或外科处理，引流不畅是治疗失败主因","气胸/脓气胸置管引流，必要时负压吸引","重症休克按脓毒症集束化治疗","流感流行季加用奥司他韦治疗原发病毒感染","心内膜炎、骨髓炎等迁徙灶需静脉抗生素 4–6 周","48–72 小时不改善需复查 CT 评估脓肿、引流充分性与药敏"],"life":["静脉吸毒者做戒毒咨询并拔除感染导管","控制血糖，皮肤伤口护理","出院随访影像（肺气囊多自行吸收）","MRSA 患者接触隔离，落实手卫生与导管管理"]},"prog":"MSSA 肺炎病死率约 10%–20%，MRSA 可达 30%–50%；流感后坏死性肺炎可在 24–48 小时内迅速进展。肺气囊多在 2–6 周吸收。合并菌血症、休克或心内膜炎者预后差。","refs":["中华医学会呼吸病学分会《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南》（2018）","《国家抗微生物治疗指南（第 3 版）》（2022）"]},{"id":"resp_klebsiella","name":"肺炎克雷伯菌肺炎","aka":["Klebsiella pneumoniae pneumonia","克雷伯菌肺炎","弗里德兰德杆菌肺炎"],"rank":3,"basic":{"define":"由肺炎克雷伯菌（革兰阴性荚膜杆菌）引起的肺炎，典型者好发上叶后段、以组织坏死与脓肿为特征；分社区获得性与医院获得性/呼吸机相关，后者以 ESBL 与碳青霉烯耐药株为主。","risk":["老年、体弱、营养不良与卧床患者","长期酗酒（典型胶冻样痰多见于此人群）","糖尿病（易发生侵袭性肝脓肿与转移性感染）","COPD、慢性肝病与慢性肾病","近期广谱抗生素、ICU 住院、机械通气","既往检出耐药株或碳青霉烯耐药高发病区"],"epi":"肺炎克雷伯菌是我国 HAP/VAP 主要革兰阴性病原之一，分离率居前 3 位；社区获得性病例常伴基础病，病死率约 15%–30%，我国部分医院碳青霉烯耐药株（CRKP）检出率达 20%–30%。"},"patho":"荚膜多糖抗吞噬、内毒素引起强烈炎症与液化坏死，病变多始于上叶后段并形成多发脓肿，致密实变可使叶间裂膨出。耐药以产 ESBL、AmpC 酶与碳青霉烯酶（KPC、NDM 等）为主，显著延长疗程并升高病死率。","dx":{"criteria":["老年、酗酒或糖尿病患者起病急，寒战高热与全身中毒症状显著。","稠厚的砖红色或暗红色胶冻样痰，可拉丝，部分咯血。","可早期出现呼吸困难、意识改变与脓毒症/休克。","影像：上叶后段致密实变、边缘膨隆、叶间裂下坠，内见多发小空洞或脓肿，可并发脓胸。","白细胞正常或升高（重症下降），CRP 与 PCT 显著升高。","病原：痰涂片见革兰阴性粗短杆菌，痰/气管吸出物培养阳性并做药敏与 ESBL、碳青霉烯酶表型，血培养约 30% 阳性，必要时检测耐药基因（blaKPC、blaNDM）。","痰培养阳性须结合临床与影像区分定植与感染。"],"workup":["胸部 CT：评估实变范围、空洞、叶间裂膨出与胸腔积液","痰涂片与培养药敏、血培养 ≥2 套、耐药基因检测","血常规、CRP、PCT、肝肾功能、电解质与血糖","血气与乳酸，评估是否需 ICU","胸腔超声与穿刺","耐药风险评估：90 天内住院或抗生素使用、机械通气、既往检出史"],"grading":"按来源分社区获得性与医院获得性；按耐药分敏感株、ESBL 阳性与碳青霉烯耐药（CRKP）；按影像分单纯肺炎、坏死性肺炎/肺脓肿与脓胸。"},"ddx":[{"name":"肺炎链球菌肺炎","point":"与本类中肺炎链球菌肺炎的鉴别点：肺炎球菌痰为铁锈色、以肺叶均匀实变为主、少见坏死空洞；克雷伯菌痰为砖红色胶冻样，老年酗酒者多见，上叶后段实变伴叶间裂膨出，痰涂片为革兰阴性杆菌。"},{"name":"葡萄球菌肺炎","point":"与本类中葡萄球菌肺炎的鉴别点：葡萄球菌多继发于流感、青年或静脉吸毒者，肺气囊与气胸突出，革兰阳性球菌；克雷伯菌好发上叶后段、革兰阴性杆菌，二者均需培养药敏区分。"},{"name":"铜绿假单胞菌肺炎","point":"多见于结构性肺病与长期机械通气者，痰呈绿色脓性，培养见革兰阴性杆菌，需菌种鉴定与药敏区分。"},{"name":"肺结核","point":"亚急性病程，低热盗汗，树芽征与空洞，抗酸染色与结核核酸阳性。"},{"name":"厌氧菌性肺脓肿","point":"多与误吸和牙周病有关，痰奇臭，厌氧培养阳性。"}],"tx":{"drug":[{"name":"头孢曲松","dose":"2 g 静滴 qd，重症 q12h","note":"无耐药风险的社区获得性病例初始经验用药；有 ESBL 风险者不宜","renal":"一般无需调整","hepatic":"无需调整","interact":"新生儿禁与含钙输液同瓶；与华法林相互作用"},{"name":"哌拉西林/他唑巴坦","dose":"4.5 g 静滴 q8h，延长输注 3–4 小时，重症 q6h","note":"覆盖多数 ESBL 产酶株与铜绿假单胞菌；对碳青霉烯酶无效","renal":"CrCl 20–40 mL/min 4.5 g q8h；CrCl <20 mL/min 2.25 g q8h","hepatic":"无需调整","interact":"与万古霉素合用增加急性肾损伤"},{"name":"美罗培南","dose":"1 g 静滴 q8h（延长输注 3 小时），重症可 2 g q8h","note":"ESBL 阳性或重症坏死性肺炎的首选","renal":"按 CrCl 调整剂量与间隔","hepatic":"无需调整","interact":"与丙戊酸合用显著降低其浓度（禁用）"},{"name":"头孢他啶/阿维巴坦（CRKP）","dose":"2.5 g 静滴 q8h，输注 2 小时，疗程 10–14 天","note":"KPC 型碳青霉烯酶首选；对 NDM 等金属酶无效，须按酶型选药","renal":"按 CrCl 调整（如 CrCl 31–50 mL/min 1.25 g q8h）","hepatic":"轻中度无需调整","interact":"注意合并肾毒性药物"},{"name":"多黏菌素 B（CRKP 联合）","dose":"负荷 2–2.5 mg/kg 后 1.25–1.5 mg/kg q12h","note":"碳青霉烯耐药且无更优选择时的联合方案，常与美罗培南或替加环素联用","renal":"主要非肾排泄；多黏菌素 E 按肾功能调整","hepatic":"无需调整","interact":"与氨基糖苷、万古霉素合用增加肾毒性；有神经肌肉阻滞作用"},{"name":"替加环素（联合）","dose":"首剂 100 mg 静滴，后 50 mg q12h","note":"不单独用于 CRKP 肺炎（肺内浓度低），以联合方案应用；不覆盖铜绿假单胞菌","renal":"无需调整","hepatic":"Child-Pugh C：首剂 100 mg，后 25 mg q12h","interact":"与华法林合用需监测 INR"}],"nonDrug":["药敏回报后尽快降阶梯至窄谱有效方案","肺脓肿与脓胸需引流，引流不畅者预后差","脓毒性休克按集束化复苏，呼吸衰竭需机械通气","疗程 7–14 天，坏死性肺炎、肺脓肿或脓胸 3–6 周","院感防控：接触隔离、手卫生、减少碳青霉烯滥用"],"life":["严格戒酒，控制血糖","营养支持，意识障碍者防误吸","出院 4–6 周复查 CT，观察空洞闭合","出院带药按药敏，避免长期无指征广谱抗生素"]},"prog":"敏感株社区获得性肺炎病死率 15%–25%，ESBL 与 CRKP 感染可升至 30%–50%。糖尿病合并侵袭性肝脓肿者可伴眼内炎与脑膜炎，需早期识别。残留空洞可数月方吸收。","refs":["《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南》（2018）","《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国碳青霉烯耐药肠杆菌科细菌感染诊治与防控专家共识》（2021）"]},{"id":"resp_mycoplasma","name":"肺炎支原体肺炎","aka":["Mycoplasma pneumoniae pneumonia","MPP","原发性非典型肺炎"],"rank":4,"basic":{"define":"由肺炎支原体（无细胞壁病原体）引起的社区获得性肺炎，好发于儿童与青少年，以干咳为主、体征轻而影像改变明显；重症可致节段性实变、胸腔积液与血栓事件。","risk":["学龄儿童、青少年与青年（5–20 岁高发）","学校、寄宿制学校、军营等集体单位与家庭聚集","密闭人员密集场所，冬春季与秋冬季流行","COPD、哮喘患者感染后易加重","大环内酯耐药高发地区人群（我国耐药率显著高于欧美）"],"epi":"肺炎支原体占成人 CAP 病原约 10%–30%，儿童中可达 20%–40%；我国大环内酯耐药率报道可达 50% 以上，学龄儿童与集体单位最受影响。"},"patho":"病原黏附呼吸道上皮纤毛细胞，释放过氧化物与社区获得性呼吸窘迫综合征毒素（CARDS），引起上皮损伤与支气管周围淋巴细胞间质炎症，故影像呈斑片或磨玻璃浸润而听诊体征少。免疫反应参与皮疹、溶血性贫血、脑炎与关节炎等肺外表现。","dx":{"criteria":["学龄儿童、青少年或成人亚急性起病（数日至 1–2 周），阵发性干咳突出，伴咽痛、低至中度发热与乏力。","肺部体征轻或缺乏，与影像浸润范围不相称（体征与影像分离为典型特点）。","影像：斑片磨玻璃浸润、支气管周围增厚或间质改变，重症可呈单叶节段实变。","白细胞多正常或轻度升高，CRP 轻度升高，PCT 一般正常（升高提示细菌混合感染）。","血清学：双份血清（间隔 2–4 周）抗体滴度 ≥4 倍升高可回顾性确诊；单次 IgM ≥1:160 支持近期感染。","核酸：咽拭子或痰 PCR 检测支原体 DNA/RNA，为首选，可同时检测大环内酯耐药基因。"],"workup":["胸部 CT：明确实变范围、胸腔积液、支气管壁增厚与黏液栓","咽拭子或痰支原体核酸 PCR，必要时耐药基因检测","双份血清抗体","血常规、CRP、PCT、肝功能（可伴转氨酶升高）","重症查血气、D-二聚体与凝血（儿童可并发肺栓塞）","出现皮疹、贫血或神经系统症状时做相应评估"],"grading":"分轻症（门诊、无低氧）与重症（呼吸急促、低氧、节段或多叶实变、胸腔积液、肺外并发症）；按对大环内酯的临床反应区分为敏感与耐药。"},"ddx":[{"name":"病毒性肺炎","point":"与本类中病毒性肺炎的鉴别点：流感/RSV 起病更急、肌痛显著、淋巴细胞减少，有抗病毒窗口；两者均可呈间质改变，需 PCR 区分，支原体以亚急性阵发性干咳与体征轻为特点。"},{"name":"肺炎链球菌肺炎","point":"与本类中肺炎链球菌肺炎的鉴别点：肺炎球菌骤起高热、铁锈色痰、大叶实变、白细胞明显升高，β-内酰胺敏感；支原体多见于青少年、体征轻、β-内酰胺无效。"},{"name":"肺结核","point":"咳嗽咳痰超过 2 周不缓解，盗汗消瘦，上叶尖后段空洞与树芽征，结核核酸与 IGRA 阳性。"},{"name":"百日咳","point":"阵发性痉挛性咳嗽伴吸气性吼声，成人可仅表现为长期咳嗽，百日咳核酸阳性。"},{"name":"军团菌肺炎","point":"高热伴相对缓脉、腹泻与低钠血症，尿抗原阳性。"}],"tx":{"drug":[{"name":"阿奇霉素","dose":"成人 0.5 g 口服/静滴 qd 连用 3 天，或首日 0.5 g 后 0.25 g qd 至第 5 天；儿童 10 mg/kg 首日、后 5 mg/kg","note":"首选；我国耐药率高，48–72 小时无改善须换药","renal":"CrCl <30 mL/min 慎用或减量","hepatic":"严重肝功能不全禁用","interact":"延长 QT；与华法林合用增加出血"},{"name":"克拉霉素","dose":"0.5 g 口服 bid，疗程 7–14 天","note":"大环内酯替代，CYP3A4 相互作用较强","renal":"CrCl <30 mL/min 减半","hepatic":"严重肝功能不全慎用","interact":"禁与辛伐他汀、西沙必利等 CYP3A4 底物合用"},{"name":"多西环素","dose":"100 mg 口服/静滴 bid，首日可 200 mg，疗程 7–10 天；≥8 岁儿童按体重","note":"大环内酯无效或耐药时的替代","renal":"重度肾衰慎用","hepatic":"肝功能不全慎用","interact":"与含铝镁钙抗酸剂、铁剂间隔 2 小时；光敏反应"},{"name":"莫西沙星（成人）","dose":"0.4 g 口服/静滴 qd，疗程 7–10 天","note":"成人替代方案，对耐药株有效；18 岁以下禁用","renal":"无需调整","hepatic":"Child-Pugh C 慎用","interact":"禁与延长 QT 药物合用；与糖皮质激素合用增加肌腱断裂"},{"name":"泼尼松（重症）","dose":"成人 0.5–1 mg/kg/d；儿童 1–2 mg/kg/d，遵儿科重症共识，短期使用","note":"仅用于重症或难治性病例（高热不退、大叶实变、炎症指标显著升高），须排除细菌混合感染，不推荐常规使用","renal":"无需调整","hepatic":"无需调整","interact":"与喹诺酮合用增加肌腱断裂；与 NSAIDs 合用增加消化道出血"}],"nonDrug":["轻症门诊治疗，休息补液，无低氧一般无需住院","低氧者氧疗；黏液栓阻塞的重症可支气管镜清理","疗程：阿奇霉素 3–5 天，多西环素或喹诺酮 7–10 天，重症 10–14 天","集体单位聚集者呼吸道隔离观察，儿童症状缓解后 5 天可返园","48–72 小时无改善提示耐药或重症，需换药并评估激素"],"life":["发病期间休息，暂停集体活动","2–4 周复查影像，节段实变吸收可长达 4–8 周","感染后咳嗽可持续 2–4 周，告知患者无需反复使用抗生素"]},"prog":"多数为自限性轻症，有效治疗后 3–5 天缓解；耐药株热程延长、影像吸收慢。重症约 5%–10%，可并发胸腔积液、坏死性肺炎、肺栓塞与哮喘加重，儿童可并发脑炎与 Stevens-Johnson 综合征。成人病死率低。","refs":["《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国儿童肺炎支原体肺炎诊疗指南》（2023 年版）","《国家抗微生物治疗指南（第 3 版）》（2022）"]},{"id":"resp_viral_pneumonia","name":"病毒性肺炎","aka":["Viral pneumonia","流感病毒肺炎","RSV 肺炎","CMV 肺炎"],"rank":5,"basic":{"define":"由流感病毒、呼吸道合胞病毒、腺病毒、人偏肺病毒、鼻病毒、副流感病毒，以及免疫抑制者的巨细胞病毒与疱疹病毒等引起的肺实质炎症，可单独发生或作为细菌性肺炎的前驱与混合感染。","risk":["冬春季流行，人群密集场所","≥65 岁与婴幼儿","妊娠、肥胖、慢性心肺疾病、糖尿病","免疫抑制（CMV 肺炎多见于移植、HIV 与化疗后）","烟草暴露与 COPD、哮喘","医务人员与集体居养人员"],"epi":"病毒约占成人 CAP 病原的 20%–30%，流感季可达 40%，以流感病毒最常见；全球每年流感相关呼吸系统死亡 29 万–65 万例。RSV 是老年人（>60 岁）与婴幼儿住院的重要病因。"},"patho":"病毒侵袭气道上皮与肺泡二型细胞，引起上皮坏死、纤毛脱落与单核细胞间质浸润，间质水肿与透明膜形成导致弥散障碍与低氧；重症流感可出现弥漫性肺泡损伤（类 ARDS）。黏膜屏障破坏与局部免疫下调使 5–10 天后易继发肺炎链球菌、金黄色葡萄球菌或流感嗜血杆菌感染，是死亡的重要加重因素。CMV 肺炎以弥漫性间质性肺炎与中性粒细胞减少为特点。","dx":{"criteria":["流感：突起高热（39–40 ℃）、头痛、肌痛乏力与干咳；2–5 天后不缓解反加重、出现呼吸困难与低氧提示肺炎。","RSV：婴幼儿喘息与三凹征；老年人症状可不典型，表现为食欲下降、意识改变与低热。","CMV（免疫抑制）：亚急性发热、干咳、进行性低氧，伴中性粒细胞减少与肝炎、视网膜炎。","影像：双肺磨玻璃、斑点或网状间质浸润，可呈肺门周围分布；CT 见弥漫磨玻璃、铺路石征或小叶中心结节，无典型肺叶实变。","白细胞正常或降低，淋巴细胞减少，CRP 轻中度升高、PCT 正常或轻度升高。","病原：呼吸道多重核酸 PCR 为首选；免疫抑制者做 CMV 血或肺泡灌洗液核酸与 pp65 抗原；快速抗原敏感性低。","继发细菌感染线索：发热再度骤升、脓痰、PCT 显著升高、影像出现新实变或空洞。"],"workup":["胸部高分辨率 CT：区分间质型与实变型，排查继发细菌感染与肺栓塞","呼吸道病毒核酸多重 PCR（鼻咽拭子、痰或 BAL）","血常规、CRP 与 PCT 动态监测","血气或指脉氧，必要时乳酸","心肌酶与心电图（流感重症可合并心肌炎）","免疫抑制者查 CMV DNA 定量与 GM 试验"],"grading":"按病原分类（流感、RSV、腺病毒、CMV 等）；按严重度分轻症、重症与 ARDS；影像分间质/磨玻璃型与实变型，并标注是否继发细菌感染。"},"ddx":[{"name":"肺炎支原体肺炎","point":"与本类中肺炎支原体肺炎的鉴别点：均可呈间质浸润且白细胞不高；支原体多见于青少年、亚急性阵发性干咳，需 PCR 区分；流感起病更急、全身中毒症状显著、有明确抗病毒窗口。"},{"name":"肺炎链球菌肺炎","point":"与本类中肺炎链球菌肺炎的鉴别点：肺炎球菌为肺叶实变、脓痰、白细胞与 PCT 显著升高，β-内酰胺有效；病毒性肺炎为弥漫磨玻璃、无充气支气管征。"},{"name":"葡萄球菌肺炎（流感后）","point":"与本类中葡萄球菌肺炎的鉴别点：流感症状改善后再高热、脓血痰，CT 出现肺脓肿与肺气囊即提示继发葡萄球菌感染，须立即加抗葡萄球菌药。"},{"name":"非感染性 ARDS","point":"符合柏林标准的弥漫磨玻璃与低氧，但需除外胰腺炎、创伤、吸入与大量输血等病因。"},{"name":"心源性肺水肿","point":"端坐呼吸、双肺底湿啰音、BNP 升高、心脏增大，利尿后影像迅速吸收。"}],"tx":{"drug":[{"name":"奥司他韦（流感）","dose":"成人 75 mg 口服 bid，疗程 5 天；重症或免疫抑制者 5–10 天；儿童按体重 30–75 mg bid","note":"发病 48 小时内用药获益最大；重症、孕妇与高危人群疑诊即用，不受 48 小时限制","renal":"CrCl 30–60 mL/min 30 mg bid；CrCl 10–30 mL/min 30 mg qd；透析遵说明书","hepatic":"轻中度无需调整","interact":"与减毒活流感疫苗同期不推荐；丙磺舒升高血药浓度"},{"name":"帕拉米韦（流感重症）","dose":"成人 300–600 mg 静脉滴注 ≥15 分钟，单次；重症可每日 1 次连用 1–5 天","note":"不能口服或重症者的静脉选择","renal":"按 CrCl 调整剂量与频次","hepatic":"无需调整","interact":"遵说明书"},{"name":"玛巴洛沙韦（流感）","dose":"成人及 ≥12 岁：40–80 kg 40 mg 单次，≥80 kg 80 mg 单次","note":"单剂治疗无并发症流感；重症住院患者数据有限，不推荐常规使用","renal":"重度肾功能不全遵说明书","hepatic":"严重肝功能不全遵说明书","interact":"与含铝镁铁钙的制剂及乳制品同期可降低吸收，需间隔服用"},{"name":"更昔洛韦（CMV 肺炎）","dose":"诱导期 5 mg/kg 静滴 q12h，2–3 周；维持期 5 mg/kg qd 或按肾功能调整","note":"CMV 肺炎首选，须监测骨髓抑制与肾功能","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与齐多夫定合用增加骨髓抑制；与亚胺培南合用增加癫痫风险"},{"name":"经验性抗菌药物（继发感染）","dose":"按可能病原选择：如头孢曲松 1–2 g 静滴 qd 覆盖肺炎球菌；流感后重症加苯唑西林或万古霉素","note":"不推荐对单纯病毒性肺炎常规使用抗生素；PCT 升高、脓痰或新发实变时再加","renal":"按药物与 CrCl 调整","hepatic":"按药物调整","interact":"按具体药物"}],"nonDrug":["飞沫隔离与手卫生，减少院内传播","氧疗：SpO₂ 目标 90%–94%（COPD 88%–92%）；HFNC、无创通气或俯卧位；ARDS 按肺保护性通气（6 mL/kg 预测体重）","重症采用限制性液体策略，监测尿量与乳酸","动态 CRP/PCT、重复培养与影像识别继发细菌感染","难治性低氧可考虑 ECMO","每年接种流感疫苗，高危人群优先"],"life":["发热期休息补液，退热 24–48 小时后逐步恢复活动","老年与慢性病者出院后评估肺功能与运动耐量","家庭通风与手卫生，避免近距离接触高危人群","恢复期避免剧烈运动（警惕心肌炎），症状反复及时复诊"]},"prog":"轻症 1–2 周自行缓解；住院病毒性肺炎病死率约 5%–15%，重症 ARDS 可达 30%–40%。合并继发细菌感染与免疫抑制者风险显著升高。感染后咳嗽持续 2–4 周，部分患者遗留弥散功能下降。","refs":["《流行性感冒诊疗方案（2020 年版，国家卫健委）》","《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","《中国成人流行性感冒诊疗规范急诊专家共识》（2022）"]}]},{"id":"resp_other_gap","name":"其他呼吸疾病","rank":10,"summary":"本类收集中枢教材常考但前几类未覆盖的三组问题：结核性胸膜炎以渗出性胸水与 ADA 升高为诊断核心，诊断性抽液同时兼顾治疗；慢性肺源性心脏病由肺动脉高压与右心衰构成，治疗强调氧疗与利尿的平衡；呼吸调节异常与肥胖低通气以日间高碳酸血症和夜间低通气为核心，夜间无创通气是重点。三者共同点是先明确可治病因，再长期随访管理。","compare":[{"diseaseId":"resp_tb_pleurisy","dx":"低热盗汗、胸痛咳嗽，影像示单侧渗出性胸腔积液；胸水淋巴细胞为主、ADA >40 U/L、IGRA 阳性","key":"诊断性胸腔穿刺 + 胸水 ADA 与结核核酸确诊，四联抗结核 6 个月，大量积液可短期加激素"},{"diseaseId":"resp_cor_pulmonale","dx":"COPD/间质病基础上进行性呼吸困难、颈静脉怒张、肝大与下肢水肿；超声估测 PASP >30 mmHg、右心扩大","key":"基础病治疗 + 长期氧疗 + 谨慎利尿，避免过度利尿致低血压与痰液黏稠"},{"diseaseId":"resp_hypoventilation","dx":"BMI ≥30、日间嗜睡与晨起头痛，清醒时 PaCO2 >45 mmHg，多导睡眠监测示夜间低通气","key":"减重 + 夜间无创正压通气（BPAP），停用镇静剂，随访日间血气与右心并发症"}],"diseases":[{"id":"resp_tb_pleurisy","name":"结核性胸膜炎","aka":["Tuberculous pleurisy","结核性渗出性胸膜炎"],"rank":1,"basic":{"define":"结核分枝杆菌直接侵犯胸膜（或胸膜下干酪样病灶破入胸腔）引起的胸腔积液，属肺外结核；在结核流行区是渗出性胸腔积液最常见的原因。","risk":["与活动性肺结核患者密切接触或结核高流行区居住","HIV 感染（胸水 ADA 可偏低）","长期激素、TNF-α 抑制剂或器官移植后免疫抑制","糖尿病、矽肺、慢性肾病与营养不良","年轻成人（20–40 岁）最常见，老年人比例上升"],"epi":"我国结核性胸膜炎约占肺外结核的 20%–30%；胸水结核培养阳性率仅 20%–30%，临床依靠 ADA 等指标综合诊断。规范治疗后多数吸收，但约 20%–50% 遗留胸膜增厚。"},"patho":"结核蛋白抗原刺激胸膜产生迟发型变态反应，毛细血管通透性增加，淋巴细胞与纤维蛋白大量渗出形成高蛋白渗出液；胸膜下干酪灶破溃可使胸水呈脓性（结核性脓胸）。后期纤维蛋白沉积机化致胸膜粘连增厚，严重者形成纤维板束缚肺组织。","dx":{"criteria":["起病缓慢，低热、盗汗、乏力、消瘦、咳嗽与胸膜性胸痛，积液增多后转为胸闷与呼吸困难。","体检：患侧呼吸动度减弱、叩诊浊音、语颤与呼吸音减弱，积液上方偶闻管状呼吸音。","影像：单侧（>90%）少量至中量积液，肋膈角变钝或大片致密影；CT 见光滑或厚壁强化胸膜、胸膜下结节与对侧肺内结核灶。","超声：积液伴胸膜条索、分隔与增厚，提示结核。","胸水为渗出液（Light 标准），白细胞以淋巴细胞为主（>50%），间皮细胞 <5%，葡萄糖下降、LDH 升高。","胸水腺苷脱氨酶（ADA）>40 U/L 且高于血清高度支持，结合临床灵敏度与特异性约 85%–90%，>70 U/L 更倾向结核。","病原：胸水抗酸染色、结核培养（20%–30%）、Xpert MTB/RIF 核酸（约 50%）；胸膜活检联合培养与病理可提高至 70%–90%。","IGRA 或 PPD 阳性支持感染，不能单独确诊。"],"workup":["胸部增强 CT：评估胸膜厚度、结节、肺内病灶与纵隔淋巴结","胸腔超声定位并诊断性穿刺，首次抽液 ≤600–700 mL","胸水常规、生化、ADA、LDH、细菌与结核培养、核酸及脱落细胞学（排除恶性）","胸膜活检（超声或 CT 引导，或胸膜腔镜）用于诊断困难者","CRP、肝肾功能、电解质与 IGRA","HIV 筛查与其他免疫抑制评估"],"grading":"按病程分急性与慢性；按渗液性质分单纯渗出性、包裹性、结核性脓胸与胸膜纤维板；按积液量分层。"},"ddx":[{"name":"慢性肺源性心脏病（右心衰积液）","point":"与本类中慢性肺源性心脏病的鉴别点：肺心病并发胸水多双侧、以右侧为主，伴颈静脉怒张、肝大与下肢水肿，BNP 升高，胸水为漏出液或轻度渗出液；结核性胸膜炎为单侧渗出液、淋巴细胞为主、ADA >40 U/L，伴结核中毒症状。"},{"name":"肺炎旁胸腔积液","point":"急性发热、脓痰与实变影，胸水中性粒细胞为主，ADA 不高，抗感染后迅速吸收。"},{"name":"恶性胸腔积液","point":"年龄偏大、消瘦，积液量大且反复迅速增长，ADA 常 <40 U/L，脱落细胞学与肿瘤标志物阳性，CT 见胸膜结节。"},{"name":"类风湿或系统性红斑狼疮胸膜炎","point":"伴关节痛、皮疹等系统表现，胸水葡萄糖极低（类风湿），自身抗体阳性。"},{"name":"心力衰竭胸腔积液","point":"漏出液、多双侧，心脏增大、BNP 升高，利尿有效。"}],"tx":{"drug":[{"name":"异烟肼","dose":"300 mg 口服 qd（5 mg/kg/d，最大 300 mg/d），空腹顿服","note":"四联核心药物；治疗前后监测肝酶，出现四肢麻木加维生素 B6","renal":"严重肾衰可减量，透析后补充","hepatic":"活动性肝病慎用，监测 ALT","interact":"与利福平、吡嗪酰胺合用增加肝毒性"},{"name":"利福平","dose":"≥50 kg：450–600 mg 口服 qd 空腹；<50 kg 遵说明书","note":"尿汗呈橘红色为正常现象，需告知患者","renal":"无需调整","hepatic":"严重肝病减量或避用","interact":"强 CYP 诱导剂，降低口服避孕药、华法林、他汀及部分抗病毒药疗效"},{"name":"吡嗪酰胺","dose":"≥50 kg：1.5 g 口服 qd；<50 kg：1.0–1.25 g","note":"强化期使用 2 个月；可致高尿酸血症与肝毒性","renal":"CrCl <30 mL/min 减量或延长间隔","hepatic":"严重肝病慎用","interact":"与别嘌醇合用降尿酸效果下降"},{"name":"乙胺丁醇","dose":"15–25 mg/kg/d 口服 qd（常规 0.75–1.0 g/d）","note":"主要不良反应为球后视神经炎，治疗前后定期查视力与色觉","renal":"按 CrCl 调整或延长间隔","hepatic":"无需调整","interact":"与氨基糖苷类合用增加神经毒性"},{"name":"泼尼松（辅助）","dose":"0.5 mg/kg/d 口服，2–4 周后逐渐减量，总疗程 4–8 周","note":"用于大量积液吸收慢、中毒症状重或播散性结核，可减少胸膜增厚；须在有效抗结核基础上使用并排除糖尿病、溃疡","renal":"无需调整","hepatic":"无需调整","interact":"与利福平合用激素代谢加快；与非甾体抗炎药合用增加消化道出血"},{"name":"莫西沙星（替代/耐药方案）","dose":"0.4 g 口服 qd","note":"四联中如有禁忌可在结核专科指导下替代乙胺丁醇；耐药结核按耐药方案","renal":"无需调整","hepatic":"Child-Pugh C 慎用","interact":"延长 QT；与含铝镁抗酸剂间隔 2 小时"}],"nonDrug":["初治方案 2HRZE/4HR（总 6 个月）；2 个月后积液未吸收或胸膜增厚明显可延长至 9 个月","胸腔穿刺抽液：首次 ≤600–700 mL，之后每次 1000–1500 mL，每周 1–2 次，尽早清除减少纤维化","包裹性或黏稠脓性积液行置管引流或胸腔镜清理","遗留纤维板致限制性通气障碍者考虑胸膜剥脱术","强化期每 2–4 周监测肝功能、视力与尿酸","密切接触者筛查与规范隔离管理"],"life":["规律全程服药，不得自行停药减量，避免耐药","加强营养，戒烟限酒，控制血糖","疗程结束后 3、6、12 个月复查胸片与肺功能","出现黄疸、视力下降或四肢麻木及时就医"]},"prog":"规范治疗 6 个月后积液多 2–4 个月吸收，多数无后遗症；约 20%–50% 遗留胸膜增厚，部分出现限制性通气障碍。结核性脓胸与就诊延迟者预后较差，需外科评估。耐药者疗程长、复发风险高。","refs":["《中国结核病防治工作技术指南》（2021 版）","中华医学会结核病学分会《结核病诊断和治疗指南》（2017）","《中国原发性胸腔积液诊断和治疗专家共识》（2022）"]},{"id":"resp_cor_pulmonale","name":"慢性肺源性心脏病","aka":["Chronic cor pulmonale","肺心病"],"rank":2,"basic":{"define":"由支气管-肺组织、胸廓或肺血管病变导致肺血管阻力增加与肺动脉高压，继而引起右心室肥厚、扩张或右心衰的心脏病，最常见于 COPD。","risk":["COPD（占 80% 以上），尤其重度与反复急性加重者","支气管扩张、重度肺结核后遗毁损、间质性肺病","胸廓畸形、脊柱后凸、睡眠呼吸暂停与肥胖低通气","慢性血栓栓塞性疾病与其他肺血管病","长期吸烟、高原缺氧环境","反复呼吸道感染与长期低氧高碳酸血症"],"epi":"我国 40 岁以上人群 COPD 患病率约 13.7%，相当比例并发肺心病；急性加重期病死率约 8%–15%，合并右心衰与严重低氧者更高。"},"patho":"慢性缺氧与高碳酸血症引起肺小动脉痉挛，继而平滑肌增生、内膜纤维化与微血栓形成，肺血管阻力持续升高形成肺动脉高压；压力负荷使右室肥厚扩张，最终右心衰。高碳酸血症与酸中毒进一步收缩肺血管、减低心肌收缩力，与气道分泌物潴留共同形成呼吸衰竭与右心衰相互加重的恶性循环。","dx":{"criteria":["存在 COPD、间质性肺病、胸廓畸形或肺血管病等基础病，有长期咳嗽气短与反复呼吸衰竭史。","胸片示心尖上翘、肺动脉段突出、右下肺动脉干扩张 ≥15 mm；心电图示肺型 P 波（≥0.25 mV）、电轴右偏、右室高电压与 V1–V3 rS 型。","超声心动图估测 PASP >30 mmHg（三尖瓣反流速度 >2.8 m/s），右室扩大、室间隔平直或左室呈 D 形；右心导管为金标准（mPAP >20 mmHg）。","右心衰体征：颈静脉怒张、肝颈静脉回流征阳性、肝大压痛、下肢凹陷性水肿与腹水；BNP/NT-proBNP 升高但幅度常低于左心衰。","血气示 PaO2 <60 mmHg、PaCO2 >50 mmHg，可有代偿性红细胞增多；肺功能示阻塞性通气障碍。","超声与 BNP 排除左心疾病，必要时右心导管区分肺病相关与其他类型肺动脉高压。"],"workup":["超声心动图估算 PASP 与右心大小（首选无创）","胸片与心电图，急性加重期与基线对比","动脉血气、血常规与电解质","肺功能与 DLCO，必要时 6 分钟步行试验","右心导管（诊断不确定、拟用靶向药或评估移植时）","BNP/NT-proBNP、肝肾功能与凝血","怀疑 OSAHS 或肥胖低通气者做夜间血氧与多导睡眠监测"],"grading":"分代偿期（肺动脉高压无右心衰）与失代偿期（急性加重伴右心衰）；按 WHO 功能分级 Ⅰ–Ⅳ 评估症状；急性加重期分以呼吸衰竭为主与以右心衰为主，常并存。"},"ddx":[{"name":"结核性胸膜炎","point":"与本类中结核性胸膜炎的鉴别点：结核性胸膜炎为单侧渗出性胸水、ADA >40 U/L，无颈静脉怒张与肝大，BNP 正常；肺心病右心衰积液多为双侧，伴右心衰体征与 BNP 升高。"},{"name":"呼吸调节异常与肥胖低通气","point":"与本类中肥胖低通气的鉴别点：后者以肥胖、日间嗜睡与夜间低通气为特征，早期无右心结构改变，减重与无创通气后 PaCO2 可改善；肺心病有结构性肺病基础并已出现右心改变。"},{"name":"左心衰竭","point":"端坐呼吸、夜间阵发性呼吸困难、双肺底湿啰音，BNP 升高明显，超声见左室增大与 EF 下降。"},{"name":"动脉性肺动脉高压","point":"无常见肺病基础，女性多见，PASP 显著升高而肺功能基本正常，需右心导管确诊并考虑靶向治疗。"},{"name":"缩窄性心包炎","point":"右心衰体征但超声见心包增厚、室间隔抖动，肺功能多正常。"}],"tx":{"drug":[{"name":"噻托溴铵（基础病治疗）","dose":"18 µg 吸入 qd；或 LABA/LAMA 联合按肺功能分级选择","note":"规范吸入治疗减少急性加重；重视装置使用训练与依从性","renal":"吸入全身吸收少，一般无需调整","hepatic":"遵说明书","interact":"与其他抗胆碱能药合用时尿潴留与青光眼风险增加"},{"name":"呋塞米","dose":"20–40 mg 口服 qd 起始；急性期 20–40 mg 静推 q12–24h，按需加量","note":"减轻前负荷与水肿，目标体重每日下降 0.5–1 kg；肺心病对利尿剂敏感，过度利尿可致低血压、痰液黏稠与代谢性碱中毒、加重高碳酸血症","renal":"肾功能不全需加量，监测电解质","hepatic":"无需调整","interact":"与氨基糖苷类合用增加耳毒性；致低钾可诱发地高辛中毒"},{"name":"螺内酯","dose":"20 mg 口服 qd","note":"保钾利尿，与呋塞米联用减少钾丢失；注意高钾与肾功能","renal":"CrCl <30 mL/min 慎用","hepatic":"肝功能不全慎用","interact":"与 ACEI/ARB 合用高钾风险；升高地高辛浓度"},{"name":"地高辛","dose":"0.125 mg 口服 qd（老年与肾功能不全 0.0625–0.125 mg qd），血药浓度 0.5–0.9 ng/mL","note":"仅用于合并房颤控制心室率或伴左心功能不全，不改善肺心病预后；低氧与低钾时易中毒","renal":"按 CrCl 减量并监测浓度","hepatic":"无需调整","interact":"与胺碘酮、维拉帕米、克拉霉素合用升高浓度"},{"name":"抗感染（急性加重期）","dose":"阿莫西林/克拉维酸 625 mg 口服 tid，或头孢曲松 1–2 g 静滴 qd；有铜绿假单胞菌风险者哌拉西林/他唑巴坦 4.5 g q8h","note":"急性加重最常见诱因为呼吸道感染，留取痰培养后尽早经验治疗，5–7 天复评","renal":"按 CrCl 调整","hepatic":"按药物调整","interact":"参见肺炎章节"}],"nonDrug":["长期家庭氧疗：PaO2 ≤55 mmHg 或 ≤59 mmHg 伴红细胞增多/右心衰，每日 ≥15 小时，流量 1–2 L/min 使 PaO2 ≥60 mmHg","急性加重期控制性氧疗（SpO2 88%–92%），pH <7.35 且 PaCO2 >45–50 mmHg 时首选无创通气，必要时有创通气","避免过度利尿：按体重、尿量、血压与电解质动态调整，出现低血压或痰液黏稠时减量","纠正低钾低氯与代谢性碱中毒，保持痰液稀薄","肺动脉高压靶向药仅在第 3 组重度病例经右心导管确认后由专科评估，不常规使用","终末期患者评估肺移植；戒烟与疫苗接种"],"life":["戒烟，避免粉尘与冷空气刺激，家庭氧疗按时使用","低盐饮食（<5 g/d），每日固定时间称重监测水肿","肺康复：缩唇呼吸、腹式呼吸与力量训练","每 3–6 个月随访肺功能、血气、超声与 BNP","痰量增多、气促加重或下肢水肿时及时就医"]},"prog":"病程长且反复急性加重，5 年生存率约 50%–70%；急性加重期病死率 8%–15%，合并严重高碳酸血症、休克与重度右心衰者更高。长期氧疗、肺康复与戒烟可改善生存；肺动脉压持续升高者需评估移植。","refs":["中华医学会呼吸病学分会《慢性肺源性心脏病诊断和治疗指南（2018 年版）》","《慢性阻塞性肺疾病诊治指南（2021 年修订版）》","《中国肺动脉高压诊断和治疗指南》（2021）"]},{"id":"resp_hypoventilation","name":"呼吸调节异常与肥胖低通气","aka":["Obesity hypoventilation syndrome","OHS","肥胖低通气综合征","肺泡低通气"],"rank":3,"basic":{"define":"以肺泡通气不足导致慢性高碳酸血症为特征的一组疾病，包括中枢性呼吸调节异常、呼吸肌无力与胸廓畸形，以及最常见的肥胖低通气综合征（OHS）：BMI ≥30 kg/m² 且清醒时 PaCO2 >45 mmHg 并排除其他原因；多数合并阻塞性睡眠呼吸暂停（OSAHS）。","risk":["BMI ≥30 kg/m²（≥40 时风险显著增加）","合并 OSAHS：打鼾、目击呼吸暂停、夜间频繁觉醒","颈围增大、口咽部狭窄、甲状腺功能减退","镇静催眠药、阿片类或酒精滥用（抑制通气驱动）","神经肌肉疾病：肌萎缩侧索硬化、重症肌无力、脊髓损伤","胸廓畸形：脊柱后凸侧弯、强直性脊柱炎"],"epi":"OHS 在肥胖成人中患病率约 8%–20%（重度肥胖可达 30%）；我国 OSAHS 患者中约 10%–20% 合并 OHS。未治疗者 5 年病死率可超过 20%，规范无创通气可明显改善预后。"},"patho":"肥胖使胸腹脂肪负荷与腹内压增加，胸肺顺应性下降、呼吸做功增加；瘦素抵抗与中枢化学感受器对 CO2 敏感性降低使呼吸驱动不足，形成慢性高碳酸血症与呼吸性酸中毒，肾脏代偿性重吸收碳酸氢盐（代谢性碱中毒）又进一步抑制通气驱动。长期夜间低通气致肺动脉高压、右心衰与红细胞增多，日间嗜睡影响认知与驾驶安全。","dx":{"criteria":["成年人 BMI ≥30 kg/m²，清醒且非急性加重期 PaCO2 >45 mmHg。","排除其他肺泡低通气原因：重度 COPD、间质性肺病、胸廓畸形、神经肌肉疾病、药物与甲状腺功能减退。","临床线索：日间嗜睡（Epworth 评分 >10）、晨起头痛、乏力、夜尿增多、睡眠不解乏、打鼾与目击呼吸暂停。","夜间低通气：多导睡眠监测示呼气末 CO2 >45 mmHg 或经皮 CO2 升高 >10 mmHg，血氧 <90% 累计 >5 分钟。","神经肌肉病变者 FVC <60% 预计值或仰卧位较坐位下降 >20%；先天性中枢性低通气综合征夜间反复呼吸暂停而缺乏呼吸肌努力。","血气典型组合：PaCO2 与 HCO3⁻（>27 mmol/L）升高、PaO2 下降，pH 正常或轻度酸中毒。"],"workup":["清醒坐位与仰卧位动脉血气、血常规（红细胞增多）","多导睡眠监测（含气流、呼吸努力、血氧与 CO2 监测）","肺功能与最大吸气压、呼气压（评估限制性通气与呼吸肌力）","甲状腺功能、肝肾功能与电解质","超声心动图与 BNP（评估右心扩大与肺动脉高压）","怀疑神经肌肉或胸廓病因时行肌电图、胸廓影像与专科评估"],"grading":"OHS 分级按 PaCO2：轻度 45–<50 mmHg、中度 50–<55 mmHg、重度 ≥55 mmHg 或伴 pH <7.30；按是否合并 OSAHS 分单纯 OHS 与混合型。呼吸调节异常按病因分中枢性、神经肌肉性与胸廓性。"},"ddx":[{"name":"慢性肺源性心脏病","point":"与本类中慢性肺源性心脏病的鉴别点：肺心病有 COPD 等结构性肺病基础、肺功能为阻塞性通气障碍，右心改变不能单用肥胖解释；OHS 早期肺部结构正常，以肥胖、嗜睡与高碳酸血症为主，减重与无创通气可显著改善。"},{"name":"结核性胸膜炎","point":"与本类中结核性胸膜炎的鉴别点：结核性胸膜炎表现为单侧渗出性积液伴发热盗汗，ADA >40 U/L，不引起慢性清醒期高碳酸血症。"},{"name":"单纯 OSAHS","point":"单纯 OSAHS 日间 PaCO2 正常；一旦清醒时 PaCO2 >45 mmHg 即考虑 OHS，治疗需同时纠正夜间低通气。"},{"name":"甲状腺功能减退","point":"嗜睡、体重增加与呼吸肌无力，TSH 与 FT4 异常，补充甲状腺素后多改善。"},{"name":"神经肌肉疾病","point":"伴肢体无力、吞咽困难与 FVC 显著下降，需肌电图与神经专科评估。"}],"tx":{"drug":[{"name":"乙酰唑胺","dose":"125–250 mg 口服 bid 起始，按耐受性与电解质调整","note":"利尿性碳酸酐酶抑制剂，可改善中枢通气敏感性并纠正代谢性碱中毒，须联合无创通气，不宜单用；注意低钾、肾结石与肢体感觉异常","renal":"肾结石与重度肾衰慎用","hepatic":"肝功能不全慎用","interact":"与阿司匹林合用增加中枢神经毒性；降低锂排泄"},{"name":"茶碱缓释片","dose":"0.1–0.2 g 口服 bid，按血药浓度 5–10 µg/mL 调整，遵说明书","note":"仅作为部分中枢性或神经肌肉性低通气辅助，疗效有限；OHS 不推荐常规使用","renal":"肾功能不全监测浓度","hepatic":"肝功能不全减量","interact":"与西咪替丁、环丙沙星合用升高浓度；与利福平、吸烟降低浓度"},{"name":"甲羟孕酮（女性选择性使用）","dose":"5–10 mg 口服 qd，遵说明书个体化","note":"孕激素刺激中枢呼吸驱动，用于部分女性 OHS 或无创通气耐受差者，需专科评估，注意血栓与体重增加","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与利福平合用减效；增加血栓风险"},{"name":"减重药物（遵医嘱）","dose":"按说明书适应证选择（如 GLP-1 受体激动剂），配合营养与生活方式干预","note":"仅限符合减重适应证者，不作为 OHS 首选单独治疗","renal":"按药物说明","hepatic":"按药物说明","interact":"与降糖药合用注意低血糖"}],"nonDrug":["夜间无创通气为首选：以 BPAP 为主，必要时较高压力保证有效通气，每晚 ≥4–6 小时可改善日间 PaCO2、睡眠与生存；以 OSAHS 为主者可用 CPAP，日间 PaCO2 不降则改 BPAP","减重：饮食控制与运动，减重 5%–10% 即可改善通气；重度肥胖考虑减重手术","避免镇静催眠药、阿片类与酒精，停用致体重增加的药物","合并低氧或肺心病者配合长期氧疗，肺康复训练","神经肌肉疾病者加用咳嗽辅助设备与气道清理","治疗前避免驾驶，Epworth 评分显著升高者做交通安全评估"],"life":["规律使用无创通气，每 3–6 个月检查依从性与漏气量","持续减重与营养指导，每 3 个月复查体重与 BMI","随访日间血气、肺功能与超声心动图","随身携带无创通气参数卡，就诊时告知医生","家人了解夜间呼吸暂停与低氧的识别与急救"]},"prog":"未治疗的 OHS 5 年病死率 20%–30%，主要死于心脑血管事件与呼吸衰竭；规律无创通气配合减重可于数周内改善日间高碳酸血症，长期生存显著改善。减重手术可使多数患者脱离无创通气。先天性中枢性低通气综合征需终身夜间通气与家庭监护。","refs":["中华医学会呼吸病学分会《阻塞性睡眠呼吸暂停低通气综合征诊治指南》（2015 年）","《肥胖低通气综合征诊治专家共识》（2021）","ATS《肥胖低通气综合征评估与管理临床实践指南》（2019）"]}]},{"id":"pneu_atypical","name":"非典型病原体肺炎","rank":41,"summary":"非典型病原体（衣原体、军团菌等）为胞内寄生或细胞壁缺陷，β-内酰胺类天然无效；诊断依赖核酸、尿抗原与血清学，治疗以四环素类、大环内酯类、喹诺酮类为主，须按年龄、妊娠状态与肝肾功能选药。","compare":[{"diseaseId":"resp_chlamydia","dx":"亚急性干咳、声嘶、低热，肺部体征轻而影像有浸润，肺炎衣原体 PCR 或 MIF 血清学阳性；鹦鹉热有禽类接触史与高热、剧烈头痛","key":"β-内酰胺类无效；成人首选多西环素，孕妇与 8 岁以下儿童选阿奇霉素"},{"diseaseId":"resp_legionella","dx":"高热、相对缓脉、腹泻、意识改变伴低钠血症（血钠 <130 mmol/L），尿抗原或呼吸道 PCR 阳性","key":"病情凶险且 β-内酰胺类无效；首选喹诺酮或阿奇霉素，重症疗程 14–21 天"}],"diseases":[{"id":"resp_chlamydia","name":"衣原体肺炎","aka":["Chlamydia pneumoniae Pneumonia","Psittacosis","鹦鹉热","肺炎衣原体肺炎"],"rank":1,"basic":{"define":"由肺炎衣原体（Chlamydia pneumoniae）或鹦鹉热衣原体（Chlamydia psittaci）引起的急性呼吸道感染。两者均为专性胞内寄生、细胞壁缺陷，β-内酰胺类不能穿透细胞膜且无靶点，故治疗须选四环素类、大环内酯类或喹诺酮类。","risk":["学龄儿童、青年及集体生活人群（学校、军营、宿舍）——肺炎衣原体","禽类接触：鹦鹉、鸽子、火鸡、鸭、鸡及活禽市场、养殖场、禽类加工——鹦鹉热","吸烟与慢性心肺疾病","免疫功能低下、HIV 感染、长期糖皮质激素","职业暴露：兽医、屠宰、皮毛加工、禽类运输"],"epi":"肺炎衣原体约占成人社区获得性肺炎（CAP）的 5%–15%，儿童与青年中比例更高，每 4–7 年可出现一次流行高峰。鹦鹉热为动物源性散发，我国多见于有观赏鸟或活禽接触者，人际传播罕见。"},"patho":"含病原体的气溶胶吸入后，原体黏附于呼吸道上皮，被巨噬细胞吞噬并在胞内形成包涵体繁殖，逃避溶酶体融合；细胞免疫（Th1/IFN-γ）决定清除。肺炎衣原体感染后可诱发气道高反应与哮喘加重。鹦鹉热可经血行播散至肝、脾、心内膜与中枢神经系统，产生全身毒血症状与多器官受累。","dx":{"criteria":["临床：肺炎衣原体多为亚急性起病，咽痛、声嘶、干咳持续 5 天以上，低至中度发热（多 <39°C），肺部听诊常无湿啰音，症状与体征、影像不平行。","鹦鹉热：禽类接触后潜伏 5–14 天（最长 21 天）出现高热 39–40°C、剧烈头痛、干咳、相对缓脉，可伴肝脾大与 Horder 斑。","影像：单侧下叶斑片状浸润或间质改变，胸腔积液少见（<10%）；鹦鹉热可呈大叶实变，重症快速进展为双肺弥漫渗出。","实验室：白细胞多正常或轻度升高（<12×10⁹/L），ESR 增快，CRP 轻中度升高；鹦鹉热常有 ALT >2×ULN、低钠血症。","病原：急性期痰、支气管肺泡灌洗液（BALF）或鼻咽拭子肺炎衣原体 PCR 阳性；或微量免疫荧光（MIF）IgM ≥1:16、IgG 双份血清 ≥4 倍升高、单次 IgG ≥1:512。","鹦鹉热：BALF 或痰特异性 PCR、mNGS 阳性；培养需 BSL-3 实验室，不作常规。补体结合试验 ≥1:32 或双份血清 4 倍升高仅作回顾诊断。","治疗反应：规范 β-内酰胺类治疗 72 小时无效、痰普通培养阴性、炎症指标不高，应主动考虑本病。","重症标准：PaO2/FiO2 <300、呼吸频率 >30 次/分、多叶浸润或需机械通气；鹦鹉热可快速进展为 ARDS。"],"workup":["鼻咽拭子、痰或 BALF 多重 PCR（肺炎衣原体、支原体、军团菌、呼吸道病毒）","血清 MIF 双份（间隔 2–4 周）；鹦鹉热用微量免疫荧光或补体结合试验","胸部 CT：浸润分布、实变范围、有无胸腔积液与空洞","血常规、CRP、肝肾功能、电解质（低钠提示鹦鹉热或军团菌）","重症者查血气、BALF mNGS，并送细菌、真菌、分枝杆菌培养排除混合感染","详细追问禽类、职业与旅行接触史（最易漏问的环节）"],"grading":"无统一分型。按病情分轻症（CURB-65 0–1 分、可口服、SpO2 ≥92%）与重症（PaO2/FiO2 <300 或需氧疗、机械通气）；鹦鹉热按有无 ARDS 及多器官受累分层。CAP 严重度用 CURB-65 或 PSI。"},"ddx":[{"name":"军团菌肺炎（resp_legionella）","point":"与本类中军团菌肺炎的鉴别点：两者均为胞内病原、β-内酰胺类无效、均可有低钠与肝酶升高；军团菌起病更急、高热 >39°C、腹泻与意识改变突出、尿抗原（血清型 1）阳性，衣原体则以声嘶、亚急性干咳为主，尿抗原阴性。"},{"name":"肺炎支原体肺炎（resp_mycoplasma）","point":"儿童与青年多见，干咳、咽痛、耳痛，可伴皮疹与溶血性贫血；支原体 IgM 或 PCR 阳性。与衣原体肺炎临床几乎无法区分，需病原学；大环内酯耐药时改用多西环素或喹诺酮。"},{"name":"病毒性肺炎（resp_viral_pneumonia）","point":"流感起病更急，高热、肌痛、白细胞减少，流感抗原或核酸阳性；影像双肺间质改变相似，但病毒性肺炎少有肝酶显著升高与禽类接触史。"},{"name":"肺炎链球菌肺炎（resp_pneumococcus）","point":"急起寒战高热、铁锈色痰、大叶实变，白细胞 >15×10⁹/L，尿抗原阳性，对 β-内酰胺类敏感；衣原体肺炎白细胞多正常。"},{"name":"肺结核（resp_tb）","point":"病程 >2 周、盗汗消瘦，上叶尖后段空洞或树芽征，痰抗酸染色或结核核酸阳性；衣原体肺炎无空洞与树芽征。"},{"name":"Q 热（Coxiella burnetii 感染）","point":"牛羊接触史，高热、头痛、肝酶显著升高，可伴血小板减少；血清学或 PCR 确诊。多西环素同样有效，但 Q 热更易出现心内膜炎，需超声心动图评估。"},{"name":"肺栓塞","point":"突发呼吸困难、胸痛、低氧，D-二聚体升高，CTPA 见充盈缺损；无发热与感染背景，抗感染治疗无效。"}],"tx":{"drug":[{"name":"多西环素（成人首选）","dose":"100 mg 口服或静滴 q12h；肺炎衣原体疗程 7–14 天，鹦鹉热 10–14 天，重症首剂静滴","note":"鹦鹉热首选药物，退热后仍需继续 7–10 天以防复发；8 岁以下儿童一般禁用（牙齿着色），8 岁以上按 2.2 mg/kg q12h（单次 ≤100 mg）","renal":"无需调整（主要经胆汁排泄）","hepatic":"严重肝功能不全者慎用或减量","interact":"含铝镁抗酸剂、铁剂、钙剂降低吸收，需间隔 2 小时；增强华法林作用；与异维A酸合用可致颅内压升高"},{"name":"阿奇霉素","dose":"成人 500 mg 口服或静滴 qd × 3 天（或首日 500 mg、第 2–5 天 250 mg qd）；儿童首日 10 mg/kg（≤500 mg），之后 5 mg/kg qd（≤250 mg），共 3–5 天","note":"孕妇与 8 岁以下儿童首选；鹦鹉热重症可静脉给药，热退后改口服序贯","renal":"无需调整","hepatic":"肝功能不全者慎用，出现肝酶显著升高或黄疸应停药","interact":"含铝镁抗酸剂降低峰浓度；与胺碘酮、喹诺酮、西沙必利合用延长 QT；为 CYP3A4 抑制剂，可升高他汀、环孢素浓度"},{"name":"左氧氟沙星","dose":"500 mg 口服或静滴 qd × 7–14 天（或 750 mg qd × 5 天）","note":"成人替代方案；18 岁以下与孕妇禁用；注意肌腱炎、肌腱断裂与 QT 延长","renal":"CrCl 20–49 mL/min：首剂 500 mg 后 250 mg qd；CrCl <20 mL/min：250 mg q48h","hepatic":"无需调整","interact":"增强华法林抗凝；与糖皮质激素合用增加肌腱断裂风险；抗酸剂、铁剂降低吸收"},{"name":"莫西沙星","dose":"400 mg 口服或静滴 qd × 10 天","note":"肺组织浓度高，可覆盖非典型病原；肝功能不全者慎用，QT 延长者避免","renal":"无需调整","hepatic":"Child-Pugh C 级禁用或慎用","interact":"与胺碘酮、索他洛尔等 QT 延长药禁用；增强华法林作用"},{"name":"红霉素（替代，耐受性差）","dose":"成人 500 mg 口服 qid；儿童 30–50 mg/kg/d 分 4 次","note":"胃肠道反应与静脉炎明显，仅用于不能耐受其他大环内酯者；孕妇可用但优先阿奇霉素","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"强效 CYP3A4 抑制剂，与他汀、秋水仙碱、胺碘酮合用风险高；延长 QT"}],"nonDrug":["门诊治疗指征：CURB-65 0–1 分、能口服、SpO2 ≥92% 且无快速进展影像；否则住院","氧疗目标 SpO2 92%–96%（合并 COPD 者 88%–92%）","鹦鹉热重症合并 ARDS：肺保护性通气（潮气量 6 mL/kg 预计体重）、必要时俯卧位","禽类暴露管理：隔离病禽，清理禽粪时戴 N95 口罩与手套；高危暴露者可多西环素 100 mg bid × 7 天预防（需评估）","学校、军营等集体单位出现聚集病例时报告疾控并筛查密切接触者","避免单用 β-内酰胺类经验性治疗非典型病原体肺炎"],"life":["足疗程用药，鹦鹉热退热后仍需 7–10 天，擅自停药复发率可达 20%","戒烟、避免受凉；哮喘或 COPD 患者感染后 4–8 周复查肺功能","接触禽类后立即洗手，不购买来源不明活禽，职业人群做好防护","2–4 周复查胸部影像，吸收延迟超过 6 周需排除结核与肿瘤"]},"prog":"肺炎衣原体肺炎多为自限性，规范治疗 7–14 天症状缓解，病死率 <1%。鹦鹉热未经治疗病死率可达 10%–20%，规范四环素类治疗后降至 <1%，但合并 ARDS 者仍可达 5%–10%。老年、免疫抑制与延误治疗者预后较差。","refs":["中华医学会呼吸病学分会《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","国家卫生健康委员会《中国儿童社区获得性肺炎诊疗规范（2019 年版）》","IDSA/ATS《Diagnosis and Treatment of Adults with Community-acquired Pneumonia》（2019）","《内科学》第 9 版（呼吸系统 肺炎）"]},{"id":"resp_legionella","name":"军团菌肺炎","aka":["Legionnaires Disease","Legionella Pneumonia","军团病","嗜肺军团菌肺炎"],"rank":2,"basic":{"define":"由嗜肺军团菌（Legionella pneumophila）等革兰阴性胞内杆菌引起的急性肺部感染。临床分军团病（肺炎型）与庞蒂亚克热（Pontiac fever，无肺炎、自限性流感样综合征）。","risk":["空调冷却塔、热水系统、淋浴喷头、喷泉、加湿器气溶胶暴露","男性、年龄 >50 岁、吸烟、酗酒","糖尿病、慢性心肺疾病、慢性肾功能不全","免疫抑制：器官移植、泼尼松 ≥20 mg/d、TNF-α 抑制剂、HIV 感染","近期旅行或住院（院内暴发多见于 ICU、移植病房）"],"epi":"军团菌占成人 CAP 的 2%–8%，重症 CAP 中可达 10%–15%。我国以夏秋季散发为主，院内暴发多与冷却塔、热水系统污染相关。未治疗病死率 15%–20%，规范治疗降至 5%–10%。"},"patho":"含菌气溶胶（直径 1–5 µm）吸入肺泡后被巨噬细胞吞噬，细菌抑制吞噬体-溶酶体融合并在胞内大量繁殖，裂解细胞后释放，引起急性坏死性肺炎与大量中性粒细胞渗出。细菌可经血行播散至肝、脾、肾、脑。β-内酰胺类不能穿透细胞膜，且军团菌产 β-内酰胺酶，故天然耐药。","dx":{"criteria":["临床三联：高热 ≥39°C、干咳、相对缓脉（体温高而心率不相应增快），伴乏力、肌痛、头痛。","肺外线索：腹泻或恶心呕吐（30%–50%）、意识改变或谵妄、低钠血症（血钠 <130 mmol/L，约 50%）、肝酶升高、CK 升高、蛋白尿或血尿。","影像：早期斑片浸润，迅速进展为大叶实变（下叶多见），可伴空洞与胸腔积液（约 30%）；影像进展常快于症状。","尿抗原：仅检测嗜肺军团菌血清型 1，发病 3 天后阳性，敏感性 70%–80%、特异性 >95%，可持续数周至数月；阴性不能排除其他血清型或菌种。","呼吸道标本（痰、BALF）PCR 或 mNGS 阳性；BCYE 培养基培养 3–7 天出菌，为金标准但敏感性仅 30%–70%。","双份血清抗体 ≥4 倍升高（间隔 3–6 周）仅作回顾性诊断，不能指导早期治疗。","经验性线索：CAP 患者出现低钠 + 腹泻 + 意识改变，且 β-内酰胺类治疗 72 小时无效，应立即覆盖军团菌。","重症标准：CURB-65 ≥3 分、PaO2/FiO2 <300、需机械通气或多器官受累。"],"workup":["尿军团菌抗原（所有重症 CAP 应常规送检）","痰或 BALF 军团菌 PCR 加 BCYE 培养；疑难病例送 mNGS","血气、血钠、肝肾功能、CK、CRP 与降钙素原","胸部 CT：实变范围、空洞、胸腔积液与有无跨叶播散","环境调查：冷却塔、热水系统、喷泉采样（由疾控协助）","血培养与痰普通培养排除其他病原（军团菌血培养阳性率低）"],"grading":"分军团病（有肺炎）与庞蒂亚克热（无肺炎，2–5 天自限）。按 CAP 严重度用 CURB-65 或 PSI 分层；重症定义见上。社区获得病例中血清型 1 占 80%–90%，院内暴发可见其他血清型与菌种。"},"ddx":[{"name":"衣原体肺炎（resp_chlamydia）","point":"与本类中衣原体肺炎的鉴别点：两者均对 β-内酰胺类无效、均可有低钠与肝酶升高；军团菌起病更急、体温更高、腹泻与意识改变突出，尿抗原阳性；衣原体以声嘶、亚急性干咳为主，尿抗原阴性。"},{"name":"肺炎支原体肺炎（resp_mycoplasma）","point":"青年、干咳、咽痛、耳痛，可伴皮疹与溶血性贫血；低钠与腹泻少见，大环内酯治疗有效；支原体 IgM 或 PCR 阳性。"},{"name":"病毒性肺炎（resp_viral_pneumonia）","point":"流感或新冠起病急，高热、肌痛、淋巴细胞减少，双肺磨玻璃影，核酸阳性；合并细菌感染时降钙素原明显升高。"},{"name":"肺炎链球菌肺炎（resp_pneumococcus）","point":"急起寒战高热、铁锈色痰，白细胞 >15×10⁹/L，大叶实变，尿抗原阳性，对 β-内酰胺类敏感；无低钠与腹泻组合。"},{"name":"肺炎克雷伯菌肺炎（resp_klebsiella）","point":"酗酒或糖尿病者，上叶实变、砖红色胶冻痰、叶间裂膨出；痰培养阳性，β-内酰胺类有效。"},{"name":"肺结核（resp_tb）","point":"亚急性或慢性病程、盗汗消瘦，上叶空洞与树芽征，抗酸染色或结核核酸阳性；军团菌病程以天计。"},{"name":"Q 热","point":"牛羊接触史，高热、头痛、肝酶显著升高，可伴血小板减少；血清学或 PCR 确诊；多西环素有效，但低钠与腹泻不如军团菌突出。"}],"tx":{"drug":[{"name":"左氧氟沙星（首选）","dose":"750 mg 静滴或口服 qd，疗程 7–14 天；免疫抑制或重症 14–21 天","note":"起病 24–48 小时内给药可显著降低病死率；避免单药用于未排除结核者","renal":"CrCl 20–49 mL/min：750 mg q48h；CrCl 10–19 mL/min：首剂 750 mg 后 500 mg q48h","hepatic":"无需调整","interact":"增强华法林；与糖皮质激素合用增加肌腱断裂；抗酸剂、铁剂降低吸收；延长 QT"},{"name":"莫西沙星","dose":"400 mg 静滴或口服 qd，疗程 7–14 天","note":"肺组织浓度高，覆盖军团菌；注意神经精神反应与 QT 延长","renal":"无需调整","hepatic":"严重肝功能不全（Child-Pugh C）禁用","interact":"与胺碘酮、索他洛尔合用禁用；增强华法林作用"},{"name":"阿奇霉素","dose":"500 mg 静滴 qd，病情稳定后改口服，总疗程 7–10 天；重症可静脉 3–5 天后序贯","note":"孕妇与儿童可用；克拉霉素 500 mg bid 为替代","renal":"无需调整","hepatic":"肝功能不全者慎用，监测肝酶","interact":"延长 QT；CYP3A4 抑制剂，升高他汀、环孢素浓度"},{"name":"克拉霉素","dose":"500 mg 口服 bid × 10–14 天","note":"大环内酯替代；CYP3A4 强抑制剂，注意他汀与秋水仙碱毒性","renal":"CrCl <30 mL/min 减半","hepatic":"肝功能不全者慎用","interact":"与辛伐他汀、洛伐他汀禁用；与胺碘酮延长 QT；增强华法林"},{"name":"多西环素（轻中度替代）","dose":"100 mg 口服 bid × 10–14 天","note":"用于轻中度或不耐受喹诺酮者；重症证据不足，不作为首选","renal":"无需调整","hepatic":"严重肝功能不全者慎用","interact":"抗酸剂、铁剂降低吸收；增强华法林"}],"nonDrug":["重症监护与器官支持：ARDS 肺保护性通气、CRRT、血管活性药物","低钠纠正：仅症状性低钠用 3% 高渗盐水，24 小时血钠升幅 ≤8–10 mmol/L，避免渗透性脱髓鞘","中大量胸腔积液行胸腔穿刺或闭式引流","环境干预：清洗消毒冷却塔与热水系统，ICU、移植病房定期监测水系统","不推荐常规糖皮质激素，除非合并 ARDS 或感染性休克按相应指南使用","庞蒂亚克热仅需对症治疗，不需抗菌药物"],"life":["出院后 2–4 周复查影像与肾功能（喹诺酮相关）","戒烟、控制血糖；糖尿病患者感染后易重症","家庭与单位水系统定期清洗，长期不用水龙头先放水 1–2 分钟","免疫抑制者出现发热应尽早查尿军团菌抗原"]},"prog":"规范治疗病死率 5%–10%，重症或免疫抑制者 25%–50%；延误有效治疗超过 48 小时病死率明显升高。存活者影像吸收需 8–12 周，少数遗留纤维化。庞蒂亚克热 2–5 天自愈，无死亡。","refs":["中华医学会呼吸病学分会《中国成人社区获得性肺炎诊断和治疗指南（2016 年版）》","中华医学会呼吸病学分会《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南（2018 年版）》","IDSA/ATS《Diagnosis and Treatment of Adults with Community-acquired Pneumonia》（2019）","《内科学》第 9 版（呼吸系统 肺炎）"]}]},{"id":"pneu_special","name":"特殊宿主与真菌肺炎","rank":42,"summary":"特殊宿主肺炎的病原谱由免疫缺陷类型与持续时间决定，诊断须把宿主因素、影像模式与微生物学证据结合；痰培养念珠菌多为定植，PCP 依赖 BALF 与 G 试验，寄生虫病则靠流行病学史与嗜酸性粒细胞增多提示。治疗强调按体重给足剂量、覆盖与降阶梯并重。","compare":[{"diseaseId":"resp_candida","dx":"粒缺、长期广谱抗生素或中心静脉导管患者发热不退，痰培养念珠菌阳性但无诊断价值，需肺组织病理或无菌下呼吸道标本培养证实","key":"痰培养阳性多为定植，不得据此用药；确诊靠组织侵袭证据，首选氟康唑或棘白菌素"},{"diseaseId":"resp_pcp","dx":"HIV CD4 <200/µL 或长期激素者亚急性干咳、活动后气促，双肺磨玻璃影，LDH 与 β-D-葡聚糖升高，BALF 六胺银或 PCR 阳性","key":"SMZ-TMP 按体重给药 21 天；PaO2 <70 mmHg 或 A-a >35 mmHg 必须加激素"},{"diseaseId":"resp_immunodef_pneu","dx":"中性粒细胞缺乏、移植后或长期激素患者新发肺部浸润，病原谱广，HRCT 模式结合血培养、BALF、GM/G 试验与病毒核酸判断","key":"粒缺伴发热 1 小时内经验性抗假单胞菌治疗，4–7 天不退加抗真菌，明确病原后降阶梯"},{"diseaseId":"resp_parasitic","dx":"疫区居住、疫水或犬接触、生食淡水蟹史，伴嗜酸性粒细胞 >500/µL，影像见脓肿、囊性灶或肺动脉高压","key":"肺包虫严禁穿刺；阿苯达唑 10–15 mg/kg/d 围手术期使用，肺阿米巴用甲硝唑后须清除包囊"}],"diseases":[{"id":"resp_candida","name":"肺念珠菌病","aka":["Pulmonary Candidiasis","念珠菌肺炎","侵袭性肺念珠菌病"],"rank":1,"basic":{"define":"由念珠菌属（以白念珠菌为主）侵入肺实质引起的感染，绝大多数发生于严重免疫抑制、长期广谱抗生素或中心静脉导管留置患者。痰或气道分泌物培养念珠菌阳性通常代表定植，不能作为诊断依据。","risk":["持续中性粒细胞缺乏（ANC <500/µL 超过 7 天）","ICU 长期广谱抗生素、机械通气超过 7 天","中心静脉导管、全胃肠外营养","腹部大手术、消化道穿孔、反复腹腔感染","糖尿病、慢性肾功能不全或透析","长期糖皮质激素（泼尼松 ≥20 mg/d 超过 3 周）、器官移植"],"epi":"肺念珠菌病占侵袭性念珠菌病的 5% 以下，尸检确诊者多伴全身播散。ICU 患者气道念珠菌定植率 20%–50%，痰培养阳性对肺念珠菌病的阳性预测值不足 10%，故不能据痰培养诊断或启动治疗。"},"patho":"念珠菌为口咽与消化道常驻菌，微吸入是主要感染途径。菌体黏附受损气道上皮后形成假菌丝侵入组织；中性粒细胞与肺泡巨噬细胞是主要防御，粒缺、广谱抗生素导致菌群失调、黏膜屏障破坏时侵袭风险显著升高。血行播散（念珠菌血症）可经肺毛细血管形成肺内多发微脓肿，此时肺病变是全身感染的一部分。","dx":{"criteria":["宿主因素：中性粒细胞缺乏 ≥10 天、长期广谱抗生素、中心静脉导管、腹部大手术、长期激素或器官移植等至少 1 项。","临床：广谱抗生素治疗 4–7 天仍发热不退，伴咳嗽、咳白黏痰，肺部体征无特异性。","影像：新出现支气管肺炎、斑片实变、结节或空洞，无特征性，不能仅凭影像诊断。","痰或气道分泌物培养念珠菌阳性不能诊断（定植）；需无菌下呼吸道标本（BALF、防污染毛刷、肺组织）培养阳性并伴组织侵袭证据。","组织病理为金标准：肺组织见酵母细胞与假菌丝侵入肺实质，伴中性粒细胞浸润。","血培养念珠菌阳性伴肺部新发浸润，提示血行播散至肺，按念珠菌血症处理。","β-D-葡聚糖（G 试验）>80 pg/mL 支持侵袭性真菌感染，但特异性低；阴性预测值高，可用于排除。","需排除细菌性肺炎、侵袭性肺曲霉病、肺孢子菌肺炎、病毒性肺炎与肺水肿。"],"workup":["血培养（双侧双瓶，需氧加厌氧）、BALF 真菌涂片、培养与药敏","血清 G 试验、GM 试验（鉴别曲霉）、隐球菌荚膜抗原","胸部 CT：实变、结节、空洞及有无播散灶","腹部超声或 CT：排查肝脾脓肿（慢性播散性念珠菌病）","眼底检查：念珠菌眼内炎","拔除或更换中心静脉导管并送导管尖端培养"],"grading":"按感染途径分原发性（吸入性）与继发性（血行播散）；按诊断级别分确诊（组织病理或无菌部位培养阳性）、临床诊断（宿主因素加影像加 G 试验）、拟诊。慢性播散性念珠菌病（肝脾念珠菌病）需延长疗程。"},"ddx":[{"name":"肺孢子菌肺炎（resp_pcp）","point":"与本类中 PCP 的鉴别点：PCP 多见于 CD4 <200/µL 或长期激素者，双肺磨玻璃影，LDH 与 G 试验升高，BALF 六胺银染色或 PCR 阳性；念珠菌肺炎影像无特征，需 BALF 培养加组织假菌丝证据，两者可合并。"},{"name":"侵袭性肺曲霉病","point":"粒缺患者出现结节伴晕轮征、空气新月征，GM 试验阳性，病理见分隔菌丝；念珠菌无此类影像与抗原特征。"},{"name":"医院获得性细菌性肺炎（HAP/VAP）","point":"气管插管、脓性痰、痰培养革兰阴性杆菌，抗菌治疗有效；念珠菌定植常与细菌感染并存，不能以念珠菌解释全部病情。"},{"name":"肺隐球菌病","point":"孤立或多发结节，隐球菌荚膜抗原阳性，病理见厚荚膜酵母；念珠菌荚膜抗原阴性。"},{"name":"病毒性肺炎（CMV/HSV）","point":"移植后 30–100 天，双肺磨玻璃影或小结节，病毒核酸阳性；G 试验可假阳性，需病毒载量确诊。"},{"name":"肺水肿或 ARDS","point":"双肺弥漫渗出、BNP 或 NT-proBNP 升高、对利尿有效，无感染与定植证据。"},{"name":"肺结核","point":"慢性病程、上叶空洞、抗酸染色或结核核酸阳性；念珠菌病患者长期激素可合并结核，需同步排查。"}],"tx":{"drug":[{"name":"氟康唑","dose":"首剂 800 mg（12 mg/kg）口服或静滴，之后 400 mg（6 mg/kg）qd；疗程一般 2–4 周，免疫抑制者至影像吸收","note":"白念珠菌首选；光滑念珠菌耐药率高、克柔念珠菌天然耐药，用药前须送药敏","renal":"CrCl ≤50 mL/min 维持量减半（200 mg qd）","hepatic":"Child-Pugh B/C 级慎用，监测肝酶","interact":"CYP2C9/3A4 抑制剂，升高华法林、苯妥英、磺脲类与他汀浓度；与胺碘酮合用延长 QT"},{"name":"卡泊芬净","dose":"首日 70 mg 静滴，之后 50 mg qd；重症可 70 mg qd","note":"棘白菌素类，对唑类耐药菌有效；对隐球菌与毛霉无效","renal":"无需调整","hepatic":"Child-Pugh B 级减至 35 mg qd，C 级慎用","interact":"与环孢素合用肝毒性增加；利福平降低其血药浓度"},{"name":"米卡芬净","dose":"100 mg 静滴 qd（重症 150 mg qd）","note":"念珠菌血症与肺念珠菌病的替代选择；耐受性较好","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"与西罗莫司、伊曲康唑合用可升高后者浓度"},{"name":"两性霉素 B 脂质体","dose":"3–5 mg/kg 静滴 qd","note":"用于重症、耐药或中枢受累；监测肌酐、血钾与血镁","renal":"肾毒性明显，CrCl 下降时减量或换药","hepatic":"遵说明书","interact":"与其他肾毒性药物叠加；可加重低钾"},{"name":"伏立康唑（备选）","dose":"负荷 6 mg/kg 静滴 q12h × 2 次，维持 4 mg/kg q12h；口服 200 mg q12h","note":"非肺念珠菌病首选，用于白念珠菌且氟康唑不耐受者；建议治疗药物监测谷浓度 1–5.5 mg/L","renal":"CrCl <50 mL/min 改用口服","hepatic":"Child-Pugh B 级维持量减半，C 级慎用","interact":"CYP2C19/3A4 抑制剂与底物，禁与他汀、胺碘酮合用；利福平显著降低其浓度"}],"nonDrug":["拔除或更换中心静脉导管，是导管相关念珠菌感染的关键措施","控制血糖（目标 8–10 mmol/L），减少不必要的广谱抗生素","恢复中性粒细胞（G-CSF）、尽量减少激素与免疫抑制剂","感染源控制：脓肿引流、坏死组织清创","不推荐对 ICU 发热患者常规经验性抗真菌，仅用于高危且培养或 G 试验支持者","慢性播散性念珠菌病需延长疗程并反复影像评估肝脾病灶"],"life":["长期免疫抑制者加强口腔护理，减少口咽念珠菌定植","控制血糖，避免长期留置中心静脉导管","疗程内每 1–2 周复查肝肾功能与血常规","出现视力下降或眼痛需立即排查念珠菌眼内炎","出院后 4 周复查胸部 CT 评估吸收"]},"prog":"念珠菌血症病死率 30%–40%，合并感染性休克可达 50%；原发性肺念珠菌病罕见，但重症患者病死率高。早期拔除导管、及时有效抗真菌与免疫恢复是改善预后的关键；光滑念珠菌与克柔念珠菌耐药者预后较差。","refs":["中国成人念珠菌病诊断与治疗专家共识（2020 年版）","中华医学会器官移植学分会《中国实体器官移植受者侵袭性真菌病临床诊疗规范（2019 年版）》","IDSA《Clinical Practice Guideline for the Management of Candidiasis》（2016）","中华医学会呼吸病学分会《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南（2018 年版）》"]},{"id":"resp_pcp","name":"肺孢子菌肺炎","aka":["Pneumocystis Pneumonia","PCP","PJP","耶氏肺孢子菌肺炎"],"rank":2,"basic":{"define":"由耶氏肺孢子菌（Pneumocystis jirovecii）引起的机遇性真菌性肺炎，是 HIV 感染者 CD4 <200/µL 及长期免疫抑制患者最常见的致死性机会性感染之一。","risk":["HIV 感染 CD4 <200/µL 且未接受预防","长期糖皮质激素：泼尼松 ≥20 mg/d 或等效剂量超过 4 周","实体器官移植（尤其肺、肾）与造血干细胞移植","血液系统恶性肿瘤、化疗、利妥昔单抗或抗 TNF-α 生物制剂","自身免疫病（ANCA 相关血管炎、SLE）接受强化免疫抑制","营养不良、早产儿与原发性免疫缺陷"],"epi":"HIV 未预防者 CD4 <200/µL 时 1 年发病率 20%–30%。随着抗反转录病毒治疗（ART）普及，非 HIV 免疫抑制患者占比上升；我国非 HIV 相关 PCP 病死率 30%–50%，显著高于 HIV 合并者（10%–20%）。"},"patho":"肺孢子菌黏附于肺泡 I 型上皮细胞，引起肺泡内泡沫状渗出、肺泡-毛细血管弥散障碍与表面活性物质异常，导致低氧血症与弥散功能下降，肺泡间隔淋巴细胞浸润。免疫重建（ART 启动过快）可诱发免疫重建炎症综合征（IRIS），使低氧短期加重。","dx":{"criteria":["临床：亚急性起病，干咳、活动后气促、发热，症状持续 3–7 天至数周；听诊常无湿啰音，体征与低氧程度不平行。","血气：PaO2 <70 mmHg 或肺泡-动脉氧分压差（A-a DO2）>35 mmHg 提示重症，为激素指征；静息 SpO2 <90% 或活动后下降 ≥5% 提示显著气体交换障碍。","影像：HRCT 双肺弥漫磨玻璃影（地图样或蝶翼样），可伴小叶间隔增厚、薄壁肺气囊（约 10% 病例）与气胸；X 线早期可正常。","实验室：LDH 升高（>500 U/L 提示，敏感性高、特异性低）；β-D-葡聚糖 >80 pg/mL（敏感性约 90%，阴性预测值高）；HIV 者 CD4 <200/µL。","病原：诱导痰或 BALF 六胺银或吉姆萨染色见囊体与滋养体；BALF PCR 敏感性 >95%、特异性 90%–95%；血清 PCR 不推荐。","组织病理：肺组织见泡沫状肺泡渗出与银染阳性囊体，为金标准但少用。","排除：细菌性肺炎、病毒性肺炎（尤其 CMV）、肺水肿、肺泡出血、间质性肺病急性加重。","非 HIV 者诊断更难：BALF 阴性而临床高度怀疑时，可结合 G 试验与 PCR 结果经验性治疗并动态评估。"],"workup":["呼吸室内空气的血气分析与 A-a 氧梯度计算","胸部 HRCT（薄层），评估磨玻璃、肺气囊与气胸","LDH、β-D-葡聚糖、血常规与 CD4 计数（HIV）","诱导痰（3% 高渗盐水雾化）或 BALF 染色加 PCR","BALF 细菌、真菌、分枝杆菌培养，CMV/HSV PCR 与 mNGS","HIV 抗体、免疫抑制药物史与移植史梳理"],"grading":"按宿主分 HIV 相关与非 HIV 相关（后者起病更急、病死率更高）；按氧合分轻度（PaO2 ≥70 mmHg）与重症（PaO2 <70 mmHg 或 A-a DO2 >35 mmHg，需加激素）；影像分磨玻璃型、囊性/气胸型与实变型。"},"ddx":[{"name":"肺念珠菌病（resp_candida）","point":"与本类中肺念珠菌病的鉴别点：两者均见于免疫抑制宿主且 G 试验可升高；PCP 影像为弥漫磨玻璃、LDH 显著升高、BALF 六胺银或 PCR 阳性；念珠菌肺炎需组织假菌丝证据，痰培养阳性多为定植。"},{"name":"侵袭性肺曲霉病","point":"粒缺或移植后，结节伴晕轮征、空气新月征，GM 试验阳性，病理见分隔菌丝；PCP 为弥漫磨玻璃且 GM 阴性。"},{"name":"CMV 肺炎","point":"移植后 30–100 天或 HIV 晚期，双肺磨玻璃或小结节，CMV DNA 载量升高，BALF 检出病毒；常与 PCP 合并，需同时检测。"},{"name":"病毒性肺炎（流感、RSV、新冠）","point":"急性起病、高热肌痛、淋巴细胞减少，核酸阳性；磨玻璃影相似，但 PCP 病程更隐匿、LDH 更高。"},{"name":"间质性肺病急性加重","point":"已知 ILD 背景，HRCT 在原有纤维化基础上出现新磨玻璃影，抗感染无效，需激素冲击；BALF 无肺孢子菌。"},{"name":"肺水肿","point":"心衰史、BNP 或 NT-proBNP 升高、双侧胸腔积液，对利尿有效；无发热与 G 试验升高。"},{"name":"弥漫性肺泡出血","point":"咯血、血红蛋白下降，BALF 呈血性且逐管加深，含铁血黄素巨噬细胞阳性；PCP 气胸型需与此鉴别。"},{"name":"粟粒性肺结核","point":"弥漫粟粒结节而非磨玻璃，抗酸染色或结核核酸阳性，常伴肝脾受累；HIV 晚期可同时存在。"}],"tx":{"drug":[{"name":"复方磺胺甲噁唑（SMZ-TMP，一线）","dose":"TMP 15–20 mg/kg/d 加 SMZ 75–100 mg/kg/d，分 3–4 次口服或静滴（60 kg 者约 2 片 160/800 mg q8h）；HIV 疗程 21 天，非 HIV 14 天","note":"首剂可给负荷量；监测血钾、肌酐、血常规与皮疹；HIV 者应在治疗 2 周内启动 ART，但需警惕 IRIS","renal":"CrCl 15–30 mL/min 减量 50%；CrCl <15 mL/min 避免使用或按血药浓度个体化；透析后补一剂","hepatic":"肝功能不全者慎用，监测肝酶","interact":"增强华法林；与 ACEI、ARB、保钾利尿剂合用致高钾；与苯妥英、甲氨蝶呤、磺脲类相互作用"},{"name":"泼尼松（重症辅助）","dose":"40 mg 口服 bid × 5 天，继 40 mg qd × 5 天，再 20 mg qd × 11 天（HIV 21 天方案）；非 HIV 可用 1 mg/kg/d 后渐减","note":"指征为 PaO2 <70 mmHg 或 A-a DO2 >35 mmHg；应在抗 PCP 治疗开始后 24–72 小时内加用；监测血糖与继发感染","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"CYP3A4 诱导；与喹诺酮合用增加肌腱断裂；与非甾体抗炎药合用增加消化道出血"},{"name":"克林霉素 + 伯氨喹（磺胺过敏替代）","dose":"克林霉素 600 mg 静滴 q8h（或 450 mg 口服 q6h）加伯氨喹 30 mg（基质）口服 qd，疗程 21 天","note":"用药前必须查 G6PD，缺乏者禁用（致命性溶血）；伯氨喹可致高铁血红蛋白血症","renal":"克林霉素无需调整；伯氨喹肾功能不全者慎用","hepatic":"两者均需慎用并监测肝酶","interact":"伯氨喹与奎宁、甲氟喹合用增加 QT 与血液毒性；克林霉素与神经肌肉阻滞剂合用加重肌无力"},{"name":"喷他脒（替代）","dose":"4 mg/kg 静滴 qd，溶于 5% 葡萄糖，输注不少于 60 分钟，疗程 14–21 天","note":"肾毒性、低血糖或高血糖、QT 延长与低血压；仅用于磺胺不耐受且无其他选择者","renal":"CrCl <30 mL/min 减量或隔日，密切监测肌酐","hepatic":"肝功能不全者慎用","interact":"与其他肾毒性药、QT 延长药叠加"},{"name":"阿托伐醌（轻中度）","dose":"750 mg 口服 bid，随餐，疗程 21 天","note":"生物利用度个体差异大，重症不推荐单药；腹泻常见","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"利福平降低其浓度；抗酸剂降低吸收"},{"name":"卡泊芬净（挽救或联合）","dose":"首日 70 mg，之后 50 mg qd，联合克林霉素或 SMZ-TMP","note":"对囊体有效、对滋养体无效，仅作联合或挽救治疗，不单用","renal":"无需调整","hepatic":"Child-Pugh B 级减至 35 mg qd","interact":"与环孢素合用肝毒性增加"}],"nonDrug":["氧疗目标 SpO2 90%–95%；PaO2 <60 mmHg 或呼吸窘迫用经鼻高流量或无创通气，失败者及时气管插管","保守液体管理，避免加重肺水肿与低氧","呼吸道隔离：PCP 可人际传播，免疫抑制患者集中收治时应单间或负压病房","气胸处理：胸腔闭式引流，复发性气胸可行胸膜固定","HIV 者尽早启动 ART，但需监测 IRIS；非 HIV 者在感染控制后逐步减停免疫抑制剂","预防：HIV CD4 <200/µL 或口腔念珠菌病者用 SMZ-TMP 160/800 mg qd 或每周 3 次，CD4 >200/µL 持续 3 个月可停"],"life":["移植后 6–12 个月及长期激素者按指南预防 PCP","出院后 2–4 周复查血气与胸部 CT，评估氧合与吸收","HIV 者每 3 个月复查 CD4 与病毒载量，坚持 ART","避免与 PCP 患者密切接触，移植受者少去人群密集场所","戒烟、营养支持，接种流感与肺炎链球菌疫苗"]},"prog":"HIV 合并 PCP 规范治疗病死率 10%–20%，非 HIV 者 30%–50%；需机械通气者病死率超过 50%。气胸、低氧持续超过 1 周、LDH >1000 U/L、合并 CMV 感染为不良预后因素。存活者肺功能多在 3–6 个月恢复，部分遗留弥散功能下降。","refs":["中华医学会感染病学分会艾滋病丙型肝炎学组《中国艾滋病诊疗指南（2021 年版）》","中华医学会呼吸病学分会《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南（2018 年版）》","NIH/CDC/HIVMA《Guidelines for the Prevention and Treatment of Opportunistic Infections in Adults and Adolescents with HIV》（2024）","《内科学》第 9 版（呼吸系统 肺真菌病）"]},{"id":"resp_immunodef_pneu","name":"免疫缺陷者肺炎","aka":["Pneumonia in the Immunocompromised Host","免疫抑制宿主肺炎","粒缺伴肺炎"],"rank":3,"basic":{"define":"免疫功能受损宿主（中性粒细胞缺乏、造血干细胞或实体器官移植、长期激素或免疫抑制剂、血液系统恶性肿瘤、HIV）发生的肺炎。病原谱广、起病隐匿、进展快，常为细菌、真菌、病毒与分枝杆菌的混合感染。","risk":["中性粒细胞缺乏（ANC <500/µL）或预计 48 小时内降至 <500/µL","造血干细胞移植（尤其异基因、合并 GVHD）与实体器官移植（肺、肾、肝）","长期糖皮质激素（泼尼松 ≥20 mg/d 超过 4 周）或其他免疫抑制剂、生物制剂","血液系统恶性肿瘤、化疗后骨髓抑制","HIV 感染 CD4 <200/µL","结构性肺病、糖尿病、营养不良、ICU 长期留置导管与机械通气"],"epi":"中性粒细胞缺乏伴发热患者中约 10%–50% 可找到明确感染灶，肺炎占 20%–30%。粒缺合并肺炎病死率 20%–40%，需机械通气者超过 60%。移植后 1 年内肺炎发生率 15%–30%，病原随移植后时间呈特征性分布。"},"patho":"中性粒细胞与 T 细胞免疫受损使胞外菌、胞内菌、真菌与病毒清除均下降；移植后与骨髓瘤患者调理素缺乏，易感荚膜菌。镇静、插管与 GVHD 破坏咳嗽反射和黏液纤毛清除。免疫抑制强度与持续时间决定病原谱；炎症反应弱使影像与症状滞后于感染进展，常在出现明显低氧时才被发现。","dx":{"criteria":["宿主判定：ANC <500/µL，或移植后、泼尼松 ≥20 mg/d 超过 4 周、接受化疗或生物制剂、HIV CD4 <200/µL。","粒缺伴发热定义：单次口温 ≥38.3°C 或 ≥38.0°C 持续 1 小时，且 ANC <500/µL 或预计 48 小时内降至 <500/µL，需在 1 小时内启动经验性抗菌治疗。","影像：HRCT 为首选；结节伴晕轮征提示曲霉，双肺磨玻璃提示 PCP 或 CMV，反晕轮征提示毛霉，实变提示细菌。","病原学：双侧双瓶血培养、痰或 BALF 细菌真菌培养、GM 与 G 试验、CMV/EBV/HSV PCR、PCP PCR、mNGS。","时间轴推断：HSCT 后 <30 天以细菌与念珠菌为主；30–100 天以 CMV、PCP、曲霉为主；>100 天以社区病原、荚膜菌与迟发 CMV 为主。","严重度：PaO2/FiO2 <300、需血管活性药、多叶受累或 ANC <100/µL 持续超过 10 天为高危。","排除非感染性病因：药物性肺损伤、放射性肺炎、GVHD 相关肺病、肺水肿、弥漫性肺泡出血（BALF 逐管血性）。"],"workup":["胸部 HRCT（薄层），不以胸片作为筛查手段","血培养 2 套、CRP 与降钙素原、G 试验与 GM 试验","痰与 BALF 涂片培养（细菌、真菌、分枝杆菌）、PCP 染色与 PCR、CMV DNA、mNGS","鼻咽拭子呼吸道病毒多重 PCR","免疫状态评估：CD4/CD8、IgG、中性粒细胞绝对计数、移植类型与 GVHD 分级","必要时经支气管或外科肺活检，术前评估血小板与出血风险"],"grading":"按宿主类型与粒缺持续时间分层：低危（预期粒缺 <7 天、无合并症）与高危（预期 >7 天、血流动力学不稳、肺炎、黏膜炎）。肺炎按 CURB-65 或 PSI 与氧合分级；移植后按时间轴分期。"},"ddx":[{"name":"肺孢子菌肺炎（resp_pcp）","point":"与本类中 PCP 的鉴别点：PCP 多见于 CD4 <200/µL 或长期激素者，双肺磨玻璃影、LDH 与 G 试验升高、BALF 六胺银或 PCR 阳性；免疫缺陷者肺炎病原更杂，需同时排除细菌与曲霉。"},{"name":"肺念珠菌病（resp_candida）","point":"痰培养念珠菌多为定植，确诊需组织病理或无菌下呼吸道标本培养；不能以痰培养阳性解释粒缺患者的肺部浸润。"},{"name":"侵袭性肺曲霉病","point":"粒缺超过 10 天，结节伴晕轮征或空气新月征，GM 试验阳性；进展迅速，需尽早抗真菌，不能等待培养。"},{"name":"CMV 肺炎","point":"移植后 30–100 天，双肺磨玻璃或小结节，CMV DNA 载量升高，BALF 检出病毒；需更昔洛韦治疗。"},{"name":"医院获得性细菌性肺炎（HAP/VAP）","point":"气管插管、脓性痰、革兰阴性杆菌培养阳性，降钙素原升高；经验性抗假单胞菌治疗有效。"},{"name":"肺结核与非结核分枝杆菌肺病","point":"移植后或长期激素者影像不典型，可呈结节、实变或粟粒样；抗酸染色、结核核酸与分枝杆菌培养阳性。"},{"name":"弥漫性肺泡出血","point":"咯血、血红蛋白下降，BALF 血性且逐管加深，含铁血黄素巨噬细胞阳性；常见于移植后或血管炎。"},{"name":"药物性肺损伤或放射性肺炎","point":"有明确用药或放疗史，影像与照射野一致，停用可疑药物或激素治疗后改善，病原学阴性。"}],"tx":{"drug":[{"name":"哌拉西林-他唑巴坦（经验性一线）","dose":"4.5 g 静滴 q6h，延长输注 3–4 小时；CrCl 20–40 mL/min 减至 3.375 g q6h，CrCl <20 mL/min 减至 2.25 g q6h","note":"覆盖铜绿假单胞菌与肠杆菌目；粒缺伴发热应在 1 小时内给药","renal":"按上述 CrCl 分层调整","hepatic":"无需调整","interact":"与甲氨蝶呤合用增加毒性；与丙磺舒合用升高浓度；可致低钾"},{"name":"头孢吡肟（替代）","dose":"2 g 静滴 q8h；CrCl 30–60 mL/min 2 g q12h，CrCl 11–29 mL/min 2 g q24h，CrCl <11 mL/min 1 g q24h","note":"第四代头孢，覆盖铜绿假单胞菌；癫痫史者慎用","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"与氨基糖苷类肾毒性叠加；用药期间避免饮酒（双硫仑样反应）"},{"name":"美罗培南","dose":"1 g 静滴 q8h，延长输注 3 小时；CrCl 26–50 mL/min 1 g q12h，CrCl 10–25 mL/min 500 mg q12h","note":"产 ESBL 肠杆菌或重症首选碳青霉烯；癫痫史者慎用","renal":"按 CrCl 调整","hepatic":"无需调整","interact":"显著降低丙戊酸血药浓度（禁止合用）"},{"name":"万古霉素","dose":"15–20 mg/kg 静滴 q8–12h，目标 AUC/MIC 400–600（或谷浓度 15–20 mg/L）","note":"用于 MRSA 定植、血流动力学不稳、黏膜炎或导管相关感染；48–72 小时评估是否降阶梯","renal":"CrCl 50–90 mL/min 15 mg/kg q12h；CrCl 20–49 mL/min q24h；CrCl <20 mL/min 按血药浓度个体化","hepatic":"无需调整","interact":"与哌拉西林-他唑巴坦合用增加急性肾损伤；与氨基糖苷类、两性霉素 B 肾毒性叠加"},{"name":"卡泊芬净（经验性抗真菌）","dose":"首日 70 mg，之后 50 mg qd；持续粒缺发热 4–7 天不退时加用","note":"替代方案为脂质体两性霉素 B 3 mg/kg qd 或伏立康唑 6/4 mg/kg；根据 GM 试验与 CT 调整","renal":"无需调整","hepatic":"Child-Pugh B 级减至 35 mg qd","interact":"与环孢素合用肝毒性增加；利福平降低浓度"},{"name":"更昔洛韦（CMV 肺炎）","dose":"5 mg/kg 静滴 q12h × 14–21 天，之后按维持量；或缬更昔洛韦 900 mg 口服 bid","note":"监测中性粒细胞与血小板；CMV 肺炎可联合静脉免疫球蛋白","renal":"CrCl 50–69 mL/min 2.5 mg/kg q12h；CrCl 25–49 mL/min 2.5 mg/kg q24h；CrCl <25 mL/min 1.25 mg/kg q24h","hepatic":"无需调整","interact":"与齐多夫定、霉酚酸酯等骨髓抑制药叠加"},{"name":"复方磺胺甲噁唑（覆盖 PCP）","dose":"治疗：TMP 15–20 mg/kg/d 分 3–4 次；预防：160/800 mg qd","note":"按体重给足量，勿按固定片数；监测血钾与肌酐","renal":"CrCl 15–30 mL/min 减量 50%，<15 mL/min 避免使用","hepatic":"肝功能不全者慎用","interact":"增强华法林；与 ACEI、ARB、保钾利尿剂合用致高钾"},{"name":"重组人粒细胞集落刺激因子（G-CSF）","dose":"5 µg/kg 皮下注射 qd，至 ANC >1.0×10⁹/L","note":"用于高危粒缺伴发热或预期粒缺超过 7 天者；不推荐所有粒缺患者常规使用","renal":"无需调整","hepatic":"无需调整","interact":"与化疗同期使用需间隔 24–48 小时"}],"nonDrug":["粒缺伴发热 1 小时内经验性抗菌；4–7 天不退且粒缺持续者复查 CT 并加抗真菌","降阶梯：明确病原后缩窄方案；无病原、稳定 48–72 小时且 ANC >500/µL 可停万古霉素","感染源控制：拔除感染导管、引流脓肿、清创坏死组织","减少免疫抑制、恢复中性粒细胞；严重低丙种球蛋白者补充 IVIG","呼吸支持：经鼻高流量或无创通气，避免延迟插管","保护性隔离：HEPA 或层流病房、手卫生、避免鲜花与施工粉尘"],"life":["移植后 6–12 个月预防 PCP，CMV 每周监测 DNA 至移植后 100 天","避免接触宠物排泄物、霉变环境与呼吸道感染者","按时间表接种灭活疫苗（流感、肺炎链球菌），免疫抑制期间避免活疫苗","发热立即就诊，不自行服退热药掩盖体温","长期激素者不可骤停，需按计划渐减"]},"prog":"粒缺合并肺炎病死率 20%–40%，需机械通气者超过 60%；中性粒细胞恢复时间是最关键预后因素。移植后肺炎合并 GVHD、耐药革兰阴性杆菌或曲霉感染者预后差。早期经验性治疗与及时降阶梯可减少耐药与药物毒性。","refs":["中国中性粒细胞缺乏伴发热患者抗菌药物临床应用指南（2020 年版）","中华医学会呼吸病学分会《中国成人医院获得性肺炎与呼吸机相关性肺炎诊断和治疗指南（2018 年版）》","中华医学会器官移植学分会《中国实体器官移植受者侵袭性真菌病临床诊疗规范（2019 年版）》","IDSA《Clinical Practice Guideline for the Use of Antimicrobial Agents in Neutropenic Patients with Cancer》（2010）"]},{"id":"resp_parasitic","name":"肺寄生虫病","aka":["Pulmonary Parasitosis","肺阿米巴病","肺血吸虫病","肺包虫病","肺吸虫病"],"rank":4,"basic":{"define":"寄生虫感染累及肺部的疾病总称。临床常见三类：肺阿米巴病（溶组织内阿米巴肝脓肿穿破膈肌入肺）、肺血吸虫病（虫卵栓塞肺小动脉致肉芽肿与肺动脉高压）、肺包虫病（细粒棘球绦虫幼虫形成肺囊肿）；肺吸虫病亦为我国常见类型。","risk":["肺阿米巴：热带与亚热带疫区、卫生条件差、男性、酗酒、肝脓肿史","肺血吸虫：疫水接触（长江流域湖沼区）、渔民与农民、夏秋季作业","肺包虫：牧区（新疆、青海、西藏、内蒙古、甘肃）、犬接触、皮毛加工","肺吸虫：生食或半生食淡水蟹、蝲蛄","免疫抑制并非主要危险因素，与机会性感染不同"],"epi":"我国包虫病流行于西部牧区，肺包虫占囊型包虫病的 10%–25%。血吸虫病主要分布于长江流域及以南 12 个省，肺受累多见于急性期与慢性肺动脉高压。肺阿米巴多继发于肝脓肿，约 10%–20% 的肝脓肿可穿破膈肌累及肺或胸腔。"},"patho":"阿米巴滋养体经门静脉入肝形成脓肿，直接穿破膈肌进入肺或胸腔，形成巧克力色坏死性脓肿或脓胸。血吸虫尾蚴入血后童虫经肺（急性期短暂肺炎），成虫寄居门脉系统，虫卵经侧支循环入肺栓塞肺小动脉，引起肉芽肿性闭塞与肺动脉高压。包虫虫卵在十二指肠孵化，六钩蚴穿肠壁入血，滞留肺毛细血管后缓慢长成囊（每年约 1–5 cm），囊壁分内外囊，破裂可致过敏反应与播散。","dx":{"criteria":["流行病学：疫区居住或旅行、疫水接触、犬与牛羊接触、生食淡水蟹或生肉史；无此线索极易漏诊。","嗜酸性粒细胞增多：外周血嗜酸性粒细胞 >500/µL 或 >8%（急性血吸虫、肺吸虫、包虫破裂时明显；阿米巴可不升高）。","肺阿米巴：肝脓肿病史加右下胸痛、咳巧克力色痰，影像见右膈下脓肿与右下肺脓肿或胸腔积液相通；阿米巴抗体（IHA/ELISA）阳性；痰或胸液可查见滋养体（阳性率低）。","肺血吸虫：急性期发热、干咳、荨麻疹、肝大；慢性期活动后气促、肺动脉高压（超声估测肺动脉收缩压 >40 mmHg）、右心扩大；粪或尿虫卵、直肠黏膜活检阳性，血清抗体阳性。","肺包虫：影像见单发或多发圆形、边界清楚囊性病灶（直径 1–20 cm），囊壁钙化、水上浮莲征（内囊破裂）或新月征；ELISA 或免疫印迹阳性（敏感性 80%–95%）；严禁经皮穿刺。","肺吸虫：生蟹或蝲蛄史、游走性皮下结节、铁锈色痰、嗜酸性粒细胞显著升高；痰或粪查虫卵，血清抗体阳性。","影像：阿米巴为厚壁空洞伴液平，血吸虫为肺纹理增粗、小结节与肺动脉扩张，包虫为薄壁囊性灶；增强 CT 与 MRI 有助包虫定性。","鉴别：细菌性肺脓肿无疫区史且嗜酸性粒细胞正常，肺结核为上叶空洞伴抗酸阳性，肺癌为厚壁偏心空洞伴强化。"],"workup":["血常规（嗜酸性粒细胞绝对计数）与血清总 IgE","痰、胸液、粪、尿查虫卵与滋养体","血清学：阿米巴 IHA/ELISA、血吸虫抗体、包虫 ELISA 与免疫印迹、肺吸虫抗体","胸部薄层 CT 加腹部超声或 CT（肝脓肿、肝囊肿）","超声心动图评估肺动脉高压，必要时右心导管","包虫术前评估囊壁完整性，避免穿刺与剧烈活动"],"grading":"肺阿米巴分单纯肺脓肿、脓肿-支气管瘘与脓胸；血吸虫分急性期、慢性期与晚期（肺动脉高压、肺心病）；包虫按 WHO-IWGE 分 CE1–CE5（CE4、CE5 为无活性），并按囊肿数量、大小与有无破裂分层。"},"ddx":[{"name":"免疫缺陷者肺炎（resp_immunodef_pneu）","point":"与本类中免疫缺陷者肺炎的鉴别点：寄生虫病有明确疫区、生食或犬接触史，外周血嗜酸性粒细胞 >500/µL，无粒缺或移植背景；免疫缺陷者肺炎以细菌、真菌、病毒为主，嗜酸性粒细胞多正常，靠病原学确诊。"},{"name":"肺念珠菌病（resp_candida）","point":"免疫抑制宿主，痰培养念珠菌多为定植，确诊需组织病理；寄生虫病以流行病学史与血清学为关键，嗜酸性粒细胞常升高。"},{"name":"细菌性肺脓肿","point":"急起高热、脓臭痰、厚壁空洞伴液平，白细胞升高；无疫区史与嗜酸性粒细胞增多，抗细菌治疗有效。"},{"name":"肺结核","point":"上叶尖后段空洞与树芽征，抗酸染色或结核核酸阳性；病程更长，嗜酸性粒细胞不显著升高。"},{"name":"支气管肺癌","point":"厚壁偏心空洞、边缘毛刺、增强强化，CEA 可升高；包虫囊壁薄而光滑、无强化，血清学阳性。"},{"name":"肺栓塞","point":"突发胸痛气促、D-二聚体升高，CTPA 见充盈缺损；血吸虫相关肺动脉高压为慢性过程，需超声与右心导管评估。"},{"name":"细菌性肝脓肿","point":"起病急、黄疸、胆道病史，脓液培养阳性；阿米巴肝脓肿多为巧克力色脓液、血清学阳性，甲硝唑治疗有效。"}],"tx":{"drug":[{"name":"甲硝唑（肺阿米巴）","dose":"750 mg 口服或静滴 tid × 7–10 天，重症可延长至 14 天","note":"杀组织内滋养体；疗程结束后必须用肠腔内药物清除包囊，防止复发","renal":"CrCl <30 mL/min 减量或延长给药间隔","hepatic":"严重肝功能不全者减量","interact":"用药期间禁酒（双硫仑样反应）；增强华法林；苯妥英、苯巴比妥加速其代谢"},{"name":"巴龙霉素（肠腔清除）","dose":"500 mg 口服 tid × 7 天；或二氯尼特 500 mg 口服 tid × 10 天","note":"甲硝唑疗程结束后使用；妊娠期清除包囊首选巴龙霉素","renal":"肾功能不全者慎用","hepatic":"遵说明书","interact":"与降糖药合用可致低血糖；与其他氨基糖苷类肾毒性叠加"},{"name":"吡喹酮（血吸虫与肺吸虫）","dose":"血吸虫：40 mg/kg 单次（日本血吸虫）或 60 mg/kg 分 2–3 次 1 天内服完（曼氏、埃及血吸虫）；肺吸虫：25 mg/kg tid × 2–3 天","note":"饭后服用；治疗后复查虫卵；脑型血吸虫需同时抗癫痫，必要时用激素","renal":"无需调整","hepatic":"严重肝功能不全者减量并监测肝酶","interact":"利福平、卡马西平、苯妥英降低其浓度；地塞米松降低浓度；与阿苯达唑合用可增加肝毒性"},{"name":"阿苯达唑（包虫）","dose":"10–15 mg/kg/d 分 2 次口服（最大 800 mg/d）；术前 4 周、术后 4–8 周，疗程 3–6 个月；可用 28 天服药、14 天停药的循环方案","note":"包虫首选药物；术前用药减少囊液外溢播散；监测肝酶与血常规（骨髓抑制）","renal":"无需调整","hepatic":"肝功能不全者慎用，治疗前及每 2–4 周查肝酶","interact":"地塞米松提高其血药浓度；与吡喹酮合用增加肝毒性与浓度"},{"name":"甲苯咪唑（包虫替代）","dose":"40–50 mg/kg/d 分 3 次口服，疗程 3–6 个月","note":"用于阿苯达唑不耐受者；吸收差，需随含脂食物服用","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"西咪替丁升高其浓度；卡马西平降低其浓度"}],"nonDrug":["肺阿米巴：超声或 CT 引导肝脓肿穿刺引流（巧克力色脓液），合并脓胸行闭式引流，不常规开胸","肺血吸虫：急性期卧床护肝；肺动脉高压者按 PAH 指南用波生坦或西地那非，右心衰者利尿","肺包虫：禁忌经皮穿刺或活检（过敏性休克与播散风险）；手术为首选（内囊摘除加囊壁缝合或肺叶切除），术中用 20% 高渗盐水灭活；PAIR 仅用于肝囊型包虫，不用于肺","包虫围手术期：术前阿苯达唑 4 周，术后继续 4–8 周；多发或不耐受手术者长期服药","肺吸虫：重症或脑型加用激素，皮下结节可切除","疫区防控：犬定期驱虫、粪便无害化、灭螺、饮水煮沸"],"life":["疫区居民与旅行者避免赤足接触疫水，饮煮沸水，淡水蟹与蝲蛄彻底煮熟","犬定期驱虫，接触犬后洗手，避免儿童玩土","治疗后 3、6、12 个月复查影像与血清学；包虫需随访 5 年以上","血吸虫治疗后 1 个月复查粪卵；肺动脉高压者每年复查超声心动图","出现咯血、突发胸痛或呼吸困难立即就诊（警惕包虫破裂）"]},"prog":"肺阿米巴规范治疗病死率 <5%，延误治疗合并脓胸或脑脓肿者可达 10%–20%。肺血吸虫急性期治愈率高，慢性肺动脉高压者 5 年生存 50%–70%。肺包虫术后复发率 2%–10%，囊液外溢者更高，规范围手术期阿苯达唑可降低复发。","refs":["《内科学》第 9 版（呼吸系统 肺寄生虫病）","中华人民共和国卫生行业标准《血吸虫病诊断标准》（WS 261—2006）","中国医师协会外科医师分会包虫病外科专业委员会《肝两型包虫病诊断与治疗专家共识（2019 版）》","《食源性寄生虫病诊治专家共识（2023 年版）》","WHO/PAHO《Guidelines for the Treatment of Human Echinococcosis》（2010）"]}]},{"id":"ild_more","name":"其他间质性肺疾病","rank":43,"summary":"本类聚焦肺泡填充性病变的鉴别：核心是 HRCT 模式（磨玻璃、铺路石征、囊腔）与 BALF 细胞学、病理结合，避免把可治的肺泡蛋白沉积症误当感染或特发性肺纤维化。","compare":[{"diseaseId":"ild_pap","dx":"隐匿起病的活动后气促，HRCT 双肺磨玻璃伴铺路石征，BALF 牛奶样且 PAS 阳性，血清 GM-CSF 自身抗体阳性","key":"病理本质是表面活性物质在肺泡内沉积而非炎症或纤维化；全肺灌洗为首选，糖皮质激素无效"}],"diseases":[{"id":"ild_pap","name":"肺泡蛋白沉积症","aka":["Pulmonary Alveolar Proteinosis","PAP","aPAP","肺泡蛋白沉积"],"rank":1,"basic":{"define":"肺泡蛋白沉积症（PAP）是一种罕见的弥漫性肺疾病：肺泡巨噬细胞清除表面活性物质的功能障碍，导致脂蛋白样物质在肺泡腔内沉积，引起气体交换障碍。约 90% 为自身免疫性，由抗粒细胞-巨噬细胞集落刺激因子（GM-CSF）自身抗体介导。","risk":["吸烟（自身免疫性 PAP 患者中 60%–70% 有吸烟史）","粉尘与烟雾暴露：二氧化硅、金属粉尘、有机溶剂","血液系统恶性肿瘤、骨髓增生异常综合征（继发性）","免疫抑制、移植后、HIV 感染（继发性）","CSF2RA 或 CSF2RB 基因突变（先天性，多见于儿童）","男性、30–50 岁为发病高峰"],"epi":"患病率约 6–7/百万，年发病率约 0.2/百万。我国报道以 30–50 岁为主，男女比约 2:1；自身免疫性占 90%，先天性不足 2%。"},"patho":"GM-CSF 通过肺泡巨噬细胞表面受体（CSF2R）促进其成熟与清除表面活性物质。自身抗体中和 GM-CSF 后巨噬细胞功能缺陷，表面活性物质（磷脂与载脂蛋白）在肺泡内蓄积，形成 PAS 阳性蛋白样物质，阻碍肺泡-毛细血管气体弥散，产生肺内分流与低氧血症。肺泡结构早期正常，晚期可纤维化。","dx":{"criteria":["临床：隐匿起病的活动后气促、干咳、乏力、体重下降，病程数月至数年；咯血少见，体征轻（发绀、杵状指少见）。","血气：PaO2 降低、A-a DO2 增大；活动后 SpO2 下降 ≥5% 或低于 90%；DLCO 下降常先于肺容积改变。","肺功能：限制性通气障碍（TLC <80% 预计值），DLCO <70% 预计值；6 分钟步行距离下降。","HRCT：双肺弥漫磨玻璃影，伴小叶间隔增厚呈铺路石征（crazy-paving），地图样分布，下叶及外周为主；无蜂窝与牵拉性支气管扩张（晚期例外）。","BALF：外观牛奶样或乳白色，放置后分层；光镜下肺泡巨噬细胞增大、胞质 PAS 阳性颗粒；电镜下见层状小体。","血清 GM-CSF 自身抗体：ELISA 阳性，敏感性与特异性均超过 90%，是自身免疫性 PAP 的关键诊断依据，可替代肺活检。","组织病理：肺泡腔内充满嗜酸性细颗粒状物质，PAS 阳性、AB-PAS 阴性，肺泡间隔轻度增厚。","排除：肺孢子菌肺炎、肺水肿、肺泡出血、外源性过敏性肺泡炎、黏液腺癌与病毒性肺炎。"],"workup":["胸部薄层 HRCT，评估铺路石征与分布","BALF 外观、细胞分类、PAS 染色与电镜检查","血清 GM-CSF 自身抗体（送检周期长，可先治疗后送检）","肺功能含 DLCO 与 TLC、6 分钟步行试验、血气分析","痰与 BALF 病原学排除 PCP、真菌与结核","抗体阴性或不典型者行经支气管或外科肺活检；同时查血常规、LDH、肝肾功能筛查继发性病因"],"grading":"按病因分自身免疫性（90%）、继发性（粉尘、血液病、免疫抑制）与先天性（基因突变）。按严重度：DLCO <40% 预计值、PaO2 <65 mmHg 或 A-a DO2 >40 mmHg 提示需全肺灌洗。按影像分铺路石型、磨玻璃型与实变型。"},"ddx":[{"name":"肺孢子菌肺炎（resp_pcp）","point":"本大类仅本病，故列最易混淆的邻类疾病作鉴别：PCP 同样表现为双肺磨玻璃影与低氧，但宿主有 CD4 <200/µL 或长期激素背景，LDH 与 G 试验升高，BALF 六胺银或 PCR 阳性，抗 PCP 治疗有效；PAP 的 BALF 为牛奶样、PAS 阳性，GM-CSF 抗体阳性，抗感染无效。"},{"name":"肺水肿","point":"心衰史、BNP 或 NT-proBNP 升高、双侧胸腔积液，磨玻璃影呈重力分布，对利尿有效；PAP 无心脏扩大与 BNP 升高。"},{"name":"弥漫性肺泡出血","point":"咯血、血红蛋白下降，BALF 呈血性且逐管加深，含铁血黄素巨噬细胞阳性；PAP 的 BALF 为乳白色而非血性。"},{"name":"外源性过敏性肺泡炎（ild_hypersensitivity）","point":"抗原接触史（鸟、霉变草料、加湿器），BALF 淋巴细胞 >50%、CD4/CD8 比值降低，脱离抗原后改善；PAP 的 BALF 以 PAS 阳性巨噬细胞为主。"},{"name":"病毒性肺炎","point":"急性发热、肌痛、淋巴细胞减少，病毒核酸阳性；影像磨玻璃但病程短，PAP 病程以月计。"},{"name":"特发性肺纤维化（ild_ipf）","point":"蜂窝、牵拉性支气管扩张、基底部分布，DLCO 下降，抗纤维化治疗；PAP 无蜂窝，铺路石征为主。"},{"name":"黏液腺癌（肺炎型肺癌）","point":"实变伴支气管充气征，CEA 可升高，BALF 或活检见恶性细胞；PAP 的实变为蛋白样物质填充，细胞学阴性。"}],"tx":{"drug":[{"name":"沙格司亭（GM-CSF 替代治疗）","dose":"5–10 µg/kg/d 皮下注射，或雾化吸入 250–500 µg qd–bid（按治疗中心方案调整），疗程 3–6 个月","note":"用于全肺灌洗依赖、复发或不能耐受灌洗者；监测发热、皮疹、注射部位反应与白细胞增多","renal":"遵说明书","hepatic":"遵说明书","interact":"与化疗或放疗同期增加骨髓毒性；避免与其他免疫抑制剂同用"},{"name":"利妥昔单抗（难治性或自身免疫性）","dose":"375 mg/m² 静滴，每周 1 次，共 4 次","note":"清除产生 GM-CSF 抗体的 B 细胞；监测输注反应、HBV 再激活与低丙种球蛋白血症","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"与活疫苗、其他免疫抑制剂合用增加感染风险；可致 HBV 再激活"}],"nonDrug":["全肺灌洗（WLL）：金标准，每次 10–20 L 37°C 生理盐水，单侧肺灌洗，双侧间隔 1–2 周；适应证为 PaO2 <65 mmHg、DLCO <40% 预计值或活动受限","戒烟与脱离粉尘暴露，是最重要的一级措施","血浆置换：用于重症、抗体介导或灌洗前准备，一般 3–5 次","肺移植：终末期纤维化或反复灌洗无效者（约 5%–10%）","灌洗前后筛查并治疗合并感染（PCP、曲霉），感染期暂缓灌洗","避免不必要的糖皮质激素与免疫抑制，既无效又增加感染"],"life":["绝对戒烟，避免粉尘、烟雾与有机溶剂暴露","每 3–6 个月复查肺功能、DLCO、6 分钟步行试验与 HRCT","出现发热、咳黄痰或气促加重立即就诊，感染可致命","灌洗后 4–6 周复查影像与血气评估疗效","接种流感与肺炎链球菌疫苗；免疫抑制治疗期间避免活疫苗"]},"prog":"全肺灌洗后 70%–80% 患者症状与氧合改善，疗效维持 6–12 个月；5 年复发率 10%–30%，需重复灌洗。约 5%–10% 进展为肺纤维化，总体 5 年生存超过 90%；未治疗的重症患者可死于呼吸衰竭或继发感染。","refs":["中国肺泡蛋白沉积症诊断和治疗专家共识（2022 年版，中华结核和呼吸杂志）","欧洲呼吸学会（ERS）《肺泡蛋白沉积症诊断与管理指南》（2024）","国家卫生健康委员会《中国罕见病诊疗指南（2019 年版）》","《内科学》第 9 版（呼吸系统 间质性肺疾病）"]}]},{"id":"pleura_tumor","name":"胸膜肿瘤","rank":44,"summary":"胸膜肿瘤以转移性最常见，原发性恶性胸膜间皮瘤与石棉暴露密切相关；诊断依赖影像、胸腔镜活检与免疫组化，治疗以多学科综合为主，整体预后差，姑息支持应早期介入。","compare":[{"diseaseId":"resp_mesothelioma","dx":"石棉暴露史（潜伏 20–40 年），胸痛与反复胸腔积液，CT 见胸膜弥漫结节状增厚 >1 cm，胸腔镜活检加免疫组化（Calretinin、WT-1、D2-40 阳性）确诊","key":"与肺腺癌胸膜转移靠免疫组化鉴别（TTF-1、CEA 阴性）；可切除者多模式治疗，不可切除者培美曲塞加铂，联合免疫治疗"}],"diseases":[{"id":"resp_mesothelioma","name":"胸膜间皮瘤","aka":["Malignant Pleural Mesothelioma","MPM","恶性胸膜间皮瘤","Diffuse Malignant Pleural Mesothelioma"],"rank":1,"basic":{"define":"胸膜间皮瘤是起源于胸膜间皮细胞的肿瘤，恶性胸膜间皮瘤（MPM）是最常见的原发性胸膜恶性肿瘤，几乎均与石棉暴露相关，潜伏期 20–40 年，侵袭性强、预后差。","risk":["石棉暴露：造船、建筑、保温、纺织、刹车片制造与拆除作业","间接或环境暴露：清洗石棉污染工作服、居住在石棉厂矿附近","潜伏期长（20–40 年），接触后终生风险升高","男性、年龄 50–70 岁","既往胸部放疗（霍奇金淋巴瘤放疗后）","毛沸石暴露、BAP1 基因胚系突变（罕见）"],"epi":"全球每年新发约 3 万例，我国估计年发病 2–3/百万，随石棉暴露滞后效应呈上升趋势。中位发病年龄 60–70 岁，男性多于女性；中位生存 12–18 个月，5 年生存率不足 10%。"},"patho":"石棉纤维（尤其长而细的角闪石纤维）沉积于胸膜，诱导慢性炎症、活性氧损伤与基因突变（CDKN2A 缺失、BAP1 突变、NF2 失活），间皮细胞恶性转化后在胸膜腔弥漫生长，形成结节状或弥漫性胸膜增厚并包裹肺，产生大量胸腔积液。肿瘤局部侵袭性强，可侵犯心包、膈肌与胸壁，血行转移相对较晚。","dx":{"criteria":["病史：石棉暴露史（职业、环境或家庭间接接触）加潜伏期 20–40 年；约 20% 患者无明确暴露史，不能据此排除。","症状：持续性胸痛（钝痛，不随体位缓解）、呼吸困难、体重下降与乏力；胸腔积液反复增长。","影像：CT 见胸膜弥漫结节状或波浪状增厚（厚度 >1 cm）、胸膜环状增厚包绕肺、叶间裂增厚、纵隔胸膜受累、肋膈角闭塞与胸腔积液；可伴胸壁侵犯与心包增厚。","PET-CT：胸膜局限性高代谢（SUVmax 常 >4），用于分期与良恶性鉴别。","胸腔积液：渗出液，LDH 升高、葡萄糖降低（常 <3.3 mmol/L）、pH 降低，透明质酸升高；细胞学阳性率仅 30%–50%。","胸腔镜活检为金标准：敏感性与特异性均超过 90%，可直视下多点取材（壁层、膈、纵隔胸膜）。","免疫组化：Calretinin、WT-1、CK5/6、D2-40、MC 阳性；CEA、TTF-1、MOC-31、Ber-EP4 阴性，用于与肺腺癌胸膜转移鉴别。","分期：IASLC TNM 第 8 版（2016）；组织学亚型分上皮样（55%–65%，预后较好）、双相型（20%–30%）、肉瘤样（10%–15%，预后最差）。"],"workup":["胸部与上腹部增强 CT，评估胸膜、膈肌、心包与对侧胸膜","PET-CT 用于分期与指导活检；必要时纵隔镜或 EBUS 行淋巴结分期","胸腔穿刺：积液常规、生化、细胞学、透明质酸与 CEA","胸腔镜活检（首选），必要时开胸活检","免疫组化套餐：间皮标记加腺癌排除标记","肺功能、血气与超声心动图评估手术耐受性"],"grading":"组织学分为上皮样、双相型与肉瘤样；分期采用 IASLC TNM 第 8 版（Ⅰ–Ⅳ期，Ⅳ期为远处转移）；按可切除性分潜在可切除（Ⅰ–ⅢA 期、上皮样、PS 0–1）与不可切除。"},"ddx":[{"name":"肺癌胸膜转移","point":"本大类仅本病，故列最易混淆的邻类疾病作鉴别：肺腺癌胸膜转移有肺内原发肿块、CEA 升高，TTF-1 与 Napsin A 阳性、间皮标记阴性，胸膜增厚常伴肺内病灶；间皮瘤以胸膜弥漫环状增厚为主，Calretinin、WT-1、D2-40 阳性。"},{"name":"结核性胸膜炎（resp_tb_pleurisy）","point":"中青年、低热盗汗，PPD 或 IGRA 阳性，胸水 ADA >40 U/L、淋巴细胞为主，抗结核治疗有效；胸膜增厚多光滑、无结节。"},{"name":"良性石棉性胸腔积液","point":"有石棉暴露史，渗出液可反复发作但自限，细胞学阴性，长期随访无肿瘤证据；需胸腔镜排除恶性。"},{"name":"其他来源胸膜转移癌","point":"乳腺、卵巢、胃肠道转移，免疫组化 CK7/CK20、ER/PR、PAX8 等帮助定位，常伴原发灶症状。"},{"name":"胸膜孤立性纤维性肿瘤","point":"局限性边界清楚肿块而非弥漫增厚，CD34 与 STAT6 阳性，多为良性，手术切除预后好。"},{"name":"脓胸与胸膜纤维化","point":"感染史、脓性胸水、胸膜增厚伴钙化，抗感染与引流有效；无结节状增厚与高代谢。"},{"name":"反应性胸膜间皮增生","point":"石棉暴露者可见良性反应性增生，需免疫组化（BAP1 缺失、p16 FISH 支持恶性）与胸腔镜多点活检鉴别。"}],"tx":{"drug":[{"name":"培美曲塞 + 顺铂（一线）","dose":"培美曲塞 500 mg/m² 静滴（10 分钟）q21d，加顺铂 75 mg/m² 静滴 q21d，共 6 周期","note":"用药前 7 天起叶酸 400–1000 µg qd 至末次后 21 天，维生素 B12 1000 µg 肌注（首次前 1 周，之后每 9 周），地塞米松 4 mg bid 于用前 1 天、当天与后 1 天预防皮疹","renal":"培美曲塞在 CrCl <45 mL/min 不推荐；顺铂在 CrCl <60 mL/min 减量或改卡铂","hepatic":"培美曲塞在总胆红素 >3×ULN 时慎用","interact":"NSAIDs 减少培美曲塞排泄（CrCl 45–79 mL/min 慎用）；顺铂与氨基糖苷类肾毒性叠加"},{"name":"培美曲塞 + 卡铂（顺铂不耐受）","dose":"培美曲塞 500 mg/m² 加卡铂 AUC 5 静滴 q21d，共 6 周期","note":"卡铂按 Calvert 公式计算；血小板减少较顺铂明显","renal":"卡铂按 CrCl 调整 AUC；培美曲塞在 CrCl <45 mL/min 不推荐","hepatic":"同培美曲塞","interact":"同培美曲塞"},{"name":"纳武利尤单抗 + 伊匹木单抗（一线免疫联合）","dose":"纳武利尤单抗 360 mg 静滴 q3w，加伊匹木单抗 1 mg/kg 静滴 q6w，最长 24 个月","note":"用于不可切除 MPM 一线，非上皮样亚型获益更明显；监测免疫相关肺炎、结肠炎、肝炎与内分泌病","renal":"无需调整","hepatic":"转氨酶 >5×ULN 时暂停","interact":"与激素或其他免疫抑制剂合用降低疗效；避免活疫苗"},{"name":"贝伐珠单抗 + 培美曲塞/顺铂（可选）","dose":"贝伐珠单抗 15 mg/kg 静滴 q21d，联合培美曲塞与顺铂","note":"MAPS 研究显示总生存延长（18.8 个月对 16.1 个月）；注意高血压、蛋白尿、出血与血栓风险","renal":"无需调整","hepatic":"肝功能不全者慎用","interact":"与抗凝或抗血小板药合用增加出血；与 NSAIDs 合用增加肾毒性"},{"name":"培美曲塞单药（二线或维持）","dose":"500 mg/m² 静滴 q21d","note":"一线未用培美曲塞者可二线使用，或一线联合治疗后维持","renal":"CrCl <45 mL/min 不推荐","hepatic":"总胆红素 >3×ULN 慎用","interact":"同培美曲塞联合方案"},{"name":"吉西他滨（二线）","dose":"1000 mg/m² 静滴 d1、d8，q21d","note":"二线替代方案；骨髓抑制与流感样症状常见","renal":"CrCl <30 mL/min 慎用或减量","hepatic":"胆红素 >1.5×ULN 减量","interact":"与放疗同期增加肺毒性；增强华法林作用"}],"nonDrug":["胸膜固定术：滑石粉 3–5 g 经胸腔镜喷洒或经引流管注入，用于复发性胸腔积液且肺可复张者，失败率 10%–15%","留置胸膜导管：肺不能复张或复发性积液，可居家引流","手术：潜在可切除（Ⅰ–ⅢA 期、上皮样、PS 0–1）行胸膜切除/剥脱术或胸膜外全肺切除，加辅助治疗，须多学科评估","放疗：穿刺通道预防性放疗 21 Gy/3 次减少种植；姑息止痛可用 30 Gy/10 次","姑息治疗：阿片类镇痛、氧疗、营养与心理支持，确诊后早期引入","避免反复胸腔穿刺；如需活检优先胸腔镜，并计划通道放疗"],"life":["完全戒烟（降低肺癌风险，虽不直接降低间皮瘤风险）","职业暴露者脱离石棉环境，家庭成员避免接触污染工作服","每 2–3 个月复查 CT 与体重，监测免疫治疗不良反应（皮疹、腹泻、气促）","接种流感与肺炎链球菌疫苗，免疫治疗期间避免活疫苗","呼吸困难者家庭氧疗与呼吸康复，早期进行预立医疗计划沟通"]},"prog":"不可切除 MPM 中位生存 12–18 个月，上皮样型 16–20 个月，肉瘤样型仅 6–10 个月，5 年生存率不足 10%。免疫联合治疗使部分患者 2 年生存率提高至约 40%，非上皮样亚型获益更明显。预后因素包括组织学亚型、PS 评分、分期、血小板与白细胞计数及 LDH 水平。","refs":["《中国恶性胸膜间皮瘤临床诊疗指南（2021 版）》（中华肿瘤杂志）","《中国恶性胸膜间皮瘤临床诊治全国专家共识（2023 年版）》","NCCN《Clinical Practice Guidelines in Oncology: Malignant Pleural Mesothelioma》（2024）","ESMO《Clinical Practice Guidelines: Malignant Pleural Mesothelioma》（2022）","《内科学》第 9 版（呼吸系统 胸膜疾病）"]}]}]},"rheum":{"categories":[{"id":"ra_as","name":"关节炎","rank":1,"summary":"以「控制滑膜炎、阻止结构损伤」为核心：RA 尽早启动 csDMARD（甲氨蝶呤为锚药）并达标治疗；AS 以 NSAIDs 一线、TNF 抑制剂等生物制剂为二线，贯穿功能锻炼。","compare":[{"diseaseId":"rh_ra","dx":"对称性小关节（MCP、PIP、腕）肿痛 >6 周 + RF/抗 CCP 阳性 + ESR/CRP 升高，超声/MRI 见滑膜炎或骨侵蚀","key":"对称、外周小关节、晨僵 >1 h、RF/抗 CCP 阳性"},{"diseaseId":"rh_as","dx":"炎性腰背痛 >3 个月（起病 <40 岁、隐匿起病、活动后改善）、骶髂关节 X 线双侧 ≥Ⅱ级或单侧 ≥Ⅲ–Ⅳ级（或 MRI 骨髓水肿），HLA-B27 阳性支持","key":"中轴受累、夜间痛、活动后改善、HLA-B27 阳性、RF 阴性"}],"diseases":[{"id":"rh_ra","name":"类风湿关节炎","aka":["Rheumatoid Arthritis","RA","类风关"],"rank":1,"basic":{"define":"以慢性、对称性多关节滑膜炎为特征的全身性自身免疫病，可致关节畸形与功能丧失，并累及肺、眼、血管等关节外器官。","risk":["女性（男女比约 1:3）","发病高峰 30–50 岁","吸烟（尤其携带 HLA-DRB1 共享表位者）","一级亲属患病","牙周炎等口腔菌群异常","肥胖、低社会经济状态"],"epi":"我国患病率约 0.28%–0.42%，患者近 500 万；未经规范治疗者 2 年内约 70% 出现影像学骨侵蚀，致残率高。"},"patho":"遗传易感（HLA-DRB1 共享表位、PTPN22）+ 环境触发（吸烟、牙周菌）导致自身抗原瓜氨酸化，产生抗 CCP 抗体；滑膜内 T/B 细胞与巨噬细胞浸润，TNF-α、IL-6 驱动滑膜增生形成血管翳，基质金属蛋白酶与破骨细胞活化造成软骨与骨破坏。","dx":{"criteria":["2010 ACR/EULAR 分类标准（总分 ≥6/10）：受累关节 1 个大关节 0 分、2–10 个大关节 1 分、1–3 个小关节 2 分、4–10 个小关节 3 分、>10 个关节且至少 1 个小关节 5 分","血清学：RF 与抗 CCP 均阴性 0 分、至少一项低滴度阳性 2 分、至少一项高滴度阳性（>3 倍正常上限）3 分","急性期反应物：CRP 与 ESR 均正常 0 分、任一项异常 1 分","症状持续时间：<6 周 0 分、≥6 周 1 分","关节受累需为临床可确认的滑膜炎（肿胀），且无其他疾病可更好解释"],"workup":["关节计数（DAS28、CDAI/SDAI），记录晨僵时间","RF、抗 CCP 抗体（抗 CCP 特异性约 95%）","ESR、CRP、血常规、肝肾功能、乙肝（HBsAg、抗 HBc）、丙肝、结核筛查（T-SPOT/PPD + 胸片）——用药前必查","手足 X 线：软组织肿胀、关节周围骨质疏松、关节间隙狭窄、边缘性骨侵蚀","关节超声能量多普勒见滑膜增生与血流信号，可早于 X 线发现侵蚀；MRI 骨髓水肿提示预后不良","合并间质性肺病者查 HRCT、肺功能"],"grading":"DAS28-ESR 缓解 <2.6、低活动 2.6–3.2、中活动 3.2–5.1、高活动 >5.1；CDAI 缓解 ≤2.8。功能按 HAQ-DI 或 ACR 功能分级Ⅰ–Ⅳ。"},"ddx":[{"name":"强直性脊柱炎（rh_as）","point":"与本类 rh_as 的鉴别点：RA 为外周对称性小关节炎、RF/抗 CCP 常阳性、HLA-B27 多阴性；AS 以中轴（骶髂、脊柱）受累为主、起病 <40 岁、RF 阴性、HLA-B27 阳性，外周多为下肢非对称寡关节炎。"},{"name":"银屑病关节炎","point":"有银屑病或甲改变，DIP 受累、腊肠指、附着点炎，RF 多阴性；X 线见「笔帽样」改变。"},{"name":"系统性红斑狼疮关节表现","point":"多为非侵蚀性关节痛，伴蝶形红斑、光敏、口腔溃疡、血细胞减少，抗 dsDNA/抗 Sm 阳性，尿检异常提示肾受累。"},{"name":"痛风性关节炎","point":"急性单关节红热痛，第一跖趾关节最常见，血尿酸升高，超声双轨征，偏振光镜下见负双折射针状结晶。"},{"name":"骨关节炎","point":"负重关节（膝、髋）为主，活动后加重、休息缓解，晨僵 <30 min，Heberden/Bouchard 结节，无显著滑膜肿胀与自身抗体。"},{"name":"病毒性关节炎","point":"乙肝、丙肝、细小病毒 B19 等所致对称性小关节痛，有前驱发热/皮疹，多 6 周内自限，病毒血清学阳性。"}],"tx":{"drug":[{"name":"甲氨蝶呤（MTX）","dose":"7.5–15 mg 口服或皮下，每周 1 次（起始 7.5–10 mg/周，2–4 周可加至 15 mg/周，最大 25 mg/周）；同时补充叶酸 5 mg/周（MTX 后 24 h 服用）","note":"锚定药物，确诊即启动，无需等待 X 线侵蚀；4–6 周复查血常规、肝肾功能，起效需 6–12 周","renal":"eGFR 30–59 起始 5–7.5 mg/周并密切监测；eGFR <30 禁用","hepatic":"ALT/AST >2 倍正常上限慎用、>3 倍禁用；长期饮酒或肝纤维化风险高者慎用","interact":"与复方磺胺/TMP-SMX 合用增加骨髓抑制；NSAIDs 可加重肾毒性；禁饮酒；与生物制剂联用安全"},{"name":"来氟米特","dose":"10–20 mg qd（用于 MTX 不耐受/禁忌者）","note":"不常规与 MTX 联用（毒性叠加）；有致畸性，计划妊娠前需消胆胺 8 g tid×11 天洗脱","renal":"eGFR <30 慎用或避免","hepatic":"活动性肝病、转氨酶持续升高者禁用","interact":"与 MTX 联用肝毒性叠加；利福平降低其血药浓度"},{"name":"羟氯喹","dose":"200–400 mg/d（≤5 mg/kg 实际体重）","note":"早期轻症或中低活动度可单用；长期使用者每年眼底检查（见 SS 条目监测方案）","renal":"eGFR <30 减量或慎用","hepatic":"严重肝损伤慎用","interact":"可升高 MTX 浓度；与胺碘酮、莫西沙星等增加 QT 延长风险"},{"name":"泼尼松","dose":"中高活动度起始 ≤10 mg/d（或等效剂量），联合 csDMARD 桥接；病情允许时 3 个月内减至 ≤5 mg/d，尽早停用","note":"不单药长期维持；关节腔注射前须排除感染","renal":"无需调整","hepatic":"监测血糖、血压","interact":"与 NSAIDs 联用增加消化道出血风险"},{"name":"阿达木单抗（TNF 抑制剂）","dose":"40 mg 皮下注射，每 2 周 1 次","note":"csDMARD 治疗 3–6 个月未达标时加用；用药前筛查结核、乙肝；活动性感染禁用","renal":"无需调整","hepatic":"严重肝功能不全慎用","interact":"不与阿那白滞素、阿巴西普联用；活疫苗禁忌"},{"name":"托法替布（JAK 抑制剂）","dose":"5 mg bid 口服","note":"用于 csDMARD/生物制剂应答不佳；≥65 岁、吸烟、既往 VTE 或心血管/肿瘤高危者先评估风险","renal":"CKD Ⅳ–Ⅴ 期减量或避免","hepatic":"Child-Pugh C 禁用","interact":"CYP3A4 强抑制剂/诱导剂显著改变暴露；与 MTX 合用可增加肝酶异常"},{"name":"NSAIDs（塞来昔布、依托考昔、双氯芬酸等）","dose":"按病情间歇或短期使用，遵说明书","note":"仅缓解症状，不改变病程；有消化道溃疡、CKD、心衰者慎用","renal":"eGFR <30 禁用，eGFR 30–59 慎用","hepatic":"严重肝病禁用","interact":"与抗凝剂、利尿剂、ACEI/ARB 合用增加出血与急性肾损伤风险"}],"nonDrug":["达标治疗（T2T）：每 1–3 个月评估 DAS28/CDAI，目标临床缓解或低活动度；持续 ≥6 个月可考虑减量","滑膜切除术：单关节顽固性滑膜炎、药物治疗失败","关节置换：晚期髋膝破坏致功能丧失；腕管综合征减压"],"life":["戒烟、地中海饮食、控制体重、肌力与有氧训练","每 3–6 个月评估心血管与骨质疏松风险；长期激素者补充钙剂与维生素 D","疫苗接种：流感、肺炎链球菌、乙肝、带状疱疹（活疫苗在免疫抑制期间禁用）","妊娠规划：MTX、来氟米特、大部分生物制剂需提前停药，羟氯喹可继续"]},"prog":"早期达标治疗 5 年缓解率可达 30%–50%；未达标者 10 年内约 50% 出现明显功能受限，寿命缩短 5–10 年，主要死因为心血管疾病与感染。合并间质性肺病者预后较差。","refs":["2023 中国类风湿关节炎诊疗规范（中华内科杂志）","2020 中国类风湿关节炎诊疗指南","2010 ACR/EULAR 类风湿关节炎分类标准","2021 EULAR 类风湿关节炎管理建议"]},{"id":"rh_as","name":"强直性脊柱炎","aka":["Ankylosing Spondylitis","AS","放射学阳性中轴型脊柱关节炎"],"rank":2,"basic":{"define":"以骶髂关节与脊柱受累为主的慢性炎症性风湿病，属中轴型脊柱关节炎（axSpA）的放射学阳性表型，可伴葡萄膜炎、银屑病及炎症性肠病。","risk":["HLA-B27 阳性","男性、20–30 岁起病","一级亲属患病","肠道菌群异常与炎症性肠病","泌尿生殖道感染史"],"epi":"我国患病率约 0.3%，患者中 HLA-B27 阳性率约 88%–95%；男女比约 2–3:1。"},"patho":"HLA-B27 递呈关节/肠道来源肽段引发 CD8+T 细胞反应，叠加 IL-23/IL-17 轴激活，导致骶髂关节与附着点慢性炎症；反复炎症后软骨化生与新骨形成（韧带骨赘），最终出现「竹节样」脊柱强直，同时伴骨量丢失。","dx":{"criteria":["炎性腰背痛（ASAS 标准 ≥4 项）：起病年龄 <40 岁；隐匿起病；活动后改善；休息不能缓解；夜间痛（起床后缓解）","影像学骶髂关节炎：X 线双侧 ≥Ⅱ级或单侧 ≥Ⅲ–Ⅳ级；或 MRI 骶髂关节骨髓水肿","加 ≥1 项 SpA 特征：炎性背痛、关节炎、附着点炎、葡萄膜炎、指趾炎、银屑病、IBD、NSAIDs 反应良好、家族史、HLA-B27 阳性、CRP 升高","病程 >3 个月；无放射学改变时 MRI 为早期诊断关键"],"workup":["骶髂关节与腰椎 X 线：骨侵蚀、软骨下硬化、关节间隙变窄或融合","骶髂关节 MRI（STIR/T2-FS）：软骨下骨髓水肿","HLA-B27、ESR、CRP（约 40% 患者 CRP 正常）","BASDAI、BASFI、ASDAS-CRP","活动度评估：Schober 试验、枕墙距、胸廓扩张度","眼科筛查前葡萄膜炎；心电图与超声评估传导阻滞、主动脉瓣反流；腰椎骨密度"],"grading":"骶髂关节炎 X 线 0–Ⅳ级（0 正常、Ⅰ 可疑、Ⅱ 轻度、Ⅲ 中度、Ⅳ 完全强直）；BASDAI ≥4 提示活动；ASDAS-CRP ≥2.1 高活动、<1.3 非活动。"},"ddx":[{"name":"类风湿关节炎（rh_ra）","point":"与本类 rh_ra 的鉴别点：AS 多起病 <40 岁男性、以中轴与下肢非对称寡关节炎为主、RF/抗 CCP 阴性、HLA-B27 阳性；RA 为对称性小关节炎、晨僵更长、自身抗体阳性、骶髂关节罕有典型改变。"},{"name":"致密性髂骨炎","point":"多见产后女性，骶髂关节下 1/3 髂骨侧致密硬化、关节间隙正常、无骨侵蚀，炎症指标正常。"},{"name":"弥漫性特发性骨肥厚（DISH）","point":"老年人，≥4 个椎体前纵韧带连续骨化、椎间隙保留、骶髂关节正常，无炎性腰背痛。"},{"name":"感染性骶髂关节炎","point":"单侧急性剧痛、发热，MRI 见关节腔积液与周围水肿，血培养/穿刺培养阳性。"},{"name":"椎间盘源性下腰痛","point":"机械性疼痛、久坐久站加重、休息改善，无夜间痛与晨僵，HLA-B27 阴性。"}],"tx":{"drug":[{"name":"NSAIDs（塞来昔布、依托考昔、双氯芬酸）","dose":"足量规律使用，4 周后评估疗效，遵说明书","note":"一线治疗；≥2 种 NSAIDs 足量 4 周无效判定为疗效不佳，考虑生物制剂","renal":"eGFR <30 禁用，eGFR 30–59 慎用","hepatic":"严重肝病禁用","interact":"与抗凝剂、ACEI/ARB、利尿剂合用增加肾损伤与出血风险"},{"name":"柳氮磺吡啶","dose":"起始 0.5 g bid，逐周加量至 1.0 g bid–1.0 g tid（每日最大 3 g）","note":"以外周关节炎为主者适用，对中轴症状疗效有限；用药前查 G6PD","renal":"eGFR <30 慎用","hepatic":"肝功能不全者慎用","interact":"磺胺过敏者禁用；影响华法林、MTX 浓度"},{"name":"甲氨蝶呤","dose":"7.5–15 mg 每周 1 次（仅用于以显著外周关节炎为主者），叶酸 5 mg/周","note":"对中轴症状无明确疗效，不用于单纯中轴病变","renal":"eGFR <30 禁用","hepatic":"ALT/AST >3 倍正常上限禁用","interact":"同上 RA 条目"},{"name":"阿达木单抗（TNF 抑制剂）","dose":"40 mg 皮下注射，每 2 周 1 次","note":"NSAIDs 疗效不佳且有高 CRP/高活动度或 MRI 炎症者首选；用药前必须排除结核、乙肝","renal":"无需调整","hepatic":"严重肝功能不全慎用","interact":"活疫苗禁忌；不与阿那白滞素联用"},{"name":"司库奇尤单抗（IL-17A 抑制剂）","dose":"150 mg 皮下注射，第 0、1、2、3、4 周，之后每 4 周 1 次；疗效不佳可增至 300 mg 每 4 周","note":"TNF 抑制剂应答不佳或禁忌时选用；合并炎症性肠病者禁用","renal":"无需调整","hepatic":"重度肝损慎用","interact":"活疫苗禁忌"},{"name":"糖皮质激素","dose":"不推荐全身长期使用；局部关节腔/骶髂关节注射按需，遵说明书","note":"全身激素对中轴症状无获益且损害骨密度；CT 引导下骶髂关节注射可用于顽固性骶髂痛","renal":"无需调整","hepatic":"监测血糖血压","interact":"长期使用需补钙与维生素 D"}],"nonDrug":["规律功能锻炼（脊柱伸展、深呼吸、游泳）为治疗基石，每日进行","物理治疗与姿势训练，避免长期卧床","髋关节置换：严重髋关节破坏致功能受限","脊柱截骨矫形：严重后凸畸形","合并前葡萄膜炎须眼科紧急处理"],"life":["戒烟（吸烟加重脊柱结构损伤并降低 TNF 抑制剂疗效）","睡硬板床、低枕，避免长期低头驼背姿势","定期评估骨密度、心血管风险与情绪睡眠","每 3–6 个月复评 BASDAI/ASDAS 与 CRP"]},"prog":"多数患者进展缓慢，约 10%–20% 最终出现严重强直与功能受限；女性与 HLA-B27 阴性者进展较慢。生物制剂显著改善症状与活动度，但已形成的骨赘不逆转。","refs":["2022 中国强直性脊柱炎诊疗规范","2009 ASAS 中轴型脊柱关节炎分类标准","ASAS/EULAR 中轴型脊柱关节炎管理推荐（2022 更新）"]}]},{"id":"sle_ss","name":"结缔组织病","rank":2,"summary":"系统性自身免疫病：以自身抗体谱+多系统受累定诊断，按疾病活动度与器官威胁分层；SLE 以羟氯喹为基础、激素联合免疫抑制剂，狼疮肾炎与神经精神狼疮决定预后；SS 以替代治疗与羟氯喹为主，警惕淋巴瘤转化。","compare":[{"diseaseId":"rh_sle","dx":"2019 EULAR/ACR：ANA ≥1:80 为入围条件，随后 10 个领域各计分、同一领域取最高分，总分 ≥10 且至少 1 项临床指标可分类为 SLE（如肾脏 4 分、中枢神经 5 分）","key":"多系统受累（皮肤、关节、肾、血液、浆膜）+ 抗 dsDNA/抗 Sm 阳性 + 补体下降"},{"diseaseId":"rh_ss","dx":"2016 ACR/EULAR：唇腺活检灶性淋巴细胞浸润灶性评分 ≥1 且抗 SSA/SSB 阳性各计 3 分，总分 ≥4 可分类（唾液腺/泪腺功能检查等各计 1 分）","key":"口干眼干 >3 个月 + Schirmer 试验/角膜染色阳性 + 抗 SSA/SSB 阳性，常伴高球蛋白血症"}],"diseases":[{"id":"rh_sle","name":"系统性红斑狼疮","aka":["Systemic Lupus Erythematosus","SLE","红斑狼疮"],"rank":1,"basic":{"define":"由自身抗体与免疫复合物介导、累及皮肤、关节、肾脏、血液、神经等多系统的慢性自身免疫病，以复发-缓解为特征。","risk":["育龄期女性（男女比约 9:1）","非洲裔、亚裔人群患病率较高","紫外线暴露诱发","雌激素暴露（口服避孕药、妊娠）","一级亲属患病、单基因干扰素通路变异","EB 病毒、吸烟等环境因素"],"epi":"我国 SLE 患病率约 30–70/10 万（部分地区抽样达 0.1%），患者以 20–40 岁女性为主；肾脏受累率达 40%–60%，是我国患者主要死因之一。"},"patho":"遗传易感叠加紫外线、感染等触发，凋亡细胞清除障碍使核抗原持续暴露；树突状细胞产生大量 I 型干扰素（IFN-α），B 细胞活化产生抗 dsDNA、抗 Sm 等自身抗体，免疫复合物沉积于肾小球、皮肤、血管激活补体经典途径，造成组织损伤与血栓形成。","dx":{"criteria":["2019 EULAR/ACR 分类标准：曾出现 ANA ≥1:80 为入围必备条件","入门时计入的临床指标（同一领域只计最高分）：发热 2 分；血液学—白细胞减少 3 分、血小板减少 4 分、溶血性贫血 4 分；神经精神—谵妄 2 分、精神病 3 分、癫痫 5 分；皮肤黏膜—非瘢痕性脱发 2 分、口腔溃疡 2 分、亚急性皮肤型狼疮/盘状狼疮 4 分、急性皮肤型狼疮 6 分；浆膜炎—胸腔积液/心包积液 5 分、急性心包炎 6 分；关节—≥2 个关节滑膜炎或压痛伴晨僵 ≥30 min 计 6 分；肾脏—尿蛋白 >0.5 g/24 h 计 4 分、肾活检 Ⅲ/Ⅳ 型 8 分或 Ⅴ 型 10 分；免疫学—抗 dsDNA 6 分、抗 Sm 6 分、抗磷脂抗体阳性 2 分、补体 C3/C4 下降 3 分、直接 Coombs 试验阳性（无溶血）4 分","总分 ≥10 且至少 1 项临床指标（非仅免疫学指标）可分类为 SLE；同一表现只计 1 次","临床诊断可早于满足分类标准：年轻女性多系统损害、ANA 阳性、补体下降须高度怀疑"],"workup":["ANA（入职/筛检，≥1:80 为分类标准入围）、抗 dsDNA（与肾炎活动相关）、抗 Sm、抗 U1RNP、抗磷脂抗体（抗心磷脂、抗 β2GP1、LA）","补体 C3/C4、血常规、网织红细胞（溶血）、直接 Coombs、尿常规+尿沉渣、24 h 尿蛋白或尿蛋白/肌酐比","肾功能、肝功能、血脂、空腹血糖、ESR/CRP（SLE 中 CRP 多不高，显著升高提示感染或浆膜炎）","起病或有肾损时行肾活检（LM+IF+EM），依 ISN/RPS 分型指导方案","SLEDAI-2K（活动度）、BILAG-2004（器官活动）、PGA；评估神经精神狼疮时结合脑 MRI、脑脊液、抗 NMDAR 抗体","妊娠评估：抗 SSA/SSB（胎儿心脏传导阻滞）、抗磷脂抗体；用药前筛查乙肝、结核"],"grading":"活动度：SLEDAI-2K ≤4 为轻度活动、5–8 中度、≥9 高度活动、0 为无活动；BILAG A/B 分提示需强化治疗。肾病理 ISN/RPS 2003 分型：Ⅰ 微小系膜、Ⅱ 系膜增生、Ⅲ 局灶（<50% 肾小球）、Ⅳ 弥漫（≥50%）、Ⅴ 膜性、Ⅵ 硬化型。损伤指数（SLICC/ACR DI）评估不可逆器官损害。"},"ddx":[{"name":"干燥综合征（rh_ss）","point":"与本类 rh_ss 的鉴别点：SLE 以抗 dsDNA/抗 Sm、补体下降、狼疮肾炎（免疫复合物肾小球肾炎）为特征；SS 以口干眼干、抗 SSA/SSB 阳性、唇腺灶性淋巴细胞浸润为特征，肾受累多为肾小管间质性肾炎而非肾小球肾炎，少见严重补体下降。"},{"name":"类风湿关节炎","point":"关节为对称性侵蚀性小关节炎，无蝶形红斑、脱发、口腔溃疡，抗 CCP 阳性而抗 dsDNA/抗 Sm 阴性，补体正常。"},{"name":"ANCA 相关血管炎","point":"肾损害为寡免疫复合物新月体肾炎，合并咯血、鼻窦/肺受累；ANCA 阳性、抗 dsDNA 阴性，活检 IF 阴性可与狼疮肾炎区分。"},{"name":"特发性免疫性血小板减少症","point":"仅有血小板减少而无其他系统指标，ANA 阴性或低滴度，补体正常，骨髓巨核细胞正常或增多。"},{"name":"药物性狼疮","point":"由普鲁卡因胺、肼屈嗪、米诺环素等诱发，抗组蛋白抗体常阳性、抗 dsDNA 阴性，停药后多于数周至数月缓解。"}],"tx":{"drug":[{"name":"羟氯喹","dose":"200–400 mg/d（按实际体重 ≤5 mg/kg），口服，长期维持","note":"所有无禁忌的 SLE 患者均应使用；可减少复发、血栓、器官损伤并降低病死率；妊娠期可继续；若无法减量须每年至少 1 次眼科筛查（视野 10-2、OCT、多焦 ERG），长期高剂量（>5 mg/kg/d）者 5 年起每年筛查；出现视网膜黄斑病变立即停药","renal":"eGFR <30 减量或慎用","hepatic":"严重肝功能不全慎用","interact":"可升高 MTX 浓度；与胺碘酮、莫西沙星等增加 QT 延长风险；抗酸剂降低吸收（间隔 4 h）"},{"name":"泼尼松","dose":"轻中度 0.25–0.5 mg/kg/d；重度/器官威胁 0.5–1.0 mg/kg/d；狼疮肾炎 Ⅲ/Ⅳ 型冲击甲泼尼龙 250–500 mg/d×3 天后口服 ≤0.5 mg/kg/d；病情控制后以 4–8 周为一档逐步减量，力争 2–3 个月内减至 ≤7.5 mg/d","note":"尽量联用免疫抑制剂/生物制剂以减少激素暴露；每次减量前评估 SLEDAI、尿蛋白、补体","renal":"无需调整（水肿时需限钠）","hepatic":"监测血糖、血压、眼压","interact":"与 NSAIDs 合用增加消化道出血；强效 CYP3A4 抑制剂（酮康唑、利托那韦）升高激素暴露"},{"name":"吗替麦考酚酯","dose":"狼疮肾炎诱导 1.5–2 g/d 分 2 次；维持 0.75–1.5 g/d 分 2 次；血液系统/皮肤受累 1–2 g/d","note":"狼疮肾炎诱导与维持的一线选择之一；禁用于妊娠（有致畸性，需避孕，计划妊娠前至少停药 6 周）","renal":"eGFR <30 起始 ≤1 g/d 并监测；严重肾功能不全需减量","hepatic":"重度肝损慎用","interact":"与硫唑嘌呤禁止联用；抑酸药/考来烯胺降低吸收；与阿昔洛韦竞争肾小管分泌"},{"name":"环磷酰胺","dose":"静脉冲击：狼疮肾炎 0.5–0.75 g/m² 体表面积，每 4 周 1 次，共 6 次诱导，或 Euro-Lupus 方案 500 mg 每 2 周 1 次×6 次；严重神经精神狼疮 0.5–1.0 g/m² 每月 1 次；口服 1–2 mg/kg/d 仅用于冲击不可行时","note":"主要毒性为骨髓抑制、膀胱毒性、性腺损伤与感染；冲击前查血常规与肾功能，若 WBC <3.0×10⁹/L 或中性粒细胞 <1.5×10⁹/L 暂缓；充分水化并用美司钠预防出血性膀胱炎；育龄患者考虑 GnRH 激动剂保护卵巢","renal":"eGFR <30 减量 25%–50%（按 CrCl 调整剂量）","hepatic":"重度肝损伤需减量或慎用","interact":"与别嘌醇合用增加骨髓抑制；与华法林增加出血风险；活疫苗禁忌"},{"name":"贝利尤单抗（BLyS 抑制剂）","dose":"10 mg/kg 静脉输注，第 0、14、28 天，之后每 4 周 1 次；或 200 mg 皮下注射每周 1 次","note":"用于高疾病活动度、抗 dsDNA 阳性且补体低、常规治疗应答不佳者；可减少激素用量；用药前筛查结核、乙肝，活动性感染禁用","renal":"无需调整","hepatic":"重度肝损慎用","interact":"活疫苗禁忌；不与其他生物制剂联合使用"},{"name":"泰它西普（BLyS/APRIL 双靶点抑制剂）","dose":"160 mg 皮下注射，每周 1 次","note":"国内获批用于常规治疗应答不佳的活动性 SLE，尤其高活动度合并抗 dsDNA 阳性者；监测免疫球蛋白与感染","renal":"重度肾损慎用","hepatic":"遵说明书","interact":"活疫苗禁忌；避免与其他生物制剂联用"},{"name":"硫唑嘌呤","dose":"1.5–2.5 mg/kg/d 口服（维持治疗或妊娠期替代）","note":"维持治疗首选之一；用药前查 TPMT/NUDT15 基因型或活性；妊娠期可在监护下小剂量使用","renal":"eGFR <30 减至常规剂量 50%","hepatic":"肝功能不全者减量","interact":"与别嘌醇/非布司他合用须减至 25%，否则严重骨髓抑制；与 ACEI、柳氮磺吡啶合用增加骨髓抑制风险"},{"name":"阿尼鲁单抗（I 型干扰素受体抑制剂）","dose":"300 mg 皮下注射，每 4 周 1 次","note":"用于中重度皮肤与关节受累、对标准治疗应答不佳者；国内可及性受限制","renal":"无需调整","hepatic":"遵说明书","interact":"活疫苗禁忌"}],"nonDrug":["肾活检：蛋白尿 ≥0.5 g/24 h 或活动性尿沉渣时进行，依分型决定诱导方案","难治性狼疮肾炎：血浆置换、静脉丙种球蛋白、利妥昔单抗，或进入临床试验","进展至 ESRD 者规划肾脏替代治疗；血液系统受累宜避用引起血细胞减少的药物","妊娠期管理：风湿科与产科联合随访，孕前缓解 ≥6 个月再妊娠"],"life":["严格防晒（SPF50+、遮阳帽），避免光敏药物与诱发复发的感染","接种流感、肺炎链球菌、HPV、乙肝疫苗（活疫苗在免疫抑制期禁用）；接种宜在疾病稳定期","戒烟、控制体重，长期激素者补钙与维生素 D、每年骨密度检查","每 3–6 个月复评 SLEDAI、补体、抗 dsDNA、尿蛋白；计划妊娠者孕前评估抗 SSA/SSB 与抗磷脂抗体"]},"prog":"10 年生存率已升至 90% 以上，但器官损伤累积（肾、神经、心血管）显著影响长期预后；狼疮肾炎进展至 ESRD 者约 10%–20%，合并抗磷脂抗体者血栓风险高。主要死因为感染、狼疮肾炎与心血管事件，规范化达标治疗可显著改善结局。","refs":["2020 中国系统性红斑狼疮诊疗指南（中华医学会风湿病学分会）","2023 EULAR 系统性红斑狼疮管理推荐","2019 EULAR/ACR 系统性红斑狼疮分类标准","2019 EULAR 狼疮肾炎管理推荐"]},{"id":"rh_ss","name":"干燥综合征","aka":["Sjögren's Syndrome","SS","舍格伦综合征"],"rank":2,"basic":{"define":"以泪腺与唾液腺等外分泌腺淋巴细胞浸润、分泌功能减退为特征的慢性自身免疫病，分为原发与继发（合并 SLE、RA 等）两类，可累及腺外器官。","risk":["中年女性（男女比约 9:1）","一级亲属患自身免疫病","抗 SSA/SSB 抗体阳性","丙型肝炎、HTLV-1 感染相关","唇腺灶性淋巴细胞性涎腺炎"],"epi":"我国原发性干燥综合征患病率约 0.3%–0.7%，发病高峰 50 岁左右；抗 SSA 阳性者胎儿先天性心脏传导阻滞风险约 1%–2%。"},"patho":"腺体上皮细胞在病毒等触发下表达自身抗原（Ro/SSA、La/SSB），并作为非专职抗原提呈细胞激活 T 辅助细胞与 B 细胞，形成淋巴滤泡样结构；IFN 通路活化与 BAFF 升高驱动 B 细胞过度活化，产生高球蛋白血症与自身抗体，腺体分泌减少，腺外可形成冷球蛋白血症与黏膜相关淋巴组织（MALT）淋巴瘤。","dx":{"criteria":["2016 ACR/EULAR 原发性干燥综合征分类标准（总分 ≥4 可分类）：唇腺活检灶性淋巴细胞浸润，灶性评分（focus score）≥1 计 3 分","抗 SSA/Ro 抗体阳性计 3 分","角膜染色评分 ≥5（或 van Bijsterveld 评分 ≥4）计 1 分","Schirmer 试验 ≤5 mm/5 min 计 1 分","非刺激全唾液流率 ≤0.1 mL/min 计 1 分","入选条件：至少具备 1 项干燥症状（每日眼干 >3 个月、反复砂砾感、每日需人工泪液 >3 次；或每日口干 >3 个月、反复或持续腮腺肿大、需饮水帮助吞咽干性食物），或 ESSDAI ≥1；排除既往头颈部放疗、丙肝、HIV、结节病、淀粉样变、移植物抗宿主病、IgG4 相关病、用药史","继发性干燥综合征须同时符合另一结缔组织病（SLE、RA、系统性硬化）分类标准"],"workup":["Schirmer 试验、角膜荧光素/丽丝胺绿染色、泪膜破裂时间；非刺激全唾液流率","抗 SSA（Ro52/Ro60）、抗 SSB、ANA、RF（约 50% 阳性）、免疫球蛋白定量（IgG 显著升高）","唇腺活检：≥50 个淋巴细胞聚集为 1 个灶，每 4 mm² 腺组织 ≥1 灶为 focus score ≥1","唾液腺超声（低回声、不均匀、低血流）可作为替代影像","评估腺外受累：血常规（白细胞减少）、补体 C3/C4（下降提示冷球蛋白血症）、冷球蛋白、尿常规与肾功能（远端肾小管酸中毒）、肺 HRCT 与肺功能、肌电图（周围神经病）","每年淋巴结/腮腺检查；腮腺持续肿大、IgG 显著升高或 C4 持续下降者警惕淋巴瘤，必要时 PET-CT 与活检"],"grading":"ESSDAI（0–123 分，分 12 个器官域）：<5 低活动、5–13 中活动、≥14 高活动；ESSDAI ≥1 提示全身活动。合并冷球蛋白血症（Ⅱ型）为独立预后不良因素。"},"ddx":[{"name":"系统性红斑狼疮（rh_sle）","point":"与本类 rh_sle 的鉴别点：SS 以口干眼干、腮腺肿大为主，抗 SSA/SSB 阳性而抗 dsDNA/抗 Sm 阴性，补体多正常；SLE 有蝶形红斑、光敏、浆膜炎、肾小球肾炎，抗 dsDNA 阳性、补体下降。两者可重叠称为继发性干燥综合征。"},{"name":"IgG4 相关性疾病","point":"腮腺、下颌下腺、泪腺无痛性肿大，血清 IgG4 升高、活检见席纹状纤维化与 IgG4 阳性浆细胞浸润，对激素反应迅速。"},{"name":"结节病","point":"双侧肺门淋巴结肿大、皮肤结节、高钙血症，活检见非干酪样肉芽肿，ACE 升高，抗 SSA 阴性。"},{"name":"药物性口干眼干","point":"抗胆碱能药、抗抑郁药、利尿剂、异维 A 酸等引起，用药相关、停药缓解，自身抗体阴性。"},{"name":"丙型肝炎相关干燥综合征","point":"合并 HCV 感染，抗 SSA 阴性或低滴度，冷球蛋白血症常见，需抗病毒治疗。"},{"name":"老年性腺体功能减退","point":"老年人泪液与唾液分泌生理性减少，无腺体肿大、自身抗体阴性、唇腺活检无明显灶性浸润。"}],"tx":{"drug":[{"name":"人工泪液与人工唾液（局部替代）","dose":"按需使用，遵说明书（人工泪液优选不含防腐剂单支装）","note":"干燥症状的一线处理；唾液替代可用羧甲基纤维素、木糖醇含片","renal":"无需调整","hepatic":"无需调整","interact":"无已知显著药物相互作用"},{"name":"环孢素 A 眼用乳剂（0.05%–0.1%）/毛果芸香碱","dose":"环孢素眼用乳剂 1 滴双眼 bid；毛果芸香碱 5 mg 口服 tid（或 4% 滴眼液）","note":"用于中重度干眼；毛果芸香碱可增加唾液与泪液，注意出汗、腹痛、视物模糊","renal":"无需调整","hepatic":"遵说明书","interact":"毛果芸香碱与 β 受体阻滞剂合用心动过缓风险增加"},{"name":"羟氯喹","dose":"200–400 mg/d（≤5 mg/kg 实际体重）","note":"改善关节痛、肌痛、乏力与腮腺肿大，降低高球蛋白血症，可能减少淋巴瘤风险；每 6–12 个月眼科评估，出现视网膜病变立即停药","renal":"eGFR <30 减量或慎用","hepatic":"严重肝功能不全慎用","interact":"增加 QT 延长风险药物叠加；降低 MTX 清除"},{"name":"泼尼松","dose":"轻症不推荐全身激素；腺外受累（间质性肺病、神经病、肾小管酸中毒伴低钾、重度血细胞减少）起始 0.5–1.0 mg/kg/d，遵医嘱逐渐减量","note":"避免长期使用；治疗期间监测骨质疏松、感染与血糖","renal":"无需调整","hepatic":"监测血糖血压","interact":"与 NSAIDs 合用增加消化道出血风险"},{"name":"甲氨蝶呤","dose":"7.5–15 mg 每周 1 次，口服或皮下；叶酸 5 mg/周（MTX 后 24 h）","note":"用于明显关节受累者；起效 8–12 周，每 4–8 周复查血常规与肝肾功能","renal":"eGFR <30 禁用，30–59 减量并监测","hepatic":"ALT/AST >3 倍正常上限禁用；肝病或饮酒者慎用","interact":"复方磺胺/TMP-SMX 联用增加骨髓抑制；NSAIDs 增加肾毒性"},{"name":"利妥昔单抗（抗 CD20）","dose":"375 mg/m² 静脉每周 1 次×4 次，或 1000 mg 第 1、15 天各 1 次","note":"用于重度腺外受累（冷球蛋白血症性血管炎、重度周围神经病、间质性肺病、淋巴瘤）；用药前筛查乙肝与结核，输注前预处理预防输注反应","renal":"无需调整","hepatic":"重度肝损慎用","interact":"活疫苗禁忌；与 MTX 联用增加感染风险"}],"nonDrug":["眼部护理：热敷、睑缘清洁、泪点栓塞改善中重度干眼","口腔护理：含氟牙膏、定期洁牙、刺激唾液（无糖口香糖），每 6 个月口腔检查","腮腺持续肿大或疑诊淋巴瘤者行细针穿刺或切除活检，必要时 PET-CT","间质性肺病者呼吸康复，严重者考虑抗纤维化治疗"],"life":["保持室内湿度、避免空调直吹与长时间屏幕；每日多次少量饮水","戒烟，避免使用加重口干的抗胆碱能药物","定期随访腮腺、淋巴结与甲状腺；抗 SSA 阳性育龄女性妊娠需监测胎儿心脏传导阻滞（18–26 周胎儿心超）","每 6–12 个月复评 ESSDAI、免疫球蛋白与补体"]},"prog":"多数患者为良性慢性病程，总体生存接近正常人群；5%–10% 合并腺外重要器官受累者预后较差。原发性干燥综合征患者淋巴瘤风险为普通人群约 5–15 倍（以 MALT 淋巴瘤为主），腮腺持续肿大、紫癜、冷球蛋白血症、C4 下降、持续高球蛋白血症者为高危。","refs":["2020 中国干燥综合征诊疗指南（中华医学会风湿病学分会）","2016 ACR/EULAR 原发性干燥综合征分类标准","EULAR 原发性干燥综合征管理推荐（2019 更新）"]}]},{"id":"vasculitis_myositis","name":"血管炎与肌病","rank":3,"summary":"血管炎按受累血管大小与 ANCA 状态分类，核心是激素 + 免疫抑制剂诱导缓解、维持治疗与感染防控；炎性肌病强调肌酶/肌炎抗体分型及 ILD、肿瘤筛查；系统性硬化以抗纤维化与血管保护为核心。","compare":[{"diseaseId":"rh_anca","dx":"多系统受累（鼻窦-肺-肾三联征）+ ANCA 阳性（MPO 或 PR3）+ 组织活检小血管坏死性血管炎","key":"老年人 + 肺肾同时受累 + ANCA 阳性，肾活检为寡免疫复合物新月体肾炎"},{"diseaseId":"rh_gca","dx":"≥50 岁新发颞部头痛、颞动脉触痛或搏动减弱、咀嚼跛行，ESR ≥50 mm/h，颞动脉超声晕征或活检见肉芽肿","key":"老年 + 新发头痛 + ESR 显著升高 + 视力威胁，需紧急激素"},{"diseaseId":"rh_dm","dx":"对称性近端肌无力 + CK 升高 + 肌电图肌源性损害 + 肌活检炎性浸润；DM 伴向阳疹、Gottron 征","key":"肌无力 + 肌酶升高 + 肌炎特异性抗体（Mi-2、NXP2、MDA5、TIF1γ）分型"},{"diseaseId":"rh_ssc","dx":"手指皮肤硬化（mRSS 评分）+ Raynaud 现象 + 抗 Scl-70/抗着丝点抗体阳性 + 甲襞毛细血管扩张","key":"皮肤硬化 + Raynaud + 抗 Scl-70（ILD）或抗着丝点（PAH）分型"}],"diseases":[{"id":"rh_anca","name":"ANCA 相关血管炎","aka":["ANCA-associated vasculitis","AAV","肉芽肿性多血管炎","GPA","显微镜下多血管炎","MPA","嗜酸性肉芽肿性多血管炎","EGPA"],"rank":1,"basic":{"define":"以抗中性粒细胞胞浆抗体（ANCA）阳性为特征的一组小血管坏死性血管炎，包括肉芽肿性多血管炎（GPA）、显微镜下多血管炎（MPA）与嗜酸性肉芽肿性多血管炎（EGPA）。","risk":["多数 60–70 岁起病","PR3-ANCA 与 GPA 相关、MPO-ANCA 与 MPA 相关","EGPA 常合并哮喘、嗜酸性粒细胞增多","硅暴露；部分药物（肼屈嗪、丙硫氧嘧啶）可诱导 ANCA 血管炎","地区与民族差异"],"epi":"发病率约 10–20/100 万/年（欧洲），我国 MPA 相对多见，MPO-ANCA 阳性率高于西方；GPA 男女比约 1.5:1，EGPA 略高发于女性。"},"patho":"ANCA 刺激中性粒细胞脱颗粒、释放活性氧与中性粒细胞胞外诱捕网（NETs），导致小血管内皮损伤与坏死性炎症；补体旁路途径（C5a）放大中性粒细胞活化。GPA 以肉芽肿与坏死性炎症（耳鼻咽喉、肺、肾）为主，MPA 以寡免疫复合物坏死性新月体肾炎与肺出血为特征，EGPA 以嗜酸性粒细胞浸润、肉芽肿与哮喘相关。","dx":{"criteria":["GPA（2022 ACR/EULAR，总分 ≥5 分）：鼻出血/结痂/鼻中隔穿孔或鞍鼻、软骨受累、听力下降、巩膜炎、肺结节/空洞/出血、肾小球肾炎、c-ANCA/抗 PR3 阳性、活检肉芽肿或坏死性血管炎","MPA（总分 ≥5 分）：p-ANCA/抗 MPO 阳性、寡免疫复合物肾小球肾炎（新月体为主）、肺泡出血、鼻窦/耳受累、肺间质纤维化","EGPA（总分 ≥6 分）：哮喘、嗜酸性粒细胞 >1×10⁹/L、鼻息肉、肺浸润、周围神经病、活检嗜酸性粒细胞浸润或肉芽肿、c/p-ANCA 阳性","需有组织活检或明确器官受累证据"],"workup":["ANCA 检测（IIF + 抗 PR3/抗 MPO ELISA 联合）；MPO-ANCA 与肾病、肺纤维化关系密切","尿常规 + 尿沉渣 + 24 h 尿蛋白 + 血肌酐；疑肾受累者肾活检（寡免疫复合物新月体肾炎）","胸部 HRCT：结节、空洞、磨玻璃影、肺出血、间质纤维化","耳鼻喉科检查（鼻内镜、鼻窦 CT）；GPA 常见鼻中隔穿孔","支气管镜 + BAL（肺泡出血：血性灌洗液）","血常规（嗜酸性粒细胞）、IgE、ESR/CRP、心电图与肌钙蛋白（心脏受累）；肺/皮肤/神经活检"],"grading":"按 BVAS 评估活动度；EULAR/ERA-EDTA 分层：局限型（无器官威胁）、严重型（器官/生命威胁，如快速进展性肾炎、肺出血、中枢神经受累）、难治型。"},"ddx":[{"name":"巨细胞动脉炎","point":"与本类 rh_gca 的鉴别点：AAV 除大血管外还累及肾小球与肺微血管（血尿、肺泡出血、肺结节/空洞），ANCA 阳性、肾活检示坏死性新月体肾炎；GCA 见于 ≥50 岁、以颅部血管与视力威胁为核心、ESR 显著升高、ANCA 阴性。"},{"name":"抗 GBM 病（Goodpasture 综合征）","point":"肺出血 + 肾衰竭，抗 GBM 抗体阳性（可与 ANCA 双阳性），肾活检见 IgG 沿 GBM 线样沉积；AAV 为寡免疫复合物沉积。"},{"name":"狼疮肾炎","point":"ANA、抗 dsDNA/抗 Sm 阳性、低补体，肾活检见「满堂亮」免疫复合物沉积，区别于 AAV 的寡免疫。"},{"name":"感染性心内膜炎","point":"发热、杂音、血培养阳性、超声见赘生物；可致 ANCA 假阳性与免疫复合物型肾炎。"},{"name":"高嗜酸性粒细胞综合征","point":"持续嗜酸性粒细胞增多伴多器官受累但无哮喘/血管炎，FIP1L1-PDGFRA 融合基因阳性支持，对伊马替尼反应好。"},{"name":"肺孢子菌肺炎/感染性肺病","point":"免疫抑制患者发热、进展性呼吸困难与双肺磨玻璃影，LDH 升高；激素冲击后需常规预防。"}],"tx":{"drug":[{"name":"糖皮质激素（泼尼松）","dose":"严重型 0.5–1 mg/kg/d（最大 60–80 mg/d）起始；脏器威胁（肺出血、RPGN、中枢神经）甲泼尼龙 500–1000 mg/d×3 d 冲击；4–6 周内减至 <15 mg/d，6 个月内减至 ≤5 mg/d","note":"诱导期核心，与利妥昔单抗或环磷酰胺联合；注意高血糖、感染与骨质疏松","renal":"无需调整","hepatic":"监测血糖、血压","interact":"与 NSAIDs 合用增加消化道出血风险"},{"name":"利妥昔单抗","dose":"375 mg/m² 每周 1 次×4 次（或 1000 mg 第 1、15 天各 1 次）","note":"PR3-ANCA/GPA 优先选择，尤其育龄期、需保留生育力者；用药前筛查 HBV（再激活）与结核；维持期可每 6 个月 500–1000 mg 重复","renal":"无需调整","hepatic":"HBV 携带者需预防性抗病毒","interact":"活疫苗禁忌；与硫唑嘌呤等联用增加感染"},{"name":"环磷酰胺","dose":"静脉 500–750 mg/m² 每 3–4 周 1 次（或 15 mg/kg）；口服 2 mg/kg/d；老年与肾功能不全减量","note":"严重器官威胁型诱导可选；监测白细胞（目标 >3.0×10⁹/L）、出血性膀胱炎与膀胱癌风险；累计剂量尽量 ≤10 g","renal":"eGFR <30 减量 25%–50%","hepatic":"严重肝损慎用","interact":"与别嘌醇合用增加骨髓抑制；活疫苗禁忌"},{"name":"甲氨蝶呤","dose":"10–25 mg 口服/皮下，每周 1 次","note":"非严重型或维持期联合；妊娠前后停用；补充叶酸 5 mg/周","renal":"eGFR <30 慎用/禁用","hepatic":"肝酶 >3 倍正常上限停用","interact":"与 TMP-SMX 合用增加骨髓抑制"},{"name":"硫唑嘌呤","dose":"1–2 mg/kg/d（维持期）","note":"维持治疗经典选择；用药前查 TPMT/NUDT15；定期查血常规","renal":"eGFR <30 慎用","hepatic":"严重肝病禁用","interact":"与别嘌醇/非布司他必须减量；与 ACEI 合用可致白细胞减少"},{"name":"美泊利单抗（EGPA）","dose":"100 mg 皮下注射，每 4 周 1 次","note":"嗜酸性粒细胞增多、激素依赖型 EGPA；可减少复发与激素用量；难治性 EGPA 可与利妥昔单抗联合","renal":"无需调整","hepatic":"遵说明书","interact":"活疫苗禁忌"}],"nonDrug":["血浆置换：合并抗 GBM 抗体、肺出血伴严重肾衰竭（Cr >500 μmol/L 或需透析）时考虑","肾脏替代治疗：急性肾损伤需透析者","气道病变：声门下狭窄行球囊扩张/气管切开；鞍鼻整形","诱导缓解 3–6 个月后转入维持治疗 ≥18–24 个月，复发者延长","预防：复方磺胺甲噁唑预防肺孢子菌（尤其激素 + 环磷酰胺）；乙肝与结核预防性治疗"],"life":["戒烟，避免硅尘暴露","每 3 个月监测肾功能、尿检、ANCA、血常规与感染迹象","骨质疏松与心血管风险预防（长期激素）","妊娠：病情稳定 ≥6 个月再计划妊娠，避免环磷酰胺与甲氨蝶呤","灭活疫苗接种；免疫抑制期避免活疫苗"]},"prog":"联合免疫抑制后 5 年生存率约 75%–90%，复发率 30%–50%（PR3-ANCA 更高）；终末期肾病风险约 10%–25%，感染是早期死亡首位原因。","refs":["2021 中国 ANCA 相关血管炎诊断和治疗指南","2022 ACR/EULAR 肉芽肿性多血管炎/显微镜下多血管炎分类标准","2022 ACR/EULAR 嗜酸性肉芽肿性多血管炎分类标准","2022 EULAR 血管炎管理推荐"]},{"id":"rh_gca","name":"巨细胞动脉炎","aka":["Giant Cell Arteritis","GCA","颞动脉炎","Temporal Arteritis"],"rank":2,"basic":{"define":"发生于 ≥50 岁人群、累及主动脉及其主要分支（尤其颅外颈动脉分支）的中大血管肉芽肿性血管炎，最突出表现为新发颞部头痛与视力威胁。","risk":["年龄 ≥50 岁（峰值 70–80 岁）","女性（男女比约 2–3:1）","北欧/白种人遗传背景（HLA-DRB1*04）","合并风湿性多肌痛（约 40%–60%）","吸烟、高血压"],"epi":"≥50 岁人群发病率约 10–50/10 万/年，随年龄显著上升；亚洲人群发病率低于欧美，但我国并不罕见。"},"patho":"树突状细胞识别血管壁抗原后募集 CD4+T 细胞（Th1/Th17），释放 IFN-γ 与 IL-17 激活巨噬细胞形成肉芽肿，IL-6 驱动全身炎症。内膜增生、内弹力膜断裂与血管闭塞导致视神经缺血性病变、脑血管事件；主动脉壁慢性炎症可引起动脉瘤。","dx":{"criteria":["1990 ACR 分类标准（≥3/5 项）：发病年龄 ≥50 岁；新发头痛；颞动脉触痛或搏动减弱（非动脉硬化所致）；ESR ≥50 mm/h；颞动脉活检异常（坏死性动脉炎伴多核巨细胞或肉芽肿）","2022 ACR/EULAR 分类标准（加权计分，总分 ≥6 分）：结合晨僵、突发视力丧失、咀嚼跛行、头皮压痛、超声晕征或活检、单侧/双侧受累等","典型表现：新发颞部头痛、头皮触痛、咀嚼跛行、一过性黑矇或复视","高度怀疑时不等活检结果即启动激素，以免致盲"],"workup":["ESR、CRP 显著升高（ESR 常 ≥50 mm/h，但与严重程度不完全平行）","颞动脉超声：动脉壁「晕征」（低回声环）、受压不变形，敏感性较高","颞动脉活检：金标准，双侧取材（≥2 cm），间隔 >1 cm；激素治疗 2 周内仍可阳性","颞动脉/头部 CTA/MRA 或 PET-CT：评估颅外大血管受累","眼科评估（视野、眼底）；主动脉 CTA/PET 评估主动脉瘤或大血管病变","血常规：正细胞正色素性贫血、血小板升高"],"grading":"无统一分级；按是否存在视力威胁、颅外大血管受累（主动脉瘤/狭窄）与复发风险定义为重型。"},"ddx":[{"name":"ANCA 相关血管炎","point":"与本类 rh_anca 的鉴别点：GCA 为 ≥50 岁、颅部中大血管受累、ANCA 阴性、ESR 显著升高，肾脏受累罕见；AAV 累及小血管，常见肾小球肾炎（血尿、蛋白尿）、肺出血或肺结节，ANCA 阳性。"},{"name":"风湿性多肌痛（PMR）","point":"颈肩及髋部对称性肌痛、晨僵、ESR/CRP 升高，无头痛与视力改变，对泼尼松 ≤15 mg/d 迅速反应；约 15%–20% PMR 合并 GCA，需排查。"},{"name":"偏头痛/紧张性头痛","point":"年轻人多见、发作性头痛伴先兆，ESR/CRP 正常，颞动脉超声无晕征。"},{"name":"颞下颌关节疾患","point":"咀嚼痛限于关节弹响、张口受限，无头皮触痛与动脉搏动异常，ESR 正常。"},{"name":"原发性中枢神经系统血管炎","point":"中青年、卒中样表现，脑脊液异常、MRA 多发节段狭窄，需脑组织活检。"}],"tx":{"drug":[{"name":"糖皮质激素（泼尼松）","dose":"无视力威胁：40–60 mg/d（0.7 mg/kg/d）起始；视力威胁（一过性黑矇、视野缺损）：甲泼尼龙 1000 mg/d×3 d 后 1 mg/kg/d；4 周后逐步减量，6 个月内减至 ≤10 mg/d，2 年内尽量停用","note":"高度怀疑即启动，不必等活检；视力丧失多不可逆，须 24 h 内治疗；减量过快复发率高","renal":"无需调整","hepatic":"监测血糖、血压","interact":"与 NSAIDs 联用增加消化道出血；CYP3A4 抑制剂增加激素暴露"},{"name":"托珠单抗","dose":"162 mg 皮下注射，每周 1 次（或每 2 周 1 次，视病情）","note":"激素依赖或复发、需减少累积激素量者加用；可降低复发与激素累积剂量；用药前筛查结核与乙肝","renal":"无需调整","hepatic":"转氨酶升高者慎用","interact":"活疫苗禁忌；IL-6 阻断可使部分 CYP 底物（如甲氨蝶呤）清除恢复"},{"name":"甲氨蝶呤","dose":"10–15 mg 口服/皮下，每周 1 次（可加至 20–25 mg/周）","note":"激素节约辅助，尤其复发性者；补充叶酸 5 mg/周","renal":"eGFR <30 慎用","hepatic":"肝酶 >3 倍正常上限停用","interact":"与 TMP-SMX 合用增加骨髓抑制"},{"name":"阿司匹林","dose":"75–100 mg qd（无禁忌者低剂量）","note":"用于合并缺血事件或心血管高危者的辅助预防；证据有限，需个体化评估","renal":"严重肾功能不全慎用","hepatic":"活动性肝病禁用","interact":"与抗凝剂、NSAIDs 联用增加出血"}],"nonDrug":["颞动脉受累严重或高度视力威胁：活检后尽快专科治疗，必要时眼科联合","主动脉瘤监测：确诊后 1 年复查 CTA，之后每 2–3 年；主动脉直径 >4.0 cm 需外科评估","心脑血管血栓风险个体化评估与预防","合并 PMR 者物理治疗与康复，维持活动度","患者教育：视力突然变化（黑矇、复视）立即就诊"],"life":["长期激素：补充钙剂 + 维生素 D，监测骨密度；管理血糖与血压","注意感染防控：带状疱疹与肺炎链球菌疫苗（活疫苗在免疫抑制期禁用）","每 3 个月监测 ESR/CRP 与症状，指导激素减量","戒烟与控制心血管危险因素"]},"prog":"激素治疗后症状多在 24–72 h 内明显缓解；约 15%–20% 出现永久视力损害，一旦发生几乎不可逆。大血管受累（主动脉瘤）发生率约 10%–20%。多数治疗 2 年左右可停药，约 40%–60% 出现复发。","refs":["2022 中国巨细胞动脉炎诊断和治疗规范（中华医学会风湿病学分会）","2022 ACR/EULAR 巨细胞动脉炎分类标准","2023 EULAR 大血管炎管理推荐","2018 EULAR 巨细胞动脉炎管理建议"]},{"id":"rh_dm","name":"皮肌炎/多发性肌炎","aka":["Dermatomyositis","Polymyositis","DM","PM","特发性炎性肌病","IIM"],"rank":3,"basic":{"define":"以骨骼肌非化脓性炎症为特征的自身免疫病：皮肌炎（DM）伴典型皮疹，多发性肌炎（PM）无皮疹但肌炎表现相似；两者均可合并间质性肺病，DM 恶性肿瘤风险升高。","risk":["40–60 岁发病（DM 女性多于男性）","恶性肿瘤（DM，尤其抗 TIF1γ/NXP2 阳性者，发病前后 1–3 年风险最高）","间质性肺病（抗 MDA5、抗 SSA 阳性）","家族史与 HLA 易感","紫外线、感染；他汀、免疫检查点抑制剂可诱发"],"epi":"患病率约 5–9/10 万，女性多见（DM 男女比约 2:1）；近年免疫检查点抑制剂相关肌炎发生率约 0.5%–1%。"},"patho":"DM 以补体介导的毛细血管内皮损伤为特征，CD4+T 细胞与 B 细胞沿血管周围浸润，伴肌束周围萎缩；PM 以 CD8+T 细胞克隆性浸润非坏死肌纤维（MHC-Ⅰ 高表达）为特征。肌纤维坏死、再生与纤维化导致近端肌无力；皮肤病变由界面性皮炎与微小血管病变所致。","dx":{"criteria":["对称性近端肌无力（肩胛带、髋部、颈屈肌），数周至数月内进展","肌酶升高：CK、醛缩酶、AST、ALT、LDH（部分 DM 尤其抗 MDA5 型 CK 可正常）","肌电图：低波幅短时限多相电位、纤颤电位（肌源性损害）","肌活检：肌纤维坏死与再生、炎性浸润（DM 为血管周围/肌束周围，PM 为肌内膜 CD8+ 克隆）","特征性皮疹：向阳疹、Gottron 丘疹、披肩征、V 征、甲周红斑","肌炎特异性抗体：抗 Mi-2（经典 DM）、抗 NXP2、抗 TIF1γ（肿瘤相关）、抗 MDA5（快速进展型 ILD）、抗 SRP/抗 HMGCR（坏死性肌病）","2017 EULAR/ACR 分类标准（加权计分，区分 PM、DM、免疫介导坏死性肌病、包涵体肌炎、幼年型）"],"workup":["CK、醛缩酶、LDH、AST/ALT、肌红蛋白","肌炎抗体谱：Mi-2、TIF1γ、NXP2、MDA5、SAE、SRP、HMGCR、Jo-1、PL-7、PL-12、EJ、OJ","肌电图与神经传导（排除神经源性）；大腿 MRI（肌肉水肿、脂肪替代）；肌活检（影像引导更准）","胸部 HRCT 与肺功能：抗 MDA5 者需警惕快速进展型 ILD","心电图、肌钙蛋白、心超（心肌受累）；吞咽评估（咽肌受累）","肿瘤筛查：DM 首选全面筛查（乳腺/盆腔/胸部 CT/胃肠镜），1–3 年内每年复查"],"grading":"按疾病活动评分（MDAAT）或肌力 MMT-8；肌无力按 MRC 分级 0–5 级；2017 EULAR/ACR 标准区分亚型。"},"ddx":[{"name":"系统性硬化","point":"与本类 rh_ssc 的鉴别点：DM/PM 以近端肌无力与肌酶升高为核心、无皮肤硬化，DM 有特征性皮疹（Gottron、向阳疹）；SSc 以手指皮肤硬化 + Raynaud + 抗 Scl-70/抗着丝点阳性为特征，肌无力多为轻度继发。"},{"name":"包涵体肌炎","point":"50 岁以上男性，股四头肌与指屈肌无力（不对称）、远端受累，CK 轻中度升高，肌活检见镶边空泡与 TDP-43 聚集，对激素无效。"},{"name":"他汀/免疫检查点抑制剂相关肌病","point":"用药史明确；他汀肌病 CK 升高而肌力可正常；检查点抑制剂相关肌炎常合并心肌炎或重症肌无力。"},{"name":"内分泌性肌病（甲减、皮质醇增多症）","point":"甲状腺功能或血皮质醇异常，肌酶轻度升高，纠正内分泌后肌力恢复。"},{"name":"运动神经元病","point":"肌电图示神经源性损害、广泛自发电位与肌束震颤，CK 轻度升高，无皮疹。"},{"name":"重症肌无力","point":"波动性易疲劳性无力（眼睑下垂、复视、吞咽），抗 AChR/MuSK 抗体阳性，肌酶与肌电图正常。"}],"tx":{"drug":[{"name":"糖皮质激素（泼尼松）","dose":"诱导 0.5–1 mg/kg/d（最大 60 mg/d），4–8 周后按反应逐步减量；严重吞咽困难、快速进展型 ILD 可甲泼尼龙 500–1000 mg/d×3 d 冲击","note":"PM/DM 首选；警惕激素性肌病（减量后肌力仍差而 CK 下降）","renal":"无需调整","hepatic":"监测血糖、血压","interact":"与 NSAIDs 联用增加消化道并发症"},{"name":"甲氨蝶呤","dose":"15–25 mg 口服/皮下，每周 1 次（起始 7.5–10 mg 逐渐加量）；补充叶酸 5 mg/周","note":"DM 皮肤病变与肌炎均有效，激素节约一线；定期查肝酶与血常规","renal":"eGFR <30 慎用/禁用","hepatic":"肝酶 >3 倍正常上限停用","interact":"与 TMP-SMX 合用增加骨髓抑制"},{"name":"硫唑嘌呤","dose":"1.5–2.5 mg/kg/d","note":"激素节约治疗，合并 ILD 常用；用药前查 TPMT/NUDT15","renal":"eGFR <30 慎用","hepatic":"严重肝病禁用","interact":"与别嘌醇/非布司他需大幅减量"},{"name":"吗替麦考酚酯","dose":"1.0–1.5 g bid（最大 3 g/d）","note":"合并 ILD 或重症者使用；监测血常规与感染","renal":"eGFR <25 减量","hepatic":"重度肝损慎用","interact":"与更昔洛韦竞争肾小管排泄"},{"name":"静脉免疫球蛋白（IVIG）","dose":"2 g/kg，分 2–5 天静脉输注，每 4–6 周 1 次","note":"难治性 DM、严重肌无力伴吞咽障碍、MDA5 型快速进展型 ILD","renal":"肾功能不全慎用（蔗糖稳定剂可致渗透性肾损伤）","hepatic":"严重肝损慎用","interact":"活疫苗需间隔 3 个月以上；可影响血糖监测"},{"name":"利妥昔单抗","dose":"375 mg/m² 每周 1 次×4 次或 1000 mg×2 次，遵说明书","note":"抗 SRP 坏死性肌病、难治性病例；需筛查 HBV 与结核","renal":"无需调整","hepatic":"HBV 携带者需预防性抗病毒","interact":"活疫苗禁忌"},{"name":"托法替布/环孢素 A（MDA5-ILD）","dose":"托法替布 5 mg bid 或环孢素 A 2–4 mg/kg/d 分 2 次（遵说明书与专科意见）","note":"抗 MDA5 阳性快速进展型 ILD 的联合方案，需呼吸科与风湿科共同管理；环孢素监测血药浓度与血压","renal":"环孢素肾功能不全慎用","hepatic":"环孢素肝损者减量","interact":"托法替布受 CYP3A4 抑制剂/诱导剂影响；环孢素避免与酮康唑、地尔硫䓬合用"}],"nonDrug":["物理治疗与康复：渐进式抗阻训练，防止废用性萎缩","吞咽障碍：吞咽评估与言语治疗，必要时鼻饲或经皮胃造瘘","间质性肺病：呼吸科联合管理，终末期评估肺移植","恶性肿瘤筛查与处理：DM 患者 1–3 年内每年筛查；确诊肿瘤按肿瘤科方案","皮肤防护：严格防晒（SPF ≥50），局部激素或钙调神经磷酸酶抑制剂"],"life":["每 1–3 个月评估肌力、CK、皮肤病变与肺功能","长期激素者补充钙剂与维生素 D，监测骨密度","避免诱发药物（他汀、免疫检查点抑制剂慎用）","灭活疫苗接种；免疫抑制期避免活疫苗，注意机会性感染","心理支持与康复支持"]},"prog":"DM/PM 5 年生存率约 70%–80%，10 年约 50%–70%，死亡主因为感染、ILD 与恶性肿瘤。抗 MDA5 型合并快速进展型 ILD 预后较差；抗 TIF1γ/NXP2 与肿瘤相关，需长期筛查。","refs":["2022 中国特发性炎性肌病诊疗指南（中华医学会风湿病学分会）","2017 EULAR/ACR 特发性炎性肌病分类标准","2021 中国结缔组织病相关间质性肺病诊疗指南","2022 ACR/EULAR 特发性炎性肌病分类标准更新"]},{"id":"rh_ssc","name":"系统性硬化","aka":["Systemic Sclerosis","SSc","硬皮病","Scleroderma"],"rank":4,"basic":{"define":"以皮肤与内脏器官纤维化和血管病变为特征的自身免疫病，分局限型（lcSSc，皮肤硬化局限于肘/膝远端）与弥漫型（dcSSc，累及躯干近端），后者进展更快、内脏受累更早。","risk":["20–50 岁起病（男女比约 1:3–8）","硅尘与有机溶剂暴露（煤矿、硅业工人）","抗 Scl-70（拓扑异构酶Ⅰ）与弥漫型及 ILD 相关","抗着丝点抗体与局限型及肺动脉高压相关","抗 RNA 聚合酶Ⅲ 与肾危象相关"],"epi":"患病率约 50–300/百万，女性多见；我国 lcSSc 与 dcSSc 均常见，抗 Scl-70 阳性者 ILD 风险高。"},"patho":"微血管内皮损伤触发内膜增生与血管闭塞（Raynaud、指端溃疡、肺动脉高压、肾危象）；成纤维细胞活化、TGF-β 与 IL-6 驱动细胞外基质沉积，导致皮肤与肺纤维化；同时存在 B/T 细胞自身免疫。早期以炎症为主，晚期以纤维化为主要表现。","dx":{"criteria":["2013 ACR/EULAR 分类标准（总分 ≥9 分）：双手手指近端皮肤硬化（MCP 关节以上）即 9 分，可直接分类","其他条目：手指皮肤硬化（MCP 以上）4 分、指尖硬化接近 PBP 2 分、指尖凹陷性瘢痕 3 分、指端溃疡 2 分、甲襞毛细血管扩张 2 分、肺动脉高压/ILD 2 分、Raynaud 现象 3 分、SSc 相关自身抗体 3 分","需排除肾源性系统性纤维化、粘连性肩关节囊炎、硬化性黏液水肿等"],"workup":["皮肤硬化范围（mRSS 改良 Rodnan 皮肤评分）与近端/远端型分类","自身抗体：抗 Scl-70、抗着丝点、抗 RNA 聚合酶Ⅲ、抗 U3-RNP、抗 PM-Scl","胸部 HRCT + 肺功能（FVC、DLCO）：早期 ILD（多为 NSIP 型）","心超估测肺动脉收缩压（PAH 筛查），必要时右心导管确诊","甲襞毛细血管镜（特征性改变）、指端溃疡评估","肾功能、尿常规与血压（肾危象风险）；食管测压/造影（食管运动障碍）；心脏 MRI（心肌纤维化）"],"grading":"分局限型（lcSSc）与弥漫型（dcSSc）；mRSS 0–51 分评估皮肤厚度；ILD 按 CT 范围（>20% 为显著）与 FVC 分期；PAH 按 2022 ESC/ERS 标准（mPAP >20 mmHg、PVR >2 WU、PAWP ≤15 mmHg）。"},"ddx":[{"name":"皮肌炎/多发性肌炎","point":"与本类 rh_dm 的鉴别点：SSc 以手指皮肤硬化、Raynaud 与抗 Scl-70/抗着丝点阳性为核心，肌酶多正常或轻度升高；DM/PM 以对称性近端肌无力、CK 显著升高与特征性皮疹为主，无明显皮肤硬化。"},{"name":"混合性结缔组织病（MCTD）","point":"抗 U1-RNP 高滴度阳性、手指肿胀但多无真性皮肤硬化，合并 Raynaud、肌炎与 PAH，抗 Scl-70/抗着丝点阴性。"},{"name":"硬化性黏液水肿","point":"伴单克隆丙种球蛋白血症（常为 IgG-λ），皮肤丘疹样硬化与面部浸润，无 Raynaud 与自身抗体。"},{"name":"嗜酸性筋膜炎（舒尔曼综合征）","point":"四肢皮肤硬化呈「橘皮样」、外周血嗜酸性粒细胞增高、高丙种球蛋白血症，筋膜活检见嗜酸性浸润，无 Raynaud 与指端改变。"},{"name":"肾源性系统性纤维化","point":"CKD 4–5 期、钆造影剂暴露史，皮肤硬化对称分布伴丘疹与关节挛缩，无自身抗体与 Raynaud。"}],"tx":{"drug":[{"name":"硝苯地平（Raynaud 现象）","dose":"缓释剂 10–20 mg，每日 1–2 次，按耐受调整；或氨氯地平 5 mg qd","note":"Raynaud 一线；注意低血压、外周水肿与头痛","renal":"无需调整","hepatic":"严重肝损慎用","interact":"CYP3A4 抑制剂（克拉霉素、伊曲康唑）升高药物浓度"},{"name":"波生坦/安立生坦（肺动脉高压）","dose":"波生坦 62.5 mg bid（4 周后 125 mg bid）；安立生坦 5 mg qd（可增至 10 mg qd）——遵说明书","note":"PAH 确诊后使用，需肺动脉高压专科评估；波生坦每月监测肝功能","renal":"无需调整","hepatic":"波生坦中重度肝功不全禁用；转氨酶 >3 倍正常上限停药","interact":"波生坦为 CYP3A4 诱导剂，降低华法林、激素与免疫抑制剂浓度；避免与格列本脲合用"},{"name":"西地那非/他达拉非","dose":"西地那非 20 mg tid（PAH）；他达拉非 20–40 mg qd（遵说明书）","note":"PDE5 抑制剂用于 PAH 及难治性指端溃疡；禁忌与硝酸酯类联用","renal":"eGFR <30 减量","hepatic":"严重肝损慎用","interact":"硝酸酯类药物禁忌（严重低血压）"},{"name":"卡托普利（硬皮病肾危象）","dose":"6.25 mg 起始，逐级加量至血压控制（最大 50 mg tid，遵说明书）","note":"肾危象一线；ACEI 应用后肾危象预后显著改善；需监测肾功能与血钾；避免大剂量激素","renal":"血肌酐升高 30% 以内可耐受，继续观察","hepatic":"严重肝损慎用","interact":"与保钾利尿剂、NSAIDs 合用增加高钾与肾损伤"},{"name":"甲氨蝶呤/吗替麦考酚酯","dose":"甲氨蝶呤 15–25 mg 每周 1 次；吗替麦考酚酯 1.0–1.5 g bid","note":"早期弥漫型皮肤病变与 ILD；MMF 可延缓肺功能下降","renal":"MMF eGFR <25 减量；MTX eGFR <30 慎用","hepatic":"严重肝病禁用","interact":"MTX 与 TMP-SMX 增加骨髓抑制；MMF 与更昔洛韦竞争排泄"},{"name":"环磷酰胺","dose":"600 mg/m² 每月 1 次×6 次（或口服 1–2 mg/kg/d）","note":"重度进展性 ILD 可用；监测血常规与膀胱毒性","renal":"eGFR <30 减量","hepatic":"严重肝损慎用","interact":"与别嘌醇增加骨髓抑制"},{"name":"尼达尼布（ILD）","dose":"150 mg bid 口服，遵说明书","note":"用于 SSc-ILD 延缓 FVC 下降；主要不良反应为腹泻与肝酶升高","renal":"eGFR <30 慎用","hepatic":"中重度肝损减量或禁用","interact":"P-gp 抑制剂（酮康唑、利托那韦）升高暴露；与抗凝剂增加出血"},{"name":"糖皮质激素","dose":"仅用于早期炎症（关节炎、心肌炎、ILD 急性加重）：泼尼松 ≤15 mg/d 或更低，避免大剂量","note":">15 mg/d 与硬皮病肾危象风险升高相关（尤其抗 RNA 聚合酶Ⅲ 阳性），须谨慎","renal":"肾危象高危者尤其避免大剂量","hepatic":"监测血糖、血压","interact":"与 NSAIDs 联用增加消化道出血"}],"nonDrug":["指端溃疡：前列环素类似物（伊洛前列素静脉）、清创与抗感染，严重者交感神经切断术","严重 Raynaud 伴指端坏死：交感神经切断术","PAH：联合靶向治疗（ERA + PDE5i + 前列环素类），评估肺移植","ILD：氧疗与肺康复，终末期评估肺移植","消化道受累：PPI 抑酸、促动力药；小肠细菌过度生长时轮替抗生素"],"life":["严格保暖（手套、避免冷水与寒冷环境），戒烟","每 6–12 个月评估肺功能与心超（PAH 筛查）","自测血压并监测肾功能（肾危象预警：突发高血压、头痛、视力改变）","皮肤护理：保湿、避免外伤，情绪波动可诱发 Raynaud","灭活疫苗接种；长期 PPI 者注意骨质疏松风险"]},"prog":"局限型 10 年生存率约 80%–90%，主要死于 PAH；弥漫型 10 年生存率约 60%–70%，死亡主因为 ILD、肾危象与心脏受累。发病 3 年内的内脏受累是预后关键，抗 Scl-70 阳性者 ILD 进展风险高。","refs":["2022 中国系统性硬化症诊疗指南（中华医学会风湿病学分会）","2013 ACR/EULAR 系统性硬化分类标准","2023 EULAR 系统性硬化管理推荐","2022 ESC/ERS 肺动脉高压诊断与治疗指南"]}]},{"id":"spa_oa","name":"脊柱关节病与退行性关病","rank":4,"summary":"骨关节炎以关节软骨退变为核心，治疗靠运动、减重与按需镇痛，避免长期全身激素；银屑病关节炎与反应性关节炎同属脊柱关节炎范畴，以附着点炎、非对称寡关节炎与 HLA-B27 相关为特征，前者需关注皮损与指趾炎，后者多有前驱感染；纤维肌痛为中枢敏化性疼痛，靠 WPI/SSS 诊断与 C 类药物、运动、认知行为治疗。","compare":[{"diseaseId":"rh_oa","dx":"中老年，负重关节疼痛伴活动后加重、休息缓解，晨僵 <30 分钟，骨性膨大与骨擦音，X 线见关节间隙不对称狭窄、骨赘与软骨下骨硬化","key":"机械性疼痛 + 骨赘与骨硬化，无全身炎症与自身抗体"},{"diseaseId":"rh_psa","dx":"银屑病皮损 + 非对称寡关节炎或指趾炎、附着点炎，可伴骶髂关节与脊柱受累，HLA-B27 约 30%～40% 阳性，RF 与抗 CCP 多阴性","key":"皮损 + 指趾炎（香肠指）+ 附着点炎，抗 CCP 阴性"},{"diseaseId":"rh_rea","dx":"泌尿生殖道或肠道感染后 1～4 周出现非对称下肢寡关节炎，可伴尿道炎、结膜炎或前葡萄膜炎，HLA-B27 约 50%～80% 阳性","key":"前驱感染 + 关节炎 + 尿道炎/结膜炎三联征，HLA-B27 相关"},{"diseaseId":"rh_fm","dx":"广泛疼痛 ≥3 个月，WPI ≥7 且 SSS ≥5，或 WPI 4～6 且 SSS ≥9，伴疲劳、睡眠与认知障碍，炎症指标与影像正常","key":"全身疼痛 + 疲劳与睡眠障碍，化验与影像均正常"}],"diseases":[{"id":"rh_oa","name":"骨关节炎","aka":["OA","Osteoarthritis","退行性关节病","骨性关节炎"],"rank":1,"basic":{"define":"以关节软骨退变、软骨下骨硬化与骨赘形成为特征的慢性关节疾病，可累及关节全部结构。按累及部位分手、膝、髋骨关节炎，另有全身性骨关节炎与继发性骨关节炎。","risk":["年龄 >50 岁、女性绝经后","肥胖（膝 OA 最重要可控因素）","膝关节外伤、半月板或韧带损伤史","长期重复负重劳动、蹲跪作业","遗传易感（手 OA 家族史）与关节发育异常"],"epi":"我国 40 岁以上人群膝关节骨关节炎患病率约 15%～25%，女性高于男性；65 岁以上约半数有影像学膝 OA。膝 OA 为我国致残重要原因。"},"patho":"机械负荷与老化、低度炎症共同致软骨细胞外基质降解与合成失衡，软骨逐渐变薄并出现裂隙；软骨下骨硬化、骨赘形成与滑膜炎症。关节周围肌肉萎缩与本体感觉下降进一步加重生物力学失衡。OA 的本质是全体关节器官病变，而非单纯软骨磨损。","dx":{"criteria":["负重关节疼痛，活动后加重、休息后缓解，晨僵 <30 分钟","关节骨性膨大、骨擦音、活动受限，可伴关节积液","膝 OA 临床标准：膝关节痛 + 年龄 ≥50 岁 + 晨僵 <30 分钟 + 骨擦音 + 骨性膨大，满足其中 3 项可诊断","无全身炎症表现，血沉与 CRP 正常或轻度升高，类风湿因子与抗 CCP 阴性","X 线负重位见关节间隙不对称狭窄、骨赘、软骨下骨硬化与囊性变（Kellgren-Lawrence 分级）"],"workup":["关节 X 线（负重位，膝关节取站立位）","血沉、CRP、类风湿因子、抗 CCP（与类风湿关节炎鉴别）","关节超声评估滑膜增厚与积液，必要时 MRI 看软骨与骨髓水肿","尿酸（痛风鉴别）、抗核抗体（必要时）","关节液检查：非炎症性（白细胞 <2×10⁹/L）"],"grading":"Kellgren-Lawrence 分级：0 级正常；Ⅰ级可疑骨赘；Ⅱ级明确骨赘、间隙正常；Ⅲ级间隙中度狭窄；Ⅳ级间隙消失伴骨硬化。临床按疼痛与功能用 WOMAC 或 Lequesne 指数评估。"},"ddx":[{"name":"银屑病关节炎（rh_psa）","point":"与本类 rh_psa 的鉴别点：PsA 有银屑病皮损或甲改变、指趾炎、附着点炎与骶髂关节受累，炎症指标常升高；OA 为机械性疼痛与骨赘。"},{"name":"反应性关节炎（rh_rea）","point":"与本类 rh_rea 的鉴别点：ReA 有前驱感染、急性非对称下肢寡关节炎与 HLA-B27 相关，起病年轻。"},{"name":"纤维肌痛（rh_fm）","point":"与本类 rh_fm 的鉴别点：纤维肌痛为全身广泛疼痛伴疲劳与睡眠障碍，无关节结构破坏。"},{"name":"类风湿关节炎（rh_ra）","point":"与本科室 rh_ra 的鉴别点：RA 以对称性小关节滑膜炎、晨僵 >1 小时、抗 CCP 阳性为特征；OA 为负重关节、抗 CCP 阴性。"},{"name":"痛风性关节炎","point":"发作性单关节红肿热痛，血尿酸升高、关节液见尿酸盐结晶；OA 为慢性机械性痛。"}],"tx":{"drug":[{"name":"对乙酰氨基酚","dose":"0.5 g 口服，每日不超过 3 g；遵说明书","note":"轻中度疼痛首选，注意肝功能与长期安全性。","renal":"肾功能不全者慎用","hepatic":"严重肝功能不全禁用","interact":"与酒精或其他肝毒性药物合用增加肝损伤"},{"name":"局部非甾体抗炎药（双氯芬酸二乙胺乳胶剂等）","dose":"患处涂抹每日 3～4 次；遵说明书","note":"膝、手 OA 首选外用 NSAIDs，全身不良反应显著低于口服。","renal":"遵说明书","hepatic":"遵说明书","interact":"与口服 NSAIDs 叠加时注意胃肠道风险"},{"name":"口服非甾体抗炎药（塞来昔布、依托考昔等）","dose":"按说明书常规剂量，最短疗程；遵说明书","note":"外用无效或疼痛明显时使用；有消化道、心血管与肾脏风险者评估后使用。","renal":"eGFR <30 者慎用或禁用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、抗血小板药、ACEI/ARB 及利尿剂合用增加出血与肾损伤风险"},{"name":"关节腔注射糖皮质激素","dose":"如复方倍他米松 1 ml 或曲安奈德 40 mg，每次间隔不少于 3 个月；遵说明书","note":"用于膝关节积液疼痛急性加重，短期缓解 4～6 周；每年不超过 3～4 次。","renal":"遵说明书","hepatic":"遵说明书","interact":"与全身激素叠加需注意总剂量"},{"name":"度洛西汀（慢性疼痛）","dose":"起始 30 mg qd，逐渐增至 60 mg qd；遵说明书","note":"用于伴中枢敏化或 OA 慢性疼痛合并抑郁者。","renal":"重度肾功能不全禁用","hepatic":"肝功能不全需减量","interact":"与曲马多等 5-羟色胺能药物合用警惕血清素综合征"}],"nonDrug":["核心治疗：个体化运动疗法（股四头肌力量与有氧训练）、减重、物理治疗与自我管理教育","辅助器具：手杖、护膝、支具；禁用长时间制动","关节腔注射玻璃酸钠：部分患者可短期缓解，不作为常规必须","关节置换：终末期疼痛与功能障碍、保守治疗 3～6 个月无效者行全膝关节或全髋置换","手 OA 可行关节固定与矫形支具"],"life":["控制体重，BMI 降至 25 以下可显著减轻膝负荷","避免长时间蹲跪、爬楼与重体力搬抬，改用低冲击运动（游泳、骑车）","每年评估疼痛与功能，出现关节不稳或明显变形时转诊骨科"]},"prog":"进展缓慢且异质：多数患者症状波动，约 10%～15% 发展为严重疼痛与功能障碍需关节置换。长期规律运动与减重可延缓进展，关节置换后 10 年假体生存率超过 90%。","refs":["《内科学》第 9 版 骨关节炎","中华医学会骨科学分会《骨关节炎诊疗指南（2018 年版）》","中华医学会风湿病学分会《骨关节炎诊断及治疗指南（2010）》"]},{"id":"rh_psa","name":"银屑病关节炎","aka":["PsA","Psoriatic Arthritis","银屑病性关节炎"],"rank":2,"basic":{"define":"与银屑病相关的慢性炎症性脊柱关节炎，可累及外周关节、中轴、附着点与指趾（指趾炎），常伴皮肤与甲病变。临床分非对称寡关节炎型、远端指间关节型、对称性多关节炎型、脊柱关节炎型与残毁型。","risk":["银屑病患者，约 20%～30% 最终发生关节炎","皮肤病变广泛、头皮与甲受累、屈侧银屑病","肥胖、吸烟","HLA-B27（中轴与骶髂受累者）、HLA-Cw6","家族史"],"epi":"我国银屑病患者约 600 万，其中关节炎发生率约 6%～10%；男女比例接近，发病高峰 30～50 岁。约 15% 患者关节炎先于皮肤病变出现。"},"patho":"遗传易感叠加皮肤与关节的机械微创伤、肠道菌群与 IL-23/IL-17 轴活化，Th17 细胞与 TNF-α 驱动滑膜炎、附着点炎与骨侵蚀，同时促角质形成细胞增殖。关节破坏以侵蚀与新生骨并存为特点。","dx":{"criteria":["有银屑病（皮肤或甲）且具备以下至少一项：非对称寡关节炎、指趾炎、附着点炎（跟腱或足底筋膜）、骶髂关节炎或脊柱炎、远端指间关节受累","CASPAR 分类标准：现症银屑病 2 分（病史 1 分，家族史 1 分）、甲改变 1 分、类风湿因子阴性 1 分、指趾炎 1 分、附着点炎 1 分、影像学新骨形成 1 分，总分 ≥3 可分类","类风湿因子与抗 CCP 多阴性，CRP 与血沉可升高","超声或 MRI 见滑膜炎、附着点炎与骨髓水肿"],"workup":["关节与骶髂关节 X 线、超声、必要时 MRI","血沉、CRP；类风湿因子、抗 CCP","HLA-B27（中轴受累者）","皮肤科评估皮损面积（PASI）与甲改变","代谢综合征筛查：血糖、血脂、体重与血压","结核与乙肝筛查（生物制剂前）"],"grading":"关节受累按 66/68 关节计数与 DAPSA 或 MDA 评估；皮肤按 PASI 与 DLQI；中轴受累按 BASDAI 与 ASDAS。功能用 HAQ。"},"ddx":[{"name":"骨关节炎（rh_oa）","point":"与本类 rh_oa 的鉴别点：OA 为负重关节机械性疼痛伴骨赘，无皮损与指趾炎；PsA 有银屑病、附着点炎与骶髂受累。"},{"name":"反应性关节炎（rh_rea）","point":"与本类 rh_rea 的鉴别点：ReA 有前驱感染与尿道炎或结膜炎，皮损为脓溢性皮肤角化病而非典型银屑病。"},{"name":"纤维肌痛（rh_fm）","point":"与本类 rh_fm 的鉴别点：纤维肌痛无炎症与关节破坏，检查正常。"},{"name":"类风湿关节炎（rh_ra）","point":"与本科室 rh_ra 的鉴别点：RA 为对称性小关节滑膜炎伴抗 CCP 阳性，无皮损；PsA 为不对称、有皮损与附着点炎。"},{"name":"强直性脊柱炎（rh_as）","point":"与本科室 rh_as 的鉴别点：AS 以外周关节少受累、以中轴为主；PsA 有皮肤与指甲改变及不对称外周关节炎。"}],"tx":{"drug":[{"name":"甲氨蝶呤","dose":"10～15 mg 每周 1 次口服或皮下，可增至 20～25 mg 每周 1 次；遵说明书","note":"外周多关节受累的一线传统改善病情药；每周补充叶酸 5 mg（非同日）。","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用，定期监测肝酶","interact":"与复方磺胺、非甾体抗炎药合用增加毒性；避免孕期使用"},{"name":"来氟米特","dose":"负荷 100 mg/d×3 天，后 20 mg qd；遵说明书","note":"用于外周关节炎，注意血压、肝酶与脱发；有致畸性，妊娠需停药并考来烯胺洗脱。","renal":"遵说明书","hepatic":"肝功能不全或肝酶 >2 倍正常上限者禁用","interact":"与甲氨蝶呤合用肝毒性叠加"},{"name":"托法替布 / 其他 JAK 抑制剂","dose":"托法替布 5 mg bid 口服；遵说明书","note":"用于传统改善病情药效果不佳者，注意带状疱疹、静脉血栓与心血管事件风险。","renal":"中重度肾功能不全需减量","hepatic":"重度肝功能不全不宜使用","interact":"与生物制剂或强效免疫抑制剂合用增加感染风险"},{"name":"TNF-α 抑制剂（阿达木单抗、依那西普等）","dose":"按说明书固定剂量，皮下注射","note":"中重度外周关节炎、附着点炎或中轴受累且传统治疗失败者；用药前筛查结核与乙肝。","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与阿那白滞素或阿巴西普联合"},{"name":"IL-17A 抑制剂（司库奇尤单抗、依奇珠单抗）","dose":"按说明书固定剂量，皮下注射","note":"对皮损与外周关节均有效；活动性炎症性肠病者慎用。","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他生物制剂联用"},{"name":"IL-23 抑制剂（古塞奇尤单抗等）","dose":"按说明书固定剂量，皮下注射","note":"适合皮肤病变明显者，对关节亦有效。","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他生物制剂联用"},{"name":"塞来昔布 / 双氯芬酸","dose":"按说明书常规剂量，短期使用","note":"用于疼痛与晨僵的辅助控制，不能改变病程。","renal":"eGFR <30 慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药合用增加出血风险"}],"nonDrug":["关节内注射糖皮质激素用于单关节肿胀，不长期反复使用","局部光疗或系统治疗皮肤病，与皮肤科协作","严重畸形或残毁关节可行关节置换或融合术","戒烟、控制体重与代谢危险因素"],"life":["规律随访：每 3～6 个月评估关节计数、PASI 与 CRP","疫苗接种（流感、肺炎链球菌、乙肝）在免疫抑制前完成","避免创伤诱发新发皮损或关节受累（同形反应）"]},"prog":"约 20% 患者出现明显关节破坏与功能丧失。早期使用改善病情药可延缓骨侵蚀，总体预后优于早年报告，但中轴受累与代谢合并症影响远期功能与生存。","refs":["《内科学》第 9 版 银屑病关节炎","中华医学会皮肤性病学分会银屑病专业委员会《中国银屑病诊疗指南（2023 年版）》","中华医学会风湿病学分会《银屑病关节炎诊断及治疗指南（2018）》"]},{"id":"rh_rea","name":"反应性关节炎","aka":["ReA","Reactive Arthritis","赖特综合征","Reiter 综合征"],"rank":3,"basic":{"define":"发生于泌尿生殖道或消化道感染后 1～4 周的急性非化脓性关节炎，属脊柱关节炎范畴，可伴尿道炎、结膜炎、虹膜炎与皮肤黏膜改变。","risk":["HLA-B27 阳性（约 50%～80% 患者）","前驱感染：沙眼衣原体、沙门菌、志贺菌、弯曲菌、耶尔森菌","男性 20～40 岁居多（性传播途径）","HIV 感染者病情更重"],"epi":"我国尚无准确发病率，发达国家发病率约 3～5/10 万；性传播相关者男性多见，肠道感染暴发后可出现聚集病例。"},"patho":"感染后抗原（如衣原体或肠道菌的脂多糖、热休克蛋白）与 HLA-B27 呈递的自身肽交叉反应，激活 CD8+ T 细胞与 IL-17 通路，引起滑膜与附着点炎症；部分患者关节内可检出衣原体 DNA，提示局部持续感染。","dx":{"criteria":["前驱感染（尿道炎、宫颈炎或腹泻）后 1～4 周出现关节炎","以非对称下肢寡关节炎为主，累及膝、踝与足部小关节，可有指趾炎","可伴尿道炎、结膜炎、前葡萄膜炎、口腔溃疡与脓溢性皮肤角化病","HLA-B27 阳性支持诊断，血沉与 CRP 升高，类风湿因子与抗 CCP 阴性","关节液非化脓性（白细胞 2～50×10⁹/L），细菌培养阴性","排除感染性关节炎、痛风与银屑病关节炎"],"workup":["关节 X 线、超声（积液、滑膜增厚、附着点炎）","血沉、CRP、类风湿因子、抗 CCP、HLA-B27","沙眼衣原体核酸检测（尿液或宫颈拭子），粪便培养与肠道病原 PCR","尿酸、抗核抗体","关节液常规、培养与晶体检查","眼科裂隙灯评估葡萄膜炎"],"grading":"按病程分急性（<6 个月）与慢性（≥6 个月）；按受累部位分外周关节炎型与中轴受累型（骶髂关节炎、脊柱炎）。BASDAI 与 ASDAS 用于中轴症状评估。"},"ddx":[{"name":"骨关节炎（rh_oa）","point":"与本类 rh_oa 的鉴别点：OA 为中老年负重关节机械性痛、无前驱感染与HLA-B27 关联。"},{"name":"银屑病关节炎（rh_psa）","point":"与本类 rh_psa 的鉴别点：PsA 有典型银屑病与甲改变；ReA 有前驱感染与尿道炎或结膜炎。"},{"name":"纤维肌痛（rh_fm）","point":"与本类 rh_fm 的鉴别点：纤维肌痛无关节肿胀与炎症指标升高。"},{"name":"强直性脊柱炎（rh_as）","point":"与本科室 rh_as 的鉴别点：AS 为慢性起病的中轴痛、无前驱感染；ReA 起病急、以下肢寡关节炎为主。"},{"name":"感染性关节炎（如淋球菌）","point":"关节液混浊、培养或核酸阳性，全身中毒症状重，需静脉抗感染；ReA 关节液培养阴性。"}],"tx":{"drug":[{"name":"非甾体抗炎药（双氯芬酸、塞来昔布等）","dose":"按说明书常规剂量，疗程 4～8 周；遵说明书","note":"关节炎一线对症治疗，多可显著缓解；症状控制后逐渐减量。","renal":"eGFR <30 慎用","hepatic":"严重肝功能不全禁用","interact":"与抗凝药、ACEI/ARB 及利尿剂合用增加出血与肾损伤风险"},{"name":"多西环素","dose":"100 mg bid 口服，疗程 2～4 周；遵说明书","note":"用于衣原体前驱感染者，可缩短病程并减少复发；肠道感染无需常规抗菌治疗。","renal":"重度肾功能不全需调整","hepatic":"遵说明书","interact":"与抗酸药、钙剂同用降低吸收；与异维A酸合用增加颅压"},{"name":"柳氮磺吡啶","dose":"起始 0.5 g bid，逐渐增至 1.0 g bid；遵说明书","note":"用于 NSAIDs 无效的慢性外周关节炎；用药前查 G6PD，监测血象与肝功能。","renal":"肾功能不全慎用","hepatic":"肝功能不全需监测","interact":"与甲氨蝶呤合用增加肝毒性与骨髓抑制"},{"name":"甲氨蝶呤或来氟米特","dose":"遵说明书，按方案使用","note":"用于持续性外周关节炎，疗程 3～6 个月评估。","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用","interact":"与复方磺胺合用增加毒性"},{"name":"局部糖皮质激素注射","dose":"关节腔注射，遵说明书","note":"用于单关节顽固积液，每年不超过 3～4 次。","renal":"遵说明书","hepatic":"遵说明书","interact":"与全身激素叠加需注意总剂量"}],"nonDrug":["中轴受累或改善病情药无效者可考虑 TNF-α 抑制剂","前葡萄膜炎需眼科局部激素与散瞳治疗，重症全身激素","慢性畸形可行关节矫形或置换","必要时关节腔抽液缓解","筛查并治疗性伴（性传播相关者）"],"life":["注意饮食与饮水卫生，安全性行为可减少复发","约 30%～50% 病情反复或转为慢性，需长期随访","出现眼红、眼痛、畏光立即就诊眼科"]},"prog":"多数患者 3～6 个月内症状缓解，约 30%～50% 发展为慢性或反复发作；HLA-B27 阳性者更易出现中轴受累与骶髂关节炎。前葡萄膜炎可致视力损害，需及时处理。","refs":["《内科学》第 9 版 反应性关节炎","中华医学会风湿病学分会《反应性关节炎诊断及治疗指南（2010）》"]},{"id":"rh_fm","name":"纤维肌痛","aka":["Fibromyalgia","纤维肌痛综合征","FM"],"rank":4,"basic":{"define":"以全身广泛肌肉骨骼疼痛、疲劳、睡眠障碍、认知障碍与情绪异常为特征的慢性中枢敏化性疼痛综合征；无关节炎症与结构破坏，实验室与影像学检查基本正常。","risk":["女性，男女比约 4:1～9:1，高峰 30～60 岁","躯体或心理创伤、手术、感染后诱发","焦虑、抑郁与睡眠障碍","合并类风湿关节炎、系统性红斑狼疮、骨关节炎等慢性疼痛疾病","家族聚集与应激敏感性"],"epi":"全球成人患病率约 2%～4%，我国社区研究约 1%～3%，女性显著高于男性，诊断常被延误 2 年以上。"},"patho":"中枢痛觉处理异常，下行抑制通路功能减弱，导致痛阈降低与痛觉超敏；脑内谷氨酸与 P 物质升高、5-羟色胺与去甲肾上腺素能下行抑制减弱。同时存在自主神经功能紊乱与睡眠浅化，低度神经炎症与心理社会因素共同维持症状。","dx":{"criteria":["广泛疼痛持续 ≥3 个月，累及 5 个区域中至少 4 个","2016 ACR 标准：弥漫疼痛指数 WPI ≥7 且症状严重度 SSS ≥5，或 WPI 4～6 且 SSS ≥9；症状持续 ≥3 个月，且无其他能解释疼痛的疾病","伴随症状：疲劳、睡眠后不解乏、认知障碍（“脑雾”）、头痛、肠易激、焦虑抑郁","血常规、血沉、CRP、肌酶、甲状腺功能、自身抗体与影像一般正常","可用 2011 调查量表自评，Symptom Severity 包括疲劳、睡眠、认知三项各 0～3 分"],"workup":["病史与体格检查（压痛点已非必需，用于辅助）","血常规、血沉、CRP、肌酸激酶、甲状腺功能","自身抗体（ANA、抗 CCP）用于排除合并病","25-羟维生素 D、铁蛋白","睡眠与情绪评估（PHQ-9、GAD-7、PSQI）","必要时多导睡眠监测（疑睡眠呼吸暂停或周期性肢体运动）"],"grading":"按 ACR 2016 的 WPI 与 SSS 组合判定；功能用 FIQR 评分与 6 分钟步行试验评估。严重度分轻度（症状可控、功能基本正常）、中度与重度（明显功能受限）。"},"ddx":[{"name":"骨关节炎（rh_oa）","point":"与本类 rh_oa 的鉴别点：OA 有明确关节骨赘与影像学改变；纤维肌痛影像正常且疼痛弥漫。"},{"name":"银屑病关节炎（rh_psa）","point":"与本类 rh_psa 的鉴别点：PsA 有皮损、关节肿胀与炎症指标升高。"},{"name":"反应性关节炎（rh_rea）","point":"与本类 rh_rea 的鉴别点：ReA 有前驱感染与急性关节肿胀，多可缓解。"},{"name":"类风湿关节炎（rh_ra）","point":"与本科室 rh_ra 的鉴别点：RA 为对称性小关节滑膜炎伴抗 CCP 阳性与 CRP 升高。"},{"name":"甲状腺功能减退与抑郁症","point":"甲减有促甲状腺激素升高与肌酶升高，抑郁以情绪低落为核心且无弥漫疼痛。"}],"tx":{"drug":[{"name":"度洛西汀","dose":"起始 30 mg qd，1～2 周后增至 60 mg qd；遵说明书","note":"一线药物，可改善疼痛与功能；注意恶心、出汗与血压升高。","renal":"重度肾功能不全禁用","hepatic":"肝功能不全需减量","interact":"与曲马多、曲坦类合用警惕血清素综合征"},{"name":"普瑞巴林","dose":"起始 75 mg bid，可增至 150 mg bid；遵说明书","note":"失眠与疼痛明显者适用；注意头晕、嗜睡与水肿，慎与阿片类联用。","renal":"按肌酐清除率减量","hepatic":"遵说明书","interact":"与阿片类、苯二氮卓类合用增加呼吸抑制"},{"name":"米那普仑","dose":"遵说明书，按方案滴定","note":"部分患者可用；与度洛西汀一般不联用。","renal":"遵说明书","hepatic":"遵说明书","interact":"与 5-羟色胺能药物合用警惕血清素综合征"},{"name":"曲马多（短期）","dose":"遵说明书，短期使用","note":"仅在其他药物无效且疼痛严重时短期试用，不推荐长期阿片类治疗。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与 5-羟色胺能药物合用增加癫痫与血清素综合征风险"}],"nonDrug":["运动疗法（有氧、力量与拉伸）是循证证据最强的非药物治疗，需循序渐进而非卧床休息","认知行为治疗与正念减压改善疼痛相关焦虑","睡眠卫生与失眠的认知行为治疗","水中运动、推拿与针灸可作为辅助","多学科疼痛管理，避免反复影像学检查与不必要手术"],"life":["建立稳定作息与适度活动节奏（避免“过劳-废用”循环）","避免长期卧床，鼓励坚持低冲击运动","心理支持与家属教育，减少污名化","每 3～6 个月评估 FIQR 与情绪状态"]},"prog":"为慢性波动性病程，多数患者症状可长期存在，但通过药物与运动结合可显著改善功能与生活质量。纤维肌痛不引起关节破坏或器官损害，预后与早期识别、合理治疗关系密切。","refs":["中华医学会风湿病学分会《纤维肌痛综合征诊断和治疗指南（2024 年版）》","《内科学》第 9 版 风湿性疾病总论","2016 ACR 纤维肌痛诊断标准修订版"]}]},{"id":"ctd_more","name":"其他结缔组织病与血管炎","rank":5,"summary":"结缔组织病重叠综合征以抗体谱组合与最严重器官表型为导向处理，MCTD 以 U1RNP 为主线；抗磷脂综合征以血栓或病理妊娠为诊断支点，三阳性者抗凝强度与随访最严；白塞病以口腔、生殖器溃疡与眼炎为三联，部位特异性治疗；IgG4 相关性疾病易误诊为肿瘤或干燥综合征，组织 IgG4 阳性浆细胞与血清 IgG4 是诊断关键。","compare":[{"diseaseId":"rh_mctd","dx":"有 SLE、SSc、多发性肌炎重叠表现 + 抗 U1RNP 高效价（≥1:1600 或免疫印迹强阳性），常伴雷诺现象、手指肿胀与肺高压","key":"确诊要素是抗 U1RNP 高效价；需随访器官受累演变"},{"diseaseId":"rh_aps","dx":"动脉或静脉血栓，或 3 次连续不明原因流产或病理妊娠，并有抗心磷脂抗体、抗 β2 糖蛋白 I 抗体或狼疮抗凝物中至少 1 项两次阳性（间隔 ≥12 周）","key":"血栓/病理妊娠 + 抗磷脂抗体两次阳性，间隔 12 周"},{"diseaseId":"rh_behcet","dx":"复发性口腔溃疡（每年 ≥3 次）加以下任 2 项：生殖器溃疡、眼炎（前或后葡萄膜炎、视网膜血管炎）、皮肤病变（结节性红斑、假性毛囊炎）或针刺试验阳性","key":"口腔溃疡 + 生殖器溃疡/眼炎，按 2014 国际标准分类"},{"diseaseId":"rh_igg4","dx":"器官弥漫性或局限性肿大（胰腺、唾液腺、眼眶、腹膜后），血清 IgG4 可升高，组织示致密淋巴浆细胞浸润、IgG4+ 浆细胞/IgG 浆细胞 >40% 且 >10 个/高倍视野，伴席纹状纤维化与闭塞性静脉炎","key":"组织病理三联 + 血清 IgG4，需排除肿瘤与感染"}],"diseases":[{"id":"rh_mctd","name":"混合性结缔组织病","aka":["MCTD","Mixed Connective Tissue Disease","Sharp 综合征"],"rank":1,"basic":{"define":"兼有系统性红斑狼疮、系统性硬化症与多发性肌炎临床特征，且血清高效价抗 U1 核糖核蛋白（U1RNP）抗体的重叠综合征；其主要特征是雷诺现象、手指肿胀与肺高压风险。","risk":["女性，男女比约 8:1～15:1","发病高峰 30～50 岁","遗传易感 HLA-DR4、DR2","长期吸烟与粉尘暴露可能加重肺受累"],"epi":"患病率约 1～2/10 万，亚洲人群较西方更常见；我国病例以中年女性为主，肺高压是最主要致死原因。"},"patho":"抗 U1RNP 抗体针对剪接体复合物，与 RNA 结合蛋白形成免疫复合物，激活自身免疫应答并沉积于血管壁与肾小球，产生免疫复合物性肾炎与血管炎；内皮损伤致雷诺现象与肺动脉高压，肌纤维间质炎症产生多发性肌炎表现。","dx":{"criteria":["临床：雷诺现象、手指肿胀（腊肠指）、关节炎或关节痛、肌炎（肌酶升高、肌无力）、食管动力障碍、间质性肺病或肺高压、紫癜或面部红斑","血清学：抗 U1RNP 抗体高效价（≥1:1600 或有明确免疫印迹条带），且抗 Sm 抗体阴性（若抗 Sm 阳性多诊断为 SLE）","高丙种球蛋白血症，抗 dsDNA 与补体多正常或轻度降低","下列 4 项临床主要表现中至少 1 项：指端硬化、肾损害、肺高压、肌炎，并满足上述血清学"],"workup":["抗核抗体谱（ANA、抗 U1RNP、抗 Sm、抗 Scl-70、抗 dsDNA、抗磷脂抗体）","肌酸激酶、醛缩酶、肌电图与肌肉 MRI","心脏超声估测肺动脉收缩压，肺功能与高分辨率 CT","食管钡餐或测压（动力障碍）","尿常规、补体与肾功能","甲襞毛细血管镜"],"grading":"按器官受累与活动度分层：轻度（雷诺现象与关节炎为主）、中度（肌炎、食管受累）、重度（肺高压、间质性肺病、肾损害）。肺高压按 WHO 功能分级评估。"},"ddx":[{"name":"系统性红斑狼疮（rh_sle）","point":"与本科室 rh_sle 的鉴别点：SLE 常有抗 Sm 与抗 dsDNA 阳性、补体下降、明显狼疮肾炎；MCTD 抗 U1RNP 高效价而抗 Sm 阴性、肾损害轻。"},{"name":"系统性硬化症（rh_ssc）","point":"与本科室 rh_ssc 的鉴别点：SSc 有抗 Scl-70 或抗着丝点抗体、皮肤硬指（非肿胀）、食管与肺纤维化；MCTD 皮肤以手指肿胀为主且可逆。"},{"name":"特发性炎性肌病（rh_dm）","point":"与本科室 rh_dm 的鉴别点：肌病以近端肌无力与肌酶升高为核心、抗 Jo-1 等肌炎抗体阳性；MCTD 的肌炎多为轻度且伴雷诺与手指肿胀。"},{"name":"抗磷脂综合征（rh_aps）","point":"与本类 rh_aps 的鉴别点：APS 以血栓与病理妊娠为标志，抗磷脂抗体阳性；MCTD 可合并 APS，但以 U1RNP 为主线。"}],"tx":{"drug":[{"name":"羟氯喹","dose":"200～400 mg/d 口服（按体重 ≤5 mg/kg/d）","note":"基础用药，改善皮肤与关节症状、减少复发；每年查眼底。","renal":"肾功能不全需减量","hepatic":"肝功能不全慎用","interact":"与胺碘酮、莫西沙星等延长 QT 的药物合用需谨慎"},{"name":"泼尼松","dose":"0.5～1 mg/(kg·d)，炎症控制后渐减；遵说明书","note":"用于肌炎、浆膜炎与间质性肺病活动期；避免长期大剂量。","renal":"遵说明书","hepatic":"肝功能不全监测","interact":"与 CYP3A4 抑制剂合用血药浓度升高"},{"name":"甲氨蝶呤","dose":"7.5～15 mg 每周 1 次；遵说明书","note":"用于关节炎与皮肤表现，作为激素减量药物。","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用","interact":"与复方磺胺合用增加毒性"},{"name":"吗替麦考酚酯","dose":"0.5～1.0 g bid 口服；遵说明书","note":"用于间质性肺病或肾损害；有致畸性，育龄女性严格避孕。","renal":"肾功能不全需减量","hepatic":"肝功能不全慎用","interact":"与硫唑嘌呤不可联用；与阿昔洛韦合用血药浓度升高"},{"name":"内皮素受体拮抗剂 / PDE5 抑制剂（肺高压）","dose":"按说明书，例如波生坦 62.5 mg bid 起始、西地那非 20 mg tid","note":"确诊肺动脉高压后联合心内科或呼吸科管理。","renal":"遵说明书","hepatic":"波生坦需监测肝功能","interact":"西地那非禁与硝酸酯类合用"}],"nonDrug":["雷诺现象：保暖、钙通道阻滞剂或前列环素类似物","严重肺高压评估靶向药物联合治疗","食管动力障碍者小餐多次、抬高床头，必要时 PPI","严重关节畸形可行矫形手术"],"life":["戒烟、避免寒冷与情绪应激，注意肢端保暖","每年筛查肺高压（心脏超声、NT-proBNP）、肺功能与肾功能","育龄女性病情稳定 6 个月以上再计划妊娠，妊娠期多学科管理"]},"prog":"异质性大：约 1/3 在多年内演变为明确的 SLE、SSc 或肌病；肺高压是最重要的死亡原因，合并肺高压者 5 年生存约 50%～60%。早期识别与肺高压筛查可改善预后。","refs":["《内科学》第 9 版 混合性结缔组织病","中华医学会风湿病学分会《混合性结缔组织病诊断和治疗指南（2011）》","2023 EULAR 结缔组织病相关肺高压建议"]},{"id":"rh_aps","name":"抗磷脂综合征","aka":["APS","Antiphospholipid Syndrome","抗磷脂抗体综合征"],"rank":2,"basic":{"define":"以反复动静脉血栓与病理妊娠，伴抗磷脂抗体持续阳性为特征的自身免疫性血栓性疾病；可原发或继发于 SLE。少数出现多器官血栓的灾难性抗磷脂综合征（CAPS）。","risk":["女性（尤其 SLE 患者），男女比约 1:3","中青年血栓事件（<50 岁无传统风险因素）","反复流产或晚期胎儿丢失","抗磷脂抗体三阳性（狼疮抗凝物、抗心磷脂抗体、抗 β2 糖蛋白 I 抗体）","感染、手术、停用抗凝、妊娠为诱发血栓事件的因素"],"epi":"一般人群抗磷脂抗体阳性率约 1%～5%，但 APS 发病率约 5/10 万，女性为男性的 3～5 倍；约 30%～40% 的 SLE 患者抗体阳性。"},"patho":"抗体结合 β2 糖蛋白 I 后激活内皮细胞、单核细胞与血小板，促组织因子表达与补体活化，形成促凝状态；同时激活补体损伤胎盘滋养层，导致胎盘梗死与胎儿丢失。抗 β2 糖蛋白 I 抗体还直接抑制纤溶与滋养层细胞。","dx":{"criteria":["临床标准：血管血栓（任意器官动脉、静脉或小血管，需影像或病理证实，浅表静脉血栓除外）；妊娠不良结局（孕 10 周前 ≥3 次连续流产、孕 10 周后 ≥1 次形态正常胎儿死亡、孕 34 周前因子痫前期或胎盘功能不全致早产）","实验室标准：狼疮抗凝物、抗心磷脂抗体（中或高效价 IgG/IgM）、抗 β2 糖蛋白 I 抗体中至少 1 项两次阳性，间隔 ≥12 周","至少满足 1 项临床 + 1 项实验室标准可分类为 APS","CAPS：≥3 个器官血栓在 1 周内相继或同时出现，微血管血栓为主，抗磷脂抗体阳性"],"workup":["狼疮抗凝物（需停用抗凝药后复查，避免假阳性）、抗心磷脂抗体与抗 β2 糖蛋白 I 抗体（间隔 12 周复查）","抗核抗体谱、抗 dsDNA 与补体","血管超声、CT 血管成像或肺动脉 CTA 明确血栓部位","心脏超声（Libman-Sacks 心内膜炎）与肾脏评估","血小板、凝血功能、D-二聚体","妊娠评估：胎盘超声、胎儿生长与羊水"],"grading":"按血栓类型分动脉性与静脉性；按抗体谱分三阳性（风险最高）与单阳性；CAPS 按器官受累严重度与是否有抗凝禁忌分层。"},"ddx":[{"name":"混合性结缔组织病（rh_mctd）","point":"与本类 rh_mctd 的鉴别点：MCTD 以抗 U1RNP 高效价和雷诺现象为主，血栓事件不是核心；MCTD 可合并 APS，需抗体谱区分。"},{"name":"白塞病（rh_behcet）","point":"与本类 rh_behcet 的鉴别点：白塞病有口腔生殖器溃疡与眼炎，静脉血栓多为大静脉并可伴动脉瘤，抗体阴性。"},{"name":"IgG4 相关性疾病（rh_igg4）","point":"与本类 rh_igg4 的鉴别点：IgG4 相关疾病以器官肿大与席纹状纤维化为主，抗磷脂抗体无诊断意义。"},{"name":"SLE（rh_sle）","point":"与本科室 rh_sle 的鉴别点：SLE 可继发 APS，但以抗 dsDNA、抗 Sm 与多系统狼疮表现为核心；APS 需单独评估抗磷脂抗体谱。"},{"name":"遗传性易栓症","point":"如抗凝血酶、蛋白 C/S 缺陷或因子 V Leiden，结合家族史与反复血栓、抗磷脂抗体阴性鉴别。"}],"tx":{"drug":[{"name":"华法林（静脉血栓）","dose":"起始 2.5～5 mg/d，按 INR 调整","note":"APS 静脉血栓首选，首次血栓目标 INR 2.0～3.0；复发性或动脉事件目标 2.5～3.5 或联合抗血小板治疗。APS 在直接口服抗凝药（DOAC）的证据差于华法林，三阳性患者优选华法林。","renal":"重度肾功能不全需加强监测","hepatic":"肝功能不全需加强监测","interact":"与胺碘酮、唑类抗真菌药、大环内酯类合用 INR 升高；与利福平、卡马西平合用降低疗效"},{"name":"低分子肝素（妊娠期）","dose":"依诺肝素 40～60 mg 皮下注射，每日 1～2 次；预防剂量或治疗剂量按指南，遵说明书","note":"妊娠期抗凝首选低分子肝素（华法林有致畸性，DOAC 孕期禁用）；产后可转为口服抗凝并重叠至 INR 达标。","renal":"eGFR <30 需减量或改用普通肝素","hepatic":"遵说明书","interact":"与抗血小板药合用出血风险增加"},{"name":"阿司匹林","dose":"100 mg qd 口服","note":"少量证据支持用于血栓性 APS 的二线或伴动脉风险者；妊娠期合并低分子肝素可预防子痫前期。","renal":"重度肾功能不全慎用","hepatic":"重度肝损伤慎用","interact":"与抗凝药合用出血风险增加"},{"name":"羟氯喹","dose":"200～400 mg/d 口服","note":"用于继发于 SLE 者，有降低血栓复发的观察性证据。","renal":"肾功能不全需减量","hepatic":"遵说明书","interact":"与延长 QT 药物合用需谨慎"},{"name":"利妥昔单抗 / 糖皮质激素 / 血浆置换（CAPS）","dose":"遵说明书，按专科方案","note":"CAPS 需抗凝 + 糖皮质激素 + 血浆置换，必要时加用利妥昔单抗或依库珠单抗。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["血栓性 APS：推荐终身抗凝；首次静脉血栓至少 3 个月后评估复发风险再决定维持治疗","产科 APS：依诺肝素加低剂量阿司匹林，产后继续抗凝至 6～12 周","CAPS：抗凝与糖皮质激素、血浆置换联合，重症可加用依库珠单抗","控制高血压、高脂血症等血管危险因素","避免口服避孕药与吸烟"],"life":["定期复查抗磷脂抗体谱（如前 2 年内每 6～12 个月）","充分了解抗凝药物的监测与出血风险，佩戴抗凝提示卡","计划妊娠提前咨询，妊娠期改为低分子肝素，孕 34 周后注意分娩计划"]},"prog":"血栓复发率较高，尤其三阳性与既往动脉事件者，5 年复发率可达 20%～30%。规范抗凝显著降低复发；CAPS 病死率约 30%，需紧急处理。妊娠联合抗凝后活产率可提高至 70%～80%。","refs":["《内科学》第 9 版 抗磷脂综合征","中华医学会风湿病学分会《抗磷脂综合征诊断和治疗指南（2021 年版）》","2023 ACR/EULAR 抗磷脂综合征分类标准"]},{"id":"rh_behcet","name":"白塞病","aka":["Behçet Disease","Behçet 综合征","贝赫切特病","BD"],"rank":3,"basic":{"define":"以复发性口腔与生殖器溃疡、眼炎与皮肤损害为特征的全身性血管炎，可累及大中血管、消化道与神经系统；沿丝绸之路地区高发，属变异性血管炎。","risk":["我国、土耳其、伊朗、日本及地中海沿岸发病率高","20～40 岁男性更易出现重症（眼炎、神经与血管受累）","HLA-B5（B51）阳性","儿童期或青壮年起病"],"epi":"我国土耳其裔报道患病率达 80～370/10 万，我国发病率低于此但非少见；男女性均可发病，男性以重症器官受累居多。"},"patho":"中性粒细胞过度活化与 Th17 细胞失调介导血管炎，可出现中性粒细胞性血管壁炎症与自身炎症反应；已知与 IL-10（EBV 与肠道感染触发）及 HLA-B51 相关。大小血管均可受累，含动脉瘤与血栓形成。","dx":{"criteria":["复发性口腔溃疡：每年至少 3 次，并经医师观察确认","加上以下至少 2 项：复发性生殖器溃疡（瘢痕性）、眼部病变（前葡萄膜炎、后葡萄膜炎或视网膜血管炎）、皮肤病变（结节性红斑、假性毛囊炎或丘疹脓疱性病变、痤疮样结节）或针刺试验阳性（24～48 小时出现脓疱）","针刺试验阳性或 HLA-B51 支持但非必需","肠白塞需内镜见回盲部溃疡；神经白塞需头颅 MRI 与脑脊液"],"workup":["皮肤黏膜与眼科检查，必要时皮肤活检","针刺试验（无菌针头刺前臂）","血沉、CRP、白细胞与血小板","眼科裂隙灯与眼底检查","肠道受累：肠镜；神经受累：头颅 MRI 与脑脊液","血管评估：下肢与颈部血管超声、CT 或 MR 血管成像","Pathergy 试验与 HLA-B51（辅助）"],"grading":"按器官受累分层：黏膜皮肤型（口腔、生殖器溃疡、结节性红斑）、关节型、眼型、肠型、神经型、血管型。眼炎评分与病情活动度用 BSAS 或 EULAR 活动评分。"},"ddx":[{"name":"混合性结缔组织病（rh_mctd）","point":"与本类 rh_mctd 的鉴别点：MCTD 有抗 U1RNP 高效价与雷诺现象，口腔生殖器溃疡罕见。"},{"name":"抗磷脂综合征（rh_aps）","point":"与本类 rh_aps 的鉴别点：APS 以血栓和病理妊娠为主，抗磷脂抗体阳性；白塞的大静脉血栓常伴口腔与生殖器溃疡。"},{"name":"IgG4 相关性疾病（rh_igg4）","point":"与本类 rh_igg4 的鉴别点：IgG4 相关疾病无复发性溃疡与眼炎，以组织淋巴浆细胞浸润为主。"},{"name":"克罗恩病","point":"伴腹痛、腹泻、肛周病变，肠镜见节段性纵行溃疡与非干酪样肉芽肿；肠白塞以回盲部单发深溃疡、常伴口腔外溃疡。"},{"name":"复发性阿弗他口炎","point":"仅口腔溃疡反复，无生殖器溃疡、眼炎与皮肤病变，针刺试验阴性。"}],"tx":{"drug":[{"name":"秋水仙碱","dose":"0.5～1 mg bid 口服；遵说明书","note":"用于黏膜皮肤病变与关节症状，尤其结节性红斑。","renal":"eGFR <30 需减量","hepatic":"肝功能不全慎用","interact":"与克拉霉素、酮康唑等 CYP3A4 与 P-糖蛋白抑制剂合用增加毒性"},{"name":"沙利度胺","dose":"起始 25～50 mg qd 睡前，可增至 100 mg qd；遵说明书","note":"用于难治性口腔、生殖器溃疡与皮肤病变；有强致畸性，育龄女性须妊娠试验并双重避孕至停药后 4 周。","renal":"肾功能不全需减量","hepatic":"肝功能不全慎用","interact":"与地塞米松合用增加血栓风险；与神经毒性药物合用加重周围神经病"},{"name":"硫唑嘌呤","dose":"2～2.5 mg/(kg·d) 口服；遵说明书","note":"用于眼炎、消化道与神经系统受累的维持治疗；用药前查 TPMT。","renal":"肾功能不全需减量","hepatic":"肝功能不全慎用","interact":"与别嘌醇合用需大幅减量，警惕骨髓抑制"},{"name":"环孢素","dose":"2～5 mg/(kg·d) 分次口服，按血药浓度调整；遵说明书","note":"用于严重眼炎，起效快但肾毒性明显，需监测血药浓度与血压。","renal":"肾毒性，肾功能不全慎用","hepatic":"肝功能不全需减量","interact":"与唑类、钙通道阻滞剂合用浓度升高"},{"name":"TNF-α 抑制剂（英夫利西单抗、阿达木单抗）","dose":"按说明书固定剂量","note":"用于环孢素或硫唑嘌呤无效的眼炎、肠白塞、神经白塞与血管受累；用药前筛查结核与乙肝。","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与其他生物制剂合用"},{"name":"糖皮质激素","dose":"系统重症：泼尼松 1 mg/(kg·d)；眼炎局部可注射；遵说明书","note":"用于重症眼炎、神经白塞与血管型；长期使用需防骨质疏松与感染。","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["眼部：局部糖皮质激素与散瞳，重症联合系统免疫抑制","动脉瘤或大静脉血栓：需血管外科与风湿科协同，血栓首选免疫抑制 + 抗凝，动脉瘤可能需手术或介入","肠白塞：糖皮质激素 + 硫唑嘌呤，狭窄或穿孔者手术","口腔溃疡局部用药（含糖皮质激素糊剂、漱口液）","针刺试验前避免使用免疫抑制"],"life":["口腔卫生与定期牙科检查可减少溃疡诱因","戒烟","眼部受累者每 3～6 个月眼科随访，出现视力下降立即就诊","育龄女性使用沙利度胺期间严格避孕，计划妊娠前需专科评估"]},"prog":"以黏膜皮肤型为主者预后良好，病程反复；眼炎可致失明，肠白塞可穿孔或出血，神经白塞与肺动脉瘤为重症并危及生命。男性与早发病者预后较差，早期识别器官受累可明显改善结局。","refs":["《内科学》第 9 版 白塞病","中华医学会风湿病学分会《白塞病诊断和治疗指南（2010）》","2014 白塞病国际研究组诊断标准"]},{"id":"rh_igg4","name":"IgG4 相关性疾病","aka":["IgG4-RD","IgG4-Related Disease","IgG4 相关疾病"],"rank":4,"basic":{"define":"以受累器官弥漫性或局限性肿大、血清 IgG4 升高与 IgG4+ 浆细胞浸润为特征的纤维炎症性疾病，可累及胰腺、胆管、唾液腺、泪腺、眼眶、腹膜后、淋巴结、肾脏、肺与甲状腺，常以假性肿瘤表现。","risk":["中老年男性多见（胰腺、腹膜后与胆管受累者）","唾液腺与泪腺受累女性比例较高","过敏史与高 IgE 血症常见","亚洲人群报道较多，我国近年诊断增多"],"epi":"我国尚无准确患病率，日本报道约 336/100 万；IgG4 相关胰腺炎约占慢性胰腺炎的 10%，腹膜后纤维化中约半数与 IgG4 相关。"},"patho":"IgG4+ 浆细胞与 Th2 型免疫、调节性 T 细胞（Tfh2、Tfr）扩增致 IgG4 类转换，伴嗜酸性粒细胞浸润；IgG4 半抗体不能激活补体，组织损伤以纤维化为主，形成席纹状纤维化与闭塞性静脉炎。病变可致器官压迫、狭窄与功能衰竭。","dx":{"criteria":["器官肿大或假性肿瘤：胰腺弥漫性肿大、涎腺与泪腺肿胀、眼眶炎性假瘤、腹膜后纤维化、肾小管间质性肾炎","血清 IgG4 升高（>135 mg/dl），但约 20%～30% 患者正常","组织病理：致密淋巴浆细胞浸润、IgG4+ 浆细胞/IgG 浆细胞 >40% 且 >10 个/高倍视野、席纹状纤维化、闭塞性静脉炎","排除恶性肿瘤（胰腺癌、淋巴瘤）、感染与其他自身免疫病（干燥综合征、原发性硬化性胆管炎）","2019 ACR/EULAR 分类标准综合临床、血清学、影像与病理评分"],"workup":["血清 IgG4、IgG、总 IgE、嗜酸性粒细胞计数","受累器官影像：腹部 CT/MRI（胰腺腊肠样肿大、胆管狭窄）、超声或 PET-CT","组织活检与免疫组化（IgG4 与 IgG 双染）","抗核抗体谱、类风湿因子、抗 SSA/SSB（与干燥综合征鉴别）","肾功能与尿蛋白（肾小管间质性肾炎）、肝功能与胆管影像","肿瘤标志物与病理排除恶性肿瘤"],"grading":"按受累器官数与器官损伤程度评估；2019 ACR/EULAR 分类要求至少 1 个器官符合病理或临床影像条目且总分 ≥20。按病程分急性活动期、慢性纤维化期。"},"ddx":[{"name":"混合性结缔组织病（rh_mctd）","point":"与本类 rh_mctd 的鉴别点：MCTD 以抗 U1RNP 与雷诺现象为主，无 IgG4 浆细胞浸润与席纹状纤维化。"},{"name":"抗磷脂综合征（rh_aps）","point":"与本类 rh_aps 的鉴别点：APS 以血栓与抗体阳性为特征，无器官肿大性纤维炎症。"},{"name":"白塞病（rh_behcet）","point":"与本类 rh_behcet 的鉴别点：白塞以溃疡与眼炎为主，无席纹状纤维化。"},{"name":"干燥综合征（rh_ss）","point":"与本科室 rh_ss 的鉴别点：干燥综合征以口干眼干、抗 SSA/SSB 阳性与唇腺灶性淋巴细胞浸润为特征；IgG4 相关疾病有 IgG4+ 浆细胞与纤维化。"},{"name":"胰腺癌与原发性硬化性胆管炎","point":"胰腺癌 CA19-9 多升高、病理见恶性细胞；硬化性胆管炎无 IgG4 浆细胞浸润。"}],"tx":{"drug":[{"name":"泼尼松","dose":"0.6 mg/(kg·d)（常 30～40 mg/d）口服，2～4 周后按反应减量；遵说明书","note":"绝大多数患者一线治疗，可显著缩小病灶并改善器官功能；维持 3 个月至 3 年，减量过快易复发。","renal":"遵说明书","hepatic":"遵说明书","interact":"与 CYP3A4 抑制剂合用浓度升高"},{"name":"利妥昔单抗","dose":"按体表面积 375 mg/m² 每周 1 次×4 次，或 1000 mg 间隔 2 周×2 次；遵说明书","note":"激素依赖、复发或不能耐受激素者的首选二线；警惕乙肝再激活与感染。","renal":"遵说明书","hepatic":"遵说明书","interact":"与免疫抑制剂合用增加感染风险"},{"name":"硫唑嘌呤 / 吗替麦考酚酯","dose":"遵说明书，按方案使用","note":"用于减少激素用量与维持缓解；硫唑嘌呤需查 TPMT。","renal":"肾功能不全需减量","hepatic":"肝功能不全慎用","interact":"硫唑嘌呤与别嘌醇合用需大幅减量"},{"name":"甲氨蝶呤","dose":"7.5～15 mg 每周 1 次；遵说明书","note":"可用于维持治疗，减少复发。","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用","interact":"与复方磺胺合用增加毒性"}],"nonDrug":["梗阻性黄疸或胆管狭窄者行内镜胆管支架（ERCP）缓解，必要时外科引流（PTCD）","腹膜后纤维化致输尿管梗阻者行输尿管支架或肾造瘘","甲状腺受累致功能减退者补充左甲状腺素","手术仅用于诊断或解除压迫，术后复发率高，需激素合并治疗"],"life":["随访监测：每 3～6 个月复查血清 IgG4、影像与受累器官功能","长期激素者补钙与维生素 D、预防骨质疏松与感染","避免将本病误诊为肿瘤而进行不必要的大范围手术"]},"prog":"对糖皮质激素反应良好，多数 2～4 周内病灶缩小；但停药后复发率达 30%～50%，需长期随访。腹膜后纤维化或胆管受累未及时治疗可致肾功能衰竭或胆管硬化。","refs":["中华医学会风湿病学分会《IgG4 相关性疾病诊疗指南（2021 年版）》","《内科学》第 9 版 风湿性疾病总论","2019 ACR/EULAR IgG4 相关性疾病分类标准"]}]},{"id":"vasculitis_more","name":"其他血管炎与自身炎症性疾病","rank":6,"summary":"两类疾病都易被误为感染：结节性多动脉炎（PAN）为中型血管坏死性血管炎，以多系统缺血与微动脉瘤为核心，激素联合环磷酰胺为主；成人斯蒂尔病（AOSD）以高热弛张、皮疹、关节痛与铁蛋白极高为特征，须先排除感染与肿瘤，重型时用 IL-1 或 IL-6 抑制剂。","compare":[{"diseaseId":"rh_pan","dx":"中青年、发热乏力、多系统缺血表现（皮肤结节、周围神经病、腹痛、肾缺血、高血压），血管造影或活检见中型动脉微动脉瘤与坏死性血管炎，ANCA 阴性","key":"中型血管 + 微动脉瘤 + ANCA 阴性；需排除乙肝病毒相关 PAN"},{"diseaseId":"rh_aosd","dx":"弛张热 ≥39 ℃ 伴一过性鲑鱼色皮疹、关节痛与咽痛，铁蛋白显著升高（常 >1000 ng/ml）且糖化铁蛋白 <20%","key":"发热 + 皮疹 + 关节炎三联 + 高铁蛋白合并低糖化铁蛋白；排除感染与淋巴瘤"}],"diseases":[{"id":"rh_pan","name":"结节性多动脉炎（PAN）","aka":["PAN","Polyarteritis nodosa","结节性动脉周围炎","经典结节性多动脉炎"],"rank":1,"basic":{"define":"累及中型及小动脉的坏死性血管炎，无肾小球肾炎及微动脉、毛细血管、微静脉受累。可累及皮肤、周围神经、消化道、肾脏与心脏。与乙肝病毒相关者为 HBV-PAN；另有皮肤型 PAN 仅累及皮肤。儿童期有一种以 CECR1（ADA2）突变相关的 PAN 样血管炎。","risk":["HBV 感染（HBV-PAN 在 PAN 病例中约 10%–30%，我国比例更高）","丙型肝炎与其他病毒感染","川崎病或既往链球菌感染史（儿童）","纤维肌性发育不良等血管结构异常","药物（部分疫苗、青霉胺）与被动免疫制剂"],"epi":"PAN 罕见，年发病率约为每百万人 2–10 例，男性多于女性，发病高峰 40–60 岁。我国 HBV-PAN 占比仍较高。5 年生存率在联合免疫抑制治疗下已由 13% 提升至约 80%，预后不良因素按 FFV 评分（肾功能不全、消化道受累、心肌病、中枢神经受累、年龄 >65 岁）。"},"patho":"免疫复合物在血管壁沉积，激活补体与中性粒细胞，引起血管壁纤维素样坏死及全层炎症，伴内膜增生与血栓形成；修复期纤维化致动脉瘤、狭窄与闭塞。HBV-PAN 由 HBsAg 免疫复合物沉积触发。中型动脉受累产生器官梗死与出血；皮肤、周围神经与小/中动脉丰富器官（肠系膜、肾、心）受累多见。肾损害以肾梗死与肾血管性高血压为主，与 ANCA 血管炎的肾小球肾炎不同。","dx":{"criteria":["临床表现：发热、乏力、体重下降伴多系统缺血 — 皮肤（网状青斑、皮下结节、溃疡）、周围神经（多发性单神经炎）、消化道（腹痛、缺血、出血）、肾（肌酐升高、肾性高血压）、心（心肌缺血）","组织活检：皮肤结节或腓肠神经、肌肉活检可见中型动脉坏死性血管炎","血管造影（肠系膜、肾、肝血管）：串珠样狭窄、微动脉瘤与血管截断","实验室：ANCA 阴性（若有 ANCA 阳性需重新考虑 ANCA 相关血管炎）；ESR 与 CRP 升高，白细胞升高，贫血","HBV/HCV 筛查必须，血清补体可降低","儿童 PAN 需查 CECR1（ADA2）突变"],"workup":["病史与系统查体：皮疹、神经查体、血压、腹部","皮肤或神经/肌肉活检（首选有症状部位）","腹部或全身 CTA 或 MRA：评估微动脉瘤与狭窄","HBV、HCV 与 HIV 筛查","尿常规、肌酐、血压、心电图与心肌标志物","ANCA、抗核抗体、冷球蛋白、补体","胃肠道受累者行腹部 CT 与内镜"],"grading":"五因素评分（FFV）：肾功能不全（肌酐 >140 μmol/L）；消化道受累（出血、穿孔、梗死、胰腺炎等）；心肌病；中枢神经系统受累；年龄 >65 岁。每项 1 分，≥2 分提示 5 年病死率显著升高。儿童 PAN 分为全身型与皮肤型。"},"ddx":[{"name":"成人斯蒂尔病（rh_aosd）","point":"与本类 rh_aosd 的鉴别点：AOSD 为全身炎症（高热、皮疹、关节炎）而无血管狭窄与微动脉瘤，铁蛋白极高；PAN 为血管闭塞性缺血表现。"},{"name":"ANCA 相关血管炎（rheum_3）","point":"与 rheum_3 中 ANCA 相关血管炎的鉴别点：ANCA 阳性并有肾小球肾炎与肺泡出血；PAN 主要累及中型动脉，ANCA 阴性。"},{"name":"巨细胞动脉炎（rheum_3）","point":"大中血管，多 >50 岁、颞动脉压痛与视力障碍，活检见肉芽肿性动脉炎；PAN 多 <50 岁，以皮肤与神经为主。"},{"name":"感染性心内膜炎与脓毒症栓塞","point":"发热伴栓塞表现者需血培养与心脏超声；PAN 无瓣膜赘生物，以血管瘤与血栓为主。"},{"name":"冷球蛋白血症与乙肝相关冷球蛋白血管炎","point":"冷球蛋白阳性、紫癜、关节痛与肾小球肾炎；与 HBV-PAN 需检测冷球蛋白鉴别。"}],"tx":{"drug":[{"name":"泼尼松","dose":"起始 1 mg/kg/日（一般 60 mg/日），最大不超过 80 mg/日；遵说明书","note":"轻型（皮肤型或单系统）可单用激素，2–4 周后逐渐减量；长期维持需评估骨、血糖与感染风险。","renal":"肾功能不全者无需另行减量，但需监测血糖与电解质","hepatic":"遵说明书","interact":"与 CYP3A4 强诱导剂合用降低药效，减量时注意 HPA 轴抑制"},{"name":"环磷酰胺","dose":"口服 2 mg/kg/日或静脉冲击 0.5–0.75 g/m² 每月 1 次；遵说明书","note":"重型、FFV ≥1 或合并严重系统受累者联用；需监测血象、尿常规与膀胱毒性，总累积剂量尽量 <12 g。","renal":"eGFR <30 ml/min 者减量 25%–50%，并注意出血性膀胱炎","hepatic":"肝功能不全者减量","interact":"避免与活疫苗同用；与别嘌醇合用增加骨髓抑制"},{"name":"甲氨蝶呤（轻型或维持期）","dose":"7.5–15 mg 每周 1 次口服或皮下，递增至 20–25 mg；遵说明书","note":"皮肤型或作为激素节省剂，每周同补叶酸 5 mg（非同日）。","renal":"eGFR <30 禁用","hepatic":"肝功能不全慎用","interact":"与复方磺胺、NSAIDs 合用增加毒性；避免孕期使用"},{"name":"恩替卡韦（HBV-PAN 的病毒治疗）","dose":"0.5 mg qd，肾功能不全按 Ccr 调整；遵说明书","note":"HBV-PAN 以抗病毒为核心，激素用于急重症控制，避免免疫抑制加重肝炎；注意是否需联合血浆置换与短程激素。","renal":"按肌酐清除率调整间隔","hepatic":"遵说明书","interact":"与利福平等肝毒性药物合用需监测"},{"name":"托珠单抗（难治性）","dose":"8 mg/kg 每 4 周静脉，或每周 162 mg 皮下；遵说明书","note":"部分难治性或多复发者可选，需筛查结核与肝炎；不可与活疫苗同时使用。","renal":"肾功能不全无需调整","hepatic":"肝功能异常者慎用","interact":"与 CYP 底物合用可能影响代谢；与 IL-1 抑制剂不常规联用"}],"nonDrug":["血浆置换：用于重症 HBV-PAN 或严重内脏缺血，次数 7–9 次，每次 60 ml/kg，需联合抗病毒","手术：消化道出血、穿孔或肠缺血需急诊手术；肾动脉狭窄致药物难以控制的高血压可考虑血运重建","中西医结合与康复训练：周围神经病残留者需理疗与神经营养","合并动脉瘤者需血管外科随访与介入栓塞，避免破裂"],"life":["戒酒戒烟、控制血压与血糖，降低血管事件风险","激素治疗期间补钙与维生素 D，监测骨密度与白内障","每 3–6 个月复查 ESR、CRP、尿常规、肌酐与血压，评估系统受累与复发","HBV-PAN 者长期抗病毒随访 HBV DNA 与肝功能，禁止擅自停用免疫抑制"]},"prog":"联合糖皮质激素与环磷酰胺使 5 年生存率提升至 70%–80%。FFV 评分 ≥2 者 5 年病死率可达 30%–40%，死亡主因为肠系膜缺血、心衰与中枢受累。约 30%–50% 缓解后复发，HBV-PAN 复发较少；残留周围神经病常见。","refs":["中华医学会风湿病学分会《结节性多动脉炎诊断和治疗指南（2021）》","中华医学会风湿病学分会《血管炎诊断与治疗指南》","ACR/EULAR 2022 Classification Criteria for Polyarteritis Nodosa","《内科学》第 9 版 结节性多动脉炎"]},{"id":"rh_aosd","name":"成人斯蒂尔病（AOSD）","aka":["AOSD","Adult-onset Still disease","成人 Still 病","成人起病 Still 病","变应性亚败血症"],"rank":2,"basic":{"define":"成年人（一般 ≥16 岁）起病的系统性自身炎症性疾病，与儿童全身型幼年特发性关节炎（sJIA）同一疾病谱。以高热、一过性皮疹、关节炎/关节痛、淋巴结与肝脾增大为主要表现，伴铁蛋白显著升高。","risk":["发病年龄多在 16–35 岁，女性略多","感染后（扁桃体炎、上呼吸道感染）诱发","HLA 相关等遗传易感","属于自身炎症谱系（与 sJIA 及噬血细胞综合征相关）"],"epi":"我国 AOSD 患病率约每 10 万人 1–3 例，占风湿免疫门诊发热待查的 10%–20%。AOSD 可演变为巨噬细胞活化综合征（MAS），发生率约 12%–15%，病死率高。"},"patho":"先天免疫过度活化是核心：中性粒细胞、单核细胞与 CD8+ T 细胞释放 IL-1β、IL-6、IL-18 与 TNF-α，形成自身炎症性级联。IL-1β 驱动发热、皮疹与关节炎症，IL-6 参与急性期反应。高铁蛋白为其标志之一，因巨噬细胞与铁蛋白转录被促炎因子增强，且糖基化水平降低（低糖化铁蛋白）。MAS 时巨噬细胞与 T 细胞异常活化致血细胞减少、肝酶升高与高甘油三酯。","dx":{"criteria":["发热：弛张热 ≥39 ℃，每日波动幅度大，热退时体温可正常，热型持续 ≥1 周","皮疹：随发热出现的一过性鲑鱼色或橙红色斑疹（多在前胸、躯干），热退即消","关节痛或关节炎：多关节炎可致破坏，膝、腕为常见","其他：咽痛、淋巴结增大、肝脾增大、胸膜炎或心包炎","实验室：铁蛋白显著升高（常 >1000 ng/ml 或 >正常上限 5 倍），CRP 与 ESR 升高，白细胞 ≥10×10⁹/L（中性粒细胞为主），肝酶升高，糖化铁蛋白 <20%（或 ALT/AST 正常时铁蛋白比例 ≤20%）","Yamaguchi 标准：主要 4 项（发热、关节痛 ≥2 周、典型皮疹、白细胞升高）与次要 4 项（咽痛、淋巴结或脾大、肝功异常、类风湿因子与 ANA 阴性），符合 ≥5 项且含 ≥2 项主要，并排除感染、肿瘤与其他风湿病","成人 Still 病需满足年龄 ≥16 岁"],"workup":["血常规、ESR、CRP、铁蛋白（必要时查糖化铁蛋白）","肝功能、肌酶、凝血功能与血培养","ANA、类风湿因子、抗 CCP、ANCA（多为阴性）；补体","感染筛查：结核、EBV、CMV、肝炎病毒、血培养与尿培养","肿瘤筛查：乳酸脱氢酶、胸腹盆腔 CT 与淋巴结超声，必要时 PET-CT","关节 X 线与超声；有破坏者评估 ERA","MAS 评估：血细胞减少、甘油三酯升高、纤维蛋白原降低、NK 细胞活性与 sCD25"],"grading":"Yamaguchi 与 Fautrel 分类标准用于诊断。病情评估：热评分、关节与系统受累数量；Pouchot 活动评分；MAS 按 HLH-2004 标准评估（发热、脾大、血细胞减少、高甘油三酯/低纤维蛋白原、铁蛋白、sCD25、NK 细胞活性）。分单一系统型（全身型、关节型）与混合型。"},"ddx":[{"name":"结节性多动脉炎（rh_pan）","point":"与本类 rh_pan 的鉴别点：PAN 以中型血管缺血、皮疹结节与神经病变为主，血管造影见微动脉瘤；AOSD 无血管病变、皮疹随热出现而热退消失。"},{"name":"系统性红斑狼疮（rheum_2）","point":"与 rheum_2 中 SLE 的鉴别点：SLE 有 ANA 与抗 dsDNA 阳性、多浆膜腔炎与肾脏受累；AOSD 自身抗体阴性。"},{"name":"感染（败血症与病毒感染）","point":"高热伴白细胞升高需血培养与影像；AOSD 血培养阴性、对激素迅速反应而抗菌无效。"},{"name":"淋巴瘤与其他恶性肿瘤相关发热","point":"老年起病、LDH 显著升高、淋巴结持续增大者需活检；AOSD 的皮疹与铁蛋白模式可助鉴别。"},{"name":"类风湿关节炎与多关节起病者","point":"与 rheum_1 中 RA 的鉴别点：RA 为对称性小关节滑膜炎伴抗 CCP 阳性；AOSD 为高热与皮疹起病伴铁蛋白升高。"}],"tx":{"drug":[{"name":"非甾体抗炎药（轻型）","dose":"如布洛芬按说明书剂量分次服，短期使用；遵说明书","note":"仅用于轻度发热与关节痛，不能阻止关节破坏；长期使用注意胃肠道与肾脏。","renal":"肾功能不全禁用或减量","hepatic":"肝功能异常者慎用","interact":"与激素、抗凝药合用增加消化道出血"},{"name":"泼尼松","dose":"0.5–1 mg/kg/日，一般 0.5–1 mg/kg，最大 60 mg；遵说明书","note":"中重型一线；起效快（数日内退热），需评估激素相关并发症与结核筛查。","renal":"遵说明书","hepatic":"遵说明书","interact":"利福平降低疗效；与 IL-6 抑制剂合用注意感染"},{"name":"甲氨蝶呤","dose":"7.5–15 mg 每周 1 次，可增至 20–25 mg；遵说明书","note":"激素节省剂，用于关节炎或需长期控制者；每周补叶酸，禁孕龄女性在孕期使用。","renal":"eGFR <30 禁用","hepatic":"肝功能明显异常时减量","interact":"与复方磺胺、非甾体抗炎药合用增加毒性"},{"name":"阿那白滞素（IL-1 受体拮抗剂）","dose":"100 mg 皮下 qd，必要时可增至 100 mg q12h；遵说明书","note":"系统性炎症显著或合并 MAS 高风险时首选，起效迅速；注射部位反应常见。","renal":"重度肾功能不全按说明书延长间隔","hepatic":"遵说明书","interact":"与活疫苗不同时使用；与 TNF 抑制剂不常规联合"},{"name":"托珠单抗（IL-6 受体拮抗剂）","dose":"8 mg/kg 每 4 周静脉，或每周 162 mg 皮下；遵说明书","note":"用于关节受累或难治性全身症状，可快速降铁蛋白与 CRP；治疗前筛查结核与肝炎。","renal":"肾功能不全无需调整","hepatic":"肝酶升高者慎用，监测肝功","interact":"与甲氨蝶呤合用监测肝酶；与活疫苗避免同用"},{"name":"环孢素 A（MAS）","dose":"2–4 mg/kg/日，分次口服，按血药浓度调整；遵说明书","note":"用于巨噬细胞活化综合征，常与激素、IL-1 抑制剂联用；监测血压、肾功与血药浓度。","renal":"肾功能不全减量，避免与肾毒性药合用","hepatic":"肝功能不全者减量","interact":"与唑类抗真菌药、地尔硫卓合用升高浓度；升高他汀血药浓度"}],"nonDrug":["轻型：非甾体抗炎药 + 关节腔注射或物理治疗；密切随访","中重型：激素联合甲氨蝶呤；2–4 周无效或合并内脏受累时加用 IL-1/IL-6 抑制剂","MAS：大剂量激素冲击 + 环孢素或 IL-1 抑制剂，必要时血浆置换与 IVIG","严重关节破坏：随访 ERO/ERA，必要时关节置换","发热待查阶段不得随意长期使用激素而掩盖感染或肿瘤，需在评估后规范使用"],"life":["规律随访：前 6 个月每月复查血常规、ESR、CRP、铁蛋白、肝功与肾功能","生物制剂治疗前筛查结核（T-SPOT）、乙肝与丙肝，治疗中每年复查","避免感染：发热时及时评估，必要时暂停免疫抑制","激素减量需缓慢，预防肾上腺皮质功能不全；补充钙与维生素 D"]},"prog":"约 1/3 患者呈自限性单相病程，1/3 表现为间歇复发，1/3 呈慢性持续型；合并 MAS 者病死率 10%–20%。多数经规范治疗可控制，关节破坏见于约 1/3 慢性关节炎患者。IL-1/IL-6 抑制剂使用后严重系统发作的控制率显著提高。","refs":["中华医学会风湿病学分会《成人斯蒂尔病诊断和治疗指南（2021）》","ACR 2023 Guideline for the Treatment of Adult Still Disease","《内科学》第 9 版 成人斯蒂尔病","Yamaguchi 分类标准（1992）与 Fautrel 标准"]}]},{"id":"rp","name":"复发性多软骨炎","rank":41,"summary":"复发性多软骨炎以耳廓、鼻与气道软骨的反复无菌性炎症为特征，按 McAdam 标准临床诊断；轻症用激素或氨苯砜，气道与心血管受累需激素冲击联合免疫抑制剂，并始终警惕喉气管塌陷所致的窒息。","compare":[],"diseases":[{"id":"rh_rp","name":"复发性多软骨炎","aka":["Relapsing polychondritis","RP","复发性多发性软骨炎","复发性软骨炎"],"rank":1,"basic":{"define":"复发性多软骨炎（RP）是一种罕见的免疫介导的全身性软骨炎症性疾病，累及耳、鼻、喉气管、关节、眼与心血管系统，呈反复发作与缓解，可致气道塌陷、鞍鼻与主动脉瘤。","risk":["发病高峰 40–50 岁，男女比例相近","合并其他自身免疫病（血管炎、SLE、RA、干燥综合征、炎症性肠病）约 30%","合并骨髓增生异常综合征或其他血液肿瘤约 10%–15%","HLA-DR4 阳性者风险升高","反复耳廓外伤、穿孔或耳部感染可为诱因","吸烟与气道受累进展相关"],"epi":"发病率约 0.35–3.5/百万/年，患病率约 4–5/百万；我国尚无确切流行病学数据，以个案与单中心队列报道为主。诊断时平均年龄 40–50 岁，儿童少见。"},"patho":"针对Ⅱ型胶原、matrilin-1 等软骨抗原的自身免疫反应介导，T 细胞与自身抗体浸润软骨，基质金属蛋白酶与弹性蛋白酶降解软骨基质，软骨失去弹性与支撑。耳廓与鼻中隔透明软骨受累致耳廓红肿变形与鞍鼻；气管支气管软骨环破坏致气道软化、塌陷与窒息；心血管受累为主动脉中膜弹性纤维破坏，致主动脉瘤与瓣膜反流；眼部以巩膜炎、葡萄膜炎常见。","dx":{"criteria":["双侧耳廓软骨炎：反复红肿、疼痛与压痛，耳垂不受累（耳垂无软骨，为本病特征）","非侵蚀性、血清阴性多关节炎：掌指、近端指间与膝关节为主，RF 与抗 CCP 多阴性","鼻软骨炎：鼻梁疼痛与压痛，反复发作后出现鞍鼻畸形","眼部炎症：结膜炎、角膜炎、巩膜炎、葡萄膜炎，可致视力下降","呼吸道软骨炎：声嘶、喘鸣、干咳、呼吸困难与颈部压痛，肺功能见吸气相流速-容积环平坦","耳蜗或前庭损害：感音神经性聋、耳鸣与眩晕","McAdam 标准：上述 6 条中满足 ≥3 条即可临床诊断，不需组织学证据；Michet 改良标准为活检证实加上 ≥1 条表现，或满足 ≥2 条且对激素/氨苯砜治疗有反应","实验室与影像：活动期 ESR、CRP 升高（80% 以上），轻中度贫血、白细胞升高，RF/ANA 多阴性，抗Ⅱ型胶原抗体约 30%–50% 阳性；气管壁增厚、钙化与主动脉根部扩张支持诊断"],"workup":["耳鼻喉检查：耳廓（注意耳垂豁免）、鼻梁塌陷、喉镜与支气管镜评估气道狭窄与软骨环消失","肺功能（流速-容积环）与颈胸部 CT：气管壁增厚、钙化、气道狭窄与软化","心脏超声与主动脉 CTA：基线及每年评估主动脉根部直径与瓣膜反流","眼科裂隙灯（巩膜炎、葡萄膜炎）与纯音测听（感音神经性聋）","实验室：ESR、CRP、血常规、ANA、ANCA、RF、抗 CCP、抗Ⅱ型胶原抗体，排除血管炎与感染；贫血或血细胞减少者行骨髓穿刺/活检排除 MDS","活检：耳廓或鼻软骨（避免气道活检致水肿），病理见软骨周围淋巴细胞浸润、软骨基质嗜碱性减低"],"grading":"按受累范围分局限型（耳、鼻、关节）与全身型（气道、心血管、神经、皮肤）；按病情分轻（皮肤软骨、关节）、中（眼、内耳、全身炎症）、重（喉气管/支气管受累、心血管受累、神经系统受累）。气道受累按狭窄程度（<50%、50%–70%、>70%）与是否为动力性塌陷分层，用于决定支架或气管切开。"},"ddx":[{"name":"肉芽肿性多血管炎（rh_anca）","point":"与本类（复发性多软骨炎）邻类疾病 rh_anca 的鉴别点：GPA 有鞍鼻、鼻窦炎、肺部结节或空洞、肾脏受累与 PR3-ANCA 阳性，活检见坏死性肉芽肿性血管炎；RP 以耳廓软骨炎突出、ANCA 多阴性、无肺部空洞。"},{"name":"感染性耳廓软骨炎","point":"多为单侧，有外伤、穿孔或手术史，铜绿假单胞菌常见，伴脓性分泌物与波动感；抗生素联合引流有效，RP 为双侧反复无菌性炎症。"},{"name":"耳廓冻伤或外伤性耳廓血肿","point":"有明确寒冷或外伤史，单次发作，无全身炎症指标升高与软骨抗体。"},{"name":"Cogan 综合征","point":"非梅毒性间质性角膜炎伴前庭听觉症状，可合并主动脉炎；但无耳廓与鼻软骨炎，可与 RP 重叠需长期随访。"},{"name":"强直性脊柱炎或反应性关节炎","point":"中轴或下肢寡关节炎、HLA-B27 阳性、骶髂关节炎；无软骨炎与鞍鼻。"},{"name":"梅毒性鼻中隔穿孔或麻风","point":"梅毒血清学阳性；麻风有感觉丧失性皮损与抗酸杆菌；RP 血清学阴性且伴多部位软骨炎。"},{"name":"淋巴瘤或骨髓增生异常综合征相关软骨炎","point":"顽固贫血、血细胞减少、淋巴结肿大与全身消耗，需骨髓检查；RP 合并 MDS 时二者可并存，不能仅满足于 RP 诊断。"},{"name":"结节性多动脉炎（rh_pan）","point":"中血管炎，皮肤结节、多单神经炎、肾与肠缺血，ANCA 阴性；无耳鼻软骨炎与气道软骨破坏。"}],"tx":{"drug":[{"name":"泼尼松","dose":"0.5–1 mg/(kg·d) 口服（通常 40–60 mg/日），活动控制后每 2–4 周减 5–10 mg，维持 5–10 mg/日","note":"一线治疗；气道受累者初始按 1 mg/kg 足量，减量过快易复发；长期使用需预防骨质疏松与肺孢子菌肺炎（泼尼松 >20 mg/日超过 4 周）。","renal":"遵说明书","hepatic":"严重肝病者需经肝转化，改用甲泼尼龙","interact":"与 NSAIDs 叠加消化道出血；CYP3A4 抑制剂（酮康唑）升高浓度；降低降糖药疗效；利福平、苯妥英加速代谢"},{"name":"甲泼尼龙（冲击）","dose":"500–1000 mg 静脉滴注 qd，连用 3 天，随后改为口服泼尼松","note":"用于气道塌陷、威胁视力的巩膜炎、主动脉炎或神经系统受累；监测血糖、血压、感染与心律失常。","renal":"遵说明书","hepatic":"无需肝内转化，可直接使用","interact":"与利尿剂合用加重低钾；与 CYP3A4 抑制剂升高浓度"},{"name":"甲氨蝶呤","dose":"7.5–15 mg 口服或皮下注射，每周 1 次；次日补叶酸 5 mg（非同日）","note":"激素助减剂，适用于关节、皮肤与耳鼻受累；起效需 6–8 周，用药前查肝肾功能与血常规。","renal":"CrCl<30 禁用或显著减量；透析者避免使用","hepatic":"肝病或酗酒者禁用，定期监测肝酶","interact":"与甲氧苄啶等叶酸拮抗剂叠加骨髓抑制；与生物制剂合用增加感染风险；NSAIDs 可能升高血药浓度"},{"name":"硫唑嘌呤","dose":"1–2 mg/(kg·d) 口服，起效 6–12 周","note":"激素助减剂；用药前检测 TPMT 或 NUDT15 基因，缺陷者骨髓抑制风险高。","renal":"肾功能不全减量","hepatic":"肝损者慎用并监测肝酶","interact":"与别嘌醇、非布司他合用显著增加骨髓抑制（硫唑嘌呤减至 1/4）；与 ACEI 合用可加重白细胞减少"},{"name":"环磷酰胺","dose":"口服 1–2 mg/(kg·d)，或静脉 500–750 mg/m² 每 4 周；重症气道、心血管或神经系统受累时使用","note":"累积剂量与膀胱毒性、骨髓抑制和性腺毒性相关；监测血常规、尿常规，鼓励饮水。","renal":"CrCl<30 减量 25%–50%","hepatic":"肝损者慎用","interact":"与别嘌醇合用增加骨髓抑制；与华法林合用改变 INR"},{"name":"托珠单抗","dose":"8 mg/kg 静脉滴注每 4 周，或 162 mg 皮下注射每周 1 次","note":"IL-6 受体拮抗剂，用于难治性气道受累（病例系列支持）；用药前筛查结核与乙肝，监测感染与中性粒细胞。","renal":"无需调整","hepatic":"重度肝损不推荐","interact":"不与其他 IL-6/IL-1 拮抗剂联用；炎症消退后 CYP450 底物（华法林、辛伐他汀）代谢恢复，需监测"},{"name":"氨苯砜","dose":"50 mg qd 起，1 周后增至 100 mg qd（轻症或皮肤软骨受累）","note":"轻症可单用或作为激素助减剂；用药前查 G6PD，缺乏者禁用（溶血风险）。","renal":"CrCl<30 减量或隔日给药","hepatic":"肝损者慎用","interact":"与甲氧苄啶合用增加溶血与高铁血红蛋白血症；利福平降低血药浓度"}],"nonDrug":["气道受累：支气管镜评估狭窄与软化程度；出现喘鸣、呼吸困难或狭窄 >50% 者，必要时气管切开或置入硅酮/金属支架（支架并发症高，需谨慎选择）","急性窒息：立即气管插管或环甲膜切开，不能延误；插管时避免损伤软化气道","主动脉瘤：直径 >50 mm 或年增长 >5 mm 行外科或腔内修复；主动脉瓣反流者行瓣膜置换","耳鼻畸形：病情稳定 6–12 个月后行鞍鼻鼻重建（自体肋软骨）或耳廓整形，活动期不宜手术","血浆置换或免疫吸附：重症难治性气道、主动脉炎或视神经炎可联合使用","多学科团队：风湿科、耳鼻喉科、呼吸科、心外科与眼科共同随访；听力下降者配助听器与前庭康复"],"life":["避免耳廓外伤、穿孔与睡眠时患侧受压，冬季注意耳部保暖","戒烟（气道受累者至关重要），接种流感、肺炎球菌疫苗，避免呼吸道感染","长期激素者补钙与维生素 D，每 1–2 年查骨密度；泼尼松 >20 mg/日超过 4 周者预防肺孢子菌肺炎","每 3–6 个月复查 ESR、CRP 与肺功能；每年心脏超声与主动脉 CTA；出现声嘶、喘鸣或呼吸困难立即就诊","妊娠：病情稳定期计划妊娠，激素维持最小有效剂量；硫唑嘌呤相对安全，甲氨蝶呤、环磷酰胺与托珠单抗孕期禁用"]},"prog":"5 年生存率约 80%–90%，10 年约 70%–75%；主要死亡原因为气道塌陷与感染（约 20%–30%）、心血管并发症（主动脉瘤破裂、瓣膜病）及合并恶性肿瘤。气道受累与起病年龄大者预后较差；规范激素联合免疫抑制治疗并定期气道与心脏评估可显著改善生存。","refs":["《复发性多软骨炎诊治进展》，中华风湿病学杂志 2019;23(5)","McAdam LP, et al. Relapsing polychondritis: prospective study of 23 patients and a review of the literature. Medicine (Baltimore). 1976;55(3):193-215","Michet CJ Jr, et al. Relapsing polychondritis. Survival and predictive role of early disease manifestations. Ann Intern Med. 1986;104(1):74-78","Kelley & Firestein's Textbook of Rheumatology (11th ed.), Relapsing Polychondritis"]}]}]},"uro":{"categories":[{"id":"stone","name":"结石与急症","rank":1,"summary":"结石相关急症先判断是否为梗阻合并感染（致命）再决定减压顺序：尿脓毒症=急救复苏+静脉抗生素+紧急引流（肾盂穿刺造瘘或输尿管支架），引流先于或同期取石；单纯绞痛以 NSAIDs 镇痛、按结石大小/位置选择排石观察、SWL、输尿管镜或 PCNL。","compare":[{"diseaseId":"ur_stone","dx":"突发单侧腰腹绞痛向会阴/大腿内侧放射，镜下或肉眼血尿，CT 平扫见高密度结石影并伴近端积水；体温正常、血流动力学稳定","key":"无全身炎症反应（体温、心率、血压、WBC/PCT 正常）=单纯绞痛；一旦出现寒战发热或休克即为感染性梗阻"},{"diseaseId":"ur_sepsis","dx":"梗阻性结石（或留置支架/造瘘）患者出现寒战高热、心动过速、呼吸急促、低血压、意识改变，符合 Sepsis-3（SOFA 增加≥2 分）或 qSOFA≥2 项","key":"感染+梗阻=泌尿外科急症，抗生素不是全部，6 h 内（尽量即刻）引流解除梗阻才救命"}],"diseases":[{"id":"ur_stone","name":"尿路结石（肾/输尿管结石）","aka":["泌尿系结石","肾结石","输尿管结石","Urolithiasis","肾绞痛"],"rank":1,"basic":{"define":"尿液中成石物质（草酸钙、磷酸钙、尿酸、感染性鸟粪石、胱氨酸）过饱和析出并聚集形成的结晶聚集体，位于肾盂肾盏或输尿管；输尿管急性梗阻时引起肾绞痛，是最常见的泌尿外科急症。","risk":["饮水量不足（每日尿量 <1 L）、高温作业、高钠高蛋白饮食","高草酸饮食（菠菜、坚果、浓茶）、高嘌呤饮食、高果糖饮料","肥胖、糖尿病、代谢综合征、高尿酸血症/痛风","尿路感染（产脲酶菌致感染性结石）、尿路梗阻或畸形（UPJ 狭窄、马蹄肾）","甲状旁腺功能亢进、远端肾小管酸中毒、胱氨酸尿症等代谢病因","结石家族史、既往结石史（5 年复发率约 50%）、长期卧床","药物：茚地那韦、氨苯蝶啶、磺胺类、维生素 C/D 过量、袢利尿剂"],"epi":"我国成人泌尿系结石患病率约 1%–10%，南方高于北方，男性多于女性（约 2–3:1），高发年龄 30–50 岁；输尿管结石最常见于三个生理狭窄（肾盂输尿管连接部、跨越髂血管处、输尿管膀胱壁段）。"},"patho":"尿液过饱和→成核→晶体生长与聚集→附着于肾乳头 Randall 斑→形成结石。结石下移至输尿管后引起急性梗阻，近端压力升高及输尿管平滑肌痉挛产生剧烈绞痛；梗阻持续导致肾盂内压升高、GFR 下降，并存感染时细菌与内毒素经肾盂静脉/淋巴回流引起菌血症。结石局部摩擦黏膜致血尿。","dx":{"criteria":["典型症状：突发单侧腰部或腹部绞痛，阵发性加剧，向下腹、腹股沟、阴囊/大阴唇放射，伴恶心呕吐、烦躁不安、不能静卧；部分仅表现为镜下血尿","尿常规：红细胞 ≥3/HPF（约 85% 患者有血尿），合并感染时白细胞与亚硝酸盐阳性","泌尿系 CT 平扫（NCCT）：首选，敏感度 95%–98%，可见高密度结石影、大小/位置/CT 值（HU）及梗阻积水程度；CT 值 >1000 HU 提示硬结石（不利 SWL）","超声：首选于孕妇及儿童，可见强回声伴声影与肾盂分离；对输尿管中段结石敏感度低","KUB 平片：可显示 >90% 的 X 线阳性结石，用于随访","实验室：血常规、肾功能、电解质、血尿酸、尿培养（有发热或脓尿时必做）"],"workup":["急诊评估三问：是否发热/寒战（感染）、是否单肾或移植肾（孤立肾梗阻需紧急引流）、肾功能是否急剧恶化","NCCT 报告结石最大径、位置、HU 值、皮肤至结石距离（SSD）、是否嵌顿及积水分级","结石成分分析（排石或术后）：红外光谱，指导代谢评估与预防","代谢评估：复发或双侧结石者查 24 h 尿钙/草酸/枸橼酸/尿酸、血甲状旁腺激素、血钙","尿培养+药敏：合并脓尿或既往感染性结石者"],"grading":"按部位分肾结石（肾盏/肾盂）、输尿管上段（L4 以上）、中段（跨越髂血管）、下段（骶髂关节以下至膀胱壁段）、膀胱及尿道结石。按成分分草酸钙（约 70%–80%）、磷酸钙、尿酸（约 10%）、感染性磷酸铵镁（鸟粪石）、胱氨酸（<1%）。"},"ddx":[{"name":"尿源性脓毒症（ur_sepsis）","point":"与本类 ur_sepsis 的鉴别点：结石绞痛者体温正常、心率血压稳定、WBC 与 PCT 正常；一旦出现寒战高热、低血压或意识改变，即由单纯绞痛升级为梗阻合并感染，需按脓毒症路径抢救与紧急引流，不可再按绞痛保守观察。"},{"name":"急性阑尾炎","point":"转移性右下腹痛、麦氏点压痛与反跳痛、WBC 升高；尿检多无血尿，CT 见阑尾增粗、周围渗出而非高密度结石影。"},{"name":"腹主动脉瘤破裂/夹层","point":"突发撕裂样腰背痛、双侧血压差、搏动性腹部包块、休克；结石绞痛为绞痛、血压常正常，影像可见结石与夹层内膜片。40 岁以上首次「肾绞痛」须警惕。"},{"name":"急性胆囊炎/胆总管结石","point":"右上腹持续痛向右肩背放射、Murphy 征阳性、发热、胆红素与 ALP 升高；超声见胆囊壁增厚或胆管扩张，而肾盂积水与结石位于泌尿系。"},{"name":"急性肾盂肾炎","point":"发热寒战、腰痛、肋脊角叩痛、脓尿及白细胞管型；肾盂肾炎合并结石梗阻即视为感染性梗阻，需引流。"},{"name":"卵巢扭转/异位妊娠","point":"育龄女性腹痛需查妊娠试验与盆腔超声；卵巢扭转表现为突发盆腔痛伴恶心，卵巢增大、血流信号减少，而非泌尿系结石影。"},{"name":"肾梗死","point":"房颤患者突发腰痛伴血尿、LDH 升高，CT 增强示楔形无强化区而非结石，尿路无明确结石。"}],"tx":{"drug":[{"name":"双氯芬酸（吲哚美辛栓）","dose":"双氯芬酸 50–75 mg 肌注（或双氯芬酸钠栓 50 mg 直肠给药），必要时 6–8 h 重复；吲哚美辛栓 50–100 mg 纳肛；口服双氯芬酸 25–50 mg tid","note":"绞痛一线镇痛，NSAIDs 止痛效果不劣于阿片且呕吐更少；合并消化性溃疡或肾功能不全都需慎用","renal":"eGFR <30 避免；脱水、低血容量时慎用，可致急性肾损伤","hepatic":"严重肝功能不全慎用","interact":"与抗凝药、糖皮质激素联用增加消化道出血；与 ACEI/ARB、利尿剂联用增加肾损伤（三联「triple whammy」）"},{"name":"布桂嗪/曲马多","dose":"布桂嗪 100 mg 肌注，或曲马多 100 mg 肌注/静滴；无效改用吗啡 5–10 mg 皮下/静注","note":"NSAIDs 禁忌或控制不佳时用弱/强阿片；绞痛剧烈者先建立静脉通路补液再加阿片","renal":"曲马多经肾排泄，eGFR <30 减量并延长给药间隔","hepatic":"肝硬化者曲马多减量","interact":"曲马多与 SSRI 联用增加 5-HT 综合征与癫痫风险；吗啡与镇静催眠药联用抑制呼吸"},{"name":"间苯三酚","dose":"40–80 mg 静滴或肌注，必要时 4 h 后重复","note":"选择性作用于痉挛的平滑肌，抗胆碱能副作用少，可作为解痉辅助；不能替代阿片镇痛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"坦索罗辛（MET 辅助排石）","dose":"0.4 mg qn 口服，疗程 4 周（输尿管下段 5–10 mm 结石）","note":"α1 受体阻滞剂可提高输尿管下段结石排出率、缩短排出时间；仅用于可选择观察排石者","renal":"重度肾功能不全慎用","hepatic":"重度肝功能不全慎用","interact":"与 PDE5 抑制剂、其他降压药联用可致体位性低血压；避免与强 CYP3A4 抑制剂合用"},{"name":"枸橼酸氢钾钠（结石预防）","dose":"10 g/d 分 3 次口服（尿酸结石溶石可增至 9–12 g/d 分次），维持晨尿 pH 6.2–6.8","note":"用于尿酸结石溶石与低枸橼酸尿性草酸钙结石复发预防；感染性结石及尿素分解菌感染时禁用","renal":"慢性肾衰竭、高钾血症者禁用","hepatic":"遵说明书","interact":"含铝抗酸剂可降低疗效，间隔 2 h 服用"},{"name":"别嘌醇（高尿酸血症）","dose":"起始 100 mg qd，逐渐增量至 200–300 mg qd，目标血尿酸 <360 μmol/L","note":"用于尿酸结石及高尿酸尿症者；治疗初期需预防痛风发作，结石溶解需同时碱化尿液","renal":"eGFR <60 起始 50–100 mg qd，按肾功能减量","hepatic":"慎用，定期查肝功","interact":"与硫唑嘌呤/6-巯基嘌呤合用可致严重骨髓抑制，必须减量；与华法林合用增加 INR"}],"nonDrug":["观察排石：结石 ≤6 mm 且疼痛可控制、无感染、无孤立肾梗阻者，配合饮水 2.5–3 L/d 与 MET 观察 4–6 周","体外冲击波碎石（SWL）：肾结石及输尿管上段结石 ≤2 cm、CT 值 <1000 HU、SSD <10 cm；孕妇、严重凝血障碍、未控制的感染、主动脉瘤附近为禁忌","输尿管镜碎石（URS/RIRS）：输尿管中下段结石首选，≥1 cm 或 SWL 失败者；妊娠期输尿管结石可考虑","经皮肾镜取石（PCNL）：肾结石 >2 cm、鹿角形结石、SWL 失败、下盏结石不利因素；标准通道与微通道按结石负荷选择","紧急干预指征：孤立肾/双侧梗阻、感染性梗阻、顽固性疼痛、肾功能进行性恶化→输尿管支架或经皮肾穿刺造瘘引流后再择期处理结石","腹腔镜/机器人肾盂切开取石或输尿管切开取石：URS 不可及的长段嵌顿结石、畸形需同期成形者"],"life":["每日饮水 2.5–3 L，维持尿量 ≥2.5 L，尿色清亮","限钠 <5 g/d，适量动物蛋白，足量钙（1000–1200 mg/d，不必低钙饮食）","限高草酸食物、限高嘌呤（内脏、浓肉汤、啤酒）、少饮含果糖饮料","减重、规律运动、避免久坐与高温脱水作业","术后 1–3 个月复查 KUB/超声或低剂量 CT；复发高危者每 6–12 个月代谢随访","结石成分分析后个体化饮食：尿酸结石碱化尿液，感染性结石控制感染并彻底取石"]},"prog":"无症状肾结石约 10%–25% 在 5 年内出现症状；输尿管结石 <5 mm 自发排出率约 70%–80%，5–10 mm 约 50%，>10 mm 明显下降。结石清除后 5 年复发率约 30%–50%，10 年可达 50%–70%。梗阻合并感染未及时引流者可进展为脓毒症与肾功能丧失。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·尿石症","中国泌尿系结石诊断治疗指南（中华医学会泌尿外科学分会，2019）","欧洲泌尿外科学会（EAU）尿石症指南 2023","美国泌尿外科学会（AUA）肾结石与输尿管结石指南 2016（2023 更新）"]},{"id":"ur_sepsis","name":"尿源性脓毒症","aka":["梗阻性肾盂肾炎","感染性肾积水","Urosepsis","梗阻性化脓性肾盂肾炎"],"rank":2,"basic":{"define":"由泌尿系统感染（梗阻性化脓性肾盂肾炎、经尿道操作后感染、感染性结石）引起的脓毒症，即宿主对泌尿系感染反应失调导致危及生命的器官功能障碍；核心矛盾是「梗阻+感染」，引流与抗生素同等重要。","risk":["泌尿系结石梗阻（尤其感染性结石/鸟粪石）、UPJ 狭窄等尿路梗阻","糖尿病、血糖控制不良（女性尤著）","近期经尿道操作/输尿管镜/留置双 J 管或导尿管","免疫抑制：长期激素、化疗、移植后抗排异、HIV","高龄、女性、妊娠、神经源性膀胱、尿流改道","既往多重耐药菌尿路感染、反复尿路感染史","慢性肾脏病、肝硬化、营养不良"],"epi":"尿源性脓毒症约占全部脓毒症的 9%–31%，是脓毒症最常见感染来源之一；梗阻合并感染的病死率显著升高，合并感染性休克者病死率可达 20%–40%。输尿管镜碎石术后尿源性脓毒症发生率约 0.3%–1.5%，术前尿培养阳性者风险更高。"},"patho":"梗阻使肾盂内压升高（>20–30 cmH₂O 时发生肾盂静脉/淋巴返流），细菌及内毒素进入循环；产脲酶菌（变形杆菌、克雷伯菌）分解尿素产氨使尿 pH 升高，形成磷酸铵镁结石进一步加重梗阻。内毒素激活补体与凝血系统，导致血管扩张、毛细血管渗漏、微循环障碍与多器官功能障碍，早期为高排低阻的暖休克，进而转为低排低阻。","dx":{"criteria":["Sepsis-3：可疑或确诊泌尿系感染 + SOFA 评分较基线增加 ≥2 分；qSOFA（呼吸 ≥22 次/min、意识改变、收缩压 ≤100 mmHg）≥2 项提示预后不良","典型表现：寒战高热（常 >38.5℃）或低体温、心动过速、呼吸急促、低血压、少尿、意识改变","感染性休克：充分液体复苏后仍需血管活性药维持 MAP ≥65 mmHg 且血乳酸 >2 mmol/L","尿培养或血培养阳性（尿源性脓毒症血培养阳性率约 30%–50%）；脓尿 + 亚硝酸盐阳性","影像示梗阻性积水（超声/CT），梗阻侧可伴肾周渗出、气肿性肾盂肾炎征象（肾实质/集合系统积气）","PCT 升高（>2 ng/mL 提示细菌感染与病情较重），CRP 与 WBC 可升高或白细胞减少","气肿性肾盂肾炎：CT 见肾实质或肾周气体，多见于糖尿病女性，属外科急症"],"workup":["入院 1 h 内：血培养 2 套 + 尿培养 + 尿常规 + 血常规、CRP、PCT、肝肾功能、电解质、凝血、血气/乳酸","生命体征与尿量监测，qSOFA/SOFA 评分，必要时转 ICU","床旁超声：肾盂积水、积脓、结石；无法判断时行腹部 CT 明确梗阻部位","警惕气肿性肾盂肾炎、肾脓肿、肾乳头坏死脱落（尿中见坏死组织）","药敏结果回报后降阶梯；关注多重耐药肠杆菌（CRE/ESBL）","糖尿病者查血糖与酮体，评估会阴 Fournier 坏疽（需急诊探查）"],"grading":"按 Sepsis-3 分层：脓毒症（SOFA 增加≥2）→ 脓毒性休克（需升压药且乳酸 >2 mmol/L）。按感染源形态分梗阻性化脓性肾盂肾炎、感染性肾积水/肾积脓、气肿性肾盂肾炎、肾脓肿、Fournier 坏疽。"},"ddx":[{"name":"尿路结石（单纯绞痛，ur_stone）","point":"与本类 ur_stone 的鉴别点：结石绞痛者体温正常、无低血压与器官功能障碍，仅需镇痛与排石处理；一旦结石患者出现寒战高热、低血压或乳酸升高，即按尿源性脓毒症启动抗生素+紧急引流，不能继续观察排石。"},{"name":"急性非梗阻性肾盂肾炎","point":"同样有发热腰痛与脓尿，但影像无积水或积脓、无尿路梗阻；门诊口服/短期静脉抗生素即可，无需引流。"},{"name":"急性肾盂肾炎合并肾周脓肿","point":"抗生素治疗 72 h 无改善或持续高热，CT 见肾周/肾实质低密度无强化区与液化，需经皮穿刺引流而非仅更换抗生素。"},{"name":"Fournier 坏疽（会阴坏死性筋膜炎）","point":"会阴/阴囊剧痛与皮肤坏死、捻发音、与体征不成比例的疼痛，需急诊清创；常并发于糖尿病与尿路感染，可同时存在脓毒症。"},{"name":"急性胆管炎","point":"Charcot 三联征（发热、右上腹痛、黄疸）或 Reynolds 五联征，胆红素/ALP 升高、胆管扩张；梗阻部位在胆道需 ERCP 减压。"},{"name":"腹腔感染/消化道穿孔","point":"腹膜炎体征、膈下游离气体、CT 见腹腔渗出与游离气；需外科探查，感染来源不同。"},{"name":"药物热/输血反应","point":"无脓尿、尿培养阴性，与用药时间相关，停药后热退；血培养阴性且无梗阻表现。"}],"tx":{"drug":[{"name":"晶体液复苏","dose":"初始 30 mL/kg 平衡晶体液在 3 h 内输注；随后按 250–500 mL 滴定，目标 MAP ≥65 mmHg、尿量 ≥0.5 mL/kg/h、乳酸下降","note":"复苏越早越好；心功能不全者改为小剂量分次并床旁评估容量反应性，避免肺水肿","renal":"无尿期不限制补液但需密切监测容量与电解质","hepatic":"严重肝病者优先平衡晶体液，避免大量生理盐水致高氯性酸中毒","interact":"遵说明书"},{"name":"去甲肾上腺素","dose":"0.05–0.5 μg/kg/min 静脉泵入，目标 MAP ≥65 mmHg；单药不达标加用肾上腺素 0.05–0.5 μg/kg/min 或血管加压素 0.01–0.04 U/min","note":"液体复苏后仍低血压即启动；经中心静脉输注，避免外渗；不可因等待药敏而延迟","renal":"遵说明书","hepatic":"遵说明书","interact":"与 β 受体阻滞剂合用可致严重高血压；MAO 抑制剂增强升压作用"},{"name":"哌拉西林他唑巴坦","dose":"4.5 g 静滴 q6h（延长输注 3 h）；重症首剂可给负荷量","note":"经验性覆盖革兰阴性杆菌+厌氧菌，用于社区或医院获得性尿源性脓毒症；药敏回报后降阶梯","renal":"CrCl 20–40：4.5 g q8h；CrCl <20：2.25 g q8h；CVVH 按方案调整","hepatic":"无需调整","interact":"可增加万古霉素肾毒性；与华法林合用增加出血"},{"name":"头孢曲松（社区获得性轻中度感染）","dose":"2 g 静滴 qd（或分 q12h）","note":"社区获得性尿源性脓毒症经验用药；ESBL 流行或近期住院/操作者不适用","renal":"无需调整","hepatic":"无需调整","interact":"与含钙输液（如乳酸林格液）同管可沉淀，新生儿禁用"},{"name":"美罗培南（产 ESBL/CRE 高危）","dose":"1 g 静滴 q8h（延长输注 3 h）；CRE 或重症可 2 g q8h","note":"近期住院、留置尿管或支架、既往 ESBL 检出者经验性选用；CRE 需联合头孢他啶阿维巴坦等","renal":"CrCl 25–50：1 g q12h；CrCl 10–25：0.5 g q12h；CVVH 按方案","hepatic":"轻度无需调整，重度慎用","interact":"丙戊酸血药浓度显著下降，禁联合；碳青霉烯类可降低癫痫阈值"},{"name":"万古霉素（耐甲氧西林葡萄球菌高危）","dose":"负荷 25–30 mg/kg 静滴（按实际体重，最大 2 g），维持 15–20 mg/kg q12h，谷浓度 15–20 mg/L 或 AUC/MIC 400–600","note":"既往 MRSA 病史、医院获得性感染或留置导管者加用；尿培养阴性一般不需","renal":"按 CrCl 调整并监测浓度","hepatic":"无需调整","interact":"与哌拉西林他唑巴坦/氨基糖苷类合用增加急性肾损伤；快速输注致红人综合征"},{"name":"氢化可的松（难治性休克）","dose":"200 mg/d 静滴（50 mg q6h 或持续泵入），通常不超过 5–7 d","note":"液体+升压药仍不能维持 MAP 时使用，不用于无休克的脓毒症","renal":"遵说明书","hepatic":"遵说明书","interact":"大剂量激素增加消化道出血与高血糖，需监测血糖"}],"nonDrug":["紧急减压引流是核心：超声引导经皮肾穿刺造瘘或输尿管镜下留置双 J 管，应在诊断后 6 h 内完成，条件允许即刻进行；引流失败时改另一种方式","引流优先于取石：一期造瘘+二期取石，避免在脓毒症状态下长时间手术","脓性引流液送培养；造瘘管在感染控制、体温正常、肾功能恢复后择期处理结石","气肿性肾盂肾炎：急诊引流+广谱抗生素，必要时肾切除；坏死性感染需清创","ICU 支持：机械通气、CRRT、器官支持","更换堵塞的导尿管或双 J 管，移除不必要的导管"],"life":["急性期绝对卧床，尽早在肠内营养","血糖控制（糖尿病者目标 7.8–10.0 mmol/L）","治愈后评估结石与梗阻病因，避免再次梗阻引发脓毒症","抗菌药物按药敏降阶梯，疗程一般 10–14 d（引流后体温平稳可 7–10 d）","出院后随访肾功能、尿常规、尿培养与超声","留置造瘘/支架者注意管道护理与引流液性状，出现寒战发热立即就诊"]},"prog":"及时引流联合抗菌药物者病死率降至 <10%；引流延迟（>24 h）或感染源未控制者病死率可升至 20%–40%。合并感染性休克、气肿性肾盂肾炎、糖尿病或免疫功能低下者预后差。肾功能恢复取决于梗阻时间与感染是否彻底控制，部分患者遗留肾萎缩或慢性肾病。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·泌尿系感染","中国尿源性脓毒症诊治专家共识（中华医学会泌尿外科学分会，2021）","欧洲泌尿外科学会（EAU）泌尿系感染指南 2023","拯救脓毒症运动（Surviving Sepsis Campaign）国际指南 2021","中国脓毒症/脓毒性休克急诊治疗指南（2018）"]}]},{"id":"prostate","name":"前列腺疾病","rank":2,"summary":"BPH 先以 IPSS 量化下尿路症状并按轻/中/重分层选择观察、α 受体阻滞剂±5α 还原酶抑制剂或手术；前列腺癌靠 PSA+MRI 靶向穿刺确诊、以 Gleason/ISUP 分级分组与危险分层驱动治疗决策，PSAD 用于降低不必要穿刺与风险分层。","compare":[{"diseaseId":"ur_bph","dx":"中老年男性 LUTS（尿频、夜尿、排尿困难），IPSS 评分量化；直肠指检前列腺增大、质韧，PSA 多 <4 ng/mL，尿动力学示膀胱出口梗阻","key":"IPSS+前列腺体积+Qmax+残余尿四项构成分层；IPSS≥8 且影响生活质量即需药物治疗"},{"diseaseId":"ur_pca","dx":"PSA 升高（>4 ng/mL）、DRE 触及硬结节、MRI PI-RADS≥3 行靶向穿刺，病理 Gleason 评分并换算 ISUP 分级分组 1–5","key":"确诊靠系统+靶向穿刺病理；Gleason 4 的比例决定 ISUP 分组与转移风险，PSAD>0.15 提示临床有意义癌"}],"diseases":[{"id":"ur_bph","name":"良性前列腺增生","aka":["BPH","前列腺增生","前列腺肥大","Benign Prostatic Hyperplasia","LUTS"],"rank":1,"basic":{"define":"中老年男性前列腺移行带与中央带腺体及间质平滑肌增生，导致膀胱出口梗阻（BOO）与下尿路症状（LUTS）的良性进展性疾病，可引起尿潴留、膀胱结石、反复尿路感染与上尿路积水。","risk":["年龄（组织学增生 40 岁约 8%，60 岁约 60%，80 岁以上 >80%）","雄激素（睾酮经 5α 还原酶转为双氢睾酮 DHT 驱动增生）","代谢综合征、肥胖、糖尿病、高血压","缺乏运动、高热量饮食","家族史","前列腺炎症反复发作"],"epi":"我国 40 岁以上男性 BPH 患病率约 30%–40%，60 岁以上约 60%，80 岁以上可 >80%；约 1/4 的 50 岁以上男性存在中重度 LUTS；需治疗的 BPH 是泌尿外科门诊最常见病种之一。"},"patho":"增生腺体（静力性梗阻=腺体体积）与平滑肌 α1 受体张力（动力性梗阻）共同构成梗阻；膀胱逼尿肌代偿性肥厚→小梁化→憩室→失代偿，残余尿增加致反复感染与结石，长期高压可致双肾积水与肾功能损害。雄激素、年龄与炎症因子共同促进前列腺基质与上皮增生。","dx":{"criteria":["中老年男性 + LUTS：储尿期（尿频、夜尿、尿急）与排尿期（尿流细、排尿踌躇、终末滴沥、排尿时间延长）症状","IPSS（国际前列腺症状评分）7 项共 0–35 分：0–7 轻度、8–19 中度、20–35 重度；QoL 生活质量评分 0–6","直肠指检（DRE）：前列腺增大、表面光滑、质韧、中央沟变浅；结节或质硬需排除前列腺癌","尿流率测定：Qmax <10 mL/s 提示明显梗阻（Qmax >15 mL/s 多为轻度）","残余尿（PVR）：>50 mL 提示膀胱排空不全，>200 mL 为急性尿潴留高风险","前列腺体积（经直肠超声）：>30 mL 为体积增大；>40 mL 者 5α 还原酶抑制剂才能缩小腺体并获益","PSA：>4 ng/mL 需排除前列腺癌（合并大腺体时按 PSAD 判断）"],"workup":["病史与用药（抗胆碱药、α 受体激动剂、利尿剂可加重 LUTS）","IPSS + QoL + 尿流率 + PVR + DRE + PSA（50 岁以上或预期寿命 >10 年）","尿常规、尿培养（排除感染）、肾功能（上尿路受损）","经直肠或经腹超声：前列腺体积、残余尿、膀胱结石/憩室/肾积水","尿动力学：拟手术或症状与梗阻不成比例、神经源性膀胱可疑时","膀胱镜：拟手术或有血尿/反复感染以排除膀胱肿瘤与尿道狭窄"],"grading":"IPSS 分层：轻度 0–7 分（观察等待）；中度 8–19 分；重度 20–35 分（药物治疗或手术）。BOO 分级按 Qmax 与压力-流率测定（Schäfer/ICS 分度）评估；急性尿潴留一次即视为手术指征之一。"},"ddx":[{"name":"前列腺癌（ur_pca）","point":"与本类 ur_pca 的鉴别点：BPH 前列腺增大但质韧、无结节，PSA 多正常或轻度升高且以移行带为主；前列腺癌 DRE 触诊结节/质硬，PSA 显著升高、PSAD >0.15，MRI 见外周带 PI-RADS ≥3 病灶需穿刺确诊。"},{"name":"神经源性膀胱","point":"有脊髓损伤、糖尿病周围神经病变、脑血管病史，尿动力学示逼尿肌无收缩或活动过度，而非单纯出口梗阻。"},{"name":"尿道狭窄","point":"有尿道外伤、感染或导尿史，尿流率呈「平台型」，尿道造影见狭窄段，膀胱镜可明确。"},{"name":"膀胱过度活动症（OAB）","point":"以尿急、尿频、夜尿为主而无明显排尿期症状，尿流率与 PVR 多正常，M 受体拮抗剂或 β3 激动剂有效。"},{"name":"慢性前列腺炎","point":"会阴部坠胀、前列腺触痛、EPS 白细胞升高，多见于年轻和性活跃期男性；PSA 可一过性升高。"},{"name":"原发性膀胱颈梗阻","point":"前列腺体积不大而膀胱镜见膀胱颈抬高，Qmax 低、PVR 高；可见于较年轻男性。"},{"name":"糖尿病/尿崩症性多尿","point":"全天尿量增多、尿频伴口渴，血糖/尿比重异常，与前列腺症状和梗阻不相关。"}],"tx":{"drug":[{"name":"坦索罗辛","dose":"0.2 mg qn（国内说明书起始 0.2 mg，部分患者可增至 0.4 mg qn）","note":"α1A 选择性阻滞剂，起效快（数天至 2 周），IPSS 改善 4–6 分，不缩小前列腺、不降低 AUR 或手术风险；体位性低血压与逆行射精为常见不良反应","renal":"轻中度无需调整，重度慎用","hepatic":"重度肝功能不全慎用","interact":"与 PDE5 抑制剂联用（间隔 4 h 以上、从小剂量起）可致低血压；避免与强 CYP3A4 抑制剂合用"},{"name":"多沙唑嗪","dose":"1 mg qn 起始，逐步增至 4–8 mg qn","note":"α1 阻滞剂，需按剂量滴定以防首剂低血压；兼降压作用，合并高血压者适用","renal":"无需调整","hepatic":"肝功能不全减量","interact":"与 PDE5 抑制剂、其他降压药合用加重低血压"},{"name":"特拉唑嗪","dose":"1 mg 睡前起始，每 1–2 周递增，维持 2–10 mg qn","note":"α1 阻滞剂，起始剂量小、滴定慢，可降低首剂效应","renal":"无需调整","hepatic":"肝功能不全减量","interact":"同其他 α 阻滞剂，注意低血压"},{"name":"非那雄胺","dose":"5 mg qd，需连续服用 6 个月以上起效；前列腺体积 >40 mL 者获益","note":"5α 还原酶Ⅱ型抑制剂，可使前列腺体积缩小约 20%–30%、PSA 下降约 50%（解读时需乘以 2），并降低急性尿潴留与手术风险；性功能不良反应","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"与 α 阻滞剂联用不良反应叠加；经肝脏代谢，注意肝功能"},{"name":"度他雄胺","dose":"0.5 mg qd，服用 3–6 个月起效","note":"5α 还原酶Ⅰ/Ⅱ型双重抑制剂，缩小前列腺体积效果强于非那雄胺，PSA 约降至一半；起效后长期维持","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"强 CYP3A4 抑制剂可升高血药浓度；与 α 阻滞剂联合用于中重度 BPH"},{"name":"索利那新（叠加 OAB 症状）","dose":"5 mg qd，不耐受或疗效不足可增至 10 mg qd；PVR >200 mL 时先解除梗阻再加用","note":"M3 选择性抗胆碱能药，用于 α 阻滞剂后仍有尿频尿急者；注意残余尿与认知副作用","renal":"CrCl <30：最大 5 mg qd","hepatic":"中度肝功能不全最大 5 mg qd，重度禁用","interact":"与强 CYP3A4 抑制剂合用需限量"},{"name":"他达拉非（合并 ED）","dose":"5 mg qd 长期服用","note":"PDE5 抑制剂可改善 LUTS 与勃起功能，可与 α 阻滞剂联用但需间隔并监测血压","renal":"CrCl <30 减量或慎用","hepatic":"重度肝功能不全禁用","interact":"禁与硝酸酯类合用；与 α 阻滞剂合用注意低血压"}],"nonDrug":["观察等待：IPSS ≤7 且生活质量无明显受影响者，调整饮水与排尿习惯、避免抗胆碱药与减充血剂","经尿道前列腺电切（TURP）：手术金标准，适用于中重度 LUTS、反复尿潴留、反复感染、膀胱结石、上尿路受损、药物无效","经尿道前列腺激光剜除（HoLEP/ThuLEP）：大体积（>80 mL）可替代 TURP，出血更少、留置尿管时间短","前列腺动脉栓塞（PAE）：拒绝手术或有高手术风险者，改善症状但远期再治疗率高于 TURP","前列腺支架/水蒸气热疗等微创：高龄、抗凝或手术禁忌者可选","急性尿潴留：立即导尿并监测尿量，留置尿管 2–3 天尝试拔管，失败者行 TURP 或清洁间歇导尿","抗凝/抗血小板患者术前需评估出血风险并按专科策略停用"],"life":["减少睡前饮水与咖啡、酒精、浓茶，避免便秘","规律排尿、避免憋尿与长时间久坐","体重管理与规律运动（减重可改善 LUTS）","α 阻滞剂睡前服以减轻低血压，注意体位性低血压与逆行射精","每 6–12 个月复评 IPSS、Qmax、PVR，注意急性尿潴留与肾积水","服用 5α 还原酶抑制剂者 PSA 解读需乘以 2，每年随访 PSA"]},"prog":"轻中度观察等待者 5 年内约 20%–30% 症状加重需药物或手术；α 阻滞剂起效快但无法阻止疾病进展；5α 还原酶抑制剂需 6–12 个月显效，可降低急性尿潴留与手术风险约 50%。TURP 术后 10 年再手术率约 10%–15%，HoLEP 更低。合并糖尿病、大体积前列腺与高 PVR 者进展更快。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·良性前列腺增生","中国良性前列腺增生诊断治疗指南（中华医学会泌尿外科学分会，2014）","欧洲泌尿外科学会（EAU）非神经源性男性下尿路症状（含 BPH）指南 2023","美国泌尿外科学会（AUA）良性前列腺增生管理指南 2019（2023 更新）"]},{"id":"ur_pca","name":"前列腺癌","aka":["前列腺腺癌","Prostate Cancer","PCa","Gleason 评分","ISUP 分级分组"],"rank":2,"basic":{"define":"前列腺腺上皮来源的恶性肿瘤，绝大多数为腺泡腺癌，多起源于外周带；临床上以 PSA 筛查发现的局限性病变为主，是男性最常见的泌尿生殖系统肿瘤之一。","risk":["年龄 >50 岁（40 岁以下少见，50–70 岁高发）","家族史：父亲或兄弟患病风险增加 2–3 倍，BRCA2 携带者风险显著升高","非裔人群高发（我国发病率低于欧美但增速快）","肥胖、高脂饮食","慢性前列腺炎与前列腺增生（部分共享危险因素）","长期吸烟、缺乏运动"],"epi":"我国前列腺癌发病已居男性泌尿生殖系统肿瘤首位，年新发病例约 13–15 万，城市高于农村，确诊时分期晚于欧美；局限性期 5 年生存率 >95%，转移性约 30%。发病率随年龄上升，60 岁以上检出率明显增加。"},"patho":"雄激素受体（AR）通路是前列腺癌生长的主要驱动；Gleason 4 型腺体融合与筛状结构提示侵袭性。肿瘤经包膜外侵犯→精囊→淋巴结（闭孔、髂内、髂外）→骨转移（成骨性）。进展为去势抵抗性前列腺癌（CRPC）与 AR 扩增/突变、神经内分泌分化相关；约 20% 患者存在 BRCA2 等 DNA 修复基因突变。","dx":{"criteria":["PSA >4 ng/mL 提示异常；4–10 ng/mL 为灰区，需结合 PSAD（f/tPSA）与 MRI 决定穿刺；PSAD >0.15 ng/mL/cm³ 提示临床有意义癌风险升高","直肠指检触及结节/质硬区（PSA <4 但 DRE 异常亦需穿刺）","多参数 MRI（PI-RADS v2.1）：≥3 分需靶向穿刺；≤2 分可考虑随访","前列腺穿刺（系统+MRI 靶向融合穿刺，10–12 针）为确诊依据","病理 Gleason 评分 = 主要+次要分级（均 5 分时加用最高分级作为第三成分），换算 ISUP 分级分组：1（≤6，3+3）、2（3+4）、3（4+3）、4（8 分）、5（9–10 分）","分期：TNM；MRI 评估包膜外侵犯/精囊侵犯，骨显像或 PSMA PET/CT 用于转移评估"],"workup":["PSA、f/tPSA、PSA 密度（PSAD=PSA/前列腺体积）","DRE + 经直肠超声 + 多参数 MRI（PI-RADS）","穿刺病理：Gleason 评分、ISUP 分组、阳性针数占比、有无神经侵犯","风险分层：低危 T1–T2a、Gleason ≤6、PSA <10；中危 T2b–c 或 Gleason 7 或 PSA 10–20；高危 T3a 或 Gleason 8–10 或 PSA >20","高危/中危：骨显像、盆腔 CT/MRI 或 PSMA PET/CT；基因检测（BRCA2、MSI-H），转移性者尤需","随访：连续 PSA（生化复发：根治术后 PSA ≥0.2 ng/mL，放疗后较谷值升高 ≥2 ng/mL）"],"grading":"Gleason/ISUP 分级分组：1=Gleason ≤6（3+3）；2=3+4；3=4+3；4=Gleason 8（4+4、3+5、5+3）；5=Gleason 9–10。风险分层：低危（T1–T2a，ISUP 1，PSA <10）；中危（T2b–c 或 ISUP 2–3 或 PSA 10–20）；高危（T3a 或 ISUP 4–5 或 PSA >20）；极高危（T3b–T4 或主分级 5）。"},"ddx":[{"name":"良性前列腺增生（ur_bph）","point":"与本类 ur_bph 的鉴别点：BPH 前列腺弥漫增大、质韧无结节，PSA 升高多以移行带为主、PSAD <0.15，MRI 无外周带可疑灶；前列腺癌 DRE 有结节、MRI 见外周带 PI-RADS ≥3，穿刺病理方可确诊，5α 还原酶抑制剂使用者 PSA 需乘以 2 解读。"},{"name":"肉芽肿性前列腺炎","point":"PSA 可升高、DRE 触及硬结，但穿刺见肉芽肿性炎、特殊染色阴性；需活检鉴别。"},{"name":"前列腺结核","point":"有肺结核史，前列腺可增大伴钙化与干酪样坏死，尿中查抗酸杆菌阳性；活检示肉芽肿伴干酪样坏死。"},{"name":"膀胱颈/尿道癌","point":"无 PSA 显著升高，膀胱镜见膀胱颈肿物，活检为尿路上皮癌；免疫组化 PSA/NKX3.1 阴性。"},{"name":"直肠癌侵犯前列腺","point":"便血、里急后重、肠镜见肿物，活检为腺癌（CDX2 阳性、PSA 阴性）；MRI 见直肠病灶与前列腺分界不清。"},{"name":"其他原发灶的骨转移","point":"肺癌/乳腺癌/肾癌骨转移，需结合免疫组化（NKX3.1、PSA、AR 阳性提示前列腺来源）与 PSMA PET。"}],"tx":{"drug":[{"name":"戈舍瑞林（ADT 去势）","dose":"3.6 mg 皮下植入 q28d，或 10.8 mg q3 个月","note":"GnRH 激动剂，用于局部晚期/转移性前列腺癌，联合放疗时提前 2–3 个月开始；初始可致睾酮一过性升高（肿瘤闪烁），脊柱转移者需先抗雄","renal":"无需调整","hepatic":"肝功能不全慎用","interact":"部分 GnRH 激动剂可延长 QT，与 QT 延长药合用需监测"},{"name":"地加瑞克（GnRH 拮抗剂）","dose":"起始 240 mg 皮下 q28d ×2 次，之后 80 mg q28d","note":"直接拮抗 GnRH 受体，无睾酮闪烁，适用于脊柱转移/尿路梗阻风险高的高危患者；注射部位反应常见","renal":"重度肾功能不全慎用","hepatic":"中度肝功能不全维持量减至 80 mg q28d，重度慎用","interact":"与 QT 延长药物合用注意电解质与心电监测"},{"name":"比卡鲁胺（抗雄）","dose":"50 mg qd（联合 LHRH 激动剂或放疗）","note":"非甾体抗雄药，用于联合 ADT（CAB），起始 2 周预防闪烁；需监测肝功能","renal":"无需调整","hepatic":"中重度肝功能不全慎用","interact":"CYP3A4 抑制/底物；与华法林合用需监测 INR"},{"name":"阿比特龙（mCRPC/mCSPC）","dose":"1000 mg qd 空腹口服，联合泼尼松 5 mg bid","note":"CYP17A1 抑制剂，用于转移性去势抵抗及转移性激素敏感期（联合 ADT）；必须同时用糖皮质激素防盐皮质激素过多；需定期查肝功能","renal":"重度肾功能不全慎用","hepatic":"中度肝功能不全减量至 250 mg，重度禁用","interact":"需与泼尼松同服；避免与强 CYP3A4 诱导剂；食物影响吸收（空腹服用）"},{"name":"恩扎卢胺","dose":"160 mg qd 口服","note":"AR 拮抗剂，用于 mCRPC、mCSPC、非转移性 CRPC；注意癫痫风险（既往癫痫/脑损伤者慎用）与跌倒、疲乏","renal":"轻中度无需调整，重度慎用","hepatic":"轻度无需调整，中重度慎用或减量","interact":"CYP3A4 底物与诱导剂；与华法林合用时需监测 INR"},{"name":"多西他赛（化疗）","dose":"75 mg/m² 静滴 q21d，联合泼尼松 5 mg bid；高危转移性激素敏感期可用 6 周期","note":"用于 mCRPC 或 mHSPC；需监测中性粒细胞、肝功能与神经毒性","renal":"无需常规调整","hepatic":"轻中度减量，中重度禁用","interact":"强 CYP3A4 抑制剂可增加毒性；与华法林合用需监测"},{"name":"镭-223（骨转移）","dose":"55 kBq/kg 静脉注射，q4 周共 6 次","note":"α 粒子骨靶向放射性药物，用于有骨转移的 mCRPC；与骨髓抑制治疗同期使用需监测血细胞","renal":"重度肾功能不全慎用","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["极低危/低危：主动监测（PSA q3–6 个月、重复 MRI 与穿刺），或根治性前列腺切除、外照射放疗（EBRT）","中高危局限期：根治性前列腺切除 ± 盆腔淋巴结清扫（可加辅助放疗），或 EBRT 联合 ADT 4–6 个月/2–3 年","极高危/局部晚期：EBRT 联合 2–3 年 ADT，可加用阿比特龙或阿帕他胺","转移性激素敏感期（mHSPC）：ADT 为基础联合新型内分泌药/多西他赛，低转移负荷可加原发灶放疗","mCRPC：新型内分泌治疗、多西他赛、PARP 抑制剂（BRCA 突变）、PSMA 放射性配体","骨转移：唑来膦酸或地舒单抗，预防骨相关事件与椎体压缩","根治术后随访：PSA q3 个月×2 年，后每半年；生化复发需影像评估"],"life":["均衡饮食、控制体重、规律有氧运动以改善 ADT 相关肌少症与心血管风险","ADT 期间监测骨密度（维生素 D+钙，需要时用双膦酸盐）、血脂、血糖与心电","根治性切除术后盆底肌训练改善尿控；放疗后排尿刺激与直肠反应需随访","主动监测者坚持定期随访，避免失访","戒烟、限酒，关注性功能与心理健康","转移性患者以症状控制与生活质量为主要目标，家属参与治疗决策"]},"prog":"局限性前列腺癌 5 年生存率 >95%，主动监测的低危患者肿瘤特异性生存率同样很高；局部进展期 5 年生存率约 80%–90%；转移性患者中位生存已由 2–3 年提升至 4–5 年以上（新型内分泌+化疗联合）。Gleason 4 比例、PSA、TNM 分期与治疗反应为主要预后因素。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·前列腺癌","中国前列腺癌诊治指南（中华医学会泌尿外科学分会，2019）","欧洲泌尿外科学会（EAU）前列腺癌指南 2024","美国国家综合癌症网络（NCCN）前列腺癌指南 2024","前列腺癌筛查中国专家共识（2017）"]}]},{"id":"u_tumor_inf","name":"泌尿肿瘤与感染","rank":3,"summary":"肾癌确诊主要靠增强 CT 强化特征且对放化疗不敏感，以手术为主；膀胱癌靠膀胱镜+病理分期，非肌层浸润以 TURBT+灌注为主、肌层浸润需根治性膀胱切除；复杂尿路感染需先明确「结构或功能异常+耐药风险」再选择引流与抗菌方案。","compare":[{"diseaseId":"ur_rcc","dx":"偶发血尿或体检发现肾脏占位，增强 CT 示皮质期明显强化、实质期/排泄期密度下降（快进快出），强化幅度 >15 HU","key":"肾癌对放化疗不敏感，局限期首选手术（部分切除优先保留肾功能），转移期以靶向+免疫为主"},{"diseaseId":"ur_bca","dx":"间歇性无痛性肉眼血尿为典型表现，膀胱镜见乳头状或广基肿瘤，病理为尿路上皮癌，MRI 或二次电切评估肌层浸润","key":"非肌层浸润（Ta/T1/CIS）行 TURBT+术后灌注；肌层浸润（T2 及以上）需根治性膀胱切除联合新辅助化疗"},{"diseaseId":"ur_uti","dx":"尿频、尿急、尿痛或发热腰痛，尿培养阳性；复杂尿路感染常伴梗阻、结石、导管、糖尿病或免疫抑制，并常为多重耐药菌","key":"先取培养再用药，合并梗阻/脓肿者必须引流；48–72 h 无改善须重评病原与梗阻"}],"diseases":[{"id":"ur_rcc","name":"肾细胞癌","aka":["RCC","肾癌","肾透明细胞癌","Renal Cell Carcinoma"],"rank":1,"basic":{"define":"起源于肾小管上皮的恶性肿瘤，以透明细胞癌（ccRCC，约 70%–75%）最常见，其次为乳头状癌与嫌色细胞癌；多数为偶发体检发现，部分伴副肿瘤综合征。","risk":["吸烟（剂量相关，主要可防因素）","肥胖与高血压（与 ccRCC 显著相关）","长期透析/终末期肾病（获得性囊性肾病相关肾癌）","职业暴露：三氯乙烯、石棉、镉","遗传性肾癌综合征：VHL 病、BHD、HLRCC（FH 突变）、SDH 缺陷","男性、>60 岁、家族史"],"epi":"我国肾癌发病率约 5–8/10 万，男性多于女性（约 2:1），高发年龄 60–70 岁；约 60% 为偶发发现，诊断时约 1/4 已转移。晚期肾癌对放化疗不敏感，靶向与免疫治疗显著延长生存。"},"patho":"ccRCC 多因 3p 缺失导致 VHL 基因失活，HIF 累积→VEGF/PDGF 表达增加→肿瘤血管生成旺盛（富血供、易出血坏死）；乳头状癌与 MET 信号相关；嫌色细胞癌与线粒体功能缺陷相关。肾癌经血行转移至肺、骨、肝、脑，静脉瘤栓可延伸至下腔静脉。","dx":{"criteria":["影像学诊断：增强 CT 或 MRI 见皮质期强化明显（增幅 >15 HU，ccRCC 常 >60 HU）、实质期与排泄期减弱（「快进快出」）","典型影像特征：富血供、假包膜、中央坏死、静脉瘤栓；乳头状癌强化弱，易与肾盂癌混淆","组织学确诊：病理为金标准；拟行主动监测、消融或转移性病变需分子分型时行穿刺活检","小肾癌（≤4 cm）需与血管平滑肌脂肪瘤（CT 见 <−20 HU 的脂肪成分）鉴别，避免过度治疗","分期：增强 CT 评估 T（是否突破包膜、肾静脉/下腔静脉瘤栓），CT 胸腹与骨显像评估 M","副肿瘤综合征：高血压（肾素）、红细胞增多、高钙、发热、肝功能异常（Stauffer 综合征）"],"workup":["血常规、肾功能、电解质、肝功能、血红蛋白、碱性磷酸酶（怀疑骨转移）","增强 CT 胸腹盆（评估碘过敏史与肾功能）；禁忌增强者用 MRI 或超声造影","鉴别肾盂癌或诊断困难：CT 尿路成像（CTU）或输尿管镜","核素骨显像或 PET 用于可疑转移；脑 MRI 用于神经系统症状","遗传评估：年轻发病、双侧/多发、家族史者查 VHL/FH 等基因","术后随访：腹部影像（超声/CT）与胸部影像、血肌酐与尿常规"],"grading":"TNM（第 8 版）：T1a ≤4 cm，T1b 4–7 cm；T2a 7–10 cm，T2b >10 cm；T3 侵及肾周脂肪或肾静脉/下腔静脉或集合系统；T4 侵犯肾上腺/超出肾周筋膜。WHO/ISUP 核分级 1–4 级；肉瘤样、横纹肌样分化提示预后差。转移期按 IMDC 危险分层（低/中/高危）。"},"ddx":[{"name":"膀胱癌或肾盂尿路上皮癌（ur_bca）","point":"与本类 ur_bca 的鉴别点：尿路上皮癌多位于肾盂/输尿管、向腔内生长并伴输尿管积水，强化轻中度、密度低于皮质；肾细胞癌来自肾实质、强化明显快进快出、常有假包膜；免疫组化 PAX8/RCC/CD10 与 GATA3/uroplakin 可区分。"},{"name":"复杂尿路感染/肾脓肿（ur_uti）","point":"与本类 ur_uti 的鉴别点：肾脓肿表现为发热腰痛、脓尿、CT 见环形强化低密度区，抗感染+穿刺引流后缩小；肾癌多无发热脓尿，有强化实性成分。"},{"name":"血管平滑肌脂肪瘤（AML）","point":"CT 见脂肪密度（<−20 HU）即可诊断 AML；乏脂肪 AML 强化明显易误诊肾癌，需多期增强与 MRI 化学位移成像。"},{"name":"复杂性肾囊肿（Bosniak Ⅲ–Ⅳ）","point":"Bosniak Ⅰ/Ⅱ 为良性；Ⅲ 类壁/分隔增厚强化，Ⅳ 类含实性强化成分，后者按肾癌处理。"},{"name":"肾转移瘤（肺癌/黑色素瘤）","point":"多发、双侧、无假包膜，有原发肿瘤史，强化程度与原发灶相似；需全身评估与穿刺确诊。"},{"name":"肾淋巴瘤","point":"CT 表现为肾内浸润性低强化肿块、多发结节，常伴腹膜后淋巴结肿大；活检可确诊，以化疗为主。"},{"name":"肾上腺肿瘤/嗜铬细胞瘤","point":"位于肾上腺，有阵发高血压、心悸、出汗发作，儿茶酚胺/甲氧基肾上腺素升高；位置与肾实质分界清楚。"}],"tx":{"drug":[{"name":"帕博利珠单抗+阿昔替尼（一线转移性 ccRCC）","dose":"帕博利珠单抗 200 mg 静滴 q3 周（或 400 mg q6 周）联合阿昔替尼 5 mg bid 口服","note":"一线首选免疫+抗血管联合，显著延长 PFS/OS；需监测免疫相关不良事件（甲状腺、结肠炎、肝炎）与血压","renal":"轻中度无需调整，重度遵说明书","hepatic":"阿昔替尼重度肝损减量；免疫性肝炎需激素","interact":"阿昔替尼为 CYP3A4 底物，避免强抑制剂/诱导剂"},{"name":"舒尼替尼","dose":"50 mg qd 口服，服 4 周停 2 周（或 37.5 mg 连续）","note":"TKI 用于转移性 RCC；主要毒性为疲乏、手足皮肤反应、高血压、甲状腺功能减退与骨髓抑制","renal":"重度肾功能不全减量","hepatic":"重度肝功能不全减量或禁用","interact":"CYP3A4 底物；与 QT 延长药合用注意心电"},{"name":"依维莫司（二线/晚期）","dose":"10 mg qd 口服","note":"mTOR 抑制剂，用于 TKI 失败后的 mRCC 或部分非透明细胞癌","renal":"轻中度无需调整","hepatic":"轻中度减量，重度禁用","interact":"CYP3A4/P-gp 强抑制剂或诱导剂需调整；增加感染风险与高血糖"},{"name":"纳武利尤单抗（二线免疫）","dose":"240 mg q2 周 或 480 mg q4 周 静滴","note":"PD-1 抑制剂，用于既往抗血管治疗失败的 mRCC；免疫相关不良事件按分级使用糖皮质激素","renal":"轻中度无需调整","hepatic":"免疫性肝炎需停药与激素","interact":"与全身免疫抑制剂合用降低疗效；与其他免疫治疗联用毒性叠加"},{"name":"肾脏术后镇痛","dose":"对乙酰氨基酚 0.5–1 g q6h（最大 4 g/d）；阿片类药物按需，遵说明书","note":"根治性/部分肾切除后镇痛，避免肾毒性药物，尤其孤立肾或 CKD 患者","renal":"NSAIDs 在 eGFR <30 禁用；阿片类减量","hepatic":"肝功能不全对乙酰氨基酚减量","interact":"阿片类与镇静药联用注意呼吸抑制"}],"nonDrug":["局限性肾癌：部分肾切除（≤7 cm、单侧、位置合适可保留足够肾实质）为首选，减少 CKD 与心血管事件","根治性肾切除：肿瘤巨大、中央型、侵入肾窦或部分切除困难者","主动监测：≤3 cm、高龄或合并症重、生长缓慢的小肾癌可随访观察","射频/微波消融：手术高危或拒绝手术的 ≤3–4 cm 小肾癌，需定期影像随访","静脉瘤栓：肾切除+瘤栓取出（可联合血管外科/体外循环）","转移性肾癌：体能好、转移负荷低者可减瘤性肾切除；寡转移可转移灶切除或立体定向放疗","术后随访：低危每年腹部影像+胸部影像，高危每 3–6 个月，持续 5 年以上"],"life":["戒烟，控制体重与血压（术后心血管事件是主要死亡原因之一）","保护肾脏：控制蛋白、避免肾毒性药物、充足饮水","术后定期复查腹部/胸部影像与血肌酐、尿常规","靶向/免疫治疗期间监测血压、甲状腺功能、血糖与免疫不良症状","单肾患者避免严重外伤与高危运动","遗传性肾癌家系成员进行基因筛查与定期影像随访"]},"prog":"局限性肾癌根治性切除后 5 年生存率约 70%–90%；T1 期 >90%，T3/T4 期约 30%–70%。转移性肾癌中位 OS 由 1 年提升至 3–5 年，IMDC 低危可达 >5 年。ISUP 4 级、肉瘤样分化、静脉瘤栓、骨/脑转移为不良预后因素。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·肾癌","中国肾癌诊治指南（中华医学会泌尿外科学分会，2019）","中国转移性肾癌诊疗指南（CSCO，2021）","欧洲泌尿外科学会（EAU）肾细胞癌指南 2024","美国国家综合癌症网络（NCCN）肾癌指南 2024"]},{"id":"ur_bca","name":"膀胱癌","aka":["膀胱尿路上皮癌","Bladder Cancer","Urothelial Carcinoma","非肌层浸润性膀胱癌"],"rank":2,"basic":{"define":"起源于膀胱尿路上皮的恶性肿瘤，约 90% 为尿路上皮癌，少数为鳞癌、腺癌与肉瘤；按非肌层浸润性（NMIBC，Ta/T1/CIS，约 75%）与肌层浸润性（MIBC，T2 及以上）区分治疗路径。","risk":["吸烟（最重要可归因因素）","职业性芳香胺暴露（染料、橡胶、皮革、印刷业），潜伏期 10–20 年","长期滥用含非那西丁的镇痛药、环磷酰胺化疗史","盆腔放疗史、慢性膀胱炎症/血吸虫感染（鳞癌）",">60 岁、男性（男女约 3–4:1）","反复泌尿系结石与感染、长期留置导尿管"],"epi":"我国膀胱癌发病率约 6–8/10 万，男性居泌尿系肿瘤前列，发病年龄 50–80 岁；NMIBC 复发率可达 50%–70%，进展率 10%–30%；MIBC 根治性切除后 5 年生存率约 50%–60%。"},"patho":"两条途径：多数 NMIBC 为 FGFR3 突变、PI3K 通路激活的乳头状、低级别病变，复发多见；MIBC 多为 TP53、RB1 失活的扁平状高级别病变，易进展。肿瘤浸润肌层后经淋巴与血行转移至盆腔淋巴结、肺、骨、肝。鳞癌与慢性炎症/血吸虫相关。","dx":{"criteria":["典型表现：间歇性、无痛性全程肉眼血尿（约 85% 患者就诊时存在），可伴血块、尿路刺激症状；血尿程度与肿瘤大小不相关","膀胱镜+活检为确诊金标准：可见乳头状或广基、蕨样肿物；活检明确分级与是否侵入肌层","尿细胞学：高级别肿瘤敏感度较高，可辅助 CIS 诊断","影像：CTU 或 MRU 评估上尿路有无同时性肿瘤；MRI 评估肌层浸润程度，CT 增强评估淋巴结与转移","尿肿瘤标志物：NMP22、BTA、UroVysion（FISH）用于复发监测，不能替代膀胱镜","CIS（原位癌）：表现隐匿，细胞学阳性而膀胱镜仅见红斑，需多点随机活检"],"workup":["膀胱软镜（蓝光/窄带成像提高检出率）+ 组织活检","电切标本病理：WHO 2004/2016 分级（低/高级别）、T 分期、有无 CIS、淋巴血管侵犯","TURBT 后 2–6 周二次电切：T1 或高级别、电切不全或标本无肌层者，明确是否残余与升级（约 10%–30% 升级为 T2）","肌层浸润评估：MRI（VI-RADS）或重复电切示肌层受累","胸腹盆 CT 增强评估转移，术前查肌酐与尿培养","上尿路评估：CTU 或肾盂造影，排除上尿路同时性肿瘤（约 2%–5%）"],"grading":"TNM：Ta 非浸润乳头状癌；Tis 原位癌（CIS）；T1 侵及黏膜下结缔组织；T2a/T2b 侵及肌层内半/外半；T3 侵及膀胱周围脂肪；T4 侵犯邻近器官。分级：低级别/高级别（WHO 2004）。NMIBC 风险分层：低危（单发 Ta 低级别 ≤3 cm）、中危（多发/复发 Ta 低级别）、高危（T1、高级别、CIS、多发复发、>3 cm）。"},"ddx":[{"name":"肾癌或上尿路尿路上皮癌（ur_rcc）","point":"与本类 ur_rcc 的鉴别点：肾癌多无肉眼血尿或为全程血尿伴腰痛，CT 见肾实质强化占位；膀胱癌以无痛性肉眼血尿为主要表现但膀胱镜见膀胱内肿物，影像双肾无实性占位，CTU 用于排除同时性上尿路肿瘤。"},{"name":"复杂尿路感染/出血性膀胱炎（ur_uti）","point":"与本类 ur_uti 的鉴别点：尿频尿急尿痛明显、尿培养阳性，血尿伴脓尿、抗感染后血尿消失；膀胱镜见弥漫充血而非乳头状肿物。"},{"name":"膀胱结石","point":"排尿痛向阴茎头放射、排尿中断、超声见强回声伴声影，膀胱镜可见活动性结石，无肿瘤组织。"},{"name":"前列腺增生/前列腺癌出血","point":"男性血尿伴 LUTS，DRE 前列腺增大或结节、PSA 升高，膀胱镜见前列腺出血点而无膀胱肿物。"},{"name":"放射性膀胱炎","point":"有盆腔放疗史，血尿间歇发作，膀胱镜见黏膜弥漫充血、血管扩张、溃疡，无新生肿物。"},{"name":"膀胱子宫内膜异位症","point":"育龄女性，血尿与月经周期相关，膀胱镜见紫蓝色结节，活检示子宫内膜腺体与间质。"},{"name":"膀胱鳞癌/腺癌（少见）","point":"鳞癌常与慢性炎症/血吸虫相关，腺癌与脐尿管或腺性膀胱炎相关；免疫组化 GATA3 阳性率较低，生物学行为不同。"}],"tx":{"drug":[{"name":"吉西他滨+顺铂（新辅助/转移）","dose":"吉西他滨 1000 mg/m² 静滴 d1、d8，顺铂 70 mg/m² d1，q21d","note":"MIBC 新辅助（3–4 周期）或转移性尿路上皮癌一线；需水化与止吐，监测血肌酐与听力","renal":"CrCl <60 顺铂减量或改用卡铂；<30 禁用顺铂","hepatic":"肝功异常减量","interact":"氨基糖苷类增加耳/肾毒性；与甲氨蝶呤、紫杉类联用注意骨髓抑制"},{"name":"卡介苗（BCG）膀胱灌注（NMIBC 高危）","dose":"诱导期 120 mg（或 81 mg）膀胱内灌注 q1 周×6 周，维持期按方案（如 3 周×3 次，间隔 3/6/12 个月）；每次保留 1–2 h","note":"高危 NMIBC 减少复发与进展的金标准；灌注后出现发热、流感样症状需排除播散性 BCG 感染","renal":"局部灌注，肾功能不全者遵说明书","hepatic":"免疫抑制状态者禁用","interact":"免疫抑制剂降低疗效并增加感染风险；膀胱穿孔/活动性感染时禁灌注"},{"name":"吡柔比星（TURBT 后即刻灌注）","dose":"吡柔比星 30 mg 溶于 50 mL 生理盐水，术后 24 h 内（尽量 6 h 内）单次灌注，保留 30–60 min","note":"降低低危 NMIBC 复发；需在无膀胱穿孔、无大量血尿时进行","renal":"肾功能不全慎用","hepatic":"重度肝功不全慎用","interact":"避免与其他蒽环类心脏毒性药物联用"},{"name":"表柔比星（灌注化疗）","dose":"表柔比星 50 mg 溶于 50 mL 生理盐水膀胱内灌注，保留 30–60 min，按方案每周 1 次×8 次后维持","note":"中危 NMIBC 灌注化疗备选；膀胱刺激症状较吡柔比星明显","renal":"肾功能不全慎用","hepatic":"重度肝功不全慎用","interact":"避免与其他蒽环类药物联用"},{"name":"帕博利珠单抗/阿替利珠单抗（BCG 无应答/晚期）","dose":"帕博利珠单抗 200 mg 静滴 q3 周；阿替利珠单抗 1200 mg q3 周","note":"用于 BCG 无应答的高危 NMIBC（拒绝或不适合膀胱切除）或晚期尿路上皮癌；需监测免疫相关不良事件","renal":"轻中度无需调整","hepatic":"免疫性肝炎需激素处理","interact":"与免疫抑制剂合用疗效下降"},{"name":"恩诺单抗（后线转移性）","dose":"1.25 mg/kg 静滴 d1、d8、d15，q28d（二线）","note":"抗体偶联药物，用于铂类失败后的转移性尿路上皮癌；注意周围神经病变与眼毒性","renal":"eGFR <30 慎用","hepatic":"轻中度无需调整，重度慎用","interact":"与强 CYP3A4 诱导剂合用疗效下降"}],"nonDrug":["TURBT：NMIBC 标准治疗，需完整切除肿瘤至肌层（整块切除更佳），高危者 2–6 周二次电切","低危 NMIBC：TURBT+术后单次即刻灌注，3 个月及 1 年膀胱镜随访","中危 NMIBC：TURBT+术后灌注化疗或 BCG 维持 1 年","高危 NMIBC（T1、高级别、CIS）：BCG 诱导+维持；BCG 无应答或不耐受者行根治性膀胱切除","MIBC：根治性膀胱切除+尿路改道（回肠导管/原位新膀胱）+盆腔淋巴结清扫，可加新辅助化疗","不能手术的 MIBC：根治性放化疗（放疗+顺铂/氟尿嘧啶），或最大程度 TURBT 后联合放化疗","转移性尿路上皮癌：一线铂类联合化疗，维持免疫治疗；后线 ADC 或 FGFR 抑制剂（FGFR3 突变）","随访：NMIBC 高危每 3 个月膀胱镜×2 年，后每 6 个月；MIBC 术后每 3–6 个月影像与尿检"],"life":["戒烟，避免职业性芳香胺暴露，多饮水（2–3 L/d）","减少膀胱刺激物（咖啡、酒精、辛辣）","出现血尿立即就诊，不得因「无痛」延误","灌注治疗期间多饮水，关注发热与膀胱刺激症状","膀胱切除术后造口/新膀胱护理培训，定期肾功能与影像随访","高危患者长期规律膀胱镜随访，每年 CTU 注意上尿路复发"]},"prog":"NMIBC 5 年复发率 50%–70%，进展率 10%–30%；高危 T1 与 CIS 进展风险最高。MIBC 根治性切除后 5 年生存率约 50%–60%，T3–T4 或淋巴结阳性者降至 30% 以下；转移性中位 OS 约 12–18 个月（含免疫维持者更长）。多发、高级别、CIS、淋巴血管侵犯是复发与进展的主要危险因素。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·膀胱癌","中国膀胱癌诊治指南（中华医学会泌尿外科学分会，2019）","欧洲泌尿外科学会（EAU）非肌层浸润性膀胱癌指南 2024","欧洲泌尿外科学会（EAU）肌层浸润性与转移性膀胱癌指南 2024","美国国家综合癌症网络（NCCN）膀胱癌指南 2024"]},{"id":"ur_uti","name":"复杂尿路感染","aka":["复杂性尿路感染","cUTI","复杂性尿感","导管相关尿路感染","Complicated UTI"],"rank":3,"basic":{"define":"存在尿路结构或功能异常（梗阻、结石、肿瘤、畸形、神经源性膀胱、留置导管或支架、尿流改道）或宿主因素（糖尿病、免疫抑制、肾功能不全、妊娠、男性）的尿路感染，病原谱更广且常为多重耐药菌，需影像评估与解除易感因素。","risk":["尿路梗阻：结石、UPJ 狭窄、前列腺增生、肿瘤压迫","留置导尿管、双 J 管、肾造瘘或尿流改道（生物膜形成）","糖尿病（尤其血糖控制差者）","免疫抑制：激素、化疗、移植后、HIV","神经源性膀胱、膀胱输尿管反流、妊娠","既往抗菌药物暴露与多重耐药菌定植（ESBL/CRE）","男性、高龄、长期护理机构居住者"],"epi":"女性一生中约 50% 发生尿路感染，其中约 25% 会复发；留置导尿管者导管相关尿路感染（CAUTI）发生率为每 1000 导管日 2–5 例，长期留置者几乎普遍存在菌尿。我国住院尿路感染中产 ESBL 肠杆菌比例逐年升高，复杂尿路感染耐药率明显高于单纯性。"},"patho":"病原以大肠埃希菌为主（约 70%–80%），复杂病例中克雷伯菌、变形杆菌、铜绿假单胞菌、肠球菌与念珠菌比例升高。导管与支架表面形成生物膜，使细菌耐药并反复再发；梗阻使局部淤积与压力升高，促进细菌增殖与返流；糖尿病与免疫抑制降低局部防御。多重耐药（ESBL、碳青霉烯酶）常经质粒传播。","dx":{"criteria":["症状：发热、寒战、腰痛、尿频尿急尿痛、下腹不适；老年者常表现为意识改变、乏力或食欲下降","尿常规：脓尿（WBC ≥10/HPF）+ 亚硝酸盐/白细胞酯酶阳性支持诊断","尿培养：清洁中段尿 ≥10⁵ CFU/mL（有症状者 ≥10³ CFU/mL 也可考虑）；留置导管者须更换新管后取标本；「有症状+培养阳性」方可诊断","无症状菌尿一般不治疗，妊娠与泌尿外科手术前除外","血培养：发热、寒战或拟住院者 2 套（尿源性脓毒症时必做）","影像：超声首选排除梗阻；CT 增强评估肾脓肿、气肿性感染、复杂结石；CTU 评估解剖异常","耐药风险分层：近期住院、3 个月内抗菌药使用、既往 ESBL/CRE 检出、长期护理者按多重耐药处理"],"workup":["尿培养+药敏（治疗前采集，不得因急于用药而省略）","血常规、CRP、PCT、肌酐、电解质、肝功、血糖与酮体","泌尿系超声（肾积水、结石、脓肿）；复杂病例行 CT 增强","基础疾病评估：糖尿病控制、神经源性膀胱、前列腺排尿梗阻、结石负荷","评估是否需要引流：梗阻、脓肿、气肿性感染、感染性结石","妊娠：尿培养阳性即治疗（无症状菌尿也需治疗），避免喹诺酮与四环素类"],"grading":"按部位：下尿路（膀胱炎）、上尿路（肾盂肾炎、肾脓肿）、尿源性脓毒症；按风险：复杂性尿路感染（伴结构/功能异常或宿主因素）、导管相关尿路感染、复发性尿路感染（≥3 次/年或 ≥2 次/6 个月）。多重耐药按药敏分级（ESBL、CRE、产碳青霉烯酶）。"},"ddx":[{"name":"膀胱癌（ur_bca）","point":"与本类 ur_bca 的鉴别点：膀胱癌以无痛性肉眼血尿为主，可继发感染但尿培养阴性或仅低度生长，膀胱镜见肿物；尿路感染以脓尿与培养阳性为主，血尿通常随抗感染消失，持续血尿须膀胱镜排除肿瘤。"},{"name":"肾细胞癌伴发热（ur_rcc）","point":"与本类 ur_rcc 的鉴别点：肾癌可有发热（副肿瘤），但脓尿与尿培养阴性，影像见强化实性占位而非脓腔。"},{"name":"尿路结石合并梗阻","point":"结石本身可有镜下血尿与绞痛但尿培养常阴性、无发热；合并发热寒战+脓尿+肾积水时即为感染性梗阻，需先引流。"},{"name":"急性阑尾炎/盆腔炎","point":"可有发热腹痛，但尿常规多正常或轻度异常，尿培养阴性，超声/CT 见阑尾增粗或盆腔积液。"},{"name":"泌尿系结核","point":"慢性病程、无菌性脓尿（多次培养阴性）、尿抗酸染色或结核培养阳性，CT 见肾盏虫蚀样改变、狭窄与钙化。"},{"name":"间质性膀胱炎/膀胱疼痛综合征","point":"慢性盆腔痛、尿频尿急但尿培养反复阴性，膀胱镜见 Hunner 溃疡；需排除感染后诊断。"},{"name":"药物性/放射性膀胱炎","point":"有环磷酰胺化疗或盆腔放疗史，血尿与刺激症状明显而培养阴性，膀胱镜见弥漫充血或放射性改变。"}],"tx":{"drug":[{"name":"左氧氟沙星","dose":"750 mg qd 静滴或口服（或 500 mg qd）；轻中度 500 mg qd 口服，肾盂肾炎疗程 7–10 d","note":"仅用于药敏敏感的社区获得性复杂尿路感染，当地喹诺酮耐药率高时不宜经验用药；注意肌腱与 QT 延长风险","renal":"CrCl 20–49：首剂 500 mg 后 250 mg q24h；CrCl <20：250 mg q48h","hepatic":"轻度无需调整，重度慎用","interact":"与含铝/镁抗酸剂、铁剂、钙剂同服降低吸收，间隔 2 h；与华法林、茶碱、QT 延长药合用需注意"},{"name":"头孢曲松（非产 ESBL 社区感染）","dose":"1–2 g 静滴 q24h，疗程 7–14 d（肾盂肾炎 10–14 d）","note":"用于病房经验性治疗革兰阴性杆菌；ESBL 流行或近期抗菌药暴露者不适用","renal":"无需调整","hepatic":"无需调整","interact":"与含钙输液同管可沉淀，新生儿禁用"},{"name":"哌拉西林他唑巴坦","dose":"4.5 g 静滴 q6h–q8h（延长输注），疗程 10–14 d","note":"医院获得性或疑产 ESBL、混合厌氧感染的经验治疗；药敏后降阶梯","renal":"CrCl 20–40：q8h；CrCl <20：2.25 g q8h；透析后追加","hepatic":"无需调整","interact":"与万古霉素合用增加肾毒性；与华法林合用增加出血"},{"name":"美罗培南（产 ESBL/CRE 高危）","dose":"1 g 静滴 q8h（延长输注 3 h）；CRE 2 g q8h，疗程按药敏 10–14 d","note":"用于产 ESBL/CRE 或既往培养阳性的复杂尿路感染；CRE 首选头孢他啶阿维巴坦等组合","renal":"CrCl 25–50：q12h；CrCl 10–25：q12h 减半剂量","hepatic":"轻中度无需调整","interact":"禁与丙戊酸联用"},{"name":"呋喃妥因","dose":"100 mg qid 或 50 mg qid，疗程 5–7 d（仅限下尿路感染）；长期预防 50–100 mg qn","note":"用于下尿路感染或复发的口服治疗，组织浓度不足以治疗肾盂肾炎","renal":"CrCl <30 禁用（疗效下降且毒性增加）","hepatic":"肝功能障碍或既往肝损伤史者禁用","interact":"含镁抗酸剂及降低胃酸的药物降低吸收；G6PD 缺乏者慎用"},{"name":"磷霉素氨丁三醇","dose":"3 g 单次口服（下尿路感染）；预防可 q10d 或间隔给药，遵说明书","note":"下尿路感染口服替代，对产 ESBL 肠杆菌常有效；不用于上尿路感染的单一治疗","renal":"CrCl <10 避免","hepatic":"无需调整","interact":"与甲氧氯普胺合用可降低血药浓度"},{"name":"氟康唑（念珠菌尿路感染）","dose":"200 mg qd 口服，念珠菌膀胱炎 7–14 d","note":"用于有症状的念珠菌尿路感染；长期留置导管者需同时更换导管，单纯用药无效","renal":"CrCl <50 使用半量","hepatic":"肝功异常需监测；重度肝损禁用","interact":"强 CYP2C9/CYP3A4 抑制剂，与华法林、他汀、QT 延长药合用需注意"}],"nonDrug":["解除易感因素是核心：结石梗阻行引流或取石，前列腺增生者解除梗阻，脓肿行经皮穿刺引流","怀疑 CAUTI 时先更换导尿管，再取标本与治疗；尽早拔除不必要的导管","气肿性肾盂肾炎/肾积脓：超声引导经皮穿刺引流，必要时外科清创或肾切除","反复发作管理：性交后预防、饮水与排尿习惯调整，绝经后女性局部雌激素","不作常规膀胱冲洗；无症状菌尿除妊娠与术前外无需治疗","泌尿外科手术前必须治疗无症状菌尿（术前尿培养阴性方可手术）"],"life":["每日饮水 2–3 L，规律排尿、避免憋尿","注意会阴部清洁，减少导尿管留置时间","糖尿病者严格控制血糖（目标 HbA1c 7% 左右）","充足饮水等非药物措施可辅助减少复发","抗菌药物按疗程完成，不自行停药或换药，防止耐药","复发者行影像学随访，排除梗阻、结石与解剖异常"]},"prog":"及时治疗与解除梗阻者预后良好，多数在 48–72 h 内退热；产 ESBL 或 CRE、合并脓毒症或延迟引流者病死率明显升高。复发性尿路感染 1 年内复发率约 25%–50%；长期留置导管者持续菌尿难以根除，需以控制症状与减少并发症为目标。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版）·泌尿系感染","中国复杂性尿路感染诊断和治疗专家共识（2015）","中国抗菌药物临床应用指导原则（2015 年版）","欧洲泌尿外科学会（EAU）泌尿系感染指南 2023","美国感染病学会（IDSA）导管相关尿路感染指南 2009（2019 更新）"]}]},{"id":"uro_infect_tb","name":"泌尿系感染与结核","rank":4,"summary":"泌尿系结核以顽固膀胱刺激征+无菌性脓尿为线索，查尿抗酸杆菌与 CTU，规范抗结核后按破坏程度手术；急性阴囊疼痛先用多普勒排除扭转；慢性前列腺炎以 III 型为主、按 UPOINT 表型治疗。","compare":[{"diseaseId":"ur_renal_tb","dx":"慢性膀胱刺激征伴无菌性脓尿、终末血尿，尿抗酸杆菌或 TB-DNA 阳性，CTU 见肾盏虫蚀样破坏","key":"无菌性脓尿+普通抗感染无效是最强提示"},{"diseaseId":"ur_epididymitis","dx":"急性阴囊疼痛肿胀伴发热，附睾触痛，多普勒附睾血流增多而睾丸血流正常","key":"先多普勒排除扭转，不凭 Prehn 征放弃影像"},{"diseaseId":"ur_prostatitis","dx":"盆底会阴疼痛伴 LUTS 持续 >3 个月，NIH-CPSI 与 EPS 辅助分型","key":"III 型最常见，EPS 白细胞多不高"}],"diseases":[{"id":"ur_renal_tb","name":"肾结核（泌尿系结核）","aka":["泌尿系结核","肾结核","Renal Tuberculosis"],"rank":1,"basic":{"define":"结核分枝杆菌经血行播散至肾皮质形成的继发性结核，破入肾盂后沿尿路下行累及输尿管、膀胱与生殖系统。","risk":["肺结核或肺外结核病史与密切接触","HIV、糖尿病、长期激素或免疫抑制","营养不良、透析患者"],"epi":"我国为结核中高负担国家，泌尿生殖系结核占肺外结核约 10%–15%，双侧受累约 10%–20%。"},"patho":"菌血症播散至肾小球→皮质结核结节（早期无症状但尿中排菌）→干酪坏死破入肾盏→虫蚀样破坏与钙化（自截肾）。含菌尿下行致结核性膀胱炎，后期纤维化挛缩（容量可 <50 mL）；输尿管受累形成串珠样改变或狭窄致肾积水。","dx":{"criteria":["慢性尿频尿急尿痛（普通抗感染无效）、终末血尿、脓尿，可伴低热盗汗","无菌性脓尿：尿白细胞增多而普通培养反复阴性，尿 pH 偏酸","病原学：晨尿抗酸杆菌涂片 3–5 次、结核分枝杆菌培养、TB-DNA、Xpert MTB/RIF 查耐药","CTU：肾盏变钝、虫蚀样破坏、空洞钙化、串珠样输尿管、膀胱挛缩","核素肾显像评估分肾功能"],"workup":["留晨尿 3–5 次送抗酸杆菌涂片与培养；抗结核前查肝功与视力色觉","排除普通细菌与真菌混合感染；胸片查肺灶"],"grading":"病理分结节型、干酪空洞型、硬化钙化型（自截肾）与全肾破坏型；临床分早期与晚期。"},"ddx":[{"name":"慢性前列腺炎（III 型 CPPS）","point":"与本类中慢性前列腺炎的鉴别点：CPPS 以骨盆痛为主、无结核中毒症状，尿抗酸杆菌阴性"},{"name":"慢性/复杂尿路感染","point":"培养可检出致病菌且抗感染有效；培养阴性、抗感染无效者应查结核"},{"name":"膀胱肿瘤","point":"无痛性肉眼血尿为主，膀胱镜见占位"},{"name":"间质性膀胱炎","point":"疼痛随充盈加重、水扩张见黏膜下出血，结核检查阴性"}],"tx":{"drug":[{"name":"异烟肼（H）","dose":"300 mg（5 mg/kg）po qd 空腹，按方案 6–9 个月","note":"每月查肝功，同服维生素 B6，禁酒","renal":"透析患者遵说明书","hepatic":"转氨酶 >3 倍且伴症状停药","interact":"升高苯妥英、卡马西平、华法林浓度"},{"name":"利福平（R）","dose":"450–600 mg（10 mg/kg）po qd 空腹，6 个月","note":"尿泪液橙红色需告知","renal":"一般无需调整","hepatic":"重度肝病慎用","interact":"强效诱导剂：降低避孕药、华法林、他汀疗效"},{"name":"吡嗪酰胺（Z）","dose":"1.5–2.0 g qd（25 mg/kg），强化期前 2 个月","note":"监测血尿酸，可致关节痛","renal":"肾功能不全减量或延长间隔","hepatic":"出现黄疸停药","interact":"升高环丙沙星浓度"},{"name":"乙胺丁醇（E）","dose":"0.75–1.0 g qd（15–20 mg/kg），强化期前 2 个月","note":"查视力色觉，视物模糊即停药","renal":"需减量","hepatic":"一般无需调整","interact":"与其他神经毒性药相加"}],"nonDrug":["无功能肾或破坏性空洞反复感染、大出血：抗结核 4–6 周后患肾切除，术前确认对侧肾功能","输尿管狭窄：双 J 管或经皮肾造瘘，必要时狭窄段切除或膀胱瓣成形","挛缩膀胱（<50 mL）：抗结核 4–6 周后膀胱扩大术，术后继续用药 6 个月以上"],"life":["全程规律服药、DOT 督导，禁自行停药","每月复查肝功，每 3–6 个月复查 CTU，疗程后随访至少 2 年","密切接触者筛查；合并 HIV 者同步抗病毒"]},"prog":"规范治疗约 80%–90% 可治愈；未治疗者终致膀胱挛缩、对侧肾积水与尿毒症。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·泌尿系结核）","WHO 结核病整合治疗指南（2022）","EAU Guidelines on Urological Infections 2024"]},{"id":"ur_epididymitis","name":"附睾炎与睾丸炎","aka":["急性附睾炎","附睾睾丸炎","Epididymitis","Orchitis"],"rank":2,"basic":{"define":"病原体经输精管逆行或血行感染引起的附睾/睾丸炎症；腮腺炎病毒性睾丸炎多见于青春期后男性。","risk":["性活跃期无保护性行为（<35 岁以衣原体、淋球菌为主）","导尿、膀胱镜等器械操作","BPH、排尿功能障碍（≥35 岁以肠道阴性菌为主）","未接种腮腺炎疫苗"],"epi":"急诊阴囊疼痛第二位原因；20%–40% 青春期后腮腺炎患者并发睾丸炎，多在腮腺肿大后 4–7 天。"},"patho":"病原自输精管逆行至附睾尾部并蔓延至睾丸，附睾充血水肿、中性粒细胞浸润。病毒性睾丸炎经血行侵犯生精小管，致上皮破坏与萎缩，双侧受累可致不育。","dx":{"criteria":["急性单侧阴囊疼痛肿胀、红肿热，可伴发热与尿道分泌物","附睾肿大压痛（自尾部始）；Prehn 征阳性支持，提睾反射鉴别价值有限","彩色多普勒必查：附睾增大、血流显著增多；睾丸血流减少提示扭转","尿常规尿培养；<35 岁查衣原体与淋球菌；CRP","腮腺炎性睾丸炎有腮腺肿大史伴淀粉酶升高"],"workup":["急诊先用多普勒排除睾丸扭转","查 AFP/hCG/LDH 与超声排除睾丸肿瘤","性伴侣同治；老年或有梗阻者评估 BPH"],"grading":"按病因分细菌性与病毒性；按病程分急性（<6 周）与慢性（>6 周）。"},"ddx":[{"name":"慢性前列腺炎（III 型 CPPS）","point":"与本类中慢性前列腺炎的鉴别点：CPPS 以会阴盆底疼痛为主，阴囊无急性红肿，附睾血流正常"},{"name":"睾丸扭转","point":"<25 岁突发剧痛伴呕吐、睾丸上抬、血流消失，高度怀疑即刻探查"},{"name":"睾丸肿瘤","point":"无痛硬块、超声实性低回声、标志物可升高；抗感染 2–4 周不消退须重查"},{"name":"睾丸附件扭转","point":"疼痛在上极、见「蓝点征」，睾丸血流正常"}],"tx":{"drug":[{"name":"多西环素（疑性传播病原）","dose":"100 mg po bid，10–14 天","note":"覆盖衣原体，性伴侣同治","renal":"肾功能不全慎用","hepatic":"严重肝病禁用","interact":"与抗酸药、钙铁剂间隔 2 h"},{"name":"头孢曲松（淋球菌）","dose":"1 g im 或 iv 单次，后续口服按指南","note":"青霉素严重过敏者慎用","renal":"无需调整","hepatic":"一般无需调整","interact":"禁与含钙输液同瓶"},{"name":"左氧氟沙星（肠道阴性菌）","dose":"500 mg po qd，10–14 天","note":"癫痫、主动脉瘤者慎用，<18 岁一般不用","renal":"CrCl <50 mL/min 减量","hepatic":"出现黄疸停药","interact":"与制酸剂间隔 2 h；慎与 QT 延长药联用"},{"name":"阿莫西林克拉维酸（器械操作后）","dose":"按说明书常规成人剂量 po bid–tid，10 天","note":"青霉素过敏禁用","renal":"调整给药间隔","hepatic":"肝病史慎用","interact":"增强华法林作用"},{"name":"布洛芬等 NSAIDs","dose":"按说明书常规剂量 5–7 天","note":"镇痛消肿，与抗凝药合用增加出血","renal":"CrCl <30 mL/min 避免","hepatic":"失代偿期慎用","interact":"与 ACEI/ARB+利尿剂合用风险增加"}],"nonDrug":["卧床、阴囊托带抬高、早期冷敷 24–48 h","精索封闭用于剧痛；脓肿形成经阴囊切开引流"],"life":["完成性伴侣治疗，疗程结束 1 周后恢复性生活","48–72 h 无改善须重评（脓肿、扭转、肿瘤、耐药）","治疗后 2–4 周复查超声"]},"prog":"规范抗菌后 1–2 周多数缓解，5%–10% 形成脓肿或转慢性；腮腺炎性睾丸炎约 30%–50% 患侧萎缩。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·附睾睾丸炎）","EAU Guidelines on Urological Infections 2024"]},{"id":"ur_prostatitis","name":"慢性前列腺炎与前列腺脓肿","aka":["慢性前列腺炎","CP/CPPS","NIH-CPSI","前列腺脓肿"],"rank":3,"basic":{"define":"NIH 分四型：I 急性细菌性、II 慢性细菌性、III 慢性前列腺炎/慢性骨盆疼痛综合征（IIIa/IIIb）、IV 无症状炎性；临床以 III 型为主。前列腺脓肿是急性细菌性前列腺炎的严重并发症。","risk":["久坐、憋尿、骑行，精神压力","不洁性行为、多性伴","下尿路梗阻、导尿","糖尿病、免疫抑制（脓肿高危）"],"epi":"我国前列腺炎样症状患病率报告 8%–25%，门诊患者 III 型占 90% 以上；脓肿占急性前列腺炎 0.5%–2.5%。"},"patho":"CP/CPPS 涉及隐匿感染、尿液反流、神经病理性疼痛、盆底肌筋膜紧张与心理应激的复合机制（UPOINT 表型）；II 型以革兰阴性菌生物膜形成、药物难渗透为特点。脓肿为腺体内液化脓腔。","dx":{"criteria":["会阴/耻骨上/腰骶部疼痛伴排尿症状，持续 ≥3 个月","NIH-CPSI 总分 0–43（疼痛 0–21+排尿 0–10+生活质量 0–12），≥15 分为中重度","前列腺按摩液（EPS）白细胞 >10/HPF 为炎性（II/IIIa），<10 为 IIIb","EPS 培养与尿培养排除尿路感染","脓肿：高热、会阴剧痛、尿潴留，直肠指诊波动感肿块，超声见液性低回声","PSA 可因炎症升高，抗炎 4–6 周后复查"],"workup":["NIH-CPSI 初诊与随访评分","EPS 常规与培养、性传播病原检测","经直肠超声评估体积与脓肿；梗阻者查尿流率与残余尿","疑脓肿行盆腔增强 CT/MRI 与血培养"],"grading":"NIH 分型 I–IV；CP/CPPS 用 UPOINT（排尿、心理、器官特异、感染、神经、肌筋膜）表型指导治疗。"},"ddx":[{"name":"附睾炎与睾丸炎","point":"与本类中附睾炎的鉴别点：阴囊红肿热痛、附睾触痛、血流增多"},{"name":"肾结核","point":"与本类中肾结核的鉴别点：有无菌性脓尿与 CTU 肾盏破坏；CPPS 影像正常"},{"name":"BPH","point":"中老年排尿困难与前列腺增大为主，无显著骨盆痛"},{"name":"前列腺癌","point":"PSA 持续升高、硬结节、MRI PIRADS ≥3，需穿刺确诊"},{"name":"膀胱疼痛综合征（IC/BPS）","point":"疼痛随膀胱充盈出现、排尿后缓解"}],"tx":{"drug":[{"name":"坦索罗辛","dose":"0.2 mg po qn，可增至 0.4 mg","note":"伴排尿症状者主力药，注意体位性低血压","renal":"重度肾功能不全慎用","hepatic":"重度肝功不全慎用","interact":"与 PDE5 抑制剂合用注意低血压"},{"name":"左氧氟沙星","dose":"500 mg po qd，II 型 4–6 周；III 型仅病原阳性时 2–4 周","note":"<18 岁与妊娠禁用","renal":"CrCl <50 mL/min 减量","hepatic":"肝功能异常慎用","interact":"与制酸剂间隔 2 h"},{"name":"塞来昔布","dose":"200 mg po qd–bid，2–4 周","note":"疼痛为主者；磺胺过敏禁用","renal":"CrCl <30 mL/min 避免","hepatic":"重度肝病禁用","interact":"与抗凝药合用出血风险增加"},{"name":"米诺环素或阿奇霉素","dose":"米诺环素 100 mg po bid 2 周，或阿奇霉素按说明书","note":"仅病原阳性时使用","renal":"肾功能不全调整","hepatic":"严重肝病慎用","interact":"与制酸剂铁剂间隔服用"},{"name":"头孢曲松+甲硝唑（脓肿）","dose":"头孢曲松 2 g iv qd+甲硝唑 0.5 g iv q8h，据药敏调整，2–4 周","note":"引流后仍须足疗程","renal":"按肌酐清除率调整","hepatic":"甲硝唑肝功能不全减量","interact":"甲硝唑停药 3 天内禁酒"}],"nonDrug":["温水坐浴每日 15–20 min，避免久坐与长时间骑行","盆底物理治疗与生物反馈、心理干预；前列腺按摩每周 1–2 次（II/IIIa 部分获益）","脓肿：超声引导经直肠或经会阴穿刺引流，失败者经尿道去顶"],"life":["规律作息，减少久坐憋尿与饮酒辛辣","每 1–3 个月复查 NIH-CPSI","PSA 异常者抗炎后复查，仍高者行 MRI/穿刺"]},"prog":"CP/CPPS 约 1/3 患者 1 年内显著缓解但易复发；脓肿充分引流治愈率 >80%。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·前列腺炎）","慢性前列腺炎/慢性骨盆疼痛综合征诊治中国专家共识（2019）","EAU Guidelines on Urological Infections 2024"]}]},{"id":"uro_congenital_func","name":"先天与功能泌尿","rank":5,"summary":"先天畸形重在时机：隐睾 6–12 月龄内固定，尿道下裂 6–18 月龄一期成形并禁割包皮；精索静脉曲张仅在有精液异常、睾丸萎缩、疼痛或睾酮低时手术；睾丸肿瘤先查标志物与阴囊超声，经腹股沟根治切除后按分期选 RPLND 或化疗；女性 SUI 先做尿动力学区分 UDS 与 ISD，盆底肌训练为基础，TVT/TOT 用于中重度。","compare":[{"diseaseId":"ur_cryptorchidism","dx":"阴囊内触不到睾丸，6 月龄后仍未下降，超声/腹腔镜定位","key":"手术 6–12 月龄（最迟 18 月龄）"},{"diseaseId":"ur_hypospadias","dx":"尿道口位于腹侧，伴阴茎下弯与背侧帽状包皮","key":"6–18 月龄一期成形，禁割包皮"},{"diseaseId":"ur_varicocele","dx":"立位 Valsalva 可及蚯蚓状静脉团，彩超内径 >3 mm 与反流 >1 s，左侧为主","key":"仅伴精液异常、睾丸萎缩、疼痛或睾酮低者手术"},{"diseaseId":"ur_testis_tumor","dx":"无痛性睾丸硬结节，超声实性低回声，AFP/hCG/LDH 升高，腹部 CT 评估腹膜后淋巴结","key":"禁穿刺，经腹股沟根治切除后按分期选择 RPLND 或化疗"},{"diseaseId":"ur_sui","dx":"腹压增高时漏尿，尿动力学示 Valsalva 漏尿而逼尿肌无收缩","key":"尿动力学区分尿道过度活动与括约肌缺陷决定术式"}],"diseases":[{"id":"ur_cryptorchidism","name":"隐睾（睾丸未降）","aka":["隐睾","睾丸未降","Cryptorchidism","Undescended Testis"],"rank":1,"basic":{"define":"睾丸未按正常途径下降至阴囊底部，位于腹腔、腹股沟管或阴囊上方；6 月龄后仍未下降即诊断成立。","risk":["早产与低出生体重（最重要因素）","母亲孕期吸烟、内分泌干扰物暴露","家族史；合并疝、Kallmann 综合征","合并尿道下裂提示 DSD 可能"],"epi":"足月男婴发生率约 3%–4%，早产儿可达 30%；1 岁时约 1%；单侧约 80%。"},"patho":"腹腔与腹股沟温度比阴囊高 2–4 ℃，致生精小管发育受损、生殖细胞凋亡增加；睾丸生殖细胞肿瘤相对风险增至约 3–5 倍。","dx":{"criteria":["新生儿阴囊触诊筛查，一侧空虚为提示","温暖环境平卧或交叉腿位由外环向下触诊，区分可触及型与不可触及型","6 月龄后仍未在阴囊内即确诊","不可触及者腹腔镜为金标准：血管入内环或见盲端","双侧不可触及：hCG 刺激试验、AMH，必要时核型分析"],"workup":["记录睾丸位置与体积、是否合并尿道下裂","评估鞘状突未闭/腹股沟疝（可同期处理）","疑 DSD 转多学科行核型与激素评估"],"grading":"按可触及性分可触及型与不可触及型；按侧别分单侧/双侧。回缩性睾丸仅需随访。"},"ddx":[{"name":"精索静脉曲张","point":"与本类中精索静脉曲张的鉴别点：曲张者睾丸在阴囊内且精索可及静脉团"},{"name":"回缩性睾丸","point":"提睾反射亢进致间歇上提，温室内可推回并停留"},{"name":"睾丸缺如（无睾症）","point":"hCG 刺激无反应、AMH 极低、腹腔镜见盲端血管"},{"name":"腹股沟疝/鞘膜积液","point":"可复性包块或透光积液，睾丸常可触及"}],"tx":{"drug":[{"name":"hCG","dose":"常用 1500–2500 IU/m² 每周 2 次、4–5 周，遵小儿泌尿外科医嘱","note":"不能替代手术；可致暂时阴茎增大与阴毛早现","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["睾丸固定术为金标准，6–12 月龄内完成，最迟 18 月龄","可触及型：精索无张力固定于阴囊中隔肉膜层，同期高位结扎鞘状突","不可触及型：腹腔镜探查与下降固定（Fowler-Stephens）","青春期后发现且睾丸萎缩者可切除（对侧正常者），需知情同意"],"life":["术后第 1 年每 3–6 个月随访，之后每年至青春期","告知恶变风险增加，成年后需自检与泌尿外科随访","18–20 岁查精液分析与睾酮"]},"prog":"6 月龄前手术预后最佳，萎缩率 <5%；12 月龄后手术生精功能受损明显增加。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·隐睾）","EAU/ESPU Paediatric Urology Guidelines 2024","AAP 隐睾评价与治疗临床报告（2014）"]},{"id":"ur_hypospadias","name":"尿道下裂与隐匿性阴茎","aka":["尿道下裂","隐匿性阴茎","Hypospadias","Concealed Penis"],"rank":2,"basic":{"define":"尿道下裂为尿道口位于阴茎腹侧+腹侧下弯（chordee）+背侧帽状包皮三联症；隐匿性阴茎为阴茎体正常但被耻骨前脂肪或皮肤肉膜异常掩盖，按压耻骨上可显露。","risk":["早产、低出生体重","孕期内分泌干扰物、母亲吸烟、年龄偏大","家族史（风险升高约 8–10 倍）","合并隐睾、DSD；隐匿性阴茎与肥胖相关"],"epi":"尿道下裂新生儿发生率约 1/125–1/300，远端型占 50%–70%。"},"patho":"胚胎期尿道沟自会阴向龟头闭合不全→尿道口近端移位；腹侧尿道板与肉膜发育不良形成纤维索带→下弯。隐匿性阴茎为皮肤/浅筋膜附着异常，阴茎体正常。","dx":{"criteria":["尿道口位于腹侧，包皮呈帽状（背侧多、腹侧缺）","脱套后牵引测下弯：轻 <30°、中 30°–60°、重 >60°","记录阴茎长度与阴囊位置（阴囊型/会阴型提示近端型）","近端型+双侧不可触及睾丸高度提示 DSD，查核型与肾上腺激素","隐匿性阴茎：按压脂肪后阴茎体显露、长度正常"],"workup":["出生体检登记尿道口位置与包皮外观并拍照","近端型或合并隐睾：DSD 评估后再手术","术前评估下弯与尿道板质量，决定一期或分期成形","隐匿性阴茎：测显露长度与脂肪厚度，排除小阴茎"],"grading":"按尿道口位置：龟头、冠状沟、阴茎体远/中/近端、阴茎阴囊、阴囊、会阴型；临床分轻/中/重度依据下弯与尿道板是否可保留。"},"ddx":[{"name":"隐匿性阴茎","point":"与本类中隐匿性阴茎的鉴别点：尿道口位置正常、包皮可完整，按压后阴茎显露"},{"name":"小阴茎","point":"长度低于同龄 -2.5 SD 而结构正常、无下弯"},{"name":"蹼状阴茎","point":"阴囊皮肤向腹侧阴茎延伸，尿道口位置正常"},{"name":"性发育异常（DSD）","point":"近端型下裂+隐睾+阴囊融合，需多学科决策"},{"name":"包茎/包皮粘连","point":"包皮口狭窄，尿道口位置正常无下弯"}],"tx":{"drug":[{"name":"短期睾酮（仅阴茎过小者）","dose":"遵说明书与儿童内分泌方案，1 个疗程（1–3 个月）","note":"避免长期使用致骨龄提前","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"遵说明书"},{"name":"术后镇痛解痉","dose":"对乙酰氨基酚/布洛芬按体重；奥昔布宁按说明书","note":"导尿管期用解痉药减轻膀胱痉挛","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["手术时机 6–18 月龄（约 1 岁）","轻中度 TIP/Snodgrass 或 Mathieu/Onlay 一期成形；重度先伸直再分期成形","禁割包皮：包皮是成形首选材料，初诊须告知家属","目标：尿道口正位、勃起下弯 <10°、尿流正常","隐匿性阴茎：轻度减重观察；影响排尿或心理者行脱套+白膜固定+脂肪清除"],"life":["术后导尿 5–7 天，拔管后查尿流率与残余尿","术后 1、3、6、12 个月随访外观、尿线、狭窄与瘘","保持会阴清洁；隐匿性阴茎控制体重"]},"prog":"TIP 一期成形成功率 85%–95%，并发症为尿道瘘（2%–10%）、狭窄（3%–10%）与再次下弯。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·尿道下裂）","EAU/ESPU Paediatric Urology Guidelines 2024","尿道下裂诊疗中国专家共识（2021）"]},{"id":"ur_varicocele","name":"精索静脉曲张","aka":["精索静脉曲张","Varicocele"],"rank":3,"basic":{"define":"精索内蔓状静脉丛异常扩张与反流，左侧占 80%–90%；右侧孤立者须警惕腹膜后或肾占位压迫。","risk":["瘦高体型、长期站立与重体力劳动","腹压增高：便秘、慢性咳嗽","左侧静脉长而垂直、瓣膜缺如"],"epi":"普通男性患病率约 15%，不育男性 35%–40%；双侧约 10%–15%。"},"patho":"静脉瓣功能不全→反流淤血→睾丸温度升高、缺氧与氧化应激→生精小管萎缩、精子 DNA 碎片增加，睾丸体积缩小。","dx":{"criteria":["Dubowitz 分级：Ⅰ Valsalva 可触及；Ⅱ 静立可触及；Ⅲ 视诊可见团块","立位+Valsalva 触诊，仰卧减轻提示原发、不减轻提示继发","彩超：立位 Valsalva 内径 >3 mm、反流 >2 s 为阳性；睾丸体积差 >2 mL 或 20% 为萎缩","精液分析（WHO 第六版）与精子 DNA 碎片","右侧孤立者行腹部增强 CT/MRI"],"workup":["记录分级、侧别与睾丸体积","精液分析禁欲 2–7 天，复查 2 次","查睾酮；疑胡桃夹行左肾静脉超声或 CTA"],"grading":"Dubowitz Ⅰ–Ⅲ 度；分亚临床性与临床性；病因分原发性与继发性。"},"ddx":[{"name":"隐睾","point":"与本类中隐睾的鉴别点：隐睾阴囊空虚、睾丸位于腹股沟"},{"name":"睾丸肿瘤","point":"睾丸内硬结节、超声实性低回声、标志物升高"},{"name":"附睾炎/附睾囊肿","point":"急性触痛伴发热与血流增多；曲张平卧缓解"},{"name":"腹股沟疝","point":"可复性包块降入阴囊、有咳嗽冲击感"}],"tx":{"drug":[{"name":"迈之灵（马栗种子提取物）","dose":"按说明书常规剂量，4–8 周","note":"对精液参数疗效证据有限","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"},{"name":"左卡尼汀/辅酶 Q10","dose":"左卡尼汀 1–2 g 每日分次；辅酶 Q10 按说明书","note":"抗氧化辅助，不能替代手术"}],"nonDrug":["阴囊托带，避免长站、重体力与剧烈骑行","手术适应证：①睾丸萎缩；②少弱精子症合并不孕；③中重度疼痛；④青春期双侧Ⅱ–Ⅲ度；⑤睾酮低下者","显微镜下腹股沟下静脉结扎为金标准（复发 <1%–2%）；介入栓塞为替代"],"life":["术后 3–6 个月复查精液与睾丸体积","不育夫妻同步评估配偶因素"]},"prog":"显微镜结扎术后 60%–70% 精液参数改善、自然妊娠率约提高 2 倍，疼痛缓解 70%–90%。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·精索静脉曲张）","精索静脉曲张诊断与治疗中国专家共识（2015）","EAU Guidelines on Sexual and Reproductive Health 2024"]},{"id":"ur_testis_tumor","name":"睾丸肿瘤","aka":["睾丸生殖细胞肿瘤","Testicular Germ Cell Tumor","TGCT","精原细胞瘤"],"rank":4,"basic":{"define":"起自睾丸生殖细胞（约 95%）的恶性肿瘤，15–35 岁多见；分精原细胞瘤与非精原细胞瘤，多数可治愈。","risk":["隐睾（风险增加 3–5 倍）、睾丸萎缩","一级亲属患病（风险增加 4–8 倍）","对侧睾丸肿瘤史（2%–5%）","早产、低出生体重"],"epi":"我国发病率约 1–3/10 万男性；精原细胞瘤约 50%–60%，总体 5 年生存率 >95%。"},"patho":"生殖细胞经 GCNIS 发展为浸润性肿瘤（常伴 i12p）。精原细胞瘤生长慢、对放化疗敏感、AFP 不升高；非精原细胞瘤易早期转移、AFP/hCG 可升高。淋巴转移先至同侧腹膜后淋巴结；绒毛膜癌以血行转移为主。","dx":{"criteria":["无痛性睾丸硬块、体积增大或沉重感","阴囊超声：实性低回声、血流丰富，可伴微钙化","AFP、β-hCG、LDH：治疗前、术后与随访必查；AFP 升高排除纯精原细胞瘤","胸腹盆增强 CT 评估腹膜后淋巴结（>1 cm 为增大）与肺转移","经腹股沟根治性睾丸切除+病理确诊，禁穿刺","术前精子冻存"],"workup":["术后 3–5 天复查标志物观察半衰期（AFP 5–7 d、hCG 24–36 h）","化疗前查肾功能、血常规、肝功与听力基线","对侧睾丸超声排查同时性病变"],"grading":"TNM+S：Ⅰ 期无转移、Ⅱ 期腹膜后淋巴结、Ⅲ 期远处转移。IGCCCG 风险分层：预后良好（AFP <1000、hCG <5000、LDH <1.5 倍上限，仅肺或腹膜后转移）、中等、预后差（肝脑骨转移或 AFP ≥10000、hCG ≥50000）。"},"ddx":[{"name":"附睾炎与睾丸炎","point":"与本类中附睾炎的鉴别点：有发热红肿触痛且抗感染 2–4 周消退；肿瘤无痛硬块"},{"name":"精索静脉曲张","point":"与本类中精索静脉曲张的鉴别点：曲张为精索静脉团，睾丸内无实性肿块"},{"name":"睾丸扭转","point":"突发剧痛、血流消失；不能排除时手术探查"},{"name":"鞘膜积液/血肿","point":"透光阳性、超声见液性暗区；突发大量积液须排查隐匿肿瘤"},{"name":"淋巴瘤累及睾丸","point":">60 岁双侧无痛肿大、LDH 高而 AFP/hCG 正常"}],"tx":{"drug":[{"name":"BEP（博来霉素+依托泊苷+顺铂）","dose":"3 周期（预后良好）或 4 周期（中/差）：博来霉素 30 U 每周（d1/8/15），依托泊苷 100 mg/m² d1–5，顺铂 20 mg/m² d1–5，每 21 天一周期，按 CSCO/NCCN 与体表面积调整","note":"顺铂充分水化与三联止吐；监测肾功、听力与神经毒性；博来霉素总量一般 ≤400 U 并监测肺功","renal":"顺铂需 eGFR ≥50–60 mL/min，否则减量或换卡铂（AUC 法）","hepatic":"依托泊苷肝功能不全调整","interact":"氨基糖苷类加重肾耳毒性；活疫苗禁用"},{"name":"EP（依托泊苷+顺铂）","dose":"4 周期：依托泊苷 100 mg/m² d1–5，顺铂 20 mg/m² d1–5，每 21 天，按 CSCO/NCCN 调整","note":"Ⅰ 期高危非精原细胞瘤辅助或 ⅡA 精原细胞瘤可选"},{"name":"VIP（依托泊苷+异环磷酰胺+顺铂）","dose":"依托泊苷 75 mg/m² d1–5，异环磷酰胺 1.2 g/m² d1–5+美司钠，顺铂 20 mg/m² d1–5，按 CSCO/NCCN 调整","note":"预后差或复发二线；必须用美司钠防出血性膀胱炎","renal":"两药均需肾功能评估后调整"},{"name":"止吐与支持","dose":"地塞米松 8–12 mg+帕洛诺司琼 0.25 mg+NK1 拮抗剂；G-CSF（如非格司亭 5 μg/kg 皮下）按说明书","note":"按 CSCO 化疗止吐指南预防使用","interact":"阿瑞匹坦抑制 CYP3A4，影响地塞米松剂量"}],"nonDrug":["经腹股沟根治性睾丸切除（高位阻断精索）为首选与分期基础","Ⅰ 期精原细胞瘤：主动监测或单次卡铂 AUC 7 辅助化疗，监测组复发率约 15%–20%","Ⅰ 期非精原细胞瘤：低危监测或 1 周期 BEP；高危 1–2 周期 BEP 或 RPLND","Ⅱ 期：ⅡA/B 精原细胞瘤 3 周期 BEP 或放疗；ⅡA/B 非精原细胞瘤 RPLND 或 3–4 周期 BEP","RPLND：Ⅰ 期高危、化疗后残留（非精原 >1 cm、精原 >3 cm 且 PET 阳性）与畸胎瘤切除","复发/难治：二线化疗、高剂量化疗+自体干细胞移植"],"life":["随访：1–2 年每 3 个月、3–5 年每 6 个月、5 年后每年，含标志物与影像","治疗前精子冻存，化疗后 1–2 年再生育","长期监测心血管风险与第二原发肿瘤"]},"prog":"总体 5 年生存率 >95%（Ⅰ 期 98%–99%），预后良好转移组约 90%、预后差组 50%–70%。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·睾丸肿瘤）","CSCO 睾丸生殖细胞肿瘤诊疗指南（2023）","EAU Guidelines on Testicular Cancer 2024","NCCN Testicular Cancer Guidelines 2024"]},{"id":"ur_sui","name":"女性压力性尿失禁","aka":["压力性尿失禁","SUI","Stress Urinary Incontinence","TVT","TOT"],"rank":5,"basic":{"define":"腹压突增（咳嗽、喷嚏、跳跃、提重物）时尿液不自主漏出而逼尿肌无收缩；须与急迫性与混合性尿失禁鉴别。","risk":["阴道分娩（产程长、巨大儿、器械助产）、多产","绝经后雌激素缺乏与盆底肌力减弱","肥胖（BMI >30）、慢性咳嗽便秘、重体力劳动","盆腔手术与放疗史"],"epi":"我国成年女性尿失禁患病率约 20%–30%，SUI 约占一半，50–59 岁达高峰。"},"patho":"控尿依赖尿道闭合压与「吊床」样中段尿道支撑。盆底肌与筋膜损伤→尿道过度活动型（UDM）；括约肌功能下降→固有括约肌缺陷（ISD，闭合压 <20 cmH₂O），需尿动力学选术式。","dx":{"criteria":["腹压增高时漏尿、无尿急，ICIQ-UI-SF 量化","截石位咳嗽试验阳性；Q-tip 试验评估尿道移动度；POP-Q 评估脱垂","尿常规尿培养排除感染；残余尿 >100 mL 提示排尿功能障碍","尿动力学：Valsalva 漏尿而逼尿肌无收缩，识别 ISD 并排查逼尿肌过度活动","1 小时尿垫试验增重 ≥2 g 为阳性"],"workup":["询问诱因、频率与合并症及用药（α 阻滞剂、利尿剂）","复杂病例（既往盆腔手术/放疗、神经疾病、混合型、拟手术）必须行尿动力学","评估脱垂掩盖型 SUI（子宫托试验）"],"grading":"Ingelman-Sundberg 分度：Ⅰ 度剧烈腹压时偶发漏尿、Ⅱ 度日常活动即漏尿、Ⅲ 度轻微活动或静息即漏尿；分型 UDM、ISD、混合型。"},"ddx":[{"name":"急迫性尿失禁（OAB）","point":"与本大类内 OAB 的鉴别点：漏尿前有尿急、UDS 示逼尿肌过度活动而咳嗽无漏尿；并存称混合性尿失禁"},{"name":"膀胱阴道瘘","point":"持续漏尿与姿势无关，有手术后/放疗史，亚甲蓝试验阳性"},{"name":"尿道括约肌缺陷（ISD）","point":"静息亦漏尿、闭合压 <20 cmH₂O，需选 TVT 而非 TOT"},{"name":"尿路感染","point":"尿频急痛伴脓尿、培养阳性，抗感染后消失"},{"name":"脱垂掩盖型 SUI","point":"脱垂致膀胱颈扭结平时不漏，复位后出现漏尿"}],"tx":{"drug":[{"name":"米拉贝隆（β3 激动剂）","dose":"25 mg po qd，4 周后可增至 50 mg qd；eGFR 15–29 mL/min 或中度肝损最大 25 mg/日","note":"主要针对 OAB 症状，单纯 SUI 疗效有限；用于合并 OAB 或不能手术者，注意血压升高与尿潴留","renal":"eGFR <15 mL/min 及透析不推荐","hepatic":"重度肝损不推荐","interact":"强效 CYP2D6/3A4 抑制剂（如氟康唑）需减量；与地高辛合用需监测"},{"name":"度洛西汀（可选）","dose":"20–40 mg po bid，4 周评估","note":"证据等级低，仅用于不愿或不能手术者","renal":"CrCl <30 mL/min 禁用","hepatic":"肝功能不全慎用/禁用","interact":"禁与单胺氧化酶抑制剂合用"},{"name":"局部雌激素（绝经后）","dose":"雌三醇阴道栓/胶按说明书常规剂量，≥4–6 周","note":"改善黏膜萎缩；乳腺癌与妊娠禁用","renal":"遵说明书","hepatic":"肝功能不全慎用","interact":"遵说明书"}],"nonDrug":["盆底肌训练：每日 3 组、每组 8–12 次，收缩 8–10 s 再放松，持续 8–12 周，配生物反馈","减重 5%–10%、戒烟、治疗慢性咳嗽便秘","阴道子宫托（不愿手术者的替代方案）","尿道中段吊带：TVT（耻骨后）疗效持久，ISD 或既往失败者首选；TOT/TVT-O 穿刺并发症少但腿痛较多、ISD 效果差；用于中重度或保守 8–12 周无效","自体筋膜吊带/Burch 用于重度 ISD；合并脱垂者同期修复","TVT 并发症：膀胱穿孔（1%–5%）、排尿困难、吊带侵蚀"],"life":["治疗前后评估尿垫试验与 ICIQ-UI-SF，监测残余尿","术后 6–8 周避免重体力与性生活，术后 1、3、12 个月复查","维持盆底肌训练与体重控制；告知治愈率约 70%–90%"]},"prog":"盆底肌训练 8–12 周可使 50%–60% 主观改善但需长期维持；吊带术后 1 年治愈率 >80%、5 年约 70%。","refs":["中国泌尿外科和男科疾病诊断治疗指南（2022 版·女性压力性尿失禁）","女性压力性尿失禁诊断和治疗中国指南（2022）","EAU Guidelines on Urinary Incontinence in Adults 2024","AUA/SUFU 女性 SUI 手术治疗指南（2023）"]}]},{"id":"uro_trauma_func","name":"泌尿系统损伤与男性性功能","rank":6,"summary":"泌尿系损伤先判血流动力学与是否有尿外渗：血流不稳者控损伤后择期修复，稳定者按 AAST 分级分层，尿道损伤强调先逆行尿道造影、忌盲目插导尿管。男性勃起功能障碍先筛查心血管、内分泌与药物因素，PDE5 抑制剂为一线并按合并用药禁忌把关。","compare":[{"diseaseId":"ur_uro_trauma","dx":"外伤后血尿（肾损伤 80% 以上）、骨盆骨折伴尿道口滴血与排尿困难（后尿道损伤）、骑跨伤伴会阴血肿（前尿道）、下腹顿挫伴不能排尿（膀胱破裂），CT 造影或逆行尿道造影定位","key":"先稳定血流动力学与排除尿外渗；尿道损伤确诊前不插导尿管"},{"diseaseId":"ur_ed","dx":"持续 3 个月以上不能获得或维持足够勃起、影响性生活，IIEF-5 ≤21 分，可伴夜间勃起消失","key":"ED 是心血管事件的哨兵症状；PDE5 抑制剂禁与硝酸酯类合用"}],"diseases":[{"id":"ur_uro_trauma","name":"泌尿系统损伤（肾/输尿管/膀胱/尿道）","aka":["Renal trauma","Ureteral injury","Bladder rupture","Urethral injury","肾外伤","膀胱破裂","尿道断裂","后尿道损伤"],"rank":1,"basic":{"define":"外力或医源性操作导致肾、输尿管、膀胱、尿道结构与连续性破坏，可表现为血尿、尿外渗、腹膜后或阴囊血肿、排尿困难。按部位分为肾损伤、输尿管损伤（多为医源性）、膀胱损伤（腹膜外型、腹膜内型）与尿道损伤（前尿道：球部、阴茎部；后尿道：膜部、前列腺部）。","risk":["钝性腹部或腰背部外伤（肾损伤占腹部钝性伤 8%–10%）","穿透伤（刀刺、枪弹）：肾与输尿管穿透伤需手术探查率高","骨盆骨折（后尿道损伤发生率约 5%–10%）","骑跨伤（前尿道球部）；骨盆手术、导尿、尿道扩张等医源性因素","盆腔手术（子宫切除、结直肠手术）与放疗后的输尿管损伤","膀胱充盈状态下的下腹部暴力（腹膜内型膀胱破裂）"],"epi":"严重创伤中泌尿系统损伤约占 10%，其中肾损伤最常见（约 60%–80%），其次为膀胱、尿道损伤。骨盆骨折合并后尿道损伤为经典组合，男性多见；女性尿道损伤少见但诊断易延误。"},"patho":"钝性外力致肾实质挫裂、包膜下或肾周血肿，重者肾蒂血管撕裂或肾碎裂；贯通伤呈弹道样组织毁损。输尿管损伤多因术中误扎、电热损伤或撕裂，局部缺血后数日才出现尿瘘。膀胱在充盈时受暴力易致穹顶部腹膜内破裂，尿液入腹腔引起化学性腹膜炎与高钾、高肌酐；骨盆骨折骨刺可致腹膜外破裂，尿液渗入膀胱周围间隙。后尿道在尿生殖膈处受剪切力断裂，断端回缩、血肿位于尿生殖膈以上，尿液不入会阴；前尿道在耻骨联合下方被挤压于硬物上致球部挫裂或断裂，血肿局限于阴囊与会阴（蝶形血肿）。","dx":{"criteria":["外伤病史 + 血尿：肾损伤约 80% 以上有肉眼或镜下血尿；血尿程度与损伤严重度不平行","肾损伤血流动力学不稳定、肉眼血尿或机制提示者行增强 CT（实质期 + 排泄期）；稳定且仅镜下血尿者可观察","膀胱破裂：下腹外伤后不能排尿、导尿引出少量血性尿、注水试验阳性（注入 300 ml 生理盐水回抽量不足或超过）；CT 膀胱造影见造影剂外溢（腹膜内型进入腹腔、腹膜外型局限于膀胱周围）","尿道损伤：尿道口滴血、会阴蝶形血肿、排尿困难或尿潴留、直肠指检前列腺浮动或触不到；耻骨骨折伴上述表现禁忌盲目插导尿管，先逆行尿道造影","输尿管损伤：术中或术后无尿、腰腹痛、引流液肌酐明显高于血清、影像见输尿管梗阻或造影剂外渗"],"workup":["血流动力学评估与创伤初级调查（ABC），先处理威胁生命的损伤","增强 CT 尿路造影：肾损伤分期金标准，可见肾裂伤深度、肾周血肿、是否合并肾蒂伤","逆行尿道造影：尿道损伤定位与判断是否完全断裂，注入 20–30 ml 造影剂，男性取斜位片","膀胱造影或 CT 膀胱造影（延迟 10–15 min 充盈期）","血常规、肾功能、血尿肌酐对比、尿常规","肾动脉造影或介入：怀疑肾蒂损伤、持续血尿或血管性对比剂外渗时"],"grading":"肾损伤 AAST 分级：Ⅰ级 挫伤或包膜下血肿无实质裂伤；Ⅱ级 包膜下血肿或皮质裂伤 <1 cm 不伴尿外渗；Ⅲ级 实质裂伤 >1 cm 未累及髓质；Ⅳ级 裂伤累及集合系统或血管伤、肾段动脉血栓；Ⅴ级 肾碎裂、肾蒂撕裂或肾完全撕脱。膀胱损伤：Ⅰ 挫伤；Ⅱ 腹膜外破裂；Ⅲ 腹膜内破裂；Ⅳ 破裂累及膀胱颈（女性 Ⅴ 级累及阴道或外阴）。尿道损伤按 AAST：Ⅰ 挫伤；Ⅱ 尿道牵拉伤；Ⅲ 前尿道部分断裂；Ⅳ 前尿道完全断裂 <2 cm；Ⅴ 前尿道完全断裂 >2 cm 或累及后尿道。"},"ddx":[{"name":"肾绞痛/输尿管结石（结石大类）","point":"与本科室结石大类（uro_1）的鉴别点：结石为突发腰腹绞痛伴镜下血尿、KUB 或 CT 见高密度结石；外伤性肾损伤有明确外力史、CT 见实质裂伤与肾周血肿。"},{"name":"膀胱肿瘤或尿路感染诱发出血","point":"与 uro_3 中膀胱肿瘤的鉴别点：肿瘤性血尿无外伤史、影像见膀胱内肿物；外伤性血尿须结合 CT 尿路造影定位损伤部位。"},{"name":"骨盆骨折伴腹膜后血肿","point":"骨盆骨折本身可致休克，血肿亦可仅由骨盆静脉丛出血；须用尿道造影与膀胱造影区分是否合并尿路破裂，避免误判为单纯骨折出血。"},{"name":"输尿管医源性损伤与术后肾功能不全","point":"术后少尿需鉴别急性肾损伤；输尿管梗阻者引流液肌酐常显著升高，需影像确认梗阻或尿漏。"}],"tx":{"drug":[{"name":"氨甲环酸","dose":"创伤出血早期 1 g 10 min 内静注，随后 1 g 输注 8 h；遵说明书","note":"用于创伤后大量出血伴高危者，需在伤后 3 h 内启动。","renal":"肾功能不全按说明书调整","hepatic":"遵说明书","interact":"与其他促凝药物叠加需评估血栓风险"},{"name":"头孢呋辛或头孢唑林（预防感染）","dose":"术前 1.5 g 或 2 g 静脉，手术超过 4 h 追加；遵说明书","note":"泌尿系损伤伴尿外渗或手术修复者需预防性抗菌，合并肠道损伤需覆盖革兰阴性菌与厌氧菌。","renal":"肾功能不全按肌酐清除率减量","hepatic":"遵说明书","interact":"与华法林合用可增强抗凝作用"},{"name":"对乙酰氨基酚或阿片类（镇痛）","dose":"对乙酰氨基酚 0.5–1 g q6h，每日不超过 3 g；阿片类按需滴定；遵说明书","note":"疼痛管理以多模式镇痛为主，减少阿片类相关尿潴留与肠麻痹。","renal":"重度肾功能不全减量或延长给药间隔","hepatic":"严重肝功能不全禁用","interact":"阿片类与大剂量镇静药合用加重呼吸抑制"}],"nonDrug":["复苏与损伤控制：血流动力学不稳定者优先止血、纠正休克，肾损伤可先行肾动脉栓塞后择期处理","肾损伤：AAST Ⅰ–Ⅲ 级多保守（卧床、监测血压与血红蛋白），Ⅳ级视情况血块清除与引流，Ⅴ级或肾蒂撕裂行手术探查与修补或肾切除","输尿管损伤：术中即发现者行端端吻合或再植入；术后发现者行经皮肾造瘘引流 + 延期修复","腹膜内型膀胱破裂：急诊剖腹探查修补；腹膜外型可留置导尿管保守引流 10–14 天，伴膀胱颈受累或骨折碎片穿透者手术","尿道损伤：完全断裂者行耻骨上膀胱造瘘或会阴血肿引流，择期行尿道成形术；部分断裂可试插导尿管或尿道会师","严重骨盆骨折合并后尿道损伤需多学科（骨科、泌尿外科、介入）协作"],"life":["保守治疗期间监测血红蛋白、血压与排尿，肾损伤 48 h 内复查 CT 评估血肿扩大或尿外渗","留置导尿管或造瘘管期间保持引流通畅、每日记录尿量与性状","修复后 3–6 个月复查影像（CT 尿路造影或超声）与肾功能，尿道损伤者评估排尿功能与尿道狭窄","尿道损伤后远期尿道狭窄发生率可达 30%–50%，需定期排尿评估，必要时尿道扩张或成形"]},"prog":"肾损伤约 85%–90% 可保守治愈，其中 Ⅰ–Ⅲ 级极少需手术；Ⅴ 级与肾蒂撕脱者肾切除率高达 50% 以上。腹膜内型膀胱破裂及时修补预后良好；后尿道损伤修复后尿道狭窄与尿失禁风险较高。输尿管损伤延迟诊断可致肾单位丢失，应在 1–2 周内处理。","refs":["中华医学会泌尿外科学分会《泌尿系统损伤诊治指南》相关章节","《外科学》第 9 版 泌尿系统损伤","EAU Guidelines on Urological Trauma 2023","AAST Organ Injury Scaling（Kidney、Bladder、Urethra）"]},{"id":"ur_ed","name":"男性性功能障碍与勃起功能障碍","aka":["ED","Erectile dysfunction","勃起功能障碍","阴茎勃起障碍","PE","早泄"],"rank":2,"basic":{"define":"勃起功能障碍（ED）指男性持续不能获得或维持足以完成满意性生活的阴茎勃起，病程通常 ≥3 个月。常与早泄（PE）、性欲减退（性腺功能减退）、射精障碍并存，统称男性性功能障碍。","risk":["年龄：40 岁以上约 40%，60 岁以上过半有不同程度 ED","糖尿病（ED 发生率约 35%–75%，常早于代谢并发症）","高血压、血脂异常、代谢综合征、肥胖与吸烟","冠状动脉疾病与周围动脉病（ED 常为其早期信号）","盆腔手术、放疗或创伤（前列腺癌根治术后）","精神心理因素（焦虑、抑郁、夫妻关系）、抗抑郁药与抗高血压药"],"epi":"我国 40 岁以上男性 ED 患病率约 40%，其中中重度约 15%；早泄患病率约 20%–30%。ED 患者在确诊后平均约 3 年内发生心血管事件的风险显著高于无 ED 者。"},"patho":"勃起依赖海绵体平滑肌舒张、动脉血流增加与静脉回流受限于白膜；一氧化氮经鸟苷酸环化酶升高 cGMP，激活蛋白激酶 G 使平滑肌舒张，PDE5 负责降解 cGMP。血管内皮功能障碍（糖尿病、高血压、吸烟）使 NO 生成减少；海绵体平滑肌纤维化、白膜结构改变或盆腔神经损伤（手术或放疗）致器质性 ED。睾酮不足、高泌乳素血症及焦虑抑制性欲与反射。心理性 ED 多呈突发、晨勃保留、因场景而异。","dx":{"criteria":["症状：性生活时持续不能获得或维持勃起 ≥3 个月，可伴性欲减退、早泄、射精困难","IIEF-5（SHIM）评分：22–25 分无 ED；17–21 分轻度；12–16 分轻中度；8–11 分中度；5–7 分重度","区分心理性与器质性：心理性者为突发、晨间勃起保留、手淫时可勃起、伴焦虑；器质性者渐进、晨勃消失、伴血管病危险因素","夜间阴茎勃起监测（NPT）：正常者 (>3 次/夜，阴茎尖端硬度 ≥70% 持续 ≥10 min) 提示心理性","病因筛查：阴茎海绵体注射血管活性药试验、阴茎彩色多普勒超声（PSV <25–30 cm/s 提示动脉供血不足）","必查：空腹血糖或糖化血红蛋白、血脂、睾酮（晨 8–10 点）、血压与心血管风险评估；早泄诊断按 IELT <1–2 min 伴控制力差与困扰"],"workup":["病史：起病方式、ED 与 PE 合并情况、性欲、晨勃、伴随用药与精神史","IIEF-5 问卷与早泄 PEDT 问卷","体格检查：血压、第二性征、睾丸大小与质地、阴茎弯曲或硬结（Peyronie 病）","实验室：空腹血糖、HbA1c、血脂、睾酮；必要时泌乳素、甲状腺功能","NPT、海绵体多普勒超声或注射试验（鉴别与手术前评估）","心血管风险分层：低危可直接治疗，中危可行运动负荷试验，高危先心内科评估"],"grading":"IIEF-5 分级：22–25 正常；17–21 轻度；12–16 轻中度；8–11 中度；5–7 重度。早泄（PE）按原发与继发分类，或分终身性与获得性，伴或不伴射精控制力差与困扰。按病因分心理性、器质性、混合性。"},"ddx":[{"name":"泌尿系统损伤（ur_uro_trauma）","point":"与本类 ur_uro_trauma 的鉴别点：损伤后 ED 有骨盆外伤或尿道断裂史，伴狭窄或神经损伤；平时 ED 无外伤史、症状渐进。"},{"name":"性腺功能减退","point":"晨间睾酮两次低于参考值（<8–9.2 nmol/L）伴性欲下降、肌肉减少与骨质疏松；需补充睾酮与监测 PSA 及红细胞压积。"},{"name":"Peyronie 病（阴茎硬结症）","point":"体检可扪及白膜硬结、勃起时阴茎弯曲与疼痛；需先处理畸形再考虑 PDE5 抑制剂或手术。"},{"name":"甲状腺功能异常与高泌乳素血症","point":"甲减或甲亢、泌乳素升高均可致性欲与勃起下降；查 T3/T4/TSH 与泌乳素可明确。"},{"name":"药物性 ED","point":"抗抑郁药（SSRI）、β 受体阻滞剂、α 受体阻滞剂、5α 还原酶抑制剂与阿片类可致 ED；调整方案前需评估权衡。"}],"tx":{"drug":[{"name":"西地那非","dose":"按需 50 mg 性活动前 30–60 min 口服，按疗效与耐受调整至 25–100 mg，每日最多 1 次；遵说明书","note":"PDE5 抑制剂一线；需性刺激才起效，高脂餐降低吸收。","renal":"Ccr <30 ml/min 起始 25 mg","hepatic":"重度肝功能不全起始 25 mg","interact":"禁与硝酸酯类、利奥西呱合用；与 α 受体阻滞剂合用须间隔 4 h 以上并警惕低血压；CYP3A4 强抑制剂（酮康唑、克拉霉素）减量"},{"name":"他达拉非","dose":"按需 10 mg 或 20 mg，或每日 2.5–5 mg 规律服用；遵说明书","note":"半衰期约 17.5 h，每日小剂量适用于 ED 合并下尿路症状或性生活频率高者。","renal":"Ccr <30 ml/min 按需最大 10 mg、隔日服用","hepatic":"重度肝功能不全按需最大 10 mg","interact":"禁与硝酸酯类合用；与 α 受体阻滞剂合用须先评估血压"},{"name":"伐地那非","dose":"按需 10 mg，性活动前 25–60 min，可按需要调整至 5–20 mg；遵说明书","note":"起效较快，选择性对 PDE5 较高，对视觉影响少见。","renal":"严重肾功能不全起始 5 mg","hepatic":"中度肝功能不全起始 5 mg，重度慎用","interact":"禁与硝酸酯类；避免与 CYP3A4 强抑制剂合用"},{"name":"十一酸睾酮（确诊性腺功能减退时）","dose":"按制剂与说明书，口服或肌注，需监测睾酮水平；遵说明书","note":"仅用于明确睾酮低下者，且勃起障碍需配合 PDE5 抑制剂；前列腺癌、未评估的 PSA 升高者禁用。","renal":"遵说明书","hepatic":"肝功能异常慎用，监测肝酶","interact":"与华法林合用增强抗凝"},{"name":"盐酸达泊西汀（合并早泄）","dose":"性活动前 1–3 h 30 mg 口服，按需可增至 60 mg，每日 1 次；遵说明书","note":"用于 IELT 短、射精控制差并伴困扰者；按需服，24 h 内不超过 1 次。","renal":"轻度肾功能不全慎用，中度以上不推荐","hepatic":"肝功能不全禁用","interact":"禁与 MAO 抑制剂、硫利达嗪、其他 5-羟色胺能药物合用，警惕血清素综合征"}],"nonDrug":["生活方式干预为所有患者的基石：戒烟、减重、运动 150 min/周、控制血糖血压血脂","真空负压勃起装置：药物无效或禁忌（硝酸酯类使用者）时的非侵入选择","低强度体外冲击波治疗：血管性 ED 可选，证据中等","阴茎海绵体注射（前列地尔）或尿道内给药：口服药物无效者，注意异常勃起","阴茎假体植入：重度器质性 ED 药物无效者，满意度高","心理治疗与夫妻性治疗：心理性 ED 或合并焦虑抑郁者需联合","前列腺癌根治术后 ED 可早期行康复治疗"],"life":["心血管风险筛查与随访：ED 患者每年评估血压、血糖、血脂与体重","避免自行服用含西地那非类成分的保健品，已在服用硝酸酯类者务必停用后再用 PDE5 抑制剂","随访 IIEF-5 与用药效果，无效应评估是否剂量不足、服药时机或性刺激不足，再考虑升级"]},"prog":"PDE5 抑制剂按需治疗后约 60%–70% 患者可恢复满意勃起；规律小剂量他达拉非可能改善内皮功能。血管性器质性 ED 多需长期治疗，糖尿病与盆腔术后 ED 疗效较差，需多模式联合。ED 本身可提示心血管疾病，是心血管风险筛查的窗口。","refs":["《中国勃起功能障碍诊治指南（2022 版）》","《中国男科疾病诊断治疗指南》勃起功能障碍与早泄部分","EAU Guidelines on Sexual and Reproductive Health 2024","中华医学会男科学分会《早泄诊断与治疗指南（2022）》"]}]},{"id":"uro_congenital_more","name":"泌尿系畸形（补充）","rank":41,"summary":"包茎的处理核心是区分生理性与病理性：生理性以观察、清洗与局部糖皮质激素为主，病理性、反复龟头包皮炎或排尿困难者行包皮环切；嵌顿包茎属急症，须在 6 h 内手法复位，失败或已缺血者立即背侧切开。","compare":[],"diseases":[{"id":"ur_phimosis","name":"包茎","aka":["Phimosis","包皮过长","嵌顿包茎","Paraphimosis","干燥性闭塞性龟头炎","BXO"],"rank":1,"basic":{"define":"包茎指包皮口狭小、不能上翻显露阴茎头；出生后绝大多数为生理性（包皮内板与阴茎头粘连、包皮口弹性差），随发育可自行缓解。病理性包茎指包皮口瘢痕性狭窄（多见于硬化性苔藓/BXO 或反复感染），不能自愈。包皮过长指包皮覆盖阴茎头但可上翻。","risk":["婴幼儿生理性包皮粘连（出生时几乎全部存在）","卫生不良、包皮垢积聚与反复龟头包皮炎","干燥性闭塞性龟头炎（BXO/硬化性苔藓），为成人病理性包茎主因","糖尿病血糖控制不佳，龟头炎与 BXO 风险升高","肥胖、隐匿阴茎、蹼状阴茎致包皮口相对狭窄","长期留置导尿管、器械操作或外伤后瘢痕挛缩"],"epi":"新生儿包皮不能上翻者约 96%，6–7 岁降至约 8%，14 岁后不足 1%。病理性包茎随年龄增长占比上升，成人新发包茎须警惕 BXO 与阴茎癌；嵌顿包茎多见于 5–12 岁及性活跃期男性。"},"patho":"生理性包茎源于胚胎期包皮内板与阴茎头上皮未分离，加之类固醇激素水平低使包皮口弹性纤维发育不足；随阴茎生长、间断勃起与上皮角化脱落，粘连逐渐分离。病理性包茎为慢性炎症（BXO 特征为淋巴细胞与浆细胞浸润、基底细胞液化、胶原硬化）导致包皮口瘢痕性狭窄、失去弹性，不能自行缓解。嵌顿包茎为狭窄环卡在冠状沟，远端静脉与淋巴回流受阻而动脉灌注继续，形成水肿—狭窄加重—缺血坏死的恶性循环，6–12 h 内不解除可致阴茎头坏死。","dx":{"criteria":["包皮口不能上翻显露阴茎头为完全性包茎；可部分上翻但显露不全为不完全性包茎；包皮可上翻但自然状态下覆盖阴茎头为包皮过长","生理性包茎：多见于 ≤3–5 岁，包皮口柔软、无瘢痕、无反复感染，可随年龄缓解","病理性包茎：包皮口增厚、发白、失去弹性，可见瓷白色硬化环与皲裂（提示 BXO），任何年龄均不能自行缓解；成人新发包茎须活检排除恶变","嵌顿包茎：包皮上翻后未复位，冠状沟处触及紧缩环，远端包皮与阴茎头水肿、发绀、疼痛，重者溃疡、感觉减退；属急症，需 6 h 内复位","反复龟头包皮炎：每年 ≥2–3 次，包皮红肿、脓性分泌物、异味，可伴发热","排尿困难：包皮口呈针孔样，排尿时包皮先鼓成球状（ballooning）、尿线细、排尿时间延长；长期梗阻可致残余尿、膀胱小梁与上尿路扩张","合并症：包皮结石、尿潴留、性交痛、BXO 相关尿道口狭窄；儿童需评估是否合并隐匿阴茎（按压耻骨上脂肪后阴茎体可显露）"],"workup":["体格检查：记录包皮口直径、能否上翻、有无瘢痕或硬化环、阴茎头与尿道口情况；肥胖儿童按压耻骨前脂肪判断隐匿阴茎","尿常规与尿培养：反复感染者；伴发热者按尿路感染处理","尿流率与残余尿超声：排尿困难或排尿时包皮鼓泡者","血糖与 HbA1c：成人病理性包茎或反复龟头炎者筛查糖尿病","包皮或阴茎头活检：疑 BXO 或局部硬结、溃疡、菜花样病变者，排除鳞状细胞癌","必要时性病筛查（分泌物涂片/核酸扩增）"],"grading":"按病因分生理性（先天性）与病理性（瘢痕性，含 BXO）；按程度分不完全性包茎（可部分上翻）与完全性包茎（完全不能上翻）；嵌顿包茎按缺血程度分三度——轻度：水肿但阴茎头色泽与感觉正常；中度：发绀、感觉减退、无溃疡；重度：溃疡、坏死或不能排尿，需急诊手术。"},"ddx":[{"name":"尿道下裂与隐匿性阴茎（ur_hypospadias）","point":"与本类（泌尿系畸形）邻类疾病 ur_hypospadias 的鉴别点：尿道下裂有尿道口位置异常与阴茎下弯、包皮呈头巾状背侧堆积；隐匿阴茎的阴茎体埋于耻骨前脂肪内、按压后可显露，包皮口本身无狭窄。二者均不宜按包茎单纯行环切。"},{"name":"生理性包皮粘连","point":"包皮口宽、仅包皮内板与阴茎头粘连，可钝性分离；包茎为包皮口本身狭窄，需区别处理。"},{"name":"包皮龟头炎（感染性）","point":"急性红肿、脓性分泌物与疼痛，抗感染后包皮可上翻；仅反复发作致瘢痕时才转为病理性包茎。"},{"name":"干燥性闭塞性龟头炎（BXO/硬化性苔藓）","point":"瓷白色硬化环、皲裂、尿道口狭窄，需活检；环切须切除全部病变，否则复发与恶变风险持续。"},{"name":"阴茎癌","point":"中老年、长期包茎史，硬结或溃疡、菜花样肿物，活检确诊；包茎掩盖病变易漏诊，成人新发包茎必须排除。"},{"name":"嵌顿包茎与过敏性/虫咬性包皮水肿","point":"后者无紧缩环、无包皮上翻史，抗过敏消肿后恢复；嵌顿包茎可触及冠状沟处狭窄环并有明确上翻未复位史。"},{"name":"蹼状阴茎","point":"阴囊皮肤向阴茎腹侧延伸至阴茎体，包皮口正常；单纯环切会加重畸形。"}],"tx":{"drug":[{"name":"丙酸氯倍他索软膏 0.05%","dose":"薄涂包皮口狭窄环，每日 2 次，涂药后轻柔牵拉 1–2 min，连用 4–8 周；无效停药","note":"生理性包茎一线，儿童成功率约 80%–90%；出现皮肤萎缩、红斑或灼痛即停。","renal":"局部用药全身吸收少，遵说明书","hepatic":"遵说明书","interact":"与其他外用糖皮质激素叠加可增加皮肤萎缩与肾上腺抑制风险"},{"name":"糠酸莫米松乳膏 0.1%","dose":"每日 1 次涂包皮口，连用 4–8 周","note":"中效激素，适用于婴幼儿及不能耐受强效激素者。","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他外用激素叠加可致局部皮肤萎缩"},{"name":"莫匹罗星软膏 2%","dose":"每日 3 次涂患处，连用 5–7 天","note":"用于细菌性龟头包皮炎；用药前清洗并保持干燥。","renal":"遵说明书","hepatic":"遵说明书","interact":"长期使用可致耐药，不与同类外用抗菌药叠加"},{"name":"克霉唑乳膏 1%","dose":"每日 2 次涂患处及包皮内板，连用 7–14 天","note":"用于念珠菌性龟头炎；伴侣有症状者同时治疗。","renal":"遵说明书","hepatic":"遵说明书","interact":"无需与其他外用唑类联用"},{"name":"氟康唑","dose":"成人念珠菌性龟头炎 150 mg 单次口服；反复发作者 150 mg 每周 1 次，连用 4–6 周（遵说明书）","note":"局部治疗无效或反复发作时使用；用药前查肝功能。","renal":"单次给药无需调整；反复给药 CrCl<50 时延长间隔至 48–72 h，透析后给药","hepatic":"肝损者慎用并监测肝酶","interact":"升高华法林、磺脲类、他汀与 CYP3A4 底物浓度；禁与特非那定、西沙必利合用"},{"name":"利多卡因（2% 凝胶或 1% 注射液）","dose":"2% 凝胶 5–10 mL 涂阴茎头与狭窄环，5–10 min 后行手法复位；或 1% 利多卡因 5–10 mL 阴茎背神经阻滞（不加肾上腺素）","note":"用于嵌顿包茎复位镇痛；阻滞后观察 15 min 再操作。","renal":"遵说明书","hepatic":"重度肝损减量","interact":"与其他酰胺类局麻药叠加可致全身毒性"},{"name":"头孢呋辛酯","dose":"250–500 mg 口服 bid，连用 7 天（成人）；儿童按体重 10–15 mg/(kg·d) 分 2 次","note":"用于包皮蜂窝织炎、伴发热或糖尿病患者的中重度感染。","renal":"CrCl 10–30 减量或延长间隔","hepatic":"遵说明书","interact":"与丙磺舒合用升高血药浓度；与抗酸剂间隔 2 h"}],"nonDrug":["生理性包茎：观察随访至 5–10 岁，每日温水清洗，避免强行回翻；局部激素 4–8 周无效再评估","包皮口手法扩张/粘连分离：婴幼儿包皮粘连，表面麻醉下钝性分离，之后每日清洗防再粘连","包皮环切指征：病理性包茎或 BXO、反复龟头包皮炎（≥2–3 次/年）、反复尿路感染（尤其合并膀胱输尿管反流）、排尿困难或包皮鼓泡、发生过嵌顿包茎、包皮结石、需长期清洁导尿或留置导尿管","嵌顿包茎手法复位：4–6 h 内首选；纱布包裹持续挤压水肿 5–10 min，或于水肿处多点针刺挤出液体后，双手拇指推阴茎头、食中指拉包皮复位；失败或已坏死行背侧切开（12 点纵切狭窄环后横缝），水肿消退 4–6 周后环切","合并 BXO：环切须切除全部病变并送病理，术后随访尿道口狭窄与复发","隐匿阴茎禁忌单纯环切，需阴茎体固定/整形；新生儿常规环切在我国不作推荐"],"life":["每日温水清洗外阴，不用刺激性皂液或消毒剂；包皮可上翻者清洗后务必复位","糖尿病者控制血糖（HbA1c <7%），减少龟头炎与 BXO 复发","环切术后 2–3 天换药、1 周内避免剧烈运动、4–6 周避免性活动，观察出血、感染与狭窄","儿童每 6–12 个月随访至青春期，评估包皮可复性与排尿","BXO 者每年随访，警惕尿道口狭窄与阴茎癌"]},"prog":"生理性包茎 90% 以上随发育或局部激素治疗缓解；环切术并发症约 1%–5%（出血、感染、切除过多或过少、尿道口狭窄），规范操作可降低。嵌顿包茎及时复位预后良好，超过 12 h 未解除可致阴茎头坏死；BXO 相关病理性包茎术后仍可复发，需长期随访。","refs":["黄健主编《中国泌尿外科和男科疾病诊断治疗指南（2022 版）》包茎与包皮过长章节","《吴阶平泌尿外科学》（第 3 版）包皮疾病章节","EAU Guidelines on Paediatric Urology 2024","American Academy of Pediatrics Task Force on Circumcision: Circumcision Policy Statement. Pediatrics 2012"]}]},{"id":"uro_func","name":"排尿功能障碍","rank":42,"summary":"排尿功能障碍的核心是明确储尿期与排尿期的压力-容量关系：神经源性膀胱以尿动力学分型，排空障碍首选清洁间歇导尿，逼尿肌过度活动用抗胆碱能药或 β3 激动剂，并以影像与肾功能终身监测保护上尿路。","compare":[],"diseases":[{"id":"ur_neurogenic_bladder","name":"神经源性膀胱","aka":["Neurogenic bladder","NB","神经源性下尿路功能障碍","逼尿肌括约肌协同失调","DSD"],"rank":1,"basic":{"define":"神经源性膀胱指中枢或周围神经病变导致膀胱储尿和/或排尿功能障碍的综合征，表现为尿潴留、充溢性尿失禁、尿频尿急与反复尿路感染，严重者因高压膀胱致膀胱输尿管反流、肾积水与肾功能衰竭。","risk":["脊髓损伤（年发病率约 23–60/100 万），伤后 80% 以上出现膀胱功能障碍","多发性硬化、视神经脊髓炎、脑血管病、帕金森病与痴呆","糖尿病周围神经病变（病程 >10 年者约半数有下尿路症状）","脊柱裂、脊髓栓系、脊髓空洞与脊髓肿瘤","盆腔根治性手术（直肠癌、宫颈癌）致盆神经损伤","腰椎间盘突出或椎管狭窄致马尾综合征、带状疱疹、HIV 相关神经病变"],"epi":"脊髓损伤患者 80% 以上存在神经源性膀胱，其中约 1/3 为逼尿肌括约肌协同失调；多发性硬化患者 75%–80% 出现下尿路症状；糖尿病病程超过 10 年者约 50% 有膀胱功能障碍。"},"patho":"骶髓（S2–4）以上的上运动神经元病变，急性期脊髓休克致逼尿肌无反射与尿潴留，休克期后（数周至数月）出现逼尿肌过度活动；若与尿道外括约肌收缩不协调即为逼尿肌括约肌协同失调（DSD），储尿期逼尿肌压升高（>40 cmH₂O）导致输尿管口梗阻、反流与肾积水。骶髓及以下的下运动神经元病变使逼尿肌无收缩、括约肌弛缓，膀胱容量增大、残余尿多，呈充溢性尿失禁。感觉支受损使膀胱充盈感缺失，进一步加重过度充盈与感染。","dx":{"criteria":["有明确神经系统疾病或损伤，出现排尿困难、尿潴留、尿失禁、尿频尿急或反复尿路感染","排尿日记（连续 3 天）记录排尿次数、单次尿量、尿失禁次数与饮水量；单次尿量 >500 mL 或 <100 mL 均提示异常","残余尿（PVR）超声 >100 mL 为排空不全，>200 mL 需干预；PVR >300 mL 常伴充溢性尿失禁","尿动力学为确诊与分型金标准：储尿期逼尿肌压 >40 cmH₂O 或漏尿点压（DLPP）>40 cmH₂O 提示上尿路损害高风险；膀胱顺应性 <20 mL/cmH₂O 为低顺应性","逼尿肌过度活动（DO）伴或不伴 DSD 提示上运动神经元病变；逼尿肌无反射、最大膀胱容量 >500 mL 提示下运动神经元病变","上尿路评估：超声见肾积水或输尿管扩张、膀胱壁增厚 >5 mm、小梁小房形成或膀胱输尿管反流，提示高压膀胱","排除梗阻性因素：男性前列腺体积与尿流率、尿道狭窄（尿流率+尿道超声/造影）、抗胆碱能药与阿片类用药史","脊髓损伤 T6 以上者突发高血压、剧烈头痛、出汗与心动过缓，为自主神经反射异常，需立即排空膀胱并排查诱因"],"workup":["尿动力学检查（充盈期膀胱测压+压力-流率+括约肌肌电图）：记录初尿意容量、最大膀胱容量、顺应性、DLPP 与排尿期逼尿肌压","泌尿系超声（肾、输尿管、膀胱、残余尿）与血肌酐/eGFR：每年至少 1 次，高压膀胱者每 6 个月","排尿期膀胱尿道造影或 DMSA/肾图：怀疑膀胱输尿管反流或需评估分肾功能时","尿常规+尿培养、血糖与 HbA1c；脊髓 MRI 明确病因及是否需减压","膀胱镜：除外结石、肿瘤与尿道狭窄；长期留置导尿管者定期筛查鳞状细胞癌","神经电生理：球海绵体反射、括约肌肌电图，判断下运动神经元损伤程度"],"grading":"Madersbacher 四型：①逼尿肌过度活动+括约肌协同失调（上运动神经元完全性病变）；②逼尿肌过度活动+括约肌弛缓（上运动神经元不完全性病变）；③逼尿肌无反射+括约肌痉挛（下运动神经元不完全性病变）；④逼尿肌无反射+括约肌弛缓（下运动神经元完全性病变）。尿动力学功能分类另列逼尿肌过度活动（DO）、逼尿肌无收缩（DA）、逼尿肌括约肌协同失调（DSD）、低顺应性膀胱与膀胱感觉减退。"},"ddx":[{"name":"良性前列腺增生（ur_bph）","point":"与本类（排尿功能障碍）邻类疾病 ur_bph 的鉴别点：BPH 见于中老年男性，前列腺增大、尿流率下降与 PVR 增加，但无神经系统病变，尿动力学无 DO/DSD；神经源性膀胱需神经病史与尿动力学证据，二者可并存。"},{"name":"女性压力性尿失禁（ur_sui）","point":"腹压增加（咳嗽、喷嚏、活动）时漏尿，尿动力学无 DO、残余尿少；神经源性者多有神经病史与 DO/DSD。"},{"name":"膀胱过度活动症（非神经源性 OAB）","point":"尿急、尿频伴急迫性尿失禁但无明确神经病变；诊断神经源性膀胱必须有神经系统疾病证据，不能仅凭 DO。"},{"name":"尿道狭窄或膀胱颈梗阻","point":"尿流率低平、尿道造影见狭窄段，尿动力学示排尿期高压低流而非逼尿肌无反射；留置导尿管史与外伤史支持。"},{"name":"药物性尿潴留","point":"抗胆碱能药、阿片类、α 受体激动剂与钙通道阻滞剂可致排尿困难，停药后恢复，无神经体征与上尿路改变。"},{"name":"急性尿潴留（结石、血块、术后）","point":"突发不能排尿、膀胱充盈胀痛，导尿后缓解；无慢性神经病变与尿动力学异常。"},{"name":"马尾综合征","point":"双下肢无力、鞍区麻木与大小便失禁，MRI 见椎间盘突出或血肿压迫马尾，需 24–48 h 内急诊减压；延误可致永久性功能障碍。"}],"tx":{"drug":[{"name":"索利那新","dose":"5 mg qd 口服，4 周后疗效不足可增至 10 mg qd","note":"一线抗胆碱能药，用于逼尿肌过度活动；起效 2–4 周，注意口干、便秘、视物模糊，认知障碍与闭角型青光眼者慎用。","renal":"CrCl<30 mL/min 最大 5 mg qd","hepatic":"中度肝损最大 5 mg qd，重度禁用","interact":"CYP3A4 强抑制剂（酮康唑、伊曲康唑、克拉霉素）增加暴露，禁与 >5 mg 剂量合用；与其他抗胆碱能药叠加"},{"name":"米拉贝隆","dose":"25 mg qd 起始，4–8 周后疗效不足增至 50 mg qd","note":"β3 受体激动剂，不增加口干与认知风险，适用于老年或抗胆碱能不耐受者；可轻度升高血压，需监测。","renal":"CrCl 30–89 无需调整；CrCl 15–29 最大 25 mg qd；ESRD 或透析不推荐","hepatic":"中度肝损最大 25 mg qd，重度不推荐","interact":"CYP2D6 抑制剂（帕罗西汀、氟西汀）升高血药浓度；与地高辛合用升高地高辛浓度，需监测"},{"name":"托特罗定","dose":"即释片 2 mg bid，可增至 4 mg bid；缓释片 4 mg qd","note":"抗胆碱能药；即释片餐前服，肝功能不全者优选缓释剂型。","renal":"重度肾功能不全减量，最大 1 mg bid（遵说明书）","hepatic":"轻中度肝损或合用 CYP3A4 强抑制剂时不超过 1 mg bid","interact":"CYP3A4 抑制剂升高血药浓度；与华法林合用可延长 INR"},{"name":"坦索罗辛","dose":"0.2 mg qd 晚餐后服，可增至 0.4 mg qd","note":"α1A 受体阻滞剂，降低尿道阻力，用于 DSD 辅助排空及合并 BPH 者；注意首剂体位性低血压。","renal":"重度肾功能不全慎用","hepatic":"重度肝损慎用","interact":"与 PDE5 抑制剂、降压药合用加重低血压；CYP3A4 强抑制剂升高血药浓度"},{"name":"巴氯芬","dose":"10 mg tid 起始，每 3–7 天加 5–10 mg，最大 80 mg/日；严重痉挛可鞘内泵入","note":"用于 DSD 相关括约肌痉挛与下肢痉挛；突然停药可致反跳、幻觉与癫痫。","renal":"主要经肾排泄，CrCl<30 减量并延长间隔","hepatic":"肝损者慎用，监测肝酶","interact":"与阿片类、苯二氮䓬类、加巴喷丁合用加重中枢抑制"},{"name":"A 型肉毒毒素（onabotulinumtoxinA）","dose":"逼尿肌内注射 200 U（神经源性逼尿肌过度活动），分 20–30 点注射，必要时 6 个月后重复；特发性 OAB 100 U","note":"用于抗胆碱能药无效的难治性 DO；术后尿潴留率 10%–40%（神经源性更高），需具备清洁间歇导尿能力。","renal":"遵说明书","hepatic":"遵说明书","interact":"氨基糖苷类与肌松药增强神经肌肉阻滞；避免与其他肉毒毒素制剂同期使用"},{"name":"呋喃妥因","dose":"50 mg qn 口服，疗程 3–6 个月（复发性尿路感染预防）","note":"仅用于无梗阻、CrCl 尚可者；长期使用监测肺与肝毒性，不推荐用于急性肾盂肾炎。","renal":"CrCl<30 禁用；30–60 慎用（疗效下降、毒性增加）","hepatic":"肝损者禁用","interact":"丙磺舒减少肾排泄；抗酸剂减少吸收"}],"nonDrug":["清洁间歇导尿（CIC）为排空障碍一线：每 4–6 h 一次，单次导尿量控制在 400–500 mL 以内，饮水 1.5–2 L/日；使用 12–14 Fr 亲水涂层导尿管，严格手卫生","留置导尿管或耻骨上膀胱造瘘仅用于不能 CIC、手功能受限或需持续引流者；长期留置增加结石、反复感染与鳞癌风险","骶神经调控（SNM）：难治性非梗阻性尿潴留与 OAB，先测试 1–2 周（排尿量改善 >50% 为有效）；完全性脊髓损伤无效","膀胱扩大术（肠管/胃）用于低顺应性高压膀胱且上尿路受损、药物与 CIC 失败者，术后需终身 CIC","男性 DSD 伴高压膀胱可行经尿道外括约肌切开或尿道支架，术后改用集尿器；终末期可行尿流改道","胫神经刺激（PTNS）用于不完全性神经病变的 OAB；高压膀胱者每 6 个月超声+肾功能，必要时早期膀胱扩大"],"life":["制定个体化饮水与排尿/导尿计划，避免一次大量饮水与憋尿，夜间适量限水","记录排尿日记与导尿量，每 3–6 个月复查超声、残余尿与肾功能","脊髓损伤 T6 以上者及家属培训自主神经反射异常的识别：立即坐起、排空膀胱、解除便秘与压疮等诱因，血压持续 >150/90 mmHg 需急诊处理","长期留置导管者保持引流密闭、每 4 周更换，不常规膀胱冲洗；出现发热、尿液浑浊及时就诊","每年评估尿动力学（上尿路损害者每 6 个月）；育龄女性计划妊娠前评估肾功能与用药"]},"prog":"神经源性膀胱本身不直接缩短寿命，主要死亡风险来自上尿路损害与尿脓毒症。规范 CIC 联合抗胆碱能药或 β3 激动剂可使肾积水与肾功能恶化风险显著下降；脊髓损伤患者约 10%–20% 最终出现上尿路并发症，高位损伤与 DSD 者风险最高，终身随访是防止肾衰竭的关键。","refs":["中华医学会泌尿外科学分会尿控学组《神经源性膀胱诊断治疗指南》（2011）","黄健主编《中国泌尿外科和男科疾病诊断治疗指南（2022 版）》神经源性膀胱章节","EAU Guidelines on Neuro-urology 2024","AUA/SUFU Guideline on Adult Neurogenic Lower Urinary Tract Dysfunction: Diagnosis and Evaluation (2021)"]}]}]},"vascular":{"categories":[{"id":"aortic","name":"主动脉疾病","rank":1,"summary":"主动脉疾病以影像学定型（部位、直径、累及范围）为第一决策点：瘤样病变按直径/增长率决定监测或修复，夹层按 Stanford 分型决定手术时机，贯穿始终的是控制主动脉壁应力（心率+血压）。","compare":[{"diseaseId":"vs_aaa","dx":"无症状多见或腹部搏动性包块；超声/CTA 示肾下腹主动脉最大径 ≥30 mm，>50 mm 为手术阈值","key":"管壁全层瘤样扩张、无假腔；非以突发撕裂痛为主要表现"},{"diseaseId":"vs_dissection","dx":"突发撕裂样胸/背/腹痛 + 血压不对称 >20 mmHg；CTA 见内膜片与真假双腔，按是否累及升主动脉分 Stanford A/B","key":"存在内膜撕裂口与假腔；A 型急诊手术，B 型以药物/腔内为主"}],"diseases":[{"id":"vs_aaa","name":"腹主动脉瘤（AAA）","aka":["Abdominal Aortic Aneurysm","AAA","腹主动脉瘤"],"rank":1,"basic":{"define":"腹主动脉局限性永久性扩张，肾下段最大外径 ≥30 mm（或较正常段增大 >50%）；多数无症状，破裂后死亡率极高。","risk":["男性 ≥65 岁、吸烟（最强可干预因素）","高血压","动脉粥样硬化、冠心病、外周动脉疾病","慢性阻塞性肺疾病","腹主动脉瘤家族史","慢性肾脏病、高同型半胱氨酸血症"],"epi":"我国 65 岁以上男性超声筛查检出率约 3%–6%，女性约为男性 1/3–1/4；无症状瘤破裂后院外死亡率 >50%。"},"patho":"中膜弹力纤维与平滑肌进行性退变，MMP-2/9 活性升高降解细胞外基质，伴慢性炎症，管壁在血流压力下扩张；按 Laplace 定律（T = P×r）张力争平方级升高，形成「越大长得越快」的正反馈。侧后壁薄弱处最先破裂，常破入腹膜后腔或腹腔。","dx":{"criteria":["影像学：肾下腹主动脉最大外径 ≥30 mm 即诊断（部分共识女性 27 mm 为界）","直径分级：30–39 mm 小瘤、40–49 mm 中瘤、50–54 mm 大瘤、≥55 mm 为手术绝对阈值的常用界值","破裂前预警：新发或持续性腹/腰背痛、搏动性包块伴压痛、不明原因血压下降或贫血","破裂三征：突发腹背痛、低血压、腹部搏动性包块（约 1/3 患者三征齐全）","监测频次：30–39 mm 每 3 年 1 次；40–49 mm 每 12 个月 1 次；≥50 mm 或年增长 >5 mm 每 3–6 个月 1 次","12 个月增长 ≥10 mm 或 6 个月 ≥5 mm 为快速增长，不论直径均需重新评估修复"],"workup":["腹部超声：初筛与随访首选，肥胖或肠气干扰改 CTA","CTA（增强）：术前金标准，测瘤颈长度/角度、附壁血栓、髂动脉瘤、钙化与侧支","血常规、肾功能、电解质、凝血；MRSA 筛查（开放手术前）","心电图、胸片、超声心动图与肺功能评估开放手术耐受性","ESR、CRP、血培养、PET-CT 用于疑诊感染性/炎症性动脉瘤"],"grading":"按直径分层：<30 mm 正常；30–54 mm 规律监测；≥55 mm（女性 ≥50 mm 可个体化）或快速增长/症状性 → 修复指征。按解剖分肾下型、近肾型、肾旁型、肾上型，决定 EVAR 或开放修复。"},"ddx":[{"name":"主动脉夹层（vs_dissection）","point":"与本类 vs_dissection 的鉴别点：AAA 为管壁全层扩张、无假腔与内膜片，多为缓慢增长的搏动性包块；夹层突发撕裂样痛、血压不对称，CTA 见内膜片及真假腔。"},{"name":"假性动脉瘤","point":"有穿刺、外伤或感染史，瘤壁为周围组织包裹，超声见 to-and-fro「阴阳」血流征。"},{"name":"肾绞痛/输尿管结石","point":"绞痛向腹股沟放射、血尿、超声见肾积水，无搏动性包块；老年突发腰腹痛先 CTA 排除破裂。"},{"name":"腹膜后肿瘤或淋巴结肿大","point":"不与主动脉腔相通、无搏动性血流信号，增强 CT/MRI 可明确与管腔关系。"},{"name":"腰椎间盘突出/腰肌劳损","point":"疼痛与体位相关、血压稳定；老年反复腰背痛需常规触诊并做腹部超声。"}],"tx":{"drug":[{"name":"美托洛尔（或比索洛尔）","dose":"美托洛尔缓释片 23.75–47.5 mg qd 起始，按心率滴定；目标静息心率 60–70 次/min","note":"降低 dp/dt 与壁应力，延缓瘤体扩张，为一线用药","renal":"一般无需调整，eGFR <30 起始减量","hepatic":"重度肝功能不全减量","interact":"与维拉帕米/地尔硫䓬合用增加心动过缓与传导阻滞风险"},{"name":"氨氯地平（血压未达标时联合）","dose":"5 mg qd 起始，可增至 10 mg qd；目标血压 <130/80 mmHg","note":"以 β 阻滞剂为骨架，联合 CCB 或 ACEI/ARB 降压","renal":"开始或加量后 1–2 周复查血肌酐与血钾","hepatic":"重度肝功能不全起始 2.5 mg","interact":"辛伐他汀联用时限 ≤20 mg；西柚汁升高血药浓度"},{"name":"阿托伐他汀","dose":"20–40 mg qn；目标 LDL-C <1.8 mmol/L","note":"按动脉粥样硬化二级预防，围手术期不中断","renal":"无需调整","hepatic":"活动性肝病禁用；转氨酶 >3 倍正常上限停药","interact":"强 CYP3A4 抑制剂增加肌病风险"},{"name":"阿司匹林","dose":"100 mg qd","note":"合并冠心病、脑血管病或外周动脉疾病者使用","renal":"无需调整","hepatic":"活动性消化道出血、严重肝病禁用","interact":"与 NSAIDs、抗凝药、糖皮质激素合用增加消化道出血风险"}],"nonDrug":["修复指征：最大径 ≥55 mm（女性 ≥50 mm 可个体化）；12 个月增长 ≥10 mm 或 6 个月 ≥5 mm；症状性/濒临破裂；囊状或感染性动脉瘤","濒临破裂/破裂：急诊血管外科，容量复苏（收缩压约 80–100 mmHg）+输血+即刻开放或腔内修复","EVAR：解剖适合（瘤颈 ≥10–15 mm、角度 <60°）者首选，围手术期死亡率更低但需终身随访","开放修复：解剖不适合 EVAR 或年轻低危患者，人工血管置换","择期修复前 30 天戒烟，营养与呼吸功能预康复","EVAR 后 1 个月、12 个月及此后每年 CTA/超声，监测内漏、瘤囊回缩与移植物移位"],"life":["戒烟为最强干预，降低增长与破裂风险","血压 <130/80 mmHg、心率 60–70 次/min，规律用药","他汀与抗血小板按动脉粥样硬化风险管理","避免剧烈憋气用力（举重、便秘）致腹压骤升","60–74 岁吸烟男性建议一次性腹部超声筛查；一级亲属患病者提前筛查","按直径规律随访，新发腹痛立即就诊"]},"prog":"年破裂风险随直径陡升：50–59 mm 约 1%–3%/年，60–69 mm 约 10%/年，≥70 mm 达 20%–30%/年；破裂者即使到达医院手术死亡率仍约 40%–50%。择期 EVAR 围手术期死亡率 1%–2%、开放修复 3%–5%，但 EVAR 再干预率更高（每年约 2%–3%）。","refs":["欧洲血管外科学会（ESVS）腹主动脉瘤管理指南 2024","《中国腹主动脉瘤诊断和治疗指南（2017）》","美国血管外科学会（SVS）腹主动脉瘤诊治实践指南 2018","2017 ESC 外周动脉疾病诊断与治疗指南（主动脉部分）"]},{"id":"vs_dissection","name":"主动脉夹层","aka":["Aortic Dissection","AD"],"rank":2,"basic":{"define":"主动脉内膜撕裂后中膜撕裂扩展，形成由内膜瓣分隔的真腔与假腔；累及升主动脉为 Stanford A 型，仅累及降主动脉及以远为 B 型。","risk":["高血压（最主要，约 70% 患者有）","结缔组织病：Marfan、Loeys-Dietz、Ehlers-Danlos","二叶式主动脉瓣、主动脉缩窄、主动脉炎（大动脉炎、梅毒、白塞病）","主动脉瘤或既往主动脉手术/腔内修复","可卡因、苯丙胺滥用","妊娠与剧烈外伤/减速伤"],"epi":"年发病率约 (3–6)/10 万，男性约为女性 2 倍，发病高峰 50–65 岁。A 型占 2/3，未治疗 48 h 内死亡率约 50%，每过 1 h 增加约 1%–2%。"},"patho":"中膜囊性中层坏死与弹力纤维断裂是结构基础；血压骤升的高 dp/dt 冲击下，内膜破口（多在窦管交界上方或左锁骨下动脉开口远端）使血液进入中膜形成假腔并扩展。假腔压迫真腔致脏器/肢体灌注不良，外膜破裂致心包压塞、胸腔或腹膜后出血，逆行累及冠脉开口可致下壁心肌梗死。","dx":{"criteria":["突发剧烈撕裂样胸/背/腹痛，伴濒死感、晕厥或神经系统症状","血压不对称：双上肢收缩压差 >20 mmHg；约 20% 为假性低血压（心包压塞、假腔破裂）","A 型：CTA 见升主动脉内膜片与真假双腔；B 型：内膜片仅位于左锁骨下动脉以远","扩展危险征象：心包积液、主动脉周围/纵隔血肿、假腔 >22 mm 或假腔优势、入口破口大、疼痛与血压难控","灌注不良证据：肠系膜/肾/下肢缺血（乳酸升高、少尿、无脉）、急性卒中、下壁 MI","DeBakey 分型：Ⅰ型起于升主动脉并延伸；Ⅱ型限于升主动脉；Ⅲ型起于降主动脉"],"workup":["床旁心电图与高敏肌钙蛋白：排除 ACS，A 型可因冠脉开口受累而升高","双上肢血压、四肢脉搏、床旁超声（心包积液、升主动脉、主动脉瓣反流）","全主动脉薄层增强 CTA：首选确诊手段（敏感性/特异性 >95%），同时评估破口、假腔范围与分支","CTA 禁忌时：MRI 或经食管超声（TEE，对升主动脉敏感）","D-二聚体：<500 ng/mL FEU 对低危患者有高阴性预测价值，用于排除而非确诊","血型、凝血、交叉配血、血气、肝肾功能、乳酸；A 型术前评估冠脉与主动脉瓣"],"grading":"Stanford 分型：A 型累及升主动脉（外科急诊）；B 型不累及升主动脉（药物/腔内为主）。B 型按病程分急性 <14 d、亚急性 14–90 d、慢性 >90 d；慢性期假腔 ≥55 mm、年增长 ≥5 mm 或症状复发为干预指征。"},"ddx":[{"name":"腹主动脉瘤（vs_aaa）","point":"与本类 vs_aaa 的鉴别点：夹层以突发撕裂样痛 + 内膜片/真假双腔为核心，可伴灌注不良；AAA 为慢性扩张的搏动性包块，破裂以失血性休克为主、无假腔。需 CTA 全程评价主动脉。"},{"name":"急性冠脉综合征","point":"胸痛相似，但 STEMI 有 ST 抬高与肌钙蛋白升高而无内膜片；关键提示为心包压塞、双上肢血压差。误用抗凝/溶栓可致灾难性出血。"},{"name":"肺栓塞","point":"突发呼吸困难、低氧、右心负荷证据（CTPA 见肺动脉充盈缺损）；夹层以撕裂痛与血压不对称为主。"},{"name":"主动脉壁内血肿/穿透性溃疡（IMH/PAU）","point":"同属急性主动脉综合征；IMH 无内膜破口与血流假腔（CTA 见新月形高密度壁增厚 ≥5 mm），PAU 见局部溃疡样外突。"},{"name":"急性胰腺炎/胆绞痛","point":"上腹痛向背部放射伴淀粉酶/脂肪酶升高、影像示胰腺水肿；夹层背痛为撕裂性且血压多显著升高。"}],"tx":{"drug":[{"name":"艾司洛尔或美托洛尔（首选）","dose":"艾司洛尔负荷 0.5 mg/kg 静推（1 min），维持 50 μg/(kg·min) 起始，可上调至 200 μg/(kg·min)；或美托洛尔 5 mg 静推每 5 min（总量 ≤15 mg）后改口服缓释片","note":"先将心率降至 60 次/min、收缩压 100–120 mmHg；β 阻滞剂须先于或同步于血管扩张剂，防反射性心动过速","renal":"严重肾功能不全时艾司洛尔代谢产物蓄积，需减量","hepatic":"美托洛尔经肝代谢，重度肝病减量","interact":"与维拉帕米/地尔硫䓬合用可致严重心动过缓；β 阻滞剂禁忌时可用非二氢吡啶类 CCB"},{"name":"硝普钠（降压补充）","dose":"起始 0.3–0.5 μg/(kg·min) 静脉泵入，每 5 min 按血压滴定，常用 0.5–10 μg/(kg·min)","note":"仅在心率受控后使用，需有创动脉压；A 型急诊手术前、心包压塞者慎用骤降","renal":"连续使用不宜 >24–72 h，肾功能不全改乌拉地尔或尼卡地平","hepatic":"重度肝功能不全影响代谢，需减量","interact":"与磷酸二酯酶抑制剂合用可致严重低血压；避光输注"},{"name":"乌拉地尔","dose":"12.5–25 mg 缓慢静推，继以 50–100 mg 溶于 100 mL 泵入（约 5–40 mg/h）","note":"α1 拮抗兼中枢降压，不增加心率，适合主动脉夹层","renal":"无需显著调整","hepatic":"重度肝功能不全减量","interact":"与其他降压药合用需谨慎滴定，避免严重低血压"},{"name":"吗啡（镇痛首选）","dose":"2–4 mg 静脉缓慢推注，每 5–10 min 按疼痛评分可重复","note":"疼痛致交感兴奋升高血压，充分镇痛是控制 dp/dt 的关键；监测呼吸","renal":"代谢产物蓄积，减量并延长间隔","hepatic":"重度肝功能不全减量","interact":"与镇静催眠药合用加重呼吸抑制"},{"name":"芬太尼（阿片不耐受时）","dose":"25–50 μg 静脉缓推，按需重复","note":"起效快、循环抑制轻","renal":"无需显著调整","hepatic":"重度肝功能不全减量","interact":"与咪达唑仑等合用致呼吸抑制"},{"name":"美托洛尔缓释片（慢性期维持）","dose":"47.5–95 mg qd，按静息心率 60–70 次/min 滴定；联合 ACEI/ARB 使血压 <130/80 mmHg","note":"B 型慢性期终生药物治疗，降压可促进假腔血栓化","renal":"一般无需调整","hepatic":"重度肝功能不全减量","interact":"与非二氢吡啶类 CCB 合用时注意心动过缓"}],"nonDrug":["Stanford A 型：确诊即急诊外科手术（升主动脉置换，必要时根部/全弓替换），争取 1–2 h 内开始","Stanford B 型无并发症：强化药物治疗；难治性高血压、持续疼痛、快速扩张、灌注不良 → TEVAR","B 型合并灌注不良综合征：优选 TEVAR 恢复真腔血流，必要时分支重建","A 型合并心包压塞：立即手术，术中缓慢打开心包避免血压骤降","Marfan 等结缔组织病：血管脆性大，避免支架，以开放手术为主","慢性 B 型瘤样扩张 ≥55 mm、年增长 ≥5 mm 或出现症状 → TEVAR","绝对禁忌溶栓，诊断明确前不得盲目抗凝/抗血小板"],"life":["终生严格控制血压（<130/80 mmHg，A 型术后部分共识要求收缩压 <120 mmHg）与心率 <70 次/min","避免疼痛、情绪激动、剧烈用力、骤停降压药","术后 1、3、6、12 个月及此后每年 CTA 复查全主动脉","戒烟、控制血脂与体重，β 阻滞剂不随意停用","遗传性主动脉病家系一级亲属影像筛查；妊娠前多学科评估"]},"prog":"未治疗 A 型 48 h 内存活约 50%，手术成功后院内死亡率仍达 10%–25%；急性 B 型院内死亡率约 10%，药物治疗的慢性 B 型 5 年生存率 60%–80%，约 20%–40% 最终需干预。存活者 10 年内晚期再干预率约 20%–30%，灌注不良是围手术期死亡的主要预测因子。","refs":["欧洲心脏病学会（ESC）主动脉疾病诊断与治疗指南 2024","《中国主动脉夹层诊断与治疗规范（2017）》","AHA/ACC 主动脉疾病指南 2022","《Stanford B 型主动脉夹层诊治中国专家共识（2019）》"]}]},{"id":"limb","name":"周围动脉与静脉","rank":2,"summary":"核心是「缺血分级 + 时间窗 + 可挽救组织」：慢性下肢缺血以 Rutherford 分型定严重度，跛行者先运动与药物、CLTI 需血运重建；急性缺血按 Rutherford 急性分级决定保肢紧迫性；血栓后综合征以 Villalta 评分与压力治疗为主线。","compare":[{"diseaseId":"vs_aso","dx":"劳力性间歇性跛行、行走距离固定，ABI ≤0.90 确诊；重度缺血见静息痛、溃疡/坏疽，ABI <0.40 或趾压 <30 mmHg","key":"症状与行走距离相关、ABI 降低，病程数月至数年渐进，双侧多见且有动脉粥样硬化危险因素"},{"diseaseId":"vs_ali","dx":"起病 <14 d 的突发疼痛、苍白、无脉、麻木、运动障碍（6P），多普勒可闻静脉血流而动脉信号消失；常伴房颤或近期血管穿刺","key":"突发进展迅速、无侧支代偿；感觉/运动障碍提示不可逆缺血，需 6 h 内血运重建"},{"diseaseId":"vs_dvt_chronic","dx":"既往 DVT ≥3–6 个月，站立或活动后肢体沉重、肿胀、色素沉着、脂质硬化性皮炎，Villalta 评分 ≥5 分","key":"以静脉高压体征为主（水肿、色素沉着、内踝溃疡），动脉搏动正常、无间歇性跛行"}],"diseases":[{"id":"vs_aso","name":"下肢动脉硬化闭塞症（ASO）","aka":["ASO","Peripheral Arterial Disease","PAD","LEAD","下肢 PAD"],"rank":1,"basic":{"define":"下肢动脉粥样硬化性狭窄或闭塞导致灌注不足，表现为无症状、间歇性跛行、慢性肢体威胁性缺血（CLTI）或急性加重；ABI ≤0.90 为诊断界值。","risk":["吸烟（最重要可干预因素）","糖尿病（病变弥漫、以远端为主）","高血压、血脂异常（LDL-C 升高）","慢性肾脏病/透析","高龄（>65 岁）、肥胖、缺乏运动"],"epi":"我国 45 岁以上人群患病率约 6%–8%，65 岁以上 >10%，确诊者约 10%–20% 为 CLTI；ABI <0.90 者心血管事件风险约增 2 倍。"},"patho":"斑块主要累及股浅动脉收肌管、腘动脉及胫/腓动脉；狭窄达 50%–70% 时运动时远端压力骤降诱发疼痛，休息后缓解。慢性缺血刺激侧支形成，故病程相对缓慢；斑块破裂/血栓形成或栓子脱落可急性加重。终末期出现静息痛与组织坏死。","dx":{"criteria":["间歇性跛行：行走固定距离后小腿/大腿/臀肌酸胀痛，休息 2–5 min 缓解（臀/大腿提示髂动脉，小腿提示股/腘动脉）","体征：足背/胫后动脉搏动减弱、皮温降低、毛发脱落、趾甲增厚","ABI ≤0.90 确诊；0.90–1.00 需运动后 ABI 下降 >20% 或趾肱指数（TBI）<0.70 辅助","ABI >1.40 或动脉不可压缩（糖尿病、CKD 钙化）时以 TBI <0.70 或趾压 <30 mmHg 诊断","CLTI：静息痛 ≥2 周需镇痛，或足部溃疡/坏疽；ABI <0.40、踝压 <50 mmHg 或趾压 <30 mmHg"],"workup":["双下肢血压测量与 ABI/TBI——首选无创初筛","下肢动脉多普勒超声：评估狭窄部位、程度与血流动力学","CTA 或 MRA：血运重建前解剖评估；DSA 作为治疗与最终确认","血脂、空腹血糖/HbA1c、肾功能、同型半胱氨酸、血常规","心电图、超声心动图与颈动脉超声评估合并心脑血管病"],"grading":"Rutherford 分型（慢性）：0 级无症状；1 级轻度跛行（>500 m）；2 级中度跛行（200–500 m）；3 级重度跛行（<200 m）；4 级静息痛；5 级轻度组织缺损；6 级大范围组织缺损/坏疽；4–6 级为 CLTI。Fontaine 分型：Ⅰ 无症状、Ⅱa/Ⅱb 跛行、Ⅲ 静息痛、Ⅳ 溃疡或坏疽。"},"ddx":[{"name":"急性肢体缺血（vs_ali）","point":"与本类 vs_ali 的鉴别点：ASO 病程渐进、有跛行史、侧支代偿好、ABI 低但可测；ALI 起病 <2 周、突发 6P、动脉信号消失。慢性缺血急性加重应按 ALI 处理。"},{"name":"血栓后综合征（vs_dvt_chronic）","point":"与本类 vs_dvt_chronic 的鉴别点：ASO 为动脉缺血（跛行、ABI 降低）；PTS 为静脉高压（肿胀、色素沉着、内踝溃疡、ABI 正常）。"},{"name":"腰椎管狭窄/神经源性跛行","point":"弯腰、坐下或前倾时缓解，症状不随行走距离固定，足背动脉与 ABI 正常，MRI 见椎管狭窄。"},{"name":"腘动脉卡压综合征","point":"年轻无动脉粥样硬化危险因素、运动后小腿疼痛、超声见腘动脉解剖异常。"},{"name":"静脉性溃疡","point":"多位于内踝上方、水肿与色素沉着明显、脉搏可及；动脉性溃疡多在趾端/足跟、边缘整齐、疼痛剧烈，ABI 降低。"}],"tx":{"drug":[{"name":"西洛他唑","dose":"100 mg 口服 bid（餐前 30 min 或餐后 2 h）；不耐受 50 mg bid；连续 3 个月评估疗效","note":"改善跛行距离的核心药物；充血性心力衰竭（任何级别）禁用","renal":"eGFR <30 或透析者经验有限，慎用","hepatic":"中重度肝功能不全慎用","interact":"与 CYP3A4 抑制剂（红霉素、酮康唑）及西柚汁升高浓度；与抗血小板/抗凝药增加出血"},{"name":"盐酸沙格雷酯","dose":"100 mg 口服 tid（餐后），疗程 3 个月并评估","note":"抗血小板/PDE 抑制剂，改善跛行与自觉症状","renal":"严重肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"与抗凝药、抗血小板药合用增加出血风险"},{"name":"贝前列素钠","dose":"20 μg 口服 tid，可增至 40 μg tid","note":"前列环素类似物，国内常用于糖尿病/透析伴肾损害者改善缺血症状","renal":"肾功能不全不需显著调整","hepatic":"肝功能不全慎用","interact":"与抗凝药、抗血小板药合用增加出血风险"},{"name":"前列地尔（PGE1 脂微球）","dose":"10 μg 静脉滴注 qd，10–14 d 一疗程；重症静息痛可 20–40 μg qd","note":"用于 CLTI 或跛行改善，避光、速度 2–3 mL/min，监测低血压与注射痛","renal":"严重肾功能不全慎用","hepatic":"肝功能不全慎用","interact":"与降压药、抗凝药合用增加低血压与出血风险"},{"name":"阿司匹林","dose":"75–100 mg qd 长期口服","note":"按动脉粥样硬化二级预防，有症状者一线抗血小板","renal":"无需调整","hepatic":"活动性肝病、消化道出血禁用","interact":"与 NSAIDs、抗凝药、糖皮质激素合用增加出血风险"},{"name":"阿托伐他汀","dose":"40–80 mg qn（或等效高强度他汀）；目标 LDL-C <1.8 mmol/L，高危者 <1.4 mmol/L 且降幅 ≥50%","note":"改善斑块稳定性与步行距离；4–6 周复查血脂与肝功能","renal":"无需调整","hepatic":"活动性肝病禁用；转氨酶 >3 倍正常上限停药","interact":"强 CYP3A4 抑制剂增加肌病风险"},{"name":"利伐沙班（低剂量抗栓）","dose":"2.5 mg 口服 bid 联合阿司匹林 100 mg qd","note":"用于近期下肢血运重建（尤其膝下）降低大截肢与再狭窄风险","renal":"CrCl 15–50 需评估出血风险；CrCl <15 不推荐","hepatic":"Child-Pugh B/C 不推荐","interact":"与 CYP3A4/P-gp 双重抑制剂合用显著增加出血；避免 NSAIDs"}],"nonDrug":["症状性 PAD 首选监督下运动疗法：每周 3–5 次、每次 30–45 min，跛行至中度疼痛后休息","CLTI 需尽快血运重建（2 周内）：腔内治疗（PTA/DCB/支架/旋切）为多数股腘病变首选；膝下以球囊/DCB 为主","长段股浅动脉闭塞或腔内失败：股-腘/股-胫旁路（自体静脉优于人工血管）","严重坏死/感染无法重建：先控制感染与清创，再行截肢","血运重建后抗血小板（+低剂量利伐沙班）并在 1、3、6、12 个月超声随访"],"life":["戒烟为最重要干预，可显著降低截肢率","运动训练与足部护理（糖尿病者每日检查足部）","血压 <130/80 mmHg、HbA1c 个体化（一般 <8.0%）、LDL-C 达标","避免压疮、冻伤与过紧鞋袜","每年复查 ABI 与足部检查，出现静息痛/溃疡立即就诊"]},"prog":"间歇性跛行者 5 年内约 20% 症状加重，仅 1%–2%/年需截肢；CLTI 未重建者 1 年截肢率 20%–40%、1 年死亡率约 25%。合并糖尿病/ESRD、溃疡深且感染、ABI 极低者预后最差；心血管事件风险约为无 PAD 者 2–3 倍。","refs":["ESC 外周动脉疾病诊断与治疗指南 2017 / 2024","《中国下肢动脉硬化闭塞症诊治指南（2015）》","《下肢动脉硬化闭塞症诊治指南（2022 更新）》","AHA/ACC 下肢外周动脉疾病指南 2024"]},{"id":"vs_ali","name":"急性肢体缺血","aka":["Acute Limb Ischemia","ALI","急性下肢缺血","动脉栓塞/血栓形成"],"rank":2,"basic":{"define":"肢体动脉血流突然中断导致灌注急剧下降，起病 <14 d（多数 <24 h）的急症；多由动脉栓塞或在原有狭窄基础上血栓形成引起，6–12 h 内不恢复血流可致不可逆坏死。","risk":["心房颤动、瓣膜病、人工瓣膜、近期心肌梗死","左心室血栓、扩张型心肌病","动脉粥样硬化（ASO/支架/旁路移植史）","腹主动脉瘤附壁血栓","近期血管穿刺/介入操作或创伤","高凝状态、脱水"],"epi":"年发病率约 1.3–1.7/万，下肢占约 90%。院内 30 天死亡率约 10%–20%，大截肢率约 10%–15%。"},"patho":"栓塞多位于分叉处（股总动脉、腘动脉）且侧支未建立；血栓形成多在原有斑块狭窄处，侧支不足代偿。缺血 4–6 h 后神经与肌肉开始不可逆损伤；恢复血流时再灌注损伤释放氧自由基、钾与肌红蛋白，可致肌红蛋白尿、急性肾损伤与高钾血症。","dx":{"criteria":["6P：疼痛、苍白、无脉、感觉异常、麻痹、皮温降低；感觉/运动障碍提示晚期不可逆缺血","多普勒：可闻及静脉血流而动脉信号消失（与 DVT「动脉可闻、静脉不闻」相反）","ABF 无窄时 EBF <0.30 或无法测及提示临界缺血","起病 <14 d、突发且无侧支；房颤者首先考虑栓塞，跛行/支架史者多考虑血栓形成","血肌酐、血钾、CK、肌红蛋白与乳酸升高提示肌肉坏死与再灌注风险","肢体僵硬、固定性斑驳、无感觉无运动 = 不可逆，需立即截肢"],"workup":["双下肢动脉多普勒超声 + ABI/节段压力（不可测时记录静脉信号）","心电图、超声心动图与心电监护（评估房颤与心源性栓塞）","血常规、凝血、血型与交叉配血、肾功能、血钾、CK、肌红蛋白、血气与乳酸","CTA 或 DSA 明确闭塞位置与长度；病情危重可直接进手术室行 DSA","术后监测肌红蛋白尿与筋膜室压力"],"grading":"Rutherford 急性肢体缺血分级：Ⅰ 级有活力（无感觉/运动障碍）；Ⅱa 级边缘活力（感觉丧失、无运动障碍，及时重建可保肢）；Ⅱb 级即刻危及（感觉丧失 + 运动障碍，需 <6 h 重建）；Ⅲ 级不可逆（肢体僵硬、固定性斑驳、无感觉无运动，需截肢）。"},"ddx":[{"name":"下肢动脉硬化闭塞症（vs_aso）","point":"与本类 vs_aso 的鉴别点：ASO 病程数月至数年、症状与行走距离相关、侧支代偿、ABI 可测；ALI 突发 <2 周、无侧支、动脉信号消失。ASO 基础上突发加重也按 ALI 处理。"},{"name":"血栓后综合征（vs_dvt_chronic）","point":"与本类 vs_dvt_chronic 的鉴别点：PTS 为慢性静脉高压（肿胀、色素沉着、溃疡），动脉搏动正常；ALI 为急性动脉缺血，皮温骤降、苍白、剧痛。"},{"name":"急性深静脉血栓形成（股白肿/股青肿）","point":"肢体肿胀、发热、红紫、条索状压痛，超声见动脉血流正常而静脉不可压缩；ALI 为苍白、皮温低、动脉信号消失。"},{"name":"骨筋膜室综合征","point":"有外伤/骨折史，触痛明显、被动牵拉痛与损伤程度不成比例、筋膜室压升高，动脉血流存在。"},{"name":"急性神经病变/卒中","point":"以运动感觉障碍为主但皮温与肤色正常、脉搏可及；ALI 的麻痹是晚期表现，伴苍白与无脉。"}],"tx":{"drug":[{"name":"普通肝素（即刻抗凝）","dose":"首剂 80 U/kg 静推（或 5000 U），继以 18 U/(kg·h) 泵入，调整 aPTT 至 1.5–2.5 倍正常上限","note":"诊断明确即开始，防止血栓蔓延与侧支血栓化，但不替代血运重建","renal":"无需调整，监测 aPTT 与出血","hepatic":"重度肝病/凝血障碍慎用","interact":"与抗血小板/溶栓药增加出血；HIT 者禁用（改用阿加曲班/比伐卢定）"},{"name":"阿加曲班（HIT 或肝素禁忌时）","dose":"起始 2 μg/(kg·min) 静脉泵入，调整 aPTT 至 1.5–3 倍","note":"直接凝血酶抑制剂，用于 HIT 或既往 HIT 史","renal":"无需调整（肝胆排泄）","hepatic":"Child-Pugh B/C 减至 0.5 μg/(kg·min) 并严密监测","interact":"与华法林重叠期 INR 升高，需谨慎滴定"},{"name":"阿替普酶（导管接触溶栓）","dose":"导管内 0.5–1.0 mg/h 持续灌注（总量约 20–30 mg），配合肝素 250–500 U/h，24–48 h 内评估","note":"适合 Ⅱa 级、旁路移植血栓形成；Ⅱb 级无法耐受长时间溶栓者应直接手术","renal":"无需显著调整","hepatic":"重度肝病增加出血风险","interact":"与治疗剂量抗凝、抗血小板药合用显著增加出血"},{"name":"尿激酶（导管内溶栓替代）","dose":"导管内 20–30 万 U/h 持续灌注或遵说明书；监测纤维蛋白原 >1.5 g/L","note":"国内常用；监测穿刺点出血与血红蛋白下降","renal":"无需显著调整","hepatic":"重度肝病慎用","interact":"与抗凝/抗血小板药增加出血"},{"name":"碳酸氢钠（预防再灌注损伤）","dose":"1.25% 或 5% 溶液静脉输注，按血气与尿量滴定，维持尿量 ≥100 mL/h、尿 pH >6.5","note":"预防肌红蛋白尿所致急性肾损伤，需同时充分补液并监测电解质","renal":"容量管理需谨慎，避免肺水肿","hepatic":"无需调整","interact":"可使儿茶酚胺类失活（同一通路禁用）"}],"nonDrug":["Rutherford Ⅱb/Ⅲ 级：立即血管外科手术或 DSA，目标 6 h 内恢复血流","栓塞（房颤、无侧支）→ 患者稳定时 Fogarty 导管取栓；血栓形成（有 ASO/支架）→ 腔内溶栓/机械吸栓，必要时支架","术后继续抗凝（华法林/DOAC）预防心源性再栓塞，并行超声心动图评估心源","灌注不良伴骨筋膜室综合征：血运重建后行筋膜切开减压","Ⅲ 级或全身情况危重者：计划性截肢以保生命","术后再灌注损伤管理：扩容、碱化尿液、监测血钾与 CK，必要时透析","旁路移植血栓形成：优先溶栓或取栓加修正吻合口"],"life":["房颤者长期抗凝（CHA2DS2-VASc 评估），合并 ASO 者按动脉粥样硬化二级预防","急性期患肢保暖但不可热敷，禁止抬高与按摩","术后每周随访脉搏/ABI 与伤口，1、3、6、12 个月超声复查","戒烟、控制血脂、血压、血糖；心源性栓塞者心内科协同","出现少尿/茶色尿、心悸立即就医（高钾与急性肾损伤）"]},"prog":"Ⅰ–Ⅱa 级及时血运重建保肢率 >90%；Ⅱb 级每延迟 1 h 截肢风险明显上升，6 h 内处理保肢率约 80%；Ⅲ 级一般需截肢。30 天死亡率 10%–20%，主要为心源性并发症与再灌注损伤。房颤栓塞者再栓塞风险高，需终身抗凝。","refs":["欧洲血管外科学会（ESVS）急性肢体缺血管理指南 2020","《下肢动脉硬化闭塞症诊治指南（2022 更新）》急性缺血部分","AHA/ACC 外周动脉疾病指南 2024","2017 ESC 外周动脉疾病诊断与治疗指南（急性肢体缺血部分）"]},{"id":"vs_dvt_chronic","name":"血栓后综合征","aka":["Post-Thrombotic Syndrome","PTS","深静脉血栓后遗症"],"rank":3,"basic":{"define":"深静脉血栓形成（DVT）后 3–6 个月出现或持续存在的慢性静脉高压症状与体征，包括肿胀、沉重、色素沉着、脂质硬化性皮炎与静脉性溃疡；以 Villalta 评分诊断分级。","risk":["既往 DVT（尤其近端/髂股 DVT）","复发性同侧 DVT","急性期抗凝不充分或延迟治疗","肥胖（BMI >30）","高龄、静脉瓣功能不全","腓肠肌泵功能下降"],"epi":"DVT 后 2 年内约 20%–50% 发生 PTS，其中重度（含溃疡）约 5%–10%；髂股静脉血栓者发生率可达 50% 以上。"},"patho":"DVT 后静脉壁炎症、瓣膜纤维化破坏及血栓机化导致的流出道梗阻共同引起静脉高压；毛细血管渗漏、红细胞外渗与含铁血黄素沉积刺激纤维增生与脂质硬化性皮炎，最终形成难愈性溃疡。残余梗阻且无再通（尤其髂股段）者风险最高。","dx":{"criteria":["有已确诊 DVT 病史，症状出现 >3–6 个月或急性期症状持续超过 6 个月","症状：站立或久走后患肢肿胀、沉重、疼痛、痉挛、瘙痒，休息或抬高可缓解","体征：下肢水肿、色素沉着、静脉曲张、脂质硬化性皮炎，溃疡多位于内踝上方","Villalta 评分：5 项症状（疼痛、痉挛、沉重、瘙痒、感觉异常）+ 6 项体征各 0–3 分；≥5 分或存在溃疡 = PTS","分级：5–9 分轻度、10–14 分中度、≥15 分或活动性溃疡为重度","需排除 DVT 复发（症状加重 + D-二聚体/超声）、动脉性疾病与蜂窝织炎"],"workup":["复核既往 DVT 超声/造影，明确血栓部位与再通情况","下肢静脉多普勒：静脉反流时间（股/腘静脉 >0.5 s、胫静脉 >1 s）与残余闭塞段","CT/MRI 静脉成像：计划髂静脉支架（髂静脉受压综合征/May-Thurner）时评估髂股段","溃疡患者必须测 ABI 与趾压，排除合并动脉病变","D-二聚体与超声：与复发 DVT 鉴别","生活质量量表（如 VEINES-QOL/Sym）与溃疡面积/感染评估"],"grading":"Villalta 评分：≥5 分或活动性溃疡诊断 PTS；5–9 分轻度、10–14 分中度、≥15 分或溃疡为重度。CEAP 分级：C0 无、C1 毛细血管扩张、C2 静脉曲张、C3 水肿、C4 皮肤改变（a 色素沉着/湿疹、b 脂质硬化）、C5 愈合溃疡、C6 活动性溃疡。"},"ddx":[{"name":"下肢动脉硬化闭塞症（vs_aso）","point":"与本类 vs_aso 的鉴别点：PTS 为静脉高压（肿胀、色素沉着、内踝溃疡、ABI 正常）；ASO 为动脉缺血（跛行、静息痛、ABI <0.9）。PTS 溃疡合并 ASO 时愈合更差，需同时评估动脉。"},{"name":"急性肢体缺血（vs_ali）","point":"与本类 vs_ali 的鉴别点：PTS 病程慢性、以肿胀与皮肤改变为主、皮温与脉搏正常；ALI 突然起病、苍白、皮温低、伴运动/感觉障碍。"},{"name":"慢性静脉功能不全（非血栓性）","point":"长期久站或家族史，无 DVT 病史，超声见浅静脉反流而无深静脉闭塞。"},{"name":"淋巴水肿","point":"足趾肿胀（Stemmer 征阳性）、皮肤如橘皮样，无色素沉着与溃疡，淋巴显像鉴别。"},{"name":"蜂窝织炎/丹毒","point":"急性红肿热痛、边界清楚、发热与白细胞升高；PTS 皮肤改变为慢性且无全身感染征象。"},{"name":"心衰或肾病性水肿","point":"双侧对称、伴气促/夜尿增多、利尿剂有效；PTS 多为单侧且与既往 DVT 侧一致。"}],"tx":{"drug":[{"name":"医用压力袜（基础治疗）","dose":"踝部压力 30–40 mmHg 渐进式压力袜，白天穿戴、夜间取下；条件允许 40–50 mmHg","note":"PTS 防治核心，DVT 后 2 周内使用可降低发生；溃疡愈合期推荐 40 mmHg 左右","renal":"无特殊调整","hepatic":"无特殊调整","interact":"ABI <0.6 的严重外周动脉疾病慎用，需专业评估"},{"name":"地奥司明","dose":"450 mg 口服 bid，或微粒化 500 mg 口服 bid，疗程 8–12 周并评估","note":"改善肿胀、疼痛与沉重感，辅助压力治疗","renal":"严重肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"遵说明书"},{"name":"舒洛地特","dose":"遵说明书；常用 250 LSU 口服 bid，肌注 600 LSU qd","note":"静脉活性糖胺聚糖，改善皮肤营养障碍；肌注需监测出血","renal":"严重肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"与口服抗凝药合用增加出血风险"},{"name":"羟苯磺酸钙","dose":"0.5 g 口服 tid，连续 3–6 个月","note":"改善毛细血管通透性与沉重感、夜间痉挛","renal":"eGFR <30 慎用/减量","hepatic":"严重肝功能不全慎用","interact":"与抗凝药合用需警惕出血"},{"name":"利伐沙班（延长抗凝，个体化）","dose":"20 mg qd（CrCl 15–50 mL/min 为 15 mg qd）；疗程由 DVT 复发风险决定","note":"PTS 本身非抗凝指征，仅高复发风险（非诱发性、复发、癌症相关）者延长","renal":"CrCl 15–50 减为 15 mg qd；CrCl <15 不推荐","hepatic":"Child-Pugh B/C 不推荐","interact":"与 CYP3A4/P-gp 双重抑制剂合用增加出血；避免 NSAIDs"}],"nonDrug":["压力治疗为基础：中重度 PTS 需 30–40 mmHg 弹力袜，依从性是关键","抬高患肢、踝泵运动与规律行走，避免久站久坐","溃疡：清创 + 压力绷带 + 促愈合敷料；难愈者考虑皮肤移植","髂股静脉残余梗阻（May-Thurner 综合征）可行髂静脉支架改善重度 PTS","深静脉瓣膜严重反流：瓣膜修复术（证据有限，建议在有经验中心）","急性 DVT 早期导管溶栓/机械吸栓可能降低 PTS，需个体化","溃疡合并感染需抗感染与清创；≥5 cm 或 12 周不愈需进一步评估"],"life":["DVT 后 2 周内开始压力袜并持续 2 年以上可降低 PTS 风险","控制体重、规律步行/踝泵运动，避免长期站立或屈膝久坐","每日检查足部皮肤，破损、红肿、发热及时就诊","溃疡患者每周换药并评估，注意压力治疗","继续戒烟与控制血糖，避免下肢外伤","再次急性肿胀、D-二聚体升高时排查复发 DVT"]},"prog":"PTS 多在 DVT 后 2 年内出现并趋于稳定；约 10%–20% 发展为重度，5%–10% 出现静脉溃疡。溃疡 1 年愈合率 60%–70%，1 年复发率可达 15%–30%。依从压力治疗者症状明显改善，髂股静脉支架后 1–2 年症状缓解率约 70%–80%。","refs":["《深静脉血栓形成诊疗指南（2021 版）》","《中国静脉血栓栓塞症防治指南（2023）》","美国血液学会（ASH）静脉血栓栓塞管理指南 2020","欧洲血管外科学会（ESVS）静脉血栓管理指南 2021（血栓后综合征部分）"]}]},{"id":"carotid_venous","name":"颈动脉与静脉疾病","rank":3,"summary":"颈动脉狭窄按症状+狭窄度+斑块稳定性决定干预；静脉疾病按是否血栓/反流+CEAP 决定保守或手术。主线：影像定量→抗栓与干预风险权衡→长期危险因素控制。","compare":[{"diseaseId":"vas_carotid","dx":"TIA、一过性黑矇或轻卒中史，颈动脉超声+CTA/DSA 测 NASCET 狭窄","key":"动脉性缺血事件，狭窄局灶且与症状侧一致"},{"diseaseId":"vas_varicose","dx":"久站后下肢沉重、夜间抽筋，迂曲浅静脉、色素沉着或溃疡；站立位反流 >0.5 s","key":"慢性病程、体位相关、浅静脉反流"},{"diseaseId":"vas_tv","dx":"单侧骤然肿胀疼痛、Homan 征阳性、D-二聚体升高，加压超声静脉不可压陷","key":"急性起病、单侧不对称水肿、深静脉血栓"}],"diseases":[{"id":"vas_carotid","name":"颈动脉狭窄","aka":["Carotid Artery Stenosis","CAS","颈动脉粥样硬化性狭窄"],"rank":1,"basic":{"define":"颈动脉分叉/颈内动脉起始部粥样硬化斑块致管腔狭窄；症状性指近 6 个月内同侧 TIA、一过性黑矇或非致残轻卒中。","risk":["吸烟、高血压","糖尿病、代谢综合征","高 LDL-C、脂蛋白(a) 升高","高龄（男 ≥65、女 ≥70 岁）","冠心病、外周动脉疾病","颈动脉杂音、颈部放疗史、CEA 后再狭窄"],"epi":"≥65 岁人群无症状 ≥50% 狭窄检出率 5%–10%；缺血性卒中约 15%–20% 与颈动脉狭窄相关；未干预的症状性重度狭窄 2 年卒中风险 15%–20%。"},"patho":"分叉后外侧壁低剪切力区脂质沉积→泡沫细胞与坏死核心→纤维帽变薄、新生血管与 MMP 活跃致易损斑块破裂；血栓栓塞远端分支产生 TIA/卒中。重度狭窄同时存在灌注不足与栓子脱落，两者叠加。","dx":{"criteria":["NASCET 分级（分母取狭窄远段正常颈内动脉）：<50% 轻、50%–69% 中、70%–99% 重度、近闭塞呈「线样征」","ECST 法数值通常比 NASCET 高 10%–15%，报告须注明方法，临床决策以 NASCET 为准","症状性定义：同侧黑矇/TIA/轻卒中（mRS ≤3），近 6 个月内发生","症状性 70%–99% 为获益最大核心人群；50%–69% 男性可考虑 CEA，女性获益不确定","无症状 ≥70% 且预期寿命 >5 年、围术期卒中/死亡 <3% 者可考虑 CEA","易损斑块：溃疡型、斑块内出血、薄纤维帽（CTA/黑血 MRI/CEUS）"],"workup":["颈部血管超声（含流速、斑块形态、假性闭塞识别）：初筛与随访首选，须有经验者操作","CTA：术前评估狭窄长度、钙化、颅内段与侧支","DSA：CAS 术中金标准，不作为初筛","脑 MRI（DWI）：确认梗死部位与症状侧一致性","动态心电图/心电监护、超声心动图：排除心源性栓塞","血脂、HbA1c、同型半胱氨酸、肾功能（对比剂）"],"grading":"NASCET 轻/中/重度/近闭塞；按症状性/无症状性；斑块分稳定型（钙化多、表面光整）与易损型（溃疡、内出血、薄纤维帽）。"},"ddx":[{"name":"下肢静脉曲张与慢性静脉功能不全（vas_varicose）","point":"与本类 vas_varicose 的鉴别点：颈动脉狭窄呈局灶神经缺血（黑矇、单瘫、失语），无体位相关性；静脉曲张为站立加重的下肢沉重与皮肤色素沉着。"},{"name":"深静脉血栓（vas_tv）","point":"与本类 vas_tv 的鉴别点：DVT 为单侧下肢肿胀痛、皮温升高，无黑矇与单瘫；偏瘫患者卧床需另行排查 DVT。"},{"name":"心源性栓塞（房颤、机械瓣）","point":"无颈动脉狭窄而突发多血管分布区梗死，心电提示房颤，以抗凝为主，不行血运重建。"},{"name":"颈动脉夹层","point":"<50 岁、颈部外伤/推拿史、颈痛+Horner 征，影像见双腔/内膜片，狭窄呈长段锥形。"},{"name":"大动脉炎","point":"年轻女性、无脉症、ESR/CRP 升高，影像见管壁环形增厚、长段狭窄，活动期忌腔内治疗。"},{"name":"Moyamoya 病/放疗后狭窄","point":"颅内动脉末端狭窄伴血管网，或放疗野内长段狭窄，无典型偏心性斑块。"}],"tx":{"drug":[{"name":"阿司匹林","dose":"75–100 mg qd 长期","note":"有症状及无症状 ≥50% 均建议单抗；消化道出血史加 PPI","renal":"遵说明书，重度肾衰慎用","hepatic":"重度肝病出血风险高，评估后使用","interact":"与 NSAIDs、抗凝药合用时出血风险升高"},{"name":"氯吡格雷","dose":"负荷 300 mg（拟 72 h 内手术者常 600 mg），维持 75 mg qd","note":"阿司匹林不耐受者替代；CEA 围术期单抗即可","renal":"一般无需调整","hepatic":"重度肝功能不全慎用","interact":"奥美拉唑、埃索美拉唑抑制 CYP2C19，宜改用泮托拉唑"},{"name":"阿司匹林+氯吡格雷（CAS 围术期）","dose":"阿司匹林 100 mg qd + 氯吡格雷 75 mg qd，择期术前 5 d 开始，术后至少 4 周（常用 1–3 个月）后转单抗","note":"CEA 不常规双抗；仅 21 d 内症状性轻卒中可短期双抗 21 d","renal":"遵说明书","hepatic":"遵说明书","interact":"避免与抗凝药、NSAIDs 同用"},{"name":"阿托伐他汀（或瑞舒伐他汀）","dose":"阿托伐他汀 40–80 mg qn 或瑞舒伐他汀 20–40 mg qn，LDL-C <1.8 mmol/L 且降幅 ≥50%","note":"强化他汀稳定斑块、降低复发，与基线 LDL 无关","renal":"瑞舒伐他汀严重肾衰减至 10 mg；阿托伐他汀无需调整","hepatic":"活动性肝病或转氨酶 >3×ULN 禁用，4–8 周复查","interact":"克拉霉素、伊曲康唑、胺碘酮升高浓度增加肌病；避免与吉非贝齐合用"},{"name":"依洛尤单抗","dose":"140 mg 皮下 每 2 周 1 次（或 420 mg 每 4 周）","note":"他汀+依折麦布 10 mg 仍未达标时加用","renal":"无需调整","hepatic":"重度肝损数据有限","interact":"遵说明书"},{"name":"乌拉地尔（围术期血压）","dose":"持续泵入 1–2 mg/min 起始滴定，维持 <140/90 mmHg","note":"术后高血压致高灌注综合征与出血，低血压致心肌缺血，均应避免","renal":"遵说明书","hepatic":"遵说明书","interact":"与其他降压药叠加低血压"},{"name":"普通肝素（CAS 术中）","dose":"60–70 IU/kg 静推，按 ACT 补充，术后 4–6 h 评估穿刺点","note":"须在双抗覆盖下使用","renal":"一般无需调整","hepatic":"遵说明书","interact":"与双抗合用出血风险叠加"}],"nonDrug":["CEA：症状性 NASCET 70%–99% 首选，建议症状出现 2 周内手术；50%–69% 男性、无症状 ≥70% 且围术期风险 <3% 可考虑","CAS 适应证：高位分叉、放疗后狭窄、CEA 后再狭窄、不能耐受全麻，或年龄 <70 岁；须用远端栓塞保护装置","无症状狭窄不做预防性手术，除非易损斑块、微栓子监测阳性或进展性狭窄","房颤等心源性栓塞者不行血运重建，按抗凝二级预防","术后监测 NIHSS、血压、颈部血肿与气道；随访术后 1、6 个月及此后每年颈动脉超声看再狭窄与对侧进展"],"life":["严格戒烟，为延缓斑块进展的核心","血压 <140/90 mmHg（糖尿病 <130/80），HbA1c <7.0%","LDL-C <1.8 mmol/L，限制饱和脂肪","识别先兆：黑矇、单侧无力、言语不清立即急诊（4.5 h 溶栓窗）","双抗期间避免自行加用止痛药，黑便或持续出血立即就诊"]},"prog":"未干预的症状性 70%–99% 狭窄 2 年同侧卒中约 15%–26%，CEA 绝对风险下降约 16%；CAS 围术期卒中约 3%–4%（≥70 岁更高）。术后 5 年再狭窄 5%–10%，多为内膜增生，可再次干预。强化内科治疗使无症状重度狭窄卒中风险降至约 1%/年，故须严格筛选干预对象。","refs":["《中国颈动脉狭窄诊治指南（2017）》","中国缺血性卒中和 TIA 二级预防指南 2022","中国颈动脉狭窄诊治专家共识 2021","ESVS 颈动脉疾病管理指南 2023","AHA/ASA 无症状颈动脉狭窄指南 2021"]},{"id":"vas_varicose","name":"下肢静脉曲张与慢性静脉功能不全（CVI）","aka":["Varicose Veins","CVI","静脉曲张"],"rank":2,"basic":{"define":"下肢浅静脉永久性扩张、迂曲与延长，伴或不伴深静脉反流所致静脉高压，以久站沉重、色素沉着进展至静脉性溃疡；按 CEAP 评估临床、病因、解剖与病理生理。","risk":["女性、多次妊娠","长期站立或端坐职业","家族史","肥胖、缺乏运动","高龄","DVT 后遗症"],"epi":"成人患病率 10%–30%，女性约男性 2 倍；C4–C6 期占 5%–10%；静脉性溃疡占腿溃疡 70% 以上，1 年复发 30%–50%。"},"patho":"瓣膜功能不全或静脉壁胶原异常，站立时踝部静脉压可 >90 mmHg→毛细血管静水压升高→血浆外渗与白细胞激活，形成含铁血黄素沉着与脂质硬化；溃疡多在内踝上方「靴形区」。","dx":{"criteria":["CEAP：C0 无体征；C1 毛细血管扩张；C2 曲张（≥3 mm）；C3 水肿；C4a 色素沉着/湿疹、C4b 脂质硬化/白色萎缩；C5 愈合溃疡；C6 活动性溃疡","反流时间（站立位）：股浅/隐静脉 >0.5 s、穿通静脉 >0.35 s 为功能不全","C3–C6 需区分原发性浅静脉、深静脉反流/阻塞与穿通静脉功能不全","C 级后补 E（原发/继发/先天）、A（解剖）、P（反流/阻塞）","溃疡须测 ABI：<0.8 提示动脉因素、>1.3 为假性低压，避免强压致坏死","合并浅静脉血栓需评估近端深静脉延伸"],"workup":["下肢静脉双功超声（站立位）：评估深浅静脉与穿通静脉反流、血栓，术式选择依据","ABI：压力治疗与溃疡患者必备","CTV/MRV：双侧水肿、盆腔痛或单侧色素沉着显著者，排除髂静脉受压","血常规、凝血、D-二聚体（疑血栓）","溃疡取分泌物培养，必要时活检排除恶性肿瘤"],"grading":"CEAP C0–C6（含 C4a/C4b），补症状性 S/无症状 A；用 VCSS 量化严重度；浅静脉反流分大隐、小隐、副大隐与穿通静脉来源。"},"ddx":[{"name":"深静脉血栓（vas_tv）","point":"与本类 vas_tv 的鉴别点：CVI 为慢性、体位相关症状且超声无充盈缺损；DVT 为单侧突发肿胀痛、D-二聚体升高、静脉不可压陷，首选抗凝。"},{"name":"颈动脉狭窄（vas_carotid）","point":"与本类 vas_carotid 的鉴别点：颈动脉狭窄为动脉缺血（黑矇、单瘫），与体位无关；CVI 为静脉高压的沉重感与皮肤营养改变。"},{"name":"下肢动脉硬化闭塞症（ASO）","point":"间歇性跛行、足背动脉搏动减弱、ABI <0.9、皮温低；与 CVI 可共存，故溃疡者必须先测 ABI。"},{"name":"心源性/肾性/肝性水肿","point":"双侧对称，伴 BNP 升高、蛋白尿或腹水，无色素沉着与静脉反流。"},{"name":"丹毒/蜂窝织炎","point":"急性红肿热痛伴发热、边界清楚、白细胞升高。"},{"name":"淋巴水肿","point":"足趾方形、Stemmer 征阳性、非凹陷性；CVI 有体位性减退与靴形色素沉着。"}],"tx":{"drug":[{"name":"地奥司明","dose":"900 mg bid（或 1000 mg qd）餐中服，4–6 周后评估减量","note":"改善 C3–C4 水肿与沉重感，证据中等，不提高溃疡愈合率","renal":"重度肾功能不全慎用","hepatic":"重度肝病慎用","interact":"与抗凝药合用注意出血"},{"name":"七叶皂苷（马栗种子提取物）","dose":"50 mg bid 餐后，疗程 4–8 周","note":"减轻水肿与疼痛，不能替代压力治疗","renal":"遵说明书","hepatic":"遵说明书","interact":"与抗凝药合用注意出血"},{"name":"利伐沙班（合并浅静脉血栓）","dose":"10 mg qd 口服 45 d；或磺达肝癸钠 2.5 mg 皮下 qd 45 d","note":"血栓 ≥5 cm 或距隐股汇合 ≤3 cm 按 DVT 处理，否则止痛+压迫","renal":"CrCl <15 避免，15–50 谨慎减量","hepatic":"Child-Pugh B/C 慎用","interact":"酮康唑、利托那韦增加出血"},{"name":"银离子/碘敷料（溃疡创面）","dose":"按产品说明更换，渗液多者每 2–3 天 1 次","note":"仅在明确感染征象时使用全身抗菌药","renal":"遵说明书","hepatic":"遵说明书","interact":"避免碘敷料与含汞制剂同用"}],"nonDrug":["压力治疗为核心：C1–C2 用 15–20 mmHg，C3–C6 用 20–30 mmHg（溃疡期 30–40 mmHg 或双层），晨起下床前穿戴","禁忌：ABI <0.5 或失代偿心衰（改用短弹性绷带渐进加压）","腔内热消融（激光/射频）±泡沫硬化剂：C2 症状性首选，门诊局麻、恢复快","手术：高位结扎+EVLA/RFA；细小腿曲张用泡沫硬化；反流穿通静脉（≥3.5 mm）可内镜离断或热消融","避免孤立小腿浅静脉单纯高位结扎；不推荐全部大隐抽剥式手术","溃疡：压力治疗+创面床准备（清创、渗液管理），愈合后持续弹力袜防复发，必要时溃疡切除+植皮","髂静脉受压/狭窄行球囊扩张+支架"],"life":["每 1 h 起身活动 5 min，做踝泵与提踵","抬高下肢高于心脏 20–30 min，每日 2–3 次","BMI <25，步行、游泳、骑车，避免久坐与翘腿","皮肤保湿防裂，避免搔抓湿疹区","醒时长期穿弹力袜，6–12 个月更换；定期复查超声与 VCSS"]},"prog":"C2 患者 10–20 年内 30%–50% 进展至更高分期；规范压力治疗 3 个月溃疡愈合率 70%–90%，但 1 年复发 30%–50%。热消融 5 年闭合率 85%–95%，优于抽剥，需超声引导防隐神经损伤。","refs":["《慢性下肢静脉疾病诊断与治疗中国专家共识（2014）》","中国静脉曲张微创治疗共识 2021","ESVS 慢性静脉疾病管理指南 2022","UIP CEAP 分级 2020 修订版"]},{"id":"vas_tv","name":"深静脉血栓（DVT）","aka":["Deep Vein Thrombosis","DVT","下肢深静脉血栓形成"],"rank":3,"basic":{"define":"深静脉内异常凝固形成血栓，腘静脉及以上为近端 DVT、小腿肌间/胫腓静脉为远端；可并发肺栓塞（PE）与血栓后综合征（PTS）。","risk":["近期大手术（髋膝置换、腹盆腔手术）、创伤与制动","恶性肿瘤","妊娠产褥期、口服避孕药/激素","既往 VTE 或易栓症","肥胖、高龄、吸烟、心衰与呼衰","中心静脉导管/起搏导线","抗磷脂综合征、炎症性肠病"],"epi":"全球年发病约 1–2/1000 人年，≥70 岁 5/1000 人年；未治疗的近端 DVT 20%–50% 发生 PE；DVT 后 2 年内 PTS 20%–50%。"},"patho":"Virchow 三要素（淤滞、内皮损伤、高凝）：瓣膜袋内低速血流致局部缺氧，内皮表达组织因子、P-选择素，白细胞-血小板-纤维蛋白成栓。急性期脱落栓塞肺动脉；数周后机化并破坏瓣膜，导致静脉高压、反流与 PTS。","dx":{"criteria":["Wells 评分 ≥2 分为「可能」，≤1 分为「不太可能」，与 D-二聚体按两段法组合","D-二聚体 <500 μg/L FEU 或年龄校正（>50 岁：年龄×10 μg/L）可排除","加压超声静脉不可压陷为金标准；近端敏感度 >95%，小腿静脉需 5–7 d 复查","体征：单侧小腿周径差 ≥3 cm（胫骨粗隆下 10 cm）、沿深静脉走行压痛","疑 PE 首选 CTPA；妊娠/肾衰用 V/Q 显像","诱因分级：一过性、持续（肿瘤、易栓症）、无诱因"],"workup":["双下肢加压超声（股总、股浅、腘、胫后/腓静脉）","D-二聚体定量：低/中度可能用排除，高度可能直接影像","血常规、PT/APTT、纤维蛋白原、肾功能、肝功能","无诱因 >50 岁者按症状行肿瘤筛查（便潜血、胸部 CT、乳腺/妇科）","易栓症筛查限于 <50 岁、反复、家族聚集或非典型部位；急性期蛋白 C/S 与抗凝血酶可假性降低，需延后","髂静脉或下腔静脉血栓行 CTV/MRV"],"grading":"解剖：远端（肌间/胫腓）、近端（腘及以上）、髂-腔静脉型；病程：急性 <14 d、亚急性 15–28 d、慢性 >28 d；诱因：一过性/持续/无诱因。PTS 用 Villalta 评分（≥5 分或溃疡）。"},"ddx":[{"name":"下肢静脉曲张与慢性静脉功能不全（vas_varicose）","point":"与本类 vas_varicose 的鉴别点：DVT 急性单侧肿胀、D-二聚体升高、超声见充盈缺损；CVI 慢性、体位相关、超声示反流而无血栓。"},{"name":"颈动脉狭窄（vas_carotid）","point":"与本类 vas_carotid 的鉴别点：颈动脉狭窄为颈动脉分布区神经缺血，不引起下肢肿胀；卒中卧床者需同时排查两病。"},{"name":"蜂窝织炎/丹毒","point":"边界清楚的红肿热痛伴发热与白细胞升高；超声无静脉充盈缺损，但二者可并存。"},{"name":"贝克囊肿破裂","point":"腘窝囊性肿物突发破裂，小腿后方肿痛伴踝周瘀斑，超声见囊壁破裂。"},{"name":"腓肠肌拉伤/血肿","point":"运动后撕裂感、肌腹局部压痛、瘀斑，D-二聚体正常，超声见肌内血肿。"},{"name":"心/肾性水肿与淋巴水肿","point":"双侧对称伴原发病证据；非凹陷性硬肿与足趾方形提示淋巴水肿。"}],"tx":{"drug":[{"name":"利伐沙班","dose":"15 mg bid 餐中服 21 d，随后 20 mg qd；疗程 3 个月起，肿瘤或反复者延长","note":"一线单药；胃/泌尿道活动性病变慎用","renal":"CrCl 15–50 谨慎减量，15–20 避免；<15 禁用","hepatic":"Child-Pugh B/C 或凝血障碍者避免","interact":"强 CYP3A4/P-gp 抑制剂增出血，利福平等诱导剂降低疗效"},{"name":"阿哌沙班","dose":"10 mg bid 口服 7 d，之后 5 mg bid","note":"大出血风险低于华法林，轻度肾损可用","renal":"CrCl <25 数据有限","hepatic":"重度肝损慎用","interact":"强 CYP3A4/P-gp 抑制剂/诱导剂需评估"},{"name":"依诺肝素","dose":"1 mg/kg 皮下 q12h 或 1.5 mg/kg qd，至少 5 d 并至 INR 达标 2 d","note":"妊娠首选、肾功能不全或肿瘤 VTE 可选","renal":"CrCl <30 改为 1 mg/kg q24h 并监测抗 Xa（0.6–1.0 IU/mL）","hepatic":"重度肝病出血风险高","interact":"与抗血小板药、NSAIDs 合用出血增加"},{"name":"华法林","dose":"2.5–5 mg qd 起始（老年/低体重 2.5 mg），目标 INR 2.0–3.0，每周监测","note":"机械瓣、抗磷脂综合征（三抗体阳性）、严重肾功能不全首选；须与低分子肝素重叠 ≥5 d","renal":"不需调量但出血风险高，监测 INR","hepatic":"肝硬化基线 INR 偏高，慎用","interact":"胺碘酮、甲硝唑、复方新诺明、氟康唑、NSAIDs 及丹参/银杏增强；利福平与维生素 K 食物减弱"},{"name":"尿激酶/阿替普酶（导管接触溶栓）","dose":"尿激酶首剂 4000 U/kg 静推 10 min，维持 4000 U/(kg·h)（常用 2–4 万 U/h）≤72 h；阿替普酶 0.5–1 mg/h 经导管；每 6–12 h 查纤维蛋白原，<1.5 g/L 暂停","note":"适应证：症状 <14 d 的髂股型、股青肿；颅内出血 <1%","renal":"遵说明书，注意出血","hepatic":"严重肝病、凝血障碍禁用","interact":"溶栓期间停用其他抗栓药"},{"name":"抗凝（下腔静脉滤器置入后）","dose":"条件允许尽快恢复治疗量（如利伐沙班 15 mg bid×21 d 后 20 mg qd），可回收滤器 3–6 个月内取出","note":"滤器仅用于抗凝禁忌、足量抗凝下仍复发者","renal":"遵说明书","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["确诊后 24 h 内启动抗凝；高度怀疑时先行经验性抗凝","导管接触溶栓±机械血栓清除：急性髂股型（<14 d）、股青肿/股白肿，由介入科评估出血风险后实施","下腔静脉滤器：抗凝绝对禁忌、足量抗凝下反复 PE、大面积 PE 取栓术前；优先可回收型","外科取栓：仅限肢体濒危且溶栓禁忌者","弹力袜：DVT 后 2 周起穿 20–30 mmHg ≥2 年（若耐受），减轻 PTS 症状","确诊后 24 h 即在抗凝下下床活动，避免严格卧床","高危患者用气动压缩装置联合药物预防","疗程结束时复查 D-二聚体、超声与出血风险"],"life":["急性期避免按摩患肢与热敷，抬高患肢 20–30°","不擅自停药；黑便、血尿、大片瘀斑、持续头痛立即就诊","控制体重、戒烟，减少复发",">4 h 旅行穿压力袜、定时活动踝部、补充水分","女性重新评估避孕药/激素替代风险，妊娠前多学科计划","再次出现腿肿痛、气促胸痛、咯血立即急诊"]},"prog":"疗程结束后近端 DVT 年复发 3%–5%；一过性诱因者 3 个月后停抗凝，无诱因/持续诱因者长期复发 >30%，可延长抗凝（利伐沙班 10 mg qd 或阿哌沙班 2.5 mg bid）。PTS 20%–50%，CDTI 使髂股型 PTS 降约 1/3（CaVenT）。有效抗凝后 PE 3 个月死亡率 <5%。","refs":["《深静脉血栓形成的诊断和治疗指南（第三版，2017）》","中国肺血栓栓塞症诊治与预防指南 2018","中国骨科大手术静脉血栓栓塞症预防指南 2023","CHEST 抗栓治疗指南 2021","ESC 静脉血栓栓塞管理指南 2019"]}]},{"id":"access_rare","name":"通路与罕见血管病","rank":4,"summary":"透析通路按流量-压力-再循环评估并以 ADQI 分级处理；血栓闭塞性脉管炎与雷诺以严格戒烟和痉挛/炎症调控为核心，药物优先于介入。","compare":[{"diseaseId":"vas_avf","dx":"透析血流量不足、静脉压升高或穿刺困难，超声见通路狭窄、流量下降","key":"有造瘘史 + 透析参数异常 + 通路内狭窄"},{"diseaseId":"vas_tao","dx":"年轻男性吸烟者、远端肢体缺血，影像见中小动脉节段闭塞、近端动脉正常、无钙化","key":"吸烟 + 远端小动脉受累 + 无 ASO 背景"},{"diseaseId":"vas_raynaud","dx":"遇冷后手指苍白→紫绀→潮红三相变色，可逆，无指端坏死或仅浅溃疡","key":"可逆性对称血管痉挛，无动脉闭塞"}],"diseases":[{"id":"vas_avf","name":"血液透析通路建立与拥塞","aka":["Arteriovenous Fistula","AVF","动静脉内瘘","透析通路功能障碍"],"rank":1,"basic":{"define":"慢性肾衰血液净化的血管通路，首选自体 AVF，其次移植物 AVG 与中心静脉导管（CVC）。拥塞指流量不足、静脉压升高或再循环，多源于吻合口或流出道狭窄、血栓及中心静脉狭窄。","risk":["糖尿病、动脉硬化、高龄（AVF 成熟失败 20%–40%）","既往中心静脉置管（致狭窄）","低血压、左心功能不全","反复同点穿刺、压迫过久","高凝、抗磷脂抗体","动脉流入不足"],"epi":"我国血透通路中 AVF 占 70%–80%、AVG 10%–15%、CVC 10%–20%；AVF 1 年通畅 60%–75%，AVG 约 50%。通路失功是透析患者住院主因之一。"},"patho":"吻合口高剪切力与湍流损伤内膜，早期内膜增生致限流狭窄；静脉段动脉化重塑过度则形成动脉瘤。穿刺纤维化与中心静脉置管后纤维带促发血栓与中心静脉狭窄，表现为流出道梗阻。","dx":{"criteria":["血泵流量 <250 mL/min 或 −200 mmHg 下难维持；静脉压 >150 mmHg；再循环 >10%–15%","体检：震颤/杂音减弱、狭窄段硬结；抬臂试验静脉塌陷延迟 >3–5 s 提示流出道梗阻","「rule of 6」成熟标准：6 周时流量 >600 mL/min、内径 ≥6 mm、深度 <6 mm、可用穿刺段 >6 cm","ADQI 分级：Ⅰ 血流不足无临床后果；Ⅱ 透析不充分（Kt/V <1.2）；Ⅲ 反复血栓/需干预；Ⅳ 通路废弃","狭窄：管径较正常段减少 ≥50% 且伴流量/压力异常，仅解剖狭窄不干预","中心静脉狭窄：同侧上肢与头面肿胀、胸壁静脉扩张，静脉造影确认"],"workup":["通路超声：流量、内径、狭窄部位、血栓与动脉瘤","透析记录：血泵流量、静脉压、跨膜压、Kt/V 与再循环","DSA：干预前金标准，可同期 PTA/支架","CTV/MRV：有置管史或不明原因失功","术前血管评估：上肢动脉、头/贵要静脉内径 ≥2.5 mm、深静脉通畅","高凝评估与心脏超声（EF <30% 或重度主动脉瓣狭窄避免高流量瘘）"],"grading":"ADQI 通路失功 Ⅰ–Ⅳ 期；解剖分流入道（动脉/吻合口）与流出道（静脉/中心静脉）；形态分狭窄、血栓闭塞、动脉瘤/假性动脉瘤、感染。"},"ddx":[{"name":"血栓闭塞性脉管炎（vas_tao）","point":"与本类 vas_tao 的鉴别点：通路拥塞局限于造瘘肢、以透析参数为线索、超声见局部狭窄；Buerger 病为年轻吸烟者远端小动脉节段闭塞，无内瘘。"},{"name":"雷诺综合征与血管痉挛（vas_raynaud）","point":"与本类 vas_raynaud 的鉴别点：穿刺痉挛为透析中突然流量骤降、局部苍白，热敷后恢复；雷诺为遇冷后手指三相变色，无通路狭窄。"},{"name":"内瘘相关性高输出心衰","point":"流量 >1500–2000 mL/min、气促、心指数升高，方向与狭窄性流量不足相反，需限流。"},{"name":"通路感染/脓肿","point":"局部红肿热痛、脓性分泌、血培养阳性，超声见液性暗区。"},{"name":"中心静脉血栓/上腔静脉综合征","point":"同侧上肢肿胀、颈静脉充盈、面颈水肿，CTV 见上腔静脉狭窄。"}],"tx":{"drug":[{"name":"阿司匹林（术后早期）","dose":"100 mg qd，术前 1–3 d 至术后 4–6 周；可与氯吡格雷 75 mg qd 联合 4 周，出血高危者单用","note":"可减少早期血栓（尤其 AVG），不作长期双抗","renal":"尿毒症血小板功能差","hepatic":"重度肝病慎用","interact":"与 NSAIDs、抗凝药合用增加出血"},{"name":"氯吡格雷","dose":"75 mg qd，反复血栓或 PTA 高危者 3–6 个月","note":"不改变 PTA 后长期通畅率","renal":"一般无需调整","hepatic":"重度肝硬化慎用","interact":"奥美拉唑降低活性代谢物"},{"name":"肝素（透析抗凝）","dose":"首剂 0.3–0.5 mg/kg 静推（约 1000–2000 IU），每小时追加 500–1000 IU","note":"出血风险高者改低分子肝素或无肝素透析","renal":"尿毒症半衰期延长，注意减量","hepatic":"重度肝病出血风险高","interact":"与抗血小板药叠加出血"},{"name":"4% 枸橼酸局部抗凝","dose":"动脉端输入 18–20 mmol/h 起始，按离子钙（0.9–1.2 mmol/L）滴定","note":"适用于活动性出血或术后早期","renal":"枸橼酸蓄积风险，监测总钙/离子钙","hepatic":"肝衰竭时乳酸酸中毒风险增加","interact":"同管路含钙输液可沉淀"},{"name":"华法林（合并系统性抗凝指征）","dose":"目标 INR 2.0–3.0（机械瓣 2.5–3.5），按常规桥接","note":"单纯为通路通畅不建议长期抗凝","renal":"无需调量但出血风险高","hepatic":"肝硬化调量困难","interact":"胺碘酮、甲硝唑、氟康唑、NSAIDs 增强"},{"name":"尿激酶（血栓性闭塞）","dose":"经导管 10–25 万 U 局部灌注或 2–4 万 U/h，单次 ≤75 万 U；优先机械抽吸","note":"用于急性（<2 周）闭塞，需与 PTA 联合","renal":"有残余肾功能者减量","hepatic":"凝血障碍者禁用","interact":"溶栓期间停用其他抗栓药"}],"nonDrug":["造瘘规划优先非优势手前臂 AVF，AVF > AVG > CVC；提前 3–6 个月建立","PTA 为首选干预，狭窄段球囊扩张至内径；弹性回缩或 3 个月内再狭窄置入覆膜支架","急性闭塞：溶栓+机械清除+PTA，同时处理流入/流出道狭窄","反复失败者行贵要静脉转位、上臂肱动脉-贵要静脉瘘或 PTFE 移植物","中心静脉狭窄：球囊扩张+支架，避免再置管","监测：每次透析记录流量与静脉压，每月 Kt/V，每 6 个月通路超声","穿刺采用绳梯或扣眼法，超声引导减少血肿","感染通路切除感染段并重建，脓毒症时拔除"],"life":["透析后压迫 10–15 min，24 h 内不热敷、不浸水","内瘘侧肢体不测血压、不抽血、不输液、不受压","每日触摸震颤、听杂音，消失立即就诊（6 h 内溶栓成功率高）","透析间期增重 <干体重 5%，低盐低钾饮食","戒烟、控糖，长途旅行咨询是否需抗凝","上肢肿胀、发热、穿刺点流脓即刻就诊"]},"prog":"AVF 1 年原生通畅 60%–75%、辅助通畅 >80%；AVG 1 年约 50%，PTA 后 6 个月再狭窄 40%–50%。及时干预可避免废弃；依赖 CVC 者感染与死亡率显著升高（血流感染 1–5 次/1000 导管日）。","refs":["《中国血液透析用血管通路专家共识（第 2 版，2019）》","中国维持性血液透析患者血管通路管理指南 2021","KDOQI 血管通路临床实践指南 2019 更新","国际透析通路协会（ADQI）通路管理共识 2021"]},{"id":"vas_tao","name":"血栓闭塞性脉管炎（Buerger 病）","aka":["Buerger Disease","Thromboangiitis Obliterans","TAO"],"rank":2,"basic":{"define":"以中青年吸烟男性为主、累及四肢中小动静脉的节段性非粥样硬化性炎症闭塞病，表现为指（趾）端缺血、反复溃疡与坏疽，戒烟可显著延缓进展。","risk":["烟草暴露（几乎为必要条件）","男性 20–40 岁起病","寒冷潮湿环境","家族聚集（部分）","牙周疾病"],"epi":"我国北方多见，男女约 20:1；在亚洲与东欧占外周动脉疾病 5%–16%；持续吸烟者截肢率 40%–50%。"},"patho":"烟草代谢物损伤内皮并触发免疫反应，致中小动脉与浅静脉节段性全层炎症、腔内纤维化血栓闭塞，病变呈跳跃式，血管壁结构完好、罕见钙化；后期远端缺血出现溃疡坏疽，常伴游走性静脉炎与雷诺现象。","dx":{"criteria":["<45 岁、男性为主、当前或既往吸烟","远端缺血：足底/小腿跛行、静息痛、指（趾）溃疡或坏疽","游走性浅静脉炎（30%–40%）、雷诺现象（20%–30%）","桡/尺/胫后/足背动脉搏动减弱，Allen 试验阳性，近端大动脉搏动正常","影像：中小动脉节段闭塞、「螺旋状」侧支，近端正常、无钙化","排除 ASO、动脉栓塞、血管炎（ANA/ANCA/抗磷脂抗体阴性）、红白蛋白增多症（Shionoya 标准）"],"workup":["四肢动脉超声：闭塞节段与侧支，排除近端病变","CTA/MRA：跳跃性闭塞、近端通畅、无钙化","DSA：术前评估远端流出道与侧支","激光多普勒与趾端 tcPO2；趾端 PPPG <30 mmHg 提示重度缺血","血常规、ESR/CRP、ANA、ANCA、抗磷脂抗体、冷球蛋白","血糖、HbA1c、血脂以排除 ASO"],"grading":"临床分期：Ⅰ 局部缺血期（跛行、发凉）；Ⅱ 营养障碍期（静息痛、皮色苍白、甲厚）；Ⅲ 组织坏死期（溃疡/坏疽）。亦可按 Rutherford 0–6 级描述缺血程度。"},"ddx":[{"name":"雷诺综合征与血管痉挛（vas_raynaud）","point":"与本类 vas_raynaud 的鉴别点：Buerger 为器质性闭塞，持续缺血、搏动消失、进行性溃疡；雷诺可逆、发作间期完全正常、无闭塞。"},{"name":"血液透析通路建立与拥塞（vas_avf）","point":"与本类 vas_avf 的鉴别点：Buerger 不依赖透析通路，影像为多发中小动脉节段闭塞；通路拥塞限于造瘘肢与透析参数异常。"},{"name":"下肢动脉硬化闭塞症（ASO）","point":">50 岁伴糖尿病/高血脂，病变在股浅、腘或胫动脉近段，影像见钙化，无游走性静脉炎。"},{"name":"动脉栓塞","point":"突发「6P」、无侧支代偿，房颤/瓣膜病史，超声见动脉内栓子。"},{"name":"系统性血管炎","point":"发热、ESR/CRP 明显升高、肾炎或肺受累、自身抗体阳性，血管影像呈弥漫炎症。"},{"name":"胸廓出口综合征","point":"随抬臂/肩内旋诱发，影像见锁骨下动脉受压，无吸烟关联与远趾缺血。"}],"tx":{"drug":[{"name":"完全戒烟（含药物替代）","dose":"尼古丁贴片 21 mg/24h（>20 支/d）阶梯减至 7 mg，8–12 周；伐尼克兰 0.5 mg qd×3 d→0.5 mg bid×4 d→1 mg bid 至 12 周；安非他酮 150 mg qd×3 d 后 150 mg bid","note":"继续吸烟则任何治疗（含手术）均无效，戒烟应与药物同等处方化","renal":"伐尼克兰 CrCl <30 减至 0.5 mg qd","hepatic":"重度肝损慎用安非他酮","interact":"伐尼克兰与华法林合用监测 INR；安非他酮降低癫痫阈"},{"name":"前列地尔（脂微球 PGE1）","dose":"10 μg 静滴 qd，疗程 2–4 周；或 20 μg 加入 100 mL 生理盐水静滴 qd","note":"改善微循环与静息痛，促溃疡愈合；单用对重度坏疽有限","renal":"严重肾功能不全慎用","hepatic":"遵说明书","interact":"与降压药叠加降压；与抗凝药合用出血增加"},{"name":"伊洛前列素/贝前列素钠","dose":"伊洛前列素静脉 0.5–2 ng/(kg·min)×6 h/d，2–4 周（需监护）；贝前列素钠 40 μg tid","note":"用于重症缺血与难治性静息痛，可致低血压、头痛、下颌痛","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"伊洛前列素与肝素同管路可能沉淀，需分开输注"},{"name":"西洛他唑","dose":"100 mg bid（50 mg bid 起始 2 周后加量）","note":"改善跛行，本病为经验性使用；心衰禁用","renal":"CrCl <25 慎用或减量","hepatic":"重度肝损禁用","interact":"酮康唑、红霉素升高浓度；与抗血小板药叠加出血"},{"name":"依诺肝素/利伐沙班（浅静脉炎急性期）","dose":"依诺肝素 40 mg qd 或 1 mg/kg q12h 皮下 2–4 周；或利伐沙班 10 mg qd 4–6 周","note":"证据有限；长期抗凝无证据","renal":"CrCl <30 依诺肝素减量","hepatic":"重度肝病慎用","interact":"与抗血小板药叠加出血"},{"name":"镇痛","dose":"对乙酰氨基酚 0.5–1 g q6h（日 ≤3 g）；曲马多 50–100 mg q6h 必要时；加巴喷丁 100–300 mg qn 渐增","note":"避免长期 NSAIDs；难治性静息痛可加用加巴喷丁","renal":"曲马多与加巴喷丁肾功能不全减量","hepatic":"重度肝病对乙酰氨基酚 ≤2 g/d","interact":"曲马多+SSRI 有 5-HT 综合征风险；加巴喷丁+阿片类呼吸抑制"},{"name":"抗生素（并发感染）","dose":"按药敏，如阿莫西林/克拉维酸 625 mg tid 或头孢呋辛 0.5 g bid；骨髓炎 4–6 周序贯","note":"单纯缺血性溃疡不必常规使用","renal":"按 CrCl 调整","hepatic":"遵说明书","interact":"遵说明书"}],"nonDrug":["戒烟是唯一被证实改变自然史的措施，须反复强化并纳入随访","血管重建仅用于可靶血管者，优先自体大隐静脉旁路；PTA 再狭窄率高、慎用","脊髓电刺激：不可重建且有静息痛/局限溃疡者，改善微循环与镇痛","交感神经阻滞或腰交感神经切除：短期缓解痉挛与疼痛","清创与截肢：局限坏疽清创，深部感染或进展性坏疽需截趾/截肢，术前须确认戒烟","高压氧：难愈溃疡辅助（证据有限）","随访：1–3 个月评估戒烟、ABI/tcPO2 与溃疡愈合"],"life":["绝对戒烟（含二手烟与电子烟），家庭与工作环境无烟","保暖防潮，禁热水袋直接接触缺血肢体（易烫伤）","每日检查足趾皮肤，穿宽头软底鞋，剪甲由专人处理","Buerger 运动：抬高 2 min→下垂 3 min→平卧 5 min，每日数次","避免长时间屈膝或交叉腿","新发溃疡、脓性渗出或坏疽扩大立即就诊"]},"prog":"预后几乎完全取决于戒烟：戒烟者截肢率 5%–10%，持续吸烟者 40%–50%，5 年内约 40% 需截肢。旁路 1 年通畅 70%–80%，低于 ASO，介入更差。","refs":["《血栓闭塞性脉管炎诊断和治疗中国专家共识（2021）》","中国血栓闭塞性脉管炎诊治指南 2019","《下肢动脉硬化闭塞症诊治指南（2015）》","ESVS 外周动脉疾病指南 2023","日本 Buerger 病临床指南（Shionoya 标准）2017"]},{"id":"vas_raynaud","name":"雷诺综合征与血管痉挛","aka":["Raynaud's Phenomenon","Raynaud 现象","雷诺病"],"rank":3,"basic":{"define":"遇冷或情绪诱发指（趾）端阵发性缺血，典型三相（苍白→紫绀→潮红）或二相变色；原发性（Raynaud 病）无基础疾病，继发性合并结缔组织病、用药或振动暴露。","risk":["女性、15–40 岁","寒冷气候、振动工具作业","结缔组织病（系统硬化、狼疮、MCTD）","β 阻滞剂、麦角胺、博来霉素/顺铂、干扰素","吸烟、咖啡因过量、精神压力","冷球蛋白血症、红白蛋白增多症"],"epi":"人群患病率 3%–5%，女性为男性约 3 倍，多为原发性；系统性硬化 90% 以上合并，10%–15% 发展为指端溃疡。"},"patho":"外周 α2 受体反应性增强致指动脉、毛细血管前小动脉与动静脉吻合支痉挛；血小板活性与血液黏滞度升高加重缺血。反复发作致慢性低灌注；继发性者伴内膜增生与微血管结构破坏，出现溃疡与坏疽。","dx":{"criteria":["发作性三相变色（苍白→紫绀→潮红），双手对称，多不累及拇指（累及更提示继发）","诱因为寒冷、情绪、振动，数分钟至数十分钟自行恢复","原发性（LeRoy）：无溃疡、无指端硬化/凹陷、ANA 阴性、甲襞毛细血管正常","继发性：存在结缔组织病、抗体阳性、甲襞毛细血管异常（扩张、出血、稀疏）或指端溃疡","排除胸廓出口综合征、腕管综合征、栓塞、冻伤","用 RCS 评分与发作频率记录严重度"],"workup":["病史：发作频率、持续时间、对称性、诱因、溃疡/坏疽、用药与振动暴露","甲襞毛细血管镜：区分原发/继发","自身抗体：ANA、抗 Scl-70、抗着丝点、抗 U1RNP，必要时冷球蛋白与抗磷脂抗体","血常规、ESR/CRP、甲功、血糖、免疫球蛋白","指端多普勒超声，必要时手部 DSA","继发人群评估肺功能、胸部 CT、心超与食管功能"],"grading":"轻度：偶发变色无组织损伤；中度：频繁发作伴疼痛影响生活；重度：指端溃疡、凹陷瘢痕或坏疽。LeRoy 1992 区分原发/继发；系统性硬化可用 EUSTAR 指端溃疡评分。"},"ddx":[{"name":"血栓闭塞性脉管炎（vas_tao）","point":"与本类 vas_tao 的鉴别点：雷诺发作间期正常、脉搏正常、无闭塞；Buerger 持续缺血疼痛、搏动消失、节段闭塞、进行性溃疡。"},{"name":"血液透析通路建立与拥塞（vas_avf）","point":"与本类 vas_avf 的鉴别点：雷诺无造瘘史与透析参数异常、变色可逆对称；通路窃血综合征仅累及造瘘侧。"},{"name":"指端动脉栓塞","point":"单侧突发剧痛、无三相演变，血压不对称，超声见栓子。"},{"name":"冻伤/冻疮","point":"长时间寒冷暴露史，皮损为红斑、水疱、坏死；雷诺为短时冷刺激的可逆变色。"},{"name":"胸廓出口综合征","point":"抬臂诱发、上肢麻木，Adson 试验阳性，影像见肌/骨性压迫。"},{"name":"腕管综合征","point":"夜间正中神经分布麻木而无颜色改变，肌电图异常。"}],"tx":{"drug":[{"name":"硝苯地平","dose":"缓释片 30 mg qd 起始，滴定至 30 mg bid（最大 60 mg bid）","note":"一线，发作频率降约 50%、严重度降约 40%；头痛、潮红、踝部水肿常见","renal":"一般无需调整","hepatic":"肝硬化减量并监测","interact":"克拉霉素、伊曲康唑增加浓度；葡萄柚汁提高生物利用度"},{"name":"氨氯地平","dose":"5 mg qd 起始，可至 10 mg qd","note":"长效、依从性好，适合合并高血压者","renal":"无需调整","hepatic":"中度肝损 2.5 mg qd 起始","interact":"与辛伐他汀合用增加肌病风险（辛伐他汀 ≤20 mg）"},{"name":"地尔硫䓬","dose":"缓释 90–180 mg qd，必要时 180 mg bid","note":"不耐受二氢吡啶或合并房颤/心绞痛时替代；左室功能不全者避免","renal":"无需调整","hepatic":"重度肝损减量","interact":"与 β 阻滞剂合用致心动过缓；升高地高辛浓度"},{"name":"伊洛前列素（伴溃疡）","dose":"静脉 0.5–2 ng/(kg·min)×6 h/d×5 d，每 6–8 周可重复；吸入 5 μg/次，每日 6–9 次（自 2.5 μg 起）","note":"系统性硬化相关溃疡愈合与预防，监测低血压与下颌痛","renal":"遵说明书","hepatic":"遵说明书","interact":"与肝素同管路可沉淀，须分开输注"},{"name":"西地那非/他达拉非","dose":"西地那非 20 mg bid 或 50 mg 按需；他达拉非 2.5–5 mg qd 或 20 mg 按需","note":"改善微循环与溃疡愈合，证据中低；禁与硝酸酯类合用","renal":"CrCl <30 西地那非 25 mg 起","hepatic":"重度肝损禁用","interact":"与硝酸酯类致严重低血压"},{"name":"氟西汀","dose":"20 mg qd，3–6 周起效","note":"原发性发作频繁者可选，合并抑郁焦虑优先","renal":"严重肾功能不全减量","hepatic":"肝硬化减量","interact":"与曲马多、SSRI 有 5-HT 综合征风险；可升高 INR"},{"name":"外用硝酸甘油软膏（溃疡期）","dose":"0.2%–0.4% 薄涂 qd–bid，避免大面积","note":"改善局部血流，证据有限；头痛、潮红常见","renal":"遵说明书","hepatic":"遵说明书","interact":"与 PDE5 抑制剂系统合用可致严重低血压"},{"name":"波生坦/马西替坦（难治溃疡，专科）","dose":"波生坦 62.5 mg bid×4 周后 125 mg bid；马西替坦 10 mg qd","note":"系统性硬化反复指端溃疡，每月查转氨酶","renal":"慎用","hepatic":"转氨酶 >3×ULN 停药；Child-Pugh B/C 禁用","interact":"波生坦为 CYP3A4 诱导剂，降低激素避孕与华法林疗效"}],"nonDrug":["保暖为首要措施：手套、暖手袋，避免冷水与冷空气","戒烟、限咖啡因，生物反馈与压力管理","指端溃疡清洁换药防感染，避免过度清创","难治性继发溃疡：星状神经节阻滞或局部肉毒毒素注射（短期有效）","停用/替换诱发药物（β 阻滞剂、麦角胺等），由原医生评估","坏死边界清晰后行指端清创或截指，尽量保留指长","风湿免疫科随访原发病（硬皮病肺间质病变筛查）"],"life":["手部保暖，用温水洗手，避免握冰冷物品","戒烟、避免二手烟，适度运动","均衡饮食、限咖啡因，管理压力","每日观察指端颜色与皮肤完整性，持续发紫/发黑立即就诊","医疗操作前告知病史，避免动脉穿刺与冷敷","记录发作频率与诱因，随访评估溃疡与肺间质病变"]},"prog":"原发性约 1/3 数年内自行缓解，极少坏疽；钙拮抗剂治疗使发作减少约 50%。继发性（尤其系统性硬化）10%–15% 出现指端溃疡，部分需截指；早期识别继发特征影响长期预后。","refs":["《雷诺综合征诊断与治疗中国专家共识（2022）》","中国系统性硬化病诊疗指南 2021","EULAR 系统性硬化指端溃疡管理推荐 2017","美国血管医学学会雷诺现象实践建议 2019"]}]},{"id":"vas_upper_mesenteric","name":"上肢、肠系膜与血管畸形","rank":5,"summary":"上肢缺血看「锁骨下-腋-肱」段狭窄与胸廓出口压迫；肠系膜血管病的关键是**疼痛与体征分离**（剧烈腹痛而腹软），CTA 是首选；血管畸形按 ISSVA 分类区分血管瘤与血管畸形，治疗路径完全不同。","compare":[{"diseaseId":"vas_subclavian","dx":"上肢乏力、发凉、活动后酸胀，双侧血压差 >15 mmHg，CTA 见锁骨下动脉或腋动脉狭窄/闭塞","key":"双侧血压差 + 上肢运动诱发症状；大动脉炎与动脉粥样硬化是最常见病因"},{"diseaseId":"vas_tos","dx":"上肢外展或过头运动时诱发麻木、疼痛与乏力（Adson 试验、Roos 试验阳性），影像见锁骨下血管或臂丛受压","key":"姿势性诱发是特征；需与颈椎病、腕管综合征鉴别"},{"diseaseId":"vas_ami","dx":"剧烈腹痛与腹部体征不成比例（「疼痛与体征分离」）， lactate 升高，CTA 见肠系膜上动脉闭塞或狭窄","key":"房颤患者突发剧烈腹痛 + 乳酸升高 + 腹软，必须想到 SMA 栓塞"},{"diseaseId":"vas_malformation","dx":"出生即存在的血管性包块（血管畸形）或生后出现的增殖性红斑（婴幼儿血管瘤），按 ISSVA 分类","key":"血管瘤会自行消退（多用普萘洛尔），血管畸形不会消退且需介入/硬化治疗"}],"diseases":[{"id":"vas_subclavian","name":"锁骨下动脉狭窄与上肢动脉闭塞","aka":["Subclavian Artery Stenosis","Upper Limb Ischemia","锁骨下动脉盗血综合征"],"rank":1,"basic":{"define":"锁骨下动脉或腋动脉、肱动脉的狭窄或闭塞导致上肢缺血，可伴「锁骨下动脉盗血」（椎动脉血流逆流至患侧上肢，引起椎基底动脉供血不足）。","risk":["动脉粥样硬化（吸烟、糖尿病、高血压、高脂血症）","大动脉炎（年轻女性，我国多见）","胸廓出口压迫（见 TOS）","放射治疗后","外伤与医源性（导管、放疗）"],"epi":"锁骨下动脉狭窄在无症状人群中检出率约 2%–4%，在脑血管病患者中可达 15%–20%。左侧较右侧多见（约 3:1）。大动脉炎在我国年轻女性中相对高发。"},"patho":"动脉粥样硬化斑块或大动脉炎的慢性炎症致管腔狭窄，远端灌注压下降。当狭窄 >70% 或闭塞时，椎动脉因压力差出现**逆向血流**（锁骨下动脉盗血），导致椎基底动脉供血不足（眩晕、复视、晕厥）。上肢的侧支循环（甲状颈干、肋间动脉）可在慢性期代偿，故部分患者可无症状；急性血栓栓塞则无代偿，症状重。","dx":{"criteria":["症状：患肢乏力、发凉、麻木、活动后酸胀（间歇性跛行）、指端苍白；伴盗血者出现眩晕、复视、晕厥、共济失调","**体征：双侧上肢血压差 >15–20 mmHg（收缩压），患侧脉搏减弱或消失，锁骨上窝可闻及收缩期杂音**","**CTA 或 MRA**：见锁骨下动脉、腋动脉狭窄或闭塞，可评估侧支与盗血","彩色多普勒超声：见狭窄处流速增快、狭窄后湍流，椎动脉反向血流（盗血）","DSA（数字减影血管造影）：金标准，可同时行介入治疗","病因鉴别：年轻女性 + ESR/CRP 升高 + 多支病变 → 大动脉炎；老年 + 危险因素 + 钙化斑块 → 动脉粥样硬化"],"workup":["双侧上肢与双下肢血压测量（对比）、脉搏触诊与血管杂音","上肢动脉彩色多普勒超声（含椎动脉血流方向）","CTA 或 MRA（首选无创影像，评估解剖与侧支）","DSA（拟介入或手术时）","ESR、CRP、自身抗体（疑大动脉炎）","血脂、血糖、肾功能（动脉粥样硬化危险因素）","经颅多普勒（评估颅内血流与盗血）"],"grading":"按狭窄程度分 <50%（轻度）、50%–69%（中度）、70%–99%（重度）与闭塞；按症状分无症状、慢性缺血（间歇性跛行）与急性缺血（Rutherford 分级用于下肢，上肢可参照）；按病因分动脉粥样硬化性与炎性（大动脉炎）。"},"ddx":[{"name":"胸廓出口综合征（vas_tos）","point":"与 TOS 的鉴别：TOS 症状由姿势（外展、过头）诱发，影像见锁骨下血管或臂丛在胸廓出口受压；锁骨下动脉狭窄为固定的解剖狭窄，血压差持续存在。"},{"name":"急性肠系膜缺血（vas_ami）","point":"与肠系膜缺血的鉴别：后者以腹痛为主、无上肢症状与血压差；两者均可由动脉粥样硬化或栓塞引起（房颤患者需同时评估）。"},{"name":"血管畸形（vas_malformation）","point":"与血管畸形的鉴别：血管畸形为先天性包块（搏动性、皮温高、可闻杂音），无血压差与脉搏改变。"},{"name":"颈椎病（神经根型）","point":"以上肢放射痛、麻木为主，颈部活动诱发，无血压差与脉搏减弱，影像见颈椎间盘或骨赘压迫。"},{"name":"腕管综合征","point":"正中神经分布区（拇指、示指、中指）夜间麻木，Tinel 与 Phalen 试验阳性，无血管体征与血压差。"},{"name":"大动脉炎（takayasu）","point":"大动脉炎是多发性主动脉及分支炎症，可同时累及肾动脉与颈动脉；锁骨下动脉狭窄是其常见表现之一（需查全身血管与炎症指标）。"}],"tx":{"drug":[{"name":"抗血小板（阿司匹林 / 氯吡格雷）","dose":"阿司匹林 75–100 mg qd 或氯吡格雷 75 mg qd（介入或术后双抗 1–3 个月）","note":"动脉粥样硬化性病变的二级预防；出血高危者需权衡","renal":"CrCl <30 慎用阿司匹林","hepatic":"活动性肝病禁用","interact":"与抗凝合用增加出血；与 NSAIDs 合用降低心血管保护作用"},{"name":"他汀（阿托伐他汀/瑞舒伐他汀）","dose":"阿托伐他汀 20–40 mg qn 或瑞舒伐他汀 10–20 mg qn，目标 LDL-C <1.8 mmol/L","note":"所有动脉粥样硬化性外周动脉病患者均应使用","renal":"瑞舒伐他汀 CrCl <30 起始 5 mg","hepatic":"活动性肝病禁用","interact":"与 CYP3A4 抑制剂、贝特类合用增加肌病风险"},{"name":"糖皮质激素（大动脉炎活动期）","dose":"泼尼松 1 mg/kg/d（最大 60 mg/d），缓解后逐渐减量至 5–10 mg/d 维持，疗程 1–2 年","note":"**大动脉炎活动期的一线治疗**；需监测血糖、骨密度与感染；应在炎症控制后再行血运重建","renal":"无需调整","hepatic":"肝病者监测","interact":"与 NSAIDs 合用增加消化道溃疡"},{"name":"西洛他唑（间歇性跛行）","dose":"100 mg bid 口服（上肢缺血证据有限，下肢 ASO 有证据）","note":"改善跛行距离；心衰（LVEF <40%）禁用；可能致头痛与心悸","renal":"重度肾功能不全慎用","hepatic":"重度肝病禁用","interact":"与 CYP3A4 抑制剂合用升高浓度；与抗血小板药合用增加出血"},{"name":"肝素/低分子肝素（急性血栓栓塞）","dose":"依诺肝素 1 mg/kg q12h 皮下（CrCl <30 减为 1 mg/kg q24h）","note":"急性上肢动脉栓塞的术前抗凝；需评估溶栓或取栓","renal":"按 CrCl 调整","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**血运重建指征**：症状性重度狭窄（>70%）或闭塞、盗血综合征有症状、急性缺血","介入治疗：**经皮腔内血管成形 + 支架（PTA/PTAS）**为首选（锁骨下动脉的成功率 >90%）","开放手术：颈动脉-锁骨下动脉旁路、腋-腋旁路（介入失败或长段闭塞）","大动脉炎者**必须在炎症缓解期**手术或介入（活动期再狭窄率高）","急性栓塞：Fogarty 导管取栓或导管接触溶栓","戒烟与运动康复（上肢功能锻炼）"],"life":["**严格戒烟**（外周动脉病最重要的可干预因素）","控制血压、血糖、血脂，规律运动","避免患肢受压、寒冷与外伤","定期随访：术后 1、3、6、12 个月评估症状、血压差与影像（支架内再狭窄）","大动脉炎者需长期监测炎症指标与全身血管（每 6–12 个月影像）"]},"prog":"无症状的锁骨下动脉狭窄年卒中风险约 1%–2%（低于颈动脉狭窄）。介入治疗（PTA/PTAS）的 5 年通畅率约 70%–85%。大动脉炎所致者再狭窄率较高（约 20%–30%），需免疫抑制配合。急性栓塞者若在 6–12 小时内重建血流，预后良好；延误可致上肢坏死与截肢。","refs":["《外科学》第 9 版（人民卫生出版社）周围血管疾病章","2017 ESC Guidelines on the Diagnosis and Treatment of Peripheral Arterial Diseases","2016 AHA/ACC Guideline on the Management of Patients With Lower Extremity Peripheral Artery Disease（上肢部分参照）","2018 EULAR Recommendations for the Management of Large Vessel Vasculitis","《中国大动脉炎诊疗指南（2021）》"]},{"id":"vas_tos","name":"胸廓出口综合征","aka":["Thoracic Outlet Syndrome","TOS","胸出口综合征","颈肋综合征"],"rank":2,"basic":{"define":"锁骨下动脉、静脉或臂丛神经在胸廓出口（前斜角肌与中斜角肌之间、锁骨与第一肋之间）受压所引起的一组症状，按受累结构分神经型（最常见，约 90%）、静脉型与动脉型。","risk":["颈肋或第一肋异常（骨性压迫）","前斜角肌肥厚或痉挛","长期上肢过头作业（画家、举重、游泳、投掷）","创伤（锁骨或第一肋骨折、挥鞭伤）","姿势不良（圆肩、头前倾）与肥胖","女性（尤其 20–50 岁）多见"],"epi":"人群患病率约 1%–3%，神经型占 90% 以上。静脉型多见于年轻男性（运动或重复上肢活动后），动脉型最少见但可致栓塞与缺血。"},"patho":"胸廓出口由前斜角肌、中斜角肌与第一肋构成三角形的狭小间隙，臂丛下干与锁骨下动静脉从中通过。当存在骨性异常（颈肋）、肌肉肥厚或姿势不良时，神经血管束在特定体位（上肢外展、后伸、深呼吸）受压，产生神经性症状（压迫、缺血、脱髓鞘）或血管性症状（静脉血栓或动脉狭窄/栓塞）。神经型的病理基础为慢性机械性刺激与缺血。","dx":{"criteria":["**神经型（最常见）**：上肢尺侧（C8-T1 分布）麻木、刺痛、乏力与精细动作笨拙，症状在**上肢外展、上举或负重时加重**（夜间与长时间使用更明显）","**静脉型（Paget-Schroetter）**：突发上肢肿胀、发绀、疼痛，浅静脉扩张，多见于年轻男性剧烈运动后（「用力性血栓」）","**动脉型**：上肢发凉、乏力、Raynaud 现象、指端缺血或栓塞（可致指尖坏死）","**激发试验**：Adson 试验（头转向患侧并深吸气时脉搏消失）、Roos 试验（EAST，双臂外展 90° 并快速握拳 3 分钟诱发症状）、Wright 试验、肋锁压迫试验——**注意：激发试验在健康人群中也可阳性，需结合临床**","**影像**：颈椎与胸部 X 线（颈肋、第一肋异常）；CTA/MRA（血管型，见狭窄、血栓）；超声（静脉型见血栓）","**电生理**：肌电图/神经传导（神经型可无异常，但可排除颈椎病与腕管综合征）"],"workup":["详细病史（体位与活动相关性、职业、外伤）","体格检查：激发试验（Adson、Roos、Wright）、患肢脉搏与颜色、感觉与肌力（C8-T1 分布）","颈椎与胸部 X 线（颈肋、第一肋）","血管型：上肢静脉或动脉超声、CTA/MRA","神经型：肌电图与神经传导（排除颈椎病、腕管、肘管综合征）","必要时 MRI（评估臂丛与软组织）"],"grading":"按受累结构分神经型、静脉型、动脉型（可混合）；按病因分骨性（颈肋、第一肋异常）与软组织性（斜角肌肥厚、姿势）；按严重度分轻（间歇症状、保守有效）与重（持续症状、肌肉萎缩、血运障碍）。"},"ddx":[{"name":"锁骨下动脉狭窄（vas_subclavian）","point":"与锁骨下动脉狭窄的鉴别：后者为固定狭窄，双侧血压差持续存在、症状不依赖姿势；TOS 的症状由姿势诱发、休息后缓解。"},{"name":"急性肠系膜缺血（vas_ami）","point":"与肠系膜缺血的鉴别：后者为腹痛与乳酸升高，无上肢症状与姿势诱发。"},{"name":"血管畸形（vas_malformation）","point":"与血管畸形的鉴别：血管畸形为先天性包块，无 C8-T1 神经症状与姿势诱发。"},{"name":"颈椎病（神经根型 C8-T1）","point":"颈椎 MRI 见椎间盘突出或骨赘压迫，Spurling 试验阳性，症状与颈部活动相关；TOS 的诱发体位是上肢外展而非颈部后伸。"},{"name":"腕管综合征","point":"正中神经分布区（拇指至中指）夜间麻木，Phalen 试验阳性，与 TOS 的尺侧分布不同。"},{"name":"肘管综合征（尺神经）","point":"尺神经在肘部受压，Tinel 征在肘内侧，手内在肌萎缩；TOS 的尺神经症状无肘部压痛，且与上肢姿势相关。"},{"name":"上肢深静脉血栓（非 TOS）","point":"有中心静脉置管、肿瘤或凝血异常等诱因，超声见血栓但无胸廓出口压迫证据；Paget-Schroetter 特指用力性 TOS 相关血栓。"}],"tx":{"drug":[{"name":"抗凝（静脉型血栓）","dose":"利伐沙班 15 mg bid×21 天，之后 20 mg qd（至少 3 个月）；或低分子肝素桥接华法林（INR 2–3）","note":"静脉型 TOS 合并血栓需抗凝；若压迫持续存在，单纯抗凝复发率高，需考虑减压手术","renal":"利伐沙班 CrCl <30 慎用","hepatic":"重度肝病禁用","interact":"利伐沙班与强 CYP3A4/P-gp 抑制剂合用增加出血"},{"name":"抗血小板（动脉型/术后）","dose":"阿司匹林 75–100 mg qd；介入或术后双抗 1–3 个月","note":"动脉型或血管重建后的抗栓治疗","renal":"CrCl <30 慎用","hepatic":"活动性肝病禁用","interact":"与抗凝合用增加出血"},{"name":"非甾体抗炎药（神经型疼痛）","dose":"布洛芬 400–600 mg q6–8h 或塞来昔布 200 mg bid，短期使用","note":"缓解神经炎症性疼痛，非根本治疗；需与物理治疗同步","renal":"eGFR <30 避免","hepatic":"重度肝病禁用","interact":"与抗凝、抗血小板合用增加消化道出血"},{"name":"加巴喷丁 / 普瑞巴林（神经病理性疼痛）","dose":"加巴喷丁 300 mg qn 起始，滴定至 900–1800 mg/d 分 3 次；普瑞巴林 75 mg bid 起始","note":"用于神经型 TOS 的慢性疼痛；注意眩晕、嗜睡与肾功能调整","renal":"加巴喷丁按 CrCl 严格调整（CrCl 30–59 减量，<30 减半，<15 减为 qd）","hepatic":"无需调整","interact":"与阿片类、苯二氮卓类合用增加呼吸抑制"}],"nonDrug":["**保守治疗为首选（神经型约 70%–80% 可改善）**：姿势矫正（纠正圆肩、头前倾）、前斜角肌与胸小肌拉伸、肩胛骨稳定肌训练、避免上肢过头负重","物理治疗（斜角肌放松、神经滑动训练、呼吸训练）","**手术指征**：保守治疗 3–6 个月无效、肱三头肌或手内在肌萎缩、静脉型血栓反复、动脉型缺血","手术方式：**经腋路第一肋切除 + 前斜角肌切开**（神经型）、静脉型血栓可加导管接触溶栓后减压","静脉型血栓在发病 2 周内可考虑导管接触溶栓（恢复通畅率更高）","动脉型栓塞需取栓或溶栓并处理压迫"],"life":["**纠正姿势与工位（键盘高度、避免长时间抬臂）**","避免背包单肩负重与上肢过头运动","循序渐进的功能锻炼（避免急性期过度牵拉）","术后康复：早期被动活动，渐进负重（1–3 个月）","体重管理与戒烟（降低血栓与动脉风险）"]},"prog":"神经型经规范保守治疗后约 70%–80% 症状明显改善；手术减压的有效率约 80%–90%（需选择合适的患者）。静脉型血栓经溶栓 + 减压后 5 年通畅率 >80%；单纯抗凝者的复发与血栓后综合征风险较高。动脉型最少见但可致指端坏死，需积极处理。","refs":["《外科学》第 9 版（人民卫生出版社）胸廓出口综合征章","《血管外科学》（人民卫生出版社）胸出口综合征章节","2016 Society for Vascular Surgery Reporting Standards for Thoracic Outlet Syndrome","2019 AHA Scientific Statement: Diagnosis and Management of Thoracic Outlet Syndrome","2012 Adson / Roos Provocative Tests – Diagnostic Value (J Vasc Surg)"]},{"id":"vas_ami","name":"急性肠系膜缺血","aka":["Acute Mesenteric Ischemia","AMI","肠系膜上动脉栓塞","急性肠系膜血管闭塞"],"rank":3,"basic":{"define":"肠系膜血管（主要为肠系膜上动脉 SMA）急性闭塞或严重低灌注所致的肠管缺血坏死，是**病死率最高的腹部急症之一**（30%–80%），早期诊断困难且极易被误诊。","risk":["**心房颤动（SMA 栓塞的最常见原因）**","动脉粥样硬化与严重心血管病（SMA 血栓形成）","低血压/休克与低心排血量（非闭塞性肠缺血 NOMI）","高龄、透析、主动脉夹层累及内脏动脉","近期心梗、心衰、主动脉手术","静脉血栓倾向（肠系膜静脉血栓）"],"epi":"发病率约 0.1%–0.2% 的住院患者，在 70 岁以上急腹症患者中可达 1%。房颤患者中 SMA 栓塞占急性 AMI 的 40%–50%。总病死率约 30%–80%，与诊断延迟密切相关。"},"patho":"**SMA 栓塞**：血栓多来自房颤的左心耳，栓塞部位常在 SMA 中段（结肠中动脉发出后、回结肠动脉之前），导致广泛小肠与右半结肠缺血。**SMA 血栓形成**：多发生在原有粥样硬化斑块处（SMA 起始部），起病相对渐进，侧支（胃十二指肠动脉-胰十二指肠动脉弓）可部分代偿。**NOMI（非闭塞性）**：严重低血压与血管痉挛致广泛肠缺血，多无固定闭塞。肠管缺血 6 小时后出现黏膜坏死与透壁坏死（穿孔、腹膜炎），故**黄金窗口为症状出现后 6 小时内**。","dx":{"criteria":["**症状与体征不相称（最核心的临床特征）**：剧烈腹痛（多为脐周或弥漫、持续）但**腹部柔软、压痛轻、无腹膜刺激征**","早期：突发剧烈腹痛、恶心呕吐、腹泻（可有血便）、肠鸣音亢进；晚期：腹膜炎、肠鸣音消失、休克","**实验室**：白细胞升高、乳酸升高（>2 mmol/L 提示缺血，显著升高提示坏死）、D-二聚体升高、代谢性酸中毒；**早期乳酸可正常，故不可依赖**","**CTA（首选，敏感度与特异度均 >90%）**：见 SMA 起始部闭塞、肠壁不强化、肠壁积气、门静脉积气；**疑 AMI 应直接行 CTA，而非等待**","腹部 X 线：早期可正常或见肠管扩张（「黏膜皱襞增厚」），晚期见肠壁积气（pneumatosis）与门静脉积气（提示坏死，预后极差）","DSA：可确诊并可同时行血管内治疗（取栓/溶栓/支架）"],"workup":["**立即 CTA（腹部血管重建）**——疑诊即做，不等化验结果","乳酸、血气（代谢性酸中毒）、血常规、D-二聚体、淀粉酶/脂肪酶、肝肾功能","心电图与心超（寻找房颤与心源性栓子）","腹部超声（可正常，价值有限；可评估门静脉积气）","DSA（介入治疗前）","必要时剖腹探查（高度怀疑且有腹膜炎）"],"grading":"按病因分 SMA 栓塞、SMA 血栓形成、NOMI（非闭塞性）与肠系膜静脉血栓四型（治疗策略不同）。按肠管状态分可逆缺血、透壁坏死（需切除）与穿孔；按起病时间分急性（<1 周）与亚急性/慢性（慢性肠系膜缺血为餐后腹痛与体重下降）。"},"ddx":[{"name":"锁骨下动脉狭窄（vas_subclavian）","point":"与上肢动脉病变的鉴别：后者症状在患肢，无腹痛与乳酸升高；两者的共同背景是动脉粥样硬化/房颤。"},{"name":"胸廓出口综合征（vas_tos）","point":"与 TOS 的鉴别：TOS 为上肢姿势性症状，无腹部体征与乳酸升高。"},{"name":"血管畸形（vas_malformation）","point":"与血管畸形鉴别：血管畸形为先天性包块，无急性腹痛与休克。"},{"name":"急性胰腺炎（ap_acute）","point":"脂肪酶/淀粉酶显著升高（>3 倍上限），CT 见胰腺渗出与坏死；AMI 的酶学升高较轻而乳酸升高突出，CTA 是鉴别关键。"},{"name":"急性肠梗阻","point":"腹胀、呕吐与肠鸣音亢进/气过水声，影像见气液平面；AMI 早期可无梗阻征象，晚期可伴肠麻痹。"},{"name":"消化性溃疡穿孔","point":"突发刀割样腹痛、板状腹、膈下游离气体；AMI 的早期腹部柔软是核心区别。"},{"name":"急性心肌梗死（下壁）","point":"下壁心梗可表现为上腹痛与恶心，心电图与肌钙蛋白可确诊；AMI 也可由低心排诱发（NOMI）。"},{"name":"肠系膜静脉血栓","point":"起病更渐进、腹痛与腹胀为主，CTA 见静脉充盈缺损（而非动脉闭塞）；治疗以抗凝为主，手术指征为腹膜炎或肠坏死。"}],"tx":{"drug":[{"name":"普通肝素（立即抗凝）","dose":"首剂 80 U/kg 静脉推注，随后 18 U/kg/h 泵入，目标 APTT 1.5–2.5 倍（约 60–80 s）；或依诺肝素 1 mg/kg q12h","note":"**疑诊 AMI 应尽早抗凝**（无论最终是否手术）；活动性出血或大面积肠坏死为相对禁忌","renal":"依诺肝素 CrCl <30 减为 1 mg/kg q24h；普通肝素无需调整","hepatic":"重度肝病（凝血障碍）慎用","interact":"与抗血小板药合用增加出血"},{"name":"广谱抗生素（覆盖肠道菌群）","dose":"哌拉西林他唑巴坦 4.5 g q6h 静脉或头孢曲松 2 g q12h + 甲硝唑 500 mg q8h","note":"肠壁缺血使黏膜屏障破坏，菌群易位与脓毒症风险高；**所有 AMI 患者均应使用抗生素**","renal":"哌拉西林他唑巴坦按 CrCl 调整","hepatic":"无需调整","interact":"哌拉西林他唑巴坦与甲氨蝶呤合用增加毒性"},{"name":"镇痛（阿片类）","dose":"吗啡 3–5 mg 静脉缓慢推注，按需重复","note":"缓解剧痛与焦虑；注意呼吸抑制与低血压（尤其在低血容量时）","renal":"肾功能不全者活性代谢物蓄积，减量","hepatic":"肝病者减量","interact":"与镇静药合用增加呼吸抑制"},{"name":"血管扩张剂（NOMI，谨慎）","dose":"罂粟碱 30–60 mg/h 经导管肠系膜动脉持续泵入（介入途径）；或前列地尔静脉","note":"**NOMI 的核心治疗是纠正低心排与血管痉挛**（导管内罂粟碱），而非单纯扩张血管；需在介入条件下使用","renal":"无需调整","hepatic":"无需调整","interact":"与降压药合用加重低血压"},{"name":"溶栓（选择性导管接触溶栓）","dose":"阿替普酶 1–2 mg/h 经导管注入（SMA 小分支栓塞或术后残留），需介入监测","note":"用于远端小分支栓塞或术后残余血栓；**大面积主干闭塞首选取栓/手术**","renal":"无需调整","hepatic":"凝血障碍者禁用","interact":"与抗凝合用增加出血"},{"name":"血管活性药物（休克时）","dose":"去甲肾上腺素 0.05–0.3 µg/kg/min（维持 MAP ≥65 mmHg）；避免使用大剂量缩血管药（加重肠缺血）","note":"纠正休克是 NOMI 的关键，但需平衡全身灌注与肠缺血","renal":"无需调整","hepatic":"无需调整","interact":"与非选择性 MAO 抑制剂合用可致危象"}],"nonDrug":["**急诊血运重建**：SMA 栓塞/血栓的首选——**血管内取栓（机械取栓）或导管接触溶栓**（在有条件的中心，优先于开放手术）","**开放手术**：SMA 取栓/旁路（栓塞段切除 + 自体静脉旁路），并**评估肠管活力（切除坏死肠段）**","**Second-look 剖腹探查（24–48 小时后）**：评估肠管是否需进一步切除，是降低病死率的关键措施","NOMI：纠正低心排、液体复苏、避免大剂量血管加压药、导管内罂粟碱","肠系膜静脉血栓：抗凝为主，手术指征为腹膜炎或肠坏死","术后抗凝（房颤者长期抗凝；非心源性者 3–6 个月）"],"life":["**房颤患者规范抗凝**（预防 SMA 栓塞等体循环栓塞）","控制动脉粥样硬化危险因素（戒烟、他汀、降压、控糖）","**术后肠功能与营养管理**：短肠综合征者需肠内/肠外营养与长期随访","定期随访 CTA（1、3、12 个月）评估血管通畅与残余缺血","高危患者（房颤 + 突发腹痛）需教育：**腹痛不缓解立即急诊，不可等待**"]},"prog":"总病死率 30%–80%，是腹部急症中预后最差者之一。**预后与从症状到血运重建的时间直接相关**：6 小时内干预者存活率可达 70%–80%；超过 24 小时者病死率 >80%。肠管坏死的范围决定术后短肠综合征风险。Second-look 手术与多学科协作可显著改善结局。","refs":["《外科学》第 9 版（人民卫生出版社）肠系膜血管疾病章","2017 ESVS Clinical Practice Guidelines on the Management of the Diseases of Mesenteric Arteries and Veins","2020 World Society of Emergency Surgery (WSES) Guidelines on Acute Mesenteric Ischemia","2016 AHA/ACC Guideline on Peripheral Arterial Disease（肠系膜部分）","《中国急性肠系膜缺血诊治专家共识》（2021）"]},{"id":"vas_malformation","name":"血管瘤与血管畸形","aka":["Vascular Anomaly","Hemangioma","Vascular Malformation","ISSVA 分类"],"rank":4,"basic":{"define":"按 ISSVA（国际血管异常研究学会）分类，血管异常分为**血管肿瘤**（以婴幼儿血管瘤为代表，内皮细胞增殖）与**血管畸形**（结构异常而内皮细胞增殖率正常，出生即存在、不会自行消退）。两者在自然史与治疗上完全不同。","risk":["婴幼儿血管瘤：早产、低出生体重、女性、白种人","血管畸形：多为先天性（基因突变，如 TEK、PIK3CA、RASA1），部分为家族性","动静脉畸形可因外伤、青春期或妊娠而增大"],"epi":"婴幼儿血管瘤是最常见的婴幼儿良性肿瘤（发生率 4%–5%，早产儿可达 20%）。血管畸形总体患病率约 1%–1.5%，其中静脉畸形与毛细血管畸形（葡萄酒色斑）最常见。"},"patho":"**婴幼儿血管瘤**：出生后数周出现，经历增殖期（0–12 个月，快速增大）、稳定期与消退期（1–7 岁，多数完全消退），由 GLUT1 阳性的内皮细胞增殖形成。**血管畸形**：出生时即存在，按血流动力学分慢血流（毛细血管、静脉、淋巴管畸形）与快血流（动静脉畸形、动静脉瘘）。静脉畸形由扩张的静脉腔隙构成，可进行性增大与血栓形成；动静脉畸形存在高流量分流，可致心衰与出血。基因突变（如 PIK3CA 在静脉畸形、RASA1 在毛细血管畸形-动静脉畸形综合征）是近年重要发现。","dx":{"criteria":["**婴幼儿血管瘤**：出生后 1–4 周出现，女性多见，头颈部最常见；**生后 5 个月内快速增殖**，随后 1–7 岁逐渐消退（约 50%–60% 在 5 岁时完全消退）","**血管畸形**：出生时即存在，随身体等比例增大，**不会自行消退**","毛细血管畸形（葡萄酒色斑）：平坦的红色斑片，按分布（V1 三叉神经区需警惕 Sturge-Weber 综合征）","静脉畸形：柔软的蓝紫色包块，体位改变（低头）时增大，可触及静脉石（钙化）","动静脉畸形：搏动性包块、皮温升高、可闻及机器样杂音、震颤（高流量分流）","**影像**：超声（血流与结构）、MRI（首选，评估范围与肌肉/骨骼受累）、CTA/DSA（动静脉畸形）","**需警惕综合征**：PHACE（血管瘤 + 后颅窝异常 + 动脉异常 + 心脏 + 眼）、Sturge-Weber、Klippel-Trenaunay、Parkes Weber"],"workup":["详细病史（出现时间、生长模式——这是鉴别血管瘤与畸形的关键）","体格检查（大小、颜色、质地、搏动、温度、杂音、并发症如溃疡/出血）","**MRI（首选影像）**：评估范围与深层受累","超声（血流速度与分流评估）","动静脉畸形：CTA/DSA（术前必须）","综合征筛查：心脏超声（PHACE）、眼科与神经影像（Sturge-Weber）","必要时活检或基因检测（疑难病例）"],"grading":"按 ISSVA 分：血管肿瘤（良性/局部侵袭性/恶性）与血管畸形（单纯型：毛细血管/淋巴管/静脉/动静脉；混合型；知名综合征）。血管瘤按风险分低风险（小、非面部）、中风险与高风险（面部、气道、肝巨大血管瘤、溃疡、PHACE 综合征）。"},"ddx":[{"name":"锁骨下动脉狭窄（vas_subclavian）","point":"与动脉狭窄鉴别：后者为获得性狭窄伴血压差，无先天性包块；血管畸形的动脉型可有搏动与杂音但无血压差。"},{"name":"胸廓出口综合征（vas_tos）","point":"与 TOS 鉴别：TOS 为上肢姿势性症状，无包块与皮温升高。"},{"name":"急性肠系膜缺血（vas_ami）","point":"与肠系膜缺血鉴别：后者为急腹症与乳酸升高，与皮肤包块无关。"},{"name":"婴幼儿血管瘤 vs 血管畸形（关键鉴别）","point":"两者核心区别：血管瘤出生后出现、快速增殖后消退、GLUT1 阳性；血管畸形出生即存在、不消退、随身体生长。"},{"name":"淋巴管畸形","point":"半透明囊性包块（大囊型/微囊型），穿刺见淡黄色淋巴液，MRI 见多房囊性结构；与静脉畸形（蓝色、可压缩、有静脉石）不同。"},{"name":"软组织肿瘤（脂肪瘤、纤维瘤等）","point":"非血管性包块，无体位性改变与搏动，MRI 见脂肪或纤维信号。"},{"name":"静脉血栓（浅静脉）","point":"局限性条索状硬结与疼痛，超声见血栓，非先天性包块。"}],"tx":{"drug":[{"name":"普萘洛尔（婴幼儿血管瘤一线）","dose":"口服：2 mg/kg/d 分 2 次（起始 1 mg/kg/d，1 周后加量），疗程 6–12 个月；**高风险者（面部、气道、肝巨大）可在生后 1 个月内启动**","note":"**普萘洛尔是婴幼儿血管瘤的一线治疗**（约 90% 有效）；治疗前需评估心率与血糖，监测心动过缓、低血糖（尤其喂养不足时）与睡眠障碍","renal":"无需调整","hepatic":"肝病者慎用","interact":"与糖皮质激素合用可致低血糖；与维拉帕米合用增加心脏抑制"},{"name":"局部噻吗洛尔（浅表小血管瘤）","dose":"0.5% 噻吗洛尔滴眼液局部外涂，每日 2–3 次","note":"适用于浅表、小的血管瘤（面颈部）；全身吸收少，安全性好","renal":"无需调整","hepatic":"无需调整","interact":"与 β 阻滞剂口服药合用可能叠加"},{"name":"西罗莫司（复杂血管畸形，mTOR 抑制剂）","dose":"0.8 mg/m² bid 口服（按血药浓度调整，目标谷浓度 5–15 ng/mL）","note":"用于复杂静脉畸形、淋巴管畸形与卡波西样血管内皮瘤（KHE）；需监测血药浓度、血脂、血象与感染","renal":"无需调整","hepatic":"肝功能不全需减量并监测浓度","interact":"CYP3A4 抑制剂（酮康唑、克拉霉素）显著升高浓度；与活疫苗禁用"},{"name":"糖皮质激素（血管瘤，二线）","dose":"泼尼松 2–3 mg/kg/d 口服（短期），用于普萘洛尔禁忌或无效者","note":"起效需数周，长期使用影响生长与免疫；现已多被普萘洛尔取代","renal":"无需调整","hepatic":"监测","interact":"与 NSAIDs 合用增加消化道溃疡；与利福平合用降低浓度"},{"name":"硬化剂（静脉畸形）","dose":"聚多卡醇（0.5%–3%）或无水乙醇，经皮注射（每次按病灶大小，需专科操作）","note":"**静脉畸形的一线治疗**（硬化治疗）；需在影像引导下进行，警惕皮肤坏死与深静脉血栓","renal":"无需调整","hepatic":"无需调整","interact":"无特殊"},{"name":"抗凝（静脉畸形合并血栓）","dose":"低分子肝素或利伐沙班（按体重与肾功能），疗程 3–6 个月","note":"静脉畸形内血栓形成（局部疼痛性硬结）时使用","renal":"按 CrCl 调整","hepatic":"重度肝病慎用","interact":"与抗血小板药合用增加出血"}],"nonDrug":["**婴幼儿血管瘤：观察随访**（低风险者多数自行消退）；高风险者尽早（生后 1 个月内）启动普萘洛尔","**脉冲染料激光（PDL）**：葡萄酒色斑与浅表血管瘤残留红斑（595 nm，需多次治疗）","**手术切除**：血管畸形（尤其局限型）、血管瘤消退后的多余皮肤与纤维脂肪残留","**介入栓塞（动静脉畸形）**：术前栓塞或姑息治疗（需与手术联合，单纯栓塞易复发）","**硬化治疗（静脉畸形、淋巴管畸形）**：影像引导下注射","溃疡处理（血管瘤溃疡）：局部护理、镇痛、必要时系统治疗"],"life":["**定期随访评估生长与并发症**（血管瘤在增殖期需每 4–8 周复诊）","面部血管瘤需评估视力（眼睑遮挡可致形觉剥夺性弱视）与气道（声门下血管瘤致喘鸣）","V1 区葡萄酒色斑需筛查 Sturge-Weber 综合征（青光眼与癫痫）","动静脉畸形避免外伤与部分栓塞（可诱发出血）","心理支持（外观影响、儿童社交）与患者教育（血管瘤会消退、畸形不会）"]},"prog":"婴幼儿血管瘤多数（约 90%）在 4 岁时显著消退，约 50% 遗留皮肤松弛、毛细血管扩张或纤维脂肪残留。高风险血管瘤（面部、气道、肝巨大）未经治疗可致毁容、气道梗阻、心衰（肝血管瘤分流）。血管畸形不会消退且可进行性增大，需长期管理；动静脉畸形治疗难度大、复发率约 30%–50%。","refs":["《外科学》第 9 版（人民卫生出版社）血管瘤与血管畸形章","2018 ISSVA Classification of Vascular Anomalies（国际血管异常研究学会）","2019 Clinical Practice Guideline for Infantile Hemangioma (Pediatrics, AAP)","2020 European Reference Network (ERN) Guidelines for Vascular Anomalies","《中国婴幼儿血管瘤与脉管畸形诊疗指南（2019）》"]}]},{"id":"lymphatic","name":"淋巴系统疾病","rank":6,"summary":"淋巴水肿以肢体对称性、凹陷性、抬高后减轻为特征，不能以静脉疾病或心肾疾病完全解释；按国际淋巴学会分期 0–Ⅲ 期与病因（原发性/继发性）分型，治疗以综合消肿治疗（CDT）为核心，规范压力治疗与皮肤护理决定长期疗效，药物仅为辅助。","compare":[{"diseaseId":"vas_lymphedema","dx":"单侧或双侧肢体肿胀，起自足趾或足背（方趾征），皮肤增厚、非凹陷性、抬高与休息后减轻；淋巴显像或吲哚菁绿淋巴造影确诊，静脉超声正常","key":"方趾征 + Stemmer 征（不能捏起足背皮肤）+ 静脉超声正常；抬高后减轻但不如静脉性水肿明显"}],"diseases":[{"id":"vas_lymphedema","name":"淋巴水肿","aka":["Lymphedema","原发性淋巴水肿","继发性淋巴水肿","Milroy 病","淋巴回流障碍"],"rank":1,"basic":{"define":"因淋巴生成过多或淋巴回流障碍致富含蛋白的组织间液在软组织积聚的慢性疾病，多见于下肢，表现为肢体肿胀、皮肤与皮下组织纤维化，晚期可形成象皮肿。按病因分原发性（淋巴管发育异常）与继发性（手术、放疗、感染、外伤）。","risk":["妇科肿瘤、前列腺癌、乳腺癌根治术或腹股沟/腋窝淋巴结清扫后","盆腔或腹股沟放疗（继发性淋巴水肿最常见原因）","丝虫感染（热带地区最常见的感染性病因，我国已基本消除）","丹毒与蜂窝织炎反复发作","肥胖（BMI ≥30 为重要危险因素）、静脉功能不全合并","遗传性（Milroy 病，VEGFR3 突变；Meige 病）与先天性（Turner 综合征）"],"epi":"我国继发性淋巴水肿以肿瘤术后及放疗后为主，乳腺癌术后上肢淋巴水肿发生率约 15%–30%，妇科肿瘤术后下肢淋巴水肿约 10%–40%。原发性淋巴水肿较少见，女性多于男性，多在青春期后起病（早发型），另有余多 >35 岁起病的晚发型。"},"patho":"淋巴液由毛细血管滤出后经初始淋巴管摄取，经前集合淋巴管、集合淋巴管与淋巴结回流入静脉系统。淋巴管发育不全、功能障碍或淋巴结清除过多导致组织间液蛋白质潴留，渗透压升高进一步吸引水分；巨噬细胞活跃后成纤维细胞增生，皮下脂肪与纤维组织堆积，形成不可凹性肿胀。长期蛋白潴留易继发细菌感染（丹毒）与淋巴管炎，感染又加重淋巴管损伤，形成恶性循环。抬高与压力治疗可改善回流，而运动与肌肉泵有助于动员淋巴液。","dx":{"criteria":["肢体或足背肿胀，起自足趾（方趾征，方脚趾征阳性），而非踝部逐渐向上","Stemmer 征阳性：不能捏起第二足趾背侧皮肤","水肿初期凹陷，随病程转为非凹陷性，皮肤增厚、结节与角化（象皮肿）","抬高位（夜间）肿胀可减轻，但不如静脉性水肿明显","排除静脉、心、肝、肾与药物性水肿","影像：淋巴显像（TC-99m 淋巴显像）或吲哚菁绿（ICG）淋巴造影见淋巴管稀少、迂曲、回流延迟或示踪剂外渗；静脉多普勒与静脉压正常"],"workup":["病史：肿瘤手术与放疗史、感染史、家族史、起病年龄与进展速度","体格检查：周径测量（同一解剖标志）、方趾征、Stemmer 征、皮肤与溃疡、色素沉着","静脉彩色多普勒排除深静脉血栓与静脉瓣功能不全","心脏超声、肝功能、肾功能、尿蛋白与甲状腺功能（排除系统性疾病水肿）","淋巴显像或 ICG 淋巴造影（明确诊断与分型）","必要时 MRI 或 CT 评估脂肪与纤维化程度","肿瘤患者评估复发与转移"],"grading":"国际淋巴学会（ISL）分期：0 期（潜伏期）无可见肿胀但淋巴运输异常；Ⅰ 期 肢体肿胀，抬高后部分减轻，按压凹陷；Ⅱ 期 抬高后不减轻，皮肤纤维化，非凹陷性；Ⅲ 期 象皮肿，皮肤改变（疣状增生、角化过度与大量皱褶）。按病因分原发性与继发性；按淋巴影像分淋巴管发育不良型、增生型、梗阻型。"},"ddx":[{"name":"血栓后综合征与慢性静脉功能不全（vs_dvt_chronic）","point":"与本科室周围动脉与静脉大类（vascular_1）中血栓后综合征的鉴别点：血栓后综合征有 DVT 病史、静脉超声异常、含铁血黄素沉着与静脉性溃疡、水肿以踝部为主；淋巴水肿为方趾征与 Stemmer 征阳性、静脉超声正常。"},{"name":"深静脉血栓形成","point":"有 DVT 病史：单侧突发肿胀伴疼痛、静脉超声见血栓；淋巴水肿起病缓慢、无 D-二聚体升高。"},{"name":"心衰、低蛋白血症与肾性水肿","point":"双侧对称、伴心悸气促、血清白蛋白降低或尿蛋白阳性；淋巴水肿常单侧且蛋白正常。"},{"name":"静脉畸形与血管畸形（vas_malformation）","point":"与 vascular_3 中血管畸形的鉴别点：静脉畸形为先天性软性肿块、多普勒见静脉湖，可伴血栓；淋巴水肿为弥漫性肢体肿胀无局限性肿块。"},{"name":"脂肪水肿（Lipedema）","point":"几乎仅见于女性，双下肢至踝对称性脂肪堆积、下肢压痛、皮肤不累及足背（脚踝袖口征阴性），加压治疗无效；常合并静脉功能不全。"}],"tx":{"drug":[{"name":"地奥司明（微粒化黄酮类）","dose":"500 mg bid，可增至 500 mg 每日 2 次以上；遵说明书","note":"作为淋巴水肿的辅助用药减轻肿胀与沉重感，不能替代压力与手法治疗。","renal":"重度肾功能不全慎用","hepatic":"严重肝功能不全慎用","interact":"与抗凝药合用需监测出血"},{"name":"青霉素或头孢类（丹毒与蜂窝织炎）","dose":"按感染程度与说明书剂量，疗程通常 10–14 天；遵说明书","note":"淋巴水肿肢体感染进展快，需早期足量抗菌；反复感染者可评估长期小剂量预防性青霉素。","renal":"肾功能不全减量","hepatic":"遵说明书","interact":"与其他肾毒性药物合用注意肾功能"},{"name":"利尿剂（慎用）","dose":"遵说明书，仅在合并心衰、肾性水肿时使用","note":"单纯淋巴水肿不推荐常规利尿，可致血容量不足与电解质紊乱加重组织纤维化。","renal":"肾功能不全时需监测电解质","hepatic":"遵说明书","interact":"与 ACEI/ARB 合用可引起低血压与高钾"}],"nonDrug":["综合消肿治疗（CDT）为一线：皮肤护理、手法淋巴引流（MLD）、压力治疗与运动治疗四部分组成","压力治疗：Ⅱ 期以上用多层低延展弹力绷带（强化期），维持期改为定制型压力袜或压力袖（20–30 mmHg 起，依分期与耐受调整，下肢常用 40–50 mmHg）","维持期每日白天佩戴压力袜，每日穿戴至睡前；每年更换","皮肤护理：每日清洁保湿、防止外伤与蚊虫叮咬，感染时立即治疗","肥胖者减重；可辅助间歇性充气加压治疗（IPC）","手术：晚期象皮肿可行淋巴管–静脉吻合（LVA）、抽脂术或病变组织切除","避免患肢抽血、输液与测量血压过久，减少感染诱因"],"life":["长期规律佩戴压力袜并进行运动（步行、游泳、抗阻训练），以肌肉泵促进回流","手臂与下肢避免长时间下垂，休息时抬高患肢高于心脏水平","定期测量肢体周径并记录，评估水肿分级与治疗依从性","肿瘤患者需同时随访原发病与复发；出现皮肤破溃、红热痛时立即就诊排除丹毒"]},"prog":"淋巴水肿为慢性进行性疾病，无法根治；规范 CDT 可使 70%–90% 患者水肿减轻与症状改善，但需终身维持压力治疗。早期治疗可延缓纤维化与象皮肿；反复丹毒可致急性加重，淋巴管–静脉吻合术后部分患者肢体周径可减少，长期效果依赖依从性。","refs":["中华医学会整形外科学分会/淋巴学组《肢体淋巴水肿诊疗专家共识（2020）》","《外科学》第 9 版 淋巴水肿","International Society of Lymphology (ISL) Consensus Document on Lymphedema 2020/2023","中国抗癌协会乳腺癌专业委员会《乳腺癌术后上肢淋巴水肿诊治专家共识（2021）》"]}]}]}};